INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c77b666f-c9bb-47a6-9ff8-b4d8f27875bd', '4d837b35-b887-46dd-9a34-0f1f322199bf', 3, '100145703', '恋愛小説家', '「性欲は善」と放言する星山純一はベストセラーを連発する恋愛小説家。しかしその陰で執筆中に「似た作品を前に書いた」と疑心にかられると嘔吐してしまう症状に苦しんでいた。伊良部はむかつきの原因究明と除去で治ると言うが、純一は作家特有のストレスと考え取り合わない。そんなある日純一は友人の義雄から自分の小説がパターン芸だと言われる。一方、伊良部は作家転身を宣言し、編集者を紹介しろとしつこく純一に迫る。', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b160674-d5ef-4ce2-8415-83088f153b97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6ab92ce-0ed3-403a-ba58-3ed0bbd41f8a', '4d837b35-b887-46dd-9a34-0f1f322199bf', 4, '100145704', 'ホットコーナー', 'ヤクルトスワローズの三塁手、坂東真一は連続暴投によりルーキー鈴木との交代を命ぜられる。病院に来た真一に伊良部は暴投が「イップス」の症状だと告げる。症状確認と称して真一とのキャッチボールを強要する伊良部によって「投げる」という行為を再確認した真一。しかし翌日の練習ではキャッチボールすらできなくなる始末。伊良部の不可解な診療で症状を悪化させた真一と対称に、鈴木へのマスコミとファンからの期待が高まっていく…。', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf90c747-d8cd-4e84-ac77-eaf62c3b9888.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0cfa52c3-f689-4bf5-93bf-02d6d9cca386', '4d837b35-b887-46dd-9a34-0f1f322199bf', 5, '100145705', '義父のアレ', '池山達郎は大学病院で勤務する精神科医。医学部長である野村の娘と結婚し、周囲の羨む生活を送っている…はずだったが、野村家での生活に馴染めずにいた。次第に発症する心の病の症状を抑えようと必死になっていた達郎は大学の同窓会で伊良部と再会する。旧友の異変に気づく伊良部だが、達郎はなかなか伊良部に症状を打ち明けようとしない。精神科医の心のトラブルに伊良部はどうする? そして、達郎を追いつめる義父の「アレ」とは一体?', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6b0a05d-6b03-4062-8442-91797aacd5e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78c4d229-a4b4-405e-b9a3-6797404dbe73', '4d837b35-b887-46dd-9a34-0f1f322199bf', 6, '100145706', 'フレンズ', '津田雄太は常に携帯電話で最新の音楽やドラマの情報収集をし、仲間と入ったレストランでは店員、ユリのメールアドレスを聞き出したり、と人気者になる事に懸命な高校生。携帯電話が手から離れると痙攣してしまう依存症状の治療で来た病院で会った伊良部には無関心だが、ナースのマユミ目当てで通院する事に。1週間後のクリスマスまでにユリと親しくなろうと雄太は授業中にメールを送るが、教師に見つかり携帯電話を没収されてしまう。', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e69b5649-3513-45f4-8149-29c44ae6f463.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa479f97-9b09-4d4d-895a-f76b47262084', '4d837b35-b887-46dd-9a34-0f1f322199bf', 7, '100145707', 'ハリネズミ', '猪野誠司は「般若の誠司」の異名で恐れられるヤクザ。しかし実は尖端恐怖症で、ボールペンの先、フォーク、テーブルの角、サンマ、どれも叫び声をあげる程怖い。伊良部はマユミと二人で恐怖に叫ぶ誠司を羽交い絞めにして嬉々として注射を打ち、憔悴した誠司に逆療法が有効と言い放つ。一方、誠司の内縁の妻が出店しようとする飲食店が敵対する吉安一家の支配地域にあり、吉安一家の刃物使いの名手、ヤッパのヤスが誠司の前に現れ脅そうとする。', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d60f1d8f-8462-4fa3-9ead-cffbf70c107b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee2afb4c-29d5-4cb6-b407-58ac8cf01c64', '4d837b35-b887-46dd-9a34-0f1f322199bf', 8, '100145708', 'いてもたっても', 'ルポライター、岩村義雄は強迫神経症のせいで、家の火の消し忘れが気になって仕方がない。記事の取材中にストーブのスイッチを切ったかが気になって家に帰ったり、煙草の火の始末を確認しに帰ったり、で仕事にならない日々。ついには出版社からクビを言い渡されてしまう。義雄は精神医学書を買い漁って研究し、伊良部病院に来てカウンセリングを希望するが、伊良部は「聞いても無駄」と取り合わない。果たして義雄は社会復帰できるのか?', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/994024c7-bd2f-4c8c-a249-f1825331993f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45195eb4-eb37-4cdf-8964-a81cea51ea88', '4d837b35-b887-46dd-9a34-0f1f322199bf', 9, '100145709', '天才子役', '「ヒロちゃんスマイル」で一世を風靡した天才子役、安川ヒロミは28歳となった今も子役時代のイメージを守り続けようとしていた。テレビ撮影中はどんなシーンでもスマイル! で、それが仇となって仕事を失う羽目になっても笑みを絶やさない。ヒロミのマネージャー、厚子はその空気を読まない病的な笑顔に耐えかね、無理やりヒロミを伊良部のもとに連れて行くが、伊良部はヒロミの事そっちのけで厚子の事を口説こうとする。', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe839acb-c384-449c-b598-8c7b99324e61.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0aa6f881-babb-4ac5-b1d8-d46f59d2723c', '4d837b35-b887-46dd-9a34-0f1f322199bf', 10, '100145710', 'オーナー', '歯に衣着せぬ発言で有名な新聞社会長兼プロ野球球団オーナー、ナベマンこと田辺満雄。彼は光と闇に反応して発作を起こすパニック障害を患っていた。伊良部は満雄に「闇は棺桶の象徴、光は天国の象徴」で、死への恐怖が原因と言う。光を避けたい満雄に記者達は政界と、スワローズの三塁手坂東の悪送球に関するコメントを聞き出そうとフラッシュを浴びせていく…。誰しも逃れられない「死」の恐怖に直面する満雄への伊良部の行動とは?', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4f1f845-0a27-410f-96f8-eb510a63a24f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2fb0772-1f7b-4c6d-9e4f-93328c764a1e', '4d837b35-b887-46dd-9a34-0f1f322199bf', 11, '100145711', 'カナリア', '【最終話】救急救命科の医師、津田英雄は患者を救う事にやり甲斐と充実感を感じる日々を送っていた。しかし、高校生の息子、雄太が携帯電話を手放すと痙攣するケータイ依存症を発症、妻の久子からの頼みで、渋々と院内で変わり者として有名な伊良部に治療を頼む。雄太に携帯を止めろと言っても聞かず困っている、と言う英雄に伊良部は突然注射を打たせろと迫る。強引に注射を打った後も何の変化もしない「正常」な英雄に伊良部は意外な事を語り始める…。', '2023/06/14 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7af3b5c8-ff94-4ae8-9823-a7933fdc34ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3685d7f4-f0ab-43df-aa3e-001c7d0e6267', '空挺ドラゴンズ', '', 'hulu', 'drifting-dragons', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd4184d3-dbef-46bc-b89b-ae34a02edcce.jpg?w=331&h=447&p=t', 'hulu', 2020, 0, 1, 'FINISHED', NULL, 108450, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8659feb8-3883-4825-bbbe-3ec959f238fe', '3685d7f4-f0ab-43df-aa3e-001c7d0e6267', 'hulu-drifting-dragons-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8edb9233-3a99-46ea-af2c-8aeea0716726.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fbb404c3-5b5f-4730-88cb-2d7bdd7cdc31', '8659feb8-3883-4825-bbbe-3ec959f238fe', 1, '100220862', 'クィン･ザザ号', '捕らえた龍を解体し、それを売って、旅をする……今はその数も少なくなった、現役の捕龍船クィン･ザザ号。新人のタキタは、ミカ達ベテラン船員の鮮やかな龍捕り【おろちと (り)】を目の当たりにし息を飲む。その後、一行は早速近くの市【まち】に降りて龍の肉や油を人々に売り捌く。久々の地上で、船員たちはほっと一息。だがそれも束の間、新たな龍が現れ、隣市【となりまち】が危険との情報が! やがて遭遇した龍は、クィン･ザザ号に対してやけに好戦的な態度を示す。その理由とは……?', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8edb9233-3a99-46ea-af2c-8aeea0716726.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93bfc822-a816-412e-b3f1-719215aa860c', '8659feb8-3883-4825-bbbe-3ec959f238fe', 2, '100220863', '賞金と極小龍の悪魔風', 'クィン･ザザ号に乗り込んでから3ヶ月経ち、新人のタキタも少しずつ仕事に慣れてきた。そんな彼女が甲板でひとり風に当たっていると、手すりに奇妙な鳥が。……いや、違う。龍だ! 鳥のような小ささでも龍は龍。捕まえればかなりの儲けに違いない!! タキタは甲板から船内へと紛れ込んだ龍を密かに捕獲しようと奮闘する。しかし、なかなか見つけられずにいるうち、ギブスが何者かに襲われ負傷。事態は船全体を巻き込んだ、大騒動へと発展する。', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9c425ce-8764-4cb6-b4b2-02503336542b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3270e953-e2a3-4259-9352-a31c80d280a6', '8659feb8-3883-4825-bbbe-3ec959f238fe', 3, '100220864', '光る龍と', '捕龍船といえども、龍と戦ってばかりではない。空の上にも平時の職務はある。見張り台の当番をしていたジローは、天測で雲行きが怪しいことに気がついた。そんなこととは知らず、非番の者は賭けに興じたり、二日酔いでへばったり、古くなった龍の肉を燻製にしたりと、自由きままに過ごしていた。しかし、船の責任者と会計士は頭を抱えていた。このまま龍が捕れなければ大赤字!! しかもジローの見立て通り、船の前方には嵐を伴う巨大な雲が迫りくるのだった!!', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb5b9f21-486c-496b-a8ce-bf5aaf55c89a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e073c6f5-89f0-490c-af99-33ad62ea578b', '8659feb8-3883-4825-bbbe-3ec959f238fe', 4, '100220865', '乗船理由と龍のテリーヌ', 'タキタが偶然見つけた一枚の紙。そこには眠るヴァナベルの艷やかな姿が! こんな絵を描くために女の寝室に忍び込むとは……けしからん! 状況証拠で絞り込まれた容疑者候補は3人。船員たちは面白半分で犯人を絞り込もうとするが、ヴァナベル本人はといえば、馬鹿げた騒動を気にすることもなく、物思いに耽っていた。そこに現れた中型の龍。戦いの最中、ミカの姿にヴァナベルが感じたものは――。', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca5c4949-f60e-4ce0-b95d-56305ae460e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d14505a-6213-4239-86c0-5abd3f08d6f4', '8659feb8-3883-4825-bbbe-3ec959f238fe', 5, '100220866', '空中海賊とパストラマ', '大きな市【まち】での久々の補給を目前に、浮かれた調子のクィン･ザザ号の船員たち。ここのところ龍をほとんど捕獲できておらず、航行中のほぼ唯一の楽しみである食事もすっかり貧しい内容で、体も心も疲れきっていた。稼ぎの少なさは気になるところだが、それでもどこかにとどまっての休みは喜ばしい。しかし、海上で貨物船の救難信号を見つけたことから、事態は急転直下。ザザ号は貨物船を救出しようとするが、そこに一隻の飛行船が現れる。その正体は――空中海賊だった!', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7787bcd7-d766-46cd-9f06-4b43f8c0686c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('265d8daa-3e4e-4382-81d0-1b2dc517bbc4', '8659feb8-3883-4825-bbbe-3ec959f238fe', 6, '100220867', '祭りと龍肉の手延べ汁麺', '港市【みなとまち】クオーンに、クィン･ザザ号は補給と船の修理のために降り立った。一仕事終えた船員たちの多くは、久々の陸【おか】を堪能しようと酒場へ繰り出す。そんな中、ミカは初めて龍の解体を経験したことで心ここにあらずなタキタ気遣い、一緒に市【まち】に向かう。そして、「千剖士」【せんぼうし】という龍を解体･加工して暮らす一族を訪ねる。そのころ酒場では、ザザ号と他の船の龍捕りのあいだで乱闘が勃発。ジローはその騒ぎから、カーチャという名の可憐な少女と出会う。', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1912bb36-ebd5-4c1a-8f80-a32fff33c032.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd8bde00-17dd-446d-8893-cf0454a2d585', '8659feb8-3883-4825-bbbe-3ec959f238fe', 7, '100220868', '大災と食える龍', 'クオーンの平和は、一瞬にして破られた。組合の飛行船が曳航してきた、大型の龍。毒によって仕留められていたはずのそれが突如息を吹き返し、市中【まちなか】で猛威を振るい出した。放たれる激しい熱閃で、至るところに火の手が上がり、傷の苦痛にのたうつ巨体で、瓦礫の山が築かれる。寄港していた船は次々と逃げ出すが、市【まち】の住人たちに逃げ場はない。クィン･ザザ号も決断を迫られる中、ジローは市の人々を守ることを主張する。その熱意とミカの食欲が、龍捕りたちの気持ちを動かす。だが、大型龍の力は並大抵ではなかった。', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f5b626a-f002-494e-b362-a73e2ccd65c8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e55e4966-dd93-49c8-94a7-20cfc76f8545', '8659feb8-3883-4825-bbbe-3ec959f238fe', 8, '100220869', '暴れ龍捕獲作戦', '空中と地上からの攻撃を組み合わせた捕獲作戦が思うように進行せず、未だ燃え続ける市【まち】。大型龍によって破壊された、カーチャのいた娼館の残骸を前に、衝撃を隠せないジロー。そうして立ち竦むあいだにも、手負いの大型龍は被害をさらに拡大させていく。このままでは、製油工場にまで火の手が及ぶのは時間の問題。だがそんな状況を前にして、ジローは何かに突き動かされるように、大型龍に挑みかかる。', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/04b41e23-7d77-4628-bcc4-0a4a97d803f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b3a1271-059c-498a-9ae9-b15d6f59b5a6', '8659feb8-3883-4825-bbbe-3ec959f238fe', 9, '100220870', '炊き出しの釜煮と龍のカツレツ', '大型龍の解体が始まった。その近くで、クオーンの人々は総出で炊き出しを行うことに。予定されていた祭りが中止になり、そのために揃えていた食材がふんだんに使えるとあって、料理上手な人々の腕が鳴る。クオーンの郷土料理である「釜煮」は、それぞれの家庭にこだわりの味があることもあって、ちょっとした料理対決のような雰囲気に。だが、そんな楽しい時間が、いつまでも続くわけではない。元の日常に帰る朝、クィン･ザザ号が、ふたたび空へと上がるときがやってきた。そのとき、ジローは……。', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e92ef08a-17b2-419b-9a2d-e34d9718addf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b0d95a4-f87f-45d7-be93-7a15d1d3d132', '8659feb8-3883-4825-bbbe-3ec959f238fe', 10, '100220871', '渡り龍と谷の底', 'クオーンを出たクィン･ザザ号の次なる目的は、「龍の回廊」という特別な場所。辿り着くためには、山岳地帯の崖のあいだを飛び、強い上昇気流に乗り、厚い雲の上に抜けなければならない。危険な飛行を無事乗り切り、狙いどおり、回遊してきた「渡り」の龍の群れと遭遇できたクィン･ザザ号。しかし、捕龍の最中、タキタが獲物とともに、船の甲板から谷底へと落下してしまい…!?', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/476f73d4-e4c8-4310-a520-e9817c2d89e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5ffcf4a-44b2-4eca-b8ca-e2895e5180ab', '8659feb8-3883-4825-bbbe-3ec959f238fe', 11, '100220872', '小さい龍と龍脳の猟師鍋', '船から落下したタキタの無事を信じ、捜索を続けるクィン･ザザ号の仲間たち。当のタキタは、アスケラと名乗るマタギの少女に助けられ、拾った子龍を連れてキャンプで保護されていた。命の危機こそ去ったものの、万全ではない体調。船に戻るための方法も、まったく考えが及ばない。だが、タキタはそうした自身の抱える問題以上に、食事をせず、日々衰弱していく子龍の様子を気にかけていた。', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/997c7517-b713-4d23-ac11-46af1db17e10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7186c4a2-5b54-4b28-894d-2a1d4f25f701', '8659feb8-3883-4825-bbbe-3ec959f238fe', 12, '100220873', '龍の回廊', '【最終話】火山の噴火に誘われて、大量の「渡り」の龍の群れが周囲に現れる。さまざまな種類の龍が入り乱れ、中には別種の龍を喰らう龍までいる。そんな壮絶な光景を前に、ミカやヴァナベルら、クィン･ザザ号のすべての船員が、それぞれの役割を果たしながら、全身全霊で龍捕りとしての生き様を示していく。それを目の当たりにしたタキタもまた、背中に子龍を背負いながら、龍捕りとして為すべきことをやり遂げようと、決意を固める。', '2025/04/07 00:00:00', 1384, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96beeea9-711e-4678-affa-bc45a0e41c04.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
