INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', '1bd00d5e-825d-419e-87f2-a406d1630873', 'hulu-the-100-girlfriends-who-really-really-really-really-really-love-you-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fec78752-5b8a-4a5b-a3d0-5bd07383c8ef.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85e3dfba-a400-49af-b84d-f4407890f24c', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 1, '100161961', '君のことが大大大大大好きな2人の彼女 (あと98人)', '恋の神様から「高校で出会う運命の人は100人いる」と告げられた恋太郎。そんな中、入学式から早々に二人の運命の人、羽香里と唐音と出会う。果たして恋太郎の決断は!?', '2023/10/11 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fec78752-5b8a-4a5b-a3d0-5bd07383c8ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c75e11e1-bd7f-471d-8f7f-8fd0e53549cf', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 2, '100163052', 'はじめてのチュウ', '人生初の彼女が同時に二人もできた恋太郎。そんな中、キスの経験もまだであることを知った羽香里と唐音。二人はあの手この手で恋太郎のファーストキスを奪い合うのだが…。', '2023/10/18 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f5e0ca5-0f2a-4d9c-9b6c-39d86dab851f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eea514a4-88d1-48d0-aa3e-43218ce5699e', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 3, '100163636', '無口な姫と騎士と武士', '好本静と運命の出会いを果たした恋太郎。静は人と話すことが苦手で、愛読書の台詞や文章を指差し、それを相手に読んでもらいながら会話していた。そんな静に恋太郎は…。', '2023/10/25 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4d76c76-5c18-4a12-8820-7ff2e9db8ad9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8bb7899-e1f8-4cc3-a46a-a7ff3c8e41d0', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 4, '100164309', 'いちゃいちゃ回と思いきや', '3人目の彼女に戸惑うも、恋太郎の誠意に満ちた姿勢もあり、静を迎え入れる羽香里と唐音。しかしどこか遠慮がちな様子の静。そこで恋太郎はとっておきの秘策を実行する…。', '2023/11/01 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a61141d4-4548-447c-b7cd-9df9fe1cd185.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df3983bc-699f-4c88-aaef-41eadc5b29ab', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 5, '100165193', '効率的な彼女', '才色兼備で何事にも効率を求める栄逢凪乃と運命の出会いを果たした恋太郎。何気ない会話ですら「無意義」とあしらわれ、本当に“運命の人”なのかと戸惑う恋太郎だが…。', '2023/11/08 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61531d7d-ace0-4434-90c1-a75d9ef0f778.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5956369a-cc50-4634-9b9d-b70effbf5287', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 6, '100165740', '皆大好き水着回', '屋内プールに遊びに来た恋太郎一行。彼女たちの魅力に翻弄され、ついには失神してしまった恋太郎。その後もトラブルに見舞われる彼女たち…。どうなるスパリゾート編?!', '2023/11/15 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7ef643c-533c-4e08-8cf8-6038e9ba6b77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('114269b1-c074-4cfb-bf1e-cd53b118703c', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 7, '100166598', 'はじめましてのお薬少女', '化学室で見かけた女の人に運命を感じた恋太郎。翌日化学室を訪れるとその女性はおらず、小柄で陽気な女の子、薬膳楠莉がいるだけだった。いささか強引な楠莉に恋太郎は…。', '2023/11/22 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1203e22-0d5a-4c4d-a035-dbd4e0ef4cd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('693cc6f8-e2a9-4d5a-a715-ec553a369760', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 8, '100167132', 'キスゾンビ♡パニック', '楠莉が用意した薬を間違って飲んだ羽香里、唐音、静、凪乃は恋太郎とキスをすることしか考えられないキスゾンビになってしまった! 恋太郎と楠莉は、4人を救うため化学室を目指す…!', '2023/11/29 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be2e2e84-a1d4-4941-a4dd-38933210c6d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04476242-2252-48d4-bd78-28d5dfee2f3b', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 9, '100167759', '愛と魂をかけた聖戦', 'フラワーパークを訪れた恋太郎一行は、パーク名物のブーケトスイベントに参加する。ブーケをキャッチできた人は特製のウェディングドレスを着て、恋人と一緒に記念撮影ができるというが…。', '2023/12/06 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22fcbff1-494c-469a-b635-8d58f32a2588.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d863866-759e-4a0e-8b07-21cb05afd745', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 10, '100168607', 'ラブミッション：インポッシブル', '突然の羽香里からの別れ。それは彼女の母親である羽々里から恋太郎を守るための悲痛な決断だった。羽香里を連れ戻すため、恋太郎ファミリーはいざ花園家の屋敷に忍び込む。', '2023/12/13 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0c15dbb-ec36-4d7b-835d-26bd2a3fd45e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3861d0cc-f681-4260-ba76-43d62b3d5411', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 11, '100169276', 'この命にかえても', '恋太郎と唐音を拘束した羽々里は強硬な態度をとり続ける。しかし特注の嘘発見器をもってしても恋太郎の愛に偽りはなかった。そんな中、自室で思い詰めていた羽香里は…。', '2023/12/20 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/615bde5e-54cd-40f8-a055-efd981b9a4e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42c6d9ee-974f-48e3-a59c-52ab442ac60c', 'cab0b27c-cad6-494e-8619-e3ccd8ef4bc0', 12, '100170183', '君のことが大大大大大好きな100人の彼女 (あと94人)', '羽香里を取り戻し、羽々里を加えた恋太郎ファミリー7人は、花園邸でお泊まり会をすることに。最終話の出血大サービスとばかりに楽しい時間はあっという間に過ぎていき――。', '2023/12/27 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26115d86-058e-4ac6-aa8f-ebe700fe841b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8bc4bf1f-6c93-4050-9a68-8513f34725c0', '1bd00d5e-825d-419e-87f2-a406d1630873', 'hulu-the-100-girlfriends-who-really-really-really-really-really-love-you-s2', '第2期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4193f1ea-6121-467f-bd5b-da82779b6470.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b549b8c3-a4fc-403d-8537-4f90eafd3692', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 13, '100212542', '彼 (カノ) の名は。', 'ついに始まったアニメ第2期! 開幕早々の騒動の後、恋太郎は高校の購買を訪れていた原賀胡桃と運命の出会いを果たす。だが空腹でイライラする彼女の人当たりが強すぎて…。', '2025/01/15 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4193f1ea-6121-467f-bd5b-da82779b6470.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a54804e3-39a2-4722-9739-74e49315e02d', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 14, '100213946', '開幕! 激闘! 決着! フードファイトフェスティバル', '恋太郎の提案でフードファイトフェスティバルに参加するファミリー一行。次々に立ちはだかる試練を力を合わせて切り抜けてきたが、ファミリーたちの胃にも限界が近づき…。', '2025/01/22 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2253acad-07ea-4368-ba4f-dbb5fc8ec816.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('500c5143-dbd4-496c-afd2-31ac4cf6afe0', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 15, '100214479', 'メイドさんは見えてる?', '今日も今日とて楠莉の薬による騒動を経た後、羽々里から花園家のメイドの瞳の秘密を知った恋太郎ファミリー。彼女の瞳を一目見ようとあの手この手で開眼を試みるが…。', '2025/01/29 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49176e10-14af-4cfd-86a8-e8654f553fe4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f18b9f74-e54d-475e-aa4f-27bd40c971ed', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 16, '100215223', 'ぬれぬれメイドパーティー', '恋太郎の1日専属メイド、もとい1日デートを終えた芽衣とメイド服に身を包んだ彼女たちによる、恋太郎のハグチューを賭けたメイドサバイバルゲームが今、開幕する!', '2025/02/05 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c75e8f15-4c82-48f0-b47f-a6cc1e86aa8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0a8d4f3-3e84-4bac-8b2c-9a22e6ebc064', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 17, '100216457', 'アスリートは基本ドM', '恋太郎は校門前で素振りをする須藤育と運命の出会いを果たす。努力家な育の姿に心を動かされる恋太郎。惹かれ合う二人だったが、恋太郎が彼女といるところを育が目撃し…。', '2025/02/12 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ab205d1-c06a-47eb-a7fc-201ec820c545.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cbd9d01a-bef1-45e2-bd0c-bcf9757d45eb', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 18, '100217558', '君のホームランに誓う', '女子野球部存続のため、練習試合に出ることになった恋太郎ファミリー。誰よりも過酷な練習をしてきた育だったが、打席に立つとなぜかバットを振ることができないでいた…。', '2025/02/19 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8100d31-fb75-4bec-b641-270749466caf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1effeca3-e88e-426c-b52d-78ab78687125', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 19, '100218519', 'カラオケ･クライシス', '今日は恋太郎ファミリー皆でカラオケデート! しかし人前で声を出すことが苦手な静は一歩踏み出せずにいた。一方、楠莉がカラオケルームに怪しげな薬を充満させていて…。', '2025/02/26 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abb9168c-ff0a-411a-928e-fe011185443d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3f15a66-da99-4dd7-9b0a-9259df71cf9e', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 20, '100219307', '美しきものたち', 'かつてビューティーコンテストで凪乃に敗北した美々美は、凪乃へ複雑な感情を抱いていた。凪乃と再会した美々美は、ファミリー追放を賭けて「美しさ探し」の勝負を挑む。', '2025/03/05 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a598c65-02e2-4b03-8b71-cfea2ff49243.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5afb3f63-ae79-469f-a499-27a35fbafdc3', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 21, '100220314', '髪のみぞ知る世界', '楠莉の薬で羽々里の髪が大暴走! 本能のまま蠢く髪の毛はやがて学園の域を超え、町中の人々を襲い始める…。恋太郎たちは無事、その毛威から逃げ切ることができるのか!?', '2025/03/12 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d7ee0d6-753d-423e-b9fe-be1f73d051c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b665c9d0-fd7d-4e2e-be41-7ffeecb93f35', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 22, '100221427', 'かくれんボーイミーツガール', '何が起きても前髪を死守する華暮愛々と運命の出会いを果たした恋太郎。しかし彼女は恋太郎から声をかけられるたびに一瞬で姿を消してしまう極度の恥ずかしがり屋だった。', '2025/03/19 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b2bc0ac-1692-419d-a835-f9dbfa42aa2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50597735-8053-4dc9-9942-490be47c18be', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 23, '100221962', '失われしツンデレ', '自分だけが恋太郎に素直になれないことを気にしていた唐音は、楠莉の薬を飲んでツンデレじゃなくなってしまう! やがてファミリーは元の唐音に戻ってほしいと気づき始め…。', '2025/03/26 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08e39a39-a3f6-4236-ad12-f53b2727d69d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a18ce5eb-9faf-4444-a30f-e4e4f0197fce', '8bc4bf1f-6c93-4050-9a68-8513f34725c0', 24, '100222838', '君のことが大大大大大しゅきな100人の彼女 (あと89人)', '【第2期 最終話】ツンデレを封印した唐音だったが、恋太郎たちの想いに触れ、皆で力を合わせてツンデレを取り戻すことを決意する。唐音を元に戻すため、恋太郎ファミリーがひとつになる!', '2025/04/02 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61c6d8bd-d759-4e0b-a9c7-1c18579e1e7e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('761298a4-79d5-411e-8cb4-1e57c0df4443', '君は冥土様。', '', 'hulu', 'you-are-ms-servant', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26ac435c-52a0-49ed-913a-65b2922f3ee9.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 172190, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('197cdf76-3d9b-46ab-bfb4-2e4993afb96f', '761298a4-79d5-411e-8cb4-1e57c0df4443', 'hulu-you-are-ms-servant-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5e6df72-e62b-4d11-8748-ff3aecfdaf43.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c843fde5-3752-4b9d-af98-ab898f86fb98', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 1, '100200720', '第1話『君と運命の出会い。』', '夏休みのとある日。一人暮らしを満喫中の横谷人好の家に、メイド服を着た女性が突然やってきた。「私を使用人として雇ってはいただけないでしょうか？」と言う彼女の美しさに見惚れてしまった人好だったが、暗殺が得意だと淡々と語る彼女に慄き、一度は雇用を断る。しかしトラックに轢かれそうになったところをその女性に助けられ、人好は彼女をメイドとして雇うことに。そんな彼女だが家事の腕は壊滅的で――', '2024/10/11 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5e6df72-e62b-4d11-8748-ff3aecfdaf43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('116a8fb6-9c0d-46e2-ad8a-8541f376a144', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 2, '100201673', '第2話『君は知りたい。』', '家の前に捨てられていた温厚そうな犬を引き取ろうとする人好。しかし暗殺訓練中に野犬に怯えた経験があるメイドさんは、犬に近づけない。暗殺しかできない自分を責めるメイドさんだったが、楽しそうに笑う人好と犬を見て、この世界に自分の居場所がほしいと感じる。殺し屋をやめて“普通”の子になれるかもしれないと考えた彼女は、犬が「あげもち太郎」と名づけられたのを見て、自分にも名前をつけてほしいと依頼する。', '2024/10/18 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6190839a-f151-48ce-9ca3-b094ed0d50e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d658076e-7c71-4350-9744-6f2733151869', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 3, '100201674', '第3話『君は雪さん。』', '別の家で暮らしている人好の妹･李恋 (リコ) が横谷家にやってきた。綺麗な女性が大好きなリコは、「雪」と名づけられたメイドさんの登場に驚きつつも、殺し屋稼業と聞いて興味津々。暗殺テクニックを教わったり雪の独特な味覚を褒めたりして、すぐに雪と仲良くなる。人好、李恋と共に夏祭りに出かけた雪は、大好きな勝田ソースを使用したソース煎餅の味に昇天。生まれて初めてお祭りを心から楽しんだ。', '2024/10/25 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03c51ccb-9f7f-4c07-8945-306823b2b2db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d711f6bb-0526-46bb-a191-14cf74868af4', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 4, '100201675', '第4話『君は逃さない。』', '李恋 (リコ) が手配したおかげで、人好と同じ高校に通えることになった雪。人好のいとこ「横谷雪」という設定で同じクラスに編入する。勝田ソースを使った勝田パン争奪戦に参戦し、雪はすぐに高校生活に打ち解けていく。そんなある日、雪の不手際で怪我をした人好が保健室に行くと、新田という臨時の保険医が待っていた。妖艶な雰囲気をまとった女の登場に、雪は危機感を覚える。', '2024/11/01 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21d398db-0f6b-4e4e-a869-76e911d98b5b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2628beef-f223-46e2-9a82-c4f8799ea8ec', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 5, '100201676', '第5話『君の護りたいもの。』', '新田に自分と同じ暗殺者の匂いを感じた雪は、人好を徹底的に守ることにした。学校でも家でも、雪は人好にぴったりくっついて離れない。夜はベッドの真横で人好を見張っていたが、一瞬の隙をつかれ暗殺者に人好を奪われる。新田と名乗っていた女の正体は暗殺者グレイス。グレイスの狙いは、最強暗殺集団「竜生九子」内でも伝説と呼ばれた、“白狼の雪 (シュエ) ” の命。大切な人好を人質に取られ、雪の怒りは頂点に達する。', '2024/11/08 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57e2297e-e16d-4310-831f-26182c7438ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba4dd5be-5e44-42fe-94a5-640de92cfbed', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 6, '100201677', '第6話『君は割と寂しがりや。』', '雪との圧倒的な力量差を知ったグレイスだったが、これ以上お互いに干渉しないことを条件に、体育教師の新田として人好の高校に勤務することに。人好がクラスメイトと話しているのを見て嫉妬したり、苦手だった洗濯が上手にできるようになったりと、雪は“普通”の生活ができる幸せを日々実感する。一方、小さなことに一喜一憂している雪を見て、人好は雪の過去をもっと知りたいと思うようになっていた。', '2024/11/15 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d96a0cec-b6e4-44c9-be9e-764437a89ae6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3b27012-3a4a-4b99-9b63-0a8b3df3b9c4', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 7, '100201678', '第7話『君は遂にそこに気付いた。 －THE HALLOWEEN NIGHT WITH YOU－』', 'メイド服は“普通”ではないと知ってショックを受けた雪は、人好、李恋 (リコ)、グレイスと一緒に街にショッピングに出かける。服をたくさん買ったり、映画館で初めてゾンビ映画を観たりと、ごく普通の休日を満喫した雪。帰宅すると、あげもち太郎 (もち太) が愛用しているタオルがボロボロなことに気づく。洗濯するためタオルを預かろうとすると、もち太が初めて牙をむいた。もち太にとって大切なタオルであると知った雪は――', '2024/11/22 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05cecf67-5d81-4d7d-bc9d-9a1b44592af6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d09515d-f5b3-4d22-964b-44ef91fa522b', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 8, '100201679', '第8話『君と食欲 (ソース) の秋。』', '人気の勝田ソースがあと1週間は買えないことがわかり、ショックを受けている雪。さらに生き別れた妹の夢を見てうなされる毎日。自分のせいで家族が壊れてしまった幼少期の悪夢に苦しんだが、人好との添い寝で気持ちを落ち着けた。人好の高校では勝田三大祭が近づき盛り上がっているが、1年生で優勝できる可能性は低い。しかし優勝賞品に勝田ソースがあると知った雪は、本気で優勝を目指そうとする。', '2024/11/29 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3c49da8-7cd6-41c4-8227-442334e29123.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbbaf67d-ff6c-448b-b0c0-425cd28ed7cd', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 9, '100201680', '第9話『君と文化の段。』', '勝田祭のクラス対抗戦は、クラスから3人が代表して出場する「ケイドロ」。生徒会長の日陰武は日陰流忍術の後継者として圧倒的な戦闘能力を誇り、2年連続の優勝を狙う。雪たちのクラスメイトで武の妹である日陰ナカは、勝って兄に認めてもらいたいと情報収集で雪たちに加勢する。兄と共に厳しい訓練を受けてきたナカには友達がいない。ナカは勇気を振り絞り、自分と友達になってほしいと雪に伝える。', '2024/12/06 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56b45a65-b675-44e6-b131-b95a18e6a494.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53b41015-633f-4f04-a0d3-06dfc546fd02', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 10, '100201681', '第10話『君と禁断の果実。』', 'ナカという友人ができ、護るものが増えた雪だったが、一方の人好は父親の帰国が決まり浮かない顔。人好を元気づけたいと考えた雪は、李恋 (リコ) に協力をあおぎ、精一杯のオシャレをして人好にデートを申し込む。いつもよりさらに綺麗な雪にドキドキが止まらなくなった人好は、雪への恋愛感情があるのか意識するように。そんなある日、コタツで鍋をした人好、雪、リコ。初めてコタツを体験する雪だったが――', '2024/12/13 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/971cf902-5856-43da-9ea1-69184286dd2d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13937b99-73b9-4f91-b542-650c6762f1b2', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 11, '100201682', '第11話『君の祈りは神の祈り。』', '雪への恋心を自覚してしまった人好は、雪とあえて距離を取ろうとする。そんな人好の態度に戸惑いながらも年末の大掃除に取り組む雪だったが、失敗ばかりで涙が止まらなくなってしまう。落ち込んだまま新年を迎えた雪は、ナカの誘いで初詣へ出かける。「必要とされなくなって、人好様と一緒にいられなくなるんじゃないかって…」と、雪は本音をナカに打ち明ける。', '2024/12/20 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7e282c4-ae7e-44c9-b28a-8166e388a970.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf884712-2132-426b-bd46-cd30277c12f9', '197cdf76-3d9b-46ab-bfb4-2e4993afb96f', 12, '100201683', '第12話『君たちによる福音。』', '【シーズン1 最終話】人好の父、新が横谷家に帰ってきた。雪の主の話題で盛り上がる新と雪を見て人好は疎外感を感じ、久しぶりなのに父とうまく言葉を交わせない。別れ際、人好はどうしても聞きたかったことを父に尋ねる。新がいなくなり人好と2人きりになると、雪は人好に誕生日プレゼントを渡した。雪が頑張って選んだプレゼントを見て大切なことを思い出した人好は、雪に抱いているすべての想いを打ち明ける。', '2024/12/27 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d3d6de5-5b5a-49f7-b070-a31214ee7174.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7f5a8380-13d9-4bc0-973c-fed4e24daf1b', '薫る花は凛と咲く', '', 'hulu', 'the-fragrant-flower-blooms-with-dignity', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/487fbab2-6813-452d-bd27-3f0c7ec079e5.png?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 181444, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e71a3842-99bd-40e3-9344-3e33d42e21d2', '7f5a8380-13d9-4bc0-973c-fed4e24daf1b', 'hulu-the-fragrant-flower-blooms-with-dignity-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b372c37e-51cf-459f-bd74-8ce750608dce.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2774b5f8-384e-473e-bc5a-2782147c02d4', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 1, '100232551', '凛太郎と薫子', '底辺男子校の都立千鳥高等学校と、由緒正しきお嬢様校の私立桔梗学園女子高等学校。隣接してはいるものの、両校の溝は深い。千鳥に通う紬凛太郎は実家のケーキ屋の手伝い中に、大量のケーキを食べる少女･和栗薫子と出会う。凛太郎を見て逃げるように店を去った薫子。怖がらせてしまったと後悔する凛太郎だったが、翌日彼女は凛太郎を訪ねてくる。', '2025/07/13 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b372c37e-51cf-459f-bd74-8ce750608dce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81fa9fa4-f310-4f88-b18f-1a6b515cd320', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 2, '100232932', '千鳥と桔梗', '自分を怖がらず、まっすぐに見てくれた薫子が桔梗の生徒だと知った凛太郎は、校門で起きた騒動で千鳥と桔梗の仲の悪さを目の当たりにし、もう会わない方がいいと思いながらも薫子のことが頭から離れないでいた。露骨に千鳥を嫌う桔梗だから、薫子はケーキ屋にも来なくなるだろうと考えていたが、凛太郎が帰宅するとそこには薫子の姿が。', '2025/07/20 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/986375c7-5a5f-4b20-9b11-4fa9fdce6535.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e3a56f2-3a48-44e2-91b5-4ff67c877983', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 3, '100233463', '優しい人', '担任から、中間試験で赤点を取るとスポーツ大会に参加できないと伝えられた凛太郎と翔平。朔と絢斗に教えを乞うも断られ、放課後2人は赤点を回避するために図書館で勉強することに。途中、1人外のベンチに移動した凛太郎は同じく勉強に来ていた薫子に出会い話をする。その様子を薫子の友人で千鳥を嫌う保科昴に見つかってしまい――。', '2025/07/27 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f54f000f-9f34-4fcb-be1a-0ac015542ab6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9341b10d-290b-42c7-bb65-1c23d7a89159', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 4, '100233916', '心の温度', '薫子に勉強を教わることになった凛太郎。休日に2人で過ごすことに緊張しつつも、互いに敬語で話すことをやめ、友人として距離を縮めていく。勉強会を終えて帰宅しようとした凛太郎は、突然昴に呼び止められる。困惑する凛太郎に、昴は「もう薫子には会わないでほしい」と伝えてきて――。', '2025/08/03 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d70a8f0-f537-4a39-8cb1-3b1c8e5c6d1e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('792696af-0210-4c4e-be0e-b2b5031d6229', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 5, '100234665', 'はじまりの予感', '薫子からのメッセージが添えられたノートを翔平･朔･絢斗に見られてしまった凛太郎。問い詰められても「言いたくない」と拒絶する凛太郎に朔は怒りを隠せず、険悪な雰囲気になってしまう。2人に仲直りをしてもらいたい翔平と絢斗が朔に怒っている理由を聞くと、意外な答えが返ってくる。', '2025/08/10 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb7c53d3-9f94-4b9c-8c88-24a46a74f705.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00b5bdc3-ba11-4745-a877-8818429261ef', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 6, '100235055', '大嫌い 大好き', '昔よく2人で遊んだ公園に薫子を呼び出した昴は、凛太郎に「薫子にはもう会わないでほしい」と話したことを打ち明ける。勝手なことをしたと何度も謝る昴に、薫子は「今だけ、昔に戻ろう」と幼少期の思い出を話しはじめる。それを聞いた昴は――。', '2025/08/17 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ba12950-bd3f-48f2-8fe1-ffda2025910c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19a0edc9-0429-42ca-be29-8d5499295e3c', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 7, '100235415', 'かっこいい男', '様子のおかしい凛太郎を見て何かあると感じた翔平･朔･絢斗は、放課後、凛太郎を尾行する。凛太郎が待ち合わせをしている相手が桔梗の生徒･薫子と昴であることに驚く3人。ファミレスでバレないよう隣の席に着くと、凛太郎の本音が聞こえてきて――。', '2025/08/24 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e54d575-127b-448a-b6dd-3a5dacf40c0e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c13329cd-b32e-44a0-a59b-a1b2322f80e8', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 8, '100236036', '感情の正体', '翔平･朔･絢斗に薫子と昴を紹介する凛太郎。ぎこちなさは残るものの、千鳥と桔梗という学校の垣根を越え、6人は新しい関係を築き始める。その帰り道、中間試験の勉強会のお礼がしたいと話す凛太郎に薫子がお願いしたのは一緒にでかけることだった。', '2025/08/31 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3859b60-e61e-47d6-a452-960d23470004.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93f2f079-24b7-4bcb-af0e-149946e4d7d1', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 9, '100236782', '金髪とピアス', '薫子への想いを自覚した凛太郎は、自分の感情に振り回されることにもどかしさを感じていた。休日に翔平･朔･絢斗が凛太郎の自宅に遊びに来ることになり、当日偶然ケーキを買いに訪れた薫子と昴も合流することに。', '2025/09/07 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0451731-1cf5-45b4-840e-e5afde528240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f910dec4-2f62-4572-a936-3446d3624007', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 10, '100237723', '青い嵐', '期末試験に向け6人は勉強会をすることに。その成果もあり、凛太郎と翔平は再び赤点を回避。放課後、クラスメイトとボウリングに向かう途中、道の向こうに薫子たち桔梗の生徒の姿を見つけ、凛太郎は薫子から目が離せなくなる。それに気づいた翔平の一言で“ポンコツ紬”が再来――。', '2025/09/14 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae5bb344-103c-4ab2-bc3f-5709fbc5ae6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27400282-aa9f-48b9-acef-4469a55cdfec', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 11, '100238132', 'ぬくもりのひとくち', '昴から薫子の誕生日が2週間後だと知らされた凛太郎は、祝いたいと思いつつも何をプレゼントすれば良いのか悩んでしまう。母のアドバイスを受け、薫子の大好きなケーキを手作りすることにした凛太郎は、父に教えてもらうことに。昴のアシストもあり、薫子と誕生日に会う約束をした凛太郎は一層気合を入れてケーキ作りの特訓に励む。', '2025/09/21 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e282949a-047c-4174-b10c-1555289a8d73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6af81345-7482-4faf-9541-632dcda43880', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 12, '100238987', '海辺の惑い', '夏休み、6人で海に遊びに来た凛太郎たち。和やかな雰囲気の中、1人浮かない表情を浮かべる昴。薫子に理由を尋ねられ、悩んでいる理由を打ち明ける。みんなと過ごす中で凛太郎たちとちゃんと向き合いたいと思った昴は、4人にある「お願い」を口にする。', '2025/09/28 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3bd937f0-18b6-494e-a795-af11331cd1ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e0c532d-aa1e-492a-9ebf-40c5eb2f97a5', 'e71a3842-99bd-40e3-9344-3e33d42e21d2', 13, '100239680', '薫子と凛太郎', '【最終話】海で思わず告白してしまった凛太郎は、もう一度会って話をするために薫子と2人で夏祭りに行く約束をする。凛太郎から真っ直ぐな思いを伝えられた薫子は、2人が初めて出会った日のことを話し始めるが、それは凛太郎が思い出している日とは違っていて…。2人にとって、一生忘れられない1日が始まる――。', '2025/10/05 01:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/962ee119-29a4-4bce-9861-001ebb584f15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('49e4d59e-115e-4094-b9c7-629a4a7a85f5', '経験済みなキミと、経験ゼロなオレが、お付き合いする話。', '', 'hulu', 'keikenzuminakimi-to-keikenzeronaore-ga-otsukiaisuru-hanashi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cfbc1782-fb57-4459-a2a0-004893e8c746.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 154459, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', '49e4d59e-115e-4094-b9c7-629a4a7a85f5', 'hulu-keikenzuminakimi-to-keikenzeronaore-ga-otsukiaisuru-hanashi-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb8dd27c-8ce1-450b-b3f0-32118161f237.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a09fd8cb-858e-4498-880a-25e1c1f9d372', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 1, '100162150', '経験済みなキミに、経験ゼロなオレが、告白する話。', '高校2年生のリュートは、量産型陰キャ男子。友人も少なく、趣味はゲーム実況動画を観ることぐらい。もちろん彼女なんて、できたことがない。ところが、ひとりだけテストの成績がよかったがために、学年一の美少女･ルナに告白することになる。ほとんど話したことがなく、住む世界がまるでちがう存在。当然断られると思っていたが……!?', '2023/10/12 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb8dd27c-8ce1-450b-b3f0-32118161f237.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7eb6add9-9bfa-4dec-8311-ffbcfbdfb64f', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 2, '100162655', '経験済みなキミと、経験ゼロなオレが、初デートする話。', 'ルナとお付き合いすることになったリュート。だが、友人のイッチーとニッシーからは、「告白をOKしたのは、陽キャジョークにすぎない」と言われ、すぐにフラれるのではないかと不安でいっぱい。ルナに話しかけられても、まわりの視線が気になり自信が持てない。そんな中、ルナと初デートをすることになって……!?', '2023/10/19 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3789086e-3e54-46c3-932c-b253c07ac0c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c45776ae-abf6-4898-9b6a-f3b43adc77e2', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 3, '100163934', '経験済みなキミに、経験ゼロなオレが、サプライズする話。', '中学1年生のときにフラれた相手、マリアが転校してきたことに驚くリュート。でも、ルナという彼女がいるので、話しかけられても距離をとるようにする。そんなある日、リュートは、ルナの親友で鬼ギャルのニコルに声をかけられる。ビクビクしながら話を聞くと、もうすぐルナの誕生日であることを教えてもらって……!?', '2023/10/26 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1ab97cf-3289-4454-8a82-62b61826fcfa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b3d2718-cbb1-443f-b978-d66033f3886c', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 4, '100164307', '経験済みなキミに、経験ゼロなキミが、嫉妬する話。', 'クラスメートの前で、ルナの彼氏であると宣言したリュート。ルナもまた、リュートと付き合っていることをみんなに伝える。どよめく教室から、そっとひとり出ていったのは、マリア。リュートは追いかけ、なぜルナについての悪い噂を流したのかを聞く。するとマリアは、ルナとの驚くべき関係について話しはじめた……!', '2023/11/02 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/693cbce5-da14-453e-b695-3541c2be4e84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3bbe6222-7e51-455d-9b97-d3c2d4c739e7', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 5, '100165402', '経験済みなキミと、経験ゼロなオレが、お泊まりする話。', 'リュートとルナは、交際一ヶ月記念に、海へデートに行くことになった。ルナのまぶしい水着姿にドキドキのリュート。ルナの背中に日焼け止めを塗るだけでもぐったりだが、ルナの楽しそうな様子につられて、少しずつ緊張もとけて満喫する。ところが、夕方になって天候が急変。交通機関が止まって、二人は帰れなくなってしまい……!', '2023/11/09 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6b601a5-e920-4a39-be1e-359bebffc660.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e10ba44-eeaa-41f7-8f80-384b027a34e4', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 6, '100165739', '経験済みなキミが、経験済みな誰かと、浮気する話?', 'リュートを夜の体育館倉庫に呼びだしたのは、ルナのふりをしたマリアだった! 激しく動揺するリュートに、マリアは切々と自分の胸のうちを伝える。「わたしは初めてを……わたしの全てを加島くんに捧げたい!」 マリアの思いを聞いたリュートは……? さらに、二人が話しているところを何者かが撮影していて……!?', '2023/11/16 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fbec4b2-aefc-412b-842e-3299ad60b02b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('383ec136-7076-447b-a51a-af9132932dff', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 7, '100166596', '経験済みなキミと、経験ゼロなオレが、夏まつりに行く話。', 'リュートとルナは、夏まつりまでの二週間を、ルナのひいおばあちゃんの家で、いっしょに暮らすことになった。海の家の手伝いをしたり、夕飯の買い物へ行ったり、料理をしたり……。まるで夫婦のようなシチュエーションにドキドキしながら、二人は幸せをかみしめて、将来を思い描く。', '2023/11/23 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bdbd6f42-2f9f-4e42-bbfa-f72ec6ae6380.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25700d1e-a137-4e8f-a8bc-c491f5540726', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 8, '100166987', '経験済みなキミと、経験ゼロなオレたちが、サバゲーする話。', 'リュートは、ルナといっしょにできるお互いにとって初めての経験をしようと考え、サバゲーへ行くことに。イッチー、ニッシー、ニコル、アカリも誘って、陰キャ男子とギャルたちによる熱いバトルがフィールドで繰り広げられる。サバゲーで大いに盛り上がった後、二人になったリュートとルナは観覧車に乗って……。', '2023/11/30 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b9727bd-6cb5-40ff-a066-41970d3875ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ee71345-bbcf-434d-ab05-1679509393fb', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 9, '100167757', '経験済みなキミと、経験ゼロなオレが、いっしょに走る話。', 'ルナは、マリアとの『友達計画』を推しすすめようと、文化祭の実行委員に立候補。リュートも巻きこんで、三人でパンフレット係になる。ところが、ルナとマリアの意見はかみあわない一方で、リュートとマリアはゲームの話などでつい盛りあがってしまう。そんなぎこちない関係性のまま迎えた運動会の日に事件が起こる……!?', '2023/12/07 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/edb1cd7f-4141-4436-b1f5-d67883e26e05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7cf6f68-c032-49f7-bd89-274a16ade6f9', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 10, '100168606', '経験済みなキミと、経験ゼロなオレが、すれちがう話。', 'ルナは、しばらく距離をおこうとリュートに提案する。何もできずにいるリュートだったが、アカリから「ルナがパパ活をしているかもしれない」と聞く。ルナがそんなことをするわけないと信じつつも、相手の男が気になるリュートは、関家に頼んで、文化祭の日に学校に来てもらうことにしたが……!', '2023/12/14 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e472daa9-b7ea-4808-b58e-acb3b4a47cf3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2d6e74c-25c7-4729-ac3e-9f2a15a72649', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 11, '100169274', '経験済みなキミと、経験ゼロなオレが、お別れする話。', 'イッチーはアカリにフラれて引きこもり、ニッシーはニコルに片思い。ニコルは関家と再会できて付き合いはじめたかに見えたが、うまくいっていない。……それぞれの恋愛模様が揺れる中、リュートとルナの関係性は、表面上穏やかでもお互いの心が見えず、ぎこちないままだった。そしてとうとう、ルナはある決意をする……。', '2023/12/21 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/54d964e0-11a3-4d9a-b4aa-6298b5b51786.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b219c67a-9b4f-40b1-884e-c1a54226e756', '9f9b6e3b-f2f5-4c7f-97e7-f60edc426bb3', 12, '100170182', '経験済みなキミと、経験ゼロなオレが、経験する話。', '【最終話】ルナは、また家族みんなで同じ家に暮らしたいという夢を叶えたい。そこでクリスマスイブの日、リュートとマリアの協力のもと、両親をサプライズで再会させて元の夫婦に戻す作戦を計画する。ところが事態は予想外の方向へ……! さらにその夜、リュートとルナは二人きりで一夜をすごすことに。ルナに抱きつかれたリュートは……!?', '2023/12/28 23:00:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c41f9be1-7482-41a8-9640-0432cc20fd4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ba6b9e74-3f75-41f3-b092-ed4b297b0e26', '警視庁 特務部 特殊凶悪犯対策室 第七課 -トクナナ-', '', 'hulu', 'tokunana', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9718206-26ae-4226-9aa3-400447728d28.jpg?w=331&h=447&p=t', 'hulu', 2019, 3, 1, 'FINISHED', NULL, 108554, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5aab91c0-184c-4206-884b-ce5934fe3e5b', 'ba6b9e74-3f75-41f3-b092-ed4b297b0e26', 'hulu-tokunana-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c92323e2-a2b8-4ff9-9b0f-ad8afc5a56c7.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ef82114-2ac1-4507-bbe9-d2f188915d4e', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 1, '100043589', '一は凶兆を、七は幸運を', '中学生の頃、凶悪犯罪組織「ナイン」によるテロ事件に巻き込まれた七月清司は、一人の警官に命を救われる。事件から9年が経ち、命の恩人である警官に憧れ、自らも警官となった。ある非番の日に、銀行強盗の現場に居合わせた七月は、そこで同じく警官だと言う一ノ瀬栞に出会う。この日を境に、七月の人生は大きく変わることになるのだった―。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c92323e2-a2b8-4ff9-9b0f-ad8afc5a56c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b7a1efb-03f4-4af7-a466-1981fde19914', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 2, '100043772', '捜査する二人', '銀行強盗事件の一件で、「特殊凶悪犯対策室 第七課―通称トクナナ」に突如配属されることになった七月。そこは凶悪犯罪組織･ナインに対抗する為の部署で、卓越した能力をもった個性の強い警察官6人が所属しており、その中に一ノ瀬もいた。そして赴任早々、七月は一ノ瀬と共に政治家殺害事件の現場に向かうことになる。しかし捜査をしていく中で、ほぼ同時刻･同様の殺害方法で他の3人の政治家も殺されていることが判明し…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/529a2fa9-e1d2-4c8c-9b60-123e4ee50e76.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ac10704-8d58-444f-a9b0-77daf5da8102', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 3, '100044013', '三重の罠', '情報屋から二条のもとに、連続爆弾魔Bがオフィスビルに爆弾を仕掛けたとのタレコミが入る。ナイン関係者と言われるBの爆弾には、ドラゴンの遺産である“魔術”の技術が使われていた。現場に急行したトクナナは3棟のビルに仕掛けられた4つの時限爆弾を発見するも、爆発物処理班が何者かに襲撃を受けて到着できない緊急事態となる。やむなく自分たちで解体を進めるが、爆弾のカウントダウンが急速に速まり…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77409621-6d03-47ba-bde5-39d809b02658.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('337760e9-b0a7-414e-b970-c5c484d130a3', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 4, '100044316', '四人の家族', 'とある交通事故を捜査するトクナナ一同。自動車が発火するなど、不審な点が多くみられ、ナインが関わっている可能性があるためだった。運転手の江口晋太郎は軽傷だが息子は意識不明の重体。しかも息子にはなんと1億もの保険金がかかっているという。今回ある事情で二条と捜査を進めることになった七月。しかし一ノ瀬以上に何を考えているのか分からない二条と、果たして上手く捜査を進められるのか…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43b27e74-dafb-4f11-a7c6-d2bdb1ea00c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43bb6ab8-0e9d-44aa-96f6-4d5ed2f05771', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 5, '100044851', '第五の封印', '先日のオフィスビル爆破事件と近似した魔術反応があったというショッピングモールへ、捜査に向かった七月たち。七月と一ノ瀬は各階のフロアを見回るも、特に不審なものは見られない。すると突如、モールの入り口が爆破され銃声が鳴り響く。客に紛れて侵入したナインを自称するテロ集団が現れ、「儀式を行う」と宣言しモール内はパニック状態に…! 一方、二条は単独で地下フロアに向かうが、そこで彼が遭遇した人物とは…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43f77ccb-a6f4-4f6f-a28b-8c31ecc2134c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02ac7565-4482-4c4a-93cb-0c786a027d44', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 6, '100045170', '六分間の死闘', '桐生院の命令により四季彩たちが駆け付けるが、妨害電波のせいで地下にいる二条とは連絡がとれない。一刻を争うため、一ノ瀬はこのメンバーでの人質救出を判断する。圧倒的に不利な状況ではあるが、一ノ瀬はテロリストのほとんどが一般人に近い素人同然の者たちの集まりであることに気づき、ある作戦を立てる。それは意外性があるものの、かなりエキセントリックなもので…。七月たちは人質を無事救出できるのか…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3152a4dd-bb3f-4bcc-bb7d-1a300168d208.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91a391c3-3117-41a3-8f03-4df76e18f52a', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 7, '100045743', '七日目は惰眠', 'ショッピングモール事件から数日。休日となったトクナナ部署だったが、七月は間違えて出社してしまう。そんな七月に桐生院はせっかくだからとデートに行こうと誘い出す。桐生院が向かった先は、元トクナナメンバー･三潴ルカにまつわる場所だった。七月が三潴について尋ねているところに偶然、一ノ瀬がやって来て…。一方で四季彩･遠藤･ベルメールが各々休日を過ごす中、二条は情報屋･黒真珠から衝撃の事実を告げられる。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47e8502c-a588-47d1-b47e-db40dcf21b8a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bdcba917-f89c-4b85-8cc7-4416f5c60a38', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 8, '100046334', '八フィートの逃げ道', 'ある日ベルメールは、ミニドラゴン型ドローンを通して桐生院と話しながら買い物に出かけていた。しかし店を出たところで突如知らない男に車に連れ込まれ、誘拐されてしまう! すぐに異変に気づいたトクナナメンバーは、手分けしてベルメールを探すために動くが、手掛かりが少なく中々居場所を突き止められない。一方、ベルメールと桐生院は監禁された部屋で“あるモノ”を見つけてしまい…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e33e79ca-7eea-4bb0-bcff-91026762512a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81f4d65e-1e6e-4e88-a3ca-3b65c8cd8fbd', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 9, '100047341', '九年の憤怒', 'エアポート･テロ事件の実行犯であり、ナインの元構成員･枇杷島を護送するトクナナ。だが、枇杷島は反省した様子が全く無く、不遜な態度をとり続ける。怒りを抑えきれない一ノ瀬と戸惑いを隠せない七月、そして不自然に沈黙を保つ二条。それぞれの思惑が交差する中、ついに9年前の事件の真相が明かされていく…。そして、枇杷島の護送中、突如ナイン構成員に銃撃を受ける七月たち。絶体絶命の状況を切り抜けられるのか…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac8f7a5c-74ec-4c87-87ff-127c77af575a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5829dcf-f198-4e16-9842-85755c98af07', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 10, '100047637', '十番目の竜', 'エアポート･テロ事件の裁判が開廷し、ナインの首謀者ウォーロックの判決が下される日がきた。厳戒態勢の中、他の警官と共に警備に駆り出されるトクナナ。だが、二条はある決意から、桐生院のもとを訪れていた…。そして、裁判が始まるが、ウォーロックの弁護人は「彼の無実を証明しよう!」と突如叫びだし!? 混乱する法廷。ついに全貌を現したナイン。そして、七月の隠された秘密が明かされる!!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7334d009-edc8-4c9e-bd66-992104802c54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa00ebf5-459c-40a2-b6da-c84decac66cd', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 11, '100047936', '十一時の戦争', '七月は三潴ルカが壊れたのは自分を助けたせいだと、自身を責めていた。そんな七月に一ノ瀬は、三潴の相棒として“警官の正義” を伝えるが…? 七月の出した答えとは!? 一方、公安によりトクナナの拘束命令が出ている中、桐生院から明かされるドラゴンの秘密。ウォーロックの強大すぎる力の前にどう立ち向かうのか、決断を迫られるトクナナ。そしてトクナナを離れた二条はひとり、兄である三潴と対峙する!!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c00b826-35d4-456c-a6a1-fcf44c7b5399.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2251aa19-3136-42a8-ad86-e4034002bb89', '5aab91c0-184c-4206-884b-ce5934fe3e5b', 12, '100048200', 'ゼロからナナへ', '激戦を繰り広げるトクナナとウォーロック。ウォーロックは圧倒的なドラゴンの力を誇り、まったく攻撃が通じない。同じドラゴンの力を持つ七月が奮戦する中、弱点をさがす一ノ瀬の元に、かかってきたのは一本の電話。意外な相手から提示された作戦に、一ノ瀬は唯一の望みをかける! 果たして、七月は自分の正義を見つけられるのか。一ノ瀬･二条は過去から抜け出せるのか、トクナナVSウォーロックの戦い、ついに決着!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a65509fc-054c-49d8-aab4-fda41f7ffca5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1676b819-c16f-4d36-b0c9-408333086a34', '結界師', '', 'hulu', 'kekkaishi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50000593_series_art__338x600_kekkaishi_ea54c54aa572eff7656149c02190b84c.jpg?w=331&h=447&p=t', 'hulu', 2006, 3, 1, 'FINISHED', NULL, 1606, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('74bee2a5-8766-4c1f-92d3-ddd63489fc29', '結婚するって、本当ですか', '', 'hulu', '365-days-to-the-wedding', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6f0b8de-7182-4def-ab5a-6288211a5ee9.png?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 165790, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', '74bee2a5-8766-4c1f-92d3-ddd63489fc29', 'hulu-365-days-to-the-wedding-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcc20345-d203-41e9-b97f-299cd21a62e5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf9e58dd-3dac-4d34-a672-37017dd32c22', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 3, '100201337', 'ピンチを、分かち合えますか?', 'タクヤが結婚する噂を聞きつけた、タクヤの父･耕一が熊本の阿蘇からやってきてしまう。自分の生まれ故郷である熊本への想いを話す耕一に共感するリカと、自分にはどうにもできないとうんざりするタクヤ。結局タクヤは説明をするために実家に帰ることになり、リカは自分が口を出すことができないところまで問題が大きくなっていることに悩む。そんな時、タクヤは旅行代理店から人気の国であるリヒトブルクの王女･クラウディアのアテンドを依頼される。男好きという噂があるクラウディア王女だったが、彼女にはある秘密があって…。', '2024/10/18 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcc20345-d203-41e9-b97f-299cd21a62e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40dcfeba-12eb-485b-9878-76b23150502c', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 5, '100203097', '一緒に旅を、しませんか?', 'タクヤの実家がある阿蘇に到着したタクヤとリカ。偶然空港で出会ったタクヤの祖母の家に行き、メロン収穫の手伝いをしていたリカだったが、疲れすぎで倒れてしまう。そこへ耕一が現れ、共に介抱するなかでタクヤは結婚がウソであると伝える。耕一にはこっぴどく怒られ、実家にいる母と姉にも謝りに行くタクヤ。倒れていたことで実家の謝罪までタクヤに任せっきりになってしまい、落ち込むリカ。二人は夜の散歩に行き、リカはタクヤと出会ってから楽しいと感じていること、タクヤはリカからもらった石を見るといつもリカのことを思い出すことを伝える。', '2024/11/01 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00fc349e-0710-4aef-8dc1-1a117114d168.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef76e184-1f22-4b65-9224-40704421f966', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 6, '100203851', '二人でいるって、幸せですか?', 'タクヤを意識していることを自覚し始めるリカ。しかしタクヤの幼なじみ･ナオと出会い、二人が仲良さそうな姿を見てモヤモヤしてしまう。良い雰囲気だったリカの態度が急に冷たくなり、何かしてしまったのかと悩むタクヤ。一方JTCでは、社内で一番キッチリしている同僚･進士さんは毎日愛妻弁当を持ってきており、幸せそうな様子。しかし、その進士さんが急に仕事に来なくなってしまう。大騒ぎしているJTCに進士さんの息子･英夫がやってきて、原因が奥さんとの離婚話だとわかり社内に衝撃が走る。タクヤは英夫と一緒に進士さんを探しに行き…。', '2024/11/08 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66b766e7-5c63-49a6-b643-1d285b350546.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae1cfee5-f1e1-4635-8f4a-2e54bbeb1633', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 7, '100205104', '部屋に行っても、いいですか?', 'タクヤとの接し方がわからなくなってしまったリカのもとに、阿蘇から上京してきたナオが現れる。ナオが働くガラス工房に行ったリカだったが、半ば強引に誘われて、リカの家で飲み会をすることに。二人はナオが作った阿蘇への想いがこもったガラスでお酒を酌み交わし、お酒が進んだリカはタクヤへのもどかしい想いが溢れてしまう。リカの想いを聞いたナオは、本人に直接聞くのがいいとタクヤを呼び出す。急に呼び出されて困惑するタクヤがリカの家に到着すると、出迎えたのは泥酔したリカだった。', '2024/11/15 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d91be229-b2a4-4882-8ee0-8b7039186544.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09b3c77e-08a7-4a34-a406-7a4b8f5bf490', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 8, '100205105', '愛の告白って、本当ですか?', 'タクヤがリカに告白したことを後悔していると、権田が家にやってくる。権田はマッチングアプリにハマっており、オタ活目的で知り合った人とオフ会をするため一緒にきてほしいと言う。当日、権田の前に現れたのはカオリーという女性だった。タクヤが間に入る必要もなく、すぐに意気投合する二人。権田は育った家庭環境からちゃんとした家庭に憧れがあり、カオリーとの結婚を意識するようになる。結婚前提で付き合ってほしいとカオリーに告白する権田。本気なのか尋ねたカオリーは権田をある所に連れていく。', '2024/11/22 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fce9282f-4cdc-4468-9d06-27bac57f911a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74142a9a-89f1-4433-b78f-3f014caef681', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 9, '100206177', '莉香さん、お元気ですか?', 'カオリーがシングルマザーであることを知って怖気づいてしまった権田。彼女を想って泣く権田の姿を見て、タクヤはリカとちゃんと話そうと決意する。そのころ、リカはタクヤからの告白にどう答えるべきか悩んでいた。リカの様子を見たナオは、ガラス作り体験を提案する。ガラス作りを通して自分の性格を再認識するリカ。リフレッシュしたリカだったが、母･律から連絡が入って会いに行くことに。律のペースに巻き込まれて疲れるリカ。さらに突然、結婚はしないのかと聞かれて誤魔化してしまう。しかし、律はリカの結婚の話を知っているようで…。', '2024/11/29 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a8cf10c-b646-4b7c-a6cc-f52f6c48ec40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4e5af6b-1865-4332-a1df-c375d3478b5f', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 10, '100207736', 'デートするって、大丈夫ですか?', 'リカは恋愛の連鎖を断ち切るため、タクヤにデートを提案する。いつも通りの自分を見せてがっかりさせるため、玉川上水巡りにつれていくが、タクヤはがっかりするどころか興味をもっている様子。そして楽しそうなリカの姿を見て、普段のリカを知ることができて嬉しいと感じるのだった。昔の人の営みを想像して感動するリカに、共感して一緒に楽しんでくれるタクヤ。嬉しく思うリカだったが、タクヤみたいな人がいることが信じられない。タクヤに別れを告げるリカだったが、悲しいと感じてしまう。お互いに相手が大切な存在だと気付いた二人は―。', '2024/12/06 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a780038c-03c5-4cb7-906f-c758b5692c3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4823a8ef-b26c-4f12-b95d-f014777e6a68', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 11, '100207891', '一つ屋根の下って、本気 (マジ) ですか?', '支店長･黒川から、会社のサイトに掲載する仕事と生活の密着レポート「やりがいJTCライフ」の連載を依頼される。危険だからやらないほうがいいと話すリカと、自分たちの結婚話が本当なのか確かめる罠ではないかと疑うタクヤ。お互いのアラスカ行きを回避するため、企画を引き受けることにする二人。黒川はタクヤとリカが同居していると思い込んでいるため、二人はタクヤの家に一緒に住むことになる。リカは予想外のことが起こらないようにするためのプランを作成して、一緒に実行するように提案する。', '2024/12/13 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/570cfcfd-a99d-428c-bf12-b913ffd5fbd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60241954-0d14-44ab-ad30-12b78f925185', '5f38af71-c9f7-49dd-aaab-5ebc0cfd151d', 12, '100209368', '結婚するって、本当ですか?', '【シーズン1 最終話】タクヤとリカは順調に「やりがいJTCライフ」の連載を進めていた。ある日、タクヤは権田がアラスカ行きの候補に挙がっていることを知る。自分たちの計画のために、権田をアラスカに行かせてはいけない。ウソの結婚を通して自分以外の人生について考えることができるようになったタクヤは、本当は結婚しないことを黒川に話す。すると、リカも自分たちの結婚がウソだと話していた。そして黒川は自分がアラスカに行くと宣言するのだった。アラスカ行きは無くなった二人だったが、それは同時にウソの結婚計画の終了を示していた。', '2024/12/20 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52343613-b400-4cc7-84eb-4eebcf23a83b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('340796c1-8179-4bea-b237-1f68dc932831', '結婚指輪物語', '', 'hulu', 'tales-of-wedding-rings', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32550453-73f2-4ffb-aeee-7f55f4bc3b1c.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 160389, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('885c1067-8467-4efc-960e-5f5fcdec9318', '340796c1-8179-4bea-b237-1f68dc932831', 'hulu-tales-of-wedding-rings-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce3562f6-bdeb-489d-98f8-2305468230fb.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b8e0f3f-8389-4cde-ae34-8895e8f6a1af', '885c1067-8467-4efc-960e-5f5fcdec9318', 1, '100171007', '第1話', 'どこにでもいる普通の男子学生サトウは、幼馴染のヒメに恋心を告げられずにいた。ある日、サトウはヒメから遠いところに引っ越さなければならないと突然の別れを告げられてしまう。恋心を諦めきれないサトウはヒメを追いかけて彼女が入って行った光のゲートに飛び込むと、そこは日本では無く、アーヌルスと呼ばれる異世界だった!', '2024/01/09 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce3562f6-bdeb-489d-98f8-2305468230fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d490e64-dbee-4a89-a733-3316a84f2250', '885c1067-8467-4efc-960e-5f5fcdec9318', 2, '100171809', '第2話', 'ヒメと結婚し、アーヌルスを深淵王の脅威から救う伝説の“指輪王”となったサトウ。幼馴染から突然夫婦となってしまったサトウとヒメは、気恥ずかしさから今までの関係値から更に一歩前進することが中々できずにいた。しかし新婚生活を楽しむ余裕もなく、指輪王の復活に気づいた深淵王の追手がサトウ達に迫る。', '2024/01/16 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8a6eb26-9875-4e76-8fd5-d538ddf67119.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51db4c79-4e08-49d3-925d-8e9266390aa7', '885c1067-8467-4efc-960e-5f5fcdec9318', 3, '100172639', '第3話', '指輪の姫君ネフリティスと結婚するためエルフ達が住む風の国“ロムカ”にやって来たサトウ一行。しかしネフリティスはその人見知りの性格から、サトウとの結婚を強く拒否してしまう。更にネフリティスの兄ジェードによってサトウはロムカの牢に拘束されてしまうが、彼を助け出すために一人のエルフがサトウの前に現れる。', '2024/01/23 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4edef85-cb6f-4d1f-9f61-66ca7bcf13f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ffd6fec-b44b-4445-a052-b305aa5f6dc8', '885c1067-8467-4efc-960e-5f5fcdec9318', 4, '100173470', '第4話', 'ネフリティスの両親の話を聞き、彼女のロムカを守ろうとする決心が非常に強いものだと認識したサトウ一行。こうしている間にも深淵王の軍勢が迫っていると考えたアラバスタの助言により、サトウ達は一度ネフリティスとの結婚を後回しとし他の国に向かうことにする。しかし時同じくして、深淵王の騎士が風の国ロムカに迫っていた。', '2024/01/30 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12754673-556f-4d76-a7eb-14b2f8ac8a50.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e08c09ca-0939-4969-99c7-5dcaf5ce5dc6', '885c1067-8467-4efc-960e-5f5fcdec9318', 5, '100174107', '第5話', '次の指輪の姫君と結婚するため旅を続けるサトウ一行。しかしヒメはネフリティスに世話を焼くサトウに強い嫉妬心を抱いてしまう。何となく各々の関係がぎこちなくなる中、彼らの目の前に巨大なキャラバンで移動する火の国“ニーダキッタ”が現れた。サトウはその国の姫グラナートと結婚するために彼女に「お見合い」を申し込むが…。', '2024/02/06 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7880761-5101-47f6-8766-b7bb4191cc43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb77e781-0794-4c71-a353-e5ec5a2b4bee', '885c1067-8467-4efc-960e-5f5fcdec9318', 6, '100175066', '第6話', 'サトウはグラナートに「お見合い」と称する剣術の試合で勝利するためマルスと共に練習に励んでいた。指輪王である前にヒメの前ではかっこいい男でありたいと思っているサトウは、強敵グラナートに正々堂々勝負を挑むべきか指輪王の使命を優先するか苦悩する。しかし深淵王の魔の手が、ニーダキッタにも近づいてきていた。', '2024/02/13 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abc4dc25-6fb9-4f78-93e0-1bdda5d6df50.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a1f431f-ceb4-45d4-b9e8-6bb3879eaa2a', '885c1067-8467-4efc-960e-5f5fcdec9318', 7, '100175409', '第7話', '水の国“マーサ”を訪れたサトウは、思わぬところで指輪の姫君サフィールと結婚してしまう。動揺する一行だったが、サフィールは帝国ギサラスに牛耳られる母国を救うために指輪王の力が必要だと考えていた。そんな中、サトウは謎の暗殺者に命を狙われてしまう。またサフィールの双子の妹サフィラも、マルスと浅からぬ関係があるようで…。', '2024/02/20 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0819fd98-5a13-4665-86ce-9faaee9e8685.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ca19751-0dc3-419b-be71-3a60a4bc3a51', '885c1067-8467-4efc-960e-5f5fcdec9318', 8, '100176153', '第8話', '水の国“マーサ”を牛耳る占術師は、かつて指輪王になる使命を帯びながらもそれを遂行できなかったマルスにある助言をする。サトウはマーサに迫る深淵王の魔物を撃退すべく、マルスの兄スリュダーと共に準備を進めるが、彼らの前に現れたのは想像を絶する多さの魔物たちだった。奮闘するサトウの前に、突然ある人物が立ちふさがる。', '2024/02/27 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d0cef2e-9a6e-4e9b-abf8-249af833a9d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92aa1632-9810-4eb6-8b9a-aedaa0d4e727', '885c1067-8467-4efc-960e-5f5fcdec9318', 9, '100176663', '第9話', '“マーサ”に平和が戻り、つかの間の休息を手に入れたサトウ達。サトウはヒメと二人っきりで街にデートに行くことにするが、その後ろをこっそりネフリティス、グラナート、サフィールがついてきてしまう。二人っきりのデートを楽しんでいたサトウとヒメだったが、出発直前にアラバスタから掛けられた言葉が気になってしまい…。', '2024/03/05 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c70e2e7-691d-4742-abe7-a91e8b8619b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e010b59f-ad00-48ad-937e-312e90f3b68a', '885c1067-8467-4efc-960e-5f5fcdec9318', 10, '100177418', '第10話', '“土の国”イダノカンに向かうサトウ一行。しかしイダノカンは先の深淵王との戦いで既に滅び、ドワーフたちも街を去った後だった。指輪の姫君を探すサトウ達だったが、遂にもっとも恐れていた事態が起きてしまう。大量の深淵の魔物に追われ身動きが取れなくなってしまうサトウ達を守るため、アラバスタはある魔法を発動させる。', '2024/03/12 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6d228de-1d9a-4682-a6ad-51135edeead5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('506ed0b2-f083-4641-b4d4-38a00d903ce4', '885c1067-8467-4efc-960e-5f5fcdec9318', 11, '100178212', '第11話', 'アラバスタの魔法によって、サトウとヒメが元々暮らしていた世界に転移されてきたサトウ達。アーヌルスに戻る方法も無く途方に暮れる彼らだったが、新たな生活を続けるうちにヒメの心は徐々に揺れ動いていく。指輪王としての使命を果たせず苦悩するサトウの前に、なんと土の国“イダノカン”の指輪の姫君アンバルが現れる。', '2024/03/19 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1e2ced0-a128-4015-8e74-06e62e95e4c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c7da564-838f-447a-8f6c-03c6212b21d6', '885c1067-8467-4efc-960e-5f5fcdec9318', 12, '100178649', '第12話', '【シーズン1 最終話】アンバルの力を使いアーヌルスに帰還したサトウ達。しかし転移した先のイダノカンには無数のギサラス帝国兵士と深淵の魔物の死体があった。もはやアラバスタもマルスもおらず、絶望的な状況な中サトウは遂に深淵王と遭遇する。5人の指輪の姫君の力を使い、アーヌルスを救うためサトウは指輪王として深淵王に直接対決を挑む…!', '2024/03/26 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/390b9397-1cde-44d4-8240-4732060b6545.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ae4894be-712a-4ddf-a0be-f91a08a7cf15', '340796c1-8179-4bea-b237-1f68dc932831', 'hulu-tales-of-wedding-rings-s2', '第2期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58ca3204-7592-4f9e-9aec-b21dd66a1d5d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcff9cd2-d044-42e2-bcb0-0d0cd35d0fe5', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 1, '100239892', '第13話', '深淵王との戦い後、ノカナティカに戻ったサトウ一行は、ヒメの妹モーリオンと再会する。アラバスタの「花嫁修業」宣言と共に、指輪の姫君たちは自身の魔力とサトウとの絆を磨く修行を開始。ヒメは強力なパワーを持つ光の杖を手にするため、モーリオンの指導を受けながら魔力の感覚を掴もうと励むが――。', '2025/10/07 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58ca3204-7592-4f9e-9aec-b21dd66a1d5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2f64d03-5f3d-4f65-a727-3d46347010ee', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 2, '100240551', '第14話', 'ロムカに到着したサトウ一行は、初代指輪王と深淵王の戦いの歴史について学ぶため、ペリドートと共にエルフの大書庫に入る。かつての謎を解き明かしていくうちに、サトウたちは初代指輪王にまつわる衝撃の事実を知る。そんな中、ペリドートはサトウと指輪の姫君たちがより強力な絆で結ばれるよう、ある作戦を企てていた。', '2025/10/14 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe58e9ad-614b-4a7e-b987-875c2d3045b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('058daac3-9c58-456b-b01c-17187b74cb37', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 3, '100241036', '第15話', 'サトウと姫君たちは、身体を交わらせることで更に強力な力を手にするため、大書庫に閉じ込められてしまった。心に決めたヒメへの想いと、次々に自分を誘惑してくる姫君たちの魅力に揺れるサトウ。しかし、煮え切らない態度を取り続けるサトウにしびれを切らしたペリドートが、ついに禁断の罠を稼働させてしまい…。', '2025/10/21 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc1741a2-d5a7-4ed0-af48-42fb7fb57138.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8065d418-8bd2-4bd4-8104-5faf655bfc45', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 4, '100241535', '第16話', '閉じ込められた大書庫から出るすべがなく、徐々に地底での生活に順応していく一行。そんな中、グラナートはかつて猫人が使っていたと言われる火の魔法を上手く習得できずに悩んでいた。ネフリティスと二人で訓練に勤しんでいると、突如深淵の魔物が現れる。窮地の中、グラナートはサトウにあることをして欲しいと頼む。', '2025/10/28 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9e50eba-76ac-4407-9077-aa67a6386147.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c486b526-1b05-4b15-9424-49c64f2f3166', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 5, '100242444', '第17話', 'モーリオンのアドバイスもあり、ヒメはサトウに対する自分の想いと、他の指輪の姫君たちへの気持ちに整理をつけ始める。世界の危機にあたって、いつまでも大書庫にいるわけにはいかないと決意を固めたヒメは、指輪の姫君たちだけを集めて、女子だけのあるイベントを開催する。除け者にされたサトウは気が気ではなく…。', '2025/11/04 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae092f1e-ffd7-4f42-8614-0a30694c4514.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74770805-a7b8-40d7-bacd-0617b46dbc71', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 6, '100243621', '第18話', '深淵王に対抗すべく、サトウ、サフィール、アンバルは指輪王の剣を求めて帝国ギサラスに残り、ヒメ、ネフリティス、グラナート、モーリオンは魔法修業のため魔導の尖塔へ向かう。初めて離れ離れになったサトウとヒメは、それぞれが決意を胸に使命に向けて動き出す。そんな中、ヒメの前に謎の女性が現れる。', '2025/11/11 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ece1564-7adb-4ab7-be48-97a65a48710f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('201b5a4f-176d-42ed-8f5e-9430a6eabbb5', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 7, '100244437', '第19話', 'サトウたちは深淵王を打倒したと伝わる指輪王の剣を手に入れるため、神話遺物庫への潜入作戦を実行する。しかし遺物庫の入り口を守るゴーレムにサトウの指輪王としての力が全く通じず…。一方ヒメは魔力を急成長させて周囲を驚かせていた。そんな状況を不審に思うモーリオンはこっそりヒメの様子を探るが…。', '2025/11/18 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ea95016-2293-408f-b942-3adef6b21af3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f5ae15b-89d6-427d-9b5a-ec7f75224695', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 8, '100245406', '第20話', '闇落ちしてしまったヒメは、来るものすべてを拒絶する塔の中に閉じこもってしまった。深淵王も時を同じくして大量の深淵の魔物をサトウたちにけしかける。皆が必死に魔物から塔を守る中、サトウは単身ヒメの救出に向かう。しかし、使命と愛の狭間で揺れるヒメは世界平和よりもサトウと二人だけの世界を望んでいた。', '2025/11/25 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/877a6837-f593-4ea7-9200-7c69389eafad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6159f1d7-a8a5-4aca-8b8c-033156aef7b1', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 9, '100246271', '第21話', '「俺は、今度こそヒメを抱く!」闇落ちしたヒメを救うため、今まで我慢してきた彼女への想いを率直に伝えるサトウ。塔の外には強力な深淵の魔物たちが次々と現れ、光の魔法を持たないアラバスタたちは窮地に追いやられる。しかし、想いを通わせたヒメはついに覚醒する。そして、二人は光の中へ入っていき…。', '2025/12/02 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92578c52-cd69-4a51-9916-f8d1f3acb392.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b22e97f-5a40-4cb3-9540-a67751fda1bf', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 10, '100246602', '第22話', '絆を更に深めたサトウとヒメ。そこへ帝国からの使者が現れ、指輪王一行は深淵王との最終決戦に向けて移動を開始する。マルスの兄、スリュダーとも協力し、深淵王の近くまで魔物を避けて進むため、サトウたちはかつてドワーフが作り上げた迷宮隧道を進んでいく。しかしそこには、アンバル出生の秘密が隠されていた。', '2025/12/09 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/137e217a-8d7b-47f1-8c27-3efa0ae93342.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('617bd86c-6524-4fd6-af2c-81593b0ca3f0', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 11, '100247778', '第23話', '深淵の領域に辿り着いたサトウたち。決戦を前にしてヒメからありったけの力を受け取ったサトウは、深淵の領域へと突入する。魔族との激しい戦闘の末、深淵王の居城にたどり着いた一行だったが、指輪の姫やモーリオンたちは闇の力によって分断されてしまった。サトウは一人、深淵王との最後の戦いに挑む。', '2025/12/16 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b98b0ce-d8d0-455c-a112-8101fedbe16d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51cff81b-ebf7-471d-914e-bf27597b324e', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 12, '100248495', '第24話', '深淵の領域にアーヌルスで生きるすべての種族が集まり、深淵王を打倒するため、そして世界を救うために戦っていた。指輪の姫君たちは修行の成果を発揮し、サトウも姫たちとの絆を武器に必死に剣を振るう。しかし、深淵王が仮面の奥に隠していた“真の姿”が明かされた時、新たな絶望がサトウに襲い掛かる。', '2025/12/23 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4630ac18-df72-463b-b0fe-2182b2c9565b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ed9f7b3-b98e-4ea0-89c6-57bd97b2e396', 'ae4894be-712a-4ddf-a0be-f91a08a7cf15', 13, '100249478', '第25話', '【第2期 最終話】深淵に飲み込まれてしまったサトウ。誰もが希望を失う中、ヒメだけは自らの光の力を、そしてサトウの生存を信じ、自ら深淵の中に飛び込んでしまう。果たしてサトウ、ヒメ、ネフリティス、グラナート、サフィール、アンバルたちは、今度こそ深淵王を倒し、アーヌルスに平和をもたらすことができるのか…!', '2025/12/30 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7ddde87-624d-4981-af1b-b4b4ffd0d10f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
