INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('07da28a8-5cc9-4db7-9f9f-30fa491e5f29', '月がきれい', '', 'hulu', 'tsukigakirei', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50029088_series_art__338x600_tsukigakirei_4c7228d4202a23be81499c73fbedf136.jpg?w=331&h=447&p=t', 'hulu', 2017, 2, 1, 'FINISHED', NULL, 100305, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('612dc5b2-ea25-4138-a2aa-9af30679b1d9', '07da28a8-5cc9-4db7-9f9f-30fa491e5f29', 'hulu-tsukigakirei-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/140fa1ba-bb11-4281-bd92-71a9303e854a.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71a6a76a-db33-41ed-9a58-ea66a851ed26', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 1, '60878637', '春と修羅', '小説家志望の文芸部員、小太郎。茜は陸上部で短距離走専門。中学3年になり、初めて知り合った2人。家族と食事に出かけたファミレスで出くわしたり、運動会の用具係で一緒に作業したりが続き、互いを意識し始める。', '2017/04/25 18:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/140fa1ba-bb11-4281-bd92-71a9303e854a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10a30c9b-226a-4995-9da7-e64af7aaa026', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 2, '60878635', '一握の砂', '中学最後の運動会。小太郎はくじ運悪く出走した競走で転倒、保健室で茜の親友･千夏の治療を受ける。千夏の奔放さに気圧されて用具係の仕事に戻ると、最終種目のリレー出走直前だというのに、茜の様子がおかしい。', '2017/04/25 18:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7473cf44-cf4e-4bdf-bf8d-948eb0aef6a3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bbb8cc56-5623-4ea9-a7c2-dd487f6d6a84', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 3, '60878634', '月に吠える', '運動会が終わると次は修学旅行。中3の初夏は浮ついた空気の中、過ぎていく。LINEで連絡を取り合うようになった茜と小太郎。陸上競技会で自己ベストを記録した茜は、喜びに任せて小太郎のいる神社へ報告に行く。', '2017/04/25 18:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/36a30269-3700-423f-b32f-7237cc1d1b06.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36f91c0b-5f49-437b-a049-16100d0a469d', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 4, '60879827', '通り雨', '「少し待って、返事。」戸惑いのままに迎えた京都への修学旅行。小太郎も2人きりになれる機会を作ろうとLINEで待ち合せの連絡を入れるが、茜の返事を待たずにスマホを没収されてしまう。翌日、雨の中待つ茜は…。', '2017/05/02 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1b0738e0-6712-4b12-b371-fcc08c9aeebd.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('daf62277-73ec-4ba7-b005-91bf36a05bd1', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 5, '60883071', 'こころ', '誰も知らないけど、私と安曇くん、付き合い始めましたー。特に理由はないけれど、2人の仲はまだ秘密。でも「つきあう」って何するの? 初めてのことに気持ちは盛り上がりながらも、悩ましい小太郎と茜は…。', '2017/05/09 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/643961ef-eb89-409d-848a-9917b3b980d6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1fdc3c1-6358-4116-8e21-6709502b3f97', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 6, '100000706', '走れメロス', '「私、安曇くんのこと好きになっちゃったみたい」親友である千夏からのメッセージに、部活の大会を目前に控え茜は気もそぞろ。そんなこととは知らない小太郎のもとには、出版社から連絡があり、会いに行くことに。', '2017/05/16 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8034796e-e528-4197-bf75-323efa8b54f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('689b03f7-0077-46aa-9f3d-5116e4e419eb', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 7, '100001857', '惜しみなく愛は奪う', '夏休み。期末試験も終え、千夏の誘いで同級生たちと遊園地へ。交際を明らかにしていない小太郎と茜がぎこちなく同行する中、小太郎への千夏のアプローチにやきもきする一方、茜は比良と一緒に皆からはぐれてしまう。', '2017/05/30 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dd2a077-20ae-41f4-8a3f-e1766ccd923a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40ca65d0-c4e2-410b-98ae-f4f0d77959c5', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 8, '100002248', 'ヰタ･セクスアリス', '「安曇と水野ってつきあってんの?」休み中に遊園地でのことが拡散し、登校日の二人は注目の的。うれしはずかしい空気の中、初めて一緒に帰る約束。小太郎のお囃子の練習に付き合い、二人は夕暮れの川越の街へ…。', '2017/06/06 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ea1dff7-64f6-4ab1-9d7c-6a455be9d4a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8af1c4b1-1fe0-483f-8993-1bb4b079bd07', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 9, '100002676', '風立ちぬ', '中3の秋は進路の季節。のんびり構えていた小太郎もいよいよ、茜との会話にその話題が出始める。そんな中、茜は中学最後の大会へ。こっそり観に来た小太郎の前でのラストランで自己ベストを更新、有終の美を飾るが―。', '2017/06/13 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2635b08b-ffda-458e-a56b-cdbc11a9b72f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9f95864-fd56-43b9-9404-1c523ea082d9', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 10, '100003078', '斜陽', '「引っ越すかもしれない」茜は引越し先の高校の推薦入試を受けることになり、小太郎もその高校を受けると言い出す。動揺の中迎えた川越祭り、陸上部のメンバーと遊びに来た茜は、山車で舞う小太郎の姿に見惚れるが…。', '2017/06/20 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c32599c4-7caa-42f6-8b60-fdaeae5ac8ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bc8df98-e49b-4506-9b41-59c4bf3c9ec0', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 11, '100003318', '学問のすすめ', '茜と同じ高校に行くために勉強を始めた小太郎。だが三者面談の席上、志望校としてその校名を出し、母親と衝突してしまう。気まずい家の中で母親と話すことなく勉強に没頭する小太郎。一方、茜は推薦入試に合格する。', '2017/06/27 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cfbb17bf-a7ec-45d9-b402-e5d031552a8a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0043a13-cd43-43e9-afdf-34b53fbea40e', '612dc5b2-ea25-4138-a2aa-9af30679b1d9', 12, '100003883', 'それから', '【シーズン1 最終話】茜の引越しが近づく。進路は決まったものの、遠距離恋愛の不安が二人に圧し掛かる。茜は引越し荷物に涙を刻み、小太郎は想いを文章に綴る。卒業式翌日、引越し前の最後のデート。同じはずの二人の想いはすれ違い―。', '2017/07/04 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ceadaf90-4518-490b-88b1-6a370238e79a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b05dc30b-51bd-4292-a2e2-fc937d733f87', '月が導く異世界道中', '', 'hulu', 'tsukimichi-moonlit-fantasy', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4deec92a-a641-42b7-982a-a8c5ca126563.jpg?w=331&h=447&p=t', 'hulu', 2021, 2, 1, 'FINISHED', NULL, 125206, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ab31357d-9686-461c-8226-4383272cbd38', 'b05dc30b-51bd-4292-a2e2-fc937d733f87', 'hulu-tsukimichi-moonlit-fantasy-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84fa3da6-47e5-40e6-ae19-38fe97f9946c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21fdd8f2-9a9b-45fe-bc3b-2cb478645f1c', 'ab31357d-9686-461c-8226-4383272cbd38', 1, '100086636', '勇者…失格', 'とある事情で異世界に召喚された平凡な高校生･深澄 真は勇者になる……はずだった。しかし、理不尽な理由で異世界の女神に嫌われた真は、不毛の荒野に放り出されてしまう。途方に暮れ荒野を彷徨う真は、ハイランドオークの少女･エマと親交を深める。しかし彼女が上位竜「蜃」に捧げられる身だと知った真は……。', '2021/07/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84fa3da6-47e5-40e6-ae19-38fe97f9946c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2592c88a-0b04-489b-b03d-82c07ce5a333', 'ab31357d-9686-461c-8226-4383272cbd38', 2, '100086966', '災害の黒蜘蛛', '上位竜「蜃」を相手に有利な立場で契約を結んだ真。蜃が作り出す霧の中の異界『亜空』へと案内される。豊かな土地に恵まれ、女神からも身を隠すことができる『亜空』を、移住してきたハイランドオークと共に開拓する真。一方、外界では永遠の飢えにより正気を失った「災害の黒蜘蛛」が『亜空』へ迫る。', '2021/07/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d8cd897-bd2a-4bcb-b46b-343b5cc11f21.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e039563-59a8-4ae9-bfc9-79dbc2c2dbd1', 'ab31357d-9686-461c-8226-4383272cbd38', 3, '100087271', 'ヒューマンショック', '意識を失っている間に「災害の黒蜘蛛」に契約を結ばれた真。困惑しつつも「蜃」と「災害の黒蜘蛛」に名前を与える。一方、『亜空』にはエルダードワーフをはじめとした様々な種族の亜人が移住し始める。亜人に囲まれ人が恋しくなった真は、ヒューマンの街へと向かう。しかし、そこで真を待っていたのは武器を構えるヒューマンたち! いったいなぜ!?', '2021/07/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37491195-f5bc-48e5-a470-a6d1d6806b83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb173486-7ac4-4767-8342-044ddfac363d', 'ab31357d-9686-461c-8226-4383272cbd38', 4, '100087648', 'あとのまつり', 'ヒューマンの街･絶野で真たちは、行方不明の姉を探す少女･リノンと出会う。その晩、宿で何者かの襲撃を受ける真たち。そこでリノンの姉･トアが借金を理由に捕らえられていることを知る。とある理由で冷静さを失いかける真に代わり、巴と澪はトアの救出に向かう。だが、巴たちの前に一人の男が立ちはだかる。', '2021/08/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/782b00cc-111c-44fc-9b2f-053dc869a269.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b22ec1d3-04cb-4ad2-81a1-7d7bd01ee3af', 'ab31357d-9686-461c-8226-4383272cbd38', 5, '100088038', 'よくばり馬車の旅', '崩壊した絶野の街を出発した真は、トアやリノン、他の冒険者と共に新たな街を目指していた。道中、多くの魔物に遭遇しながら無事、ツィーゲの街に到着した一行。トアたちとの別れを惜しむ真は、最後に打上げを開催する。その最中、真は初仕事を引き受けたレンブラント商会に関する不穏な噂話を聞いてしまい……。', '2021/08/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85b0beb7-7b91-411f-848b-907d53c0e4ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1bdfbebb-d13b-4353-85c7-025272e924be', 'ab31357d-9686-461c-8226-4383272cbd38', 6, '100088701', 'ナイスミドルの憂鬱', 'レンブラント商会の依頼を引き受けた真たち。渡すべき素材は既に手に入れ、冒険者として初仕事は順調かに思われた……。だが冒険者として実績がない真は、商会の主･パトリック=レンブラントから疑いの目を向けられてしまう。さらに商人ギルドへの加入を目指す真を、2つの試験が待ち受ける。', '2021/08/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98994cc0-661a-44e4-b5dd-05e72bae394f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e49d7b53-e078-4c1e-b1cf-0c17879c268b', 'ab31357d-9686-461c-8226-4383272cbd38', 7, '100089217', '秘薬精製', '呪病に侵されたレンブラントの妻子を助けるため、真はハザルと共に秘薬アンブローシアを精製する。その後、妻子に秘薬を飲ませた真は、彼女たちの回復を願いながらレンブラント邸を後にする。依頼を終えた真は、迎えに現れた巴と澪に合流する。そこで3人は、宿から後を付けてきた何者かの襲撃を受けてしまい……?', '2021/08/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c5aa5d0-ac20-49ca-a073-872a02c3c286.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3d1fdc3-7b34-4fa1-8275-7dc3ef1c4aa4', 'ab31357d-9686-461c-8226-4383272cbd38', 8, '100089776', '亜空ランキング', 'レンブラント商会の依頼達成後、『亜空』でのんびり過ごす真だったが、新たな問題が発生する。真たちが訓練指導をしているハイランドオークやリザードマンの戦士たちが自信を無くしてしまったのだ。そこで巴は、戦士の士気を再び高めるべく種族に関係なく全員参加の個人戦「亜空ランキング」の開催を宣言する!', '2021/08/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1f58596-fe7b-433b-a4ba-e1f43e9bc9ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85fb57c2-8c52-407b-b714-7fbf6fbe21a3', 'ab31357d-9686-461c-8226-4383272cbd38', 9, '100090748', '喰うか喰われるか', 'ヒューマンの街にクズノハ商会を設立した真は、お祝いに宴を開いてもらう。『亜空』の住民と親睦を深めた真は、途中で宴を抜け出し弓の訓練を始める。だがそこに取り乱した様子の巴と澪が現れる。突然泣きだす澪に状況が把握できない真。すると巴は信じられない言葉を口にして!?', '2021/09/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cfaa5598-fdf1-493c-bb81-4568dfc3bc0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6d33fe0-ff9d-4259-94f3-b0891d5e1a57', 'ab31357d-9686-461c-8226-4383272cbd38', 10, '100091311', '鬼の隠れ里', 'クズノハ商会にアンブロシアの花を仕入れるため、ティナラクの森を訪れる真と澪だったが、花を守る森鬼のアクアとエリスに襲われる。真は正気を失った澪や、居合わせた冒険者たちに気を取られ追い込まれてしまう。巴の助けにより窮地を脱する真と澪。だが交渉のために訪れた森鬼の村で、さらなる事件に巻き込まれてしまい……?', '2021/09/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/076eb43a-4864-4c6a-8e13-62fa72619c2d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68965310-c802-4713-8b7a-44709114991c', 'ab31357d-9686-461c-8226-4383272cbd38', 11, '100091870', 'さようなら', '『亜空』を襲った謎の爆発、そして倒れる巴。突然の出来事に動揺しつつも、真は怪我人の手当てのため爆心地へと向かう。爆発によって『亜空』の住民に被害が出たことを知りショックを受ける真。同時に脳内に流れ込んできたヒューマンの記憶から、爆発の真相を知る! 身勝手な彼女たちの行いを知った真がとった行動とは!?', '2021/09/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48b7a707-a33c-46fe-8e2b-2c647e2b3d20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1eb88f0-e81f-4a91-ab67-8bc631cb33e7', 'ab31357d-9686-461c-8226-4383272cbd38', 12, '100092123', '月が導く…', '【シーズン1 最終話】真は学園都市へ向けて旅立つ……はずだった。しかし女神によって、ヒューマンと魔族の戦いのド真ん中に転移させられた真。そこでヒューマン最強の冒険者･ソフィア＝ブルガと上位竜の御剣に襲われる。魔族に味方するソフィアたちは、女神の使徒と見なした真に容赦ない攻撃をしかける。最大の危機に陥った真は、最後の力を振り絞り魔法を発動する——。', '2021/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe53a426-5a74-469d-b8ef-aab0f7408e8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5b9a660a-053b-4c7d-b295-5958118f3ac6', '月が導く異世界道中 第二幕', '', 'hulu', 'tsukimichi-moonlit-fantasy-season-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/212a5b4b-2fb8-466e-8919-4535c492680d.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 139518, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('da3f4afb-8aae-4d17-b1da-db162ae7eafb', '5b9a660a-053b-4c7d-b295-5958118f3ac6', 'hulu-tsukimichi-moonlit-fantasy-season-2-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9af83048-34e0-423f-a741-68a011a67307.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('224faac3-d665-4175-9f53-11278dc33969', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 1, '100171405', 'え? 荒城の月?', 'ソフィアたちとの激戦を乗り越えて、学園中央都市･ロッツガルドを目指して旅をする深澄 真と識。道中、ヒューマンが暮らすオビットの街に立ち寄った2人は、一時別行動をすることに。その最中、真はヒューマンの少女･ラナと獣人の少年･エトと出会う。彼女たちは“荒城の月”を名乗る盗賊から故郷のタパ村を守ってくれと街の者に訴えるものの、誰からも相手にされていなかった。そんな2人のことが気になった真は、共にタパ村へと向かい……。', '2024/01/13 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9af83048-34e0-423f-a741-68a011a67307.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20c65fe5-1dc2-490e-a177-ac151c5feffa', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 2, '100172262', '二人の勇者は美男美女', '多彩な才能の持つ女子高校生･音無 響。ひと通りの努力でなんでも出来てしまう人生に退屈していた彼女はある日、勇者として異世界へ召喚される。突然の出来事に困惑しながらもリミア王国へと降り立った響は、ナバール=ポーラーら王国の精鋭たちとパーティーを結成。一同はさっそく魔族との戦いに挑むのだが……。同じ頃、グリト二ア帝国には、もう1人の勇者･岩橋智樹が降り立っていた。', '2024/01/20 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f25b36c5-c022-4861-ab97-b9bab43edb97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1f3106d-1065-4fc2-852f-3287c3e6a0d6', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 3, '100173308', 'ステラ･ウォーズ', 'かつて魔族に奪われたステラ砦。その場所を取り戻すべくリミア王国とグリト二ア帝国は手を組み、魔族に奪還戦を挑むことに。開戦の前日、初対面を果たした響と智樹だったが、智樹の傲慢な態度が災いし、2人は打ち解けられず、気まずい雰囲気になってしまう。翌日、開戦すると入念な下準備の甲斐があり、優位に戦いを進めるヒューマン軍。だが、戦場には勇者たちを陥れる魔族の恐ろしい罠が仕掛けられていた……。', '2024/01/27 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58a3d09b-456c-4e18-8e54-2748f1801a59.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f41f99ad-7366-4370-929f-c5a298fa8806', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 4, '100174106', '僕がどうして先生に!?', '長旅の末、ロッツガルドに到着した真と識。まずはクズノハ商会の新店舗開店に向けて、街の情報を集めることにする。だが、そんな間もなく、2人はロッツガルド中央学園の生徒たちと料理屋で働く少女･ルリアが揉めている場面に遭遇。周囲に冷めた目を向けるルリアのことが気になった真は、彼女を助けるのだが……。その後、真は学園の入学試験に備えるものの、受ける試験が教員採用試験だと判明して!?', '2024/02/03 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37982a02-aa8d-4493-8d95-aac64502d637.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bee6c3de-543b-432f-aa87-c7d689efd9ab', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 5, '100174898', 'それでは授業をはじめます', '見事、教員採用試験に合格した真。正式な採用通知も届き、ロッツガルド中央学園で非常勤講師として働くことが決まる。それから数日が経ち、迎えた初授業の日。真は生徒たちから舐められないよう、憎まれ役を演じることにする。時を同じくして、巴はステラ砦をかけたヒューマンと魔族の戦争中にできた湖･星湖の調査に乗り出していた。その最中、戦争に参加していたというヒューマンの記憶を覗いてみると……?', '2024/02/10 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c97ab58f-82c1-4a63-918c-f3f644ef1dfa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3398de6-c998-4f4e-976f-5c2608bcbc1b', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 6, '100175231', 'めざせ三つ星シェフ', 'ロッツガルドにクズノハ商会の新店舗がオープン。ロッツガルド中央学園での仕事も本格的に始まり、商会経営と教員生活は順調。……かに思われたが、共に新たな問題が真の頭を悩ませていた。一方、星湖周辺の調査を続ける巴とライム=ラテのもとに、智樹やグリト二ア帝国の一行が訪ねて来る。彼らは、巴とライムが持つ刀を珍しがり、譲ってくれるよう頼む。さらに智樹は、巴も手に入れようと、人々を魅了する魔眼の力を使い……。', '2024/02/17 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7854e58c-ff04-444f-bc94-0d8948e379bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e88af01e-b5a9-490c-92e0-a7882d870240', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 7, '100175719', '新メンバーオーディション', '久しぶりに亜空へ帰還した真は、澪や巴たちからサプライズと共に迎えられる。宴が開催され、一同は再会を喜び、楽しい一夜を過ごす。その後、星湖や智樹について巴から報告を受ける真。話の途中、亜空の異常な暑さを指摘すると、巴の口から亜空に関する新たな事実が明らかになるのだった。そして翌日、亜空へ新たに迎え入れる種族を決める“新メンバーオーディション”が開催されるのだが……?', '2024/02/24 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6ebdd04-e785-4d4e-b965-5a72b1c86989.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec713374-36c3-4c61-b609-551ee7e0e36e', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 8, '100176568', '悪い噂の美人姉妹', '亜空で忙しくも楽しい時間を過ごした真。一通り用事を終えた彼は、識と共に再びロッツガルドで仕事に励むことに。まずはクズノハ商会ロッツガルド店に顔を出してみる2人。主が不在の間、アクアとエリスが立派に店番を務め、新店舗の営業は順調? な様子だった。一方、ロッツガルド中央学園では、復学したシフ=レンブラントとユーノ=レンブラント、さらに転入生･カレン=フォルスが新たに真の講義を受けることになり……。', '2024/03/02 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c9f9c6d-d60a-4b01-b63f-a8ce9c9fc3a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5c2d0bc-849b-497d-850d-8a85074aa3a2', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 9, '100177417', '変態ドラゴン', 'ロッツガルドで密かに行われているという人体実験の調査に乗り出したライム。しかしその途中、ロッツガルド中央学園の新開発区画で遭遇した謎の男に挑むも敗北してしまう。さらに、なぜかその場に居合わせた学園の図書館司書･エヴァと共に人体実験を行っている裏組織に捕らわれる羽目に。その後、なんとか脱出に成功した2人は真たちと合流。クズノハ商会に保護されたエヴァは、真の両親や自身に関するとある秘密を打ち明ける。', '2024/03/09 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ae579d0-3b28-415e-9e08-ca216fd1a573.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa6d0784-4d82-4e5e-8a9c-0888ec296969', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 10, '100178211', 'やってみせます世直し稼業', '裏組織を壊滅させるべく、真たちは本格的に行動を開始する。そんな彼らに魔将のロナも協力。一同は首謀者がロッツガルド中央学園の常勤講師･ブライトだとつきとめる。その後、拘束したブライトと対峙する真。会話の途中、目的のためなら犠牲を厭わないと訴えるブライトに怒りを覚えた真は、容赦なく裁きを下すのだった。翌日、真は学園で夏休み前、最後の講義を開講する。少しでも成長したところを見せようと張り切るジン=ロアンたちに、新たな試練を課して……。', '2024/03/16 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/147842d5-b33a-464b-8c7c-adfd10b9c5e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c952305-3a9b-47b5-be85-e17619d6c679', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 11, '100178586', '成長の夏、新技の夏', '夏休みに入ったロッツガルド中央学園。休みを利用して亜空へ帰還した真は、雑務に励んだり魔力の運用方法について学んだりと忙しくも充実した毎日を過ごしていた。そんなある日、亜空の新たな住民、翼人たちと模擬戦をすることに。過去に行われた模擬戦では、負け無しだという強敵を前に気を引き締めて戦いに臨む真だったが……。さらにそれから数日後、巴の提案で亜空の住民たちによる新技発表会が開催されて……?', '2024/03/23 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13af0e7d-305f-4f39-befe-94ed83e7a8c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b54f423c-8783-4506-aac2-ed412a3df43b', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 12, '100179330', '巨獣襲来', '夏の終わりが近づいたある日のこと。亜空の開拓調査をしていたハイランドオークが北方の森で狼と熊に襲われる事態が発生する。その知らせを聞いた真は、2種族と和解をすべく森へと足を運ぶ。だが、そこで対面を果たした熊から敵意と警戒の眼差しを向けられてしまい……。一方、時を同じくしてロッツガルド中央学園の生徒、ジン=ロアンたちは、以前遭遇した際に手も足も出なかった亜竜にリベンジをしようと画策していた……。', '2024/03/30 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d8c17c2-6bcc-4ac1-a0ff-00aa5cdb31cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5248eef-1ddf-4eb7-b81a-2f4e9bb1694b', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 13, '100180168', '学園祭は大忙し', '街をあげた一大行事･学園祭の開催が迫ったある日。女神を信仰する神殿の準司祭･シナイが真のもとにやって来る。急遽、設けられた話し合いの場で、クズノハ商会が販売する薬に関して良くない噂が流れていることを伝えるシナイ。さらに彼は薬の製法を神殿に明かせば噂の払拭に協力することを約束するという。その提案に真は……。 それから数日後、文化祭がスタート。前日、夜遅くまでお店の準備をしていた真は、初日から寝坊をしてしまい!?', '2024/04/06 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/062d788e-2d82-4403-a5c0-8355d8482a22.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('125ce341-ec17-4a21-a47f-4ce70700dfe9', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 14, '100180358', '社交界は苦手です', '学園祭2日目。生徒や来賓が集う立食パーティーに招待された真。慣れない社交の場で時間を持て余していると、ローレル連邦の重鎮･サイリツから声をかけられる。初対面なうえに、魔族を護衛につけている彼女から話しかけられ戸惑う真。一方、サイリツはクズノハ商会の看板に書かれた漢字と、異邦からローレル連邦に伝わった文字が同じであることを告げる。そのことから彼女は真が異世界からやって来た存在ではないかと指摘して……。', '2024/04/13 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb67c077-d017-4497-abec-c717605a2833.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d01a8c92-362b-4513-983a-c95191a2ba7a', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 15, '100182071', '闘技大会、熱戦あまた', '学園祭の目玉イベント･闘技大会の個人戦に挑む真の生徒たち。大会で日頃の成果を発揮しようと張り切っていた彼らだったが、貴族の策略により同門対決を強いられてしまう。そんな中、決勝へ進出したジンは、真に憎悪の眼差しを向けるイルムガンド=ホープレイズと対決する。果たして勝つのは!? その翌日、真は商人ギルドの代表･ザラに呼び出される。そこで、部外者から見れば不審な点が多いクズノハ商会の流通手段について、ザラから問い詰められてしまい……。', '2024/04/20 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e4270d0-000f-4337-af61-4a3144181877.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bc08c37-3720-464f-b514-1a1a4ea3c29c', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 16, '100182630', 'とある生徒の秘密', 'ザラとの一件もあり、魔族に肩入れしようと決めた真は、生徒の晴れ舞台である闘技大会を見届けてから、ロッツガルドを去ることにする。翌日、団体戦の決勝に進んだジンたちは、イルムガンド率いるチームと対峙。試合が始まるとジンたちは圧倒的な実力差で相手を追い詰めていく。そんな中、凄まじい気迫と狂気を放つイルムガンドのことが気になる真。すると一緒に観戦していた巴と澪がロッツガルド全体に蔓延る妙な気配を感じ取り……。', '2024/04/27 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f2bc080-1682-4b1d-beb4-8f3a770a7e91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c838f8a6-e181-44be-8ce5-e936bc888673', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 17, '100183506', '変異体ハザード', '魔族の策略によって怪物、通称･変異体へと姿を変えたイルムガンド。彼を止めるため、攻撃を開始するジンとアベリアたち。だが、彼らの攻撃は中々通じず、かつてない強敵を前に戦意と気力を失ってしまう。同じ頃、街中ではイルムガンドと同じく変異体に変貌したヒューマンたちが暴れ始め、ロッツガルドは未曾有の危機に陥る。そんな中、この事態を収拾すれば街の商人や他国の貴族を見返し、恩を売れると考えた深澄一行は、各々行動を開始するのだった。', '2024/05/04 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/308e33aa-566c-4c13-9161-7fdaa3df8c3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28b468ae-1af3-44ed-80f8-d602486bc202', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 18, '100184068', '学園都市の崩壊', '依然として混乱が続くロッツガルド。変異体との戦いを騎士たちに任せた深澄一行は、他国や街の人々の避難活動に注力していた。そんな中、街や周辺地域に相当な数の変異体が出現。真からそのことを知らされたジンたちが討伐に向かおうとするのだが……。一方、真から避難所の護衛を命じられた澪は、任務の最中に妙な匂いを察知。その元を辿ってみると、肉塊となりながらも自我を取り戻したイルムガンドがいて……?', '2024/05/11 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c69b9379-8f01-4254-a72f-7dd02cc4d8e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dc22d6e-8ca4-4fdf-9921-722b0fda7c7a', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 19, '100184788', '暴れん坊商人', '一向に収束の気配が見えない変異体騒動。避難所では、新たに変異体へと変貌する者が現れ、人々の不安と疲労はピークに達していた。そんな状況を変えるため、深澄一行は変異体討伐部隊へ参加。まずはロッツガルド北東区画へと繰り出し、いとも簡単に敵を倒していく。その後、商人ギルドを訪れた一行はレンブラントやザラと再会。以前、ザラから商人失格の烙印を押された真は、今回も厳しい言葉をかけられると思っていたが……。', '2024/05/18 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8d8ac4c-63e1-4a22-b142-7661e1751ec1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc86e102-e4b9-4d87-a690-5ac2d9be177f', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 20, '100185386', '憎みきれますロクデナシ', '変異体騒動を囮にリミア王国とグリトニア帝国へ進軍する魔族軍。ヒューマン軍は敵の迎撃にあたるものの、戦力不足によりすぐさま劣勢に。2つの大国は陥落の危機に陥ってしまう。そんな中、魔族の本当の狙いが響の命であることを知り、彼女の救援へ向かおうとする真と識。だが、その直前、周囲に転移の手段を失ったと嘘をついたことが仇となり、身動きがとれなくなってしまう。するとその時、神々しい金色の光が真たちを包んで……。', '2024/05/25 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/119de4e7-21cc-4e89-9990-ff8ab53d5dad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a19f09b7-8d3a-48be-ba62-eb3962e60075', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 21, '100186391', '勇者奮戦', '今は魔族領となってしまったエヴァとルリアの故郷･ケリュネオン。その土地の奪還を真から命じられた巴や澪、亜空の住民たちは敵地へ出陣。一同は日頃の訓練の成果を発揮し、見事、魔族軍を蹂躙していく。この勢いのまま、巴たちは亜空の初陣を勝利で飾ることができるのか!? 一方、舞台は少しだけ時を遡ったグリト二ア帝国。戦場へと向かう智樹たちの前に、ヒューマン最強の冒険者にして魔族に加担するソフィアが立ちはだかるのだった。', '2024/06/01 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce8a13eb-30d1-4b12-ae8c-ac70e6ee1a07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('711e1769-562d-4d5c-b728-2a0321a094ac', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 22, '100187054', '戦えヒーロー!', '戦場で対面を果たした勇者の正体が高校の先輩･音無 響だと知り動揺する真。だが、彼女について深く考える間もなく、イオとの戦闘が開始してしまう。戦闘序盤、魔族との無駄な交戦を避けたい真はイオに撤退を提案。だが、敵にその意思がないことが分かると、真は容赦ない攻撃を仕掛けていく。追い詰められたイオは反撃すべく、魂を捧げる代わりに絶大な力が得られる禁断のアイテム･青い石の薔薇 (ローズサイン) を使用する。', '2024/06/08 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78744adc-32be-4ff1-a770-e5b07b38e61a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5125009d-b066-4214-9202-3e11ec16b9ae', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 23, '100187506', '宿敵リベンジマッチ', '真とイオの戦いに突然乱入してきたソフィア。以前から真との再戦を熱望していたソフィアは戦場に降り立って早々、宿敵に猛攻を仕掛けていく。一方真は、彼女の参戦によって数的不利な状況に陥ったものの余裕の表情を見せる。魔力を物質化した“魔力体”を駆使してイオとソフィアを一方的に追い詰めていく……。その頃、リミア王国王都･ウルの城外で魔族を迎撃していた響一行に御剣が放った大量の光剣が降り注ぎ!?', '2024/06/15 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01270aea-4a46-4634-ae79-1bf12255beca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f7cdc24-6dc3-49c4-bbda-c1bc15284060', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 24, '100188375', '魔人VS.竜人', '識と御剣による激戦が繰り広げられるリミア王国の王都城外。戦闘序盤、力を取り戻し完全体となった御剣に若干押され気味の識……。だが、事前にルトから御剣に関する情報を得ていた識は、敵に有効な攻撃を次々と放ち、あっという間に形勢を逆転する。その頃、城内では真とソフィアの戦いが続いていた。圧倒的な実力差により為す術を失いつつあったソフィアは、二匹の上位竜を葬ったという奥の手を繰り出す。魔人･クズノハVS竜人･ソフィア、決着の時!', '2024/06/22 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bcae88ce-3d9a-42ce-b6e8-fe157c4d0a33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82682087-ae1c-4236-8e6d-a806ddd4c8d8', 'da3f4afb-8aae-4d17-b1da-db162ae7eafb', 25, '100188949', '月下祭宴', '【シーズン2 最終話】リミア王国での激戦を終え、亜空へ帰還した真。すると彼のことを巴や澪、亜空の住民たちが迎え入れ、一同は戦果や被害状況を報告しあうことに。その場は慌ただしくお開きとなってしまったものの、真は久しぶりに仲間たちと共に過ごすのだった。翌日、再びロッツガルドを訪れた真たちは変異体の残党を一掃。数日間、街の人々を苦しめた変異体騒動に終止符を打つのだった。一方その頃、リミア王国に身を潜めていたソフィアのもとに、彼女が探していた最上位の竜･万色ことルトが現れて……。', '2024/06/29 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c46cce55-3a51-4636-adfd-ad16ebe21ab9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('70fe2a00-7fc0-40a8-86e0-59084a055c4f', '月刊モー想科学', '', 'hulu', 'gekkan-mousou-kagaku', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7dbf0142-26c4-4813-af42-f29d215309d1.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 169418, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('481a865d-e6b1-443f-8668-849a5a62323b', '70fe2a00-7fc0-40a8-86e0-59084a055c4f', 'hulu-gekkan-mousou-kagaku-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9776885c-65c9-493b-adcd-d05657b4aaa7.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e1b428f-5aee-489c-8038-9dbc00d9c617', '481a865d-e6b1-443f-8668-849a5a62323b', 1, '100171839', 'も～、びっくり!? タローの変身?', '『月刊モー想科学』は科学では解明できない不思議現象を扱う月刊誌。編集部で働くのは、夢は寿退社で専業主夫希望のタローと、IQ高めの少し生意気な少年ジロー、そして犬のサブローの3人。ある日、サイエンス研究所の研究員ゴローが自分の研究を取り上げてもらうべく現れるのだが、タローはゴローの背後に『あるもの』が見えてしまう。実はゴローは伝説の大陸･モー大陸の存在を信じ、研究を続けていた。そんな彼と関わることでタロー自身にとんでもないことが起こるのであった。', '2024/01/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9776885c-65c9-493b-adcd-d05657b4aaa7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('768f5199-a6d5-4468-b5e1-c7a91e3c43d9', '481a865d-e6b1-443f-8668-849a5a62323b', 2, '100172261', 'も～、お前! 何勝手に働いてんの?', '一連の事件で研究所を除籍になってしまったゴローは編集長キャサリンに誘われ『月刊モー想科学』編集部に加わる。やる気満々のゴローは、早速獣人に変身したタローをネタに記事を書こうとするが、どうやらタローには変身中の記憶がない様子。そこへ、高校生達がテニス部の合宿中に光る井戸を発見したとネタ提供に訪れる。タローは嫌々ながらもジロー達と現場へ向かうが、そこで怪しい謎の二人組に遭遇。どうやら二人はゴローの持つモーパーツを狙っているようで……。', '2024/01/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0575685b-5595-4815-978a-d145047d4844.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a3f764d-3795-41a4-b599-fcada06c8ba3', '481a865d-e6b1-443f-8668-849a5a62323b', 3, '100173305', 'も～、止まらない!? ミュージカル口調……!?', '結婚相談所から初めてマッチングしたとの連絡を受けウキウキのタロー。嬉々としてデートへ向かうが、ジローはタローがデートに行くのが気に入らない様子。初デートは人気舞台『トミオとオムレット』の鑑賞だったが、主演俳優のハナノスケが演技中に突然ミュージカル口調になってしまい、舞台は台無しに。キャサリンの指示で彼を取材しに行くと、なぜかある時から無自覚にミュージカル口調になるようになってしまったらしく……。', '2024/01/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/226a7a24-4e22-4358-8534-916afa01a607.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28f408e2-62c2-4e9c-9c4b-052515e47e16', '481a865d-e6b1-443f-8668-849a5a62323b', 4, '100174104', 'も～、不思議!? ヌス湖の秘密', '来月号のネタ探しが難航するタロー達は、ゴローの提案でヌス湖に現れる未確認生物のヌッシーを探しに行くことに。ヌス湖が若い男女の出会いの場となっていると聞くと、タローもノリノリに。一同は早速キャンプ道具を持って湖に向かうが、実はパーチとノインにつけられていた。一方で、そんなことは知る由もないタロー達は湖に到着。しかし、そこは閑散としていて、聞いていた話とは全く違う場所だった。すっかりやる気をなくしたタローだったが、湖のほとりで美しい女性に話しかけられる……。', '2024/02/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/86a294fd-b63c-4fe2-8a32-b52d5aa46b23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('968eac4a-20d9-411f-ba3e-d068cd9a4a02', '481a865d-e6b1-443f-8668-849a5a62323b', 5, '100174897', 'も～、ナニ悩んでるの? 氷上の貴公子', '仮面をつけた男が深夜の高速道路を高速で駆け抜けている! ――という情報を掴んだゴローだが、タロー達は相変わらず全く興味を示さない。仕方なくゴローは一人で取材へ。入替りに喫茶『岩』にフィギュアスケートの名コーチ･ロベルトがある依頼をしに現れた。彼の教え子である若手ホープのリョーマが毎夜こっそりどこかへ出かけており、しかも翌朝はかなりやつれた様子に。どこで何をしているのか本人にただすも無断外出はしていないと答えるのだった……。', '2024/02/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf96cf93-db3d-41b9-9b9e-a2209e2a92ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c2d8f26-42e1-498a-a239-915e84f71aab', '481a865d-e6b1-443f-8668-849a5a62323b', 6, '100175230', 'も～、なんで? ここが猫のたまり場!?', 'タロー達は、猫アレルギーのモテ男でモデルのジョニーから近所の猫のたまり場を何とかしてほしいと依頼を受ける。「うちは便利屋じゃない」と断るタロー。しかし、偶然訪れたキャサリンの命令で、仕方なく調査に向かう。現場はジョニーの家の目の前。誰かが餌を置いている様子もない。一同は猫が集まるという深夜に出直すことに。その帰り際、ゴローの提案でずっと気になっていたホワイトペガサス社の偵察に向かうことになったのだが……。', '2024/02/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31400cd3-af9c-405f-9285-e754b50a9e88.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ec66e78-10ae-4e6a-99cd-1e33d1e34e1d', '481a865d-e6b1-443f-8668-849a5a62323b', 7, '100175715', 'も～レツ!? お見合いパーティ', '超VIP限定お見合いパーティが開催されることに。早速、自らも参加し、夢の逆玉専業主夫を目指すタローだが、年収が参加条件に達しておらず門前払いを食らってしまう。だが、なぜかその後急に参加を認められたタローはゴローと共に会場の豪華客船へ。早速、受付を済ませ、自己プロフィールカードの記入を悩んでいると、お見合いパーティ参加50回目のレジェンドに声をかけられる……。', '2024/02/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d49ae02-2862-4321-a551-2e22ad6fb416.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bef37f6a-3f0c-4f36-9ee2-c489c71d77e7', '481a865d-e6b1-443f-8668-849a5a62323b', 8, '100176566', 'も～犬 (ケン)! 犬も歩けばモーに当たる', '犬の散歩が男女の出会いの機会になる! ――そう気付いたタローは、早速、犬のサブローを連れて公園に散歩へ。しかし、愛犬家同士の密な会話に全くついていけず、肩を落として編集部へ戻ると、編集部宛にドッグコンテストの招待状が! 実はこのコンテスト、ホワイトペガサス社が仕組んだ罠だった! そうとも知らず、サブローがやたらと参加したがる為、仕方なく会場へ。着ぐるみを着たパーチとノインが何かと罠にはめようとするが無意識に罠を回避するタロー達だったが……。', '2024/03/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/116fb145-963b-4cb6-85a8-2de93b52eb8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb3fbd82-2ffe-4bad-8cd1-0fda9f922195', '481a865d-e6b1-443f-8668-849a5a62323b', 9, '100177415', 'も～、謎だらけ! 天才少女の過去', '――15年前のこと。サイエンス研究所の研究員に最年少で博士号を取得し、世間からの注目を浴びていた天才少女がいた。彼女の名はフォー･チュン。エドワードはかつて彼女の助手を務めていた。そんな彼の協力もあり、フォー･チュンの研究ははかどり古文書の解読に成功する。その古文書が示していたのは、伝説の大陸･モー大陸の存在であった。そして、彼女はモー大陸の研究結果をマスコミの前で発表するが……。', '2024/03/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f429f7e4-9e92-4805-9f94-c7fd483b6a74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77da3dd0-025e-4d51-99f6-24e116082a9a', '481a865d-e6b1-443f-8668-849a5a62323b', 10, '100178208', 'も～、イヤだ! ケンカで大陸浮上!?', 'モー大陸を浮上させるには残り3つのモーパーツが必要だった。ゴローは何としてでも手に入れようと考えるが、そこへなんとキャサリンが残りのモーパーツを持って現れた。ゴローは驚きながらも好奇心から彼女を疑問に思うことなくモーパーツを受け取ってしまう。早速モー大陸を浮上させようと焦るゴロー。しかし、タロー達は「おかしいことだらけだ」と反論。両者は言い合いとなり、タローは店を出て行ってしまう……。', '2024/03/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8ec726f-359d-4d9b-ba15-39df5e1e9b92.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68abd8e1-00f6-44ea-8c24-1d917c708048', '481a865d-e6b1-443f-8668-849a5a62323b', 11, '100178584', 'も～、聞いてないよ! キャサリン!', 'モーパーツが全て揃い、とうとう海に沈んでいたモー大陸が浮上した! タロー達はサブローの案内で秘密の地下通路からモー大陸へ。感動するゴロー、懐かしさを感じるタローを尻目にモー大陸の王子であった時の記憶を完全に取り戻したジローは、慌てた様子でかつての居城へと向かう。タロー達もジローの後を追って駆け出していく。そこでタロー達の目に飛び込んで来たのは長きに渡り闇に包まれていたモー大陸の謎……そのすべてが今、明らかになる……。', '2024/03/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f85035f7-2e25-42c0-9c51-b13ad6c6901f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04c15db5-7874-4911-b988-46c935a9443e', '481a865d-e6b1-443f-8668-849a5a62323b', 12, '100179329', 'も～、この世は奇想天外!', '【最終話】人類消滅装置『ラ･モー』の起動スイッチを押してしまったフォー･チュン。人間のエドワードとゴローはすでにその姿を失い始めており、人類消滅の時間が刻一刻と迫っていた! もはや止める手段はないかと思われたが、「一つだけ方法がある」とジロー。その方法とは――『モー大陸を消滅させる』というもの。しかし、ジローは肝心のその方法が分からない。果たして、『ラ･モー』を止められるのか? そして彼らの運命は?', '2024/04/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afd96fdb-5036-46b0-b874-77b00b513f54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('419b1c23-1c07-4950-9395-72222846fe87', '月面兎兵器ミーナ', '', 'hulu', 'mina', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50022999_series_art__338x600_mina_f4bedc067c6db48e1dcdf62a73fbf542.jpg?w=331&h=447&p=t', 'hulu', 2007, 0, 1, 'FINISHED', NULL, 1865, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2b2426e5-5ea7-4092-b9e9-284e301a8eeb', '419b1c23-1c07-4950-9395-72222846fe87', 'hulu-mina-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f08f1a3a-ad2a-49d5-96ea-f7cebd980c35.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d80aa8d8-49c1-4899-bac4-9784dd9a631c', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 1, '60606599', 'はじめての汁実', '美奈は下町に住む平凡でちょっとドジな女子高生。しかし憧れのルナテレビのアナウンサーオーディションに見事合格したことで、高校生でありながらアナウンサーという二束のワラジを履くことに。スポルナに初出演する美奈だったが、初回から大失敗を喫してしまう。しかし、結果的に高視聴率を生んだ美奈は、早速プロ野球のスーパースター、二階堂選手のインタビューを受け持つことになる。だが、そこでは宇宙人による二階堂選手乗っ取り事件がまさに行われようとする瞬間であった…。', '2015/09/17 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f08f1a3a-ad2a-49d5-96ea-f7cebd980c35.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb07f2dd-1c45-4421-99ea-8d4da150bda5', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 2, '60606597', 'プロレス大好き', 'スポルナで待望の自分のコーナーを持たせてもらうことになった美奈。プロレスについてのレポートをまとめるため、居残りで作業することに。そして本番となりレポートを読もうとする美奈だったが、六棟の悪戯により原稿がすりかえられてしまったのであった。', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/77148560-12ab-419e-8fa6-28c144cc4064.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b94cc796-e23e-4f0c-ac76-5ba44f60f06e', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 3, '60606605', 'やくそくの魔球', '美奈の幼馴染の寛治は、美奈がスポルナに出ていることが気に入らない。そんな兄を不思議に見る妹のナコル。ある日、美奈は番組で高校野球の取材をすることになる。しかし、取材現場は寛治がピッチャーを務める母校の野球部だった。', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/09200321-efcc-4205-8fd3-663625aded31.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d0e37c4-6b70-49bb-99f3-3ce941eed485', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 4, '60606603', '六棟大ブレーク', 'ルナテレビで毎年行われている夏イベント「うめたてルナフェスタ」が開催し、美奈も参加することに。そこで美奈は、甲州翠怜と組んでビーチバレー大会に参加することになる。優勝者にはトロフィーが授与されるのだが、またもや宇宙人の影が…。', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b3e64ce0-036a-4ed8-bc2e-96f8308846db.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f2ec798-9458-41cb-9c02-f9d2b1e80e1c', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 5, '60606598', 'ミーナに赤札 (レッドカード)?', 'やっとミーナの任務に慣れてきた美奈。今日も任務を終え女子高生の姿に戻る、がその一部始終を見ていた謎の影が…。ある日、スポルナの特別ゲストに人気子役の小鳥遊由宇がやってくる。彼女は美奈の正体をほのめかすような発言をする。', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/211068e7-066b-4593-9572-2697e153eb4f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e88bb2dd-9e32-4155-b2b8-4178891fa243', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 6, '60606604', '露天風呂のソコ', 'ラグビーの代表合宿が宇宙人らしきものの被害に遭う。真相を解明するため、美奈は桐生と組んで温泉郷に取材へ行くことに。しかし美奈は、ほのかに恋心を抱く桐生のことを意識するあまり仕事に集中できないでいた。', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a3be6295-379a-4282-9830-2204327ae973.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('006e76f4-3fd6-4047-b70b-ad3f34daa09c', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 7, '60606601', '翠怜先輩の不倫', '翠怜アナウンサーにある球団監督とのスキャンダルが発生する!! しかし美奈は信じることができない。事の真相を確かめようと、美奈は証拠写真を撮ったと噂される一人のパパラッチに接触を試みるのであった。', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/18a12ffb-8833-488e-8b58-cbb973470fb5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b00a4c7a-8790-4ddc-8aff-7da562f3da37', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 8, '60606606', '不機嫌なナコル', '寛治はすっかり国民の人気者となった月城ミーナが気になって仕方がない。そんな兄の様子を見たナコルは『月城ミーナなんてどこがいいの!?』と機嫌が悪い。ところがある日、ナコルの目の前で寛治が宇宙人にさらわれてしまう。', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/073652bc-6c55-4cd9-b28b-c7350cb79912.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f80a7171-5152-41e7-b744-5a71749e32ff', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 9, '60606595', '高度千粁 (キロメートル) の死闘', '指定したポイントに集まらなければ正体をばらすという宇宙人からの脅迫状がミーナたちに届く。UFOに集まったミーナたちは宇宙人の執拗な攻撃を受ける。彼女たちは無事地球に帰ることはできるのか?', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e1556c0d-ebc1-4e7e-bf43-6c35f47f6817.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee472255-4e75-432d-a464-b2e49183908f', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 10, '60606594', '宇宙から来たヨ', '大月ミーナは大活躍、しかしその破天荒ぶりからやり過ぎの声が聞こえ始める。今日も宇宙人を倒したものの公共物を破壊してしまった。そんな中、美奈に謎の人物が近づく。彼女は大月ミーナこそ地球人の敵だと訴えるのだが。', '2015/09/17 12:00:00', 1385, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f2f6da4e-ad56-49e1-99b2-f4c1d23d2a68.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2847005-07fd-400a-bed5-90af46653cbe', '2b2426e5-5ea7-4092-b9e9-284e301a8eeb', 11, '60606602', '最終 (ラスト) アナウンス', '【シーズン1 最終話】師走ミーナの陰謀により、スポルナは存続の危機に立たされた。世間が師走フィーバーに沸く中、美奈は己を信じてカメラに向かう。ミーナかスポルナか、それは自らの内にあるミーナとアナウンサーの狭間で揺れ動く気持ちを代弁する。', '2015/09/17 12:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d08a6bce-29cd-4228-ad01-85c50f7f2204.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
