INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3a4184ba-553d-42de-96c0-3db4361bfe04', 'b885921b-414e-43f2-aa12-23f72b7a0ec7', 'hulu-mieruko-chan-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71757a13-862f-4c88-be3e-c84049736b4f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c8c82fd-80b8-4c44-a29a-14534e001b7d', '3a4184ba-553d-42de-96c0-3db4361bfe04', 1, '100093664', '見える?', 'なんの変哲もない女子高生･四谷みこの日常。通学し、授業を受け、帰宅し、弟と怖いテレビ番組を観たり。そんなみこに、ひたひたと忍び寄る影。それはなんの前触れもなく、突如みこの視界に入り込んだ。最初は気のせいかと思った。幻覚だと思った。疲れているだけと思おうとした……しかし『それ』は確かに見えている――。', '2021/10/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71757a13-862f-4c88-be3e-c84049736b4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb61056e-f4f2-4ff1-bfa7-ea1018dafabe', '3a4184ba-553d-42de-96c0-3db4361bfe04', 2, '100094260', '超見える', 'ヤバいやつらはどこにでもいる……街、学校、友人の背後。やつらは至るところに存在している――そしてほとんどの人は『見えない子』。親友のハナもそのひとり。みこに見えるものが、ハナには見えない。見えない故の能天気が、見えるみこを思わぬ事態へ巻き込むことに……みこはそれでも『見えない』フリを貫き通せるのか。', '2021/10/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c56a2b19-96e8-48b1-9390-030a46801b3c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2af5624-b7df-41f3-b517-d0c6f46ec1e8', '3a4184ba-553d-42de-96c0-3db4361bfe04', 3, '100094615', 'まだ見える', 'ヤバいやつらは人にも憑く。ハナを始め、誰かにまとわりついていたり。やつらがどうして存在するのか、何をしたいのか……『見える子』に目をつけ話しかけてくるやつすらもいる。気づかれ、話しかけられ、ズンズン寄ってくる……さすがに危険を感じたみこは、数珠を買いに行くことに。', '2021/10/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cc8ac6a-fba6-4988-a81b-9d9a21b080f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68e5eaea-7f4b-44f2-85d2-3b0217385752', '3a4184ba-553d-42de-96c0-3db4361bfe04', 4, '100095207', 'やっぱり見える', '下町のゴッドマザーの数珠効かず……ヤバいやつらにも色々いる。大きいやつ、小さいやつ。強そうなやつ、弱そうなやつ。比較的、怖くなさそうなやつを見つけたみこ。不用意にも『それ』について行ってしまい……そんな日々の『見える』生活に疲れ始めているみこの様子に、弟の恭介が何かを察知したようで――。', '2021/11/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/355b03c7-6447-4a26-8a85-61865db96d85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48e49834-df7a-41a2-a198-63b6785c632a', '3a4184ba-553d-42de-96c0-3db4361bfe04', 5, '100095490', 'ワタシも見える', 'ゴッドマザーに弟子入り志願し、弟子を自称する、みこの同級生･二暮堂ユリア。彼女は、みこと同様にヤバいやつらが『見える子』だった。『見える』ことに孤独を抱えるみこと、『見える』ことに誇りを持つユリア。ふたりの『見える子』が邂逅したとき、運命は動き始める……のかもしれない。', '2021/11/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f07d9461-a5c6-4c8e-bf9f-7d01e8c0c440.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4ffac0b-7edd-4958-81da-95365b51b89f', '3a4184ba-553d-42de-96c0-3db4361bfe04', 6, '100095856', 'スゴいの見える', 'ヤバいやつらは普通『見えない』。その方が幸せなようにも思えるが、『見えない』が故に危機に陥ることもある。不穏な空気、まことしやかに語られる噂。そんな状況があってなお、その場所に足を踏み入れるのは、彼女が『見えない子』だから……心霊スポットと名高い廃ビルにハナが足を踏み入れてしまったのも、つまりはそういうこと……。', '2021/11/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/852e55b2-c9ec-4191-8c29-1e252ad929b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('301ae577-09b6-4155-9c72-3d879d8ee24e', '3a4184ba-553d-42de-96c0-3db4361bfe04', 7, '100096288', '見た?', 'ヤバいやつらは写真にだって映り込む。ただし、それを見える子と見えない子がいたりもする。『少し見える子』である二暮堂ユリアは、体育倉庫での屈辱を晴らすため、再びみこたちに近づく。ちょうどハナがインスタントカメラにハマっていることもあり、ユリアは、みことハナのふたりを有名な心霊スポットでの撮影に誘い出すことに成功するのだが……', '2021/11/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d1a9c73-6017-46e4-b59a-c1a43dae9858.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f29e184-5e04-4114-ac7a-d2fe2bd9bc6c', '3a4184ba-553d-42de-96c0-3db4361bfe04', 8, '100096960', '見えてるもの', 'ヤバいやつらの行動は摩訶不思議。なにをしているのか、なにが目的なのか、皆目見当がつかない。だからこそ恐ろしい……まして見えている子には。ヤバいやつらを徹底的にスルーすることで、難を逃れてきたみこ。しかし、弟の恭介と買い物に出かけた際、どうにもこうにも無視しきれそうもないヤバイやつに遭遇してしまい……', '2021/11/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6ed31e7-e0d9-4ec9-bd56-0074c51f1de3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d493b8e3-5f05-49a5-bf08-65faee64439b', '3a4184ba-553d-42de-96c0-3db4361bfe04', 9, '100097568', '見たことある', 'ヤバイやつは特定の『人間』の側にもいる。それが偶然なのか、目をつけられたのかは分からない……ただ、ヤバいやつらを引き連れるように彼らは常に一緒にいる。産休の担任に代わって、新たに赴任してきた教師･遠野善。彼はかつてみこたちに仔猫の里親として名乗り出た人物だった。そして、そのときと変わらず、善の周囲にはヤバそうな猫の化け物の姿が……。', '2021/12/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c79ad35-d2b4-4681-a445-d03058a8d221.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e075601a-892b-4109-a879-8af161e00d9c', '3a4184ba-553d-42de-96c0-3db4361bfe04', 10, '100098104', '見るな', '現実世界にだってヤバそうな『人間』はいる……猫の化け物を引き連れた新担任の遠野善。善の周りで日々増えていく猫の姿をした異形……相まって街の野良猫は次第に減り、善の手に付着した赤黒い血――。更には猫の化け物だけでなく、善の側には見るからにヤバいやつまで現れて……。本当にヤバいのは異形の存在の方か、それとも……', '2021/12/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35792d79-0581-4fe5-8247-743356bedcdc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('672ff3f4-53cb-4dfa-8da8-c46cbfbb1cfd', '3a4184ba-553d-42de-96c0-3db4361bfe04', 11, '100098633', '見る?', '現実世界でヤバそうな『人間』を尾行する。それは、とてもとても危険な行為。相手は同じ世界で生きる『人間』。時には現実に危害を加えられることも…。それでもみこは、善の後をつけることを決意する。善を取り巻くヤバいやつらが、ハナを弱らせているであろうことは明白。向こう見ずな勇気を振り絞り、みこは単身、ヤバそうな『人間』と対峙することに――。', '2021/12/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4f6868d-94fd-4e0b-a5d7-d0c1e7295bd7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ceebda35-5ecb-4016-b756-d88d185eb719', '3a4184ba-553d-42de-96c0-3db4361bfe04', 12, '100099491', '見える子ちゃん', '【シーズン1 最終話】みこの勇気に端を発した行動により、善への誤解は氷解、更に善に取り憑いた異形の存在たちも消え去った。怖がるだけでなく向き合うことで現状が変わる――みこの心にも少し変化が訪れた模様で……。見えないだけでヤバいやつらはどこにでもいる――ほら、貴方の隣にも。しかし、正しく向き合い対処すれば、どうにかなる……かもしれない。', '2021/12/27 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd0cbf2a-336d-436d-bcd6-ab6420de686b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5d07ff5c-ab8a-4037-a51a-7efc3e607a74', '賢者の孫', '', 'hulu', 'kenja-no-mago', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6713a0b-1f8d-413b-bc21-483c306f9688.jpg?w=331&h=447&p=t', 'hulu', 2019, 1, 1, 'FINISHED', NULL, 100112, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b5eab956-3e27-43d1-994d-d7809e9b4cbb', '5d07ff5c-ab8a-4037-a51a-7efc3e607a74', 'hulu-kenja-no-mago-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30204da3-f37b-4011-80b0-082576054d40.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dff3e161-0969-4d34-be49-366b201cd7ea', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 1, '100034073', '世間知らず、王都に立つ', '事故で死んだはずのサラリーマンは、なんと赤ん坊として異世界へと転生する。そこで賢者･マーリンに拾われ、「シン」と名付けられる。賢者たちに育てられ、規格外の魔法を操れるようになったものの、なんと常識を教えられていなかった! 森を出て買い物すらしたことのない15歳。そんな世間知らずのシンは、友人を得るため、そして常識を身につけるため高等魔法学院に入学することになる。', '2019/04/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30204da3-f37b-4011-80b0-082576054d40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a324f41c-83cd-4fb7-a217-4e3f02bffa00', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 2, '100034418', '常識破りの新入生', 'いよいよ迎えた入学試験日。会場には、アールスハイド王国の王子･オーグやシシリー、マリアの姿もあった。実技試験では相変わらず、桁違いの力で周囲を驚かすシン。他の受験生は身振り手振りとともに呪文を唱えるが、シンは無詠唱で魔法を発動させ、さらには大爆発を起こす始末。圧倒的な力の差により、なんと入試首席で入学することとなった。さてこれから、楽しい学園生活が幕を開ける―と思いきや、いきなり問題発生!?', '2019/04/25 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dfe2203-6e4e-4eae-bee5-2a4acc907df7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b5a4ba0-bb6f-4c57-bb66-7a86f59e8586', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 3, '100034726', '緊急事態発生!', '護衛のため、シシリー、マリアと一緒に登校するシン。授業初日は、先生の案内のもとSクラスの皆で校内を見学することに。するとオーグから、研究会を立ち上げてはどうかと、提案を受ける。急な事態に戸惑うシンだが、そんなシンを差し置いて盛り上がるSクラス一同により、「究極魔法研究会」を作ることになった。一方、最近様子がおかしいカートは、中等生のころ怪しい先生の研究室に通っていたとか…。', '2019/05/02 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93c4c8fd-126d-4343-84ea-0bf93c146844.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2854be56-3920-4d70-b770-b8ab42eaf817', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 4, '100034727', '黒幕の名は', '数十年ぶりに現れた魔人を撃退したシンを新英雄と讃え、歓喜に満ち溢れる民衆たち。しかし、直接魔人と戦ったシンは違和感を抱いていた。まさか“人為的”に魔人化が行われているのではないか…。一方、学院では「究極魔法研究会」への入会希望者が押し寄せていた。そして、新たにマークとオリビアが仲間に加わることとなった。シンは武器の新調のため「ビーン工房」へと向かうが、その途中で眼帯の男と遭遇する…。', '2019/05/09 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb7dbde3-498f-4be4-bcf7-5674e43cefc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('decd7250-eb82-4742-aa35-a5a333039851', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 5, '100035250', '破天荒な新英雄', '新しい武器を開発するため、ビーン工房へ向かうシンたち。しかし、どこか浮かない表情のシンは、先日のシュトロームとの戦いで起こった謎の爆発について考えていた。シンの魔法では爆発が起こるはずがなく、あれはシュトロームが目をくらますために行ったもの。つまり彼がまだ生きていることを意味していた。シンは再び事件が起こる前に、皆のレベルアップを図り、戦いに備えることにした。', '2019/05/16 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72e3ead4-b4b9-4a8f-b72f-8e27273415eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfeda11b-8087-485b-90e6-1f68c42de241', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 6, '100035788', '開戦と合同訓練', 'アールスハイド王国との国境付近まで進軍したブルースフィア帝国軍。そこには、いるはずのない王国軍が待ち構えていた。部下から聞いていた情報と違い、怒り心頭に発するヘラルド皇帝。すると、帝都に大量の魔物が出現したとの一報が入り、急いで引き返す帝国軍。しかし、すでに街は変わり果てていた。獅子やオラウータンといった災害級の魔物に襲われ、あたりには血まみれの死体が散乱し、まさに地獄と化していた。', '2019/05/23 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49b79afb-ef61-4506-832a-594c857fd7a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad5de5c8-4f93-4f1b-9ed8-bdb798d52217', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 7, '100036071', '合宿に行こう!', '森の最深部で合同訓練を行うシン達の班は、騎士学院生と協力し熊の魔物討伐に成功。ようやく剣と魔法の連携の重要性が分かってきたようである。ある日、オーグから魔人の新しい情報を聴く。現在、魔人たちはブルースフィア帝国領内の町や村を襲撃し、さらには人々を魔人に変えているという。勢力を拡大し続けているシュトロームに対抗するため、究極魔法研究会のメンバーは強化合宿を行う。', '2019/05/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99202572-8c97-4f73-8aa2-7ccb44c9b4d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4259cb1-6c34-47cf-9564-a3b4ee55bc9a', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 8, '100036555', '星空の誓い', 'クロードの街で合宿を行う究極魔法研究会。マーリンは魔力制御を、メリダは魔道具制作を指導し、2人の協力のおかげで着実にパワーアップしているメンバーたち。しかし、圧倒的な勢力の魔人を相手に戦うには、まだまだ力が足りない。シンも負けじと新魔法の練習を行う。皆が警戒する中、イメージを膨らませ魔法を放つが、またまたやらかしてしまうのであった。そしてオーグに後押しされ、遂にシンはシシリーに…!', '2019/06/06 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/443434df-c89f-4ada-ad17-c7d1df79f5c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9faec37-6439-4fec-86a4-eec5e21840d2', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 9, '100036825', '孫と魔道具と婚約披露', 'ある朝、シンはシシリーに“大事なこと”を頼まれた。それは両親への交際の報告であった。緊張した面持ちでクロード邸へと向かい、挨拶をするシン。するとシシリーの母から、貴族の娘であるゆえ“その先”、つまり結婚を覚悟してもらいたいと告げられる。まだ付き合い始めたばかりのシンは、果たして何と答えるのだろうか…。一方、マーリンとメリダもシンから報告を受けると、何やら固い表情をしてある所へ向かった…。', '2019/06/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca576be0-cfbd-43ba-a391-e57dab103975.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00ab27c6-19dd-4739-a1bb-efa9c2098b84', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 10, '100037131', '滅亡する帝国', '平民たちまでも次々と魔人化させたシュトロームにより、ブルースフィア帝国はとうとう滅亡へと追い込まれてしまった。今まで貴族たちに虐げられてきた元･平民の魔人たちは、唐突に強大な力を得たことにより世界征服へと乗り出そうとする。しかし、帝国の殲滅という目的を果たしたシュトロームは、生きる意味を見失っていた。そして、自らの過去を語り始めるのであった…。ついに明らかになる、シュトローム魔人化の秘話…!', '2019/06/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/324a320c-db2d-4299-bd22-653de05c376c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e841f238-0f6b-4028-800c-623d7e2b94be', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 11, '100037411', '史上最強の魔法師集団', 'スイード王国に魔人が出現したとの一報が入り、浮遊魔法で空を飛び、急いで救援に向かうアルティメット･マジシャンズ。しかし、王国の城壁はすでに破壊され、敵は城内に侵入していた。子どもを抱いた母親をもてあそぶ魔人。シンはそれを見つけるとすぐさま駆け付け、ドロップキックをお見舞いするのであった。他のメンバーは、魔人との戦闘は未経験のため気を張り詰めていたが、彼らの力は圧倒的に強かった!!', '2019/06/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce5c032a-76bc-4fd4-bb3e-d894fcb675ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bae6958d-e482-4e5f-bcdb-a2b386423118', 'b5eab956-3e27-43d1-994d-d7809e9b4cbb', 12, '100038259', 'そして、世界へ…', '【シーズン1 最終話】魔人との戦いで傷を負った兵士たちに治癒魔法をかけるシシリー。負傷者の数が多く、疲労の色が浮かんでいた。その時、城門の辺りで大きな爆発が上がる。なんとミリアが加勢したのである。アリスとリンが全力で立ち向かうも、これまでの魔人とは桁違いの強さで苦戦を強いられる。そこに、バイブレーションソードを手にしたシンが駆け付け、激闘が始まるのであった! 果たしてどちらが勝利するのか…!', '2019/07/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4aa1fbbd-3529-439b-a147-66da58e49319.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5df09984-1fa0-44ab-bf37-80a4e0a523db', '賢者の弟子を名乗る賢者', '', 'hulu', 'she-professed-herself-pupil-of-the-wise-man', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb80230d-5e87-48f0-953d-d0b820790b3b.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 119056, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('de73161b-1582-498b-a71d-63d71d5ba71a', '5df09984-1fa0-44ab-bf37-80a4e0a523db', 'hulu-she-professed-herself-pupil-of-the-wise-man-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bdfede01-e692-4c2e-9f98-b07de0c8ddba.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f140a744-f450-4d27-8254-5c66bb167d44', 'de73161b-1582-498b-a71d-63d71d5ba71a', 1, '100101604', 'わし、かわいい……', '無限の可能性が広がるVRMMO『アーク･アースオンライン』で、召喚術を究めたプレイヤー･ダンブルフ。彼は仲間と建国したアルカイト王国の最高位「九賢者」として目覚ましい活躍を見せていた。この日も国王の臣下としてのロールプレイを楽しみながら、魔物討伐のクエストに挑むのだが……。ゲーム内に大きな異変が起こる。', '2022/01/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bdfede01-e692-4c2e-9f98-b07de0c8ddba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03e7dd64-f776-4be5-a5d2-a23c453d845d', 'de73161b-1582-498b-a71d-63d71d5ba71a', 2, '100101986', 'わし、ウソついた……', 'アルカイト王国に帰還し、ゲーム内のフレンドであり国王のソロモンに再会するミラ。ロリっ子姿を盛大にいじられながら、この世界が大きく変質したことを知らされる。もはやゲームではなく、現実であった。ミラはダンブルフの弟子を名乗って生きることを決意するが、それは女の子として生きていくということでもあり……!?', '2022/01/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9699300-b7c0-48e3-90bc-dc132987c290.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e4f3880-0724-4fb2-8338-a9f703764c3b', 'de73161b-1582-498b-a71d-63d71d5ba71a', 3, '100102700', 'わし……こういうのに弱いんじゃよなぁ', 'アルカイト王国と周辺国との不戦条約の期限が近づいていた。国を守るためには、九賢者をできる限り集めなくてはならない。ソロモンから九賢者を探し出す依頼を受けたミラは、九賢者の一人と関わりの深い古代神殿ネブラポリスへ向かう。道中で出会った冒険者たちとともに、ダンジョンを攻略することになるのだが……。', '2022/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d06135d9-b5da-4277-a38e-1bed07eda090.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da951722-6751-46ec-88db-4036fd6f3773', 'de73161b-1582-498b-a71d-63d71d5ba71a', 4, '100103616', 'わし、もう限界!', '暗丞の間の用事を済ませ、ミラたちはダンジョンの奥深くを目指すことに。白亜の城へたどり着くと、ミラは秘密の用事があると言って一人で奥へと進んでいく。実は、何かが限界に達しようとしていて……!? そして、ミラは王の間でソウルハウルの秘密に触れるのだが……そこへ大きな脅威が近づこうとしていた。', '2022/02/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43af766f-ba5e-43bc-9b06-fa0a4d4bc958.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df0a02cf-a89e-493c-b91f-71a6957a1974', 'de73161b-1582-498b-a71d-63d71d5ba71a', 5, '100104121', 'わし、再･誕!', 'カラナックは黒煙を上げて燃えさかり、街にはゾンビがあふれ出していた。ミラはヴァルキリーシスターズを召喚し、ゾンビたちに対抗しようとする。だが、そこへ黒い霧に包まれた人影が現れる。かつてダンブルフですら苦戦したという半魔族が復活を遂げようとしていたのだ。アルフィナはミラに新技の使用許可を求めるが……。', '2022/02/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9e536eb-cdc8-4aaf-a51b-34f2e13472a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1ee3322-d449-47fc-a1db-2596654f3c1c', 'de73161b-1582-498b-a71d-63d71d5ba71a', 6, '100104766', 'わし、着せ替えっ!', 'アルカイト王国へ帰還する途中、ミラは人間に襲われたという風の精霊に出会う。その傍らにいた猫の式神には思い当たる節があった。アルカイト王国へ帰還してからも、ミラには多くの難題が残っていた。ソウルハウルの研究資料の解読、悪魔の暗躍について……。さらには侍女たちに新しい服を何度も着せられることになって……!?', '2022/02/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95ca241e-f815-4073-93f1-6dae42bc5c13.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7c48d0b-8742-420a-819d-c698d5d767aa', 'de73161b-1582-498b-a71d-63d71d5ba71a', 7, '100105233', 'わし、最強!', 'ソウルハウルに繋がる手がかりを探るため、ミラはアルカイト学園の地下にある「愚者の脅威の部屋 (フール･ザ･ヴンダーカンマー)」を目指す。だが、召喚科の教師ヒナタに出会ったことで、学科対抗の術技審査会に出場することになってしまう。万年最下位の召喚科の名誉を回復しようと意気込むが……術のエンタメ化と超優秀な生徒に対応できるのか!?', '2022/03/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/968af930-1854-4673-ac40-08ac40247d60.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cce081e2-08d4-4f14-981a-fcb0cd0740d8', 'de73161b-1582-498b-a71d-63d71d5ba71a', 8, '100105892', 'わし、ダンブルフ', '「愚者の脅威の部屋 (フール･ザ･ヴンダーカンマー)」にヒナタもついてくることになった。ヒナタはミラとクレオスに自分の召喚術を見てもらおうと、自ら魔物に立ち向かっていく。一方、ミラとクレオスはそんなヒナタに手本を見せながら、その極意をレクチャーするのだが……。この迷宮には力業では切り抜けられない、複雑なギミックが待ち構えていた!', '2022/03/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66d92632-8108-4245-ad66-7f4af18d01b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bda6b144-9fd5-4cf3-80b8-dfe459b71a3b', 'de73161b-1582-498b-a71d-63d71d5ba71a', 9, '100106714', 'わし、こういう展開嫌いではないのぅ', 'マリアナとの楽しいひとときも束の間、再び冒険の旅に出るミラ。次なる目的地は、「祈り子の森」の御神木。道中の砦でひと休みしようとするが、砦は半壊状態だった。この地域には存在しないはずの魔物が出現したといい、重傷者も出ていた。ミラはここでも世界の異変を感じ取り、魔物を追いかけようとするのだが……。', '2022/03/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eeadbcba-f180-43b3-bd9d-25935472c3c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('620d3d58-949d-4884-a969-b3aa132a5f03', 'de73161b-1582-498b-a71d-63d71d5ba71a', 10, '100107307', 'わしっ、全裸っ!', '「天魔迷宮プライマルフォレスト」に通じる湖畔にやってきたミラ。召喚したペガサスに動物たちが集まり、初めて出会う超絶かわいい生き物に大興奮! しかし、いつまでも遊んでいるわけにはいかず……。目的地の密林でソロモンから依頼された素材を集めていると、複数の魔物が出現。さらに、不審な人物に遭遇する。', '2022/03/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c42e959-061e-4832-8e94-2e8229d36991.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7020da11-94df-4054-abd1-179b3bcc4078', 'de73161b-1582-498b-a71d-63d71d5ba71a', 11, '100107770', 'わし……褒められてなくないか?', 'ハンターズビレッジに立ち寄ったミラは、そこでセロ、エメラ、フリッカに再会。キャラバンの護衛をしている彼らと情報交換をすることになった。九賢者の一人に関係する、とある街の話を聞いていると、後続のキャラバンが魔物に襲われたとの報せが届く。ミラも救出に加わるが……深い霧に包まれた森に迷い込んでしまう。', '2022/03/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3cbe8ca3-e43b-4d28-ac00-237e9c56b029.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c01424ac-e855-4922-afc0-d15ce65aabba', 'de73161b-1582-498b-a71d-63d71d5ba71a', 12, '100108639', 'わし、参上!', '【第1シリーズ 最終話】アルカイト王国内にかつてない規模の魔物の群れが発生。30年前のクエストの記憶が甦るソロモンだが、今回は九賢者が揃っていないという絶体絶命の危機にあった。休暇中のルミナリアも戦場に立ち、ソロモンも出撃を考える中、さらなる魔物の群れが出現する。窮地に陥るアルカイト王国。果たしてミラは間に合うのか!?', '2022/04/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2537b91-9711-4ae0-8219-6d5c40ff0125.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2d92c1ae-fc9c-4e7a-9e76-fd733339accd', '幻想三國誌 -天元霊心記', '', 'hulu', 'fantasia-sango-realm-of-legends', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ddbabebd-32e1-48c4-96ce-5dac3110a266.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 137247, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b6821115-5d5b-46a2-ac83-46f53797711f', '2d92c1ae-fc9c-4e7a-9e76-fd733339accd', 'hulu-fantasia-sango-realm-of-legends-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45d5b87d-b5af-4746-ba45-7180af2c8a0c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2a24116-4aa6-4d21-9d2f-21ffb561707b', 'b6821115-5d5b-46a2-ac83-46f53797711f', 1, '100098876', '魎狩隊', '人々の昏い心を糧とする存在、魍魎! 戦乱の世の中で、魍魎はおおいに蔓延っていた。三国の歴史を駆け抜ける幻想の物語が今、幕を開ける!', '2022/01/11 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45d5b87d-b5af-4746-ba45-7180af2c8a0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54fad23f-4fab-43f3-9c3f-9d791ca24013', 'b6821115-5d5b-46a2-ac83-46f53797711f', 2, '100100504', '鬼斬抄', '黒き鬼女と化した小霊の苦痛を抑えることに成功し、次なる事件の調査に向かう應幾たち。しかし魍魎を見つけることができない中、小霊がひとり姿を消してしまう――', '2022/01/18 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0ff7076-15ee-40a8-9448-0a5d9fca1928.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0caef696-bd34-4c87-bc3e-490f720dbec8', 'b6821115-5d5b-46a2-ac83-46f53797711f', 3, '100101611', '連環計', '暴れまわる凶馬。惨状を目の当たりにした小霊は、瘴気の力を暴走させてしまう。果たして應幾は、小霊を闇の中から救うことができるのだろうか!', '2022/01/25 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/836a65e7-a5fe-4897-97de-83fea1faad38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb207745-2a78-44c5-936c-ef1c3a9ad1e9', 'b6821115-5d5b-46a2-ac83-46f53797711f', 4, '100102225', '義兄弟', '乱世に名高い、桃園の義兄弟がついに姿を表す。魍魎に憑かれた弟を止めるため、兄は青龍偃月刀を手に一騎討ちに赴く。――神州中原最強の義兄弟が、今刃を交わす。', '2022/02/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dcb73ba5-803e-4a00-b8f4-ee94f29ac8ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd5d1d46-517f-48b7-b7b0-5a6f9f46dd5d', 'b6821115-5d5b-46a2-ac83-46f53797711f', 5, '100102826', '裏切者', '丁研の元に、かつての仲間、旧六番隊が現れる。小霊への復讐を成そうとする旧六番隊に迫られた丁研が出した答えとは。', '2022/02/08 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae07eff8-95af-437f-96e6-c6a9a21bfaae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cf8c338-b0be-4a0d-924a-7520dea21515', 'b6821115-5d5b-46a2-ac83-46f53797711f', 6, '100103706', '呪心臓', '戦いの最中、瘴気を吸い過ぎた小霊は意識を失ってしまう。小霊の呪いを解くため、應幾たちは冬裳の師、良元の元へ向かうが、待ち受けていたのは、残酷な真実だった。', '2022/02/15 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e4a8b54-d7d4-4a14-ab62-55f7ef7f0c5a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a128b44e-b6bf-4e82-8b14-9a4a96d6239a', 'b6821115-5d5b-46a2-ac83-46f53797711f', 7, '100104319', '決死行', '應幾たちの前に、最強の魍魎が立ちはだかる! 絶対絶命の危機の中、應幾は果たして小霊を守り切ることができるのだろうか!? 二人の逃避行が今、始まる。', '2022/02/22 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c13c6b1-58d6-4a03-8b33-5d83a94ed814.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e986b6d-5e0e-401c-af07-960479e96cf4', 'b6821115-5d5b-46a2-ac83-46f53797711f', 8, '100104836', '鳳凰教', '人々を死に至らしめる恐ろしき病、死血病! 霊薬を求める洵喬に出された条件は、「魍魎狩りをやめる」というものだった。弟を救いたい洵喬の決断はいかに。', '2022/03/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66a582cc-c2ad-4a08-89b1-62b264d66f7c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f540ac4-2b0f-499b-98cf-75706e44d902', 'b6821115-5d5b-46a2-ac83-46f53797711f', 9, '100105343', '悲愁譜', '教団の中が蘇った屍の群れで溢れ返る! 小霊を助けるため、急ぐ洵喬の前に僵屍鬼に成り果ててしまった弟が立ちはだかる。小さな楽園に、美しき鎮魂歌が今、響き渡る!', '2022/03/08 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12572530-bc94-488c-90c2-eeb3cbd2fd6c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1462fb3-2a6a-4b2f-82d8-dae60f5f9c85', 'b6821115-5d5b-46a2-ac83-46f53797711f', 10, '100106093', '鬼哭澱', '険しい戦いの中、ついに結束した六番隊! ひとときの安らぎの中で、小霊を守る決意を新たにする應幾。しかし、そんな二人を残酷な悲劇が襲う。――應幾が、意識を失い倒れてしまった。', '2022/03/15 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2264dcb7-486d-401e-a8e7-d6b28fa00076.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70ea66aa-8634-4a90-841a-5b2307250aa3', 'b6821115-5d5b-46a2-ac83-46f53797711f', 11, '100106844', '魎魔宮', '應幾を救う為、瘴気を吸う小霊。何とか應幾は助かるが、呪心臓を瘴気で満たされた小霊を、冬裳が奪って行ってしまう。小霊を救いに向かう應幾たち。そこに、魍魎王が現れる…。', '2022/03/22 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/007bb09c-46aa-4c6e-b1e3-b41153f99331.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0154fcdf-1ecc-4bc0-a3d3-c1d8ded4fc24', 'b6821115-5d5b-46a2-ac83-46f53797711f', 12, '100107406', '魍魎姫', '【最終話】魍魎王に小霊を奪われた。小霊の呪心臓と融合する魍魎王は、嘆きの扉を開き、全土へ魍魎を放つ――。小霊との絆を武器に六番隊は最後の戦いに挑む。4人の運命は!?', '2022/03/29 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6518ce7-854e-4b41-a7c0-d5f3993880dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('43a6bebf-cd4c-4d9a-842c-d2f7078ff18b', '源氏物語千年紀Genji', '', 'hulu', 'genji-monogatari-sennenki-genji', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb9cc3fc-de33-49a2-a716-0c5908e68c54.jpg?w=331&h=447&p=t', 'hulu', 2009, 0, 1, 'FINISHED', NULL, 5155, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('55c89dbf-34a6-42ee-8b1d-0d763473cf7c', '43a6bebf-cd4c-4d9a-842c-d2f7078ff18b', 'hulu-genji-monogatari-sennenki-genji-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ac77537-4643-406c-a988-b1d4b20db21c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6afe69d7-31c5-4966-b687-17a4f96dbe70', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 1, '100143302', '光る君', 'いづれの御時にか――。平安時代の宮廷に、「光る君」と称され、人々に愛された御子がいた。帝の第二皇子でありながら、臣下として源氏姓を受けた光源氏その人である。源氏9歳の頃、亡き母･桐壺の更衣の面影を持つという藤壺の女御が、帝の新たな妻として後宮に入内する。5歳年上の美しい少女に、源氏は運命を予感する。だが、間もなく源氏は元服することになり、宮中のしきたりによって、藤壺と会うことは叶わなくなってしまう。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ac77537-4643-406c-a988-b1d4b20db21c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f48b3617-4b5a-43de-8e96-898dd93ebbc3', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 2, '100143303', '六条', '幼い日の恋心は秘められたまま、17歳となった光源氏。気位の高い妻･葵の上と心すれ違う日々の中、葵の兄で親友である頭の中将から、当代一の貴婦人と呼ばれる六条の御息所の噂を聞く。源氏は嵐の中を六条へと向かい、学問の教えを請う。御簾ごしに交わす緊張感あるやりとり、その手ごたえと高貴さに圧倒され、たびたび通うようになる。同じように六条の御息所もまた、我知らず強く源氏に惹かれ、その訪れを待ちわびる……。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9c84740-db96-4256-acf7-48fe13cfbf29.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27645de6-6509-44c4-ba09-160d1840879f', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 3, '100143304', '夕顔', '光源氏は、六条の御息所との逢瀬を重ねる毎に、その美しさ、情の深さに溺れていく。しかし同時に重くも感じるようになっていた。そんな時、町の白い夕顔の咲く家に住む女性と文を交わしたことから、新しい恋がはじまる。自分の名も明かさず、源氏の名も知りたがらない、ただ逢える事が幸せと言うその女性に源氏は癒され、「夕顔」と呼んで愛しむ。だがそんな幸せも、長くは続かなかった。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d06bd833-f247-4086-aa6c-51cfb0afd10d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fbe2e327-959f-4298-bc13-35ad91e1dc0d', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 4, '100143305', '藤壺', '夕顔を失った光源氏は、心身の病で内裏への出仕も出来なくなる。父･桐壺帝は源氏の長患いを案じ、見舞いを送るよう藤壺の女御に促す。藤壺からの見舞いに付けられていたささやかな手紙に、かつて封印した想いが甦る源氏。ようやく快方の兆しが見えた頃、源氏は北山の寺へ祈祷を受けに行くことに。そこで、藤壺に生き写しの幼い少女に出会い、ますます想い人への心が強くなる。やがて都に戻り、出仕を明日に控えた夜――。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5a90468-a9ad-4ba1-9441-67cf154ac43c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a6d9033-581a-4f15-b6f7-25c73e5ac4a2', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 5, '100143306', '宿世', '禁忌を犯し、父帝の妻である藤壺と想いを遂げた光源氏。罪を背負って愛し続ける決意をする源氏だが、藤壺はこれ以上の罪を重ねまいと拒む。二人の恋は誰にも知られぬまま消えるはずだった。しかし、天の定めた宿命は過酷なものだった。藤壺の懐妊――。何も知らない帝は喜び、藤壺をいたわる。実家に宿下がりした藤壺と密かに再会した源氏だが、藤壺から最後の別れを言い渡される。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f28a280-8c15-4e5e-94c8-e4e88ecbb510.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67474a01-b36d-4098-8eb0-d67098b72a99', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 6, '100143307', '朧月夜', '生まれた若宮は光源氏に生き写しだった。帝は、若宮を次の春宮とし、源氏にその後見人を命ずる。それはいずれ若宮が帝となり、源氏が最高位に立つ事を意味していた。臣下に下った身でありながら、思いがけず開かれた出世の道。だが後にそれを阻むきっかけとなる妖しい出会いが訪れる。朧月の夜、源氏のもとへ扇を落とした、明るく奔放な姫君との幻のようなひととき……。姫君は、政敵である右大臣家の六の君だったのだ。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ac99152-958b-4f31-9173-73c668795b84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dde8c88e-7b3d-4ffd-945f-866b86832de9', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 7, '100143308', '葵の上', '光源氏の父･桐壺帝は退位し、藤壺を伴って御所を去った。愛する人の消えた御所で佇む源氏に、正妻･葵の上の懐妊が知らされる。噂は広まり、源氏の訪れを待ちわびる六条の御息所は想い乱れていた。初夏になり、源氏は新帝となった兄･朱雀帝より都の祭礼「葵祭り」の勅使を任命される。源氏の晴れ姿を一目見ようと、人々や貴族達の車が押し寄せる。六条も、身分を隠し忍んで来ていた。そこへ、後から現れた葵の車と出くわしてしまい――。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d0e6ee6-9476-495c-aeb8-ad6a7b3f168d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e15e8e4e-1a39-41bd-92b6-968555b6309a', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 8, '100143309', '嵯峨野', '葵の上の突然の死は、光源氏に耐え難い悲しみを与えた。産まれた子供･夕霧を鎹に、これからやっと夫婦になれると考えていた矢先の不幸。求めても求めても手に残らない虚しさに、源氏は打ちひしがれる。しかも、葵にとり憑き命を奪ったのは、六条の御息所の内なる魂……。それと悟った六条は、都を離れ、源氏と別れて、伊勢の斎宮となる娘について嵯峨野の野々宮へ行く決意をしていた。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/138c76ae-d994-4f44-8132-4834521f005e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b50b6a33-9cdf-4900-8430-5c0112de3fc3', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 9, '100143310', '叢雲', '六条の御息所が伊勢へと旅立ち、光源氏の元から次々と大切な人が去っていく。そして、また一人……。父帝である桐壺院の崩御。そのことによって、政敵である右大臣家は急激に勢力を伸ばし始め、源氏の身辺にも危うい流れが押し寄せてきていた。それは源氏が後見人を務める春宮の立場をも脅かすことでもある。藤壺は、母として春宮を守るため、そして院への裏切りの罪を自ら罰するために、ある覚悟を決める。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40599d45-ca70-4636-9d88-38a036e35526.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75810121-b45b-4e74-a25c-a4ee491e6997', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 10, '100143311', '謀叛', '光源氏は朧月夜と危険な逢瀬を重ね、ついに右大臣に知られる事となってしまう。弘徽殿の女御はこの機に源氏を失脚させようと、朱雀帝への謀叛の意ありと、流刑を提言する。朱雀帝は受け入れず、朧月夜の心が自分に向く時を静かに待つと言う。だが、噂は尾ひれをつけて瞬く間に世間に広がり、源氏への風当たりは増していく。さらに追い討ちをかけるように、源氏と藤壺の密通の疑惑が持ち上がり……。', '2023/06/25 00:00:00', 1360, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e8311bf-9c22-44b4-8f56-ba42cfcc4f6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6bbd89e1-b664-4f59-a673-8d4e74d16829', '55c89dbf-34a6-42ee-8b1d-0d763473cf7c', 11, '100143312', '若紫へ', '【最終話】光源氏は、自ら都を離れ、流刑地である須磨へ行くことを決意する。それが、愛する者たちを守る唯一の手立てだった。幼い頃から傍に寄り添っていた若紫は、連れて行ってほしいと涙で訴える。いつの間にか少女から女性へと成長していた若紫の真剣な想いを受け止め、妻として待っていて欲しいと言う源氏。若紫は「紫の上」となり、二人ははじめて結ばれる。別れの日は迫っている。しかし、必ず戻る約束をして、源氏は旅立つ。', '2023/06/25 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/123c40db-1f9a-400b-8466-783bda989bce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7f96ef5b-7d14-48ba-88f9-032a798da420', '現実主義勇者の王国再建記', '', 'hulu', 'how-a-realist-hero-rebuilt-the-kingdom', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef21b5ca-19a5-4af7-b130-fb677a4ef061.jpg?w=331&h=447&p=t', 'hulu', 2021, 2, 1, 'FINISHED', NULL, 117612, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('aa28c34a-0668-4c49-9775-8b05a3fe48b8', '7f96ef5b-7d14-48ba-88f9-032a798da420', 'hulu-how-a-realist-hero-rebuilt-the-kingdom-s1', '現実主義勇者の王国再建記 第一部', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1b1da9f-a636-4944-878c-a01fa37e6dab.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('934365ef-8d5d-4ad9-a2dc-e15c5b677c65', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 1, '100140686', 'まず勇者より始めよ', '相馬一也は勇者召喚の儀式によってエルフリーデン王国に召喚された。アルベルト王はその資質を見抜き、彼に王位を譲るとともに娘リーシアとの婚約も決めた。現代知識を駆使して挑む王国再建記がここに始まる。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1b1da9f-a636-4944-878c-a01fa37e6dab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0742ba2-185a-43d5-944b-f119ba6eab7b', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 2, '100140687', 'ただ才あらば用いる', 'エルフリーデン王国の財政は苦しく、ソーマは輸出用の綿花中心の農業から食料増産に方針を変え、まず人民の暮らしの安定を図る。だがまだまだ問題は山積み。解決のためには人材不足が否めず、ソーマは広くこれを民間から募ることにした。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6a0e0ec-9b78-4458-89d4-71cfc3ab32c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a995ff25-0bb7-4cc6-8222-950bea7736b4', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 3, '100140688', '臣をして忠臣たらしむことなかれ', 'ソーマの「ただ才あらば用いる!」の一言で、国中からさまざまな人々が集まってきた。ダークエルフのアイーシャ、美貌のジュナ、怜悧な頭脳を持つハクヤなど多才な者たち。しかし、ソーマが一番高く評価したのは、食いしん坊のポンチョだった……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c826af5c-fd59-4ef2-b82d-0db9f435d348.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea234858-0dcb-44f3-80b3-4d260ea13d9a', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 4, '100140689', '食指、動く', '集まってきた人々の中に、妖狼族の少女トモエがいた。彼女のもたらした情報は、ソーマたちに衝撃を与える。一方、ソーマの命を受けて国中を回ったポンチョは、今まではあまり顧みられることのなかった「食材」を各地から集めてきた。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/867f58e9-3c34-4a78-b086-1da79fd3fdd4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46941704-cf0a-4ec0-a20d-e6e63d4232af', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 5, '100140690', '衣食足 (た) って、栄辱を知る', 'ポンチョのもたらした新しい「食材」は衝撃的ではあったが、美味さと手軽さゆえに瞬く間に国民の間に広がっていった。多忙な日々がつづくある日、ソーマは婚約者のリーシア、ダークエルフのアイーシャとお忍びデートすることに……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4616771-9c50-4a20-8b9b-05087f8c4d9e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88feb8ba-5c57-4e0a-9932-58039f93e8a6', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 6, '100140691', '智者は時にそむいて利を捨てず', '革新は常に反発をもたらす。軍を統べる三公とソーマは対立状態にあり、若い士官の中にはゲオルグの下にはせ参じようとする者もいた。そんなひとりハルバートとソーマは街で出会う。そして翌日、彼の父グレイヴがもたらした情報とは……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff7222e4-44a4-4387-836e-fad529bea505.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27aaa07d-1ac1-437f-a0b2-f46ce8c4d3b8', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 7, '100140692', '古老、曰く', '王国の財政は官僚たちの努力もあって危機を脱しようとしていた。ソーマは新しく港湾都市ヴェネティノヴァを建設する計画を打ち出す。将来、流通の要となり、新たな雇用と住宅を生み出すはずだった。しかし、これに一人の古老が反対する。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09c8310c-6397-4769-9939-821fbc67ffdc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46da8e41-db13-4559-b80a-b6041e8a582c', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 8, '100140693', '森、鳴動す', 'アイーシャの故郷である神護の森に未曾有の危機が訪れる。長雨で地滑りが起き、集落の半分が飲まれたというのだ。被災者の生死を分けるといわれる72時間の壁が迫る中、ソーマたちは必死の救護活動に挑む。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce2fa2ee-1fd1-4f79-8aa6-f22d8fdb8d92.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd96269d-a608-4fe2-b663-34f26a69b8a6', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 9, '100140694', '縦横、成らず', 'ソーマはついに三公との会議を開き、最後通告を出す。自分に従うか、さもなくば戦か。エクセルは恭順を示したが、残るゲオルグとカストールは戦いの道を選ぶ。さらにその混乱を突くように、隣国アミドニアが兵を動かした。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c8def2f5-deb9-4aa1-b601-7a4f791c1bd4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45a8a69c-5b61-415d-86bc-7301910b5201', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 10, '100140695', '兵は楽しむ所に非 (あら) ざるなり', 'アミドニア軍は、エルフリーデン王国の城壁都市アルトムラを包囲し、開城を要求した。領主ワイストは城内の意見をまとめるのに、一両日の時間をもとめる。一方、ソーマはカストール率いる空軍との戦端を開かざるを得なくなり……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a2172a8-e82d-44cb-a0c1-9d457ed15090.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6438b38-e131-4b15-9fd2-9a1a23f38b68', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 11, '100140696', '李代桃僵 (りだいとうきょう)', 'アルトムラを包囲するガイウス八世は笑う。もはやエルフリーデン王国は落ちたも同然と。だが、ソーマたちはカストールの空軍を奇襲で破ることに成功。さらにゲオルグたちの陸軍とも交戦を開始したのである。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6dbd2c36-4671-4520-a5bc-4ec6e38d9cda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fa7039d-f51c-45fa-b982-9680b404dc0c', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 12, '100140697', '囲師には必ず闕 (ひら) く', 'ソーマは、だれもが予想していなかった策を講じる。アミドニアの首都ヴァンの前面に兵を進めたのだ。ガイウスは必死で軍を走らせ、故国を敵の手から守ろうとする。そして、ついに両者はヴァンの平野でぶつかりあう!', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daecd351-95f2-46b1-bf07-1d9796e9f1cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76a00905-1504-4780-a5d2-eccecbb41ff9', 'aa28c34a-0668-4c49-9775-8b05a3fe48b8', 13, '100140698', '百戦百勝は善の善なる者に非 (あら) ず', '【第一部 最終話】ヴァンを制圧したソーマは、ヴァンもまたエルフリーデン王国のように自由な街に作り変えていく。その陰で笑うガイウスの娘ロロア。そして、ついに人類宣言の盟主グラン･ケイオス帝国が動き出そうとしていた……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cdb68d5-a3c0-49f8-9ca6-12ca6dc62ee4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fb300f1e-028d-461e-a079-f1b0bbcfb00e', '7f96ef5b-7d14-48ba-88f9-032a798da420', 'hulu-how-a-realist-hero-rebuilt-the-kingdom-s2', '現実主義勇者の王国再建記 第二部', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c7ed06c-8af2-41ec-8092-3a42747fdf6f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f780d945-6901-4c0c-a991-28531c77c23b', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 14, '100140699', '虎の威を借るアミドニア', 'ガイウスの息子ユリウスは、大国グラン･ケイオス帝国の威を背景にかつての自領ヴァンをソーマの手から取り戻そうとする。その交渉の全権を与えられたのは、女皇マリアの妹ジャンヌ･ユーフォリアであった。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c7ed06c-8af2-41ec-8092-3a42747fdf6f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3181de27-7923-4e45-8d65-e48e513e6308', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 15, '100140700', '莫逆 (ばくぎゃく) の友と為る', 'ジャンヌとの交渉はつづく。もはや交渉はユリウスのものではなく、グラン･ケイオス帝国とエルフリーデン王国のものだった。そして、ジャンヌはソーマの中に、新しい未来を、新しい世界の姿を見る。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afcfc757-3e77-461f-b1ea-cb9376644b4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89e6fd39-4939-453e-88e2-d9e6dccd555b', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 16, '100140701', '苛政は寅よりも猛し', 'グラン･ケイオス帝国の仲介の結果、ヴァンはユリウスの元に返還されることになる。高額な賠償金を引き換えにして。ソーマは未だ多くの問題が残るエルフリーデン王国へと帰還していく……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3bb77f92-cfd0-4324-98d3-d4a355781592.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7feed17-8af6-438f-ab1b-c5d77970ea9e', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 17, '100140702', '士は己を知る者の為に死す', '内乱、さらにはアミドニアとの戦いに勝利したソーマ。だが、それはゲオルグという男の献身の上に成り立ったものであった。しかし、法は法。ソーマは彼に対し厳しい裁きをくださねばならなかった。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/372192ed-b545-4840-9d32-292b7eb50b16.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72b38d19-8a6f-4307-930a-bec8975ee1a3', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 18, '100140703', '杯中の蛇影', 'さまざまな困難を乗り越え、ソーマはなんとか戦乱の後処理を終える。だが、彼には言い知れぬ疲労が忍び寄っていた。人の上に立たねばならない者のみが背負う苦悩と重圧。それは彼ひとりで抱えきれるものではなく……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7f14ea2-4549-4d13-81c5-8f29140a4d8c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c07c9d82-edf2-4cd6-b60f-d410c17a0416', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 19, '100140704', '奇貨おくべし', '近衛騎士団のルドウィンの幼なじみジーニャは稀代のマッドサイエンティストであった。その発明は、科学技術が発達した世界からやってきたソーマでさえ、驚き感嘆……そしてあきれ果てるようなものだった。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de3d2288-e668-4d63-bba8-fe7d6d3d9bae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52cefe96-594f-4dc1-a630-d32c23039aed', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 20, '100140705', '西施のひそみにならう', 'ユリウスに返還されたアミドニアの首都ヴァンでは、再び圧政が敷かれていた。民衆の不満は日に日に増していき、ついに反旗を翻すに至る。そのとき、ソーマの前にユリウスの妹ロロアが現れた。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5edf19c-2e13-4ad8-85b1-d91c97b46b53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30196413-19aa-4719-8ec4-b93d17ec2f89', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 21, '100140706', '蝦で鯛を釣ろうとしたら鮫が掛かった', 'ロロアの登場によってアミドニアとエルフリーデン王国の状況はさらに複雑になる。ソーマすら想定していなかった結果。これを受けてグラン･ケイオス帝国の女皇マリア･ユーフォリアとソーマの会談が開かれることに……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1d02335-d9fc-4a84-91f7-be66ccb4b768.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31f68ac0-8bc5-4ca1-963e-b1721d421b01', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 22, '100140707', '人学ばざれば智なし、智なき者は愚人なり', 'フリードニア王国にジンジャー･カミュという奇妙な奴隷商がいた。彼は奴隷に清潔な衣服とじゅうぶんな食事を与え、さらには教育まで施してやった。それがゆくゆくは王国を揺るがすことになるとも知らずに……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89972504-6d11-4706-8b7c-060da1cb8644.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ecbb328-dcf8-495e-af98-4514964d0b37', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 23, '100140708', 'うがい手洗いは防疫の基本', '難民、それは現代社会も抱える難問のひとつである。そして、フリードニア王国もまた例外ではなかった。王都の壁の外には魔物の侵入によって国を追われた難民たちが集まり、キャンプを築いていたのである。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d2c6cbe5-00a7-4daf-bf72-4e5a1bffdf91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0077701d-5134-41be-b082-0e2ce12a2df2', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 24, '100140709', '家郷 (かきょう) に離別して歳月多し', '難民の元を訪れていたソーマたちは、難産の妊婦を助けることに。新しく生まれてくる命、それは難民たちの希望であり、未来への礎であったが、彼らのすべてがソーマの示す未来を受け入れるわけではなかった。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eaef31c8-1514-4ef7-95ea-bcea48291ca6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6d40380-22bd-4e41-a81a-24e4ce4ebb8b', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 25, '100140710', '相手を知り、己を知れば夫婦仲も危うからず', 'とある夜、リーシア、アイーシャ、ジュナ、ロロアといった婚約者たちに、エクセルは囁く。殿方の喜ばせ方をお教えしましょう、と突如始まった「花嫁育成講座」。ソーマと婚約者の秘密がつまびらかになる……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90f31b9c-eae3-427c-b354-3d0a7bdf991e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('159a37dc-b7af-4275-97e7-9809d22c8892', 'fb300f1e-028d-461e-a079-f1b0bbcfb00e', 26, '100140711', '前 (さき) に古人 (こじん) を見ず、後 (のち) に来者 (らいしゃ) を見ず', '【第二部 最終話】大晦日の晩、ソーマは先代の王アルベルトに呼び出され、妃のエリシャと共に話をすることに。アルベルトの口から告げられる驚くべき真実。そして、「すべて」を知ったソーマの胸にこみ上げるのは……。', '2023/05/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63583b7f-104b-4d27-95dc-91ea517c0ea1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
