INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9202ddb9-6d88-4399-83f7-e1c56da6ce52', '後宮の烏', '', 'hulu', 'raven-of-the-inner-palace', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6baa1b4-11ce-4de7-9e73-c8e23e0cf80c.jpg?w=331&h=447&p=t', 'hulu', 2022, 3, 1, 'FINISHED', NULL, 142701, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ee4719bf-e0aa-45a7-9405-db0f18e38021', '9202ddb9-6d88-4399-83f7-e1c56da6ce52', 'hulu-raven-of-the-inner-palace-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5157421-8223-4e2d-a91c-a2fdd54785f6.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71a0fd65-d969-46dc-b6b0-6ea6e8eaa218', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 1, '100125034', '翡翠 (ひすい) の耳飾り 前篇', '烏妃 (うひ) は、妃でありながら夜伽をしない特別な妃である。呪殺、祈祷、失せ物さがし、頼まれればなんでも請け負うが、会えば災いがあるとも言われている。後宮に住んでいるが詳しいことは誰も知らない謎めいた存在だ。夏王朝 (かおうちょう) の皇帝･夏高峻 (かこうしゅん) は、烏妃の住まう夜明宮へと足を踏み入れる。そこにいたのは漆黒の衣装をまとった美しい少女･柳寿雪 (りゅうじゅせつ) であった。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5157421-8223-4e2d-a91c-a2fdd54785f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0736f1e9-2db6-4dc9-a3b1-cb309ea96a1f', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 2, '100125712', '翡翠 (ひすい) の耳飾り 後篇', '高峻に頼まれた寿雪は、翡翠の耳飾りに取り憑いた幽鬼のことを調べていた。耳飾りの持ち主は班鶯女 (はんおうじょ)。十年ほど前、三の妃を毒殺した疑いをかけられ、首を吊って亡くなっていた。その死の真相を突き止めるため、侍女に迎えた九九 (じうじう) とともに、班鶯女の側仕えをしていた蘇紅翹 (そこうぎょう) がいる洗穢寮 (せんえりょう) へと向かう。しかし話を訊くことはできなかった。紅翹は舌を切り落とされていたのである。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb620b12-ae44-413d-81d5-4da6bc3c4778.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('378148d4-602d-4618-888d-858d17ab1394', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 3, '100126527', '花笛 (はなぶえ)', '鴛鴦宮に住まう後宮最上位の妃、花娘 (かじょう) が夜明宮にやってきた。花娘は、花笛がなぜ鳴らなかったのか知りたいという。花笛とは冬の終わり、その年に亡くなった者を弔うため、軒先に吊るしておくものである。春の訪れを告げる風とともに死者が還ってきて、笛を鳴らすと言われている。花娘は恋人だった欧玄有 (おうげんゆう) を亡くした時、笛が鳴らなかったことを気にかけていた。寿雪は求めに応じて欧玄有の魂を呼び出し、話を訊こうとする。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33668db7-75e1-4b74-b4af-7014bdee14bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4144175-f8a6-4ec2-9de3-4e3b0ae35391', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 4, '100127241', '雲雀公主 (ひばりひめ)', '夜明宮に雲雀の幽鬼がやってきた。未練があり、楽土へと渡れないらしい。不憫に思った九九は寿雪に雲雀を救ってほしいとお願いした。寿雪は雲雀を飼っていた雲雀公主 (ひばりひめ) のことを調べる。宮女に話を訊いて回っていると、とある世間話を耳にする。それは、下げ渡される反物などがない宮は侍女にとってはずれであるということだ。寿雪は九九に何もあげたことがなかった。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a8d131c-c8c9-4480-811f-f97aaa07495b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25c9f536-64bd-4bcb-a23f-dd2ed96094b7', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 5, '100127982', '懐刀 (ふところがたな)', '高峻の寝所に夜な夜なふたりの幽鬼が現れる。それが原因で憔悴していく高峻の身を、衛青 (えいせい) は案じていた。烏妃に相談してはどうかと勧めるが、他言無用だと口止めされるばかりである。その理由は幽鬼にあった。高峻の母と、親しかった宦官･丁藍 (ていらん) だったのである。高峻はふたりの死に対して、自責の念にかられていた。その気持ちを理解しつつも、放っておけない衛青は、寿雪の元を訪ねようとするが——', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afa0876a-6f3a-43c5-9557-c6f8929f630c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ba0c875-bc47-452f-befb-ba756c0412b0', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 6, '100128515', '夏の王、冬の王', '皇帝の住まう凝光殿 (ぎょうこうでん) の庫 (くら) には、幽鬼が身につけていた縞瑪瑙 (しまめのう) の玉珮 (ぎょくはい) が納められていた。その持ち主は明珠公主 (めいじゅこうしゅ)。欒王朝最後の皇帝の娘であった。庫にはその絵姿も残っていた。そこで寿雪は明珠公主と、ある人物の絵を目にする。一方、歴史書を紐解き、烏妃の秘密を探し求めていた高峻は、薛魚泳 (せつぎょえい) から本当の史実が書かれたもう一つの歴史書が存在すること、そしてそれを持っているのは烏妃であると明かされる。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/720b1a6b-e3c5-4e6c-b153-8e684fb47599.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7391de0b-d731-458d-ba3b-8c0220207afd', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 7, '100128980', '玻璃 (はり) に祈る', '前王朝の血を引く冰月 (ひょうげつ) と明珠公主は、結婚の約束を果たせないまま戦の中で亡くなった。死後、幽鬼となった冰月は、同じく幽鬼になりさまよう明珠公主を柳の下で見つけたが、呼びかけても反応がない。その公主を救うため、冰月は楽土へ渡らず留まり続けていたのである。手を尽くしたが公主は呼びかけに応えてくれないままだった。どうすれば公主を救えるのか。寿雪はひとつの仮説を立てていた。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc0bf130-2b99-48b1-ae63-a7278fa42455.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57121869-54b5-49e7-8cb4-bf6600cfea1b', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 8, '100129622', '青燕 (あおつばめ)', '飛燕宮の見習い宦官･衣斯哈 (いしは) が夜明宮を訪ねてきた。衣斯哈は青燕の羽根を持つ少年の幽鬼を見かけ、その子を救ってほしいと寿雪に頼む。調べを進めていくと、衣斯哈が先輩宦官たちに棒で折檻されている場に遭遇してしまう。寿雪が止めに入ると、衣斯哈の指導役である康覧 (こうらん) は震え上がる。寿雪の瞳の中に恐ろしい化物が見えたのだ。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ded821ca-402a-4e72-ade3-be346f013376.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('859f96d4-20e0-4e09-8561-0f8bf7d52c3b', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 9, '100130254', '水の聲 (こえ)', '宮女･安蕙蘭 (あんけいらん) が頼み事にやってくる。蕙蘭は水の中から死んだはずの妃の声が聞こえると訴える。炎帝が統治していた時代、鵲妃として迎えられた西婉琳 (さいえんりん) は、帝のお渡りがある日、池に飛び込み亡くなった。水の中からする声はその妃のものだという。蕙蘭は婉琳を救ってほしいと頼み込むが、寿雪はその訴えの裏にある蕙蘭の真意を見抜いていた。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e57c1f9-d62e-4c37-a4ba-a375b73a79a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd0e1eee-3cf8-43ca-9b5a-1dec128ef3f9', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 10, '100130968', '仮面の男', '高峻が珍しく寂しそうな顔をみせた。そのことがどうも気にかかるが、寿雪はその理由を問うことができない。数日後、高峻が幽鬼の取り憑いた面を持って夜明宮に顔を出す。幽鬼は異国渡りの琵琶の音に反応するらしい。その琵琶を高峻が用意することで話がまとまる。話を終えた高峻は帰ろうとするが、寿雪はつい引き止めてしまう。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/970a4df4-2241-483b-948b-e8ac395e667b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68052267-51ac-4dac-878e-38e97cf54d8c', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 11, '100131562', '布石 (ふせき)', '寿雪が星烏廟 (せいうびょう) を訪ねると、薛魚泳と高峻が碁を打っていた。寿雪が魚泳と代わり、高峻と勝負をする。碁を終えた後、二人はしばし庭で話をすることにした。その姿を見ていた魚泳は高峻が帰った後、寿雪に忠告をする。情けは愛とは違う。高峻とこれ以上親しくするべきではない。烏妃は何も望んではならないのだから——と。それは寿雪が麗娘から教えられた烏妃としてのあるべき姿だった。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/107291cd-26e8-4ad8-b80f-66a0a9ce7900.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf7b3d5f-5518-4ee7-b1e7-7e14cb3eef3f', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 12, '100132209', '兄妹 (きょうだい)', '戻らない温螢 (おんけい) を探して、寿雪は鵲巣宮に乗り込んだ。そこで寿雪はやつれはてた鵲妃･琴恵瑤 (きんけいよう) に会う。大切な兄を亡くした後、長らく床に臥せっていると思われていた恵瑤だったが、彼女は鵲巣宮の中で、あるものと過ごしていた。それは亡くしたはずの兄。髪の毛と泥を使って蘇らせてもらったのだと恵瑤は語る。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bd0c3a1-35e9-43ef-b2e0-6f300666ec83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c3aacfe-fcb4-480d-ae03-ee4b34c7cf79', 'ee4719bf-e0aa-45a7-9405-db0f18e38021', 13, '100133231', '想夫香 (そうふこう)', '【シーズン1 最終話】鵲妃･恵瑤の迎えた悲劇は寿雪、高峻の胸に重く残っていた。その一件から数日後、高峻の命で調べを進めていた衛青は、封宵月 (ほうしょうげつ) を後宮に招き入れた協力者が宮廷内にいることを突き止めた。衛青は温螢、淡海 (たんかい) とともにその者を追うが、一足違いで逃げられてしまう。同じ頃、ある人物が夜明宮を訪ねてきた。寿雪は驚く。その人物は重大な禁忌を犯していた。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1ece189-3a2b-4c4c-a432-be5e428aba49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('887c5fbe-c52f-4858-9472-5491f15058e9', '交響詩篇エウレカセブン', '', 'hulu', 'eureka-seven', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cf386e9-79c3-4911-815f-34c560518e25.jpg?w=331&h=447&p=t', 'hulu', 2005, 1, 1, 'FINISHED', NULL, 237, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cee6de9d-3754-4c6b-9243-9e485d42eaee', '887c5fbe-c52f-4858-9472-5491f15058e9', 'hulu-eureka-seven-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d634b3f-92a2-49a9-820d-e3e9e7594103.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f0f3514-3724-4ab5-ae84-dc9d7cf953e9', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 1, '100025594', 'ブルーマンデー', '単調な毎日にうんざりしていたレントン。そんなある日、レントンの家に幻のLFOニルヴァーシュが落ちてきた。コックピットから現れたのは、美少女エウレカ。メカニック業を営む彼の祖父の家に、ニルヴァーシュの整備を頼みに来たというのだが。彼女の後に、ゲッコーステイトと塔州連邦空軍のKLF部隊も現れて…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d634b3f-92a2-49a9-820d-e3e9e7594103.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('186cceab-cc08-4c5c-ba7f-0d9fce9ae1fc', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 2, '100025595', 'ブルースカイ･フィッシュ', 'ニルヴァーシュを追って現れた塔州連邦空軍。ホランド率いるゲッコーステイトも加わって、空で繰り広げられる激しい攻防戦。エウレカを守るため、レントンもボードで空を飛ぶ。祖父サーストンから手渡されたアミタドライヴをニルヴァーシュに装着した、その瞬間、ニルヴァーシュは光に包まれる。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3c91e54-c097-4b77-89e2-d50318355c2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4faaef0e-be49-42cb-a127-48a9366f8b36', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 3, '100025596', 'モーション･ブルー', '再会したホランドとサーストン。レントンの知らない話が、二人の間で交わされる。その頃、塔州連邦空軍の圧力によって空港滑走路が閉鎖された。ゲッコーステイトの乗る空船、月光号は逃げ場を失う。月光号救出のため空港へ急ぐホランド。「一緒に行こう」エウレカはレントンを月光号に誘うのだった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/910be512-7d61-4be7-8c2f-0e945b9b6983.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('728fe9e3-67cb-4b7e-8993-d3977351710f', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 4, '100025597', 'ウォーターメロン', '憧れだった月光号に乗ることになったレントン。しかし、そこで理想と現実のギャップに悩まされる。淡々と日々を過ごす彼らは、財政難に苦しんでいたのだ。そんな中、密輸の仕事を任されたレントンは、エウレカとともにニルヴァーシュで目的地へと向かう。しかし、そこには州軍の大規模な演習場があった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7119cfb0-36c9-4b48-a4e3-40e5b9d413b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5638216f-9152-41e3-bca3-ee7a05a36f1c', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 5, '100025598', 'ビビット･ビット', '月光号での新しい生活。レントンは、己の居場所を見出そうと頑張るが、やることなすことすべてが裏目にでてしまい、エウレカとの距離も縮まらない。そんな中、タルホが街へ買出しに行く。同行したレントンは、彼女の悩みを垣間見ることに。揺れ動く大人の感情に翻弄されるレントン。そんな中、タルホが街で絡まれて…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d0cf350-4dd1-48c8-80f2-5403debff8b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8d57936-1ea9-4f55-8464-aa1d97692631', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 6, '100025599', 'チャイルドフッド', 'エウレカをママと呼ぶ三人の子どもたち。彼らは、なぜかレントンを目の仇にし、執拗にいたずらを繰り返していた。ところが、そのいたずらが原因で、ついには月光号が窮地に陥る。ピンチを切り抜けようと、子どもたちを乗せてLFOを動かすレントン。そこに、州軍のKLF部隊が現れる。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/feef714a-fe76-435d-ab50-3a2efc5c6f56.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96b0533b-b5ce-43c3-ac63-e3852c2bfac3', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 7, '100025600', 'アブソリュート･ディフィート', '謎の敵に襲われた、塔州連邦軍のKLF部隊。その報告を受けた賢人会議は、ある男を召還する。その頃、月光号では、レントンが営倉から出され、重大な任務を言いつけられていた。とある人物と密会し、危険物を手渡すという、その任務。レントンは、勢い込んで街へ繰り出すが、その一部始終は誰かの視線にさらされていた。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/275ccd68-d21e-4d8b-8585-cdd8d9ac6176.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84e5b42f-3ff0-45fd-b60b-1a1b8a591082', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 8, '100025601', 'グロリアス･ブリリアンス', 'エウレカの付き添いで、街へ買い物に出かけるレントン。そこでティプトリーという名の女性と知り合いになる。彼女の家でお茶をご馳走になるレントン。しかし、そこにホランドが踏み込んでくる。ティプトリーは、ヴォダラクという反政府組織の重要人物だったのだ…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25300453-0f65-4458-9387-655159a36df6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae3cee0c-d4cc-448d-b69a-de071074f7bc', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 9, '100025602', 'ペーパームーン･シャイン', 'ヴォダラクの聖地、シウダデス･デル･シエロを訪れた月光号。廃墟と化しているそこは、かつて美しい空の都と呼ばれた土地。停泊中、リフを楽しんでいたレントンは、いきなりホランドに殴られ、泣きながら廃墟へと飛び出していく。すると、そこに軍の定時爆撃を知らせるサイレンが響き渡り…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75239f77-caf6-4548-8f34-cfb8674f3b35.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87cda042-b4be-4dab-a296-8303612f54d3', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 10, '100025603', 'ハイアー･ザン･ザ･サン', '地殻変動が起こり、それに伴うトラパーの大量噴出が星の裏側で起こるという。ゲッコーステイトは、リフを楽しむため、弾道飛行を決行する。ところが、辿り着いた場所は、連邦軍マナアキ基地跡。そこは、タルホとホランドにとって忘れ得ぬ、宿命の土地だった。未だ過ぎ去らぬ過去と、ホランドは対峙するのだが…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72f03f92-7703-475b-a449-fb504a5b2b5a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2f26d60-646e-4a50-bf80-454ef36da15d', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 11, '100025604', 'イントゥー･ザ･ネイチャー', 'ニルヴァーシュとの関係に、変化が見られ始めてから、身体の調子が悪いエウレカ。そんな中、月光号は未知なる現象であるコーラリアンに遭遇する。エウレカは無理に、ニルヴァーシュで出動するが…。コーラリアンのゾーンで、新たな敵、タイプ･ジ･エンドが攻撃をしかけてくるのだった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba352d8d-2f1a-461f-9fb4-591c7d6ccde1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6d742c7-65ed-4c7e-bf2a-9d91a0a0f8cf', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 12, '100025605', 'アクペリエンス･1', 'タイプ･ジ･エンドの攻撃を受けたニルヴァーシュ。気を失ったレントンは、夢の中へと堕ちていく。悪夢の中で、エウレカと、アネモネに出会うレントン。これは、レントンの個人的な夢なのか、それとも…。その頃、コーラリアンのゾーンの外、月光号はイズモ艦との戦いに苦心を強いられるのだった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f9ece93-bead-4bdf-a50f-a57bd8fc4a3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d75d200e-0fbb-494b-8eab-b3f1806ec4b8', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 13, '100025606', 'ザ･ビギニング', 'コーラリアンのゾーンから帰還したレントンは、少女アネモネと再会する。しかし、エウレカとアネモネは、まるで共鳴しあうかのような、ひどい頭痛を訴えていた。アネモネを守るように現れたドミニクとともに、レントンは薬を求めて駆け出していく。辿り着いた町は、コーラリアンの影響で混乱状態にあって…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/516c83bb-b30a-48b4-bdac-4f3c0993b010.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('353d3202-e8f4-442d-95c8-186ea7dc1b4b', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 14, '100025607', 'メモリー･バンド', '軍との戦闘で大きな損傷を受けた月光号は、低空飛行を余儀なくされる。徐々に回復しつつあるエウレカだが、コーラリアンの現出によってその謎は一層深まりを見せていた。コーラリアン現象に、自らの解釈を提示するストナー。そして同じ頃、ドミニクもまた、エウレカとニルヴァーシュに関る世界の謎に思考を巡らせていた。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec3954e2-c682-470c-95d9-7b3b85ee583b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76383dd6-ad01-4ab5-a5a0-2b4843c770c5', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 15, '100025608', 'ヒューマン･ビヘイヴュア', '軍との戦闘で大幅な修理が必要になった月光号。その間にレントンは、幼少の頃を過ごした町･コントロラドに立ち寄る。エウレカたちとともに懐かしい思い出の家に行ったレントンは、親戚と久しぶりに再会する。しかし、お尋ね者のゲッコーステイトの仲間であると言うわけにはいかず、必死に嘘をつき通そうとするのだが…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ff0846d-9547-4252-b7c8-86f7fbb55528.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a69feb6-14b9-4890-be4c-05f826c014f3', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 16, '100025609', 'オポジット･ヴュー', '月光号を修理するため、閉鎖された遺跡発掘現場にいったん身を隠すゲッコーステイト。レントンは、ニルヴァーシュを一人で操縦してからというもの、エウレカとの間に溝が生じてしまったことに気づいていた。そして、エウレカに、思わず心無いことを口走ってしまう。そんな中、坑内で奇妙な施設を発見したレントンは…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4aa7a443-b1c2-45cd-8b40-fe84c8992240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ba7ac7c-d565-4f0c-8256-5c651cb208e9', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 17, '100025610', 'スカイ･ロック･ゲート', 'エウレカとの間がもとに戻らないレントン。月光号も、修繕がはかどらず、空を飛べないままでいた。ゲッコーステイトは、リフレクション･フィルムを注文するため、フィルム職人のもとを訪れることに。そこで、フィルムを作るために必要な、スカイフィッシュを捕らえることに協力するのだが…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/002e985e-4de3-4a38-8a36-ec5e88f87fe9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74143db0-a7dd-4e88-bc2e-f031e579f070', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 18, '100025611', 'イルコミュニケーション', 'トラパーが枯渇して久しい発掘現場。停泊する月光号は、そこでブリタニという発掘屋の男と出会う。ブリタニに連れられ、レントンは発掘現場の洞窟でLFOのアーキタイプを見る。そんな中、世界最古といわれるニルヴァーシュtypeZEROを見たブリタニは、思いがけない行動に出るのだった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6221d14-e746-433a-bad2-014d0ddb7f1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d682149c-7a67-42b3-9ce6-c54b1ddfbd2e', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 19, '100025612', 'アクペリエンス･2', 'ブリタニの行動によって、州軍に発見されてしまった月光号。トラパーの波もなく、ニルヴァーシュも動かせない月光号は、窮地に陥る。そんな中、調子が悪いままのエウレカは、自分の変化を恐れ、ニルヴァーシュからアミタドライヴを引き抜いてしまう。すると、ニルヴァーシュはエウレカを載せて、洞窟の奥へと動き始め…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8af93128-fbda-4647-ae55-a03957c0b9ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a28aadd-9b6d-48dd-9370-6aac67a53e38', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 20, '100025613', 'サブスタンス アビューズ', 'スカブに取り込まれたエウレカは、意識のないままだった。レントンは心配するが、面会謝絶で近づくことはできない。そんな中、軍に囚われたヴォダラクの高僧の救出依頼が月光号にくる。仕事を請けるホランドに、レントンはエウレカより金が大事なのかとぶつかっていく。一人、出撃したホランドだったが…。', '2025/04/01 00:00:00', 1458, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eabdbd6f-525a-459e-b423-59853b3f4a24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebbe4848-8d5f-4f50-b89f-bdc3eff4275d', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 21, '100025614', 'ランナウェイ', 'LFOで、人を殺してしまったという事実は、レントンに重たくのしかかる。だいぶ具合の良くなったエウレカに、レントンは救いを求めるが、彼女の口から励ましの言葉はなかった。拒絶されたと思ったレントンは、自分の存在意義を見失い、月光号を飛び出していく。その頃、とある人物のもとへ赴くデューイ大佐は…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5363e9fa-ccaa-4a2a-afb4-8e18c1a4ce1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7ea844e-6c20-46cd-a377-583ea91ec3e3', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 22, '100025615', 'クラックポット', 'レントンが月光号を降りたことで、動揺を見せるメンバーたち。エウレカは、自分の気持ちの変化の理由が何なのか、理解しようとしていた。その頃、無一文になっていたレントンは、ビームス夫妻と出会う。夫妻の空船に招かれたレントンは、そこで彼らのLFOに搭乗することになり…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f65e7845-fd5d-4513-82eb-ae9497a66e65.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c654e95-e644-4b81-bf68-2102dd3e0378', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 23, '100025616', 'ディファレンシア', 'とある町で起こったテロ。それはヴォダラクの過激派によるものだった。ビームス夫妻の船に居候することになったレントンは、彼らの仕事に付き添い、とある町へ行く。ヴォダラク過激派のテロが起こったその町で、レントンは瀕死のヴォダラクの少女に出会う。その頃、レントンが月光号から降りたことを知ったエウレカは…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2926908f-672c-4393-b065-0cda30134db8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d2234bf-aae7-45e6-9d76-da5b1e996777', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 24, '100025617', 'パラダイス･ロスト', 'チャールズ夫妻から、自分たちを両親のように思ってくれと言われるレントン。両親のいないレントンにとって、それは嬉しいことだった。だが、レントンがゲッコーステイトのメンバーだと知ると、チャールズ夫妻の顔色が変わるのだった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bcc087e-1b2f-41fb-841a-c0cd973d321d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b98557dd-fa20-454d-8aec-a5f7e894f0bc', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 25, '100025618', 'ワールズ･エンド･ガーデン', 'エウレカのもとへと急ぐレントン。彼はそんな中で、ウィリアムという青年に出会う。ウィリアムは、マーサという絶望病の女性とともに、自給自足の生活をしていた。二人を通して、レントンは、絶望病とこの大地の関係、また、自分にとって一番大切なものは何かを、改めて知るのだった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/18944d97-7bf5-4f81-ac42-efef93856eec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed2ee1ab-e8ca-45df-a49d-0d8619c98294', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 26, '100025619', 'モーニング･グローリー', 'レントンを探すため、月光号から飛び出すエウレカ。その頃、レントンもエウレカを求めて月光号を目指していた。七色に光る雲の中で、エウレカは州軍が攻めてきたことを知る。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/081846d9-4dee-4703-911d-c9629d0d9c50.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3d74c1a2-f3e7-47d4-81cb-e95303fe506b', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 27, '100025620', 'ヘルタースケルター', 'メディアが発表する、ヴォダラク過激派の動向とコーラリアンの記事。世界は、複雑な様相を呈していた。そんな中、ビームス夫妻が月光号に強襲しかけてくる。', '2025/04/01 00:00:00', 1458, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae9ef17d-2d7d-4a41-9a55-e92d30fe0885.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f486a7a7-d369-4501-b7c6-2d385b97f193', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 28, '100025621', 'メメントモリ', 'たった一人、月光号に奇襲をしかけるレイ。エウレカへの憎しみが、彼女を狂気へと駆り立てていた。出撃するホランドら。レントンは、レイを止めようと、通信で必死に呼びかける。だが…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/331d18a4-e713-4d3e-beb6-095cfb35ea62.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afbfb657-27f3-4af2-bc85-e96d41003c9e', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 29, '100025622', 'キープ･オン･ムービン', 'レントンとニルヴァーシュの関係を調べるため、ベルフォレストへやってきたドミニクは、レントンの祖父と接触する。その頃、レントンは、思いがけず、エウレカの真実を知ることになる。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/555bfc11-f128-4fa9-a1f4-46ff8ee1b11c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('702831fd-59ba-44d4-b9d8-1b65a019b7f8', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 30, '100025623', 'チェンジ･オブ･ライフ', 'ニルヴァーシュを修理するため、軍のトレゾア研究施設へ赴くゲッコーステイト。そこは、エウレカがかつて過ごした場所だった。レントンは、そこでニルヴァーシュの作られた経緯を知る。そんな折、変化していくエウレカに合わせるかのように、タルホもまた、自身を変えようとするのだった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e500d50-dc46-439e-94a3-45250e56e7cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c91b37f1-5527-46cc-9913-56465ec4091d', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 31, '100025624', 'アニマル･アタック', '難航するニルヴァーシュの修理に、アーキタイプ研究の第一人者、ドクター･ベアの助力を得ることになる。エウレカとニルヴァーシュの変化に応じたスペックアップが必要だと説くベア。だが、作業が頓挫している間に、デューイのコーラリアンを巡る計画が本格的に始動するのだった。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85c96f61-0706-4fb6-bf3f-d5b10786fcf7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b061475e-c023-4fe5-88a5-0ed6cf9ecc4b', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 32, '100025625', 'スタート･イット･アップ', 'コーラリアンの被害を蒙った町で、難民船と接触する月光号。彼らはそこで、コーラリアンを巡り、デューイが本格的に動き始めたことを知る。そんな中、スペックアップしたニルヴァーシュのボードを受け取るため、空へと飛び出すレントンとエウレカ。だが、そこにはアネモネの操るジ･エンドが待ち受けていた。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebc3cb64-5b7f-4364-89f6-3b78a3c9b0c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99e3a49a-fbef-42ab-a5e4-f238cdc0e9bd', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 33, '100025626', 'パシフィック･ステイト', 'コーラリアンによる悲劇に、欝とした気持ちが晴れないままのゲッコーステイト。そんな中、タルホは「リフをしよう」と持ちかける。レントンの顔にも、久しぶりに笑顔が戻るのだが…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d07f02f8-a54d-492e-a5f0-c1fb9a07b2df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a32cc43d-0582-49f3-ac45-92c335fa2b5e', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 34, '100025627', 'インナー･フライト', 'ヴォダラクの高僧ノルブが、首都で捕まった。ノルブを追っていたホランドは、首都へ潜入するため弾道飛行を決行する。道中、ホランドからノルブとの出会いを聞くレントン。ノルブは、コーラリアンを巡る謎を解く鍵となる人物なのだという。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/967c2872-0938-41e3-a14f-1cc51309601f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c18d897a-dbbb-4dd9-ad9d-cd590279da02', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 35, '100025628', 'アストラル･アパッチ', 'ノルブ救出のため、首都キャピトル･ヒルに奇襲をしかけるゲッコーステイト。その防衛線上、軍KLFとの熾烈な戦闘が繰り広げられる。ついにノルブのもとに辿り着いたホランドは、はからずもデューイと再会し…。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/529353f5-0666-4a0b-9cd3-79bb4751d6a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfa62dab-a421-4cd9-a135-8db4fbcffa9e', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 36, '100025629', 'ファンタジア', 'いなくなった姉ダイアンの話をホランドから聞くレントン。消息を絶った原因に、スカブコーラルが関係していることを知る。同じ頃、エウレカは顔についた傷を気に病んでいた。レントンに、綺麗な自分を見せたいと思うのだが。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c60f02e-43bb-4dfc-bab4-0cbf4ada6693.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b60676d-0989-4adf-a77a-afde6298a20f', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 37, '100025630', 'レイズ･ユア･ハンド', '会談するドクター･ベアとノルブ。科学と宗教、両者の立場から導き出されるスカブコーラル知性体仮説。そしてデューイの真の目的を知ったホランドは、残された猶予がないことを知る。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e0c7900-20a1-4ecb-90b3-364fc625b46c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ea74e1a-8694-49b4-bc53-b1b3123d244d', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 38, '100025631', 'デイト･オブ･バース', 'エウレカが父アドロックのことを知っていたという事実に驚くレントン。今までなぜ話してくれなかったのかとエウレカを責め、二人の仲にすれ違いが生じる。その頃、デューイは賢人会のもとへ赴いていた。世界は、デューイの計画によって、大きく動き出そうとしていたのだ。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61386692-8ade-4a32-a711-40ae0bcbea4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10228612-b982-4624-b50c-1bbe7e0e83bc', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 39, '100025632', 'ジョイン･ザ･フューチャー', 'ノルブとともに、グレートウォールの麓にあるヴォダラクの本拠地、ヴォダラ宮へ向かうゲッコーステイト。その頃、クーデターを起こしたデューイは、世論を巻き込むためにテレビを通して演説を始める。', '2025/04/01 00:00:00', 1443, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e62d9821-f1ca-42cb-9c16-f801f4d504f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb7d595d-50f6-49bf-a449-9ccb8cfee36c', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 40, '100025633', 'コズミック･トリガー', 'ヴォダラクの街で、ティプトリーと再会するゲッコーステイト。ホランドは、彼女らの協力を得て、レントンとエウレカをヴォダラクの本拠地であるヴォダラ宮へと潜入させる作戦を実行する。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/080f876d-d5a2-46f9-8057-aff1b84fed10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c736435-fdf8-4262-9fc4-f79448f33aa9', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 41, '100025634', 'アクペリエンス･3', 'ヴォダラ宮に潜入したゲッコーステイト。レントンとエウレカは、ノルブから人型コーラリアンであるサクヤとの話を聞くのだった。そんな中、軍が急襲をしかけてきて…。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d13d685-5ac2-47c5-abab-e9a430281607.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5b1fa1a-352d-41b2-9c8f-847b1f845645', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 42, '100025635', 'スターダンサー', 'グレートウォール突破を試みるレントンとエウレカ。だが、そこへ軍の攻撃によって抗体コーラリアンが現出する。ノルブ、そしてゲッコーステイトの面々は、レントンらを守り、送り出そうとするが…。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/944348d2-f3d4-40c0-9930-f2a761ec3c8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06d3467c-298b-43af-9b6e-0a15d3860ba3', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 43, '100025636', 'ザ･サンシャイン･アンダーグラウンド', '見知らぬ場所に迷い込んでしまったレントンら一行。ゲッコーステイトたちの安否も分からぬまま彷徨う。その頃、デューイとともに、アネモネは新年の宴に出席する。そこで、デューイの口から、ある真実が語られるのだった。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a38d992-f090-40b5-bb88-c397d0c8be6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae60f550-4f33-4a25-ae14-1ca7839bd6bf', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 44, '100025637', 'イッツ･オール･イン･ザ･マインド', '行くべき道が分からないまま、些細なすれ違いから、レントンたちの間に亀裂が生じる。その頃、デューイの命により、ドミニクはワルサワシティへと向かっていた。そこで、彼はアネモネの真実を知る。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6f34476-9e5b-4e09-95c8-0ef0cc967d42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b984cb77-6ad2-4c13-9dfb-b4f945baffb1', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 45, '100025638', 'ドント･ユー･ウォント･ミー?', 'エウレカの変化をきっかけに、レントンと子どもたちの亀裂が深まる。そんな中、エウレカは、逃れられない過去の傷をつきつけられるのだった。一方、ワルサワを出発したドミニクは、イズモ艦艦長とともに、ある場所へ向かう。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73c51bd6-4b04-46ce-9323-9780d763f524.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2afdfa9e-1ab8-4f8a-a416-c4217e47b315', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 46, '100025639', 'プラネット･ロック', 'スカブコーラル殲滅に向けて、デューイの攻撃が最終段階に突入する。デューイの攻撃を阻止しようと行動するゲッコーステイト。その頃、腕を負傷し動けなくなったレントンを、エウレカと子どもたちは懸命に看病していた。だが、エウレカの身体にも異変が起こり始め…。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03575454-89aa-4300-b198-6719dbd582c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03f7bd7f-f613-462f-9b3f-d6803b3768df', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 47, '100025640', 'アクペリエンス･4', 'コンパク･ドライヴの光に導かれるまま、ニルヴァーシュで移動するレントンたち。辿り着いた先は、スカブコーラルの中心だった。レントンは、そこで思わぬ人物と対面し、スカブコーラルの意思と、その歴史を知る。だが、デューイの攻撃が始まり、ついにスカブコーラルの覚醒が始まろうとしていた。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/743fbbc8-b480-4a29-99d0-c4fcdeded360.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cb4bcb1-7ef8-41fe-9f86-60ceb4efc932', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 48, '100025641', 'バレエ･メカニック', 'デューイの攻撃により、スカブの大地に大穴が出現する。そこから、スカブコーラルの中心に向けて、出撃するジ･エンド。レントンたちは、ジ･エンドを阻止するため、ニルヴァーシュで立ち向かう。空中で繰り広げられる激しい攻防戦。その中で、アネモネはその素顔を垣間見せるが…。', '2025/04/01 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b3233e3-a892-4ed7-b239-4c1cf4f3b646.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('175987d5-b081-4926-b300-4e4c2a5a66f8', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 49, '100025642', 'シャウト･トゥ･ザ･トップ!', '地殻攻撃によって生じたデブリが、地上に降り注ぐ。星の壊滅を目前に、スカブコーラルと対話しようとするレントンたち。ニルヴァーシュは、その心に呼応したかのように動き出そうとするが。そこへデューイの乗るギンガ号が降り立つのだった。レントンたちの危機に、現れたのは…。', '2025/04/01 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c7dfa53-b07c-4d8f-a11c-6d26c638b233.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8e940ab-f260-416e-84e2-7b1dfc9fa52a', 'cee6de9d-3754-4c6b-9243-9e485d42eaee', 50, '100025643', '星に願いを', '最終話 ※権利元の意向であらすじが存在しません。ご了承ください。', '2025/04/01 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a02db477-6d19-473e-9459-4c6098b68136.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8f7ddfe1-54a0-490c-ad1e-a399705bcbe9', '公女殿下の家庭教師', '', 'hulu', 'private-tutor-to-the-dukes-daughter', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39fbf0d8-747a-4ea8-af35-c3e051a09cd5.jpg?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 170113, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c07d23d3-4425-4f96-a09d-f1848f3cba89', '8f7ddfe1-54a0-490c-ad1e-a399705bcbe9', 'hulu-private-tutor-to-the-dukes-daughter-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f62737d-38a8-4074-8a27-ffa1c95d6265.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04b5847e-2a1a-4d28-98e4-93ed67e92b42', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 1, '100231112', '魔法が使えない公女殿下', '王宮魔法士の試験に落ちてしまったアレン。仕事を探していたところ、恩師である教授の紹介で公女殿下の家庭教師を務めることになりハワード公爵家へ。到着した先で待っていたのは、魔法が全く使えないティナという少女。彼女の父親であるワルター･ハワード公爵から伝えられたアレンの使命は、ティナに「王立学校入学を諦めさせること」だった……!', '2025/07/06 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f62737d-38a8-4074-8a27-ffa1c95d6265.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c821fd8-1208-4749-a91c-b06a8b792318', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 2, '100231113', '拒絶するモノ', 'ティナとエリーの家庭教師として魔法授業を開始したアレン。エリーがあっという間に成長していく一方、ティナは一向に魔法を発動できるようにならず、その差は開くばかり。少しずつティナの中には劣等感が募っていき……。解決策を探るため、書庫へやってきたアレンは、勉強しようとやってきたティナとメイド長のシェリーの姿を見かける。', '2025/07/13 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6542e528-986a-4038-929a-867fea369ec0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b587c45f-b361-4a11-9281-6d35afc4923b', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 3, '100231114', '涙の後に咲く花', '魔法が使えるようにならない焦りから魔力を暴走させたティナ。魔力の暴走を抑えようと試みるアレンは、吹雪の中でティナの中にあるものを目にする。それこそがティナの魔法発動を妨げていた「何か」だった——その後、ティナは魔法を使えるようになるも、ワルターは王立学校受験を頑に認めようとしない。反発するアレンに、ワルターはある条件を提示する。', '2025/07/20 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3693a539-1215-4320-9cca-93acd6ee0172.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1176c41-3f91-4539-a45a-6771382b548a', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 4, '100231354', '最終試験', 'ティナの王立学校受験を認める条件としてワルターから提示された最終試験に向け、日々訓練に励むティナとエリー。そんな中、アレンはティナが魔力を暴走させた時に見えた「何か」の正体を調べていた。そして迎えた最終試験当日。ティナとエリーの対戦相手として現れたのは銀仮面をつけた大男だった……。果たしてティナとエリーは王立学校を受験できるのか!?', '2025/07/27 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f3b3b47-365a-4980-827b-b902c82b527c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1025bf1-6aa4-47b4-8df8-4a40146c0efd', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 5, '100231356', '憧れの王立学校 前編', '王都へ戻ったアレンは、リディヤからの追及をなんとか躱しつつ、久々の再会を楽しむ。一方、ティナとエリーは王立学校入学試験を非常に優秀な成績で合格。首席のティナは新入生代表の挨拶を務めることになる。そしてアレンが王宮魔法士試験に落ちた理由が明かされる――憧れの王立学校編がついに開幕!', '2025/08/10 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41245298-8d11-4559-a6eb-56ba004c575c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74a0d12a-04a4-40e5-a878-000e3e1ff0cc', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 6, '100231357', '憧れの王立学校 後編', '王立学校入学式の最中、アレンに王宮から救援を求める知らせが届く。駆けつけたアレンが目にしたのは、騎士達を次々に倒し、ジェラルド王子に対して剣を振るうリディヤの姿だった。それから数日後、アレンは王立学校に呼び出されていた。教授の計らいで臨時講師になることになったアレンは、先生として初めて王立学校の教壇に立つ。', '2025/08/17 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b53bc4c-c6b7-4fcf-a8b3-0fca01e5528f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd073506-f35f-4aaf-8531-b9fef164cd76', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 7, '100231358', '課外授業は温泉で', 'オルグレン公爵家の温泉施設へ旅行にやってきたティナ･エリー･アレン･リディヤ。温泉を楽しみにしていた一同だったが、設備故障により入れなくなり落胆する。温度管理に使っていた魔石が消えてしまったのだという。そんな中、同じく旅行に来ていたステラ･フェリシア･カレンにまさかの遭遇。一同は温泉に入るため、魔石を探すことに!?', '2025/08/24 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb2f5560-b4c9-4af6-9155-f657183191e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31978f95-ab4b-47bc-829e-6ed45130063e', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 8, '100231359', 'マガイモノ', '王立学校で授業の準備をしているアレンに、電話がかかってくる。ジェラルド王子やその取り巻きと口論になったリィネが、決闘を申し込んだらしい。駆けつけたアレンが目にしたのは、禍々しいオーラを発する短剣を手にし、いつもと様子の違うジェラルド王子だった。アレンがジェラルド王子の暴走を食い止めようとする中、リディヤが颯爽と登場して……。', '2025/08/31 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffc229b3-7108-465f-8a7a-e8826bbdb6f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37cc9625-dd4d-4dc1-a401-e2c8cf666ed0', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 9, '100231360', '光のない路 (みち)', 'アレンはカレンに、ステラが相当落ち込んでいるようだと相談を持ちかけられる。先日のジェラルド王子との戦いで、ステラは急速に魔法の腕を上げていくティナ達と自身の実力差を目の当たりにしたのだった。その頃、アレンはティナを呼び出していた。期待と喜びの表情を浮かべるティナに、アレンはティナの中に存在しているのが何なのか、驚くべき正体を告げる。', '2025/09/07 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20a37e02-5e81-42c9-bae3-00d1d9857c3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20214d59-a5e0-4815-a0d6-3916fe11bac2', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 10, '100231361', 'フェリシアの決断', 'ハワード･リンスター両公爵家の取引先選定役を務めるアレンのもとに、フェリシアの父であるフォス商会のエルンスト代表が商談にやってくる。大量の商品を仕入れたいというエルンスト代表の提案を、アレンは無理な条件だと断る。その話を聞いたフェリシアは、商談を父に任せきりにしていたことを悔いて、アレンに直談判を持ちかける。', '2025/09/14 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8f4f946-f139-44d5-8b7c-51e8e3b854d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8acd4bc1-5ec3-45bf-9e83-515d40adc1d1', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 11, '100231362', '月と星の輝く夜に', '寮を飛び出しハワード家の別邸に身を寄せるステラのもとへ、アレンがやってくる。優しく語りかけるアレンに対し、ステラは肩を震わせ嗚咽を漏らす。カレンやフェリシア、エリー、リィネ、ティナと自身を比べて塞ぎ込むステラに、アレンは今日一日学校をサボり一緒に王都をデートしようと提案する。アレンがステラをエスコートした先は……?', '2025/09/21 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/863362cd-5768-4b49-af0a-3ee94c3c21fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1354b0d9-51b8-49be-98d4-bafa159492ea', 'c07d23d3-4425-4f96-a09d-f1848f3cba89', 12, '100231363', '少女達の戦い', '【最終話】ステラ･アレン VSティナ･エリー･カレンの決戦当日。訓練場に集まった面々は互いに手加減無しの全力勝負をすると誓い合う。アンナの掛け声と同時に動き出す両陣営。ティナ･エリー･カレンの連携技に対し、ステラ･アレンも作戦を実行していく。戦いは激しさを増していき、ついにティナの極致魔法『氷雪狼』がステラ･アレンに迫る――!', '2025/09/28 01:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/efd21af9-c4b4-480f-b874-725293bf2e50.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
