INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 'a6cfc8a4-640d-4928-b007-7175bf9a21ee', 'hulu-ghost-in-the-shell-sac-2nd-gig-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5f730233-2b61-4afc-ac2b-6f3a359f24c3.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c5e79cb-e10b-457d-98d9-c1cad378cfed', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 1, '60565025', '再起動 REEMBODY', '「個別の11人」と名乗る武装グループによって中国大使館が占拠された。密かに出動していた公安9課の面々は無期限待機命令の解除を待つ。総理は、犠牲者を出さず15分以内にテロリストを鎮圧することを条件に、突入を許可するが─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5f730233-2b61-4afc-ac2b-6f3a359f24c3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('997e8ce7-ec86-49ee-a034-cf93c4922e4d', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 2, '60565038', '飽食の僕 NIGHT CRUISE', '3大ネットワークJBNNの会長･片倉の専属パイロットを務めるギノ。欺瞞と不正に満ち溢れた世の中から、憧れの高級娼婦“ヒララ”を救い出したい。義憤に燃えるギノは、彼らに正義の鉄槌を下すべく行動を開始する!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/35e00e9f-20cc-4576-8d7f-1da27dca58a2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8451cc8c-35c3-4008-9bd1-1f8cf57a9ca9', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 3, '60565029', '土曜の夜と日曜の朝 CASH EYE', '政財界の名士である田所会長のもとに、窃盗犯から予告状が届いた。9課は芽葺首相の命により、田所主催のパーティを警備することになる。だが、窃盗犯の正体は草薙だった! 9課の本当の狙いは何処にあるのか!!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/92fa6ab1-fa56-4839-8812-ef51525336dc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('848fd586-3727-4bee-b1f2-a92848810bad', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 4, '60565048', '天敵 NATURAL ENEMY', '合同演習中にAIヘリが暴走。誘われるように各地で無人のヘリが動き出し、集結し始めた。そして、対応を迫られる9課の前に忽然と現れた内閣情報庁の“ゴーダ”。彼の真意も図れぬまま、草薙らはタチコマで出撃するが─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/029e7cbf-616d-414c-b1c4-3688614d9d3c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c5eb29c-43a2-47c5-8af9-6cb723ead5c5', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 5, '60565043', '動機ある者たち INDUCTANCE', '「個別の11人」から茅葺首相に暗殺予告文が届いた。9課は警護につくが、参禅に乗じて暗殺は実行にうつされる。茅葺に迫る全身義体の男･クゼ。はたして草薙は阻止できるのか!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9f74e16e-16a0-4f73-9cc7-239663b0cdfa.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5da45bd5-a1dc-40c0-b738-a11c8b4f21d0', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 6, '60565040', '潜在熱源 EXCAVATION', 'エネルギー省を脅迫していた男が、不可解な死を遂げた。トグサは彼の足跡をたどるべく、招慰難民居住区「東京」に向かう。だがそこでは、あるべきはずもないものが、地下最深部から呼び起こされようとしていた。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/72ff4d66-e66d-460b-8a7e-6749692ddf7d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f441deb9-d6bf-4bc6-ba08-c6bced7dab6b', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 7, '60565033', '狂想は亡国の調べ 239Pu94', '新宿地下原発から燃料棒の海路移送計画が「個別の11人」に漏洩した。ゴーダの指揮のもと、9課は移送任務を請け負うが、経由する陸路は不穏な空気が漂う難民居住区だった。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/abb2eaeb-c2af-478a-afcb-2a44fe987c79.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6ce5d44-9220-4389-964b-e64d57b405bc', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 8, '60565023', '素食の晩餐 FAKE FOOD', '「個別の11人」容疑者カワシマの身柄確保に奔走する9課。だが、虚構であったとしても現実へと変換されれば、それは真となる─。彼は本当に「個別の11人」なのか、それとも別の目的を持った偽者なのか!?', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8694b753-849f-4521-b159-b55612aeb016.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aaf091e6-0b90-4a7e-953b-daa445c3512c', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 9, '60565030', '絶望という名の希望 AMBIVALENCE', '生きることに希望を見だせない人々がその身をやつす「自爆テロ」。そして、それを阻止するため奔走する9課。一方、単独で内閣情報庁に潜入した草薙は、そこでゴーダの仮想人格と対峙するが─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6ad5cf64-8367-4257-a1e8-3595eda2a2bd.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28332961-27f7-4093-8276-e1148ed0d330', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 10, '60565037', 'イカレルオトコ TRIAL', '非番中にやむなく発砲してしまったトグサは、単なる証人から「不幸な事故」の引き金に仕立て上げられる。証言台に立つ彼の前で、理不尽な追求が9課にまでその矛先をのばそうとした時、事態は思わぬ展開を見せた!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/990de169-5fad-4186-97d8-c8af48eb4c14.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c75df3f9-8f3a-4f52-a2e1-ee8f58bde7d4', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 11, '60565046', '草迷宮 affection', '虚実定まらぬ街で誘われた、記憶を預かるという『牢記物店』。草薙は、そこで主無き少年少女の義体とめぐり会う。物言わぬ彼らにかつて訪れた物語とは─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cb129daa-8049-4684-b0c7-2a5ebc56ea71.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06c102ff-2b06-41fd-ae95-3bac3557bf64', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 12, '60565036', '名も無き者へ SELECON', '虚ろなる真に導き寄せられる「個別の11人」。そして、組み上がった因子を解き明かしはじめる9課。だが、さらなる具現を阻むべく行動を起こしたその時、すべてを暗転させる「刃」が抜かれた!!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7ed939b4-8457-49b9-8e32-a5d2fec760c0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25fdfdfd-8bfc-4c27-b701-95c97be903c2', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 13, '60565034', '顔 MAKE UP', 'クゼの顔を追って、9課は造顔作家へとそのコマを進めた。だが、カメラの映し出したパズの凶行が、捜査の動きを鈍らせる。これも「クゼ」の仕業なのか、それとも─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5bb87392-fdc0-43f5-b38f-cab448e3c922.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf856b03-cad1-47ca-860e-41519814dc8c', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 14, '60565042', '左眼に気をつけろ POKER FACE', '米帝特使を迎え厳戒態勢が敷かれる中、待機中の隊員等はポーカーに興じていた。そこで、一人勝ちを続けていたサイトーは、左眼にまつわるポーカーフェイスを語りはじめるのだが─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/becf5a71-56fc-4c87-9528-c4acf8c05d86.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6af982eb-20fb-4bc2-a935-ccf53101b036', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 15, '60565039', '機械たちの午後 PAT.', '「この人どこかで見たことがあるんですよね…。」研究所の爆破事故後の捜査中に、奇妙な既視感を感じるタチコマ。所在不明の有須田博士と、自分達の主体について疑問を持つ彼らとをつなげるものとは─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7fc7a421-e42d-43ea-b327-673242c13bb6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b090c8b6-8b5b-4d24-9344-cbc05dcbd726', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 16, '60565027', 'そこにいること ANOTHER CHANCE', '国連平和維持軍としての戦い、任務を終えてからの葛藤─。イシカワの持ち帰ったクゼの過去、それは9課にとっても草薙にとっても不可解なものであった。一方、国内情勢の悪化は日米安保締結に拍車をかけていた…。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/35698a40-e38e-4f53-93df-9975e2daf8b7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('920e7a65-576e-4b15-acb2-dab529b1706a', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 17, '60565026', '修好母子 RED DATA', 'クゼの足取りを追い台湾へ潜入した草薙は、そこで少年･チャイと出会う。行動を共にし始めた二人の関係は、時には友人、時には親子、そして時には恋人─わき起こる奇妙な感覚に母性を励起させ、彼女は行動を開始する!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7876a1bc-741a-4283-b9a8-da9f8f93233b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db87db76-178a-4b02-9a0a-68c2e0631aca', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 18, '60565041', '天使の詩 TRANS PARENT', '当局が追っている正体不明のテロリストは『天使の羽根』と呼ばれていた。大規模な包囲網が街を覆う中、ある少女の存在がバトーの脳裏をよぎる。そして、彼女の秘密に突き当たったとき、天使は再び舞い降りた─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/48609d84-8312-4aa3-83b5-c86e62593750.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b816c43-421f-483b-90ca-ca44aeadbd5c', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 19, '60565047', '相対の連鎖 CHAIN REACTION', '並列化した招慰難民達の行動は、自治区宣言へと拡大した。これに対し草薙は、クゼを確保すべくハブ電脳へとダイブする。だが、潜伏場所を急襲した9課を予想し得ない事態が待ち受けていた!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d7bdb39a-dfae-4113-8f54-f80dd4510bc2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df40b042-3acd-468e-a096-c686a65bf27c', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 20, '60565035', '北端の混迷 FABRICATE FOG', '北端、択捉─そこは、旧型の電脳都市にして混沌の坩堝。断片的な情報を元にクゼの目的を想定し9課は旧ロシアの原潜基地跡へと向かう。しかし、そこでは既に難民等とアームスーツが戦いを始めていた!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/34774afb-3f77-4203-bb99-4663ed0839ad.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aea6c960-68fa-4e41-95d4-297a0d9f3d93', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 21, '60565031', '敗走 EMBARRASSMENT', 'クゼと9課との間にある、わずかな動機の差。それは彼に包囲網を突破させ、出島へと辿りつかせる。だが人々の前に広がった光景は、第三者による意志の介在を予見させるのだった。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1fc87c7d-9ff1-4476-8c8a-4d319d7b1fcc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54e04bd8-3a44-4045-9e18-5d8c3052c06c', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 22, '60565024', '無人街 REVERSAL PROCESS', '「個別の11人」最期の場所である九州電波塔に、プルトニウム爆弾が仕掛けられた。解体処理のため無人と化し静寂につつまれる街中を、バトーは一人ゴーダのもとへと赴く。クゼが自決をしなかったその場所で、二人はなにを語ろうというのか─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/08ad2baf-43ab-49fc-bf50-96e7cb39f574.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1e78f30-46fe-4b7a-bcfc-88422cf0adc2', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 23, '60565044', '橋が落ちる日 MARTIAL LAW', '戦わずとも勝負は決するはずだった招慰難民と自衛軍。しかし、水が低きに流れるように、人の心もまた易きに流れる。一発の銃声が状況を急変させ、事態は混迷の度を深めていく。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d76307e1-796a-48a7-b6f3-dfbfafec03ac.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b20a5c3-5f2e-42f0-998d-b251c3edba71', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 24, '60565032', '出島、空爆 NUCLEAR POWER', '制空権をおさえられ潰走する招慰難民達。ゴーダの策略がさらなる展開を見せる中、9課は出島へと突入する。一方で、クゼは人々をハブ電脳に繋ぎ止めるべく、次の手に出ようとしていた─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6add802f-d066-485d-b299-01026050cd98.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce38909d-a052-45f5-a3b1-bc9f801bd6a2', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 25, '60565028', '楽園の向こうへ THIS SIDE OF JUSTICE', 'クゼと邂逅を果たす草薙、そして茅葺の救出に成功する荒巻─事態は収束に向かうかと思われた。だが、タチコマが掴んだ情報は、9課の動きが未だにゴーダの予想の範疇を出ていないことを示していた。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9cf28f5a-ddb1-4b37-adc0-4bb97cf2adb9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5af8f2be-7402-4838-853e-1f223ecc758d', '54d2fc14-5d8c-4cc5-b375-1fe363c886d0', 26, '60565045', '憂国への帰還 ENDLESS∞GIG', '【シーズン2 最終話】この終焉は、通過点の一つであり、又始まりでもあるのだろう。自らを賭して攻撃を阻止したタチコマ。革命の行く末を見極めることなく逝くクゼ。ゴーダとの因縁を精算する9課。そして─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/67f9c03f-1389-430a-925f-e19f3d008377.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
