INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('43842de1-fc23-4820-8dcf-27b64f500d8f', '227197cd-9fdf-40c5-93be-7eb4a098c5a7', 'hulu-ghost-in-the-shell-stand-alone-complex-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0cb119f6-a1cb-4125-b467-27890247ec05.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd338912-e823-466e-968f-2124fda9c27d', '43842de1-fc23-4820-8dcf-27b64f500d8f', 1, '60565017', '公安9課 SECTION-9', '夜の高級料亭で、アンドロイド芸者が外務大臣一行を人質に立て籠もる事件が発生。公安9課･草薙素子率いる攻殻機動隊の制圧で、無事外務大臣の救出に成功する。だが事件の背後には、軍の機密情報･一ノ瀬レポートを巡る陰謀が渦巻いていた─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0cb119f6-a1cb-4125-b467-27890247ec05.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90101e84-7a18-4c58-8eb7-a2d4e97e6971', '43842de1-fc23-4820-8dcf-27b64f500d8f', 2, '60565004', '暴走の証明 TESTATION', '剣菱重工の最新型多脚戦車が突然暴走し始めた。演習場を後に、ある方向を目指してひた走る。テロともAIの故障とも判別できないまま出動する公安9課。やがて事件は意外な展開を見せ始める!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1f588a7f-5adf-490f-9a47-f711de6be2a3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e74bb33-a67e-481a-9f62-96b281ee3f0e', '43842de1-fc23-4820-8dcf-27b64f500d8f', 3, '60565010', 'ささやかな反乱 ANDROID AND I', '各地で旧式のアンドロイド･ジェリが一斉に自殺する事件が発生した。原因はウィルス感染だったが、ただ一体だけ、ウィルスから守られたジェリがある男と逃亡していた。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b423af1a-30df-44cc-8861-d60368047ef7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea9d8871-1cbe-476a-8f00-66529638ca6a', '43842de1-fc23-4820-8dcf-27b64f500d8f', 4, '60565002', '視覚素子は笑う INTERCEPTER', '6年前に起きた企業テロ。“笑い男事件”を追っていた特捜部の山口は、不穏な秘密を知った直後、自動車事故で死亡した。事故の直前に山口からいわくありげな写真を渡されていたトグサは、警察内部で不正使用されている盗視覚デバイスの存在に気付く。その事件の中で、“笑い男”が再び見えない姿を現した!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/18e4b437-072b-48f8-a8cc-50fe9f44f614.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12aebf90-4e67-4bb8-8736-73cbd7bef493', '43842de1-fc23-4820-8dcf-27b64f500d8f', 5, '60564996', 'マネキドリは謡う DECOY', 'インターセプター不正疑惑会見で起こった〈笑い男出現事件〉。荒巻は、警察自演の騒ぎではないかと疑念を抱く。〈笑い男〉最重要参考人･ナナオを張り込む公安9課。一方、草薙は単独で6年前の〈笑い男事件〉を洗い直し、警視総監の護衛を申し出た。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/35a2a50b-215b-45f9-938a-00acf56204be.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('525e3c06-b81b-4361-8792-bc61bc6b1179', '43842de1-fc23-4820-8dcf-27b64f500d8f', 6, '60565007', '模倣者は踊る MEME', '警視総監暗殺予告当日の会場では、SPの一人がナナオの仕組んだ遅効性ウィルスにより発症。だがウィルスとは無関係の暴走も連発し、混乱は加速する。〈自称犯人〉たちであふれ返す警察取調室。騒動のさなか、荒巻と草薙はある場所へと向かうのだった─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fd0aa5c6-88b5-4444-9aa4-431efdce2644.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59dde4e7-cee3-4abc-afe7-30238d6db3eb', '43842de1-fc23-4820-8dcf-27b64f500d8f', 7, '60565018', '偶像崇拝 IDOLATER', '幾度もの暗殺計画を奇跡的にくぐり抜けた南米某国の国民的英雄･マルセロ。その男がたびたび極秘裏に来日しているとの情報を受け、9課の調査が始まった。やがてマルセロと暴力団組織との関係が露呈し、ついに来日の目的が明らかに─!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2ce9e062-6580-44ee-b2b2-be8bb800e5cc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dac5f537-5271-40b8-b92e-773845563c32', '43842de1-fc23-4820-8dcf-27b64f500d8f', 8, '60565012', '恵まれし者たち MISSING HEARTS', '移植手術を受けた少女の心臓が、提供者の承諾を得ていないものであることが判明。組織的な臓器密売の可能性から、9課が捜査に乗り出した。少女と同じ年頃に全身を義体化した草薙が事件に特別な感情を抱く中、意外な実行犯の姿が浮かび上がる─!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/14be491d-1f53-4bcb-ab0f-fd48c3f2f451.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8346b188-abb4-431c-bc8a-dda76340ccd8', '43842de1-fc23-4820-8dcf-27b64f500d8f', 9, '60565021', 'ネットの闇に棲む男 CHAT! CHAT! CHAT!', 'ネットマスター･オンバの主宰する〈ラッフィングマンルーム〉では、笑い男事件をめぐってJ･D、ぐるぐる、カナビ、ベビールース、クロマらがチャットに参加し、推理を展開していた。果たして彼らは真実にたどり着けるのか─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/887d788e-ab2a-4f2c-b2fd-c8311fa89d67.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0da4e11-804b-4c90-8d5a-82f1a8755ed8', '43842de1-fc23-4820-8dcf-27b64f500d8f', 10, '60565011', '密林航路にうってつけの日 JUNGLE CRUISE', '女性が生皮を剥がされて殺害されるという残忍な事件が連続して発生。その犯行スタイルから、バトーは過去の出来事を思い起こさずにはいられなかった。事件の背後にちらつく、ある極秘計画の影。そして事件の結末は─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c8637041-1c37-4c8f-b838-671e7f76ceb0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('419ab3a5-bfd6-459b-ad69-8ac9cc733164', '43842de1-fc23-4820-8dcf-27b64f500d8f', 11, '60565016', '亜成虫の森で PORTRAITZ', '電脳閉殻症患者の授産施設から厚生労働省にハッキングが仕掛けられた。犯行の常人離れした手際のよさ、厚生労働省の不自然な反応などから、荒巻はトグサに施設の潜入捜査を命じる。そこでトグサが目にした異常な光景とは─!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5ea8e85f-5885-4ce6-8ad3-3631e92d144b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27c5ecca-5cfe-4f29-b86a-c083a07b458b', '43842de1-fc23-4820-8dcf-27b64f500d8f', 12, '60565013', 'タチコマの家出 映画監督の夢 ESCAPE FROM', '天然オイルを入れられていたタチコマ1機が、突如起動。繰り出した街で犬を探す少女と出会う。タチコマは少女を手伝うことになるが…。その道中でタチコマが拾い持ち帰った〈防壁のない電脳〉が、9課に騒ぎをもたらすことになる。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/495530ab-dbf0-4e16-9197-a507f493255d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71aa7a8b-84d3-4d14-b6ce-5f878308ac49', '43842de1-fc23-4820-8dcf-27b64f500d8f', 13, '60565009', '≠テロリスト NOT EQUAL', 'テロリスト集団〈興国の旅団〉に誘拐され、消息不明だった少女エカ。〈興国の旅団〉が潜む海上プラント内で連絡の途絶えた海上保安庁の先遣隊。謎を秘めたプラントを目指し、9課の捜査が始まった。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f8c20f91-3926-4d89-96ab-504d05314e9c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('522c3a00-b14e-47f2-a523-c18f68c903fc', '43842de1-fc23-4820-8dcf-27b64f500d8f', 14, '60565008', '全自動資本主義 ￥€＄', '大富豪の個人投資家･横瀬を狙う、中国から来た殺し屋フェム。9課は情報を得て、横瀬の身辺を固めるべく行動を開始する。だが横瀬については自宅の豪邸の場所以外、謎に包まれている。9課は暗殺を阻止できるか、そして横瀬の正体とは?', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e4449542-525a-4455-906a-d3ed240b5a17.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b66188f-ddc1-4f3e-8566-5e3488294f82', '43842de1-fc23-4820-8dcf-27b64f500d8f', 15, '60565014', '機械たちの時間 MACHINES DESIRANTES', 'タチコマたちは、草薙の態度を不審に思い、近く何らかの処分があるのではと議論を巡らせる。AIにとっての生と死の概念、ゴースト、神、そして自分たちの存在意義。彼らは自分たちの身を守る方法として、ある行動に出るのだが─。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e5108043-f21b-4b95-a22e-e5ea207187f2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6292c4db-817b-415c-8534-2937373c1b3a', '43842de1-fc23-4820-8dcf-27b64f500d8f', 16, '60565001', '心の隙間 Ag2O', '海自への潜入捜査でスパイ容疑者ザイツェフに近づくバトー。ザイツェフは、かつては「義体の隙をつく」と表現される独特の技で一世を風靡した格闘家だった。バトーはかつて憧れていた人物との、任務を越えた決着をつける。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3a48ed5e-134e-45c6-84ee-3c67aa459778.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3ced37a-bee2-4ba1-9f7d-95b15d706f09', '43842de1-fc23-4820-8dcf-27b64f500d8f', 17, '60565020', '未完成ラブロマンスの真相 ANGELS'' SHARE', 'ロンドンでの国際テロ対策協議を終えた荒巻と草薙。荒巻は単身、昔なじみの勤める銀行に向かうが、そこで思わぬ事件に巻き込まれる。荒巻が画策する危機脱出計画、荒巻の行動を予測しながら救出を図る草薙。そして事件の行方は!?', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b72f50ce-732f-4c5e-af74-35b2798ceec7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5e4f5f4-ef96-4964-922e-d5332303bfa7', '43842de1-fc23-4820-8dcf-27b64f500d8f', 18, '60565006', '暗殺の二重奏 LOST HERITAGE', '荒巻はかつての同僚の娘から、様子のおかしい弟のことを調べて欲しいと頼まれたが、私的な理由で仕事はできないと断る。一方、中国外務次官の暗殺が計画されているという極秘情報を掴む9課。その犯人として浮上したのは、依頼を受けた娘の弟だった―。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3321fee8-06e3-485d-9e1e-d225761ff4fb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb4e7097-c535-4bc7-9b58-48ce9fe6e5c4', '43842de1-fc23-4820-8dcf-27b64f500d8f', 19, '60565019', '偽装網に抱かれて CAPTIVATED', '神崎元首相の娘、玲子が突然失踪。9課は北方マフィアによる集団拉致の可能性を疑う。だが集団拉致を否定してきた神崎の娘が誘拐されたのはなぜか? 犯人の意図が読めない綱渡りの捜査の中、主犯はロシアの対外情報局の元女工作員･クルツコワと判明した―。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ad882a06-69c8-4c5e-8a9e-6a92b1f089cb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6789fa10-e341-42a1-91bd-e6063af7c944', '43842de1-fc23-4820-8dcf-27b64f500d8f', 20, '60565005', '消された薬 RE-VIEW', '過去の事件の腑に落ちない点を足がかりに、笑い男事件の真相を独自に推理するトグサ。厚生労働省の資料捜査にあたる中、〈村井ワクチン接種者リスト〉が紛失していることに気づく。そして向かったNPO〈ひまわりの会〉で、絶体絶命の危機に陥る!', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/374cdb64-a521-4f53-9d99-27b8b36b8f01.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfa664c0-cdb4-4de2-868a-71c94e79f468', '43842de1-fc23-4820-8dcf-27b64f500d8f', 21, '60564999', '置き去りの軌跡 ERASER', '〈笑い男事件〉の真相を知ると思われる今来栖尚を確保すべく、全力を挙げる9課。麻薬取締局強制介入班と激しい戦闘を演じる中、立ちはだかるアームスーツを前にした草薙は、自ら囮となる―。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1f1bc3ca-4ec9-4af6-894a-9535765843b8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('863164a6-e7e0-4509-8c13-db8d77c0028b', '43842de1-fc23-4820-8dcf-27b64f500d8f', 22, '60564997', '疑獄 SCANDAL', '消息の知れなかった実の兄が生きていたとの報を受け、罠とも知らず単身招慰難民居住区へと向かう荒巻。一方で義体換装中の草薙にも忍び寄る、強制介入班残党の魔の手。そんな草薙の窮地に現れたのは、あの〈笑い男〉だった。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/98665f75-999c-49dd-9a33-d6b8ef7740be.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8cae0d9-4b02-4ec0-a8f0-2e8b56027f4f', '43842de1-fc23-4820-8dcf-27b64f500d8f', 23, '60565000', '善悪の彼岸 EQUINOX', '〈笑い男事件〉とその黒幕･薬島幹事長とを結びつける最後の線、セラノゲノミクス。9課が動き出した矢先、青いフードをかぶった人物が瀬良野社長宅を訪れる。〈笑い男事件〉の発端となった6年前の誘拐事件が、今まさに再現されようとしていた。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bdd4999b-29d8-4913-8e63-f80e91e3b716.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('14b8680d-ad29-4902-aeb7-e13f3700bb1c', '43842de1-fc23-4820-8dcf-27b64f500d8f', 24, '60565003', '孤城落日 ANNIHILATION', '薬島幹事長を逮捕するため総理と掛け合う荒巻。だが、既に9課壊滅のシナリオが動き出した後だった。特殊部隊規制法案の施行、そして本部の武力制圧。草薙は9課の「解散」を宣言し、それぞれに逃走･潜伏することを命じるのであった。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/29f1eb0e-cb2d-4b3c-924f-001e1346c5d5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('855ac4c3-eb42-44ba-b473-2a911baf4fa7', '43842de1-fc23-4820-8dcf-27b64f500d8f', 25, '60565015', '硝煙弾雨 BARRAGE', '捕らえられていく9課のメンバーを救うため、奔走する荒巻。草薙のセーフハウスで、追っ手の待ち伏せにあうバトー。そして、窮地を救うために駆けつけるタチコマ達。多大な犠牲を払いつつも、草薙と共に脱出を図ろうとした、まさにそのとき―。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e3448bfe-51a9-453f-beeb-316d5c89c92b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5372ccf7-f911-48a0-b575-6cc2e890ec3b', '43842de1-fc23-4820-8dcf-27b64f500d8f', 26, '60564998', '公安9課、再び STAND ALONE COMPLEX', '【シーズン1 最終話】薬島幹事長逮捕の知らせを受け、義憤の念に駆られるトグサ。自分たちが信じてきた正義とは、いったい何だったのか。それを確かめるかのように、トグサは銃をポケットに放り込み、検察や報道陣であふれかえる与党本部に向かうのだった。', '2021/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/04e71b00-e61a-488a-9029-28c67d2919ae.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dbf39179-709d-41ce-b616-5d1a8ce9e02f', '甲鉄城のカバネリ', '', 'hulu', 'kabaneri-of-the-iron-fortress', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25a08d3d-663b-4a61-9f74-aff612525a4c.jpg?w=331&h=447&p=t', 'hulu', 2016, 1, 1, 'FINISHED', NULL, 21196, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('38a2357e-42c9-439a-8392-87d226227d0f', 'dbf39179-709d-41ce-b616-5d1a8ce9e02f', 'hulu-kabaneri-of-the-iron-fortress-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6891fc7-b557-482a-bc11-bf71521ad376.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('590f8453-e71f-4180-90f2-a0d8286d803a', '38a2357e-42c9-439a-8392-87d226227d0f', 1, '100147003', '脅える屍', '不死の怪物･カバネが顕金駅を襲った。顕金駅で暮らす蒸気鍛冶の少年･生駒は、逃げ惑う人々の波に逆らって走り出した。密かに開発した武器――ツラヌキ筒でカバネと戦うつもりだ。彼自身の過去と、誇りのために。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6891fc7-b557-482a-bc11-bf71521ad376.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('803a2559-56ce-44ca-a9b1-68814856bc4b', '38a2357e-42c9-439a-8392-87d226227d0f', 2, '100147004', '明けぬ夜', 'なんとか助かった生駒は、顕金駅に唯一残された駿城――甲鉄城に向かう。一方、カバネの中に取り残された菖蒲たちの前に、幼い少女･無名が現れた。彼女はその超絶の戦闘力で、甲鉄城への脱出路を切り開いていく。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11c13966-e9e9-4a0f-ab22-ff2474fe4cf9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba92690b-d043-40c1-99fc-d49dca9883df', '38a2357e-42c9-439a-8392-87d226227d0f', 3, '100147005', '捧げる祈り', '顕金駅を脱出した甲鉄城は、幕府の要害――金剛郭を目指す。しかし、甲鉄城の人間たちは早くも内部対立し、生駒たちカバネリを追い出そうとする。急遽リーダーになった菖蒲にそれを治める力はなくて……。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8533fe57-2233-4881-aa36-4d6a4927fbc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5500b90-6fa0-40d8-bd76-0441077d54dc', '38a2357e-42c9-439a-8392-87d226227d0f', 4, '100147006', '流る血潮', '生駒と無名は民衆によって最後尾車両に閉じ込められてしまう。それは甲鉄城の戦力の弱体化を意味していた。ちょうどそこにカバネが襲ってくる。しかも中には、戦いを重ねて強くなったカバネ――ワザトリがいて……。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/515ff60d-4b63-445c-ae16-67bd84004216.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb99e1c1-48b3-4b44-a05c-e96d88dbe25a', '38a2357e-42c9-439a-8392-87d226227d0f', 5, '100147007', '逃げられぬ闇', 'カバネに滅ぼされた八代駅で、甲鉄城は生存者を拾った。生存者の中には無名の昔なじみ榎久がいた。彼は甲鉄城に馴染み始めた無名を弱くなったと指摘する。焦った無名は、自ら無謀な戦いを選択し、窮地に陥ってしまう。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21aae686-8473-4d96-b06c-0215ef519ee7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a9563ef-05f9-4d7b-bd70-2bc6939d5087', '38a2357e-42c9-439a-8392-87d226227d0f', 6, '100147008', '集う光', '甲鉄城は巨大なカバネの塊――黒けぶりを前に立ち往生していた。一方、生駒と無名は廃駅の底に落ちていた。周囲はカバネ、無名はガレキの下敷き、援護は望めないという絶望的な状況で、それでもなお生駒は前を向いた。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ca7aaf0-5930-4051-9db4-7c0cd62e2bd7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8608ef0b-2f2f-42d0-bb9b-824f13cd9b5e', '38a2357e-42c9-439a-8392-87d226227d0f', 7, '100147009', '天に願う', '顕金駅を出てから初めて、甲鉄城は人の暮らす駅――倭文駅に着いた。生駒たちは買い出しに出かけ、久しぶりの平安を味わう。一方、菖蒲は倭文駅に食料を分けてくれるよう交渉する。しかし、どの駅も食料は貴重で……。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2835789-54b7-40a0-b975-edf9c87b1d79.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66cb9161-5554-4f49-a124-6d8a0343ffc7', '38a2357e-42c9-439a-8392-87d226227d0f', 8, '100147010', '黙す狩人', '無名の慕う兄様は、カバネを狩る特殊部隊――狩方衆を率いる美馬だった。だが、人々から英雄と讃えられる美馬のことを、生駒は信じられない。彼こそが、無名をカバネリにした元凶だったからだ。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6aef4b59-7541-4be0-b5a3-c1e5a09bd457.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('309f3859-164a-47b5-891d-8f10454c939b', '38a2357e-42c9-439a-8392-87d226227d0f', 9, '100147011', '滅びの牙', '甲鉄城は金剛郭へ至る最後の砦――磐戸駅に到着する。幕府は、民衆の声望を集める美馬を警戒し、金剛郭への道を閉ざそうとするが、美馬は磐戸駅の領主に会談を求め……。ついに、美馬と狩方衆による倒幕が始まったのだ。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e7254af-4edc-420d-b248-57ab11b6463b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('325430df-c98a-417d-b8ea-a9d56d156216', '38a2357e-42c9-439a-8392-87d226227d0f', 10, '100147012', '攻め上ぐ弱者', '克城に連結された甲鉄城では、逞生たちが狩方衆の厳しい管理下に置かれ、血を採取されていた。絶望する人々の中で、生駒は諦めず反攻作戦を企図する。自由と誇りと、無名を取り戻すために。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/893b9d69-99e0-496a-9086-a9e30ebef709.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5eda0a14-543c-42bb-b87a-71cd94a1c5d8', '38a2357e-42c9-439a-8392-87d226227d0f', 11, '100147013', '燃える命', '美馬は、父親である現将軍･興匡と10年ぶりの再会を果たす。その裏で無名のヌエを準備しつつ。一方、なんとか一命を取り留めた生駒だったが、自信と気力を失い、心が縮こまっていた。カバネを見ても怯えることしかできない生駒だが……。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb75fdc5-605d-493e-bcca-7bc829ec69eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('83d21afb-5daa-41f9-a683-6a35db7c7eb1', '38a2357e-42c9-439a-8392-87d226227d0f', 12, '100147014', '甲鉄城', '【最終話】美馬の計略と、ヌエとなった無名、そして流入したカバネにより、金剛郭は崩壊しつつあった。そこに生駒が到着する。自らの体を再び改造した生駒は、無名を救うために、敵だらけの金剛郭に踏み込んでいく。', '2023/07/31 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae3f9cd1-2147-4797-8d33-4745a75b2d07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8d831c45-7553-4e7e-87e6-245323010692', '荒川アンダー ザ ブリッジ', '', 'hulu', 'arakawa-under-the-bridge-anime', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a35a4cf-eacc-498e-98ae-388685f8d2a2.jpg?w=331&h=447&p=t', 'hulu', 2010, 1, 1, 'FINISHED', NULL, 7647, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7da92a36-4b30-4594-b32d-1a9568312f8e', '鋼の錬金術師', '', 'hulu', 'fullmetal-alchemist', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4002a12a-cfce-4029-b82e-dd4651bb0f91.jpg?w=331&h=447&p=t', 'hulu', 2003, 3, 1, 'FINISHED', NULL, 121, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', '7da92a36-4b30-4594-b32d-1a9568312f8e', 'hulu-fullmetal-alchemist-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/544fe448-a465-4313-90c6-65953b958f2f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb5af884-b556-425c-9dcf-7c9d1c0e3934', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 1, '100035129', '太陽に挑む者', '強大な力を秘める「賢者の石」を求めて旅するエルリック兄弟。15歳の兄･エドワードは、史上最年少で国家錬金術師の資格を得た天才錬金術師。弟のアルフォンスは、外見は屈強な鎧姿だが、心優しい14歳の少年である。東部辺境の町リオールにやってきた2人は、レト教の教主･コーネロの「奇跡の御業」を目撃する。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/544fe448-a465-4313-90c6-65953b958f2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8eae5c4c-931d-4691-8951-7ebd4096769a', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 2, '100035130', '禁忌の身体', '『賢者の石』をめぐり、コーネロ教主とリオールの教会で対決するエルリック兄弟。だがそこに、教主の危機を聞きつけたレト教の信者たちが乱入してくる。街中に逃れた2人だが、「奇跡の御業」で動き出したレト神像によってアルは破壊され、エドは町人に捕らえられ、コーネロの前に引きずりだされてしまう。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/769b4cc7-2425-4e5c-9179-88142e32288c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68ff99a2-7b08-460f-9bd0-ddaf67b13d9f', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 3, '100035131', 'おかあさん……', '旅の途中立ち寄った街角の古本屋で、錬金術の入門書をみつけるエドとアル。昔、それを使って勉強していたときの頃のことを思い出す。それはまだ2人が幼い時、故郷リゼンブール村で暮らしていた頃のことだった。彼らは、お母さんの喜んだ顔がみたい、その一心で、競って錬金術にのめりこんでいった…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd0765ca-7b7a-4907-8587-0cb70c6154a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61828c15-5a71-413e-a055-d63f20155865', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 4, '100035132', '愛の錬成', '国家錬金術師になるために、生まれ故郷のリゼンブールから旅立ったエルリック兄弟は、途中、マジハールという錬金術師の風評を聞き、彼の住む村を訪れる。だがその村では、死者が甦り人々を次々に襲うという、不吉な噂が流れていた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca5d2099-4fcd-4cec-b8cc-9ad796548f38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9b1eceb-5294-43ee-ba4c-4a70d1454b38', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 5, '100035133', '疾走! 機械鎧 (オートメイル)', '国家錬金術師になるためセントラルに向うエドとアル。間もなく到着するとマスタング中佐に報告の電話を入れた所、突然! 次の列車に乗れと命じられ、どうにか乗り込んだ2人。なんと、その列車には家族と旅行中のハクロ将軍が乗っていた…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e1862f6-a157-44f4-95c2-e44f812401a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f12e7737-1325-4b90-b5f2-0e77abc419e3', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 6, '100035134', '国家錬金術師資格試験', 'エドとアルは「国家錬金術師試験」にむけて、マスタングの紹介で生体錬成の第一人者である「綴命の錬金術師ショウ･タッカー」の家で過ごすことになった。タッカーの娘のニーナ、愛犬のアレキサンダーの励ましを受け、日々勉学に没頭する2人。そして当日、試験に挑むエドとアルだが…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6d3faba-0339-4dc0-92d7-36ed55944da3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef55af5a-79d7-4585-9a46-8e413ef90b65', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 7, '100035135', '合成獣 (キメラ) が哭く夜', 'エドは難関の「国家錬金術師試験」に12歳で合格し、最年少記録を塗り替えた。マスタングから国家錬金術師の証である銀時計を受け取るエド。それは様々な特権を得ると同時に、軍の一員になることを意味していた。タッカー家ではお祝いパーティーが開かれるが、タッカーは迫りくる査定に苦しみ、追い詰められていく…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a517b0ee-3bd7-4031-a4dc-9996f4c462cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('199f6e36-324f-4820-91d6-32336f2757f7', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 8, '100035136', '賢者の石', 'エドは、ニーナを救う事が出来なかった後悔と自分の無力さを噛み締めていた。そんなエドにマスタング中佐は、タッカーの残した研究の分析を命じる。冷徹ともいえる命令に反発し、エドは1人で、ニーナ殺害犯の捜査をはじめる。', '2026/02/01 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb62bde1-36e5-44ec-8706-a0d835d375b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59033757-ad60-4e70-a801-b701eda1f2a3', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 9, '100035137', '軍の狗〈いぬ〉の銀時計', '自分の小ささ、無力さを感じつつも、自分達の目的に向かっていくため、『軍の狗』国家錬金術師になることを決意したエド。そんな中、エドは、マスタング中佐から、国家錬金術師としての初任務の伝令を受けることになる。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6cd51ac4-1742-4994-9673-d7787af99b2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a95953b6-5eb0-40fb-9510-de395bfff84c', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 10, '100035138', '怪盗サイレーン', 'マスタング大佐へ報告に向かう途中、水の都･アクロイアで途中下車するエドとアル。アクロイアは観光名所として有名な街だが、最近サイレーンという正体不明の怪盗が出没しているという。手掛かりと言えば1つだけ、錬金術を使うこと。エドとアルは、街の刑事から捜査協力の依頼を受けることになったが…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/512773d6-4bfb-4838-92eb-8a3db82f0eaf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9682c0f-f818-474d-9f91-c1585bb950f3', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 11, '100035139', '砂礫の大地･前編', '『賢者の石』の噂を聞いて、金の産地･ゼノタイムにやって来たエドとアル。かつて栄華を誇った町はいつしか寂れ、町の人々はマグワールが研究している『賢者の石』に最後の望みを託していた。エドとアルはそこで偽のエルリック兄弟の存在を知る。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89a317e4-d98f-46f7-8f5c-5d10554d4e7e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a522e349-adde-42a5-b60d-dc699ba1bc6a', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 12, '100035140', '砂礫の大地･後編', 'エルリック兄弟の名を語り、賢者の石の研究を続けていたラッセルとフレッチャー。ラッセルは、マグワールから赤い水から賢者の石を精製するために、ある方法の実行を命じられる。しかしどうしても実行することの出来ない彼らは、地下牢に捕らえられてしまう。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f07827bd-2034-4e82-b888-075fef9f58d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad374880-3db8-4bbc-a32d-979ad2131be8', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 13, '100035141', '焰 vs 鋼', '国家錬金術師としての調査報告のために、軍･東方司令部を訪れたエドとアル。エドはゼノタイムで聞いたドクターマルコーの噂を、マスタング大佐に尋ねてみるが軽くかわされてしまう。そこでエドは一計を案じ、マルコーの情報を賭け、マスタング大佐と模擬戦闘を行なうことに…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa02d99a-1d4d-4cc2-bb35-cc3dbd8097c8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2fb1926-12e5-4bd3-832e-5c55e4329744', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 14, '100035142', '破壊の右手', 'かつてイシュヴァールの内戦中、軍から脱走した元国家錬金術師･ドクターマルコー。『賢者の石』の研究者であった彼を訪ねて、ハイドウ村にやって来たエドとアル。エドは、マルコーが軍から持ち出した『賢者の石』の研究資料を見せてほしいとせまるが…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/34fbdd98-f15d-4ec0-86cc-d1aca4e87727.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b50ae4d0-ee09-4f29-acac-967c167711db', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 15, '100035143', 'イシュヴァール虐殺', 'スカーに追い詰められたエドとアルは、間一髪の所をアームストロングに助けられ、マルコーを連れて逃げる。スカーがイシュヴァール人であることを知ったマルコーは、過去に起きた戦争のことを語りだす…。イシュヴァールの内乱の凄惨なる真実を。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1eaa7a3-e5cf-4faf-8e69-349fee9b987b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0622f720-94da-4abc-81a7-9af2396bdbc6', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 16, '100035144', '失われたもの', 'スカーによって破壊されたオートメイルの修理の為、リゼンブールへと向かうエドとアル。マルコーから密かに受け取ったメモには、「賢者の石」に関する研究資料の隠し場所が記されていた。その場所はセントラル図書館･第一分館。エドとアルは、ようやく掴んだ「賢者の石」の手がかりに向け、今また出発する。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92ce1694-65d4-435a-b8e4-240c3b18bbf1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5be26b5-0535-499b-a978-3961e9107d60', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 17, '100035145', '家族の待つ家', 'オートメイルの修理のため、リゼンブールを訪れたエドとアル。家を焼き、「賢者の石」を求めて旅だったあの日以来、4年ぶりの帰郷。ピナコとウィンリィも、憎まれ口をききながらも、温かく2人を迎え入れる。', '2026/02/01 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed67c16f-950b-41b0-a0b3-94131dece3dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a67d9db-5871-42b3-bc9c-e6e6651540a4', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 18, '100035146', 'マルコー･ノート', '「マルコー･ノート」マルコーの残した「賢者の石」の研究資料を求めて、セントラルを再び訪れたエドとアル。しかし資料の保管場所であるセントラル図書館･第一分館は、火災により焼失。目撃者の証言から、推測される犯人は、スカー。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca806d88-5873-4739-b4c7-9faf52bda67c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('753a0831-6412-4514-8696-165df31386f4', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 19, '100035147', '真実の奥の奥', '失ったすべてを取り戻すため、エルリック兄弟が追い求めてきた「賢者の石」。それはおびただしい生きた人間を犠牲にして作られるものだった。エドは、衝撃の事実に打ちのめされるが、やがてマルコーの残したメモ「真実の奥の奥」の意味を確かめる事を決意する。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a030f038-717a-4845-bf9f-f18c49ad6c68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d173c36d-f98c-448f-b922-9492b9d10229', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 20, '100035148', '守護者の魂', '「賢者の石」の研究場所が「第五研究所」であることをつきとめたエドとアル。廃墟のはずのその場所には、数々の罠が仕掛けられていた。そして、エドとアルに襲い掛かる2つの黒い影。死刑囚ナンバー48とナンバー66。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ea9ae79-03f5-4ed7-974c-4de94b3981ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3163c50b-6b99-482b-a417-6d99b5fa2357', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 21, '100035149', '紅い輝き', '第五研究所の中で繰り広げられる、ナンバー48とエドの死闘。「賢者の石」の情報をめぐり息もつかせぬ一進一退の攻防が続く。一方、研究所中庭でもまた、アルとナンバー66の戦いが始まろうとしていた…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f59413dd-2d21-427c-990d-f0e55c058b00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c85e6e2f-1c86-4971-8ba9-73fac5f19e94', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 22, '100035150', '造られた人間', '第五研究所の深部へとたどり着いたエド。そこではかつて錬金術の軍事転用の為に、大規模な生体錬成の研究が行なわれていた。研究所内に放置された、夥しい量の未完成の賢者の石と巨大な錬成陣。タッカーは、エドにそれらの材料を使用し、賢者の石を完成させることを提案する。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c45e35b4-6512-4206-a4c7-3360c5f928ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('352eb4af-91a3-4363-91bd-223ca34c4869', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 23, '100035151', '鋼のこころ', '朦朧としたまま、病院のベッドで目覚めた満身創痍のエド。アルもまた半壊した姿で部屋の片隅に置かれている。賢者の石に後一歩のところまで迫りながら、踏み切ることが出来なかったことがエドの心を締め付ける。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74a96419-0839-4003-ad9e-57f0c6b91cd4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62027068-2a43-4e59-ad6b-5936e04cc70b', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 24, '100035152', '思い出の定着', '自分の記憶も魂さえも偽りのものではないかとの疑念に囚われ、エドの前から逃げ出したアル。街角でただ立ちすくんでいた彼は、そこでイシュヴァール人の幼い兄弟、レオとリックと出会う。兄弟に連れられてイシュヴァールの隠れキャンプを訪れたアルは、思わぬ人物と再会する。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7fb668f9-1edc-4f3a-9c72-88bec4fa833d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e310e6c-657c-4632-a445-1213485408e2', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 25, '100035153', '別れの儀式', '皆を危険に晒すことなく、元に戻るための方法を探すエドとアル。2人はその可能性を求めて師匠に会うことを決め、道の途中にある機械鎧の聖地･ラッシュバレーが目当てのウィンリィと共に、ダブリスに向かう。一方、第五研究所と賢者の石について調査を続けていたヒューズは、ある事実にたどりつくのだが…。', '2026/02/01 00:00:00', 1540, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abc8dced-c02b-4b3b-8dae-141b69717f37.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cde83303-1c44-4703-8af2-5aaf6f06f0c7', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 26, '100035154', '彼女の理由', 'オートメイル生産のメッカ、ラッシュバレーに到着したエドとアル、そしてウィンリィの3人。街中に建ち並ぶオートメイル工房を前に、大はしゃぎするウィンリィ。3人はラッシュバレー名物オートメイルアームレスリング大会で、腕と両足が機械鎧の女の子パニーニャと出会う。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0f663df-6a86-4762-a99c-965795c56f72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a9295bc-fe59-4f6d-abab-139a5fdfa1f2', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 27, '100035155', 'せんせい', 'エドとアルがもっとも恐れる人物。錬金術の師匠であるイズミにラッシュバレーで捕まった2人。エドが「軍の狗」国家錬金術師になった事を知り、怒り心頭のイズミは、2人を引き連れてダブリスの街に向かう。一方、東方司令部のマスタングのもとには、セントラル異動の正式辞令が下っていた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad20b055-55a6-4124-9b84-dcf368e6213f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e0006b6-5ca1-46c6-beed-a7eef4dc2b35', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 28, '100035156', '一は全、全は一', 'エドとアルは、イズミにカウロイ湖の孤島、ヨック島に連れて行かれた。そこは、かつて2人が幼少の頃、修行をした場所であった。島には当時の痕跡がいくつも残されており、2人は昔を思い出しながらもう一度自分達を見つめ直していた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/001f8d08-0d23-4895-b4e6-5f2d9236e1e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('882e243d-f2da-40ae-93c1-24ed9a9bc499', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 29, '100035157', '汚れなき子ども', 'ヨック島で昔の事を思い出し、自分達の侵した過ちを悔やみながらもエドとアルは、それでも前に進むことを決意する。そんな時、無人であるはずの森の中から、錬金術を使う謎の少年が姿を現す。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7d88838-f714-47e9-90b6-a605de3fcd22.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1181dd55-fff2-47e7-8406-4824e6a854ee', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 30, '100035158', '南方司令部襲撃', 'イズミがヨック島から連れ帰ってきた少年。彼の右肩には古い傷跡があり、それはエドが幼い頃受けたものと酷似していた。エドの詰問に逃げ出す少年。一方、ヒューズの後任のフランク･アーチャー中佐はアームストロング少佐を供だって、エドたちの行方を捜し、ダブリスに到着していた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d9b037c-395f-407a-92e3-87f3d0c3d57c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf3febbe-7b98-4195-a045-098a6839ab72', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 31, '100035159', '罪', '右足にウロボロスの紋章を持つ少年。彼を巡り、南方司令部にて対峙する軍部、キンブリー、エルリック兄弟、そしてイズミ。一方、ロイは大総統より命を受け、スカーの身柄確保の為、軍を率いキシュア近郊のスラムに向かっていた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8aeab12c-3a05-47dd-8059-f8189ec52017.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2222d858-7dd6-464f-8cb2-2046c1258a2d', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 32, '100035160', '深い森のダンテ', 'エドの失われた右腕と左足を持つ少年、ラース。彼は、イズミが人体錬成に失敗した結果、生み出されたホムンクルスだった。ラースは人間になることを望み、そして残りの身体すべて奪うため、エドに襲い掛かる。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7ddfbe3-bf77-426b-92d0-e4b083d9b742.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('208e9c3d-5baf-4c3a-9b82-df1400cc2fb6', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 33, '100035161', '囚われたアル', 'ダンテの館で、グリード率いるキメラ軍団に襲撃され、連れ去られたアル。彼らの根城である、町外れの酒場デビルズネストに囚われたアルは、そこで、グリードから永遠の命の秘密について尋問を受ける。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/762d700a-a3a7-4f29-9396-98559351d679.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1ecdb33-3ad2-4ea9-8aa8-3e8d0b030160', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 34, '100035162', '強欲の理論', 'デビルズネストで展開される不穏分子殲滅作戦。アーチャー隊の兵士によって、グリード一派のキメラたちが次々と射殺されていく中、グリードは、キンブリーとタッカーの裏切り、そしてラスト、グラトニーの襲撃を受け、追い込まれていく。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7ac5035-6564-4603-8fc5-20cc0dabdce5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2b0c059-e9e1-407d-8e28-a8b7ad803ca4', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 35, '100035163', '愚者の再会', 'ラストは、偶然にも彼女の過去を知る人物、ルジョンと出会う。2年前、ルジョンは故郷の村を襲った原因不明の難病･化石病の治療法を見つけるため、錬金術の研究に明け暮れていた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b50bc9ba-e779-42c9-b737-9062099ae5d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f64e85e-2ab1-4583-aaea-bb37b6975ded', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 36, '100035164', '我が内なる科人 (トガビト)', 'かつてイシュヴァールで造られたという「賢者の石」。南部辺境の地で、軍によって護送中のイシュヴァール人に接触したエドとアルは、賢者の石について知る老人の存在を教えられる。エドとアルそしてウィンリィは、その老人の住むキシュアの街に向かう。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6320006c-9615-4cfa-89ce-a87c959d5275.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a16823b-bcd4-485c-9cf8-d0658e0ca3e5', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 37, '100035165', '焔の錬金術師／戦う少尉さん／第十三倉庫の怪', '軍内務課からマスタング大佐の監査命令をうけるハボック少尉。彼はブレダ、ファルマン、フュリーとともに「ロイ･マスタング観察日記」を極秘につけはじめる。そこで次々に明らかになるマスタング大佐の知られざる日常の姿とは!?', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d578c3a8-702e-4314-84f4-a3de0c476bcf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a4e1bb9-c958-4bc2-b262-5ac7c123eb39', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 38, '100035166', '川の流れに', 'イシュヴァールを目指し旅を続ける途中、エドとアルはスカーを止めるべきか、自分達の身体を取り戻すことを優先すべきかをめぐり仲違いしてしまう。一方、ヒューズの事件について1人調べていたシェスカは、ある仮説にたどり着く。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95d56ce7-5a5f-487c-b24c-362601a4d440.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fc291ba-999f-4c29-a47f-3671ccc44ad8', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 39, '100035167', '東方内戦', '旅の途中、マーテルはエドとアルにかつて自分が特殊部隊に所属していた過去について語る。そこで明らかになるイシュヴァール内戦勃発の真実。その頃、反抗勢力を鎮圧するために、アーチャー率いる軍隊がリオールに到着していた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b0eae6b-20f8-49ca-8d1a-4e73b5f83889.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae8b284f-367d-4e3a-9ffa-25efdf03d7ec', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 40, '100035168', '傷痕', 'グリード、そして仲間達を売り、軍部に寝返ったキンブリー。その憎き仇を見つけ出したマーテルは、アルの制止をはねのけ、一気に襲い掛かる。一方リオールでは、ついにエドとスカーが対峙していた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13663653-d112-4190-a765-80c5104c24e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80428b5a-9bf4-481a-8fa4-9bdb5bae93f1', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 41, '100035169', '聖母', '指導者を失い混迷し続けるリオール。その混乱に乗じ軍事的に制圧を目論む軍部。ついに鎮圧部隊は市街に進軍する。そしてスカーは、リオール内乱を利用し、「賢者の石」を完成させようとしていた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13dac529-b639-440a-acd8-67de9f372137.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f477a98-c077-4e55-a028-b73207669357', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 42, '100035170', '彼の名を知らず', '賢者の石を求めるものは、必ず滅びる。今また新しい伝説がリオールという1つの街を犠牲に、生み出されようとしていた。大総統の特命を受け、リオールの市街に攻め入るキンブリー率いるキメラ部隊。だが、その前にイシュヴァールでの復讐に滾るスカーが立ち塞がる。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4222a12c-f741-4163-a2fd-4909bd69711e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c22467b-71d1-4a45-8f85-db7007bd9d86', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 43, '100035171', '野良犬は逃げ出した', 'リオールの街から忽然と姿を消したエドとアル。「賢者の石」となったアルを追って、軍部が、そしてホムンクルスが迫る中、エドとアルはリゼンブールに向け、逃亡を続けていた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48417920-4649-4e6f-86ee-dd1beb4f416a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7afd331-7e20-43a9-97bc-4b097d5d6d88', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 44, '100035172', '光のホーエンハイム', 'リゼンブールに身を潜めているエドとアルの前にあらわれた意外な人物。それは十数年前に家族をおいて行方知れずになっていた2人の父･ホーエンハイムだった。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68f05f90-959c-49c8-8d12-7ec5ae72ad05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4815ef54-6b4a-494f-95e8-e0bbc9587a7a', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 45, '100035173', '心を劣化させるもの', 'セントラル旧市街。その地下に広がる巨大都市遺跡の一角。向かい合う光のホーエンハイムとダンテ。彼らに纏わる永き因縁。それは、400年前に遡る。彼らがついに辿りついた、あの日から…。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c3535a9-901a-4fa2-a2e8-9f4e91f9966e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a05ca1ec-e011-4322-9fe8-3756d7e86eda', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 46, '100035174', '人体錬成', 'ホムンクルスとの戦いを決意したエドは、ラースの弱点を手に入れるためイズミの元を訪れる。一方、残されたアルが、賢者の石の使用法を知る為に向かった場所。それはショウ･タッカーの隠れ家だった。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b03bd05-ad76-48eb-99a4-a3b1308e2ecb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcbc3242-b9c3-43f4-a620-c0d009828dcb', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 47, '100035175', 'ホムンクルス封印', '賢者の石となったアルを巡り、対峙するエドとスロウス。アルはいまだスロウスに母親の面影を感じ、惑う。侵した罪。本当の贖罪を、自らの手で果たす為、エドは今、スロウスに立ち向かう。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8d7e1b9-1ea6-454a-ae66-0d7e32d9d919.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b76bf8de-1d79-40db-9a4b-4492152a5b70', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 48, '100035176', 'さようなら', 'スロウスの構成物質をすべてエタノールに再構築したエド。それは自分達が犯した罪への避けては通れない道だった。一方、北方に送られた部隊では、不穏な空気が漂い出していた。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/18608eb1-7ff5-4aad-bcfe-026994f522c8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2abfca3-272a-42c0-ac72-4e27e04747e4', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 49, '100035177', '扉の向こうへ', '連れさられたアルを追って、セントラルに向かったエド。そこで再会したトリンガム兄弟より、エドは、第五研究所の先にあった、『賢者の石』に纏わる、巨大な研究場の所在を教えられる。', '2026/02/01 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6148c2ec-883c-4c90-a4cf-56669f8440ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07b54cc9-e2d9-4919-a4dd-7846dfe2dc8a', '1ce5e7bf-6ea4-4eb1-aa74-aea1ca413bb5', 50, '100035178', '死', 'ロゼの赤ん坊から出現した門に呑み込まれたエドは、門の向こう側の世界へと飛ばされる。そこは20世紀初頭のロンドンだった。混乱の中、街を襲うツェッペリンから逃げるエド。その頃ダンテはグラトニーにアルを食べさせ、完全な賢者の石を得ようとしていた。そして門の向こう側の世界では…。', '2026/02/01 00:00:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a80554c-9c7d-4ebd-b1b7-ce4334a81dee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7f69b769-d872-4384-9d9e-3248f1f61865', '鋼の錬金術師 FULLMETAL ALCHEMIST', '', 'hulu', 'fullmetal-alchemist-brotherhood', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92476ad5-5f43-46d8-9768-1d30bd5ebdb9.jpg?w=331&h=447&p=t', 'hulu', 2009, 1, 1, 'FINISHED', NULL, 5114, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('7372e6d4-85df-46c4-8183-a279299e8c41', '7f69b769-d872-4384-9d9e-3248f1f61865', 'hulu-fullmetal-alchemist-brotherhood-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2bf4ddf7-61e3-4b9e-b6b4-ea3e2dc450e3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff2c0d51-42d3-442e-a625-6b59605778a2', '7372e6d4-85df-46c4-8183-a279299e8c41', 1, '100035181', '鋼の錬金術師', '元国家錬金術師でありながらイシュヴァール殲滅戦後、反体制派に寝返った男「氷結の錬金術師」アイザック･マクドゥーガル。アイザックがセントラルに姿を現した。彼を捕縛するため大総統キング･ブラッドレイの命によりロイ･マスタング、そしてエドワード･エルリックと弟のアルフォンス･エルリックらが動き出すが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2bf4ddf7-61e3-4b9e-b6b4-ea3e2dc450e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef342f42-afe3-468e-b592-75f58bfed863', '7372e6d4-85df-46c4-8183-a279299e8c41', 2, '100035182', 'はじまりの日', 'エドとアルは、優しかった母を蘇らせるため、最大の禁忌とされていた「人体錬成」に挑む。だがそこで待っていたのは余りにも大きすぎる代償だった。ある日、絶望の淵に沈んでいた兄弟たちの前に一人の軍人が現れた。彼は兄弟たちに国家錬金術師への道を提示する。失ったものを取り戻すため、彼らの長い旅が始まった!', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1293db45-85dd-4733-9af2-22f31c3fb1bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4246e45-70d7-4e89-8ec4-b07cfebd4bed', '7372e6d4-85df-46c4-8183-a279299e8c41', 3, '100035183', '邪教の街', '「奇跡の業」を使うという教主の話を聞き、リオールという街にやって来たエドとアル。そのレト教教主であるコーネロは、等価交換の原則に反した錬金術を行っていた。ことの真相を探るべく知り合った少女、ロゼの案内でコーネロのもとを訪れるエドとアルだったが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/42ce9f28-431f-44a1-952b-af73d5d414ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2717189a-bbac-4c05-80d0-cf10c5305ce1', '7372e6d4-85df-46c4-8183-a279299e8c41', 4, '100035184', '錬金術師の苦悩', 'ロイより「綴命の錬金術師」ショウ･タッカーを紹介されたエドとアル。タッカーは人語を解する合成獣 (キメラ) の錬成に成功した生体錬成の権威であった。タッカー宅で資料を探す間、その娘であるニーナと親しくなるエドたち。一方、年に一度行われる国家錬金術師の「査定」日を前に、タッカーは焦りを募らせていた…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63e94909-03b0-4e55-a903-1c0be57bf3b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6502954a-8889-473d-b28c-9211609e95f6', '7372e6d4-85df-46c4-8183-a279299e8c41', 5, '100035185', '哀しみの雨', 'アメストリス全土を騒がす、神出鬼没にして国家錬金術師ばかりを殺害する謎の人物「傷の男 (スカー)」がイーストシティに現れた。エドとアルは、街中で偶然そのスカーと遭遇。問答無用で襲いかかるスカーに応戦するも、その超絶した体術と不思議な“破壊の右手”に圧倒されるエドとアルは…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7d21e94-b76e-4438-ab34-84a6eec81375.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36d8d0d9-b488-43f0-b1d1-0f6a44427172', '7372e6d4-85df-46c4-8183-a279299e8c41', 6, '100035186', '希望の道', '壊れた機械鎧を直すため、アームストロングとともに故郷リゼンブールへ向かうエドとアル。途中休憩した駅で、アームストロングは偶然一人の男を見かける。その男の名はドクター･マルコー。かつて軍の研究所で錬金術を医療に応用する研究をし、イシュヴァール内乱後、突如行方をくらました人物であった…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/047ed5a5-8123-4e79-aa15-d7e3feebe7a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3e7c145-5d43-4c10-9bf9-89f92e5177de', '7372e6d4-85df-46c4-8183-a279299e8c41', 7, '100035187', '隠された真実', 'マルコーの研究資料を探しに国立中央図書館第一分館へやって来たエドとアル。だが彼らが見たものは、全焼した分館の跡だった。マルコーの資料が本当に分館にあったかを確認するためエドたちは、分館の資料に精通しているという少女、シェスカのもとを訪れる。そしてエドたちは資料が焼けた分館にあったことを知り…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b95bc473-35f4-41e0-a81e-a08469bae6d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e31ba99-45c4-4712-b83e-fcb772736b8a', '7372e6d4-85df-46c4-8183-a279299e8c41', 8, '100035188', '第五研究所', '賢者の石の真実を探るため元第五研究所へ忍び込んだエドは、そこで床に描かれた賢者の石の錬成陣を発見する。その時、鎧に身を包んだ男、ナンバー48がエドに襲い掛かかる。一方、研究所の外でエドを待つアルも、鎧を纏ったナンバー66という男に襲われる。繰り広げられる激闘、その最中思わぬ事実が判明して…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf8ad494-6c73-45b9-90c4-57c98c68d75c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8adc394-c7cb-4aec-8968-9ebc2b06436e', '7372e6d4-85df-46c4-8183-a279299e8c41', 9, '100035189', '創られた想い', '第五研究所の戦いにより、機械鎧を破損したうえ、ひどい重傷を負ったエド。そしてアルはバリーが放った一言により心を乱されていた。「自分は兄さんに魂も記憶もすべて作られた偽者なのではないだろうか?」という拭い去れない疑惑は、徐々に波紋を広げ、崩れることのなかった兄弟たちの絆を綻ばせていくのだった…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f23448a-c4ff-4151-8ffb-8ca3f6be986d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8892d0fe-4a9a-4337-92e5-57af568d3d8e', '7372e6d4-85df-46c4-8183-a279299e8c41', 10, '100035190', 'それぞれの行く先', '病室にて第五研究所の顛末をアームストロングたちに話すエドとアル。人柱、賢者の石の錬成陣、そしてウロボロスの入れ墨を持つ者たち…。そこへ突然、大総統キング･ブラッドレイが現れる。彼はエドたちに、軍内部に大総統の自分ですら掴みきれない不穏な存在があること、事態が判明するまで全員行動を慎めと告げるが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/076c1449-a637-4f80-8580-4f33703cdbb6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e94adfeb-5b74-4c64-9433-ae8cecd4abb1', '7372e6d4-85df-46c4-8183-a279299e8c41', 11, '100035191', 'ラッシュバレーの奇跡', 'ウィンリィの希望で、ともに機械鎧技師たちの聖地「ラッシュバレー」を訪れたエドとアルだったが、到着早々国家錬金術師の証である銀時計をパニーニャという少女に盗まれてしまう。だがそれがきっかけとなり、エドたちはパニーニャや彼女の機械鎧の作成者ドミニク、そしてドミニクの家族らと思わぬ触れ合いを持つが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f18727ab-5723-45a5-bb2c-1bee84b3d8a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1627446-3a08-49c6-a488-cbf1663da782', '7372e6d4-85df-46c4-8183-a279299e8c41', 12, '100035192', '一は全、全は一', 'エドとアルは師匠のイズミとの再会を果たした。そんな中、エドはイズミより父、ホーエンハイムの消息を伝え聞くことに。その晩、イズミと初めて出会った時のことを思い出すエド。錬金術の腕を磨くためイズミに無理やり弟子入り志願したエドとアルだったが、二人を待っていたのは無人島での1ヶ月サバイバル生活だった…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db10c24d-f823-4cc9-9d56-cc214dd2643e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('464498c8-9ccd-4b40-aac5-8a1063ee8cab', '7372e6d4-85df-46c4-8183-a279299e8c41', 13, '100035193', 'ダブリスの獣たち', 'ついにセントラルへ異動となったロイ。一方、ホムンクルスたちに重傷を負わされたスカーも、セントラルへ向かうべく行動を再開する。その頃、真理の扉の記憶を取り戻すためイズミのもとに滞留するアルのもとに、「おまえの秘密を知ってる」という怪しげな一派が接触を図ってきた。彼らは全員キメラだというのだが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d22fb82-1659-4fc8-96cb-dfb775c6261e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43370774-78c9-4ce3-a4f9-c358c3784ae3', '7372e6d4-85df-46c4-8183-a279299e8c41', 14, '100035194', '地下にひそむ者たち', 'イズミの乱入によりグリードとの戦いは転機を迎える。だがそこへ国軍が突入し、グリード一派らの殲滅を開始する。アルを抱え逃げようとするグリードだったが、その前にブラッドレイ自らが立ち塞がり、ホムンクルスであるグリードを攻め立てる。その中、グリードはブラッドレイの眼に信じられないものを見つけて…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a4817b8-9390-4ceb-a812-629e2daf9069.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed421bcc-f21f-453f-9eaa-6e89bbf0e02b', '7372e6d4-85df-46c4-8183-a279299e8c41', 15, '100035195', '東方の使者', 'セントラルへ向かうスカーとヨキの前に謎の少女、メイが現れる。「錬丹術」という不思議な術を使う彼女は東の大国であるシンから、不老不死の法を求め、アメストリスへやって来たと話す。そんな一方、機械鎧の修理のためにラッシュバレーを訪れたエドとアルは、そこで行き倒れていた少年、リンと知り合い…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0467229-0bfd-4848-9b24-73a07dc5736a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c742561-8632-474d-a2b4-8c229e3fa4f4', '7372e6d4-85df-46c4-8183-a279299e8c41', 16, '100035196', '戦友の足跡', 'バリーとの接触でヒューズ殺害の真相を掴み始めたロイ。その動きはホムンクルスたちの知る所となる。その頃、ヒューズに会うためウィンリィとともにセントラルへきたエドとアルはマリア･ロスよりヒューズが死んだという衝撃の事実を告げられる。だがそれを知らないウィンリィは一足先にヒューズ宅へと向かってしまい…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f081ff4-9024-48d2-8d18-8b03b330bf09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75a166e7-f949-4978-bd7a-65fcff74a14c', '7372e6d4-85df-46c4-8183-a279299e8c41', 17, '100035197', '冷徹な焰', 'ヒューズ殺害の犯人として軍に拘束されたロス。そんな中、バリーがその留置所を襲撃し、居合わせたリンとロスを連れて逃亡する。軍より射殺も含めた捕獲命令が出る中、エドとアルもことの真相を探るべく中央司令部へと向かう。だがそれらの動きよりも先にロイがロスの前に立ちはだかり、彼女へ炎の閃光を走らせた…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e209044c-d0cd-416c-a950-307b9e10bae7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90c4fdba-32ca-4e21-9393-1bf150743a05', '7372e6d4-85df-46c4-8183-a279299e8c41', 18, '100035198', '小さな人間の傲慢な掌', 'ロイの命令で、セントラルにアルを残し、アームストロングとともにリゼンブールへ向かったエド。ところが到着早々、ブレダの手引きで伝説の王都、クセルクセス遺跡へと旅立つことに。大砂漠を越えて到着した遺跡にてエドはフーとも再会。彼の案内で遺跡奥深くに向かったエドたちは、そこで思いがけない人物と遭遇して…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c883d8ba-8a31-4ae1-8e7a-35c9562d24e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5b33eec-744e-4707-8635-b870e122ff72', '7372e6d4-85df-46c4-8183-a279299e8c41', 19, '100035199', '死なざる者の死', '自らの肉体を探すバリーを追って、ハボックやアルとともに第三研究所の地下へと潜入するロイたち。二手に分かれ進んだ先でハボックとロイは、彼らを始末しにきたラストと遭遇する。初めて明かされるホムンクルスの正体と秘密。戸惑いながらもロイは咄嗟の機転で大爆発を起こし、ラストを木端微塵に吹き飛ばすが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62d85f4b-2a05-43f0-8b7b-1a163bf48944.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b32aea9-191d-4e56-bf3d-76cc7058b23c', '7372e6d4-85df-46c4-8183-a279299e8c41', 20, '100035200', '墓前の父', 'エドとアルの父ヴァン･ホーエンハイムがリゼンブールへ戻ってきた。だが母トリシャに苦労をかけた彼に、エドは憎悪の感情を隠さない。エドたちが人体錬成を行ったことを知ったホーエンハイムは「それは本当にトリシャだったのか」と疑問を残す。翌日ホーエンハイムが村を去った後、エドはピナコと自宅跡へ向かい…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89a378e8-2f71-43a7-b44c-46c41972f9ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c462e119-a424-4163-9f2f-c55c3519ca7c', '7372e6d4-85df-46c4-8183-a279299e8c41', 21, '100035201', '愚者の前進', 'ロイとハボックのもとへ見舞いに訪れたエドとアル。そこで彼らは、ホムンクルスたちの根城と予想される範囲の一部に、大総統官邸が入っていることを知る。自分たちが相対している存在の巨大さに戦慄する一同。やがてホムンクルスらの秘密を探る兄弟のもとに、スカーがセントラルへ現れたとの情報がもたらされて…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28b07e2b-38a5-4112-9b50-feedb36d6f3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f582307d-a261-4249-886d-bc450d297fb7', '7372e6d4-85df-46c4-8183-a279299e8c41', 22, '100035202', '遠くの背中', 'ブラッドレイに斬られたランファン。リンが助けに入るが、彼もブラッドレイやグラトニーに追い詰められてしまう。一方、ヒューズの墓参りに行ったウィンリィはエドとアルがスカーと戦っていることを知る。急ぎ現場へと向かうウィンリィだが、そこで偶然、スカーこそ両親を殺した犯人であるという事実を耳にしてしまい…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00508094-8200-4169-922e-a7427d8c07eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ddd9fb29-5f6e-4fc3-b30c-160d73edd340', '7372e6d4-85df-46c4-8183-a279299e8c41', 23, '100035203', '戦場 (いくさば) の少女', 'ホムンクルスを捕らえるため、傷心のウィンリィを軍に託し、再びスカーとの戦いに赴くエドとアル。そんなエドたちと共闘するロイやホークアイらも現場へと動き出す。その頃、ランファンを抱えながら逃げ覆そうとブラッドレイと戦いを繰り広げるリンだが、グラトニーにより次第に逃げ場のない場所へ追い詰められていき…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f263daf-2eb7-4666-92fc-19244934b7fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8a463cb-25bf-4be0-9b37-bbecd55e6727', '7372e6d4-85df-46c4-8183-a279299e8c41', 24, '100035204', '腹の中', 'ホムンクルスのアジトに捕らわれの身のマルコー。彼はホムンクルスたちの目的が、アメストリス国民全てを巻き込んだ「国土錬成陣」の構築にあると考える。一方、暴走したグラトニーを止めようとするエド、アル、リンだったが、すべてを“飲み込む”グラトニーに成す術がない。その最中、リンは異様な気配に気づき…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1044b58-462a-4914-8be7-f0b25beec611.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de68af7a-77b8-47c0-aaf8-3093a11ef4ef', '7372e6d4-85df-46c4-8183-a279299e8c41', 25, '100035205', '闇の扉', 'グラトニーに飲み込まれてしまったエド。なんとかリンと再会するも、脱出の手がかりはなく途方にくれる。やがて彼らは、エンヴィーとも再会。エンヴィーはエドたちに、ここがグラトニーの腹の中であり、“お父様”が作った真理の扉の失敗作であることを教え、入ったら最後、二度と出ることはできないと告げるのだった…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/778a5be2-84ac-4da2-bb6e-5903b710772d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e869e4b-6e42-4e5c-b479-ce022f076fdc', '7372e6d4-85df-46c4-8183-a279299e8c41', 26, '100035206', '再会', '“お父様”に会うため、グラトニーとともにホムンクルスたちのアジトへ向かうアルとシャオメイ。途中、シャオメイを探すメイとスカーも、彼らの後を追い地下へと潜入する。一方、グラトニーの腹の中で、真の姿を現したエンヴィーと戦うエドとリンだが、エンヴィーの体を構成する人々の姿を見たエドは攻撃をためらい…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d677684d-44f1-4af6-b3a9-dba4a1b4e421.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8f7daba-99c4-45e3-a379-9810673614f8', '7372e6d4-85df-46c4-8183-a279299e8c41', 27, '100035207', '狭間の宴', 'どこかの村の祭り。ホーエンハイムに若い女が酒を持ってくる。彼女の名前はピナコ･ロックベル。酒を飲みながらピナコはホーエンハイムと、この国の在り方やエドたちの旅路について話し出す。そしてホーエンハイムの前に現れる一人の少女。ホーエンハイムそっくりの男の存在。彼らを取り巻く世界がおかしく歪んでいき…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce98a4e5-1c8c-4ecd-9cfc-a53d4de43bdf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1770f62-09d1-4b48-aa79-aecc28ae0801', '7372e6d4-85df-46c4-8183-a279299e8c41', 28, '100035208', 'おとうさま', 'グラトニーの案内で「お父様」の所へ着いたアルとシャオメイ。その時突然グラトニーの腹が裂け、中からエド、リン、エンヴィーが現れる。再会の喜びも束の間、彼らの前へ現れたお父様の姿に驚くエドとアル。その素顔はなんと兄弟たちの父、ホーエンハイムにそっくりであった。お父様は兄弟たちを厚く手当てするが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc2aeaf5-9b83-4e4a-a7fa-d346091b9874.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d96b461a-1bd1-4419-b4ca-f8ed7a7c620e', '7372e6d4-85df-46c4-8183-a279299e8c41', 29, '100035209', '愚者の足掻き', 'エンヴィーたちに捕まったエドとアルは、お父様の指示で中央司令部のブラッドレイのもとへ連れて行かれる。ロイよりホークアイ以下ロイの部下たちの異動話、そして軍上層部が敵側の手に落ちていたことを知らされるエドたち。エドはお父様の計画に加担しないため国家錬金術師の資格を返上するとブラッドレイに告げるが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ec69913-7652-4c04-9310-829c7d876927.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('adf9b516-4580-4e85-befb-e03fbd27c14c', '7372e6d4-85df-46c4-8183-a279299e8c41', 30, '100035210', 'イシュヴァール殲滅戦', '借りた銃を返しにホークアイを訪れたエドは、彼女に敵に対し銃が撃てなかった事実を告げる。そして銃を持つことの重さ、それをホークアイが甘んじて引き受ける原因となった、イシュヴァール戦について尋ねるのだった。時同じく、マルコーはスカーに、イシュヴァールで軍部が起こした出来事について話そうとしていた…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf10f8ad-6b7b-4323-901b-017619693928.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('894dafc5-6e62-4a3d-8a31-1be6b185bacd', '7372e6d4-85df-46c4-8183-a279299e8c41', 31, '100035211', '520センズの約束', 'エドは街中でアルと再会。イシュヴァール戦後、生きることを諦めず、「目的を果たしたその先」を見据え行動するロイやホークアイらの話をし、自分たちも失った体を取り戻す決意を新たにする。あの時変わらず力を発揮できた錬丹術に光明を見出すエドとアル。早速錬丹術を知ろうと、翌朝二人はメイの行方を探すのだが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c7d02d8-f65d-4ed8-be07-da594f567d0f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f97e38de-b69c-40a6-bee8-5f758e4213ef', '7372e6d4-85df-46c4-8183-a279299e8c41', 32, '100035212', '大総統の息子', 'ヒューズの墓の前で密かにグラマンと会うロイ。一方、メイの行方が掴めないエドのもとへアームストロングが来て、メイたちが北へ向かったことを教える。動き出そうとするエド、そんな彼にアームストロングは自筆の紹介状を渡し、北へ着いたら“ブリッグズの北壁”と称されるブリッグズ要塞の将軍に会えと指示して…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2efc42f6-49c5-47c3-8685-24704db81b58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bafcf3c6-4ada-4f35-b8a3-5dd05bfed5cf', '7372e6d4-85df-46c4-8183-a279299e8c41', 33, '100035213', 'ブリッグズの北壁', 'スカーとマルコーの跡を追って、西へと向かったキンブリーと捜索隊の一行。錯綜する情報の中で、キンブリーはスカーが西経由で北へ向かうと推理する。その夜、北へと走る貨物車に潜伏するスカー。そこへ突然キンブリーが現れる。兄を殺した張本人を目の前にして、スカーの怒りはすぐさま頂点に達して…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a87886f5-f73e-460a-acba-a45b86caeb8d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a0fb11f-bfce-4c8b-bbf4-fc0f7fd2ea47', '7372e6d4-85df-46c4-8183-a279299e8c41', 34, '100035214', '氷の女王', 'ブリッグズ要塞に辿りついたエドとアルは、そこの指揮官オリヴィエに自分たちがここに来た経緯と目的を話し、メイ捜索のための協力を願う。メイを見つけるまでの間、要塞内の仕事を手伝うことになったエドとアルは、補佐官のマイルズに要塞内を案内されながら、要塞を支配する“弱肉強食”の掟について聞かされて…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9c81405-e638-46a2-89a6-e93ad68a715b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b907bad-7a57-4b95-bad1-5a417976487c', '7372e6d4-85df-46c4-8183-a279299e8c41', 35, '100035215', 'この国のかたち', '襲撃してきたホムンクルス、スロウスに“ブリッグズ流”の反撃を始めるオリヴィエたち。翌日、キンブリーが近くの病院へ入院していると聞いたマイルズはそこへ向かいキンブリーと出会う。その頃、スロウスの掘ったトンネル内でオリヴィエに真実を話すエドとアル。そして彼らはこの国の成り立ちの異様さに気づき…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bdccd571-e265-42c3-bc10-30ad69eb4caa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d840aa67-5b9e-41c0-ab3b-6d299c04d032', '7372e6d4-85df-46c4-8183-a279299e8c41', 36, '100035216', '家族の肖像', '人気のない山中で一人佇むホーエンハイム。胸に指を突き立て、体内より赤い血の塊を解き放つ彼の脳裏には、在りし日の家族の思い出が甦っていた。その頃、軍の企みを聞き出そうとレイブンと談笑を続けるオリヴィエのもとに、スロウスの掘ったトンネル内を捜索していた一隊に異常が発生したとの連絡が入り…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05f27ab9-6b48-486d-bf4a-d0d2ab7fe88b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('daa9a433-ab33-49b3-a86a-626fe4da8ad9', '7372e6d4-85df-46c4-8183-a279299e8c41', 37, '100035217', '始まりの人造人間 (ホムンクルス)', 'ブラッドレイの策略でブリッグズ要塞へ連れて来られたウィンリィ。エドとアルは、改めて自分たちの存在がホムンクルスら、敵側の手の内にあることを強く感じる。一方、消息の途絶えた捜索隊を探すため、バッカニア率いる別隊がスロウスの掘ったトンネル内へと入った。彼らはなんとか奇跡的に二名の生存者を助けるが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b8e710ce-2802-4e29-a9ac-8c344107eb6f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f285b56-95c2-41c8-b2b6-699d3328057a', '7372e6d4-85df-46c4-8183-a279299e8c41', 38, '100035218', 'バズクールの激闘', 'スカーを捕まえるため、バズクールという街に来たエドたち。各所が手分けして探す中、エドとアルは、独自にスカーを、彼と一緒にいるメイ共々探し出そうとする。メイやマルコー、ヨキたちと再会するエドとアル。その頃、メイたちと別行動していたスカーの所へ、キンブリーの部下であるザンパノとジェルソが現れて…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f3a7f46a-41d5-452e-b049-92f01dfe4b51.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7801143-1732-4236-90f5-f48afef57497', '7372e6d4-85df-46c4-8183-a279299e8c41', 39, '100035219', '白昼の夢', 'エドとアルの奮闘により捕らえられたスカー。両親を殺した彼に、ウィンリィは傷の手当てを施す。「俺を許すのか」と尋ねるスカーに、「理不尽を許してはいない」と答えるウィンリィ。またイシュヴァールの血を継ぎながら「この国を変えるため」軍に居続けるマイルズの存在もスカーの心境に新たな変化をもたらして…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/905c27e0-efde-4817-9955-e16ed8e9ebe7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89224b14-cb85-40e2-a8ae-3dcbb288fa3a', '7372e6d4-85df-46c4-8183-a279299e8c41', 40, '100035220', 'フラスコの中の小人 (ホムンクルス)', 'ブラッドレイの命令で中央司令部へ召喚されたオリヴィエ。突破口を開くため、彼女は軍上層部に籍を置く。一方、中央司令部の食堂でホークアイと再会を果たしたロイは、彼女から伝えられた暗号から大総統の息子であるセリムの正体を知る。その頃、中央司令部地下ではお父様が在りし日の過去を夢見ていた…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/159f7652-7096-49c7-91c3-147e29bdd492.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7085d06-7956-465b-ae42-fe0ec31cdee8', '7372e6d4-85df-46c4-8183-a279299e8c41', 41, '100035221', '奈落', 'キンブリーとその部下たちを始末しようと動き出すマイルズらブリッグズ要塞の面々。キンブリーが一人になったところを狙撃しようとするマイルズたちだが、彼らの計画に気づいたキンブリーに実行直前で反撃に遭ってしまう。しかもエドの所には、キメラ化したキンブリーの部下、ダリウスとハインケルが襲い掛かってきて…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf428cdb-42bf-4f19-a30c-47d615eef2ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81ce8499-fc67-48da-90b4-c1c5030fc6bd', '7372e6d4-85df-46c4-8183-a279299e8c41', 42, '100035222', '反撃の兆し', '突如意識を失ったアルを抱え、道中の山小屋へ立ち寄ったウィンリィたち。そこで休憩がてら、メイとマルコーはスカーの兄の書を読み解こうと試みる。途中、意識の戻ったアルとマルコーの会話からヒントを得たメイはスカーの兄の書に細工を施し、そこに秘められていた一つの錬成陣に辿りつく。だが、その錬成陣はなんと…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e6c5737-c56e-4184-a2de-12adf294be66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92013660-fb87-4b8b-bd64-93992c902db5', '7372e6d4-85df-46c4-8183-a279299e8c41', 43, '100035223', '蟻のひと噛み', 'アスベックというイシュヴァール人たちのスラムに身を寄せていたマルコーたちのもとへ、エンヴィーがやってきた。応戦するマルコーやジェルソたちだったが、すんでの所で巨大化したエンヴィーにマルコーが捕らえられてしまう。そしてマルコーが犯した罪をあげつらい、エンヴィーはじわじわと彼を苦しめるが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6cadb912-cdd9-41ab-8ad0-73b011d3bb85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d9c03d5-9fdf-4923-b891-3b54cfd986c6', '7372e6d4-85df-46c4-8183-a279299e8c41', 44, '100035224', 'バリンバリンの全開', 'リオールにてホーエンハイムと再会したアルたち一行。アルはホーエンハイムに、これまでのいきさつや、エドが現在行方不明になっていることを話す。その頃、ノースシティの銀行に、エドの口座より金を引き出すダリウスの姿があった。彼はそのまま街の病院へと戻っていくが、その後を軍がこっそりとつけてきていて…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6586b26-6d00-4d07-a3c3-1e232e0824b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f552560-8efe-4651-a7ed-1ebe1b727078', '7372e6d4-85df-46c4-8183-a279299e8c41', 45, '100035225', '約束の日', 'シンへ帰るため東部の街、ユースウェルへ立ち寄ったメイは、人々から手厚いもてなしを受ける。アメストリスの人々を見捨て自国へ戻ることに躊躇していた彼女の心は揺れるに揺れる。一方、アルと再会するため、セントラルのロイの隠れ家を訪れたエドとダリウスたちは一時的に身体の主導権を取り戻したリンと再会するが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8ecaff1-7521-45eb-b974-1c20786bd5fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0535a073-4b4c-4396-b756-c8b259215ae2', '7372e6d4-85df-46c4-8183-a279299e8c41', 46, '100035226', '迫る影', '「約束の日」を前に、自宅へ戻ったウィンリィはエドと思わぬ再会を果たす。一方、マイルズと秘密裏に東部へ来ていたアルは、潜伏先で再び肉体に魂が引っ張られる感覚に襲われる。肉体のほうへ引っ張られる間隔が段々と短くなっていることに不安を覚えるアル。その最中、アルはなんとグラトニーに見つかってしまい…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5caf0562-b3cf-46eb-9f88-787e6a10185d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc48ddf6-e3bd-426b-9fb8-45a9fb72fe21', '7372e6d4-85df-46c4-8183-a279299e8c41', 47, '100035227', '闇の使者', 'カナマという集落にて、エドたち一行はホーエンハイムと再会する。エドはホーエンハイムより、彼の身体の秘密や、お父様が翌日起こる“日蝕”を利用して、真理の扉を開けようとしていることを聞かされる。その後、エドは彼にピナコより頼まれていた母トリシャからの遺言を伝える。それを聞いたホーエンハイムの反応は…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9eb1b79a-f263-4cdd-8d5f-d44a877132a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5913383-750a-4947-9ee2-a683ae3a2f80', '7372e6d4-85df-46c4-8183-a279299e8c41', 48, '100035228', '地下道の誓い', 'ランファンの手助けで、形勢逆転を果たしたエドたち。別の場所ではハインケルが倒れる気配のないプライドに苦戦を強いられていた。やがて周囲に明かりが灯され、封じていたプライドの影が復活してしまう。一方、マダム･クリスマスの手助けでセリムの正体を調べ上げたロイ。そんな彼に軍の密偵が忍び寄ってきていて…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2391337c-9748-429e-80b7-e6aa89ca7516.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('084b32e7-0d04-459f-9fd3-f83d104986a3', '7372e6d4-85df-46c4-8183-a279299e8c41', 49, '100035229', '親子の情', '非情な手段でグラトニーの能力を手に入れたプライド。その力の前にエドたちは成す術なく、追い詰められてしまう。その頃、別の場所でようやく息を吹き返したアルは、自分のせいで兄たちが窮地に陥っていることを知り、ホーエンハイムに一計を提案する。その提案を持って、ホーエンハイムはプライドと対峙するが…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56845adc-94ce-4ea8-bcbd-e5f688edd180.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d709eda7-6112-403d-891d-f045b62a6130', '7372e6d4-85df-46c4-8183-a279299e8c41', 50, '100035230', 'セントラル動乱', 'ブラッドレイ夫人を人質に取り、ついに中央司令部へ反逆の狼煙を上げたロイ。すぐさま鎮圧されると思われたその反乱は、ロイ一派の巧みな攻撃、そして予期せぬ所から出現したチャーリー隊やブリッグズ軍らの加勢により、激しい市街戦へと突入する。そんな中、ロイたちは反乱の協力者として思わぬ人物と再会して…。', '2026/02/01 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b0fec23-70cd-4b0d-9f26-76db1e24b72e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5d6f7745-e452-4a0d-8b45-46b9f73efcfd', '鋼鉄神ジーグ', '', 'hulu', 'steel-god-jeeg', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0280f064-cf5b-4156-b7a5-cfd4b608e7cd.jpg?w=331&h=447&p=t', 'hulu', 2007, 1, 1, 'FINISHED', NULL, 2157, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('354ddf74-6fed-4f73-89d0-aab7554a0251', '5d6f7745-e452-4a0d-8b45-46b9f73efcfd', 'hulu-steel-god-jeeg-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e25490fd-49e4-48d5-8fbd-79a9bc1c08ce.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4882d2d-9f48-4b54-a6d8-84a0c2f2b736', '354ddf74-6fed-4f73-89d0-aab7554a0251', 1, '100184578', 'ビルドアップ! 鋼鉄ジーグ!!', 'かつて、鋼鉄ジーグと邪魔大王国の最終決戦の地となった九州。そこはあの日より、謎の結界“ゾーン”に覆われ連絡不能となっていた。あれから50年…。“ゾーン”に遮られた九州を望む本州最南端の町。高校生ライダー･草薙剣児は突如、地中から現れたハニワ幻神･魔愚羅 (まぐら) と遭遇して…。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e25490fd-49e4-48d5-8fbd-79a9bc1c08ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c39e125a-1900-4988-b2f5-0b0ea642a6e4', '354ddf74-6fed-4f73-89d0-aab7554a0251', 2, '100184579', '蘇る妃魅禍! 復活! 邪魔大王国', 'ビッグシューターから射出されたパーツで鋼鉄ジーグにビルドアップした剣児。魔愚羅 (まぐら) との戦いの中、広がったゾーンの中に飲み込まれてしまう剣児たち。その頃、阿蘇の地中深くでは、かつてのジーグに封印された邪魔大王国の女王･妃魅禍が復活を遂げて…。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/919fc144-7d85-4df2-95f9-a885dd55c7e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9ada0bb-2bbf-4ea5-aa3b-684693c9943c', '354ddf74-6fed-4f73-89d0-aab7554a0251', 3, '100184580', 'じゃじゃ馬ならし! 炸裂! 地獄ビンタ', '未だ状況を把握し切れていない剣児に、50年前のジーグと邪魔大王国の戦いについて語る珠城司令。ジーグと同調できるのは自分だけだと知り、自分が選ばれし者であると調子に乗る剣児。一方、妃魅禍は新たなるジーグの中に銅鐸 (どうたく) の存在を感じ、ハニワ幻神･馬頭羅 (めずら) を博多に出現させる。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/29e6b725-4cd8-4611-ac84-75ff88425a32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73a8819f-4e3d-4a40-bbc8-3aafcd54f2fe', '354ddf74-6fed-4f73-89d0-aab7554a0251', 4, '100184581', '決死の水中バトル! 列車砲 (ギガシューター) 準備よし!!', 'ゾーン内の現状の把握と、設備の復旧を急ぐビルドベース。見守るしかない剣児は雷鋼馬で偵察に出かける。珠城司令と司馬遷次郎はデータ収集のため、ゾーン内にあった旧ビルドベースの調査を敢行する。旧ビルドベースを訪れた珠城司令と遷次郎はゾーンの中が時間が止まっていたかのように50年前と全く変わっていないことを知る。一方、妃魅禍配下の黄泉軍兵に抵抗を続ける自衛隊員たちに会う剣児。そこに、海中からハニワ幻神･加治羅 (かじら) が迫る。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0c57192-160a-4198-a7d5-7cb80b4375a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2154b481-c235-4136-822c-0d0f21ad47c7', '354ddf74-6fed-4f73-89d0-aab7554a0251', 5, '100184582', '無我夢中?! 恐るべし、邪魔大王国の罠', 'ハニワ幻神･罵玖羅 (ばくら) との戦いから戻った剣児たちはビルドベースの食堂でくつろいでいた。不意に奇妙な感覚にとらわれる剣児たち。まるで夢を見ているかのように幼い日の思い出の中に入っていく剣児とつばき。鏡も不思議な古代の幻影を見ていた。柳生も早乙女も身堂も、いつしか不思議な日常の中にとらわれ違和感を覚え始める。戦闘に出た者だけが、知らず知らずのうちに奇妙な世界に引き込まれていた。繰り返す日常。なにかが違うと気づいた剣児は、その世界からの脱出を試みるが…。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e39a07a-adea-403f-ac0e-e16b561b058a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23497027-5624-449a-be84-684e782d32fd', '354ddf74-6fed-4f73-89d0-aab7554a0251', 6, '100184583', '摩訶不思議! 大黒様もビルドアップ!', 'この先、剣児の気合だけの闘いでは危険だと感じ、もっとジーグを理解させ、無理のない戦闘をさせようと個人授業を始めるつばき。しかし、剣児は机に座るとすぐに居眠りをする始末…。困っているつばきに、剣児をその気にさせるならいい方法があると身堂たちが持ちかける。剣児が特訓をクリアしたらご褒美をやるといい、その気にさせる柳生。スケベ心から、俄然、やる気を出す剣児。そんな時、邪魔大王国の阿磨疎 (アマソ) と壬魔使 (ミマシ) がハニワ幻神･魔可羅 (まから) を率い出現する。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81f0bff7-7003-4d80-9866-d97e8534ffac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8af4b0f-7282-48a8-bfbd-5da5be45b839', '354ddf74-6fed-4f73-89d0-aab7554a0251', 7, '100184584', '侵入! 高千穂の峰へ! 霧の大地にヤツを見た!', '50年前の最終決戦の日から謎のエネルギーが滞留し、もっとも濃度の濃い高千穂周辺。美和もその場所の調査が重要であると感じていたが、常識を遥かに上回る高重圧反応に調査隊を差し向けることを躊躇していた。そんな時、遷次郎に来客が訪れる。妻の菊江と娘のまゆみだった。二人はゾーンの中の九州で生きていた。宙のことを聞かれ、答えられない遷次郎。宙がいる可能性のもっとも高いのも高千穂の峰だった。高千穂の高重圧反応が突然収まり、美和は調査を決断する。霧に霞む高千穂の火口で剣児たちが見たものは…。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0251f761-64c0-4cf0-af34-157ea10f3f53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab579d55-ef58-4654-8390-58b45afa440b', '354ddf74-6fed-4f73-89d0-aab7554a0251', 8, '100184585', '愛の力でジーグを狙え! 換装完了高度1万メートル!', '高千穂で発見されたのは首の無い宙のジーグだった。宙はどこに…? コクーン化したジーグヘッドは壱鬼馬 (イキマ) が八岐之大蛇に持ち帰っていた。ジーグヘッドから銅鐸を取り出そうとする妃魅禍 (ヒミカ) だが取り出せない。壱鬼馬はもう一つの銅鐸が手に入れば二つの銅鐸の共鳴により取り出せるに違いないと考え、ハニワ幻神･徒鼻羅 (とびら) で剣児のジーグの銅鐸を狙う。空を高速で飛行する徒鼻羅に翻弄される剣児。ギガシューターにスカイパーツを装填するが、余りにも速い敵の動きに換装ポイントが定まらない。早く換装しないと、剣児が危ない…! その時、つばきの潜在能力が…。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/486b1f15-1ed3-4662-a923-cb09ca758f08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc097b0c-8f82-4151-85a0-d033c4963825', '354ddf74-6fed-4f73-89d0-aab7554a0251', 9, '100184586', '非情なる策略! ビルドベース殲滅作戦!', 'ハニワ幻神･玄武羅 (げぶら) でビルドベースに全面攻撃を敢行する壱鬼馬 (イキマ)、壬魔使 (ミマシ)、阿磨疎 (アマソ)。防御力の高い玄武羅に手を焼くビルドベース。このまま玄武羅の接近を許せば、ビルドベースは壊滅的なダメージを受ける。攻防戦に苦戦するジーグたち。しかし、妃魅禍 (ヒミカ) たちの狙いは別にあった。つばきの能力に気がついた妃魅禍は、その能力を利用して、宙 (ひろし) のジーグヘッドから銅鐸を取り出そうとつばきに狙いをつけていた。ビルドベース総攻撃は囮だったのだ。アースパーツで玄武羅を砕くジーグ。だがその時、つばきのビッグシューターは無数の火焔偶 (かえんぐう) に取り囲まれていた…!?', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba80ca0a-0f99-4e29-844c-445d63cd505b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ac6593a-0087-4eb8-9819-040539fe2cad', '354ddf74-6fed-4f73-89d0-aab7554a0251', 10, '100184587', '囚われたつばき! 邪悪なる妃魅禍の儀式!', '捕まったビッグシューターを破瑠覇 (バルバ) とともに追うジーグ。阿蘇でジーグを待っていたのは、これまで見たこともない数のハニワ幻神の軍団だった。つばきと鏡を救うため、必死で戦う剣児。しかし、ジーグの追撃を予想していた壱鬼馬 (イキマ) は、邪魔大王国の奥義･万象羅偶 (ばんしょうらぐう) を発動させる。倒したハニワ幻神の残骸が集まり、超巨大ハニワ幻神となり立ちふさがる。だがその時、破瑠覇と感応した剣児のジーグは破瑠覇にスルーインし、バルバ･ジーグとなった! さらなる力を得て、万象羅偶を打ち砕くジーグ。だが、祭壇に飛び込んだ剣児が見たのは、妃魅禍 (ヒミカ) の依り代になっているつばきの姿だった。', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88b19318-0428-4c37-9603-c7404ba8922b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa1794e0-9382-47ed-88ac-872ac9e164d7', '354ddf74-6fed-4f73-89d0-aab7554a0251', 11, '100184588', '月を睨め! 惡を断つ、不屈の想いで!', 'つばきと宙を救出したものの、阿蘇に散った鏡…。二つの銅鐸のパワーを得た妃魅禍が、遂に結界の呪縛から解き放たれた。そして、九州全域に大空爆を行った妃魅禍は、八岐之大蛇で何処かに消えてしまう。 ビルドステーションの大利博士と連絡をつけた遷次郎は、すべての残存兵力を率いてビルドシャトルで宇宙に飛び立つ!', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2d4aa2c-02ed-46f0-97c8-c79c51796d08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2348d98-d7f2-4ebb-80e8-d631a7033af1', '354ddf74-6fed-4f73-89d0-aab7554a0251', 12, '100184589', '最終決戦! 大銅鐸、立つ!', 'ビルドステーションに集結する防衛軍の残存兵力たち。銅鐸が無く、ジーグになれない剣児と宙 (ひろし)。唯一残る妃魅禍 (ヒミカ) に対抗し得る手段は、銅鐸の真理にもっとも近いと思われる剣児とつばきが、真の意味で銅鐸と共鳴を果たすことだった。月面に潜む敵の本拠･ラングーンへの突入を命じる美和。だがその頃、すでに妃魅禍は二つの銅鐸の力を使い、さらなる力を我がものとするための儀式を行っていた。壱鬼馬 (イキマ)、阿磨疎 (アマソ) の率いるハニワ幻神軍団との全面対決の火蓋が切って落とされる! 柳生たちビルドエンジェルの協力を受けながらラングーンに突入する剣児、つばき、宙。剣児がその中で目にしたものは…!?', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f47eed63-7647-43e0-996d-b68f5368870f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38eda505-6ad0-4d99-9d67-f07a7d1c4c4c', '354ddf74-6fed-4f73-89d0-aab7554a0251', 13, '100184590', '鋼鉄神になれ!!', '剣児とつばきの想いが大銅鐸と共鳴したことにより、新たなる銅鐸を生み出したつばき。剣児と宙のジーグが復活した。ハニワ幻神を蹴散らすWジーグ。しかし、すでに大銅鐸の力を我がものにした妃魅禍 (ヒミカ) は様々なパワーを使い、Wジーグを翻弄する。剣児が、つばきが、宙が、美和が人類の未来を懸けて戦う! 剣児たちの決死の攻防に最終兵器を起動する妃魅禍。だが、大銅鐸から生まれ落ちたそれは、妃魅禍の想像すら遥かに超える存在だった…! 怒涛の最終回。剣児よ、鋼鉄神になれっ!!', '2024/06/13 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b41e494-68fb-4b6d-9c77-2a2f6229512f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5fdbb594-65e6-4652-ad85-ab2b35dd3901', '合コンに行ったら女がいなかった話', '', 'hulu', 'how-i-attended-an-all-guys-mixer-anime', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ba65fe7-bb8f-4c6a-acd9-f422f4350b6f.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 169931, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('64789ff3-b66e-426b-87d8-63f4df17965d', '5fdbb594-65e6-4652-ad85-ab2b35dd3901', 'hulu-how-i-attended-an-all-guys-mixer-anime-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bcd02135-13fe-4518-966a-c41c0b618358.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d165af99-3e4e-4a75-84b5-b547a6a4ece1', '64789ff3-b66e-426b-87d8-63f4df17965d', 1, '100201259', '合コンに行ったら××だった話', '同じゼミの女子･蘇芳 (すおう) さんに合コンに誘われた大学生の常盤 (ときわ)。同じく合コン初体験の友人･浅葱 (あさぎ) と萩 (はぎ) を連れて、胸を高鳴らせながら待ち合わせの居酒屋へ。女性陣が先に着いたことを知って、急いで席に向うと…そこには、まばゆく輝く3人のイケメンたちが。男6人と女0人の少し変わった合コンの幕が上がる!', '2024/10/05 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bcd02135-13fe-4518-966a-c41c0b618358.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa627c3a-f01b-493c-ac2b-709108e93431', '64789ff3-b66e-426b-87d8-63f4df17965d', 2, '100202135', 'BARに行ったら××だった話', '藤 (ふじ) に呼び出され、漫画の資料撮影をすることになった浅葱 (あさぎ)。一方、萩 (はぎ) は街で琥珀 (こはく) と偶然出会う。突然降り出した雨により、二人きりで雨宿りをすることに。そして、あの少し変わった合コンから数日後、常盤 (ときわ) たちは蘇芳 (すおう) たちのバイト先である「男装バーRose」に初めて足を踏み入れることになる。', '2024/10/12 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4c20829-14c0-487d-962f-1f70662c182c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18280ec2-ae8f-4a5d-bacc-f51be9a58e06', '64789ff3-b66e-426b-87d8-63f4df17965d', 3, '100202855', '居酒屋に行ったら××だった話', '「あの時の借りは必ず返す。忘れんじゃねぇぞ」そう言われ琥珀 (こはく) に呼び出された萩 (はぎ) は、恐る恐る待ち合わせに向かうのであった。一方、浅葱 (あさぎ) は頼みごとがあると藤 (ふじ) の自宅に呼び出される…。常盤 (ときわ) は課題を手伝ってもらったお礼がしたいと蘇芳 (すおう) に申し出る。「二人で飲みに行きたい」と言う蘇芳 (すおう) の希望から、二人は居酒屋に行くことに…。', '2024/10/19 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b27593e-140c-4840-9a53-7cc86bf1bfcc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('837f839c-3ddc-4a27-8b28-168fab1cbc62', '64789ff3-b66e-426b-87d8-63f4df17965d', 4, '100203713', '動物園に行ったら××だった話', '「週末みんなで遊びに行こう」蘇芳からそう言われ、目的地もわからぬまま待ち合わせ場所に集まる常盤 (ときわ) ･浅葱 (あさぎ) ･萩 (はぎ)。するとそこに、蘇芳 (すおう) の運転するワゴンがやってくる。道中終始、蘇芳 (すおう) のイケメンオーラに圧倒される常盤。やがて車は動物園に到着し…。', '2024/10/26 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc8d83a3-368d-48bf-8170-204a08d97c9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c393614-5137-41d1-a243-37e888d03249', '64789ff3-b66e-426b-87d8-63f4df17965d', 5, '100204349', 'コミケに行ったら××だった話', '藤 (ふじ) から“お祭り”に誘われる浅葱。しかし行ってみるとそこはコミケ会場だった。藤 (ふじ) の「西1026aにいる」という暗号のようなメッセージに戸惑いながら会場をさまよう浅葱 (あさぎ)。ようやく藤 (ふじ) と合流できたものの、しばらくブースを空けることになった藤 (ふじ) の代わりに浅葱 (あさぎ) は、人生初の売り子をすることに…。', '2024/11/02 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa0d5c48-61cf-4dd3-bc5a-6e9863fefced.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15750edd-94ec-410c-84ae-ef5f08fa9a47', '64789ff3-b66e-426b-87d8-63f4df17965d', 6, '100204995', 'おうちに行ったら××だった話', '男装した琥珀 (こはく) にときめき、自分の気持ちが良くわからなくなる萩 (はぎ)。見かねた常盤 (ときわ) と浅葱 (あさぎ) は、萩 (はぎ) を連れて「男装バーRose」に向かう。バーで琥珀 (こはく) と話すうちに自分の恋心に気づいた萩は、悶々とした日々を過ごすことになる。そんな萩 (はぎ) を心配した琥珀 (こはく) は、蘇芳 (すおう) たちのアドバイスから萩 (はぎ) の家を訪ねることに。玄関先で話し始めたその時、思わぬ事態が…。', '2024/11/09 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a73d14d-2239-4ec3-93bd-bbdf69a2036b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c0bf6c4-d2a3-4e1f-ac15-ea80fa575963', '64789ff3-b66e-426b-87d8-63f4df17965d', 7, '100205942', 'キャンプに行ったら××だった話', 'キャンプにやってきた6人。蘇芳 (すおう) たちの気づかいで、琥珀 (こはく) と二人きりになった萩 (はぎ) は琥珀 (こはく) の誤解を解くことに成功する。大自然の中、バーベキューを楽しむ。その夜、空に浮かぶ月を見上げながら常盤 (ときは) と二人きりになった蘇芳 (すおう) は、大胆な行動に出る。', '2024/11/16 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a3a9c18-c181-4056-940d-3e4182bfae21.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1c99c15-5ecb-464c-8a80-d1228bd6ba9c', '64789ff3-b66e-426b-87d8-63f4df17965d', 8, '100206969', 'キャンパスに行ったら××だった話', 'ある日、大学内で男装していない蘇芳 (すおう) と歩く姿を、千草 (ちぐさ) と撫子 (なでしこ) に目撃された常盤 (ときわ)。「プリンスとその女性、どっちを選ぶの!?」と問い詰められてしまう。一方、Roseで藤 (ふじ) と二人きりになった浅葱 (あさぎ) は、流れでバーの制服を着て接客することに…。', '2024/11/23 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0a83441-ab59-43a2-b560-9f76e2ab2c72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63c3d28c-d51d-4eab-95d7-8f3e2cbc741b', '64789ff3-b66e-426b-87d8-63f4df17965d', 9, '100207706', '夏祭りに行ったら××だった話', '琥珀 (こはく) を夏祭に誘う萩 (はぎ)。その様子を影から見守ろうと他4人も出かける事になるが、2人を見つけられずに蘇芳 (すおう) と常盤 (ときわ)、藤 (ふじ) と浅葱 (あさぎ) の2組に分かれて夏祭りを楽しむことに。その頃、緊張しながら琥珀 (こはく) を待つ萩 (はぎ) だったが、待ち合わせ場所に現れたのはなんと男装していない浴衣姿の琥珀だった…。', '2024/11/30 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59ce28ab-f0db-4c42-858f-41d6b094787d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42ce56a6-65f0-4414-8cf9-d1f076e4be3d', '64789ff3-b66e-426b-87d8-63f4df17965d', 10, '100208942', '自宅に行ったら××だった話', 'ある日、藤 (ふじ) からの一言を気にしてカッコよくなりたいと決意する浅葱 (あさぎ)。琥珀 (こはく) の俺様キャラを参考に藤 (ふじ) を見返そうとする。様子がおかしい事に気がついた藤 (ふじ) は、浅葱 (あさぎ) を自宅に連れて行く。一方、バーの激務で体調を崩した蘇芳 (すおう) を、家まで送り届けた常盤 (ときわ)。一度は別れたものの心配になって引き返すと、蘇芳 (すおう) は玄関先で倒れていて…。', '2024/12/07 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e4c8d39-54ef-4311-985f-6ac1c10f6473.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e586eaa5-1198-4a7f-b4b3-b03833acf518', '64789ff3-b66e-426b-87d8-63f4df17965d', 11, '100209913', '海に行ったら××だった話', '琥珀 (こはく) のお願いで海の家を手伝う事になった5人。萩 (はぎ) は、琥珀 (こはく) が働く様子を見ながら、自分の気持ちに整理がつかず、一人からまわる。一方、海らしい事をしたい蘇芳 (すおう) は常盤 (ときわ) を連れ出すと、カップルの男性が浜辺で日焼け止めを塗ってあげているのを見て「私たちもやろうか」と言い出す。', '2024/12/14 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89ab335d-5031-4d03-836c-e2c30215ff37.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37048236-e1bb-48f0-812b-86187db4908f', '64789ff3-b66e-426b-87d8-63f4df17965d', 12, '100210961', '合コンに行ったら●●だった話', '【シーズン1 最終話】夜の浜辺で琥珀 (こはく) と二人きりになった萩 (はぎ) は、これまでの心のモヤモヤをあくまで友人の恋愛相談として打ち明ける。一夜明け、浅葱 (あさぎ) と萩 (はぎ) が起きてこないなか、一人で名所巡りに出かけた常盤 (ときわ) は蘇芳 (すおう) に偶然出くわす。一緒に観光をして回る二人は最後に『願いを叶える鐘』と呼ばれる観光スポットに辿り着く。', '2024/12/21 02:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f774545-4f9a-459d-bac3-8d47c9beb46f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3b4d44bc-3370-4acc-a205-4811f87273dd', '拷問バイトくんの日常', '', 'hulu', 'the-daily-life-of-a-part-time-torturer', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e8a6f3d-8e74-4178-8c03-a06859702bf0.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'FINISHED', NULL, 197731, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8e6e4d77-8da9-4e9e-9d41-00ae6d438978', '3b4d44bc-3370-4acc-a205-4811f87273dd', 'hulu-the-daily-life-of-a-part-time-torturer-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afa9742b-7b80-4951-b4c2-fb7de84d8fb2.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b69be2f1-ead5-4608-a181-395a36b50b4b', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 1, '100250175', 'バイト1日目', '拷問請負業者「スピリタス」のアルバイト･セロは、今日も強情な悪党を相手に仕事に励む。頼もしい先輩･シウと並んでタバコを吹かす時間が、ご褒美だ。そして人手不足で困っていたところに、ミケとヒューという2人の新人がやってきて……。', '2026/01/10 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afa9742b-7b80-4951-b4c2-fb7de84d8fb2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ffd7e69-058c-4ec9-a2bd-bc7f26c83c21', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 2, '100250787', 'バイト2日目', 'セロとシウのアドバイスを受けながら少しずつ成長していくミケとヒュー。2人は同じ後輩組として、親交を深めていく。一方、セロが休日にパチンコをしているとシウから「5分で来い」という連絡があった。急いで街の一角へ向かうと、そこには……。', '2026/01/17 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9041ddbe-014f-4d22-b527-4d2b5fde4ad8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3070e1c4-05dc-40c6-856a-09be75c69343', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 3, '100251482', 'バイト3日目', '「じゃあ、うちの社長って珍しいんだ!」。ミケの無邪気な一言から明らかになる、美貌の社長･ヘラの真実とは? そして、社員のノエはどうしてセロといがみ合うのか? また、あるとき仕事熱心だったセロが理由も言わずに会社を休み始めて……。', '2026/01/24 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0df8b75-2564-4f35-bbea-8906098148ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d942e9d-4e18-4afd-bf02-9d10047c5d1c', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 4, '100252110', 'バイト4日目', '「コロッケ」案件が担当できて、ホクホクのミケ。仕事を終えると、屑屋のフォンがやってくる。人当たりの良いフォンだが、笑顔の裏にはセロも警戒するヤバさがあった。また、ある日のこと、会社の近くをうろつく不審者を捕まえると、それはセロの弟ルクだった。彼が会社に来た理由とは……?', '2026/01/31 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/027fd1cd-461a-4c77-b6d9-ade70b956bfe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba2d8aae-1a17-42c4-be34-12725e050a81', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 5, '100252731', 'バイト5日目', '大学で学んでいる現代拷問学のレポートに悩んだヒューは、友人･ラスの助言でセロたちに話を聞いてみることに。すると事態は「第1回ドキドキ拷問クイズ大会」へと発展!? また、ある日には、スピリタス社員&バイト一同がビーチへ! シウはヘラが何か企んでいるのではないかと怪しむが……?', '2026/02/07 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d8fcb3f-9e17-4c42-af4c-a729c9f3f4c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93a59933-0ef9-4c28-941f-82b1bc81cfa0', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 6, '100253269', 'バイト6日目', '悩んでいた小説が書けて、拷問後の掃除も楽しく、ご機嫌のミケ。そこへ、掃除屋のリーシェがやってくる。防護服にガスマスク姿で内気なリーシェだが、ミケのことが気になるようで……。またある日、拷問の依頼と殺しの依頼のダブルブッキングが発生。やってきた殺し屋のマニカは、セロの〝元カノ〟だった。', '2026/02/14 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f989c12-96bc-4b58-badf-e96041e31fc6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08c63f36-6ca7-49aa-8010-f2f5fd7a0f48', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 7, '100253849', 'バイト7日目', '弟･ルクの部屋で、現代拷問学部の大学パンフが目に入り動揺するセロ。うまく話を切り出すことができないまま、ルクと2人で町へ買い物に行ったセロは、偶然シウと出くわすのだった。またある日、シウはセロを連れて娘たちが通う小学校の学習発表会へ行く。シウはママさんたちに驚異の馴染みぶりで……。', '2026/02/21 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca93aec6-79c7-4622-8cf6-d04d03742800.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf785f6d-2fba-4780-a1f0-10b9c4c916e2', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 8, '100254757', 'バイト8日目', '拷問を受ける前に気を失ってしまった悪党のために、医者のイズアが駆けつける。イズアは、ついでにヘラとシウも診ていくと言うのだった。また、指を怪我したミケは看護師のメリムの手当を受ける。メリムはぬいぐるみのアムムを介して話す女の子で……?', '2026/02/28 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9024898-13fb-4f78-9a68-e3d8bc260271.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be720255-667a-40a8-8ca9-0621350f88ed', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 9, '100255498', 'バイト9日目', '桜が満開を迎え、仕事終わりにお花見へ行くことを決めた4人。だがそこへ、急ぎの案件が入ってしまい……。またある日、先輩たちからプレゼントをもらい張り切っていたミケとヒューが、仕事で大失敗をしてしまう。落ち込む2人に、フォンは「君たちには何か信じられるものがある?」と問いかける。', '2026/03/07 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89789eff-5b67-4820-a613-83890a0e6ec3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81013ba6-8683-4a6d-ac0d-0abe9799b55d', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 10, '100256437', 'バイト10日目', '普段は拷問を仕事にしているスピリタスの従業員たち。しかし今宵だけは――王子様に変身!? ヘラが懇意にしているホストクラブ「NOX」で働くことになった4人。そこは、セロのかつての職場で……。またある日には、謎の缶飲料を飲んだシウたちの見た目が幼児化してしまって大パニック!', '2026/03/14 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fba2a690-b40e-49fe-a75d-05769a491e72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0503ddd9-bbd6-4079-8ed9-3a8e1bb7d3ba', '8e6e4d77-8da9-4e9e-9d41-00ae6d438978', 11, '100256878', 'バイト11日目', 'ベルタが貸してくれた店の商品を使って、勉強に励むミケとヒュー。ある日、セロが危険な組織の報復によって負傷してしまう。しかし、なぜかシウはセロに怒っていて……。そんなこんなもありながら、社員&バイト一同は慰安旅行で温泉へ! ミケは前々から気になっていたあることをシウに尋ねる。', '2026/03/21 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64add500-dcef-4c6b-919c-4919c780eb7d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('aeeb629a-448c-4b94-accd-ce247b317d14', '黒の召喚士', '', 'hulu', 'black-summoner', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da583cde-0fdc-40f0-9fc6-a61a27654ac9.jpg?w=331&h=447&p=t', 'hulu', 2022, 2, 1, 'FINISHED', NULL, 145260, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1d171689-ede8-4afb-abab-9f968013af6d', 'aeeb629a-448c-4b94-accd-ce247b317d14', 'hulu-black-summoner-s1', '第1シーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/973661ec-c012-455f-9c68-8d6a779505d3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12fd3442-3880-4221-8008-09608643fd1f', '1d171689-ede8-4afb-abab-9f968013af6d', 1, '100117668', '記憶を無くした転生者', '神様の手違いの事故により死んでしまった青年は、女神との契約により「ケルヴィン」として異世界に転生した。転生前の記憶や思い出などを引き換えにして得た豊富な初期スキルに加え、国に一人いるかいないかの希少な職業である「召喚士」のケルヴィンは、転生を司る女神･メルフィーナとともに、冒険者として新たな人生の幕を開ける。', '2022/07/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/973661ec-c012-455f-9c68-8d6a779505d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('005f5aea-b5a2-4d2a-95fd-798c37f41b3e', '1d171689-ede8-4afb-abab-9f968013af6d', 2, '100118140', '黒霊騎士', 'ブルースライムのクロトを仲間にし、無事依頼を達成したケルヴィンは、E級冒険者に昇格し、冒険者ギルドで次の依頼を探していた。すると、依頼を終えたD級冒険者のカシェルに、他の個体と比べて強力な黒霊騎士の討伐に誘われる。彼の不穏な称号に気づきながらも、あえて誘いに乗るケルヴィンは、黒霊騎士のいるダンジョン内でカシェルたちと合流し…。', '2022/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa388dbf-464e-47a1-ab2f-ce7480042683.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25c3bb2c-d13d-45ce-96c2-b731b93fcad9', '1d171689-ede8-4afb-abab-9f968013af6d', 3, '100118687', 'ギルドとの密約と奴隷少女', '黒霊騎士ジェラールとの戦いに勝利し、配下に加えたケルヴィン。ギルドへ討伐の報告に行くと、冒険者ギルド･パーズ支部 ギルド長のリオに呼び出される。そこでリオから自分以外の異世界人「勇者」の存在と、「魔王」が近く復活する話を聞く。勇者と魔王の存在に気分が昂るケルヴィンは、パーティ増強のため、奴隷商を訪れるが…。', '2022/07/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22434e63-2a65-477e-a83f-3cdd2d56645b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96dd1f44-d17f-41c9-83e5-d9cc46476950', '1d171689-ede8-4afb-abab-9f968013af6d', 4, '100119487', '悪魔', 'エフィルが仲間になってから一か月。クロトやジェラール、エフィルとともに順調にモンスターを倒し、A級昇格間近となったケルヴィンは、アンジェの誘いで、エフィルとケルヴィンの三人で出かけることに。仲を深め楽しいひと時を過ごす3人だったが、そこに東の軍国･トライセンの第三王子タブラが乱入し…。', '2022/08/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4b809fe-6b5d-4367-b0dc-897a24870268.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c0271a4-0766-49d4-87fd-443ddcd805b5', '1d171689-ede8-4afb-abab-9f968013af6d', 5, '100120103', '魔王の娘', 'S級モンスター･ビクトールと激しい戦いを繰り広げるケルヴィンたち。未だかつてない強敵に昂るケルヴィンは、一進一退の攻防の中、エフィル･ジェラール･クロトとの連携でビクトールを追い詰めたかのように見えたが…。', '2022/08/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/717566e5-2aa0-4772-9d7d-0eb35dc28cf6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('762378ef-7835-48ce-90cc-bb0f7d0a580d', '1d171689-ede8-4afb-abab-9f968013af6d', 6, '100120575', 'コメと盗賊と勇者', 'ビクトールとの死闘を制したケルヴィンは、魔王の娘･セラを仲間に迎えた。装備を整えた後、ビクトールと交わした「セラに世界を見せる」約束を果たすべく水国トラージへと向かうが、道中で盗賊団「黒風」の襲撃に遭い…。', '2022/08/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b01f383-5499-4416-a2bd-4466c1abd786.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f4500ed4-c307-4686-bbb9-08a7c5cc7d9b', '1d171689-ede8-4afb-abab-9f968013af6d', 7, '100121399', '勇者たちとの対戦', '駆け付けた勇者一行に黒風と勘違いされたケルヴィンたちは、勇者に今回の事件の証人になってもらうべく、勇者一行と対決する。新たな装備を着けたケルヴィン1人に対し、勇者たちは妖精の加護やスキル、魔法を駆使して戦うが…。', '2022/08/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbca7140-1bd6-41b8-9d69-fbe5c8a2756b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('521a8be1-7e75-4d21-9f8d-1890040421fe', '1d171689-ede8-4afb-abab-9f968013af6d', 8, '100121750', 'パーズへの帰還と女神の降臨', '勇者一行に勝利し、罰ゲームと称して勇者たちにダンジョンで稽古をつけるケルヴィン。ボスモンスターを倒し勇者一行と別れた後、ギルド長の使いに案内されケルヴィンたちはトラージ国王ツバキ･フジワラに謁見することに。', '2022/09/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a5e00931-1c60-4a1c-b1d1-1f61acb0ea70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('507f4dec-540c-4202-a27d-322461fff355', '1d171689-ede8-4afb-abab-9f968013af6d', 9, '100122899', '勇者召喚', 'トラージ国王ツバキから盗賊団“黒風”討伐の褒美を与えられたケルヴィン一行は転移門を使いパーズに戻り、ついにメルフィーナの召喚を果たした。“転生神の加護”により勇者の召喚ができるようになったケルヴィンだったが、転生させられる者の思いを考え、悩むのであった。', '2022/09/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3035abd-40f6-4929-a43c-bc1d8e0d7922.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50e5f235-b016-497b-98df-f10fbd30c03d', '1d171689-ede8-4afb-abab-9f968013af6d', 10, '100123597', '新たなる家族', 'ケルヴィンにより召喚されたリオンを仲間に加え、リオンと屋敷のメイドのエリィ･リュカを連れ、B級ダンジョン･暗紫の森にやってきたケルヴィンたち。順調に3人がレベルを上げる中、屋敷の周りには不穏な影が迫っていた…。', '2022/09/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/898e7109-1570-430c-8481-b523ffe89256.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9662a1a-74be-4054-a7f8-58a882ced119', '1d171689-ede8-4afb-abab-9f968013af6d', 11, '100124300', 'S級昇格試験', '獣国ガウンの獣王レオンハルト･ガウンから直々にS級冒険者昇格試験の通達を受けるケルヴィンたち。昇格試験のため、未知のS級モンスターが出没するようになったエルフの里へとやってきたケルヴィンたちだったが、里の長老･ネルラスはエフィルを見て驚愕する。', '2022/09/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5181aa6c-dcc8-41c7-ba7c-c9a9ba6ed725.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9fbbe628-be15-4d94-9b53-ad53ff187c43', '1d171689-ede8-4afb-abab-9f968013af6d', 12, '100124965', 'もう一人の転生者', '【最終話】トライセンの混成魔獣団を撃破したケルヴィンたちだったが、突如として現れた強敵･トライセン魔法騎士団将軍クライブがケルヴィンたちに襲い掛かる。ケルヴィンとクライブによる一進一退の激しい攻撃の応酬が続く中、クライブが災厄クラスの魔法を発動し…。', '2022/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dfa2543e-b0ee-4835-9c6b-01e6a267ad64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ccd9deed-838e-46cf-97cd-e3b4c88950d1', '黒岩メダカに私の可愛いが通じない', '', 'hulu', 'medaka-kuroiwa-is-impervious-to-my-charms', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b51c9e8-e14e-43f4-8842-57bd66bb95c7.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 177552, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('bc6a4e70-f904-4b02-a40b-295456a2f091', 'ccd9deed-838e-46cf-97cd-e3b4c88950d1', 'hulu-medaka-kuroiwa-is-impervious-to-my-charms-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ea1fc58-d065-401a-96da-f456e7bdcde1.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74b82644-6580-4e34-bfb9-11d1224e9aaa', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 1, '100212405', 'オチないアイツ', '川井モナ17歳。息をするようにモテる女。今まで自分になびかなかった男などいなかったが、転校生の黒岩メダカだけは全く彼女に関心を示さない。このままではクイーンビーとしてのプライドが許さないモナはメダカをどうにか振り向かせるためにあの手この手で誘惑する。一方でモナと距離を置こうとするメダカにも何やらワケがあるようで…!?', '2025/01/12 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ea1fc58-d065-401a-96da-f456e7bdcde1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28325e02-980b-4c8c-ba71-6a59e7430de7', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 2, '100213331', 'アイツと“好き”', '美術の授業でメダカとペアになったモナ。デッサンのモデル役となり、あの手この手でメダカの気を引こうと意気込むが、そんな彼女の後ろでは何やらクラスメイトの春野つぼみが怪しげな視線を送っており…。メダカに好意を寄せている (?) と考察したモナは思わぬライバルの出現に焦り、つぼみを調査することに。', '2025/01/19 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a5744852-34c6-4513-94ad-e213bde6d005.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f3d56318-7986-42f1-be2b-79db8c014099', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 3, '100214288', 'アイツと文化祭', '全校生徒が最も浮つくイベント“文化祭”。メダカをオトす絶好のチャンスと意気込むモナはつぼみから学校に昔から伝わる“愛の架け橋”の伝説を聞く。文化祭準備中から積極的に仕掛けるモナはバニーガールの衣装を着て誘惑を試みるが――!? つぼみのアシストもあり、メダカと2人で文化祭を回ることに。', '2025/01/26 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22c98641-4439-4a3c-a7f2-93d272ce3ded.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cae5609-6450-41ea-85db-946d91feaf13', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 4, '100214804', 'アイツと伝説', 'つぼみのアシストもあり、メダカと二人で文化祭を回るモナ。ここぞとばかりに仕掛けるも苦戦が続き、気付けば文化祭も終わりが近づくが、何を仕掛けても上手くいかず、モナは意気消沈。そんな中またしてもつぼみの計らいで、メダカと二人で文化祭の片付けをすることになるが、いつも通りに振る舞えない。', '2025/02/02 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5908a337-ad96-4d87-9363-9f5ef4c70e3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fc35c8a-a1ae-4e01-b744-4046aaf6bf8b', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 5, '100216178', 'アイツとバスケ女子', 'ある日一緒に登校したモナとメダカは一学年後輩のバスケ部エース･湘南旭と遭遇する。一緒に登校してきたことを旭に厳しく問い詰められ、メダカへの好意を疑われるモナ。そして彼女から突然の宣戦布告をうける。メダカを狙う一年生の登場でモナのメダカ攻略にも大きな影響が…!?', '2025/02/09 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91504abc-0ee3-45e2-8328-a328ac5a5fa7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa2518f2-5909-465a-bf90-57747a8fbfc4', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 6, '100217047', 'アイツを看病', '風邪を引いたメダカのお見舞いのため、モナはメダカの家へと向かう。一人暮らしと聞いて色々と企むモナだったが、旭も参戦し、結局二人でお見舞いに行くことに。お見舞いの機会に乗じてメダカにあれこれ仕掛けるモナと旭。 お互いの企みが交錯するメダカの看病バトルの行く末とは…!?', '2025/02/16 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6de2e5bf-43c2-4bd2-bfde-d1bdab2f91bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3d78954-bd3c-4cd8-9490-c4e644a15a91', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 7, '100218307', 'アイツと待ち受け', '翔のいたずらで過激な待ち受け画像に変えられたメダカ。モナはつぼみが送ったメッセージを消すため、メダカの携帯を追う。それぞれの思惑が交錯し…!? その後、ハロウィンイベントでメダカをオトすと意気込むモナの提案でコスプレ衣装を皆で買い出しに行くことに。', '2025/02/23 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d686ab87-2c22-45d0-a956-6968ec7a4944.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f056b311-cd88-4e5b-a0e1-4dc7d66e3d26', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 8, '100218921', 'アイツとハロウィン', 'メダカの好みのコスプレ衣装を購入し、ハロウィンパーティーに向け準備万端のモナ。ついにハロウィンパーティー当日を迎える。各々が用意したコスプレ衣装もお披露目し、美味しいお菓子にゲームにパーティーは大盛り上がり。モナもこの流れに乗じてメダカとツーショットを撮ろうと試みるが…!?', '2025/03/02 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2914c043-2a80-428c-a827-d86f84594d77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3fe3dc24-e90d-40f9-95ce-6988764f32c0', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 9, '100220109', 'アイツと親友', '美波のアシストでメダカと二人でお昼ご飯を食べることになった旭。メダカと二人きり、ハロウィンパーティーでの反省を活かし、旭は大胆な行動に出る。そんな中、大阪からモナの幼馴染･難波朋が遊びに訪れる。メダカに対する気持ちを恋心だと言い切る朋。親友のその言葉にモナは…。', '2025/03/09 01:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f900ab8d-b93f-4ebf-8f44-ad92ac9bb3fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54fcb581-cbc8-47fa-be62-1c536a1eaa6c', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 10, '100220781', 'アイツと遊園地', '旭からメダカにキスしたことを告白されたモナ。旭の大胆すぎる行動に焦ると共に自身の気持ちに戸惑ってしまう。朋の計らいで遊園地に行くことになったが、ここぞとばかりに仕掛ける旭とは対称的に、モナはいつも通りにメダカと接することができない。モヤモヤするこの気持ちの正体とは…。', '2025/03/16 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3601f6b-392a-4171-ba13-ec4f126d300e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c499090-a2be-4762-94a4-b2b8f9cc7fc5', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 11, '100221801', 'アイツと二人きり', '遊園地に来て以降、旭にリードされ気味で焦るモナ。トラブルが重なり一人はぐれてしまう。迷子になり困っているところをメダカが見つけ助けてくれるも、予期しない二人きりの時間にモナはドギマギする。会話も思うように続かず気まずい空気が流れる中、メダカの希望もあり観覧車に乗ることに。', '2025/03/23 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9550936e-c1de-4067-9532-93b05576c022.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a25fcdf8-b277-45de-823b-f3208666ee7a', 'bc6a4e70-f904-4b02-a40b-295456a2f091', 12, '100222465', 'アイツに初恋', '【シーズン1 最終話】ついにメダカへの恋心を自覚したモナ。親友としてそばで見守ってくれていた朋に自身の気持ちを打ち明ける。そしてモナは恋のライバルとなった旭に、決意を込めた宣言をするのだった。 メダカともっと話したい、もっと近づきたい、それから…。', '2025/03/30 00:30:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd2bb76c-caf6-4a18-aec2-45b3633d8b99.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0dc019d3-40de-4f23-92f5-2e69d394fecd', '黒子のバスケ', '', 'hulu', 'kurokos-basketball', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50027430_series_art__338x600_kurokos_basketball_951a96212032d2e47bf06f1e7bb97a22.jpg?w=331&h=447&p=t', 'hulu', 2012, 1, 1, 'FINISHED', NULL, 11771, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('30d8f999-7f12-45ea-a811-0a97c94404c3', '0dc019d3-40de-4f23-92f5-2e69d394fecd', 'hulu-kurokos-basketball-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1972f2a6-cd3e-4979-9990-77664107f161.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bec40ef0-6a98-48eb-9546-6314724f8cc7', '30d8f999-7f12-45ea-a811-0a97c94404c3', 1, '60807617', '黒子はボクです', '春、誠凛高校のバスケットボール部で、新入部員の挨拶が行われている。主将の日向と監督のリコが注目するのは、本場アメリカ帰りの巨漢･火神大我と、中学の絶対王者･帝光中学出身の黒子テツヤだ。ミニゲームで早速、圧倒的な存在感･天賦の才の片鱗を見せつける火神。一方、黒子はそこにいても誰も気づかない程の影の薄さ。だが実は黒子は、影の薄さを利用したミスディレクションにより、見えないパス回しを得意とする、帝光中学『キセキの世代』の幻の6人目 (シックスマン) だったのだ!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1972f2a6-cd3e-4979-9990-77664107f161.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7950cc3-cddd-4c00-96fe-3f02faec5e91', '30d8f999-7f12-45ea-a811-0a97c94404c3', 2, '60807590', '本気です', '互いの実力を認め合った黒子と火神。火神という光の影として、誠凛を日本一にする、と言う黒子だが、『キセキの世代』の5人がそれぞれ強豪校へ進学したのに対して、昨年から新設された誠凛高校を選んだのは理由があった。そんな中、誠凛は『キセキの世代』の1人、黄瀬涼太が入学した海常高校との練習試合が決定する。士気が上がる誠凛のもとに、黄瀬本人が登場、黒子に挨拶しにきたという。試合が待ちきれない火神は黄瀬に1ON1の勝負を挑むのだが…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/309ebfb0-82ae-4a3d-8544-186879755279.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e5cbd9a-a780-442a-9793-5dffce6b03d7', '30d8f999-7f12-45ea-a811-0a97c94404c3', 3, '60807618', '勝てねェぐらいがちょうどいい', '誠凛と海常の練習試合が始まった。レギュラー陣の軽い調整と豪語し、エース黄瀬を温存する海常に対して誠凛の怒りが爆発、火神がダンクシュートによりゴールを破壊する。一度見たプレーを完璧にコピーできる、天才･黄瀬は、投入直後に火神のダンクシュートをコピー、さらにお返しのダンクを決める火神、と試合は序盤からノーガードの殴り合いの様な点の取り合いの様相を呈する。タイムアウトの際、黒子と黄瀬は互いのチームメイトに対して、それぞれの弱点を指摘するのだが…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/249516ec-5fda-4f65-8bb0-09d4d1fe8d86.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9da6ce6a-4ce2-48cc-9a37-a964e8ac606e', '30d8f999-7f12-45ea-a811-0a97c94404c3', 4, '60807589', '逆襲よろしく!', '第2クォーターに入り、徐々に点差を縮める誠凛。黒子と火神の新たな連携により、チームの攻撃パターンの幅が増大、また天才･黄瀬の高い身体能力を持ってしても、極限まで影の薄い黒子のプレイスタイルだけはコピーできないのだ。アクシデントにより一旦コートを退いた黒子だが、キャプテン･日向ら2年生メンバーも奮起。コートに戻った黒子の力も加わり、ついに同点に追いついた! その時、黄瀬の目の色がこれまでとは明らかに変わった…その真の実力がついに発揮される!?', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/83533f29-cf1d-40a0-96e9-085de8bf6178.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3aa50c0-b768-4a6f-8473-aedf2ba01ee4', '30d8f999-7f12-45ea-a811-0a97c94404c3', 5, '60807596', 'おまえのバスケ', '誠凛と海常の練習試合は、火神の劇的なブザービーターで、誠凛の勝利に終わった。歓喜に沸く誠凛を背に、悔し涙に暮れる黄瀬のもとへ『キセキの世代』No.1シューター･現在は秀徳高校の緑間真太郎が現れる。秀徳と誠凛は地区大会で当たるため、偵察に訪れたのだが、ダンクの応酬となった試合内容、また無名の新設校に進学した黒子の考え方に対して、緑間は一方的な嫌悪感を露にし、誠凛に負けることはあり得ない、と豪語し去っていく。緑間と別れた黄瀬は黒子のもとへ向かう。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2cdbf5f8-bb87-4ddf-9d73-d1feb47f435a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4810239b-fc52-44ef-973b-d3068d360310', '30d8f999-7f12-45ea-a811-0a97c94404c3', 6, '60807597', '2つ言っておくぜ', 'インターハイ予選が間近に迫っている。同地区での最大の敵は、昨年全国ベスト8にして、『キセキの世代』緑間を擁する秀徳。トーナメント決勝で秀徳を撃破し、決勝リーグ進出を遂げるため、これまで以上に激しい練習に臨む誠凛。特に、昨年、新設校ながら健闘するも、あと一歩でインターハイ出場を逃した、日向をはじめとする2年生たちは気合十分だ。そして迎えた1回戦。相手は身長2mのセネガル人留学生･パパの加入で、一気に強豪クラスにのしあがってきた新協学園だ。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0c5b180e-6536-4b8b-b090-16105bdb9c00.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff0149d5-b199-44ee-be36-fd238de6aaeb', '30d8f999-7f12-45ea-a811-0a97c94404c3', 7, '60807609', 'すごいもん見れるわよ', '新協の身長2m選手･パパから子供扱いされた黒子は、スティールを連発、第1クォーターから大差をつけることに成功する。迎えた第2クォーターは火神とパパの真っ向勝負。気合十分のパパだが、それを上回る気迫を見せた火神が圧倒、誠凛は見事1回戦を突破する。一方『キセキの世代』緑間の秀徳は、初戦からエンジン全開。緑間の百発百中･フォームを崩されない限り絶対に落ちないシュートが炸裂、絶好調ぶりを見せつける。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0a4e7b11-887a-434b-b978-77fca4bf5c4e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('572ce240-47d8-4ddc-a9f3-f1517714d6d9', '30d8f999-7f12-45ea-a811-0a97c94404c3', 8, '60807600', '改めて思いました', 'インターハイ予選トーナメントを、何とか準決勝まで勝ち進んだ誠凛。相手は緑間を擁する秀徳と並び、東京の王者と称される強豪･正邦高校。キャプテン日向ほか2年生メンバーにとっては、昨年大敗を喫した因縁の相手だ。過去を乗り越えるべく勝利への決意を固める2年生の姿に、黒子と火神は「勝ちたい」と改めて思う。しかし試合開始から、古武術の動きを取り入れた正邦の、圧倒的なディフェンス力の前に、得点を奪うことができない…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1818ab31-7e06-4c56-ab2f-11595a9d6d77.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a9d612c-6ec2-4e53-9992-be157f3dcd55', '30d8f999-7f12-45ea-a811-0a97c94404c3', 9, '60807614', '勝つために', 'インターハイ予選トーナメント準決勝、秀徳は緑間を温存する余裕の戦いぶりで決勝進出は確定的。一方、王者･正邦に挑む誠凛は、火神のダンクと黒子のパスワークにより、第1クォーターを同点で終える。しかし正邦の執拗なディフェンスの前に奮闘していた火神が、第2クォーターにして4回目のファウルをとられてしまう。最大のピンチを迎えたに見えた誠凛だが、キャプテンの日向は落ち着いた様子で、火神、そして黒子の交代を告げる。誠凛2年生メンバーの目は決意に満ちていた…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/612351c1-3664-4c1e-bb2c-44ca7cdcb88d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('473cec91-9df6-4cd5-ad03-197268cf2de9', '30d8f999-7f12-45ea-a811-0a97c94404c3', 10, '60807591', '困ります', '準決勝、王者･正邦VS誠凛も大詰めを迎えた頃、再び黒子がコートに戻る。2年生の先輩としての意地と、黒子と火神の、後輩としての先輩への敬意。チームの心が1つになり正邦を追い詰めるが、正邦も王者のプライド全開で一歩も退かない。白熱の試合は、劇的なフィナーレで誠凛が勝利するのだった。小休止の後、緑間を擁する秀徳との決勝戦が幕を開ける。開始直後から互いに譲らず、均衡した展開となる。先取点を取り、試合の主導権を握ることになるのは果たして…!?', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c25d6eec-2c08-4b60-986e-a333d5f4835e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4272fb4-f682-4af7-bdf1-483254c2b6d0', '30d8f999-7f12-45ea-a811-0a97c94404c3', 11, '60807608', 'そんなもんじゃねえだろ', '先取点を取られた誠凛だが、直後に黒子のエンドラインからの回転式超長距離パスを火神が受け、取り返す。これにより、緑間の超高弾道スリーポイントシュートを間接的に封じた誠凛。すると秀徳は黒子のマークを高尾にチェンジ。高尾は、これまで誰も止められなかった黒子と火神のコンビプレイの阻止に成功する。実は高尾は誠凛、伊月のイーグルアイより更に広い視野でコート全体を見ることができる、ホークアイの持ち主であり、黒子のミスディレクションが通用しない相手だったのだ…!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/446db0d0-888d-47ef-ba0d-9a1177a8e7ef.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8bc41653-69aa-4e08-a76d-f957555c2763', '30d8f999-7f12-45ea-a811-0a97c94404c3', 12, '60807620', '『勝利』ってなんですか', 'センターラインからのみならず、自陣ゴール付近からのシュートすら決める、緑間の勢いが止まらない。第2クォーター終了時で、誠凛は20点近い点差をつけられてしまう。高尾にミスディレクションを封じられた黒子がベンチで見守る中、日向たちは必死で集中力を保ち秀徳にくらいつくが、なかなか突破口を見い出せない。そんな中、火神はベンチにいながらも全く諦めようとしない黒子の思いを受け、黒子や先輩たちに頼らなくても1人で勝つべく、天賦の才を爆発させ、圧倒的な存在感を発揮し出す!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cb7aa1c9-0b55-48bf-b339-378fcfbb3748.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37d58761-26c1-493b-8352-8794a9820016', '30d8f999-7f12-45ea-a811-0a97c94404c3', 13, '60807605', '信じてました', '決勝戦も第4クォーターに突入。満を持して登場した黒子だが、当然高尾がマークにつく。しかし黒子には高尾に対する秘策があった。一方火神の体力も尽きようとしていた。飛べるのはあと2回が限界。満身創痍の中、残り2分、ついに秀徳に1ゴール差まで追いつく。秀徳が突き放すか、誠凛が追いすがるか、運命のタイムアウト…秀徳は残り時間、全て緑間にボールを預けることを決める。一方の誠凛も、キャプテン･日向の3ポイントシュートに賭ける。勝敗のゆくえは…!?', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/72001fb1-3039-4082-bb27-1ac659b8854b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb1aa59c-6db8-4f9a-aacb-ccc314c4b2fc', '30d8f999-7f12-45ea-a811-0a97c94404c3', 14, '60807619', 'そっくりだね', '激戦の末、秀徳に勝利し、インターハイ予選決勝リーグ進出を決めた誠凛。帰り道で立ち寄った鉄板焼き屋で、秀徳の緑間、海常の黄瀬らとバッタリ遭遇したり、唐突に黒子が拾ってきた犬「テツヤ2号」を飼うことになったりしつつ、決勝リーグに向けた特訓の日々が続く。そんな中プールにて練習中の黒子のもとに、決勝リーグの対戦相手、桐皇学園マネージャー、自称･黒子の彼女の桃井が、そして個別メニュー消化中の火神のもとに、同じく桐皇の、そして『キセキの世代』エース、青峰が現れる!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5ad8048f-db4c-4c0c-94da-5bd7cfee153a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a424c58-d188-4da3-b008-582bcfa68d89', '30d8f999-7f12-45ea-a811-0a97c94404c3', 15, '60807601', '笑わせんなよ', '決勝リーグを間近に控えても、桐皇学園エース、青峰は練習をサボりマイペースを貫く。反発する部員に対し、主将、今吉は青峰の反則的な強さと、チームワークに頼らない桐皇のバスケスタイルを説き諌めるのだった。一方、青峰に1ON1で完敗を喫した火神は、黒子から、かつて誰よりもバスケを楽しんでいた青峰が、その後変わってしまったことを聞き、改めて試合での勝利を誓う。そして迎えた試合当日…だが桐皇のベンチに青峰の姿はない…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/39420de0-1cb8-4da6-a70f-9c164dad81f2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6eda3d27-1ea2-43ba-b21f-bceee963770d', '30d8f999-7f12-45ea-a811-0a97c94404c3', 16, '60807613', 'やろーか', '青峰が会場に到着しない中、桐皇と誠凛の試合が始まった。青峰抜きでも主将の今吉を中心に、各メンバーの個人技で全国レベルの強さを見せつける桐皇だが、誠凛もチームプレイで対抗する。しかし桐皇マネージャーの桃井による、圧倒的な情報収集力と、現状のみならず成長性まで読み切った分析力により、はじめて見せる連携プレイですら阻止されてしまう。本領を発揮させないまま誠凛を封じ込めようとする桃井…だが実は予測不可能な黒子の動きだけは読み切れないのだった!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cbe335e1-9c90-4255-a934-7e7b297ae23a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78d3c3aa-a8c8-4538-b2e3-dd4efcfa02c2', '30d8f999-7f12-45ea-a811-0a97c94404c3', 17, '60807587', 'ふざけた奴ばっかりだ', '第2クォーター残り30秒、誠凛が10点差まで追いすがったタイミングでついに青峰が到着した。アップがてらサクっと1本決める、と早々にスーパープレイを披露する青峰だが、黒子&火神も応戦、一歩も退かず、会場のどよめきを誘う。想像より手応えのある誠凛コンビに対して青峰のモチベーションは高まり、後半への意欲を見せる。一方の誠凛は、ミスディレクションが弱まってきた黒子を一旦温存し、火神が青峰を抑える作戦に賭ける。そして後半、青峰の全開･本気モードがついに爆発する!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cdd907f8-a783-44d2-a620-f7940e5457a6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8744cd7e-cd1f-4156-9c6e-fbd8f81edd9b', '30d8f999-7f12-45ea-a811-0a97c94404c3', 18, '60807607', '嫌だ!!', '青峰の、セオリーを無視したストリートスタイルのバスケに、誠凛は手も足も出ない。火神が必死に追いすがるも、青峰は軽々とその上をいき、点差はじわじわと開いてしまう。これ以上離されたら勝機がなくなる誠凛は、満を持して黒子を投入し、パスワークで点差を縮めていく。しかし、中学時代、誰よりも黒子のパスを受けた青峰には、黒子のパスが見えていた。スティールからの5人抜き、という離れ業で誠凛を蹴散らした青峰は、黒子に対して「お前のバスケじゃ勝てねぇよ」と言い放つ…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4e43a1b7-2e82-4b8a-b411-7801eed2e22c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb5e35de-9992-44d4-b130-2b76ef6b9f81', '30d8f999-7f12-45ea-a811-0a97c94404c3', 19, '60807632', '新しい挑戦へ', '圧倒的大差で桐皇に敗れた誠凛。続くリーグ戦2戦にも全力で挑むが、青峰に自分のバスケが通用しなかった黒子は精彩を欠き、また足の負傷を悪化させた火神が欠場する中、連敗…誠凛のインターハイへの挑戦は幕を閉じた。しかしそれはウインターカップを目指す、新たな戦いのスタートでもあった。しかし青峰の爪痕は黒子と火神の不協和音を生んでいた。今のままでは勝てない…2人がそれぞれ思い悩む中、誠凛バスケ部創始者にしてエース･木吉が入院明けでチームに復帰してきた…!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/662b68cd-1423-429b-a587-21f2eb57386d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecbc2afe-2701-4819-ab49-2386c2485120', '30d8f999-7f12-45ea-a811-0a97c94404c3', 20, '60807594', 'なりたいじゃねーよ', 'チームに合流した木吉は、いきなり火神と1ON1の勝負を挑んだり、格下相手の練習試合を黒子･火神ほか1年生メンバーのみで戦わせたり、とまるで何かを企んでいるかの様だ。木吉の狙いは、青峰に負けたことをきっかけに、プレイが自己中心的になりつつある火神に、チームワークの大切さに気付かせるため…と思いきや、火神のことは全く心配しておらず、真の狙いは、黒子に現在のバスケスタイルの限界に気付かせるためだった。そんな中黒子は日向に、自らスタメン落ちを申告する…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8907f152-2ab4-427d-b8c1-a425dd9485ce.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7aed2b72-cb32-4da5-93b3-5dea02500df1', '30d8f999-7f12-45ea-a811-0a97c94404c3', 21, '60807623', '始めるわよ', 'それぞれ今よりもっと強くなり、より大きな力を合わせて『キセキの世代』を倒す…黒子と火神の思いは交わり、ウインターカップへ向けての新たな挑戦がスタートした。夏合宿で問題となるであろう、絶望的なリコの料理の腕前も、火神の指導により何とか上達、いざ海辺での夏合宿がスタートした。各個人の動きのクオリティ向上のため、通常の3倍という地獄の練習メニューをこなす誠凛。そして2日目の朝。宿で何と緑間ら秀徳高校メンバーと遭遇する。実は同じ民宿に泊まっているのだった!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/afca5bd1-b327-4841-903b-70b3851fd844.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('95b9aeaa-4f70-403d-86a1-4f811992cd17', '30d8f999-7f12-45ea-a811-0a97c94404c3', 22, '60807606', '死んでも勝つっスけど', '地獄の夏合宿で、秀徳との合同練習に臨む誠凛。1人別メニューの火神は『キセキの世代』に対抗するため、得意の空中戦に磨きをかけることを目指すも、緑間との1ON1で空中戦で完敗してしまう。だが火神は緑間に負けた理由と、今後の課題がハッキリと見えていた。そんな火神を前に、黒子も自分の新しいバスケを見出そうとしていた。そして何とか合宿を乗り越えた誠凛は、そのままインターハイ観戦に向かう。対戦カードは海常VS桐皇。『キセキの世代』の激突、黄瀬VS青峰の決戦が始まる!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c8fce95a-5093-437d-91ab-355bb55ca8e2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00bdb978-ef6c-4c91-90d7-a4509335c18f', '30d8f999-7f12-45ea-a811-0a97c94404c3', 23, '60807616', '大人じゃねーよ!', '海常VS桐皇の試合は、ともに『キセキの世代』の、黄瀬と青峰の対決で幕を開ける。黄瀬の攻撃を青峰が抑え、流れに乗って先制する桐皇だが、海常もキャプテン笠松を中心に反撃、一進一退の攻防が続く。青峰に押され気味の黄瀬だが、何度かの対決でついに青峰を抑えることに成功し、第1クォーターは海常リードで終える。しかし第2クォーターに入り、徐々に本領を発揮してきた青峰は、黄瀬を終始圧倒、点差は徐々に縮まっていく…!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/65c55d32-dbf6-45f2-bae5-ca1f536b0306.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('690ce0f1-8c1f-4e71-b3e8-807a170f55ac', '30d8f999-7f12-45ea-a811-0a97c94404c3', 24, '60807633', 'カン違いしてんじゃねーよ', '一度見たプレイは完璧にコピーできる、天才･黄瀬をもってしても、唯一無二のスタイルを誇る青峰のプレイはコピーできない。しかし、青峰に勝つために黄瀬、そして海常が選んだのは、青峰のコピーに挑戦することだった。9点差を追いかける海常だが黄瀬のコピーが完成するにはまだ時間がかかる。そして迎えた第3クォーター、桃井の予想より遥かに早いペースで青峰に迫る黄瀬だが、一方の青峰も一歩も退かない。はじめて感じた、チームの絆、信頼を背に、天才･黄瀬がついに覚醒する!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/40d71f5b-94ed-43a5-9bcc-45322d166774.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b30964e5-e9a8-4425-8542-5d8b42f13c5a', '30d8f999-7f12-45ea-a811-0a97c94404c3', 25, '60807612', 'オレとおまえのバスケ', 'インターハイ準々決勝、海常VS桐皇はついに第4クォーターに突入し、青峰と黄瀬の一騎打ちは、どちらも一歩も退かないまま残り時間1分を迎える。攻める黄瀬、守る青峰。そしてついに勝敗の行方を決定付ける瞬間が訪れる…! キセキの世代同士のハイレベルな激突を会場で目の当りにした誠凛メンバーたち、そして秀徳の緑間、高尾らは、来たるウインターカップへ向けての思いを馳せる。そして黒子と火神は、改めて、力を合わせてキセキの世代を倒す、という誓いを交わすのだった。', '2026/02/01 00:00:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f815c497-2967-44c7-b3fd-7e3bf3d162d5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', '0dc019d3-40de-4f23-92f5-2e69d394fecd', 'hulu-kurokos-basketball-s2', '第2期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7aae49e7-db0f-4717-8f36-8b7e1fcaabea.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9d2c231-2893-4f2a-9645-83d9dae15037', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 26, '60807631', 'こんな所で会うとはな', '誠凛高校バスケ部は、ウインターカップでの『キセキの世代』との全面戦争へ向けて、激しい練習を積んでいた。そんなある休日ストリートバスケの大会に参加した黒子たちは、会場で火神のアメリカ時代の兄貴分･氷室辰也と出会う。かつてともにバスケを学び、技術を競い、決着をつけられないまま別れてしまった因縁の相手に対し、煮え切らない態度を見せる火神。そんな火神だが…? さらにそこへ、氷室と同じく陽泉高校バスケ部に所属する『キセキの世代』紫原敦が現れる。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7aae49e7-db0f-4717-8f36-8b7e1fcaabea.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b0c1d6c-6e37-4f23-91cd-53f4cff4003a', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 27, '60807599', 'ウインターカップで', '『キセキの世代』紫原敦がストバス会場に現れた。巨体とは裏腹にゆる～い雰囲気の紫原だが、火神の挑発に乗せられ、急遽試合に参戦することに。紫原を前に、開始早々アクセル全開の木吉。木吉にとって紫原は、中学時代に対戦し、完敗を喫した因縁の相手だった。氷室と火神、紫原と黒子、そして木吉。因縁が交錯するストバス対決の結果は? その頃、他の誠凛メンバーは、突然泣きながらやってきた桐皇のマネージャー･桃井の対応に追われていて…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b123e556-2d25-438b-b1b4-42d17536a42e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ef2cc3d-2d1a-4f5a-a27d-a77ca1be2075', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 28, '60807595', '始動!!!', 'いよいよウインターカップ予選が始まった。誠凛の初戦の相手は、大型新人センター･鳴海を擁し、インサイドに強い丞成高校。火神を徹底マークしインサイドを封じにかかってくる丞成。しかし誠凛のインサイドは、木吉の復帰により遥かにパワーアップしていた。木吉は久しぶりの試合で浮かれつつも、ポイントガード並のパスセンスと、相手の出方を見てから手を変える「後出しの権利」を駆使し『無冠の五将』と呼ばれる実力を遺憾なく発揮。それを見た黒子、火神ももちろん黙ってはいない!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e32fb255-f437-44db-9855-346d7a9bf06c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50da5a4c-d133-49d3-973a-750c11c1dbd2', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 29, '60807593', '答えはひとつに決まっている', 'ウインターカップ東京代表二校を決める決勝リーグの出場校四校が出そろった。まず誠凛は王者泉真館を撃破。また緑間擁する秀徳高校も霧崎第一を難なく下すが、霧崎の一軍メンバーは、秀徳戦には出場せず誠凛戦を観戦･分析していた。霧崎を率いるのは、『無冠の五将』の1人である花宮真。「悪童」と呼ばれるその理由は…? そしてついに誠凛と秀徳の運命の再戦が始まる。インターハイ予選での敗北を機に、火神を完全にライバルと認めた緑間は、ただならぬ闘志を漂わせていた…!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e3ae5e0b-f15c-41a1-b229-2607511d1739.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('094dda96-c255-4f73-ba89-d0873d491f8e', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 30, '60807634', '待ってたぜ', '第2クォーターに入ってもひたすら続く、緑間のシュートを火神がブロックする、という光景。振り切られまいと粘る火神に対し緑間が見せたプレイは、かつての彼では有り得ないプレイスタイルだった。これにより飛躍した秀徳のチームとしての力が誠凛に襲い掛かる! しかし誠凛も木吉加入によるインサイド強化と、高速パス回し･ラン&ガンスタイルの進化で、ハイペースな点の取り合いに持ち込む。そして迎えた第3クォーター。新生･緑間を相手にし続けている火神の体力は限界に近づいていた…!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1caee58e-e559-4bac-a3f4-347fffafc2f2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5896d03d-065e-4639-8f8f-a568de0c5399', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 31, '60807621', 'とうの昔に超えている', '第3クォーター終了直前、誠凛は切り札として黒子を投入。黒子は、緑間、高尾を新技バニシングドライブでブチ抜き、連続得点に繋げ、同点にまで追いついた。第4クォーターも、高速パスワークに黒子が加わることによる、変幻自在のラン&ガンスタイルで勝負するが、秀徳･緑間も限界を超えてなおも3Pを放ち続ける。一進一退の攻防は、誠凛の1点ビハインドの残り2秒、木吉がディフェンスファウルを得る。勝敗の行方は木吉のフリースロー2本に託された…!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f933f5da-dd89-412f-83d3-5ecba18c4776.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a7562b1-5fbd-4140-bb67-c851c516479d', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 32, '60807592', 'あきらめろ', '誠凛と秀徳の戦いは、両校死力を尽くした結果引き分けに終わり、黒子と緑間はウインターカップでの再戦を誓う。一方火神は、試合後の控室で話す日向と木吉の会話を偶然耳にし、衝撃を受ける。ひざの痛みに耐えながら、「今年が最後のチャンス」だという木吉…。帰宅中、その言葉の意味を問う火神と黒子に対し、日向は誠凛高校バスケ部が創られたいきさつを語り始める。1年前、バスケから離れようと決意していた日向に対し、木吉は一緒にバスケ部を創ろうとつきまとって…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6bd9b34d-63c2-4ee3-a836-51709a7c29b0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a513fbc3-31c5-4db3-826a-91d86bf2d023', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 33, '60807628', '誠凛高校バスケ部だ!', '全てをふっきり、再びバスケと向き合うことを決めた日向と、屋上での決意表明を見て部員の本気を感じたリコが加わり、誠凛バスケ部はついに本格始動を始める。性格はかみ合わないものの、木吉と日向の中外二枚看板で、新設校ながら異例の快進撃を見せる誠凛。あと一つ勝てばインターハイ予選･決勝リーグ進出という状況で迎えた霧崎第一高校戦。木吉のパスワークで翻弄し、誠凛優勢で進む試合終盤、霧崎第一はメンバーチェンジ。『無冠の五将』の花宮が登場する。その目は、木吉の左ひざの震えを捉えていた…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a272a0e5-f582-427a-b988-26623673b5fa.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96725517-7787-458f-a400-760171c0999d', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 34, '60807627', '必ず倒す!!', 'ウインターカップ予選リーグ決勝･誠凛VS霧崎第一の試合がはじまった。因縁の相手を前に入れ込む日向ら誠凛。黒子も開始早々、バニシングドライブを炸裂させる。流れをつかんだかに見えたが、霧崎第一の選手たちは、審判の死角を突いたラフプレイを繰り広げる。チームメイトを露骨に狙ってくる花宮のやり方に木吉の怒りが爆発。仲間を守るためインサイドを攻守とも全て1人でこなすと言い、反対するリコや日向の声にも耳を貸そうとしない。孤軍奮闘を続ける木吉に対し、花宮の苛立ちは高まり…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/69eb3a0d-fe8b-46d4-8585-e9dd3ee7d241.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1b45c5a-eb1e-4366-939f-c95eb0dad72f', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 35, '60807604', '信頼だ', '木吉の身体を張った奮闘により、誠凛は第2クォーターをリードで折り返す。木吉を愚弄し、バスケに不誠実な態度をみせる花宮に対して、黒子は静かに怒りの炎を燃やす。第3クォーターに入ると、霧崎第一は満を持して瀬戸を投入、花宮と瀬戸の連携による「クモの巣」で伊月のパスを100%スティールし、逆転。入れ込みすぎている日向のシュートも1本も決まらず、誠凛は窮地に立たされる。そして迎えた第4クォーター、クモの巣を破るために、黒子がチームプレイをやめる!?', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/15a371f5-2209-4ba6-bc24-2a6130e05c16.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd76d061-9f7d-4c87-8e40-2a0748aa331c', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 36, '60807603', 'ふざけるな', '日向、リコらの説得を受け、満身創痍の木吉はベンチに下がった。両チームの激しいせめぎ合いが続く中、花宮に対する怒りに囚われていた日向は、木吉との約束が「花宮を倒すこと」ではなく「日本一になること」だったと気付き、ついに本来の実力を取り戻す。止まらない日向の3Pをきっかけに、完全に勢いに乗った誠凛は逆転に成功。しかしそんな想いのこもった猛攻をもあざ笑う「悪童」花宮の卑劣なプレイに、ついに黒子が…!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6f9f5a62-47e1-4877-94d8-a10e738fe043.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8feb4c03-1632-41ff-9a7b-2d9a25fe966f', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 37, '60807635', 'よろしゅうたのむわ', 'ウインターカップ出場を決め、温泉旅館で身体を癒す誠凛。そこへ、近場での練習試合を終えた桐皇学園が鉢合わせる。偶然かと思いきや、今吉たちは挨拶をしにきたのだという。発表されたばかりのウインターカップの対戦表、誠凛の初戦の相手は桐皇学園だったのだ! 来たるべき再戦へ向け、黒子･火神と青峰は火花を散らす。気合いも新たに始まった合宿。誠凛メンバーはリコの父･景虎のもと、各々自分だけの武器を磨くことになった。しかし何故かそこに火神の姿はなく…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/79d7484f-e6c0-42d8-8c16-6f263a8a3ab6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c85788a-04e9-40c0-8594-c9155e2591cf', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 38, '60807588', '今度はもう絶対に', '火神は1人チームメイトから離れ、アメリカ時代の師匠の元で修行を続けていた。そしてついにウインターカップが開幕する。開会式の後、『キセキの世代』の主将だった洛山高校の赤司の呼び出しで、黒子を含む『キセキの世代』全員が久しぶりに一同に会した。部外者を寄せ付けない緊張感の中に、遅れて帰国した火神が飛び込んでくる。すると赤司は誰もが驚く行動に出て…! 赤司との衝撃の初対面となったものの、火神の頭の中は目の前の桐皇戦、青峰とのリベンジマッチに集中していた。桐皇VS誠凛が幕を開ける!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0c632413-cfea-43e5-b6fc-af8676edca40.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce0eb813-b57e-4176-b304-4c464e90f042', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 39, '60807626', 'ムダな努力だ', '試合開始早々、青峰の攻撃で先制した桐皇に対し、誠凛も黒子の新技『イグナイトパス廻』や木吉の『後出しの権利』で対抗するが、桐皇の地力の強さをなかなか上回ることができない。白熱するかと思われた火神と青峰のエース対決も、火神が攻め込もうとせず観客を驚かせる。さらに試合は日向と桜井の3ポイントシュートの打ち合いとなり、決め手にかけたまま同点で第1クォーターを終える。そして迎えた第2クォーター、先手を取るべく黒子は青峰に1ON1を挑む!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cfdb9888-4142-4223-8edd-9f264f14e0de.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8871bd39-de1f-4b3e-bc33-8e9fb8bb4abf', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 40, '60807629', '嬉しくてしょうがないと思います', '青峰に新技を破られ、これまでの努力を完全否定された黒子は、ベンチで悔し涙に暮れる。そんな黒子の思いを胸に、かつてない強い気持ちで青峰に挑みかかる火神がついに覚醒する! 研ぎ澄まされた感覚で青峰のフォームレスなプレイに食らいつくその様は、まさに「野生」。火神の変化を感じ取った青峰は、失いかけていた闘争心をよみがえらせる。他の介入を許さないほどの両校エースの直接対決は、互いに譲らぬまま前半戦が終了する。思わぬ接戦に苛立つかと思いきや、青峰の顔には笑みが浮かんでいた。一方黒子は…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f89c57b9-a078-46f9-a90e-50658b935ad3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('104ae6f5-a587-41b5-9d4f-90ecc3c14551', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 41, '60807636', '今勝つんだ', '今吉のマークによって黒子の動きが封じられたうえに、桃井のデータと予測を採り入れたディフェンスで誠凛の攻撃を完封する桐皇。青峰も、覚醒した火神以上の力を発揮し、格の違いを見せ付ける。徐々に開いていく点差。効果をなくしたミスディレクション…。万策尽きたかに見えたそのとき、黒子は最後の切り札、『ミスディレクション･オーバーフロー』を発動させる!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7508ae04-464e-4961-8e9c-9833141f51af.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1df21ab-3ea5-4cd4-a641-7e7b644d8563', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 42, '60807615', '信じてますから', '第4クォーター、チームプレイで桐皇に対抗する誠凛だが、両チーム点の取り合いが続く中、差は一向に縮まらない。しかし、決死の覚悟で挑んだ黒子･火神･木吉のトリプルチームの複合技でついに青峰を止めることに成功し、3点差まで追いつく。しかし青峰は、選ばれた者にしか入れない究極の領域『ゾーン』の扉をこじあけ、その真の実力を発揮。もはや誰も青峰を止められないのか…誠凛の運命はエース火神に託された!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/48cbafbd-029d-421d-9643-f7378dce0bf5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d49e62d-de8b-4c45-90ea-b357706d2342', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 43, '60807598', '負けるかよ', '仲間の想いを背負った火神は、青峰に続き『ゾーン』に突入。2人の次元の違う戦いに誰も手出しできないが、青峰の表情はどこか楽しそうでもあった。土壇場で火神が青峰を上回るも、青峰も譲らず、残り時間数秒で3点差…。誠凛に延長戦を戦う力は残されていない。絶対にあと2本決めなければ! 逆転の可能性にかける誠凛は、木吉の機転によりバスケットカウントを得る。これが本当のラストプレイ。勝敗の行方は、火神と青峰のリバウンド勝負に託された…!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9273af25-be75-48fa-9d36-f155fa202708.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b09aa83-8928-4c1e-9c10-22c0be940348', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 44, '60807611', '教えてください', 'ウインターカップ初戦を突破し、誠凛は火神の家で束の間の休息を楽しんでいた。すると、突然謎の金髪グラマラス美女が現れる。彼女の名はアレックス。火神と氷室のアメリカ時代のバスケの師匠で、愛弟子である2人の対戦を観る為に来日したという。翌日、試合のない誠凛と共に、緑間や紫原の出場する試合を観戦したアレックスは『キセキの世代』の力を目の当たりにし、火神に新たな特訓を授けることを申し出る。一方、黒子はある人物のもとへ…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e9aa2cb9-503b-4bbd-9d15-36e0256ded57.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1578818-2b29-415a-802d-5a01bf8361bc', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 45, '60807625', '軽いものなはずないだろう', 'ウインターカップ二回戦、対中宮南戦。誠凛はリコの采配により黒子･火神を除いたメンバーで挑むも、本調子が出ず思わぬ苦戦を強いられる。しかし「日本一になる」という強い想いでなんとか勝利を収める。一方『キセキの世代』紫原を擁する陽泉高校は、前代未聞の連続無失点勝利を飾っていた。その他海常･秀徳･洛山といった優勝候補もそれぞれ順調にコマを進める。そしてついに準々決勝、誠凛VS陽泉戦が始まる!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/60e4b75a-924d-4056-961c-8b8d8b670d4c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2abf1af3-19cc-4785-9337-e7539054b537', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 46, '60807624', '初得点!!', '準々決勝、『キセキの世代』紫原と、火神のアメリカ時代の兄貴分･氷室を擁する陽泉高校との試合がついにはじまった! ここまで無失点で勝ち上がってきた陽泉の鉄壁のディフェンス『イージスの盾』を前に、誠凛は超高速パスワークや、木吉の新技『バイスクロー』で挑むも、第1クォーターを無得点に押さえられてしまう。迎えた第2クォーター、黒子は青峰の特訓を受け完成した新技『ファントムシュート』を繰り出す!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f692cdb4-e342-49f6-9e23-81d8f4a2d268.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9ccfc56-41cd-451e-b042-2a3050d0e01d', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 47, '60807630', '決まってらあ', '黒子の得点を皮切りに、猛烈に追い上げる誠凛。そして第3クォーター、かつて「兄弟の絆」を結んだ火神と氷室の勝負が本格開戦する。氷室は『ミラージュシュート』をはじめ流麗なプレイで「キセキの世代」と遜色ない実力を見せつけるも、火神は本領を発揮しきれない。形勢逆転を狙う日向と木吉は、『イージスの盾』と称される陽泉の鉄壁の防御を破るため秘策に出る。巧妙な戦略で紫原をイラつかせる木吉だったが、身体を張ったプレイに全身が悲鳴を上げだしていた…。', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a55f73c0-f96f-43c3-a08c-7b2b341c97eb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a147f70-b5bc-46c5-9153-db6723ac9a6b', '5733aecb-e60c-4e3d-8fcf-24a84d9e58e3', 48, '60807602', '負けたくない!', 'ついに紫原がオフェンスに加わってきた! 誠凛は3人がかりでブロックするが、怪物じみたパワーは止まることを知らず、強烈なダンク『破壊の鉄槌 (トールハンマー)』によりぶち破られてしまう。木吉の「後出しの権利」も通用せず、火神のブロックも破られ、果てはゴールまで破壊されてしまう…。心も体も消耗しコートに倒れる木吉に無慈悲な言葉を投げかける紫原。交代した黒子をはじめ、誠凛は木吉のリベンジを誓い、新フォーメーションで反撃に出る!', '2026/02/01 00:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/09fbb067-dea1-485b-866b-61efa7dcaf8a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('35aeba93-6b07-494a-b47e-78a68d1db497', '黒執事', '', 'hulu', 'black-butler', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5649f941-9a41-427d-bfb5-bd6c1da349ee.jpg?w=331&h=447&p=t', 'hulu', 2008, 3, 1, 'FINISHED', NULL, 4898, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('82da19f4-005a-4605-afa3-7c9bb1479181', '35aeba93-6b07-494a-b47e-78a68d1db497', 'hulu-black-butler-s1', '第Ⅰ期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f2e7c91-ab70-40c2-b3c7-97ef2320a6af.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35e08e96-63ab-46fd-b62b-33c63600812b', '82da19f4-005a-4605-afa3-7c9bb1479181', 1, '100072018', 'その執事、有能', 'ファントムハイヴ家に来客予定の日。超一流なファントムハイヴのもてなしの準備にかかる執事のセバスチャン。しかしその一方で、セバスチャンをあっと言わそうと、使用人のバルドたちが独自に準備にかかる。その結果は…、全て大失敗。来客まで残り時間わずかとなった最悪の状況で、セバスチャンがとった行動とは!?', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f2e7c91-ab70-40c2-b3c7-97ef2320a6af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d9b05d4-1441-4215-8878-d8d633335149', '82da19f4-005a-4605-afa3-7c9bb1479181', 2, '100072019', 'その執事、最強', 'シエルが書斎から何者かにさらわれてしまった。セバスチャン宛てに届いた一通の誘拐犯からの手紙。そこには、主人であるシエルを返す条件として、ある物をもって指定の場所に来るように書かれていた。使用人達に夕食の用意を任せると、セバスチャンは一人、犯人のもとへ向かった…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62dbdc51-88fa-43fa-9694-5e5752f00fac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1d5879b-5f1f-4135-9360-cfcee4c9ae25', '82da19f4-005a-4605-afa3-7c9bb1479181', 3, '100072020', 'その執事、万能', 'マダムレッドの頼みで、役に立たない執事グレルを引き取り、鍛えなおすことになったシエル。そこに突然、許婚のエリザベスが訪れる。勝手に屋敷を少女趣味に飾り立てたエリザベスは、ダンスパーティーをやろうと言い出す。ダンスの経験が浅いシエルに、セバスチャンは指導を申し出て…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96bcd260-51f3-4488-8e7e-ccc267740e10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4aec5e4f-dcb8-4e0c-acaa-3b4f56eaf49a', '82da19f4-005a-4605-afa3-7c9bb1479181', 4, '100072021', 'その執事、酔狂', 'ホワイトチャペルで娼婦の猟奇殺人事件があった。その残忍な殺害方法から、スコットランドヤードは犯人を「ジャック･ザ･リッパー」と呼んだ。女王の憂いを払うため、犯人の特定を急ぐシエル。やがて、捜査線上に黒魔術に傾倒している貴族が浮かんだ。シエルとセバスチャンは、その子爵が開くパーティに潜入するが…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad02809d-c8d9-4bda-b4da-99e6840cece7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d580eacc-6c23-4a3e-9cc7-94377cc2bc14', '82da19f4-005a-4605-afa3-7c9bb1479181', 5, '100072022', 'その執事、邂逅', '子爵が犯人でないことが判り、あらためて犯人像の割り出しにとりかかったシエル。被害者の身体的な共通点から、次の被害者を予想し、犯人を袋小路で待ち伏せるシエルとセバスチャン。しかし、そのすぐ側で、新たな犠牲者の悲鳴が響き渡った…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be1a3524-4007-4c0d-9887-a4206d1691cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76dbd692-a7a4-4593-a972-3d86b3d40f90', '82da19f4-005a-4605-afa3-7c9bb1479181', 6, '100072023', 'その執事、葬送', 'マダム･レッドの亡骸にマントをかけるシエル。その背後では、月光に照らされる中、グレルとセバスチャンの死闘が続いていた。ほぼ互角の両者の攻防だったが、グレルの放った一撃が深々とセバスチャンの胸元を切り裂いていった…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afc67057-7ce4-4a68-9299-e5fd614f8073.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce07c180-fb62-4738-8f87-5e235879e0a1', '82da19f4-005a-4605-afa3-7c9bb1479181', 7, '100072024', 'その執事、遊興', '法律の抜け穴をくぐり、裏で「犬虐め」を行なう村を、女王の保養地の名目で確保しに来たシエル達。しかし、出迎えた村の有力貴族ヘンリー卿は、祟りがあるために、女王の命令でも買収には応じられないと提案を断固拒否する…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47966ff6-3c1a-4a70-8795-3d46ede9f7bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2247c336-fc69-45d9-b21d-bab72dcdb458', '82da19f4-005a-4605-afa3-7c9bb1479181', 8, '100072025', 'その執事、調教', 'ヘンリー卿が殺害された。その死体には、かなり大きな動物の噛み傷が残されていた。伝説の魔犬の仕業と信じ、怯える村人達。そんな中、薬草を積みにいったまま戻らないヘンリー卿のメイドのアンジェラを探しに、使用人達は沼地へ向かった…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ef88519-180b-4ad9-ad7b-05fd6672c445.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a42419f-f320-4020-bc2d-1d0b77417832', '82da19f4-005a-4605-afa3-7c9bb1479181', 9, '100072026', 'その執事、幻像', 'イギリスで写真技術を発明したタルボット。彼が最後に使っていたカメラで人物を撮影すると、被写体の人物が一番恋しく思う存在が写るという。そのカメラを入手したシエルは、バルド、フィニ、メイリンの三人に、本人に気付かれずに、セバスチャンを撮影するように命令した…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c557ccb9-dfea-4b27-9bd0-0fbbc5a57888.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7789b2d-ac04-4fa1-a563-18cbca3f2e9e', '82da19f4-005a-4605-afa3-7c9bb1479181', 10, '100072027', 'その執事、氷上', '凍ったテムズ河で開かれている氷上マーケットを訪れたシエルとセバスチャン。偶然出逢ったアバーラインから、非常に価値のあるブルーダイヤを追っていることを聞き、ダイヤ探しに付き合うことにする。一方、エリザベスもシエルにあげるプレゼントを探しにマーケットを訪れていた…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2545a2dd-a0be-44b6-87ea-4dbf35c5e01e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('091797fa-f638-4809-ba67-808c207fa5b9', '82da19f4-005a-4605-afa3-7c9bb1479181', 11, '100072028', 'その執事、如何様', 'シエルの誕生日前日。エリザベスは、自分が壊してしまったファントムハイヴ家の指輪の代償として、拾った「ホープの欠片」の指輪をプレゼントしようとする。だが、シエルの指にはセバスチャンが修復した指輪がはまっていた。落胆するエリザベスは、かすかに聞こえてくる音楽に併せて指輪が明滅し始めたことに気付き…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b83de621-0e02-4559-88ba-f5b5e52ac06f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18cf52d2-f6a1-49e5-b5fc-4dce4ed5f5aa', '82da19f4-005a-4605-afa3-7c9bb1479181', 12, '100072029', 'その執事、寂寥', '月明かりに照らされた塔の制作室の中、人形にされたエリザベスが椅子に座らされていた。一方、襲い掛かる少女人形を撃退しながらエリザベスを追ってきたシエルは、自分の身が再び砕けることも恐れないほどエリザベス救出に固い決心を示す。その時、ドロセルが奏でる音楽によって操られた人形達がシエル達の前に現れて…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c65ef213-a202-4976-b97f-7a20294ec7e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02958722-ee06-4b83-8c1c-5b55ebbeb1ec', '82da19f4-005a-4605-afa3-7c9bb1479181', 13, '100072030', 'その執事、居候', 'コーヒーハウスの店先に、半裸の白人四人が逆さ吊にされる事件が起きた。そんな彼らの体には、舌の絵と王室を侮辱する内容を含む犯行声明書が貼られていた。インド人密航者が多い暗黒街を調査していたセバスチャンとシエルは、突然インド人達に絡まれてしまう。その時、従者を連れたインド人が、間に割り込んできて…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cacaabec-7d1c-4038-9a20-d27ac6bf3151.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73de5763-741e-4385-8de9-a9c56416bad7', '82da19f4-005a-4605-afa3-7c9bb1479181', 14, '100072031', 'その執事、異能', 'ソーマが寝た後、アグニが内緒でどこに行っているのか突き止めるため、後をつけたセバスチャン達。アグニがはいっていったのは、インドからの輸入品を扱っているハロルド･ウェスト=ジェブの屋敷。実はウェストは自分がロイヤルワラントを手に入れるために、アグニを操り、逆さ吊り事件を起こしていた首謀者だった…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7aedcf3-530c-4319-9d17-4f8ab5bf3140.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87a3a31c-a659-413d-8a4b-57b22004fe0f', '82da19f4-005a-4605-afa3-7c9bb1479181', 15, '100072032', 'その執事、競争', 'ヴィクトリア女王参加の下、ロイヤルワラントをかけたカレー対決の火蓋が切って落とされた。参加者が調理に入る中、とりわけ格好よく手馴れた感じで調理するアグニ。一方、セバスチャンもそれに引けをとらない手つきで調理を行う。そして、セバスチャンが鍋に入れ始めたものは、なんとファントム社製のチョコレートで…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f861bc96-8dad-419e-bfbe-314a0c3fdeac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9e41ca0-38c9-4e42-932f-705d27b393f7', '82da19f4-005a-4605-afa3-7c9bb1479181', 16, '100072033', 'その執事、孤城', 'ラドロウ城に幽霊が出るため、ホテルの改装工事の中止依頼が来ているとの報告を受けたシエルは、セバスチャンと真相を確かめるべく城に向かう。そこで四百年前に暗殺されたと言われるエドワード5世とリチャードの二人の王子の霊に出会う。城の明け渡しを賭け、エドワード5世とのチェス勝負に臨んだシエルだったが…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f0cfddc-c55c-4076-8325-bcb1d8b6621f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0281773d-a56e-41c2-b550-55d4802b883e', '82da19f4-005a-4605-afa3-7c9bb1479181', 17, '100072034', 'その執事、奉納', 'アッシュから、プレストンの郊外にある今は使われていない修道院が異様な教義を唱える教団の巣窟になっており、政府に対して蜂起を企てているとの情報を聞いたセバスチャンとシエルは、修道院へ向かう。ドゥームズデイブックと呼ばれる生前の美徳や悪行が刻まれた台帳を使用する教団に潜入したセバスチャン達だったが…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4f2fbce-1d36-470c-9153-947ee1937fff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5404393a-6281-42f4-a13f-d690bc7ca630', '82da19f4-005a-4605-afa3-7c9bb1479181', 18, '100072035', 'その執事、転送', 'セバスチャンとともに教団のアジトである修道院へ潜入したシエル。ところが、すぐに信者に見つかってしまい、なぜか彼だけ教祖のもとへ連れていかれる。そこでシエルは、自分は過去を変えられるという教祖の謎の力によって、両親が殺害された時の記憶を呼び起こされて…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a5ae544-5e9b-4422-b9d6-585a8f165ddf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea1752db-bfea-4034-a732-17f332061a58', '82da19f4-005a-4605-afa3-7c9bb1479181', 19, '100072036', 'その執事、入牢', 'テムズ川で死体が発見された。被害者のジョン･スタンレーは、女王のために働いていた裏社会の人物で、何者かに殺害されたらしい。女王から、彼の遺留品を手に入れ、秘密裏に処分するよう命じられたシエル。早速調査を始めた彼は、遺体が発見された地域を取り仕切る、上海マフィアのボス、劉のもとを訪れる。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b5f5528-3faf-4c4a-9da4-2feada60228c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39c1c50c-6c78-48c5-9393-39e1cfd88d10', '82da19f4-005a-4605-afa3-7c9bb1479181', 20, '100072037', 'その執事、脱走', 'ジョンの遺留品の行方を追う最中、シエルは何者かの罠にはまり、ロンドンで流行している麻薬“レディ･ブラン”に関与したとして警察に告発され、セバスチャンと別々に、ロンドン塔に幽閉される。孤立無援の状態に陥ったシエルだが、それでも一人で調査を続けようとする。そこにアバーラインが現れて…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/102f0a6e-befd-43c5-9411-62c1aabec57b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ef8d247-6697-4823-8038-f8183565d186', '82da19f4-005a-4605-afa3-7c9bb1479181', 21, '100072038', 'その執事、雇傭', 'シエルの使用人、メイリンとフィニ、バルドの三人は、落ち込んでいるようすの主人を心配していた。なんとか彼を元気付けようと相談を始めた三人は、ちょうど屋敷を訪れたエリザベスの意見を仰ぐことに。その結果、自分たちの笑顔で屋敷の雰囲気を明るくしようと決意する。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1bdfd0a0-d002-45b1-a2db-deebe69336d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c42b622-998f-4a76-af6c-2ff948af6412', '82da19f4-005a-4605-afa3-7c9bb1479181', 22, '100072039', 'その執事、解消', 'パリ万博に訪れている女王に謁見するため、パリを訪れたシエルとセバスチャン。そんな時、突然剥製が動き出して会場の照明を割り、会場は大混乱になる。セバスチャンの提言で、会場の外に一人避難したシエルだったが、そこで思いがけずアンジェラに遭遇してしまう。エレベーターの中へと逃げ込んだシエルだったが…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c613700f-d02c-4e71-a4be-f1447a971d45.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68361bcc-2719-4709-aa7b-d0b19dab94ba', '82da19f4-005a-4605-afa3-7c9bb1479181', 23, '100072040', 'その執事、炎上', '蒸気客船の貨物室内で、荷物の影に隠れていたシエルは、葬儀屋に出会い、ロンドンで多くの魂の回収が必要なことを教えられる。その時、人々の絶望の叫び声がして、シエルはデッキに出る。デッキからはロンドンの町が赤く炎に染まっているのが見えた。そして葬儀屋から、自分がもうすぐ死ぬということを告げられて…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44891080-72b9-4599-bc5f-28e194ed8aa0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c38d9f85-5d55-49fe-839f-7d349ec0c6a4', '82da19f4-005a-4605-afa3-7c9bb1479181', 24, '100072041', 'その執事、滔滔', '【第Ⅰ期 最終話】ロンドンで建設中のタワーブリッジの上に立っているアッシュ。セバスチャンはシエルを抱き、アッシュのもとへと急いだ。タワーブリッジの上、対峙する両者。シエルの口から、アッシュを倒すようにセバスチャンに命令が下される。ついに天使との決戦の火蓋が切って落とされた…。', '2021/01/21 00:00:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dfaba4de-7b7e-4712-8fd8-d01cba074935.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('23cb0002-688f-4c8f-89cb-407f8fb0051d', '黒執事', '', 'hulu', 'black-butler-kisyuku-gakkou-hen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2194dc8e-7e67-4595-934b-a550553b6b21.jpg?w=331&h=447&p=t', 'hulu', 2008, 3, 1, 'FINISHED', NULL, 4898, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', '23cb0002-688f-4c8f-89cb-407f8fb0051d', 'hulu-black-butler-kisyuku-gakkou-hen-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07887463-ab19-4a46-b82a-6a52d1aca05f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b11794b-a053-4762-9973-a491bb5d823f', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 1, '100181504', 'その執事、登校', '英国屈指の名門寄宿学校･ウェストン校に新入生として通うことになったシエル。4つの寮の監督生 (プリーフェクト)･P4が統治する学園は、伝統を重んじ厳しい規律に縛られた閉鎖空間だった。慣れない学園生活に翻弄されるシエルの前に、寮監に扮した執事･セバスチャンが現れる。', '2024/04/16 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07887463-ab19-4a46-b82a-6a52d1aca05f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31ffe2d1-94e1-4e84-bdf1-a3647f6f2507', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 2, '100182351', 'その執事、偽装', 'ウェストン校に通う複数人の生徒が音信不通になっている。その実態を調査せよ――。女王の命で学園に潜入したセバスチャンとシエル。学園を統治するP4に近付くため、シエルは学内の評価を上げ、P4とその寮弟だけの会合に参加する機会を得る。だがセバスチャン特製の茶菓子を手に会合の場を訪れたシエルを、予期せぬ事態が待ち受けていた。', '2024/04/23 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b596cb6c-1022-46f6-82ac-23fc3eece033.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ea787e8-46c3-4297-bbea-9b7f4c4b0e6c', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 3, '100182826', 'その執事、策謀', '自身を陥れたモーリス･コールへの借りを返すため動き出したシエルは、他寮の所属であるモーリスを監視させるため、ソーマを特例で入学させる。そこで明らかとなったのは、学園一の美少年･モーリスの裏の顔だった。', '2024/04/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44ce3a93-1e2c-4d58-9e43-7839d34d79f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5497afe-d422-4081-a88d-fc0471f02ece', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 4, '100183731', 'その執事、談合', 'モーリス･コールによって着せられた濡れ衣を晴らし、P4からの信頼を勝ち得たシエル。しかし未だ校長に近付く機会はなく、音信不通の生徒たちの調査は進まない。そこでシエルは、寮対抗クリケット大会に浮足立つP4とその寮弟たちに、デリック･アーデンの話題を持ち出す。するとP4の表情が一変し――。', '2024/05/07 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba49f440-811f-40d2-a3e3-b74cbb03e5fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46b34f6c-fd65-462e-bff4-e198dfc24acc', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 5, '100184435', 'その執事、入場', 'デリック･アーデンたちを寮から引きずり出すため、紫黒の狼 (ヴァイオレット･ウルフ) 寮に火を放ったシエルとセバスチャン。しかしデリックは現れなかった。八方ふさがりのシエルだったが、有力な情報を耳にする。ウェストン校伝統のクリケット大会には多忙な校長が現れる。そして、最も『紳士的なプレイ』をした生徒は、校長主催の『真夜中のお茶会』に招待されるというのだ。', '2024/05/14 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30014115-b789-4c18-9bd3-4155dfc436e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6a9d1f8-35a4-42c1-bd65-870934cbcf1a', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 6, '100184918', 'その執事、策動', 'クリケット大会の選手に選ばれたシエル。しかし、彼の所属する紺碧の梟 (サファイア･オウル) 寮は万年最下位の成績。そんな弱小寮が過去1度だけ優勝したことがあった。『碧の奇跡』と呼ばれる快挙の立役者が父･ヴィンセントであることを知ったシエルだが、奇跡ではなく力尽くで勝利をもぎ取ることを決意するのだった。そして大会は当日を迎える。', '2024/05/21 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96d94d46-76ac-4312-a640-8f3e48adf2fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5b4a6ed-4661-4529-afb9-253dd2f980fd', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 7, '100185899', 'その執事、決勝', '決勝戦まで勝ち進んだシエルたち紺碧の梟 (サファイア･オウル) 寮。一方、とうとう姿を現した校長を追うセバスチャン。選手たちの才能が惜しみなく発揮され、翡翠の獅子 (グリーン･ライオン) 寮の「力」と紺碧の梟 (サファイア･オウル) 寮の「策」が拮抗し試合が白熱するなか、セバスチャンは校長を捕まえることができずにいた。', '2024/05/28 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0aa6a695-7653-4514-8f8a-985d7f5919c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b62847f8-1291-4c9e-80e6-eba06307604c', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 8, '100186529', 'その執事、施錠', '熱戦を制し 、クリケット大会優勝をとげた紺碧の梟 (サファイア･オウル) 寮。後夜祭のメインイベントであるボートパレードで、シエルはヴィクトリア女王に真実を献上することを改めて誓う。その夜、シエルのもとに『真夜中のお茶会』の招待が届く。', '2024/06/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/521d7a29-af83-4159-84d4-292ac367f21a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91b07531-d0b9-4865-bb99-2bdb5612724e', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 9, '100187231', 'その執事、朗笑', '2024年6月8日放送分', '2024/06/11 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d7ec4f4-f038-472b-b126-2661df0d9c54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9c37d8e-73e4-4e67-b60a-8d34bfb72455', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 10, '100187873', 'その執事、賛同', '生徒失踪の真相。それはP4によるデリック･アーデンら5名の殺害、そして秘密結社･暁 (アウローラ) 学会による死者蘇生だった。さらに校長に扮していた人物の正体が、かつてファントムハイヴ家の協力者だった葬儀屋 (アンダーテイカー) であることが明らかになる。彼の目的は『動く死体』の進化だという。', '2024/06/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af316b9d-8934-4c52-a6f7-564298104ddb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a43afc3-a241-4ab3-b885-314023cb9365', '59ac8e00-4d8f-4e16-9f4c-7a8d891a47db', 11, '100188492', 'その執事、滑走', '【最終話】女王の番犬としての任務を果たし、ファントムハイヴ邸での日常に戻ったシエル。ファントム社の新商品視察のためセバスチャンたちとともに訪れたロンドンで、シエルは使用人たちの装身具を新調する。その後ファントム社の店舗に着いた一行は、通りで事故に遭遇。セバスチャンは意外な人物と再会する。', '2024/06/25 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c8be567-6273-4001-a49f-6344ed5261c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c7d51f52-17bd-4291-ae8d-2c832968ac11', '黒執事', '', 'hulu', 'black-butler-midori-no-majo-hen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/880e18af-c056-4821-90ac-4b28127116d6.jpg?w=331&h=447&p=t', 'hulu', 2008, 3, 1, 'FINISHED', NULL, 4898, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2d26808c-893e-49cc-9b52-18184c4b0d8a', 'c7d51f52-17bd-4291-ae8d-2c832968ac11', 'hulu-black-butler-midori-no-majo-hen-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ce99b4f-d632-43b0-9bbf-72a8f83e2488.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f02e01a-2a90-4a4a-98d9-742777b4d99a', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 1, '100223470', 'その執事、探訪', 'ドイツで不可解な死亡事件が発生。被害者たちは皆「人狼 (ヴェアヴォルフ) の森」に足を踏み入れ、「魔女の呪い」を受けたと言う。真相を調査すべく、セバスチャンとシエルは使用人たちと共に「狼の谷 (ヴォルフス･シュルト)」を訪れる。女性ばかりが暮らすその村で一行が出会ったのは、幼き領主ジークリンデ･サリヴァンだった。', '2025/04/08 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ce99b4f-d632-43b0-9bbf-72a8f83e2488.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5abb6c9-e20a-4b9d-9726-e85a38edd5a6', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 2, '100223858', 'その執事、警鐘', '領民たちの反対を制し、サリヴァンはセバスチャンたちに村への滞在を許す。村唯一の男性である、サリヴァンの執事ヴォルフラムは、不信感をむき出しにしながらも一行を「緑の館」へと案内する。晩餐を共にするシエルとサリヴァン。そこに、人狼が現れたとの知らせが飛び込んでくる。', '2025/04/15 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/850da5b5-eb32-445e-8ba7-be8c69468357.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c519ee7f-875c-4ea8-8c1d-498baea98e72', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 3, '100224795', 'その執事、出向', '禁を破り、「人狼 (ヴェアヴォルフ) の森」を調査するセバスチャンとシエルの体に異変が現れる。シエルはサリヴァンによる浄化の儀を受けるが、心身共に弱ってしまう。主人の治療を引き続き依頼するセバスチャンに対して、サリヴァンは思いも寄らない交換条件を突きつける。', '2025/04/22 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/996f3a99-4ded-4430-a08b-77374940945c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('220b5651-9d2f-4b09-8be2-fc83f80147d1', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 4, '100225531', 'その執事、奉公', 'サリヴァンとの交換条件により、彼女の執事として仕えることになったセバスチャン。一方で、別人のようになってしまったシエル。セバスチャンは自分の代わりに、世話役としてフィニを抜擢する。大人に怯えるシエルに優しく付き添いながら、フィニはシエルとの出会いを思い出す。', '2025/04/29 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19a34721-3bb4-4b13-8580-34f807d4960b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('583dd523-8ee3-4d4c-b06d-ce3b2db3c310', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 5, '100226438', 'その執事、下降', 'ヴォルフラムの目を盗み、セバスチャンとスネークが緑の館内を調べている頃、シエルとフィニは人狼の襲撃を受ける。サリヴァンは本来であれば起きえない事実にショックを受け、人狼たちと接触。「究極魔法」の完成を約束して、怒りを鎮めるよう懇願する。', '2025/05/06 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2375ae1-ac63-4f67-9270-91b4220670d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b9136d5-3e25-4e66-a6d8-99a3f8d17714', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 6, '100226904', 'その執事、失望', 'セバスチャンたちは、ヴォルフラムより「狼の谷 (ヴォルフス･シュルト)」からの退去を命じられる。そこへ現れたのは、ヴィクトリアからの手紙を携えた、女王の馬丁ジョン･ブラウン。時間の猶予がないと悟ったセバスチャンは、自身を拒絶し続けるシエルをきつく責め立てる。', '2025/05/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/777606fb-1f58-4694-8605-2c40859138cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90fdc960-88db-42bf-9ae3-9b582f55e996', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 7, '100227514', 'その執事、勧奨', '遂に究極魔法を完成させたサリヴァン。緑の魔女としての責務を果たし、次は村のためにも外の世界でたくさんのことを学びたいと話すサリヴァンだったが、ヴォルフラムに強く反対されてしまう。気落ちする彼女のもとに、セバスチャンとシエルが現れる。', '2025/05/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0a5c668-3571-422c-abee-dbd2d22b7889.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('041656f1-5111-4a1e-a46e-06c8600fa061', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 8, '100228103', 'その執事、狂暴', 'セバスチャンとシエルにより明らかとなった「狼の谷 (ヴォルフス･シュルト)」の正体。「緑の魔女」「人狼」「呪い」……その真実を知り、憔悴するサリヴァンに、シエルはある選択を迫る。', '2025/05/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b6d68ad-e4ca-45ff-9e09-6abd705a6abb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d78cf66f-c76d-43e5-85c9-a175e0c6c429', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 9, '100228664', 'その執事、遭逢', '血眼になってサリヴァンを追う村人たちと、ファントムハイヴ家の使用人たちが激闘を繰り広げる。渦中で、シエルはサリヴァンをフィニに託し、ある命令を下す。', '2025/06/03 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28c23402-61b2-4fe4-ad22-3b4638a36320.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a8d5b38-80db-4f61-bf80-60d9e21845b9', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 10, '100229276', 'その執事、掃討', '絶体絶命のシエルを救ったのは、父の親友ディーデリヒだった。彼の調査によると、「狼の谷 (ヴォルフス･シュルト)」は人狼や呪いを超えた、更なる脅威を隠し持っているらしい。 “それ”は、シエルたちに襲い掛かろうとしていた。', '2025/06/10 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4c4fa0c-2f00-417d-aa90-50201c96e176.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1483357-4f38-41d9-a0bf-2bf9820fd692', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 11, '100229806', 'その執事、不詳', '死線を潜り抜け、脱出経路で合流したセバスチャンたち。安堵したのも束の間、執念深く一行を追うヴォルフラムの魔の手が迫る――。', '2025/06/17 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff994b51-d54e-4fcf-94f9-62f5c340b4de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39b85efc-0baf-4af9-91c1-cc62d9de2a5c', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 12, '100230837', 'その執事、尋訪', '「人狼 (ヴェアヴォルフ) の森」から脱出を果たしたセバスチャンたち。ディーデリヒの屋敷に身を寄せたシエルは、寄宿学校での事件以来、行方不明となっていた葬儀屋 (アンダーテイカー) がディーデリヒのもとを訪れていたことを知る。', '2025/06/24 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67959911-5a4d-4f6b-8239-e2e8549b548f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d17c8b84-2b29-40e7-8921-7df92d3e53a5', '2d26808c-893e-49cc-9b52-18184c4b0d8a', 13, '100231373', 'その執事、潜航', '【最終話】英国に戻った一行。今回の「女王の番犬」最後のミッションは、粗野なサリヴァンをヴィクトリア女王に無事謁見させること。セバスチャンによる、厳しい淑女レッスンが始まる――。', '2025/07/01 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97128c34-e164-4ad6-9942-c4d748661008.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('48992b44-d8cc-49d6-843b-525a86b55baf', '黒執事 Book of Circus', '', 'hulu', 'black-butler-book-of-circus', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b63d3804-827d-472b-a7b2-a39c9443773b.jpg?w=331&h=447&p=t', 'hulu', 2014, 2, 1, 'FINISHED', NULL, 20606, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0227da77-a787-4e1c-bbfb-7132aea53846', '48992b44-d8cc-49d6-843b-525a86b55baf', 'hulu-black-butler-book-of-circus-s1', '第Ⅲ期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6517f83c-884e-4064-8de1-b8be1a60d385.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd2740d6-14af-42ca-8aca-693aad726ed8', '0227da77-a787-4e1c-bbfb-7132aea53846', 1, '100072054', 'その執事、披露', 'ファントムハイヴ家執事･セバスチャンの朝は早い。多忙な若き主人･シエルが快適に過ごせるよう全てを尽くす。それが執事の美学。ある日、シエルの仕事仲間の劉 (ラウ) とともに、ファントムハイヴ家に来客が。セバスチャンは最高のおもてなしをすべく準備にとりかかるが、ドジな使用人たちは失敗続きで…。今日もまた、ファントムハイヴ家の日常が始まる――。', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6517f83c-884e-4064-8de1-b8be1a60d385.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5a5303f-596c-4a13-8e23-b1d5e6d41e59', '0227da77-a787-4e1c-bbfb-7132aea53846', 2, '100072055', 'その執事、壇上', 'シエルのもとにヴィクトリア女王から手紙が届く。同封されていたのは移動サーカスのチケット。「ノアの方舟サーカス」が訪れた街から子どもが消える事件が起こっているのだという。「女王の番犬」として調査に乗り出すシエルとセバスチャン。さまざまなショーが繰り広げられる中、セバスチャンは心ときめく存在と出会ってしまい!?', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f57f8a8e-02a1-42a8-9478-06c95456b731.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4b4d83b-0e1d-4f09-a43b-b290fc135bc4', '0227da77-a787-4e1c-bbfb-7132aea53846', 3, '100072056', 'その執事、採用', '事件の調査のために訪れた移動サーカスで、サーカス団員にスカウトされたセバスチャン。潜入捜査をすべく、シエルも入団テストを受けることに。ナイフ投げや綱渡りを、セバスチャンの悪意あるフォローを受けながらこなしていくが…!?', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/568c8550-96eb-4190-b9e2-028d1d85414b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('381a47c7-12ac-4ff9-bb0f-16fa3931d2af', '0227da77-a787-4e1c-bbfb-7132aea53846', 4, '100072057', 'その執事、同僚', '潜入したサーカス団で、新人として紹介されたのは死神･ウィリアムだった。まさかの邂逅の驚きが冷めやらぬままに、セバスチャンとウィリアムは宿泊テントまで同室になってしまう。険悪な雰囲気のまま対峙する二人。そして夜が更けていく…。', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61e5d0b0-376d-4a3d-896b-4d9ad0069180.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c20bbf76-7ff0-4d04-8225-b9cf0e54882d', '0227da77-a787-4e1c-bbfb-7132aea53846', 5, '100072058', 'その執事、飛翔', '調査も残りは一軍テントのみ。テントに人がいなくなる公演時間を狙って調べようとしたところ、アクシデントによりセバスチャンがサーカスに出演することに。一人テントを探るシエルだったが、公演を終えて戻ってきたドールに見つかってしまい…!?', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c122911d-37c3-4a6b-b5ee-5296e19a0c2e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90a45596-5840-4cf9-80bd-97fedbf08cbc', '0227da77-a787-4e1c-bbfb-7132aea53846', 6, '100072059', 'その執事、交渉', '無理がたたって倒れてしまったシエル。身動きの取れない主人に代わって、調査に出るセバスチャンだったが、その前にウィリアムが立ちはだかる。サーカス団の外に出ることを阻まれたセバスチャンは、傷心のビーストに近づき…。', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57dad893-0229-419b-905e-ff2b8dca73b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc37864d-d5a7-4b81-bd55-7891d626ebbc', '0227da77-a787-4e1c-bbfb-7132aea53846', 7, '100072060', 'その執事、撫養', '“お父様”と面会するジョーカー。タウンハウスに戻り、ソーマ&アグニの強い勧めでシエルを療養させるセバスチャン。セバスチャンの看病で回復したシエル。動き出すサーカス団員たち。それぞれの想いを胸に、全てが動き始める。', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0eb9063-240b-47d8-b71e-a84734fdd8f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebf61aff-fe79-4fc6-80bc-dd2bb18fae29', '0227da77-a787-4e1c-bbfb-7132aea53846', 8, '100072061', 'その執事、嘲笑', 'ケルヴィン男爵によって語られる衝撃の真実。過去のシエルとケルヴィンの歪んだ繋がりが明らかに。それを知ったシエルが取った行動は…。そのころ、エリザベスが滞在している使用人たちだけのファントムハイヴ邸に、サーカス団の魔の手が迫っていた。', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aaf12225-0805-4d2c-9edb-45ef925e521d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7434484a-772c-4cb7-8ad0-7e0b109aa540', '0227da77-a787-4e1c-bbfb-7132aea53846', 9, '100072062', 'その執事、従容', 'サーカス団員たちの襲撃を迎え討つファントムハイヴ家使用人たち。セバスチャンとシエルが選んだ彼らはファントムハイヴ家の秘密と誇りを守る私兵だった。その事実を知って絶望するジョーカー。彼らが抱えていたものとは…。そしてシエルが下す決断は…?', '2021/01/21 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44db01a3-3ca2-4582-af91-c5b8852cb3b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa270fc1-d492-453d-aaa7-dac18c37b546', '0227da77-a787-4e1c-bbfb-7132aea53846', 10, '100072063', 'その執事、遂行', '【第Ⅲ期 最終話】舞い上がる走馬灯劇場 (シネマティックレコード) に映るのは悲しい過去だった。ケルヴィン邸にたどり着き、真実を知ったドールの悲鳴と刃がシエルに向けられる。鞄からこぼれおちるキャンディー。全てが炎に包まれ、閉幕の時を迎える。', '2021/01/21 00:00:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebac837a-5616-4be0-b916-254f35f796ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7c5bd85f-3a86-449a-a288-9cc496f5ec60', '黒執事', '', 'hulu', 'black-butler-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fb55cea-e16e-4699-b8cb-033d300af774.jpg?w=331&h=447&p=t', 'hulu', 2008, 3, 1, 'FINISHED', NULL, 4898, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8e981dc1-b696-4a0e-9af6-b728a7c64485', '7c5bd85f-3a86-449a-a288-9cc496f5ec60', 'hulu-black-butler-2-s1', '第Ⅱ期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e26b85c7-f9ad-4484-a9c5-163529e47131.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5971f31b-cf3e-4076-9180-27b8a3b49fe1', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 1, '100072042', 'クロ執事', '19世紀後半、英国。名門貴族トランシー家の若き当主、アロイス･トランシー伯爵の傍らには、常に漆黒の執事クロード･フォースタスが付き従っていた。ある晩、トランシー邸に一人の旅人がやって来て――。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e26b85c7-f9ad-4484-a9c5-163529e47131.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad9147a6-9f7e-4251-9cc8-cd2679ccbd2e', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 2, '100072043', '単執事 (そろしつじ)', '今日は、ファントムハイヴ領に新たに作られた水門の開通式。エリザベスは、見た者に幸運をもたらすという『幻の白いシカ』を探しに行こうとシエルを誘う。果たして白いシカは見つかるのだろうか?', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48f91bec-19a7-41d4-8805-485d681b16de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6722269-d5e6-4fd9-a217-97020fbc59b7', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 3, '100072044', '女郎執事 (めろしつじ)', 'ロンドンで頻発している、原因不明の人体発火事件。女王の命を受けたシエルは、誇り高き“女王の番犬”として、事件を解明するためセバスチャンと共にロンドンへ向かう。やがて犯人を突き止めた2人の前に、死神――グレル･サトクリフが現れる。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a55f454-57cf-41b7-82d8-e69102b5eb5c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54761c86-889f-4b52-972d-8d734ad17fca', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 4, '100072045', 'テロ執事', '女王の命を受け、誘拐事件の犯人の乗り込んだ列車へと潜入するシエルとセバスチャン。そんな中、列車内で護送中の殺し屋が脱走、さらには仕掛けられた爆弾の存在まで明らかになる。危機的フルコースの連続に、セバスチャンはどう対処するのか…!?', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/feb39da1-fead-4ef7-90c1-3a20e59ce6fa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e43a1e3-b28f-4c6e-94f9-e8cad24f12b5', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 5, '100072046', '狼煙執事 (のろしつじ)', 'トランシー家の主催する仮装舞踏会に招待されたシエル。舞踏会には、エリザベスやソーマたちも訪れており、思い思いの格好に仮装しながらパーティーを楽しんでいた。“女王の蜘蛛”と呼ばれるトランシー家を不審に思うシエルは、密かに邸内を探るよう、セバスチャンに命じる。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/228c04b4-e6a3-4a29-a821-f870a7cacc4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a07e2585-0412-4da9-b915-b372a679c84d', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 6, '100072047', '夜露執事 (よろしつじ)', 'ついに対峙する二組の主従。トランシー家使用人のトンプソン、ティンバー、カンタベリーの仕掛ける連携攻撃がセバスチャンを襲う。その頃、舞踏会の会場では、“天使の歌声”という別名をもつ楽器、アルモニカが演奏されるが、その音色を聴いた招待客の様子に変化が現れて…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b820324d-66d6-4b88-b48c-bfd7f08ac551.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2882ff8-624f-42cf-b0da-6dac8d0ad70b', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 7, '100072048', '殺執事 (ころしつじ)', 'シエルのもとへ、再びトランシー家から舞踏会への招待状が届く。今度こそアロイスとの決着を着けるため、セバスチャンとともにトランシー邸を訪れるシエル。そこでは、“ダンス･マカーブル”――「死の舞踏」を踊るべく、アロイスとクロードが待ち受けていた。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40188eee-2a05-4237-b202-c6ebd2ae0487.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9880a49-e0ae-4569-aedc-0c60d06255dc', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 8, '100072049', '吐露執事 (とろしつじ)', 'シエルとの決闘により重症を負ったアロイス。痛みに苦しみながらも、クロードがシエルの魂に興味を持ち始めたことに不安を覚える。クロードを失いたくないという一心から、自らシエルのもとへと向かう間、アロイスは、自分のこれまで歩んできた人生を思い返していた…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cabd0bc9-0e2b-482b-ba03-4d96c80557ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9d25491-8b2d-49df-886f-72e7a5dd319c', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 9, '100072050', '虚執事 (うろしつじ)', 'アロイスとの決闘以来、眠れない日々が続いていたシエル。そんな折、女王陛下からの伝言が届く。ロンドン周辺で近頃、何者かによって『目玉がくりぬかれる』事件が頻発しているというのだ。早速ロンドンへと向かうシエルとセバスチャンだったが、そこにはある人物が仕掛けた罠が張り巡らされていた。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0248ace0-2345-4fde-8fde-71fcff9a535e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dba40542-d06b-4577-a4c8-7ac50ffc5d30', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 10, '100072051', '零執事 (ぜろしつじ)', 'ついにシエルを手に入れたクロードは、その魂の味に魅了され、トランシー邸でシエルとの至福の時を過ごす。一方セバスチャンは、グレルから、アロイスの魂が「指輪」になっていることを聞き出し、彼の過去を探り始める。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97970fb5-8d70-4feb-b894-abf9cee18312.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76c5a12b-a604-4af7-bb19-9926ad47a69d', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 11, '100072052', '岐路執事 (きろしつじ)', 'アロイスの魂はシエルの身体を乗っ取り、自らの心の迷宮を具現化した“薔薇迷宮”を作り出し、セバスチャンとクロードに旅をさせる。2人の執事はシエルの魂を手に入れるため、迷宮内で出題される様々な問題に解答しながらゴールを目指すのだが…。', '2021/01/21 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c821b1b6-b6fa-42a9-ac32-844c8e357e18.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06d54f54-db9e-4e8a-951c-34e559aae290', '8e981dc1-b696-4a0e-9af6-b728a7c64485', 12, '100072053', '黒執事 (くろしつじ)', '【第Ⅱ期 最終話】シエルの身体を支配したまま、ハンナと再契約を交わしたアロイス。その契約内容には、セバスチャンとクロードどちらかが、悪魔としての生を終えることが含まれているという。そしてハンナは、悪魔のサンクチュアリである「死の島」で、セバスチャンとクロードに“悪魔同士の決闘”を命じるのだった。', '2021/01/21 00:00:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/154f4e84-0278-42b6-aecd-c2e40100de34.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2f5aa8eb-b5ae-46b7-9ac7-8b7cb9da4988', '今日からマ王！', '', 'hulu', 'kyo-kara-maoh-god-save-our-king', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9aacc234-e557-4468-aaf7-79dc2128093a.jpg?w=331&h=447&p=t', 'hulu', 2004, 1, 1, 'FINISHED', NULL, 251, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', '2f5aa8eb-b5ae-46b7-9ac7-8b7cb9da4988', 'hulu-kyo-kara-maoh-god-save-our-king-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a167a582-f9ab-439c-bdc3-dab0de3f679c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9342f6dc-eaa0-4d06-a6fe-b9ea0a7f2bcc', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 1, '100109566', '流されて異世界', '正義感の人一倍強い渋谷有利は、ある日、不良たちにからまれている元同級生を助けに入るが、返り討ちに遭い公衆トイレに連れ込まれる。「便器に顔を…!」と思いきや、水に流され異世界へトリップ。果たしてそこは、欧風テーマパークにしては大げさすぎる広大な世界。不安に駆られ汗ジトの有利は、ただ立ち尽くす…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a167a582-f9ab-439c-bdc3-dab0de3f679c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b730ff0-90ef-42c4-a5be-a148c04080a3', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 2, '100109567', '決闘! 美少年VS野球少年', '訳も分からぬ間に城へ連れて来られた有利は、前魔王ツェリや何故か態度が冷たいヴォルフラムとグウェンダルたちとの軍事会談のような厳めしい晩餐会の席で、母親のことを貶したヴォルフラムの頬を引っ叩く。一同騒然となるが、その理由は有利の想像をはるかに超えたこの世界のしきたりがあったからだった…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee7797cb-7e83-482e-84b4-b7e2b98cb788.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5498064-215e-421d-86f4-962bf4467856', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 3, '100109568', '渋谷有利! 俺がマ王だ', '国境近くの村で起こった紛争を収めようとヴォルフラムと共に血盟城を抜け出す有利は、炎に包まれる村で、アーダルベルトと再会する。法術により動きを封じられたヴォルフラムをよそに有利を懐柔しようとするアーダルベルト。彼は語る、「人間の村に火を放ったのは、人間であり、この紛争は人間同士の紛争である」ことを…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/069585e0-334b-4583-a2cf-77774b46dfe3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd72452d-a2c8-4f92-b813-c05fffd38928', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 4, '100109569', '今度は最終兵器!?', '魔族の下着である紐パンを母の美子に見つかり赤っ恥をかきつつ、異世界での体験は夢ではないことを実感する有利。一度はあきらめた野球を村田健と再開し、「草野球だけど、また始めたって聞いたらコンラッドは何て言うだろう?」と感慨に耽ったのも束の間、またまたマの悪い時に眞魔国への扉は開かれるのであった…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1a88039-55bb-42b8-b952-46b568f2686f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8cde789-0bbc-48a4-ae62-93f454f2058e', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 5, '100109570', 'セーラー服ときかん坊', '失われた聖剣･モルギフを求めて豪華客船でコンラッドとお忍び (笑) の旅に出た有利。快適な船旅と思いきや、無理やりついて来たヴォルフラムは船酔いだわ、変装用のコンタクトは目に痛いわで先が思いやられる船出となった有利に更なる災難が降り掛かる。突然、有利たちの乗る豪華客船が、海賊に占領されたのだ…!', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26c38200-c708-445e-92c5-febff4fb86d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf7c73c4-b34a-4013-a5f5-6891253a9d5e', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 6, '100109571', '人喰いマ剣･モルギフの恐怖?', 'ヴァン･ダー･ヴィーア島にたどり着いた有利一行は、休憩に立ち寄った峠の茶屋の女将から、15～16年前に起きた山頂の泉での不思議な出来事を耳にする。その出来事が、魔剣･モルギフによるものと確信した一行は、さっそく山頂の泉へ赴く。不気味な様相の泉、鍾乳洞。果たして魔剣･モルギフは…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5e5d2ea-4bef-4eac-bff8-3bb37ca2995a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffb15902-1f0d-48fd-b322-e54862b754ad', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 7, '100109572', '暴走? 迷走? マ剣発動!', '大勢の観客が見守る中、囚人との一騎打ちをする破目に陥り、闘技場に立ち尽くす有利。対戦相手として目の前に現れたのは、かつて有利が窮地から救った客船の少年船員、リックだった。容赦なく斬りかかってくるリックに困惑し防戦一方の有利は、彼の口から信じ難い事実を聞かされ愕然とする…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ba5f90a-bb7f-4f2e-9fc9-7131cbc7b673.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12b8019d-2257-428e-8a10-b03b7811f43c', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 8, '100109573', '月下の陰謀', '川岸のグラウンドで草野球の練習に励む有利。落ちたボールを拾おうとして川に足を滑らせ、またまた眞魔国へ…。初代魔王の魂が眠る眞王廟に出現した有利は、眞王の託宣を授かる巫女のウルリーケと出会う。彼女には特別な能力があり、有利の身に不吉なことが起きようとしていることを悟っていた…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7419ffbb-4e46-4793-b0b1-5736676104ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('280af81a-f13e-411a-b652-abbd7471fe0c', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 9, '100109574', '盗まれた秘宝', '眞魔国の秘宝中の秘宝「竜王の石」が、盗まれた。意外と平和な眞魔国ライフに退屈していた有利は、待ってましたとばかりに盗難事件の捜査に乗り出す。捜査に付き合うコンラッドとヴォルフラムは、有利の周囲に不審な影の存在を察知する。俄かに緊迫する血盟城。有利の身にマの手 (?) が迫る…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0710381a-286d-4c8b-9e51-56c22200a5cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fd18444-36f7-4632-b73f-4d0e8a295caa', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 10, '100109575', '迫り来るマの手!', '謀反を企てるシュトッフェル。彼を説得し、平和裏にことを治めようと魔王･有利は、コンラッド、ヴォルフラムと共に、シュトッフェルの居城、シュピッツヴェーグ城へ向かう。一方、アニシナを筆頭に、グウェンダルら居残り組みが、ギュンターの頭を締め付ける呪いの輪っかを外そうとあの手この手で奮闘中で…!', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/302fc7a9-903f-464a-ab30-962172926aef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2336faca-93e2-4ed1-8b38-172d2878d71f', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 11, '100109576', '次元のむこうで戦争がはじまる', '誘拐され、シュピッツヴェーグ城に幽閉された有利は、クーデターを目論むシュトッフェルにより洗脳を受けていた。その頃、コンラッド、ヴォルフラムと大軍を率いるギュンター、グウェンダルは、有利救出のためシュピッツヴェーグ城へ馬を走らせる。いよいよ旧政権と現政権の戦いの火蓋が切られる…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e838de71-5db5-4f9b-856c-cb4c1595ae7f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ab74924-b4fe-4794-8072-7d968dd1d990', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 12, '100109577', '愛と宿命の鎖', 'イルカショーを見物中に異世界へ流された有利。本人であることを執拗に確認するヴォルフラムたちに事情を訊くと、スヴェレラという国で、ニセ魔王が食い逃げ (笑) の罪で処刑されるという噂が流れていて、さらにそのニセモノは、魔族の至宝である魔笛を所持しているという…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/082b87bb-d725-4e2c-bb51-f13b5c355248.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc669f42-f50e-438a-9a2a-cd589b197146', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 13, '100109578', '花嫁と有利とグウェンダル', '追っ手を逃れ挙式中の教会へ入った有利とグウェンダルは、成り行きで、花嫁の脱走に手を貸すことに。花嫁･ニコラは魔族である恋人を守るため、人間の男との愛の無い結婚を強いられていたのだという。不幸な花嫁の身の上話に聞き入る有利たち。ところが、ニコラの口を突いて出た恋人の名前を聞いて、グウェンダルの表情が豹変する。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75386507-79f6-44d6-86de-5a6058249e1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f365724-ef9c-4891-9476-7d9a127c6073', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 14, '100109579', '有利、重労働す', '囚われの身となった有利とグウェンダルは、護送用の馬車の中で語り合う。語らいの中で、有利の権力欲の無い純粋な正義感に感銘を受けグウェンダルは思わず笑みを漏らす。心を打ち解け合ったと思われた瞬間、馬車が止まり二人が連れ出されたのは、裁判所だった。二人は、駆け落ち者として裁かれることに…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1aefc32-9fcf-4d75-96da-2803f769bb9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ceee427-4b7d-4981-8837-63d7423dffd0', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 15, '100109580', '砂漠に降る雨', '意識を取り戻した有利は、スヴェレラ軍の追っ手から逃れるため、仲間と共に採石場を後にする。思うように距離を稼げず焦る一行の前に、突然、巨大な砂熊が現れ凶暴な雄叫びを上げる。慌てる一同。踵を返すとそこには、スヴェレラ軍が控えていた。有利危機一髪!「前門のパンダ、後門のモヒカン…」', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c16dd4df-6845-46ae-93cc-3d59f880b0ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e538c3fc-34fd-407c-97ae-98b9eeed0747', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 16, '100109581', 'マ王捕物控!', '地球に帰れなくなり、ギュンターから帝王学を叩き込まれる毎日でボロボロの有利は、休憩時間のキャッチボールでコンラッドに思わず愚痴ってしまう。そんなある日、血盟城に運搬途中の魔石が何者かに盗まれたとヨザックから報告を受ける。魔石とは魔力を回復させたり魔動装置を直したりできる石で採掘量が少なく、貴重なものだと言う。勉強をサボるチャンスとばかり犯人探しに乗り出す有利だが…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b36702ac-8385-49e7-9026-1c2c1ad669cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72fad487-9548-4a48-b8c4-55b3bf55f6a7', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 17, '100109582', '私、再婚します', '「私、再婚します!」と、ツェリの突然の大宣言。その再婚相手とは、シュトッフェルの部下であるレイヴンだった。再婚式の準備が、着々と進められる中、ツェリ、シュトッフェル、レイヴンの三人の脳裏に、秘められた甘酸っぱい青春の日々が蘇る。そして再婚式当日、有利も巻き込んでの大騒ぎの予感で…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6f12ad2-d035-4d31-868e-3c71b5716a37.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('352b2a7b-2d0d-4e82-97b6-a57d7ddac76a', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 18, '100109583', 'その愛のために', '魔王の間に無断で入ってくるヴォルフラムに業を煮やした有利は、廃屋同然の迎賓棟に目をつける。聞けば、使われなくなって久しい迎賓棟には、今は恐ろしい怪物が潜んでいるとのこと。「怪物を倒してそこにヴォルフラムを住ませれば、もうオレの部屋に来なくなるかも!」有利の一人部屋獲得大作戦が幕を開ける…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e7d01e8-8503-4191-b88f-08518cdaa205.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46708c53-f73c-4db7-b7ce-65f5e9f6adad', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 19, '100109584', '勇者VSマ王前編', '思いつきで、コンラッドたちを引き連れ、竜を見に出かける有利。一向は、険しい山道を越え、密猟者用のトラップをかわし、なんとか竜と対面する。最初は警戒していたが、悪意の無い有利に少しずつ打ち解けていく竜。一方その頃、竜退治の青年･アルフォードと密猟者の一団が、有利たちの居る竜の巣に迫っていた…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b464e18-4340-47f3-8f33-d061c9b45a67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9143094f-d905-4722-8251-8162addbe0cd', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 20, '100109585', '勇者VSマ王後編', '有利一行は、密猟団からの襲撃をかわし、捕縛した勇者のアルフォードから事情聴取を行った。それにより有利は、アルフォードが魔王や竜について間違った認識をしてはいるが、心根は正義に基づいていることを悟り、彼の縄を解いてやる。一方、一時撤退していたベルマたちは、新たなる竜捕獲の作戦を着々と進行していた…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d6367a9-d789-4ca1-b944-6dbfee08241d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f761597a-1721-4632-8c6b-86133eec2894', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 21, '100109586', '危険な訪問者', '魔族語の読み書きも多少できる様になりすっかり上機嫌な有利の前に暗殺者が現れた! 寸でのところで凶刃をかわすが、その姿を見て有利は愕然とする。なんと有利を襲ったのは、年端もいかない女の子だった。捕らえられた女の子から有利はさらに衝撃的なことを聞かされることに…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce803d11-e6f0-4718-acda-e5ed2b0ff9d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9261291-a03b-40c6-841a-46b9b3c463ab', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 22, '100109587', '運命の男', '「女の子いじめて遊ぶなんてあんまりいい趣味じゃないよ、おじさんたち」湯治のため、シルドクラウトを訪れている有利。場所が変わっても相変わらずお節介者。そのせいでならず者たちと一騒動。一方、そんな有利を探すヴォルフラムの前に立ちはだかる謎の仮面剣士。その力はヴォルフラムを軽く凌駕する。果たしてこの男の正体は?', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73ee3124-c5f3-4c2b-bb77-fb30e7e5347d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72825398-7813-4d85-880c-34be15b8dffd', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 23, '100109588', '炎のレース', 'ビロンから不当に扱われている人々を解放するため、魔王である自らを賭けて珍獣レースに参加する有利。競走する珍獣は、ライアン率いる「砂熊ケイジ」とビロン所有の「地獄極楽ゴアラ」。競技が始まるや否や愛らしい容貌とはうってかわり凶暴な本性をあらわす地獄極楽ゴアラ。レースは、俄に異様なムードに包まれる…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93e3db39-813b-4d8a-a821-3c359d021be7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ea7f3b7-3d3a-4076-8702-365a848a3a76', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 24, '100109589', '許されざる者', '眞魔国に戻った有利を待ち受けていたのは、傷ついたヒューブに対するグウェンダルたちの冷遇だった。有利は、自分が全く知らない20年前の傷の大きさを目の当たりにし、唯一ヒューブを治療しようと動いてくれたギーゼラに、事の真相を尋ねる。そして、過去の出来事が静かに語り出される…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd5a27dd-6717-4f4d-9c65-3586466bdbed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5cb33bbf-d82d-43f0-b38a-2b6b452cd43d', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 25, '100109590', '過去と未来', '許されざる罪を償うため、死を決意したヒューブ。魔族の秩序を守るため、ヒューブを罰せんとするグウェンダル。ヒューブの魔族としてのプライドを尊重し黙して見守るコンラッド。死を以って罰することを許容できずに戸惑う有利。それぞれの思いが交錯する瞬間、グウェンダルの剣が振り上げられる…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97677c26-9ea4-4d58-88d6-dcc970afd867.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a06e7196-5a3b-4295-89bc-115923f5842d', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 26, '100109591', '巡る命の果てで', '有利が元の世界へ戻された後の血盟城では、一抹の寂しさがありながらも騒々しい時間が流れていた。コンラッドはそんな一同を見守りながら、過去に思いをはせる。それは、今は有利のものである魂が、ジュリアと呼ばれていた頃…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e21c9233-10b7-4665-84d6-633e1ce6fb7f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5f2e523-ad9a-413e-9cf0-aa73e6d7a79d', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 27, '100109592', 'コンラッドの腕', '夏休み中、海水浴場で、親友･村田とアルバイトをする有利は、海に飛び込んだ拍子にまたまた異世界へトリップ。いつも通り眞魔国に到着した有利だが、今回は、どうも様子がおかしい。殺気立ったコンラッドとギュンターが、有利に駆け寄り地球に帰るよう促す。訳を訊くと人間の国が、魔族との開戦準備を始めていて眞魔国ですら安全ではないと言う。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/440e47da-1aa1-4c7f-a700-300de6e2f240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc704789-bad0-461a-bd1f-266320457353', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 28, '100109593', '凶悪な再会', '有利の失踪に揺れる眞魔国。ヴォルフラムは単身、眞王廟に駆け込み、有利の居場所を知っているであろう言賜巫女･ウルリーケに詰寄る。一方、自ら仮死状態となったギュンターは、アニシナとグウェンダルによってとんでもない姿で…いや、新たな姿で蘇ろうとしていた。当の有利はそんな混乱など知る訳もなく、村田と共にカロリア領主の館で手厚いもてなしを受けていた。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c91019a-617b-498a-8033-7bc4f1f92551.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5507110c-873a-45f0-a146-15219d75de96', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 29, '100109594', '戦慄の序章', '小シマロンと大シマロンの小競り合いのどさくさに紛れ、有利と村田は、フリン･ギルビットの手引きによりカロリアを脱出する。一行が逃走のため乗り込んだのは、強面の囚人たちと羊の群れがひしめき合う異様な輸送船だった。関わりを持たぬよう勤めていた有利だったが、囚人たちにからまれるフリンを見て持ち前の正義感がうずきだす。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd42e4d5-4277-45bd-9d55-2c7ebccce989.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f28631b7-c2fe-4c77-b217-b233bf83a546', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 30, '100109595', '禁じられた箱', '有利を捜し求め、カロリアに降り立ったヴォルフラム、ギーゼラ一行は、ギルビットの館を訪れ、執事･ベイカーに有利の行方を尋ねる。しかし、何故か真相を語ろうとしないベイカーに、ヴォルフラムたちは、業を煮やす。その頃、グウェンダル、ギュンターの待つ血盟城では、コンラッドの左腕が盗まれるという事件が起こっていた。果たして、腕を盗んだのは、何者なのか。そして何のために…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd557a23-546e-43dd-9ffd-581f39fea23d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46f33530-f65f-4544-aa8b-8f74eee02795', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 31, '100109596', '地の果て', '禁忌の箱を開く儀式が進む中、「虎視眈々と世界の支配を狙う邪悪な存在」と魔族を称するマキシーンの演説に、賛同の意を示す人々。それにショックを受ける有利に対して村田は、「その誤解のために傷つく民衆こそ守らなければいけない。」と統治者の自覚を持つよう説く。思わぬ人物からの助言に、驚く有利は、村田からさらに驚くべき出生の秘密を聞かされる。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c87b29dc-b201-4977-9d73-e645bd7687fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4554ed84-0baa-43bf-a063-ef4047d75a86', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 32, '100109597', '鍵をかけられた記憶', '発動した「地の果て」の被害は、遠くカロリアにも及んでいた。崩れた港と脅える人々を前に有利は、二度と「地の果て」が開かないよう、鍵となったコンラッドの腕を処分しようと決意する。しかしグウェンダルは、コンラッドの腕を人間に対する抑止力にするよう迫るのだった…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8373e9ab-394f-45f5-ba11-b9f359b3b889.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36943c03-afe3-48fc-b44e-11af3c72f639', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 33, '100109598', '激走! 雪ゾリレース', '大シマロンからの天下一武闘会開催の知らせを受け、表情を曇らせるフリンに、有利は困惑の理由を尋ねる。フリンは、「四年に一度催される天下一武闘会は、宗主国である大シマロンが属国に権威を誇示するための祭典」であり、目的を果たすためには、八百長も辞さない公正を欠いたものだと言う。正義感に火が点いた有利は、追い縋り涙するギュンターをも振り切り、天下一武闘会に出場するため、港を後にする。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e569774-d29d-4a39-8ccf-0600803f6d74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a729ab90-39f9-44a9-aa3e-05f770b6c0a9', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 34, '100109599', '熱闘コロシアム!?', '禁忌の箱の一つ「風の終わり」を取り戻すべく天下一武闘会に参加した有利たちは見事、優勝戦へ進出。だが、国の威信をかけたこの一戦には強力な代表選手団が待ち構えていた。その中にはなんと、大シマロンの制服を身にまとい不敵に微笑むアーダルベルトの姿が…。意外な人物の登場に驚きを隠すことも出来ず、呆然と立ち尽くす有利一行。果たして、武闘会の行方は如何に!', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b69f00fb-d141-46ad-b4ad-2ef4f2c9689e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('602ddb79-e3b4-403a-bfa1-b6ca05c3058d', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 35, '100109600', '雪降る大地', 'フリンを人質にとり有利たちに試合放棄を要求していたマキシーンは、偶然居合わせたツェリの怒りを買い散々な目にあわされる。しかし有利たちがフリン解放を知った時には、中堅･ヨザックが負けた後。試合は、1勝1敗で大将戦までもつれ込み、カロリアチームは有利の出番。対する大シマロンチームのベンチからは、意外な人物が現れる。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4dcfea8-4629-4a63-a249-cff200c6032d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d81ca88b-a358-46f0-8fe6-e83a8d3aed92', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 36, '100109601', 'さらばコンラッド', '大シマロンの戦士として現れたのはなんと…。信じられない気持ちのまま、一同は、有利の魔王化によって騒然となったコロシアムを後にする。「なんで…なんでなんだよ…!」大シマロンが持つ禁忌の箱「風の終わり」を手に入れ、目的を果たしはしたものの、一同の間には重苦しい空気が漂う…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19198c47-21dc-4f74-8598-f9577d7ae73e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65a50881-581f-4e2c-8cff-b8f53f830185', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 37, '100109602', '箱の行方', 'やっと再会できたコンラッドの信じられない言葉が脳裏を離れず、有利は地球に戻っても一人思い悩む。そんな有利を見るに見かねて村田は、有利と共に再び眞魔国へトリップする。眞魔国に着いてもコンラッドの姿は無く肩を落とす有利だったが、彼を心配しすがり付くグレタを見て、少しずつ冷静さを取り戻す…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2effca94-03a2-4566-9410-2f95ac5bc8b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d45e962-9e3b-4028-879c-06dea0ed1618', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 38, '100109603', 'ギュンターVSコンラッド', '新たな箱を求め小国･フランシアに向け船出した有利一行は、入港許可を得るためフランシアと国交があるカヴァルケードに立ち寄る。ヒスクライフの助けを得て、無事カヴァルケード王との会見を終えた有利たちだったが、時を同じくしてフランシアでは、大シマロンの使者が、密かにフランシア王･アントワーヌに謁見しようとしていた。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08bf00e3-f3ef-43d3-83e7-5073f04a5779.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b7f878f-76ff-4bc5-9286-ada98d65e635', '2bc5c40a-05fa-4586-a41e-3c4ea7bcd2c4', 39, '100109604', '君の名はマ王', '【第1シリーズ 最終話】フランシアに禁忌の箱がある! 有利たちは、箱を求め国中を探し回る。一方、大シマロンも箱を手に入れるため戦力を送り込んでいた。そんな中、「遺跡に箱がある」とライラから知らされる有利。が、そこにはすでに大シマロンの大兵団が待ち構えていた。しかし、遺跡にはさらに驚くべき罠が、意外な人物によって張り巡らされていた。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ece2d80e-3541-4db1-8607-f00a68be2262.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('775cf4c9-b2fa-4ebb-b311-b25c84729e29', '2f5aa8eb-b5ae-46b7-9ac7-8b7cb9da4988', 'hulu-kyo-kara-maoh-god-save-our-king-s2', '第2シリーズ', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/512ed3ca-0fe5-4766-a190-c6f363a6c243.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92082c37-eedd-413a-9970-a0042787621a', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 40, '100109605', '絆のために', '大シマロン軍による厳戒態勢下、カヴァルケードへ越境を試みようと準備する有利一行。しかしコンラッド率いる大シマロン軍は既にライラの家を取り囲んでいた。改めてコンラッドの裏切りにショックを受ける有利、抗戦の構えのヴォルフラム、ヨザック。だが、なぜか村田は、冷静にヴォルフラムたちを制止するのだった。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/512ed3ca-0fe5-4766-a190-c6f363a6c243.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0466edda-a29e-4f30-a48f-870c0bcf8b1b', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 41, '100109606', 'コンラッドの帰還', '何とか危機を脱し、大シマロン軍を撃退した有利たち。フランシアとの同盟締結も決まり、有利を中心に、種族をこえた同盟の輪は広がりつつあった。一方、罪人としてフランシア城に幽閉されたコンラッドは単身脱走、再び有利の前から姿を消そうとする。それを知った有利は…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caaf9e8f-7811-4beb-a6a6-2ede4fb1c62a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3e58436-11e7-4379-9167-afa39a96ff59', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 42, '100109607', '遠い約束', '日曜日、村田との待ち合わせに出かけた有利は、ロドリゲスという外国人に声を掛けられる。シドロモドロの有利のもとに現れた村田は、なぜかロドリゲスと親しげに話し出す。その頃、有利の兄･勝利は、自室のパソコンで、ある人物からのEメールを読むうち、幼い頃のある出来事を思い出した…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d0a4238-fc9b-43cb-9dc0-6fe3fb996b7f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61bd2e36-6ba6-446a-bb6f-b6b3e18bb7d1', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 43, '100109608', '血盟城ベビーパニック!', '血盟城内のいつにない慌ただしさに、うろたえる有利。ヴォルフラムに尋ねると今日は、年に一度、その年に生まれた子供たちのことを眞王に報告する「眞誕の儀式」の日だという。その儀式に参加するため、ニコラが、子供のエルを連れてやってきた。有利たちは、儀式の準備に忙しいニコラに変わって子守を引き受けることになるが…。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a22deb29-acba-45df-8670-7d3b363a6d8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46a3bd21-d7f2-4ace-8cf7-89933370a7ac', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 44, '100109609', '幻の少女', '言賜巫女、ウルリーケが目覚めない。巫女たちからの一報を受け村田は、ウルリーケの様子を見るが、彼女からは、気が感じられない。まるで、魂が抜けてしまったように。時を同じくして、城下町では不思議な少女が突然現れ、大人の男を投げ飛ばしたり、大食い選手権で優勝したりと騒ぎになっていた。その噂を聞き、有利は、調査に乗り出す。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45482fed-5cd1-4ce3-8c87-1575174d492d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20eb7808-1e91-4400-9002-387d2b8580c5', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 45, '100109610', '許婚VS婚約者', 'なんと有利にお見合い話が、舞い込んだ。企画者はシュトッフェルとレイヴン。シュトッフェルたちが連れてきた相手は、レイヴンの姪のエリザベート。しかし彼女は、なぜか浮かない顔。そこに有利のお見合いのことを聞きつけ怒りに燃えるヴォルフラムが、乱入した。一同騒然となる中、突然エリザベートが立ち上がり衝撃の一言を告げる。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/adf1b2d4-94a3-4b08-a671-90f9eadb0975.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b681b31b-99b3-4cb8-8c90-9911130e6532', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 46, '100109611', '森の巫女', '禁忌の箱最後の一つである「鏡の水底」探しを進めるが、今日も本物の箱が見つからず、途方にくれる一同のもとにゲーゲンヒューバーからの有力情報が寄せられる。有利たちは早速現地に向かう。そこは、太古の昔より誰も住む者の無い森だという。箱が沈んでいるという湖にたどり着くが、突然目の前に骨だけの巨大な魚が出現する。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a208ac5e-1f8a-4004-85b3-160a87934fc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c517bf44-6481-4139-bd53-d918d379ae27', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 47, '100109612', 'いのちの証', '若き日のグウェンダル。彼は、ダンヒーリー･ウェラーを嫌っていた。なぜならダンヒーリーは、魔族ではなく人間であり、一人放浪の旅に出ては、母･ツェツィーリエを寂しがらせる男だからだ。ある日ダンヒーリーが、旅の共に実の息子であるコンラートではなく、グウェンダルを指名した。釈然としないグウェンダルだが、ツェリの頼みもあり渋々旅に出ることにした。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e0d0698-76ec-40eb-98b8-07a877b1b4ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('984f06ef-ecbe-4d94-8ed4-8221b9afd318', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 48, '100109613', '逆襲、大シマロン!', '鳴りを潜めていた大シマロンが、ついに動き出した。眞魔国派同盟の国々に、各国の交流のため互いの国の王族や貴族の子を交換留学させようという親書を送ってきたのだ。が、それは、表向きの理由で体の良い人質作戦であることは明白。それを聞き、ガツンと一言言ってやるといつもの調子の有利。そんな有利を制して、グウェンダルは、単身敵地へと向かっていった。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9e8f27a-3bfb-4a0e-a18e-76432e2b1a3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7d01a9f-d234-40ef-ad63-c31c70f40a62', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 49, '100109614', '獅子と狼', '有利とアーダルベルトは大シマロン軍から逃れるため、かつてモルギフが安置されていた洞窟に身を隠す。そこでアーダルベルトは、ジュリアに関するわだかまりを語り始める。なぜ自分ではなくコンラッドに首飾りを託したのか。なぜ一言の相談も無く戦場へと赴いたのか。そして、本当に有利はジュリアの魂を受け継いだのか。語り合う二人に大シマロンの追っ手が迫る。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1626b78-2d36-4c7a-a30e-6ba6faa0f989.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b05b296e-9443-4523-8e59-53f2a0cfe9a0', '775cf4c9-b2fa-4ebb-b311-b25c84729e29', 50, '100109615', '我が愛しきジュリア', '火山活動が再開し地獄絵図と化したヴァン･ダー･ヴィーア島。突然の出来事にベラール率いる大シマロン軍は、蜘蛛の子を散らしたように撤退するが、ベラールにより人質とされた王族の子供たちは、岩石の降り注ぐ中置き去りにされる。有利一行は、子供たちの救出に向かうが、火の粉が舞い、木々が燃え落ちる中での救出活動は困難を極める。', '2022/05/12 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e094fb00-0657-43cf-8d90-a6c07eaa926f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('56cfd2b2-7725-4ac0-85a0-0a2522486e1c', '婚約破棄された令嬢を拾った俺が、イケナイことを教え込む', '', 'hulu', 'im-giving-the-disgraced-noble-lady-i-rescued-a-crash-course-in-naughtiness', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/616d7846-611f-4983-bc13-c628003104c0.png?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 154214, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8a2cc301-3658-4b8d-9472-5eea626338c1', '56cfd2b2-7725-4ac0-85a0-0a2522486e1c', 'hulu-im-giving-the-disgraced-noble-lady-i-rescued-a-crash-course-in-naughtiness-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/477b6c53-6bc3-431f-8d9d-abb29c49612a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8acc185e-5146-41a7-934a-63ee7a1b49e3', '8a2cc301-3658-4b8d-9472-5eea626338c1', 1, '100160409', 'イケナイ出逢い', '「魔王」と恐れられ、森の奥でひっそりと暮らす人嫌いの天才魔法使い･アレンはある日、森で行き倒れていたシャーロットを拾う。彼女はニールズ王国の令嬢だったのだが、無実の罪で婚約破棄された挙げ句、指名手配までされていた。不憫なシャーロットに同情したアレンは彼女を匿うだけでなく、自分の屋敷に住まわせ、さらにはイケナイことを教え込み始めて…!?', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/477b6c53-6bc3-431f-8d9d-abb29c49612a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b709f4e-3169-486a-83ad-7a8928252457', '8a2cc301-3658-4b8d-9472-5eea626338c1', 2, '100161057', 'イケナイストレス解消法', 'アレンはシャーロットに教え込むイケナイことをあれこれ考えるのだが、どうにも彼女の自己肯定感の低さが気になる。その原因がシャーロットの不遇な家庭環境にあると睨んだアレンはどうにかしてあげようと考えて、サテュロス運送社の配達員･ミアハにサンドバッグを注文する。アレンはシャーロットにストレス解消と称してサンドバッグを殴る“イケナイこと”を教え込もうとするのだが…。', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/612c9c0d-a9a7-46ca-8fea-781ffd5c99c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('560f5df8-8a62-4b00-9d09-90f7216495df', '8a2cc301-3658-4b8d-9472-5eea626338c1', 3, '100161540', 'イケナイ対決', 'アレンの屋敷に義妹のエルーカがやって来る。シャーロットの存在に気づいたエルーカは、彼女の境遇を知り、激しく同情する。さらに、アレンがシャーロットに“イケナイこと”を教え込んでいると聞くと、なぜかアレンへの対抗心をむき出しに!? 一同は街に繰り出すのだが、アレンとエルーカはどちらがシャーロットに“イケナイこと”を教え込めるかの兄妹対決を始めてしまい…。', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/706022cd-6b7d-40d4-877a-332988172838.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f62dbd36-6676-4635-9ea4-4b8c1913fc0b', '8a2cc301-3658-4b8d-9472-5eea626338c1', 4, '100162333', 'イケナイお出かけ', '朝から何やら落胆しているアレン。その理由をエルーカとミアハが尋ねると、シャーロットが一人で街に行ってみたいと言い出したからだという。不安で仕方ないアレンはエルーカたちとシャーロットを尾行することに。その不安の通り、シャーロットは街でも治安の悪い方向にどんどん進んで行ってしまい、ヒヤヒヤのアレンたち。そしてついに、見るに見かねたアレンは…。', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c6797c4-c1ef-44bc-83b1-93c1e41203c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40a3ad06-c3de-4a82-abbb-a37e96e648bc', '8a2cc301-3658-4b8d-9472-5eea626338c1', 5, '100164110', 'イケナイ温泉旅行', '配達員ミアハに温泉宿泊旅行をプレゼントされ、ユノハ･リゾートへ遥々やって来たアレンとシャーロットの2人。なぜか宿泊プランがカップル限定のものになっていて、2人はカップルとして宿泊するハメに!? 温泉、水着、同じ部屋でのお泊りなどドキドキなイベント満載で、アレンとシャーロットの距離が急激に縮まっていく。その裏で暗躍するミアハとエルーカもいて…!?', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffc1f4b0-169d-422d-9927-fa2a5f5ea9e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef2934e2-f167-46d4-abb4-2b035146f78a', '8a2cc301-3658-4b8d-9472-5eea626338c1', 6, '100164161', 'イケナイ動物園', 'シャーロットのリクエストで動物園にやって来たアレンとシャーロット。和気あいあいと楽しむ2人だが、そこに暴走したフェンリルが襲いかかってくる。アレンとシャーロットは共同戦線を張り、フェンリルの暴走を止めにかかる。すると、シャーロットの隠された力が覚醒して…。地獄カピバラも入り乱れての大乱闘の果てに2人は無事動物園を守りきれるのか!?', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1e99256-9914-4af4-8a7b-54303b8c13b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da97f224-4c1d-43be-b341-b4d97c9de3cb', '8a2cc301-3658-4b8d-9472-5eea626338c1', 7, '100165006', 'イケナイ住人', 'シャーロットを慕って、フェンリルのルゥと地獄カピバラのゴウセツがアレンの屋敷にやってきた。新たな仲間に困惑気味のアレンだったが、『魔物使い』になるべく前向きに勉強を始めたシャーロットには目を細めるばかり。そんな中、突如庭の地下から怒鳴り声とともに現れた小柄な少女に驚く一同。話を聞くと、実はその少女はアレンの屋敷と深い関係があることがわかり…。', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36bfed03-88d6-4d58-adce-1ad94ecb55bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3572597-8883-4eea-a44e-ce72bd2bc2d7', '8a2cc301-3658-4b8d-9472-5eea626338c1', 8, '100165588', 'イケナイ寸劇', 'アレンの屋敷の先住者でボクっ娘エルフの小説家･ドロテアに、屋敷を譲る代わりに寸劇をするよう交換条件を持ちかけられるアレンとシャーロット。ゴウセツとルゥも混ざって寸劇をこなしていくのだが、ドロテアの指示は恋人役、夫婦役など次第に過激になっていく。強制恋人ごっこのせいで、アレンとシャーロットはお互いを意識せざるを得なくなってしまい…!?', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73be9300-6352-4103-af61-e4f121424a89.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6d62849-c17b-41e5-a208-1100d10a50c7', '8a2cc301-3658-4b8d-9472-5eea626338c1', 9, '100166847', 'イケナイ実家訪問', 'シャーロットの義妹･ナタリアの一大事と聞き、アレンの古巣･アテナ魔法学院へとやって来るアレンたち一同。そこで待ち受けていたのは、アレンの叔父･ハーヴェイと叔母･リーゼロッテ。熱烈な歓迎を受ける中、アレンが家出した秘密が明かされる。そして、ナタリアの現状も明らかになるのだが、なぜかアレンとシャーロットが恋人のふりをすることになってしまい…!?', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17e32265-30cc-430c-9c5d-6e60cdbcd04a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0007db7f-765b-4937-b4bf-5a235985bdca', '8a2cc301-3658-4b8d-9472-5eea626338c1', 10, '100166904', 'イケナイ再会', '魔法学院への潜入によってナタリアと接近するアレンとシャーロット。そんなナタリアはわずか8歳ながらに多数の手下を率いる一大武闘派閥の長となり、日々抗争に明け暮れていた。妹を心配するシャーロットは変装によって正体を隠したまま彼女と接するが、緊張したり感激したりと忙しい。そんな姉妹の再会を温かく見守るアレンだが、一方ではナタリアの抱える問題を冷静に分析していて…。', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3546685-2959-49f7-b39b-48ed19ac4058.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa62d477-6fba-4ab8-8050-f2cac7da8ff7', '8a2cc301-3658-4b8d-9472-5eea626338c1', 11, '100167526', 'イケナイダンジョン', 'シャーロットは正体を隠したままナタリアに勉強を教えてもらったりと楽しいひと時を過ごす。だが、ナタリアに対抗心を燃やすクリスによって、彼女の大切なカバンが奪われてしまう。ナタリアはクリスからカバンを取り返そうと立ち入り禁止のダンジョンへ足を踏み入れる。さらに、シャーロットも姿を消してしまう。アレンはナタリアたちの身を案じて捜索に出るのだが…。', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af223ff7-21b3-4617-929d-b3b38a708488.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf2da11f-2739-4302-9001-f0a919048916', '8a2cc301-3658-4b8d-9472-5eea626338c1', 12, '100168282', 'イケナイ＝幸せ', '【最終話】立入禁止のダンジョンに足を踏み入れたナタリアとクリス。2人の前に現れたのは、凶暴な巨大モンスター。そんな絶体絶命のピンチに駆けつけたのはシャーロットだった。だが、彼女の力では太刀打ちできるわけがなく…。そこに颯爽と現れるアレン。そして、遂にナタリアに正体を明かすシャーロット。2人の再会の行方は…。そして、アレンとシャーロットの恋の行方は…!?', '2025/01/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12a8c825-e614-4b7c-96c4-9a6830aa21fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c2965f42-75fa-45b1-9023-2b4d425e0242', '佐々木とピーちゃん', '', 'hulu', 'sasaki-and-peeps', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38b1c9ac-8895-4d7d-b349-35dc53480dbf.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 152682, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('809b409d-7a3c-4c0f-aa33-f67aecdeb176', 'c2965f42-75fa-45b1-9023-2b4d425e0242', 'hulu-sasaki-and-peeps-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52a7d9bb-5353-4ddc-b682-68645e20fcbb.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b5adce0-25db-4ecc-bf48-7f09b8861bcb', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 1, '100171183', '現代と異世界', 'ブラック企業に勤める会社員「佐々木」がペットショップで購入した文鳥「ピーちゃん」は、異世界から転生した賢者様だった。ピーちゃんから魔法の力と異世界に渡る機会を与えられた佐々木は、異世界に現代日本の品々を持ち込んで商売を始める。会社から帰ったあとは異世界で夢のスローライフを満喫!……できるかと思いきや、会社からの帰り道で異能力者に出くわし……!?', '2024/01/10 22:00:00', 2901, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52a7d9bb-5353-4ddc-b682-68645e20fcbb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c91a7ea6-d9d8-4ace-a8ad-66d64cdeb1e7', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 2, '100171900', '初仕事とパートナー', 'ピーちゃんから学んだ魔法を異能力と勘違いされ「内閣府超常現象対策局」に採用された佐々木。異世界でのスローライフも束の間、現代日本では国家公務員として奔走する羽目に。初任務は異能力者の一斉摘発。対象者は低ランクの異能力者とのことだったが、現れたのは界隈でも有名なランクA異能力者の少女だった。', '2024/01/17 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/186871bb-8d05-4efd-bf60-91de4cee6e6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9df9eb32-ed2c-4cef-9b60-cfe3c6dd14f5', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 3, '100172717', '戦とお嬢様', '現代日本で異能バトルを終えた佐々木は異世界にバカンスを求める。しかし、滞在先の「ヘルツ王国」は隣国の「オーゲン帝国」と開戦。ミュラー子爵からも協力を求められる。王国のために一肌脱ぐことを決めた彼は、経済大国の「ルンゲ共和国」に向かい独自に兵站を担う。当初は危ぶまれた仕入れも期間内に整い、ミュラー子爵を戦地に見送った……のだが。', '2024/01/24 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dac6b797-8e47-4884-a098-b879624af472.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f65876b5-c0de-472e-bcce-1d5b86ba9997', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 4, '100173558', '王子と賢者', 'フレンチのお店でエルザと一緒に食事をしていた佐々木とピーちゃん。そこに届いたのは、エルザの兄たちの訃報だった。ミュラー子爵に続き、その息子たちまで亡くなったことで、ミュラー家の家督はエルザに託された。さらには子爵領に向けてオーゲン帝国の大軍勢が迫る。転生後は隠居を決め込んでいたピーちゃんの魔法が、再び異世界で炸裂する――!', '2024/01/31 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45d37a0d-da9a-4570-abbd-f186f471da61.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89efc212-a4ed-4876-ac82-f03395e672e2', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 5, '100174614', '魔法中年と三つ目の世界', '未登録の異能力者をスカウトするために、佐々木と星崎さんは埼玉県内の高校へ車を走らせる。相手は不良に絡まれていた気弱そうな男子高校生。星崎さんは大胆な行動で対象に接触する。すると、そこへ予期せず魔法少女が姿を現して……。', '2024/02/07 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c089c7b-49d7-4e10-819a-eb59df311bfc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1110ab24-5921-402d-8c22-f1d6fafb1afd', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 6, '100175142', '面談と接待', '突然の魔法少女との戦い。佐々木たちを助けに現れた二人静は局へ移籍したいと申し出る。昨日の敵は今日の友。阿久津は優秀な異能力者である彼女を局へ招き入れることに決めた。そして、二人静のOJTは佐々木が担当することに。', '2024/02/14 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f31f1e6-d427-42c7-b0e0-b9bc83a4915f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9cbbd8c3-b61e-4e69-b90a-b00174b62b49', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 7, '100175544', '武力と政治力', 'ミュラー子爵や佐々木の下に、マルクが不敬罪で捕らわれたとの一報が届く。彼らはマルクを救出するために東奔西走。その為に必要な資金を集めるべく、佐々木とピーちゃんは異世界から日本に向けてゴールドの運び込みを進めていたが……。', '2024/02/21 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/690f0e2c-b15b-4597-ab1a-250cde2f18a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1493f22c-f662-4dec-ad15-71a51e5f5852', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 8, '100176340', '疑念と観光', '異世界から日本にゴールドを運び込んだ佐々木とピーちゃん。その荷にまぎれてエルザ様まで来日してしまう。彼女はどうやら、佐々木たちがマルクの身柄を他所の貴族に売り払ったと勘違いをしたようだ。すると現場に居合わせた二人静にも動きが見られて……。', '2024/02/28 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f097f005-9390-4794-a685-be938d735748.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0e324c0-f8d1-466b-adb0-41ca2169e0a3', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 9, '100176915', '処刑と交渉', 'マルクの処刑が決まったことをハーマン店長から聞かされたミュラー伯爵と佐々木は、ディートリッヒ伯爵の下を訪れる。交渉の末、処刑までひと月程度の猶予を得る。大切なビジネスパートナーを助けるため、佐々木とピーちゃんはヘルツ王国を離れてルンゲ共和国に向かった。', '2024/03/06 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b8461323-fdae-4f17-b47b-765e5fb5ea06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ac9eb93-e794-49c0-8dc9-159aab266a11', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 10, '100177705', '価値と尊厳', 'マルクの身柄を巡ってディートリッヒ伯爵やハーマン店長と交渉を行う佐々木。ミュラー家とは犬猿の仲であり、伯爵からは無理難題が飛び出す。しかし、事前に策を巡らせていた佐々木には通じない。やがて、彼がヘルツ王国の未来について力説すると……。', '2024/03/13 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/54d03bf2-4b30-4974-81fa-3b00956ec2e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a31b24f7-d3ad-4375-a83d-6a31990d657e', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 11, '100178455', '妄想と攻略', '二人静が泊まるホテルに呼び出された佐々木。部屋に入ると随所に血液が飛び散り、室内は荒れ果てていた。二人静を狙っていたのは、彼女がもともと所属していた組織の一員でオタク風の格好をした男だった。間一髪のところで二人静を救出した佐々木たちは真っ向勝負に出る。', '2024/03/20 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58c901cf-5931-4bd7-9f4a-e82aa87fa527.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e418e275-a0fd-480d-bf7e-e382f46c6d90', '809b409d-7a3c-4c0f-aa33-f67aecdeb176', 12, '100179001', '現代と異世界と四つ目の世界', '【シーズン1 最終話】敵対組織との交戦を終え一段落……とはいかず、星崎さんから魔法少女が局に現れたとの一報を受けた佐々木。現場へ向かうとマジカルピンクとマジカルイエローの姿があり、物々しい雰囲気に包まれていた。魔法少女が張ったバリアを突破するため、佐々木はある策を講じることに。', '2024/03/27 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01267eed-b1e6-4952-816b-5d3a2bde2ada.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d7216c41-1653-49ea-9281-cd54679ede2d', '佐々木と宮野', '', 'hulu', 'sasaki-and-miyano', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb51fb93-1dae-4f96-9d9f-00804f7e4c05.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 126288, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('590e1c0d-0630-4e5b-af2b-a931987edf28', 'd7216c41-1653-49ea-9281-cd54679ede2d', 'hulu-sasaki-and-miyano-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b2254d5-8988-4817-90c6-c824f1dc1f0f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9d5d7dd-33bb-49ec-a71c-a9a6b5a89e83', '590e1c0d-0630-4e5b-af2b-a931987edf28', 1, '100101306', '初めて。', 'ある夏の日。校内で起きた喧嘩を止めようとした宮野。代わりに立ち向かってくれたのは、ちょっと不良の先輩･佐々木だった。それ以来、宮野はなぜか佐々木に気に入られてしまい……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b2254d5-8988-4817-90c6-c824f1dc1f0f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc8a47e1-893e-4235-9b85-124e6c526f94', '590e1c0d-0630-4e5b-af2b-a931987edf28', 2, '100101939', '好きな子。', '「みゃーちゃんはかわいいねー。俺と付き合わない?」と冗談めいた言葉を交わして以来、佐々木はたびたび宮野のクラスに遊びに来る。しかも、宮野が好きなBL漫画も読むようになって……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40bb8fd0-96ba-413c-ad18-5e7d7b2ccabd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19a3c8ac-8405-4c6d-aac0-570b1c63a293', '590e1c0d-0630-4e5b-af2b-a931987edf28', 3, '100102568', '先輩は。', '自分自身にBL展開を望んでいるわけではないと、佐々木の冗談に大慌ての宮野。ある日、佐々木が同級生から「お前、BLなんて読んでんの?」と言われているのを聞いてしまい……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f21f842-2773-40bb-a897-d5db59e47e6f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5a9c797-2497-49f9-b3e3-f5cf453c320b', '590e1c0d-0630-4e5b-af2b-a931987edf28', 4, '100102935', '限界。', '電車の中で佐々木に囁かれた言葉が気になって、新学期を迎えても、宮野はどんな顔をして佐々木と会えばいいのかわからない。混乱した宮野は、思わずBL漫画を手に取って……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/113c1336-4981-49c7-8bad-1928db4a5a05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eac72d04-0a6f-417d-8e17-46aaa6bbfee9', '590e1c0d-0630-4e5b-af2b-a931987edf28', 5, '100103892', 'いっこずつ。', '体育祭の休憩中に遭遇した佐々木と宮野。春休み前の一件以来、佐々木にどう接していいかもやもやしていた宮野は、普通に話ができていることに安心する。そんな宮野に、佐々木が……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b25a07d5-69ba-47da-a922-683367b0c83e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f664aaa-5711-4f75-b27a-c080beea30bf', '590e1c0d-0630-4e5b-af2b-a931987edf28', 6, '100104454', '気持ち。', '「好きって……なんだろう」体育祭で佐々木に告白されて、返事を必ず考えると伝えたときから、宮野はずっと考えている。そんなとき、佐々木の誕生日が近いことに気づいて……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b26eb0cb-0593-4b88-9b63-f5b375947bab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3791a54-443e-4025-8c19-37eb79f57c34', '590e1c0d-0630-4e5b-af2b-a931987edf28', 7, '100104950', '困らせたくねーのに。', '文化祭で行われる女装大会に、クラス代表として出場することになった宮野。そんな折、佐々木と一緒に帰る途中で、宮野は中学時代の同級生と偶然再会する。実は彼女は……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/390e4e36-31c9-4af2-98dd-2fab55cf84b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04f4d76a-5277-4f42-aa4a-16fd15468d8a', '590e1c0d-0630-4e5b-af2b-a931987edf28', 8, '100105739', '気づいた。', '高校最後の文化祭を楽しもうとする半澤に手伝ってもらい、女装大会用の衣装の準備を進める宮野。放課後の教室で衣装を試着しながら、宮野は思わず半澤にあることをたずねて……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96990aab-dba2-466e-a0f1-377d8bf311ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fff03933-eaaf-4bf2-ac9c-6b724cf5320e', '590e1c0d-0630-4e5b-af2b-a931987edf28', 9, '100106411', '先輩のこと大事にしたいって思って。', '佐々木に抱きしめられたとき、佐々木を抱きしめたいと思った自分に驚く宮野。思い出してはドキドキし、女装大会に出て欲しくないと言った佐々木にどう答えるか悩む宮野は……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59378c22-26e0-4a86-ad0f-9b75c5c87519.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7290694-2e10-4fb0-9b31-2e39c6ab8ea3', '590e1c0d-0630-4e5b-af2b-a931987edf28', 10, '100107222', '恋。', 'ついに迎えた文化祭当日。佐々木と宮野は、お互いの休憩時間に一緒に出店を回って、文化祭を満喫する。そして、女装大会本番。衣装を着てステージに立つ宮野の笑顔に、佐々木は……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7c84259-c31b-4c84-abca-1fc058a08d85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c9e62fc-f392-4998-87e4-c59091991daf', '590e1c0d-0630-4e5b-af2b-a931987edf28', 11, '100107649', 'この感情をどうしたらいい。', '佐々木と映画を見に行った宮野は、あふれだす気持ちについに確信する。「好き」の気持ちは止められず、はやく佐々木に返事がしたいと焦る宮野。そんな中、クリスマスが近づいて……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9542468-e4e5-404e-b150-0093f93c5b64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('700f4467-fbfc-4f39-af1b-dd6d0d4c6f43', '590e1c0d-0630-4e5b-af2b-a931987edf28', 12, '100108292', '明日。', '【第1シリーズ 最終話】校内で衝動的に宮野にキスをしようとしてしまった佐々木は、我に返って、逃げるように去ってしまう。佐々木の様子に心を決めた宮野は、憧れた、あの背中を追いかけて走る―――。', '2025/12/26 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14fc0c22-17f1-4678-9289-46f5ca45d968.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('24d65822-1902-4bf5-9098-452662c4d24c', '左ききのエレン', '', 'hulu', 'eren-the-southpaw', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/903b6b91-df6d-4aeb-ac44-418409f8df00.png?w=331&h=447&p=t', 'hulu', 2026, 1, 1, 'NOT_YET_RELEASED', NULL, 158036, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ea03ff72-c525-4f15-b02f-2fdc97fe2943', '最果てのパラディン', '', 'hulu', 'the-faraway-paladin', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b93336df-76d1-44dc-ace3-28552ec5b711.jpg?w=331&h=447&p=t', 'hulu', 2021, 3, 1, 'FINISHED', NULL, 132473, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a0361c2d-6acf-4d54-9647-1c029ffee646', 'ea03ff72-c525-4f15-b02f-2fdc97fe2943', 'hulu-the-faraway-paladin-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7a578e1-9f2e-4005-a79f-fc2dca698745.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85835f77-f8be-4c1a-9704-4f4d6097c888', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 1, '100094225', '死者の街の少年', '死者の街と呼ばれる辺境の地で、少年ウィルは三人の不死者 (アンデッド) に育てられていた。愛情を一身に受け健やかに育つウィルだが、自分以外にこの地に住んでいる人間はいない。なぜ自分はここにいるのか、そして三人がひた隠しにする秘密とは何なのか。そんな疑問を抱くようになるが、彼自身にも秘密があり…。', '2021/10/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7a578e1-9f2e-4005-a79f-fc2dca698745.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f19c9e5-942a-4627-9c13-e81208731fe4', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 2, '100094616', '彷徨の賢者', 'マリーの秘密を知ってから5年が経ち、ウィルは13歳になっていた。三人から教わる内容は日々高度になり、ウィルも負けじと食らいついていく。そんなある日、ブラッドの授業で廃墟都市の地下街から脱出するよう命じられる。必死に魔物を倒しながら出口を目指すウィルだが、異様な殺気を感じ足を止めると、そこにいたのは――', '2021/10/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09622e48-4aa7-4a6d-95ed-919ffad0349a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7eb5174f-3d59-42e3-9f57-8f08c7040d91', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 3, '100095208', '約束の日', '15歳になる成人の儀としてブラッドと真剣勝負をすることになったウィル。しかし、一方でその勝負に故意に負けてくれと頼むガス。廃墟都市でのガスの殺意の真意を確かめることができないまま、ウィルはブラッドとの試験へと向かうのだった。', '2021/10/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd72fda5-8699-41aa-979a-80228e6f5ea1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bc910d1-35b0-4ca5-be08-e81819663bd9', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 4, '100095452', '灯火の女神', '突如現れた不死神スタグネイトはブラッドとマリーを連れ去ろうとするが、それを打ち払ったのはガスだった。しかし、安心したのも束の間、彼の胸を黒い靄が切り裂く。何もできずに立ちすくむウィルにスタグネイトは「お前のおかげだ」と不敵に笑い告げるのだった。', '2021/11/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a03827d-9a63-45d0-92c6-2662d33b8fd6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4f9b86b-4365-421d-a100-5dc890bd5088', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 5, '100095857', '意志の兜', '死の間際、ウィルはグレイスフィールに誓いを立て、再び立ち上がりスタグネイトに戦いを挑む。しかしスタグネイトはウィルを欺いて姿を消し、ブラッドとマリーを直接狙う。その意図に気付き急いで神殿に戻ったウィルが見たのは、今まさにスタグネイトが満身創痍の二人に手を伸ばそうとするところで……。', '2021/11/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43bae8f1-d44a-4816-a8d4-d824c17801a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6946c5b-1331-4988-a499-8b1527e23b91', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 6, '100096289', '獣の森の射手', '死者の街をあとにしたウィルは、まだ見ぬ外の世界へと旅に出る。何日も森の中を歩き、初めて出会った人間は、狩人でハーフエルフのメネルだった。彼と別れた後も同年代ぐらいの人間と話せた喜びをかみしめるウィル。しかし、その夜グレイスフィールからの啓示があり――。', '2021/11/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb0b7b9c-7d9e-4000-a9d6-2099b0dbafc9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0793e289-c4d6-4b6f-a180-373d06478771', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 7, '100096961', '惨劇の記憶', 'メネルの案内のもと、魔物に襲撃された村に行くことになったウィル。魔物の残党を討伐をするにつれ、村の惨劇が徐々に明らかになっていく。積み重なる死体に焼け落ちた家屋。そして、か細い声でメネルに声をかけてきたのは炎に焼かれ不死者 (アンデッド) 化した少年だった。', '2021/11/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce71e1f3-7afa-44e0-b1bf-a63b0bdd44f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('acf7b6c5-f4dd-42d6-a310-73eb72b92f35', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 8, '100098029', '英傑の詩', 'メネルの案内のもと、魔物に襲撃された村に行くことになったウィル。魔物の残党を討伐をするにつれ、村の惨劇が徐々に明らかになっていく。積み重なる死体に焼け落ちた家屋。そして、か細い声でメネルに声をかけてきたのは炎に焼かれ不死者 (アンデッド) 化した少年だった。', '2021/12/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a5b9248-5fd5-4327-9406-1b6ac857541d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a84c5e61-fefa-4d43-99fc-9b572b5bc94a', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 9, '100098634', '白帆の都', 'ビィとトニオと共に旅を進めるウィルたちは、いよいよ目的の「白帆の都 (ホワイトセイルズ)」に到着する。初めて見る大きな街やそこで生活をする人々に感動するウィル。これまでの旅の疲れを癒していると、非常事態の鐘が鳴り響く。急いで外を見ると大きな黒い影が彼らの頭上を横切っていき――。', '2021/12/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dcdaea5f-52c1-4d71-bee3-a1c91390d91d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c8d509e-6cd4-4d09-a2a1-1fe5dd4e6690', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 10, '100099492', '武勲の輝き', '「ワイバーン殺し」として領主であるエセルバルドと謁見することになったウィルは、多発する魔獣被害を無くすべく私兵を集めて動きたいと申し出る。あまりにも突飛な申し出に一度は威圧的な姿勢を見せるエセルだが、ウィルを見定め、それを許すことに。共に戦う仲間を探すため、冒険者が集う酒場へと向かう。', '2021/12/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae84e1db-4dff-417c-8277-d8d81bb8e385.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('892cb04e-1ee7-4a81-9ce2-1e21698a9ef3', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 11, '100099771', '絶望の谷', '聖騎士 (パラディン) として任命されたウィルは、集落の復興や魔物退治に務めていた。そんなある日、帰ってこない部隊を捜索するため、「つらぬき」の二つ名をもつレイストフやメネルと共に「獣の森 (ビーストウッズ)」へ。ちらばる遺体に異変を感じ、奥の谷間へと進んでくが…。', '2022/01/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ddcc8d13-ff60-4464-bd5b-b7c019ce1f01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('109b39da-b1c5-4e1b-ac74-7a269da8ee8e', 'a0361c2d-6acf-4d54-9647-1c029ffee646', 12, '100099772', '最果ての聖騎士', '【シーズン1 最終話】魔獣たちの罠にハマり、敗走したウィルたち。大怪我をおったメネルをみたウィルは、仲間を無意識に危険な目に合わせていたことを痛感し、周囲と自分のあまりに大きな実力差を思い知る。一人で魔獣を倒しに行くというウィルの前に立ちふさがるのは、怒りをあらわにしたメネルだった。', '2022/01/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96a77647-9bd4-43e7-bd58-005cb27cbd51.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1bc55f11-5432-4812-8895-24945bdf3999', '最果てのパラディン 鉄錆の山の王', '', 'hulu', 'the-faraway-paladin-the-lord-of-the-rust-mountains', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7354ffc-d25f-4201-976a-03348ae69ca9.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 143085, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2dd84371-b332-45c0-af40-cd7670c960b4', '1bc55f11-5432-4812-8895-24945bdf3999', 'hulu-the-faraway-paladin-the-lord-of-the-rust-mountains-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f0d3474-2b92-4270-a508-49c44c9ab930.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6242cb4-312d-4e32-bdf1-2c29ee7eec19', '2dd84371-b332-45c0-af40-cd7670c960b4', 1, '100162152', '聖騎士と詩人', '死者の街を出て2年、灯火の河港 (トーチ･ポート) の将来に繋がる確かな発展を実感するウィルは、エセルバルドに招待され白帆の都 (ホワイトセイルズ) で新年の式典に参加していた。式典後、ビィの要望で『賢者の学院 (アカデミー) 』へと一緒に向かうがその道中にある『迷いの森』で謎の老人と出会う。その老人はここで森番をしているというが…', '2023/10/13 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f0d3474-2b92-4270-a508-49c44c9ab930.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d673ccc-40e4-4da0-bc75-ad476dbcc671', '2dd84371-b332-45c0-af40-cd7670c960b4', 2, '100163051', '狂える森', 'ウィルとメネルは、エセルバルドの依頼で獣の森 (ビースト･ウッズ) に起きた異変を調査するため森を訪れていた。木々が枯れ落ち、獣たちが死んでいる惨状を目の当たりにしたメネルは、この森を統治する2つの古樹『樫の木の王』と『ヒイラギの王』に何かあったのではないかと気づく。原因を突き止めるため、森の最奥へと向かう二人だが、そこで待ち受けていたのは――', '2023/10/20 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41fa5e5c-7fd3-43b4-8872-413b19464f5b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa86688f-891c-404a-9185-46ef2e2c9ce8', '2dd84371-b332-45c0-af40-cd7670c960b4', 3, '100164099', '最後の王', 'これまでに各所で起きていた災いは、ドワーフの国があった鉄錆山脈に原因があることが発覚し、それを突き止めるため引き続き調査を進めるウィルとメネル。ある日、2人が日課の鍛錬をしていると、1人のドワーフが草陰に隠れてその様子を見ていた。興味があるのかとウィルが声をかけると、そのドワーフはおどおどした様子で足早に逃げて行ってしまうのだった。', '2023/10/27 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/266c8625-2c83-4def-bd98-5d3d5e534014.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('679bf6d8-55a1-4254-a99d-1bc459bf1d5a', '2dd84371-b332-45c0-af40-cd7670c960b4', 4, '100164842', '勇気の意味', 'ウィルはドワーフの青年ルゥを従士として雇い、メネルと共に稽古をつけることに。ストイックな鍛練にも食らいつくルゥは、少しずつだが成長をみせていた。稽古の後、ウィルから戦士、そして勇気の何たるかを学びたいと言うルゥ。しかしウィル自身も、鉄錆山脈の元凶――邪竜ヴァラキアカへ恐怖を抱き、勇気とは何か、まだ分からずにいた。', '2023/11/03 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a03a937e-ce05-495e-b9db-7987e45cab4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91ec17e6-bd1d-43f9-9456-01c0181fd9af', '2dd84371-b332-45c0-af40-cd7670c960b4', 5, '100165488', '玄室の遣い', '獣の森 (ビースト･ウッズ) で起こった不死者 (アンデット) 騒ぎは不死神スタグネイトの《遣い》 (ヘラルド) が、ウィルをおびき寄せるために仕掛けた罠だった。警戒するウィルに対してスタグネイトは、邪竜ヴァラキアカとの戦いを避け、力を蓄えるよう忠告しに来ただけだという。その時、ヴァラキアカの咆哮が森に響き渡り――。', '2023/11/10 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea10ef80-08f5-4de3-a844-d086184d7de0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8509187-5513-4df3-8719-d2a1120f31fc', '2dd84371-b332-45c0-af40-cd7670c960b4', 6, '100166123', 'ひとときの帰郷', '竜を討ちに行く決意を胸に、灯火の河港 (トーチ･ポート) を出発し、鉄錆山脈へと向かうウィルたち。ウィルはデーモンたちの裏をかくために川の支流を上って山脈の裏側から侵入することに。その道中、故郷である死者の街に立ち寄ることとなったウィルは、二年越しのガスとの再会に胸を弾ませるが……?', '2023/11/17 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fefa0053-45c0-46ec-9e5a-c34dfc798441.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6d4d87e-31cc-43af-ab5e-4c807d333067', '2dd84371-b332-45c0-af40-cd7670c960b4', 7, '100166748', '水底の眠り', 'ブラッドが遺した英雄たちの装備を得て、束の間の休息をとった一行。竜を討ちに向かおうとするウィルにガスは逃げてもよいと語り掛けるが、ウィルは首を縦に振らず、既に覚悟を決めていることを伝える。その決心を聞いたガスは、ヴァラキアカとの戦いについて助言をし、彼らを送り出すのだった。', '2023/11/24 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64cc978c-aa5c-4f4b-8a25-e388edba3b91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aef0f68f-ce80-4f63-9c70-1da1d6356763', '2dd84371-b332-45c0-af40-cd7670c960b4', 8, '100167314', '花の国', '鉄錆山脈への道中、ヒュドラに襲われていたエルフのディーネを助け出したウィルたち。なぜあんな辺鄙な場所にいたのかと彼女に尋ねると、竜の瘴気によって集落が困窮し、自発的に出てきたからだという。事情を聞いたウィルは病人たちを治療するため、ディーネの集落である「花の国 (ロスドール)」へと向かう。', '2023/12/01 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af2698fd-cda7-42c6-a447-09b8bca98e8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a04306fe-a542-45a2-936a-e03401de8fc3', '2dd84371-b332-45c0-af40-cd7670c960b4', 9, '100168292', '戦士の炎', '《くろがねの国》の奥より放たれたヴァラキアカの気迫に押されつつも、自らを奮い立たせ前進する一行。その前に現れたのは、不死者 (アンデッド) 化したドワーフの一隊だった。200年もの間、竜との戦いに囚われている彼らを見たルゥは自らがヴァラキアカを倒し、奪われたかつての王国を取り戻すと高らかに宣言するのだった。', '2023/12/08 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78025da2-1294-4409-ab85-a5e5bf071797.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63c8036f-1416-4a5a-b057-dea16bdd7814', '2dd84371-b332-45c0-af40-cd7670c960b4', 10, '100168953', '鉄錆の山の王', 'ようやくヴァラキアカの元にたどり着いた一行は、圧倒的な力を前に死闘の覚悟を決める。しかしヴァラキアカから、戦わずに自分をしもべにしないかと持ち掛けられる。思いもよらぬ提案にウィルは混乱するが、ヴァラキアカは更に追い打ちをかけるかのように頭を垂れ、笑うのだった――。', '2023/12/15 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3788e442-e912-4e6a-a18d-249a9458eed7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4c6e21f-924b-4915-9578-c97af9777cc1', '2dd84371-b332-45c0-af40-cd7670c960b4', 11, '100169762', '邪竜と女神', '究極の破壊魔法である《存在抹消のことば》も躱され、仲間も倒され、絶望の淵に立つウィルに、今度は自分のしもべになれとヴァラキアカは告げる。その誘いを断固として拒否したウィルは一人でヴァラキアカと戦い続ける。しかし、力の差は一向に埋まらず、遂に最愛の武具である〈おぼろ月〉 (ペイルムーン) までが折れてしまう…', '2023/12/22 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9543a8ad-3181-48d9-b432-a7a45fde4ca5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07f25c45-e7e0-43ce-8940-b3aa44bf6d4a', '2dd84371-b332-45c0-af40-cd7670c960b4', 12, '100170446', '夜明け呼ぶもの', '【シーズン2 最終話】ヴァラキアカとの激しい戦いの末、追い込まれたウィル。愛槍は折れ、魔剣も封じられ、グレイスフィールの結界も砕かれた彼の前に現れたのは、不死神スタグネイトだった。スタグネイトは、かつてくろがねの国で戦ったドワーフの戦士たちを蘇らせ、グレイスフィールは魂の輪廻へと返れぬ戦士たちを“勇気”としてウィルたちの胸に灯した。再び立ち上がったウィルたちは決意を新たに、最強の敵――ヴァラキアカに挑む!', '2023/12/29 18:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0e25a0d-28a9-4bd7-bab9-df730769fd73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('fc09ce89-9a7d-4521-941f-874d2a3cd368', '最凶の支援職【話術士】である俺は世界最強クランを従える', '', 'hulu', 'the-most-notorious-talker-run-the-worlds-greatest-clan', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/014a75b2-631a-45e8-8d05-2a56b5008da8.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 177104, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d2b4a9cc-1455-4f52-bb7c-c43062ca71be', 'fc09ce89-9a7d-4521-941f-874d2a3cd368', 'hulu-the-most-notorious-talker-run-the-worlds-greatest-clan-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebad3db7-bfb5-4c7e-b403-23dcfb3eb171.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9a57a4d-6f4a-4984-81fc-9a26552b1f63', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 1, '100202607', '最弱が最強を目指す理由', '最強の探索者 (シーカー) を目指す少年･ノエル。彼が授かった職能 (ジョブ) は、最弱の支援職と呼ばれる【話術士】だった。所属パーティ･蒼の天外 (ブルービヨンド) の仲間と共に戦うも、指示を出すばかりで直接的な戦闘には加わらない。それでも最強の座を手にするために、ノエルはより権限を得られる組織 (クラン) の創設を仲間に提案する――。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebad3db7-bfb5-4c7e-b403-23dcfb3eb171.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9dd13988-2440-45d3-bf48-615bda19018d', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 2, '100203138', 'その話術士は容赦をしない', 'パーティの仲間であるロイドとタニアが裏切ったと、ノエルの下宿に駆け込んできたヴァルター。ロイドの書き置きから、多額の借金があり、その返済のためにパーティ資金を横領したと発覚。帝都から逃亡した2人を追おうとするヴァルターの装備を整えさせ、ノエルは酒場へ向かう。確実に2人を捕らえるための狡猾な蛇の策が、牙を剥く。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cabf1086-42c6-48b4-80b0-a63c907b2890.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1611abd4-2bc1-49c4-9134-ba7c396881d2', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 3, '100203867', '本物の天才', '裏切った二人をフィノッキオに売り飛ばし、パーティを新生すると決めたノエル。酒場で応募者を待つノエルの前に現れたのは、小柄な女性･アルマだった。さらに、彼女は伝説の殺し屋･アルコルの孫であると告げる。名を聞いた周囲が騒然とするなか、居合わせた1人の探索者 (シーカー) がアルマには格が無いと挑発してくる。アルマは探索者の格は何で決まるかとノエルに問い――。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fa03cdf-7887-4f60-9bdf-d59aed622126.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94daab0b-b4c6-42e8-bd1b-e74b6ad1e7d8', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 4, '100204407', '謝れば許してもらえると思うなよ', '盗賊団討伐の依頼を受けて、ミンツ村にやってきたノエルとアルマ。村長から情報と前金を受け取った2人は、村長の娘･チェルシーからの応援も受けつつ、さっそく盗賊団のアジトに向かうことに。現地に到着すると、そこには事前情報の倍以上の人数。加えて、盗賊団のボスは200万フィルの賞金がかけられている剃刀ゴルドーであることが発覚し――。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b54858e-3ebe-4b91-935f-a784ed14105b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b48cf79-7053-420d-b7f1-6be2288aabc1', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 5, '100205089', '極東の剣士', 'ノエルはアルマに帝都を案内してまわることに。鑑定士ギルド、馴染みの武具屋、スキルブックの販売店と次々に目的地を訪れる2人。その道中で、ノエルはアルマと別れスラム街へ。そこで帝都随一の情報屋･ロキより、とある人物に関する調査報告書を受け取る。情報を受け取ったノエルがスラム街を出ようとしたところ、ボサボサの黒髪に虚ろな目をした男･コウガと出会う。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33bcf6f2-d013-4b6e-a953-486ba090dffd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8900059f-78ba-4b56-94f7-fdcae445cea2', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 6, '100206195', '誇りの価値', '猫満腹亭でアルマと合流したノエルは「有望な新人は勧誘できたの」と問われ、脳裏にコウガの姿を思い浮かべるも振り払う。一方、当のコウガは、主人のミゲルがダランベールファミリーの金を横領したことで、ガンビーノファミリーのアルバートに拘束されていた。『真性の外道』と呼ばれるアルバートは、このまま引き渡しても面白くないと、二人に対し自身の考えを告げる。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f13d0fe-e74a-4cb6-8c69-8c5631e27970.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('315dc305-021e-416f-9fd6-380831e07bbc', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 7, '100207083', '仁義なき世界', 'ガンビーノファミリーに因縁をつけられ、刺客となったコウガと戦うノエル。職能 (ジョブ) の差は圧倒的で、コウガの刃が突きつけられる。しかし、とどめを刺すことを躊躇するコウガに、ノエルは情けをかけるなと一喝。さらに、二人の間にアルマが救援として割って入る。アルマとコウガ、才能を持つ者同士の戦闘を目の当たりにしたノエルは、【話術士】として最強へ至る考えに確信を得る。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daf641c5-3600-446a-b8b0-a5348552ef14.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f4f30222-029c-481d-920b-d9ca2a4fc94a', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 8, '100207899', '王者の器', 'ガンビーノファミリーとのしがらみを絶つべく、アルバートの秘密を暴き、決闘に持ち込んだノエル。フィノッキオが立会人となり、アルバートは代理決闘者にコウガを指名する。ノエルは代理を立てず自身が闘うと宣言。職能 (ジョブ) の差を覆す策に警戒するコウガと一進一退の攻防を繰り広げる。その戦いのさなか、ノエルは唐突に魔銃を投げ捨て――。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a669a435-8fd9-4871-ad8e-79483a481870.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7aa27b1-67d5-4704-80c8-e438b0248180', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 9, '100209380', '毒牙を磨ぐ蛇', 'コウガが仲間となり、クラン創設のためシーカーギルドを訪れたノエルたち。面接を受けた一同に対し監察官･ハロルドが告げたのは「却下」の一言。1年後に特大の深淵 (アビス) から、深度十三の大ロードであるヴァリアントが現界するため、対抗できる即戦力を求めていることからくる理由だった。その場は引き下がったノエルだが、一気に飛躍するチャンスだとその瞳に野心をたぎらせる。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/437e6ad1-1d22-40f0-b56f-e065c8f327bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3c71a24-70b5-482f-a547-05472ededfd0', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 10, '100210088', '持つ者と持たざる者', 'ノエルは監獄を訪れ、死刑囚である【傀儡師】ヒューゴと面会を行っていた。ヒューゴを仲間に誘うも、なかなか首は縦に振られない。その後、ノエルたちは格上の探索者 (シーカー) 達が集う新たな酒場へ。さっそく気に食わない探索者 (シーカー) に絡まれるが、ノエルは巧みに御する。そこへノエルが目を付けていたトップレベルのBランクパーティー･天翼騎士団が店を訪れ――。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e82cd897-d7af-4245-b745-af829c1f2888.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da6e19c8-0702-4eb7-9f80-31679b469200', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 11, '100210963', '正しさの代償', 'ノエルたち蒼の天外 (ブルービヨンド) はクラン創設を賭け天翼騎士団と競うことに。創設を認める条件は、深度八の悪魔 (ビースト) ･ダンタリオンを先に討伐するというものだった。さらに、敗者にはパーティを解散する条件が課される。三日の準備期間を経た試験の日、ダンタリオン討伐に動き出した天翼騎士団に対し、ノエルたちは驚きの行動に出る。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d65ed191-a033-4bbb-9c12-3a435d41fde8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c569980-a8c2-4952-8957-46143a573215', 'd2b4a9cc-1455-4f52-bb7c-c43062ca71be', 12, '100211934', 'その蛇には翼が生えている', '【シーズン1 最終話】崩壊した天翼騎士団を捨て置き、ダンタリオンと交戦を開始したノエルら蒼の天外 (ブルービヨンド)。人の心を読むダンタリオンの能力にノエルは【戦術家】のスキルで対抗し、戦闘を有利に展開させ追い詰めていく。一方の天翼騎士団では、この盤面がノエルの策略により整えられたものだと知ったカイムが激昂していた。ノエルは天翼騎士団に「すでに崩壊する運命にあった」と告げ――。', '2025/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5f5cb98-9c84-40b5-9ec5-ae4e3a0eaa6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0bba30df-9d2b-4b18-8871-e5ba8ccf4433', '最強タンクの迷宮攻略　～体力9999のレアスキル持ちタンク、勇者パーティーを追放される～', '', 'hulu', 'the-strongest-tanks-labyrinth-raids-a-tank-with-a-rare-9999-resistance-skill-got-kicked-from-the-heros-party', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6bc2a94c-e406-4cd3-b7a2-5b51186f3685.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 169935, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', '0bba30df-9d2b-4b18-8871-e5ba8ccf4433', 'hulu-the-strongest-tanks-labyrinth-raids-a-tank-with-a-rare-9999-resistance-skill-got-kicked-from-the-heros-party-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de5c6f9b-b47f-4f07-b06c-e640d0a02387.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c434fdd8-3702-44bc-8485-a0143afd5535', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 1, '100171193', 'パーティー離脱', 'どんな願いも叶えてくれるという『迷宮の秘宝』を手に入れ、妹の病を治すために、ルードは勇者達と共に迷宮攻略を進めていた。だが勇者の横暴により、突然パーティーを追い出されてしまう。仕方なくルードは妹の待つ故郷へ。しかし旅の途中、予期せぬ戦闘に巻き込まれ……。そこで出会ったのは、裸に布を纏っただけの美しい少女だった――。', '2024/01/09 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de5c6f9b-b47f-4f07-b06c-e640d0a02387.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3d0b6a1-d50f-44ce-81e3-c2c34db59b0a', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 2, '100171811', 'アバンシアへの帰還', '久しぶりの故郷に心が休まるルード。しかしルナは緊張が解けない様子。その後、自宅に戻ると最愛の妹マニシアが手料理を用意し、兄の帰りを待っていてくれた。ややツンとした態度のマニシアだが、ルードはデレデレ。そしてルナは、兄妹との交流をきっかけに少しずつ心がほどけてきて――。', '2024/01/16 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50d223ca-dc33-4be1-8173-11784abda4d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfc364b2-4477-4db2-903d-7cbb20ac73de', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 3, '100172264', '未知の魔物', '「自分の存在が、兄の未来を閉ざしているのではないだろうか?」不安を拭えないマニシアは、ルードとうまく接することができない。だがルナの励ましにより、ようやく兄と向き合おうと決意する。それから間もなくして、勇者パーティーの一人、聖女のニンがルード宅のドアを叩く――。', '2024/01/23 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9e3bd54-edc3-46cf-ba2c-be89afe2532e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d573ce3a-91c0-4ce0-8742-ead68494864a', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 4, '100173471', 'わがまま', '襲来したブラックウルフには、2つの魔石が埋め込まれていた。通常では起こらない事態に不安をおぼえるルード達。間を置かず、現れたのは凶暴なカメレオンコングの群れ。ルードは集まった冒険者達と力を合わせ、なんとかこの場を切り抜けるが。町の近くに『迷宮の入り口』が出現し――。', '2024/01/30 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fd1f10e-95d4-4bfb-8a31-cd24ccbe2b6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a5318a1-cfe5-4bda-aaf1-0cfdda0f2932', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 5, '100174110', '夢へ', 'マニシアと町を救うため『アバンシア迷宮』の攻略を決めたルード。そこには人と同じように言葉を話す「意思を持つ守護者」がいるという。新たなメンバーと、リリアとリリィと共にルードは次々と襲いかかってくる魔物を倒し、迷宮の深部を目指す。やがて辿り着いた空間には、着物姿のマリウスが立っていて――。', '2024/02/06 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b4d55fe-8d40-41b5-87fd-aca7c7f33944.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47e97c3f-c62d-4e0b-a578-f30287507bda', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 6, '100175067', '迷宮の管理者', '迷宮で手に入れた魔石により、不治の病の症状が軽減したマニシア。一方、仲間となったマリウスは、ルードに迷宮の管理者になってほしいと申し出てきた。断りたいルードだが、マリウスの強い要望により、しぶしぶ迷宮の管理室へ向かう。その後、2通の招待状がルードの元に届き――。', '2024/02/13 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/536af8ed-2261-46b7-b9ff-8afea1a13682.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7d0bc01-c8d1-4050-bb6e-c0068200c0cf', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 7, '100175551', 'ケイルドにて', '宿泊施設にて、いきなり部屋に引っ張り込まれたルードは、リリィの姿にびっくり。その後、初めてリリアとリリィのつらい過去を知ることに。ルードは『ケイルド迷宮』の攻略を進めると同時に、前に立ち、指揮を執ることを決意したリリィを見守る。だがリリアは、妹の変化に複雑な様子。そして途中の階層にて、マリウスの正体を聞かされ――。', '2024/02/20 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c17cc1d6-3eb7-4666-8542-7114c6189b99.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('003bffc5-1c00-4b71-a8b4-ae7ef4e9f17a', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 8, '100176154', 'リリアとリリィ', 'リリアはリリィの成長を喜ばしく思う反面、自分から離れていってしまうことに不安に感じていた。だがルードの助言により、いつも通りの前向きな気持ちを取り戻す。その後、再び向かった『ケイルド迷宮』にて、進んだ先に現れたのは3つの水晶を操るダークスケルトン。特殊な攻撃を受けてしまったリリアは、過去のトラウマがフラッシュバックし――。', '2024/02/27 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ba95fee-2d3b-47b5-b80c-9ab7f2f89f73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfacdc2e-f1c4-42d3-bc03-c5a9f6d7b354', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 9, '100176737', 'アモン･スロース', '最奥部にて舞い降りてきた少女アモンは魔王だった。扇子による猛烈な風魔法と、驚異的なスピードに翻弄される一行。しかしルードと仲間達は一致団結し、それぞれの力と、築き上げた信頼関係により、じわじわとアモンを追い込んでいく。すると竜巻のような風が巻き起こり、姿を現したのは――。', '2024/03/05 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06271d2c-c43f-4c34-93ea-03d5cf2b08bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9d052eb-ba16-4587-ada0-d2d9e0b647ac', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 10, '100177699', '異国のホムンクルス', '魔石のおかげで元気になったマニシア。ひと安心のルードだが、そこに傷を負った1人の少女が助けを求めてやってきた。森に向かうと、隣国から逃げてきたというホムンクルス達と、戦闘型ホムンクルス達が剣を突き合わせていた。ルードはスキルと魔力を駆使し、戦闘型を撃破。その後、行き場のないホムンクルス達を保護することになるが――。', '2024/03/12 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c48ca61-792e-4ada-b19f-991adef886f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c778dffd-ed76-45cd-96dd-c505a53082bb', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 11, '100178291', '魔物の襲撃', '魔王グリードの存在を知ったルードは、迷宮にて『魔力の特訓』と『魔物相手による身体強化』を行っていた。その後、ホムンクルス達によって建設された公衆浴場が完成し、お風呂を満喫する一同。ホムンクルス達への偏見も解け、良いムードが漂う町。だがそこに、魔物の群衆が迫っているとの凶報が届き――。', '2024/03/19 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fdc2a13-7d11-4e00-a274-93bd46227364.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13356e57-328e-45ba-aa76-9cc8f0f6018a', 'c19a0ab3-7dbf-4e4d-b271-eb74ec6bf4ee', 12, '100178727', '魔の力', '【最終話】最下層と思われる空間にいざなわれたルード達。待ち構えていたのはグリードだった。己の研究のため、違法ホムンクルスを作り、利用し続けていたグリードに、怒りを隠せないメンバー。その後、グリードの姿はみるみるうちに変化し、ルード達にとてつもない魔力が放たれる。外皮を削られながらも、全力で立ち向かうルード達だが――。', '2024/03/26 02:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/360f12a7-384a-44cb-9480-cefc79ddff9a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0f84a5a0-c5b8-47c4-9fd6-0a9aaec2f101', '最強の王様、二度目の人生は 何をする? ', '', 'hulu', 'the-beginning-after-the-end', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31e76d2c-9e85-4612-b0d1-51ea571cb7aa.jpg?w=331&h=447&p=t', 'hulu', 2025, 1, 1, 'FINISHED', NULL, 183161, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('14078f8c-9dc7-4ebb-9a68-9dc652b44002', '0f84a5a0-c5b8-47c4-9fd6-0a9aaec2f101', 'hulu-the-beginning-after-the-end-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/146f8de6-fe59-4183-a9b9-9b6ceb068e1a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ebf66c4-3745-4f78-9e5d-d36ce5235260', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 1, '100222796', '王様、生まれ変わる。', '数々の敵を倒し、富も名声もすべてを手に入れた史上最強の王様･グレイは、ある日突然の死を遂げてしまう。しかし、次に目覚めると、無力な赤子として魔法世界に転生していた。そこではアーサーと名付けられ、愛情あふれる両親のもと“二度目の人生”が始まった――。', '2025/04/06 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/146f8de6-fe59-4183-a9b9-9b6ceb068e1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e301c686-b172-4dfc-93ce-654518ab1cbf', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 2, '100223517', '王様、襲われる。', 'アーサーに本格的に魔術を教えるため空中都市キシラスへ向かうことになったレイウィン一家。父レイノルズと母アリスがかつて所属していたアドベンチャラーのパーティー「ツイン･ホーンズ」を護衛につけて旅立つが、その道中で出くわしたのは……。', '2025/04/13 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84ab807c-123a-4500-92a0-c407277c43e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0e2d74a-5d0c-47b0-9c94-f397741910c0', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 3, '100224215', '王様、出会う。', 'アーサーは盗賊たちとの戦いの中で崖下に落ちてしまった。目覚めた彼の前に現れたのは、鎧をまとった謎の魔物。彼女の名はシルビア。アーサーを助け、離れ離れになった家族の行方も知っているようだった。シルビアの正体とは……。', '2025/04/20 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c9db6d9-a68c-47e1-8da9-81bd7bdf8c1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69f8e604-c67b-4ba6-9a35-773b75d44562', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 4, '100224934', '王様、助ける。', 'シルビアと別れたアーサーは森の中で少女の悲鳴を聞く。声のもとへ駆け付けると、エルフの少女･テシアが奴隷商人たちに捕らえられていた。「新たな人生に光を……」シルビアの言葉を胸に、アーサーはたった一人で戦いを挑む……。', '2025/04/27 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4996ec66-4fa7-4e52-8513-c32be720ea5a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fdb1a45e-723f-4945-84eb-b253ca7bec74', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 5, '100225663', '王様、試される。', 'テシアとともにエレノア王国にたどり着いたアーサーは、人間に深い恨みを抱くエルフの兵士たちに拘束されてしまう。一触即発のところで前国王･ヴィリオンにより解放され、エレノア王国の城へ招かれることに。しかしアーサーはマナコアから生じる痛みが悪化していて……。', '2025/05/04 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82f106a8-16d2-45b7-b920-8a912aca6dc8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee1a4167-1969-43ea-86bf-6c00a67b3fea', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 6, '100225664', '王様、修行する。', 'レイノルズとアリスに無事を知らせる手段があると告げられたアーサーはヴィリオンと共にとある魔女の家を訪れる。そこで特殊な魔法を使って両親の姿を見ることができた。悲しみに暮れる両親の様子を目の当たりにしたアーサーは、大切な人を護れるように、そして、自らに宿る狂暴な力を制御するため、ヴィリオンの元で修行を始める。', '2025/05/11 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73b631c1-8157-4fe0-a43e-129ef81ac323.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71fabec3-ba61-4c14-bd76-37034f320290', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 7, '100226957', '王様、お別れする。', 'アーサーがエレノア王国で修行を始めてから3年の月日が経った。テシアとともに修練に励み強く成長したアーサーは、ヴィリオンの力を借りてマナコアに宿る強大なビーストの意思を目覚めさせることに成功する。そしてある晩、シルビアから託されていた石が光り輝いて……!', '2025/05/18 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3b1e608-4af5-4e73-a63e-0c0af1be5114.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5fcdd84d-4452-4c89-820b-ee62bbafc3e0', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 8, '100227576', '王様、再会する。', 'キシラス･シティに到着したアーサーは、妹･エレナとの新しい出会いと両親との再会を喜ぶ。アーサーはレイノルズとのスパーリングで修行の成果を家族に披露するが、その魔術の才能を目の当たりにしたヴィンセント･ヘルステアはある提案をもちかける。それは最高峰の魔術学校であるキシラス･アカデミーへの入学だった。', '2025/05/25 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14bebf95-ba65-4635-9023-1b533bdbb7ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5f30557-bb28-4df4-ad51-8648c685750e', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 9, '100228173', '王様、教える。', 'アーサーはヘルステア家の一人娘･リリアたちに連れられて、近々開催されるオークションへ向けて身だしなみを整えるために街へ出掛ける。一方、リリアの両親であるヴィンセントとタビサは娘の将来のためにかねてよりキシラス･アカデミーへ入学させようとしていたが、リリアの魔力は未だ目覚めず……。', '2025/06/01 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7c779d4-e406-495e-ae85-211f97160cd6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eaf90e71-335f-4234-9165-e2eeceebc0c1', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 10, '100228799', '王様、逆らう。', 'サピン王国の王族も参加するオークションの開催当日。正装に身を包んだアーサーたちが会場へ訪れると、そこではレイノルズが警備隊長として仕事をしていた。数々の貴重なオークション品に会場が沸く中、アーサーはシルビーがどこかへ行ってしまったことに気付く。そんなシルビーは、王族の護衛を務める歴戦の魔術師に目をつけられていた――!', '2025/06/08 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd86ff43-74a1-4354-bc69-f4e331d052c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7cc089b5-dd19-4e36-954d-8b3db439f22c', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 11, '100229364', '王様、決意する。', 'キシラス･アカデミーを訪れたアーサーは、学院長のシンシアと初対峙することに。名門魔術学校のトップを務めるだけあって彼女の力は凄まじく、様々な魔術に圧倒されるアーサーだったが、自らも持ち得る力を見せるのであった。そしてアーサーは、シンシアにある取引を持ち掛ける……。', '2025/06/15 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca295eb9-e49c-47af-8cab-f20e2b236c11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('beae2c91-3a77-4bc9-81bf-69b76e9a8492', '14078f8c-9dc7-4ebb-9a68-9dc652b44002', 12, '100229862', '王様、旅立つ。', 'ジャスミンとともに旅立ったアーサーは、アドベンチャラーのランク審査を受けるためにギルドへとやって来た。すると、ギルド長のカスピアンの元へ案内されるやいなや、本来は必要な筆記試験を免除するというのだ。どうやら、推薦人であるジャスミンの家柄が関係しているようで…。さらにアーサーの実技試験は、カスピアンが直々に審査すると言い出し──!', '2025/06/22 12:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36eaa5e5-7279-47f1-8caf-16f4547ab48d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('614e1436-6a88-4114-9aed-a744d3f10fce', '最強陰陽師の異世界転生記', '', 'hulu', 'the-reincarnation-of-the-strongest-exorcist-in-another-world', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e71287c-3205-44aa-b50a-84ad69814101.jpg?w=331&h=447&p=t', 'hulu', 2023, 0, 1, 'FINISHED', NULL, 144553, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('24a18fd0-68cd-4743-a2e9-af04991e2b8e', '614e1436-6a88-4114-9aed-a744d3f10fce', 'hulu-the-reincarnation-of-the-strongest-exorcist-in-another-world-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/133d57cf-9d92-4170-accf-99285bb53f93.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a28f096-3355-480f-ae87-0aad1db4a7b1', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 1, '100134434', '最強の陰陽師', '歴代最強の陰陽師･玖峨晴嘉は、その強大すぎる力を朝廷に危険視され謀略によって命を落とした。しかし、死の直前に“転生の呪い”を使い、異世界へと転生することに成功し、剣と魔法の世界にセイカ･ランプローグとして生まれ変わる。そうして“狡猾に生きて幸せになる”ことを目標として2度目の人生を歩み始めた彼は魔術の才能を一切持たない代わりに前世から受け継いだ記憶と式神、そして強力な呪力を持っていた。', '2023/01/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/133d57cf-9d92-4170-accf-99285bb53f93.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('866d2d48-6f2d-4697-8612-8a11a302fe7f', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 2, '100134952', '学園都市ロドネア', 'セイカは陰陽師としての力を使い自身の活躍を“演出”して父を説得。自分を敵対視する兄のグライを決闘で打ち負かし魔法を学ぶための学校である学園都市ロドネアへの入学を認められた。学園にたどり着いた2人は入学の手続きをはじめるが、周囲からは奇異の眼差しが向けられていた。そんな2人の前に平民の生まれでありながら全属性の素質を持つ赤髪の少女「アミュ」が現れる。', '2023/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4025f536-58be-4a32-af17-5f91c68c449c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3404bc6-0b10-4ef7-bd2e-514c1c7cc225', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 3, '100135401', '託宣の勇者', 'いよいよ始まった学園への入学試験において、魔力の代わりに呪力を駆使するセイカと精霊の力を借りたイーファの魔法は凄まじく、実技試験の会場は騒然となっていた。セイカとイーファ、アミュの入学が決定し、アミュによる新入生代表のあいさつが行われることとなったが、そこには異形の影が迫っていた。', '2023/01/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd711cc4-7e96-43a6-97ae-e1b870b7039b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44681267-d505-4e2d-b5c5-ac40aea668b9', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 4, '100136017', 'ダンジョン･トラップ', '魔族が率いるデーモンの軍団を退けたセイカは、特別な力を持ったアミュを利用しようと思い声をかけるが、なかなか距離を縮められずにいた。そんな中、セイカとアミュは開校記念日の式典として学園にある森の中の神殿を訪れることになった。しかし、謎の魔法陣により正体不明のダンジョンへと飛ばされてしまった2人の目の前にはゴブリンやナーガといった強力なモンスターたちが立ちはだかっていた。', '2023/02/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f632419-04c7-4edc-a9c6-dd44625dec6f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eac803c0-4d32-41ce-b3ba-3c314fcfc277', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 5, '100136739', 'メイベル･クレイン', 'デーモン騒動から1年が経ち2年生となったセイカは、ダンジョンでの出来事からアミュとも打ち解け平穏な学園生活を送っていた。そんな中、突然、学園長から呼び出しを受けたセイカは帝都で開催される総合武術大会に出場して欲しいと依頼される。セイカと共に出場することになったのはイーファでも、アミュでもなく、謎の新入生「メイベル･クレイン」だった。', '2023/02/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4dd0af25-6fe7-4378-a49a-3f96f97a2308.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfc2d4d0-23e5-4de2-aa6a-66bef0e74ce1', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 6, '100137356', 'それぞれの思惑', 'アミュと同じ赤髪を持ち、彼女を模擬戦で負かすほどの戦闘能力を持つメイベルと共に総合武術大会を勝ち進むセイカ。だが、視線に呪いを込め容易く命を奪うことのできる邪眼を使う青年･カイルという危険な相手の登場により楽勝だと思っていた大会が一気に雰囲気を変えていた。さらに大会の裏で暗躍する組織の存在も明らかになり、多くの人々が集まる総合武術大会の場で様々な思惑が交差していく。', '2023/02/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8169a28-a8fe-46a7-bbb0-deec7364c43a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c216134d-8b26-42a3-8423-ec27f0fea5b2', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 7, '100137993', '兄妹', '大会決勝の前夜、突如、メイベルに寝込みを襲われたセイカは、彼女の真意を聞くために自らメイベルに再接触することを決める。メイベルの口から語られた、カイルとの因縁と、その残酷な真実を知ったセイカは、決意を新たにカイルとの決勝戦へと出場する。邪眼と陰陽道、重力魔法と式神、ぶつかり合う互いの力と技。これまでにない激しい戦いの先でセイカはひとつの決断を迫られることになる。', '2023/02/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c1851f6-500f-40a8-bfb9-242396f5b856.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3507c210-ca17-4512-b084-d3c40e84692f', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 8, '100138697', 'イーファの想い', 'セイカやアミュたちともすっかり打ち解けたメイベル。そして、季節は夏休みに突入しようとしていた。生徒たちが思い思いに休暇を過ごすなか、セイカは父からの依頼でアスティリア王国に住むというドラゴンの調査へ赴くことになった。そんな矢先、アスティリア王国の王子であるセシリオが学園を訪れセイカを尋ねる。だがセシリオはイーファのことを気に入ってしまい…?', '2023/03/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40fff250-b637-4857-9cb7-5b90da84642f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d28b5660-a205-413e-8fb4-8aae15e17d8e', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 9, '100139799', 'イーファの決意', 'イーファに一目惚れしたというセシリオ王子は、イーファを後宮 (ハレム) に誘うが、セイカを想うイーファは困惑する。だがそれだけではなく、王子の側近であるエルフの女性･リゼは、イーファに「セイカという男は危険だ」と忠告するのだった。それぞれの想いがすれ違う中、セイカは問題のドラゴンを調査するため、単身、ドラゴンが棲む山へと向かう。そこで、セイカはドラゴンの意外な真実を目にすることとなる。', '2023/03/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc8bc4d2-dff1-4809-878e-97d40db68480.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ead24e93-5242-4665-ab27-3de2ce5996ee', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 10, '100140345', '聖皇女', 'アスティリア王国のドラゴン事件を解決したセイカはアミュやメイベルと共に里帰りをする。久しぶりに再会する父や長兄ルフト。そして軍での研鑽によりアミュをも凌ぐほどに大きく実力を伸ばしていた次兄グライは、聖皇女と称されるウルドワイト帝国の姫･フィオナの護衛である聖騎士となっていた。世間知らずなためか、周りの物事に興味津々で接するフィオナにセイカたち一同は振り回されることとなるが…。', '2023/03/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a254816-b8c4-4a58-bc37-0bcc7f1e58d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac417c14-cd86-46d7-b400-30d71bccc247', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 11, '100140724', '未来視', '1人テラスで過ごすフィオナに話しかけたセイカは「未来視」の力を持つという秘密と彼女の真意の一片を聞かされる。あやふやに、だがはっきりとした意思で語られる崩壊と破滅の未来。その未来を裏付けるかのように魔族の精鋭による脅威もすぐそこまで迫っていた。そんな中、セイカたちはフィオナの馬車に同行し学園への帰路を目指すのだった。', '2023/03/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b8bc6746-20cd-4241-a4e6-ec9d8be7f8ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('baef4380-567c-480e-8b83-ce29578b3c55', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 12, '100141518', '最悪の魔王', '新学期を迎えた学園でセイカは入学式での在校生総代を任されることになる。わざわざ目立つ役割を引き受けたことに疑問を呈するユキにセイカは今までのように神経質に欺くように生きるのではなく、普通に、自然に過ごしたいという想いを語る。だがそんなセイカの思いとは裏腹に学園へと迫る脅威。襲撃者である魔族パーティのリーダー･ゾルムネムは勝利を確信していた。だが…。', '2023/03/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aefd1ed9-0dae-4e26-a243-8fc6852879ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab3abcc5-4744-4b1d-bd6f-9e619c645d03', '24a18fd0-68cd-4743-a2e9-af04991e2b8e', 13, '100141863', '新たなる旅立ち', '【シーズン1 最終話】突如、学園内に乱入してきた騎士たちによりアミュが連行されてしまう。身に覚えのない帝国への反逆という罪。学園長に話を聞いたセイカは帝国内に渦巻く政治の派閥争いを知る。勇者の生まれ変わりという立場と力に振り回され、目の前から奪われたアミュ。生前に経験した、自身の結末を知る男はその理不尽を前に1つの決断を下す。ついにセイカは最強と謳われた陰陽師の力を解き放つ。', '2023/04/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b5f0af0-005f-4570-940a-fc11c1eb9ee3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6c723486-d2b4-4038-a6b6-3e319fdcdacf', '最強王図鑑 ～The Ultimate Battles～', '', 'hulu', 'the-ultimate-battles', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d44699af-62c1-4fe5-a133-ff0c187fa4f9.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 173216, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('35cc27c2-0299-461f-8950-625f0d1f884d', '6c723486-d2b4-4038-a6b6-3e319fdcdacf', 'hulu-the-ultimate-battles-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c520040d-b2af-403c-9bf3-e634cd5de523.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e2a930e-97f4-446c-a77e-759438f87668', '35cc27c2-0299-461f-8950-625f0d1f884d', 1, '100169846', '【スペシャルマッチ】ティラノサウルス VS ライオン', '今回のバトルフィールドは、荒れ果てた岩場。ここで最強の座をかけて戦うのは、究極の進化を遂げた恐竜王･ティラノサウルス VS 誇り高き百獣の王･ライオン! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/01/06 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c520040d-b2af-403c-9bf3-e634cd5de523.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7dea7a37-1da1-4518-99ae-45c651d0ac15', '35cc27c2-0299-461f-8950-625f0d1f884d', 2, '100169847', '【スペシャルマッチ】インペリアルマンモス VS トリケラトプス', '今回のバトルフィールドは、どこまでも広がる荒野。ここで最強の座をかけて戦うのは、マンモスの帝王･インペリアルマンモス VS 3本角の暴れん坊･トリケラトプス! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/01/13 08:00:00', 286, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a1a3a2e-58d6-4254-a36a-cc0461d02b14.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22ed968e-9656-454a-a97a-09a199ce45fd', '35cc27c2-0299-461f-8950-625f0d1f884d', 3, '100169848', '【スペシャルマッチ】ティタノボア VS スピノサウルス', '今回のバトルフィールドは、木々が鬱蒼と生い茂る森林。ここで最強の座をかけて戦うのは、すべてを呑み込む大蛇･ティタノボア VS 史上最大級の水竜･スピノサウルス! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/01/20 08:00:00', 286, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55b9f812-0a67-4c6c-8faf-caf849870452.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f72cfb74-0a59-42bc-b2e7-0f087f390255', '35cc27c2-0299-461f-8950-625f0d1f884d', 4, '100169849', '【スペシャルマッチ】ホッキョクグマ VS ヘラクレスオオカブト', '今回のバトルフィールドは、どこまでも続く白銀の氷原。ここで最強の座をかけて戦うのは、氷雪世界の白き皇帝･ホッキョクグマ VS 巨大な槍を装備した勇者･ヘラクレスオオカブト! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/01/27 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/117c3cb6-dabe-487a-bb3e-47d16d6d91f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bdb8b1cf-d083-4f7a-91dd-3d9a83d8c5f1', '35cc27c2-0299-461f-8950-625f0d1f884d', 5, '100169850', '【スペシャルマッチ】ケツァルコアトルス VS オオエンマハンミョウ', '今回のバトルフィールドは、どこまでも広がる巨大な洞窟。ここで最強の座をかけて戦うのは、太古の空の大王･ケツァルコアトルス VS 肉食昆虫界の凶暴王･オオエンマハンミョウ! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/02/03 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a9c1dc4-0624-4598-996b-be4e6fb21125.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a5b41e1-524c-427f-9053-6c20aaf91146', '35cc27c2-0299-461f-8950-625f0d1f884d', 6, '100169851', '【スペシャルマッチ】スミロドン VS シベリアトラ', '今回のバトルフィールドは、死角だらけの荒れ果てた岩場。ここで最強の座をかけて戦うのは、巨獣専門のビッグハンター･スミロドン VS 北の大地に君臨する孤高の帝王･シベリアトラ! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/02/10 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/399aab2d-29e1-4dda-ba7d-18ad5e33b38f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d87a87ae-1c3c-43c1-a3e4-3c3b64cd4875', '35cc27c2-0299-461f-8950-625f0d1f884d', 7, '100169852', '【スペシャルマッチ】アフリカゾウ VS オオスズメバチ', '今回のバトルフィールドは、どこまでも広がる荒野。ここで最強の座をかけて戦うのは、怒りの破壊神･アフリカゾウ VS エリート戦闘集団からの刺客･オオスズメバチ! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/02/17 08:00:00', 286, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd6d0dd5-bef6-489c-9466-ce7f2d81682a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3d3e2818-7e93-4502-b500-0640fa898953', '35cc27c2-0299-461f-8950-625f0d1f884d', 8, '100169853', '【スペシャルマッチ】アンドリューサルクス VS ペルビアンジャイアントオオムカデ', '今回のバトルフィールドは、ほの暗い闇に包まれた洞窟。ここで最強の座をかけて戦うのは、あぎと雄々しき怪物･アンドリューサルクス VS 密林の暴君･ペルビアンジャイアントオオムカデ! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/02/24 08:00:00', 286, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8aa7e709-2dcc-47ca-94da-236878758817.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4eae565-c774-4edd-bd80-13fce2d80633', '35cc27c2-0299-461f-8950-625f0d1f884d', 9, '100169854', 'モースト特別編集 切り抜き最強王 〜スペシャルマッチ〜', '今回はこれまで繰り広げられてきた、選ばれし猛者たちによるスペシャルマッチをプレイバーック! OH!マイモーストなスペシャルマッチ名場面集を振り返る特別編!', '2024/03/02 08:00:00', 286, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78ed618b-ab68-44c2-9ba9-37fb3f5a7130.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfc8b980-b3cc-42ad-b20f-7e8e8346f827', '35cc27c2-0299-461f-8950-625f0d1f884d', 10, '100169855', '【レギュラーマッチ】キリン VS ユウティラヌス', '来たる最強王トーナメントへの出場権を賭けた戦い、レギュラーマッチが開幕! 勝敗のみならず、最強を競うにふさわしいバトルをした者こそが最強王トーナメントに出場できるのだ! 今回のバトルフィールドは、木々が鬱蒼と生い茂る森林。ここで最強王トーナメント出場をかけて戦うのは、サバンナにそびえ立つ高層タワー･キリン VS モフモフ暴君･ユウティラヌス! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/03/09 08:00:00', 286, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab2211fb-73cf-4ad7-a929-296381a7d75c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02bbb48b-305b-4344-9cfe-290e9841c308', '35cc27c2-0299-461f-8950-625f0d1f884d', 11, '100169856', '【レギュラーマッチ】デスストーカー VS カバ', '来たる最強王トーナメントへの出場権を賭けた戦い、レギュラーマッチ! 今回のバトルフィールドは、どこまでも広がる荒野。ここで最強王トーナメント出場をかけて戦うのは、冷酷&非情な追跡者･デスストーカー VS 獰猛な河の巨獣･カバ! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2024/03/16 08:00:00', 286, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7120a7c-b5b1-4f24-8494-a4c96583bb1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
