INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb63facf-fddd-4b8e-9e56-796ea8e19ba9', '35cc27c2-0299-461f-8950-625f0d1f884d', 30, '100169875', '【レギュラーマッチ】インペリアルマンモス VS パラポネラ', '来たる最強王トーナメントへの出場権を賭けた戦い、レギュラーマッチ! 今回のバトルフィールドは、木々が鬱蒼と生い茂る森林。ここで最強王トーナメント出場をかけて戦うのは、マンモスの帝王･インペリアルマンモス VS 世界で最も危険なアリ･パラポネラ! 勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/07/27 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec5c0037-3fdd-4a3f-8b1f-68b11d164e15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
