INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5b85d4f-18fc-47b2-b48f-f7d2a9030961', '35cc27c2-0299-461f-8950-625f0d1f884d', 32, '100169877', '【レギュラーマッチ】ティラノサウルス VS スピノサウルス', '来たる最強王トーナメントへの出場権を賭けた戦い、レギュラーマッチ! 今回のバトルフィールドは、どこまでも続く白銀の氷原。ここで最強王トーナメント出場をかけて戦うのは、究極の進化を遂げた恐竜王･ティラノサウルス VS 史上最大級の水竜･スピノサウルス!勝つのはどっちだ～～!?  モ～～～～スト、ファイッ!', '2024/08/10 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d95f5b7-a72b-4c95-8c4c-8f6604b7c8bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7fbb3acf-8c57-4159-92f1-7dddbaf14fc4', '35cc27c2-0299-461f-8950-625f0d1f884d', 33, '100169878', 'モースト特別編集 ロード･トゥ･最強王', 'いよいよ開幕される、最強of最強の頂上決戦「最強王トーナメント」トーナメントに勝ち上がるのは誰だ!?  その候補者を各部門別で紹介していくOH! マイモーストな特別編!', '2024/08/17 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc585621-0ff8-4c48-a1ef-e22a1659c759.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('791b1e73-c56b-4f0b-b8d3-9901d45bf66f', '35cc27c2-0299-461f-8950-625f0d1f884d', 34, '100169879', '【最強王トーナメント】ライオン VS パラケラテリウム', 'ついに開幕した最強王トーナメント! 我こそは最強と名乗りをあげた猛者たちによる時空を超えた大バトル! 1回戦は全8試合! 第1試合のバトルフィールドは、切り立った岩壁がゴツゴツした荒れ果てた岩場。この超危険なステージで最強の座をかけて戦うのは、誇り高き百獣の王･ライオン VS 規格外のギガント哺乳類･パラケラテリウム! トーナメントを勝ち進むのはどっちだ～!?  モ～～～～スト、ファイッ!', '2024/08/24 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/445305a9-05c5-4032-b0d4-14e6e29f0a43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
