INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53f0ba3c-fe52-4d1e-8b47-0499519808ab', '35cc27c2-0299-461f-8950-625f0d1f884d', 46, '100169891', '【最強王トーナメント】スピノサウルス VS プルスサウルス', '最強of最強の頂上決戦「最強王トーナメント」2回戦第4試合のバトルフィールドは、ほの暗い闇に包まれた洞窟。最強の座をかけて、この不気味なフィールドで戦うのは、史上最大級の水竜･スピノサウルス VS アマゾンの大怪獣･プルスサウルス! トーナメントを勝ち進むのはどっちだ～!? モ～～～～スト、ファイッ!', '2024/11/22 14:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43e94950-89df-41af-9245-f48cc7f91941.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de048a50-4f56-4be5-a28d-4ce58bfa2711', '35cc27c2-0299-461f-8950-625f0d1f884d', 47, '100169892', '【エキシビションマッチ】モササウルス VS メガロドン', '「エキシビションマッチ」そのバトルフィールドは、初となる海の中! 水圧、浮力、酸素濃度、すべてが地上とは異なるこのフィールドで戦うのは、恐竜をも襲うプレデター･モササウルス VS 古代の海に生きた巨大ザメ･メガロドン! 出会うはずのない海の凶暴王同士が、時代を超えてここに激突する! さあ! 勝つはどっちだ～!? モ～～～～スト、ファイッ!', '2024/11/23 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a760d048-9dc6-4823-92e6-d2fb48df0fd0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('391a0774-1ba4-4a75-a27c-148ed1331511', '35cc27c2-0299-461f-8950-625f0d1f884d', 48, '100169893', '【最強王トーナメント】ライオン VS ティラノサウルス', '最強of最強の頂上決戦「最強王トーナメント」準決勝第1試合のバトルフィールドは、切り立った岩壁がゴツゴツした荒れ果てた岩場。この超危険なステージで最強の座をかけて戦うのは、誇り高き百獣の王･ライオン VS 究極の進化を遂げた恐竜王･ティラノサウルス! 決勝戦に勝ち進むのはどっちだ～!? モ～～～～スト、ファイッ!', '2024/11/30 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e13b4c9-e052-4152-8899-47998a1a9f82.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6aba11fb-868e-484a-b637-f4b1f84f75ea', '35cc27c2-0299-461f-8950-625f0d1f884d', 49, '100169894', '【最強王トーナメント】ティタノボア  VS プルスサウルス', '最強of最強の頂上決戦「最強王トーナメント」準決勝第2試合のバトルフィールドは、木々が鬱蒼と生い茂る森林。深い緑に囲まれたこの場所で最強の座をかけて戦うのは、すべてを呑み込む大蛇･ティタノボア VS アマゾンの大怪獣･プルスサウルス! 決勝戦に勝ち進むのはどっちだ～!? モ～～～～スト、ファイッ!', '2024/12/07 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c08a5567-de14-41aa-a642-5634d9b088e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('009e7e08-40d3-4016-8f91-c85f13a5a336', '35cc27c2-0299-461f-8950-625f0d1f884d', 50, '100169895', '【最強王トーナメント】プルスサウルス VS ティラノサウルス', '【最終話】最強of最強の頂上決戦「最強王トーナメント」決勝戦!ついに、熾烈極まる最強王バトルの頂点がここに決する!伝説となる戦いに挑むのは、全戦無敗! 超絶パワーで立ちはだかる強敵たちをなぎ倒してきた、アマゾンの大怪獣･プルスサウルス VS 全ての最強を目指す者たちの頂点に立たんとする圧倒的支配者、究極の進化を遂げた恐竜王･ティラノサウルス! 最強王の称号を手にするのはどっちだ!? モ～～～～～スト、ファイッ!', '2024/12/14 08:00:00', 285, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a9be296-7460-4f0f-93e9-93a7938d3bb3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
