INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50249d8e-23c6-45e9-bef5-2cf066208cf8', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 1, '100223338', '【ノックアウトラウンド】ティラノサウルス VS トリケラトプス', '時間も空間も超越したモースト危険な孤島「最強島」この最強島を舞台に、最強王の称号をかけて戦いが繰り広げられるモースト壮大なトーナメントこそが、ジ･アルティメット･トーナメント。最強王ノックアウトラウンド 第1試合! バトルフィールドは、鋭い冷気が身を刺す極寒の氷原。ここで最強の座をかけて戦うのは、究極の進化を遂げた恐竜王･ティラノサウルス VS 3本角の暴れん坊･トリケラトプス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/04/06 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef0cb551-8e0b-4053-b4e0-a4b3e187a2b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('edfcfec3-6c7e-4a4e-9988-0cbbff00fd73', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 2, '100223339', '【ノックアウトラウンド】パラケラテリウム VS ティタノボア', '最強王ノックアウトラウンド 第2試合! バトルフィールドは、無数の木々たちが悠然とそびえたつ森林。ここで最強の座をかけて戦うのは、史上最大の巨神･パラケラテリウム VS すべてを呑みこむ大蛇･ティタノボア! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/04/13 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b231fca-abee-4742-a9c0-f8a6e95a3ec8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('000dd30d-8576-4de9-8132-0f149dab2d67', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 3, '100223340', '【ノックアウトラウンド】ケツァルコアトルス VS ヘラクレスオオカブト', '最強王ノックアウトラウンド 第3試合! バトルフィールドは、何本もの岩の柱が鋭く突き出す広大な洞窟。ここで最強の座をかけて戦うのは、太古の空の大王･ケツァルコアトルス VS 巨大な槍を装備した勇者･ヘラクレスオオカブト! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/04/20 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a78328f-fb0e-4580-b1ba-d1e5bab14a6f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dbb9a41-6f8e-4749-844d-966ac74cb4a9', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 4, '100223341', '【ノックアウトラウンド】 ペルビアンジャイアントオオムカデ VS キリン', '最強王ノックアウトラウンド 第4試合! バトルフィールドは、荒れ果てた岩場。ここで最強の座をかけて戦うのは、密林の暴君･ペルビアンジャイアントオオムカデ VS サバンナにそびえたつ高層タワー･キリン! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/04/27 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a38cf009-2ddc-49b7-8a9a-eb7ca5d5747e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('deaeefec-a052-4e1e-81db-ef66b56f1121', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 5, '100225824', '【エキシビションステージ】ファイヤー･ドレイク VS 応龍', 'エキシビションステージ 最強王ドラゴンリーグ 第1試合! バトルフィールドは、朽ち果ててもなお、荘厳で神秘的な古代神殿の廃墟。ここで戦うドラゴンは、すべてを焼き尽くす火竜･ファイヤー･ドレイク VS 天地を統べる龍の王･応龍! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/05/04 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c28baf5-6e88-4632-aed0-8e53d27c46cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
