INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bdfd3091-c4dd-47ef-9d7b-ab51ece687b8', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 10, '100225829', '【ノックアウトラウンド】ミイデラゴミムシ VS  インペリアルマンモス', '最強王ノックアウトラウンド 第9試合! バトルフィールドは、何本もの岩の柱が鋭く突き出す広大な洞窟。ここで最強の座をかけて戦うのは、昆虫界の虎･ミイデラゴミムシ VS マンモスの帝王･インペリアルマンモス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/06/08 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/500c40fb-513e-4a13-9617-b8cfe533b0ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab925f17-7315-4c06-9c93-a02bac006c72', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 11, '100229078', '【ノックアウトラウンド】プルスサウルス VS アンキロサウルス', '最強王ノックアウトラウンド 第10試合! バトルフィールドは、無数の木々たちが悠然とそびえたつ森林。ここで最強の座をかけて戦うのは、アマゾンの大怪獣･プルスサウルス VS 骨の鎧を背負ったハンマー使い･アンキロサウルス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/06/15 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84506af9-2e36-4b08-b712-ba28db6d629d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ee3de41-9240-46dc-b75b-b92ac0a51fb5', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 12, '100229079', '【ノックアウトラウンド】ルブロンオオツチグモ VS カバ', '最強王ノックアウトラウンド 第11試合! バトルフィールドは、無数の木々たちが悠然とそびえたつ森林。ここで最強の座をかけて戦うのは、世界最大級のタランチュラ･ルブロンオオツチグモ VS 獰猛な河の巨獣･カバ! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/06/22 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/526b35c9-e28a-4b6e-a478-9c27ed8fdf13.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be20143e-623b-4028-9fd7-162b9b25b7dc', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 13, '100229080', '【エキシビションステージ】レインボー･サーペント VS ヴリトラ', 'エキシビションステージ 最強王ドラゴンリーグ 第2試合! バトルフィールドは、密林にそびえ立つ断崖絶壁に囲まれたテーブルマウンテン。ここで戦うドラゴンは、世界を創造した虹竜･レインボー･サーペント VS 復讐の代行者･ヴリトラ! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/06/29 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/692ac97c-a60d-4eb6-b093-54ace04cfb07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('463e6c62-b055-4ec1-982e-0420c07d93c4', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 14, '100231468', '【ノックアウトラウンド】ギガノトサウルス VS アンペロサウルス', '最強王ノックアウトラウンド 第12試合! バトルフィールドは、荒れ果てた岩場。ここで最強の座をかけて戦うのは、南米に君臨した暴食王･ギガノトサウルス VS 鎧を着た竜脚形類･アンペロサウルス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/07/06 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a81c0225-564b-4509-a0c2-eaa500243b04.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('714b0201-1079-4422-9735-a444538f1606', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 15, '100231469', '【ノックアウトラウンド】オニヤンマ VS オオスズメバチ', '最強王ノックアウトラウンド 第13試合! バトルフィールドは、何本もの岩の柱が鋭く突き出す広大な洞窟。ここで最強の座をかけて戦うのは、縦横無尽に飛翔する空の覇者･オニヤンマ VS エリート戦闘集団からの刺客･オオスズメバチ! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/07/13 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ba21e38-696d-4551-b5ea-1438aaa7bc29.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('887f6ce1-5647-43b1-b83e-efd442829bc7', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 16, '100231470', '【スペシャルエキシビション】ダイオウイカ VS リヴァイアサン･メルビレイ', '水中最強王スペシャルエキシビション第1試合! バトルフィールドは、水圧が重くのしかかる、地上とはまったく異なる世界となる海中。ここで戦うのは、謎多き深海の住人･ダイオウイカ VS 巨大な体と牙で大海を制す･リヴァイアサン･メルビレイ! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/07/20 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83811fac-90b5-446c-95b2-f16507d21ce1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31eb9587-91fe-449e-a5f8-fbad821693a7', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 17, '100231471', '【ノックアウトラウンド】ホッキョクグマ VS カリコテリウム', '最強王ノックアウトラウンド 第14試合! バトルフィールドは、朽ち果ててもなお、荘厳で神秘的な古代神殿の廃墟。ここで最強の座をかけて戦うのは、氷雪世界の白き皇帝･ホッキョクグマ VS カギ爪のナックルウォーカー･カリコテリウム! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/07/27 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7793da22-89c6-4855-9720-5afac6c45245.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9a6dd5d-d70f-4bbc-b243-fcf0e00d88f3', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 18, '100233414', '【ノックアウトラウンド】プロコプトドン VS ユウティラヌス', '最強王ノックアウトラウンド 第15試合! バトルフィールドは、灼熱のマグマが噴き出し、溶岩の川が流れる危険に溢れた火山地帯。ここで最強の座をかけて戦うのは、古代世界のヘビー級キックボクサー･プロコプトドン VS モフモフ暴君･ユウティラヌス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/08/03 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91df750d-56bd-4bc2-978b-6f35c0d4c0a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
