INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f41fa56-9bf6-43dc-bdd0-8046338388dc', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 26, '100233422', '【マッチアップラウンド】ライオン VS ヘラクレスオオカブト', '第1ステージ『最強王ノックアウトラウンド』を制した猛者たちによる次なるステージ『最強王マッチアップラウンド』が開幕! 最強王マッチアップラウンド第1試合! バトルフィールドは、朽ち果ててもなお、荘厳で神秘的な古代神殿の廃墟。ここで最強の座をかけて戦うのは、誇り高き百獣の王･ライオン VS 巨大な槍を装備した勇者･ヘラクレスオオカブト! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/09/28 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08989a4a-2c40-4d64-96f3-70d8633ebff4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
