INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e3be348-98ff-4970-960d-809f4659c2fc', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 28, '100233424', '【マッチアップラウンド】パラケラテリウム VS オオカレエダカマキリ', '最強王マッチアップラウンド第3試合! バトルフィールドは、密林にそびえ立つ断崖絶壁に囲まれたテーブルマウンテン。ここで最強の座をかけて戦うのは、史上最大の巨神･パラケラテリウム VS 木の葉隠れの擬態忍者･オオカレエダカマキリ! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/10/12 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10c97cd3-fade-47d8-b182-a5f89ad477f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0351566-7780-441c-80a5-391480ac997f', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 29, '100233425', '【マッチアップラウンド】ルブロンオオツチグモ VS テリジノサウルス', '最強王マッチアップラウンド第4試合! バトルフィールドは、灼熱のマグマが噴き出し、溶岩の川が流れる危険に溢れた火山地帯。ここで最強の座をかけて戦うのは、世界最大級のタランチュラ･ルブロンオオツチグモVS命を刈り取るカマ恐竜･テリジノサウルス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/10/19 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30c14696-c413-48e4-a9d6-6e5dcc1b4c7b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b1d2faf-aa25-4aea-9d32-4a74ad495a73', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 30, '100233426', '【スペシャルエキシビション】メガロドン VS プルスサウルス', '水中最強王スペシャルエキシビション第2試合! バトルフィールドは、水圧が重くのしかかる、地上とはまったく異なる世界となる海中。ここで戦うのは、太古の海に生きた巨大ザメ･メガロドン VS アマゾンの大怪獣･プルスサウルス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/10/26 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/977636b6-1c3b-4e38-a93c-92ca2c00056c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5cbe5ff-dd54-41f2-add1-c75a69fe58ae', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 31, '100233427', '【エキシビションステージ】レインボー･サーペント VS ファイヤー･ドレイク', 'エキシビションステージ 最強王ドラゴンリーグ 第4試合! バトルフィールドは、鋭い冷気が身を刺す極寒の氷原。ここで戦うドラゴンは、世界を創造した虹竜･レインボー･サーペント VS すべてを焼き尽くす火竜･ファイヤー･ドレイク! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/11/02 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bd91f2b-2087-49a2-93b1-570fec80a3cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5b90e13-9a29-4dd0-b888-b12a4f6379cd', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 32, '100233428', '【マッチアップラウンド】ティタノボア VS ケツァルコアトルス', '最強王マッチアップラウンド第5試合! バトルフィールドは、視界を遮るものは何もない、無限に広がる荒野。ここで最強の座をかけて戦うのは、すべてを呑み込む大蛇･ティタノボア VS 太古の空の大王･ケツァルコアトルス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2025/11/09 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e2c4e2b-aa94-4840-ac63-25c7ea630ee4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
