INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('369125dc-2c64-4f7a-83b9-20607b2effa8', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 43, '100243559', '【バトルロワイヤル第2試合】ティタノボア VS カリコテリウム VS トリケラトプス', 'バトルロワイヤル第2試合! バトルフィールドは、無数の木々たちが悠然とそびえたつ森林。ここで最強の座をかけて戦うのは、すべてを呑み込む大蛇･ティタノボア VS カギ爪のナックルウォーカー･カリコテリウム VS 3本角の暴れん坊･トリケラトプス! 準決勝に勝ち上がる猛者は誰だ!? モ～～～～スト、ファイッ!', '2026/02/01 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e826200a-f75e-4c9d-90de-8170bd9b9bf3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('969249d0-c268-4971-99eb-bc333998724a', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 44, '100243560', '【バトルロワイヤル第3試合】パラケラテリウム VS プルスサウルス VS インペリアルマンモス', 'バトルロワイヤル第3試合! バトルフィールドは、荒れ果てた岩場。ここで最強の座をかけて戦うのは、史上最大の巨神･パラケラテリウム VS アマゾンの大怪獣･プルスサウルス VS マンモスの帝王･インペリアルマンモス! 準決勝に勝ち上がる猛者は誰だ!? モ～～～～スト、ファイッ!', '2026/02/08 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02ad97d4-2fdb-4f1a-abb1-a418b66fbdc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('048507f1-681d-4bb6-aafd-e9e4fdd23c53', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 45, '100243561', '【バトルロワイヤル第4試合】プロコプトドン VS スピノサウルス VS ギガノトサウルス', 'バトルロワイヤル第4試合! バトルフィールドは、密林にそびえ立つ断崖絶壁に囲まれたテーブルマウンテン。ここで最強の座をかけて戦うのは、古代世界のヘビー級キックボクサー･プロコプトドンVS史上最大級の水竜･スピノサウルスVS南米に君臨した暴食王･ギガノトサウルス! 準決勝に勝ち上がる猛者は誰だ!? モ～～～～スト、ファイッ!', '2026/02/15 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b06daa8f-6acc-4818-a599-75336c6d6470.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b0c5cbb-8202-4b5f-89d4-d561c4fd1d87', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 46, '100243562', '【準決勝第1試合】ティタノボア VS ヘラクレスオオカブト', '最強王トーナメント準決勝第1試合! バトルフィールドは、鋭い冷気が身を刺す極寒の氷原。ここで最強の座をかけて戦うのは、すべてを呑み込む大蛇･ティタノボア VS 巨大な槍を装備した勇者･ヘラクレスオオカブト! 決勝進出を決めるのはどっちだ～～!? モ～～～～スト、ファイッ!', '2026/02/22 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d061788c-7823-4a96-8f7a-83b32fbe5cc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('471f0733-1562-48b8-a697-23c77443c33c', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 47, '100243563', '【準決勝第2試合】インペリアルマンモス VS ギガノトサウルス', '最強王トーナメント準決勝第2試合! バトルフィールドは、灼熱のマグマが噴き出し、溶岩の川が流れる危険に溢れた火山地帯。ここで最強の座をかけて戦うのは、マンモスの帝王･インペリアルマンモス VS 南米に君臨した暴食王･ギガノトサウルス! 決勝進出を決めるのはどっちだ～～!? モ～～～～スト、ファイッ!', '2026/03/01 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3345e0d9-6161-4dfe-b341-6c3adc37bb0d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('acdaefe0-d93c-4217-b089-6648d00ca784', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 48, '100243564', '【スペシャルエキシビション】リヴァイアサン･メルビレイ VS スピノサウルス', '水中最強王スペシャルエキシビション最終試合! バトルフィールドは、水圧が重くのしかかる、地上とはまったく異なる世界となる海中。ここで戦うのは、巨大な体と牙で大海を制す･リヴァイアサン･メルビレイ VS 史上最大級の水竜･スピノサウルス! 勝つのはどっちだ～～!? モ～～～～スト、ファイッ!', '2026/03/08 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e885c20e-eeee-43e9-9f92-ca9cbbfbae84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9c81800-d745-44f9-947b-3f6715483187', 'dfa67f3c-e364-4cb2-a4f5-27385fb1156c', 49, '100243565', '【決勝戦】ティタノボアVSインペリアルマンモス', '最強王トーナメント決勝戦! バトルフィールドは、朽ち果ててもなお、荘厳で神秘的な古代神殿の廃墟。ここで最強の座をかけて戦うのは、すべてを呑み込む大蛇･ティタノボアVSマンモスの帝王･インペリアルマンモス! 最強無敵のナンバーワンになるのはどっちだ～～!? モ～～～～スト、ファイッ!', '2026/03/15 08:00:00', 660, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b62e5ad9-6bdf-48df-a6a4-e44cb8178b4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('60e439b1-d9b8-4865-ae82-44c4b3d2bccc', '最後にひとつだけお願いしてもよろしいでしょうか', '', 'hulu', 'may-i-ask-for-one-final-thing', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21b0214f-b3b4-437f-b31d-50bb4287f410.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 181447, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2c2177b4-88dc-43b4-bab2-a41ac14f7590', '60e439b1-d9b8-4865-ae82-44c4b3d2bccc', 'hulu-may-i-ask-for-one-final-thing-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d882322-a659-466c-865a-f1102b4cdf21.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63992cac-9032-434e-8f9e-37e622f7f470', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 1, '100240370', '悪徳貴族 (豚野郎達) を思う存分ボコボコにしてスカッとしてもよろしいでしょうか', '見目麗しき公爵令嬢のスカーレットは、婚約者である第二王子カイルから理不尽な婚約破棄を言い渡されてしまう。新たな婚約者も登場し、散々な濡れ衣を着せられ“悪役令嬢”と罵られるスカーレット。しかし彼女は、ただ断罪されるだけの悪役令嬢ではなかった。「私の最後のお願いです。このクソアマをブッ飛ばしてもよろしいですか?」――彼女は“拳”を握り、目の前の腹立たしい悪徳貴族たちに立ち向かう。', '2025/10/04 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d882322-a659-466c-865a-f1102b4cdf21.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('090f1b55-d214-4a87-9548-ab4ecbb4b6d8', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 2, '100240859', '拳の味を教えて差し上げる、これを淑女の嗜みとしてもよろしいでしょうか', '悪徳貴族たちを拳ひとつで制裁したスカーレット。事件後、彼女は第一王子のジュリアスから事の顛末を聞く。今回の騒動により、第二王子派の貴族たちが一斉に取り締まられ、黒幕が宰相のゴドウィンであることが明らかになったそうだ。そして時を同じくして、スカーレットの元にメイドに扮した暗殺者が迫る。「ムカついた方を殴る。これは淑女の嗜みですわ」――暗殺を指示した黒幕を殴るため、スカーレットは王都へ向かう。', '2025/10/11 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22a13a12-4f74-45ab-918f-8ce0db6d0da1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e218233e-2319-41a9-b4bf-1a66bd6b61dd', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 3, '100241350', 'ちゃんと話し合いで解決しようと思いましたが、やはりボンボコボンボコ上位貴族を殴ってもよろしいでしょうか', '黒幕のゴドウィンに会うため、奴隷オークションへの潜入を企てるスカーレットたち。スカーレットは奴隷商と交渉し、ナナカを奴隷として引き渡すことを条件としてオークションへの参加を許可される。いつもは“拳”で解決する彼女も、今回は話し合いで解決……と思いきや、乱暴に扱われるナナカを見て、彼女はやはり“拳”を握る。「では、遠慮なくブッ飛ばせます」――その一方で、ゴドウィンも怪しげな動きを見せ始めていた。', '2025/10/18 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff15b51d-9eac-4fd4-bba8-949dd9b54ac5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6022a166-e314-4bbe-85b5-cd7d894171d2', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 4, '100241971', '拳の想い人 (サンドバッグ) に会いに行ってもよろしいでしょうか', 'ついに奴隷オークション当日。レオナルドや王宮騎士団も参戦し、会場は緊張に包まれていた。無用な暴力を振るわないことを条件に潜入を許可されたスカーレットだったが、貴族たちの醜悪な振る舞いに我慢の限界を迎える。己の拳で制裁するべく、ジュリアスと秘密の取引をしゴドウィンを追う。「悪徳貴族の方々は私のお肉。取っちゃメッ、ですよ?」――しかし、ゴドウィンを追った先で、スカーレットは新たな敵と対峙する。', '2025/10/25 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bd2e6b7-600f-4f88-aea6-043643b5d826.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e77215a-84ac-4c6b-b15f-f99e59eac430', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 5, '100242803', 'クソ王子をブッ飛ばしてもよろしいでしょうか', 'ゴドウィンから“テレネッツァは異世界から転生してきた人間”だと明かされるスカーレット。しかしスカーレットは、その意味を全く理解していなかった。「そろそろ殴ってもよろしいでしょうか?」――ゴドウィンに想いのこもった“拳”を叩き込むスカーレット。しかし悪の宰相は、ボコボコにされながらも最後の力を振り絞って起死回生の一手を打つ。万事休すのスカーレット。しかしその時、彼女を身を挺して庇う影があった……。', '2025/11/01 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9abdd326-b9f1-472d-9c18-02c84e739066.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22d42753-24ea-457b-9781-9bf5f7526416', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 6, '100243905', '豚さんを空に飛ばして差し上げてもよろしいでしょうか', '黒幕･ゴドウィンを捕えるも、彼は獄中で不可解な死を遂げた。消えぬ不穏な気配に、スカーレットはディアナ聖教の“聖地巡礼の儀”に同行することを決める。巡礼の出発地へ向かうスカーレットたちだが、道中で対立するパルミア教の妨害を受けてしまう。立ちはだかる異端審問官を前に、“拳”を構えるスカーレット。「殴り心地が良さそうな豚野郎ですわ」――一方、聖女･ディアナはスカーレットとの再会を待ちわびていた。', '2025/11/08 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2287be01-2a16-4c2d-8b9b-b0f7aae3e40d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de47d552-0194-4aee-b225-86836e5a6bee', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 7, '100245023', 'ギャップ萌え作戦を決行してもよろしいでしょうか', '聖地巡礼の出発式典で、またもパルミア教の妨害を受けたスカーレットたち。スカーレットは単身パルミア教総本部に乗り込んで“拳”を振るい、騒動を鎮める。しかし、騒動の直後から聖女･ディアナの様子がおかしい。妨害の不安によるものかと思いきや、ディアナはある人物への恋心に悶えていたのだった。「大丈夫。私にいい考えがありますわ」――立ち寄った温泉地で、スカーレットは秘密の作戦を実行する。', '2025/11/15 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b863619-d67f-48f4-9faa-d3145463597d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d83c07c-c2af-4fda-873b-2892ea4022c0', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 8, '100245898', '拳でよければハンカチ代わりに差し上げてもよろしいでしょうか', '巡礼の目的である“浄化の儀”を行うため、東の大聖石へ向かうスカーレットたち。順調に執り行われる儀式の一方で、対立するパルミア教に潜入していたシグルドから“巡礼一行に裏切り者あり”と報せが届く。次なる目的地、北の街･スノーウィンドへ辿り着いた一行を待ち受けていたのは、パリスタン王国の“真の聖女”を名乗る宿敵の女だった。「ごきげんよう、テレネッツァさん」――そして裏切り者の正体が明らかになる。', '2025/11/22 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0aec7b29-b86b-4a46-85a6-33187c17bb09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cbb45e0-c595-411e-96bf-43ff237f68b2', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 9, '100246278', 'それは誰にでもできることではないのですとお伝えしてもよろしいでしょうか', 'テレネッツァとの戦闘で力を使い果たし、昏睡状態となったスカーレット。一方ジュリアスは、“もう一人の裏切り者”の正体を突き止めていた。裏切りの理由を問いただそうとしたその時、パルミア教の計画が動き出す。魔物の侵攻、周辺国からの戦線布告……重大な危機に瀕したパリスタン王国。そんな中、ようやく狂犬姫が目を覚まし“拳”を振るう。「寝起きはやはりこれに限りますね」――裏切り者たちの真実が明かされる。', '2025/11/29 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d4eada5-e24d-439f-af42-035776ea34dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43b3b7b0-c5ed-453e-bab2-29d01408855b', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 10, '100247129', '分厚いお肉の芯までボディブローで火を通してもよろしいでしょうか', '大聖石を破壊されたパリスタン王国は、魔物の侵攻と周辺国からの宣戦布告により危機的状態に陥っていた。圧倒的な数の魔物と国境に迫る敵軍を前に、スカーレットたちは打開策を模索する。そんな絶望的な状況のなか、心強い同盟軍が現れる。そして敵国と交渉の余地があることも明らかに。一同は危機を乗り越えるために立ち上がる。「さあ、魔物狩りと参りましょうか」――狂犬姫スカーレットの“拳”が炸裂する。', '2025/12/06 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71a9a555-cdac-4a57-9a2d-3dbe485de8f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13fc11c7-5e53-4cf5-8d2e-0db2b57f54c7', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 11, '100247882', '焼き足りなかったようなのでいっそミンチにしてもよろしいでしょうか', 'ファルコニア軍との停戦交渉に向かったナナカとディオスだったが、囮となるはずだった“紅天竜騎兵団”の脳筋ぶりで作戦は崩れ、立ち往生してしまう。報せを受けたスカーレットによる再度の陽動作戦をやはり聞いていなかったアルフレイムはただ一騎、圧倒的な数の魔物に立ち向かう……。「焼き足りなかったようですね。いっそミンチにしましょうか」――過酷な戦いの中、各人の奮闘によって危機は次第に切り開かれていくが……。', '2025/12/13 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5de75ac9-5a68-4e88-8b31-9ec27ee2a573.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7eeecaf-23a9-4f21-be00-332d25f0d9ec', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 12, '100248499', '溜まった拳のツケを払っていただいてもよろしいでしょうか', '西の街･サハスギーラの大聖石を狙うテレネッツァたち。情報を得たスカーレットたちも、サハスギーラへ急行する。パルミア教が仕掛けた罠をかいくぐり、一行はパルミア教徒が集まる広間へと辿り着くが肝心のテレネッツァの姿はない……。スカーレットはテレネッツァを止めるため、単身で憎き彼女の元へ向かう。「随分と手を焼かせてくれましたが、いよいよ終幕です」―スカーレットとテレネッツァの最後の戦いが始まる!', '2025/12/20 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/baeb2d03-fb10-4407-8474-4809ea0dbdee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c498660-9de9-4f9b-bfc3-1ecee265a26d', '2c2177b4-88dc-43b4-bab2-a41ac14f7590', 13, '100249637', '最後にひとつだけお願いしてもよろしいでしょうか', '【最終話】操られたジュリアスを迷いなく殴り飛ばしたスカーレット。困惑するテレネッツァだが、今度はジュリアスの命を人質にしてスカーレットに降伏を迫る。その時、ジュリアスの持つ“加護”の秘密が明かされる。それは、愛する者が危機に陥った時に無限の力を発動する特別な加護。発動条件は、相思相愛であること。「……ジュリアス様、ひとつ確認させてください」――スカーレットは意を決し、ジュリアスを見つめて……。', '2025/12/27 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9201f5cf-93c3-45e7-947a-d8dac9ae4654.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e3a5c722-69e2-41f5-b695-fb9fe921436b', '最後の召喚師 -The Last Summoner-', '', 'hulu', 'the-last-summoner', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f82b2f7f-b79d-4ded-a538-a0991ead8737.jpg?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'FINISHED', NULL, 114108, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 'e3a5c722-69e2-41f5-b695-fb9fe921436b', 'hulu-the-last-summoner-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2068c98a-8efc-491d-ad64-2b1356126936.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94e98774-c043-4152-89df-e56bbb324a86', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 1, '100134728', '覚醒', '平凡な高校生･アジェは、あることをきっかけに女神･ドラを召喚する。魂の契約を迫る彼女に、平和な生活を狂わされるアジェだったが、召喚師という新しい世界への扉を開くことになる――。', '2023/01/18 00:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2068c98a-8efc-491d-ad64-2b1356126936.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46335d9c-72b9-4f3d-8819-a88f243e75b7', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 2, '100135280', 'ハナ', 'ある日人喰い花に襲われるアジェとドラ。人喰い花の正体は謎の美少女･ハナの召喚霊だった。二人はピンチを乗り切ることができるのか……!?', '2023/01/25 00:00:00', 1473, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c99ef407-e9f1-49a5-8f08-871866bbc5da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a8302ea-b8cf-4669-aab6-1f61b1db385a', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 3, '100135801', 'ミャウ', '突如、街で動物たちが暴れだす。騒動の首謀者は、召喚師のミャウだった。街を守るハナはミャウと戦うことになるが……。', '2023/02/01 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/388cbf03-bdf1-4229-8b76-451bcad8bc29.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cab7acd4-c40d-4116-82b0-772ca075e1f6', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 4, '100136312', '最後の晩餐', 'ハナの屋敷に招待されたアジェたちはハナの祖父･ハールンと会う。ハールンに召喚師の世界を教わるアジェたちだったが、突如何者かに屋敷が襲われ……。', '2023/02/08 00:00:00', 1458, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb3ca2f0-3d02-4aa6-b8f8-18c83f03c0af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('707d1ab2-18a1-4239-9884-d55800927747', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 5, '100137003', '破壊者', 'ファンシン率いる【破壊者】に急襲されるアジェたち。破壊者たちの狙いはハールンだった。強力な破壊者たちの攻撃にアジェは苦戦を強いられる。', '2023/02/15 00:00:00', 1391, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69d4c8fc-e539-4cec-895f-ec3f83df4b7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bca0ffce-f984-4cdf-bba0-78b73dc4ada7', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 6, '100137683', 'スタン', '壊滅状態に追いやられたアジェたちが新たな仲間としてスカウトしたのは召喚師のスタンだった。何者かに追われるスタンを助けるアジェたちだったが……。', '2023/02/22 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85d29a57-71e8-4e68-ab46-e01dc795e413.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37cd8d01-e7b8-4d9f-a25e-e6424315ec0d', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 7, '100138132', '石の森', '【破壊者】に立ち向かうことを決心したアジェたちは破壊者の一人の居場所を突き止める。そこはかつて地図から消えた廃村だった……。', '2023/03/01 00:00:00', 1466, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56097b2a-f4f1-4355-a6bc-d9e031cafb75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2d88cc2-ffb0-445c-a1e1-0b86bd0075cc', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 8, '100139371', '彼岸花', '破壊者･モドを追い詰めたアジェたち。彼はアジェに、自らの過去を語り始める。そこで語られたのは、この村の悲しい歴史だった……。', '2023/03/08 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/232b8d41-4a61-404e-832d-0cc1b29580e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9e1ffba-9182-4c05-9719-1454e988eaf8', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 9, '100140157', '悪魔熔炉', 'モドを倒したアジェたちは【破壊者】から追われることに。アジェの家に戻ると、ハナの姿がない。どうやら彼女は、召喚師の聖地･悪魔熔炉 (デビルフォージ) へ向かったらしく……。', '2023/03/15 00:00:00', 1081, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b288eead-89f3-431c-8965-11f81d1db956.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2313ad9-ae4e-452f-9d22-1d1323e2fa87', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 10, '100140540', '熔炉島', '【破壊者】の追撃を受けつつも何とか悪魔熔炉にたどり着いたアジェたち。そこは世界中の召喚師が集まり公正公平に戦う巨大競技場だった。ハナを探すため、アジェたちも試練を受けることになる。', '2023/03/22 00:00:00', 1408, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78afb595-678c-489a-a2b0-5cf7802ba972.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27888808-7daf-4b3e-9e2a-11dbe3b4ad7d', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 11, '100141188', '果てしなき試練', '早くも悪魔熔炉の試練を受けることとなったアジェたち。それぞれの力を発揮し乗り越えていくが、息つく間もなく新たな試練に挑むこととなる……。', '2023/03/29 00:00:00', 1278, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6159dbf-dc3c-4be5-bbed-01b5dc0af11b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b943e70b-28c1-41b2-9ebb-db42073c467a', '9b964b07-b5eb-4d39-bd2f-8b25e9adb6d3', 12, '100141879', '奉納', '【シーズン1 最終話】次々と試練を突破していくアジェたち。【守護者】【破壊者】それぞれの思惑がうずまく悪魔熔炉でアジェたちは生き残ることができるのか……!?', '2023/04/05 00:00:00', 1263, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/726f176a-acfd-4ce3-82e1-9b7b41372fa1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4e0a2826-5c74-47dd-b95a-c7ff08c3bddb', '最弱テイマーはゴミ拾いの旅を始めました。', '', 'hulu', 'saijaku-tamer-wa-gomihiroi-no-tabi-wo-hajimemashita', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/860fc865-3c9a-45a0-b6b4-df289a8a797a.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 156891, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('702eb5a7-5865-42ea-bfaf-8355280a4284', '4e0a2826-5c74-47dd-b95a-c7ff08c3bddb', 'hulu-saijaku-tamer-wa-gomihiroi-no-tabi-wo-hajimemashita-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62b024fe-edb9-4a13-a89b-19a44ea9faef.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64458099-d96b-4a6a-a8ec-2a165d9b606d', '702eb5a7-5865-42ea-bfaf-8355280a4284', 1, '100171841', 'ひとりの旅へ', '森で暮らす8歳の少女フェミシア。村長はフェミシアを不吉な子供だと言って捕まえようとする。村を捨てて冒険の旅に出たフェミシアは、『捨て場』でまだ使えるゴミを拾って、旅の道具にする。しかし、フェミシアを追跡する冒険者が現れる。冒険者から逃げるフェミシアだが、スライムの大群と遭遇して――。', '2024/01/14 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62b024fe-edb9-4a13-a89b-19a44ea9faef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bebd5d1b-7f9b-4ee7-b4c3-e1d9be77d360', '702eb5a7-5865-42ea-bfaf-8355280a4284', 2, '100171810', 'ラトト村へ', '森を旅する少女アイビーは、ワナで野ネズミを捕まえると、新しい村に立ち寄る。その村でも人はみんな、様々なスキルを使って働いていた。それを見てアイビーは、自分のスキルについて悩む。野ネズミの肉を売ってお金を手に入れるアイビーは、何年かぶりのパンを買う。しかしソラはパンを食べず――。', '2024/01/21 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56e76f26-dec7-4620-bae3-33d4611b1196.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a2e4812-ce18-48fb-8e9d-813856cf70e5', '702eb5a7-5865-42ea-bfaf-8355280a4284', 3, '100173310', '追憶の日へ', 'もうすぐ5歳になる少女フェミシアは、優しい家族にかこまれて暮らしていた。この国では人はみな、5歳になると教会でスキルをさずかり、そのスキルで得意な仕事につく。どんなスキルがもらえるかは分からず、すべては神様しだい。フェミシアは、魔物を手なずけるテイマーになりたいと言うが――。', '2024/01/28 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/752f44b9-cfd0-474f-98ee-d36c00983fea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77f193e7-4afb-4780-8740-29d016320ee8', '702eb5a7-5865-42ea-bfaf-8355280a4284', 4, '100174109', '思わぬ事態へ', 'ソラと一緒に楽しい旅を続けるアイビー。青いポーションが大好きなソラは、アイビーがケガを治すためにとってあるものまで、ぜんぶ食べてしまいそうになる。アイビーはソラを早く寝かせようと、おとぎ話を始める。そのむかし、世界は戦争をしていた。戦争を止めるため、魔術師はある魔法を使って――。', '2024/02/04 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47cfc349-37c4-4409-8217-baeb1015abcc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f416f676-186f-455d-88e6-eed4e4c1a572', '702eb5a7-5865-42ea-bfaf-8355280a4284', 5, '100174900', 'ラトメ村へ', '次の村に立ち寄るアイビー。村の入り口では、怖そうな門番が見張りをしていた。アイビーが恐る恐る村に入ろうとすると、門番に呼び止められて尋問される。アイビーは、ラトミ村から来た事を正直に話すと、門番は意外な事を言うのだった。そして、なぜかアイビーの買い物に付き合ってくれるのだった。', '2024/02/11 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/424f2f2b-d1e9-47d0-9350-cf56c32f4c15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dafb0d17-1e34-4d31-a732-b2095f62b5ff', '702eb5a7-5865-42ea-bfaf-8355280a4284', 6, '100175232', '想い彼方へ', 'アイビーの狩りを手伝ってくれるシエル。おかげで大猟だった獲物を売りに行くと、なぜか村人がみんな、アイビーに優しい。不思議に思っていると、どうやらオグト隊長の仕業らしい。肉を売ってお金を手にしたアイビーは、ラトミ村の特産のザロを売る行商人に出会う。そして、ラトミ村の話を聞くと――。', '2024/02/18 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2392e50d-120e-43ad-8643-cea55bde7b8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1039f0af-75d1-4251-86e5-a35861991cec', '702eb5a7-5865-42ea-bfaf-8355280a4284', 7, '100175725', '冒険の道へ', 'ソラ、シエルと一緒に旅をするアイビーだが、突然、何かに追いかけられる。なんとか逃げ切ろうとするが、魔物の群れと遭遇してしまう。必死に逃げるアイビーだが、ワナにかかってしまい、身動きがとれなくなる。そこに現れたのは冒険者のチームと、スライムを操る、星を持ったテイマーだった。', '2024/02/25 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/382bd4b4-b794-46b8-b165-8697f6d584cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fcdc3fe0-e105-4463-8d5c-c2448dcc9c7d', '702eb5a7-5865-42ea-bfaf-8355280a4284', 8, '100176570', '危険な町へ', '魔物を退治した討伐隊は、野営地で酒盛りを始める。アイビーは美味しい料理を作れるため、冒険者たちの間で人気者だった。いろいろな冒険者を紹介されたアイビーは、討伐隊と一緒に次の町へ向かう。初めて見る大きな町に感動するアイビーだったが、その町には大きな問題があった。', '2024/03/03 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ea9c2b8-d40a-4b05-ac99-393389ccf15e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('073ec996-2580-4ad3-9832-57aabd4268c0', '702eb5a7-5865-42ea-bfaf-8355280a4284', 9, '100177420', '組織との対決へ', 'アイビーが9歳になった事を伝えると、みんなからお祝いの言葉をもらう。長いあいだ人から祝われた事のなかったアイビーは、感激する。炎の剣と雷王のメンバーは、組織の犯罪について説明をする。そこでアイビーは、ソラの能力と前世の記憶によって、組織について分析をするのだった。', '2024/03/10 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2b1eef6-5536-4a81-9ea7-03561aabf4ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59c58139-b340-40d4-aa27-8b0c946c22cc', '702eb5a7-5865-42ea-bfaf-8355280a4284', 10, '100178213', '事件の渦中へ', 'ミーラたちと一緒に、甘い物を食べに行くアイビーとラットルア。ソラによると、双子の兄弟トルトとマルマは、やはり悪い人だった。状況から考えると、緑の風は組織のオトリかもしれない。このままだと、ミーラたちは殺されてしまう。そこでアイビーは反対に、自分がオトリになると言うのだった。', '2024/03/17 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4e3f0cd-c711-4309-b586-215136563ae4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ddc04a2-050a-4b7b-b8b4-4d7e7db14c64', '702eb5a7-5865-42ea-bfaf-8355280a4284', 11, '100178588', '戦へ', '作戦を開始するアイビーとラットルア。二人はワナにかかったふりをして、緑の風といっしょに、敵のいる甘味処に着いていく。そこでミーラたちを問い詰めるラットルア。正体がバレたトルトとマルマは、ラットルアと戦う。一方、炎の剣と雷王は、バークスビー団長と共に別の作戦を決行していた。', '2024/03/24 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0832dfd-87d7-440f-98e8-d43014592141.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b045274-bc4d-4084-a6ac-5598d9866070', '702eb5a7-5865-42ea-bfaf-8355280a4284', 12, '100179331', '三人の旅へ', '【最終話】アイビーは、事件の顛末の説明を受ける。組織の実体は想像よりはるかに大きく、国を揺るがす大問題になっていた。作戦に貢献したアイビーとソラは、ギルドマスターたちに感謝される。そしてアイビーは、炎の剣や雷王、そして自警団団長たちから、この町で一緒に暮らそうと誘われるのだった。', '2024/03/31 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e47e688-8f27-4e36-ab74-ac5ea9d0e2e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('fbabe06e-fff9-4cd2-9f81-06708c72e024', '最弱無敗の神装機竜《バハムート》', '', 'hulu', 'undefeated-bahamut-chronicle', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50024924_series_art__338x600_undefeated_bahamut_chronicle_920eb8f62fce1e6ede5a4f97eb6c2bbf.jpg?w=331&h=447&p=t', 'hulu', 2016, 0, 1, 'FINISHED', NULL, 21188, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('23dfccaf-2296-4668-a183-e03ba63787d0', 'fbabe06e-fff9-4cd2-9f81-06708c72e024', 'hulu-undefeated-bahamut-chronicle-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1fab3881-11c7-4e96-bf96-fb2ef26aefc0.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2058a49-5339-4035-b1b4-62dd707f54c1', '23dfccaf-2296-4668-a183-e03ba63787d0', 1, '60671630', '朱の戦姫', '5年前にクーデターによって滅ぼされたアーカディア旧帝国の皇子であるルクスは、アティスマータ新王国で咎人として国民の雑用を引き受けるという契約のもと、日々様々な仕事に励んでいた。そんなある日、不運にも屋根が壊れ、ドラグナイトを目指す少女たちが通う学園の浴場に落下してしまったルクスは、新王国の姫であるリーズシャルテことリーシャに目を付けられ…。', '2016/01/15 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1fab3881-11c7-4e96-bf96-fb2ef26aefc0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c74f03b0-e104-4c8e-9d9a-611045371275', '23dfccaf-2296-4668-a183-e03ba63787d0', 2, '60672771', '最弱の機竜使い', 'ドラグナイトとしての適性値が高い少女たちを育成するための学園に通うことになったルクス。少女たちから好奇の目で見られ、様々な雑用を押し付けられそうになっていたところを助けたのは、才女として学園で一目を置かれているクルルシファーだった。クルルシファーはルクスに旧帝国を壊滅させた伝説のドラグナイトである《黒き英雄》を探して欲しいと頼む。', '2016/01/22 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9700d0e7-f709-4dc6-bba8-e0ceb95f6fae.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39ea0813-cbd2-44c0-b8cd-8f6b0b33c91f', '23dfccaf-2296-4668-a183-e03ba63787d0', 3, '60676091', '北の令嬢の婚約事情', 'ルクスの入学祝いと称してパーティーを開いてくれたリーシャたち。そこへ水を差すかのように大量の雑用依頼を持ったレリィがパーティーの余興としてルクス争奪戦を提案する。それは依頼を受けてもらえない生徒たちへの不満解消のため、ルクスが持っている特別な依頼書を奪うことができれば、一週間優先して雑用を依頼できるというもので…。', '2016/01/29 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/084690e9-83d5-4c37-a149-17e4c80cef52.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2ded465-35dc-4cb5-86e2-df8a748fb027', '23dfccaf-2296-4668-a183-e03ba63787d0', 4, '60679637', '第六遺跡 －箱庭－', '未だ謎に包まれている遺跡の調査に向かうことになったルクスたち。他国からの留学生であるため、遺跡の調査など危険を伴う行動を制限されているクルルシファーも同行を志願し、調査隊に加わることになる。そして調査が行われる当日、クルルシファーの許嫁であるバルゼリッドが手助けと称して、協力を申し出るのだが…。', '2016/02/05 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b20e1607-c279-4d63-aeae-4585baa54eca.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38a8dfc2-d428-4452-b64b-b4d28b1e3df0', '23dfccaf-2296-4668-a183-e03ba63787d0', 5, '60682727', '少女の願い', '全てはバルゼリッドが仕組んだことだった。クルルシファーの出生の秘密を知るバルゼリッドは、その力を手に入れるためにクルルシファーに近づいていた。バルゼリッドの不可思議な力の前に為す術なくやられてしまうクルルシファー。絶体絶命かと思われたそのとき、月夜の空に漆黒の神装機竜が姿を現す。', '2016/02/12 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f532e0a2-5e10-45eb-a9f3-860a3a727646.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a410fc54-4c16-49ef-976f-e7e1309ed29e', '23dfccaf-2296-4668-a183-e03ba63787d0', 6, '60685974', '最強の帰還', '学園の敷地内に不審者が出るという話があり、シャリスたちに敷地内の見回りに協力して欲しいと頼まれたルクス。快諾して学園内を歩き回るルクスだったが、突如不審者が現れ、ナイフを突きつけてきた。そのとき、助けに現れた少女こそ、四大貴族の令嬢、学園最強と呼ばれる騎士団長、セリスティア･ラルグリスだった。', '2016/02/19 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fd7c6ac4-14a7-4252-b136-10d758e082ff.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01970b47-ca8d-42aa-9cd1-fc9ed49d4066', '23dfccaf-2296-4668-a183-e03ba63787d0', 7, '60688774', '少女の真実', '強化合宿のため島へとやってきたルクスたち。水着に着替え、海辺で羽を伸ばす学園の少女たち。しかし、学園に残り、ラグナレク討伐に同行するため、この島でルクスはセリスと勝負をすることになっていた。一方、ルノとしてセリスと仲良くなったルクスは、二人でデートをすることに!? その陰では、不審者が再び暗躍していた…。', '2016/02/26 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/eced86f4-730f-48a2-b21c-d44d3c87889e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfd28772-b6f8-43e6-9ebe-66a83d318daa', '23dfccaf-2296-4668-a183-e03ba63787d0', 8, '60692868', '幻神獣の目覚め', '突如として姿を表した巨大な船の形をした遺跡。合宿の本当の目的はこの遺跡《方舟》を調査することだった。4つのチームに分かれ、遺跡の調査を行うルクスたちは、瓦礫の下で横たわる一人の少女を見つける。《方舟》の管理者を名乗る少女が言うには、《方舟》の大半の機能が停止しているため復旧の必要があるのだが…。', '2016/03/04 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5329a042-cd81-464a-a506-cfa06765368d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb452d2b-ae87-4634-aeb4-ba25007c2c48', '23dfccaf-2296-4668-a183-e03ba63787d0', 9, '60696912', '約束', 'レリィから語られるフィルフィに隠された真実。ルクスはフィルフィに残された時間があと僅かであることを知る。幼い頃、絶望の淵にいた自分を必死で救ってくれたフィルフィの姿を思い出すルクス。あのときフィルフィがいてくれたから自分は戦うことができた。ルクスは今度こそ何があっても必ず彼女を救ってみせると決意し、遺跡へと向かう。', '2016/03/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/90224fa8-52bb-40f4-93f6-003930cac69c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36ecf185-273d-4432-bc3b-9eb88c4509f1', '23dfccaf-2296-4668-a183-e03ba63787d0', 10, '60700736', '少女たちの報酬', '間近に迫ったアティスマータ新王国の建国記念祭。数日間にわたって行われる国を挙げての祭典をルクスと過ごすため、リーシャたちはこぞってデートを申し込む。しかしたまった雑用の依頼もあり、自由な時間が限られているルクス。そこでレリィの提案もあり、ルクスは一緒にデートに行く女の子を3人選ぶことになるのだが…。', '2016/03/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/55ad600d-64df-431c-bb96-388904bfba33.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40da6852-58b0-493d-aeec-a52fa85b3d2d', '23dfccaf-2296-4668-a183-e03ba63787d0', 11, '60701966', '帝国の凶刃', 'ナルフ宰相から聞かされる帝都奪還計画という名の陰謀。建国記念祭で行われる全竜戦の終了と同時にその計画は決行されるという。計画を阻止する協力として、王都を襲撃するために潜んでいるという100体に及ぶアビスを引き付ける囮役を命令されるルクス。さらには全竜戦で優勝することも要求されるのだが…。', '2016/03/25 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c7b38ce3-bace-4945-8e74-684633559e83.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5d0c747-3024-4324-bd54-12e2e833430e', '23dfccaf-2296-4668-a183-e03ba63787d0', 12, '60706570', '少女の本懐', '【シーズン1 最終話】全ては用意周到に仕組まれた罠だった。リーシャは敵の策略によって捕らえられてしまい、ルクスはラグリード率いる反乱軍とアビスの群れに追われ防戦一方。そしてクロスフィードには巨大な影が迫っていた。まさに絶体絶命の危機を迎えたアティスマータ新王国を守るため、決死の戦いが始まる。', '2016/04/01 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d0862076-1c7c-4008-9a49-7b98d78de392.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4fab16dc-7733-4378-a50e-e78413e651f0', '最推しの義兄を愛でるため、長生きします！', '', 'hulu', 'ill-live-a-long-life-to-dote-on-my-favorite-stepbrother', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b8ca3ab-5d59-4dfd-8685-ec3b759e21d4.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'RELEASING', NULL, 199446, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('146ec985-a886-4ab3-a488-48fd96a8d1a3', '4fab16dc-7733-4378-a50e-e78413e651f0', 'hulu-ill-live-a-long-life-to-dote-on-my-favorite-stepbrother-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb79acf4-0573-4cba-8bde-a8d72587aa57.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fba6203-5cbc-432b-b5dd-d727ed6111a9', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 1, '100247117', '最推しの義兄に!', '前世の記憶を持つアルバは、再婚した母親とともに公爵家へ。そこで義兄となったのは、前世でプレイした乙女ゲームの最推しキャラクター･オルシスだった。推しと家族になれたと喜ぶアルバだが、同時に思い出す。ゲームでは、義父に溺愛される自分のせいで、オルシスが悲劇に陥るのだった。', '2026/01/06 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb79acf4-0573-4cba-8bde-a8d72587aa57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('207f399e-eb6c-49d0-9829-ae4cd7a9ea6e', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 2, '100247118', 'ラオネン病!', 'オルシスとの出会いに動揺したアルバは、突如発作で倒れてしまう。この世界の人間は魔力を持って生まれる。しかしアルバは自身の魔力の放出を自分で止められない“ラオネン病”を患っていたのだ。意識が戻ると、義父ハルスとオルシスから温かい言葉をかけられ、家族として迎え入れられたことを実感する。', '2026/01/13 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/204f388f-4cde-42fb-8b94-1bee270bcbb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8ca3ab0-f504-44cb-863b-c136f79eeb66', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 3, '100247119', '兄様のかわいいがすぎる!', 'オルシスとハルスの関係が冷え切っていたことを回避するため、アルバはどうにか二人の関係をよくしようと奮闘する。そのアルバのまっすぐな言動により、ハルスはオルシスとの関係を見直していき――。', '2026/01/20 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51edacfd-52e8-47a5-9679-66bfbaabfcc9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('235f9581-21bb-47cb-8c45-1c3e93d5c2a3', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 4, '100247120', '兄様の誕生パーティ!', 'ハルスとオルシスの関係が良くなり、このまま順調にいくと思っていた矢先、オルシスの誕生パーティーにて、オルシスの祖父母と出会う。アルバの事をよく思っていない祖父母に厳しく当たられ、アルバはまた発作を起こしてしまい――!?', '2026/01/27 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d772b7ef-9eca-4f9d-ac58-56945317b618.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e7122bc-a905-453d-a1da-2d9b389b06dc', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 5, '100247121', 'ラオネン病の特効薬!', '意識が戻ったアルバは、兄の将来を近くで見るために生きることを決意する。前世の記憶を頼りに、ラオネン病の特効薬になる薬草を求めて、メノウの森に一人で転移しようとしていた。しかし、その様子をオルシスに見つかってしまう。', '2026/02/03 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92c0db60-47aa-40a6-ae9f-c97650af2610.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8f74979-0ef3-45c5-9de6-6de101a1a3b3', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 6, '100247122', '兄様と森を探検!', '薬草を求め「メノウの森」へ向かうアルバに、同行を申し出るオルシス。しかし道に迷ってしまい、森をさまようことに。そこへ、オルシスの魔法で知らせを受けたハルスが現れるが――。', '2026/02/10 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/661c422d-3b05-4a41-8af1-d21f2629491b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81db0c90-eca4-4c5c-a8a8-9fc6837c3276', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 7, '100247123', '義父の魔法がすごすぎる!', 'ハルスを説得したアルバは、彼と共に特効薬の薬草採取へ向かう。しかし、薬草が入手できる場所は高い崖の中腹で、アルバは気後れしてしまう。どうにか降りる方法を考えていると、ハルスから驚きの提案を聞くことになり…。', '2026/02/17 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c75a769-1671-4c74-95ae-849ab8329d64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebbe3067-a64e-4232-a98f-086ebfbbe041', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 8, '100247124', '薬草みつけた!', '無事に洞窟まで降りられた一行。その先である植物を見つけ出す。ただ、その用法までは分からないため、一度帰宅して様子を見ることに。自宅に戻ると予想だにもしないイベントが発生する。', '2026/02/24 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbd5d482-eb97-4915-8278-9aca7ea97531.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf0af002-640b-43d3-aa34-0c17b13b3b42', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 9, '100247125', '父様と兄様!', '一人ハルスの自室に向かったオルシスは、アルバの不可解な言動について相談する。しかし、ハルスから告げられた驚くべき可能性に動揺を隠せない。その数日後、自宅の庭に立っていたアルバの前に、ゲームではありえない光景が広がる。', '2026/03/03 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c96d2c0-84a0-4de8-b2b9-7f84cb2011b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10b952d1-a0b1-4e18-8679-a78244d8ca18', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 10, '100247126', '新たな攻略対象との出会い!', '自宅の庭にできた不思議な植物園に入ったアルバは、洞窟で見つけたものと同じ植物を発見する。その植物には、魔力を蓄える性質があることが判明し、ハルスは特性を調べるため、友人のヴァルト侯爵と、その息子であり乙女ゲームの攻略対象であるブルーノを屋敷に招くのだった。', '2026/03/10 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25d42ba2-8b03-4b8d-8390-fedad34399a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('414c07e2-93b0-4423-8cb9-019117fecb07', '146ec985-a886-4ab3-a488-48fd96a8d1a3', 11, '100247127', 'レガーレの研究!', 'アルバとオルシスの仲の良さにとても困惑するブルーノ。そんな中、アルバ達が発見した植物の名前が決まり、研究にも進展があった。そんなことを話していると、ブルーノがあることに気づく。', '2026/03/17 22:00:00', 240, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4ed0b04-4fcf-426e-8b94-1b8bc55e9831.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('22e6daee-aa2f-455e-9ca5-b491783f9de5', '妻、小学生になる。', '', 'hulu', 'tsumasho', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5292de58-c40f-4bd0-9426-5a31cbefb031.png?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 162785, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('280d9b96-3565-48d7-8c95-7a6f1ffefab8', '22e6daee-aa2f-455e-9ca5-b491783f9de5', 'hulu-tsumasho-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7a9ecc3-6df1-4d04-b44b-ab15500f7a50.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22940ae8-bb7f-496f-b135-1f0aaa46c1ab', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 1, '100199188', '家族、ふたたび。', '新島圭介は恋をした。相手は取引先の会社員、古賀貴恵。貴恵をデートに誘い、告白し、結婚して、娘の麻衣が生まれた。しかし、幸せな日々は貴恵の死によって終わりを告げる。最愛の妻を亡くし、生きる気力を失う圭介。それから十年。妻の死から立ち直れずにいる圭介の前に、ひとりの小学生が現れる。「私は新島貴恵! あんたの妻、麻衣の母親!」彼女は貴恵の生まれ変わりだと言うが……?', '2024/10/06 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7a9ecc3-6df1-4d04-b44b-ab15500f7a50.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c0b85cc-8854-43a9-88e3-e4a4a6ea2824', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 2, '100199189', 'だって、いまは。', '貴恵が小学生の姿ながらも帰ってきてくれたことを喜ぶ圭介と麻衣。十年ぶりに一緒に出かけ、その奇跡に圭介は感涙してしまい、貴恵と麻衣に呆れられる。共に過ごせなかった時間を取り戻そうと圭介ははりきる。一方で白石万理華として小学四年生の生活をおくる貴恵は人知れず悩みを抱えていた……。', '2024/10/13 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce2c423f-2b89-426d-b66c-2c58d1a3b893.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24c5f1df-35ad-4cc4-a054-b3e502556de9', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 3, '100199190', '一歩、ふみだして。', '転職活動に成功し、新しい仕事をはじめる麻衣。だが、はじめての客先で相手とコミュニケーションがうまく取れず、落ち込んでしまう。貴恵は麻衣を励まし、花火大会へ誘う。同じ頃、会社帰りの圭介は花火大会に立ち寄っていた。そこで会った会社の後輩社員、守屋と一緒に花火を見ることになって……。', '2024/10/20 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb7ea9a6-4fe4-4ccc-b1ea-2fffa5ecfa40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8f4b3ec-b00f-4fa8-b9ef-15ad0935931f', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 4, '100199191', 'ふたりは、語らう。', '麻衣は同じ失敗をしないようにと、客先の相手･愛川蓮司に真心を持って話しかける。その想いは通じ、蓮司は己の過去を話すなどして少しずつ心の距離を縮めていく。そして偶然再会してしまった貴恵と守屋も、友人としての距離を縮めていて……。', '2024/10/27 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2cf9966-d466-4034-b51e-08dc0bab4fc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dedc7a44-c9fc-4ad2-9010-0fc9aab5ace4', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 5, '100199192', '母と、家族。', '貴恵は、母･千嘉の再婚のために引っ越すことになる。そのせいで圭介たちと離れてしまうことを心配する貴恵だが、圭介たちは「一生会えなくなるわけではない」と心配する様子はない。育児放棄をする千嘉ではあるが、彼女の幸せも願う貴恵は再婚を前向きにとらえ、千嘉の再婚相手とも仲良くしたいと思う。', '2024/11/03 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21dcbd1b-49ef-46a9-9e42-01ec6fa2743b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('825a98eb-b428-41a5-803b-8d901865feba', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 6, '100199193', '想い、きしんで。', '娘である万理華 (貴恵) が圭介たちと仲よさげにしているところを目撃した千嘉は、貴恵に詰め寄る。真実を話せない貴恵は黙るしかなく、それはますます千嘉を怒らせる。千嘉の激昂を目撃した圭介は、貴恵の複雑な家庭環境をはじめて知る。たとえ妻でも、いまは無関係の人間同士であることを痛感する圭介だが、貴恵を救いたいと願う。血のつながりよりも大切なものがあると信じて。', '2024/11/10 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f11659ed-52fc-43dc-8af2-3797d3ba23be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24707e50-3f71-4d18-878d-464429661e39', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 7, '100199194', 'しあわせの、兆し。', '貴恵と千嘉の問題はひとまずの解決をみせ、ほっとする圭介たち。そんなときに、麻衣のもとを蓮司がおとずれる。蓮司が麻衣の恋人であると知った圭介は衝撃をうけ、動揺する。それは守屋に心配されるほどのダメージだったが、そんなときに何気なく言った言葉が守屋へひとつのきっかけを与える。', '2024/11/17 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b5759bd-9eaa-44f5-a559-2675149245e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e384b4d6-cf4b-4113-955b-2be85c04116e', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 8, '100199195', 'あなた、誰?', '貴恵だった頃の記憶をなくしてしまった万理華。「知らない大人」として自分たちを警戒する万理華に困惑する圭介と麻衣。千嘉も戸惑いながらも、万理華を支えようと奮闘する。ここ一年ほどの記憶がない万理華は千嘉の変化に驚き戸惑うが、安らぎを感じはじめる。ひとつの家族の幸せが消え、もうひとつの家族のあらたな日常が戻ってきたのだった。', '2024/11/24 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba2d05f6-8320-45f3-9996-4635fe344f2e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9f2ad0d-014a-4e35-8e7c-66b7758a1a2d', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 9, '100199196', '伝えたい、この気持ち。', '貴恵は記憶を取り戻し、同時に自分が生まれ変わったわけではないことを知る。貴恵は千嘉に自分のことは『万理華』と呼んで欲しいと頼む。いつか万理華が戻ってきたときに困らないように、と。その話を聞いた圭介も、貴恵が生まれ変わりではないことを察する。だがそれは、圭介にとっては受け入れがたいものだった。', '2024/12/01 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90f696e8-bb31-485c-bad4-9c02877ab21b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6960be97-286e-46b8-8e2f-d1fc5863dd42', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 10, '100199197', 'それが、願いなら。', '守屋から告白された圭介は貴恵のことを打ち明け、ふがいない自分は守屋に想ってもらうほどの人物ではないと語る。貴恵のために貴恵と別れることを願う圭介に、守屋の心は乱れる。かたや貴恵は、麻衣と蓮司と共に結婚式場の下見に来ていた。美しい教会を見学する三人。貴恵はおもいきって麻衣と蓮司に、あるお願いをする……。', '2024/12/08 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f35f9391-f65c-4f88-83e6-2c25e5cb7945.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef1ab030-fb5a-4eac-ae04-e8162c98c159', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 11, '100199198', 'だれよりも、愛してる。', '圭介は麻衣に「守屋君と結婚する」と告げる。混乱する麻衣。圭介は貴恵は生まれ変わりではなく、万理華に憑依しているだけなので、その体を返さなくてはいけないと麻衣を説得しようとするが、混乱する麻衣は受け入れられず、その場から逃げ出す。そして、夜の公園で貴恵と話し合い……。', '2024/12/15 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/edbc6301-4ed1-454c-b127-4a43ac686150.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3761e677-0ab7-40cf-bc2c-78bf7601516e', '280d9b96-3565-48d7-8c95-7a6f1ffefab8', 12, '100199199', 'その一瞬を、', '【シーズン1 最終話】圭介が指定する場所に、麻衣と貴恵は訪れる。そこは奇しくも圭介がはじめて貴恵のお弁当を食べた公園だった。懐かしく思う貴恵。麻衣と観覧車に乗り、別れの予感に貴恵は麻衣へ感謝の言葉を伝える。そして貴恵は、圭介の決断を目撃する。', '2024/12/22 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b665ac0b-5a55-417c-802c-c251f15cb337.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('28449298-4487-4ba5-b9c0-4ad7fafb566c', '彩雲国物語', '', 'hulu', 'colourcloud-palace', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe61a917-7c15-4ebe-9fb9-fd84940e197b.jpg?w=331&h=447&p=t', 'hulu', 2006, 1, 1, 'FINISHED', NULL, 957, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1b6a7734-ec2e-4a7b-84e0-8524140efcdb', '28449298-4487-4ba5-b9c0-4ad7fafb566c', 'hulu-colourcloud-palace-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82056105-0488-4e1d-8a1f-1ddd19304b6d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cfc7494-b45f-4fd4-8ba7-c22312d89ccd', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 1, '100029855', 'うまい話には裏がある', '紅秀麗は、彩雲国の王都･貴陽に暮らす、由緒正しい紅家のお嬢さま。だけど家計は火の車で、賃仕事に精を出す日々。ある日、朝廷のお偉方、霄太師が頼みがあるとやってきた。高額報酬に目がくらみ、二つ返事で引き受けた秀麗だったが、頼みというのは、ダメ王様と噂される彩雲国の新王、紫劉輝の妃になってくれ、というものだった…。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82056105-0488-4e1d-8a1f-1ddd19304b6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7acc134c-7706-4ea5-81f7-fce524464710', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 2, '100029856', '井の中の蛙大海を知らず', '新王･劉輝の教育係として、妃の身分で後宮に入った秀麗。劉輝と過ごす日々の中で、噂ほどのダメ王様ではない、むしろ、いい王様になるかもしれないと思い始める。秀麗は、劉輝が街へ出たことがないと知り、庶民の生活の現状を見せようと、おしのびで、劉輝を下街へと連れ出すが…。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15c6e1e0-da99-42d4-9e8e-a0cb9a1b31bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcedd660-d752-461c-a2cf-6234c9ff49da', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 3, '100029857', '能ある鷹は爪を隠す', '秀麗が後宮に上がって、ひと月。彩雲国の新王、劉輝は秀麗との約束を守り、次第に政事に関わるようになっていた。ある夜、バラの花を手にした劉輝が、突然、後宮の秀麗の元を訪ねてくる。手を傷だらけにしてバラを摘んできた劉輝に、秀麗はバラ姫の話を聞かせる。そんな折、宮殿で彩雲国の高官が集まる酒宴で事件が起きる。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d34d3868-946c-4d27-a71c-c1a678f1c037.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('febda381-bc81-4751-9ed3-690e85fe960d', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 4, '100029858', 'それは宝の持ち腐れ', '劉輝が秀麗の危機を救い、実は、劉輝はダメ王様のフリをしていただけだと知った秀麗は、怒りのあまり後宮を辞すと告げるが、霄太師らに丸め込まれる。憤る秀麗は、父の邵可から、劉輝の不幸な幼年時代の話を聞く。宮中では武芸大会が催されることになり、劉輝をはじめ、楸瑛や静蘭が剣の腕を競う。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92a07285-0333-464f-8e77-fcecaf915b13.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3d749025-159c-44e0-9081-10d1a3550a90', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 5, '100029859', '努力に勝る天才なし', '秀麗の身の回りから次々と発見される毒に対処し、その出所に目星をつける劉輝ら。そんなことは全く知らない秀麗は、藍龍蓮と名乗る、奇妙な青年と出会う。その青年は、藍将軍の弟だった。自由気まま、傍若無人に振る舞う変わり者の龍蓮に、周囲は振り回されてしまう。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be03b5f8-9b3c-49f4-b71d-64499350a787.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30b567b3-b612-4dde-9808-6525d01925e3', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 6, '100029860', '画竜点睛を欠く', '日に日に王らしくなっていく劉輝に、満足げな霄太師ら。秀麗は、劉輝に王としての自覚を持たせるという、自分の役目が終わりに近いことを察し、寂しくなる。何だかんだ言っても、後宮で過ごす日々は楽しかったからだ。側付きの香鈴も、秀麗の寂しさを感じ、元気づけようとするが、その矢先、秀麗が何者かに拉致されてしまう。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/307dec46-3c31-4c76-9ae7-6cc09682d2ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b6cbcee-33a2-4cb1-8800-7c899b86e243', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 7, '100029861', 'よく泳ぐ者は溺れる', '楸瑛が黒幕の元にたどり着いた時、既にそこに黒幕の姿はなかった。秀麗は劉輝の活躍で、窮地を脱するが、体内に残っていた毒により、倒れてしまう。彩雲国一の名医でも解毒不可能な毒のため、秀麗の命が危ない。何とか秀麗を救いたいと必死の劉輝。そんな劉輝に、秀麗を助けられる解毒剤がある、と告げたのは意外な人物だった…。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03baaead-b18c-49d5-9372-683e457fd13d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb6788fe-dd91-4abe-86bc-42a833afd5c4', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 8, '100029862', '猫の手も借りたい', '秀麗が後宮を辞してひと月、彩雲国は、記録的な猛暑に襲われていた。あまりの暑さに、体調を崩す官吏たちが続出し、朝廷は人手不足に陥っていた。そんな最中の朝議で、劉輝は、国試の女人受験を導入したい、と発言し、波紋を呼ぶ。一方、秀麗は、邸の門前に行き倒れていた、髭もじゃの男 (浪燕青) を拾っていた…。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f36d4291-159e-4c61-a6bc-3d5e896723fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d3ef89d-bddd-41d8-9f3e-95cd059150f0', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 9, '100029863', '千里の道も一歩から', '猛暑による人手不足の朝廷で、秀麗は、ひと月だけ、財政を預かる戸部の雑用係として働くことになった。女性は朝廷に入れないため、男の子の格好をして、懸命に働く秀麗。変人と呼ばれる仮面の男、戸部尚書の黄奇人も、そんな秀麗の働きに一目おいて…。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2fd37a8f-c3c2-4bc3-8674-c68fbb04bcf8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5072e2c1-9545-48cf-97c8-c808890f47f1', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 10, '100029864', '待てば海路の日和あり', '劉輝が懸命に取り組んでいた、「国試女人受験制」の草案作りは、ようやく完成した。草案を仕上げるまではと、秀麗に会うのを我慢していた劉輝は、これで秀麗に会えると喜ぶ。世間知らずの劉輝は、わざわざ、「夜這い御免状」をしたためて、秀麗の父、邵可に送るが、そんな折も折、騒動が勃発する。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4cac417-cab8-4fc2-b310-25d9c7965492.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff40e7e1-f78b-4a47-9d42-81914a9928a7', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 11, '100029865', '恋の病に薬なし', '国試受験のために課せられた適性試験が終わり、結果が発表される前のこと。秀麗は、いたずらをした寺子屋の生徒、柳晋を叱ろうと追いかけているうちに、冬の川に落ち、風邪をひいてしまう。秀麗が寝込んでいると知り、次々と訪れる見舞い客。楸瑛、絳攸はもちろん、秀麗がまだその存在を知らぬ、叔父の紅黎深、さらには、仮面の男･黄奇人まで…。そんな中、柳晋が行方不明になる。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e12dfe6-c485-4c39-980e-0a8b691fe317.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6a91821-2efd-42d3-bad1-21d5d1fb33ff', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 12, '100029866', '逃げるが勝ち', '冬の彩雲国、近づく国試に、王都･貴陽はたくさんの人で賑わっていた。無事、適性試験に及第した秀麗は、国試に集中するため、賃仕事をくれた雇い主たちにいとまを告げに行く。花街一の妓楼、姮娥楼では、秀麗が姉のように慕う芸妓の胡蝶が、秀麗との別れを惜しむ。胡蝶は、そこで、珍客だと言って、どう見ても十二、三歳にしか見えない少年を秀麗に引き合わせる。貴陽に着いたばかりだというその少年は、杜影月と名乗った。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de107ef1-b28c-4718-8abe-8f3d052617ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cc0dfdc-b74f-49ce-9bff-f734b6e77853', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 13, '100029867', '瓢箪から駒', '訳もわからぬうちに、青巾党と名乗るごろつきに追われるはめになった秀麗、影月、静蘭は、姮娥楼に逃げ込む。そこには、なぜか、彩雲国の若き国王、劉輝の姿が…。そこへ秀麗の幼なじみ、三太が、青巾党が姮娥楼を根城にしようと襲撃してくる、との情報をもたらす。そんな中、秀麗は、意外な言動をとる胡蝶に、目を丸くして驚く。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f607d7a0-0af4-4e65-9c0f-5fbfa5bee32f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba3d575d-9a34-4b7c-a6cb-7a2b936b0b2d', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 14, '100029868', '石の上にも三年', '晴れて国試に合格し、彩雲国史上初の女性官吏となった秀麗だが、急によそよそしくなった街の人たちの態度に、秀麗は傷つく。最年少の十三歳で首席合格した影月と、女性でしかも三位で合格した秀麗を面白く思わない者が大勢いた。新人官吏の研修指導官である魯官吏も、秀麗と影月に目をつけているのか、二人に与えられた仕事は、思わず耳を疑いたくなるようなものだった。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d13f594e-1be4-4d88-9494-b3af3ae55a96.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3de9473c-a9a8-4b49-b479-2f6f63a29484', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 15, '100029869', '親の心子知らず', '新人官吏の研修が続いている。秀麗の叔父で、後見人の紅黎深は、辛い目にあっている秀麗を見るのが辛い。そこで、彩雲国の王、劉輝に秀麗を守るようにと直訴し、にらみをきかせる。黎深の養子である李絳攸は、そんな秀麗への態度とは異なり、自分に厳しく接する黎深に、自分は黎深から愛されていないのではないかと深く悩む。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50b5058f-b4db-4af1-821c-843c99071e5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab445cef-08cc-4437-8fbc-1bba5316c611', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 16, '100029870', '渡る世間に鬼はない', '秀麗と影月は、相変わらず、厠掃除とくつ磨き、大量の書類整理と計算に追われ、さらには二人を面白く思わない古株の官吏たちから、様々な嫌がらせを受ける。しかし、ひどい仕打ちにもめげずに頑張る二人に、最初は冷たい目で見ていた同期の新人官吏たちも、少しずつ考えを改めるようになっていく。そんな折、秀麗の国試及第に不正があったらしいとの噂が流れる。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8efff34-9e28-44e9-b2ab-1ee8d32580e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f602301-6bb2-4c40-9972-007f206b3285', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 17, '100029871', '藪をつついて蛇を出す', '休養日、胡蝶に招かれ、姮娥楼にやってきた秀麗と影月は、突然、ゴロツキたちに取り囲まれ、監禁されてしまう。胡蝶の裏切りにぼう然となる秀麗。その頃、秀麗の父、邵可の元には、紅本家から弟の玖琅が訪れていた。そこへ、秀麗の後見人である黎深が、秀麗の国試及第に関する不正行為のかどで拘束された、との報が入る。そして静蘭は秀麗を守るため、ある覚悟を決める。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3168d10-e51f-4f56-bf67-1550ac6099ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2cd28d6-98d8-40a1-aab0-bd1258dfe6c5', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 18, '100029872', '頭隠して尻隠さず', '彩雲国初の女性官吏となった秀麗だが、彼女の国試及第に不正の疑いがあるとして、その真偽をはかるべく、査問会が開かれることとなった。王宮では、朝議が開かれ、誰が紅吏部尚書を捕縛したかの追及が始まっていた。そして、一人の男が黒幕として浮かび上がってくる。それは意外な人物だった…。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e0d6744-9aba-44bd-ae98-c89e1f8c232c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('856197bf-2694-4426-b8f9-d484b0b08afa', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 19, '100029873', 'かわいい娘には旅をさせよ', '再び茶州からやってきた浪燕青は、茶州の現状を劉輝らに報告する。秀麗、影月は、新人官吏の配属を決める任命式を、数日後に控えていた。劉輝は、秀麗の配属先について最後まで悩むが、ついに決断する。それが、彩雲国の王としての使命だからだ。任命式当日、秀麗と影月に、驚くべき配属先が告げられた。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1fc53877-a968-498c-b3b9-e112fd893e26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff17bfda-191c-41c0-a689-163680c01c1e', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 20, '100029874', '枯れ木に花咲く', '彩雲国史上初の女性官吏、紅秀麗と最年少官吏の杜影月は、二人組の州牧として茶州に赴任することになった。燕青は若き州牧たちの補佐として、静蘭は二人を守る武官として、ともに茶州へ赴くことになっていた。出立前、秀麗の母の墓参りに出かけた静蘭は、心の奥底に封印してきた自身の過去を振り返る。十五年前、第二公子、紫清苑として王宮で過ごした日々、病弱だった母のこと、そして、異母兄弟の誰よりも抜きんでて優秀だったがために、その身に降りかかった悲劇のことを…。', '2019/02/21 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/501d6bc3-8cc3-444b-9d77-4eef4308c14e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24947696-246c-4217-be87-829ab19822a9', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 21, '100029875', '君子危うきに近寄らず', '秀麗たちが紫州を離れる日がいよいよ二日後に迫っていた。そんな折、絳攸は秀麗に、一年前に起きた秀麗拉致事件の真相を明かす。後宮に劉輝の妃として入った秀麗を、誰が何のためにさらったのか、そして、その企てを手助けしようと、ひそかに毒を盛ったのは誰だったのか…。真実を知り衝撃を受ける秀麗だったが、そこへぷらりと、藍龍蓮がやってきて…。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dea4598f-13ce-4a25-8319-4f23577aec24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80a372d3-94ed-4786-ae06-0f0325c7eaa2', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 22, '100029876', '命あっての物種', '茶州へと出立する秀麗、影月。燕青は若い州牧たちの補佐として、静蘭は二人を守る武官として、そして秀麗に同道を許された香鈴もともに旅立った。州牧として赴任するためには、三ヶ月以内に茶州の州都･琥璉にたどり着かなければならない。それを過ぎても着任できない場合は、任務放棄と見なされ、自動的に州牧を解任されるのである。赴任先の茶州はひどく不穏な状態にあった。新州牧たちを狙い、茶家の手の者たちが暗躍する。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e8547dc-efe3-493b-b40c-1c29562da004.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c11cf311-3a74-4d46-b605-8d93e0bd945a', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 23, '100029877', '旅は道連れ世は情け', 'いよいよ秀麗たちが茶州へと足を踏み入れようとしていた矢先、関所の官兵によって、静蘭、燕青、影月、香鈴が捕らえられ、茶州の入口にある町、崔里に連行されてしまう。燕青の機転により、一人難を逃れた秀麗は、再会を約束した地、商都･金華を目指すことにする。どうやったら無事に金華までたどり着けるか思案する秀麗の前に、あやしいほどに美しい一人の青年が現れる。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8fb7fe8b-5dcb-48c4-963f-9d3665c0746d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f146be9-2ffa-49c4-9f90-c3f9631967f3', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 24, '100029878', '寝耳に水', '静蘭、燕青、影月、そして秀麗の身代わりとなった香鈴を捕らえたのは、茶家当主の座を狙う茶仲障の孫、草洵だった。一方、琳千夜と名乗る商人の侍女として、金華に向かうことになった秀麗だったが、一向に崔里を出発する様子がない千夜にやきもきする。そんな中、地下牢より静蘭と燕青が脱走する。手助けしたのは、草洵の末の弟、克洵だった。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a254a7a9-97f6-4746-8522-2b5d5b5fc0f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc78e7eb-d7e0-4bbd-8b0a-c82e63796119', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 25, '100029879', '他人のそら似', '秀麗が琳千夜について崔里を出て20日あまり、影月、香鈴は克洵と、静蘭は燕青と、皆それぞれに金華を目指していた。途上、静蘭と燕青は、過去に因縁のあった殺刃賊の新頭領、瞑祥と対峙する。秀麗は、茶家次男の朔洵と、新州牧である自分の結婚話が進んでいると千夜に聞かされ驚く。様々な思惑が絡む中、秀麗はついに、金華にたどり着く。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad59d3cc-e19b-47d7-b537-9876cc696315.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9bad5de8-84a8-42a6-968a-a046e6a1650c', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 26, '100029880', '闇夜の烏', '静蘭たちとの再会を約束した街、金華にたどり着いた秀麗は、驚くべき話を聞かされる。琳家の人間は、殺刃賊に全員殺されたというのだ。では、金華まで一緒にきた琳千夜と名乗る青年は一体誰なのか…。一方、草洵は、香鈴が秀麗の身代わりだったことを知り、激怒する。草洵たちに金華城へ連行された影月と香鈴は、大勢の殺刃賊に囲まれてしまう。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3cb512ef-912c-4111-a0de-0613208f8cff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb2563d0-cb94-43e9-8e13-e2c486875c25', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 27, '100029881', '花は折りたし梢は高し', '金華で、静蘭、燕青、影月、香鈴と再会を果たした秀麗だが、琳千夜の真の姿を知った衝撃からは、立ち直れずにいた。しかし、秀麗には、茶家の横暴で荒廃した茶州の治安を建て直すという、新州牧としての務めが待っていた。秀麗は、全商連の金華特区長、柴彰に協力を要請する。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17576b5f-2de9-4610-aa43-00d416401279.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb8036a7-22f9-4941-a946-ff38ece282a8', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 28, '100029882', '案ずるより産むが易し', '金華にのさばっていた殺刃賊を一掃し、事件の事後処理に忙殺される秀麗たちの前に、州都･琥璉からきたという、由准と名乗る官吏が現れる。由准は燕青の知り合いらしく、秀麗たちを手伝い、テキパキと事案を片づけていく。そんな中、茶家の三男、克洵は、とある決意を胸に秘め、一人、琥璉へ向かった。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02b66e40-d836-4e67-abfe-8f5616eed7f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a58e9c55-3a03-410d-ba0e-f2ff4c4981ba', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 29, '100029883', '一日千秋の思い', '茶州州都･琥璉が、茶家の手により全面封鎖された。知らせを受けた秀麗たちは、琥璉に乗り込むべく、金華を出立することになった。一方、秀麗たちの知らぬところで、金華を目指し、寝る間も惜しんで馬を走らせている一行がいた。何とそれは、彩雲国国王、紫劉輝、そして、かつて劉輝から「信頼の証」である「花」を贈られた楸瑛と絳攸だった。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3679fecc-8bcd-4c51-8dbb-b741b567ec11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('948e0e75-690a-4652-959e-1b91c5212a68', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 30, '100029884', '女は度胸', '秀麗たちは、完全に封鎖された茶州州都･琥璉を目前に、足止めを食らっていた。秀麗と影月が茶州州牧として着任するためには、何としてでも期限までに琥璉に入らなくてはならない。意を決して関所を突破した秀麗一行は柴彰の姉、柴凛の邸に身を寄せる。邸には柴凛からの置き手紙と、もう一通、茶朔洵からの、茶家当主選定式への招待状が残されていた。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/422f8589-2b81-4f62-ac14-0a1524d33320.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a39a6b3-ba16-4fd6-bcfe-2684f43b5686', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 31, '100029885', '掃きだめに鶴', '茶家当主選定式の招待状を受け取った秀麗は、危険を承知で、茶朔洵の元へ飛び込んだ。劉輝から、茶州州牧任命の折、贈られた「つぼみ」のかんざしを取り返さなければならないからだ。一方、茶家三男、克洵は、祖父、仲障のたくらみを止めようとして、牢に放り込まれていた。その克洵を助けに、克洵を慕ういとこの春姫が琥璉へと向かっていた。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f2698be-46d5-430c-8971-a5e767961d37.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd2569ca-6ce6-4c87-a290-940b03c011c1', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 32, '100029886', '女にも二言なし', '朔洵から、茶家当主選定式の当日に「つぼみ」を返すと約束された秀麗は、茶本家の離れに留まり、行方がわからない克洵と春姫の祖母、英姫を捜していた。秀麗は、秘かに邸内を調べて回るが、広大で、迷路のように入り組んだ邸に、難儀していた。そんな中、秀麗は、茶仲障と対面する。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c98388df-7a70-4569-95a7-9d7b517ab51d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f1b7f49-58fd-4924-98f6-6255f64c08e0', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 33, '100029887', '覆水盆に返らず', '茶家当主選定式当日がやってきた。秀麗が茶家の屋敷にいるのも、今日が最後である。別れを惜しむ朔洵は、秀麗に、最後に、甘露茶を淹れてくれないかと頼むが…。日が暮れ、刻一刻と迫る選定式。静蘭は春姫と、影月は燕青と行動をともにし、それぞれの目的を持って動き出す。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e061745-73dd-46b8-97cb-8f1c0e312cb8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('505c8fdc-2229-4522-8d28-43ae4059f266', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 34, '100029888', '毒をもって毒を制す', '新月の闇の夜、運命の、茶家当主選定式が開かれる。克洵を捜す秀麗と春姫は、庭の社に足を踏み入れ、そこに広がる光景に目を丸くする。一方、影月、燕青は、選定式が行われる大堂に案内されるが、そこには不穏な空気が漂っていた。そして、静蘭は、干將を手に、朔洵の元へと駆けていた。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/871982ea-08be-41e5-bcdb-67b34bc33d3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29eee1f9-8935-4342-b950-e4418c918eaf', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 35, '100029889', '逢うは別れの始め', '茶家の主立った者たちは捕縛された。茶家当主には、克洵が就任した。克洵は、当主として、茶家の罪を一身に背負い、一生かけて償っていくという苦難の道を選択した。そしてそのころ、離れでは、静蘭と朔洵の、お互いの大切なものを賭けた、命がけの勝負が始まろうとしていた…。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b34346c-bfc0-4b00-b7a0-345aca78c439.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27b88e37-6a96-49a4-9f32-7eaa5c960e00', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 36, '100029890', '世はすべてこともなし', '茶家当主選定式は終わったが、秀麗には、茶州州牧としてやるべきことが残されていた。秀麗と影月は、茶家の手により琥璉城の牢獄塔に幽閉されている、鄭悠舜を救い出さなければならないのだ。琥璉城へと急ぐ二人の到着を前に、牢獄塔に火の手が上がった。一刻も早く悠舜を助けなくては、と焦る秀麗に、助けに行く必要はないと止めたのは、由官吏だった。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac43c9d5-1ce5-4e3b-9930-87c74b1f8754.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52ed4b19-64eb-44a2-8976-20ef20f8d841', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 37, '100029891', '雨は天から、涙は目から', '無事、茶州州牧に着任した秀麗と影月。秀麗は、朔洵のことを忘れるかのように、仕事に没頭していた。若き二人の新州牧たちは、百年先の茶州を見据えて、施策を練る。そんな中、秀麗は、新年の朝賀に出席するために、静蘭とともに、彩雲国の王都、貴陽に戻ることになるが、劉輝に会うには、気持ちの整理をつけなければならなかった。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52ced04f-6af0-43cf-bc3f-c530443106b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2293e87-18a7-4762-b1ed-9ca682a80536', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 38, '100029892', '今日の後に今日なし', '茶州州牧として新年の朝賀に出席するため、琥璉を出発する秀麗。悠舜と静蘭、茶家新当主として出席する克洵、茶州全商連支部長の柴凛も同道した。貴陽では、茶州発展のための案件を通すという、大仕事が待ち構えていた。秀麗の到着を待ちわびていた父、邵可だが、秀麗の顔を見るなり、すぐさま仕事に送り出す。もう一人、朝賀を前に、緊張で押しつぶされそうになっていた克洵の前には、龍蓮が現れて…。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbef707f-b479-4eec-9a7c-c85409109c7c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b51df6f-9d57-44ff-a6a4-9ac2dd3711ad', '1b6a7734-ec2e-4a7b-84e0-8524140efcdb', 39, '100029893', '縁は異なもの味なもの', '【シーズン1 最終話】秀麗たちが立案した、茶州発展のための計画は、受け入れられた。秀麗との再会を誰よりも切望していたはずの劉輝だったが、朝賀の後、劉輝は王としての職務に専念し、秀麗も計画遂行のための準備に追われていた。ようやく、秀麗が、得意の手料理を振る舞い、懐かしい人々との再会を喜び合った席にも、劉輝の姿はなかった…。', '2019/02/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03a816bf-ef75-4433-94f2-c1d4f3adc2fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('78fbed8f-7151-4dd6-8db5-043e62062fba', '彩雲国物語', '', 'hulu', 'colourcloud-palace-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/700c0a36-bfcf-4d6e-a90e-002753d2b035.jpg?w=331&h=447&p=t', 'hulu', 2006, 1, 1, 'FINISHED', NULL, 957, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c233877a-d27a-494e-9c77-b7821e222389', '78fbed8f-7151-4dd6-8db5-043e62062fba', 'hulu-colourcloud-palace-2-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27d1c308-882b-4f1b-9ba4-5a0c0e2864c4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d228faff-2aa0-44ea-b26b-7e677bca3133', 'c233877a-d27a-494e-9c77-b7821e222389', 1, '100030591', 'わが家に勝る所なし', '新年を迎えて華やぐ彩雲国王都貴陽。秀麗には、茶州州牧として朝賀に出席した後も、茶州を繁栄に導くための議案 (特産物がない茶州を、人材を育成することで「学究の都」として発展させようという案) の根回しをする、という大役が待っていた。そんな大仕事を前に、久しぶりに帰ったわが家で、てんやわんやの騒動が…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27d1c308-882b-4f1b-9ba4-5a0c0e2864c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('347c2596-b7df-47f5-9571-1b75b5b4329c', 'c233877a-d27a-494e-9c77-b7821e222389', 2, '100030592', '泣くも笑うも同じ一生', '茶州州都･琥璉に残った、もう一人の州牧、影月は、寝る間も惜しんで職務に励んでいた。そんなある夜、影月は、燕青と香鈴に、幼い頃、不幸な体験から自分を救ってくれた堂主様の話をする。一方、貴陽の秀麗は、議案を通すために必要な関係各所からの賛同を得るため、鄭悠舜や柴凛の協力を得ながら、奔走していた。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3dd9e8cf-6820-43b9-9acb-36397d3d85dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ea53157-c4e4-4f94-8135-e2e420f64f03', 'c233877a-d27a-494e-9c77-b7821e222389', 3, '100030593', '類は友を呼ぶ', '執務中、影月の香鈴に対する態度がよそよそしいことに気づいた燕青は、影月にその理由を問い詰める。そんな折、茶州虎林郡で、「邪仙教」と名乗る集団が勢力を広めているとの知らせが入る。その教祖の名が「千夜」だと知って、影月と燕青は、よからぬことが起きなければいいがと案じる。一方、貴陽の秀麗の元へ、ひょっこり、藍龍蓮がやってくる。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eca040b1-87c3-4b24-b8b8-2e0c9b48fb1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0bfe1fc-332d-475f-8890-4f19f8ee2cda', 'c233877a-d27a-494e-9c77-b7821e222389', 4, '100030594', '冬来りなば春遠からじ', '劉輝は、悠舜を呼び、宰相位に任じたいと告げる。悠舜も、茶州が落ち着いたら必ず戻り、王の側で仕えると約束する。その頃、秀麗の縁談話で邵可を訪ねた玖琅は、紅家にとって一番いい縁談は、秀麗と絳攸の結婚だと絳攸に告げたことを認める。一方、茶州の影月たちの元に、石榮村で発生した原因不明の病気の続報が入る。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/500d8c93-971e-416e-b8bb-533c3b8ac1c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('584ca7a7-7308-4c0c-a004-89f0f0a17a2e', 'c233877a-d27a-494e-9c77-b7821e222389', 5, '100030595', '愛は惜しみなく与う', '秀麗は、王宮で、この世の者ではない気配を漂わせた白銀の髪の男と出会う。金縛りに遭ったような恐怖心に襲われた秀麗を、駆けつけてきた邵可が救う。静蘭は秀麗からその男がつけていた家紋を聞き出し、気色ばむ。府庫に向かった秀麗は、吏部での悪夢のような仕事から、ようやく解放された絳攸とばったり出会うが、相変わらず様子がおかしい絳攸で…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b1559e3-57ee-426a-8b0c-d4fbfaa2028b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f36ae4f5-74fe-45c0-a672-7027a58e7ea8', 'c233877a-d27a-494e-9c77-b7821e222389', 6, '100030596', '青天の霹靂', '稀代の名官吏と誉れ高い、黒州州牧の櫂瑜が、秀麗に面会を申し入れてきた。櫂州牧は、秀麗に、影月の師匠である、西華村水鏡道寺堂主からの預かり物だと言って、たくさんの医学書を秀麗に渡す。さらに、櫂州牧は、影月に関する驚くべき話を秀麗に聞かせる。ちょうどその時、秀麗に、茶州の燕青と影月から、それぞれ急ぎの文が届く。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1afbaf0-9b72-4881-b457-1501b10758ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6d8bb0d-81e2-4d4b-aeb7-5f5ad9060019', 'c233877a-d27a-494e-9c77-b7821e222389', 7, '100030597', '一心岩をも透す', '茶州虎林郡で発生した奇妙な病に対処するため、王宮では陶老師をはじめとする最高医官たちが、堂主より託されたたくさんの医学書の中から、その治療法を懸命に探していた。影月が尊敬する堂主こそ、伝説の名医を輩出した華一族の誉れ、華眞であり、託された医学書は華眞が記したものだった。しかし、ようやく見つけ出した治療法は、王宮の筆頭侍医である陶老師をもってしてもできない、高度な技術を要する治療法だった。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0377677-3b85-4564-ae37-24ebf83daaa8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3183ba6f-c3c0-460e-ad16-1c1c27661538', 'c233877a-d27a-494e-9c77-b7821e222389', 8, '100030598', '人事を尽くして天命を待つ', '茶州で病に苦しんでいる民を救うため、駆け回る秀麗。全商連から医師を派遣してもらう協力をとりつけたものの、まだ、大きな仕事が待ち構えていた。急遽、召集された朝議の席で、居並ぶ重鎮たちを説得しなければならないのである。一刻も早く、民を救いたい一心での秀麗の行動だったが、朝廷の機能を無視した越権行為だという声が上がり、朝議は紛糾する。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5689ef4-dfef-4869-b5fe-3277ceb2a7cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('467184d8-ad16-4133-8713-812277709856', 'c233877a-d27a-494e-9c77-b7821e222389', 9, '100030599', '地獄で仏に会う', '独り、石榮村に駆けつけ、不眠不休で病人の看病に当る影月。村人たちから頼りにされても、今の影月には病を治すことはできない。秀麗が治療法を見つけて駆けつけてきてくれるのを信じて、最善を尽くすしかないのだ。そんな中、影月は、敬愛する堂主にそっくりな男を見つけ、思わず後を追いかける。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c73b9918-33bb-4107-a76e-b05cd9671f71.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fd4c038-7e0d-4118-8061-f922ad277beb', 'c233877a-d27a-494e-9c77-b7821e222389', 10, '100030600', '待ち人きたる', '奇妙な病の原因は女州牧のせいだとする、邪仙教とやらが広めた噂を打ち消し、病に苦しむ民を救うため、茶州へと向かった秀麗。燕青と再会した秀麗は、燕青に、決死の思いを伝える。その頃、影月は邪仙教を名乗る集団に捕らえられていた。千夜と名乗る、邪仙教の教祖は、堂主の顔をしていた…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d7bac49-5365-4a60-94f2-98ccb1eba813.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9b3f8b6-ed01-4ad8-b80a-95353f9882d4', 'c233877a-d27a-494e-9c77-b7821e222389', 11, '100030601', '知らぬは亭主ばかりなり', '医師らを引き連れ、燕青とともに、茶州･虎林城へ駆けつけた秀麗だが、病気の原因を女州牧のせいだと思い込んでいる男たちから、入城を阻止され、命を狙われる。病気で苦しむ人々を助けにきた、ここで死ぬわけにはいかないと、燕青に訴える秀麗。その時、秀麗をののしる男たちの前に、一人の少女が立ちはだかる。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51c25b73-e1d0-4e2b-bb90-607933d15e68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9a81ae95-f1e9-4c46-80c8-b749e6fad2d7', 'c233877a-d27a-494e-9c77-b7821e222389', 12, '100030602', '義を見てせざるは勇なきなり', 'ようやく虎林城に入った秀麗たち一行は、病気の村人たちと対面するが、事態の深刻さに言葉を失う。一刻の猶予も許されないと、人体切開の手術に取り掛かる葉医師。その手助けとなったのは村の女房たちだった。一時は、人体切開を目の当たりにし尻込みした若い医師たちも、助けを求める村人の姿に、医者としての本分を思い起こす。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0ed50b0-6be4-4d89-b9d7-8ceb1a7a4762.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f67d2eb4-ff73-43f6-9878-054be37de249', 'c233877a-d27a-494e-9c77-b7821e222389', 13, '100030603', '急いては事を仕損じる', '秀麗たちは、邪仙教に捕らわれている影月と村人たちを救い出すため、石榮村に向かっていた。一方、茶州から遠く離れた王都･貴陽では、劉輝が縹家当主･璃桜と対面する。影月を捜して、邪仙教に捕まった香鈴は、榮山の坑道で、病気の村人たちの世話をしながら、影月の居場所を探っていた…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07e6538a-78ce-4106-979b-0d66506a9a92.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f4d4ff9-d4a4-4210-b87f-8a9e5d94f255', 'c233877a-d27a-494e-9c77-b7821e222389', 14, '100030604', '虎穴に入る', '邪仙教に捕らわれた村人たちを救出するため、秀麗たちは動き出した。ひそかに影月の居場所を探っていた香鈴は、ようやく、捕らわれの身となっている影月と再会する。秀麗たちの作戦を聞いた影月は、傷ついた影月を助け出そうと必死の香鈴に対して、見つかったらすべてが無駄になると、すぐに戻るように告げる。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ca60983-b9f7-4542-a207-f6ed5017e301.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67f41d8e-a573-4d0e-aa61-55e16a35d982', 'c233877a-d27a-494e-9c77-b7821e222389', 15, '100030605', '一寸の光陰', '静蘭や燕青らの協力を得て、邪仙教に捕らわれていた村人たちを救い出した秀麗は、ついに、千夜と名乗る教祖と対面する。その男は、秀麗の脳裏をよぎった千夜とは全くの別人だった。龍蓮に助け出された影月は、敬愛する堂主･華眞の体を持つその教祖に怒りをぶつける。教祖を捕らえようとする秀麗。だが、そこには、もう一つ、罠が仕掛けられていた。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d85f026-6a0b-42d6-97e1-6ddff23bff00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b166577-7ff6-47d8-94f6-cf3429a90fd2', 'c233877a-d27a-494e-9c77-b7821e222389', 16, '100030606', '風前のともし火', '邪仙教の騒動は収束したが、ついに、影月の命の炎が燃え尽きてしまった。影月を失った香鈴は、衝撃のあまり、高熱を出し倒れ込んでしまう。秀麗たちは、重篤な状態にある香鈴を、ただ祈るような気持ちで見守るしかなかった。一方、影月と命を分かち合ってきた陽月は、悶々とする自分の心を持て余していた…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0e8b89d-bfcd-4488-8fad-8129094fa641.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('add4afe2-b4d1-404c-82a9-0f227819c57e', 'c233877a-d27a-494e-9c77-b7821e222389', 17, '100030607', '浮き沈み七度', '混乱を収めた秀麗たちに、貴陽から届いた茶州州牧解任の辞令。官位降格だけで茶州に残る影月に対し、秀麗には貴陽帰還と官位剥奪、謹慎処分の命が下った。秀麗が茶州を離れるまで残りわずかとなったある日、皆を手料理でもてなすため、買い出しに出かけようとする秀麗に、龍蓮は、茶州の名所旧跡案内を買って出る。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94e5aad1-961e-4828-bbd9-967d40564ab9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af006437-17ff-4ba4-9b78-f6b53cc9c902', 'c233877a-d27a-494e-9c77-b7821e222389', 18, '100030608', '日暮れて道遠し', '劉輝は、秀麗が無事、貴陽に戻ってきたことを素直に喜ぶ。しかし、秀麗に対する反発を抑えるためとはいえ、茶州の民を救った秀麗から官位を剥奪し、何の職務もない冗官に更迭したことで、秀麗がどう思っているか、劉輝は気にかけていた。そんな劉輝の元へ、秀麗から、茶州での出来事を記した報告書が届く。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/236775d0-a215-42d8-8dec-ef152f6a21ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bbc38e5d-0e93-4597-8c01-1bc5780c78b7', 'c233877a-d27a-494e-9c77-b7821e222389', 19, '100030609', '捕らぬ狸の皮算用', '劉輝は、秀麗とともに茶州から戻ってきた悠舜を、自分の副官として、これまで空席だった尚書令に任じ、宰相として迎えた。悠舜も劉輝を守る「盾」となることを誓う。一方、冗官への降格と、しばらくの登殿禁止を言い渡された秀麗は、遊んでいるわけにはいかないとばかりに、謹慎が解けるまで、自分がやれることは何でもやろうと街に出る。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96ab0b9e-3adc-4779-b309-87900f7e0750.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06173aba-fdf3-44b2-a194-ec045e1f8057', 'c233877a-d27a-494e-9c77-b7821e222389', 20, '100030610', '暖簾に腕押し', '胡蝶から会わせたい人がいるからと誘いを受け、姮娥楼にやってきた秀麗は、歌梨という女性にいきなり抱きしめられ、目を白黒させる。歌梨は、秀麗が持ってきた贋作の画に目を留めると、あわてて飛び出して行く。そこへ、胡蝶の手下が、川に流されたマヌケがいると報告にくる。金のタヌキを持っているというその男は、どうやら、秀麗の知り合いのようだが…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/46d24eda-59ca-4af7-bc73-f054fb937455.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69bb37e9-f13f-4c06-8e2a-1e87a8dbc086', 'c233877a-d27a-494e-9c77-b7821e222389', 21, '100030611', '蛙の子は蛙', '秀麗は、やる気のない求婚をしてきた榛蘇芳、通称タンタンを連れ、静蘭とともに贋作の絵画とニセ金の出所を探って、街中を歩き回っていた。同じ頃、劉輝と絳攸、楸瑛も、伝説の画師、碧幽谷の居所を知っていると思われる、歌梨という女性を捜して歩き回っていた。やがて秀麗たちと劉輝たちの足取りが重なる…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7088a36-1257-4fd8-8984-1c5a2685efee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f345e82b-899a-4e9d-ba66-5b85e9724bef', 'c233877a-d27a-494e-9c77-b7821e222389', 22, '100030612', '獅子身中の虫', '歌梨は、蘇芳の屋敷で息子の万里と涙の再会を果たす。実は、歌梨こそ、劉輝たちが捜していた天才画師、碧幽谷その人だった。母の才能を受け継ぐ万里はだまされて、贋作、さらにはニセ金づくりまで手伝わされていたのだ。蘇芳は、自分の父親が万里に描かせた贋作で金もうけをしていることに気づき、すべてを明らかにする決意で秀麗を家へ案内したのだった。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f94686e1-fea7-4df8-b4ab-30228b7e9f90.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7a64885-17e2-4889-8f41-e4407a76578e', 'c233877a-d27a-494e-9c77-b7821e222389', 23, '100030613', '泣き面に蜂', '朝議で、貴族派の門下省長官･旺季から、冗官を一斉退官させる提案が出された。劉輝は秀麗を助けるためにも、その提案を却下したかったが、名案が思いつかない。悠舜が助け船を出し、ひと月以内に働き場所を見つけられれば官吏に残れる、という猶予が設けられることになった。秀麗は同じ立場の蘇芳や、やる気のない冗官たちの尻を叩いて、奮起させようとするのだが…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/723e71b7-24e5-4278-9443-a3ef3956f86a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('170d990d-1321-4093-a162-05c8af8c2aa1', 'c233877a-d27a-494e-9c77-b7821e222389', 24, '100030614', '情けは人のためならず', '冗官たちを叱咤激励し、働き場所を探すようにと追い立てる秀麗。他人の世話を焼くばかりで、自分のことは後回しになっていた。秀麗は、働き場所を既に決めているという陸清雅の余裕の発言に心が揺れるが、自分はツテを頼らず、期限ギリギリまでは他の冗官たちと同じ条件で頑張ろうと決意する。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3322057c-21e8-450d-ab52-03d38d341a65.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ca39662-66e8-4dd5-a97c-8d63ef189a99', 'c233877a-d27a-494e-9c77-b7821e222389', 25, '100030615', '若いときの苦労は買ってもせよ', '冗官たちが解雇になる期限まであと半月。秀麗は相変わらず、他の冗官たちの面倒をみるばかりで、自分の行く先を決められずに悶々としていた。そんな時、蘇芳から二胡を弾いてくれと頼まれ、いつになく神妙な蘇芳の様子に首をかしげる。翌日、料理に使う塩の質が悪くなっていることが気になり、街に調べに出た秀麗は、塩の価格が高騰していることに気づく。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/894ccd72-cdcd-4cd2-9df9-ace2704fc122.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0772f159-c6e7-4ebd-8860-fcecb63f57e0', 'c233877a-d27a-494e-9c77-b7821e222389', 26, '100030616', '大賢は愚なるが如し', '蘇芳の父親が亡くなったと聞いて、秀麗は蘇芳の家に駆けつけるが、そこに彼の姿はなかった。その頃蘇芳は、思うところあって、ある屋敷に住み込みで働いていたのだった。やがて秀麗は、清雅に協力してもらいながら、塩で金もうけをたくらんだ者にめぼしをつける。塩の問題を解決すれば、退官は免れる。秀麗は徹夜で上申書を完成させるが…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e31df934-ceb9-483b-ab33-8aca83073732.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1558a23e-78a2-420e-88dd-b1879b33699c', 'c233877a-d27a-494e-9c77-b7821e222389', 27, '100030617', '待たれる身より待つ身', '劉輝は秀麗からの報告書を読みながら静蘭と話していた。冗官になった秀麗は、誰に命じられるでもなく自力で駆け回った。蘇芳とともに、贋作･塩･ニセ金事件の真相に迫ったのである。劉輝は秀麗の活躍を心から喜ぶ一方で、これから多忙になる秀麗とあまり会えなくなることを寂しく思う。劉輝は、相談があると呼び寄せた絳攸に、ある決意を告げる。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c193135-94fa-44f8-9834-bac2d20b9fe9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6fc7da7-3e07-417a-b765-10b2bf87f13e', 'c233877a-d27a-494e-9c77-b7821e222389', 28, '100030618', '桃栗三年柿八年', '貴陽へ向って旅をしていた燕青は、謎の男たちに命を狙われている娘を助ける。その娘は、どこか秀麗に似ていた。貴陽では、監察御史になった秀麗が同僚の清雅に対して、ひとり、怒りを爆発させていた。二人の性格は全く相容れないだけに、互いにライバル心を燃やすのだった。その頃、楸瑛は深く思い悩んでいた…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8887f634-8142-4792-9f70-db66129ea2a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da944450-de89-40e9-bc32-f3ed0175ddf6', 'c233877a-d27a-494e-9c77-b7821e222389', 29, '100030619', '遠ざかる程想いが募る', '楸瑛は、妹の十三姫と再会する。十三姫は劉輝の妃になるため、藍家から送り込まれたのだった。劉輝と藍家、どちらを選ぶかで、楸瑛は苦悩する。十三姫は、身の安全のため極秘で後宮の離れにかくまわれることになり、身代わりとして秀麗も同行することになった。一方、秀麗は、冤罪で牢に入っていた隼と名乗る男から、謎の言葉を告げられる。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ac94a6c-af40-41d0-a3a8-adcc1b864c6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6c03f69-4061-4a0f-b752-ddc10c9fb2a9', 'c233877a-d27a-494e-9c77-b7821e222389', 30, '100030620', '鳴かぬ蛍が身を焦がす', '秀麗は十三姫の身代わりとなって、後宮の離れ、桃仙宮で一緒に暮らし始める。その矢先、早速、食事に毒が盛られ、十三姫の命が狙われていることが明らかになる。秀麗が清雅と出かけた後、劉輝が桃仙宮に現われる。十三姫と対面した劉輝は、妃に迎えることはできないと告げるのだが…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ed4b5f0-3a49-481f-ba3a-25e68d1f325c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1bbf58a4-1749-442a-a0ea-860a5129c504', 'c233877a-d27a-494e-9c77-b7821e222389', 31, '100030621', '身から出たさび', 'ある夜、久しぶりに秀麗に会いにきた劉輝。秀麗は、楸瑛と絳攸が劉輝から離れていることを気に懸け尋ねる。一方、劉輝は、秀麗と十三姫が暮らす桃仙宮の警護が穴だらけ過ぎると心配する。劉輝の言葉に引っかかりを感じた秀麗は、やがて、清雅のたくらみに思い至る。そして謎の男、隼が秀麗に「事が起こる」と予言した新月の夜がやってきた。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6aa5a775-f969-44b6-a223-1833ede75eef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('227b3be4-f433-441f-8613-3a57559f06a3', 'c233877a-d27a-494e-9c77-b7821e222389', 32, '100030622', '後ろ髪を引かれる', '秀麗と清雅の眼前で、孟兵部侍郎が暗殺される。孟侍郎の背後に、糸を引いているものがいる。孟侍郎は口封じのために殺されたのだ。その頃、楸瑛は、桃仙宮の十三姫の元へ駆けつけていた。そこへ、秀麗に謎の言葉を残した隼が現れる。楸瑛と十三姫と、隼…。三人の間にある、因縁が明らかになろうとしていた。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7d43689-a226-441e-a083-be5c5d8baeec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('832d0335-f911-443b-99e5-4f10d9a38ba7', 'c233877a-d27a-494e-9c77-b7821e222389', 33, '100030623', '月日変われば気も変わる', '楸瑛は、劉輝から授かった花菖蒲の剣と左羽林軍将軍職を返上し、藍州へ帰還するため城を後にする。清雅は、藍家の弱みを握るため、楸瑛を拘束して、兵部侍郎殺しの犯人と藍家の関係を問いただそうとするが、機転を利かせた秀麗が、一足早く楸瑛を逃がす。やがて劉輝は、十三姫を連れて藍州へ行くと宣言する。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7228ff5-6c63-4361-b970-53c2f5c2ff94.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f98d976f-6df6-4996-93f2-1eaf3dcd99e4', 'c233877a-d27a-494e-9c77-b7821e222389', 34, '100030624', '藍より青し', '秀麗は、一連の事件の手がかりを得ようと、御史台長官に藍州行きを請願し、ようやく許可が下りる。秀麗の頼みを受けて、国試を受けるため貴陽にきていた燕青が、護衛を兼ねて一緒に行くことになった。一方、劉輝は、十三姫と邵可を連れてひそかに藍州へと旅立つ。長官から王を無事連れ戻すよう命を受けた秀麗は、タンタン、燕青とともに劉輝の後を追う。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc7f1106-1631-43ac-b4c5-e9b362a85b78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17ea502f-147a-4f57-9459-27ac780223b8', 'c233877a-d27a-494e-9c77-b7821e222389', 35, '100030625', '危ない橋を渡る', '藍州を目指す秀麗、タンタン、燕青。一行の船は激流を抜け、ようやく藍州州都･玉龍に到着する。藍州州牧の迎えを受けた秀麗は、劉輝が忍びで藍州に入っていることを告げ、大至急捜し出してほしいと頼む。だがその頃、劉輝一行は禁断の地「九彩江」に足を踏み入れようとしていた。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eef7bc19-4312-485f-92a6-44f06605a633.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29b1a092-9b85-4ad3-915a-03ce00941da3', 'c233877a-d27a-494e-9c77-b7821e222389', 36, '100030626', '人生いたる所に青山あり', '「王たる者だけが九彩江･宝鏡山の上にある社にたどりつける」という言葉を胸に、劉輝はひとり山に入るが、道に迷ってしまう。疲れからまどろんでしまった劉輝の夢に、秀麗と出会い、王として振舞うことを決意してから成してきた、数々の決断の瞬間が走馬灯のように現れる。眠りから覚めた劉輝は、「自分は王としての責任から逃げてはいなかっただろうか…」と涙する。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/243fd57c-68a8-4014-ace8-71f5cd077489.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87d58d30-814a-45e2-908d-7e41f91b48b4', 'c233877a-d27a-494e-9c77-b7821e222389', 37, '100030627', '目は心の鏡', '劉輝を捜すため、激流を抜け、滝を抜け、命からがら、九彩江にたどりついた秀麗たちの前に、隼が現れる。「縹家のおばちゃん」の命令で、秀麗を宝鏡山山頂の社まで連れにきたという。秀麗は、自分に何の用かといぶかしく思いながらも、高山病で倒れていた劉輝を拾って社で寝かせているという隼の言葉を信じ、同行する。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38cec4dc-d13b-4b4b-a079-e3fad65ef124.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81b8d512-e0d8-4199-b664-0ae03da104d9', 'c233877a-d27a-494e-9c77-b7821e222389', 38, '100030628', '刎頚の交わり', '縹家当主の姉･縹瑠花の魔の手から秀麗を救うため、宝鏡山のご神体である鏡を割った邵可。鏡には、宝鏡山の名前の由来となったあやかしが封じ込まれていた。荒れ狂う山。空が泣き、地が震える。珠翠が機転を利かし、逃げる時間を稼ぐ。劉輝を乗せた秀麗たちの舟が岸を離れようとするまさにその時、珠翠が舟から飛び降りてしまう。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5cf5a082-db8f-4014-8b26-33773c0911d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('573b699b-92f9-4f61-888e-56cfa230995b', 'c233877a-d27a-494e-9c77-b7821e222389', 39, '100030629', '縁あれば千里', '【シーズン2 最終話】藍州を離れる秀麗たち。楸瑛も一緒である。楸瑛は劉輝に生涯の忠誠を誓った。劉輝の想いは果たされた。ようやく彩雲国の王として真の自覚を持った劉輝。早朝、貴陽の船着場に出迎えた悠舜と静蘭に、劉輝と楸瑛はそれぞれの決意を伝えるのだった。王としての劉輝にはやるべきことが山ほどある。これからが本当の始まりなのだ。そして、秀麗との関係にも変化が…。', '2019/03/28 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4945bd69-4f2e-4e27-bf3f-26edff4dc82f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('581b09b7-c533-4b8f-ae1f-38aa332c0afb', '冴えない彼女の育てかた', '', 'hulu', 'saenai-heroine-no-sodate-kata', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d17493a-e019-49e5-b190-bd9203c7db48.jpg?w=331&h=447&p=t', 'hulu', 2015, 0, 1, 'FINISHED', NULL, 20657, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1b8d4afe-a587-45fd-82ac-e9322ab46acc', '581b09b7-c533-4b8f-ae1f-38aa332c0afb', 'hulu-saenai-heroine-no-sodate-kata-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9910641a-f200-4f10-9b1b-1212f1201023.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('804ebea3-5bdf-4489-b8ea-839aa4013137', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 1, '100146202', '間違いだらけのプロローグ', '「ある春の日、俺は、運命と出逢った」。桜が舞い散る坂の上で、高校2年生の安芸倫也は白いワンピースの美少女に出会う。その出会いに運命を感じたオタクの倫也は、彼女をメインヒロインにした「最強ギャルゲー」を制作する事を決意する。そこで、美術部のエースにして超有名同人作家の澤村･スペンサー･英梨々と、学園一の才女にして超人気ラノベ作家の霞ヶ丘詩羽に協力を仰ごうとする。そんな中、あの時の「美少女」が意外な人物だったことが判明する。', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9910641a-f200-4f10-9b1b-1212f1201023.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a029a50b-f392-4dbc-861b-41b991c8e362', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 2, '100146203', 'フラグの立たない彼女', 'あの日、運命を感じた美少女は、なんてことはないただのクラスメイト、加藤恵だった。「メインヒロイン」のイメージ像とは程遠い薄い存在感の恵に、倫也は途方に暮れてしまう。「加藤……俺の創作意欲を返せ」。落ち込んでいるのもつかの間、倫也と恵のもとに待ち合わせをすっぽかされた英梨々と詩羽がやってくる。', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0feef08e-0173-4abc-856e-e494a769497f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fc27ffb-7d4f-4265-90a9-6ff2650e9baf', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 3, '100146204', 'クライマックスはリテイクで', 'ゴールデンウィーク明けまでに英梨々と詩羽を納得させる企画書を作る事になった倫也。そこで恵をミーティングに誘うが、恵はゴールデンウィークいっぱいは家族旅行で北海道にいると言う。ひとり、机に向かう倫也だが、全くはかどらず、時間ばかりが過ぎていく。そこへ、突如英梨々がやって来る。「もしかしてお前、今日来たのって、俺のこと励ましに……?」', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe8ed59f-bcc0-4ee6-8532-657df0b74fa5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e054e21f-0304-40d0-8edd-d16f171997b0', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 4, '100146205', '予算と納期と新展開', '「それにしても、いまだに信じられないな……これを書いたのが、あの霞ヶ丘先輩だなんて」。霞ヶ丘 詩羽、その正体は、シリーズ累計50万部突破『恋するメトロノーム』原作者、超人気女子高生ラノベ作家、霞詩子である。次回作も期待されているのだが、全くプロットが進んでいない。そんな彼女のもとに、編集部よりインタビューの仕事が舞い込む。乗り気ではない詩羽だったが、その相手が意外な人物であると知り……!?', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bff63d17-d3ae-4b5e-ba2f-298270982318.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7d8f228-d9e6-4f11-8714-27316eb07c11', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 5, '100146206', 'すれ違いのデートイベント', 'ついにサークル活動がスタートした。英梨々は恵をモデルにしてキャラクターデザインを始めるが、全くキャラの立たない恵から二次元的メインヒロインをデザインするという作業に早速頭を抱えていた。そんな中、倫也が唐突に口を開く。「ところでさ、英梨々。デートって、したことあるか?」英梨々と詩羽の動揺は凄まじく…。', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ce62828-f75b-40f3-98ce-81f46f323588.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d19cde6-c403-47c6-b0ec-23986035db7d', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 6, '100146207', '二人の夜の選択肢', '次回作の取材のため町田とともに和合市を訪れていた詩羽へ、『倫理君』からの着信が続く。気になりながらもその電話に出ることができない詩羽は、倫也との出会い、そして半年前の出来事を思い出していた。その頃詩羽を追いかけて和合市まで来た倫也は、二人の思い出の場所、ファミレス、駅前公園などを探しまわるが、ついに雨まで降り出して…。「いつになったら許してくれるのかな……」。', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fee6015-2a98-48ef-bd76-91ef15c5ab4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9c74825-0673-40ac-9b34-8108c403bb21', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 7, '100146208', '敵か味方か新キャラか', '「お、お前っ、男の俺を巻き込んでおきながら十八禁作るつもりか!?」夏コミを控え修羅場モードの英梨々に呼び出された倫也。原稿が遅れている原因が自分であるため手伝いを申し出るが、同人誌作りに関して素人である倫也に英梨々はストーリーを一緒に考えてほしいと言う。かくして原稿の読み合わせをする二人だが、英梨々の描く同人誌は十八禁で……。', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ea36b25-afcd-4bc9-871d-70de08704f61.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3da666f1-cce6-40d4-adf5-13ed2565161e', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 8, '100146209', '当て馬トラウマ回想モード', 'キャラクターデザインの方向性を打ち合わせるため倫也の部屋を訪れた恵だったが、そこには夏コミ開始を翌日に控えて原稿を進める英梨々と手伝う倫也の姿があった。集中するふたりにサークルの打ち合わせはできないと感じた恵は、時間潰しのためリトラプをプレイし始めたのだった。そして翌日、倫也の“弟子”出海が出展するサークルスペースへ倫也と恵がやってきた。感激で胸をぎゅうぎゅうと押し付け倫也に抱きつく出海に、恵は少しの感情も込めずに言う。「えっと……せっかく彼女と勘違いされてることだし『倫也から離れなさいよこの泥棒猫っ』とか言った方がいいかな?」', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02982a32-c6a5-4d05-839c-544f16b8222d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ab6ceba-03e9-4792-ad76-ea4f482ce3c7', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 9, '100146210', '八年ぶりの個別ルート', '走り去る英梨々にただ立ち尽くすことしか出来なかった倫也。自室で目が覚めた倫也は、目の前にいる詩羽に驚きの声を上げる。恵からの連絡に詩羽はすぐさま駆けつけたのだった。ふたりに英梨々とのやりとりを説明するが、大人げないと指摘され、このことが原因で英梨々はクリエイターとして活動できなくなるかもしれないと言われてしまう。サークル崩壊の危機を乗り越えようと思案する倫也に恵が告げた。「安芸くんが……主人公じゃなくて、ヒロインになればいいんだよ」。', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a62c773d-0760-4b06-ab37-133124fe4cd3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e71f7c2-cbde-4c45-bf8f-824ea75c51eb', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 10, '100146211', '思い出とテコ入れのメロディ', '倫也、英梨々、詩羽、恵の4人がゲームでのお風呂遭遇イベントについて、ビデオ通話をしていた夜。夏コミでの出来事からモチベーションの上がっている英梨々と、自分の新作小説以上に熱を込めてゲームシナリオに取り組む詩羽、ネット上でもステルス能力を発揮する恵だったが、時刻はいつの間にか0時半に。本日のネット会議は解散して倫也は風呂へ向かうが、なぜかそこには下着だけを身に付けた従姉妹の美智留がいて……。「違うだろ! おまえは悲鳴を上げて『な、何見てるのよこのスケベ～!』って怒らなくちゃならない立場だろ!」', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a16f4009-02d4-4940-a3bf-82ad674f459a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4bf3187b-4d34-48da-8739-0e10aaebfdee', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 11, '100146212', '伏線回収準備よし', 'サークルの音楽担当として美智留を他のメンバーに紹介する倫也だが、オタクへの理解を得られず、美智留から『痛い夢追っかけてないで、脱オタして現実見ようよ』と言われてしまう。サークルに参加してくれるように必死で頼むが、美智留の目には倫也以外のメンバーは本気で取り組んでいないように見えていた。「あたしたちのバンドは、みんなが本気で同じ夢を目指してるんだ……あんたのサークルとは違うんだよ」。', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62d70cbd-3164-4d83-b251-8ed10fd9e6a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64967deb-7fac-4d76-b4eb-416b3ecf393a', '1b8d4afe-a587-45fd-82ac-e9322ab46acc', 12, '100146213', '波乱と激動の日常エンド', '【最終話】ゲーム制作の進行が遅れている中、英梨々や詩羽には事情を明かさぬまま、『icy tail』のマネージャーも引き受けた倫也。彼の尽力により、ついに『icy tail』は初ライブを迎える。だがこのライブには美智留の知らない秘密があり……? 美智留のマネージャーを引き受けた倫也の真意とは!? blessing softwareはゲームを完成できぬまま、解散してしまうのか!?', '2023/06/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09e46362-6fd9-4852-b7d7-4800e345370b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('17401ef1-b6ad-4f9d-8d51-e3d152b4786b', '冴えない彼女の育てかた ♭', '', 'hulu', 'saenai-heroine-no-sodate-kata-flat', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c9f6a6b-9bbb-4f5d-b1bc-c70ef680ca28.jpg?w=331&h=447&p=t', 'hulu', 2017, 1, 1, 'FINISHED', NULL, 21180, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ff74ccfd-bca4-4c84-83f6-35b92e95e50e', '17401ef1-b6ad-4f9d-8d51-e3d152b4786b', 'hulu-saenai-heroine-no-sodate-kata-flat-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f228ead2-0fd2-442b-a392-61403703ea5a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e712d2a-69e4-478d-960b-ca865136acfe', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 1, '100146215', '冴えない竜虎の相見えかた', '時は1年前の豐ヶ崎学園。自分の書いたライトノベル「恋するメトロノーム」が図書室に入ったのを確認する詩羽。その帰り道の廊下を歩いていると、途中階段に差しかかったところである人物に突然声をかけられる。声をかけたその人物こそ「澤村･スペンサー･英梨々」だった。ついに明かされる英梨々と詩羽の出会い。二人の間にはいったい何が!?', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f228ead2-0fd2-442b-a392-61403703ea5a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('83928ef6-1292-4c1b-9259-55be704a48b2', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 2, '100146216', '本気で本当な分岐点', 'ついに完成したシナリオの脱稿祝いの打ち上げとして、池袋でデートをする倫也と詩羽。本屋、映画館と詩羽の知識欲を満たす場所を巡り、夜はレストランで食事をする二人。そこで詩羽は、近くの大学に進学するべきか、関西の大学に進学するべきかを倫也に問いかける。デートも終わり、帰り際の駅でその詩羽の問いかけに対し、とある結論をだす倫也。その、結論を聞いた詩羽はとある行動に出るのだった。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b443bff7-37cb-4a04-aeea-3bdd6318b561.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('814106bd-1018-4c18-8fc3-35dec0495ef8', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 3, '100146217', '初稿と二稿と大長考', '出海との待ち合わせ場所に着いた倫也達。なんとそこには、出海だけでなく伊織の姿もあった。そこで伊織は自分のサークル「rouge en rouge」の新作ゲームのメイン原画を出海が担当し、さらにゲームのジャンルを「blessing software」と被らせることで、真向勝負の構えを見せる。サークルメンバーの力を信じる倫也に、伊織は「シナリオだけは負ける気がしない」と言い放つ。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc8734a5-656a-45bc-b7a8-667b9027976a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75258d8f-c5e3-4826-8ce6-3c55d3e32a4c', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 4, '100146218', '二泊三日の新ルート', '詩羽の書いたシナリオの致命的な弱点に気付いてしまった倫也。そのシナリオは小説としては完璧のクオリティだが、ゲームのシナリオとしては成立していなかった。倫也はディレクターとしてシナリオのリテイクを決断し、シナリオの修正を始める。そこに、気持ちを整理した詩羽も協力し二人でゲームとしてのシナリオを作り上げていくのだった。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec96c1a7-8ef2-402a-b202-da878cbbf88b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11030b04-03c0-4827-8222-228107472d2e', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 5, '100146219', '締め切りが先か、覚醒が先か', 'シナリオのリテイク&ルートの追加により、順調にゲーム制作の進行も遅れる中、英梨々の原画作業にも遅れが目立ち始める。かけた時間がクオリティに反映されてこないと指摘する詩羽。それでも英梨々は最後に予想通りのものをきちんとあげてくると信じる倫也。そんな中、英梨々は那須高原の別荘に籠り、一人原画作業に没頭するのだが…。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db539010-cbbf-4d8f-b82a-1f78372d0b70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38d0dcef-a2db-41cf-84fb-4228b0981d9c', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 6, '100146220', '雪に埋もれたマスターアップ', 'ついに最後の原画を完成させた英梨々だったが、倫也に電話で完成の報告をしている最中に風邪による高熱で気を失ってしまう。英梨々の異変に気付いた倫也は、マスターアップの作業よりも英梨々の元へ駆けつけることを優先する。伊織の助けにより那須高原の別荘にたどりつき、病床の英梨々を看病する倫也。果たしてゲームの完成はどうなってしまうのか――', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f10ce3ab-c222-483f-a1b4-8e19940c30fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40c7cac7-6517-4174-9bee-76718b913b74', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 7, '100146221', 'リベンジまみれの新企画', '倫也たちが完成させたゲーム『cherry blessing』は、英梨々の原画と詩羽のシナリオがネットで評判となり、同人ショップでの委託販売もあっという間に完売し、大量の追加発注も来るほどに。倫也は作品の盛況ぶりを喜ぶ一方、恵とはまだ仲直りできないでいるのだった。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d4037a9-f0ba-4e3d-bc82-065a0962a05f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50c41758-6b5d-4ad8-af7d-a7140c4b2ba4', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 8, '100146222', 'フラグを折らなかった彼女', 'あらためて『cherry blessing』をプレイし、その演出の細かさから恵がどれほど真剣にゲーム制作に取り組んでいたかに気付いた倫也。翌日、気まずそうにする恵をなかば強引に視聴覚室に連れて行き、いつもの暑苦しい様子で「blessing software」の次回作について熱く語る。そして、ようやく恵に去年英梨々が倒れた時に相談できなかったことの謝罪と、「blessing software」を好きでいてくれたことの感謝を述べる。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/031de573-b96f-4209-97a8-35606a041c19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45d8c157-419b-4384-b3f5-c535c5d9a1c6', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 9, '100146223', '卒業式と超展開', '豐ヶ崎学園の卒業式を迎えた詩羽の卒業を祝う倫也は、詩羽に対しこれからも今のメンバーでゲームを作っていきたいと告げる。そのためには、みんなが参加したいと思える企画を立てるしかないと考え、詩羽に新作ゲームの企画書を見せる倫也。詩羽はその企画書に対して75点という高評価をつけるも、この企画には参加できないと告げるのだった。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6887ca77-7413-467a-a87f-3206eeb37572.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ed7eab7-0634-40eb-a9b0-a9cfa376a1eb', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 10, '100146224', 'そして竜虎は神に挑まん', '高坂朱音から、20年続く人気RPG「フィールズクロニクル」の新作に参加しないかと誘われた英梨々と詩羽。打ち合わせの場で、英梨々は絵が描けないのはスランプではなく、ただ下手なだけだと罵倒され、詩羽は英梨々のおまけとして扱われてしまう。悔しい思いをする二人であったが、クリエイターとしては魅力的な企画に、心が揺れてしまう。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab7c8dcc-3442-4ed4-b766-6bb37baf92bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1ce4775-d969-43e8-9e46-ef19847784ae', 'ff74ccfd-bca4-4c84-83f6-35b92e95e50e', 11, '100146225', '再起と新規のゲームスタート', '【最終話】詩羽と英梨々のサークル離脱で傷心の倫也。恵はそんな倫也をもう一度デートにと誘う。場所は再び六天馬モール。前回のデートのことを懐かしく感じながら、色々なお店を回る二人。買い物の最後に入った帽子屋で、倫也は自分を元気づけようとしてくれたお礼と、前回プレゼントしてもらった眼鏡のお返しとして、とある帽子をプレゼントする。', '2023/06/28 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b15a103-ba6b-4fd0-9fba-576e6697884e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('cb4d9b0b-c33f-4a75-860f-f09cedfdd11d', '坂道のアポロン', '', 'hulu', 'kids-on-the-slope', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c02c59ec-d88c-4f3b-bbb5-39aa937ca61e.jpg?w=331&h=447&p=t', 'hulu', 2012, 1, 1, 'FINISHED', NULL, 12531, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1855a04e-033d-44ad-8f42-1f9c25ade9d4', 'cb4d9b0b-c33f-4a75-860f-f09cedfdd11d', 'hulu-kids-on-the-slope-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32919d71-5379-499d-acf7-2a7c1c15cec7.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d75673b-00ce-4656-b628-7ae70d904297', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 1, '100155288', 'モーニン', '父親のもとを離れ、叔父のいる九州の高校へと転入した西見薫。しかし転入初日、慣れない環境と周囲からの好奇の視線に耐えられず、薫は激しい吐き気を催してしまう。教室を飛び出し、あわてて学校の屋上へと向かう薫。しかしそこで彼を待っていたのは、川渕千太郎との出会いだった。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32919d71-5379-499d-acf7-2a7c1c15cec7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a3d221e-bec5-49c7-bbd8-800598918edf', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 2, '100155289', 'サマータイム', '千太郎のドラムプレイを目の当たりにした薫。その日から、彼の頭のなかではジャズの響きが鳴り続けていた。そんななか、クラスメイトである律子の父が営むレコード店に、お客が訪れる。千太郎が「淳兄」と慕う桂木淳一を交えて、地下のスタジオで始まる、突然のセッション。初めて見る生のジャズセッションに、薫は興奮を隠しきれない。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9ccd5b7-86df-4e0b-8ef7-13b11682257e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c23c2f1-580c-4a42-9bbd-ee674886b821', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 3, '100155290', 'いつか王子様が', '夏の海水浴場で、ひとつ年上の美しい先輩･深堀百合香と出会った薫たち。その清楚な雰囲気に、千太郎はすっかり心を奪われる。毎日のジャズの練習にも身の入らない千太郎の様子を見かねて、薫は千太郎に、百合香に交際を申し込むようにけしかける。そして律子を交えた4人は、ピクニックに出かけることになるが……。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d060799-c6dd-46f5-aadc-09ed911fd062.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('152f1d64-0481-410b-b492-aa9040cfdbc6', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 4, '100155291', 'バットノットフォーミー', 'クリスマスが近づいてきたある日、東京から再び淳一が戻ってきた。喜ぶ千太郎たちを前に、彼は「ライヴをやってみないか」と持ちかける。場所は、近くの繁華街にあるジャズバー。初めての人前での演奏に、2人は緊張と期待で胸をふくらませる。だがその一方、先日の突然の告白以来、薫と律子はぎくしゃくした雰囲気が続いていて……。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f9d9f96-0b3c-43eb-9ce1-552a5b5131c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f6772a2-ae14-4be7-aa4c-45cb5f181f4d', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 5, '100155292', 'バードランドの子守唄', 'キスの一件以来、さらに悪化した薫と律子の仲。バツの悪くなった薫は結局、ジャズの練習に一度も顔を出さないまま、年を越してしまう。そんなある日、彼のもとに一通の手紙が届く。そこには、音信不通になっている母の近況が書かれていた。薫は、十数年ぶりに母と再会するため、無理矢理同行してきた千太郎とともに東京へ向かう。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59b6bec4-0782-438b-92db-49479630f172.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b42a0f61-f907-4b52-a49a-8fff5d57d299', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 6, '100155293', 'ユー･ドント･ノウ･ホワット･ラブ･イズ', '春。二年に進級した薫たちの前に、ド派手なクラスメイトが現れる。ビートルズや流行の音楽にのめり込み、髪型もマッシュルームにした松岡星児。彼は、自分が率いるロックバンドのドラムに、千太郎を誘う。初めは拒否していたものの、じつは苦労人である星児の境遇を聞き、共感を抱く千太郎。彼は、その願いを快諾するのだが……。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8346079d-d69f-422c-8ac6-d649d2dafff8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dda2abea-da65-4dbd-8f33-e683356074c9', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 7, '100155294', 'ナウズ･ザ･タイム', '星児のバンド、オリンポスに参加することになり、練習に忙しい千太郎と、学園祭の実行委員に選ばれた薫。2人の距離は、開いていくばかりだった。そして迎えた学園祭の当日。観客の歓声を集めるオリンポスを目にして、薫は苦々しい想いを抑えきれない。しかし、そのステージで思わぬトラブルが発生して……。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c92e6a7-3671-4198-a941-83e3a45783a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac238938-84b2-4891-8221-d413ce8d66f5', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 8, '100155295', 'ジーズ･フーリッシュ･シングス', 'まるで別人のような姿で地元に戻ってきた淳一。尊敬する淳一のボロボロの姿を目にした千太郎は、ショックを隠しきれない。周囲に巻き込まれるように大学紛争のリーダー的立場になった淳一。しかし彼はそこで忘れられない挫折を味わっていた……。彼のアパートに押しかけた百合香は、傷ついた彼の姿を見て、すべてを捧げる決意をする。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c63a8c1-ff76-49d0-9f21-1c5e280f4080.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9611ec0-9f26-44e4-93a5-0468b596e435', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 9, '100155296', 'ラヴ･ミー･オア･リーヴ･ミー', '薫が九州に来て2回目のクリスマス。律子の気持ちを勘違いしたままの薫は、星児が主宰するパーティに出向くものの、寂しさを感じずにはいられない。一方、薫のために手袋を編む律子もまた、もどかしい想いに悩んでいた。自分からフッておいて、告白できるはずもない。逡巡する彼女の背中を押したのは、千太郎の言葉だった。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ee9acfb-150d-499e-a780-5682806173ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8c3d600-8466-461d-b982-16052e0cbc00', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 10, '100155297', 'イン･ア･センチメンタル･ムード', '東京に駆け落ちした淳一と百合香――千太郎の恋は悲しい結末を迎えた。一方、薫と律子は、クリスマスの一件を経て、徐々に接近。なかなか次の一歩が踏み出せない薫だったが、風邪のお見舞いにやって来た律子に、彼は二度目の告白を果たす。そして季節はめぐり、高校三年の夏。練習に打ち込む千太郎に、ある知らせが舞い込む。', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84b595cb-e999-4493-8fcc-30dba91fd788.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75ab79d9-90fa-4042-acec-85f2eefc7cec', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 11, '100155298', 'レフト･アローン', '父親の帰郷を知り、黙って家を出る千太郎。だが彼を待ち伏せる人物が…!? 文化祭が近づき、星児から挑戦状を叩きつけられた薫たちは、意外なメンバーを増やし名曲「マイ･フェイバリット･シングス」をレパートリーに入れて高校最後のステージに臨む。準備は万端、あとは本番を残すのみとなった前日、思いもよらない出来事が!!', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c9225c0-86d4-4d10-801a-44cc32529c4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cf7ad67-694f-44f7-9b60-6fe9de6c036a', '1855a04e-033d-44ad-8f42-1f9c25ade9d4', 12, '100155299', 'オール･ブルース', '姿を消した千太郎。薫はその現実を冷静に受け止めようとするあまり、律子を傷つけてしまう。気持ちがすれ違ったまま、薫は東京の大学に合格し、町を離れる日が来るが…!? 奇跡的に出会った薫と千太郎がジャズを通じて共鳴し輝いた時間。その光を失った薫の心はどこへ向かう? 相棒との絆はどうなる? 衝撃展開の最終回!!', '2023/09/19 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7908c1b-fb47-4f13-aa37-fd95dc81ee38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8fc9ba68-bad6-4cef-a847-4ee3104d8f07', '坂本ですが?', '', 'hulu', 'havent-you-heard-im-sakamoto', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2843cbff-a0a7-4ca2-961d-3bc61b14b5dd.jpg?w=331&h=447&p=t', 'hulu', 2016, 1, 1, 'FINISHED', NULL, 21595, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('592f90b6-1b4b-48de-990f-09421779e3f4', '8fc9ba68-bad6-4cef-a847-4ee3104d8f07', 'hulu-havent-you-heard-im-sakamoto-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d33cd645-e039-4594-854a-8e3b7836c850.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61e5bbf9-ec33-4c29-9017-34c8568e4f4c', '592f90b6-1b4b-48de-990f-09421779e3f4', 1, '100191511', '1年2組坂本君／ビー･クワイエット', 'スタイリッシュな高校生･坂本は、そのクールな行動で学校中の注目を集める人気者。そんな坂本のことが気に入らない不良3人組は、彼をいじめのターゲットにする。', '2024/08/19 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d33cd645-e039-4594-854a-8e3b7836c850.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c05db60-27f4-4c25-b366-50d8de1e3269', '592f90b6-1b4b-48de-990f-09421779e3f4', 2, '100191512', '守られるより守りたい／今日から使える恋愛心理術', 'ある日、坂本はクラスメイトの久保田が他の生徒からカツアゲされている現場を目撃する。助けを求められた坂本が、「僕に考えがあります」と言って彼がとった行動とは?!', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5183865-aab8-4c56-a4e7-0a3388f5aa12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1040fef5-db50-4701-9a85-37eadb6ca3d3', '592f90b6-1b4b-48de-990f-09421779e3f4', 3, '100191513', 'パシリスト坂本／恋のかくれんぼ', '2年生の不良･丸山は、坂本をパシリにするが、彼のズバ抜けた「おもてなし」に超ご満悦。次第に指示を出すのも面倒になった丸山は、坂本に究極の命令を下す!', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3af32ab3-fac4-4800-b3ee-c2bf525bc86e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ee2cb07-23b1-4e3c-a176-51e02a583fd4', '592f90b6-1b4b-48de-990f-09421779e3f4', 4, '100191514', '坂本はすけべですか?／授業風景オムニバス／坂本が消えた夏', '生徒指導の角田先生は毎日遅刻ギリギリに登校する坂本を叱りたいと思っていた。だが、坂本の何枚も上手な行動に、あっさりと門を通らせてしまう屈辱的な日々を送っていた。', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcd97fa5-9dee-4977-b07d-08b40c65d1db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04859f89-4274-4f7c-a564-159bd3671255', '592f90b6-1b4b-48de-990f-09421779e3f4', 5, '100191515', 'カリスマヤンキー8823先輩', '丸山は坂本をパシリにしていた時に受けたトラウマが癒えず、坂本を見ただけでもおびえていた。2年生の不良･8823先輩は、示しがつかないと坂本にタイマンを申し込む!', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf851571-5f24-47f1-847c-8ef4d9facfe6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c933f83-7e6d-42f1-826e-5b8c8d64aaa2', '592f90b6-1b4b-48de-990f-09421779e3f4', 6, '100191516', '下校のルール／カメラ越しの恋', '石蹴り遊び、道路の白線渡りなど、下校時のたわいない遊びですらスタイリッシュにこなす坂本。そんな坂本を見た男子小学生3人組は、負けじと彼の背中を追いかける。', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/050f0b19-c368-4c45-8ef2-d817b33c44d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f621d48c-74ec-449f-8a09-ed9581b93d92', '592f90b6-1b4b-48de-990f-09421779e3f4', 7, '100191517', 'やはり坂本はすけべですか?／瀬良のフランス革命', '不良3人組はレンタルビデオ店にいた。目的は18禁コーナーへの侵入! しかし、18禁コーナーののれんは厚く、なかなか突破できない。そんな彼らの前に、坂本が現れる。', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37f4dc6e-b105-4724-980e-fda18b92b0dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7ff9eef-18f6-4417-81e3-71f293452d5e', '592f90b6-1b4b-48de-990f-09421779e3f4', 8, '100191518', '文化祭はグルーミー', '坂本のクラスは文化祭の準備真っ最中! 不良グループたちも文化祭を楽しもうと準備に精を出していた。だが、そんな彼らの前に不良たちさえも恐れる3年生･深瀬が現れる。', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ada9d02-88be-4024-abda-47fb9606f4a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74b29ff9-80c6-4118-a351-4c4113325cd5', '592f90b6-1b4b-48de-990f-09421779e3f4', 9, '100191519', '坂本君と私の出会い／一番近くて遠い人', '藤田、みーちゃん、カナちゃんが坂本に見惚れていると、藤田が坂本とのロマンチックな出会いを語りはじめる。それに続き、みーちゃん、カナちゃんも語り始め…。', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebd426d1-45fa-4af5-9b76-ceb78aff14e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73b67e61-9822-4b4c-8779-addf15cec65b', '592f90b6-1b4b-48de-990f-09421779e3f4', 10, '100191520', '魔王／足りないもの', 'クリスマスの夜。坂本はひょんなことから見ず知らずのイケメン大学生に誘われ、なんと3対3の合コンに参加することになってしまった!!', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6017d75-e673-4a90-aa4f-48af9ed705ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2a73965-fcbd-49f5-a2ff-76cd1c9214f2', '592f90b6-1b4b-48de-990f-09421779e3f4', 11, '100191521', 'ぬくもりはいらない／1-2メモリーズ', '街に雪が降り積もった。雪は初めてという坂本に、あっちゃんが雪の遊び方をレクチャーするのだが、いとも簡単にマスターされてしまう。悔しがるあっちゃんだが…。', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2cc8621a-4e4e-4165-bc01-dc5eec64efb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf3334e4-8fc7-411b-8dac-fd118031f2fb', '592f90b6-1b4b-48de-990f-09421779e3f4', 12, '100191522', 'さよなら坂本君', '【最終話】3年生の卒業式。坂本の送辞中に、あっちゃんがバットを持って乱入。あっちゃんを止めようと駆け付けた8823 (ハヤブサ) 先輩だが、坂本はそんな彼を静かに制止する。', '2024/08/19 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bca0f750-02ae-4780-bb3b-c55094e86da2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('80abaf51-ba62-4f64-9110-5ea7dfa33947', '咲-Saki-', '', 'hulu', 'saki', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e223fdb7-548f-4a6c-9a98-f4d0865c6596.jpg?w=331&h=447&p=t', 'hulu', 2009, 1, 1, 'FINISHED', NULL, 5671, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', '80abaf51-ba62-4f64-9110-5ea7dfa33947', 'hulu-saki-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/866de4e7-3395-4126-977e-8b1aacdfd8f5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea21a4f7-754b-4930-8ff0-ed3c82781b8e', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 1, '60054204', '出会い', '訳も分からず麻雀部に連れて行かれ、麻雀を打つ事になった咲。そこには小川のほとりで出会った少女、和がいた。結果、対局は和の勝利で終わったが、咲の打ち方に疑問を感じた和は、もう一回打って欲しいと願う。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/866de4e7-3395-4126-977e-8b1aacdfd8f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b8036ee-fd94-4722-baf8-6863154a6f2e', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 2, '60054203', '勝負', '勝つよりも難しい離れ業を成し遂げた咲に、ある「提案」をする久。それは、咲の潜在能力を確かめる為の対局だった。久の予想は的中し、見事に実力を発揮する咲。しかし、それを見た和の心にはひとつの感情が湧き起こるのだった。', '2018/06/07 00:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6f381402-0ddb-433d-b2ea-46d4aab94371.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1da09b0-0974-4f74-a3b6-6eb0350dbc0e', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 3, '60054200', '対立', 'みんなで麻雀打っていた和は、咲の打ち回しに違和感を感じる。その疑問が確信に変わったとき、和の感情がついに爆発してしまう。一方そのころ、久とまこは高校生麻雀大会･県予選の抽選会場に足を踏み入れていた。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9b849068-de8c-45c8-9635-92eea3dcb4a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ba9f307-ee39-4ce9-bbe8-9da187495dbe', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 4, '60054202', '翻弄', 'いよいよ間近に迫る、全国高校生麻雀大会の県予選。そんな中、咲と和は、まこの実家が経営するお店の手伝いをすることに。「社会勉強も特訓の内!」と説明する久だったが、彼女の胸の内には“ある企み”が潜んでいた。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ba91ea2a-7c0d-46a1-9b3b-ed26bd895595.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0609935c-be2f-45c9-8b92-c81c58c086cf', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 5, '60054201', '合宿', '県予選突破を目指すために始まった強化合宿。気持ちいい露天風呂とおいしい料理を楽しみつつ、特訓に励む咲と優希。そして和に与えられた特訓は、久のちょっとした思いつきから始まる。それは、恥ずかしい格好で麻雀を打つことだった。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b4d61a7e-3413-4164-b70a-75bce6109a3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b32c3ab3-cccf-4e8d-abd4-db6b4cf0bd3f', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 6, '60054908', '開幕', 'ついに始まった県予選!風越女子などの優勝候補が現れ、徐々にヒートアップしてゆく会場で、咲だけがみんなとはぐれてしまう。ひとりぼっちで涙ぐむ咲の前に現れたのは、昨年の団体戦で優勝した龍門渕高校のメンバーだった。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/922df1a7-348d-41e9-b1e5-6d44e9ec33ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('815fbc1d-e053-427a-98bf-2b2226d6fa54', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 7, '60054909', '伝統', 'ペンギンのぬいぐるみを抱いて対局室に現れた和。その姿を見たギャラリーは騒然となり、偵察に来た透華も周囲の視線を集めている和に苛立ちをみせる。そんな状況を唯一、久だけが楽しそうに眺めていた。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/92f3341e-a17a-4d25-8f1c-fb5b0e929147.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42bc1360-5d65-4d1f-860e-db102d0e7769', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 8, '60054910', '前夜', '順調に勝ち進み、県予選･決勝まで駒を進めた清澄高校麻雀部。みんなと一緒に全国へ行く!その気持ちを改めて確かめ合う咲と和。しかし、龍門渕、風越、鶴賀のメンバーもまた、負けられない想いを強く抱いていた。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5c702c47-f10b-4be9-9784-9ef13259c814.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('660f0114-b1de-4a39-837b-a3ddfef9ee44', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 9, '60054911', '開眼', '決勝戦へ臨む清澄高校麻雀部に緊急事態が発生! 優希の力の源「タコス」が奪われてしまった! ショックで涙を浮かべる優希だが、彼女の肩に手が優しく差し述べられる。それは優希と対戦する風越女子の部長、福路美穂子だった。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c3da1271-b4cc-4cba-aa6f-bd8424de60ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2f07227-a1ee-48ea-b33c-a84c12460e85', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 10, '60054912', '初心者', '次峰戦開始直後、まこは早々とメガネを外す。裸眼となった視界には、過去に記憶した膨大な観戦記録がイメージとなって浮かび上がっていた。これらのイメージ(記憶した観戦内容)が、大事な局面で手助けとなり有利に闘いを進めていくハズだったのだが…。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/03a16fd7-7d8f-465a-a36e-570f16c23658.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81bbefb6-d00d-48fa-9652-dc5945f08fc7', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 11, '60054913', '悪戯', '中堅戦に挑む久は、自らを不利な状況に追い込む打ち方を続けていた。しかし、これこそが勝負時に魅せる彼女のスタイルだった。勢いに乗った久は、他校を圧倒し首位に躍り出る。対して最下位に落ちた龍門渕高校の一(はじめ)は、自分を戒める鎖に「うずき」を感じていた…。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8802ef96-1b66-4e76-b1a4-035860411ad6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5626c2ef-bb7a-46de-b8bd-a20dd8406d96', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 12, '60054914', '目醒め', '中堅戦の前半が終了し、4校の点差は横並び状態に陥った。リードを守れなかった風越女子の文堂は、駆けつけたキャプテン･福路の姿を見た途端、情けない気持ちから涙をこぼす。そんな傷心の彼女を福路は優しく抱きしめるのだった。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4577a4d1-5b2c-4916-9d2d-df80a13c1bc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfb11fbe-5851-447f-80dd-41a797e4783d', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 13, '60054915', '微熱', '副将戦は小さな和了と流局が交差する、静かな戦いとなっていた。緊張感あふれる対局が続く中、和の身体に「異変」が起こる。こらえきれず徐々にこみ上げてくる高揚感。頬を赤らめ、柔らかくなってゆく表情。艶やかになってゆく和を見た龍門渕透華は、念願の宿敵に出会えた喜びを感じるのだった。', '2018/06/07 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1606f098-b12a-44bc-8eed-5e412e569cee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a338dab0-ff35-48e8-b0be-03ec666a78df', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 14, '60054916', '存在', '和は、堅実な和了を積み重ねて着実にポイントを稼ぐ。そんな和の快進撃に、龍門渕透華が立ちはだかる。高得点の和了りで和のパーフェクトゲームを阻止した透華は、このまま波に乗って連荘を目指すそうとするのだが…。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/470c4efc-a5e4-4310-b260-aedc8679b08f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('add69f5a-0d64-41f5-817e-680147d4d5dd', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 15, '60054917', '魔物', 'ついに最後の戦いとなった県予選･団体戦。勝負の行方は、4名の大将に託された。清澄高校の宮永咲。風越女子の池田華菜。鶴賀学園の加治木ゆみ。そして昨年度のMVP、龍門渕高校の天江衣。譲れない戦いの幕が、いま切って落とされる。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ce5d7bb6-1663-4f11-bf68-3fdf0fa892fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0df80317-f54d-4447-b018-c868f10fb7d5', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 16, '60054918', '結託', 'まるで海の底に引きずり込まれがごとく、何回牌をツモっても手を進める事ができない咲と池田と加治木。そんな中、天江衣だけが和了つづける。これが、悪夢の始まりだった。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/274ec6c3-843a-4798-a445-8361c18bc08a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d525e79-c14a-4ece-b7f6-07a86095701d', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 17, '60054919', '悪夢', '天江衣の圧倒的な強さで前半戦が終了。他校を寄せ付けない点差を稼ぎ、独走状態となった。ショックを隠すことができない対局者たちの前に各校の仲間が駆けつける。池田には福路が寄り添い、加治木を桃子が激励し、咲は和と手を取り合い二人で誓い合った「約束」を思い出す。そして、後半戦が始まろうとしていた。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/576757d0-1040-4977-8bd5-18162efd3e6c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2349272-c8e6-4f2a-b47f-abf857ba56d2', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 18, '60054920', '繋がり', '槍槓を和了り、窮地を脱した池田。しかし最下位という状況は変わらず、挽回できるとは思えない点差が開いていた。そんな絶望的な状況でも戦う心を失なわず、池田は果敢に攻め続ける。一方、自分の対局スタイルを思い出した咲は、徐々に本来の調子を取り戻しつつあった…。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/55f62fd2-feaa-47c0-8732-04ffae9c014d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1821fcf-6bf9-48d9-bb66-709130ea7447', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 19, '60054921', '友達', '4回目の海底撈月を和了り、咲の連荘を阻止した天江衣。舞台はいよいよオーラス、最後の1局となった。圧倒的な点差で独走を続ける天江衣。そして彼女に挑む加治木、池田、咲。県予選団体戦･決勝戦、最後の戦いが始まろうとしていた。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/82bdab90-c377-434e-87bc-4597298ecefd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66732b01-f6b3-462a-99e7-3c905b082e13', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 20, '60054922', '姉妹', '部長から水着を持参するよう指示された清澄高校麻雀部のメンバー。その理由は、スポーツランドのプールで特訓を行う為だった。艶やかな水着姿を披露する和や咲たち。そしてその場には、思いも寄らない面々も遊びに来ていた。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b746e7d8-9836-4dda-9fa6-423719da9a81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4095ed8-7b17-44ed-804b-50a41c668ce4', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 21, '60054923', '追想', '県予選代表選抜･個人戦の初日がついに始まった!数少ない全国出場の個人戦枠を手に入れるため、各校の選手が奮闘する。その中には、初めて姿を見せる選手も潜んでいた。清澄高校麻雀部のメンバーは互いの健闘を誓い、それぞれに用意された対局室へ向かうのだが…。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/239aa798-293a-4570-9fa8-21d2b9954214.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be016ec1-e2bc-4eca-b820-3cd3fb83066b', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 22, '60054924', '約束', '個人戦2日目が始まった。団体戦で活躍した選手が順当に上位へランキングされるなか、一人だけ聞き慣れない名前が浮かび上がる。それは、個人戦にのみ参加登録をしている平滝高校の選手だった。やがて午前の闘いが終了し、ランキングを確認をする和は信じられない光景を目撃する。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/04ee44f1-725b-4256-8070-7e51001fe7f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5be7405-92ea-4bb0-b1df-fba9c2ef3425', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 23, '60054925', '本気', '全国出場の枠をかけた個人戦も、ついに最終局面を迎える。残された対局数で、これまでの分を取り返そうと奮闘する咲だったがステルスモードとなった桃子に苦戦を強いられる。そんな時、咲は強化合宿での特訓を思い出す。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2e905ac1-1189-42a5-bd96-a55de7972758.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f8b0193c-1237-432d-ab88-f2f5cd9de191', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 24, '60054926', '夏祭り', 'みんなで夏祭りに行こうと楽しみにしていた矢先、期末試験で優希が赤点を取ってしまった!追試に向けて優希の勉強を手伝う咲と和だったが、優希がなかなか勉強に集中してくれない。同じ頃、龍門渕、風越、鶴賀の麻雀部宛に一通の手紙が届く。差出人は久で、清澄を含めた4校合同合宿の誘いだった。', '2018/06/14 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/be3e1e09-402a-48b3-bf6a-dfc61e3de1c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12a9576b-408c-4ead-bd2d-0b1dc2383ac7', '3b65a472-c9f0-4a50-a44e-ca0fdd7ea371', 25, '60054927', '全国', '【シーズン1 最終話】団体戦の決勝メンバーで行われる4校合同合宿がついに始まった。しかし合宿所に着いた早々、みんなでお風呂に入ったり卓球勝負が繰り広げられたりと、なかなか特訓が進展しない。それでも、学校の垣根を越えた交流は、咲と和にとって、かけがえのない時間となっていた。', '2018/06/14 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0d61897d-ebb7-42eb-9d75-51c4c999e313.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dd7f43e2-cc1c-48bd-8ce5-96b25c6b02a3', '咲-Saki-阿知賀編 episode of side-A', '', 'hulu', 'saki-achiga-hen-episode-of-side-a', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fc60071f-9c16-468a-a0c8-f873b6ad4761.jpg?w=331&h=447&p=t', 'hulu', 2012, 1, 1, 'FINISHED', NULL, 10884, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('70e56670-0d0e-4980-9cb5-bc09646317f7', 'dd7f43e2-cc1c-48bd-8ce5-96b25c6b02a3', 'hulu-saki-achiga-hen-episode-of-side-a-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce903c68-2c2d-414c-82ac-3cbea2c85e23.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8238180-3c85-4241-8501-22bf0afcc0c0', '70e56670-0d0e-4980-9cb5-bc09646317f7', 1, '100027657', '邂逅', '東京から転校生してきた小学生の原村和は、同級生の高鴨穏乃と新子憧に誘われて赤土晴絵が開いている麻雀教室に通うようになる。クラブでは年上の松実玄とも知り合い、楽しい日々が続いていた。だが、晴絵が実業団からスカウトを受け、麻雀教室は終わりを迎えることに。さらに中学へ進学したあとで和の転校が決まってしまい、かつての仲間が集まることは無くなってしまった。そんな中学3年生の夏休みに穏乃がテレビをつけると衝撃が走る。そこには全国中学生麻雀大会の優勝者として、原村和が映っていたのだ。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce903c68-2c2d-414c-82ac-3cbea2c85e23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c884a03-abd1-42b1-a137-2d12db9003cf', '70e56670-0d0e-4980-9cb5-bc09646317f7', 2, '100027658', '始動', '和の活躍に触発された穏乃、憧、そして一人麻雀教室を守っていた玄の三人は、インターハイで和と会うために、阿知賀の麻雀部を復活させようとしていた。そのためには残り二人の部員が必要だということで、部員の獲得に奔走する三人。そこでターゲットとなったのは、玄の姉で極度の寒がりの松実宥と、幼少時から麻雀を経験していた鷺森灼だった。宥は麻雀部への入部に快く応じてくれたが、灼は入部については了承したが、晴絵のことでわだかまりがあった…。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17ba93d4-e8b0-43ac-8f1b-81b1f2eb311e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a53a24c3-5035-4783-bfd4-38798009c3c7', '70e56670-0d0e-4980-9cb5-bc09646317f7', 3, '100027659', '接触', '阿知賀に戻ってきた赤土晴絵をコーチにむかえ、本格的に活動を開始した阿知賀女子麻雀部。日本リーグで活躍した晴絵の指導と猛特訓の末、ついに迎えたインターハイの県予選。1回戦では優勝候補である「晩成高校」の大会10連覇を阻止し、全国大会への出場を決めた。しかし、全国には思いも寄らない強さを秘めた者たちが沢山いる。そこで晴絵の提案で各県のNo.2と練習試合をする旅に出ることに。そこでまず最初に向かったのは長野県の予選第2位、「龍門渕高校」だった。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4377c2d7-0f1a-4dc0-9c4a-ba805c138a64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5a4cb3e-7f90-4f05-bf70-3368d717cf2e', '70e56670-0d0e-4980-9cb5-bc09646317f7', 4, '100027660', '全国', 'ついに全国の舞台を踏んだ阿知賀女子麻雀部。しかし、和がいる清澄高校はトーナメント表の逆サイドに位置していた。つまり、和と相対するには決勝進出しか道はない! 高い目標を定めて迎えたインターハイ第1回戦は、玄の爆発力ある麻雀が見事に炸裂! 後続のメンバーもそれぞれの持ち味を生かして初戦を突破! 順当に駒を進めることに成功した。しかし続く第2回戦の対局室で、玄は見覚えのある人物と遭遇する。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a7d68a2-cc21-43e9-ac7a-624ac9a5ee1f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2dd52af-4a8a-441e-a000-e38a9a08e592', '70e56670-0d0e-4980-9cb5-bc09646317f7', 5, '100027661', '強豪', 'インターハイ第2回戦の先鋒戦。玄の相手は、東京へ向かう途中のサービスエリアで出会った千里山女子のエース「園城寺怜」だった。対局中、玄はドラが多く集り、不自由になったところを、怜に不思議な打ち回しで和了られる展開が続く。また、リーチをかけた後は誰かが鳴かない限り、確実に一発ツモを成功させる。怜が打つ麻雀は、まるでほんの少し先の未来が見えているかのような打ち方だった。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5c44cce-67fa-4b44-ac1b-00580b654825.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6ba814b-b669-436d-a8fb-45199be3b9a1', '70e56670-0d0e-4980-9cb5-bc09646317f7', 6, '100027662', '奪回', '阿知賀のエース、先鋒の玄がまさかの大量失点で最下位に!! これまでになかった状況だが、姉の宥が妹、玄の雪辱を果たすべく次鋒戦に挑む。対する千里山女子の二条泉は、宥との対戦に自信を持っていた。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51aaf596-576e-443f-819d-234c33537e27.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65dc608c-bcfb-47aa-8d7e-ec6dcaa5d16d', '70e56670-0d0e-4980-9cb5-bc09646317f7', 7, '100027663', '信念', '一度は最下位まで落ち込んでしまった阿知賀女子麻雀部だが、次鋒の宥、中堅の憧が意地を見せてなんとか2位まで浮上する。しかし副将戦では劔谷の選手が絶好調で大物手を炸裂させる。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c0ec292-bb61-4d8b-a581-c8793cf0f7b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1575c5e5-f720-4a14-8853-175088b5facf', '70e56670-0d0e-4980-9cb5-bc09646317f7', 8, '100027664', '修行', '清澄高校の応援にきていた鶴賀学園の東横桃子に偶然出会ったことから、蒲原の祖母の家に招待されることになった阿知賀女子麻雀部。そこで穏乃は、「明日までに強くなりたい」と加治木ゆみに告げる。彼女たちの熱い気持ちを理解した加治木は、蒲原にある人たちをここへ呼んで欲しいと伝える。それは…。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01ba922e-5939-459b-905d-d682a34f7029.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65b73aca-8a62-4888-bcc8-a43c902f1863', '70e56670-0d0e-4980-9cb5-bc09646317f7', 9, '100027665', '最強', '阿知賀女子、千里山女子、新道寺女子、そして前年度優勝校の白糸台高校。四校による準決勝がついに始まった。最強の高校生、宮永照に立ち向かう玄たちに対し圧倒的な力で和了を重ねる照に対抗したのは、意外にもあの高校であった…。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/296a5140-a7aa-4a7f-8079-782ccf3521b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('254b5188-d427-4050-b17f-a3782a2c33e8', '70e56670-0d0e-4980-9cb5-bc09646317f7', 10, '100027666', '連荘', '準決勝先鋒戦も前半戦が終了。圧倒的な力を見せつけるチャンピオン宮永照。千里山の園城寺怜も1巡先を読むものの、追いつくことができずにいた。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf3cf5b0-a71a-437a-8070-a9dbf29dad3d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c7e1ff5-4463-4f08-b158-b87453fdffb3', '70e56670-0d0e-4980-9cb5-bc09646317f7', 11, '100027667', '決意', '準決勝先鋒後半戦。自分の体力を削りながら打つ千里山の園城寺怜は、新道寺の花田煌との連携プレイによってチャンピオン、白糸台の宮永照の連荘を止めにかかる。', '2018/12/27 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d662b77-6c22-4016-af2c-5a0838dac81f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b81c0d5e-3a1c-4711-95a0-a36c231e8c83', '70e56670-0d0e-4980-9cb5-bc09646317f7', 12, '100027668', '約束', 'ついにオーラスを迎えた準決勝先鋒戦後半戦。圧倒的リードを誇るチャンピオンの宮永照に対し怜、玄、煌の三人は最後の力を振り絞り反撃の一打を狙う。', '2018/12/27 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76b899b4-d766-4e82-886d-ce05f433c072.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d939d98-a42a-483e-a45f-a0d0e832be24', '70e56670-0d0e-4980-9cb5-bc09646317f7', 13, '100027669', '混戦', '波乱含みの準決勝先鋒戦を終え、戦いは次鋒戦へ突入。倒れた怜を思いつつ、堅実な打ち回しで二位キープを狙う千里山女子、二条泉。しかし、新道寺女子、安河内美子の初和了りから試合は混迷を極めていく。', '2018/12/27 00:00:00', 1795, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44c5a625-efeb-4cfb-85f5-8b9a4212e6b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('535a2f9d-de87-476d-8d98-4187cf610783', '70e56670-0d0e-4980-9cb5-bc09646317f7', 14, '100027670', '憧憬', 'インターハイAブロック準決勝中堅戦を終え原点復帰した阿知賀女子。多くの人の想いを胸に秘め試合に臨む副将の鷺森灼だったが、白糸台高校2年の亦野誠子に先制をゆるしてしまう。', '2018/12/27 00:00:00', 1798, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b36d9db6-f370-45d7-aa30-c0161fb2ff86.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5661c1e0-c80a-4c46-b937-6c5976c769b7', '70e56670-0d0e-4980-9cb5-bc09646317f7', 15, '100027671', '激化', '点数に大きな動きがあった波乱の副将戦を受けて始まった大将戦。それでも余裕の表情を崩さない白糸台高校1年大星淡に対し、新道寺女子2年鶴田姫子と千里山女子3年清水谷竜華が牙を剥く。', '2018/12/27 00:00:00', 1799, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a1293e7-c408-41ef-9fdb-db99de53f475.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47755369-790e-4065-9c02-c6cfbaa2cf86', '70e56670-0d0e-4980-9cb5-bc09646317f7', 16, '100027672', '軌跡', '【最終話】インターハイ準決勝Aブロック大将戦、決勝への2枚の切符を賭けた最後の半荘が始まる。本気になった大星淡に支配される卓上で吉野の山々を思い出し静かに微笑む阿知賀女子1年高鴨穏乃、その視線の先に映る結末は…。', '2018/12/27 00:00:00', 1798, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/362777f5-85df-4e3d-b266-af8f8bbbf65a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ed17c72e-db3d-422b-9ca5-41662ab5f190', '咲-Saki-', '', 'hulu', 'saki-zenkoku-hen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48e3d4c7-242a-4211-b6f6-0966483f1586.jpg?w=331&h=447&p=t', 'hulu', 2009, 1, 1, 'FINISHED', NULL, 5671, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 'ed17c72e-db3d-422b-9ca5-41662ab5f190', 'hulu-saki-zenkoku-hen-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5884244-7c8f-4d94-8a0e-8355a056770e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5cabcdf7-e7bf-44b0-bf03-6a0c6c57e3d5', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 1, '100028186', '上京', '熾烈な県予選大会を勝ち抜き、全国の舞台へと駒を進めた清澄高校麻雀部。全国各地でも続々と代表校が決まっていき、強豪たちが決戦の地へと集まっていった。そして、全国大会抽選会当日―。続々と各校の対戦相手が決定していく中、久が抽選を行った。果たして相手は―。高校生雀士の頂点を極める闘いが遂に始まる。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5884244-7c8f-4d94-8a0e-8355a056770e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc546754-63f8-4d5a-925f-5ee6b3543ced', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 2, '100028187', '応援', '抽選の結果、姉･照とは決勝まで進まないと対局できないことが分かった咲。照への思いを胸に、必ず決勝まで進むことを再び決意する。遂に迎えた全国大会初戦当日。会場に着いた久の携帯電話に学生議会副会長から緊急の電話が入った。怪訝そうに電話に出る久だったが、その内容は清澄高校の仲間たちからの応援メッセージだった。予期せぬ応援に感激する清澄高校麻雀部一同。一方、久は夏の合同合宿を思い起こしていた…。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/561a3b93-65b5-4cb8-9858-24763975e0d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62793d81-10e2-4a9a-903a-f6c2a4526e76', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 3, '100028188', '始動', '合同合宿で久が「この合宿の真打ち」と呼んだのは夢乃マホだった。次々と清澄高校麻雀部の打ち筋を再現するマホの姿に咲は脅威を感じるのだった。一方、咲以外の清澄高校のメンバーたちも他校との交流戦を重ね、全国大会への準備を整えていった―。舞台は再び全国大会へ。各ブロックの強豪たちが次々と1回戦突破を決めてゆく中、清澄高校の闘いぶりが会場を賑わせることとなる。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e8882a1-74ef-4890-ae66-e0c1324c8d99.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b823dabb-0f8e-477b-af3e-b6f9711821cb', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 4, '100028189', '東風', '久の活躍により一回戦を和、咲まで回すこと無く終えた清澄高校麻雀部。姫松高校、永水女子高校、宮守女子高校という屈指の強豪校に対し、優希の起家から二回戦がスタートした。得意の速攻で早速波に乗り連荘する優希。その姿に姫松高校の上重漫はうろたえるが、宮守女子･小瀬川白望と永水女子･神代小蒔は静かに状況を見つめていた…。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/253a170d-85ca-4119-ac6c-29b80ee8d7d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32df6974-1490-4aa3-aa6d-e309183a663f', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 5, '100028190', '神鬼', '宮守女子･小瀬川白望の跳満ツモを受けながらも、依然順調のまま先鋒戦を進めていく優希。しかし、先鋒戦後半も佳境に差し掛かった時、永水女子･神代小蒔の力が遂に発揮される。ただならぬ雰囲気はモニター越しに戦況を見つめる咲にも伝わり、思わず震えを覚えるのだった。先鋒戦後半オーラスの行方はいかに…。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1b5d383-b8f6-4ec5-8a3d-0b463e4f10ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('720ed669-c07f-4090-a138-b3f9d3c88ded', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 6, '100028191', '萎縮', '健闘したものの、宮守女子･小瀬川白望と永水女子･神代小蒔の前に3位で終了した清澄高校麻雀部。地方大会での圧倒的な強さを見せた宮守女子･エイスリンの活躍が予想された次鋒戦だったが、まこの翻弄するような打牌により清澄高校はトップで中堅戦へ突入する。他校の誰よりも早く会場へ足を踏み入れる久だったが、試合を目前にして未知の感覚に襲われるのだった。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a89ac86-0cad-4654-ac8e-1d35ec8f77b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81b1521f-59cd-48ea-9698-dce7a1c78526', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 7, '100028192', '注目', '全国の舞台を、麻雀を、楽しむ―。対戦相手の前に改めて大事なことに気付かされ調子を取り戻した久。しかし中堅戦前半で大きくリードを伸ばした姫松高校･愛宕洋榎には届かず、2位で中堅戦は終了。副将戦の会場に入った和だったが、永水女子高校･薄墨初美の衝撃の登場に驚き、和の手を離れたエトペンが絹恵の足元に転がっていき…。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d75ac1d3-5d4d-4c9b-9a4d-dfd61bd86140.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3612716-c4a0-4f9e-b35b-346c506f31c5', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 8, '100028193', '防塞', '副将前半戦から完全に自分のスタイルを見せつける和。その脳裏には「負ければ離ればなれになってしまう」という強い気持ちがあった。対局は進み、永水女子･薄墨初美が北家となり、初美の四喜和を警戒する絹恵と塞。しかし、和から切られた北を初美がポン、四喜和へのきっかけである鬼門が完成してしまう。手を進めていく初美だったが、ここで臼沢塞が動くのだった。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a421f0b7-5d80-433b-8644-147a44ab7c3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80c78f0b-c3d2-4ecc-9792-4df3064065c0', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 9, '100028194', '出撃', '宮守女子高校･臼沢塞の力により、完全に封じられてしまった薄墨初美。しかし、北家のたびに初美を抑えこんでいた塞の体力は限界へ―。対局は最後の初美の北家となり、手牌から東、北を出さないよう注意していたが、和の出した東をポン、さらに初美は北を暗槓し、小四喜を上がり切るのだった。波乱の副将戦を終え、ついに雌雄を決する大将戦の火蓋が切って落とされる。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba705b33-3fd2-4cfd-802f-18b29b68f535.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e3dc6bd-7d43-48de-93de-b2e71b2efc0a', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 10, '100028195', '仲間', '大詰めをむかえる全国大会ニ回戦。姫松高校･末原恭子が果敢にリーチを繰り返すものの、宮守女子高校･姉帯豊音のおっかけリーチにことごとく振り込んでしまい大将戦前半は終了。休憩の後、二回戦最後の半荘が始まった。前半豊音の様子からリーチをかけずに手を進めていく他校の面々。しかし、ここで豊音が予想外のポン。次々と鳴いて手を延ばす豊音。その真意とは…。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35f08685-b02f-4e30-85f4-21ab685a51ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd82106b-f903-4fab-a589-a59778c3d00a', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 11, '100028196', '脅威', '守りだけでは勝ち抜けられなくなった永水女子高校･石戸霞は「攻め」へと転じることとなる。霞の攻勢により戦局は一転。一位で大将戦に臨んだ姫松高校はトップから陥落していた。さらに配牌は霞の力により絶一門の状態―。窮する姫松高校･末原恭子だったが、この絶一門の状況でとある経験を思い出すことになる。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ca862f7-8914-4b1a-8bd8-d9bd8e81f448.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9eb02162-6c50-45b7-b662-14b14962476a', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 12, '100028197', '真実', '大将戦もついに雌雄を決する南場へと突入。ここで咲は大明槓からのツモ切りと、これまでの闘いでは見せなかった打牌をする。その意図は絶一門を脱するためのものだった。このズレにより姫松高校･末原恭子が倍満をツモ。各校最後まで突破、脱落の可能性を残したまま、最終局面であるオーラスを迎える…。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd74065d-922b-4a58-9dcc-ad4b10bac009.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f78510b-784f-49e3-9076-b95f8135ff24', 'a79a3e17-0b8d-43c0-80bc-e26d2c9a46fe', 13, '100028198', '旧友', '【最終話】各校全く退くことがなく過酷を極めた2回戦だったが、咲の活躍により、準決勝進出を決めた清澄高校。パンフレットに「阿知賀女子」の名前を見つけた和に誘われ大会会場へと向かう咲だったが、直前のところで立ち尽くしてしまう。一方、会場へと足を踏み入れた和はかつての仲間、阿知賀女子の面々との再会を果たすのだった…。', '2019/01/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84719e06-5b04-47f9-9eb0-6621b6f6c64c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('aa07d165-a113-46d3-b56e-347f04aa0084', '咲う アルスノトリア すんっ！', '', 'hulu', 'smile-of-the-arsnotoria-the-animation', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3e0391d-379d-4865-9d07-94fa3f9c8a8a.jpg?w=331&h=447&p=t', 'hulu', 2022, 2, 1, 'FINISHED', NULL, 149874, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 'aa07d165-a113-46d3-b56e-347f04aa0084', 'hulu-smile-of-the-arsnotoria-the-animation-s1', '第1シーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a98120ac-4778-490b-bfca-aaa50090cf32.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ba06195-1edc-48b0-9918-63ed3b549220', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 1, '100117155', 'すんすんすーん', 'アルスノトリア･メル･小アルベール･ピカトリクス･アブラメリンの5人は、今日も〈あの部屋〉に集合! いつも通りの楽しいお茶の時間 (ティータイム) と思いきや、スコーンの食べ方を巡ってひと勝負することに…!?', '2022/07/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a98120ac-4778-490b-bfca-aaa50090cf32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b17f6e3e-d5cd-4b1d-ab0f-55c366c92d75', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 2, '100117664', 'ぎゃーーーーーーー!!!', 'いつ現れるとも知れない〈蟲〉から学園を守るため、本日の〈防除係〉を行うことになったアルスノトリア。メル･小アルベール･ピカトリクス･アブラメリンも手伝いに駆けつけ、協力しながら係活動を進めていく。しかし教師の影猫ペルデラの一声で、学園内は大騒ぎ!?', '2022/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3bebf9f-547a-4375-a30f-41658736515c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91368e11-0d47-444a-879a-a34ab2c85f86', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 3, '100118142', 'すーん………', 'ある朝、〈匂い〉が分からなくなってしまったアルスノトリア。それに気づいたメル･小アルベール･ピカトリクス･アブラメリンは、アルスノトリアの嗅覚を取り戻すため“すごい匂い”を集めてショック療法を試みることに。', '2022/07/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a250b2ff-b0fd-423f-b936-34f994612acc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8ce2598-f958-4b88-992b-a2e7f90b82fe', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 4, '100118831', 'リーーーンゴーーン', '今日は〈夜の特別授業〉の日。アルスノトリアたちは、真夜中の校舎を楽しみながら、魔法植物学の実習を受けるため学園長ソローのもとへ。月明かりに照らされた温室にいくと、そこには見たことのない光景が広がって…!', '2022/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a915f7fe-3932-4ab4-88c0-f6b62619845e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5f7e4f6-8b90-4aff-9409-db71b7e29f4c', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 5, '100119489', 'すー……', '今日は〈休日〉! メルと小アルベールは下級生たちと“かくれんぼ”を、ピカトリクスは宿題を、アブラメリンは調べ物をして過ごす一方、アルスノトリアは遅めのランチを一緒にとろうと“ある人”がいる至書塔へ向かう。', '2022/08/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78bd618a-19fc-4971-bd35-16588f7462a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba98dc8a-c641-452e-9f87-3622a0f4e32f', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 6, '100120104', 'しー', '学園から出て下界に〈おつかい〉へ行くことになったアルスノトリアたち。当初予定していた精霊の営むお店だけでは品物を揃えることができずに困ってしまうが、思わぬハプニングから手に入れる方法を思いつき…!?', '2022/08/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fbdd04a-c4a5-4506-ad82-24c96db4ff97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0087892-bfd3-4be8-bf15-2f32dae7380f', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 7, '100120576', 'ノ～ノ～ノ～', '〈倫敦の新聞〉で読んだ“流行の髪型”を再現しようとするピカトリクス。せっかくだからと、みんなでオシャレをすることに。飾り用の羽根を手に入れるため、アルスノトリアたちは校舎内に鳥の巣箱を置くことを考える。', '2022/08/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4a2b000-ac0e-4835-839f-007bcbe8d060.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3813331e-304c-45de-b742-6b98663fbaff', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 8, '100121401', 'わーーーーー', '小アルベールが〈行方不明〉!? 教室棟へ向かう途中で急にいなくなってしまった小アルベールを見つけるため、学園中を探し回るアルスノトリアたち。すると『教室の壁から謎の声が聞こえてくる』とリデルが大慌てでやってきて…!', '2022/08/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f867b96a-7dd6-4f74-9fe8-534ccbe3a8da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d51d8aa0-bb5b-4601-8902-3d65b367db2c', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 9, '100121866', 'う～う～うぉ～～', 'ある朝、アシュラムが〈一面の銀世界〉に。ペンタグラムたちは初めての雪に大はしゃぎ! メルと小アルベールの提案により、“雪でかき氷”を作ることにしたアルスノトリアたちは、キレイな雪を探して学園の一番高いところへ。しかし雪がどんどん吹き荒れてきて…!', '2022/09/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/762eac4c-d614-411f-8b09-99e9494ee590.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bed72578-ed53-4d8a-8758-69031dc05595', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 10, '100123080', 'すすすすーーーー', '学園長ソローがひらく〈淑女の歩き方を学ぶマナー教室〉に参加することにしたアルスノトリアたち。そこへ“裏生徒会長”とも呼ばれるヴェラムが現れて…。アシュラム名物ピカトリクスVSヴェラムの“ですわ対決”が始まる…!', '2022/09/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8321c7be-42da-454b-91fd-683d466d7452.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96d65917-86c2-4355-9cb9-46d2657f5ab9', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 11, '100123835', 'せーの', '廊下で拾った“謎の物体”を、幸運を呼ぶ〈猫のヒゲ〉ではないかと推測したアルスノトリアたち。本当に効果があるのか試そうとするも、“ヒゲ”を探しているという生徒エンキリディオン･仙伯･パラグラヌムがそれぞれやってきて…!', '2022/09/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f6ead72-97e3-4845-a5d2-8ee906b46c98.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f03d137-d4dd-4bac-9c8d-bfb4c10d2c4f', '2ba7bab4-6885-4dbe-9ccc-3c550fc7f929', 12, '100124087', 'すんっ!', '【第1シーズン 最終話】アルスノトリア･メル･小アルベールは、お茶の時間 (ティータイム) 用のお菓子を買って、ピカトリクスとアブラメリンが待ついつもの〈あの部屋〉へ! たっぷりの美味しいお菓子で、いつもより少し豪華なお茶会が始まる頃、遠くで鳴っていた雷の音が次第に近づいてきて…。', '2022/09/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db3512a6-d97a-4fea-bfb9-e0b2022a69e8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6c898122-1363-4b88-bf7d-d67939ae223e', '桜蘭高校ホスト部', '', 'hulu', 'ouran-high-school-host-club-anime', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41ab5500-bf19-4ef8-8026-8a318fef34ee.png?w=331&h=447&p=t', 'hulu', 2006, 1, 1, 'FINISHED', NULL, 853, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a5e0d564-e82e-4a34-bbff-2894c26d0c2e', '殺し愛', '', 'hulu', 'love-of-kill', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/29668669-8d36-460b-be3a-8080e888d363.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 127050, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ff38ed56-916d-4641-9e22-071aec94034c', 'a5e0d564-e82e-4a34-bbff-2894c26d0c2e', 'hulu-love-of-kill-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7d1e7ee-8439-4517-8f18-5502826f349b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76cd12ec-1644-4131-aa26-00175b7f9c7e', 'ff38ed56-916d-4641-9e22-071aec94034c', 1, '100101605', 'WHAT''S YOUR NAME?', '賞金首を追うシャトーは、とある仕事場で殺し屋のリャンハに遭遇する。それ以来、彼から賞金首の情報を提供されるようになるのだが、ある時リャンハをターゲットとした依頼が舞い込んでくる。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7d1e7ee-8439-4517-8f18-5502826f349b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b8c62dc-4b1e-4c9a-8fb2-1008a2d3fa29', 'ff38ed56-916d-4641-9e22-071aec94034c', 2, '100101987', 'TARGET', 'リャンハとの接触を社長に疑われながらも、独断でリャンハの用意した賞金首のもとを訪れるシャトー。しかし、標的を乗せて商会へ戻る道中、謎のバイクに襲撃されてしまうのだった。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dccd19bd-4f33-48b2-a8a4-c6bee3c056a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4ccb440-707a-4ddb-9623-11f530acafb0', 'ff38ed56-916d-4641-9e22-071aec94034c', 3, '100102701', 'ROOM', '襲撃を受けたシャトーは、リャンハに助けられモーテルで目を覚ます。相変わらず飄々としたリャンハに調子を狂わされ、さらにシャワー中、下着から何から勝手に洗濯されたことに青ざめてしまうのだった。別れ際、シャトーはホーが放った「裏切り者」という言葉を告げる。5年前、リャンハがある組織で犯した罪とは――。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fc8aa681-6d52-49d4-a8aa-b494da2e8b1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1eab66b4-208d-473c-94c0-75c254da5d6f', 'ff38ed56-916d-4641-9e22-071aec94034c', 4, '100103741', 'REAL FACE', '父親の命日に教会を訪れるシャトー。リャンハに遭遇し軽口を叩かれたのも束の間、そこへ襲撃者が現れる。リャンハが銃撃戦を繰り広げる間、シャトーはさらわれたシスターを追うのだが、そこにはホーが待ち構えていた。一方、社長はシャトーの母親アンナと面会していた。シャトーが関わっていた17年前の事件とは……?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e50dbf7f-e489-428c-a25b-39f8e9ad4508.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('727256af-44a3-487f-9eb2-44c1d017c52e', 'ff38ed56-916d-4641-9e22-071aec94034c', 5, '100104122', 'LIMIT', 'シャトーを人質に取られ、ホーの前に姿を現すリャンハ。過去の因縁から激しい憎しみに燃えるホーに対し、リャンハはあくまでも淡々と彼を追い詰めようとする。しかし、シャトーの命が危険にさらされていることに気づき……。一方、シャトーは爆弾の積まれた車に囚われていた。シャトーとリャンハ、二人に最大の危機が訪れる。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/058299b1-8013-4b0e-aeec-c9edb439514b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06644bb0-3407-4e09-bcf0-3f5c38fc1b27', 'ff38ed56-916d-4641-9e22-071aec94034c', 6, '100104767', 'DARK DREAM', '豪華客船で要人の周辺警護を担当するシャトー。しかし、突如としてリャンハが目の前に現れ、対応を余儀なくされる。リャンハの目的はわからないままだったが、仕事に支障をきたさないよう監視を兼ねてともに行動することになり、客室で一夜を過ごすことになってしまう。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53a0a60a-d564-45d6-bc39-b687a661166a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae6df09b-664b-4d11-9a41-3dffc80ff557', 'ff38ed56-916d-4641-9e22-071aec94034c', 7, '100105234', 'BULLET', '社長の行方を追うシャトーのもとへ、彼の回線から連絡が入る。だが、相手は社長ではなく、リャンハだった。指定された場所へ辿り着いたシャトーは、その惨状に絶句する。一方、謎の襲撃者と対峙するも逃げられてしまったリャンハ。シャトーの客室で彼女と合流するが、冷ややかな表情のシャトーに銃口を向けられてしまう。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75ee9ed3-8fb7-4bc7-aff6-7406dd44d9da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3fbab78-6195-4670-beac-895b82b9f85e', 'ff38ed56-916d-4641-9e22-071aec94034c', 8, '100105893', 'CONFUSION', '社長に続き、ジムの身にも危険が迫っていた。仲間たちを危険にさらした罪悪感から自暴自棄に陥ったシャトーは、リャンハの前で衝撃の行動をとるのだった。そんな中、客船は港町バロセラへ到着。リャンハは自ら取引材料となり、ジノンに投降。彼とその仲間ニッカに身柄を預け、ある場所へ移送される。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1e55afa-9c1f-4785-8f96-0b6aa3b114f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('007a4052-9ba7-4ee0-9503-bc9c148166d4', 'ff38ed56-916d-4641-9e22-071aec94034c', 9, '100106715', 'A WAR TRIGGER', 'ドニーと対面するリャンハ。ドニーがリャンハを連れてきた理由――それは、二人の過去にまつわる「因縁」とも言えるものだった。そして、囚われのリャンハにジノンとニッカの狂気が迫る。一方、リャンハに借りを作ってしまったシャトーは、彼の行方を追うためにある決断をする。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1220e9e4-4e66-49ba-aa34-e930c3fb27d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5ef9e28-877c-42eb-ac39-a9335e0e9aeb', 'ff38ed56-916d-4641-9e22-071aec94034c', 10, '100107308', 'HELP', 'ドニーの屋敷から逃れたシャトーとリャンハは、協力者のいる橋の下のテントへ身を潜める。傷を負ったリャンハを気づかおうとするシャトーだが、リャンハに押し倒された挙げ句、身元を隠すため夫婦を演じることになってしまう。一方、ドニーはリャンハを逃したニッカに、再度チャンスを与える。だが、本当の狙いは別にあった。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e0be24a-6c7e-4026-a91f-d5e41db19d17.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0ac4766-06e2-49b1-b9aa-390d682736a2', 'ff38ed56-916d-4641-9e22-071aec94034c', 11, '100107768', 'WORST', 'すべては17年前――ドニーの手伝いをしていたリャンハと、ある少年の出会いから始まった。何者かに追われていた少年に遭遇し彼をかくまうリャンハ。数日で別れるはずだったが、リャンハは少年を「仕事」に巻きこんでしまう。二人が依頼人から預かったスーツケースを空けると、そこには一人の少女が眠っていて……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60e1d7ab-c459-44eb-9c58-6c59b4dcd528.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('98ed8474-8d98-4239-b1c9-a0e869042806', 'ff38ed56-916d-4641-9e22-071aec94034c', 12, '100108814', 'MY NAME', '【第1シリーズ 最終話】幼いシャトーを連れて必死に生き抜こうとする、二人の「リャンハ」。だが、追っ手と対峙するリャンハは追い詰められてしまい、もう一人のリャンハもまた大きな傷を負ってしまう。それでも二人は、シャトーを守ろうと決死の覚悟で前を向く。「終わり」にして「始まり」の物語は、未来のシャトーとリャンハの運命へと繋がっていく。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b6fce46-a53a-49b7-bd65-8529df54ea01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5f99b076-2959-4da8-aa5b-830442f37986', '殺せんせーQ！', '', 'hulu', 'koro-teacher-quest', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6de7e776-883a-4293-980c-d8da513cecd9.jpg?w=331&h=447&p=t', 'hulu', 2016, 3, 1, 'FINISHED', NULL, 21864, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('776a34eb-5782-41f3-9102-92d3677e7ab3', '5f99b076-2959-4da8-aa5b-830442f37986', 'hulu-koro-teacher-quest-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5424df28-c723-472c-9319-7fb5a3fdd593.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5eb018b-6ded-4911-98f1-c19f881550f2', '776a34eb-5782-41f3-9102-92d3677e7ab3', 1, '100139482', '魔王とE組', 'クヌギガオカ魔法学校では、勇者になるための勉強を教えてくれる。しかし、おちこぼれクラスのE組にはある秘密があった! それは、担任が、魔王だったことだ!', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5424df28-c723-472c-9319-7fb5a3fdd593.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8bb16af2-2276-4731-aa7e-fe100f4440e4', '776a34eb-5782-41f3-9102-92d3677e7ab3', 2, '100139483', '赤い悪魔', '魔王「殺せんせー」を倒すべく、生徒たちは「赤い悪魔」と言われる天才魔法剣士･赤羽業をクラスに引き入れようと画策するが…?', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb5d7181-b6fb-41c8-96fc-85cf9e6ab8e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff3acc91-849c-41c4-aaba-feb207761c41', '776a34eb-5782-41f3-9102-92d3677e7ab3', 3, '100139484', '誘惑の魔女', '烏間騎士長のはからいで装備を買いに街にやってきたE組だが、そこは誘惑の魔女･イリーナの魔の手にかかっていた。彼女の魔法で次々に僕 (しもべ) にされてしまう男子たちと、殺せんせーも!? 絶体絶命のピンチ!', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffb0d8a0-81d8-4afe-be4c-83dbf323b015.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0cd57466-631f-4314-a3a4-27304d205676', '776a34eb-5782-41f3-9102-92d3677e7ab3', 4, '100139485', '試練の遺跡', '法王･浅野學峯登場! 魔王なのに教師をしているという殺せんせーの真偽を確かめる為、法王は「試練の遺跡」で殺せんせーとE組のテストを行うことに。そこで待ち構えていたのは…。', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7222bc9b-1d70-4498-9f83-a2d6d92e700f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53544e74-ac85-412e-bd86-d41f8c8072e0', '776a34eb-5782-41f3-9102-92d3677e7ab3', 5, '100139486', '進化の魔術師', '進化の魔術師と恐れられる自律思考魔道石板、通称「律」が転校してくる。律はあらゆる魔法を自分のためだけに使い、チームワークに活かそうとしない。殺せんせーはそんな律に協調性の大切さを教えようとするが…?', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aaa1068e-d3c4-4340-be60-2a0bbeedc1e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0146243b-1de1-424b-b3ae-0f757d6d3da8', '776a34eb-5782-41f3-9102-92d3677e7ab3', 6, '100139487', '銀の狂戦士', '律に続き、銀の狂戦士イトナまでもがE組に! 同じく触手を持っているイトナと殺せんせーは、どちらが魔王にふさわしいか、バトルを開始! 果たしてその勝敗は!?', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5c9b5b7-6d36-45cd-9486-a49e3431e6d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c846ad7-c6eb-4727-9ce5-a214deb5c05a', '776a34eb-5782-41f3-9102-92d3677e7ab3', 7, '100139488', '襲撃! 五英傑!', 'なんでも一番じゃないと気が済まない浅野学秀率いる聖騎士の中のエリート集団、五英傑がE組にやってきた! 狙いは魔王殺せんせー! どうなる殺せんせー & E組!', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b600fa59-524a-4b93-91ef-cae964dec820.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aea2d786-5498-4e21-a7a1-0a0cc8d80b27', '776a34eb-5782-41f3-9102-92d3677e7ab3', 8, '100139489', 'オレが魔王で 魔王がオレで', '伝説のアイテムが入っているとされる宝箱を開けたE組生徒と先生たち。と、それは、なんと精神と肉体が入れ替わってしまう魔法だった! 渚はカルマと、前原は磯貝、そしてなんと殺せんせーは!?', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43cae4d7-78d8-434e-acde-ea710dbdae87.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7965d780-992e-4440-932c-2289c8848e8f', '776a34eb-5782-41f3-9102-92d3677e7ab3', 9, '100139490', '決戦! 伏魔の塔', '(小娘に間違えられた) 渚を人質にして魔王殺せんせーを呼び出す鷹岡! 渚救出に向かうE組達に立ちはだかるのはガストロ、グリップ、スモッグの手練れ達!', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4511a38-c5f1-4ca9-b003-f24ca14a7bbe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50c6c334-7d83-4da3-8e44-943ab0eb8468', '776a34eb-5782-41f3-9102-92d3677e7ab3', 10, '100139491', '竹林、E組やめるってよ', '季節はバレンタイン。3-Eも盛り上がりを見せる中、竹林が突然E組を抜けて聖騎士団に入ると言い出した! 竹林に一体何が!? あの手この手で引き留めようとするクラスメイトだが…? エンディングにもご注目。', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1e619bc-349d-49fb-933e-94b4e017fa85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b785e761-5ca1-40d4-a80c-97294e4a6ad6', '776a34eb-5782-41f3-9102-92d3677e7ab3', 11, '100139492', '転職? 天職?!', '殺せんせーはなぜ勇者から魔王になったのか!? その謎がついに明かされる! 先代の魔王はなんとあの人!? 弟子も登場! 1年程前、勇者としての伸びしろに悩んでいた彼は転職を決意して…。', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da8cbc65-6a08-4732-83d3-083a04c7c29e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0e3d1f3-d24d-478d-b38c-76ffa8ff03b1', '776a34eb-5782-41f3-9102-92d3677e7ab3', 12, '100139493', 'BYE BYE魔王', 'さよなら、魔王殺せんせー!? さよなら、3年E組!? ついに最終回!「私の卒業式を執り行います。みなさん盛大に見送ってください…」その時、“彼”のバグが炸裂する!!', '2023/03/22 00:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dfecac4c-fb23-4190-89ab-3ca25bc7b8cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c4eb7fdd-5c03-4647-b40c-ebeba2f0e7d2', '錆色のアーマ-黎明-', '', 'hulu', 'rustedarmors', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f135b55-64ba-4df6-b7db-e6fb5303e77d.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 109820, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b3e08826-4f0c-4a61-9ea0-f8198acc0b40', '山田くんと7人の魔女', '', 'hulu', 'yamada-kun-and-the-seven-witches', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1df1af69-662f-42e9-b91b-7dfeb9525388.jpg?w=331&h=447&p=t', 'hulu', 2015, 1, 1, 'FINISHED', NULL, 20966, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5448263d-c547-4250-b296-8aebc3415239', 'b3e08826-4f0c-4a61-9ea0-f8198acc0b40', 'hulu-yamada-kun-and-the-seven-witches-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fea59c7b-3a55-402e-9b7e-f5a09625cc1c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c572f05e-a6b3-4274-91b7-3f61870b99f7', '5448263d-c547-4250-b296-8aebc3415239', 1, '100168698', 'アイツになってんじゃねーかぁぁッ!', '私立の名門朱雀高校に通う2年生･山田竜は、遅刻早退はもちろん、あちこちでケンカ三昧、授業中に居眠りまでする超問題児。ある日、優等生の白石うららと階段から転げ落ちた山田は、意識を失って保健室で目を覚ますと、自分の体が白石うららになっていた!? どうやら「キス」に秘密があるらしい。一刻も早く元に戻りたい山田。ところが、うららの姿になったことで女子の世界がいろいろと見えてしまう。うららの抱える事情にケリをつけた山田は、うららと「キス」をすることでようやく元に戻れたが、その瞬間を生徒会の宮村虎之介に見られてしまって……!', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fea59c7b-3a55-402e-9b7e-f5a09625cc1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d55ae4f3-ec7c-46c6-8263-5e62506757c1', '5448263d-c547-4250-b296-8aebc3415239', 2, '100168699', '俺とキスしな', '山田、うらら、宮村の3人が超常現象研究部 (超研部) の活動を再開させたところに超常現象好きの伊藤雅が現れた。キスをするためだけに部室を利用したい山田たちは、得意気に超常現象グッズをチラつかせる雅に本当のことを言い出せない。そんな中、雅がいないうちに入れ替わろうとした山田とうららは、キスの瞬間をうっかり雅に目撃されてしまう。「絶対に許さないんだから!」。仲間ができた気持ちを裏切られた雅は怒り心頭で山田とうららの噂を学校中に流して回る。噂のせいでうららが孤立してしまうことを気にする山田は、雅を呼び出して噂を撤回させようとするが、雅は言うことを聞かない。そんな雅に「俺とキスしな」と山田は迫る!', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d4b5f19-9a54-4157-9fc0-6796f7bd0076.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fdf2291-316c-4f7f-b9a8-e8d4a3343992', '5448263d-c547-4250-b296-8aebc3415239', 3, '100168700', '受ける? それとも受けない?', '「部費が足りねぇだぁ!?」。生徒会から部費がもらえず、超常現象の研究がはかどらないと不満気な雅。部費に興味の無かった山田だが、大好物の焼きそばパンを温められる電子レンジを買えるっぽいとわかり、手のひらを返す。早速部費の交渉に生徒会長･山崎春馬の元を訪れるも、山崎は女子の話しか聞かないらしい。山田はうららと、宮村は雅と入れ替わって交渉するが、山崎に即バレてしまった!? 山崎は部費を出す代わりに「生徒会の抱える問題」を解決してほしいと言い出す。その問題とは、優等生の白石うららが進学を希望していない、というものだった。「何で白石は進学する気がねえんだ!?」。', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/86400ae7-6cf4-4d97-bc2b-1f6af276a280.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51a151de-5f44-4821-a8b5-a39c9a434994', '5448263d-c547-4250-b296-8aebc3415239', 4, '100168701', '山田のことが好きになったみたい!', '「今日から林間学校かー」。気乗りしない山田だったが、うららと入れ替わってやりたいことを満喫する。「これで少しは楽しめそうだぜ」と山田。でも、うららは女子の輪になかなか入れずにいた。そんなうららの背中を押してやる山田。うららは徐々にクラスの女子と仲良くなっていくのだった。そんな中、宮村と次期生徒会長の座を争う小田切寧々が山田の前に現れた。うららと入れ替わっている間に、バレたらヤバイ写真を寧々に撮られてしまう山田。宮村との勝負に勝つためなら手段を選ばない寧々は、写真をネタに白石うららが模試を受けるのを阻止しろと山田に命令してきた!', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/018ecc7d-6bb3-49ff-b4b8-8567d446e081.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f412e59-8798-49ba-bd08-743731069da0', '5448263d-c547-4250-b296-8aebc3415239', 5, '100168702', 'キスしちゃダメよ?', '「白石には内緒にしとけよ!」。キスの能力が『虜』に変わってしまったことをうららに黙っておくと決めた山田だったが、そんな時に限ってうららから入れ替わりの催促が。早く小田切寧々に会って能力を元に戻さねーと!! 一方の寧々は、キスで『虜』になったはずの山田が自分の前に姿を見せずイラついていた。山田のことが気になるから様子を見に行くと言い出す寧々を、おかしいと感じ始める側近の五十嵐潮。山田を探す寧々と五十嵐は、山田とうららがキスをする瞬間を目撃。それを見て涙を流す寧々。逆に寧々の方が山田に惚れてしまったのだと五十嵐は確信する。怒った五十嵐は山田を蹴り飛ばした!「小田切寧々に何をした!?」。', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16a590bc-bdee-4036-883f-ab9ef35667cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f92baafb-c0b0-4696-bced-cdfd423393fb', '5448263d-c547-4250-b296-8aebc3415239', 6, '100168703', '応答せよっ!', '「夏だ! 海だ! 合宿だ!」。魔女伝説のノートの下巻を見つけるためにクラブハウスで合宿を開く超研部。でも山田は、漫画研究部の大塚芽子、鶴川秀明、亀田満たちと追試アンド補習合宿に強制参加させられ、テンションは急降下。おまけにノートの下巻があるらしい倉庫のカギもまだ開けられないときた。そんな山田に「明日は入れ替わってあげる」と救いの手を差し伸べるうらら。おかげで海を満喫でき、ついでに追試までクリアーだ! と思いきや、山田は急に元の体に戻される。なんでも補習合宿の時、芽子が突然キスをしてきたというのだ! その行動を見てうららは、芽子のことを魔女だと断言する。', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f808a69-ac35-40c5-b34e-c2e77762475e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e698ace8-0d51-4767-ab6a-116ff2b75672', '5448263d-c547-4250-b296-8aebc3415239', 7, '100168704', '天ぷらだけはやめてくれぇ!', '魔女探しを始めた山田は、引きこもって学校を休んでいる4人目の魔女･猿島マリアの家を訪れる。マリアと二人きりになった山田は、彼女の能力が「キスをした相手の未来を見る」ものだと聞かされる。マリアが学校を休む理由は、朱雀高校の旧校舎が火事になる未来を見ちまったから!? しかも、マリアはその犯人にされてしまうらしい!! んでもって、山田まで犯人扱い!? 山田は火事の真犯人を突き止めるため、マリアとキスをして能力をコピー!', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3674b35d-43fc-4528-8e3c-e070698ea31d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27ea2fa8-0b00-44b9-b46b-bcb22c6c3712', '5448263d-c547-4250-b296-8aebc3415239', 8, '100168705', '超ウザイんだけど', '文化祭で焼きそばパン屋を出店するために、滝川ノア率いる1年生の問題児をおとなしくさせることになった山田たち。ノアは魔女で、キスをした相手の過去を見て弱みを握るようなヤツ。しかも、魔女伝説が書かれたノートの下巻まで持ち出したみてぇだ! 山田は、いろいろ一気に片付いて好都合だと、早速ノアをシメにいくが、逆にシメられて帰ってくる。リベンジに燃える山田だが、ノアにウザがられるばかり。そこで山田はノアに「俺を仲間にしてくれ」と頼む奇策に出た! 山田が魔女の話を切り出した途端、目の色を変えたノアは、山田を押し倒して強引にキスを迫ってくる!', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28840499-bd4a-43be-86b3-49429b39c9bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66ec3618-ac68-4a91-9f90-e997be30cb64', '5448263d-c547-4250-b296-8aebc3415239', 9, '100168706', '必ず未来を変えて', '朱雀祭開催! 超研部の焼きそばパン屋は、マリアの未来予知能力をコピーした山田の絶対的中占いで大繁盛。そんな中、マリアは山田に「魔女の能力を消してほしい」と頼んでくる。ワタシはふつうのキスをして恋がしたい。山田は早速、魔女の力を消せるという玉木真一の元を訪れる。コピーの山田に対し、玉木はキャプチャー (吸い取る) の使い手で、いまはとある魔女から奪った透明人間の能力を持っていた! 玉木は、次期生徒会長の座を狙っていると山田に明かし、山崎会長が誰を後継者にするか調べてくれたら、マリアの願いを叶えると、交換条件を出してくる。早速山崎から聞き出してやるぜ!', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e264b8d-6f9c-44a7-aa16-0e8f5ed7d89b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('005d7d4e-8dc5-418e-9994-26b4bd44754c', '5448263d-c547-4250-b296-8aebc3415239', 10, '100168707', '俺と付き合ってください!', '7人目の魔女を探す山田たち超研部は、宮村の姉･レオナに会う。レオナはその魔女の『記憶喪失』の能力から逃れるために登校拒否をしていた。7人目の魔女の名前を知った瞬間、魔女に関するすべての記憶が消されることになるらしい。それってつまり、俺が白石のことを忘れちまうってことか!? それでも山田は、「全っ然たいしたことねーな!」と覚悟を決め、レオナから7人目の魔女の名を聞く。うららのために未来を変えることを選んだ山田は、「俺を引き戻してくれ」と超研部の仲間たちに頼み、山崎に魔女の名を告げる!', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3bbfdb2-3bc5-4b22-be47-04a8f8a26914.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b30bb620-bfbc-4aad-abc8-64588909895a', '5448263d-c547-4250-b296-8aebc3415239', 11, '100168708', '白石をどこにやった!', 'うららの涙を見て、いてもたってもいられなくなった山田は、うららが魔女であることを証明するためにキスを迫るが、うららに拒絶されてしまう。あきらめずに記憶を取り戻す術を探す山田と玉木。そこへ、血相を変えた寧々がやってきた。「よくも私に能力をかけてくれたわね!」。なんと寧々は山田の記憶を取り戻していた! 山田とキスをした魔女は記憶を取り戻せる!? そんな山田の前に再び現れたリカは、7人の魔女全員の名前を知った者が記憶を消される理由を話し始めた。なに!? 魔女が全員揃ったらどんな願い事も叶っちまうだってぇ!!?', '2024/01/11 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb91b796-f473-4149-8624-93726fdfc140.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b77a6a4a-b01d-4e70-aca2-37436c280846', '5448263d-c547-4250-b296-8aebc3415239', 12, '100168709', '俺は白石が好きだ!', '【最終話】魔女の儀式を実行するために7人の魔女全員を揃えなきゃならない山田たち。残すはうらら、美琴、リカの3人。とにかくうららを救いたい山田は、生徒会役員の宮村を連れて美琴の家へ向かおうとするが、姉のレオナにつかまる。事情を話して焦る山田に、うららよりもまずリカを説得すべきだと話すレオナ。リカは、儀式に参加する代わりにレオナを学校へ連れてくるよう交換条件を出してきた。レオナは決心をして、かつて自分が超常現象研究部の部員だったこと、そして、もうひとりの部員･山崎春馬と魔女伝説を探り、山崎は記憶を消され、レオナは学校に行かずリカから逃げ続けていることを明かすのだった。', '2024/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1ed71a9-2b50-4606-a6d1-0b48c886c730.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('78007d03-7c4b-4aee-8f76-8fc2501d1ac4', '山田くんとLv999の恋をする', '', 'hulu', 'my-love-story-with-yamada-kun-at-lv999', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b5e0256-50b5-4dee-b080-6ae5cf6314b4.jpg?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 154965, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a044ba4b-c89a-4814-a602-743395c35500', '78007d03-7c4b-4aee-8f76-8fc2501d1ac4', 'hulu-my-love-story-with-yamada-kun-at-lv999-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e36a530-38a1-496d-9c8a-39942fe2bb70.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9ad41fc-42d0-463c-9dea-68c497c75770', 'a044ba4b-c89a-4814-a602-743395c35500', 1, '100141934', 'これだからっ! ゲームする男なんて!!', '女子大生･木之下茜を襲った突然の悲劇――それは彼氏のたくまから「好きな子ができた」と別れを切り出されたこと。しかもその相手は、茜がたくまと話を合わせるためにプレイしていたネトゲ「Forest of Savior (FOS)」で知り合った女性だという。理不尽な事態にショックを隠し切れない茜は、FOS内で雑魚キャラ相手に憂さ晴らしをする。そこに居合わせたのが、同じギルドに所属する「山田」だった。思わず彼に恋人との別れを話してしまったことが、茜の人生を大きく変える。', '2023/04/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e36a530-38a1-496d-9c8a-39942fe2bb70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfa1d5e8-82c1-4859-b165-32c116cf03e2', 'a044ba4b-c89a-4814-a602-743395c35500', 2, '100142562', 'そろそろボス湧きの時間なんで', 'FOSのオフラインイベントで偶然「山田」を発見した茜だが、元カレ (with新しい彼女) と遭遇した際、衝動的に山田を彼氏だと紹介してしまう。その埋め合わせのために入った居酒屋で茜は泥酔し、山田の自宅で介抱される&思い出のアクセサリーを失くすという大失態……。茜はアクセサリーを探そうと、FOSのギルドルームで出会った山田に接触。だが、山田からは冷たくあしらわれた上、武器庫の使い方についてダメ出しをされてしまう。', '2023/04/11 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1a50e05-492b-4d5f-ae56-df8af460c0ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6b59e29-218e-4cfa-a5e1-328ca02b2fd4', 'a044ba4b-c89a-4814-a602-743395c35500', 3, '100143562', 'オフ会したいなぁ♡', '別れを引きずり、合コンにも身が入らない茜。FOSにログインしてみると、そこにはギルドマスターである瑠璃姫と山田の姿があった。普段は「能面」のアバター通りに無愛想な山田だが、瑠璃姫には以前から親しげに絡んでいる様子が気にかかる茜。もしや、ふたりは恋人同士だったのでは――そんな思いが頭をよぎると同時に、山田への気持ちを茜は自覚しはじめる。その後、瑠璃姫からオフ会の誘いを受け、会う約束をするが……。', '2023/04/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ce6e243-354e-4f32-9b51-dc0f6c445012.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9088af5e-676f-40d2-8ead-c086ddd5d4c8', 'a044ba4b-c89a-4814-a602-743395c35500', 4, '100144187', '山田さんのこと好きなんですか?', 'FOSのコラボカフェで開催された、ギルド「Chocolate Rabbit」のオフ会に参加した茜。だが、山田と瑠璃姫らしき女性は把握するも、その場にいる瑛太と鴨田と呼ばれる男性にはピンと来ていなかった。山田の先導で自己紹介が始まると、鴨田はtakezoの名で参加しているいちご農家のおじさんで、FOSでは対面したことがない人物だった。さらにもうひとりの瑛太は、茜が思いもよらぬアバターの主 (あるじ) で――。', '2023/04/25 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dea6aabc-f022-408c-83dd-a4821a672e28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47a8f371-cfb6-4c79-996f-327f5ff3f5cc', 'a044ba4b-c89a-4814-a602-743395c35500', 5, '100144756', '詳しく聞かせてもらおうか', 'ギルドのメンバーと仲良くしたい茜だが、瑛太の妹である瑠奈から距離を置かれていることは感じ取っていた。そんな瑠奈からカフェに誘われ、テンションが上がる茜。ところが、この誘いは瑠奈のイタズラであり、カフェにいたのは、瑠璃姫の大ファンを名乗る見ず知らずの男性だけ。一旦、状況を整理しようとトイレに行く茜だったが……。一方、家庭教師として佐々木家を訪ねていた山田は、瑠奈の様子がおかしいことに気づき、茜へのイタズラを知る。', '2023/05/02 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/526b177a-0d76-4b6e-a9dc-ef21d0b8038c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df95b890-9b9f-4ca0-8e01-2de86fc7f9e0', 'a044ba4b-c89a-4814-a602-743395c35500', 6, '100145428', '個人的にはラブコメ希望', '瑠奈のイタズラに端を発した騒動は、山田たちギルドの面々が仲介に入ったことで解決。茜も瑠奈の謝罪を受け入れる。その後、瑠奈はすっかり茜に懐き、茜の自宅にも頻繁に遊びに来るまでになる。一方で茜も、瑠奈との関係が改善されたことでよりFOSのプレイに熱中するようになり、ようやく山田ともゲーム上でフレンドとなる。だが、ネトゲによって負荷がかかりすぎたためか、突然、茜のパソコンが爆発し――。', '2023/05/09 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/86ceb03c-e44d-45b3-9f8d-b22737065bd1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f15dd629-ddca-4175-a5d0-c1e600c83ca6', 'a044ba4b-c89a-4814-a602-743395c35500', 7, '100145938', '安心したいですか?', '茜のパソコンを修理するため、彼女のマンションへやってきた山田。ある理由から女性と距離を取り続けてきた山田であったが、不思議と昼寝をしている茜からは目が離せなくなる。思わず茜の髪に触れようとしたそのとき――玄関からチャイムが鳴る。山田が様子を見に行くと、そこに立っていたのは、茜の元彼である「たくま」だった。茜の部屋から山田が現れたことに驚く「たくま」がこの場所に来た理由とは……。', '2023/05/16 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea8ae63c-0d2c-4de3-9258-0abe77a2edea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6768fa60-8ecd-4d35-8547-158d7d156749', 'a044ba4b-c89a-4814-a602-743395c35500', 8, '100146644', 'もしそうならそれはすごく', '茜はギルドのメンバーと一緒に、山田が通う高校の学園祭「東成祭」へとやってきた。瑛太と鴨田は生徒たちが運営するメイドカフェに、一方の瑠奈は、来年この高校を受験するというプレッシャーから腹痛に襲われ、トイレに駆け込む。茜は瑠奈の身を案じてトイレ前で待っていると、そこに山田が現れる。ふたりはその後、買い物がてら一緒に校内を歩くことに。山田が女性と歩く珍しい光景に、周囲の生徒たちだけでなく、教師もざわつきはじめ……。', '2023/05/23 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08a3aba8-ebe8-4648-8836-62cf0f4a2381.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5da963b6-c8c8-4c7a-9864-13fa7d8a2683', 'a044ba4b-c89a-4814-a602-743395c35500', 9, '100147403', 'ギルドの一大事だよっ!!', '学園祭で互いに素直な気持ちを話し合い、これまで以上に打ち解けた茜と山田。茜は山田への想いに自覚がありながらも、年下の高校生である彼に対してどこかブレーキをかけてしまうところがあった。もやもやした気持ちが晴れない中、FOSのギルドに次なる展開が訪れる。ギルドに新たな女性メンバーが加入することになったのだ。だが、その女性は山田と同い年のクラスメイトであり、しかも山田本人の紹介だという――。', '2023/05/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fc3770e-0c28-4854-9871-54743f79c128.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b01df466-f774-4c51-8a7a-03a8c68b252e', 'a044ba4b-c89a-4814-a602-743395c35500', 10, '100148264', 'きっといつか傷つく', '重い風邪で倒れる寸前だった茜の前に現れたのは、山田だった。山田は茜を担ぎ上げ、夜間病院へと連れていく。一方、山田が塾に来ないことを心配していたのは、新たにギルドに参加したクラスメイトの椿だった。椿は、別のネトゲで山田と対戦したことを機に交流を持ち、彼が女性を遠ざける理由も知っていた。「こんな残酷な人に恋をしたら」――そんな気持ちとは裏腹に、椿の中で山田の存在はすでに大きくなっていて……。', '2023/06/06 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/196e2e88-e07c-435a-b6a9-de47ae1e5fa2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c3f23ee-f9f8-4906-a9e8-d96f14fa1d20', 'a044ba4b-c89a-4814-a602-743395c35500', 11, '100148671', '話したいことがあるの', '山田の介抱のおかげで風邪から回復した茜。久々にFOSにログインすると、ギルドの新メンバーで、椿のアバター「TSUBAKI」と初めて接触する。ふたりは早速ボス戦に挑むが、その防御の「かたさ」に苦戦を強いられる。結局時間切れでボスに逃げられるも、共闘したことでTSUBAKIとの関係はすぐに深まっていった。ログアウト後、茜はボス攻略のアドバイスをもらおうと山田に電話するが、つい長電話に。これを機に茜は、ある決心を固める。', '2023/06/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8841ffed-4149-4903-979d-149a06e17654.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a7a9df7-8712-4ae5-9642-f889c8c02fbd', 'a044ba4b-c89a-4814-a602-743395c35500', 12, '100149323', '好きだよ', '山田に対して告白する決意を固めた茜は、失恋時に励ましてくれた親友の桃子と「瑠璃姫」＝瑛太にその意思を告げる。茜はそのまま勢いに任せ、アポなしで山田のマンションを訪ねるが、塾へ急ぐ彼に対してなかなか気持ちを伝えることができない。結局、塾終わりに落ち合うことになったものの、突然の豪雨と、その雨に誘われたような椿の衝動的な行動によって、その日の約束は中止になってしまう――。', '2023/06/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bbc1fa2e-8209-4abd-ad19-c9d337813ccc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbdfd045-a16a-4792-a469-399d826af6c7', 'a044ba4b-c89a-4814-a602-743395c35500', 13, '100150136', '朝 起きたら', '【シーズン1 最終話】衝動的に山田への気持ちを吐露した椿は、改めて彼を呼び出す。山田の気持ちが別の女性に向いていることはわかっていたものの、学生生活の中でどんな想いを抱いてきたか、すべてをぶつけようとする。その気持ちに対し、山田は……。同じ頃、茜はギルドの焼肉オフ会に参加していた。山田も遅れて合流するはずであったが、緊張からかついつい飲みすぎ、泥酔してしまった茜。そんな状況の中で合流した山田は、嫌がらずに茜に付き添う。そして酔いが覚めた茜に対し、山田が取った行動とは――。', '2023/06/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45e7966f-74f2-4e36-a7c0-f72af0f757f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('bea284ff-96c5-432c-a534-7c81a6f3015c', '残響のテロル', '', 'hulu', 'terror-in-resonance', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7d4373e-807a-41eb-a69a-d48f6cfb0abb.jpg?w=331&h=447&p=t', 'hulu', 2014, 2, 1, 'FINISHED', NULL, 20661, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b97ddafd-7051-405d-bf7c-e2a689430107', 'bea284ff-96c5-432c-a534-7c81a6f3015c', 'hulu-terror-in-resonance-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1366892-75e4-41fc-a869-46193e2f946a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed12ba0a-8e6f-4f9b-9703-7b3fdd590cd6', 'b97ddafd-7051-405d-bf7c-e2a689430107', 1, '100152224', 'FALLING', '核燃料再処理施設の壁に描かれた「VON」の文字。それが全ての始まりだった。そして夏、動画投稿サイトに謎めいたメッセージがアップされる。スピンクス1号･2号と名乗る二人は告げる。「新宿方面ではところによりでっかい火花があがるでしょう……」。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1366892-75e4-41fc-a869-46193e2f946a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d62824ae-db53-416e-a308-6970bb4f7535', 'b97ddafd-7051-405d-bf7c-e2a689430107', 2, '100152225', 'CALL & RESPONSE', '都庁を襲った爆弾テロ。その騒動に巻き込まれたリサは、自分が会ったあの二人――ツエルブとナインが犯人と知り狼狽する。混乱する警視庁を尻目にスピンクス1号･2号の新たなメッセージ動画がアップされる。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58a686dc-13a2-4ff8-9c03-129635dd2dfd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1b28cd7-26f6-403d-a013-57f7424ba604', 'b97ddafd-7051-405d-bf7c-e2a689430107', 3, '100152226', 'SEARCH & DESTROY', 'スピンクス1号･2号を追うため、文書課の刑事･柴崎が捜査に加わることになった。2つの事件の周辺を洗う中、スピンクスが第三の標的を発表する。柴崎の推理は爆弾のありかを突き止めることができるか。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c162e2fe-894a-4d75-a7e9-5e7b170e7c31.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('165b2d46-385c-451c-ae05-9f4490ccb055', 'b97ddafd-7051-405d-bf7c-e2a689430107', 4, '100152227', 'BREAK THROUGH', '犯人の手がかりを追って核燃料再処理施設のある青森を訪れた柴崎。東京に戻った柴崎を待っていたかのようにスピンクスから新たな謎が発表された。一方、家出をしたリサの前にツエルブが姿を見せる。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c580c115-097f-475c-a375-d92bfc5d9e76.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8dd97d25-b41b-46b1-bd04-7ea4af6ea080', 'b97ddafd-7051-405d-bf7c-e2a689430107', 5, '100152228', 'HIDE & SEEK', 'ナインとツエルブのアジトにつれてこられたリサ。だが、リサの処遇をめぐってナインとツエルブの意見は合わない。スピンクスのハッキングで捜査情報を流出させられた警視庁のもとにアメリカからある人物がやってくる。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67f3e986-0914-4ac2-86d6-b71148c64761.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfb8e0ce-e128-48e7-b25e-b5630f8f190e', 'b97ddafd-7051-405d-bf7c-e2a689430107', 6, '100152229', 'READY OR NOT', 'アメリカからやってきた少女ハイヴはスピンクスのテロの裏をかいてきた。ナインは、彼女が地下鉄のテロを妨害していたと直感する。ハイヴは自分たちを恨んでいるのか? と気に掛けるツエルブ。そんな中、スピンクスを名乗る何者かから、新たな犯行予告が届く。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81426586-de88-4a29-95a3-4019bf2e21bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60675ef3-1ba9-460d-a609-f02fe28d1b84', 'b97ddafd-7051-405d-bf7c-e2a689430107', 7, '100152230', 'DEUCE', '羽田空港の電光掲示板に映し出されるチェスの問題。それはハイヴからナインにあてた“挑戦状”だ。ツエルブは監視カメラの死角を縫って反撃の準備を進める。さらに空港に駆けつける柴崎。爆弾を巡り、水面下で激しい攻防が行われる。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d69d85b-787d-4ba9-872a-f27893cd5fa1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24d971dd-babc-4c35-953c-487710abb855', 'b97ddafd-7051-405d-bf7c-e2a689430107', 8, '100152231', 'MY FAIR LADY', '無期限の休職を言い渡された柴崎。だが、独自に捜査を続け、テロの標的に共通して関係のある団体「新進平和塾」の関係者を訊ねる。そのころ、ナインとツエルブはアジトを変えようとするが、古いアジトにいるリサに荷物が届き……。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2c5eacf-2adc-4ea2-8744-a3ad5ea9857e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2ca5732-5f84-445a-84fc-4df06ff51731', 'b97ddafd-7051-405d-bf7c-e2a689430107', 9, '100152232', 'HIGHS & LOWS', 'リサをとらえたハイヴは、ナインとツエルブを呼び出す。リサを助けるべきかどうか。二人の時間は限られている。その一方、調査を続けていた柴崎はプロジェクト･アテネの存在を知る。プロジェクト･アテネとは一体何だったのか。ようやく探り当てた関係者の青木は、柴崎に重い口を開く。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9946c445-2428-443b-a780-cb91ee73e5ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c1ad2c1-c019-410b-8f83-61840da6d344', 'b97ddafd-7051-405d-bf7c-e2a689430107', 10, '100152233', 'HELTER SKELTER', '警視庁に出頭したナイン。ナインは原子爆弾をセットしてきたことを伝え、爆発を止めるかわりにある要求をする。一方、柴崎はプロジェクト･アテネの中心人物、間宮俊造の元へと赴く。全ての真実が今、白日の下にさらされようとしている。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3095140-bfef-47a1-9568-3cb90bdb48b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc45d853-e692-42b9-9fae-2d42a6a62c65', 'b97ddafd-7051-405d-bf7c-e2a689430107', 11, '100152234', 'VON', '【最終話】ハイヴの妨害により、記者会見にたどり着くことができなかったナイン。そのため自動で流れる最期の犯行予告とともに、原子爆弾の発射装置が動き始める。混乱し、人のいなくなった東京でナイン、ツエルブ、そしてリサは空を見上げる。', '2023/08/23 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8920225-1bcb-45f0-8782-5f6b33078fcb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7b8f3376-0ead-4be2-8c94-085d96390c27', '史上最強の大魔王、村人Aに転生する', '', 'hulu', 'the-greatest-demon-lord-is-reborn-as-a-typical-nobody', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da37d1f3-ce3e-4dc4-bcca-041d9ea7c7b9.jpg?w=331&h=447&p=t', 'hulu', 2022, 1, 1, 'FINISHED', NULL, 130586, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f1d6cae9-c87b-4df1-9346-cacf00d2dc19', '7b8f3376-0ead-4be2-8c94-085d96390c27', 'hulu-the-greatest-demon-lord-is-reborn-as-a-typical-nobody-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7742d8d-c96a-4ec9-8c80-2e98c434b5ce.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('578f7b5c-19cb-43d8-8ed4-d162258fee34', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 1, '100109480', '村人A', '強さゆえの孤独から平凡な生活に憧れた《魔王》ヴァルヴァトスは、数千年後の村人アード･メテオールに転生する。夢は人間と友情の絆を結ぶこと。しかし、10歳を迎えても友達を作るという目的は達成できずにいた。そんな中、森の中で魔物と戦う少女と運命の出会いを果たす。', '2022/04/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7742d8d-c96a-4ec9-8c80-2e98c434b5ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb283717-b380-48cc-a9ca-2a2f2f119893', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 2, '100109897', '規格外', '魔法学園に入学したものの、平凡とはほど遠い生活が待っていた。アードは知らぬ間に名声を手に入れ、急にもてはやされてしまう。さらに、クラスでも問題が発生。サキュバスの少女ジニーが貴族の息子エラルドに虐げられていた。エラルドは介入したイリーナを侮辱。アードが謝罪を要求すると、決闘を申し込まれてしまう。', '2022/04/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/989f3143-ba46-4881-9115-c68f2c1758a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e9275e4-92c6-4255-aa75-8aafe9b7dd53', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 3, '100110479', '魔王劇場', '学園長からバトルイベントへの参加を懇願されるアード。受けても断ってもリスクが大きく、頭を抱えてしまう。そんな中、アードはジニーからデートに誘われる。イリーナも割り込んでくるが、ジニーはそれをあっさり承諾。かえって気を遣うイリーナに、ジニーはある野望を語る。そして、デート当日。3人は不審な集団に遭遇する。', '2022/04/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c7a8f3e-5138-4f7e-a59c-d7a725267917.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b91023b-f273-46c3-a273-a087a9435df2', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 4, '100110803', '決闘', 'モテまくるアードを前に、イライラが収まらないイリーナ。アードが機嫌を取る方法を考えていると、ジニーがやってきてあられもない姿をさらけ出す。誘惑の魔眼でアプローチを仕掛けるジニー。一方、イリーナもまた大胆な格好で迫ろうとしていた。アードをめぐり、一触即発の2人。決闘にまで発展しようとするが……!?', '2022/05/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63f84510-3b37-4f44-ad7c-9fa9849dbb93.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13005505-23b8-4cbe-980a-a63e64288558', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 5, '100111115', '孤独なりし王の物語', 'エルザードは世界を滅ぼすため、イリーナを生け贄として邪神の一柱を復活させようとしていた。なぜ、イリーナが生け贄に選ばれたのか? アードはイリーナを救出するために、新たな武器を携えてエルザードの元へとやってくる。立ち塞がる魔族たち。そして、イリーナに隠された真実を告げられたとき、アードは……?', '2022/05/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aaa190a3-b4b4-471d-b802-f9dbf73b1623.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3240443-7a18-4d49-a7f7-f31b038a2158', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 6, '100112023', '激動の勇者', '《魔王》の仲間シルフィーが、数千年の時を経て現代に現れた。仮面の男に《魔王》の居場所を聞かされたシルフィーは……? 一方、魔法学園は学園祭を控え、アードは剣王武闘会、演劇、そして“学園祭の中止”を求める脅迫状への対応を迫られていた。アードたちが演劇について話し合いを始めると、学園で大きな騒ぎが起こる。', '2022/05/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88eeef9c-922d-4b7a-ab9e-107041674ac1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('642b20d3-e34c-46d5-a189-ea902383d31d', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 7, '100112389', '白熱の祭典', '学園祭が始まり、アードはイリーナと警邏に励んでいた。だが、オリヴィアには剣王武闘大会に勝手にエントリーされ、ジニーの「お色気メイド喫茶」では無理矢理もてなされ、頭を抱えるばかり。そんな中、イリーナ、ジニー、シルフィーが剣王武闘会の出場を決意する。シルフィーには優勝賞品に強い思い入れがあった。', '2022/05/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ca07dc3-10a0-46c9-af00-8847f45d2b53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47433aa4-54b9-4d69-b23d-ec42c7f60b04', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 8, '100113155', '仮面は嗤う', '学園祭の目玉である演劇が始まった。《魔王》を演じるアードは《邪神》を演じるシルフィーを前にして、ふいに《邪神》との決戦を思い出す。当時のシルフィーは、リディアに必要とされていないと劣等感を抱えていた。ヴァルヴァトスはリディアの真意を伝え、自由に戦うことを許可するが、シルフィーの招いた結末は……?', '2022/06/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbcda747-1a37-4413-9377-f75a1001c4f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af1a39de-d362-4cc6-8da7-28a7c2559dd0', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 9, '100113976', '神曰く', '修学旅行に向かう道中、アード、イリーナ、ジニーの前に神を名乗る謎の幼児が現れる。謎めいた依頼をされた3人は、知らぬ間にヴァルヴァトスが存命の古代世界に飛ばされてしまう。状況を変えようとヴァルヴァトスへの拝謁を決めた矢先、荒野で魔物と戦う女性に遭遇。そこに現れたのは、3人もよく知る人物だった……。', '2022/06/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b149febc-dbb0-49ed-9f5b-01c05654b3d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c80d65df-1938-4836-a098-dfda76845444', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 10, '100114479', '古の戦場へ', '出撃までリディアの別荘に滞在することになったものの、アードはどこか後ろめたさを感じていた。そんな中、ついに魔族との戦争が始まり、アードたちは後方支援を任される。この戦争には大きな波乱はないと記憶していたアードだが、後方にまで魔族の手が伸びる。その先にある《魔王》との対面を果たすため、アードは……。', '2022/06/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63f00fed-4a09-4f01-872c-eb123be14fb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6ea1936-b3eb-4f41-90e1-feef13026c35', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 11, '100115051', '覚悟ある者', '《魔王》からの宣戦布告を受け、ヴァルヴァトスは討伐を決定。アードは歴史の変化を実感するが、その行く末を予測しかねていた。考えを巡らせていると、突如として《魔王》が現れる。ディザスター･ローグを名乗る《魔王》から素性を明かされ、驚愕するアード。そして、ある提案を持ちかけられる。', '2022/06/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c3d1b99-fa1e-4caf-be08-b4f3418419ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f298b31b-0e99-48ce-b18d-fe50ffd8b006', 'f1d6cae9-c87b-4df1-9346-cacf00d2dc19', 12, '100115874', '決意の先に', '【シーズン1 最終話】もう一人の自分である《魔王》ローグと対峙するアード。拮抗する二人の戦いの中、《魔王》はアードにある事実を告げる。《勇者》としての決意を持ち、戦いに身を投じるリディア。リディアの救済に決断を下すアードと《魔王》。それぞれの覚悟が交差する中、己の過去、そして自分自身と向き合ったアードが出した答えとは……。', '2022/06/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba6405d2-5488-4728-9ac2-3b0b32b7c7e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dfe02d76-770b-45b1-844f-6a9b6f520700', '四月は君の嘘', '', 'hulu', 'your-lie-in-april', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89e7f5a8-392b-469a-8dfa-8bbe4ade14d4.jpg?w=331&h=447&p=t', 'hulu', 2014, 3, 1, 'FINISHED', NULL, 20665, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 'dfe02d76-770b-45b1-844f-6a9b6f520700', 'hulu-your-lie-in-april-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13455eff-33e7-4118-bc7b-f01dd447051f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09172113-4186-4b05-bde4-4f1f2b9de62c', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 1, '100154541', 'モノトーン／カラフル', '11歳の秋、天才ピアニストと呼ばれていた有馬公生は、母の死をきっかけに突然ピアノが弾けなくなってしまう。それ以来、彼の時間は止まったままだった。そんな公生を気に掛ける幼なじみの少女･澤部椿は、公生をダブルデートに誘う。同じく公生の幼なじみの渡亮太がとある女の子に会うことになっていた。気が進まないながらも待ち合わせ場所に向かう公生。彼はそこでピアニカを演奏する少女を目にする。渡のことが好きだという少女の名は、宮園かをり。彼女は、ヴァイオリニストだった!', '2023/09/05 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13455eff-33e7-4118-bc7b-f01dd447051f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25b71fd7-56e5-4e07-85c2-fcc15d86f4f2', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 2, '100154542', '友人A', '有馬公生たちを連れて、宮園かをりはコンサートホールへ向かう。そこではヴァイオリン部門のコンクールが行われていた。懐かしい匂いがするホールの空気を味わう公生。天才ピアニストと呼ばれていた公生のことに気づく観客も会場には多くいた。コンクールがはじまり、会場には緊張感が張りつめる。そして4番目にかをりの出番がやってきた。彼女が弾く『クロイツェル』は、ほかの出場者の演奏とは全く違うものだった。楽譜の指示に従わず、曲を自分のものにしてしまう。その彼女の姿は美しかった。演奏を終えたかをりは渡亮太のもとへ駆けていく。その光景はまるで映画のワンシーン。ヒーローとヒロインのラブシーンを横で見つめる、公生はさながら「友人A」の役を務めているような気分を味わうのだった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1124177d-152c-4f41-be9a-1a16c710882b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fac4ebf6-5135-412a-b2f9-cf5d905bd541', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 3, '100154543', '春の中', '学校の帰り道、宮園かをりとばったりと出会った有馬公生は、渡亮太の代役でカフェへ向かう。美味しいワッフルを食べて、大喜びのかをり。そのカフェでは、子どもたちが古びたアップライトピアノで「きらきら星」を弾こうとしていた。かをりは公生に演奏するように命じる。店内に公生が奏でるピアノの音が響き渡る。だが突然、公生は演奏を止めてしまう。公生は集中するとピアノの音が聴こえなくなってしまうのだった。そんな彼を、かをりは自らの伴奏者に任命する。先日のコンクールで聴衆推薦に選ばれたかをりは、二次予選に出場することになっていた。涙をこぼしながら訴える、かをりの姿に、公生は伴奏を引き受ける決意をする。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b433fe18-9bdc-4274-8b8f-92b9880c5a1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ddc8ef7-89b1-41ad-adbd-64ab73a94c71', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 4, '100154544', '旅立ち', 'コンクールの二次予選の日。かをりと公生は会場の廊下で出番を待っていた。緊張する公生を見て、宮園かをりは頭突きを一撃。公生と瞳をあわせると、「君ならできるよ。」と励ますのだった。2人の行先の決まっていない、音楽の旅がはじまる。大人しい演奏からスタートしたものの、曲調が変わると同時にかをりは本性を発揮…全身でヴァイオリンを弾きはじめる。公生はかをりに遅れないよう一音も漏らさず正確についていく。だが、公生が演奏に集中するほど、音符が次々と消え、ピアノの音が聴こえなくなっていく…。やがて伴奏は乱れ、公生は演奏を止めてしまう。すると、かをりも演奏を中断。微笑みながら少女は、「アゲイン。」とつぶやく――。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71035ad7-cbf5-4722-9871-5a3e62f52063.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3fec2504-5e7b-498a-bdff-7cac68cd4bdf', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 5, '100154545', 'どんてんもよう', '病院の病室へ駆け込む、椿と渡、そして公生の幼なじみトリオ。コンクールの演奏後、かをりは入院していた。演奏を途中で止めたため、公生とかをりはコンクールの本選へ進むことはできなかった。だけど、かをりは公生に対して恨み言をひとつも言わない。そのことが公生には辛かった。ピアノは弾いてる? 君は忘れられるの? かをりの問いかけがいつまでも公生の中に残っていた。数日後、公生は退院して学校にいるかをりを見かける。話しかけようと迷うが、かをりのそばには渡がいた。勘違いするな、と自分に言い聞かせる公生。だが、その日の学校の帰り道に…公生はまたかをりとばったり出会ってしまう。かをりは公生にピアノのコンクールに出るように頼み込むのだった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b9482ed-a71b-4c82-8857-c57795d7ecf1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc257b07-6d12-486e-b9ea-236a89580308', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 6, '100154546', '帰り道', '学校の音楽室からピアノの音が流れる。公生の演奏を録音して、みんなで聴きなおしていたのだ。自分の演奏にショックを受ける公生。落ち込んでいる公生を気にもかけず、かをりはすでにコンクールに公生の応募書類を送ってしまったことを報告する。君は何のためにピアノを弾きたいの? そう問いかける、かをり。公生はひとりでピアノに向かう。ピアノと公生、二人ぼっちの練習の日々がはじまった。公生に急接近するかをりの姿を見て、椿はさびしさを感じる。そこには彼女が踏み込めない音楽家の世界があった。中学最後の夏、椿はソフトボールの試合中に足を負傷し、惜しいところで負けてしまう。うつむき落ち込んだときに椿の目の前に現れた人物は……公生だった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08a34fee-b85c-4e74-9d5e-12240ce1b3bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67bdd41f-9b4a-4624-ba07-eb79ed7dfbd1', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 7, '100154547', 'カゲささやく', 'コンクールの日が近づく。課題曲は暗譜で弾けるようになった。だけど、その曲を自分のものにできたかがわからない。苦悩する公生は授業中に倒れ、保健室に運ばれてしまう。君はどうせ君だよ、保健室に来たかをりは、公生に語りかける。悩んで、迷って、苦しんで、たどりついた答えは笑っちゃうくらいシンプル……。とうとうコンクールの日がやってきた。またピアノが弾けなくなるんじゃないかと怯える公生。しかし、心の中のかをりが彼を勇気づける。そのころ会場には公生を待つ、2人の男女がいた。相座武士と井川絵見、2人は数年前に公生がコンクールで賞を獲り続けていたころ、公生に憧れ、嫉妬し、ライバル視していた同年代のピアニストたちだった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e22af03-1277-4f71-b18a-9f77644045ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('645ba349-f698-4af5-8ccd-1a28cdc16bca', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 8, '100154548', '響け', 'コンクールの優勝候補である武士は2年間、公生を待っていた。公生のピアノに憧れ、より高みを目指して強靭な意志で研鑽を積んできたのだ。その想いをピアノにぶつける武士。その演奏は会場から万雷の拍手で称えられる。その演奏を聴き終え、静かにステージへ向かう絵見。彼女は幼い公生に憧れ、ピアニストになることを誓ったという過去があった。公生がいなくなってから目標を失い、ここ数年不安定な成績を上げていた。だが、公生と再会したこのコンクールで彼女は最高潮の演奏を披露する。感情の起伏が音楽のうねりとなって観客に訴えかける。観客席にいたかをりは、絵見の演奏に共感するのだった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e2d9cd3-c42d-4834-a30e-4d9645658fb0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c95238dd-0aed-4885-b947-be3168654605', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 9, '100154549', '共鳴', '絵見は、あこがれのピアニストだった公生に想いを伝えるべく熱演を披露する。ステージを終えたばかりの絵見は、公生のもとに向かうが、かける言葉はなかった。想いは全部、ピアノに込めたのだから。そしていよいよステージに向かう公生。ピアノを前にした公生に、亡き母の幻影が語り掛ける。過去と対峙する公生の音楽の旅がはじまった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/231c5972-0f02-4e1f-aff4-ec6957024cad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('748a3908-0137-44f4-9c1b-c5636d97810f', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 10, '100154550', '君といた景色', '公生の演奏がはじまった。最初は好調だった演奏だがやがて中盤に来て、演奏が乱れはじめる。その荒れた演奏を聴いて、ざわめきはじめる観客。ピアノの音が聴こえなくなったという噂は本当なのか。観客席のかをりや椿、渡は心の中で公生を応援し、演奏を終えたばかり絵見と武士はその演奏を心配そうに見守る。公生はステージでひとり、母のトラウマと対峙していた。', '2023/09/05 00:00:00', 1372, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4239ea52-0ae9-4ad0-8c10-fc00c0a96bc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5b1c88c-7532-4d0c-93e6-70f2dc613c64', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 11, '100154551', '命の灯', '公生の演奏は終わった。コンクール会場の控室に戻った公生の前に、亡き母の友人･瀬戸紘子が現れる。日本屈指のピアニストである紘子は、公生がピアノに込めた想いを読み取っていた。――ピアノは奏者のすべてを引きずりだすわよ。そのことばに戸惑う公生。そしてコンクールの結果が発表されたが、武士と絵見は妙に晴ればれとした公生の表情を見て、彼の変化と成長をたしかに感じ取るのだった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40bca0c5-3c97-4e9d-8ef6-a00c57f82d47.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3aae6d16-195f-4908-bff1-1209c9fecbfe', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 12, '100154552', 'トゥインクル リトルスター', '主催者推薦で藤和音楽コンクールのガラコンサートに選ばれたかをりに誘われて、公生はピアノに向かう。かをりが選んだ曲はクライスラーの『愛の悲しみ』。かをりがかつて公生の家にいったときに、本棚にささっていた楽譜。『愛の悲しみ』は公生の亡き母がよく弾いていた…公生にとっては母の匂いを感じてしまう曲だった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89a26a7f-d67e-4c9d-855e-af5ab55a1739.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc393d4a-4390-4094-856c-2a721f6db612', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 13, '100154553', '愛の悲しみ', 'ガラコンサート本番当日、出番の時間を迎えたが、かをりが会場に現れなかったため、公生はひとりでステージに立った。伴奏者であるはずの公生がひとりで現れるという奇妙な状況に、ざわめき出す会場。そんな中、公生は亡き母が好きだった曲、クライスラー『愛の悲しみ』の演奏を始める。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55eceb1e-1339-404b-92ba-fdf6b9975f16.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('068ba7cb-4405-400e-bc80-45d7171a6100', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 14, '100154554', '足跡', 'ガラコンに姿を見せなかったかをりが自宅で倒れて入院したと聞き、病院にかけつけた公生たち。元気そうに振舞うかをりだったが、その体調は芳しくなかった。その一方、椿は幼いころから続いてきた公生との居心地の良い関係がかをりの出現で変わってしまったことや、公生に対する自分の気持ちの変化から目を逸らしていた。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66eb136c-4004-4b2d-84ef-18435239364a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7151f802-9477-44a7-9398-1e6837afc856', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 15, '100154555', 'うそつき', '音楽科のある高校へ進学するために公生が家を出ることを知り、戸惑いを隠せない椿。弟のような存在だと思っていた公生の存在が、椿のなかで、より大きな存在になっていることに柏木をはじめ、周囲の人も気づいていたが、それは椿と付き合っている斎藤先輩も例外ではなかった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d5e1de7-56e7-4704-9edc-cc6574aebd3d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12f79dc9-1c18-4c75-b718-0202d7020d70', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 16, '100154556', '似たもの同士', '瀬戸先生に弟子入りした凪を指導することになった公生。最初は初めての指導に戸惑うも、先生らしく振舞うようになる。そんな中、入院しているはずのかをりが公生の目の前にふいに現れる。かをりは渡の代役として公生を指名し、いっしょにショッピングや学校に向かう。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9bbbccd-7c47-4152-9211-dd862115b2b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd8d4803-b3fd-4a99-88be-1586d79ec84b', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 17, '100154557', 'トワイライト', '椿からかをりの見舞いに誘われるが、気が乗らない公生。かをりにどんな言葉をかければいいのか、どんな顔で会えばいいのか分からずに、一歩を踏み出せずにいた。練習にも身が入らない公生を気にかけた凪は、自分の学校の話をしたりと、彼女なりに公生を励ます。すると公生は、誰かのために演奏するのは大切だと言うのだった。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc869836-87a8-4a2f-a6b4-b51b86da6900.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9dad604-8dae-4867-bcdd-b3bd6b5d9ae3', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 18, '100154558', '心重ねる', '胡桃ヶ丘中学の学園祭に出してほしいと凪に頼んだ公生。自分の演奏をかをりに届けたい。その想いを胸に、ふたりはステージに上がる。ついに始まった演奏。だが、サポートであるはずの公生は練習時とはうって変わり、異常に早いテンポとひりつくような雰囲気の演奏で、凪にプレッシャーをかけてくる。凪も、公生に負けじと喰らいつく…。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e8c4453-8603-4dd8-a88f-620be6f8b017.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7357e70-bd42-4b2a-ad0a-ff584cdb0e0e', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 19, '100154559', 'さよならヒーロー', '公生と凪の連弾を聴き、もう1度公生と演奏するために手術を受けることを決意したかをり。次のコンクールに向けて練習を開始した公生を叱咤激励しつつ、再び舞台を目指し自らもリハビリに挑む。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9110b11-2622-498f-8194-c0f62b410303.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ba41b31-88f5-4add-9e78-7cce4bee6a9e', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 20, '100154560', '手と手', 'いつも通りかをりの見舞いに行こうとする公生だったが、渡が先に訪ねていることに気づき、見舞いを遠慮する。そんな公生を見た椿は、自分の気持ちに素直になれない公生にもどかしさを感じていた…。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a07c9159-8e40-4839-86f2-51dc829684bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffa7cb84-edd8-4fd7-8158-0d1c23951d0e', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 21, '100154561', '雪', 'かをりの容体が急変する場に居合わせていた公生は、そのショックからまたピアノに向き合うのをやめてしまう。音楽が大切な人を連れ去っていく…。過去のトラウマが頭をよぎり、公生は再びひとりぼっちになっていた。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c807ecb0-c7f7-4377-8991-4b3a538421fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9141c3b1-17e9-4b46-b598-b1ee386071e1', 'dfb0eee1-9d8d-428d-a03a-8fb545f659c6', 22, '100154562', '春風', '【最終話】自分が舞台に立っているのは、周りの人がいたから、支えてくれたからだと気付いた公生。公生はみんながくれた音を奏で始め、かをりに届けるべく、すべての思いを演奏に乗せる。', '2023/09/05 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/926c7a5d-b3b3-4d31-8f5a-f8b5f875aa19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('60192e6d-4482-4365-aa9d-2a14b35562ff', '四畳半神話大系', '', 'hulu', 'yojouhan-shinwa-taikei', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/596f5cd8-c474-4187-990d-abfc3fca84b6.jpg?w=331&h=447&p=t', 'hulu', 2010, 1, 1, 'FINISHED', NULL, 7785, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b165a103-d023-444f-bc97-b19e22ad2a8e', '60192e6d-4482-4365-aa9d-2a14b35562ff', 'hulu-yojouhan-shinwa-taikei-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf35f241-3ec1-4780-87f0-afe3b521f7de.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20474753-720f-48b1-bd79-ab2872ed32b3', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 1, '100141560', 'テニスサークル「キューピット」', '薔薇色のキャンパスライフを夢見ながらも無意義な2年間を過ごしていた大学三回生の「私」。入学した時に数ある中から選んだテニスサークルで出会った小津と共に、人の恋路を邪魔する「黒いキューピット」を演じていた……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf35f241-3ec1-4780-87f0-afe3b521f7de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('049f8fd1-20e9-4a7a-b3c8-9eea36f0d72c', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 2, '100141561', '映画サークル「みそぎ」', '入学した時に数ある中から映画サークルを選んだ「私」。ちっちゃなカリスマぶりを発揮してサークルを支配する城ヶ崎先輩に抗い、そこで出会った小津と共に盗み撮りなどなんでもありの告発映画を作ることになるが……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6cb47af9-e1ca-416a-879a-c96bcc2f09b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f4019fd3-9c7e-4d19-9058-d30e29b85f88', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 3, '100141562', 'サイクリング同好会「ソレイユ」', '入学した時に数ある中からサイクリング同好会を選んだ「私」。その体育会系ぶりにすぐについていけなくなり、高性能マシンを購入してレース優勝を目指すが、レース直前に宿敵･自転車整理軍に撤去されてしまうことに……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5dcd7291-772f-4fec-8003-03eb98e879f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc868363-6893-435f-966c-f35d0a500b27', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 4, '100141563', '弟子求ム', '入学した時にいつの間にやら樋口師匠の弟子となっていた「私」。大学八回生であり、仙人の様な言動をする樋口師匠。ある日、伝説の束子を探すよう命じられ、妹弟子の明石さんと共に探すことになるが……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48c39cc4-ccc0-4024-b953-55288e4f7be5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2576676-c6a2-4a07-87b9-3b262b58161c', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 5, '100141564', 'ソフトボールサークル「ほんわか」', '入学した時に数ある中からソフトボールサークルを選んだ「私」。そこは女子率の高いほんわかとしたサークル。しかし、ほんわかし過ぎて馴染めない。唯一親近感を持てた小津も、とんでもない事を考えていて……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/815652f0-7559-4274-9bef-217b8673845a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ee52cb2-5a00-45db-884e-d2d9426b616d', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 6, '100141565', '英会話サークル「ジョイングリッシュ」', '入学した時に数ある中から3つのサークルを選んだ「私」。3回生になった今、3人の女性から同時に誘われるという、かつてない華やかな事態が発生。羽貫さん、香織さん、景子さんの3人から、羽貫さんを選ぶが……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0b5d814-ec00-4a77-8694-9819cb691954.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf5a7283-f16c-47d1-bdf4-816d8b4a9625', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 7, '100141566', 'サークル「ヒーローショー同好会」', '入学した時に数ある中から3つのサークルを選んだ「私」。3回生になった今、3人の女性から同時に誘われるという、かつてない華やかな事態が発生。羽貫さん、香織さん、景子さんの3人から、香織さんを選ぶが……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f21dcb48-20a4-4fdf-a7a6-1d1a1c21f14e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2823a58e-15db-497a-90a8-16ae582184f3', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 8, '100141567', '読書サークル「SEA」', '入学した時に数ある中から3つのサークルを選んだ「私」。3回生になった今、3人の女性から同時に誘われるという、かつてない華やかな事態が発生。羽貫さん、香織さん、景子さんの3人から、景子さんを選ぶが……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80231d3b-1724-4f6b-8837-17776b944223.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7185fd41-d22f-4b16-8d12-89ee4bd68afd', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 9, '100141568', '秘密機関「福猫飯店」', '入学した時に数ある中から避け続けていたサークルを選んだ「私」。そこは、様々な組織を配下に持ち、あらゆる情報を網羅する、秘密機関であった。色々な組織へと配属されるがどこでも失敗ばかりを重ねて……。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fb73add-7870-4521-8908-367abb1ed38d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e953498-a77c-442a-9b2d-775cb20cc360', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 10, '100141569', '四畳半主義者', '入学した時に数あるサークルから何も選ばなかった「私」。四畳半の中に全てがあると信じ、「四畳半主義者」として大学生活を過ごしていくことに。ある日、ドアを開けると同じ部屋が。窓を開けても同じ部屋。いったい何が…。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f37df30e-0153-47a4-8422-67116e5b378c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0877691-aaf5-4445-aac1-61bb9b7245dc', 'b165a103-d023-444f-bc97-b19e22ad2a8e', 11, '100141570', '四畳半紀の終わり', '【最終話】四畳半に囲まれた世界にいる「私」。幾つもの部屋を進んだあげく、最初の部屋へと戻ってくる。ここから出ることは出来ないのか? そんな時、部屋にいた一匹の蛾が、幾つもの部屋から集まり大群となって襲いかかってくる…。', '2025/06/16 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e50b4ef-7a87-4c44-811f-e74b57b16a85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('867c2486-1037-46df-9fa4-aacd8ed9deac', '屍鬼', '', 'hulu', 'shiki', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d35bef70-9286-40f0-a437-23a6197e71ce.jpg?w=331&h=447&p=t', 'hulu', 2010, 2, 1, 'FINISHED', NULL, 7724, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('567dc487-f74d-44cf-8518-4609b4aa0c80', '867c2486-1037-46df-9fa4-aacd8ed9deac', 'hulu-shiki-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f54848b6-88bc-4e9c-b98b-c94597b530d1.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f0510bf-8655-4b62-a189-f18620d5dfc5', '567dc487-f74d-44cf-8518-4609b4aa0c80', 1, '100147027', '第遺血話', '人口1300人の小さな村、外場村。何もかもが田舎くさい、清水恵はこの村が大嫌いだ。恵の関心事は、都会から引っ越してきた少年･夏野の存在と、坂の上に完成した兼正の洋館だ。その洋館から視線を感じた恵は、その姿を求め坂を上っていく。そして恵は姿を消した。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f54848b6-88bc-4e9c-b98b-c94597b530d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ac7814e-6fef-4b8b-bfca-5ac91b8412b6', '567dc487-f74d-44cf-8518-4609b4aa0c80', 2, '100147028', '第腐堕話', '恵の死。通夜に姿を現す夏野。かおりは恵が出しそびれていた暑中見舞いを夏野に渡すが、拒否される。山入地区の連続死から続けざまに起こる数人の死。医者である敏夫は疫病の発生を予感する。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1030adc6-f851-435e-a4eb-2ba1ecf63178.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5136f147-514b-4bf9-9bab-e94463b74f38', '567dc487-f74d-44cf-8518-4609b4aa0c80', 3, '100147029', '第惨話', '首をひねる敏夫。体調を崩した安森奈緒の血液検査の結果がおかしい。静信は夜、沙子という少女と出会う。そして、奈緒が死んだ。夏野は何かの気配に眠ることができない。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55c83cab-e28d-48b7-98ce-c389a0893ea4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ddf793e-5ede-4880-84e7-96da53dff975', '567dc487-f74d-44cf-8518-4609b4aa0c80', 4, '100147030', '第死話', '繰り返される死、夜中の引越し、うつろな視線の村人たち。不安な兆候があっても、そこから何も掴むことができず浮かんだ疑問は闇の中に消えていく。恵の気配に密かに怯える夏野。再び徹の部屋で眠る。夜がやってくる。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4fadf7c-c0ce-405f-b95f-e6d5f6038c74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48a2459e-d469-4a2d-844b-2adca85b0660', '567dc487-f74d-44cf-8518-4609b4aa0c80', 5, '100147031', '第偽話', '静信は、死者が出た家を周って不審点を洗い出す。そこで浮かんだ共通点は、かなりの人が死ぬ数日前に辞職をしていることだった。夏野は恵の暑中見舞いはがきを受け取る。一層濃くなる恵の気配。徹が死ぬ。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4dd39d2-1c16-4ef5-a932-576e9f51c9bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6a0ebc4-ad7c-4ea2-afd8-e94bf64213bd', '567dc487-f74d-44cf-8518-4609b4aa0c80', 6, '100147032', '第髏苦話', '増え続ける死。手詰まりの敏夫は怒りをあらわにする。静信の持って来た情報にも、礼を言うどころか暴言を投げつける有様だ。夏野はある仮説を胸に秘め、ビデオや書物を調べはじめる。そして何げなくした保との会話から、あるキーワードに辿り着く。「起き上がり」だ。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4f2e604-e28b-4582-b0e7-45123376f16d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2808be8-7585-46f5-8a27-44177aec9ae6', '567dc487-f74d-44cf-8518-4609b4aa0c80', 7, '100147033', '第弑魑話', '兼正を怪しんでいるかおりと昭に出会った夏野は事件の真相をはっきりさせるため墓を暴くという作戦を二人に持ちだした。尾崎医院に運ばれた安森節子。家族は立て続けに死んでいる。真相を知るために入院をさせる敏夫。彼もまた、一つの結論に達しようとしている。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3aceb3e9-eba0-4b33-b72b-07121373570b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3fc141a0-ab9c-49bd-b610-20c4a6412cb9', '567dc487-f74d-44cf-8518-4609b4aa0c80', 8, '100147034', '第夜話', '墓にシャベルを突き刺す夏野、昭、そしてかおり。シャベルの切っ先が棺桶に到達した時、彼らは思いがけない事態に遭遇する。静信は沙子が何者なのかを感じ取る。夏野を訪ねる見知らぬ子供。夜は、殺意の重みで撓んでいく。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13d8b409-0e9d-4210-a3c7-48ceaa66af4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a72f2e23-b274-4fd7-bdb4-91e4a050a1b8', '567dc487-f74d-44cf-8518-4609b4aa0c80', 9, '100147035', '第柩話', '安森節子を守るため、敏夫は彼らの襲撃を待ちうける。静信は戸惑いながらも敏夫と共に夜を過ごす。律子が夜に見たもの。外からの声に起き上がる節子。いまやはっきりと、彼らは月光にその姿を晒している。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fe32c6c-c3df-40c8-b05e-48dffbac5d85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05a4151e-3dc4-4b6d-82e6-56924a75686d', '567dc487-f74d-44cf-8518-4609b4aa0c80', 10, '100147036', '第悼話', '彼らの脅威となってしまった夏野は存在を許されない。粛清の気配を感じる夏野。部屋で彼らの訪れを、息をひそめて待つ夜、静かに窓を叩く者が現れる。その声は親しげで、どこか懐かしい…。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/631e2a84-b6d5-43c6-90c3-4244730f06ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea6243b8-e5b1-434b-9e70-af415c4faa87', '567dc487-f74d-44cf-8518-4609b4aa0c80', 11, '100147037', '第悼と悲屠話', '敏夫は逃げることのできない問いを、静信に投げかける。一方、起き上がりの存在を確信した祈祷師･郁美は村に広がる危機を人々に声高に訴えるが誰もが本気で取り合おうとはしない。いきり立った郁美は、桐敷の屋敷へと乗り込んでいく。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f485e10b-eecf-4bf0-ada3-2e17d67728ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('810ef5e7-588a-41b4-b320-181b6783b0d9', '567dc487-f74d-44cf-8518-4609b4aa0c80', 12, '100147038', '第悼と腐汰話', '時が迫る。夏野は部屋で友の襲撃を静かに待ち続ける。見なれた影がやがて現れる。友はあの日と変わらないままだ。絶望の夜闇に切なる希望は瞬き、そして消えていく…。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a77d73e1-08f9-4eaf-bb28-654bc3739ded.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4359ec24-9f68-48af-aa03-192208f7069a', '567dc487-f74d-44cf-8518-4609b4aa0c80', 13, '100147039', '第悼と惨話', 'かおり、昭の必死の抵抗も空しく夏野は最後の夜を迎えようとしている。敏夫は一人で戦う方法を見つけ出そうとするが結局無力な自分を痛感するだけだ。全てが綻んでいくのを、彼らは黙って見ていることしかできないのか。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/212088b5-abd7-4919-9cec-5c4f4aa621c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44dac4ee-4f90-434b-932c-80a9cf06b609', '567dc487-f74d-44cf-8518-4609b4aa0c80', 14, '100147040', '第悼と死話', '妻･恭子が死んで5日。諦めかけた敏夫の傍らで、屍が目を覚ます。それは長く彼に連れ添った者、そして敵に対抗するための唯一の手掛かり。彼はメスを取る。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa37707d-bdf3-4017-96ce-dbb6d51daed8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('891e65c5-8a81-45f5-afa5-369cae254487', '567dc487-f74d-44cf-8518-4609b4aa0c80', 15, '100147041', '第悼と偽話', '杭を心臓に打つこと―。恭子への残酷な実験によって、対抗策を突き止めた敏夫。静信は彼の覚悟とその手段に背を向ける。孤独な戦いを強いられる敏夫の前に現れた女。自分もまた、獲物として狩られようとしている。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/896a6bad-032c-48b8-82d6-093fc1ca82c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f5e25c2-cc48-4d3e-bc86-a8b20c7d9462', '567dc487-f74d-44cf-8518-4609b4aa0c80', 16, '100147042', '第悼と髏苦話', '罪を重ねていく徹。夏野をその牙にかけてから幾つもの夜が過ぎた。届けられた伝令。桐敷の屋敷に呼び出された徹に沙子はある一人の少女の物語を語りだす。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a77cc04-8db5-4412-9d6a-84d7e739669d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('83ca62da-b1a8-44aa-8347-2c2c89116d5b', '567dc487-f74d-44cf-8518-4609b4aa0c80', 17, '100147043', '第悼と弑魑話', '律子は看護婦として、多くの謎の死とそれに格闘する敏夫を見つめてきた。敏夫は何かを知っている…という予感の中電話が鳴る。彼女に、そして敏夫にも夜が襲いかかる。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1e6ef19-a77a-4c1f-8550-941014b3e07c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('275d6739-a12b-4686-ac4e-0f67840bc303', '567dc487-f74d-44cf-8518-4609b4aa0c80', 18, '100147044', '第悼と夜話', '千鶴にカルテの改ざんを報告する敏夫。彼はついに屍鬼の支配に下ったのだ。今宵は霜月神楽、祭囃子が鳴り響く。心浮き立たせる彼女に敏夫がひとつの提案をした時、その音は惨劇の前奏曲となる。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6042716-a6f3-4580-8d9a-b2a4cb99ae78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88c5f130-1c2e-4768-ae28-48b58d07057c', '567dc487-f74d-44cf-8518-4609b4aa0c80', 19, '100147045', '第悼と柩話', '千鶴の正体が衆目のもとに曝されついに村人たちが屍鬼狩りに立ち上がる。狩りの陣頭指揮をとる敏夫、対して一気に作戦を完遂させようとする沙子。そのとき静信は何を思うのか?', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d854617-b0d4-4f27-a96e-954c7c2a430a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ed8d015-af40-4d2c-971c-cd4536a59fa7', '567dc487-f74d-44cf-8518-4609b4aa0c80', 20, '100147046', '第腐汰悼話', '尾崎医院、亡骸の傍らに残された意味深なメッセージ。それを記したものは、まだ建物の中にいる。敏夫と大川は階段を上がっていく。山入では空腹と、抗いがたい欲望に震える律子、徹は自分自身の葛藤に苦しくなり、声を荒げる。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd726a5f-3799-42cc-9bb3-a435d010e5c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e43c1fa-d6db-4684-be35-24300ab6582b', '567dc487-f74d-44cf-8518-4609b4aa0c80', 21, '100147047', '第腐汰悼と悲屠話', '地下に隠された小部屋で、沙子は眠りに堕ちていく。静信の言葉に耳を傾けながら。それは、罪と罰、区切るものと区切られるものの物語。人は確実に屍鬼を追いつめている。終焉の時が近づく。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bde6edc5-5578-4b18-b875-6e8b12de6707.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('acc82cde-3c62-4b4d-8dd9-f31ffb3d62f7', '567dc487-f74d-44cf-8518-4609b4aa0c80', 22, '100147048', '蔡蒐話', '【最終話】修羅と化した「人」は、屍鬼を狩りつくす。静信は瀕死の傷を負い、沙子も捕まってしまう。姿を現した夏野、その前に立つ辰巳の姿。敏夫は村を守るため、力を尽くすが…。全てが終わる。', '2023/06/30 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d727e78a-34ec-4896-8797-3c8bed180314.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a53f9dec-be33-43c2-bee4-be619346b1de', '死亡遊戯で飯を食う。', '', 'hulu', 'shiboyugi-playing-death-games-to-put-food-on-the-table', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/050f923d-92d1-4a85-80b1-d6720ef486ed.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'FINISHED', NULL, 180746, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6213abf1-b8bb-4b10-ac41-2188b3099350', 'a53f9dec-be33-43c2-bee4-be619346b1de', 'hulu-shiboyugi-playing-death-games-to-put-food-on-the-table-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e86a8e3f-bf18-41dd-ab69-0558fcd465b2.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2fdf5d9-0a43-49b2-95ad-c73babd5e94b', '6213abf1-b8bb-4b10-ac41-2188b3099350', 1, '100249763', 'All You Need Is ----', '窓の無い洋館、クラシカルなメイド服。知らないベッドの上で幽鬼は目を覚ます。先に集っていたのは五人の少女たち。まだ自らが置かれた状況を飲み込めない彼女たちに、幽鬼は口を開く。「みんなは、初めてなのかな?」命を賭けた、殺人ゲームの舞台の幕が上がる―― (28：GHOST HOUSE)', '2026/01/07 23:00:00', 2860, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e86a8e3f-bf18-41dd-ab69-0558fcd465b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecc3a394-ce83-44ea-be68-9e57076197de', '6213abf1-b8bb-4b10-ac41-2188b3099350', 2, '100250570', 'Chains of ----', '月影の差し込む廃ビル、真っ白なワンピース。冷たいコンクリートの上で幽鬼は目を覚ます。参加者である四人の少女たちは、八回目だというプレイヤー･御城を中心にまとまろうとしていた。「もしかして、みなさん知り合い?」どこか居心地の悪い幽鬼をよそに、廃ビル探索が始まる――(10：SCRAP BUILDING)', '2026/01/14 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6220c71-e801-4fc8-96a8-e89540a5a78e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfe76f43-99f9-48f3-a63f-347d4dff02ef', '6213abf1-b8bb-4b10-ac41-2188b3099350', 3, '100251150', 'In the Name of ----', '負傷した言葉を切り捨てた御城に対し、幽鬼は独り危険を顧みず彼女の救出へと向かう。生存だけを考えれば理解しがたい行動に疑問を抱く言葉。幽鬼は彼女へ一言で理由を告げる。「点数稼ぎかな」一方、別行動となった御城たちは、廃ビルに潜む新たな脅威に直面する―― (10：SCRAP BUILDING)', '2026/01/21 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/682f8414-2198-4073-9e45-b4b5713d70ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d28acc40-bcb1-4006-8f63-c27aad3ef001', '6213abf1-b8bb-4b10-ac41-2188b3099350', 4, '100251945', 'Bad ----', '獣に右腕を食われた御城の前に現れた幽鬼は、自らの非を認めて謝罪をすれば助けてやると彼女に告げる。だが、葛藤する御城からは、意外な言葉が口を衝いて出る。「ふざけないでくださいまし!」迫り来る獣を前に、彼女たちは生存できるのか。そして生存者たちを待ち受ける〈最後の試練〉とは―― (10：SCRAP BUILDING)', '2026/01/28 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a06b135-c3c5-4472-a7ab-a01b9fc028cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8ff5103-98e8-4adc-ba46-c9cbeb8ea3ba', '6213abf1-b8bb-4b10-ac41-2188b3099350', 5, '100252511', '---- Is All You Need', '“三十回目近くのゲームで、生還率は急激に低下する”。いよいよ次回〈三十の壁〉へ挑む幽鬼だが、直近のゲームではどうにも精彩を欠き、思い悩んでいた。そんな折、彼女に一本の電話が入る。「金子と申します」 節目を目前に、幽鬼は命懸けのゲームに参加し続ける自らを今一度見つめる――', '2026/02/04 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b424a33-84f3-41a4-b102-70f97e0178a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8204e5f2-5e19-46bf-b5c0-92948298d19a', '6213abf1-b8bb-4b10-ac41-2188b3099350', 6, '100253235', 'Who''s ----ing You', '湯気の立ち込める巨大浴場、身を包むのは一枚のタオル。他プレイヤーから随分と遅れて幽鬼は目を覚ます。脱出の鍵を巡るゲームは既に白熱し、盤面は膠着し始めていた。「ここに残ってるのは、〈出遅れ組〉なんだね」この窮地を打開し、幽鬼は〈三十の壁〉を超え、生還できるのか── (30：GOLDEN BATH)', '2026/02/11 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afb3c2ef-7bbc-4a14-ae0d-1cbdf797840f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('235e02b4-e1ef-4946-ac28-91d63c5145bd', '6213abf1-b8bb-4b10-ac41-2188b3099350', 7, '100253610', 'Good ----', '御城が仕掛けた作戦が、弛緩していた幽鬼たちを強襲する。自戒する幽鬼だが、仲間たちは壊滅する。捕らえられた幽鬼は、遂に御城の面前へと引き据えられる。「……決着は、もっと劇的なものでなければならないはずだ」“四十回目”の御城と“三十回目”の幽鬼。彼女と彼女は再会する―― (30：GOLDEN BATH)', '2026/02/18 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1b1f234-42df-4d06-adf8-1171060a3d22.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aada6dba-6f85-4727-a076-550dbfa4b42a', '6213abf1-b8bb-4b10-ac41-2188b3099350', 8, '100254505', '---- It All', '森を想起させる箱庭、うさぎ耳が特徴的なバニースーツ。人工的な音声で幽鬼は目を覚ます。幽鬼が属する〈うさぎ〉チームは、師匠と仰ぐ白士を筆頭に常連たちがゲーム開始を待つ。「うさぎはな、切り株に殺されるんだ」一方、対峙する〈切り株〉チームではプレイヤー･萌黄が目を覚ますが―― (9：CANDLE WOODS)', '2026/02/25 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1719a3b3-ac83-4118-bde7-74ac61e0bb00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7fcd2fb6-6ad7-43e2-857a-ac4f23af4a00', '6213abf1-b8bb-4b10-ac41-2188b3099350', 9, '100255150', 'Can''t Help Falling In ----', '初心者だらけの〈切り株〉チームを率いようとする萌黄。しかし常連の多い〈うさぎ〉たちを前に、仲間は次々と倒れていく。「チュートリアルは終わりだ。あとは自分たちで考えなさい」己の未熟さにもがく萌黄。そんな彼女にも幽鬼のように、師匠と仰ぐ人物がいた―― (9：CANDLE WOODS)', '2026/03/04 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e8be3fc-1bf7-4183-be86-8bab1d90fe81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('037bca1b-ab2f-4003-8357-7bdad4cc757f', '6213abf1-b8bb-4b10-ac41-2188b3099350', 10, '100256090', 'Goin'' ----', '“〈うさぎ〉チームに殺人鬼が紛れ込んでいる。”白士の言葉とともに拠点は煙幕に包まれ、迫る殺人鬼を前に〈うさぎ〉たちは離散する。「一番に考えるべきこと、それは……私の生存だ」拠点を脱出した幽鬼は、庭園で〈切り株〉チームの萌黄と鉢合わせる。共に師匠を持つ、弟子同士の戦いが幕を開ける――(9：CANDLE WOODS)', '2026/03/11 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6199791-2822-4b3e-8d83-5547f14d49bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9861e1e-8fc1-4989-afaf-35daa6f1b917', '6213abf1-b8bb-4b10-ac41-2188b3099350', 11, '100256669', '-- v -', '本気で挑んできた萌黄を、本気になれぬままセンスに任せて打倒してしまった幽鬼。その事実に彼女の心は曇る。「お前はなぜ〈ゲーム〉をするんだ」かつてその問いを投げかけてきた白士は、伽羅の手で無残な姿となっていた。白士の言葉を脳裏で反芻しながら、幽鬼は殺人鬼と対峙する―― (9：CANDLE WOODS)', '2026/03/18 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d35ce40-0060-4478-b5a0-d47af84c2f80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3d1e3583-573f-4616-a0c2-da8be0df1212', '私を喰べたい、ひとでなし', '', 'hulu', 'this-monster-wants-to-eat-me', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0b54980-abb0-453e-9856-68c95bbfb4a2.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 183385, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', '3d1e3583-573f-4616-a0c2-da8be0df1212', 'hulu-this-monster-wants-to-eat-me-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3e1f60a-66d7-4c2b-8eb0-1649b9ad1481.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cae3afed-158d-4c6a-9810-d019c5c89389', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 1, '100240374', '死にたがりの彼女は海を待つ', '空虚な日々を過ごしていた八百歳比名子は、早く夏が終わることを望んでいた。ある日、深い海のように透き通った瞳をした少女と出会う。比名子はその少女に対して海に似た印象を覚え、授業の最中も彼女のことを思い浮かべるのだった。その日の下校時、比名子は不意に海の匂いと少女の気配を感じ、上履きのまま海へと向かう。すると海の中から人ならざる者が姿を表し……。', '2025/10/07 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3e1f60a-66d7-4c2b-8eb0-1649b9ad1481.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a280e3f-92d5-46d0-af4c-a19338469701', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 2, '100240860', '斜陽の獣と祭囃子', '「私は君を喰べに来ました」――そう告げた汐莉が、比名子の通う高校へ転入してきた。彼女なら自分を死なせてくれるかもしれない。そんな期待を胸に抱きつつ、一向に自分を喰べようとしない汐莉に、比名子は戸惑いを覚える。何故自分のことを今すぐ喰べないのか? その問いに汐莉は、「人間にだって喰べ頃があると思いませんか?」と口にして……。', '2025/10/14 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/763e30f5-f8aa-4e85-80b1-fdf2aedc443f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56fd2ee6-11bb-40b7-9f37-0900d0612156', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 3, '100241348', '希望の海', '比名子は汐莉に連れられて、夏祭りへ向かう。しかし、身勝手で優しい汐莉の行動によって「あの頃」の記憶をフラッシュバックさせてしまい、彼女の手を振り解いて人混みの中に逃げてしまうのだった。追いかけた先で、比名子が汐莉へ口にしたのは「あの頃」の思い出と、本当に自分を喰べるつもりがあるのかという疑問。それに対して、汐莉は――。', '2025/10/21 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1b451cd-052c-451d-acd0-d0488f026278.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb410e56-a7d7-4646-992f-d743902aa90d', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 4, '100241973', '泡沫の結び目', '普通の人間には見えないはずの妖怪の血。しかし、美胡の目にはその血が見えてしまっていた。また、美胡は以前より汐莉から妖怪の匂いがしていたと明かし……。放課後、比名子は美胡と一緒に遊んでいたが、そこへ汐莉が姿を現す。そして比名子へ強いトーンで、「早く……ソレから離れて」と美胡から離れるように忠告し――。', '2025/10/28 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b9513c0-553c-4d48-8bed-f5d1d18053f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8cd33c8-3686-42fd-b083-bf04a7c6d1a7', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 5, '100242816', '親愛の獣', '妖狐の姿を現した美胡と汐莉の戦いが始まった。その中で、これまで美胡が体調を崩しがちだったのは、近くに自分という存在がいながらも喰べずにいたからだと比名子は知り……。決着間際、美胡は比名子の家族の名前と、比名子への想いを口にする。その言葉に比名子は、美胡の正体がかつて約束をしたある存在だと気付いて――。', '2025/11/04 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a07122b3-8528-489b-a736-bc31a96db595.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69e84210-d4c3-4337-8bb4-be9130d9409b', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 6, '100243906', '親愛の形', '美胡は尻尾二本分の妖力を捨て、比名子のそばにいることを決めた。比名子もまた、彼女が妖怪であることを知った上で、友人でいることに変わりはないと言う。その夜、汐莉は美胡から、比名子が妖怪から襲われるようになったのは、家族を失い自らも生死を彷徨った「あの事故」以降だと知らされる。', '2025/11/11 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e42444c0-46af-41d1-a0f4-970eecc8eacd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ff3e9a2-631d-4d8b-bbf0-47b7ae7080c3', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 7, '100245024', '優しいひと', '雨が降る海水浴場で、比名子は非業の死を遂げた人間の嘆きが形となった存在を目の当たりにしてしまう。そしてその直後、事故による傷跡を汐莉に見られてしまうのだった。しかし汐莉は、見た目よりも、比名子が比名子であることが大事と口にして――。数日後、美胡は比名子にバスケ部合宿でのマネージャー役を依頼する。', '2025/11/18 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70487f70-d81a-4c00-be44-16dd0c452880.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e10f557f-6e1c-41ae-b32b-cef8a2f855eb', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 8, '100245899', 'ひび割れの起点', '汐莉は美胡から、比名子の身体にある傷跡について話を聞く。その話は、生き延びただけでも奇跡なほどの事故であったこと、独り苦しみながら生きているのはどれだけ辛いことなのかまで辿り着き……。一方その頃、比名子はあやめと会話中、彼女へ亡き母親のイメージを重ねてしまっていた。その話を聞いたあやめも、自らが過去に「母親」であったことを明かす。', '2025/11/25 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc7237a3-9e24-44fc-8048-2eeac5fc1a6c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff88bef4-cc2f-4d0f-89dd-7569bcfb4f28', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 9, '100246227', '焼け付いた祈り', '自分の血が混ざっている人間は、不味くて喰べられたものではない。あやめの言葉が頭に残ってしまった比名子は、汐莉へ直接その真偽を確かめる。自分の身体の中には汐莉の血が入っているのか、そして昔、自分と会ったことがあるのか? その問いに対して、汐莉は「あの事故」が起こる少し前の出来事について話し始めて――。', '2025/12/02 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f921711d-b11a-48c5-8024-277b737a4dfb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33cc03e2-ca9c-4bdc-aab5-3d42c0aaa518', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 10, '100246859', '祈りを込めて', '汐莉は美胡へ昔の話を語り出す。とある漁村で子供と一緒に暮らしていたこと。しかしその子供へ自分の肉をあげたことで、恨まれてしまったこと。自分は誰とも心を通わせられない世界の外側の存在だと知ったこと。そこから数十年も経ち、比名子と出会ったために自分が世界の内側に招かれた実感を得たこと。そして、比名子への想いが芽生えたことを……。', '2025/12/09 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e80e89c2-cfab-43ec-b936-4048c842e399.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30f8b199-f6bd-4b3a-9e3a-ede1ae5d9e74', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 11, '100247872', '冷たい朝', '「風邪気味」と伝えて学校を休んだ比名子だったが、美胡はそれが仮病であると看破。ひとりで比名子の家へ向かう。そこで汐莉から過去の話を聞いたことを明かしつつ、比名子が生きてくれて嬉しかったと告げるのだが……。比名子は家族と一緒に死にたかったと、言葉を吐いてしまう。', '2025/12/16 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ddf43151-0605-420e-bf2e-ace5cc15a60a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbbf3001-0338-4405-a52c-db385e3d9844', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 12, '100248453', '愛し子', '汐莉は比名子へ十年前に出会ったときのことと、本当の祈りを明かす。汐莉はただ、比名子に生きていて欲しかった。生きてもらうための口実として、比名子が望むことを口にしていただけだったのだ。その話を聞いた比名子は、汐莉へ「もう放っておいて」と叫ぶのだが……。', '2025/12/23 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/217cee14-4abe-4337-8e02-ba0d83954901.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af24397e-29aa-4600-af52-7063fbf90c7b', '899a9dc8-0a47-4e1f-8b98-e87e8452fb2e', 13, '100249129', '温かな海底', '【最終話】バスケ部の合宿を手伝ったお礼として、部員から温泉旅館の宿泊の話をもらった美胡は、比名子と汐莉を誘って旅行へ向かう。約束のし直しにより旅先にも関わらず暗い顔の汐莉へ、美胡は世話を焼いて比名子と一緒にいられる時間を作ろうとするのだが……。一方、比名子にも思ってもみない心境の変化があり……?', '2025/12/30 23:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c98bd52-1f47-4b9d-afdf-71a30a66b1c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b6ac1adf-3570-42e1-8434-589d31f1790e', '紫雲寺家の子供たち', '', 'hulu', 'the-children-of-shiunji-family', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5dcc7294-c25c-4611-a410-d83447758bc2.jpg?w=331&h=447&p=t', 'hulu', 2025, 1, 1, 'FINISHED', NULL, 174802, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 'b6ac1adf-3570-42e1-8434-589d31f1790e', 'hulu-the-children-of-shiunji-family-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55316760-0442-48f1-ac17-4f10bb7b4d1e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2b556d9-5dc4-4e28-800c-c4e74ce326c2', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 1, '100223758', 'What if…?', '世田谷区の一等地にある「紫雲寺家」には、絶世の美男美女と噂される7兄弟姉妹が住んでいる。長男の新は5姉妹に振り回され、その弊害で女子に対して奥手な性格となっていた。自分が紫雲寺家の人間でなければ……。別の「運命」に思いを馳せる中、末っ子･ことのの誕生会が開かれ、父親から衝撃の事実を告げられる!', '2025/04/11 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55316760-0442-48f1-ac17-4f10bb7b4d1e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b9b2ed0-6779-44f9-9c0d-5af2708da549', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 2, '100224505', 'Now what', '兄弟姉妹には血の繋がりがない――。その事実は7兄弟姉妹を少なからず動揺させた。さらに、謳華はことのが新に告白したことを志苑から聞かされ、大きな衝撃を受ける。一方、新には数々の試練が訪れる。裸で抱きついてきたことのだけではなく、部屋には清葉が待ち伏せており、いきなり驚きの行動に出て……!?', '2025/04/18 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d38e1378-beed-4616-997b-31ccb7c99f53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ae4538c-4ac6-4111-a3db-a496b1e75a84', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 3, '100225390', 'For now', 'ようやく紫雲寺家に平穏が戻ってきたかに見えたが、謳華はどことなく新のことを気にしていた。そんな中、7兄弟姉妹はことのの誕生祝いで大型テーマパークへ。早速、思い思いに行動を始め、取り残された新は万里からデートに誘われる。距離感の近い姉にからかわれ、調子が狂う新。だが、兄弟姉妹への想いを聞かされ……。', '2025/04/25 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2bad598-a471-4f12-b41b-67c9b48bd284.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10e88db0-8264-4284-a535-552f859c7086', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 4, '100225861', 'Respectively', '日曜日、いつも通り新が筋トレをしていると、南がやってくる。普段よりも早い時間にやってきた南は、どこかそわそわした様子。それもそのはず、南は謳華が新に「好き」と伝えた瞬間を目撃していたのだ! 2人の関係がどうなっているのか聞きたい南。そして、探り探り尋ねるのだった――「謳華ちゃんと、何かあった?」。', '2025/05/02 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c8a331a-ed0b-4c76-b46a-4b0b9429fef7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('241fb2ad-afbe-47c8-9379-3c0d9cf6dad9', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 5, '100226706', 'Perhaps', '最近、妙に真剣な表情をしている清葉。悩み事だと思った新が相談に乗ろうとすると、なぜかタッチマットゲームを提案される。新の部屋での一件は清葉の心にわずかな高揚感をもたらしたらしく、その感情を改めて検証したいのだという。密着をなんとか避けようとする新と、ぐいぐい迫ってくる清葉。果たして、検証の結果は!?', '2025/05/09 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b700ee86-7c6e-464b-9b0a-80494bdfccdd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f02d7090-b95a-4720-b55a-ae92fe75bc21', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 6, '100226986', 'Now''s the time', 'ことのの「告白」は、姉妹に大きな衝撃を与えた。南は動揺しつつもインターハイに向けた練習に励むが、実は足に怪我を抱えていた。団体戦に出られなくなれば、大切な先輩を勝たせてあげられない。怪我を押して練習を続ける南に、事情を知った新が故障者ケアをすると申し出る。そうして、2人きりのトレーニングが始まり……。', '2025/05/16 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae6cea0d-1311-4cce-ab84-c7281dcb17ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8853b7ab-5d0b-4189-b810-7b09ec509254', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 7, '100227688', 'Surely', '兄弟姉妹の心配をよそに、姿の見えなかった南が何事もなかったかのように帰宅。インターハイ決勝に出場しないことを明かし、早々に自室へ戻ってしまう。心配した新が部屋を訪ねると、南は驚くほど元気だったため、新は妹の決断を尊重しようとする。しかし朝方、南を偶然見たという志苑から、そのときの様子を聞かされ……。', '2025/05/23 23:30:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12320bce-599d-4169-a518-286bb91ca8e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7bc59b3-6de5-460b-9ec2-bcf979c367c9', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 8, '100228218', 'Since then', 'インターハイ決勝から数日後――。いまだ試合結果に納得のいっていない謳華をよそに、すでに結果を受け入れている南は、少しずつ新を意識するようになっていた。そんな中、ことのの部屋を訪れ、新への気持ちを確認しようとする謳華。そして、万里は看護大学に忘れ物をしたといい、新を誘って夜のキャンパスに忍び込む。', '2025/05/30 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b5a2b99-f845-4412-af45-a04a1caf5ec0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('185854ac-9a5f-400c-bb09-1d44aa09d145', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 9, '100228803', 'Not yet', '山梨に出かけた謳華が、3日過ぎても帰ってこない。延泊すると連絡があったものの、それきり返事はなく、学校も欠席。ファミリー共有のGPSを辿ったところ、謳華は富士山にいることが発覚する。新は高速バスで富士山を目指すことになり……。一方、8合目の山小屋に辿り着いた謳華は、どうしても見たいものがあるという。', '2025/06/06 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7da89a5c-9329-4e98-a1a4-138bf13be795.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7acdd8e5-ef7b-4ad4-ba68-aa8ac7636fbe', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 10, '100229371', 'Finally', '山道から滑り落ち、怪我をした謳華の前に現れたのは――新だった。かつて父と母が出会ったときのように、謳華をおぶって下山する新。すると、謳華はどうして富士山の山頂を目指したのかを語りはじめ、堰を切ったように抱えていた苦しみを吐露する。新もまた謳華の思いを受け止め、ここにやってきた理由を語る。', '2025/06/13 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f84efbd7-fe10-4c07-afa3-e228ab5c481d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd7094b8-17a6-4a66-87f9-24ddbc6dc09a', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 11, '100229868', 'So then', '軽井沢の別荘へやってきた紫雲寺の7兄弟姉妹。だが、新は謳華にされたキスに戸惑い続け、まともに彼女と話せなくなっていた。新の気持ちも知らず、謳華はあの日以来、毎日のように新の部屋を訪れるようになり、今度はテントサウナでの我慢比べに誘ってくる。しぶしぶ勝負を受けると、「彼女とか作らないの?」と聞かれ……!?', '2025/06/20 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f762201f-c590-4ae0-9f39-e25b9ba2b9f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26b321a2-09cd-42f0-9aaf-d5fefb4a42fb', '7b6dd70e-b88d-4525-9052-9bc8b9dd6af4', 12, '100230992', 'Still', '【シーズン1 最終話】奥軽井沢の川原でバーベキューをすることになった新たち。しかし、相変わらず新は謳華のことを意識してしまい、南もまたどこか落ち着かない様子。万里はいつも通り新をからかってばかりだが、ふいに笑顔を向け、思いを伝えようとしてきて……? 新を巡る姉妹たちの思いはますます膨れ上がり、交錯していく――。', '2025/06/27 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be918658-a18d-412a-bdfd-184f6201ca4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8154e3a6-6c1a-4d23-a93a-4e9fb157a0b5', '時々ボソッとロシア語でデレる隣のアーリャさん', '', 'hulu', 'alya-sometimes-hides-her-feelings-in-russian', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/127af2aa-a3e1-4ff2-be7b-60901d8af9cb.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 162804, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('39cc9198-c601-4063-ba1e-3683e43d2885', '8154e3a6-6c1a-4d23-a93a-4e9fb157a0b5', 'hulu-alya-sometimes-hides-her-feelings-in-russian-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8907644c-077c-472b-84c8-91e66ecd19da.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a618d83e-3771-4de0-a8fa-8b6c3f96b379', '39cc9198-c601-4063-ba1e-3683e43d2885', 1, '100189611', 'ロシア語でデレるアーリャさん', 'アーリャは今日も、先輩からの告白を玉砕し、完璧超人と噂されていた。そんな彼女が普段と違う顔を見せるのは、とある一瞬、隣の席でだらけている政近に対してだけ。授業中に居眠りをしていたり、休み時間に禁止されているスマホを使ってソシャゲをしていたり。そんな政近に日本語では注意しながらも、時々ボソッとロシア語でデレた言葉を呟くのだった。しかし、そのロシア語の意味が実は政近に伝わっていて……!?', '2024/07/03 23:30:00', 1481, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8907644c-077c-472b-84c8-91e66ecd19da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd23b464-8ed1-4cae-97c7-2cf45142e7b0', '39cc9198-c601-4063-ba1e-3683e43d2885', 2, '100190386', '幼馴染とは?', '政近の幼馴染みである有希の手伝いで、学園の備品整理をすることになった政近とアーリャ。使用用途の分からない備品に呆れつつ作業を進める中、生徒会長の統也がやってくる。彼は政近の仕事を認め、生徒会へ勧誘してきた。政近はその誘いを断るものの、同時にアーリャが生徒会長選挙への出馬を考えていることを知り……。そしてその夜、とある女の子が政近のマンションにやってきて……!? ドキドキのデートが始まる!', '2024/07/10 23:30:00', 1481, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa609c60-e62f-4ed3-b6c1-bad17cb23b70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd9527f3-5456-423f-9bb2-38a3dd94f9c4', '39cc9198-c601-4063-ba1e-3683e43d2885', 3, '100191178', 'そして二人は出会った', '数年前、グループで地域の仕事について調査することになったとき、アーリャは本気で課題に取り組んだ。しかし、グループの仲間たちは課題を適当に捉えていたことで、大喧嘩に。それからアーリャは他人に期待せずに生きていくようになる。しかし、昨年の学園祭で起きたとある出来事によって政近から諭され、その日をきっかけに考えを改めることとなるのだった。これは、アーリャが政近にデレるようになった、きっかけのお話。', '2024/07/17 23:30:00', 1481, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b60690d1-cf62-4714-bc88-b3f844e9ae55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b84cacf-eaf5-4484-98d6-1fd389ec073d', '39cc9198-c601-4063-ba1e-3683e43d2885', 4, '100192069', '溢れ出す想い', '生徒会に入ることを拒み続けている政近は、統也から自身が冴えない男子だった頃の話を聞く。そして、生徒会に入る動機が何であれ、そこに後ろめたさを覚える必要はないと諭される。一方で、アーリャは単身、野球部とサッカー部の校庭使用権を巡る会議を仲裁する仕事を請け負っていた。しかし、どちらもヒートアップし、アーリャは次第に追い詰められてしまう。その末にアーリャが発したロシア語のヘルプ。それに、応えるのは――!', '2024/07/24 23:30:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9af6c1d-44bb-485b-a87b-b1a1b622893a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe96643d-a8f8-4838-9b8a-d684053be43d', '39cc9198-c601-4063-ba1e-3683e43d2885', 5, '100192776', 'それぞれの決意', 'アーリャがボソッとロシア語で呟いた「好きよ」という言葉。そして、幼少期に初恋をした相手のこと。二人の女の子に政近が想いを巡らせる中、有希はお構いなしに兄との愉快な日常を過ごしに来る。しかし有希も、政近が生徒会長選挙で自分ではなくアーリャのサポートを務めることを聞いて……。一方、アーリャも自分が呟いてしまったことを思い出してはドキマギしており、政近から目を離すことができずにいた。', '2024/07/31 23:30:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49629c83-2db7-441a-a768-044ab3828618.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a2059fb-d690-4094-914c-2d10c631b5c0', '39cc9198-c601-4063-ba1e-3683e43d2885', 6, '100194033', 'いわゆるひとつの間接キス', '正式に生徒会入りを果たし、政近はアーリャとともに他のメンバーと交流しながら活動に奔走し始める。アーリャは有希からパートナーを奪ったことに対し仁義を切りに行くも、政近のことを誰よりも愛しているという発言に振り回されてしまい……!? 更には、ほんわかとしているマーシャが政近と話している様子にも嫉妬してしまう。そんな中、政近はアーリャが生徒会長を目指すにあたり、作戦会議をしようとファミレスに誘うが……?', '2024/08/07 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ada093d1-c6e7-48d4-ad3d-a962d66973a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbc1a84c-4875-4fe0-bafd-307347cdcaf3', '39cc9198-c601-4063-ba1e-3683e43d2885', 7, '100194612', '嵐、来たる', '有希が生徒会長選に向けてパートナーに指名したのは、彼女の従者である君嶋綾乃だった。綾乃は政近が有希ではなくアーリャの補佐役となったことで周防家当主が怒っていることを伝えるが、政近は「周防家の事情など俺には関係ない」と言い返す。その想いを知った有希もまた、アーリャ&政近にどう立ち回るのか考え始め……。一方、政近と綾乃が新たに加入した生徒会では歓迎会が開かれる。その裏では、新たなライバルが動き始めているとは誰も知らずに――。', '2024/08/14 23:30:00', 1481, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ba08f41-b506-4e97-acfb-b90c1e7b51c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('627af71d-b903-4d1e-85cb-bbd1e2998fb8', '39cc9198-c601-4063-ba1e-3683e43d2885', 8, '100195352', '学生議会', 'かつて有希と生徒会長の座を争った谷山沙也加が、アーリャと政近が有希と戦うことに対して、異議を申し立ててきた。更には、アーリャと政近を生徒会長選挙の出馬候補から引きずり下ろそうと、沙也加は二人へ討論会を申し込む。討論会の議題は、「生徒会加入における教師の査定の導入」。ここで負けては、生徒会長への道が閉ざされてしまう。二人は相手の戦法を推理しながら、勝てる策を練っていく。そして、討論会当日。勝利の行方は――!?', '2024/08/21 23:30:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ad21cc9-a235-483f-836a-325c014d1375.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f4a8b24-4061-41cd-9a92-03571fbcec76', '39cc9198-c601-4063-ba1e-3683e43d2885', 9, '100196030', 'ラブコメのち催眠術', '討論会は、沙也加が途中退席をしたために、アーリャの勝利に終わった。しかし、アーリャは生徒たちから揶揄されている沙也加のことが気がかりで、政近に彼女を救いたいと相談する。そこで政近は、彼女の幼なじみである宮前乃々亜のもとへ向かうのだった。一方で、生徒会を取り巻くラブコメの空気はさらに加速。政近とアーリャは有希たちと共に、副会長の更科茅咲が没収してきた本に書かれた催眠術を試してみることとなり……?', '2024/08/28 23:30:00', 1511, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83670688-4a36-4a5c-b458-fe7ed16fe5f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd998312-ed0e-43de-8e72-9a607b828406', '39cc9198-c601-4063-ba1e-3683e43d2885', 10, '100196794', '遅ればせながら、誕生会', '沙也加を揶揄する声も落ち着いたある日、アーリャから政近のもとへ電話がかかってくる。そこでアーリャは、政近がテストで学年30位以内に入ったら、なんでも言うことを聞くと約束した。しかしその会話の最中、自分が政近の誕生日パーティーに誘われなかったと知って、落ち込んでしまう。なぜなら、ロシアでは誕生日パーティーに誘うことが友好の証だったから! 彼女が落ち込んだ理由を知った政近は、アーリャをお出掛けに誘うのだった。', '2024/09/04 23:30:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1664ef2-d6f0-4e44-a2c1-268a947b4608.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28d7dfd4-09f0-421c-848a-7492a8354fc8', '39cc9198-c601-4063-ba1e-3683e43d2885', 11, '100198219', '予期せぬ前哨戦', '風邪を引いた政近は、有希に病欠の連絡を入れる。しかし、放課後に看病へやってきたのはアーリャだった。アーリャがおかゆを作ってくれたり、メイド姿の綾乃と対峙したり……。てんやわんやの一日を過ごした政近は、翌日昼頃になってようやく目を覚ます。一方アーリャは、有希がパーソナリティを務めるお昼の校内放送にゲストとして呼ばれていた。政近が病欠の中、果たしてアーリャは生徒会長候補として、この突発イベントを乗り切ることができるのか?', '2024/09/11 23:30:00', 1481, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7da11bb5-c86a-4910-9f3f-78dad636bb74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf56da0f-76bb-44ac-9ecb-dd03882ee841', '39cc9198-c601-4063-ba1e-3683e43d2885', 12, '100199153', '前を向いて', '【シーズン1 最終話】校内放送で有希に後れを取ったアーリャは、終業式での生徒会役員あいさつに向けて練習をし始める。終業式という全校生徒が集まる場で行われる生徒会役員あいさつは、実質的に生徒会長選挙の立候補者演説と同義。緊張が止まらないアーリャに、政近はある秘策を授ける。そして終業式が始まり、生徒会役員あいさつがスタート。有希と綾乃が堂々としたスピーチをこなした後、遂にアーリャが演台へと上がって……。', '2024/09/18 23:30:00', 1511, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fcefbbe-433f-4d75-aa7f-449fbd2a99f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('fe310e12-b5ef-4266-b9f9-aeed91130028', '時光代理人-LINK CLICK- 英都篇', '', 'hulu', 'link-click', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fabeee76-ba36-4e16-9d75-46290b506111.png?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'FINISHED', NULL, 170166, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3d0590b0-257b-4f2f-90da-6aac99241b0c', '治癒魔法の間違った使い方', '', 'hulu', 'the-wrong-way-to-use-healing-magic', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a7cfa5d-5759-4c94-95c9-0058c42223a3.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 137908, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', '3d0590b0-257b-4f2f-90da-6aac99241b0c', 'hulu-the-wrong-way-to-use-healing-magic-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47bd22ee-164f-44b3-b3bb-21466ac9ad74.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66ddab8e-25ad-414b-86a2-e17afecabb67', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 1, '100171402', '巻き込まれて異世界!', '平凡な高校生･ウサトは生徒会長のスズネ、副会長でクラスメイトのカズキと共に、突如異世界に召喚された。勇者としてリングル王国を救うよう頼まれる3人だったが、実は召喚された勇者はスズネとカズキの2人で、ウサトは巻き込まれただけだった! しかしウサトに治癒魔法の適性があることが判明すると状況は一変。そこに救命団団長を名乗るローズが現れる。', '2024/01/11 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47bd22ee-164f-44b3-b3bb-21466ac9ad74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e8af8c2-277a-4ac0-888a-06be1fb6a63d', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 2, '100172004', '地獄の始まり!', '救命団に所属することになったウサトは早速ローズと地獄の訓練を開始する。初日の訓練をこなし安心したのも束の間、翌日からひたすら走らされることに……。ローズの治癒魔法で強制的に筋肉痛を治されながら地獄の訓練を続けていく中で、ウサトの体には徐々に変化が……。', '2024/01/18 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a479e10-6363-452e-a5c3-e4f68fd38c48.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a433691-ef9d-45a0-90f8-8ab2eaaec381', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 3, '100172719', '過酷! リングルの闇!', 'ローズによって魔物がはびこる“リングルの闇”に放り込まれたウサトは、グランドグリズリーを狩るという試練のためにサバイバル生活を開始する。最初はグランドグリズリーに圧倒されたウサトだが、観察を続けるうちに少しずつ愛着が湧くようになる。数日後、意を決してグランドグリズリーを倒しに向かったウサトだったが、そこで凄惨な光景を目撃する……。', '2024/01/25 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b079d67-4c7d-40d6-a694-762595bf2fec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07f57cad-77d5-4a16-ae3f-f5ca8961d4be', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 4, '100173559', '救命団員ウサト!', '魔王軍との戦争が近いことを知らされたウサトは、ローズと同じように前衛としての活動ができるのか自信を持てないでいた。“リングルの闇”で出会ったブルーグリズリーの子ども･ブルリンを背負い、いつものように訓練を続ける中、城下町で同じ治癒魔法を使うオルガと出会う。同じ救命団の一員であるオルガの話を聞き、ウサトは救命団員としての覚悟を固めていく。', '2024/02/01 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33a73f2c-7480-402e-834e-137c6d9adbda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2858a1b-5909-4d33-ad7d-c124c5515458', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 5, '100174616', 'ウサト、再び森へ!', 'スズネの訓練に同行することになったウサト。騎士のアルク、魔法使いのコリン、ブルリンと共に訓練に向かう途中で盗賊団と遭遇する。難なく盗賊団を撃退していたウサトたちだったが、突如フォールボアの大群が襲来し、ウサトとスズネは弾き飛ばされてしまう。たどり着いた先はなんと“リングルの闇”。ウサトとスズネはそこで野宿をすることになり……。', '2024/02/08 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ad40711-672b-499f-af07-449c1083ab79.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7dd500b-7fd4-467d-93fd-55cf488a396a', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 6, '100175062', '迫り来る危機……!', '“リングルの闇”から生還したことをロイド王に報告するウサトとスズネ。2人の無事を喜びつつも、普段と違う魔物の様子から不穏な気配を感じたロイド王は、状況を確かめるべくローズに偵察を命じる。早速偵察に出たローズは、侵攻の準備を進める魔王軍と遭遇する……。一方オルガとウルルが営む診療所を訪れたウサトは、オルガたちとともに事故現場に同行することに……。', '2024/02/15 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c3f6a7f-fd4b-481d-a97d-f2f3e84385bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a7d3dbc-4bbf-41f3-82f3-ff2bbe2edc1f', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 7, '100175546', '決意の夜!', '獣人の少女･アマコに見せられた不穏なビジョンに困惑するウサト。夜になっても気になり眠れないでいると、窓に不思議な光球が現れた。光球に誘われるように外を見ると、そこにはカズキの姿が。ウサトを前にカズキは、勇者として戦場に立つことが怖いと、おもむろに自身の気持ちを吐露し始める……。', '2024/02/22 00:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2c4ff04-f975-4f6e-bd12-ede7aedda55a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18a31d29-90e4-4a8d-9f3c-6a520f18abaf', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 8, '100176190', '大隊長ローズ', '5年前、リングル王国騎士団大隊長のローズは、副隊長のアウルをはじめ一癖も二癖もあるメンバーを集めた直轄部隊を率いていた。ある日、偵察任務の命を受けたローズとアウルたち隊員は、“リングルの闇”へ向かうことに。隊員同士の想いを確かめ合った翌朝、ローズたちは魔物を運び出そうとする謎の魔族の集団と遭遇する。その中には只ならぬ雰囲気を纏う一人の魔族の姿があった……。', '2024/02/29 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eae539c9-398b-4fbd-81e9-160c623e8a3a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80729200-9c34-40e1-9568-ff820853f891', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 9, '100176918', '終わりと始まり', '“リングルの闇”で剣を交えるローズ直轄部隊と魔王軍。ローズと隊員たちが魔王軍を少しずつ押し始め、戦況はローズたち優勢に傾きつつあった。魔王軍の将･ネロは、ローズたちの実力を認め、自身の部下に捨て身の攻撃を命令する。相打ち覚悟の攻撃に次々と倒れていく直轄部隊の隊員たち。怒りと動揺で精彩を欠いたローズに、ネロの攻撃が容赦なく襲いかかる……。', '2024/03/07 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/004e6bd3-d206-480f-b69d-1320ada189ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99f58dd3-6085-4511-9010-17382a6d03c4', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 10, '100177706', '最狂!? 黒騎士現る!', 'いよいよ魔王軍との戦争が始まった。ウサトは黒服たちの手により、続々と運ばれてくる要救護者の治療を行う中で、改めて戦場の厳しさを実感する。戦況が進み、ローズとともに戦場の最前線に出ていくウサト。鍛え上げた身体能力を駆使し、魔王軍の猛攻の中、次々と王国騎士たちを救っていく。一方、勇者として前線で戦うスズネとカズキの前に、黒騎士と呼ばれる謎の魔族が現れる。', '2024/03/14 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b504bd0-4538-4f2c-8fb9-db487ba15e3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36a92cf8-67cc-4f07-8b1f-fe1f4a58f725', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 11, '100178286', '炸裂! 必生の拳!', '攻撃を“反転”させる黒騎士に対し、為す術もなく倒されてしまうスズネとカズキ。黒騎士がトドメを刺そうというその時、間一髪で放ったウサトの拳が黒騎士の顔に炸裂する。受けるはずのないダメージに感情的になる黒騎士。その後もなぜか“反転”が発動しないウサトの攻撃により、黒騎士は次々とダメージを負っていく。それはウサトの“治癒魔法の間違った使い方”が影響していた。', '2024/03/21 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a06951e-0ad4-4cec-9d65-a5cc0fdb0769.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('356c312d-cf4a-4979-8219-72cd3f056f51', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 12, '100178731', '黒騎士の素顔!', '次の戦いに備え、捕虜となった黒騎士を尋問することにしたリングル王国側に対し、黒騎士は尋問に応じる条件としてウサトと会わせることを要求する。要求が通り、黒騎士が捕らえられた牢にやって来るウサト。そこで誰も気づかなかった黒騎士のダメージに気づき、ウサトは敵である黒騎士に治癒魔法をかける。ウサトの治癒魔法で傷を癒された黒騎士は……。', '2024/03/28 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d9e0ab7-12bd-49f3-a4a5-babcb7bf83e8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('551adf18-3608-4e29-806d-ede64ef5a439', '2bfcc89c-a69d-44ea-8a1c-9e5e708c808f', 13, '100179552', '旅立ち!', '【最終話】スズネとカズキの危機を知らせてきたアマコから、今度は母親を救ってほしいと告げられたウサト。そこでアマコがはるばる獣人の国からリングル王国までやって来た理由を知ることになる。アマコから獣人の国への同行を求められるも、ウサトは救命団員としての立場もあり、なかなか結論が出せずにいた。考えた末、ウサトは獣人の国に行くためのある一手を思いつく……。', '2024/04/04 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5092fb44-1032-4465-912c-3156f3e1f396.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('cea5f880-ea63-4ce9-a77d-a67407d8289e', '自動販売機に生まれ変わった俺は迷宮を彷徨う', '', 'hulu', 'reborn-as-a-vending-machine-i-now-wander-the-dungeon', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74357c29-9584-4480-94eb-e0aba2a883b7.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 153360, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 'cea5f880-ea63-4ce9-a77d-a67407d8289e', 'hulu-reborn-as-a-vending-machine-i-now-wander-the-dungeon-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/177d2f7a-44e3-4983-a75a-5fa6e4f256ca.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8811b44f-633e-40c0-a88d-2c02e866608d', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 1, '100151848', '自動販売機、移動する', '交通事故にあった俺は、目が覚めると湖のほとりに立っていた。身動きも取れず、声も出せず、どうやら自動販売機に生まれ変わってしまったらしい!? 戸惑う間にも魔物に襲われ、危機的な状況に。困り果てていると、目の前にハンターの少女･ラッミスが現れた。', '2023/07/12 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/177d2f7a-44e3-4983-a75a-5fa6e4f256ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3351549f-68d6-4ef1-a85a-63236204f751', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 2, '100152409', '王蛙人魔が現れた', '熊会長からの依頼を受け、ハッコンとラッミスは蛙人魔の討伐へ同行することに。ハンター達への食糧提供を任されたハッコンは大活躍。護衛として参加する「愚者の奇行団」の面々との交流も深める中、絶え間ない蛙人魔の発生に異変を感じ…?', '2023/07/19 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c72462a0-b2a9-4225-ae6d-80d0d6837ea8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b70cace-718c-4752-8a83-0da57d2e3c94', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 3, '100153308', '復興', 'ハッコン達が遠征に出ていた間、集落は魔物の襲撃を受けていた。住人達は無事だったものの、翌日から村の復興が始まる。ラッミスが持ち前の怪力で瓦礫撤去を手伝う一方で、ハッコンにもまた、自動販売機ならではの相談が各所から舞い込む。', '2023/07/26 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16862919-2641-4780-ac47-3cfdf0998a5b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('155a6a37-9c30-4162-acde-52e7656c77b5', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 4, '100153783', 'ハッコン、誘拐される', '突如誘拐されてしまったハッコン。悪党に連れて来られたアジトには、ラッミスの幼馴染･ヒュールミもまた監禁されていた。魔道具技師である彼女は、持ち前の頭脳でハッコンの能力をすぐに理解する。様々な商品を駆使しながら助けを待つ2人だが…。', '2023/08/02 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4751c5cc-530c-4c0e-a5b6-ea4fd40400d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8bb9d04d-f2f5-424b-876d-387476858633', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 5, '100154689', '見栄とプライドと自動販売機', '無事に集落へ戻ったハッコンとヒュールミ。2人はスオリの頼みで魔道具のお披露目会へ参加することに。当日、会場にはスオリが目の敵にする令嬢のカナシの姿が。出場者の魔道具が次々披露される中、カナシの用意した魔道具にはある秘密があった。', '2023/08/09 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/befe0f41-aeaf-469a-a75d-785290029936.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53ead8a6-618f-4860-8892-f660da1b5384', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 6, '100155462', '戦う自動販売機', '凶暴な鰐人魔の調査のため、ハッコンとラッミスはふたたび愚者の奇行団と遠征へ。たこ焼きや焼きそばなどハッコンが提供する食べ物に団員達は大喜び。やがて鰐人魔の生息する沼地へ近づくと、ハッコンは立地を活かしたある作戦を思いつく。', '2023/08/16 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44427bc8-d344-49fb-9890-2106f9f5420e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbd5c7c3-b2a1-435b-bc23-8f3ca8878d4a', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 7, '100156129', '暴食の悪魔団', 'ハッコンが階層の割れ目から落ちた先は、巨大な迷路の中。誰も現れないまま数日を過ごしていると、豚の魔物に追われる4匹の袋熊猫人魔に遭遇! モフモフな彼らに癒されつつも、必死にコミュニケーションを試みるハッコン。果たしてラッミスの元へ帰れるのか!?', '2023/08/23 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2d54b47-02ca-48ee-abc0-c62ff435bf2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aeecb2e6-5224-4037-adc8-f9265b97b79f', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 8, '100156606', '迷路階層の炎巨骨魔', 'ケリオイルから炎巨骨魔の討伐に誘われたハッコン達。どうやら愚者の奇行団は「どんな願いも叶う」という迷宮に伝わる伝説のために、階層主を倒してコインを集めているらしい。大食い団も仲間に加わり、一行は迷路階層の階層主である炎巨骨魔へ挑む。', '2023/08/30 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ca41472-d63c-48f0-ad98-47ea866a98e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c18620c-8981-45aa-9d05-3df26cabc994', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 9, '100157319', '理想の英雄未満', 'ハンター協会で金髪の美剣士･ミシュエルと出会う。イケメンに振る舞っているようで時折挙動不審になるミシュエルは、実は極度のコミュ障。ハッコンが陰ながら見守る中、ミシュエルはコミュ障を克服するため愚者の奇行団へ同行することに。', '2023/09/06 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/096e276b-42cb-4d09-9ffa-b208cc800dfe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc4cb0ce-4ae2-4cab-b576-a1503dd2b644', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 10, '100158152', '胃袋の果てに', 'ムナミの提案で大食い大会が開催されることに。大会当日まで順調に参加者が集まっていたが、食いしん坊のシュイと大食い団の参戦により飲食店は一気に赤字のピンチに! 店主達に泣きつかれたハッコンは、飲み物にある工夫を凝らした提案をする。', '2023/09/13 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be9d79e9-feaf-4012-9dc7-cb7a4cda042d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6597275b-033a-4dd6-845d-ad505c14e1a9', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 11, '100158716', '亡者の嘆き階層', '愚者の奇行団の次の遠征先は、亡者の嘆き階層。死人魔や骨人魔が出るらしく、怖がりなラッミスは出発前からビビってばかり。集落に到着しても依然怯えるラッミスをハッコンは優しく見守る。そんなある晩、ハッコンは宿屋の前で子供の死人魔と出会う。', '2023/09/20 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57e2e5a4-f9da-4e82-bf77-696682cbccc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('566b4aa1-359a-4574-9c6a-4f112f517c36', '49f20a69-f45a-4ab9-b7ac-1af24dcfe221', 12, '100159724', '自動販売機として出来ること', '【最終話】いよいよ死霊王との戦いが始まった。ハッコンによる作戦もあり、愚者の奇行団の総力を尽くして立ち向かう。これまでにない手強い敵に、ギリギリで応戦する団員達。果たして勝てるのか!?', '2023/09/27 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a7396c0-205c-4635-923a-cd0108994d0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7dea78c5-c0e6-4fdf-8f41-673f56f69fce', '自動販売機に生まれ変わった俺は迷宮を彷徨う 2nd Season', '', 'hulu', 'reborn-as-a-vending-machine-i-now-wander-the-dungeon-2nd-season', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93c847d4-201d-4198-aec2-35e27a32048d.jpg?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 169440, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c5d37952-cf6c-4a0a-8df7-b25624149ca0', '7dea78c5-c0e6-4fdf-8f41-673f56f69fce', 'hulu-reborn-as-a-vending-machine-i-now-wander-the-dungeon-2nd-season-s1', '2nd season', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7581bfce-b72a-411f-bd42-6edf9317c138.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('245056b7-e352-44c9-a2b1-9da8d548abad', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 1, '100231797', 'ハンターと思惑', '死んで自販機に生まれ変わるという、とんでもない事態になってしまった俺。そこは空もあり季節もある、複数の階層からなる迷宮の中だった。そんな中、各階層のハンター協会の会長たちが集まる重大な会議に呼ばれて…!?', '2025/07/07 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7581bfce-b72a-411f-bd42-6edf9317c138.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5302aa30-c512-4583-89cd-ab05dc33ee0c', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 2, '100232490', '意思の疎通', '冥府の王の思い通りにはさせまいと、各階層へ急ぎ戻る一行。そこで待ち受けていたのはたくさんの避難民と、魔物に襲われて変わり果てた集落だった――。', '2025/07/14 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c6d477a-0466-40ed-92cd-c4469775dda4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('298450ae-a7fe-4b42-badb-ff2a2b2ad0ee', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 3, '100232891', '強い想い', '魔物が次々と侵入してくる壁の大穴を塞ぐため、ハッコンは巨大自動販売機へフォルムチェンジすることに。大量の金貨を必要とするため、スオリの屋敷に向かうが…', '2025/07/21 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ffe56de-c034-4375-b3bf-92551f7b3ca4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('102034fb-14de-4129-b9f8-16cae97de932', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 4, '100233487', '聖職者と自動販売機', '激戦の末、清流の湖階層はひとまず平穏を取り戻した。復興作業中、陥没した地面の穴を見たハッコンは、みんなのためにとあるモノを作ろうと閃いた。', '2025/07/28 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa4d6efa-56bf-47f5-a20d-8198c2af24f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee9380b1-6094-41ee-98b9-0a2d4981fd1d', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 5, '100234054', '各々の望み', '「愚行の奇行団」の治癒担当である聖職者･へブイが仲間に加わった。そんなある日、自動販売機の分類について復習してたハッコンは、自らの新しい機能に気が付き……?', '2025/08/04 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5d3e4b3-c8af-45d5-8536-c161bd9f5b1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fdbdbb5b-f480-4669-ba74-93d3cf98be4e', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 6, '100234719', '甘い誘惑', '始まりの階層で復興作業を続けるハッコンたち。そんな中、ケリオイルに連れられて「愚行の奇行団」の拠点へ向かうことになる。ハッコン達が目にしたものとは――?', '2025/08/11 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd8aa95c-45b5-4b03-ada7-ac124424cfd3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7b609d6-3ce5-4dbf-a32a-aa9e7020588e', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 7, '100235143', '動物と少女', '突如、迷路階層に転送されてしまったハッコン。熊会長とヒュールミと行動する中で、謎多き少女･キコユと出会う。彼女は魔物を吸収する不思議な力を持つ土の球「畑の欠片」とともに行動していて…!?', '2025/08/18 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0ad1887-1044-462a-9187-4ff882dda4d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1297f491-8a15-4265-be11-377be55fd8d2', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 8, '100235515', '闇の森林階層', 'ラッミスと再会した一行だったが、転送陣がまたも暴走し、人の形をした不気味な木々が立ち並ぶ闇の森林階層へとたどり着く。ハッコンたちは森の奥へと踏み込むが――。', '2025/08/25 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef9c7502-6a67-4233-b446-37acca6809ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43066f41-e744-4b97-b7b2-31d071a928a1', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 9, '100236110', '大炎上', '階層主を討伐するため、襲い掛かってくる魔物を倒しながら森を進むハッコンたち。そんな中突如、森の奥で巨大な炎が上がる――何者かが階層主を焼き殺したようで…!?', '2025/09/01 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abd89e2b-d43c-4935-94a3-fa50f4d138ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4106b40-193a-4e56-bd30-d4a01c12a613', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 10, '100237267', 'ダンジョン女神グランプリ', '清流の湖階層で「ダンジョン女神グランプリ」が開催! 主催のムナミによる巧みな誘導で、ラッミスとヒュールミも参加することに。 果たして、栄冠を手にするのは誰なのか…!?', '2025/09/08 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d08046a-b4ac-4974-91f0-4ec8b6017281.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('816e32f3-9e67-4eb2-a329-164fa5197257', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 11, '100237727', '灼熱の砂漠へ', '突然姿を消したへブイの後を追い、灼熱の砂階層に向かった一行。焼けるような暑さの中で情報を集めると、そこで浮上したのは「滾る爆炎の団」と呼ばれるハンター集団の名だった。', '2025/09/15 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6c040da-b3a5-4896-8462-a03f4912b9d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('98591481-687b-4632-affd-5d5ffe2cb289', 'c5d37952-cf6c-4a0a-8df7-b25624149ca0', 12, '100238276', '砂漠の吹雪', '【シーズン2 最終話】ついに「滾る爆炎の団」のリーダー･タシテを追い詰めるヘブイ。しかし、追いつめられたタシテは階層主の双対鬼を目覚めさせる。桁外れな強さの双対鬼に、ハッコンたちはある作戦を決行することに…!', '2025/09/22 22:00:00', 1412, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1d32cbb-d66f-4581-900e-7977ef28584d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4ca15244-9290-4517-a2d6-dce91d572d54', '七つの大罪', '', 'hulu', 'the-seven-deadly-sins', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f353620f-12d1-4a51-a721-35695a8d7f08.jpg?w=331&h=447&p=t', 'hulu', 2014, 3, 1, 'FINISHED', NULL, 20789, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', '4ca15244-9290-4517-a2d6-dce91d572d54', 'hulu-the-seven-deadly-sins-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c321f3b-9792-4363-ab73-eb6a8eb07d05.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0a2369f-9eef-4df1-8624-5404481c8702', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 1, '100012022', '七つの大罪', '絶大なる魔力を有し、人々から敬われ、時に恐れられる存在〈聖騎士〉に守られた『リオネス王国』。王国の王女エリザベスは、たった一人国を離れ、ある者たちを探す旅に出ていた。それは最強最悪の騎士団として恐れられ、国を裏切り、全聖騎士を敵に回した罪人たち―〈七つの大罪〉。たどり着いた一軒の酒場で、エリザベスは店主を名乗る少年･メリオダスに出会う。それは、彼女と〈七つの大罪〉たち、そして世界の命運を一変させるとびきりの冒険の始まりであった―!', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c321f3b-9792-4363-ab73-eb6a8eb07d05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8c061df-912b-4f8d-b5db-1a4375d1483a', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 2, '100012023', '聖騎士の剣', '〈七つの大罪〉の情報収集と〈豚の帽子〉亭でふるまうお酒を仕入れるためにエールで有名なバーニャの村に訪れたメリオダスたち。しかし、バーニャエールの材料である名水は、訪れた聖騎士の魔力によって水源を封じられ、枯れてしまっていた。途方に暮れるバーニャ村の人々。そこに、〈七つの大罪〉の友人だと語る村の少年が現れ!?', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3961acdd-1ef4-48bb-af95-76277d52eaab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00be6e5e-555d-4275-a1ed-fa62f007c383', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 3, '100012024', '眠れる森の罪', 'メリオダスたちが新たな〈七つの大罪〉を探して訪れたのは、聖騎士も恐れて近寄らないという白夢の森だった。深い霧に包まれた森で、悪戯子鬼のハイドアンドシークの妨害を受けながらも、彼らに匿われた巨人族の少女のもとに辿り着く。その少女こそが〈七つの大罪〉の一人、嫉妬の罪、サーペント･シンのディアンヌであった!', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7520fab-0096-442f-a4d0-7e7f231e7a0d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ea38959-cb77-47cf-9ad9-a9d9cb77f55b', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 4, '100012025', '少女の夢', '聖騎士･ギルサンダーから残りの〈七つの大罪〉の情報を聞き出すべく、彼の剣をわざと受けたメリオダス。強欲の罪、フォックス･シンと怠惰の罪、グリズリー･シンの居場所を聞き出したが、その傷は深く、強欲の罪･バンが捕えられているというバステ監獄に向かう途中で倒れてしまう。さらにバステ監獄には、バンを捕えた4人の聖騎士〈不気味な牙 (ウィアード･ファング)〉が待ち構えていて!?', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62f7d468-529c-437b-8652-37ea662043d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c6bef81-e1a4-447e-b9b9-4dd9648c2336', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 5, '100012026', 'たとえあなたが死んでも', 'バステ監獄近くのダルマリーの町で傷を癒していたメリオダスは、〈ウィアード･ファング〉ゴルギウスの策略で、町の医師･ダナによって毒を飲まされてしまうが、刃折れの剣が奪われそうになった瞬間、謎の力でこれを跳ね返し、窮地を脱する。しかし、安心したのもつかの間、〈ウィアード･ファング〉は新たな攻撃を仕掛けてくる!', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13bcd19a-96a3-4462-bec3-c4f23b8d1364.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e05c886c-a2a8-4b51-8ad2-a52473cc55f4', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 6, '100012027', 'はじまりの詩', '〈ウィアード･ファング〉ルインの幻術によって、お互いを敵だと思い攻撃し合うメリオダスとディアンヌ。しかし、エリザベスの強い意志と活躍により、幻術を解くことに成功する。その頃、バステ監獄では牢を出たバンが自身を捕えた〈ウィアード･ファング〉ジュドと対峙していた。', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a881b8f7-dfed-44e6-82f5-d3f427ccbc62.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05ac3618-4887-45ee-8053-b155c18e2a36', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 7, '100012028', '感動の再会', 'バンと合流したメリオダスたち。死んだとされている怠惰の罪、グリズリー･シンのキングの手がかりを求め、死者の都を目指す。近くの町で情報収集のため〈豚の帽子〉亭を営業する一行だが、バンはサボって単独行動。そんなバンを付け狙う人物が…!?', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68a4ab62-3a08-4737-bebb-eae42a728da8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d74465a-8b94-4987-a2df-a4cff5f28bfd', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 8, '100012029', '恐るべき追跡者', 'メリオダスたちの前に姿を見せたキング。しかし彼はバンに強い恨みを抱き、復讐を果たそうとしていた。何かを追いかけて死者の都を進むバンの前に立ちはだかるキング。さらに、メリオダスたちの前には彼らを追う聖騎士･ギーラが現れ…!?', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53c69c95-fdd5-41b4-871b-789fd0c58e06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03222d35-b64d-4493-9a40-f92fdd617901', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 9, '100012030', '暗黒の脈動', 'ギーラに追い詰められたメリオダスたちを救ったのは、エレインの説得を受けたキングだった。神器･シャスティフォルを使い、圧倒的な強さを見せつける。一方、二人の聖騎士長ドレファスとヘンドリクセンが実権を握る王都では、一部の聖騎士たちによる不穏な動きが始まっていた。', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0af48406-5559-40c8-9e98-68a9dd6ee2ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6986e5c3-85a7-496c-95ad-e35d6b5549e9', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 10, '100012031', 'バイゼル喧嘩祭り', 'ディアンヌの神器･ギデオンがバイゼルの町の喧嘩祭りの優勝賞品になっていることを知り、参加することにしたメリオダス、バン、キング。なんとそこには聖騎士･ハウザー、グリアモールも参加していた。さらに圧倒的な強さを見せる少女･マトローナがマントを脱ぐと〈豚の帽子〉亭の制服を着ていて!?', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4299d288-c889-45f5-95d1-b49c5c7cc1c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d63eb13-11d3-49b4-bde6-1b2482200e0e', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 11, '100012032', '積年の想い', 'バイゼル喧嘩祭り1回戦最終試合、メリオダスとバンの試合が始まる。メリオダスの拳を受け、彼との出会いを思い出すバン。強奪〈スナッチ〉の能力を駆使し、メリオダスを追い詰めるが…!? 一方、バイゼルの町ではベロニカとグリアモールがエリザベスを探し回っていた。', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4560c12d-6347-401e-bd19-8f829baf55c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08bb5ed6-3820-416d-aec9-2f329cca051c', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 12, '100012033', '戦慄のカノン', 'メリオダスVSディアンヌの喧嘩祭り決勝戦。嫉妬で怒ったディアンヌとメリオダスの真剣勝負が開始したかに思われたが、なんとジェリコ、ギーラたち聖騎士団の襲撃を受け、喧嘩祭り会場はパニックに。聖騎士たちの目的は―!?', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f591c4fa-d7c2-4f6e-9dc9-e18949de0135.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e7b6982-4e8f-45b8-b3f7-85068b3b77c9', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 13, '100012034', '破壊の使徒', 'ヘンドリクセンがベロニカに渡した女神の琥珀に封印されたメリオダスだったが、エリザベスたちの危機に封印を破って現れる。圧倒的な力を見せつけるメリオダス。しかし、その様子は普段の彼ではなく、敵はおろか味方にまで攻撃を始め!?', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9dc455db-043d-4993-9c6b-030a68bb1227.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d4ea2b1-aff1-4e13-a6df-68c392fc0f69', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 14, '100012035', '本を読むひと', '聖騎士たちを退けたメリオダスたちは残る〈七つの大罪〉を探して新たな旅を始めていた。一方、聖騎士ヘルブラムはオーダンの森に現れた鎧巨人を狙って、殺戮集団〈暁闇の咆哮 (ドーン･ロアー)〉を差し向ける。その鎧巨人の鎧は色欲の罪、ゴート･シンのゴウセルのものであった。', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2666c05f-f1cc-48af-9cb3-84cdc83cf373.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f97337a0-4cef-4e5f-8f88-2780bfbe98d1', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 15, '100012036', 'アンホーリィ･ナイト', '〈ドーン･ロアー〉の攻撃が鎧巨人を捉えたその時、変装を解いたゴート･シン、ゴウセルが現れる。久しぶりの再会を喜ぶのもつかの間、ゴウセルは意外な行動に出て!? その頃、〈豚の帽子〉亭にはケインが訪れ、エリザベスはメリオダスの過去とリズの存在を知る。', '2023/09/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98a467ae-fb0e-4d99-b5f3-f0a55f43327e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('866e0d8a-77bf-4f22-961a-3618422ed005', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 16, '100012037', '駆り立てられる伝説たち', 'エリザベスの言葉で戦う決意をしたメリオダス。ゴウセルが仲間に加わり、10年前の事件でメリオダスの意識を奪った人物が明らかになる。王都ではドレファスがヘンドリクセンを警戒する中、ヘンドリクセンたちが魔神復活のための儀式を始め―。', '2023/09/21 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38b9fbcb-4330-466a-b476-e76c342b70c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a08191cd-b99f-4cfc-926c-7e123baecc16', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 17, '100012038', '最初の犠牲', '連れ去られたエリザベスを追いかけリオネス王都に突撃するメリオダス、バン、ゴウセル。迎え撃つ聖騎士たち。時を同じくして、リオネス王国に大量の兵を率いて、キャメロットの王･アーサーが現れる。ヘンドリクセンと対峙するが―!?', '2023/09/21 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06be2d19-1a9f-429f-9570-910af093bd91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('435289eb-6dbd-4f7d-be28-12dfda93e4ba', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 18, '100012039', 'この命にかえても', '聖騎士たちの攻撃の中、ギーラの弟･ジールをかばい瀕死のディアンヌ。さらなる攻撃を仕掛けようとするヘルブラムたちに、ハウザーとギーラが反旗を翻し立ち向かうが、ドレファス、ギルサンダーの圧倒的な魔力の前に苦戦を強いられる。そこにゴート･シン、ゴウセルが駆けつける!!', '2023/09/21 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/105a149d-f2e9-4685-8be2-94348a6b5c48.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3b30eec-efe0-45dc-8eb2-aa25954a7c18', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 19, '100012040', 'まちぼうけの妖精王', 'ディアンヌを守るため、ヘルブラムと戦うキング。思い出される700年前の記憶―妖精王であったキングとディアンヌとの意外な出会い、そしてキングとヘルブラムに起こった悲しい事件。親友であった二人が交わした約束とは!?', '2023/09/21 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13da9a6f-6ee1-4032-908f-b0966f255b2d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db8a67a4-3313-45fb-ae0f-9dc47cff1529', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 20, '100012041', '勇気のまじない', 'キングとヘルブラムの戦いが終結を迎えた頃、メリオダスは刃を交えるアーサーとヘンドリクセンの前に辿り着く。エリザベスを取り戻すべく、ヘンドリクセンと対峙するメリオダス。そこにビビアンの魔術によって送りこまれたギルサンダーが現れ、メリオダス･アーサー対ギルサンダー･ヘンドリクセンの壮絶なバトルが始まる。', '2023/09/21 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/614aaeee-9138-45b5-b16c-666940bd3b40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b383b291-a4e1-4f69-a591-a576c7fd2ed7', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 21, '100012042', '今、そこにせまる脅威', '暴食の罪、ボア･シンのマーリンの登場により、ビビアンの野望は打ち砕かれ、メリオダスはエリザベスとの再会を果たす、一方、エレインを生き返らせるため、王国の地下神殿にある〈ケルヌンノスの角笛〉で女神族と交信するバン。望みを叶える代償として女神が提示した条件は“ある人物を殺す”ことだった。', '2023/09/21 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7ab51fd-a99d-42ea-baa4-831b3c4303fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77ff6d12-de23-42ec-a721-4ffb523e3ebd', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 22, '100012043', '君のためにできること', '魔神の力で復活したヘンドリクセンの手に落ちたエリザベス。追いかけるメリオダスの前に、バンが立ちはだかる。バンはエレインのためにメリオダスを殺さなければならないという。一方、ディアンヌたちは、魔神化し暴走させられた新世代たちに苦戦を強いられている。そんな中、ヘンドリクセンの前に現れたのは消えたドレファスであった。', '2023/09/21 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b278e8f3-5ca2-46bb-8376-0e21f445d729.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c55e7b3-987a-4136-a8ab-318358c39f8e', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 23, '100012044', '絶望降臨', 'ヘンドリクセンを追う〈七つの大罪〉はかつて妖精王の森を襲いバンに倒された〈赤き魔神〉の屍体を目にする。この魔神の力を手に入れたヘンドリクセンをバンが一蹴。しかしさらに地下深く、もう一体の魔神の屍体が。その血を体内に取り込んだヘンドリクセンは強大な魔力を手に入れ、メリオダスたちの前に立ちはだかる。', '2023/09/21 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21de8b60-a1de-487f-9003-95c88179a028.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cdf3c2f-0de2-46ee-9d27-7d622f685a81', 'ed11cbb1-cd82-40f0-b914-3c1ed0051e6d', 24, '100012045', '英雄たち', '【シーズン1 最終話】ヘンドリクセンの圧倒的な力の前に〈七つの大罪〉さえも敗北するかに見えたその時、エリザベスの力が開花する。その力によって回復したメリオダスたちは戦意を喪失した聖騎士たちを鼓舞し、ヘンドリクセンに対峙する。〈七つの大罪〉と魔神･ヘンドリクセンとの戦いが遂に決着!!', '2023/09/21 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d694bcd-f97e-4eaf-8886-da31d24a3fac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8c68aa19-f7e3-45bb-9d01-fcd258db3c45', '七つの大罪 戒めの復活', '', 'hulu', 'the-seven-deadly-sins-revival-of-the-commandments', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f66a4054-73cb-43e3-8466-b73b13da70a8.jpg?w=331&h=447&p=t', 'hulu', 2018, 0, 1, 'FINISHED', NULL, 99539, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('90c477fa-b5dd-427b-b6d0-a3d9506b16ee', '8c68aa19-f7e3-45bb-9d01-fcd258db3c45', 'hulu-the-seven-deadly-sins-revival-of-the-commandments-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94688c82-988b-4ff9-bd38-96c87920b658.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0573f1c9-0db6-4b83-b9bd-17e02bf3b567', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 1, '100013221', '魔神族復活', 'ようやく平和が訪れたリオネス王国、その第三王女エリザベスは夢を見る。―闇に包まれる世界。現れる十体の影。何者かと戦うメリオダス。〈七つの大罪〉とともに旅に出るエリザベス。その話を聞き国王バルトラは眉をひそめるが、王国を救った〈七つの大罪〉へ勲章授与式を開催する。しかし〈七つの大罪〉の勲章授与に異議を唱える者がいて…。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94688c82-988b-4ff9-bd38-96c87920b658.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c08cace5-e527-4a79-b3bf-320b185bc020', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 2, '100013592', '存在と証明', '〈七つの大罪〉から抜けることをメリオダスに告げて〈豚の帽子〉亭を去るバン。後を追うキング、そしてなぜかついてきたジェリコ。向かった妖精王の森で歓迎を受けるバンに対しキングは…。そんななか大地を揺るがす光が空に向かって放たれる。三千年の封印から復活した十戒はエジンバラの丘を目指す。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c54df05-aebe-42bf-8946-555cd057c978.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('646aa3f6-95cd-4940-ae68-017a1738473e', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 3, '100013748', '神器ロストヴェイン', 'ギーラとジールから記憶を奪ったのは、感情を理解する心を欲するゴウセルだった。記憶をもてあそぶような行為を許せないディアンヌは、神器を手にするゴウセルとぶつかることに。そこへメリオダス、マーリンも駆けつけ、ついにゴウセルの正体が明らかになる…!', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2276731e-e032-4615-9505-91eb5a7883f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51958d3f-1e1f-4727-8494-9f0cfc4bbe26', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 4, '100014073', '〈十戒〉始動', '王都キャメロットに出現した魔人族に作られた古の兵器、巨獣アルビオン。空飛ぶホークママから飛び出し、メリオダスは神器ロストヴェインを振るいアルビオンを粉砕する。だがアルビオンが現れたのはキャメロットだけではなかった。妖精王の森に現れた、その大樹をしのぐ大きさのアルビオン。妖精たちから裏切り者と言われてしまったキングは、それでも大切な故郷を守るためアルビオンへ立ち向かう。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f266590-2e27-47bc-88a1-daec13ed874a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d982163c-80e4-4b79-962f-1728df69d3af', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 5, '100014356', '圧倒的暴力', 'メリオダスたちの前に現れた〈十戒〉のひとり、ガラン。ホークの魔眼が示したのは、魔眼の異常を疑うほどに飛び抜けた数値だった。その圧倒的な力に挑むメリオダスだが…。一方旅に出たギルサンダー、ハウザー、グリアモールの三人はバイロンの町を襲う赤き魔神に遭遇する。力を合わせる三人の前に予想外の人物が現れる…!', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c418f2d7-021d-44e8-97b6-cf610fd496f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36e87a78-7fbc-4406-bd28-36f04bf56b2a', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 6, '100014602', '償いの聖騎士長', '灰色の魔神と戦うギルサンダー、ハウザー、グリアモールの前に現れたのは、メリオダスに倒されたはずのヘンドリクセンだった。戸惑いながらも協力して灰色の魔神を倒す四人。ギルサンダーの覚えのある力を放つヘンドリクセンから、王国を混乱に陥れたその真実がついに語られる…!', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4201dbd-ea4a-4365-9033-293bc7bf374c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e2466db-eae7-4afc-a6a7-947791c77c44', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 7, '100014827', '記憶が目指す場所', 'ガランとの戦いで怪我を負ったディアンヌがようやく目を覚ました。しかし顔を覗き込むキングへ困惑の表情を向ける。戦いで頭を強打したディアンヌは記憶を失っていた…! 記憶と異なるキングの風貌、団長をメリオダスと呼び、エリザベスのことは覚えてすらいない。〈七つの大罪〉入団以前へ記憶が戻ってしまったディアンヌは仲間の前から姿を消す。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c036b7d0-f8c2-4483-9a9f-e180e38877ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45a49d80-374f-4690-b7c8-f3f2845fd520', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 8, '100015155', 'ドルイドの聖地', 'ゴウセルに記憶を操作され姿を消したディアンヌを探すため、メリオダスたちはディアンヌが向かうであろう巨人族の里･メガドーザへと移動を始める。ところがメガドーザへの道中には〈十戒〉が魔力回復を行うエジンバラ城跡があった。数百マイル離れた先で何者かが戦っているのを察したメリオダスは…。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf0c6c68-ff09-40ea-844a-ee759f952ce6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58376bee-0981-47eb-a095-6779729a15b1', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 9, '100015374', '愛する者との約束', '〈十戒〉と戦う力を得るため、メリオダスたちは森の賢者ドルイドの聖地･イスタールを訪れた。10年前にマーリンに奪われたメリオダスの強大で危険な力は、ドルイドに預けられていたのだ。力を取り戻すため、苦しく辛い試練に挑むメリオダスの前に現れるリズの姿。そしてエリザベスにも試練が待ち受けていた。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/404b64d6-3e3f-4e43-bd2c-a9fa64e1afb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f263c86-b7ae-4906-a95d-cb4d4a92f973', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 10, '100015858', '僕たちに欠けたもの', 'レイブンズに着いたバンとジェリコは瀕死のウェアフォックスに遭遇する。盗賊都市と呼ばれるその町はバンが子供の頃に住んでいた町。バンは傷だらけだった幼い頃と、そんなバンに手を差し出した男のことを思い出す…。一方メリオダスたちはドルイドの聖地･イスタールで厳しい修業を続けていた。修練窟へ入ったメリオダスとキングだが…。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8021f299-f8e9-4ee1-a0e6-0289ad0e4abd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be7ff972-49f4-4f95-96ca-5d0cda2091bb', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 11, '100016204', '父親と息子', '『女神の琥珀』に入れられていた力がついにメリオダスの元へと戻った。本来の力を取り戻し、メリオダスはひとり〈十戒〉の元へと乗り込む。殺気立つガランを制してメリオダスは余裕の表情を浮かべるのだった。挑発された〈十戒〉たちはブリタニア侵略のため散会して行動を開始する。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5b61727-e9ed-4841-b057-65248a36d075.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6ff1667-b1a7-4474-a6ab-87bcb83de4c7', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 12, '100016518', '愛の在り処', '父親代わりであったジバゴの死を看取ったバンの前に、妖精の森で眠るはずのエレインが現れた! 何者かに操られるエレインは恋人を愛しく思う気持ちを訴えながら、バンを傷つけてしまう。さらに〈十戒〉のふたりが姿を現し、バンの魂を狙う…!', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7bdfc3fd-6be0-4390-842e-297fd1d63e5f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1984800d-0483-443c-8c01-f0709e3e6419', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 13, '100017438', 'さらば愛しき盗賊', 'ブリタニア支配のため別行動を開始した〈十戒〉たち。だがそれこそが彼らの力を分散させる、メリオダスの計略だった。行動を共にするガランとメラスキュラ。蘇る死体の噂はメラスキュラの禁呪によるものだった!', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f808d141-1dcb-477c-a76f-37f0c79f2dc4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3221d03b-a314-4ef2-90c3-7eaa3639fe87', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 14, '100018184', '太陽の主', 'バン、ジェリコ、そして蘇ったエレインの三人は、〈十戒〉のガラン、メラスキュラと対決しなんとか窮地を脱する。戦いに疲弊したバン、力の弱るエレインを背負い歩むジェリコだが、依然としてガランたちの魔の手が迫ろうとしていた。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79868ccf-c986-45ed-be59-b3950db7e5f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26b9fda8-38be-44ce-9b14-c1356b45e8e8', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 15, '100018566', '戦慄の告白', 'ガランとメラスキュラに追撃されるジェリコたちが逃げ込んだのは、洞窟の奥の酒場〈麗しき暴食〉亭。そのマスターこそが七人目の大罪〈傲慢の罪〉エスカノール!〈十戒〉のふたりを圧倒的な力で蹴散らしてしまう。一方、〈蒼天の六連星〉は〈十戒〉フラウドリンに身体を乗っ取られたドレファスを捕獲する。ゼルドンの研究棟に捕われたドレファスだが…。', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f66841b-a3fa-4dea-9f71-a7d5c67188dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7966f05-ec2b-4819-a68a-38d0168bd798', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 16, '100018677', '死の罠の迷宮', '〈十戒〉グロキシニアの操る魔神によって、大陸中に『バイゼル大喧嘩祭り』のチラシがばらまかれた。瀕死の子供たちを救うため奇跡にすがるマトローナとディアンヌ、喧嘩祭りに興味を持つメリオダスたち、バンやエレインを荷車に乗せて酒樽を運ぶエスカノール一行。散り散りになった仲間たちを迎えるのは、バイゼル大喧嘩祭り第一関門『死の罠の迷宮』だった!', '2023/09/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7cc4bec-8fef-44a6-8f27-3077d9ed2b64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48a0e478-94fc-4a2f-aedb-da96d1b642cb', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 17, '100018985', '伝承の者共', '〈十戒〉巨大迷宮の中でディアンヌはエリザベス、ホークと再会する。またメリオダスはバンに再会、バンは〈豚の帽子〉亭へ戻る意志を見せる。ふたりは再生する壁をぶち抜くという荒技でついにゴールへたどり着くが、そこにいたのは禍々しいオーラを放つ〈十戒〉のドロールとグロキシニアだった。', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1992673-81f3-463a-922f-2c996d64d4ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f693be4f-2163-4743-b8b0-16bb50841395', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 18, '100019183', 'その光は誰が為に', 'バイゼル大喧嘩祭りタッグマッチが始まった! メリオダス&バンペア、エリザベス&エレインペアは対戦相手を撃破し、他のペアたちも戦いを繰り広げる中、キング&ディアンヌペアに立ちはだかるのは〈十戒〉のふたりが操るゴーレムとサーバント。強力な攻撃にキングは妖精王として真の力を見せるが…。', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bbe4f51d-3517-4614-abae-78f8100c5a40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6d4264a-67d4-4298-bfd4-5b27873f52cb', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 19, '100019462', 'メリオダスvs〈十戒〉', 'タッグマッチで敵対することになったゴウセル&ジェリコペアと、ホーク&エスカノールペア。ゴウセルの“悪夢語り〈ナイトメア･テラー〉”によって心を弄ばれたエスカノールは神器を解放する。だがその攻撃の矛先はゴウセルではなく、ドロールとグロキシニアだった! 深い傷を負ったふたりの前にメリオダスが降り立つ!', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79a8b691-d616-4fdd-988c-b8eb8f43c180.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1405258-a966-4e97-bf85-7edc0be91e29', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 20, '100019855', '希望を求めて', 'ドロールとグロキシニアを倒すため、罠と知りながら大喧嘩祭りに参加したメリオダス。しかし勝利を寸前にして、集結した〈十戒〉の攻撃を受けてしまう。渾身の力で振るった神器･ロストヴェインさえも「慈愛」の戒禁を持つエスタロッサに受け止められ、ついにメリオダスは倒れてしまう。エスタロッサから語られる三千年前の事実とは…!?', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfb96b23-18cc-411f-9c31-db9eb2ff2b75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94d06043-fa7b-4180-a0e6-368976c5538e', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 21, '100020261', 'たしかな ぬくもり', 'エスタロッサの操る七本の剣に七つの心臓すべてを刺されてメリオダスは死んでしまった。そして本格的な侵攻を開始した〈十戒〉率いる魔神族によってブリタニアは蹂躙されてしまう。各地で魔神族の侵攻を止めようと残った〈七つの大罪〉たちや聖騎士たちが戦う中、〈豚の帽子〉亭ではエリザベスとホークが心臓が止まったままのメリオダスを見守っていた。', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07acb8e5-f22b-419e-ae2f-1ef2dc06322f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20d1cd5a-4351-4c28-b7da-ab419cd7f950', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 22, '100020551', '〈罪〉の帰還', '〈豚の帽子〉亭へ現れた聖騎士ザラトラスによって、目を覚ますことのないメリオダスの記憶の中へ入ったエリザベス。そこには幼いエリザベスに必ず生きて戻ると約束を交わすメリオダスの姿があった。一方、〈十戒〉の襲撃を受ける王都リオネスでは、エスタロッサとその戒禁に囚われないエスカノールが激しい戦いを繰り広げていた!', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e09e196-c53f-43ba-9db5-1f9b4cecc023.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1799a220-5ddb-4cef-9b14-069b43a4b8c4', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 23, '100020922', '英雄、立つ!', 'エスカノールによってエスタロッサとゼルドリスの脅威は免れたものの、いまだ王都リオネスへの魔神族による襲撃は止まず、陥落はもはや時間の問題となっていた…。リオネスへ向かうエリザベスたちだが、そこに〈十戒〉のデリエリが現れる。襲われるエリザベスを救ったのは目を覚ましたメリオダスだった!', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6920fe14-178d-45d3-9a82-d7beb7a244c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ddc3be0-910a-4a50-9592-19b60d58be8e', '90c477fa-b5dd-427b-b6d0-a3d9506b16ee', 24, '100021200', '君がいるだけで', '【シーズン1 最終話】ドレファスから分離したフラウドリンと復活したメリオダスとの一騎打ちは圧倒的な闘級の差を見せたが、メリオダスらしからぬ戦い方に仲間たちは困惑する。メリオダスの復活と強さは魔神の王にもたらされた呪いによるものだった…。そしてついに〈十戒〉と人間との戦いは収束を迎える!', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/078078af-11e7-4404-b349-68bb64916d33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6ffa4218-7a07-4b39-aa7d-dc49319e231b', '七つの大罪 神々の逆鱗', '', 'hulu', 'the-seven-deadly-sins-imperial-wrath-of-the-gods', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa3b20e4-d0ee-4f9b-b20e-443c15911fbf.jpg?w=331&h=447&p=t', 'hulu', 2019, 3, 1, 'FINISHED', NULL, 108928, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f7d03a90-746a-4bd5-b598-4ec33fc055fe', '6ffa4218-7a07-4b39-aa7d-dc49319e231b', 'hulu-the-seven-deadly-sins-imperial-wrath-of-the-gods-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c775d3c9-e6a3-4375-a731-5b9bb805e2ef.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de291807-a6ae-4ada-a412-b0e97a17b37a', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 1, '100043591', '闇を払う光', '煉獄より復活を果たしたメリオダス。〈七つの大罪〉の活躍により〈十戒〉のグレイロードとフラウドリンが討たれ、リオネス王国は守られたが、ブリタニアは依然として〈十戒〉の脅威にさらされていた。人々の心は荒んでいき、魔神たちの支配に抗うこともできない。そんな中、決死の覚悟で武器を手に立ち上がる村人たちの前に現れた〈七つの大罪〉。ブリタニア解放を賭けた反撃が、今まさに始まろうとしていた。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c775d3c9-e6a3-4375-a731-5b9bb805e2ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bf008f2-a261-42ce-ac6d-d27421dc6cce', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 2, '100043943', '聖戦の記憶', '〈十戒〉の脅威から逃れるため、妖精王の森へと避難していたキングとディアンヌ。花びらが舞い散る大樹の広場で妖精たちとの束の間の休息をとる中、2人はいつの間にか意識を失ってしまう…。そして、目を覚ました2人の目の前に現れたのは〈十戒〉「安息」のグロキシニアと「忍耐」のドロール! 死を覚悟して戦いを挑む2人であったが、桁違いの力の差に手も足も出ない。傷付き、倒れ、まさに最期の瞬間を覚悟したその時、2人が〈十戒〉から耳にしたのは意外な言葉だった。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a81c35d-5fa8-4bf7-bfc6-03cf11e5ef7f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80aa948c-1df7-44bc-a420-bb6e1fbb999f', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 3, '100044046', '光あれ', '〈十戒〉から課せられた試練により、三千年前のブリタニアでグロキシニアとドロールの姿となって目覚めたキングとディアンヌ。そこで出会ったのはメリオダスと―女神族の姿をしたエリザベスだった! メリオダスは、人間の集落を襲っている魔神族と戦っていた。キングとディアンヌも協力して古の〈十戒〉カルマディオスと戦い、見事勝利を収める。しかし試練はまだ終わらない。そこでは女神族、巨人族、妖精族の連合〈光の聖痕 (スティグマ)〉と魔神族が血で血を洗う戦いを繰り広げていた…!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f746a349-b708-47d4-9be6-d2f10c797081.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e54b0d5-cbd4-42ed-a32c-75265df5cd1d', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 4, '100044311', '〈十戒〉vs.〈四大天使〉', '魔神族を根絶やしにせんとする〈四大天使〉のリュドシエルと、全ての種族の共存を望むエリザベス。2人の思いが交錯する中、ついに〈十戒〉率いる魔神族と〈光の聖痕 (スティグマ)〉の全面戦争が始まろうとしていた。〈四大天使〉のサリエルとタルミエルを相手に魔神族の軍隊は壊滅的な状況に追い込まれ、〈十戒〉のデリエリやモンスピートたちは苦戦を強いられる。しかし追いつめられたデリエリとモンスピートは、限られた者にしか許されない禁忌の術を解放する―!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/716b5354-782d-4717-b0c6-ba32bb1dd4ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26929439-ba2a-4c6e-b241-220080d3a5f0', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 5, '100044742', '感情メイルシュトローム', '〈光の聖痕 (スティグマ)〉と魔神族の戦いが熾烈を極める中、禁忌の術で最悪の化け物「インデュラ」となったデリエリとモンスピート。その2人の前に立ちはだかったのは、なんとエリザベスだった! エリザベスはリュドシエルの反対を振り切って2人を助けると宣言し、インデュラの闇の力を打ち消そうと必死で立ち向かう。そんなエリザベスの姿を目の当たりにしたサリエルとタルミエルは、リュドシエルの命令ではなく自らの意志で動くことを決意する―。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb66b3aa-9fb4-474a-9ea3-c827f8b18e29.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b94829b-0806-4790-9aca-11c2c18528e9', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 6, '100045348', 'それをボクらは愛と呼ぶ', '破壊獣「インデュラ」と化したデリエリとモンスピートの救出に成功したエリザベス。一方、ゴウセルの策略によって魔界の牢獄の門が完成し、そこからもう1人のゴウセルが現れる。彼はディアンヌに自身の命を懸けた計画を話し、とある“お願い”をする。そんな中キングは、人間が〈光の聖痕 (スティグマ)〉相手に反乱を起こしていると知り、ゲラードの元へと急ぐ。しかし彼が辿り着いた先にいたのは―!?', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daacbce0-4a0e-4a30-a873-87b26fc6427a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a145946-72a9-4b31-bb7c-015a8dcb4e24', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 7, '100045667', 'いざ 大罪集結へ!!', '血まみれのゲラードを目撃するも、怒りの攻撃を寸でのところでこらえたキングは、無事三千年前のブリタニアから帰還する。一方、ディアンヌと2人のゴウセルは、聖戦の真っ只中でメリオダスの弟ゼルドリスに出会っていた。ゼルドリスはゴウセルに牢獄へ戻れと命じたが、ゴウセルがそれを拒否し戦いに発展。ディアンヌは2人のゴウセルを逃がし、1人ゼルドリスと対峙する。2人の戦いは激しさを増し―!? ディアンヌは、無事元の世界へと戻ることができるのか―!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a789c0ba-51c9-44c6-afb7-3e5928ee50b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('372084af-fac5-43f1-a052-64edef965fbf', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 8, '100046314', '人形は愛を乞う', 'キングに続きようやく現代へと戻ってきたディアンヌ。試練も終わり、〈七つの大罪〉は再び集結したかに思えたが、今度はバルトラが差し出した「魔法の心臓」を見たゴウセルが逃走。メリオダスたちはゴウセルを追ってリオネス王国の街へと向かうこととなった。その最中、魔法の心臓によって感情を持っていたゴウセルが感情をなくした経緯が明かされる! 何かを思い出しかけた逃走中のゴウセルは、その発生した“ノイズ”を消去しようとするが―。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af439b76-0ede-4951-8047-0bf2ada4fd22.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f1cedec-22c2-4762-a2ea-c6a350b787d7', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 9, '100046984', '呪われし恋人たち', 'ディアンヌとマーリンの説得によってゴウセルは感情を取り戻し、〈七つの大罪〉は再集結。〈豚の帽子〉亭ではエリザベス、ディアンヌ、エレインが、リオネスの酒場ではキング、ゴウセル、エスカノールが語らっていた。その夜、エリザベスはディアンヌから聞いた「昔の団長と、キミに瓜二つのエリザベスに出会った」という話が頭から離れずにいた。そしてそれについてはぐらかすメリオダスの意思とは裏腹に、エリザベスはどんどんと核心に迫っていく。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6338cb1c-35da-4acb-935a-5c26eac9882b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1df4f523-88b1-4120-b20f-1bd400c8ef6b', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 10, '100047337', 'それが僕らの生きる道', 'ゼルドリスの力に触れたことで自身とメリオダスの真実を知り、記憶が戻り始めたエリザベスは意識を失ってしまう。メリオダスは「エリザベスの記憶がすべて戻れば、エリザベスは三日で死ぬ」と〈七つの大罪〉たちに真実を告げた。それは、三千年前の聖戦の最中、魔神族メリオダスと女神族エリザベスが魔神王と最高神によって受けた罰。永遠の生と永劫の輪廻によって繰り返されてきた2人の物語は、あまりにも辛いものだった…。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c0b5349-7c3c-445e-b2fd-2c8c004aa13a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb17f8eb-2ab7-4c71-9407-e462b3ec4f6c', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 11, '100047632', '怨念たちは眠らない', '魔神王と最高神にかけられた呪いの真実を知らされた一行。しかし彼らはメリオダスの意思で今までどおり目的を果たすべく、キャメロットを守る次元のひずみを解除するためコランドへと向かった。しかしコランドにつくやいなや、メリオダスは突如現れたメラスキュラによって「暗澹の繭 (あんたんのまゆ)」に包まれ連れ去られてしまう。残された一行は、囚われたメリオダスの力で強化された死霊たちに苦戦を強いられる。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a11db4d-d91a-4891-ab31-e2eee6d18a77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5f6af60-3f24-45f6-ae1d-6d1adddd6705', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 12, '100047933', '愛は乙女の力', 'メラスキュラによって暗澹の繭 (あんたんのまゆ) に囚われてしまったメリオダスと、怨霊に憑かれ操られているディアンヌ。自らを犠牲にしたヘルブラム、そしてエレイン、覚醒したエリザベスの力によってディアンヌはようやく怨霊から解放されたが、今度はメラスキュラが大蛇へと変貌して一行を襲う。さらには、脱出不可能と思われた暗澹の繭を破り、凄まじい邪悪な波動とともに漆黒の翼を広げる「殲滅状態」のメリオダスが我を失い姿を現して―!?', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3af9ec08-e1f0-4c8a-934f-90480b59d2fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96ca7f75-26ee-4635-a5e8-5faacb82169b', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 13, '100048523', '最強 vs. 最凶', '暗澹の繭から脱出するため魔神の力を解放したメリオダスは、かつての〈十戒〉統率者時代へと戻ってしまった。エスカノールが対処しようとするも、メリオダスの剣に体を貫かれてしまう。苦戦を強いられるエスカノールだが、正午になり力が頂点に達したことでついにメリオダスを無力化することに成功する。マーリンはメリオダスの暴走を止めるため、エリザベスとメリオダスをパーフェクトキューブに閉じ込める。苦しい状況に置かれる一行だが、民を救うためキャメロットへと向かうのであった。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7ab5f90-8d16-4d2e-a6f1-a89248fa5f6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ca0286e-bad1-45d6-b643-20d8822ce5e8', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 14, '100049096', '新たなる脅威', '〈七つの大罪〉一行がキャメロットへ向かう中、ゼルドリスは魔神王より「メリオダスを奪還せよ」「〈七つの大罪〉を皆殺しにせよ」との命を受けていた。ゼルドリスが〈十戒〉に招集をかけるが、駆けつける者は誰一人いない。コンタクトがあったグロキシニアとドロールは、「もう命令には従わない」という。だがゼルドリスのもとに、新たな魔神族･キューザックとチャンドラーが現れる。2人はそれぞれ、メリオダスとゼルドリスの師匠だった男で―。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/323bfe99-6beb-4358-96cf-ae68993720bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d9d40be-07fd-4854-843a-4a51b99d1f95', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 15, '100049349', '団長へ', '魔神王の命でメリオダス奪還へと向けて動き出したゼルドリス。そこに現れたのは、ゼルドリスの師･キューザックと、メリオダスの師･チャンドラーだった。チャンドラーは〈豚の帽子〉亭へと向かい、〈七つの大罪〉へと襲い掛かる。キングとゴウセルは渾身の合技を繰り出すが、チャンドラーは軽傷を負っただけだった。その後も必死で応戦し、一度は勝利したと思われたが…チャンドラーは悪魔のような姿へと変貌を遂げて再び立ち上がり―!?', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c6d980b-be3d-467f-a98e-75b412b95fe0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1fdd44af-00df-4462-8af3-00ea2d471f95', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 16, '100049641', '〈七つの大罪〉終結', '一度は倒したと思われたチャンドラーは、悪魔のような姿に変貌し復活。〈七つの大罪〉は、再び絶体絶命の窮地へと追い込まれた。しかしそこに、グロキシニアとドロールが駆けつける。2人は自らを犠牲にする覚悟でチャンドラーと対峙し、消耗しきった〈七つの大罪〉一行を逃がす。だが一同が受けたダメージは、心身ともに甚大なものだった。さらに意識を失っているメリオダスが発する瘴気は刻一刻と強くなっていき…。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2a5aa8d-ce90-4a05-b1c8-4fa98cf1a026.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('777e87cc-f0e3-4e78-a4fd-b5b4f193f1ec', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 17, '100050433', 'ボクたちの選択', '〈十戒〉統率者として目覚めたメリオダスは〈七つの大罪〉解散を告げ、エリザベスを連れてゼルドリスの元へと去ってしまった。それは、彼自身が魔神王となりエリザベスを救うためだという。残された〈七つの大罪〉一行は、去り際にメリオダスが放った一言でホークが煉獄と繋がっているという衝撃の事実を知る。魔神王は、ホークの目を通してずっとメリオダス達を監視していたのだ。それを知ったバンは、メリオダスの感情を取り戻すため、1人煉獄へと向かった。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1552bf7c-d823-44c7-96b6-7c5679aced06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4198c507-01bf-4554-b669-c8673fdea123', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 18, '100050861', '聖者の行進', '魔神王になるためゼルドリスとエスタロッサに戒禁の回収を命じるメリオダス。一方エリザベスは、メリオダスが魔神王になるのを阻止するべく城から脱出する。メリオダスの命で〈七つの大罪〉の元へと向かったゼルドリスは、マーリンの姿を見て、彼女こそ魔神王と最高神の祝福を受けし娘だと知る。『無限』の魔力を持つ奇跡の天才児として生まれたマーリンは、かつてその力を手中に収めたい魔神王と最高神からあらゆる知識と加護を受けていたのだった…。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2628bc4e-0dac-4c6b-b0b3-10e15c48edee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cabbbc8-3d90-49ca-a50a-7cf84c239379', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 19, '100051074', '聖戦協定', 'メリオダスが魔神王になるのを阻止するため、エリザベスはキャメロット城から脱出。逃げ出したエリザベスを探すメリオダスを見て、チャンドラーは「エリザベスを始末できる絶好のチャンス」と、自身の分身を作り彼女を見つけて殺せと命じる。エリザベスはチャンドラーの分身に見つかって襲われるも、ディアンヌの助けでどうにか〈七つの大罪〉たちとの合流を果たす。仲間に事情を話したエリザベスは、自らの命と引き換えようともメリオダスを助けることを宣言する。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d772fec5-14cf-48df-ba15-fa681b91121b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09175bed-30f9-43fe-8cd3-55413538ad56', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 20, '100051290', '希望の子', 'リオネスに帰還したエリザベスと〈七つの大罪〉は、メリオダスの戒禁集めを阻止するため、リュドシエル率いる〈光の聖痕 (スティグマ) 〉と盟約の光を交わす。聖騎士たちは聖戦に向けて湧きあがり、アーサーは聖剣エクスカリバーを手に入れるため1人キャメロット城へと向かっていた。そんな中、壊れたゴウセルを直すマーリンに、ゴウセルはとある“お願い”をする。その願いとはいったい? そしてアーサーは、エクスカリバーを無事手にすることができるのか?', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7f29903-2d1a-44d6-bbb1-cc3e56ce8800.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c238389-6d1e-42cd-ba4a-21ad73d2845d', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 21, '100051762', '聖戦の幕開け', 'キャメロット城に潜入したアーサーの前に立ちはだかったのは、ゼルドリスたちと…なんとメリオダス! 聖剣を手にしたアーサーは彼らに戦いを挑む。初めは圧倒しているかのように見えたアーサーだが…聖剣の強大な力に耐えきれず、体がズタズタになってしまう―。もうだめかと思われたその時、突如現れたマーリンによってアーサーは〈豚の帽子〉亭へと離脱することに成功する。しかしこの時すでに、アーサーはキューザックの術中にあって―!?', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95d6569d-832c-475d-9a89-d31c3deb09d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f15b75f7-7452-4e66-8059-a5610214c755', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 22, '100052275', '戦禍のブリタニア', '〈豚の帽子〉亭に逃げ延びたアーサー。しかしキューザックの術により、アーサーはマーリンの目の前で自らを貫き絶命した。悲しみにくれるマーリン達だが、それを乗り越え魔神族との戦いを決意する。三千年の時を経て、ついに聖戦の火ぶたが切って落とされた。リュドシエルの「祝福の息吹 (ブレス･オブ･ブレス)」によって強化された聖騎士たちに〈七つの大罪〉も加勢し、戦いは激しさを増していく。しかしリュドシエルのその力は「ペテンの光」と呼ばれる恐ろしいものだった。聖騎士たちを本当に守っていたのは―。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af5dc8b4-49b7-41c3-890b-2ea69e8094e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1902cc11-6261-4c61-bfa4-15a3479ce33f', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 23, '100052811', '闇に歪む者', 'ブリタニア全土で繰り広げられる、〈光の聖痕 (スティグマ) 〉と魔神族による聖戦。そんな中、戒禁を奪いにきたエスタロッサからデリエリを守るため、モンスピートは自らの命を犠牲にデリエリを逃がす。残されたデリエリはエリザベスの魔力を辿って彼女の元へ向かうが、デリエリを追ってきたエスタロッサは再び彼女の戒禁を狙う。戒禁集めを阻止するため、そして仲間を守るため、エリザベスはエスタロッサに立ち向かう―!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f338eaf6-0eda-40c1-8286-14dcee082627.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('154d9053-3a16-4f31-8ab7-3802f229670b', 'f7d03a90-746a-4bd5-b598-4ec33fc055fe', 24, '100053203', '暴走する愛', '【シーズン1 最終話】エスタロッサはモンスピートの戒禁を取り込み、エリザベスへの思いを語り始める。エリザベスを好きであること。なのにエリザベスの視線の先にはメリオダスしかいなかったこと…。しかし取り込んだ3つの戒禁の拒絶反応で理性を失い、ドロドロとした闇へと変貌。応戦するも歯が立たず、エリザベスはエスタロッサに連れ去られてしまった。一行はエリザベスを、そして暗黒領域の主となってしまったメリオダスを奪還すべく一致団結し、エスタロッサとの最終決戦に挑む―!', '2023/09/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b033d4c6-9d49-4cb1-8235-8b3516a19922.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('28b0255b-cc66-4bae-bdca-117ca1f21d35', '七つの大罪 聖戦の予兆', '', 'hulu', 'the-seven-deadly-sins-signs-of-holy-war', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50026817_series_art__338x600_the_seven_deadly_sins_signs_of_holy_war_4f1032b731a06c9441ec4de7187d78d4.jpg?w=331&h=447&p=t', 'hulu', 2016, 2, 1, 'FINISHED', NULL, 21385, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('eac596cf-ea59-4b1d-b056-e7a24cd8eb50', '28b0255b-cc66-4bae-bdca-117ca1f21d35', 'hulu-the-seven-deadly-sins-signs-of-holy-war-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/69378ddf-c7a7-4e4e-a3cc-47d8194b6093.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('768ebb3f-00df-4ff8-8521-1f1854bb9ee1', 'eac596cf-ea59-4b1d-b056-e7a24cd8eb50', 1, '60774582', '黒き夢のはじまり', '王都奪還の戦いから数日後、復興作業が進むリオネス王都。〈豚の帽子〉亭にも平穏な日常が戻ってきたが、ひょんなことから、ホークが飛び出して行ってしまう。メリオダスたちはギルサンダー達も巻き込んで、ホークを捜索することに。', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/69378ddf-c7a7-4e4e-a3cc-47d8194b6093.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2741881-7c3f-478e-a2a2-50335066888f', 'eac596cf-ea59-4b1d-b056-e7a24cd8eb50', 2, '60774580', '二人の喧嘩祭り', 'ヘンドリクセンとの戦いの最中に交わした約束を果たすべく、メリオダスとバンは対峙する。しかしそこには、なぜかたくさんのギャラリーが待ち構えていた。エリザベスやホーク、七つの大罪や聖騎士たちが見守るなか、遂に二人だけの喧嘩祭りが始まる!!', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/58bbf28d-5cb6-43d6-9e7a-9528102f67e1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d73b829-f4ee-469f-9e1e-f8b30e40e5eb', 'eac596cf-ea59-4b1d-b056-e7a24cd8eb50', 3, '60775749', '初恋を追いかけて', '王国生誕祭をディアンヌと二人で過ごしたキングは幸せな気持ちで満たされていた。しかし数日後、突然ディアンヌが行き先も告げずにひとり出かけてしまう。先の戦いの最中に人間たちからひどい仕打ちを受けていたディアンヌ。心配になったキングは、急いで後を追いかける。', '2023/09/21 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/efa2a280-75e3-4387-bb59-0dab4f7aae57.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1679f14d-c6c3-4a43-98e9-c5ab40a44308', 'eac596cf-ea59-4b1d-b056-e7a24cd8eb50', 4, '60779682', '愛のかたち', '【シーズン1 最終話】ここのところ、少しお客さんが減ってきた〈豚の帽子〉亭。そこでメリオダスは、マーリンをウェイトレスに加え『最強看板シスターズ』を結成しようと画策する。しかし、交換条件としてマーリンはある依頼を持ちかけてくる。その依頼とはいったい…? そして、街に出たメリオダスが見たものとは!?', '2023/09/21 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d4a24da1-879e-4be9-998a-c8c0ff04fcbc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3d3dcef3-2d3a-49b2-9a5e-0e591ff7adbe', '七つの大罪 憤怒の審判', '', 'hulu', 'the-seven-deadly-sins-dragons-judgement', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c171ccb9-28fb-4692-8371-86f8bd1c582d.jpg?w=331&h=447&p=t', 'hulu', 2021, 0, 1, 'FINISHED', NULL, 116752, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5c372a25-4b91-43f8-ba0e-e8e9f01e823a', '3d3dcef3-2d3a-49b2-9a5e-0e591ff7adbe', 'hulu-the-seven-deadly-sins-dragons-judgement-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/507c3bb3-55e5-4eae-9eba-7e0f31314a00.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('adda29f8-5c6f-4f58-ba21-7705b98e9549', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 1, '100073827', '煉獄より', '煉獄の立ち込める瘴気のなかで、何百年もの時を経ながらもバンはメリオダスを探し続けていた。一方現実世界では、3つの戒禁を取り込み暴走したエスタロッサがエリザベスを連れ去り、キング、デリエリ、サリエル、タルミエル、ゴウセル、ホークが後を追う。たどり着いたのは天空演舞場。そこでは巨大化したエスタロッサが、エリザベスへの愛を叫んでいた。また暗黒領域では、リュドシエル、マーリンら一行が、ゼルドリス、チャンドラー、キューザックと対峙していた。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/507c3bb3-55e5-4eae-9eba-7e0f31314a00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0aa44e2-16b5-41a8-8184-b001863a714d', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 2, '100074061', '未知との遭遇', '煉獄へと向かったバンは、ついにメリオダスと再会を果たす。親友との邂逅、感涙にむせぶ二人が次に考えるべきは、この煉獄からの脱出方法だった。その鍵は、メリオダスを煉獄へと閉じ込めた、父たる魔神王が握っていると彼らは予想する。身辺を整えながら、手探りで状況を変えようとする二人の前に、見慣れた一匹の生き物が姿を現す。それはホークと瓜二つの「ワイルド」だった。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f3c1e6c-2349-4acf-9031-555169c26722.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('220d6b8f-f2a8-4b66-b069-9dc6362644bf', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 3, '100074667', '一途なる想い', 'ワイルドという味方を得て、魔神王のもとを目指して進む、メリオダスとバン。その最中、メリオダスは弟であるゼルドリスとの過去を語り始める。ゼルドリスは吸血鬼族のゲルダを愛していた。しかし、吸血鬼族の王が魔神族に謀反を起こしたことから、魔神王はゼルドリスに「吸血鬼一族の処刑」を命じる。ゼルドリスの中で、愛する者を守りたい想いと、決して逆賊になれないという想いが交錯する。処刑の直前、ゼルドリスはその剣を吸血鬼一族に向けるが……。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/29006f01-b2d9-4706-be8d-d650961a6b1b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62f8afc5-566b-465a-a8ea-f8475981b0ea', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 4, '100075373', '聖戦の犠牲者', 'メリオダスはエスタロッサについて語ろうとした時、その記憶がなぜか抜け落ちていることに愕然とする。その違和感を察したかのように、魔神王が姿を現す。一方その頃、現実世界ではメリオダスの魔神王化を阻止するべく、マーリンを始めとする強襲部隊と、ゼルドリスたちとの激しい戦闘が続いていた。ゼルドリス側には「最上位魔神」たるキューザック、チャンドラーが立ちはだかり、圧倒的な力を見せつける。しかし、マーリンはその戦力差にも臆することなく、「弱点がないのであれば、弱点を作ればいい」と言ってのける。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4316997d-3715-48d0-bd82-05238ac8335b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7b92f7b-e250-4c43-927e-048b47d827bb', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 5, '100075884', '悲しき一撃', 'ゴウセルから明かされた真実――それは3000年前、聖戦を終結させるために魔術士ゴウセルが、〈四大天使〉マエルの記憶とその男を知る全ての者の認識を改変する禁呪を使用したことだった。〈十戒〉エスタロッサは存在せず、まさにその男こそが、〈四大天使〉マエルだったのだ。なぜ、魔術士ゴウセルは禁呪を用いたのか。その口から語られる考えは、到底、マエルにとって理解できるものではなく、復讐心はゴウセルに鋭く向けられた。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7b3eb52-7d02-4a94-876e-8f31314284b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ecec23f-7568-4a8e-9419-46c31d8dadc3', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 6, '100076366', '絶望に立ち向かえ', 'マエルの放った一撃により、デリエリが討たれた。4つ目の戒禁を奪われ、それら全てをマエルは取り込もうとする。ゴウセルは自らを犠牲にして解決を図るのではなく、仲間を護るために、マエルと戦う決意を固める。ディアンヌも天空演舞場に集結するが、最終形態に移行しつつあるマエルの闘級は20万以上と、圧倒的な数値を叩き出すまでになっていた。ディアンヌ、キング、ゴウセルは、一矢を報いるべく、三位一体の必殺技を仕掛ける。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e79a42f-3dc7-4703-b5d3-69a0e965c24a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88f5edec-09f4-4182-9e05-185f6ad0eef3', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 7, '100076858', '希望と葛藤と絶望', '4つの戒禁と融合し、異形の姿となったマエル。マエルの強大な力を前に一時追い詰められたキングだったが、「妖精王･ハーレクイン」として覚醒しその真の力をふるう。霊槍を同時に複数発動させられるようになったキングは、ついにマエルを追い詰める。しかし、ゴウセルはその最中でも自らの行いを悔い、マエルを救うチャンスを探る。そして、ゴウセルはマエルの精神世界に“侵入”し、対峙することを選ぶのだった。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca8a07bb-29bb-4d12-9fd4-e913c5921596.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b2d9d6a-82ab-4f86-8e10-11173f566b8c', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 8, '100077532', '希望への扉', '煉獄で、ついに魔神王と対峙するメリオダス、バン、ワイルド。この煉獄から脱出するには、魔神王に打ち勝ち、「現世への出入口」を通らねばならない。「攻撃すると逆に魔力を奪われる」という強大な力を持つ魔神王に、メリオダスたちは苦戦を強いられる。戦い始めて60年の月日が流れても、なお勝利の糸口はつかめない。しかし、戦いのなかでバンは魔力を他者へ「与える」術を身につける。その変化をきっかけに、メリオダスは魔神王を打倒する秘策を思いつく。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/664b776b-7528-48c7-8087-231a031555f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73f6401d-c872-4c04-bd19-3167c9b5f7b5', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 9, '100077985', '集結するものたち', '激戦続くキャメロット城では、チャンドラーとキューザックが融合し、〈原初の魔神〉へと変貌を遂げていた。マーリンは「勝機は完全に失われた」と絶望し、エスカノールであっても防戦一方となっていた。そこに、マエルを仲間に加えたキングたちが参戦する。形勢逆転の好機……と思いきや、キングの前にゼルドリスが立ちはだかる。「無駄な抵抗はやめておけ…お前たちに勝機はない!」', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/205c2cd0-fcd8-44b4-9b23-0a9bdf06c310.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b9e2933-ed96-4dbf-b8ea-f5a67824fa8d', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 10, '100078426', '太陽の救済', '全ての戒禁がメリオダスに取り込まれた。魔神王誕生を阻止するため、禁呪発動を試みるマーリン。窮地に現れた〈四大天使〉長･リュドシエルは、〈原初の魔神〉を前にも臆することなく技を発動する。一方、満身創痍のエスカノールのもとに集結したマエルたち。そこで、エスカノールの魔力「太陽」(サンシャイン) は、もともとはマエルの恩寵だったことが明らかになる。エスカノールはマエルに恩寵を返し、共に戦ってくれるよう懇願する。果たして、戦局は変えられるのか。マーリンの禁呪完成まで、あと10分――!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8a84bd8-d934-4129-80a6-390360e76664.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('890d047c-9038-4592-80de-a97e9059cf59', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 11, '100079002', '神と対峙する人', 'マーリンの禁呪発動により、メリオダスの魔神王化は阻止された。聖戦にも終止符が打たれたかのように思われたが……そこにはいつもと姿の違うメリオダスが佇んでいた。違和感を察するエリザベスからの追求に、その正体が露わになる。中身に宿るのは、メリオダスの父たる魔神王であった。魔神王はエリザベスに「名案」を告げる。「エリザベスよ……お前にかけられし“永劫の輪廻”の呪いを解いてやろう!」――その言葉の真意とは? 迫りくる魔神王の手から、〈七つの大罪〉はエリザベスを護れるのか?', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ba5d6a0-7cfc-4d0e-8522-12654c73b417.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cff7ac66-96da-44a1-93ca-fd3a32e54eda', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 12, '100079484', 'みんながキミの力になる', 'メリオダスの肉体を手に入れた魔神王は、圧倒的な戦力差で〈七つの大罪〉を苦しめる。そこへ、煉獄から戻ったバンが駆けつける。さらに、ゴウセルによって、エリザベスたちはメリオダスの精神世界に介入を果たす。こうして〈七つの大罪〉は、現実世界と精神世界で並行して魔神王と戦うことになった。仲間からの応援を背に、徐々に魔神王を押し返していくメリオダスたち。しかし、魔神王も簡単にやられはしない。現実世界で強大な力を持つ「嘆息の賢人」を呼び出し、形勢を一気に逆転させる。目前に迫る危機、そんな中、剣を抜いたのは……ゼルドリスだった。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/333932dc-b31c-4561-83d9-7b23ee4b59cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2a2a7e1-31f7-405d-97f2-ea9a66f17062', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 13, '100079997', '永き旅の終着', '〈七つの大罪〉によって魔神王は討ち取られた。王を失った魔神族はリオネス王国からも撤退を始める。つかの間の平和が訪れるかに思えたが、肝心の問題は残っていた。エリザベスの呪いの刻限はあと一日しか残っていないが、それを解く手段であった戒禁も、魔神王と共に滅してしまったのだ。エリザベスは自らの転生を受け止めるが、メリオダスは「呪いを解く方法はある」とあっけらかんと言い放つ。本来の魔力を取り戻したメリオダスは、マーリンによって可視化された“永遠の生”と“永劫の輪廻”を消し去るべく、魔力を放って打ち破る。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23c0da19-1eea-4dae-8e72-04924d2a68a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e9e45d3-17d4-4278-87b7-ed3d8434084e', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 14, '100080544', 'さよなら〈七つの大罪〉', '新たな魔神王となり、強大になりすぎたメリオダスを、世界は排除しようとしていた。迫りくる期日を前に、メリオダスはその事実を誰にも告げはしなかった。ただ、それに気づいたバンをはじめ、〈七つの大罪〉はそれぞれが気づかないフリをしている。口に出せば、それが現実になってしまいそうだからだ。平穏のなか、〈豚の帽子〉亭でにぎやかに働く〈七つの大罪〉だったが、大切な“団長”をこのままにはしておけないと、勇気を出して問いただす。そして、エリザベスもまた、誰にも打ち明けないままに、ある決心を固めていたのだった――。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80b6901a-0f6f-4048-8dcd-f6a391dd9e80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f7f04a5-3c04-45b4-97f4-cdb65af98b48', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 15, '100080724', '宿命の兄弟', '魔界の門に踏み入ろうとするメリオダスとエリザベス。しかし、突如落下した巨石によって、エリザベスは死の危険に脅かされる。間一髪、マーリンによって救われるも、消失したはずのエリザベスの“永劫の輪廻”が復活していることが判明。それはまた、もう一つの事実を〈七つの大罪〉に突きつける。魔神王は、まだ生きている――。魔神王を蘇らせるには、何者かを依り代にしなければならない。それだけの魔力を受け止められる存在に、メリオダスは心当たりがあった。キャメロット跡地の荒野で、いかにして魔神王は復活を果たしたのか?', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/547ab92e-2086-42af-b071-2d6cd3d26840.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f5c62b2-3793-45ea-8e36-55c689492d71', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 16, '100081124', '最終戦争', 'ゼルドリスを依り代に復活した魔神王、そして魔神王が召喚した魔獣インデュラ――〈七つの大罪〉と魔神王の戦いの火蓋は切って落とされた。メリオダスとエリザベスは、魔神王と化したゼルドリスを救うべく戦う。エリザベスは女神族の力を解き放ち、本来の強さを見せつける。また、激化していくインデュラとの戦いでは、〈七つの大罪〉が得意技を組み合わせて抵抗を続ける。一方、インデュラの幼体が現れたリオネス城では、エスカノールたちが絶体絶命の危機に陥る。そこに救いの手を差し伸べたのは……〈四大天使〉マエル! エスカノールは仲間のために、再び「太陽」の魔力を取り戻す。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9322664c-bd3f-48c8-b9d7-bb8a9c9771ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9927defb-6515-4719-816c-e5642f1fbd90', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 17, '100082155', 'キミの名を呼ぶ声', '魔神王として更に力を増すゼルドリス。窮地に立たされた〈七つの大罪〉のもとに現れたのは、決死の状態で死力を尽くすエスカノールだった。その善戦の隙を突き、メリオダスとゴウセルはゼルドリスの精神世界へと侵入する。精神世界で魔神王とゼルドリスを分かつためであった。ゼルドリスは、最愛の恋人･ゲルダと共に居たが……。一方、現実世界での激闘も続くが、ディアンヌが勇気を振り絞って放った奥義が、戦況を一変させていく――!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80db760d-9d39-4d5b-883b-34fe41450349.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67191baf-94c9-4a58-86d8-27499284a462', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 18, '100082614', '王は孤独に歌う', 'ディアンヌの技「大地創造 (マザー･クリエイション)」によって、ついに魔神王の魔力の供給源であった「魔法の湖」を消失させることに成功した〈七つの大罪〉。時を同じくして、時刻は正午を向かえる。エスカノールにとって最強の1分間がもたらされた……! 魔神王と互角以上に渡り合うエスカノールだったが、タイムリミットは直前にまで迫っていた。しかし刻限を超え、〈七つの大罪〉は未だ見たことのないエスカノールに出逢う。それは1分間を超えてなお、最強状態を保ち続けるエスカノールの姿だった。エスカノールは静かにつぶやく。「……友よ。これでようやく……誓いを果たせる――」', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a59a825-d518-4439-9974-00614f64b273.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42770653-b3c4-4fac-a0e5-1e17cb0275b1', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 19, '100083241', 'あがき', '正午を超えてなお燃え盛る、“天上天下唯我独尊 極” (ザ･ワン アルティメット) ――自分の全生命力を魔力に変換して戦うエスカノールは、魔神王に肉迫する。だが、死力を尽くすエスカノールの眼前に、メリオダスは立ちはだかった。これ以上は命を落としかねないと悟ったからこその行動だった。しかし、エスカノールは拒否し、仲間のために命を懸けることを厭わない。魔神王がさらに呼び出す闇の獣を前に、メリオダスは全員で戦う決断を下す! 一方、ゼルドリスの精神世界では、本物のゲルダも加わり、魔神王との戦いが続く。ついにゼルドリスは刀を抜き、魔神王と対峙する!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f28ec50-5f8b-4d97-a7cf-6cde80fe45d4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('caaa7577-5726-4d04-8d4f-7bc1231db600', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 20, '100083822', '倶に天を戴かず', '〈七つの大罪〉とゼルドリスは、現実世界／精神世界の魔神王を追い詰める。ところが、魔神王はゼルドリスの体から分離し、ブリタニアの大地を新たな依り代とし、おぞましき進化を遂げてしまう。だが、彼らは自らの勝利を確信していた。〈七つの大罪〉は仲間たちとの絆を信じ、一斉に必殺技で攻撃を仕掛ける。メリオダスの「全反撃 (フルカウンター)」がもたらす一撃の行方は――!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd3d7cae-86ea-4922-83ed-d7e8206f7b53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('848fb3a7-a28a-4c8b-8311-db8a0a2ba591', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 21, '100084206', '魔女が求め続けたもの', '魔神王を撃破し、聖戦は終結。その影で〈七つの大罪〉エスカノールは散った。訪れた平穏のさなか、ブリタニアには新たな不穏が忍び寄る。『光と闇の均衡が崩れる時、神々の時代は終焉を迎え、混沌が蘇る。そして世界は生まれ変わる』……それぞれの幸せを信じる〈七つの大罪〉を前に、マーリンは自らが共に戦ってきた理由を見せるという。瞬間移動で連れられたのは、魔神王との戦いの地である「魔法の湖」であった。マーリンは「アーサーを混沌の王として目醒めさせる」と魔術の詠唱を始める。今、明かされるマーリンの過去と目的とは。', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/408989b2-291c-40aa-b7e5-2a480596906d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9085db2-6416-4989-b4ba-d0cb01e8a0b3', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 22, '100084585', '混沌の一端', 'メリオダスへの密かな想い、そして心の飢えを満たすための混沌の復活……明かされたマーリンの狙い。さらに魔法の湖の「混沌の巫女」はマーリンの行動の裏付けを語りを始める。〈七つの大罪〉からは自分たちを謀っていたのではないかと疑念の声が上がる。そんな中、覚醒した混沌はアーサーに共鳴して共生を決め、アーサーは「混沌の王」に認められたとマーリンが告げる。その時、常に傍らに居たキャスが、異形の者となってアーサーに襲いかかり……!?', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67e60cf6-b043-4a63-b9da-3fcc9fcc26cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc7f99c8-4a0c-4c5a-8d8c-3b28f2cd3a70', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 23, '100084947', '永遠の王国', 'アーサーに襲いかかったキャスの正体は、かつて混沌から生み出された獣の暴君だった。そして、〈七つの大罪〉と袂を分かつことになったマーリンは、アーサーを守るべくたった一人でキャスと対峙する。アーサーも剣を抜いてキャスに立ち向かうが、キャスの精神攻撃の前に崩れ落ちようとしていた。ピンチを迎えるマーリンたちを援護したのは、〈七つの大罪〉とエリザベスだった。果たして混沌は世界を飲み込むのか。〈七つの大罪〉の最後の戦いが、始まる――!', '2023/09/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a2bd48f-4f8e-46fa-b0b1-457fd96bf0e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32394a5d-1265-4c6d-8215-3caaf53bf723', '5c372a25-4b91-43f8-ba0e-e8e9f01e823a', 24, '100085604', '継がれゆくもの', '【シーズン1 最終話】アーサーによってキャスは葬られ、再び世界に平穏はもたらされた。〈七つの大罪〉はその役目を終え、それぞれの道を歩み始める。キングとディアンヌは妖精と巨人の王国をつくり、バンはエレインとブリタニアを旅する……。そして、メリオダスとエリザベスも、新たなリオネス国王となる前に、二人で過ごした思い出の地をめぐることに決めた。魔神王との戦いから1年半後、エリザベスとエレインには、種族を超えた新たな生命が宿っていた。', '2023/09/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4f7a16c-151d-4459-be11-1bb86c0bfe2a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6da17131-9a82-40f5-b8de-ae5273cadf72', '七つの大罪 黙示録の四騎士', '', 'hulu', 'the-seven-deadly-sins-four-kights-of-the-apocalypse', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6bfe9369-41d8-45d9-bd78-e401fdd89ed2.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 148862, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cd909823-e462-4685-8e1b-148876f0ec5e', '6da17131-9a82-40f5-b8de-ae5273cadf72', 'hulu-the-seven-deadly-sins-four-kights-of-the-apocalypse-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40ad4c03-770c-4028-b86c-78aa3cbfc70f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9483aa4-9a90-4f6d-94f7-891fce2c27ae', 'cd909823-e462-4685-8e1b-148876f0ec5e', 1, '100162533', '少年は旅立つ', '人里離れた天空の地『神の指』で暮らす少年パーシバル。16歳を迎えた日、祖父バルギスから『外の世界の言い伝え』を聞いたパーシバルは、冒険への憧れを膨らませるものの、バルギスを一人には出来ず、その気持ちを抑えこんでいた……。そんな時、パーシバルの前に、言い伝えの一つである『天空を駆ける幻海の舟を操りし騎士』が現れる。', '2023/10/15 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40ad4c03-770c-4028-b86c-78aa3cbfc70f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ed53b1d-b360-48c0-91c9-a49a9ee1eb64', 'cd909823-e462-4685-8e1b-148876f0ec5e', 2, '100163053', '未知なる力', '生まれて初めて外の世界に降り立ったパーシバルは、不思議なキツネの後を追う中で、大道芸人のカッツ、エルバ、そしてドニーと出会う。魔法のような不思議な力を使う彼らに、イロンシッドを捜していることを打ち明けるパーシバル。情報を得るために村に向かおうとするパーシバルたちの元に、なぜか慌てた様子の村人がやってきて――', '2023/10/22 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95204ff1-0409-4bff-a18f-5bba7a7e98d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0aaf4189-9449-49fb-9691-59b039fc9f06', 'cd909823-e462-4685-8e1b-148876f0ec5e', 3, '100164233', '〈黙示録の四騎士〉', '突如パーシバルたちの前に現れた、イロンシッドの同胞を語る黒き鎧の騎士ペルガルド。危機的状況の中で不思議な力に目覚めたパーシバルは、その力を駆使して戦いに挑むが、尚もって力量差は圧倒的で、次第に追い込こまれてしまう。そこに現れたのは、以前パーシバルが出会った不思議なキツネだった。', '2023/10/29 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0585a219-807e-4026-a62b-ae6378e7f272.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5cc4e124-6055-4520-b4ea-52201739fcd2', 'cd909823-e462-4685-8e1b-148876f0ec5e', 4, '100164843', '木霊の谷の悪魔', '自らが〈黙示録の四騎士〉であると聞かされたパーシバルは、リオネス王国を目指す途中、悪魔が住むと妖精たちが噂する谷に迷い込んだ。噂の悪魔の正体である薬師ナシエンスに囚われ、モルモットとして怪しげな薬の実験台にされるパーシバル。そんなパーシバルを救出するべく、シンとドニーもまた谷へと足を踏み入れるが……', '2023/11/05 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5cef6ce-d094-4c18-b806-d81947375e36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21be196c-9858-4085-9576-8405d15e776f', 'cd909823-e462-4685-8e1b-148876f0ec5e', 5, '100165489', 'さらなる決意', '谷の植物や動物をおかしくしていたのは、怪物となり果てたナシエンスの祖父オルドだった。さらにパーシバルたちの前に姿を現すキャメロットの聖騎士タリスカー。そのタリスカーこそ、オルドを怪物にし、操ってた張本人だと知ったパーシバルとナシエンスは、谷とオルドを救うべく、共に力を合わせることにする。', '2023/11/12 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd92ac7d-b66d-4696-830a-4080b5e9940f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('281ba122-c324-405d-8836-1d36953c94f5', 'cd909823-e462-4685-8e1b-148876f0ec5e', 6, '100166858', '戦慄のシスタナ', 'シスタナの街に現れたイロンシッドは、領主であるカルデンを使い、街の人々にある物を捜させていた。一方、カルデンの娘であるアンは、イロンシッドの企みに人々が利用されていることを見抜き、そのある物を隠す。そんな中、ナシエンスを仲間に加え、リオネス王国を目指すパーシバルたちもシスタナの街にやってきて――。', '2023/11/26 17:40:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf1fc990-602a-4a4e-bcc4-43ef252f92e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3720b80-c29d-4b86-853b-9ecf8d08c434', 'cd909823-e462-4685-8e1b-148876f0ec5e', 7, '100167534', 'その魔力の名は', 'イロンシッドが完成させた『常闇の棺』の儀式により、シスタナの街に混沌の亡者が解き放たれてしまった。儀式の生贄である街の人々をシンに任せ、パーシバルはドニー、ナシエンス、そしてアンと共にイロンシッドの元へ向かう。なんとか『常闇の棺』と奪おうとするパーシバルたちだが、イロンシッドの強さは凄まじく、団結に綻びが生じ始める。', '2023/12/03 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a79cf144-7c77-4b94-8c80-809112fc6a65.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d236e23-fba2-4807-a52f-f495fa036762', 'cd909823-e462-4685-8e1b-148876f0ec5e', 8, '100168376', '幼き勇者たち', '瀕死の重傷を負うも、仲間の想いを力に変える魔力『希望 (ホープ)』によって目覚めたパーシバル。一方、街の人々に迫る亡者たちを退けるために奔走するシン。儀式の妨げとなるパーシバルの息の根を止めんと、あらゆる手段を講じるイロンシッド。しかし、パーシバルたちもまた、イロンシッドに対抗するためのある作戦を考えていて――。', '2023/12/10 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de6e6d76-30e9-4b78-ae03-87727bf3d8eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e76c2c1-77a8-4dec-942d-1dd1e3770d85', 'cd909823-e462-4685-8e1b-148876f0ec5e', 9, '100169054', '師と弟子', '聖騎士になりたいと望むアンを仲間に加え、リオネス王国を目指すパーシバルたち。道中にあるダルフレア山脈を越えるための準備をすべく、カントの街へ向かう。そんな中、ドニーはアンと同じ様に聖騎士を目指していた頃のことを思い出す。――数年前、ドニーには厳しい聖騎士の師匠と、共に修行に励む兄弟子がいた。', '2023/12/17 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb5120b4-2fbd-48b8-8173-0e4c3b0630b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01011983-c5d9-4ad5-8295-c6cd3d11fd86', 'cd909823-e462-4685-8e1b-148876f0ec5e', 10, '100169766', '破滅の咆哮', 'かつての師匠であるハウザーから、聖騎士を諦めた事を責められ逃げ出してしまったドニー。一方、パーシバルたちとハウザーは、かつてのドニーの兄弟子であり、盗賊の頭であるエドリンに囚われてしまう。途方に暮れるパーシバルたちの元へやってくる酒場のマスター。マスターはエドリンの背後にある大きな力について語り始める。', '2023/12/24 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2f0b02b-304a-4786-b2ef-d21512c6d84f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3b93c40-27cf-4a20-b1ba-7a4b8cbd3022', 'cd909823-e462-4685-8e1b-148876f0ec5e', 11, '100170447', '本物の聖騎士', '暴れ出したエンシェントドラゴンを止めようと奮闘するパーシバル。同じ頃、牢屋の中のハウザーは、シンからパーシバルが予言の騎士であること、そしてドニーが混沌の騎士から『常闇の棺』を守ったことを聞かされる。ドラゴンの力を前に逃走を余儀なくされるパーシバルたち。そこに、聖騎士の眼差しを取り戻したハウザーがやってきて――。', '2023/12/31 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/915205b4-74c5-4596-96f8-21a991fa786a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b4ed8ff-72ef-411f-8148-efb96610e01d', 'cd909823-e462-4685-8e1b-148876f0ec5e', 12, '100171687', '邪悪なる試み', 'カントの町を出発し、ダルフレア山脈に足を踏み入れたパーシバルたち。険しい山道をゆく途中、パーシバルは不思議な村を見つける。村へと入ったパーシバルとドニーを追おうとするナシエンスとアン。そこへ一人の猟師･アードが現れ、村には入るなと警告する。アード曰く、そこは化け物の巣窟らしいのだが……', '2024/01/14 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7dbcba64-28ac-480d-9f78-bcb02ad6512c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc8f6f4f-c0ad-4fc7-bcab-c380611fdc9b', 'cd909823-e462-4685-8e1b-148876f0ec5e', 13, '100172631', '追い詰められる者', 'ダルフレア山脈で出会ったアードの正体は、アーサー王に仕える聖騎士･アードベックであった。村に住む魔神族たちが戦を好まず平和に暮らそうとしているにも関わらず、問答無用で成敗しようとするアードベック。一方、すでに村の魔神族と仲良くなっていたパーシバルは、なんとかアードベックを止めようとするが……', '2024/01/21 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9d6277b-f337-4f52-92f1-393b3e0f2fac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2b5a4f2-4947-4aa4-94c4-ed5403a0975e', 'cd909823-e462-4685-8e1b-148876f0ec5e', 14, '100173298', 'ゴート･シン', 'アードベックの魔力によって赤ん坊になってしまったパーシバルたち。そこに現れたのは魔神族の村の長老だった。なぜかアードベックの魔力が効かない長老は自らの正体を明かすと、パーシバルたちを元に戻す代わりにアードベックの望みを叶えると言う。しかしアードベックはその言葉を信じようとはしない。', '2024/01/28 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/65cb62cd-cd42-40a9-b82a-9ad023dd151a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aecb7e20-cc88-45a6-876a-c6845baa32c2', 'cd909823-e462-4685-8e1b-148876f0ec5e', 15, '100174096', '闇のタリスマン', 'ゴウセルやドルチョモンテたちと別れを告げたパーシバル一行は、アーサーが放った追手を気に掛けながらダルフレア山脈を進む。やがてパーシバルたちの前に現れる、巨大な樹木が絡み合う鬱蒼とした森。シンは、すでに間近に迫っている追手をこの森で迎え撃とうと提案する。', '2024/02/04 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84de93b6-88eb-4e7a-b896-bec00b81e051.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc9a9c1c-5d27-4155-a80d-597f0f4105b2', 'cd909823-e462-4685-8e1b-148876f0ec5e', 16, '100174892', 'シンとの別れ', '錯綜する森で『闇のタリスマン』を迎え撃ったパーシバルたち。個々の成長とチームワークにより敵の数を減らしていくが、リーダーであるフィディックの力は他の騎士たちよりも格段に強く、苦戦を強いられる。さらにフィディックは、パーシバルたちが持つ強さの要を潰すため、ある作戦を実行に移す。', '2024/02/11 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6dfe0859-ce7b-467a-891a-16795040ef75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90bb6288-466a-43ce-b6c3-5974779cf10a', 'cd909823-e462-4685-8e1b-148876f0ec5e', 17, '100175222', 'リオネス王', 'ランスロットと共にリオネス王国にやってきたパーシバルたちは、その街並みや異なる種族が行き交う様に圧倒される。一行は王様に謁見すべくリオネス城へと赴くが、運悪く不在の上、いつの間にかパーシバルまでいなくなっていた。その頃、一人で町を散策していたパーシバルは、とあるトラブルに巻き込まれて……', '2024/02/18 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7db12175-758f-4ce2-b782-52aa321d8f8d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef329b3a-ae64-43d4-afae-e83b9417d3d3', 'cd909823-e462-4685-8e1b-148876f0ec5e', 18, '100175727', '予言の騎士の邂逅', '『常闇の棺』の欠片を持っていたことでアーサーの配下だと勘違いされ、リオネスの聖騎士･イゾルデ、ジェイド、キオンに狙われるパーシバルたち。トリスタンによって戦いは止められたものの、視界を奪われた状態で仲間たちを失ったと思い込んだパーシバルは、大きな絶望に囚われてしまい……。', '2024/02/25 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f65e785-3d0a-4bc0-bf88-e066c629c6a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bcb4020-731e-4f6a-a885-70e22c3bf8b2', 'cd909823-e462-4685-8e1b-148876f0ec5e', 19, '100176734', '灼熱のリオネス', 'リオネス城から逃げ出した四人目の予言の騎士を捜索するパーシバルたち。手掛かりは金の装飾が施された白い鎧のみ。そんな中、ランスロットの前に現れた謎の少女は、すぐに捜している人に会えるという予言めいた言葉を残す。一方その頃、町の広場には強い殺気を放つ一人の男が現れて――。', '2024/03/03 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ead7a9b7-c32b-4501-861e-41ede99efb8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b418d10-70a8-4bd6-99a5-ad0bc83f89bf', 'cd909823-e462-4685-8e1b-148876f0ec5e', 20, '100177405', 'じゃじゃ馬ならし', 'パーシバルを追ってリオネスにやってきたペルガルドの前に、ついに揃った〈黙示録の四騎士〉。一触即発の空気の中、ここでペルガルドと戦うべきか逃がすべきかで意見を分かつトリスタン、ランスロット、ガウェイン。一方、パーシバルはペルガルドに歩み寄り、ある提案を持ちかける。', '2024/03/10 17:40:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b0a4af7-e942-41e5-b52e-a8df71b615b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4386d692-a0b4-45c4-838c-2468e4ecdf4e', 'cd909823-e462-4685-8e1b-148876f0ec5e', 21, '100178199', '〈黙示録の四騎士〉 VS 混沌の使徒', 'アーサーの刺客としてリオネスに現れたのは、16年前の聖戦でメリオダスらと死闘を繰り広げた〈十戒〉のガランとメラスキュラ。一方、〈十戒〉が囮だと推測し、アーサーの真の狙いを探ろうとするメリオダス。破壊の限りを尽くさんとするガランとメラスキュラの前に、〈黙示録の四騎士〉が集結する。', '2024/03/17 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c20b8d5-4195-4715-8564-6eaeddb4a48f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9a332c3c-9d91-4660-86b9-31f49e036f34', 'cd909823-e462-4685-8e1b-148876f0ec5e', 22, '100178567', '凍てつき燃ゆる心', '連携によってガランとメラスキュラを退けたパーシバルたち。その直後、とある気配を察知したランスロットはリオネス城へと向かう。城の地下牢には、過ぎた行動を咎められ拘束されたキオンと、見張り役のジェイドがいた。地下へと降りてきた一つの気配に気が付いた二人は、その人物を呼び止めるが……', '2024/03/24 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/616f1afc-d6fd-4d0c-8d3f-946807910a9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ef2f6c1-40da-4f8f-a2d1-e0c10fc5db85', 'cd909823-e462-4685-8e1b-148876f0ec5e', 23, '100179429', '王国聖騎士 VS メラガラン', 'ランスロットが不在の中、混沌の力によって融合し復活したガランとメラスキュラ。その強さは融合前と比べ物にならず、パーシバルの攻撃はおろか、トリスタンやガウェインの魔力攻撃すら躱されてしまう。そんな中、リオネスを守るべく戦う予言の騎士に力を貸すため、王国の聖騎士達がたちあがる。', '2024/03/31 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed50c93a-7cd1-4c56-bcc5-fec1e5c9ab12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('758e0678-fc79-4a1c-9c92-5770ade2d3bf', 'cd909823-e462-4685-8e1b-148876f0ec5e', 24, '100180170', '降臨', '【最終話】人々の希望で力を増した魔力によって、メラガランにダメージを負わせるパーシバル。さらにイゾルデとの共闘で善戦するも、メラガランの力には未だ及ばない。絶体絶命の状況の中、再びメラガランの前に立つトリスタンは、最後の手段を使う決意を固める。だがそれは、あまりにも危険な賭けでもあった。', '2024/04/07 17:10:00', 1409, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/536067e5-2472-4dbd-8260-7284f8d37ef5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f2a4e844-9468-4bbe-91b5-ae25752c5a1e', '6da17131-9a82-40f5-b8de-ae5273cadf72', 'hulu-the-seven-deadly-sins-four-kights-of-the-apocalypse-s2', '第2期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b4092ba-f922-4c15-bef7-b9875046c808.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e883216c-e2a7-4aa8-b2ca-c9884ad62369', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 25, '100201570', '王の威光', 'リオネス王国に到着したパーシバル達の前に現れた宿敵、アーサー･ペンドラゴン。アーサーは自らが治める国･キャメロットでは誰も苦しまず、悲しまず、さらには亡くした大切な人とも再会できると語る。真実か否か、パーシバルや人々が翻弄される中に駆けつけたのは、リオネス王･メリオダスだった。', '2024/10/09 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b4092ba-f922-4c15-bef7-b9875046c808.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56fdbd58-c1c2-4ff6-9c1f-bdbc3919ba9b', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 26, '100202599', '別れの決意', 'キャメロットの襲撃から一夜明け、謁見の間に呼び出されたパーシバル隊の面々は、メリオダスと王妃エリザベスに労いの言葉をかけられる。しかし、〈黙示録の四騎士〉であるパーシバルの【リオネス到着】という一つの目的が果たされた今、ドニー、ナシエンス、アンの三人には、ある悲しい予感があった……。', '2024/10/16 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a32767d-2b48-47b2-b452-015cc7c43446.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('437cd2c7-854c-42f6-ac1e-b08634ce037d', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 27, '100203241', 'ギネヴィア', '仲間たちと共にキャメロットを探す旅に出ることになったパーシバルは、はやる気持ちを抑えきれずにいる。一方、リオネスに滞在している謎の少女･ギネヴィアと再会したランスロットは、彼女の正体とその魔力、そして心に抱えた悲しみを知ることに……', '2024/10/23 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3e0cd66-1993-4fe1-96fc-9cb9bc1355ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92ef954c-78ef-42f8-900c-b39c642d5d9a', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 28, '100204094', '対峙', 'ギネヴィアをキャメロットに連れ去った後、自宅に戻るイロンシッド。そこで【ある家族】に迎えられたイロンシッドは、普段の冷酷な姿とは違う一面を見せる。一方、旅の途中で壁の街･ウォルナックを目指すパーシバルたちは、その動きをギネヴィアの魔力を利用したアーサーに知られてしまう。', '2024/11/06 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1718f7b7-9ba2-4f5b-a188-ac095d66afd3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44223792-55e9-4ce1-8812-da59cd77db38', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 29, '100205260', '壁の町の戦い', '壁の街･ウォルナックの鎮魂祭に参加し、亡き大切な人々に想いを馳せるパーシバルたち。その背後に、アーサーが送った2人の刺客、マクダフとティーニニックが迫る。その頃、謎の女性と共に街を歩いていたトリスタンは、恐るべき彼女の正体を知ることに――', '2024/11/13 17:40:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5b9e2d8-ba04-4968-89e9-1d231f350dea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a479dcfb-9dad-40f9-b89a-0b0b56e5e2e9', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 30, '100206689', '追想の炎', 'キャメロットから来た刺客･ティーニニックを倒し、はぐれた仲間たちとの合流を急ぐパーシバルたち。一方、戦いの中で毒を受けたイゾルデと共に移動するアンとジェイドの行く手に、もう一人の刺客･マクダフが立ち塞がる。それぞれの想いを懸けた戦いが始まろうとしていた。', '2024/11/20 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6b9953f-040c-45dd-9873-a60007eb3dbe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21eb063e-3327-4744-859c-e0412e92a992', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 31, '100207470', '狂王', '大切な仲間を失い、離れ離れになりそうな皆の心を必死につなぎとめるパーシバル。その頃キャメロットでは、ウォルナックでの戦いの結果を知ったアーサーがさらなる刺客を送り込もうと画策していた。一刻も早くキャメロットを見つけるべく、手がかりを掴みたいパーシバルたちだが……', '2024/11/27 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ea8f2ac-da30-405f-9099-97a60af1133e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30581f99-ee51-43fc-bd26-a67ab22b6150', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 32, '100208329', '救い主様', 'キャメロットへの手がかりを見つけるため、魔神族のイオと共に魔界へやってきたパーシバルたち。その光景を見た時、パーシバルの脳裏にかつてこの場所にいたという不思議な記憶が蘇る。一方、侵入者を捕らえるために動きだす魔神族。彼らを束ねるのは――', '2024/12/04 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a4736c6-f6cf-4119-96c6-3219b742b466.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25d5637a-1ad0-4068-8d81-5de2b0a0396c', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 33, '100209658', '災いのベヒモス', '〈黙示録の四騎士〉を始末するべく魔界にやってきた刺客･モートラックたちに単独で戦いを仕掛けるガウェイン。その一方で、刺客の一人であるローズバンクと出会ったパーシバルは対話をしようと試みる。同じ頃、魔界の城にいるトリスタンは、魔神王ゼルドリスからキャメロットに通じる扉についての情報を得るが……', '2024/12/11 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90da4647-1c24-409e-949c-9e1efd4ee0d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ff7e1ef-eedd-446b-982f-86264bf5faa0', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 34, '100210361', '揺れるココロ', 'ベヒモスの周囲に炎の雨を降らす『炎災の月』が終わるまでの間、ランスロットの特訓を受けるパーシバル隊の面々。課せられた課題に臨む中、改めて自分の心と感情に向き合うことになるナシエンスとアン。一方、次の戦いに備えていたトリスタンは、魔神族の闘士･シュバルツから呼び出され、決闘を挑まれる。', '2024/12/18 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1098ae05-5a20-4dbb-bc75-1e0d3348d7df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('324d395d-e50a-4c3d-8844-565641e4a7e8', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 35, '100211514', '宿命の少年', 'ランスロットとの特訓中、魔力によって生まれた『もう一人のパーシバル』。再びその魔力が己に宿る時、パーシバルはこれまでにない力が湧き出すのを感じる。やがて『炎災の月』が止み、ベヒモスへ向かう時がやってきた。キャメロットを目指す者たちと、それを阻まんとする者たちの戦いが目の前に迫る。', '2024/12/25 17:10:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47c0e6ea-d82a-4307-b00c-27965a7a6d19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f971040-b456-4e6d-91c7-7844597c723d', 'f2a4e844-9468-4bbe-91b5-ae25752c5a1e', 36, '100211949', '強者たちの宴', '【第2期 最終話】突如ベヒモスに宿る精霊の世界に引き込まれ、自らの存在の起源を知るパーシバル。その真実を受け止めきれぬまま元の世界へと戻ったパーシバルの前に、モートラックたちが立ちはだかる。ついに姿を現すキャメロットへの扉を前に、互いに譲れぬ使命を背負う〈黙示録の四騎士〉たちとキャメロットの騎士たちが激突する。', '2025/01/01 17:10:00', 1412, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a4d5beb-0d3d-4a5e-ac9e-9783c934d841.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ce001638-e15d-4fb5-8ac0-18a7aeb08acd', '七つの魔剣が支配する', '', 'hulu', 'reign-of-the-seven-spellblades', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b5dab4f-bc6e-43bb-971c-2c41af82b38c.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 142598, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('53d8a0a0-7671-4598-910f-ca7a19b573eb', 'ce001638-e15d-4fb5-8ac0-18a7aeb08acd', 'hulu-reign-of-the-seven-spellblades-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1484ed49-5fc1-4f1b-9ad7-a96c11108174.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0350af0-230d-45ab-9634-8ce92a3d8d23', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 1, '100150703', '入学式 (セレモニー)', '名門、キンバリー魔法学校の入学式に向かう少年･オリバー=ホーン。彼は新入生の中で、ひときわ異彩を放つ、”サムライ”のような出で立ちの少女に目を奪われる。賑やかな喧騒とともに、歓迎の魔法生物パレードが始まるが、突然トロールの一体が暴走し始める。新入生のひとりに危害が及ぶその瞬間、それを阻んで立ち塞がったのは刀を携えたサムライの少女･ナナオ=ヒビヤだった。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1484ed49-5fc1-4f1b-9ad7-a96c11108174.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24d4bec1-5fa0-47bd-9e15-e62f4aae29d6', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 2, '100150704', '魔法剣 (ソードアーツ)', 'キンバリーでの授業初日、オリバーたちは「魔法剣」について学ぶ。呪文詠唱が間に合わない至近距離での攻防、「一足一杖」の間合いにおける「杖剣」を使った戦い方である。担当教諭･ガーランドの提案で、経験者同士で立ち合うことになるも、なぜか名乗りを挙げたのは魔法素人のナナオだった。相手を務めるオリバーは手加減しようとするのだが……。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7928b4b0-73ad-48b2-85ad-bb7e45751bb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eba47755-526a-413d-b9ca-f302f67f1f6a', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 3, '100150705', '死兵 (ソルジャー)', '迷宮化した夜の校舎で、禍々しい気を纏った上級生のオフィーリアとリヴァーモアに挟まれたオリバー、シェラ、ピートの3人。しかし、上級生たちには因縁があるらしく、互いを侮蔑しながら杖を抜く。魔女と魔人の戦いを前に為す術はなく絶体絶命の状況。そこに現れたナナオは、自分が囮となり3人を逃がすと言ってのけるが、オリバーは捨て身の彼女に怒りを覚えて……', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91a8fa97-51c4-4a7e-8147-a2e8f32a063d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04823988-fc7b-4d12-8add-090604ebc5ac', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 4, '100150706', '円形闘技場 (コロシアム)', 'カティはパレードで自らを襲ったトロールと仲良くなるため、魔法生物飼育区画へと足繁く通う。一方、人権派の彼女を疎むクラスメイトたちからの嫌がらせは日に日に悪化する。痺れを切らしたオリバーたちは、ついに”行動”に出てしまい……1年生の多くが敵に回る中、オリバーとナナオに決闘を申し込んだのは、授業初日から因縁をつけてきたアンドリューズだった。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83e2b735-415e-4634-8625-a5e7ba4ecbb0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b776f516-f3c0-4c6e-a19e-7086b5bc59fb', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 5, '100150707', '蛇眼 (グレアー)', '決闘にガルダが乱入して以来、亜人種の権利を認めない保守派の生徒たちは随分と大人しくなっていた。カティは人権派の先輩･ミリガンに見守られながら、トロールを真摯に世話しつづけ、ついに意思疎通が叶う。やっと学校生活が軌道に乗り始めたと思えた矢先、トロールを処分するべきと主張していたダリウスによる「錬金術」の授業でオリバーは目をつけられてしまう。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58614012-bf3a-4563-b70d-c734e8629a56.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5b5ebee-ba76-4168-825f-93003ceaf307', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 6, '100150708', '顕現 (アライズ)', 'カティを連れ去った犯人はミリガンだった。ミリガンはカティの“脳”を解剖し、トロールの言語能力を開花させた仕組みを暴こうとする。友人を助け出そうとするオリバーとナナオだが、上級生･ミリガンの実力を前に苦戦する。2人は連携し、決死の覚悟で攻撃に転じるが、嘲笑うかのように”蛇眼”が怪しく光る。果たして無事にカティを救うことはできるのか――。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b15b5bc-e91e-4db7-9f35-47130c52d0ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fcc6cccb-cd31-4638-be48-af135c3473e2', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 7, '100150709', '両極往来者 (リバーシ)', '母の仇の1人であるダリウスを討ったオリバー。残る復讐の相手は、キンバリー魔法学校の学校長･エスメラルダをはじめ6人の教師陣。突然姿を消したダリウスの行方について話し合う彼らだが、エスメラルダは犯人が誰であれ、自分を敵に回したことを後悔するのみと冷酷に言い放つ。一方、朝から様子がおかしいピート。実は彼の体には“ある変化”が起こっていた。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8deba286-ab88-44f4-92a2-3ffb0908932d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6dae1263-3142-45db-988c-ee991e0ab20e', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 8, '100150710', '挑戦者 (ライバルズ)', 'ピートは「魔法剣」の授業で同学年トゥリオ=ロッシとの立ち合いに負け、「頼もしい仲間に守られている“姫”」と侮辱されてしまう。怒りを覚えつつも反論できないピートは、オリバーとシェラに放課後の特訓を願い出る。しかし、そこに突っかかって来たのはまたもやロッシだった。一年最強は誰かを決めよう――彼は活躍を続けるオリバーたちに対し決闘を申し込む。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08d560e3-7db2-4531-88c3-7bd968156b6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49d3cdef-edb5-4ca7-a37d-c4284a356a23', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 9, '100150711', '迷宮探索 (エクスプロア)', '特異体質“リバーシ”となったことを、オリバー以外の4人にも伝えたピート。同時に、それが欠点ではなく、魔法使いにとって稀有な才能であることをシェラから教わる。そんな中で挑んだ「魔法剣」の授業で、ピートは同学年のステイシー=コーンウォリスと立ち合うことに。以前教師のセオドールに褒められたピートへ嫉妬を抱くステイシーは、容赦のない剣で彼を追い詰める。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12cbcfce-7db8-4e86-a307-4a9a726548b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5940ba55-0443-4999-920d-93a1d9d9b702', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 10, '100150712', '主従 (マスターアンドナイト)', 'ミリガンから譲られた工房でオリバーとナナオが呪文の訓練をしている中、エントランスからガイの叫び声が聞こえてくる。駆けつけると、そこにはカティが絆を結んだトロール、マルコの姿があった。互いの友好を確認し合った彼らは、合流して二日目の迷宮探索へと出発。しかし行き先にステイシーとフェイが待ち構えており、メダルを賭けた決闘を挑んでくる。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d74b802-07f7-412e-8aa8-6f47380e9565.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5933167f-2593-42a0-971f-218ef614429a', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 11, '100150713', '責務 (デューティー)', '迷宮第二層『賑わいの森』の中で、杖剣を交えるオリバーとオルブライト。度重なる猛攻をオリバーは必死に耐え凌ぎ、技術を駆使して粘り強くオルブライトと渡り合う。一方、シェラとナナオも、ステイシーとフェイの連携に苦戦。なぜステイシーがここまでシェラとの戦いに必死になるのか。そこには、マクファーレン家にまつわる複雑な事情にあった。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59510548-ef1c-474d-bec3-0e3e272709c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7a58f58-2069-4a16-be30-a34ddb1e1b76', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 12, '100150714', '生還率 (ポッシビリティー)', '魔に呑まれたオフィーリアによって、ピートやオルブライト、フェイが攫われてしまった。ほかにも多くの生徒が行方不明となっており、ゴッドフレイら上級生が救出へと向かう。しかし、数日経っても彼らは戻ってこず、オリバーたちは焦りを募らせる。教師に掛け合うも取り合ってもらえず、ついに自らピートの救出へ向かうことを決意する彼らだが、意外な人物がそこに現れ……。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7521205-a5dc-4dbe-b099-6664e804812d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11b92aa6-1d69-44f1-b6f8-0cb2f32e98ed', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 13, '100150715', '賑わいの森 (ノイジーフォレスト)', '捕らわれたピートたちを救うべく、迷宮第二層『賑わいの森』を捜索中のオリバーたち。険しい道のりが待ち構え、森は魔獣だらけ、さらにはオフィーリアの産み出したキメラが徘徊する中を通り抜けなければならない。懸命に歩みを進める彼らだが、その前に巨大な魔猿が姿を現す。戦いを覚悟するオリバーとシェラに対し、なぜかナナオは刀を抜かず魔猿へと近づいていき……。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a56c79b2-76dd-4425-a4e7-c5576e3ff27a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c3e234b-332f-48dc-9480-ccb05af3cba1', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 14, '100150716', '淫魔の末裔 (サルヴァドーリ)', '迷宮第三層へと到達し、オフィーリアの濃密なパフュームに集中力を削られながら探索を続けるオリバー。その頃、同じく三層を進むゴッドフレイは、3年前のオフィーリアとの出会いを思い出していた。カルロスに紹介され、友人になるべく彼女のもとへ通い詰めた日々。その努力が実ってパフュームを克服し、彼はついに自らの自警団へオフィーリアを招き入れるのだが……。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb7f38aa-1dac-4c55-8920-1fcdd1755ccf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64b86af6-c32c-4ad6-90cf-2cb9875416cd', '53d8a0a0-7671-4598-910f-ca7a19b573eb', 15, '100150717', '聖歌 (ラストソング)', '【最終話】ピートの投げた救難球の光はオリバーたちに届いていた。ピートはすんでのところで救出される。オリバーから「よく頑張った」と抱きしめられたピートは安堵の涙を流す。が、再会を喜ぶのもつかの間、そこにキメラを連れたオフィーリアもやって来てしまう。もはや彼女との正面対決しか道はないと覚悟を決めるオリバーたち。一方で、同じ現場を目指すゴッドフレイとカルロスは……。', '2026/03/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3fd3996-3b92-4580-8141-6960d9708b6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c4560ed9-03af-46c5-960f-b2b4731af87e', '失格紋の最強賢者', '', 'hulu', 'the-strongest-sage-with-the-weakest-crest', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6dce5726-b199-4aef-93cb-42ea1b6cd519.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 129191, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9b06322e-c9f9-4f02-90b7-496f740f2645', 'c4560ed9-03af-46c5-960f-b2b4731af87e', 'hulu-the-strongest-sage-with-the-weakest-crest-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7afd41f6-6b34-44db-8bdb-3a799af08c00.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6dfae4d-d23b-4666-a9bb-b049945aed7b', '9b06322e-c9f9-4f02-90b7-496f740f2645', 1, '100101108', '最強賢者、現る。', '12歳になった貴族の少年マティアスは魔法を学ぶため王都の学園の入学試験を受けに行く。道中で襲ってきたモンスターを簡単に退け、同じく試験を受けに来た少女ルリイとアルマのために常識離れの付与魔術を披露し、試験本番では圧倒的な力を見せつける。「失格紋」の持ち主でありながらここまでの実力を発揮する彼の正体は……。', '2022/01/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7afd41f6-6b34-44db-8bdb-3a799af08c00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5a1aae1-aab3-42f0-8ece-8de84702f8b8', '9b06322e-c9f9-4f02-90b7-496f740f2645', 2, '100101585', '最強賢者、迷宮 (ダンジョン) へ。', 'マティアスの正体は、数千年の時を経て転生した賢者ガイアスだった! マティアスは学園同士の代表が戦う対抗戦に出場し、余裕で勝利。しかも彼が倒した生徒の正体は前世で滅ぼしたはずの魔族だった。これをきっかけに動き出した魔族たち。マティアスは来るべき魔族たちの戦いに備え、ルリイとアルマを連れて迷宮の探索へ向かう。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24839e09-657a-4b18-a860-fcb9dc8333b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4c8c449-c57e-4282-83b0-0cbc6e14b34f', '9b06322e-c9f9-4f02-90b7-496f740f2645', 3, '100102314', '最強賢者、竜 (イリス) と出会う。', '王都に突如現れた2体の魔族。2体を同時には相手にできないマティアスは1体を自分が、もう1体をルリイとアルマに任せることに。魔族に対して魔力量で劣るマティアスに、実戦経験は足りないルリイとアルマ。圧倒的不利に見える戦いで、マティアスが元賢者としての真価を発揮する! そしてさらに新たなる規格外の仲間が……。', '2022/01/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99bb3927-f4af-4b56-be8a-8381cce1f1e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50b8639b-75bb-49fb-ac28-cb330d7b6b5a', '9b06322e-c9f9-4f02-90b7-496f740f2645', 4, '100102827', '最強賢者、潜入する。', '前世の頃の知り合いであった暗黒竜イリスを仲間にしたマティアスは、彼女の背に乗って魔族が潜伏する村へ向かう。突然のマティアスの襲撃に困惑する魔族たちだったが、彼らはこの戦いの前にある壮大な策を用意していた……。そして王都に戻ろうとするマティアスはイリスに対してとんでもない提案を言う。', '2022/02/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e06004e8-ce74-4f18-b083-eedd552760c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ed14de5-946c-4e29-80b7-bcf86375fd93', '9b06322e-c9f9-4f02-90b7-496f740f2645', 5, '100103738', '最強賢者、仲間を得る。', '王都に向けて魔物を大量に発生させていた魔族たち。それに対する防衛策としてマティアスは結界を構築するために、第一学園の協力を求めたり、迷宮で結界の材料を集めたりと大忙し。しかし、第一学園からは対抗意識を燃やす向こうの校長に協力を跳ね除けられ、迷宮内では誤って巨大な竜を召喚してしまうなどトラブル続きで……。', '2022/02/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56cb27d0-dedd-4fc8-b582-58bcbd6b1539.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8d162b6-2429-4dd1-95d7-5fab3a3f7e8d', '9b06322e-c9f9-4f02-90b7-496f740f2645', 6, '100104328', '最強賢者、学園を出る。', '王都大結界の構築中、魔族が王都周辺に侵入してきた。結界の構築から手を離せないマティアスは魔族の対応をルリイとアルマに任せることに。二人はマティアスの期待に応えてあっさり魔族を撃退。しかし魔族は最終手段を用いて、いよいよ全軍を王都に集結させる。学園生たちと魔族の全面衝突がついに始まる……!', '2022/02/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa370987-01af-4da3-9438-d4bbe1a7748e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b85ceba5-411e-42ab-939d-af081427efb1', '9b06322e-c9f9-4f02-90b7-496f740f2645', 7, '100104841', '最強賢者、旅路を往く。', 'マティアスたちは龍脈の調査をするために学園を離れ、迷宮都市メルキアへの旅に出る。だが、たどり着いたメルキアは領主の無茶な命令と強力な魔物の出現が重なり、すっかりさびれていた。問題の迷宮を調査するべく冒険者ギルドで許可証をもらおうとするマティアスたちだが、さっそく魔物が起こした騒ぎに巻き込まれ……。', '2022/02/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b6bd654-8276-4009-8497-e3a64d66104c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46e25313-9cc4-4552-9466-3e5d89ff8e0b', '9b06322e-c9f9-4f02-90b7-496f740f2645', 8, '100105680', '最強賢者、街を救う。', '悪徳領主の刺客によって捕えられそうになったマティアスだが、あっさり返り討ちにする。さらに国王の許可も取って逆に領主を捕えようと計画を立てる。王家代理人のエイクと共に正面から屋敷に乗り込んで領主を捕えたマティアスは、領主の不自然な行動の裏には迷宮を利用しようとする魔族が関わっていたことを知る!', '2022/03/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d6be222-162f-4c44-a0a7-92dc2bbda85f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1d85485-4968-4239-a352-e5700a39b52a', '9b06322e-c9f9-4f02-90b7-496f740f2645', 9, '100106118', '最強賢者、決闘する。', '迷宮に潜む魔族を倒した直後、マティアスは魔族たちを指揮する者からの干渉を受ける。その者の正体を探るため、マティアスは前世の自分が作った探知装置を求めてラジニア連合へ向かう。だが探知装置のある地域に入るにはAランクの冒険者になる必要があった。その昇格試験の試験官にSランク冒険者のギルアスが名乗りを上げる!', '2022/03/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0c1542e-6bfd-4274-9338-3d534410f2ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cc50dac-5a46-44b7-99c3-6e59ddbb1460', '9b06322e-c9f9-4f02-90b7-496f740f2645', 10, '100106975', '最強賢者、連携する。', 'Aランク冒険者となり、探知装置のあるフォルキアへ向かったマティアスたち。だが、フォルキアは魔族の群れによって支配されていた! 人間たちを魔法で操り、国をも滅ぼす巨大兵器をひそかに生産する魔族たち。このような事態を見逃すわけにはいかないマティアス一行はイリスの膨大な魔力を使った意外な作戦に打って出る!', '2022/03/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4a655c9-b40a-4288-b4c3-240aa32a92cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('781e5d9b-6401-49a3-80b2-ac99feec86bd', '9b06322e-c9f9-4f02-90b7-496f740f2645', 11, '100107457', '最強賢者、強敵と相対する。', 'ギルアスによって魔族のボスは倒される。だがその正体は、強大な魔力によって操られた、ただの死体だった。マティアスはこの死体を操っていた者こそが一連の事件の黒幕だと確信する。そして一行はいよいよ魔法文明が眠る古代遺跡に突入する。しかし、実はこの遺跡に眠る品々は全部前世のマティアスが作ったもので……。', '2022/03/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/577a9a85-039a-4655-809b-ce35e605950d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81e568b1-2f35-48a7-988a-7fb8bf0be495', '9b06322e-c9f9-4f02-90b7-496f740f2645', 12, '100107902', '最強賢者、再び旅立つ。', '【第1シリーズ 最終話】ついに復活した最高位の魔族･ザリディアス。その圧倒的な魔力の前にはマティアスですら太刀打ちできない……。アルマとルリイは王都の宝物庫に眠る前世のマティアスが作った魔剣を回収しようとするも、魔族に学園の生徒を人質に取られ足止めをされてしまう……。このかつてない窮地をマティアスは乗り越えることができるのか!?', '2022/03/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00114a9b-9a71-4f5a-b933-30c3785cd9fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ccebf50e-8b5b-4b09-8cff-8fcd9443c95b', '実は俺、最強でした？', '', 'hulu', 'jitsuha-ore-saikyo-desita', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6bf83606-d5f9-4a5c-9788-3b5b17d0d677.png?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 154391, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ca06d41e-b78f-41b4-bbb5-640cd8dad258', 'ccebf50e-8b5b-4b09-8cff-8fcd9443c95b', 'hulu-jitsuha-ore-saikyo-desita-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7222b684-18e5-44f4-9efb-0c69f194ca46.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6448476c-a28a-42fd-8be1-d1636c44b5e3', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 1, '100151183', '「転生したらどん底スタート」', '引きこもりから異世界の王子の赤ちゃんとして転生したハルト。転生の際、女神から強大な魔力を与えられたものの、強大すぎるが故に測りきれず“魔法レベルが低い”と勘違いされ、転生早々森に捨てられてしまう。その後、森で出会った魔族のフレイと共にゴルド･ゼンフィス辺境伯に拾われ、不自由のない引きこもり生活を送ることになるが…そこには“強大な魔力を有する”ハルトの秘密に迫ろうとする妹･シャルロッテの姿があった。', '2023/07/08 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7222b684-18e5-44f4-9efb-0c69f194ca46.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eee04724-7866-4586-a073-a6c4a9f3f493', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 2, '100151184', '「シャルに嫌われてます」', '近頃、ゴルド辺境伯領内で盗賊による被害が多発していた。領内で不穏な空気が漂う中、シャルロッテと母･ナタリアが謎の集団に襲われてしまう。家族を狙った敵に怒り狂うハルトは、間一髪でシャルロッテとナタリアを救出。だが、この事件をきっかけに、ハルトとシャルロッテの距離は一気に縮まることになった。一方ハルトは、盗賊被害やシャルロッテたちを襲った敵の正体について、領内に裏切者が存在することに気付き始め…', '2023/07/15 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2036ce02-37d9-4b8a-9444-e46184cb0b9d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('14e17fc1-3d66-477b-8a4d-b5a687748e1d', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 3, '100152296', '「シャルに懐かれました」', '帝国兵に襲われた一件からシャルロッテはハルトを慕い、常に一緒にいる仲良し兄妹となっていた。そんなある時、ハルトはシャルロッテに“アニメ”の存在を教える。見てみたいと言われ、苦労の末、現代日本のネット世界と転生後の世界を繋げることに成功したハルト。そしてそこには、初めて目にしたアニメに夢中になるシャルロッテの姿があった…一方でハルトは、アニメに影響されたシャルロッテの願いで正義の味方･シヴァとして活動を始めることになるのだが…', '2023/07/22 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f798e556-e2df-4ee7-a2be-76bbf1293619.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a854eb99-ff9d-461f-adf3-439e675f15e3', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 4, '100152297', '「俺･キレる」', 'ある日、シャルロッテが王子･ライアスの視察に同行することになった。それを心配したハルトが視察ルートを監視していると、なにやら怪しい召喚士部隊がいることに気が付く。シヴァとして召喚士部隊に接触したハルトは、リーダーらしき男から衝撃の目的を告げられる。それは王妃･ギーゼロッテの命令でシャルロッテを暗殺する…というものであった。自分を捨てたうえ、大切な家族の命を狙うギーゼロッテに怒りが込み上げるハルトは反撃を決意するのであった…', '2023/08/05 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03cd3f00-e0da-4516-9ca7-6e90d4294a5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3af05273-1a7f-4ea2-91ae-033c1f2a6880', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 5, '100152298', '「世界最強」', 'シャルロッテ暗殺失敗に怒るギーゼロッテの前に、反撃を目論むシヴァが現れた。強大な魔法力で圧倒したシヴァは、ギーゼロッテの首に簡単には外れない特殊な首輪を付ける。そしてそれは屈辱の証でもあった…ギーゼロッテの一件も落ち着いて5年が経ったある日、ハルトはゴルドから王都の魔法学校に通うよう言われてしまう。夢見る引きこもりライフとはかけ離れた提案に戸惑うハルトだったが、自身を拾い大切に育ててくれた父親への恩返しとして学校に通うことを決意するのであった。', '2023/08/12 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec687210-0276-49d7-977d-4968d8ee87a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31387203-c4c1-405f-96a7-af12b5cf7156', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 6, '100152299', '「従者を探さないと…!」', 'ハルトが通うことになった魔法学校では、従者を1人連れていく必要があった。しかし、適した従者を見つけることにハルトは苦戦していた。一方その頃、国境付近で手負いのドラゴンが出現したという情報がハルトの元に入る。ハルトとフレイが急いで現場へ向かうと、そこには兵士に襲われて負傷したブリザード･ドラゴンが倒れていた。その後、ハルトたちの手により無事保護されたドラゴンは、“リザ”として新たな仲間に迎えられることになった。', '2023/08/26 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a987233d-9119-47cf-a2bf-7bd6157bd0b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a829ce4b-1e81-47bd-ac6d-7e1ec9ac8b4f', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 7, '100156548', '「円卓会議」', 'ハルトの計らいによりゼンフィス家のメイドとなったリザ。真面目で優しくメイドとしての仕事も完璧にこなすその姿は、ハルトの従者として最も適した存在であった。しかし、従者にしてしまうと王都まで同行させなければならず、仲良しなシャルロッテとリザを離れ離れにしてしまうことになる…。可愛い妹とリザを傷つけるわけにはいかない! そんな葛藤を抱く中で、ハルトはある秘策を思いつくのだった…。', '2023/09/02 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98f39b2b-20ec-4eb7-b3a6-064820064a46.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08388b13-62a1-43a9-a3b9-3fd7c9f4bff8', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 8, '100157172', '「新たな出会い」', 'ハルトの入学が決まり内心嬉しいライアスとマリアンヌ。その2人のもとにギーゼロッテが現れ、ライアスにとある任務を課した。それは「ハルトから黒い戦士･シヴァに関する知り得る限りの情報を聞き出す」というもの。自分のせいでハルトを大変なことに巻き込んでしまったのではないか…と罪悪感を隠せないライアス。一方で王都に着いたハルトは、シャルロッテが提案した調査 (という名のデート) への付き添いで王都内を巡っていたが、そこで謎の少女と出会う。', '2023/09/09 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee72591c-498c-458a-8989-71a0f460a421.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26b48aae-d78a-47dd-bfca-5de3182d3e88', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 9, '100157173', '「入学式のすったもんだ」', '理想の引きこもりライフとは程遠い学院生活を送ることになったハルトは、入学早々に退学の道を模索し始める。そんなハルトの魔法に興味を抱き、自分の研究室へと執拗に勧誘するティアリエッタ教授は、古代魔法の研究者としてとても有名だった。そしてハルトはティアリエッタによる執拗な勧誘から逃れている最中、以前王都で出会った少女が学院の上級生に絡まれているところを目撃するが…。', '2023/09/16 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91a4387c-cc41-45f6-9175-95d939d9afac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ea96b49-d48c-4a22-bd53-6f3be34bb213', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 10, '100158974', '「魔王の名は」', 'シュナイダルの一件以降、学院内でも噂となったハルト。そんなある日、ティアリエッタやライアス達からの執拗な勧誘に苦悩しているハルトの所に偶然にも謎の少女が通りかかる。「こいつと約束がある」という口実で何とかその場から逃れたハルトは、謎の少女と初めて真面に言葉を交わすことになる。彼女の話によるとハルトと同様に生まれた時に捨てられ、閉鎖的で孤独な生活を送っていたという。そして彼女は“イリスフィリア”と名乗ったのだった…。', '2023/09/23 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cafba844-f178-4af3-804f-b8adbfd69c28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc01858b-fae1-4c05-8aaf-d45c5073bff6', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 11, '100158975', '「いろんな人に絡まれました…」', '入学して初めてのクラス分けでCクラスとなったハルトは、最初のテストでいきなり高得点を叩き出してしまい早々にAクラスへの昇格が決定する。早速、属性論を専門とするオラトリア教授による講義が始まるが、ハルトのひょんな発言から、ここでも自身の優秀さが露呈し再び注目を集める結果となってしまった。しかしハルトは自分が優秀なのではなく、いつも時間を共にしているシャルロッテが優秀すぎるが故に、自分も優秀になりつつあることに気付くのだった…。', '2023/09/30 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b08e2ff-def9-4242-bf76-2517678a5688.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aae6f11d-f37e-4a41-a817-b5e6da6d6f7e', 'ca06d41e-b78f-41b4-bbb5-640cd8dad258', 12, '100158976', '「悪くない夜」', '【最終話】ティアリエッタの研究室への所属が決まり、新人歓迎会で温かく迎えられたハルトとイリスフィリア。この研究室に入ったことで強くなれるかもしれないとイリスフィリアに感謝され、照れるハルト。実は彼女は魔法レベルが低いまま止まってしまったことを気にして古代魔法にかけていたのだった。しかしその裏でシュナイダルが先日の復讐をしようとハルト達を狙っていた…! そしてとある日、円卓会議のメンバーと熱い議論を交わすシャルロッテ達の姿があった。その内容にハルトは…?', '2023/10/07 00:00:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94639d41-fa3f-4beb-8785-c953247e271a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('502658c1-e20c-473f-b350-ad6ded10d6f5', '社長、バトルの時間です！', '', 'hulu', 'shachibato', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36f75a2d-ab14-421e-b25c-960822db452a.jpg?w=331&h=447&p=t', 'hulu', 2020, 1, 1, 'FINISHED', NULL, 113570, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', '502658c1-e20c-473f-b350-ad6ded10d6f5', 'hulu-shachibato-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b8c5cf7-dd7f-447c-a3d9-3391366c726c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6396ae09-26f7-465f-900a-4a1c6cfe2c37', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 1, '100054047', '社長就任', '「お願い、私たちの社長になって!」幼馴染のユトリアに呼び出され、突然そう告げられたミナト。流されるままに、ミナトは行方を眩ませた父親に代わって倒産寸前のキボウカンパニーの社長になることに。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b8c5cf7-dd7f-447c-a3d9-3391366c726c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad25c98b-d668-4878-b072-2a5683c05159', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 2, '100054534', '遺産相続', '社長就任早々、ミナトに知らされたのは、キボウカンパニーの財政難―収益予想は大赤字、装備品の補充もままならず、社の存続すら危うい崖っぷちの現状だった。状況を打開するため、選んだ手段は賞金レース!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f18c5eb7-33e8-4d41-9a3a-d729c2d7fa88.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2426f178-5a6b-4fd8-ab8e-7cdb2d15581e', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 3, '100054894', '受注コンペ', 'アカリのサイエッジへの引き抜きをかけて、ライバーとの壮絶なダンジョン攻略争いが開幕する! マコトのリュックに隠された秘密、そして最深部に潜む強大なボスマジューとの闘いの行方は…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89ef4aa5-00a7-4a99-8120-88c6cbbaa626.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae012310-7775-469b-9cd4-42b895a9b176', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 4, '100055132', '財宝探索', 'おいしい話が見つかったと喜ぶユトリアの手元には、魔法使いの少女･マリカが持ってきた古びた宝の地図が。相続税の支払いのため、ミナトたちは一攫千金を狙い宝探しに挑むが、当然一筋縄ではいかなくて…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00c32167-13ac-41be-a6cf-649b4fe61107.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c4a0f04-4870-4136-b5df-75fa395a49d4', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 5, '100055200', '新入社員', 'マリカを新たな社員に迎え、盛り上がるキボウカンパニー。しかし、ミナトが契約書の回収で訪れたマリカの家で事件が…。一方、ゲートピアの地下道に異様なダンジョンが見つかり、サイエッジが探索に向かう。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67628232-58fa-48df-bc1d-919baaed0b8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae64857d-6561-48be-b928-06fbf73571f0', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 6, '100055667', '企業目標', 'ミナトたちはレアアースを求めて、奇妙な機械化ダンジョンへ探索に向かう。次々にトラップが迫り、見たこともないマジューが襲ってくる危険な状況のなか、アカリとマリカにも異変がおきてしまい…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b8ba49e2-1a04-4602-a6f3-f1066e0d52e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f305b8eb-3a0d-41c6-bbcd-4f266232e596', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 7, '100055911', '中間決算', '経営が軌道に乗り始め、張り切る社員一同。しかし女神召喚の前に、考えるべきは目前に迫った中間決算! 膨大な資料に目を剥くミナトに、ぽつぽつと語られるガイドの昔話。そしてアカリのお願いとは…?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20f015b2-6315-4ba3-a02a-def3ccedef20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa850a00-f05d-4c98-b4e3-53716a48402a', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 8, '100056344', '新種発見', 'マコトは“言葉を話す”と噂される不思議なマジューに興味津々。どうしても会いたいと暴走するマコトと共にダンジョンの探索に向かうが、そこでミナトは絶体絶命な状況に陥ってしまう。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1fcba27e-e4d0-427f-8020-b38df3c6dd24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('499fb1f9-feae-4b47-a286-ecb3c86c5a3f', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 9, '100057129', '白馬の騎士', '友だちになるという約束を果たすため、マコトは姿を消してしまったミネ子を追う。無事ファムネラの巣を見つけ出したものの、マコトが懸念していた通り、そこにいたミネ子はぼろぼろの姿だった…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5a1d0ad-8ea7-4550-8397-6d886bffc588.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11260e0c-899f-4e10-8c4c-5895229fc294', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 10, '100057409', '企業戦士', 'ミネ子のおかげでキラクリ集めは順調! 予定よりもはやく女神様が呼び出せそうと盛り上がる一同。そんな中、社員たちの策略によってミナトとユトリアはふたりきりのダンジョン攻略へ行くことになる。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f745d600-f342-4342-9aa2-f8db59b50ce3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('acab7df6-4bc3-4e1e-84c4-70df59e7b4ed', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 11, '100058172', '商機到来', '地面を割って突如出現した新たなゲート。膨大なキラクリを求め、キボウ･サイエッジ･インペリアルの3社が一堂に会するダンジョンで、遂に明かされるミナトの「知られたくない過去」とは何なのか。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/964c1af1-3a90-405a-a3dd-f028af13c70c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc2a9810-f509-4342-8525-d87451dac2b1', '73cd75a7-5b8b-4846-a4d3-1c22dbef6a5f', 12, '100058915', '経営理念', '【シーズン1 最終話】社長の過去を知ったことで、より絆を深めたキボウカンパニー。ミナトの指揮のもと、最悪な変異を遂げたマジューとの戦いに挑む。無事にキラクリを手にして、ミナトは父のもとへ辿り着けるのか…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb313e92-20e3-4d72-8cb2-6be1a290b5dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('82a69c79-0329-498b-8245-d69ade8a369e', '邪神ちゃんドロップキック', '', 'hulu', 'dropkick-on-my-devil', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71548973-13ad-40a9-92b9-cbb9fe9bc868.jpg?w=331&h=447&p=t', 'hulu', 2018, 2, 1, 'FINISHED', NULL, 100714, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a0201ced-498b-44b1-8594-2a56cabd1dc9', '82a69c79-0329-498b-8245-d69ade8a369e', 'hulu-dropkick-on-my-devil-s1', '第3期：邪神ちゃんドロップキックX', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b35a62c5-6329-4ef7-afd9-afea90a26d97.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fd0f65e-f3c5-4fb6-99fc-5225b70567ec', 'a0201ced-498b-44b1-8594-2a56cabd1dc9', 12, '100123547', 'ドロップキックは永遠に', '【最終話】ついにアトレとエキュートは、ゆりねの居場所を突き止めた。ヴァンパイア族だと名乗る2人は、ゆりねを自分たちの仲間にすべく、あの手この手で勧誘する。ゆりねがヴァンパイア族になり不死となったら、魔界に戻ることができなくなってしまう。そう思って焦った邪神ちゃんは…。そして、ある日の邪神ちゃんは、「魔貴族の誇り」を取り戻すことを決意する。本気の筋トレと、食事制限に励む邪神ちゃんを待ち受けていた事態とは…。', '2022/09/21 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b35a62c5-6329-4ef7-afd9-afea90a26d97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a454c774-dece-4c2a-8d25-0e11407a5b18', '灼眼のシャナ', '', 'hulu', 'shakugan-no-shana', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba87ab08-128d-4283-afea-38611e99b381.jpg?w=331&h=447&p=t', 'hulu', 2005, 3, 1, 'FINISHED', NULL, 355, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 'a454c774-dece-4c2a-8d25-0e11407a5b18', 'hulu-shakugan-no-shana-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03916dfa-3801-4875-b88c-bf90105c5088.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cce02de2-6721-45f9-880f-a497be901333', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 1, '100048692', '全ての終わり、一つの始まり', '坂井悠二の高校生活は、ずっと続く日常になるはずだった。だが、悠二は見てしまった。学校の帰り道、商店街の風景が止まり、人々が燃え、その炎をマネキンと巨大な人形が吸い込んでいく、あまりにも異様な景色を。大太刀を振るう、炎髪と灼眼の少女を。それは、悠二の高校生活に終止符を打つに十分な事件だった。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03916dfa-3801-4875-b88c-bf90105c5088.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ac6933e-f5cc-4b2b-8397-4c8aa17876e6', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 2, '100048693', '灯る炎', '悠二は死んでいた。今の彼は、紅世の徒に存在を喰われた後の残りかす。残りわずかな時間で、誰にも気付かれず消え去っていく灯火。人間には見えるはずのないそれを、灼眼の少女はトーチと呼んだ。だが、悠二には見えた。そして、クラスで机を並べているクラスメイト･平井ゆかりの中にもトーチがあった。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72db98ac-9abb-4756-9e96-3a4bf3611d7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1afba138-adbe-40b2-91d6-4bdad18c821b', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 3, '100048694', 'トーチとフレイムヘイズ', '平井ゆかりは死んでしまった。正確にはトーチの火が消えたのだが、悠二にとってそれは死と同じ意味を持っていた。その中、悠二は灼眼の少女に名前を付ける。「君はシャナ、もうただのフレイムヘイズじゃない」。だが、その翌日、クラスメイトが過去の存在も消え失せたはずの平井ゆかりを覚えていた。彼女はそこにいた…。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/634901d1-ec92-49ce-96ad-2af76e6911bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7b600bb-db8e-4e70-883f-2cbc3877c868', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 4, '100048695', '惑いのフレイムヘイズ', 'シャナは悠二の家にいた。その身に宝具を納めた“ミステス”である悠二を、頻繁に事件を起こしているフリアグネから守るため。悠二を囮にフリアグネを狩るために。だが、紅世の徒を追う新たなフレイムヘイズ･マージョリーと彼女に力を与えている紅世の王･マルコシアスが現れた。今、フレイムヘイズ同士の戦いが始まる。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0aa1b9be-2a4d-411a-a4b9-03e81f9d17ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71606dc3-85b1-43ae-88e2-2bcd171e64fe', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 5, '100048696', 'それぞれの想い', 'フリアグネは気付いた。自らの計画のため配置したトーチが徐々に消えて行くことを。フレイムヘイズではない何者かがこの街にいることを。そして、その者を狩るため力を使った時、マージョリーと接触する。一方、シャナと離れてクラスメイトの一美と出掛けた美術展で、悠二は紅世の徒“屍拾い”ラミーと会話をしていた。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5bbffbf-8f83-429b-8487-039fc603ef63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3db39ba6-a31f-44e0-9273-832fea37e5bc', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 6, '100048697', '交錯･発動･対決', 'シャナは自分の気持ちに苛立っていた。ただのトーチである悠二の存在が、その要因なのか。その苛立ちが頂点に達した時、フリアグネの計画が動き出した。それに気付き、戦いの場へ急ぐシャナ。奴の自在式を止めなくては、この街は崩壊する。残された悠二の中で、ラミーの言葉がリフレインする。そして悠二は決断する。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ac59d3a-b43a-430a-918c-2e5919be6d37.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ae897d7-ff40-4a0b-b803-009f3a27ec1a', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 7, '100048698', '二人のフレイムヘイズ', '「シャナと一緒に戦う」と悠二は言った。共に戦うために鍛えてもらおうと自ら申し出た、それが認められただけではない。シャナにとって、悠二はただのトーチではなくなったのだ。だが、そのきっかけを与えてくれたラミーは、マージョリーの手に落ちようとしていた。その原動力は紅世の徒への過剰なまでの復讐心だった。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6835d180-2def-4c9f-b4fe-3318e9fe20fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('522476bd-30ad-4bc1-b91b-04a1e32d0b2a', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 8, '100048699', '麗しのゴブレット', 'マージョリーは戦闘狂と化していた。群青の炎を散らすトーガをまとい、紅世の徒の討滅を実行するために。だが、その目前に立ち塞がった少女は言う、自分たちの使命はこの世と紅世のバランスを守ることだと。トーガを分裂させシャナを囲むマージョリー。だが、悠二を得て、シャナは変わっていた。二人の戦いの結末は…。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/005a982e-af03-4d35-a707-99b2fb229da5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e34b231-23a5-4b9d-bae6-b71b6617643e', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 9, '100048700', '恋と欲望のプールサイド', '太陽が容赦なく照りつける日、クラスメイトの池が持ってきた「御崎ウォーターランド」の招待券。オープンしたばかりの話題の巨大屋内プールに、誰もが喜んだ。だから、その場で日曜日に一緒に行こうと盛り上がった。それは悠二も同じだった。だが、そこには戦いが待っていた。シャナと一美が、プールで思いをぶつける。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e2d4f60-4eef-40dd-8ec4-25b26b564f59.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04b184ef-9d2f-4adb-b094-30a24a8b580e', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 10, '100048701', '絡まる想い', '悠二にとって、それは日常になりつつあった。「強くなり、シャナと共に戦いたい」。だからこそ、行っていた日々の鍛錬。一方、シャナの思いはより強くなっていた。「重要なのは悠二が強くなること。一緒に戦うこと」。今、二つの思いは、互いの影すら見失おうとしていた。燐子が現れたのは、そんな時だった。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a5c05df-1ad1-4448-bbfd-d2bc66fac1cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8102b711-f909-41e0-b6b6-97d78bbbf62d', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 11, '100048702', '悠二とシャナとキス', 'シャナは悠二の力を必要とし、悠二はシャナに必要とされることで自信を得ていた。以前とは違う間柄へ変わりつつある二人。だが、アラストールはそこに一つの問題を見出していた。シャナに対する悠二の有り様をどこまで許容するか。そして、悠二の母･千草の存在。満を持したアラストールは、千草との直接対決を決意する。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c53fe5a2-c68b-4e50-aa65-d7cfadf6ec59.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('549dc72f-2b4a-4b6f-bc34-e278a678b27c', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 12, '100048703', 'ゆりかごに花は咲いて', '悠二は池に、シャナは一美に問いつめられた。自分の気持ちから逃げることが、人の好意を無心で受けることが、他の人を苦しめているのだろうか。しかし、二人にはそれ以上に心を向けなければならないことがあった。紅世の徒の討滅。そんな時、この街に新たな徒が現れた。彼らの狙いはシャナの持つ「贄殿遮那」だった。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77432c12-891d-4244-99af-6e7c8bf5f759.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7076bfdb-15ab-4aeb-b770-54a82b633eaf', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 13, '100048704', '校舎裏の宣戦布告', '街は山吹色に染められていた。「贄殿遮那」を狙うソラトとティリエルが操る巨大な植物の花びらが空を舞っている。シャナの大太刀は、植物の蔦を切り、ソラトを蒸発させる。だが、それは一瞬でしかなかった。前もって仕掛けられていた自在法のためか、ソラトの再生は異常に早い。やがてシャナは捕らえられてしまう。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bbdd2c04-33cc-4e98-afc6-1838db65b89c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d76bf7e8-2ed0-499b-a2e1-38470ff9c7db', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 14, '100048705', '偉大なる者', 'この世からも紅世からも見えない場所･天道宮。そこにはアラストールと、シャナの生活面を世話するヴィルヘルミナ、そしてシャナがシロと呼ぶ鍛錬の相手。限られた人物が、理想のフレイムヘイズを生み出すため、十分な時間を掛けシャナを育てていた。そして、その日が来た。いや、予想より早くその日が来てしまった。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1538fb6-bd3c-437c-a6ce-23a2dd875d81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebcd0105-aa35-4d5e-b211-089e5eef6cf0', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 15, '100048706', '炎の生まれた日', 'シャナの前に、一人の徒が現れていた。新たなフレイムヘイズ、新たな炎髪灼眼の誕生を阻止するため、現れたその男の名はウィネ。徒を天道宮へ招いてしまった責に動揺するシャナに、ヴィルヘルミナは言う「この生活は不要になった」「もう大丈夫」だと。それは、新たな道、フレイムヘイズへの扉が開かれた瞬間だった。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/efc14066-839d-407f-ad95-bb0bbcf5ecf2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22a8d30b-ef5a-4532-a26b-a8c23711c6c8', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 16, '100048707', '炎髪灼眼の討ち手', '炎に照らされ、一人のフレイムヘイズが生まれた。長い炎髪が揺れ、鋭い灼眼が煌めく。長らく待ち望んでいた契約は達成された。だが、彼女がこの世に慣れるまでの期間を邪魔されないためにも、天道宮に踏み込んだ紅世の徒を逃すわけにはいかない。ヴィルヘルミナとシロは新たな決意を胸にその一歩を踏み出す。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/310be5b5-6190-4a32-9935-60544ab9e377.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d95e583-1ea4-4f62-ae0f-bca89c39dc1e', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 17, '100048708', '新たなる序章', '毎日のように吉田一美の弁当を食べている悠二が嫌だったシャナ。そのため、千草に料理を教わるシャナだったが、そうそう上手くなるはずもない。そこで千草は、気分を変えさせようとミサゴ祭へ行くよう提案する。一方、そんなシャナの気持ちを知らない悠二は、祭に一緒に行きたいという一美の誘いを受けてしまうが…。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae3b219a-efa4-4cba-bd5d-06c6c34f9053.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f45c473-c2d3-4552-a4b3-21675d7c3fb8', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 18, '100048709', '砕ける願い', '吉田一美は、世界の本当の姿を見てしまった。カムシンから手渡された片眼鏡の宝具「ジェタトゥーラ」。それを覗くことでトーチの存在を目の当たりにした一美は、ある心配を抱く。「…坂井くんは?」。そして、ミサゴ祭当日。各々の思いと決意を胸に神社へと集まる面々。だがその時、何者かが配した自在式が動き出した。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/419e5330-1d13-4442-b997-23130dd32620.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56ea0996-9a32-48e8-a3eb-79c405e98772', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 19, '100048710', '戦いの中で', 'シャナは吉田一美に告げた「私はフレイムヘイズ」だと。人々を襲う紅世の徒という化け物、悠二がトーチだったこと、そしてシャナが違う世界の存在だったこと…。一度に押し寄せた非日常の荒波に、一美は混乱した。一方、悠二は封絶の中で動く佐藤に出会い、自分が“ミステス”であることを知られてしまう。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b9932ea-dc1f-4aa2-8870-8f4c7d136e46.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b522678-82c8-47bb-98de-52c3eaec9b19', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 20, '100048711', '非情のヴィルヘルミナ', '悠二の心が自分と共にいないことに気付き、戸惑うシャナ。その時、フレイムヘイズのヴィルヘルミナが現れた。フレイムヘイズになる前の自分を知り、フレイムヘイズになろうとした自分を知る存在に、シャナは暫しの安息を得る。だが、ヴィルヘルミナの目的は、「零時迷子」を徒に渡さないための策を実行することだった。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1819f51f-62f7-4d28-8d81-a7f90e272484.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fd1eba1-b071-43c5-a10b-eb4efa834610', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 21, '100048712', '遠ざかる想い', '自分を狙う徒から、大切な人々を守るために街を出ることを決意した悠二。だが、シャナはそれを承知してはくれなかった。シャナが悠二に求めるものは、そんなものではなかったのだ。各々の思いがゆっくりと離れて行く中、祭で使われた飾りに火が付けられる。だがその時、その上空に再び自在式が浮び上がる。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59bd0559-8656-4ddf-b310-5c221a4daa31.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b3445c0-c17a-4c35-8967-8ac4263d7b33', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 22, '100048713', '揺らぐ炎', '悠二がシュドナイにさらわれてしまった。連れて行かれた先は、御崎市に現れた［バル･マスケ］の城砦･星黎殿。［バル･マスケ］は悠二を、「零時迷子」を使って何をしようというのか。ベルペオルの口から出た「存在の泉」とは何か。一方、佐藤と田中、そして一美は、悠二を助けるためにはどうすればいいかを考えていた。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97d8dc3e-eb92-4a5c-8cf7-58cbe296ad37.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24747292-65c4-4d4b-ad41-490d63ead367', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 23, '100048714', '星黎殿の戦い', 'シャナは星黎殿へ突入した。だがそこには、教授と呼ばれる紅世の王“探耽求究”によって罠が仕掛けられていた。その罠に捕らわれ、シャナとヴィルヘルミナの身体から抜けて行く存在の力。その一方、「零時迷子」によって生み出され、星黎殿から溢れ落ちる存在の力は御崎市を満たし、これまでにない現象を見せ始めていた。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/785d68d8-84e1-4b30-92e4-b260f25760b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5673faca-7b57-4861-b9ab-aca22d9a0aa3', '73d5b71f-dcbe-4cfe-a983-4bfc58654ffa', 24, '100048715', '紅蓮の想い', '【第1期 最終話】幾本もの光の柱が立ち並んだ御崎市。その上空では、いつ終わるとも言えぬ戦いが繰り広げられていた。その根幹にある「零時迷子」=悠二と彼を取り込んだヘカテーを前に、シャナは言う。「悠二を返してもらう」。それは、ただのフレイムヘイズではなく炎髪灼眼のシャナの決意だった。シャナとそして悠二の戦いの結末は…。', '2020/02/20 00:00:00', 1482, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ac4f042-852d-4e05-8309-7f916876232b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6f14c2ab-3795-4610-ad09-36cd1a79c9af', '灼眼のシャナⅡ(Second)', '', 'hulu', 'shakugan-no-shana-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/618853ee-6464-448c-8ece-d2db023dfb25.jpg?w=331&h=447&p=t', 'hulu', 2007, 3, 1, 'FINISHED', NULL, 2787, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4b24a210-5a04-4dff-9d25-b85935cf4f34', '6f14c2ab-3795-4610-ad09-36cd1a79c9af', 'hulu-shakugan-no-shana-2-s1', '第2期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56c707db-1e84-4330-9e22-1b0149e7b05a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41044d8a-a3e0-4264-a123-78511deda46a', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 1, '100048716', '再びの刻', '二学期が始まり、シャナと共に闘った夏祭りの夜が嘘だったかのような風景に、悠二は嬉しささえ感じていた。だが、そんな風景に違和感をおぼえ始める悠二。シャナが英語教師に意見するのも、一美が持って来てくれた手作りのお弁当も、まったく同じことを前にも経験しているのではないか? それは確信に至り、悠二は…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56c707db-1e84-4330-9e22-1b0149e7b05a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d7e7de8-2a5c-4991-8396-3f776bebbad3', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 2, '100048717', '全ての序章', '夢を操る“紅世の徒”、“戯睡郷”メア。悠二の活躍でその自在法は破られ、シャナの一太刀で“徒”はあっけなく倒れたかに見えた。だが、また再び夢の中にいることに気づいた悠二たちの前に本当の姿を現すメア。その力によって現実化する強大な敵。夢を覚ますためのキーはどこにあるのか。そしてメアの狙いとは…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f07f5e67-15cc-4bbd-ba20-f72b5e333771.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb8edaa3-ad7b-4788-a294-7577732663ca', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 3, '100048718', '疑惑の転校生', '悠二のクラスに来た転校生･近衛史菜。彼女は［バル･マスケ］の幹部･“頂の座”ヘカテーに似ているため、とっさに封絶をするシャナ。その封絶内で動けない史菜を“徒”とは思えず、シャナたちは様子を見ることにする。そんな中、史菜に優しくするクラスメイトたちだったが、シャナは疑いを解かずにある計画を準備して…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8727dd6e-68c6-4e05-86c7-502bb9b0ddd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c583b2e7-96ef-41e7-98c5-ea0925902a30', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 4, '100048719', '憂いの少女たち', '学校生活に慣れ、悠二たちと一緒に昼食を取るようになった史菜。だが、彼女への疑惑が消え去ったわけではなかった。そのため、マージョリーとヴィルヘルミナは［バル･マスケ］の動きを収集するなど、わずかな不安要素も見逃さない気構えでいた。そんな中、悠二はみなを誘って新規オープンしたデカ盛りの店に向かうが…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19d629d3-43ec-4bea-a0f7-d20fb1f90cc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa86b811-b6ac-4f8a-a210-e08415cc6b33', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 5, '100048720', '家族の食卓', 'ヴィルヘルミナによる厳しい鍛錬で、新たな力を身に付けようとしていた悠二。一方、その鍛錬を休んだシャナは、理由としてヴィルヘルミナに「都合が悪い」とだけ伝えていた。だが、本当の理由はシャナがとある気持ちで苛立っていたからだった。そんなシャナの苛立ちを知ってか知らずか、悠二は翌日、史菜の屋敷に行き…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4def6b6c-8d35-47ac-be1d-2f8a62b98faf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8406e98-6768-4859-8839-ae1720225377', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 6, '100048721', '試練の前夜', '明日から行われるテストの対策として、緒方の発案により佐藤の家で勉強会を開いた悠二たち。しかし、シャナは史菜が当然のように悠二の隣に座っているのが気に食わない。一方、みんなのために夕食を作っていた一美も、史菜に優しすぎる悠二の態度に寂しさを感じずにはいられなかった。だが、そこにマージョリーが現れ…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9043ec9d-1357-47b8-a592-324fa8ab6400.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c875e6f-1160-46ec-ba43-f060220be357', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 7, '100048722', '池速人、栄光の日', '史菜を初めての遊園地へ誘う悠二たち。その幹事は「いい思い出は、いい段取りから生まれる」が信条の池速人。段取りさせたら池のことを御崎高一だと誰もが思っていた。そこで今回の段取りを成功させて、リーダーシップの取れる頼りになる男として、彼は一美に少しでもアピールしようと決意を新たにしていたが…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd8a8cfe-400f-4bd4-acf9-4e744e02f4f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6a791d8-b9f6-41dd-8c35-298cbd32e5e4', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 8, '100048723', '過去への扉', '鍛錬の成果により、次の段階へ一歩踏み出そうとしていた悠二。一方、マージョリーの力になりたいと思った佐藤は、「俺を、鍛えて下さい」と彼女に懇願する。だが、そんな佐藤に彼女は「アンタ、死ぬわよ」と冷たく言い放ち、“千変”シュドナイと繰り広げた戦いと一人のフレイムヘイズとの出会いを語り始めて…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a9376ec-84da-465c-afad-bc6809749dc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a7d12c4-41f9-4ae0-992a-fde9efc7b9f8', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 9, '100048724', '哀しみのマイルストーン', 'エンパイアーステートビルで、“紅世の徒”の“穿徹の洞”アナベルグと対峙していたマージョリー。そこへ現れたシュドナイが彼女のトーガを切り裂く。そんな彼女の危機に、半人前のフレイムヘイズ“魑勢の牽き手”ユーリィが駆けつける…。自らの過去を佐藤たちに語り出したマージョリーだったが、ふいに話をやめて…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f94aea6c-7cbc-46e4-b849-9802e1b3bc79.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71c7694d-c4b2-47ea-ab8b-16ae77bbe1c4', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 10, '100048725', '帰ってきた男', 'ついに自在法の構築に成功した悠二。だが、シャナとアラストールから祝いの言葉はなく、二人は封絶を染める炎から目を離せずにいた。その炎の色は「銀色」をしていた…。そして、学園祭まで三週間を切ったある日、そのパレードの代表者にシャナたち四人が選ばれる。その夕刻、シャナは自分を尾行する怪しい影に気付き…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aec8f72e-80a1-425a-b696-795339790a4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('205a50de-36ad-4612-84d0-99b80664f927', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 11, '100048726', '約束の二人', '御崎高校学園祭「清秋祭」まで後三日。悠二たちは、その準備に忙しく、学校に泊り込んで作業を行なっていた。その中で、一美は自分自身に正直でいるための決意を新たにし、シャナもまた己の心に真正面から向き合おうとしていた…。そしてヴィルヘルミナが帰ってきたその夜、悠二に新たな試練が突きつけられる。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f7fed41-ae57-40fa-821d-622128d91516.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd95041d-a33c-4797-9330-404c9d63727c', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 12, '100048727', '清秋祭始まる', '「清秋祭」初日、悠二の両親やヴィルヘルミナ、そしてヴィルヘルミナに無理矢理連れてこられたマージョリーらが見守る中、御崎高校の生徒たちによる、地域の商店街を練り歩く仮装パレードが行われていた。その楽しそうな雰囲気を横目に、ヴィルヘルミナはマージョリーに、悠二に起きている異変を相談しようとしていた。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c74ef786-070b-47f9-94f4-3eac0ce78ab3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d30a069b-806f-4e28-a732-9c2c287adfec', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 13, '100048728', '収束、そして兆し', '琥珀色をまとう竜巻の中心に捕らえられた悠二。だが、その中心から新たな色の炎が走り封絶が張られた刹那、マージョリーの表情が一変し、彼女はその中心へと飛ぶ。一方、シャナは悠二を狙う“徒”と対峙していた。琥珀色の風を操るその者は、零時迷子を作ったエンゲージリンクの一人である“彩飄”フィレスだった…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49b171dc-1abd-4504-91f5-c1744afde42f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a15f994-9adc-4f3a-8343-31f445e23fea', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 14, '100048729', '永遠の恋人', 'フィレスが求める『約束の二人 (エンゲージ･リンク)』の片割れであるヨーハン。そして、マージョリーが狙う銀。それが悠二の中にあるのかを知るため、二人に休戦と協力を約束させたシャナたち。その夜、衰弱したフィレスに力を分け与えようとする悠二。その時、展開されるマージョリーの自在法。彼女たちの目的とは…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d669c56a-dfef-4f51-a0d8-29930e5a3c95.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e481631c-4559-4fb4-b1bb-e3ab51a10174', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 15, '100048730', '覚醒', '意識だけを宿した傀儡を操る自在法「風の転輪」によって、マージョリーやシャナ、そしてかつての盟友のヴィルへルミナまでも利用したフィレス。彼女は、悠二へ…愛すべきヨーハンへと手を伸ばす。だがその時、悠二の胸から現れた銀の炎に包まれた腕。その事態に干渉する新たな存在がいた。果たして、その存在とは…?', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ef19662-b87d-4ad1-a8c7-4b6c8d08e3ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82382218-1131-478d-a0bc-4cdb2c37b0fd', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 16, '100048731', 'つきせぬ想い', '清秋祭が終わりを告げた時、そこに近衛史菜の姿はなかった。ヘカテーの偽りの器だった彼女はヘカテーと同化され、この数ヶ月を一緒に過ごしたクラスメイトたちの記憶からも彼女の存在が失われてしまった。その違和感に戸惑いながらも、一美はある決意をする。そして、バル･マスケの新たな策略が見え始める…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b2c8add-dd41-4693-b6f8-2cf04f761e85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ced3dc07-0654-4bbb-b610-6e996a6d5ad6', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 17, '100048732', 'それぞれの道', 'ヘカテーが打った刻印で、逃げも隠れもできない悠二が望んだ新たな鍛錬。一方、共に「マージョリーに付いて行く」と決意した田中に、佐藤は自分の意思をぶつけていた。封絶内での戦闘だったために緒方は既に元通りになったとはいうものの、マージョリーの手により彼女を失った事実が、田中の心を大きく揺るがしていて…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe4cd8a9-e166-41a6-886c-7e9d96979972.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f13216dc-644e-40a6-91a8-d5e8210259c6', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 18, '100048733', '錯綜の悠二', '悠二が封絶で見せた“銀”の炎。果たして、“銀”の正体とは? そして、何故その力が彼の中にあるのか? さまざまな疑問と疑惑が交錯する中、マージョリーの指導で悠二の自在師としての鍛錬が始まった。その鍛錬は、悠二自身の頑張りもあり順調に進んで行く。だが、その頑張りに、マージョリーは違和感を感じていた…。', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4dea12b-2ad8-448e-bf24-23b0ff653fa6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92305f62-e0be-4438-850c-cdc819353a79', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 19, '100048734', '言えなかったこと', '五つの身体を持つ“紅世の徒”の“聚散の丁”ザロービに声を掛けられた悠二。その“徒”に近くの住宅地で暮らす人々を人質に取られてしまい、悠二は河川敷、繁華街、そして駅前のアーケードへと為す術もなく進む。果たして、人の混み合う場所へ移動する敵の意図は何か? そして、数少ない情報から導き出した悠二の答えとは?', '2020/02/27 00:00:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c07250ad-d301-470f-914f-884b459f288e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a66d6c07-a5fe-441a-9501-a96f00952dfe', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 20, '100048735', '茜色の死闘', 'ザロービの計略を推測し、自らの力で最前の策を成し遂げた悠二の元にシャナとヴィルへルミナが合流した。だが、安心する間もなく新たな攻撃が三人を襲う。無数の刃がシャナの体を刻み、茜色の炎がヴィルへルミナと悠二を飲み込む。そして、かろうじて立ち上がった悠二の胸に、“壊刃”サブラクの剣が突きつけられて…。', '2020/02/27 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1d51814-1557-40ab-b4c4-5fecbb20dd2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93012cf7-817b-4fb5-8e87-dbc5dc0b3d5e', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 21, '100048736', '合わさる力', '時と共に傷を広げる自在法『スティグマ』。そのため他のフレイムヘイズは動けないと思っていたサブラクは、シャナの登場に驚愕する。ヴィルへルミナがひとりサブラクの相手をしている間、その正体に着目し、結論を得る悠二。そして、3人のフレイムヘイズと1人のミステス、佐藤と一美の2人の人間が加わった作戦が始まる。', '2020/02/27 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ced76a65-0582-4b6f-af2e-5b200ab1e332.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f8613085-1fa1-43ce-81d2-e791f2e51af6', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 22, '100048737', 'クリスマス･イヴ', 'クリスマスの準備に街が賑わう頃、父の貫太郎から悠二に告げられた吉報。その事実が「この世界を守りたい」という彼の思いを後押しする。一方、自分の気持ちにケリをつけるため、同じ思いを抱くシャナと待ち合わせをした一美は、悠二にどちらかを選んでもらおうと考えていた。そんな一美とシャナが選んだ方法とは?', '2020/02/27 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/177f43dc-c054-431d-9689-3a56053f9501.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03503c56-1217-4a50-a9d8-0ee2451bf9b8', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 23, '100048738', '危難の胎動', '悠二はシャナと一美に指定された場所へ向かっていた。だがその直前、ヘカテーによって零時迷子が奪われてしまう。なんらかの異変に気付くシャナ。だが、悠二が捕われた“殻”の中に入る術はない。その時、シャナの元へ一美が駆けつける。', '2020/02/27 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbc4f809-0c7a-4553-9da2-b26f286291bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a26eb262-b44b-4c01-ad58-ff2026279644', '4b24a210-5a04-4dff-9d25-b85935cf4f34', 24, '100048739', '守るべきもの', '【第2期 最終話】バル･マスケの狙いは、紅世でしか生まれ得ない“徒”をこの世で生み出すことだった。その狂気の計画を止めるため動き出すシャナたち。そんなシャナたちの反撃を感じた悠二は、「零時迷子」を抜かれた自分に限界が迫りつつあることを知りながらも走り続けていた。守るべきもののために「僕は僕の戦いをする」と…。', '2020/02/27 00:00:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8cb6b5d-f250-4a88-970d-dfc2473a6d16.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('38678df6-7de8-4197-b5e1-7970b809067f', '灼眼のシャナ S', '', 'hulu', 'shakugan-no-shana-s', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/571ce89b-7d03-4282-9395-ea88c585b9e0.jpg?w=331&h=447&p=t', 'hulu', 2009, 3, 1, 'FINISHED', NULL, 6572, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('04813e44-4d13-40bf-b3dd-802ae25a0826', '38678df6-7de8-4197-b5e1-7970b809067f', 'hulu-shakugan-no-shana-s-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50320d33-4aa9-4391-a5d9-11c6dfe274ec.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fbc8694-9807-4c6b-80e4-d8d50d817c21', '04813e44-4d13-40bf-b3dd-802ae25a0826', 1, '100251659', 'リシャッフル', '“狩人”フリアグネが残した宝具の選別中、それは起きた。筒状の宝具“リシャッフル”を覗いた悠二と、その向こう側に見えたシャナの目があった途端、二人の心と身体が入れ替わってしまったのだ。とまどう二人にアラストールは言う。「余人にこの状態にあることを知られてはならん!」何故、仲間にさえ知られてはいけないのか。アラストールの言葉の真意とは…。真夏の御崎市に、シャナと悠二の汗が散る!', '2026/02/27 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50320d33-4aa9-4391-a5d9-11c6dfe274ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63cb2dac-8d73-46f1-b9fc-1153719fb8ad', '04813e44-4d13-40bf-b3dd-802ae25a0826', 2, '100251660', 'ドミサイル', 'ここ最近、シャナの帰宅時刻が遅い。それは些細なことかもしれない。だが、“紅世の徒”と戦うフレイムヘイズにとって、その緩みが命取りになりかねない。シャナの行動に危機感を抱いたヴィルヘルミナは、悠二を不本意ながらも帯同させ、その動向を探り始める。だがその尾行中、シャナの気配が消えた。まさか、これは…。不安を高めるヴィルヘルミナの眼前にマージョリーが現れる!', '2026/02/27 00:00:00', 1748, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac7eccb7-82a5-4e32-b531-c8fd2de1562e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6aba9f7f-8c84-4860-b336-eec316c25b3f', '04813e44-4d13-40bf-b3dd-802ae25a0826', 3, '100251661', 'オーバーチュア 前編', '十数年前に行方不明になった男性が突如発見された。その存在が“徒”に喰われていたと確信した少女――『贄殿遮那のフレイムヘイズ』は、“徒”を討伐するため情報の発信地となった街へ訪れる。存在を喰われた人間がここまで目立つことはない。また、フレイムヘイズが駆け付けるのはわかっているのに、その“徒”はまだここに留まっている。それは何故か……。人の繋がりのなかで、彼女の探索が始まる。', '2026/02/27 00:00:00', 1659, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4de727a6-d09b-4867-b541-a2dcf66bc33c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b93ae61-968b-42ad-97e7-1d06a853c6db', '04813e44-4d13-40bf-b3dd-802ae25a0826', 4, '100251662', 'オーバーチュア 後編', '【最終話】トーチとなった少女･大上準子の存在に割り込み、人を喰らった“徒”の痕跡を探していた『贄殿遮那のフレイムヘイズ』は、準子の記憶を巡るなか、ついに“徒”の明確な痕跡を発見する。準子の存在だけを喰らい、同じ場所にいた濱口幸雄を見逃した“紅世の徒”ウコバクの欲望とは何か。そして、戦いの場でウコバクの周囲に浮かぶ無数のシャボン玉、そのなかに見える人影が意味するものとは……。', '2026/02/27 00:00:00', 1712, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9852e056-c9a5-4452-93bf-950d05a6bdc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('fb524dc7-9faa-47f8-a7fd-1802e0c7ed9d', '灼熱カバディ', '', 'hulu', 'burning-kabaddi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c8218e59-2d31-48fb-a1bb-5d0d5cc17144.jpg?w=331&h=447&p=t', 'hulu', 2021, 1, 1, 'FINISHED', NULL, 120859, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f4681213-a38f-429d-8904-9784e0d3e473', 'fb524dc7-9faa-47f8-a7fd-1802e0c7ed9d', 'hulu-burning-kabaddi-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b72978f0-b490-4824-818c-c222b53049fe.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e46ccab-72b0-4e12-bba0-d5665f33bd81', 'f4681213-a38f-429d-8904-9784e0d3e473', 1, '100078448', 'カバディってなんだよ', '宵越竜哉はサッカーの有名な選手だった。しかし、高校入学を機にスポーツと縁を切ってしまう。そんな彼をカバディ部に勧誘しようと畦道相馬が部屋に押しかけ、見学だけでもと強引に連れていく。アホ臭いネタスポーツだと思っていた宵越だったが、副部長である井浦慶の計略にハマり半ば強引にカバディを体験することに……。', '2021/04/03 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b72978f0-b490-4824-818c-c222b53049fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bbe081b6-fde6-4dd1-88c3-bd6610fc982f', 'f4681213-a38f-429d-8904-9784e0d3e473', 2, '100078449', '繋がる男たち', '守備 (アンティ) の練習はやりたくないと断る宵越。その理由とは守備同士が手を握るフォーメーション、通称『チェーン』。男同士で手を握りたくないと守備を拒むものの、攻撃の成功率はゼロ。だが、二年の水澄京平と伊達真司、そして井浦を観察したことで必勝法を思いついた宵越は攻撃でハットトリックを決めると宣言する。', '2021/04/10 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22745513-609e-4b85-9322-3e1c6453bac8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b08f78e-6e81-4e29-b434-c5d7e4c242e0', 'f4681213-a38f-429d-8904-9784e0d3e473', 3, '100078450', '灼熱の世界へ', '1年の宵越と畦道チーム、2年の水澄と伊達チームに分かれて練習試合を行うが1年チームは惨敗。2人の連携不足が敗因と考える宵越は、畦道と協力しなければいけないことにイラつく半面、勝つためには協力が必要だと暗号による連携プレイをひらめく。これを機に宵越達は秘密の特訓を開始。気合充分で2年チームへと挑む!', '2021/04/17 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf8e0ef0-97ce-4422-b929-48a8a0472a6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9be3e25-e6e9-4497-8749-bfd3ada8362b', 'f4681213-a38f-429d-8904-9784e0d3e473', 4, '100078451', '最強のレイダー', '宵越は『勝つ』感覚を掴もうと模索しながら練習するも、焦りが先行するばかり。見かねた井浦は秀でたポテンシャルを活かして“能京の獣”、最強の攻撃手 (レイダー) になれと助言する。後日、ランニングをしていた宵越は気配を全く感じさせない細身の男性とぶつかってしまう。病み上がりだというこの男の正体は……。', '2021/04/24 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/650d6ea0-78b3-4181-b507-b27e3cf4579a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91d43c0b-2403-4013-b9c7-ed317af6d0c1', 'f4681213-a38f-429d-8904-9784e0d3e473', 5, '100078452', '試合開始ィ!!!', '一緒に練習した仲間と勝ち上がりカバディで日本一になろうと王城は語る。そのためには一回試合をしておきたいと考え、世界組と呼ばれるトップ選手が在籍する高校と練習試合を組むことに。相手は王城の古い友人でありライバルの六弦歩、そしてエースレイダーの高谷煉を有する関東ベスト4の強豪校、奏和高校カバディ部だ。', '2021/05/01 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f28f1f0-b1a5-4a69-a7ca-e012b1a7aa98.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('98a21a91-abbb-4554-b97f-b83eef6d441e', 'f4681213-a38f-429d-8904-9784e0d3e473', 6, '100078453', '追撃×反撃', '宵越の攻撃成功で3点獲得。能京有利の流れを作れたかに思えたが、高谷の大量得点と六弦の完璧な守備によって逆転を許し、じわじわと点差をつけられてしまう。更に、高谷の意識がベンチの王城に向いていることで宵越のイライラはつのっていく。離される得点、畦道の負傷と精神的に弱る能京を救うのは、やはり……。', '2021/05/08 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93c3922b-fd6c-4d2c-802c-d31bcb50ec2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afea6615-1d37-4ac4-a081-3d676faaf58d', 'f4681213-a38f-429d-8904-9784e0d3e473', 7, '100078454', 'STRUGGLE', '後半戦開始。王城と高谷が激しい攻防を繰り広げ、能京は点差を4点まで縮める。しかし、井浦が次の攻撃は王城を出さないと言い出す。疲労の溜まった王城が怪我をしたら大会に出場できなくなってしまう。ここで能京の目標を終わらせないための決断だった。井浦の真意を理解した王城は、高谷を追い出す大役を宵越に託す。', '2021/05/15 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8478f842-b4e5-428b-a54e-193bead8a2c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5df8cf4d-44eb-4e71-b54b-a5b94b3f1e04', 'f4681213-a38f-429d-8904-9784e0d3e473', 8, '100078455', '入部希望', '一年生の伴伸賢がカバディ部へ入りたいと入部届を持ってくる。伴は髪型がリーゼントで目つきが悪く、それなのに声は極小という変わり者だ。しかも、彼に誘われたと言って同級生の関隆太と人見祐希も体育館を尋ねてきた。実はこの伴という男、小学2年生の時に宵越と出会っていたのだ。それは、とても暑い日のことで……。', '2021/05/22 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67f6cb38-b5ae-4dac-9e86-afbd7c9e4029.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e68c633c-c978-4d26-b3ae-68133f907991', 'f4681213-a38f-429d-8904-9784e0d3e473', 9, '100078456', '意地の勝負', '水澄は悩んでいた。新しい布陣の中、伊達とばかり守備を組んできたせいでアンティとしての立ち回りが分からなくなってしまったのだ。コイツがいなかった時、どうしてたっけ……入部したての水澄は初めての試合で挫折を味わった。もうみじめな思いはしたくない、そう考えて体格の良い伊達をカバディ部へ誘ったのだが……。', '2021/05/29 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b940f126-0321-4c5a-9f0c-7c857b65b437.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bce44eff-67eb-422c-9966-5671ca4ba428', 'f4681213-a38f-429d-8904-9784e0d3e473', 10, '100078457', 'エースだから', '王城の後輩だった佐倉学にライバル心を燃やす宵越。そして、師匠である王城を越えたい佐倉。いわば兄弟弟子の2人がコートの上で激突する。宵越はひそかに磨いていた新技を繰り出し、更なる成長を見せる。一方、佐倉も複雑な思いを胸に王城と対峙する。一進一退の攻防が続く中、思いもよらぬアクシデントが発生し……。', '2021/06/05 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/798c357d-0f6f-403f-b7ae-4ff450364058.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7652fe01-ee31-4ab2-acf0-cc1dd991a3c2', 'f4681213-a38f-429d-8904-9784e0d3e473', 11, '100078458', '目指す方向', '佐倉がエースとして覚醒し、一度の攻撃で信じられない大量得点をあげる。萎縮する能京。だが、宵越だけは違った。攻撃に出た宵越はこの場面を立て直すべく、一瞬の隙を狙って佐倉に新たな技を仕掛ける。「あの技は?!」と驚く一同。ところが、集中力を取り戻した佐倉によって帰還を阻まれ、遂に逆転されてしまう。', '2021/06/12 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99fdfa39-22c5-47ac-afa3-6afe4bfff78b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0af9b3f5-e3b2-4e89-9c79-e11cc428a24a', 'f4681213-a38f-429d-8904-9784e0d3e473', 12, '100078459', '全て出し尽くした先に', '【最終話】残り時間1分。紅葉に5点のリードを許す能京は王城を失い、疲労もピークに達していた。そんな中、宵越は攻撃の手を緩めず何とか2点取り返す。しかし、王城をコート内へ戻すことは叶わなかった。それでも諦めない能京は、水澄の活躍によって再び士気を高める。残り15秒。宵越に気合が入る。「今度は俺の番だ……」と。', '2021/06/19 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a60f417-0478-48bc-9725-5036b3e41aa1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('915bd543-a2b9-4d97-ae1c-b2f16ff9036b', '灼熱の卓球娘', '', 'hulu', 'scorching-ping-pong-girls', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/961b107f-23d5-4322-9f8c-32374e72b73a.jpg?w=331&h=447&p=t', 'hulu', 2016, 3, 1, 'FINISHED', NULL, 21715, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', '915bd543-a2b9-4d97-ae1c-b2f16ff9036b', 'hulu-scorching-ping-pong-girls-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bde8e5e-8219-4f97-bf36-8f46aea0abd5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3dbc00aa-aca8-41b1-b306-f72656aeef5f', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 1, '100107937', '…ドキドキするっ!', '中学卓球界では、9年連続全国大会優勝の凰堂学園が敗れるという大波乱が起きていた。群雄割拠の覇権争いが始まりつつある中、市立雀が原中学校卓球部のランキング1位に君臨するエース･上矢あがりは、その座を誰にも渡すまいと日々努力を重ねていた。しかし転校生･旋風こよりにより、そのランキングは大きく変動していく……。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bde8e5e-8219-4f97-bf36-8f46aea0abd5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9481714-2436-4b60-945c-43be8389be4f', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 2, '100107938', '譲れない場所', 'こよりは校内ランキング4位のムネムネとの試合を経て、部内随一のテクニックをもつ出雲ほくとや超攻撃型プレイヤーの天下ハナビといった、ランキング上位者との試合を次々に繰り広げる。こよりの実力が明らかになっていく中、あがりはこよりの台頭に当惑し、彼女に対してそっけない態度をとるようになってしまう……。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21037d7f-e952-4bb1-8ee3-72ae448fbd1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9b3940a-2c75-4def-bae3-2d91d1541aa1', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 3, '100107939', '好きっ!!', '「旋風さん。私と、勝負して」。ついに始まる、雀が原中学卓球部現エース･あがりと、転校生･こよりの試合。あがりは得意とするドライブ戦法でこよりを圧倒していく。勝利を確信するあがりだが、彼女が目にしたのは満面の笑みを浮かべながらラケットを振るうこよりの姿だった。次第に激しくなる二人のラリー。そしてついに決定的な一打が放たれた。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51d6ab9a-6455-48c6-98eb-8b9e93a4838e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cd88b48-3fea-4e1e-bc0a-cb052eae53db', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 4, '100107940', 'タイクツな卓球', '雀が原中学卓球部に誕生した二人のエース、こよりとあがり。校内ランキング上位を目まぐるしく入れ替えながら、お互いを更に高めあう二人の姿に勢いづく卓球部。そんな折、足の怪我で一時部活を離れていた部長･後手キルカが復帰することに。キルカは復帰早々、部員たちに自分との試合を申し渡す。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a18cb17c-ad17-43d5-88f9-ff5392b2666b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be9038ad-3317-41d1-8145-f36dc0a85b1d', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 5, '100107941', 'あなたとドキドキしたいから', '一見、飄々としてとらえどころのないキルカ。しかしその実力は部内随一のカットマンだった。怪我のハンディをものともせず、悠々と勝ち進んでいくキルカに闘志を燃やすあがり。全国大会出場の夢を込めた渾身のスマッシュがキルカに迫る。そんなあがりの覚悟に胸が高鳴るこよりは、もっとドキドキしたいと新たな決意を固める。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6827f09a-5031-4aaf-9f3f-f21d0fdd1408.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('907f9ec1-0f0d-4eeb-98ba-1659f1ff7339', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 6, '100107942', 'ともだち', 'ほくととハナビは小学校からの幼馴染。実家が卓球用具店を営むほくとは、ラケットのラバーを見極める目を持っていた。最近不調のこよりの原因も、ラバーの寿命によるものだという。そこで新しいラバーを得るため、こよりはほくとのお店でお手伝いをすることに。慣れない仕事に悪戦苦闘のこより。一方あがりも、そんなこよりが心配で……。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82fd750f-5ef1-48bb-8f6a-edb1a3633586.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b713dbaf-0885-4897-b5aa-75efb267f743', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 7, '100107943', '全国校の実力', '練習試合当日、もず山中学卓球部部長の座敷童石榴に迎えられた雀が原中学の部員たち。そこでこよりは、ほくとの卓球店で出会った少女･二重丸くるりと再会する。彼女は“東のドライブマン”と謳われる選手だった。こよりはくるりから「卓球をする理由」を問われ、答えられずに動揺してしまう。そして先鋒･ハナビと蠍田幸子との試合が始まろうとしていた。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c9666dc-503a-4079-b6b1-15fd6bfd426c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59c71867-90e9-48ad-8334-f964cc3b548f', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 8, '100107944', 'ダブルス', '善戦虚しく蠍田に敗れたハナビ。ほくとは必勝の決意を胸に由良木ゆらとの試合に臨むが、もず山の実力は伊達ではなかった。雀が原部員の期待を一身に背負って、キルカとムネムネがダブルスに挑む。対する鐘梨まゆう&羽無公子ペアは絶妙なコンビネーションを見せる。しかしムネムネは、キルカの足の具合を気遣うあまり、本気を出せないでいた……。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84462b38-7de8-49b0-b240-44dad322a3a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75eda738-2c87-4fa7-bfa9-2b1278df0aea', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 9, '100107945', '私には届かない', 'キルカとムネムネのダブルスの奮闘で、一勝をあげた雀が原。続く第四試合、もず山部長･石榴にあがりが挑む。自分も必ず勝利してこよりに繋げると意気込むあがりだったが、石榴の脅威の粘り強さの前に先制を許してしまう。焦燥感を募らせるあがりの瞳には、石榴の姿がまるで揺るがない巨木のように映っていた。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/064f0fa7-d0f4-4a68-a798-bdaa66204c9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab0d76c2-d110-4bc4-9731-2365937cf23d', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 10, '100107946', 'わたしの卓球', '辛くも石榴に勝利したあがり。その思いを受け継ぎ、こよりが最終戦に臨む。しかしくるりは必殺のカーブドライブでこよりを翻弄する。そんなくるりに、全力のドキドキで応えると力強く宣言するこより。両者譲らぬ激しい打ち合いのなか、雀が原中学ともず山中学の雌雄が決しようとしていた。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/633e864c-276e-4fa4-a91a-42adbebd05fa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dba5e138-1ecf-4865-a39a-3cf6788f5822', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 11, '100107947', '合宿', 'もず山との練習試合を終え、合宿を行うことになった雀が原中学卓球部の面々。あがりは石榴との試合から自分の課題に気づき、どこか浮かない表情を浮かべていた。そして出発の朝、あがりたちの前に元雀が原卓球部員の月ノ輪紅真深が現れる。意味深な言葉を残して去っていく紅真深にもやもやが募るあがり。合宿では各々の課題を克服すべく練習を行うことになるが…。', '2022/05/14 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a910474-d9cd-4bc6-b844-78b3baa16805.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76b33b37-76a5-4978-b77a-a74ac041a090', '4119ac95-16da-40e3-a3c4-ad3fcc22f5d7', 12, '100107948', 'ふたりでならどこまででも', '【最終話】卓球尽くしの集中合宿、あがりはこよりと共に新必殺技の特訓に励む。厳しい練習を終えた最終日の夜、部員全員巻き込んだ臨時ランキング戦が始まった! 練習試合、さらには合宿を通じて幾重にも成長した雀が原の部員たち。そして卓球の楽しさを再確認したこよりとあがりは、一緒に全国大会を目指すことを心に誓い合う。', '2022/05/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97fcce4f-d805-4d40-8087-78517eafa5a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c48cb2ba-db01-4ffe-a4de-74685c7ee545', '弱虫ペダル', '', 'hulu', 'yowamushi-pedal', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c3f8f2e-2c00-49be-a98c-e84a026fa1f3.jpg?w=331&h=447&p=t', 'hulu', 2013, 3, 1, 'FINISHED', NULL, 18179, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a2711bb4-278d-4677-a944-2a0fbf8e9363', 'c48cb2ba-db01-4ffe-a4de-74685c7ee545', 'hulu-yowamushi-pedal-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/30272047-3309-414f-ab3f-a700efc4321f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32a307a2-217a-494a-a605-946bf5e31e7f', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 1, '60440134', 'アキバにタダで行けるから', '千葉県総北高校に入学した小野田坂道は、大好きなアニメグッズを買う為に、毎週アキバまで、往復90kmの道のりをママチャリで通っていた。高校生になったらアニ研に入って友達を作ろうと思っていた坂道だが、なんとアニ研は人数が集まらず廃部になっていた。落胆する坂道の前に、ロードレーサーの今泉俊輔が現れて…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/30272047-3309-414f-ab3f-a700efc4321f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92b5a898-6cbe-4b08-9057-8ed422f51fd6', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 2, '60440109', '部員をふやすため', '高校近くの急な裏門坂を、鼻歌を歌いながらママチャリで登る坂道を見た今泉。その実力を確かめようと、坂道に自転車レースを申し出る。驚く坂道だが、今泉が負けたらアニ研に入るという条件を聞いて、勝負を受ける事に。話を聞きつけた寒咲幹達が見守る中、坂道と今泉の裏門坂自転車レースがスタートする!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7bcd2cb4-a59e-4bf7-858b-331f41d6d11f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('609962b8-d0e2-469d-9aa2-d4d14defa898', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 3, '60440119', '僕は友達いないから', 'ついに始まった坂道と今泉の裏門坂自転車レース。今泉にアニ研に入ってもらう為、懸命にペダルを回す坂道だが、後からスタートした今泉にあっさり抜かれてしまう。落胆する坂道は、通司の車で追いかけて来た幹にサドルの調節をしてもらい、再び今泉を追う。必死の追い上げで、ついに今泉に追いつく坂道だが…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d2c68bbd-a653-467a-b460-cdcbf77b1003.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('764eafb3-1573-4bbf-9e8c-788305baac08', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 4, '60440107', '鳴子章吉', '裏門坂のレースを終えて、少し今泉との距離が縮まった坂道。大好きなアニメグッズを買う為、いつもの様にママチャリでアキバへやって来ると、関西弁で自転車乗りの少年、鳴子章吉に出会う。そんな中、坂道のママチャリにタバコの吸い殻を投げ捨てた男に怒った鳴子は、坂道と一緒に、男が乗る車を自転車で追いかけようとする!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f7b8bb9d-42fe-4630-94e2-0ea24b012bdf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a8de97b-198a-4376-9bee-defd09713504', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 5, '60440127', '総北高校自転車競技部', '鳴子と一緒に、アキバの街を自転車で走った翌日、坂道は高校の購買部で鳴子との再会を果たす。鳴子に自分と同じ自転車競技部に入るよう勧められる坂道だが、アニ研への未練を捨てきれずにいた。しかし、鳴子に誘われて、自転車競技部の放課後練習を見た坂道は、自分の可能性を試してみたいと感じ始める。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3bbaabb7-51dd-48c8-a752-6f2d87032a3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b84740e5-1490-4a17-af36-49031543b757', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 6, '60440118', 'ウエルカムレース', '自転車競技部に入った坂道は、いきなり1年生対抗ウエルカムレースに参加する事に。初めてのレースに緊張しながらも、また今泉や鳴子と一緒に走れる事に期待を膨らませる坂道。ところが、レースがスタートすると、一人ママチャリの坂道は、ロードレーサーの部員達に次々と抜かれ、とうとう最後尾になってしまう!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cd380d71-00df-4afc-95be-9f81f88f208c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91e681a1-311e-47f5-9342-8acaa03c658a', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 7, '60440117', '追いつきたい!', '幹の乗る車に積まれたロードレーサーを手に入れた坂道。ロードレーサーに初めて乗るにもかかわらずフラつくこともなくまっすぐ走り、周囲を驚かせる。その性能に感動しながらも、遅れを取り戻そうと必死に今泉達を追いかけるが、金城からは、このままのでは二人に追いつけないと告げられてしまう。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/661a5da8-f87d-47f6-9da8-94cef1d2583c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bde9811e-f2cb-42e6-9254-8f5e8575a6b1', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 8, '60440116', 'スプリントクライム!!', '今泉と鳴子を追いかけて、必死にペダルを回す坂道は、ついに二人を捉えた。今泉と鳴子も、坂道の驚異的な成長と、そのまっすぐな想いに触発され、更なる闘志を燃やす。3人のバトルがますます加速する中、レースは山岳ステージに突入。坂が苦手なスプリンターの鳴子は、徐々に失速してしまい…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c089a192-9999-484d-83cf-0ac58976af57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e83d9b0c-778d-47e2-80d8-478783e245e4', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 9, '60440141', '全力VS全力', '鳴子に背中を押され、峰ヶ山での山岳賞を取る決意をした坂道は、ケイデンスを最大にまで上げてトップの今泉に並ぶ。必死に食らいつく坂道を、今泉も全力で引き離そうとする。山頂までのラストスパート、坂道は、鳴子から教えてもらった秘策をもって、全力で今泉に挑む!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e1dee4a3-e2bb-4542-aa8b-f42bc645937c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05ca40e5-c0d0-419b-8f64-02e5ca2f79c6', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 10, '60440105', 'ピークスパイダー', 'ウエルカムレースを終えて、クライマーとしての自分の可能性を見い出した坂道。翌朝、部室に行くと、ポスターの裏に隠れて、壁に大きな穴が空いているのを見つける。その穴を空けたのが3年の巻島だと知った坂道は、その日の放課後練習で、巻島とマンツーマンの個人練習を言い渡され、ガチガチに緊張してしまう!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b9a261c5-2eb3-4a28-a330-a4111a610d7d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e94d0a9f-48c8-48f4-9fa7-165b72fdf28a', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 11, '60440138', '肉弾列車!!', '個人練習の翌日。部活が休みだと思っていた坂道達は、たった今、3年生達がインターハイ出場を決める千葉県予選に出場していると聞き、大急ぎで会場へ向かう。会場に到着すると、レースは既に始まっていた。総北高校は、先頭2校のチームに50秒以上の差をつけられ、かなり厳しい状況になっていて…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9e35eff7-3312-4666-92ab-c626edbad881.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e596949a-402e-4d0f-bdff-624c68a798d2', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 12, '60440111', '合宿初日!', 'インターハイに向けて、合宿を開始した総北高校自転車競技部。合宿所へ向かう途中、車酔いで休憩していた坂道は、そこで自転車乗りの少年、真波山岳に出会う。同じ坂が好きな真波との出会いに心弾ませつつ、合宿に挑む坂道。だが、金城から告げられた合宿のメニューは、予想以上に過酷なものだった!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/791b17e4-b95e-46ea-9e7b-de9e1e82105e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d8ec8b5-8b2f-4d4e-9a50-53d60525409b', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 13, '60440110', '今泉と鳴子の1000km', 'ついに始まった強化合宿。主将の金城から告げられた、4日間で1000km走破という過酷なメニューを乗り切る為、朝から気合いを入れて走る今泉と鳴子。坂道も、巻島のアドバイスを受けて徐々に距離を伸ばし始める。一方、同じくインターハイ出場が決まっている他校の選手達も、大会へ向けて着実に動き始めていた…!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ce51e4dd-ac43-44fe-b097-4e47b945cf20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3813c8a8-af00-4284-af9e-45a1393a5a50', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 14, '60440142', '朝霧の再会', '合宿3日目。周回ペースが一番遅れている坂道は、皆に追いつこうと、一人早朝から走り始めていた。コースの途中、合宿初日に出会った少年、真波に再会した坂道。同じ自転車部の1年生で、坂が好きな真波との再会が嬉しい坂道は、自転車で坂の上まで競争しようと提案するが…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/22aa1582-3faf-40d8-902a-43e7422dc423.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('14d36313-86da-40ff-b856-3c13fb7ac857', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 15, '60440121', '策略', '真波との再会によって、インターハイへの想いが高まる坂道。インターハイに出場する為に、まずはこの合宿で1000kmを完走しなければいけないと気付いた坂道は、同じく出場を目指す今泉や鳴子と共に、必死でペダルを回す。だが、そんな坂道達に対し、2年の手嶋、青八木はある策略を巡らせていた…!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/848c428a-c795-4541-92d5-19733e21ead0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9fd23e4f-1ef8-4cc4-b163-e4eebdf97988', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 16, '60440136', '一点突破', '1000km走破を目指す坂道達の前に、立ちはだかる2年の手嶋、青八木。二人はリードしている順位を死守する為、坂道達に勝負を仕掛けてきた。二人の強固なチームワークと巧妙な策によって、精神的にも追いつめられる今泉や鳴子。そんな中、手嶋は去年の春、高校に入学して青八木と出会った頃のことを思い出していた…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/abf0282b-184a-4dbb-bcd1-99c17eb61dfb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f19832d2-6c63-418f-9470-952393c80d27', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 17, '60440135', '最後尾の小野田', '手嶋の鉄壁のガードを破り、坂での一点突破を成し遂げた坂道。万策尽きて落胆する手嶋だが、必ず二人揃ってインターハイに行くという青八木の強い意志を受けて、再び1年を追いかける。様々な想いの中、ゴールラインを目指して全力で疾走する5人。インターハイ出場を賭けた1年と2年の戦いが遂にクライマックスを迎える!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f8afa4fc-cfbe-480c-91bc-8dd67aed3aea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fde11310-d0f1-425e-9c3f-2844e9aca40b', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 18, '60440130', '全力の勝負', '最後尾に落ちながらも、不屈の走りでペダルを回して先行する今泉、鳴子、手嶋、青八木に追いついた坂道。5人それぞれが様々な想いを胸にゴールラインを目指して全力で疾走、決死のゴールスプリントで激突! インターハイ出場を賭けた1年と2年の戦いが遂にクライマックスを迎える!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2ef14878-ee9d-4a59-944f-c82de6cc75e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d771abf0-5894-4a3f-8507-7a828d1214d1', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 19, '60440122', '新たなるスタート', '過酷な1000km合宿を終えて、大きく成長した1年生達。坂道も見事完走を果たしたものの、自分は経験、実力共に他のメンバーよりも不足していると痛感し、インターハイメンバーになる事を諦めていた。そんな気持ちで臨んだある日の練習で、主将の金城が坂道に語りかける。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a14fcdbe-9b11-4a97-b061-7ddfb47dfba7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('446a9279-6dea-4de3-8b41-5fe24e5cbd30', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 20, '60440124', '真波山岳', 'インターハイに向けて士気あがる総北高校自転車競技部。一方、昨年の優勝校、箱根学園でも、2年の黒田、1年の真波という2人のクライマーによる、インターハイ出場を賭けたレースが行われていた。2年の黒田が先行する展開の中、福富らレギュラーメンバーの目の前で真波が見せた走りとは…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7f1f7ac6-7da2-49f7-ba2d-d2351837fa88.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56423c62-8301-4717-a966-1953660bc479', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 21, '60440126', '石道の蛇', 'インターハイ前日。休みの部室に一人佇む金城は、1年前の夏のインターハイを思い出していた。当時、総北のエースとして出場していた金城は、先頭を走る箱根学園のエース、福富を捉えていた。ゴール直前、レースは一騎打ちへと持ち込まれるが…。一方、巻島の家に集まった坂道達も、福富との因縁の話を聞いていた。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/edbd3334-f547-4eb0-bfcd-0babeca6715c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bd2e601-253d-40f9-b7e9-622a227194ba', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 22, '60440140', 'インターハイ開幕', 'スタート地点である江ノ島のインターハイ会場にやって来た坂道達。初めて出場するレースへの緊張で、動揺を隠せない坂道だが、メンバーからの励ましを受けて気合いを入れる。次々と全国の強豪校、ライバル達が集う中、高まる闘争心や期待を胸に、ついに、インターハイの幕が開く!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1f132922-4160-459d-9767-a5c47b18a744.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38fe54dc-7046-474b-9a2f-b75c116376c1', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 23, '60440132', 'トップスプリンター!!', 'インターハイ1日目が遂にスタート。坂道は高まる期待を胸に、今泉や鳴子と一緒にゴールを目指して走り始める。レースが動き出し、最初の平坦区間に突入すると、各校のトップスプリンターが一斉に動き出し、田所と鳴子も集団を飛び出した。そこへ箱根学園から、全身筋肉のスプリントマシーン、泉田が立ちはだかる!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/aa3680d6-bd1e-4800-881c-5d5d1e87892d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00e05516-e6da-4933-854a-6366aca3a330', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 24, '60440133', '震える泉田', 'ファーストリザルトを目指し、一斉に走り出した各校のトップスプリンター達。先頭を激走する田所と鳴子を猛追するのは、この日の為に完璧な肉体を作りあげた箱根学園の泉田。彼は、自らのスプリンターとしてのセオリーに反する二人に「あなた方はスプリンター失格だ!」と言い放つ。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6f295115-5cc0-4a56-b65e-83c8e2b198e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4b6652d-9987-43b1-b323-54ab15713f40', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 25, '60440120', '負け', 'それぞれの必殺技で泉田に迫る、田所と鳴子。その予想外な強さを目の当たりにした泉田は、「スプリンター失格」と言った事を撤回。ジャージのジッパーを上げ、本気モードとなり、全身の筋肉を槍の様に鋭く研ぎ澄まして突き進む。その速さに圧倒される田所と鳴子だが、過去に味わった悔しさをバネに、全力で勝負に挑む!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/120615ac-62a6-45d6-9db2-e09ae371dde9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9eff025-f9f0-49c9-b203-e9bcf0e1fcc3', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 26, '60440129', '空が見える', '三つ巴の戦いとなったファーストリザルト。田所と鳴子は、落車も恐れずにゴールへと直進!最後の勝敗を分けたのは勝利への執念だった。そして、レースはいよいよ山岳区間へと突入。各校のクライマー達が動き出す中、巻島と箱根学園の東堂も準備を開始。坂道は、巻島が抜けた後のチームを引くという役割を与えられるが…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d4d0eb5a-b1ef-4ddb-9c83-3d9d9c70af20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee2965de-8396-4068-b68b-3eb9459381d2', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 27, '60440114', '山神東堂', '山岳リザルトを狙う巻島の為に、山岳区間でチームを引く役割を与えられた坂道。しかし、集団落車に巻き込まれ、最後尾となってしまう。坂道を失った総北は、巻島がチームに残る決断を下す。そこへ、箱根学園の東堂が現れ、ライバルである巻島に、3年最後のリザルトを賭けた勝負をしようと持ちかける。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2175bb3d-c992-4320-91e2-cbe95d66a2fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c11c1c4c-d793-4cd6-b99b-94b074b7672f', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 28, '60440137', '100人の関所', '坂道が必ずチームに追いつくと信じ、3分間だけ待つ決意をした巻島。一方、最後尾となってしまった坂道は、先頭を走る総北チームを目指して全力で走り出す。手嶋から「登りで100人抜け」と言われた坂道は、得意のハイケイデンスで驚異的な追い上げを見せる! しかし、そこに京都伏見の御堂筋が立ちふさがる。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ec1fda5c-b649-4579-9fac-c1d1381f1e35.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44f0b5d5-22b8-47cc-be04-eee932c10b7e', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 29, '60440128', '山頂', '100人目の御堂筋を抜き、怒涛の走りで総北チームに追いついた坂道。巻島は坂道への感謝の言葉を金城に託し、山岳リザルトを獲る為、先頭を走るライバル･箱根学園の東堂を追いかける。巻島と東堂、共にクライマーとして競い合ってきた2人の、意地とプライドを賭けたラストクライムが遂に実現する…!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d88b9839-b72c-42f1-b987-e3a3d485fc31.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4fa4cf8-d8b8-41be-b749-7070401db9bc', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 30, '60440108', '荒北と今泉', 'ゴールまで残り4km。各校のエース達が初日の優勝を目指し一斉に動き始める中、総北はエースの金城と今泉がチームの想いを積んでゴールを狙う。全力で金城を引く今泉だが、後ろから箱根学園のエースアシストを務める荒北が、野獣の様な走りで二人に迫る。荒北は今泉を「お利口ちゃん」と煽り、圧倒的な追い上げを見せる。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6c8b50dc-1ef0-4335-b238-4d09ff73f977.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da8e0039-9605-4ea7-9ec6-4917ee957b92', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 31, '60440106', '強者3人', 'ゴール目前、今泉と荒北は、それぞれエースである金城と福富を送り出し、勝負は彼ら二人に絞られる。しかし、後方から一瞬の隙をついた御堂筋が、驚異的な追い上げで今泉達を追い抜き、先頭に迫る! 今泉はエースを守る為、限界が近い脚で追いかけるが、御堂筋にはまだ、とっておきが残っている…!?', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4c172673-042b-4985-9f76-85090d498678.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1250ff1d-6716-4229-a015-f15cf7ef436f', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 32, '60440115', '希望の夜', '福富、金城、御堂筋によるまさかの三つ巴の戦いの末、3選手同着1位となったインターハイ1日目。ゴールを迎えた選手達の各区間リザルトが表彰される中、田所は体調を崩し、地面に倒れ込んでしまう。不穏な空気を残しつつ、宿舎へと向かうチーム総北。明日のレースに控え、休養をとる坂道達の前に、あるお客さんが現れる。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9a09ae13-b3f1-4035-b8d3-e019b6cd1d6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3ac297c-e780-49c9-99ef-91095a7d072b', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 33, '60440131', 'ヒメなのだ', '3日間中、最も長いステージであるインターハイ2日目がスタートした。坂道は自分に与えられた“チーム全員を引いて峠を登り、できるだけ早く金城と今泉に追いつく”というオーダーを胸に、気合を入れて走りはじめる。しかし、前日に体調を崩していた田所は、一人、スタートできずに立ち尽くしていた…!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/956cd767-dfa9-4513-989b-746efd839dfd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a1fcf25-c7bb-49f1-be85-0823ad9df28e', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 34, '60440139', '新開隼人', 'メンバーがバラけてしまったチーム総北をしりめに、早々にメンバー全員が合流を果たした王者･箱根学園。焦る総北の金城と今泉だが、追い打ちをかけるように御堂筋率いる京都伏見が合流を果たし、先頭は2校の戦いとなる。御堂筋はファーストスプリントリザルトの勝負を持ちかけ、箱根学園のエーススプリンター新開が動き出す!', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2acb80ee-c85f-45ef-a622-cad212c6bc62.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6a8ac63-9654-4cd2-8d42-ee45e856721c', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 35, '60440123', '勝利する男', '巻島と鳴子が合流するも、依然として不利な状況が続く総北。しかし、坂道と田所が後ろから順調に追い上げて来ている事を知り、再び一丸となって先頭を追いかける。一方、先頭では御堂筋と新開のスプリントバトルが過熱!過去のトラウマを乗り越え、仲間の為に走ろうとする新開だが…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8598ef59-4be0-4f7c-a1b9-49526e26fbe0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f5b3b4d-2e3a-4358-8913-6903cd7fe66d', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 36, '60440113', '最強最速', 'スプリントラインまで残り100m。御堂筋との激闘の中で“箱根の直線鬼”として覚醒した新開は、鬼の形相でかつて最速と言われた走りを見せる。その圧倒的強さを前に、御堂筋も太股のテーピングを外して全力で勝負に挑む。一方、バラバラになっていた総北も、坂道と田所が驚異的な追い上げを見せる。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0787f097-a6dd-4a73-9653-d98bf9c2b0ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc5c8faa-20dd-4b22-a769-bd7454d6737c', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 37, '60440125', '王者交代', '坂道と田所が追いつき、遂に6人全員が合流を果たしたチーム総北。今泉や鳴子も、坂道の頑張りに引っ張られるように、気持ちを一つにして走り出す。一方、先頭を走っていた王者･箱根学園は、御堂筋との激戦を繰り広げた新開が陥落し、メンバーが徐々にバラけ始めていた。御堂筋の挑発に心を乱す泉田だが…。', '2025/05/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/72d0beef-468d-4302-969d-d5c5086419e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('95a974bf-400c-4987-b0b7-63d74cc63e07', 'a2711bb4-278d-4677-a944-2a0fbf8e9363', 38, '60440112', '総北の魂', '【第1期 最終話】山岳ポイントを取り、先頭を独走する京都伏見。全てが御堂筋のシナリオ通りと思われたが、メンバーがバラけていた王者･箱根学園が、築き上げてきた強い信頼でペースを取り戻し、総北も坂道の活躍により、先頭争いに追いついた。総北vs箱根学園vs京都伏見、各校がそれぞれの想いと誇りを背負い、全力でゴールを目指す!', '2025/05/01 00:00:00', 1410, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5dd8ab69-6924-43e3-9e0c-0c537014af65.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3efb1112-7e32-43f1-94a7-b35e8b03e762', '弱虫ペダルGLORY LINE', '', 'hulu', 'yowamushi-pedal-glory-line', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a81b2f7-feb0-42fe-bfaa-b7895dfdffad.jpg?w=331&h=447&p=t', 'hulu', 2018, 0, 1, 'FINISHED', NULL, 99476, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b4539761-a118-4337-8b21-d8e3a43c1983', '3efb1112-7e32-43f1-94a7-b35e8b03e762', 'hulu-yowamushi-pedal-glory-line-s1', '第4期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4c21acb-1aee-4ee7-8f66-596ee7a1347c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7fc15855-c715-4011-b63e-996f835b4e5e', 'b4539761-a118-4337-8b21-d8e3a43c1983', 1, '100089030', '最終局面へ', 'インターハイ栃木県大会1日目。ファーストリザルトは箱根学園の銅橋が獲得、続く山岳ステージでも総北のキャプテン手嶋を抑え、箱根学園の真波が山岳賞に輝いた。快進撃を見せる箱根学園は迫るゴールに向けて、エース葦木場とエースアシスト黒田が飛び出す! 抜群にしなる脚を持つ“黒猫”黒田の走りに後れを取ると思われた総北だったが、今泉と鳴子の2年生コンビが猛追していく。緊迫する最終局面、遂にゴール争奪戦がスタートする!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4c21acb-1aee-4ee7-8f66-596ee7a1347c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71d16047-24ec-4c6d-985b-d16e12a2db52', 'b4539761-a118-4337-8b21-d8e3a43c1983', 2, '100089031', '2人のエース!!', '1日目のゴールに向けて、黒田の引きで一気にリードする箱根学園だが、総北はスプリンターからオールラウンダーに転向した鳴子章吉が本領を発揮! 登りでもスピードを発揮する新必殺技を見せて一歩も引かない。手嶋から「エースは自分たちで決めろ」と言われ、コンビというよりライバルのように競り合って走る今泉と鳴子に対し、黒田は葦木場とのコンビで百戦錬磨のレース運びを見せる。そんな中、後方から両チームに忍び寄る影が…!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8fe6470-d58b-4f2e-a581-1d305969c940.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e692810-c505-4ee6-b8b9-9d72d1963ccd', 'b4539761-a118-4337-8b21-d8e3a43c1983', 3, '100089032', '約束の時', '1日目ゴールまで残り3.5km! 優勝は総北か箱根学園どちらかのチームだと誰もが確信する中、突如京都伏見の御堂筋と岸神が後方から奇襲を仕掛け、御堂筋がゴールに向けて一気にアタック! しかし、鳴子だけは御堂筋から目を離さず、そのアタックについていく。開会前の宣戦布告のとおり、御堂筋VS鳴子のリターンマッチが始まる! 一方、今泉に協調を提案した黒田は「スイッチ」を入れ、今まで以上の走りで2人を追いかける!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e0b9bae-5031-4e33-98d1-d799cc9af82a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('14f50301-be9a-4872-b2b6-8ae8e54c3592', 'b4539761-a118-4337-8b21-d8e3a43c1983', 4, '100089033', '覚悟の5人', '先頭で御堂筋と鳴子の激しいデッドヒートが続く! 後方では黒田が決死の引きを見せ猛追するが、前を行く2人を視界に捉えることができない。するとこれまで引いてもらっていた葦木場が「ゴール前にいなければ勝負にならない」と、黒田とポジションを交代し、メトロノームダンシングで激走。ぐんぐん前との差を詰めていく。今泉も鳴子の走りを後押しすべく懸命にペダルを踏む。御堂筋、鳴子、黒田、葦木場、今泉――。覚悟を決めた5人の決着の時が迫る!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89ed0084-1663-48ea-bfab-cf9b4562d5db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d646566-f3ec-4e9e-8de4-afb0a4210a51', 'b4539761-a118-4337-8b21-d8e3a43c1983', 5, '100089034', '削る3秒', '自らの力を全解放して“変態”した御堂筋と、この日のために磨いてきた純粋な全力スプリントを見せる鳴子がゴールに近づく。そこに、黒田のギリギリのコーナリングと決死のアシストから飛び出した葦木場が追いついた!「オレは強いよ!」黒田に背中を押された葦木場、御堂筋と鳴子の三つ巴のゴールスプリント! 3人がゴールラインに向かってバイクを投げ出して、ほぼ同着でゴール―。果たして、インターハイ1日目を制したのは…!?', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e61a7de6-2352-47e5-993b-e8c0f7fd25c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ef0e321-77a4-4438-a9b9-9979adc9f65e', 'b4539761-a118-4337-8b21-d8e3a43c1983', 6, '100089035', '揺らぐ総北', 'インターハイ1日目、三つ巴の争いを制したのは箱根学園のエース葦木場拓斗だった! 僅差で同着2位は鳴子と御堂筋。初日の全てのゼッケンを獲得した箱根学園は、王者復権を見せつける。鳴子は表彰式では明るく振る舞うも、その心は悔しさに震えていた。総北は全ステージで2位という悔しい結果に加え、鏑木が疲労で倒れ不穏な空気に包まれる。そんな中、不安な表情を見せる坂道の前に、総北の前主将･金城が姿を見せ…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39804d94-17f7-4d4e-b0f3-3f213f9beace.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f334a866-a955-47c7-b39a-51a60f55cda3', 'b4539761-a118-4337-8b21-d8e3a43c1983', 7, '100089036', '希望の足音', '金城と出会い、もっと強くなれと言葉をもらった坂道。さらに巻島と田所も応援に来てくれていると知り、1日目の敗北で揺らぐ手嶋たちにその事を伝え、チーム総北は2日目以降のレースを新たな気持ちで挑む決意をした。一方、同じく1日目に敗れた京都伏見の御堂筋も、2日目のレースに向けて新たな戦略を立てていた…。そして迎えたレース2日目の朝。坂道に箱根学園の新開悠人が話しかける。「勝負しましょう、オレと、今日どこかで。」', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/055349ba-0051-4517-96e5-947d25611a86.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13b4e615-0271-412c-945b-3571a8ee980f', 'b4539761-a118-4337-8b21-d8e3a43c1983', 8, '100089037', '2日目、スタート!!', 'インターハイ2日目がスタートし、選手が1日目の着順スタートで次々と走り出す。少しでも早く先頭の今泉と鳴子に追いつこうと坂道と手嶋がペダルを回すが、鏑木は自身の様子がおかしいことに気付く。一方、なかなかペースを上げない箱根学園だったが、それは司令塔の黒田を合流させるためだった。そんな中、不調の鏑木がチームからちぎれてしまう。鏑木を助けに行こうとする坂道を、箱根学園を警戒して止める手嶋。そこに青八木が口を開き…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/997268a0-c35d-4aa5-80d5-48418948a381.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e007b71-ab0a-4ec1-9e45-baa77280e971', 'b4539761-a118-4337-8b21-d8e3a43c1983', 9, '100089038', '願いのタスキ', '手嶋の制止を振り切り、後方に沈んだ鏑木の救出に向かった青八木。一方、鏑木は古賀の激励もあり少しずつ調子を取り戻すものの、まだ全力を出す事ができない。そこに現れたのは…青八木! ところが鏑木は青八木がバテて落ちてきたと勘違いし、逆に自分が前になって激走! 先行する集団に追いつく。青八木はその集団からさらに飛び出すため、ペースを上げる秘策として神様からのメモを鏑木に渡す。そこに書かれていたのは、ある歌の歌詞だった…!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/702a949c-94aa-43bb-8357-f74a438b68b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7eda7681-aca3-400d-90ff-5e361d52c648', 'b4539761-a118-4337-8b21-d8e3a43c1983', 10, '100089039', '16番、新開悠人', '京都伏見が先行していることに気付いた青八木は、集団から抜け出そうと鏑木に神様のメモを渡す。そこに書いてあったのは、先輩･田所がインハイで救われたというアニソン「恋のヒメヒメぺったんこ」の歌詞だった! 2人は一緒に歌いながら一気に加速する。そして前方では箱根学園が手嶋と坂道に追いつき、1年生クライマー新開悠人が牙を剥く! 手嶋を抜き去った悠人は坂道に宣戦布告。対する坂道も、先頭の今泉と鳴子を守るために闘志を燃やす!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee4b557f-b983-4c8f-947a-61fbcb83ccfd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('286cfdf7-d79f-42bf-a022-0d0db54ecff6', 'b4539761-a118-4337-8b21-d8e3a43c1983', 11, '100089040', '山王', '坂道と悠人の戦いが始まった。“山王”とまで呼ばれるほどになった坂道と戦うことに悠人は興奮し、先頭を行くそれぞれのチームメイトとの合流をゴールとする勝負を持ちかける。「ただチームのために」走る坂道の姿勢に違和感を覚えながら一気に勝負に出る悠人。しかし今泉と鳴子が坂道が来ることを察知し、勝負は引き分けとなった。しかし、そこに黒田ら箱根学園が追いつくと、勢いは一気に箱根学園へ。追うか、手嶋を待つか…。今泉は判断を迫られ…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82b6dee2-a1df-4704-a6b3-41517bb53acb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1d65062-fc55-4b37-9286-071ac31a4e4b', 'b4539761-a118-4337-8b21-d8e3a43c1983', 12, '100089041', 'こぼれ落ちた想い', '全員が揃った箱根学園が加速し、鳴子は今泉の命令を振り切り一人で箱根学園を追いかける! その後、手嶋が今泉と坂道に合流するがなかなかペースが上がらない。するとそこに岸神小鞠が引く京都伏見が現れ、抜き去っていく! 自身の判断ミスと苛立ちから手嶋に厳しい声を浴びせる今泉の心で、何かが折れた音が―。そして対峙する箱根学園と京都伏見はスプリント勝負へ。泉田と御堂筋が対決…と思いきや、意外な男が忍び寄り…!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7747cd2-8367-49ad-b2f4-9dfdf0a6496b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cdd1e9b-513f-42d7-8a00-6aae6788fa81', 'b4539761-a118-4337-8b21-d8e3a43c1983', 13, '100089042', '罪を背負いし者', 'スプリントリザルトを懸けた闘いが始まった。箱根学園キャプテンのスプリンター泉田に対し、京都伏見は泉田の「最上級筋肉 (よきにく)」に執着する岸神小鞠が飛び出す! 泉田は、前年のインターハイでの敗北、自分がキャプテンにふさわしいのか葛藤していたこと、そんな自分の背中を押してくれた葦木場や黒田の言葉を思い出していた。すべての罪と覚悟を背負った泉田が疾走する! しかし岸神も「最上級筋肉 (よきにく)」への異常な執着で追いすがる!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fd141b5-c1eb-4eb1-b293-e03a563a8782.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('085329d9-1453-4bc4-87c6-f2482372775b', 'b4539761-a118-4337-8b21-d8e3a43c1983', 14, '100089043', '心のつつみ、心の函', '白熱するスプリント争い! 岸神は己の“欲”を全て解放させて走る。彼は幼い頃から筋肉 (にく) に興味を抱いていたが、由緒ある家の教えからその欲求を包み隠していた。しかし、中学生の時に御堂筋と出会い、「真実が欲しいなら己の全てを差し出すべき」という言葉を受け、欲望を覚醒させたのだ。リザルトラインが迫り、泉田と岸神の戦いはさらに激化。箱根学園の主将として走る泉田。「もう包み隠さない!」と解き放たれた岸神。勝負の行方は―!?', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aff234d2-309a-4723-aebf-c0e8fddff5d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b3d6ab0-9870-4ca4-b345-09c4e305666e', 'b4539761-a118-4337-8b21-d8e3a43c1983', 15, '100089044', '歓喜のスプリントライン', '泉田と岸神の全力スプリント勝負も大詰め。そんな中、コースに観客のペットボトルが転がり落ちてきた。スピードを緩めて障害物を避けるべき、とシグナルを出すアンディとフランク。しかし泉田は、昨年のインターハイの田所と鳴子とのレースを思い出し、構わずに直進する! そして勝ったのは…泉田! 箱根学園の主将として、エーススプリンターとしての重責を果たした。岸神は筋肉 (にく) への欲を満たせなかったものの、その敗北を受け入れる美学を見せたのだった。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1bf70dde-eed1-4f57-bf2a-937c84efaebd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecba37bb-3d25-4f05-bd59-33e0f471aca6', 'b4539761-a118-4337-8b21-d8e3a43c1983', 16, '100089045', '遅れる総北', '泉田のスプリントリザルト獲得に沸く箱根学園は先頭を突き進む。一方、総北はチームが散り散りとなり、最悪の状況が続いていた。先頭集団に張り付く鳴子もチームが追いつくのを待ち続けながら体力を擦り減らしていた。手嶋･坂道･今泉は熊本台一にも抜かれ、より絶望的な状況に。しかし、坂道は明るく「青八木さんと鏑木くんが追いついてきます!」と2人を信じてペダルを回していた。そして、後方を見る手嶋の目に、黄色いジャージが飛び込んできた―!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ceebc3e1-9cbf-42c7-afb9-897ec70379f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0985bf6f-716f-4904-a098-6ece588a60da', 'b4539761-a118-4337-8b21-d8e3a43c1983', 17, '100089046', '山のはじまり', '後方に落ちていた鏑木と青八木が追いつき、遂に合流を果たした総北。5人が揃い、チームにも希望が見え始めた。その中で、坂道は真波ともう一度戦うという約束を胸に走る。一方、先頭集団はすでに平坦から山岳･榛名山へと突入! 山岳リザルト、そしてその先のゴールに向けて熱を帯びる。箱根学園の真波も坂道を気にしていたが、黒田は京都伏見の動きを警戒。そして、御堂筋たちがアタックを仕掛け、一進一退の攻防が繰り広げられる!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0497e93-2e0c-41ba-bd5b-9f3d8803aa26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c3a26d6-cef0-4ed1-aff4-2378b92716dc', 'b4539761-a118-4337-8b21-d8e3a43c1983', 18, '100089047', '鳴子の意地', '坂道は真波とのインハイで戦う約束を果たそうとペダルを回し、チームと共に箱根学園に追いつく。しかしそこは先頭ではなかった。葦木場や御堂筋たちが先行していたのだ。レース状況の変化から真波は坂道に「戦うことはできない」と告げる。手嶋は坂道に「先頭を追え」とオーダー。意を決した坂道は、今泉と共にスピードを上げる。一方、先頭では、葦木場たち箱根学園、御堂筋の京都伏見、熊本台一に対し、鳴子は仲間が追いつくことを信じひとり戦いを挑んでいた!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27cff68e-1bd5-40b3-801b-e31ce79b7c20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68ea5787-aff2-4a6f-a0f9-572ebfc4968d', 'b4539761-a118-4337-8b21-d8e3a43c1983', 19, '100089048', '近づく山頂', '鳴子は坂道と今泉が追いつくことを信じて、先頭集団で御堂筋の変則的な攻撃に耐えながら、さらに葦木場と悠人と戦いながら、孤軍奮闘していた。そして遂に鳴子が落ちた、と思ったその時、後ろから坂道と今泉が現れた! 鳴子の頑張りを受けた2人は、山岳賞、そしてゴール争いに突入していく! 一転して形勢が不利になった御堂筋は、水田に山岳賞をちらつかせて自分を引かせる。そんな中、坂道が凄まじい走りで他を圧倒。その“山王”の本領発揮に悠人も驚愕の表情を見せて…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3486358d-7178-4441-949c-0216d3237978.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a006074f-a4bc-4779-9bed-401ad9540380', 'b4539761-a118-4337-8b21-d8e3a43c1983', 20, '100089049', '山岳賞', '圧倒的不利な状況だった御堂筋は、水田に山岳賞を狙わせ、“王者･箱根学園”の誇りを持つ葦木場を刺激する。結果、山岳賞は葦木場が獲得するが体力を消耗。ここぞとばかりに御堂筋は加速。そして、総北も坂道に想いを託された今泉がゴールを狙う。エースとしてゴールを狙うはずだった葦木場の行動を悠人は理解できない。しかし、葦木場は「まだゴールを諦めていない」と告げる。過去を思い出す悠人。彼は自転車競技部入部当初、兄･隼人の弟としか見ない先輩と衝突していた―。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8944841-fdf8-4452-bd90-359a6918a658.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d316ea6-f0fb-4d5a-b95b-690f0a46eba3', 'b4539761-a118-4337-8b21-d8e3a43c1983', 21, '100089050', 'リミッター', '悠人は入部当初、兄･隼人の存在から部の中で孤立していた。先輩と衝突する悠人に、ある日葦木場が勝負を持ちかける。勝負は葦木場の圧勝に終わり、悠人は葦木場の強さから彼を慕うようになった。そしてインターハイ2日目のゴール争い、葦木場は悠人にエースの役割を託す。自分はクライマーのはず、そんな気持ちを覆すかのように悠人は凄まじいスプリントで今泉と御堂筋に追いついていく! 御堂筋と悠人が激しく競り合う中、今泉も坂道たちの想いを胸に、自らの“リミッター”を外す!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84b61a16-f867-49ad-8baf-f9c98857fcb2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e648cbc-2a90-4748-bd07-989185beb5ed', 'b4539761-a118-4337-8b21-d8e3a43c1983', 22, '100089051', '3人の強者', 'インターハイ2日目のゴールまで残りわずか。今泉、悠人、御堂筋も3人のゴールスプリントが激しさを増す! リミッターを外し先頭を走る今泉。一方御堂筋は、かつて入院する母の病院へと通っていた頃の記憶を辿り、勝利を掴むイメージを鮮明化させる。そして、悠人も兄･隼人と純粋に自転車を楽しんでいた頃の自分を思い出す。「箱根の直線に出る鬼に、弟がいたってウワサ知ってるかい?」兄と同じくスプリントの鬼と化した悠人! ゴール前、攻防戦を制するのは果たして―――。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1bac824b-b605-45a1-b1c1-58f8a8095e84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8e241b6-5c15-4dde-b295-918b7be79a2c', 'b4539761-a118-4337-8b21-d8e3a43c1983', 23, '100089052', '勝利者', 'インターハイ2日目のゴールが迫る! 今泉、悠人、御堂筋、三つ巴のゴールスプリントは、残り20mを切った! 今泉は、信じて背中を押してくれた仲間の想いのために。悠人は偉大な兄を持ったことから生まれたコンプレックスを振り払い、“王者”箱根学園勝利のために。御堂筋はただ、己の勝利を掴むために。三者三様の想いをペダルに乗せ、突入するゴールライン! トップでゴールしたのは…!? そしてその夜、3日目への不安を振り払うように山を登る坂道の前に、1人の男が現れ…!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05a15915-84e3-40c4-a840-34e86ed1531a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9794f6ce-ea82-417b-af3a-9cd7cc82dadb', 'b4539761-a118-4337-8b21-d8e3a43c1983', 24, '100089053', '小さな峠', 'インターハイ2日目の夜。坂道は山道で箱根学園の卒業生･東堂尽八と遭遇する。東堂はある男からの連絡を受けて走っているという。その男とは…巻島裕介だった! 驚きと嬉しさが入り混じる坂道の目の前で、巻島と東堂の本気の勝負が始まった! 同着が続き、2人は2回戦、3回戦…と勝負を続け、坂道はその姿に気持ちを昂ぶらせる。勝負が終わった後、巻島からの「自分を貫け」という言葉を受け、決意を新たにする。一方、真波も東堂からの言葉で闘志をみなぎらせるのだった。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed164534-2459-4c5a-aa80-82aacb1082e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7deefd2d-4723-44b6-bf5a-aecedc837305', 'b4539761-a118-4337-8b21-d8e3a43c1983', 25, '100089054', 'それぞれのスタートライン', '【第4期 最終話】インターハイ最終日の朝が来た。想いを繋いで全員でここまでたどり着いた総北。“王座奪還”そのためだけに走ってきた箱根学園。無駄なものをすべて削ぎ落とし“勝利”だけを見据える京都伏見。その他各校が、頂を目指して、それぞれのスタートラインに立つ!', '2025/05/01 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb273fa4-57ea-4e15-a54e-3642d1fdb331.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d912fa67-0ffc-4ac6-96e5-fca17aba4e8c', '弱虫ペダルGRANDE ROAD', '', 'hulu', 'yowamushi-pedal-grande-road', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5803cf81-d437-49c2-9e6f-a80fdf01a843.jpg?w=331&h=447&p=t', 'hulu', 2014, 3, 1, 'FINISHED', NULL, 20723, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 'd912fa67-0ffc-4ac6-96e5-fca17aba4e8c', 'hulu-yowamushi-pedal-grande-road-s1', '第2期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c4f29cd5-46cc-4b68-8b67-b28e9163188f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12c1d23f-8a1f-448e-bd5c-9e94ccdf9982', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 1, '60541859', 'フェイズ49', 'インターハイ2日目もゴールまで残り4km。先頭を走るのは、箱根学園と京都伏見、そして坂道の活躍によりチーム全員が合流を果たした総北高校。3校の先頭争いが繰り広げられる中、追い込まれた御堂筋は"フェイズ49"を発動。箱根学園のアシスト、荒北に迫る! 激動のロードレース後半戦、優勝を懸けた戦いが遂に始まる!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c4f29cd5-46cc-4b68-8b67-b28e9163188f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('398e08a5-6ee0-4d51-8117-4ae4b879ed1a', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 2, '60541871', 'エースたち', '2日目のゴール直前。3校の先頭争いが続く中、エースアシストの今泉は、勝負のクランク後でエースを切り離すタイミングを狙っていた。しかし、御堂筋がクランク前で予想外のアタックを賭け、ゴール前は一気に御堂筋の独走状態に! 役目を果たせず悔やむ今泉だが、金城はチームの想いを背負い、全力で追走を開始する!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0e47a132-bae4-4d9d-b416-2dcced975fda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b96be77b-d575-478f-9342-0bb795b26336', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 3, '60541872', '翔', 'クランク前で予想外の単独アタックをかけ、ゴール直前で独走状態となった御堂筋。しかし、金城と福富もチームの想いを背負い、己の限界を越えて御堂筋を追走。それを受け、御堂筋の走りは更に加速! 全てを捨て、勝利だけを求める御堂筋の姿に、金城と福富も尋常ではない気迫を感じていた。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3d48e0d1-e9f1-4948-b814-1ff07cc982bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d5c9657-6925-4ef3-814e-13ea1207aecb', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 4, '60541870', '覚悟', '2日目の勝者は、箱根学園の福富だった。金城が敗れる結果にも飄々とした態度の巻島と田所に納得のいかない今泉と鳴子。しかし、今は耐えて、悔しさをバネに明日を走れと巻島に言われ、覚悟を決める。各校が士気を高めている中、金城、田所、巻島の3人は、自分たちが1年だった頃を思い出していた…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c3e93172-54b9-4984-86d7-38fcfc6e8c0d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1889deec-d137-4db2-958d-10a59ce57eec', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 5, '60541868', '薬局までの3km', 'インターハイ2日目の夜。レースに敗れた御堂筋は「明日のレースには出ない」と石垣たちに告げ、一人宿舎を後にする。ところが、自転車で京都に帰ろうとする御堂筋の前に、同じく自転車で薬局に向かう途中の坂道が現れる。御堂筋は坂道を無視するが、坂道はずっと気になっていた事を聞くため、御堂筋を追いかける。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0e08f221-ae82-41a0-b881-20130ddb8fb0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('681b0b27-da6f-4d2d-8cdd-7decfdd26639', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 6, '60541856', 'モってる男', '最終日に突入したインターハイ。スタート前、各校の緊張は最高潮に高まり、坂道たちも気合いを入れる。しかし、そんな空気を切り裂き、広島呉南の待宮が現れる。福富や金城に絡み、自分の運の良さを説く待宮に、動揺する坂道たち。そんな中、行方をくらましていた御堂筋も現れ、遂に3日目がスタートする!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/142b7c77-77c7-4164-a5f4-debfcaa2d2c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0dc7294-f4f0-4823-b3bc-e50d3cd32617', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 7, '60541854', '迫る、集団', '遂に始まったインターハイ3日目。先にスタートしたエースに追いつく為、共に走る"協調"体勢に入った総北と箱根学園。一方、広島呉南の待宮も、後方集団を束ね"協調"を始めていた。奈良三里や熊本台一を次々と呑み込み、40人以上の大集団となった待宮たちは、驚異的なスピードで先頭集団を捉えようとしていた…!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b97bdaed-bacf-4eb7-a543-a9bd07d41c98.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('233f2ba8-f5d4-4ef7-90eb-b9b25e328d06', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 8, '60541861', 'アラキタ', '待宮率いる後方集団に飲み込まれてしまった坂道。当の広島呉南は早々に集団を切り捨て、溜めていた足で先頭を狙う。集団をあざ笑うかの様に去って行く待宮たちに、絶望する選手たち。そんな中、坂道は総北に追いつくため、回りの選手に"協調"をお願いする。断られ続ける坂道の前に、箱根学園の荒北が現れて…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ebc78283-5039-4323-9d5d-d4ee767cdabc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32a12be8-c20a-498d-b004-077066c25824', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 9, '60541864', '呉の闘犬', '坂道の必死の申し込みにより、"協調"を受け入れた荒北。そこへ真波も加わり、異色の3人での追走は、野獣と化した荒北の引きにより、遂に待宮たちを捉えた。そんな荒北に、広島呉南の井尾谷は"20m引き離しレース"を提案。待宮は隠していた己の闘争本能を全開に暴走する!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a3a3c3e3-bf06-4ed2-a19f-af0693f62510.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3851c765-9df1-44cc-af94-b22298d2c011', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 10, '60541869', 'その先の領域', '「ハコガクを潰す!」と、箱根学園への恨みを爆発させる待宮は、荒北へ強烈な頭突きを繰り出し暴走する。荒北はそんな待宮を、過去のやり場の無い気持ちで荒れていた自分と重ね合せ、「ソックリなんだよ、昔の俺に」と語りかける。荒北は、野球を諦め、福富に出会うまでの、過去の自分を思い出していた…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/43e356e1-c822-4d63-ba40-dbdbcd8aedf2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5b798b5-be06-432a-9051-e03baa551cbe', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 11, '60541863', 'サバイバル', '過去の自分に捕われず、前だけを見続けてきた荒北は、待宮たちに圧倒的な実力の差を見せつけ、先頭集団に合流する。総北、箱根学園共に6人全員が揃い、インターハイ3日目は、遂にラストステージへ突入! ゴールに向けてチームの士気が高まる中、坂道は今までとは違う緊張感に押し潰されそうになっていた。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d3591a9f-8567-4700-8996-63f3c23a53de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc88d822-382b-455c-88b2-703a4d827b07', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 12, '60541866', '泉田の誇り', '自らを犠牲にしてチームを引いた荒北の意思を継ぎ、なおも加速する箱根学園。その姿を見た坂道は、これがチーム全員で走れる最後の瞬間である事を悟り、勝利の為に全力を出し切る決意をする。そんな坂道に今泉と鳴子も触発され、箱根学園に追いつく為、チームを引き始めるが…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0ba63cf1-38bd-43b0-ac29-91adc673a14e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e8ff69d-cc66-4a5b-932e-314543eb8173', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 13, '60541857', '激走、山中湖', '泉田の加速により、総北に差をつけ独走する箱根学園。金城たちは、その差が決定的な距離になる前に、1年に代わりチームを引き始める。そんな3年の実力を前に、ただ見守る事しかできない自分たちの無力さを感じる今泉と鳴子。だが、坂道はそんな先輩たちの背中を見つめ、何かを感じ取ろうとしていた。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e00a9908-f521-4b04-b0d7-eb5d5e859d1b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66f62777-02a7-4c40-ac8e-714e630acb13', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 14, '60541862', '最後の作戦', '3年の追い上げにより、一度は箱根学園に並んだ総北だが、新開の加速により再び離されてしまう。だが、田所が最後の全力引きでチームを運び、遂に箱根学園を捉える。そして、コースはラストステージである山岳区間へと突入。ゴールに向けて動き出すその瞬間、2日目のレースでひざを痛めていた金城に異変が…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f4f2df5a-954b-453d-8c6c-1b7c4c57e107.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf790988-ff66-4bbe-afd8-4cebf7e68dc4', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 15, '60541851', '鳴子! 真骨頂!', '自らの膝の不調により、オーダーの変更を言い渡す金城。坂道たちは、そんな金城の想いを受け、前方の箱根学園を目指し山を駆け上がる。やがて総北はスプリンターの鳴子がチームを引き始める。インハイ前、田所のアドバイスにより、こっそりと登りの練習をしていた鳴子。修得した必殺技で観客を沸かせ、登りで真骨頂を見せる!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8e293d1c-1b6a-4fc8-8f96-481a512ff7ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7cadf3c0-cd6a-426e-9c24-8f3daf9bd94c', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 16, '60541849', 'エース今泉!', '山岳区間をスプリンターである鳴子の全力引きにより、箱根学園を捉えた総北だが、体力を限界まで使い果たした鳴子は、コース脇に自転車ごと倒れ込んでしまう。ゴールまで残り15km、鳴子の意思を継いだ今泉は、自らを総北のエースと宣言し、箱根学園のエース･福富に挑む!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4a454b0c-5052-40d1-93ca-8b1d73cc928c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85879fa4-2d1d-41f6-add6-b8ae1fabd2d0', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 17, '60541852', '箱根学園ゼッケン6番', 'エースの意識とチームを背負う覚悟から、覚醒を果たした今泉は、箱根学園のエース福富を力でねじ伏せにかかる! しかし、後方から、沈んだと思われた京都伏見の御堂筋が現れ、先頭を狙い加速する。エースを守る為、いよいよ箱根学園のゼッケン6番･真波がその実力を見せる!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/720d936f-71f4-4809-966a-1d63c1f6ef42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7788dd6c-4f73-4688-9826-4dade531d465', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 18, '60541850', '一歩一歩', 'ゴールまで残り10km。後方から追い上げ、一気に先頭を狙う御堂筋を抑えるべく、飛び出した真波。お互い一歩も譲らない闘いを繰り広げる中、真波は御堂筋に、まだ"とっておき"があると言い、風に乗って更に加速する。その頃、巻島に想いを託された坂道は、一人、必死にケイデンスを上げ、二人を追っていた。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1b97f2f9-e01f-492f-b7b7-8eecac5b38a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4595e8a1-1a7e-40a3-8a86-17040f7350af', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 19, '60541860', '坂道の役割', 'チームの為に強くなる決意を秘め、懸命にペダルを回す坂道は、遂に前方の御堂筋と真波を捉える。御堂筋の持ちかけた「エースまで早く辿りついたものを、ゴールまで追い抜かない」という勝負に坂道も加わり、三つ巴の攻防戦が行われる中、坂道はコースアウトしながらも、なんとか二人に食らいつき…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/506904bc-7e82-4171-ae6e-334787590fac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49bf3a41-47d2-4db7-a88e-17a3a47a8c3e', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 20, '60541867', '今泉 vs 御堂筋', '真波、御堂筋との勝負を経て、先頭に追いついた坂道。今泉と合流を果たし、お互いがゴールを目指す意思を確認する。そこへ、後方から上がって来た御堂筋がすかさずアタックを仕掛ける! しかし、戦略を読んだ今泉が一瞬で抑え、先頭へは行かせないと宣言。今泉と御堂筋、因縁のバトルが開戦する!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6f1a1e4a-b2d9-4f3e-ad21-eae3f747425c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf0598f9-3e34-4ec0-a627-1f3e6cec6e84', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 21, '60541855', '91番', 'ゴールまで残り4km。何度もアタックを繰り出す御堂筋と、それを抑える今泉。二人の先頭争いが加速する中、コースは富士あざみライン唯一の大下り区間へと突入! 落車のリスクを背負いながら、1ミリでも先へ進む為スピードを上げる今泉と御堂筋。ギリギリのバトルで下りを制するのは…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/67e2aa12-aaf5-4e28-820e-3cd8fc6b66eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9027d157-f659-45a2-811d-631cef8c192f', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 22, '60541853', '真波と坂道', '御堂筋との死闘でフレームにヒビが入った今泉を、後ろからアタックで一気に抜き去っていく真波。フレームの状態から追走は難しいと判断した今泉は、坂道に総北の魂を託す。チームの想いを積んで、驚異的なケイデンスで真波を追いかける坂道だが、ギアを上げて独走する真波に引き離されてしまう。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cf629bf7-da39-4e7d-899d-9083c3593fc1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79135b5e-6074-4206-963a-944ee518e38d', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 23, '60541865', '約束の道', '先頭は坂道と真波の2名に絞られた。今泉から総北全員の想いを託された坂道は、ゴールを目指し、ただ真っ直ぐに突き進む。一方、真波も頂上を目指し、逸る心と共にギアを1段ずつ上げていく。ゴールまで残り1km、ギアを最終10段目まで上げ、圧倒的な強さを見せる真波に、必死に追いつこうとする坂道だが…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7c5c395f-00ce-4c6a-8531-9f8089cf9acc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('243422cc-f255-436f-bbd0-34c3166efb05', '4b9f0c36-73ca-450c-a71f-09aa5cb47ddb', 24, '60541858', 'WINNER', '【第2期 最終話】託された総北のジャージを届ける為に、ペダルを回し続ける坂道。真波も最後の力を振り絞り、山頂を目指す。ゴール目前、二人は総合優勝の座を手にする為、全力のラストスプリントでゴールへと飛び込む…! 坂道 vs 真波、長かった真夏のインターハイが遂に決着を迎える!', '2025/05/01 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f4bd78bc-560c-4a74-a52a-366d9f889589.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a2767521-faea-4dc8-a42f-cf28b7039c61', '弱虫ペダル LIMIT BREAK', '', 'hulu', 'yowamushi-pedal-limit-break', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7920326-30de-4da4-b340-014f39a30062.jpg?w=331&h=447&p=t', 'hulu', 2022, 3, 1, 'FINISHED', NULL, 142481, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 'a2767521-faea-4dc8-a42f-cf28b7039c61', 'hulu-yowamushi-pedal-limit-break-s1', '第5期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c2e2ee0-3c03-4262-882c-1aea59056e7d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b2c4ef8-ea0f-4a56-bc3c-8b7801818a87', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 1, '100125498', '最終日、スタート‼', 'インターハイ栃木県大会3日目。坂道たち総北の連覇を懸けた大会は、ついに最終日を迎えた。スタート前、キャプテンの手嶋を中心に士気を高めるチーム総北。御堂筋率いる京都伏見も、全員がボーズという異様なスタイルで現れ、覚悟を見せる。寝坊した真波も何とか間に合い、最終日のレースがついにスタート! 先頭争いに加勢するため、一秒でも早く前の今泉に追いつきたい坂道は、得意のハイケイデンスを使い、全力でペダルを回す!', '2022/10/10 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c2e2ee0-3c03-4262-882c-1aea59056e7d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d4adad0-8f14-4897-bc5e-b3604319c7a2', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 2, '100125986', 'ピラニア', '先頭を走るエースたちに追いつくため、一時的に協調して走る総北と箱根学園。そこへ、先行していた京都伏見の御堂筋と水田が落ちてきた。レース早々の失速に驚き、理由を問い詰める鳴子。しかし、御堂筋は後方、熊本台一の井瀬を使い、密かにフェイズを進めていた。一方、御堂筋から今回のフェイズの重要な役割を任されていた山口は、ムチャぶりと複雑な心境の中、チームのために完遂する覚悟を決めていた。', '2022/10/17 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53aaffbe-e9c1-4456-a4e7-a6bd8eb98924.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c579427c-4939-40aa-b918-19fd4fa4c63e', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 3, '100127066', '共に進む力', '御堂筋の策略により、巨大なピラニアの群れとなった最終集団。次々と先行する選手を飲み込み、ついには協調していた総北と箱根学園へと襲いかかる! 動揺と混乱の中、集団に飲み込まれてしまった手嶋。必死に協調相手を探すが、御堂筋の裏切りにあった集団は失速してしまう。しかし、助けに来た青八木と合流し、手嶋に一筋の光が差し込んだ。二人は息の合ったコンビネーションで、前を追いかける!', '2022/10/24 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c2d6f63-5eec-46af-b1ed-366ddb1c410a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73bdbdc3-eeb7-4402-a1ef-3f6dc4bb6ed6', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 4, '100127367', 'チーム2人', '集団を飛び出し、前を追う手嶋と青八木に立ち塞がる京都伏見。山口は、御堂筋から託されたフェイズを完遂するため、手嶋と青八木に条件付きのスプリント勝負を仕掛けてきた。クライマーの手嶋には不利な勝負だが、受けなければ前には進めない。脚の痛みで全力のスプリントができない青八木を気遣い、前を引く手嶋の姿に、青八木は二人が出会った頃のことを思い出していた……。', '2022/10/31 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fb721c5-7029-4d7c-8e06-cbc4164a9aac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75fe041f-7493-440c-b165-0aa8ad091c8a', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 5, '100128082', '先輩', '京都伏見とのスプリント勝負を制し、見事チームとの合流を果たした手嶋と青八木。6人全員でのレースを楽しむ坂道たちだが、その時間は長くは続かない。箱根学園に追いつくため、全力でチームを引く青八木の脚は、前日からの痛みで限界が近づいていた。そんな先輩の背中を見て、涙が止まらない鏑木。青八木の 想いを受け継ぎ、チームのために走ることで、自らも大きく成長しようとしていた。', '2022/11/07 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23e979dd-e31d-4c44-84a1-4ff735bbbe10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2502318b-2de1-47a2-9bef-37e3e471de7e', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 6, '100128596', '銅橋正清のインターハイ', '山の入り口まで1km地点。青八木の決死の引きにより、先頭の箱根学園に追いついた総北。食らいつく鏑木とのスプリントバトルで消耗した銅橋は、限界が近づき、意識がトビながらも、一心不乱にチームを先導していた。かつては初めてのインターハイを恐れ、真波や荒北から必死に感想を聞き出していた銅橋。だが、今は自らの力を解放し、全力でレースを楽しんでいた――!', '2022/11/21 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ce2f411-a3fc-48fa-9480-a48497d1d900.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94fb0fbb-a9a0-4e19-81f1-3487e0e92eb4', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 7, '100129679', 'FINAL ROAD!', 'スプリンターたちに送り出され、最後の山へと突入した坂道たち。4人のクライマーがいる箱根学園から、次々と総攻撃を受ける総北だが、オールラウンダーに転向した鳴子の活躍もあり、何とかその場をしのぐ。しかし、峠の合間にある平坦道にさしかかかると、箱根学園キャプテンの泉田がチームを引いて一気に加速! エーススプリンター泉田の、筋肉を限界まで研ぎ澄ましたやりのような走りによって、総北は一瞬で引き離されてしまう!', '2022/11/28 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f3436af-af92-446d-9910-cec13500e5a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('887509bb-bf74-4baa-8f8d-47f5e2530848', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 8, '100130355', '手嶋のオーダー', '大会前、キャプテンの手嶋から、今回のインターハイでは「山のエースから外す」と言い渡されていた坂道。山でのファーストアタックで、箱根学園の強敵、真波を早めに潰すためのオーダーだ。しかし、泉田のスプリントによって予想外に開いた距離を埋めるため、手嶋は自らを犠牲にしてチームを引く。その一歩一歩全力で進む熱いバイブレーションは、坂道たちだけではなく、箱根学園のエース･葦木場にも伝わっていた……!', '2022/12/05 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5dba5a1e-4a09-46dc-8cb4-4b402cb8a5dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6abdba79-e725-4589-a9be-172242bbab1c', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 9, '100131622', '転校生', 'インターハイ最終日の山で、山岳賞を懸けた勝負を手嶋に持ちかける葦木場。小学生の頃、転校生だった葦木場は、音楽を通じて手嶋と仲良くなり、中学の時には同じ自転車部で走っていた。レースで中々結果を出せない二人だったが、手嶋は密かに葦木場の中に眠る才能に気付き、山岳賞を獲らせたいと考えていた。しかし、手嶋と一緒に走れるだけで楽しいと感じていた葦木場は、その気持ちに気付けないまま、二人はすれ違ってしまう。', '2022/12/19 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3870b499-d8f5-44e7-9857-2e544d32b756.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('713aedeb-828b-4d83-a175-cd953138a0ee', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 10, '100132295', '響きあう振動', '互いに一歩も譲らない、熾烈 (しれつ) な山岳賞争いを繰り広げてゆく手嶋と葦木場。しかし、葦木場に必死で食らいつく手嶋の脚は既に限界が近づいていた。ロードレースでは平凡な実力といわれた手嶋だが、一歩一歩努力する、実力を超えて無理をする走りこそ自分の必殺技だと信じ、ペダルを回す。その熱い走りを見た観客から“手嶋コール”が沸き起こり、葦木場からもその強さを認められた手嶋は今、予想外の才能を開花させる。', '2022/12/26 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83fc1fa6-adff-4484-8598-0c76570a2527.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9527c0c9-688d-4ba1-afeb-261e2b2c52b3', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 11, '100132296', '仰ぎ見た空', '中学のころから互いの目標であった山岳賞を懸けて闘う、手嶋と葦木場。中学3年の冬、自分の才能に見切りをつけ、自転車をやめると言いだした手嶋。葦木場はそれを阻止しようと画策するが、突然の転校でかなわなくなってしまう。高校では疎遠になった二人だが、葦木場は自転車さえ続けていれば、いずれ出会えると信じていた。そして今、再会を果たした二人は、積年の想いを抱えながら、インターハイ最後の山岳ゲートへと突き進む!', '2023/01/09 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c8f21ce-6ec8-4a15-90c2-c3715e66d1a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1bfe9a6-ec55-4bad-9e48-2f6d72c24f4c', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 12, '100134456', '来襲‼', '最終ゴールに向けて動き出した総北と箱根学園。クライマーの新開が登りのアタックで加速する中、オールラウンダーに転向した鳴子も、鋭い登りで対抗する。手嶋から最後のオーダーを託され、坂道たちは全力で前に進む! しかし、総北と箱根学園の2チームに絞られたかに見えたゴール争いは、後方から密かに機会をうかがっていた第三の脅威、京都伏見の登場によって混迷を極める!', '2023/01/16 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5dac394-b983-45f4-95fb-408614c56016.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c76c116-aa50-4ed0-9b4f-6ec14251bff4', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 13, '100134898', '新開悠人の覚悟', '突然の京都伏見の襲来に、かき乱されるゴール争い。先頭を追う御堂筋を止めるため、新開悠人が立ち塞がる。いつも強気で飄々 (ひょうひょう) としている新開だが、積み重なる勝負と重圧で限界に近づいていた。今までの自分だけ勝てばいいと思っていたレースから、箱根学園のジャージに勝ってほしいという想いに変わった新開。覚悟を決めて走るその姿を見ていた小鞠は、理屈を超えた新開の“にく”に興味を奪われていく。', '2023/01/23 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f08681d3-576f-42ce-a5b9-e63c38a04cea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28874e64-b8c6-47da-a1a5-c0f6ee4b48fe', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 14, '100135381', '鳴子VS真波 ギリギリバトル', 'ゴールを目指し先頭を走る坂道たち。黒田と真波が追うが、その後ろにはぴったりと鳴子が張り付いていた。鳴子はエースクライマーの真波に、登りで捨て身の勝負を仕掛ける! 坂道たちに先に追い着いた方が勝利、負けたら鳴子は黒田を抜かないというルールの下、二人のギリギリバトルが始まった! 去年より登れるようになった鳴子だが、真波の天性のクライムには及ばない。無謀な勝負に思われたが、そこには一縷 (いちる) の望みが…!', '2023/01/30 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d52e2deb-94cf-42c1-a1f8-ca8037a74c91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('387a644c-df56-484c-87f6-798526af4426', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 15, '100135382', '攻防! ダウンヒル!!', '先頭で坂道と今泉に合流を果たした鳴子。ドリームだと思っていた“3人でゴール”という約束の可能性に近づき、胸が高ぶる坂道。しかし、ここまで真波や新開と勝負してきた鳴子の体力は限界が近づいていた。後続の箱根学園は、黒田が猛烈なスピードで追い上げ、後ろの御堂筋も、ゴールを目前としたこの下りで、一気に勝負を仕掛けてくる! ハイスピードなダウンヒルで、熾烈 (しれつ) な先頭争いが始まった!', '2023/01/30 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6ecafc3-d70d-4b1d-b9d4-c973f5735e23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de9bd624-d051-47f3-a506-e1562f7d223a', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 16, '100135927', '鳴子特急‼', '捨て身のダイブバンクで一気に先頭に躍り出た御堂筋。ゴール前の最終局面で200m以上の距離を奪われてしまった総北は、“鳴子特急･最終便”で御堂筋を追いかける! 全ての物を軽量化し、意識が遠のきながらも前を追う鳴子の姿に、もう3人でのゴールはないことを悟る坂道。覚悟を持って走る鳴子に、今泉と坂道は全力の感謝で言葉を贈る。二人の想いを受けとった鳴子は最後の力を振り絞り、根性の走りを魅せる!', '2023/02/06 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1254e947-16f8-45df-8de7-657e750e6204.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3168d86-1bb7-4aca-9b7c-0962153dd797', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 17, '100135928', '変わる風向き', '尾根沿いの下りに入ったインターハイ最終日、ゴールまで残り4.5㎞。鳴子が決死の覚悟で残してくれた先頭ポジションを守る為、御堂筋に勝負を挑む今泉。これまで何度も御堂筋に心を砕かれながらも、チームの支えの中で成長を遂げてきた今泉は、御堂筋のギリギリの戦法にも動じず、エースの走りを見せる! しかし、ゴール前最後の下りで突然の雨! 今泉VS御堂筋、雨の中、二人のハイリスクな因縁のバトルが開幕する－－!', '2023/02/06 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f845078c-edb0-44a5-a5a1-ac07d7725ed6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57d4d9f2-89c3-4309-be01-2061c3529089', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 18, '100136638', 'ウォーターゲートダイブ', '突然の雨の中、下りでのハイリスクバトルとなった今泉VS御堂筋。お互い先頭を一歩も譲らない攻防の中、自らのリミッターを跳ねのけて突き進む今泉。一方、後方の坂道も、慣れない雨での下りに苦戦しながら、総北のワンツーフィニッシュを目指し、全力で今泉を追いかける。レースは土砂降りの中、今泉と御堂筋は、巨大な水たまりができた下りを、全力ダイブで駆け下りる!', '2023/02/13 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e337ce9f-a077-4fc6-ad70-f2ef77d00890.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e43f876-611c-4c17-b454-89751fbdeac9', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 19, '100137280', '最後のオーダー', '雨の中の死闘を制し、先頭を走る今泉。坂道も合流し、トップを独走する総北の状況に、杉元たちサポートメンバーも歓喜する。このままワンツーフィニッシュを狙う二人だが、その背後からは箱根学園の黒田と真波が迫っていた。黒田に背中を押され、一気に先頭へと飛び出した真波。その危機的状況に戸惑う坂道だが、チームのためにできることはただ一つ。坂道は、今泉から最後のオーダーを託される……!', '2023/02/20 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88adecf3-dab6-410f-872c-9a26715403fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('740941b0-e9eb-4ede-912e-bdd19236936d', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 20, '100137973', '5月の水族館', 'ゴールまで残り2㎞。今泉から最後のオーダーとしてゴールを託された坂道は、覚悟を決めて真波を追う。インターハイ前の春先、偶然レース帰りに立ち寄った水族館で再会した、坂道と真波。二人はそこで、夏のインターハイ、出しおしみの無い勝負をしようと約束する。そして、図らずもこのインターハイ最終日のゴール前で闘うこととなった二人は、戸惑い、チームの勝敗を背負いながらも、運命的な勝負の瞬間に胸を高ぶらせていた。', '2023/02/27 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33e1797e-fdee-44ed-b62b-93bb64c8938a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93e74c28-e13e-48cf-aa8d-7d2f35a31d6b', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 21, '100138630', 'スイッチとハナウタ', '坂道と真波のゴール争いが始まる少し前、引き離された先頭に真波を運ぶ黒田。1年前、予選で真波に負けて腐っていた黒田は、荒北から部を託されたことで、再び箱根学園を王座へと引き戻す決意した。“スイッチ”によって鋭い走りを見せる黒田は、脚の痛みに耐えながら、最後、自身の想いを真波に託し、背中を押した。羽根を広げて加速する真波。一方、引き離される坂道は窮地の最中、なぜか頭には“ハナウタ”が流れていた!', '2023/03/06 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff8dc8d5-b456-41ba-af4c-7b3defef7adb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0ed6b37-64cd-44d4-8dda-655be97c7d29', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 22, '100139869', '声、届け', '応援に駆け付け、ゴール前の山道で真波を待つ委員長。1年前のインターハイの後、総北に敗れ傷心する真波に、委員長はどう接したらいいかわからずにいた。体が壊れるくらい練習に明け暮れる真波が心配になり、東堂に相談するが、真波が負った深い傷はすぐには回復せず、今は見守ることしかできないと返される。それから1年間、ずっと真波を見てきた委員長は、大会が近づくにつれ、真波が一つの答えにたどり着くのを感じていた。', '2023/03/13 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec3a4396-65b0-408c-876c-2981af6f2e1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0af0c915-ad42-4cdf-a967-3a9c26311eaf', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 23, '100140433', '金城、最後の仕事', 'ゴールまで残り700m。拮抗 (きっこう) 状態で削りあう坂道と真波の闘いに、レースを見守っていた荒北は、真波が勝つと予想する。敗北を知り、地の底からはい上がった真波こそ、ゴールをつかむ資格があると宣言する。それを聞いた金城は、この1年、坂道も大切な存在を失い、失意の中にいたことを明かす。世界一尊敬する巻島との突然の別れで道が見えなくなっていた坂道。金城はそんな坂道を海へと誘い、ある出来事を話す……。', '2023/03/20 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93bb8ee3-75c9-454c-8e2f-7ba4dc6e1f51.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4341813e-5779-4ffc-b5eb-79d47b89f2a6', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 24, '100140861', '二人のラストスプリント', '金城から、総北はつらい時こそ支えあうチームであること、巻島がイギリスで手紙を読んでいることを聞いた坂道は、その日から驚くほど回復していった。その話を聞いた荒北は、坂道にもまた、ゴールをつかむ資格があると知る。ゴールまで500m、懸命に走る坂道と真波に、先輩たちが最後のエールを送る! 巻島の言葉に後押しされ、最後の気力を振り絞る坂道。それぞれの想いを胸に、二人はラストスプリントでゴールを狙う……‼', '2023/03/27 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a493ab59-6685-439a-afa8-711a87663bf3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b141cc6-08c6-45a6-9395-fee29041ce3e', '1778b66b-f291-4cd6-9a50-c8107fb0e6c5', 25, '100140862', '大空に手を挙げた者', '【第5期 最終話】坂道VS真波、ゴール目前のラストクライム! チームのジャージを託され、仲間の想いをつないで走る坂道と、過去の自分を超えて、雪辱を果たすという誓いを胸に走る真波。それぞれの想いを背負い、全開全力、最後の力を振り絞って走る二人。皆が見守る中、ついに、車輪はゴールラインを越える! 長かった3日間のインターハイ。その頂を制し、最後に大空に手を挙げるのは、果たして－－。', '2023/03/27 20:00:00', 1495, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95791456-6f9c-476f-8e20-bcd1dcc47a3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('34c6c067-b04c-482f-95d8-876eb4042d14', '弱虫ペダルNEW GENERATION', '', 'hulu', 'yowamushi-pedal-new-generation', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ecab091-4426-4235-883f-988fc9d06272.jpg?w=331&h=447&p=t', 'hulu', 2017, 0, 1, 'FINISHED', NULL, 21407, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ef0e0632-65c7-49bc-a516-8bebd9036908', '34c6c067-b04c-482f-95d8-876eb4042d14', 'hulu-yowamushi-pedal-new-generation-s1', '第3期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff340d7d-000b-4d99-94d2-973ecc31cbe4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db651f82-bd91-4c66-ab4c-b450ae60e2f8', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 1, '100089055', '最後の峰ヶ山', 'インターハイでの激闘を終えた、総北高校自転車競技部。1年の小野田坂道は、同級生の今泉や鳴子と共に、ニューバイクに乗り換え、3年生が抜ける新生チームとしての新たな闘いに向けて走り出していた。総北の新キャプテンに任命された手嶋も、盟友の青八木と共に連覇を目指し動き出す。そんな中、坂道は憧れの先輩である巻島から、ある事を告げられる…。', '2025/05/01 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff340d7d-000b-4d99-94d2-973ecc31cbe4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('351e0bbe-7842-40b9-895b-ba1f01c8600c', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 2, '100089056', '巻島が残したもの', '巻島が卒業を待たずして部を退部し渡英するというショックから抜け出せず、一人調子が上がらない坂道。練習でも空回りしている坂道に、同じく巻島からクライマーとしての魂を受け継いだ手嶋が「ゆっくりでいい」と語りかける。一方、箱根学園も新キャプテンに泉田が任命され、今年の雪辱を果たすべく新生チームが始動。その中には新たなメンバーが…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5420683b-764a-43b8-9d70-2989034c7784.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2625320f-30d0-4e58-85eb-f5f3a83d537f', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 3, '100089057', '手嶋、魂の走り', '秋の「峰ヶ山ヒルクライム」に出場する総北高校の坂道、今泉、手嶋。インターハイの優勝者として注目を集める坂道だが、不調から抜け出せず、不安で萎縮してしまう。一方、箱根学園は2年生の葦木場拓斗を送り込んできた。202cmという長身を活かした“メトロノームダンシング”で他を圧倒する葦木場に対し、総北の新キャプテン･手嶋が魂の走りで挑む!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/107e4ce0-9cff-4fd5-b23f-762ff82b79bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5da14f16-dcd0-4352-ad84-433f30a91920', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 4, '100089058', '峰ヶ山で一番速い男', '峰ヶ山ヒルクライムレースで手嶋が見せる魂の走りに熱い鼓動を感じた坂道は、自らを奮い立たせ懸命に葦木場を追う! 果たして勝負の行方は…!? レース後、3年生の福富と顔を合わせる葦木場。彼にはある過去があり…。後日、田所の卒業レースとなる「湾岸クリテリウム」が開催。“総北スプリントスピリッツ”を持つ田所、鳴子、青八木の三つ巴の勝負が展開する!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7188456-780f-4069-bcb5-faa80b5497a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d83a941b-8748-4ec4-bb90-342788852870', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 5, '100089059', '自転車異種格闘技場!!', '順調に滑り出したと思える新生総北だったが、今泉は3年生が抜けてチーム全体のレベルが下がることを懸念していた。そして鳴子に対して、チームが勝つためにオールラウンダーになれと言い放つ。自分はスプリンターであると反発しつつも、先輩の抜けた穴の大きさを痛感していた鳴子は、ある決意を胸に地元大阪に向かう。一方、総北の練習に1人の中学生が参加する。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbb5b9c4-4e43-4c09-b287-a51702bcefd9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45fa44c3-4f04-4d8e-9672-27bbffb78be0', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 6, '100089060', '鳴子vs御堂筋', '総北を強くする答えを求め、地元･大阪で草トラックレースに参加する鳴子。スピード自慢のスプリンターたちを蹴散らし、自分が強くなっていることを実感する鳴子だったが、そこに京都伏見高校のエース御堂筋翔が現れる。「大切なもの」を賭けた勝負を持ち掛ける御堂筋に、鳴子は全力のスプリントで挑む! そして御堂筋も更なる強さを求めていた…!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38a52772-34c7-477c-b57d-44c928c1b887.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8dd37256-7729-46eb-b3fc-b1f5cc67d332', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 7, '100089061', '最後の走行会', '箱根学園では、伝統の3年生追い出しファンライドが行われようとしていた。120kmにも及ぶファンライドは、スタート早々福富たち3年VS泉田たち新世代の本気レースに! 箱根学園の“王者”としての意志を受け継ぐため、そして憧れである3年たちを超えようとする新世代と、それを迎え撃つ3年生。まずは泉田と新開のエーススプリンター対決がスタートする!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d36e032-2cd0-466b-b77f-144ff02946b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67bec60e-6e9e-402e-ac77-f1cfea099c49', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 8, '100089062', 'ゴールライン', '箱根学園恒例の3年生追い出しファンライド。福富ら3年に「今から超えます!」と宣言した泉田は新開と対戦し、成長した姿を見せつける。そしてレースは山岳区間に突入、東堂と真波のクライム勝負へ。どこか思い悩む様子の真波に、東堂が語り掛け…。一方、福富と荒北、葦木場と黒田のエースとエースアシストのコンビ同士も熱い火花を散らす!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61a1487b-db04-42e7-b7a5-f6d0f639dd07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27b83c16-42d8-421f-8830-166ca882125e', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 9, '100089063', '新生総北、始動!', '2年に進級した坂道、今泉、鳴子。インターハイで優勝した総北自転車競技部には、多くの新入生が入部し、手嶋や青八木も手ごたえを感じていた。しかし、初めて部の先輩となった坂道は戸惑うばかり…。そんな新入部員の中には、中学から活躍していた鏑木一差と段竹竜包の姿も。2人は「1年生レース」でのワンツー優勝でインターハイのメンバー入りを狙っていた!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ce2511e-f17b-461e-b6e8-66f12fa8fea7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cdfc56fe-4383-41bc-ace3-a5348d785568', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 10, '100089064', '杉元兄弟の絆', '総北自転車競技部恒例の1年生ウェルカムレースが始まった。その中には2年生杉元の姿が。ひそかに練習を重ね、レギュラーの座を狙う杉元に、今泉たちもエールを送る。しかし、同じくワンツーフィニッシュによるインハイメンバー入りを狙う鏑木と段竹は凄まじいスピードでレースをリードする。それでも諦めない杉元は、弟･定時と一緒に2人を追い上げていく!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7b9241f-fca6-4d4f-be5c-48e6be7b608c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f756e793-64f0-48e0-b917-ee236ac2066b', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 11, '100089065', '決着', '混戦となった1年生ウェルカムレースは、大本命の鏑木と段竹、そして弟･定時とのシンクロ走法で驚異の追い上げを見せた杉元によるゴール争いへと突入! レースを制したのは…鏑木! 敗れた杉元は鏑木に想いを託す。インターハイ出場を目指す総北のレギュラメンバーの座を勝ち取った鏑木は期待に胸を膨らませるが、一方で先輩らしくない坂道に不満を抱いていた。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a09fe31c-bfeb-4b7b-8cf6-2424c957b5dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1943d4bc-f5b2-4d92-9330-bacd6d034fc0', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 12, '100089066', 'トラブル!', 'インターハイ千葉県予選。高校の公式戦デビューとなる鏑木は自分がエースとして走ると意気込むが、段竹と離れ1人で走るプレッシャーから腹痛に襲われる。レーススタートから勢い良く飛び出す鏑木だったが、パンクトラブルに見舞われてしまう。果たして総北はインターハイに出場できるのか…!? そして、王座奪還を目指す箱根学園、御堂筋の京都伏見も動き出す!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0aa81f3-9e55-4cab-994d-e706943a3013.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0973bb2-0064-417b-a8eb-2c64cdff8cd5', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 13, '100089067', '1000km再び', 'インターハイ出場を決めた総北は、最後の強化を図るために地獄の1000km合宿へと突入する! 4日間で1000km走破という過酷なメニューに、合宿初参加の鏑木たちは戸惑いを隠せない。一方、車酔いで参加が遅れていた坂道の前に、3年生の古賀公貴が現れる。これまでメカニックなどで部を支えていた古賀は、ある決意をもってこの合宿に参戦してきていた。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/840c11c8-afc5-49f4-97e1-df3b572c81df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f727a519-e234-465c-9291-c9f7918bcab1', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 14, '100089068', '凡人と天才', '手嶋と古賀によるインターハイメンバー入りを賭けた勝負が始まった。力強い走りで手嶋を追い込んでいく古賀にはある過去があった。一方の手嶋も必死に食らいつく!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3bdef12d-aed2-48d1-8d96-19da6402739f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0787320-130b-42cc-93bb-7ccae458d03d', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 15, '100089069', '古賀のゴール', 'インターハイメンバーの座を賭けた勝負を制したのは、手嶋だった。敗れた古賀は熱い意志を6人に託す。そして、総北の合宿所に、意外な2人が姿を見せ…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f7777ac-f8f3-4f1c-ae85-cb67f75fc6c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81016044-2f1b-4fd4-92b4-86015e9eb221', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 16, '100089070', '2度目のインターハイ', 'いよいよインターハイ当日! 連覇を目指す総北、王座奪還を狙う箱根学園、御堂筋率いる京都伏見と、強豪が集う。そんな中、鏑木は箱根学園のある男と遭遇する…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a8a8a28-ec26-4620-817b-2f5c7f849f44.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f1cc059-c94e-4ccb-97a5-d76c1cc89322', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 17, '100089071', 'スタート!!!', 'スタート直前、御堂筋は京都伏見のメンバーに岸神小鞠を急遽組み込んだ。その岸神は今泉に近づき…。一方、箱根学園の6人目のメンバーがいよいよ明らかになる!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68acb29f-d863-4476-b758-4a975fc4285c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56b7635f-4625-409d-9d99-c90a28b8eb20', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 18, '100089072', 'ふくらむ青八木', 'インターハイがスタート! まず各チームが狙うのはスプリンターたちによるファーストリザルト。箱根学園からは“怪道”銅橋が、総北からは青八木と鏑木が参戦する!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/529242fe-0564-4296-9428-fa8b7912ea91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a16b0e9a-a82f-4b21-ba09-966618f7fbe8', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 19, '100089073', '怪道銅橋', '箱根学園の“怪道”銅橋と、総北の青八木･鏑木コンビのスプリントバトルが始まった。予想以上の走りを見せる鏑木に対し、銅橋も自らの感情をむき出しにした走りを見せ…!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a54f302-d44b-4572-b723-7d9e83b85c36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1357b775-973c-4c65-8dc5-25da452ea3af', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 20, '100089074', '鏑木、全開!', '銅橋が背後に迫る中、青八木は新たな必殺技で力を振り絞るが、解き放たれた銅橋に追いつかれてしまう。しかし、その背後に鏑木の姿が…! ファーストリザルト、決着!', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db77a8d0-8a8e-46ec-a5ef-9ce0c6360b6c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b6e5f3e-bd9c-4e8f-a3d4-2be47ca56043', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 21, '100089075', '箱根学園、動く!', 'ファーストリザルトを銅橋が獲りいよいよ箱根学園が動き出した。後続を引き離そうとする箱根学園に総北も必死に付いていく。そして箱根学園のある作戦が襲い掛かり…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/46879257-ab5a-4384-a802-e2674097182b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0eb8127-49aa-438b-981a-359f6ab4903c', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 22, '100089076', 'ゼッケン1のプレッシャー', '集団にのまれ、さらに他チームからの徹底マークで坂道は身動きが取れない。そして先頭は山岳ステージへと突入し、箱根学園は真波が飛び出す。そして総北からはあの男が…!?', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9633a71-e9a4-4158-b697-b71d95ba110b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5065ce13-fa8c-4b76-9cd9-f8d714fc6f9a', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 23, '100089077', '坂道、追撃', '集団にのまれた坂道だったが、手嶋とチームを助けるために、大好きなアニソンを歌いながらグングン加速する! しかしそこに御堂筋の京都伏見が立ち塞がり…!?', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d971c5e3-f4d0-472f-985e-3fb9048aeb52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3242e48f-9654-4530-bcd7-b6e08d619583', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 24, '100089078', '雑草の走り', '山岳賞を狙う真波を追って、いろは坂を必死に登る手嶋。真波は手嶋の平凡な走りに興味を持てなかった、手嶋は執念で食らいつく。その熱い姿に応える真波は…。', '2025/05/01 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39f3c812-e4a1-4e2a-a0b0-77ef7c510aa1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6006828-49a5-429e-9380-e108de3717e6', 'ef0e0632-65c7-49bc-a516-8bebd9036908', 25, '100089079', '空を仰ぐ', '【第3期 最終話】山岳賞のリザルトラインまであとわずか。全開の真波と限界の手嶋の争いの中、真波にトラブルが!? 手嶋は全力でペダルを回す! インターハイ1日目の山を制するのは!?', '2025/05/01 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16923e3b-cbf5-45a6-b442-7b31aa2ac519.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('04870399-e885-4eaa-aea1-b5a42d0317d5', '呪術廻戦', '', 'hulu', 'jujutsu-kaisen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1dcc18b6-b849-453a-9dce-8f53ea31524b.jpg?w=331&h=447&p=t', 'hulu', 2020, 3, 1, 'FINISHED', NULL, 113415, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1ee6859f-3d50-4153-8986-9ebb21a3ece8', '04870399-e885-4eaa-aea1-b5a42d0317d5', 'hulu-jujutsu-kaisen-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a23e38a-ff72-4d2e-896a-b4a5339f90e6.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe7fc2dc-3983-418e-831a-c13cb71a348c', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 1, '100066127', '両面宿儺', '並みはずれた身体能力を持つ高校生･虎杖悠仁。祖父が死んだ夜に呪術高専一年の伏黒 恵と出会う。彼は、虎杖の持つ“呪物”を回収しに来たというが、ちょうどその“呪物”は虎杖の先輩らによって封印が解かれていた。“呪物”が引き寄せた、呪いの化け物に襲われる先輩たち。そこに虎杖と伏黒が駆けつける。', '2020/10/04 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a23e38a-ff72-4d2e-896a-b4a5339f90e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ddd3d07c-f3c5-45a8-8cf8-8dd99d8d7680', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 2, '100066644', '自分のために', '見知らぬ部屋で目を覚ます虎杖は、目の前にいた呪術高専の教師･五条 悟から自分の“秘匿死刑”が決定したと告げられる。五条は、虎杖に二つの選択肢を示す。今すぐ死刑になるか、『両面宿儺の指』20本を探し出し、すべて取り込んだのちに死ぬか――。', '2020/10/11 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97007cc5-8943-4cc9-a682-cfe45f86db5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aca3aa64-68c0-47b1-ba26-4be49a76d2da', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 3, '100066870', '鉄骨娘', '3人目の一年生、釘崎野薔薇を迎えに行く虎杖と伏黒、五条。そのままとある廃ビルへ向かい、五条は虎杖と釘崎に、廃ビル内に潜む呪霊を祓ってくるよう課題を与える。ビル内、二手に分かれて呪霊を探し始める虎杖と釘崎は、子どもを人質にとる狡猾な呪霊と対峙する。', '2020/10/18 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16e0421c-166d-4db0-9ce9-c5cf9c33c02f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27bc78f6-980c-4c2c-9045-eae6694db331', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 4, '100067321', '呪胎戴天', '少年院で起きた緊急事態に、虎杖、伏黒、釘崎が派遣される。任務は、いずれ特級呪霊に成り得る呪胎とともに取り残された生存者の確認と救出。乗り込んだ虎杖たちは、無慈悲な現実に直面する。直後釘崎の姿が消え、残された虎杖と伏黒の隣には、特級呪霊の姿があった。', '2020/10/25 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d1866ff-01be-4965-a7e0-2284dbf1e50e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ec32eb9-bc0a-4384-a55c-01d6ce244778', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 5, '100067590', '呪胎戴天－弐－', '少年院の外に退避した伏黒は、特級呪霊の死に気付く。次の瞬間、横に両面宿儺が現れ、虎杖の体から心臓を抜き取り、人質にする。このままでは虎杖の意識が戻っても死んでしまうと戦い始める伏黒だったが、格の違いを痛感する。', '2020/11/01 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20b40644-b053-4e83-a861-1a97e0c9b8be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8289efee-4e28-4269-bdb1-4b741cfb94f8', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 6, '100068620', '雨後', '虎杖の死に悔しさをかみしめる五条。仲間の死に沈み込む伏黒･野薔薇は強くなるために2年生達と特訓を始める。一方、夏油達も動き出す。そんな中、死んだはずの虎杖は――。', '2020/11/08 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c5f41b8-ed65-4479-9a3a-d4af0c801d3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7790f124-5448-4dc8-a3ff-67903fa4323a', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 7, '100068840', '急襲', '移動中だった五条は、特級呪霊･漏瑚の奇襲を受ける。攻撃を重ねても決して当たらない――漏瑚は、すぐに五条の強さを目の当たりにする。一瞬で高専に戻り、修行中の虎杖まで連れてくる余裕の五条に、漏瑚は怒りを爆発させ、ある手段に出るが、対して五条は――。', '2020/11/15 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0661f43-5d5e-45e2-b3e4-7ca581b84627.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd28d691-1cc0-4351-b296-008f3e7fd001', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 8, '100069735', '退屈', '交流会に向けた特訓の合間。釘崎と伏黒の前に、呪術高専京都校二年の禪院真依と東堂が現れ、二人にケンカを吹っ掛ける。伏黒を腕っぷしで押していく東堂。一方、真依の言葉に嫌悪を抱き、釘崎は真依を挑発するが――。', '2020/11/22 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/511e51f5-1b6d-4e9a-be31-90491345e940.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0c6433b-a323-4f42-94e3-ab8207366f41', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 9, '100070548', '幼魚と逆罰', '高校をサボり映画館に来た吉野順平は、自分をいじめていた同級生が顔を変形させられ、死んでいるところを目撃する。“犯人”を追い、声をかける吉野。その後、事件現場の映画館に乗り込んだ虎杖と脱サラ一級呪術師の七海建人は、2体の呪霊に遭遇する。', '2020/11/29 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/112a3ca9-399b-4bd5-8b0a-43836c26d102.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9260e0d-db14-4947-bade-469ed4641ca1', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 10, '100071076', '無為転変', '吉野の調査を任された虎杖は、補助監督の伊地知に作戦を聞く。低級の呪いに吉野を襲わせ、反応を確かめるというが作戦は失敗し、虎杖は吉野に直球で声をかける。結果的に嫌悪する担任教師を追い払ってくれた虎杖を見て、吉野は話を聞く気になる。一方、真人のアジトを突き止めた七海は地下水路で真人と相まみえるのだった。', '2020/12/06 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0552395-dec9-4247-b748-0f6308762c42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('272a6258-b5ef-4ca9-8194-8f2964d1545f', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 11, '100071565', '固陋蠢愚', '真人に追い詰められた七海は呪力の制限を解除、十劃呪法『瓦落瓦落』で地下水路の壁を破壊し、がれきの雨を降らせる。一方、吉野と接触した虎杖は、映画の話で意気投合する。吉野の母とも会い、家に招かれるとさらに打ち解けるのだったが…。', '2020/12/13 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28fed564-88f6-4274-bcf9-e210baf3e2db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88187f49-79ec-4e66-be11-3e688024e2c3', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 12, '100071803', 'いつかの君へ', '真人に心酔していた吉野は、上手く利用され虎杖と戦うように仕向けられていた。復讐に走り暴走する吉野に対し、虎杖は拳を重ねながらも動機を聞き出し説得しようと図るが、吉野の口から残酷な事実を知ることになる。そんな二人のそばに真人が忍び寄り――。', '2020/12/20 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/000405ba-86ab-4222-9864-dcc9c16e772e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('385ce86a-5be2-4503-bbf2-67b778070dca', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 13, '100072132', 'また明日', '間一髪で真人の一撃を防ぎ虎杖を救った七海。ここで確実に真人を祓うため虎杖と七海は息の合った攻撃を重ねる。真人は改造人間を使い虎杖を精神的にも追い詰めようとするが、虎杖はそれを乗り越える。畳み込まれる攻撃に追い込まれた真人は「死」を感じ――。', '2020/12/27 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e03a3a9-1b38-443e-baf3-0e404c104ca2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15b394e3-c8c3-40be-b030-234cf59f0c5e', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 14, '100073213', '京都姉妹校交流会－団体戦 (0)－', '虎杖たちから逃れた真人は、夏油らと合流し、あるプランを進めようとする。一方、呪術高専では“京都姉妹校交流会”が行われようとしていた。伏黒と釘崎、二年の真希、棘、パンダが集合するが、そこに東堂ら京都校の面々も到着。早速一触即発な空気の中、さらに遅れて五条が駆けつけあるサプライズを行う――。', '2021/01/17 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93a82d08-b7c1-463f-bb6b-0d37b140bfdc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('689a09ea-5030-4be7-a639-0f6339d8f764', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 15, '100073669', '京都姉妹校交流会－団体戦 (1)－', '京都姉妹校交流会の団体戦が始まった。東京校のメンバーに、京都校の東堂が襲い掛かるが、足止め役を任されていた虎杖が相対する。東堂のパワーに圧倒される虎杖だが、突然東堂から女の趣味を尋ねられ――。', '2021/01/24 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78beaa81-b906-4c55-be7e-21a86899d366.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('682ca68e-9d98-4aa7-be86-0c7d14817987', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 16, '100074239', '京都姉妹校交流会－団体戦 (2)－', '東堂は、虎杖の“逕庭拳”が特級には通じない技だと指摘する。助言を素直に受け取る虎杖に対し、東堂は全力で相手をし、導いていく。一方、京都校の西宮に、釘崎はケンカを吹っ掛ける。その横にいたパンダに、陰から攻撃を仕掛けるメカ丸。釘崎と西宮、パンダとメカ丸の戦いが始まる。', '2021/01/31 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/336908e2-0269-4d60-bc70-ae969791b29e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9c2cfd3-dcf8-444a-addb-dbeb530a99b2', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 17, '100074531', '京都姉妹校交流会－団体戦 (3)－', '交流会団体戦は続く――。対峙する真希と三輪。三輪は真希の等級には表れない圧倒的強さに驚きを隠せない。同じ頃、箒で空中を飛び回る西宮を追う釘崎。真依の苦労、女性呪術師として生きていく意味を語る西宮をバッサリ切り捨て、一気に反撃に出る。そして姿が見えない真依は――。', '2021/02/07 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8db8ba13-c9eb-4311-856e-4bf5e80a8672.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6be55658-a700-4af4-a8fc-5701169085c6', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 18, '100075372', '賢者', '各所で勝敗が見え始めた交流会1日目。伏黒は御三家の嫡男･加茂と対峙していた。自身の血を操る「赤血操術」を使う加茂に、伏黒は式神と体術で対抗する。同じ頃、狗巻の言霊の増幅･強制術式である「呪言」を生かして場を進めていく。その狗巻が突如感じた不穏な気配に振り返るとそこには――。想定外の事が起こり始める交流会。戦いの行方は――。', '2021/02/14 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4016b96f-828d-4a48-90fb-442e976d56e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffdbdf52-6153-492c-b747-99ee7f6152f2', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 19, '100075882', '黒閃', '交流会に突如乱入し、襲い掛かる特級呪霊･花御。対峙する伏黒と狗巻、加茂は花御の攻撃を防ぎながら、帳の外に向かって走る。追い詰められる3人だったが、そこに真希が参戦し、伏黒との連携で攻め立てる。しかしそれでもなお、特級呪霊である花御の圧倒的な戦闘力を前に窮地に立たされてしまうが――。', '2021/02/21 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84caff19-0700-41e7-bab5-c0d0afbaefc4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8aaaa8ce-e913-42f7-9f2b-0db915c53090', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 20, '100076361', '規格外', '花御との戦いに参戦した虎杖と東堂。虎杖が黒閃を決め、東堂との連携プレーで攻め立てていく中、さらに自身の術式を解禁する東堂。超親友となった虎杖と共に、東堂はトリッキーな術式と (自称) IQ53万の脳内CPUを持つそのクレバーさで花御を翻弄していくが――。', '2021/02/28 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4522ebe-67dc-4dea-9e61-17b7acdc38a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6cbb8966-d216-4d3b-9c69-2b5e8beda61c', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 21, '100077042', '呪術甲子園', '圧倒的な強さで五条は花御を退けた。瀕死の花御と合流した真人は、「両面宿儺の指」と特級呪物「呪胎九相図1番～3番」を強奪。着実に10月31日に決行する五条悟封印の準備を進めていた。一方、高専サイドは真人らの目的を明らかにできない。被害を鑑み、そのまま交流会も中止、となりかけるが、何故か野球で決着をつけることに。姉妹交流会･2日目野球戦、プレイボール――。', '2021/03/07 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03997c0a-46b2-4617-9f55-12ae49868189.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f046845-cdf2-4434-b6b7-25248cde4d2f', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 22, '100077675', '起首雷同', '呪霊により3人の男が似た状況で死亡する事件が発生。被害者たちは同じ中学校に在籍していたことが判明し、虎杖、伏黒、釘崎はその調査に派遣される。現地に着いてみると、その中学校は伏黒の母校であった。被害者らは地元の心霊スポット「八十八橋」の下で揃って倒れていたことがあったと聞く。さらに伏黒の姉･津美紀も事件に巻き込まれていたと分かり――。', '2021/03/14 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3af84407-8040-4699-aeca-4841778317a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee03e04a-9087-465b-91b9-203802fe8112', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 23, '100078188', '起首雷同―弐―', '八十八橋の呪いに加え特級呪物「呪胎九相図」の1体･血塗 (けちず) と対峙する虎杖･伏黒･釘崎。八十八橋の呪いの結界内にいる伏黒たちだが、突如釘崎が腕を引かれ、結界外に消える。それを追い、出ていったもう一体の血塗と虎杖も外へ。残った伏黒は早々に八十八橋の呪いを片付けるが――衝撃の光景を目の前にする。一方、釘崎は「呪胎九相図」の1体･壊相 (えそう) と対峙。そこに血塗 (けちず) と、追ってきた虎杖も加わり――。', '2021/03/21 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1675cc82-65b0-4467-9ea9-82d00addf1fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5eb386ab-9f18-41df-8806-2d65ae6b4939', '1ee6859f-3d50-4153-8986-9ebb21a3ece8', 24, '100078620', '共犯', '【シーズン1 最終話】「呪胎九相図」兄弟の壊相･血塗に対する虎杖と釘崎だったが、壊相･血塗の血を浴びてしまい体内から腐食が始まる。窮地に立たされるも釘崎は自らに釘を刺し、「共鳴り」を発動。兄弟との我慢比べが始まる。虎杖も止まらず血塗を攻め立てていくが――。「両面宿儺の指」に端を発した今回の任務。果たして虎杖･釘崎･伏黒は無事高専へ帰還できるのか――。', '2021/03/28 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/46319b2c-30fd-4b49-84ad-dae0479e7bf3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b51bbb8e-d9b5-458c-b02c-648e58959fef', '呪術廻戦 第2期', '', 'hulu', 'jujutsu-kaisen2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3acc62dc-aab1-4bcd-a3da-29bb815f296f.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 145064, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('344a93a0-9865-43f5-a2e5-c38fefdf39a3', 'b51bbb8e-d9b5-458c-b02c-648e58959fef', 'hulu-jujutsu-kaisen2-s1', '第2期 懐玉･玉折／渋谷事変', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/acfc4e2b-0048-43a1-b755-619deb0fe3e2.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f822364-96ef-469e-aecc-675bfaf525b2', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 1, '100151407', '懐玉', '行方不明者が多発する曰くつきの洋館の調査に派遣された術師の歌姫と冥冥。洋館に潜入し、呪霊の結界術に気づいた二人は、結界を破るための行動に出るが、突如建物が崩れ始めてしまう。宙に放り出されたその瞬間、目の前に現れたのは――。2006年。最強の2人の、もう戻れない青い春が始まる。', '2023/07/07 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/acfc4e2b-0048-43a1-b755-619deb0fe3e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('586d9e50-fb00-4d95-b6d3-5e76b6f06ac0', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 2, '100152412', '懐玉－弐－', '天元との適合者である“星漿体”、その少女の「護衛」と「抹消」という任務を課された五条と夏油。“星漿体”･天内理子を狙うのは呪詛師集団『Q』、そして天元を崇拝する宗教団体、盤星教。ホテルでの急襲を退けた五条と夏油は天内の意向で、使用人の黒井と合流し、天内の学校へ向かうことに。そして、新たな刺客の存在が明らかになる――。', '2023/07/14 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/069a1c6b-667d-4c34-8d4b-59d7fdd0af17.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cbeef525-fbd9-49d2-8502-5d1756249b8a', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 3, '100153309', '懐玉－参－', '天内の懸賞金を狙う呪詛師たちを退けた五条と夏油、すると突如震えだす天内の携帯。そこには捕らえられた黒井の姿が。拉致犯が人質交換をもちかけてくることも考慮し、天内を高専へ連れ帰ろうとする五条。しかし、天内は自らも取引に行くと啖呵を切り、五条･夏油と共に取引の指定場所へ向かうことに――。', '2023/07/21 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21a8f5e6-962d-4223-846a-61a207edaf2d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b91b64c-9a97-424b-b988-2aca2f9e6827', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 4, '100153784', '懐玉－肆－', '「帰ろう、理子ちゃん」夏油が天内に手を差し伸べたその刹那、最悪の事態が起きてしまう。呆然と立ち尽くす夏油の前に、伏黒甚爾が姿を現す。甚爾は夏油にこう告げる。「五条悟は俺が殺した」激昂した夏油は呪霊を召喚し、甚爾に畳みかけるが――。', '2023/07/28 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac8ab3fa-ac86-4db0-95ad-1ed94e4bbd9c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d03b491-c53a-4b88-84b2-f2b005eb16be', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 5, '100154690', '玉折', '『2007年8月』。五条は“最強”に成り、任務もすべて1人でこなすようになった。必然と夏油も1人になることが増えた。その夏は呪霊が頻出し、夏油は、ひたすら祓い、取り込む。誰のために? そしてある日、夏油の前にある人物が現れる。五条を“最強”の呪術師に、夏油を“最悪”の呪詛師に至らしめた在りし日の事件、その結末とは――!?', '2023/08/04 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1fae903d-3d18-4a86-bdcb-9ae864f1cb4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec9522f6-4edf-416e-80cd-096472ec68b4', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 6, '100157355', 'そういうこと', '2018年。ある日の任務を終えた虎杖、伏黒、釘崎の3人。虎杖は映画に、釘崎は買い物に行こうとするが、そんな2人を横目に、「お前ら元気だな」と1人伊地知の車で帰路に着く伏黒。虎杖と別れ、買い物を終えた釘崎はある女性に話しかけられる。「さっき、虎杖くんと一緒にいませんでした?」唐突な質問に驚く釘崎、虎杖と面識があるらしいこの女性の正体は――。', '2023/09/01 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c9dc0cb-a8ed-4f11-87e7-0dcc3b8536d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac8903a1-558e-4639-8778-fe1373f99299', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 7, '100158198', '宵祭り', '動く肢体を得る為、呪霊側に通じていた京都校のメカ丸こと与 幸吉。交渉は決裂し真人との闘いを余儀なくされるが、与は密かに準備してきた巨大なメカ丸･究極メカ丸絶対形態 (モード･アブソリュート) に乗り込み応戦する。全てを視てきた与はこれまでに縛られていた年月で得た呪力の全てをぶつける。果たして与は死地を脱し、五条に呪霊側の計画を伝えることができるのか――。', '2023/09/08 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c96630f-4da6-4e71-9d11-80d8ceff3e23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59eadd6d-ccc9-4dd3-b4e6-0d45f7fa6ca9', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 8, '100158908', '渋谷事変', '『2018年10月31日19:00』渋谷に『帳』が降ろされる。『帳』の中では一般人が大勢閉じ込められており電波も断たれてしまう。多くの術師が渋谷に集まるが、被害を最小限に抑えるため、五条が単独で渋谷駅地下ホームへ。そこで五条は、漏瑚、花御、脹相と相対する。一方、冥冥と同行していた虎杖は人語を解する呪霊と遭遇。呪術師、呪詛師、呪霊が渋谷に集結し、かつてない大規模戦闘がはじまる――。', '2023/09/15 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/565b7ca0-7e54-4ec1-bf0c-ba280e3dd89e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('194e9cb0-2dfb-4902-9550-4c6d762a2726', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 9, '100159755', '渋谷事変 開門', '渋谷駅地下ホーム。一般人を盾にされながらも、漏瑚、花御、脹相を圧倒し追い詰める五条。しかし、漏瑚達の狙いは、時間を稼ぎ、獄門疆により五条を封印することだった。大量の改造人間と共に真人も参戦。一般人を盾に五条を削ろうとする漏瑚達だったが、五条はある秘策に出る――。', '2023/09/22 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb19ddb4-7c29-4134-b8d4-d873eb0b1c2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ae85ab5-4cb4-445e-a54c-99a015f32bd5', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 10, '100160464', '昏乱', '真人を追い、明治神宮前駅から渋谷駅に向かっていた虎杖の元に突如現れたのは、耳を覆うような形となった小さなメカ丸だった。「五条 悟が封印されタ」と最悪の事態を告げるメカ丸。半信半疑の虎杖達だったが、メカ丸の説明に状況を飲み込み、五条の封印を全ての術師に伝え、五条奪還の為に動き出す――。', '2023/09/29 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47de19a1-1323-47d6-a009-0d26a70c92bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a4497f5-db0b-4924-9e01-49827a075e6e', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 11, '100161573', '降霊', '七海、伏黒、猪野と合流した虎杖は、七海から指示を受け、伏黒、猪野と共に「術師を入れない『帳』」を解くことに。虎杖の打撃でもびくともしない『帳』に対し、3人は結界の基をあえて結界外の目立つ場所におくことで強度を上げていることに思い至り、渋谷の街に立つ一際高いタワーを目指す。だがそこには呪詛師達が待ち構えていて――。', '2023/10/06 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b26beadb-e267-4a95-8f0c-bfa4f7afdf55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('655bd1f1-905e-4b97-9ea4-e6b01c0ff20d', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 12, '100162525', '鈍刀', '虎杖と伏黒は、呪詛師･栗坂の術式を攻略し「術師を入れない『帳』」を解くことに成功。一方、1級でしか通らない要請を済ませるため伊地知と合流しようとする七海だったが、何者かに刺され倒れている伊地知を発見する。また、七海が伊地知を発見した少し前、真希の指示で伊地知の元に向かおうとする釘崎と新田だったが、そこに呪詛師が現れて――。', '2023/10/13 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df396494-43eb-4a42-b787-8d1d81030f0a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1fbfe314-38b4-48b6-b319-bdd458cc1682', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 13, '100163639', '赫鱗', '狗巻の助けもありなんとか渋谷駅構内に辿り着く虎杖。そんな虎杖の前に現れた脹相は、「弟の仇…!!」と問答無用に襲い掛かる。戦いの最中、苦戦する虎杖に対し脹相は問いかける。「弟は、最期に何か言い遺したか?」', '2023/10/20 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe454c03-ad3f-414d-9b3d-231c52f0b78e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f3983aed-29f7-40b6-bcb8-e6c08a6f4b43', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 14, '100164232', '揺蕩', '夏油 傑の皮を被った何者かが呼び出した特級特定疾病呪霊と対峙する冥冥と憂憂。冥冥は、状況を冷静に分析し、憂憂とある策を打つ。一方重面を撃破した七海は、真希、直毘人と合流するが、能力未知数の呪霊と遭遇する。直毘人は術式を発動し、素早い攻撃を仕掛けるが…。', '2023/10/27 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f55eb90-2a2d-497d-add8-6cbf04e33c8c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2279c5f6-bc8c-45c0-baa5-951cd326e4c2', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 15, '100165191', '渋谷事変 揺蕩-弐-', '特級呪霊･陀艮の領域展開「蕩蘊平線」により窮地に追い込まれた七海、真希、直毘人。そこに現れた伏黒の加勢により死地に活路を見出すが、そこに甚爾が乱入。暴走状態の甚爾はそのまま強者である陀艮に攻撃を仕掛ける。一方、美々子と菜々子は、脹相との闘いで意識を失った虎杖の下に――。', '2023/11/03 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f97df117-7764-4f5e-b542-1ef25a83a86a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('810e3df7-c17c-44e8-9a90-a8971f39fadb', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 16, '100165734', '霹靂', '目を覚ました宿儺は漏瑚の助言には耳を傾けず、特級呪霊である漏瑚に対し、圧倒的な強さを見せつける。一方、お互いを未だ知らず、対峙する伏黒と暴走する甚爾。圧倒的な甚爾に対しギリギリの攻防を繰り広げる伏黒だったが――。', '2023/11/10 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4c457eb-28d2-4a83-877f-1006a695da49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('979d3c4c-e762-4b44-9016-46b7e58d13e3', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 17, '100166500', '霹靂-弐-', '甚爾との戦闘で深手を負った伏黒は、たまたま居合わせた重面から不意打ちを受けてしまう。瀕死状態に陥ってしまった伏黒は重い足取りで必死に歩を運ぶ。道玄坂の広い交差点にたどり着いた伏黒は、自身の術式『十種影法術』によってある式神を呼び起こす――。', '2023/11/17 00:30:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7820005a-b0ec-4448-aede-40b55fcf4b4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1625184-623c-47dc-9664-f43590cc025f', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 18, '100167036', '理非', '渋谷の街を壊し、数多の人を殺し、伏黒の式神を破った宿儺。そして目覚めた虎杖はその凄惨な状況を目の当たりにする――。悲愴な決意を顔に湛え、まるで幽鬼の様に歩を運ぶ虎杖。その一方、疲れ切った七海は朦朧としながらも群がる改造人間を祓い続ける。しかし、そこに真人が現れ――。', '2023/11/24 18:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51a492ee-e420-4653-8454-3abe47ce25bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbb75a6a-c630-4b30-8ecd-3d94f06d21b5', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 19, '100167635', '理非-弐-', '真人と一進一退の闘いを繰り広げる虎杖だったが、一般人を利用した真人の策に苦戦する。その頃、新田の制止を振り切って戦場に舞い戻った釘崎は、真人の分身体と遭遇する。釘崎を殺し虎杖の魂を折ろうと企む真人に対し、真人の術式に警戒しながらも応戦する釘崎。攻撃の効かない真人に対し、釘崎は――。', '2023/12/01 18:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/04db21a1-e908-4116-9606-10a6af37ae4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('312fee2e-dc57-4a94-8980-b4ec15759baf', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 20, '100168374', '理非-参-', '目の前の惨状に呆然と立ち尽くす虎杖。虎杖の心はもう限界を超えていた。一方、思い描く理想の展開に「呪い」として興奮する真人は、更に虎杖に追い打ちをかける。遂に真人は止めを刺そうするが、その時――。', '2023/12/08 18:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8cf774bd-2e3c-48a7-bf61-1d56a03e1a8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e51d78d3-a6f7-46b2-8740-4c001794cc62', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 21, '100169047', '変身', '窮地を救われた虎杖は東堂に鼓舞され、立ち上がる。激しい攻防の中、虎杖、真人に続いて東堂も黒閃を繰り出し、三者それぞれが120%の潜在能力を引き出すに至る。ギアを上げた真人は、「多重魂」「撥体」による全方位範囲攻撃を繰り出し襲い掛かる。ついに、虎杖、東堂、真人による最後の呪い合いが始まる――。', '2023/12/15 18:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d16bf77f-2209-4c0b-83cb-f4a4d00c531e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46a0a8cb-48d0-4705-8752-059c635a2749', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 22, '100169761', '変身-弐-', '虎杖と真人の死闘に決着がついたかと思われた瞬間、「助けてあげようか、真人」と夏油の皮をかぶった何者かが真人に声をかける。瞬時に虎杖は眼前に立つその男が五条を封印した者と同一人物だと気づき立ち向かうが、その男が繰り出す夏油 傑の呪霊操術により阻まれる。そしてその男は、ある事を語り始め…。', '2023/12/22 18:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd7e97d7-5927-4b7f-a3ff-cd08e6e7c3fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5075ce9-5304-4880-b7af-dba703a49e2e', '344a93a0-9865-43f5-a2e5-c38fefdf39a3', 23, '100171073', '渋谷事変 閉門', '【シーズン2 最終話】渋谷事変の最終局面に呪術師が集うなかで、脹相は夏油の亡骸に寄生する“黒幕”の正体に気付く。そして、絶体絶命の危機に現れた特級術師･九十九由基。九十九と“黒幕”がそれぞれ語る人類の未来 (ネクストステージ)。事変の終焉が招く破滅と混乱、世界は急変する――。', '2023/12/29 18:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cee7d0f8-97f0-4c30-8de6-d722ecc6465b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('beb62370-ece8-4527-bae5-6bd9456bd888', '呪術廻戦 死滅回游 前編', '', 'hulu', 'jujutsu-kaisen-the-culling-game-part1', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/082237ce-a536-4d3d-9597-a1e902bca033.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'RELEASING', NULL, 172463, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2ebc0752-ad47-4fdf-8fc3-85230098cee7', 'beb62370-ece8-4527-bae5-6bd9456bd888', 'hulu-jujutsu-kaisen-the-culling-game-part1-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf45d8fd-5041-4da9-9557-febba285cfb9.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4417bb1-3e10-4b23-b70b-bfc902071a5e', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 1, '100249831', '執行', '渋谷事変を経て魔境と化した東京で、黙々と呪霊を狩る虎杖と脹相。そこに禪院家当主の座を狙い伏黒の暗殺を企てる禪院直哉が襲撃。虎杖は直哉の口から、自らの死刑執行猶予が取り消されたことを知らされる。更に虎杖の死刑執行役として特級術師･乙骨憂太が急襲。虎杖は乙骨の圧倒的な呪力量に追い詰められる——。', '2026/01/09 01:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf45d8fd-5041-4da9-9557-febba285cfb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be0c5a11-95ca-4f4f-bc5c-4fa4a3a1918a', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 2, '100249832', 'もう一度', '死刑執行人･乙骨の刃に胸を貫かれた虎杖。一方脹相は、術式を用いて高速で攻撃を繰り出す直哉に苦戦を強いられていた。しかし、150年自らの術式と向かい続けた脹相は、赤血操術を駆使して応戦。そして死闘が決着したかに思われたそのとき、乙骨が微動だにしない虎杖の身体を引きずりながら現れ——', '2026/01/09 01:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d41036db-3e2b-4df3-b7ce-de3c952917a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1440ca53-74fb-4e87-8ba2-e2d466acdc02', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 3, '100249833', '死滅回游について', '渋谷での大量殺人から自責の念に駆られる虎杖だったが、「まずは俺を助けろ」という伏黒の言葉を受けて立ち上がり、高専に潜伏する九十九たちと合流する。一行は「五条の封印されている獄門疆の封印の解き方」と「加茂憲倫の具体的な目的と今後の出方」を求めて、天元に会うため薨星宮に向かう。天元は質問に答えると共に、加茂憲倫の本当の名前と彼の仕組んだ呪術を与えられた者達の殺し合い「死滅回游」について語り始める——。', '2026/01/16 01:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/870f8752-5d82-4612-8cb9-1f61d81712aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abe3035e-110a-4acf-8ccb-6cc90155e8d8', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 4, '100249834', '葦を啣む', '「死滅回游」平定のため其々の役割に動き出す一行。その中で、真希は死滅回游に参加するための戦力を強化すべく呪具の回収のため禪院家に赴く。直哉からの罵倒、そして母からの制止も聞かずに忌庫へと向かう真希。そして忌庫の扉を開くと、空となった中身の代わりに、血まみれの真依と、父･禪院扇の姿があった——。', '2026/01/23 01:00:00', 1685, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0264604-5464-4bb6-b266-1d25a8b4d1d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfb0991d-4bcc-46dc-a483-bc2cd618b7e6', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 5, '100249835', '熱', '渋谷事変を経て死罪となった夜蛾。彼のもとに刺客、そして楽巌寺が姿を現す。一方、薨星宮を発った虎杖と伏黒は停学中の呪術高専3年･秤 金次に協力を仰ぐため、秤が主催している賭け試合の会場に向かう。上層部との折り合いが悪い秤に高専関係者と気づかれないために、二人は身分を隠して賭け試合「ガチンコファイトクラブトーナメント」に潜入する——。', '2026/01/30 01:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19b8c441-4267-4131-b4b8-5ed9f273e12e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5551c7b-62b5-45fb-9b98-80e1b630197f', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 6, '100249836', '部品', '先にファイトクラブに潜入していたパンダと合流し、伏黒も潜入し拠点に向かうが、秤と行動を共にするもう一人の 3 年生･星綺羅羅に高専側の人間であると気づかれてしまう。綺羅羅は「金ちゃんが危ない…!!」と、詳細不明の術式を発動して、伏黒たちが秤のもとに向かえないよう妨害。伏黒は綺羅羅の術式を解明しようとすると同時に、秤を仲間に引き入れるべく綺羅羅の説得を試みる——。', '2026/02/06 01:06:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da63890a-2151-4043-bae4-eb301bdc9aa3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bb9c334-4c46-48eb-aa3f-3db96316754d', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 7, '100249837', '東京第1結界①', '秤の協力を取り付けた虎杖たち。そこに突如現れた死滅回游の泳者に憑く式神･コガネが総則追加のアナウンスをする。そして追加された総則により、既に100点以上所持している2名の泳者を特定した虎杖たち。彼らは獄門疆の封印を解ける『天使』を捜しながら、死滅回游に穴となる総則を追加する為に100点以上を所持する泳者たちに接触すべく、結界へと足を踏み入れる——。', '2026/02/13 01:06:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15cb56fe-f344-4245-ab8c-5fa9ce576746.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8be061d-9f85-4a2d-813e-030ae6011867', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 8, '100249838', '東京第1結界②', '100点を持つ死滅回游泳者･日車寛見は、かつて弁護士として、信念をもって活動していた。しかし、ある時強盗殺人の容疑で起訴された大江の弁護を担当することになり……。一方、現代にて東京第一結界に足を踏み入れた虎杖と伏黒は別々の場所に転送された。そして虎杖は「日車は池袋にいる」と、伏黒は「日車は新宿にいる」とそれぞれ違う情報を得る。別の場所を案内された二人がそれぞれ出会ったのは——。', '2026/02/27 01:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1593aaa5-285f-4dac-bcd8-404e48eb53ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aec1a41b-5927-45a1-9d81-882ca0081038', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 9, '100249839', '東京第1結界③', '日車に出会った虎杖は、死滅回游を終わらせるために協力するよう交渉を持ちかける。しかし、死滅回游に可能性を感じている日車はそれを拒否し、領域展開「誅伏賜死」(ちゅうぶくしし) を発動。そして現れた式神「ジャッジマン」により、虎杖を対象とした裁判がスタート。『黙秘』『自白』『否認』。課せられた容疑に対して、3つの選択肢を与えられた虎杖は——。', '2026/03/06 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00046376-5ce5-4035-8953-31031698c9c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('035f8be6-0824-42ba-b4fa-03b9ab50e5a4', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 10, '100249840', '東京第1結界④', '麗美に騙された伏黒は、日車のもとではなく過去の術師であるレジィたちのもとに連れてこられた。そして総則追加のために得点を渡すよう要求するも交渉決裂となり、針･黄櫨を含めた3人との交戦となる。3対1で苦戦する中、他プレイヤーへの得点譲渡が可能となるルールが追加されたと、コガネがアナウンスする。それを聞いて覚悟を決めた伏黒は反撃を開始する——。', '2026/03/13 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0d04c62-9f2c-472b-b418-4005e785eaeb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58a99ddd-342f-44d3-a628-211d2b5191c2', '2ebc0752-ad47-4fdf-8fc3-85230098cee7', 11, '100249841', '東京第1結界⑤', '領域展開「嵌合暗翳庭」(かんごうあんえいてい)。苦戦を強いられていた伏黒は、逃げたふりをしてレジィを体育館に誘い込み、空間を領域として転用。不完全ながら領域展開を発動する。しかし、レジィは歴戦の経験で機転を利かせ対応を試みる。二人の大技が激突し、ついに戦いは決着する——。', '2026/03/20 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9180a5d-5922-4b6c-8c17-940ebf47f45c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5e0b036e-ecd4-4eb1-8558-843dfc32fbfa', '呪術廻戦', '', 'hulu', 'jujutsu-kaisen-selection-the-strongest-man-gojo-satoru', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/049d982b-db37-49d4-aba4-0dce72d23fb2.png?w=331&h=447&p=t', 'hulu', 2020, 3, 1, 'FINISHED', NULL, 113415, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9e82e717-964e-4276-9306-0dcfd3d93545', '5e0b036e-ecd4-4eb1-8558-843dfc32fbfa', 'hulu-jujutsu-kaisen-selection-the-strongest-man-gojo-satoru-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc67b510-d62f-4752-885a-e6723b038045.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('98dcfe51-12ba-4fd3-ad1c-9818db38c038', '9e82e717-964e-4276-9306-0dcfd3d93545', 1, '100252750', '自分のために', '見知らぬ部屋で目を覚ます虎杖は、目の前にいた呪術高専の教師･五条 悟から自分の“秘匿死刑”が決定したと告げられる。五条は、虎杖に二つの選択肢を示す。今すぐ死刑になるか、『両面宿儺の指』20本を探し出し、すべて取り込んだのちに死ぬか――。', '2026/02/11 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc67b510-d62f-4752-885a-e6723b038045.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a2acc96-c85e-4579-a0fc-8c33ddad5d0e', '9e82e717-964e-4276-9306-0dcfd3d93545', 2, '100252751', '急襲', '移動中だった五条は、特級呪霊･漏瑚の奇襲を受ける。攻撃を重ねても決して当たらない――漏瑚は、すぐに五条の強さを目の当たりにする。一瞬で高専に戻り、修行中の虎杖まで連れてくる余裕の五条に、漏瑚は怒りを爆発させ、ある手段に出るが、対して五条は――。', '2026/02/11 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c78a2a9-4d1f-40fa-a125-d39f43558679.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed94f874-3bb4-43bd-abb1-d828630ec4c8', '9e82e717-964e-4276-9306-0dcfd3d93545', 3, '100252752', '規格外', '花御との戦いに参戦した虎杖と東堂。虎杖が黒閃を決め、東堂との連携プレーで攻め立てていく中、さらに自身の術式を解禁する東堂。超親友となった虎杖と共に、東堂はトリッキーな術式と (自称) IQ53万の脳内CPUを持つそのクレバーさで花御を翻弄していくが――。', '2026/02/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4dcdf579-95a7-4230-b413-d83c881d6c52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8782f15a-c24b-42d0-80ac-9c88ab5d70ea', '9e82e717-964e-4276-9306-0dcfd3d93545', 4, '100252753', '懐玉－参－', '天内の懸賞金を狙う呪詛師たちを退けた五条と夏油、すると突如震えだす天内の携帯。そこには捕らえられた黒井の姿が。拉致犯が人質交換をもちかけてくることも考慮し、天内を高専へ連れ帰ろうとする五条。しかし、天内は自らも取引に行くと啖呵を切り、五条･夏油と共に取引の指定場所へ向かうことに―。', '2026/02/11 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2bad58a-ea86-42c1-b472-323a7fb23765.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c655bd48-f9bb-4bf6-9c94-75900b8777ec', '9e82e717-964e-4276-9306-0dcfd3d93545', 5, '100252754', '懐玉－肆－', '「帰ろう、理子ちゃん」夏油が天内に手を差し伸べたその刹那、最悪の事態が起きてしまう。呆然と立ち尽くす夏油の前に、伏黒甚爾が姿を現す。甚爾は夏油にこう告げる。「五条悟は俺が殺した」激昂した夏油は呪霊を召喚し、甚爾に畳みかけるが―。', '2026/02/11 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba665bc2-42da-4f56-8f53-56945e45b87f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac44cf49-76fa-4e1b-94ad-81729c282055', '9e82e717-964e-4276-9306-0dcfd3d93545', 6, '100252755', '渋谷事変', '『2018年10月31日19:00』渋谷に『帳』が降ろされる。『帳』の中では一般人が大勢閉じ込められており電波も断たれてしまう。多くの術師が渋谷に集まるが、被害を最小限に抑えるため、五条が単独で渋谷駅地下ホームへ。そこで五条は、漏瑚、花御、脹相と相対する。一方、冥冥と同行していた虎杖は人語を解する呪霊と遭遇。呪術師、呪詛師、呪霊が渋谷に集結し、かつてない大規模戦闘がはじまる―。', '2026/02/11 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db68067b-5134-4aab-95db-07b947982343.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4daaf90e-63e1-4b66-98ea-a519885bb375', '9e82e717-964e-4276-9306-0dcfd3d93545', 7, '100252756', '渋谷事変 開門', '渋谷駅地下ホーム。一般人を盾にされながらも、漏瑚、花御、脹相を圧倒し追い詰める五条。しかし、漏瑚達の狙いは、時間を稼ぎ、獄門疆により五条を封印することだった。大量の改造人間と共に真人も参戦。一般人を盾に五条を削ろうとする漏瑚達だったが、五条はある秘策に出る―。', '2026/02/11 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f71dd92-50c9-4790-acc4-54c98a96078f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d1f97db9-3692-4942-bdcc-a47f87dfc59e', '終わりのセラフ', '', 'hulu', 'seraph-of-the-end', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b61f3e5e-65f9-4ce9-a0b9-4a31751c0b56.jpg?w=331&h=447&p=t', 'hulu', 2015, 1, 1, 'FINISHED', NULL, 20829, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('df2c704f-9418-4025-b90e-667fcb0d93fb', 'd1f97db9-3692-4942-bdcc-a47f87dfc59e', 'hulu-seraph-of-the-end-s1', '第1クール', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e64503f-1d90-4d7b-8532-68f4037499e1.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b7eabf5-3c11-40e1-bd92-fb1617bee8a9', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 1, '100048651', '血脈のセカイ', '突如蔓延した未知のウイルスにより、世界は破滅を迎えた…!! 生き残った少年少女は、地の底より現れた吸血鬼に連れ去られていった。―それから4年後。「百夜孤児院」の家族と一緒に、吸血鬼の都市「サングィネム」で暮らす、優一郎とミカエラ。自分たちの血を奪い、家畜同然に扱う吸血鬼たちに、優一郎は反感を抱くが…。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e64503f-1d90-4d7b-8532-68f4037499e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7558d08-bdfa-42c7-993c-8aaa90b59331', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 2, '100048652', '破滅後のニンゲン', '優一郎が吸血鬼の世界から脱出し、4年の歳月が流れた。日本帝鬼軍へと入隊した優一郎だが、吸血鬼への強い恨みが先行し、命令違反を犯してしまう…。謹慎処分を受け、第二渋谷高校に通うことになるが、与えられた条件は「友だちを作ること」。軍の監視官である柊シノアが見張る中、優一郎は学園生活に馴染めず苦戦する…。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa418230-a0ac-47b4-94c1-8fe2a40dee4c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d59ddb8a-fa3f-4508-9791-a12aeb4524ed', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 3, '100048653', '心に棲むオニ', '念願の「吸血鬼殲滅部隊」に配属された優一郎だが、未だ高校へ通う生活に不満を募らせていた。そんな中、同級生が「開かずの間」と呼ばれる立ち入り禁止区域に入ってしまう。「旧渋谷地下神殿」―そこは未熟者が入ると、鬼に取り憑かれるという。優一郎は同級生を救い、そして力を得るべく、自ら修練の地へ進入する…!!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49b526d2-4f5e-4204-892b-74ded10e371e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df373d16-943d-4452-83f4-be3ab434f547', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 4, '100048654', '吸血鬼ミカエラ', 'サングィネムで優一郎を庇い、命を落としたと思われたミカエラは、なんと生きていた! 一体彼に何が起きたのか!? 秘められた真実が明らかに…!! 一方、優一郎と与一は共に吸血鬼殲滅部隊「月鬼ノ組」の研修生となる。だが、自己紹介も十分に行えないまま、優一郎は同じ研修生の君月と衝突。転入早々、波乱を巻き起こすのだった…。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/556dfe88-f501-464c-bd8e-559efdbd1289.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb748d15-a4ed-490b-9a5f-8f1a49785dff', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 5, '100048655', '黒鬼とのケイヤク', '評議会の決定で、吸血鬼たちはついに日本帝鬼軍殲滅へ動き出した。一方、日本帝鬼軍本部も吸血鬼たちの動きを察知し、対策会議を設けていた。様々な思惑が交錯する中、優一郎たちは鬼呪装備契約のための訓練に励む。なかなか進展しない訓練に業を煮やした優一郎は、グレンに直談判。鬼呪装備契約の約束を取り付けるが…。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8a4e9f1-530b-43e3-b548-97e7b000386a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec0689da-caf7-4525-b206-7bc3a94b0929', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 6, '100048656', '新しいカゾク', '最上位の鬼を封印した『黒鬼』シリーズとの、契約の儀を開始した優一郎、君月、与一の3人。武器を抜いた瞬間、鬼は優一郎たちの心の「最も脆い部分」を攻撃し始める。打ち勝って力を得るか、負けて鬼に体を乗っ取られてしまうか!? それぞれの精神世界で、鬼と契約者との戦いが始まった。3人は無事、契約に成功できるか…!?', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8afd8027-9c95-49e8-8529-b1b122339752.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b35f2bfd-5385-4992-a41a-71e8f5eb9e55', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 7, '100048657', '三葉のチーム', '見事、最上位の『黒鬼』シリーズを手に入れた優一郎は、シノア、与一、君月らと組み、初の任務へと赴くこととなった。そんなシノア率いる分隊に、新たな仲間が配属された。その名は三宮三葉。13歳のころから殲滅部隊にいるという彼女だが、新人だらけの部隊に配属されることに反発。とりわけ優一郎と衝突を繰り返すが…。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/537a8cff-6695-4da2-948e-4d3d03aeca4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a6e6cb2-a393-4d58-bf69-212b748996e6', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 8, '100048658', '殲滅のハジマリ', 'シノア分隊の初任務、原宿での吸血鬼奇襲作戦が遂に決行される! 向かった先で優一郎たちが見たものは、家畜の服を着せられ、生きる気力を失った多くの人間だった。かつての自分の境遇を思い出し、復讐の念を燃やす優一郎。果たして、4年をかけて身につけた彼の力は吸血鬼に通用するのか!? 優一郎の訓練の成果が、今、試される。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dcc4b262-b315-4b07-a433-68bdfef31843.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97307ccc-d648-49ff-9c29-9ad7cfa87f34', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 9, '100048659', '襲撃のヴァンパイア', '原宿での任務を終えた優一郎たちは、最終目的地の新宿へと到着する。だが防御壁を築き安全だったはずの新宿は、吸血鬼の襲撃を受け戦場と化す! シノア隊もすぐさま戦線に加わり、新宿攻防戦は激しさを増していく! 時を同じくして新宿へと降り立つミカエラ。吸血鬼となったミカエラは、優一郎との再会だけを願い剣を抜くが…。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2fe55a8f-52af-4e9e-aad9-755a7df3bd03.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e4be642-29b2-4932-8b24-3721c68a6389', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 10, '100048660', '選択のケッカ', '熾烈を極める新宿攻防戦。戦況はめまぐるしく変化し、帝鬼軍は次第に劣勢に追い込まれていく。黒鬼装備を持つ優一郎たちの参戦もあったが、希望を打ち消すかのように、第七位始祖フェリド･バートリー率いる吸血鬼主力部隊が動き出す! その主力部隊にはミカエラの姿もあった。迎え撃つは、吸血鬼殲滅部隊月鬼ノ組グレン隊!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/298cc863-ce45-43a9-804b-d92c4a27e597.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4dc55ae-0cab-46d9-ac1d-d6e1168b25e0', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 11, '100048661', '幼馴染のサイカイ', '4年の時を経て、ミカエラとの再会を果たす優一郎。大切な家族が憎むべき吸血鬼になったことを知った優一郎は何を思うのか。苦戦を強いられる中、新たに現れる吸血鬼の貴族。圧倒的な力で月鬼ノ組の仲間が蹂躙されていく。絶体絶命の光景を目の当たりにした優一郎の体に突如、鬼の力とはまったく異なる何かが姿を現す―!!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/635773ab-beb4-4249-ad4e-de91f85e208f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f187a3c7-66d7-4981-8669-785d21e158f9', 'df2c704f-9418-4025-b90e-667fcb0d93fb', 12, '100048662', 'みんなツミビト', '【第1クール 最終話】日本帝鬼軍と吸血鬼の新宿攻防戦は終結。だが、未だ多くの謎が残されていた。戦場で異形の姿へ変貌した優一郎。その恐るべき力の正体とは!? 一方、何かを知りながらも隠すグレン。吸血鬼になっても、優一郎を救いたいと願うミカエラ。優一郎の暴走を目の当たりにした仲間たち。死闘の末に、それぞれを待ち受ける運命とは…!?', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ae7e927-eb17-40ab-a122-e9f218f4aaed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cce12c29-e264-41b3-8168-e12b9f1e8ac1', 'd1f97db9-3692-4942-bdcc-a47f87dfc59e', 'hulu-seraph-of-the-end-s2', '第2クール', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab8beff1-3e71-44bf-8b17-fa797b60353d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3de1387-c13b-47d6-8129-7682f9d4e47e', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 13, '100048663', '人間のセカイ', '優一郎に宿る謎の力の暴走により、新宿防衛戦は終結。優一郎はミカエラが生きていることを知り、吸血鬼から家族を取り戻すことを決意する。その矢先、優一郎は柊家から身に覚えのないスパイ容疑をかけられてしまう! 日本帝鬼軍を組織し、今なお絶対的な権力を振るう柊家。困惑する優一郎に、残酷で無慈悲な尋問が行われる!!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab8beff1-3e71-44bf-8b17-fa797b60353d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9dd45c27-bb9b-4b86-aa8c-a699c5c1500d', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 14, '100048664', '交錯するカンケイ', '吸血鬼との戦いで実力不足を痛感した優一郎は、家族を守るため、「鬼呪装備」の更なる力を引き出す修業に身を投じる! 一方、吸血鬼の世界では「終わりのセラフ」を兵器利用する人間の動きを危惧し、吸血鬼上位始祖会が開かれていた。「終わりのセラフ」を巡る人間と吸血鬼の思惑は、優一郎たちの未来に何をもたらすのか…!?', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fe11fd0-a236-47bb-a4c2-d397d8f98bc4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22bc0945-dd0d-45c7-bfbd-a2dc7d59bf27', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 15, '100048665', '帝鬼軍のヤボウ', '優一郎に宿る「終わりのセラフ」の秘密を知りながら、隠蔽を図っていたグレン。それを知ったシノア隊はグレンと柊家、どちらにつき従うべきなのかを考える。その頃暮人に呼ばれたグレンは優一郎、与一、君月たち黒鬼適性者について尋問を受けていた。三人とグレンの邂逅は偶然ではないのか? そしてシノア隊が出した答えとは?', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7b0ec41-b855-4283-9032-b1647615f743.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5adebef-085f-484f-b695-f7c6bb1f318c', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 16, '100048666', '月鬼のゴウレイ', '貴族殲滅作戦に参加するため、集合場所である海老名サービスエリアへと向かうシノア隊一行。しかし、ヨハネの四騎士による襲撃などもあり、集合時間に遅刻してしまう。吸血鬼殲滅部隊の指揮官であるグレンは、シノア隊への戒めとして模擬戦闘試験を敢行。優一郎とグレンを筆頭に、黒鬼装備同士が熱き火花を散らすことに…!!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5790bc8-1316-4f6f-ac05-3519ca7d4820.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0766771-eaf9-4970-b85c-72e192f97cb0', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 17, '100048667', '反逆するカチク', '遂に始まった、貴族殲滅作戦。鳴海隊と合同で作戦を決行することになったシノア隊は、名古屋テレビ塔･展望台にて作戦開始の時を待っていた。危機感のないシノア隊の作戦参加に不満を募らせる鳴海隊だったが、優一郎の仲間を守る覚悟を受けとめ、作戦参加を承諾。そこへ、第十五位始祖、ルカル･ウェスカーが姿を現す―!!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/043b581e-e73e-4909-b644-99306a4f1e73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f926298-03b0-4bcc-b0e5-c27637d522bd', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 18, '100048668', '正義のツルギ', '貴族殲滅作戦に成功したシノア隊と鳴海隊は、他部隊と落ち合うため合流地点で待機していた。そこへ、相原隊とグレン隊が合流。戦果報告もほどほどに、吸血鬼に捕らわれた月鬼ノ組のメンバーを救出するため、名古屋市役所へと急行する。相原隊は伝令役として留まるが、その眼前にミカエラが所属する吸血鬼軍が舞い降りた…!!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a512cd9-9799-4cdf-b8cb-5fd1caf665d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ccec4aa-0743-46a6-95fd-af5e0ccf8438', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 19, '100048669', '深夜とグレン', '人質に取られたメンバーを救うため、グレン率いる月鬼ノ組は第十三位始祖、クローリー･ユースフォードに先制攻撃を仕掛ける…!! しかし、クローリーの戦闘能力はグレンの想像を遥かに超えていた。勝ち目はないと悟ったグレンは、退却を決断するが…。果たして、グレンの運命は!? 優一郎たちは人質を解放することができるのか!?', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/663e69a8-a212-48b8-8534-1c446eef29b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('297189f4-df91-43aa-a5f7-e2fde2efb3ce', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 20, '100048670', '鬼のコモリウタ', 'シノア隊はクローリーに拘束されたグレンの救出に駆けつけていた。優一郎を始めとするシノア隊の5人が、それぞれ渾身の攻撃を仕掛けるが、クローリーに傷一つつけることができない。戦いの最中、約束の5分を告げるアラームが戦場に鳴り響く。「グレンは捨てる」―苦渋の決断を下した深夜は、全員に撤退を告げるのだが…。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df0ddf18-d425-4f50-83c0-0524364f7945.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e95df2e-f1a5-4972-8489-5f919fccb354', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 21, '100048671', '裏切りのミカタ', '「家族を救えないくらいなら―死んだ方がマシだ」。グレンを救うため、鬼呪装備本来の力を引き出す薬に手を出した優一郎。阿朱羅丸の力を受け取り覚醒した優一郎は、シノアたちの制止も聞かず、ただ一人クローリーの元へと向かう。優一郎はクローリー、そして従者のホーン、チェスからグレンを救い出すことができるのか…!?', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/125ddbfd-bc79-4357-8a0e-070e2cecf4a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e51b23f-c494-4978-b1e7-f0cfa94e7bec', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 22, '100048672', '優とミカ', 'シノアたちの援護により、優一郎を連れて逃げ延びたミカエラ。彼には優一郎にどうしても伝えたいことがあった。一方、戦場に残った深夜率いる月鬼ノ組は、突如襲来した吸血鬼と交戦!! 傷を負い、苦戦を強いられる隊員たち…。最悪の状況を回避するために、深夜は、空港を合流地点とし、メンバー全員に即時撤退を命じる…!!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85b47d97-13da-4ebb-b299-b23d295eb475.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abdc291c-0a14-40d1-9597-b3d60dedfd56', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 23, '100048673', '傲慢なアイ', '吸血鬼との交戦で深手を負った、深夜率いる月鬼ノ組。絶体絶命の状況を脱するべく、逃走用のヘリが用意された空港を目指す。だが、そこには飛行機の残骸があるのみだった。脱出手段を失い、途方にくれる隊員の前に突如暮人が現れる。「任務達成、ご苦労だった。」―その言葉の真意とは…!? 深夜たちは助かることができるのか!?', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caba66f7-7bff-4338-8ff1-17182f261b57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8a413f6-b52e-417b-ad41-c9b3c2f98866', 'cce12c29-e264-41b3-8168-e12b9f1e8ac1', 24, '100048674', '終わりのセラフ', '【第2クール 最終話】優一郎目掛けて振り下ろされる、グレンの凶刃…! そして、時と場所を同じくして動き出す「終わりのセラフ」!! 優一郎達の理解が及ばぬ中で、「終わりのセラフ」がもたらす無差別な殺戮は熾烈を極める!「俺は、あん時とは違う」。もう二度と大切な「家族」を失わないために、優一郎は自らに宿る禁断の力を解放する―!!', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47a9bc17-1e6b-4b45-8e73-a7861b4007af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6f97f452-be59-4bb6-8b88-e0f7d2b18a38', '終物語', '', 'hulu', 'owarimonogatari', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/895398b9-9a0c-4837-aeaf-de5e1d55cf7a.jpg?w=331&h=447&p=t', 'hulu', 2015, 3, 1, 'FINISHED', NULL, 21262, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6b36e182-84d0-464f-a1a6-eea5ce51f7e0', '6f97f452-be59-4bb6-8b88-e0f7d2b18a38', 'hulu-owarimonogatari-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/166c4fae-2345-422f-a3d7-391968dbef34.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('521531d5-90d8-4542-b524-451b47e68732', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 1, '100024721', 'おうぎフォーミュラ 其ノ壹／おうぎフォーミュラ 其ノ貳', '神原駿河に忍野メメの姪と自称する転校生の少女、忍野扇を紹介された阿良々木暦。学校を移るたびに校舎の図面を作成している扇は直江津高校の図面に存在する不思議な点を発見し、その隠し部屋に暦を誘ったのだが…。', '2024/07/04 00:00:00', 2906, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/166c4fae-2345-422f-a3d7-391968dbef34.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33f43b36-2f77-4e15-862b-9bd291412610', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 2, '100024722', 'そだちリドル 其ノ壹', '老倉育との再会をきっかけに、通っていた七百一中学校を訪れた阿良々木暦と忍野扇。かつて使用していた下駄箱を訪ねると、そこには中学一年生の暦に宛てた封筒が入っていた。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2edeb1e-ca0d-4ce6-9a81-cec27df8cfa6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8f55cf9-51c5-4de1-8651-0a578fbef17a', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 3, '100024723', 'そだちリドル 其ノ貳', '五年前の一学期が終わろうとする頃、中学一年生の阿良々木暦は、突如自分の前に現れたモンティ･ホール問題に興味をそそられ、その解を求め、とある廃屋を訪れていた。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef08c01a-b7ef-44b1-a05a-16378ae86a3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c189c967-a39e-432f-aecf-25c936aa1cf2', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 4, '100024724', 'そだちロスト 其ノ壹', '老倉育は2年ぶりに登校したあの日以降、戦場ヶ原ひたぎとの一件の翌日から、再び学校に姿を現さなくなった。阿良々木暦と羽川翼は彼女を見舞うため、育の家に向かうのだが、そこに忍野扇が現れる。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a95078e-e963-4bdb-8a14-ff0ee67b3339.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d716fd90-c481-4447-be0b-0bcf4efd93a7', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 5, '100024725', 'そだちロスト 其ノ貳', '羽川翼とともに、老倉育の住むマンションの一室へと足を踏み入れた阿良々木暦。頬を赤く腫らしたパジャマ姿の育を前に、暦は昔の話を始める。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd58d236-e3eb-4863-905b-5389a9ff09a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de388793-bdec-4dfd-91e7-38bd8a78a6b2', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 6, '100024726', 'そだちロスト 其ノ參', '失踪した母の捜索を約束し、老倉育のマンションから出てきた阿良々木暦と羽川翼。この事件の疑問点をまとめようと、マンション前の広場のベンチに座ったのだが、そこに忍野扇が再び姿を現す。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19fe48eb-009e-4294-9677-cc57bbd27c3a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8db80e42-1814-405b-9d54-58f10757352c', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 7, '100024727', 'しのぶメイル 其ノ壹', '夏休みが終わり、二学期が始まった直後、吸血鬼とのペアリングが切られ、およそ半年ぶりにほぼ生身の人間となった阿良ヶ木暦は、臥煙伊豆湖からの依頼を受け、学習塾跡に神原駿河を呼び出した。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e50017b0-b291-40f6-885c-70ea5729ed0f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f409c008-cb56-41b0-bf0c-1f157db43c68', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 8, '100024728', 'しのぶメイル 其ノ貳', '突如現れた怪異に襲われた阿良々木暦と神原駿河。間一髪で斧乃木余接に助けられた二人は、彼女の助言で、共に臥煙伊豆湖との集合場所へと向かうのだが…。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13410ed1-c366-4e24-9629-b17b8fa278cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1242342f-dedb-4b8d-8bbc-f7a5301b6a99', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 9, '100024729', 'しのぶメイル 其ノ參', '臥煙伊豆湖との待ち合わせ場所で、暦と駿河は忍野忍に出会う。そこに、新たな怪異が現れ、暦たちを襲うのだが、その正体は…。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1ddf838-7291-4306-b07e-903fbca4e26f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89611a6f-fae2-4d41-9878-dd4831e0272b', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 10, '100024730', 'しのぶメイル 其ノ肆', '15年前、北白蛇神社に眷属の灰が溜まってしまったことが、結果として様々な怪異をこの町に引き寄せる遠因となったことを、暦は伊豆湖に知らされ―。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce1d4580-65c1-4136-a999-d24f098f0a64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b77477e4-5a98-4ce0-a664-9249d87b77f6', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 11, '100024731', 'しのぶメイル 其ノ伍', '少年のような姿になった死屍累生死郎は、阿良々木暦に「キスショットと別れてほしい。」と告げる。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39a2eac5-bd74-465d-8796-26bedc4a8779.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df28c4ba-79f3-484c-91c8-a6021c09ab02', '6b36e182-84d0-464f-a1a6-eea5ce51f7e0', 12, '100024732', 'しのぶメイル 其ノ陸', 'キスショットのただ一人の眷属の座を賭けて、暦はエピソードと共に初代怪異殺し･死屍累生死郎との決闘に挑む。', '2024/07/04 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b7a33e0-018a-436e-984d-1dab40d1135c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f887bb5b-9a08-44bc-a840-15b70cb5e0e8', '終末ツーリング', '', 'hulu', 'touring-after-the-apocalypse', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01d21cc4-7fba-4307-b12c-838e42446028.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 186920, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 'f887bb5b-9a08-44bc-a840-15b70cb5e0e8', 'hulu-touring-after-the-apocalypse-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2472d1c-51f3-4cf4-a12e-0f51225688f0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70dd61c4-27f1-4de1-aef1-e244e38d1cb9', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 1, '100240354', '箱根', 'ここは終末世界。電動化されたセローに乗って自由気ままに旅をするヨーコとアイリ。今回の目的地は箱根。', '2025/10/07 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2472d1c-51f3-4cf4-a12e-0f51225688f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5877c6c9-f779-4ec1-a7f5-e35a1e22488c', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 2, '100240861', '横浜･横須賀', '旅路は箱根から横浜へ。崩れた橋、海に浮かぶビル群。食べ物を探しに出かけた二人に、思いがけない出会いが――。', '2025/10/14 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3403e83b-7075-4e4b-8c7d-4998d2294e07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2feb224-7e04-407f-b144-bbdb11a44c1d', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 3, '100241397', '世田谷･新橋･有明･東京ビッグサイト', '東京方面へ進む中、飲み水を求めて世田谷･等々力渓谷へ。喉を潤した後、食料を探しに空き家を散策して回ることに。', '2025/10/21 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05c65e0c-64cf-4e56-9bed-eaa683beda0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9736608e-705e-417b-a918-c0cead18655f', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 4, '100242155', '秋葉原', '「アキバラジオ」の発信源を探すため、二人は秋葉原を訪れる。廃墟の電気街で執事とメイドの衣装を見つけ、コスプレで盛り上がっていると――。', '2025/10/28 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5cdf0f86-3e2f-4fdc-b0f5-1e9e03aedb89.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8bbb3f66-3ea6-420d-865f-b7c259aefc28', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 5, '100242999', '流山･利根川運河･木更津', '秋葉原を後にし、千葉県側から海ほたるに向かう二人。流山に広がる湿地帯ではセローをうまく運転できず苦戦する。', '2025/11/04 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c20c7bd-ba8d-4757-bfc1-94921516efc4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('025dfadc-8c73-464d-86e0-1536ac9ecc3c', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 6, '100244232', '海ほたる', '嵐の東京湾アクアラインを駆け抜け、なんとか海ほたるに辿り着いた二人。雨が止むまで、暗闇の中を探索していたら――。', '2025/11/11 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/415669c1-8869-45c9-906b-3c048ac15bb2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f86182e-6d86-4f9a-85eb-490e069bce0e', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 7, '100245034', 'つくば', 'アイリのメンテナンスのため、つくばエキスポセンターに到着。そこにある何の変哲もない電話ボックスが突然……?', '2025/11/18 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f042cac3-9ec8-4c3b-a3ea-4e229cfb86f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b101483-0da8-4ad5-95b4-be946cdaf7f6', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 8, '100245900', '霞ヶ浦･モビリティリゾートもてぎ', '「つーりんぐらむ」がアップデートされ、スタンプ機能が実装された。二人は一番近くにあるスタンプを目指して霞ヶ浦へとやってくる。', '2025/11/25 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9374337-d7f6-4441-93ba-81a7e5daed77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbad1719-4159-49a3-bd49-f50c85946fcf', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 9, '100246475', 'モビリティリゾートもてぎ', 'サーキットを走ってみたくてモビリティリゾートもてぎにやってきた二人。そこで、案内ロボットのアイザックと出会う。', '2025/12/02 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8735220-f33f-4021-bb02-24ad09b2d5ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a0d1717-aad8-49b6-99b3-f5ff895e216a', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 10, '100247135', '大洗･大谷･日光', '二人の旅は大洗へ。大洗港のフェリーで一晩過ごした後、このフェリーで行けたはずの北海道への思いを馳せる。', '2025/12/09 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/add9126e-3962-4e99-83a2-c273f87a9fde.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c45e1cab-e85b-4955-81b9-b09e2526ec70', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 11, '100247982', '吉見百穴', '日光を後にして、アイリにだけ聞こえる不思議な音がする方向へ向かうと――そこは埼玉県にある史跡･吉見百穴だった。', '2025/12/16 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d2663bd7-9780-41ab-8e35-f1b7aa4d231f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('050eb407-d49f-4a25-aa76-01cd5587ee31', '4da18abd-ed4d-45f4-b203-8bf2d66bee1f', 12, '100248588', 'ビーナスライン･シェルター', '【シーズン1 最終話】白樺湖の湖畔でキャンプをした後、ヨーコとアイリはツーリングの聖地･ビーナスラインへ向かう。濃い霧を抜け、二人が見たものは――。', '2025/12/23 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d343f223-a43f-4af4-a52e-f74d6208c042.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('924c5926-8bc4-4a36-b0f0-ac62c864cbdb', '終末トレインどこへいく？', '', 'hulu', 'shumatsu-train-doko-e-iku', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cacd4f03-3735-4b5b-8454-45a14e2a815c.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 155657, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5014edb9-505b-440d-ab94-056fed05f482', '924c5926-8bc4-4a36-b0f0-ac62c864cbdb', 'hulu-shumatsu-train-doko-e-iku-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4d9fbab-24c9-4063-9c97-bfe300573fbf.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb730917-5ef3-4f7e-8501-e28d1b099168', '5014edb9-505b-440d-ab94-056fed05f482', 1, '100180360', 'ちょっと行ってくる', '埼玉県にある吾野駅。住民たちにとある異変が起きてしまったこの田舎町で、高校生の静留は日々を過ごしていた。ある日、町に届いた荷物の中に、静留がずっと探していた親友の手がかりを見つけ……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4d9fbab-24c9-4063-9c97-bfe300573fbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c6e3fa7-eed5-43e0-9645-8ffeb7df1bc4', '5014edb9-505b-440d-ab94-056fed05f482', 2, '100181633', '推測、だろう、思われる', '静留たちを乗せた電車が駅を出発した。景色も、町と町を繋いでいるレールもすっかり変わってしまった世界を車窓から眺めながら、葉香がいるであろう池袋をめざして進んでいく。すると、遠くから謎の人物が…?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1ff9a23-157e-4ba6-8f60-7551aabe7c8a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea19ab46-a573-479e-87af-c70aea03732d', '5014edb9-505b-440d-ab94-056fed05f482', 3, '100182074', 'ショートでハッピーイージーに', '隣駅の東吾野駅に着くと、頭からキノコが生えている住民たちから出迎えられた静留たち。おすすめされたミストサウナ、さらにキノコ料理まで堪能して旅の疲れをリフレッシュ! でも晶だけは、なんだかここの人たちが怖くて……', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7786a41a-ea4b-44d2-a069-0ad7363b6687.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a5cf25b-c298-44d4-81e4-cdbf6708e9f1', '5014edb9-505b-440d-ab94-056fed05f482', 4, '100182633', 'なんでおしり隠すの?', '変な動物、妙な人参、ゴルフボール的なものと、色んなものから逃げながら、静留たちを乗せた電車は池袋へ向かって進んでいく。しかし、それらをくぐり抜けたと思ったのもつかの間、晶の体には異変が……?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a02f134e-224c-4df0-a6f8-ad22ee9898ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('197a7c4e-2122-4161-97ac-3251e315d17b', '5014edb9-505b-440d-ab94-056fed05f482', 5, '100183509', '骨にされてしまいます', 'どうにか脱出した静留と玲実は、一帯を牛耳っているボスに幽閉されていた“ドクター”を助けに向かう。市民にも協力してもらい、なんとか救い出したドクターを連れて玲実は晶の元へ急ぐ!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a08c3a29-840e-42b4-a49a-db9c42928e4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7492e0a6-e345-47df-b261-40ec7d295484', '5014edb9-505b-440d-ab94-056fed05f482', 6, '100184070', 'そんなにひどいこと言ったかな', 'みんなで電車をアポジー号と名付けたのも束の間、ちょっとした口喧嘩から、静留は電車を降りてしまう。ポチさんは静留についていくものの、撫子たちとは分かれてしまう……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1bf5383-16ee-47a1-87b5-e6e41f424468.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3897264-5cb5-430d-ae88-46617cfc3640', '5014edb9-505b-440d-ab94-056fed05f482', 7, '100184791', '笑うゾンビはゾンビじゃない', '静留を追いかけて撫子、玲実、晶は森へ入ることを決めた。ゾンビに遭遇してピンチに陥るも、ゾンビの女王･黒木と一緒にいる静留を発見! 撫子たちはなんとか静留を助け出そうと、こっそりその後を追っていく。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c78e50b-9b66-47c0-8372-906ee03c493b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('509ee27c-b43f-4621-8666-3f6254b761b5', '5014edb9-505b-440d-ab94-056fed05f482', 8, '100185389', 'バチ当たらない?', '大泉学園駅が“練馬の国のアリス”の町“ネリアリランド”になっているという話を聞いて、期待に胸を膨らませる玲実。しかし到着した町は、ヒロインのアリスの姿がないどころか、悪夢の様相を呈していた。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8536b8cd-ba0b-498b-bfba-10a3383eed8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1eb06834-69b0-4741-84c6-2f0bfa0a5763', '5014edb9-505b-440d-ab94-056fed05f482', 9, '100186407', '思ってたよりつまんないみたいな', '池袋駅まであと10駅。大泉学園駅を出発した静留たちは以前に会った仙人のスワンボートを見つける。そこで再会した仙人はこれまでの旅路について話し始める……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b89ec70-35e4-41c1-9699-27a48e479793.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70d9a19f-d946-497b-ba1f-db54a7d934a7', '5014edb9-505b-440d-ab94-056fed05f482', 10, '100187057', 'これこそ反抗と退廃の証', '葉香のいるという池袋へ向けて、アポジー号を走らせる静留たち。しかし、終点･池袋駅を目前にした椎名町駅では、静留たちを足止めする刺客が待ち構えていた!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b7e8cd7-b331-402b-9a91-505c48d22335.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9bc9e0bf-eb3a-4ed7-b177-bcc7ab763b95', '5014edb9-505b-440d-ab94-056fed05f482', 11, '100187508', 'もう無理かな……', '長い道のりを経て、アポジー号はついに終点･池袋に到着した。葉香の匂いを嗅ぎつけたポチさんを追いかけて、静留たちは走り出す……!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75378e8a-9ad1-4796-b21f-11cf8d4d899c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0628635a-9593-4517-916a-9163a62075d1', '5014edb9-505b-440d-ab94-056fed05f482', 12, '100188939', 'いつもって何だっけ', '【最終話】ポンタローによって、葉香は装甲列車で連れ去られてしまった。葉香と、ついでに世界を元に戻すため、静留たちはアポジー号に乗って必死に装甲列車を追いかける。そして、静留は再び葉香と向き合う。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85c257ba-7e24-45c2-88a7-b3fd7a381857.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('10be6aba-e801-40d5-ab3c-880f0d69be12', '終末なにしてますか? 忙しいですか? 救ってもらっていいですか?', '', 'hulu', 'worldend-what-do-you-do-at-the-end-of-the-world-are-you-busy-will-you-save-us', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de3593e0-5414-4269-835d-613e762f25ea.jpg?w=331&h=447&p=t', 'hulu', 2017, 1, 1, 'FINISHED', NULL, 21860, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0602232c-8e51-48ab-906c-138145c67ba1', '10be6aba-e801-40d5-ab3c-880f0d69be12', 'hulu-worldend-what-do-you-do-at-the-end-of-the-world-are-you-busy-will-you-save-us-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66e1eadc-5d12-4c25-83a7-935db612b393.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e54cd59-e677-4a76-9f26-25ce35b0d13a', '0602232c-8e51-48ab-906c-138145c67ba1', 1, '100098604', '太陽の傾いたこの世界で', '浮遊島の街中で、猫を追いかけていた少女、クトリを救ったのは人間で唯一の生き残り、青年ヴィレム。クトリに行きたいところがあると頼まれるヴィレムは、彼女を案内することに。「うん。夢もかなったし、良い思い出も出来たし、思い残すことはもうないかな」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66e1eadc-5d12-4c25-83a7-935db612b393.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59031d60-7c55-49bb-bc82-ffd361207dbf', '0602232c-8e51-48ab-906c-138145c67ba1', 2, '100098605', '空の上の森の中の', 'クトリたちが妖精兵器だと知って驚きを隠せないヴィレム。命に頓着しない彼女たちに、彼女たちの背負っている宿命の大きさを認識する。残り少ない命のクトリは、ヴィレムに最後のお願いをする。「わたしがあと5日で死んじゃうとしたら、もうちょっと優しくしてくれる?」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4d2e4f5-cd58-4934-8360-a77fff331bc7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c46bde85-aacd-4ff1-b123-42cc173697a0', '0602232c-8e51-48ab-906c-138145c67ba1', 3, '100098606', 'この戦いが終わったら', '妖精兵と聖剣との関係について話をするヴィレムは、クトリに聖剣「セニオリス」の使い方について、身体を張って指南するも無理が祟り、地面に突っ伏してしまう。「お前が『妖精郷の門』なんぞを開かず、死ななくて良い方法を考えてた」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a279f55a-88f0-49de-afa0-9b4cdede0b2b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b858021a-0eff-4b71-a926-355565bf0f33', '0602232c-8e51-48ab-906c-138145c67ba1', 4, '100098607', '帰らぬ者と、待ち続けた者たち', 'クトリたちが戦いに出てから暫くして、ティアットに一人前の妖精兵になる兆しが現れた。ナイグラートの代わりに彼女の検査に同行するヴィレムだが、ティアットに振り回されっぱなしで…。「やっぱり気になる? クトリ達のこと。もう半月も連絡ないものね」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/197f5f73-cc92-4d7e-8cc2-ba7f12565ac9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18459544-88bb-4a70-aace-87754324664b', '0602232c-8e51-48ab-906c-138145c67ba1', 5, '100098608', '誰も彼もが、正義の名のもとに', '15番島での戦いに窮するクトリたち。島を放棄し帰還するよう命令が下る。何としてでも獣を倒して無事帰還したいクトリだが、戦闘中、幼い少女の「声」が聞こえてきて…。「待ってるから、ちゃんと帰って来てよね」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e12691d4-ebee-449c-83e9-a8115450da31.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('047b8cb9-a37c-4268-8565-5c23d2e8a68e', '0602232c-8e51-48ab-906c-138145c67ba1', 6, '100098609', '消えない過去、消えていく未来', '妖精倉庫に帰って来たクトリ達。大賢者スウォンの元に向かってしまったヴィレムはいない。一方、久しぶりに再会するヴィレムとスウォン。昔話に花が咲く二人だが…。「今はただ、あいつらの元へ早く帰りたい」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e421346-37ed-4c52-9252-6dcb1236f217.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f13a0898-e8a3-4e20-a477-ba5fa6591c4d', '0602232c-8e51-48ab-906c-138145c67ba1', 7, '100098610', 'ただいま帰りました', '地上でサルベイジャーの護衛に就いている妖精兵、ノフトとラーントルクに面会するグリック。自分たちの存在意義に関わる「獣」の存在について、ラーントルクは問いかける。「俺はもう半分くらいはお前らの親のつもりでいるんだがな」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c27ec9d-7456-4a18-a07e-ad64028e22d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1e0a57a-e7f2-4af1-a653-6e3926d10e63', '0602232c-8e51-48ab-906c-138145c67ba1', 8, '100098611', 'いずれその陽は落ちるとしても', '地上のサルベイジャーの件で49番浮遊島の基地に出頭するように命を受けるヴィレム。妖精倉庫から妖精兵を連れてくるように指示が出るも、気乗りしないヴィレム。「妖精兵を一人地上に送れと言われた」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/312f76fa-6c0d-4e49-9024-6c2698c21420.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('703501bf-87cb-4472-b760-6f32f9d1e261', '0602232c-8e51-48ab-906c-138145c67ba1', 9, '100098612', 'たとえ未来が見えなくても', '自分が自分でいられるかどうか不安なクトリ。そこへ現れるアイセア。前世の記憶に悩まされていたのはクトリだけではなかった。アイセアは前世の浸食を受けた“ある女の子”の話をする。「その当時は、いっそ死んでしまおうとも考えた」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e423f1a7-1002-4ece-976f-68197ac891d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd019e69-8e9e-4857-8a22-a9e1bc065015', '0602232c-8e51-48ab-906c-138145c67ba1', 10, '100098613', 'いまこの時の輝きを', '地上の妖精兵、ラーントルクとノフトと対面したヴィレム。早速、魔力中毒になりかかっていた二人の身体のメンテナンスをしてやる。それでも17種の獣をバラまいた人間族の生き残りであるヴィレムを信用できないラーントルク。「人間は一体何から獣を生み出したのでしょうか」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fafdb074-31a9-4d04-a141-da96d314f4c8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99b88c2e-504b-449a-b7ef-1206048d3070', '0602232c-8e51-48ab-906c-138145c67ba1', 11, '100098614', 'どうか、忘れないで', '昨日の告白から何となくぎくしゃくしているヴィレムとクトリ、二人はグリックと遺跡で待ち合わせする。そこは、ヴィレムの生まれ故郷、帝国領ゴマグ市。その時、大きな地震が発生、ティメレの大群が出現する!「幸せに気づくことはできても、幸せになることはできません」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec70bb17-2fc5-49d9-974f-f12af86048a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e2b7d35-3373-4f61-b617-ea9b983cc14c', '0602232c-8e51-48ab-906c-138145c67ba1', 12, '100098615', '世界で一番幸せな女の子', '【シーズン1 最終話】襲いかかるティメレの大群。応戦するネフレン、ラーントルク、ノフトたち。しかし、その圧倒的なティメレの数に徐々に追い込まれていく。ヴィレムもその傷ついた身体でティメレに立ち向かう!「それでもきっと、あなたの存在はクトリにとって救いだったはずです」', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52e157df-bf92-42e6-b719-adc233e45528.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3033e19d-cb24-449d-9fc0-499045114bac', '終末のイゼッタ', '', 'hulu', 'izetta-the-last-witch', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50027046_series_art__338x600_izetta_the_last_witch_b3a2ca147901e0ecc8c78e1ee0c07a17.jpg?w=331&h=447&p=t', 'hulu', 2016, 3, 1, 'FINISHED', NULL, 21838, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9b068a1e-ca04-4af8-84f7-7d48271bed60', '終末のハーレム', '', 'hulu', 'worlds-end-harem', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63269fb9-dc81-4fb0-a12e-6b7fe73fa571.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 118465, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', '9b068a1e-ca04-4af8-84f7-7d48271bed60', 'hulu-worlds-end-harem-s1', '第1シーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2aa94180-ea7f-41ac-bf1c-677baf12dedb.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcaf7f01-675c-4582-a892-90f8025829ff', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 1, '100101303', '女たちの世界', '2040年、難病の細胞硬化症に罹り、コールドスリープすることになった医学生･水原怜人は幼馴染･橘絵理沙と再会を約束し、長い眠りにつく。だが5年後、目覚めると世界は一変していた。MKウイルスによって99.9%の男性が死滅していたのだ。ウイルスへの抵抗力を持つ怜人は、絵理沙に瓜二つの担当官･周防美来からある依頼をされる。それは人類の存続のため、残された女性たちとメイティング (子作り) することだった…!', '2022/01/15 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2aa94180-ea7f-41ac-bf1c-677baf12dedb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b73ce37a-cfa7-4ecf-b499-40054241ff8c', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 2, '100101931', '二人の女性', 'かわるがわる美女を抱き、憧れの美人女優ともメイティングできる…。最初に目覚めたナンバーズ･火野恭司は、この世界を心ゆくまで楽しんでいた。一方、怜人はメイティングの猶予を与えられる代わりに、美来からある条件を突きつけられる。それは、専属のボディガードとナースと毎夜、一緒のベッドで寝ることだった! それでも絵理沙への想いを貫く怜人。だが、シャワー中に裸の女性が現れ、強引に迫られてしまう。', '2022/01/22 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a67214c2-0588-4bbf-a525-6332f68d4470.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79e974b0-199a-402d-b9b2-2edd1ff4bede', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 3, '100102355', '第3の男', '3人目のナンバーズ･土井翔太のかつての高校生活は散々なものだった。不良たちに目を付けられ、いじめられる毎日。あげく、怜人たちと同じ細胞硬化症に罹り学校を去ることになってしまう。しかし5年後、コールドスリープから目覚めた翔太は、担当官･神谷花蓮のプロデュースによって高校生活をやり直すことに。待っていたのは、魅力的な女子生徒に囲まれた甘美かつ刺激的な青春…そして、かつて憧れた担任教師･羽生柚希だった。', '2022/01/29 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32585abf-04f1-49aa-9003-df484a229a22.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aacdbe3e-98c0-4df9-adac-b3d59d8ee189', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 4, '100102930', '学園の秘密', '柚希と逢瀬を重ね、その魅力に取りつかれていく翔太。その一方で、水泳の授業中に熱っぽい視線を浴びたり、たまたま裸を見てしまったり、とクラスメイトを意識することも増えていく。そんな中、花蓮からあるお願いが。女子寮の空調が壊れた為、翔太の部屋に交代でクラスメイトを泊めて欲しいというのだ。最初にやってきたのは一条奈都。彼女は一人では着替えすらできず、誰かと一緒でないと眠れないという浮世離れしたお嬢様で…。', '2022/02/05 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62c9bc5e-278b-4292-8ae6-5927c62af2ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d728158-8506-4b6a-b89e-f6ca54b7738e', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 5, '100103734', '最初の犠牲者', 'ワクチン開発が思うように進まない怜人。さらにメイティングを避けてきたことで美来が更迭、新たな担当官として片桐麗亜と黒田マリアがやってくる。2人を加え、慶門市へ向かう怜人たち。道中、研究者でもあるマリアにMKウイルス人工説をぶつけると、慶門市にはその手掛かりとなる重要人物がいると明かされる。期待に胸を膨らませ、怜人が旅館の温泉に入っていると、そこに女性陣がやってきて彼女たちの体を洗うことに…!?', '2022/02/12 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f595af8f-f82c-4afe-bfdc-2c50f7322d2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b570916b-2019-4459-a490-4cbd3700262f', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 6, '100104450', '絡み合う思惑', '谷口から日本初のMKウイルス感染者であった夫について聞き出せるかと思われた矢先、谷口の容態が急変したことで調査が行き詰まってしまう。しかし、彼女から預かった写真立てが絵理沙の残したスマートリングと反応。データを確認すると、それはMKウイルスの作成法に関する論文だった…。一方、日々にマンネリを感じ始めた火野。刺激を求め、新たなメイティング候補を探すのだが…彼が惹かれたのは怜人の妹･まひるだった!', '2022/02/19 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59e2d56a-76e0-442d-9309-0bb2fbbcab33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1396558f-a1a2-4448-b738-ea8ed37401c7', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 7, '100104838', '僕当番', 'この学園は全て、翔太様のために―。あまりに都合のよい状況に、戸惑いを隠せない翔太。そんな翔太をよそに花蓮はプロデュースの手を緩めない。ある日、翔太との相部屋を巡って抽選が行われる。当選したのは翔太が苦手な金髪ギャル･柳律香だった。メイティングを迫られると、トラウマがフラッシュバック。逃げ出した先で待っていたのは、翔太と同じ“痛み”を持つ少女だった。めくるめく快楽の渦が翔太を飲み込もうとしていた…。', '2022/02/26 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64fe7557-fbc3-4886-9266-85d195711ace.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4ed8a5c-6f23-474b-8757-fea5b73665ed', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 8, '100105675', '復讐', '転校生として、翔太の前にかつてのクラスメイト･星野汐音が現れた。いじめの現場に遭遇しても無関心だったタレント志望の美女。ナンバーズと繋がればタレントへの道が開ける―そんな打算的な彼女に翔太は“交換条件”を与える。それは、汐音が見ているなか翔太がいじめを受けた場所―屋上でのメイティングだった! 一方、怜人たちは過去に何人ものウイルス研究者が消息を絶った疑いのある慶門市中央区第三病院へ向かっていた。', '2022/03/05 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7edd1786-cdc3-4c58-b12b-8137a563916c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59855623-2aac-4ce4-834c-367a9a3be9bf', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 9, '100106406', '肉の森林', 'ナンバーズを巡り、世界は大きく動き出そうとしていた。UW世界本部は、公表された怜人以外にも抵抗力を持つ男性が隠匿されていることを嗅ぎ取り、UW日本支部との主導権争いを激化させていく。そんな中、狂気の世界を受け入れた翔太は、積極的にクラスメイトとメイティング。だが、クラスメイトの中には外部の勢力に内通する少女が紛れていて…。一方、第三病院への潜入に成功した怜人たちは、そこで意外な人物に遭遇する。', '2022/03/12 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a93c5daf-51fd-42bd-a450-a439e1a56249.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e90e041d-67a3-42d9-a0c1-2afc3391c095', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 10, '100107215', '二人のナンバーズ', 'テロリストの襲撃を受けながらも一命を取りとめた翔太は、花蓮からついに真実を明かされる。自分以外にも抵抗力を持つ男性が存在すること、そして花蓮が抱いている“野望”について。それを聞いた翔太は花蓮への協力を申し入れる。一方、UW世界本部に保護された怜人は、クロエから絵理沙がテロリストの一味だと明かされる。それでも絵理沙を信じたい怜人だったが、絵理沙たちのグループもまた不穏な動きを見せ始める…。', '2022/03/19 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a556d253-7222-46ea-976e-14853f14267c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd3aa3e3-b2f4-45b9-b14c-ace4c2bc866e', 'e7b331bd-af80-4a0a-99f6-b7f497c2bb3c', 11, '100107453', '脱出', '【第1シーズン 最終話】混沌とした状況の中、各勢力の動きが活発化する。成長促進器によって変貌を遂げた翔太は、クロエと怜人のことを探るため、花蓮とともに怜人に接触する。一方、怜人は美来を呼び出し、UW日本支部からの脱出を提案。何が本当で、何が嘘なのか。それを一緒に確かめたいと話す怜人だが、美来からある条件を突きつけられる。それは、美来とのメイティングだった…! 美来の切実な想いに、牙を剥く世界に、怜人はどう向き合うのか。', '2022/03/26 01:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e32320f-d9e0-49ac-ab1f-6b8f201049c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('332c0a21-5eaf-49aa-a28b-fa33cf7833ab', '舟を編む', '', 'hulu', 'the-great-passage-tv', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8130c5e7-564d-4edf-bf4c-9ee0ade2515b.jpg?w=331&h=447&p=t', 'hulu', 2016, 3, 1, 'FINISHED', NULL, 21703, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('aa10ca71-2fce-4244-adaa-d1a84b8012ca', '332c0a21-5eaf-49aa-a28b-fa33cf7833ab', 'hulu-the-great-passage-tv-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b5247e4-a40c-48b3-a91e-cde9029a0488.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6b79666-4a65-4ff4-8af5-bce6051ad0b7', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 1, '100152258', '茫洋', '辞書編集部員の西岡は、街の本屋でとある営業マンのお粗末な仕事っぷりを目撃する。それは、西岡も勤める玄武書房の社員である馬締 (まじめ) という男だった。一方、辞書一筋のベテラン編集者･荒木は、定年を前に後任者を探していた。そんな荒木に何気なく馬締の話をする西岡。すると荒木は突然立ちがり、足早に営業部に向かった。突然の訪問者に戸惑う馬締は、荒木からの『言葉』に関する質問に自分なりの答えを語る。その瞬間、荒木は馬締のセンスを見抜き、辞書作りに向いていると確信する。そして、その場で馬締をスカウトするのだった―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b5247e4-a40c-48b3-a91e-cde9029a0488.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5b4fd49-ea8c-4808-b46b-b52fc09cf3bb', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 2, '100152259', '逢着', '辞書編集部へ異動になった馬締は、荒木や監修の松本先生の辞書作りへの情熱を知ることになる。編纂途中の中型辞書･『大渡海』への想い、そしてなぜ新しい辞書を作り続けるのか……。そんな馬締は、彼らの期待に答えることができるのか……という不安に襲われていた。しかし、下宿先の大家･タケさんは言う。「頼ったり頼られたりすればいいと思うよ」。そんな満月の夜。下宿先のベランダで、馬締は美しい女性と遭遇する―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb3eed12-6d7c-41e5-a365-2e1311961d32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbcaea21-9314-45ff-bac4-800d3ea267c2', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 3, '100152260', '恋', '馬締が、タケの孫娘･香具矢に恋をしたことが発覚。そこで辞書編集部の一同は、香具矢が板前修業をしている店を訪れることに。西岡の雑談にも程よく答えながら、真剣に料理と向き合う香具矢に見惚れる馬締。彼女もまた、辞書作りと同じ長く困難な道を極めようとしているのだ。帰り道、西岡と馬締は語る。馬締は、場を作るのがうまい西岡を尊敬していた。そんな馬締を変な奴だ…と呆れる西岡は、これから面白くなるかもな…という期待も感じていた。しかしそんなさなか、西岡は『大渡海中止』という噂を耳にしてしまう―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/053c2cb8-2bd0-46cf-9f7a-6e7652fa3486.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('172c2a57-8ac9-41e2-bf0c-b094a8ccf2f1', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 4, '100152261', '漸進', '社内で噂される『大渡海中止』の動きを阻止すべく、辞書編集部は西岡発案の大胆な策を実行する。一丸となって奔走する一同。そんななか西岡は、今までにない生き生きした表情を浮かべていた―――。数ヶ月後。久しぶりに休日を取った馬締は、タケの後押しもあり香具矢と二人で出かけることに。二人は観覧車に乗り、東京の街を見渡した。そして、料理への情熱を語る香具矢。感動した馬締も、自分なりに想いを伝えようとするのだが……。その夜。馬締は香具矢へ想いを伝えるべく、手紙を書き始めた―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/631f82f8-950e-45dc-a990-d1924f3f3350.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e662887-abed-4a2e-abeb-24551d6d67c9', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 5, '100152262', '揺蕩う', '局長に呼び出された西岡は、『大渡海』続行の条件を言い渡される。それは、別の辞書の改訂と、西岡の宣伝部への異動だった―――。辞書作りへの情熱を感じ始めていた西岡はショックを受ける。しかし、『大渡海』の見本刷りを見て喜ぶ編集部員たちや、既に条件である小型辞書の改訂作業を始めている馬締。そんな彼らを目の当たりにし、「異動までに俺ができることは全部やる!」と意気込むのだった。一方、恋文が完成した馬締は、勇気を振り絞り香具矢に手渡した―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7176bd2d-20ad-409f-ac98-37425d57c311.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea4de041-c896-42a4-a49b-38d501f0a2cd', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 6, '100152263', '共振', '恋文を渡した翌朝、香具矢に遭遇した馬締は思わず逃げ出してしまった……。その日の昼、今後の対策について話しあう編集部員たち。そこで、西岡が自身の異動を告白する。衝撃を受ける一同。西岡さんが……と呆然となる馬締は、不安に襲われつつ帰宅するのだった。その夜、恋文の返事を香具矢に迫る馬締。絶対今日中に聞けと西岡から助言を受けていたのだ。しかし、動揺した香具矢は部屋に戻ってしまった。振られた……と肩を落とす馬締。しかし、恋文の文面を再確認してきたという香具矢は、馬締へ想いを告げる。「私も、好きです」―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ceb38123-051f-48bb-9066-dbe0ad0ff7bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f714f1a-a174-48b2-9721-753f7b947706', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 7, '100152264', '信頼', '大学教授から上がってきた原稿に問題が見つかり、西岡と馬締は修正案を作成する。そのなかで馬締は、大渡海には西岡が必要だと改めて感じる。そんな馬締に、西岡は力強く語る。たとえ離れても、お前をフォローし続けると―――。数日後。修正に激怒した教授から連絡が入り、西岡は一人謝罪に向かう。露骨に不機嫌な態度をとる教授。しかし西岡は機転をきかせ、教授に今後の協力を約束させる。大学を後にした西岡は、晴れやかな表情で新たな道を歩き出した。そして馬締も、新たな決意を胸に一人作業を続けていた―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98efd481-2eb8-47a9-9a16-c8ccf2d23e5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ae42fa9-9d0c-4e68-aeb3-6a0c69b91573', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 8, '100152265', '編む', '13年の月日が流れ、新たな社員･岸辺がやってきた。しかし、入社以来ファッション雑誌を作ってきた岸辺は、なぜ私が辞書を……という悶々とした思いを抱えていた。そんななか岸辺の歓迎会をすることに。そこで馬締は、岸辺が「言葉を大事にする人」だと言う。しかし理解できない岸辺は、自分に辞書作りは無理だと店を飛び出してしまった……。そんな岸辺と遭遇した西岡は、ある質問をする。それはかつて、荒木が馬締のスカウトを決めた『言葉』に関する質問だった。岸辺の答えを聞いた西岡は、微笑みこう言った。「君、辞書向いてるよ」。翌日。辞書編集部には、率先して仕事をする岸辺の姿があった―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef7a7ed8-0c09-4b4c-b7b2-842f954c8509.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9672435-d7a9-4c0f-a61b-f5246b896e55', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 9, '100152266', '血潮', '新たなスタートを切った岸辺は、松本や馬締との交流のなかで、『言葉』や『辞書』についてより理解を深めていく。そんななか総仕上げの作業が始まり、並行して『大渡海』専用の紙の開発も続けられていた。来る日も来る日も机に向かい、黙々と作業をする一同。そして季節は移り変わっていく―――。約一年が経過し、とうとう紙が完成した。そして同時に、営業や宣伝といった他部署との打ち合わせも重ね、日に日に大渡海の完成に近づいていく。そんなある日、重大なミスが発覚してしまう―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36ec94fe-6f98-4b43-8b54-a4f5e83938be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d7b61ad-c250-4416-bb53-38c23c8e92ca', 'aa10ca71-2fce-4244-adaa-d1a84b8012ca', 10, '100152267', '矜持', '抜けている単語が見つかり愕然となる編集部員たち。そこで馬締は、24万語全てのチェックをやり直すと決断した。そんな矢先、松本が入院してしまう。焦る馬締は、いち早い『大渡海』の完成を目指し、黙々と作業を続けるのだった。そうして、編集部員とアルバイトたちの壮絶な合宿生活が始まる。昼夜問わず作業を続け、限界まで働き続けた。馬締は他部署との打ち合わせなどもこなしつつ、かつての自分を振り払うかの様に作業に没頭した。そして時は流れ……とうとう全ての再確認が終了した。西岡も駆けつけ歓喜に湧く一同。こうして、『大渡海』の完成が迫ってきたが―――。', '2023/08/30 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aefd4175-aea3-4fef-b6d7-8bedb56ddcdf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e8f18006-b8b5-404f-9c6f-e54c1af6c76e', '週刊ラノベアニメ', '', 'hulu', 'light-novel-anime', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73fcf93c-f244-4b25-b1fc-029ecbed0d04.png?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 198745, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f2155558-ffb2-401e-a907-dd44f842ac83', 'e8f18006-b8b5-404f-9c6f-e54c1af6c76e', 'hulu-light-novel-anime-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bcfefcb6-ee5e-4bbf-8589-828fbfaede9b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63f64031-64da-4aed-ba02-39d1ac0cb0ee', 'f2155558-ffb2-401e-a907-dd44f842ac83', 1, '100237933', '第1話', '『Jack the Reaper』気がつくと、俺は取調室にいた。自分が何者かも一切記憶がない。戸惑う俺の前に現れたのは、若い女刑事。『傷心タイムリープ』クリスマスに若菜は想いを寄せる和瀬に告白するがフラれてしまう。失意の中、過去の日記を辿っていると、不思議な光に包まれ、彼女は半年前へタイムリープしていた…! 『ファムファタル育成計画』阿多川祐樹は、自他共に認める170cm95kgの愛されるデブ。従妹を傷つけた元カレを見返すため「俺が美女になってアイツを惚れさせて、手ひどく振ってやる!」とダイエットを決意する! 『マリー･アントワネットに転生したので全力でギロチンを回避します』オタク女子が転生したのは、マリー･アントワネット! 無事にギロチンを回避することができるのかーー⁉', '2025/09/30 03:50:00', 1374, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bcfefcb6-ee5e-4bbf-8589-828fbfaede9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16092007-a9a0-4af5-b1da-a56d5f24f125', 'f2155558-ffb2-401e-a907-dd44f842ac83', 2, '100237934', '第2話', '『Jack the Reaper』繰り返す死の中で、自分の置かれている状況を少しずつ解き明かしていく。。『傷心タイムリープ』振られたクリスマスから一転、気づくと4月にタイムリープしていた若菜美梨。過去をもう一度やり直す決意をする。そんな下校時に雨が降り…。『ファムファタル育成計画』ダイエットを決意した阿多川祐樹。さっそく食事制限を始めるが、、。『マリー･アントワネットに転生したので全力でギロチンを回避します』マリーアントワネットに転生してしまった主人公。ルイとの結婚式と共に、豪華絢爛な新しい生活が始まる。。', '2025/09/30 03:50:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62114ec1-e0d2-4fb5-aa97-8b9ec3eef8b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('749503ef-ec4f-44a0-b84e-1346434188f3', 'f2155558-ffb2-401e-a907-dd44f842ac83', 3, '100237935', '第3話', '『Jack the Reaper』連続殺人事件の容疑者となった俺。まずは目の前にいる婦警の名前を聞き出そうとするが…。『傷心タイムリープ』また振られたクリスマスに戻った若菜。ただ、過去を変えた結果、未来が少し変わった事に気づく。次なる分岐点を探しスマホに手を当てると、席替えの日に戻っていた…。『ファムファタル育成計画』思うようにダイエットが進まない阿多川祐樹。山田のアドバイスで家庭部で栄養管理が得意な緋山あさぎの元へ訪れるが…。『マリー･アントワネットに転生したので全力でギロチンを回避します』慣れない舞踏会に参加するアントワネット。そこで、国王の公妾 デュ･バリー夫人にぶつかってしまうが…。', '2025/09/30 03:50:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df20bfdd-55cb-4710-9571-60ee8fd1b118.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51f437d8-9997-4ca9-acd7-b88334a1bf2b', 'f2155558-ffb2-401e-a907-dd44f842ac83', 4, '100237936', '第4話', '『Jack the Reaper』いよいよ限界を感じた俺は、婦警を気絶させて取調室から脱出を図るが…。『傷心タイムリープ』和瀬と距離を置くきっかけになった「席替えの日」にタイムリープした若菜。今度はすれ違いを回避する為に…。『ファムファタル育成計画』実は太っていた過去を隠して生活してきた緋山あさぎ。そんな彼女に、あるトラブルが起き…。『マリー･アントワネットに転生したので全力でギロチンを回避します』デュ･バリー夫人への誕生日プレゼントに何を送るか悩むルイ、シャルル、スタニスラス。そこでマリーはあるアイディアを思いつき…。', '2025/09/30 03:50:00', 1408, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66b948a5-dfe5-49e3-b595-8a33c84b0123.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64df5ff0-a6c8-4705-bd11-bade5be8c19f', 'f2155558-ffb2-401e-a907-dd44f842ac83', 5, '100237937', '第5話', '『Jack the Reaper』婦警の名前をGETした俺は、次に受付ロビーから外へ脱出を図る。そこに待ち受けていたのは、白いスーツの男…。『傷心タイムリープ』席替えのすれ違いを回避した若菜。クリスマスの夜に戻ったが、またも振られてしまう。次はどの過去を変えればよいかと奮闘するが…。『ファムファタル育成計画』放課後、緋山あさぎの元に集まる、阿多川祐樹達。そこでダイエット講義が始まる…。『マリー･アントワネットに転生したので全力でギロチンを回避します』いよいよデュ･バリー夫人への誕生日。ルイからは「歌」をプレゼントする…。', '2025/09/30 03:50:00', 1277, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/252e7831-8676-4978-a07d-65c2d687dc6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc1e33ad-c408-4739-986e-95068de89c50', 'f2155558-ffb2-401e-a907-dd44f842ac83', 6, '100237938', '第6話', '『Jack the Reaper』矢継早と1対1で戦う事になる俺。繰り返す死の中で、また新たな手掛かりを求めるが…。『傷心タイムリープ』大きく過去を変える事を決意する若菜。次は会話の機会が減っていた時期、テスト後にタイムリープをするが…。『ファムファタル育成計画』緋山あさぎの指導で食生活も見直し、10キロも体重を落とした阿多川祐樹。従妹の家に訪れるが…。『マリー･アントワネットに転生したので全力でギロチンを回避します』デュ･バリー夫人への歌のプレゼントを成功させたマリー。次はマリーの誕生日にスタニスラスも一緒に歌ってもらおうとするが…。', '2025/09/30 03:50:00', 1363, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81157374-5206-4e9b-9557-691f12fe2e4c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a99c1cbe-a138-4e27-8892-3de60f3c1c1e', 'f2155558-ffb2-401e-a907-dd44f842ac83', 7, '100237939', '第7話', '『Jack the Reaper』決意新たに、いくつもの作戦を試みる俺。果たして…。『傷心タイムリープ』補習を抜け出してきた若菜は、和瀬に陸上部を辞めた理由を問うが…。『ファムファタル育成計画』ランナー膝になってしまった阿多川祐樹。次は運動の専門家の仲間を求め、「鏡 基之」を仲間に取り込もうとするが…。『マリー･アントワネットに転生したので全力でギロチンを回避します』3人の王子から「歌」のプレゼントに興奮を抑えきれないマリー。次なるマリーの作戦とは…。', '2025/09/30 03:50:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a100763-180b-41af-a887-718672f7b125.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92da4630-7551-481a-886f-d79bca579b17', 'f2155558-ffb2-401e-a907-dd44f842ac83', 8, '100237940', '第8話', '『Jack the Reaper』「警察官連続殺人事件」の真相を探る俺。小町の気持ちに答えるべく、「いつもの呼び方」を当てようするが…。『傷心タイムリープ』夜の公園で二人きりになる若菜と和瀬。若菜は和瀬にある想いを伝える。『ファムファタル育成計画』鏡に仲間になる事を断られた阿多川祐樹。近くのスイミングスクールに足を運ぶ祐樹は、そこで偶然鏡に会い…。『マリー･アントワネットに転生したので全力でギロチンを回避します』スタニスラスに心から歌ってもらう為に、まずは仲良くなろうとするマリー。マリーの次なる作戦とは…。', '2025/09/30 03:50:00', 1404, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/adb2e1ef-8de2-432b-9714-441004e746ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58d5f926-7644-4e27-a4c4-2aec436dd216', 'f2155558-ffb2-401e-a907-dd44f842ac83', 9, '100237941', '第9話', '『Jack the Reaper』「警察官連続殺人事件」の資料を探し続ける俺。タイムリープ能力を活用し、ようやく見つけた資料にはいくつか不可解な点が…。『傷心タイムリープ』遊園地に4人で遊びにいった日にタイムリープする若菜。和瀬との関係に変化を起こせるか…。『ファムファタル育成計画』ダイエットの方向性で言い争いになる鏡と緋山先輩。あたふたする祐樹。そこへ鈴木が改めて今回のファムファタル育成計画の作戦を語る。そこから見えてくる園村の好みの女性のタイプとは…。『マリー･アントワネットに転生したので全力でギロチンを回避します』本をきっかけにスタニスラスとの距離も縮まってきたマリー。次は2月にある国王陛下の誕生日に向けて、また歌をプレゼントする事が決まり…。', '2025/09/30 03:50:00', 1412, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b646c0f-1c55-4ebc-9dde-c48582ebe4c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7239bdd-35ba-406b-87fc-f516c89e7ca5', 'f2155558-ffb2-401e-a907-dd44f842ac83', 10, '100237942', '第10話', '『Jack the Reaper』捜査に行き詰まるも、それでも俺が犯人でないと信じ続けてくれる小町。その想いを聞き、改めて二人で一緒に捜査して欲しいと説得をする俺。その時3時の鐘が鳴り…。『傷心タイムリープ』水族館に寄り道をする若菜と和瀬。その帰り、和瀬はある想いを語る…『ファムファタル育成計画』怪我も治ってきて、ダイエットは順調に進行中の祐樹。しかし、声や仕草などの女子力がまるで足りてない事を、山田、鈴木、鏡は指摘する。そこで対策として…。『マリー･アントワネットに転生したので全力でギロチンを回避します』お忍びでオペラを見に行くマリー達。現在のオペラの様々な課題に気づいたマリーは、そこから、ある考えを思いつき…。', '2025/09/30 03:50:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae2fdb2d-67b5-4107-b274-0aa0d820e4b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60bba2e6-ea12-4851-ac28-ecad7c7a7bb3', 'f2155558-ffb2-401e-a907-dd44f842ac83', 11, '100237943', '第11話', '『Jack the Reaper』死から目を覚ました俺は、小町を名前を呼びながら抱きしめる。その後、証拠保管室に向かう事を納得した小町は、ある考えを思いつくり…。『傷心タイムリープ』帰り道の公園で、若菜は和瀬に告白の返事を求めるり…。『ファムファタル育成計画』女性らしい声や仕草が欠如する祐樹。対策としてVTuberのひぐらしまわたに協力を求めり…。『マリー･アントワネットに転生したので全力でギロチンを回避します』国王陛下の誕生日に向けて、3王子と歌のレッスンを始めるが、何故かルイの声が小さく。それが原因で喧嘩まで始まってしまいり…。', '2025/09/30 03:50:00', 1344, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0aa2a66-9058-4bd4-96db-4069a1c89c09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('299a425d-4f06-4010-a403-87a7bb31f189', 'f2155558-ffb2-401e-a907-dd44f842ac83', 12, '100237944', '第12話', '『Jack the Reaper』証拠保管室へたどり着いた時城。ドアの先には...。『傷心タイムリープ』これまでのタイムリープを振り返る若菜。そうして季節は廻り...。『ファムファタル育成計画』様々な努力を重ねてきた祐樹は、ついに70キロ台に突入する。そんなある夜、祐樹の元に月乃が訪ねてくる...。『マリー・アントワネットに転生したので全力でギロチンを回避します』ルイの様子に違和感を覚えたマリーは、ルイの部屋を訪ねる。そこでルイは、胸の内にしまっていたある想いを打ち明ける...。', '2025/09/30 03:50:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4297aac-b956-4c44-8d73-aacdf72f0621.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2cd2a851-1eb2-4239-9431-28fc311b7809', '十二国記', '', 'hulu', 'the-twelve-kingdoms', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50026164_series_art__338x600_the_twelve_kingdoms_f3655e518409e591fd869aea87859b96.jpg?w=331&h=447&p=t', 'hulu', 2002, 1, 1, 'FINISHED', NULL, 153, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('df17e28e-8f2d-4cd9-a31c-8db97288f076', '2cd2a851-1eb2-4239-9431-28fc311b7809', 'hulu-the-twelve-kingdoms-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/618e94fa-fd6b-4c56-9bc4-babb03bfd7cb.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6c1e981-2314-4dbc-8b0c-6779284ca591', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 1, '60740277', '「月の影 影の海」 一章', '代わり映えのない生活を送っていた中嶋陽子は、日ごとに進行していく『夢』を見続けていた。不安を募らせる陽子の前に金色の髪を持つ『ケイキ』と名乗る青年が現れる。探していたと云われ、さらに困惑してしまう陽子。一方的に連れ出されて二人が向かった先は屋上。そこには巨大な鳥が陽子を待ち受けていた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/618e94fa-fd6b-4c56-9bc4-babb03bfd7cb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('208f26d6-9fb2-45bf-a2f6-7bb8d426faa9', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 2, '60740283', '「月の影 影の海」 二章', '光の渦を抜けてきた陽子。自分はどこにきたのか、そんな不安を抱く陽子のもとに新たな妖魔が現れた。ケイキたちとはぐれ気を失っていた陽子が再び目を覚ますと、今までに自分が見たことのない海を目にする。ぼう然とそれを眺めた後、『ケイキ』という名を頼りに歩き続ける陽子。一つの集落を見つけ安心する陽子だが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4ca2627b-426d-4071-8cf9-36092908af1c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('852c8686-31a7-490c-9687-c4b52408e19b', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 3, '60740242', '「月の影 影の海」 三章', '陽子たちが乗せられた馬車に、黒い妖魔の群れが襲いかかった。陽子の身体に取りついた賓満の力が発動し、陽子、杉本、浅野の三人は何とかその場を切り抜けることができた。当てもなく森の中を歩きまわる陽子たちは、やがて一軒の家を見つける。その家の部屋の中で陽子たちは食べるものや着るものを探すが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/15c486c7-5435-407d-82ff-c5afe0fafb76.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2d62d1d-dcaa-480b-a0ee-38bf83b2386b', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 4, '60740244', '「月の影 影の海」 四章', '達姐について行った陽子たちは、ようやく達姐の母親が営む宿屋にやってきた。しかし、母親のところに話をしに行った達姐は、なかなか戻ってこない。陽子が店の奥へと入っていくと、達姐と母親の会話が聞こえてきた。愕然とする陽子。達姐は陽子たちに仕事を紹介するのではなく、宿に売り飛ばそうとしていたのだ…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a62f4b6e-df77-479c-b8e3-4d7ed1df74b6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ad2bdf8-2267-402a-b994-ce8fc104c1fb', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 5, '60740270', '「月の影 影の海」 五章', '森の中で出会った金色の髪の女性から自分がこの世界のために必要だと言われた杉本は、陽子や浅野と別れて別行動をとることにする。空腹に耐えきれなくなる浅野を見かねた陽子は人から食料を奪おうと決意する。通りかかった人影の前に飛び出した陽子だが、そこにいたのは芝居を観た時に出会った旅芸人の親子だった…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/06c27c4a-bdb5-4c12-bb13-abeb82f81ca2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8724072-993c-499a-9e07-6c9cf119955a', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 6, '60740252', '「月の影 影の海」 六章', '剣を振るう杉本は、陽子と互角に渡り合う。とうとう陽子は傷つき、気を失う。気づくと、陽子は見知らぬ家に寝かされていた。そこに現れたのは、言葉を喋るねずみ。ねずみは「楽俊」と名乗り、自分を「半獣」だと告げる。そして陽子のかたくなな心に踏み入ることなく、楽俊は傷ついた陽子の世話をしてくれるが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/005ea163-cdb1-4c1a-8742-a66c311009a5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5f37cf6-4f42-4934-880f-70f04c31da0f', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 7, '60740251', '「月の影 影の海」 七章', '楽俊とともに雁の国を目指して旅立った陽子は、訪れた街で妖魔に襲われていた。その最中、他人を押しのけ我先にと逃げる人々や、妖魔が入ってこないように門を閉める役人たちの姿を見た陽子は、人は他人のためには生きられないのだと悟るのだった。妖魔を倒し終わった陽子は、傷ついて動かない楽俊の姿を見つけて…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8c632804-1f28-4a22-810f-aac43b447ecb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ce89542-49b3-43f2-b6a8-8f3fb122ec09', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 8, '60740272', '「月の影 影の海」 八章', '荒廃した村で生活を送っていた杉本は塙王に呼び出され、陽子が生きていることを知らされた。再び陽子を殺める機会を望む杉本に塙王は賓満に命を吹き込ませるよう塙麟に命じる。一方、港街で微真たちの興行を手伝っていた陽子は、その夜宿屋の一室で微真たちから一緒に雁国まで行かないかともちかけられるが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ab179795-e2ca-4de9-8763-9e19a196e5f6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05c1e9bc-d4b1-44e1-a67a-c6fc7b69ec44', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 9, '60740284', '「月の影 影の海」 九章', '巧国から出航した船で、雁の国へとやってきた陽子。そこへ自分の名を呼ぶ懐かしい声が聞こえてくる。振り返った先には、家に戻ったと思っていた楽俊の姿があった。楽俊は陽子より雁国まで先回りして、これからの道筋を立てるために方々に連絡を取ってくれていたのだ。二人は陽子の戸籍を得るために街の役所へ向かうが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/53c6336e-54fe-444f-9e36-1a92b0ddce9e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13999a27-a87d-4bd9-932f-b17a955c175f', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 10, '60740249', '「月の影 影の海」 十章', '延王を尋ね訪れた雁国の街で、再び妖魔に襲われた陽子は苦戦を強いられていた。そこへ男が助けに入ってくる。その桁違いな腕力や見事な剣さばきに、次々と倒されていく妖魔たち。戦いの最中で男は小松尚隆と名乗り、自らを延王と呼んだ。妖魔を倒した後、陽子と楽俊は尚隆の泊っている宿屋へと連れてこられて…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/215c7da8-e0c6-4b56-86a9-e44cc43a7e61.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80ec3a10-5d11-42bf-908a-bf0851d8052b', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 11, '60740291', '「月の影 影の海」 十一章', '戦乱に明けくれる中世の京都。そこには六太の姿があった。雁国の麒麟の卵果として、蝕によりこの地へと流れ着いていたのだ。しかし家族を養っていくことが出来ないと悩む両親の手によって、六太は山の中に捨てられてしまう。そして女怪によって自分のいるべき場所へと戻ってきた六太は麒麟としての宿命を知らされて…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/29c238bf-97e4-46dd-a86e-d38c450050c8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f988007c-fcca-47f8-b4de-cd6225e62937', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 12, '60740269', '「月の影 影の海」 十二章', '雁国の王と麒麟との出会いを聞いた陽子。楽俊からは前の慶国の王は商人の娘だったことを聞き、景麒は何故普通の人を王として選んだのか考えていた。すると水禺刀が強く光り始め、そこに景麒と見知らぬ女性の姿を映し出した。一方、壁落人の所にいた杉本は子供たちと遊ぶうちにその顔には自然な笑みが浮かんでいたが…。', '2017/05/26 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4f6667d2-1db2-4820-9923-cf4e5e19ac6e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('375e09ea-87f5-4510-8280-b5e5f82163ee', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 13, '60740296', '「月の影 影の海」 終章', '新たな王が誕生する慶国に劣り、愚王だと呼ばれることを怖れて陽子を殺そうとした塙王。その真意を暴かれ立ち尽くす塙王の前に、失道の病に陥った塙麟が姿を現し、再び善き治世を行って貰いたいと願う。だが塙王より陽子を殺すように命じられ、悲痛な表情を浮かべる塙麟に陽子は耐えられず、間に割って止めに入るが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/836eeb52-18fd-48e6-bd0f-8e429e736837.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7220560-9f4f-489d-98c2-b60973d7f1a7', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 14, '60740245', '「月の影 影の海」 転章', '先代の慶国の王の妹である舒栄を偽りの景王として立てることで、慶国が自分の国よりも豊かにならないように企てた塙王。しかし巧国の麒麟である塙麟の「死」により、それが現実になることはなかった。そして、理由を聞く暇も与えられず景麒によって連れてこられた陽子は、自分自身で慶国の新たな王となることを選び…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8a7c86d2-1a46-408b-bb20-d6432cc98643.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7cd9c092-9c24-47e9-acd5-de102a71286f', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 15, '60740263', '「風の海 迷宮の岸」 一章', '国の麒麟である景麒によって王としての選定を受けた陽子は正式に王位を授かるため、天が存在するという世界の中央にある五山の一つ、蓬山を訪れていた。天から王位を授かる間、王と麒麟が滞在する宮へと向かう際に景麒は陽子にどうしても寄りたい場所があるという。そして景麒は蓬山に住む女仙の一人、蓉可と再会して…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b0e20ed7-6ee7-40ec-b841-05a332bac339.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f33065f9-3e59-48f5-8af3-7e319c91e98c', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 16, '60740240', '「風の海 迷宮の岸」 二章', '陽子は自分と同じく胎果として日本で育った、幼い戴国の麒麟の話を景麒と蓉可から聞いていた。戴国の麒麟の卵果は蝕によって日本に流されてから十年の時を経て蓬山へと帰還した。自分の出生の秘密を聞かされ、その事実を受け入れた泰麒は家族の側にいてはいけなかったのだと理解し、故郷への別れを受け入れたのだった…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e6318cbd-f5e1-4e6d-a257-882ba511603c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5c5ad140-2ebc-4524-af4f-d6031e3c72d6', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 17, '60740292', '「風の海 迷宮の岸」 三章', '麒麟の姿にどうすれば変わることができるのかと悩む泰麒。だがほんの一瞬、汕子が目を離した隙に泰麒は突如蓬廬宮の外へと引きずり落とされてしまう。自分の身に何が起こったのか分からない泰麒。自分の手首に鎖が巻きつけられ、そこから赤い血が流れ出しているのが見えた。鎖をたどった先にいる男は醐孫と名乗り…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/437281d8-31d4-4bcc-ab98-8f07e2aee5ee.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ed38761-ac4a-49ee-8615-c92ed2f1d287', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 18, '60740268', '「風の海 迷宮の岸」 四章', '麒麟は生まれながらに転変や使令を持つ方法を理解しているもの。泰麒は例外であり、何も知らなかった。そこで何か助力を頂ければと碧霞玄君玉葉が景麒を呼んでくれたのだった。しかし、景麒は帰らなければいけない時がやってきた。別れ際に景麒は、泰麒が王を選ぶことが出来た時、会いにきてくれることを約束して…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/dc4cc2a9-3d1e-42d8-b0da-8b423f5e58b7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec905ffc-655f-4b82-8a0c-c5fb8006cfe2', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 19, '60740293', '「風の海 迷宮の岸」 五章', '泰麒は新たな戴国の王となるべき人物を見い出せなかった。そのことに安心した泰麒は毎日のように李斎と驍宗に会いに出かけるようになった。そんなある日、驍宗たちとスウグ狩りについていくことになった泰麒。だが、行きがけに言われた女仙たちの発言が泰麒の身を案じるばかり驍宗と李斎に対する侮りとなってしまい…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bb90ced5-e6a9-42e2-a00e-c3a1fed42b62.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a873c5fa-9895-4404-94de-ea013a120caf', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 20, '60740264', '「風の海 迷宮の岸」 終章', '泰麒は戴国の王として驍宗を選んだのだ。だが嬉しい筈の泰麒からは明るさが失われていた。天から王を任じる儀式の際に天啓を持たぬ王は天の裁きがその身を滅ぼしてしまうと思い、驍宗を死なせてしまうことに苦悩する泰麒。そして天勅を戴く瞬間が訪れた。泰王としての天勅を戴いた後、泰麒と驍宗は白圭宮へやってきて…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e7309f83-8b5c-435a-8427-f8709dd09fe3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7c8ab6a-5587-4251-ab78-da40034eba31', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 21, '60740255', '「風の海 迷宮の岸」 転章', '十二の国の内情を六太は気にかけていた。国には王がいるだけで最低限荒れることは無いのだが、王がいない国は土地は荒れ妖魔が出没し民は貧困に喘ぐことになるのだ。最も荒れている国が北東の端に位置する戴国であった。戴国では王と麒麟の行方が分からなくなっていた。六太は戴国の小さかった麒麟、泰麒を考えていた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/10011891-67a3-4389-8367-995470db6af7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5193e777-ecd4-482c-a560-29967bf7a1c5', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 22, '60740246', '「書簡」', '雁国首都、関弓山の麓に展開した大学。そこに楽俊の姿があった。陽子が景王として登極した頃、楽俊は延王の配慮があって大学への受験を許され、合格に向けて精一杯勉学に取り組んだ。その結果が現在に至ったのだ。楽俊の部屋に向かって人の声を運ぶ鸞鳥が舞い降りてくる。鸞鳥は凛とした女性の声で語り始めた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/22e6795f-659c-46b0-9e96-887da9771cae.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87dd7ab0-b704-4bc1-9577-097537594a1b', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 23, '60740287', '「風の万里 黎明の空」 一章', '大木鈴は触によって十二国の世界へと渡ってしまう。一方、芳極国で華やかな王宮暮らしを送っていた祥瓊。あまりに苛烈な法の裁きは国の人口を激減させることとなり、王の半身である麒麟の身体は王が道を失い始めると陥る失道の病に倒れてしまう。そして、新たな王となった陽子は王としての自分に悩み苦しんでいた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4bb80d7f-42b9-4f5f-b757-311deec228f0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75a59be2-0f17-4913-b6b2-bd83235a846b', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 24, '60740262', '「風の万里 黎明の空」 二章', '鈴は才国琶山の中腹にある翠微洞へ戻ってきた梨耀から慶国に新しく即位した女王のことを教えられる。一方、里家と呼ばれる場所で両親を亡くした子供たちと働きながら生活を送る中で祥瓊はそんな苛烈なまでの虐げを受けていた。その頃、慶国では即位の儀式を終えた陽子を雁国の王と麒麟、そして楽俊が迎えてくれていた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/750d3ada-7f36-4e36-9269-91747f4fc884.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b961cb4-0ecf-45a1-98d2-bc703f16edbf', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 25, '60740276', '「風の万里 黎明の空」 三章', '梨耀のもとで苛烈な扱いを受けている鈴は、蓬莱出身の景王に会うことさえできればこの場所から救い出してもらえるのだと、自分の中の景王像を日増しに強く描くようになっていた。そんな景王に期待の念を描く鈴とは反対に、憎しみを募らせていく祥瓊。その頃、陽子は少しずつ国の内情を理解し始めることができていた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/dd7fec11-b2b9-425b-a772-3d56bb1e57c2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf55d14a-bef8-47b4-8590-91c38d6b453a', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 26, '60740254', '「風の万里 黎明の空」 四章', 'とうとう逃げ出す決意を固めた鈴は、才国の首都揖寧へと向かう。一方、自分の正体を里の人々に知られてしまった祥瓊。処刑が行われ始めた時、止めに恵州州師が駆けつけた。州師に連れていかれた祥瓊は、両親を殺し簒奪を企てた張本人である月渓と再会する。そして陽子は太師の屋敷に休息を兼ねて食事に招待されるが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/79a2542d-a29b-4dcc-a557-58d12187b17b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f861cc1-a63d-4a1a-9703-872d846182c4', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 27, '60740271', '「風の万里 黎明の空」 五章', '祥瓊は月渓の命によって恭国へ身柄を預けられることになった。そこで祥瓊は供王の奚として働くことになる。同じ頃、梨耀から逃げ出し采王を訪ねて王宮へ辿りついた鈴。采王から里で暮らすようにと勧められる。そして陽子は自分の治める国で生きる里の人たちと一緒に生活し、見えないものを見つけにいくことを決意して…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6a29ef12-f3a5-4362-bb36-31b0973e35c8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75d853b5-0068-427d-a708-675e576acffa', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 28, '60740290', '「風の万里 黎明の空」 六章', '景王に会いに行くために慶行きの船を待ち奏国に留まっていた鈴。そこで鈴は触によって流された時に出会った少女と再会した。一方、恭国の王宮で奚としての生活を送る祥瓊だが、いつまでこの生活が続くのだろうと苛立ちを募らせていた。その夜、御庫へと向かう祥瓊。翌朝、御庫は荒らされ王宮の中に祥瓊の姿は無かった…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/67a317df-3eca-448f-8779-2d8fb0f2d260.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d367f049-2bdb-4be9-9305-d6b23ba2fa32', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 29, '60740258', '「風の万里 黎明の空」 七章', '慶国の固継という里で生活を送り始めた陽子は、閭胥である遠甫から教えをこうていた。一方、ようやく慶行きの船に乗ることができ、景王に会いに行くという目的に一歩近づいた鈴。だが鈴は船で知り合った清秀に何故か冷たい態度をとられ続けていた。そして、恭国の御庫より宝飾品を盗み出した祥瓊は柳国へときていた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a06c83e9-0a86-4c2b-b331-b27fd3a98313.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9e93bbc-4873-425f-877f-ba313fccec2b', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 30, '60740257', '「風の万里 黎明の空」 八章', '祥瓊は恭国の御庫から宝飾品を盗んだ罪によって捕らえられたが、賄賂を要求してくる県正とやりとりをすることで処罰もなく出てくることが出来た。ようやく慶国へと辿り着いた鈴たちは馬車に乗り首都堯天を目指す。一方、不穏な影に気を張り続けていた陽子は遠甫を尋ねてきた奇妙な男の使いをした労という家を訪ねる…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c3db5902-08c0-46d0-b367-e92e285eab2f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a34cded6-88b0-4263-b9f2-97c5b08fbd69', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 31, '60740241', '「風の万里 黎明の空」 転章', '慶国の戸籍を得るために一旦戴国へ渡ろうとした祥瓊は、柳国で出会った楽俊とともに柳国と雁国との国境の街へとやってきた。祥瓊は楽俊と旅することによって玉座に王がいないというのがどれだけ国に対して影響を与えるのかを理解する。楽俊から祥瓊は憎しみの念を募らせていた景王と知り合いだということを聞かされて…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/253c90e6-1d40-44dc-9f98-0b2e4e8d22e1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('306f2be1-60d9-48ff-ac9a-8c408ecf38c2', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 32, '60740253', '「風の万里 黎明の空」 九章', '清秀の死を真実として受け入れることの出来ない鈴は、清秀をひき殺した郷長昇紘の情報を得た。鈴は昇紘に対する恨みから仇討ちを決意する。一方、陽子もまた蘭玉から止水の郷長である昇紘のことを聞いていた。そして雁国と慶国との国境の街へとやってきた祥瓊は、ここまで連れてきてくれた楽俊と別れた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4785f8f8-4c1b-4038-be6d-886645a1787b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('676d3dbf-5751-4b6d-a714-2fd8b3806c28', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 33, '60740282', '「風の万里 黎明の空」 十章', '清秀の命を奪った郷長昇紘の悪事を許し、かばっているのが景王であるという噂を聞いた鈴は慶国の王宮を訪ねる。その頃、陽子は和州の状況を調べるために、景麒を連れて州都である明郭へと旅立つ。一方、和州の止水を目指していた祥瓊は首都堯天に次いで栄えている街だと聞いていた州都明郭へと寄ったのだが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/dd7a6265-b976-4c22-bd34-e25971ddc11f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46ab5638-0dcb-4c6b-a35b-25dd4f8a383c', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 34, '60740274', '「風の万里 黎明の空」 十一章', '明郭の街で兵士に追われる祥瓊は、桓魋に助けられた。屋敷に案内された祥瓊は彼から和州に住む「二匹のケダモノ」と呼ぶ人物のことを聞かされる。虎嘯たちの仲間となった鈴は、昇紘を庇っている和州の州侯、呀峰もまた敵であると聞く。慶の国に過酷な刑罰があることを知らされた陽子は虎嘯と夕暉のいる宿を訪ねるが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/65304f2d-20bc-4a5e-b852-0a686dadaf91.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('acaf4639-04f6-47b9-b0d0-c93f6a5d39f4', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 35, '60740295', '「風の万里 黎明の空」 十二章', '陽子は里家を襲った人物の手掛かりを掴むため、まず遠甫を訪ねてきた怪しい男の仲介役であった労の家を訪ねる。一方、桓魋たちの仲間となった祥瓊は、和州に乱を起こすための軍資金を得るため、冬器の荷をある場所まで運んで欲しいと頼まれる。また、鈴も虎嘯から冬器を購入してきて欲しいと、その運び役を頼まれていた。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/dcc90057-9d6b-41db-9721-56322a74c758.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('276c96ae-cd10-4666-992f-b40863a40f7e', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 36, '60740261', '「風の万里 黎明の空」 十三章', '陽子は郷長昇紘の酷吏を許さんとする名目で集まった虎嘯たちに加わり、これを機にその乱が始まった。夕暉は、まず兵士たちの分散させるために少数の人数で本体となる屋敷ではなく別宅となる屋敷と凶作のための蓄えが納められている蔵を襲撃する。拓峰の街で起こった乱の知らせが祥瓊のいる明郭の街にも届いていた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d059b727-c78e-4084-8c94-a13140fb8fd8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9223a43-f433-4b2a-b044-18ab259f3b45', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 37, '60740281', '「風の万里 黎明の空」 十四章', '昇紘の住む郷城を警備していた兵士たちを巧みな作戦によって分散させ、郷城への突入に成功した陽子たちは昇紘を捜すため二手に分かれる。そして陽子は驃騎と班渠から昇紘の居場所を聞き、昇紘を見つけ出した。陽子の赤い髪に見覚えがあった昇紘は陽子の正体に気づく。そんな中、鈴は陽子が捕えさせていた浅野と出会い…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7f8408da-0282-42fc-87c1-88b64f4ba807.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0da3633-1c91-446f-a7a9-0bef7eb770a0', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 38, '60740288', '「風の万里 黎明の空」 十五章', '州師にも勝る勢力となった陽子たちだが、それでも街の人は静まり返ったままであった。そんな街の人の気持ちが、梨耀に仕えていた時に抱いていた自分の気持ちと似ているのだと鈴には良く分かった。祥瓊もまた同じ気持ちで、次の呀峰や昇紘のような人物を生み出さないで欲しいという願いが景王に届けばいいと陽子に話す…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3fb59510-3d19-4f26-8f17-d7a8e55e62c1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31df9f2f-c38c-462e-a06f-d575d2f4e479', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 39, '60740285', '「風の万里 黎明の空」 終章', '王直属の軍隊である禁軍が陽子たちの敵として現れる。だがそれによって陽子は王である陽子の了解を得ず勝手に禁軍を動かした人物がいることを知り、呀峰と昇紘の後ろ盾として裏で取りまとめていた元冢宰、靖共の存在に気づく。これ以上勝手はさせないと決意する陽子のもとに、金色の鬣を持つ一頭の獣が舞い降りてきた…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d44ed780-7ade-498e-9328-2dcd3ae2e38d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78479e89-481b-41ce-8c35-9836c05f80a1', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 40, '60740267', '「乗月」', '前王が絶たれて四年。新たな王が立つまでの間を州侯の一人が仮の王として国を統べている芳国に慶からの使者が到着していた。突如慶国の使者がやってきたことに驚きを隠せない恵州侯月渓。この月渓こそが空座となった芳国の玉座を仮王として立ったのだと聞き、桓魋が景王陽子からの書状を持って訪ねてきたのだった…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/96372759-3bb1-43fb-ae62-717eb0dd68b8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24a31619-afcd-4127-b7ae-4db4e6b4f643', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 41, '60740260', '「東の海神 西の滄海」 一章', '陽子たちが延王を訪ねてやってきた場所は元斡由という人物のお墓だった。延王は戸惑う陽子に自身が登極して二十年たった頃の話を語り始めた。 かつて雁国はすさまじい荒廃が見られたが、六太が尚隆を王として選んだことにより大地には緑が増えてきていた。六太はふと昔に出会った「更夜」という子供のことを思い出し…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4fbe89d4-03fc-4d72-87c2-4f3bad190208.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63331c71-b95e-4c5c-b2ba-3246c2654fad', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 42, '60740248', '「東の海神 西の滄海」 二章', '斡由の目的に納得し、自ら元州に捕えられることを承諾した六太。だが、斡由は最終的に王の上にさらなる権力を持った上帝位という官位を設けることで、王の代行者を立てるべきだと考えていたのだ。このままでは尚隆と斡由の二人が戦うことは避けられないと六太は感じ、更夜に斡由を止めて欲しいと頼むが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c8436f4c-4b8d-466e-b91d-c23e49952e76.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('912d7021-4c8f-4bd3-aba7-ea504bd34a03', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 43, '60740278', '「東の海神 西の滄海」 三章', '成笙率いる王師軍は、漉水を挟んだ頑朴の対岸側に陣を設け、民からの志願兵を募りながら不気味なほど静観していた。その兵数は既に二万余りとなり、さらに王都関弓に残留した兵数は三万にも達しようとしていたのだ。その様子を頑朴山の中腹から監視していた州兵の中に、名を偽って潜入した尚隆の姿があった…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/77de32f3-9be6-43d0-9c32-3104944b70be.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9885ef37-afb0-497d-aa4f-1b853f4ed438', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 44, '60740273', '「東の海神 西の滄海」 終章', '斡由の命によって送り込まれた州師の部隊は、突如築き上げた堤を切り始めた。一瞬にして穏やかだった雰囲気は壊され、民と州師の間で戦闘が行われてしまう。部下からその報告を受けた成笙は、民を救うべく先陣を切って州師の所へと向かうのだった。そして、六太は関弓に戻ることを告げるため斡由の元を訪れるが…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9026a344-4c32-4e3f-ad1c-3dc1fa5ce92e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75ecca6c-7557-461f-9e12-4e112de6d721', 'df17e28e-8f2d-4cd9-a31c-8db97288f076', 45, '60740294', '「東の海神 西の滄海」 転章', '【シーズン1 最終話】蓬莱で育った陽子は、十二国の世界に存在する「天」というものを信じきることができずにいた。それ故に自分もいつかは、やはり「天」を疑っていた昇紘と同じようなことをしかねないと不安を抱いていた。そんな陽子に延王は「もう一人の俺」と呼んだ斡由の話をしてくれた。その事の意味を、陽子はもう一度振り返り…。', '2017/05/26 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/43e3c313-3cdf-4cd7-8e24-7b9f05c9501c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6685a183-c230-431b-abf3-0ef5d43f134c', '獣の奏者エリン', '', 'hulu', 'erin-the-beast-player', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/843de198-3437-411c-ac43-483421390d0a.jpg?w=331&h=447&p=t', 'hulu', 2009, 0, 1, 'FINISHED', NULL, 5420, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e56e9935-329c-4767-9075-1a81fcd5972c', '6685a183-c230-431b-abf3-0ef5d43f134c', 'hulu-erin-the-beast-player-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9503183-f37a-4cb2-9032-141c2bb7ead0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e286d76-7f91-4c38-95d5-518385a18f8a', 'e56e9935-329c-4767-9075-1a81fcd5972c', 1, '100033649', '緑の目のエリン', 'エリンは獣ノ医術師をしている母･ソヨンと暮らす10歳の少女。その目は医術や薬学に秀でた霧の民の特徴である緑色だった。二人が暮らすアケ村は戦の道具として使われる闘蛇 (とうだ) を育てる特別な村。闘蛇はおそろしい生きものなのに、エリンは怖がるどころか、興味を持つばかり。それはソヨンのような獣ノ医術師になりたいという夢があるからだった。ある日、飼っていた闘蛇の赤ちゃんが逃げ出してしまい村中が大騒動になってしまう…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9503183-f37a-4cb2-9032-141c2bb7ead0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf57416d-87a8-4ffc-8831-508f5c25c50e', 'e56e9935-329c-4767-9075-1a81fcd5972c', 2, '100033650', '医術師のソヨン', '戦の道具である闘蛇を育てるアケ村は特別な村。そのため行商人や役人以外の旅人が訪れることは滅多になかった。ある日、エリンがヤギの世話をしていると、病気になった闘蛇をつれた武人がやって来た。戦場から戻った途端餌を食べなくなってしまったと言う。その治療を任されたソヨンは、原因を調べ始めるが、なかなかつかめない。エリンもソヨンを手伝おうとするが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d9864b9-870c-49f0-83fc-20cc38e335eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66ac6a32-92d7-46a5-b899-85accae961ea', 'e56e9935-329c-4767-9075-1a81fcd5972c', 3, '100033651', '闘 (たたか) う獣', 'アケ村で飼われている闘蛇の中でも勇猛で特別な闘蛇はキバとよばれていた。そのキバをつかった軍事教練がおこなわれることとなった。戦う闘蛇の姿をみたことのないエリンと、幼なじみのサジュとチョクの三人は大人たちに内緒で訓練を覗き見ようとする。教練場には大公とその息子であるシュナンとヌガン、王族のダミヤが視察に訪れていた。そして激しい教練がはじまる。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40fd1d91-aae7-4dc5-899c-17ab0959f54b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e1c6e0b-dc7c-4ded-96f3-2d10a2e1085b', 'e56e9935-329c-4767-9075-1a81fcd5972c', 4, '100033652', '霧の中の秘密', 'アケ村から他の闘蛇衆の村に花嫁に出て行くサジュの姉･ソジュ。きれいな花嫁衣装にエリンもうっとり。だがそのソジュはチチモドキの毒にあたり、高熱を出してしまう。闘蛇衆同士の結婚は村にとっても成功させなければいけない一大事。チチモドキの解毒のためにソヨンは霧の民がおこなってきた霧の市を使うことを提案する。ソジュを助けたい一心から、エリンはソヨンとともに霧の市に向かうことになるが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b8c171f-9b04-46c3-b02b-f128456de449.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ec1bf8b-ec5a-4a18-a148-8994ca86fe2d', 'e56e9935-329c-4767-9075-1a81fcd5972c', 5, '100033653', 'エリンと卵泥棒', '年に一度行われる闘蛇の卵狩り。アケ村の闘蛇衆は、ラゴウの沼から野生の闘蛇の卵をとってきて育てることになっていた。エリンは卵狩りにはじめて参加することを許される。静かなラゴウの沼で闘蛇の卵をさがす闘蛇衆たちは、野生の闘蛇の気配にどこか緊張している様子だった。そんな闘蛇衆たちの様子をものかげから伺う怪しげな二人組がいた。なんと彼らは闘蛇の卵を狙う卵泥棒だった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60ae9528-f302-4ed3-a789-57cfbfbbb17b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71ef5853-db13-419e-91e7-5dd7bda1ab40', 'e56e9935-329c-4767-9075-1a81fcd5972c', 6, '100033654', 'ソヨンのぬくもり', 'ある夜、アケ村に闘蛇の弔い笛が響く。かけつけたエリンたちが目にしたのは、死んだ“キバ”の姿だった。“キバ”は大公から預かった最も大切な闘蛇。そしてその死は、村が取り潰しにあってもおかしくないほどの大罪。死因すら特定できない状況のなか、集会では死なせてしまった罰は世話をしたものが受けなければならないということに。それはエリンの母ソヨンだった…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/961c6d37-3600-4286-92ec-c07e920c9412.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5742b270-e80a-4860-82af-743050a97743', 'e56e9935-329c-4767-9075-1a81fcd5972c', 7, '100033655', '母の指笛', 'キバを死なせた罪で監察官に連れて行かれてしまったソヨン。エリンはサジュの家に預けられ、ソヨンが帰ってくるのを待っていた。しかしある夜、エリンはソヨンがラゴウの沼で闘蛇の裁きにかけられることを耳にする。心配になったエリンは、闇の中ラゴウの沼へと走り出す。そして早朝、静かなラゴウの沼では闘蛇の影がうごめきはじめる。エリンはなんとかしてソヨンを助けようとするが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7da09f98-c02f-4242-86f4-cbc489161eda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('14cc5da7-4465-412b-ac86-3f7aeb939c26', 'e56e9935-329c-4767-9075-1a81fcd5972c', 8, '100033656', '蜂飼 (はちか) いのジョウン', 'ソヨンの手で闘蛇の背に乗せられたエリンは、アケ村からはるか遠いところにある真王領の川岸に流れ着く。そこで蜂飼いのジョウンという男に助けられるが、傷と疲れのために高熱をだし、意識がないままであった。ジョウンはエリンを自分の小屋へと連れ帰り看病を続ける。意識の戻ったエリンは、窓から見える木に吊り下げられたサナギを見て、亡きソヨンとの暮らしを思い出し悲しみに暮れるのだった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0cd9c543-39e0-4355-9fc0-8f4b3a99d1e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('969cbe34-4dd8-4de4-8c20-4b2d260e1920', 'e56e9935-329c-4767-9075-1a81fcd5972c', 9, '100033657', 'ハチミツとエリン', '蜂飼いのジョウンと一緒に暮らすことになったエリン。ジョウンの家には見たこともない道具がたくさんあった。不思議そうにそれを見るエリンに、自分の宝物を見せてやると外に連れ出すジョウン。エリンは興味しんしんでジョウンの後についていく。途中、ジョウンの宝物の一つ、めす馬のトッチとヤギのノロと会う。そしてエリンはいろいろな花々が咲きみだれる場所で不思議な光景をみるのであった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8ee7948-8048-49b3-85b7-293058227609.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bce36f65-c36d-47f8-98b0-c374ef37bda2', 'e56e9935-329c-4767-9075-1a81fcd5972c', 10, '100033658', '夜明けの鳥', '山の暮らしに必要なものを買い揃えるため、街へ出かけたエリンとジョウン。エリンは生まれて初めて見る大きな街の賑わいに驚く。楽師達の演奏を楽しんでいた時、エリンは道の端で美しい音色で竪琴を弾く青年に気付く。青年が弾く曲が気になるエリン。しかし、青年は曲名を告げるとエリンの前から姿を消してしまった。エリンとジョウンが食品の店を訪ねると、女店主が病に倒れていた。そこに役人に追われた女店主の息子がやってきて…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd7c61df-67e6-4c0e-b238-f380a8ae0cdb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('474ebc40-c93c-4fd7-ad65-95fdaaf11feb', 'e56e9935-329c-4767-9075-1a81fcd5972c', 11, '100033659', 'とびらの中に', '夏の間、カショ山にあるジョウンの「夏の小屋」に移動することになったエリンとジョウン。家を空ける前に、片付けをすることにした。奥の部屋を掃除しようとするエリンに、ジョウンは絶対に入ってはいけないと言う。ジョウンが蜂飼いの師匠･ドランの家に出かけ、エリンはひとり留守番をすることになる。ジョウンから奥の部屋に入ることを禁じられたエリンだが、何があるのか知りたくてたまらず扉を開けてしまう…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9347d00e-feb3-4273-8630-831d6ac25a4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71805010-75d6-420a-bcba-e8e60967c24d', 'e56e9935-329c-4767-9075-1a81fcd5972c', 12, '100033660', '白銀の羽', 'カショ山の「夏の小屋」に着いたエリンとジョウン。久しぶりの「夏の小屋」は傷んでホコリだらけ。ついてきたヌックとモックも加わり大掃除が始まった。エリンが煙突にもぐりこんだ時、何かの影が頭上の光を一瞬さえぎる。気になったエリンは、その影の主を探しに森へ行き、そこで巨大な羽を拾う。ジョウンからその羽は獣の王者である「王獣」の羽だと聞く。エリンは闘蛇より大きく、そして気高い獣が存在することを初めて知るのだった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a45054a-9dc8-4fd0-aefc-cbda162f297f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e13118e-ad01-4c91-9a42-9f11892e303e', 'e56e9935-329c-4767-9075-1a81fcd5972c', 13, '100033661', '王獣の谷', '薬草として高く売れるチゴの根を採りに行くことにしたジョウン。しかし、チゴは闘蛇が多くいる危険な峡谷で育つことを知ったエリンは、母を失ったラゴウの沼でのことがよみがえり不安になり、ジョウンの後を追いかける。心配どおり、ジョウンは崖の途中の岩棚に落ちてケガをしていた。動けないジョウンを一人にしておけないエリンは、一緒に崖で一晩過ごすことにした。そこでエリンは、闘獣が王獣のヒナを襲おうとしているところを見てしまう。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa7960d3-7e50-466b-876a-be4b30638e42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3223969d-abf7-425d-ad2b-57ff169ca54c', 'e56e9935-329c-4767-9075-1a81fcd5972c', 14, '100033662', '霧の民', 'アケ村より真王領に流れ着いたエリンの後を影のように追い、見守ってきた「霧の民」の探索者ナソンは、エリンの様子を伝える為に霧の民の村へと戻る。ナソンは、ソヨンとエリンは幸せな日々を送ってきたこと、エリンはソヨンによく似て、聡明で好奇心が強い娘であること、闘蛇のキバが死んだことでソヨンが裁きにかけられたこと、そして母の手で闘蛇に乗せられ幼いエリンだけは王都へ逃れ着いたことなどを長老たちに語るのだった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48340936-2b92-4eae-8f0e-ab6188b689db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba7eac41-e3e1-4ed1-82dc-f7996588fd63', 'e56e9935-329c-4767-9075-1a81fcd5972c', 15, '100033663', 'ふたりの過去', 'ジョウンの元にきてから四年もの月日が流れ、十四歳となったエリンは、自分で蜂を増やして蜜を売り、お金を稼げるまでに成長していた。ある日、ジョウンを訪ねて見知らぬ男がやってくる。その顔を見て驚くジョウン。男がジョウンにかけた言葉は、エリンにとって思いもよらないものだった。そんなエリンに、ジョウンはひた隠しにしていた自分の過去を語り出し、またエリンもジョウンに自らの生い立ちを包み隠さず話しはじめる。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/233e8145-a95f-40a5-8a69-f701fee885ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1c24928-754d-43c1-9893-be10984f1c89', 'e56e9935-329c-4767-9075-1a81fcd5972c', 16, '100033664', '堅き楯 (セ･ザン) のイアル', '王獣保護場から《入舎ノ試し》についての返事が届く。合格の条件は厳しいものだったが、特別に試しを受ける許可が下りたエリンは、ジョウンと共にカザルムへと向う。その旅の途中、エリンの竪琴が壊れてしまう。修理のために楽器職人の家を訪れたエリン。その竪琴を見て驚いた職人のヤントクは、エリンに竪琴をどこで手に入れたのかを尋ねるのだった。同じ頃、ヤントクの工房には若き有能な武人･堅き楯〈セ･ザン〉のイアルの姿があった…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b7213eb-0edb-4b95-84cb-8e620a4cccc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e4e22eb-9d0f-4357-9388-1b7c1a8e51b8', 'e56e9935-329c-4767-9075-1a81fcd5972c', 17, '100033665', '狙われた真王', 'ジョウンの学友である教導師エサルの計らいにより、カザルム学舎で《入舎ノ試し》を受けることになったエリン。カザルムに向かう途中に立ち寄った街で、真王の60回目の誕生日への贈り物を運ぶ大きな荷車の列を見る。王宮の大広間では、真王陛下を祝おうと、大公や貴族たちが真王陛下のもとに集まっていた。式典が始まり、ダミヤが真王に献上したものは、荷車に積まれていた幼い王獣だった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df7a35aa-b99f-41ff-ba37-6107f5664384.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b84e7873-e6e9-4784-bca6-c128f6159697', 'e56e9935-329c-4767-9075-1a81fcd5972c', 18, '100033666', '教導師エサル', 'カザルム王獣保護場についたエリンとジョウンをエサルが出迎えてくれた。エサルによって学舎を案内される二人。エリンにとってはどれもこれも興味深いものばかりだったが、その中でも教導師長室の書架に並ぶたくさんの本に釘付けになる。そしてエリンの《入舎ノ試し》がはじまった。エサルはエリンの学力が秀でていることは元より、特に獣ノ医術師になりたい理由を書いた作文のすばらしさに驚き、エリンの才能に気付くのであった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40b4d277-3b11-48d2-923b-1cba5b48134b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ecbede9-d041-46e4-95e1-4fee5eaecb2a', 'e56e9935-329c-4767-9075-1a81fcd5972c', 19, '100033667', 'カザルムの仲間', '《入舎ノ試し》に合格し、カザルム学舎の中等二段に編入したエリン。ジョウンと二人きりの生活から、同じ年頃の子ども達との初めての共同生活が始まる。しかし、エリンは王獣のことを学べることが嬉しく、授業では先生を質問ぜめにしたり、自分が知りたいことに一生懸命で学舎の規律を守ることが出来ない。カザルム学舎にはエリン以外にもう一人の女子学生、ユーヤンがいた。ユーヤンはそんなエリンを気遣い声をかけてくれるのだった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3d3b80a-14b6-4a50-9767-23352c71d51c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25413831-2143-4e20-bd8a-d64fbf63f4c5', 'e56e9935-329c-4767-9075-1a81fcd5972c', 20, '100033668', 'リランという名の王獣', '獣ノ医術師を目指す仲間たちと共にエリンの新たな生活が始まった。王獣のことを学べることが嬉しくて、獣舎の掃除やフン集めの授業でさえ楽しみにしているエリンだった。しかし、野生の王獣の美しさを知っているエリンにとっては人に飼われているカザルムの王獣が哀れに見えて仕方がない。ある日、野生の王獣とカザルムの王獣の違いを話すエリンを教導師長のエサルはあるところへ連れて行く。そこには傷付いた幼獣のリランがいた。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4eec1f7a-7b6c-43bd-8897-d62e9a051483.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ba924c2-532c-4ab4-9879-994508b3c1e8', 'e56e9935-329c-4767-9075-1a81fcd5972c', 21, '100033669', '消えそうな光', 'トムラに代わって、ひと月だけ幼獣･リランの世話をする許可をもらったエリン。幼いうちに母親から引き離されたリランと自分を重ねずにはいられず、必死に世話を続けるがリランは水以外一切口にしようとしない。このままエサを食べなければリランはいずれ死んでしまう。悩む日々が続く中、以前に見た野性の王獣の子どもが、母親の身体の下にいた姿を思い出し、あることに気が付いたエリンは、王獣舎の壁板をはがすのだった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c25b4637-1c70-40c9-910b-cabb690396f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e67ad857-6ef3-4a1f-bf97-8ee677ed63d8', 'e56e9935-329c-4767-9075-1a81fcd5972c', 22, '100033670', '竪琴の響き', '毛布の中で響いた竪琴の音が、王獣の母親の鳴き声に似ている事に気付いたエリンは、その音を正確に出すことができれば、リランは自分に応えてエサを食べるようになってくれるのではないかと思い、大切にしてきた竪琴に細工をすることにする。そして、かつて竪琴を直してくれたヤントクの店を訪ねる為にトムラと王都に向かう。その頃、式典で真王を狙った暗殺者の仮面の出所について調べていたイアルに何者かが襲いかかろうとしていた…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ecc68535-97eb-437d-994d-73b4b2c890ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d30bac5a-73e0-415d-aab7-4e75f35f49a3', 'e56e9935-329c-4767-9075-1a81fcd5972c', 23, '100033671', 'カザルムの誓い', '餌を食べるようになり、元気に水浴びするリランの姿にほっとするエリン。しかし、学童たちの間では、エリンが霧の民の不思議な力を使ってリランを操ったのではないかという噂が広まっていた。エサルは教導師達を集め、エリンが竪琴を使って母親の鳴き声に似た音を奏でてリランに餌を食べさせたことを話すが、王獣と意を通じようとしていることは王獣規範 (おうじゅうきはん) に書かれた規則に背くことでもあった。悩むエサルが下した決断とは…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6275d198-ad67-4fb0-b12c-cf29bbe1d522.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffb1eb6b-0b15-4834-8afc-91ac747ef15b', 'e56e9935-329c-4767-9075-1a81fcd5972c', 24, '100033672', '嘆きの歌', '幾度となく繰り返される隣国･ラーザとの戦い。終わりの見えない戦いに、国の行く末を案ずる大公の息子･兄のシュナンは、傷つき前線から戻ってきた兵士の姿をやりきれない思いで見つめる。一方、弟のヌガンは戦場で戦いたいと思っているが大公に許されないでいた。考え方の違う二人が、むかし兄弟で植えた木の前でそれぞれの思いを胸に言葉をかわす。「二人でこの国を守ろう」そう誓いあった幼い日に思いをはせるのであったが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11007faa-d60e-4a68-abcc-6849fe4780b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a1d6eaa-c1bd-4712-94ff-2e29e78b3b4c', 'e56e9935-329c-4767-9075-1a81fcd5972c', 25, '100033673', 'ふたりのおつかい', 'ラゴウの沼で命を救われて以来、エリンを追ってカザルムまでついて来たヌックとモック。カザルム王獣保護場で雑用係として働くものの、毎日失敗続きで寮母のカリサに怒られてばかり。ある日、カリサに頼まれて街におつかいに出かけた二人は、このおつかいを見事に成功させてカリサを見返してやろうと決意するが、早速預かったお金を失くしてしまう。途方に暮れた二人は、何とかしてお金を稼ごうとするのだが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/679f2749-ce1e-4633-a27f-bba6aa565070.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5a1a956-8ae3-4f02-b822-ca43fec887ca', 'e56e9935-329c-4767-9075-1a81fcd5972c', 26, '100033674', 'リランの心', 'カザルム学舎では夏の試験が行われようとしていたが、リランの世話に夢中になっていたためエリンの勉強は確実に遅れていた。試験に落第したらカザルムを去らなければならないエリンは、トムラや同級生たちに助けられ、無事に高等一段に進級する。夏休みに入り同級生たちがそれぞれ帰省してしまい、カザルムでひとり過ごすエリン。ある日、リランが竪琴を使っていないのに自分の言葉を理解していることに気付くのであった…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d4f8cc8-63c7-4fdb-8a0f-5e2450d868ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('394d3df3-8ffa-4e4f-8795-8ce76b9b6cc3', 'e56e9935-329c-4767-9075-1a81fcd5972c', 27, '100033675', 'ヒカラにおちて', '毎晩、ソヨンの夢ばかりを見るエリン。寝坊してリランの餌やりに遅れてしまう。いつもと違って顔色も悪く、どこかぼんやりしたエリンを心配するエサルたち。ある夜、霧の中を飛びかう不思議な光を見かけたエリン。翌朝、その場所に行ってみると、そこにはたくさんの王獣の石像が並んでいた。それは王獣たちの墓だった。カリサによれば、霧のたちこめる夜には不思議な光が飛びかい、迷いこんだ人間の魂をヒカラに連れて行くと言うが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a90fe7f7-c84e-4f59-9c69-d70f100d9e3d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('599dae67-eff0-4cc2-b89e-8e2051a92048', 'e56e9935-329c-4767-9075-1a81fcd5972c', 28, '100033676', 'ジョウンの死', 'ある夏の日、エリンの元にジョウンの息子アサンからの手紙が届いた。その手紙の内容は、王都に戻り静かに暮らしていたジョウンの死を知らせるものだった。エリンはジョウンの遺した書物を前に、必死で涙をこらえる。心配するエサルを前に、大丈夫だと笑みを見せ、気丈にリランの世話をこなすエリン。そんな様子を見ていたエサルは、エリンをつれて小旅行に出かける。そこはジョウンとエサルの思い出の地であった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d17a75f1-505c-479a-aa2d-1992f7de4ba2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eebd7cc0-23a3-48da-ae6a-cf8d8222569c', 'e56e9935-329c-4767-9075-1a81fcd5972c', 29, '100033677', '獣の牙', '夏休みも終わり、学童たちが戻ったカザルムはいつもの賑やかさを取り戻す。ジョウンの死を知ったユーヤンはエリンを気遣うが、エリンは明るく振る舞おうとする。リランは産毛の生え変わりの時期を迎え、その毛並みを整えてやろうとしたエリンはヌックとモックに頼みこみ、大きな刷毛を作ってもらう。出来上がった刷毛で毛を整えてもらうリラン。気持ちよさそうにのどを鳴らして喜ぶが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/726365e1-1a4b-4353-9ec8-0f5e997dc967.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17e20a3d-4cd1-4e99-a9e6-9d4f70bed03b', 'e56e9935-329c-4767-9075-1a81fcd5972c', 30, '100033678', '四年目の冬', '十八歳になったエリンは、カザルム学舎の最上級生になっていた。教導師長室で、カリサと話していたエサルは、エリンがジョウンに連れられて《入舎ノ試し》を受けに来た日のことを思い出していた。「この世に生きるものが、なぜ、このように在るのかを知りたい」と書かれたエリンの作文に感心し、カザルムへの入舎を許可してから四年。その月日の間にエリンの身に起こったさまざまな出来事をエサルは思い返すのだった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09bb8d40-bd7a-42ca-8ba1-b4bf19cc30be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3177d27e-bdd9-47ad-a38b-9cd6574a4360', 'e56e9935-329c-4767-9075-1a81fcd5972c', 31, '100033679', '光の空', 'ラザル王獣保護場の研修から戻ったトムラは「カザルムでは王獣規範に従わずに王獣を育てている」という噂が流れていることをエサルに報告する。ときを同じくして、タムユアンから新しい教導師･キリクがやってきた。美しい容姿を持ち、惜しげもなく菓子をくれるキリクに学童たちは夢中になる。そんなキリクはやたらとエリンの事を詮索して回るのだった。ある日、リランを連れて外に出たエリンはそこで思わぬ事態に直面する。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9f45f52-0b5d-4721-979a-5938bf2f0354.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac8d4a34-8c86-4ec4-aa13-a5da856177c5', 'e56e9935-329c-4767-9075-1a81fcd5972c', 32, '100033680', '大罪', 'エリンを背に乗せ大空を舞うリラン。上空の寒さに震えるエリンの耳に、かすかな指笛の音が響く。眼下にたたずむ灰色の人影。地面に降り立ったエリンを迎えたのは、霧の民のナソンだった。竪琴で王獣と言葉を交わすことは大罪であると言うナソン。母･ソヨンも口にした「大罪」とは何を意味するのか。ナソンは、太古の昔、アフォン･ノアの彼方に栄えた王国･オファロンに起きた出来事を話し始める。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/013fd38c-992d-4923-b493-39c762c40e95.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea2a3fa0-7adf-4b8d-be0d-fc2b2278777a', 'e56e9935-329c-4767-9075-1a81fcd5972c', 33, '100033681', '飛翔', 'エリンは、リランが自分を乗せて空を飛んだことをエサルに報告する。その報告に喜ぶエサル。しかし、自由に飛べるようになったリランがカザルムから飛んで逃げてしまっては大問題になりかねない。そこで、リランが空を飛んだということが外に漏れないよう、学童たちがいない冬休みの間に、リランがエリンの命令で空を飛ぶようにする訓練を行うことになった。しかし、全く飛ぼうとしないリランにエリンは困り果ててしまう…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffbbb766-5c0a-47b5-9284-a63282377b3c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c32ff2a9-9c25-47a8-939f-37a7258f861e', 'e56e9935-329c-4767-9075-1a81fcd5972c', 34, '100033682', 'イアルとエリン', '爪にケガを負った王獣がラザルからカザルムに運びこまれてきた。動けないほどに弱った王獣の息から漂う甘い香りに、エリンはアケ村でソジュが倒れた時のことを思い出す。原因がチチモドキの毒にあると気付いたエリンは、解毒薬を求めて王都の薬問屋に向かう。その頃、菓子の中に仕込まれたチチモドキの毒に倒れたセィミヤの侍女･ナミの命を救うため、同じく王都の薬問屋に向かうイアルの姿があった。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47ea42ce-4c1e-4b7a-980e-5df0784bc795.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87ca0f43-8d67-4b2f-b9af-aa348bad9dd4', 'e56e9935-329c-4767-9075-1a81fcd5972c', 35, '100033683', 'あたらしい命', 'カザルムに、羽をケガした野生のオスの王獣が運ばれてきた。この王獣は「雄」という意味である「エク」と名づけられた。エクは傷の治療の為に音無笛で硬直させても、硬直がとけるたびに暴れ傷が開いてしまう。そこで、エリンがエクの世話係りを任される。エリンは泊まりこみで世話にあたり、エクは次第に回復する。ある日、リランの世話をしていたエリンは、体毛にある変化が現れていることに気付く。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13361f11-1d0a-40d4-a6f1-553e0ea7c071.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64c34ab2-d32e-4b3d-b6d0-50a93b106f59', 'e56e9935-329c-4767-9075-1a81fcd5972c', 36, '100033684', '卒舎ノ試し', 'リランの妊娠に喜ぶカザルムの学童たち。しかし、王獣の出産は例がなくエサルにも経験が無い。卒舎ノ試しが近づいていても、ソヨンに教わったことを思い出しながら、一生懸命リランの世話にあたるエリン。リランのことで頭が一杯のエリンに、トムラは卒舎ノ試しで一等がとれなければカザルムに残れないことを告げる。エリンは、リランと一緒にいるためにも必ず一等を取ることを心に誓う。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cad52098-e02e-4155-8134-af112e2fa064.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe317963-f72a-41bf-82d0-edda9332bbfe', 'e56e9935-329c-4767-9075-1a81fcd5972c', 37, '100033685', '誕生', '新しい学童たちがカザルムに入舎した。教導師になったばかりのエリンは、今年の新入生で唯一の女子･シロンが、他の学童たちと遊ばず一人で本を読んでいることが気になり、声をかける。誰にも負けないよう本を読んで勉強し、絶対に教導師になると答えるシロン。エリンは、本を読むのも大事だが、自分で見聞きし感じることも大切だと教えるが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6cb2323-c7e7-4c99-b66c-178db4f88cfd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19450131-8f1c-486f-8ee6-3f44ebf4a580', 'e56e9935-329c-4767-9075-1a81fcd5972c', 38, '100033686', '真王ハルミヤ', 'リランの子･アルと会うため、初めて王宮から外出する真王。エサルは、エリンがリランたちと竪琴で心を通わせていることを知られてはならないと考え、エリンに人前に出る事を禁じる。カザルムに着いた真王は、リラン親子の美しさに見とれ、一歩また一歩と近づいていく。子育てでいつもより気が立っているリランに近づいては危ないと、エリンは思わず真王の前に飛び出してしまう…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfbf3720-d148-42a1-be79-94f12b033040.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b17e8894-e9e1-4767-a299-1e3b6200db88', 'e56e9935-329c-4767-9075-1a81fcd5972c', 39, '100033687', '闘蛇の襲撃', '王獣の視察を終えた真王は、カザルム河を下る巨大な御座船で王都への帰路につく。展望の丘から、感嘆しながら美しい御座船を見つめる学童たち。しかし、遠眼鏡をのぞいていたシロンは、支流から流れてくる丸太のようなものに気づく。とっさにそれが闘蛇だと気づいたエリンは、真王や御座船に乗った人々の危険を察して走り出す。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2128f65d-2f1a-4225-822b-358838819dd1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e32d06cd-78fa-46e1-89ae-9828a89394fb', 'e56e9935-329c-4767-9075-1a81fcd5972c', 40, '100033688', 'かげりゆく国', '真王の御座船を襲った闘蛇の軍により傷ついた多くの人々を、エリンは必死に治療していく。そんな中、誰もがこの事件を闘蛇を操る大公の仕業だと思っていたが、エリンだけはそうではないことに気付く。そして、真王を守って傷ついたイアルを治療しながら、エリンは彼に自分の考えを伝える。一方、エリンとリランが起こした奇跡を目の当たりにしたダミヤは…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb33b3d9-34ef-421c-9838-261a17de5506.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d944d905-d9bd-4a8e-88f0-7a8ad387d552', 'e56e9935-329c-4767-9075-1a81fcd5972c', 41, '100033689', '真王の真実', 'カザルム河での襲撃事件から一命を取りとめた真王ハルミヤは、次第に回復に向かい、カザルム候の館での晩餐会にエリンを招待する。そこで、王宮に戻る真王の護衛をリランと共におこなうよう命じられるエリン。王宮にいってしまえば、リランは王獣本来の生き方を許されない…。それを避けようと、エリンは真王にすべての真実を話すことを決意する。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/813e6e09-27f8-43e3-9b34-d2716eb18de4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('909ee21f-72ea-46b0-afbf-60715b7157c7', 'e56e9935-329c-4767-9075-1a81fcd5972c', 42, '100033690', 'セィミヤの涙', '真王が亡くなったという知らせに、衝撃を受けるエリン。一方、王宮では、大切な肉親を失ったセィミヤが悲しみにくれていた…。次の真王となるセィミヤは、リョザ神王国の存続のため、世継ぎを生み、真王の座を継承していかなければならない。ダミヤはセィミヤをなぐさめながらも、一番愛している男は誰なのかと問いかけていく。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0765b796-9cd6-4d16-b8eb-e668c12237ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f3c1b8b-9e3e-4c29-9a0c-f15c7cddeb21', 'e56e9935-329c-4767-9075-1a81fcd5972c', 43, '100033691', '獣ノ医術師', 'カザルムの農園で、学童たちと山リンゴの接ぎ木の実習をしていたエリン。そこにトムラが息を切らせて駆けつけ、急を告げる。真王からの命を受け、ラザル王獣保護場のオウリがリラン一家を連れにきたというのだ。エリンは必死でリランの王獣舎へと走ったが、すでにリランは、ラザルの王獣使いたちに牙を向けていた…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f029b6d-7fa7-4727-a379-25b7c300f0c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12beccb2-3047-47a9-9a2d-9b216956a363', 'e56e9935-329c-4767-9075-1a81fcd5972c', 44, '100033692', 'アクン･メ･チャイ', 'ラザル王獣保護場へと連れてこられたエリンだが、馬車が向った先はダミヤの館だった。エリンの前に現れたダミヤは、彼女が恐怖に負けることなく王獣を制していることを褒める。しかし、リランとエリンは、今までのような関係ではなくなっていた…。顔を強張らせたエリンにダミヤは、大公の闘蛇部隊に対抗する王獣部隊を作るよう命じる。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8a676fb-a623-4aa2-9c9d-05fa3022d826.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f24a5c67-2377-4af9-aa9a-c20ebc8db3fa', 'e56e9935-329c-4767-9075-1a81fcd5972c', 45, '100033693', 'かごの鳥', '『建国の夜明け』の日、エリンは王祖ジェの伝説のように、大勢の人々の前で王獣に乗って空を舞う。そして、シュナンをはじめとする闘蛇軍をやすやすと撃退するだろう…。まるで確信したかのようなダミヤの言葉に衝撃を受け、うなだれるキリク。そんな彼にダミヤは、自らの陰謀に気づいた可能性のある人物を毒で消すよう命じた。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24930af7-0444-4297-895d-793311438acf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ecc95fa-200c-4cd2-811c-54a8cf7389c6', 'e56e9935-329c-4767-9075-1a81fcd5972c', 46, '100033694', 'ふたりの絆 (きずな)', 'ダミヤに毒を飲まされ、仮面の男たちに襲われたイアルは、その追撃をかわし、ラザル王獣保護場へと逃げ落ちる。そこにはリランたちの世話をするエリンの姿があった。傷ついたイアルを見つけ、その治療をするエリン。傷から来る熱と毒とにうなされながら、悲しい過去を夢見るイアル。そんな時、ダミヤの追っ手がラザルへと迫ろうとしていた…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c802967c-63d9-4ec6-bae6-1a258f92b76b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('052e81c5-53c6-4921-a46f-4150fd59cf3c', 'e56e9935-329c-4767-9075-1a81fcd5972c', 47, '100033695', '清らかな夜', 'タハイ･アゼでの決戦が迫る中、ダミヤとの結婚こそがリョザを清らかな国に導く手段だと信じ、みそぎの森へと赴く真王セィミヤ。しかし、シュナンの存在が頭から離れない。シュナンは自分を愛するからではなく、国のために結婚しようとしているのではないか。その疑念がセィミヤを迷わせる。そんなセィミヤの前に現れたのは…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/892aaa7c-5648-465b-9843-127f06c62119.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8822e331-fb57-4631-8eae-7a73b89fb586', 'e56e9935-329c-4767-9075-1a81fcd5972c', 48, '100033696', 'リョザの夜明け', '雪の舞うタハイ･アゼに、大公の誇る勇猛な闘蛇の軍が集っていた。一方、緊張高まる丘の上の天幕には、セィミヤとダミヤ、そして、エリンとリランの姿があった。今のエリンにはリランが戦の道具になることがないようにと願いながら、セィミヤがすることを見つめることしかできない…。そんな中、傷を負ったイアルが真王の天幕に近づこうとしていた。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/006f1ffc-0d99-449f-ad0e-128bc3d725f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad5dc6e4-e724-46e7-bff3-39cd3d2ae642', 'e56e9935-329c-4767-9075-1a81fcd5972c', 49, '100033697', '決戦', 'タハイ･アゼの夜が明ける時、はるか大地の向こうに陣取る大公軍を前にしてダミヤはセィミヤに向かって言った。あれがそなたの軍なのだと…。その言葉を聞いたセィミヤは心を固める。そして時は満ち、雲間から射した光が大地を照らすと、静かに闘蛇の群れが動き始める。わずかばかりの手勢を連れた真王を目指して。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e7b387c-af4e-42cd-8a5a-37d06a5f3d8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d25c732d-6a08-4e17-8285-d103c5b7fee3', 'e56e9935-329c-4767-9075-1a81fcd5972c', 50, '100033698', '獣の奏者', '【シーズン1 最終話】セィミヤの意思により青い旗が掲げられた瞬間、皆が真王と大公とが手を取り合う新たな時代の訪れを信じた。だがそれは突如走り出した闘蛇の群れによる混乱の中で潰されてしまう。シュナンを亡き者にしようと迫る闘蛇軍と守ろうとする闘蛇軍が互いにぶつかり合う惨劇の中、孤立したシュナンを助けようと、エリンはリランとともに飛び立つが…。', '2023/08/31 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aaec0a17-e0ef-444a-adb4-1092471e0069.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('236dc05b-3fb3-48f0-bf9e-0703bf217940', '獣王星', '', 'hulu', 'jyu-oh-sei', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9524a73-77c1-4808-9c69-ed43bff09a94.jpg?w=331&h=447&p=t', 'hulu', 2006, 1, 1, 'FINISHED', NULL, 953, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('062d3ab4-6575-45cd-94c0-c42f435c557e', '236dc05b-3fb3-48f0-bf9e-0703bf217940', 'hulu-jyu-oh-sei-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df720fd1-b15b-4016-aa7c-c36a4d81b6cf.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd8f7354-42b6-4be9-9b2d-3c6889176a56', '062d3ab4-6575-45cd-94c0-c42f435c557e', 1, '100150647', '運命', '西暦2436年。両親を殺され死刑星へと送られて来た双子「トール」と「ラーイ」。『獣王星』と呼ばれるこの星は獣にならないと生き残れないという過酷な環境の惑星だった。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df720fd1-b15b-4016-aa7c-c36a4d81b6cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a0faf8a-6347-415a-8d46-fcbba1c1a3ba', '062d3ab4-6575-45cd-94c0-c42f435c557e', 2, '100150648', '茶輪 (リング)', 'トールはティズとサードに助けられ茶輪の砦に来ていた。ティズから「夫になれ」と指名されるがそれを断り砦を去るトール。追いかけてくるティズだが突然地面が揺れ始め…。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da54a840-7fd6-4991-88d9-432f4ee88280.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f82bdace-2c81-4873-afa0-6a9295a55b59', '062d3ab4-6575-45cd-94c0-c42f435c557e', 3, '100150649', '仲間', 'トールとティズの前に、ティズのかつてのボス『チェン』が現れる。掟を破ったティズを連れ戻しにやって来たのだ。「帰らなければ殺す」と剣を突きつけてくるチェンだが…。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb4687fb-7956-4e2c-94bf-d3fee13f01d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e3f1b73-3451-45dd-872f-170c0f24b299', '062d3ab4-6575-45cd-94c0-c42f435c557e', 4, '100150650', '挑戦', 'トールと同じ『ユノ』から送られて来た囚人コリン。トールの名を聞くと動揺し、ぽつりぽつりと真実を語り始めた。家族を絶望に陥れた張本人の名を聞きトールは困惑する。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fc57491e-a641-408c-86a4-d9d289e8b8ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd9f2840-50d7-47b9-8724-cf15561053ac', '062d3ab4-6575-45cd-94c0-c42f435c557e', 5, '100150651', '決闘', 'サードの策略で茶輪のトップに挑戦する事になったトール。あまりの力の差に勝てる自信のないトールに「お前に一度だけチャンスをやろう」とサードは囁く。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53d560d1-bc7a-44c3-bbf3-e1ba1e806cb3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f64d023f-110c-4af8-ab19-059bdc3062fa', '062d3ab4-6575-45cd-94c0-c42f435c557e', 6, '100150652', '白狼鬼', 'トールが茶輪のトップになってから3年が過ぎた。獣王星では『ブラン･ロウ』率いる白輪が残虐な殺戮を繰り返していた。それを止める為にサパの村へと向かうトールたちだが…。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6e417e8-7e8b-405c-a663-9b350c316771.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3e5606b-cb6f-4bc5-9f0d-0b3f798d11c7', '062d3ab4-6575-45cd-94c0-c42f435c557e', 7, '100150653', '独立', '『ブラン･ロウ』の正体はザギだった。うろたえるトールに、ザギは獣王とはただの幻なのだと話し、「一緒に独立戦争を仕掛けないか」と持ちかけてきた。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb990cce-6836-4082-95e4-ac4273de9c0d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04d09df2-4274-4534-ba59-0ec9a330c65f', '062d3ab4-6575-45cd-94c0-c42f435c557e', 8, '100150654', '深層', 'カリムを追いかけムーサの狭間に落ちてしまったトール。「お前のせいでザギに捨てられた」と怒りをぶつけてくるカリムに対し、気持ちを打ち明け始めるトール。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d88d825-a651-4986-90e9-35b9a317c5df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0cc4c775-a59f-4420-904a-0f6be41fb6f7', '062d3ab4-6575-45cd-94c0-c42f435c557e', 9, '100150655', '獣王', 'カリムを茶輪に引き取る事を決めたトール。ティズは二人の関係に不安を抱きふさぎ込んでしまった。カリムはトールとザギの間で心が揺れ、気持ちを確かめるためにザギの部屋へと向かった。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebff62cc-93d4-4e78-ad5d-4e8f330560c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8f6c5ef-cc8e-4500-b955-d40e2070d05a', '062d3ab4-6575-45cd-94c0-c42f435c557e', 10, '100150656', '悪夢', '第三十八代獣王としてダガー･パゴダへ迎え入れられたトール。いいしれない不安のなか宇宙港で待っていたのは宿敵オーディンと自分によく似たシグルドという軍人だった。', '2023/08/02 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a210dc8-2241-468a-b194-f7db19e276f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9e69803-7b0e-40f8-978b-860a77b452b4', '062d3ab4-6575-45cd-94c0-c42f435c557e', 11, '100150657', '希望', '【最終話】ワルキューレの暴走を止める為、トールはヘカテへと向かう。獣王の冷凍施設でやりきれない思いを爆発させるトール。突然イヴァの声でバルカン連邦がひた隠しにしてきた真実が語られ始める。', '2023/08/02 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c544f836-0940-401a-affe-9dd87181dee7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0f600b43-dfe6-4dee-a40b-82e0fecfce71', '獣兵衛忍風帖「龍宝玉篇」', '', 'hulu', 'ninja-scroll', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d2007f2-8052-49ca-9c62-a1024bce6ce3.jpg?w=331&h=447&p=t', 'hulu', 2003, 1, 1, 'FINISHED', NULL, 618, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b6f5e771-f846-406c-b0c7-540e43ce201b', '出会って5秒でバトル', '', 'hulu', 'battle-game-in-5-seconds', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba159455-f412-4a6f-b3fc-dd63a8315e86.jpg?w=331&h=447&p=t', 'hulu', 2021, 2, 1, 'FINISHED', NULL, 126047, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 'b6f5e771-f846-406c-b0c7-540e43ce201b', 'hulu-battle-game-in-5-seconds-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f1ce188-f8b2-40e0-a178-456ee3f3336b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f95dc6f-c1a3-4104-9881-c9f3be11598f', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 1, '100233264', '詭弁家', 'ゲームが趣味の高校生･白柳啓は日常に退屈していた。そんなある日の通学途中、突然謎の男に襲われる。とっさの判断力で撃退するも、直後に現れたマジシャン風の女･魅音によって無残にも殺されてしまう。目が覚めると、謎の施設に集められていた啓。魅音に「能力」の実験モニターとしてプログラムに参加してもらうと告げられ、過酷な能力バトルに巻き込まれてゆく。そして啓は決意する、「このゲームを遊び尽くす」と。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f1ce188-f8b2-40e0-a178-456ee3f3336b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee1288f6-fbc3-41c3-979d-da0c02b6ae9c', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 2, '100233265', '鬼神', '「偶然」という言葉が大嫌いな不幸体質の女子高生･天翔優利は、啓と同じく謎の組織に集められたモニターの一人。ある日、ビルの屋上で身投げ寸前の男を助けようとして死んでしまう。最初のプログラムは1on1での決闘。対戦相手の予想外の行動に戸惑う優利は苦戦を強いられるが、同居していた少女の元に戻るため、絶対にこのゲームをクリアすると誓う。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/404b04fe-e017-4caa-8d59-9cb1bb896287.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b344bfa2-88f1-4862-9c9c-4c1ad34b6a31', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 3, '100233266', '真剣師', '2ndプログラムは5対5の団体戦。各々が自分の能力を明かしていく中、啓は自身の能力を「手を大砲にする能力」と偽る。相対する敵チームには妖艶な美女･香椎鈴や引っ込み思案な女子高生･多々良りんごの姿があり、双方一進一退の攻防を繰り広げる。勝敗の行く末を決める重要な一戦、満を持して霧崎が登場する。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92cbdeae-32b5-48d2-b129-2d2f9e367852.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed87400e-1e9b-4f4d-bfdf-5cb9cc633b62', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 4, '100233267', '皮肉屋', '命をも失いかねない5対5の団体戦、中盤に登場した霧崎は「木の枝を何でも切れる剣に変える能力」で好戦するも、油断により逆転されてしまう。次に登場した啓は、対戦を通して冷静に自身の能力を検証し、より理解を深めていく。チームの勝敗がかかった最終戦、優利はこのゲームに参加するキッカケを作った因縁の男、星野王子と対峙することになるが……!?', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25ee19fc-9786-4c1a-8ab5-3a331ac4a3ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0840e57-9913-411d-b8e9-c0d3cb3bd39c', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 5, '100233268', '狩人', '3rdプログラムがスタート。開始と同時に、啓の目の前に「キミを勧誘しに来た」と関西弁を喋る克也という男が現れる。克也によると、3rdプログラムには複数の派閥があり「赤チーム」は危険な連中が仕切っていて、自分たちは「緑チーム」に属しているという。プログラムクリアの糸口を探る啓は、緑チームの陣地を訪れチームリーダーの白鷺と対面する。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f75c7337-b7aa-4ffd-9b1d-a6c17bbb9b08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('613bdd26-8c4a-4913-b17b-c93673ad04e5', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 6, '100233269', '調停人', '「緑チーム」に留まることにした啓は、来るべき戦いに備えて自身の本当の能力を優利に告げる。魅音から大規模討伐クエストのアナウンスが入りクエストに参加するが、そこには「赤チーム」のリーダー大神と黒岩らが「緑チーム」の偵察に訪れていた。能力を隠すためその場から離脱を図る白鷺たちに対して、黒岩は残酷な策を講ずる……。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8c0787d-46f4-44b1-80df-154a121c1470.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94699951-a315-4f22-9b21-e6ca3fe821f3', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 7, '100233270', '暴君', '魅音によって、大規模クエスト「王様狩り」が告知される。赤チームと緑チームがそれぞれの存亡をかける次回クエストまで、束の間の平穏を手に入れた啓達。各々の陣営が来たるべき戦いに向けて準備を進める中で、啓の「本当の能力」に気づいた“ある人物”が動き出す……。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a09a01be-9e12-4742-99de-016a668c90e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6f3a32b-ca35-41aa-a567-92cf160ca769', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 8, '100233271', '護衛官', 'クエスト勝利に向けて準備を進める啓は、青チームのリーダー･万年青と接触し協力を求める。時が満ち「王様狩り」が開始されると、王様である大神が予想に反して最前線に現れ、圧倒的な暴力で戦場を支配していく。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/faac9dc0-b696-45d0-a936-d24732e24626.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1412bf7-fd42-4523-98cc-7979e1a8395a', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 9, '100233272', '鉄の処女', '大神の登場によって戦線は一気に拡大し、各地で戦端が開かれていく。優利は窮地に陥っていたアスカを救うべく大神と交戦し、啓と霧崎は赤チームの幹部である竜胆と対峙することに。赤と緑が死闘を繰り広げる中、同じチームだった鈴と恋華は戦中に紛れて互いを始末しようと事を構えていた。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/049ff9ed-f13f-433c-bf7e-4bde5e469729.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('beb53b08-a9dc-4cca-971a-d399d757c42c', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 10, '100233273', '金剛手', '奮戦により赤チーム幹部と好勝負を演じ、戦況は緑チーム優勢に推移していく。両チームの勝敗がかかった重大な局面で、ついに緑チーム内に潜んでいた裏切り者が動き出す。一方、啓は赤チームの副リーダー黒岩をその射程にとらえようとしていた。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/46c7527b-3c9d-4b67-a924-ceca07d2271d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5115ab80-1e06-49d1-94d2-46d3aecfdc85', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 11, '100233274', '高利貸し', '黒岩の能力に苦戦を強いられる啓。互いの高度な権謀術策が飛び交う中、先の先を読み勝利を掴むのは――。一方で、大神を倒すべく戦いを繰り広げていた優利、霧崎、熊切は、突如変貌を遂げた大神の圧倒的な力の前に為す術を失っていた。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f9669d2-9845-4c9f-9c26-0ab6275ea6df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0368905f-118b-4cc7-9b12-425c94a14cef', '5b1ac78a-9dae-4d5d-9b4d-637891d2ec27', 12, '100233275', '最後の能力', '【最終話】数多の犠牲を乗り越えて「王様狩り」は最終段階を迎えていた。3rdプログラムのクリアのため、似た境遇を持つ少女の元へ戻るため、各々が内に秘めた想いを叶えるべく死力を尽くして立ち上がる。戦いの先に待つ未来とは――。', '2025/08/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e43c3eef-f384-4791-88ed-0d4fea3c8a6f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ac7daf56-7879-44c7-ab21-d5f8b41319c5', '出禁のモグラ', '', 'hulu', 'dekin-no-mogura-the-earthbound-mole', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53355d07-5639-4af0-a6b2-04a8361a7481.png?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 184574, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4dee06a2-518b-4cff-b836-ecfb98a33e80', 'ac7daf56-7879-44c7-ab21-d5f8b41319c5', 'hulu-dekin-no-mogura-the-earthbound-mole-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06714019-0d64-4dc1-85bd-4eba05f0408b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f0b2d30-b4bb-4c17-86c8-c0e91c590a7b', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 1, '100232367', '都内某所にて', '真木栗顕と桐原八重子は、すれ違った男の頭に広辞苑が直撃し、血を流して倒れるところを目撃してしまう。なぜかその男は2人の介抱や救急車を拒絶し、ケガ人とは思えない機敏さで逃げ出してしまう。その男は自らを「モグラ」と名乗り、「自分はあの世から出禁を食らっているから死なない」と、奇妙なことを語るのだった。', '2025/07/10 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06714019-0d64-4dc1-85bd-4eba05f0408b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f64e2f2-171d-4755-a465-a7ac98732e58', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 2, '100232368', '幽霊=人間', 'モグラは、かつて戦争に招集され、この世の地獄を見たと語る。そんなモグラの目的は、再びカンテラに灯を集め、あの世にたどり着くことだった。数日後、モグラは2人から相談を受け、心霊写真に写っている八重子のバイトの後輩･犬飼詩魚のもとを訪れる。彼女にまとわりついていた幽霊を追い払って、火を集めることに成功するモグラだったが…。', '2025/07/17 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcdcfb2f-3abb-4df8-8ef9-7b2bbc92493d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c768b872-8e35-4627-b7be-89d007e27b71', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 3, '100232369', '揃った人材', 'ストーカー幽霊から逃げるモグラたちは、祓い屋見習いである、猫附梗史郎と出会う。梗史郎は巨大化け猫の「ナベシマ」の手を借りて幽霊を撃退した。さらに、彼の父が、真木たちの大学の教授であることが発覚する。数日後、真木はバイト先に出る幽霊達に困り、モグラの伝手で猫附親子にお祓いをしてもらうことに。猫附家がモグラの依頼を断れないようだが、その理由とは一体…。', '2025/07/24 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69701db3-ee70-4ca1-ac63-b7a9016eca53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('804e95dd-2c4c-45e2-beca-8ca6c4616820', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 4, '100232370', '狂犬とレッサーパンダの怪', '真木のバイト先100えんHOMEで起きた怪現象の正体。それはレッサーパンダ「マギー君」の幽霊であり、祓おうとするモグラたちに対して、ポルターガイストや金縛りで抵抗を始める。追い詰められたマギー君だったが、自分とよく似た“とある人物”にとり憑くことで一件落するも、今度は真木の弟･真木梅晴が、新たな心霊現象に巻き込まれていた…。', '2025/07/31 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ffa70d6-91c7-4881-8dbf-a803ad052f02.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('209fdf6d-345f-4e3e-9ade-a017f53f65ba', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 5, '100232371', '引き金', '真木の弟･梅晴からの聞いた、女友達･ミヤの家族として扱われていた異様な人形は、亡くなったミヤの姉であるマヤを忘れないための形見だった。しかし、その人形が突然いなくなったという騒ぎを聞き、モグラたちは急いで人形を捜索する。そのころ、人形が向かった先では、今まさに新たな凶霊が生まれようとしていた。', '2025/08/07 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b02d716-4fb2-4250-9158-de21ff9221e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7e55259-7cb5-47ae-8795-749422fa9125', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 6, '100232372', '兄弟と姉妹と', '間一髪、モグラはカンテラの灯を使い、マヤの凶霊化を阻止。マヤは姿を消し、残されたミヤは、人形を供養して前に進もうと決意するのだった。それから数日、詩魚は梗史郎の母･杏子に誘われ、ケーキをご馳走してもらうことに。そこに現れた近所の主婦･咲良子は、杏子の持つ「特殊な力」に依存し、神のように崇めていた…。', '2025/08/14 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/079a4e89-7be0-40b0-ba12-544a6bcc30a8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55411d6a-91be-4db8-b1f3-789d4e7af040', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 7, '100232373', '結果しか見えない罠', '杏子の「先の未来を予測する目」に依存していた主婦･咲良子は、梗史郎の除霊と、意外な“霊”の手を借りて鬱憤をさらけ出し、ようやく迷いを吹っ切れる事ができた。とある日、祭りに関する課題の題材に迷う真木に、八重子は地元の「人魚祭り」を調べることを提案。その理由には、モグラの過去に関わりのある、とある人物を訪れるという目的もあり…。', '2025/08/21 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49df442c-0371-4b3d-8df5-79891a09945b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('372314fc-33e7-495a-a2cc-7ae1034aeb33', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 8, '100232374', '人魚様', '八重子の地元に伝わる「人魚を鎮めるお祭り」を調べるために、真木たちは八重子の実家へ。そこでモグラは八重子の曽祖父･雄八と再会する。祭りが始まると、沖に浮かぶ「人魚様岩」には、いくつもの霊が集まり、巨大な「人魚」が現れた。一方、八重子はかつてのクラスメイト･森を見つけ声をかけるが、異様な空気を纏った森は、その場を立ち去ってしまう…。', '2025/08/28 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc7f58b7-c3a1-4c6c-8ff5-5d82716f5864.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc91a5be-7b4d-4fc7-9689-0f6b2521674c', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 9, '100236170', '偉大な母の愛', '森が自殺未遂を起こし慌てる八重子だが、そこに大地主の鮫島鯉太郎と孫の鮋依があらわれ、島の観光案内を申し出る。モグラは島民の噂と八重子の父の説明により、鮫島家と森家の間で起こったトラブルを知る。一方、梗史郎はナベシマを使った盗聴により、島を支配する鮫島家の実態と、森家を陥れようとする策略を知る。その事実を知ったモグラたちは…。', '2025/09/04 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0b14e58-9e5d-48f9-9a79-b99a7d927796.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10bae86e-7f80-4d06-91df-bfc280747488', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 10, '100236171', '真価', '森が語った真実、それは鮋依による巧みな噂の扇動により、追い詰められたという過去であった。鮋依によりトラウマを刺激された森は、助けようとした真木とともに、人魚に海に引きずりこまれてしまう。絶体絶命の2人は、モグラの人並み外れた技により一命をとりとめた。一連の出来事を見ていた鯉太郎は、ついに隠された本性をさらけ出す。', '2025/09/11 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20ee46f2-ee31-4551-9e55-8e14ad381636.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8fedb5d-00ea-4fde-ada1-837364835962', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 11, '100236172', '人魚と化け猫', '猫附親子が操る化け猫2匹により人魚を無力化することに成功。モグラに撃退され気絶していた鯉太郎は、ついに人魚の姿を認識し、恐ろしさのあまり人格崩壊を起こしてしまう。一方、鮋依の車で移動していた杏子は、何らかの「奥義」で鮋依を言い負かす。人魚の最後の抵抗により、鮋依が海へと転落してしまうが…。', '2025/09/18 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80c41353-08e4-46fb-aeaf-7aa2dbee283f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d32ca88-2e13-4d2c-939b-6efe5061f972', '4dee06a2-518b-4cff-b836-ecfb98a33e80', 12, '100236173', '梅雨の中にて', '【最終話】事件後、一連の責任を鮫島家に押し付けようとする島民たちを叱りつけたのは、八重子の父だった。騒動が解決し帰ろうとするモグラに、八重子の曽祖父･雄八は1通の手紙を託す。それはかつての戦友へのメッセージだった。東京へと戻ってきた後、抽斗通りで駄菓子屋の女性と出会った真木は、彼女の名と役職、そして、モグラの驚くべき過去を知る…。', '2025/09/25 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60ad1b44-66a8-42e1-af9b-ef2d48ffd81e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('00394836-4fac-45be-adeb-baa9babdea32', '出来損ないと呼ばれた元英雄は、実家から追放されたので好き勝手に生きることにした', '', 'hulu', 'the-banished-former-hero-lives-as-he-pleases', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0e6df8a-2985-42e9-8990-8655a97dac0a.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 166372, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2f1598cf-d1ca-4d35-b267-b6333478a7f2', '00394836-4fac-45be-adeb-baa9babdea32', 'hulu-the-banished-former-hero-lives-as-he-pleases-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd5fa5df-3a84-4d0c-b8d3-1b17e559aab0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56b30258-46af-4cb2-8ea4-afd9d9da58e1', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 1, '100180117', '追放', '世界を救った元英雄アレン。平穏な暮らしを望んで転生した先は、異世界の名門公爵家。ギフトを得られず、出来損ないと見なされて家を追放されてしまう。だが、息苦しい生活に辟易していたため、追放を喜び、自由気ままな旅を開始することに。その旅の途中、元婚約者であるリーズが魔物に襲われているところに遭遇してしまい……。', '2024/04/05 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd5fa5df-3a84-4d0c-b8d3-1b17e559aab0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('590204f4-88f1-48c7-9822-153c2aedb0e0', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 2, '100180887', '聖剣の鍛冶師', '赤龍王との闘いで剣を折ってしまったアレンのため、一行はグランホルムを目指すことに。そこに住む鍛冶師･ノエルは、リーズの友達ということだったが……忙しさを理由に、剣を打つのを断られてしまう。ところが、アレンの折れた剣を見せた途端、ノエルの態度に変化が。「“聖剣を超える剣”に興味はある?」と、持ちかけられ……。', '2024/04/12 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52ffe2cd-f39e-4532-8540-d42e46d957cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29b84cba-fdfe-4fd4-9325-f723e289fa2b', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 3, '100181746', '意地と覚悟', '森で遭遇した魔物･フェンリルに、異常なまでの復讐心を抱くノエル。自身の剣で切りかかろうとする彼女を、「その剣では傷一つつけることは出来ない」とアレンは説得する。復讐を諦められないノエルは、寝ずに剣を打ち直し、遂に聖剣を超える剣を完成させる。その剣で復讐を果たそうと、一人森へ向かうが……。', '2024/04/19 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d3d0a29-2984-40fd-be36-f2254fcd17d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('978792af-86db-442b-a968-6a11c68e2365', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 4, '100182365', '降霊祭', '将軍暗殺の手がかりを探すアレンたちは、ノエルからある噂を聞く。リンダールの村に出る“銀の鎧”の霊――悪魔が関わっている可能性があると知り、一行は村を調べることに。だが、降霊祭の準備中だという村は平穏そのもの。そんな中、“銀の鎧”に思うところがあるリーズ。実は、亡くなったリーズの叔父も、かつて銀の鎧をまとっていた……。', '2024/04/26 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f3a945d4-b384-464c-8676-621e42487fd5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5b45fc6-6196-427b-8aca-bd17dcd4d833', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 5, '100183226', '狂乱の開幕', '「死んだはずのシリル将軍が現れた」という噂に揺れる王都。その裏では、クレイグたちの謀略が進んでいた。訓練場に誘き出される第一騎士団のエドワード団長――悪魔に襲われる勇者･アキラ……そして、大司教と共に、民衆の前に姿を現すシリル将軍。クレイグと、ブレットの歪んだプライドが、王都を襲う!', '2024/05/03 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74b94a18-6506-426a-9f33-c49738ada682.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cebca8bf-5406-4bf6-b782-89227af6751b', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 6, '100183738', '憎悪の果て', '騒乱の王都に現れたアレンによって、クレイグたちの陰謀が暴かれる。将軍暗殺、リーズ暗殺未遂……いずれも、悪魔とヴェストフェルト公爵家が組んで行ったものだった。一方、復讐心に駆られ、悪魔の力で暴走するクレイグ。王都に降りかかる闇の力を振り払うため、かつて出来損ないと呼ばれた息子、アレンがその前に立ちはだかる!', '2024/05/10 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8d88e77-f887-4f54-a2ed-db0b4bee5340.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eccdc03d-deb0-4292-b46b-79072bc06adc', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 7, '100184442', '帝国の侯爵令嬢', '王都の戦いから半年。平穏な暮らしを送るアレンは、転生直前の夢を見る。それは、使徒アンリエットとの最期の対話だった……。日々の暮らしに思うところあったアレンは、ヴィクトゥル帝国へ旅立つことを決める。そこで待ち受けていたのは……くすぶる戦争の火種、そして、侯爵令嬢へと転生していたアンリエットだった。', '2024/05/17 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03881565-66c3-4be5-aee7-da83857c12e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96e53dca-09e8-4ce2-95af-df13f76d28ff', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 8, '100184910', '妖精王', 'アンリエットの屋敷に匿ってもらう間、暇を持て余して街へと遊びに行くノエル。だが、なぜか街のエルフたちからの注目を集めてしまう。理由を知るアンリエットは、“昔の記憶がない”ノエルを連れて、アレンたちをエルフの森へ誘うが、そこでノエルの出自が明らかになり――。', '2024/05/24 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c41674b-0f04-4fc0-8c4f-aaec17f3841a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a43d9cd0-f7bd-49ea-aaa7-3325ae1ebb7c', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 9, '100185890', '悪魔の烙印', 'エルフの森に滞在中のアレンたち。 “エルフの王”を望まれるノエルは、決断を悩んでいた。 そんな中、黒狼騎士団が動き出す。 屋敷に戻ったアンリエットを待ち構えていたリゼット。 さらに、エルフの森に侵入したオズワルドに、悪魔の子供も見つかってしまう。 前世での苦い経験から、「救うべきか?」とアレンもまた、決断を悩むことに……。', '2024/05/31 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dcad4472-cc2a-40e5-ad5a-0c4f1c7d9c13.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3341aa5c-5cf7-4f92-a5c5-f67d4037b877', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 10, '100186520', '助けを求める声', '街道の封鎖が解かれ、帝国を発つことにしたアレンたち。しかし、その直前、アンリエットの弟を名乗る青年･カーティスが現れ、助けを求めてくる。なんと、アンリエットが皇帝暗殺事件の主犯として、黒狼騎士団に連行されてしまったのだという。アレンたちは、カーティスに疑いを持ちつつも、共に帝都を目指すことになるが……。', '2024/06/07 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4537cbe6-97d7-4431-ae9f-974803ebe07a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f65df091-0266-4253-9c2c-a7743ce205a3', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 11, '100187224', '惑う元英雄', 'ノエルとミレーヌを人質に取ったオズワルドと対峙するアレン。 難なく二人を救出するが、すでにオズワルドに『エクスプロード』を仕掛けられていた。 しかも、周囲にいる負傷した多数の市民たちも同様で――。 そこで思い出されたのは、助けた子供に「化け物」と罵られた……前世での記憶。 逡巡するアレンの出した答えは……!?', '2024/06/14 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7af52642-a02c-4c4a-8678-1bf2fba67367.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0d69e3c-2fec-4123-8636-c73f4a74d3fe', '2f1598cf-d1ca-4d35-b267-b6333478a7f2', 12, '100187877', '元英雄は好き勝手に生きる', '【最終話】地下牢のアンリエットの前に現れたカーティス。 すべては、悪魔の力を手にしたカーティスが仕組んだことだった。 一方、アンリエットから手助け無用と告げられたアレン。王国への帰路を選択するが、リーズから「戻りましょう」と提案され……。 かつて実家を追放され、好き勝手に生きようと願ったアレン。 その旅路の先に望んだものは――。', '2024/06/21 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f12b380-d9bf-43f9-9328-6b3f7eb9d359.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('27974804-c75e-4f5e-9173-b81cd03357ab', '盾の勇者の成り上がり', '', 'hulu', 'shieldhero', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f9c3c80-c3a7-4a44-b309-90bc77474ded.jpg?w=331&h=447&p=t', 'hulu', 2019, 0, 1, 'FINISHED', NULL, 99263, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('aa97fce9-d57a-4b54-90bc-94fba7244f6c', '27974804-c75e-4f5e-9173-b81cd03357ab', 'hulu-shieldhero-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3c9c7f4-72bc-46e1-8d13-02e766e37395.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df37b58c-19ce-4091-bdc6-3e976f1df01b', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 1, '100029753', '盾の勇者', '図書館で『四聖武器書』という本を読んでいたところ、突如として異世界へ召喚された大学生･岩谷尚文。伝説の勇者の一人「盾の勇者」として世界を救うことになるが、ある朝、金と装備が盗まれてしまう。', '2019/01/17 00:00:00', 2841, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3c9c7f4-72bc-46e1-8d13-02e766e37395.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8dc925c5-feaf-4e50-b778-8109998a7e1a', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 2, '100030016', '奴隷の少女', '奴隷商に案内され、自らの剣となるパートナーを探す尚文。だが、手持ちの少ない尚文が買えるのは、病を患った亜人の少女のみだった。尚文はラフタリアと名乗る生気のない少女に、過酷な戦いを強いる。', '2019/01/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00e5c774-928f-4b33-9e96-b74286a1126e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3df965ad-fcc7-436d-bdd1-fbb59801b55d', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 3, '100030234', '災厄の波', '様々なスキルと技能を習得し、ラフタリアとの連携も抜群によくなった尚文。迫りくる波に対抗して武器と防具を新調し、波の刻限を示すという龍刻の砂時計へ向かう。すると、そこへ元康たちがやってきて…。', '2019/01/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7153d96-7379-45f5-8e2c-5947d23033f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5400af59-3fe9-49b0-ad0c-daef13944721', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 4, '100030477', '暁の子守唄', '波が去ったのも束の間、メルロマルク城での祝宴のさなか尚文は元康から決闘を挑まれてしまう。奴隷を使役するのは勇者にあるまじき行為であり、即刻、ラフタリアを解放せよというのが元康の言い分なのだが…。', '2019/02/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c190a96f-1710-41c4-bee6-684a9ae685d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4c1c1ef-6edb-4334-88f7-7ef2504eeab2', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 5, '100030686', 'フィーロ', 'オルトクレイからなけなしの報酬を渡された尚文は、ラフタリアの要望で再び奴隷紋を入れ直した。数日後、奴隷商から購入した魔物の卵くじも孵化。新たな仲間を加えるが、滞在中のリユート村にマインが現れ…。', '2019/02/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8582699f-4d9d-414c-ba8e-2e4a6fd01f95.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b484236d-afa9-4af9-af1d-1ef3900c7b86', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 6, '100030805', '新しい仲間', '謎の少女の正体はフィーロだった。フィーロは変身能力を持つフィロリアル･クイーンであり、人間の姿にもなれるという。しかし、変身のたびに服が破けるため魔法の服が必要に。尚文は素材を求め、新たな冒険に出発する。', '2019/02/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2828e870-d82c-41a5-a244-9c9450e80677.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fab223dd-965b-48c2-adbe-4c60251ae64d', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 7, '100031291', '神鳥の聖人', '除草剤を必要としている村があると聞き、行商に向かう尚文たち。村は魔物化した植物に飲み込まれ、住民は避難を余儀なくされていた。人間にも寄生するこの植物、どうやら原因を作ったのは元康のようで…。', '2019/02/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/536893d7-d7c3-4e56-8979-385772c0b10a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24ba396c-2bd7-40d7-91bf-228af8b543df', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 8, '100031755', '呪いの盾', '疫病に苦しむ東方の村の話を聞き、薬を届けに行く尚文たち。疫病の原因は、1ヶ月前に退治されたドラゴンの死骸が適切に処理されぬまま腐敗してしまったためだった。死骸処理の依頼を受け、尚文たちは山を目指す。', '2019/03/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b382d537-1b20-42b0-9583-baa64363238c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b4bf075-1a39-4dce-8ba6-2e50a9bb9ef1', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 9, '100032006', 'メルティ', '東方の村で、尚文はメルティと名乗る少女に出会う。フィーロとすぐに打ち解けた彼女は、一緒に王都に行きたいという。どうやら護衛とはぐれてしまったらしい。しぶしぶ同行させるのだが、王都で待っていたのは…!?', '2019/03/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/910c34bf-268b-4139-8f36-8f51967a777e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b41405f2-bed7-4f0c-8d02-9e238288496c', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 10, '100032509', '混迷の中で', 'メルティを拒絶した尚文は、粛々と次の「波」に備える。協力したいという少年兵を条件付きで受け入れ、加えてレベルアップしたラフタリアをクラスアップさせようとするが…そこに王の嫌がらせが待ち受けていた。', '2019/03/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cccf0945-ada1-4377-88b8-6bccd47456d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('036e8ad9-8337-45e2-a748-a12988f0266e', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 11, '100032779', '災厄、再び', '辺境の村で新たな「波」を迎え撃つ尚文。志願兵の協力もあって村人の安全は確保したが、「波」はいつまで経っても収まる気配がない。尚文がほかの勇者の援護に向かうと、そこには巨大な幽霊船が浮かんでいて…。', '2019/03/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b09ad231-bfe0-407f-95cf-e505b35fb254.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1b37a8c-82d7-4fb5-885f-69ddd7620735', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 12, '100033273', '漆黒の異邦者', 'ソウルイーターを一撃で仕留めた謎の少女、グラス。「真の波の戦い」を始めると告げ、最初に攻撃を仕掛けた錬、元康、樹を圧倒する。尚文たちの連携技も通用せず、満身創痍の中、尚文は再び憤怒の盾を使おうとする…。', '2019/04/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44c546a8-4337-4a30-912e-6615f201ddf2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a05dad74-ec8e-4a5e-a4e8-fff735a888d8', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 13, '100033623', '盾の悪魔', 'メルティへの攻撃を防ぎ、騎士団を追い返した尚文。しかし、メルティ誘拐と騎士殺害の濡れ衣を着せられ、逃避行を余儀なくされる。各地に厳戒態勢が敷かれる中、尚文たちに追い打ちを掛けるような事態が発生する。', '2019/04/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87ce421a-4bf7-4b9e-a85e-4f4af0572922.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a293103-c0f5-4d16-93e2-89b1412669df', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 14, '100034065', '消せない記憶', '山火事を起こすというマインの暴挙により、麓の村まで逃げてきた尚文。しかし、騎士団の包囲網を突破するのは簡単ではない。メルティは知己の貴族を頼ろうとするが、ラフタリアにとってここは因縁の地域で…。', '2019/04/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2bfcea7e-7d00-4a00-90a4-0041322b1f2e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c37c10a-ba54-4a7b-b3f4-8171d9536097', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 15, '100034436', 'ラフタリア', 'イドルを追い詰めるラフタリア。その瞳には復讐の炎が灯り、殺意を帯びた切っ先がイドルののど元に突きつけられる。尚文の言葉で一度は怒りを飲み込むが、イドルが再びラフタリアに襲いかかろうしたそのとき…。', '2019/04/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48a68ec4-3d5e-4766-a968-1d9261a7cd97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('505059d8-f53e-4124-becc-38b60b5855a8', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 16, '100034753', 'フィロリアルの女王', '衰弱した子どもたちを連れた尚文にタイラントが襲いかかる。フィーロが狙われていると気付いた尚文は、フィーロに乗ってタイラントを街の外へおびき出すが、正面から戦ってもダメージが通らず手詰まりになってしまう。', '2019/05/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a176176e-78db-4fe1-adff-b6e725a9ccff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ca10ce3-1d08-4336-ac71-be725c4728b3', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 17, '100034885', '紡がれる約束', '四聖勇者が和解しなければ皆殺しにするというフィトリア。さらにメルティを人質にするという強硬手段に出るが、それでも尚文は和解を拒絶。その想いを汲み取ったフィトリアは、代わりにフィーロとの一騎打ちを提案する。', '2019/05/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da226043-5d8f-4fa1-bbd5-2e55a2340a11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('100072cc-267f-407c-b57d-beb38af396b7', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 18, '100035077', '連なる陰謀', '勇者たちと話し合うため、尚文は正面から関所を抜けようとする。しかし、そこには一番話の通じなそうな元康が待ち構えていた。問答無用で襲いかかってくる元康。かつてないほどの殺意が意味するものとは…。', '2019/05/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8182d195-8948-4585-a0b2-650a67a5fe40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('679bf1fd-b5bf-4516-a626-cf8eaeb0ed6d', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 19, '100035631', '四聖勇者', '教皇が有するのは四聖武器の力を備えた究極の武器。その刀身から放たれる「裁き」と強大な魔力障壁を前に、尚文たちは為す術がなかった。窮地に陥る中、偽勇者として裁かれる側となった元康が驚きの行動に出る。', '2019/05/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7917dff5-5a19-4647-b491-96cc901a6a6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae8aa900-cbc6-4b93-a053-e274ee46c339', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 20, '100036067', '聖邪決戦', '教皇の「大聖堂」に囚われながらも、攻撃の手を休めない尚文たち。しかし、神聖な領域において呪いの盾は無効化され、あと一撃が届かない。尚文は新たに解放された呪いの盾を使おうとするが、竜の怒りに心を蝕まれて…。', '2019/05/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3464920e-4f4b-4bf5-a8c4-008bb0be3ef0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d76c8312-c44c-4de5-bf8d-c00cb8f398f1', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 21, '100036554', '尚文の凱旋', 'ミレリアのおかげで一命を取り留めた尚文は、彼女から勇者召喚の真実と盾の勇者が迫害される理由を聞かされる。そして、尚文の冤罪を晴らすというミレリアによって、オルトクレイとマインの弾劾裁判がはじまる。', '2019/06/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96b3c6e4-4c0f-4e2f-8ba9-235e2483b69f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('300a68ab-e577-4171-9475-cc34be2f11aa', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 22, '100036674', '勇者会議', '紆余曲折ありながらもクラスアップを果たした尚文たち。三勇者とともに祝賀会という名の会談に参加し、いわゆる「ボーナスステージ」の存在を知る。一方その頃、ラフタリアは祝賀会場で揉め事を起こしていた。', '2019/06/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80bf9b76-2630-4259-81ef-e499449a9c89.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50868dc1-6b31-44d2-b599-a23d708e0cea', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 23, '100037043', 'カルミラ島', 'カルミラ島に向かう船の中で再びラルクに遭遇し、尚文はペースを崩されながらも、気さくな彼と徐々に打ち解けていった。経験値稼ぎに、賑やかな食事。この世界にきて初めてと言えるくらい充実した時間が流れていく。', '2019/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43f9079d-99f4-4e8e-acf1-e3bc9818fe97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed448257-240b-4a10-a31d-192dfce0a035', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 24, '100037407', '異世界の守護者', '海上で波を迎え撃つため、メルロマルクは大艦隊を編成する。女王自ら指揮を執るが、三勇者は相変わらず役に立たず、尚文たちが孤軍奮闘するばかり。尚文はラルクとテリスの協力を得て波に対抗するのだが…。', '2019/06/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5128b6a3-4f7e-45df-b65b-4391fdc943b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59492e21-2eea-4d91-bc00-280a1d353a8e', 'aa97fce9-d57a-4b54-90bc-94fba7244f6c', 25, '100038196', '盾の勇者の成り上がり', '【シーズン1 最終話】グラスは異世界の勇者を名乗るラルクの仲間だった。尚文は強烈な連携攻撃を耐え凌ぎ、一騎打ちでグラスに肉薄するのだが…。本当にこの世界を守りたいのか、尚文はグラスとの戦いの中で己の覚悟を問われる。', '2019/07/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62d57874-118a-48f0-b67d-8448b1f00836.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('01d3cc61-e481-405d-8351-a2ad579fe1ad', '盾の勇者の成り上がり', '', 'hulu', 'the-rising-of-the-shield-hero-season-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3344fc4a-f041-422c-ad3d-314a526b3955.jpg?w=331&h=447&p=t', 'hulu', 2019, 0, 1, 'FINISHED', NULL, 99263, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5176135f-626e-488a-98d0-9e18f1f59261', '01d3cc61-e481-405d-8351-a2ad579fe1ad', 'hulu-the-rising-of-the-shield-hero-season-2-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2f300df-5b8a-48c6-afc5-d79957e5bdb8.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66b1cf37-0a1b-44c8-a79f-31bf2469ceec', '5176135f-626e-488a-98d0-9e18f1f59261', 1, '100109479', '新たな咆哮', '尚文が次の「波」への準備を進めていると、謎の魔物たちが現れ、同時に「波」へのカウントダウンが停止してしまう。急遽、ミレリアから呼び出された四聖勇者たちは、伝説の魔物「霊亀」が復活したことを告げられる。', '2022/04/13 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2f300df-5b8a-48c6-afc5-d79957e5bdb8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a96a752-4680-45f5-9ddc-76778302ff79', '5176135f-626e-488a-98d0-9e18f1f59261', 2, '100109896', '霊亀の足跡', '霊亀国に集う各国の司令官たち。尚文もまたその場に同席し、勇者の一人として力を貸すと約束。連合国軍による霊亀討伐作戦が動き出そうとするのだが、突如として謎の女性が会議場に現れる。彼女の正体とは……!?', '2022/04/20 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/195c09bc-b340-48db-86b5-a88c621d5b33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21390bde-5b34-4ca8-ae63-eda7989c1992', '5176135f-626e-488a-98d0-9e18f1f59261', 3, '100110478', '揺れる大地', '霊亀が活動を再開し、ついに霊亀国の辺境に現れる。尚文は自らが標的となって使い魔たちをおびき寄せ、エクレールたちは霊亀を山間部へ誘導しようとしていた。霊亀の使い魔であるオストも協力して果敢に戦うが……。', '2022/04/27 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d7562e2-b808-4577-bf23-27a751048d99.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6a446e5-2bab-45ed-8cb7-7de2395f9af8', '5176135f-626e-488a-98d0-9e18f1f59261', 4, '100110799', '霧中の遺跡', '霊亀の首を落としたものの、使い魔のオストは健在であり、いつ霊亀が復活してもおかしくない状況だった。連合軍は再編成が急務の状況。尚文はリスクを覚悟して少数の仲間と霊亀の背に登り、真の弱点を探ろうとする。', '2022/05/04 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f480d97f-9130-4ab0-b31c-0e574f397ca0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f85322ce-88e8-47f3-8e46-bfd0cec0a6c9', '5176135f-626e-488a-98d0-9e18f1f59261', 5, '100111113', 'オスト＝ホウライ', '尚文の前に現れたのは、ラルク、テリス、グラスだった。三人が追っているのは、霊亀の封印を不正に解き放ち、操っている者。尚文の目的と一致していた。ラルクは、また手を組もうと提案してきて……。', '2022/05/11 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bbcc9b4-b58a-4f05-bc60-3e92da8e6da7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('231d12f9-e156-4727-b473-f6229aa11161', '5176135f-626e-488a-98d0-9e18f1f59261', 6, '100112021', '追駆', '霊亀が復活すると同時にフィトリアが現れ、尚文はフィトリアが霊亀の首を落とすタイミングに合わせ、心臓を破壊しようとする。そこへラルクたちも合流するのだが、キョウは圧倒的な力で尚文たちを追い詰めていく。', '2022/05/18 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aed85e99-068d-4901-baf2-2236095fbc13.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da6836c0-d052-4bdb-91f3-06c7083bd139', '5176135f-626e-488a-98d0-9e18f1f59261', 7, '100112388', '無限迷宮', '尚文が見知らぬ牢獄で目覚めると、全員がレベル1になり、フィーロの行方がわからなくなってしまった。尚文は脱出の方法を探りながら、レベルを上げようとする。しかし、突如として現れた魔物に大苦戦してしまう。', '2022/05/25 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9bd192e-3978-4783-9a2a-83e91866d4e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf89b147-139c-4bca-87a3-5366dfe73af1', '5176135f-626e-488a-98d0-9e18f1f59261', 8, '100113153', '雪の別れ', '絆を召喚したシクール国へ向かうため、尚文たちは行商しながらミカカゲ国の龍刻の砂時計を目指す。希少な回復アイテムを販売し、売上を伸ばす尚文。だが、偶然知った天才術師の存在に思うところがあり……。', '2022/06/01 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/edf563a7-4782-48ad-81b5-1df461ccf281.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9187fde-19eb-4fdf-a27f-bb59bab3f0cd', '5176135f-626e-488a-98d0-9e18f1f59261', 9, '100113974', 'ハミングフェーリー', 'シクール国に転移した尚文たちは、絆から眷属器の勇者エスノバルトを紹介される。彼は、ラフタリアの髪の毛と尚文の血を触媒とした式神なら彼女の居場所がわかるという。式神を生成し、そこに現れたのは……。', '2022/06/08 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17332228-96d1-46ce-bdfb-54454553a3c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('064320d9-8e3c-4f3b-bd92-9b3419c04eb0', '5176135f-626e-488a-98d0-9e18f1f59261', 10, '100114481', '刀の勇者', 'レイブル国の牢獄に囚われたラフタリアは、同じ牢に収監されたラルクたちを警戒しつつも、脱出のための協力を仰ぐ。だが、グラスは減退牢獄で生命力が低下していた。ラフタリアには脱出の策があるというが……。', '2022/06/15 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0026d286-87cd-41fb-869e-ff17bf0014d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7e3b502-d7ed-498d-8bf5-1c878c63d157', '5176135f-626e-488a-98d0-9e18f1f59261', 11, '100115052', '絆', 'ラフタリアとの再会を喜ぶ尚文たち。グラスたちも絆と合流し再会を喜ぶが、絆はグラスたちが別の世界へ侵攻したことを非難。尚文たちとは戦わないと誓い、別の方法を探ると決意する。そんな中、キョウの魔の手が迫る。', '2022/06/22 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abc12700-a008-49b1-85b8-188d286617a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f776a44a-50db-4e91-85bf-5a011d137351', '5176135f-626e-488a-98d0-9e18f1f59261', 12, '100115873', '戦う理由', '刻限を待たずして「波」が発生。絆たちは「波」のもとへ転移させられ、尚文たちはエスノバルトの船でキョウの研究所へ向かう。そこで人を人とも思わず、あらゆる者を捨て駒にしていくキョウの悪意を目の当たりにする。', '2022/06/29 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/807bfd2b-c9eb-49cb-aa33-ab1511deb022.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94b8e9da-a74f-4c16-a518-3ddcd2070592', '5176135f-626e-488a-98d0-9e18f1f59261', 13, '100116529', '追憶の献花', '【シーズン2 最終話】ある目的のためにルルロナ村を発った尚文たち。その道中、ラフタリアとリーシアはミカカゲ国で絆と服選びをしたことを思い返すのだった。絆にいろいろな服を着せられるラフタリア、そしてリーシアも巻き込まれ……!?', '2022/07/06 23:30:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c550143b-dd06-462f-a5f2-7732d3da9287.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d2f6bcdb-2e73-466d-80ff-a46ed7e72b26', '盾の勇者の成り上がり', '', 'hulu', 'the-rising-of-the-shield-hero-season-3', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/949956d2-93b6-41e0-b4ad-b33fd9a67522.jpg?w=331&h=447&p=t', 'hulu', 2019, 0, 1, 'FINISHED', NULL, 99263, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8720169d-9b26-4e88-bb4b-f279c91b328e', 'd2f6bcdb-2e73-466d-80ff-a46ed7e72b26', 'hulu-the-rising-of-the-shield-hero-season-3-s1', 'シーズン3', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9b80bd5-ad74-4d71-98f7-c05fdadc8ad3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b4f1dc0-415a-4ea7-bad8-042f65771786', '8720169d-9b26-4e88-bb4b-f279c91b328e', 1, '100161947', '闇のコロシアム', '新たな四霊「鳳凰」の復活に備え、尚文は散り散りになったルロロナ村出身の亜人を取り戻そうとする。だが亜人の奴隷たちはある理由で買い占められていた。尚文は彼らを救うため、商人と傭兵の国ゼルトブルへ向かう。', '2023/10/11 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9b80bd5-ad74-4d71-98f7-c05fdadc8ad3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8c90ffb-d46c-480d-91ff-56a7b6871217', '8720169d-9b26-4e88-bb4b-f279c91b328e', 2, '100162648', 'ナディア', '正体を隠して地下賭博闘技場に出場する尚文たちは、闘技場内外に渦巻く欲望と無法ぶりを身をもって知りながら勝ち進んでいく。そして、ついに迎えた決勝戦。ラフタリアは対戦相手の特徴に聞き覚えがあるようで……。', '2023/10/18 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6fcda02-6ebd-4444-b049-2e49edbf63e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93163076-0f33-4768-b135-dc1c415eaf61', '8720169d-9b26-4e88-bb4b-f279c91b328e', 3, '100163631', 'ハクコの兄妹', '奴隷市場を訪れた尚文は、亜人の奴隷フォウルに病気の妹を救ってほしいと懇願される。代価を支払う覚悟を問う尚文だが……。一方、救出された亜人を迎え入れ活気づくルロロナ村に、大きな危機が迫ろうとしていた。', '2023/10/25 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3226700-db7c-4ae5-8b87-f2390e2b13c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41aceb27-6044-4f22-93ba-3457ef130d50', '8720169d-9b26-4e88-bb4b-f279c91b328e', 4, '100164300', '槍の勇者捕獲作戦', '槍の勇者･元康の所在が確認され、ミレリアに説得を頼まれた尚文。領地はエクレールに任せ、元康探しに向かおうとすると、そこへ招かれざる客がやってくる。そして、元康が滞在する町では予想外の人物に遭遇し……!?', '2023/11/01 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/706c599e-830a-4d6c-b087-7ac6a9c5b4c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08174e8f-6ae7-4398-96a2-ae66bcdce1a1', '8720169d-9b26-4e88-bb4b-f279c91b328e', 5, '100165108', 'それぞれの道', '街道で謎の二人組に襲撃される尚文たち。相手はラフタリアの攻撃を軽く受け止め、尚文の援護魔法を解除し、果ては巨大な隕石まで操るかなりの手練れだった。追い詰められる尚文たち。窮地に現れたのは……!?', '2023/11/08 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f56d2f9-3b73-43ed-9bbf-6f60e3e80423.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('463056e5-ed97-4ee0-a4d6-8688a666d224', '8720169d-9b26-4e88-bb4b-f279c91b328e', 6, '100165735', '強さの矛先', '剣の勇者･錬はかつてプレイしたゲームとこの世界を重ね、ゲーム感覚で行動した結果、悲劇を招いてしまった。すべてを失いながら、それでも引けない願い。さらなる力を求める錬が、尚文と元康を襲う!', '2023/11/15 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcaedfe5-00ed-4f82-b5d4-ed610ecda3b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f5ff01f-f4b6-4d55-8003-7fcf3426d69e', '8720169d-9b26-4e88-bb4b-f279c91b328e', 7, '100166591', '少女とドラゴン', 'ミレリアの紹介で尚文のもとへ魔物専門の錬金術師ラトが派遣されてくる。彼女を村の魔物小屋へ案内すると、尚文は魔物好きの少女ウィンディアからひときわ大きな卵を渡される。その卵は、なんとドラゴンの卵で……!?', '2023/11/22 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f3ba74b1-d770-42e4-9fd3-af15950ec2cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9829d30-1e23-4a32-a6ce-d9bed6bb1b11', '8720169d-9b26-4e88-bb4b-f279c91b328e', 8, '100166983', '竜の巣', '尚文はガエリオンの追跡部隊を編成するが、その矢先にフィーロの体調が急変する。フィーロからは禍々しい力が溢れ、その力はガエリオンに流出しているおそれがあった。追跡を急ぐ尚文に、大きな決断の刻が迫る。', '2023/11/29 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/248f867c-2531-4b0b-b197-3440e1a25bf9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2faeaab-e3c1-4aa3-99e9-62b4144531bc', '8720169d-9b26-4e88-bb4b-f279c91b328e', 9, '100167752', '魔竜', '絶望的な状況の中で魔竜に攻撃を仕掛けたのはアトラだった。その攻撃は魔竜にも届くが、洞窟が半壊。尚文たちは濁流に飲まれてしまう。体勢を整える中、ウィンディアは父との暮らしを思い出し、ある事実に気づく。', '2023/12/06 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e15366d4-e24d-44a5-98f3-dfd00bb84745.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec869aba-9e72-408d-bbf9-b880f2820623', '8720169d-9b26-4e88-bb4b-f279c91b328e', 10, '100168601', 'パーフェクト=ハイド=ジャスティス', 'メルティとレベル上げがしたいフィーロと、仕事が山積みのメルティ。二人の事情を考慮した尚文は、ある宣言を行う。そんな中、今も地下賭博闘技場に出場するセインから、闘技場を渡り歩く弓使いの噂を聞かされる。', '2023/12/13 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de31a04d-fb52-4703-aafb-17067d4046b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b3c0c9d-ef24-4e57-8e8e-55f3fd579f2a', '8720169d-9b26-4e88-bb4b-f279c91b328e', 11, '100169268', '正義 VS 正義', '樹を救おうとまっすぐに対峙するリーシア。だが樹は聞く耳を持たず、その歪んだ正義は客席の尚文や子どもたちをも巻き込んでいく。リーシアは樹の掲げる正義を真っ向から否定し、命を賭して立ち向かおうとする。', '2023/12/20 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/065b9b96-535b-4730-b9e3-b15bf7bd7410.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af164cd8-37f6-4d8f-8899-5881d5664055', '8720169d-9b26-4e88-bb4b-f279c91b328e', 12, '100170179', '守るべき者達', '【シーズン3 最終話】エルハルトに頼んだ武具の修復が完了した。ラフタリアの巫女服も無事に戻ってくるが、サディナは血相を変えて巫女服を脱がそうとする。事情を説明しようとした瞬間、ラフタリアが着替えに入った家で大爆発が起こる。', '2023/12/27 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e60fc93a-bfbc-407f-8fe0-c587b2178a12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9f576cb4-eb8c-4718-a2b8-380232e03df6', '盾の勇者の成り上がり', '', 'hulu', 'the-rising-of-the-shield-hero-season-4', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1064120c-eea9-4057-a69f-7683e82cb449.jpg?w=331&h=447&p=t', 'hulu', 2019, 0, 1, 'FINISHED', NULL, 99263, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('bafcbd57-a003-4057-8952-318ea0e51486', '9f576cb4-eb8c-4718-a2b8-380232e03df6', 'hulu-the-rising-of-the-shield-hero-season-4-s1', 'シーズン4', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/821c748a-5863-4f89-b2e9-2e1663c86ec1.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d091ef9-f1d4-4b93-b66e-d6dc17fb0f56', 'bafcbd57-a003-4057-8952-318ea0e51486', 1, '100232549', 'シルトヴェルト', 'ラフタリアの暗殺を狙うクテンロウとの交渉に向け、尚文たちは唯一クテンロウへの連絡船が出る亜人の国シルトヴェルトへ旅立つ。だが、シルトヴェルトの民と権力者に熱烈に歓迎され、思わぬ足止めを喰らってしまう。', '2025/07/14 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/821c748a-5863-4f89-b2e9-2e1663c86ec1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('335dfaf5-332c-4be1-97c1-05905204ef90', 'bafcbd57-a003-4057-8952-318ea0e51486', 2, '100232908', '歓待', '神のごとき歓待を受ける尚文は、“ハーレム”という過剰なまでのサービスを押しつけられる。しかし船が用意される気配は一向になく、シルトヴェルトに不信感を募らせていく。そんな折、ジャラリスが接触してきて……。', '2025/07/21 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/521b499b-6b1b-4415-b323-374c133792dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('623bb913-fb23-44f0-af99-e50b2199c898', 'bafcbd57-a003-4057-8952-318ea0e51486', 3, '100233494', '真なる民とは', '朝食会場での毒混入騒動に揺れるシルトヴェルト城。各派閥の醜い舌戦に激昂したアトラが、重鎮たちを一喝し尚文の偉大さを高らか説こうとする。そして尚文は“密偵”を通じて、真犯人を突き止めるのだが……。', '2025/07/28 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0861f5e5-0d71-4aef-bf9d-1e050e18e54f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28a3f2da-9f0b-402b-8bb2-72f087c4e128', 'bafcbd57-a003-4057-8952-318ea0e51486', 4, '100234061', '託された力', 'フォウルは搦め手を使うジャラリスと、アトラは歴戦の猛者であるリケラスと対峙。強敵を相手にしながらも、二人は一切怯まずに立ち向かっていく。だが、フォウルがジャラリスの猛毒攻撃を食らってしまい……!?', '2025/08/04 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/347f742a-f767-4d90-8d80-9d3c54e75524.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45f808d8-33bf-42ed-a588-7c48192fc2f0', 'bafcbd57-a003-4057-8952-318ea0e51486', 5, '100234726', '白虎 (ハクコ)', '獣人化したフォウルがジャラリスとぶつかり合う。尚文たちは乱入してきたジャラリスの部下を抑えるが、ジャラリスは敗れた部下を喰らって異形化。追い詰められたフォウルは、尚文に強くなる“覚悟”を問われる。', '2025/08/11 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/613dc9db-196b-43a2-834d-80024f1d5350.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e668432c-24d9-4276-8b72-351b99decc20', 'bafcbd57-a003-4057-8952-318ea0e51486', 6, '100235148', '出港', 'ルロロナ村へ一時帰還した尚文は、村の戦力を再編しながらクテンロウ行きのメンバーを選定。“師匠”の手がかりを掴んだエルハルトも珍しく同行することに。無事に船出をするが、敵船に襲撃されてしまい……!?', '2025/08/18 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d9f20d7-e670-4fb5-896f-fbdd5d1be130.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dceeaa02-bfd9-4883-9398-d3741306e81b', 'bafcbd57-a003-4057-8952-318ea0e51486', 7, '100235521', 'クテンロウ上陸', 'クテンロウに潜入した尚文たちは、この国では動物の殺生が禁じられ、さらに民には重税が課せられていることを知る。この状況を逆手に取ろうとする尚文の前に、天命に不満を抱く革命派の者たちが接触してきて……。', '2025/08/25 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a39ef241-38aa-45d7-9d6c-a98244e387a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45a4763e-070a-4c32-bdc9-fe2bd510f381', 'bafcbd57-a003-4057-8952-318ea0e51486', 8, '100236114', '大蛇 (オロチ)', '現在地と首都の間にある「旧都」の制圧を提案するラルヴァ。進軍が決定した矢先、天命の祝福を受けていた「封じられしオロチ」が復活する。尚文のスキル「桜陣結界」でオロチの加護を無効化し、短期決戦を目指すのだが……。', '2025/09/01 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39bacc29-7d9f-488b-89d3-5537dd8438d4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40177d91-6637-46ae-975b-a648e679fde7', 'bafcbd57-a003-4057-8952-318ea0e51486', 9, '100237274', 'ゾディア', 'フィーロを“神鳥”として掲げ、旧都近郊をすんなり支配下に置く尚文たち。増援を待つ間、尚文とセインが天叢雲剣の状態を確認しに鍛冶場を訪れると、迷子の少女ゾディアが現れ、ムラマサが急に飲み会を提案し……!?', '2025/09/08 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50f654c2-d0b1-43e3-a7e3-c11b2bdbae1b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4092b625-61ee-4a8a-bcdf-1446a1422b8f', 'bafcbd57-a003-4057-8952-318ea0e51486', 10, '100237735', '祈り', '水竜の巫女シルディナとの会談に臨むラフタリア。シルディナから一時休戦を提案され、さらに講和に向けた天命との会談も用意するという。だが、彼女から提示された条件は、ラフタリアの覚悟を問うもので……。', '2025/09/15 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7889b34-5cdf-403f-8ef5-1f427485f9c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('317f46c1-eef7-45e6-9629-c174b29cd641', 'bafcbd57-a003-4057-8952-318ea0e51486', 11, '100238337', '神託の巫女', '旧都関所前に現れたシルディナは、戦の幕引きとして代表者による決闘を宣言。先代巫女のサディナを指名し、役割を押しつけられた恨み節をぶつける。飲み比べに、雷と風の激突に――。二人の決闘は混迷を極め……!?', '2025/09/22 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f3ffe85-408b-432c-b1d4-61670fbdfdb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f97a696-c539-473b-800e-e81edd37cc97', 'bafcbd57-a003-4057-8952-318ea0e51486', 12, '100238959', '天命の帰還', '【シーズン4 最終話】シルディナに乗り移った“過去の天命”がマキナに裁きを下す。亡霊となったマキナの抵抗に遭うが、尚文たちの連携で無力化。しかし、過去の天命はシルディナ解放の条件に、ラフタリアとの一騎打ちを迫り……!?', '2025/09/29 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7f0be9c3-3f9d-42b7-8b06-5049f3c813f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('34cb194f-bfca-4ae0-8d0c-f0a147d30678', '純潔のマリア', '', 'hulu', 'junketsu-no-maria', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6abb38d-9b8f-486c-8fe1-8059f20a0644.jpg?w=331&h=447&p=t', 'hulu', 2015, 0, 1, 'FINISHED', NULL, 20840, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('62916dd4-52b9-41ce-84fc-97f837dea878', '34cb194f-bfca-4ae0-8d0c-f0a147d30678', 'hulu-junketsu-no-maria-s1', 'シーズン1', 1, NULL, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('aadbeb7d-9509-4b47-97fe-3369f95cb46b', '処刑少女の生きる道（バージンロード）', '', 'hulu', 'the-executioner-and-her-way-of-life', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73bb560b-657a-4de6-8ade-d7a847226bff.jpg?w=331&h=447&p=t', 'hulu', 2022, 1, 1, 'FINISHED', NULL, 129193, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 'aadbeb7d-9509-4b47-97fe-3369f95cb46b', 'hulu-the-executioner-and-her-way-of-life-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14b8d2e6-5ce6-4208-a25c-70b16b4f3c48.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac541983-7c08-43dd-90ca-4be03fcd0c03', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 1, '100109072', '処刑人', 'かつて日本から現れ、この世界を滅ぼすほどの厄災をもたらしたと言われる《迷い人》。日本人の少年･ムトウミツキ、彼もこの世界に召喚された《迷い人》だ。グリザリカ王城に召喚され、「無能力」と判定されたミツキは、王城から追放されてしまう。ゆくあてもなく彷徨っていたミツキは、自分を保護してくれるという神官の少女･メノウと出会う。', '2022/04/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14b8d2e6-5ce6-4208-a25c-70b16b4f3c48.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42997556-2845-4c71-b9cb-1f6a15640398', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 2, '100109442', '迷い人', '主に仕える神官であると同時に、《迷い人》を殺す使命を担う《処刑人》･メノウ。ミツキと同時に、アカリというもう一人の異世界人が召喚されていることを知る。メノウの後輩で《処刑人補佐》のモモもサポートに加わり、王城への潜入に成功。安心させるような演技でアカリに近づき、アカリの処刑を試みるが……。', '2022/04/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38781423-71e3-45f3-a74d-5b9050a1ba4c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfc0972a-3398-47d5-a3ae-412c42728395', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 3, '100109996', '禁忌の【赤】', '確実に殺したはずのアカリは、彼女の持つ謎の能力により復活してしまう。実質不死身であるアカリの、その能力が暴走する前に仕留めなければと焦るメノウは、アカリを連れガルムにある異世界人討滅のための儀式場へと向かう。だが、その車中、謎のテロリストの襲撃を受ける…。そんな中、同列車の貴賓車両には、グリザリカ王女、アーシュナの姿があった。', '2022/04/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b02c076-1ae8-46fd-8db4-a9e5b6d90238.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f027e380-1db9-41c9-92c8-136afe126884', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 4, '100110690', '古都ガルム', 'テロリストの襲撃によって制御弁が破壊され、暴走する列車。このままでは大惨事になりかねないと、アカリと導力を接続して列車を止めることに成功。その際、アカリの能力を再び目撃したメノウは、彼女の持つ能力が【時】の純粋概念だと確信する。そして、無事にガルムについたふたりは、大司教オーウェルと対顔する。', '2022/04/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3fe39f1-5082-4030-8e24-82dc4c9286b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5fc66a25-43b9-4fef-ad9c-00f41de84148', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 5, '100110691', 'さよなら', 'オーウェルから、ガルムで起こっている「女性連続行方不明事件」の調査依頼を受けるメノウ。ガルムの街を観光したいというアカリのため、モモに調査の代行を依頼。旧王城地下を調査するモモは、またもやあの厄介な姫騎士に遭遇してしまう…。一方、日本に帰ることができると思いこんでいるアカリは、メノウに別れを告げていた。', '2022/05/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fd0b857-996b-4d96-8249-f3de48bb1678.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0444f963-1438-4af2-95c9-9a0cec5d96e5', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 6, '100111375', '【回帰:記憶･魂･精神】', '旧王城地下に、異世界人召喚のための転移術式を発見したモモとアーシュナ。第一身分 (ファウスト) しか知るはずのないこの転移術式が王城地下にあったことから、この一連の事件の首謀者は、大司教オーウェルだという真相にたどり着く。メノウは、自らの若返りのためだけに【禁忌】を犯したオーウェルと対峙する。', '2022/05/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/034a575a-5b27-45dc-b5dd-ee7ca775c01e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6176336-405e-455e-8046-b37a17638ad6', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 7, '100112017', '港町リベール', '激しい戦いの末、オーウェルの打倒に成功したメノウは、アカリを確実に殺しきる方法を見つけるために、彼女を連れて旅に出ることを決意する。そして、旅の途中、「港町リベール」にたどり着く。そこには、四大人災 (ヒューマン･エラー) を封じ込めた霧の牢獄、「霧魔殿 (パンデモニウム)」が存在した。', '2022/05/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7bbce95-4360-4b46-afe2-3769b86b1388.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0906cdfa-7de5-475b-9eee-100ef7611059', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 8, '100112574', '魔薬', '霧の牢獄、「霧魔殿 (パンデモニウム)」にアカリを閉じ込めて殺す方法を試みるメノウだったが、アカリの純粋概念によりまたもや失敗に終わってしまう。今後の旅費の申請を行うためにリベールの街に立ち寄ったメノウは、道中、第四 (フォース) の襲撃を受ける…。その様子を、和服の少女の影が覗いていた――。', '2022/05/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84873356-6858-4d66-948e-a9530ae57e36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ef8be52-8c64-4b36-823f-f728cc9612bc', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 9, '100113391', '夜会にて', 'リベール当主代理、マノン･リベールを筆頭に、「自由」な第四の身分を主張する･フォース。彼らは【禁忌】とされる魔薬の流通に手を染めていた。その調査のため、メノウはアカリと共にマノン･リベール主催の夜会に潜入する。一方、メノウ達とは別ルートで調査に潜入していたモモに、魔の手が迫っていた…。事態は急展開を迎える――。', '2022/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dcaf4815-c0f4-45cc-a582-427a78159256.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ad1b7d8-54d4-4f0d-a896-ed3751cef4e7', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 10, '100114131', '迷い人の娘', '魔薬の生産にマノン･リベールが関わっている証拠を掴んだモモだったが、あと一歩のところで敵の罠により瀕死の重症を負ってしまう。そんな中、アカリはたったひとりでマノン･リベールと対峙し、マノンとこの街の謎について迫ろうとしていた。', '2022/06/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0d5400e-dd9b-406a-92ad-8462c207dfea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fc5490f-a477-4245-b811-0010e58050c5', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 11, '100114705', '万魔殿 (パンデモニウム)', 'マノン･リベールの体内から出現した、明るく元気で血まみれななんとも不気味なその幼女は、歌と踊りと映画が好きと言い、そして、自らを「万魔殿 (パンデモニウム)」と名乗った。【魔】の生贄にされた人々を目の当たりにしたアーシュナも、メノウと共に戦闘を開始する。四大人災 (ヒューマン･エラー)、【魔】。過去最大の厄災のうちのひとつが、メノウたちを襲う――。', '2022/06/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80ba3af6-1769-4509-a326-29c91ba3dec9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d02ed94e-adf8-42e4-9b26-f2f681e3977b', '86e4a65b-c2d4-42b9-a9ac-5b34e7784833', 12, '100115358', 'ふたりの旅路', '【最終話】封印に成功したと安堵したのも束の間、おぞましい巨大な化物に変身し、再びメノウ達の前に現れた万魔殿 (パンデモニウム)。激闘の最中、自らの武器である経典と短剣を飲み込まれ、最悪の事態に追い込まれたメノウ。窮地に立たされた《処刑人》の少女は、襲い掛かる【魔】の小指に、最後の戦いを挑む。', '2022/06/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b862f814-65d7-4c62-9d47-8d58c5107fb7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4580f787-e696-40c6-8924-4524bffa6a96', '女子高生の無駄づかい', '', 'hulu', 'jyoshimuda', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2da7ab37-91d6-4d58-9f54-5e8da92d7989.jpg?w=331&h=447&p=t', 'hulu', 2019, 2, 1, 'FINISHED', NULL, 105081, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('964e58f5-605b-4bce-9fc8-513d19836320', '4580f787-e696-40c6-8924-4524bffa6a96', 'hulu-jyoshimuda-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b92a738-4f01-41a0-9ea9-76f368a4dfb5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb863091-07dc-4653-a2b6-c9a01791aba9', '964e58f5-605b-4bce-9fc8-513d19836320', 1, '100038597', 'すごい', 'かつてとあることをきっかけに何となく疎遠になってしまっていた田中、菊池、鷺宮の三人は、偶然にも同じ高校に進学したことによって再会を果たす。久しぶりに会う旧友を前に、ぎこちなさを隠せない菊池だったが、昔と何一つ変わらない田中と鷺宮のやりとりを見ているうちに、自然とツッコミを入れてしまう。クラス分けでも同じクラスになった三人は、そのまま入学式に出るが、途中から何やら落ち着かない様子の田中。入学式を終えて、教室へと向かう途中で、田中は取り返しのつかない失敗をしてしまったと話し始める。', '2019/07/12 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b92a738-4f01-41a0-9ea9-76f368a4dfb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a149116-46f4-4480-9339-3b768047cad5', '964e58f5-605b-4bce-9fc8-513d19836320', 2, '100039325', 'まんが', 'クラス全員にあだ名をつけるという田中の試みによって、菊池はヲタ、鷺宮はロボ、そして田中自身はバカというあだ名が定着したある日の日曜日。ヲタはベッドに寝転びながら、低所得Pの新曲を聞いたり、アニメを観てみたり、漫画を読んでみたりと、週末を満喫していた。バカから暇過ぎるからという理由で、大量に送られてくる自撮り写真を完全に無視して、趣味を謳歌するヲタは、いつか自分も有名になって夢の印税生活をしてやると奮起し、描きかけで止まっていた自らの漫画を描き始める。', '2019/07/19 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4a4b83b-47bf-4777-9f74-493107ef0823.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('335a1dbc-9301-4249-b376-fba758bed487', '964e58f5-605b-4bce-9fc8-513d19836320', 3, '100039584', 'わすれもの', '百井咲久は、その可愛らしい見た目から、周囲にいつも小さくて可愛いと言われ続けてきた。自分の容姿にコンプレックスを抱き、グレてやるとまるで尖ったナイフのように生きているのにも関わらず、周囲の反応は変わらない。そしてバカにロリというあだ名をつけられてしまい、事あるごとにあだ名を連呼されることに怒ったロリは、もうバカとは口を聞いてやらないと宣言するが、バカの巧みな誘導によって、つい返事をしてしまう。さらにはバカの嘘にまんまと騙されてしまい、ロリはバカに対して最高の悪口を言うのだが…。', '2019/07/26 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/367b118d-d172-4e5a-81b2-139d9ddbca15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd54dc53-1998-4194-8f79-525f372c32b2', '964e58f5-605b-4bce-9fc8-513d19836320', 4, '100039866', 'まじめ', '高校受験当日、高熱をはじめあらゆる体調不良によって、志望していた高校に落ちてしまい、さいのたま女子高校に入学することになったマジメこと一奏。辛い3年間が始まると落ち込んでいたマジメだったが、入学式のクラス分けが貼られた掲示板に、ずっと憧れていた鷺宮しおりの名前を見つけ、奇跡が起きたと喜ぶ。しかし、そんな喜びも束の間、中学では一度として崩れなかったロボの表情が、バカによっていとも簡単に崩されてしまったのを見て、衝撃を受けるマジメ。マジメはどうにかロボとお近づきになろうと、バカの観察を始めるのだが…。', '2019/08/02 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f3958382-2905-43dd-a422-a16dd11f8057.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('465e65a6-fc7b-4a44-8aa9-c9bde1284fbc', '964e58f5-605b-4bce-9fc8-513d19836320', 5, '100040055', 'りりぃ', 'バカたちのクラスに転入生がやってきた。転入生の名前は染谷リリィ。さらさらのロングヘア、ぱっちりとした大きな瞳、瑞々しくぷるんとした唇、扇情的な隆起を描く豊かな胸、きゅっとした細い腰に、すらりとした長い足、そして透き通るような白い肌という、リリィの完璧な美少女ぶりを見て、ヲタは思わず格差社会かと叫んでしまう。リリィはにっこりと微笑んで、自己紹介をするのだが、その内容が好き嫌いのくだりに入ったとき、その可憐な容姿からは想像もつかない斜め上の言葉が次々と飛び出していき…。', '2019/08/09 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55010e4e-cb5b-475c-8176-7958c6da865e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28663a56-c148-4b3f-8e25-678898298d4a', '964e58f5-605b-4bce-9fc8-513d19836320', 6, '100040792', 'まじょ', 'ファミレスで、いつものようにバカのすごい話を聞いていたヲタとロボ。そんな三人に久条琥珀という見知らぬ少女が話しかけてくる。琥珀の話によると、双子の姉である翡翠が、バカたちと同じさいのたま女子高校に通っているのだが、とある事情で数えるほどしか学校に行っていないらしい。このままでは出席日数が足りずに、退学処分になってしまうかもしれない。翡翠にどうにか学校に通ってもらうため、バカたちに翡翠と友達になって欲しいという。話を聞いたバカたちは、快く友達になることを引き受けるのだが…。', '2019/08/16 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/288b68de-7bbc-4a2b-8cff-5441f5573ec4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84a0aa8b-f273-42a6-a100-3063119f987f', '964e58f5-605b-4bce-9fc8-513d19836320', 7, '100041193', 'やまい', '屋上の給水タンクの上に座って、人間はもっとプライドを持たなければならないとつぶやくヤマイ。そんなヤマイに話があるから降りてこいと言うワセダだったが、ヤマイはワセダの言葉には屈しないと返す。しかし、ワセダが内緒で饅頭を一つやろうと言うと、あっさりと降りていき、いつものごとく進路指導室へと連れて行かれる。ワセダはヤマイの包帯がいつもに増して多いことを心配していて、いったい何があったんだと問いかけるが、ヤマイは大したことじゃないから案じるなと反論し…。', '2019/08/23 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25241b5e-4447-4d30-8d58-358afc91d745.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb716caf-5f74-4b7e-a6f4-3f30df55fe8d', '964e58f5-605b-4bce-9fc8-513d19836320', 8, '100041550', 'みずぎかい', 'ある夏の昼下がり、ファミレスに集まっていたバカ、ヲタ、ロボの三人。するとバカが、もしかして人生で一度きりの16歳の夏休みを無駄に過ごしている自分たちは、ものすごい贅沢をしているのではないかと話し始め、さらに女子高生が水着で武装すれば無敵じゃないかと語る。このあたりに海はないと返すヲタに、電車に乗ればすぐ海に行けるし、なんだったら海外でもと言うバカ。すかさずそんな金はないとヲタに一刀両断されるバカだったが、都合良く福引きで特賞が当たるなんてこともあるかもしれないと言い、三人は量販店に向かう。', '2019/08/30 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ddac27eb-6165-4745-a9a9-a49677cbe0b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a395a024-f9b2-4360-a174-cbf1b2ca6089', '964e58f5-605b-4bce-9fc8-513d19836320', 9, '100041872', 'おしゃれ', 'ある日、スーパーで買い物を終えたロリは、帰り道で同級生をいじめている小学生たちを見かける。彼らにいじめをやめるように注意をするロリだったが、小学生たちは言うことを聞くようなそぶりもなく、ロリに対してどこの小学校に通っているんだと凄む始末。小学生に間違われたことに憤慨し、自分が高校生であると主張するロリ。しかし、小学生たちはロリの言うことをまるで信じようとしない。高校生ならもっと胸が大きいはずだと言われたロリはショックのあまり、買い物袋を落としてしまい…。', '2019/09/06 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b551db9d-95de-48d6-9152-3233a0813c2a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c51d057-792f-4dd6-a09d-9fad9ac74a8a', '964e58f5-605b-4bce-9fc8-513d19836320', 10, '100042235', 'ろぼ', '廊下の掲示板に張り出された2年生に進級したときのコース分け。事前に文系か理系かを選択し、そこには選んだほうが記載されているはずにも関わらず、バカのところには未定と書かれていた。まだ進路希望の紙を提出してなかったのかと聞くヲタに対して、ちゃんと出したはずと答えるバカだったが、そこにワセダが現れ、お前は進路希望を意味を理解していないと、バカを進路指導室へと連れていく。進路指導室から教室に戻り、貴重な休み時間が減ったと喚くバカに呆れるヲタ。そしてふとしたことからバカとヲタの喧嘩が始まってしまい…。', '2019/09/13 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f447cc7-c451-485d-9adb-6dc3f3f67c72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('86700d8e-7921-4b94-aab4-7dfb3d6a6c56', '964e58f5-605b-4bce-9fc8-513d19836320', 11, '100042551', 'ゆめ', '年末が近づいたある日、机に向かって漫画を描いていたヲタだったが、中々アイディアが浮かばずスランプに陥ってしまう。気分転換をするために、低所得Pの楽曲を聞き始めたヲタは、こんなに素敵な曲をどうやって作っているのか、作っている人はどんな人なのだろうと恋にも似た思いを馳せる。どうにかしてこの熱い思いを届ける方法はないかと考えているうちに、ヲタはかつて歌ってみたをやるために、機材一式を買い揃えていたことを思い出す。一度は難しくて挫折してしまった歌ってみただったが、低所得Pに気持ちを伝えるため、ヲタは再び歌い始める。', '2019/09/20 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39c141d7-81bd-4b9c-ae19-d59e95bc66c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e1d5bc9-0cf1-49d8-8b7b-0a33928ca025', '964e58f5-605b-4bce-9fc8-513d19836320', 12, '100042837', 'なかま', '【シーズン1 最終話】年明け早々にワセダから、今度の期末で相当頑張らないと留年してしまうことを宣告されたバカ。どうやら1教科でも赤点を取ったら本当に留年してしまうらしい。落ち込むこともなく笑いながら、ワセダから留年するかもしれないと言われたことをヲタやロボに話すバカに対して、ヲタは一つも笑えないと返す。さらにマジョからも占いの結果が良くないことを示していたと言われるが、どこ吹く風のバカ。どうやら以前からとっておきの勉強法を実践しているから、何の心配もないと言うのだが…。', '2019/09/27 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/463734bf-6ea2-4125-b924-8bc7ec75816f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4138a239-31d5-4b59-a08c-5f464809b4f2', '女神のカフェテラス', '', 'hulu', 'goddess-cafe-terrace', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84b96045-c8dd-488a-9bf2-badb0b59e7c4.jpg?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 154412, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6c8900fd-7a9c-4709-aefb-db6d185b42a0', '4138a239-31d5-4b59-a08c-5f464809b4f2', 'hulu-goddess-cafe-terrace-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/317298a7-2b6f-4104-8af1-e8be3f070e03.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2758b7a-9ded-4a84-bff5-9f88c5ff2278', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 1, '100143136', 'ファミリア', '東大現役合格をした男子学生･粕壁隼は、亡くなった祖母が営んでいた喫茶店「Familia」を畳むため、3年ぶりに店を訪れる。しかし、そこには祖母が住み込みで雇っていた5人の女の子たちが暮らしていた。5人は店を潰させないように、あの手この手で隼を陥落させようとする。赤字まみれの喫茶店はあるだけ無駄だと考えていた隼だったが、彼女たちと接するうちに、昔のことを思い出し…。', '2023/04/13 02:55:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/317298a7-2b6f-4104-8af1-e8be3f070e03.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('569cf299-5f88-42d6-8086-601d01be9438', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 2, '100143740', 'おばあちゃんとの約束', '亡くなった祖母の店･喫茶店「Familia」を立て直すことを決意した隼。なし崩し的に、住み込みバイトの5人との共同生活も始まったのだが、女5人に男1人の中で、初日からトラブルばかり。肝心の経営もうまくいかず、コーヒーの腕もイマイチ。5人のバイトたちから時に優しく、時に厳しく諭され、隼は今の自分には足りないものが多いと気づいていき…。', '2023/04/20 02:55:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f55f26e7-bcea-4fd1-8693-19f2ce5dd4e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16d74afe-7b59-43ab-8932-4164834e9022', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 3, '100144391', '開店!', 'コーヒーの練習や近所への挨拶回りを終え、そろそろ喫茶店をリニューアルオープンしようという矢先、隼は流星から「桜花と仲良くしろ」と指摘される。5人の中でも1番反発していた桜花との関係を改善しようとアプローチを試みる隼だったが、店の制服に着替えた桜花を褒めると、意外な反応が? そしてついに、喫茶店「Familia」の再オープンの日が訪れる…。', '2023/04/27 02:55:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e012fae-b359-43f2-8aac-66eefc85fdab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02a65ebe-1592-4b9f-a9e7-81b3dba352b4', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 4, '100144752', '桜まつり!', 'ハプニングだらけのオープン初日を乗り越え、1週間が経過。最初の勢いも徐々に失いつつある現状を打破するべく、隼は近々開催される「桜まつり」での売り込みを狙う。そのプランとは、店のメンバーを二分し、別動隊として出店を計画すること。5人の協力や近所のみんなからの助力もあり、順調な滑り出しを迎えるが、桜花に声をかけたナンパ男たちがトラブルを起こし…。', '2023/05/04 02:55:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8cfa300-db7b-4db8-8b24-74804fdefec5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a967c449-aa35-4ae3-ab5f-7cfbe180b245', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 5, '100145636', '定休日', '「桜まつり」への出店が功を奏し、喫茶店「Familia」の経営もようやく軌道に乗ってきた中、人一倍忙しそうに働いている流星。夜もSNSで店の宣伝をするなど、どこか無理をしている様子の流星を見かねて、隼は声を掛ける。また別の日、店の定休日に街へ買い物に来ていた隼は、たまたま前を通りかかったライブハウスで紅葉のバンドがライブをすることを知り…。', '2023/05/11 02:55:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e607b6f-ee9a-484a-8bcb-365aede5ade6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b53b131-8764-4183-abfb-4533c0b62131', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 6, '100145967', '2か月!', 'キッチンで仲良さそうに話す隼と白菊を見つめている流星は、モヤモヤするよく分からない感情を抱いていた。そんな白菊と流星によるトーストサンド対決が突然始まり…。一方、普段はうるさいくらいの秋水が大人しい。不審に思ったみんなは、原因を突き止めようと試行錯誤する。そんな賑やかなメンバーと共に、騒がしい日々を過ごしていた隼だったが、いつの間にか、家族と従業員の境界を忘れ、甘えていたのではないかと気づいてしまい…。', '2023/05/18 02:55:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f23a94f8-da4e-4acb-973f-528b3c5422f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45beddd1-0430-41c9-be7c-c3de9d7049fe', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 7, '100146716', 'アタシの1年', '紅葉の物憂げな様子に、何かあったのではないかと察する隼は、店を辞めるつもりなのではないかと、本人に直接尋ねる。何かを諦めたかのような紅葉の表情を見た隼は、最後のデートと称し、紅葉が愛する祖母直伝のコーヒーの淹れ方を教わる。理由を何も聞かない隼に、本当の家族ではないことを思い出してしまい、何も言えなくなる紅葉。そんな彼女が淹れたコーヒーを飲みながら、隼が口にした言葉は…。', '2023/05/25 02:55:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5fabeba-0f37-4c4b-89aa-3d16b9ab2b3c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae5529dd-e13b-445d-87bf-2b33f2831a19', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 8, '100147781', '海の家!', '紅葉の母親の説得にも成功し、現状を守ることに成功した隼だったが、喫茶店「Familia」の人間関係は少しずつ、だが確実に変化しつつあった。そんな中、季節は夏本番に突入し、喫茶店「Familia」をさらに盛り上げるべく、隼は本店と並行して海の家をオープンする計画を立案する。夏の陽気と忙しさに浮足立つ6人。そしていよいよ始まった海の家で、いつも以上に張り切ってしまった流星が、突然倒れてしまい…。', '2023/06/01 02:55:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dacfc75c-274b-4a32-9307-06e9eb1c804a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('434b9f5b-a657-48b3-b89d-8f5b8e534151', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 9, '100148310', '流星と、その過去', '熱中症で倒れてしまったものの、隼の迅速な対応ですっかり回復した流星。海の家作戦も予想以上の賑わいを見せ、嬉しい悲鳴があがるばかり。隼も、みんなと少しずつ本音で話せるようになってきたと思った矢先、喫茶店「Familia」の海の家に、テレビ局のクルーが取材に訪れる。ディレクターの男性は、どうやら流星を知っているらしく思わぬ再会をきっかけに、今まで誰にも話そうとしなかった流星の過去が明かされる…。', '2023/06/08 02:55:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bc86c67-fb5c-4729-9dcb-9bfff28e8c7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f47c073a-50a1-4963-aec9-fa4df6d81de4', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 10, '100148984', '桜花と橘花', 'いつも通り無邪気にからもうとする秋水を、突然冷たい言葉で突き放す桜花。明らかに様子がおかしいと隼に泣きついた秋水だったが、その正体は、桜花の双子の妹である橘花だった。その後、家を訪れた橘花は、「Familia」の他の面々にも、辛らつな言葉を投げつけ、桜花と喧嘩になってしまう。隼はまた面倒なことになったとぼやきつつも、彼女が訪れた理由を探るうちに、2人の関係の複雑さと、秘密を知ることとなり…。', '2023/06/15 02:55:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5de3b6bf-f563-47e4-a97f-d1156b6b9306.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('506e9e55-9e37-49ff-b893-0509c8eb0ebd', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 11, '100149595', '恋の火花', '「Familia」の庭で、花火をしながら夏を振り返る、隼と5人。色々なことがあった夏の間に、隼との関係が深まっていた。そんなある日、家の風呂釜が壊れてしまったため、6人は町の銭湯へと足を運ぶ。開放的になった女子5人は、たまたま居合わせた和菓子屋のおばちゃんの「隼くんのこと、どう思ってるの?」という問いに、それぞれの答えを返すが、なかなか素直になれない流星に、紅葉が意外な言葉をかける…。', '2023/06/22 02:55:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0540576-4538-4ed7-aec2-51ab2f477209.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('499c83e7-a11a-495b-9f91-3bd6678a6261', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 12, '100150572', '二つの出会い', 'お互いの本音･隼への恋心をさらけ出し、ライバル宣言をした流星と紅葉。一方、喫茶店「Familia」の新メニューを開発しようと意気込む隼は、白菊と共に試行錯誤を重ねる。そんな中、2人が近所のお店仲間の面々と店のメニューについて相談していると、魚屋のおじさんが、祖母との思わぬ思い出を口にする。その言葉に反応する白菊の様子に、隼は何かを確信し、白菊が語る、過去にあった“ある出会い”を知る。', '2023/06/29 02:55:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78bb6873-e900-4ac4-9d2c-169183db0b40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b342e793-d1ee-467a-a662-8ef0591eb3f2', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 13, '100190268', 'ファミリアに黒い影', '隼に自分の気持ちを伝えた紅葉と白菊は好意を隠せなくなり、「Familia」の営業中でも隼と身体の距離が自然と近くなってしまう。店の風紀を心配する桜花は紅葉と白菊に注意するが、2人は素直に認めようとしない。さらに流星が隼への恋心を桜花たちの前で打ち明け、桜花は「Familia」の人間関係に思い悩む。妹の橘花にそのことを相談するが、橘花からは自分の中にある隼への感情を指摘されてしまう。', '2024/07/10 01:26:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5b3aa44-3dda-4afd-8cd3-dd70f1c26929.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f973c8d-c25d-4674-9f81-64d078731f3a', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 14, '100191074', '青天の霹靂', '娘を案じる桜花の父から幕澤家に招かれた隼。そこで対面した桜花の祖母･春恵は隼の顔を見て涙を流す。かつて春恵は、隼の祖父･大洋が営んでいた喫茶店で働いていたのだという。春恵の話から今の「Familia」で働く6人の祖母が大洋の店で働いていたことに気付いた桜花は、これが単なる偶然なのか疑念を抱く。そんな中、「Familia」の隣に不破が経営するカフェレストラン「Family」がオープンするとの報せが…。', '2024/07/17 01:26:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c07c3e13-3782-4297-8aec-fe6d36f0ca90.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('704a6255-d11c-4c8d-b9ea-c8db4ef66978', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 15, '100191680', '反撃の一手', '不破が「Familia」を潰すためオープンさせた「Family」に対抗するべく、ハロウィンに合わせた新衣装と、目玉となる新メニューの展開を考える隼たち。幸子が作っていた料理に手を加えたくない白菊は、メニュー作りに難航していたが、隼の言葉で吹っ切れ自分ならではの渾身の逸品を作り上げる。そんな白菊の背中を見た流星も、自分にしかできないやり方で「Familia」の力になろうと考える。', '2024/07/24 01:26:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/987d660a-22f2-4907-bc66-3d17aa03d1c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfb9ab0f-dcfd-4cda-9754-95bb5104b73f', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 16, '100192667', '男女11人共同生活', '莉々歌が配信を切り忘れていたことで致命的な悪評を被った「Family」。激怒した不破はカフェレストランを閉店させ、働いていた5人を住む場所からも追い出してしまう。莉々歌から事情を聴いた流星は、行き場所を失った彼女たちを「Familia」に住まわせてくれるよう隼に頼み込む。「Familia」の5人を迎え入れた祖母のことがよぎる隼は、不承不承ながらそれを受け入れるのだった。', '2024/07/31 01:26:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcbef60e-41b0-48e9-8596-9c5cc795c914.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7820245a-0dcd-4067-9272-9f44c8721c0c', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 17, '100193818', '温泉旅行 ファミリア御一行様', '隼の支援を受け、カフェレストラン「Family」は定食屋「千代田食堂」として再始動した。プレオープンに招かれ、萌美の料理に舌鼓を打つ隼たち。帰り際、流星は莉々歌から隼と行くようにと温泉旅館のペア宿泊券を渡される。隼と2人きりとなり、勇気を出して旅行に誘う流星だが、及び腰な態度の隼。そんな中、商店街のくじ引きでそれぞれ温泉旅行のペアチケットを当てた桜花と白菊が帰ってきて…。', '2024/08/07 01:26:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8fca5994-29e8-4df3-82b2-4514b176e624.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aea552f8-8c05-4b05-8fdd-c4ea340798a6', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 18, '100194399', '怖い夢の終わり', '病気によって自分のことを忘れてしまった祖母の勝代と、再び向き合う決意をした秋水。普段の明るさを取り戻して勝代が暮らす施設へと向かった秋水だが、久しぶりに再会した勝代の様子は、突き放すかのように無表情のまま変わらない。それを受け止められずに泣き崩れてしまう秋水に代わって勝代の前に立った隼は、昨晩夢に現れた祖父の大洋と同じ言葉で呼び掛ける。', '2024/08/14 01:26:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1426ab43-f169-4a9f-9136-6595b8eeeae4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2aaf7c7f-afec-4f31-b9f6-51441da46d1e', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 19, '100195254', '眠らせない夜', '秋水が祖母のもとに一晩残ることになり、旅先でもう一泊していくことになった「Familia」の5人。しかし見つかった宿泊先は見るからに怪しい古旅館。一刻も早く眠りにつこうとする隼だが、紅葉や白菊が引き起こす騒ぎに巻き込まれて中々休むことができない。やっと夜が明けてみんなが目覚める中、眠り続ける隼を起こそうとした桜花は衝撃的なモノを目撃してしまう。', '2024/08/21 01:26:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69c5bfc3-56a8-4ced-906d-f2264ee0a4dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c5cb4b7-d10a-45dc-8754-a744d558ac33', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 20, '100195892', '冗談なんかじゃない', 'ライバル店となる「Family」のオープンや温泉旅行など様々な出来事があり、白菊の誕生日を3週間も過ぎていたことを思い出す隼。遅ればせながらも誕生日を祝うため、紅葉とともにプレゼント選びで合羽橋を訪れる。紅葉のアドバイスでプレゼントを決めた隼だったが、帰り際に今日が紅葉の誕生日だったことに気が付く。お詫びとしてなにかプレゼントをさせてほしいと告げる隼に、紅葉はあるお願いをしてきて…?', '2024/08/28 01:26:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/643eb6ca-5afd-4821-96e7-a6f4e097c902.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0527cac3-71c1-4a7c-84d8-3a55e966e2c0', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 21, '100196666', '母と娘', '馴染みのディレクターである野村から、流星にドラマ出演のオファーが届く。莉々歌の後押しもあって出演を決めた流星だったが、配役は元天才子役という設定の死体役だった。一方ドラマロケで流星のいない「Familia」に、全身黒づくめにサングラスの男が訪れる。6時間も1人で居座り続け、不審な素振りをみせたため秋水に撃退されるものの、丁度帰宅した流星は伸びた男の素顔を見て…。', '2024/09/04 01:26:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c713a74-9247-4ffb-b343-4cb58d7b76cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e2b38f0-6185-4800-8e54-6792187140f3', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 22, '100197847', 'クリスマスパーティー!', '「Familia」と「千代田食堂」による合同のクリスマスパーティーを開くことにした隼たち。パーティーを前にして流星は莉々歌に、紅葉は碧流に、白菊は萌美に、それぞれ隼との関係について進捗を聞かれるが、3人とも進展がないことに気付いて焦りを抱く。初めて大勢でクリスマスを迎えることになった隼がささやかに楽しみにしていたパーティーは、凄絶な「隼争奪戦」に変わろうとしていた。', '2024/09/11 01:26:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9985d43-55d3-4d0c-8fc4-a075f07b8c53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57cfc4f5-91a2-4c24-9556-ab4933171766', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 23, '100198851', 'キスとスキと考えごと', '白菊が隼にキスをした事件についての裁判の結果、「Familia」の他の4人にも隼とキスをする権利が与えられることに。ピンと来ない秋水と固辞する桜花を後目に、紅葉はみんなの前で見せつけるようにして隼の唇を奪う。それに触発された流星は、理想のシチュエーションでキスをするため隼を外へと連れ出す。しかし、あくまで隼の方からからキスをしてもらいたい流星の願いは中々叶わず…。', '2024/09/18 01:26:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68578650-3436-4e2a-a4ee-abf4eb5eb257.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e86a46e-1056-489f-8fa2-d4bbca07b205', '6c8900fd-7a9c-4709-aefb-db6d185b42a0', 24, '100199682', '最後のピラフ', '【シーズン1 最終話】初詣から戻り、「千代田食堂」から届いたおせちを囲む隼と5人。成人した紅葉も酒宴に加わり、元旦はいつも以上に賑やかに過ぎていく。新年を迎え、みんなの前で東大を退学して正式に「Familia」を継ぐことを宣言する隼。それを聞いた桜花は、3月からフランスのファッションブランドで働くために、1月いっぱいで「Familia」を去っていくことを告げる。突然訪れた桜花との別れに隼と4人は…!?', '2024/09/25 01:26:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb622546-5370-4614-97fe-ccb04530f1a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('778473fd-e4a5-45f0-8524-490822f4e5cd', '女神降臨', '', 'hulu', 'true-beauty', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a025cce0-8f04-4ab1-9640-12bababdda54.jpg?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'FINISHED', NULL, 152184, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c3f48bf2-1417-454f-9acc-61ec9186b8cd', '傷だらけ聖女より報復をこめて', '', 'hulu', 'kizudarakeseijo-yori-houfuku-wo-komete', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a33f13d-45d4-40ba-a321-435c25dfc737.jpg?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 195209, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 'c3f48bf2-1417-454f-9acc-61ec9186b8cd', 'hulu-kizudarakeseijo-yori-houfuku-wo-komete-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2275c2a-4f55-402c-8609-c72a5e33bb40.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab9cd765-2a13-4e34-9777-c1be30c5188e', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 1, '100232608', '傷だらけ聖女', '欠陥聖女と呼ばれるルーアは、思い人であるガロットを命懸けで救う。だが功績は親友･アリアンに奪われ、2人は婚約。全てを失ったルーアは、信じていた者たちへの報復を誓う。', '2025/07/13 12:00:00', 870, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2275c2a-4f55-402c-8609-c72a5e33bb40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eca1a2fe-3fc7-4c6a-aca2-ca3db2648fb8', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 2, '100232900', '神殿の闇', 'アリアンに裏切られたルーアのもとに現れたのは第二王子スウェンだった。復讐をもちかけるスウェンから、ルーアは驚くべき神殿の闇を聞かされる。', '2025/07/20 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6260b5e-09e3-4a84-9daa-2cbbb50a1363.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('726115eb-3fed-4763-8b78-f331607edb4c', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 3, '100233396', '怪しい人影', '神官長の秘密を探るため、王宮の書館でユアン族の情報を調べるルーア。その夜、神官長とユアン族、アリアンの密談現場を目撃してしまい…!?', '2025/07/27 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/260d05f7-b286-4d46-b11b-a1a3f872aa32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fe746c2-2dcf-4b70-a863-42bc2a67ba45', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 4, '100233880', '女たらし子爵', 'スウェンと手を組んだルーア。スウェンは二人でデドモンド子爵の舞踏会へ潜入し、悪事の証拠を掴むことを提案する。一方、アリアンもガロットとともに舞踏会へ行く計画を立てていた。', '2025/08/03 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fc033b8-9e87-40ff-9a92-e66b8448f4e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5291b81f-58bc-4b37-93f2-a69f3521428d', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 5, '100234651', '舞踏会へ', 'スウェンから贈られたドレスを身に着け、共に舞踏会へ潜入するルーア。デドモンドへ接近しようとするが、そこに現れたのはアリアンとガロットだった。', '2025/08/10 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c675479-8d9c-49c1-8456-fd9c6c4d89f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('490d95fe-cff5-4ba6-8b34-6556a3166143', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 6, '100235115', 'デドモンドの悪業', '舞踏会場で挙動不審な侍女を見かけたルーアとスウェン。侍女を会場から連れ出して事情を聞く二人は、デドモンドが過去に行った卑劣な所業を聞かされる。', '2025/08/17 12:00:00', 870, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c58bbb1-5f29-4953-beec-6fcd223674a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9386d5a1-97f1-4957-b073-deaa0b7efc65', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 7, '100235427', '過去の出会い', '自身の過去に思いを馳せるスウェンは、次第にルーアに対する想いを募らせていく。一方、デドモンドとの接触に成功したルーアは、単身でデドモンドの自室に向かった。', '2025/08/24 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2725865f-fdb2-427b-99ea-2b17ceba7dc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f7c669e-88c3-44e1-ab1c-b1735bd6da32', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 8, '100236028', '命か金か', '寝室でデドモンドと接触するルーア。聖女の能力で彼を追い詰め、悪事の証拠を掴もうとする。一方、待機していたシジーはアリアンと不審な男の密会を目撃していた。', '2025/08/31 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e917a034-9a7f-4f24-a187-a32e3242546b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3407c8a-df9b-4cfe-b18d-d6d6dce80037', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 9, '100236733', '決着', '突然舞踏会に魔獣が現れ、会場は大パニックに陥る。魔獣と相対し、戦いの中でルーアを逃がそうとするスウェン。しかしルーアには秘策があり…?', '2025/09/07 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14f1de9b-0166-47ae-82b0-6bc9307b268b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc9eb53e-fb7b-4542-8959-6ddb982fe35f', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 10, '100237686', '国王陛下からの呼び出し', 'デドモンドの悪事を暴いた二人だったが、神官長らの関与の証拠は得られなかった。国王陛下に謁見を命じられたルーアは王宮に向かうが、道中で次期国王と目されるスウェンの兄･サリッドと出会う。', '2025/09/14 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26076ac6-7e57-401f-b2d7-23c13005a7aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afedb097-56f0-4d76-b60e-efda917734eb', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 11, '100237961', 'ルーアの望み', 'サリッドに問い詰められるルーア。しかしサリッドの婚約者･ディアナの助けで事なきを得る。国王陛下に謁見したルーアは、魔獣騒ぎを収めた褒美として自身の望みを伝える。', '2025/09/21 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8456b37f-e6cc-4e3d-999a-d5dee84aedcb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('260f4f92-ac18-4361-8926-9ab55c9ecbc8', '9fdb0237-d67e-4dc9-ab30-8b12942b68b2', 12, '100238953', '次の計画', '【シーズン1 最終話】幼少期にレストアット家に仕えていたルイズと再会したルーア。家族の死が「策略」によるものだと聞かされ衝撃を受ける。そんな矢先、女神ルーシェの生誕祭の薔薇姫に推薦されて…!?', '2025/09/28 12:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92d7552d-cc40-4d48-9315-48dab6d2dce0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5f0ff2a4-d727-4b62-b675-a24c1e35bc54', '小市民シリーズ', '', 'hulu', 'how-to-become-ordinary', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aee393d6-9d75-4307-b84f-24b28c2e3104.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 173295, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e7f27b0f-6c67-4f8a-ba96-c25e8774728a', '5f0ff2a4-d727-4b62-b675-a24c1e35bc54', 'hulu-how-to-become-ordinary-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/913df2d6-c952-4cfe-b0ae-e66fdf22a8f0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e1fe223-c518-45f0-bfbb-e8bc6d8b1a12', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 1, '100190370', '羊の着ぐるみ', '平穏で慎ましい小市民を目指すという約束をした小鳩常悟朗と小佐内ゆきは、無事同じ高校に入学した。ところが、小佐内からいちごタルトを買いに行こうと誘われた四月のある日、小鳩は校内で盗まれたというポシェットの捜索に駆り出されてしまう。いきなり事件に遭遇した小鳩たちは、穏やかな放課後を過ごせるのだろうか。', '2024/07/12 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/913df2d6-c952-4cfe-b0ae-e66fdf22a8f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c1324e2-84ba-4f7e-8461-d3d7b3a5219d', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 2, '100190371', 'おいしいココアの作り方', '日曜日、堂島健吾の家に招かれた小鳩と小佐内は、堂島がこだわりの方法で作ったココアを振る舞われる。小佐内不在のタイミングで、小鳩の性格が変化した理由を尋ねる堂島。答えをはぐらかして席を立った小鳩だが、今度は台所にいた堂島の姉･知里の謎解きに引き込まれてしまう。堂島がココアを作った方法とシンクの状況が、どう考えても矛盾しているらしい。', '2024/07/19 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c15416f8-9d43-4cb8-8d10-0e7056941be2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('800553fa-05e9-4ea5-9cc1-069002b333f1', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 3, '100190372', 'ハンプティ･ダンプティ', '中間テストがあった日の放課後、小鳩は小佐内に呼び出され、ケーキバイキングができる洋菓子店を訪れた。テスト中にロッカーにあった花瓶が割れたことが原因で、小佐内は思い出しかけていた答えを忘れてしまったのだ。やけ食いをする小佐内からその話を聞いた小鳩は、学校に忘れたスマホを取りに行ったついでに、教室内を調べはじめる。', '2024/07/26 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f63ed3ea-e3b9-42a6-a509-3b18431c7741.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8544c633-01e1-4286-a221-3a539a730f3a', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 4, '100190373', '狐狼の心', '小佐内の自転車が盗まれ、路上に捨てられていた事件。小佐内が犯人に復讐を企んでいることを知った小鳩は、堂島にも用心棒を頼むことに。しかし、事情をよく知らぬ堂島はどうにも納得ができない。そこで小鳩は一連の出来事についての推理を堂島に話す。犯人が自転車を盗んでまで自動車学校に向かった理由は何だったのか?', '2024/08/09 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/310bab30-6c9b-41fe-bd9c-7cc46667ed12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d9936ca-0427-4c9f-bf25-edf7b5521e5d', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 5, '100190374', '伯林あげぱんの謎', '新聞部にアンケートを届けた小鳩は、部長の堂島から謎解きを頼まれる。学校近くにできたドイツパンの店の揚げパンを購入し、その中でマスタード入りのものを食べた部員が取材記事を書くことになっていた。だが部員はみな、自分が食べたものはマスタード入りではないと答えたらしい。内心興味をそそられた小鳩は、つい推理をはじめるのだった。', '2024/08/16 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74a5eec6-c271-410e-93f1-7ea30f7107a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df33ea0a-500e-42be-baa9-27de3f340355', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 6, '100190375', 'シャルロットだけはぼくのもの', '夏祭りの縁日、浴衣姿の小佐内と出会った小鳩。しばらく縁日を散策したのち、別れ際に小佐内から夏休みの予定を聞かれる。特にないと答えた小鳩であったが、ある予感がしていた。すると翌日、突然小鳩の家にやってきた小佐内から、街のスイーツ店を記した地図を渡される。それが〈小佐内スイーツセレクション･夏〉のはじまりだった。', '2024/08/23 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0d584214-a14e-4608-88ce-76044be2fff3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebb4071a-6ef3-4a9d-82b8-e87fda32dc62', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 7, '100190376', 'シェイク･ハーフ', '小佐内とスイーツを食べると約束した時間より早く着いてしまい、近くのバーガーショップに入った小鳩は、店内にいた堂島に声をかけられる。堂島は不穏な噂のある高校生グループを見張っていたのだ。その経緯を小鳩に話していた堂島だが、グループに動きがあったので、メモを残して店を出ていってしまう。小鳩がそのメモを手にとってみたところ、書かれていたのは「半」という文字だけであった。', '2024/08/30 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb362498-78fa-4a4d-bc4a-da214a45eadf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17f8cbe7-a668-46bd-a6ff-1f8a1b7635ec', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 8, '100190377', 'おいで、キャンディーをあげる', 'りんごあめを買いに行く約束をしていた小鳩は、一緒に出掛けるため小佐内のマンションを訪れた。だがそこで、小佐内が誘拐されたことを知る。状況がつかめないままマンションを出てすぐ、その小佐内からスマホにメッセージが届いた。そこには、買ってきてほしいスイーツが記されていて……。小鳩は堂島に電話をかけ、小佐内を探す手助けを依頼する。', '2024/09/06 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66fea597-415a-4925-8be5-c023b80c22a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58d25ebc-b5b1-4420-b7d4-564b6a748041', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 9, '100190378', 'スイート・メモリー（前編）', '誘拐事件が解決して数日後、小鳩と小佐内は〈小佐内スイーツセレクション・夏〉で最後に残った夏期限定トロピカルパフェを食べにきた。小鳩はパフェの価格と大きさに圧倒されつつ、刺激的だった夏休みを振り返る。まずは先日謎解きをしたバーガーショップに、そもそもなぜ堂島がいたのかについて……。', '2024/09/13 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbf1050c-9256-41c1-9ac6-2101a25769b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fb086d1-4533-4167-b2c6-3a68f8c43b54', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 10, '100190379', 'スイート・メモリー（後編）', '溶けてゆく夏期限定トロピカルパフェを挟み、向かい合う小鳩と小佐内。この夏の出来事に関して小佐内を問い詰める小鳩に対し、小佐内もまた、楽しげに推理をする小鳩について考えていたことを語りだす。「小市民」を目指していたふたりのこれからは、どうなってしまうのだろうか。', '2024/09/20 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eeb28406-e173-4271-b2cd-cb8206fd2b81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb7c8d83-6126-48cd-bafb-9dbacf4f4a37', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 11, '100223008', 'あたたかな冬 (前編)', '交際中の小佐内ゆきと瓜野高彦は、学校帰りに喫茶店に立ち寄った。瓜野は味気ない記事ばかり載る学内新聞「月報船戸」を変えたいのだと力説し、小佐内はティラミスを味わいつつ応援の意思を表明する。すると後日、他の新聞部員からの提案で、学内新聞にコラム欄が新設されることに。瓜野は強力なネタを探し始めるが……。', '2025/04/11 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77d99633-bdd3-4ad8-887b-438b111c54c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a08db59-74cf-45c8-90c2-d308ca20b129', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 12, '100223009', 'あたたかな冬 (後編)', '友人である氷谷優人の助言を受け、瓜野は市内を騒がす連続不審火を調査し、次の発生現場を予想するコラムを書く。一方、河川敷で車が炎上する騒動に居合わせた小鳩常悟朗は、その車が昨夏の誘拐事件に用いられたものだと気づく。新聞部部長の堂島健吾に電話をかけ、新聞部に干渉しているという小佐内の動向を探る。', '2025/04/18 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f059836-b116-4a86-a698-67ee6a948fa3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c9fc92e-6f45-4f3c-b62a-ab224ffdf169', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 13, '100223010', 'とまどう春', '昨秋から仲丸十希子と付き合い始めた小鳩だが、小佐内と連続不審火の関連が気になっていた。その頃、小佐内に認めてもらえないことにもどかしさを覚える瓜野は、予想記事の暴走ぶりをとがめられ、他の新聞部員と口論になっていた。部長の堂島に仲裁された瓜野は、不審火の法則性をしぶしぶ語りだす。', '2025/04/25 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6ffeb95-d9bc-47b1-ad5b-06cc49159654.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b673208f-f77b-42a1-b76a-183d33c3f6b0', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 14, '100223011', 'うたがわしい夏 (前編)', '新聞部部長になった瓜野は、次の放火が予想される地域の張り込みを新入部員たちとともに計画する。犯人を捕まえ、新聞部の不朽の業績を打ち立てるのだ! 一方、放火事件と小佐内の動向を探る小鳩は、新聞部の五日市公也を呼び出し、ある提案を口にする……。', '2025/05/02 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc987fe6-0d7b-4b1d-83e2-52d5401862e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c34b9b59-1910-4c29-825f-a783a87b7b81', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 15, '100223012', 'うたがわしい夏 (後編)', '瓜野の考えた法則性どおりに起きる連続放火事件は、次第にその規模をエスカレートさせていた。犯人を捕まえられず、氷谷から励まされた瓜野は、後日小佐内からも気になる助言を受ける。その頃、小鳩と仲丸の関係性にも変化が訪れていた。', '2025/05/09 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae305c2a-cfc6-4501-9b41-5ea55c7fd730.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4ecfb9c-1849-4418-b0d0-99646b64113d', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 16, '100223013', '真夏の夜', 'おれは、犯人が誰なのか、知っている――。そう宣言した瓜野は、連続放火犯を捕まえるため、新聞部員たちとともに夜の町へと繰り出す。小鳩と堂島もまた、放火発生が予想される場所で待ち伏せをしていた。ついに火の手が上がり、現場に駆けつけた小鳩が遭遇した人物とは……。', '2025/05/16 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71c45d87-99dc-4739-bb1c-fae436d73dd5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43f750db-734d-490f-87db-f0d37e1a7001', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 17, '100223014', 'ふたたびの秋', '真夜中の公園。連続放火犯は捕まり、とうとう小鳩と小佐内は出会った。この事件について、小鳩がしていたことを知りたいのだと小佐内はいう。小鳩は、河川敷での不審火をきっかけに、事件に興味を抱いた経緯を語り出す。しかし小鳩にも、まだ推理できていないことがあって……。', '2025/05/23 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b31307ff-565b-45cf-8804-a538a58d171d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5c48ff9-0ea9-4610-8b19-32ce29ad5d80', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 18, '100223015', 'わたしたち本当に出会うべきだったのかな', '大学入試を翌年に控えた12月。小佐内と歩いていた小鳩はひき逃げにあい、病院に搬送された。見舞いに来た堂島から小佐内の無事を聞くなど話をするうち、小鳩は中学時代、同じようにひき逃げにあった当時のクラスメイト、日坂祥太郎のことを思い出す。', '2025/05/30 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e23b336-8de9-41eb-b46c-d2b196455ac1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28d58d79-b335-4c8d-928e-f80d6111ec3c', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 19, '100223016', '小鳩くんと小佐内さん', 'クリスマスの深夜、病室で目覚めた小鳩は、テーブルの上にボンボンショコラの小箱を見つける。同封のメッセージカードを読むに、これは小佐内からの贈り物で、彼女は小鳩をひいた犯人を追っているようだ。中学三年生の時、小佐内と初めて図書室で話したときも、彼女は車のブレーキ痕を調べていた。', '2025/06/06 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b67e768-5022-4c0f-937f-0d75ebb464d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5cb288f6-026d-45b4-b697-4672266cc459', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 20, '100223017', '乾いた花に、どうぞお水を', '小佐内から贈られたボンボンショコラを一日一粒ずつ食べ、小鳩はリハビリをする日々を送る。いまはなかなか会えないが、中学時代の小鳩と小佐内は協力して日坂のひき逃げ事件を捜査した。日坂の友人や後輩から話を聞いて推理するうち、ふたりはある隠された事実を突き止めたが……。', '2025/06/13 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf3724a3-f077-4764-89e3-230b6464942a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd8bf088-ffbe-426c-aab8-87b7667fc29b', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 21, '100223018', '黄金だと思っていた時代の終わり', '小鳩が目覚めると病室にドライフラワーが飾られていた。寝ているときに小佐内が置いていったらしく、花の間に封筒が挟まっている。ボンボンショコラも残り少なくなった年末、小鳩は中学時代の日坂のひき逃げ事件の結末と、小市民を志すきっかけとなった出来事に思いを馳せる。', '2025/06/20 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eae2a544-227c-43ad-8d2c-be5622e1d766.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ee0c3b0-703c-42d0-a5b4-c66ffed5664e', 'e7f27b0f-6c67-4f8a-ba96-c25e8774728a', 22, '100223019', '報い', '【シーズン1 最終話】大晦日、小佐内が小鳩の病室を訪れているとき、小鳩をひいた犯人が現れる。襲いかかる犯人から逃れ、ふたりはエレベーターで屋上へ。寒空の下で小鳩は、中学時代の日坂のひき逃げ事件と、この冬に起きた自身のひき逃げ事件についての推理を語りはじめる。', '2025/06/27 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e308a2b0-0c36-4f4d-ac35-72f59b750898.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('229818d9-dac6-4266-a982-14c02ab0fd86', '小林さんちのメイドラゴン', '', 'hulu', 'miss-kobayashis-dragon-maid', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fb14d1d-b93d-4654-9ee2-a503bed16b1f.jpg?w=331&h=447&p=t', 'hulu', 2017, 0, 1, 'FINISHED', NULL, 21776, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cf451b46-e7c3-4516-a484-2c8c74754c18', '229818d9-dac6-4266-a982-14c02ab0fd86', 'hulu-miss-kobayashis-dragon-maid-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a8de410-4aca-45b1-ad28-89c092b7431d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('246a81c5-439c-4568-923a-46180c6d251d', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 1, '100083879', '史上最強のメイド、トール! (まあドラゴンですから)', '朝、会社に出ようとしたらドラゴンがいた。茫然とする小林さんの目の前で、そのドラゴンは角あり尻尾ありのメイド服を着た美少女へと変身した。トールと名乗るそのドラゴン娘は「今日からメイドとして働かせてください!」と申し出る。どういうことか分からず尋ねると、昨夜酔った勢いで小林さんが家に誘っていたようだった。「人を雇う余裕はない」と断る小林さんだったが、会社に遅刻してしまいそうな時間だと気づき――。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a8de410-4aca-45b1-ad28-89c092b7431d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('efd20837-3c19-411c-b2ab-c0bc0ab89884', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 2, '100083880', '第二のドラゴン、カンナ! (ネタバレ全開ですね)', '小林さんとトールの共同生活が馴染んできたころ。トールと一緒にお買い物へと出かける小林さん。トールが商店街の人たちと仲良くしているのを目の当たりにし、トールのコミュ力の高さに驚く。でも当の本人は「なんか適当に愛想よくしただけ」とブラック発言。未だ人間の感情は理解していないご様子。そんなある休日、小林さんが一人家にいると尋ね人が。扉を開けるとそこにいたのは、角と尻尾を携えた幼女だった――!?', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f80ad17-7db2-42f5-9463-aa45ad12405e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ac4938c-0967-4bc2-8c65-652f7a420f39', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 3, '100083881', '新生活、はじまる! (もちろんうまくいきません)', 'トールに加えカンナも住むようになった小林さんち。賑やかになったのはいいが、いかんせん狭いマンションに三人暮らしは窮屈。そこで引っ越しを決意する小林さん。引っ越した先で滝谷を呼んでパーティーを開くことになったのだが、そこにトールの知り合いである洞窟住まいのファフニールや、太古からこちらの世界に住まうルコアなど、新しいドラゴンたちが小林さんちを訪ねてくる……。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d81f91ed-c963-44cf-92e2-265d30d129d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e191bc31-f7d0-4100-9ee0-e15318e905f1', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 4, '100083882', 'カンナ、学校に行く! (その必要はないんですが)', '登校する小学生を羨ましそうに見下ろすカンナ。小林さんはカンナを小学校に行かせてあげることを決める。小学校に通うために必要なものを買いに商店街へ出かける小林さん、トール、カンナの三人だったが、最近できたという今時の文房具店に、小林さんはたじたじ。一方トールとカンナは初めて見る文房具の数々に興味津々で……。そしてなんとか必要なものを揃えたカンナは、いよいよ小学校に乗り込む――!!', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb68dc27-8e33-4af6-8055-165dd11aff1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28965ce3-2d1f-41d4-8430-67abe3897909', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 5, '100083883', 'トールの社会勉強! (本人は出来てるつもりです)', 'ようやく板についてきたメイドのお仕事。トールはふと小林さんの仕事場が気になり、会社見学に赴いた。そこでは皆に頼られる立派な小林さんがいて、改めて小林さんに惚れる。だがそこには小林さんに嫌がらせをする上司もいて、トールは激しい怒りを覚える……。街ではあちらの世界にいるはずのファフニールと偶然出会う。自分もこちらの世界に住むと言うファフニールのために、トールは一緒に住まいを探すことに――!?', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70bba2f8-411f-4f6f-a00c-040a4ea30f13.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11208d2d-7013-4ee0-86d7-d95f440d65c0', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 6, '100083884', 'お宅訪問! (してないお宅もあります)', '才川から家に誘われたカンナ。才川家にもメイドがいるとのことで、小林さんとトールも一緒に招かれる。出迎えてくれた本格的なメイドのジョージーに、小林さんは興奮状態。意気投合しメイド談義に花を咲かせる。さらに今度はルコアまでもがこっちの世界に住むことになったと言いだす。魔法使いの家系である翔太君に召喚されたのだそうだ。ルコアは翔太君と仲良くなろうとスキンシップを図るが、それがあまりにも過激で――。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21a5a3d8-78e2-482f-8559-1a1baf80df2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('379a5aa8-b3a0-4318-99e0-b12c9fd17c4c', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 7, '100083885', '夏の定番! (ぶっちゃけテコ入れ回ですね)', '海に来た小林さんたち。だが早々、際どすぎる水着のルコアが監視員に連れて行かれてしまう。気を取り直し、日焼け止めを塗りあったり、スイカ割りをしたり、みんなで泳いだり、夏を目いっぱい楽しむ一同。海の次はコミケ! と、オタクたちの戦場へと赴く小林さんとトール。オタクの尋常じゃないオーラにさすがのトールも戦慄。滝谷のサークルの手伝いをしていると、トールは角と翼を生やしたコスプレだと勘違いされ――!?', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df28590b-5c80-4d3c-b1c9-ef00f1951560.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c23201c-090b-402b-af33-2ef2e39ddc15', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 8, '100083886', '新たなるドラゴン、エルマ! (やっと出てきましたか)', 'カンナに遠足に持っていくお弁当を頼まれた小林さん。自分に任せてくださいと言うトールとの間で、どっちが上手いか勝負が勃発! ルコア、ファフニールを審判員に迎え、二人の料理対決がいま始まる! そしてついに新たなドラゴン娘が登場! 突如小林さんちの壁を破壊し現れたのは、トールと犬猿の仲であるエルマ。秩序を重んじるエルマは、人間との関係を拗らせかねないトールを無理矢理連れ戻そうと勝負を挑んでくる――!!', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89c53ae2-a5ff-4b30-8585-995e97d9d102.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96b77a67-39e8-4f9d-94c0-778c060255c3', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 9, '100083887', '運動会! (ひねりも何もないですね)', 'カンナの運動会。しかし小林さんは仕事が忙しく行けそうにないと知ると、カンナは拗ねてしまう。親でもない自分にどうしてそこまで来てほしいのかわからない小林さんだったが、カンナにとって小林さんは既に親も同然。滝谷からも「行けるかどうかより、行きたいかどうかで決めた方がいい」と言われてしまう……。そうしていよいよ始まった運動会。ドラゴンであるカンナの身体能力は圧倒的なはずだったが――!?', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f051b461-a26a-44fc-a585-5acefa3d73dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18d2ad26-fc6e-47d0-99dc-3956e81497f6', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 10, '100083888', '劇団ドラゴン、オンステージ! (劇団名あったんですね)', 'クリスマスも近づいてきたある冬の日。トールは老人ホームで行われるクリスマスパーティーの出し物を頼まれる。忙しい小林さんに迷惑はかけないようにとトールたちだけで劇をすることになったのだが、小林さんという制御を失ったドラゴンたちが考える劇はやはりハチャメチャな方向に……。そうしてついに始まるトールたちの劇。小林さんは心配そうな表情でステージを見つめるが――。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ececade1-dcb4-4295-8a9a-d25d999dbe65.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ce8e4a8-e637-4c14-b922-b0d3eae4befc', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 11, '100083889', '年末年始! (コミケネタありません)', '一年の終わりも近づいてきたころ。商店街でトールが福引を引くと、当たったのはなんと温泉旅行――ではなくコタツだった。ついに小林さんちに導入されたコタツに、トールたちはごろごろごろごろ……。コタツは人間どころかドラゴンまでをもダメにしてしまう。そんな感じでだらだらと年末年始を過ごす小林さんち。平和な休日がただ無為に過ぎて行く。そんな中、トールたちは初詣に行くために着物を着させてもらうことに――!?', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e555522-c26f-4ba2-9a65-7b2ef5d7dad1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7727ce59-c453-4da4-84a1-8e72a9cf9509', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 12, '100083890', 'トールと小林、感動の出会い! (自分でハードル上げてますね)', '今や家事を完璧にこなせるようになったトール。小林さんの希望もあって、今夜は最高のオムライスを作ろうと思い立つ。しかし高い食材を揃えるには予算オーバー。どうしても小林さんの笑顔を見たいトールは、つい禁じ手に手を出してしまう……。一方の小林さんは、仕事疲れで電車の中でうとうと。夢で見えてきたのは、小林さんが初めてトールと出会った夜だった。小林さんとトールの出会いが、ついに明らかに――!?', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0059a1d-5a87-4a6e-a77c-9d04d19dcad5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6d346cd-051a-4e51-baef-10f32d2646d2', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 13, '100083891', '終焉帝、来る! (気がつけば最終回です)', '穏やかな休日。小林さんちでは、いつものように緩やかな時間が流れていた。しかし買い物に出たトールは、道中ふと考えてしまう。小林さんは人間で、もし小林さんの寿命が来て、死んでしまったら――? 永遠には一緒にいられない。いつか別れは来る。わかっていたのに。覚悟しているのに。それでもトールの心は乱される。そんなトールに追い打ちをかけるように、彼女の目の前に現れたのは終焉帝――トールの父だった。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f8642e9-a42b-49fa-bb52-04dda3aaada2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('580ec96d-dd31-4d4b-89f8-5d5471ae5028', 'cf451b46-e7c3-4516-a484-2c8c74754c18', 14, '100091631', 'バレンタイン、そして温泉!(あまり期待しないでください)', 'バレンタイン。トールは身も心も小林さんを手に入れようと、媚薬入りの特製チョコを作る。小林さんはトールのそんな下心を見抜き、見事に受け取りを回避するのだったが、ひょんなことから媚薬チョコを口にしてしまう……。心機一転、今度は温泉旅行に向かう一同。エルマたちドラゴンと、才川や翔太君までみんなが勢揃い。そんな楽しい旅行の中、トールは小林さんへもう一度チョコを渡すタイミングを一人うかがっていた――。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a50015e-9f3f-4fbe-bb5a-69ec13900926.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c09dc7b4-bdbd-4015-9af3-6b4bb9d726b1', '小林さんちのメイドラゴンS', '', 'hulu', 'miss-kobayashis-dragon-maid-s', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91c6a36b-b770-4ae2-8a29-870c5d50773e.jpg?w=331&h=447&p=t', 'hulu', 2021, 2, 1, 'FINISHED', NULL, 107717, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f4f44c07-c837-466c-8719-6cea3aae6f19', 'c09dc7b4-bdbd-4015-9af3-6b4bb9d726b1', 'hulu-miss-kobayashis-dragon-maid-s-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53fbe152-a1ba-4c03-bf09-dffd47597251.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc6708ef-bc61-4486-a909-9e99f26ad54c', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 1, '100086631', '新たなるドラゴン、イルル!(またよろしくお願いします)', '自称究極のメイドであるトールは、今度オープンする新しいメイド喫茶にライバル心を燃やし殴り込みに行く。しかし戻ってきたトールは「なんか働くことになりました」と言い出した。そんな変わらない毎日を送っていたある日、ニュースで小林さんと出逢った山が何者かに破壊されていることを知る。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53fbe152-a1ba-4c03-bf09-dffd47597251.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1fce97f-a8a2-4656-8f2d-6fc582299bde', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 2, '100086962', 'イケメン、小林!(いろんな意味で)', 'イルルを退けた小林さんだったが、その代償に魔法で「アレ」を股間に付けられてしまう。すると普段は何とも思っていなかったトールやカンナが違って見え始め、次第に小林さんは悶々し始めていく。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7f4771d-8be3-4cb7-a240-3691142e108d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e5242e9-fd64-41d5-8768-558de2ffd779', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 3, '100087266', '課外活動 (もちろん普通じゃありません)', '小林さんちに遊びに来た才川。しかし見知らぬ女の子 (イルル) が……。一緒に遊ぼうと誘うも、イルルは冷たく避けていく。そこに偶然訪れたルコアは、避けようとするイルルの気持ちに気付き、助け船を出そうと計らう。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db751874-f7a3-48c8-94d1-1d0c14b4dc60.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84e580d2-893d-43fd-8547-d1f78d6f9af8', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 4, '100087646', '郷に入りては郷に従え (合わせるって大変です)', '美しいコード配列に感嘆する小林さんと滝谷。なんとそれを書いたのはエルマだった。ついに一人前の戦力になったと小林さんは大喜び。小林さんは会社の「柱」としてもっとたくさんの仕事を抱えているそうだ。しかしその話を聞いた途端、エルマは急に怒りだす。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81cec114-a455-4d2b-b0d8-fc22e4383bef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49adbf6a-eb6f-479b-a4d8-0302643e5a0a', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 5, '100088139', '君と一緒に (まあ気が合えばですが)', '商店街で会うなりいがみ合うトールとエルマ。いつもの光景に呆れ気味の小林さんだが、出会った当初はそうではなかったと言う。犬猿の仲の二人の出会いは、遡ること遥か昔。あちらの世界でトールが一人旅をしている時のことだった……。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6353d1ac-334e-4cf8-a42d-17a99b928b15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee844171-276b-4577-9667-a7a033bb4218', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 6, '100088816', '合縁奇縁 (片方はドラゴンです)', '毎日ルコアの奔放な接触アプローチに悩まされている翔太。本来なら自分が主人のはずなのに……。一人前の魔法使いを目指す身として、主導権を取り戻さなければ、と一念発起する。そこで翔太は、ルコアの弱点を探り始めるのだった。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c054087c-1517-4fb5-8c1f-43ca57653818.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8487823-d11a-4e5e-b936-0aa1b662ef54', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 7, '100089274', '一般常識 (みんなずれてます)', '夜闇が支配する路地裏に、怪しい人物が2人。不穏な空気を醸し、何やら密談を交わしている。「なんだい? こんなところに呼び出して」――2本角の痴女が言う。「お前の力を貸せ」――執事服の陰鬱男が返す。最凶最悪のタッグが今、動き出す――。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e68a2ec-6d78-4076-8577-ee01c35eb238.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6fcf196-c9be-413a-9414-3ae9cd59e29b', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 8, '100089910', '世界に一つだけの (好きな言葉を続けてください)', '何やら部屋に籠り始める翔太。父の日のプレゼントとして魔術道具を制作するため、難しい魔術書を読み漁っていた。その難易度が高いため手伝おうと名乗り出るルコアだったが、自分一人の力でやり遂げたい、と断られてしまう。だがやはり制作は失敗続きで……。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd44cd2b-7181-4fa2-a430-ac9b013a9b23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21dbe217-9098-4c57-8004-fd507f99e13e', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 9, '100090745', 'いろいろワケがありまして (エルマざんまいです)', '待遇改善を要求する――! それはエルマの一言から始まった。小林さんたちの勤める会社は、極めて“黒”に近い。そこにエルマがようやくおかしいと気付き、旗を掲げたのだ。改善などどうせ無理だろうと高を括っていた小林さんだったが、ドラゴンのバイタリティは予想を遥か上回っていて……。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b743a44e-20b4-4325-891b-7739293b450f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11086850-414c-43b0-9345-f062eeaf9b84', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 10, '100091308', 'カンナの夏休み (二か国語放送です!?)', '小林さんと喧嘩した勢いで家出をしてしまったカンナ。帰りたくないからと太陽のある明るい方向へと大海原を飛んでいく。その時、たまたま見つけた陸地へと降り立ったカンナだったが、なんとそこは決して眠らない街･ニューヨークだった。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/46248838-9b56-433f-9186-a38a15bed904.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8cfb27ce-3455-414d-944c-67947b37487c', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 11, '100091867', 'プレミアムシート (特別料金はかかりません)', '本格的に腰を痛めて来た小林さん。改善しようと健康グッズを買い漁るが、それらはほとんど使われないまま……。業を煮やしたトールがしっぽ肉を食べさせようとするも、あえなく拒絶。トールは、小林さんが求める「一般的な治療法」を探し始める。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b88329f-c990-4666-9838-450d9ed00dff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('483669f2-b75a-435b-9b00-a9d92e9dfd3f', 'f4f44c07-c837-466c-8719-6cea3aae6f19', 12, '100092121', '生生流転 (でも立ち止まるのもありですかね)', '【シーズン2 最終話】いつも通りの朝。いつも通りのドラゴン娘たち。何一つ不満のない、かけがえのない平凡な日常。だが小林さんの中には、終焉帝の話を聞いてから、ほんの少しだけ重い何かが転がっていた。でもそれが何か判然としない。もやもやとする中、待ちに待った夏祭りが始まる――。', '2024/08/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fb588de-9f28-4ef6-9e33-9ae07090c16a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('985fffcd-1c25-41db-97b3-7aba2799d427', '少女終末旅行', '', 'hulu', 'girls-last-tour', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/625046f9-05fc-4d52-bc8d-b5267109f0b7.jpg?w=331&h=447&p=t', 'hulu', 2017, 3, 1, 'FINISHED', NULL, 99420, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1df3b6cc-d862-416e-8fca-950a6fe13b20', '985fffcd-1c25-41db-97b3-7aba2799d427', 'hulu-girls-last-tour-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17599b9b-665c-4453-9ee3-e94f4af138b2.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e43c281-93db-41c5-bbb3-1009ec9bc7be', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 1, '100008685', '星空／戦争', '文明が崩壊し、全てが滅んでしまった世界で、ふたりぼっちになったチトとユーリは、延々と続く廃墟を愛車ケッテンクラートに乗って旅をしていた。しかし、ユーリのふとした思いつきで建物の内部に入った二人は、そのまま道に迷い、外に出ることができなくなってしまう。陽の光も当たらない暗闇の中で、自分たちがどこにいるのかもわからないまま、時間の感覚すら失い始めた頃、眠りから目覚めたチトはわずかに流れている風に気がつく。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17599b9b-665c-4453-9ee3-e94f4af138b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('499d0658-29b7-4bf2-83e9-cc5d57dd00bc', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 2, '100009178', '風呂／日記／洗濯', '見渡す限り一面の銀世界をケッテンクラートに乗って走るチトとユーリ。雪はしんしんと降り続き、ケッテンクラートが走ったあとのわだちもすぐ雪に覆われていく。ユーリは荷台でいくつもの雪玉を作っては並べながら、チトにここはどこなんだろうと尋ねるが、答えなど出るはずもなく、徐々にその勢いを増していく雪と風。吹雪の中で本格的に生命の危機を感じ始めたチトとユーリは意識を失いそうになりながら、寒さを凌げる場所を探す。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6af6338-192d-4da3-9ede-a1f44538e366.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef478b80-4de8-407a-b3b5-ca577da98b3a', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 3, '100009415', '遭遇／都市／街灯', '巨大な溝のそばで、溝の向こう側に渡るための橋を探すチトとユーリ。しかし、どこまで行っても延々に溝が続くだけで、向こう側に渡れそうな橋は見当たらない。そのときふと煙草の匂いがすることに気がついたチトが匂いの方を見ると、まだ火がくすぶっている吸い殻が落ちていた。警戒して辺りを見回すと雪の上に足跡も残っている。近くにいる何者かを警戒し、銃を手にしたユーリにチトは弾を込めるように指示を出す。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6722d6cb-a2da-4745-b904-1dada404aaa6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cab719a-0c5f-42b9-932f-2236d6a34283', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 4, '100009738', '写真／寺院', '生まれて初めて見るカメラを手に試行錯誤しながらユーリの写真を撮るチト。何とかピントは合ったものの画面が全体的に白く上手く撮れたとは言い難い。撮影を止め、ケッテンクラートに乗って走り出すチトとユーリだったが、カメラに興味津々のユーリはチトが首にさげているカメラを取り、写真を撮り始める。運転中のチトに声をかけ、写真を撮るユーリに、運転中によそ見をすると危ないと言うチトだったが、時既に遅く石像にぶつかってしまう。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fc402dd5-d5c8-47b5-9606-29368fd3373b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b6c2027-41c0-4a68-bd06-cad648dfd3af', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 5, '100010396', '住居／昼寝／雨音', 'いくつもの建物が連なった巨大な団地にやってきたチトとユーリ。電気や水道といった設備はまだ動いているが、人は誰もいない。かつてはたくさんの人々が住んでいた家だった場所を探索しながら、家について考える二人。探索を続けるうちにまだドアがついている部屋を見つけた二人が中をのぞいてみると、そこには二つのソファが残されていた。ソファに座ったチトとユーリは背にもたれかかり、一息つきながらお互いの理想の部屋について語り始める。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6593ce1-ec29-413f-9964-4bc8a794c6bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3bffa177-3ab0-464c-9805-c724e4e767fc', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 6, '100010576', '故障／技術／離陸', '故障して動かなくなってしまったケッテンクラートを修理するチトの横で、仰向けに寝転び、空を眺めているユーリ。板金をしゃぶりながら鼻歌を歌うユーリに、少しは手伝って欲しいと告げるチトだったが、返ってきたのは断りともっと絶望と仲良くなろうよという返事だった。このまま直らなかったらどこにも行けなくなってしまうと溜息をもらすチト。そんなときユーリの視界に空を飛ぶ何かが飛び込んでくる。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c191f87-fd29-40eb-9f9f-9df94e12251d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19403bb4-2f12-4c1e-9300-4d1e5e73a7be', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 7, '100011034', '迷路／調理', 'イシイが描いてくれた食料生産施設への地図に従ってやってきた建物の中には大小様々なパイプが縦横無尽に組まれた空間が広がっていた。上も下も右も左も前も後ろもパイプしか見えない。そこから先については行けばわかるとしか書いておらず、仕方なくパイプの上を歩きながら進んでいくチトとユーリ。しかし高いところが苦手なチトは、足を踏み外せば命を落としてしまうであろう高さに耐えきれず、その場にへたりこんでしまう。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69057b62-b4a2-4323-a039-dc89f4d1bce8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59001f6a-d9f6-4e78-8480-d71869a2e0ba', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 8, '100011334', '記憶／螺旋／月光', '視界の果てまで続く広大な敷地の中に整然と並ぶ無数の引き出しがついたいくつもの壁。引き出しは欠落している箇所を除けば、ほとんどぴったりと閉じていて開けることができず、開けることができたいくつかの引き出しも空っぽか役にも立たない価値のなさそうなものが入っているだけ。そして壁の終わりのほうに見覚えのある石像を見つけたチトとユーリは、石像の写真を撮り、カメラをくれたカナザワのことを思い出す。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/318ee405-44ff-4fb9-8475-bcedb064ff52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c03ca482-9dde-4c10-ae7d-5fc498eb80ed', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 9, '100011793', '技術／水槽／生命', 'まだ所々電灯がついている薄暗い場所をケッテンクラートに乗って進んでいたチトとユーリ。そんな中、チトが地面に何かが打ち付けられるような音に気がつく。警戒しながら音の正体を探ろうとする二人。連続して聞こえるその音は徐々に大きくなり、次第に地面も音に合わせて振動を始める。暗闇の中から目の前に現れたのは長い足を持つ巨大なロボットだった。ロボットはチトとユーリの眼前を通過し、また暗闇の中へと消えていく。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3750123b-ed16-400f-8bf6-54c5c5071df3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bea0ca96-0036-4ceb-91a6-99d2efd9db2a', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 10, '100012138', '電車／波長／捕獲', '駅のホームにやってきたチトとユーリは、そこに到着した電車にケッテンクラートで乗り込む。瞬く間にスピードを上げて進んでいく電車の窓の外に広がる巨大なプラントが立ち並ぶ施設に圧倒される二人。電車は施設の上に架けられた高架橋を通り、トンネルへと進んでいく。見るものがなくなってしまったチトとユーリは、暇を持て余し、電車の先頭車両へ行こうとケッテンクラートを走らせる。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d73ce988-d745-4ff8-8ac0-d1846975c5c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f35e1d00-c589-4781-a8a1-80540024dda3', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 11, '100012583', '文化／破壊／過去', '大穴の中で見つけた猫のような謎の生き物を拾ったチトとユーリ。ヌコという名前らしいその生き物に銃弾を食べさせているユーリを見て、驚くチトだったが、ヌコは銃弾をお気に召したらしく、もっと食べたいとねだる。ユーリが拾ってきた大小様々な銃弾の中でも大きな20mmの銃弾を頬張るヌコを横目に、建物の中に何かを見つけたチトは、ケッテンクラートの進路を変えて、建物の中へと入っていく。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc9e0eba-032f-4db1-9049-9270d0a7a0c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b53d48f7-97d3-499c-a62a-8bb20b1b83d7', '1df3b6cc-d862-416e-8fca-950a6fe13b20', 12, '100012785', '接続／仲間', '【シーズン1 最終話】巨大な潜水艦の中を探索しながら、昔の人々がどんな暮らしをしていたのか知りたいと言うチト。ユーリになぜそんなことを知りたいのかと聞かれるチトだったが、上手く言葉にできない。潜水艦の中で見つけたチョコレートを食べるユーリに、チトがカメラを向けてファインダーを覗くと、そこに何か文字が浮かび上がる。何が起きているのか把握する間もなく、チトとユーリの前に浮かび上がったのは、これまで撮影してきた写真の数々だった。', '2025/12/26 00:00:00', 1442, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fda9692-25dc-465e-801c-457117e73cb1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1bab5dc9-4fce-4711-8642-9ec164ca63c6', '昭和元禄落語心中', '', 'hulu', 'showa-genroku-rakugo-shinju', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ecbf3dd2-79b8-4c6f-87a5-2cdd92dcad54.jpg?w=331&h=447&p=t', 'hulu', 2016, 0, 1, 'FINISHED', NULL, 20972, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('be735fbe-3fbb-441a-8fae-b44c11a16aa6', '笑顔のたえない職場です。', '', 'hulu', 'a-mangakas-weirdly-wonderful-workplace', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6c90707-d172-4ef5-ab54-147e1f6ac833.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 173523, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5898e098-31c6-4047-805c-7d509281ea69', 'be735fbe-3fbb-441a-8fae-b44c11a16aa6', 'hulu-a-mangakas-weirdly-wonderful-workplace-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9df3d139-252b-4cb1-b777-9bdd9cabc7dd.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab748f37-681a-450f-b350-1dcf9d147a4c', '5898e098-31c6-4047-805c-7d509281ea69', 1, '100240365', 'とある漫画家と編集です。', '深夜、とあるマンションの一室。新人漫画家･双見は、苦戦していた連載ネームをようやく描き上げた。早速、担当編集･佐藤に送ろうとするが、ふと「もしかして今ごろ佐藤さんは◯◯中なのでは……?」と躊躇ってしまう。アシスタント･瑞希に一蹴されてもなお、双見のよからぬ妄想は止まらず……', '2025/10/11 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9df3d139-252b-4cb1-b777-9bdd9cabc7dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad468bd8-aa6b-400c-8d93-831f7900752b', '5898e098-31c6-4047-805c-7d509281ea69', 2, '100240589', '心底頼れるアシさんです。', '『昴へ』のコミックス作業が進む中、瑞希がSNSに投稿した4コマがバズっているのを発見した双見。既に編集者からスカウトもされているという瑞希に、双見は「デビューしちゃえばいいじゃん!」と発破をかける。しかし当の本人には、のらりくらりとかわされてしまい……', '2025/10/18 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/04bc537c-7e25-4215-a309-1925f31acf12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6f9056f-c424-4e36-b991-ce63bac9fcb3', '5898e098-31c6-4047-805c-7d509281ea69', 3, '100241027', '猫の手も借りたい状況です。', '作業量が増え、アシスタントを増員したい双見。佐藤の紹介により、地方在住のデジタルアシスタント･ねこのてを雇うことに。SNS上の激しいテンションに怯みながらも、お試し発注に挑むが――。さらに将棋道場への取材では、『昴へ』の監修も務める女流棋士･角館塔子と対面し……', '2025/10/25 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f409b46-f0b2-404a-81eb-0fc22cb25bcd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe7c6474-b54a-4fa8-9bef-1c4c66c73e9e', '5898e098-31c6-4047-805c-7d509281ea69', 4, '100241786', '一人じゃできない仕事です。', '漫画家あるあるの“単行本発売前ウツ”に陥ってしまった双見。出来立てコミックスを前にしても、いまいち現実感が沸いてこない。そんな双見が、敏腕営業担当･池波に連れられ、書店回りに向かった先で目にしたものとは? そして何やら言いたいことがありそうな佐藤が、いよいよ口を開いて……', '2025/11/01 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88a2c39e-5cf7-4f35-a225-937b03dcf5ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bba07598-d097-4353-a938-cdcc6151d7b2', '5898e098-31c6-4047-805c-7d509281ea69', 5, '100242653', '先輩は自称ライバルです。', '新キャラとして”ライバル”を登場させたい双見。悶々と悩んでいるところに、アシスタント時代の先輩･梨田が現れる。打ち切り宣言を食らったばかりの梨田は、泥酔&だる絡み&寝落ちというなかなかの態度。そんな彼女を前に、瑞希から飛び出した提案とは……?', '2025/11/08 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76f24ce2-f7b8-49fc-9337-df3a7fa2f4b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9daa8255-4e54-4132-814e-6197a77cf251', '5898e098-31c6-4047-805c-7d509281ea69', 6, '100243622', '不思議な三角関係です。', '「浮気する時って、こんな感じなのかな」他誌の編集から執筆を依頼された双見。きっぱり断ることができず、ずるずると関係を続けてしまう。どうにか佐藤に事情を打ち明けたものの、佐藤のテンションもまた露骨に変化して……「なんか、寝取られにあった気分」。もつれた3人の行く末は!?', '2025/11/15 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1a0cea4-b7ca-4523-8a1c-afe915cf0643.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('edd05b72-8985-451c-bde9-c501c4708f18', '5898e098-31c6-4047-805c-7d509281ea69', 7, '100244443', '想定してない展開です。', 'ねこのての仕事ぶりには満足しているものの、謎の素性が気になり始めた双見。瑞希のアイデアで、初のビデオ通話を繋げると、そこに現れたのは想定外の人物! 対話を重ねると、驚きの事実が発覚して……!? さらに双見の仕事場に、塔子が突然の来訪。塔子と初対面の梨田は、警戒し牙を剥く。そんな梨田に、塔子は”簡単なゲーム”を提案するが……', '2025/11/22 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2b10cfe-57da-4868-a3e7-ea8a60ef9a55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d8fce18-0c70-4866-9c9c-3b7610a5511e', '5898e098-31c6-4047-805c-7d509281ea69', 8, '100245595', 'これも漫画家の仕事です。', '『月刊クローバー』の編集部で、深刻な事件が起きたらしい。編集長･立浪に呼び出された双見は、事件にまつわる重大な依頼を受けることに。そのころ既に、『昴へ』コミックス2巻の作業も始まっていた。双見と佐藤は、カバーの打ち合わせのため、デザイナー･月縄の事務所に向かう。', '2025/11/29 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1ac1a72-24df-4006-96e2-f3f78edf7deb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('275e9002-2e4c-4069-9674-a33b8396477e', '5898e098-31c6-4047-805c-7d509281ea69', 9, '100246100', '散歩で見つけたお宝です。', 'ダイエットのための散歩中、双見は捨てられた子犬を拾う。かつて漫画家として低迷していた自分を、つい重ねてしまう双見。瑞希に頼み込み、子犬を仕事場で飼うことに。無邪気で愛くるしい子犬は、梨田に佐藤、塔子に浅倉と、関わる者すべてを虜にしていく。一方そのころ、絶賛低迷中の梨田のもとに、運命を変える一通のファンレター (?) が届き……', '2025/12/06 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/118069f7-1915-4d3e-999d-41b442b3ec69.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('86fda79a-770f-48a8-b536-b1a579379b59', '5898e098-31c6-4047-805c-7d509281ea69', 10, '100246634', 'たまにはお仕事休みます。', 'ものもらいに罹り、強制的に仕事を休まされてしまった瑞希。「私がいなくても、なんとかなっちゃうんだ……」複雑な思いを抱える瑞希は、姉･柚希からさらなる正論パンチを食らわされ……。また双見は、塔子から女流玉座戦の前夜祭への招待を受ける。泊りがけの取材となったが、佐藤が予約していたのは、やけに豪華な温泉旅館で……?', '2025/12/13 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb29dff1-4e14-48af-b6f2-3e7f97fd72bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8528ea43-3d23-490b-bf95-1a7554870e21', '5898e098-31c6-4047-805c-7d509281ea69', 11, '100247389', '体験するのは大切です。', 'スピンオフの本格始動が近づき、怖気づいてきた梨田。双見を無理やり同行させ、師匠･滝沢を訪ねる。そこで二人は、超売れっ子作家の過去を知ることになる。一方、春休みを利用して上京してきたねこのて。双見や瑞希と共に、”梨田&塔子の一日デート体験”を尾行することになり……', '2025/12/20 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b7c9fbf-c7c4-42ac-8b50-fc8260e5d521.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('317a8b35-931e-43db-bd12-7b68bbc96c42', '5898e098-31c6-4047-805c-7d509281ea69', 12, '100248142', '描いててよかった! 感動です。', '双見、梨田、和。それぞれの躍進を祝うため、滝沢宅でピザパーティーが開催されていた。そして時を同じく、双見のマンションでは佐藤、瑞希、塔子による裏方メンツのチキンパーティーが開催中。そこへ帰宅した双見は、『昴へ』2巻発売のサイン会の開催を知らされる。“原稿の先にいる読者”に会うため、双見は佐藤と共に、故郷の書店へと向かう――', '2025/12/27 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4bfc9d5c-122f-44c7-9fe5-01a78261acc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('225f235c-cace-4b4c-b577-8d1bdac20538', '5898e098-31c6-4047-805c-7d509281ea69', 13, '100248867', '笑顔のたえない職場です。', '【シーズン1 最終話】「ご両親に挨拶に行きたいなって」サイン会の後、佐藤の申し出で双見の実家に向かう二人。大家族の大歓迎を受けながら、佐藤は双見のルーツを知ることになる。東京に戻り、いつも通りに仕事に励む二人だったが、突然立浪編集長から呼び出される。場所は高級料理店。そこで漫画家･双見に課された、新たな役割とは……', '2026/01/03 22:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aeda6c18-d3dd-43fd-ba5f-e17d19d43147.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f45196e8-d827-4387-8ccd-24b95874ad61', '擾乱 THE PRINCESS OF SNOW AND BLOOD', '', 'hulu', 'joran-the-princess-of-snow-and-blood', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6950f4de-1978-4751-9ee2-aaaff831366d.png?w=331&h=447&p=t', 'hulu', 2021, 1, 1, 'FINISHED', NULL, 129664, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('109194ba-e014-4010-9b82-5f207bf71c97', '杖と剣のウィストリア', '', 'hulu', 'wistoria-wand-and-sword', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/391f6f06-27fd-4b4f-bad3-8b9b63af044a.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 174576, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d056f431-b59a-4043-8e1c-e269586d965c', '109194ba-e014-4010-9b82-5f207bf71c97', 'hulu-wistoria-wand-and-sword-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b036f47d-5a40-45c3-a086-994758dd4a08.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aad37446-1444-4a19-9df6-184cf72f0719', 'd056f431-b59a-4043-8e1c-e269586d965c', 1, '100190449', '一振りの剣のように', '魔法学院の生徒でありながら初歩的な魔法すら使えないウィル。皆に落ちこぼれと見下されていた彼は、ある日、自分を蔑む同級生がモンスターに襲われている姿を目撃する。', '2024/07/12 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b036f47d-5a40-45c3-a086-994758dd4a08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e18bd18-7b8b-471e-b50f-83e93f8d07f7', 'd056f431-b59a-4043-8e1c-e269586d965c', 3, '100192071', 'Order & Watcher', 'エルファリアが学院全体へ下した勅令に従い、モンスターの素材を採取しにダンジョンへ向かったウィルは、道中で学院の後輩･アイリスと出会い、彼女と行動を共にする。', '2024/07/26 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5577c5e2-0096-495c-a3bd-0b63e6034eee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4be3bb01-da7d-4b01-9589-c7b5b8c8e3b4', 'd056f431-b59a-4043-8e1c-e269586d965c', 4, '100193824', '大祭前夜', '学院の一大イベント･魔導大祭を直前に控え、生徒たちが色めきだつ中、普段通りにドワーフ族の居酒屋でアルバイトをするウィル。そこへ学院TOP3の一人、ユリウスが現れる。', '2024/08/09 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5957350-2880-4df7-bb40-960f1970b9b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e5df2a8-b279-4622-b27b-12ffb2f19cdc', 'd056f431-b59a-4043-8e1c-e269586d965c', 5, '100194406', '号砲を上げよ', 'ドワーフたちの名誉を賭け、魔導大祭でユリウスと戦う決意をしたウィルは、コレット、シオンと組み、祭壇の王冠を奪い合う競技「奪冠 (クラウン･アタック)」に出場する。', '2024/08/16 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8052ba25-9f45-4851-98b8-10735907d381.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b62cb40-9325-4fe8-80e3-97415665953c', 'd056f431-b59a-4043-8e1c-e269586d965c', 6, '100195263', '矜持と熱情の間', '大観衆の前で、ウィルは突然チームメイトのシオンから攻撃を受ける。これまで抱いていた複雑な想いを魔法と共にぶつけてくるシオンに、ウィルは正面から向き合う。', '2024/08/23 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a5bf5c7-5f92-4f0f-9d00-5b8e8a320c6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9df860f-35cf-45aa-84d8-78b0521ed864', 'd056f431-b59a-4043-8e1c-e269586d965c', 7, '100195900', '十二の氷秘法', 'エルファリアが編み出した分身魔法を操りウィルを翻弄するユリウス。誰もが彼の勝利を確信した瞬間、誰よりもエルファリアの魔法を熟知しているウィルの反撃が始まる。', '2024/08/30 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ceaa7c96-8906-4a98-9eba-da64a2e4d838.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43e6664b-5c01-47ee-be66-4807f1dc5e08', 'd056f431-b59a-4043-8e1c-e269586d965c', 8, '100196674', 'Shall we date?', '魔導大祭で一躍注目株となったウィルを仲間に引き込もうと、彼に詰め寄る同級生たち。そんな周りの反応を見て焦ったコレットはウィルとのデートを取り付けるが――。', '2024/09/06 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/318ea07f-05fe-445e-a687-17c079948d6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('98eac45a-0b2a-4b02-b24c-90971ca7a8c4', 'd056f431-b59a-4043-8e1c-e269586d965c', 9, '100197855', '実習開始', '学院の実習の総決算、「総合実習」が始まる。危険なサバイバル実習――のはずが、リアーナたちパーティーメンバーが優秀過ぎるあまり、ウィルはお荷物となってしまう。', '2024/09/13 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4f73521-bd38-40b0-88a2-55df2f77957c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7eb58d85-a14c-48ef-a5b0-60e50c9dac39', 'd056f431-b59a-4043-8e1c-e269586d965c', 10, '100198857', 'ボクたちのユメ', '謎の巨大モンスターによってダンジョンの奥に落とされてしまったウィルたち。そこでウィルと2人きりになったイグノールは、「自分はエルフの落ちこぼれだ」と語り出す。', '2024/09/20 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03213aa3-a729-45f3-b66e-e2416a485f05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ca35e4b-00f6-499b-bb28-6497db497229', 'd056f431-b59a-4043-8e1c-e269586d965c', 11, '100199845', '臆病者の真名', '謎の魔導士たちが召喚したイヴィル･グランドデュークに加え、無数のモンスターに包囲されるという絶体絶命な状況。それでもウィルは「戦おう」と告げる。', '2024/09/27 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a66512c-f28b-4cfa-bb55-201c985364cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f93469fc-b2a7-4f98-becc-d15ca3e50d80', 'd056f431-b59a-4043-8e1c-e269586d965c', 12, '100200602', '杖と剣', '【シーズン1 最終話】強敵を倒し満身創痍のウィルたちに、モンスターの大群が襲い掛かる。もはやこれまでかと思われたその時、“至高の五杖 (マギア･ヴェンデ) ”のアロンが姿を現す。', '2024/10/04 17:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e322419-966f-49a0-88ef-ecad6cb24f03.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7cc21b4a-1ec4-4dd8-80a3-6e4644faa4c2', '織田信奈の野望', '', 'hulu', 'oda-nobuna-no-yabou', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50025846_series_art__338x600_oda_nobuna_no_yabou_a9497dcbb1ba2e02c63b56f0429bb137.jpg?w=331&h=447&p=t', 'hulu', 2012, 2, 1, 'FINISHED', NULL, 11933, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', '7cc21b4a-1ec4-4dd8-80a3-6e4644faa4c2', 'hulu-oda-nobuna-no-yabou-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/20d45c3f-3500-4292-9968-3ed99b8c7aa1.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('378e28c5-9a9e-47a5-819e-47d8fd9d3da3', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 1, '60717222', '信奈とサル', '突然、戦国時代にタイムスリップしてしまった高校生の相良良晴。合戦の真っ只中で足軽のおっさんに救われるも、なんとそのおっさんが流れ弾に当たって討ち死にしてしまった。おっさんの名は木下藤吉郎。「木下藤吉郎って、豊臣秀吉じゃねーか!」歴史が変わったことに動揺する良晴だったが、今度は騎馬武者に襲われている一人の美少女に出会う。彼女こそ、天下を目指す尾張の姫大名、織田信奈であった!', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/20d45c3f-3500-4292-9968-3ed99b8c7aa1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae5bb0e5-6be4-485c-82c2-6804b1ae938a', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 2, '60717240', '織田家、お家騒動', '織田家の足軽となった良晴は信奈の弟、織田信勝が姉の悪口ばかり言うのに腹を立て、思わず殴ってしまう。だが、信勝は織田家長男。本当なら家を継ぐ筈だったと、信奈に謀反を繰り返している超問題児だったのだ。良晴の首を要求され、悩む信奈。下手に拒めば、御家真っ二つの内乱になる。足軽が殴れば問答無用だが、侍大将に出世させれば交渉の余地はあるかも…。「一週間以内に米を八千石を調達しなさい!」相場の二倍という無理難題。だが、成功させなければ良晴の命はない!', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bc9a3b5a-9e51-42a1-b711-d5f0620b30e3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f8514eea-916e-4864-bf44-d264d8758e33', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 3, '60717235', '美濃動乱', '斎藤道三の息子、義龍が謀反! 美濃三人衆も敵となり、戦場で孤立する道三と明智光秀。だが、信奈は援軍を出さない。今、尾張は強大な今川家に狙われているからである。良晴は「それでいいのか?」と問い詰めるが、信奈の目尻に涙を見てしまう。「わたしが好きになった人はすぐに死んじゃうの…。」それが信奈の本心。戦国武将であると同時に一人の女の子でもある。そんな折、北近江の大名、浅井長政が政略結婚を持ちかけてくる。', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/da170139-28f1-4f3a-a084-b8f2093f829e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c570d5c8-fe6d-4cc7-b16f-6d9fbbb8930f', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 4, '60717231', '風雲! 桶狭間!', '織田軍の十倍に達する大軍で尾張へと侵攻を開始する今川義元。この危機を前にして、信奈は良晴を追放する。それが良晴を巻き込むまいとした心情の裏返しだと知り良晴は自分にしか出来ないことで信奈に報いようと思う。すでに幾つかの歴史を変えた今、自分が知っている通りには進まないかもしれない。だが、歴史を知っているから、死ぬはずだった人も救えた。「だったら、歴史は俺の味方だ!」良晴は五右衛門らと、織田軍が唯一勝てる場所――桶狭間へと向かう。', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a8c4c163-bf28-42ba-b3c9-582c87065818.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65d7084f-fb0f-4399-a684-bc72ac6ced7d', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 5, '60717246', '天才軍師調略', '美濃攻略へと出陣した信奈たちだったが、なんと連戦連敗させられてしまう。その原因は、日本随一と言われている天才軍師･竹中半兵衛の存在だ。美濃を攻める前に半兵衛を味方につける必要がある。史実通りならそれを成したのは豊臣秀吉、つまり――「こいつは俺のイベントなんだよ!」半兵衛を調略するため、光秀の案内で井ノ口の町へとやってきた良晴だが、そこにはまたしても浅井長政が! 長政の狙いも同じだった。はたして良晴は天才軍師を手に入れることが出来るのか!?', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8f248c6e-7442-4803-90b6-171ef02d0aa4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6aa6b61a-820b-4ad7-a692-b0d841cb9a59', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 6, '60717225', '墨俣一夜城', '美濃攻略上、最大の要所である墨俣。信奈たちは城を築こうとするが、そこは敵地の真っ只中。途中で攻撃を受け、勝家たちは工事を完成することが出来ずにいた。しかし、良晴にはとっておきの秘策があった。「一夜で城を造ってしまえば、邪魔したくても出来ないぜ」それは豊臣秀吉だけが完成させた前代未聞の作戦。秀吉が天下人へと上り詰めるきっかけとなった最大のイベントだ。信奈から託された瓢箪を旗印に、良晴は未来の建築術で墨俣一夜城に挑む!', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6a5f293d-5d8b-4da8-a6d1-9f76984fa039.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79a680e3-5b31-4f4f-975f-d6a30d31b067', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 7, '60717238', '信奈上洛', '武士の頂点に立つ征夷大将軍が襲われ、室町幕府が滅亡した。将軍を奉じて上洛する信奈の計画は台無しになったが、代わりに将軍の血を引く今川義元を担ぎ、上洛を開始するのだった。一方、本隊に先駆けて京都へと偵察に向かった良晴が目にしたのは、統治者を失った無法地帯。この国を作った神々の子孫が住むやまと御所までもが襲われていた。「ここって、やんごとなき御住まいじゃねーのか!?」良晴たちは悪漢どもを撃退し、一人の美しい少女を救うのだったが…。', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5a8287fc-175a-4db6-8c00-7bed8205a0e2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b49d49c4-4052-4921-b154-eb54cb93a01a', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 8, '60717236', '黄金の自由都市･堺', '関白･近衛前久は今川義元の将軍宣下に対し、十二万貫もの大金を要求してきた。困った信奈は日本最大の貿易都市･堺から金をかき集めようとする。しかし、堺では豪商の今井宗久と津田宗及が激しい権力争いを繰り広げており、巻き込まれた良晴は新たな名物料理を生み出すため、光秀と対決しなければならなくなる。「サル人間には絶対に負けません!」異様なまでにやる気の光秀、織田家でも権力闘争勃発か!? 光秀と戦う良晴が考えた秘策とは?', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/212edd35-89ca-4ee7-87bd-d868bd1f43cf.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8af1ffd3-1575-4adc-964f-fe3bdc4ea1b9', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 9, '60717219', '清水寺攻防', '信奈の天下統一を阻むため、張り巡らされる織田包囲網。武田信玄や上杉謙信が動いたとの噂も流れ、尾張滅亡の危機が迫る。京を捨て、全軍撤退しようとする信奈を引き止める良晴。「天下を目指すなら、ここが踏ん張りどころじゃねーのか!?」しかし、本国には大切な人たちがいる、それを守れなくて何が天下人か! 良晴と喧嘩別れになった信奈は、わずかな守備隊だけを残して尾張へと引き返すが、その機を逃さず、妖将･松永久秀が京を襲う!', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b4deca7b-1be1-484e-b886-f0933247fa32.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('197587b6-529c-4387-ad6d-ade51b4c9563', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 10, '60717229', '信奈絶体絶命', '京を治めたものの、北陸には反織田最大勢力･越前の朝倉義景がいる。信奈は良晴を京の守りに残し、その隣国･若狭へと進攻した。歴史通りなら、織田は朝倉を攻めて大敗している。史実と違うのに困惑しつつも安心する良晴だったが、信奈は若狭と見せかけて越前を奇襲する作戦を立てていた。事実を知った良晴は慌てて信奈のもとへ向かう。「信奈、逃げろ!」だが、時すでに遅く、織田軍は浅井･朝倉連合軍に挟撃されてしまうのだった。', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2d64b756-39f2-4a33-aa60-37801f3824ad.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60d56e1b-2eb2-4347-8b62-7a0cb3d39d74', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 11, '60717230', '金ヶ崎の退き口', '信奈を逃がすため、敵を引きつける囮り役となった良晴。三万もの大軍に対し、良晴と残ったのは川並衆ら五百名。数の差は歴然、共に戦ってきた仲間たちは一人、また一人と倒れていった。敵は大将の良晴を狙い、味方は大将を守るために進んで命を投げ捨てていく。この状況に良晴は上に立つ者、信奈の心境を痛感する。「重い…。重過ぎるぜ…。」朝倉軍の猛攻に万策尽きた良晴はついに断崖へと追い詰められてしまう。', '2016/05/12 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b0e418f2-ae6b-49c3-9564-ba0b0f81944d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3e0696e-6658-40b4-badc-11145ff57da3', '772ab3e6-6dca-46e0-9b73-3ff3440c7e7e', 12, '60717232', '天下布武', '良晴、帰らず。悲嘆の淵に沈む信奈は弔い合戦だと、敵がたてこもる聖地･比叡山を包囲する。歴史通りなら織田信長は比叡山を焼き討ちし、乱世の魔王へと成り果てた。「お前に魔王は似合わない。今のままの信奈でいてくれ!」そう訴え続けた良晴はもう信奈のそばにいない。陰謀と共に日本を支配しようとする諸悪の根源たちは目の前にいる。はたして織田信奈が選んだ道は――!', '2016/05/12 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7e9a4d51-7417-4f96-8c0a-b6ea5e844b8a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4637ec2a-5f31-4069-bafd-10a59c86e588', '食戟のソーマ', '', 'hulu', 'food-wars-shokugeki-no-soma', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d306de2-65ed-451b-b9c8-b5fc0007a357.jpg?w=331&h=447&p=t', 'hulu', 2015, 1, 1, 'FINISHED', NULL, 20923, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('bc6517e3-d030-4a96-a395-5a9eb7f04039', '4637ec2a-5f31-4069-bafd-10a59c86e588', 'hulu-food-wars-shokugeki-no-soma-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff50cd41-ee23-4182-be01-a8e5c0e739ec.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f12fd344-062c-42fd-a5b4-4295a4ca0603', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 1, '100002975', '果て無き荒野', '下町で人気の定食屋「ゆきひら」。店主の息子である中学3年生の幸平創真は、父を越える料理人になろうと店を手伝いながら修行に励んでいた。ある日、「ゆきひら」の土地を狙う地上げ屋たちに、創真は「客が求める料理を出せなかったら店をたたむ」と宣言してしまう。地上げ屋たちは卑劣な方法で冷蔵庫の肉をダメにし、その上で創真に「肉料理」をオーダーした…。', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff50cd41-ee23-4182-be01-a8e5c0e739ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd682a48-fbf3-498c-a1a9-dcdb0469a7ba', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 2, '100002976', '神の舌 (ゴッドタン)', '父･城一郎に言われて創真が向かった先は、日本屈指の料理学園「遠月茶寮料理學園」。編入試験の審査員･薙切えりなは、内部進学の学園生。彼女は人類最高の味覚「神の舌 (ゴッドタン)」を持ち、幼い頃から日本中の有名店の味見役を務めていた。えりなに「才能なし」と言われたら、料理業界では生きていけない。編入希望者は恐れるあまり、試験から逃げ出すのだが…!?', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78576f33-60ca-4c75-9fd0-1f3a51bc05c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c60f3bb-9a86-4974-a4f4-687cdc795238', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 3, '100002977', 'その料理人は笑わない', 'なんとか遠月学園の編入試験に合格した創真。だが始業式の編入生挨拶でいきなり豪胆な宣言をし、生徒達から嵐のようなブーイングを受けてしまう。創真のような悪目立ちはしまいと決心する女生徒･田所恵。あと1回でも不可もしくはE評価を取ったら即退学なのだった。ところが最初の授業で創真とペアを組むことに。さらに運悪く、この授業の講師･シャペルは評価が厳しいことで有名な「笑わない料理人」だった…!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1b82488-41da-45d6-bdd7-eb094513cb77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ba975ee-9575-4341-b408-d48c7314e2c0', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 4, '100002978', '極星のマリア', '学生寮への入寮を希望していた創真は、期待に胸を膨らませて「極星寮」へ向かった。たどり着いたそこは、荒れ果てた外観の不気味な洋館。そして怒号とともに、寮母である大御堂ふみ緒が現れる。料理を作り、ふみ緒にその味を認められた者のみ入寮が許される―。創真は入寮をかけ、極星名物「入寮腕試し」に挑む!!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53939df9-16bd-4f1d-a3a7-452fc53ea570.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1aa3a22b-7cdb-4a57-8366-f11b31902d46', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 5, '100002979', '氷の女王と春の嵐', '極星寮に住む唯一の2年生･一色慧。彼は遠月十傑の1人だった。十傑入りを目指し、創真はさっそく料理勝負を挑むが、そこで初めて遠月学園伝統の料理対決「食戟」のルールを知る。一方その頃、えりなは自分専用の調理棟の建設のためちゃんこ鍋研究会の主将と「食戟」を繰り広げていた…。', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0159d26-5337-4c36-8b5f-f111ebe2b81f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd44b481-0da0-499c-8e19-c30c4d0f8ce5', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 6, '100002980', '肉の侵略者', '学園内の料理研究会に興味を持った創真は、恵を連れて「丼物研究会」へ見学に行く。出迎えたのは意気消沈した主将･小西ただ1人。丼研はもうじき、えりなの手で潰される運命にあると言う。丼研を潰すのが惜しいと感じた創真は、小西に代わって初めての「食戟」に挑む!!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f3cd6f5f-7b88-4f10-8385-72004ccd8e0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06e6a994-71a7-4d7b-aaf1-a45be8cc4621', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 7, '100002981', '静かなる丼、雄弁な丼', '水戸郁魅VS幸平創真の「食戟」開戦! えりなを含め会場の誰もが、ミートマスターこと郁魅の勝利を確信していた。一方の創真は、登場しただけでブーイングの嵐…。「食戟」のテーマは丼、メイン食材は肉。果たして創真は丼研を守ることができるのか!?', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fff8aab-7255-4af4-a288-ae2125b8d0f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5a58053-e7c2-453d-b65a-34710e2a0c6c', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 8, '100002982', '発想と創造の協奏曲', '遠月学園高等部、最初の地獄と言われる「宿泊研修」。この合宿では連日何十人もの生徒が強制送還･退学となり、生徒数が半分以下まで減るという噂もある。研修場所は、「遠月リゾート」が経営する豪華ホテル。創真たちはそれぞれの想いを胸に、生き残りをかけた地獄の合宿へ!!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7f86c16-0d79-446f-a63d-ee4c4f3a80a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d27c2a6-1785-4ade-9a48-f9394c84ff66', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 9, '100002983', '山を彩る衣', '遠月OG･乾日向子の課題は「ここにある食材で日本料理を作る」こと。調味料以外は建物の周囲で確保しなければならない。合鴨を見事に捌き、一発で合格したアルディーニ兄弟。創真をライバル視するタクミは、まだ調理に入らない創真たちを挑発する。創真は「ここにある食材」という言葉である秘策を思いつき、恵とともにフィールドへ駆け出す!!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e9e8480-c641-4f25-88f5-9b611be93c19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9baea691-7c3e-45b6-a671-3ac548bbf3d4', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 10, '100002984', '至上のルセット', 'なんとか合宿1日目を乗り切った極星寮メンバー。恵は創真のサポートをちゃんとできたことで手ごたえを感じ、少しだけ自信を持ち始めていた。迎えた合宿2日目。創真と恵は、昨日1日で30人以上を退学にしたと言われる、フランス料理の天才･四宮の課題に取り組む…。', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7803832-5114-468f-9149-44c9e1de04dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('180a278b-1dce-4076-9a1e-359adc1f981a', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 11, '100002985', '東から来た魔術師', '恵の退学を取り消すため、無謀にも四宮へ「食戟」を申し出た創真。四宮は創真との「食戟」を拒むが、堂島の命令で半ば強制的にこの勝負を受ける。四宮に挑む創真&恵、しかもメイン調理は恵という条件付き! 創真たちが勝てば恵の退学は取り消し。だが負ければ、恵だけでなく創真も退学することに。地下の厨房で、密かに「非公式の食戟」が始まる―!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea8653ad-5190-4bec-b86f-27f2e92128d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b19f0d91-6b5c-464e-9311-7a2cd9727620', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 12, '100002986', 'ひと皿の記憶', '四宮VS恵･創真の「非公式の食戟」開戦! 懸けるのは、恵と創真の退学―。四宮の料理に続き、恵の料理の審査が始まる。初めて恵がメインシェフとなって作った料理。それは、四宮の課題「9種の野菜のテリーヌ」を意識した、7種の野菜の層による「虹のテリーヌ」だった!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e816c6c-3f92-4e42-93b6-8f74686be72f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad497c0d-931b-4312-8233-d6c93dbedb2c', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 13, '100002987', '夜明け前の卵たち', '合宿3日目の夜。創真たち極星寮のメンバーは、過酷な課題をクリアして、何とか全員生き残っていた。研修のしおりには、今日の就寝時間が書かれていない。極星寮メンバーが不思議に思っていると、召集のアナウンスが入る。堂島が疲労でボロボロの生徒たちに与えた新しい課題、それは明日の朝までに「卵を使った朝食メニュー」を考えること―!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/889fbf37-3209-4618-9ba8-ff61ea5f7d73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c43d069-31f8-4721-8157-e75f1c98b1a3', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 14, '100002988', 'メタモルフォーゼ', '課題合格の条件は、「卵を使った朝食メニュー」をビュッフェ形式で2時間以内に200食以上食してもらうこと。創真の「スフレオムレツ」はお客さんが手に取る前にしぼんでしまい、残り30分でまだ10食以下と絶望的な状況。創真は城一郎の言葉を思い出し、起死回生の一手に懸ける…!!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b57f9aa2-6c9e-42dd-b6d3-3c74f6fc4511.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48c26fc0-e8ff-4cd5-8751-68874e5a016a', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 15, '100002989', '「修羅」と呼ばれた男', '宿泊研修が終了し、生き残った生徒たちは遠月学園に戻る。そんな中、創真は帰りのバスに乗りそこねて呆然と立ち尽くしていた。一方、えりなも部屋に忘れ物をして別の車で帰ることに。運良くえりなと出会えた創真は、同じ車に乗り…。気まずい車中でえりなが語る「秋の選抜」とは!? そして極星寮では意外な人物が待っていた―。', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a37bc43a-131e-455e-a501-30865bfa540e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7609e9f4-9fe9-40ac-9afd-7514ddccb6d2', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 16, '100002990', '万里を駆ける料理人', '極星寮にふらりと現れたのは、創真の父･城一郎。城一郎は遠月学園、そして極星寮のOBだった!「お前がどれだけ成長したか見せてほしい」城一郎は創真に料理勝負を持ちかける―。審査員はふみ緒･一色･恵の3人。創真VS城一郎、久しぶりの「親子対決」が始まる!!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b518a992-1b6b-4f62-b9f2-9ae59a26c676.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48a731f1-422e-473c-815d-ff622c5bf7db', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 17, '100002991', '官能の唐揚げ', '創真は連休を利用して、編入以来初めて実家へ帰る。店の風通しをするだけのつもりだったが、「お食事処ゆきひら」の復活を待っていた人が押しかけ、少しだけ再オープンすることに。店内は大盛況。だが、その片隅で「すみれ商店街」の若旦那衆が俯いている。どうやら商店街の客を『駅ナカ』に取られてしまい…!?', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f8f4b35-afdd-43ad-8764-32379070a81c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58f3697a-6a21-4534-9b24-cb5bfa96fd39', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 18, '100002992', '青春の唐揚げ', '「お食事処ゆきひら」がある「すみれ通り商店街」は、駅ナカに出来た唐揚げの専門店「もず屋」に客を奪われていた。流れてしまったお客さんを取り戻すべく、創真は倉瀬や助っ人の肉魅らと一緒に対抗策を考える。創真たちが辿り着いたキーワードは、「食べ歩きの唐揚げ」! すみれ通り商店街…唐揚げ夏の陣、開戦!!', '2022/12/19 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/964063aa-7017-4367-9389-1588d82fb622.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33d5353c-75ce-4706-a421-a48b8c18c0e6', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 19, '100002993', '選ばれし者', '遠月学園、1学期の終業式。学園内の掲示板には、『秋の選抜』に出場する生徒の名前が張り出されていた。創真をはじめ、極星寮のメンバーやタクミ、肉魅など、実力のある1年生たちが名を連ねる。予選のお題は『カレー料理』。創真はカレーについて話を聞くために、城一郎から教えてもらったある“先輩”のもとへ向かう。', '2022/12/19 00:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e7bcc07-e454-4b4b-80be-69554aa63c18.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8e3c027-6e5b-4770-95af-6fdda4396d04', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 20, '100002994', '龍は臥し、空へ昇る', 'スパイスを知り尽くす葉山と出会い、カレー料理の奥深さを知った創真と恵。『秋の選抜』に出場する1年生たちは夏休みの期間を使い、それぞれ自らのカレー料理と向き合っていた。そして迎えた試合当日。『秋の選抜』本選出場をかけた予選が幕を上げる―!!', '2022/12/19 00:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/faf1d561-4ee7-44d9-a69a-f24e72c752d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5c815b2-3bb9-4610-9812-124970e79b9b', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 21, '100002995', '未知なる既知', 'ついに始まった『秋の選抜』の予選! 生徒たちはA･Bの2ブロックに振り分けられ、調理を開始する。本選に出場できるのは各ブロック4名のみ。Aブロックの創真は、優勝候補の葉山らが注目を集める中、マイペースで自分の調理を進める。一方、Bブロックでは恵が地味に作業をしていた。それまで目立たなかった恵は、ある特殊な食材を取り出し…。', '2022/12/19 00:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/157c8fe7-7528-40a0-9420-5762ce9e998b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7f4add7-9a31-4a90-bac7-20732e09eb75', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 22, '100002996', '日常を越えるもの', '『秋の選抜』予選、各ブロックの審査が始まる! Bブロックではすでに緋沙子らが高得点を出し、会場を沸かせていた。続いて北条やタクミ･イサミ兄弟、アリスも次々とオリジナルのカレー料理を披露していく。そして最後に、観客も審査員も期待していない恵のカレー料理。創真から勇気をもらって作り上げた、恵の料理とは―?', '2022/12/19 00:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5eae48e-8691-4cac-90b6-5c7dba39b027.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f395a4b6-a1a2-44b7-876a-ca1c48b2f1da', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 23, '100002997', '華開く個の競演', '激闘が続く『秋の選抜』予選大会。Bブロックからは、アリス、緋沙子、タクミ、そして恵が本選に出場! 一方、Aブロックでは審査員の千俵なつめが0点を出し続け、いまだ高得点の選手が現れない。次に登場するのは、アリスの側近である黒木場リョウ。謎に包まれた黒木場の料理が、いよいよ姿を現す!', '2022/12/19 00:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fe1ebe2-3fb2-4b94-a78c-379df49bb3f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad2f3bfa-06b5-4f2f-a416-d6fb23d96976', 'bc6517e3-d030-4a96-a395-5a9eb7f04039', 24, '100002998', '戦士たちの宴', '【シーズン1 最終話】ダークホースの黒木場がトップのAブロック。その審査もいよいよクライマックス! ついに登場する、スパイスの天才で優勝候補の葉山アキラ。「香りの爆弾」のようなフィッシュヘッドカレーに、会場中が圧倒される。葉山の審査を終えて、一気に沸き立つ場内。そして満を持して―創真のカレー料理が登場する!', '2022/12/19 00:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ae4a4e3-67a7-468a-a6f0-552d46109580.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('24877eeb-d759-470a-ae42-db4d7c71fd59', '4637ec2a-5f31-4069-bafd-10a59c86e588', 'hulu-food-wars-shokugeki-no-soma-s2', '弐ノ皿', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a13c769-e587-46f8-a946-55e7b1c0ac67.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('879047fb-79c9-4760-a726-9335d97aa947', '24877eeb-d759-470a-ae42-db4d7c71fd59', 1, '100002999', 'その箱に詰めるもの', '「秋の選抜」本戦･1回戦の組み合わせが決定し、 第1試合から出場することになった創真。 そして創真の対戦相手として姿を現したのは、 分子ガストロノミーに基づいた調理を得意とする薙切アリスだった! 2人の対決テーマは『弁当』。 最先端技術を詰め込んだ常識を超えるアリスの弁当の中身は? そして、創真の秘策“進化系のり弁”とは…! 気になる審査の行方は…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a13c769-e587-46f8-a946-55e7b1c0ac67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce9ecbe7-482c-4a94-b821-540fea0490c7', '24877eeb-d759-470a-ae42-db4d7c71fd59', 2, '100003000', '交錯する光と影', '「秋の選抜」本戦･第1試合は渾身の“のり弁”を披露した創真が見事アリスに勝利。そして続く第2試合、田所恵と黒木場リョウの対決テーマは『ラーメン』! ラーメンの命ともいえるスープの素材にそれぞれが選んだのは…!? 性格も料理の特徴も正反対の2人が今、激突する!!', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24546d77-47ed-4f0a-89c4-0bfd76179410.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c11f42c1-5989-425e-ae19-95821e2954c2', '24877eeb-d759-470a-ae42-db4d7c71fd59', 3, '100003001', '『玉』の世代', '「秋の選抜」本戦･第2試合、ついに決着! 気になるその結果は…!? 日が変わった第3試合では優勝候補筆頭･葉山アキラとえりなの側近である新戸緋沙子が激突! 究極の『ハンバーガー』対決の軍配はどちらに!? 一方、第4試合で対戦するタクミと美作の間には何やら不穏な空気が…?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c589aa4b-84e1-4fef-9dbb-250a1072f79b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07ade0bc-9c41-4c0f-abab-242161f07968', '24877eeb-d759-470a-ae42-db4d7c71fd59', 4, '100003002', '追跡者', 'タクミ･アルディーニと美作昴が対決する第4試合。この試合は準決勝進出最後の1枠を争うだけでなく、同時に“食戟”が行われることに! アルディーニのプライドを傷付けられた屈辱を返すため、勝利に燃えるタクミ。しかし、テーマである『デザート』の調理を始めると美作はタクミと全く同じ品を作り始め…!? 謎に包まれていた美作の実力や戦略が今明かされる!!', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94c614e7-53d8-428d-81cb-c267b0e35e27.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e55a319b-d025-4b7d-90f9-a2b3a635c8cd', '24877eeb-d759-470a-ae42-db4d7c71fd59', 5, '100003003', '一口目の秘密', '創真の準決勝の相手は、タクミを倒し勝ち上がってきた美作! しかも、美作からの申し出を受け、自らの料理人人生を賭けた食戟を行うという。さらにはどうせ予測されるからと、テーマの『洋食のメイン』にあわせて作る品を明かしてしまう! 創真は美作のパーフェクトトレースにどう立ち向かうのか…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81804731-a023-44df-934b-8d041987f15d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23135b41-45e2-424b-abc7-cea47b95cff7', '24877eeb-d759-470a-ae42-db4d7c71fd59', 6, '100003004', '朝はまた来る', 'ついに始まった創真VS美作の“ビーフシチュー”対決! メイン食材の牛テールをコピーされた上、美作の方は得意のアレンジで審査員と観客の心をつかみ始める。しかし創真にも、美作の裏をかくとっておきの作戦が!! 果たして、創真が料理人人生をかけた食戟の結果は…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1fcf8ead-8f12-42ef-8fc5-d21b2ff01dbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c43397a2-a8b0-4601-8721-4329ce73da52', '24877eeb-d759-470a-ae42-db4d7c71fd59', 7, '100003005', '喰らいあう獣', '創真の勝利で幕を閉じた準決勝第1試合に続き、黒木場リョウと葉山アキラによる準決勝第2試合が開戦! テーマは第1試合と同じく『洋食のメイン一品』。魚介を使ったインパクトのある料理を得意とする黒木場と、いくつものスパイスを巧みに使い、香りで審査員を魅了してきた葉山。決勝進出最後の一枠をかけた戦いが今始まる!!', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba5fde84-ee37-4108-9dac-430f809eba09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee1c89d8-c794-4dbc-bf57-ebee6b9be029', '24877eeb-d759-470a-ae42-db4d7c71fd59', 8, '100003006', '旬を巡る戦い', '決勝戦のお題『サンマ』はゆきひらでも秋の定番の食材。順調に試作が進むかと思いきや、サンマを買い付けに魚河岸を訪れた創真は “目利き”の時点で自分が黒木場･葉山に劣っていることを知る。旬の食材を扱う勝負では一番の素材をつかめるかどうかが、勝敗を分ける大きなカギ! 思わぬところでハンディを背負った創真に、起死回生の一手は残されているのか…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/976b3fe3-84e1-4302-9222-fd9923212211.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce747998-e2d5-49e7-bb82-7f2c43ef9353', '24877eeb-d759-470a-ae42-db4d7c71fd59', 9, '100003007', '秋を告げる刀', '「秋の選抜」決勝戦がいよいよ開幕! 遠月史上初! 3名で争われる異例の一戦の食材は『サンマ』。目利きの段階で差をつけられた創真は、サンマにひと工夫加えることでその差を埋めようとしていた。光り輝く新鮮なサンマを手にした葉山･黒木場に対し、創真が取り出したサンマは…!? 月明かりの下、次々にサーブされる三者三様のサンマ料理が審査員を唸らせていく!!', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81512dcb-d6b8-408f-a9e6-4dc3af2a676e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8123b77a-6f22-4764-b266-8606e7cb7750', '24877eeb-d759-470a-ae42-db4d7c71fd59', 10, '100003008', '新たなる『玉』', '黒木場の“秋サンマのカルトッチョ”、葉山の“炙りサンマのカルパッチョ”に及ばないと思われた創真の“ぬかさんまの炊き込みご飯”には、秘密が隠されていた! 考え抜いた末に生み出したその秘策は、果たして審査員の心を揺さぶれるのか…!? 三つ巴の『サンマ』決戦、勝負の行方は…!!', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89d3a99b-eda8-476e-a2fe-1f808595930a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b8e2c5b-70c8-4179-8f45-a521f3f8e163', '24877eeb-d759-470a-ae42-db4d7c71fd59', 11, '100003009', 'スタジエール', '「秋の選抜」を終えたのも束の間、外部のさまざまな料理の現場で実戦を学ぶカリキュラム“スタジエール”がスタート! 合格基準は“目に見える実績を残すこと”。外の世界に触れられると意気揚々な創真は緋沙子とともに町の洋食屋に派遣されることに! ゆきひらでの経験を活かして、順調に研修をこなしていく創真だったが、“実績を残す”の本質はまだ先にあった…! 創真たちはスタジエールに合格することができるのか…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4e0cbd0-f9cf-4ba6-9d30-4b2c9513b58c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b673c10-b764-4d07-861f-d333c67f8e3a', '24877eeb-d759-470a-ae42-db4d7c71fd59', 12, '100003010', '魔術師再び', '第一のスタジエールを見事に突破した創真は、次なる研修先へ。創真が訪れたのは「SHINO''s TOKYO」…以前、恵の退学取り消しを賭けて食戟で戦った相手･四宮小次郎が新たにオープンさせる「SHINO''s」の初の日本支店だった! 今まで経験したことのないフランス料理店の調理場で、創真は1週間生き抜くことができるのか…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbf19afc-f90c-4f3c-8467-e7d6f47aef30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7ed901d-5d7d-4681-92b0-c76741f1ebff', '24877eeb-d759-470a-ae42-db4d7c71fd59', 13, '100003011', '威風堂々', '【シーズン2 最終話】「SHINO''s TOKYO」でのスタジエールも、残すところあと1日。めきめきとフランス料理の技術を身に付け、厨房の人々にも認められつつあった創真は、新作コンペに参加できることに! 果たして創真は、四宮の舌を唸らせ、「SHINO''s TOKYO」のメニューに自分の料理の名を刻めるのか!? そして、スタジエールの合否の行方は…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d81e76d-3197-430e-aba0-6ce2b0b91734.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4814ac26-6ea3-4f72-bbe3-e9536454dc48', '4637ec2a-5f31-4069-bafd-10a59c86e588', 'hulu-food-wars-shokugeki-no-soma-s3', '餐ノ皿', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70ce4af9-770a-418d-90a1-cdd158ddeae8.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b3faa3a-a6a3-4eea-b5ba-9899936f7820', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 1, '100008204', '十傑に挑む', '創真は、秋最後の一大イベントである学園祭「月饗祭」が近々開催されることを知る。十傑第八席･久我照紀から「何かひとつでも料理で勝てるものがあれば食戟を受けてもいい」と言われていた創真は、久我に勝負を挑むため「月饗祭」への参戦を決める! そこで、創真は久我の根城である中華研究会へ行ってみることにするが…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70ce4af9-770a-418d-90a1-cdd158ddeae8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e905c10-afc5-47fb-b615-a1bbe4dac3f6', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 2, '100008205', '『麻』と『辣』', '中華研の目の前、しかも料理ジャンル「中華」で月饗祭への出店を決め、久我へ宣戦布告した創真! 一方、アリスと黒木場、葉山が組んで模擬店を出すことになったりと、ほかの仲間たちも月饗祭への準備を着々と進めていた。そんななか創真は、恵に手伝ってもらいながら模擬店で出す料理の試作を始めるものの、なかなかうまくいかず…?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/653d326f-1027-41a4-875d-4190629d8b10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48b87c87-9bef-4b88-acef-5fce4aa2eef0', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 3, '100008206', '月饗祭', 'いよいよ開幕した月饗祭! 創真の模擬店メニューは、石窯で作る胡椒餅 (フージャオピン)! しかしお客さんは、豪華な店構えの中華研のほうへ次々と流れていってしまう。結局、一日目は大赤字…! 赤字を出したら退学という条件がある学園祭で、創真は早々にピンチに! この状況を覆せるのか!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3d339fa-782c-4907-b724-ba203de45709.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bff8a32c-1df1-4766-92d5-fa34ab4167af', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 4, '100009555', '若き獅子たちの群れ', '月饗祭･三日目! 新メニュー『なんちゃって担仔麺』の追加により売上を伸ばしてるものの、2日連続売上1位の中華研にはまだまだ及ばない。その状況を打開すべく、助っ人を呼びさらなる新メニューを売り始める! その料理とは、中華研と同じく麻婆豆腐! しかしそこには驚きの秘密が…!? 創真の作戦とは一体!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae475861-9342-4ddd-b787-a34a83808ec2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81fa0f3c-c9f6-4423-a118-8057af750116', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 5, '100009576', '翳 (かげ) りゆく食卓', 'いよいよ迎えた月饗祭最終日。ついに創真と久我の勝負が決着! 果たしてその勝敗は…!? 中央エリアの営業時間終了後、創真と恵は、竜胆の誘いで山の手エリアにある第一席･司瑛士の店へ行くことに! 第一席が提供する料理とは!? 一方、えりなの店には、とある人物が来店し…?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4e305b7-3ca9-4c2f-8c0d-ff8d76663f06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b622f96b-2f2e-4ffd-b47e-5415b1135dd6', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 6, '100009577', '囚われの女王', '遠月十傑の半数以上が寝返り、えりなの父親･薙切薊が遠月の新総帥へ就任! その情報は遠月内外に衝撃を走らせ、学園は不穏な空気が漂っていた…。そんななか、創真が部屋に戻ると、元総帥である仙左衛門が待ち構えていた…! そして、仙左衛門の口から、えりなの衝撃の過去が語られ…?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df352924-8081-4053-8b21-421bf26d14c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a02a60e3-33a4-4e7e-be36-edeabcf1cf35', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 7, '100009578', '崩れゆく学園', 'アリスと緋沙子の手助けにより実家を抜け出し、極星寮へとやってきたえりな。一方、薊は自身の選んだ生徒だけで構成する「中枢美食機関 (セントラル)」を発足。さらにゼミ･研究会･同好会等自治運営勢力の解体を宣言! その対象には、極星寮も入っていた…!!', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d10643f-7741-4dc7-aa14-e3c9a5351a97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d35236f-aec5-4a1d-9b9a-cacbe2887959', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 8, '100009579', '錬金術師 (アルキミスタ)', '創真と叡山による、極星寮の解体を賭けた食戟が始まった! これまで類まれなコンサルティングの能力を見せていた叡山の料理の実力が明らかになる…!? お題となる食材は、鹿児島産の地鶏『さつま地鶏』。しかし、審査員を叡山が買収している八百長勝負。創真に勝算はあるのか…!?', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57d2068f-0a3d-48fb-8b4e-588cc3217506.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4553b72f-66e2-4d81-93b6-11f9dba9a18d', '4814ac26-6ea3-4f72-bbe3-e9536454dc48', 9, '100009580', '残党狩り', '極星寮解体の危機は乗り越えたものの、薊政権の改革は引き続き進められていた。薊により第七席･一色、第三席･女木島、第八席･久我の3名が十傑から除名されてしまう。そして、中枢美食機関のメンバーたちによって、解体撤回を望む研究会やゼミを潰すための『残党狩り』が始まる…!', '2022/12/19 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d45b0b2-9a2d-4904-9ab8-c53072cf5064.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1708e10e-ac3e-4190-b80f-3daac87a6985', '心霊探偵 八雲', '', 'hulu', 'psychic-detective-yakumo', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fd4b99b-3a02-4309-beb9-df2005896ce7.jpg?w=331&h=447&p=t', 'hulu', 2010, 3, 1, 'FINISHED', NULL, 7662, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('319d734f-6df3-4ea3-97a7-9296ff15fd2c', '1708e10e-ac3e-4190-b80f-3daac87a6985', 'hulu-psychic-detective-yakumo-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03c880b3-d6d2-4a59-873b-bcdfcb086223.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25eeb042-d72c-4bfc-82b5-6b4c09e3b1ed', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 1, '100102237', '開かずの間', '大学の旧校舎で幽霊に遭遇した小沢晴香は映画研究同好会の斉藤八雲という人物に相談を持ちかけた。八雲には不思議な能力があるとのうわさがあったのだ。「自分には死んだ人の魂が見える」と言う八雲の言葉を、果たして信じてよいものか… 真相解明に動き出した八雲と行動をともにした晴香は、事件の裏側に潜む驚くべき真実とともに、八雲が抱える「ある秘密」を知ることとなる…。', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03c880b3-d6d2-4a59-873b-bcdfcb086223.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59d38b3f-f25f-4b21-a3ef-e1eb5bb887cc', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 2, '100102238', '白狐の祟り', '事件解決の報酬を八雲に払うため、晴香はアルバイトに勤しんでいた。そのバイト先の近くに、移築工事中の古い神社があった。ところが、神社に幽霊が度々出没、さまざまな怪奇現象が起きるため、工事は難航していた。幽霊と遭遇した晴香は、逃げる途中で見知らぬ僧侶と出会う。その僧侶の左目は八雲と同じく赤い瞳であった。一心と名乗る彼と、八雲の関係は?', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff8e5086-2ee9-4942-a515-b6e9e4d423de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('787f7163-0ef9-496e-bcd5-a829c210d138', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 3, '100102239', 'トンネルの闇', '北東新聞の記者･土方真琴が、事件の現場で撮影した写真に心霊が映っていた。その写真を見た後藤刑事は八雲を捜査に巻き込もうと決意する。一方、晴香は幽霊が出現するというトンネルで怪事件に遭遇し、八雲のもとをたずねていた。心霊写真と幽霊トンネル。二つの怪奇現象が、八雲の推理によって一つにつながったその時、晴香の身に、かつてない危機が迫ろうとしていた…。', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fec526d7-be3a-40c4-bcea-544c2fa63272.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10b347c2-fd37-48a7-b80a-6b8cd601892b', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 4, '100102240', '魂をつなぐもの ～憑依～', '連続女子高生殺害事件の取材をおこなっていた真琴が、霊に憑依されてしまった。一方、晴香は、友人の真由子から幽霊を目撃したと相談を受けるが、八雲に話を持ちかけずに単独で行動を開始する。後藤の依頼を受けて真琴と面会する八雲。確かに真琴には霊がとり憑いていた。その霊の正体を探るうちに、八雲は、忌まわしき過去と対面することに…。', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/beefa347-b625-481e-8d61-cdf0c8f76079.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8dc00e31-5733-4057-b3fe-d281631dd420', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 5, '100102241', '魂をつなぐもの ～蘇生～', '事件の捜査に復帰した八雲は、晴香や後藤とともに行動を開始する。だが彼らの行動は「ある人物」にマークされていた。人の心の闇をかぎつけ、言葉巧みに誘導し、相手に罪を犯させる。その男の両目は赤い…両目の赤い男の画策によって死の危機が晴香に迫る。一方、男の存在に気づいた八雲と後藤が現場に急行する。果たして八雲は晴香を守れるか? そして、両目の赤い謎の男の正体は!?', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dafd5194-b9b0-4944-8bc5-bb7e5065b069.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a9f3760-7178-4f0e-85a2-c723d2da78dc', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 6, '100102242', '格安の物件', '晴香は友達の影響もあって、八雲と自分の関係についてあれこれ考え始める。友達? 恋人? それとも…そんな折、不気味な女の幽霊が現れるという不動産物件の相談が舞い込む。微妙な思いを胸に、謎解きに挑む晴香は、幽霊が出るという部屋で八雲と二人きりで過ごすことに。怖さとは別の緊張感を覚える晴香。と、その時、八雲が近づいてきて…。', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c544433-a980-4c42-b112-3b30f2b88a00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b6d209f-6b68-4c07-9ae5-edefccc5c3b6', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 7, '100102243', 'つながる想い ～罠～', '十五年前に発生した『七瀬邸一家四人殺害事件』。時効制度の廃止に伴い、容疑者が逮捕に至らずのこの未解決事件に、特別捜査本部が設置されることになった。捜査から外されてしまった後藤と石井の二人は、事件現場で撮影されたビデオに幽霊が映っているという真琴の情報から、幽霊映像を八雲に見せて捜査本部とは別に捜査しようと考える。ところが、映像を見た八雲は、にわかに動揺。晴香と電話で話した直後に失踪してしまう。果たして八雲が見たものとは?', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7fafbee9-2031-4bdd-aec7-9cd089c28ffd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a08aa37-bc7b-4fd4-a7a5-71dde400c9d0', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 8, '100102244', 'つながる想い ～縁～', '『七瀬邸一家四人殺害事件』の容疑者･武田俊介が突如現れた。警察がその検挙に躍起になる一方、晴香たちは、行方不明となった八雲と後藤の消息をつかむために一心のもとに集まった。八雲と後藤、心の拠りどころを失った晴香と石井がはからずも衝突してしまう。かたや一心は、八雲の母･斉藤梓に関する忌まわしい過去を語る。そして晴香は、自分と八雲の縁 (えにし) を実感する事実に直面する…。', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4cd7f8ac-9d5f-4b23-8b52-c97db376a466.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dd8503c-e695-4af2-98da-6237e1a0a67a', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 9, '100102245', 'つながる想い ～光～', '武田俊介と遭遇したことによって八雲の居場所を察知した晴香は、一人その場所へ急行する。一方、石井と真琴もまた、独自の捜査によって後藤の所在に近づきつつあった。全ての謎が解明される。しかし、それは同時に、八雲と両目の赤い男の直接対決を意味していた。八雲の父であるというその男の本当の狙いは何か? そして、彼によって命の危機に直面した晴香の運命は!?', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88c5c784-81dc-48bb-a41f-3314d73560e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5eeae9f3-ccc5-42b7-adea-62473fa969af', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 10, '100102246', '失意の果てに ～告知～', '最新医療の取材で大学病院を訪れていた真琴が、医師から聞かされたのは、奇妙な幽霊話だった。その病院では幽霊が夜な夜な現れては患者に「あなたはいつ死ぬの?」とたずねるという。その話を真琴から聞かされた八雲は、調査に乗り出すことに。病院の調査のために車を借りようと一心のもとをたずねる八雲と晴香。そこで八雲は、一心から、驚くべき事実を知らされるのだった…。', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb46d4ab-8776-4bb2-a35f-3cfbaa377c56.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a1c3bb9-465c-44f7-adc2-072a3c32f6de', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 11, '100102247', '失意の果てに ～凶刃～', '病に侵された一心の余命はあと一年であった。事実を知った八雲は、そのことを晴香や真琴に語ることなく、幽霊が現れるという病院の調査を開始する。一方、逮捕された七瀬美雪から「あの人が一心を殺す」と宣言された後藤と石井は一心の身を守るために彼のもとへ急行する。幽霊に遭遇する八雲たち。その直後、一心が刺されたという報せが飛び込んできた。果たして一心の運命は!?', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1049f1c9-b35b-42e0-9437-a8a88d702e6c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cfecb55-1c98-4db3-a56d-2f220b720b61', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 12, '100102248', '失意の果てに ～憎悪～', '晴香の存在によって失意のどん底から復活した八雲だったが、一心を襲った犯人に対する怒りをあらわに行動を開始する。そんな八雲を心配した晴香は、自分の不安な気持ちを後藤に打ち明ける。晴香の気持ちにほだされた後藤は、中学時代の八雲について語るのだった。命あるもの、死んだもの、生死の境をさまようもの。八雲をめぐる人々の縁 (えにし) が、ついに一つの形になる。描き出されるのは、光か、闇か?', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cce61b39-ac4c-4237-a4df-7d2af1555586.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f55a5df1-fde3-4f69-aeff-2dd2656676c6', '319d734f-6df3-4ea3-97a7-9296ff15fd2c', 13, '100102249', '失意の果てに ～久遠～', '【最終話】両目の赤い男、八雲の実の父である斉藤雲海の仕掛けた壮大な計画によって、八雲は、別なる存在へと変わりつつあった。現場に居合わせた晴香たちは、目の前で起きている現実を、ただ見ていることしか出来ない。彼女たちに銃をむけた美雪が勝利を確信して微笑む。そして、ついに、その時が来た。八雲の肉体が雲海によって完全に支配されたのだ。果たして、八雲の運命は!!', '2022/02/24 00:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/624a6582-3597-4cd1-a6b0-fc8f278d49e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7c08aafa-d3e7-40cc-96e7-ece7f983d11a', '慎重勇者～この勇者が俺TUEEEくせに慎重すぎる～', '', 'hulu', 'shincho-yusha', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2904979f-34a9-4277-bef9-2df9eb697051.jpg?w=331&h=447&p=t', 'hulu', 2019, 3, 1, 'FINISHED', NULL, 105156, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f039cd89-d5bf-4963-afd2-11c6ba9e3123', '7c08aafa-d3e7-40cc-96e7-ece7f983d11a', 'hulu-shincho-yusha-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e296735f-e03e-4b00-90a2-c3c059b06c15.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f86b5f06-d7b5-4f9d-98d7-b5a4b36c981a', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 1, '100043254', 'この勇者が傲慢すぎる', '駄女神リスタは超難度の異世界救済を任され、高スペックな勇者･竜宮院聖哉を召喚。だが聖哉は異常なほど慎重だった! リスタは用心深すぎる勇者に振り回されっぱなしで…。', '2019/10/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e296735f-e03e-4b00-90a2-c3c059b06c15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('266c91ab-4a9b-4e82-b7d4-1bfbb3f2e4c4', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 2, '100043643', '新米女神には荷が重すぎる', '魔王軍四天王に急襲される聖哉とリスタ。聖哉は持ち前の慎重さで一時撤退。神界に戻り、相変わらずのレベル上げに励む。だが異世界では四天王による、村人の虐殺がはじまっていた…。', '2019/10/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f41077c5-a2c1-41f8-ac96-f6ca5d3e6344.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7830e711-89a4-4fdb-999a-e5bd0f5f3db0', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 3, '100044078', 'この勇者は身勝手すぎる', '村を後にした聖哉は、さらなる強敵に備え、またしても神界でのレベル上げ。剣神セルセウスを修行に無理矢理付き合わせ、新たな町で待望の仲間と出会うのだが…。', '2019/10/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ffde35b-30e5-4f5c-9b4b-1fb4b395597f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('496d178d-1a74-4345-9f71-fbf4a3dc77f9', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 4, '100044413', '仲間なんて超いらなすぎる', '聖哉は新たな仲間、マッシとエルルと合流。そんな折、アンデッドの大軍が村に迫っているとの情報が入る。聖哉は一人で戦いに向かうも、マッシュが敵に捕らわれてしまう…。', '2019/11/07 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7324dfd-2f8f-4fdd-ba63-4088a037c841.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e74e604e-3a5c-4346-82c5-f28300c7c26c', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 5, '100044987', 'この女神が不気味すぎる', '聖哉はマッシュとエルルを仲間にするも、いつものように神界へ。今度は不気味すぎる軍神アデネラに稽古をつけてもらった後に、伝説の武器を求め、竜族の村へ向かうのだが…。', '2019/11/14 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a26593df-f574-4d82-9e1c-b9d2e33daf92.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6fb76a1-44ec-4f8d-a81e-cb2e43e5e223', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 6, '100045345', '竜王なのにズルすぎる', '聖哉たちは最強の剣を求め、竜族の里へ。勇者として竜族の歓迎を受けるも、なんと最強の剣を手に入れるためには、エルルの命を犠牲にしなければならないという…。', '2019/11/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea5a3291-7240-4336-ac29-7a8558cc9b49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be2594d3-e304-449f-869a-3a77690cc56b', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 7, '100045896', 'この女騎士が犬っぽすぎる', '竜族の里を後にした聖哉たちの前に、ロズガルド騎士団が現れ、力を貸してくれという。だが、そこで出会ったのは聖哉と正反対の無謀な性格を持つ女騎士のロザリーだった…。', '2019/11/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db463348-0e4a-42b1-afae-865b5d8a3662.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e4a99a6-cc45-4c6d-b40b-49137ddc1704', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 8, '100046464', '清楚なくせに淫乱すぎる', '難敵ベル=ブブを倒すため、神界にて修行する聖哉。弓の女神ミティスのもとで特訓するも、一見は清楚に見えるミティスには、とんでもない秘密があった…。', '2019/12/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57647c80-4b67-4234-8872-ee91a706b3c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3c34346-8965-4e2d-84a3-1eb793ac51ae', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 9, '100047148', '死神がとにかく無敵すぎる', '聖哉は信じられない強さの死神と対峙。いつものように神界へ戻るも、死神は神界まで追ってくる。死神の圧倒的な強さに数多くの神々が倒され、絶体絶命の危機に…。', '2019/12/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f71e182f-47f0-4e91-90f1-08d6b92d987c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1aabbcd6-b611-4923-a150-b565b0b6c227', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 10, '100047847', '老人なのに強すぎる', '聖哉とリスタは、再びゲアブランデへ。そこで戦帝ことウォルクス=ロズガルドなる、人類最強騎士の強さを目の当たりにする。だがウォルクスには、とある秘密があった…。', '2019/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7a702ff-4e02-4946-9c85-7fe5c8955bed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91fcbd35-b083-4dcb-9737-db93db9675c8', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 11, '100048181', 'その真実は重すぎる', '魔王に心酔する最強の敵、戦帝を退けた聖哉たち。その後、リスタは魔王との戦闘を前に、しばしの休息を提案。聖哉も珍しく休暇を受け入れるのだが…。', '2020/01/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ff32405-45d5-47bd-8f44-c658b28dc321.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88252713-303b-45a0-a3f2-5852f4bd3339', 'f039cd89-d5bf-4963-afd2-11c6ba9e3123', 12, '100048236', 'この勇者が俺TUEEEくせに慎重すぎる', '【シーズン1 最終話】たった1人で魔王討伐に向かった聖哉。リスタは人間だったころの聖哉と自分の過去を知り、愛する聖哉のため、魔王のもとへ向かう。女神としての資格を剥奪される覚悟で…。', '2020/01/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f65f759c-0085-4f8e-870d-8f614d3b7803.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dff1ebe4-42ff-414c-be88-5e4b74e1735c', '新あたしンち', '', 'hulu', 'new-atashinchi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48e08539-8ebc-4b26-8a2d-cf27dbfbc9c8.png?w=331&h=447&p=t', 'hulu', 2015, 3, 1, 'FINISHED', NULL, 21229, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 'dff1ebe4-42ff-414c-be88-5e4b74e1735c', 'hulu-new-atashinchi-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3c2c5a2-f800-4603-a8ce-d8f0acff3c42.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3dfc7ec1-8213-46f1-9769-5f794f8fa099', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 1, '100173208', '母『強気で!』', '何事にも強気で突き進む母に、全くついて行けないみかん。そんなある日、みかんは岩木くんに近づく大チャンスを迎える…!? 母の助言が、みかんの背中を押す!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3c2c5a2-f800-4603-a8ce-d8f0acff3c42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd59e7f0-2106-427c-b4a2-06b7818ad714', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 2, '100173209', 'ユズ、サングラスかけたい', '雑誌の影響でサングラスに心奪われたユズヒコ。町で見つけたサングラスをかけようとすると藤野の邪魔が…。はたしてユズヒコはサングラスを手に入れる事ができるのか!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fb52b32-c75f-41b2-a7ec-f71f8463af18.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4eb97160-c9e9-49fb-9625-e424e7d1e3bd', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 3, '100173210', '母、新兵器が好き', 'ベランダに集まるカラスを追い払えない母。リベンジを誓いカラスを待ち受けるが、そこに現れたのは、主婦の宿敵、G!! 素早いGに翻弄される母は、ある秘密兵器を用意する。', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2469e57-e219-4111-ab40-5706299ac74a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33434f8e-fc52-4606-adf9-4d39a5378b60', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 4, '100173211', 'みかん、初期化される', 'スカートのファスナーを閉め忘れて登校してしまうなど、うっかりを連発してしまうみかん。呆れるしみちゃんに、自分は二つの事を同時にできないとみかん。このうっかりはどこまで続く!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbbbfab7-8de7-4aab-87b2-54235d01b000.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a21f9200-776f-42fa-8052-413a464608e2', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 5, '100173212', 'この町も長いわね', 'この町に引っ越して約10年…変わりゆく町並に、昔の思い出を重ねる母とみかん。気が付いたら、この町も長くなったと感慨にふける母だったが…!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24f1fd26-fc84-4c09-b1de-68019120f4ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68726f5e-5808-4b36-91c9-bf5023d67eae', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 6, '100173213', '父は器が大きい', '言い合いをするみかんとユズヒコに、細かい事を気にしないお父さんを見習えと母。そんなある日、父が取っておいた新聞の切り抜きを母は捨ててしまう。それを知った父は!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72bd811a-1fbc-4351-9109-4f0c60931825.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8bd98f01-b7b6-48c9-a393-e0a02572e869', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 7, '100173214', 'ユズピのお母さま', 'ユズヒコファンクラブに新情報! ユズヒコの母は…姉は…どんな家族なのか勝手なイメージを膨らませる川島と山下。想像が大暴走!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1593e4ea-1e07-41e0-a1e2-40ac79eebef8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3c4dad0-a744-4dd6-9366-09bcbd4f9802', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 8, '100173215', '母たちのボーリング', 'ボーリング大会に向け、母と戸山さんを練習に誘う水島さん。久し振りのボーリングに悪戦苦闘する3人のマダムたち。周りの客も騒然の珍プレイ続出!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aad2afa7-9665-4e7f-ba6d-96d7bbd2a3f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4984849b-3d1d-4ffa-adc8-790f428b8aab', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 9, '100173216', '母のケンマクに要注意', 'いつも凄まじい勢いで頼み事をしてくる母。その勢いのせいでいつも迷惑をかけられている、みかんとユズヒコ。2人は母の勢いを止められるのか!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9506bd45-95ab-419a-bc72-5beef5ae8255.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f0b3942-d443-4463-af94-c29e82d28ec0', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 10, '100173217', '川島、おまじない', '指に絆創膏を付けて、ユズヒコへの恋のおまじないをする川島。そこに山下も加わり、次々と新しいおまじないにチャレンジする2人だが…!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92b98c9f-e055-4c5d-bc47-c0188992c734.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6ec3516-ce3f-4389-99b7-a623713533b2', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 11, '100173218', '水島さん、若い', '洋服屋の店員や美容師に若いと言われ、有頂天になる水島さん。そんな浮かれまくる水島さんを、どん底に突き落としたものとは!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f46f9069-5e43-4df3-ac7c-f694da22f67f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b77bccd-d963-45aa-be3b-cb11853dab8b', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 12, '100173219', '自分のお尻は自分でね', 'だらしのない家族に、タメ息をつく母。自分の事は自分でする様にと、家族に訴える母だが、家族にも山ほどの言い分が…。そんな中、さらに各自での尻拭いを押し進める母であったが…。', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cde47138-b148-4786-8ce2-616c7ed1f211.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5d9df11-3e32-4482-b7ee-58d37b94bb12', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 13, '100173220', '母、さえてる日', '今日の母は何をやっても冴えまくる。そして、そんな自分に気付いた母は、この力が消える前に地球規模の大きな事をしたいと意気込む。はたして母の壮大な目標は達成されるのか!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8efc592a-5b7c-4b7a-bf1a-7cf73ac244f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ddfeb71-8036-41b5-8059-083b03637176', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 14, '100173221', 'ユズたち、映画に行く', '映画を観に行くユズヒコ、藤野、ナスオ。その道中、不吉な予言を繰り返すナスオに対し、ユズヒコと藤野は徐々にイラ立っていく。はたして3人は、無事に映画を観る事ができるのか!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b1c5e8a-5bcc-4a54-9d69-157365ba8da2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c10c5ab6-e58b-4630-b47e-481b21a3b290', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 15, '100173222', '男たちの平和', '居酒屋で友人と酒を飲む父。男にとって、真の平和とは何なのか? 普段は、あまり多くを語らない父だが、旧友とうまい酒の前では会話も弾む。', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e494c78-22b8-4e88-9dcd-f1357a9d8f9d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb33d4c6-744f-4f60-92d1-255754422e73', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 16, '100173223', '母とジグソーパズル', 'くじでジグソーパズルを当てた母。1ピース、また1ピースとハメていくうちに、どんどんのめり込んでいく。やめたくてもやめれない母はついに…。', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/359aee5e-e1f7-4d73-8dd3-12de3042b3a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('589db07c-5b35-4d9d-aa1f-dfb421b5bade', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 17, '100173224', 'みかん、呼びまちがい', '街中で人まちがいを連発し、赤っ恥をかくみかん。そんなみかんを見て大笑いするしみちゃんにも、実は似た様な経験が…。そして、宮嶋先生の脱線エピソードに2人は!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b802dde-179b-4910-94bc-53936d146115.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40406174-1ff3-4d2b-ba84-383f4ca1ffa7', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 18, '100173225', '簡単アレンジ料理', '食卓を囲むタチバナ家。ユズヒコは料理に調味料を足してアレンジする。それを見たみかんが一口食べると、納得の美味しさ。さらに父も加わり、ユズヒコのアレンジ料理からとんでもない展開へ!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba1053c6-d3a6-4c17-bbd0-7612dedad7c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ddab5b7-f5a3-401b-9300-4dd03161d1f1', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 19, '100173226', 'おでこ、ピッカー', 'ある日、おでこがピカピカ光っていると言われる母。それに自信をつけた母は、光るおでこでみんなに元気を与えていく。さらに母のおでこパワーは拡大し、思わぬ展開に!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2862c4b-b3fc-4a06-bd8e-6e192d98c18d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4de2e86-ac48-40d9-ba5a-a183dd33a5c0', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 20, '100173227', '母、詰め替えの天才', '神経を研ぎ澄まし、洗剤の容器に詰め替え用洗剤を注ぐ母。一滴の漏れもなく、ピタリと収まる。どんな邪魔が入ろうとも、母の集中力は途切れない…。母が次に詰め替えるモノは!?', '2024/03/11 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09ce61c6-9f83-4187-8b38-d56aea859713.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf398616-bbbe-481e-87e8-01f14e8d82db', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 21, '100173228', '男たちのロコツ', '居酒屋で友人と酒を飲む父。ロコツな振られ方、ロコツな高級店、ロコツな商売…世の中に存在する「ロコツ」を一刀両断!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ec48535-38f8-43c1-8a95-090659043ef0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('321f0a03-c2c6-4b83-a254-215d4cf2cb9b', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 22, '100173229', '白髪を抜いて', '白髪を抜いてと、みかんに頼む母。しかし、みかんが思い切り抜いた毛は、まだまだ元気な黒い毛。軽く謝るみかんに怒りを覚える母だったが、そんなみかんと昔の自分が重なって…。', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5014f5ea-1f2a-43f2-ac64-c026010b78c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e934b561-c506-4f6e-9f6d-98f72fb2271e', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 23, '100173230', 'ユズは甘え下手', '藤野やナスオのように、人に上手く甘える事ができないユズヒコ。昔を振り返っても、いつもみかんだけは上手く母に甘えていた。そんな自分を変えようと、ユズヒコは起死回生の大技をあみ出す!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e83bece4-ecdb-434e-bd5d-32d1cffd6cfd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7cb152a8-6e3a-4d2c-9050-c9e60742192a', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 24, '100173231', '父は母のどこが?', '母から父との結婚の決め手を聞き出そうとするみかんだったが、自分は父から気に入られただけだと言う母。そして、父の口から語られる衝撃の事実!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4563f045-47bc-456d-be12-7403cf1e8bbc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1de88042-9de0-4816-bbba-3e30babbcfc6', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 25, '100173232', '母、半身浴', '水島さんに腰湯をすすめられた母だが、子供時代に田舎の母から水難の相があると言われた事を思い出す…。怯えながらも腰湯に挑戦する母だったが…!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3199b90c-960a-4a3c-9202-039ac842e199.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ab50136-bd5d-43ad-b3a7-eb8e6c4cd081', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 26, '100173233', '吉岡うらやま!', '岩木に想いを寄せるみかん。そんなみかんは、吉岡のように岩木と話をしたいと、苦手なサッカーネタを勉強する。そんな中、みかんと吉岡の間に思いもかけない展開が…!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a6c4085-1b82-4d66-ab38-705aa54f520f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f568c37e-aa21-4d26-9065-2e88b0884b0c', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 27, '100173234', '母の回復法', '朝のタチバナ家。早起きして作った母の朝食は、ほとんど手をつけられずに残されてしまう。母に悪い事をしたと反省する家族だったが、母には元気を取り戻す究極の回復法があった!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ed70e77-d927-4dd8-8747-5f1dcf6aa394.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2e2bcb5-c88a-45c0-861d-480742eafb3e', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 28, '100173235', '須藤ちゃんのメガネ', '学校にメガネをかけてきた須藤を見て、大盛り上がりの藤野。大好きな須藤を笑わせるために、ひとり奮闘する藤野だが、そこに大きな壁が立ちふさがる!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/518c3bc3-edda-442d-87ab-8f8dd5464f18.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fda4ee2f-3faa-47a0-94ba-e9576c05f2f5', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 29, '100173236', 'ドーナツブーム', 'ドーナツにハマる水島さん。そんな水島さんは、母や戸山さんにドーナツの素晴らしさを猛アピール。そして母達は、ドーナツをもらったお礼を水島さんにするが、それがとんでもない事に!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fade1495-d627-43f8-b965-ed207f3cbc97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16456f21-3ed0-48f8-ad73-0e3f3099b1fd', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 30, '100173237', '最近、キョーミあること', '母が留守で家に入れないみかん。仕方なくお隣の漫画家さんの家にお邪魔する事に。そこに父やユズヒコも合流して、漫画のネタ集めの取材を受ける事に!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff4b6976-3c37-4150-9eec-d9138a4af898.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2023051f-f989-4119-8045-46f6ea5c93cb', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 31, '100173238', 'みかん、窓ふき職人', '年末のタチバナ家。大掃除がうまくはかどらず、半ば諦めムードの母。そこにやってきたみかんは、新しく買った掃除道具に目を輝かせる。張り切って掃除を始めるみかんだったが…!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/029d2911-bd73-4366-8ba4-18da38554772.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab0f196c-28df-4aff-a78c-079cfd372f84', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 32, '100173239', '母、虫コミ', '昔から何度も虫の知らせに助けられていると言う母。それは買い物に迷った時や、ストーブの消し忘れなど、ありとあらゆるところで現れる。母を助ける『虫コミ』とは!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0363d426-00ec-4581-b881-d533aa36f728.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('138d9bb8-f7ed-416d-8270-21096f87864f', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 33, '100173240', '母、たとえ下手', '感動を表に出すのが下手な母は、水島さんや戸山さんの前で大失敗を繰り返す。そんなある日、父と夫婦水入らずの旅行に行くことになるのだが…!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e41b85b6-a02e-4990-aa67-ff668d6ef391.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('646ec6a5-b43b-4c7b-a2f2-d04249f13290', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 34, '100173241', 'ベア研のクリスマス', 'クリスマスの飾り付けが光る商店街を、ケーキの箱を片手に歩くみかん。辿り着いたのは、ベア研のクリスマスパーティーが開催される理央の家。みかんが待ち望むクリスマスの奇跡とは…!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b715e739-7125-44f2-be13-9ae945cacd36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4e0ceca-96cd-4fd0-932d-18388827c938', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 35, '100173242', '母、カンで生きる原始人', '道具に頼らず、自分のカンで生きるべきだと主張する母。それに対してスマホの必要性を訴えるみかんだったが、母は全くゆずらない。そしてみかんも驚く、母の潜在能力が発揮される!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fd86ae0-1864-48b0-a4a8-f675d2da2c05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6877d574-669b-4965-a2a6-8639c356a0f4', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 36, '100173243', '岩木くんとクリスマスケーキ', 'ひょんな事から、岩木と一緒にクリスマスケーキを買いに行く事になるみかん。憧れの岩木を前に緊張しまくるみかんだが、この時間がみかんにとって最高のクリスマスプレゼントに!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d6eff29-3742-4909-9700-55fb7a9816d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a961c043-6e10-4c81-8dc8-48819633e31f', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 37, '100173244', 'タチバナ家の元日', '元日。みかんの携帯には、正月休みを満喫する友達からのメールが続々と届く。それを見たみかんは、パジャマ姿でダラダラする家族に不満噴出!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6d68067-5b73-4bb8-a2e5-8a31b9f3ad55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02e8dcaf-f369-46b3-aa2b-383a870dcc48', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 38, '100173245', 'ご町内もちつき大会', '町内の餅つき大会に来たタチバナ家。若者達の腰の引けた餅つきっぷりに、いても立ってもいられない母。そして、名人が見守る中、母の気合いを込めた餅つきがはじまる!!', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6af41d18-ac3d-4f98-95cb-a9719225a15a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8aa25a7-cd0b-4c38-9d3e-9d5c994325b8', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 39, '100173246', '短過ぎるお正月', '正月はDVDを観まくると張り切っていたみかんだが、気が付けば正月休み最終日。DVDもほとんど観ず、しみちゃんに借りた漫画も手つかず…。ここからみかんの猛烈な追い込みがはじまる!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be78bde7-9d94-4454-b4b8-de77ec9e83a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('679f49ac-1046-4df8-9b3b-b43a97e25363', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 40, '100173247', '相談しない父', 'ある日、注文したおぼえの無いピザがタチバナ家に届き、首を傾げる母。実はそのピザは、父が勝手に頼んだものだった。家族に相談せずに行動してしまう父の、さらに驚くべき行動とは!?', '2024/03/18 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5843c074-8e3c-46f1-9912-8c1a361bfb30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8724ebdb-51fe-4a2f-813b-a19012a258b1', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 41, '100173248', '母、脳トレ', '喫茶店で盛り上がる、母達3人のマダム。最近、物忘れが多くなったと言う水島さんや戸山さんと脳トレに励むのだが、母には思い出しても人には言えない秘密が!?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c91ce00-765e-4804-baf6-6a37591e9310.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee0d554a-534d-4f49-a65a-95fa30949b5a', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 42, '100173249', '男子って、やーね', '学校内で想像力豊かな遊びを繰り広げるユズヒコと藤野。それを見た石田や須藤は、男子の遊びを全く理解できない様子。そして危険な遊びは最終段階へ… (よい子のみんなはマネしないでね!!)', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09c5436f-6ade-402b-944a-fd92085a4c11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c6229e4-3270-4c4a-b365-c1a8a9dc060e', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 43, '100173250', '母、一見ぼーっとしてる', 'ぼーっとする母は、お茶や味噌汁をダバダバとこぼしてしまう。それを見ていたみかんに注意される母だが、真剣に他の事を考えていただけだと言い張る…そんな母の思考は地球規模!?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4886b23f-df42-43b1-9965-b71269c56f2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92b3e64f-59f5-4fb2-ba01-5c129f6bc904', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 44, '100173251', 'ナスオのキャラ弁', '息子のために全力でお弁当を作るナスオの母。そんなナスオの母には、キャラ弁作りという意外な特技が! 斬新なキャラ弁がクラス中の女子達を虜にする!?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71df6580-5f88-4e73-9543-835009d2e6ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d0a3047-7aff-49c7-9876-19bd52693f6a', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 45, '100173252', 'これってノンキモ?', 'ユズヒコの話題で大盛り上がりする川島と山下。ユズピと両想いになれたら何したい? と山下に質問をされ、そこで川島が答えた妄想が凄過ぎる!? それってキモイ?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01bd5559-234b-484e-844c-3dd4ffc0e6af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d073cd35-be5a-4ff9-ba6d-5fb158a4efa3', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 46, '100173253', '母、へんに勘がいい', '水島さんが食べたがっているタイ焼きを、偶然買ってくる母。変なところでカンの良い母は、周りの人に有り難がられる事もあるが、ほとんどは迷惑がられてしまう事ばかり!?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/feb47410-4b77-4596-9821-5467508884f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6ff5425-96de-497c-9974-fcb132ff0b63', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 47, '100173254', '男たちの思うツボ', '友人と居酒屋で酒を飲む父。息子を連れ回すおばさん、アヒルを散歩させる女性、動物園のパンダ…世の中に存在する「思うツボ」を、父達が徹底解剖!?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8a4d358-e1e2-44de-8eab-7e9c2448eb37.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcf7d370-eb91-4d17-bb69-5a5ba3ff0496', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 48, '100173255', '頑張れビーム', '新聞の記事をきっかけに、母は町中の頑張っている人達を応援しようと決意する。はたして、母の熱い思いは皆に伝わるのか…!?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c886993a-3d9f-4969-9475-ab4d3ba8eb86.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eabc53c0-9527-4cbc-9ca6-7ebc5f3b3ed7', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 49, '100173256', 'たっくんの節分', 'ある日、公園でたっくんと2人で遊ぶ事になったユズヒコ。そしてユズヒコの事が大好きなたっくんは、2人で鬼ごっこをしたいと大はしゃぎ。ルール無視の鬼ごっこが今始まる!?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70efb140-4b66-4899-890a-b9776abcf5bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58516760-eb46-4c7e-ab56-05c56b692152', 'baa496e4-cb81-40e6-8176-a45f6b4dbfb5', 50, '100173257', 'みかんはヤボ', '人が気にしている事や、聞いてほしくない事をついつい聞き出そうとしてしまうみかん。そんなみかんは、しみちゃんから指摘をされて、空気を読もうと努力するのだが…!?', '2024/03/25 00:00:00', 422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef9ad130-778f-45cb-a820-11d8f060c019.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('47496bb4-9806-4054-8b39-f0b4813eed19', '新サクラ大戦 the Animation', '', 'hulu', 'sakura-taisen-theanimation', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e97ace35-b31b-4fd4-a2f9-2a398654b270.png?w=331&h=447&p=t', 'hulu', 2020, 1, 1, 'FINISHED', NULL, 111500, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c26439a2-ee20-4642-97fa-96aeebe83392', '新しい上司はど天然', '', 'hulu', 'atarashii-joushi-wa-do-tennen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afdb26d0-5d34-44a5-9f55-d86a90760314.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 165070, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c782076d-b292-44b8-9d8d-c0189779ea73', 'c26439a2-ee20-4642-97fa-96aeebe83392', 'hulu-atarashii-joushi-wa-do-tennen-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c769f61a-c9c1-428d-b785-d807e062a9e3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69a212ea-5269-408c-ba6f-566a9c9a734e', 'c782076d-b292-44b8-9d8d-c0189779ea73', 1, '100161955', 'ちょっと割れてる!!', '上司からパワハラを受けたために精神と胃をやられ、前の職場を辞めて広告代理店の営業職に転職した桃瀬。しかし過去のトラウマが原因で「この新しい上司もパワハラ上司だったらどうしよう…」と不安のあまり、出社初日早々外回り中に激しい胃痛が原因でしゃがみこんで動けなくなってしまう。「早く立たないと…蹴られる…かも」と桃瀬が一人で内心焦っている時、一緒にいた新しい上司、白崎がとった驚きの行動とは……?!', '2023/10/10 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c769f61a-c9c1-428d-b785-d807e062a9e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49673967-f994-4879-9b01-303636284556', 'c782076d-b292-44b8-9d8d-c0189779ea73', 2, '100162653', 'おんぶするか?', 'リニューアルした遊園地の広告を作るために、現地取材に行く桃瀬と白崎。「いい広告を作るためには実際にそのアトラクションを楽しむことが大事だと思うんだ」と言う白崎の言葉からメリーゴーランドやジェットコースターなど様々なアトラクションを体験する。無事現地取材を終えた帰り道、停電で二人が乗る電車が緊急停車してしまう。真っ暗な車内で、桃瀬が白崎に話した「転職を決めた日」のこととは……?!', '2023/10/17 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40452a12-a9e4-414a-b7e1-1fb063d6a192.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('884e9774-34c4-4128-93d9-215f03e31bee', 'c782076d-b292-44b8-9d8d-c0189779ea73', 3, '100163702', '肉球肉球肉球…', 'とある日、桃瀬と白崎は道端でダンボールに入った捨て子猫と出会う。最初は白崎を怖がり威嚇している子猫だったが、白崎の優しい言葉と行動により懐き始め、一緒に暮らすことに。子猫を飼い始めてから名前が決まらず悩んでいる最中、白崎がふと思い出したのは子どもの頃、猫と間違えて拾ったタヌキのことだった。寂しくも山に返してあげる時に祖母と二人でタヌキに付けた名前を参考にして、白崎が子猫に付けた名前は……?!', '2023/10/24 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe54165b-ff68-4630-91ee-5f5d271ba07d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('947a31e7-ac0c-4e9b-9ce4-31575a5cc172', 'c782076d-b292-44b8-9d8d-c0189779ea73', 4, '100164305', 'うち、住む?', '桃瀬と白崎の微笑ましいやり取りを見て、桃瀬と同じくパワハラ上司に悩まされていた金城は転職を決意。無事二人と同じ会社に転職し、金城の教育担当には青山が就くことになった。そしてある日の勤務終わりに、桃瀬･白崎･青山･金城の4人で飲みに行くことに。金城は桃瀬が「これまで上司のいる飲み会で酔ったことなんて一度もない」と以前にこぼしていたことを気にかけていたが、今回の飲み会で桃瀬は酔うことができたのか――?!', '2023/10/31 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6155e33-e5ab-41fd-bd6e-9db2d055efb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ee42c2e-fb0e-4050-bca2-365dc333de4a', 'c782076d-b292-44b8-9d8d-c0189779ea73', 5, '100165400', '目からはちみつ!', '温泉旅館に泊まり出張に行くことになった桃瀬と白崎。同日青山と金城は「くまってランド」への日帰り出張に行くことに。白崎は旅館に着いてから自然とはしゃぐ桃瀬を見て、大切なことに気づかされるのだった。一方、くまってランドをひと通り周り終えた青山と金城は、帰り道に突然の大雨に見舞われる。広報の方のご厚意で宿泊施設に泊まらせてもらえることになったが、金城は風邪をひいてしまい――。', '2023/11/07 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/edd43c8b-811e-4744-83d8-b48b2f9f99a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('278b778a-ce30-44b1-adf6-8fda46bf5112', 'c782076d-b292-44b8-9d8d-c0189779ea73', 6, '100165960', '元カレ? 元カレ?? 元カレ???', '噴水にスマホを落としてしまい、機種変更をすることになった桃瀬。すると着信拒否をしていたはずの元上司の黒野から電話がかかってきて、パニックになってしまう。そんな桃瀬を心配した白崎は、桃瀬を自宅まで送ってあげることに。今まで過去の傷と向き合うことを恐れていた桃瀬だったが、白崎から自分のことを想う温かいエピソードを聞き、黒野に向き合う勇気を得る。そして意を決して電話を掛けた桃瀬に白崎がした提案とは――?!', '2023/11/14 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/278f9157-863b-4553-868c-9662d69272f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc249e1b-d42d-41ed-b6b0-14877e2d168f', 'c782076d-b292-44b8-9d8d-c0189779ea73', 7, '100166595', '衝撃の事実…!!', '白崎の家で楽しく居候生活を送る中で、桃瀬は改めてきちんと元上司の黒野のことを白崎に話す決意をする。入社当初、黒野の期待に応えなければと思っていた時のことから、日に日に酷くなっていく数々のパワハラについて、一生懸命話す桃瀬。後日、桃瀬が着替えを取りにアパートに戻った時、ふと窓の外を見るとアパートの裏には暗くてよくは見えないが人影があって……!', '2023/11/21 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/adc155aa-9429-42d3-86d7-7a34e1db75f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('814a4e60-5481-416d-91e3-278de4b033a4', 'c782076d-b292-44b8-9d8d-c0189779ea73', 8, '100167131', '俺の実家、来る?', '桃瀬と白崎が次に出張に向かったのは白崎の地元である秋田県だった。子どもの頃、ナマハゲにさらわれたことでトラウマを抱える白崎だったが、無事に取材を終えることができた。そして白崎が、祖母から「見せたいものがある」と連絡をもらっていたことから、二人は白崎の実家に向かうことに。祖母の提案で昔のアルバムを見ながら思い出話に花が咲く中、祖母が明かした「見せたいもの」は白崎が全く予想もしないもので――。', '2023/11/28 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1240fefd-61d8-4a41-a3ba-4bb0aa9fdb30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b36b36c8-03da-41ef-b609-9687e3d196a0', 'c782076d-b292-44b8-9d8d-c0189779ea73', 9, '100167755', 'それ聞いちゃいます～!?', '急遽合コンに行くことになった、桃瀬･白崎･青山･金城の4人。桃瀬は前の上司と行った過去の合コンの嫌な思い出を思い出して沈んでしまっていたが、実際合コンが始まると、青山の話でとても盛り上がっていた。途中で席を立った青山について行った金城が、気になる子でもいるのかと聞くと、青山はなんだか濁してしまう。青山が場を盛り上げていたのにはとある理由があって――。', '2023/12/05 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b0f4f45-4312-4d86-ae44-82f6ecf6c7ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8491d035-1b64-455e-9ee3-6ae311e5fc3d', 'c782076d-b292-44b8-9d8d-c0189779ea73', 10, '100168605', '着せる気だ…!', 'ハロウィン･読書･秋祭り…。白崎と過ごす秋は相変わらず「ど天然」でいっぱい! そんな日々を過ごす中、桃瀬は変わらず白崎との同居生活を送っていた。とある休日の朝、白崎から近所の美味しそうなお店を提案され、出かけることに。気になっていたお店で昼食を楽しんだ二人は、そのまま近くの公園を散歩することに――。', '2023/12/12 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47d7fe65-d38e-499f-acc1-853c075d2437.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0971d06f-237b-40e1-850b-498d20387ec1', 'c782076d-b292-44b8-9d8d-c0189779ea73', 11, '100169272', 'お家の中探検にゃ!', '多くの乗降客が行き交う駅構内で巨大な広告を見上げている桃瀬と白崎。ついに桃瀬が初めて作った水族館の広告が公開される日を迎えたのだ。水族館に向かう道中、桃瀬は近くのカフェで元上司の黒野に似た男性を見つけてしまう。館内に入っても何かと黒野のことを思い出してしまう中、一緒にいた白崎は怪しい男がいることに気付く。その男が持っている封筒には、桃瀬が元いた会社の名前が書いてあって――。', '2023/12/19 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7743c84f-ebeb-4976-91ac-c23d2f34bb84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8e63f4d-e18e-4547-bbf5-f171f8d0f0a1', 'c782076d-b292-44b8-9d8d-c0189779ea73', 12, '100170187', 'いってきま～…す!?', '【最終話】金城の提案により、4人でプレゼントを持ち寄ってクリスマスパーティーをすることに。桃瀬は引っ越し先を決めるために日々物件探しを続けていたが、楽しかった白崎との生活が終わってしまうことに寂しさを感じてしまう。パーティーを楽しんだ翌日、たくさん悩んだ末、前に進むと意を決した桃瀬は不動産屋に電話をして引っ越し先を決めたのであった。そしてついに引っ越しの日を迎える――。', '2023/12/26 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3271a450-5578-47ff-b468-0d9d9a39eb4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('51c7231f-b7a2-494b-8c22-f0622123e563', '新テニスの王子様', '', 'hulu', 'the-prince-of-tennis-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f4e3a13-5dab-47a1-a2ac-f4761bfcead3.jpg?w=331&h=447&p=t', 'hulu', 2012, 1, 1, 'FINISHED', NULL, 13245, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('de76c1e1-a933-4337-ab97-82a31e280145', '51c7231f-b7a2-494b-8c22-f0622123e563', 'hulu-the-prince-of-tennis-2-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a420a419-15a5-4f04-a606-51d8b9bbe3a6.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16231582-068b-48ad-907b-ce4fd8db1f44', 'de76c1e1-a933-4337-ab97-82a31e280145', 1, '100083002', '王子様の帰還', '中学テニス全国大会から数か月後…。日本テニス界のトップ選手を育成するU-17 (アンダーセブンティーン) 日本代表合宿に、全国優勝を成し遂げた青学 (せいがく) を始め、氷帝、立海など実力ある中学生選手が集められた。しかし、合宿参加早々、彼らはふるいにかけられる。空から落ちてくるボールを拾うことが出来ない者は即刻帰れと言うのだ。余裕でボールを拾う中学生たちの中、拾えない高校生が続出! そして最後の一つ…。そのボールを取ったのはアメリカに武者修行に出ていたリョーマだった。', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a420a419-15a5-4f04-a606-51d8b9bbe3a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a26f4490-153f-4d6c-b645-62f6f277f3b8', 'de76c1e1-a933-4337-ab97-82a31e280145', 2, '100083003', '地獄の番人', '無事、U-17 (アンダーセブンティーン) 日本代表合宿に残った中学生。豪華な施設での合宿に浮かれ気分の彼らだったが、そこへ上位コート所属の高校生との入れ替えを賭けたシャッフルマッチが発表される。その対戦相手は青学･桃城武と5番コート所属･鬼十次郎。奇しくも同じパワープレイヤー同士の対決となった。上がってくるものをことごとく退けることから「地獄の番人」と恐れられる鬼に、桃城は果敢に得意のジャックナイフで挑んでいく。しかし、鬼はそれを上回るブラックジャックナイフを繰り出してきて―。', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97dbb482-723d-47c5-a4db-742fee529b3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4b9bd1e-dc49-4025-8022-58f5891ac6de', 'de76c1e1-a933-4337-ab97-82a31e280145', 3, '100083004', '同士討ち', '精神 (メンタル) コーチ･齋藤が中学生たちに課した課題は、ペア同士の対決「同士討ち」だった。負けた方は脱落と言う非情なルールに困惑を隠せない中学生たち。それぞれ複雑な思いを抱きながら試合に臨むが、青学の菊丸だけはいつまでたっても、気のないプレイを続けていた。そんな本気を出そうとしない相棒の様子に、怒りをあらわにする大石。この試合が終わったらもう一緒にダブルスが出来なくなってしまうことを悲しむ菊丸に、大石は自分は勝って生き残ると宣言する。', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc624991-d1ba-4af8-ad3c-e34861ade361.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('481046b5-b58d-4773-b9f0-e1b80c7c9a05', 'de76c1e1-a933-4337-ab97-82a31e280145', 4, '100083005', '部長の選択', '負けた方が脱落してしまうペア同士の戦い。続いて、青学･手塚VS海堂、氷帝･跡部VS日吉の部長と2年生の対決が始まる。憧れの部長との対決に並々ならぬ思いで挑む海堂と日吉だが、海堂は手塚の百錬自得の極みの前に、思うように試合が出来ず大差をつけられてしまう。一方、日吉は跡部を相手にタイブレークで堂々と渡り合い、2組の試合展開はそれぞれ対照的なものとなっていた。しかし、どうやらこの試合、手塚と跡部の思惑は同じのようで…。その頃、単独行動を起こしたリョーマと金太郎は、徳川と鬼に遭遇。勝負を挑んでいた。', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7363510-d0dc-4e08-8cf4-69929784dae0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26167a9d-d0ae-40bd-a250-bacae699aa87', 'de76c1e1-a933-4337-ab97-82a31e280145', 5, '100083006', '勝者そして敗者', 'ペア同士の試合が続く最中、別の場所ではリョーマと徳川、金太郎と鬼の戦いが始まっていた。自分の得意技を次々繰り出し、相手を全く寄せ付けないリョーマと金太郎。高校生との試合に期待をしていた二人は、あまりの手ごたえのなさに拍子抜けしてしまう。そしてまた、同様に徳川と鬼も、二人の実力に失望を感じていた。これで終いだとばかりに、徳川と鬼がとうとう本気をみせる! いよいよ高校生の実力が明らかに!! 果たしてリョーマと金太郎は本気の高校生に勝つことが出来るのか!?', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37c84ac2-a675-4cf3-ac95-a70b289b01dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3d1333a0-6c9d-4c99-bb43-21e3a8825a24', 'de76c1e1-a933-4337-ab97-82a31e280145', 6, '100083007', '心の崖', '中学生の脱落者が決定し、帰宅の途に就くはずの負け組たちは、何故か山奥へと連れてこられていた。そして、そこには精神 (メンタル) コーチの齋藤と、リョーマ、金太郎の姿が。勝ち組と差を広げられたくないのなら、この山を登ってはどうかと言う齋藤の提案に、負け組たちは山を登ることを決意する。ところが、この山、そんなに甘くはなかった! 体力的にも精神的にも厳しい道のりを進む負け組たち。果たして彼らは、無事に山を登りきることが出来るのか!? そして、この山を登り切った先に彼らを待つものは一体―!?', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b41d105e-bd1e-4181-9c1b-30a866d42a67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afcfbef7-2081-48d9-a570-0747b1e2aa0a', 'de76c1e1-a933-4337-ab97-82a31e280145', 7, '100083008', 'ゼロからのスタート', 'やっとの事で崖を登り切ったリョーマたち負け組メンバー。そこに待っていたのは、すでに脱落したはずの高校生たちと、U-17 (アンダーセブンティーン) 日本代表･裏コーチを務める三船入道だった。三船は特訓と称し、中学生たちに次々と課題を与えていくが、その内容はどれも自分たちの力になるとは思えない不可思議なものばかり。三船や高校生に対し、イライラを募らせながらも中学生たち自分たちの成長のため、必死に課題をこなしていく。そして、1日の終わりに夜のねぐらをかけて、高校生と中学生の試合が行われることになった。', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ff8ef75-8189-46ea-b209-ecdd55a0d3fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('599b2f2c-6b88-4261-b2f5-29e5546b9ba9', 'de76c1e1-a933-4337-ab97-82a31e280145', 8, '100083009', 'スペシャルミッション', 'ある真夜中…。リョーマ、田仁志、謙也は三船よりスペシャルミッションが与えられる。それは、U-17 (アンダーセブンティーン) 日本代表合宿に忍び込み、練習用品と酒を盗んでくるというものだった。合宿所への潜入に成功した3人は、難なく備品を入手することに成功。続いて、問題の酒があるバーラウンジに向かうが、しかしそこにたどり着くには数々の罠 (トラップ) が待っていた。果たして、リョーマ、田仁志、謙也は無事に酒を持ち帰ることが出来るのか!?', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/488b837a-cefd-4f0b-aced-5dbf5f356442.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8adc3f5-8b31-4b34-aac2-e5b9a61cd29d', 'de76c1e1-a933-4337-ab97-82a31e280145', 9, '100083010', '進化と変化', '着々と三船の特訓をこなしていくリョーマたち。ある日、三船の発案により新たな特訓が行われることになる。それは……「スポーツマン狩り」!! 各々に与えられた風船には鷲の好きな匂いが塗ってあり、風船が割られないよう逃げなくてはならないという。割られた者は即刻アウトというルールに鷲から必死に逃げる中学生たちだが、その中で彼らは自分の進化を目の当たりにする! 一方その頃、勝ち残った中学生たちは高校生とのシャッフルマッチで驚異の快進撃を果たしていた。', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80b1b351-73e7-40b4-9d47-16850a1954b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e996ac3-de10-400b-93a1-6a52eb677715', 'de76c1e1-a933-4337-ab97-82a31e280145', 10, '100083011', 'さらば 手塚国光', 'とうとう3番コートと5番コートのシャッフルマッチが始まった。シングルス2で登場した青学 (せいがく) の部長･手塚は、かつて青学 (せいがく) の部長を務めていた大和祐大と対戦することになる。大和の繰り出す「幻有夢現 (げんうゆめうつつ)」を返すことが出来ない手塚は「手塚ファントム」を使い、すべてのボールをアウトにすることで勝利を掴もうとしていた。しかし、ひじに大きな負担がかかるこの技を見て大和は、常に自分を犠牲にし、チームのために戦ってきた手塚に自分のために戦ってほしいと語りかける。それを聞いた手塚は…。', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d058ea22-0245-47cc-a83d-73ea990d87f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e60c2b78-86af-455e-961d-b113522e4ef3', 'de76c1e1-a933-4337-ab97-82a31e280145', 11, '100083012', '約束', '手塚の思いを継いだ跡部が満を持してシングルス1に登場する。相手は3番コートの中心的存在である入江奏多。試合は序盤から、この合宿で驚くべき進化を遂げた跡部がその力を見せつけ、圧倒的なワンサイドゲームで入江を5-0と突き放す。その差に誰もが5番コートの勝利を確信した瞬間、ついに入江が隠していた実力を明らかにする! 跡部に牙をむく入江のテニス。最後に勝利を手にするのは5番コートか、それとも3番コートか!? シャッフルマッチ最終戦の火蓋が切って落とされる!', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4e073b8-36e5-44f0-abff-0e8849330297.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5dc76f3-dcff-47d8-8bac-44072f439792', 'de76c1e1-a933-4337-ab97-82a31e280145', 12, '100083013', '革命の火蓋', 'ノーゲームに終わった跡部と入江の試合。代表戦に自ら名乗りを上げた鬼は、圧倒的な強さで勝利を収め、ついに5番コートの中学生たちは3番コートへと勝ち上がった。一方、負け組にはこの山から下りるための最終特訓が行われる。三船は、これまで以上に厳しい練習を課すが、負けじと必死に食らいついていく負け組の面々。そして、中学生たちには三船から最終試験が言い渡された。いよいよ負け組の進化が試される。リョーマたち中学生は無事、山を降りることが出来るのか!?', '2021/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/887cf91f-0eaf-4981-9b5a-80b7ebe20c09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c598456-7345-45ae-8c35-f99de78c36d4', 'de76c1e1-a933-4337-ab97-82a31e280145', 13, '100083014', '輝ける君たちへ', '【最終話】革命軍の証である黒ジャージを着て戻ったリョーマたちは、2番コートに試合を持ちかけていた。傷だらけな中学生を見てせせら笑う2番コートの高校生だったが、これまで地獄の特訓を乗り越えてき中学生と2番コートの高校生との実力差は明白であった。負け組と言われた中学生たちは見事な勝利で2番コートの座を勝ち取り、再び、U-17 (アンダーセブンティーン) 日本代表合宿へと帰還するのだった。そして、リョーマはあの日の雪辱を果たすべく、一人練習する徳川の前に現れた…。', '2021/07/23 00:00:00', 1391, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e8ea4a3-cb64-469b-933b-4fc4808c74a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2d1dad5a-038d-4ff1-b750-06a092edb7e9', '新テニスの王子様 OVA vs Genius10', '', 'hulu', 'the-prince-of-tennis-2-ova', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e1d5941-e555-4fac-bf1c-7f7a9a7bfbb3.jpg?w=331&h=447&p=t', 'hulu', 2014, 3, 1, 'FINISHED', NULL, 20941, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('518d9597-2f52-4324-8f7a-e2be72836264', '2d1dad5a-038d-4ff1-b750-06a092edb7e9', 'hulu-the-prince-of-tennis-2-ova-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba26f244-26ac-4390-a61c-0c471b00b2ea.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8796c125-7684-4e88-8f6a-a8382f3c82f5', '518d9597-2f52-4324-8f7a-e2be72836264', 1, '100083015', '招聘前夜', '全国大会終了後、U-17 (アンダーセブンティーン) 日本代表合宿への参加が決まるまで、中学生たちは束の間の自由な時間を過ごしていた。祖父･国一と共にルアーフィッシングに出かけた手塚。商店街の福引に燃える忍足侑士&謙也。カブトムシの世話に夢中の白石は、妹･友香里から衝撃の事実を知らされる。一方、リョーマはニューヨークの街の一角にあるテニスコートで、ケンやロイといった友人たちとテニスをする日々を送っていた。テニスコートを占領しようとするジャックたちを、圧倒的な強さで一蹴するリョーマ。しかしケンは自分の力でジャックに勝ちたいと願っていた。必死に練習をするケンに対してリョーマは…。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba26f244-26ac-4390-a61c-0c471b00b2ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc2c14a8-230b-4b2a-b278-a45c2a52d0a7', '518d9597-2f52-4324-8f7a-e2be72836264', 2, '100083016', '神の子VS皇帝', '合宿への勝ち残りをかけたペア同士の非情な試合に次々と決着がつけられていく中、幸村と真田の立海頂上決戦が始まった。真っ向勝負を宣言した真田は、試合開始早々から「風林火山」を放つ。しかしその猛攻に動じることなく、冷静なテニスで真田を翻弄する幸村。やがて、真田の五感に異変が…! 一方、別のコートでは不二と裕太の兄弟対決が繰り広げられていた。観月の助言もあってテニスの腕をあげた裕太は、不二を倒そうと意気込むが…?', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b800ae21-fd36-4346-9a79-d18426933cdc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb9648b7-3799-4dfc-9c66-ddbac009d773', '518d9597-2f52-4324-8f7a-e2be72836264', 3, '100083017', '伝説を継ぐ者たち', '次なる同士討ちは白石VS謙也の試合。同じ学校で共に戦ってきた二人だが、実は直接対決するのは去年の夏以来のこと。謙也の方が白石との試合を避け続けてきたらしい。その理由は、一年前の全国大会にあった。ベスト4をかけた準決勝の立海戦、四天宝寺の前部長･原によって謙也はシングルス3に抜擢される。勝ってシングルス1の白石までバトンをつなげると意気込む謙也だったが…。果たして、謙也は過去を乗り越え、白石との真剣勝負に臨むことができるのか!?', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f52fbfba-0819-4851-a078-8b61f71e7b9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33123109-fadf-45ed-86db-038f3d706842', '518d9597-2f52-4324-8f7a-e2be72836264', 4, '100083018', '勝者の意味', '合宿に残った勝ち組メンバーは、厳しい訓練に励みつつ、豪華な設備や食事を各々楽しんでいた。しかし、そんな中にあっても、相棒と別れたことに意気消沈している菊丸と鳳。寂しさを分かち合っていた二人に、跡部と観月は負け組に同情していられるほど合宿は甘くない、と厳しい言葉を投げかける。その言葉に怒った菊丸たちは、跡部と観月に宣戦布告! いつの間にか、他の勝ち組メンバ ーを巻き込んで、まさかのテーブルテニス勝負が行われることに!', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0588e2c-14ba-4589-9b15-3e8431fc4558.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e18c81a-964a-4b2d-a133-df6d4bab939c', '518d9597-2f52-4324-8f7a-e2be72836264', 5, '100083019', '男たちの絆', '宍戸に強くなることを誓って勝ち組に残った鳳。そして、ようやくやってきたシャッフルマッチ。鳳は意気込んで、高校生･円城寺に挑むも、スカットサーブが通じず、敗北を喫してしまう。次の日、試合を辞退してひたすら自主練する鳳の様子に気づいたブン太。彼自身も、相棒のジャッカルに勝って合宿に残ったひとりだ。自分を責めて調子を崩す鳳に、ブン太は言葉をかけるが…。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b056c9d4-42f0-4fd5-a80f-4013c2f79829.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54ada9c3-57af-4d00-b222-8a9b8ab0f520', '518d9597-2f52-4324-8f7a-e2be72836264', 6, '100083020', '天使と聖書 (バイブル)', '3番コートと5番コート総入れ替え戦。鬼率いる5番コートの中学生チームは、高校生の驚異的なパワーに圧倒されて第1試合を落とす。続く第2試合を任されたのは、白石と赤也のダブルスペアだった。しかし、対戦相手の松平と都は、赤也をからかうような発言を執拗に繰り返す。さらに試合の主導権も完全に相手に握られ、苛立ちを募らせる赤也。そんな赤也を冷静にフォローする白石。不安定な感情の高ぶりが引き起こす赤也の悪魔 (デビル) 化を止めてほしい。白石は合宿所を去る柳から頼まれていたのだ…。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/930d467d-90c9-42c9-8024-64884b7b729b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('14bbc397-0d27-446c-a7c7-ef78f3f6a8d4', '518d9597-2f52-4324-8f7a-e2be72836264', 7, '100083021', 'ヒミツの王子様', '【最終話】負け組メンバーが復帰し再びにぎやかになった合宿所に、思いもよらぬ問題が発生! 悪天候が続いて、必要な物資が届かなくなってしまったのだ。食べたいものが食べられず、ストレスが溜まり始める中学生たち。そんな彼らの目に留まったのは、堀尾が持ち込んだ大きなバッグだった。中身を明かそうとしない堀尾に、ストレスMAXのメンバーたちが次々と襲い掛かる! そしていつしかそこは、まくら投げという名の戦場となった…!', '2021/07/23 00:00:00', 1392, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a830b401-203c-497f-94de-5ce288477a2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0daf86a4-5d0d-45ec-b997-cfae142f40bf', '新テニスの王子様 OVA vs Genius10', '', 'hulu', 'the-prince-of-tennis-2-ova-vs-genius10', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6748fdfc-1305-45aa-b9f6-8b0efee36b28.jpg?w=331&h=447&p=t', 'hulu', 2014, 3, 1, 'FINISHED', NULL, 20941, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a79ba505-8af5-4491-abeb-1663a0d55081', '0daf86a4-5d0d-45ec-b997-cfae142f40bf', 'hulu-the-prince-of-tennis-2-ova-vs-genius10-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9be3171a-2471-477f-9be1-7111c35a11b0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d752f94-e661-4d39-9458-087bd7bfe304', 'a79ba505-8af5-4491-abeb-1663a0d55081', 1, '100083022', '革命への前奏曲 (プレリュード)', 'U-17 (アンダーセブンティーン) 日本代表合宿に参加中の中学生たち。一度は合宿所を去ることとなった「負け組」メンバーも試練を乗り越え帰還し、合宿所は再び活気を取り戻していた。無口なルームメイトたちを相手に赤也が落ち武者話を披露する205号室。合宿に持ち込んだ鉢植えの話題で盛り上がる不二たち201号室。211号室では黄金ペア同士のまくら投げが始まって…。その頃、真田は三船コーチの伝言を受けとっていた。この合宿の1軍と呼ばれる最強選手たちが、1か月の海外遠征から戻ってくるというのだ!', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9be3171a-2471-477f-9be1-7111c35a11b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b53ce70-b72f-4588-9c33-1fc46a989815', 'a79ba505-8af5-4491-abeb-1663a0d55081', 2, '100083023', '激戦開始', '各コートに散った1軍No.11～20との試合が始まった。No.17三津谷と対峙した柳は、三津谷を「あくと兄さん」と呼び、乾を驚かせる。柳にとって三津谷は、幼いころにデータテニスを教わった相手だったのだ。しかし、データテニスの強者との戦いとはいえ三津谷に翻弄されるばかりの柳に、乾は違和感を募らせる…。一方、No.18平とNo.19原の四天宝寺OBダブルスと対戦中の桃城と謙也は、平たちの独特のペースに苦戦を強いられていた。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eada87e8-5792-4c0b-92e2-065538991212.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51eeb976-972f-4f43-b22c-496929c6c7d4', 'a79ba505-8af5-4491-abeb-1663a0d55081', 3, '100083024', '鏡像と虚像', '1軍No.11～20の選手と中学生たちの激戦は続く。幸村の対戦相手はNo.11の不破。しかし不破は一球も打ち合うことなく、「ハンデ」と称して目隠しで己の目を覆った。視界のない状態でも実力を見せつけ翻弄する不破だが、幸村は勝負を諦める様子はない。それどころか、ハンデなど必要ないと不破を挑発して…。時を同じくして、入江はNo.20秋庭と試合をしていた。試合を舞台のように演出しようとする入江のテニスを、「安い芝居」と一刀両断する秋庭。その言葉に瞬間的に燃え上がる怒りの中で、入江は跡部との会話を思い出す…。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/268aafae-fe54-424d-a45a-4ed2d56a55c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68e7180e-436a-4846-9e53-5d27f9186040', 'a79ba505-8af5-4491-abeb-1663a0d55081', 4, '100083025', '決戦前夜', '試合に勝利し、No.11 ～20のバッジを手にした中学生たちの次なる相手は1軍No.1～10、通称Genius10 (ジーニアステン)! No.1平等院鳳凰の提案で、明朝から日本代表を賭けたシャッフルマッチが行われることになった。決戦の前夜、コートで打ち合い調整をしていたリョーマと徳川を、平等院の強烈な一打が襲う。体をはってリョーマを守る徳川だが、さらなる一打が…! ラケットを構えたリョーマの前に割って入り、その球を打ち返したのは、フードをかぶった謎の1軍選手だった。平等院の剛速球を難なく返したその男の名前は越前リョーガ。リョーマの兄だというのだが…。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16d85753-c50f-4f77-a467-ad32020d84f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26ca94c5-4395-4120-95f4-137206799c42', 'a79ba505-8af5-4491-abeb-1663a0d55081', 5, '100083026', '最強のペア', 'シャッフルマッチ初戦、No.9越知とNo.10毛利とのダブルス戦に名乗りを上げたのは跡部と仁王。226cmの高身長から繰り出される越知の必殺サーブに対し、手塚へとイリュージョンした仁王は、腕への負担の大きい零式サーブで対抗する。サーブの戦いを制したのは中学生ペアだった。あと1ゲームを守るだけ…。そう意気込んだ瞬間、越知の冷たい視線が跡部を射抜く!「精神 (メンタル) の暗殺者 (アサシン)」と呼ばれる越知のプレッシャーの前に跡部は…、そして仁王は…。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b95c93e-ce11-4c9d-8989-20acd63f4057.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b0231fb-720c-4c71-ae29-9fcab73f996c', 'a79ba505-8af5-4491-abeb-1663a0d55081', 6, '100083027', '裏切りと交渉', 'シャッフルマッチ第3試合、「コート上の交渉人」の異名を持つNo.7君島と「処刑人」と呼ばれるNo.8遠野ペアに対するのは、丸井&木手ペア。異色の組み合わせだが、縮地法を生かした木手の守備力は丸井の妙技を際立たせ、理想的な戦いぶりを見せる。しかしそんな中学生ペアの善戦にも君島は余裕の笑みを崩さない。その時、木手の打球が突然丸井に襲い掛かる! 豹変する木手の態度。君島の交渉はすでに成立していたのだ…!', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f1f781c-cc79-4fc9-a03b-7689d9dbc835.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9fcfff49-8425-4fb0-9a12-45e6c1c2ac4c', 'a79ba505-8af5-4491-abeb-1663a0d55081', 7, '100083028', '10球を抱いて眠れ', '心と体を削る激闘となった丸井&木手VS遠野&君島の戦いは、意外な形で決着した。苛烈な試合から一転、ひとり静かにコートに立つNo.5鬼に、遠山が再戦を申し込む。負け組の修行を経てさらに進化した遠山のテニス。「日本一のテニスプレイヤーになる」そのために鬼に勝ちたい。巨大な壁に食らいつく純粋な闘志が、ボールを打ち合うほどに鬼の心を熱くする! 一方、リョーガと共にコートを離れたリョーマは、平等院の光る打球を打つ方法をリョーガから教わっていた。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9723eee-d5d4-46e4-b882-8991f2cae914.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4604adb-b1b4-4237-baed-a2f147917391', 'a79ba505-8af5-4491-abeb-1663a0d55081', 8, '100083029', '皇帝と怪物', 'Genius10のNo.2種ヶ島とNo.6大曲とのダブルス対決のために、真田が相棒に選んだのは亜久津だった。ブランクのある亜久津を危ぶむ中学生たちだったが、掴みどころのない種ヶ島のスタイルに翻弄されてペースを崩したのは真田の方だった。必死に振り抜いた真田のラケットが、偶然にも亜久津の頬を強打する! 張りつめた空気の中、立ち上がった亜久津。だがその顔に怒りはなかった…。この試合は、亜久津にとっても負けられない大切な試合。「お前のテニスをしろ」亜久津の言葉を受け止め、真田は集中力を取り戻す。', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c630952a-9e1d-4331-84d0-f45f25e0d8a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('909d37f9-eda0-49ed-8732-561317f9502c', 'a79ba505-8af5-4491-abeb-1663a0d55081', 9, '100083030', '覚悟', 'リョーガから光る球の打ち方を教わったリョーマは、その手ごたえを確かめるようにさらなる勝負を持ちかける。その姿にリョーガは幼い頃のリョーマの姿をだぶらせた。「真剣勝負しようよ」――記憶を失っても変わらない弟の負けん気の強さに、リョーガは笑みをこぼす。一方のシャッフルマッチでは、徳川が驚異的な猛攻によってGenius10のNo.1平等院と互角の勝負を繰り広げていた。徳川にとって平等院は、合宿参加当初に完全敗北をした因縁の相手。鬼と入江の協力により進化した徳川は、まさに死に物狂いの攻撃で平等院を追い詰める…!', '2021/07/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bbcc6fc5-5222-4cc3-86dc-72598ccd05b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56850794-b209-4c66-9d1a-ddf2ded0d892', 'a79ba505-8af5-4491-abeb-1663a0d55081', 10, '100083031', '導かれし者たち', '【最終話】次々と徳川に襲い掛かる平等院の打球。死よりも苦しい地獄を乗り越えてきた平等院にとっては、この勝負にかける徳川の決意すら生ぬるいものでしかなかった。限界を迎えながらも執念で戦い続ける徳川。一切の容赦のない平等院の攻撃。そんなふたりの死闘がリョーマの中に眠るサムライの魂を呼び覚ます! 周りの制止を振り切って徳川に迫る平等院の「デストラクション」を打ち返したリョーマ。しかしその行為は規定違反となり、合宿所を追放されてしまう。突然戻ってきた日常生活はどこか空虚だった。そんなリョーマの行き場のない想いを解放してくれたのは、いつも変わらずちょっと不器用で素直な桜乃だった。', '2021/07/23 00:00:00', 1392, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/311ac8af-4743-4242-807d-e3b9a132864f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('68d94dc4-722a-4efe-8660-5d8705558569', '新テニスの王子様 U-17 WORLD CUP', '', 'hulu', 'the-prince-of-tennis-2-u-17-world-cup', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6d7de3f-f90e-417a-993d-01d94617d525.jpg?w=331&h=447&p=t', 'hulu', 2022, 2, 1, 'FINISHED', NULL, 140187, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fd80b29c-8879-4924-9b60-5a137caa4b90', '68d94dc4-722a-4efe-8660-5d8705558569', 'hulu-the-prince-of-tennis-2-u-17-world-cup-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/039b2694-0b27-49cb-abb5-b588320781f6.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5c263ef-c94d-4757-acfb-081153c8f74e', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 1, '100115655', 'アメリカ代表･越前リョーマ', 'U-17W杯 (アンダーセブンティーンワールドカップ) 開催地、オーストラリアには各国の代表選手達が集結していた。そこには、中学生15名を含む、平等院率いる日本代表、そしてプロになるため日本から旅立った手塚を擁する強豪ドイツ代表の姿もあった。一方、日本代表合宿を追放されたリョーマはリョーガの誘いに応じ、アメリカ代表の選考会へ向かう。そこで、リョーマを軽んじ挑戦してくる他のアメリカ代表選手達。彼らを次々と退けたリョーマは、正式にアメリカ代表として迎えられる――。', '2022/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/039b2694-0b27-49cb-abb5-b588320781f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('738e88f4-ade2-429e-a109-83a516ebc752', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 2, '100115656', 'プレW杯 (ワールドカップ) 開幕!', 'プレW杯 (ワールドカップ) としてエキシビションマッチが開催され、日本はいきなり強豪ドイツと戦うことになる。第1試合に挑むのは不二とデュークのペア。不二は、今や王者ドイツの代表となった、かつての盟友･手塚の目の前で、彼が日本との決別を決意した日の知られざる戦いに想いを馳せ、また1つの進化を遂げてゆく。続く第2試合。跡部が、入江と共に手塚との試合に挑む――! 手塚が組むのはドイツ代表の参謀･QP (キューピー) ――。', '2022/07/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef5bc6b4-0dc7-4198-97c1-df7114edbc38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a0357b2-924e-4d21-bba0-5c17ca20ea7e', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 3, '100115657', '一瞬先の未来', 'プレW杯 (ワールドカップ) ･第3試合。王者ドイツは、遂に主将ボルクがコートへ――。挑むのは徳川&幸村ペア。だが試合開始後まもなく、なんと幸村が「五感を奪われて」しまう。徳川は幸村を庇いつつドイツペアを相手に、たった1人での戦うことになる。その一方で、幸村もまた孤独と戦っていた。五感を奪われ、閉ざされた闇の中で「たった1人で恐怖」と戦う幸村の耳に、かつて自分に五感を奪われながらもそれを克服した彼の声が聞こえてきた――。', '2022/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c836a33a-c849-4411-8d33-2b019046fbd0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fa8abe5-0f15-4bae-ba0e-10a26f23ad0b', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 4, '100115658', '王子様vs王子様', 'プレW杯 (ワールドカップ) は日本の敗北で幕を閉じた。試合を見届けて会場を後にしたリョーマは、そこで現地の不良達にからまれている桜乃に遭遇する。桜乃を庇い、不良達と対峙するリョーマをけしかけられたドーベルマンが襲う。それを退けたのは白馬に跨った少年だった。彼は、馬に跨ったままテニスラケットでボールを放ち、不良達を追い払ってしまう。桜乃を見て心を奪われた少年にボーイフレンドと勘違いされたリョーマは勝負を挑まれ、なんと互いに馬に乗ったままテニスで戦うことになる――。', '2022/07/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ce70610-3b0c-4376-8cc1-df29571388b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9298a293-9b8b-486f-af48-e5791d040e25', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 5, '100115659', '番狂わせ', '一夜明け、ついにW杯 (ワールドカップ) 本戦が開幕する。初戦、日本の相手はギリシャ代表。高校生と中学生の息と技がかみ合ったD2 (ダブルスツー)、D1 (ダブルスワン) そして種ヶ島の「閃きテニス」によるS3 (シングルススリー) でギリシャを退け、初戦を快勝で飾る日本代表。だが、その一方で会場に入った日本代表の面々は、「リョーマがアメリカ代表になった」という情報を聞き、驚きを隠せない。さらに、世界ランク2位のスイスが敗れたという情報がもたらされる。破ったのは、次なる日本の対戦相手･オーストラリア――。', '2022/08/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/974431fa-8189-442b-a396-655f99a37594.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('397af8e3-9bff-4d85-b2c6-3b1a5d9b4140', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 6, '100115660', '完全アウェイの戦い', '強豪スイスを破った開催国オーストラリアとの第1試合。D2 (ダブルスツー) の幸村&真田ペアは、相手の「オーストラリアンフォーメーション」によって、攻め手を封じじられてゆく。押され気味の日本代表の試合を見つめるリョーマの中にある「本心」を、ラルフは感じ取る。第2試合、D1 (ダブルスワン) に挑むのは不二&仁王ペア。跡部は2人に「おまえら、次の試合…負けるぞ」と告げる。そして始まったD1――そこには驚愕の展開が待ち受けていた。', '2022/08/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36bbbdb1-444c-48e3-b7ce-88927159fdc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a380fcae-6960-43f0-be9a-d54e2ec6e42c', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 7, '100115661', 'チェスの王様 (キング)', '仁王と跡部が入れ替わっていた――驚愕するW杯 (ワールドカップ) 会場。なぜこのような真似を? と訝しがる日本代表メンバーだが、跡部はオーストリア代表の背後にある「天才的頭脳」の存在に気づき、その「頭脳」を相手に戦っていた。速攻での決着を目論むオーストラリア代表をタイブレークへと引きずり込む跡部。彼はタイブレークを続けながら待っていた。敵の必殺技「タキオン」を不二が見極めるのを――。', '2022/08/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa6c4093-c0f7-47b2-8a9e-eeb17902268b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8bdb50e1-84eb-4932-8816-a046d9a6b92f', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 8, '100115662', 'その覚悟…その条件', 'W杯 (ワールドカップ) 3回戦。強豪スイスにダブルスで2連敗を喫する日本代表。そしてS3 (シングルススリー)、3タテを狙うスイスは主将でプロであるアマデウスが出てくる。それを見て、自ら戦うため選手交替を告げようとした平等院だが亜久津は譲らない。平等院は「負けたら日本へ帰れ」と宣告し、亜久津をコートへと送り出す。だが、試合開始早々に亜久津はアマデウスの「闇 (ダークサイド)」に封じ込められてしまう。コートに倒れた亜久津は立ち上がれるのか――?', '2022/08/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a1edafd-d74e-4656-8f1d-493e3266dbca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58e4898d-c4e5-4660-84f8-7e6de6971644', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 9, '100115663', '仲間への想い', 'スイス戦での亜久津の試合を見たリョーマに手塚が投げかけた言葉――「おまえは今、誰を倒したい?」それは、リョーマの中に大きな迷いを生むことになる。決勝トーナメントを翌日に控え、ラルフはリョーマをコートに入れ、次々にアメリカ代表選手と試合をさせる――ラルフはリョーマの中にある「迷い」に気が付いていた。コートに入ったラルフから容赦ない打球が繰り出される。「リョーマ……君のいるべき場所は、ここではないようだ」その言葉に、リョーマの中にある迷いが晴れてゆく――。', '2022/09/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7ec815c-0ca7-4f12-a31b-60d5e842d364.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('730f7267-4133-44dd-83b2-75155ea2b1a9', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 10, '100115664', '聖書 (バイブル) のその先へ', '遂に日本代表に復帰するリョーマ。リョーマをメンバーに加えて挑む準々決勝の相手は世界ランク3位･フランス。メンバーに選ばれた白石は、自分の「優等生」のテニスが世界を相手に通用するのか悩んでいた。「聖書 (バイブル) テニス」が身に沁みついた自分はそこから脱却できるのか? 悩む白石に種ヶ島が声をかける。種ヶ島が白石に送るアドバイスは果たして功を奏するのか? 白石は君島とのペアで、強豪フランスとのD2 (ダブルスツー) に挑む!', '2022/09/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83960648-8379-4a50-90ca-983b271eea8d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a55f8400-0c69-452e-a201-5046bda568e5', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 11, '100115665', '最悪のダブルスペア', '準々決勝･第2試合――D1 (ダブルスワン) は柳&毛利ペア。立海の先輩後輩でもある二人の組み合わせは一見良好なペアに見えるが、立海時代にろくに練習もしなかった毛利に対し、柳は「俺はあなたを一生許さない」と激しい言葉をぶつける。それは、「テニスをやりたくても出来ない状況」を血のにじむ想いで克服した幸村のことを間近に見てきたがゆえの言葉だった。「最悪ダブルスペア」の試合が始まる――。', '2022/09/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02bb7ade-0509-4e96-a8ca-89103462667b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('721a0c15-185a-476f-8da4-19c297f6281f', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 12, '100115666', 'プリンス オブ エース', 'フランス戦第3試合。コートに入ったのは「王子 (プリンス)」と呼ばれるシャルダール。対する日本は代表復帰戦となるリョーマ! 奇しくも、場外で行った馬上テニスの決着をつける形となる2人。以前よりパワーの増したリョーマのサーブが放たれる――だが、その全てをリターンエースで決めてくるシャルダール。馬上テニスで鍛え上げた上半身と体幹から繰り出されるスピードボールに、リョーマはなす術もなくポイントを失ってゆく――!', '2022/09/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8574bf20-6662-47c4-9576-249141bbbc48.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b7a088d-b7fd-4867-b78b-6f8568a19c56', 'fd80b29c-8879-4924-9b60-5a137caa4b90', 13, '100115667', 'サムライvs騎士 (ナイト)', '【最終話】打ち返された「ホープ」によって吹っ飛び、意識を失ったリョーマ。ベンチへ運ばれたリョーマに呼びかける仲間達。リョーマは夢を見ていた――幼い日、リョーガと共に古井戸に落ちてしまい、必死に這い登ろうとした時のことを。何度失敗しても、再び挑む幼き日のリョーマ。諦めない、決して……! メディカルタイムアウトが迫り、リョーマの棄権が宣言されようとした時、「勝手に試合終わらせないでくれる?」――王子様は目覚め、再びコートに立つ。「ホープ」を封じられたリョーマに勝機はあるのか? 決着の時――迫る!', '2022/10/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/621b8db3-472d-4b82-b53b-c485ffcef239.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1e1fd9f2-5d5c-4ea7-b97e-e8c4c14a195e', '新テニスの王子様 U-17 WORLD CUP SEMIFINAL', '', 'hulu', 'the-prince-of-tennis-u-17-world-cup-semifinal', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56e5ea47-225e-4584-b653-a7ae9a839d6e.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 165810, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('abf66a31-3adb-4e31-8630-6d6377c1b756', '1e1fd9f2-5d5c-4ea7-b97e-e8c4c14a195e', 'hulu-the-prince-of-tennis-u-17-world-cup-semifinal-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3caeef0e-e49e-404a-94c0-f7268ce06c0b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b96aa70-b75c-4331-9942-8341e6a4f66a', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 1, '100199587', '最強ドイツ 決戦前夜!', 'フランスを下し、準決勝へと駒を進めた日本代表。次の相手はかつての仲間、手塚を擁する世界No.1の強豪･ドイツ! 戦いを前に、アメリカとスイスの試合を視察したリョーマはそこでリョーガがチームから姿を消したことを知らされる。一方、手塚の元を跡部が訪れ自主トレーニングの相手を買って出る。跡部がドイツの施設に入るのを偶然見かけた切原は、跡部と手塚の姿を目撃、手塚がスパイなのでは? という疑念を持つ……。', '2024/10/05 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3caeef0e-e49e-404a-94c0-f7268ce06c0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9471a445-b83f-407c-a054-0c4613723594', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 2, '100199588', '青い鳥', '準決勝初戦、S3 (シングルススリー)。日本は鬼。対するドイツはチームNo.2と言われるQ･P。互いに正確無比なショットを打ち、さらにパワー勝負でも互いに一歩も譲らない両者。相手を圧倒する迫力で迫る剛腕の鬼に対し、観客からの声援をノイズと捉え審判に忠告をするQ･Pは冷徹ともいえるプレイスタイル。その原点は彼がテニスを始めた幼少期の頃にあった……。', '2024/10/12 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af8088fc-9131-44bd-b70f-329c5755170c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f22579a0-c21f-4b6d-826b-76e374698b6c', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 3, '100199589', '誰 (た) がために強く', '「天衣無縫の極み」を発動した鬼。それはリョーマや金太郎のものとは違う「心強さ」の輝き。圧倒的有利に試合を展開させていく鬼。だが、この展開は「完璧な品質」であるQ･Pを「究極の品質」へと昇華させる結果を招く。瞬く間に流れを引き戻すQ･Pに対し「ハートに火が点いた」鬼。しかし、Q･Pの強烈なサーブを打ち返した瞬間、鬼の手首が鈍い音をたてる――!', '2024/10/19 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7338bd2-f0c4-4d7a-93ca-64d8f7550d1f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a320e379-facd-4478-99b9-5e9d5a22570c', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 4, '100199590', '最期のイリュージョン', '準決勝D2 (ダブルスツー)。デューク&仁王ペアに対するのは、プロのシュナイダーとボルクの弟･ベルティのペア。仁王は、平等院にイリュージョンして挑む。しかし、あらゆる選手のデータをインプットしたベルティと、シュナイダーの思わぬ技で対応されてしまう。一方、かつてリョーマが所属したアメリカ代表は、強豪･スペイン代表に苦戦していた。後がないアメリカはラルフがS2 (シングルスツー) に登場。対するスペインベンチから歩み出たのは、越前リョーガだった……!', '2024/10/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44001df6-4515-48bc-b7b2-5e327f6a1a06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a185a2c-2a0e-496d-a50a-e70a6ac1984f', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 5, '100199591', '手塚vs幸村', 'D2 (ダブルスツー) はいよいよクライマックスに突入。イリュージョンを捨て、「仁王雅治」のオリジナルとして挑む仁王。これまでのデータが唯一ゼロである仁王のプレイに翻弄されつつも、徐々に押し開けるシュナイダー&ベルティ。その激戦の結末は――そして第3試合･S2 (シングルスツー)。ドイツ代表は手塚国光。その対面に立つ日本代表は幸村精市!「一瞬の瞬きも許されない」戦いの幕が開く――!', '2024/11/02 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8297524-c43b-4018-8563-abac80ff64ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a2b7f3f-5a1b-4371-9416-be45a5285e52', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 6, '100199592', '零感のテニス', '「天衣無縫の極み」＝「矜持の光 (シュトルツシュトラール)」を発動した手塚に対する幸村。幸村は試合前夜、真田を通し切原に「天衣無縫にならなくても勝てる」と伝えていた。幸村が手塚に対し発動したのは「零感テニス」と「蜃気楼の鏡 (ミラージュ･ミラー)」。日本代表の中学生たちの協力により生み出された2つの技で手塚に反撃に転じる幸村。だが、王者ボルクの期待とプロへの覚悟を背負った手塚は「手塚ゾーン」と「手塚ファントム」と融合させた新技を繰り出し――', '2024/11/09 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2ecbb53-77f4-4a1d-8d20-c87a3f939472.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf5bb9d2-0077-497d-b566-3e05b7aa4b92', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 7, '100199593', '激闘の先にある未来', '幸村と手塚の壮絶なラリーが続く。その姿をまじろぎもせず見つめるベンチの切原。試合中の全打球と全展開を覚えていて対応してくる手塚に「君の未来、奪わせてもらう」と宣言する幸村。これに対し、「未来を塗り替えてきます」とレンドール監督とボルクに宣言する手塚。ファイナルセットで手塚に追いつく幸村。最後の死力を振り絞った両者の激突が始まる!', '2024/11/16 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b67ed7d-555e-461b-92ef-e88369c76a9e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1c9a023-6528-477e-a263-f2bf2db67e62', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 8, '100199594', 'スペイン代表、越前リョーガ', '準決勝別ブロックでは、アメリカ代表ラルフが今はスペイン代表となったリョーガに一方的な試合展開で追い込まれていた。リョーガの持つ技――それは「対戦相手のテニスの能力を喰らう」というもの。リョーガがラルフのテニスを弱体化させ、スペインの決勝進出を決める。日本vsドイツのD1 (ダブルスワン)――切原･種ヶ島ペアとビスマルク&ジークフリートペアの戦いが開始される。', '2024/11/23 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4cb2d67-3f6b-487b-85de-819acdc854a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('affb0c8b-e3cb-4c3f-a3f3-c247e6129561', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 9, '100199595', '集中爆発 (バースト) vs天衣無縫', 'ジークフリートを圧倒する切原の「集中爆発 (バースト)」だが、持つのは僅か10秒。切原は猛チャージをかけた勝負を挑んでくる。だが、手塚の台頭により諦めかけていた準決勝メンバーへ選抜されたジークフリートの闘志は、やがて「集中爆発 (バースト)」を抑え込み始める。さらに、ジークフリートは、切原を挑発し、敢えて「悪魔 (デビル) 化」させる。それはビスマルクから授けられた作戦だった――。', '2024/11/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fced4c26-4863-46b0-9c55-115caab3b92d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f30d938-87b2-47d9-9dd1-8ec212afeb21', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 10, '100199596', 'タイブレークの行方', 'D1 (ダブルスワン) は、両チーム共にパートナーを欠いた状態で、種ヶ島とビスマルクによる戦いが続く。リターンゲームがとれない以上、試合をタイブレークにもちこみ、サービスゲームをキープして勝利する――それが種ヶ島の狙い。だが、日本のベンチで乾が呟く――「タイブレークはまずい…」ビスマルクはタイブレーク勝率100%。「ミスター･タイブレーク」の異名を持っていた――!', '2024/12/07 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c77926d-986c-4871-8ac4-a93bf6d300d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89d80fd9-fd2d-4f2b-bcc3-036162072ba7', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 11, '100199597', 'ファイナルセット', '土壇場で意識を回復した切原のファインプレーにより、試合はファイナルセットまで持ちこまれる。ジークフリートも回復し、再びダブルスとしての戦いが始まる。挑発で「悪魔 (デビル) 化」しそうな切原をコントロールしていく種ヶ島。切原の「集中爆発 (バースト)」と種ヶ島の「不会無 (ふえむ)」が噛み合い、有利に試合を進める日本ペア。だが、ドイツペアが発動した「存在境界 (ザイングレンツェ)」により、日本ペアは絶体絶命の窮地に陥ってしまう――。', '2024/12/14 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f256888-9d6b-4cde-96f5-7c45a099003a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('945c74f7-0747-49dd-8c4b-d59ca36a7bf7', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 12, '100199598', '螺旋の洗礼', '両チーム、決勝進出の行方はS1 (シングルスワン) に託された。ドイツは世界最強の男･ボルク。対するは、日本代表を率いる男･平等院。世界を武者修行として渡り歩き、猛者たちと戦いを繰り返す中で身に着けた数々の技を繰り出していく平等院。それに対応するボルク。まさに「世界最高峰の一戦」に恥じない互角の戦い。しかし、試合を見つめるリョーマたちは異変に気付く。平等院は、同じ言葉･同じ技。それもボルクに返された技を繰り返している……?', '2024/12/21 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3cbaf09-d355-4faa-9917-2a17bc382ad3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5849ecb1-9467-4eb6-9cfc-39481f6757d6', 'abf66a31-3adb-4e31-8630-6d6377c1b756', 13, '100199599', '命を懸けたテニス', '【シーズン1 最終話】タイブレークへともつれこんだS1 (シングルスワン)。1つのミスが勝敗を左右する緊迫感の中、容赦ないボルクの攻勢に、「命を懸ける」気迫で挑む平等院。両者一歩も譲らないまま、ついにファイナルセットを迎える。ベンチに戻ってきた平等院が既に限界を超えていることは明らかだった。平等院はリョーマと徳川を呼び寄せると、「日本を任せたぞ」と2人に言い残し最後の戦いへと歩みだす――!', '2024/12/28 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74dc19e8-b200-4893-855d-dc2966e9359e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d2dbad44-e27f-41e8-b730-62ccc664ebf6', 'シンカリオン チェンジ ザ ワールド', '', 'hulu', 'shinkalion-z', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44e2f948-9429-4252-8aae-29fda534bba6.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 172395, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('18507749-f896-4c89-a37f-31cfcb36e387', 'd2dbad44-e27f-41e8-b730-62ccc664ebf6', 'hulu-shinkalion-z-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81b8567e-bf3e-4f03-b438-734652981b6e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4882f279-6631-4f86-87be-9b320f45375b', '18507749-f896-4c89-a37f-31cfcb36e387', 1, '100078460', '新たなる出発進行!', '小学5年生の新多シンは、「世界の謎を解き明かす男」を自称するオカルト好き。その日も宇宙人の目撃情報を聞きつけて、JR横川駅周辺の調査にきていた。その道中で通りがかった「碓氷峠鉄道文化むら」に、謎の新幹線が運び込まれたという噂を聞いて、何年か前に話題になった新幹線のような幻のロボット「テツドウダー」と関係あるのではないかと怪しむシン。新たな謎に心ひかれるシンだったが……?', '2021/04/13 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81b8567e-bf3e-4f03-b438-734652981b6e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7774ce67-ee96-417e-851a-6bc74cbd13eb', '18507749-f896-4c89-a37f-31cfcb36e387', 2, '100078461', 'Z合体! E235ヤマノテ', '正式に「シンカリオンZ E5はやぶさ」の運転士となったシンは、シンカリオンの操縦シミュレーションのため、再び碓氷峠鉄道文化むらを訪れる。そこで待っていたのは、シンと同い年ながらシンカリオンの改造にも関わっている天才整備士･碓氷アブトだった。 だが、アブトはなぜかシンカリオンを運転できないのだという。シンが何気なくその理由を尋ねると、アブトは表情を硬くしてその場を立ち去ってしまった……。', '2021/04/20 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa955a3f-37c0-4e4d-b9e1-b2b7149ff278.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6244676-ccd9-4843-ad24-78c20bc94fb8', '18507749-f896-4c89-a37f-31cfcb36e387', 3, '100078462', 'ぶち抜け! VVVFブラスター!!', 'シンたちは「E6系こまち」に乗って、アブトが夢で見た盛岡駅に「Zコード」を探しに行くことになった。Zコードは日本全国に隠されており、それを見つけることで新たなザイライナーが閉塞解除されるという。どうしてZコードのヒントがアブトの夢に出てくるのか? どうしてZコードを全国に隠したのか? シン、アブト、スマットは不思議に思いながらも、新しいザイライナー、新しいZ合体を見つけるために、盛岡駅周辺を探し歩く。', '2021/04/27 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e532421-5219-42d5-880c-9f1e05e69c33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ffa2ad1-78fb-43fa-826f-3dfa7d8b93ed', '18507749-f896-4c89-a37f-31cfcb36e387', 4, '100078463', '打ち上げろ! ハナビのロックンロール!!', '「シンカリオンZ E6こまち」の運転士･大曲ハナビは、ロックンロールをこよなく愛する熱い少年だった。彼の実家は、秋田県大曲名物の花火を作っている花火工場。ハナビは花火師になるという夢を追いかけながら、自分が好きな音楽の道も、シンカリオンの運転士の道も、本気でやっていると言う。 だが、ハナビの父･タネビは、やりたいことをいくつも掛け持ちしているハナビの生き様を認めようとしなかった。', '2021/05/04 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0703c056-9fcb-4c12-bcdb-eebbf9e02d0d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31054bab-6482-4808-8bee-475075f6d19f', '18507749-f896-4c89-a37f-31cfcb36e387', 5, '100078464', '森を守れ! シンカリオンZ E7かがやき', '長野県にある木曽のとある山にやってきたシンたち。アブトによると、ひとけのないこの山奥に3人目のシンカリオン運転士候補･戸隠タイジュがいるらしい。しかし、タイジュは運転士になることに乗り気ではなく、すでに誘いを一度断られたあとだという。もともと東京に住んでいたが、事情があって木曽のとある山に移り住んだというタイジュ。シンたちが登山の末に彼を見つけると、タイジュは祖父のもとで山仕事の見習いを始めていた。', '2021/05/11 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20431b21-0857-49a4-baf3-3aee0a0533e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2cd9c3c-2b3b-40bd-ada9-74eaea9ff846', '18507749-f896-4c89-a37f-31cfcb36e387', 6, '100078465', '振り抜け! 友情のコウデンアツアックス!!', '新たなZコードを見つけるため長野駅にやってきたシンたち。残念ながらタイジュを運転士に迎えるのは無理そうだとアブトは諦めていた。それでももう一度タイジュと話してみたいシンは、アブトたちに頼んで再び彼に会いに行く。タイジュは、祖父･マサカリにアドバイスをもらい、自分のこだわりを理解してもらうためにシンを森林鉄道記念館に連れて行くことにする。', '2021/05/18 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f17fb2eb-d9e7-4285-931e-c694ec8d361f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2cf68fa-0128-47d0-865e-164c1bddc1be', '18507749-f896-4c89-a37f-31cfcb36e387', 7, '100080694', '強襲! 横川支部防衛戦!!', 'シンカリオンの整備士、細川が「妖怪を捕まえた!」と駆け込んできた。細川によると、捕まえたのは人間に化ける「バケダヌキ」だそうだが、シンたちの前にいるのは普通のタヌキにしか見えず、妖怪だという証拠はどこにもない。そんな中、シンだけは「バケダヌキと友だちになる!」と目を輝かせる。 そのころ、シンカリオンによって何度も巨大怪物体を退けられたワダツミは、自らの力で横川支部を襲撃しようともくろんでいた。', '2021/05/25 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8183f2d2-9b9f-40e6-a657-90d38a10bec1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6bd34373-fb4c-4117-a728-42b5be1cc87a', '18507749-f896-4c89-a37f-31cfcb36e387', 8, '100080695', '集結せよ! 大宮支部再始動!!', 'シンとE5はやぶさが大宮支部に引っ越す日が近づいてきた。しかし、アブトは同行せず、横川支部に残るという。納得できないシンとスマットが理由を問いただすと、アブトは自分の家族のことを語り出す。 一方、大宮支部にはE5、E6、E7が集結。ハナビとタイジュ、横川支部のスタッフとともに、かつての戦いを経験した新しい仲間たちも顔を揃えていた。そこに巨大怪物体が現れ、大宮支部での戦いが幕を開ける。', '2021/06/01 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56896736-7b91-4470-b93e-3c65e270d4ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87ac36c3-4c24-4021-a6ef-f019a45d31b8', '18507749-f896-4c89-a37f-31cfcb36e387', 9, '100080696', '翔けろ! シンカリオンZ 800ソニック', '突如九州に現れた巨大怪物体を退けたのは、空を飛ぶ新たなシンカリオン、「シンカリオンZ 800つばめ」だった。運転士は中洲ヤマカサ。シンたちよりひとつ上の小学6年生で、知力･体力ともに非常に優秀な運転士だという。Zコードを探すため、ヤマカサと共に太宰府周辺を探索するシンたち。だが、重大な問題が発生した。なんと、ヤマカサはシンの妖怪話を「非科学的だ」と言い放ち、まるで取り合おうとしなくて……!?', '2021/06/08 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da5c6ffa-bbb8-4faa-b4d6-1862f3563e9e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb726002-b0b8-4bc6-b995-3dd200f121e1', '18507749-f896-4c89-a37f-31cfcb36e387', 10, '100080697', '大空中戦! 波乱のZ合体!!', 'シンとヤマカサの相性は水と油で、どうしても打ち解けられそうにない。ヤマカサはシンの「非科学的な」話に興味を示そうとはせず、シンもヤマカサを遠ざけてしまっていた。 どうすればヤマカサが自分の話を聞いてくれるか悩むシンに、ハナビとタイジュ、アブトとスマットがある作戦を提案する。それは、シンが苦手で食べられない「おきゅうと」をいろんなアレンジレシピで食べてみるという突拍子もない作戦で……?', '2021/06/15 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af2f8715-3846-4362-9ae6-fa72a0dcdbc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62f87149-05ff-424a-a61e-419c5e6bbaab', '18507749-f896-4c89-a37f-31cfcb36e387', 11, '100080698', '初陣! シンカリオンZ N700Sのぞみ', 'アブトが夢で見た名古屋へやってきたシンたち。同じころ、超進化研究所 名古屋支部では、安城シマカゼ、安城ナガラというふたりの兄弟が「シンカリオンZ N700Sのぞみ」の運転士を決める最終試験に臨んでいた。 試験の結果は両者合格。しかし、兄のシマカゼは運転士の座を弟のナガラに譲り、自分は辞退してしまった。シマカゼに逃げられたようで気にくわないナガラ。その時、名古屋港に巨大怪物体が襲来して……?', '2021/06/22 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06625157-cc12-48a3-9ec5-62559a95a3c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('111532db-645e-4af8-82d9-01a9c01f5b29', '18507749-f896-4c89-a37f-31cfcb36e387', 12, '100080699', '秘技! デュアル･グランパス･システム', '華々しい初陣を飾ったN700Sのぞみ。シマカゼに助けられたナガラは、運転士の座をかけて、改めてシマカゼに空手の勝負を申し込む。リュウジが立会人となって、兄弟の拳での語り合いが始まった。 一方、アブトはZコードが隠されている場所のさらなるヒントを夢に見る。ところがそのヒントは、「東京でもあり、名古屋でもあり、京都でもある」という摩訶不思議な場所を示していた。', '2021/06/29 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8ab2c84-7d60-40a8-9ffe-f962b0d03109.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('043d7748-c906-4c0a-b06a-85775a9c3f55', '18507749-f896-4c89-a37f-31cfcb36e387', 13, '100085001', '起てよZ合体! 関ヶ原総力戦!!', 'アブトが父の設計図どおりに作った『シンカリオンZ N700Sのぞみ』と『ザイライナー HC85ヒダ』のZ合体テストが失敗してしまう。このままでは父に追いつけないと焦るアブトは、島に連れられてかつての父の職場を訪れる。そこは、鉄道の技術革新の担い手･先導役である「鉄道総合技術研究所」だった。 その時、関ヶ原に巨大怪物体が出現。シンカリオンZを待ち受けていたのは、ソウギョクがしかけた無数の敵だった。', '2021/07/20 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3abf8306-fc73-4f78-a646-25b252db533f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2457b23a-f17b-45fd-8d5f-608380275404', '18507749-f896-4c89-a37f-31cfcb36e387', 14, '100085002', '斬黒! ダークシンカリオン!!', '鉄道博物館に「謎の巨人」が出現するという噂を聞きつけたシンは、ハナビ、タイジュ、アユとともに潜入調査を試みる。すると、彼らは本当に巨人らしき人影を発見してしまう。その巨人と友だちになるため、シンはアユたちを巻き込んで鉄道博物館で大捜索を繰り広げるが……? その折、大宮支部を目がけて「闇の新幹線」が襲来。なんと「闇の新幹線」は自ら変形し、シンカリオンZになって襲いかかってきた!', '2021/07/27 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35b1be39-d681-48c5-a5f8-2842a4612a71.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('340bb305-fe52-4f42-b3f7-c1005f556718', '18507749-f896-4c89-a37f-31cfcb36e387', 15, '100085003', 'リーダーの資格! 怒りのZグランクロス', 'シンのひらめきで、テオティが狙う謎の結晶体、「ブラックストーン」のありかの手がかりがつかめた。これまで巨大怪物体が出現した場所が、昔からある街道沿いだということに気付いたのだ。それを知ったゲンブは、シンたちを東京都内のさまざまな街道関連スポットに案内する。ゲンブには、かつてあった「万世橋駅」のことを通じてシンに伝えたいことがあるようで……?', '2021/08/03 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c820e96-02ae-4c41-8b56-753402029c3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b91840d-47fb-40b9-a033-ddd98d23e3aa', '18507749-f896-4c89-a37f-31cfcb36e387', 16, '100085004', '可憐に降臨! シンカリオン ハローキティ', 'かつての戦いでシンカリオンに手痛い敗北を喫したあと、キトラルザスのソウギョクは新たな協力者を探していた。そんな折、彼はとあるきっかけからふるさとの桜島に帰ることになり、盛岡駅から鹿児島中央駅への在来線の旅を始める。一方、元気のないシンは、ハナビとタイジュに連れ出されて温泉旅行に行くことに。その道中で、シンたちは車体にキティちゃんが描かれた新幹線と出会う。', '2021/08/17 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f416ff72-43a0-4f0b-8fca-80f2e4732fbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d5a97a0-28a9-4636-b735-89f99a45a8aa', '18507749-f896-4c89-a37f-31cfcb36e387', 17, '100085005', 'きらめく☆シンカリオンZ 500こだま', 'シンが「シンカリオンZ E5はやぶさ」に乗って戦っていることが姉のアユと母のトキにバレてしまった。シンは自分のやっていることを理解してもらうため、二人を横川の鉄道文化むらの「車両ペイントイベント」に誘う。鉄道文化むらには、ハナビやタイジュの家族や大宮支部のスタッフたちもやってきていた。その頃、細川は島から特別な任務を任される。それは、京都支部の「シンカリオンZ 500こだま」のZ合体に関する重大な任務で……?', '2021/08/24 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/502e7db8-0406-452d-97d6-246bc08b1112.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fad95b17-88dc-40ce-b4a7-5b3875ce2bf6', '18507749-f896-4c89-a37f-31cfcb36e387', 18, '100085006', '巌流島決戦! シンVSギンガ!?', '鮮やかなデビューを飾った「シンカリオンZ 500こだま」の運転士、嵐山ギンガに会うため、シンたちは新幹線超進化研究所 京都支部を訪れる。ギンガは芸能事務所に研究生として所属するアイドルの卵で、キラキラした雰囲気を持つ異色の少年だった! なぜか適合率が下がってしまい、元気のないシン。そんな彼を見て、ギンガはチームシンカリオンの「センター」を自分が務めると言い出し、シンたちを驚愕させる。', '2021/08/31 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/477a49db-477f-4f06-b241-d251e10d4a58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9dd275d-4a31-4dda-a573-5f446565165b', '18507749-f896-4c89-a37f-31cfcb36e387', 19, '100090171', '輝け! オオサカカンジョウシンゴウトウ', '細川が開発を進める「ザイライナー 323オオサカカンジョウ」が完成間近。京都でZコードを探し始めるシンたちだが、「アブトの夢」という手がかりがなくなったために場所の見当さえつかない。疲れ果てたシンたちを、ギンガは自分のライブに誘う。 一方、ついに父･トコナミとの再会を果たしたアブトは、彼こそがダークシンカリオンの開発者であることを知る。さらに、トコナミには重大な秘密があるようで……?', '2021/09/07 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2bc76683-4ee0-48fd-b4a9-3b86de534dea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfc6f305-baa7-453c-8a33-248a4922d741', '18507749-f896-4c89-a37f-31cfcb36e387', 20, '100090172', '覚醒せよ! ヤマノテエキスカリバー!!', '大宮支部で運転士一同を集めて懇親会が開かれることになった。しかし、スマットの様子がおかしい。慕っていたアブトが敵になってしまったショックで、スマットは無意識のうちにアブトに関わるデータを封印しようとしているらしい。スマットを元に戻すため、シンは横川にあるアブトの家に向かう。その頃、度重なる敗北に戦士としての誇りを傷つけられたワダツミは、自らの全てをかけてシンカリオンとの決着をつけようとしていた。', '2021/09/14 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b52fef71-d9ab-4255-92e7-76b522d532b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa77e2c2-c3c8-4836-a50f-8434f156f241', '18507749-f896-4c89-a37f-31cfcb36e387', 21, '100090173', '出撃、シンカリオンZ 500 TYPE EVA', '京都･太秦映画村にヴァルトムが侵入し、アトラクションのエヴァンゲリオン初号機像を巨大怪物体に変えてしまった。だが、巨大怪物体化した初号機像は暴走し、ヴァルトムですら制御できない状態となってどこかへ姿を消してしまう。翌日、インターネット上でささやかれる都市伝説「きさらぎ駅」を探して遠州鉄道に乗っていたシンたちは、降車した駅で不思議な雰囲気をまとった男と出会う。', '2021/09/21 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c1ade19-b76e-4fd2-ba13-0272bb42c8f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e90f403-c36a-40e2-a38d-747f2ecbd6ee', '18507749-f896-4c89-a37f-31cfcb36e387', 22, '100090174', '逆襲のシンカリオンZ ドクターイエロー', '「鉄道の日」にちなんだイベントを開催中の大宮鉄道博物館に、アブトの母･シラユキがやってきた。シラユキからアブトへの伝言を受け取ったシンは、なんとかしてアブトと連絡を取ろうと様々な方法を試す。そんな中、同じくアブトとの対話の方法を模索していた島に誘われて、シンは名古屋支部で行われる新型シンカリオンの実働テストを見学することに。果たしてそのシンカリオンとは……?', '2021/10/05 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/497ba68b-c5ee-4816-8128-641354285036.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a338105e-3687-4373-9a20-2c751917e155', '18507749-f896-4c89-a37f-31cfcb36e387', 23, '100090175', '地下決戦! ドクターイエロー Zホセンモード', '横川の地下空間でダークシンカリオンに乗るアブトと再会したシン。シンとスマットは彼と対話しようと必死に呼びかけるが、アブトからの返事はなく、戦いにもつれこんでしまう。 一方、上野の地下空間ではドクターイエローとカンナギが対峙していた。カンナギは「ダークシンカリオンがあるかぎり、人類はテオティを止められない」と言い残して姿を消し、E5とダークシンカリオンの戦いに介入し始める。', '2021/10/12 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e890daa2-604d-43ab-9bd1-6fe34d23331e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('000a6398-629a-47e3-bc8b-1a3e8b4c97af', '18507749-f896-4c89-a37f-31cfcb36e387', 24, '100090176', 'セイリュウの帰還', 'アブトと対話するための強さを求め、シンカリオンZの運転士としてもっと成長したいと願うシン。そんな彼に対して、ゲンブはキトラルザスのセイリュウと名乗る人物を引き合わせる。かつての戦いでシンカリオンに乗り、地球を守り抜いたというセイリュウ。彼が直々に修行をつけてくれると聞いて期待するシンたちだが、セイリュウの修行はシンたちが想像したものとは全然違っていて……?', '2021/10/26 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f83b395-9958-4baf-bf88-cae3306ca925.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d19f88e9-3511-4af1-ab5a-293734828e0e', '18507749-f896-4c89-a37f-31cfcb36e387', 25, '100094561', 'SHIKOKU ROCK FESTIVAL', '徳島県大歩危、岩手県遠野。妖怪にゆかりの深い二ヶ所に新たな地下空間が見つかり、大興奮のシン。その直後、大歩危付近に子泣きじじいに似た姿の巨大怪物体が出現した。折しも、愛媛県西条市ではハナビの父･タネビたちが翌日の花火大会の準備を進めている最中。対応を迫られる超進化研究所だが、四国にはシンカリオンZが走行できる線路がない。果たして、E6こまちを大歩危に送り込む方法はあるのか……?', '2021/11/02 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9963c92-ddf5-4ea6-9dae-860a6aad2404.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44fdd226-363b-456c-b190-97feff62cb50', '18507749-f896-4c89-a37f-31cfcb36e387', 26, '100094562', 'タイジュと銀河鉄道の少女', '遠野で見つかった地下空間の調査のため、現地へ向かうタイジュと大石。お互いに読書好きということが分かり意気投合した二人は、これから行く岩手県が宮沢賢治のふるさとという話題で盛り上がる。道中、新幹線の中でうたた寝したタイジュは、宮沢賢治の『銀河鉄道の夜』の光景によく似た夢を見る。すると、その夢に金色の髪をした不思議な少女が現れて、タイジュに何かを語りかけようとしてきた。', '2021/11/09 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80e67e18-def9-4207-8fc0-e58b41d1f6de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80f62957-f6c2-48c8-8336-dcd9f428fc9a', '18507749-f896-4c89-a37f-31cfcb36e387', 27, '100094563', '脅威! ヴァルトムの執念', 'チームシンカリオンに新たな力が加わろうとしていた。その名も、E5はやぶさとドクターイエローによる「超Z合体」。超進化研究所が総力をあげて開発した最高の機体性能を誇る。しかし、「超Z合体」を成功させるには、運転士であるシンとシマカゼの適合率が96%以上、かつ二人の差が0.1%以内という厳しい条件をクリアする必要がある。シンとシマカゼは早速二人の息を合わせるための特訓を始めるが……?', '2021/11/16 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/54b344ed-c085-420b-87d9-f592258533d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1406beb-ae36-45c3-a68f-f9cf071bacf0', '18507749-f896-4c89-a37f-31cfcb36e387', 28, '100094564', '交信せよ! シンカリオンZ H5はやぶさ', 'シンとシマカゼが「超Z合体」の特訓に励む一方で、北の地に戻ったソウギョクはまたしても宇宙に向けたあてのない定時通信を続けていた。誰からも返事がもらえず、定時通信をやめてしまおうと考えるソウギョク。だが、そんな彼の無線を北海道で聞いている一人の少女がいた。彼女の名前は月野メーテル。「シンカリオンZ H5はやぶさ」の運転士候補生である彼女は、とある人物に促されてソウギョクとの対話を試みようとする。', '2021/11/23 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ddc22c3-a300-428e-a468-0408dca2bbf6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39984d0b-b6e8-4299-9836-637835169342', '18507749-f896-4c89-a37f-31cfcb36e387', 29, '100096787', 'テオティ動乱! 急襲、ダークシンカリオン', '追い込まれたヴァルトムがテオティの王を手にかけて「王の力」を奪い取り、現場を目撃したセツラをさらって地球へと逃走した。それを知ったアブトは、セツラを救出するためにダークシンカリオンで地球に急行する。その頃、日本では福岡県宝満山に落下した不自然な隕石のニュースが話題になっていた。現地の調査に赴いたヤマカサはそこでアブトの姿を見かけ、驚いて後を追おうとする。', '2021/12/07 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2500b697-37ee-4d6c-bebb-c9d411c94967.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e63554b-2f1b-40de-85db-b3abf3b1a71d', '18507749-f896-4c89-a37f-31cfcb36e387', 30, '100096788', '超Z合体! シンカリオンZ E5ドクターイエロー', '東京駅中央迎撃システムのフィールド内で対峙するシンカリオンZたちとダークシンカリオン。シンたちが必死で呼びかけるものの、様子がおかしいアブトは問答無用でダークシンカリオンを操り、襲いかかってくる。戦いの中、怒りと無力感にのまれ、ついにトレランティアを爆発させるアブト。父･トコナミの祈りも虚しく、脅威の力を持つ「ダークシンカリオン デビルモード」が覚醒してしまう……!', '2021/12/14 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88d96183-c941-43ff-9eaf-7bda332a5638.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f3469f7b-4d06-43d6-ac0c-f04709b1668e', '18507749-f896-4c89-a37f-31cfcb36e387', 31, '100098476', 'スクープ! アユの特ダネ最前線!!', 'もうすぐクリスマス。海外での仕事が一段落した父親が久しぶりに帰ってくるとあって、新多家ではシンを中心に入念なクリスマスパーティーの準備が進められていた。そんな中、偶然アケノと再会したアユは、ジャーナリストになるという夢に向けたアドバイスをもらうべくアケノをお茶に誘う。だが、逆にアケノからシンカリオンZの秘密について問い詰められてしまい……?', '2021/12/21 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f0f83e0-fb96-439f-a37e-3eeb0c41a3b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9404cca0-e152-4d11-bc24-503b77b385b5', '18507749-f896-4c89-a37f-31cfcb36e387', 32, '100098477', 'H5ホクトVSヴァルドル 銀河の旅路', 'ある夜、メーテルが無線を聞いていると、不思議な音とともに正体不明の飛行物体が落下してきた。機関車のような外見をしたその飛行物体は、かつてシンカリオンが戦い、退けたはずの機械兵器･ヴァルドル。長い間宇宙をさ迷ってきたのか、車体はひどく劣化していた。 ヴァルドルが発し続ける不思議な音には何か意味があると考えるメーテル。シンとタイジュも応援のため、E5はやぶさとE7かがやきで北海道支部に向かう。', '2021/12/28 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c19ee9a6-3a7c-4ed2-9a2e-60961c725519.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9fb91ca2-4d95-4332-b003-ad250f831303', '18507749-f896-4c89-a37f-31cfcb36e387', 33, '100098478', '伝説の運転士! 速杉ハヤト', 'セツラからもたらされた情報によって、テオティの本拠地「ユゴスピア」が宇宙にあることが判明し、意気揚がるシンたち。ちょうどその時、かつて「シンカリオン E5はやぶさ」で日本を救った伝説の運転士･速杉ハヤトがイギリスから帰ってきた。ハヤトに誘われ、セツラを連れて初詣に出向くシン、ハナビ、タイジュ。ところが、ハヤトの目的は普通の初詣とは少し違うようで……?', '2022/01/18 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/039fe715-e6f4-4b83-aa83-7ff2ecda3f57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2683a4ad-9652-436e-a874-7a06d7024496', '18507749-f896-4c89-a37f-31cfcb36e387', 34, '100098479', 'The Galaxy Express E5', '宇宙にあるテオティの本拠地に行けると聞き、鹿児島県の桜島へ向かうシンたち。そこには超進化研究所の実験線があり、シンカリオンZを宇宙に打ち上げることができるのだという。 打ち上げタイミングは46時間後。また、宇宙に運べるシンカリオンZは一度で一編成だけだ。アブトと対話をするため、そしてテオティとの共存の道を探るため、打ち上げへのカウントダウンが始まる……!', '2022/01/25 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/969897ee-cba6-4f27-a2d2-29dcc04ae6a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3d1b5dba-2de7-4881-9dde-bbf3662805d9', '18507749-f896-4c89-a37f-31cfcb36e387', 35, '100098480', 'トコナミの過去', 'ダークシンカリオンに敗れて宇宙を漂っていたE5はやぶさは、テオティの戦士たちに回収された。シンの無事を喜ぶ一方で、敵であるはずのテオティが助けてくれたことを不思議に思うヤマカサたち。そこに、アブトの父･トコナミが現れる。なぜダークシンカリオンを作ったのかとトコナミを問い詰めるシン。トコナミはシンに一枚の写真を見せ、自分が地球で過ごした日々のことをシンに語り始める。', '2022/02/01 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01030b6f-47e8-4441-8622-3f8f75ff5a00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('111f9cb0-aa7b-4fb5-a058-9c4044700da8', '18507749-f896-4c89-a37f-31cfcb36e387', 36, '100102597', '決着、シンとアブト', '運転士たち、そしてテオティの人々が見守る中、激しくぶつかり合うE5はやぶさとダークシンカリオン デビルモード。アブトの思いを全て受け止めるため、シンは決死の戦い方を選択する。その頃、地球から宇宙へ「ザイライナー E235ヤマノテ」が打ち上げられた。だが、ユゴスピアでザイライナーを起動することはできない。果たしてZ合体はできるのか……!?', '2022/02/08 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43788607-4441-4cbb-a3a7-d01ddd9665bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0bad7cb5-700c-4fb0-bfab-236dd75b150d', '18507749-f896-4c89-a37f-31cfcb36e387', 37, '100102598', '超進化! ダークシンカリオン', '横川の自宅に帰ったアブトを待っていたのは、学校を欠席中に溜まった山積みの宿題だった。シンとスマットにも手伝ってもらい、猛烈な勢いで宿題をこなしていくアブト。彼らは夏休みの自由研究のテーマを見つけるため、碓氷峠鉄道文化むらへ向かう。一方、大宮支部では回収したダークシンカリオンの解析が進められていた。解析の結果、ダークシンカリオンには恐るべき「回路」が組み込まれていることが判明し……!?', '2022/02/22 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3448599d-1c36-4d6f-8ec9-8886c4bff902.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72001285-941f-4c84-9029-a999adef71d6', '18507749-f896-4c89-a37f-31cfcb36e387', 38, '100102599', '完全制覇! シンカリゲッター', 'ある日、スマットを操作していたアブトが突然叫びだした。聞けば、スマットと運転士たちのZギアには、訪れた駅を自動で記録する「シンカリゲッター」というアプリがインストールされていて、アブトがいない間に完全制覇目前になっているという。残るは、アプト式の区間もある静岡県･大井川鐵道の各駅のみ。最後は自分の足で記録する、と意気込むアブトとともに、シンとスマットも現地への旅を楽しむ。', '2022/03/01 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3dde4697-c967-4149-b665-5f9635a4c857.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c5cf988-fca4-44b3-b4aa-5514feb4a1de', '18507749-f896-4c89-a37f-31cfcb36e387', 39, '100102600', 'カンナギVSダークシンカリオンアブソリュート', '突如現れた謎の流動体によってカンナギが地下に飲み込まれ、言葉を失うシンたち。同じ頃、ヴァルトムの策略によってブラックストーンが一斉に破壊され、全国各地にも謎の流動体が出現していた。ブラックストーンが封印していた破壊神･アラバキが復活してしまったのか? 飲み込まれたカンナギの安否は? 急変した事態に対応するため、シンカリオンZ各機は全国各地に急行する。', '2022/03/08 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84e88ebf-d12e-4a03-8b44-5034b0bb6b73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6557a901-6c29-4634-a16a-40ec9513ebd2', '18507749-f896-4c89-a37f-31cfcb36e387', 40, '100102601', '復活!! 破壊神アラバキ', '禁断のテオティコードを使った者の宿命により、死ぬまで戦い続ける暴走状態と化したカンナギ。再び立ち向かうアブトだが、カンナギの力はダークシンカリオンアブソリュートをも圧倒する。そして、その間にも全国各地に現れた謎の流動体が続々と富士山の地下に集結。とうとう全ての流動体がひとつになり、破壊神･アラバキが真の姿を取り戻してしまった……!', '2022/03/15 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/deb0f8af-5db1-4e6a-9300-5d8ad8cb15eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d20b8b76-5f49-447b-afcc-84c8f5039097', '18507749-f896-4c89-a37f-31cfcb36e387', 41, '100104458', '可能性は無限大!', '【最終話】アラバキの弱点が塩であることを突き止めたシンたちは、富士山の地下で最後の決戦に挑む。かつてない敵からこの星を守るため、手を取り合う人類、キトラルザス、テオティ。すべての「レール」が繋がったとき、とっておきの切り札「ダブルZ合体」が発動する! シンカリオンZ、最後の出発進行!', '2022/03/22 12:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3adc6be2-23c4-4b59-b19b-fadb3e4b74b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8364c8a1-5bbb-46bc-b008-c004a9d0d0aa', '新米オッサン冒険者、最強パーティに死ぬほど鍛えられて無敵になる。', '', 'hulu', 'shinmai-ossan-boukensha-saikyou-party-ni-shinuhodo-kitaerarete-muteki-ni-naru', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47b82a1d-a290-49bd-a255-e84e8c9d4846.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 163292, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6806cdb7-e569-431d-89b8-46830ce4fc2c', '8364c8a1-5bbb-46bc-b008-c004a9d0d0aa', 'hulu-shinmai-ossan-boukensha-saikyou-party-ni-shinuhodo-kitaerarete-muteki-ni-naru-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a86f44b-5a80-4918-8bf3-31b04f5320d0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5eacc3c-270c-4e27-8e41-5803cc17917c', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 1, '100190071', '12年遅れのスタート', '若者たちで賑わうEランク昇級試験会場に、30歳を過ぎてギルド事務員から冒険者に転職したリック･グラディアートルの姿があった。試験官や受験者たちから年齢や魔力量の少なさを馬鹿にされながらも、大陸最強のパーティ「オリハルコン･フィスト」による訓練を乗り越えてきたリックは次々と試験をクリアしていくが、同じ試験を受けていた「神童」フリードに逆恨みされ、その姉アンジェリカから決闘を申し込まれてしまう……。', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a86f44b-5a80-4918-8bf3-31b04f5320d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('219ed5a8-20cc-44fc-9e2c-ed3182139239', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 2, '100190551', '4242番のEランク昇級試験', '一次試験の結果発表を待つリックとリーネットのもとに、二次模擬戦試験官のひとりで「Fランク潰し」の異名を持つラスターが現れる。しつこくリーネットをナンパするラスターを制止したことで、リックは彼の恨みを買うことに。一方、模擬戦でリックを担当予定の試験官ローロットは、30歳を過ぎて冒険者を目指したリックに共感し激励に訪れる。模擬戦の直前、リックはフリードの企みによってラスターの手下に取り囲まれてしまう。', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5899b12-f5e5-46f7-9830-e01395372a28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1985491a-b06e-421b-87da-84291878490a', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 3, '100191458', '超一流エリート vs. Fランクのオッサン', '「オリハルコン･フィスト」の先輩たちが見守る中、リックは「Fランク潰し」ラスター･ディルムットが立ちはだかる模擬戦に挑む。17歳でAランク冒険者になった天才ラスターと、30歳から冒険者を目指した出遅れの新人リックの力の差は明らかだと思われたが、ラスターが冒険者になった理由を聞いたリックは、ラスターには絶対に負けないと宣言。戦いの中で、最強のパーティに鍛え上げられたリックの実力が明らかになる――', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94809149-6dde-49c3-8720-6112aed71d8c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b712d73-9664-4039-ba02-13fe4fa417b8', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 4, '100192509', 'オッサン、冒険者になる', '合格発表を待つ間、リックは『ヤマト伝説』に憧れた少年時代を思い出していた。英雄ヤマトも持っていたという固有スキルの因子が見つかり、冒険者になると宣言したリックだが、スキルが発現することは無く日々が過ぎていく。やがて夢を諦めてギルド職員として働き始めたリックは、冒険者となり経験を重ねていく友人に言いしれない想いを抱きながら見守っていた。そんな時、圧倒的な戦闘力を持つSランク冒険者リーネットと出会う。', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77eaf972-e4f6-4a1b-959c-669f1cf48055.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('975069d1-4bd0-4b03-8193-9f5fa4435a1c', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 5, '100193502', 'オッサン、最強パーティに死ぬほど鍛えられる', 'リックを鍛え上げた最強パーティ「オリハルコン･フィスト」に興味津々なローロットは、彼らが集う城に遊びに行きたいと願い出る。城を訪れ、規格外なパーティメンバーたちに翻弄されながらも次第に打ち解けたローロットに、パーティの目的を告げ、その鍵となる「六宝玉」の情報収集を依頼するブロストン。ローロットの情報をもとに北方の街を訪れたリックたちは、たまたま居合わせた新人冒険者レイと共にワイバーン討伐へ向かう。', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c725b080-1e24-4f27-93a6-eaff80fbb580.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0aada369-7b64-4df6-9374-4fae9b6b2a3a', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 6, '100194955', '拳王トーナメント闘技大会', '「六宝玉」を求め、闘技大会で賑わうヘラクトピアにやって来たリックたち。拳王トーナメントのチャンピオンベルトに「六宝玉」のひとつが嵌め込まれていることを知り、三連覇中のチャンピオン･ケルヴィンと交渉するも決裂。ベルトを手に入れるため、リックとブロストンはトーナメントへの参加を決める。出場資格を得るためのテストでリックの前に立ちはだかったのは、かつてEランク昇級試験で決闘したアンジェリカだった。', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19af392e-dd20-445e-a13e-8c03f93b2968.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90ed5354-78d9-49ad-96db-6122337a9aa8', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 7, '100195695', 'オッサン、歴代最速の予選突破', 'トーナメントの予選を勝ち上がるアンジェリカ。リックとブロストンも国中の闘技場で開かれる試合を非常識なスピードでこなして予選を突破し、ブロックリーグへと進む。そんな二人の異例の活躍を知ったチャンピオン･ケルヴィンは、不敵な笑みを浮かべるのであった。一方、リックは裏社会との関係を噂されるトーナメントのスポンサー･スネイプと出会う。アンジェリカと親しい仲だというスネイプの言葉を、アンジェリカは否定する。', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4403489-3201-4ce1-b415-16e9f017ae59.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48b29572-118c-4ddc-b7c5-d48cd2d73011', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 8, '100196287', '心のなかの天秤', '死が垣間見えるほど過酷なリックの修行から逃げ出してしまうアンジェリカ。その気持ちが痛いほどよくわかるリックは、かつて自らがブロストンから受けたある教えを伝える。その言葉で修行を再開したアンジェリカに、リーネットは「素手を剣にする」という技を伝授。修行に耐えきったアンジェリカは圧倒的な力でブロックリーグ最終戦に勝利し、予選突破を決める。16名が出揃い、いよいよ拳王トーナメントが始まる――', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d2cab7ec-2c51-4144-bf41-24ba58342685.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b45f2bb7-3dc7-420d-8a60-f47986054ca1', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 9, '100197458', '全てを持って生まれた完璧な天才', '厳しい修行の末、リーネットから習得した身体操作の奥義「糸斬り」でギースに一矢報いたアンジェリカ。そのまま優勢かと見えたが、ギースの拳闘士としての才能はアンジェリカの現時点の実力を遥かに上回っていた。戦闘不能のアンジェリカを一方的になぶるギースに、リックの怒りが頂点に達する。準決勝のカードはリックvs.ギース。アンジェリカに「お前の修行のその先を見せてやる」と告げて、リックは闘技場へと向かう。', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0984ca8c-24cf-45de-83fc-b913dbf956f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5a6d7fd-bf5b-4feb-9cf9-a11ab71356c0', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 10, '100198442', '史上最強の拳闘士', '準決勝第二試合は、三連覇中のチャンピオン･ケルヴィンvs.ブロストン。ケルヴィンはブロストンを人生最強の相手と称えるが、ブロストンからは「お前の拳には迷いが見える」と指摘されてしまう。翌日に試合を控え街外れで練習に励むケルヴィンは、偶然通りかかったリックに強引に手合わせを申し込み、その実力を認めると全力で戦えない理由を語り始める。絶対王者と呼ばれる彼は、強さと引き換えにある苦悩を抱えていた。', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d070c0d-35a7-4060-8962-d162d157695b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('669a859b-b1ee-4593-8e77-82ea54a6f080', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 11, '100199223', '対等な殴り合い', 'ブロストンが決勝の対戦相手に決まり、あまりの恐怖から部屋に立て籠ってしまうリック。あの手この手で出場するよう説得する一同のなか、ミゼットはブロストンが内に秘めた願い、リックをここまで鍛えてきた理由を語りだす。アリスレートやアンジェリカの励ましも受けてブロストンに立ち向かうことを決意したリックに、試合直前、リーネットが掛けた言葉とは――。拳王トーナメント決勝戦、S級同士の師弟対決が始まる!!', '2025/01/02 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9620bdaf-f5bf-4aae-a356-88f24c324eca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c39221c-c7ff-4d70-8c95-8c2a5eae3ad0', '6806cdb7-e569-431d-89b8-46830ce4fc2c', 12, '100200043', 'クオーター･サムズアップ', '【シーズン1 最終話】拳王トーナメント決勝戦の最中、ブロストンは自らの孤独な生い立ちと「オリハルコン･フィスト」創設の経緯、そして対等な実力者と殴り合いをしたいという夢をリックに語り始める。リックは冒険者になるという夢のために付きっきりで修業をつけてくれたブロストンの想いに応えることを決意し、二人の戦いは防御と回避を捨てた純粋な殴り合いに突入。魔力も体力も尽きたその時、ついにリックの固有スキル「蛮勇覚醒」が発動する――', '2025/01/02 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14820a1a-3340-4dfd-b515-e82051218c77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f4592b69-c9f7-4bf9-b3ac-a2bbe8e978c5', '新米錬金術師の店舗経営', '', 'hulu', 'management-of-a-novice-alchemist', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f26313f8-c2a2-484b-bf0f-80a05a38d97e.jpg?w=331&h=447&p=t', 'hulu', 2022, 3, 1, 'FINISHED', NULL, 139369, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('dcb2fabc-dc76-42df-a836-43aee97289be', 'f4592b69-c9f7-4bf9-b3ac-a2bbe8e978c5', 'hulu-management-of-a-novice-alchemist-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9bc87b0-3465-42ba-af47-d5329622ec43.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6d24ceb-3748-4470-89fb-1db295f27902', 'dcb2fabc-dc76-42df-a836-43aee97289be', 1, '100125665', 'お店を手に入れた!', '錬金術師養成学校に通うサラサは卒業試験の日を迎えていた。亡くした両親の様にお店を持ちたいと願い猛勉強した5年間。その努力がついに実を結ぶ――はずが、試験中にトラブル発生。不合格ならば錬金術師になれない! どうするサラサ!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9bc87b0-3465-42ba-af47-d5329622ec43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f3ca55d-2506-47d3-b988-b8abe658e9fb', 'dcb2fabc-dc76-42df-a836-43aee97289be', 2, '100125994', '村にやってきた!', 'サラサは住み慣れた王都を離れ、店舗があるヨック村にやってきた。雑貨店の娘ロレアやお隣さんのエルズに住人を紹介してもらうが、慣れないコミュニケーションに四苦八苦し落ち込んでしまう。サラサは本当に店舗経営できるのか!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f05009e-26f8-4942-8c2b-2052ff9bdcc8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f09de72e-6ed0-427a-8ff7-7fbcfb423e55', 'dcb2fabc-dc76-42df-a836-43aee97289be', 3, '100127076', '魔物が出た!', 'ついにお店を開店させたサラサ。しかしお客様第一号は魔物に襲われて大怪我を負った採集者アイリスと相棒のケイトだった。経緯を聞いたサラサは、魔物が暴走状態にありヨック村も襲われると推測。初日から店舗経営どころではなくなった!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/def248b3-e5d1-4819-8687-d2dcef98a4a8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cd8599f-c421-4d6a-9aab-0c5c57e77cd1', 'dcb2fabc-dc76-42df-a836-43aee97289be', 4, '100127864', '一緒に暮らそう!', '村を救ったサラサに、お店の手伝いを申し出るアイリスとケイト。治療費の返済も残る2人にサラサは共同生活を提案する。店番のロレアを入れた4人で賑やかになるサラサのお店。一方、素材の換金や分配のためにサラサは隣町へ向かうが……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7b517c6-4e64-412f-ab29-79bbf470c79c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40698d00-542c-49ae-afcc-b24485f19ee0', 'dcb2fabc-dc76-42df-a836-43aee97289be', 5, '100128360', '新商品を開発しよう!', 'ロレアのため、台所に冷蔵庫を置く話がもちあがる。冷却素材を持つ『氷牙コウモリ』を狩りに、アイリスとケイト、アンドレたちと共に洞窟へ向かうサラサ。しかし同行者たちは知らなかった。洞窟には大ダメージを与える罠があることを……', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa2d1f46-ea60-4394-8777-e645376dc28b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80c3bef6-516a-494d-8264-fa7bc46c491b', 'dcb2fabc-dc76-42df-a836-43aee97289be', 6, '100128742', '湖に出掛けよう!', '特産品になった『冷却帽子』のおかげで村全体も少しずつ潤って来た。そんなある日、レア素材を持つ魔物の情報を仕入れてくるアイリスとケイト。料理してもおいしいらしくロレアも同行したいと言う。こうして湖に出掛ける4人だったが……', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/636ab62e-ca53-4f07-ab80-afb15d221e13.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f333722a-b5da-47aa-b538-39ef6498ec87', 'dcb2fabc-dc76-42df-a836-43aee97289be', 7, '100129355', '錬成具 (アーティファクト) が壊れた!', 'サラサのペンダントは、魔力制御のためにオフィーリアからもらったものだった。修理に必要な素材を手に入れようにもなぜか転送陣が故障。サラサは魔力の制御が難しい状態での店舗経営を余儀なくされる。案の定その日から失敗続きで……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52085645-f132-4ef1-b774-022645b9f25d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b23b05e2-a6a2-4270-bdeb-481045f82d83', 'dcb2fabc-dc76-42df-a836-43aee97289be', 8, '100130091', '商売敵が現れた!', '一人の商人が村にやってくる。サラサの店より高価買取を始めたその男に採集者たちが流れていく中、サラサはある噂を耳にする。その商人は盗賊と組んで何かを企んでいるらしい。盗賊に両親を殺された過去を持つサラサは勝負を挑むことに!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62ac7d5e-50a3-4d88-95aa-7c5d4c0175c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b270182-c6e8-402c-9681-1f99d0104a42', 'dcb2fabc-dc76-42df-a836-43aee97289be', 9, '100130765', '蜂蜜を採りに行こう!', '冷却帽子の売り上げも落ちて来た。借金返済だけでなく、お店のためにもなる素材を採りたいというアイリスとケイトに、サラサは腐果蜂の蜂蜜を薦める。アイリスたちが巣を見つけると、そこには金色の蜜。それが、悲劇のはじまりだった――。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbc32997-35d4-4d57-a950-0267740687a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('edc35e05-b19f-43ea-ad72-96d8d8c8d06f', 'dcb2fabc-dc76-42df-a836-43aee97289be', 10, '100131462', 'お金で解決しよう!', '突然訪問してきたアイリスの父とケイトの母。その目的は、とある商人との結婚のためにアイリスを連れ戻すことだった。しかし縁談に裏があるのではとサラサは疑いを持つ。一方、村長の娘エリンからは、以前村を襲った魔物の調査の依頼が!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17a5bdc9-8700-420b-9e0c-0078d2385a63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('415f045a-8cd9-4730-88cb-80caa9d257f0', 'dcb2fabc-dc76-42df-a836-43aee97289be', 11, '100131930', 'サラマンダーを倒そう!', '火山を訪れたサラサたちは巨大なサラマンダーを目撃。一度は逃げ帰るものの、このサラマンダーこそ村に起こる地震や転送陣故障の原因であり、アイリスの家の借金問題を解決する鍵だと考えるサラサ。装備を整えて仲間たちと討伐に赴く!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a683d47c-4916-4bc2-b6f4-40df13c3b60f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d707a09-8584-4678-8da1-a1fc83a97a14', 'dcb2fabc-dc76-42df-a836-43aee97289be', 12, '100132549', '新米錬金術師の店舗経営', '【シーズン1 最終話】目先の不安もなくなり、店舗経営も波に乗ってきたある日、サラサに一通の手紙が届く。それは亡くした両親が営んでいた商会からのものだった。『王都に戻って両親のお店を継いでほしい』という内容に動揺するサラサ。サラサの選んだ答えとは――。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/243aa4b4-6bd5-4a3a-9bfd-1f185b7dee3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('89e35498-0a41-4c02-9895-4f5b6eaedd28', '真・一騎当千', '', 'hulu', 'shin-ikki-tousen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8901dff6-ac13-4bf8-8532-69ef24c17e29.jpg?w=331&h=447&p=t', 'hulu', 2022, 1, 1, 'FINISHED', NULL, 136303, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('51902381-d72f-499d-887d-a1832b283727', '89e35498-0a41-4c02-9895-4f5b6eaedd28', 'hulu-shin-ikki-tousen-s1', '5期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d194358-c68f-4088-9a66-4c66031293e3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9b774db-dd7d-4f45-b001-a3ce27fae0d3', '51902381-d72f-499d-887d-a1832b283727', 1, '100121020', '帰還', '関西の覇者･卑弥呼に奪われた勾玉を取り戻すため関東の名だたる闘士が遠征で不在の中、孫権仲謀が南陽に転校して来る。しかし、孫策の妹である孫権は、姉以上の“ヘタレ”だった。そんな南陽の隙を突き、関西の刺客･山田朝右衛門と因達羅が校庭内に現れる。宝刀･百辟刀を守り抜きたい一心でなけなしの勇気をふり絞る孫権に脅威が迫った時、ついに龍が覚醒する。', '2025/12/26 00:00:00', 1591, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d194358-c68f-4088-9a66-4c66031293e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf4ac640-d02d-4d67-8f6d-2ab73236702e', '51902381-d72f-499d-887d-a1832b283727', 2, '100121021', '徐福院', '覚醒により昏睡した孫権を救うには、失った水龍の氣を補充するしかない。そこで孫策が向かったのは、伝説の修験の地･徐福院。しかし、そこはすでに霊界の扉が開き、死者が溢れ出す“地獄”と化していた。勾玉もなく、闘士としての自信を失いかけていた孫策の前に現れたのは、美しき旋律を愛する剣士･佐々木巌流と、霊界の門番を務める多聞丸だった。', '2025/12/26 00:00:00', 1600, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e6026fe-8860-4c4f-9f68-902014fce9da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1e5e603-0fe6-4853-b094-94f4c3f3eb05', '51902381-d72f-499d-887d-a1832b283727', 3, '100121022', '旋律', '【最終話】呂蒙は徐福院の地下に広がる不思議な空間で目を覚ます。そこは、この世と霊界の狭間にある黄泉比良坂。蘇った亡霊･呂布との悲しみの対決を乗り越えた呂蒙だったが、その時、ついに霊界から亡者の群れが一斉に溢れ出す。佐々木巌流と多聞丸の二人と手を組んだ呂蒙は、生きて外の世界に戻るため、大地を埋め尽くすほどの亡者の群れに立ち向かう。', '2025/12/26 00:00:00', 1564, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b2c8e87-3b9b-491f-afd9-d3b53be72362.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('130aac87-efa0-4021-8413-e37c2e2fe061', '真・中華一番！', '', 'hulu', 'cookingmaster', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa16c2b4-49ed-4233-b71b-71081d091536.jpg?w=331&h=447&p=t', 'hulu', 2019, 3, 1, 'FINISHED', NULL, 107666, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('570d8be4-496e-464f-8f04-7fe52561595b', '130aac87-efa0-4021-8413-e37c2e2fe061', 'hulu-cookingmaster-s1', '第一期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e2e1cf5-1f56-4e4f-b741-196c6d195711.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5552655c-903d-41bd-933f-a8edc7976a55', '570d8be4-496e-464f-8f04-7fe52561595b', 1, '100043648', '夢を継ぐ者', '劉 昴星 (リュウ･マオシン) は料理修業を終え、メイリィ、シロウとともに広州にもどろうとしていた。その旅の途中、養鶏で栄える町にやって来た3人は、空腹のところを、鶏料理屋の娘ティアに助けられる。そこで真っ黒な鶏を見かけ、“兄貴を殺した不幸な鶏”だとティアに告げられる。その鶏を見たマオはある決意をする。', '2019/10/15 12:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e2e1cf5-1f56-4e4f-b741-196c6d195711.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0891a2b0-c71c-40cd-9e57-e492a4bc47e5', '570d8be4-496e-464f-8f04-7fe52561595b', 2, '100043894', '特級面点師', '再び「陽泉酒家」に戻ったマオたち。そんなある日、シロウが勝手に客に料理を提供したため、客が怒り、マオはその客の希望の料理を提供することに。その課題は三種類の卵を使った料理だった。マオは課題に沿った焼売を提供する。その料理に感動した客は意外な行動に出る。その客とは特級面点師のシェルであり、シェルはさらに料理対決を熱望するが…。', '2019/10/22 12:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a2c794e-2556-49f2-b36a-e89fa6261888.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0089839-2356-4a09-be22-09b06ca7de2b', '570d8be4-496e-464f-8f04-7fe52561595b', 3, '100044048', '奇妙な招待状', 'チョウユ、メイリィとマオ宛てに“絶対服従”のサインがある奇妙な招待状が届いた。三人は招待を受け、異人館で行われる夕食会に出席する。そこでメイン料理として出された「ハト料理」を食べた後、メイリィの体に異変が起こる。マオとチョウユの前に、突然仮面を付けた料理人が現れ、チョウユに復讐する、と料理勝負を申し出た!', '2019/10/29 12:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f42b719d-087a-4670-8ffd-c4cdf6a28686.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eac90138-ea18-4171-9c29-33221ceaabfd', '570d8be4-496e-464f-8f04-7fe52561595b', 4, '100044264', '怨念の鍋', '仕込まれたサソリの毒で対戦不能となったチョウユの代わりに、マオは仮面料理人と対決する。対戦成績は一勝一敗。最終決戦となる第三勝負の課題は「イセエビの鍋料理」。仮面料理人は16年前におきたチョウユとの因縁の理由をマオに述べ、その思いが詰まった秘策を使い、マオに挑んでくる。そして、完成した料理を審査するのは意外な人物だった…。', '2019/11/05 12:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd9bd106-3403-4da7-ab91-587d86c43622.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f2ef858-96ef-4062-b2a6-5c4901833d9d', '570d8be4-496e-464f-8f04-7fe52561595b', 5, '100044745', '裏料理界の野望', '手に黒い麒麟の紋章がある男に鋼棍を奪われたシェルは、マオ達に“裏料理界”への用心を呼びかける。一方、四年前に陽泉酒家にいた若き天才料理人レオンが料理修業から帰ってくることを楽しみにしているメイリィ。だが、戻ってきたレオンは変貌してしまっていた。そして、レオンはルオウ大師に「伝説の厨具」をもらい受けにきたと告げる。その手には黒い麒麟の紋章があり、マオたちは動揺する…。', '2019/11/12 12:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ceb1523-e16c-490b-ab7a-db9103fd6176.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1385c6d5-bcc6-4c5b-b867-0716bc42cc24', '570d8be4-496e-464f-8f04-7fe52561595b', 6, '100045167', '七番目の包丁', 'マオとレオンによる「伝説の厨具」の真の継承者を決める“神前刀工勝負”が始まる。食材は鯛! レオンの「七星刀」に対し、マオは「鋼糸包丁」とシェルが作った「百穴包丁」で対抗する。二人の対決は拮抗し、延長戦までもつれ込む。最後の切り札を出し切って戦う二人…勝負の行方は…。', '2019/11/19 12:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a48587c2-22da-46e8-b715-4817db318de6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aaadb95d-0325-4dfc-a580-641947709212', '570d8be4-496e-464f-8f04-7fe52561595b', 7, '100045669', '二人の継承者', 'マオとレオンの“神前刀工勝負”はついに決着する! マオが伝説の厨具「永霊刀」を手にすると継承者としての証である龍の紋章が浮かびあがった。そしてその神秘の力を体験したマオは、継承者はもう一人いると言うのであった…。', '2019/11/26 12:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45b6028b-5eeb-4642-a24d-23e3a6a7c140.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a42cd826-e1bb-40e8-9b33-0684bafdc937', '570d8be4-496e-464f-8f04-7fe52561595b', 8, '100046332', '伝説の八厨具', '“裏料理界”と戦う決意と技量を認めたマオに、ルオウとチョウユは「伝説の厨具」の秘密を明かす。そしてシェルとレオンと共に、マオは「伝説の厨具」を探す旅に出発する。メイリィ、シロウを加え、五人は次の「伝説の厨具」が封印されている地、上海に向かうのであった。旅の途中、マオは特級厨師になるまでの話をシェルやレオンに語り始める…。', '2019/12/03 12:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b57952f-591b-4bce-8e6d-78ac5c43f4b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ff26667-7066-420c-848e-e4eaa4ded686', '570d8be4-496e-464f-8f04-7fe52561595b', 9, '100046962', '魔都 上海', 'マオたちは魔都･上海に上陸。彼らを歓迎したのは、マオの兄弟子だったサンチェだった。だが、“裏料理界”の手は既に「上海厨師大連合会」に及び、サンチェの父親を含む大連合幹部達が人質に取られていた。そしてついに、上海にあるといわれる伝説の厨具をかけた“裏料理界”との闘いが始まる!', '2019/12/10 12:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51290079-6461-46ef-a453-b058fd29176d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9fdbbb2-2485-41c4-abcd-2a9d641b54cc', '570d8be4-496e-464f-8f04-7fe52561595b', 10, '100047368', '超点心大激突!', '“黄浦江楼麟艦 宴席料理決戦”がはじまる。第一試合は“特級面点師･鋼棍のシェル”VS“面点キング･ラコン”の「世紀の饅頭対決」! 饅頭の“王道”を極めたラコンが作った中国点心史上最高の傑作に対し、シェルは大胆な発想の料理を突き通そうとする。果たしてその勝負の結果は?', '2019/12/17 12:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2074875a-7544-4c48-8375-db3d8915b324.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a9153c6-6295-4108-88f9-e13e00e590d1', '570d8be4-496e-464f-8f04-7fe52561595b', 11, '100047676', '激突! 二つの『七星刀』', '“黄浦江楼麟艦 宴席料理決戦”第2試合は、“七星刀のレオン”VS“一丈青のシャン”。シャンは脱ぎ捨てられたマントの下に、レオンと同じ「七星刀」をもっていたのであった。動揺したレオンは“裏料理界”での過去について語り始めるが…。', '2019/12/24 12:00:00', 1453, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01c4b126-7901-4296-8bb0-57f884ef0882.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5e5b9f6-52cd-42d8-9423-d93e081aae10', '570d8be4-496e-464f-8f04-7fe52561595b', 12, '100048183', '運命の男', '「七星刀」でひとつでも多くの幸せを紡ぐことを誓ったレオン。究極のカニ料理を完成させるが、審査員たちから“まずい”と言われる。シャンの策略を見抜くマオに対して、シャンは二つ目の「七星刀」の真実を告げる。そして、第三試合を迎えたマオの対戦相手は因縁の相手であった!', '2019/12/31 12:00:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbc833db-65a6-4e69-93c6-4aac022023ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('753be555-0c35-478c-b5cb-05824654a182', '130aac87-efa0-4021-8413-e37c2e2fe061', 'hulu-cookingmaster-s2', '第二期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f192f9d-cba5-452e-8fa6-d2c5c7efb5f9.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d034a5f8-c5b4-42f1-ae84-73740587351a', '753be555-0c35-478c-b5cb-05824654a182', 13, '100072877', '超絶豆腐勝負!', 'マオ一行と裏料理界が伝説の厨具を賭けた“黄浦江楼麟艦 宴席料理決戦”は、互いに一勝一敗。最終決戦はマオと因縁深いショウアン。テーマは豆腐! しかし、決戦前夜にマオが準備していた大豆に異変が…。不意の災いの中から福に転じるヒントを得たマオが出した料理とは!?', '2021/01/12 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f192f9d-cba5-452e-8fa6-d2c5c7efb5f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('511c05fc-0863-4d3d-b398-07fd0a9e0bbf', '753be555-0c35-478c-b5cb-05824654a182', 14, '100073258', '差し伸べられた手', 'マオの「大魔術熊猫 (マジカルパンダ) 豆腐」に対して、ショウアンが出したのは「豆腐の三重奏」。いずれも豆腐料理の限界に挑んだ大秀作だが、判定はいかに!? 壮烈なる“黄浦江楼麟艦 宴席料理決戦”の勝敗はこの長江四千里の終着点、上海で決着がつく!', '2021/01/19 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0113b54-73c9-42b2-950e-dcca6e33e3f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4724606-95b9-40f6-8107-62f89a948eda', '753be555-0c35-478c-b5cb-05824654a182', 15, '100073762', '魔神降臨', '第二の厨具「転龍壺」を龍鎮酒家に預けたマオ、メイリィとシロウはサンチェと別れ、次の厨具のありか九華山に向かう。しかしマオ達が目にしたのは倦怠する村民達。彼らを支配していたのは謎の“アワビ魔神”だった。', '2021/01/26 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb82ec34-dd90-4202-a700-adc3ef4da5ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7fe1d225-c0c4-4792-b93d-932b9c99d64c', '753be555-0c35-478c-b5cb-05824654a182', 16, '100074063', '爆炎の河', '第三の厨具「魔聖銅器」を手に入れたマオ一行は第四の厨具のありか四川に向かうために、長江を渡る。マオの存在を警戒し、裏料理界最強幹部の五虎星が動き出す。その先陣を切ったのは「爆炎厨師」の異名をもつ“豹子頭”アルカン。マオvsアルカン、長江火工勝負の火ぶたが切って落とされる!', '2021/02/02 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/202df9cc-6eae-4ce8-b67a-7922aa6cdae9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37141731-cc46-4ea0-8027-6af2abcd89f8', '753be555-0c35-478c-b5cb-05824654a182', 17, '100074669', '長江の果てに', 'チョウユ師傅より直伝された火工の神髄を見せるマオの二品に対して、アルカンは更なる火工のスケールを見せ、長江を火の海と化して、究極の焼き魚で対抗する。マオの二品とアルカンの一品。審査員シェルの心の天秤が揺れ、判定はどうなる!? 一方、勝負の裏にシャンが再び現れ…。', '2021/02/09 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62c7a610-5aa2-4265-91d9-fbca2bdb1ae3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8507b040-5f76-4609-8be4-f622cf8453cc', '753be555-0c35-478c-b5cb-05824654a182', 18, '100075455', '菊下楼の異変', 'シャンの乱入により、シェル&レオンと二手に分断されたマオ、メイリィとシロウ。マオたちはマオの生家「菊下楼」を目指すことに。休業中のはずだった「菊下楼」は何故か営業しており、厨房で料理を振舞っていたのはジュチと名乗る少年だった。さらにジュチはメイリィに猛アタックする。マオの心は大きく揺れる…。', '2021/02/16 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/458d31e9-4618-4ad6-bebf-61d30901d8c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6e91fae-1cab-4217-8738-c94b79ba777b', '753be555-0c35-478c-b5cb-05824654a182', 19, '100075886', '鴨子 (アヒル) にたくされた想い', '親王様の料理番を賭けて、マオvsジュチの鴨子 (アヒル) 料理勝負が開始。勝負の判定役をメイリィが申し出る! マオはメイリィの故郷･広州の“香り”に気持ちを託した料理を出す。再び二人の心は一つになると思った瞬間、メイリィが突然倒れた! ジュチに「料理人、失格だ!」と言われて、窮地に追い込まれるマオ。そんなマオの前に現れたのは…。', '2021/02/23 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2317300d-7853-4c5a-b027-d85e9c12f5aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f6bd637-e4c3-4889-994b-a201fd408390', '753be555-0c35-478c-b5cb-05824654a182', 20, '100076368', '不死鳥のごとく', 'マオに正体を見破られたジュチ。“龍厨師”として、フェイはマオとジュチの再勝負を提案する。“本当の力”を発揮するマオはアヒルを不死鳥と化し、“不滅の味”を呈する。一方、ジュチは大鉄板の上にいつものように料理“パフォーマンス”を極める。果たして勝負の行方は? またジュチの秘密とは一体!?', '2021/03/02 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e946e171-9419-417c-a018-6c7f3edb21f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4f7ac89-ac84-4f8e-bc6f-56d0caef1028', '753be555-0c35-478c-b5cb-05824654a182', 21, '100076859', '眩惑の敦煌', 'マオ達とは別行動していたシェルとレオンは敦煌へ。シェルは砂漠で倒れた自分を救った褐色の美女に惚れてしまう。だが、彼女の正体は五虎星の“青眼のミラ”だった! 伝説の八厨具の地図を賭けた“敦煌式料理勝負”をすることになったシェル、ミラの超人的な能力を破る術はあるのか!?', '2021/03/09 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e35b271-2868-4c14-9b95-fddf145152b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f2317d7-0985-44b6-b6a2-9ae59131f5d8', '753be555-0c35-478c-b5cb-05824654a182', 22, '100077679', '砂漠の太陽', 'レオンはミラの完全コピー能力に対して、驚くべき料理方法で対抗する。さらに料理場に五虎星の中でも「底の知れぬ男」“浪子”エンセイが現れる。一方、マオ達は裏料理界総本山･梁山泊に向かい、ついに五虎星の筆頭“入雲龍”カイユと対峙するのであった。', '2021/03/16 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c89f602-5780-4820-a050-0cce932b289a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('752b5e6c-d58c-4a89-8e77-a988c7881aba', '753be555-0c35-478c-b5cb-05824654a182', 23, '100077986', '無限の英雄', '裏料理界に最終決戦を挑むマオ。再びアルカンが立ちはだかり、料理対決を行うことに。課題は、料理で「大陸の英雄」を表現すること。全力を出すアルカンに対して彼の能力を解明するマオ。そして、ついに勝敗を決するとき、アルカンとマオがそれぞれ料理で出した答えとは…。', '2021/03/23 02:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b47c7c00-b9f4-42fd-afaf-c94063e769e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cb39080-d1e0-4637-b517-b5c1ce7293fb', '753be555-0c35-478c-b5cb-05824654a182', 24, '100078428', '時代を創る者たち', 'アルカンに勝利したマオは「料理は人を幸せにする」という強い信念を伝え、裏料理界の厨師達の心をも震わせた。それを危険視したカイユは仲間が大勢いる梁山泊を破壊する。激流に飲まれるマオ、足枷が外れないまま水位はさらに上がっていく…。', '2021/03/30 02:00:00', 1411, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f905e259-5117-4180-b6e2-b2c888ef11f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('83df0c09-fb52-412b-afe5-a0a7b8a955d5', '真･侍伝 YAIBA', '', 'hulu', 'shin-samurai-den-yaiba', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6b42cd6-a649-48f9-946e-91aca1f61f6c.jpg?w=331&h=447&p=t', 'hulu', 2025, 1, 1, 'FINISHED', NULL, 177476, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('919ad3c3-869a-4897-9042-160fe5335704', '83df0c09-fb52-412b-afe5-a0a7b8a955d5', 'hulu-shin-samurai-den-yaiba-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0a3519b-d6c0-4c12-a6a8-7c74a03e5257.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('306880fc-91b2-4c0f-8267-40a78a894268', '919ad3c3-869a-4897-9042-160fe5335704', 1, '100223479', 'YAIBA見参', '鉄 刃は真のサムライを目指し、父である剣十郎たちと共にジャングルで日々修行に励んでいた。ひょんなことから剣十郎とジャングルで出会ったトラ･カゲトラと日本に戻り、父の友人である峰家に居候することに。峰家の娘･さやかは破天荒な刃に戸惑いながらも暮らし始める。ある日、さやかと共に彼女の通う学校に訪れた刃は、剣道の実力者である、鬼丸 猛と運命的な出会いを果たす。', '2025/04/08 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0a3519b-d6c0-4c12-a6a8-7c74a03e5257.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f96185f-cafc-41cd-aa26-746cf359da80', '919ad3c3-869a-4897-9042-160fe5335704', 2, '100223857', '蘇る風神剣', '鬼丸と勝負するため、どうにかして気を引こうとする刃。全く相手にしない鬼丸だったが、ジャングルから刃を追いかけてきたハゲタカ･庄之助に、大事にしていた鳩小屋を荒らされたことによって、ついに喧嘩が勃発する。刃のでたらめな剣により屈辱を受けた鬼丸は、悔しさの勢い余って自宅の灯篭を破壊してしまう。すると偶然にも、地下室へ繋がる階段と、魔剣･風神剣を見付けるのだった。', '2025/04/15 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab6e850d-bd0f-46f6-97c4-d339b4e384ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62e621da-1baf-45bd-9424-0d7acdbf1b09', '919ad3c3-869a-4897-9042-160fe5335704', 3, '100224498', 'もう一つの魔剣', '刃の元に、今度は鬼丸が勝負を挑んできた。ツノが生え、普段と様子の異なる鬼丸に違和感を覚えるも、戦いに奮い立つ刃。しかし、風神剣を手に入れた鬼丸の力に圧倒され、己の弱さを自覚する。鬼丸に対抗するには、もう一つの魔剣である雷神剣が必要であることを、父･剣十郎から聞かされる。雷神剣を手に入れるため、現在の所有者であり400年前から生きているという剣豪･宮本武蔵に会いに天狗岳へと向かうのだった。', '2025/04/22 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ea030c4-d0ed-4408-9f43-808c115da8ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bdb8dc49-6fc7-4d79-b4a9-f6dd7267e7b3', '919ad3c3-869a-4897-9042-160fe5335704', 4, '100225453', '八鬼襲撃', '雷神剣を手に入れたものの、雷神の力に呑みこまれ、暴走してしまった刃。剣を自在に操れるようになるために、武蔵から修行を受ける。一方、鬼と化した鬼丸は儀式によって八鬼を生み出す。さらに国会議事堂を襲撃して日本を乗っ取ってしまう。そして、刃が持つ雷神剣も狙う鬼丸は、八鬼のカエル男とヘビ男を刃の元へ差し向けるのだった。', '2025/04/29 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11c8fcb0-dcba-444f-ab58-be7aa103538c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97bf1919-bb42-4586-98e9-04299b75e07f', '919ad3c3-869a-4897-9042-160fe5335704', 5, '100225995', 'るんるん温泉旅館', '武蔵の因縁の相手であり、古の剣豪･佐々木小次郎が持っていた魔剣･物干し竿を調べるため、巌流島を目指す刃たち。しかし道中、鬼丸の手下･八鬼の内の一鬼である、かたつむり男に襲われ疲労困憊。そんな中、立ち寄ったのは下呂温泉。怪しい番頭から百万人目の通行人だと持て囃され、よく分からないまま温泉旅館に招待されることに。温泉を楽しむ刃たちだったが、雷神剣を狙う新たな魔の手が忍び寄る…?', '2025/05/06 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7678cf0a-9677-48c8-b9e0-f2e0b8584efb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64ead276-8e15-4f74-925b-21de4c689ff0', '919ad3c3-869a-4897-9042-160fe5335704', 6, '100226704', 'いきなりバットガイ', 'ナマコ男が加わり、再び巌流島へと目指す刃たち。その道中で名古屋を訪れた一行は、のん気に味噌串カツを堪能していた。その時、何者かの声が聞こえてくる。次の瞬間、さやかの串カツが無くなっていた。突如現れたバットガイと名乗る男に雷神剣を狙われる刃は、あまりの強さに防戦一方。すかさず助けに入った武蔵だったが、バットガイに首筋を噛まれてしまう。すると、武蔵の体に異変が起こる。', '2025/05/13 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e1d6423-2a23-490a-98a8-6d7eb019f72c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5403970f-bb30-4b85-a23f-3f5ff4206ce2', '919ad3c3-869a-4897-9042-160fe5335704', 7, '100227195', '小次郎復活', 'ついに巌流島に到着した刃たち。一方、鬼丸の命令によって先回りしていたクモ男によって、佐々木小次郎が復活させられていた。しかし、急に復活させられたため、状況を飲み込めない様子。老いた武蔵のことも始めは認識できないようだったが、武蔵が挑発したことにより戦いが始まる。ところが、黄泉の国から舞い戻った400年前と変わらぬ姿の小次郎に武蔵は追い詰められてしまい、助けに入った刃もピンチになってしまう。', '2025/05/20 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82f9f1d9-8436-438b-a43a-bc15fc1ae296.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5791d54-011a-4ebf-97c9-69255d2adc1c', '919ad3c3-869a-4897-9042-160fe5335704', 8, '100227839', '巌流島の戦い', '佐々木小次郎の必殺剣「つばめ返し」により、危うくやられる寸前の刃だったが、クモ男が開けた時空の穴に吸い込まれてしまい、気が付くとそこは400年前の世界。元の世界に戻るためには、武蔵が歴史通り、巌流島の戦いで小次郎に勝つ必要があった。しかし、刃の余計な一言により、武蔵の戦略が崩れ、歴史が変わろうとしていた…!?', '2025/05/27 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0f122f7-8c55-4584-a614-fff623434fcd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a15a9a1b-bbfb-413d-b185-700fda27d74e', '919ad3c3-869a-4897-9042-160fe5335704', 9, '100228318', 'かみなり斬り誕生', '武蔵の修行の成果によって、暴走せず雷神剣を操れるようになった刃。しかし今の刃では剣の力を扱うだけで、相当な気力と体力を消耗してしまっていた。そこで巌流島から峰家に帰ってきた刃たちは、何故だか家に居る小次郎や武蔵とともに、鬼丸に対抗できる新たな必殺剣を編み出すべく、さらに修行をするのだった。', '2025/06/03 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6a39e55-7498-40da-9a1c-5589003d69ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43916120-d88e-4b57-b716-6cce9a6cb7b9', '919ad3c3-869a-4897-9042-160fe5335704', 10, '100229061', '鬼丸四天王登場', '修行の末、新たな必殺剣「かみなり斬り」を習得した刃は、ついに鬼丸城へ攻め入る。城を守る黒鬼たちを薙ぎ払い突き進む刃だったが、鬼丸を目前にしてクモ男の策略により、刃たち一行は城の底へとバラバラに落とされてしまう。そこで待ち受けていたのは、城の中とは思えない景色と、鬼丸が用意した新たな手下、鬼丸四天王たちであった。', '2025/06/10 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5f4401d-8a93-4142-a650-7da8f786e52c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('074e831e-bd15-4c06-bcf1-384f5a7f0b11', '919ad3c3-869a-4897-9042-160fe5335704', 11, '100229514', '雷神剣 VS 風神剣', '鬼丸四天王を倒し、余裕を見せる刃。しかし、すでにその背後には、鬼丸が待ち構えていた。鬼丸は冷静に刃を日本征服の同志に誘うが、刃は自分は正義の味方であると主張する。力を手に入れる前から衝突を繰り返し、相容れることのない二人の運命は変わらない。さやかから雷神の玉を受け取った刃は、本来の雷神剣の力を開放する。古来より続く雷神剣と風神剣の戦いが、ついに始まるのだった――', '2025/06/17 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfbb6bd7-e56c-4fc4-b930-00d1c4223df5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23390053-99a0-478a-95df-ad762fbc7589', '919ad3c3-869a-4897-9042-160fe5335704', 12, '100230454', '大和撫子がやってきた', '決戦は、刃は雷神の玉を奪われ、鬼丸は風神剣を折るという痛み分けの結果となった。鬼丸軍団は消息不明となり、日本には束の間の平和が訪れていた。そんな中、近所で女性の「道場破り」が話題になっていた。いつも通り武蔵と修行をしていた刃は、さやかに買い物を頼まれ出掛けて行く。そして刃が留守の間に、噂の道場破りが峰道場へ来てしまう。彼女は、自分が刃の許嫁だと名乗っていて…!?', '2025/06/24 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b6c7415-16ff-457a-a6dc-4eb6b77f3d3a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('384309f1-d724-4aeb-b569-438734cf4f7a', '919ad3c3-869a-4897-9042-160fe5335704', 13, '100231374', '龍神の玉を探せ', '雷神の玉を鬼丸に奪われてしまった刃だが、空を飛べるという「龍神の玉」の存在を知り、手に入れるため、再び旅に出ることに。撫子の持つ古い地図によると、いくつか玉のありかは書いてあるものの、どれが龍神の玉なのかは分からないようだ。まずは刃一行は、地図が示している琵琶湖に向かうことに。一方、鬼丸は刃たちが龍神の玉を求めていることを知り、古の剣士剣豪の魂を使って新たな刺客を生み出し、刃たちの元へ差し向ける。', '2025/07/01 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e512114e-a10c-4611-ac72-2c3541a403ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8526de32-cbe4-4ae2-bb00-9126795802ba', '919ad3c3-869a-4897-9042-160fe5335704', 14, '100232489', '忍者小太郎現る!', '琵琶湖にあったのは龍神の玉ではなく、「水の玉」だった。どうやら龍神の玉の他にも伝説の玉があるようだ。次なる玉のありかを目指し、向かうは四国。剣山にはその昔、金長ダヌキが封じ込めたという伝説の玉があるらしい。玉を探す刃たちに忍び寄るは、忍者･風魔小太郎。そして、鬼丸は「鬼丸天下統一プロジェクト」を計画し、日本の全てを手中に収めようと、着々と準備を進めるのだった。', '2025/07/15 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/263da02a-e4d1-4aa6-888b-452b41017adf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b49d29d-68c9-4fde-b692-a658a78607b1', '919ad3c3-869a-4897-9042-160fe5335704', 15, '100233294', '対決! 妖術師VS刃', '今度は四国で、変身することができる「金の玉」を手に入れた刃たち。次なる玉のありか･九州を目指す。さっそく金の玉の力でイカダに変身して、皆を乗せ向かうのだった。九州に到着した刃一行は、いつかの敵であったヒトデ男と再会する。話によると、伝説の玉が阿蘇山の火口の奥底に眠っているらしい。早速、ヒトデ男の案内で向かう刃一行。その後を、ひっそりとクモ男と天草四郎が追っていた。', '2025/07/22 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ab50aa9-b53c-46a7-903d-c923e4a84908.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e327e39b-4b1c-48ae-8fec-6576df50037a', '919ad3c3-869a-4897-9042-160fe5335704', 16, '100233551', '巨大決戦', '九州で「火の玉」を手に入れた刃たちは、奈良に訪れていた。撫子からの情報を待つ刃たちの元に、石田六右衛門と名乗る男がやってきて、仲間になりたいと懇願される。どうやら武者修行の旅をしていて、道中で刃たちの噂を聞き付けたのだという。その夜、さやかに撫子から玉のありかが分かったと連絡が。皆に伝えようとするさやかだったが、なぜか武蔵はありかを言わなくてよいというのだった。', '2025/07/29 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c99bfccf-4e43-4674-8050-33064621c40a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6863adb-81f4-49ac-9ff6-51687418794d', '919ad3c3-869a-4897-9042-160fe5335704', 17, '100234053', '柳生新陰流の男', '石川五右衛門と大阪で戦いを繰り広げた刃は、巨大化する能力を持つ「大の玉」を手に入れたものの、五右衛門に水の玉と金の玉を奪われてしまった。玉を取り返すべく、川中島での決戦に備えて新潟に来ていた刃たちは、道中で武蔵のかつての弟子である、柳生十兵衛三厳と出会うのだった。ただ、十兵衛は刃たちと会うまでどうしていたのか、記憶がおぼろげなようで…?', '2025/08/05 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1407bb18-9a01-43d6-8237-560074e73561.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6541c25e-b717-476c-8137-3d7606774fd1', '919ad3c3-869a-4897-9042-160fe5335704', 18, '100234717', '川中島大決戦', '十兵衛が仲間になり、より戦力が増強した刃一行は、奪われた玉を取り返すべく五右衛門との二回目の決戦へ向かう。川中島に到着した刃たちは、隠れていた五右衛門の奇襲攻撃を受けるものの、仲間と陣形を組んで応戦するが五右衛門が用意した黒鬼忍者軍団に囲まれてしまう。やがて武蔵や十兵衛、撫子の奮闘によって敵将への活路を見出す。そして、刃と五右衛門の一騎討ちが始まるのだった。', '2025/08/12 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed7fdf3b-2042-4b33-aa80-755cb454d89c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb55e6aa-53b1-4101-8c2b-cbb39a6db934', '919ad3c3-869a-4897-9042-160fe5335704', 19, '100235142', '闇玉脱出特訓', '五右衛門から手に入れた玉の正体は、夢を持つ者を吸い込むという「闇の玉」であった。玉の中に吸い込まれてしまった刃と十兵衛は、ケロ吉という闇の世界の案内人と出会う。この世界では何でも夢を叶えられるが、何故かこの世界から抜け出すことはできないらしい。しかし、ケロ吉から闇の滝の裏側に出口があることを聞き出した刃と十兵衛はすぐに滝へと向かうが、ケロ介という河童が出口を守っているようで…?', '2025/08/19 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5a2513a-8219-4aad-9b01-08ce8cd11d43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1687dd48-61c6-41e9-ad83-97e44288ff98', '919ad3c3-869a-4897-9042-160fe5335704', 20, '100235514', 'モンキー芭蕉の策略', '伝説の玉を六つ手に入れ、残すところあと一つとなった玉を探す刃一行は、最後のありかである青森を訪れていた。とある寺にたどり着くと、最後の玉に共鳴するように、刃たちの持つ玉が突如として光り出す。驚く一同の元へ、松尾芭蕉と名乗る老人が現れる。その手には、探していた最後の玉が。玉をめぐって戦いが始まるが、正体を現した芭蕉によって繰り出される石化攻撃に苦戦してしまう。', '2025/08/26 00:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57490e0d-abce-410f-9524-bea02377417f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48e18ca0-68f1-41f0-aaea-e6b5f9c5fff3', '919ad3c3-869a-4897-9042-160fe5335704', 21, '100237429', '富士山頂でまつ', '最後の伝説の玉「当の玉」に導かれ、富士の火口にあるという龍神の玉を手に入れるため、富士山へと向かう刃たち。当の玉いわく、七つの玉を集めたとき、龍神の玉を手に入れることができるという。その頃富士山では、新たなる必殺剣「竜巻斬り」を習得した鬼丸が刃を迎え撃つべく待ち構えていた。龍神の玉をめぐる戦いが、始まろうとしていた――', '2025/09/09 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b19d1b2f-08ba-4ce5-860a-1581043850b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f20789ee-5ed8-4416-a1fa-34578b701663', '919ad3c3-869a-4897-9042-160fe5335704', 22, '100237836', '心の岐路', '富士山の火口に到達した刃は龍神の玉を手に入れるため、鍵である七つの玉を使い龍神の試練に挑む。直後、刃は入り口の罠で庄之介を失ってしまう。しかし、戦いには犠牲がつきものだと言ってのける龍神に、怒りが込み上げる刃。武蔵の窘めで覚悟を決め、仲間を失った気持ちを飲み込み、次の試練に進む刃。ただ、龍神の試練はまだ始まったばかりなのであった。', '2025/09/16 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15a6e66b-c483-46d2-963d-251a28915d2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccf46e18-61e8-47f8-a6cc-756148f2f238', '919ad3c3-869a-4897-9042-160fe5335704', 23, '100238746', '蘇る! 龍神の玉', 'いくつもの試練を何とかクリアし、最後の試練にたどり着いた刃。そこには失ってしまったと思っていた仲間たちと、史上最強の玉である「龍神の玉」が待っていた。龍神からの最後の試練は、決断すること。それは、「仲間を救い、龍神の玉を失うか」。それとも、「仲間を見捨て、龍神の玉を得るか」のどちらかを選べ、という問いだった。仲間の命か、龍神の玉か。刃が選択した答えとは――', '2025/09/23 00:00:00', 1434, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e186c46-e642-44b3-8825-80dd075d6713.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e21ec6d9-aa3d-444f-93fd-ac14b427eabb', '919ad3c3-869a-4897-9042-160fe5335704', 24, '100239125', '月からの侵略者', '【シーズン1 最終話】試練に打ち勝ち、龍神の玉、そして魔剣「龍神剣」を手に入れた刃は、空を飛べる能力を得て、鬼丸と太平洋上で再び戦いを始める。しかし、決戦の最中、突如上空に巨大な船が出現したのだった。突然の出来事に驚く刃と鬼丸だったが、二人の前に一人の女性が現れた。その正体は、千年の眠りから目覚めたという月の支配者･かぐや。刃、鬼丸、かぐやの三つどもえの戦いが、突如として勃発する。', '2025/09/30 00:00:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa2a6024-3287-42e7-b66e-7db8fcb18738.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f6cc2878-9a74-4ef1-a228-84e65aefb937', '真の仲間じゃないと勇者のパーティーを追い出されたので、辺境でスローライフすることにしました', '', 'hulu', 'banished-from-the-brave-mans-groupi-decided-to-lead-a-slow-life-in-the-back-country', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77316886-462c-4d3d-a631-d2b5926a6efa.jpg?w=331&h=447&p=t', 'hulu', 2021, 3, 1, 'FINISHED', NULL, 126213, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('50f2422f-1236-484e-ad80-487dd9a165ce', 'f6cc2878-9a74-4ef1-a228-84e65aefb937', 'hulu-banished-from-the-brave-mans-groupi-decided-to-lead-a-slow-life-in-the-back-country-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e1ac5bc-79ac-4aea-823f-3f2e0466e505.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2de5b4a8-3d6a-4d19-8ae9-686bdb09ef34', '50f2422f-1236-484e-ad80-487dd9a165ce', 1, '100099855', '俺は真の仲間じゃないらしい', '辺境の地ゾルタンの冒険者レッドには、勇者のパーティーから「真の仲間じゃない」と追放された過去があった。ある日、友人の甥っ子タンタが危険な病を発症し……。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e1ac5bc-79ac-4aea-823f-3f2e0466e505.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9b0e339-c290-48fa-83e0-95102e63a6e0', '50f2422f-1236-484e-ad80-487dd9a165ce', 2, '100099856', '勇者の仲間にならなかったお姫様', '開業したレッド薬草店に、軍事大国ロガーヴィア公国の第二王女リットが現れる。かつての戦友であり、レッドに好意を寄せるリットは、レッドに驚きの提案をする。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/407cfb4f-8ad4-454e-a1b2-7bd1c4cc6672.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e16ec82-347e-4c3a-a80c-5e2182960980', '50f2422f-1236-484e-ad80-487dd9a165ce', 3, '100099857', '2人でスローライフを始めよう', 'レッドはリットと同居生活を送ることになった。町へ出た二人は、タンタとその友達アルが、『喧嘩屋 (バーブローラー)』の加護に触れたアデミと争うところに遭遇する。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd86ed16-3538-4212-9afb-d003a8269d10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee60b3f1-12dc-4123-812c-b593e258dad8', '50f2422f-1236-484e-ad80-487dd9a165ce', 4, '100099858', '蜂蜜酒の理由', 'レッド&リット薬草店に、ゾルタンのBランク冒険者アルベールがやって来る。レッドが優れた実力を隠しているのではないかと疑い、仲間に引き入れにきたのだ。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4ab01d9-e96c-43b1-bfc8-d10941c1df56.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0094e619-8fe8-4893-9dae-bc2bf9bcea8d', '50f2422f-1236-484e-ad80-487dd9a165ce', 5, '100099859', '琥珀の中の指輪', 'ゾルタンの大物達が訪ねてくる。薬草店を辞めて冒険者に戻るよう、リットに求めに来たのだ。一行の中にいた盗賊ギルドの男は、リットと手を切るようレッドを誘惑する。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5260107-93ee-41c7-84b7-920faaee7308.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('428234e7-42db-4854-ac98-8b5a6a19bbec', '50f2422f-1236-484e-ad80-487dd9a165ce', 6, '100099860', '始まりの凶行', '飲めば新しい自分にもなれるという危険な薬物が、出所不明のままゾルタンの町に広がっている。その薬を飲んだらしい、アルベールの仲間が荒れ狂って人を傷つける。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8799308-c97b-4840-b03f-dc0561f3f00a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01cf71dc-f24b-456f-9a56-30a8787b3ce5', '50f2422f-1236-484e-ad80-487dd9a165ce', 7, '100099861', '嵐の後に燻る火', 'アルとその両親が、家に来たアデミに襲われた。アデミは傭兵隊長の息子。アルの地元サウスマーシュ地区の人々は、姿を隠したアデミを衛兵が匿っているとして抗議する。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c332ef83-385a-4499-966d-805f080a456b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7df5a09-bd5c-48f7-ae06-5e4a8af68267', '50f2422f-1236-484e-ad80-487dd9a165ce', 8, '100099862', '英雄になろうとした男', 'サウシュマーシュ地区の人々と衛兵達との対立は、盗賊ギルドの大物･ビッグホークが裏で糸を引いていた。ビッグホークは、拉致してきたアルに恐るべき野望を語る。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6981a94f-eb58-4221-9180-e7e5353ebec9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f13f8c18-024c-4842-9da2-8f5b5cb9a282', '50f2422f-1236-484e-ad80-487dd9a165ce', 9, '100099863', '穏やかな日々', '勇者ルーティは、パーティーを置き去りにして飛空艇に乗り、追放された兄･レッドのもとへ向かう。『悪魔の加護』の薬を飲んだことで、そうすることが可能になったのだ。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf7d425e-eaa2-4fd8-ab73-026c89409123.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c96e8d6-3310-4323-8041-a46edafa7edc', '50f2422f-1236-484e-ad80-487dd9a165ce', 10, '100099864', 'これは勇者を救う物語', 'レッドのもとに辿り着いたルーティは、二人で楽しいひと時を過ごす。その頃、置き去りにされた勇者パーティーの賢者アレスが、ルーティの行く先を突き止めていた。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bb53a9f-122f-469c-bb69-0ad606c3c44a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d7b2b52-2f7e-4cc8-838e-dcda7d038a1b', '50f2422f-1236-484e-ad80-487dd9a165ce', 11, '100099865', '英雄達はゾルタンに集う', '『悪魔の加護』を作ったゴドウィンの錬金道具を買うため、レッドは港の市場へ。すると、彼の行方を追っていたという元勇者パーティーのダナンが、声をかけてくる。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4dbd8c3a-20f5-45ae-b3d3-c73e3ad40e43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fee39c2-fe26-4b58-be14-fcaa9ee6b289', '50f2422f-1236-484e-ad80-487dd9a165ce', 12, '100099866', '別れ道', 'レッド達は古代エルフの遺跡で、レッドを追放した張本人であるアレスと再会。何としてもルーティを魔王討伐に連れ戻したいアレスは、謎の男ビュウイと手を組んでいた。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca060f12-6c3f-433a-984f-283c8f76890e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb8fdf2e-a9f3-4d9b-b2b6-aba442669f00', '50f2422f-1236-484e-ad80-487dd9a165ce', 13, '100099867', '導き手', '【シーズン1 最終話】勇者ルーティの刃から、ティセが盾となってレッドを守った。レッドによって聖剣を失ったルーティは我に返り、ティセの傷を癒そうとするものの、勇者の加護は力を貸さない。', '2022/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daada1aa-08f5-4466-9c26-c220ac91c1e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('78dfcafc-f1f5-4118-abec-017749749140', '真の仲間じゃないと勇者のパーティーを追い出されたので、辺境でスローライフすることにしました 2nd', '', 'hulu', 'banished-from-the-brave-mans-group-i-decided-to-lead-a-slow-life-in-the-back-country-2nd', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5afb8695-f844-4fa6-af0d-7e884875da5c.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 156131, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c99250e1-7e41-4376-bed8-b20291066125', '78dfcafc-f1f5-4118-abec-017749749140', 'hulu-banished-from-the-brave-mans-group-i-decided-to-lead-a-slow-life-in-the-back-country-2nd-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7137c771-2d57-4051-9661-5d54beede578.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('516161bb-6e86-448b-bfe3-42b4724189d6', 'c99250e1-7e41-4376-bed8-b20291066125', 1, '100181535', 'スローライフな旅をしよう', '恋人のリット、妹のルーティと一緒に「世界の果ての壁」と呼ばれる山脈を目指すレッド。リットに贈る婚約指輪の素材を手に入れるための、気楽な旅のはずだったが……。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7137c771-2d57-4051-9661-5d54beede578.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73914f9b-04f2-4dc9-9615-01db5b6f67fc', 'c99250e1-7e41-4376-bed8-b20291066125', 2, '100181536', '宝石の獣', 'ヤランドララと再会したレッドとリットは、キラミン王国への移住を提案される。根気強く粘るヤランドララに二人は戸惑うばかり。そんな中、ティセの勧めで温泉に入ることに。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93a79c5c-d018-4041-a507-30cb9d039762.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43d08aea-f9fb-47c0-9031-48568d2c440f', 'c99250e1-7e41-4376-bed8-b20291066125', 3, '100181537', 'ゾルタンの祝祭日', 'リュブ枢機卿がゾルタンの飛空艇に興味を示し始める。一方、ゾルタンは祝祭日を迎え、朝から活気に溢れていた。レッドたちもお祭りを楽しむが、若者の喧嘩に遭遇してしまう。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a89879e9-1e1c-43ea-a7cf-757bed953f66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f9eb3f4-47ed-4d69-8d4b-43e8129521e7', 'c99250e1-7e41-4376-bed8-b20291066125', 4, '100181538', '元勇者と暗殺者の日常', 'いつも通りの朝。ルーティは「勇者」として切り捨ててきた当たり前の日常を噛みしめる。だが、その日はティセの様子がおかしかった。昨晩のことを尋ねようとするが……。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a5eb4e1-7ad7-4fa0-b168-fe5db8428728.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64fcc8b3-385e-4dd5-ae2a-0f40284b4268', 'c99250e1-7e41-4376-bed8-b20291066125', 5, '100181539', 'スローライフが理解できない男', '療養中のダナンが快方に向かいつつあった。町を出る前にレッドとの手合わせを求めるダナン。快諾したレッドのために、かつての勇者パーティーによる特訓合宿が始まる!', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b8e72c6-f21a-4d8e-8e55-4aab09d53478.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c7d23b1-e190-43de-8036-118afec14069', 'c99250e1-7e41-4376-bed8-b20291066125', 6, '100181540', 'ロングバケーション', 'ヴァンたちがゾルタンに向かっている。ルーティの存在が知られれば面倒なことになるかもしれない。レッドとリットはルーティを連れて、三人で旅行をすることに。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caad2f15-b44b-4ac1-8e39-a877007721fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d0f42ae-f435-4462-a8be-2ae5c92ea0d5', 'c99250e1-7e41-4376-bed8-b20291066125', 7, '100181541', '二人の勇者', 'セントデュラント村で休暇を過ごすレッドたちに、かつてこの村を襲ったオーガキンの目撃情報が入る。レッドたちが見回り役を引き受けると、状況は想定以上に深刻だった。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb14103f-eb7f-4d24-8c8e-067fbcd5d447.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec04d1d7-cb1c-4337-9e8f-9eaaf3e1d1f3', 'c99250e1-7e41-4376-bed8-b20291066125', 8, '100181542', 'すべては加護と信仰の為に', 'ヴァンのヒルジャイアント討伐に同行したティセは、彼の歪んだ正義に衝撃を受ける。その正義は勇者を歓迎するゾルタンの人々にも向けられ、大規模な騒動へと発展していく。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4531d260-ffea-49b5-84b7-c50723fe1874.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5400f038-6cda-4ef5-8c7c-cd82240101fd', 'c99250e1-7e41-4376-bed8-b20291066125', 9, '100181543', '恋する妖精と強欲な枢機卿を狙い撃て', 'ゾルタンからヴァンを追い払うために、レッドたちはリュブとラベンダの懐柔を狙う。ラベンダとの交渉役に名乗りを上げたのはリットだった。その方法は……恋バナ!?', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1caed51-af5f-4d46-a355-ea4d3581072a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('472cd643-7e8f-4f6b-a563-8d7cb1139da4', 'c99250e1-7e41-4376-bed8-b20291066125', 10, '100181544', '勇者と導き手', 'エスタに裏切りの嫌疑を掛けたヴァンたちがレッドの店に押しかけてくる。話し合いの中でヴァンの価値観に触れたレッドは、その硬直した考えを覆そうと大胆な接触を試みる。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ed8e7ca-4a67-4c9c-bce9-c8b28c3404eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f3a0416-c73b-49f6-9dcf-0a1168969f8d', 'c99250e1-7e41-4376-bed8-b20291066125', 11, '100181545', '勇者の挑戦', 'ティセの依頼を受けたアルベールが、森で消息を絶った少女の捜索に向かう。無事に発見したものの、同じく救出にきたヴァンの思い込みから戦闘に発展。窮地に追い込まれる。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6062bc4c-220e-4687-8ae2-24ef0aecbab5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd7ce156-106c-4d52-a362-a2cd0b29e286', 'c99250e1-7e41-4376-bed8-b20291066125', 12, '100181546', '決着、次の旅へ', '【最終話】技量で圧倒するレッドと執念で食らいつくヴァンが、一進一退の攻防を繰り広げる。一方、ヴァンの窮地にラベンダが激昂。その体から溢れる巨大な影がリットたちを襲う。', '2024/05/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79e5858e-3bdd-4a81-b70a-ef934d112b33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('26ecad69-e37e-496d-b8ab-64259889bc44', '真夜中のオカルト公務員', '', 'hulu', 'occultkoumuin', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50809bc4-cb94-4503-b9f2-8a7a05029d6a.jpg?w=331&h=447&p=t', 'hulu', 2019, 1, 1, 'FINISHED', NULL, 102939, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b1686268-34e8-4e68-9d37-5c3a05760d1f', '26ecad69-e37e-496d-b8ab-64259889bc44', 'hulu-occultkoumuin-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6424260-231b-44e7-809e-369bffd60bce.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5176cd2-70a9-474d-a4f7-c1f674ad3176', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 1, '100033845', '新宿上空の天狗と天使', '春から新宿区役所「夜間地域交流課」に配属された宮古新。課の先輩となるのは、怪しげな実験に興じる姫塚セオと、元ホストで業務リーダーの榊京一。そして、今夜の現場という新宿で新が目にしたのは、妖精や天使や天狗といった人ならざる者たち「アナザー」だった。夜間地域交流課のお仕事は、アナザーが関与するオカルト的事象の解決。にらみ合う天使と天狗を見て、榊とセオは縄張り争いの激化を制そうとするが、新にはそんな争いには見えていなくて…。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6424260-231b-44e7-809e-369bffd60bce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bbfa052a-a721-4035-bb50-be9e66d50d12', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 2, '100034292', '神楽坂の白い猫又', '新は、人間にはわからないアナザーたちの言葉が理解できる「砂の耳」を持っていた。安倍晴明との繋がりがある可能性もあった。夜間地域交流課課長の仙田礼二は、新の背景を調査することを指示。新と榊とセオが、神楽坂の新の実家の蔵に足を踏み込むと、そこにいたのは二股の尾を持つ白い猫ユキ!? また、ある日は千代田区の狩野一文庫へ。狩野一とは、イギリス系魔術と日本の陰陽術を融合させた魔術道具職人であり、古くからの陰陽師の一族だという。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc19ffa8-2f72-48af-82cc-0933742ba2c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ad544db-fed9-4c45-a3f0-85ec39ecf7ef', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 3, '100034870', '琥珀の瞳のトリックスター', '近ごろ続いたオカルト的事象は、あるアナザーによって引き起こされたものだった。アナザーの目的は僵尸の儀式のための素材集め。アナザーは新のことを安倍晴明と呼ぶと「ぼくを楽しませて♪」と大量の僵尸で新を囲むのだった。榊とセオに打開策を尋ねながらとり乱す新。自分を晴明と呼び続けるアナザーに怒るも、晴明でないなら殺すとアナザーがいいだしてしまう。新を晴明と呼ぶアナザーの正体は災いの神ウェウェコヨトル。かつて安倍晴明が「琥珀」と名づけた存在だった。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc502c55-49a4-40f5-ae0f-1d02fb319c28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2fa7296-9096-4c86-9103-7ec15a654bdc', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 4, '100034967', '歌舞伎町の定点観測', '新の家にカジュアルな装いに変身した琥珀が居付いてしまい、戸惑う新。そんな中、夜間地域交流課では伝統行事、春期特殊事案定点観測が行われた。新宿の街を見回る新たちが出会ったのは、酒盛りする猿のアナザーの猩々、超絶美形全裸の小豆洗い、ハイエナの姿のブルドゥンギンなど多種なアナザー。アナザーたちは口々に新の砂の耳のことを噂していた。そして、交番の警官が歌舞伎町の守護神･鬼王権現に連れ去られようとしているのを目撃して…。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca3c112a-1eb6-45c4-89c7-6d7bfb80dcda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9241125c-0eea-44cf-b829-448d7c62cd8e', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 5, '100035079', '都庁展望室の異世界エレベーター', '「異世界エレベーター」の都市伝説が噂される新宿都庁展望室に調査に向かう新たち。展望室で記憶を失う事件も続いていることで都庁から現地調査の許可が下りたのだ。新と榊が北、セオが南の展望室エレベーターに乗り込むと、新と榊が着いたのはアナザーが引き起こした異空間。そこには「あなたたちのそれ、頂戴」と妖しく微笑むアナザー、パンドーラが立っていた。パンドーラは新がアナザーと話せるとわかるやいなや榊だけ元の世界に戻す。探しているのは、ある喪失感だというが…?', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a01627d5-48a9-436b-9174-29442a59d463.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fea8d22f-c97c-47b7-ac2b-bbb382b2203a', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 6, '100035608', '悪魔と喪失感', '都内女子行方不明未解決事件の被害者のひとりで、アナザーに囚われていたところを保護された女子高生が目を覚ました。なんと、彼女は昭和四十年代生まれで、高校生のときにさらわれて以来、そのまま歳をとっていなかった。長年この事件を追ってきた榊は、彼女から「黒い砂」の話を聞き、ある確信を得る。かつて自身の姉がさらわれた時にも黒い砂が残っていたのだ。そして、ついに新の目の前でも事件が。幼なじみの泉美がアナザーにさらわれてしまう。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e474fa6-b4ab-4101-9da1-4ab735fb12d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f510a03-a1ff-4413-a3c5-41dc162f69a2', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 7, '100035843', '喪失感と絶望の証明', '女性たちをさらっているアナザーはアザゼルという悪魔だった。アザゼルは伴侶だった「少女」の死を受け入れられず、女性たちから身体のパーツを集めて、蘇らせようとしていた。事件の主たる発生場所は女子校。新、榊、セオが都内の学校を捜索していると、琥珀が現れて、彼らを異空間の回廊へ誘うのだった。しかし、回廊内のアザゼルは、泉美や榊の姉の詩織の身体を使って、少女蘇生の最後の仕上げにはいってしまう。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d63e3371-2e7b-4172-9327-cbbdcbf88542.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6b60a8f-655e-4438-9912-519ed073f84a', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 8, '100036448', '老いたコヨーテと星降る庭', 'さらわれた当時の17歳のまま戻ってきた榊の姉の詩織。特殊な社会復帰となるが、榊は姉孝行ができることを素直に喜んでいた。一方、新はアザゼルの悪行を看過していた琥珀に怒る。けれど、琥珀は「トモダチのためっていうかー」と目を逸らし、新とユキを抱き上げて街に繰り出した。すると、立ち寄った文京区や台東区のアナザーたちが災いの神ウェウェコヨトルである琥珀の来訪に驚愕。スカイツリーでは晴明と縁のある八咫烏のクロに出会うが…。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99a1ec62-eab2-46fa-8e42-46a7be2f4ce8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70192ab4-2278-421f-b20e-ecb8ddbb0f97', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 9, '100036677', '幽霊団地の夢魔 (ナイトメア)', '新宿区役所職員の相田からあがった夢に関わるアナザー事件。任された新が話を聞くと、相田の息子が悪夢を見続けて、ついに目を覚まさなくなってしまったのだという。夢にまつわるアナザーを調べる新。そんな折り、都庁で行われる交流会で、東京都夜間文化環境局の狩野一悟と共に業務にあたることに。しかし、その先で新は、アナザーとは意思疎通を図ることはできないと言い切る悟に対して、大きな憤りを感じることになる。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6645873f-8db0-4584-bf40-e3a3ccbb2ea7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('325ecd4b-f257-40e7-bd17-ac22229e0fee', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 10, '100036827', '白い繭と青い炎', '新の砂の耳の能力に疑いの目を向け、アナザーは処理するものだという考えを持つ悟は、新が心を通わせた夢魔を淡々と処理した。そして、アナザーとの対話による解決を望む新に、ならばその耳で悟の持っている案件を解決してみろと持ちかけた。現場は競技場。何らかのアナザーによって、競技場全体に無数の繭が産み付けられていた。けれども、中には赤子のアナザーの姿があり、新にも言葉を交わすことができない存在なのだった。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6793297-852f-44a0-99f4-4c681bcba6d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1821aee8-143b-401a-b145-b870eeb2f8c0', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 11, '100037267', '砂の耳と新人の根性', '悟の指示のもと、新を除く交流会メンバーによる繭の駆除がはじまった。しかし、職員たちはみな、繭に取り込まれてしまう。繭をつくったアナザーは蚕神。出雲への献上品のための糸を紡ごうとしていたが、邪魔されたことにより、祟り神に転じてしまう危険性があった。神の怒りを鎮めるには複雑な儀式が必要になるが、新の砂の耳なら儀式なしでも説得できるかもしれない。危険な任務だったが、今できることの最善が自分にあるならば、と新は向かっていく。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee4b21cb-b8fd-4321-9eae-751bda007db2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f6689aa-fec6-41e6-a45f-f100db028c70', 'b1686268-34e8-4e68-9d37-5c3a05760d1f', 12, '100037949', '新宿区夜間地域交流課', '【シーズン1 最終話】ある夜、記憶喪失のアナザーを保護した新。依代だった石像が壊れてしまい、寄る辺ないアナザーは、新の家でしばし預かることになった。新は時間を見つけてはアナザーと街を歩き、アナザーを知る手がかりや新しい依代を探す。しかし、次第に消耗し、ついに倒れてしまう。自分が新のエネルギーを吸いとっていることに気づいたアナザーは新の元を去ろうとするが、新がそれを止める。そして、これが自分の仕事なのだとまっすぐにいうのだった。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2594258e-af13-4704-b8ab-586130e29446.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4fe37d18-0ed5-4852-a36f-33e60e7541e9', '神の雫', '', 'hulu', 'the-drops-of-god', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c67ce10-92c7-44ef-9a39-4e9acb37e367.png?w=331&h=447&p=t', 'hulu', 2026, 1, 1, 'NOT_YET_RELEASED', NULL, 202508, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('64fcd20d-7b3a-4742-a7fe-9fe5955ccbc5', '神は遊戯に飢えている。', '', 'hulu', 'gods-games-we-play', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6ba877f-fc14-465d-9077-3e9457689d19.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 144176, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('03dce98b-c0c7-4a28-a7e7-af6e582c25b7', '64fcd20d-7b3a-4742-a7fe-9fe5955ccbc5', 'hulu-gods-games-we-play-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c16fa81-4ded-4060-bd72-9b669d919ff6.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c88a8e8b-22ec-4bd7-91d5-1fbd943fdb5c', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 1, '100180361', 'Gods'' Games We Play', '三千年もの間、氷河の中に閉じ込められていた少女･レーシェが目覚めた。元･神様の彼女は開口一番「この時代で一番遊戯 (ゲーム) の上手い人間を連れてきて」と宣言。指名されたのは「神々の遊び」で無敗のまま3勝中の少年･フェイ。彼女を監視すべく神秘法院ルイン支部を訪れる。そこで彼は、レーシェから「自己紹介神経衰弱」を挑まれて……!?', '2024/04/06 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c16fa81-4ded-4060-bd72-9b669d919ff6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('543c84a0-37f1-4418-a6cb-75b3032ffd9b', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 2, '100181632', '神ごっこ', '二人が挑むのは、巨神タイタンによる「神ごっこ」。鬼ごっことかくれんぼがアレンジされたゲームの勝利条件を推理しながら、フェイとレーシェは攻略目指して進んでいく。しかし、タイタンにタッチされていない使徒までも神の配下にされてしまった。そのことから、フェイは隠された「第3のゲーム」の存在を見破るが…?', '2024/04/13 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11fc1780-bb9c-497e-940b-5463adbccea0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df96be82-9e75-4021-b3d7-80ca18fa1aae', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 3, '100182079', 'パール･ダイアモンドです', 'ミランダから、チームを組むのであれば三人以上でなければならないとの指摘を受け、フェイとレーシェはチームメイト探しを開始する。フェイは知り合いのチームに合流できないか連絡するものの、レーシェに怯えるあまり、誰も取り合ってくれず……!? そんな中、どうしたものかと策を練り続ける二人の前に、ある少女が現れた。', '2024/04/20 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/815cea1f-cbd8-476b-99f4-75289e105844.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('303b9d14-bf04-4057-965e-2d2f2e3af10f', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 4, '100182636', 'ウロボロス', 'フェイ、レーシェ、パールが降り立った先は無限神ウロボロスだった。使徒たちは、神にとある単語を言わせれば勝利するゲーム「禁断ワード」に挑むことに。ミィプによるとその単語とは、既に使徒が言った言葉らしいが……。いまだ攻略成功者ゼロの全長一万メートルにも及ぶ神との頭脳戦が、いま始まる!', '2024/04/27 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2326573-7f83-46c2-ac6c-a4d1c6f49795.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('523120d9-49ef-49c8-9f3c-b5a9cd19e83a', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 5, '100183512', 'ワールドゲームズツアー', 'パールが正式なメンバーとなったものの、ダイヴ希望者が多すぎるためにフェイたちは「神々の遊び」に挑むことができない。そこでミランダは、フェイたちにワールド･ゲームズ･ツアーへの参加を提案する。数ある街の中から選ばれた聖泉都市マル＝ラに向かった彼らを待っていたのは、元使徒の少女･ネルだった――!', '2024/05/04 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/939327c1-ff28-4551-a13e-b82d46d16b31.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fddd83e-90a4-496f-bf8b-b7e0a1a09e87', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 6, '100184072', 'マインドアリーナ', '二対二で行われるカード戦略系すごろく「Mind Arena」の試合が開始し、ダークス&ケルリッチに対してフェイ&パールが立ち向かう。このゲームの勝利条件は、先にゴールに辿り着くか、相手のライフをゼロにするかの二つ。攻撃系の職 (クラス) を選択し、高火力のカードで襲い掛かるダークスたち。追い詰められるフェイたちに、果たして挽回の策はあるのか……!?', '2024/05/11 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a9c8a69-9421-4cf1-9078-891ca94aed58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1eee98af-9aa3-492b-84c6-eba2469c4c5d', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 7, '100184794', '太陽争奪リレー', '都市対抗戦に勝利したフェイに、ネルはチームのアナリストになりたいと志願する。しかし、フェイは彼女の「本当にやりたいこと」は他にあるはずだと、自分たちの「神々の遊び」の応援をお願いするのだった。ネルが中継を見守る中、フェイたちはマアトマ2世による「太陽争奪リレー」に挑む!', '2024/05/18 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/310b8e33-ec76-402b-9e5b-8b90180d4b2a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e37b7cb-4746-4e4a-8243-fe38d1fd5f6f', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 8, '100185392', '太陽はどこへ消えた?', '遂に始まった「太陽争奪リレー」。神を欺くため、フェイたちはチームメイトであっても太陽の花を持つのが誰か明かさずプレイすることを選んだ。しかし、あまりにも多い猫ゴーレムの猛追に遭い、また一人、また一人と使徒が減っていく。劣勢の中、フェイたちに活路はあるのか。', '2024/05/25 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db24a675-73cf-4564-81a0-b76e345cceab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('554d00ea-9086-48d4-8fe6-76937f1ec2d7', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 9, '100186418', '賭け神 (ブックメーカー)', '賭け神 (ブックメーカー) は、同行者の1勝を賭けて勝利することで使徒の1敗を消してくれる神である。ネルを使徒として復帰させるため、フェイたちは賭け神への挑戦を決めた。一行はルイン支部に戻りネルの歓迎会を実施。パーティーのあと、お風呂でも女子たちは親交を深めるのだが……? そしていよいよネルは、賭け神との勝負に挑む!', '2024/06/01 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6060619-34ea-466f-b3b3-d82a95464845.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5b7becb-120d-4fa2-bfa7-3803063b9e68', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 10, '100187060', '神がもたらす三つのイカサマ', 'グレモワールが挑んできたのは「三つのイカサマ」。コインの裏表当て、ポーカー、ババ抜きを通して使われている同じイカサマを見破るという勝負だった。しかし、なにせ相手は神。なんでもできる中で、どんなイカサマをしているのか? ババ抜きまで終えたフェイは、もう一回ババ抜きをやることを提案するのだった。――「次のゲームでお前の必勝を打ち破る」', '2024/06/08 22:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bc01594-b6ae-40f7-9683-d4e443f72f3a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cb12eb5-ce5d-4774-8a1c-c1bcb92723b9', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 11, '100187511', '帰らずの“迷宮”ルシェイメア', 'フェイたちが飛び込んだ「死と再生の迷宮ルシェイメア」は、死んでも無限にリスポーンするダンジョンだった。迷宮には様々なモンスターや凶悪なギミック･罠が満載。フェイたちは攻略のカギとなるアイテムを回収&クラフトしながら迷宮を探索していくのだった。ミィプによると、最深部にいるラスボスを倒せば現実世界に戻れるらしいが、フェイ達は無事に最深部までたどり着けるのか……!', '2024/06/15 22:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6cd207b-f4db-4af2-a245-a0127a83d40d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('274ede4e-6fe0-4c4e-86f5-135e78befbc3', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 12, '100188380', '死と再生の“冥宮”ルシェイメア', 'ウロボロスのワンパンで倒された眠れる獅子は、セーブアイテム･ライオンハートをドロップ。これによって使徒は現実世界に一時帰還できるようになった! しかし、フェイとウロボロスはこのゲームにストーリーが進まないバグが潜んでいることを見抜いていて……!?', '2024/06/22 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68330042-807a-49c0-9d4e-4e63e8e4c28d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48fcc943-6e4b-46c4-8beb-22dc59bb73cb', '03dce98b-c0c7-4a28-a7e7-af6e582c25b7', 13, '100188941', 'Good Game Well Played', '【最終話】フェイたちは迷宮の最深部に辿り着いたが、やはりラスボスは死んでいた。だがここは「死と再生の迷宮」。ラスボス不在で攻略不可能なら、“復活させてから”倒せばいい。アイテム･黄泉がえりの鈴を使うフェイたちだったが何も起きないようで……? そこでフェイがある要素に気づくのだった。', '2024/06/29 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5904b0d2-11e1-4214-9b0b-c3ea55d16f0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8ab4aa56-ffae-4385-983b-eb2e22464df7', '神魂合体ゴーダンナー！！', '', 'hulu', 'godannar', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50011738_series_art__338x600_godannar_7c7d2ca3d69b1114d08cd69efe450fa8.jpg?w=331&h=447&p=t', 'hulu', 2003, 3, 1, 'FINISHED', NULL, 1103, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fd07ff68-6164-4fe6-9a75-f0025c0a17e5', '8ab4aa56-ffae-4385-983b-eb2e22464df7', 'hulu-godannar-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ac60aa81-7c4b-49a1-9fd5-0e0a77d7ad22.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6818b676-8656-4f29-9dfb-7bf502509662', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 1, '60678526', '戦場のウェディングベル', 'ダンナーベースに所属するスーパーロボ「ゴーダンナー」のパイロットの猿渡ゴオは、擬態獣との最終決戦で、パートナーであり恋人だったミラを失う。その時命を救われたのは、12歳の葵杏奈だった。5年後、再会した2人は恋人同士になる。ミラとの過去を吹っ切り、杏奈との結婚を決意したゴオは、結婚式を計画するが…。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ac60aa81-7c4b-49a1-9fd5-0e0a77d7ad22.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c379f8cf-d3e2-4eec-a186-253e1afb5c40', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 2, '60678525', '炎のバージンロード', 'なんとか結婚した杏奈とゴオ。甘い新婚生活が始まるはずだったが、ゴオのパートナーを目指す杏奈は、ダンナーベースで訓練を受けていた。ミラを失ったトラウマから、杏奈をパイロットにさせたくないゴオは、厳しい訓練に疲れ、家事や学業を疎かにしている杏奈に辛くあたる。そんな時、杏奈の学校に擬態獣が現れて…。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0ec0a4c2-3d13-44d7-9084-f5d78c9f74cc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abed6df8-b814-441f-ae23-52c438b8c126', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 3, '60678524', 'バトルロイヤル･ハネムーン', 'マレーシア領ディオマン島沖。台風に隠れてやって来た巨大な擬態獣が、突然暴れだした。緊急に駆けつけたのは世界各国のパイロットたち。そこに、ハネムーンでやってきたゴオと杏奈は、擬態獣と戦う彼らの勇姿を目の当たりにする。戦うことの厳しさを知り、杏奈はゴオのパートナーとなる決心をますます固めるのだった。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f6a622e3-ec15-44b7-87db-8aef12ab8d23.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94cb7f0e-f0fc-4e3b-b25f-8f8c734f0d94', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 4, '60678536', '静流、再び', 'ダンナーベースで生活している杏奈とゴオ。そして、ゴオに想いを寄せる静流は、2人の存在が気になって仕方なかった。ドジばかり踏む杏奈に辛くあたってしまう静流。なんとか静流に気に入られようと、一所懸命に努力する杏奈だったが、そんな中、静流に移籍の話が舞い込んでくる。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0b48cc4e-83b0-49dc-b543-b6ce4676f792.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('463ec2a8-5c76-443c-bc83-44771e61faa7', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 5, '60678533', '空から来た少女', '杏奈と友達が休み時間を屋上で過ごしていると、空から流れ星が降ってきた。学校を抜け出し現場に駆けつけた杏奈は、コスモダイバーの中で気を失った美少女ルウの姿を見つける。コスモベースを擬態獣に襲われ、父と離れ離れになってしまったと言うルウを伴い、ダンナーの仲間たちは擬態獣を倒すため宇宙に向かう。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4a1cdaa1-3559-4375-8caa-c0c687183263.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9288c3d2-8dda-49f8-a228-3fad2c4e0e81', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 6, '60678534', '夢の終わり', 'ミラを失った5年前の戦いの悪夢にうなされるゴオは、ある日霧子から衝撃的な事実を打ち明けられる。5年前の戦いで死亡したと思われていた戦友マックスと、かつての恋人ミラが生きていたというのだ。しかし、ミラは記憶も知識も全く失ってしまっていた。そんなミラの存在に戸惑いを隠せないゴオだったが…。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ca583d1e-3695-4303-8a96-74c0e71b62b6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0600ae19-afa0-4dee-8aba-722c3753ae23', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 7, '60678530', '追憶ニ死ス', 'ミラの接吻で目を覚ましたマックスはコアガンナーを操り、周囲に無差別攻撃を始めた。そして、ミラを愛していたこと、ゴオとミラの関係に嫉妬していたことを告白する。ゴオとミラの関係を知らされてしまった杏奈。ミラの死を責められ、心を痛めるゴオ。精神的に追い詰められた2人だが、マックスを止めるために奮闘する。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e6a0dc3b-d466-4989-9c8b-71a4f5ec2177.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e5e4fc9-606b-4ee0-b9f0-0b4934862533', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 8, '60678529', '華麗なる撃墜王', '飛空獣との戦いによって攻撃を受けたナイトとエリスは、ダンナーベースに緊急避難した。ドラグライナーを修理する間、プレイボーイであるナイトは、ダンナーの女の子を手当たりしだい口説き始める。やがて被害はミラにも及び、それを見たゴオはナイトに殴りかかる。そんなゴオを、複雑な心境で見守る杏奈だったが…。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/dd0c080b-3907-4a0e-a7b3-a3c1ceaebc1f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e757c76-0aa1-41a0-9f57-c9e9845e9cb6', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 9, '60678528', '流されてサバイバル', '戦いの最中、杏奈をミラと呼び間違えてしまったゴオ。その一瞬の隙を攻撃され、ソシュール島へ墜落してしまったダンナーとオクサー、そしてドラグライナー。通信手段も途絶え、地震の多発する無人島に取り残されてしまった杏奈、ゴオ、エリス、ナイト。その地震の正体は、地下に潜む地底獣によるものだった。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5041bc52-1646-4e56-8bcc-c77b30d9fa56.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79c53723-3bee-4c3f-87e6-dc935cf51d08', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 10, '60678535', 'ルウ出撃', '戦闘禁止地区で何者かによる戦闘の痕跡が見つかり、Menage-Zeroが発令された。そこに残された多数の擬態獣の死骸が、父親を襲った擬態獣と同じであることを知ったルウは、戦いに参加したいと申し出る。ゴオたちに全く相手にされずふてくされるルウだが、擬態獣に妻を奪われた剣と出会い、操縦を教えてもらう。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/98df07e4-c5b0-4321-91f2-ce89f518c8ba.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b4607c9-2353-420d-a697-a0e98a65a165', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 11, '60678532', '汚れなき旅立ち', '擬態獣に囲まれたルウのピンチを救ったのは、ブレイドガイナーに乗った剣だったが、彼はMenage-Zeroによって破壊命令を受けたお尋ね者だった。自分より強い剣に、娘のような存在のルウを奪われた気分のゴオは、嫉妬心からブレイドガイナーに襲い掛かる。しかし、ゴーダンナーはあっさり負けてしまい…。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ed772009-e218-4dca-be22-a4f872ffaf16.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a343ad55-2f0c-4f55-9178-7ed5df1927e3', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 12, '60678527', '去り逝く者たち', '剣との戦いをきっかけに戦闘恐怖症になり、右腕が思うように動かなくなってしまったゴオは、そのことを必死に隠そうとしていた。そんな時、擬態獣が種子島を襲った。唯一ゴオの秘密を知る静流は1人で戦闘に向かう。静流の勇姿に立ち直るゴオ。しかし、最後の最後に静流は敵から激しい攻撃を受けてしまう。', '2016/02/25 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8006d36c-9b48-4c2e-ab72-9d6a72a80d6e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91f96f9f-9a4c-434a-b4bb-6aafd70267b9', 'fd07ff68-6164-4fe6-9a75-f0025c0a17e5', 13, '60678531', 'ラストファーストキス', '【シーズン1 最終話】杏奈がダンナーベースを後にして1週間が経過したある日、世界各地で擬態獣が大量発生したというニュースが流れる。すぐにベースに戻ろうとする杏奈だったが、街は混乱しあらゆる交通手段がストップしていた。ヒッチハイクで近くまで辿り着いた杏奈のもとにゴーダンナーが駆けつけるが、その後ろにはネオオクサーが…。', '2016/02/25 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b85fd6e5-b043-4a4a-b80a-3b046ebaa0ef.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('58b48b04-9971-4d06-b22c-30478bb9cafb', '8ab4aa56-ffae-4385-983b-eb2e22464df7', 'hulu-godannar-s2', 'シーズン2', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6e6da07e-038d-4593-a0f5-96c5f2d048b1.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa08be02-43bc-4366-9490-bed905d945fd', '58b48b04-9971-4d06-b22c-30478bb9cafb', 14, '60679513', '蘇る魂', '擬態獣との戦闘後、亡くなったかに見えた静流は、生死の淵をさ迷っていた。一方、安奈がダンナーベースを出ている頃、世界中に擬態獣が発生する。ゴーダンナーだけが出撃可能という中でミラが覚醒し、ネオオクサーでの出撃を志願する。復活したゴオとミラのコンビネーションを目前にした杏奈は、再び愕然としてしまい…。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6e6da07e-038d-4593-a0f5-96c5f2d048b1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf5efa37-4cab-4980-938a-282b2c51b095', '58b48b04-9971-4d06-b22c-30478bb9cafb', 15, '60679511', '新たなる告白', '大量発生した融合獣は、ゴオ＆ミラと世界各国のパイロットたちの活躍により終息を迎えつつあった。ゴオのパートナーの座をミラに奪われた杏奈はアパート暮らしをしていたが、猫のぴんぴんを見つけた大家さんに追い出されてしまう。途方に暮れる杏奈の前に、ぴんぴんにそっくりな青年が現れ、杏奈に結婚を申し込み…。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bde7ed66-4aa2-4cd6-9265-299bab614cf4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec79cd0a-94e7-4b06-b3c3-7faa9ad82f62', '58b48b04-9971-4d06-b22c-30478bb9cafb', 16, '60679516', 'その名はゴーオクサ－!', '擬態獣の出現に出動するゴオとミラだが、いざ合体という時にミラは気を失ってしまう。ゴーダンナーの緊急事態に、長い間封印されていたゴーオクサーが出動することになるが、ゴーオクサーの操縦は困難を極め、ミラも静流も完全に操縦出来ずにいた。「杏奈なら操縦が出来るかもしれない」と静流は杏奈を迎えに行くが…。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b93c833f-1d72-40b2-8d24-02e74ebab681.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('774f53c3-4c7d-43b0-8da0-1e47664d2d60', '58b48b04-9971-4d06-b22c-30478bb9cafb', 17, '60679515', 'TONKO MY LOVE', 'ダンナーベースのメカマンたちは毎日大忙し。父親からお見合いをするように迫られている柊。息子の誕生日も家に帰れない芝草。相変わらずラブラブの林と森本。隣のブロックの女の子に密かな想いを寄せる柳沢。それぞれ悩みを抱えながら、ダンナーベースで一生懸命働いている彼らの、いつも通りの一日がまた始まる…。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1db35e20-febb-4d27-84f9-dee9d6a9c236.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3d0a55b-bada-4e0c-9fa6-40cfb7434571', '58b48b04-9971-4d06-b22c-30478bb9cafb', 18, '60679519', '氷の微笑', 'ロシアのパイロットのエカテリーナとククラチョフは、ヴァルスピナーを乗りこなす名コンビ。だが、彼女に従順なククラチョフは、エカテリーナへの愛を彼女に従うことでしか表現できずにいた。強がりから素直になれないエカテリーナは、そんなククラチョフに辛くあたり、1人で戦闘に出るように命令してしまうが…。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/562e4890-3ddd-4cc7-bf9a-935bc0192f22.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bd03478-1e1a-41c4-b138-83a09267251b', '58b48b04-9971-4d06-b22c-30478bb9cafb', 19, '60679517', 'ジェネシスター暴走!', 'アメリカのパイロット、シャドウとルナは息の合った女性コンビ。しかし、ルナはシャドウに許されぬ想いを密かに抱いていた。ルナの気持ちを知ってか知らずか、シャドウはルナにベースの移籍を勧める。本心を言えず、移籍の話を承諾するルナ。そんな中最後の戦いに臨んだ2人だが、息が合わず合体に失敗してしまう。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/41fafb1e-7d73-4026-ac4d-30806ad22b74.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6b00f0d-0986-45f5-ae45-103908c0bf25', '58b48b04-9971-4d06-b22c-30478bb9cafb', 20, '60679509', '桃花哀歌', 'ガサツで暴れん坊のモウカクと、そんなモウカクを調教師のようにあしらうシュクユウは、中国ダイノベースで活躍するパイロットコンビ。結婚を決めた2人は幸せいっぱいだが、いつものように擬態獣に向かったモウカクの体に異変が起こる。パイロットたちを襲う、謎の“狂体化”の原因は何なのか? そして、2人の運命は!?', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/11d9f31d-9056-44bf-a054-bbd67190099d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('122ffa4f-eecb-4622-aa76-1c049f854036', '58b48b04-9971-4d06-b22c-30478bb9cafb', 21, '60679510', 'ゴーダンナー出撃禁止命令!', '次々と男性パイロットの体に起こる“狂体化”現象。そのため、男性パイロットたちには出動禁止命令が下る。戦えないもどかしさと、ゴーダンナーの代わりのパイロットに静流が抜擢されたことにショックを隠しきれないゴオ。そんなゴオを気にしながらも、杏奈は静流と共に、擬態獣との戦いに出動する。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/626d1308-7c51-4070-ab01-444a527a7a9b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6826588c-979e-420b-af1b-e85bf06a184d', '58b48b04-9971-4d06-b22c-30478bb9cafb', 22, '60679518', '激突! ダンナーVSガイナー', '擬態獣と戦う杏奈と静流の前に、ブレイドガイナーとコスモダイバーが突然現れた。ブレイドガイナーに乗る剣は「擬態獣と戦わせろ」と杏奈たちに攻撃し始め、抵抗する杏奈たちに対してはコスモダイバーに乗ったルウまでもが攻撃を始めたのだった。思いもよらない展開に困惑する杏奈と静流。剣とルウの目的とは…?', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9e22ff6e-a640-47e5-8133-484417d85965.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cf0f892-c9b3-49e0-a3b5-a323d80edb32', '58b48b04-9971-4d06-b22c-30478bb9cafb', 23, '60679514', 'ダンナーベースSOS!', '世界各地で再び大量発生した擬態獣は突然攻撃を止め、一斉にダンナーベースに向かい始めたのだった。ダンナーベースでは最終警戒態勢が発令され、杏奈、静流、ミラが擬態獣の群れに立ち向かった。次々に現われる擬態獣がダンナーベースを襲う。あまりの数の擬態獣に苦戦する杏奈たちを前に、ゴオは出動を決心するが…。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3a6843ea-ca44-408a-a05d-3faf26139626.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecca595b-c2b8-468b-8a40-fbfa72674999', '58b48b04-9971-4d06-b22c-30478bb9cafb', 24, '60679512', '死闘の果てに', '進化した擬態獣は融合獣となり、互いに融合を繰り返していった。そして、さらにすべての個体を統合する存在である進化獣となっていた。次々に擬態獣を体に取り込んでゆく巨大な敵に苦戦する杏奈たちのもとに、世界のパイロットや、復活したあの男が集結した。', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fb7abcab-d857-4a83-92c8-2463b829100e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32c7be8c-8fcf-463d-830d-c4111f620ac8', '58b48b04-9971-4d06-b22c-30478bb9cafb', 25, '60679520', '永遠のふたり', 'ついにラビット･シンドロームを発症してしまったゴオ。凶体化したゴオは、さらにゴーダンナーツインドライブモードと融合し、新たな姿へ変化を遂げる。ゴオに必死に呼びかける杏奈。そんな中、ミラはある作戦を決行するためネオオクサーへ向かう。ゴオは人類最大の敵となってしまうのか? そして杏奈は無事なのか?!', '2016/03/03 12:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/66ff8c92-d986-4544-8be1-d2fd3889ccc9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8755b38e-d919-47d7-8174-d49534a4146b', '58b48b04-9971-4d06-b22c-30478bb9cafb', 26, '60679521', '来たるべき明日', '【シーズン2 最終話】あれから7年後。ダンナーベースには懐かしい顔ぶれとともに新しいメンバーが加わり、杏奈、ミラたちも新人パイロットとともに戦いを続けていた。一方、霧子たちはラビットシンドロームのワクチン研究を続け、ある特殊な遺伝子を発見していた。眠り続けるゴオは覚醒できるのか? そしてその時杏奈は? 感動の最終回!!', '2016/03/03 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/925798ba-d905-4d04-a0ee-0a42cc3f555f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dca3d3ec-ad00-4a77-8c25-cd38cb1dd775', '神達に拾われた男', '', 'hulu', 'by-the-grace-of-the-gods', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55a355f5-4093-49ed-adec-787f7e9b92b1.jpg?w=331&h=447&p=t', 'hulu', 2020, 3, 1, 'FINISHED', NULL, 115740, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ada8416a-ed0b-4ac6-b631-726f6ece0e17', 'dca3d3ec-ad00-4a77-8c25-cd38cb1dd775', 'hulu-by-the-grace-of-the-gods-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0efee890-c55e-4558-840a-f74821522e9e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd928366-33d7-4ff5-858c-5719317e2747', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 1, '100066611', 'スライムたちとリョウマ', 'ブラック企業に勤める竹林竜馬は39歳で早死。しかし、天界で3柱の神の祝福を受け異世界で少年の体に生まれ変わる。森の中に住むことになったリョウマはスライム研究にのめり込み、いつの間にか1000匹以上と暮らすようになっていた。ある日、森の中で出会ったラインハルト公爵と護衛たちの一人が大怪我をしているのに気付き治癒薬を差し出し家で休むように招き入れるが、公爵たちはリョウマのスライムとの生活ぶりに驚く…。', '2020/10/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0efee890-c55e-4558-840a-f74821522e9e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad2fabb9-4656-47c4-a2d3-ecb5a0ce42db', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 2, '100066765', 'スライムたちと旅立ち', 'リョウマにお礼を伝えるため、公爵は先代当主ラインバッハ、妻エリーゼ、娘のエリアリアたちを連れて再び森へとやってきたが、スライムが合体したビッグスライムとリョウマが契約していることに驚く。ビッグスライムの契約は不可能とされていたのだ。さらに新種のクリーナースライムに目を輝かせるエリアリアは森でそれへと進化するスライムと初めての従魔契約に成功して喜ぶ。ラインバッハに同行を誘われたリョウマは森を出ることを決める。', '2020/10/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32f99af8-22c8-42c3-bd6c-5fc2d1a2b6a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4211e276-2dfe-4d44-9490-5e3407da285a', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 3, '100066960', 'スライムたちと初めての街', 'リョウマはこの世界で初めての街ギムルに着いた。ステータスボード発行のため教会に行ったリョウマは3年ぶりに神たちと再会する。神も忘れていたスライムの可能性をリョウマが切り開き新種に進化させたこと、公爵家もその末裔であるこれまでの転移者のことなどを聞く。そしてエリアリアと一緒にテイマーギルドに登録。従魔がスライムではランクが上がらないので、冒険者ギルドにも加入するためリョウマは戦闘能力試験を受けることになる。', '2020/10/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/374fe1f3-aef5-413a-8719-eb5d000ffe6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b47705e-c441-43e6-b039-576792d25421', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 4, '100067347', 'スライムたちと清掃作業', '冒険者ギルドで受けた初めての依頼はスライムたちと一緒に作業して数時間で完了した。依頼人のミーヤから「ありがとうにゃ」と涙ながらの感謝を受けるリョウマ。報告に戻ると、共同トイレ掃除の依頼を相談される。役所が賃金を下げたため引き受け手がなく放置されているという。リョウマは快諾しスライムたちと翌日からトイレ清掃を始めた。順調に作業は進んでいたが、疫病を引き起こす病原菌が発生していることが判明する。', '2020/10/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/640e9076-c4df-4998-9331-f18716a438f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50e71941-e1fb-401a-aa06-77d7e65d6ced', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 5, '100067926', 'スライムたちとお嬢様の訓練', 'リョウマは、エリアリアと約束した魔法の遊びを教えるため郊外に。魔法を組み合わせシャボン玉を飛ばし水で魚を作って空を泳がせるリョウマと、それをまねて遊ぶエリアリア、見守る公爵家の人々との楽しい時間。リョウマも空間魔法を新たに教えてもらい懸命に練習する…そんな穏やかな一日が過ぎてゆく。翌日、エリアリアの対魔獣実戦訓練を兼ねて、鉱山廃坑に住み着く魔獣の討伐と事前調査に向かう一行。そこで見つけたのは…。', '2020/11/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/461c16e7-1180-42d3-8267-4c91c5c85da4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77968b71-23ad-4eef-b293-3bf1bdc5e063', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 6, '100068553', 'スライムたちと魔獣討伐', '廃坑の大規模な魔獣討伐依頼を受けたリョウマは、ミーヤたちとパーティを組んで参加する。順調に進むかに見えたが、坑道の奥でゴブリンの群れと遭遇し怪我人が出たとの情報が届く。リョウマは、アシッドスライムで酸のプールを作り、ヒールスライムで怪我人を治し討伐を進めるが、予想以上のゴブリンの数に冒険者たちはだんだんと消耗してゆく。そんな時、リョウマは空間魔法で呼び出した残りのスライムをゴブリンの群れに立ち向かわせるが…。', '2020/11/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3ffdc9e-e414-423b-a067-50551df82f4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41d9aba6-f3b9-4b00-8f23-289d068b8a26', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 7, '100069281', 'スライムたちと洗濯屋の開店準備', 'いまのままではダメになると自立を決意したリョウマは、公爵家の人々から離れ、ギムルの街で冒険者として鍛錬に励みたいと訴える。生活費を稼ぐためにクリーナースライムで洗濯屋を始める計画を話したところ、モーガン商会のセルジュはゴブリンの汚れも落とすクリーナースライムに興奮、すぐに開業の協力を申し出る。リョウマは店舗用の土地の斡旋や店を経営できる人材を派遣してもらうことに。こうして開店準備は着々と進んでいった。', '2020/11/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a668430-94d5-48db-8024-4054592243ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c55a5b8-f684-457b-b9dd-784c118e9b36', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 8, '100069768', 'スライムたちと洗濯屋稼業', '開店を控え、お世話になった人々を招待してお披露目会を開くことに。エリアリアたちと料理の準備をするリョウマを、モーガン商会からカルム、カルラの双子姉弟が訪ねる。二人に仕事の手順を説明するが、どうやら戸惑っている様子。やがてパーティが始まった。招待客総勢29名、楽しい会話と時間…その様子を見た二人はこの店で働かせてくださいと改めて申し出る。翌朝、廃坑を見回って店に帰ったリョウマは、店の様子に驚くことになる。', '2020/11/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a0e9c6b-bfd8-49d3-a742-62ce88b41346.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82f3fbf8-1b59-401b-b5a2-4e94b1eb162b', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 9, '100070629', 'スライムたちと新しい同僚', 'スライムによる洗濯代行バンブーフォレストは2日目も大盛況。リョウマは新しい店員を雇い入れるため商業ギルドへ。11歳のリョウマを見ると次々に辞退され、足を骨折しているフェイ、その娘リーリンしか残らなかった。その気配から元殺し屋の素性を見抜くが、店の警備も任せることにする。早速二人を連れて戻りそのまま働いてもらう。忙しく働いてくれるみんなのため、快適に働いてもらえる仕組みをリョウマは考え始める。', '2020/12/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc6fc695-b09a-451a-9634-c3a68e92a6fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbfb84aa-0941-40fb-8ff2-e060e2108cf4', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 10, '100070950', 'スライムたちと新種のスライム', 'リョウマは店をみんなに任せるようになり、セルジュから防水布の追加依頼を受ける。鎧や薬の材料として高値で売れる魔獣グレルフロッグがもうすぐ大量発生し防水服を売る絶好の機会だという。防水布を作るリョウマとスライムたちは、美しい鳴き声を持つ魔獣リムールバードを従魔にするためバイオリン練習をするエリアリアの演奏に聞き惚れる。分裂したり、進化したり、新種と契約したり、リョウマとスライムの穏やかな日々が過ぎてゆく。', '2020/12/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db5a2172-3779-43dc-a951-867231d7b9d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38f4eee8-2d5b-48a7-886d-6209b9241804', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 11, '100071629', 'スライムたちと従魔術の練習', 'エリアリアに誘われ一緒に従魔術を教えてもらうリョウマ。ジャミール家は代々従魔術師の家系、彼らが契約している魔獣の数や強さなどを知り驚かされつつ、契約魔獣との意思疎通ができる「感覚共有」という魔法を教えてもらう。やがてグレルフロッグ大量発生の季節がきた。稼ぎ時だと色めき立つ冒険者、湖はたくさんのリムールバードに埋め尽くされていた。いよいよエリアリアがリムールバードとの契約を試す時がやってきたのだが…。', '2020/12/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/897b4231-0b5b-4b9b-bbdc-3d41918960ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32b4e7b4-c0f8-4cad-ae60-aa78bed1f92b', 'ada8416a-ed0b-4ac6-b631-726f6ece0e17', 12, '100072007', 'スライムたちと新たなる日々', '【シーズン1 最終話】飛び去ったリムールバードを待つリョウマとエリアリア。この季節が終わればエリアリアは王都の学校へ、リョウマは公爵家と別れて自立することになる…お別れを意識した二人のもどかしい時間が過ぎてゆく。そんな二人を優しく見守る公爵家の人々。もじもじするエリアリアとなんだか動揺するリョウマだったが、ちょうどそこにリムールバードが舞い戻ってきた。決心したエリアリアは、深呼吸するとバイオリンの演奏を始めるが…。', '2020/12/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d50884a-ef84-40b0-877e-e17a36483296.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('65a3aaf4-599e-48c9-89ac-20fd5eb7a233', '神達に拾われた男2', '', 'hulu', 'by-the-grace-of-the-gods-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f6c213e-a6a2-4e95-91f1-70fe977c738c.jpg?w=331&h=447&p=t', 'hulu', 2023, 0, 1, 'FINISHED', NULL, 135102, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('29e5e395-70fd-40a0-873a-fe74a2f40dcb', '65a3aaf4-599e-48c9-89ac-20fd5eb7a233', 'hulu-by-the-grace-of-the-gods-2-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/022c9256-3512-4071-a2b4-0afccc321e2b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f072008a-9a19-41aa-8a3f-7da8ee3a1ecb', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 1, '100148673', 'リョウマと新しい計画', '以前と変わらずスライム研究に没頭しながらリョウマが営むクリーニング店「バンブーフォレスト」は今日も朝から大盛況。開店準備を終えたリョウマとカルラが執務室で今後の経営方針について話をしていると、店内から何やら大きな声が…。急いで2人が駆けつけると街のゴロツキたちが洗濯物にあらぬクレームをつけていたようで、暴れだした彼らをすでに用心棒のリーリンが取り押さえていた。これを機に店の防犯対策を見直そうと、リョウマはスライムの力を借りてまずは防犯ガラスを作ることに。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/022c9256-3512-4071-a2b4-0afccc321e2b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b87e26f-85cd-4f26-8369-d828b7f576a1', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 2, '100148674', 'リョウマと防犯訓練', '先日のクレーム騒動に続き、またしても「バンブーフォレスト」の洗濯物に言いがかりをつけるクレーマーが現れる。頻発する騒動についてカルラが調べると、テイマーギルド内で魔獣の強さを重視する主流派と、魔獣との共存を目指す支部長テイラーを支持する反主流派との間で派閥争いが発生しており、テイラーが目をかけるリョウマの店の評判を落とそうと企む者がいるようで…。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02f14a21-6cf7-4a34-a0d9-51981f97c264.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1985dd01-0a4a-4504-9977-c0bc3e06ae90', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 3, '100148675', 'リョウマと看板娘', '2号店出店のためレナフの街を訪れたリョウマ。活気あふれる新しい街での出会いに胸を弾ませながら、紹介を受けたピオロが営むサイオンジ商会へと足を運ぶ。すると、関西弁のような言葉を話す狐人族の娘、ミヤビがリョウマを出迎える。そこへミヤビの父親でもあるピオロも現れ、漫才さながらの軽快な会話を見せるサイオンジ親子。その後、リョウマとピオロは2号店開業の手続きのため、レナフの商業ギルドへ向かう。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a518cb3a-4792-485c-8e31-b0ca742c2365.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('816282c5-0ad7-48db-ab17-892b205cf277', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 4, '100148676', 'リョウマと2号店', 'レナフの草原でスマッシュボアに襲われている冒険者たちと遭遇したリョウマ。見事な戦いぶりでスマッシュボアを討伐すると、彼らは何かお礼がしたいとリョウマに申し出る。冒険者一行に手伝ってもらいサイオンジ商会へ討伐したスマッシュボアを運んだリョウマは、この世界の食材を駆使して生姜焼きと豚汁を模した料理を披露する。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95ec23ca-691c-4dbd-81f9-93f87810597f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('95392599-4075-4ea9-96ca-9cda86a6fcee', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 5, '100148677', 'リョウマと新たな出会い', '2号店の経営も軌道に乗り、冒険者としてのランクを上げるべくギムルのギルドへ相談に訪れたリョウマは、新人受付嬢パエナの紹介で、常人では間に合わない短期間の荷物運搬依頼を引き受ける。運搬先のケレバンは以前、セルジュの話を聞いて興味を持った魔法道具市の開催地だった。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9e5f4cf-8e81-4285-858b-bf92e75b10d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e360052-528d-4e83-8af2-39d374028ddd', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 6, '100148678', 'リョウマと魔法道具市', 'ケレバンの魔法道具市の日、ディノームの露店を訪ねたリョウマはディノームの孫、フェデーレと触れ合い充実したひと時を過ごす。ケレバンを後にしてギムルへ戻ると、炭を食べていたスライムが脱臭や消臭に特化したデオドラントスライムに進化。従業員たちの心配をよそに、リョウマは再び寝る間も惜しんでスライム研究に没頭し始める。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1295db7e-336c-4941-bd1e-9e45bc3f003b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a368c263-934c-4d53-b44e-44f6adc5beb2', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 7, '100148679', 'リョウマと郷土料理', 'エリアリアからの手紙で近々ギムルの街で祭りが開催されることを知ったリョウマ。ギムル出身のドルチェに尋ねると、街が作られた日を祝う創立祭であることを教えてもらう。一方その頃、レナフの2号店ではクリーナースライムが突如分裂を始める。急いで駆けつけたリョウマは、スライム研究者のコーキンに状況を確認すると、大量のクリーナースライムと従魔契約を交わす。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8601af64-c96c-4701-b9a6-64ea7f2c959d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e74976c-ff0c-4ad4-8989-7c7b276a7d8a', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 8, '100148680', 'リョウマと旅芸人', '従業員たちと創立祭への出店準備を進めていたリョウマは、巣穴を掘ることで交通の妨げとなる魔獣トンネルアントの目撃情報を聞きつける。巣穴の捜索依頼を引き受け草原へ向かうと、防具の材料を入手するべくトンネルアントの討伐任務にあたっていたベック率いるスラム出身の子どもたちと出会う。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb139fe2-66ef-4588-b2ec-562d1b25342e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28234a0d-45dc-484d-b57d-f9f4e5fd7fd1', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 9, '100148681', 'エリアリアと新しい仲間たち', '王都の学園に来て1ヶ月が経ったエリアリアは真面目に授業を受けていた。だが、その学園生活は退屈そのもの。そんなエリアリアに伯爵家出身のミシェルが声をかけ、2人は似た境遇からか意気投合。ミシェルの研究対象である錬金術について話を弾ませていると、そこにミヤビが現れ、リョウマから託された伝言をエリアリアに伝える。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cea5443f-a610-485c-9656-0f2f74868dfb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8f56102-2020-4a0b-b73c-760dd54f4ba4', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 10, '100148682', 'リョウマと空飛ぶスライム', '閉店後の「バンブーフォレスト」で創立祭の屋台の準備を進める中、ウォーガンからリョウマに新たな観光名所、闘技場を建設する木材となる木の魔獣トレントの素材採取依頼が舞い込む。アサギ、ミーヤたちとともに討伐へ向かったリョウマは軽快にトレント討伐をこなし、ひと時の休憩中に飛行能力を持つフラッフスライムと遭遇する。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d720cfe5-79fc-4e35-b536-52844da623d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('426a11f1-b5c5-4f7c-a87d-2ac098a32a3a', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 11, '100148683', 'リョウマと慌ただしい日々', 'トレントの素材採取を終えギムルへ戻ったリョウマ。街では至るところで創立祭の準備が進められ、セムロイド一座の公演予定地では見事な舞台が完成しつつあった。「バンブーフォレスト」も着々と屋台の準備を進めていたが、まだ飲み物のメニューが決まっていないという。リョウマは以前ジェーンの村から大量の麦が送られてきていたことを思い出し…。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af9ef4ec-878b-4a40-8be3-9ef7cfcfa530.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6dc82b10-46ca-4afe-a608-8d0ab5b19cbf', '29e5e395-70fd-40a0-873a-fe74a2f40dcb', 12, '100148684', 'リョウマとギムルの街', '【シーズン2 最終話】いよいよ迎えたギムルの創立祭当日。セムロイド一座の公演も大盛況で、彼らの楽曲を収めたオルゴールや麦茶をはじめとするリョウマが手掛けた品々も大好評。「バンブーフォレスト」の面々が忙しく屋台の業務に専念する中、レナフの2号店の従業員たちも応援に駆けつける。リョウマはこれまで出会った仲間たちと創立祭を満喫する。', '2023/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/378e276a-25cb-4b31-9e3b-e06c8087a7ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('693c5098-7a0c-4e7f-8b18-3ec19e104421', '神椿市建設中。', '', 'hulu', 'kamitsubaki-city-under-construction', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9908845-661c-41ab-89fd-b95093167aa4.jpg?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 173335, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('43d28f8e-3b87-458e-a358-10c680b406c2', '693c5098-7a0c-4e7f-8b18-3ec19e104421', 'hulu-kamitsubaki-city-under-construction-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/958c7d04-9ddb-4660-b6c5-7ed68f2ad3ef.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60ea7f3c-abed-4a24-84c9-bfecc7513b05', '43d28f8e-3b87-458e-a358-10c680b406c2', 1, '100232492', '魔女の娘 -Witchling- 後篇', '魔女の娘となった化歩は仲間と共に戦いの日々を過ごしていた。そんなある日、同じ「魔女の娘」である夜河世界が、未来視の能力によって神椿市に危機が迫っていることを察知する。その直後、実際に参番街にテセラクターの大群が発生する。', '2025/07/11 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/958c7d04-9ddb-4660-b6c5-7ed68f2ad3ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe5e7229-d3a6-4df6-9745-2c59f21c71d5', '43d28f8e-3b87-458e-a358-10c680b406c2', 2, '100232986', '浄化の歌 -Song of purification-', '神椿市を護る結界装置、VALISがテセラクターによって突破される。このままでは神椿市民が全滅してしまうことを危惧した復興課長は、VALISの復旧を急ぐ。此処は新しい結界装置を受け取るために離脱。夜河世界は、かつて自分が保護されていた「ヰ世界救済教団」にテセラクターが迫っていることを未来視で察知し、単独で救出に向かう。', '2025/07/18 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10bde384-97f2-4653-b206-7afc6dd62a91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b55b143a-8657-4884-9587-9a3b441aa26c', '43d28f8e-3b87-458e-a358-10c680b406c2', 3, '100233488', 'フラグメント -Energy of will-', 'VALISの動力源が「魔女の素養者」と呼ばれる生きた人間であることを知った魔女の娘たち。復興課のやり方に納得できない彼女たちは、自らの存在意義を見つめなおすことになる。一方、化歩たちの様子を見て、そのもやもやを知るために意外な行動をとる復興課長だったのだが……。', '2025/07/25 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11c90838-6be6-4ee1-95de-837fa058397e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4e7d985-3975-411e-b0a5-a0d968d40571', '43d28f8e-3b87-458e-a358-10c680b406c2', 4, '100234055', '悪意 -Malice-', '復興課長が失われたことで監視機能が弱まった魔女の娘たち。それでも市民を護ろうと奔走するが、Qの発生件数は増加の一途をたどる。市内では、行方不明事件に関するうわさが広まり、人々は疑心暗鬼に駆られていた。', '2025/08/01 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4dc61d46-7392-40f0-ad74-327654650b36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f009d5c-2253-49df-a79b-347122d8f9a7', '43d28f8e-3b87-458e-a358-10c680b406c2', 5, '100234646', 'ファミリア -Familiar-', 'セントラル駅前で発生したQから人々を救助した此処たち。だが、市民たちは逆に彼女たちがこの連続行方不明事件の犯人だと思い込んでしまう。街全体が敵になったと悟り、魔女の娘たちは身を隠すことを決めるのだった。', '2025/08/08 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3aa41ef2-68d4-4c3a-b4a9-ec7c0bfc508f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d475fe69-c552-451d-bdd5-46a25a9b843a', '43d28f8e-3b87-458e-a358-10c680b406c2', 6, '100235109', '記憶の卵 -Piece of memory-', '取り戻した記憶から、自分がひとつ前の神椿市からやってきたことを仲間たちに告げる此処。「フェノメノン」と呼ばれる神椿市の再生現象。くーげるが残した記憶の卵から、かつて何が起きていたのかを魔女の娘たちは知ることになる。', '2025/08/15 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa477d2c-bf4c-4a91-9a62-ab5761b9e28f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee37db18-0b54-45ea-8e92-24c277bc97a6', '43d28f8e-3b87-458e-a358-10c680b406c2', 7, '100235418', '現象 -Phenomenon-', 'ファミリアたちはフェノメノンで巻き戻らず、繰り返される神椿市をすべて見てきた、ということを知らされる魔女の娘たち。彼らから伝えられたのは「まくすうぇるが起こす二度目のブラックアウトは必ず7月31日に起きていた」という事実だった。', '2025/08/22 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61ebbf33-5069-4872-8fb8-816b9bc117e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e9b8e02-59ad-4b05-b09e-2dbcaa794e0c', '43d28f8e-3b87-458e-a358-10c680b406c2', 8, '100236023', 'ブラックアウト -Beginning of the end-', 'この世界はすべてが作り物。まくすうぇるの告げる衝撃の事実を知り、化歩に異変が起きる。狸眼や世界、派流、此処はそれぞれこのの事実にどう向き合うのか。魔女の娘たちに動揺が広がる中、二度目のブラックアウトが迫る。', '2025/08/29 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b945dbf-d48a-4de0-80c6-1dddf2f6b472.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2b16f5e-2e62-4dc8-a8b3-f9051f18b3fe', '43d28f8e-3b87-458e-a358-10c680b406c2', 9, '100236727', '欲望 -Desire-', '二度目のブラックアウトが始まり、あぐにとあねもすは戦闘不能に。絶望的な状況に追い込まれ、派流はテセラクター化し「かるら」となった。一方、神椿市営団地で戦う此処と狸眼。らぷらすとはすたーが必死の防戦を行うが、化歩は動かない。魔女の娘の想いの力は弱まり、徐々に追い込まれていく。', '2025/09/05 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/225b31e1-2cf7-416a-950e-0c4d17e262c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ec85d32-7794-4984-97b1-e315409d1568', '43d28f8e-3b87-458e-a358-10c680b406c2', 10, '100237728', '仮想と現実 -Artificial real-', '1325巡目。神椿市は魔女の娘の歌によって滅び、第壱論理界には静寂が訪れた。まくすうぇるの狙った「魔女の娘の歌によって滅ぶこと」とは何を意味するのか。', '2025/09/12 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14f979c3-53a9-4065-b04c-68b8438e617b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bce6f099-656e-4837-b5f3-fb65376544f6', '43d28f8e-3b87-458e-a358-10c680b406c2', 11, '100238279', '再生 -Regenerate -', 'はじまりの魔女ソフィアの力で、「次元の狭間」へと別々に送り出された魔女の娘たち。それぞれが、これまでのこと、これからのことに向き合う。', '2025/09/19 02:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cfc20bf4-1832-4ad4-82ec-9d32d9a43048.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e0c22d9-f752-451e-afac-4c78daeb8d65', '43d28f8e-3b87-458e-a358-10c680b406c2', 12, '100238960', '神椿市建設中 -Under construction-', '【シーズン1 最終話】まくすうぇるは浄化され、神椿市には平和が戻った。まくすうぇるが溜め込んでいたフラグメントに魔女の娘が干渉し、人々を取り戻せたかに思えたが、復活できたのは一部の人々だった。そんな中、あぐにのちょっとした言葉から、狸眼がとあるアイデアを思いつく。', '2025/09/26 00:30:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14e07c9d-af5f-48e3-8a2c-2f4927ee37b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a969f4b3-c3f6-4b4f-a9af-b282638574f0', '神無き世界のカミサマ活動', '', 'hulu', 'kaminaki-sekai-no-kamisama-katsudo', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f08159cd-8e66-47f8-9c77-cc07cd7091dd.jpg?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 148048, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 'a969f4b3-c3f6-4b4f-a9af-b282638574f0', 'hulu-kaminaki-sekai-no-kamisama-katsudo-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2914668-fc9b-4ab6-b2eb-da31e742bd7b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a351b34-0315-4ac8-84dd-73409f4add3b', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 1, '100143140', 'カケマクモカシコキ ミタマノオホミカミ ハラヒタマヘキヨメタマヘト ミタマノミコト カシコミカシコミマヲス', 'あやしげな宗教団体「神地崇教」の教祖の息子･卜部征人は無茶な修行中に命を落とし、異世界転生した。そこは「神」や「宗教」の概念がない、征人にとって理想の世界だったが――!?', '2023/04/13 00:30:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2914668-fc9b-4ab6-b2eb-da31e742bd7b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e823978f-fb4f-4c37-a573-fc3c9c7a3260', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 2, '100143492', 'カケマクモカシコキ ミタマノオホミカミ クスシクタヘナルミタマノフユニヨリテ  コノウツシヨニアレイデタルミニシアレバ ヨロヅノモノツクリタマヒキ ミタマノミコト キコシメセト カシコミカシコミマヲス', 'アルラルとシルリルを救ったことで活気を取り戻すカクリの面々。だが、皇都側が事件の調査に乗り出したことを征人は耳にする。全能神であるミタマの力があればどうにかなると高を括る征人だが……。', '2023/04/20 00:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b55fded9-1669-4597-a4c2-8e883ea9c9a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7d1e66e-b72c-4f27-92ab-ef571b8a56ca', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 3, '100144392', 'カケマクモカシコキ ミタマノオホミカミ タカアマハラノツカサニマシマシテ モロモロノマガゴト マガツヒ ツミケガレヲ ハラヒタマヘキヨメタマヘト オホツチノモトツカミ ミタマノミコト キコシメセト カシコミカシコミマヲス', 'ミタマの力で元の世界に戻ってきたベルトランは、性別が女性に変わってしまい、皇都へ戻るも別人として門前払いを食らってしまう。行き場を失ったベルトランに対し、征人は優しく手を差し伸べるが――!?', '2023/04/27 00:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/403198c0-448d-4ad5-840e-108dd87a4a1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82d26885-be8f-4f7e-b1f4-244bd12320bd', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 4, '100144674', 'カケマクモカシコキ ミタマノオホミカミ ウツシヨヲシメシタマヒ ハジメモナクヲハリモナク テンノシチヨウクヨウニジュウハッシュクヲキヨメ チノサンジュウロクジンヲキヨメタマヘト アメツチノ ミタマノミコト キコシメセト カシコミカシコミマヲス', 'コンバインに水道･電気といった近代設備をミタマの力で生み出し、カクリの文明を飛躍的に発展させていく征人。目論見通りに信者を増やしていくが、そこに皇都からの刺客である謎の幼女が現れる。', '2023/05/04 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad87a816-04a9-4d81-8eb4-b3f26e5bda0a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb0eb8ee-846c-4c2f-8d3c-acd28a33592a', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 5, '100145637', 'カケマクモカシコキ ミタマノオホミカミ ヨロズノモノ ツクリタマヒキハ ロクコンショウジョウニシテ アメツチノヨロズモノトドウタイナルガユヱニ カカルトヨアシハラミズホノクニニスマワセタマヘト マヲスコトノヨシヲ オホツチノ ミタマノミコト キコシメセトカシコミカシコミマヲス', 'クレンは自らを「ロキ」と名乗り、アルコーンの一柱であると打ち明ける。そして、ロキは征人とミタマを皇帝の元へと連れ出す。そこで待ち受けていたのは、この世界を支配する「超科学」の存在で――!?', '2023/05/11 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/435c4def-528f-4ef4-85eb-c467420068ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cd2b972-cc1c-471e-b8c1-3d9e1b407ea2', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 6, '100145968', 'カケマクモカシコキ ミタマノオホミカミ トコヨノナホヒハ アマハラニアリテハ ヒノミクニツキノミクニホシノミクニ オホツチニアリテハ アヲヒトクサヲハジメ イキアルモイキナキモ ヨニアリトシアルモノノカギリ トコヨノオホカミ ミタマノミコト キコシメセトカシコミカシコミマヲス', '皇国の支配から解放され、さらにアータルと同盟を結んだミタマ教団は、順調に信者を増やしていく。そんな中、征人は「神」を自称し、1万人規模の大教団を率いるアルコーン「ダキニ」の噂を耳にする。', '2023/05/18 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6d706c5-4313-443f-8da1-62c1dd724d04.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ac84ee2-e8dd-4c24-87bf-10ae894ff90f', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 7, '100146717', 'カケマクモカシコキ ミタマノオホミカミ モトツミココロノマニマニ ウムシイデ ウシハキマモリ サキハヘタマヘルミイサヲノ オホキヒサシキヒロキアツキ オホムウツクシミヲカゞフリテ コノウツシヨニ アラムカギリハ ヨロズノモトツヒトツカミノ ミタマノミコト キコシメセトカシコミカシコミマヲス', '教団からの解放を望むリシュの協力により、ダキニ教団への潜入に成功した征人たち。リシュの影響力を利用し、信者の分断を進める征人だったが、ダキニにその動きを感付かれ、裁判にかけられてしまうことに!?', '2023/05/25 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99fcc714-8e67-47eb-aef2-184924c6418b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a0b30e1-fd8c-4f7e-9a91-255abd3faec7', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 8, '100148311', 'カケマクモカシコキ ミタマノオホミカミ マガツヒノタメニ ケガシヤブラレルコトナク キノエキノトヒノエヒノトツチノエツチノトカノエカノトミズノエミズノト ヒフミヨイムナヤコト ニノオトフルヘユラユラトフルヘ カクイノリセシコトノヨシヲ オホクニノモトツヒトツカミノ ミタマノミコト キコシメセト カシコミカシコミマヲス', '粛清人の襲撃を受ける征人たちだが、そこに信者数を増したアータルが圧倒的な力で救援に現れる。征人の作戦は、アータルに信者を集中させることで、ダキニ教団を武力制圧することだった!', '2023/06/08 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76e178a3-9a7a-46c9-b6cb-c10f8286bce1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c933b69-297e-42ad-aa90-f307784f632b', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 9, '100148985', 'カケマクモカシコキ ミタマノオホミカミノ ナホヒココロニ ツミケガレアヤマチアラシメズ ヨロズノモノゝタグヒナリイデンカンタカラハ イハユル オキツカゞミヘツカゞミヤツカノツルギイクタママカルガヘシノタマタルタマミチカヘシノタマオロチノヒレハチノヒレクサグサモノゝヒレトイフ ミタマノミコト キコシメセト カシコミカシコミマヲス', 'ダキニ教団の信者を取り込むことに成功した征人たち、だが、自分たちのカクリへと戻ると、そこは外獣によって破壊され、無残な姿となっていた。さらに外獣を操るアルコーン「ガイア」と名乗る幼女が現れ……!?', '2023/06/15 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4392ecc9-f8f1-4b04-8a4b-4002012892ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67a1566f-856f-4337-ba90-b73f60ac5653', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 10, '100149592', 'カケマクモカシコキ ミタマノオホミカミ アラタマニギタマニ モロモロノフジョウヲミズ ツクシテウムコトナク ツトメテオコタルコトナク ウヤマヒカシコミモツカヘマツルサマヲ タヒラケクヤスラケクキコシメシテ ソレカミハユヰイツニシテミカタナシ キョニシテレイアリ アメツチヒラケテコノカタ トコヨノオホミカミノ ミタマノミコト キコシメセト カシコミカシコミマヲス', 'アルラルたちのバンド活動により、カクリに熱狂的なオンガクブームが巻き起こる。するとミタマのパワーが増加し、神の力は信者数のほか、信頼の強さや結束力によっても変化することを発見した。この検証から、征人はガイアの奇妙な行動に疑いを持ちはじめ……。', '2023/06/22 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf2cfd9a-313d-43a9-8832-2d152ef176d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2133427-3b66-4cca-a212-5f12b9a95d99', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 11, '100151386', 'カケマクモカシコキ ミタマノオホミカミ イニシニ オホヤシマアメツチヒラケノハジメ クニツチノウカレタゞヨフコト タトヘバ ナホミヅノウヘニウカベルアブラノゴトトキニ アメツチノナカニヒトツノモノナレリ スナハチカミトナル ミタマノミコトト マヲシマツル ヨロズノモノヲ  ツカサドリタマヒテ アヲヒトクサヲ ヨウイクシタマフ ヨロズモトツ ミタマノミコト キコシメセト カシコミカシコミマヲス', 'ガイアの新たな信者獲得を防ぐため、征人はガイアと子供たちを引き離そうと画策するが、ガイアが作り出した最強の外獣･テュポーンが襲いかかってくる。必死に逃げるも、その道中で征人はテュポーンに食べられてしまい……。', '2023/07/06 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c35f3a3-3a74-42b5-8699-0620ee270767.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4bb8ff9d-5e12-4464-9a30-03c336457946', '1d29e3e7-36fb-49b2-84c7-55c9e5ba05fe', 12, '100151900', 'カケマクモイトモカシコキ ミタマノオホミカミ コノカミドコニ マセマツル カケマクモアヤニカシコキ オホカミノオホマヘニ カシコミカシコミモマヲサク オホカミノ ヒロキアツキミタマノフユニヨリテ マガカミノマガゴトナク スコヤカニナリハヒノコトゴトニ イソシミツトメルヲモチテ アメツチノカムワザニタガハシメズ ヒラケヨニオクレシメズ クサグサノワザワヒナク ヨノマモリヒノマモリ メグミサキハヒタマヘト ミソラハルカニヲロガミマツラクヲ タヒラケク ヤスラケク キコシメシテ イマモユクサキモ イヤトウニイ…', '【シーズン1 最終話】テュポーンの体内にいる征人たちを助けるため、アータルは神の立場を放棄してミタマへ信者を集中させた。この作戦が功を奏し、ミタマのパワーがみるみるうちに増加していく。力が溜まったミタマは、ガイア撃破へ力を尽くす―!', '2023/07/13 00:30:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23e34115-4325-4891-862f-dbc9f850720f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b1ff174e-5766-4bc6-ad0f-dd13496ef974', '神様になった日', '', 'hulu', 'the-day-i-became-a-god', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fd326a3-6af8-4099-b617-11c203ff30d2.jpg?w=331&h=447&p=t', 'hulu', 2020, 3, 1, 'FINISHED', NULL, 118419, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('728e7c1c-a99f-45c7-90fd-179503356828', 'b1ff174e-5766-4bc6-ad0f-dd13496ef974', 'hulu-the-day-i-became-a-god-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7db77dc3-6505-4674-a8ae-ecc182709945.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f48b77e-bd6c-4180-99a4-06efb01fee9c', '728e7c1c-a99f-45c7-90fd-179503356828', 1, '100066704', '降臨の日', '高校三年生の成神陽太は、受験勉強の息抜きに公園でバスケをしていたところ、修道服を着た少女･ひなと出会う。ひなは陽太に「我は全知の神である。」と高らかに宣言し、そして「30日後に世界が終わる。」と告げる。陽太はひなを信用していなかったが、ひなが起こす“奇跡”を次々と目の当たりにすることになる。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7db77dc3-6505-4674-a8ae-ecc182709945.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dd16a81-ef2b-4fba-b922-a8ba45cae16a', '728e7c1c-a99f-45c7-90fd-179503356828', 2, '100067030', '調べの日', 'ひなが遠い親戚であることを母･時子から聞かされた陽太は、成神家にひなを居候させることをしぶしぶ納得する。そしてひなは、映画制作をきっかけに片想い中の幼馴染み･伊座並との距離を縮めるよう、陽太に助言し――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/543b57b2-62c3-43eb-89f9-b3ca555f4375.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0291c7db-79ac-4598-96e7-6a8647dc6f61', '728e7c1c-a99f-45c7-90fd-179503356828', 3, '100067378', '天使が堕ちる日', '空の所属する映研部OGの神宮司ひかりは、母が経営するラーメン屋を手伝っている。しかし、ラーメン屋の経営は傾いており、借金の取立て屋から逃げる日々を送っていた。神宮司を心配する空を見かねて、ひなはラーメン屋を立て直すよう陽太に命じる。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d50449cb-475f-4390-be5b-70e698a77b4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec9c3247-6118-4fec-a9a9-27438f037afe', '728e7c1c-a99f-45c7-90fd-179503356828', 4, '100068310', '闘牌の日', '陽太が美人弁護士･天願賀子のファンであることを知ったひなは、陽太の名前を使い、天願が主催する麻雀大会「リベルタス杯」のネット予選で勝ち抜き、本戦への出場権を掴み取る。麻雀初心者であるにも関わらず、陽太は本戦に挑むことになり――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df4d79df-fc5e-42c6-9da5-2b933027bc53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1715de0-bf67-4643-bd0c-1920424d5506', '728e7c1c-a99f-45c7-90fd-179503356828', 5, '100068708', '大魔法の日', '伊座並杏子は、幼い頃に母親を亡くしていた。母の命日が近づき、父を墓参りへ誘うが、仕事を理由に毎年断られてしまっていた。そんな伊座並家を心配したひなは、陽太と伊座並家に向かい、何とかして伊座並の父を外出させようと画策する。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e4942b6-b741-438b-a587-6a6df7b1f11a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('075ca20b-08ae-4ec9-b0c0-ba9751debd31', '728e7c1c-a99f-45c7-90fd-179503356828', 6, '100069282', '祭の日', '近所の神社で夏祭りが開催されていることを知ったひなは、連れていくよう陽太に懇願する。さらに、「夏祭りは大勢で楽しむもの!」と言い張り、伊座並や阿修羅たちを誘うことを提案する。気乗りしない陽太だったが、結局夏祭りの誘いの電話をかけることになる。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50e1804b-b97b-41df-9b8c-c49eb6387afa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be2eb14a-a56d-49cd-be5b-5dec81c6b35d', '728e7c1c-a99f-45c7-90fd-179503356828', 7, '100069748', '映画撮影の日', 'ついに映画の脚本を完成させた空は、撮影に向けてスタッフキャストを集めるよう陽太にお願いする。陽太はメンバーをかき集め、伊座並や阿修羅、神宮司、天願など大勢のメンバーが参加することに。そして、空が配役を検討した結果、ひなと陽太がメインキャラクターを演じることになり――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9876917-cdf1-48c2-a181-697890f8b78c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e050c66-5df3-43d9-9b11-3550f587c0d1', '728e7c1c-a99f-45c7-90fd-179503356828', 8, '100070549', '海を見にいく日', '映画撮影は順調に進み、夏休みも残りわずかに。ひなが言う“世界の終わり”が近づくにつれ、陽太はひなが急に成神家から居なくなってしまうのではと不安を感じるようになる。意を決して、ひなについて両親に尋ねることにするが……。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43c7f08d-61bb-4475-98d4-e6e0ad43afb8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f5a30ac-a330-4aca-8f4c-df29fc758553', '728e7c1c-a99f-45c7-90fd-179503356828', 9, '100071159', '神殺しの日', '興梠博士の目的を突き止めた央人だったが、研究結果までは突き止めることができなかった。平凡な高校生である陽太が、ラーメン屋を再建したり麻雀大会で優勝したりと、不自然な行動を繰り返していることに違和感を覚え、央人はひなが関与しているのではと疑いを持ち始め、ついに“ある秘密”に辿り着く。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/adf1e6b1-9de0-4146-a8fa-11b2fee0de41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69866d2b-a59a-44ea-9245-8914eb6a7c99', '728e7c1c-a99f-45c7-90fd-179503356828', 10, '100071728', '過ぎ去る日', 'ひなが連れ去られ、必死で探す陽太たちだったが、何の手掛かりも見つからないまま、2学期が始まってしまう。虚無感に苛まれている陽太の前に、央人が現れる。央人は陽太と次第に仲良くなり、阿修羅や伊座並とも一緒に過ごすようになるが……。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28067d8b-81c1-4a43-9122-5003045045f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ce5248f-0a39-43f9-b815-8acc1b803117', '728e7c1c-a99f-45c7-90fd-179503356828', 11, '100071945', '遊戯の日', 'ひなを取り戻すことを決意した陽太は、央人の協力の元、ひながいる養護施設に潜入する。ついに再会を果たすが、ひなは完全に心を閉ざしていた。それでもひなの中に、「あの夏、一緒に過ごしたひな」がいることを信じて、陽太は必死に向き合っていく。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2226354-d19b-4c71-9e42-db5fb19d0c58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c822b62-6e60-4144-95b0-be312278b216', '728e7c1c-a99f-45c7-90fd-179503356828', 12, '100072357', 'きみが選ぶ日', '【シーズン1 最終話】潜入が発覚し、施設から退去することになった陽太。司波からひなが別の施設に移ることを告げられ、何とか頼み込んでひなと過ごす最後の時間をもらう。「一緒に過ごしたあの夏」の思い出話をしながら、陽太は「一緒に暮らしたい?」とひなに問いかけ――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99cd2668-3b11-409b-b054-fefb66d7e601.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6a3ade09-fc75-470e-ba42-ef5b6224ce2a', '神様はじめました', '', 'hulu', 'kamisama-kiss', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0937c43-5183-47d5-b546-e37357f0b9c7.png?w=331&h=447&p=t', 'hulu', 2012, 3, 1, 'FINISHED', NULL, 14713, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('64fc1e3f-572c-4068-ad92-8821bf61b723', '6a3ade09-fc75-470e-ba42-ef5b6224ce2a', 'hulu-kamisama-kiss-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/067bdf6d-4244-4161-8fee-eb0dcdb09afd.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4045975f-0985-44f1-a771-22f443f06104', '64fc1e3f-572c-4068-ad92-8821bf61b723', 1, '100090960', '奈々生、神様になる', '父親の借金のせいで住む家をなくした桃園奈々生は、公園で怪しげな男･ミカゲから家を譲られる。しかし行ってみた先は廃神社。実はミカゲは土地神で、奈々生に神の印を与え社を譲ったのだった。そこに居たのは狐の妖怪･巴衛。巴衛はミカゲに仕える神使であったが、新しい主の奈々生を受け入れようとはせず出て行ってしまう。残された奈々生は巴衛を捜すため、あやかしの世界に足を踏み入れることになり…。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/067bdf6d-4244-4161-8fee-eb0dcdb09afd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c165931-cbc7-4b47-9c1e-3a70d6ccc668', '64fc1e3f-572c-4068-ad92-8821bf61b723', 2, '100090961', '神様、ねらわれる', '巴衛が神使になり、ミカゲ社で暮らしはじめた奈々生。ある日、奈々生の通う高校に超人気ビジュアル系アイドル･KURAMA (鞍馬) が転入してくる。奈々生は鞍馬見たさに学校に行こうとするが、神の印のせいで妖怪に狙われやすいため巴衛に止められる。それを押し切り学校に行った奈々生だったが、鞍馬に冷たくあしらわれすっかり幻滅。しかし、なぜか鞍馬の方が奈々生に興味を持ちはじめ…。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/991eb51f-7fa2-411c-8e23-4cd563b8af11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5153ecf-7d2b-484a-98ca-e3acf59209ed', '64fc1e3f-572c-4068-ad92-8821bf61b723', 3, '100090962', '神様、縁をむすぶ', 'ミカゲ社に、ミカゲと友好関係にあった沼皇女が挨拶にやってくる。巴衛は人間の娘が土地神になったと知られてはまずいと考え、奈々生を会わせずその場をやり過ごそうとするが、奈々生が部屋に入ってきて計画は丸つぶれ。しかし、沼皇女からは意外な相談を持ちかけられる。人間の男の子に恋をしてしまい縁を結んで欲しいというのだが、妖怪と人間の恋は禁忌。巴衛は一蹴するが、沼皇女の恋する姿を見た奈々生は協力に乗り出す。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99fbb8da-7343-4e63-b5f5-171cb613a3bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9aeb632f-f4ec-4aff-9811-21310c95c50a', '64fc1e3f-572c-4068-ad92-8821bf61b723', 4, '100090963', '神様、拐かされる', '学校に迷い込んだ白蛇を助けた奈々生。その時、白蛇からの一方的な婚約の印を腕に付けられてしまう。巴衛は白蛇から奈々生を守るため、人間に化けて奈々生のクラスに転入することに。しかし2人が少し離れた隙に、奈々生は白蛇の化身･瑞希に攫われてしまう。瑞希はヨノモリ社の神使で、奈々生を自分の社に連れていき求婚をする。奈々生はそれを断り帰ろうとするが、歩いても歩いてもヨノモリ社に戻ってしまい抜け出せず…。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2818ac79-b6c3-4754-896b-e1dd4e710c44.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d8e3384-32fe-48dd-b77a-3045c4a42a71', '64fc1e3f-572c-4068-ad92-8821bf61b723', 5, '100090964', '神様、家をうしなう', 'ミカゲが神の印を奈々生に譲ったことを知った雷神･鳴神姫が、印を奪いにやってくる。それを阻止しようとした巴衛だったが、打出の小槌で体を幼児にされてしまい、奈々生も神の印と社を奪われてしまう。しかも巴衛は体が小さくなったことで熱を出し倒れてしまった。巴衛を元に戻すには、鳴神姫の神使になるという条件をのまなくてはならない。そんな巴衛を抱え路頭に迷っていた奈々生の前に、鞍馬が現われて…。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fabc5b8-1bab-420f-b30d-5c423b16ff40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('448d89b7-a97c-48d0-b8cf-a47f8066f2d2', '64fc1e3f-572c-4068-ad92-8821bf61b723', 6, '100090965', '神様、風邪をひく', '神と神使の再契約のキスをした奈々生と巴衛。その日から巴衛を見るとドキドキしてしまう奈々生。巴衛は朝食を食べている奈々生が熱を出していることに気付く。しかし出席日数が足りない奈々生は、巴衛が止めるのも聞かず学校に行こうとする。すると虎徹の提案で、巴衛が奈々生に化けて代わりに学校にいくことに。完璧に化けたつもりの巴衛に、鞍馬が近づいてきて…。一方、巴衛が不在と聞いて、奈々生のもとに瑞希が訪ねてくる。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40eb22f6-c557-4727-9b15-8da24f2f19bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d0b701f-00a1-42b8-baf1-762d403b363d', '64fc1e3f-572c-4068-ad92-8821bf61b723', 7, '100090966', '神様、デートに誘う', '猫田あみから鞍馬に助けてもらったお礼を言いたいと相談をされる奈々生。しかし鞍馬はいつも女子生徒に囲まれているため、なかなか1人になるタイミングがない。そこで白札を使い2人が話せるきっかけをつくるが、それを見た巴衛は妖怪と人間の恋は禁忌と考えているため叱責する。すると今度は後輩の女子生徒から、巴衛と一緒に帰りたいと相談される。2人が一緒に帰れるようにセッティングする奈々生だったが…。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c08cce19-352e-45a4-ac11-636e87472a4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5cb3172-c85b-45ef-a6b2-f8fe196add9a', '64fc1e3f-572c-4068-ad92-8821bf61b723', 8, '100090967', '神様、海へいく', '水族館に行って以来、巴衛と自然に接することができない奈々生。巴衛の態度は変わらないが、奈々生にこれまでのように触れてはこない。元気のない奈々生を見たあみは、奈々生を海水浴に誘う。しかし、巴衛は海に入れない理由があるといい、奈々生を守ることができないと反対するが、結局、瑞希と巴衛も一緒に行くことに。海水浴を楽しむ奈々生たちだったが、あみが溺れてしまい、助けるために巴衛が海の中へ入ることになり…。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72026441-2d67-4a83-b160-46e09db35f93.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03c177ea-4938-4b45-b48c-9a3856f19ff4', '64fc1e3f-572c-4068-ad92-8821bf61b723', 9, '100090968', '神様、竜宮城にいく', '過去に巴衛が奪った龍王の右目を取り戻すため、時廻の香炉で過去に行く奈々生と瑞希。そこで右目を持った野狐の巴衛と出会う。奈々生は巴衛を尾行した民家で、人間の女性･雪路と恋仲であることを知りショックを受ける。巴衛が龍王の右目を盗んだのは、雪路の病を治すためだった。巴衛が去った隙に龍王の右目を盗もうとした奈々生だったが、雪路が苦しみ始めたため、不老長寿の効果があるという右目を雪路に与えてしまう。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba3fc3d4-0ca0-4fdd-a1ed-6be232585cea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b95102af-0486-45e8-9b14-0f2c9a3ec0eb', '64fc1e3f-572c-4068-ad92-8821bf61b723', 10, '100090969', '巴衛、神使になる／神様、合コンにいく', '今より数百年前――。神堕ちと契約し、その契約が果たせなかったため呪を受け瀕死状態にあった巴衛は、土地神･ミカゲと出会う。ミカゲはその呪いの進行を止めるため、巴衛に忘却の暗示をかけ過去を忘れさせた。その後、回復した巴衛はミカゲの神使となったが、社の外では傍若無人な振る舞いでミカゲを困らせていた。神使であることに迷いを感じていた巴衛であったが、次第にミカゲを慕うようになっていく。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7bcf4e8-f316-44dc-a49b-ae1d42fe499c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('542fdde4-8d63-478b-a099-87d61df1cb4a', '64fc1e3f-572c-4068-ad92-8821bf61b723', 11, '100090970', '神使、街にでかける', '奈々生と巴衛は学校に行き、社で留守番中の瑞希は、その不公平さを感じていた。瑞希はテレビに映ったアイドルの鞍馬を見て、人間社会に溶け込む妖術を学ぼうと、鞍馬に会いに街にでかける。人間に慣れていない瑞希は途中、キャッチセールスで高額なシールを買わされたり、怖い人にからまれたり、タクシーを無賃で乗ってしまったりとトラブルをおこす。偶然通りかかった鞍馬に助けられ、一緒に番組の打ち上げに参加するが…。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a99e901-c7db-42df-84e8-005aef640e86.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e82a05c7-7246-42c1-abbf-446154e9cca9', '64fc1e3f-572c-4068-ad92-8821bf61b723', 12, '100090971', '奈々生、神様をやめる', '今日も参拝者ゼロのミカゲ社。実は近くの住人から「お化け神社」「廃神社」と呼ばれ、敬遠されていた。そのことを知った奈々生は、なんとか人に来てもらおうと、ミカゲ社で祭を企画する。巴衛は奈々生では祭事は荷が重いと反対するが、奈々生が自分のために参拝者を増やしたいと考えていることを知り協力をすることに。祭では奈々生が神楽舞を踊ることになり、巴衛の厳しい指導のもと必死で練習する奈々生であったが…。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/831d40b9-5e3f-4a35-b9da-b4821ce8d2cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b58bf1d1-1dd2-46bb-9a52-9b4d82edaf5a', '64fc1e3f-572c-4068-ad92-8821bf61b723', 13, '100090972', '神様はじめました', '【最終話】ミカゲ社に蔓延る瘴気を払うことができず、土地神としての自信をなくした奈々生は、ミカゲ社を出ていってしまう。巴衛と瑞希が街中を必死に捜すも見つからない。そのころ奈々生はもう一度、瘴気を払うことを決心しミカゲ社へ。しかし、どんどん瘴気が濃くなっており、木々は枯れ、まるで廃神社のようになってしまったミカゲ社。奈々生は土地を清めるため、巴衛から教わった神楽の舞を踊る。', '2021/10/16 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79207d2e-e5dd-477b-92d2-26e9cb567aed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f206bb63-a65d-4fce-99b0-0985649c854d', '神様はじめました◎', '', 'hulu', 'kamisama-kiss-2nd', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f00359ff-3666-4388-afce-4664f1ef7c5a.png?w=331&h=447&p=t', 'hulu', 2015, 0, 1, 'FINISHED', NULL, 20801, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b4a6d314-ec3b-46dd-af07-b700fda2d994', 'f206bb63-a65d-4fce-99b0-0985649c854d', 'hulu-kamisama-kiss-2nd-s1', '第2期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61d3b1cb-3f2d-477d-bc1d-cfb2e7b55539.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa38d6b6-0ad7-4e05-874f-1868771eb928', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 1, '100090973', '神様またはじめました', '女子高生ながらミカゲ社の神様になった奈々生のもとに、乙比古が訪ねてくる。全国の神々が出雲に集まって会議を開く『神議り』の召喚状を持ってやってきたのだ。上から目線で参加を進められ、はじめは断る奈々生。しかし、巴衛が失踪したミカゲの影を追う姿を見て、出雲に行けばミカゲの居所を知る神が居るのではないかと考え、神議りに行くことを決意する。乙比古から参加条件として、ある試験を受けることになったが……。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61d3b1cb-3f2d-477d-bc1d-cfb2e7b55539.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d90ea8b9-ada7-4712-8667-d0c39bb1bac4', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 2, '100090974', '神様、出雲へいく', '乙比古の試験をクリアした奈々生は、式神の護と一緒に出雲に行く飛行機のチケットを買いに行く。帰り道、護が奈々生に向けられた強い殺気を感じ取り、人気のない公園に逃げ込むふたり。殺気の主は、神の座を失いもはや化け物へと成り下がった、神堕ちたちであった。人神でありながら神議りに出席する奈々生に嫉妬し、辞退せよと詰め寄ってくる。すると、偶然居合わせた青年が、神堕ちたちに挑発的な発言をしてしまい……。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bcd289b5-d3d8-45be-ba24-6255dfd5bb55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2fd4570-aaf8-429d-b491-8ae10471df21', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 3, '100090975', '神様、黄泉におちる', '神議りの主宰神の大国主から、黄泉への入り口『黄泉比良坂』へ偵察に行って欲しいと言われる奈々生。警備が手薄になる神議りの時期を狙って、妖怪が境界を壊そうとしているらしい。会議に遅刻をした罰として乙比古も同行し、ふたりは黄泉比良坂に向かう。ところが、入り口を塞いでいた巨岩石が真っ二つに割れていた! 一方、留守番を強いられた巴衛はひとりであることをいいことに、社を空けて遊びに行ってしまう。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd81cecf-22e7-4baa-94cb-cc9a26bdcc12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2657e871-4094-4655-abf6-34dd47ec2f60', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 4, '100090976', '神様、黄泉をかける', '霧仁と一緒に黄泉の国に落ちてしまった奈々生は、黄泉国主祭神のイザナミから宮殿に招待される。イザナミは奈々生に黄泉の国を出るように言うが、霧仁は死者であることを見抜き、牢に閉じ込めてしまった。奈々生は霧仁を助けるため、黄泉の住人になったフリをして、イザナミの宮殿に残る。そのころ巴衛の元へ、奈々生が黄泉の国で行方不明になった知らせが届く。巴衛はすぐに黄泉への入り口である黄泉比良坂に向かうが……。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a22e6ad6-01c7-4996-80e6-fb25c2e2bb08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de3879eb-ca11-4874-919f-fb6d349f67fd', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 5, '100090977', '神様、二度目の告白をする', '巴衛の助けにより、黄泉の国から無事に脱出した奈々生と霧仁。しかし、打出の小槌で妖怪に戻った巴衛は、大国主によって牢に幽閉されてしまった。それを知った奈々生は再び神使の契約を交わすため牢に向かうが、断られてしまう。巴衛は「この女はお前のなんだ」と霧仁から言われ、気持ちの整理がつかなくなっていた。奈々生はそれでも巴衛のために何かできることはないかと考え、麻毛理神とある物を物々交換する。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c95cbbd-dc1c-4e42-b807-02de29416eef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53a07959-6a36-4c48-8bc8-d7f6f2cd18ba', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 6, '100090978', '神様、小天狗にあう', '神議りの宴の席で、捜していたミカゲに会うことができた奈々生。しかし、思惑があるミカゲは、巴衛とは会わずに姿を消してしまった。ミカゲから人間と妖の恋が禁忌である理由を聞いた奈々生は、巴衛への気持ちに悩み、出雲からひとりで帰路につくことを選ぶ。地元に戻ると、駅で買い物中の姫美子と遭遇。姫美子は落ち込んでいる奈々生に気付き、「デートをしよう」と誘った。街を散策するうちに笑顔が戻る奈々生だったが……。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b9d9c15-8b4a-4181-a9c3-f45fba679e05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eda34afd-a010-4287-8234-10c6b50e73e6', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 7, '100090979', '神様、鞍馬山へいく', '鞍馬山からやってきた牡丹丸が捜していた真寿郎とは、鞍馬のことだった。鞍馬の父である三代目僧正坊が病に倒れ、今は四代目候補である二郎が御山を仕切っているという。牡丹丸は四代目は鞍馬にと考え、下界まで迎えに来たのだった。跡目を継ぐ気はまったくない鞍馬であったが、牡丹丸の体に二郎につけられた鞭の跡を見て帰省を決意。奈々生と巴衛も万能薬の桃丹を持って鞍馬に同行する。しかし道中、深い霧に包まれてしまい……。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2df69850-b175-41ad-831d-6e05680a0b67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae692650-a862-48b6-a071-c03d0a061ab5', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 8, '100090980', '神様、潜入する', '天狗の里の中心に立っている霊木の万年桜は、僧正坊が病に倒れてから枯れてしまっていたが、奈々生が白札で一時蘇らせることができた。しかし、偶然居合わせた二郎が、奈々生を厳しく叱責する。ここ天狗の里は、女人禁制の里だったのだ。思わぬ形で二郎と遭ってしまい、逃げ帰る奈々生。その夜、身を寄せている翠郎の家に、鞍馬の帰省を聴きつけた兄天狗たちがやってきて、鞍馬に四代目僧正坊になるように詰め寄ってくる。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/022aa5fa-5dcb-4fd9-b0a1-0a4605244398.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8131cd90-b481-42dd-9881-45ccf01fc29d', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 9, '100090981', '神様、ふいうちをくらう', '本家道場のどこかにいる僧正坊に桃丹を届けるため、奈々生は天狗の変装をして護と牡丹丸と共に潜入するが、二郎の結界のせいで僧正坊を見つけることができない。一方、鞍馬は土地神のふりをして、巴衛と共に正式に本家道場に迎えられる。鞍馬は悪酔い必至の下界の酒を二郎に振る舞うが、先に酔いつぶれてしまい、悪巧みも気取られピンチに! しかし、巴衛が奈々生に変化し二郎の酌をはじめると、結界がゆらぎはじめ……。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef2d54b2-2050-42a0-b1ef-b0b2f6180b29.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69e4e94e-e6cd-42a8-b91e-541728aca1b1', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 10, '100090982', '神様、告白される', '退魔結界で二郎の結界を解いた奈々生。夜鳥によって奪われ隠された僧正坊の御魂を、白札を使って探すが、白札が指した方向は行き止まりの壁であった。そこに二郎がやってきて、壁を破壊すると、扉が現われた。それは、17年前に封鎖された、鞍馬山に巣くう雷獣が眠る穴へと続く扉であった。二郎は奈々生に「近づくな」と言い、穴へと入って行く。奈々生も僧正坊の御魂を先に取られてはなるまいと、後を追いかけるが……。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf105340-9a5b-42da-8641-fc62e87f1879.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30b46403-9a10-478a-b5b3-ce457f3b7000', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 11, '100090983', '神様、こどもにもどる', '一年の実りをもたらすという年神の所へ、新しい札をもらいに行く奈々生と巴衛と瑞希。年神の社の入り口には、十二鳥居というそれぞれ名前の書かれた鳥居が立っている。12年ぶりの年神に各々の12年を示すため、ここを通って12年間を振り返らなければならないという。それぞれ鳥居をくぐるが、奈々生だけがいつまで経っても出てこない。巴衛と瑞希はやむをえず奈々生の鳥居に入ると、そこには幼い日の奈々生の姿があった。', '2021/10/16 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1b95cea-97ea-4b58-bcaa-9813c681ac84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a8f4407-6f4c-4102-a9b1-6924a566fd49', 'b4a6d314-ec3b-46dd-af07-b700fda2d994', 12, '100090984', '神様、求婚される', '【第2期 最終話】巴衛たちが見た12年前の奈々生は、幼くして波乱万丈であった。母を亡くし、ギャンブル好きの父は家を空けがちだったが、それでもひとりでたくましく育っていた。その様子を瑞希は見ていられなくなり、奈々生を過去から連れ出そうとするが、逃げられてしまう。そんな奈々生を巴衛は抱き上げ、奈々生を笑顔にするために欲しいものを与え、行きたい所に連れて行く。しかし、時折寂しそうな表情をみせる奈々生に巴衛は……。', '2021/10/16 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67aeddc7-1c54-47c0-a647-733f7de019af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ce5fd43b-faa8-4563-bd23-450b776e74cb', '神霊狩 Ghost Hound', '', 'hulu', 'ghost-hound', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50002202_series_art__338x600_ghost_hound_48cb605a3180712736f6d6a62de7d7c0.jpg?w=331&h=447&p=t', 'hulu', 2007, 3, 1, 'FINISHED', NULL, 2596, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ea26e376-3df1-42ca-b995-c4e4d9f9b484', 'ce5fd43b-faa8-4563-bd23-450b776e74cb', 'hulu-ghost-hound-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d430d892-22c0-43a2-baaa-4e9e52a47f87.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c73845de-4730-4c68-86b4-fa0a0c285a4a', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 1, '60791453', 'Lucid Dream', '空を飛ぶ夢をよく見る古森太郎は、夢の内容を小型カセットレコーダーに記録していた。ある夜、飛んでいる自分と視線を交わした少女の夢を見る。ドキっとなって目を覚ます太郎。「あの子は僕ば見よった…?」。翌日、太郎の通う水天町立中学に、中嶋匡幸が転校してくる。初対面の生徒にもなれなれしい匡幸は、太郎とほとんど登校することのない大神信との関係に興味を持つ。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d430d892-22c0-43a2-baaa-4e9e52a47f87.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29901121-18bf-4551-8141-f080e0a88418', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 2, '60791445', 'E.M.D.R. Eye Movement Desensitization and Reprocessing', '中嶋匡幸は、11年前水天町で起きた幼児姉弟誘拐事件のあらましをネットで蒐集した資料によって知る。そして、その事件と時を同じくして信の父、大神拝霊会副代表･大神英夫が自分の目を刃物で刺し、頚部を切って死んだことも。一方、古森太郎は、誘拐された事件の日の夢を見ていた。3年前のあの日、学校からの帰り道、姉･瑞香の後をついて歩いていた。瑞香が駆け出したかと思うと、やがて何者かに持ち上げられ…。太郎は夢で見たことが、現実にあることを確認しはじめる。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7d63c65c-6199-4a33-b712-92659d36273d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('080815ef-782a-4156-b02c-81758190de2e', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 3, '60791451', 'Phobia Exposure', '中嶋匡幸は、古森太郎と大神信を誘って、ダム底の廃村に建つ、いまでは廃墟となった亀岩肺病院に向かう。そこは、11年前水天町で発生した幼児姉弟誘拐事件で、遺体で発見された太郎の姉･瑞香が見つかった場所であり、この病院の地下室に入った者は死ぬと噂される場所でもあった。太郎は、この場所が、依然として禍々しい瘴気に覆われていることを感じる。はたして、この場所を目指した三人の行動は、単なる好奇心からなのだろうか?', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d9c56080-79af-4e41-a668-a67f38320133.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e36da5d0-68fc-4f50-9c3a-3024b6c3e4dc', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 4, '60791444', 'Altered States of Consciousness', '廃屋となっているダム底の廃村に建つ亀岩肺病院を探索する古森太郎、大神信、中嶋匡幸ら三人。目指すは11年前、太郎が監禁されていた部屋。いくつかの部屋を巡ったのち、ついに、太郎の姉･瑞香が後ろ手に縛られ横たえられていた寝台の部屋を見つける。何もない寝台の上に、瑞香の姿を見る太郎。あまりの「恐怖」から過呼吸状態に陥り、やがて信、匡幸にも伝播していく。その場から一刻も早く立ち去らなければならない思いにかられた三人は、病院の外に飛び出す。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3ae1bf25-45b0-4ffd-bc52-a261e2862beb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5bf2f3c1-34eb-4480-b012-a20254633f55', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 5, '60791454', 'O.B.E. -Out of Body Experience-', '亀岩肺病院で初めての魂 (たま) 抜けを体験し、神霊を見た古森太郎、大神信、中嶋匡幸ら三人。翌日からは、いつもと変わらない学校生活に戻る。魂 (たま) 抜けし、山の禁忌を犯した者として、亀岩神社の宮司･駒玖珠孝仁に後ろ髪をハサミで切られた経験は、三人の仲をより近いものにしていた。三人はそれぞれ親のことで悩んでいる。太郎は11年前の事件で精神を病んだ母を、信は自殺した父を、匡幸は口論の絶えない両親を。ある日の夜、魂抜けした三人は水天町の上空で出会う。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/81fbfa3c-8f5c-4936-b460-d139f9d690cd.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77c2ee0e-75f4-454f-be8f-6f85974e8169', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 6, '60791439', 'Brain Homunculus', '魂 (たま) 抜けした三人は、亀岩山の山中で自分たちを目視した猿田という老人と出会う。「あまり魂抜けして長くいると、戻れんようになる」と忠告する猿田。もっと詳しく魂抜けのことや神霊のことを知りたい古森太郎は、魂抜けしていない状態で猿田と出会った場所を訪れる。しかし、そこに猿田の姿はなかった。諦めて家路に着いた太郎は、亀岩神社の石段を下りる。が、バランスを崩し、石段を踏み外してしまう。居合わせた駒玖珠孝仁は、太郎を救急車で久間田総合病院に運ぶ。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f984c2cd-d090-4f86-bf7d-8a33fb032f32.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ed5cf15-f408-4da4-9d78-17549c4747cf', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 7, '60791438', 'L.T.P. -Long Term Potentiation-', '久間田総合病院に搬送された古森太郎は、脳のCTとMRI検査を受ける。亀岩神社の石段から落ちたとき、頭を打ったおそれがあったためだ。太郎を見舞いに病院を訪ねた中嶋匡幸は、太郎とともに脳外科医･鳳麗華から説明を受ける。脳にまつわる麗華の話は、太郎に魂 (たま) 抜けと脳には何らかの関係があるのでは、と思わせるものだった。一方、その頃、大神信は、父親の自殺の真相を探ろうと、水天町町長選挙を控えた矢崎基の選挙事務所を訪ねていた。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5d85b0f7-8891-4ccb-ab43-8864e7889eac.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74bdb7fc-e010-4d67-8d10-d1d6d23ede0f', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 8, '60791446', 'Revolution of Limbic System', '冬を迎えた水天町。古森酒蔵では来年の酒の仕込みが始まった。姉･瑞香が連れ去られる夢を見なくなった古森太郎は、久しぶりに瑞香の部屋に入り、そこで体外離脱する。大神信の姿を亀岩神社裏に見つけた太郎は、信と宮司の駒玖珠孝仁が、信の父を巡って言い争っているのを目撃する。信は父と縁のある人物に話を聞き、死の真相を探ろうとしていたのだ。太郎は、以前、亀岩山で出会った猿田という老人を探すが、そこに猿田の姿はなく、神霊と出くわすのだった。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b232c69e-ea83-4c52-8eaa-c8cf6d7343a4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd0c6d35-ac74-44f7-8f08-3ed34e039391', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 9, '60791435', 'Existential Ghosts', '県道沿いの潰れたパチンコ店に、不気味な幽霊が出る噂を同じクラスの星野道男から耳にした中嶋匡幸。そこは11年前、幼児誘拐事件の犯人である宿痾 (すくあ) 八千世が、通りがかったダンプに跳ねられ死んだ場所だった。匡幸と古森太郎は、幽霊が宿痾の怨霊ではないかと考える。11年前の事件と大神信の父の死が関係ないことを証明し、宿痾の怨霊を封印するため、魂 (たま) 抜けしてそこに向かうことを提案する太郎。夜、魂抜けした少年たちは潰れたパチンコ店に集合する。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6462825a-cd87-4ef3-a71e-d41e6080e070.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c2966c1-c2cb-4ead-8e1f-bf7779e26640', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 10, '60791441', 'Affordance / T.F.T. -Thought Field Therapy-', '幽世 (かくりよ) では、精神の力で容姿を変えたり、想像したものを実体化できることを知った古森太郎、大神信、中嶋匡幸。魂 (たま) 抜けした信は、自身を狼へと変貌させ、夜の水天町を駆け抜ける。俄然、幽世に興味が沸いてきた太郎と匡幸は、亀岩神社の宮司、駒玖珠孝仁の元を訪れ、幽世と顕世 (うつしよ) の関係についての話を聞く。環境問題に対する駒玖珠の考えを聞いた三人は、自分たちの生活する水天町について思いを巡らせる。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4021161a-5267-4f3c-9399-6ce97e510ef3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23d1a816-131a-469f-82cf-0c8292e042f6', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 11, '60791447', 'Syntax Error', '授業中に魂 (たま) 抜けした古森太郎は、亀岩ダムに男の死体が浮かんでいるのを見る。ダムに浮かぶ死体に騒然となる水天町。太郎、大神信、中嶋匡幸、星野道男の四人も、亀岩ダムへと向かう。駆け付けた駒玖珠孝仁は、そこで信の母･田部早苗の姿を見る。信の母と何らかの関係があることを知った四人は、駒玖珠にその真相を問う。観念した駒玖珠は、30年前、亀岩肺病院の呪いの部屋を信の父･大神英夫、現水天町町長･矢崎基、早苗の四人で訪ねていたことを明かす。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2bb29dc0-c187-4ac9-b6de-99a863ae165b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ad7f2de-83fd-42b9-8b1e-e37eac3d2b4a', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 12, '60791443', 'Homeostasis Synchronization', '亀岩ダムに浮かぶ死体の身元ははっきりしないまま、数日が経過した水天町。古森酒蔵では仕込みが最終段階を迎え、町は慌しさのなかにも、いつもの日常を取り戻しつつあった。東京から古森太郎のカウンセリングに訪ねていた平田篤司は、相談を受けるうち、幽界 (かくりよ) での太郎たちの活動が進化していることを知る。一方、以前、ダム湖の死者に憑依された駒玖珠都は、再び何者かに憑依されるのだった。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6623b7eb-6823-43b2-8987-dda1067b2064.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1907b27-4720-4a1e-8eae-a08e8ce02a7a', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 13, '60791440', 'For the Snark Was a Boojum, You See.', '眠りについた古森太郎は夢を見ていた。うれしい記憶と悲しい記憶が交錯する中、11年前の事件の夢を見る。高い塀が折れ曲がる路地を、姉を追いかけて走るうち、黒い巨人と対峙する。巨人に立ち向かうが、黒い広大な膜へと変化してしまう。これまでの記憶が複雑に絡み合う中、太郎は幽界 (かくりよ) が自身の脳内とつながっていることを知る。そして「スナーク」と名乗る人物と出会うのだった。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9bc3c751-9bd0-437c-9b44-f5f2165e68f1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('756880f5-928d-4e5a-948e-d401098695ac', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 14, '60791452', 'Emergence Matrix', '古森太郎、中嶋匡幸、星野道男は、駒玖珠都が発した「吾は悪事 (まがごと) も一言、善事 (よごと) も一言、言離 (ことさか) の神」の意味を調べていた。そしてそれが『古事記』に登場する一言主神 (ひとことぬしのかみ) の言葉であることを知る。太郎のカウンセリングを行っている平田篤司は、駒玖珠孝仁からの依頼で、都が憑依される原因を催眠療法により探ろうとするのだが…。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a16733c4-691b-48ff-9f94-92e0d66a5f72.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('188e7203-981e-424e-8d4e-ffb8c1b38b0d', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 15, '60791437', 'Toward an Abandoned City', '以前、魂 (たま) 抜けし、麪室の酵母菌が活性化する様子を見た古森太郎。杜氏である瘧師慧の造る酒が失敗した原因が、自分にあると責任を感じる。また、祖母･大神姫子の死は、一言主神 (ひとことぬしのかみ) が憑依した駒玖珠都に姫子の死を願ったことではないか、と自責の念にかられる大神信。二人は久間田行きのバスで出くわす。一方、中嶋匡幸と星野道男は、水天町を訪れている鈴木誠一の本当の目的を掴んでいた。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/59323b58-2307-47d3-972c-a00a6df33ae7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c490520e-a1bb-4ea6-a79e-3feb59463dcd', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 16, '60791442', 'Hopeful Monster', '久間田を訪れた大神信の目的は、11年前の水天町幼児姉弟誘拐事件と父･英夫の自殺との関係を、母･早苗から聞き出すことだった。早苗が営む居酒で、早苗の庇護者らしい貝原直人と出会う信と古森太郎。二人は貝原の案内で、早苗が身を寄せる家へと向かう。信は何年かぶりに再会した母を詰問し、父の自殺と11年前の事件の真相を訊こうとする。しかし、それでも早苗は頑なに話そうとはしない。隠し持っていたナイフに手をかけた信は…。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c3037740-fd37-4388-b63c-2d262b7433b7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e69e3042-f21f-4524-89e1-88434d9e1128', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 17, '60791436', 'Implicate Order', '駒玖珠孝仁は、娘･都の体の具合を心配していた。一言主神 (ひとことぬしのかみ) に憑かれる症状が深まっていると感じていたからだ。一方、都は突然別の人格になることがクラス中に知られるようになり、気味悪がられていた。古森太郎はそんな都に、どうして自分が心惹かれるのか、その理由が分かった気がして、そのことを伝えようとする。しかし、都にとってそれは残酷なものだった。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ee77ec7b-60d4-4ded-9636-8c635bc38d4f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('369833be-97e0-4f77-9a58-34a24fc6e209', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 18, '60791448', 'Holographic Paradigm', '久間田に留まり、父･英夫の自殺の真相を探ろうとしていた大神信の元を、貝原からの差し入れと伝言を持って瘧師慧が訪れる。時を同じくして、水天町ではダムで発見された死体を巡って、大日本バイオインダストリーの鳳麗華の元を「ふるさとジャーナル」の記者･鈴木誠一が訪ねていた。鈴木は11年前に水天町で起きた幼児姉弟誘拐事件と、その約1年半前、西日本の広範囲で起きていた児童行方不明事件の関係について調べていたのだ。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/954c8e21-5ca8-4702-a001-8b5f91d7ec3b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2273e966-dbb9-447d-9779-641b937b10dd', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 19, '60791455', 'Negentropy', '父･英夫の自殺の真相を知った大神信は、炎に包まれた貝原邸から自殺を図った母･早苗を救い出す。久間田総合病院で、再び出会う母子。しかし、早苗はこれまでの記憶を失い、信を30年前の高校生だった頃の英夫と勘違いしていた。その様子に慄然となる信。また、病院には亀岩神社の石段で、意識不明の重傷で発見された駒玖珠孝仁も運ばれていた。中嶋匡幸とともに、久間田総合病院を訪ねた古森太郎は駒玖珠都を見かけ、その顔が別人のようであることにショックを受ける。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/332a83ce-17a4-418e-8cd6-7fe3fcc7681c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e44436cd-184b-4802-b2ca-2e05cf98cc17', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 20, '60791449', 'Shaman''s District', '駒玖珠都の様子がおかしいことに、責任を感じる古森太郎。水天町の家々には、大神拝霊会の信者であることを示す御幣が下げられ、かつての勢いを取り戻しつつあった。太郎の母･美樹は、11年前に亡くなった筈の瑞香が庭にいたことを太郎に話す。その言葉に、太郎は母が「壊れて」しまったのではないかと戦慄する。さらに古森酒蔵には、瑞香に会えることをほのめかす、大神拝霊会の信者が訪れていた。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b5fdc79e-28d3-4d08-8460-9470b7658919.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71e202e1-1162-4042-b82c-fbea02f0649e', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 21, '60791450', 'Stochastic Resonance', '大神拝霊会の勢いが増すにつれ、水天町には数多くの鳥居が構えられるようになった。二つの台風が接近する中、町は異様な空気に包まれる。駒玖珠都は、加畑憲子らによって新たな大神様になることを強いられ、奉られていた。そんな中、亀岩神社の境内に集まった古森太郎、大神信、中嶋匡幸、星野道男、鈴木誠一、平田篤司、鳳麗華、猿田は、都を助けたい、という太郎の言葉に同意し、この異様な水天町を打開する方策について話し合う。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8281cc34-04ef-4a7f-b541-2a1e9560573a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('867554e1-9246-44a6-bc51-d15632a8f88e', 'ea26e376-3df1-42ca-b995-c4e4d9f9b484', 22, '60791434', 'Passage', '【シーズン1 最終話】「龍神が降りてくる」―大神拝霊会の新しい教祖、駒玖珠都の言葉に呼応するかのように、水天町には日本をはじめ世界各地の修験者やシャーマンが集まっていた。また、小学生が強制的に教祖をさせられている、という鈴木誠一のタレコミにより、数多くのマスコミが水天町を訪れ、一時町は騒然となる。都を救出するため、巫女姿に女装した古森太郎は、鳳麗華とともに大神拝霊会へと向かう。首尾よく、教祖である都に接触することに成功した太郎だが…。', '2016/11/01 12:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/663bc29b-86c8-494b-86b4-58c52334004d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4fab766d-92d3-4469-99ee-3e64c934a42a', '進撃！巨人中学校', '', 'hulu', 'attack-on-titan-junior-high', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50023653_series_art__338x600_attack_on_titan_junior_high_4ae55cad22de2db8ad5d208771aa9c9c.jpg?w=331&h=447&p=t', 'hulu', 2015, 3, 1, 'FINISHED', NULL, 21281, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fe6b2b4e-73ed-456c-83ea-0739992d9bb5', '4fab766d-92d3-4469-99ee-3e64c934a42a', 'hulu-attack-on-titan-junior-high-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/468086e2-b099-492d-9425-408eb20d0a77.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89af66ed-d6a6-43b1-ba69-751d9d8cb78f', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 1, '60626285', '入学! 巨人中学校', '中学校の入学式当日。さっそく寝坊したエレンはミカサの声で目が覚める。慌てて家を駆けだしたエレンは、同じ中学校の一年生らしき生徒達と出会いがしらに次々とぶつかってしまい、追いかけられたり吹き飛ばされたりしながら、巨大な建物の前へと辿りつく。そここそ、彼らが入学する進撃中学校。響くチャイムの音に教室へと急ぐ一同。しかし、周囲の様子が何かおかしい。そんな中、扉を開けたエレンの頭上に巨大な何かが落下する!', '2015/10/06 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/468086e2-b099-492d-9425-408eb20d0a77.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('826dea30-93fa-4071-a9d3-61cfa8eaadb1', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 2, '60627628', '追跡! 巨人中学校', '寒さを理由に、一度も登校してない極度の寒がりアルミン･アルレルト。その入部届けを回収するため、肉まん片手にアルミンの家へと向かったエレンとミカサは巨人に襲われる。奪われた肉まんを取り戻そうとするエレンだったが、その拳は巨人に届かない。あれでは肉まんが冷めてしまう。そう判断したミカサが助けに入ろうとした瞬間、突如現れた人影がハリセン一閃、巨人をしばく。羨望の眼差しで見上げたエレンの目に映ったものは?', '2015/10/13 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c5d4f3f6-b078-40a8-b6b0-6a03ef20c13c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('098d5a03-6287-4208-b93d-0710a138fd43', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 3, '60633881', '闘球! 巨人中学校', 'エレンのせいで好物を「もずく」と偽るはめになったアニ･レオンハートは、ドッジボール大会でエレンを倒すと宣言する。しかし大会当日、1年4組Aチームはエレンの寝坊により危機を迎えていた。大会参加条件はチームメイトの全員参加。エレンの不在を隠すAチームは、朝から一定時間エレンと会えないとスペックが30％に落ち込むミカサが戦力外になるなど苦戦続き。アニとの対決は実現するのか、その前にエレンは起きられるのか?!', '2015/10/20 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e09518b7-4361-405a-bbf7-33b543ee8469.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6cad94ef-d9c2-4c2c-9716-82acdbec1e73', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 4, '60637971', '清掃! 巨人中学校', '強制的に壁美化部に入部させられ苛立つエレンの前に、新入部員育成に燃えるリコ･プレツェンスカが現れる。設立当初は100人いたといわれる壁美化部も、いまや部長のリコ一人。部活動として窓掃除を言い渡されたエレン達は、ぼやきながらも窓をみがき続けるが、通りがかった女生徒達にかっこ悪いと笑われ嫌気のさしたジャンが逃げ出す。サボリは許さん! とばかりにジャンを追うリコ。その姿に思わずエレン達の目が釘付けになる!', '2015/10/27 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/768460c6-d5f8-4568-8454-5f7bb7277605.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2dde763-81e3-43ae-8a8e-05d8988dd51b', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 5, '60639995', '猛勉! 巨人中学校', '学校中、全学年、全生徒に走る緊張感。それは彼らの運命を左右する一瞬。恐怖のテスト返却の始まりだった。結果、オール0点もどこ吹く風といったコニーよりも、追試も赤点だったら給食抜きと言い渡されてしまったサシャの漂わせる悲壮感のほうが凄まじく、アルミンに勉強を教えて欲しいと頼み込む。コニーを交えて追試対策の勉強をすることにした三人だが、コニーのやる気はもつのか？ そしてサシャは苦手な数学を克服できるのか?', '2015/11/03 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cbdccd65-3a10-47c7-b3d0-a03e7da66517.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f8a4905-286d-400b-8d1d-5cb67ce0374d', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 6, '60643336', '恋文! 巨人中学校', '珍しく一緒に帰ろうとするサシャとコニーに、ハンナとフランツのバカ夫婦っぷりはいつもの事ながら、それを見るジャンの心は密かにささくれ立っていた。しかもエレンとミカサのやり取りまでもが始まってしまい、羨ましさから思わず摑みかかる。マルコになだめられつつ、ここには俺の魅力がわかる女子がいないと憤るジャン。しかし、下駄箱をあけるとそこにはラブレターが! 差出人は誰なのか?! ジャンの妄想に基づく推理が炸裂する!', '2015/11/10 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7e8955be-69aa-4404-a433-941e15ddb066.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('784a24a7-e243-4f07-a45e-2a51eae1f3f9', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 7, '60646914', '対決! 巨人中学校', '一年生は購買の焼きそばパンを買うべからず。それ以外にも挨拶、服装、髪型と、生徒の間で引き継がれる暗黙のルールはたくさんある。そうとは知らずにルール違反を重ねてしまったエレン達一年生は、罰掃除に次ぐ罰掃除に次第に苛立ちを募らせた末、リヴァイ達三年生に喧嘩を売ってしまい、オルオ達二年生を巻き込み学年対抗体育大会で勝負をつける事になるのだが、負けた学年には巨人棟の掃除が待っている! エレン達は勝てるのか?', '2015/11/17 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4bb7d957-507d-48da-9d2e-080360868582.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecf39b59-6754-4424-a9db-9ec5c58da9bb', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 8, '60649761', '怪談! 巨人中学校', '調査団の親睦をより深めるためにハンジが企画したのは、泣く子も黙るKIMODAMESHI! 日も沈む頃、集合場所の教室へと向かうエレン達。昼間とはうって変わって夜の校内は薄気味悪い。「暗いの怖い」と怯えるアルミン。それを怖がりすぎだと笑うエレンの足も、恐怖でガタガタ震えている。その時、背後の暗闇から伸びてきた手が、強がるエレンの肩をわし摑む。闇夜に響くエレンの悲鳴。果たしてエレンには何が見えたのかっ?!?', '2015/11/24 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/01ffe787-edbe-481e-b043-b46508eca337.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f203d14-0fa1-4c0e-9c13-276e809ada2a', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 9, '60654426', '甘夏! 巨人中学校', '芸術的な寝相の悪さで幼い頃の夢を見ていたベルトルト。夏祭りの日に仲良しの2人から得意の型抜きを褒められる夢から一転、ライナーに叩き起こされて目が覚める。夏祭りにクリスタを誘いたいから一緒に来て欲しいと言うライナーの頼みを断るベルトルトだったが、視線の先にはアニの姿が。何やら察したライナー、クリスタを誘いに行った流れでユミルとともに、ベルトルトがアニに声を掛けるきっかけを作ってやろうとするのだが。', '2015/12/01 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1b9ee8d1-4861-4b6f-9d30-54e171505173.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1141074a-818a-4390-9ab2-0e20826e50d2', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 10, '60657252', '推薦! 巨人中学校', '新聞部により生徒会の不祥事が暴かれ、新たに生徒会会長選挙が行われる事になった進撃中学校。モテたいジャンが立候補を決め、みんなのために仕事ができる喜びを話すマルコにお利口ぶらないで本音を言えよと迫って困らせる。会長になって一匹残らず巨人を駆逐してやる! と息巻くエレンも立候補を決め、白熱していく選挙戦。ところが、これさえあれば生徒会長戦で一発逆転も夢ではないという「イルゼの手帳」の存在が明らかになり…。', '2015/12/08 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2f0d18b6-6305-4f0a-9b60-f094ce2caffa.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc4561a3-ae54-44ed-bba1-18f1d6f67d4a', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 11, '60660556', '快晴! 巨人中学校', 'もうすぐ文化祭。エレンたち1年4組は演劇とチーハン屋の二つをやる事に。とは言え、文化祭の目玉は全模擬店参加のB級グルメ大会。チーハンの素晴らしさを皆に知らしめるチャンスとやる気満々のエレンだが、くしくも隣の店はリコとイアンが仕切る去年の優勝店。絶対に優勝する! エレンの熱い想いにうたれたアルミンは、チーハン屋を優勝に導くため去年の優勝者を凌ぐ必要に迫られたなら…と大事な何かを捨てる覚悟を決める!', '2015/12/15 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/885977eb-1a27-4c1b-b05b-14fd767a01ac.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20ba95bd-1ec8-40c4-ac0f-03f4a6de30a1', 'fe6b2b4e-73ed-456c-83ea-0739992d9bb5', 12, '60663788', '進撃! 巨人中学校', '【シーズン1 最終話】 チーハンを取り戻す! 立ち上がったエレン、ミカサ、アルミン、ジャン、サシャ、コニーは、ライナー達の協力を得て、行く手を阻もうとする教師陣を振り切るのに成功する。力になってくれるに違いないと信じて調査団の部室に行くが、リヴァイが出した結論は待機だった。動かない理由を問うエレンに、ペトラやオルオは指示に従えとしか言わない。せいぜい悔いが残らない方を自分で選べ。リヴァイの言葉にエレンは巨人棟へと向かう!', '2015/12/22 12:00:00', 1020, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/277d7ea0-7786-43c8-a072-1f8db31c2792.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0ec12696-8c5f-4b8f-89d7-89cbfc8996b1', '進撃の巨人', '', 'hulu', 'attack-on-titan', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25b5d8a9-02f8-4fd8-859e-dbc5a715448f.jpg?w=331&h=447&p=t', 'hulu', 2013, 1, 1, 'FINISHED', NULL, 16498, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('61b04f65-049f-4168-af5e-3dd84b53b55a', '0ec12696-8c5f-4b8f-89d7-89cbfc8996b1', 'hulu-attack-on-titan-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/56f3937d-9858-489c-a180-2b23ed604573.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('049495d0-6009-4bdc-abfb-f95d03c106eb', '61b04f65-049f-4168-af5e-3dd84b53b55a', 1, '60599459', '二千年後の君へ －シガンシナ陥落 ①－', '四方を50ｍを超える壁に囲まれた街･シガンシナ地区。人々は壁の外の巨人から自分たちを守るため、この巨大な壁を作りあげたのだった。外の世界に憧れる少年エレンと、彼のよき相談相手であるミカサは、壁の中で平和な時を過ごしていた。そんなある日、壁の外を探索に行った調査兵団が、この町に帰還するのを知る。調査兵団を“英雄”と呼ぶエレンが見たのは…。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/56f3937d-9858-489c-a180-2b23ed604573.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1950272-989e-4bf2-9d59-28882fb32441', '61b04f65-049f-4168-af5e-3dd84b53b55a', 2, '60599455', 'その日 －シガンシナ陥落 ②－', 'シガンシナ地区を襲った巨人は、そこで生活していた人々の日常を一変させた。悲鳴と怒号が飛び交うなか、我先にと逃げる人々をおもむ ろにつまみあげ、次々に口の中へと放り込んでいく巨人の姿は、人類はただのエサに過ぎないことを実感させるのに十分だった。目の前に いた母を救えず、己の無力さを痛感したエレンは、巨人への憎しみを募らせる。「あいつらを駆逐してやる…この世から…一匹、残らず!」', '2015/09/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/356040be-a26f-48d3-9ba7-ac0497d8a223.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb98f7da-b2cb-4af6-a74e-3b1d2a1bde5c', '61b04f65-049f-4168-af5e-3dd84b53b55a', 3, '60599451', '絶望の中で鈍く光る －人類の再起 ①－', '巨人殺しの最も有効な手段「立体機動術」を身に付けるため訓練兵団に入団したエレン、ミカサ、アルミン。キース教官の課す厳しい訓練の過程で、出身も考え方も異なる同期同士の連帯感が芽生える。立体機動術の前段階である姿勢制御訓練をミカサやアルミン、同期の仲間たちが難なくクリアしていく中、エレンは無様に失敗してしまう。兵士としての適正がなければ開拓地へと送られ、人類の食糧を支える「生産者」になるほかないが…。', '2015/09/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ac2986ac-1f72-40a6-afbb-2778dd3bf427.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2da53759-92ac-42a8-9e43-e09c60960082', '61b04f65-049f-4168-af5e-3dd84b53b55a', 4, '60599456', '解散式の夜 －人類の再起 ②－', '訓練兵団に入団して3年。キース教官のもと厳しい訓練を経たエレン、ミカサ、アルミンたちに、いよいよ卒団の時期が迫っていた。そんな中、エレンは「立体機動術」などの巨人殺しの技術を磨くことが、同時に巨人からいち早く安全圏に逃れる技術に繋がっている矛盾に気づく。訓練兵団での成績上位者は内地にて王のもとで民を統制し、秩序を守る憲兵団に入れるのだが…。', '2015/09/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/faa584c0-32ee-4738-bb54-789e4e64a481.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('840f759d-c632-469e-b6e7-601ad8872e88', '61b04f65-049f-4168-af5e-3dd84b53b55a', 5, '60599453', '初陣 －トロスト区攻防戦 ①－', 'シガンシナ区の惨劇から5年、エレンは「ウォール･マリア」破壊のきっかけとなった巨人と対峙していた。立体機動装置を作動させ、巨人の急所であるうなじを狙い攻撃を加えるエレン。しかし、突如発生した大量の蒸気に巨人を見失ってしまう。破壊された開閉扉、壁の修復にあたりながら、巨人の第二波進軍に備えるエレンたち。はたして、迫りくる巨人たちに一矢報いることはできるのか!?', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5231e8b9-a248-41d3-8a7c-c0fee1104b82.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a6834f0-1880-4159-b1c3-93efee71be2f', '61b04f65-049f-4168-af5e-3dd84b53b55a', 6, '60599450', '少女が見た世界 －トロスト区攻防戦 ②－', 'トーマス、ナック、ミリウス、ミーナ、エレン…。巨人の前に次々に斃れていく34班の仲間たち。一人生き残ったアルミンは救助に訪れたコニーに声をかけられるが、あまりの出来事に現実を受け入れられないでいた。エレンとは別の部隊で巨人と戦っていたミカサは、エレンと出会った時のことを回想する。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/518c7667-ca97-4ceb-8ea4-0a0d90d17d39.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3fb382ca-b6ab-41f7-8870-c92c05cecdf3', '61b04f65-049f-4168-af5e-3dd84b53b55a', 7, '60599470', '小さな刃 －トロスト区攻防戦 ③－', '一時撤退の鐘が鳴ったものの、立体機動装置用のガスが尽きかけているため、壁を登れないジャン、コニー、アルミンたち訓練兵。そこにミカサが追いつき、補給部隊が籠城した駐屯兵団本部に向かうことを提案する。しかしそこには多数の巨人たちが群がっていた。先陣を切って本部奪還に向かうミカサだが…。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2c500495-6fd6-416c-9775-8688a8e9409e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89e4586c-e276-4c69-ac50-4faae3ae43f9', '61b04f65-049f-4168-af5e-3dd84b53b55a', 8, '60599467', '心臓の鼓動が聞こえる －トロスト区攻防戦 ④－', '窮地に陥ったミカサを救った巨人を補給所まで誘導して、駐屯兵団本部に群がる巨人たちを倒せないか、と提案するアルミン。その提案を受け、コニーの援護のもとミカサは駐屯兵団本部を目指す。一方、ジャンたちは立ち塞がる巨人たちをすんでのところでかわしながら、ミカサたちよりひと足早く本部に辿りついていた。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/44193ee1-adb4-414b-aef4-1e97f3b21a7a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7496f0b6-d45a-47c7-8e67-5e872b05fda0', '61b04f65-049f-4168-af5e-3dd84b53b55a', 9, '60599468', '左腕の行方 －トロスト区攻防戦 ⑤－', 'トロスト区全域で繰り広げられた人類と巨人との死闘。アルミンの目の前で巨人の餌食となったエレンだったが、自ら巨人となりミカサたちの窮地を救った。しかしにわかには信じ難いキッツ率いる駐屯兵団はエレンたちに武器を向ける。キッツから「貴様の正体は何だ? 人か巨人か?」と問われたエレンは…。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/00746c0e-ded0-4359-abf4-23c0a0b588a9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01d45244-fbcf-45a8-8054-a45d0758f2e8', '61b04f65-049f-4168-af5e-3dd84b53b55a', 10, '60599448', '応える －トロスト区攻防戦 ⑥－', '巨人が人に化けている―恐怖が伝染した戦場では、エレンやアルミンがどんな申し開きをしようと、誰も聞く耳を持つ者はなかった。エレンたちに向かって放たれる砲弾。その刹那、エレンは上半身を巨人化させ、ミカサとアルミンを守ることに成功した。蒸気とともに消えゆく巨人の骨格の中で、エレンが選択するのは…!?', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/897ccad1-b0d1-47c6-91be-1b04a8a6a9e1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97860d05-0e91-4638-9270-6a893415c506', '61b04f65-049f-4168-af5e-3dd84b53b55a', 11, '60599460', '偶像 －トロスト区攻防戦 ⑦－', '南側領土を統括する最高責任者であるピクシス司令から駐屯兵団に知らされたトロスト区奪還作戦。それは、巨人化したエレンが大岩を運び、破壊された扉を塞ぐというものだった。巨人たちがトロスト区に入り続けているいま一刻の猶予もままならない。エレン自身、自らの力を信じているわけではなかったが、「オレはならなきゃいけないんだ…みんなの希望に」と決意を固める。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/15fc448c-847a-46a2-a4f8-6ced937e38f7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cbd73cd9-f2f2-4bda-97a1-ea0abe3f1050', '61b04f65-049f-4168-af5e-3dd84b53b55a', 12, '60599464', '傷 －トロスト区攻防戦 ⑧－', 'ミカサに向けて振り下ろされた巨人化したエレンの拳。トロスト区奪還作戦は、いきなり暗礁に乗り上げていた。すんでのところでその拳をかわすミカサだったが、再度、エレンはミカサめがけて拳を振り上げる。ついに自らの拳を顔面に打ち込み、動けなくなってしまうエレン巨人。そこに三体の巨人が接近してきて…。作戦の現場指揮を任された精鋭班･班長イアンは判断に苦慮する。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3c2fb3ff-8eae-4aa1-a5c6-32f4bca674e6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('424feb08-4ec2-4dcc-afed-412dd8486197', '61b04f65-049f-4168-af5e-3dd84b53b55a', 13, '60599454', '原初的欲求 －トロスト区攻防戦 ⑨－', 'エレンを覚醒させるべく語りかけたアルミンによって、巨人化したエレンは大岩を運び始めた。トロスト区内に侵入した巨人たちがエレンに群がるのを防ぐため、イアンをはじめ精鋭班の班員たちは決死の覚悟で巨人を自らに引き付ける作戦を展開する。数々の命が無残に蹂躙されていく中、巨人化したエレンはついに壁の穴を大岩で塞ぐことに成功する。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9a15a4d4-ba52-4516-a3fd-51c653449c37.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50fab482-dd8e-4e65-a02f-7b7975fe4499', '61b04f65-049f-4168-af5e-3dd84b53b55a', 14, '60599449', 'まだ目を見れない －反撃前夜 ①－', '巨人となったエレンに対する民衆の反応は様々だった。壁のより内側に住む者ほど、破滅に導く悪魔と恐れ、より外側に住む者ほど希望へと導く救世主と呼んだ。中央政府はエレンを憲兵団と調査兵団、どちらに引き渡すかの審議にかける。それぞれの兵団の思惑が交錯するなか、エレンの審議が始まる。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e5ddfc11-1be2-4875-a679-d3d97bb4b3c4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55461638-984e-4c30-8884-0c5733970695', '61b04f65-049f-4168-af5e-3dd84b53b55a', 15, '60599471', '特別作戦班 －反撃前夜 ②－', '審議の結果、調査兵団特別作戦班･通称「リヴァイ班」に所属することになったエレン。調査兵団のなかでも精鋭が集うリヴァイ班はひと癖もふた癖もある個性的な団員で構成されていた。30日後の大規模な壁外遠征を控え、エレンはトロスト区掃討戦の際に捕えた巨人の実験内容をハンジから聞くのだった。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bfb828ec-869d-424d-8f72-19c062c59e5b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2b059b5-5a02-4638-aaff-eb4f4646a7ea', '61b04f65-049f-4168-af5e-3dd84b53b55a', 16, '60599457', '今、何をすべきか －反撃前夜 ③－', '調査兵団が生け捕りにしていた二体の巨人が何者かによって殺されてしまう。第104期訓練兵にも疑いの目が向けられ、一人一人調査が行われた。結局、誰が殺したのかは分からなかったが、訓練兵たちにとっては重要なそれぞれの所属兵団を決める時期が迫っていた。彼らの前に立ったエルヴィンは本来であれば伏せておくべき情報まで明かすのだが…。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/945ee2ef-5361-4f51-9802-c080b48ad930.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d73897b-0f62-4d2d-8f11-ef05f65f62d9', '61b04f65-049f-4168-af5e-3dd84b53b55a', 17, '60599461', '女型の巨人 －第57回壁外調査 ①－', 'エレンと同期のミカサ、アルミン、ジャンたち第104期訓練兵を新たに加えた調査兵団はエルヴィンの指揮のもと第57回壁外調査に出た。長距離索敵陣形にて巨人との接触をできるかぎり避けながら目的地を目指す。しかし陣形内で索敵を担当するアルミンは“知性”を持つ女型の巨人に迫られ窮地に立たされる。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6c18596d-fa71-4f00-a72e-c4cbaae14d95.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49686734-e3e3-438f-b674-706116d473ad', '61b04f65-049f-4168-af5e-3dd84b53b55a', 18, '60599466', '巨大樹の森 －第57回壁外調査 ②－', '女型の巨人によって、陣形の右翼側索敵に壊滅的な打撃を受けた調査兵団。撤退指令が出るものと思われたが、指令班が下したのは陣形の進路を変えつつ、作戦を続行することだった。その間にも女型の巨人は調査兵団の陣形を破壊しながら団員達を蹂躙していく。そして、ついにエレンが属するリヴァイ班からも目視できる距離まで迫られる。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/35ac9fe0-38bb-4950-bf94-431be8708a38.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23ce49c9-d4d1-4443-92ae-3b0defa7e46c', '61b04f65-049f-4168-af5e-3dd84b53b55a', 19, '60599469', '噛みつく －第57回壁外調査 ③－', '“巨人殺し”のプロフェッショナルであるリヴァイ班の背後に迫る女型の巨人。しかし、リヴァイ班の面々は女型の巨人を足止めするべく、立ち向かう兵士にあえて増援することなく、ただひたすらに馬を走らせていた。エレンは問う「見殺しにする理由がわからない! それを説明しない理由もわからない!」と。その問いにリヴァイは、ある選択を投げかける。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2469dfcd-cd3d-4b2f-b95c-dc5bc6920b3d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('daa7c91b-d5e9-4471-b66e-7c3c00f48bf1', '61b04f65-049f-4168-af5e-3dd84b53b55a', 20, '60599452', 'エルヴィン･スミス －第57回壁外調査 ④－', '数多の犠牲を払いながら、ついに巨大樹の森で女型の巨人を拘束兵器で捕えることに成功した調査兵団。作戦の本来の目的を知らされていなかったほとんどの兵団員は、ようやくエルヴィン団長の真意を知ることとなる。身じろぎひとつできなくなった女型の巨人は、断末魔の悲鳴をあげるが…。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7ffb10f1-e1c2-4dfe-8e5a-b9d7854c7e01.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e4fc09c-1647-422c-a2e3-b15be4ab1eba', '61b04f65-049f-4168-af5e-3dd84b53b55a', 21, '60599462', '鉄槌 －第57回壁外調査 ⑤－', '自らの肉体を他の巨人に喰らわせ、蒸気とともに消えた女型の巨人。その中にいた人物は、調査兵団員と同じ制服で兵士の中に紛れ込み、エレンを追っていた。エレンを護衛しながら帰還するグンタを手にかけ、再び女型の巨人となってエレンの前に現れる。オルオ、エルド、ぺトラが連携しながら女型の巨人に立ち向かうが…。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3e7b5bdc-053c-4a33-a1f8-f91c73b7c633.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb4c8708-50a6-4c91-8a90-bf675ebaeef8', '61b04f65-049f-4168-af5e-3dd84b53b55a', 22, '60599458', '敗者達 －第57回壁外調査 ⑥－', '女型の巨人に捕えられたエレンを奪還するべく、そのあとを追うミカサ。そこにリヴァイが追いつき、巨人を仕留めることをあきらめ、エレンを救い出すことに目的を絞る。リヴァイは人間とは思えない驚異的な動きで、ついに女型の巨人の動きを止めることに成功する。ミカサは、止めを刺そうと攻撃に入るが…。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/54a73117-e14e-44fa-97d1-c5118d0e071b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4626a482-ebbf-4e18-a849-4c9d3c29fe61', '61b04f65-049f-4168-af5e-3dd84b53b55a', 23, '60599463', '微笑み －ストヘス区急襲 ①－', '第57回壁外調査は、人類の中に潜む敵―巨人化能力を持ち、壁の破壊を企む人間を捉える作戦でもあった。しかし、調査兵団はこの作戦に失敗してしまう。政治的判断からエルヴィンら責任者が王都に召集されるだけでなく、エレンの引き渡しも決まってしまう。そんなおり、ストヘス区憲兵団支部に所属するアニは、調査兵団がストヘス区を通過する間の警備を命じられる。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/58826d43-d8df-44ec-95a1-8bc220d129dd.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f2d115a-1861-40ef-8934-43cfc2ceb3d4', '61b04f65-049f-4168-af5e-3dd84b53b55a', 24, '60599472', '慈悲 －ストヘス区急襲 ②－', 'アルミンの立案した作戦に沿って、アニを地下通路への入口まで誘い出すことに成功したエレン、ミカサ、アルミン。しかし、アルミンの真意に気づいたアニは巨人化し、エレンを死にもの狂いで捕えようとしていた。地下通路内に逃れたエレンたちを狙う女型の巨人･アニ。ミカサ、アルミンを守るためエレンも巨人化を試みるが…。', '2015/09/01 12:00:00', 1447, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/788190f1-3749-49df-bdf9-4aa8fb336cb4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1270517-a3c0-455a-99d8-f73e0fefd1d8', '61b04f65-049f-4168-af5e-3dd84b53b55a', 25, '60599465', '壁 －ストヘス区急襲 ③－', '【シーズン1 最終話】逃げる女型の巨人 (アニ) に、巨人となったエレンは追いつき、二体の巨人は激しい闘いを繰り広げていた。巨人同士の闘いに巻き込まれ、ストヘス区市街では想像を絶する被害が出ていた。その責任を憲兵団師団長ナイルに糾弾されるエルヴィン。エルヴィンは「人類の勝利のため」と答え、ナイルの構える銃の前に立つ。', '2015/09/01 12:00:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b29e2fd1-bdf1-4158-93df-8e5e454c1440.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9149363a-a464-4651-89a7-91d32e7292cc', '0ec12696-8c5f-4b8f-89d7-89cbfc8996b1', 'hulu-attack-on-titan-s2', 'シーズン2', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c7e59ef-ea14-4798-9d4f-ea2b2738f0ae.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccffc194-0c50-483b-828d-268b30ea89b2', '9149363a-a464-4651-89a7-91d32e7292cc', 26, '100002489', '獣の巨人', '女型の巨人との戦闘の後、壁の中から発見された巨人。その正体を聞き出そうと、ハンジはニック司祭を激しく責め立てるが、ニックは脅しに屈することなく黙秘を貫くのだった。遡ること12時間前、ウォール･ローゼ南区で待機するコニーやサシャら104期生のもとに巨人が多数襲来したとの情報が伝えられる。巨人の群れが進む先には、コニーの故郷の村があった。コニーたちをそこへ向かわせるため、分隊長のミケがとった行動は…?', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c7e59ef-ea14-4798-9d4f-ea2b2738f0ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2d21b92-b9bd-48bb-a899-261f22ab5852', '9149363a-a464-4651-89a7-91d32e7292cc', 27, '100002490', 'ただいま', '巨人発見より5時間後、北の森に向かったサシャは故郷の村まで到達する。サシャの胸中によみがえる、父親との苦い思い出…。3年ぶりの故郷は最早、人の住める土地ではなく、その先に見つけた新しい村でサシャは凄惨な光景を目の当たりにする。一方で、急ぎウォール･ローゼをめざすエレンたちだったが、同行者の中には何故かニックの姿があった。ウォール教が知る壁の秘密を開示するべきか、彼は自分の目で確かめるという。', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b25e9702-02b2-415d-87b8-93745376e76e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ff469e1-28f7-48dc-a61e-b000543ec99e', '9149363a-a464-4651-89a7-91d32e7292cc', 28, '100002491', '南西へ', 'コニーの故郷に人影は一切なく、代わりに残されていたのは一体の巨人が仰向けに倒れた姿のみ。失意のコニーの耳に届く、微かな声。それは巨人が発したように思われたが…。時を同じくして、リコ率いる駐屯兵第一師団精鋭部隊は東防衛線で巨人と交戦し、ハンネス率いるウォール･ローゼ対策部隊は壁沿いの道を偵察するも未だ一匹の巨人とも遭遇しないままだった。それぞれに胸騒ぎを覚えたまま、巨人出現から最初の夜が訪れる。', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/582144c8-af34-48f4-836e-523aabbaedd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f9d7527-ef44-4730-9029-fa89ab4af779', '9149363a-a464-4651-89a7-91d32e7292cc', 29, '100002492', '兵士', 'コニーやライナー、ベルトルトのいる南班、そしてクリスタとユミルがいた西班は暗闇の中で合流し、ウトガルド城という古城跡で共に夜を明かすことになった。だが、見張りが気づいたときには既に城の周りを大勢の巨人が取り囲んでいた。戦闘用の装備を持たない104期生たちは塔の中へ一時避難するが、突破されるのは時間の問題だった。巨人の侵入を防ごうと孤軍奮闘するライナー。彼の脳裏にフラッシュバックする記憶とは…?', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d120d02-5b26-4f18-9bc1-1237087fd362.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('205bb4f8-a271-428d-8093-d1bca80c1efb', '9149363a-a464-4651-89a7-91d32e7292cc', 30, '100002493', 'ヒストリア', 'エレンたちがまだ訓練兵団だった頃。とある雪山での訓練を終えた後、ふと気づくとクリスタとユミルの姿が見えなくなっていた。クリスタは訓練中に体調を崩したダズのそばについていて、また、ユミルはそんなクリスタに付き合っているうちに遭難してしまったのだ。吹雪の中、すっかり日も暮れて、息も絶え絶えなダズを引きずって山のふもとをめざすクリスタ。このままでは3人とも助からないという状況で、クリスタのとった決断は!?', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e3007e8-a51c-4e09-9f12-77054dde5a4c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eac16b5b-c115-4d3f-93e2-b308276af19c', '9149363a-a464-4651-89a7-91d32e7292cc', 31, '100002494', '戦士', 'ウトガルド城を取り囲んだ巨人の群れはユミルの活躍と、駆けつけた調査兵団の主力部隊によって撃退された。重傷を負ったユミルは治療のためトロスト区に送られることとなり、残った調査兵団は壁の修復作戦を再開することに。ところが、穴の位置を知らせに来たはずのハンネスは「穴はどこにもない」と報告する。穴がないのだとしたら、巨人はどうやって壁の内側に現れたのか? 疑問を抱えたまま、エレンたちはトロスト区で待機する。', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad2dab90-d4f0-4706-93a5-bbeba4c0bc77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8769e290-a8d2-48e4-ac4a-f43197d9f7b7', '9149363a-a464-4651-89a7-91d32e7292cc', 32, '100002495', '打･投･極', '「鎧の巨人」と「超大型巨人」がエレンの目の前に出現。激昂したエレンはすぐさま巨人化し、鎧の巨人の顔面に拳を叩きこむ。一方、超大型巨人は調査兵団が待機していた壁を破壊し、昏睡状態のユミルを捕らえて自らの口の中に放り込むのだった。調査兵団はハンジの号令のもと、一斉に超大型巨人へ襲いかかるが、巨人が全身から蒸気を噴出させたため、近づくことすら不可能となった。その頃、鎧の巨人を相手に苦戦するエレンは…?', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da50f1a8-9257-4b2b-9dd9-ee40bd85f2d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa99238d-3b6d-4147-b3d2-3b14869252a4', '9149363a-a464-4651-89a7-91d32e7292cc', 33, '100002496', '追う者', 'エレン巨人は鎧の巨人をあと一歩のところまで追いつめたが、超大型巨人の頭部が落下してきたことにより形勢は逆転し、エレンは鎧の巨人に連れ去られてしまう。さらに、超大型巨人の発生させた熱と風圧が、その場にいた兵士たちに甚大なダメージを与える。倒れたミカサが目を覚ましたときには、既にエレンの敗北から5時間が経過していた。エレンを想って、涙するミカサ。そんなミカサやアルミンを、ハンネスは勇気づけるのだった。', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/980bfb2a-8333-474f-bd0c-714989549092.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cc80119-fdeb-4505-94a3-bcc12d23b711', '9149363a-a464-4651-89a7-91d32e7292cc', 34, '100002497', '開口', '鎧の巨人との戦いに敗れたエレンは、巨大樹の森で目を覚ます。そこにはエレンと同様に巨人化の能力を有する者たちがいた。巨人の巣窟となった森では、たとえ巨人になったとしても生き抜くことは困難であり、そもそも戦い終えたばかりのエレンには巨人になれるだけの体力はない。即ち今のエレンに出来ることは、巨人が動かなくなる夜まで大人しく待つことだけ。そんなエレンに、ある人物が「俺達の故郷に来てもらう」と語りかける。', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c2e3773-1bad-4844-bfa3-f538f1fdf0ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('263b69e5-0124-4bc0-935b-9f62de407177', '9149363a-a464-4651-89a7-91d32e7292cc', 35, '100002498', '子供達', '日没まであと1時間。調査兵団の精鋭たちがついに巨大樹の森に到達した。目的はあくまで戦闘ではなく、エレンを見つけ出し奪還すること。だが、それでも危険な作戦であることに変わりはない。そんな中で、クリスタだけは絶対に助け出さなければならないと、ユミルの心に焦りが生じていた。ユミルは思い出す。貧民街で暮らしていた幼い頃と、その後の数奇な運命、そしてクリスタとの出会いを―。はたして、ユミルはどう動くのか!?', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10fc1fe4-2300-4aef-a18d-26e75e1fd7d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4065e08-89dd-4417-b077-37111c5eb192', '9149363a-a464-4651-89a7-91d32e7292cc', 36, '100002971', '突撃', '森に突入しようとしていたエルヴィンの前に姿を現す、鎧の巨人。その肩には、ある人物の背中に括りつけられたエレンの姿があった。巨人に連れ去られる前に、何としてでもエレンを救い出そうとする調査兵団。しかし、鎧の巨人とその協力者に攻撃を仕掛けるミカサを、もう一体の巨人が何度も妨害するのだった。その巨人を殺さなくてはならないと、敵意を剥き出しにするミカサ。彼女の前に立ち、戦いをやめるよう呼びかけたのは―!?', '2017/07/01 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e1cbd20-b4ce-48cd-a270-9991a3663e01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17a81a4b-bfbd-45f6-80c4-926335510fd5', '9149363a-a464-4651-89a7-91d32e7292cc', 37, '100002972', '叫び', '【シーズン2 最終話】エルヴィンが引き連れてきた巨人の大群が、鎧の巨人に襲いかかる。まるで地獄のような光景が繰り広げられる中、調査兵団はエレンの奪還に何とか成功した。だが、退避する兵たちに向けて、鎧の巨人が他の巨人を投げつけてくる。その衝撃で落馬したエレンとミカサの前に出現したのは、5年前のあの日、エレンの母･カルラを食った巨人だった。憎き仇との因縁に自らの手で決着をつけるため、エレンは巨人となって戦おうとするが…。', '2017/07/01 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26391420-4f0b-47ab-a8b8-2e8e03a58408.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('792e1e48-7331-4f86-a6b1-6ca73f837cc9', '0ec12696-8c5f-4b8f-89d7-89cbfc8996b1', 'hulu-attack-on-titan-s3', 'シーズン3', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c620f4c-bc61-46a8-a535-a03af0522685.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1ea017b-6fd6-4883-a4c1-49209e265bce', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 38, '100025644', '狼煙', 'エレンたち104期生は新たにリヴァイ班へと編入されることになった。ウォール･マリアに開けられた穴を塞ぐという当初の目標を達成するため、巨人化したエレンの体を自在に硬質化する方法を探る実験を進めるハンジだったが、そこへニック司祭が何者かに殺されたという知らせが入る。ニックの殺害が憲兵団の手によるものと断定したハンジの報告を受けたリヴァイのもとに届く、エルヴィンからの手紙。そこに書かれていた内容とは…?', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c620f4c-bc61-46a8-a535-a03af0522685.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4bd6016-4797-4cea-b719-b7c07e3dfbd9', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 39, '100025645', '痛み', 'エレンとヒストリアを乗せた馬車が襲撃され、そのまま二人が攫われてしまった。追おうとするリヴァイの前に立ち塞がる謎の男。その顔を見て、リヴァイは「ケニー」と叫ぶ。どうやらリヴァイにとって、過去に因縁のある相手らしい。二人の戦いは、まさに相手の命を奪おうとするものだった。巨人対人類ではなく、人類同士が立体機動装置を用いて行う死闘。その信じられない光景を目撃したジャンたちもまた、戦闘に巻き込まれていく。', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abe29c85-d7b6-4c7b-92fd-722c74d53204.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ad9f805-12bb-4407-9184-11aa1e233077', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 40, '100025646', '昔話', '攫われたヒストリアが目を覚ますと、そこには彼女の父親を名乗るロッド･レイスという中年の男がいた。ロッドはヒストリアを抱きしめながら、レイス家にまつわる重大な秘密を打ち明ける。一方、ハンジも捕らえた憲兵の口を割らせて、レイス家の秘密を掴んでいた。今後の方針を決定するため、エルヴィンにレイス家の情報を伝えようとするハンジ。その頃、エルヴィンはピクシスと面会し、人類の歴史を動かす決意を表明するのだった。', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d63cf174-fa76-456a-8124-a878904632d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52476e5c-5a6b-4672-aa8a-320cb43c7d4b', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 41, '100025647', '信頼', '憲兵団の策により、民間人を殺害した罪を着せられてしまった調査兵団。彼らが潜伏する森の中に、見回りをしていた男女二人の憲兵、マルロとヒッチが足を踏み入れる。水汲みをしているアルミンを発見するも、逆にリヴァイたちによって拘束された二人。だが、憲兵団のやり方に疑問を感じるマルロは調査兵団への協力を申し出る。リヴァイは二人の身柄をジャンに預けるが、ジャンは彼らのことを信用しておらず、ナイフを向けてしまう。', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6e59968-97b8-4d1a-adad-617fda9f5c26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32dcff7e-1e1d-4435-b6e4-dec5f6dfab5f', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 42, '100025648', '回答', 'ついに調査兵団の命運が尽きようとしていた。中央憲兵に追い詰められ、エルヴィンの処刑が執行されようとしていたのだ。王の間にて、最後の裁判を受けるエルヴィン。調査兵団を失うということは、人類の矛を失うことを意味する。―エルヴィンの主張に誰も耳を貸そうとせず、処刑台へと連行されそうになった矢先に、超大型巨人と鎧の巨人がウォール･ローゼを突破したとの情報が入る。はたして、人類の未来を託すべきは誰なのか!?', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b06a61b9-5e67-4dad-8f33-64643caa3d36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d09f811b-8d90-4742-b0df-678127cb9167', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 43, '100025649', '罪', 'どれほどの時間が経ったのか。礼拝堂の地下で目を覚ましたエレンの体は鎖で拘束され、目の前にはすべての記憶を取り戻したというヒストリアが、ロッドと並び立っていた。ロッドとヒストリアの手が背中に触れたことで、エレンの脳内に浮かび上がってくる忌まわしき記憶。それは、5年前のある夜にレイス家を襲ったという悲劇の真相だった。あの夜、ロッドから家族を奪ったのはエレンの父、グリシャ･イェーガーだというのだが…。', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f1979f3-52bd-46c1-905d-3e0b427360c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b113e402-4bd8-4cf7-b21d-311396971497', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 44, '100025650', '願い', 'ロッドが語るレイス家の真実。何代にもわたって受け継がれてきた巨人の力は今、エレンの中にあるという。ヒストリアは叫ぶ。その力を手に入れ世界の歴史を継承し、この世から巨人を駆逐することこそが自分の使命だと。一方、真実を知ったエレンは償いきれない罪を犯してしまったと涙を流し、人類の命運をヒストリアに託す覚悟を決める。そんなエレンの想いを受けたヒストリアは、ロッドのもくろみ通り巨人化してしまうのか?', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a86bf77b-b0ef-4a5a-a1a0-0e6ef627227f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9bda5ea7-b5b4-4fad-8634-4ed3b34fde81', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 45, '100025651', 'オルブド区外壁', 'ヒストリアはロッドに逆らい、エレンを連れて礼拝堂から脱出しようとする。すると、床にこぼれた薬品を体内に取り入れたロッドが巨人化してしまった。その衝撃で飛ばされるヒストリアと拘束されたままだったエレンを、駆けつけた調査兵団の仲間たちが救う。そうしている間にもロッド巨人の体は形成されていき、その大きさは超大型巨人をも超えるものとなった。仲間が危機に直面したとき、エレンは再び自分を信じることを選択する。', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/29a93a84-99c0-4e8c-8e7e-05ac25360f5e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca1ca9e9-be52-477f-b943-f4e35c60dba7', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 46, '100025652', '壁の王', 'エレンは仲間を守ることができたが、同時にロッド巨人も地上に出てきてしまった。高熱を発し、周囲の木々を焼きながら、ロッド巨人はゆっくりと歩みを進める。その先にはオルブド区があるが、エルヴィンはあえて避難指示を出さずに巨人を迎え撃つ作戦を立てる。被害がウォール･シーナの中心部にまで及ぶことを防ぐためにオルブド区の住民をおとりにしつつ、ひとりも死傷者を出さないという困難な戦いに、調査兵団が立ち向かう。', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50743067-9d83-4033-940f-f0a40765b6bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7700d81-b4bf-4c13-a8b0-d50b5ab3f50c', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 47, '100025653', '友人', 'ロッド巨人は倒され、自らとどめを刺したヒストリアは住民や兵士たちの前で自分が真の王であることを宣言する。その頃、礼拝堂の崩落現場から脱出したケニーは大量の血を流し、息も絶え絶えになりながら横たわっていた。ケニーの脳裏に浮かんでは消える自らの壮絶な生涯―。ふと気がつくと、目の前にはリヴァイが立っていた。ケニーは生きるための最後のあがきをするかのように、巨人化する薬品の入った注射器を取り出すのだった…。', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19699928-73ac-47b7-83af-b84c04404bbb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b14e093b-4674-4ae0-b6a8-eb2dd81d4fa1', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 48, '100025654', '傍観者', 'ヒストリアの戴冠から2ヶ月。牧場で孤児たちの面倒を見るヒストリアは、人々から親しみを込めて「牛飼いの女神様」と呼ばれていた。調査兵団ではエレンが得た硬質化の能力に関する実験が行われ、対巨人兵器の開発に成功する。度重なる実験は体に大きな負担を強いるものだったが、エレンは、巨人を一掃できるなら自分の身が削られることなどいとわない覚悟を見せる。そして、ある人物のことを思い出すのだった。', '2018/11/01 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7a25094-4958-4fb2-9ad0-4fb1cae984a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58845271-53d4-421d-a486-eea3e9691cc5', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 49, '100026318', '奪還作戦の夜', '調査兵団の悲願であるウォール･マリア奪還作戦は、2日後に決行されることとなった。リヴァイは手負いのエルヴィンに対し出陣を控えるよう進言するが、エルヴィンは固辞。「この世の真実が明らかになる瞬間に立ち会わなければならない」と語るエルヴィンの強い意志に、リヴァイも納得してその場を去るのだった。その夜、兵舎で盛大な宴会が催され、英気を養う兵士たち。エレンたちはここまでの戦いを振り返り、決意を新たにする。', '2018/11/01 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4795f315-a6eb-4bbc-b1d1-f61b3323dae8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07bc2e7b-e170-46bc-92cf-aa146994c32e', '792e1e48-7331-4f86-a6b1-6ca73f837cc9', 50, '100038342', 'はじまりの街', '夜陰に乗じてウォール･マリアをめざす調査兵団。深い眠りにつく巨人の横を通り抜ける一同の中で、エレンはひとり呼吸を乱していた。「もしも奪還作戦に失敗したら?」「自分は人類を救えるのか?」―震えるエレンに声をかけたアルミンは、エレンとこれまでのことを振り返る…。', '2019/08/01 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/541877d8-d343-4595-ac2b-88ade594f3b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6bfe1344-6c7c-49ac-9e2e-a47aa3d4a16e', '進撃の巨人', '', 'hulu', 'attack-on-titan-oad', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2714e695-f91f-48bd-ab9d-f10754770559.png?w=331&h=447&p=t', 'hulu', 2013, 1, 1, 'FINISHED', NULL, 16498, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3b749afa-d967-4b10-873a-5e1b000654ce', '人外教室の人間嫌い教師', '', 'hulu', 'a-misanthrope-teaches-a-class-for-demi-humans', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92bafffd-0bc3-41cb-9629-97cddd0de84c.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'RELEASING', NULL, 198374, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c3f55d17-2717-4e1c-95b5-70ce8cc13f11', '3b749afa-d967-4b10-873a-5e1b000654ce', 'hulu-a-misanthrope-teaches-a-class-for-demi-humans-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a450422f-7db7-493c-907b-544ec83a5c4d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53e7bf21-2a99-47b5-bd64-3559fc7e20c0', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 1, '100250784', '人間嫌いと邂逅の教室', 'とある出来事から教師を辞め、二年間家に引きこもっていた人間零。新たな仕事を探し始めて見つけた職場は、なんと人外の女の子たちがニンゲンになるための学校で……?', '2026/01/16 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a450422f-7db7-493c-907b-544ec83a5c4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da32f9d9-5e8a-498f-86f5-ca9c10b9518a', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 2, '100251481', '人間嫌いと泡沫の花冠', 'ヒトマは担任として、生徒たちの様々な一面を知ることになる。ダンスがしたいからニンゲンになりたいと話す鏡花だが、その腕前はお世辞にも上手といえるものではなかったようで……?', '2026/01/23 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d7f342f-4463-4d1d-8d52-5764a2b8a214.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fedf1360-95bc-44a7-9aaa-ec4725c06f0f', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 3, '100252109', '人間嫌いと一輪の孤城', '物静かな一咲と、ハイテンションないさき。あまりに異なる様子に驚きながらもヒトマは二人の共通点に気付く。放送後、ヒトマはいさきにニンゲンになりたい理由を尋ねるのだが……?', '2026/01/30 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2b9edc8-ffae-4fa0-8fa1-d028adc5f20d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4f78d3b-f14a-4cd0-a248-1ce69c491211', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 4, '100252732', '人間嫌いと天使のほうき星', '校長に呼び出された右左美とヒトマは、右左美の恩人の容態が芳しくないと知る。今の姿のままでは学校の外に出られない右左美は、ヒトマにとある秘密を打ち明け恩人へ会いに行く手助けを求めるが……?', '2026/02/06 02:40:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a45a73be-1456-454c-87f4-7d5959e93921.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e41ecff3-81a0-488b-aa56-c2b9ed11616e', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 5, '100253337', '人間嫌いと福音の帳', '上級クラスでトップの成績のトバリが、授業中に体調不良を訴え保健室に行く。どうやら毎年同じ時期に調子を崩すらしい。様子を見に来たヒトマにトバリは教師生活について問いかけて……。', '2026/02/13 02:40:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1ec55d3-9265-40a1-a648-757adb7fc4f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54f6ddea-231b-4963-a622-27e3a102f80d', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 6, '100253850', '人間嫌いと黎明の光', '年度末が近づいてきた上級クラスの生徒たちに、卒業のための最終課題が出される。皆が苦戦しながらも進めていく中、自分の力で解決することにこだわる鏡花。たまらずヒトマは声をかけるが……?', '2026/02/20 02:40:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c4740cf-7d39-4c1b-bd75-e81c02e3c1c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b735f0fe-8390-4388-b780-318b7f4addb7', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 7, '100254758', '人間嫌いと徒花の恋占い', '卒業生を送り出したヒトマは、新年度に向けて動き出す。上級クラスには新たに、龍崎カリンと根津万智、黒澤寧々子が進級するが、なんと初日からカリンがヒトマに告白をして……!?', '2026/02/27 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74a3b162-5646-4d81-84e3-a520caf21b76.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('432fa2bb-b249-47d5-8396-a78deb42042b', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 8, '100255619', '人間嫌いと安寧の魔法', '夏休み、学校の敷地内でキャンプをする上級クラス。生徒たちはバーベキューや飯ごうなどを満喫する。その夜、一人夜空を眺めていたヒトマを、トバリは学校が始まったきっかけの場所に連れていき……。', '2026/03/06 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/937b3618-8231-482b-b4ac-6b10b4bf79ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2fba104-a0f4-4822-a2c4-13a882fb02be', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 9, '100256436', '人間嫌いと真心の本懐', '今年も最終課題の時期がやってきた。各々悩みながら与えられた課題に取り組みはじめるが、何かと騒がしい万智に右左美がつい大声で怒鳴ってしまい……?', '2026/03/13 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/746eefbf-6bb0-45bd-b9e7-9668ad27acd6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6b9531e-7527-4d7e-9115-a40fc2ac2413', 'c3f55d17-2717-4e1c-95b5-70ce8cc13f11', 10, '100256877', '人間嫌いと巡礼のほうき星', '上級クラスの生徒たちは一咲の卒業式を前に、いさきの卒業式も行おうと、一咲に隠れて準備していた。そして無事に卒業式と終業式を終えた後、ヒトマは右左美からある相談を受けて……?', '2026/03/20 02:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1cb90818-f67b-4128-886e-b0f4facfc9f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d6cb87bb-2791-40c6-ac9e-136c5ad48bf2', '人間不信の冒険者たちが世界を救うようです', '', 'hulu', 'ningen-fushin-adventurers-who-dont-believe-in-humanity-will-save-the-world', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7813f1b-1589-41ea-87fa-2dacc3440b4e.jpg?w=331&h=447&p=t', 'hulu', 2023, 0, 1, 'FINISHED', NULL, 137909, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 'd6cb87bb-2791-40c6-ac9e-136c5ad48bf2', 'hulu-ningen-fushin-adventurers-who-dont-believe-in-humanity-will-save-the-world-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52e5328d-04f9-4554-8125-c2d39af3b993.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce254396-62f6-430f-8018-b06fe979676a', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 1, '100133889', '人間不信の冒険者たち', '冒険者のニックは長年所属していたパーティー“武芸百般”から追い出され、恋人にも捨てられ、失意の中にいた。立ち寄った酒場で相席した連中も似たような辛い境遇を持っていた。人間不信な者たちの、再生の物語が今始まる……!!', '2023/01/10 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52e5328d-04f9-4554-8125-c2d39af3b993.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5add9c0-79b3-4ee5-aad6-7b2e25489eca', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 2, '100134624', '最強パーティ結成? サバイバーズ!', 'それぞれの趣味と日々の暮らしを守るため組んだ即席パーティー。彼らは“サバイバーズ”と名乗り、早速迷宮探索に挑むが……。互いを信じきれず疑心暗鬼な状態の彼らに容赦なく魔物たちは襲ってくる。彼らの運命は!?', '2023/01/17 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ba937f3-52af-48a4-b81e-5fe41e5f818b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2f547ae-8976-49a1-9d5a-42f30c85d5ce', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 3, '100135165', 'カランの秘密', '竜人族の使命、それは勇者となる人間に仕え、世界を救うこと。カランはその使命を託せると信じた仲間に裏切られ、捨てられた過去があった。解き明かされるカランの境遇。サバイバーズの仲間たちは彼女の救いとなれるのだろうか?', '2023/01/24 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f94aeace-6f3b-4a6e-9adb-071583cbe344.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d8988fe-c8dc-4076-9176-4d140849af76', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 4, '100135752', '絆の迷宮', 'パーティーとしての信頼も生まれ始めたサバイバーズ。そこにヴィルマから伝説の“絆の剣”の回収依頼が舞い込んだ。迷宮内を進む彼らの前にいよいよ目当てのものが現れるのだが、なんとその剣がしゃべり出し……??', '2023/01/31 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c5b5415-964e-440f-990c-8cd4b6732f1b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb638df3-88e4-49fe-8f5a-dbccfcfb79e2', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 5, '100136170', '鉄虎隊、相まみえる。', 'かつてニックを騙していた元恋人のクロディーヌは“鉄虎隊”というパーティーに所属していた。ニックを挑発してくる彼らにサバイバーズも殺気立つが、やがて事態は鉄虎隊の獣人、レオンとニックの一騎討ちとなり……。', '2023/02/07 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf03e627-e950-47d3-98f6-95f65fb1955f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43f905a5-0d89-45c1-9f6c-75954c377364', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 6, '100137012', '算数ベアナックル', '算数と拳闘の対決を同時に行う“算数ベアナックル”。サバイバーズは決戦当日まで特訓と相手チーム調査に尽力していた。そんな中見えてきたのは鉄虎隊の不正疑惑。そこに目をつけ戦略を巡らせるサバイバーズだが、果たして……!?', '2023/02/14 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2076c6e1-796d-4af4-a6ae-fc0f51857801.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afbfa813-0184-4e4f-b749-8286eef415d8', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 7, '100137689', '賭博指南', '投獄されたレオンは秘蔵の“滅の剣”の力を借りて脱獄に成功する。剣の力で凶暴化したレオンが向かったのはニックたちのいるカジノだった。新たなる力を手に暴れ回る彼にもまた、克服できない過去があった。レオンを止めるのは……!?', '2023/02/21 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89ad6a6e-a869-4afb-bcf1-dc8435856940.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f47be202-3e70-4a4f-8209-ab14b3d48d9b', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 8, '100138136', '麗しのパラディンさま', '客のいない酒場で歌うベル･ハギンズの前に現れたのは、アイドルデビューをそそのかす一人の男だった。アゲートとしてアイドルの成功をつかんでいくのだが、私生活は変わり始めていく。そんな中、立ち寄ったカジノで事件に巻き込まれ……。', '2023/02/28 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3086a994-c053-40c7-a30c-e080dcb33ffa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b54ba8fc-6497-4175-bb52-417bc2bf38f2', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 9, '100139374', '迷宮都市伝説 ステッピングマン!?', '迷宮都市に広まる謎の怪人“ステッピングマン”の噂。都市伝説のはずが、襲われる少女をゼムたちが救ったことで、その存在が現実味を増してくる。手がかりを求めサバイバーズは、あらゆる犯罪が集まるという無法地帯“ガーベージコレクション”に向かう。', '2023/03/07 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/736dd5c7-3742-408d-96f9-a124a13647c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8273e88c-02d8-46c1-85c2-7df50541072a', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 10, '100140052', '迷宮捜査網', '怪しい都市伝説を扱う雑誌編集者、オリヴィアの正体はステッピングマンだった!? 真相究明のため情報を集めたサバイバーズは死体安置所へと向かうが、それを阻むように襲来したのはやはりオリヴィア! 果たしてステッピングマンの正体は!?', '2023/03/14 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb3bb0d5-b41c-4cef-bc9e-37735e4b31a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1a5d43a-5be4-4657-a1a1-f15e7f2a4d90', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 11, '100140546', 'サバイバーズVSステッピングマン', '遂にたどり着いたステッピングマンの正体。彼を廃工場内へと追いつめたサバイバーズの前に現れたのは、黒い鎧に身を包んだ怪しげな男。圧倒的な力を見せつけられ、なすすべがないニックたち。絶体絶命のピンチを前にサバイバーズの総力戦が今、始まる!!', '2023/03/21 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07d3f7d3-f309-4b50-9ef7-aa0dbf4199ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee5ece86-99f9-46d1-ba46-b4e912e0186a', 'cf5a3d9c-2706-4b0c-9c7b-0c528a80d076', 12, '100140875', '冒険者はまだ世界を救えない', '【シーズン1 最終話】ステッピングマン事件の決着は、サバイバーズに必ずしも救いとはならなかった。改めて彼らが対峙するのは“過去と日常”。苦悩する彼らは、人類が避けて通れぬ難題にどう立ち向かうのか? サバイバーズの戦いは続く!!!!', '2023/03/28 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61f5c8c0-cdaf-402b-b994-16efc0d33fec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('79c0aea5-c196-437a-8045-d189f17f6042', '人造昆虫カブトボーグ V×V', '', 'hulu', 'artificial-insect-kabuto-borg-victory-by-victory', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/18beb569-e438-4822-9980-acd946082666.jpg?w=331&h=447&p=t', 'hulu', 2006, 3, 1, 'FINISHED', NULL, 17291, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5a41042e-f65f-44f3-8771-0d199f435632', '79c0aea5-c196-437a-8045-d189f17f6042', 'hulu-artificial-insect-kabuto-borg-victory-by-victory-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/34accbe7-fe7d-4968-b94d-83b1dc5fa18b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71f10a86-29bf-43ad-bbf6-560ce21a64d1', '5a41042e-f65f-44f3-8771-0d199f435632', 1, '100153238', '親父超え! 勇気のライジング･プロミネンス', '某大会、数々の強敵を倒し決勝戦へと駒を進めた天野河リュウセイ。決勝の相手は謎の組織「ビッグバン･オーガニゼーション」の総帥にして最強のボーガー「ビッグバン」。そのビッグバンに決勝を前に浴びせられた言葉「今のお前では私には勝てない!」。何が足りないのか悩むリュウセイ。又、ビッグバンの正体は何者なのか。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/34accbe7-fe7d-4968-b94d-83b1dc5fa18b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('34d5bc30-2fe4-41c4-bac0-d867f9df5d74', '5a41042e-f65f-44f3-8771-0d199f435632', 2, '100153239', 'さらば友よ! 涙のメタリック･ギガトン･クラッシュ', 'ボーガー仲間の勝治が突然リュウセイに挑戦状を叩き付けてきた。いつもは冷静な勝治には似合わないその挑発的とも言える行動に戸惑うリュウセイ。残り少ない人生を懸けた勝治の想いをリュウセイに伝える勝治の母親。その熱い想いに応えるためリュウセイは勝治の挑戦を受ける事を決意。静かだが熱い戦いが奇跡を呼ぶ。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/619734a8-7acc-4ed2-b72f-2dfb32f1379f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dafdce37-5eef-4d8c-bcb1-39c0bb94f042', '5a41042e-f65f-44f3-8771-0d199f435632', 3, '100153240', '守れ! 鉄壁のサイキック･ドラゴン･マスター', '近所にオープンしたライバル店の出現により売り上げ激減。閉店の危機に見舞われたケンの店を救う為に立ち上がるリュウセイと勝治。ところがリュウセイが暴走、勝手に店の存続をボーグバトルの試合に賭けてしまった。ところが相手の中華三兄弟はボーグバトルの賞金を開店資金にしていた強者ボーガーだった。店の存続を賭けた三本勝負が始まる。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4d72846-3ad4-4a26-af58-2d0851553460.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d617680f-77ca-432d-96ef-51ea7bd5efcb', '5a41042e-f65f-44f3-8771-0d199f435632', 4, '100153241', 'ライバル登場! 必殺ヴァリアブル･ルルド･ウォーター', 'リュウセイ達の住む町に突然現れた流れ者ボーガー「ジョニー」。次々に町のボーガー達が倒され、ついにリュウセイ達の前に現れ挑戦してきた。ジョニーの正体を調べるべく町の情報屋「ジェニファーの店」に向かうリュウセイ達。そこには意外にもジョニーの過去を知る女が働いていた。ジョニーの目的は何か、過去は。やがて強敵との決戦の日がやってきた。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e5f88bb-d1be-4b06-98d0-ea1c68d04b17.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e65d91a-d814-4a64-8b80-df47ec40649c', '5a41042e-f65f-44f3-8771-0d199f435632', 5, '100153242', '目覚めろ! ボールディング･トリプル･スクリュー', '柄にも無く勉強とボーグバトルの両立について語り合うリュウセイ達。そこにリュウセイの父親･大輝が現れ「両立を目指すなら塾に来てみないか」と言葉をかけた。リュウセイの父親は塾も経営していたのだ。しかしその正体は塾生達を各界の中枢に送り込み世界支配を目論む秘密組織だった。その野望を打ち砕くため立ち上がるリュウセイ達。その前に立ち塞がる同級生エリート3人組。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c64bd1a-bdea-43bb-88ce-a81cb05f35fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8987f92a-5c49-46e7-8350-adfc39e4fab1', '5a41042e-f65f-44f3-8771-0d199f435632', 6, '100153243', '魂の叫び! トワイライト･フレンドシップ･ソウル', '突然、お米以外の主食を禁じる条例が発令された。パンを食べられなくなったロイドは町を出ると言う。「そんな理不尽は許せない」と立ち上がるリュウセイと勝治。主食の選択権を賭けボーグバトルの勝負が始まる。雑魚ボーガーを倒した後に立ち塞がったのは親友のケン。中華料理屋の息子が何故…。何かに憑かれたように戦うケンにさすがのリュウセイも大苦戦。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d53a86b-16c1-41ec-b06e-732e9b372427.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f52c2639-afd1-45da-aa80-7d61f0fe7d54', '5a41042e-f65f-44f3-8771-0d199f435632', 7, '100153244', '涙の素パスタ! オーバー･ザ･レインボー', '近所に開店した大型回転寿司の店。余興としてのボーグバトルにリュウセイの名が。初めは気乗り薄のリュウセイだったが「お寿司食べ放題」に俄然やる気満々。さらに挑発に現れた謎の天才美少女ボーガー「ベネチアン」に闘志を燃やす。しかし対戦相手のベネチアンの正体を知ってしまったリュウセイは試合での精彩を欠く。リュウセイの試合ぶりにプライドを傷付けられたベネチアンの猛攻が始まる。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51b1687e-99cf-4982-9d5b-cc7cb489d3a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b43346e5-361b-4a06-8024-0d9e6fcad69e', '5a41042e-f65f-44f3-8771-0d199f435632', 8, '100153245', '鎮魂歌! リビング･レジェンド･グッド･ナイト', '生死の境をさまよう勝治。そこに突然スクータで病院に乗り付けた老人が一人、勝治の祖父だった。奇跡的に回復した勝治につれられロイドの店にやってくる。たまたま手にしたカブトボーグでリュウセイにあっさりと負けてしまうがどうにも収まらない。翌日改めて勝治を参謀にリュウセイに勝負を挑む事になった。60年の充実した人生と輝ける将来との激突。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d19d5ca2-6b40-4361-9294-72a702b6f203.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bbe4e17c-214f-4096-b833-941e111efd56', '5a41042e-f65f-44f3-8771-0d199f435632', 9, '100153246', '輝け! ダイヤモンド･ダイヤモンド･ダイヤモンド', 'リュウセイの同級生、石田一の様子がおかしい。憧れの班長、相馬友子に頼まれて一肌脱ぐ事になった勝治。原因は石田の母親がボーグバトルに夢中になり家庭を顧みない事だった。不良主婦の溜り場「ボーセン」に乗り込み、そこのボスとして君臨する石田の母親に勝負を挑む勝治。果たして勝治の勝負と恋の行方は如何に。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a37d66c3-b069-4f83-8cd0-e0a93b9c2fe7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('544d5357-ec4f-4b2e-b108-5f5a430756ca', '5a41042e-f65f-44f3-8771-0d199f435632', 10, '100153247', '兄弟対決! ディープ･ギャラクシー･アタック', 'リベンジに燃えるガルフストリーム笹本との対戦中に突然現れた若い男。次々にマシンを蹴散らし打倒リュウセイの言葉を残し去ってゆく。男の正体をつかむ為にリュウセイ達は早速「マダム･ジェニファーの店」へと出掛けてゆく。そしてそこに現れたビッグバン。そこでリュウセイが初めて知る驚愕の事実。はたして男の正体は。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7da374ec-92ad-4584-8735-02f5192b0fe0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39c1bb07-f4bd-452d-8696-ad8cfa82c7c4', '5a41042e-f65f-44f3-8771-0d199f435632', 11, '100153248', '最強の名! マッドネス･デュプティ･スクリーミング', '突如夜の街に現れた正体不明のボーガー「ボーガーX」。今日もまたオプションパーツ狩りの犠牲者が一人。傍若無人なその振る舞いにリュウセイ達が立ち上がる。しかし神出鬼没の敵に対し何ら有効手段が掴めない。そこにかつての「ボーガーX」を知ると言う女性の登場。「彼を止めて!」の願いを背に戦いの火蓋が切られる。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/853a37ac-4c75-4640-9d1a-8c954997051b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c601f37c-35e1-433d-8fb5-29c9b5ab3482', '5a41042e-f65f-44f3-8771-0d199f435632', 12, '100153249', '過ぎ去りし日! チャコール･グレイ･フォルクローレ', 'ロイドの店に届いた一枚の手紙。差出人は、ロイドの若き日の仲間･シェリルだった。ロイドのかつての盟友ロバートが、悪の組織のボスになったことを告げるシェリル。ロイドはシェリルに、ロバートを止める様求められるが拒絶する。しかしリュウセイの熱い言葉に心を動かされ、封印していたマシンを手にする。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e000a41-730c-42aa-afc1-0ec90288a639.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b23b59c-7d92-4e0d-a7f4-1f65f5c4164f', '5a41042e-f65f-44f3-8771-0d199f435632', 13, '100153250', '夢を諦めない! フラッシュ･ドリーム･エボリューション', 'ビッグバンの留守中に街の支配を目論むドクター･ネオが現れる。その野望を阻止すべく立ちはだかるケン、勝治。一方リュウセイは新たな必殺技を身につけるべく、ボーグ仙人の下で激しい修行を積んでいた。ドクター･ネオは、ケン、勝治に勝利し、彼らの夢を否定する。そこへ、ついにリュウセイが現れた。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e75fb612-09cd-4397-96b6-b64ea6ad25e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e67719b-4090-48c4-b929-b10c96f46147', '5a41042e-f65f-44f3-8771-0d199f435632', 14, '100153251', '敗北そして崩壊…ロストワールド･エンドロール', 'ブラックゴールド団による世界征服の野望を砕くため、敵の本拠地に乗り込むリュウセイ、勝治、ケン。様々な障害を乗り越えて進む中で、一緒に戦うかつての対戦相手、ライバル達は次々倒されてゆく。彼らの想いを背にした3人は、ついに基地の心臓部へとたどり着くが…。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3858314c-88a9-4521-ae39-b10f3cbe1399.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21b3118e-4b0f-4759-bf8a-86b39a3bb252', '5a41042e-f65f-44f3-8771-0d199f435632', 15, '100153252', '開幕! トータル･ブリリアント･カリズマティック', 'ボーグバトル全国大会に向けての地区予選が始まった。今まで対戦して来た強豪達も全てこの地区大会に参加する中、リュウセイは再会した山田･ジョニー･一郎と決勝戦での対戦を誓い合う。そんな中、意外すぎる選手が勝ちあがっていた…。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/516723ce-d922-4a3e-bc23-09e365a508bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b464897-7a20-4fe5-89f2-fd64fa418fa9', '5a41042e-f65f-44f3-8771-0d199f435632', 16, '100153253', '美しき! リゾート･デンジャラス･サンセット', '全国大会へ向けての気分転換のため、海辺の静かな漁村の民宿に出かけたリュウセイ、勝治、ケン、ロイド。しかし村ではお年寄りの楽しみとしてボーグバトルがとても盛んだった。しばらくボーグバトルから離れていたかったリュウセイは必死に逃げる。しかし村のいたるところで老人たちが待ち構えていた。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76440996-e480-439e-af44-ff7a4070e536.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4011944a-e7d9-4e9e-8028-cb35b457c1f2', '5a41042e-f65f-44f3-8771-0d199f435632', 17, '100153254', '頂上決戦! クライミング･ハイリスク', '富士山を舞台に開催される全国大会。その前日、リュウセイはビッグバンの挑発にまんまと乗ってしまった結果、信じられないハンデを背負い戦うことになってしまう。圧倒的不利な状況下で、果たしてリュウセイは勝ち進むことができるのか?', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e43a44a-4dd2-4572-a846-a118771d7b4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb704b26-99bf-4451-bb94-269e93fc8506', '5a41042e-f65f-44f3-8771-0d199f435632', 18, '100153255', '旅立ちの時! クライング･ロンリー･ウルフ', '決勝戦に進んだリュウセイの相手は、ヨーロッパで活躍するビデ田中。リュウセイはビッグバンの「お前は海外に出たことがあるのか! 世界の壁を知れ!」という言葉に自信を失う。必死に励ます仲間たち。そこへ世界レベルの黄金のカルテットが登場した。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0d650ea4-cab9-425e-8187-8ca5b87153fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77c94f10-a8e1-4cfe-a572-ad2d0f9aea08', '5a41042e-f65f-44f3-8771-0d199f435632', 19, '100153256', '華麗なる! ツインズ･バスト･ウエスト･ヒップ', '日本チャンピオンになったリュウセイは一躍人気者に。勝治、ケンはいつの間にかリュウセイの雑用係の様な存在になり、リュウセイとの友情に疑問を持ち始める。そんな中、リュウセイの人気に目をつけ、ボーグバトルでリュウセイを倒すことで芸能界デビューを目論む、双子の姉妹が現れる。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a25372d1-62d7-4486-8252-9381b176bdf5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6cc3415b-c085-446f-9080-ffc5692fdcf3', '5a41042e-f65f-44f3-8771-0d199f435632', 20, '100153257', '美食の殿堂! ルブラン･パセリ･グレイビーソース', 'はす向かいに出来たフレンチレストランの為に、またしても昇竜軒は経営不振に。そのピンチを救う為乗り出すリュウセイ達。フレンチ店のオーナーが撤退条件として出してきたのは、ライバルとのボーグバトルに自分を勝たせることだった。コーチを引き受けたリュウセイだったが…。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2559199-648a-48e6-aea0-61c625e9e5ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b75db67-be38-48b0-b6ac-742c3824a53d', '5a41042e-f65f-44f3-8771-0d199f435632', 21, '100153258', '変わらぬ愛! フォーエヴァー･ライトニング･シンフォニー', '病院でボーグバトル禁止を言い渡される勝治。もうその体は激しいバトルには耐えられず、命の危険さえあるという。落胆する勝治の前に、シルクハットの伯爵が現れる。伯爵は、勝治の病状を見透かしたように、エレクトリカルスピードワゴンを譲ってほしいと持ちかける。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb957dca-f07d-4244-ab34-039c819c53b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('451be910-9a35-4ccd-aadc-6c3e61f4eb17', '5a41042e-f65f-44f3-8771-0d199f435632', 22, '100153259', '健康第一! ベジタブル･ジャーマン･スープレックス', '野菜嫌いなリュウセイに対して、ロイドは世界大会における3大伝説を語る。それは全て食べ物の好き嫌いにより勝負が決した話だった。しかしリュウセイは聞く耳を持とうともしない。ロイドは野菜ボーグを通販で取り寄せ、リュウセイと練習試合を組んでみることにしたが…。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c37396b-916d-4f8a-bbfa-7173e0bcbc14.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('138be07c-97bd-47a3-90a6-615da00636ba', '5a41042e-f65f-44f3-8771-0d199f435632', 23, '100153260', '筋肉少年隊! スイート･マスキュラー･ペイン', 'パワーをつける為のトレーニングを模索するリュウセイたちは、ボディビルの特訓をはじめる。トレーナーのバーバラのもと、リュウセイ、勝治、ケンの3人とも、面白いように筋肉が付いてゆき、いつの間にか目的がボディビル大会への出場へとすりかわっていった。そこへビッグバンが現れる。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b8647f5-ca96-49fd-b88d-837c154312e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f331d9b-9b9d-462d-ae76-de7129a01d00', '5a41042e-f65f-44f3-8771-0d199f435632', 24, '100153261', '試練! ワンダー･ミラクル･ハート', 'リュウセイの前に現れる偽者リュウセイ。次々に現れてはリュウセイにバトルを挑む。実はリュウセイを鍛える為の試練だった。何も知らないリュウセイは戦いを進めるごとに、本当の自分がわからなくなっていった。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c058c4b5-514a-479a-87ca-3715a6793190.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11162894-674b-41bd-904f-907cabf16364', '5a41042e-f65f-44f3-8771-0d199f435632', 25, '100153262', '歴史は! ナイト･スクープ･モーニング', '世界大会を控えたリュウセイのもとに、ボーグバトルマンが現れた。彼は日本代表のリュウセイに、教養をレクチャーし、日本の恥をさらすことにならない様、カブトボーグ協会より派遣されてきたのだ。リュウセイの激しい抵抗も虚しく、ボーグバトルマンによる、カブトボーグの歴史、そして起源についての講義がはじまった。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2cd6365b-26c1-4a6d-899f-a6da9636b4a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6bf3003-c4d7-437c-9aba-65ea1fccd171', '5a41042e-f65f-44f3-8771-0d199f435632', 26, '100153263', 'さらば祖国! ネヴァー･フォール･イン･ラヴ･アゲイン', 'ケンは不良に絡まれていた少女･ミノリを助け、一目惚れしてしまう。楽しいデートの日々を送るケンだったが、リュウセイの世界大会出場に帯同するため、出国の日が迫っていた。恋と友情の狭間で悩むケン。果たしてケンが選ぶのは、ミノリとの恋か、リュウセイとの友情か?', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/651011f1-5f99-4f7a-bd2d-c112fe5214e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8de99dec-42e4-4c20-86b5-d02ef2532cff', '5a41042e-f65f-44f3-8771-0d199f435632', 27, '100153264', '壁! ハイエスト･オナー･オブ･グローリー', 'ボーグバトル世界大会の為、N.Y.にやってきたリュウセイ達は、街角で行われていた子供達の草ボーグに何気なく参加。しかし何度対戦しても全く歯が立たない。その頃、日本のカブトボーグ協会でも、ある大きな問題が提起されていた。このままでは日本代表のリュウセイには勝ち目がない。壮大なプロジェクトが今、始まる。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c49583c-ee6d-4d69-848c-c04a33e1bab9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21d5fc0c-4c8d-4ae4-852d-b87a377cffb2', '5a41042e-f65f-44f3-8771-0d199f435632', 28, '100153265', '新たなる盟友! フルスペック･ワールドワイド･レスポンス', 'いよいよ世界戦。ビルの頂上を目指し、先着16台が決勝リーグに進出、残りは脱落という過酷な戦いがはじまった。新しいマシンを手にしたリュウセイだったが、各国代表のライバル達に大きく引き離される。焦るリュウセイに対して、アメリカ代表、ジャンマイケルが衝撃の一言を放った。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e803ca2-05b3-43d4-9166-42dd236999d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7c6d682-0793-487f-8f08-2206d8c482c4', '5a41042e-f65f-44f3-8771-0d199f435632', 29, '100153266', '危険地帯! ダーク･バトル･ソルジャー', '決勝リーグ、次の舞台に向かう飛行場で、リュウセイのマシンが強奪された。犯人を追う勝治とケンがたどり着いた先は、何でもありのダークバトルが行われている地下の闘技場。犯人の少女、ジュディは母親の入院費ほしさに、リュウセイのマシンを奪って賞金稼ぎに来ていたのだった。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5fc26df-fc3f-4e22-a6f6-b086213a0dbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf57faa6-2d54-4a84-b21f-d28fe5f15f45', '5a41042e-f65f-44f3-8771-0d199f435632', 30, '100153267', '吼えろ! アフリカ･サバンナ･キリマンジャロ', '世界戦、次の会場はアフリカ･サバンナ。リュウセイの対戦相手はエジプト代表カメーダ･カーメダ。彼は、不思議なことに国内予選を1戦もする事も無くエジプト代表となり、世界大会出場を果たしていた。何も知らないリュウセイは、既にカメーダ親子の策略に陥ってしまっていた。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/792f3831-21ac-4cc5-80dc-352869090115.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c17223e-8171-4a6a-b89c-4cb2c5d6e833', '5a41042e-f65f-44f3-8771-0d199f435632', 31, '100153268', '王様は絶対! スキャンダラス･マジェスティック･エゴイズム', '世界戦ツアーの合間に、リュウセイ一行は、カブトボーグ好きの王様が治めるアマラオ王国に招待を受け、豪遊する。中でも勝治は大歓待を受けるうちに、ここに残りたいと言い出す始末。まだ試合を残すリュウセイ達は勝治と別れて出発する事に。そこに軍のクーデターと民衆の革命軍の蜂起が同時に勃発、王国はパニックに陥る!', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5130c787-a431-47d4-afcd-86094f4bdb0a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a35527de-c6ba-4d43-bedc-0be8444be446', '5a41042e-f65f-44f3-8771-0d199f435632', 32, '100153269', '準々決勝! ランニング･バックブリーカー･ストップ', 'ベスト8に駒を進めたリュウセイは、国際カブトボーグ連盟からの呼び出しを受け、大会に潜り込んだ敵対する団体からの刺客を探すことになる。リュウセイ達が怪しいと睨んだのは、準々決勝での対戦相手･英国代表のトーマス･アルバート。そして、激しいバトルの最中、ついにトーマスの意外な正体が明らかに…。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7861c0f-10d3-49cd-ab13-86fd2734608d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d1902de-c219-4341-9bd3-a58bbcc81096', '5a41042e-f65f-44f3-8771-0d199f435632', 33, '100153270', '栄光の! リベンジ･カムバック･ドライフラワー', '世界戦後、リュウセイたちは気晴らしに幼稚園に出かける。アイスクリームを懸けた園児たちとのボーグバトルで敗退するリュウセイ。勝治たちはわざと負けたリュウセイの優しさを誉めるが、リュウセイからは何と衝撃のボーグバトル引退宣言が飛び出した。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0601da8-0aab-45db-a195-233241a14ce7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab9b42ba-3d4e-4ff2-85b9-3007d71fa0f0', '5a41042e-f65f-44f3-8771-0d199f435632', 34, '100153271', '絆! ハンギング･アナザー･エグゼクティブディシジョン', '動物園でのイベントに招待されたリュウセイ。実は人気者の白熊「ピーク」とのボーグバトルだった。白熊とはいえピークはかなりの「実力者」。追い討ちをかけるように飼育係の低一とピークの心温まるエピソードに、観客は涙を誘われてしまう。絶体絶命のリュウセイ、その時――!', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64858326-42e4-4bb9-b98e-0182b62b8e92.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd896455-3816-476c-856f-664e867bb25d', '5a41042e-f65f-44f3-8771-0d199f435632', 35, '100153272', '愚兄賢妹! ストロベリー･チューカ･ッテユーカ', '学校に来ないケンを心配したリュウセイ、勝治が昇竜軒を訪ねると、中華料理からスイーツの店に様変わりしていた。オーナーはケンの妹リンリン。リュウセイ達は、中華料理店に戻す様、リンリンにボーグバトルでの勝負を挑むが、追い返されてしまう。ケンの屋台で寂しくラーメンをすする3人、しかしあまりの不味さに驚く。3人は昇竜軒秘伝のタレを捜しに、再び店に戻るが…。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ab9495b-7b7a-4563-a689-dd3505c6c9b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d529dc77-e7e8-4982-bf52-dafdb74ac25a', '5a41042e-f65f-44f3-8771-0d199f435632', 36, '100153273', '目に見えぬ敵! ロマンティック･インビジブル･ムード', 'ロイドの店に同じクラスの西山が現れ、リュウセイの宿命のライバル･ジョニーの襲撃を知らせる。新必殺技をあみだしたジョニーは、リュウセイとの対決を迫る。ひとまずジョニーをケンに任せたリュウセイは、勝治とともにマダム･ジェニファーの店へと急ぐ。そこで語られる驚愕の事実に驚く2人。一方ジョニーは軽々とケンを倒し、リュウセイを追う。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be189df9-5a33-485c-bacd-a9da50996a73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ab0feea-b937-40a3-9d0f-e01ddbff653a', '5a41042e-f65f-44f3-8771-0d199f435632', 37, '100153274', '真夏の夜の夢! グレイト･クレイジー･カーニバル', 'ボーグ工場のオーナー･中島がロイドを訪ねてきた。仲の悪い双子の娘を仲直りさせ、工場を仲良く二人で継いでほしいのだが…という中島の相談にのり、一行は工場へ向かう。大喧嘩する姉妹を勝治が叱責し、喧嘩は一旦収まった。しかし姉妹は二人とも勝治に惚れてしまい、今度は勝治を巡ってまた大喧嘩。中島と一行は事態の収拾に努めるが…。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15f31a46-3f42-46d8-a53a-9464583dea2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b915d5ef-1708-49e4-b951-226b47df2b25', '5a41042e-f65f-44f3-8771-0d199f435632', 38, '100153275', '武勇伝! レジェンド･オブ･タンジェント･デスティニー', 'ロイドの店に、リュウセイの馴染みだという浜田がやってくる。浜田が語るリュウセイとの並々ならぬ因縁。しかし当のリュウセイは浜田のことを一向に思い出す気配がない。業を煮やした浜田はリュウセイにボーグバトル勝負を挑む。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a709cc35-ff36-4ca5-aa6b-8acc89591d9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53f8bf5c-f0c0-4571-86cb-be35823bf82e', '5a41042e-f65f-44f3-8771-0d199f435632', 39, '100153276', '墜落!? エアボーグ･ナイン･ナイン', 'リュウセイ達の乗る飛行機に、時限ボーグが仕掛けられていた。排除しなければ飛行機は墜落してしまう。偶然乗り合わせていたボーガー達は、協力して時限ボーグ排除に立ち上がる。リュウセイ、勝治、ケン、ロイド、ビッグバン、中華三兄弟、ジョニー、ボーガーX…。総力を結集した闘いが今幕を開ける。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62d352c1-8dda-4587-bdec-a3fa56f1175c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c0eff31-e760-4f37-ac49-005e2eb7687e', '5a41042e-f65f-44f3-8771-0d199f435632', 40, '100153277', '給食のおばさん! ビューティフル･ワンダフル･ストレンジャー', '不良少年少女からマシンを盗む「ボーグスリ名人･銀次」が現れた。各地で被害が報告される中、ケンのマシンがすられてしまう。銀次の正体を突き止めるべくリュウセイと勝治が動き出す。そして突き止めた正体は、何と学校給食のおばさんだった…!', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32748c22-c8e0-4780-9859-91f04c462f09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c120355a-0726-4718-b5be-2f509c4236a4', '5a41042e-f65f-44f3-8771-0d199f435632', 41, '100153278', '裏切りの序曲! ノイズ･アンド･ファンタスティック･ハーモニー', 'いつもの4人 (リュウセイ、勝治、ケン、そしてマンソン) がロイドの店にたむろしている。そこにビッグバン達が公園を荒らしまわっているとの情報が入る。いつもの4人の連携でビッグバン達を撃退するが、ビッグバンは新たな刺客、ビッグ･バン･ローゼスを送り込んできた。果たしていつもの4人は勝てるのか!?', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/205ba08b-4433-4e26-a1cf-e1efde51e34a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b9d3f68-4510-47ea-a1a1-8ccb3a1819f8', '5a41042e-f65f-44f3-8771-0d199f435632', 42, '100153279', 'カブト刈! バリカン･バリバリ･サンダー', '昇竜軒の斜向かいに出来た床屋にケンは散髪に出かけるが、つい気持ち良く寝てしまったところで「カブト刈」にされてしまった。元に戻してもらうためにボーグバトルを挑むも敗退。カブト刈のまま登校する羽目になってしまう。翌日には勝治までカブト刈の犠牲者に。しかしそこから街の様子が変わってきた。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45ac25f6-fd2a-4403-a74a-c7f9095f9bf6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90876fa4-d702-49a1-aa4c-86f6da290388', '5a41042e-f65f-44f3-8771-0d199f435632', 43, '100153280', '心! サドンリー･ズームアウト･コンチネンタル', '誰でも手軽にバトルを楽しめる1コインボーグが流行りだす。しかしお手軽さに比例してマシンを粗末に扱う風潮が広がりだし、あちこちに捨てられている1コインボーグのマシン。そんな現状にリュウセイ達は違和感を覚えるが、ある日、捨てられた1コインボーグを片付ける1人の老人と出会う。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/284bd4cc-a2a7-4968-a90b-5b1158bf511b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1076ec87-3712-4ecc-b129-344ddbd67275', '5a41042e-f65f-44f3-8771-0d199f435632', 44, '100153281', '流れる大河! スカラベ･フラッシュ･ピラミッドパワー', 'リュウセイは対戦相手のミイラ男に不吉な予言をされ敗退する。失意のリュウセイを取材陣が取り囲む。しかし取材の相手はトムキャット･レッド･ビートルだった。試合に負けた腹いせと嫉妬でリュウセイは思わずトムキャット･レッド･ビートルを川に投げ捨ててしまう。川に流されたトムキャットは様々な人々の手に渡り旅を続ける。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5190588c-d392-4d97-a6a5-da202698349a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b314e295-0746-4f63-9841-74877468abfd', '5a41042e-f65f-44f3-8771-0d199f435632', 45, '100153282', '三姉妹! ゴンドラ･アルプス･フライドチキン', 'リュウセイは、入院したベネチアンの代わりにイベントに参加するベネチアンの弟の稽古をつける事になった。しかしあまりのお粗末さに見かね、リュウセイ自身が身代わりになりイベントに参加することに。イベント当日、エキシビションの相手として現れたのは謎のボーガー、チロリアンとカナリアンだった。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06b83a3f-e9d7-47c7-b77b-35587c6c9307.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fc8b4ba-b31a-4e71-b720-cd0560f80038', '5a41042e-f65f-44f3-8771-0d199f435632', 46, '100153283', '全てを! セレクト･ユア･ファイナル･ディシジョン', 'カブトボーグ世界ランキング上位者が何者かにより次々に倒されてゆく。そしてリュウセイの前に現れたその男の正体は、宿命のライバル、ジョニー･山田一郎だった。リュウセイとの決着を着ける為シベリヤで修行したジョニーは、恐ろしいほどの力を身につけていた。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4ddbb41-44b6-4868-8e53-821d863f3600.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e20f394e-dd7a-4cc0-bf94-0dc3847d8ab1', '5a41042e-f65f-44f3-8771-0d199f435632', 47, '100153284', '忍び寄る聖夜! サイレントナイト･ホーリーナイト', '今年こそ彼女を作り楽しいクリスマスを送りたいと切に願うケン。バス酔いのまま夜の街を歩いていると、サンタクロースに出会う。酔った勢いでサンタに絡み、彼女をねだりながら寝てしまったケン。目が覚めると、そこは見知らぬ女･マキコの部屋だった。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e7912ee-32c0-4bc4-9d3b-6f81e36a0e41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50b98e65-8a95-4688-9594-25bcfbcbb8b7', '5a41042e-f65f-44f3-8771-0d199f435632', 48, '100153285', '熱暴走! エンド･オブ･サマー･バケーション', '夏休みもあと僅か。ほとんど宿題に手をつけていないリュウセイとケン。頼りの勝治は家族と海外旅行中。思い余った二人は街に出て宿題争奪ボーグバトルを次々に仕掛けてゆく。無差別に町内を荒らしまくる二人にロイドの堪忍袋の緒が切れた。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b727cb3-3050-402d-8632-a153f5676dd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f343c1e7-ec25-46f6-8bfa-9225fe37bc98', '5a41042e-f65f-44f3-8771-0d199f435632', 49, '100153286', '哀しき熱帯! エンド･オブ･サマー･ホリデイ', '夏休みも終わりに近付いた頃、勝治は家族と海外旅行に出かける。島の観光に出かけたその日の晩に、民族衣装を身に纏い、踊る一人の少女と出会う。彼女にほのかな恋心を抱く勝治だが、言葉が通じない為の誤解から少女を悲しませることになってしまう。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56b4d83a-c94f-41df-96eb-6a279e1ecdc1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28a9d5c2-b0dd-4a96-826e-3c25911cd7d9', '5a41042e-f65f-44f3-8771-0d199f435632', 50, '100153287', 'それぞれの道! ライズ･ユア･アイアン･ウイル', '中華料理の真髄を極める為の修行を終え、中国からケンが帰ってきた。しかし様子がおかしい。戸惑うリンリンはリュウセイ達に助けを求める。ロイド、勝治が見守る中、ケンとリュウセイの最後のバトルが始まった。', '2023/08/10 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6a0cbf1-90e1-4b3c-b0da-7620d8b83ddd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b2e9321c-aca8-4606-b298-d66a1a7af525', '図書館戦争', '', 'hulu', 'library-wars-tv', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89488ec6-86de-4a6c-83cd-7497a9940c9a.jpg?w=331&h=447&p=t', 'hulu', 2008, 1, 1, 'FINISHED', NULL, 3613, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 'b2e9321c-aca8-4606-b298-d66a1a7af525', 'hulu-library-wars-tv-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44fc535a-a462-4830-b017-f65b37b72528.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abb250af-6fac-4f1b-be0d-9665378cdb11', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 1, '100148397', '我ガ王子様ハ図書隊ニアリ', '愛しい本を検閲から守ってくれた“王子様”を追って『関東図書隊』に入隊した、熱血バカ･笠原郁 (170cm)。鬼教官･堂上 (165cm) の厳しい軍事訓練が続くある日、市街哨戒へ出た郁はメディア良化隊の検閲に遭遇する!', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44fc535a-a462-4830-b017-f65b37b72528.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0c98d2d-a9f4-43a9-99d8-7b47689ff68a', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 2, '100148398', '図書特殊部隊 (ライブラリータスクフォース)', 'ライバル･手塚とともに“ライブラリータスクフォース”に配属された郁。野戦訓練ではクマ、図書館業務では座学不足が郁を襲う。一方、業務部の同期･柴崎は、問題図書を狙う良化隊の不穏な動きに気付いていた――', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e1474ef-7fc0-400c-a71b-a43f32a2d1eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d27bf25-1dff-48b7-97a5-8259bc565388', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 3, '100148399', '小田原攻防戦', '手塚からの告白に動揺する郁。検閲の歴史を収蔵した資料館が閉鎖――激戦が予想されるヘリ空輸作戦から、堂上は郁ひとりを外す。その真意はどこに…? 傷心の郁を残し、良化特務機関との大攻防戦が幕を開ける!', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad812086-0d73-47c0-9f25-d3922e4919e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04a712f1-b254-4551-8707-940f8f1bfda0', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 4, '100148400', '図書隊司令ヲ奪回セヨ', '小田原攻防戦が終息したのもつかの間、稲嶺基地司令と郁が、良化法賛同団体に拉致された。必死に行方を追う図書隊、そして堂上。郁の機転が功を奏したとき、タスクフォース隊長･玄田が放つ起死回生の一手が光る!', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d152438-efbb-4101-a359-55ff2c890236.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0ce7fc6-7261-48f3-8a32-31b36f204a77', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 5, '100148401', '両親攪乱作戦', '郁の仕事ぶりを見ようと、両親が図書館にやってくる。戦闘職種配属を隠していた郁は、タスクフォースの面々に泣きつく。危険な仕事に断固反対の母、成長を試すような父。田舎への強制送還を阻止できるか、郁!?', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d1a4546-943d-4c1b-b73c-cb2d4e9f0ebe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92464157-c59e-45ac-862c-4c3cf22b9b64', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 6, '100148402', '図書隊ハ発砲セズ', '良化隊がつけ狙う本――『予言書』を回収した郁と小牧。襲撃から逃げるさなか、小牧は、郁と昔の堂上の姿を重ね合わせる。堂上班誕生のエピソード、そして絶体絶命のピンチを切り抜ける小牧の作戦とは。', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0edac42e-9b6b-4870-8dc0-12d74fa90683.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a68c9bfb-2c40-4abc-8c88-c2d2dc38f9ec', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 7, '100148404', '恋ノ情報探索 (恋のレファレンス)', '図書館に通う青年･朝比奈と仲を深める柴崎。同じ頃、手塚の前に現れた彼の兄･慧。郁を陥れる罠。やがて朝比奈は、柴崎にある困難な選択を突きつける。その真意は何か、そして柴崎の出す答えとは――。', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b769fd64-289f-49ad-b92e-1fc69542659f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('745bbddb-0cbd-4e25-a59b-dfe14f92e9f2', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 8, '100148405', '策動セシハ手塚慧', '図書隊の厳しい査問と、隊内の白い目に耐え続ける郁。手塚は、慧が主宰する『未来企画』の企みに気付き、悩む。慧から郁を呼び出す電話が鳴ったとき、すべての事情を察した堂上が動いた――!', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/098b73af-f3fc-4790-a54f-ce9d97718b25.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1813e314-b7b1-4313-ba43-2fdbb703fdc3', 'af04cd69-606f-497a-9ce6-8e5dd9cfc19a', 9, '100148406', '昇任試験、来タル', '郁たちに昇任試験が迫る。“王子様”の正体を知った郁は大混乱、手助けしようとする堂上にも素直になれない。一方、実技に意外な弱点を抱える手塚。思わず柴崎に試験対策を頼む。それぞれの恋と試験の行方やいかに。', '2023/07/12 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbf03ffd-9966-430c-ab76-f0e5636bcb38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2945876c-cb4b-4a92-bf18-5bba4c63b8f5', '厨病激発ボーイ', '', 'hulu', 'chubyou', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0990e92b-102f-4074-bf77-f564a489715c.jpg?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'FINISHED', NULL, 113979, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('318cd7e0-19db-49ec-9b4e-79f22beefe08', '2945876c-cb4b-4a92-bf18-5bba4c63b8f5', 'hulu-chubyou-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9262c37a-b7b5-49b9-abb4-8aa64beb51d0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69fb3fef-6498-45b7-8d54-c91e7e550a94', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 1, '100043345', 'そうさ 俺は目覚めてしまった', 'わけあって中途半端なタイミングで皆神高校に転校してきた聖瑞姫は、転校初日に突拍子もない言葉を投げかけられる。平穏な高校生活を送りたい彼女が出会ったのは、平穏とはほど遠い、厨二病をこじらせまくった残念男子たちが集まる“ヒーロー部”の面々だった! 妄想と暴走にツッコミが追いつかない厨二病学園生活が、今始まる!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9262c37a-b7b5-49b9-abb4-8aa64beb51d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a84bfa98-19cf-4d11-806f-a28d424bc2f2', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 2, '100043698', '天使か悪魔の生まれ変わりか', '校庭から飛来するサッカーボール、廊下からおそい掛かる鳥のおもちゃ、そしてバドミントンの羽根。転校翌日から続けて危ない目に合った瑞姫を心配していたヒーロー部だったが、ついに犯人の正体が判明した! しかし、なぜ瑞姫は狙われているのか。残った謎を探るうちに、瑞姫とヒーロー部は思わぬ新事実にたどりつく。どうやらクラス委員の渡瀬菜々子が関係しているようで…?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b78e3a6-66b4-4789-9bb9-fb52fdc889c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad792d40-4459-42ed-b8f9-93809bc2a04c', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 3, '100043944', '子供じゃないし大人でもない', '中村の活躍 (?) で事件は解決し、瑞姫には友達もできて平穏な日常が訪れたかに思えたが、ある時、九十九が怪しげな言葉を口にする。気になって彼を尾行するヒーロー部と瑞姫が目にしたものは、次々と赤から青に変わる信号、都合よく始まるタイムセール…もしや彼は時間を操る能力者!? さらに後を追った瑞姫たちは九十九の正体に驚愕するのだった―。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a73c5e4-5e94-4b69-93dd-adb1b458fa42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8ec7036-07a4-4371-991c-adac1bce9962', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 4, '100044416', 'こじらせちゃってパンパカパッパッパーン', '新たな転校生･厨二葉はアメリカからの帰国子女。しかもイケメンとあって瑞姫たちのクラスは大賑わい。そんな逸材を見逃すはずもなく…「仲間になれよ、グリーン!!」野田がヒーロー部への勧誘作戦をスタート! さらに調理実習では厨の入部をかけたお料理バトルが勃発!? 当然、ヒーロー部たちの料理が無事に完成するはずもなく…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ecb530a-2035-41c7-a2e9-2702e5ee1a9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a426d6b1-3b92-4086-b152-7db1a59903f2', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 5, '100044566', '強大なチカラ 持ってしまった', 'ついにやってきた夏休み! 誰にも邪魔されずにインドア生活を満喫していた瑞姫だったが、九十九からのヒーロー部緊急招集になぜか巻き込まれてしまう。今回のミッションは遊園地でのアルバイト! 瑞姫の心配をよそに、厨病ボーイズは迷子センターやフードコートで意外な活躍を見せる。ところが、「アイライブ!」ショーでトラブル発生!? 立ち上がったのは、そう―アイツだった…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/813eb51a-a495-4375-9c37-510b889b6dce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('928c8cd8-1a92-418c-b41b-74f25ce994d6', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 6, '100045100', 'チラチラ視線感じてる', '夏休みが終わって新学期が始まり、皆神高校は体育祭の季節。紅白対抗戦を制したい生徒から助っ人の依頼が舞い込み、ヒーロー部は本番に向けて猛特訓!? そして体育祭当日、実行委員の野田はいつも以上に元気いっぱいで、放送委員の高嶋もノリノリの実況をお届け! 中村や九十九も赤VS白のデッドヒートで盛り上がる中、厨だけは調子が上がらないようで…?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e10c09f-8731-4ec1-b228-daaedb4bc236.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24f69fce-6723-409e-afde-b3922e53997b', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 7, '100045390', 'イケメンじゃないしone night love', 'すっかりヒーロー部に馴染んできた瑞姫だったが、ある日、ヒーロー部の活動を問題視する生徒会に呼び出されてしまう。そこで瑞姫が言い渡されたのは、ヒーロー部への警告だった! 文化祭までに騒ぎを起こせば次はないと知った瑞姫は、厨病ボーイズの暴走を防ぐため、ヒーロー部への依頼の取りまとめ役を申し出るのだが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8dade258-dad4-4736-b37c-4dbc727183aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fea0953e-1fac-40f7-a038-371108507280', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 8, '100046335', '理想と現実の狭間で揺れてる', '今回の依頼人は廃部寸前の演劇部。存続のための条件は文化祭の人気投票で1位を取ること!? 彼女たちを救うため、ヒーロー部も演劇に協力することになる。演目はお姫様が王子様を救う男女逆転のおとぎ話! 順調に思えた練習だったが、親指姫役の野田がセリフを覚えられず大苦戦で…? 一方、裏方の瑞姫は、音楽担当の放送委員長から人気の歌い手の噂を耳にするのだった―。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0453a61-a496-45bd-aeb4-0251e6e15e72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ce70450-b67b-4ad5-a8e7-4b5c61072ab4', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 9, '100046966', 'おかけになった電話は', '厨の活躍でハプニングを乗り越え、ついに文化祭当日を迎えたヒーロー部。模擬店のBGMに特撮とアニソンを選曲する野田と高嶋、お化け屋敷で絶叫する九十九、絶叫させる中村―演劇が始まるまでそれぞれの時間を楽しんでいた。ところが、演劇の開演直前に妨害が発生! しかも、主役たちが舞台裏で待機するしかない状況で、動けるのは裏方の瑞姫たちだけ…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76cb77a0-6c1a-4360-a059-8eff6b082297.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf20d48f-7920-403e-ae21-ea3916047349', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 10, '100047211', '孤独と屁理屈の闇に紛れて', '文化祭で演劇部を救い、ヒーロー部は絶好調! …と思いきや、一連の騒動のせいでヒーロー部は生徒会から活動を禁止されてしまう! 部室を閉鎖され、バラバラになった6人はどこか調子があがらない。そんなとき、瑞姫のもとに依頼が届くが、以前のようには活動できずもどかしい思いをするのだった―。一方その頃、備品がなくなる事件が多発して学校中が大混乱で…!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fee8443-109b-4bf2-ae10-171f0069d56d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08787cc0-70ec-4fa2-bfec-136833fdee8e', '318cd7e0-19db-49ec-9b4e-79f22beefe08', 11, '100047638', '放て俺のサーチライト!', '【シーズン1 最終話】ヒーロー部に助けられた人々の想いに触れた瑞姫は、自分たちが必要とされていることを知り、活動再開を決意する。そして、校内の協力者に支えられ、ヒーロー部はついに復活! しかし、ヒーロー部がいない間に謎の事件は続き、いまだ皆神高校は混乱の中にあった…。果たして瑞姫たちは史上最大のピンチを乗り越えられるのか!―世界を救え、ヒーロー部!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2fb69284-a54c-455c-9fc8-5617e4c1afc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c28785a5-9545-4592-aa80-f5b6ece7f1c4', '推しが武道館いってくれたら死ぬ', '', 'hulu', 'if-my-favorite-pop-idol-made-it-to-the-budokan-i-would-die', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/026535c2-2864-4c68-8a6d-2d3daa5a14dd.png?w=331&h=447&p=t', 'hulu', 2020, 0, 1, 'FINISHED', NULL, 104391, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('67bd0400-6f3a-492a-ae51-4be684ebf1db', '水属性の魔法使い', '', 'hulu', 'the-water-magician', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a8b0452-b8b1-4ab4-bf06-843fd16dfb90.jpg?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 186052, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('eae4cb44-5811-4773-9099-1d13c35c2f59', '67bd0400-6f3a-492a-ae51-4be684ebf1db', 'hulu-the-water-magician-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc8360b6-6b88-4b24-98bc-ec4062995ec4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27c43539-27cb-412d-a28e-f3bb3de4965a', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 1, '100231745', '危険なスローライフ', '死んだはずの三原涼が告げられたのは、魔法の存在する異世界への転生だった。与えられた「水属性」の魔法と共に快適なスローライフを送ろうとする涼だったが、外は手強いモンスターだらけ。この世界を生き抜くため、魔法の修行に明け暮れる涼だが…?', '2025/07/07 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc8360b6-6b88-4b24-98bc-ec4062995ec4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f7cbeff-0b6f-4bba-8a0c-0b7a64d97859', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 2, '100232304', '漂流者アベル', '砂浜に打ち上げられた男を助けた涼。アベルと名乗るその男に街までの道案内を頼まれ、涼は森を発つ。道中襲い来るモンスターを、華麗な闘技で撃退するアベル。涼も修行した魔法で援護するが、アベルはその規格外の魔法に驚きを隠せず…?', '2025/07/14 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d529f98-6243-4d75-9259-fdfc17ee2061.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9c45a1f-76eb-4f1b-9a5d-8003bb0853a2', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 3, '100232845', 'ルンの街', 'ルンの街に辿り着いた二人。冒険者登録をするためギルドへ向かうが、死んだと思われていたアベルは冒険者達から大歓迎を受ける。再会に水を差さないようギルドの外で待つ涼の前に現れたのは、目を奪われるほど美しいエルフ、セーラだった。', '2025/07/21 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58323888-3f51-41fd-80c3-53090998ba7b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0ccd2e7-bc76-475a-8ea4-506eabfc8c07', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 4, '100233371', '日食と悪魔', '初心者講座でダンジョンに潜る涼とアモン。本来第一層にいるはずのないモンスターとの遭遇に涼は違和感を覚える。さらに翌日、錬金術について調べるため図書館を訪れた涼だが、日食と共に現れたのは圧倒的な強さを誇る悪魔、レオノールだった。', '2025/07/28 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d2e47622-12bb-49bd-9a7d-b1c3c8cff37a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5c95418-d699-42cc-8e86-1dd3deacfa06', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 5, '100233872', '大海嘯', 'ダンジョンの異変を察知したヒューは、「赤き剣」と「白の旅団」を呼び出す。調査に向かったアベルたちだったが、既に大海嘯はすぐそこまで迫っていた。 一方そのころ北側の図書館に向かっていた涼は、セーラと再会するのだった。', '2025/08/04 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7183f660-192a-46bc-853c-5a1befdb864f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a58b3f28-1d11-4192-a27e-39422dfdd561', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 6, '100235021', 'ダンジョン封鎖', 'ダンジョン封鎖で依頼不足に悩むニルスたちに、涼は個人的な依頼を与える。一方、大海嘯後のダンジョン調査に王都からやってきた学術調査団に対し、ヒューは渋々封鎖を解除する。護衛として雇われた「赤き剣」は調査団と共にダンジョンへ向かうが…?', '2025/08/18 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b14b8562-32cf-43f3-8eaf-a8beec9a123f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f348d73-857c-4359-b051-2bbabaec1b7a', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 7, '100235405', '門の先で', 'ダンジョン調査中に転移されてしまったアベルたち。そのころ、何も知らない涼は図書館で日食と大海嘯の関係について調べようとしていた。 前人未到の四十層で人では勝てない存在と言われるデビルと魔王子に襲われる調査団。善戦する赤き剣だったが…。', '2025/08/25 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67200974-344c-4096-bc81-9f0b563ad16a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('461dcec6-7b14-4798-a845-f605bd3acf29', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 8, '100236007', '規格外', '規格外の魔法で魔王子を圧倒する涼。無事帰還したアベルたちを見て安堵するヒューは、二度ものアベルの危機を救った涼に対し底知れない強さを感じるのだった。 一方、涼は飽食亭で居合わせたセーラと手合わせをすることになり…。', '2025/09/01 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/deb5f09e-e330-47a2-baec-41538df0c240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a747663-d412-4d75-a078-da274ff444b5', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 9, '100236702', 'ニルスの不思議な村', 'ニルスの故郷からの依頼を受けるため、十号室メンバーと臨時パーティーを組むことになった涼。 討伐対象はゴブリンとスケルトンという奇妙な組み合わせ、そして村人の敵対。不思議な村の原因を調査するため、四人はアバリー村に向かうのだった。', '2025/09/08 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27613d77-d7ad-4902-982c-1fb88721538c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e5e2809-3b13-4351-9b06-57f4cc7acd9e', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 10, '100237634', '開港祭', '五年に一度開かれる開港祭に向かう商団の護衛として、ウィットナッシュを訪れた涼と十号室メンバー。お祭り気分に浮かれる涼たちだったが、ウィットナッシュには各地から続々と曲者が集まってきていた…。', '2025/09/15 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a09c27fe-1983-41f5-87e4-db2c01ec48d4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1141a522-d96c-4c78-8021-b7185e7fd22a', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 11, '100237904', '爆炎の魔法使い', '平和な村で両親と鍛冶の師に愛され、健やかに育っていた幼少期のオスカー。しかしその幸せな生活は一夜にして崩れ去ってしまう。後に「爆炎の魔法使い」となる彼の抱える壮絶な過去が、今語られる、、。', '2025/09/22 04:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/589f3dfe-874c-4070-aede-08eb5f28d006.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4528e20-c4b2-4c0e-895f-1eda2978dc9c', 'eae4cb44-5811-4773-9099-1d13c35c2f59', 12, '100238938', '涼の帰路', '【シーズン1 最終話】フィオナを助けたニルスたち。しかし後から駆け付けたオスカーに、フィオナを襲った犯人であると勘違いされてしまう。オスカーの怒濤の攻撃に圧倒されるパーティー「十号室」の前に、ついに涼が到着する。', '2025/09/29 04:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7de98742-e1eb-4aba-b186-ba27c0687eaa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('92720e1c-e365-4357-b1e4-d82d6a1f09af', '世界の闇図鑑', '', 'hulu', 'world-darkness-illustrated-book', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50029208_series_art__338x600_world_darkness_illustrated_book_cf6b7e77fe027cdfc1063e6da983f2f0.jpg?w=331&h=447&p=t', 'hulu', 2017, 1, 1, 'FINISHED', NULL, 98442, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('41916b9d-4dc6-4644-90ae-f6c16255f5e8', '92720e1c-e365-4357-b1e4-d82d6a1f09af', 'hulu-world-darkness-illustrated-book-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cff845c4-bb47-4537-b2a1-1888e4c38ef4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a615692-933d-451b-8fc4-c24d1dea35e2', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 1, '60881283', '誘惑の黒い影', '毎夜、夫に黙って外出していく妻。「今夜こそ行き先を暴いてやる!」。意を決し、妻を尾行した夫が見たものとは…!', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cff845c4-bb47-4537-b2a1-1888e4c38ef4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6d9f500-a7cf-4794-9f08-1a0feec90d7d', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 2, '60881282', '雪の中の妖精', 'ある雪の日、ミハエル少年が作った雪だるまは、彼にとっての唯一の友達だった。粗暴な父親から逃げて、雪だるまと逃避行を図ったミハエル少年は、思いもよらない「闇」に出会う。', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0711e4a5-0f4b-4d5e-bc5a-e1d2c03df542.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79cf0af5-2e12-4ab7-a3ab-bb1fa299974f', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 3, '60881292', '荒野を駆ける死神', '荒野をヒッチハイクで旅している青年ノエルは、空腹と疲労で限界だった。命からがら、美女の運転する車に乗せてもらう。しかしそれは、悪夢のドライブの始まりだった。', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/420aae46-b41f-479f-9fa4-0238f97f44c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccc888ba-0d4f-41a6-ae2e-01f2f770ceb3', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 4, '60881284', '謎の円形の正体', 'トウモロコシ畑の上空に突如現れた、謎の発光体。翌朝、畑にできていた円形の幾何学模様。果たしてそれは、宇宙人の仕業なのか…?!', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0a81039f-cc28-4d5a-a014-e93d4ce4d310.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc41036a-34a4-4e1d-b79b-49a1f422d42c', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 5, '60881291', '機械人がやってくる', '文明が発達し、人間とロボットが一緒に暮らす時代。果たして、共存することは可能なのか? 遠くない未来に疑問を投げかける、問題作! 勝つのはどっちだ?', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/70c6106e-4c0f-4cc0-99ac-f70fe19f7cb4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6402c63c-6071-41f1-95e9-df24c34895e8', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 6, '60881286', '砂に消えた悪夢', '穏やかな砂浜に、突然打ち揚げられた巨大な海洋生物の死骸。悪臭を放ちながらビクともしない。発見した若者たちは興奮しはしゃいでいたが、その喜びも束の間だった…。', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4c3f3163-8758-4810-a94d-6e93b14b43b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('199dc720-d1b4-441e-8bb9-d2cd154795d1', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 7, '60887347', '無邪気な道化師', '「鏡を入り口に、道化師がやってくる」そんな言い伝えを知ってしまった姉妹。何気ない生活の中、鏡に映った姉妹の顔が、惨劇に凍りつく…!', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4028586d-8f24-49b4-b3c4-44ba3cf12a5f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40935851-f0d9-404d-97f6-7782e5396ad4', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 8, '100001389', '病にかからぬ謎の民', '絶対に病気にならない民族がいる…。その謎を解き明かすべく、奥地へと向かった探検隊が消息を絶った。彼らの行方と、「病気にならない秘密」に因果関係はあるのか…!', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5740f031-cb5f-4e88-a81e-cb757cdf1b63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01bacce4-d1b6-4e12-982c-02dd4b4bf170', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 9, '100001390', '不幸を呼ぶ呪いの箱', '引っ越したばかりの新居に存在する、古ぼけた奇妙な箱。その箱は見るものを魅了し、感情をかき乱す。箱の周辺で巻き起こる、異常な事件の数々。', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c0e8b64-9ed8-426a-b1d1-bd3e96ed74c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b999b1c6-91b6-468a-9b07-8170d97927c8', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 10, '100001391', '最期を見つめる奇面', 'その謎の面は、ヨーロッパのとある骨董品屋に並べられていた。太古の昔より人々の顔を覆い、様々な悲劇を目撃してきた面が、装着する者を恐怖の世界へと誘う。', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1657fc18-3c74-42f0-88b0-5d81e10374c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3085bca6-ce1c-4b6b-8f44-592fa103ac11', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 11, '100001392', '地底からの呼び声', '世界の不思議とされ、大きな石像が並ぶ太平洋の島。誰が、何の為に、どうやってそこに建てたのか…? その謎に興味を持った旅行者は、二度と島から出られない…!', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dae5159a-d99b-411b-b9e9-1c98a2c5231c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6de0820-8cce-4713-80b8-f8dfa87eb44b', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 12, '100001393', '海底に蠢く赤い目', 'リゾートを満喫していたカップルに、突如降りかかった予想外の恐怖。彼らを襲った知的生命体の謎が、今解き明かされる…!', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/089c01c7-8480-47d1-988e-fc0df491cb63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51a1f13b-5f82-4d22-aa82-3b2831c1d006', '41916b9d-4dc6-4644-90ae-f6c16255f5e8', 13, '100001394', '霧につつまれた樹木', '【最終話】少女は森を彷徨っていた。その森での新たなる出会い、暗い過去との決別…。森は少女にとって「救い」となるのか…。', '2021/10/04 00:00:00', 270, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e48b03ee-8b51-46c8-94b3-7ce09594ffa1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f5ab96cd-f4c5-47db-b5ff-310f86df6bbf', '世話やきキツネの仙狐さん', '', 'hulu', 'senkosan', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10b009b4-5e9b-4b7d-a68a-4b027d1552a7.jpg?w=331&h=447&p=t', 'hulu', 2019, 1, 1, 'FINISHED', NULL, 105914, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 'f5ab96cd-f4c5-47db-b5ff-310f86df6bbf', 'hulu-senkosan-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/003bb191-8adc-46be-ac26-48115b5bf9d9.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c30747a-2799-41f7-bcdc-aec57b8b79ae', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 1, '100034072', '存分に甘やかしてくれよう', 'ブラックな会社に勤め、疲労困憊の日々を過ごすサラリーマンの中野くん。ある日、残業の末疲れ果てて帰宅すると、何故か消したはずの部屋に明かりが。不思議に思いながら開いた扉の先にいたのは、温かい料理を作る狐耳と尻尾姿の少女でした。「仙狐」と名乗り、自らを800歳の神使の狐と高らかに謳う少女の出現に混乱を隠しきれない中野くん。仙狐さんは中野くんのことをお世話しに来た、と言うのですが…。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/003bb191-8adc-46be-ac26-48115b5bf9d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0327d2a-928d-404b-8a27-404f65cc159d', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 2, '100034341', '恥ずかしがらずともよいよい', '翌朝、部屋で仙狐さんの姿を見て、昨晩の出来事が夢ではなかったと理解する中野くん。昨晩遅くに帰宅したにも関わらず、朝食を食べることもなく慌てて出勤していく中野くんの姿を見送った仙狐さんは、帰宅後の彼を存分に甘やかそうと決意します。手始めに一人暮らしですっかり汚れた部屋の掃除に洗濯、料理と、慣れた手付きで家事をこなし始めるのでした。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad3c8c7e-9490-4313-a497-2c69c4fd5583.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de426d8c-488b-426d-850a-b9c31e45c86e', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 3, '100034725', 'おぬしが幸せならそれでよい', 'とある休日、仲良くゲームで遊んでいた中野くんと仙狐さん。対戦ゲームで見事勝利した中野くんが、仙狐さんに尻尾をモフモフさせてもらうべく迫っていた瞬間、玄関から女性の怒鳴り声が! そこに立っていたのは隣に住んでいる大学生兼漫画家の高円寺さん。男性の一人暮らしだと思っていた部屋で、幼女に迫 (っているように見え) る中野くんの姿を目撃した高円寺さんは…。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55d9eedb-2bf7-467e-9bb2-d32d995327da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ec2b3c4-ab7b-45d7-a2f5-611796737473', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 4, '100034970', 'なぜ休日に仕事をせねばならんのじゃ!?', 'いつにも増してボロボロな姿で帰宅した中野くん。翌日は日曜日、ゆっくりと休むことをすすめる仙狐さんですが、なんと中野くん、日曜日も働かなければならないと言うではありませんか! いつか倒れてしまうのではと気が気でない仙狐さん、せめて気持ち良く目覚められるようにと、翌朝中野くんを起こしてあげると申し出るのですが…。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37bd7b0a-bb7c-40cd-9453-ce96fdf5f16b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c47c3934-9e55-4a71-a79b-71a2b4768205', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 5, '100035119', 'しっぽなら、わらわのがあるじゃろ?', '突然始まった仙狐さんとの共同生活という非日常にも、ようやく慣れてきた中野くん。その日も仕事を終えて仙狐さんが待つ家に帰ってくると、そこにはもう一匹、我が家のようにくつろぐ見知らぬ狐娘の姿が…! 純白の耳と尻尾を持ち、仙狐さんと同じ神使の狐だというその狐は「シロ」と名乗り、続けて堂々と中野くんに宣言します。「特別にシロの頭を撫でさせてあげるわ!!」', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb17efaa-ee62-4eb7-bb9c-ec124aedc85c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2010af1-b720-4545-9e47-7ec34c0ca15a', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 6, '100035605', 'もふりたいだけじゃろ、おぬし', 'さも当然のように、休日の中野くん宅へ颯爽と登場するシロ。以前、中野くんに尻尾をモフられそうになったことも忘れ、どうやら再び甘やかされにやってきたようです。そんなシロに、中野くんは部屋にあるゲームで遊ぶことを勧めます。仙狐さんが苦戦したチュートリアルを難なくこなし次々とクリアしていくシロ、遂には仙狐さんの手作りおはぎを賭けて中野くんにゲーム勝負を挑みます。果たして勝負の行方はいかに…!', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03b525e4-247b-4033-98aa-0c05bf7921fa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4f109b2-3b3d-4004-bdff-08fd2d8593c6', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 7, '100036070', 'おぬし、別のキツネの匂いがするのう', '仙狐さんとの晩御飯を終え、食器を下げようと立ち上がった中野くんに衝撃が走る! 日々の運動不足と会社での慣れない肉体作業によってすっかり腰を痛めてしまった中野くん。そんな彼の体の凝りをほぐさねばと意気込む仙狐さんの、すっと足を差し出しながら放たれた一言に中野くんは我が耳を疑うのでした。「わらわが踏んでやるのじゃ!」', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f637ab61-04d0-45a4-b60d-d5d2d3b36204.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49f39e2a-3e2e-456f-a906-217b5407e972', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 8, '100036446', 'わらわが忘れさせてやろう!', '季節は夏! しかし中野くんに与えられた夏季休暇はたったの1日だけ…。遠出もできないからと家で休もうとしていた中野くんと仙狐さんの元へ、いつもながらに突如現れるシロ。「さっさと出かける準備をしなさい!」と急かされ、連れてこられた先で中野くんと仙狐さん、そして高円寺さんが目にしたのは…燦々と輝く太陽、晴れ渡る空、そして一面に広がる美しい海でした!', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09d5d286-09d0-4f75-9036-731a3d9fd179.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7126a39-f951-4f1c-84c0-ad32d3a0d1d3', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 9, '100036740', 'こうすれば恥ずかしくないじゃろ', '夏も過ぎた頃のとある朝、テレビの料理特集を見てヨダレをすする中野くん。我に返り慌ただしく会社に出かける姿を見送りながら、仙狐さんは中野くんが夢中になっていた料理…グラタンを作ってあげたいと考えます。しかし、和食ならばなんでもお任せの仙狐さんも、洋食にはあまり自信がない模様。そこで隣の高円寺さん (&シロ) と相談して、一緒に料理することに! 中野くんのため、美味しいグラタンを作れるでしょうか…?', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf65db99-f899-408a-8489-998a8b6a6744.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7f6dbb8-ce3c-47ad-82fc-a86b89c0d7bc', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 10, '100037106', 'たまには童心に返るのもよいじゃろ?', 'しんと静まり返った早朝、カーテンを開けるとそこには一面に広がる雪景色が! こんな大雪では会社に行けるわけがない! と止める仙狐さんを尻目に、いつもどおり出勤しようとする中野くん。行く行かせないの押し問答のさなか、やっと会社からお休みの連絡が届きます。するとさっきまで出かけるのを止めていた仙狐さんが中野くんの手を引き、外に連れ出すのでした。「せっかくじゃし、雪遊びでもするかの!」', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf0fc2b3-2ce2-4cf9-8d47-a12a4bd6ad1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0e42efc-2b0c-45f4-b36e-f0e30e15cf31', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 11, '100037410', '今夜は少し荒れそうじゃの', '仕事から帰った中野くんが自宅の扉を開けると、そこには割烹着姿で三つ指ついて出迎える仙狐さんの姿が! 何事かと驚く彼の目に入ったのは、暖簾に書かれた「居酒屋 仙狐」の文字でした。多種多様に取り揃えられたお酒と旬の素材を肴に堪能し、いつもより酔いが進んだ中野くんから思わず漏れる本音。そんな彼の心を、仙狐さんが優しく解きほぐします。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11a32236-8dfe-423f-8ce0-b4823e252a66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2000c524-3468-4add-81d9-a291aaa93d7e', '9c1f2fde-f4f6-4b28-abb6-2cc13bb5778f', 12, '100038197', 'それでも、あやつを……', '【シーズン1 最終話】会社からの連絡で予定を早めに切り上げ、帰省から戻ってきた中野くん。帰ってきた彼を待っていたのは、預けた携帯電話だけを残し仙狐さんがいなくなった、空っぽの部屋でした。「良くないことが起きるかもしれない―」、という夜空の言葉が頭をよぎり、必死に仙狐さんを探す中野くんですが…。', '2025/12/26 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a6c0ca9-33df-4625-9293-86cccf151323.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('10d191b0-62be-402a-988b-bfeeea2aa340', '瀬戸の花嫁', '', 'hulu', 'my-bride-is-a-mermaid', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50001002_series_art__338x600_my_bride_is_a_mermaid_9e85fbc117e1d98b662bae67ee33de1b.jpg?w=331&h=447&p=t', 'hulu', 2007, 1, 1, 'FINISHED', NULL, 2104, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c2d58a53-82cf-4a81-91be-da74600c7969', '10d191b0-62be-402a-988b-bfeeea2aa340', 'hulu-my-bride-is-a-mermaid-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/887dd975-cc64-48ea-b1e8-53c07557dd2b.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22f3cd5c-bcb8-4460-9142-8064a6d5e660', 'c2d58a53-82cf-4a81-91be-da74600c7969', 1, '60517637', '極道の妻 (おんな)', '父親の実家がある瀬戸内に帰省していた満潮永澄は、泳いでいる最中に両足がつって溺れてしまった。そんな永澄に手を差し伸べたのは人魚の女の子、瀬戸燦だった。だが人魚の世界は「身内以外の者に姿を見られれば、その人間か自分のどちらかが死ななければならない」という掟が存在していた。果たして、永澄の運命は…!?', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/887dd975-cc64-48ea-b1e8-53c07557dd2b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3f86cdc-9e27-4470-9075-679a6fd6aeab', 'c2d58a53-82cf-4a81-91be-da74600c7969', 2, '60517648', '指輪物語', '人魚の女の子、燦と夫婦となることとなった満潮永澄だったが、どうすればお互いを知っていくことが出来るか分からず戸惑うばかり。祖母のアドバイスを受けた永澄は、燦を夏祭りへとデートに誘うのだが、そこには、燦の結婚を快く思わない父の豪三郎による瀬戸内組を挙げたデート妨害工作が待ち受けているのだった…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a101193a-47c7-48ad-91a5-9a8df55fced4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1da02968-b078-41ca-94fe-56e5362c5846', 'c2d58a53-82cf-4a81-91be-da74600c7969', 3, '60517647', '天国に一番近い島', '急な埼玉への帰宅を告げられた永澄。燦と遠距離恋愛になってしまうことを考え、センチメンタルになっていた。そんな中、結婚に大反対だった豪三郎が、突然「無人島でのびのび遊んでこい」とクルーザーを用意してくれた。小さな可愛い女の子、巻き貝の巻も付き添いでやってきて、楽しくなりそうな予感がしていたのだが…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b901c791-25bc-4d0a-8c30-da52848f14ea.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('efd9028d-4353-4de2-970d-b7ed9822c6a7', 'c2d58a53-82cf-4a81-91be-da74600c7969', 4, '60517636', '男はつらいよ', '瀬戸内から埼玉の実家へと帰ってきた満潮家一行。永澄の妻となった燦と、燦の護衛役の巻も一緒に。女の子が増え、賑やかになった満潮家だが、両親が燦をえこひいきするわ、巻からは命を狙われるわで、永澄の生活は前途多難。そんな最中、巻が昼寝をしている隙をつき、燦と二人きりで近所へ散歩に出かけた永澄だったが…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d58857bc-a70b-47da-b211-23dab27514e8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d6df6b6-7eb8-437a-af02-790cb2c9aeba', 'c2d58a53-82cf-4a81-91be-da74600c7969', 5, '60517631', '狙われた学園', '新学期がスタートし、燦と一緒に学校へと登校する永澄。永澄の悪友である猿飛秀吉を始め、学校中の男子生徒は、きらめく程に可愛い燦の姿に夢中になってしまう。美少女の転校により、浮き足立つ永澄のクラスだったが、新しい担任の先生も赴任してくることに。その新担任はなんと、燦の父である豪三郎だった…!', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/695a2b9d-cdf1-4b2f-978a-0c40c43dc7d4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('197ef48e-ff9c-47a1-a02c-e8203aebd021', 'c2d58a53-82cf-4a81-91be-da74600c7969', 6, '60517635', 'お嬢さんお手やわらかに', '永澄と燦の仲の良さを見ているうちに、もやもやとした感情を抱き始めた巡。気合いを入れ直すため、風紀の取り締まりに力を入れる巡だが、その最中、同じ屋根の下から出てくる永澄と燦と出逢ってしまう。それをきっかけに、永澄と燦の同居など様々なことが気になり始めた巡は、燦の秘密を執拗に探り始めるが…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f59b963a-0d9f-439d-8378-5594de0b9b23.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ef5ebbd-725c-4dbb-a397-63ccd9255456', 'c2d58a53-82cf-4a81-91be-da74600c7969', 7, '60517646', '来訪者 (ビジター)', '今をときめく超人気アイドル“LUNAR”。実は彼女も人魚であり、その正体は、瀬戸内組とライバル関係にある江戸前組の娘、江戸前留奈であった。燦を一方的にライバル視していた留奈は、燦が永澄と結婚したという衝撃の事実を知る。留奈は、燦に勝ち誇り見返してやるために、燦から永澄を奪い取ることを宣言して…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/23b36d97-12ad-40ec-84d1-086a6160b529.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb3d9a75-65f8-4ade-bcb7-6780450a9fa8', 'c2d58a53-82cf-4a81-91be-da74600c7969', 8, '60517640', '激突', '留奈の燦に対する嫉妬心から始まった二人の争いは、本人たちの意思とは関係無く、磯野第八中学校男子生徒を巻き込んだ燦派と留奈派の抗争へと繋がっていく。かくして事態は、全校をも巻き込んだ燦と留奈のライブ対決へと発展していく。永澄を賭けた女の戦いの結末は…。そして、燦は永澄を守れるのか…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7d0c96b1-f515-43cd-b332-89b650fb5025.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b99b8e2-64de-450d-8048-c88ed5bbcf63', 'c2d58a53-82cf-4a81-91be-da74600c7969', 9, '60517624', 'バトルランナー', '永澄から燦を取り返すためにやってきた名古屋弁の人魚、三河海が現れた。燦の説得もあり、己の未熟さを思い知った海は、修行し直すと言い残し去って行った。だが、その翌日、同じクラスへ海が転校してきた。男修行をすると同時に燦を奪い取る機会を狙う海は、翌週に開催される運動会で決着をつけることを提案して…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e7aa0f49-2d2a-423e-95f2-85e4dd3bb493.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f77fc682-81cc-4357-8ed5-4a3a0e1ced03', 'c2d58a53-82cf-4a81-91be-da74600c7969', 10, '60517634', '鋼鉄の男', 'ある朝、永澄が目覚めると、目の前に黒ずくめのマッチョマンが佇んでいた。留奈に関する警告を残して消えて行った謎の男の影に怯える永澄。そして、永澄の前に再び謎の男が現れ、執拗に追い回し始める。途中で見つけた海を巻き込み、一緒に逃走劇を繰り広げる二人であったが、遂には海も謎の男に倒されてしまい…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/53f3d0b4-e2bb-437e-84f0-0915f75cb369.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf290e52-0d8e-4d7f-8228-8582090ebbe4', 'c2d58a53-82cf-4a81-91be-da74600c7969', 11, '60517641', 'アルマゲドン', '健康診断で体重が増えていることを知った留奈は、燦を強制的に仲間へと引き込み、ダイエットを決意する。燦がダイエットを始めるという噂を聞きつけ、瀬戸内組が通信販売事業で取り扱っているダイエットグッズを取り寄せた豪三郎はプレゼントする。そのグッズの中に混じっていた飲み物を思わず飲んでしまった永澄だが…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f4c7eeb9-80b9-417a-af57-d0be68559d7d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee73ad30-ae14-4b46-b307-db7bd067de1f', 'c2d58a53-82cf-4a81-91be-da74600c7969', 12, '60517645', '愛の奴隷', '燦と永澄母が買い物へ行ったため、留守番をすることになった永澄と留奈。アイドル業が忙しく成績が悪くなった留奈は、燦がいなくなった隙をつき、勉強を教えるように永澄へ命令する。最初は普通に勉強を教えていた永澄だったが、憧れだったLUNARと二人きりというシチュエーションを変に意識し始めてしまい…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c477feae-b13f-45f7-8964-f9684975300d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('887f3ba4-adbf-4baa-90d1-66b33c5ff822', 'c2d58a53-82cf-4a81-91be-da74600c7969', 13, '60517644', 'ある愛の詩', '誤解されて留奈と結婚させられることになってしまった永澄。江戸前組により幽閉されてしまった永澄と、悲嘆に暮れる燦。一方、留奈は永澄を奪い取ったことで大喜び。そして永澄と留奈の結婚お披露目会の場として、東西極道懇親会が開催される。その中、固めの盃を出された永澄の口から思いも寄らぬ言葉が飛び出して…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bc971d74-8199-4a0e-abf2-ec6efca9234d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0cc7486-e6c7-493c-9b09-6d6a974a7b9a', 'c2d58a53-82cf-4a81-91be-da74600c7969', 14, '60517642', '子猫物語', '魚人族の弱点が猫であることに気づいた永澄。日頃の恨みを晴らすべく、中学校へと子猫を連れて行く。効果は抜群で、海や豪三郎は子猫が怖くて永澄に対して全く手が出せない始末。だが、永澄に負かされて怒りが収まらない豪三郎は、新たな刺客として、自分直属の親衛隊を呼び寄せるよう、巻に指令を下すのだった…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/02a43e2d-954c-49be-99d4-022a2e18f921.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ef398d2-39e4-46d1-971c-775c2babd007', 'c2d58a53-82cf-4a81-91be-da74600c7969', 15, '60517627', '君の名は', '海によって仕組まれたダブルデートに、四人で行くことになった永澄。集合場所へ行ってみるとサルと留奈までいて、どの組合わせでデートをするのかと一騒動。くじ引きの結果、無事に燦と組めることになった永澄だったが、留奈に頼まれジュースを買いに行く最中に、うっかり見知らぬ美少女とぶつかり眼鏡を割ってしまい…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4c5e9e82-df67-45d0-9ecf-6f0bc7404710.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b56fb21-192f-4b9f-9d8e-849d2a51a32b', 'c2d58a53-82cf-4a81-91be-da74600c7969', 16, '60517629', 'マイノリティ･リポート', '永澄たちのクラスへと転入してきた謎の転校生、不知火明乃。燦や留奈たちの行動を一挙一動見逃さず何かをメモしている彼女は、実は、燦たちが上手く正体を隠して人間界で生活出来ているかを審査する人魚試験官だったのだ。果たして彼女たちは、ボロを出すことなく、無事に明乃の人魚試験を乗り越えることが出来るのか…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/72165d02-1923-4c23-89d3-d17cea1af94b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fb53425-8eab-4ec4-8760-2c05887bf8d8', 'c2d58a53-82cf-4a81-91be-da74600c7969', 17, '60517628', '県警 対 組織暴力', '転入早々、磯野第八中学校最強伝説を築いてしまった不知火明乃は、早くも周囲から八中の「悩まし番長」と命名されてしまう。明乃の意思とは裏腹に、磯野一中から七中までの番長が集結した磯中番長軍団や、銭形巡を始めとする女子クラスメイト軍団、豪三郎を始めとする瀬戸内組の面々までが加わる争いが勃発して…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/02311a72-840e-4f74-bc98-712cf31b0960.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2464d68-4c0f-4326-8ec9-9a0111b29702', 'c2d58a53-82cf-4a81-91be-da74600c7969', 18, '60517625', '肉体の門', '担任の豪三郎がすっかり忘れていたため、急遽修学旅行へと出発することになった永澄たち。皆でお風呂に入ったりする修学旅行に燦は不安で一杯。しかも、修学旅行中も明乃の人魚試験は絶賛続行中。みんなが楽しむ中、相も変わらず独りで行動する明乃を気遣い声をかける永澄だが、そんな二人に巻の魔の手が…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ac6c1af5-d31e-4703-9509-7b11db573374.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c07b5a91-6f3e-4fdc-8dce-2edceb4ee5e3', 'c2d58a53-82cf-4a81-91be-da74600c7969', 19, '60517638', 'ショウほど素敵な商売はない', '初主演映画の撮影で京都を訪れていた留奈とも合流し、賑やかになった永澄たち。一方、永澄と燦を別れさせるという密命を受けている明乃は、飲んだ者の欲望をさらけ出させる秘薬を飲ませることで永澄のみっともない姿を見せつけ、燦を幻滅させようと企む。計画を実行するため、エラ呼吸三兄弟や海を仲間に引き込んだが…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/102e5e04-8559-43e4-98c6-683b796738f8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3747cbf8-1b55-4fd1-9836-1a64256e2248', 'c2d58a53-82cf-4a81-91be-da74600c7969', 20, '60517643', '男たちの挽歌', '“年頃の女の子=ギャル”の心を理解するために、ルナパパは資料を探し始めた。色々と検索した結果、一つの資料へと辿り着くのだが、それはなんとギャルゲーだった。元にする資料が根本的に間違っていることに気づかないまま、同じように娘の心を理解したい豪三郎も引き込み、父親たちは暴走を始めて…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/61d83308-5e26-4787-a3b6-fc29fa8d8776.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('019332b8-9609-4777-8208-803d7f5e7421', 'c2d58a53-82cf-4a81-91be-da74600c7969', 21, '60517626', '恋のからさわぎ', '差出人不明のラブレターが入っているのを発見し、自分がモテ始めていると思い浮かれる永澄。だが、隠していた手紙を巻に見つけられ、ラブレターをもらったことが、燦や留奈たちにまでバレてしまう。永澄がどう動くのかを木陰から見守る一同だったが、その永澄との待ち合わせ場所へと現れたラブレターの差出人はなんと…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6ef0bcc9-2a42-49e2-996f-919118d53f1c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('335c1712-d80e-45d0-8b5d-3c7f26d426bc', 'c2d58a53-82cf-4a81-91be-da74600c7969', 22, '60517630', '傷だらけのアイドル', 'ドラマの役作りの練習のため、燦に理想的な恋人役を演じることを頼む留奈。だがそれを了承した燦の理想の男性像は、むさ苦しいほどに漢くさい番長タイプだった! 燦の暴走に振り回され、全く練習にならなくなってしまった留奈は、ドラマの練習はあきらめ、次に隠し芸の特訓を始める。その内容は“腹話術”で…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/06618636-3cee-4a26-81a3-4dc5423122ef.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('534836d5-cd64-4450-be32-b95676df2c84', 'c2d58a53-82cf-4a81-91be-da74600c7969', 23, '60517649', '過去のない男', '幼い頃に失踪した兄の行方を探し続けていた明乃は、以前に自分と互角に渡り合った燦の太刀筋が自分の流派と同じだということに目をつけた。燦たちと一緒に、その師である政のもとを訪れ、どこから剣術を学んだのかを問いただす明乃。実は政は記憶喪失で、瀬戸内組に入る前までのことは何も覚えていないと言うが…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/250e98b5-3955-4edd-afc4-be761a83b54f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b40d984-31a5-49bb-9fff-83fb2025d9e3', 'c2d58a53-82cf-4a81-91be-da74600c7969', 24, '60517632', 'さらば友よ', 'お尻におできが出来てしまった海。クールでカッコいいキャラの自分のお尻におできが出来たことがバレる訳にはいかないと、こっそり通院していた。後日その病院の前を通りかかったサルがふとした勘違いから海が不治の病にかかっていると思い込んでしまう。その噂は広がり、世間をも巻き込んだ騒動へとなっていく…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/82e7ccb4-e461-4516-972d-accb0e89b480.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf2a3829-a1f0-4af2-9202-50f85fe167b4', 'c2d58a53-82cf-4a81-91be-da74600c7969', 25, '60517633', '家族ゲーム', '些細なことが原因でケンカをしてしまった燦と永澄。普段ならばすぐに仲直りをするのだが、お互いに気まずくなってしまい、口もきかなくなってしまう。ケンカ状態の二人を周囲は心配するけれど一向に仲直りの気配はない。永澄の態度にいつも以上に苛立ってしまった燦は、魚人貴族が主催するパーティーへ出かけてしまい…。', '2015/04/16 12:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e65a5849-202e-4c44-81e1-248d4d43e9f2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7be7d017-e9b3-4c1e-942e-c46674735637', 'c2d58a53-82cf-4a81-91be-da74600c7969', 26, '60517639', 'きみの帰る場所', '【シーズン1 最終話】魚人貴族“源義魚”が主催するパーティーへとおびき出され、囚われの身となってしまった燦と瀬戸内組の面々。しかし、その燦を救い出すため、永澄が海や留奈たちと瀬戸内へと向かっていた。果たして永澄は、囚われの燦を義魚の魔の手から取り戻すことが出来るのか? そして、壊れてしまった夫婦の絆の行方は?', '2015/04/16 12:00:00', 1410, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b483077a-6379-4f0f-91a4-e7287c76d62c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9a763faf-f489-40a4-a582-4eaa56249238', '政宗くんのリベンジ', '', 'hulu', 'masamunekuns-revenge', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50027764_series_art__338x600_masamunekuns_revenge_71daefae9c0d9b6146fa72fb2e21cf12.jpg?w=331&h=447&p=t', 'hulu', 2017, 0, 1, 'FINISHED', NULL, 21857, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('90352aff-c5bb-4538-a0b5-9db8eb92b462', '9a763faf-f489-40a4-a582-4eaa56249238', 'hulu-masamunekuns-revenge-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c0354a77-b754-470d-a7ac-f054cec0343d.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26f02c30-1a33-4444-9266-ae62b50a67e0', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 1, '60824465', '豚足と呼ばれた男', '8年前、美少女･安達垣愛姫に豚足と呼ばれ、こっぴどくフラれた真壁政宗は、愛姫に復讐を果たすため、激ヤセし、名字を変えてイケメンに生まれ変わった。政宗は転入した高校で、「残虐姫」と呼ばれる愛姫と再会を果たすのだった。', '2017/01/13 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c0354a77-b754-470d-a7ac-f054cec0343d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f13d590c-4415-48a6-b6fc-3bffbb341717', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 2, '60826393', 'シンデレラは笑わない', '「豚足」と書かれた手紙を受け取った政宗は、自身の黒歴史を知る者が校内にいること確信し動揺する。手紙の送り主、怪人Xが誰なのか探ろうとする政宗だったが、その正体は意外な人物だった。', '2017/01/20 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/eeb97a2a-f9ae-493c-a8c0-456dc00acd06.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a1e720b-842f-4dab-b7b7-56b491f45d17', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 3, '60829770', '吉乃のマジックショー', '愛姫とのデートの約束を取り付けるため、小十郎とチームを組んで、愛姫と吉乃に実力テストの合計点で勝負を挑むことになった政宗。勝てば愛姫とデート。負けたら愛姫につけられた仇名を卒業するまで背負って過ごさなければならない。果たして勝負の行方は…!?', '2017/01/27 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/45a6c605-42a7-48df-bf0e-42fd4dde0d58.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6c7edd4-4731-4c0b-9847-a23243da97c9', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 4, '60831228', '今そこにある危機', '愛姫への復讐を果たすべく、少女漫画「バラステ」で愛姫への攻略方法を勉強する政宗だったが、師匠こと吉乃からダメ出しをされてしまう。攻めのラブ盛りアプローチから一転、愛姫を無視して気を引こうとする政宗だったが…。', '2017/02/03 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/05ea7319-5377-47c1-b09e-e70f3cf1ee56.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0afead93-306d-44fd-bd8b-a614c58f22be', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 5, '60834748', 'ミステリアス･キャット', '車に轢かれそうになった愛姫を助けた政宗だったが、その車に乗車していた名も知らない美少女に「お逢いしとうございました…」と言われ抱きつかれるハプニングに遭遇する。数日後、藤ノ宮寧子 (ふじのみやねこ) と名乗る、美少女が政宗のクラスに転入して来る。寧子の登場以来、愛姫の機嫌が何時にもまして悪くなり…。', '2017/02/10 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fc170795-cf1a-410c-8604-856907af1f8b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d5e04c6-3164-41b4-b82d-8b1cc0f6c4f8', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 6, '60838211', '突撃! お宅訪問戦', '政宗に熱烈なラブコールをしかける寧子。その魂胆が読めず警戒しているなか帰宅すると、そこには吉乃と寧子が料理を作って待っていた。政宗は、自宅にある数々の見られたくない過去の証拠を隠そうと奮闘するのだが…。', '2017/02/17 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2bf561bf-e9ee-470d-9b62-19e9ab934cea.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('232f8807-483e-47cf-8119-911c8364736e', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 7, '60841480', '綱手島事件', '期末試験を終え、夏季休暇がスタート。政宗は一気に愛姫へアプローチを仕掛けるべく、吉乃･寧子等6人で愛姫の別荘地のある「綱手島」へと向かう。そこで、この旅行中に愛姫と進展がなければ全てバラすと吉乃に脅され焦る政宗は、お目付け役として派遣された安達垣家秘書の由井崎に、愛姫と付き合っていると豪語する。二人は恋人同士のフリをすることに…。', '2017/02/24 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f44b83a1-ecdd-40a2-b007-feef235f229b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68f926bc-29ba-49ce-8d32-476ba16dc5f1', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 8, '60848052', '君じゃないんだ', '政宗の携帯に愛姫から着信があった。浮かれる政宗だが、幼いころの政宗と愛姫の写真が自宅からなくなっていることに気が付き、犯人は寧子だと確信する。真相を確かめようとこっそりと寧子の自室へ忍び込む政宗だったが、寧子に見つかってしまう。寧子は予想外の行動を取るのだが!?', '2017/03/03 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8eb9e2f3-6bb0-422c-8258-437c23703f2e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('731e91c9-250f-4fce-b653-2df120f29061', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 9, '60852487', '愛とも恋ともいうけれど', '寧子からの交際の申し出を断ったことを皆に打ち明ける政宗。不穏な空気の中、行方不明の寧子を皆で探すことに。捜索中に愛姫と居合わせる政宗だったが、振られた寧子に同情する愛姫に、豚足というあだ名に覚えがないか打ち明ける。その一方で、居場所が見つかった寧子は昔話を語り始める。', '2017/03/10 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6f45e46f-d485-46ab-a691-bb2c54d7290c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b2e159b-3fdd-46f2-82c7-573f5ad84331', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 10, '60855491', '疑惑の新学期', '突如愛姫の前に現れた政宗と同じマサムネ、雅宗兼次。夏季休暇も明け、変わらず愛姫にアプローチをする政宗は、彼が愛姫の許嫁であることを告白される。兼次への態度が自分と明らかに違うことに焦る政宗は吉乃に対策を相談するが…。', '2017/03/17 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cd9fd62c-83d8-41e2-b7f3-c34ff07b1754.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('110791b6-a639-40af-8c92-cc643a82fcb5', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 11, '60860093', '八坂祭の白雪姫', '文化祭の出し物「白雪姫」で多く票を獲得した方が、後夜祭で愛姫と踊れるという勝負が幕を開けた。火花を散らす政宗と兼次。そんななか、二人の身に思わぬハプニングが起こる…。', '2017/03/24 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ea4f6168-bb75-4c8a-b06f-cfb4ceb366ea.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3b474b0-41a4-4c0d-ae41-1d4ca8a00a0e', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 12, '60861612', '死んでもマイクを手放すな', '【シーズン1 最終話】いろいろと大変だった文化祭も終わり、政宗たちと愛姫親衛隊たちも参加して打ち上げを開催するもカラオケ勝負に! そして政宗のリベンジの行方は…!?', '2017/03/31 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/86178180-0612-49b5-b935-1d8c740f2451.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4580fd9f-7ad6-4441-935c-935dc65be119', '90352aff-c5bb-4538-a0b5-9db8eb92b462', 13, '100068850', 'うちのママにかぎって／綱手島、ふたたび。／12時を過ぎたシンデレラ', 'TVシリーズの番外編として、原作：竹岡先生原案、コミックスのその後をショートストーリー3部構成で映像化! 政宗･愛姫･吉乃それぞれの想いを収録。', '2020/12/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48a68ce8-596b-4524-abe4-0e60fd8ad55a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a83a84e9-7e1f-434c-a64e-89656ed303c4', '政宗くんのリベンジR', '', 'hulu', 'masamune-kuns-revenge-r', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dfc5ac43-3e70-428d-848e-0965cea75316.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 146953, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('24ef548e-6b30-4731-a76d-e75f42ef7baf', 'a83a84e9-7e1f-434c-a64e-89656ed303c4', 'hulu-masamune-kuns-revenge-r-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fdc9d952-3ae9-4fe0-8554-4e3ec281872c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfea0498-f2c0-4963-ab67-d03f158abfe8', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 1, '100151847', '巴里とオがつくマドモアゼル', '様々なハプニングに見舞われた文化祭。それから月日は流れ、真壁政宗たちは修学旅行でフランスを訪れる。修学旅行中に安達垣愛姫に対する復讐「デッド･オア･ラブ作戦」を次の段階に進めようと意気込む政宗。一方、愛姫は政宗に「ずっと考えてたの、一度あなたとゆっくり話をするべきだって」と意外な言葉をかける。彼女の真意が分からず困惑する政宗……。そんな時、2人は日本のアニメや漫画に興味を持つフランス人のオタク少女、ミュリエル･ベッソンと出会い……!?', '2023/07/10 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fdc9d952-3ae9-4fe0-8554-4e3ec281872c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4aa81bd-9c9c-4457-a80e-0135b589f1b7', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 2, '100152294', 'プリンセスの告白', '政宗の復讐作戦を陰から協力してきた小岩井吉乃。だが、遂にそのことが愛姫の許嫁･雅宗兼次にばれてしまう。厄介な存在である吉乃の動きを封じるべく、彼女のことを脅す兼次。そんな彼を最初は相手にしない吉乃だったが、代々、安達垣家に仕える家庭の事情が仇となり、身動きがとれなくなってしまう。一方、政宗と愛姫はミュリエルの兄、フランク･ベッソンから頼まれて、日本人高校生カップルの見本として擬似デートをすることに。カップルとは程遠いぎこちないやり取りをする中、不意に愛姫が8年前の出来事を話し始める……。', '2023/07/17 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1718cf1a-dfdc-46e9-aaa4-6a42ec754d15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('86084ed9-49b8-4361-b293-7ab813e89d2d', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 3, '100153306', '忘れたころにやってくる', '政宗と愛姫の大喧嘩で幕を下ろした修学旅行……。帰国後も2人の関係は修復されず、「デッド･オア･ラブ作戦」は中断を余儀なくされる。作戦を進行すべく、なんとか愛姫と仲直りしようとする政宗だったが良い方法が思いつかず手詰まりな状況に。そんな時、彼のもとにミュリエルの兄、フランク･ベッソンが現れ、政宗と愛姫をモデルにミュリエルが描いた漫画を置いていく。その漫画をきっかけに政宗は自身が「豚足」呼ばわりされた8年前の出来事について、とある1つの可能性にたどり着く。', '2023/07/24 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e82c5b70-c305-482c-b495-b21d7b5a4db3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df0c3e74-909a-4cc7-ac50-a85c96074b24', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 4, '100153780', 'あんたなんか好きにならないわよ、豚足', '8年前、自身を「豚足」呼ばわりしたのが吉乃ではないかという疑念を抱いた政宗。彼から真相を問われた吉乃は、政宗を突き放したことを告白する。「デッド･オア･ラブ作戦」の根幹を揺るがす真実に動揺を隠せない政宗。そんな彼に対して吉乃は幼少期の自分が愛姫と政宗に抱いていた感情や、高校で再会した政宗に協力していた真の理由を明かすのだった。一方、時を同じくして兼次は政宗を愛姫から遠ざけるべく、愛姫の親衛隊を味方につけて……?', '2023/07/31 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a689d150-8247-4bfd-a95c-205b8e3283bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4bfbb07-2d32-41ff-932d-cda4c35de928', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 5, '100154685', '彼と、彼女になりまして', '吉乃から真実を告げられた政宗。兼次と愛姫のデート現場に駆け付け、その場の勢いで愛姫に告白。さらに兼次と揉み合いの喧嘩をしながら、自身が8年前に愛姫と出会ったデブでいじめられっ子“マサムネ”だと言うことも告げる。その言葉で政宗こそが思い出の少年だと気が付いた愛姫は、彼の告白を受け入れ、2人はめでたく恋人となる。しかし、復讐対象ではなくなった愛姫に恋愛感情とは別の複雑な感情を抱く政宗……。そんな彼の気持ちに反応するように彼の体に異変が起こり始めて……!?', '2023/08/07 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3309af5-7ae7-47ec-bb07-1020de32f1cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67190d7b-411a-4dcc-9a98-100f7b3511ab', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 6, '100155069', '二度目のデート', '吉乃から協力関係の解消を告げられた政宗。彼女の最後のアドバイスとして、12月24日が愛姫の誕生日だと聞いた政宗は、愛姫をクリスマスデートに誘う。彼からの誘いにまんざらでもない表情を見せる愛姫。当日、2人は以前のデートと同じく映画館を訪れる。ギスギスしていた以前とは異なり、恋人として甘酸っぱい幸せな時間を過ごす政宗と愛姫。だが、その後はスケジュール通りに進行できず、政宗の家でお茶をすることに。当然、家には家族がいるものだと思って帰宅する政宗たちだったが……!?', '2023/08/14 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7bf9fe33-a3d3-448a-8660-6b722447c1d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ef3f478-4469-4587-a184-2859a55b6f3a', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 7, '100155729', '言うても詮無き告白ですが', 'せっかくのクリスマスデートを最悪の形で終えた政宗と愛姫。その後、2人が顔をあわせることなく迎えた新年。政宗は原因不明の発疹に頭を悩まされ、愛姫も政宗の部屋で目撃したリベンジ帳が頭をよぎり、2人は悶々とした気持ちで冬休みを過ごしていた。新学期が始まると思わず吉乃を頼ろうとしてしまう政宗。その気持ちを抑え、代わりに寧子に愛姫や体調のことを相談する。すると前々から彼の異変を感じていた寧子は……。', '2023/08/21 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e5c87cd-d585-490c-9e51-892987895087.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6354a259-2e88-4d3e-ada7-b01d39b6962f', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 8, '100156490', '気づいちゃいけないこともある', '買い物中の吉乃と鉢合わせた政宗。すぐさまその場を立ち去ろうとする吉乃だったが、足を捻挫していたこともあり、2人は公園で休憩することに。久しぶりに訪れたふたりきりの時間だったが、政宗と距離をとる吉乃。一方、政宗は愛姫の恋人として楽しく過ごしていることを明かすも、とある感情が心に引っかかっていた。時を同じくして親衛隊に政宗と付き合っていることを告白した愛姫だったが、自身の気持ちに迷いが生じていることに気が付く。そんな時、とある人物に再会して……。', '2023/08/28 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e24620c-65d2-4ab2-89bf-42c6d759305d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee710752-6ffd-491f-8f13-b61b901fb291', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 9, '100157106', '聖バレンタインが見ている', 'バレンタインが1か月後に迫り、色めきたつ男女一同。各々が好きな人にチョコレートを渡そうと準備する中、吉乃に励まされた愛姫も政宗に手作りお菓子を渡すことを決意。苦戦しながらバレンタイン前日に見事、チョコクッキーを完成させる。そして迎えた2月14日の放課後、久しぶりに顔をあわせた政宗と愛姫。その場で彼女からプレゼントを手渡され、大喜びの政宗。バレンタインをきっかけに再びふたりの距離は縮まったかに思われたが、政宗はとある違和感を覚えていた。', '2023/09/04 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5dc8efe-b707-465d-84e0-673620eecb8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e5fcf67-462e-4131-b613-b6e21afb74b8', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 10, '100158094', 'ホワイトアウト', '過去の想い出に縛られ、本当の気持ちを押し殺して愛姫と付き合う政宗……。一方、政宗の幸せを願う寧子から彼と別れるように言い渡された愛姫。以前、目にしたリベンジ帳から政宗が自身に復讐目的で近づいたことに気が付いていた愛姫は、彼への恋心が一方通行であることを痛感し、涙を流す。そんな彼女に吉乃は8年前の出来事や「デッド･オア･ラブ作戦」に関する真実を告白。全てを知った愛姫はとある考えのもと、政宗をホワイトデーデートに誘う。果たして、2人の歪な恋の行きつく先とは!?', '2023/09/11 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e648e3d-f33a-4733-8938-9f769fec5198.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c46e6832-3c8d-42a6-b0a2-b22168e66ddf', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 11, '100158714', '自分の気持ちに向き合って', 'ホワイトデーデートの日、愛姫から別れを告げられた政宗。翌日から学校を無断欠席してしまう。心配して自宅を訪ねる吉乃たちだったが政宗の姿はなく、8年前の幼少期を過ごしていた信州に向かったこと知る。その帰り道、吉乃と2人きりの時間を作った愛姫は“主と付き人”という関係を捨てて、話すことを決意。今まででの出来事を振り返るふたりだったが、話題は政宗のことに。必死に彼に対する恋心を否定する吉乃。だが、愛姫に背中を押されたことで政宗のもとに向かう決心をする。一方、政宗はひとり、8年前の出来事に思いを馳せていた……。', '2023/09/18 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e492176f-8fdf-4755-bf36-ad03966ab876.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e01edbb-0ad7-42be-b195-b3a59c08735c', '24ef548e-6b30-4731-a76d-e75f42ef7baf', 12, '100159287', 'Dead or love?', '【シーズン2 最終話】自身の気持ちと向き合い、信州に居る政宗のもとに駆け付けた吉乃。再会した彼に吉乃は勢いのまま告白をするのだった……。それから迎えた新学期。吉乃の態度から自身の失恋を察し、気持ちを切り替えようとする愛姫。だが、進級のクラス替えで政宗と同じクラスになってしまう。授業中や休み時間、様々な場面で政宗から話しかけられ、ついつい彼のことを意識してしまう愛姫。そのせいで悶々とした学校生活を送る中、ある日の放課後、吉乃から旧校舎に行くように告げられる。言われた場所に行くとそこで愛姫を待っていたのは!?', '2023/09/25 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/356d3de3-a600-4b28-aeaf-a5145ddcae4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2089ddb5-5f4c-486d-b8cf-b418ba2fdc73', '星界の戦旗', '', 'hulu', 'banner-of-the-stars', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57f81cc2-3566-4acf-9db4-4090afa5918c.jpg?w=331&h=447&p=t', 'hulu', 2000, 1, 1, 'FINISHED', NULL, 396, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('77855198-4013-4e05-8842-f18e3b06c3ab', '2089ddb5-5f4c-486d-b8cf-b418ba2fdc73', 'hulu-banner-of-the-stars-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b115a9b-a65a-4388-b501-f88564f17082.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7083944-8606-4875-bfbb-3f76255b2e71', '77855198-4013-4e05-8842-f18e3b06c3ab', 1, '100207604', '再会', 'アーヴによる人類帝国は、人類統合体への大規模な反攻作戦を開始した。そんな中、主計修技館を卒業したジントは、ラフィールが艦長をつとめる突撃艦バースロイルに赴任する。慣熟航行を終えたバースロイルは人類統合体への大規模な反攻作戦の戦列に加わるべく、星界軍の拠点･ヴォベイルネー鎮守府を目指す事に……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b115a9b-a65a-4388-b501-f88564f17082.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4949f32a-96a6-40cc-a64a-11f8d680f0bc', '77855198-4013-4e05-8842-f18e3b06c3ab', 2, '100207605', '幻炎作戦', '人類統合体に対し、旧領回復を目的とした幻炎作戦を発動したアーヴ帝国。スポール提督率いる幻炎第一艦隊は、敵宇宙要塞を撃破してアプティック星系内に進む。アプティック星系で哨戒の任に就くこととなったバースロイルだが、突撃隊司令アトスリュア百翔長は、3年前にラフィールが殺したフェブダーシュ男爵の妹だった。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/376863ba-bf0d-4376-9f6b-c3afc89879f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('602165ca-d1c4-4def-8248-98f524ff9a13', '77855198-4013-4e05-8842-f18e3b06c3ab', 3, '100207606', '突撃艦“バースロイル”', 'ダクルーで休息していたジントの元に、アトスリュアが現れる。兄のことは恨んでいないと言うアトスリュアだが、それでもジントの警戒心は晴れないままだった。そんな中、バースロイルは正体不明艦の迎撃を命じられる。緊張するジントとは反対に、艦長として初の実戦に挑むラフィールは、逸る心を抑えられずにいた。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/002eda2e-1fd1-4e80-ab7b-f145169bdc84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1faa5f53-b8a4-41b0-a337-bdf6c0c9826f', '77855198-4013-4e05-8842-f18e3b06c3ab', 4, '100207607', '初陣', 'アプティック門から平面宇宙に進入したアーヴ軍は、敵の威力偵察だった時空泡群の追撃を開始した。攻撃力も防御力もアーヴ突撃艦を上回る敵巡航艦に、苦戦を強いられるラフィール。激しい戦闘が続く中、敵の電磁投射砲がバースロイルの一角を貫き……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c0cee8d-dcd8-4443-9b2f-7756fc898746.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d55938e0-a2c5-4898-85e2-2577a4b56a5f', '77855198-4013-4e05-8842-f18e3b06c3ab', 5, '100207608', '華やかな狂気', '初陣で傷ついたバースロイルは補修に回り、翔士たちは束の間の休暇を楽しむ。その頃、幻炎作戦は新たな局面を迎えていた。それによってアプティック防衛艦隊の指揮官に派遣されたのは、“華麗なる狂気”という異名を持つ、ビボース一族の兄弟だった。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d58b2f1a-7333-4fda-9f76-758ac2498e23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79602c26-209e-4c99-a539-e6a29a22b588', '77855198-4013-4e05-8842-f18e3b06c3ab', 6, '100207609', '弔いの晩餐', 'ジントはアトスリュアから、共に兄の誕生日を祝おうと誘われた。彼女の兄は、以前ラフィールがやむを得ず手にかけた前フェブダーシュ男爵。死者の誕生日を祝うという弔いの晩餐に、ラフィールは出席することを決める。会食の席で、ラフィールはアトスリュアに、自分を恨んでいないかと問いかけるが……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae12a9aa-7de6-4cbf-927d-ca302fb4c97f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f15b43e-3f09-4744-b6ef-b1e4ff6ae88d', '77855198-4013-4e05-8842-f18e3b06c3ab', 7, '100207610', 'くらやみの逃亡', '平面宇宙内の移動速度は、時空泡内の質量に反比例する。そのため、戦闘で時空泡内に大量の浮遊物を抱えたバースロイルは、同じ状況の僚艦セーグロイルと共に、本隊から遅れて帰還することになった。しかしその途中で敵の奇襲を受け、セーグロイルは大破してしまい……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9740b8e-74a9-4d71-8bcc-d4b2fd332a20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05a7335f-d4a8-498f-aa0a-dfbf15435e65', '77855198-4013-4e05-8842-f18e3b06c3ab', 8, '100207611', '決戦前夜', '敵･人類統合体の狙いが、アプティックと確定した。来たる決戦を前にして、突撃艦バースロイルのクルーたちには、束の間の休息が与えられた。それぞれの時間を過ごしていくジントたち。そして、決戦の日がついに訪れる……!', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa3ef7fc-5d94-4e6a-a9b3-33df834240e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1463f103-d128-4668-92c6-2deb4adc35c9', '77855198-4013-4e05-8842-f18e3b06c3ab', 9, '100207612', 'バースロイルの戦い', 'ラフィールの所属する突撃艦隊は、味方の艦隊が到着するまでの間、独力でアプティック門を守らなければならない。一時的に臨戦態勢が解除され、休息を取るジントとラフィールは、アーヴの三つの生き方について話し合う。やがて、敵機雷群が次々と門からわき出してきて……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40573ca8-c009-43e5-afa4-b6d861955146.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cbdf660-0ace-4361-848b-58aab32d959c', '77855198-4013-4e05-8842-f18e3b06c3ab', 10, '100207613', '流れる星', '人類統合体の機雷は、複数の小型機雷に分裂する新型の機雷だった。新兵器による執拗な攻撃の前に、アプティック防衛艦隊は苦戦を強いられる。機雷に囲まれた僚艦キドロイルの支援に向かったバースロイルだが、キドロイルは機雷の直撃を受けて爆散してしまい……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d987dce8-3eae-4679-b792-1eae46b464a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62546603-e1d9-432e-a64f-e259ffda7318', '77855198-4013-4e05-8842-f18e3b06c3ab', 11, '100207614', '灼熱の戦場', 'アーヴ艦隊は、進軍を開始した敵艦隊に対して格闘戦を仕掛ける。僚友の死を目撃して気落ちしていたラフィールだが、アトスリュアの指揮を受けて、自軍を上回る数の敵艦隊を相手に勇戦する。しかし、敵艦の主砲がバースロイルを目掛けて発射されて……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cdd4f774-23f6-444c-b8ee-5339e97770f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0078892-77b1-4899-bd4e-77ca6680a0ba', '77855198-4013-4e05-8842-f18e3b06c3ab', 12, '100207615', 'アプティック門沖会戦', '集中砲火を受けたバースロイルは、戦線離脱を余儀なくされる。退艦の指揮を任されたジントは取り残された負傷者の救助に向かうが、その途中で爆発に巻き込まれ、通信が途絶えてしまう。それを知ったラフィールは、ジントを探すため、爆発間近のバースロイルに残ることを決めて……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff599d57-0f26-46b0-bf29-b2bf219ec1bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4249fb7e-d5f2-4869-bcea-5663a0a5a876', '77855198-4013-4e05-8842-f18e3b06c3ab', 13, '100207616', '絆のかたち', '【最終話】ようやくアプティックに第一艦隊が到着した。スポール提督の働きによって、アーヴ軍の勝利は決定的なものになる。一方、救命莢でバースロイルから脱出したジントとラフィール。しかし、電磁波によって救命信号は打ち消され、救命莢の酸素も残り少なくなってしまい……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b526bc4e-0c9b-4d92-8207-b28547ef6fcc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f4fd4314-1045-402e-8b05-2d43225b65b5', '星界の戦旗 II', '', 'hulu', 'banner-of-the-stars-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b6ce9ef-b446-400f-9421-f4485fc96a74.jpg?w=331&h=447&p=t', 'hulu', 2001, 2, 1, 'FINISHED', NULL, 397, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f4cbebf8-e075-469d-a6fa-d3e073700b07', 'f4fd4314-1045-402e-8b05-2d43225b65b5', 'hulu-banner-of-the-stars-2-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/016d6883-a231-46a1-86a1-fdbd7f2db22e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f20c972c-ce87-485c-ad71-ac6da9e6ab42', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 1, '100207617', '狩人作戦', 'ビボース提督率いる狩人第四艦隊所属突撃艦バースロイルは、新たな任務を受け、輸送艦隊と共にロブナス星系に向かう。制圧した惑星ロブナスIIの代官という職を命じられたラフィールは、いささか不満げな様子。そんな中、平面宇宙を抜けロブナスIIに着いたバースロイルに、突然、複数の指向性電磁波の照準が向けられる。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/016d6883-a231-46a1-86a1-fdbd7f2db22e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b042ebba-0ff3-4791-872d-62882082ca22', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 2, '100207618', '流刑の星', 'ロブナスIIからの電磁波は、領民政府代表を名乗る四人の人物からの通信だった。この惑星は、実は犯罪者たちを収監する流刑の星なのだ。強襲輸送艦ダーク･セスで降下した代官副代行ジントは、星界軍に対し大規模な移民計画を要請される。視察も兼ね、ジントはサムソンたちと共に食料配給の輸送艇に同行するが……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6b02077-3a4a-4178-b1d3-7e7ade5e0033.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('efe504ed-dc4d-45ab-882d-79a25c993aa9', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 3, '100207619', '移民計画', '行政長官メイディーンからの要請は、行政庁職員とその家族、約二万人を移民させることだった。ジントは、配給の輸送艇が狙撃されたことで叛乱の可能性を実感、ラフィールへ報告する。そんな中、シャンガル以下西部矯正区の囚人たちも移住の希望を申し出る。一方、平面宇宙では更なる深刻事態が待ち受けていた。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0877752e-78c4-4e80-b600-76e454a7f260.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6a1e6f5-af60-4542-a9cb-e33aaf26bd09', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 4, '100207620', '狩人たち', '狩人艦隊は、敵艦隊の不穏な動きを察知した。敵残存艦隊は、突出するネレース提督の第四艦隊と本体の間をぬって天川門郡中心部へ脱出を図ろうというのだ。この敵艦隊の進路上にロブナス星系があるため、輸送艦隊に撤退命令が下される。移民計画が中断され困惑するロブナスII内で、とうとう叛乱が勃発してしまう。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/833264d2-30ce-4e15-b0cf-2192728ac02f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49ab7119-2e2d-4fcb-b251-3d2e15b2ff16', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 5, '100207621', '叛乱', 'アンガスン率いる囚人たちの叛乱は、その範囲を広げつつあった。戦火は管理区まで迫り、ジントたちはやむなく行政庁舎の放棄を決める。一方、ラフィールの指揮により、ダークセス以下二隻の強襲輸送艦は地上降下を開始する。ラフィールの許可を得てメイディーンと共に海務部へ移動したジントは、移民を指揮するが……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/452bed85-0ca3-4803-8a0f-ff085c6c6afe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b5c7a54-3a8f-413c-ab51-45e2f105a1c8', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 6, '100207622', 'アーヴの地獄', '港務部を後にしたジントとメイディーンは、移動の車中で叛乱側の刑務官によって拉致されてしまう。この叛乱の裏には、アルカイクという名の麻薬の存在があった。叛乱の首謀者アンガスンとドクフーは、ジントを人質にしてラフィールと交渉を始めるが、ソバーシュによってアーヴの怒りを目の当たりにしてしまう。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9f87cb2-58d2-47cd-96c7-405eb75b07ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('112d3207-70e0-4e95-a671-7ecb323c2d43', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 7, '100207623', '金色烏 (ガサルス) の旗', '敵残存艦隊追撃のため、ロブナス星系を訪れたスポール率いる狩人第一艦隊。だが、そこにはバースロイルが残っていた。即時撤退を要求するスポールに、ラフィールは、帝国の威信をかけて移民計画の遂行とロブナスIIの保持を要求する。一方、ジントは二派に分かれて対立を始めた囚人たちの抗争の中で意識を失ってしまう。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5dd81951-4696-450c-85a2-7621c7f69f58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb915e51-8568-4a31-94f9-f4dd3fac9287', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 8, '100207624', '守るべきもの', 'スポールは、ラフィールと約束したロブナスIIの保持を少しでも長引かせるため、敵艦隊と決死の時間の取引を行う。そんな中、ラフィールのもとに新しい領民代表トマソフが訪れる。彼が持ってきたのは、行方不明のままのジントの端末腕環だった。失望を押し殺すラフィールだが……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6af1df9c-32e2-4b58-9929-afd850a2c3d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0e8837e-218f-4ab4-a519-e58d1141b99f', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 9, '100207625', '弓を置くとき', 'スポール率いる狩人第一艦隊は全方位雷撃戦を展開する。しかし、敵艦隊の執拗な攻撃により撤退を余儀なくされ、その後ソードに突入してきたラフィールと合流する。一方、狩人第四艦隊司令長官ビボースは、包囲していたバスコット門の先に友軍旗艦の姿を確認する。そこにいたのは、ラフィールの父･アブリアル大提督だった。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb07a011-13c3-4586-89f8-469e7646bcb4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9842b2b8-bcf7-4d06-8f75-c26c50cf658e', 'f4cbebf8-e075-469d-a6fa-d3e073700b07', 10, '100207626', 'アブリアルの涙', '【最終話】休暇願いを出したラフィールは、ロブナスIIに降り立ち、個人的にジントの行方を探そうと画策した。だが、友人のために料理を用意することでジントの無事を祈るサムソンに諭され、断念する。そんな中、ジントの頭環を持った女性残留者が連行されてきた。不安を抱えつつ、ラフィールはジントを待ち続けて……。', '2024/12/25 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ab8abac-eb10-4b27-991b-178898e92156.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('61c2fe02-f8f7-45e7-ad6f-1b32a6243ebb', '星界の戦旗 III', '', 'hulu', 'banner-of-the-stars-3', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/853e5ed7-f5ea-4ecd-b467-4d52e96dd27c.jpg?w=331&h=447&p=t', 'hulu', 2005, 2, 1, 'FINISHED', NULL, 398, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('7a169e8d-fbb7-443a-a45b-d9bc0f7094ef', '61c2fe02-f8f7-45e7-ad6f-1b32a6243ebb', 'hulu-banner-of-the-stars-3-s1', 'シーズン3', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bd1924e-8591-4e2f-925d-4a4fc3240cab.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1579c4b9-1744-47cf-bddf-24a20f3a4956', '7a169e8d-fbb7-443a-a45b-d9bc0f7094ef', 1, '100207675', 'めぐりあう星たち', '『狩人作戦』の中、ロブナスIIで反乱に巻き込まれ、捕らわれてしまうジント。そして生還を果たしたジントは一時的に軍を離れ、ラフィールとハイド星系を目指していた。それは帝国領に復帰した故郷の惑星マーティンを統治するためだった。一方、星界軍ではアトスリュアのもと、第一蹂躙艦隊が編成されていた…。', '2024/12/25 00:00:00', 1808, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bd1924e-8591-4e2f-925d-4a4fc3240cab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5efb9353-80b9-4021-9ece-ee6998e11677', '7a169e8d-fbb7-443a-a45b-d9bc0f7094ef', 2, '100207676', '家族の食卓', '【最終話】帝国領に復帰したジントの故郷である惑星マーティンは、帝国からの独立を画策していた。そんな中、ハイド星系では第一蹂躙艦隊による軍事演習が進行しつつあった。かつて突撃艦バースロイルの乗員だったソバーシュが艦長を務める襲撃艦フリーコヴに便乗し、故郷に向かうジント。果たしてジントは故郷を救えるのか…?', '2024/12/25 00:00:00', 2673, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0f90d97-6617-41c4-a092-dafcb5026884.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c10a8709-0355-4303-9f6d-ad1f1d9fe83f', '星降る王国のニナ', '', 'hulu', 'nina-the-starry-bride', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66b645fa-9f93-4c6e-8a90-b23c16f10c18.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 171038, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('920fd88e-5e96-4d2d-8782-2c5dda350d9a', 'c10a8709-0355-4303-9f6d-ad1f1d9fe83f', 'hulu-nina-the-starry-bride-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7af7e2e0-8409-47f2-b812-f8c40ea13ab2.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23993c31-2bbe-4701-b6cc-1a9798fd149b', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 1, '100201714', '罪のはじまり', 'フォルトナ国城下で孤児として生きる瑠璃色の瞳を持った少女ニナは、仲間と貧しくも幸せな生活を送っていた。しかし仲間の死をきっかけに灰金色の瞳の男に売られる。その男の正体は、フォルトナ国第二王子アズールで、亡き星の姫巫女に成り代われと命じられる。', '2024/10/10 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7af7e2e0-8409-47f2-b812-f8c40ea13ab2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55157035-ccdc-45cd-9296-713d5e8c54bf', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 2, '100202600', '失われた名前', '亡き星の姫巫女アリシャに成り代わり、大国ガルガダに嫁ぐため、アズールから教育を施されるニナ。耐えきれずに部屋を抜け出したところを第一王子ムフルムに見つかる。優秀な兄アズールと比べられ、意固地になるムフルムのために、一緒に弱みを探ろうとたくらむが!?', '2024/10/17 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e0992ef-6657-401d-afb1-5e5c481e571e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8f1d0e6-75ee-4de1-8136-e7c64558d9c2', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 3, '100203232', '夢咲く夜', 'アズールに必要とされるのがうれしくてがんばるニナ。二人きりのときはアズールが「ニナ」と呼んでくれるようになって、ほのかな幸せを感じる。アズールのことを特別だと思うようになった矢先、アズールの命を狙う者の存在を偶然知ることになり……!?', '2024/10/24 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/feef0595-1790-4b89-9f9e-eeacd5cb8e95.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6e470fe-3ade-446f-a244-84c691413c1f', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 4, '100204091', '出立の日', 'お互いに特別な存在となったアズールとニナ。アズールはニナの嫁入りを白紙にする交渉をはじめると言うが、彼の命を狙う者の正体は未だわからず、ニナは素直に喜ぶことができない。意を決したニナは王妃と王それぞれと対峙し、アズールの命を守ろうとするが……!?', '2024/10/31 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2a96228-77f8-4a8e-ba80-0be2b2dfd219.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e878ac1-710b-4649-9fec-bbbffd4ff56f', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 5, '100204635', '深紅の瞳', 'ガルガダの第一王子セトの住むバステア城に到着したニナ。しかし、待てど暮らせどセトには謁見できず、侍女たちも冷ややか。ようやく会えたと思ったら、悪びれもせず歓迎の儀に誘ってくる。歓迎の儀には花嫁候補が集められるが、姫たちの様子がおかしく……?', '2024/11/07 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9685f77-d8d6-4261-baac-43dae9043f9a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b5b407e-21a9-4f35-97fa-e38512d5f1e7', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 6, '100205256', 'はじめての姫', 'セトに斬りつけられたものの、すっかり元気になったニナ。早速、セトのもとへ向かうが、今は留守中だという。セトが不在の中、幅を利かせた近衛隊長が侍女たちを苦しめていた。その振る舞いが許せないニナは、ヒカミやアンの力を借りて、ある作戦を実行する。', '2024/11/14 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8c7335b-09ea-4318-9852-9cccc825f496.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c50c59e-5f98-4de0-bcfb-e34713ac3f4a', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 7, '100206585', '大国の夢', '崖から転落しながらも一命を取り留めたニナだが、森の中で巨大な虎に襲われてしまう。窮地を救ってくれたのは、ニィナを追ってきたセトだった。しかし、セトは虎の攻撃を受けて負傷。ニナは、高熱を発するセトの体とどこまでも冷えた心に寄り添おうとする。', '2024/11/21 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98537817-7e3c-47e8-8d36-77195d0ea54d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcd38ae7-fb9f-46d8-afe4-8eacf3541f95', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 8, '100207383', '血の記憶', 'ガルガダの王位継承順位は白紙とし、アリシャを得た者を次期国王とする――。王の意向を受け、王子たちは積極的にニナと接触しようとする。ニナは勝手に物事が決まっていくことに苛立ちを募らせるが、図らずもセトの“呪い”について知ることになり……。', '2024/11/28 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a369345-59bd-40ed-8eb5-dbe803e83ab8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3d63b4b-e096-4f15-987d-dba865018836', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 9, '100208277', '懸想の窓', 'フォルトナの使者にまぎれてアズールがいることに気づき、接触しようとするニナ。しかしアズールは振り向いてもくれず、ニナは拒絶されたと落ち込んでしまう。それでも諦めきれず強硬手段を取るのだが、アズールとセトが鉢合わせする事態になってしまい……!?', '2024/12/05 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee91e5e3-54a2-4dcd-8bce-02a16cc4604a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f246ba68-b06e-4218-a662-30bddb8c1a3d', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 10, '100209762', '口蜜腹剣', 'アズールの言葉に心を揺らしながらも、ニナは自身の知らぬまま自分を巡って事態が進んでいくことに無力感を抱いていた。気もそぞろではセトの気持ちにも向き合えない。闘技大会当日、意を決したニナはガルガダ王に王子との婚姻の見返りにあるものを要求する。', '2024/12/12 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48d76f3b-3061-4847-bdcb-1bbc1edbb736.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('234e0969-3e07-4f8f-8961-bcdbf4087d41', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 11, '100210353', '逢ひて逢わざる恋', 'ニナの前で剣を交えるアズールとセト。そこへノア王の声が響き渡り、会場は騒然となる。一方、ビドーはニナとアズールの態度を見て何かを察し、翌日、ニナとフォルトナの使者たちをお祭りに誘う。ビドーの気遣いで、ニナはアズールと二人きりになるが……。', '2024/12/19 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56daf4be-5bb6-4274-9dd4-82b77efe92d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('237572fd-1a54-49fe-9706-11b053e33a0f', '920fd88e-5e96-4d2d-8782-2c5dda350d9a', 12, '100211256', '星のゆくえ', '【シーズン1 最終話】裏切りのナイフがセトに振り下ろされる! セトへの真心を利用されたニナは、一連の事件の容疑者として幽閉されてしまう。失われた絆、届かなかった言葉。ニナを救うために動き出すアズール。一方、意識を取り戻したセトは…。それぞれの瞳が見つめるものは――。', '2024/12/26 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6717330-3bd7-46a3-9405-fbc138b383e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9ac5ab32-8d5d-421e-8ed8-e5f0dfc6b19b', '正反対な君と僕', '', 'hulu', 'you-and-i-are-polar-opposites', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a51ba46-f9a0-47f5-88ba-1fd4c0bf7b82.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'RELEASING', NULL, 184951, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b194bcc1-b17f-4a0e-9346-e839c48522ee', '9ac5ab32-8d5d-421e-8ed8-e5f0dfc6b19b', 'hulu-you-and-i-are-polar-opposites-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c354332-772c-466d-a08f-ec706ccd1d58.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21239a3b-4b71-43a2-8d1a-0ce6da59458f', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 1, '100248127', '正反対な君', 'いつも元気いっぱいだが周りの目を気にしてしまう鈴木は、隣の席の物静かながら意見をハッキリ言う谷に密かに憧れていた。ある放課後、二人で下校することになり……。', '2026/01/14 17:30:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c354332-772c-466d-a08f-ec706ccd1d58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe6ed8d9-e920-47d8-9e22-370e988c24cf', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 2, '100248128', '初デート!', '告白が実り、付き合うことになった鈴木と谷。念願の初デートで、鈴木は谷によく思われたくて空回りしてしまうが……。', '2026/01/21 17:30:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd3dc208-0078-4410-a6c9-3a81bc4e827e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f794faa6-955d-4ebd-a9ea-f9d35f6f19c0', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 3, '100248129', 'カワイイとカッコイイ', '鈴木と谷の交際は徐々にクラスに知れ渡る。鈴木に「カワイイ」と言われた谷は、その意味を考えて1人モヤモヤ……。', '2026/01/28 17:30:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f77a3852-58a0-4a47-ac5d-5bf138af591e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2abf7eed-19e1-408a-874e-6b90f32a5a81', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 4, '100248130', '夏の夜のバイブス', '期末試験のため、勉強会を開く鈴木。谷が周りの友達と親しくなっていくことに嬉しさを感じる。そしていよいよ夏祭り当日……。', '2026/02/04 17:30:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72f8e226-7d72-4e44-b089-efa6a9b967ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da1b92f0-e954-419c-8100-fae544795c3f', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 5, '100248131', '考える人、考えない人', '山田は、人見知りで控えめな西の笑顔に触れ、次第に彼女に興味を持つ。思い切って「友達になって」と声をかけ、段々と距離を縮め……。', '2026/02/11 17:30:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/445c329f-31e7-47fa-87e3-ad2ec687607e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1bff89f-76b4-4df5-b6ae-0f7ab2910616', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 6, '100248132', '文化祭!', '夏休みが明け、迎えた文化祭。鈴木は、中学時代に付き合っていた理人に再会し……。', '2026/02/18 17:30:00', 1448, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79c32fd8-06f8-4157-83b3-646dc79ec0f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e86ba201-db24-46a2-9ce5-baa6b3e7529c', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 7, '100248133', 'ドキモヤ', '文化祭を経て、山田と西の間には曖昧な空気が流れていた。それを察して何かを企む鈴木。その様子に谷は翻弄され……。', '2026/02/25 17:30:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c2a6785-aac5-4478-a6b9-c6bb193c000b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65fbdff4-f26c-4c6d-99ff-824048f6a2bf', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 8, '100248134', '今年の秋は…', '文化祭も終わり、季節は秋へ。元カレからの連絡に悩む東に、東の気持ちを代弁する平。二人の関係が少しずつ変わっていく……。', '2026/03/04 17:30:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fdbb2805-3ec7-46a1-8aed-2fe6548bdd47.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('666b3008-b85b-40e1-910d-76314034d146', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 9, '100248135', 'サプライズ!', '谷の誕生日を迎え、鈴木と谷は博物館デートへ。混雑やトラブルに見舞われるが、気持ちを伝え合い距離を縮める二人……。', '2026/03/11 18:00:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80cf0305-003f-4f16-a3f9-ceb1c3384be6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8980c9d1-52fc-4a65-8ba0-ceb6581e5619', 'b194bcc1-b17f-4a0e-9346-e839c48522ee', 10, '100248136', '修学旅行! (前編)', 'いよいよ修学旅行。クラスの女子から谷との関係について質問攻めにあう鈴木。東に、「谷くんともっと進展したい」と本音を打ち明け……。', '2026/03/18 17:30:00', 1433, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc7c1b21-fcd6-4964-802f-bbcbf6623c78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('77a350e5-4fc2-41da-aecf-613ab2dbb724', '生徒会役員共', '', 'hulu', 'seitokai-yakuindomo', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/001b8179-6c28-4ac2-a418-78c49fca1160.jpg?w=331&h=447&p=t', 'hulu', 2010, 2, 1, 'FINISHED', NULL, 8675, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3fbb4649-3e16-4500-bafe-32b6c124a705', '77a350e5-4fc2-41da-aecf-613ab2dbb724', 'hulu-seitokai-yakuindomo-s1', '生徒会役員共', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f5bd8bc-2152-482d-a9c7-43624f51bfeb.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59f2e1b7-00aa-4819-992c-51bc08d53fb4', '3fbb4649-3e16-4500-bafe-32b6c124a705', 1, '100119203', '桜の木の下で／毎回続くのこの感じ?!／とりあえず脱いでみようか', '私立桜才学園1年の津田タカトシは、校門前で服装検査していた生徒会長の天草シノに制服を着崩していたことをとがめられる。その後生徒会書記の七条アリア、会計の萩村スズも加わって、すったもんだしているうちにタカトシは遅刻。するとシノはお詫びと称してタカトシを強引に生徒会副会長に任命するのだった。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f5bd8bc-2152-482d-a9c7-43624f51bfeb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fde7e810-a8c5-414d-9ca6-00e7254cc780', '3fbb4649-3e16-4500-bafe-32b6c124a705', 2, '100119204', '時に君はSかMか／ならば君のその力を試させてもらおう／きらきらと輝くこいつはお主のなんだ?', '圧倒的に女子の多い桜才学園の特異な環境に少し慣れ始めたタカトシは、クラスメイトの三葉ムツミから柔道部を作りたいと相談を受ける。さっそくムツミとともに生徒会へと相談に向かったタカトシだが、シノやアリアの下ネタボケについ振り回されてしまう。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0dfcf74-4967-4ffb-8dad-091abf2b6931.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('344fbc77-ad57-4fd8-a323-e2252122de22', '3fbb4649-3e16-4500-bafe-32b6c124a705', 3, '100119205', '我ながら見事な包み具合だ／会長! もっと裾を広げちゃってください!／もう満腹なのか?!', '修学旅行で楽しみにしていた京都に着いたシノとアリア。ツッコミ役のタカトシがいないため、いつもの下ネタボケが果てしなく続く。一方、取材に余念がない畑は、どこへでもカメラを持ち込みシノやアリアのスクープを狙う。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e64cdc6e-0e90-4992-91f6-2540c2c7e80f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb31d5f8-a20b-4cea-94d6-dc5fcf5c5237', '3fbb4649-3e16-4500-bafe-32b6c124a705', 4, '100119206', 'だから見えないところで着崩してる／おめでたー／だから私はここまででいい', '修学旅行から帰ったシノが、タカトシとスズにおみやげを持ってきた。男性にものを贈るのは初めてというシノがタカトシにあげたおみやげは、非常にいかがわしいモノだった。その一方で、生徒会室からシノのメロンパンが紛失する事件が起きる。頭脳明晰なシノは内部犯行と断定し、ある人物を犯人と見抜く。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/363bef39-d53c-4a19-9068-f81d354a6bf2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e088430a-ac35-4397-ab7e-daa0ce2b4011', '3fbb4649-3e16-4500-bafe-32b6c124a705', 5, '100119207', 'お尻、大変でしょ?／欲求不満なだけだ!／私もパンをくわえて登校しなきゃ!', '風邪をひき、熱を出してしまったタカトシ。タカトシの傘を借り、濡れてしまったことが原因と、シノは責任を感じて放課後、生徒会を代表して津田家へお見舞いに向かう。だがタカトシの妹のコトミは、訪問したシノを出張〇〇の女性と勘違いしてしまう。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23201d43-9a94-476a-90a0-099e62c64fb1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('509b1470-84f5-4845-8e54-08ec9b3675be', '3fbb4649-3e16-4500-bafe-32b6c124a705', 6, '100119208', '津田くんは読まないわ! 使うのよ!／受けがあるなら攻めがあるだろー!／いや、服は着て来い', '夏の定番、怪談話が流行っている桜才学園。そんな時、生徒会に、三階の廊下で不気味な笑い声が響くからなんとかして欲しいと投書が届いた。早速、調査に向かおうとするシノだったが、スズは気乗りしない様子。その理由とは…。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5599d792-eb3e-4ab8-9ea5-7a9ef2744e26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55012cc2-3909-4854-ba5b-bcb25fd00f73', '3fbb4649-3e16-4500-bafe-32b6c124a705', 7, '100119209', 'だんだん大きくなってくわ／津田くんはボーイズラブ', '親睦を深める恒例の日帰り海水浴に出かけた生徒会一同は、赤いビキニに大きなイルカ型の浮き袋と気合の入ったシノを中心に、それぞれの方法で海を満喫していた。ところが、引率でドライバーの横島先生が、誘惑に負けてビールを飲んで眠り込んでしまう。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47568dbb-19b2-403b-8683-17899f2f2a4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8405299d-a6f7-4001-9ae9-8c8b5844d69b', '3fbb4649-3e16-4500-bafe-32b6c124a705', 8, '100119210', 'あ?! お前は朝のイチゴパンツ!／筆おろしが流行るかもしれん／みんなの分まで私が戦う!', '来月に行なわれる体育祭に備え、競技の内容などの打ち合わせに忙しい生徒会一同。今回は共学化初の体育祭となるので、男子のタカトシにさまざまな意見が求められる。タカトシはシノとアリアの下ネタにツッコミを入れつつ、体育祭のために知恵をしぼる。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/732037ee-fce2-41d0-897f-a4d8b571fb75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4cdb393-1664-45da-a3d5-f1c009b557bd', '3fbb4649-3e16-4500-bafe-32b6c124a705', 9, '100119211', 'いくらで買います?／なるほど! 関係ないな俺たち!／ベネズエラ', '生徒会の活動やイベントなどを知らせるため、新聞を作ろうとするシノ。新聞部の協力を得て制作は進められたが、案の定ランコやアリアがボケるせいで作業は脱線しっぱなし。だがここで、タカトシが意外な才能を発揮し、全桜才学園女子を涙の海に沈めてしまう。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a8a4d7f-8be2-46d2-9a32-ccf49ab8e22c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f6949d8-4dbb-4aa4-9f8d-5f8f73776cec', '3fbb4649-3e16-4500-bafe-32b6c124a705', 10, '100119212', 'メイドは見た! お嬢様の淫らな (略)／俺にそんなキャラ設定はない／私でよければ付き合うが', '体育祭が終わったある日、シノたちはアリアの自宅に招かれた。想像以上に広大なお屋敷や、七条家に仕えるメイド･出島サヤカの存在にシノたちは驚かされる。だが出島は最近屋敷に来たばかりで、以前は「開発関係」の仕事に従事していたという…。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8948d1f5-6f04-4827-948e-1637f80d4f28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17f0b384-ba22-42de-849b-310c0d131d3b', '3fbb4649-3e16-4500-bafe-32b6c124a705', 11, '100119213', 'それは津田君の使用済みティッシュ／下着もつけたほうがいい?／サンタさんの性癖', '受験生のコトミは、兄のタカトシが通う桜才学園を狙っていた。人目がないと勉強がはかどらないコトミに付き合っていたタカトシは、桜才学園に面接試験があることを思い出す。そこでタカトシはコトミの練習相手になるが、その答えは妙なものばかりであった。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47d1e08d-7ada-4e88-8988-5c9c882634bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb7a48f2-54fd-4bc5-b527-4766f186310f', '3fbb4649-3e16-4500-bafe-32b6c124a705', 12, '100119214', '一般的な恥じらいです／制服は半脱ぎが相場だよ／君なりの露出プレイじゃなかったのか?', '新年早々、シノたちの初日の出ドライブに連れ出されたタカトシは、続いて初詣にも付き合わされる。人ごみのなか、はぐれないようスズのツインテールを手首に結んでいたタカトシだったが、シノたちの姿を見失ってしまう。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/289764b4-115e-4f79-9c12-006ef86ccb3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a3a2b84-966c-4342-85e3-fc8a16ae9871', '3fbb4649-3e16-4500-bafe-32b6c124a705', 13, '100119215', '生徒会役員共! 乙!', '【最終話】放課後に校内の見回りをしている途中、今更ながらロボット研究会の存在に気づいたシノとタカトシ。そこには、スズの友人である轟ネネが所属していた。ネネは、最近まであまり機械に興味がなかったが、ある物をさらにパワーアップするがため、ロボット研究会に入部していたのだ。', '2022/09/30 00:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1fbef59-2b01-45b5-89f1-d444938a0b9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4118e6a2-e32b-41da-a130-f48563b2d469', '77a350e5-4fc2-41da-aecf-613ab2dbb724', 'hulu-seitokai-yakuindomo-s2', '生徒会役員共 番外編', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c1f23ed-c21e-4e66-988e-c467f1dc8b50.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4981445e-076f-4841-8e50-61007894cf55', '4118e6a2-e32b-41da-a130-f48563b2d469', 1, '100119216', '帰ってきた生徒会役員共', '春、桜才学園の制服に身を包んだコトミは無事に入学式を迎えた。シノは早速コトミに校内を案内する。すっかり桜才学園の雰囲気に慣れたコトミは、生徒会役員の面々に新しく出来た友達の時 (トキ) を紹介するが、彼女はとんでもなくコワモテだった。', '2022/09/30 00:00:00', 1531, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c1f23ed-c21e-4e66-988e-c467f1dc8b50.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f69f3056-8e16-422a-954d-03c9c3fb6a22', '4118e6a2-e32b-41da-a130-f48563b2d469', 2, '100119217', 'はんぱない兄貴／大変な仕事も笑顔でこなすスズちゃんはエライなあ (轟談)／児童会役員共', '新入生が増えたことで活気付く学園内。コトミは、タカトシの周囲に女性が多いことに気付き、こっそり兄をつけまわす。一方、夏を前に、生徒会室の掃除を始めるシノ達。当然、何事もなく終わるわけはなかった。', '2022/09/30 00:00:00', 1620, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77b3b01c-9505-4fb5-b24d-372edaa0aad9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f2f64bc-1dbf-4a8d-a423-be335981737a', '4118e6a2-e32b-41da-a130-f48563b2d469', 3, '100119218', '気分は青空 会長はブルー／ハイリスクが気持ちいい／道着の勲章／桜才･英稜 学園交流会!', '各部活の抜き打ち検査を始める生徒会。将棋盤や自分達が見られて困る物まで、いろいろなものを没収する。そして最後に立ち寄ったロボット研究会にはとある物が置いてあったのだ。', '2022/09/30 00:00:00', 1620, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac9781b2-f44f-4a40-aaaa-5bbebedf8189.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c0519b6-cc94-439c-b148-ca301c8a7a4e', '4118e6a2-e32b-41da-a130-f48563b2d469', 4, '100119219', 'わんこ／津田家の事情／ストレートだと毛が乳首にこすれて気持ちいいですよね', '夏休みも残り1週間。授業はなくても部活動で賑わう学校内で、もちろん生徒会も仕事中。横島が差し入れてくれたケーキに舌鼓を打ちながら談笑をしていると、学校内に思わぬ闖入者が。', '2022/09/30 00:00:00', 1609, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68a7efe0-4108-4952-86e3-cedd4f31887b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61126f65-2a14-41e0-a639-5a6bd0d259f6', '4118e6a2-e32b-41da-a130-f48563b2d469', 5, '100119220', '花より大切なもの／桜才七不思議／柄', '花見にやってきた生徒会役員共は、出島の用意してくれた数々の料理に花より団子状態。そんな中、風船を飛ばしてしまって泣いている少女を見かけたスズは、とある行動にでる。', '2022/09/30 00:00:00', 1584, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f66d8e7d-1f71-4b8e-a5e9-e9fcbca1d321.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9290ebdc-dea2-4a5f-97ed-48f0f1e3ac0d', '4118e6a2-e32b-41da-a130-f48563b2d469', 6, '100119221', 'お約束じゃ済まさないぜ／夜の学園／兄バカ文化祭', '二学期が始まった桜才学園。まだまだ残暑も残っているが、衣替えも無事完了のご様子で、生徒会役員共のハイテンションな日常が戻ってくる。ミニエピソード「スルメとタカトシ」も収録。', '2022/09/30 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a31c172-d24b-4d02-9ae8-3cdd207f5a50.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b23dbf3-fbc1-49b1-bb79-e8d2bd41afeb', '4118e6a2-e32b-41da-a130-f48563b2d469', 7, '100119222', '萩村スズの1日／乗り物談義／やきもきチョコ', 'タカトシが風邪をひいたことにより、生徒会のツッコミ役を任されてしまうスズ。タカトシ不在の中、いつもと変わらぬ生徒会役員共の下ネタボケにスズは振り回されてしまう。彼女は無事にツッコミ役を勤め上げることができるだろうか。', '2022/09/30 00:00:00', 1545, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a17c90e6-1837-4925-95b2-1783dee7f798.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dff7d6e9-e2ee-438b-af30-2f46067a8d83', '4118e6a2-e32b-41da-a130-f48563b2d469', 8, '100119223', 'メイド教室とまさかの気持ち／女子高生家庭教師 天草シノ／未来の穴', '【生徒会役員共 番外編 最終話】アリアに突然お見合いの話が持ち上がる。何とか断ろうと、アリアはタカトシに協力を頼む。演技とはいえ、仲のいい雰囲気のアリアとタカトシを見ていたシノとスズは……。4話に渡ったミニエピソード「スルメとタカトシ」も最終回!', '2022/09/30 00:00:00', 1674, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f646d36d-4ff5-4218-a82b-e2c7a93ceda0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('be5c64e5-4c9e-4666-9837-867f2ea957fc', '77a350e5-4fc2-41da-aecf-613ab2dbb724', 'hulu-seitokai-yakuindomo-s3', '生徒会役員共＊', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2817f70-28c6-43c8-96e4-7fb16129fe3f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('786ac301-2931-4620-bd75-89d04e9f370d', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 1, '100119224', 'また桜の樹の下で／ねむねむの季節ポロッ／ねこをかぶったオオカミ', '私立桜才学園2年になった津田タカトシ。1年前と同じく桜の木の下で、生徒会長天草シノに制服を着崩していたことを再び咎められた。その後、生徒会書記の七条アリア、会計の萩村スズ、さらに桜才学園生徒が次々に登校してくるが、タカトシの妹、津田コトミが遅刻してきてしまう。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2817f70-28c6-43c8-96e4-7fb16129fe3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1563882c-5266-4fe9-bd7e-2dd030672a2b', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 2, '100119225', '萩村スズを見守っていました／桜才･英稜学園交流会おかわり!／症状チェック常備はポケティッシュ', 'いつもと変わらない生徒会室。お昼を食べていた最中、スズが食欲不振で体調を訴えた。熱があったスズは、生徒会メンバーの誘いもあり保健室へ移動することになった。シノやアリアが看病をするが、いつもの調子でかえってスズを疲れさせることに…。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93d96204-7f6d-4f76-b94c-d1e96566d95d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5c17cc63-341a-40d8-92e3-7e9da09d8158', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 3, '100119226', '三日副会長／ちんだら かぬしゃまよ', '沖縄で修学旅行へやって来た桜才学園2年生。その間、津田タカトシの妹コトミは副会長の代理を務めることとなった。しかし何故か沖縄では新聞部畑ランコも非公式で同行しており、なにやら道下先生と大門先生をマークして欲しいとのことであった。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc798ef8-112f-4a4f-8b2d-8a17beaa5f20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71532ffc-7dd0-45f4-bb8f-c5fc66514d9e', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 4, '100119227', '強調部位ブイブイブイ／萌えテイル／画期的ズルむけ', 'タカトシが生徒会室の扉を開けると、そこにいたのは英稜高校生徒会長の魚見であった。車に水をかけられてしまった魚見は、水に濡れた制服を乾かしている間、生徒会の仕事を見学することになった。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67af93b7-129d-43d5-98ce-7ec35737eb24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('007259a4-1647-434f-8019-e332b8d4fdac', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 5, '100119228', '支えスタイル／ぬぎあと もっこり／戦う少女達', 'ある夜、シノとコトミが電話をしていると、シノが赤ちゃんの頃の写真を見たいと言い出した。コトミはある写真を送ると、シノは驚愕する。翌朝、いつもより暑い日であった生徒会室では、熱中症対策の話でシノ･アリアがいつもの如く発言をする。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1f643e7-dd7d-483f-b6eb-4fc14fbc9dc4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78773ff7-acda-4305-bf75-e332806df26c', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 6, '100119229', 'アイドル生徒会長／攻撃アイテム ビクッビクン', 'ある日、街を歩いていたシノは、ある芸能事務所にスカウトを受ける。その事務所とは、最近人気急上昇中のアイドルユニット「トリプルブッキング」が所属していた。学生とアイドルの二足のわらじで活動するか悩むシノであったが…。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e4c8b90-69b0-4ffc-9c0f-77bf950a1233.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('509fc28e-69c8-44f4-b70d-c54b44d9e6b9', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 7, '100119230', '上手いこと いってやったぜ／君を照らす大きい存在／見たまんま たれ流し', '早朝、飼い犬のボアと散歩をしていたスズは、出島さんを始めとした知り合い何人かに会うも、うんざりしてしまう。一方、シノは今までクラブ活動をしたことが無いといい、体験入部をしたいと言い出した。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1163209d-0a1d-4358-8d1f-c749c30c6e86.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bec00752-5a79-4f71-a87a-2e235170b047', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 8, '100119231', '波との戯れ びちょびちょだぜ／万能ウィング／夏の夜 夏の朝', '臨海学校の下見にやってきた生徒会メンバーとコトミ+横島先生。それぞれ海水浴を楽しみ、日が雲に隠れてきたところで本日の宿に向かうことになった。そして、夜も更けてきたところで恒例の肝試しをすることになり…。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/194d9216-ff4c-49b5-b842-b521734c1bde.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f62f3b40-7c7f-4d4a-8369-288541eb2136', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 9, '100119232', '畑ランコ カマす／OGはチョベリグ／ぐーぜん誤解 いただき中', 'いつもと変わらない日常の生徒会室、しかし、屋上には畑ランコが何やら悩んでいるらしく、生徒会役員共はそれを目撃してしまう。実は、新聞部員達が休んでしまっており、畑一人では休刊してしまうらしい。そこで、生徒会として力を貸すことに。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e44cee9b-a79c-4418-a0af-509ed8cd6dd2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a797fc3-48b8-497f-9672-98426c3350f3', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 10, '100119233', '津田キノコは想定内／羽根が飛ぶ／カボチャの気持ち', '安く食料を手に入れ家計の負担を減らすのがデキる女ということで、急遽七条家所有の山で山の幸を取ることになった生徒会役員共。山の幸アドバイザーの資格を持つ出島さんも現れ、一安心かと思いきや…。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ddf333d9-27ab-4039-97ae-a95177dc89fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec248417-a8d5-433d-9c69-fa1815103862', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 11, '100119234', '裏用語に純反応／一部の国ではそうらしいです／雪と戯れ サンタの末裔', '共学化されてから新しい校則が追加されているが、あまり知られていないということで、今回の生徒会だよりの記事にすることになった。それは男女間の立場を明確にするというもので、風紀委員の五十嵐カエデは、最近ふしだらな空気が蔓延していることを危惧していた。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff8de251-b0d8-4ca2-b851-e8bc55f5358f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e0f9f07-aa6f-4feb-9373-29e963fbc544', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 12, '100119235', 'あけおめだよ／人の上に立つ器／どう〇い／それを洗うなんて とんでもない', 'お正月休み、初売りセールにやってきた生徒会役員共。そこで店内で五十嵐カエデと遭遇。そして魚見と鉢合わせ、最後はカメラを持った畑ランコに出会うのであった。', '2022/09/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52c33a57-4c16-494f-b98f-01fd1a0e5b19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80304d90-7c64-4a0d-abf9-1a53b4244f68', 'be5c64e5-4c9e-4666-9837-867f2ea957fc', 13, '100119236', '正しい恋バナ／遠距離アタック／毛のラインナリ／桜の空', '【生徒会役員共＊ 最終話】前回に引き続き両親が出張で不在の津田家。帰宅したタカトシであったが、そこには何故か家にいた魚見が出迎えていた。理由を聞くと、夕飯を作りにきたのだという。さらにそこにシノも加わることに…。', '2022/09/30 00:00:00', 1405, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8beb15e1-9a87-489f-8811-0b8a95efb510.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('bef4cb90-293b-4803-9e43-246adb934f42', '77a350e5-4fc2-41da-aecf-613ab2dbb724', 'hulu-seitokai-yakuindomo-s4', '生徒会役員共＊ 番外編', 4, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2365939-083c-4e37-bcba-e1f6894a3b83.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0a2e0fe-531c-4545-982d-9e2f20a27815', 'bef4cb90-293b-4803-9e43-246adb934f42', 1, '100119237', '1対1／パチパチパンパン', 'お正月休み、タカトシ家にやってきたシノ、アリア、スズ。おせちを持ち寄って楽しげな (?) 雰囲気の中、ゲームや書き初めをして楽しむ生徒会役員共であった。そして、生徒会の今年の目標を決めることになったが…。', '2022/09/30 00:00:00', 1499, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2365939-083c-4e37-bcba-e1f6894a3b83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f76860c1-0684-4396-b976-0455a65c000b', 'bef4cb90-293b-4803-9e43-246adb934f42', 2, '100119238', 'さよならコイン／強者の集い／おはようございます体の記憶', '体育の授業で怪我をしたシノは、午後の全校集会のスピーチをタカトシに依頼することにした。急遽依頼されたタカトシは、人前に立つことに慣れてきたばかりであったが、カタコトながらも練習することに…。', '2022/09/30 00:00:00', 1485, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b361f44-c2a6-46f9-86cc-f32059e1cff5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec3405ca-2d72-4e01-a593-06cfed98425c', 'bef4cb90-293b-4803-9e43-246adb934f42', 3, '100119239', 'KOUMON／光速のちちくらべ／悪天登校', '桜才学園の登校風景。そこにはいつもと変わらず生徒に挨拶をする生徒会役員共がいた。登校時間も終わりに近づき、校門を閉めようとするタカトシだったが、締まりが悪いことが気になり…。', '2022/09/30 00:00:00', 1477, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1efc2172-7368-4ad1-9901-659287dd98c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24599ff3-a092-416f-b4f0-411402814b76', 'bef4cb90-293b-4803-9e43-246adb934f42', 4, '100119240', '人型決戦ロボット／未開の穴 背後の感触／やさしい朝', 'ロボット研究会から悲鳴が聞こえ駆けつけた生徒会役員共。ネネはロボット大会に参加する為、試作品を作製していた…。', '2022/09/30 00:00:00', 1505, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eac75295-9e86-4b57-a2a7-5bb69dc2cec8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca1f53c6-9457-4e1e-bc5f-d57073bc19ca', 'bef4cb90-293b-4803-9e43-246adb934f42', 5, '100119241', '都市伝説の結論／フラグ建設地', 'ランコが借りているアパートの向かいにある河川敷には、夜になるとUMAが現れるという話を聞いた生徒会役員共。現場を突き止めようと、交代で見張りを始めるが…。', '2022/09/30 00:00:00', 1528, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dabf9d06-1eb5-48ac-a4a9-a79f9d1bca2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26589714-b381-4a1a-9555-fd6de2a56215', 'bef4cb90-293b-4803-9e43-246adb934f42', 6, '100119242', '3日間無人島生活／残暑見舞う', '夏休みに七条家が所有している無人島に遊びにきた生徒会メンバーとコトミ。出島さんも参加し大自然を満喫し楽しんでいたメンバーだったが、夜寝静まった頃、スズが一人で立ちあがり…。', '2022/09/30 00:00:00', 1457, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe434851-6c32-49d0-a08b-e5c8b0c389db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('444eef50-4c27-49b1-85ad-58196cb3d6bf', 'bef4cb90-293b-4803-9e43-246adb934f42', 7, '100119243', '生徒会の寄り道／カラーリングは驚きの白さ／副会長はカナヅチ', '【生徒会役員共＊ 番外編 最終話】生徒会メンバーは下校の後、魚見が働いている飲食店に行くことに。その後も水着を試着しに行ったり、最後は4人でカラオケで盛り上がり…。', '2022/09/30 00:00:00', 1477, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f680a496-20a3-4191-b3b0-68b49ce835a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('bf0c00b1-e62b-42c7-9a78-623d36a8ca81', '精霊幻想記', '', 'hulu', 'spirit-chronicles', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b3cf3b7-4c45-478a-91cd-b38de65f903d.jpg?w=331&h=447&p=t', 'hulu', 2021, 2, 1, 'FINISHED', NULL, 126546, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d60bf12e-7a90-4ceb-b974-0a16b16e10ea', 'bf0c00b1-e62b-42c7-9a78-623d36a8ca81', 'hulu-spirit-chronicles-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/438ee1e2-dd27-49c3-a1b2-dbe3d4c3847f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ddb849fa-5aae-4385-94b0-f05b61ef3213', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 1, '100086632', '前世の記憶', '二十歳の大学生、天川春人は路線バスの事故で命を落とす。薄れゆく意識の中でただひとつの後悔は、高校の入学式以来姿を消してしまった幼馴染の美春への伝えられぬ想いだった。ところ変わってベルトラム王国のスラム街。薄汚い小屋の隅で悪夢にうなされて目を覚ます孤児の少年リオ。ある男への復讐だけを目標に生きてきたリオの脳内に突然、見知らぬ世界で暮らすもう一人の自分――【天川春人】の記憶がフラッシュバックする。', '2021/07/11 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/438ee1e2-dd27-49c3-a1b2-dbe3d4c3847f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68bcff53-0867-4f19-a5ec-448b71457c9c', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 2, '100086965', '王立学院', '誘拐された王女フローラを救出したリオは、その恩賞としてベルトラム王立学院の初等部に特待生入学することに。だが王侯貴族の子弟が集う学院の生徒達は孤児であるリオを歓迎しない。周囲から蔑んだ視線を向けられるリオを気遣ってくれるのは、十二歳の若さで初等部の担任講師を務める少女、セリアだけだった。文字を読むことができないリオのため、セリア先生とリオ、放課後の研究室で二人きりの個別指導が始まる。', '2021/07/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee2ce082-de40-4f58-89c1-a30d4b2c53b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c281fdd7-ec88-444e-8441-ad0024810fde', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 3, '100087269', '偽りの王国', 'リオの王立学院編入から五年が経ち、卒業試験の野外演習が迫っていた。 卒業後は両親の故郷であるヤグモ地方に向け旅立ちたいと語るリオの言葉を複雑な想いで受け止めるセリア……。 野外演習当日、魔物の襲撃に我を失ったスティアードが王女フローラを崖に突き飛ばしてしまう。 とっさにダイブしたリオは空中でフローラの身体を崖の上に投げ返し、そのまま高さ三十メートルはある崖の下へと落ちていった……!', '2021/07/25 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfb9c32c-5017-4b43-a579-5582161f408a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01aa5d18-4028-4f33-a3ba-27a8ef8151d5', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 4, '100087717', '暗殺者の少女', 'セリアに別れを告げ、ベルトラム王国から旅立ったリオは、隣国ガルアーク王国の交易都市アマンドにたどり着く。城門前の露店には「パスタ」や「マンジュウ」という名の料理があった。それらの開発者であるリーゼロッテは自分と同じく日本人の記憶を持っているのではと考えるリオ。都市を出て森に入ると行き倒れた少女の姿が……。リオが近づいて声をかけた瞬間、少女は目を見開きリオにナイフを突き出してきた!!', '2021/08/01 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e463a50-d633-42bb-be93-f86e94c91e43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e8c6755-79b4-460c-b4cd-04a36b47ee9c', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 5, '100088037', '精霊の森', 'ラティーファと未開地の森に入ったリオは、眠っている間に亜人らしき集団に取り囲まれた。「精霊の民」と名乗る彼女らと話し合いを試みるリオだが、翼獣人のウズマは同じ獣人であるラティーファをリオが拉致したと思い込み問答無用で襲いかかってくる。ウズマの電撃で意識を失ったリオの夢に現れたのは、ピンクブロンドの髪を靡かせた見知らぬ美少女と、【天川春人】の幼馴染の少女、綾瀬美春だった。', '2021/08/08 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/999d97de-ef00-484f-93ce-b76404aec5db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82db1f53-2f41-4fdd-92ea-e39ab71fefa1', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 6, '100088700', '祭りの夜', 'リオが里で暮らすようになって一年が過ぎ、精霊大祭の日が訪れた。大樹の精霊ドリュアスの祝福を受け、リオは精霊の民の盟友として認められる。楽しい宴の夜、リオから里を出るつもりであることを告げられたラティーファは、それを受け入れられずに森へと走り去ってしまう。一方、上空で侵入者を警戒する里の戦士達が不審なオドの反応を察知する。その正体は里を鋭く狙うブラックワイバーンの大群だった。', '2021/08/15 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b1fb158-5f54-40a3-a835-f5a719c9c44b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22cc07e1-1ace-44ee-a98c-c8b58d4f0462', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 7, '100089218', '約束の地', 'リオは精霊の民の里を出て両親の故郷であるヤグモ地方へ。何の情報も掴めないまま、カラスキ王国の小さな村を訪れたリオは、村長のユバと出会う。リオの両親の名前を聞いて驚くユバ――彼女はリオの祖母だった。ユバのすすめで村で暮らすことになるリオ。従姉のルリや村の少女･サヨとの穏やかな生活が始まる。やがて秋になり、年貢の量を決める検税官が近々派遣されるというある日、サヨの兄･シンと隣村の男達の間でケンカが起こる。', '2021/08/22 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f65d690-f75b-4baf-8dec-53348d12638f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f59d6c9-fd60-4e52-926b-eaa251e74bf8', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 8, '100089911', '王家の系譜', '年貢を運ぶ交易隊の護衛としてカラスキ王国王都を訪れたリオ達。役目を終えたリオとサヨが城下町で買い物や食事を楽しんでいると、幼い少女をさらおうとしている浪人に出くわす。難なく迎え撃ち少女を助けるリオ。その少女コモモは検税官ハヤテの妹だった。ハヤテの父･ゴウキはユバからの手紙を読んで驚愕し、妻のカヨコとともにリオの宿を訪ねる。そして、自分達はリオの母･アヤメに仕えていた者だと告げるのだった。', '2021/08/29 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b5fabe9-7e69-4f2e-ad83-d0c1c661d300.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60453f45-fb36-4658-a6f7-55a8ec6c6cfe', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 9, '100090747', 'それぞれの決意', 'あらためて母の復讐を決意したリオは、しばらくしたらシュトラール地方へ戻ることをユバに告げる。従姉のルリ以外の村人達には王族であることを隠したまま、穏やかな日々が過ぎてゆく。春になり、リオが村を出ることを知ったサヨは家に帰るとひとり土間で泣き崩れる。そんなサヨの姿を見て、いてもたってもいられなくなった兄のシンは、村に残ってくれとリオに懇願するが……。', '2021/09/05 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d03dc32-55bf-4be9-b884-dfba02c7a722.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e8514f6-d3a5-4c63-80b3-399d0a082ebc', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 10, '100091310', '精霊の目覚め', 'リオは精霊の民の里に帰ってきた。翌朝目を覚ますと、リオの隣には全裸で眠っている見知らぬ美少女が……!? 部屋を覗いて色めき立つラティーファと里の少女達だが、その美少女は「春人 (リオ)」の契約精霊であるという。名前もわからない彼女にリオはアイシアと名づけた。強力な精霊の気配を感じて現れた大樹の精霊ドリュアスに促され、謎多き契約精霊の戦闘力を知るためにリオはアイシアと戦うことになる。', '2021/09/12 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/971cb283-1474-4ac4-8544-9a0e136ea5e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cbeebb11-7a4e-45a7-929a-0b354b50b7c6', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 11, '100091869', '白銀の花嫁', 'セリアとシャルル=アルボーとの政略結婚を知り愕然とするリオ。結婚式は明日に迫っている。アイシアの力を借りて王城の迎賓館に忍び込み、リオはセリアとの再会を果たす。リオの顔を見て喜びがあふれるセリアだが、本当に望んだ結婚なのかという問いには同意していると答える。終始にこやかな態度を貫くセリア。リオには彼女の本心が見えなかった。翌日、結婚式が執り行われる王都の大神殿に向かって盛大なパレードが始まる。', '2021/09/19 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c53b37d-20d6-410a-b409-a69d24fbbde7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f554402-9800-48b8-bce9-639591dbbe45', 'd60bf12e-7a90-4ceb-b974-0a16b16e10ea', 12, '100092122', '運命の再会', '【シーズン1 最終話】セリアを乗せた馬車が結婚式場の大神殿前に到着したその時、パレードの人垣を縫って素早く接近してくる黒い人影―― 護衛の騎士達を軽々とねじ伏せ、セリアを連れて逃げるその人影はリオだった。 もう一度セリアの意思を確認するリオの真っ直ぐな想いに、セリアもついに本心を伝える……。その時、王都から一筋の光が上空へ打ち上がり、シュトラール地方の各所からも同じように、合わせて六本の光柱が天空を貫いた……!!', '2021/09/26 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f459bef-4499-4435-815e-94782161b372.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ee3559fd-8b9a-4070-8e35-4304ce86d7b4', '精霊幻想記2', '', 'hulu', 'seirei-gensouki-2-spirit-chronicles', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2edf8d75-eaf1-4ad5-8f66-876ffa2cb295.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 141182, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 'ee3559fd-8b9a-4070-8e35-4304ce86d7b4', 'hulu-seirei-gensouki-2-spirit-chronicles-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/480d8dbd-d1bc-4f2b-bac3-e2f49393113e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9fbf7a95-97b3-4074-8af0-69f7ac25fa00', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 1, '100202063', 'こんな世界で出会えた君は', '結婚式からセリアを救出した直後、6本の光の柱を目撃するリオ。アイシアの指示で向かった先には千堂亜紀、雅人、そしてリオの前世、天川春人の初恋の相手である綾瀬美春の姿があった。奴隷商人から三人を救出したリオは、岩の家を出現させ、合流したセリアたちと共に避難する。その夜、食事を終えた一行に、リオはシュトラール地方に伝わる「六賢神の伝説」について語り出す。様々な運命が交錯し、リオの新たな物語が幕を開ける!', '2024/10/11 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/480d8dbd-d1bc-4f2b-bac3-e2f49393113e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3db6d3a-8ec0-436a-a32b-2b567a94d20b', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 2, '100202601', '異世界ショッピング', 'セリアと美春たちの日用品を買うため、交易都市のアマンドにやってきたリオたち。初めての異世界に戸惑いながらも、美春はセリアと共に試着をするなど、存分に買い物を楽しむのだった。一方ベルトラム王国のフローラ王女の元には、勇者として坂田弘明が召喚されていた。突然の出来事に初めは驚く坂田だったが、持ち前の知識で瞬く間に状況を理解していく。少しずつ運命の歯車が動き出す中、悪しき者たちは静かに暗躍を始めていた。', '2024/10/18 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7fe7d30f-c4bd-4edc-a94f-7e9a9466d76e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9773d716-7580-4b27-b588-7ac48f4ab722', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 3, '100203233', '狙われた我が家', 'セリアと美春たちを預かってもらうため、精霊の民の里へ戻ったリオは、長老に美春たちのことを相談する中で、自分に前世の記憶があることを告白する。そんな彼にそっと寄り添うラティーファ。翌日、受け入れを承諾されたリオは、すぐに美春たちの元へ向かう。一方リーゼロッテは、坂田の元へ勇者をお披露目する夜会の招待状を届けに来ていた。時を同じくして、リオの帰りを待つ美春たちの元に謎の魔物･レヴァナントが迫っていた!', '2024/10/25 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afedefde-7715-4fd8-9d0f-a67d32533042.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06e6a18f-2a82-4904-9622-56828e5573a9', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 4, '100204092', 'おかえりなさい', '精霊の民の里にやって来たセリアと美春たちの歓迎会が催される。リオにとって大切な存在である彼女たちに対し、ラティーファは自分にも日本人だった前世の記憶があることを打ち明け、美春たちのシュトラール語の先生になると宣言する。それから数日後、リオはセリアの手紙を両親へ手紙を届けるため、故郷のロダニアへ行くことを提案する。里に美春たちを残し、リオはセリアとアイシアとともにセリアの生家へと旅立つ!', '2024/11/01 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a1eef60-3de4-449d-915c-db0571b79d89.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2071451-a464-4dd0-af4d-3778c3a5e875', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 5, '100204636', '勇者と英雄', 'ワイバーンに遭遇したリーゼロッテ一行は、近くの都市ノワへ降り立つ。そこにはユグノー公爵の飛行船も避難していた。陸路を使うというリーゼロッテに、坂田は自分たちもついて行くと告げ、馬車でアマンドへ同行することになる。その道中、突如無数の魔物に襲われる一行。アリアを筆頭に侍女たちの活躍で何とか耐え凌ぐ戦闘の最中、さらに強力な伝説の魔物ミノタウロスが現れ、フローラとリーゼロッテに襲い掛かる――', '2024/11/08 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f702229a-4360-4ed5-966f-bd59d7eff340.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2738157c-4650-4146-86ee-2a180ec39750', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 6, '100205257', '記憶の楔', 'リーゼロッテたちの窮地を救ったリオは、一行の中にベルトラム王国の学院で旧友だったフローラとロアナがいることを知り、ハルトと名乗って正体を偽る。だがフローラは、名前も髪の色も違うハルトにリオの面影を感じていた。なりゆきで一緒の馬車に同乗してアマンドに向かうことになったリオ。一方精霊の里では、亜紀が子供の頃を思い出し、一人立ちすくんでいた。それはかつての兄、天川春人との悲しい別れの記憶だった。', '2024/11/15 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/263b86fb-73de-40a3-bd16-f829bdc88c24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7950a55d-5898-48af-a5bd-233727b351db', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 7, '100206586', '乱入者たち', 'アマンドに到着したリオは、セリアたちと合流し、リーゼロッテの手配した宿でしばらくアマンドに滞在することを告げる。その夜、レストランで食事をしていたリオたちの個室に、学院時代に同級生だったアルフォンスがスティアードと女性たちを連れてやって来る。貴族の身分を笠に着てリオたちを部屋から追い出そうとする二人に、リオは素直に従い退室しようとするが、突如アルフォンスがその出口を塞ぎ、立ちはだかって――', '2024/11/22 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d292afca-8fb8-4065-9eb2-1aa03609b1b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1a7e0f6-2d16-4b2c-9e4b-032b408f6c16', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 8, '100207384', '忍び寄る魔の手', '森を調査していたアルフォンスたち騎士一行は、突如現れたルシウスに瞬く間に制圧されてしまう。やがて意識を取り戻したアルフォンスは、レイスによっておぞましい魔物･レヴァナントに変えられた騎士たちを目撃する。そしてその魔の手は、ついにアルフォンスにも……。一方その頃フローラは、ハルトと名乗る彼を思い、学院時代のリオと重ねていた。リオへの感謝、贖罪、自分でも形容できない感情が渦巻き、眠れずにいたのだった。', '2024/11/29 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90f9c969-6caa-497b-b7f8-95f0b13e7ce8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2e10151-fdbf-403f-978c-33f36cbc5536', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 9, '100208278', 'アマンド防衛戦', '突如、無数の魔物の襲撃を受けるアマンド。予期せぬ魔物たちの出現に、たちまち恐怖と混乱に陥るアマンドの人々。リーゼロッテは侍女たちを各所に配置して、被害を食い止めようと奔走していた。リオも東門の守備に加勢し、その圧倒的な力で次々と魔物たちを倒していく。一方レヴァナントへと変貌したアルフォンスの案内でリーゼロッテの屋敷に潜入したルシウスたちが、フローラや坂田たちの待機する部屋に迫っていた。', '2024/12/06 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6402fd93-5730-4a0c-8ad4-c39f00176c34.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef2819c9-0a19-4915-80c0-d6e752768e8b', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 10, '100209763', '因縁の宿敵', '坂田やフローラたちがいる部屋を強襲するレヴァナントたち。アルフォンスの一撃に一度は倒れた坂田だったが、再び目覚めると神装“ヤマタノオロチ”の力を解放する。間一髪逃れたアルフォンスを追おうとした時、レイスによって坂田は意識を失ってしまう。一方一人廊下に逃れたフローラは、ルシウスに捕らえられ屋敷の外へ連れ去られるところだった。それに気づいたリオは、レヴァナントをアイシアたちに任せ、単身ルシウスを追う。', '2024/12/13 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec6e1ac9-72ba-453f-8fc1-82c48b98b825.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d198f0db-9c10-4ee4-a040-33afb8b9d576', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 11, '100210354', '激突', '精霊の里にいる美春は、不穏なリオの夢を見て目を覚ます。ちょうどその頃、リオはフローラを誘拐したルシウスに追いつき、復讐の相手と対峙していた。あくまで冷静にルシウスを仕留めようとするリオ。一方のルシウスはその態度が気に入らず、リオの正体を探ろうと挑発を繰り返す。フローラの一時的な解放を条件に、ついに正体を明かすリオ。この邂逅を喜ぶルシウスだったが、次の瞬間、リオの凄まじい速さの斬撃が炸裂する!', '2024/12/20 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c51c5d6-79d2-42e3-aaf5-48a3f3441276.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2295fbc-8b02-4324-9cd5-cdccbc2de1e5', '421e4325-e39d-42ba-8d43-0ffa22f0fd3d', 12, '100211257', '運命の明日へ', '【シーズン2 最終話】戦いを終えたリオに、長年ため込んでいた感謝と謝罪を伝えるフローラ。だがリオはその言葉を受け取らず、リオという名前を忘れるようにと告げる。その後、屋敷に帰還したリオは、ユグノー公爵たちとの話し合いの席で、フローラを救出したお礼をしたいというリーゼロッテに対し、ある願いを申し出る。その後、精霊の民の里に戻ったリオは、美春たちを勇者となった沙月と再会させるべく、新たな旅に出る――!', '2024/12/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71b1ae61-aa7e-45d9-9b1a-6a8f420c5936.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b41db7a6-00fb-48f6-a30c-e8f4b3183032', '聖剣学院の魔剣使い', '', 'hulu', 'the-demon-sword-master-of-excalibur-academy', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41d4a5c3-a0ba-4584-9b30-ab853e23827a.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 140501, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('80da2edf-3ca3-4a64-a76a-146799ae59b6', 'b41db7a6-00fb-48f6-a30c-e8f4b3183032', 'hulu-the-demon-sword-master-of-excalibur-academy-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3759490d-e805-47da-b64d-6b377e136996.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea9e89e4-c03d-48e6-ad87-5076b3e97cb1', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 1, '100162538', '魔王復活', '神話の時代――不死者の魔王レオニス･デス･マグナスは、人類の英雄との戦いで敗勢に追い込まれ、捲土重来を期し長き眠りに就く。そして1000年後。想定外の状態で覚醒を果たしたレオニスは、遺跡調査に来たリーセリアと名乗る少女に保護されたのだが、そこにヴォイドと呼ばれる人類の敵が襲来。リーセリアの仲間レギーナは、「聖剣」というレオニスの知らない能力で抗戦する。眠りに就く前とはなにもかも変わってしまった世界の中、レオニスはひとつの決断を迫られる。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3759490d-e805-47da-b64d-6b377e136996.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20a2bdcf-7c49-42d2-be71-204839b30e88', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 2, '100162539', '背負わされし運命', 'ヴォイドを退けたレオニスがリーセリアらに連れられた先は、第〇七戦術都市。それは海に浮かぶ巨大な要塞。想像を絶する発展を遂げた人類のテクノロジーに驚愕しつつ、レオニスは魔王軍復興のため、正体を隠して戦術都市で暮らすことに。ともに眠っていた盟友ブラッカス、配下のメイドシャーリを目覚めさせ、都市の調査を開始した。聖剣学院に編入されることになったレオニスは、そこでリーセリアが抱えていた苦難を知り、さらには自らが彼女に与えた宿命を明かす――。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d2528aa-bf9e-40a4-b193-492b098504aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51a1b9a2-8850-4bca-b621-022e02f76c80', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 3, '100162540', '覚醒する魂', 'レオニスは死んだリーセリアを救うべく、彼女に吸血鬼化の魔術を施していた。この事実を告げられたリーセリアは、壮絶な過去と自らに課した使命をレオニスに語る。リーセリア率いる第十八小隊のメンバーである咲耶とエルフィーネにも、ヴォイドによって刻みつけられた因縁があることをレオニスは知る。レオニスの聖剣審問にはミュゼル･ローデスが乱入し、リーセリアもレオニスを守るべく参戦。予期せず生じた戦いの行方は――?', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f21ce1ac-3269-4da7-a622-f67152c01641.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49e8cc85-0516-476e-aa11-007496cdbea2', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 4, '100163377', '深き遺恨の胎動', 'ついに聖剣覚醒を果たしたリーセリアは、自分を鍛えてほしいとレオニスに願い出る。眷属の強化はレオニスにとっても吝かでは無く、ふたりは訓練に勤しむことに。一方、管理局では戦略会議が招集されていた。不可解な調査報告に困惑する一同は、警戒を強めつつさらなる情報収集を行うという方針を採用する。リーセリアは「鍛えてくれたお礼に、ごはんをごちそうする」と、レオニスをとあるレストランに連れ出す。そこでレオニスは、リーセリアのもうひとつの顔を見る。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1dc8d6cd-2ed5-43d0-8bf7-d1ae0d0ba838.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c445f75-188e-4b1b-818b-7223a2049949', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 5, '100164103', '大狂騒', '管理局での戦略会議は混迷していた。ヴォイドの可能性を示す調査対象の挙動があまりにも異質なため、明確な判断を下せない。しかしそこにエルフィーネが、独自の分析から導いた推論を提示。その推論は核心に迫るもので、程なく状況が急変する。スタンピード発生。凄まじい数のヴォイドが都市を襲う。聖剣学院を離れていたレオニスとリーセリアは、孤児たちを守るために戦う。そしてレオニスは、このスタンピードを引き起こした者の正体を見るのだが――。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6643fa6f-df6e-4ca0-801c-60981c0c97e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71b6c6c0-8346-4278-8561-1c1b3b8807e1', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 6, '100165195', '魔王の覚悟', '第〇七戦術都市に吹き荒れるスタンピード。引き起こしたのは、千年前に魔王レオニスと戦った六英雄のひとり、大賢者アラキールがヴォイドロードと化したものだった。レオニスをおびき出すため、リーセリアを捕らえて待ち受けるアラキール。レオニスは魔王のプライドに懸けて、眷属を取り返すべくアラキールのもとへと向かう。凄まじい力でレオニスを攻撃するアラキールとの激戦。やがてレオニスは、ある重大な決断を下す。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da8c6726-9490-48d9-ac56-1cc63c1f240f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b63f36e-f4b4-470a-9ed3-93179c6a68ee', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 7, '100165964', '王女の秘めた想い', 'スタンピードが過ぎ去り復旧が進む第〇七戦術都市に、王族が訪れる。第四王女アルティリア･レイ･オルティリーゼ。彼女は都市を守り抜いた聖剣士たちを慰労するため、パーティーを催す。レオニスたち第十八小隊一同もパーティーに招かれたのだが、なぜかレギーナだけは不参加を表明。その頃、帝国の体制に不満を抱く亜人の集団は、好機とばかりに王女の誘拐を企んでいた。そこに現れた妖しげな女シャルナークが、亜人たちに謎の力を授けるのだが――', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fe5a5f9-9c68-4155-a1be-545ea63afade.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ada1985-2072-4593-8a33-c2b59cdbb11b', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 8, '100166600', 'その絆は消えず', '反体制派の亜人たちによるテロ行為は、ひとまず成功してしまった。最新鋭艦ハイペリオンはジャックされ、アルティリア王女も拘束されている。咄嗟に乗り込んできたレギーナはレオニスに出自を明かし、ふたりは手分けして王女救出と艦の奪還に動く。ハイペリオンがヴォイドの暗礁へと突入する中、レオニスはシャルナークと対峙。「女神」の名を口にする彼女に尋問を試みるレオニスだが、シャルナークの様子が急変し――', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/016a3c3f-c49e-4e8a-a70f-831e41ca2084.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e3e5633-e8ed-4cbc-8c23-39ba1eb3ac34', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 9, '100166990', '廃都出現', '聖剣学院で、小隊対抗戦形式での演習が行われる。聖剣を得て初めての本格的演習、勝利すれば小隊のランクも上がるとあって、闘志を燃やすリーセリア。対戦相手はフェンリス率いる強敵、第十一小隊。熾烈な真剣勝負はリーセリアとフェンリスの一騎討ちという状況すら招く。演習を終えた第十八小隊に、ある特別な命令が下される。遠方洋上に出現した戦術都市の調査任務――それはリーセリアが家族と暮らし家族を失った、第〇三戦術都市であった。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6ce1e0d-b38b-46fe-bc09-6d2f1ac49d4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5f1e217-1a1f-4fc9-a3ea-67710341005c', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 10, '100167539', 'エルフの勇者', 'リーセリアとレギーナが育った第〇三戦術都市は、いまやヴォイドが跳梁する地に成り果てていた。その地に千年前から来た勇者、アルーレが現れる。レオニスはヴォイドの急襲で負傷したリーセリアとひとたび身を躱し、そこで廃都の亡霊と出会う。レオニスたちと別行動をしているレギーナ、咲耶、エルフィーネはアルーレと遭遇。咲耶とアルーレは刃を交える。亡霊に導かれてレオニスとリーセリアはクリスタリア公邸、すなわちリーセリアの生家へと赴くのだが――。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27ec7e43-f631-4a13-a392-fd0a2da3aea8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03c54358-f8b5-451f-9fd9-5476b1930047', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 11, '100168378', '女神の声', 'リーセリアに突如浴びせられた攻撃は、ログナス三勇士が間一髪で防いでいた。駆けつけたレオニスは、千年前に見たネファケスという男と邂逅する。ネファケスは地響きを契機に姿を消し、残されたレオニスたちの前にヴォイドロードが出現。それはまたしても、千年前の六英雄が姿を変えて蘇ったものだった。事態は急迫し、別行動のレギーナたちはヴォイドとの戦闘を余儀なくされる。そしてヴォイドロードを討たんとするレオニスの脳裏に、過去からの声が響く。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1a953cf-0493-407b-9d0a-56897f3416c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b67dcac-3c15-4687-bfdc-a31b1320f270', '80da2edf-3ca3-4a64-a76a-146799ae59b6', 12, '100169062', '魔剣の真実', '【最終話】レオニスは、記憶の奥底に埋まっていたある約束を思い出した。改めて自らの使命を確信したレオニスは、ふたたびヴォイドロードに挑み討ち滅ぼすことを強く決意する。リーセリアとログナス三勇士、そして廃都の亡霊たちもレオニスに力を貸す。レギーナ、咲耶、エルフィーネもヴォイドロードを倒すべく、アルーレとともに廃都を疾走。それぞれの場所で展開するそれぞれの死闘がやがて重なり、ついに決着の時が来て――。', '2025/01/11 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69abccb1-8afe-4956-bd9e-3caf1314356c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('191c0156-b32c-4c19-a2c7-95433fb839a6', '聖剣使いの禁呪詠唱＜ワールドブレイク＞', '', 'hulu', 'world-break-aria-of-curse-for-a-holy-swordsman', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50019876_series_art__338x600_world_break_aria_of_curse_for_a_holy_swordsman_6d2eb7f9d1415aef4dd7925ebc7925a6.jpg?w=331&h=447&p=t', 'hulu', 2015, 0, 1, 'FINISHED', NULL, 20627, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('451b7124-a23a-4101-88a9-a47cbaaf9404', '191c0156-b32c-4c19-a2c7-95433fb839a6', 'hulu-world-break-aria-of-curse-for-a-holy-swordsman-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/79a5aae1-d31f-420a-9a1d-ccc2f51ddd37.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6a5ffa0-245b-4407-a787-7cd1a97a6d33', '451b7124-a23a-4101-88a9-a47cbaaf9404', 1, '60500153', '転生せし者 －The Reincarnater－', '「二つの前世の記憶を持つ」灰村諸葉は、入学した亜鐘学園で嵐城サツキ、漆原静乃という二人の少女に出逢う。これが現世と前世を繋ぐ物語の始まりだった。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/79a5aae1-d31f-420a-9a1d-ccc2f51ddd37.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e253414f-1162-4c11-85b5-e01c6fe46fd1', '451b7124-a23a-4101-88a9-a47cbaaf9404', 2, '60502395', '我が剣に宿れ魔焔 －The Swordbringer comes back－', 'ストライカーズに入隊した諸葉と静乃。実力不足で思うようにいかず焦れるサツキだったが、休日に赴いたショッピングモールで初めてメタフィジカルと相まみえる。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7809f911-9013-41fd-b542-05bdde17b787.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d65d9e2b-2645-48a3-bcec-fcb763b20003', '451b7124-a23a-4101-88a9-a47cbaaf9404', 3, '60506587', '冥府の魔女 －The Black Sorceress－', '世界にたった6人しかいないランクSのセイヴァー、エドワードが来日。一方、前世の記憶を語ろうとしない静乃と、それが気にかかる諸葉の周囲に不穏な影がさす。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b3219c5d-ddf0-4148-9bdc-5393298d8255.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('468b983b-0281-470b-9619-159639147a85', '451b7124-a23a-4101-88a9-a47cbaaf9404', 4, '60508791', '白騎士強襲 －The Silver knight－', '家柄に縛られ己を抑制し続けてきた静乃。静乃を解き放とうと奮闘する諸葉の前にエドワードが立ちはだかる。今、諸葉のもう一つの前世が覚醒しようとしていた。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a26d81af-ed1b-47cd-b2f7-18e70f2749ea.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea12cc59-0306-4b87-9d42-29960ccd0029', '451b7124-a23a-4101-88a9-a47cbaaf9404', 5, '60514265', 'We Are The･夏 －We are the "Natsu"－', '季節は夏。そして海! 亜鐘学園のストライカーズは島で夏合宿を行うことに。張り切って水着を選ぶサツキと静乃。諸葉も春鹿や斎子たちとの交流を楽しむ。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7df7ba23-27e2-4411-8b18-35f0f1ea8896.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f046a4a8-0d6c-46b5-8b6e-308c474ce693', '451b7124-a23a-4101-88a9-a47cbaaf9404', 6, '60516048', '我ら、救世の剣なり －We are the “Saviors”－', '諸葉たちは対“異端者”の実戦部隊、ストライカーズに入隊した。そんな折、突如新たな“異端者”が出現。味方の援護が来ないため、諸葉たちだけで戦うことになってしまう。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c22aca1b-63cc-42e0-8fc5-e0cdb1f65747.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('356904f3-f431-4ad1-890e-d66d12536512', '451b7124-a23a-4101-88a9-a47cbaaf9404', 7, '60523474', '銀髪の異邦人 －a Foreigner－', 'ある朝、登校した諸葉はロッカーの中に自分宛てのラブレターを発見する。送り主はロシアからの転校生、エレーナ・アルシャヴィナだった。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a6206b12-bb78-431d-912b-5ab837ad68a4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6b21124-1c61-4c14-8b26-d51061d6c91b', '451b7124-a23a-4101-88a9-a47cbaaf9404', 8, '60525774', '魔剣と聖剣 －ambivalenz－', '明かされたレーシャの正体。それはマンイーターと呼ばれる暗殺者だった。やがて刃を交わす諸葉とレーシャ。その時、諸葉の聖剣が覚醒を迎えようとしていた。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/25aae0ff-9d90-40c1-bce6-54cfd949be96.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3b25dbd-8267-4d15-9e7e-2f7be079ae21', '451b7124-a23a-4101-88a9-a47cbaaf9404', 9, '60528726', 'シベリア行 (こう) －Lonely Soldier－', 'レーシャのため、ロシア支部に戦いを挑む決意をした諸葉。エドワードのバックアップのもと、アンジェラを伴ってロシアの地に降り立つ。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ea661e32-f5b2-41ac-95db-9ea86f6d95e2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52c3ce9d-9134-4b64-90be-d8ea65f6603c', '451b7124-a23a-4101-88a9-a47cbaaf9404', 10, '60531077', '決戦･エカテリンブルク －Ouroboros－', '"雷帝"ヴァシリーサを追いロシアを駆ける諸葉は、ついに彼女の在処を突き止める。行く手を阻む刺客と1人戦い続ける諸葉の元に、仲間たちの思いが届く。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a7576b5e-8d3e-497a-bf39-ada50fcd5837.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f26a17e5-2241-43d7-93c9-c5208a96112b', '451b7124-a23a-4101-88a9-a47cbaaf9404', 11, '60534396', '悪夢は前世より －Karma－', 'ロシアでの戦いを終えた諸葉たちは、一時の休息を過ごす。しかし平和な時間は長くは続かなかった。諸葉の不在を狙ったかのように、新たな敵が亜鐘学園に襲来する。', '2016/05/26 12:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b9d1c1b1-1443-48e8-98d8-1ffd2e0cc129.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d9899c1-8715-45a6-8f38-8b1c7ae69104', '451b7124-a23a-4101-88a9-a47cbaaf9404', 12, '60538226', '二つの生を越え －Beyond the Time－', '【シーズン1 最終話】亜鐘学園を蹂躙する巨大なドラゴン。その圧倒的な力に決死の覚悟で対抗するストライカーズ。そしてついに帰還した諸葉。前世と現世を結ぶ宿命の戦いの火蓋は切られた。', '2016/05/26 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0a7e9661-94fc-45f0-9038-205a959ccea0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2d2ca21e-848e-4b39-b2d1-7b2f60e3390e', '聖者無双 ～サラリーマン、異世界で生き残るために歩む道～', '', 'hulu', 'the-great-cleric', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de977ebd-9d87-42c2-be22-eae72473ddcf.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 155418, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('382cbcb2-c3e5-473c-8b20-8806afe2f695', '2d2ca21e-848e-4b39-b2d1-7b2f60e3390e', 'hulu-the-great-cleric-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3aea89e9-bcea-4271-a8ba-f07808d6f020.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9dbded59-9048-44a4-afdf-662cccdc8373', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 1, '100152304', '治癒士ギルド', '出世を目前に凶弾に倒れたサラリーマンは、気が付くと15歳･ジョブ「治癒士」のルシエルとして異世界に転生していた。「絶対に寿命で老衰する!」という決意を胸に、新たな人生をスタートさせたルシエル。前世で培った営業スキルを活かし女性聖騎士隊隊長･ルミナに治癒士ギルドへ案内をしてもらうが、まだ治癒魔法が使えないルシエルは10日間のスパルタ訓練を受けることに…。', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3aea89e9-bcea-4271-a8ba-f07808d6f020.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('992e88ea-6c2a-400b-9b6a-b89309bfbb0b', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 2, '100153201', '冒険者ギルド', '負傷した新米冒険者4人の治療を試みるルシエル。しかし緊張のせいかヒールをうまく発動させることができず、魔力枯渇も起こしてしまう。そこでルシエルは、経験を積んで治癒士としてもレベルアップするため、冒険者ギルドの門を叩くことに。受付嬢のナナエラに迎えられ、魔法による治癒行為を対価に武術の指導をお願いしたルシエルの元へやってきたのは厳つい顔を浮かべるブロドだった。', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21a45d4f-abce-41ab-af78-2d1f7b6a5857.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f731dd7e-8544-4d26-9d03-bc711d1b269b', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 3, '100153622', '武術の才能', '鍛錬のため冒険者ギルドに身を置き、ブロドによる修行と、冒険者への治療を始めたルシエル。さらに修行の一環として、クソまずいというデメリットを持ちながらチート級の効力を持つ「物体X」を、シェフのグルガーから飲まされることに。その後「物体X」と修行の日々を送るルシエルは、ある時から“視線”を感じるようになるのだが…!?', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2cd64178-9949-45c8-998e-8e5c97e9332a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ebed46c-edf7-41c6-abae-dd50e3f46e11', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 4, '100154290', '物体Xと少しの変化', '修行に明け暮れるルシエルは、初めての休息日を迎える。グルガーの兄･ガルバから魔物の解体を、ナナエラたちからはこの世界の歴史などを教えてもらったりと有意義な時間を過ごしていく。そしてその後のある休日、ナナエラと買い物に出ると、帰り道で突如響き渡る叫び声が…!? その声の元へ駆けつけたルシエルが見たものは、血を流した治癒士ギルドの受付嬢･モニカの姿だった…。', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59350f4d-80d5-4d73-b035-30ba7650467c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67b1ebd3-d44d-4a2a-8b43-d2215fd374b4', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 5, '100155078', '治癒院長ボタクーリ登場', '修行に明け暮れるルシエルは、初めての休息日を迎える。グルガーの兄･ガルバから魔物の解体を、ナナエラたちからはこの世界の歴史などを教えてもらったりと有意義な時間を過ごしていく。そしてその後のある休日、ナナエラと買い物に出ると、帰り道で突如響き渡る叫び声が…!? その声の元へ駆けつけたルシエルが見たものは、血を流した治癒士ギルドの受付嬢･モニカの姿だった…。', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41146223-6291-4b6b-8267-40d6fc28addd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('153dc8eb-f8a9-41e8-8e0b-78f2a5fa8f10', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 6, '100155737', '旅立ち', 'ボタクーリの一件から半年が過ぎたころ、ルシエルの元に一通の手紙が届く。その内容は聖シュルール教会本部への異動辞令だった。辞令が自分を冒険者ギルドから追い出すためのボタクーリの仕業であることを知りながらも、ルシエルは半年後の異動へ向けて準備を始める。そして迎えた最終日、ルシエルはある思いを胸に、ブロドを訓練場へ呼び出すのであった。', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77ffe79a-1174-45d9-867a-787e14c38d64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ab0bbb4-1613-408b-88c9-ad09f3b2554b', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 7, '100156905', '聖都シュルール', '聖都シュルールへ到着したルシエルは、司祭･グランハルトから退魔士として教会本部の地下迷宮でアンデッドを祓う仕事を命じられる。そこで偶然再会したルミナから、地下が迷宮化した理由や危険が伴う仕事だと知らされるのだが、多少の不安はあるものの前任の退魔士･ジョルドからアンデッドの倒し方を学んだルシエルは、いざ地下迷宮へと足を踏み入れるのであった――。', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2f97949-dba6-45e9-ace9-a2d140741655.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('063f4180-3b64-4f20-8729-b38a6ee1f578', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 8, '100156906', 'ボス部屋の脅威', '無事に初日の迷宮探索を終えたルシエルは、迷宮内で手に入れた魔石を交換してくれるという教会本部内にある売店へ向かう。店主のカトレアから格安で剣と槍を購入し、『二槍刀流』での迷宮探索を進める。十階層までたどり着いたルシエルの前に現れた怪しげな部屋。そこは主部屋と言われ「アンデッドが集団で襲ってくる場所」だという。ルシエルは早速十階層の主部屋へと挑むが…!?', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a874559-12cf-42a8-9e0a-f065cc7d6b6f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74c6a71a-4cb4-426e-a8c6-47c3121a92b8', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 9, '100157969', '聖騎士隊との訓練', 'なんとか十階層の主部屋をクリアしたルシエルだったが、戦闘においては反省点も多く、更なる修行を思案していた。そこでルミナに相談すると、『戦乙女 (ヴァルキリー) 聖騎士隊』の訓練へ参加させてもらえることに。厳しい訓練の甲斐もあり、無事に二十階層の主部屋を突破したルシエルは、教皇から主部屋で戦ったワイトの正体を明かされる。', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9596da93-99de-4277-bf93-6857aaf97015.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a18d7dda-bc75-4de5-881d-c4d274db839b', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 10, '100158341', '物体Xの秘密', '「物体X」を補充するために聖都シュルールの冒険者ギルドへやってきたルシエルは、マスターから冒険者たちの治癒を依頼される。引き受けたルシエルに冒険者からは感謝の「ドMゾンビ」コールが。治療と引き換えに「ドM」呼びを禁止するも、通り名会議は難航し…。一方、ルシエルの強さに疑問を持ったカトレアは「物体X」の存在を教皇へ報告。教皇から語られる「物体X」の正体とは…?', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a384a2c4-cbd4-43ce-8056-ed869a97b540.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bd2aa84-1e71-49f2-a09c-b4459cb7a76f', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 11, '100159293', '聖都シュルールの異変', 'アンデッドの情報収集のために冒険者ギルドへ向かったルシエルは、遠いメラトニの街からやってきたナナエラとモニカに再会する。二人の近況を聞きたいルシエルだったが、ギルドで治療を心待ちにしていた冒険者たちに駆り出されてなかなか話せない。しかも、獣人の少女･シーラが助けを求めて駆け込んできて、彼女と共にスラム街へ向かうと、そこでは大勢の獣人が苦しんでおり…!?', '2024/10/11 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ec772ed-3387-44fb-a0b3-4565cad83c25.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d24f77e-20dc-4a1c-8923-84477d9f5249', '382cbcb2-c3e5-473c-8b20-8806afe2f695', 12, '100160153', 'S級治癒士兼退魔士ルシエルの宣言', '【最終話】地下迷宮で四十階層の主部屋を攻略したルシエルは、帰ることができぬまま五十階層の主部屋前までたどり着く。覚悟を決め主部屋へ足を踏み入れたルシエルを待っていたのは、ラスボス･キングワイトだった。激闘の末なんとか勝利したルシエルは、五十階層のさらに奥へと足を進める。しかしその先に眠っていたのは、死んだように眠り続けるドラゴンで…!?', '2024/10/11 00:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36dff90b-c102-48ed-b321-a30242245e1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7549e06d-61c4-45f9-95cb-a4dbff88abc5', '聖女の魔力は万能です', '', 'hulu', 'the-saints-magic-power-is-omnipotent', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc006f6c-6d9d-473b-a7da-830e8b8cda87.jpg?w=331&h=447&p=t', 'hulu', 2021, 1, 1, 'FINISHED', NULL, 123802, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', '7549e06d-61c4-45f9-95cb-a4dbff88abc5', 'hulu-the-saints-magic-power-is-omnipotent-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d161128-987e-45cf-88be-108fef7ad10e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ef7c9bd-de1c-476a-89e2-b10f560ab550', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 1, '100079880', '召喚', '小鳥遊聖 (タカナシ･セイ) は、ちょっと仕事中毒な20代の会社員。ある夜、残業を終えて帰宅すると突然光に包まれ、異世界の王宮に「聖女」として召喚されてしまう。ところが、現れた王子は同じく召喚されたもう一人の少女に夢中で、放置されたセイは暇を持て余す。そんな時、王宮敷地内で出会った青年･ジュードに案内されたのは薬用植物研究所。元々植物好きで研究所に興味を持ったセイは、そこで研究員として働くことになるが、薬草と魔法を使ったポーション作りで思いがけない能力を発揮することに……。', '2021/04/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d161128-987e-45cf-88be-108fef7ad10e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cdc259a5-7a04-4fbf-ae07-2beab737578c', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 2, '100080160', '親交', '瀕死の騎士を救ったポーションが評判となり、功労者であるセイは褒美として、研究所内にキッチンを設置してもらう。この世界には薬草を料理に使う習慣がなかったが、薬草を加えたセイの手料理は、所長のヨハンも感心するほどの美味しさだった。後日、セイはヨハンから第三騎士団の団長･アルベルトを紹介される。彼こそが、セイのポーションで救われた騎士本人だった。ブルーグレーの瞳を持つアルベルトに優しく微笑まれ、落ち着かない気持ちになるセイ。さらに、王宮図書館でも新たな出会いが待っていた。', '2021/04/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0ac5d02-c69d-45a3-9c2d-c15a4c4defad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8019bdee-19d5-46bf-afdb-479c360cce7d', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 3, '100080581', '王都', '夏の休日、セイはアルベルトに誘われて街へ出かける。人々の賑わいに瞳を輝かせるセイの手を取り、優しくエスコートするアルベルト。二人は一緒に街を歩き、楽しいひとときを過ごす。別れ際、アルベルトはセイに髪留めを贈る。その話を聞いたヨハンとエリザベスは、アルベルトの行動に込められた彼の思いを察していた。数日後、髪留めに魔法付与が施されていると知ったセイは、自分でもやってみたくなり、教えを受けるため宮廷魔道師団の隊舎を訪ねる。そこで出会ったのは、副師団長のエアハルトだった。', '2021/04/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77ec6993-e3a5-421e-803f-b40e7e7d8f9a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31cd0bd8-5867-40f6-9331-0c927b233686', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 4, '100081086', '奇跡', '王宮の執務室で、ジークフリート国王はヨハンとエアハルトからセイの優れた魔力について報告を受ける。一方、当のセイも自らが人並み外れた魔力を持っていることを自覚していた。考えられる理由は「本物の聖女」だから。しかし、それを積極的に喧伝するつもりはなく、できれば普通の人として過ごしたいと思っていた。ある日、ポーションを大量に作りすぎたセイは、ヨハンから強制的に休みを言い渡される。調べ物でもしようと立ち寄った王宮図書館で、不意に声をかけてきたのはジークフリート国王だった……。', '2021/05/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74a4df94-70ac-4ff7-9c87-6d156bfafb62.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00a45026-32b5-4412-8c13-113e349e0666', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 5, '100081783', '鑑定', '宮廷魔道師団の師団長･ユーリのもとで、「鑑定」を受けることになったセイ。だが、セイはユーリの鑑定魔法を無意識に弾いてしまう。それは彼女の魔力量がユーリよりも多いことを物語っていた。確証はなかったが、魔力の特異性からもセイが聖女であると判断したユーリは、その件をジークフリート国王に報告。王宮の使者はセイに、国王が謁見を望んでいることを伝えた。謁見の日、セイは気合いが入った侍女たちによって美しく仕立てられ、護衛役として迎えに来たアルベルトと共に王座の間へ向かう。', '2021/05/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9297b83b-dedf-4214-b7e9-a27b09d5d659.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3b0a96b-e15a-4c36-88fc-14e7d04c339f', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 6, '100082362', '淑女', 'セイが魔法を正式に学ぶにあたり、講師役はユーリが務めることになった。この機会にセイの不思議な魔力をじっくり観察させてもらおうと、すっかりご機嫌なユーリ。とはいえ、指導は意外とスパルタで、セイは魔法を高速発動する課題に苦しむ。そこで、より実戦的な練習で感覚を掴むため、アルベルトに頼み第三騎士団の訓練に参加させてもらう。それはいずれ、討伐の支援要請が来ると考えてのことだった。セイが受けている講義は他にもあり、ダンスやマナーなどを学ぶその日を、セイは「淑女の日」と呼んでいた。', '2021/05/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/931c1bfa-d1a2-438e-b451-826f4aed7072.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0c0d33d-ebbd-46b5-9913-238f391d5f1d', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 7, '100082887', '章間', 'セイと同時に聖女として召喚された、もう一人の人物――御園愛良 (ミソノ･アイラ)。セイのように放置されることなくカイル王子に保護されたものの、彼女は突然の異世界に戸惑い、元の世界に戻れないと知り涙を流した。カイル王子はそんなアイラの世話をやき、王立学園に編入させる。アイラ自身も自分にできることを頑張ろうと、魔法の勉強に励んだ。しかし、彼女を偏重しすぎるカイル王子の姿勢が影響し、アイラは学園内で孤立してしまう。その状況をなんとかしようと、エリザベスはアイラに声をかけるが……。', '2021/05/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e54a8ca1-5a9c-422b-9830-c07c6f0e811e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('645a11a4-1b31-4616-b848-de9cd51cfc11', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 8, '100083366', '覚醒', '念願だった禁書庫での書物閲覧を許されたセイは、より効果の高いポーションが作れないかと研究に没頭。過去の聖女は魔物を殲滅する「聖女の術」という魔法を使ったらしいが、記録がないため詳しいことはユーリにもわからなかった。ある夜、この世界で出会った人たちのことを思い返していたセイの心に何かが湧き上がってくる。その瞬間、辺りに広がる金色の光。それが何なのか答えが見つからないまま、セイは西の森の討伐に回復要員として参加する。同行したユーリやアルベルトと共に危険な森を進んでいくが……。', '2021/06/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2a73939-4b94-44c1-b163-392f348e7a41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e86b643-4c6a-49b2-8053-c88a3ba4910a', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 9, '100083899', '聖女', 'セイが放った光り輝く魔法は、瘴気の沼から湧き出る魔物たちを一掃した。その一件により、セイはますます周囲から聖女として注目されるようになっていく。そんな時、王宮内ではエリザベスが、アイラにかかりきりのカイル王子に詰め寄っていた。カイル王子は聖女と噂されているセイを否定する発言をし、居合わせたセイは気まずくなってしまう。そこへ現れたジークフリート国王が場を収めたが、カイル王子は謹慎処分を受けることになった。しばらくして、エリザベスはセイとアイラを交流させようと、お茶会を開く。', '2021/06/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8231d09f-3fed-4306-bfd1-a58d01b3712c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5005a092-27e2-45ce-9ab3-c18a0836d298', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 10, '100084333', '日記', '討伐のため、地方のクラウスナー領へ遠征する第三騎士団。危険を伴う任務だったが、同行するセイは薬草の一大産地であるクラウスナー領で、新たな薬草を学べることに期待していた。領主のダニエルはセイに薬師のコリンナを紹介。コリンナは、この地で「製薬の祖」と呼ばれた薬師が残した日記をセイに読ませてくれる。この薬師も聖女だったのかもしれない。そう考えていた時、地元の傭兵団から森に魔物が現れたと知らされる。第三騎士団でも怪我人が出たと聞き、アルベルトが心配なセイは思わず駆け出す――!', '2021/06/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73726260-29c7-47cd-9b09-c094d8f4e946.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e8f1101-cc48-4edb-bdef-bb3447ee3497', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 11, '100084670', '窮地', '再び「聖女の術」を放ったセイは、その発動条件に自ら気づき困惑していた。一方、セイの能力を目の当たりにした傭兵団のレオンハルトは仲間として勧誘しようとするが、彼女が聖女だと知り、仕方なくあきらめる。そして、いよいよ本格的な討伐が開始される。「聖女の術」が必要となる事態も考えられるが、セイはアルベルトに発動条件を打ち明けることはできなかった。クラウスナー領の森は思っていた通り、珍しい植物にあふれていた。アルベルトとレオンハルトに護衛されたセイは、ワクワクしながら森の奥へと向かう……。', '2021/06/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4da86d3-7fb2-4a0c-abab-3c8c3a5ba8e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5912f1b9-224d-4605-be88-cb53ef223cbf', 'cf1ae75c-6d20-44cd-a74f-c5e889b46f2b', 12, '100084990', '帰還', '【シーズン1 最終話】スライムの襲撃を受けたセイたちは、王都から支援に駆け付けたユーリとアイラの加勢で無事に森から撤退した。その後、コリンナの協力で「聖女の術」を自在に発動できるよう練習に励むセイ。再編成した部隊で再び森へ向かうことになるが、過去に魔物討伐で一帯を燃やし尽くしたユーリの参加に、故郷の森を愛するレオは心配顔をする。行く手にはまたしてもスライムが出現するが、目的地は森の奥深くにある瘴気が渦巻く沼。巨大な怪物のようなスライムも襲いかかってくるなか、セイは「聖女の術」で沼の浄化を試みるが……!?', '2021/06/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff36c068-6013-487b-ad81-c4efdc7ed6c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('63cf21a5-fd6b-4cbc-8e3d-9b72b0eb84ac', '聖女の魔力は万能です', '', 'hulu', 'the-saints-magic-power-is-omnipotent-season2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/039a2df9-1277-4995-b9e5-bb27b05fdcce.jpg?w=331&h=447&p=t', 'hulu', 2021, 1, 1, 'FINISHED', NULL, 123802, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('68ad8e3d-863d-4ebb-94f0-b45447c966b1', '63cf21a5-fd6b-4cbc-8e3d-9b72b0eb84ac', 'hulu-the-saints-magic-power-is-omnipotent-season2-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/230824ca-ade5-4e9b-a643-d08c0a8e73db.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cae37098-adf6-4727-b61a-89db54bda343', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 1, '100161774', '商会', '聖女として認知されてからも、薬用植物研究所で研究三昧の日々を過ごすセイ。今は新しい化粧品を開発中だが、その効果の高さは侍女たちにも注目されていた。そんなとき、ヨハンはセイに新たな商会を立ち上げることを提案する。', '2023/10/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/230824ca-ade5-4e9b-a643-d08c0a8e73db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4a1dfc0-e3be-4cc3-89f2-f5611a9d9697', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 2, '100162531', '異国', '元いた世界と同じ農産物を探し求めて、港町モルゲンハーフェンを訪れたセイ。その船着き場で事故現場に遭遇するが、お忍びのため回復魔法は使えない。助けを求めるセイラン船長に手持ちのポーションを渡し、セイは立ち去るが……。', '2023/10/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/884bbe6a-915c-4e77-9606-f2f2cfb41753.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('390bb072-43a4-40ba-82f1-9a7e2258b93f', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 3, '100163372', '式典', '王宮にて「聖女セイ」の正式なお披露目会と舞踏会が開かれることになった。注目されることが苦手なセイは戸惑うものの、アルベルトからのエスコートの申し出を受ける。当日、国王の隣には聖女のローブをまとうセイの姿があった。', '2023/10/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7222d020-e833-43a1-9561-28fdefb3fc2d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7703140c-9a46-42d1-b7fe-a92f71ae8399', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 4, '100164206', '皇子', '貿易相手国の王子を留学生として迎えるにあたり、セイは住居を研究所から王宮へと移す。それは国家機密である聖女の能力を隠す目的もあった。留学生の国が以前出会ったセイランと同じ国だと知り、嫌な予感がするセイだが……。', '2023/10/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d49ae155-7f48-4c29-9026-b064edb7fdb1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa58f4fe-4a49-4c11-95d9-e0814fa84233', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 5, '100164836', '目的', '研究所で遭遇して以来、留学生のテンユウは連日セイを探し回っていた。ごまかすのも限界と判断したヨハンは、聖女であることを明かさずにセイと会わせる。テンユウと植物談義で盛り上がったセイは、彼の目的が気にかかり……。', '2023/11/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4cfb64c-ce68-4ec0-8eb7-a5a41ab4ccd6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6909d2b-1e6a-4583-bcf5-82345b9bbc2a', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 6, '100165484', '天佑', '難病に苦しむ母がいるテンユウは、セイランがもらったポーションを手がかりに、優れた薬師を探していた。だが、どんな上級ポーションでも進行中の病に効くとは限らない。事情を知ったセイは万能薬作りに挑戦してみることに……。', '2023/11/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3f264a4-430e-416a-a477-a7b870d5b23e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3bbd099b-02c6-443e-8995-0584479f0c33', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 7, '100166120', '幕間', 'アルベルトが率いる第三騎士団とセイが行う魔物討伐に、一旦の区切りが見えてきた。ひと息ついたところで、今後はセイの婚約問題が持ち上がると告げるエリザベス。聖女であるセイの婚約は、国王の会議でも話題になっていた。', '2023/11/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/843cf9f1-34df-4a9b-8676-79a019f6364c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e96fa0c-3ff3-48cd-b2df-7688fddbb168', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 8, '100166855', '辺境', '魔物討伐のため、アルベルトの故郷･ホーク領を訪れたセイたち。アルベルトの両親で領主を務めるホーク夫妻は晩餐会を開き、セイは楽しいひとときを過ごす。翌日、魔物が出現する鉱山周辺は異様な雰囲気に包まれていた……。', '2023/11/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e64e71a4-dae7-4313-9c59-7fc1d88f26a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cb0a244-5a7d-437d-bdc6-c6d2f501e3cf', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 9, '100167530', '終幕', '鉱山の森に現れたのは、生きた屍のような魔獣だった。それらを生み出す「黒い沼」を目指し、セイたちは鉱山の薄暗い坑道を進む。襲いかかる魔獣の群れを退けながら、たどり着いた最深部でフルパワーを発揮するセイだが……。', '2023/12/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b837499-659e-40fb-bd02-640f85aa2053.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0d86b25-0cef-4102-ac3d-b784c690d2b5', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 10, '100168290', '思慕', '巨大魔獣を倒して「黒い沼」も消滅させたセイたち。領主の屋敷では一行を労る宴会が開かれ、セイは美味しい料理を夢中で味わう。翌日、ホーク領の市場を訪れてはしゃぐセイを、同行したアルベルトは眩しそうに見つめていた。', '2023/12/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae823e5e-b763-43fa-a9da-7e36055188b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('adbb1449-32d5-4264-a617-368e4d423977', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 11, '100169050', '観劇', '魔物討伐の終結により、セイの聖女としての使命はひとつの区切りを迎えた。そんなある日、ユーリのもとに養父のドレヴェス侯爵から演劇の招待状が届く。何かを思いついたユーリはセイを誘うが、それが波紋を呼ぶことに……。', '2023/12/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbfd4b70-9594-470f-9851-e0fc27a9c7af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f3e6f9ec-db42-4cac-9d46-9ffbe1df6960', '68ad8e3d-863d-4ebb-94f0-b45447c966b1', 12, '100169770', 'Blessing', '【最終話】セイとの初めての出会いやこれまでのことを振り返りながら、自らの想いと向き合うアルベルト。一方のセイはエリザベスから、自分の気持ちを大事にするようにと諭される。周囲の誰もが、不器用な二人の様子を見守っていた……。', '2023/12/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b11de926-303c-4e48-bfe6-3b3eee0a1195.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a8b5007e-6cc0-4e69-b75e-b26facc21688', '聖闘士星矢 THE LOST CANVAS 冥王神話', '', 'hulu', 'saint-seiya-the-lost-canvas', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e7247a0-dd27-49c5-b790-0158ff85bd64.png?w=331&h=447&p=t', 'hulu', 2009, 2, 1, 'FINISHED', NULL, 6171, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 'a8b5007e-6cc0-4e69-b75e-b26facc21688', 'hulu-saint-seiya-the-lost-canvas-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1610c753-bfcd-49c1-9007-0d17e9d40a9b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba52b01d-389e-4361-a95b-21df37cc0796', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 1, '100175862', '約束', '聖戦。それは二百数十年ごとに繰り返される女神アテナと冥王ハーデスとの闘い。その兆しが見えはじめた18世紀ヨーロッパの田舎町。そこで暮らすテンマとアローンは、性格は正反対だが、仲のいい親友だった。ある日アローンは、パンドラと名乗る女性に出会う。その日を境に、運命の歯車は大きく動き始める。', '2024/04/05 00:00:00', 1596, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1610c753-bfcd-49c1-9007-0d17e9d40a9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19961c6a-4462-4515-b300-2e8de8075b1b', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 2, '100175863', 'ハーデス覚醒', '聖域では、冥王軍との新たな聖戦に向けて女神アテナの名のもとに黄金聖闘士たちが集う。その頃テンマは、聖闘士になるため修行に励む中、アローンの妹･サーシャと偶然の再会を果たし、彼女がアテナの化身であることを知る。一方アローンは、遠く離れた親友テンマのことを思いながら、ひとり絶望に打ちひしがれていた。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6f0675a-2df8-4e1d-9578-a4e1b5860c5e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47f02058-6671-4a4a-9296-8d84d655c37c', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 3, '100175864', '聖戦始動', 'テンマたち聖闘士は、冥闘士が集結しているというイタリアの町に向かう。そこが故郷の町であることに気づき、アローンの身を案じるテンマ。しかし、火に包まれていた町で姿を現したアローンは、冥王ハーデスとして覚醒していた。親友の豹変にショックを受け、呆然とするテンマに対し、アローンは容赦なく一撃を加える。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/388f3e93-7eed-4954-9f7a-192dbe7d6557.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0853a52-c977-4921-867a-2268263b63c3', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 4, '100175865', '祈りの花輪', '「テンマの死」と「兄アローンのハーデスとしての覚醒」を知らされながらも、哀しみを押し殺しアテナとして気丈に振舞うサーシャ。一方、テンマの死体を引き上げた青銅聖闘士･耶人は、突如現れた女戦士ユズリハに連れられ、ジャミールへ向かう。ジャミールの族長ハクレイは耶人に、テンマは完全には死んでいないと告げる。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56a46dd4-23c8-4e7f-af62-7e068e3d9e0f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3a1b76c-8af2-4c73-aba9-9261515c66ff', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 5, '100175866', '毒薔薇', '冥王軍三巨頭の一人ミーノスは、聖域に攻め入るべく見えない糸を操り次々に聖闘士を倒していく。だが、聖域を目前にしてミーノスたちの前に出現したのは、毒薔薇の園。そして園の中には魚座の黄金聖闘士アルバフィカの姿が。毒薔薇の香気の効かない冥闘士ニオベを、自らの血を打ち込み倒したアルバフィカだが…。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6181a6c-13e0-4f92-9cb8-595382a4b239.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee1ccc0b-9403-495d-af9b-162fe9140491', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 6, '100175867', '花葬列', 'ミーノスの実力に苦戦するアルバフィカは渾身のクリムゾンソーンを放つが、それすらも冥衣によって防がれ、ついにアルバフィカは倒れ伏す。そしてミーノスが次に向かったのは、アルバフィカが守ろうとしていた聖域近郊の村。村は次々に破壊され、アルバフィカを慕っていた少女アガシャも、ミーノスの標的にされてしまう。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc0d18b8-0524-40ca-893c-0827852d2cdb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5c7defaa-3e79-4633-a730-5c3828850294', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 7, '100175868', '木欒子の実', '不死である冥闘士を倒す方法が、冥界に生える木欒子の実にあると聞き、テンマたちは必死で捜索する。たどり着いた木欒子の前に現れたのは、乙女座の黄金聖闘士アスミタだった。味方か? 敵か? 光の無い世界で瞑想の修行を続けてきたアスミタはテンマの戦いの理を否定し、人間の五感を奪い去る「天舞宝輪」を放つ。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7040beeb-e4b1-415f-814c-be2c4bd8ffda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd146b4d-5c3d-425c-9b42-fda5b28fe018', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 8, '100175869', '良き風の日', 'アスミタに渾身の一撃を与えるテンマ。するとテンマの小宇宙の高まりに呼応し、木欒子が実を結ぶ。アスミタは姿を消してしまうが、テンマたちはとりあえずその実を拾い集め、冥界から生還。しかしジャミールにも、新たな冥闘士の魔の手が迫る。彼らの前に立ちはだかったのは、再び現れたアスミタだった。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c98a9c95-e628-427b-b12c-bd236357cf4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('886a7dce-2b6f-43e9-bd8a-8be79942ca8f', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 9, '100175870', '巨星', '聖域に進攻しようとした冥闘士たちを圧倒的な力で一蹴する、牡牛座の黄金聖闘士アルデバラン。そこに敵意を剥き出しにした天暴星ベヌウの輝火が降り立ち、戦いを挑む。一進一退の攻防が続くも、アルデバランの言葉に追いつめられた輝火は、炎でアルデバランの動きを縛り、立て続けに大技を放つ。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c27f1d58-3712-45fb-a2ed-0e7295cc7ef6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecb5f5ae-dfc5-4621-b8df-3f213284a554', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 10, '100175871', '降臨', '輝火の猛攻を凌いだアルデバランは、大地を返すほどの「タイタンズノヴァ」で勝負を決める。だがアルデバランは、輝火のことを邪悪ではないと断じ止めを刺さず、傷だらけの輝火は薄暮の空に飛び去った。その後、聖域では突然、恐ろしく巨大な小宇宙とともにアテナの結界が破られる。サーシャの前には冥王ハーデスの姿が!', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98e943fe-005b-40a8-a9f8-bc705f616188.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b75fb858-ae86-4f3b-bc93-52e9ffe1dd32', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 11, '100175872', 'もう届かない', 'ついに聖域へと帰還し、アローンに戦いを挑むテンマだが、返り討ちにあってしまう。その時、教皇が現れ、先代アテナの護符を用いてハーデスの力を弱体化させる「タリスマンケージ」を発動。アテナと小宇宙を合わせて封印の地へと空間を繋ぎ、ハーデスを封印しようと試みる。だがそこにパンドラまでもが駆けつけ…。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59aa9399-be9b-4c9a-ab4b-20367976bdc6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37e5a968-1ff4-4182-8540-be25aa83ea2d', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 12, '100175873', '絶えない犠牲', '完成したときに地上は滅びるという空一面の絵「ロストキャンバス」。優しかったアローンがハーデスとして人類を滅ぼそうとしていることに苦悩するテンマ。その頃、パンドラはハーデスの覚醒が不完全なことに焦り、原因であるテンマを抹殺すべく刺客を送り込む。超音波によってテンマたちを眠らせた冥闘士たちだが…。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3316664-9842-452d-a5a5-997730c98126.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8a566e0-5d38-4857-b651-559b4bce29f4', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 13, '100175874', '旅立ち', '聖域を去り、一人で戦うことを決意するテンマだったが、教皇の命を受けた蟹座の黄金聖闘士マニゴルドに捕まり、牢に閉じ込められてしまう。一方ハーデス城では、アローンの記憶に遮られて完全に覚醒していないハーデスを空間の歪みに作ったアトリエに幽閉するよう、ヒュプノスとタナトスがパンドラに仕向けていた。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6c13157-bd2a-4b19-9d0a-79036a106db9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4343c50b-344e-46bb-89ea-d6b665b3b2fd', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 14, '100175875', '死の森', 'アローンを冥王として完全に覚醒させるため、「ロストキャンバス」の制作に専念するようその身を幽閉するパンドラ。その陰で、神話の時代から冥王との因縁を持つペガサスの聖闘士の存在を危惧し、冥王の側近である双子神･タナトスとヒュプノスが動き始めていた。一方、聖域ではジャミールの長老･ハクレイが教皇の下を訪れる。そして蟹座の黄金聖闘士マニゴルドも教皇の命を受け、テンマの後を追う。その頃、ハーデス城に向かう途中、滅ぼされた故郷の村に着くテンマだったが、そこに現れたのは妖しさを放つ巨大な森だった。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fa5b146-8c43-4c7b-b07b-838fa8b612ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b216b6d-5457-4f20-9a33-0a486b963011', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 15, '100175876', 'もしあの日に帰れたら', '死の森に足を踏み入れ、テンマたちとはぐれてしまったユズリハ。その目の前に、死んだはずの弟･トクサの姿が現れる。トクサの呼びかける声に、ユズリハの思いは過去へと向かう……。その一方、耶人は巨大なムカデに追いつめられていた。薄れゆく意識の中で耶人もまた、少年時代のことを思い出すのだった。冥闘士ベロニカと対峙し苦戦を強いられるテンマの下に、ふたりは辿り着けるのか?', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19fad0ca-a275-4880-bd68-921b6c9eb120.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf155484-b328-4b70-b20e-f019116c94c9', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 16, '100175877', '神と駒', 'ベロニカが操る無数のゾンビに囲まれるテンマたちだが、蟹座の黄金聖闘士･マニゴルドに助けられる。教皇の命を受けテンマの護衛として現れたマニゴルドは、圧倒的な強さでベロニカの体を真っ二つに。それでも死なないベロニカは、森とともにテンマたちを腐らせようとする。一方、離宮では一連の闘いを双子神ヒュプノスとタナトスがチェスをしながら眺めていた…。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07cd0cbd-82aa-4e0f-9841-ac9df9e62e49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36711b14-20b2-4e9a-a49e-6f5a0ab1d5c2', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 17, '100175878', '塵芥', '双子神の居場所をつきとめたマニゴルドだが、死の神タナトスの圧倒的な力の前に、為す術なし。そこへ教皇セージがかけつけ、応戦する。タナトスの攻撃を受けながら、マニゴルドは幼少時代にセージと出会った日のことを思い出す。戦争孤児だったマニゴルドは、かつて人間の命など塵芥だと考えていた…。ついに本気となるタナトスを前に、果たして勝機はあるのか?', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e65e7b7b-5938-4fc5-8685-1697e37523f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6065ea24-8220-4793-8444-3fdbd6b9d15b', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 18, '100175879', 'ただ生きてほしい', 'マニゴルドに傷つけられたことによって、タナトスがついに本気になった。圧倒的に不利な状況で、しかしセージはひるまない。「絶望などと、簡単に口にするでない」というセージの言葉から、マニゴルドは師との昔のやりとりを思い出し、希望を取り戻す。二人は一縷の勝機にかけて「積尸気冥界波」を放ち、タナトスの魂を肉体から分離させることに成功するが…!', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36679be6-f52b-4352-affc-74e6e6a631ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1de1b7eb-8c71-4423-8479-4d4a57f384b1', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 19, '100175880', '孤高の剣', 'ヒュプノスは、夢を司る四人の神々を招集する。その一人、幻夢イケロスは、人馬宮にまで侵入し、その場に居合わせた山羊座のエルシドの攻撃をかいくぐり、未だ意識の戻らないシジフォスの魂を奪い去る。エルシドはシジフォスの魂を奪還すべく、単身、聖域を後にする。シジフォスの右腕として常にそばにいたエルシドは、シジフォスが目覚めない理由を感じ取っていた…。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1a651c6-1ca2-4a09-9042-ca176bc13776.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f340bc2-ec5d-42aa-ab5e-1a13399673e7', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 20, '100175881', '夢の牢獄', 'エルシドは、シジフォスの魂を奪還するため、夢を司る四神の一人･イケロスに戦いを挑むも、片腕をもぎ取られ崖の下へと落下していく。一方、ハーデス城へと向かっていたテンマは、ユズリハや耶人とはぐれてしまい、なぜか滅んだはずの故郷へとたどり着く。そこには幼いアローンやサーシャの姿が。「今までのことは、すべて夢だったのか?」混乱するテンマだったが…。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e850eca2-e968-4276-b289-d7e82c6b4f00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('858af302-69d1-4eb4-b004-d3239c441766', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 21, '100175882', '夢の先に', 'エルシドは、空間を自在につなげて攻撃してくるイケロスに対し、自らの血を舞わせてその動きを読み、イケロスを貫き倒す。その頃、ペガサス流星拳で夢から覚めたテンマの前に、造形者モルペウスが立ちはだかる。モルペウスは夢界に咲く芥子の花で次第にテンマの感情を奪っていくが、テンマの耳にアローンの声が聞こえると、テンマの聖衣に変化が表れて…!', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88abcba6-6514-4597-aa16-45f4e0b99c00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('765fbfd1-5ae1-4223-8a8b-1031334b861f', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 22, '100175883', '大義の道', 'イケロスたちと合体したオネイロスの前に、テンマたちはシジフォスの魂を救うこともかなわず追い詰められてしまう。だがそこに、シジフォスを救おうとアテナであるサーシャ自らが夢界へと乗り込んできた。サーシャの邪魔をさせまいと、テンマとエルシドは再びオネイロスに立ち向かう。そして、オネイロスを夢界から地上へ追いやることに成功する!', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df9e7a7d-5c38-4620-9c22-81685c90fd27.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bb796f0-42eb-4840-85dc-9bce48937730', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 23, '100175884', '聖剣', '夢界へやってきたサーシャは、シジフォスの夢へ入っていく。シジフォスは夢の中で、自分がサーシャを聖域に連れ去ったことが彼女を不幸にし、さらに聖戦を引き起こしてしまったのではないかという罪悪感に苛まれていた。心を閉ざし闇に落ちかけたシジフォスを、サーシャは命を掛けた説得で救い出す。だが、そのころ地上ではオネイロスとの戦いの中で、エルシドの小宇宙がついに尽きようとしていた…。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/644e2932-206c-4074-9a6e-60a4414f8471.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75c4eb28-7df5-4463-a16d-ea1aca9d5358', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 24, '100175885', '血戦の時', '四神が倒されたことで、ヒュプノスの「眠りの結界」は破壊され、ついに聖闘士たちは、亡き仲間たちの想いを胸にハーデス城へと進軍する! ハクレイはセージに代わって全聖闘士たちを鼓舞し、自らも眠りの神ヒュプノスを討つべくハーデス城に乗り込んでいく。だがそのころ、夢界でロストキャンバスを描き続けていたアローンは、ヒュプノスによってついに冥王ハーデスとして完全に覚醒してしまう…。', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc8208f6-7afa-4f31-9e06-940597480a2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06608304-e804-4778-8936-6212f896a94a', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 25, '100175886', '幾星霜', '先代アテナの加護を受けた剣を携えてハーデス城に一人潜入したハクレイは、立ちふさがる冥闘士をなぎ倒しながら進み、ハーデス城を守る結界の中心を発見する。しかし、アテナの剣で結界を破ろうとしたそのとき、ハクレイの前にヒュプノスが立ちはだかる。ハクレイは、前聖戦からの因縁の相手であるヒュプノスとの戦いに決着を付けることができるのか!?', '2024/04/05 00:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a735e154-e30c-4996-be1d-bafa08171dac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('209fc5c3-befd-4f0c-b8ff-12bdc69d75d2', 'b6dede99-6b2d-4ff2-af97-44e3f7cb36eb', 26, '100175887', 'お前らしくあれ', '【最終話】ついにハーデス城の結界が解かれようとしたその時、冥王ハーデスが姿を現す。テンマや童虎も駆けつけるが、覚醒したハーデスの力はあまりにも強大すぎた…。もはや為す術はなく、撤退すらもできない。絶体絶命…、そう思われたそのとき…!', '2024/04/05 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5adefac-b62d-4308-b5bc-2c5d0f7367e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f4c59c87-bcee-4cd9-8bdf-7359ec8ae654', '西洋 骨董 洋菓子店', '', 'hulu', 'antique-bakery', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77aba944-ea7a-4b0e-99d2-0daee416ee75.jpg?w=331&h=447&p=t', 'hulu', 2008, 2, 1, 'FINISHED', NULL, 4021, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 'f4c59c87-bcee-4cd9-8bdf-7359ec8ae654', 'hulu-antique-bakery-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69f83e9b-429a-4339-b4b1-e1a6b6f9de5b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76cfba56-f49f-46a2-84f8-fad94cd6845d', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 1, '100150658', '「再会の酸味」', '裕福で満ち足りた生活の中、何か埋まらない空白を持つ橘圭一郎は、会社をやめ西洋骨董をコンセプトにした洋菓子店「アンティーク」を開くことにする。親からの紹介でパティシエの小野裕介と出会う。橘は小野を知っていた。小野は過去、橘と高校の同級生であり、橘は小野に対して屈辱的な言葉を浴びせていたのだった。ところが、小野は橘を覚えていない素振り。また天才パティシエと呼ばれながら店を転々とする小野には、ある秘密があった…。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69f83e9b-429a-4339-b4b1-e1a6b6f9de5b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aba72076-82d9-4c55-bec7-a934c55216d3', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 2, '100150659', '「決意の辛味」', '洋菓子店「アンティーク」のオープンに向けて販売員を募集していた。現れたのは元ボクサーの神田エイジだった。小野の作るスイーツに感動したエイジは、販売員の募集だったのにもかかわらず小野に弟子入りを志願する。その頃、ボクサーのサンダーはジムの会長から次の試合で負けたら引退と勧告された。納得できないサンダーは恋人の波子に連れられ「アンティーク」へやってくる。そこには伝説のボクサーであったエイジが働いていた。エイジの姿に悪態をつくサンダーに波子は妊娠したことを告げる。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23eaa4b0-bfbb-4952-97fd-a3b225e38334.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bcc22b1-ea5d-4f8d-8b54-f40c2f9dbc8f', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 3, '100150660', '「四人の新味」', 'グランドオープン当日は生憎の雨。そんな中でも自信たっぷりで余裕の橘。順調な売り上げを見せる。そんな店にサングラスで全身黒ずくめの長身男･小早川千影が現れる。見た目とは裏腹に天然で不器用な千影。彼は橘の幼馴染だった。雨で客足の途絶えたアンティークで、偶然二人きりになってしまった小野と千影。小野はサングラスをとった千影の素顔を見た瞬間、理性が飛びときめいてしまう。二人は雨の中、外へ飛び出し…。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/909a92aa-0f17-4fff-bdb2-9890e532da60.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d535e0a5-8f35-475a-9e4b-bb799c6c4c72', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 4, '100150661', '「悪夢の真味」', '橘は千影をアンティークの従業員に迎える。その晩、小野と千影は橘に内緒で夜の街へ出る。二人で飲んでいても橘を気遣う千影に、小野は嫉妬し魔性のゲイの力を発揮する。艶かしい小野の姿に千影はふと唇を近づける。ところが純粋無垢な千影は、小野がゲイであることに気付かず、勘違いと後悔で小野をひとり残して去ってしまう。翌日、二人の微妙なやり取りに何かを感じる橘とエイジ。そこに小野の恋人が浮気を問い詰めにやってくる。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37c7c8b8-d6bc-4eee-b2c4-5ca1b8bb321e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22248fcd-dcf0-4279-9071-1007be37f39d', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 5, '100150662', '「試練の渋味」', '今もジムに寝泊りしているエイジ。夜な夜なエイジの体からはスイーツの甘い香りが漂い、ジム生から苦情が出る。エイジは会長から聞き、ジムを出ることを決意する。そんな頃、デパ地下洋菓子フェアへの出店とテレビの取材依頼がやってくる。自信満々の橘。人出の多いデパ地下を橘が担当することにしていたのだが、アクシデントで、急遽、女性が苦手な小野と不器用な千影がデパ地下を、橘とエイジがアンティークを切り盛りすることになるのだが…。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/591cd633-a5f1-4d7d-839e-bf6831686ee7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e24b1fb-88cf-4b5c-8f70-2e789629c919', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 6, '100150663', '「危機の苦味」', 'アンティークに世界的に有名なパティシエ、ジャン･バティストがやってきた。ジャンは小野の洋菓子の師匠であり、かつての恋人でもあった。ジャンは小野を引き抜きにきたのだ。破格の条件に橘たちは慌てる。だが、小野は断るつもりでいた。その旨を聞いた橘は安心したものの、小野はジャンに切り出すタイミングを計りかねていた。翌朝、小野が時間になっても出勤しない。心配になった橘と千影は自宅を訪ねるとジャンと小野の修羅場に遭遇する。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1c21e4c-074d-4d6f-b505-22ded1b40672.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed818949-c2f6-47b9-9a09-3faf17b82df6', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 7, '100150664', '「聖夜の甘味」', 'ケーキ店が一年で最も忙しい日、クリスマスが近づいていた。橘の提案でイブ当日限定で無料配達をすることにし予約の受付が始まる。申し込みは好調。小野とエイジでクリスマスケーキ作りが進められる。そんな中、常連客から特注クロカンブッシュの予約注文がやってくる。しかも配達先で飴掛けのパフォーマンスをしてほしいという。橘はそんな無理な注文も気軽に引き受けてしまった。混乱と奮闘の中、ついにクリスマス当日がやってくる。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/932f16a5-ac37-4444-87ce-071cdcea8d61.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ad66a04-0811-49cd-a068-9d76bccf4181', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 8, '100150665', '「千影の隠味」', '悪夢にうなされる橘。未だ少年時代の誘拐体験のトラウマから抜け出せずにいた。千影はそんな橘を傍で見守り続けている。千影は橘にとってもなくてはならない存在なのであった。ある晩、閉店後のアンティークに背の高い美少女が訪ねてくる。彼女はいきなり千影に泣きついた。母親と喧嘩して家を飛び出してきたというのだ。ただ呆然と眺める小野とエイジ。そこへ少女の母親が現れて…。少女と千影の関係、そして千影のある秘密が明らかになる。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84257bbf-0f3f-488c-971c-0582a0d6baa3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c6da330-0ede-4338-85a6-17dcf69131b2', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 9, '100150666', '「憂鬱の小味」', '連続児童誘拐事件が世間を賑している。過去の自分が蘇る橘。また一方で、報道を神妙な顔つきで見つめる男、芥川がいた。「アンティーク」では、エイジがパティシエとしてメキメキと成長していた。橘と小野は近い将来フランスでの洋菓子修行を薦め、語学学校へ通わせる。エイジはあまり乗り気ではない。「アンティーク」での自分の存在が希薄になっているように感じていたのだ。そんな時、エイジは公園で不良に絡まれている男を助けたのだが…。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8367993b-4e2c-4d6c-aab2-c9e8901da8b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a0d7604-1e81-434c-b6ba-961f9f248a4f', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 10, '100150667', '「鼓動の異味」', 'ある日、小野の妹永子が訪ねてくる。小野に自分の結婚式に出席してほしいとの頼みだった。しかし、小野はゲイであることを打ち明け、家を飛び出して以来、家族と顔を合わせることがなかった。妹の願いに小野は即答することができないでいた。その頃、世間を賑す児童誘拐事件に新たな展開がみられる。被害者の胃の内容物からビスケットやチョコレートなどの共通した食品が見つかり、合わせると一個分のケーキになることが判明したのだった。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8507f638-2ded-450f-b2c1-bb397e489aae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad0ead12-286c-4955-9b18-0e3e2c33c50f', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 11, '100150668', '「真相の快味」', '子供の頃の記憶。誘拐されたときの悪夢。拭い去れない闇。橘は未解決のまま長引く誘拐事件に漠然と何かを感じていた。警察は、被害者の胃の内容物から、事件解決の糸口をアンティークに見出した。橘たちの協力の元、店に張り込みを始める。いつもと変わりのないアンティークの日常が過ぎていく。特に変わったこともないまま、閉店時間を迎えようとしていた時、顔色の悪い一人の中年女性が店にやってくる。', '2023/08/28 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37f99c6c-fb8c-4317-8695-088d20084575.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc2394e7-7cc2-4ed0-b584-7dca123a9ea5', '20ba91a9-42a5-41aa-9b59-49adeba1e3d1', 12, '100150669', '「永遠の後味」', '【最終話】橘の行動で連続幼児誘拐事件は解決をみた。しかし、それでも橘は言いようのない暗い感慨を抱えたまま、変わらぬ悪夢に眠れぬ夜を過ごしていた。アンティークはオープンから一年が経とうとしている。ますます繁盛し、何もかも順調であった。エイジはフランスへの渡航を決め、千影は橘から離れ一人で生きていく道を選ぶ。それぞれが新たな世界へと踏み出すなか、過去を捨て新たな歩みを始めようとしている、ある初老の男の姿があった。', '2023/08/28 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f16a221a-7b97-44d7-b56f-c13f31f19979.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('87b73030-9ab5-4787-9a97-be1c8cbc1afa', '青のオーケストラ', '', 'hulu', 'ao-no-orchestra', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5674c814-f01b-4b15-9676-88e967340545.png?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 147369, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('589c8532-2e46-456f-8aac-c72319983774', '87b73030-9ab5-4787-9a97-be1c8cbc1afa', 'hulu-ao-no-orchestra-s1', 'Season1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2c05b4a-cc53-45be-930e-4c8cc1f79209.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65df4122-7d64-46bd-a7c1-b3118ef55aed', '589c8532-2e46-456f-8aac-c72319983774', 1, '100143135', '青野ハジメ', '世界的に活躍するヴァイオリニスト･青野龍仁を父に持つ少年、青野一。父の背中を見て育った一は数々のコンクールで好成績を収め、ヴァイオリンの天才少年と称賛される。しかし、とある理由で弾くことを辞め、無気力な毎日をすごしていた。そして迎えた中学3年の秋、止まってしまった時間が静かに動き出す日がやって来る。きっかけは、同級生の少女との出会いだった。さらに、進学を控えた彼は、高校オーケストラ部の存在を知る。', '2023/04/12 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2c05b4a-cc53-45be-930e-4c8cc1f79209.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f3256089-1efd-42e1-b127-deffff5e5836', '589c8532-2e46-456f-8aac-c72319983774', 2, '100143491', '秋音律子', '最悪な形で出会った、青野一と秋音律子。ヴァイオリン初心者の律子は、たった1人での練習を、熱心に続けていた。武田先生に頼まれたヴァイオリンの指導は断ったものの、不意に耳に飛び込んでくる律子のつたない、しかしまっすぐな音は、青野の心をざわつかせる。そして起こった思わぬ騒動。クラスメートを鋭くにらみつける律子の表情に、青野は彼女の事情と、ヴァイオリンへの思いを知る。そして、律子が差し出す楽器に青野は――。', '2023/04/19 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb8ccf11-0444-4794-816b-a0bded6df3f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd2e465c-f5b4-46ce-816b-138831139822', '589c8532-2e46-456f-8aac-c72319983774', 3, '100144389', '海幕高校オーケストラ部', '同級生でヴァイオリン初心者の秋音律子と出会ったことで、情熱を取り戻し、音楽と再び向き合うことを決意した、ヴァイオリンの“元･天才少年”青野一。中学3年の彼が武田先生に勧められた進学先は、コンクールで8年連続最優秀賞の強豪オーケストラ部を擁する、千葉県立海幕高校だった。やがて、2人の目標は自然に近づいていく。青野は律子にヴァイオリンを、律子は青野に受験勉強を指導する。そして迎えた春、2人が進む道とは――。', '2023/04/26 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9a7cc17-53f4-4829-9c12-aee1f4e46891.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d447e0ef-24e0-4152-aee8-5d4b8d8889a5', '589c8532-2e46-456f-8aac-c72319983774', 4, '100144672', '佐伯直', 'オーケストラ部のある海幕高校に入学した青野と律子。青野は、ヴァイオリンのコンクールで活躍した佐伯直という少年が音楽推薦で入学したらしいと、中学の武田先生から聞いたことを思い出す。そして青野は、小学生の頃から何度か同じコンクールに出たチェロの山田と楽器店で再会する。山田もオーケストラ部を目当てに海幕高校に入学していた。その山田が話題にしたのも、佐伯のことだった。そんな中、1年生の仮入部期間が始まる。', '2023/05/03 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6cd82373-c706-4306-8c34-2eccb2720fd4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ee5676f-f9eb-4c07-9062-c7e60ce1a588', '589c8532-2e46-456f-8aac-c72319983774', 5, '100145635', '原田蒼', '見学に訪れたオーケストラ部で、初対面の佐伯と音を合わせることになった青野。2人の高度な演奏は、部員たちをざわめかせる。やがて佐伯は、青野を挑発するかのようにテンポを変え始めた。青野も食らいつき、激しいぶつかり合いとともに2人の音は高まっていく。コンサートマスターの原田からの称賛と、部員たちの惜しみない拍手。しかしその中から不意に聞こえてきた、父･青野龍仁の名前。よみがえるあの日に、青野は凍りつく。', '2023/05/10 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4f64e1d-478e-40db-ba10-eb72a81f6835.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7b2b762-6f79-4f2e-848d-d377fc9b8d54', '589c8532-2e46-456f-8aac-c72319983774', 6, '100145935', '雨の日', '青野たち1年生にとっては初舞台となる夏の定期演奏会に向けて、オーケストラ部の練習が動き出した。佐伯とともに1stヴァイオリンに参加した青野は、大人数で音を合わせる難しさを知る。一方、2ndヴァイオリンに加わった律子は何度も演奏を止めてしまい、経験者との実力の差を痛感しながらも、ひたむきに取り組んでいく。そして授業の無い雨の土曜日。鮎川先生を指揮者として迎える前に、部員たちによる合奏練習が行われる。', '2023/05/17 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c86c9665-373a-44e5-ab0a-d6796d43841f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('469a9c39-064f-42c0-a7dc-13953b738495', '589c8532-2e46-456f-8aac-c72319983774', 7, '100146643', '小桜ハル', '鮎川先生の指揮によるオーケストラ部の合奏練習。厳しい指導の中で表現が追究されていく。その妥協のない姿勢に、青野は不意に父のことを思い出し、譜面を見失ってミスをしてしまう。鮎川先生によって演奏は即座に中断された。何もかもうまくいかない雨の土曜日。その雨は、練習が終わり帰る時間になっても降り続いていた。青野は、傘を強風に壊されてしまった同じ1stヴァイオリンの小桜ハルと、2人いっしょに帰ることになる。', '2023/05/24 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6edd1db-1249-4482-b692-e9c79c613e88.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64e2b215-1034-4b66-ac12-b9828cd5245b', '589c8532-2e46-456f-8aac-c72319983774', 8, '100147401', 'G線上のアリア', '転校の原因になった中学の同級生を偶然見かけたことで、登校することができなくなってしまったハル。部活も休み続けていた。心配する律子のメッセージに返ってくるのは、「大丈夫」という言葉ばかり。それは、ハルが自分を縛る呪いの言葉だった。ハルは、律子の優しさを知っているからこそ、頼ることができずにいた。高校オーケストラ部でともにヴァイオリンを演奏しようという、中学生の2人が交わした約束。律子は行動を起こす。', '2023/05/31 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c660124-9da1-47cb-a8ce-3900b9953e7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('387a885d-b51f-47e9-8b3a-1e09969afc68', '589c8532-2e46-456f-8aac-c72319983774', 9, '100148263', '先輩', '夏の定期演奏会まで2か月を切った。メイン曲となる「ドヴォルザーク交響曲第9番『新世界より』」のメンバーはオーディションで選ばれ、席順は学年と関係なく実力で決まるという。勝ち取るのは誰か? 審査する側となる3年生、コンサートマスターの原田はワクワクしていた。そして青野たち1年生の前に現れた見慣れぬ先輩。たまにしか部活に来ていない2年生の羽鳥だ。ヴァイオリンを手にした羽鳥は、いきなりコンマス席に座った。', '2023/06/07 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6bb0384-18e0-4498-b4fb-b207a5ea2ccc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0885287-dfb0-47d3-ada8-74e02c4ade16', '589c8532-2e46-456f-8aac-c72319983774', 10, '100148668', '初心者と経験者', '定期演奏会に向けてのオーディションまで1週間を切り、部員たちはそれぞれ熱心に練習に取り組んでいた。緊張感に気を引き締めながらも焦りと不安に駆られる律子は、思うように弾くことができない。高校で楽器を始めた者と、幼少期から弾き続けている者。律子と同じ2ndヴァイオリンの経験者･立花は、初心者にも関わらずオーディションに挑戦しようという律子にいらだつ。やがて、練習への取り組み方をめぐって、衝突が起こる。', '2023/06/14 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b5fd215-ad6e-4ca0-ad84-311d743dd6b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c98e1e6-8d41-41a6-8a9f-cf7de23fddaa', '589c8532-2e46-456f-8aac-c72319983774', 11, '100149404', '決戦前夜', 'オーディション3日前。部員の誰もが練習に打ち込む中、青野と佐伯は数学の補習を受けていた。2人そろって小テストが赤点だったのだ。早く部活に参加したい一心で、2人は課題に取り組む。大急ぎで駆けつけた音楽室では、合奏練習がもう始まっていた。鮎川先生は、オーディションでの演奏次第で、学年に関係なく席順を決める考えのようだ。コンサートマスターの原田も、1･2年生を競わせたいと思っていた。そして迫る決戦の日。', '2023/06/21 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92756c50-12e0-40ba-b6c4-2b75289a6dba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bddf8414-4b7a-475a-9a41-f3b0702b7c1f', '589c8532-2e46-456f-8aac-c72319983774', 12, '100150571', 'オーディション', '定期演奏会のメイン曲となるドヴォルザーク「交響曲第9番『新世界より』」演奏メンバーのオーディションが始まった。廊下に漏れるヴァイオリンに、順番を待つ部員たちの緊張が高まる。佐伯とどちらがよい席を勝ち取るのか? 青野は注目されていた。ライバルに勝ちたい、そして鮎川先生に自分を認めさせたい――。青野の番が訪れる。奏者に背を向けて座る審査員の3年生。しかし音が響いたその瞬間、全員が誰の演奏なのかを理解した。', '2023/06/28 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aca01dec-30be-47a1-b0da-8fb4c0f53773.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('edfc2d79-ce0d-4d8d-9415-9cc5ad901238', '589c8532-2e46-456f-8aac-c72319983774', 13, '100150949', '自分の音色', 'オーディションの結果、青野は佐伯より上の席次を勝ち取ることができた。ところが鮎川先生に、技術は高いが青野だけの音色が見えないと言われてしまう。幼少時に予選敗退したコンクールで、つまらない演奏と父に言われた記憶がよみがえる。焦りと迷いの中、とにかくヴァイオリンを弾きたい。しかし期末テストを控え、部活動は停止期間に入った。テストの成績が悪い部員は演奏会に出ることができない。青野はテスト勉強に取り組む。', '2023/07/05 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4e05d03-3dfa-4036-a106-c5fa12367478.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b01fc77e-e9ec-4f2a-925e-f06a732b057d', '589c8532-2e46-456f-8aac-c72319983774', 14, '100151843', '歩み寄る', '夏休みに入り、合奏練習が本格的に始まった。青野は、大勢で音を合わせることの難しさを痛感する。1人ずつの音程やリズムは正しいのに、合奏すると音がまとまらない。しかしその時、コンサートマスターの原田が、弓や身体の動きを使って合図を送り始めた。ゆるやかに陽気で楽しく―。皆の呼吸が徐々に揃って、演奏がひとつになっていく。オーケストラの全員、そしてすべての楽器の音と向き合う原田の手腕に、青野は感銘を受ける。', '2023/07/12 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb1961a8-fb9e-4529-aa06-ca8d2d7efe0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7dc8b3d7-2ebd-45be-bf40-875811484c80', '589c8532-2e46-456f-8aac-c72319983774', 15, '100152291', '本音', '将来のコンサートマスター候補として期待されている青野と佐伯は、弦楽器のトップ練習を見学することになった。各パートのトップ奏者が集まり、コンサートマスターを中心に曲のイメージを共有し、表現を具体的に決めていく場だ。そこには一切の遠慮が無かった。激しい意見のぶつかり合いに2人は圧倒される。しかし一度合奏が始まると、おだやかな時間が流れ始めた。青野は、先輩たちが楽器を通して本音の会話をしていると感じる。', '2023/07/19 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ad9b673-d2e5-4a31-a102-9c9b01df484e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5519e3fc-0973-4178-96d7-64965ba07d69', '589c8532-2e46-456f-8aac-c72319983774', 16, '100153303', '心配', '定期演奏会に向けて合奏練習に熱が入る中、青野が部活に姿を見せない。鮎川先生によると、青野の母が倒れ、入院したのだという。心配で今ひとつ身が入らないまま、練習は進む。青野の母をよく知る律子は、特にショックを受けていた。何度かけても繋がらない電話。じっとしていられず、家に様子を見に行くことを決める律子に、佐伯、ハル、山田も加わる。青野は、皆の突然の訪問に驚きながらも、ぽつぽつと自分のことを話し始めた。', '2023/07/26 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e18a1f2d-c1f2-4e30-8193-83ac6279d2ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3756a89c-e8b2-4c75-84ee-d5b6e8e5acea', '589c8532-2e46-456f-8aac-c72319983774', 17, '100153776', 'もう一つの本音', '「話したいことがある」。ひとり青野のもとに戻ってきた佐伯。深刻そうな表情で何かを切り出そうとするが、なかなか言葉にすることができない。ふと目に留まった防音室。青野が、父･龍仁とともに幼少期からヴァイオリンの練習に打ち込んだ部屋だ。飾られたトロフィーやコンクールの記念写真。青野の過去に触れる中で、佐伯は口を開き始める。声楽家の母のもとドイツで育った佐伯。日本に戻ってきた目的は、青野に会うことだった。', '2023/08/02 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4bd7158b-b509-405a-8557-b80c78f79231.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97e793a9-0b38-41a7-93f6-358aa5c3db9c', '589c8532-2e46-456f-8aac-c72319983774', 18, '100156819', '真実', '青野がまた、部活に来ない。秋音は、皆で青野を訪ねた夜、佐伯がひとり戻ったことを知る。最後に会ったはずの佐伯が何か知らないか問うと、返ってきたのは「青野くんはもう来ないかもしれない」という答えだった。その言葉通り、青野は退部を考えていた。体調を崩し入院中の母に、ふとそのことを漏らす青野。しかし母は、自分のやりたいことをやってほしいと反対する。思い悩む青野は、中学時代の恩師･武田先生と街で偶然出会う。', '2023/08/30 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c8c6239-9c49-4948-8021-cbbcc4f43b47.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('434fb014-2128-46ff-8b80-9d5442dda630', '589c8532-2e46-456f-8aac-c72319983774', 19, '100157315', '君として', '「あいつとケンカしてくる」と秋音に宣言した青野。青野と佐伯は、人気のない夜の公園で向き合っていた。あの夜、佐伯が打ち明けた事実を、青野は許すことができない。謝罪の言葉を繰り返すばかりの佐伯に、青野は感情をぶつける。佐伯との演奏が楽しかったこと、自分に無いものを持つ佐伯を妬んでいたこと―。そのすべてを裏切られたように、青野は感じていた。「佐伯直として、俺の前に立って話せ!」。青野は佐伯を問い詰める。', '2023/09/06 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08128414-abba-4881-9a2c-0bfc6d0dcc67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a6a3ed8-4b35-4b15-a432-43795995355c', '589c8532-2e46-456f-8aac-c72319983774', 20, '100158196', '夏の居場所', '夏休みまっただ中。オーケストラ部員たちは、定期演奏会に向けて、熱心に練習に取り組んでいた。青野たち1年生の初舞台となる“定演”は、3年生にとっては引退公演だ。部長の立石は、部活動と勉強に明け暮れる「最後の夏」に、充実感と少しの寂しさを感じていた。そしてやってきた部活休みの日曜の夜は、ちょうど花火大会。金魚すくい、かき氷、射的、そして花火。青野、律子、佐伯、ハル、山田の5人は、つかの間の夏を楽しむ。', '2023/09/13 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f00080fc-295a-47d3-bc2e-18bdbd7e5eb4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62b37794-4a78-48f7-b3e5-9fbf70956eb9', '589c8532-2e46-456f-8aac-c72319983774', 21, '100159178', 'ユーモレスク', '夏休みの宿題、観察日記。枯らしてしまったミニトマトに、よかったじゃないかと言う父。感じたことを音にしてみろ―。青野は、明け方に目覚めた。父のことを夢に見たのに、不思議と気分は悪くない。世界的に活躍するヴァイオリニストの父･龍仁。褒めてもらいたくて弾き続けた、幼い頃。思い出に導かれるように開いた譜面に見つけた書き込みは、父の筆跡だった。お前は、どう弾く? 青野はひとり、ヴァイオリンに弓を走らせていく。', '2023/09/20 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03d8be22-8dc4-444c-8a7b-5970d75eacd9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52826079-a3e1-4e13-b7d2-7fc9ac105cb3', '589c8532-2e46-456f-8aac-c72319983774', 22, '100159754', '贈る言葉', 'ついに迎えた定期演奏会の日。部員たち自身の手で会場となるホールに楽器や機材の搬入が行われる。舞台袖に並べられる楽器ケース。最後の舞台となる3年生は寂しさを感じていた。開演を待つ観客の中には、青野の中学の恩師･武田先生の姿があった。青野の母と出会った彼は、指揮者の鮎川先生と同級生だった高校時代、ともに部活に打ち込んだ日のことを語る。そして舞台裏では本番を前に、部員たちに向けた3年生の挨拶が始まった。', '2023/09/27 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e44b31c-21ce-4e87-9f87-26bfc3e12f0f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('348f337e-f7fb-4622-9066-5be50577c510', '589c8532-2e46-456f-8aac-c72319983774', 23, '100160792', '定期演奏会', '定期演奏会は「カルメン」で幕を開けた。オーケストラ部で楽器を本格的に始めた律子にとって、人前での演奏は未知への挑戦だ。同級生と対立し保健室登校していた中学の頃。ヴァイオリンとの出会い。演奏に、これまでの歩みが重なっていく――。ハルの出番となるチャイコフスキー「くるみ割り人形」。3年生メインのヴィヴァルディ「四季」。それぞれが音とともに過ごした時間、悩みや葛藤、心の交流、その全てをのせて演奏会は進む。', '2023/10/04 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d045ebea-3c66-4b8c-9a13-f29be560aaba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca322941-57a5-4d19-ace1-19afdfe04668', '589c8532-2e46-456f-8aac-c72319983774', 24, '100161763', '新世界より', '【シーズン1 最終話】故郷チェコを離れ、アメリカ大陸に渡ったドヴォルザークが作曲した「交響曲第9番『新世界より』」。オーケストラ部員たちは、それぞれの演奏の中にそれぞれの“新世界”を思い描いていた。ドイツで生まれ育った佐伯にとっては、日本こそが新世界。人と音を重ねて表現していく難しさと喜びを高校で初めて知った青野にとっては、オーケストラこそ新世界だ。全員の音が一体となって、海幕高校オーケストラ部の新世界への旅は始まる。', '2023/10/11 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/156d8980-d89d-4fee-9c35-d41990a89288.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('de281134-83d3-4508-a8c1-dd7d99db1616', '87b73030-9ab5-4787-9a97-be1c8cbc1afa', 'hulu-ao-no-orchestra-s2', 'Season2', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30f56777-6881-4873-9d43-985acffd210e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72f9c044-0921-4a95-bc62-fbb602e09312', 'de281134-83d3-4508-a8c1-dd7d99db1616', 1, '100239495', 'ほころび', '定期演奏会を終えた海幕高校オーケストラ部。青野たちは手応えをかみしめていた。次は全国コンクール。海幕オケ部は、2年生を中心とした新体制で、連覇を目指し始動する。しかし初日の朝練、ヴァイオリンの人数が思いのほか少ない。さらにパーカッションのセクションリーダー･佐久間が、新コンサートマスターの羽鳥そして弦楽器のメンバーを、辛辣な言葉で挑発する。戸惑う青野、立腹する佐伯と律子。新生オケ部、波乱の幕開け。', '2025/10/08 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30f56777-6881-4873-9d43-985acffd210e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a64f5bf-43f8-4f2d-86aa-15e63b0d84c3', 'de281134-83d3-4508-a8c1-dd7d99db1616', 2, '100240568', '波紋', '1stから異動して2ndヴァイオリンのパートリーダーになった滝本は、朝練を休み続けていた。パートをまとめる立場なのになぜ来ないのかと、ミーティングで佐久間たちに責められても、滝本はのらりくらりとかわし続け、理由を明かさなかった。ついには2ndメンバーの不満が爆発、滝本に詰め寄る。その様子を目撃してしまう青野。滝本は、意味ありげなことを言い捨て立ち去った。そして、滝本を心配する裾野からの思わぬ提案。', '2025/10/15 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f155a350-1856-45db-8ba2-fe7f784210ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11b12818-fae9-4849-a42b-f21856be82ff', 'de281134-83d3-4508-a8c1-dd7d99db1616', 3, '100240970', 'ケジメ', '下校途中の青野が思いがけず出会った滝本は、ひとり苦しげに泣いていた。先輩を気遣う青野に、滝本はとつとつと語り始める。辞めた部員をめぐる出来事、部活に意味を見つけられなくなった自分の、冷めた思いと迷い。それは、かつて父との関係をめぐって一度はヴァイオリンを手放した、青野の気持ちと重なるものだった。弾くことをやめていた頃の苦しみと、その頃とは違う父への今の思いを語る青野。青野の言葉に、滝本は決意する。', '2025/10/22 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6341ea87-1cf5-4125-b520-7f579212e8ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ac9377d-67df-4de3-bae3-992572e34aff', 'de281134-83d3-4508-a8c1-dd7d99db1616', 4, '100241523', '体育祭', 'コンクールまで2か月。弦楽器がコンサートマスターの羽鳥を中心にまとまり始めた頃、体育祭がやってきた。部活対抗リレーの選手となった律子の全力で楽しもうとする姿勢に、運動や行事が苦手な青野も感化されるが、クラスで騎馬戦の大将に選ばれてしまう。おじけづく青野に、同じく騎馬戦に出場することになった佐伯は対抗意識を燃やす。違う組の青野をつい応援してしまうハルは、ずっと気になっていた問いを、青野に投げかける。', '2025/10/29 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/630fd4ce-be14-4783-b516-afb64bbf48d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a7d7a88-4477-4979-970f-4ed8bb174e2d', 'de281134-83d3-4508-a8c1-dd7d99db1616', 5, '100242471', '課題', 'コンクールまで1か月。演奏メンバー全体での曲の解釈が定まらないまま、3つのグループに分かれてのブロック練習が始まり、青野は佐久間と同じグループになってしまう。敵対関係の中での男女の愛憎を描く、サン=サーンスの歌劇『サムソンとデリラ』より「バッカナール」。優雅さと妖しさ、怒りと悲しみ、嘘と秘密。青野と別のグループになったハルは、青野への自分の気持ちを知る3年生の先輩･町井との対話から、何かをつかむ。', '2025/11/05 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e42115c-d36d-43b0-9c67-116bb0055107.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37535150-d014-40b2-97e2-3d52ffbadb5d', 'de281134-83d3-4508-a8c1-dd7d99db1616', 6, '100243689', '後悔と一歩', 'ブロック練習で律子と同じグループになった立花は、主体的に行動しようとしない部員たちにいらだっていた。立花が、同じ中学出身の先輩である佐久間を何かと意識していると、律子は感じる。立花は律子に、コンクール金賞常連だった中学の管弦楽部で佐久間から部長を引き継いだこと、自身の熱意と責任感が結果に届かなかった苦い経験と後悔を語る。2人で音を合わせる立花と律子。佐久間は、離れた場所でティンパニーを叩いていた。', '2025/11/12 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76ab31c6-2c4c-4b33-be2f-33e24fbc96b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('850c40af-a53c-4a69-84b2-4c3107ea237d', 'de281134-83d3-4508-a8c1-dd7d99db1616', 7, '100244286', '怒り', 'コンクールまであと10日。風邪で休んでいる青野に佐伯が電話で練習の様子を伝える。鮎川先生は『バッカナール』の主題である“怒り”についてしっかり話し合えと指摘したが、その後の反省会ではリーダー以外に発言する部員はおらず、佐久間も黙っていたらしい。翌日登校した青野は佐久間と怒りについて会話し、「もっと自分の怒りに向き合いなよ」と挑発される。青野の演奏だけでなく、ミーティングでの行動にも変化が起きる。', '2025/11/19 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9bae79bc-9184-41ae-9d54-c260e9666f2b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccbc3d2b-6be9-44f5-bddb-8c9d6510e221', 'de281134-83d3-4508-a8c1-dd7d99db1616', 8, '100245925', 'コンクール', 'コンクール当日。出番を待つ間、オケ部全体に静かな緊張感が漂っている。佐久間は日向が辞めてしまった日のことや立花をサポートできなかった後悔を、筒井は部長になると決断した日のことを振り返っていた。観客席では、元オケ部の3年生たちが強豪校の演奏に感嘆。連覇を心配する柴田や米沢を横目に、原田は羽鳥と交わした言葉を思い出していた。鮎川先生からの手厳しい激励を受け、各々の決意を胸に新生オケ部の宴がはじまる。', '2025/11/26 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2908c9e-20c2-4028-99cb-ee220478f4b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f458a8b-8058-4038-a5e6-2c41e7c47635', 'de281134-83d3-4508-a8c1-dd7d99db1616', 9, '100246272', 'バッカナール', 'コンクール9連覇をかけた演奏がいよいよはじまる。固唾をのんで見守る原田ら3年生。それぞれの想いを曲に乗せる部員たち。佐久間はこれまでの後悔の念を一打一打ティンパニにぶつけていく。青野は父親から逃げていた自身への怒りをヴァイオリンに込める。サムソンの怒りが全てを打ち壊したとき、万雷の拍手が新生オケ部に降り注ぐ。演奏後、期待と不安が入り混じりつつ結果を待つ青野ら部員たち。果たして最優秀賞を掴むのは―', '2025/12/03 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/822388e3-64e8-49bf-bffc-e0799e4ac177.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3e11ecd-c7f8-49b3-afc6-ebe5d00d7baa', 'de281134-83d3-4508-a8c1-dd7d99db1616', 10, '100246702', 'らしさ', 'コンクールが終わって部活のない休日、2人きりで出かける青野とハル。行き先は青野が幼い頃から通う楽器店だ。互いを意識しぎこちない2人。メンテナンスのため楽器を預け、立ち寄ったフードコート。デートのような状況に浮かれるハルだが、話題はいつしか律子のことに。ハルは、自分が転校した後の中学で出会った青野と律子の関係を、ずっと気にしていた。ネガティブ禁止と自分に言い聞かせるハル。その時、最悪の相手が現れる。', '2025/12/10 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0827a7fe-6a1d-467b-b7bd-79ac14884862.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79b557f6-1fe8-4fb7-9a8e-913b66f8c208', 'de281134-83d3-4508-a8c1-dd7d99db1616', 11, '100247518', 'プレゼント', '頼みがあると、律子に呼び出された青野。母が好きな、バッハの「2つのヴァイオリンのための協奏曲」の演奏を、誕生日にプレゼントしたいのだという。中学の頃のように、律子は青野に勉強を教え、青野は律子にヴァイオリンを教える。誕生日当日、青野は、初めて訪れた女子の部屋にドキドキ。律子の母は、初めて会う青野に興味津々だ。演奏を始める2人。ヴァイオリンの音は、律子と母2人の関係にとって、特別な意味を持っていた。', '2025/12/17 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b7c1048-723a-4a82-aa97-e36f54a9d209.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93dfdaf9-ac00-4da0-bb34-2a429953da2d', 'de281134-83d3-4508-a8c1-dd7d99db1616', 12, '100248126', '合唱', '青野、律子、ハル。ゆれる気持ちに戸惑いながら、いつもどおりに振る舞う3人。青野は、律子とハルに勉強を教えてもらい、期末テストを終える。オーケストラ部の次の出番は、合唱部と合同で開催するクリスマスコンサートだ。オーケストラの演奏とともに合唱部員が歌うだけでなく、一部の曲ではオケ部員たちも合唱に参加する。人前で歌う恥ずかしさもあり、慣れない歌に苦戦する青野。そこに、堂々とした歌声が響く。その声の主は?', '2025/12/24 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5d4b854-a810-4e27-a75d-358cfc76d371.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5f03f15-7e42-46fc-a61d-c32f313f6f77', 'de281134-83d3-4508-a8c1-dd7d99db1616', 13, '100248910', '朝霧', '早朝、登校する佐伯。朝焼けの空、冷たい空気。静かな冬の朝、イヤホンから流れる「アヴェ･マリア」の歌声が、幼い頃のドイツでの、母との記憶を呼び起こす。毎日、子守歌のように聴いていた、声楽家である母の歌声。母に聴いてもらいたくてヴァイオリンを練習していた気持ち。鮎川先生は、いつかは忘れてしまう記憶もやがては血肉になると語る。何かをつかんだ佐伯は、故郷ドイツを思わせる寒さの中、青野と2人で音を合わせる。', '2026/01/07 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d023a0c-14f6-422f-82e3-c06a18a32ccb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b1d6221-1324-488a-ab66-aa94b04c360b', 'de281134-83d3-4508-a8c1-dd7d99db1616', 14, '100250263', 'クリスマスコンサート', '合唱部と合同でのクリスマスコンサートは、オーケストラ部員たちも歌う「もろびとこぞりて」で幕を開けた。荘厳なパイプオルガンとともに響き渡る歌声。律子の母は、全身を震わせる音に圧倒される。青野の母も来ていた。続く「アヴェ･マリア」。演奏するうちに、佐伯は、母との暖かい思い出に包まれていく。壮大な「ハレルヤ･コーラス」。青野の胸には、確かな手応えが残された。終演後、冷たい雨はいつしか雪へと変わっていた。', '2026/01/14 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d81ff56-8d08-4729-b934-5253758ce8a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a66dd675-c252-465b-ace4-e86431f23538', 'de281134-83d3-4508-a8c1-dd7d99db1616', 15, '100250783', '新しい景色', '1月1日は青野の誕生日。青野の新しい1年は、律子、ハル、佐伯、山田との初詣から始まった。そして冬休み明け最初の部活。鮎川先生から、学生オケ各国代表が競う「世界ジュニアオーケストラコンクール」の開催と、参加者募集が発表される。オーディションを受け代表メンバーに選ばれれば、同世代トップの奏者たちとともに演奏することができるが、時期が近い定期演奏会には一部しか参加できなくなる。青野たちそれぞれの決断は?', '2026/01/21 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0dda45ad-b0b5-4739-8dc4-9ac925c094ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48638835-f9c0-48e1-b069-3271d7cfd0ce', 'de281134-83d3-4508-a8c1-dd7d99db1616', 16, '100251517', '巌虎玄六', 'オーディションを突破し、ジュニアオケのメンバーとなった青野たち。しかし、合格者の多くは音大付属高校の生徒だった。仮の座席順でコンサートマスターの席に座ったのは昴雪人。青野は、その実力に圧倒される。そして、世界的な指揮者･巌虎玄六による厳しい指導が始まった。理想の音を追求する巌虎の威圧的な言葉は、生徒たちを涙させる。指導の方向性は的確だが、やり方が気に入らない。佐伯は、巌虎に正面から不満をぶつける。', '2026/01/28 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e81dfb4-a993-42d3-84e4-db7e900e7525.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d72d820-d1be-4e23-a521-692fe6e3eb70', 'de281134-83d3-4508-a8c1-dd7d99db1616', 17, '100252492', '偉大な父', '巌虎の全身からほとばしる熱が音を導く。青野たちは厳しい指導に必死で食らいついていた。曲は芥川也寸志「交響管弦楽のための音楽」だ。昴から不意に投げかけられた、「天才の父親を持つってどんな気分?」という問い。世界的ヴァイオリニストである父･青野龍仁。芥川も、父･芥川龍之介の存在に苦しんだかもしれない。今の自分がやるべきなのはヴァイオリンを弾くこと。父への複雑な想いを語る中で、青野は決意を新たにする。', '2026/02/04 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a966fafa-eb99-4c63-afac-229e85310ac1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35d1bd50-498c-4354-a86f-f363361388c7', 'de281134-83d3-4508-a8c1-dd7d99db1616', 18, '100252964', 'それぞれの兆し', '校内でチョコレートが飛び交うバレンタイン。オーケストラ部員たちも浮かれていた。青野は、机の中に忍ばされたチョコを発見して動揺する。さらに、皆にチョコを配っていたという律子からはもらえていないことに気づいてしまった。ジュニアオケの練習では、座席順のオーディションに向けて、皆のモチベーションと集中力が高まる。指導者の目を引く意外な成長を見せる者もあった。練習の帰り、青野とハルは同じ電車に乗り合わせる。', '2026/02/11 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d6e7707-1504-4e08-9d8f-3dec9c335571.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c18a0bb-dd2e-4421-ab68-99bc77a15614', 'de281134-83d3-4508-a8c1-dd7d99db1616', 19, '100253264', '本性', '日本代表としてコンクールに挑むジュニアオケのメンバーは、音楽の道に進むという強い意志を持つ者ばかり。中でもコンサートマスター席に座る昴雪人の、すべてを音楽に注いできたであろう存在感に、青野は圧倒されていた。そんな青野に、ホームである海幕オケ部のコンマス･羽鳥はエールを送る。そして、座席順を入れ替えるためのオーディションが始まる。演奏を心から楽しむ佐伯。昴は、内面の渇きや希望を音として解放していく。', '2026/02/18 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d000e1f5-cb8f-4611-8d6a-52d1dbbcdc9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b74ebfe6-6dc8-4eb8-bc4a-ad9696380c1e', 'de281134-83d3-4508-a8c1-dd7d99db1616', 20, '100253822', '超える', '2人1組で行われるオーディションは青野とハルの番となった。高度にシンクロする2人の演奏は審査員たちを驚かせる。そこには青野の明確な役割意識があった。ソロパートに入ると、細やかな演奏から打って変わって気迫のこもった音を響かせるハル。そして青野。世界的ヴァイオリニストである父のもとで音楽と出会い、コンクールで活躍した自分。過去を克服し、自分のやり方で父を超える。青野の演奏には強い決意が込められていた。', '2026/02/25 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84420bab-0beb-4414-a97e-cef525fd8cc9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40aaed34-0d55-4c7c-8b0f-0cc4f23c69c3', 'de281134-83d3-4508-a8c1-dd7d99db1616', 21, '100254517', '卒業', '【シーズン2 最終話】桜咲く春3月は旅立ちの季節。卒業式での演奏とオーケストラ部の卒業パーティー。つかの間の語らいの中で、去る者たちと送り出す者たちの思いが交錯する。時に激しくぶつかり合うことで手にしたそれぞれの成長、作り上げた音。青野は佐伯に、オーケストラ部に入ってほんとうによかったと語る。別れの曲は、パッヘルベルの「カノン」。ひとつひとつの音が重なり合い、旋律がリレーされていく。青春の音が、未来に向けて響き合う―。', '2026/03/04 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53192295-e6af-4f35-8a51-b44a18ebdd0e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3f5f5d79-5c42-470e-84be-2d226bc2a64c', '青のミブロ', '', 'hulu', 'blue-miburo', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5be33813-cda1-4e77-b6b0-a1d2c13701a9.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 169258, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0033530a-78c8-4911-8454-1b5bae0977c7', '3f5f5d79-5c42-470e-84be-2d226bc2a64c', 'hulu-blue-miburo-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7254872-ef65-45be-a8e9-28f8ea8cd086.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1a18c98-4e4f-4e96-8c71-5e4970587850', '0033530a-78c8-4911-8454-1b5bae0977c7', 1, '100202744', '壬生浪と少年', '黒船の来航により、動乱が巻き起こる幕末の京都。団子屋で働く心優しい少年「ちりぬ にお」は、のちに新選組となる「壬生 (みぶ) 浪士組 (ろうしぐみ)」、通称“ミブロ”の土方歳三、沖田総司と出会う。金も土地も命すら理不尽に奪われる時代。自らの正義を胸に、京の街を守る“ミブロ”の面々との出会いをきっかけに、ふつうの13歳の運命が、大きく動き出す! 命懸けの“ド青春”新選組、開幕!', '2024/10/23 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7254872-ef65-45be-a8e9-28f8ea8cd086.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7c89dff-da9a-4540-b9a0-673b10e03724', '0033530a-78c8-4911-8454-1b5bae0977c7', 2, '100203420', '泣いていい世界', '「僕だって強くなりたい。こんな世界変えたい」。土方歳三、沖田総司と出会ったことがきっかけで、京の街を守る剣客集団「壬生浪士組」、通称“ミブロ”の一員となったにお。皆と寝食をともにする屯所が「鬼の棲み家」と呼ばれ恐れられていることを知り、「ひょっとしたら、僕は危険なところに来たのかもしれない」と感じていた。永倉新八、原田左之助らと顔を合わせると、「力を見せろ」といきなり相撲で勝負することになり……!?', '2024/10/30 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa089d19-36f4-44dd-ade8-6ddefa6f75e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46b122c0-989e-47ed-9766-3c0cf27dba2d', '0033530a-78c8-4911-8454-1b5bae0977c7', 3, '100204136', '魂の在り処', '京の街を守る剣客集団「壬生浪士組」、通称“ミブロ”に加わって3日目の朝。ミブロの面々の顔と名前を覚えてきたにおだったが、田中太郎という見慣れない少年と対面する。におと同い年で、芹沢鴨に連れられてミブロに置いてもらっているという。ところが、なぜか土方歳三は「太郎にはあまり関わるな」とにおに告げる。そんな中、芹沢が酒に酔った勢いで仲間を斬ったことが判明。芹沢は、太郎に死体を始末するよう言いつけて……!?', '2024/11/06 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36c39bdf-09bb-4118-86c4-89f67a14c435.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('806fb940-ca9e-4c2e-a770-292f1bbd3e1f', '0033530a-78c8-4911-8454-1b5bae0977c7', 4, '100204889', '敵の名前', '朝の稽古中、斎藤はじめとの勝負に敗れてしまったにお。自分の無力さを痛感しつつも、だからこそ「そこにいたいなら姿勢で示す!」と近藤勇に稽古をつけてもらう決意をする。「及ばないならせめて汗をかく。誰にもできることをコツコツと!」その後、土方歳三、はじめとの市中の見廻りでは、子供を人質にとった男を発見する。下手に刺激しない方がいいと、はじめが冷静に分析するが、におは「その子を放せ!」と思わず叫び……!', '2024/11/13 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f45bb00-b7fc-4a38-b6f5-703dbc6dee30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27092aff-2643-4fd2-bf9c-39ae8151a5d4', '0033530a-78c8-4911-8454-1b5bae0977c7', 5, '100205357', '志は一つ', '「会津藩から正式にお預かりの話が出た」という芹沢鴨からの報告を受け、山南敬助は尊王攘夷の嵐吹き荒れる京の街で、「命を懸けて戦う覚悟はあるか」とミブロ一同に問う。「本当に“死ぬ覚悟”があるだろうか?」におが自問するなか、隊士たちは次々と覚悟を語り決意を新たにする。「我ら壬生浪士組。京の街を守る。志は一つ!」訪れた会津藩でミブロは、暗殺者の対処を命じられる。一方、におは世都という少年に出会い……。', '2024/11/20 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9c240e1-97e7-4fc0-afc6-cc3ffd0e6d6e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8609507b-c749-4d2f-bb84-5103f1cd4f96', '0033530a-78c8-4911-8454-1b5bae0977c7', 6, '100206669', 'それぞれの正義', 'におとはじめの前に、暗殺者の木村寿太郎が現れた! はじめと寿太郎が一触即発の中、二人の間に入ったにおは話し合うことを提案する。子供らしからぬ強さをもつはじめに、勇気も知恵もあるにお。そんな二人に寿太郎は、「君らはだまされているのだ」と異国を排除すべき理由を語り始める。国の未来を想う熱き志と覚悟に触れたにおだったが……。さらにそこへ、暗殺者の京四郎もあらわれて……!?', '2024/11/27 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fe25916-e175-4d3f-862c-b902de369b49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5eaecd62-e89d-45b2-b0a3-fba37d5b44ad', '0033530a-78c8-4911-8454-1b5bae0977c7', 7, '100207455', '矜持', '鶴屋に向かったにおは、単刀直入に世都を問いただす。暗殺者･木村寿太郎に、自分たちの居場所を教えたのは世都ではないかと。ところが世都は、自分ではないと反論し……。そんな中、暗殺者たちが出入りしている宿をつかんだミブロ一同。女将から部屋の中で刃物を振り回さないようお願いされる中、向かった部屋にはある老人が――。近藤は、老人と茶を酌み交わそうとするが、果たしてその真意は……!?', '2024/12/04 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d789aa74-8fc8-40e0-a4b8-60dbd69475f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4cc723d-01f1-4c82-a9da-613b50c5b404', '0033530a-78c8-4911-8454-1b5bae0977c7', 8, '100208577', '掌', '会津藩を襲う暗殺者「五匹の悪魔」最後の一人、宗助は必死に走っていた。仲間の一人が殺され、他の仲間は誰も約束の場所に現れない。「まさか全員捕まったのか?」と焦り、一刻も早く京の街から逃れようとしていた。そんな宗助をミブロは追い詰める! 近藤の挑発をきっかけに、におと勝負することになった宗助。「僕が勝ったらあなたはおとなしく捕まる。あなたが勝ったらこのまま逃げるのを見逃す」におの提案に、宗助は――。', '2024/12/11 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7da2fbec-c1b3-4f29-bffc-42eb2124f79e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d8b67c6-3e23-4037-b55c-0c40eed3e5bf', '0033530a-78c8-4911-8454-1b5bae0977c7', 9, '100209751', '宝', 'ミブロで大酒飲み大会が開催され、ついに土方と芹沢の一騎打ちに! その中で芹沢が発した“故郷に縛られるな”という言葉を受け、におは“なぜ自分が京の街を好きなのか”を考え込んでしまう。翌日。隊服にする揃いの羽織を作るため、におたちは婆ちゃんの団子屋へ。婆ちゃんの故郷への思いを聞くことで、自分が京を好きな理由に気づかされ、更に思いを強くする。そして、ここで人生における重大な人物と出会うことになり…。', '2024/12/18 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebbadbc7-9e75-41cd-86aa-7c3805e7b56c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('697121d1-b691-464c-a099-4d300e0f4acf', '0033530a-78c8-4911-8454-1b5bae0977c7', 10, '100210599', '最弱の将軍', 'ちりぬ屋に謎の少年･菊千代がやってきた。無性に腹が減っていると言い、店にある全種類の団子を注文。ところが金はないと言うなどただならぬ様子。そんな中、店に入ってきた怪しげな大男。菊千代は、今すぐ店から離れるよう、におに伝える。すると、大男は異様に長い刀を店の中で振るおうとしていた! におたちは大男に立ち向かうが……。菊千代との出会いをきっかけに、ミブロの新たな戦いの幕が上がる!', '2024/12/25 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ba2f8c8-6234-4d3a-aadd-c737650f28f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66ca7a83-012b-46a5-87a7-50f013fc4cf4', '0033530a-78c8-4911-8454-1b5bae0977c7', 11, '100211136', '真の強さ', '菊千代こと徳川家茂将軍を刺客から守りつつ二条城へ送り届けることになったミブロ。三組に分かれ、囮作戦を実行。におたちが城に着くまでの時間を稼いでいた。直純から逃げるにおと菊千代は、二条城の近くでついに菊千代の部下と合流できたものの、彼らは追いかけてきた直純に斬られてしまう…。「首をもらうぞ、家茂」迫りくる直純と対峙し、におは菊千代に逃げるよう呼びかけるが、菊千代は「なぜこのようなことをする?」と直純に問いかける。', '2025/01/01 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9de6c25e-e2a9-46ac-869d-c810b630d921.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecaa3557-27e1-4c02-83e1-23dffb7ad3d0', '0033530a-78c8-4911-8454-1b5bae0977c7', 12, '100211792', '八つの頭', '辛くも菊千代を逃がし、決死の覚悟で直純に食らいつくにお。しかし、自分だけ逃げることはできないと、菊千代は戻ってきてしまう。絶体絶命の状況の中、姿を現したのは土方だった!「上様を二条城まで送って差し上げろ」土方の言葉に、におは菊千代と城へ急ぐ! 一方、久しぶりの“手応えのある男”の登場に、思わず笑みを浮かべる直純。「貴様にとって武とは何だ!?」と土方に問いかけるが、土方からは思いもよらぬ答えが…!?', '2025/01/08 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/197db8f9-2e12-498f-b4a1-b00ec770402f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('992b21f2-d52d-4b8e-b7e7-b838c1c4ee98', '0033530a-78c8-4911-8454-1b5bae0977c7', 13, '100212383', '同じ夢を描いて', '二条城まで菊千代を守り通したにおだったが、直純との戦いで傷つき気絶してしまう。夜中に目覚めたにおは「攘夷」を訴える声が、城の中まで聞こえてくる実情を目にする。翌朝、その様子を菊千代に伝えると、「攘夷決行は決まっている」と驚きの真実を告げられる。「まるで人の力ではどうにもならぬ時代という川に流されておるようじゃ」そう漏らす菊千代は、「ミブロを辞めて、我の下で働かぬか」とにおに提案し…!?', '2025/01/15 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05cc6d39-ded6-4a76-8205-043cd8af12a8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cdc31e6-0c6e-48d3-8335-782fa6bfc824', '0033530a-78c8-4911-8454-1b5bae0977c7', 14, '100213953', '金策奔走', 'におは京の町の人々へ安心を与えるための「しるし」として、ミブロとしての揃いの羽織を作ることを発案する。しかし、そのためにかかる費用は250両! 隊士たちは金を稼ぐため町に繰り出す。にお達も仕事を探しに出かけるが、はじめは「お前らはついてくんな」と、一人でどこかに行ってしまう。その頃、土方は「いい刀がある。あんたにぜひ振ってもらいたい」という女に出会い、“日本一の刀鍛冶師”という刀匠の元へ案内される。', '2025/01/22 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f4ea138-3068-4428-b395-3aca593c156c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc19d1bc-596f-4f02-8aeb-10a477d0f48b', '0033530a-78c8-4911-8454-1b5bae0977c7', 15, '100213954', '川の流れのように', '金策のため、汚れ仕事を扱う「蛇」の店を訪れたはじめ。「次郎。いや、今は二代目斎藤一だったかい。その名前で呼ばれる気分はどうだい?」そう問う蛇は、問答の中で刀に手をかけるはじめを見て、「初代には程遠い」とあしらう。“仕事”の話になり、「どいつを殺るんだい?」と問われたはじめの回答は…? 一方、におと太郎は、身重の女性ナギとその夫、陽太郎と出会う。この出会いはにおの人生に大きな影響を与えることとなる…。', '2025/01/29 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9faaff2c-3539-41bb-bf44-e61536881bb2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9fc245d3-3467-4655-89ea-2251e76e4768', '0033530a-78c8-4911-8454-1b5bae0977c7', 16, '100214571', '出陣', '近藤と、京八館当主の陽太郎が三本勝負をすることに。猛スピードで打ち込み、近藤を攻めていく陽太郎。その手数の多さに、におたちは驚くが、なんと近藤はすべての打ち込みを捌ききっていた。果たして、勝負の行方は? 陽太郎の道場を訪ねてから3日。におは、妊婦のナギのことが気になっていた。ところが、はじめから「あの女には肩入れしない方がいい」と言われてしまう。そんな中、“血の立志団”からミブロにある手紙が届き……!?', '2025/02/05 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ef5b0b1-4d79-4c09-b93b-4752c63e7327.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ef5e4a9-2d75-480f-9bbe-025b032b6978', '0033530a-78c8-4911-8454-1b5bae0977c7', 17, '100215418', '居場所', 'ミブロと“血の立志団”の戦いが始まった! 鴨川にかかる7つの橋を落とし、京の町を燃やそうと企む血の立志団。ミブロはそれを阻止すべく、別れて全ての橋に向かうことに。「おめでとう。大当たりだ」。におたちの前に現れたのは、直純だった! その場を芹沢に任せて駆け抜けるにおたちだが、さくらは直純の持つ刀を見て驚く。「あの重い刀を使える人がいるなんて…」それは太刀筋が見えにくく、新月の夜に最も力を発揮する黒刀だった!', '2025/02/12 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27a63e16-b2fb-4b28-9323-4a33fc8a909c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('803ed140-b5cb-4210-b411-9386bfb569d4', '0033530a-78c8-4911-8454-1b5bae0977c7', 18, '100216857', '土の人間', '原田、永倉の目の前で、夜叉に背後から刺され、猟犬が倒れた。なぜ仲間の猟犬を斬る必要があったのか、と指摘する永倉に、夜叉は「弱いから死ぬ。強い者が生き残る、それこそ武士の論理」と宣言。永倉は「ならば貴様はここで死ぬ。それが真理」と夜叉に告げて――。その頃、四条大橋では、土方が扇動と向き合っていた。自分たちと共に歩むか、無名の人生を終えるか。運命を決める橋にようこそ、と笑う扇動に、土方は……?', '2025/02/19 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ee991c4-5f54-4505-93f9-df786c11ac36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c53a9ef2-3fb9-4bb8-a458-61de5c597688', '0033530a-78c8-4911-8454-1b5bae0977c7', 19, '100218068', '継承者', '「気に入った。特にその殺気満々の闘志がいい」。彩芽から立志団に誘われるも、断るはじめ。彩芽の“妙な自信”に嫌な予感がしていた。以前、向き合ったときにも感じた違和感だが、なかなか思い出せない。彩芽が左手を使わないことに気づいたはじめは、小型の暗器を仕込んでいると考え、左手めがけて攻撃するが、反撃を受けてしまう。「お前は弱い…」薄れゆく意識の中、はじめは、“次郎”と呼ばれていた自身の過去を思い出す。', '2025/02/26 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26b44579-5cd0-4325-ae6a-c784db55961f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85bdd4d0-a199-46bd-95da-01dc243ffbcd', '0033530a-78c8-4911-8454-1b5bae0977c7', 20, '100218564', '覚悟の上', '陽太郎と近藤が対峙。におは説得を試みるが、陽太郎には届かない。「力で止めるしかあるまい」。ついに、近藤と陽太郎の戦いが始まった! 陽太郎を近藤に任せたにおは、妊婦のナギと再会。陽太郎から全てを聞いていたナギは、「私はこの家に残る。これが私の覚悟と戦いです」と語る。さらに、自身が守れる範囲以外の被害は仕方ない、と言い切るナギに、説得をあきらめかけるにお。そんななか、ナギが産気づき、倒れてしまう…。', '2025/03/05 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97140bce-5e03-40d3-8057-680bc41d8888.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('355551c1-3a67-4fba-a9ed-e3785e925da7', '0033530a-78c8-4911-8454-1b5bae0977c7', 21, '100219530', '罪と幸', 'ナギのお産が始まる一方で、陽太郎は近藤との力の差を痛感していた。「たとえ勝てなくても…負けられない」。陽太郎は決死の覚悟で近藤に向かっていく。幼い頃、突然直純と共に過ごすことになった陽太郎。その日から武士としての特訓が始まった!「この家にいられるように」と愚直に剣を学んできた陽太郎。そんな中、突然直純との別れがやってくる。陽太郎と直純の知られざる過去が明かされる!', '2025/03/12 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbd0a1cc-f6bd-4a42-97c2-cb5d3b6cf623.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2ce4c1b-ca7b-4f31-9606-77c65f91581c', '0033530a-78c8-4911-8454-1b5bae0977c7', 22, '100220398', '抗う者たち', '火の手が上がる京八館を見て、芹沢は「町に火をかけるんじゃなかったのか?」と直純に聞く。武家に生まれることはある意味、呪い。“呪われた家を燃やす”という直純自身の望みに気づいた芹沢は、「武士らしく死に場所でも用意したか」と問いかける。その問いに「黙れ!」と返し、刀を振り下ろす直純。果たして二人の戦いの決着は? そして、時代という巨大な敵に抗い続けてきた直純と立志団の行く末とは?', '2025/03/19 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21360a04-258d-4ba5-b865-8aaa88476b3d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4ff23e2-ab2b-4600-b2a5-63dac608d47b', '0033530a-78c8-4911-8454-1b5bae0977c7', 23, '100221400', '繋がり', '「この世のどこにも血の繋がりはなかった」。生まれてすぐに両親を失ったナギは、親戚筋をたらい回しにされ、宿屋の下働きでなんとか食い繋いできた。唯一の楽しみは舟で届け物をする際に川を渡ること。いつも一人だったナギはある日、陽太郎と出会い、その運命が大きく変わることに。「残してやる、生きた証を!」という想いを胸に、ナギは婆ちゃんやにおの励ましを受け、必死に陣痛に耐えていく。ナギの想いは実を結ぶのか?', '2025/03/26 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90fcf774-f123-4b79-9180-444dbfee8389.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('309f42fb-aeca-44ab-86fb-6a039fa41ed9', '0033530a-78c8-4911-8454-1b5bae0977c7', 24, '100222075', '青の誓い', '【シーズン1 最終話】はじめに、三日間の護衛をしてもらうことになった姉小路。ミブロは鉄砲や大砲など用意することを検討した方がいいと助言。さらに、「いずれお主らの最大の敵になるかもしれぬな」と坂本龍馬の名前を挙げる。一方、ナギの死を知り倒れたにお。数日で熱は下がったものの、部屋から出ようとしない。「理想っていうやつのために走るしかねぇじゃねぇか、俺たちは」。太郎の言葉に、におが出した結論は? 血の立志団編、遂に完結!', '2025/04/02 18:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95bbdcf3-8e62-4f18-9ea1-9948f5255f8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('15d7143c-40af-419a-91b9-31d30d9917ff', '青のミブロ', '', 'hulu', 'blue-miburo-season-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b62c12c0-0f21-481e-beb9-51929868daf7.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 169258, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5f7eb796-918d-4834-9787-f62a1fcee9e5', '15d7143c-40af-419a-91b9-31d30d9917ff', 'hulu-blue-miburo-season-2-s1', '第2期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5326dc63-0658-4a16-b6b2-c5236b6590ee.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('821d518f-be37-481a-9d82-3323087ae53b', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 25, '100248235', '暴走乱闘', '京都で将軍警護の役目を終え、大阪にたどり着いたミブロ。メンバーたちが浮かれる中で、におと近藤は怪しい男を見つける。近藤が声をかけると男は逃げてしまった。男の名は山崎丞といい、実家がトラブルを抱えているという…。一方、太郎は、芹沢に連れられ意外な場所へ来ていた。芹沢の真意がわからず困惑する太郎だったが、ミブロでさらに頑張ろうと決意する。しかし、その帰り道でとんでもない事件に巻き込まれてしまう…。', '2025/12/20 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5326dc63-0658-4a16-b6b2-c5236b6590ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6459d1ea-08ed-47e3-8808-c12443cee094', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 26, '100249064', '人の道', '芹沢が力士を斬ったことで起こった大乱闘。暴走する芹沢を止めた近藤は、争いを収めるため、にお、山崎と共に奉行所へと向かうことに。にお達を追いかけてきた太郎は事件の真相を語り、さらに山崎からは奉行所の吟味役が、山崎の実家に取り立てをしていた内山彦次郎であることも明かされる。近藤は「芹沢先生を助けてくれ」という太郎の願いを叶えるべく、ある決断をして奉行所へと乗り込むが…。果たして、芹沢への沙汰はいかに?', '2025/12/27 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c974f02a-322b-4ee0-827e-d6348185f70e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2c40dd4-bfb1-43d8-a4a5-2f00ac413513', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 27, '100250219', '一匹の羊', '無駄な争いを避けるため、隊士を大幅に増やしミブロをさらに強く大きくするというにおの提案が受け入れられた。新隊士を募集すると、会場に列ができるほど志願者が集まる。荒くれ物や曲者も多いなか、意外にも土方は「今日ここに来た者は全員合格だ」と告げる。果たしてその真意は!? そんな中、におたちは長州藩の大物･桂小五郎と出会う。異国と戦争中の長州の重要人物がなぜ京の街に? そして桂の目にミブロはどう映ったのか!?', '2026/01/10 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57666061-e51b-4a30-8396-925977c345c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6f12483-eb15-4dbb-a38b-54c0293129b0', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 28, '100250754', '悪名', '組織の拡大とともに近藤派と芹沢派の対立が激化。事態を収束させるべく、土方は、誰がミブロの長にふさわしいか投票するという案を決行する。拮抗した状況の中、ミブロの長に選ばれたのは…。そんな中、はじめは坂本龍馬との邂逅を果たす。日本を変えるためなら自分の意思も感情も必要ないと語る龍馬を、自分たちの世を壊しかねない危険な存在と感じ、はじめは刀に手をかけるが…', '2026/01/17 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/046fe772-940e-46bf-bc85-5db788112bf9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9a8f3d9f-c3d0-483f-ba3b-9191007df716', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 29, '100251468', '蛍の光', '「我らは史上最強の集団である。それを忘れるな!」と説く芹沢の姿を見て、覚悟を決めた太郎は「自分にもお役に立てる仕事をください」と申し出る。すると芹沢は「お前がにおに飲ませろ」と太郎に“毒”を渡してきた。果たして太郎はどうするのか…。さらにある日、ミブロがお世話になっている八木家では、幼い子供、お菊が夜になっても帰ってこず、ミブロ総出で捜索することに。', '2026/01/24 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84ec6d1c-e44d-403b-af92-a0aecd1cba96.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('483f26c9-9801-463c-bc20-ecbc0c4438b2', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 30, '100252099', '不協和音', '夜の見回り中、土方は一人の少女と出会う。泣きながら「生きている意味がない」と言い、死のうとする少女に「生きてほしい」と説得する土方。力の強い者が笑い、弱い者が泣く世の現状を痛感した土方は、自分が守るべきものを再確認する。そんな中、大和屋で火事が発生。土方たちが現場に向かうと、衝撃の光景が広がっていた…。', '2026/01/31 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/113e6d7a-b965-40c8-8cf7-ebcc05ba740a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('837d773e-dc49-47ce-9efa-3841ed287c86', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 31, '100252866', '最強の二人', '御所で危急の動きがあり、会津から御所内警備の任務を命じられたミブロ。におたちは急ぎ御所へ向かうが、門番との諍いが起きて立ち往生。現状を治めるべく、近藤は出直しを決断するが、そこに“あの男”が駆けつけ門番たちを一喝。その圧倒的な存在感も相まって、一瞬でその場を治めることに成功する。そんな中、新見から呼び出された山南。新見は「芹沢に幕を引かせる」と山南に告げる。果たしてその真意とは…?', '2026/02/07 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec536bbd-96dc-48ce-9469-b14b2d47200e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b068c083-9e61-4dfe-9dd2-0be6c991da54', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 32, '100253175', '近くて遠い', '新見が自害したという知らせを受けたにおたち。現場の料亭へ向かうと、店主から、芹沢とみられる白い羽織の大男が、掃除代などを支払ったうえで返り血を浴びたまま悠々と引き上げていったという話を聞く。そんななか、近藤は芹沢を殺すことを土方ら一部のミブロ隊士に宣言。最終的に土方主導のもと暗殺が決行されることに。一方、はじめに任務が与えられた。それは、最期まで芹沢に尽くすつもりの太郎を救うことだった。', '2026/02/14 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/febc3713-bc84-4192-a5c2-baeab1590761.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffb9d6e5-c026-4f95-b81b-2d42239682a1', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 33, '100253855', '修羅の道', '運命の日。宴が始まり、隊士らが盛り上がる一方、芹沢暗殺に向けて動く土方たちは緊張感を高めていた。一方、暗殺計画を知らないが何かが起こると予期しているにお、太郎を救う任を背負ったはじめ、芹沢の隣に最期まで立つと決めた太郎、三人は己の信念に従い、それぞれが行動を開始する。そして、ついに芹沢暗殺計画が始まる! 果たして土方らの思惑通りに暗殺は果たせるのか?', '2026/02/21 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a637a7a-8f68-4316-97e8-05ead784d378.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0580e670-ee67-46e3-a087-1abfb2c8ecad', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 34, '100254789', '土俵', '「通すわけにはいかねぇ」。最期まで芹沢に付き従う覚悟の太郎を止めるべく、はじめが立ちはだかる。降りしきる雨の中、はじめが鋭い目を向けると、太郎は決意の表情となり刀を抜く! 一方、土方、沖田、原田、山南は暗殺の最終段階に向け動き出す。芹沢のいる奥の間へ、二手に分かれて向かうが、沖田が不審な位置にある明かりを発見する。土方の判断で、そのまま踏み込む一行だが…。果たして、芹沢暗殺の結末は!?', '2026/02/28 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a17d70c0-2a18-4cc3-a6a1-900e8eafd29a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63991b0b-acbd-4ded-9bcf-dc7f402010a9', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 35, '100255605', '不細工な一刀', 'これ以上、長くはかけられない上、犠牲者も出せない。自分たちが置かれた状況を判断して勝負をかけることを決意した沖田。二刀を手にし、芹沢に向け「我々は無傷で完遂します」と宣言する。それを受けた芹沢は不愉快そうに「この芹沢も、ナメられたものよ」とつぶやき、緊迫した空気が張り詰める…。そんななか、芹沢が一気に沖田に襲い掛かる! 沖田と芹沢、ともにミブロの中でも随一の剣の腕を持つ二人の戦いの結末は…!?', '2026/03/07 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9486ac0-508e-485e-b50b-5d897a79bf08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b17094d8-9ccf-4e39-b04c-d5918ef4f8dd', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 36, '100256546', '芹沢鴨', '土方と沖田の前から、重傷を負ったはずの芹沢が忽然と姿を消した。それは、におの手引きによるものだった。「まさか…わしを逃がそうとしているのか!?」におの行動に屈辱を感じる芹沢だが、ふと脳裏に浮かんだのは、不器用に微笑む太郎の姿。太郎のことを考えるうちに、生きたい、という気持ちが芽生える芹沢。そんななか、におに案内された場所には、芹沢が待ち望んでいた“あの人物”が立っていた…。', '2026/03/14 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c16686c-a18c-45e5-b61c-4e9a46b61f01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c929e850-4fe1-4686-9993-e64750a18c0f', '5f7eb796-918d-4834-9787-f62a1fcee9e5', 37, '100256775', '青の時代', 'ついに実現した芹沢と近藤の一騎打ち。命を燃やし尽くすがごとく戦う芹沢の姿を見て、におはその生き様を心に刻む。傷だらけの芹沢との、一見無駄にも見える一騎打ちに黙って付き合う近藤の姿に、芹沢は改めて、近藤こそが自分が唯一認める天下の武士であると確信。ミブロのすべてを任せると宣言する。一方、別の場所では、太郎とはじめの戦いもついに決着が。泣き崩れる太郎に対し、はじめは、ある言葉を投げかける。', '2026/03/21 18:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e00fda7c-63e0-4b5b-94ee-21e22c72f767.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('fc3ed810-daff-44d7-9195-b5773f3b59e5', '青の祓魔師', '', 'hulu', 'blue-exorcist', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50003338_series_art__338x600_blue_exorcist_14ac0236122460fb2473170aabc5d0c1.jpg?w=331&h=447&p=t', 'hulu', 2011, 1, 1, 'FINISHED', NULL, 9919, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9aff3e75-c195-47e2-9388-e77dd980e9df', 'fc3ed810-daff-44d7-9195-b5773f3b59e5', 'hulu-blue-exorcist-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8a7a7d2d-9607-4bdb-a293-436034f38700.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5da9ad8e-6db4-43b2-a614-046bcd91adf8', '9aff3e75-c195-47e2-9388-e77dd980e9df', 1, '60837027', '悪魔は人の心に棲む', '修道院で暮らす15歳の少年、奥村燐は双子の弟、雪男が名門高校の正十字学園への進学を決める一方、進路が決まらない自分に焦りを募らせていた。養父の獅郎に送り出されてバイトの面接に向かった燐は、店内で暴れる悪魔の姿を発見! 騒動を起こしてしまう。そんな中、落ち込む燐のもとに、喧嘩相手の白鳥が仕返しに訪れる。悪魔のような形相で襲い掛かる白鳥の脅威に、燐は…!!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8a7a7d2d-9607-4bdb-a293-436034f38700.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29546af6-312b-473c-a81b-e64f727fe40b', '9aff3e75-c195-47e2-9388-e77dd980e9df', 2, '60837002', '虚無界の門 (ゲヘナゲート)', '獅郎に自分が魔神の落胤であることを知らされ、燐はひどく混乱! しかし燐の動揺など構わず、激しく襲い掛かってくる悪魔たち。獅郎に「決して抜いてはならない」と降魔剣を渡され、修道院地下室に隠される燐。外では、巨大な悪魔と化した白鳥と祓魔師たちとの熾烈な戦いが展開される! そして何とか戦いを終えた獅郎に、燐は怒りを向け「父親ぶるな」と激昂。その言葉に衝撃を受けた獅郎は…。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/81ad7fe1-b26f-4225-b5f8-1439f77718b8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6172841e-e011-4348-abbc-c7499770fbeb', '9aff3e75-c195-47e2-9388-e77dd980e9df', 3, '60836961', '兄と弟', '祓魔師への道を決意した燐は獅郎の友人と名乗る謎の男、メフィストに連れられて、雪男と共に正十字学園へ入学。要塞のように巨大な校舎、雪男の主席入学…と、燐にとって新たな環境は驚きの連続であった! その後、燐は「魔神の落胤であることは秘密」とメフィストに厳しく釘を刺されつつ、祓魔師の養成所、祓魔塾へ向かう。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6ed0b355-e5a3-4841-9ddc-ace538c20271.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7807bf5-5300-4b69-aea6-a85513615c9b', '9aff3e75-c195-47e2-9388-e77dd980e9df', 4, '60837026', '天空 (アマハラ) の庭', '任務を受けた雪男に同行し、燐は祓魔師の用品店、祓魔屋へ向かう。そこで燐は、庭の草木を世話する足の不自由な少女、しえみと出会う。しえみが世話する庭は、亡き祖母から受け継いだ大切なものらしい。その時雪男が現れ、しえみの足を診察。彼女の足に悪魔の痕跡を発見し、雪男は庭が原因と推察する。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c684be56-b5e0-4c9f-baea-62323408649a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e24cbe1d-b2c4-472f-aceb-e0681bde3eef', '9aff3e75-c195-47e2-9388-e77dd980e9df', 5, '60836982', '祟り寺の子', '祓魔塾の授業では、居眠りをしてばかりの燐。そんな燐の不真面目な態度を見て、努力家の優等生、勝呂は苛立ってばかり。祓魔師になって京都の実家の寺を再興しようとする彼にとって、意識の低い燐が同じ境遇にいることが我慢ならないのだ。短気で喧嘩っ早い、ある意味似たもの同士の燐と勝呂は、当然ながらことあるごとに衝突してしまう!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f139682f-a164-412a-a1fb-4171c4d71a9f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3f6a4af-a8b7-492e-9f05-6e64da361077', '9aff3e75-c195-47e2-9388-e77dd980e9df', 6, '60836976', 'まぼろしの料理人', '学園生活を送る燐の目下の最大の悩み、それは毎日の食生活! メフィストから支給される生活費は、なぜか二千円札たった一枚!? これでは、セレブ御用達で高額な学食メニューなど手が届かない。燐は雪男の助言で寮の厨房を使い、自炊生活を始めることに。しかし夜に下ごしらえした料理が、朝になると消えているという事件が発生!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a80dfb0f-df21-4769-bf50-fc21df788223.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('345cf3b8-ef6a-48ba-bcad-992f29750417', '9aff3e75-c195-47e2-9388-e77dd980e9df', 7, '60836962', '友千鳥 (ともちどり)', '人見知りを克服するため、密かに「友達を作る!」と決心を固めるしえみ。さっそく出雲に声をかけようとするが、ドジな性格が災いして、なかなか上手くいかない。その後、授業で手騎士の才能を見せたしえみは、同じく手騎士志望の出雲に友達になって欲しいと告白! しかししえみを小馬鹿にする出雲は、適当にあしらって彼女をパシリにしてしまった。そんな中、燐たちの寮で祓魔塾の合宿が行われる。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bd2ccbfa-b915-4963-a542-f125b2d7081a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea935c77-a8b6-48e7-8ee9-7b69e086da4e', '9aff3e75-c195-47e2-9388-e77dd980e9df', 8, '60836996', '此 (ここ) に病める者あり', '親友の朴を助けられずに落ち込む出雲は、イラ立ちのあまり勝呂と衝突! 二人の喧嘩は燐たちも巻き込み、結局、塾生そろっての反省会になってしまう。下級悪魔を膝に乗せ、長時間の正座に耐える燐たち。その最中、突如部屋の電気が消え、先日燐が撃退した悪魔･屍 (グール) が襲い掛かってきた!!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f55eff8e-f3ce-4a94-9d16-b85893e63be3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac77b0b6-8c2d-4bc2-8fe9-f55d6b1e2ed5', '9aff3e75-c195-47e2-9388-e77dd980e9df', 9, '60837034', 'おもひで', '仲間との共闘で辛うじて苦難を乗り越えた燐たち。その場に突如、メフィストや塾の講師たちが登場し…!!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/dd4997c4-584c-4502-9d20-9d546e4bea0a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62855ac5-1088-4694-b703-ce2243422f0f', '9aff3e75-c195-47e2-9388-e77dd980e9df', 10, '60837040', '黒猫 (ケットシー)', '仲間と共に候補生 (エクスワイア) に昇格できたものの、大量の課題を前に、燐はすでにうんざり気味。そんな中、雪男に緊急の祓魔任務が入る! 騎士団の使い魔が凶暴化してしまい、その対処が命ぜられたのである。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/647b1e6a-6d12-4051-a292-a48664e91dd2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c801c42-7dfb-403b-990a-d7e1dcbc74eb', '9aff3e75-c195-47e2-9388-e77dd980e9df', 11, '60836968', '深海の悪魔', '夏の海岸へ出張を命じられた燐、志摩、出雲は、なぜか海の家で働くことに…。そこで彼らは地元の少年、洋平と出会い、「海の悪魔」という怪物の存在を聞かされる。しかも洋平は「海の悪魔」の襲撃で父親を奪われたことで、怪物への復讐まで計画しているらしい。悪魔に関わろうとする洋平を案じた燐たちは、彼の行動を見守ることを決める。そんな矢先、海に異変が発生!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/af5e47c9-6de8-4701-8911-fe7d0b954fe5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3fc75334-18de-4f1a-93fb-ae2ac9a0d018', '9aff3e75-c195-47e2-9388-e77dd980e9df', 12, '60837019', '鬼事 (おにごっこ)', '今回の燐たちの任務は、遊園地で目撃された幽霊 (ゴースト) の捜索。燐はしえみとコンビで行動することになり、デート気分で落ち着かない様子だ。やがて二人は子供の幽霊を発見するが、幽霊は二人をからかって逃げるばかりで、いつしか事態は鬼ごっこへと展開してしまう。そしてしえみとはぐれた燐の前に、地の王アマイモンと名乗る悪魔が登場!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cf99d08e-542a-4036-a82d-87c2b94f5e7b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb9b8dea-e7d3-417e-bd48-2b8ec0d1d77c', '9aff3e75-c195-47e2-9388-e77dd980e9df', 13, '60836959', '証明', '燐とアマイモンの戦いを制止した上一級祓魔師、霧隠シュラ。彼女はヴァチカン本部より派遣された監査役で、塾生に紛れ込み騎士團を内偵していたのだ。地下基地へと連行された燐は、シュラが獅郎の弟子だったことを知り、さらには「師匠の不始末をつける」と排除対象と認識されてしまった。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f3dcdd97-d96f-4328-aa09-93c2d8f8e07d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('825608b8-a761-4785-b517-d718c6920806', '9aff3e75-c195-47e2-9388-e77dd980e9df', 14, '60836995', '愉しいキャンプ', '一学期の授業が終了し、正十字学園は夏休みに突入。しかし燐たち祓魔師候補生 (エクスワイア) には、林間合宿という名目での三日間の実戦訓練が課せられることになった。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c117879f-3eab-443d-9efc-ee8f65fe6827.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd5f28d0-1902-4567-965e-a92563d5f73c', '9aff3e75-c195-47e2-9388-e77dd980e9df', 15, '60836985', 'やさしい事', '勝呂が提案した共同作戦が功を奏し、実戦訓練は成功目前! しかし巨大な蛾の悪魔･虫豸 (チューチ) が出現し、油断した燐に襲い掛かった!!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9701836d-fd54-402b-8fea-204b8ff47076.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ac43b2f-003a-4f29-9965-48d2ee9b935d', '9aff3e75-c195-47e2-9388-e77dd980e9df', 16, '60836981', '賭', 'アマイモンとの戦いで炎の力に飲み込まれ、凶暴化してしまう燐! 力を使い果たして暴走は収まるが、燐はその場で現･聖騎士 (パラディン) のエンジェルに捕らえられてしまった!!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0b3efc76-c299-4fde-8e47-6219fe08151d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24863a94-5702-4f70-a56b-ab5ad4d62908', '9aff3e75-c195-47e2-9388-e77dd980e9df', 17, '60837003', '誘惑', '長引く懲戒審問の中、騎士團は燐の処分を決めかねていた。メフィストが燐を「魔神に対抗し得る武器」と主張したためである。そこにある異変が…!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/80a0711b-9b82-4405-a9e4-2bb85645a2f3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07c4e103-46c6-4f64-85a3-560488fbfcd7', '9aff3e75-c195-47e2-9388-e77dd980e9df', 18, '60837016', '颶風 (グフウ)', '魔神の炎を使いこなすべく修行中の燐。そこに巨大な怪鳥の悪魔･颶風が現れた! 雪男の助けで撃退したものの、颶風の進入経路を洗い出すため、祓魔塾メンバーは調査に借り出されることに…。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ece13941-6288-40cf-8e7c-8e28a762c931.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2513c0f4-9bc2-44f3-a2e9-c78e1686e052', '9aff3e75-c195-47e2-9388-e77dd980e9df', 19, '60837023', 'なんでもない日', '志摩の誕生日占いで盛り上がる祓魔塾メンバーたち。その際、出雲の誕生日が近いことを知った一同は、彼女に内緒でサプライズパーティーを開くことを思いつく!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/51aa2a98-81a1-4900-8cf1-1b8836f437de.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('602ad77d-d1b7-41ce-9523-edf858301ff5', '9aff3e75-c195-47e2-9388-e77dd980e9df', 20, '60836986', '假面 (カメン)', '燐と雪男の育った大切な場所、南十字男子修道院が謎の襲撃者に襲われた! 仮面を被った襲撃者は、「魔神に関わる者は許さぬ」と謎めいた言葉を残して去っていくが…。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b12ef823-dbd7-4501-8726-45716c0d80ed.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0485dc9-9c68-469a-89fb-38f778d6507a', '9aff3e75-c195-47e2-9388-e77dd980e9df', 21, '60837046', '秘密の花園', '襲撃者を取り逃がしたものの、修道院襲撃事件は一段落。その時、雪男の前にある人物が現れる!', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/18c70175-5400-40da-a02d-422a9261e7bb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1547d03-02c9-4e0f-a653-4596fbea52d2', '9aff3e75-c195-47e2-9388-e77dd980e9df', 22, '60836987', '悪魔狩り', '修道院襲撃からの一連の事件を受け、理事長を解任されるメフィスト。さらには騎士團最高位の三賢者 (グリゴリ) も更迭され、エルンストが教皇に就任することに。そして新たに日本支部長として現れたのは…。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9812f671-6575-45ad-bdc5-a1a561dab8a9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb759768-f749-49ba-880b-bc18c50514a8', '9aff3e75-c195-47e2-9388-e77dd980e9df', 23, '60836979', '真実', '魔神の息子である燐の血を使い、虚無界への門であるゲヘナゲートを出現させようと目論むエルンスト。傷ついた兄を守るため、雪男は身代わりを申し出る。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3b3674d4-69e0-42d0-b662-2416947fcd39.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74a0b5f1-fff5-43fb-8d2f-b167d33ecd96', '9aff3e75-c195-47e2-9388-e77dd980e9df', 24, '60836999', '魔神の落胤 (サタンのこ)', 'ゲヘナゲートから膨大な数の悪魔が出現! 虚無界より侵攻してきた悪魔は正十字学園町の人々に無差別で襲い掛かってきた! その頃学園最上部では、燐が勝呂としえみに助け起こされていた。目覚めた燐が見たものは…。', '2021/03/25 00:00:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/be654973-3241-45b4-a07e-da11c2ae7802.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a21adc97-b8f3-49d7-a9cb-18f8c19db9ec', '9aff3e75-c195-47e2-9388-e77dd980e9df', 25, '60837043', '時よ止まれ', '【シーズン1 最終話】巨大なゲヘナゲートと化した魔神は、次元の裂け目を広げて物質界を飲み込もうとする。燐と雪男は合流したシュラ、エンジェルらと共にゲートに立ち向かうが、圧倒的な強さを前に苦戦を続ける。一方で学園の祓魔師たちも、無数の悪魔に追い詰められつつあった。', '2021/03/25 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a97d7421-207b-4933-86a1-595265277791.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('63ebb3ba-e644-47ba-9748-b22b1b46c6e3', '青の祓魔師 京都不浄王篇', '', 'hulu', 'blue-exorcist-kyoto-saga', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3449d8d9-7759-4dc0-98d7-0816474d9ed3.jpg?w=331&h=447&p=t', 'hulu', 2017, 0, 1, 'FINISHED', NULL, 21861, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e0b826f5-f851-49ff-8351-7b89b348e61f', '63ebb3ba-e644-47ba-9748-b22b1b46c6e3', 'hulu-blue-exorcist-kyoto-saga-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c012705-6afe-4bb0-b36f-0ce6929419df.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('34b25fe1-b9ba-4a95-9a0c-417b8b2b1ce6', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 1, '100018801', '嚆矢濫觴 (こうしらんしょう)', 'アマイモンの襲撃により魔神の落胤である事が露見した奥村燐は、祓魔対象として正十字騎士團の監視下に置かれることとなり、監視役である霧隠シュラの指導のもと、魔神から継いだ「青い炎」を操るための修業をしていた。そんな中、シュラのもとへ学園最深部に封印されていた「不浄王の左目」が何者かに盗まれたとの連絡が入る。現場に駆け付けた燐たちは、犯人を追跡するが…。', '2021/03/25 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c012705-6afe-4bb0-b36f-0ce6929419df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b32f659-87c0-4302-9b73-737b46f72d6d', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 2, '100018802', '呉越同舟 (ごえつどうしゅう)', '「不浄王の右目」を守る京都出張所へ増援部隊として派遣された燐たちが案内された逗留先は、勝呂竜士の実家である旅館だった。襲撃に耐えたものの、多くの被害を受けた明陀宗。そして、そんな状況でも姿を現さない明陀宗の現頭首である父に、勝呂は複雑な思いを募らせる。一方、塾生たちとの溝が埋められないままの燐。そんな燐に声をかけてきたのは、勝呂の父･達磨だった。', '2021/03/25 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c494cc2-d1b0-4eb7-a706-396bec2f9be9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47dbc00f-880c-4c79-97d5-b2c4fd100971', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 3, '100018803', '疑心暗鬼 (ぎしんあんき)', '父への憤りが日々増していく勝呂。明陀宗のことを案じる三輪子猫丸は、魔神の落胤である燐を恐れ拒絶する。また、杜山しえみも友人である燐の出生を知り、動揺を隠せずにいた。各々が惑い悩む中、志摩八百造の招集により明陀宗の当主総会が開かれる。それは右目襲撃における内通者を探すための詮議の場だった。謎の多い達磨の行動に、明陀宗の面々は疑心を抱きはじめ…。', '2021/03/25 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db3dd0c0-5855-4d93-874b-c80a0765de3c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd60ca37-9145-45a5-a866-06cbf5af6563', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 4, '100018804', '背信棄義 (はいしんきぎ)', '明陀宗を裏切っている者は誰なのか。頭首不在のまま紛糾した総会は、結論が出ないまま中断された。父のもとを訪ねすべてを問い質そうと決意した勝呂は、人目を避けるように京都出張所深部へと向かう志摩柔造の姿を目撃する。不審に思った勝呂は後を追うことにするが…。そして燐もまた、シュラとともに深部へ向かうことに。そこで彼らを襲った騒動、対峙した事態とは―。', '2021/03/25 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9497d9d-35bb-4131-b98d-66001161e264.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eaa9033e-ed92-44f1-8856-a5cf56a0a023', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 5, '100018805', '合縁奇縁 (あいえんきえん)', '藤堂三郎太と宝生蝮の共謀により、「不浄王の右目」が奪われてしまった。京都出張所には別働隊の奥村雪男たちも到着し、奪われた右目と左目を取り戻すための会議が開かれる。一方、勝呂と衝突し、大勢の前で青い炎を出してしまった燐は、独房に捕らえられてしまう。燐の正体を知り動揺する祓魔師たち。その騒ぎに紛れて、シュラは達磨から燐に宛てた手紙を託されていた。', '2021/03/25 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8022114d-8eb5-4590-a64f-327001678180.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9034922-2441-485e-9874-e800e20783ff', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 6, '100018806', '綿裏包針 (めんりほうしん)', '降魔剣「倶利伽羅」をめぐる燐･雪男の養父である藤本獅郎と達磨の出会い。明陀宗の本尊として祀られていた降魔剣が燐の手に渡るまでの経緯が手紙によって明かされていく。そして、寺の本尊を手放した達磨に疑念を抱き、明陀宗を救おうと右目を奪い逃走した蝮は、藤堂とともに向かった明陀宗の元拠点･降魔堂で、連綿と受け継がれてきた不浄王の秘密を知ることになり…。', '2021/03/25 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ab3855c-b8ee-4cc1-add3-4d89cf4144ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d392b996-3e65-4893-8ab2-127c5effc5a6', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 7, '100018807', '気炎万丈 (きえんばんじょう)', '藤堂の策略により、遂に復活を果たした不浄王。達磨から使い魔･伽樓羅を奪った藤堂は更なる力を手に入れる。達磨の願いを託された燐だったが、己の悪魔の力と向き合う中で降魔剣を抜くことができなくなっていた。狼狽する燐に追い打ちをかけるように、突如現れたメフィストから燐の処刑決定が告げられる。不浄王の復活、燐の処刑を知った勝呂たちが取った行動は…。', '2021/03/25 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2040b5af-c76b-4291-9189-d005edb7ed03.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('721c684d-1267-4fc7-b8ca-0ec2db1a77d7', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 8, '100018808', '父子相伝 (ふしそうでん)', '不浄王の瘴気が街中に降り注ぐ。不浄王に対抗するため行動を始める祓魔師たち。仲間の想いを知った燐もまた、独房を脱し洛北･金剛深山に向かい、山中で倒れた達磨を発見する。一方、燐が独房を出たことを知らずにいる雪男は藤堂と遭遇。圧倒的な力を前に苦戦を強いられる雪男を甚振るように攻撃をつづける藤堂は、燐のことを話題に上げ雪男の心理に揺さぶりをかける。', '2021/03/25 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d031939e-c8de-4d7b-86ef-f59febef5f40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29c60d1f-21bf-476f-9a7f-8dde845cd9f0', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 9, '100018809', '雪中松柏 (せっちゅうしょうはく)', '本当は兄のことが嫌いなのではないか。心の奥を暴くように問いかけてくる藤堂の言葉に雪男は激しく動揺する。幼い頃から抱えてきた自身の思いに向き合う雪男。達磨から打倒不浄王の切り札･劫波焔を受け継ぎ、胞子嚢を目指して進む勝呂と燐。救援を呼ぶため山を駆ける志摩と子猫丸。達磨を守るしえみと神木出雲。それぞれが不安を抱え、目の前の事態に立ち向かっていた。', '2021/03/25 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ed0781b-db34-4cfb-b141-6e8e4b27aaa7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('231e6327-07a2-4f21-824a-7579a2f23634', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 10, '100018810', '不撓不屈 (ふとうふくつ)', '遂に胞子嚢が破裂し、全貌を露わにした不浄王。瘴気の暴風に襲われる中で、勝呂は結界を維持しようと懸命に耐え忍ぶ。しかし、限界は刻刻と近づいていた。自分が助けられた意味は何なのか。窮地に立たされても未だ抜けずにいる降魔剣を手に燐は問う。一方、間一髪のところを柔造に救われた雪男。藤堂に対し怒りが頂点に達する柔造に、雪男はある作戦を持ちかけ…。', '2021/03/25 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64336a6c-8603-4d5d-8032-5d9599bd49b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7db62e4c-84e9-4c37-b3a9-ce08ea00266f', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 11, '100018811', '光輝燦然 (こうきさんぜん)', '降魔剣を抜くことができた燐。「自分の居場所は自分で勝ち取れ」と、シュラは燐を送り出す。だが、圧倒的な力を持ち増殖をつづける不浄王を食い止める術は見つけられない。遂には勝呂の体力も尽き、結界が崩れてしまう。街に瘴気が到達すれば甚大な被害をもたらす。絶望的な状況の中、燐の前に烏枢沙摩が現れる。そして倒したはずの藤堂が、再び雪男の前に立ちはだかり―。', '2021/03/25 00:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ebf6aeb-e567-4049-a2de-9a339da76b5a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08b762f3-caf9-4faa-875a-0ece913e142f', 'e0b826f5-f851-49ff-8351-7b89b348e61f', 12, '100018812', '虚心坦懐 (きょしんたんかい)', '【シーズン2 最終話】青い炎が不浄王の瘴気を浄化する―。青い炎が夜空を焼き尽くす光景は「青い夜」を彷彿とさせつつも、まったく違う結果をもたらした。不浄王に纏わる事件によってさまざまに揺れ動いた人々は、騒動が解決したことで新たな局面を迎える。燐が魔神の落胤であり、それでも祓魔師を目指すということ。燐と雪男にも、兄弟にとって逃れられない事実に向き合う時間が訪れ…。', '2021/03/25 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4c81087-0ba8-459c-8220-4007f99174e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8efdc53f-74a1-43fa-bcb7-45346d5ec9a0', '青の祓魔師 京都不浄王篇', '', 'hulu', 'blue-exorcist-oad-kyoto-saga-snake-and-venom-spy-game', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/684bc203-0f2f-4c16-aad1-0e5b5097844b.jpg?w=331&h=447&p=t', 'hulu', 2017, 0, 1, 'FINISHED', NULL, 21861, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c703b25e-bb86-459e-947d-35df7c6d4e04', '8efdc53f-74a1-43fa-bcb7-45346d5ec9a0', 'hulu-blue-exorcist-oad-kyoto-saga-snake-and-venom-spy-game-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9185e61c-071f-4235-b281-fdddae899081.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23e4c2cf-4901-4eef-8342-ac3adbc1947e', 'c703b25e-bb86-459e-947d-35df7c6d4e04', 13, '100207530', '蛇と毒 (へび と どく)', '志摩家とともに明陀宗の門徒をまとめる僧正血統･宝生家の長女である蝮は、正十字学園に入学するも周囲になじめず、自身とは対照的に学園生活を送る幼馴染み･志摩柔造に苦々しい思いを抱いていた。ある日、祓魔塾講師･藤堂三郎太から塾生である蝮と柔造に課題が与えられる。懸命に課題に打ち込む二人だが、それはのちに「不浄王」を巡る事件へと繋がることになり――。', '2024/12/27 00:00:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9185e61c-071f-4235-b281-fdddae899081.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('251e0b92-1f65-452d-8eb2-e71ae5fd3997', 'c703b25e-bb86-459e-947d-35df7c6d4e04', 14, '100207531', 'スパイ･ゲーム', 'スパイとして啓明結社イルミナティに潜入することになった志摩廉造。正十字学園に入学した彼は、学園の理事長であり祓魔塾の塾長でもあるメフィストに、三つのミッションを言い渡される。それは過酷で非情なスパイ養成訓練で……?! スパイは何事にも揺るがない強い心を持たなければならない。強靭な精神と揺るぎないスパイ技術を得るため、志摩の試練が人知れず始まる……!', '2024/12/27 00:00:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2bb2dab3-bbde-4897-acb4-5c3462554c8c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f807c433-0dae-4895-8bcd-3352f849c9ff', '青の祓魔師 終夜篇', '', 'hulu', 'blue-exorcist-yosuga-hen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9af5cd00-7df4-42b1-8d39-9b774809a671.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 185880, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0682ecae-107f-46d0-9fe3-1423956e2fab', 'f807c433-0dae-4895-8bcd-3352f849c9ff', 'hulu-blue-exorcist-yosuga-hen-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f51cd0c-72a3-47d6-b05d-dc7bd30a7048.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90fad6f9-d483-4b5d-b318-498bab60aece', '0682ecae-107f-46d0-9fe3-1423956e2fab', 1, '100212093', '獅郎とユリ', '人工虚無界の門が完全に開き、多くの人間が悪魔を見るようになったことで物質界は混乱に包まれていた。その中で、雪男は正十字騎士團から離反しイルミナティへ向かう。自分たちの出生の秘密を知る必要があると決意した燐は、メフィストの手引きで40年前の過去へと旅立つ。廃工場で暮らす孤児のユリと、十三號セクションの実験体である獅郎。2人の出会いを燐は目にする。', '2025/01/05 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f51cd0c-72a3-47d6-b05d-dc7bd30a7048.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af013cf5-6e9b-4bce-b6ae-e4be8ecaf26e', '0682ecae-107f-46d0-9fe3-1423956e2fab', 2, '100212696', '真実', '火事で家族を亡くし行き場を失ったユリは、十三號セクションから脱走中の獅郎と出会った。行方を追ってきた祓魔師たちに連れ戻された獅郎は、メフィストに対しある要求をする。一方、悪魔が見えることから、祓魔師養成学校･アサイラムに収容されることになったユリ。二人の成長を見守りながら、燐はアサイラムと十三號セクションの実態を目の当たりにすることになる。', '2025/01/12 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89dd7b28-3810-4548-bb7f-3211c9b4abed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42aed83b-681d-4121-a16f-679aeeba95d1', '0682ecae-107f-46d0-9fe3-1423956e2fab', 3, '100213655', '一人ぼっち', '悪魔を祓うことが祓魔師の責務だと考える獅郎と、人を助けることが祓魔師の責務であると考え、悪魔とも友好的な関係を築くことを唱えるユリ。ユリの姿勢に獅郎は苛立ち、対立する。時が経ち、祓魔師認定試験に合格した二人。獅郎は念願であったアサイラム外での一人暮らしを始め、自由を謳歌していた。その様子を心配そうに眺めるユリだったが、ある任務で二人は再び対立し……。', '2025/01/19 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa1a277b-1542-4ab7-bd4d-a6023ff6d771.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c7d999a-2aca-4e0c-96ef-b7478005b083', '0682ecae-107f-46d0-9fe3-1423956e2fab', 4, '100214297', 'サタン覚醒', '9年の月日が流れた。その時間は獅郎やユリ、リックたちにとって多くの経験を重ね、成長を促す日々だった。一方、十三號セクションではエリクサー実験が繰り返されていた。アマイモンが新たな憑依に成功するも、己に適した憑依体は未だ現れず、苦しみの中で物質への執着を強めていくルシフェル。だがそんな中、とある験体に「森羅万象そのもの」である存在が受肉し――。', '2025/01/26 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/453acee3-4195-431d-b198-9e8fd2ed4262.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('852afe61-47ee-49d3-9c6f-00d8ba2ddc99', '0682ecae-107f-46d0-9fe3-1423956e2fab', 5, '100214917', '身体より大事なもの', '受肉後、凄まじいスピードで知識を吸収していった燐火は、己の存在を魔神･サタンと認識した。力を行使し、全てを意のままにしようとするサタンに対し、ユリは説得を試みるが、サタンはそれを拒絶。十三號セクションから姿を消す。エリクサー無しに憑依体を維持することは困難であるため、朽ち果てるのは時間の問題と考える騎士團だったが、ユリはある決意を固めていた。', '2025/02/02 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2ae4255-4a87-4620-bba5-4f267a2e2fda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5c92c30f-c91f-4bdf-9d4f-7c62f2194057', '0682ecae-107f-46d0-9fe3-1423956e2fab', 6, '100216390', '俺さえいなければ', '十三號セクションに籠城するサタンのもとへ向かったユリ。ユリを受け入れ、ともに生きることを選んだサタンは、二人での暮らしを手に入れるため十三號セクションを捨てることを決意し、配下に撤退を宣言する。ユリは脱出の準備を進める中で、十三號セクションに勤務するジェニと再会。サタンとユリの脱出計画を知ったジェニは、施設にいる実験体の子供たちの解放を目論むが……。', '2025/02/09 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40740089-8544-4aec-a833-5960a76a3fdb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0f1e0c1-ff9a-468f-8d7b-01af01561d13', '0682ecae-107f-46d0-9fe3-1423956e2fab', 7, '100217217', '前夜', '生まれたばかりの燐は青い炎を纏い、周囲の祓魔師を次々と襲った。その光景に酷く動揺し、悪魔の人格に乗っ取られかけた燐を、メフィストは現代のとある場所に送る。一方、騎士團を離れた雪男は志摩とともにイルミナティの空中要塞「境界の主 (ドミナスリミニス)」に到着。幹部の藤堂誉に連れられ、ルシフェルと対面する。その頃、しえみのもとに賢座庁の者が訪ねてくる。', '2025/02/16 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f776bee-13a4-42b5-aa9b-d15e8181dda4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d1cb148-765c-4faa-85f5-3a96a06b28c7', '0682ecae-107f-46d0-9fe3-1423956e2fab', 8, '100218460', '青い夜', '突然目の前に現れた燐に元気をもらったしえみ。燐もまた、しえみの声に自身を取り戻し、全てを見届けるため再び過去へと向かった。過去ではサタンの憑依体の劣化が進行し、崩壊と暴走を始めていた。ついに始まる「青い夜」――。世界中の有力な聖職者たちが次々と青い炎に包まれる中、京都では明陀宗が、ヴァチカンでは三賢者が、日本支部では聖騎士や獅郎が事態に対抗する。', '2025/02/23 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2a0de45-6867-4ab5-b63a-d5a45acda955.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e817cc4-4681-40a0-b665-68a4582929dd', '0682ecae-107f-46d0-9fe3-1423956e2fab', 9, '100219056', '死闘', '獅郎は降魔剣を使い、燐の悪魔の心臓を封印することに成功した。それにより燐は悪魔の本性と切り離され、ユリの腕の中へと戻された。しかし安心したのも束の間、聖騎士･アベルの身体がサタンに強制憑依されてしまう。ユリへの思慕が妄執に変わったサタンにはユリの言葉も届かない。感情を爆発させ、獅郎の身体を奪おうと迫るサタン。獅郎は憑依を防ぐため、大胆な行動に出るが……。', '2025/03/02 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e1f2cec-713d-4c8f-9ba7-09e1100e604c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('848afe1f-966c-4fee-8d1e-e45ab5130001', '0682ecae-107f-46d0-9fe3-1423956e2fab', 10, '100220117', '光', 'サタンを退け、騎士團の手を逃れた獅郎とユリ。しかしユリの消耗は激しく、燐と雪男に最後の言葉を残しこの世を去った。自責の念に駆られ生きる気力をなくした獅郎に追い打ちをかけるように、悪魔が襲う。一方、物質界からサタンが消え、憑依体研究の未来に絶望したルシフェル。全てを無に帰さんとするルシフェルの暴走を、メフィストとシェミハザが阻止しようと試みる。', '2025/03/09 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8834a9f-6504-450f-924b-a800eb40f8c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36f95411-4595-40d9-8b53-4108cabca3fc', '0682ecae-107f-46d0-9fe3-1423956e2fab', 11, '100221063', '約束', '生きる気力を取り戻し、獅郎は燐と雪男を連れ日本支部へと帰還した。メフィストがサタンの仔を育てる計画を持っていると踏み、獅郎は双子を預けようとするが、メフィストはかつて交わした「約束」を突きつける。そしてメフィストは、憑依体を失い虚無界に戻ったサタンに対し、人間を害することを止めるよう交渉していた。しかしそこに力を取り戻したルシフェルが現れ……。', '2025/03/16 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/faa4dbd9-3e42-4694-82b8-f21750724a72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11d0a505-8b47-46d1-9cf6-046a4695cb8b', '0682ecae-107f-46d0-9fe3-1423956e2fab', 12, '100221803', 'ありがとう', '【最終話】かつてのユリの言葉を思い出し、三角や長友たちを頼り、修道院で燐と雪男を育てるようになった獅郎。悪魔を見て怯える雪男には祓魔師になる道を示し、自身の力を制御できずにいる燐には料理を教え、やさしいことのために力を使えと諭す。やがて二人は中学生になるが、サタンに狙われ続けていた獅郎は日増しにサタンの声を耳にするようになる。そして、運命の日が近づき……。', '2025/03/23 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/653bda8c-90d8-4a24-b96e-7cc2a2fdcc01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7bb24b49-4590-4221-89bc-709cdc07dd45', '青の祓魔師 雪ノ果篇', '', 'hulu', 'blue-exorcist-yukino-hate-hen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e5221a8-ebb1-4219-9d1a-fc92fe667e84.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 176311, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e41b58bd-67c0-4a88-b027-1b56b96e6ef7', '7bb24b49-4590-4221-89bc-709cdc07dd45', 'hulu-blue-exorcist-yukino-hate-hen-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7333962f-f5b6-4d87-9322-e7c1a172ddcb.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da16d422-39bd-4b1d-866a-53378142e1e5', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 1, '100201423', '野望', '島根において極東研究所を制圧することに成功したが、依然として大きな脅威であるイルミナティ。正十字騎士團は対抗策を講ずるべく上層部による議論を重ねていた。一方、燐たち塾生に、祓魔師認定試験の実施が早まることが告げられる。島根での出来事を機に、祓魔師になる理由を見失い悩む勝呂だったが、四大騎士･ライトニングが祓魔塾講師の助っ人として新たに赴任し……。', '2024/10/06 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7333962f-f5b6-4d87-9322-e7c1a172ddcb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c4f758b-8296-4938-83e3-43376eed168f', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 2, '100202595', '苦悩', '自らの目に異変が起きて以来、事実を周囲に隠し恐れを抱いてきた雪男だったが、その目に発現した力が一体何なのか、検証することを決意する。力が発現した状況には、「死を前にした恐怖」という共通点があった。雪男は、生死をかけた危険な修業に傾倒していく……。一方、燐としえみは二人きりでの任務に臨むことに。古民家に発生した魍魎を祓魔するという、簡単な任務に思われたが……。', '2024/10/13 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67405249-40e0-4a61-8b9c-34070a02e070.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33cee24b-0030-4a14-a22d-7824092ce2b6', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 3, '100203140', '故郷', '突如として姿を消したシュラ。行動履歴から、シュラが出身地である青森にいる可能性が高いと推測したメフィストは、燐と雪男に現地での捜索を命じる。二人は聞き込みの末、青森･永久蛇湖に辿り着くが……。シュラは、湖を中心に広い縄張りを持つ強力な八岐大蛇･八郎太郎大神と対峙していた。八郎は眷属の蛇たちとともに、シュラへ「俺たちとの約束を果たしてもらう」と迫る。', '2024/10/20 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1949fbd5-f52c-4698-a89a-567768f3598e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('464bac11-6ed6-45dc-8b72-f56c1d9795da', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 4, '100203862', 'さよならあなた', '八郎とシュラの先祖･霧隠辰子の契約により、力を得る代わりに先祖代々三十路に死ぬことが決まっている。シュラは、自身の背負う運命を燐と雪男に語った。未練は何もないと語るシュラだったが、納得できない燐は八郎を倒そうと提案。しかし、シュラが八郎に連れ去られてしまう。救出のため燐と雪男は八郎のもとに向かうが、そこには八郎の催眠能力によって操られたシュラがいた。', '2024/10/27 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25f38f97-da31-4d6a-b968-214bfc47c7e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69ce7c66-1808-4302-91f3-e4891000aff5', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 5, '100204401', '泣けとばかりに', '雪男の機転によって八郎を欺き、シュラとの契約を破棄させることに成功した燐たち。しかし、怒り狂い暴走した八郎は再びシュラを捕らえ、凍てついた湖へと向かっていく。不死である八郎からこぼれる「死にたい」という願いに、シュラは湖の底深く、永遠に一緒に眠ろうと伝え寄り添う。湖に沈んでいく中、シュラの脳裏に浮かんだのは、かつて藤本獅郎と過ごした日々の記憶だった。', '2024/11/03 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/296d25f9-433e-4ede-9972-5770397db4a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1efa9dcb-f607-4b91-a935-fde3a20838a4', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 6, '100205084', '啓蟄', '青森での一件が終わり、落ち着きを取り戻しつつある正十字騎士團日本支部。ライトニングは勝呂と共にイルミナティに関する調査を開始する。ライトニングはイルミナティ、そして「青い夜」に繋がる何かが日本支部内にあると睨んでいた。一方、燐からの告白を受けたしえみは「恋愛の好き」と「友達の好き」の違いが分からないと悩んでいた。その様子を見かねた出雲は、ある提案をする。', '2024/11/10 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9493736d-2b62-4669-bbfb-dc8d808d11d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c6ec41e-5945-4985-8731-43c35547da71', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 7, '100206202', '異形葉', '青い夜についての調査を進める中で、ライトニングはある三人の名前に着目する。青い夜以降に正十字騎士團日本支部から離職したその三人は修道士となり、南十字男子修道院――奥村兄弟が育った場所でともに暮らしていた。当時の話を直接聞くため、修道院を訪ねるライトニングと勝呂。口をつぐむ彼等に強硬な手段も厭わないライトニングは、徐々に青い夜の謎へと迫っていく……。', '2024/11/17 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7990ad04-dc8e-4e0a-823f-3197a4d868c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a64db45-c9f3-4ce0-92d8-3ea54f3665e8', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 8, '100207073', 'ハッピー (メリクリ) バースデー!', '青い夜直後の十三號セクションの姿を目の当たりにし、メフィストからそこで行われていた研究の真相を明かされたライトニングと勝呂。ライトニングは、正十字騎士團ヴァチカン本部のとある場所へ向かう。一方、手騎士を目指していたしえみが、突如として認定試験辞退と退塾の意思を示す。驚く燐や出雲たちをよそに、しえみはクリスマス兼誕生日パーティーに向けて意気込みを見せるのだった。', '2024/11/24 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a216de42-e3bd-4c70-b988-d44a9b7d5fba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c2c4a4e-d18c-4cfb-99f1-7d8217587198', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 9, '100207895', '寿', '自らの出生の秘密を知りたいという想いを募らせる雪男と、知る必要はないと考える燐。互いの考えがすれ違う中、燐たちは志摩柔造と宝生蝮の結婚式に参列するため京都へ向かう。周囲に対し通常通りの態度を見せる雪男だが、違和感をおぼえる燐。一方、調査を再開したライトニングは十三號セクションの真相に近づくため、当時の関係者として名前が浮上したドラク･ドラグレスクに接触する。', '2024/12/01 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71e5fc49-c5b8-4f8c-9a5c-ca5b7cf0b3e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce57bd00-1a51-471f-8c48-ef7940020ea6', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 10, '100209384', '散る雪の中で', '都市部に上級悪魔が出現し、対応に追われる祓魔師たち。池袋ではシュラが陣頭指揮をとっていた。魔障を受けたことにより悪魔を見ることができる人間も増えていき、世界は混乱に陥っていく。時を同じくして、勝呂を銃で脅し、ライトニングとの調査内容を聞き出そうとした雪男。志摩の忠告にも耳を傾けず孤立を深めていく雪男は、任務のため東京へ戻り、ライトニングと遭遇する。', '2024/12/08 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8ac0538-1474-46e1-890a-837ea2d0cfde.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bed09a0b-2597-468d-a93e-b4611c4ca3db', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 11, '100210085', '雪の果て', 'さまざまな感情に押し潰された雪男がとった手段を阻止したのは魔神だった。しえみから雪男のことを聞いた燐は、雪男を探すため寮を飛び出していく。そして、悪魔の動きが活性化したことにより混乱を極める物質界。首相官邸に招集されたメフィストは、内閣総理大臣･全人とともに、これまで公に認知されてこなかった悪魔の存在を公表する記者会見に臨むが、そこに現れたのは……。', '2024/12/15 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27db2d84-4f1b-426d-887b-913833e54cb4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6b33570-dec1-49bd-823b-d0b1f35ef8a2', 'e41b58bd-67c0-4a88-b027-1b56b96e6ef7', 12, '100211123', '決別', '【最終話】雪男がメフィストを銃撃した容疑で拘束された。雪男の目のことも知った燐は、兄弟で騎士團から逃亡する決意を固め、塾生やアマイモンの力も借りて雪男の救出に向かう。銃撃により大きなダメージを負ったメフィストは、憑依体を維持するため人工虚無界の門に施した結界を捨てる決断をする。それにより門は完全に開き、大量の悪魔が出現。物質界は虚無界の空気に覆いつくされていく……。', '2024/12/22 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/565e5138-ee43-46bd-adef-6ba9bd291ac1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5f792b29-64c3-4e22-901c-f1a599d1d1c7', '青の祓魔師 島根啓明結社篇', '', 'hulu', 'blue-exorcist-shimane-illuminati-hen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16901152-748f-4b2a-b83c-8db3dceae556.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 158931, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', '5f792b29-64c3-4e22-901c-f1a599d1d1c7', 'hulu-blue-exorcist-shimane-illuminati-hen-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9407891-b2b1-4400-8b1b-e15d39ecf137.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81b4e032-0d3f-4086-b3cb-57b7045ab818', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 1, '100171187', 'ざわめく世界', '魔神の落胤として生まれ、祓魔師を目指す少年･奥村燐は、悪魔が見えることに苦しむクラスメイト･醐醍院誠の相談に乗ることに。燐と同じく祓魔塾に通う候補生･勝呂竜士たちに悪魔を見えなくする方法を尋ねてみるも、解決方法は見つからない。そんな中、正十字学園の理事長であり、正十字騎士團の日本支部長であるメフィスト･フェレスに晩餐へと招かれるが……。', '2024/01/07 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9407891-b2b1-4400-8b1b-e15d39ecf137.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cf2a3b3-5e65-49d5-bb88-fe421784a40b', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 2, '100171902', '秘密の在り処', '燐の双子の弟で中一級祓魔師である奥村雪男は、正十字騎士團の上級会議に召集され、「不浄王」復活の首謀者である藤堂三郎太について聴取を受けていた。物々しい雰囲気に疑念を抱いた雪男は、亡き養父･藤本獅郎の言葉を思い出す。一方、候補生たちは「トイレの繭子さん」退治の任務に当たることになるが、神木出雲は杜山しえみに対し、あるわだかまりを持っていた。', '2024/01/14 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4049b76d-464a-40d2-ab1b-985fff448544.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('819f822c-3eb4-4e0e-bb8a-1c194d3df731', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 3, '100172637', '正十字学園祭', '学園祭の準備で賑わう正十字学園。志摩廉造と燐は、音楽フェスとダンスパーティーに参加するためパートナー探しに奔走するが、ことごとく断られてしまう。諦めきれない燐は出雲を誘おうとするも、年に一度の祓魔師認定試験が迫っていることを理由にすげなく断られる。すっかり意気消沈する志摩と燐の前に、学園の編入試験に合格し、同級生となったしえみが現れ……。', '2024/01/21 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a01f12d5-7ad8-4e0f-ae65-307c54e34daf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb12a5de-a2d7-4d3a-9857-47ef5237f608', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 4, '100173468', '内通者', 'アーサー･A･エンジェルとライトニングは、騎士團内に潜むスパイを捕らえ、啓明結社イルミナティがとある計画に必要とする人物の拉致を企てていることを知る。しかし、その実行時間は差し迫っていた。一報を聞いた霧隠シュラは、候補生たちを招集する。その頃、出雲は宝ねむと対峙していた。古びたマスコットを手にした宝に、怒りをあらわにした出雲だったが……。', '2024/01/28 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbb7cb90-4c51-463d-86f8-6e55ec10aea1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7c1278e-50c1-4575-b56b-c7ecc3314f5f', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 5, '100174224', '運命', '光の王･ルシフェルの宣戦布告により、正十字騎士團各支部は混乱に見舞われる。そんな中、雪男と燐たち候補生は、出雲と志摩を取り戻すため、出雲の故郷である島根県へと出発する。拉致された出雲はイルミナティの極東研究所に監禁されていた。目を覚ました出雲の前に、イルミナティの制服を身にまとった志摩が姿を現す。そして、そこには出雲に関わりの深い人物の姿もあった。', '2024/02/04 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a730302-581c-4750-afd4-6017f2066664.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76275098-f06a-4d6b-b629-5b290f764fd2', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 6, '100174965', 'もう誰も頼れない', '宝によって召喚された出雲の使い魔･ミケ狐神により、稲生の地と神木家にまつわる過去が語られる……。古くから続く巫女の血統で、九尾の狐を鎮めるつとめを負う神木家の当主･玉雲。その娘である出雲と月雲。巫女として強力な神通力を持ちながらも、私生活は頼りなく奔放な母と、幼い妹と過ごす出雲の日常は、ある日この土地に現れた「いなり光明財団」の活動によって狂い出していく。', '2024/02/11 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6776ffac-342c-44f4-a7ba-8d09c03e6c2a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1617f1e7-ae73-4d22-91b2-08d2e11ef7a6', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 7, '100175234', '迷い', '稲生観光都市化計画の裏で、イルミナティは徐々にこの地を蝕んでいった。ミケから出雲の過去を聞いた燐たちは、イルミナティの地下研究所の入口と思われる稲生へいわタウンへと向かう。一方、研究所では出雲が精密検査のために、外道院ミハエルの待つ部屋へと連行されていた。自ら騒ぎを起こした隙に、ウケ･ミケを召喚して脱走を試みる出雲。地上を目指して走るも、その行く手を志摩が阻む。', '2024/02/18 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa14d96d-29b0-41a6-b9eb-b4155642ea68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c105de12-48a9-4458-ab28-0fee5e611c70', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 8, '100175717', '覚悟', 'ルシフェルに心酔する外道院は、エリクサー研究の成果をあげようと更なる行動に出る。外道院の策略により、一人ひとり分断されてしまった燐たち。地下施設のコンテナで巨大な異形屍人と対峙することになるが、屍人が悪魔に寄生された人間だと知った燐は、刀を振るうことを躊躇してしまう。雪男、勝呂、しえみ、子猫丸もまた、独力での戦いに挑むことになり……。', '2024/02/25 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a850a43-e766-42b7-8435-9e1a88dd3eec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84bd02e1-d6e7-49d2-a510-cad395d59ae6', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 9, '100176567', '助けて', 'コンテナを破壊し、合流することができた燐たち。しかし、外道院が差し向けた肥大化した膨張屍人が襲いかかる。極東研究所をエリクサー実験の聖域だと語る外道院によって明かされる稲生へいわタウンの真実に憤る一同だったが、そこに九尾の移植手術に向かう出雲が現れる。出雲を助けるべく降魔剣を手に飛び出す燐。阻もうとする志摩を殴り飛ばし、出雲に手を差し伸べるが……。', '2024/03/03 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7bc6322d-6e6a-4685-bd57-2ce8e5e58b59.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a359fc8d-5c23-450e-8c6e-a62a91dbca38', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 10, '100177416', '仲間', '九尾を強制的に憑依させられ、圧倒的な力にさらされる中で振り絞った、助けを求める出雲の声に応え、膨張屍人を祓い、外道院の前に立ちはだかった燐。計算外の事態に混乱し焦りを滲ませた外道院は、時間稼ぎに大量の屍人を差し向けてくる。雪男たちも駆け付け応戦する一方で、出雲は従わせることも寄り添うこともできない九尾という狂気に飲み込まれようとしていた。', '2024/03/10 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd15e8c2-ee51-44a5-bacc-2d737ea407f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fba61665-9a2d-4a07-939f-0193f7db0179', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 11, '100178210', 'ピンクスパイダー', '玉雲によって救われ、イルミナティの脅威を押しのけることに成功した出雲たち。稲生の地は正十字騎士團による制圧がなされ、一連の騒動は落ち着いた。だが、志摩はイルミナティの一員として去ってしまった。京都出張所から応援に駆け付けた志摩の兄である柔造と金造に、志摩がイルミナティのスパイであったことを説明しようとする勝呂だったが、逆に柔造から驚くべき事実が明かされる。', '2024/03/17 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e9b7dba-06eb-4639-9259-d34c6dbcc614.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f634190-9bce-4947-9405-11428b013505', '6122e29e-8d3c-46fe-a85b-670fc9f8a4ee', 12, '100178585', '隠された本音', '【最終話】袂を分かったと思われた志摩の帰還。ライトニングによる尋問。ルシフェルと対抗するメフィストの思惑。さまざまに事態が動く中、イルミナティの地下施設でルシフェルと対面したことを隠していた雪男だが、志摩にはその事実を知られていた。志摩に「誰かに相談すべき」と忠告され、胸の内に不安を募らせていく。そんな折、メフィストの計らいで燐たちは慰労としてスパリゾートへ向かうことに。', '2024/03/24 01:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d32d34e5-39df-49bb-a3b7-e494213c6f1b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('519cbae1-fb4c-451d-b3a4-c1fa370b7adb', '青の祓魔師', '', 'hulu', 'blue-exorcist-oad-kuro-runs-away-from-home', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e359e8e-e133-456a-a559-d62ace1344e4.jpg?w=331&h=447&p=t', 'hulu', 2011, 1, 1, 'FINISHED', NULL, 9919, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('df9a673c-0fbd-4ffb-aed5-ed388cdb235e', '519cbae1-fb4c-451d-b3a4-c1fa370b7adb', 'hulu-blue-exorcist-oad-kuro-runs-away-from-home-s1', 'シーズン1', 1, NULL, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9a945182-a64d-4354-bec5-9e77e62911a0', '青春ブタ野郎はサンタクロースの夢を見ない', '', 'hulu', 'rascal-does-not-dream-of-santa-claus', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/392d24a7-1e46-4c85-bcc2-c770b942a52e.png?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 171046, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b004fe79-bf91-4cb4-bab9-f783639f6663', '9a945182-a64d-4354-bec5-9e77e62911a0', 'hulu-rascal-does-not-dream-of-santa-claus-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80adfc2f-a2f9-4afc-8fba-f8029780fad5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d85faa5e-c27b-4d5e-8fbb-fe3068af2998', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 1, '100231814', '思春期は終わらない', '大学に入学して半年。高校時代からの友人や恋人の桜島麻衣に加え、新たな出会いも得て、穏やかなキャンパスライフを過ごしていた梓川咲太。10月のある日、咲太は同じ大学に通う麻衣の妹、豊浜のどかから相談を受ける。所属するアイドルグループ･スイートバレットのリーダーである広川卯月のソロオファーが増えており、グループとしての今後を心配している様子ののどか。その翌日、授業にやってきた卯月の様子に、咲太は違和感を覚えて……。', '2025/07/08 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80adfc2f-a2f9-4afc-8fba-f8029780fad5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f8b8d4f5-cdfd-4ef8-872f-6113ca7d282b', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 2, '100232621', '空気の味は何の味?', '空気を読み、ファッションも女子学生たちに合わせ、グループに溶け込む卯月。普段と違う様子に、咲太は彼女の思春期症候群を疑う。話題のCMへの起用やバラエティ番組での活躍で、卯月の人気は高まっていく一方、ライブのリハーサルでは調子が出ず、メンバーに対しても心を閉ざしてしまう。そんな中、大学の最寄り駅で、電車から降りる素振りを見せない卯月を見かけた咲太。思わず隣の車両に飛び乗り、彼女を追いかけることに。', '2025/07/15 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9376302a-64ed-4191-8b5f-507a2c8ea516.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('edd77133-a79b-4511-a74b-02167714c8db', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 3, '100232979', 'アイドルソング', 'スイートバレットが出演する、お台場での合同ライブの日。不調を抱えたままの卯月を心配していた咲太は、麻衣と共にライブ会場を訪れる。スイートバレットのパフォーマンスの最中、卯月の声が聞こえなくなる。突然声が出なくなってしまったのだった。翌日、八景島でのライブに卯月抜きの4人で立つことになったスイートバレットだったが……。', '2025/07/22 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e40e3d2b-ee1e-4552-ae26-c155a99a347e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50e9d536-93f5-4185-b4ba-252227e6af9f', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 4, '100233373', '正義の味方', '突然咲太の前に現れたミニスカサンタ。“霧島透子”を名乗る彼女は、皆に思春期症候群をプレゼントして回っているのだという。そして、その視線の先には、咲太の中学時代のクラスメイトで、同じ大学の看護学科に通う赤城郁実がいた。郁実のことが気になっていたこともあり、友人に誘われた看護学科の女子生徒たちとの合コンに参加した咲太。その席で、SNSに書き込んだ夢が、次々と正夢になると噂の「#夢見る」の話を聞いて……。', '2025/07/29 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/995b9fc3-7520-4333-9376-6d0da410362d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7cf53e6-e97d-4f91-b2c7-1bf7a6fa2d14', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 5, '100233843', '不協和音', 'SNSに「#夢見る」で書きこまれていた通り、桜木町駅前の広場でガラスのランタンが落ちた。しかし駆けつけた郁実がランタンの真下にいる女の子を守り、怪我人は出なかった。彼女は「#夢見る」の書き込みを信じ、人助けをして回っていたのだ。大学で咲太に会いに来た郁実は、中学校の同窓会の招待状を差し出した。人助けもほどほどに、と忠告する咲太の言葉に背を向けた郁実は……。', '2025/08/05 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e489065-8c3f-45a7-8527-758c85f23c2e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f55d327-19c3-43a7-8912-0ab4e0e0492f', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 6, '100234487', '記憶領域の君と僕', 'ポルターガイストのような現象に襲われた郁実。思春期症候群かと心配する咲太に郁実は、これを治す方法は、郁実が咲太を忘れることだという。困惑する咲太に対し郁実は、咲太が「あの日」のことを思い出すのが先か、彼女が咲太のことを忘れるのが先か、という勝負を提案する。郁実の言葉の真意を考えていた咲太は、梓川花楓のアルバイトの様子を見に来ていたスクールカウンセラーの友部美和子から郁実の話を聞く。友部は、郁実が中学時代、咲太を救えなかったことを後悔して、今でも引きずっているのではないかと話した。', '2025/08/12 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a79f5dd1-2618-4961-8798-5d5af3f33718.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1821dd7e-cf26-46f3-bb89-01f8090541da', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 7, '100235260', 'ヒルベルト空間の彼方から', '「#夢見る」でSNSを検索すると、「11月27日に中学の同窓会に参加した」という夢の書き込みが数多く並んでいた。郁実も同窓会の日の夢を見ていたが、それは彼女が傷害事件を起こして警察に捕まるというものだった。咲太は郁実を峰ヶ原高校に誘い出し、これまで彼女に対して覚えていた数々の違和感を伝えた。その帰り道、鉄道の踏切を前にして郁実は突然咲太に別れを告げ――。', '2025/08/19 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3dfff68f-8eeb-4e00-9fea-589b9b8cbcfc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28fb8b61-4519-48a0-956c-749d243874c9', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 8, '100235323', '秘密と約束', '「霧島透子を探せ。麻衣さんが危ない」。郁実を通じてもうひとつの可能性の世界の咲太から届けられたメッセージを読んで、咲太は霧島透子を名乗るミニスカサンタに連絡を試みる。数日後、ミニスカサンタから12月2日であれば会ってもいいと電話を受ける。その日は麻衣の誕生日だった。不本意にも麻衣との誕生日デートをキャンセルし、透子と対面した咲太は、周囲から認識されていない透子の状況を思春期症候群ではないかと話し、彼女の様子を伺うが……。', '2025/08/26 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0ef5c8b-b6d6-4a49-a162-ac0757fa4312.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0afb75be-9a8f-49e5-a04b-50ddff762dfb', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 9, '100236332', 'I need you', '麻衣とのお泊りデートのはずのクリスマスイブに、アルバイト先の塾の生徒である姫路紗良とデートをするという夢を見た咲太。同じ夢を見た当の紗良は、自らが思春期症候群だと咲太に告げ、自分の思春期症候群を治さないでほしいと話した。紗良は失恋後に思春期症候群になったことで、抱えていた不安が解消され、“モテる”毎日が楽しいのだという。彼女を諭す咲太。すると、紗良は挑発するように尋ねる。「どうすれば、咲太せんせみたいに、人を好きになれますか?」', '2025/09/02 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/777747e8-7d15-4ff8-b759-58235bd28324.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5c2da82-a632-4e2c-86ba-57495271a200', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 10, '100237442', '聖なる夜に', '咲太は友人の福山拓海が見ていたミスコンのウェブサイト上にミニスカサンタの姿を見つける。しかし、彼女の写真の下には霧島透子ではなく、岩見沢寧々という別人の名前が書かれていた。さらに霧島透子について探っていた咲太は、紗良から協力の申し出を受ける。思春期症候群によって、強くぶつかった相手の考えていることがわかる症状を発症していた紗良は、咲太が霧島透子を探していることを知っていた。そして、クリスマスイブに行う新曲の生配信の場でミニスカサンタの心を読もうと提案する。', '2025/09/09 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f134787-0da2-47c4-a0c2-ef471620a472.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f92ee25-6a3e-4816-b94c-e341a4473e87', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 11, '100237844', '夢見る世界', '「4月1日の音楽フェスで、麻衣が霧島透子の正体は自分だとカミングアウトする」夢を見た咲太。時を同じくして、複数の大手SNSで「#夢見る」の書き込みが殺到したことによるアクセス障害が発生した。「#夢見る」が世間を騒がせる中、古賀朋絵は麻衣が一日警察署長のイベント中に事故に遭い、意識不明の重体になる夢を見たと咲太に告げた。もうひとつの可能性の世界の咲太からの「麻衣さんが危ない」というメッセージを思い出し、気がかりになる咲太の前に再びミニスカサンタが現れる。', '2025/09/16 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41610f02-40c8-448a-aae8-584d467b7962.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7595e24e-e7f1-40c3-9f29-940fb6b71f26', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 12, '100238331', 'トナカイの仕事', '麻衣は成人の日に報道陣の取材に応じ、自身が霧島透子ではないことを明言するが、「#夢見る」の影響は大きく、噂を完全に消すことはできなかった。麻衣本人に、桜島麻衣が霧島透子だという噂を否定させるというミニスカサンタとの約束を果たした咲太は、彼女とデートに出かける。デート当日、元町でショッピングをするミニスカサンタを認識する人は誰もいなかった。彼女に探りを入れる咲太だったが、高校時代から付き合っていた恋人として、意外な人物の名前が出てくる。', '2025/09/23 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d140112-9a2c-48a9-b272-e77c01a316fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79493315-0fa6-44ef-a735-3c3bd751bce8', 'b004fe79-bf91-4cb4-bab9-f783639f6663', 13, '100239187', 'サンタクロースの夢を見ない', '【シーズン1 最終話】寧々は、恋人である福山拓海に思い出してもらえなかったことをきっかけに、寧々としての自分を忘れ、完全に自分を霧島透子だと思い込むようになってしまう。この思春期症候群を治せるのは拓海だけで、それが麻衣を守ることにもつながると考えた咲太は、赤城郁実とともに急遽、拓海の帰省先の北海道へ飛ぶ。空港で出迎えた拓海に、咲太は寧々がミスコンで優勝した時のトロフィーを見せて……。', '2025/09/30 12:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ae419df-6067-4699-b092-5d9c34fa2617.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('055d8a46-7bd4-4e03-a634-2f74d192b9f6', '青春ブタ野郎はバニーガール先輩の夢を見ない', '', 'hulu', 'ao-buta', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/54329cb1-5a36-4cf5-b52a-a69d8d95f258.jpg?w=331&h=447&p=t', 'hulu', 2018, 3, 1, 'FINISHED', NULL, 101291, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9e25a72a-14fa-40a2-8bda-b0b9641a4e39', '055d8a46-7bd4-4e03-a634-2f74d192b9f6', 'hulu-ao-buta-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12ce3bea-f561-41dd-9cdb-f6f86c9f9034.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b53baac-dbcd-4f18-9579-d6112d9871cb', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 1, '100025803', '先輩はバニーガール', '峰ヶ原高校の2年生･梓川咲太は、ある日、図書館でバニーガールと出会う。その正体は、咲太と同じ高校の3年生で活動休止中の国民的女優、桜島麻衣だった。周囲からひと際目立つ麻衣だが、何故か彼女の姿は周囲の人間には見えていなかった。麻衣から金輪際、私に関わるなと言われるも気になった咲太は翌日、駅のホームで見かけた彼女に話しかける。そして咲太は、麻衣の身に起こっている不思議な現象について聞かされる。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12ce3bea-f561-41dd-9cdb-f6f86c9f9034.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe1b7d39-833c-474a-8e5b-e7117badd813', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 2, '100025948', '初デートに波乱は付き物', '麻衣の思春期症候群の原因を探るなかで、咲太は麻衣とデートをすることに。約束の日、藤沢駅に向かう道中で迷子の女の子を助けようとした咲太は、一人の少女に変質者だと勘違いされ、それが原因で麻衣との待ち合わせに遅刻してしまう。なんとか麻衣の許しを得て、デートをすることになるが、麻衣は行き先を変更して咲太を七里ヶ浜に連れていき…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e4c3a89-0e14-439a-b702-1ab2c8254aee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22147721-c7b2-4ffc-b0a5-ccd6c90dc810', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 3, '100026271', '君だけがいない世界', '藤沢を離れ、大垣まで行っても桜島麻衣のことを覚えている人は一人もいなかった。咲太は麻衣と共に学校に戻るが、そこでも友人の双葉理央から学校内で自分以外に麻衣のことを覚えている人間はいないということを聞かされる。麻衣を忘れていくのは、ある行為に起因するものだという仮説を聞いた咲太は、麻衣の記憶を失わないように奮闘する。そして、そんな咲太の姿を見て、麻衣も一つの決断を下すのだが…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d8d8819-8eb9-406d-9b41-7591fc343fcb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1db73357-e2f7-4b16-92e1-b20bd7595466', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 4, '100026564', 'ブタ野郎には明日がない', '麻衣の思春期症候群が解決したのも束の間、咲太はまたしても新たな不思議現象に遭遇する。同じ日が何度も繰り返され、明日がやってこないのだ。この現象について理央に相談したところ、同じ日を繰り返し、やり直しをしている人物―“ラプラスの悪魔”の存在が原因になっているのではないかという仮説を聞かされる。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/488d0034-6c39-441d-b43e-6af377b42aa0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73854cf4-4007-4dd7-82ad-2c4487428ce5', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 5, '100026872', 'ありったけの嘘を君に', '咲太と付き合っていると勘違いされたことで、友達の好きな人から告白されるという悩ましい事態を解決できた朋絵は、このまま恋人のふりを続けてほしいと咲太に頼み込む。麻衣に負い目を感じつつも、クラスでの自分の居場所を失うことを恐れる朋絵を放っておけず、渋々了承した咲太はしばらくの間、朋絵の嘘の恋人を演じることになり…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8b80afb-8932-4e6f-a026-7610635aa5f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('515e1af6-e573-4bbf-ac6c-34f53b01178d', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 6, '100027153', '君が選んだこの世界', '朋絵と恋人のふりをするという約束の1学期も最終日となった。七里ヶ浜での最後のデートを終え、「麻衣に未練がある咲太に愛想を尽かせて朋絵が振った」という設定で別れたことにしようと決めた咲太と朋絵。すべてがようやく解決したかのように思われたのだが…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cacfe917-4f56-4e60-9f50-467e238c5e78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe8557b8-3f78-472c-84e7-067176488a51', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 7, '100027474', '青春はパラドックス', '長かった6月、7月が終わり、ようやく麻衣とお付き合いできることになった咲太だったが、仕事で忙しい麻衣とは会えない日々が続いていた。鬱憤をためながらバイトをしていたところ、そこに仕事終わりの麻衣がやってくる。麻衣からの提案でしばらく会えなかったお詫びをもらえることになった咲太は、上機嫌でバイトを終わらせる。その帰り道、咲太と麻衣は夜の繁華街でネットカフェに入っていく理央の姿を目撃し、不審に思った咲太があとを付けたところ、驚きの事実を理央から告げられる。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e9b4c2a-61f0-4f76-88c8-4aed02ced4fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e586bffe-defa-4199-8adc-9a1a26965353', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 8, '100027738', '大雨の夜にすべてを流して', '自分が二人存在するという思春期症候群を引き起こし、咲太の家にしばらく泊まることになった理央。一方で“もう一人の理央”はSNSに思いがけない写真を投稿していた。そのことを同級生の上里沙希から教えられた咲太は、改めて理央と話をすることに。その行動の理由、そして思春期症候群の解決方法を探るため二人の理央から話を聞いていく中で、咲太はそれぞれが抱える悩みを知ることになり…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17927cac-6c10-4797-9d68-bb716f3c45dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39cf8cd8-567d-49aa-9c9a-4e25e0691c65', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 9, '100027961', 'シスターパニック', '事務所からのデート禁止令によって、芸能活動で忙しい麻衣と会えない日々が続いた咲太。ようやく2学期がはじまり、学校で麻衣に会えるようになることを心待ちにしていたが、家の前で出会った麻衣からは「あんた誰?」という衝撃の一言が。事情を確認すると麻衣とその妹･豊浜のどかの身体が入れ替わってしまっていたことが発覚する。思春期症候群が解決するまでの間、麻衣はのどかとして、のどかは麻衣として日々を過ごすことになるが…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eed39d0e-c926-4cf1-a744-3e10c9763585.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89a056a1-f048-40a8-bb7f-3a7b10da0444', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 10, '100028330', 'コンプレックスこんぐらっちゅれーしょん', '女優･桜島麻衣としてCM撮影を上手くこなすことができず、次第に劣等感を強めてしまったのどか。その後も二人の身体が入れ替わった生活が続く中で、麻衣はのどかの所属するアイドルグループ“スイートバレット”の単独ライブを迎えることになる。チケットを渡された咲太とのどかは、ライブを見に行くが…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c6b3284-6b19-4205-896d-3a367f204234.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed7c0e76-d87c-4cb1-b77c-9f24e0b8d1b9', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 11, '100028611', 'かえでクエスト', 'のどかの思春期症候群が解決し、やっと麻衣と恋人らしい毎日が過ごせると期待を膨らませていた咲太だったが、そんな矢先に桜島麻衣に彼氏がいるというスキャンダルが報道されてしまう。出演する映画の記者会見で、誠意ある説明をする麻衣の姿を見たかえでは、自分も咲太のために頑張りたいと、今年の目標を立てる。その目標の中には学校に行くという内容も記載されていて…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc2de44b-d574-46cd-a8b5-b0e8dd9742d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8faaf62-3a05-4604-90df-088fd7333847', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 12, '100028920', '覚めない夢の続きを生きている', '七里ヶ浜で遭遇した幼なじみの鹿野琴美を覚えていないと言ったかえで。その再会をきっかけに咲太は麻衣とのどかに、かえでが記憶を無くしてしまっているという事実と、2年前に起こった出来事を打ち明ける。琴美と会った次の日からもかえでは、学校に行くための練習を続けようとするが…。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f606e3d4-9b1f-4eab-8e3c-0ac0cfa57101.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea345d51-e885-4600-9ca1-d6e32e246b9e', '9e25a72a-14fa-40a2-8bda-b0b9641a4e39', 13, '100029126', '明けない夜の夜明け', '【シーズン1 最終話】咲太の手助けで夜の学校に行くことができ、次は昼の学校にいくと意気込んでいたかえで。しかし、その翌日、突如“花楓”の記憶が戻り、2年間一緒に過ごしてきた“かえで”の記憶が消えてしまった。かえでがいなくなってしまったことに打ちひしがれる咲太の前に、ある人物が現れる。', '2025/06/13 12:00:00', 1500, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f44e9a28-720a-452d-b303-c76051c5555d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('450626d6-e3c9-4ed2-a226-bde7e1351c7a', '赤髪の白雪姫', '', 'hulu', 'snow-white-with-the-red-hair', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d47b60a-1154-431c-aeb5-67dca19ee878.jpg?w=331&h=447&p=t', 'hulu', 2015, 2, 1, 'FINISHED', NULL, 21058, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('7445e62f-90e4-4037-a386-f835f943d615', '450626d6-e3c9-4ed2-a226-bde7e1351c7a', 'hulu-snow-white-with-the-red-hair-s1', '1stシーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c12bdf5-6151-4a86-9139-e013bba169c4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('825f8a75-090d-4c39-8ef6-904c2de7bc11', '7445e62f-90e4-4037-a386-f835f943d615', 1, '100054929', '出会い…色づく運命', 'タンバルン王国のラジ王子に愛妾にされそうになった白雪は、生まれ育った国を出ることに。隣国の森で出会ったのは、ゼンと名乗る少年。薬剤師の白雪は彼の捻挫の手当てを申し出るも信用されず、自らの腕を打ち、できた傷に薬を塗ってみせる。彼女の思いがけない真摯な行為に心を許すゼン。事情を聞いた彼は、災厄の原因となった白雪の赤髪を運命の色だと言う。そんなふたりの元に林檎が届けられた。贈り主は、ラジ王子であった。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c12bdf5-6151-4a86-9139-e013bba169c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d6e3b1e-fda7-4dc0-a2bb-3251cac1680c', '7445e62f-90e4-4037-a386-f835f943d615', 2, '100054930', '辿るは胸の鳴るほうへ', 'クラリネス王国で暮らしはじめた白雪。薬剤師の仕事を求めて入った薬局で、彼女は薬草をチェックする子どもに出会う。彼が宮廷薬剤師と知って驚く白雪に、店主は「クラリネスは優秀であれば、どんな人材でも支援する国だ」と宮廷薬剤師の募集要項をくれた。薬草を勉強するため、ゼンに見送られてコトの山に来た白雪。だが、見知らぬ男に襲われる。彼は稀な赤髪を持つ彼女を金持ちに献上し、褒美を得ようとしていた。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49e604ad-4cbf-4f42-b830-e4ff5fdeac20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5d5d1dd-ea83-4fc4-a242-7f9599d79d21', '7445e62f-90e4-4037-a386-f835f943d615', 3, '100054931', '約束、輝くその時に', '宮廷薬剤師を目指して試験勉強に励む白雪。王宮に呼ばれた彼女は、不眠不休で執務に励むゼンを目にする。お忍び外出をとがめられたゼンは、反省を態度で示すと執務室にこもり続けていたのだ。自分の国を知りたい、そのためにゼンは闘っている。ゼンの姿に白雪は宮廷薬剤師となる決意を強くする。そんな白雪をゼンに取り入る厄介者と思うハルカ侯は、彼女を遠ざけようと画策する。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75fcce84-f0c5-43c0-975e-72c78a25b7dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b53a9ef-ac10-4391-89a6-abf04a878ada', '7445e62f-90e4-4037-a386-f835f943d615', 4, '100054932', '芽吹きの協奏曲響く、小さな手', 'いよいよ宮廷薬剤師見習いの採用試験が始まった。白雪は薬事棟の花壇で、薬屋で見かけた宮廷薬剤師のリュウに出会う。彼に採取する時間で薬草の効能が変わることを教えられた白雪は、ここでなら生きた薬学が学べると試験への意気込みを新たにする。試験内容は薬草園の管理。夜、薬草園の灯りが気になったゼンが訪れると、白雪がひとりで作業していた。そこに何者かが現われ、白雪とゼンは薬草園に閉じ込められる。試験の行方は…。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2fcc60e1-b344-48dc-b9f7-b2e33a53358e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfc37daa-b91c-457c-8d50-bd771fb63b1f', '7445e62f-90e4-4037-a386-f835f943d615', 5, '100054933', 'この道は予感の結晶', '宮廷薬剤師見習いとしての仕事で白雪はゼンたちとラクスドの町に到着した。白雪と別れてラクスド砦に視察に訪れたゼンとミツヒデ、木々は、倒れて苦しむ兵士たちに驚く。原因がわからず、魔物の仕業だと言う兵士やオビの制止を振り切って砦内を調査するゼンは、空になった武器庫を見て盗賊を疑う。木々の提案で兵士たちの治療を白雪に頼むことにしたゼン。騒ぎのなか、オビは危険に飛び込むゼンを止めないミツヒデを不思議に思う。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70393c88-ff5f-4f03-98cf-1adaad11074c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37f1a868-3833-40a4-8c4c-bb0cd6b44b10', '7445e62f-90e4-4037-a386-f835f943d615', 6, '100054934', '意味の背中', 'クラリネス王国の第一王子、イザナが帰還し、王宮の空気が一変した。ゼンの兄との思いがけない対面にとまどう白雪。ゼンと白雪の関係を快く思わないイザナは、かつて彼女を愛妾にしようとしたタンバルン王国のラジ王子を城に招待するが…。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e91561fe-0826-422a-922a-a7e1be7a3b74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dd5dd28-657c-4cc1-96c6-3584eaf33645', '7445e62f-90e4-4037-a386-f835f943d615', 7, '100054935', '聞かせて、笑顔の旋律', 'イザナの帰還によりクラリネス王国にいる意味を見失いかけた白雪だったが、ゼンの言葉を思い出し、どうありたいのか自分の中の答えを再確認する。手をとりあい心を通い合わせる白雪とゼン。ゼンは白雪に、一国の王となる自覚をもって道を進む兄･イザナとの思い出を語り始める。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca13bab6-d8fe-47e6-b25e-fbee077c065d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c909a2f3-a10b-4453-9d6e-083c7e8b175c', '7445e62f-90e4-4037-a386-f835f943d615', 8, '100054936', '記憶は過去のらせんを描いて…', 'ラジ王子の発言で注目の的となってしまった白雪。そんな白雪を心配するゼンはオビを彼女の護衛につける。そんな中、オビは、ゼンが“王子”じゃなければ良かったのではないかと白雪に問う。それを偶然聞いてしまったゼンは、アトリという少年との過去に思いを馳せるのであった。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/528218eb-ef3a-461b-86d5-9c0c09235fd2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75dcffcb-080c-4702-bbb2-b728d5cf1f1a', '7445e62f-90e4-4037-a386-f835f943d615', 9, '100054937', '繋がり届く想い', 'ロカの実のお酒を飲んで酔ってしまった白雪は、ラクスドに行こうとする。砦での事件以来、ゼンのために何か出来ないかと考えていたのだ。護衛をまかせていたオビから知らせを受け、二人の元へ向かうゼン。その姿を見たミツヒデは、ゼンを守ると誓った日のことを思い出す。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/18b76d4c-97c4-441b-b559-8bd889c61c11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56dec28f-b9d1-4ef5-9549-a664955ef19a', '7445e62f-90e4-4037-a386-f835f943d615', 10, '100054938', '心蒼く、もっと深く', '白雪が出会ったのは笛で鳥を操る少女、キハル。彼女は鳥たちと共に暮らす一族のひとりで、むやみに鳥を狩る領主を止めるようゼンに頼みにきたと言う。王子のゼンに相手にされないだろうと諦めつつ、それでも後には引けないキハル。彼女と鳥の絆を見た白雪はゼンにある提案をする。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/897f4292-ca2c-4e82-b1eb-242e6df67453.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('014c1b16-80a5-4bde-a05a-de126edca1f4', '7445e62f-90e4-4037-a386-f835f943d615', 11, '100054939', '出会う…初めての色', '白雪負傷の知らせに馬を走らせたゼンは、彼女の笑顔を見て思わずキスをする。それから三日経っても落ち着かず、ゼンを意識してしまう白雪。一方、キハルの住む島に交渉に出かけたゼンは、白雪への想いを彼女に告げようと決意していた。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e51c46ba-d910-4257-b102-40cb102aa6bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1abc8fae-7c77-4b80-a5b1-a9a181cda3cd', '7445e62f-90e4-4037-a386-f835f943d615', 12, '100054940', '始まりのさようなら', '【1stシーズン 最終話】ゼンの告白を受け、自分の想いを返した白雪。別れ際、いつもと変わらず「またな」と言うゼンを白雪は心強く感じる。王城開放日、市井の人々であふれ、お祭りのような城内。ケガをした女優の治療に呼ばれた白雪は、座長の頼みで代役を務めることに。目立つ赤髪を隠して舞台に立つ白雪だったが…。', '2020/05/21 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c90d5348-ec0c-4ad0-a0c9-f681ff5ce343.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('25d8f793-ab5a-476b-b4bd-0225538cbd81', '赤髪の白雪姫', '', 'hulu', 'snow-white-with-the-red-hair-season-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a213a72-cf2b-4fe2-90e6-d96332293b17.jpg?w=331&h=447&p=t', 'hulu', 2015, 2, 1, 'FINISHED', NULL, 21058, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', '25d8f793-ab5a-476b-b4bd-0225538cbd81', 'hulu-snow-white-with-the-red-hair-season-2-s1', '2ndシーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/588952f3-bd03-47fe-91e0-f79399b71f60.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aeb6b5b4-b4ed-49fc-8c66-393bdd387687', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 13, '100057046', '運命を紡ぐ赤', '互いの想いを受け入れたゼンと白雪は、これからの事に思いを巡らせながら、第二王子として、宮殿薬剤師見習いとして成長していた。日常を取り戻し、穏やかな時間が流れるクラリネス王国ウィスタル城だったが、白雪とゼンに突然の来訪者が現れる。それは、以前白雪をさらって牢に入っていたはずの巳早だった。さらに、イザナの元にタンバルン王国からの便りが届き、白雪のこれからに変化の予兆が現れる。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/588952f3-bd03-47fe-91e0-f79399b71f60.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8140f366-c1e0-4d80-bd5f-71218cb6cac3', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 14, '100057047', '守る瞳、進む瞳', 'イザナから7日間のタンバルン王国行きを命じられた白雪は、立ち振る舞いの稽古に追われていた。タンバルン行きを翌日に控え、白雪を追う謎の少年鹿月の手掛かりを得られず不安を募らせるゼンに、オビは白雪の付き人を自分にしてほしいと勝負を挑む。その勝負の行方とは―。そして、決意を胸に白雪は付き人とともにタンバルン王国へと出発する。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef28e7da-1245-46fa-9032-b0ec7ea1a98e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac8d0212-177a-460e-8497-9868a141f2f3', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 15, '100057048', '迷うは戸惑いの中', 'ラジ王子に招待され、オビとともにタンバルン王国へやってきた白雪。ラジ王子は、二人と親睦を深めるため、シェナザード城の案内を自ら買って出るが、道に迷ってしまう。道に迷う白雪たちの後ろには、後をつける二人組の姿が。一方クラリネス王国では、巳早と鹿月を巡って新たな動きの兆しが見え始めた。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5269def-2f6b-4a53-9738-3980ed0e0aa8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('613191a3-7333-4c84-9c63-e44446edd835', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 16, '100057049', 'その一歩の名は、変化', 'タンバルン王国で白雪と過ごす時間の中で、少しずつ王子としての自覚が芽生え始めた様子のラジ王子。そんなラジ王子の変化を目の当たりにしたロナは、ユジナを巻き込んで白雪をタンバルン王国へ留まらせようと、画策し始める。一方、クラリネス王国で白雪を追う鹿月の動きを察知したゼンは、白雪の身に危険が迫っていると気付き、行動を起こす。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/714932b7-b4b7-4210-997c-870ffdd887e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75ec3254-a7b3-42b5-bf40-e3ebdb19393b', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 17, '100057050', '静かに絡まる夜の序章', 'ついに白雪とオビの目の前に現れた鹿月とイトヤ。彼らによって白雪はさらわれてしまう。タンバルン王国への道中を急ぐゼン、ミツヒデ、木々だが、到着したのはすでに白雪がさらわれた後。ゼンたちは、白雪の救出に力を尽くしたいと申し出たラジと共に、タンバルン国王の許しを得て、異国の地で白雪の捜索に乗り出す。その頃、ゼンたちの動きを待たずして鹿月たちを追ったオビは、森に潜む彼らを発見する。しかし、そこに白雪の姿はなかった…。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d2387d1b-51f5-43aa-a304-7bf5c7116a57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f2033a2-a0a5-41f7-910b-dd1969a6a39e', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 18, '100057051', 'いくつもの決意', '鹿月とイトヤにさらわれたはずの白雪。しかし今度は、鹿月と共に海の鉤爪にさらわれていた。白雪を探すゼンたちとラジ一行は、白雪をさらったと思われる海の鉤爪の情報を持つという山の獅子を訪れることに。その道中、すでに山の獅子の大将武風と行動を共にしていたオビとイトヤと合流する。そこで、ゼンは白雪がさらわれた経緯と目的を知らされ、イトヤに敵意を露わにする。しかし、ゼンとラジは白雪、武風とイトヤは鹿月を救出するという共通の目的の元、手を組むこととなる。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eab89f22-5683-4f62-89fc-04febc19bbf2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d10c18b-20ff-4292-9788-8a2c558a4dbf', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 19, '100057052', '覚悟の波', '白雪と鹿月を乗せた船に潜り込むことに成功した木々。彼女が持ってきた胡桃石のおかげで、白雪と鹿月が乗せられた船を特定したゼンたちとラジ一行は、白雪救出に向けて大きく動き出す。ラジは自ら民衆に呼び掛け、白雪と鹿月を乗せた船を囲い込むが、海を知り尽くした海の鉤爪に翻弄され、根城へと逃げ込まれてしまう。しかし、逃げ込んだ根城にはゼンたちが待ち構えていた。ラジの手によって退路を塞がれた海の鉤爪と、ゼンたちの総力戦がついに始まる―。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a47c339-a43f-4849-81d0-6a6bdc8fe42f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('380d7039-d1e6-45e7-bac1-abf3f489ebb7', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 20, '100057053', '微笑みの温度、大切な場所', '武風の提案で、山の獅子の村で休むことになった白雪、ゼン、ミツヒデ、木々、オビ。白雪に自分が父親だと気付かれた武風は、久しぶりの再会に緊張しながら、白雪やゼンと言葉を交わす。そして、白雪の父親としてゼンと二人きりで話すことに。その頃、山の獅子の面々と宴会を行うミツヒデと木々だが、その輪にオビの姿はなかった。護衛役にも関わらず白雪を守れなかったことを気に病むオビに、白雪はある言葉をかける。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e666172c-1c2d-433e-ba2b-cc82ea8a2051.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a6245af-d99f-458e-95f0-7bcd28465488', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 21, '100057054', '貴方といれば……', 'タンバルン王国での一件を終えたゼンたちと白雪は、クラリネス王国へ戻る道中、宿で一泊することに。久しぶりの心休まる時間に、白雪は思わず笑みがこぼれる。ゼンたちと白雪が居酒屋で夕食を食べていると、宿屋ですれ違った若い娘トロウに軽い調子で声を掛けられる。何気なくトロウと言葉を交わしたオビだったが、トロウとは面識があったらしい。そんなトロウに仕事を手伝ってほしいと頼まれたオビは、夜のうちだけという条件付きで、トロウと行動を共にすることになった。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d868d990-e246-4642-8aed-fa9c5141082f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db016579-e555-4c68-98aa-a0d8e22ba92c', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 22, '100057055', '君を潤わせるのは意志の泉', 'クラリネス王国ウィスタル城に帰城したゼンたちと白雪。早速、薬室の業務に戻る白雪だが、ゼンはそうもいかない様子。ゼン宛てに届いた見合いの催促状が山ほど溜まっていた。妃探しの夜会を開かない代わりに、目録に名のある者の中から必ず誰か一人と見合いをするよう、ハルカ侯爵に強く言われてしまう。目録の中に木々の名前を見つけたゼンは、木々と見合いをすることに。見慣れない木々のドレス姿を見たゼンは、ミツヒデと木々が初めて会った時のことを思い出す―。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d73539a-c421-4388-a11e-75d786ace43c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2b699a0-4ea1-4813-afd6-764ec635df20', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 23, '100057056', 'あるがゆえの先', '薬室を訪れたミツヒデは、ちょっとした不注意で催眠作用を持つヨイカガリの薬瓶を割ってしまう。普段深く持っている一面が助長されるというヨイカガリの影響で、ゼンへの忠誠心が強く引き出されたミツヒデは、四六時中ゼンに付いて回り、ついにはゼンにうんざりされてしまう。治療薬を作ることになった白雪は、無事にミツヒデをもとに戻すことができるのか…?', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/379b87d4-b5cc-40d0-9715-66c6b0c8d380.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5cfbefca-e3a3-4120-b2d9-51c1c1d309be', 'cdf27330-96b4-435d-8d7b-b0d4fe5da1fe', 24, '100057057', 'そして物語、私の道', '【2ndシーズン 最終話】晴れて、正式な宮廷薬剤師になった白雪。そこへ、タンバルン王国から巳早とサカキが使者としてやってきた。白雪に渡したいものがある、と言ってサカキが白雪に渡したのは、『王家の友人』の勲章。それは、白雪がいつでもタンバルン王国を訪れることができるようにというラジなりの心遣いだった。『王家の友人』の称号を与えられた白雪に向けたイザナの一言が心に留まり、白雪は、自分が立ちたいと思う場所に気付く。そして、ゼンにその想いを告げようと白雪は決意する。', '2020/07/02 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fc2e0c09-be49-48b6-baf7-9f8d8bb50b7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3d2d5dc0-9f00-479a-bec7-d5f5b7688303', '絶対衝激～プラトニックハート～', '', 'hulu', 'master-of-martial-hearts', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/890722ee-f453-49bb-82d5-4ecce45ee027.jpg?w=331&h=447&p=t', 'hulu', 2008, 3, 1, 'FINISHED', NULL, 5020, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b9fdb8c4-635b-41dd-8ca0-607d7350d2a7', '先輩がうざい後輩の話', '', 'hulu', 'my-senpai-is-annoying', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9020f71-8d34-4dca-b440-da5673b9fcf2.jpg?w=331&h=447&p=t', 'hulu', 2021, 3, 1, 'FINISHED', NULL, 120646, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d6621bdc-d1e9-4bdd-a382-d77e18aac227', '先輩はおとこのこ', '', 'hulu', 'senpai-wa-otokonoko', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94998f01-f485-4dcb-8418-e9cbb3872f99.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 163133, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f5740d73-2b17-45e9-8041-664bea0b5a38', 'd6621bdc-d1e9-4bdd-a382-d77e18aac227', 'hulu-senpai-wa-otokonoko-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28dc40e0-d902-4132-b2ac-6dabeb31e3f3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5041dd37-214a-4ab9-a187-6111c1c112e3', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 1, '100190077', '先輩はおとこのこ', '高校二年生の花岡まことには、“普通”じゃないところがある。それは、男の子だけど、学校では女の子の姿で過ごしていること。ある日、まことは「伝えたいことがあるので放課後教室に残っていてほしい」というラブレターを受け取る。放課後、まことの前に現れたのは、後輩の一年生女子･蒼井咲だった。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28dc40e0-d902-4132-b2ac-6dabeb31e3f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d224d68a-e18a-4a6f-bebe-7ed37640c09f', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 2, '100190855', 'かわいいものめぐり', 'まこと、咲、そしてまことの良き理解者である幼馴染･大我竜二を加えた3人でお昼ご飯を食べることが日常になりつつある中、学校は夏休みを迎える。しばらくまことに会えなくなる、と悲しむ咲を見かねた竜二は、まことから借りていたノートを咲に渡す。ノートを口実に意気揚々と花岡家を訪れる咲だったが、そこには男の子姿のまことがいて……。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c275adc-0d36-4848-acad-0e988544c9c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f21d48a5-a883-4e77-817c-a1b14800604b', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 3, '100191571', 'さよならわたし', '「まだこんな女の子みたいなのが好きなの?」と問う母に、自分はもう可愛いものは好きではないと、嘘をつくまこと。母を悲しませないために、可愛いものを好きでいることはやめようと決心。学校も男の子の姿で過ごすようになる。さらには、咲に付き合ってくれないかと告白をして……。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70949c47-ad1a-4484-b9a4-6dc543a52bc8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6f1d575-e6a8-4bc0-a045-b13c7938cfee', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 4, '100192516', '気づいてしまった', '創立記念パーティーを終え、また少し近づいたまことと咲の距離。さらに同級生とも打ち解け始めたまことの姿に、竜二は心のざわつきを感じていた。そんなある日、3人は休日に水族館へ行くことに。咲の機転もあり、水族館を大満喫した3人だったが、帰り道の電車で竜二はある違和感を覚える。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ed738ff-cc95-4040-9f63-287d8fc582ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e62d13b9-d48e-4b05-a5e8-742c2c7ecc20', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 5, '100193509', '特別', 'まことが助っ人として参加する、バスケ部の試合を見に行くことになった咲と竜二。試合観戦中、竜二は咲に「本当にまことのことが好きなのか?」と、真意を問う。反対に竜二はどうなのか? と聞く咲に対し、真っすぐに返答する竜二。それを受けた咲は、泣き出してしまって……。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/65f2accf-ab03-4457-8323-6979e4630520.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c5f6259-8491-41f6-aaab-9c0e799294a0', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 6, '100195043', '決めなきゃいけないこと', 'まことを諦める、と咲が決め、お昼ごはんを一緒に食べなくなってしまった3人。そんな中、まことたち二年生のもとには進路調査票が配られる。女の子になりたいのか、男の子として生きるのか。告白するか、しないのか。それぞれがこれからを見据えた選択に悩む中、学校は文化祭に向け盛り上がっていく。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7c22313-5ad4-45b6-8b78-77109d37a7c8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d0b0a9a-0cfa-4820-9527-1953aed5bea6', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 7, '100195702', 'そーいうの', 'まことへの想いをずっと隠してきた竜二。同性のまことに惹かれている自分に抵抗を覚え、一度は離れようとしたものの、気持ちを隠し幼馴染として見守り続けてきたのだった。まこともまた、生徒手帳を見てしまったことを隠し、平静を装って竜二に接し続ける。しかし竜二はまことの異変に気がついて……。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed7083fc-a559-4f19-83a0-5dc4012feb66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ddcec30c-51c7-426c-98e3-34ddcd1f4366', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 8, '100196361', '傷ぐち', '祖母が倒れた知らせを受け、急いで病院に向かう咲。仕事の関係で海外にいる父も連絡を受け緊急帰国する。なかなか会えない父と久しぶりの再会を果たし、クリスマスも日本で一緒に過ごせると聞き、咲は喜ぶ。一方、竜二もまた、クリスマスの約束をまことに提案する。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5d936af-45af-44cf-91dd-7d7807d1b846.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18a9e914-a3a0-4c4c-a985-d8e56737f961', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 9, '100197722', 'クリスマス', '迎えたクリスマス当日。プラネタリウムへと一人向かう咲だったが、その帰り道、ある人が乗るタクシーを偶然見かけてしまう。咲がタクシーを必死に追いかける一方、まこともまた、竜二の元へと向かっていた。出会うはずのなかった二人が、思いがけず出会って……。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fc1dc598-d6ab-4ee0-943e-deb35b71c421.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a361a4ac-acc7-426d-a3d7-bcd1292a3ac7', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 10, '100198482', 'ふたりの思い', '別れて以来、一緒にご飯を食べることも、会話をすることもなくなってしまった、まことと竜二。それを知った咲は、二人の仲直りをアシストしようと、ある作戦を企てる。まことと竜二が向き合おうとする一方で、咲もまた、思わぬ場所で意外な人物と出会う。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d64d863-863a-420e-84f4-68876d05155a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('279a8d10-fce6-4525-acd4-25c7b1ab2126', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 11, '100199432', '元ともだち', '咲が母と会うことを許されるようになった中、まことたち二年生は修学旅行を迎える。まことは修学旅行が終わったら果たしたいある目標を、咲と竜二に宣言する。まことが心を決める傍ら、ある人もまた、勇気を出して「自由行動一緒に回ってください」とまことに声をかけて来て……。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2002fe7-a922-4125-b5e5-e251c91e0fab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6211851b-0d56-4ace-9666-a89409d60d0d', 'f5740d73-2b17-45e9-8041-664bea0b5a38', 12, '100200087', '本当のぼく', '【シーズン1 最終話】父の勧めで、初めて祖父に会いに行くまこと。自分の好きなものへの想いを守り、ありのままに暮らす祖父とともに時間を過ごす中で、まことは少しずつ自分の気持ちを整理する。そして、ある覚悟を胸に秘め、帰宅を決意する。', '2025/12/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60881b90-beee-403a-923c-c2ec757f9952.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8afa4ab6-7a0b-4337-9ee6-f77e8c1f5b6c', '千歳くんはラムネ瓶のなか', '', 'hulu', 'chitose-is-in-the-ramune-bottle', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7f29e038-82c2-4c03-a438-81a065af1f86.jpg?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'RELEASING', NULL, 180082, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', '8afa4ab6-7a0b-4337-9ee6-f77e8c1f5b6c', 'hulu-chitose-is-in-the-ramune-bottle-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3856aa97-996d-4e6b-90d7-92abf2c09fdc.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc354166-6553-4d4d-bf84-12242ab31db6', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 1, '100240558', '春、見上げるおぼろ月', '福井県内でも随一の進学校･藤志高校に通う千歳朔。何をとっても非の打ち所がない彼のまわりには、華やかな仲間たちが集うと同時に、それをやっかむ陰口が吹聴されることもまた日常だった。そんな“いつも通り”の高校2年生の春。朔は、担任の岩波蔵之介から「引きこもりのクラスメイト･山崎健太を登校させてほしい」という依頼を受ける。原因を探るため、内田優空とともに彼の自宅へと赴く朔だったが、取り付く島もなく追い返されてしまい……。', '2025/10/10 18:30:00', 2980, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3856aa97-996d-4e6b-90d7-92abf2c09fdc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2491042f-c1d6-4c60-a8b9-3f2bd4bcc0fc', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 2, '100240974', '相互理解をはじめよう', '窓ガラスを破り、半ば強引にではあるが健太との対面を果たした朔。初めこそ「ヤリチンクソ野郎」という先入観から、一挙手一投足に突っかかってくる健太だったが、真剣に向き合おうとする朔の姿勢が、少しずつその心を動かしていく。なんでも、好きだった女子にひどい振られ方をしたことが引きこもりの原因らしい。振られた相手を見返せるように、もう一度自分の足で歩けるように、健太は期限付きで朔たちと行動を共にすることになるのだが……。', '2025/10/18 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/178a3fcf-a8fb-4c5e-85b2-3891a0655ded.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6bdf6aea-c961-4016-8cbf-46c0532b3072', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 3, '100241717', 'ひとりぼっちのヒーロー', 'チーム千歳と過ごす日々の中で、着実に努力の成果が表れてきていた健太。そんな姿を見て朔は、そう遠くないうちにやってくる「健太が過去と向き合うその日」のことに思いをめぐらせていた。「健太をけしかけたのは自分だ」その結末にまで責任を感じ始めていた朔の背中に、部活終わりの陽が声をかけてくる。持ち掛けてきたのは、十本先取の1on1。負けた方が何でも相手の質問に答えるという条件で、考え込んでいた朔の心の内を聞きたいようで……?', '2025/10/25 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fb1c006-7261-463c-8b1b-0be653562349.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a920130-c9d7-4750-a41f-0bf787d10f8d', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 4, '100242505', 'ラムネの瓶に沈んだビー玉の月', '約束の日の朝。朔たちと喧嘩別れをしてしまった健太は、冷静さを欠いていた昨日の自分を思い出し、ひどく後悔していた。今の自分にできることは、せめてこの3週間に意味があったと証明することだ——そう決意して、かつての友人たちと対面する健太だったが、何を話しても、返ってくるのは悪意に満ちた返事ばかりで、昔のチャットメッセージまで持ち出されてしまう。気丈に振る舞っていても、徐々に擦り減っていた健太の心は、どうしようもないくらいに折れかけて……。', '2025/11/01 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/faf6954c-f4ad-40f4-90da-6ebd3ae9a4cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d2e263a-16ad-4934-9f86-9ec688802a3e', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 5, '100243547', 'かりそめのスタートライン', '「私の恋人になってみませんか?」五月の土曜日。悠月から呼び出されて、朔は福井駅前のカフェに来ていた。およそ本心から出たとは思えない交際の提案に、悠月の心の内を探る朔。しかし、唐突にも思われた告白の訳は、悠月がストーカーにつけられている感覚があり、朔に恋人のフリをしてほしいから、というものだった。そういうことならと、かりそめの交際が始まった翌週。登校した二人が付き合い始めたことをカミングアウトすると、教室中に激震が走り……!?', '2025/11/08 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4cdb803e-9a27-413f-9c08-d06dcd0bdf30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('773817be-dc44-4b08-b9b3-8c38cd35a5b4', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 6, '100246736', '青色のバッシュ', '県立図書館での一件があった翌日。学食で昼食をとっていた朔と健太に、他クラスの男子生徒･成瀬智也が話しかけてくる。智也は悠月に気があるらしく、朔と悠月が本当に付き合っているのかを知りたがっていた。「一目惚れだった」と語る智也の気持ちを無碍にできない朔は、悠月との交際があくまで"フリ"であることを明かし、恋愛指南にも協力することに。一方、ストーカー被害の渦中にある悠月のもとには、自宅ポストに宛名のない不審な郵便物が届いていた。', '2025/12/06 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a94f6ff-9aa2-4492-8e1a-17a124f145ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da55da74-6001-478d-8cdb-f3d470533d55', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 7, '100247497', 'ハレの日ケの日', '悠月の劇的なスリーポイントで、逆転勝利を収めた試合の後。8番らーめんに来ていた朔、陽、悠月の3人は、悠月のバッシュが無くなった一件について意見をかわしていた。隠されていた場所や学校の内情に通じていそうな気配から、朔は、藤志高校内部の人間が犯人ではないかと推測を立てるが、まだまだ情報が足りない。犯人探しが行き詰まると、話題は朔と悠月が約束した"ご褒美デート"へ。しかし、なぜか互いに好戦的な陽と悠月。事はあらぬ方向へと進んでいき……!?', '2025/12/13 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3e4d985-6eac-4278-b7e8-ae71fe0f75d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75b3dde7-f0be-4bb2-bc04-9c0ff045dbe4', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 8, '100248174', 'やまない雨のやませ方', 'お祭りの翌日、悠月は体調を崩して学校を休んでしまう。柳下に見せた怯えるような様子を思い出し、彼女の状態を案ずる朔だったが、あくる日の朝、悠月は学校で元気な姿を見せていた。まずは一安心……と安堵したのも束の間、なずなが悠月の机にぶつかった拍子に、机の中から身に覚えのない写真が落ちて散らばる。そこには、仲睦まじくお祭りで手を繋ぐ、朔と悠月が写っていた。愕然とする悠月――そして、その姿を見る夕湖もまた、呆然とその場に立ち尽くしていた。', '2025/12/20 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c43af734-5024-499b-a52e-2c259c040496.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9bd223a4-0dff-4305-addb-b6cb941222df', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 9, '100248907', '名前のあるカンケイと名前のないキョリ', '降りしきる雨の中、ずぶ濡れの悠月を連れて自宅に戻ってきた朔。「七瀬悠月はその程度の女なのか」どうしようもないほどに弱り切り、らしくもない行動に出る悠月を見かねて、朔は問いただすように強く迫る。はっぱをかけられてなんとか持ち直した悠月は、今もなお暗い影を落とす、柳下との過去についてぽつりぽつりと話し始めた。悠月の過去を知り、朔もまた、普段は語らないような身の上を明かし、二人きりの夜は更けていく――。', '2025/12/27 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28e4fd83-b3b8-4d34-91b3-429f2d42c265.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bff8a4c1-9500-4875-afe0-cf826dba4b52', 'f77822ac-4ccc-4f89-855e-ffdaa6a5ab23', 10, '100249622', '悠な月', '特別がゆえに、何でも持っているがゆえに、何も持っていない。そんなふうにかつての自分を振り返る悠月は、朔と過ごすうちに、自身もまた"美しく"生きてみたいと願うようになっていた。そんな彼女が、一人で下校することを選んだ帰り道。図ったように待ち構えていた柳下に対して、悠月は毅然とした態度で向かい合う。脅しにも暴力にも屈しはしない——千歳朔に見た生き様が、芽生えた想いが、悠月を奮い立たせる。しかし、柳下の毒牙は容赦なく悠月を追い込んで……。', '2026/01/03 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2d6e2f9-44d5-45e0-953a-c2faeb882d46.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1f0858cd-87d1-4f26-83e9-0f5baa720d57', '戦う司書 The Book of Bantorra', '', 'hulu', 'the-book-of-bantorra', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/29696d86-dd98-4221-a2b4-56e1e0a98726.png?w=331&h=447&p=t', 'hulu', 2009, 3, 1, 'FINISHED', NULL, 6758, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3503f511-f094-4eee-8c08-6fa55b65ae78', '1f0858cd-87d1-4f26-83e9-0f5baa720d57', 'hulu-the-book-of-bantorra-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4cff25f0-dc42-401f-8a2c-c17e58f6f4f8.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89435552-152f-49ab-bd41-62f9ed381ae8', '3503f511-f094-4eee-8c08-6fa55b65ae78', 1, '100248200', '爆弾と本と沈み行く船', '人の記憶が『本』になる世界。死者の本を管理し世界の秩序を守る『武装司書』は、欲望を肯定し幸福を求める謎の組織『神溺教団』と有史以来、戦いを繰り広げてきた。武装司書を率いるハミュッツは、神溺教団に囚われた人々を解放する為、武装司書のヴォルケンたちに敵の本拠･白煙号を襲撃させる。防衛線を突破し、船倉に辿り着いた彼らの目に飛び込んできた光景は、記憶を奪われ爆弾を埋め込まれた『人間爆弾』たちの姿だった。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4cff25f0-dc42-401f-8a2c-c17e58f6f4f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf253abd-cdf0-4116-90fa-73548169f52a', '3503f511-f094-4eee-8c08-6fa55b65ae78', 2, '100248201', '爆弾と姫君と灰色の街', '「ハミュッツ=メセタを殺せ」。全ての記憶を失い人間爆弾として目覚めたコリオ＝トニスは『本』を掘り出す町、トアット鉱山に現れる。標的は歴代最強の武装司書ハミュッツ=メセタ。仲間の人間爆弾たちが爆死していくなか、コリオは謎の男から本の欠片を渡される。その本に封じ込められた記憶を読んだコリオは、猫色の髪の姫･シロンと運命的な出会いを果たす。しかし、彼女は世界で最も忌み嫌われた予知能力者、「常笑いの魔女」だった。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3a2ae6f-4c25-456a-88d0-8766adf3b008.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0cab89d-fa0e-46c6-a083-e551aef2d2de', '3503f511-f094-4eee-8c08-6fa55b65ae78', 3, '100248202', '爆弾と人間と死の神の病', '神溺教団の指導者シガルのテロ計画を阻止すべく、ハミュッツはトアット鉱山に降り立つ。投石器による遠距離射撃で街に潜入した人間爆弾たちを次々と血祭りに上げていく中、シロンの本を持つ人間爆弾のコリオの存在に強い興味を抱く。一方、武装司書のマットアラストとミレポックはハミュッツの命で神溺教団のアジトに潜入する。そこで二人はシガルによって幾重にも張り巡らされた、ハミュッツ抹殺計画の正体を知るが…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9e668fe-82b0-409d-b540-4a8f87366842.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4bb41e96-2272-4049-8270-1001a81783b0', '3503f511-f094-4eee-8c08-6fa55b65ae78', 4, '100248203', '夕方とシロンとコリオ', 'シロンの未来予知を使ったシガルの罠が、世界最強と呼ばれたハミュッツの攻撃能力を奪い、その体を竜骸咳によって蝕んでいく。絶対の防御能力を持つ魔刀シュラムッフェンを手にしたシガルの一閃はハミュッツの体を切り裂き、戦いの巧者である彼女を追い詰めていく。勝利を確信し嘲笑するシガルの前に、一人の人間爆弾が割って入って来る。それは、全ての感情を奪われ、爆弾をその胸に埋め込まれていた筈の少年、コリオの姿だった…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fdd834c1-5a8f-4382-b46c-22f76ba78216.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('070cf6c1-b49b-481c-acba-0099a101fc45', '3503f511-f094-4eee-8c08-6fa55b65ae78', 5, '100248204', '裏切りと杯と迷いの小道', '白煙号事件以来ハミュッツに反抗し、心を塞いでいた若き武装司書ヴォルケンが追憶の戦機ユックユックを奪い、バントーラ図書館から失踪してしまう。反逆者となったヴォルケンに対して、同期として最も親しかったミレポックは動揺を隠せない。唯一の手掛かりは失踪前に彼が残した『ラスコール=オセロ』という伝説の人物の名前のみ。ヴォルケンの無罪を晴らそうとするミレポックだが、次第にその裏にある本当の感情に気がついて…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/273f7546-d9c0-43af-b532-db47c818a144.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('012dc527-6948-48fe-b15d-9674770e8b5f', '3503f511-f094-4eee-8c08-6fa55b65ae78', 6, '100248205', '雷と怪物と殴る少女', '平和を取り戻したバントーラ図書館に招かれざる訪問者が現れる!「怪物」とでもいうべきその男は黄金色の仮面を被り、多くの魔法を操る不死身の襲撃者。トップレベルの戦闘能力を持つマットアラストや、ミンス、ミレポックの三人をも圧倒し去っていく。襲撃事件の後、貿易港ブジュイに派遣された見習い司書ノロティは、ハミュッツより極秘任務を与えられる。その任務とは「死にたがりの男ザトウ=ロンドホーンを助けろ」との事だが…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b505afa-bb2f-4c51-937d-7111311428c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc4a1504-d387-4e7f-983f-f1bccb7aadd6', '3503f511-f094-4eee-8c08-6fa55b65ae78', 7, '100248206', '笑顔と仮面と死にたがりの男', '肉として飼われ「笑顔」を失った少年エンリケは、真人、ガンバルゼルの導きで「怪物」になるべく神溺教団の訓練島に送り込まれる。ハミュッツを凌ぐ強さを獲得すべく魔術審議を続ける少年たちと、彼らの身の回りの世話をする少女クモラ。日々の厳しさの中でいつしか仲間意識を持ち始めた彼らを、過酷な運命が引き裂いていく。一方、ハミュッツの命でザトウを追跡していたノロティは、彼の体の信じ難い秘密を知ってしまうが…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e345eb8e-75b2-4c03-8ca3-d272ea3658a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('681ba05f-e18a-4ce4-9dcc-aaba220ddcf6', '3503f511-f094-4eee-8c08-6fa55b65ae78', 8, '100248207', '沼と仲間と浜辺の貝殻', '「笑いたい」。その言葉と共に死を望む男ザトウが消え、高笑いと共にバントーラ図書館を襲撃した「怪物」が現れる。圧倒的な魔法能力の前に防戦一方のノロティ。そこに人の魂の本質を見極める能力を持つ武装司書ミンスが駆け付け、「怪物」の正体をノロティに告げる。「黄金の怪物」と「死にたがりの男ザトウ」と「笑顔を失った少年エンリケ」。この三者の繋がりを知ったノロティは全てに決着をつけるべく、「怪物」に対して拳を叩きつける!!', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0226d38a-cdee-4f22-b6b3-843011efd409.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b07a51e1-4ae5-417c-949c-982247b0331b', '3503f511-f094-4eee-8c08-6fa55b65ae78', 9, '100248208', '真人と戦場と私の世界', 'ノロティと共にバントーラ図書館に帰還したエンリケを待っていたのは、武装司書たちの敵意に満ちた眼差しだった。「怪物」に仲間を殺された怒りをエンリケにぶつけようとする武装司書ルイークたちを止めようとするノロティだが、エンリケは構わず彼らに雷撃を放ってしまう。そんな中、孤立を深めるエンリケを追い詰めるように、真人ガンバンゼルがエンリケを「怪物」として迎え入れるべく、バントーラ過去神島に潜入を果たしていた。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83cc4b44-8edb-45c2-a830-e720d8a8bc1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc8d0669-8fb9-473d-90bc-0540a541e856', '3503f511-f094-4eee-8c08-6fa55b65ae78', 10, '100248209', '変人と母親と黒蟻の巣', '全ての生物を喰らい尽くす無数の黒蟻を操り、ハミュッツに匹敵する強さを持ちながら、心を病んで図書館の地下書庫奥深くに引き籠ってしまった武装司書モッカニア。少年時代に過ごした家を模した部屋で暮らす彼の日常は、まったく予期していなかった訪問者によって破られてしまう。バントーラ図書館に鳴り響く警報と、無数に現れる黒蟻の群れは、ハミュッツたちに新たなる危機を告げる。モッカニアが武装司書に反乱を起こした、と。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/86f70433-1cf9-44b2-a6fc-2f8f88d3d399.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5a1a51f-7b70-4341-b840-f12a2b2e3744', '3503f511-f094-4eee-8c08-6fa55b65ae78', 11, '100248210', '弱者と迷宮と女王の指し手', '武装司書モッカニアの反乱は、バントーラ図書館を黒蟻の迷宮と変える。次々と蟻の餌食となってしまう武装司書たち。イレイアの魔法権利によってモッカニアの動きを封じた間に、シュラムッフェンを手に入れたハミュッツはモッカニアの元へと駆ける。迷宮内にシュラムッフェンの高笑いが響く中、神溺教団の擬人ウインケニーが静かにほくそ笑む。果たして、何故モッカニアは反乱を起こしたのか、彼に母と呼ばれる女性は何者なのか…?', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ae2cc08-90f5-41fc-9d03-8f69e795e68d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19065ed9-8b71-49df-87aa-9b9aea24e513', '3503f511-f094-4eee-8c08-6fa55b65ae78', 12, '100248211', '過去と理不尽とパイプの煙', '館長代行ハミュッツの右腕にして、元恋人であるマットアラスト。ハミュッツと久しぶりの朝食をとりながら、初めて出会った日々のことを思い出す…。15歳にして武装司書に昇進し、天才と称された若きマットアラストは世の中への反発から荒れた生活を続けていた。ある日、ハミュッツという名の少女に出会ったマットアラストは、戦いの中でお互いの強さに惹かれ合う。程無く同棲を始めた二人は、館長代行フォトナの命で戦場に赴くが…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ff3c513-affa-4f2a-88a5-db9b025f6136.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f1a3e87-b3eb-42c6-92b2-69d7a5aaf279', '3503f511-f094-4eee-8c08-6fa55b65ae78', 13, '100248212', '休暇と絵本と赤錆の髪', '芸術とシネマの都、フルベック。数々の事件の裏に見え隠れし、死者の本を残された者に届けるという伝説の人物ラスコールを追って、霧に覆われたこの街にミレポックが現れる。かつて同様にラスコールを追い、非業の死を遂げた大女優パーニィの本を探す中、ミレポックは神溺教団の裏切り者アルメと出会い、剣を交える。慕っていたシガルの復讐のためにラスコールを探すアルメはミレポックにこう言い放つ。「ラスコールを追う者は死ぬ」、と。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffb686e1-20fd-4d20-80f1-7d0aca94cc1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ff2bb81-aa49-4474-9055-48f27470be22', '3503f511-f094-4eee-8c08-6fa55b65ae78', 14, '100248213', '落日と語りべと幾つかの寓話', '三百年前に現れ、常笑いの魔女と称された伝説の未来予知能力者シロン。神溺教団の指導者ワイザフとの戦いを前にして、彼女は遥か未来を予知する…。死者の魂が『本』となり、『本』を読むことで死者の記憶が残された者に読み継がれる世界。人は願い続ける。「夢」を、「幸福」を、「愛」を…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbb80979-f6ec-4c1f-8d72-db02f0cd77a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12f7f20c-a81e-476a-962d-4d40847cf064', '3503f511-f094-4eee-8c08-6fa55b65ae78', 15, '100248214', '少女と少女と神の寝床', 'ミレポックによるラスコール追跡は袋小路に立たされていた。ラスコールの謎を掴んだとされるパーニィの本は未だ見つからず、事情を知っている者の口も塞がれてしまう。赤錆の剣の戦士アルメとの戦いを経て、己の弱さをまざまざと実感したミレポックは精神的に追い詰められてしまう。一方のアルメもラスコールへの復讐も果たせず、己の力の無さに憤りを隠せない。脆くも儚い、そんな二人の少女をラスコールが静かに見つめていた…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97e0aad5-8e4c-42e8-af90-1c6ddc279d56.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c22cb98-23ec-4adb-b383-1eee3e88d59c', '3503f511-f094-4eee-8c08-6fa55b65ae78', 16, '100248215', '禁書と腑抜けと聖浄眼', '他人の魂を見る能力を持つ武装司書ミンスは、兄妹の武装司書ユキゾナとユーリと共に「赤本」と呼ばれる禁断の『本』を探して熱帯の街ガンダリを訪れる。武装司書の目をかいくぐり、貴重な『本』を密売するこの街の人間でさえ手を出さない「赤本」は、異常犯罪者の妄想や快楽殺人者の記憶が詰まった『本』であり、読んだ人間は快楽で精神を破壊されてしまうとされる。捜査の中ミンスは、かつて山賊を生業としていた時の相棒グレインと再会するのだが…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/740755f1-c867-4432-ba2d-73873a68a7b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ba0adce-6223-497b-9086-ece315ba748a', '3503f511-f094-4eee-8c08-6fa55b65ae78', 17, '100248216', '帰還と出会いと燃えあがる緑', '追憶の戦機ユックユックを持ち出し、行方を消していた裏切り者ヴォルケンがバントーラ図書館に戻ってきた。気色ばむ武装司書たちを前に、ヴォルケンはハミュッツの不正を正し、バントーラに真の正義を取り戻すと宣言する。一方、モッカニアの反乱以来、バントーラに保護されていたレナスの体に異変が生じる。混濁した彼女の意識上に現れ、肉体を乗っ取ろうとする「別の意思」はある言葉を呟く。「失われた、…を取り戻せ」、と。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a65d780a-2cbb-4820-8e1d-4f6ecfc0f7bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a74e779-7523-41a0-b874-1b2462b66976', '3503f511-f094-4eee-8c08-6fa55b65ae78', 18, '100248217', 'プロペラと追想と鉛の人間', 'レナスの中の「別の意思」の記憶を取り戻すため、ダライ鉱山へ向かうヴォルケンの前に、師であるビザクが立ち塞がる。年老いても未だ鋭いビザクの攻撃に苦戦するヴォルケン。一方、ハミュッツはレナスの中に封じ込められている「別の意思」の正体に気付き、マットアラストたちを残して一人追撃を開始する。ハミュッツを恐怖させ、白煙号を爆破させてまでの殺害を決意させた、レナスの中に潜む「別の意思」の正体は果たして何者か…?', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03a7dc4c-c35b-4929-a46d-67b23b792186.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1621ae01-c417-4b6c-b484-c3f672ad0a5a', '3503f511-f094-4eee-8c08-6fa55b65ae78', 19, '100248218', '阿呆と虚空と踊る人形', 'かつて肉たちを解放するべく戦ったレナスの中の「別の意思」。彼女がユックユックに込めていた「願い」を叶えるため、ダライ鉱山の山小屋を目指すヴォルケンたち。そこに執念とも言うべきハミュッツの投石器が二人を襲う。武装司書の正義を信じるヴォルケンは、悪と断言するハミュッツに対して幻と舞剣を繰り出す。一方、ユックユックの元へ急ぐレナスの中の「別の意思」の前に神溺教団の放った人間爆弾たちが迫る…!!', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/586dc468-bfb0-46b7-919c-0bedb2129939.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c96940f-caf1-41a3-a69a-10a7b492be9a', '3503f511-f094-4eee-8c08-6fa55b65ae78', 20, '100248219', '弔鐘と本と死にたがりの少年', '見習い司書からの昇進試験を兼ねて、ノロティは神溺教団の計画する細菌テロの調査に乗り出す。蒼淵呪病と呼ばれる伝染病を使った彼らの計画を掴んだノロティは、事件の発生を防ぎ首謀者を捉えることに成功するが、驚くべきことにその正体はアーキットという名前の少年であった。武装司書に対して深い憎しみを持ち、神溺教団に参加したという少年の心を開かせようと、ノロティはアーキットと共に神溺教団の総帥カチュアの元へ向かうが…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daa8f08f-95e2-4274-b39b-7a18adf208d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1321e304-3b60-48da-b6da-0c9d986676bf', '3503f511-f094-4eee-8c08-6fa55b65ae78', 21, '100248220', '憎しみと蒼と荒縄の姫君', 'バントーラ図書館と全世界の国々との激戦は続いていた。次々と現れる敵影を前に、事態の真相を掴めない武装司書たち。マットアラストとキャサリロは、捕獲した敵将校を尋問するが、何者かにとり憑かれたかの様に「ノロティ」という名を呟くのみ。バントーラ図書館を取り囲みつつある敵に対し、ハミュッツ自らイレイアと共に前線に出撃する。一方、エンリケは、ノロティがアーキットと共に行方を消した、楽園管理者の待つ山荘へと向かうが…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a4be0b5-97d7-4bb6-8377-d7d3a20e7035.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('298c0d0e-4128-4971-b576-60419057b4e8', '3503f511-f094-4eee-8c08-6fa55b65ae78', 22, '100248221', '空と結末と彼女の世界', 'アーキットと共に山荘を目指すノロティの前に、神溺教団の総帥カチュアが姿を現わす。身構えるノロティに対して、カチュアは神溺教団の降服を伝え、その対価として恐るべき交換条件をノロティに提案する…。一方、ハミュッツたち武装司書はバントーラ島まで追い詰められ、籠城戦を続けていた。砲撃がバントーラ図書館を襲い、次々と倒れる武装司書たち。ハミュッツは生き残ったマットアラストたちと共に最後の戦いに討って出る!!', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/162f0ec0-0fb3-438a-8539-93bbadea7978.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19e44844-08e6-4fa3-aa99-ac54e0521342', '3503f511-f094-4eee-8c08-6fa55b65ae78', 23, '100248222', '脱獄と道具と砂漠の菫', '神溺教団の真人でありながら、天国への反逆者としてカチュアの依頼のもとハミュッツにその根を摘み取られたとされる「菫の咎人」。ラスコールによってマキアと呼ばれる老人の本を読んだハミュッツは、「菫の咎人」の行方を追って、突然行方をくらませてしまう。彼女が向かった地は、荒野の中に佇む廃墟と化した研究施設。そこに待つ「菫の咎人」を探す中、ハミュッツはかつてこの施設で過ごした若き日の記憶を思い出す。ハミュッツの正体とは果たして…。', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3bd94b8d-ab24-4ddc-ab76-39283f2f635d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('409d87f6-38d3-4f45-ab78-a8dff6f297a5', '3503f511-f094-4eee-8c08-6fa55b65ae78', 24, '100248223', '真実と恋と第二封印書庫', '心魂共有能力と呼ばれる力を発現させた「菫の咎人」。相手の感情を思いのままに操ってしまうその能力に圧されながらも、ハミュッツは情け容赦なくその拳を振り上げる。かつて幼い日々を過ごした唯一の親友に手を掛けてまで、ハミュッツが守ろうとした秘密とは一体何だったのか…。一方、バントーラ図書館ではこれまでに無い異変が起こり始める。図書館の最深部に眠る「ある存在」が、その永き沈黙を破り活動を再開する!?', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/531387cb-4fbc-419b-b386-ce1a3f573335.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8faf929-1809-455b-8303-dcb10a422e14', '3503f511-f094-4eee-8c08-6fa55b65ae78', 25, '100248224', '静寂と惰眠と絶望の物語', '二千年ほど昔。神と人間とが調和をとり共存していた楽園時代の終わり。思い上がった人間を滅ぼすべく、未来神オルントーラは「終章の獣」を解き放った。対する人間は、十万人の戦士の『本』を「本喰い」の能力を持つ少年に捧げ、神に対抗する救世主として忠誠を誓った。少年の名はルルタ＝クーザンクーナ。彼は人々の期待を一心に受け、その責任の重圧に押し潰されそうになるが、その彼の前にニーニウという少女が現れる!?', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59481956-add8-458e-951d-1893b3bc76f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a3f5f01-c55d-4372-84bb-512436af8c17', '3503f511-f094-4eee-8c08-6fa55b65ae78', 26, '100248225', '贖罪と惑と本の中の本', 'ルルタの放った「涙なき結末の力」によって、世界は静止する。マットアラストたち武装司書をはじめ、全ての人間が穏やかな眠りにつく中、ルルタの仮想臓腑内ではハミュッツの最後の戦いが始まっていた。無数の本を喰ったことで神に匹敵する能力を持つルルタの攻撃がハミュッツを貫き、引き裂くが、その度にハミュッツは再生し復活する。驚くルルタに対し、ハミュッツの真の能力が遂に明かされる…!', '2026/01/21 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/417b2039-4569-4885-a544-34c630ea56d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64654c7d-bc89-43c0-906a-82b29bd01edc', '3503f511-f094-4eee-8c08-6fa55b65ae78', 27, '100248226', '世界の力', '【最終話】「滅びの意思」として世界中に「終章の獣」を放つニーニウ。一方ルルタの仮想臓腑の中では、孤独な戦いを続けていたハミュッツを助けるため、神溺教団との戦いの中で非業の死を遂げた者たちが集結する! 全ての力を失ったルルタは仮想臓腑の外で目を覚ましたミレポックに協力を求める。ルルタの元に集まっていく世界中の人々の想いはニーニウを変え、世界を救うか!?', '2026/01/21 00:00:00', 1525, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c5135c9-1660-40fc-ad37-a1e082999cf9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3787cb5d-20be-47f6-93cc-843553ef37a8', '戦国BASARA', '', 'hulu', 'sengoku-basara', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b4892a9-f29f-4728-9c1c-a12ceff46994.jpg?w=331&h=447&p=t', 'hulu', 2009, 1, 1, 'FINISHED', NULL, 5355, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('70bb1770-fa64-4621-aa7e-892804f705bc', '3787cb5d-20be-47f6-93cc-843553ef37a8', 'hulu-sengoku-basara-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f32201f-12a7-4c51-9a45-1713bb6ea75a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f573e0a-fdb4-48c0-bfb1-d7574e47fcc9', '70bb1770-fa64-4621-aa7e-892804f705bc', 1, '100146425', '蒼紅 宿命の邂逅!', '川中島に陣を敷く甲斐の武田信玄と越後の上杉謙信。信玄から上杉軍本陣奇襲を命じられた真田幸村は、本陣がある妻女山へと出陣する。だが同じ頃、奥州の雄･伊達政宗も妻女山へと侵攻していた。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f32201f-12a7-4c51-9a45-1713bb6ea75a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15155233-a831-49d6-852f-6fadce25a8ea', '70bb1770-fa64-4621-aa7e-892804f705bc', 2, '100146426', '戦慄! 桶狭間の遭遇', '腹心･片倉小十郎の奇策によって武田軍を足止めさせ、駿河へと侵攻する奥州の覇者･伊達政宗。それを阻止するべく追う真田幸村。再びあいまみえた好敵手同士が、今川義元の首を懸けて激突する。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1fdc1c38-75a8-4c01-a07b-a0c9827211b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3877a56d-d3db-4749-9c4f-5a5f2d854560', '70bb1770-fa64-4621-aa7e-892804f705bc', 3, '100146427', '風来坊 前田慶次!', '奥州へと戻った伊達政宗は、織田信長の前に沈黙した己に自問するかのように剣を振り続ける。そこへ諸国を訪ね歩いているという男･前田慶次が現れ、織田に対抗するための同盟構想を明かし政宗を誘う。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13f5ee88-0733-4f51-a330-8200a7f19eea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8884ed8-92d1-47f0-8bcc-437b0ecf95c9', '70bb1770-fa64-4621-aa7e-892804f705bc', 4, '100146428', '揺れる緋の華 悲を呼ぶ信義!', '熾烈なる殺戮を繰り返し、数々の敵対する勢力を討ち滅ぼす織田軍。無残にも無抵抗の女子供までをも手に掛け、草木の1本まで焼き払う織田の所業には一片の義もなく、それは文字通りの魔王による侵略行為であった。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87744758-0bd7-49f7-b82f-41c8a56eb348.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30f64ade-7e23-4ce6-a7ac-0930df497560', '70bb1770-fa64-4621-aa7e-892804f705bc', 5, '100146429', '壮絶! 長篠･設楽原の義戦', '長篠の地で徳川軍と対峙する武田･上杉連合軍。家康が織田との隷従に等しい同盟関係に甘んじていることの真意、織田の思惑、共に察している信玄は、家康を味方とするべく直接の説得を試みるが…。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88f47356-5cea-4dff-ac5a-a20b0e53e59f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b4b24cd-cc3a-4004-9fbd-abf5dd8f52cb', '70bb1770-fa64-4621-aa7e-892804f705bc', 6, '100146430', '裂かれた絆 政宗屈辱の退却!', '明智光秀率いる織田軍鉄砲隊の銃撃は、織田の盾となり戦う浅井軍にも容赦なく襲い掛かる。銃弾を浴びて倒れた長政は、光秀からお市が浅井へ輿入れした本当の理由を聞かされショックを受けるが…。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40dc4a0b-e7ce-4a47-b211-4e8b296457fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('682b31bb-a1a8-4248-a35a-6cfb984b4918', '70bb1770-fa64-4621-aa7e-892804f705bc', 7, '100146431', '略奪の梟雄! 双竜月下の真剣勝負', '甲斐の国へ身を寄せた伊達軍。鉄砲傷を負った政宗の姿に、小十郎は忸怩たる思いを募らせていた。そんな折、3人の部下が謎の爆弾兵によってさらわれたとの報が届く。彼らの身柄と引き換えに出した条件とは…?', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b8efa3a-4046-463c-bec7-73b7bef721fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4961882-6bb4-429b-9332-cef2ff39ee5d', '70bb1770-fa64-4621-aa7e-892804f705bc', 8, '100146432', '血風大伽藍! 小十郎絶体絶命', '伊達の兵たちを救うため、小十郎は三好三人衆が仕掛ける罠を突破し、松永久秀が待ち受ける仏閣跡へと単身乗り込む。だが、松永は要求したふたつの宝の一方が揃っていないことを理由に交渉を拒み…。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4756ded6-023d-40a9-b4c0-8547fc571bcc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('098570b7-3819-4e10-ba11-5abed35720df', '70bb1770-fa64-4621-aa7e-892804f705bc', 9, '100146433', '甲斐の虎、御勅使川に死す!', '第六天魔王の脅威が天下を覆わんとしているかのように、暗雲が垂れ込めていた。九州全土への侵攻を開始した織田信長は薩摩の島津義弘を破るが、そこには濃姫、森蘭丸、明智光秀らの姿はなかった。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b8738ce0-026b-416c-b155-6709988aa847.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ec4ebc5-1d52-4df3-9ca2-9dabb3faf22e', '70bb1770-fa64-4621-aa7e-892804f705bc', 10, '100146434', '幸村再起不能!? 伊達軍涙の解散!!', '仇敵･明智光秀と再び相対する政宗と小十郎。その卑劣な策略への怒り、そして長篠･設楽原での雪辱を晴らすべく、双竜の剣尖が炸裂する。だが光秀は、政宗に不可解な言葉を残して姿を消してしまい…。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd89600d-628e-48e2-b1a1-8185d40b447d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('661a1aef-ef4f-4bb5-9fb1-4b9e1a55f518', '70bb1770-fa64-4621-aa7e-892804f705bc', 11, '100146435', '光秀の謀反! 本能寺大炎上!!', '「敵は、本能寺にあり」。織田信長に最後の戦いを挑むべく、山城国･本能寺へと駆ける政宗と幸村。2人の前に現れたのは…? その頃、甲斐には上杉、徳川をはじめとする諸国の軍勢が圧巻の大集結を果たしつつあった。', '2023/07/22 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17a559eb-b947-4386-9d69-56cef6694dc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a956092-ab33-41ec-9b68-1117936420d9', '70bb1770-fa64-4621-aa7e-892804f705bc', 12, '100146436', '安土城天守 明日を懸けた死闘!!', '【最終話】第六天魔王･織田信長との決戦の地は、天下を見下ろす山の頂にそびえる未曾有の大城砦･安土城。政宗と幸村は鉄壁の城へ決死の突入を果たす。万難を排して駆けのぼった先で待っていたものとは…?', '2023/07/22 00:00:00', 1412, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4b15106-ba95-4829-898e-ec1ea877f2bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
