INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('610b0e08-9e6c-45a8-8998-85a076923510', '戦国妖狐', '', 'hulu', 'sengoku-youko', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5caebfc-ee7e-43b8-afd0-ba3024335ec1.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 168194, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b519a113-f008-42f4-86b3-f3fe435293cc', '610b0e08-9e6c-45a8-8998-85a076923510', 'hulu-sengoku-youko-s1', '世直し姉弟編', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35ff218e-5d41-412c-bfa3-7a5790ed3e3a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b469b79f-f17c-4240-a971-2727b8c31fbd', 'b519a113-f008-42f4-86b3-f3fe435293cc', 1, '100171597', '我ら乱世を憂う者', '時は永禄7年。武者修行中の武芸者･兵頭真介は、不思議な術で野武士を撃退する「世直し姉弟」＝妖狐･たまと仙道･山戸迅火に出会う。真介は二人とともに野武士集団「鬼兜組」のアジトへ乗り込むが、鬼兜組の頭領が人に仇なす闇 (かたわら) だと知った迅火とたまは秘術「精霊転化」によって力を解放すると、瞬く間に頭領を撃退。迅火の力に惹かれた真介は、2人との同行を決意する。', '2024/01/13 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35ff218e-5d41-412c-bfa3-7a5790ed3e3a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f3871ab-d591-432c-9ef9-3146fde55706', 'b519a113-f008-42f4-86b3-f3fe435293cc', 2, '100172263', '灼岩', '闇と戦う霊力僧兵集団「断怪衆 (だんがいしゅう)」。迅火、たま、真介の3人は、成り行きで彼らとともに闇･灼岩と戦うことに。灼岩の暴走の理由に疑問を感じたたまたちは、その正体が断怪衆総本山の実験によって生み出された、霊力強化改造人間だったことを突き止める。戦いの末に灼岩を人間の姿に戻した3人は、断怪衆の悪行に灸をすえるべく、総本山に殴り込みをかけることに。', '2024/01/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6dad9c78-56cf-4459-a75b-0c04f5aab743.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3088d487-8ca7-441b-9adb-8d325b217f7c', 'b519a113-f008-42f4-86b3-f3fe435293cc', 3, '100173309', '永禄七年', '断怪衆総本山に到着した一行。迅火は精霊転化し、300人の霊力僧兵と激闘を繰り広げていた。だが、人体実験の主導者である野禅を発見するものの、城の闇･泰山の強大な一撃で気を失ってしまう。朦朧とする意識のなかで、迅火はなぜ自分が人を憎み、闇を求めているのかを思い返していた。一方、森の中で身を潜めていたたま、真介、灼岩も断怪衆の僧兵に見つかってしまう。そのとき、仲間を守ろうとした灼岩の姿が……。', '2024/01/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ffc5fea-696e-427a-9466-9360a2aa7eca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ac16daf-c365-410c-ba37-d4b3ff397c61', 'b519a113-f008-42f4-86b3-f3fe435293cc', 4, '100174108', '迅火と人間', '闇･ぐらぐら様との戦いのさなか、野禅が放った闇喰い人･雷堂斬蔵が乱入してきた。風を操る魔剣･荒吹を駆使する斬蔵に対して、互角の戦いを展開する迅火だが、やがて霊力ではなく技のみで押し通す斬蔵に敗北を喫してしまう。一方、迅火の命までは奪わなかった斬蔵だが、断怪衆から確実に殺すことを要求される。斬蔵からの果たし状を受け、迅火は再度戦うことを決意する。', '2024/02/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f384a248-7b9f-4ddf-88a2-e4ba31d6554e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('366da712-4327-4178-a8f4-494179cf7cd5', 'b519a113-f008-42f4-86b3-f3fe435293cc', 5, '100174899', '氷岩', '野禅が送り込んだ次なる刺客･断怪衆四獣将のひとり、氷岩。彼女の正体は、霊力強化改造人間に改造された、斬蔵の妹･氷乃だった。灼岩に封じられている闇･火岩は、氷岩のなかにいるのが旧友の闇･蒼岩と察して語りかけるが、その意識は消滅していた。友を弄ばれた怒りに、火岩は自ら戦うことを申し出る。だが、そこへ龍の気配をまとった二人組が現れる。龍の力を前にして、迅火たちが取った行動とは……?', '2024/02/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b2c70c4-47de-4446-8cdc-b440526da572.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ce05a05-3e4c-45a1-9794-8555e7fa1b39', 'b519a113-f008-42f4-86b3-f3fe435293cc', 6, '100175451', 'ふこう', '断怪衆討伐のため、思いを新たに出発した一行。真介は斬蔵から魔剣･荒吹を託されるが、まだ自分の実力に見合わないものだと思い知らされる。旅の途中、闇･猩々 (しょうじょう) の酒の匂いをかぎつけたたまは、そこに居合わせた断怪衆四獣将のひとり、道練と鉢合わせてしまう。たまは呑み比べでの勝負を提案し、辛くもピンチを乗り切るが…。そして一行がたどり着いたのは、不幸から人々を守り続けた闇が支配する村だった。', '2024/02/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/207fb4f5-edb6-480d-a2d5-13e22dd4969b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1ac62a1-3a82-4802-8fe4-686bc0235820', 'b519a113-f008-42f4-86b3-f3fe435293cc', 7, '100175721', '火岩と芍薬', '火岩の故郷である岩の里にたどり着いた一行。ある日、迅火が身重の女性･おこうに手助けしたことで、一行は岩の里にしばらく滞在することに。だが、ほどなくして断怪衆の追っ手、烈深と道練が岩の里にあらわれた。迅火は道練とぶつかり合い、戦いのなかで真っ向勝負の楽しさに気付く。一方、おこうをかくまっている小屋を不審に思った烈深は、卑劣な手段で小屋もろとも葬り去ろうとする。そこに灼岩が身を挺して立ちはだかる…。', '2024/02/24 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f32f7b98-c88e-46f8-9adb-c9b7fc112b3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bec36079-5ba1-4048-9cf2-8d36284c96e7', 'b519a113-f008-42f4-86b3-f3fe435293cc', 8, '100176569', '魔剣士', '自らを犠牲にして岩の里を守り、深い眠りについた灼岩。彼女を失ったことで、怒りに囚われた真介は、陰の気に飲まれかけていた。ある村で守護者である闇･かごもりが、生贄の人間を食らっていると知った真介は討伐に乗り出す。だが、そこに現れたのは烈深だった。真介は感情に任せて剣をふるうが、烈深の攻撃で気を失ってしまう。朦朧とする意識のなかで、真介は魔剣･荒吹の精神世界に入り込む。', '2024/03/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48461a9e-81f2-46d7-ba90-ca1f4ec34766.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9502d9b0-ab0b-4f48-a5f4-2c43a2ea2dfe', 'b519a113-f008-42f4-86b3-f3fe435293cc', 9, '100177419', '山の神 (前)', '山の神は断怪衆に洗脳された泰山の目を覚ますべく、一行に協力を申し出て、断怪衆3つの大戦力の1つを引き受けると提案する。断怪衆3つの大戦力とは、泰山、龍、そして、くずのは。くずのはの名を聞いたたまは、愕然とする。そのころ、一行を追う断怪衆四獣将筆頭･神雲と少年千夜が目前まで迫っていた。山の神は、迅火、たま、真介を鍛え直すため、それぞれに修行を言い渡す。', '2024/03/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b86baa0-4e9e-459a-8a84-bd9181f1adc1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d570655d-0e37-4da6-a79e-badf663a356c', 'b519a113-f008-42f4-86b3-f3fe435293cc', 10, '100178296', '山の神 (後)', '妖精眼を解放した迅火は、りんずの幻術を見破り、修行をクリアする。一方、偶然にも千夜を倒すチャンスを得た真介は、まだ子供である千夜の命を奪うことに戸惑う。そのころ、たまも、迅火、真介に遅れながらも修行をクリアする。いち早く断怪衆の総本山を目指すべきという山の神に、たまが持ちかけた策とは?', '2024/03/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44ef3ebd-d34f-4eeb-ba2e-297f702cb42f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9290afe0-9eb5-4504-a645-03cdb7daed54', 'b519a113-f008-42f4-86b3-f3fe435293cc', 11, '100178587', '断怪衆最強の男', '神雲と千夜が封じられたという報は、総本山の野禅たちにも届いていた。迅火の霊力がさらに磨かれたと聞いた道錬は、再戦を待ち望む。そのころ、一行は総本山の入り口にたどり着く。たまが選んだのは、正門から乗り込む正面突破。総本山に乗り込んだ一行を待ち受けていたのは、彼らの行動を予見していた道錬だった。迅火と道錬、ついに決着となるのか!?', '2024/03/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c4ec1db-b83e-46dd-bb50-01166ddb415f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffc7c3c5-2ec8-4b9f-a5c4-8444634428d1', 'b519a113-f008-42f4-86b3-f3fe435293cc', 12, '100179431', '迅火と道練と竹吉とバリー', '断怪衆総本山で繰り広げられる迅火vs道錬、真介vs烈深の死闘。妖精眼で攻撃を見極めていた迅火だったが、道錬が繰り出した荒技･千尋拳 (せんじんけん) の威力は圧倒的だった。迅火は、朦朧とした意識を払うべく、霊気の塊の手を頭に突っ込むが…。一方、烈深の轟震海 (ごうしんかい) をかわした真介は、憎しみの果てに自分が目指すべき境地にたどり着く。そして戦いの行く末を見守っていた野禅は、ついに泰山を起動させることに!', '2024/03/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90fec50f-7920-4124-8f0d-76fd58802582.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('928996f5-142c-4466-9351-f58bbb51dd6d', 'b519a113-f008-42f4-86b3-f3fe435293cc', 13, '100180167', '神獣', '【シーズン1 最終話】断怪衆四獣将、そして泰山を失った野禅は、「精霊転化」で迅火に対抗する。九つの尾をもつ野禅は、霊力も戦闘能力も迅火を上回っていた。追い詰められた迅火は、泰山の肉を食らい、霊力を極限にまで高めていく。だが、人間としての自分を顧ない迅火は、正気を失い闇の意識に飲み込まれてしまうのだった。野禅は迅火の暴走を好機と見て、幻術で戦いを支配した。たまや真介は、迅火の正気を取り戻すべく、必死に呼びかけるが…。', '2024/04/06 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e31c3b26-59f2-4364-b04e-68696a1817a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('bbb2d823-802d-433a-aa7b-08e6c1012bb2', '610b0e08-9e6c-45a8-8998-85a076923510', 'hulu-sengoku-youko-s2', '千魔混沌編', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a132595-d938-46ae-b8b9-99d34373ef0b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a826b7f-647f-4944-83c8-f165e5844ada', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 1, '100189824', '24分でわかる「戦国妖狐 世直し姉弟編」', '第二部「戦国妖狐 千魔混沌編」放送開始前に、第一部「戦国妖狐 世直し姉弟編」をプレイバック! ポイントとなるエピソードや名シーンを中心にあらすじをわかりやすく再構成した総集編。ナレーションは「世直し姉弟編」の主人公、迅火役の斉藤壮馬さんが担当。', '2024/07/06 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a132595-d938-46ae-b8b9-99d34373ef0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f8793b3-19ad-465c-9e17-d3a5d145708a', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 2, '100192506', '黒龍', '千夜と狂神との戦いにより、月湖の父が亡くなり、村は壊滅的な被害を被った。真介と千夜は、だれにも知らせずに村を去ろうとするが、月湖が同行を申し出る。やむを得ず月湖を加え、旅の途中で出会った謎の闇･なうと共に、京へ向かう一行。戦いで人の命を奪ったことに苦しむ千夜は、内なる千の闇たちの声を遮り「おれはもう戦わない」と決意する。だが、黒龍･ムドが天空より急襲、千夜に代わって戦った月湖が攫われてしまう…。', '2024/07/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90185f2b-a9ce-4fb7-a6fd-ddbe748e3350.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc743b36-653d-49cf-b6a8-940bd806ea4c', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 3, '100193500', '荒れ都の狂神', '月湖の器量を見抜き、彼女を連れ去ろうとするムド。その危機を救ったのは、突如として現れたたまだった。たまの幻術によってムドを欺くことに成功した一行は、再び旅を続ける。だが、京の町で千夜を狙う狂神と遭遇、どうしても逃げ切れず、応戦の末に倒してしまう。自らの力が戦いを呼び寄せてしまうのに、敵を退けるため、仲間を守るためには力がいる。その矛盾に苦しむ千夜の前に現れたのは…。', '2024/08/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fbcd4b6-c4ae-4db3-a3ea-3faa99fa40be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc2dce61-27a8-4bc4-903a-4b51f0255a23', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 4, '100194141', '千夜と月湖', '一行の前に現れたのは室町幕府第十三代将軍･足利義輝だった。義輝は京の大土地神･華寅を千夜たちに引き合わせる。華寅は狂神と化した自らの分霊 (わけみ) を止めてくれた千夜を労い、自分を責めるなと伝える。それでもなお戦ったことを後悔する千夜だったが、義輝の常識に囚われない考え方に触れ、自身の力について改めて考え始める。しかし千夜の気持ちが変わり始めたのも束の間、京にムドが襲来し、月湖を攫って行ってしまう。', '2024/08/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14ce6d27-1332-4322-b99e-c1c905d5be16.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('806700da-cf23-485d-988e-3b0a20a4c04c', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 5, '100195044', '時、来たるべく来る', 'その身を極めよ――。義輝の言葉に動かされ、千体の闇たちと対話を試みる千夜。闇たちに自らを主人と認めさせようとするが、「従わせたくば力を示せ」と彼らは襲い掛かってきた。一方、剣の道を極めた義輝は、時を斬ることすら可能となり、自らの死が目前に迫っていることを打ち明ける。千夜と義輝、それぞれの運命を決める決戦が始まろうとしていた。', '2024/08/17 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3b0976b-73ee-4299-8a8e-fe2ac2a63d9c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ef10cee-3780-4022-9a7f-218dc155f9cf', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 6, '100195692', '雲の上まで', '激戦を繰り広げる千夜とムド。「全力を尽くして遊ぶ」という気持ちで挑んだ千夜に、もう悲壮感はなかった。やがて最強をかけて戦う二人は、共感すら抱きつつあった。そのころ義輝は、松永久秀の軍勢をたったひとりで圧倒していた。「本当に勝てるんじゃ…」真介が義輝の勝利を信じかけたとき、「無の民」と名乗る謎の5人組が現れる。', '2024/08/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13361f13-0f2b-4ea7-ae6f-c7288bbb8336.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0727221a-8fb0-481d-b273-f782cf916192', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 7, '100196284', '旅の終わり', 'ムドとの戦いを終えた千夜は、無事月湖や真介たちと合流を果たした。回復に専念する千夜たちだが、華寅の術により、真介と斬蔵はその地から離れられぬことが発覚。また、予期せずに無の民が襲撃をしかけてくる。無の民と武でなく対話で向き合うことを決めた千夜は、幽界で彼らの真の目的を知らされる。封印されている父を助けるため、守りたいものを守るために、千夜と月湖は華寅に修行をつけてもらうことに…。', '2024/08/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1f0de2d-2a21-41d3-a8ab-6fccc9f29b59.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0167cf1f-fcbc-400a-a512-8924bbe33061', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 8, '100197455', '古恩', 'たまと合流を果たした千夜と月湖だったが、一行が目の当たりにしたのは千本妖狐となった迅火の姿だった。迅火は海神の力を自らのものにし、周囲に強力な結界を張り巡らせてしまう。結界を突破する方法を探るべく、一行は占い師･八卦猫の元を訪れるが、狂神と化した泰山が突如現れる。なうの助けにより、千夜は幽界干渉を発動し泰山を解放する。そして、仲間に加わった泰山と共に旅を続ける千夜たちの前に、銀髪の一族を探す犬の闇 (かたわら) が姿を現す。一方、強くなりたいと悩む月湖に危険な影が忍び寄る。', '2024/09/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae9d4546-380b-4b09-82b6-52057e8a3126.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7232a136-e8db-403a-a10d-c70f9df2f055', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 9, '100198439', '千夜と神雲', '父･神雲の封印解除を願い出た千夜に、山の神は試練を申し出た。それは近くの山に現れたネズミの闇を退治すること。すぐさま山へと向かった一行だったが、にわかに不思議な香りが漂いだした。それは闇が仕掛けた催眠香を使った幻術であった。罠にかかった千夜と月湖は祭りを楽しむ子供の姿になり、たまも四人で旅をしていたころの思い出を見、在りし日の迅火の姿に心を奪われ始めるのだった…。', '2024/09/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e60866c-4c1d-427e-a3fa-2e03a371b4da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc5d87fa-70cc-4290-b20b-5a6c93216f0e', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 10, '100199431', '千夜の八年', '千夜は断怪衆を辞めるよう神雲を説得するが応じてもらえず、二人は拳で勝負することに。激闘が展開するさなか、突如として無の民が現れ、神雲らを幽界に引き込んでしまう。幽界では優勢な無の民は神雲に融合されている龍･ナダレを解放し、共にその場から逃走を試みる。だが、そこに現れたのは怒りに燃える山の神と泰山だった。地神二人を味方につけた千夜一行に勝機は芽生えるのか…?', '2024/09/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ff66471-aa0f-4a2b-8a68-1edfab051bbb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8595a43-31d6-4f21-bb1d-abc89dfdfca8', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 11, '100202133', '千魔混沌を巡って', '山の神に捕らえられていた野禅から、迅火を人間に戻す方法を告げられた千夜。迅火の結界を破るカギ、それは移動可能で土地神に匹敵する能力を持つ者。一方、無の民は、千夜との戦いには基地となる移動要塞が必要だと考えていた。両者の思惑に合致するもの、それは雲の闇･万象王の力…。一度村に帰った千夜一行だったが、千夜は無の民が起こす事件の要因は自分だと考え、1人で村を旅立ってしまう。そのころ、たまは一足先に単独行動で万象王を捜索するが、恐るべき事実を突きつけられてしまう。', '2024/10/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21d06aa2-55f6-45ae-a9a9-62508545388f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('261c314a-18c3-4790-89ca-26cabacebd90', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 12, '100202847', '決戦の地', '万象王という移動基地を手に入れた無の民は、各地の闇を洗脳し、闇の軍団を組織する。無の民は猩々たちも取り込もうと万象王を差し向けるが、その前に立ちはだかったのは道錬とムドだった。だが万象王の懐に飛び込んだムドは、予期せず同じ龍族のナダレと遭遇、返り討ちに合ってしまう。辛くも逃げ切った道錬とムドは、タゴの導きで龍の気配を辿ってきた千夜と再会。一方無の民は更に軍を増強すべく、闇の群れを求めて岩の闇の村へと向かう。', '2024/10/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fc83edf-af1b-4c6c-ad26-a8e1946d6f2a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df3f5397-636d-4e45-9494-8094e3a3cb1d', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 13, '100203627', '遭遇', '無の民が千夜との決戦の地に選んだのは、8年前に激戦が展開された断怪衆総本山。断怪衆僧正･印河は、千夜、ムド、道錬の3人の闘気が、闇の大群に匹敵する力があると感じ、本山奪還への希望を見出す。それぞれが因縁を持つため、「最初に出会った者が神雲と戦う」という取り決めを交わし、総本山へと突入する千夜たち。無の民に操られた闇の兵たちを退け、3人は総本山を突き進んでいく。万象王を追ってきたたまも加勢するが、そこに現れたのはたまがもっとも戦いたくない相手だった…。', '2024/10/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28878010-e5ef-4950-9035-5445c89e100f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f4a5f70-54af-4ae7-9372-bc5b52b0a0a5', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 14, '100204341', '開眼', '無の民の指示に従わず、神雲 (ナダレ) は道錬との対決を望んだ。2人から激しい闘気が立ち上り、戦いを見守っていたたまたちをも圧倒する。一方、無の民は、道錬と神雲の戦いには構わず、千夜に闇たちを差し向ける。膨大な数の闇たちの攻撃に、徐々に押されていく千夜。だが千夜の肉体は消耗しつつも、霊気はとめどなく湧き水のようにあふれ出していた。操られているすべての闇たちを救いたい…。その真理にたどり着いたとき、千夜はさらなる高みへと向かう。', '2024/11/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9294e806-56e2-4309-9143-737918fd301e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18746f08-e5d1-4876-b684-3826c12226b7', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 15, '100204983', '万象王、降臨', '無の民に操られ、たまに襲い掛かる灼岩。そこに駆けつけたのは真介だった。たまと真介は灼岩を拘束しようとするが、苦戦を強いられる。隙を見て幽界干渉を仕掛ける真介が、灼岩の意識の中に見たのは、彼女が芍薬だった頃の忌まわしい記憶…。村人たちから赤髪と忌み嫌われていた芍薬の前に現れたのは、白馬に乗った謎の侍だった。', '2024/11/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3f55860-7454-49ca-b28e-ceab9e9beb8a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6642f04c-629c-4543-85e1-3c8db9f3b84c', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 16, '100206188', '道介と雲蔵', '万象王が溢れさせた水は大地を覆い、瞬く間に戦場を洗い流した。あらためて万象王に挑みかかるムドだが、軽くあしらわれてしまう。それどころか、万象王はムドを相手にせず、道錬と神雲の戦いを観戦し始めるのだった。そのころ、道錬と神雲の戦いも佳境を迎えようとしていた。極限まで研ぎ澄ませた道錬の拳は一条の光となり、若かりし日の記憶を呼び覚ます。道介、雲蔵と呼び合い、お互いの技を鍛え合っていたあの頃に…。', '2024/11/16 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73a2bba6-7220-4e42-ae7c-37cab37db95e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8e2d337-d6eb-417b-9b69-ecf27d17c123', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 17, '100206959', '異形達の宴', '千夜が目覚めると、操られていた闇たちは真介の幽界干渉によって解放されていた。かつて幽界で無の民に敗北を喫した千夜は、幽界での戦い方を真介に問う。幽界干渉の極意とは…? 千夜は万象王とムドのもとに駆け付け、ついに万象王との激戦が幕を開ける。千夜、ムド、万象王が人型となり凄まじい戦いを繰り広げるなか、その様子を見守っていた神雲と道錬は野禅にとある依頼を持ちかける…。', '2024/11/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4d96033-2624-4956-8d04-dfe054417981.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa82701c-c1dc-42c3-8ae5-51774118218b', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 18, '100207697', '雲を跳び越えて', '万象王との戦いに苦戦する千夜に、神雲と道錬からある提案が持ちかけられる。二人の中にいる龍と虎を、千夜に譲り渡したいと言うのだ。彼ら自身の命と引き換えとなる提案に戸惑う千夜だったが、既に致命傷を得ている二人の想いを受け止め、受け入れることを決断する。新しく身にした龍と虎、そして千の闇たちと共に、戦いを終わらせに戦場へ戻る千夜。ムドに託され、千夜は万象王を飛び越えて無の民の元へと向かうが、いつしか幽界へと誘われていた。そこで千夜を待っていた人物とは…。', '2024/11/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32164ace-0121-46b5-b9cb-0e031f34d97d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e146145-aae9-4cb9-96fd-4fdb3bb35fba', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 19, '100208933', '夜明け', '「争いでは決着がつかない」と判断した猛は、“四方円満落着会議”を招集する。お題は、千夜と迅火を生かしたまま、無の民を救う方法を考え出すこと。隕石の落下から無の民の祖国を救うべく、千夜たちは様々な手段を考えるが、隕石の破壊も他の星への移住も、すでに不可能と判断されていた。だれも根本的な解決策を見出せない中、同席していた虎妖･邪貴が「時の万里眼」と呼ばれる闇に声をかけたという。はたして無の民を救う方法は見つけ出せるのか…?', '2024/12/07 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f9e56d7-eabc-4be1-9bf9-39a1231966db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7d2ace0-0202-4583-a73c-0fbce61932f2', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 20, '100209905', '多くと共に在る者', 'ついに千夜たちは、無の民との戦いを終結させた。ひとりその場から去ろうとする千夜だったが、華寅に捕獲され、あえなく村へと帰還する。目覚めた千夜を待っていたのは、月湖主宰による家族会議。なぜ去ろうとしたのかを問いただす月湖に対し、「いずれ人の世にあってはならない力になる」と、心のうちをさらけ出す千夜。だが月湖はまっすぐな気持ちで千夜を説き伏せる。一方、真介は千夜の告白が腑に落ちず、自身が抱える恐怖と対峙するように忠告する。', '2024/12/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/086be387-a9e8-451b-bad9-f9300e665412.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7616371e-d81b-4956-95f0-078a6136db18', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 21, '100210950', '迅火とたま', '千夜と迅火の壮絶な戦いが幕を開けた。千本妖狐の圧倒的な霊力の前に、ついに千夜も覚醒し、お互い一歩も引かない戦いが展開する。激しい霊力のぶつかり合いのなかで、月湖はひょうたんの力で霊力の乱れを整えようとしていた。霊力の嵐が研ぎ澄まされ、乱れのない川となるときこそ幽界干渉の好機。幽界で迅火に接触すべく、タイミングを見計らい、千夜と迅火の間に飛び込んだたま、真介、灼岩は、ついに幽界干渉を実行する。閉ざされた迅火の心の中で、たまたちが目にしたものとは…?', '2024/12/21 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b5a1acd-cfeb-4f55-a7d2-2d0d7ea9850e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a23d2be-54a2-4450-952a-d1864d4153cd', 'bbb2d823-802d-433a-aa7b-08e6c1012bb2', 22, '100211927', '時の彩の詩が咲く', '【シーズン2 最終話】長き戦いは幕を閉じた。迅火とたまは故郷の山に戻り、なうも地神としてあるべき場所へと帰り着く。千夜と月湖、真介と灼岩たちも長い旅の始末を終えて村へと帰還し、それぞれの暮らしをはじめるのだった。時代が移り変わり、共に過ごしてきた人たちが去っても、千夜は変わらぬ若い姿のまま。過ぎ行く季節の中でただひとり残された千夜は、時の荷を背負って果てのない旅に出る――。', '2024/12/28 00:00:00', 1621, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/694ab4d1-8630-4d4d-aa7d-f2cfc3c9fd4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f20d0c04-24a1-496e-b372-67fc1b924fea', '戦場のヴァルキュリア -Gallian Chronicles-', '', 'hulu', 'valkyria-chronicles', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07af4ee6-8ea5-4733-83f2-c1ed722807a0.jpg?w=331&h=447&p=t', 'hulu', 2009, 1, 1, 'FINISHED', NULL, 5507, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b50af628-aee4-4edc-b387-ecd48dc0bab6', 'f20d0c04-24a1-496e-b372-67fc1b924fea', 'hulu-valkyria-chronicles-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/710421ec-5d02-4531-a694-7d9295884399.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28185489-107a-4fd1-ac02-326cdbf44698', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 1, '100039468', '戦火の出会い', 'ガリア公国にある国境の街ブルール。自警団の班長を務めるアリシアの元へ不審者の通報が入り駆けつけると、そこに居たのは青年ウェルキンだった。スパイ容疑で拘束するが、彼は妹のイサラに会うために密かに抜け出してしまう。気づいたアリシアが追いかけて着いた先は、なんとガリアの英雄ギュンター将軍の家だった…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/710421ec-5d02-4531-a694-7d9295884399.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a5bb098-b239-42f1-bd7d-1871a0395eaf', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 2, '100039469', 'コナユキソウの祈り', '妹のイサラと再会を果たしたウェルキンは、アリシアと共に、父が遺した戦車エーデルワイス号で家を脱出した。しかし、ガリア正規軍の到着には丸一日以上かかり、もはや帝国軍に街を占拠されるのは時間の問題だった。住人全員が無事避難できるよう時間稼ぎをするため、自警団と帝国軍は激しい攻防戦に突入して…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f3584c0f-c891-485c-af2d-f360887706b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16ec65c2-44aa-4e65-ac01-39bb06e55037', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 3, '100039470', '第7小隊誕生', '幼馴染みのスージーと義勇軍へ入隊したアリシアは、任命式で第7小隊への配属が決まる。なんと隊長はあのウェルキン。一方のウェルキンは交通の要所であるヴァーゼル橋奪還の任務を受ける。反発ばかりの部下たちと信頼関係を築くため、ウェルキンはこの作戦が失敗したら自分が隊を去ることを条件に賭けをするが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/441e24f6-ee9f-430d-b4f4-1f13dfd10019.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54e6e545-e0c1-4d81-8e6f-f8509a45a843', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 4, '100039471', '束の間の休日', 'ヴァーゼル橋の奪還に成功し、ウェルキンに不信感を持っていた小隊メンバーも打ち解け始めた。第7小隊を快く思わない正規軍のダモン将軍は、クローデンの森補給基地制圧作戦への義勇軍の参加を拒むが、帝国軍の圧倒的な力を前に敗北する。その作戦を続行するため次に司令部が命令を下したのは、なんと第7小隊だった…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2713fcbe-a052-475d-bda7-b6fa81331fad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe9f1605-8ad8-4b11-a418-5248440e9e64', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 5, '100039472', 'クローデン奇襲戦', 'クローデンの森へ到着した第7小隊。アリシアとイサラが草むらに怪しい影を見つける。そこで捕らえたのはハネブタの子供だった。少人数で補給基地を制圧しなければならないウェルキンは、生物学を生かして作戦の糸口を見つける。ウェルキン率いるエーデルワイス号とファルディオが率いる歩兵部隊の奇襲作戦が始まった…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b0e6bba-200a-4b87-be1e-1bb51208e64c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38653c7c-0783-4e14-8e5d-caa10f1a944f', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 6, '100039473', '従軍記者、奮闘す!', '義勇軍宿舎にウェルキンを訊ねて、ラジオGBS従軍記者イレーヌ･エレットが来訪する。ヴァーゼル橋奪還や、クローデンの森での作戦の立役者、ウェルキンを取材しに来たのだ。一方アリシアは“変人ウェルキン”の正体がバレては義勇軍の名誉がガタ落ちになると、エレットにウェルキンを近づけないよう必死に振舞うが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ba6478e-a6f2-4177-aa2e-6e315aeab864.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f20b7cc-08d7-4892-8746-9e79d0795c02', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 7, '100039474', 'ダルクスの災厄', 'ダモン将軍のいやがらせによって、戦略的には価値のないバリアス砂漠の偵察を命じられた。苛立つラマールをよそに、この状況を楽しむことにしたウェルキンとファルディオ。アリシアとイサラも、これを機にダルクスの災厄にまつわる遺跡の調査に出かけることになる。その奥には、彼らが思いもかけぬ先客が訪れていて…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/813cbf8c-9ed7-4a0c-b606-bef04b6c6781.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58902464-8280-46f4-b089-5e89691dd724', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 8, '100039475', '紐解かれる歴史', '神殿の新しい碑文の前に、帝国軍ガリア方面侵攻部隊の総司令官であるマクシミリアンと“蒼き魔女”の通り名を持つセルベリアが現れた。突然のことにアリシアが銃を向け事態は一触即発となる。一方、外で帰りを待つイサラとラマール。突然の大きな地響きに驚く間もなく、遺跡のそばに見たことのない巨大な戦車が現れて…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3438e048-7a5f-4f56-a847-a55cd3ef200f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9bc76863-0235-4a18-9dd2-90b6de93a3c1', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 9, '100039476', '蒼き魔女', '帝国軍ガリア方面侵攻部隊本部に、セルベリアの部下として、カールが中央から配属されてきた。同じくして、グレゴールとイェーガーの元へも同様に部下が配属される。そんな中、マクシミリアンが一人で本国へ召集されることになった。この不穏な動きに焦りを感じるセルベリアは、マクシミリアンの後を追おうとするが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/46b8f385-4198-40b5-96d8-8c03cb40d4ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f3ef52e-1d57-4a98-b906-20eca01483b8', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 10, '100039477', '吹雪の夜', '山岳部へ偵察に出たウェルキンとアリシア。しかし山の天候は不安定で、猛吹雪に襲われる。仕方なく二人は、山小屋で嵐が去るのをやり過ごすことに。一方、二人が戻らぬことに不安を隠せない第7小隊の面々。ここは敵の勢力圏内で、二人の帰還を待てる時間には限りがある。指揮権を委ねられたラルゴが下した結論とは…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12aec9a4-7baf-4bfa-af53-78854f75239f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae244e1e-d334-4e99-8449-7001f845b394', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 11, '100039478', '招かれざる客達', 'これまでの善戦を称えられ、ウェルキンとファルディオはガリア公国の公主コーデリア姫主催の晩餐会に招かれることになった。次々と招待客が車から降り立つ中、ひと際目立つ一組の貴族が現れる。美しい妻の笑みがアリシアを見て凍りつく。なんと貴族夫婦は、イェーガーとセルベリアが変装した姿だったのだ…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78941f3a-6d0e-4fe5-a30b-5baaf6eca5a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18210907-bba6-48d9-9380-6da1e1a65b4d', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 12, '100039479', 'さらわれた姫君', 'セルベリアが何の気なしに手にした床に残されていたラグナイトの結晶。それはファルディオがアリシアにプレゼントしたものだった。アリシアの身に何かが起きたことを察したウェルキンたちに、イェーガーはこの城で起きている陰謀について教える。相容れない両者ではあったが大胆にもウェルキンは共闘作戦を持ちかけて…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7135c7be-33d4-4809-a45e-58466bb43846.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09b7186e-012b-4d89-8022-4b76f443edb0', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 13, '100039480', '戦慄の移動要塞', 'ウェルキンたちに課された目的は、装甲列車エーゼルの破壊と、占拠している帝国軍の指令中枢である工業都市ファウゼンの採掘基地制圧、そして帝国の支配の象徴である“ダルクス人強制収容所”の解放である。この作戦への参加に気が重いロージーの前に、ダルクス人レジスタンスのリーダーである、ザカが現れた…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0172517-11f7-47b6-aa92-0c16d6903263.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b1a174a-81c0-4106-ae70-c4c47ef1fb49', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 14, '100039481', 'ファウゼンの選択', '採掘基地の制圧作戦を率いるウェルキンたちは山岳地帯独特の地形に苦しみつつも徐々に戦線を上げていく。そんな中、この作戦がただのレジスタンスによる反乱ではないことを見抜いたグレゴールは、ついに装甲列車エーゼルを発進させることにする。線路に仕掛けた爆弾は、エーゼルの息の根を止めることができるのか…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80dc1428-4b72-40b1-b573-0747d3e88ce9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5422f571-1a1d-406a-8432-1035355cf647', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 15, '100039482', '歌姫の過去', '中隊長のバーロットの計らいで宴の席を設けることに。各隊で出し物を披露することになり、ウェルキンは第7小隊の代表としてロージーに歌って欲しいと頼む。しかしロージーは「ダルクス人の前では絶対に歌えない」と頑なに拒否する。そんな中イサラは、ロージーと少しでも分かり合うために、話し合おうとするが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4dba477a-b3c7-4ef2-9573-5fe7a353cc65.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f66814d-1838-4517-af61-e706cd902dbb', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 16, '100039483', '語られなかった想い', '第7小隊は、皆の気持ちがすれ違ってしまい、ギクシャクとした雰囲気になっていた。中でも、ウェルキンとアリシアのよそよそしい態度を見兼ねたラルゴは、ウェルキンを呼び出す。そこでラルゴが語り出したのは、不器用な男とその親友、そして二人の間にいた一人の女性についての、前の大戦の時の話だった…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41c9b320-c11c-4f75-a6a9-6d603107956f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed7277ba-57cf-49d9-a9b5-60d205a65404', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 17, '100039484', '精霊節の贈り物', '作業の合間に、熱心に針仕事をするイサラ。大切な人へ贈り物をする精霊節が近づいているのだ。そんな中、第7小隊に次の指令が下される。マルベリー海岸にある帝国防衛基地の殲滅で、非常に困難な作戦だった。先陣を切るのは第7小隊。戦闘を目前に控え、隊員たちはそれぞれの思いを込めて精霊節の贈り物をすることに…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2040119b-72ad-461c-bd05-200c9dda90ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a018e713-eaef-4965-8dea-34680e4d9aea', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 18, '100039485', '八月の雨', 'アマトリアン基地は悲しみに包まれていた。ロージーは医務室で憔悴し、小隊メンバーもこの悲劇を受け入れられずにいる。そんな中、ウェルキンだけが淡々と仕事をこなし、事態を冷静に受け止めていた。いぶかしむ面々。そこに追い討ちをかけるように、正規軍のダモン将軍が現れる。イサラを侮辱し罵声を響かせるが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a8be291-9ff1-48c2-a2ba-906f372d542c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54deb400-0e72-4193-85fb-6fb09015a36b', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 19, '100039486', '涙', '隊員たちの心配は伝わらず、独り心を閉ざすウェルキン。そこに更なる出撃命令が下される。攻略の目的地は、ウェルキンたちの故郷であるブルール。バーロットのせめてもの心遣いだった。新たに入隊したザカと第7小隊は戦地に向かう。その頃、ファルディオは書庫でヴァルキュリア人に関する文献を読みあさっていた…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c301ab4c-09ec-4c95-928a-fa287541a543.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('662652f5-01d6-40ff-9dc9-d93380189489', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 20, '100039487', '愛しき人', 'マクシミリアンは本国から指揮権の剥奪を言い渡され、ガリアに総力戦を挑んできた。決戦地ナジアル平原で、士気も高く戦地に立つ第1小隊に、対するはマクシミリアンが指揮する大型戦車ゲルビル。激戦の中、蒼いオーラに全身を包み、巨大な槍と盾を手にしたセルベリアが、ファルディオたちの目前に立ちはだかり…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7addb30e-8710-4b7f-a1f5-8e5fda26940c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3b0a61a-b2a8-4914-95a7-a14c7477ec19', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 21, '100039488', 'はかなき絆', 'セルベリアの強大なパワーにより、主力部隊は甚大な被害を受けた。新たに出撃命令が下された第7小隊に、アリシアまでもが瀕死の重傷を負ったとの知らせが入る。動揺するウェルキンたちだったが、帝国を止めることがアリシアを護ることだと出撃する。そんな中、昏睡状態に陥っているアリシアの元に、ある人物が現れた…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d343aad-9c32-4ece-b6f8-855669f21d9d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01472d13-c011-4188-9581-1bea0051b918', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 22, '100039489', 'とまどい', 'ナジアルで辛くも勝利を収めたガリア軍。しかし、アリシアは正規軍の監視下に置かれてしまう。心配するウェルキンだが、面会謝絶を言い渡され未だ会えずにいた。収監されたファルディオを訪ねたウェルキンは、親友が犯した衝撃的な事実を知る。そこへ追い討ちをかけるように、第7小隊隊員たちから話があると言われて…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67d136b4-4f6b-40e9-8763-7428d9cdca30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('015443dc-900f-48bd-8bd8-49df7908b8db', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 23, '100039490', '愛のかたち', 'アリシアは階級が大尉になり、正式に正規軍所属となった。第7小隊から離され、次々と戦いに駆り出される。一方の第7小隊の面々はアリシアと過ごしてきた日々を思い返し、最後に傷つけてしまったことを悔いていた。そこに次の任務が下され、その内容に隊を衝撃が走る。アリシアをウェルキンは引きとめようとするが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7414c4a-2885-4af3-ba9f-cb842fac64a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a59e3d3-a2a7-4d5a-9b45-168e62febe69', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 24, '100039491', '決意', 'アリシアの取り計らいにより、第7小隊はランドグリーズまでコーデリア姫の護衛任務についた。戦場に残るアリシアを想う隊員たち。一方、ギルランダイオ要塞ではガリア正規軍とセルベリア率いる帝国軍の決戦が始まった。その頃、マクシミリアンは極秘会談を申し入れ、コーデリア姫との謁見を果たす。その真の目的とは…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4f568ac-a692-4563-882e-91d5c0d7c492.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68abdc17-9647-4c0b-a558-d6d509b4807c', 'b50af628-aee4-4edc-b387-ecd48dc0bab6', 25, '100039492', '護るべきもの', '首都ランドグリーズへの総攻撃を開始した、マクシミリアン率いる帝国軍。そんな中、第7小隊の元へ謎の大爆発により正規軍が壊滅したという一報が届く。果たして最前線にいたアリシアの運命は…。一方、マクシミリアンは永きに渡って隠され続けてきたランドグリーズ家最大の秘密、ヴァルキュリアの聖槍を手に入れる…!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13a438f9-f58e-4487-9796-a8ac0dcb6034.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2efe77ac-149e-4943-a503-9740a7160456', '戦隊レッド異世界で冒険者になる', '', 'hulu', 'the-red-ranger-becomes-an-adventurer-in-another-world', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4855ca3-0231-42e6-862d-f841486ec56e.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 180052, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', '2efe77ac-149e-4943-a503-9740a7160456', 'hulu-the-red-ranger-becomes-an-adventurer-in-another-world-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9afaff04-6ddc-4390-a1c4-c87854def50c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60988957-4be4-4088-bbbf-0d5cfc355e65', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 1, '100213122', '戦隊レッドと魔法使い', '魔法使いの少女《イドラ･アーヴォルン》は、屋敷で冒険者の腕試しに明け暮れる日々。結果は冴えない者ばかり。しかし、そこに期待の新人と名高い《浅垣灯悟》がやってきた。謎にキレキレな動きやポーズと共に見せる彼の実力とは…!?', '2025/01/18 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9afaff04-6ddc-4390-a1c4-c87854def50c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('215d1f97-e601-4aa6-99ff-1895da208bdb', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 2, '100214293', '戦隊レッドと冒険者達', 'イドラと絆を結んだ浅垣灯悟は、冒険者ギルドでパーティー登録をする。この時にイドラは、元《王家の杖》の父親は「腰抜け」だと冒険者達から侮辱を受ける。一触即発の事態に灯悟は、決着はクエストでつけようと言い出し…!?', '2025/01/25 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/195c52fb-23bb-4387-8ace-a44102b96cff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b5a1daf-0f2e-4c88-9cba-4ab0fd68f757', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 3, '100214807', '戦隊レッドと勇者と姫様', 'アヴァルロスト皇国の王女《テルティナ》と、その従者《ロゥジー･ミスト》がやって来た。彼女たちはイドラに《魔力の種》の分析と回収の協力を依頼するが、ロゥジーは灯悟の同行を認めたくない様子。そこで二人は戦いでお互いの力を示すことになり…!?', '2025/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0e9aefa-e982-4d20-909f-412e295118c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70710511-2dd0-498f-b8f8-3a420e086ba3', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 4, '100216181', '戦隊レッドと絆の剣', 'グロッサ率いる反抗軍によってピンチを脱した灯悟たち。やはり《特権魔法》によってアカリナを支配する領主ルルグアットは強敵だ! 再戦に向け練った作戦は、灯悟とロゥジーが連携し戦うこと。でも、二人の相性は最悪で…!?', '2025/02/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e83e2e10-58cc-4a29-b745-a8740b58dfc8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('022d206e-2e30-47bf-9678-f677721f9634', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 5, '100217050', '戦隊レッドと魔王の血族', '《魔力の種》が暴走し巨大化したルルグアット。灯悟たちは《マキシマム･キズナカイザー》を爆現させ、敵と共に大空へと舞い上がる。《魔力の種》を止める手段だとテルティナが見せるのは、なんと《特権魔法》で…!?', '2025/02/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/005f8214-5e6c-4a08-9e8b-e5af025f1efc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84848849-1b7a-4ca0-8847-a1779bcef261', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 6, '100218310', '戦隊レッドと魔導士の夢', '魔王族の《常笑のアブダビ》を退けた灯悟たちは、現《王家の杖》のシャウハに導かれ《魔導塔》へやってきた。先代と当代で、イドラとシャウハそれぞれが目指す魔法の使い方への理想像は正反対。対立する二人に灯悟が放った一言とは…!?', '2025/02/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee097937-e278-4bd3-a33f-935c352e90ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('658b60c8-3b8c-4bac-a964-7c746a10afb3', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 7, '100218924', '戦隊レッドと太陽の森', '《魔力の種》の情報をもとに、太古のエルフの聖域《太陽の森》へ向かう灯悟たち。巨大なサボテン地帯で突如現れたのは森のエルフ。瞬く間にイドラが攫われてしまった! さらには行く手を阻むべく、太陽の森の防人《アメン》も現れて…!?', '2025/03/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14181adc-ba6c-42be-a418-2927081c4dec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('305e2cd7-953c-4eb4-82fc-0bbc1e4162bb', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 8, '100220112', '戦隊レッドとバンソウキラー', 'ラーニヤの眼に淋しさを見た灯悟。過去には親しい間柄だったアジールを打ち倒すしかないと悲観しているようだ。しかし、そこで敵対してぶつかり合った絆こそ、前よりもっと固い絆になると説く灯悟。この言葉の裏には自身が体験した過去があるようで…!?', '2025/03/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8c673bb-8742-4f25-a549-075c1d025618.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ace95ddc-913a-443f-be45-c9cec903ef0a', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 9, '100220784', '戦隊レッドと心の仮面', 'アジールが手下と共に、太陽の森へ攻め入って来た! 彼らの《特権魔法》を前に、テルティナやロゥジーは捕らえられてしまう。大ピンチの太陽の森。灯悟とラーニヤはそれぞれ変身し、アジールたちに立ち向かうが…!?', '2025/03/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9db8a14c-947e-4275-a9bc-61097376cb55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a93df22-5512-4fcf-9635-8476528a9c44', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 10, '100221793', '戦隊レッドと苦しみの仮面', 'ラーニヤが倒れ、《アメン》の力がアジールの手に渡ってしまった! 彼は《特権魔法》と2つの強大な力を使い、レッドの前に立ちはだかる。「夢」を一人で叶えようと支配の力を振るうアジール。彼が目指す「夢」とは一体…!?', '2025/03/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e647006-22ef-4938-ae63-b117d655b68a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00dc5319-a81a-48f1-9a93-c8e39afac7cc', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 11, '100222468', '戦隊レッドと新たな力', 'アジールは砂嵐へと姿を変え、その力を暴走させていた! 4人との絆を合わせ、遂に100%の出力となった《マキシマム･キズナカイザー》と共に、レッドはアジールを追う。太陽の森へ迫るアジール。果たして彼を止めることは出来るのか…!?', '2025/03/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/810645fa-ceea-47dc-b051-31182f605ffd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7cb92db1-3136-425f-8a4b-1a0ac13097d7', 'ceb2fb14-ebb7-4c0e-a949-552cfd6c47b9', 12, '100223342', 'キズナブラック', '【最終話】アブダビとヴィダンという強大な魔王族二人に立ち向かうため、灯悟は捨て身の最終手段に出る。彼が絆装チェンジした姿は、熱き友情の戦士《キズナレッド》ではなく、深き執着の戦士《キズナブラック》だった。全てを焼き尽くす漆黒の業火が戦火に舞う! 果たして、彼らの戦いの結末は…!?', '2025/04/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bc8f7d3-3cb2-47f2-9e76-0e5ad7fe7c69.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e831b2f4-28a5-4c44-9077-8c68246cd7d3', '戦姫絶唱シンフォギア', '', 'hulu', 'senki-zesshou-symphogear', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50025020_series_art__338x600_senki_zesshou_symphogear_305d671393117c750a0a566393f03c5d.jpg?w=331&h=447&p=t', 'hulu', 2012, 0, 1, 'FINISHED', NULL, 11751, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('73b4705d-9fb3-42f9-807d-bd991ccb443a', 'e831b2f4-28a5-4c44-9077-8c68246cd7d3', 'hulu-senki-zesshou-symphogear-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4b3aeaf2-f999-4250-baff-34aa57dfca1d.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0123a190-4e45-4d03-8c65-a5136c8b637f', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 1, '60673424', '覚醒の鼓動', '立花響は、この春より親友の小日向未来と共に、私立リディアン音楽院に通うこととなった。それまで音楽とは無縁の生活をしていた響がなぜ音楽学校へと進学したのか? それは2年前、認定特異災害ノイズに襲われたライブ会場にて、アーティストデュオであるツヴァイウィングの戦う姿を目の当たりにし、果たしてそれが現実の光景であったのか、真偽を確かめたいという思いが理由のひとつであった。平穏な新生活を送っていた響であったが、またしてもノイズの脅威に晒された際、その胸に抑えきれない破壊衝動が湧き上がるのであった。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4b3aeaf2-f999-4250-baff-34aa57dfca1d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f8826ff8-c4e7-448f-b737-8124e8d003ad', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 2, '60673427', '雑音と不協和音と', '胸に浮かび、口ずさんだその旋律は、明日に命を紡ぐ歌か、それとも―。力の使い方も、その意味も知らないまま、戦端は無情にも抉じ開けられていく。今はまだ、軋む音を立てながらギアは廻り、少女たちの物語は、ここからはじまる。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1a0b2a78-6d11-4270-a1d7-cdf75b881505.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1547709-1585-49f4-8604-f86cd48ba4ad', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 3, '60673436', '夜にすれ違う', '差し出した手は拒絶され、突きつけられた切っ先はどこまでも鋭く冷たい。少しずつ、だが確実に心を摩り減らしていく響。翼もまた、己の弱さに誇りを蝕まれていく。再び湧き上がる衝動は、より確かなものへと移ろい、鎌首をもたげた蛇は、すぐそこにまで迫り来る。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/785ff3d3-4a59-4e24-829d-0756228824f9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ca74986-c9d3-4a79-b85b-2ccf2ecc0340', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 4, '60673434', '落涙', '胸に去来するは、いつか見た光景。想い出の残滓を奪わせまいともがく翼だが、届かない現実に追い詰められていく。やがて激突の終着を、月明かりが照らしだす。戦いの果てに翼は涙し、響もまた涙する。今はまだ、流した涙でしか明日を守れない。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a4cae6cc-e397-4dcd-bcef-7f12a555b321.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92273005-9d79-4916-a362-e56a9e2372a0', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 5, '60673435', 'なお昏き深淵の底から', '闇の奥底に輝く悪意は、明日を見失った少女に向かい、痛みこそが絆と囁く。静かに広がる脅威を知る者は無く。知る時はもう、引き返すことすら許されない。共振と共鳴、凶暴なる咆哮。またひとつ君は、君を喪失していく。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ca00dd9d-ec50-4513-814e-c2a63e2eefb1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad6bc8d3-ab94-4a57-820e-f85816a32542', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 6, '60673439', '兆しの行方は', 'すれ違いは、わずかに距離を縮めども、再び離れて心を苛む。同時多発のさざ波が、いつかの可能性だとしても、今はただ一言、搾り出した言葉が全て。足りなくとも全て。求めて伸ばした手からこぼれ落ちる光。それでも君は諦めない。胸の想いを届けるために。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e84dd242-720c-4c04-a1de-bb56c8e8dcbf.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fbd4591-87c1-4f96-acd0-965be76129f6', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 7, '60673423', '撃ちてし止まぬ運命のもとに', '少女の咆哮は慟哭となり、錯綜する迷図に谺する。戦うことでしか変えられない現実と、戦い続けてなお、何も変わらない現実。そして誰かを傷つけるたび、君の心も傷ついていく。偽りの姿と力では、この向かい風に抗えない。全部脱ぎ捨て、本当の自分でこそ踏み込める。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c98ad0f6-5d5e-4dd2-9ff3-16a250a5c499.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea3d1f54-5381-4cdd-a5ca-f530ef2889eb', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 8, '60673428', '陽だまりに翳りなく', '切り取られた瞬間は一葉となり、想い出と加速する。そうなる前に、そうさせないために、明日を見失った少女たちは、声無き言葉で、気持ちを確かに伝えていく。いつかの言葉が心に灯り、踏み出す一歩に力がこもる。この道に進むこと以外、答えなんてあるわけがない。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/80279fce-f9e9-47d5-9bfb-5de7e1385151.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc2e3c33-d41c-4587-9817-9fe8dc02bde8', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 9, '60673432', '防人の歌', '知らず口ずさんでいたあの旋律は、果てしなく広がる戦場の地平に置いてきた。誰よりも速く、どこまでも遠くと求めるあまり手放したもの。だがそれが、暗闇を切り拓くための灯火だとしたら。優しい声はいつだってわたしを導き、背を押してくれた。もう逢えないことよりも、出逢えたことが嬉しい。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a19fcc9f-66fd-4b66-9362-626f03d96503.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f3ef1f7-8f42-4eeb-86bf-41726384f01b', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 10, '60673416', '繋いだ手だけが紡ぐもの', 'いまだ見通せぬ暗闇は、容易く銃火に切り裂かれる。広がる血溜まりに死にゆくモノ、誕生するモノ。流転、急転する事態。やがて不安から焦燥へ。それでも彼女が握る、「アームドギア」がある限り―。ガレキの只中で拾い上げた夢の欠片。傷だらけでも、このてのひらに決して消えない星がある。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f4ff740f-607c-4fee-a076-8ab6c66b08a1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('396d26a1-f338-4ae3-ae10-80f255a4e9a4', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 11, '60673438', '月を穿つ', '終局へと向ってひた走る少女たちに、砕けた世界はひとつに繋がると亡霊は嗤う。やがて一途な胸の内は、最速で最短で、真っ直ぐに一直線に解き放たれる。想いが地より屹立し、天に届かんとする時、帰るべき日常は音を立てて崩れ去る。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/05687882-37c0-4e82-b81e-dd7a6d182a1e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('701c914e-c449-415f-a282-9ce1079522b8', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 12, '60673437', 'シンフォギア', '痛みだけが心を繋ぐ絆と疑わず、ただひとつの真実と貫いた、数千年の想いは重い。鍛えた力を以ってしても、生命を贄と差し出しても、易く覆せないほどに。すべてが壊れて砕け、灰燼と帰していく。それでも―少女の歌には、血が流れている。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/00129773-29fa-4d72-9442-8d691b0f6e5f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('303ecd5b-3b09-4893-8189-9cf4cac96606', '73b4705d-9fb3-42f9-807d-bd991ccb443a', 13, '60673429', '流れ星、堕ちて燃えて尽きて、そして―', '【シーズン1 最終話】積年の妄執蟠る胸に、突き立てられるアームドギア。いつの日か、人の間に絆が結ばれることを願い、希望のかけらは託される。やがて、夜明けを告げる鐘の音は空に奏でられ、鳴り響き渡る。この身朽ち果てても、伝えたいものがある。響け生命の絶唱―彼方、羽ばたいて…。', '2016/02/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d8ab24ef-a4ca-4497-a88b-e2f13d02a12f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8111e3d1-0c58-4cb1-b11e-a2cc0f285f12', '戦姫絶唱シンフォギア AXZ', '', 'hulu', 'senki-zesshou-symphogear-axz', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2892178-7838-455a-8afd-0668c24d07a3.jpg?w=331&h=447&p=t', 'hulu', 2017, 2, 1, 'FINISHED', NULL, 21672, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d526c61b-91d8-4526-acd5-81b4c88fe826', '8111e3d1-0c58-4cb1-b11e-a2cc0f285f12', 'hulu-senki-zesshou-symphogear-axz-s1', 'シーズン4', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db60e9fa-25f1-4082-a743-f7e69243dc08.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f076e4a-a4c3-4705-bfa7-7ffafae3c049', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 1, '100004624', 'バルベルデ地獄変', '秘密の花園は暴かれて、命が煌めき咲いて散る。花盗人に罪は無し。すべては理想を為すために。信じた正義を、握り締めて。羽撃きは今日を裂き、残酷な明日に向かって飛翔する。遠き、遠き―そこにはきっと、置き去りにした昨日がある。', '2017/07/22 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db60e9fa-25f1-4082-a743-f7e69243dc08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eae6bd03-a5b2-4e5b-9e27-50200ca56b72', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 2, '100004625', 'ラストリゾート', '一瞬を、永遠に変えるとキミが誓う。だから傷みに涙しても、拭って払い前に進もう。この絆こそが旋律―歌に束ねて空にぶち抜く。正義を執行する刹那、銃爪に掛けた指が震える。迷いながらもがきながら、それでもまだあきらめたくない。', '2017/07/22 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4450216a-c194-4dd0-8252-a47f7609c8b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b33ed6e7-a310-4fbe-a91f-5907439ba5c3', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 3, '100004626', '歯車が描くホロスコープ', '花火があがると狼煙もあがる。舞台の幕も跳ねあがる。星の瞳の人影は、久遠の彼方へ想いを馳せる。恋心の高鳴りこそが、信じた夢と疑わず。囚われた檻の只中で、呪いの剣は抜き放たれる。無邪気に言祝ぐその意味を、知る者はまだ一人きり。', '2017/07/22 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db45a084-fe9f-4137-a8e5-07b8b77fb210.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cb74fa4-f9de-4537-9b6a-bb9ed50765da', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 4, '100004697', '黄金錬成', '激突の瞬間は突然に。だが決着は、いつしか必然に。死線に散らす火花の瞬きこそが一縷の望み。然してその一撃は、夜明けにも似た輝きと共に放たれる。狂熱の骸に持ち込まれるのもまた、過ぎ去りし狂熱の骸。胸に染み入る言の葉は、振り返った時にこそ意味を成す。', '2017/07/29 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61e34154-f807-47f7-8910-d22d47fbb253.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4766cb59-6303-4986-9f1b-837b19b324d5', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 5, '100005041', '虚構戦域に命を賭して', '互いの胸の、想いを徹すに勝利は必定。だとしても―迫り来る不可避の戦いに、勝たなくてもと君は告げる。その想いを知るからこそ、振り向かないまま駆けていける。それこそが錬金思想と秤にかけ、怖れを殺して戦場に立つ。いつかに聞いた「らしく」ある事を自分の武器と携えて。', '2017/08/05 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c63a930-68c6-4f3a-b436-cac32ed40956.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf0797b4-3a9c-4868-b0e7-9e58bd0834be', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 6, '100005724', '決死圏からの浮上', '真綿で縊るかの如く、絶命包囲が徐々に狭まる。進退維谷まる只中にあって、迫撃するはあの日の言葉。キミがままに伸ばす手は、何を掴んで何を零すか。不退転の決意を纏う者たちが、遺址の力に馳せる想い。遠く求めた理想に焦がれ、アクシアの風が吹き抜ける。', '2017/08/12 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e95bca76-2a02-47d3-b617-35b2373ab473.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21f739db-583b-4cb1-bb31-d6c51793577a', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 7, '100005957', 'ARCANA No.00', '握り合う正義の激突に、いつかの想いが去来する。変えられぬ昨日に今日を蹂躙しても、明日をこの手に。命を礎に求めた力ならば、届くと信じて疑わず。赤き輝石に抗う手立てもまた、もうひとつのキセキである。キミの胸から生まれしは、熱き歌ばかりでないからこそ。', '2017/08/19 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ba4f89b-2062-4180-89dd-4ea1c52caa76.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7666b063-cc7b-4931-819f-6e487b34a8d5', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 8, '100006339', '過去と未来の狭間で', '開闢の刻はまもなく迫り、選択をキミは強いられる。犠牲でないと嘯いても、唇の震えは隠せない。悟られぬように噛み締めた、正義の味は鉄錆にも似て。この瞬間を変えてみせると、踏み出したのは小さな一歩。失くした笑みを取り戻すため、勇気を鎧って決起する。', '2017/08/26 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06a3f139-1c16-46ea-aaec-389c3708e0f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b23cc7bd-47f0-4133-8ec4-c7ee9d8c1ec3', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 9, '100006662', '碧いうさぎ', '擦過する理想が不協和の火花を散らし、夜に瞬く。命脈が紡ぐ其は、門を越えて来たりし力。誰が為にあるのではなく、人形の見た夢にこそ。白い壁も天井もなく、果てなく広がる世界だからこそ、疾走する純心は、見失った太陽を求めて彷徨う。', '2017/09/02 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17adbe5e-0c86-4f6a-98cb-6d0cfdd4c9e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c988cd15-ada6-4ddd-9880-4b699aa86244', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 10, '100007352', 'アン･ティキ･ティラ', 'まだ見ぬ世界を照らす為、命を燃やすか死を灯すか。互いが拳に握りしは、形の違う正義と正義。相容れぬからこそ咆哮し、ならばこその歌がある。歯車は軋み、照応する宇宙観を胎にカウントダウン。轡を並べて見据える先で、人の形の悪夢 (ユメ) が嗤う。', '2017/09/16 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/824ad1b0-7b15-4237-82a0-1cd3b59c5f20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e025499b-c6fd-441a-959d-861e88405a09', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 11, '100007576', '神威赫奕の極みに達し', '叛逆するその姿は、いつかに出逢いたかった背中。今日の自分はひとりで立てる。ならば明日の誰が為に。この手に勇気が花咲いて、無限の鼓動に―我儘に。在り方すらも捻じ曲げる、重い想いはすなわち呪い。果たしてそれは、誰を殺さんと握られた拳か。', '2017/09/23 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8429c6bb-1117-4372-98b6-19688dbcad6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30be13f2-9da2-4678-9458-b8c46831ffd9', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 12, '100007887', 'AXZ', '怖じる世界は紛糾し、少女への殺意は熱を帯びる。あれなるは災害。人に仇為す波旬の仕組み。輝く姿は異形なれど、回天の祈りを込めた装束にも似て。反吐が出る侮辱の空に見上げた光。尽きて滅べ、諸刃ごと。命は贄に―礎に。一にして全なるモノが死を灯す。', '2017/09/30 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2ddd81f-a361-440e-87d6-17d7f8fb88f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba99081e-e141-4001-98e0-28e7138c0a4f', 'd526c61b-91d8-4526-acd5-81b4c88fe826', 13, '100008123', '涙を重ねる度、証明される現実は', '【シーズン4 最終話】命燃え尽きて倒れても、終わることのない歌がある。錬成された黄金が照らす、嘆きで霞む未来。掲げよう、激唱と旋律。前線銃後の―最終抜剣 (ラストイグニション)。泥濘のごとき安寧は、澱みに浮かぶ束の間の幻想 (うたかた) か。やがて突きつけられる、何処までも残酷な結末 (termination)。', '2017/10/07 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eeac6a79-d9cc-4a03-b654-0788367d4925.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('80ce63fa-4c51-47e5-9bd3-296c1373324b', '戦姫絶唱シンフォギアG', '', 'hulu', 'senki-zesshou-symphogear-g', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50025021_series_art__338x600_senki_zesshou_symphogear_g_5a9dc5014238242ac0f2d6c268da54f8.jpg?w=331&h=447&p=t', 'hulu', 2013, 2, 1, 'FINISHED', NULL, 15793, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a6278c65-f3ae-4bf2-9750-036205ad3507', '80ce63fa-4c51-47e5-9bd3-296c1373324b', 'hulu-senki-zesshou-symphogear-g-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a94d2a77-828d-4353-b5f5-6127b27d2f73.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44ef96db-0aaa-44f0-b4da-0a6af54cf759', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 1, '60673417', 'ガングニールの少女', '欠けた月が睥睨する世界に迫る終焉の刻。壇上の共演は競演となり、饗宴はやがて狂宴へと移ろう。正義の為にと吠え叫ぶ者の胸中は、果たして。それは、蔓延る悪を貫かんとする決意の穂先。そして、背負った悪を貫き徹すと誓った無垢なる覚悟。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a94d2a77-828d-4353-b5f5-6127b27d2f73.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f4da958-f76b-4cf0-84ab-2d4b5ddedf68', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 2, '60673419', '胸に力と偽りと', '歌を信じ、脅威に満ちた世界を変えると誓った二人。だが、決別の瞬間はあまりにも早く、防人は満ち足りた日々を棄てるのも厭わず、命奏でて天に羽撃く。Gの咆哮―猛る虹色の輝槍は、覆う闇を突き穿つ。あの日、手を繋ぐ少女が起こした奇跡の再現は、夜明けの光となりうるか。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f4e919ce-40be-44ec-a252-d62ea30952df.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd1b5de0-65f9-447e-a855-ac2d2ee07660', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 3, '60673422', '終焉を望む者、終焉に臨む者', '覚醒の鼓動―そして、広がる新天地。その道を征くと誓った少女たちなれど、怒りに傷み、痛む手では誰の手も繋げないとまだ知る由もない。通した袖の温もりは、昨日に馴染めなくても確かな今日。たとえそっぽを向いたとしても、君の明日は君が見つめる先にこそ。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/30c3ca83-1f37-463f-89de-051b96019e59.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64d42970-6a92-49db-b7cc-c18a249d47be', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 4, '60673426', 'あたしの帰る場所', '解り合えなくとも、通じ合えたはずであった。だから言葉より強いモノを求め、ゆえに拳を固め穂先は閃く。胸に痛みを覚えても、立ち止まることなど許されない。背中を押されて飛び出したのは、知らない素振りを続けた世界。どこまでも澄んだ高い空に、はじめての笑顔は隠せない。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1ff82ad3-6d82-4097-83a2-8ddadecf2a4d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f91bdd49-9db2-4811-b189-7cbfd8ba77f8', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 5, '60673430', '血飛沫の小夜曲', '自分で決めたことだけど、流れに逆らうだけの力がなく、踏みにじられる悲鳴に、ただ嗚咽を重ねるばかり。残された形見にすがってみても、この身の震えは収まらない。遠い日に深紅の涙は落ちて、今宵に激しく雨と降る。月明かりの下、世界の明日を語る君にこの残酷は心地いい。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/723de6cc-473d-45a8-a0cf-36491f26f05e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9619bde-d13a-4afb-a8d0-9ade0bcfbe0f', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 6, '60673433', '奇跡―それは残酷な軌跡', '繋いで束ねる力は失われ、彼我にて不和が高まる中、見下ろす月は口づけを求め、やがて歌は眠りにつく。正気では立てぬ舞台に翻りしは、君が構えた胸の覚悟か? 知らず叫んだその言葉は、どこまでも正鵠を射た無慈悲な真実。ひとつを喪失したのではない。これからすべてを喪失するのだ。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/435ad514-0f7f-4629-9704-c0a6959f5c6f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69e150a6-ccda-46b3-bfd1-46068c8bd10b', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 7, '60673420', '君でいられなくなるキミに', '滾る想いが力と変わり、熱波となって吹き荒ぶ。たとえ拒絶に振り払われても、君は繋ぐべく手を伸ばす。それが、昨日と決別する確かな一歩になったとしても。暴かれて晒されて、いつしか事態は真実へと近づいていく。だが、真実こそが求めた正しさであったためしは少ない。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fbfee504-0a13-4985-858e-fd52a125796e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa482712-2485-42e7-964a-5f3bf4f7c0ca', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 8, '60673440', '繋ぐ手と手…戸惑うわたしのため…', '行かせないことが守ることだと疑わなかった。だからこの手は、永遠―それよりも長く握っていたかった。遠く、遠くに零れていく。君がこの手から零れていく。あり続けることの苦悩と変わりゆくことの恐怖。独奏のあるがまま往く道で、天となることも厭わない。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7a44d277-d4fd-4838-8b9b-0c9be465529e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7dbf671-5398-4e24-ab60-14e38d45e5e6', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 9, '60673415', '英雄故事', '誇りある君は、義のために血を流すことも厭わない。其は命かけること。ゆえにこの魂は獅子の如く。失うことを恐れずに君は前を向け。高みに輝く夢を掴め。かつてそう呼ばれた者たちは、奈落の只中でも空を見上げた。望まぬ未来が待ち受けようと、覆すべく瞳逸らさない。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/dccb44d6-4486-460a-81b9-66f4661c33a6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13199ea9-1010-40c6-97b3-39b47b8a5e02', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 10, '60673425', '喪失までのカウントダウン', 'たとえ命枯れても、温もりが残し伝えるものはきっとある。ひたむきな願いは祈りとなり、想いは激突して血を流す。この拳も命もシンフォギアなら、未来に捧げる贄に相応しい。また会う日などないと知る君に、笑顔の「サヨナラ」は唄えない。あとのすべてを仲間に託し、ナミダ殺してその道を駆け抜ける。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/89925c8f-8413-4834-8f1f-4bdf00dabd59.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c7b6dda-e4b5-4fdd-9f9b-55c2d122fafb', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 11, '60673421', 'ディスティニーアーク', '見えない明日に踏み出せるのは、ここで出逢った意味があるから。さよならという言葉はきっと、終わり告げるためじゃない。別れの痛みより、めぐり逢えた奇蹟だけを抱きしめて、その先へ。陽だまりと温もりと厳しさも繋がりも、ぜんぶくれた場所を守る為、大好きな制服に二度と袖は通さない、通せない―ダカラ行ク。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/29a5cc6d-edc3-43e0-934c-9bf884e8df98.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eecb42f6-8da4-4a36-9a21-884717695ebd', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 12, '60673418', '撃槍', '大好きの、その一言さえも届かない天地に擦過する女神の刃。もつれた想いが綾となり、見通せないのが現実だとしても、二人はただ調べ歌い、錯綜する世界を伐リ刻み、切り刻む。本気の偽善と本気の嘘。鏡合わせの想いはついに対峙して血を流す。裸で叫ぶその歌に、この星の明日はまだ―生きるのを諦めない。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c0c9a881-aa93-41f0-b80f-0910380cc4c8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c478f8c-d28b-483a-853e-b7d5e56946ef', 'a6278c65-f3ae-4bf2-9750-036205ad3507', 13, '60673431', '遥か彼方、星が音楽となった…かの日', '【シーズン2 最終話】奪われたのでなく、解き放たれたと知った君がついに立つ。倒すべき悪の潜まぬ闇を貫くは、壊れやすいまでに純な輝き。英雄でない者だからこそ、その手に零さず掴める世界がある。寂しさは優しさへ…傷痕は、強い絆結ぶ証になる。この胸の希望に終わりはない。飛び立とう、声を重ねて―空が待っているから。', '2016/02/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/774d953c-6f1b-4427-b9e7-9a990cda2a4e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d777ea01-3e03-48b4-8c58-3921fafee1dc', '戦姫絶唱シンフォギアGX', '', 'hulu', 'senki-zesshou-symphogear-gx', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50022552_series_art__338x600_senki_zesshou_symphogear_gx_8692cac92165dfca4bf62a7ee7e2a03b.jpg?w=331&h=447&p=t', 'hulu', 2015, 2, 1, 'FINISHED', NULL, 20560, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f52d1650-7bc5-4957-b529-5d0282fce94a', 'd777ea01-3e03-48b4-8c58-3921fafee1dc', 'hulu-senki-zesshou-symphogear-gx-s1', 'シーズン3', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ba86bd16-5ecc-447d-a19b-e283d211145f.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('547c2e75-7170-4320-93b6-d1cb27c990b0', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 1, '60590110', '奇跡の殺戮者', '燃え尽きそうな空に歌は響き、明日を輝かす種火となる。 拳も命も鎧い支えるは、胸に揺れる小さな奇跡。 だが、逆巻く炎に涙する瞳は、そうと知ってなお対峙する。 鎮魂の夜を急ぐ血塗られた魔縁と、かけてもつれた抒情詩。 耳をすませば遠からず、世界を壊す―歌がある。', '2015/07/29 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ba86bd16-5ecc-447d-a19b-e283d211145f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96ab657e-00c1-48a9-8014-d0bd6dd1ea68', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 2, '60591959', '世界を壊す――その前に', '琥珀の記憶を烈しさと換え、彼方からの迷い子が吠え猛る。託されたモノは重い―だからこそ譲れない…想い。向かい抗う胸に答えはなく、問い掛けは空しくすれ違う。それこそは寄る辺、絆、映し身にしてもうひとりの自分。大切だからこそ壊れやすく、喪うことに震えて怖じる。', '2015/07/29 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0dcc29e7-9b0d-4aba-a3db-9227509fc9f3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc5e4402-9f38-44d6-aec0-e3baef5e32b0', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 3, '60594296', '装者たちの黄昏', '駆け抜けた先に明日があると、疑わなかった昨日の自分。今日の胸に、力と想いは屹度ある。無いのは繋ぐ手段だけ。匣の蓋が開かれるまで、その身を削って火花を散らす。逃げているわけではない。なれどこの目は逸らすばかり。武器を握らぬ手だからこそ、傷つける事に怯えてしまう。', '2015/07/29 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/feb76704-62e0-4973-b21f-a27e079edfd5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52ef4600-71a4-4fd0-b47d-6a6fecbe4c12', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 4, '60597576', 'ガングニール、再び', '想いと言葉に嘘はない。それでもこのままではいられない。さらなる一歩を踏み込むために、手にした力を恐れない。響け響け、この胸よ。熱く歌う、この胸よ。信じて握るは拳にあらず。戦ってでも欲しい君の真実。今はまだ見つからなくても、譲れない道についに立つ。', '2015/08/05 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b84201d3-ef85-4eaa-9ea2-17f656b8a7ef.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64858fdc-24a5-40ae-bbe4-a15481085bb5', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 5, '60600890', 'Edge Works', 'この痛みはあの日に迷い―独奏してしまった臆病者たちの償い。小さな力は死地に舞い、命を火花と散らして弾ける。ふたりでなら怖くない。だけど、ひとりを喪うことだけは…。疑われることを怖れずに、真っ直ぐ飛び込んできた者がいる。そしてここには、信じることを怖れずに受け止める者たちがいる。', '2015/08/12 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f8877145-51dd-4c97-af9d-dbbec196a0bb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28386bce-ce1f-4e6f-9b7b-6e84cd4840a4', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 6, '60602027', '抜剣', '何故、どうしての問い掛けに、忘れたと答えは吐き捨てられる。誰かを守る奇跡たらんと、願う少女の目の前で、言祝がれた悪意は、墜ちて燃えて尽きて、そして―君は知る。だからこそ怖れずに、信じて疑わない。友は知る。傷つき傷つける痛みに、君が隠れて泣いている事を。', '2015/08/19 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0a6dbff8-cbf8-40b9-aeae-187154420b28.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15a09a81-efc3-4f2e-b0ce-7933ed02e801', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 7, '60605330', '輝きを継ぐ、君らしく', '彷徨いつつも問い掛けを続け、いつだって強さを求めてきた。翻弄する運命や、己を掻き乱す茫漠に負けない力はきっとある。だがそれは、誰もが備えているからこそ気づきにくい。道はひとつでないゆえに、縺れて違え、ここにまた擦過する。この邂逅こそ即ち凶器。夏の夜に咲く笑顔を殺しにかかる。', '2015/08/26 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e9f4ec01-c12f-4e13-9b20-b225ffad7184.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6a13d61-15fe-4679-a024-a3eaaa82370d', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 8, '60608570', '向き合う勇気', '至らぬ我が身を悔やむ時、聞こえないはずの言葉が胸に湧く。激突もまた、強くなりたいと願い足掻く意思の顕れ。かつての白い世界でなく、受け止めてくれる人はきっとここに。対峙する存在は、記憶にあったそれよりも小さく、か細い。拳で砕ける壁など、如何程の脅威でない残酷が突きつけられる。', '2015/09/02 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/82531743-a205-4c67-bb04-591d0ef1bebb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c26f9568-83a8-4145-a3d9-8f20aa438e46', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 9, '60612321', '夢の途中', '横たわる隔絶は、その在り方すらも歪ませてしまう。どちらもまた翻弄されたがゆえ、気持ちのままにぶつかれない。往く事に怯えても、羽撃きを止めるには早すぎる。ここはまだ―勝機に捻じ込まれる一撃は、力でなく尽きぬ夢にて阻まれる。ここを竜宮と呼ぶのなら、危うき玉手箱があっても不思議でない。', '2015/09/09 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50a78cd3-f64e-4a88-8667-55802f25a440.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01dd08cf-506a-4bdb-87ed-35598ca1b884', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 10, '60614207', 'こんなにも、残酷だけど', '危惧しつつ、だが、仕込まれていたのは即効性の毒。発症は早くとも、気づくまでに時間を要し、手遅れの段となる。仕込んだ者はほくそ笑むが、果たして毒はそこだけか。成れなくても、してくれる―それは簡単だけど遠い答え。奪うばかりでない、大切なモノをくれたのもこの世界だから。', '2015/09/16 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/564cda15-8dc4-4a74-af48-e590c6b22d3c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8289b73-236b-4cdb-8def-02ab80834ec0', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 11, '60617417', 'へいき、へっちゃら', '困難に向き合った男と、困難より目を背け続けてきた男。それぞれを父と背負う少女と少女が、この道に再び対峙し、激突する。まろびつつ握った、なけなしの勇気だって「勇気」、だとしたら―手札は揃った、役もある。ならばこそ札を切るのに躊躇はいらぬ。ずっと求めてきた答えのために、その歌はついに響き渡る。', '2015/09/23 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5cf26f26-79fc-42d1-a2b5-ed9107006052.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a041408f-ead7-49e2-901e-d096052b14de', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 12, '60621880', 'GX', '震撼する状況の中、長く綴られた小さな挿話は終着を迎える。ある者は思い描いた夢に手を伸ばし、ある者は過ちを乗り越えるため、「ありがとう」を唄いながら、瓦解する世界の中心にて微笑む。天空に在りて奇跡を纏う者たちもまた、奇跡の殺戮者である。手繰り寄せ、カタチと紡いだこの希望に、瞳は静かに閉じられる。', '2015/09/30 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/db17d390-0dfd-431d-95de-ad00b462704b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2debea7-1824-48a0-91aa-e2b64877d45e', 'f52d1650-7bc5-4957-b529-5d0282fce94a', 13, '60625823', '正義を信じて、握り締めて', '【シーズン1 最終話】答えを求めた少女は狂い咽び、闇の果てに向かって叫ぶ。過酷･残酷に抗えず、捻じれていく祈りを救うべく、この手はたとえ、何度傷ついても伸ばし続ける。離しはしない。信じる未来 (ゆめ) があるならば、響き合う鼓動は止められない。君と行こう、一緒に。どこまでもふたり、手を取って。', '2015/10/07 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bc828f2b-11a9-44f9-9e3d-dabfbd15fa7b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4ad49c64-72ce-467a-a188-bd49073ec3cd', '戦姫絶唱シンフォギアXV', '', 'hulu', 'senki-zesshou-symphogear-xv', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebbb7610-6436-47f2-a7c2-cff59ab52054.jpg?w=331&h=447&p=t', 'hulu', 2019, 2, 1, 'FINISHED', NULL, 21673, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ca5814e6-861e-44c5-a811-0d42e87a03c9', '4ad49c64-72ce-467a-a188-bd49073ec3cd', 'hulu-senki-zesshou-symphogear-xv-s1', 'シーズン5', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caca2f40-f838-4c46-af71-63cafcf2c3c4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7658dfdc-d795-46bd-a474-f7bfd71c5ce8', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 1, '100038980', '人類史の彼方から', '閉ざされた昨日より、棺が真夏に浮上する。収められしは罪と罰―そして真実。物言わぬからこそ雄弁に、しかして言葉は奪われて。俯瞰に眺むるは、軛解かれし残光の化生 (ケモノ) たち。砕かれた明日を夢に見て、屈辱をいつか雪ぐ為に。', '2019/07/12 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caca2f40-f838-4c46-af71-63cafcf2c3c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee6c12a4-c79b-4ba4-bd75-13cc5746608b', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 2, '100039330', '天空 (ソラ) が墜ちる日', '夏から冬へ季節は移ろい、企てもまた推移する。誰彼 (たそがれ) より群がるは、骸求めて蠢く者。それこそがと疑わぬ、力に焦がれた獣ども。為すべきを為せと言う君に、ならばと返す君がいる。幕引きは声も高らかに、天国にアナタいちばん近い庭園 (にわ)。', '2019/07/19 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2313827-ece1-4b98-a438-b5878c921d49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4476c0a9-d70e-4474-bbe0-1841324004ce', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 3, '100039587', 'Penny Dreadful', 'その胸に懐く畏れは、ほどなく蔑みと失墜する。見下されるのは慣れている。なれど矜持は喪わず。誰かを殺すその前に、自分はとうに殺している。輝きの翳に刻まれた、コトバの意味もまた『言葉』。七度生まれ変わろうと、そこに貫く意地は固く。', '2019/07/26 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c28bb433-1e5c-4062-9b38-ecdec16cf19a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b6a210f-a764-4ba4-baf3-fdd1193b67a5', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 4, '100039960', '花の名は、アマルガム', 'この天と地に機は熟し、禁断の果実と甘く薫る。星の光と渡る風、盟約の行使を今ここに。未知なる楽律は惧れを奏で、君だけが既知と訝しむ。迷宮に咲く其れこそが、抗い続けるイシの輝き。躙られるまでの瞬きに、ぶつけた想いの意味は重い。', '2019/08/02 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f619273-de98-4002-83ce-541c407da2e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8bd360ab-a42b-4b01-adca-3cd75fed2820', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 5, '100040678', 'かばんの隠し事', 'いつだって秘めていた。だけど思わぬ言葉が衝いて出る。打ち明けられなかった想いとワタシ。どうしてと、わからぬキミにもどかしさを掻き毟る。幾許の屍山血河を築けば、その火護る事、能うのか。曇りに道は照らされず、奔り遁げてもなお死が迫る。', '2019/08/09 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51f09763-bbbb-4b40-a49c-4a4354426e30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('390899fc-8780-485c-bc1d-a2891e4fbb96', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 6, '100040880', 'ゼノグラシア', '邁めて進んだこの道に、いつしか無くした在るべき理由。救い求めた呼びかけなれど応じる姿はそこになく、誇りを侵し、略奪した言刃 (コトバ) にキミは―掌握 (みすか) される。仮令、明日を奪われようと抗う者らの歩みは止まらぬ。あの空に浮かぶは禁断の、口づけに眠る星の歌。', '2019/08/16 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9303e98e-c1e8-4748-87df-50be9c6c7217.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72c409d7-68a8-4f0c-b86e-04bd40fc0104', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 7, '100041403', 'もつれた糸を断ち切って', 'いつかに殺すと誓ったソレを誰かが口にするならば、0と1の彼方より、言消すために爪弾こう。不要無用と打ち棄てられた、想い出がここに残響 (コダマ) する。振り返るは、交わされなかったはずの言葉。全てを預けられるキミの、誰よりも優しい拳に託す。', '2019/08/23 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79bc4bd3-bd0e-4790-9d9b-1d50e7d51c0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10f555cf-4578-40e9-9ea2-1379823f61c9', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 8, '100041608', 'XV', '完全が完成へと至る歩みに、全速の不完全が追い縋る。表と裏。さらに裏まで忍ばせた二段の構え。なれど未来を隔てる壁向こう。辿りつくまでが果てしない。何を信じて何を選ぶのか、あるがままを捉えられずに、為す術もなく遠ざかる―いつかの虹、花の想い出。', '2019/08/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b00fb91-e5f5-44fa-a8cf-26fa89e307a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac676b1b-9b06-40ac-a1b7-4abc4aa47407', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 9, '100041938', 'I am a father', '今さらに「らしく」あれないのはわかっている。なれど自分からは逃げられず、ゆえに誰かに騙らせぬ。どこにいても一緒だと―不器用にただ、絆を想う。屍山 (ヤマ) のあなたになお遠く、「幸」住むと防人 (ヒト) のいう。だが、尋めゆきたそこに逆巻くは血風―幾つもの別離。', '2019/09/06 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23d65f01-e252-48ee-b991-ac0db5141423.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c5028b8-d9f4-4a92-97cb-dc36dc3dd9ed', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 10, '100042399', '卑しき錆色に非ず', '石もて追われたとしても、求めて欲した明日がある。だが、足掻いた果てに広がるは―不可逆の運命 (さだめ)。優しさを知るからこその慟哭が、宙の階 (ソラノキザハシ) に谺する。遠く仰いだ遥かに在るは、踏みしめていたはずの寄る辺。その所業は悪辣でなく、不条理だけが為せる絶望。', '2019/09/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec1c4172-a37d-4311-89a5-95ddab8f6ff5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d526610-138b-453c-9c68-447bad4057a1', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 11, '100042726', 'ハジメニコトバアリキ', '剣戟に散る火花が照らす、遥かに遠く乾いた世界。明日は既に失墜し、それでも夢に掻き毟る。捨てる覚悟を持つモノだけが拾う資格を掴み取る。鳴り振るえる欠片は喪われど、ふたりを繋ぐ歌はある。天をも焦がす羽撃きに、瞳は再び燃え上がる。', '2019/09/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd6fbdcd-dfa6-48f1-9f32-1a90f082a0dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e2a83b1-86e8-4f59-82e3-6946e5da1f8d', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 12, '100042900', '戦姫絶唱', '此処から遠くを仰ぎ見て、届かぬキボウに手を伸ばす。倒けつ転びつ涙して、末魔を断たれた慟哭に、帰る意味を知るキミが、捧げし一矢ともう一矢。迷いなく放たれた最後の呪いは、不可逆すらも転覆す。散りばめられし希望の欠片―神討つモノらが総力に集う。', '2019/09/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c20ad915-8b56-457c-95a9-ffe8b8d9fcf3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8aebcdaa-9785-4ca9-b58e-d6bcda7b1549', 'ca5814e6-861e-44c5-a811-0d42e87a03c9', 13, '100043128', '神様も知らないヒカリで歴史を創ろう', '【シーズン5 最終話】邂逅した世界に呪詛 (しゅくふく) はなく、もはや神 (キミ) の思うがままに。刻至らずとも奇蹟に動地、驚天し、人類 (ヒト) は一つに鷲掴まれる。それでも繋ぐこの手には―神を殺す力 (わたしのアームドギア) がある。わかりあえない―だからこそ、強く求める夜がある。仮令もどかしさに涙しても、それだけが人をたらしめる。', '2019/10/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8e71f66-726c-4a43-9116-35d56c97987c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e25e21a2-f70b-4e77-956a-381d494fa53e', '全修。', '', 'hulu', 'zenshu', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7148f53e-1069-4eb1-a846-5b886ffeb525.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 176273, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8551726e-c97d-48d7-b36c-33e9aa80ed00', 'e25e21a2-f70b-4e77-956a-381d494fa53e', 'hulu-zenshu-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d42a413f-e8f0-4020-b699-c3f65cd4049f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fb7995a-4eb8-4234-a2c2-a4d3e8148257', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 1, '100212089', '始線。', '新進気鋭のアニメ監督、広瀬ナツ子は、初恋をテーマにした長編ラブコメ映画のコンテに取り掛かっていたが、初恋を経験したことがないナツ子は絵コンテが描けなくなる。', '2025/01/06 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d42a413f-e8f0-4020-b699-c3f65cd4049f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f91c6cd-a855-40cd-8520-1e7acc873f69', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 2, '100212519', '死守。', 'ナツ子は最後の街の預言者バオバブ様にナインソルジャーへの加入を打診されるも、ルークと仲違いして決裂。現実に戻る方法を考えるナツ子だが、映画「滅びゆく物語」の展開で最後の街が再びピンチになることを思い出し、現実に戻れないとしたら死んでも守らなければならないものがあることに気付く…。', '2025/01/13 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4cbf1de6-2b8f-41d1-9da8-bfe0ad751db1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d96b03b0-af7b-4a6f-87b9-d3035a794301', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 3, '100213329', '運命。', '最後の街は収穫祭が行われ、ナインソルジャーたちも久々の休日。それぞれ羽を伸ばす。そこでルークは町長の娘、デステニーと出会う。映画「滅びゆく物語」だと2人は恋に落ちるのだが、ナツ子が転生したことで運命は少しずつ変わってきていて…。', '2025/01/20 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a7eafe8-0414-4c53-ba69-08ecc05af6f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47963931-6972-4255-8b56-cb4da94ba414', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 4, '100214285', '永遠。', 'メメルンの様子がおかしいことに気付くナツ子。映画「滅びゆく物語」ではメメルンがルークを殺そうとするシーンがあるが、映画でその理由については一切触れられておらずファンの間では謎展開となっている。ナツ子は真相を確かめるためメメルンの跡をつけることに…。', '2025/01/27 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80713cd1-2f66-4d0b-a0b4-9e753895a770.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d491c98a-d6a1-454f-beca-588039b91d76', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 5, '100214802', '正義。', 'ヴォイドを倒しまくって調子に乗っているナツ子。ナインソルジャーはデステニーに頼まれて孤児たちに食事を配りにいくことに。そこでルークは元ナインソルジャーで、今ではすっかり落ちぶれてしまったジャスティスと再会する。一方、その頃、新たなヴォイドが街に近づいてきていた。', '2025/02/03 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44eff45b-eadf-468e-bf97-2dd44f9954d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2afca33-7457-4517-982d-e61b611fb547', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 6, '100216176', '変化。', '初めてヴォイドに負けたナツ子は、また自分勝手な行動を取ろうとする。ルークはそんなナツ子に怒りもあるが、ジャスティスとの関係が気になってしまう。一方その頃、前回倒せなかったヴォイドがさらに変化しようとしていた!', '2025/02/10 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63480a13-caf8-4d1b-9557-12dd2e684602.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea0b4d63-0661-4cf1-9148-8b4d471b4acc', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 7, '100217045', '初恋。', '映画「滅びゆく物語」に心動かされた小学生のナツ子を見つめるクラスメイトのミドリちゃん。動いているものを描くことに夢中になった中学生のナツ子を見ている陸上部の二宮くん。天才と呼ばれ始めた高校生のナツ子に闘志を燃やす大学生の蒼井。アニメーターになったナツ子は長編ラブコメ映画の監督に抜擢されるも「初恋」が何なのかわからず…。', '2025/02/17 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7259b9c-bda9-45b2-aba5-c7dee17e3235.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c076c547-1e22-4279-a647-4098e1244740', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 8, '100218458', '告白。', 'ナツ子の行く先々に「無駄だよ」と言ってくる鳥が突如現れるようになる。一方、ルークはナツ子を好きな自分の気持ちに気付く。ナツ子に告白しようとするが、うまく気持ちが伝わらない。そのことをジャスティスに相談すると「デートに誘え」とアドバイスを受ける。ルークとナツ子、初めてのデート?!', '2025/02/24 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/067394fb-54e9-4bd2-9be5-f3d8c7728a6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e4af731-8b45-4e04-ae31-2c337de67983', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 9, '100218918', '勇者。', '伝説の勇者ルーク･ブレイブハート。ずっと戦って生きてきたが、ナツ子が現れて恋をして生まれて初めて人生が楽しい! 一方、ナツ子はルークに告白されて戸惑っていた。自分がこの世界に来たことで映画「滅びゆく物語」の展開とは少しずつ変わってきているが、もし映画の通りになるとしたらラストは…。', '2025/03/03 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a5610db-189f-4b4f-8083-8caa99db543a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('995af19d-25b2-44d7-a94f-7d262f7023bd', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 10, '100220107', '混乱。', 'ナツ子は、この世界が急速に映画「滅びゆく物語」の展開に修正されていることに気付く。一方、ルークは街の人たちのために勇者として気丈に振る舞う。そんなルークを心配するユニオ。メメルンは何やら怪しい儀式を行おうとしていた。そして街ではナツ子が描いたものがヴォイドになっているという噂が流れていて…。', '2025/03/11 00:15:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82c10013-f28f-48de-8398-9bdfd97a23cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2686e15d-b4c4-4859-8108-c0730267ad44', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 11, '100220778', '絶望。', '最後の街に大量のヴォイドが襲ってくる。ナツ子とユニオがヴォイドに食べられてしまった。「ナツ子が死んだ!」と歓喜する人々。勇者であるルークに助けを求める人々。ルークは、なんのためにヴォイドと戦い、誰のためにソウルフューチャーを守っているのかわからなくなってゆく。', '2025/03/18 00:15:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cb4157c-27e9-401d-ac9b-86a8638a71a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cbde48f-82fd-463b-87eb-2bc0ed733f16', '8551726e-c97d-48d7-b36c-33e9aa80ed00', 12, '100221788', '全修。', '【シーズン1 最終話】ついに超空洞ヴォイドが誕生する。映画「滅びゆく物語」と同じエンディングを迎えようとしていた。超空洞ヴォイドの前になす術もなく、誰もが諦めて世界が滅んでゆこうとしていく中、ナツ子たちはルークを救うために立ち上がる。超空洞ヴォイドと最終バトルへ。', '2025/03/24 23:45:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7edd3dd-30a9-4a2a-a1d2-c662e3806116.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4114e613-51cb-4ee6-a3b6-8c2a1eed8e2a', '素材採取家の異世界旅行記', '', 'hulu', 'a-gatherers-adventure-in-isekai', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/820a2599-0a12-48ac-bd0d-09473f1bfcdd.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 187663, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('80c7431d-51a2-4aac-8c58-3d0c4ddb5055', '4114e613-51cb-4ee6-a3b6-8c2a1eed8e2a', 'hulu-a-gatherers-adventure-in-isekai-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ab35dee-7415-43e1-9456-f94dbc4aef01.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61edab43-007d-4b49-b884-1d18f7e3cb1b', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 1, '100239824', '落ちた一滴', '謎の青年から様々な能力を与えられたタケルは、異世界の惑星マデウスに転生。早速『探査能力』を使い、高値で売れる素材を採取する。その腕を見込まれ、とある山にある“ミスリル鉱石”を採取してほしいと依頼されたタケルだが、そこには恐ろしいモンスターがいるらしく……。', '2025/10/09 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ab35dee-7415-43e1-9456-f94dbc4aef01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c76a8fd4-5734-4576-8d91-1738ba2b7ce9', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 2, '100240852', '一人じゃない晩餐', 'ドラゴンの子･ビーとの冒険がはじまる。一緒に料理を食べたり、モンスターを倒して肉を素材として採取したり、楽しい時間を過ごすタケル。だが、モンスターたちに取り囲まれたことを知ったタケルは、ビーと共に森を脱出。その先にいたのは、行き倒れているエルフだった。', '2025/10/16 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d3bb588-81f9-4f8c-8dc9-e9ae991dac6e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33e3ffc5-fe00-4abb-87f3-500819467ed4', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 3, '100241422', '故郷と旅路', 'ようやくトルミ村に帰ってきたタケルとビー。依頼された鉱石だけでなく、希少な魔鉱石を採取し益々信用を得たタケルは、商業都市ベルカイムへ行くことを勧められる。村人たちとの別れを惜しみつつ、ベルカイムを目指すタケルとビー。その前に、巨大なカニが立ち塞がる。', '2025/10/23 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/402d0496-2fbe-40cb-a7ea-3a42cbc8c273.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29e31b36-ee98-4265-b993-9bbe07010f4b', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 4, '100241694', '魔王降臨', 'ベルカイムに来て半月。 冒険者としての生活に幸せを感じているタケルは、風呂屋でリザードマンの戦士･クレイストンと出会う。 彼は、欲の無いタケルを気に掛けていた。 そんなとき、ゴブリン襲撃の報せが届く。 駆り出されたタケルは、クレイストンたち冒険者と討伐に赴くが……。', '2025/10/30 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b676be72-5055-4e28-9e4f-2481773b942b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0443c8d-ab50-4e1b-a39f-bf8ce66d2180', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 5, '100242819', '二人の用心棒', '素材採取用のハサミを求めて職人街にやってきたタケルは、見習い鍛冶職人のリブルと出会う。 自分専用のハサミの製作と引き換えに、親方の欲しがっている“イルドラ石”の採取を申し出たタケルはリュハイ鉱山を目指す。 その道中で遭遇したのは、残念エルフのブロライトだった。', '2025/11/06 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e092cd1e-4ce9-4ee0-85a5-81a0fdca04de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c9c894e-eb87-4345-8bea-2bc5653bb0a6', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 6, '100244151', '領主の切願', 'ドワーフの国の鉱山に巣くう悪魔の正体は、タケルとビーの大好物、巨大なカニだった! 見事退治し、鉱脈を発見したタケルたちは王から褒美を授かる。天馬を貰ったブロライトは再会を誓い、故郷へと旅立っていった。半月後、タケルたちの元にルセウヴァッハ領主から召喚状が届いて……。', '2025/11/13 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c69abd86-edc0-4c85-90f7-79a2c3c08301.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('392be513-a273-48fe-856c-d772d55c3fc4', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 7, '100244925', '神の花', '領主･ベルミナントの奥方の目を治したタケル。だが彼女がイヴェル中毒であることを見抜いたタケルは、解毒薬の素材を探すことに。薬になる花が咲く湖を目指すタケルたち。だが湖は黒く淀み、毒に侵されていた。さらには、村人たちに取り囲まれてしまい……。', '2025/11/20 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd9ee714-1edb-4591-bef3-37342391cca7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('630f1c14-31e9-4a45-bc34-856472156270', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 8, '100245607', '未来への一手', '薬草となる花を採取したタケルたち。早速、ルセウヴァッハ領に戻ろうとするが、案内してくれた村人たちの村が焼かれてしまう。タケルはビー、クレイと協力し鎮火。しかし、村の子供ゴンザの姿がない。エンガシュにさらわれたと知ったタケルたちは、その行方を追う。', '2025/11/27 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a171f26f-5d7c-44b0-8a11-336de1ca986f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f89def26-854d-434f-a466-2c13ce8b5129', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 9, '100246412', '意外な来訪者', '古代馬と呼ばれる神プニさんが仲間に加わった。美しくも奔放な彼女に振り回されるタケル。冒険者たちで行われる素材採取競争に参加したタケルは、その後、巨大ミミズに遭遇。その背に乗っていたのは、ブロライトだった。なんでも、タケルに頼みごとがあるようで……。', '2025/12/04 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a199611b-22c6-4220-8f2c-947c20d6097f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62bb99a5-ec6a-4f23-b405-bd17f0ffec34', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 10, '100246813', 'ブロライトの闇', 'エルフの郷にやってきたタケルたちは、ブロライトがハイエルフ族だと知る。「俗世に出てはならぬ」という一族の掟を破り、ブロライトは姉の望む天馬を探す旅に出ていたのだ。その後、王宮に赴いたタケルたちは、ブロライトの“さらなる秘密”を知ることに……。', '2025/12/11 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0375785e-5afd-4cf5-9404-d336f6ccc409.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc16f917-9a5d-468b-b123-eee99db09500', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 11, '100247916', '危険な洞', 'ハイエルフ族を救うため、守護神リベルアリナを探すタケルたち。その手掛かりを見つけるため、キエトの洞を目指す。強き魔素が渦巻くため、魔道具に身を包み、洞の中へ入っていくタケルたち。そこには、毒を持つ数多くのモンスターが蠢いていた。', '2025/12/18 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df038e99-1d4f-4d95-afa0-e8b02861b52b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1dbc0c76-7c0f-46e4-b7c2-40cf9099d491', '80c7431d-51a2-4aac-8c58-3d0c4ddb5055', 12, '100248548', 'まだ見ぬ世界', '【最終話】タケルたち一行は、リベルアリナがいる地･プネブマ渓谷にやってきた。そこには、ずっと探していたブロライトの姉リュティカラの姿も。感動の再会……かと思いきや、大ゲンカを始める二人。その後、森に入ったタケルたちの前に、いよいよリベルアリナが現れ……。', '2025/12/25 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c82aacab-f534-4c76-b79b-391c3668e08e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('104298fb-0429-447c-972f-d3fc8984cca4', '組長娘と世話係', '', 'hulu', 'the-yakuzas-guide-to-babysitting', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1dd4e2e-3ca8-462e-91db-5343473bdf9f.jpg?w=331&h=447&p=t', 'hulu', 2022, 2, 1, 'FINISHED', NULL, 138882, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1a1ea8aa-af1d-402c-986e-ef3a88d39982', '104298fb-0429-447c-972f-d3fc8984cca4', 'hulu-the-yakuzas-guide-to-babysitting-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5ce4755-282b-4791-829a-735791f6345c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('056c4f8a-9cca-4c10-bf94-04d46f8c04d7', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 1, '100117546', '組長娘と世話係', 'その暴力性から、『桜樹組の悪魔』と極道からも恐れられる、桜樹組若頭･霧島透。ある日、霧島は組長に呼び出されて――組長の一人娘である、桜樹八重花の世話係を命じられる。人見知りで、なかなか心を開いてくれない八重花にどう接していいものか、当惑する霧島。そんな時、八重花が隠していた授業参観のお知らせを見つける。授業参観の日付は今日……。そこで霧島が取った行動とは――。', '2022/07/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5ce4755-282b-4791-829a-735791f6345c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7aadb832-25e5-4320-8712-618abdb088fb', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 2, '100117864', 'やさしいひと', '世話係の仕事にも徐々に慣れ始める霧島。一緒に花火大会に出かけることで、八重花との心の距離も着実に縮まっていく。そんな折、八重花は桜樹と共に、意識不明で入院している母･美幸のお見舞いに行くことになるが……。「ずっとねてるおかあさんなんか、しらないひとだもん……!!」 母のお見舞いに行くことを拒絶する八重花に、霧島がかけた言葉とは――。', '2022/07/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c38f937-90e8-46be-b5da-7b99536e6555.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2094868-1b47-434f-9dd1-3cf7edaad177', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 3, '100118448', 'おみまいと再会', '母のお見舞いに病院を訪れる八重花。同行した霧島は、かつての桜樹組の若頭で、兄貴分だった葵と鉢合わせする。そして、お見舞いからの帰り道――霧島と八重花は捨て猫の相手をしていた女子高生の歩と出会う。「きりしま、このこかっちゃだめ?」と、八重花は捨て猫を飼いたいと言い出して――。', '2022/07/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ef05b55-99a7-44f3-9e99-a652a36fc91d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f41f37b7-57ea-4bf0-871b-866eab36deeb', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 4, '100118916', '動画配信始めるか', '『桜樹組の悪魔』、霧島透が組長から命じられた新しい仕事は――動画配信!? 財政事情が苦しい桜樹組を救うべく、霧島と杉原は動画配信でひと山当てるミッションに挑む! そしてここに、謎の覆面配信者『ミスティー』が爆誕! ネット動画の世界にカチコミをかけた霧島は、血の雨ならぬ、金の雨を降らせることができるのか!?', '2022/08/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f8ebba7-3e96-4dcd-89da-34bf18cdb6f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8eac323d-4902-4e64-9fbd-45dfc8ae5202', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 5, '100119953', '霧島のおやすみ', '桜樹も出席する組長同士の会合に、同行した霧島。その帰り道、中学時代の同級生で、今は彫り師をやっている零と再会する。すっかりオネエになった零に、さしもの霧島もたじたじで……。一方、八重花は香菜美と歩と一緒にケーキ作りに挑戦していた。八重花が手作りケーキを食べさせてあげたい相手とはいったい……。', '2022/08/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2cffa6b0-f782-4781-aa83-fe87343743de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0167b6ba-8f62-41b9-bbdb-e64ecb648a7f', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 6, '100120331', 'はじめてのおともだち', '八重花の誕生日を祝うべく、香菜美のサポートを受けて手料理に挑戦する霧島。一方その頃、杉原たち組員と公園で遊んでいた八重花は、外国人の女の子･サラと出会い、すぐに仲良くなる。その翌日、桜樹組のお隣に引っ越してきた意外な父娘 (おやこ) が挨拶に訪れて……。そして、八重花の誕生日当日――霧島が八重花のために作った手料理とは。', '2022/08/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b984c2fc-4b7c-4bf2-9b6d-8d348a3630bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5fb7aa39-6277-41e5-bba9-f9af4fa9d596', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 7, '100120956', '最高の標的', '霧島に激しい恨みを抱く柿原組の構成員･雅也が刑務所から出所してくる。「霧島透をぶっ殺す!」と、殺 (や) る気満々で霧島の前に現れる雅也であったが――そこにいたのは『悪魔』ではなく、すっかり『世話係』となった霧島だった。しつこく挑発してくる雅也に、霧島が見せた反応とは……? そして、霧島に代わって悪徳業者と対峙する杉原が見せた、意外な一面とは……?', '2022/08/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f75a9f3a-41da-4da4-8e0f-8d598aed0d93.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1102215-8c94-4e04-a3b7-81f43f054f3d', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 8, '100121717', 'お久し振りです', '堅気となって組を抜けた葵が、桜樹の元へ挨拶に訪れる。葵は桜樹と話しながら、組の若頭だった頃を思い出して――八重花を身に宿した美幸と、桜樹の穏やかな日々。そして、手の着けられないはねっ返りだった霧島に手を焼きながらも、兄貴分としてしっかり面倒を見る葵。そんな葵が極道の世界から足を洗い、堅気になった理由とは……?', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6917fbde-5d98-49b7-8abd-ef612dbe22fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8bc0ea3-12f4-4e6b-bebc-da70ea68cb87', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 9, '100122620', '霧島○○計画', 'なにやら八重花の様子がおかしい。霧島に何か隠し事でもしているかのように、そわそわ落ち着きのない様子で……。それに加え、桜樹や杉原たち組員も総出で、霧島が八重花に近づかないよう、あの手この手で妨害してくる。八重花の不審な行動の理由とは、果たして……。', '2022/09/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f96e3220-c718-455d-ab67-0fd7f63b7530.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0011a555-dee8-42e8-85fd-225ca2271f76', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 10, '100123538', 'わるいひと', '霧島と八重花の身に迫る、ドス黒い影……。かつて『ヤクザ潰し』として恐れられた霧島に組を潰された極道たちが、恨みを晴らすべく動き出した。八重花を人質に取られ、無抵抗で一方的にやられる霧島。しかし、極道たちの恨みの矛先は、八重花にまで向けられて……。その時、霧島の中の『悪魔』がついに目覚めてしまった――', '2022/09/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5184987-2e9f-4225-b362-ba5a14397d5c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc55460f-538d-4a67-909c-4e6ee9033d69', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 11, '100123834', '花火と約束と', 'ヤクザ同士のいざこざに八重花を巻き込んだ極道たちを見つけ出し、無慈悲に制裁を加える霧島。そこへ現れた桜樹の一喝で霧島は我に返り、八重花の元へ帰ってくる。八重花の世話係として、再び穏やかな日々を過ごす霧島であったが……。杉原の元に突然、『お嬢を頼む』と霧島からのメールが届いて――。', '2022/09/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8454723-7d12-4439-aca2-702ef4e008ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e99f9dc-8693-476e-a69d-deacb4881ee1', '1a1ea8aa-af1d-402c-986e-ef3a88d39982', 12, '100124560', 'お嬢の世話係', '【シーズン1 最終話】かつては『桜樹組の悪魔』『ヤクザ潰し』と恐れられた霧島も、今ではすっかり世話係が板に付き、八重花と穏やかな日々を過ごしていた。そんな2人をあたたかく見守る、桜樹、杉原、香菜美、葵。ある日、霧島は八重花と共に、両親の墓前に備える花を買いに向かう。霧島が手にしたのは、母との思い出の花･カランコエ。その花言葉は――。', '2022/09/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/761efc77-38d5-40e4-8165-82b4dd5f658f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('130715f4-e47c-4fc1-856e-813add50065c', '双星の陰陽師', '', 'hulu', 'twin-star-exorcists', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50025793_series_art__338x600_twin_star_exorcists_bf04957efc9f2cd2f6f7df51f1bd871e.jpg?w=331&h=447&p=t', 'hulu', 2016, 1, 1, 'FINISHED', NULL, 21499, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('26e8d696-755e-4950-a041-ede7e9a803aa', '130715f4-e47c-4fc1-856e-813add50065c', 'hulu-twin-star-exorcists-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7a9dd306-0aaf-4ece-a1a4-55fdb59431fa.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc273e8c-b97c-465e-a284-fc42bd3fbbd5', '26e8d696-755e-4950-a041-ede7e9a803aa', 1, '60712788', '運命の二人 BOY MEETS GIRL', '焔魔堂 (えんまどう) ろくろは、陰陽師としての才能に恵まれながら、過去に負った心のキズを癒せず陰陽師になることをやめていた。そんなろくろがひとりの美少女･化野紅緒 (あだしの べにお) と出会う。紅緒は名門･化野家の筆頭をつとめる優秀な陰陽師だった。 陰陽師トップ･陰陽頭 (おんみょうのかみ) からの命令で、京都からやってきた紅緒は、偶然知り合ったろくろに道案内を頼むが、持っていた地図がわかりづらかったせいでふたりは道に迷ってしまう。そんなふたりの前に現れたのは?', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7a9dd306-0aaf-4ece-a1a4-55fdb59431fa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13bf38f1-1487-4447-8f35-470cc20c44b4', '26e8d696-755e-4950-a041-ede7e9a803aa', 2, '60712787', '双星交差 A FATEFUL FIGHT', '紅緒がろくろたちとともに星火寮で暮らすことになった。お互いに最悪の出会いをしたせいで反発しあうろくろと紅緒。そんな中、怪しげな人物が星火寮を訪れる。どういうわけかパンツ一丁で現れたこの人物こそ、すべての陰陽師を統べる陰陽頭･土御門有馬だった。そして星火寮の面々とともに 「五鏡止水の間 (ごきょうしすいのま) 」 と呼ばれる場所へとやってきたろくろと紅緒は、なぜか全国の幹部たちの前で戦うことになる。だが、ろくろの実力を確かめたい紅緒と違ってろくろには、陰陽師として戦う意思はなく――。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7eea7d63-aa11-473b-8dba-abc0fc6592fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80436c28-0ace-4eea-833a-1f8cd7a33f28', '26e8d696-755e-4950-a041-ede7e9a803aa', 3, '60716640', 'すれ違い A HERO’S WORTH', 'ろくろやろくろの幼なじみ･音海繭良 (おとみ まゆら) と同じ学校に通うことになった紅緒は、すぐにクラスの注目の的になる。そんな中、授業の合間に異界のバケモノ･ケガレの気配を感じ取る紅緒。まだ中学生のろくろたちは、陰陽師としての仕事よりも学業を優先するように言われていたが、紅緒はかまわず学校を早退するとケガレ祓いに向かう。一方ろくろはそのまま学校に残るが、紅緒との出会いから、その心には迷いが生まれていた――。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/434f6c2e-0e6a-49cd-9a93-6a4a48843acb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6245c9f3-c65e-4c77-96fd-a46f7119de59', '26e8d696-755e-4950-a041-ede7e9a803aa', 4, '60719306', '禍野の音 BOTHERSOME TWOSOME', '星火寮で一緒に暮らし、ろくろのことを本当の弟のようにかわいがってくれる椥辻亮悟 (なぎつじ りょうご) が、ケガレ祓いの最中、ケガレの棲処･禍野 (まがの) に取り残されてしまった。依頼を受けた亮悟が出かける直前、つまらないことで言い争いをしていたろくろは、亮悟とともにケガレ祓いに向かった額塚篤 (すくもづか あつし) や国崎慎之助 (くざき しんのすけ) から話を聞くと、いてもたってもいられなくなる。一方、禍野に取り残された亮悟は、襲いかかるケガレを相手にひとり奮闘するが、徐々に追い詰められてゆく。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/255ecba6-f393-40f5-93ec-26555b11ecfe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9dce318a-5f0e-4876-9e22-b49cb3b855e6', '26e8d696-755e-4950-a041-ede7e9a803aa', 5, '60721616', '十二天将 朱雀 THE GUARDIAN SHIMON', '小学校で、練習中のサッカー部の子供たちが、突然姿を消した。子供たちはケガレによって禍野へと連れ去られていたのだ。子供たちを助けるため、紅緒や篤、慎之助とともに禍野を訪れたろくろは、自分自身の意思で陰陽師として戦うことになる。だがその最中、ふとしたことでかつてのつらい記憶がよみがえり、戦うことができなくなってしまうのだった。そのとき一同の前に現れたのは、陰陽師の中でもトップクラスの実力を持つ十二天将･朱雀の名を持つ斑鳩士門 (いかるが しもん) だった。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/00c6f998-e397-4743-9357-44b8e9def023.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6903af0-c418-4fb6-9350-924dd89d0b02', '26e8d696-755e-4950-a041-ede7e9a803aa', 6, '60725331', '紅緒と繭良 GIRLS’ PARTY', 'ろくろや繭良と同じ学校に通い始めたものの、紅緒はクラスメイトたちとなじもうとせず、毎日のように早退する日々を送っていた。紅緒はケガレ祓いのために早退を繰り返していたのだが、事情を知らない繭良はそんな紅緒を心配し、何とかして友達になれないものかと考える。早速いろいろな方法を使って紅緒と仲良くなろうとする繭良。だが紅緒はそんな繭良に困惑し、距離を取ろうとするのだが…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d7dd5696-9b0b-430b-80bb-8b2037ca2369.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8e54335-8cef-4806-a157-7cba226104f5', '26e8d696-755e-4950-a041-ede7e9a803aa', 7, '60729419', '新たなる試練 UNBELIEVABLE GAME', '有馬が星火寮を訪れ、ろくろと紅緒を「双星の陰陽師」の真価が問われる試練の場へと連れて行くと言う。「試練」と聞いて気合いの入るろくろと紅緒だが、ふたりが連れて行かれたのは豪華な屋敷。そこは夫婦に与えられる「双星」の称号を得たろくろと紅緒が暮らすための新居だった。突然ふたりきりで暮らすように言われ焦るろくろたち。有馬はそんなふたりに、お互いに協力しあわなくては解決できないある難題を課す。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/06981289-4a05-46b6-b8d5-f5a99ac75ce0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37872fdd-2f42-4a97-af39-bcdd17c90372', '26e8d696-755e-4950-a041-ede7e9a803aa', 8, '60733152', 'ろくろの気持ち SHOCKING CONFESSION', '呪力の高い人間が、突然ケガレとなる現象「ケガレ堕ち」が発生した。そんなある日、繭良が禍野へと連れ去される事件が起こる。繭良を助けるため禍野にやってきたろくろと紅緒だったが、強すぎる敵に苦戦する。そこに現れたのは、士門と同じく十二天将のひとりで繭良の父親である天若清弦 (あまわかせいげん) だった。ろくろたちが苦戦したケガレを難なく倒した清弦は、ろくろの覚悟を試すため戦いを仕掛け、さらに追い討ちをかけるようにろくろの心のキズとなっている「雛月 (ひいなつき) の悲劇」について話し始める 。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5f71b118-216f-4da2-a9fd-8c156c6a62f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67f5f2a5-9b7b-4e4e-88c0-6f291d38c34b', '26e8d696-755e-4950-a041-ede7e9a803aa', 9, '60736744', '交錯する悲劇 TRAGEDY COMES WITH SMILE', '「雛月の悲劇」―― かつて、陰陽師候補生養成所･雛月寮に突如として現れた数匹のケガレによって、候補生の子供たちのほとんどが殺されたとされる事件。この事件にまつわる話を清弦から聞いた紅緒は絶句する。「雛月の悲劇」の被害者でもある石鏡悠斗 (いじか ゆうと) は、実は紅緒の兄であり、唯一、生き残ったのがろくろだった。清弦の話を聞きろくろに詰め寄る紅緒。そのときろくろたちの前に、死んだはずの悠斗が現れる。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cba1ae56-6ee2-482a-b2e5-efd759549b35.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ac0717e-6c9e-41b4-ac02-2d087b543dba', '26e8d696-755e-4950-a041-ede7e9a803aa', 10, '60740740', 'すばるの修行 THE BEWITCHING GUARDIAN', 'ろくろたちの屋敷に、突然、紅緒のかつての師匠で、十二天将･天后 (てんこう) の名を冠する御幣島すばる (みてじま すばる) と騰蛇 (とうだ) の名を冠するタタラが現れた。悠斗と再会した禍野での戦いで自分たちの力のなさを思い知ったろくろと紅緒は、もっと強くなるため、すばるに頼み修行をつけてもらうことにする。快くそれを引き受けてくれたものの、どこか浮世ばなれしているすばるの修行 (?) はふたりにとって理解できないものばかりで… …。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/977cfaec-855e-4418-99af-dedcc84e1fad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4fc1246-fbeb-4a6d-b245-77394dec90a8', '26e8d696-755e-4950-a041-ede7e9a803aa', 11, '60745025', '新婚さんおきばりやす FANTASTIC MOMENTS', 'すばるに修行をつけてもらうことになったろくろと紅緒だが、いまだに本格的な修行をさせてもらえず不満顔。そんなふたりの気持ちを察したすばるは、かくれんぼで自分を見つけ出せたらたっぷりと修行をつけてくれると約束し、街に出かけてしまう。早速、すばるを追って街に出かけるろくろと紅緒。ふたりは協力してすばるの行きそうな場所を探すが、毎回ひとあし違いになってしまい…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7a6b6341-13bc-4ccf-9601-9b013eb55b38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1a91917-7fcc-4e5a-bb0b-371f8c220dd6', '26e8d696-755e-4950-a041-ede7e9a803aa', 12, '60748442', '勘弁しろし BASARA BOY KAMUI', 'ふたりで暮らし始めてから、ちゃんとした食事をとっていないことに気づいた紅緒が、特製ドリンク「紅緒スペシャル」を製作 (?)。あまりのまずさにのたうちまわることになったろくろは、自分が夕食を作ると言い出す。 ろくろが夕食を作っている間、日課のジョギングに出かけた紅緒は、その途中で両親の仇「神威 (かむい)」と出会う。神威は一介のケガレの強さをはるかに上回る力を持つ「婆娑羅 (バサラ)」と呼ばれるものだった。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e6a1b0c9-a7cf-40d5-9fc2-a6940a1a0a18.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4e01cd7-890e-4c0a-86e7-93d0e755e3c4', '26e8d696-755e-4950-a041-ede7e9a803aa', 13, '60752910', '君の勇気 私の勇気 ZERO MILLIMETERS APART', '十二天将クラスの陰陽師でなければ、到底かなわないと言われる究極のケガレ･婆娑羅―― その一体である神威は、より強い陰陽師と戦って倒すことをつねに望み、それゆえ「双星の陰陽師」を探していた。ろくろと紅緒が「双星の陰陽師」であることを知らない神威は、最初の一撃で、わずかながらも自分にダメージを与えたろくろに興味を持つと、その強さを極限まで引き出そうとする。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/43313f76-d044-4ed1-9b26-613addb663b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de57e62c-bf55-4c2f-ad75-e29abe36dbef', '26e8d696-755e-4950-a041-ede7e9a803aa', 14, '60756057', '浴衣と星と願い事 TANABATA SPECIAL', '年に一度の七夕をみんなで過ごすため、亮悟たちのいる星火寮を訪れたろくろと紅緒。さらに繭良も加わり久々に楽しい時間が過ぎてゆく。そんな中ろくろと紅緒が短冊に書いた願いごととは? 一方その頃、陰陽頭･有馬や十二天将は、京都の陰陽連本部にいた。温泉につかり、疲れを癒す士門と清弦は、婆娑羅としてはまだ若い神威の出現、故意に引き起こされたケガレ堕ちの発生を思い返し、今後の戦いに向け気を引き締める。そして有馬は、神託の「神子 (みこ)」の誕生を願う。陰陽師とケガレの戦いは、新たな局面を向かえようとしていた…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9982d3be-9390-4d75-a952-5e921d308d71.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aba5cad3-9df3-4cd8-aba6-b5f4605de870', '26e8d696-755e-4950-a041-ede7e9a803aa', 15, '60757674', 'ひとりぼっちに さようなら THE AWAKENING OF LOVE', '亮悟が、知り合いの陰陽師･罧原徹 (ふしはら とおる) から紹介された女性、柏原遥 (かいばら はるか) とデートすることになった。お互いにまんざらでもなさそうなふたりだったが、何度か会ううちに、亮悟の中で拭い去れない不安が大きくなってゆく。亮悟はそのことを罧原に相談するが、そんな亮悟に罧原は? 一方、陰陽頭･有馬からの指示で、鳴神町 (なるかみちょう) にとどまる清弦は、最近、この町の周辺で起きている異変について調べていたが…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ee7598cb-b66e-4536-ba83-99e493ddfc7e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e28c531e-ebef-46dd-bd81-da5629451272', '26e8d696-755e-4950-a041-ede7e9a803aa', 16, '60761564', '陰陽師として SALVATION THEN WAILING', 'もともと高い呪力を持つ繭良が、突然ケガレ堕ちになり、自我を失ってろくろや紅緒に襲いかかる! さっきまで「繭良だった」ケガレを祓うことにためらいがあり、本気で戦うことができないろくろと紅緒。なすすべもなく追い詰められて行くふたりだが、そこに清弦が現れた。 変わり果てた愛娘･繭良を呪縛から解き放とうと、苦しい選択をせざるを得ない清弦だったが、そのとき紅緒があることに気づく。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a5134fd3-b210-46b1-820f-37b64ff28744.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c91b1c93-bdba-40b6-9a4b-dd462fe054c2', '26e8d696-755e-4950-a041-ede7e9a803aa', 17, '60764762', '師がくれた赤い証 NEW TALISMAN FROM MASTER', 'ろくろや紅緒、清弦の前に再び悠斗が現れた。繭良を救うために呪力と体力を使い果たし、動くこともままならないろくろや紅緒を見た清弦は、ふたりに繭良を連れて禍野から出るように伝えると、ひとり、目の前の敵に立ち向かう。陰陽頭である有馬から与えられた使命を果たすため、かつての弟子が犯した不始末に、師としてのケリをつけるため、十二天将･白虎の名を持つ清弦が、本気の戦いを挑む!', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/17f62847-910e-4e65-b587-6489f0717288.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c522cb8-0733-4189-a8a1-39840b51ed33', '26e8d696-755e-4950-a041-ede7e9a803aa', 18, '60767146', '決戦前夜 TRIUMPH OVER FEAR', 'ろくろと紅緒は、自分たちの力で悠斗と決着をつける決心をする。決戦に備え作戦を練るふたり。だが一人前の陰陽師としての修行ができなかったろくろには使える呪装 (じゅそう) の数も少なく、今のままではとても太刀打ちできないことがわかる。そこでふたりは勝つための唯一の方法として、「双星」にしかできない技「共振 (レゾナンス)」を完璧に使いこなすことを考える。ところがいざ修行となると…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ad0650c0-401c-417d-8a02-8b8128752cc7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bdf754eb-62b5-44fa-a13c-ff40afb7f917', '26e8d696-755e-4950-a041-ede7e9a803aa', 19, '60769397', '罪もけがれも THE 10 SECONDS DECISION', 'いよいよ悠斗と決着をつけるときがやってきた。驚異的な力を持つ悠斗に立ち向かうべく、力を合わせて戦いを挑むろくろと紅緒は、レゾナンスを使った技を次々と繰り出して果敢に攻撃を仕掛ける。だがどんなに攻撃を仕掛けても、悠斗には致命的なダメージを与えることができない。そこでろくろは、悠斗を一気に追い詰め、この戦いを終わらせるために、清弦から渡された、赤い「星装顕符 (せいそうげんぷ) 」を取り出す。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7f90a614-5b3d-4d93-89ef-894716146838.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('140b4ba0-ec82-4fc6-a379-b171bf8f6831', '26e8d696-755e-4950-a041-ede7e9a803aa', 20, '60771632', 'ふたりの道 TO THE FUTURE WITH US TWO', '神威からもらった力を使い悠斗に戦いを挑む紅緒。これまで以上のスピードと高密度の呪力、重さを増した紅緒の攻撃は、徐々に悠斗を追い詰めてゆくが、そのとき、突如異変が!? 再び窮地に立たされた紅緒を救うべく、ろくろが傷だらけのからだで立ち上がる! ―「雛月の悲劇」が起こったあの日、つけることができなかった決着をつけるため、家族として、兄の罪と穢れを祓うため、それぞれ強い思いを抱いて戦うろくろと紅緒は、悠斗の野望を打ち砕けるか!?', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ecac7803-c7b1-4a39-948e-a26072c5e863.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5b5ceb7-5aa9-4e23-b567-27cd05c181ff', '26e8d696-755e-4950-a041-ede7e9a803aa', 21, '60774120', '双星新生 SWEETIE FAIRY', '高校生になったろくろと紅緒は、亮悟たち星火寮のみんなや遥、新たに陰陽師となった繭良とチームを組んでケガレ祓いをする日々を送っていた。そんなある日、ろくろたちは禍野で小さな女の子と出会う。自分の名前もわからない女の子のことを放っておけないろくろは、その子を「さえ」と呼ぶことにし、自宅に連れ帰ると、紅緒と協力して世話をすることにする。一方その頃、陰陽頭･有馬や十二天将らは、婆娑羅がかかわっていると思われる異変を確認。一同に緊張が走る―!!', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/eebf8c8c-cb48-4a3a-858e-ed666299d1e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('409475fc-293b-4acf-8f1a-68f1929800da', '26e8d696-755e-4950-a041-ede7e9a803aa', 22, '60775744', 'ケガれてんじゃ～ん PHILOSOPHICAL FILTHY SERAPHIM', '突如、鳴神町に巨大な気があふれ、ケガレが闊歩する禍野のようになってしまった。原因は禍野と現世とを隔てる結界に開いた穴「龍黒点 (りゅうこくてん)」の出現。清弦を中心に、ろくろや紅緒、亮悟たち、なぜか一緒についてきたさえが龍黒点をふさぐために駆けつけるが、襲い掛かる無数のケガレたちに苦戦する。さらにはその穴を通って、婆娑羅の珠洲 (すず) が、「真蛇 (しんじゃ)」と呼ばれる強い力を持つケガレを引き連れて現れ……。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/af27f27d-9a44-4dd2-bc8d-3e242a251a26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('263f8ab3-52e7-4146-b8d1-6adc86aaed7d', '26e8d696-755e-4950-a041-ede7e9a803aa', 23, '60779090', '双星 西へ HARD TO BE MOTHER', '龍黒点が現れた地域からの応援要請で、ろくろと紅緒、さえが現地に向かうことになった。亮悟たちも忙しく、三人を送り届けることもできない中、紅緒の式神･きなこが思いがけない活躍 (?) をする。現地に着いたろくろたちは、ほかの陰陽師たちと協力して事態の収拾にあたることになるが、そんな中、紅緒は、悠斗の一件から「化野家」をよく思わない一部の陰陽師から冷たくされる。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ead5af13-9884-4a84-96e9-e726f04696ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('189ad8e5-3d32-41c5-9faa-3a7eebaba592', '26e8d696-755e-4950-a041-ede7e9a803aa', 24, '60781816', 'ケガレの見た夢 WHAT IS BEAUTIFULL?', 'さえを連れ、新たな龍黒点が現れた遊園地にやってきたろくろたち。道すがらろくろから、「遊園地というのはキラキラしていて楽しい場所だ」と聞いていたさえは、龍黒点から噴き出す気のせいで、本来の姿とはほどとおく変化した遊園地にがっかりする。そんなさえの前に、禍野から来た真蛇･麗穏 (レオン) が現れる。暗く荒れ果てた禍野しか知らないレオンは、現世にはあるという「キレイ」を探していた。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ecca2d82-4b00-4add-8594-8d3403351313.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9cd56886-c6e7-4762-acc3-f3465967c92d', '26e8d696-755e-4950-a041-ede7e9a803aa', 25, '60784986', '天･元･空･我 COME BACK! SOUTHPAW', '突如、野球場に龍黒点が現れ、そこから噴き出す気と、その気から力を得た婆娑羅･山門 (やまと) によって街が崩壊。何とかして被害を食い止めようとするろくろと紅緒だったが、そんなふたりの前に十二天将の勾陳 (こうちん)･五百蔵鳴海 (いおろい なるみ) と天空 (てんくう) ･勝神コーデリア (かすかみ こーでりあ) が現れる。これ以上被害を拡大させないため、一刻も早く穴を塞がなければならないと考える一同。だが、問題の野球場は離れた場所にある。そんなとき、とある人物が近道の案内を申し出る。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/65030172-19ca-439b-b827-e153fe5a562a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d07ace1-dd0c-4f43-a690-1679c0019c73', '26e8d696-755e-4950-a041-ede7e9a803aa', 26, '60787266', '双星VS双生 BASARA TWINS'' STRINGS', '十二天将たちは、今回の異変の元凶として婆娑羅の闇無 (くらなし) を追っていた。その闇無から話を聞き、「双星の陰陽師」に興味を持った婆娑羅、千々石 (ちぢわ) と百道 (ももち) がろくろたちの前に現れる。もともと一体だったケガレから二体に分かれ、長い間一緒に行動してきた彼らは、互いに合図なしでも息の合った攻撃を仕掛け、ろくろと紅緒を苦しめる。レゾナンスも通用せず、いよいよ万事休すかと思われたそのとき…!', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5aaceabf-aa3b-4c8d-a863-460ffd78fb54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e8915bc-1744-400e-8988-7919ae2b8303', '26e8d696-755e-4950-a041-ede7e9a803aa', 27, '60790190', 'ひみつの繭良ちゃん MAYURA''S SECRET LESSON', '陰陽師となった繭良は、留守中のろくろと紅緒に代わり、亮悟たちとともにケガレ祓いに奮闘する日々を送っていた。だが戦いの最中にどうしてもツメが甘くなり、毎回のようにみんなの足を引っ張ってしまう自分が情けなくなる。そんな中、星火寮を訪れた士門と出会った繭良は、士門に頼んで修行をつけてもらおうとするのだが、気弱で自信のない心を見透かされ「覚悟が足りない! 」と一喝される。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5fe854e7-f274-4813-b033-6f8e1cae5a91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1d96c55-9f7c-49fc-991f-fabd8f71901b', '26e8d696-755e-4950-a041-ede7e9a803aa', 28, '60792635', '鸕宮天馬 (うのみや てんま) TRANSCENDENCE', '陰陽連の指示で、さえを連れて京都に向かう途中のろくろたちは、清弦からの連絡で、古くから霊地と言われている場所に龍黒点が現れたことを知る。龍黒点をふさぐため急いで現地に駆けつけたろくろたちは、彼らを待ち構えていた婆娑羅の鬼無里 (きなさ) との戦いに突入するが、ろくろたちの攻撃は鬼無里に少しのダメージも与えることができない。そこに十二天将のひとり、貴人 (きじん)･鸕宮天馬 (うのみや てんま) が現れた。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e1c177ae-b57e-4714-b256-f77081215446.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a58aa92-5e78-44f6-bc65-dbbdfbdc8c51', '26e8d696-755e-4950-a041-ede7e9a803aa', 29, '60795945', 'さえとの約束 MISSING EXORCIST MASTER', '久々に故郷･京都へと帰ってきた紅緒は、自分がよく知る場所にろくろやさえを案内することが楽しみな様子。そんな中、有馬から、龍黒点の発生を完全に止める方法が見つかったとの連絡が入り、ひとまず、さえを連れて陰陽連本部へと向かうことにする。一方、龍黒点がすべてふさがれることで計画に支障が出ると考えた闇無は、これを阻止するため陰陽連本部の結界をすり抜け侵入。計画に邪魔な有馬を葬り去ろうとするが、逆に禍野へと追い詰められることになる。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/00947c53-92bc-4073-82c8-b6e86ca76140.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d09aa5e6-b968-43e0-8731-60a9718d38e0', '26e8d696-755e-4950-a041-ede7e9a803aa', 30, '60798688', 'いつまでも笑顔で LOVELY SMILE FOREVER', '現世と禍野を隔てる結界を支える大樹「天の御柱 (あま の みはしら)」。最強の陰陽師･安倍晴明 (あべの せいめい) が作り出したとされるこの大樹の枝が折られ、結界が不安定になったことが異変の原因だった。龍黒点の出現を止めるには折られた枝を元の位置に戻し、結界を安定させる必要があるのだが…。 そうしている間にも上空に巨大な龍黒点が出現。大量のケガレがなだれ込み、現世が禍野の気に侵食されてゆく―。 各地に散らばっていた十二天将も続々集結する中、ろくろたちも大切なものを守る覚悟を決める。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f8c4f796-5a5d-49fa-894f-f57fea0b1652.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfba312d-abff-4478-aaca-99ed864a0d8e', '26e8d696-755e-4950-a041-ede7e9a803aa', 31, '60801363', 'そばにいるから WAI WA KINAKO YA!', 'プロ式神･きなこは、紅緒がまだ幼い頃からそばに仕え、ずっと主を見守ってきた。龍黒点出現の一件でも、紅緒やろくろたちとともに行動し一部始終を見てきたきなこは、今回起きたさまざまなことを思いながら、初めて紅緒と出会ったときのことを思い出す―。 その頃の紅緒は、目の前でケガレに両親を殺されたショックで心を閉ざしていた。プロ式神として主を理解し、信頼関係を築きたいきなこはあれこれ手を尽くすが、紅緒は一向に心を開こうとせず…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1d950064-5c96-46d9-8daf-0e06c9bfed9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('508fc439-31bf-428f-89d2-975ccc54bf91', '26e8d696-755e-4950-a041-ede7e9a803aa', 32, '60804145', '混沌の中に SEEKING THE PAST, SEEKING THE FUTURE', 'これまでの戦いで婆娑羅たちに苦戦し、身近で十二天将の強さを思い知らされたろくろは、今よりももっと強くならなければならないと考える。ずっと心の中にあった疑問と向き合い、さらに前に進むため、紅緒とともに星火寮にいる清弦のもとを訪れたろくろは、自分自身の記憶にある以前の話を聞き出そうとする。そんなろくろに清弦が話す過去とは? そして、一度は禍野へと去って行った婆娑羅の珠洲が、再びろくろと紅緒の前に現れ……。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4af6cf37-e1bf-4b2e-8d99-76d9883de6e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c905c19a-c711-48fc-9eb1-a18e19b0cc36', '26e8d696-755e-4950-a041-ede7e9a803aa', 33, '60806644', '師 (もろ) の恩返し I WANT YOU TO EAT ME', '姿を消した有馬を捜す十二天将たちに、有馬と同じ土御門家のひとり･御影 (みかげ) から、陰陽連本部に集まるようにとの連絡が入る。御影は有馬が姿を消してから陰陽頭代行としてその仕事を引き継いでいた。御影は、神託によって判明した有馬の消息について伝えるため、十二天将を召集したのだった。一方その頃、闇無は、密かに進めてきた計画が思惑通りに運んでいることに満足し、次の段階へと進める準備に取りかかっていた―。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/efa22b5d-1be6-404d-8dbb-001c2259d055.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c947a88-962b-4515-bf55-667e64332d34', '26e8d696-755e-4950-a041-ede7e9a803aa', 34, '60809203', '名コンビじゃねぇ! WACHI vs WASHI & WATASHI', '十二天将･大陰 (だいおん) の名を持つ膳所美玖 (ぜぜ みく) と六合 (りくごう)･蹉蛇桜 (さだ さくら) の父親は、かつてともに戦った仲間だった。だが彼は、桜がまだ幼い頃に婆娑羅の師 (もろ) に殺されてしまう。以来、美玖と桜にとって共通の仇となった師が、今ふたりの前に現れた。このチャンスに仇を討とうとする美玖と桜。一方の師はさらなる力を手に入れるため、十二天将であるふたりを倒してその呪力を喰らおうとする。 今まさに因縁の戦いが始まる。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/551a1b4c-be7e-43c9-9c6c-8294f7a98300.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85721457-8daf-44e8-88e2-e10f63cce8ea', '26e8d696-755e-4950-a041-ede7e9a803aa', 35, '60812038', '復讐の傀儡師 I AM NOT ALONE', 'ろくろたちの学校の裏庭で、木に打ちつけられた二体の人形が見つかったとのウワサが流れ、転入生として学校に潜入していた士門やろくろたちが調査に乗り出す。 問題の裏庭にやってきた一同は、そこに残っていた呪力の痕跡に気づくが、そんな中ろくろと紅緒だけが、突然、別の場所に移動させられる。そこにいたのは、前の戦いで苦戦を強いられた婆娑羅の千々石。千々石は「双星の陰陽師」を相棒･百道の仇として狙っていた。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/40443c68-fd0c-461d-920d-5f98c161ee60.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebeb39c1-b1dd-4a50-8632-83303c534640', '26e8d696-755e-4950-a041-ede7e9a803aa', 36, '60815034', '守るべきもの WHAT IS REALLY IMPORTANT?', 'いつの間にか学校中に呪力の糸を張り巡らせ、学校にいるすべての人間を思い通りに動く人形へと変えていた千々石。この作戦のせいで、うかつに攻撃ができなくなったろくろたちは、一旦その場から退却せざるを得なくなる。 繭良の機転によって、千々石の糸にとらわれた人々を解放する手がかりはつかめたものの、全員を無事に解放するのは簡単なことではない。そこで十二天将･朱雀の士門が起死回生の一手を投じるが…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/512a129f-e8e7-452e-8fdd-ac52c80d8cb0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb100458-9167-426a-baea-ed7691b780e7', '26e8d696-755e-4950-a041-ede7e9a803aa', 37, '60817626', '恋の町 舞い上がる TELL ME HONEST FEELINGS', 'ある日ろくろが一通の手紙をもらう。それは何とラブレターで、ろくろは繭良からのアドバイスもあり、送り主の女子生徒と会うことにする。ろくろがどんな返事をするのか気になる繭良、そして紅緒だが…。一方、龍黒点の一件は片付いたものの、今度は全国で相次いで陰陽師が失踪するなど、いまだ緊迫した状況が続く陰陽連では、さらなる大きな異変を察知。これを止めるため、御影から十二天将に伝えられた方法とは?', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3e7c4ea3-98db-460d-ae71-66be146ce6c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('249d47ee-22d6-423b-8ece-e4209eb90c02', '26e8d696-755e-4950-a041-ede7e9a803aa', 38, '60821968', '鳴神町最凶の日 NO WAY TO RUN, NO PLACE TO HIDE', '孤立した鳴神町に、巨大で禍々しいケガレが出現。焦りを隠せないろくろと紅緒だが、そんなふたりの前に闇無が現れる。闇無によると、自らが蓄えた呪力がなくならない限り、このケガレは何度でも再生するという。鳴神町を救うため、ろくろと紅緒が星火寮の仲間とともに巨大ケガレに挑む! 一方、脅威の再生能力を持つ婆娑羅･山門に手を焼く十二天将の青龍 (せいりゅう) ･水度坂勘久郎 (みとさか かんくろう) は、旧知の仲の玄武 (げんぶ) ･雲林院憲剛 (うじい けんご) に協力を頼むことに。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9be4f86e-2cde-4d86-a735-7ac518b17676.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcb47ccf-6daf-4f33-a3ad-ae58f1c25e95', '26e8d696-755e-4950-a041-ede7e9a803aa', 39, '60824272', '慈愛の霊獣 DAUGHTER''S FIGHT! FATHER''S DELIGHT', '巨大ケガレと戦う役目をろくろと紅緒に任せ、呪力を蓄えた球根部分を破壊しようと攻撃を続ける清弦と繭良。そんな親子の前に、繭良の母･紫 (ゆかり) を人質にとった闇無が現れた。闇無から、父･清弦が陰陽連の暗殺集団「律 (りつ)」のトップだったことを聞かされ、動揺しながらも、恐れることも嫌悪することもなく「お父さんが大好き!」と言う繭良。その娘の言葉と姿に、清弦は、初めて最愛の妻･紫と出会ったときのことを思い出す―。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ee9422b3-a323-421a-a851-fe9ebb85226e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41e60dc9-c0d0-4bf1-b8be-9292ccb5cffa', '26e8d696-755e-4950-a041-ede7e9a803aa', 40, '60827139', '双星ときめく FINALY THEY KISSED?', '巨大ケガレにトドメを刺すため、レゾナンスを駆使して戦うろくろと紅緒だが、強いダメージを与えてもすぐに再生するケガレに苦戦する。一方、十二天将たちは、いまだ危機的状況にある鳴神町を目の前にしながら、祓っても祓っても、キリなく襲いかかってくるケガレたちに阻まれて身動きがとれずにいた。タイムリミットが迫る中、さすがに焦りを感じ始める十二天将たちだが…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2de8f1a2-013c-4548-9ad6-ab52a3cf1ba0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b9a4fac-0374-4e94-a07f-bf564c83bae2', '26e8d696-755e-4950-a041-ede7e9a803aa', 41, '60830735', '十二天将、墜つ! HAVE A NICE NIGHTMARE, 12GUARDIANS', '十二天将の活躍もあり、何とか最悪の事態を回避することができた鳴神町。ほっとするろくろと紅緒だったが、そんなふたりの前に闇無が現れる。「これが始まりだ」と言う闇無の言葉を聞き驚愕するろくろと紅緒は、闇無を追って禍野へと向かうが、たどり着いたのは「天の御柱 (あめ の みはしら)」の枝が伸びる禍野の下層部。そこでろくろと紅緒が見たのは? さらにふたりは、因縁の相手である悠斗の姿を目にし…!?', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/369a780b-7693-4231-ae33-e87c7bc7911b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47d69cfb-ad9a-4ffd-8932-8d3ee39692c9', '26e8d696-755e-4950-a041-ede7e9a803aa', 42, '60833432', '故郷は禍野 SAY IT AIN''T SO,ROKURO!', '雪辱を誓い、これまで厳しい修行と戦いを積み重ねてきたろくろと紅緒が再び悠斗に挑む! 以前にも増して磨きのかかったレゾナンス技と、息の合った連続攻撃を次々と仕掛けるろくろと紅緒。だがさらなる力を得た悠斗はその力を使って強力な結界に紅緒を閉じ込めると、それぞれふたりを追い詰めてゆく―。必死の攻撃も通用せず苦戦を強いられる中、突如ろくろの身に異変が起き―!?', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f78714f8-374f-4ee9-a908-510a705ad206.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('310e1e1c-0321-483d-b27c-99e27cee9639', '26e8d696-755e-4950-a041-ede7e9a803aa', 43, '60836266', '千年の夢 MELANCHOLIC MISANTHROPE', 'はるか昔― 人々が安らかに暮らせる世を願う安倍晴明は、人々を救う中で、彼らが抱く怒りや憎しみ、嫉妬などが、この世に災いを為すと考えるようになった。だがこれら「陰の気」は思いのほか強大なもので、晴明は呪術によって「異界」を作り出し、「天の御柱」による結界の中に、あふれ出す「陰の気」を封じ込めることにした。だが人々が抱くそれらは増大し続けるばかりで…。――今からおよそ千年前に誕生した「禍野」と、それに対抗するため安倍晴明が仕掛けた壮大な計画、そして、明かされたろくろの秘密とは!?', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0ac4c4f9-7bbc-49f3-8b31-6a92ee0735c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49fedff6-704b-498d-a15e-e0b6e8e47f19', '26e8d696-755e-4950-a041-ede7e9a803aa', 44, '60840614', '愛すれど遠く FAREWELL, MY PRECIOUS', '決着がつかぬまま、悠斗との戦いを終えるしかなかったろくろと紅緒。紅緒は傷を癒すため休養していたが、戦いの最中、突如ろくろの身に起こった異変、悠斗が言った言葉がどうしても頭からはなれず、ひとり思い悩んでいた。一方ろくろも、生まれたときに与えられた自分自身の役目について考える中、ある決意をする。そんなろくろと紅緒が、それぞれ思い悩んだ末に出した結論とは?', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3faac1be-ec83-42a8-8b5f-69b96d0cdca8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8de95ed-54c8-4e81-a74f-4410b65e0c43', '26e8d696-755e-4950-a041-ede7e9a803aa', 45, '60844006', 'ひとりきりの二人 LONELY TWIN EXORCIST', 'あまりにも大きな力を持ちすぎたことで、陰陽連にとっても現世にとっても脅威となった悠斗。だが、闇無ら婆娑羅との戦いによって壊滅状態にまで追い込まれた陰陽連で今、悠斗に対抗できる可能性がある陰陽師はろくろのみとなっていた。因縁の相手と決着をつけ、自分自身の手で大切な人々を守るため、たったひとりで戦う決意をしたろくろが、悠斗の待つ禍野の最下層「常闇の間 (とこやみ の ま)」へと向かう。 ろくろ決死の戦いが始まった!', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/81409ded-f439-4b35-8ca3-6ccc78392421.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df1737f8-d6bc-4110-85e2-e091fbbc6435', '26e8d696-755e-4950-a041-ede7e9a803aa', 46, '60848663', '悠斗 DESTINY', '自分自身の運命に立ち向かい、乗り越えようとするろくろと悠斗の戦いは、決着がつかぬまま、ついにそれぞれが秘めた究極の力をぶつけ合うまでになっていた。だが、限界を超える力は、その強大さゆえにお互いの心とからだを蝕んでゆく―。 激闘の中、何度も力に飲み込まれそうになるろくろ。その脳裏に浮かんでは消えるのは、守れなかった仲間たちやどんなことをしてでも守りたい人々の姿で…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ebd1736b-4770-40af-99af-06212b898cdd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3871b407-b098-463a-9080-28e62126ae23', '26e8d696-755e-4950-a041-ede7e9a803aa', 47, '60852222', '紅緒 POSITIVE', '陰陽連の祖･安倍晴明が生み出し、業にまみれた人々を消し去る力を持つという「破星王 (はじょうおう)」―。 突如、千年後の現世に現れたその姿を目にした紅緒は、大きな不安にかられ、きなことともに「破星王」の現れた場所へと急ぐ。そんな紅緒を待っていたのは、陰陽頭代行を務めていた御影だった。紅緒の力が必要だという御影が語ることとは? そして紅緒は、ろくろを救うためにある決意をする。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5154a48f-6946-446f-a21c-96b326fb3a46.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd8b34ad-089b-41fe-9ac4-00262e7041a7', '26e8d696-755e-4950-a041-ede7e9a803aa', 48, '60856249', '団結 SOLIDARITY', '紅緒に救われたろくろは、自分が命を賭けてまで守ろうとした現世の変わり果てた姿に愕然とする。すべては、人々の「陰の気」が果てなく渦巻く世を憂い、現世を創り変えようとする安倍晴明の計画の内だったのだ。自分たちが暮らしてきた現世を元の姿に戻すため、死の淵から生還した陰陽頭･有馬やろくろ、わずかに残った陰陽師たちが、長い年月をかけた恐るべき計画に立ち向かう!', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5f77d9bd-e987-4734-9aec-c49e5061f7f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db1d20d2-9d3e-42ba-bc89-d6cfbe43f062', '26e8d696-755e-4950-a041-ede7e9a803aa', 49, '60860045', '復活 RESTORATION', '復活した安倍晴明が、千年の時をかけ実行に移した計画を阻止すべく、ろくろを紅緒の元へと急がせ晴明の前に立ちふさがったのは、陰陽頭･有馬だった。闇無との死闘により呪力のほとんどを失った有馬の決死の戦いが始まるが、そこに突如何者かが乱入してくる。一方、仲間たちに助けられ、やっとのことで紅緒の元にたどり着いたろくろは、紅緒から託されたあるものを取り出し…。', '2025/07/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/945d2a91-4ada-4016-b86b-bbde53dc2084.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4241635b-844b-4780-966e-d05c3dfdb35e', '26e8d696-755e-4950-a041-ede7e9a803aa', 50, '60864458', '双星 TWINS', '【最終話】あらためて共に戦うことを誓ったろくろと紅緒だが、晴明の計画はすでに最後の段階へと進んでいた。なすすべもなく諦めかけるろくろと紅緒。そのとき晴明に抵抗し計画を阻んだのは、「天の御柱」に戻ったさえだった。さえの言葉とこれまで出会ったたくさんの人々の想いに背中を押された「双星」が、最後の力を振り絞り再び立ち上がる! 「双星の陰陽師」VS「最強の陰陽師」― 現世の未来を決めるのは!?', '2025/07/01 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9d6a2159-04ef-4355-80a5-9e2b6ab96b01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c12397a1-8337-4be4-b31b-e37ddff83de4', '想星のアクエリオン Myth of Emotions', '', 'hulu', 'aquarion-myth-of-emotions', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/393b71d7-ee2b-4538-b021-70d5647b9a7f.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 162921, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('12abfccf-be7d-4034-9d32-14fb10f29b96', 'c12397a1-8337-4be4-b31b-e37ddff83de4', 'hulu-aquarion-myth-of-emotions-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25e2c080-00c4-4878-937a-02a41f285760.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e33d4d3e-c93e-4ad7-8a53-9621b64fff54', '12abfccf-be7d-4034-9d32-14fb10f29b96', 1, '100212709', '彼女の語る', 'オオトリサッコは、優秀な生徒が集められ、英才教育を施される〈私立江ノ島学園〉中等科の2年生。怖いもの知らずの性格で、クラスでもつまはじきにされている。そんなサッコが心を開ける幼馴染、イチキサヨが死んでしまった。彼女の葬儀で、なでしこの花を手向けたはずのサッコだが、ある日、登校してみると、サヨが現れ、神話のこと、1万2千年前のことを語りかけてきて……。', '2025/01/15 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25e2c080-00c4-4878-937a-02a41f285760.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6525e40-12c2-4b4d-a7d0-643b1f7433c2', '12abfccf-be7d-4034-9d32-14fb10f29b96', 2, '100213715', 'なでしこの願い', 'ベクターマシンが合体し、出現した機械天翅アクエリオン。神話獣を追い返したサッコたちは、敵は神話宇宙から攻めてくる堕天翅族であり、エレメントとは、堕天翅族に対抗しうる最終兵器･アクエリオンの搭乗者として選ばれた生徒なのだと明かされる。大人の押しつけに反発するサッコだが、幼いころ、江の島の洞窟で、サヨやモモヒメとロボットを作ったときのことを思い出し……。', '2025/01/22 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71b1b6ff-d3c6-40ea-a771-4aca6d8099a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('572e1b33-2330-442b-953e-13c637dbc701', '12abfccf-be7d-4034-9d32-14fb10f29b96', 3, '100214482', 'まだ知らない', 'サヨの葬儀が前倒しで行われたのは、宇宙の修正能力のせいだった。サヨがエレメントクラスにいたことを覚えているのはアクエリオンに乗った3人だけかと思われたが、モモヒメはそのことに勘づき、サッコたちを問いただす。エレメントクラスのことは口外するなと言われたサッコたちがなんとも答えられずにいると、その場にいた全員が、翅の生えた人々が暮らす超文明世界の幻を見て……。', '2025/01/29 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97ae78e2-534c-40e4-a75e-8c649c4e085b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa0cca16-b0d7-4738-aaf3-6cd7aa7430ad', '12abfccf-be7d-4034-9d32-14fb10f29b96', 4, '100215226', '尊い絆', 'サヨの死の真相を知りながら、アクエリオンに乗ることを決めたモモヒメ。彼女に憧れとも恋ともつかない想いを抱くリミヤだが、そのせいで感情のバランスが乱れ、絶不調に陥ってしまう。そんな中、モモヒメに誘い出されたリミヤは、「恋愛したことがない」と言う彼女がリミヤだけに対して持っているという「好き」の意味をたしかめるため、ふたりでデートに出かけることに。', '2025/02/05 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/088e37d7-061b-419f-9053-faee4fbbb783.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05a99231-3cc2-4a3c-9f1a-bdbbafe4ec87', '12abfccf-be7d-4034-9d32-14fb10f29b96', 5, '100216461', '誰か', '江ノ島学園に伝わる「江ノ学七不思議」は、4時44分に覗くと引きずり込まれる大鏡、嗤う人体標本などお決まりの怪談ばかりだが、7つめの怪異を知る者はいない。転校生にまつわる怪奇だ、誰もいないエントランスホールに響くピアノの音だと生徒たちが噂をする中、季節外れの転校生がやってくることに。その転校生は、美少年だとも、死んだサヨの姿をしているとも言われていて……。', '2025/02/12 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66d4615e-045a-437a-9104-73de9ed6978f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16f2ae08-3e33-4117-a5af-77c375037bd1', '12abfccf-be7d-4034-9d32-14fb10f29b96', 6, '100217561', '秘密を教えて', '不思議な美少年･サンと、サヨの妹･ハナをエレメント候補生として迎えた江ノ島学園。だが、サンはモモヒメに「ひとつになる約束を果たそう」と言いだすし、ハナはモモヒメを殺そうとするし、サッコたちは心中おだやかではない。モモヒメを連れ回すサンに業を煮やしたサッコたちは、彼と直接対峙する。が、サンが詠うように口にしたのは、学園や彼らの敵についての核心に触れる問いかけだった。', '2025/02/19 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/787a3360-61fb-4a39-ad8a-2f0b8873164d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e80b94ed-bfc0-492c-a295-a257f2d9a881', '12abfccf-be7d-4034-9d32-14fb10f29b96', 7, '100218511', 'ボクらの世界は', 'サンの微笑みに魅入られたのは、モモヒメばかりではなかった。学外の謎の団体に狙われるほどの影響力を持つ彼は、学園の生徒たちをも心酔させて、神秘的な集会を行うようになる。腑抜けになった生徒らに危機感を覚え、集会に乗り込んだサッコは、いつのまにか、サンの不思議な力で迷宮化した学園に迷い込んでいた。一方、戦闘中のハナは、神話獣を「意思あるヒト」だと認識してしまい……。', '2025/02/26 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6478abee-2132-477e-8bda-284c633d9e4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7067393b-ea33-4b0b-9029-50ea82578f34', '12abfccf-be7d-4034-9d32-14fb10f29b96', 8, '100219310', 'たまごの中で見る夢', '神話獣にも感情があると認識したハナは戦闘を放棄、アクエリオンを降りることになる。一方のサッコは、迷宮化した学園で見た謎のヴィジョンのせいか、サンのことが気になってしかたがない。それを察したモモヒメは、なんとかサッコとサンを近づけようと奮闘する。そのころ、学園ではサンを中心に集っていた生徒たちが暴走しだし、世界は神話宇宙の勝利に向けて修正されはじめていた。', '2025/03/05 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9c1ca44-b98f-4e47-b3f8-e095d3de0421.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6eca1e24-9499-4731-b395-11c950f6a313', '12abfccf-be7d-4034-9d32-14fb10f29b96', 9, '100220316', '輪廻の終わりに', '神話獣を追って亀裂を越えたサッコたちは、地獄のような光景の神話宇宙へと降り立った。なぜか見覚えがあるその宇宙では、欠けていた感情が埋まるようだ。そこで出会った堕天翅族は、感情だけの思念体として存在し、〈肉体の宇宙〉との合体を望んでいるが、それは〈聖なるたまごの子〉の意思であると言う。堕天翅族から戦いの真実を聞いたサッコたちは、元の宇宙に戻ろうとするが……。', '2025/03/12 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7f9ce609-c147-434d-a29f-3091fef115df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('600d1960-b47c-4f10-b45d-14a3fac83c7b', '12abfccf-be7d-4034-9d32-14fb10f29b96', 10, '100221348', '変わり果てた世界の中で', 'サッコたちが神話宇宙から戻ってくると、世界は様変わりしていた。江の島の空には地獄のような神話宇宙の光景が迫り、合体は間近であると知らせている。過去の因縁が明らかになる中、サッコたちは宇宙の合体と消滅を阻止するため、エレメント学園総生徒会長となった〈聖なるたまごの子〉サンを探すが、生徒会副会長となり学園の権力を握ったトシは、彼らの面会を阻むのだった。', '2025/03/19 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a10d5dd8-105a-4de6-b755-fe7a0fea20ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0271b589-ba0d-41cc-94e9-200337847a18', '12abfccf-be7d-4034-9d32-14fb10f29b96', 11, '100221965', '遠いむかしの約束と', '太陽と月と火星が接近し、最終決戦となる宇宙合体のときが迫る。モモヒメを失い、戦闘への意欲も失くしていたサッコだが、とあるできごとをきっかけに、まだ宇宙を救う手立てがあるのではないかと奮起。その直後、世界覚醒会議とトシの思惑により、基地に幽閉されてしまう。ところが、そんなサッコたちに、思わぬ助っ人が現れて……。', '2025/03/26 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df05efe7-1102-497d-835c-22e3b1380cf8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('097717d5-43d7-4e7e-8d16-17b32976de8a', '12abfccf-be7d-4034-9d32-14fb10f29b96', 12, '100222837', '愛の神話を語ろうよ', '【シーズン1 最終話】超神話獣に呑み込まれたベクターフェオー。サッコたちが超神話獣と死闘を繰り広げているうちに、ついに宇宙は合体をはじめてしまう。世界覚醒会議は、自分たちの勝利を確定させてデータだけの世界を実現するべく、衛星軌道上から超神話獣に向かって、地上を滅ぼしかねない攻撃を放つ。そのとき、過去と現在、想いと想いが重なり合って、新たな神話が響きはじめ――。', '2025/04/02 01:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0abd6e75-f224-49c4-8cf1-f7fd23ec73f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e195988e-74ee-469a-bd9e-e1ccf65abaef', '葬送のフリーレン', '', 'hulu', 'frieren-beyond-journeys-end', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98a851b0-1d18-4e57-8e0d-2e8f8cbda304.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 154587, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 'e195988e-74ee-469a-bd9e-e1ccf65abaef', 'hulu-frieren-beyond-journeys-end-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77f6578f-bd73-432b-98c8-eddc6403ffc0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19d10e9b-2070-48dd-93c1-a0388cb9d461', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 1, '100160214', '冒険の終わり', '魔王を倒し王都へ凱旋した勇者ヒンメル一行。各々が冒険した10年を振り返りながらこれからの人生に想いを馳せる中、エルフのフリーレンは感慨にふけることもなく、また魔法探求へと旅立っていく。50年後、皆との約束のためフリーレンは再び王都へ。その再会をきっかけに、彼女は新たな旅へと向かうことに―。', '2023/09/30 00:00:00', 1560, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77f6578f-bd73-432b-98c8-eddc6403ffc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75a1296c-a9ab-487e-ab18-9bcce6924ae2', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 2, '100160215', '別に魔法じゃなくたって…', '森深くに暮らすハイターを訪ねたフリーレンは、彼と共に暮らす孤児フェルンと出会う。ハイターから頼まれ彼女に魔法を教えるフリーレン。そしてある出来事を機に、共に旅立っていく。旅先でヒンメルの銅像がある村を訪れたフリーレンは、生前彼が好きだと言っていた花のことを思い出し…。', '2023/09/30 00:00:00', 1560, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44d83472-bd0a-4475-bcc3-11ff804db6eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae4be907-70dc-4c73-bdcf-60710515c6f1', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 3, '100160216', '人を殺す魔法', '交易都市ヴァルムへとやって来たフリーレンとフェルン。買い出しを手分けしようと言うフリーレンの様子を怪しむフェルンは彼女の後をつけることに。果たしてフリーレンの目的は…。その後、2人はとある村にやってくる。そこにはかつてフリーレンとヒンメルが戦った魔族･クヴァールが封印されていた。', '2023/09/30 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c410ccd-edfd-4d3e-9873-f8f1a562630e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab6116be-5e76-4754-92b9-ccaa473a6aad', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 4, '100160217', '魂の眠る地', 'フリーレンとフェルンはアイゼンを訪ねる。旧交を温める中、「大魔法使いフランメの手記」を探すことを手伝ってほしいと頼むアイゼン。3人は、ハイターが生前に割り出した手記が眠る場所がある森奥深くへ。フランメの手記と呼ばれるものはほとんどが偽物だというが、その場所にあるのは偽物か、それとも…?', '2023/09/30 00:00:00', 1560, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab381d4e-4c74-49d4-a86e-bac53aba1ef7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58ce038f-ef01-4780-b7e1-7e1bf1ee717a', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 5, '100161238', '死者の幻影', 'フランメが残した手記に記されていた“魂の眠る地〈オレオール〉”を目指すことに決めたフリーレンとフェルンは、アイゼンと別れ旅路を歩んでいく。今は魔王城があるその場所で、ヒンメルと話すことができるのか…。ある村を訪れると、村人が何人も幽霊に連れ去られ行方不明になっているという。', '2023/10/07 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/480ebfe8-b4d3-4bf0-b81b-edfa1d8742f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42d871ac-d49c-430e-95e8-4b97674fd0ec', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 6, '100162104', '村の英雄', 'リーゲル峡谷沿いの村で暮らすシュタルクは、紅鏡竜から村を守ったことで村の英雄として讃えられているが、実はとにかく臆病だった。それでも彼の実力を見込むフリーレンは、共に紅鏡竜を倒そうと声をかける。大岩を切り裂くほどの力を持つシュタルクだが、手の震えは止まらない。果たして戦いの場に現れるのか―。', '2023/10/14 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b2e3f37-b8e0-4bc5-8ae4-853e5e025a4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f9b072f-ddff-4ce4-b0a2-67b79f919877', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 7, '100163369', 'おとぎ話のようなもの', 'フリーレンたちは解放祭と呼ばれるお祭り前日の街にやってくる。そこはかつてフリーレンやヒンメルたちが魔族から守った町だった。町に建てられた自分たちの銅像を見るフリーレンはあることを思い出す―。その後に訪れたグラナト伯爵が治める街で、フリーレンは突然ある人物に杖を構える―!', '2023/10/21 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50dd1b58-94b4-4408-850b-60d67cb79f66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5690c1c5-c360-4e1a-abdd-dbef033ce74a', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 8, '100164105', '葬送のフリーレン', 'グラナト伯爵に和睦を申し入れてきた魔族アウラに仕えるリュグナーたちに魔法を放とうとしたことで、フリーレンは捕らえられ牢に入れられる。そんなフリーレンをリュグナーは危険視し、同じくアウラ配下のドラートがフリーレンの命を狙う。そしてフェルンとシュタルクもフリーレンを救うため行動を起こす。', '2023/10/28 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e89ce119-fd51-408d-8545-48335132c2e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b1c02ed-cb0a-47e7-8d2e-b2ac9ec2b39b', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 9, '100164806', '断頭台のアウラ', 'ひとり街を出たフリーレンは、七崩賢“断頭台のアウラ”と対峙していた。膨大な魔力を持つアウラは、死者の軍勢を次々とフリーレンにぶつけていく。一方、グラナト伯爵を救出したフェルンとシュタルクだったが、ふたりにもリュグナー、リーニエの魔の手が迫り…。フリーレン一行とアウラ軍の戦いが加速する。', '2023/11/04 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b02ce770-bccb-42f3-a764-8b0cc00978d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73345432-e91b-4dce-a5ec-41292abfd43a', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 10, '100165471', '強い魔法使い', '大魔法使いフランメ。千年以上前に生き、人間でありながら歴史上でも“英雄”と称される魔法使いだった彼女は、ある日魔王軍に襲われ全滅したエルフの集落で、ひとり生き残ったフリーレンと出会う。フランメがフリーレンに教えたものとは…。そして、フリーレンとアウラの戦いに決着がつく。', '2023/11/11 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b807b17-f5b0-413e-9729-63c80120503f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2acf282-8473-47ce-b1de-a4f1c44e7d3c', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 11, '100166127', '北側諸国の冬', 'アウラたちを倒したフリーレン、フェルン、シュタルク。平穏が訪れ、死後もアウラに操られていた自身の配下を弔い、グラナト伯爵は最大限の感謝をフリーレンに伝える。フリーレンたちは旅立つが、北側諸国の冬の道は想像以上に厳しく…。そこで彼らはひとりの武道僧 (モンク) に出会う。', '2023/11/18 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/056aeff7-3b64-4a18-a900-864d0f164e6c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89cd2032-a642-4322-9eb6-631b62f8106f', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 12, '100166740', '本物の勇者', '剣の里にやって来たフリーレンたち。そこは80年前に、世界を滅ぼす災いを撃ち払う者しか抜けない“勇者の剣”をヒンメルが抜いた場所。この里の周辺に湧いてくる魔物を対峙するという役目を務めるために訪れたのだった。そしてフリーレンの脳裏には、80年前当時のことが蘇ってきて…。', '2023/11/25 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f11f00f-4923-4cc6-b2b5-82ac60b3ffde.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fd70a7c-efa4-4217-b315-c2630a877486', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 13, '100167281', '同族嫌悪', '北側諸国アルト森林の村の教会で出会った、神父の弟･ザイン。治癒の難しい毒をいとも簡単に解毒する彼の高度な魔法を目の当たりにし、フリーレンは驚く。聞くと、ザインはかつて冒険者を夢見ていたが、旅に出ることなく、村にとどまっているという。ザインの兄は彼を連れ出してほしいと頼み…。', '2023/12/02 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e26b7f31-884e-4396-98dd-9a84b1ebf86a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03198a49-8b69-48cb-82b3-3e3e6c2a26a2', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 14, '100167847', '若者の特権', '僧侶ザインが仲間になり、ラート地方を訪れたある日、フェルンとシュタルクが喧嘩をしていた。聞くと、シュタルクがフェルンの誕生日に何も用意してなかったことが原因だという。ザインはふたりの仲直りをさせようとアドバイスを贈る。そんなザインにフリーレンが言葉をかけて…。', '2023/12/09 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e020b615-45b6-4aa4-a0ab-9acefe2a59df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6e6b4d6-4e58-4cf3-acb4-5fdb940399f4', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 15, '100168656', '厄介事の匂い', 'ラオブ丘陵の村にやって来たフリーレンたちだったが、村の人々は何らかの“呪い”によって眠らされていた。フリーレンによると、僧侶は女神様の加護により“呪い”が効きづらいという。“呪い”への耐性と知識を持つザインがその種類と発信源を割り出し、4人は原因である魔物の退治に向かう。', '2023/12/16 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7d02ce3-b3a9-4f1b-aac0-71421d63188b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79d71b77-fe88-47c5-a064-ebf42f2baf46', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 16, '100169378', '長寿友達', 'かつてフリーレンがヒンメルたちと冒険をしていた時に出会ったドワーフの戦士･フォル爺を訪ねた4人。彼はある村をずっと魔物から守っていた。フリーレンは会話を交わす中で、過去のヒンメルの言葉を思い出す…。その後、ある集落を訪れると、そこにはザインが昔共に冒険者になろうと約束した親友の足跡があった。', '2023/12/23 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9f3b14f-b71a-411d-8c6b-773394de9f06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ab0b407-4510-417f-9473-084b4677bc99', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 17, '100170661', 'じゃあ元気で', 'ザインは親友の戦士ゴリラの手がかりを得るも、彼が向かった先はフリーレンたちの目的地とは別の道だった。そんな中、滞在する集落に寒波が到来し、ひと月の足止めを余儀なくされた4人だが、それぞれの過ごし方で日々を楽しむ。ある日、フェルンとシュタルクが喧嘩をし、フリーレンはザインを頼るが…。', '2024/01/06 00:30:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2fcdffc2-5d41-4b20-ab53-06cfd34dc08d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d918cca-3bb4-43bf-8e3d-b68fd72d2573', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 18, '100171259', '一級魔法使い選抜試験', 'ザインと別れ、魔法都市オイサーストにやって来たフリーレンたち。この先の北部高原に入るには一級魔法使いの同行が義務付けられる。一級魔法使い試験は合格者が一人も出ない年もあり、そして死傷者が出ることもある難関。フリーレンとフェルンが向かった試験の会場には手練れの魔法使いたちが集まっていた。', '2024/01/13 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70ece4ef-6e21-4f3b-8fd0-224473235b23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0414569-67ec-43cb-a1b9-064e7ae8f3ad', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 19, '100171958', '入念な計画', '一級魔法使い試験の第一次試験は、3人ずつのパーティーに分かれ、試験場に生息する隕鉄鳥〈シュティレ〉を日没までに捕獲し、さらにパーティー全員が揃っていることが合格の条件。シュティレは捕獲が困難なため受験者同士の争奪戦＝サバイバルの様相を呈していく。カンネとラヴィーネと組んだフリーレンの作戦は…。', '2024/01/20 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/506f4fc5-0b07-42bb-83cd-47884781a17c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('566ba3ee-ee43-4d58-92e2-9a42a31e5613', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 20, '100172791', '必要な殺し', '一級魔法使い試験の第一次試験、フェルンはエーレと、ヴィアベルはユーベルと、ラントはシャルフと対峙する。ヴィアベルはユーベルとそれぞれ自身の魔法で戦う中で、彼女から危険なにおいを感じ取り…。一方、シュティレを捕獲したフリーレン組だったが、そこにデンケン･リヒター･ラオフェン組が狙いを定める。', '2024/01/27 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01193bd9-5904-4458-b717-fc60da4418f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e298efc7-9c7b-4f3a-bf2c-cca252d62012', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 21, '100173657', '魔法の世界', '一級魔法使い試験の第一次試験、シュティレをデンケンのパーティーに奪われたフリーレンたち。カンネとラヴィーネは圧倒的に魔力に差のあるリヒターに苦戦する。そしてフリーレンはデンケンとの戦闘の中である策を考えていた。日没が、第一次試験のタイムリミットが迫る。果たして二次試験に進むのは―!?', '2024/02/03 00:30:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47fbd5ae-bb1f-4f5b-befc-28b8d7bc251c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39c009b3-aa42-4736-aacd-653b722ff917', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 22, '100174781', '次からは敵同士', '第一次試験は18人が合格し、フリーレンとフェルンも二次試験へ。試験は3日後、合格者たちは解散し、各々でその時を待つ。フリーレンたちも宿へと戻るが、シュタルクがあることでフェルンの機嫌を損ねてしまい、機嫌を直してもらおうと3人はオイサーストの街へと繰り出す。すると偶然受験者たちと顔を合わせて…。', '2024/02/10 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b7de53c-be5c-48cd-a36a-2d645def0407.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('532ce110-688f-4f07-b5b5-298a4cb961d3', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 23, '100175189', '迷宮攻略', '一級魔法使い選抜第二次試験、試験官のゼンゼが用意したのはダンジョン攻略。「零落の王墓」の最深部に辿り着いた者は全員合格という。しかしそこは未踏破の難攻不落のダンジョンだった。フリーレンたち受験者はそれぞれ内部へと入っていくが、待ち受けていたのは魔物やトラップ、そして驚きの“魔法”だった。', '2024/02/17 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/351c7316-9b26-46b9-b3be-8440963ac534.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38598912-4924-4dbc-adfa-b9a2645af67d', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 24, '100175607', '完璧な複製体', '第二次試験でダンジョン「零落の王墓」に入った受験者たちの前に、彼らの複製体が立ちふさがる。その複製体は魔法によりそれぞれの実力･魔力･技術などを完全にコピーした実体だった。その中で、ユーベルたちは自身の複製体に遭遇してしまう。一方、デンケンたちはフリーレンの複製体を前に足止めを食らい…。', '2024/02/24 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0c9ff19-58fa-46ce-aed9-d07c7efb6eec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b9a1e2d-27a2-4063-8e79-0d194f2fbc1b', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 25, '100176299', '致命的な隙', '第二次試験の合格条件であるダンジョン最深部に行くには、フリーレンの複製体を倒さねばならなかった。複製体を前にしたデンケンやラヴィーネたちと合流したフリーレンとフェルンは、魔法使いたちそれぞれが持つ情報や知識で、複製体打倒の作戦を立てる。その中でフリーレンの脳裏に浮かぶ記憶とは…。', '2024/03/02 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5301f145-e018-4502-80d3-e435d6ffa7ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3117b8e9-49a3-468e-af1f-51e54466bf9f', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 26, '100176998', '魔法の高み', '零落の王墓に住まう神話の時代の魔物シュピーゲルが作った、王墓に入った者の複製体たち。シュピーゲルを倒すため、フリーレンとフェルンはフリーレンの複製体と戦うが苦戦する。一方、デンケンやラヴィーネたちも複製体と戦うが、試験官である一級魔法使いゼンゼの複製体の魔法が猛威を振るう。', '2024/03/09 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2130b6b1-0758-423f-8fe6-50a1ce643683.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21a3fccb-2d49-419c-b083-e4237acf80bb', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 27, '100177762', '人間の時代', '零落の王墓を攻略し、フリーレンやフェルンをはじめとする12名が第二次試験に合格した。その二次試験で粉々になってしまったフェルンの杖を直そうとフリーレンはある場所を訪ねる…。そして一級魔法使い選抜試験の最終試験、その合否のカギは、フランメの師匠で大陸魔法協会の創始者であるゼーリエが握っていた。', '2024/03/16 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69c1240e-def6-44db-a240-9b17a687100e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ef7681f-6cfd-41c5-a9fc-1426e3321a1c', '9ad6f6ce-932c-4c6b-a2fa-6a5da12c2a2f', 28, '100178447', 'また会ったときに恥ずかしいからね', '【最終話】一級魔法使い試験の最終試験、フェルンはゼーリエから合格を告げられた。続くデンケン、ヴィアベル、ユーベルたちの合否は…。そして試験を終えた受験者同士の間には、始まる前にはなかった不思議な感情が…。そして、フリーレンたちが魔法都市オイサーストを旅立つ時が近づく―。', '2024/03/23 00:30:00', 1463, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56a3f562-45d7-4f9e-a238-1085294d9cdd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f3b2edd0-c891-4153-950e-47a917c0219e', '葬送のフリーレン', '', 'hulu', 'frieren-beyond-journeys-end-season2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6462f1a-4575-4443-88fc-27f6f49ada64.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 154587, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d4a6f7d4-7388-4db2-8ada-e5441935077c', 'f3b2edd0-c891-4153-950e-47a917c0219e', 'hulu-frieren-beyond-journeys-end-season2-s1', '第2期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee958b25-4b18-4e8e-99de-2d8b6c475bc0.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('607742a2-8989-4657-b14d-a02fff4d6295', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 29, '100250760', 'じゃあ行こうか', '魔法都市オイサーストを後にし、北側諸国の道を行くフリーレン、フェルン、シュタルク。その道中、緩んだ地盤から穴の中へ落ちてしまう。そこは魔法を無効化する力を持った鉱石“封魔鉱”が一面に広がっていた。フリーレンとフェルンが魔法を使うことができず、地上に続く道を探すが、そこに魔物が現れて…。', '2026/01/17 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee958b25-4b18-4e8e-99de-2d8b6c475bc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('758e5c56-464e-4569-9b16-69d2a7650ce1', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 30, '100251467', '南の勇者', '北側諸国の村で勇者の像を磨く依頼を受けたフリーレンたち。その像はヒンメルのものではなく、かつて人類最強と謳われた“南の勇者”の像だった。フリーレンは“南の勇者”と出会った時を思い出す…。その後訪れたダッハ伯爵領の城下町で、フリーレンたちは領主から「魔族から宝剣を取り戻してほしい」と頼まれて…。', '2026/01/24 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/871b056b-a8bd-4336-bde3-e828409291a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0e9585b-5643-4e2a-8b90-5caa1c0c523e', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 31, '100252098', '好きな場所', '温泉地のエトヴァスでフリーレンたちは温泉に思いを馳せるが、山村はすでに廃れていた。山奥に「エトヴァス山の秘湯」があるという話を聞いた3人はそこに向かうことに。険しく、魔物も棲む山道を進んでいった先に待つものは果たして…。そして次の都市に到着すると、フェルンはシュタルクから意外な誘いを受ける。', '2026/01/31 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0eb2e0c5-7d8c-408f-8441-fdd53cf8dc6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b40389d2-5637-4cc6-8d40-9e9b6e8d7384', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 32, '100252815', '誰かの故郷', 'フェルンをからかうつもりで誘ったシュタルクだったが、結果2人はデートをすることに。街のさまざまな場所を訪れる2人はやがて展望広場へ。そこでフェルンが口にしたのは…。後日、街を後にした3人は過酷な北部高原へと足を踏み入れる。ある村落に立ち寄ると、その近くに強力な魔物が出現すると聞き…。', '2026/02/07 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dcf8948d-2d30-48cf-a7f0-cf6f37e4d077.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43f6e67d-d390-4212-8a0c-eafce3994ecb', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 33, '100253366', '北部高原の物流', 'ある酒場町でフリーレンはドワーフのファスと再会する。彼は無類の酒好きで、200年以上も皇帝酒ボースハフトを探しており、自身が掘った坑道の先にその酒が眠っているという。果たして見つかるのか…。そして次に訪れるノルム商会領では、なんとフリーレンに80年前から多額の借金があることが判明し…。', '2026/02/14 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ed46495-2103-432a-a73a-639788c6722a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce7825fd-d53a-4489-b1fe-14ff10ca0237', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 34, '100254771', '討伐要請', '北部高原のある村に、ゼーリエからの魔族討伐の要請を受けた一級魔法使い、ゲナウとメトーデの姿があった。その村はゲナウの故郷だという…。そしてそこに、同じく討伐要請を受けたフェルン、そしてフリーレンとシュタルクもやって来た。村はすでに全滅しており、犠牲者の特徴的な傷跡から、ある魔族の姿が見え隠れする。', '2026/02/28 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/136743cc-d06e-4391-955d-b9a9690f8491.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91221d8f-b078-4ebb-9a86-d9b6a010690b', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 35, '100255603', '神技のレヴォルテ', 'ゲナウの村を全滅させた魔族、それは四本の腕で剣を自在に振るう強敵“神技のレヴォルテ”とその手下たちだった。フリーレン、フェルン、メトーデの3人は魔族探索のため森へ、シュタルクとゲナウは村民の遺体をノルム騎士団が引き取るまで村に残ることに。そしてそれぞれに、残忍な魔族たちが近づく。', '2026/03/07 00:30:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df8ec58f-825f-4cce-bfc2-9f43bb2b14d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06b2169c-05e5-401e-9c11-2fc8d6a1cf21', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 36, '100256390', '立派な最期', '村に現れた“神技のレヴォルテ”に対するは、戦士シュタルクと、“黒金の翼を操る魔法〈ディガドナハト〉”を駆使するゲナウ。レヴォルテの強烈な攻撃に、2人は打ち勝つことができるのか…!? 一方、フリーレン、フェルン、メトーデも、強力な魔法を操る魔族ゾリーダとヘモンと対峙していた―――!', '2026/03/14 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/607d7c7b-d4cc-4e58-8256-4a42ec9dd765.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3c2b376-2ab9-445a-bb59-4064855770dd', 'd4a6f7d4-7388-4db2-8ada-e5441935077c', 37, '100256777', 'ヒンメルの自伝', '竜の群れの脅威に苛まれるも故郷を捨てようとしない男の村。そして広大な湖･コリドーア湖の港町。旅の途中、さまざまな場所を訪れるフリーレンたち。コリドーア湖で渡し舟に乗ろうにも舟代が足らず、船頭から交換条件を持ち掛けられる。それは島の修道院に眠っている“ヒンメルの自伝”を見つけることだった。', '2026/03/21 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80a79dde-bf50-4ef4-af88-eb04a9602f24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6d3f0837-9a4a-46c0-8a1d-32c68e108be4', '蒼天の拳', '', 'hulu', 'fist-of-the-blue-sky', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50028896_series_art__338x600_fist_of_the_blue_sky_0b12de6b85524941a4ed37435413b3fb.jpg?w=331&h=447&p=t', 'hulu', 2006, 3, 1, 'FINISHED', NULL, 1541, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', '6d3f0837-9a4a-46c0-8a1d-32c68e108be4', 'hulu-fist-of-the-blue-sky-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8290dd94-f625-4f86-a1aa-5ea541ea1a7b.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b71f6d81-5885-42e8-9ea7-d91c62976bea', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 1, '60874369', '賞金首･閻王', '1935年、満州国皇帝が来日。暗殺の恐怖に脅え続ける皇帝は、自らの護衛とするために上海の秘密結社、紅華会をたった一人で壊滅寸前まで追い込んだ北斗神拳伝承者“閻王”の行方を探していた。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8290dd94-f625-4f86-a1aa-5ea541ea1a7b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b87e656a-96ea-4992-8eea-6f9f9d7c49e9', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 2, '60874339', '江湖の義気', '上海を離れ素性を隠して教師として働く拳志郎は、命を賭して来日した李永健と再会する。李の口から語られる上海の朋友たちの死。そして、李を死に追い込もうとした皇帝のもとへ拳志郎は一人乗り込む。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a6df43b1-c5e6-4b7e-bb8f-d214978fc32e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfd1dfeb-74bd-43ca-9927-e3e6481bf0b3', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 3, '60874394', '北斗を継ぐ者', '皇帝の禁衛隊に捕らえられた朋友の李永健を救うため、拳志郎は、禁衛隊隊長で八極拳の使い手である金克栄のもとへと向かう。金はかつて上海で拳志郎と拳を交え、北斗神拳との決着を求めていた。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d6c1cc7d-0acb-42c0-a24f-397fef5858bb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a946675-ca1d-430a-a02f-fa4671e0cbfc', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 4, '60874378', '蒼天に願え', '圧倒的な拳格の違いで拳志郎は金克栄を破った。李永健は死の間際、上海に残して来た恋人の玉玲が紅華会に殺されたことを告げる。玉玲からの手紙を握り締め、拳志郎は上海へ戻る決意をする。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/12422b3b-944e-4ad2-bcb9-7e95db5778ad.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53bdc771-a0a5-4910-b5ed-0944645c6bca', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 5, '60874416', '上海に立つ', '上海フランス租界の闇社会は青幇に替わり紅華会が掌握していた。麻薬の売買や賭博から上がる莫大な資金を背景に、警察権力にも取り入る紅華会たち。堕落しきったこの上海に、ついに拳志郎が戻る。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e892e901-7014-435b-97ee-16e810e28b8c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8d948ba-94f1-4950-92f4-0d923b236b19', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 6, '60874383', '虐殺の処刑遊戯', '巨大賭博場「大新世界」で行われる処刑遊戯では、青幇のかつての仲間たちがリングに上げられ殺されていた。朋友の葉と再会し、紅華会の専横を聞かされた拳志郎は、葉に扮してリングに上がる。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4d12cb75-61ff-4b19-a096-488d3d0970ac.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('810a0453-17e9-4a2a-b144-3f182fe6bfe7', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 7, '60874414', '激突', '包帯で正体を隠し拳志郎は処刑遊戯のリングに上がった。対戦相手ゴランを軽くあしらう男が「閻王」だと紅華会に知れるには時間はかからなかった。一方、フランス陸軍大佐ギーズは、拳志郎へ興味を向けていた。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2dc157dd-c78f-4379-a044-5a119a1e32df.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68e5d82f-b4ed-451d-9608-11c97814a66a', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 8, '60874420', '地獄の神に祈れ', '「閻王」の上海再来に揺れる紅華会。闇社会からの資金を背景に成り上がった黄西飛も拳志郎の誅罰を受ける。紅華会は拳志郎の首への懸賞金を吊り上げ、さらに“奥の手”を探る。それは青幇にとっての“希望”でもあった。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/baacb7bd-8556-4715-9a01-66248f05c459.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4b0dcda-f04e-4727-a644-7835e2ca2085', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 9, '60874353', '血塗られた宿命ゆえに', '青幇の総帥、潘光琳が、紅華会の呉東来に捕らえられながらも生きているという情報を拳志郎はつかむ。潘の元恋人であり女優の楊美玉と接触した拳志郎は、玉玲を殺した男の名を告げられる。その名は「霊王」…。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/746beee1-923f-4e91-9903-e01acd2faa4c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00029601-1720-4ada-b710-094f4a85c3f9', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 10, '60874361', '北斗同士の闘い', '呉の居所を掴むため美玉のパーティーへ潜入した拳志郎は、会場の中で鋭い眼光を放つボーイの姿を見つける。不敵に笑うその男こそ「北斗孫家拳」の霊王であった。今、想像を絶する北斗同士の闘いが始まる!', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a9e2f572-62d6-419a-a68b-be6c35cd24ba.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4bc94ab-3e88-4f12-a206-7dd6b1f160df', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 11, '60874411', '龍に問え', '霊王との闘いにより負傷した拳志郎であったが、わずかな手がかりから潘の監禁場所を突き止めることに成功する。一方、美玉もギーズから潘が生きていることを知らされていた。しかし、呉を裏切った美玉に危険が迫る…。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9f33d3bb-d7d2-4283-bd57-623a78f19d75.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0398abae-fe4a-4b0b-9b16-3e72ab6685f1', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 12, '60874386', '復活の狼煙', '足を失いながらも拳志郎と脱出した潘の心には、青幇の再興があった。一方、ギーズは潘の救出を聞き笑みを浮かべる。この救出劇こそギーズ魔都上海･掌握計画の一環だった。利用されたと知った霊王はギーズの前に立ちはだかる。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/45d522b2-677b-470e-ac63-6a8657f7aedc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('995b7dc4-c340-4d14-bde2-518b3fac6457', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 13, '60874335', '魔道に落つ', '潘光琳の青幇再興の狼煙に呼応して、紅華会に虐げられてきたかつての青幇の男たちは集結しつつあった。紅華会との全面抗争を控え、潘はギーズと密会をする。その頃、北斗の男同士、拳志郎と霊王の最後の戦いが幕を上げていた。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8fc9d812-c010-4372-8b96-6a1e04be0799.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f6cd9f5-a91d-462f-8969-f5506b2169a3', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 14, '60874331', '運命の旅', '霊王･芒狂雲は拳志郎に敗れた。狂雲は玉玲を殺さず、記憶だけを奪ったことを拳志郎に告げる。一方紅華会は、霊王敗退の報を受け、拳志郎抹殺のために仏租界巡査部長カルネを唆してフランス軍を動かしていた。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bf676263-840f-4f52-834f-4ca38e3224ca.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b66211cc-d21f-46c4-a05b-e80a77aef41f', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 15, '60874360', '美しき馬賊', '潘光琳の率いる青幇により、紅華会の幹部は一人また一人と倒されていく。上海の勢力図は再び青幇へと塗り換わろうとしていた。その流れの中、謎の老人と向き合い自らの道を想う拳志郎。その頃、河北では美しい女頭目が率いる馬賊が台頭していた。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/daa2b057-63cd-4e76-8489-13465ba36838.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('272b2844-2268-4ad2-8bc5-a2005c004938', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 16, '60874365', '安息の地を求めて', 'ギーズと北大路には、続く戦乱により帰る国を失った民のための新国家「桃源郷」の建国という夢があった。だがその頃、紅華会は上海奪還のために、会の要である「北斗曹家拳」の張太炎を呼び寄せていた。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9b1e2c46-dacd-44bc-b6b8-dc70137a20d7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('523c4d26-d596-4481-9c47-e9fecf5ba281', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 17, '60874412', '死の宣告! 堕天掌', '何者かにギーズの秘書が襲われた。事切れる直前、秘書はギーズに「…脳を操る男が…」と言い残す。北斗曹家拳の使い手である張太炎がついに動き出したのだ。その魔手は、ギーズの妹ソフィーにまで忍び寄っており…。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/659d822b-13f8-4ec8-9d4a-30859cdab2b1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f498973a-f3e4-4831-ad8b-d04ccaa35934', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 18, '60874338', '北斗曹家拳の闘気', '張太炎の命で上海に北斗曹家拳の僧侶「五叉門党」が集結する。それは青幇と紅華会による最終決戦の幕開けだった。一方、拳志郎は張太炎を探すため、一人「桃華荘」と呼ばれる高級娼館を訪れていた。そこにも五叉門党の僧侶が姿を現し…。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/09c8fc0f-7f81-4cd4-81d7-87585b2d47e0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d4973bd-c089-4de1-9686-757b3a9f1457', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 19, '60874396', '毅然たる献花', '崩壊しつつある紅華会に、北斗曹家拳の張太炎が暗躍し始めた。北大路とギーズの「桃源郷」を作る動きに乗じて、呼び寄せた馬賊によって上海を混乱に陥れる。利用され殺された馬賊の亡骸に花を捧げる李秀宝。彼女の後姿に拳志郎は玉玲を見ていた。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/55cfc594-4895-4b21-8d2e-4d56673a4c21.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e51ec516-e40d-4dad-9cd2-d33b920e38f8', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 20, '60874366', '運命の悪戯', '日本軍は大陸深くまで進出し、李秀宝率いる馬賊は今や殲滅されようとしていた。秀宝は自らの命を捨てて部隊を帰順させる決心をする。拳志郎は過去を隠し、秀宝―すなわち玉玲の、日本軍との通訳として近づく。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/459b91ad-0f77-4b66-b1e7-2b12070b2631.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57c38035-f856-4759-8a0e-b8c539df0aac', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 21, '60874356', '燃えたぎる対峙', '李秀宝の指示により、上海で暴れていた馬賊たちは去った。拳志郎は名を偽り通訳として、日本軍との交渉を待つ秀宝の傍に控える。一方、馬賊の掌握に失敗した張太炎は、青幇の倉庫にペストノミをばらまくよう部下に指令を出すが…。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7fa1f3f4-cac2-4073-b027-a66c11b49185.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74737c91-9e27-476d-ace1-4237f9402310', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 22, '60874397', '張太炎の奥義', '張太炎らの居場所を突き止めた拳志郎は急襲を決行する。対峙した太炎の放つ秘奥義「爆龍陽炎突」。見えない拳に拳志郎は追い詰められる。この技こそ太炎自身が練り上げた自らの流派、北斗曹家拳を抹殺するための拳であった。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0b11bf75-083f-40cf-a685-206c529e21b3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd312953-ae18-49b4-8c16-f7f8f8023e3e', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 23, '60874419', '忘れ得ぬ痛み', '恐るべき張太炎の拳技。だが拳志郎の北斗神拳は太炎の技をも見切る格の違いを持っていた。死を覚悟した太炎だったが、五叉門党の二番星より、母の仇と憎み続けた北斗曹家拳伝承者である章大厳から受けた使命と真実を知らされる。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/19f6fb3c-44c8-4522-b4cb-438cfc2816d3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0337791-66f5-4561-888d-d0994022ea45', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 24, '60874373', '深く強き想い', '張太炎は父の章大厳と拳法家として死合うため去った。一方、李秀宝は、一人懐かしさを手繰るように上海の街を彷徨う。秀宝が馬賊の長として日本軍に処刑されることは明白だった。拳志郎は秀宝を見つけ共に街を歩くのだが…。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/12048446-32cb-48fe-99a6-ce87317db633.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d09fa7a6-2f16-4e04-bd8b-b6c49bd2e0f8', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 25, '60874425', '祝宴と銃声', '大川中将は李秀宝の処刑を決めた。馬賊は日本軍の敵であり、また中将の罪無き息子を殺した男も馬賊だったのだ。たとえ拳志郎らによりその男の首が届けられても、中将の信念は変わらなかった。だが秀宝は毅然として中将の前に進み出る…。', '2017/05/11 12:00:00', 1390, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e3d1620f-74f1-4daf-b258-5eb64df5f06b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db9071d1-de44-410c-a520-7d094c1c0986', '65daf08b-3dd3-4cf6-a8c5-c03181b3ebfd', 26, '60874350', 'より良い明日へ', '【シーズン1 最終話】紅華会残党の凶弾に潘光琳が倒れた。「生きろ! 玉玲のために!」呼びかける拳志郎の声に、李秀宝の心は揺さ振られる。それは北斗神拳ではなかった。二人の愛と絆こそが奇跡を起こそうとしていた…!', '2017/05/11 12:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e2a03354-ccbd-4532-8073-f33ac0bff7d2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('50192e17-c0d2-4487-9177-a4ffda809dad', '蒼天の拳REGENESIS', '', 'hulu', 'fist-of-the-blue-sky-regenesis', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cfa87e82-6862-4399-bc1a-81e1a0fe1c40.jpg?w=331&h=447&p=t', 'hulu', 2018, 1, 1, 'FINISHED', NULL, 100408, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('be462881-188f-4e10-9ec1-2ff095268d58', '50192e17-c0d2-4487-9177-a4ffda809dad', 'hulu-fist-of-the-blue-sky-regenesis-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4667157d-c411-4927-8eed-b1094fdff37b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('946ad259-1e67-4874-b237-dd8ea06cf54f', 'be462881-188f-4e10-9ec1-2ff095268d58', 1, '100048853', '北斗神拳伝承者 霞拳志郎', '時は193X年、「命の最も軽い街」上海。裏社会で勢力を二分する「青幇」と「紅華会」による抗争が激化を極め、ついに「青幇」の勝利によって終焉を迎えようとしていた。「青幇」を復活させた霞拳志郎と玉玲は、束の間の安息を喜んでいた。一方ハルピンでは、何かを大切そうに運ぶ流飛燕とエリカ･アレントの姿があった。針路を上海に定めた2人が目指す先は、フランス陸軍情報武官のシャルル･ド･ギーズ。しかし、そのギーズの前に不穏な人影が…。俺は第62代北斗神拳伝承者! 雷鳴とともに吠える拳志郎。北斗の宿命が新たなる闘いをいざなう。その先にあるものは光か闇か―!?', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4667157d-c411-4927-8eed-b1094fdff37b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6121c21a-7718-4b45-8664-dd73268f7e1a', 'be462881-188f-4e10-9ec1-2ff095268d58', 2, '100048854', '届かぬ願い', 'エリカが持つ「希望の目録」を巡り、フランス軍やドイツ軍をはじめ、様々な思惑が動き出す。夢を実現するために「希望の目録」を手にしようとしていたギーズも、突如現れた謎の拳法家の前に命をおとす。一方、飛燕は、エリカの屋敷で起きた惨劇を思い起こしていた。親子の「希望の目録」への強い想いを目のあたりにし、枯れていた涙を呼びおこしてくれたエリカを守りぬくことを誓った。「力で命は守れても、心は守れない」玉玲の言葉に突き動かされ、飛燕はあえて自らを鬼と化し、「死鳥鬼」として拳志郎と死合うことを決心する。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0fe84b4-7763-4b98-835a-a5aaceea2dd2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca09bbfb-4848-4fc0-9581-587de070a50f', 'be462881-188f-4e10-9ec1-2ff095268d58', 3, '100048855', '血を纏う死鳥鬼', '日本軍将校の射殺を端緒に、上海は緊迫し、世界大戦勃発の気配が立ち込めていた。迫る死期を感じとった飛燕はエリカを玉玲に託し、「希望の目録」に秘められた真実を語りはじめる。彼には、エリカの身を案じる悲壮な覚悟があった。大新世界で「青幇」の構成員を相手に大立ち回りを演じる飛燕の前に、拳志郎が現れる。再び拳を交えることになった、拳法家同士の悲しい宿命とは…。一方、この二人の壮絶な命のやり取りを物陰から窺い見る一人の男の姿があった。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14c722d0-e9d4-412b-bcb0-035796cd9f17.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f29cb08-8b86-445d-8c00-1a6d3185e23c', 'be462881-188f-4e10-9ec1-2ff095268d58', 4, '100048856', '北斗神拳の源流', '丘の上の教会で牧師となり、エリカと生きていくことになった飛燕。上海租界では政府軍が慌ただしく行き来し、戦争の不穏な気配が色濃く漂い始めていた。拳志郎は葉子英とともに、ギーズを手にかけた男を探しに、上海の表通りに繰り出していた。やがて路地にたどり着いた拳志郎は、シルクロードの匂いを嗅ぎ取る。政府が西斗月拳を使う拳法家を雇ったとの知らせを聞いた拳志郎。かつて、旅したシルクロードで目にした白狼を思い出し、西斗と北斗の血塗られた宿命をゆっくりと語り出すのだった。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6208361-5516-47e6-9b32-21e1aa7aea8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fd4c6de-8782-48f1-833c-2344e6c86159', 'be462881-188f-4e10-9ec1-2ff095268d58', 5, '100048857', '餓狼の怨念', '上海租界では、中国政府軍によって爆弾が撃ち込まれ、遂に戦争が勃発。潘の屋敷も爆撃の標的となった。爆撃を避けた聖堂で、拳志郎はエリカから、昨晩から飛燕が戻っていないことを聞く。「月氏の神は北斗を許さない!」飛燕の前に現れた西斗月拳の使い手ヤサカは、西斗が舐めた二千年分の無念を晴らすべく、捕らえた飛燕を自ら解放し対決に臨む。激闘の末、飛燕が目にしたのは、ヤサカの繰り出す西斗月拳の秘奥義だった―。「き、貴様あああっ!」飛燕の声が廃墟にこだまする。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/388254a6-f002-4333-a337-7a72550209cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecaafbd9-4be3-4600-bb1e-c20f650bf1f2', 'be462881-188f-4e10-9ec1-2ff095268d58', 6, '100048858', '旅立つ燕', 'ヤサカと飛燕の闘いの勝敗がまさに決しようとしていた時、一台の戦車が二人に近づいてくる。戦車から顔を出したのは、拳志郎! 朋友･飛燕を助けるために、戦火の燃え広がる上海郊外をひたすら猛進してきた。「お前…北斗に文句があるのか?」西斗の神の意思に突き動かされる西斗月拳のヤサカと拳志郎の死合が、今ここに始まる!! 一方、エリカはツバメの巣でヒナたちが鳴き騒ぐ教会で、飛燕の帰りを一心に待っていた。エリカが見上げた巣から、ヒナが次々と大空へと巣立っていく。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/101f58c4-558d-4653-95b2-a34855ebfe8c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ba60b81-6b01-4fb9-8e77-b0a55bb7b06d', 'be462881-188f-4e10-9ec1-2ff095268d58', 7, '100048859', '二千年の愛', '政府軍の砲撃に、水を刺された拳志郎とヤサカの対決。寧波の地に向かったヤサカを追うように、拳志郎も海を渡り、二人は北斗の菩提寺「泰聖院」で、再び相まみえることになる。2千年分の恨みをこめ、ヤサカが北斗神拳の伝承者たちが眠る鎮魂の塔を叩き割ると、強烈な光を発する勾玉が現れる。勾玉のまばゆい光の中に包まれたヤサカと拳志郎は、北斗と西斗の哀しみに満ちた凄絶な真実を知る。「なぜ…」。茫然自失となるヤサカが、光の中で見た西斗の憎しみとは一体…。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00224c84-f456-48b1-be1f-bcac69c8ab6e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7402486c-16ed-4bd3-aa1b-fd6517abeeb6', 'be462881-188f-4e10-9ec1-2ff095268d58', 8, '100048860', '宿命の死合い', '「さあ…死合おうかぁ」拳志郎が身構える一方で、ヤサカは、恨み続けてきた北斗の血が自身に流れることを知り、絶望する。歪められていた怨念に翻弄されていたことへの怒りが、ヤサカを突き動かす。拳を交える中、拳志郎はヤサカの秘めた覚悟を感じる。一方、玉玲とエリカは、「希望の目録」を追うドイツ軍に追われていた。絶体絶命の危機に追い詰められた時、突然、何者かが瓦礫から飛び出してきた。そしてその一部始終を、物陰から窺う巨漢の影がいた…。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3efd1583-2dbd-41b1-b457-d772281f62d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65aa49e8-bc40-4102-a690-6e088f92514e', 'be462881-188f-4e10-9ec1-2ff095268d58', 9, '100048861', '赦す者', '「光り輝く拳…?」拳志郎と葉親子とヤサカは、ギーズの体に残った「焼け焦げたような痕」から、とどめを刺した何者かの存在に行き当たり、ひとつの答えにたどり着く。教会近くの小高い丘では、飛燕の墓前でエリカが手を合わせていた。許しを請うべくエリカの前に進み出るヤサカ。エリカはヤサカの胸元に光る勾玉を目にし、勾玉に秘められた驚きの来歴を語る。拳志郎の周囲では、にわかにナハシュの民の存在感が色濃くなっていく―。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77b27acf-64d4-428d-8e97-66273ebe7b11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2b3203a-6067-4f52-b65e-5a1234e561af', 'be462881-188f-4e10-9ec1-2ff095268d58', 10, '100048862', '若き伝承者', '教会の霊園で起こった政府軍による襲撃を避け、上海の錯綜する路地へと逃げ込んだ羅門とエリカ。兄･拳志郎と交わした約束を果たすべく、「小さな守護者」として次から次へと攻撃してくる敵からエリカを守る羅門。しかしそこに、野獣のような巨体のシャムラが突進してくる。大通りでは、子英とともに政府軍の機銃掃射から逃れてきた玉玲も徐々に窮地へと追い込まれていく…。一方、拳志郎から逃げ惑う田楽田と河馬超の前には、外套を深く被った謎の人物が現れる―。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af26eddc-6063-4ebf-83d8-204d2e7007b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b41bbf91-15e6-415a-9987-78e4fd1b4bd8', 'be462881-188f-4e10-9ec1-2ff095268d58', 11, '100048863', '天斗聖陰拳', 'ドイツ軍が要求した羅門の交換条件は、ヤサカの持つ勾玉と「希望の目録」の重要な手がかりとなるエリカの身柄だった。拳志郎は一人、羅門を救うべく廃墟と化した寺院へ向かう。そこで拳志郎を待っていたのは、ドイツ軍に身をやつしたシメオン一派のシャムラだった。拳志郎と拳を交えるなかで、シャムラは「天斗聖陰拳」と口走る。一方、拳志郎の屋敷では、羅門の身を案じたエリカが、ヤサカの持つ勾玉を持ち出して玉玲たちの前から忽然と姿を消した。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/461d27eb-f1b5-497e-981e-8d9c0d865efc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8cb7c21-4e0e-4be2-b330-099145fc1fc6', 'be462881-188f-4e10-9ec1-2ff095268d58', 12, '100048864', '朋友を想う拳', '【第1期 最終話】北斗と天斗、遠く同じ流れを汲んだ二人の漢、拳志郎とシメオン･ナギットが、遂に対峙することになった。激しく繰り広げる攻防の中で拳志郎は、以前どこかで嗅いだ「ある匂い」をシメオンから嗅ぎ取った。ギーズの死の真相が、ついに明らかとなる!「朋友の文句は…、俺に言ええぇぇいぃっ!」凄まじい闘気が拳志郎を包み込み、シメオンの両腕はまばゆい光を螺旋状に周囲に放つ! 交差した両者の拳の結末はいかに!!', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96be9fed-6f6b-495e-83db-8575d7529f93.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', '50192e17-c0d2-4487-9177-a4ffda809dad', 'hulu-fist-of-the-blue-sky-regenesis-s2', '第2期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43cf35b0-c717-4321-9b33-00ddbc657dab.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67944b0f-12a7-4f7d-82b8-f932728a6471', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 13, '100048865', '神に選ばれし民', '戦禍の中国を離れ、インドネシア･ジャカルタで束の間の穏やかな時間を過ごしていた霞拳志郎らの前に、オランダ軍が迫っていた。そして、街では吸血鬼の噂が出回りはじめた。人々が誘拐され、ある実験が行われているというものだった。一方、拳志郎の前に、飛燕と同じ刺青を持ち、マントをかぶった男が現れた。男は突如、手刀を振り下ろし、拳志郎に襲いかかる。「北斗の文句は…俺に言ええぇいいいっ!」拳志郎の命を賭した最後の闘いが、今まさに始まった―。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43cf35b0-c717-4321-9b33-00ddbc657dab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f575871-9d84-47f0-a355-6c5960c46f89', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 14, '100048866', '義兄への憧れ', 'マントに身を隠していたのは、極十字聖拳の流緋鶴。流飛燕を兄と慕う女拳士であった。飛燕の死を知り、その恨みを晴らすことだけが彼女の生きる意味となっていた。一方、孤児たちと食卓を囲むヤサカとエリカの前に、謎の一団が現れる。突如、大音量で鳴り響くクラシックの調べ。駆けつけた拳志郎は、暗闇から現れたオランダ軍将校･コールと対峙する。「僕は最強、最高の人間兵器を創造するのだ!」人間を狂気へ導こうとするコールに拳志郎の怒りの拳が炸裂する。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5cfb407-9c23-4f5b-87f3-8c5b9005e510.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52b077b5-ebd4-45f0-aecc-fcf1cb7b6f95', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 15, '100048867', '現実になった予言', 'コールにより改造された人間兵器たち。コールは自身にも光る指を突き立て、人体改造を行い、拳志郎に手刀を突き入れる。「世界の『再創世』をおこなうのが目的だ～!」コールが最後に口にした『ミガドルの雷』『再創世』とは一体…!? 一方、エリカの前にはシメオン･ナギットが現れた。エリカを守ろうと立ちはだかるヤサカだったが、エリカとともに連れ去られてしまう。エリカを待っていたのは、驚きの事実とシメオンの恐ろしい目論見だった―。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eee81b5b-b821-4ba6-a01e-06683ed4eedc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6dd40eb-b3dc-433f-adaa-9c14318662ad', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 16, '100048868', 'ミガドルの雷', '「北斗神拳は人の心を救う拳。だから復讐など忘れろ。」玉玲から飛燕の最期の言葉を聞かされ、緋鶴は気持ちのやり場に戸惑っていた。その一方で、拳志郎はエリカとヤサカの行方を懸命に追っていた。地下宮殿に捕らわれたエリカは、ジェネシスの幹部から『ミガドルの雷』の真相を聞かされる。エリカの記憶にある『ミガドルの雷』と、父でもあり天才科学者でもあったロバート･アレントとは…!? 拷問を受けるヤサカの命を守るために、やがてエリカはある決意をする。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a34c3c2-4217-4fd6-894c-66e2d4df74cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('263d50ee-a7dc-42a0-84b3-3f1865c5ffff', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 17, '100048869', '交わらぬ想い', '拷問部屋では、ボロボロになったヤサカが鎖で繋がれていた。エリカを守るため、ヤサカは鎖を引きちぎり、天斗聖陰拳の遣い手であるシメオンに奥義を繰り出す。血飛沫が舞うシメオンとヤサカの闘いの最中、まばゆい光に包み込まれ、威厳を増したエリカが、『ミガドルの雷』の鍵について口を開きはじめた。その時、突如ジェネシスの地下宮殿の天井が崩れ落ち、霞拳志郎が現れた。「てめぇ、悪臭が増したなあ」拳志郎の眼が怒りで光る!!', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52757c60-6099-4ba2-bc08-fa4a346a593c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b43c12f-e0ac-44bf-bf68-f56d38f3a70b', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 18, '100048870', 'ナハシュの落日', 'エリカの前に、相まみえることになったシメオンと拳志郎。ついに北斗神拳と天斗聖陰拳、宿命の闘いが始まった。その混乱に乗じて、エリカを地下宮殿の廊下に連れ出したのは、ヒムカだった。エリカに、勾玉の在りかを執拗に迫る。果たしてヒムカの真の目的とは一体…!? 激しく打ち合うシメオンと拳志郎。互いに繰り出す拳を交え、シメオンの本質を見た拳志郎は引導を渡すのだった。「お前の拳は大昔に止まったままだ。まるで脱皮しねえ蛇みてえにな…」', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d43f519d-081d-4d6d-8b31-7bd1acb245ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35068393-ca91-4b3e-b55a-783e648f75c4', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 19, '100048871', '散り逝く漢', 'ジェネシスの宮殿は、自爆装置により崩壊が始まった。宮殿中に轟音が鳴り響き、柱や壁が崩落する。エリカと緋鶴を守る為、崩れ落ちてきた瓦礫の下敷きになったヤサカは爆炎に飲み込まれていった―。一方、地下宮殿最深部にある研究開発室で、シメオンはヒムカの仮面の下に隠された素顔を知る。「ヒムカか…そんな名は、もういらぬ」鋭く光る青い右目と金色に輝く左目のオッドアイを持つヒムカは、シメオンを欺き続け利用していたのだった。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6809e533-800e-4c42-87b9-2fed7ae6679f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8843d10b-3759-434c-81a5-6c861551eaf1', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 20, '100048872', '霞拳心の道', '鐘の音が鳴り響く高野山。北斗寺院の山門をくぐる者がいた。霞拳志郎の父でもある鉄心の前に姿を現したのは、ヒムカの名前を捨てた霞拳心だった。かつて、拳心は崖から落ちて倒れていたところを鉄心に助けられ、鉄心のもとで修行を積んでいたのだった。鉄心と対峙する拳心から語られたのは、かつて味わったこの世界のあり方への大きな絶望から生まれた、新たな世界の切望、『再創生』への道であった。「堕ちたな、拳心…」鉄心から闘気が放たれる。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2910168c-0513-4bcd-a227-3b505672ae7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('212f5949-cca9-46fd-8a02-764d691b9653', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 21, '100048873', '死合う運命', '北斗七星の脇で蒼く輝く死兆星。夜空を見つめるエリカは、その星から飛燕とヤサカが自身を見守ってくれていると健気に信じていた。そんな折、拳志郎の屋敷に傷ついた羅門が勾玉を持ってやってくる。父･鉄心が、拳心によって殺されたというのだった。拳志郎は父の最期を聞き、拳心に思いを馳せる。拳心こそが、拳志郎が幼き頃より最も畏怖すべき存在だった。再び、拳志郎の前に現れた拳心。北斗の星の宿命のもと、拳志郎と拳心の死合いがここに始まる!!', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70d33639-070f-4fdf-9a10-b4f0af9be859.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('291ab098-f0a0-4a76-8a95-769a3f0e46e5', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 22, '100048874', '受け継ぐ生き様', '「俺はこの腐った世界を終わらせる! この俺がリ･ジェネシスするのだああっ!」拳心は放浪で目にした世界の身勝手さや愚かさを、この世の真実として拳志郎に語る。拳心を前に防戦が続く拳志郎を見かね、エリカは強い覚悟とともに拳心に歩み寄る。そして2人は一陣の風とともに、こつ然と姿を消してしまう。拳心との闘いで秘孔を突かれた拳志郎の命の灯火も消えようとしていた。拳志郎は拳心との決着に備え、羅門に延命の秘孔を突かせるのだった。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/884d7d76-daff-4dec-aabf-a6f84de48469.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b49dbd7-8790-4f27-8335-c9337ceddc81', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 23, '100048875', 'ひとりの少女 エリカ･アレント', 'ノハァル･ナハ遺跡の玉座で、大小の勾玉に呼び起こされたエリカの記憶。核分裂装置の設計図は拳心が見下ろす羊皮紙に投影されて、徐々に描かれていく…。自らの死を願うエリカの悲痛な願いを受け止める拳志郎は、エリカの額に優しく秘孔を突いた。拳志郎の目から一筋の涙が頬を伝う。「俺は、目の前の少女の笑顔を守る。闘う理由なんて、それで充分だ」第62代北斗神拳伝承者としての最期の闘いが、いよいよ始まった。', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/942b466c-d425-4083-8cf1-4582be294b5a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02123fbc-c4be-44a9-a293-43888b8acc43', 'ad7a1fc2-3e5c-41eb-ad11-3ce986cb2156', 24, '100048876', '霞拳志郎と云う漢', '【第2期 最終話】天斗聖陰拳と北斗神拳を合わせた拳心の秘奥義が、拳志郎を呑み込む。「これが最期の一撃…俺の歴史は、今ここから始まる!!」「ならば俺は、この一撃に朋友の思いをかける…!!」互角の拳を持つ強者相闘う時、その両者の頭上に死兆星輝く。北斗の宿命のもと死合う拳志郎と拳心、2人の闘いの行方はいかに―!? 拳志郎の最期の闘いがついに決する!!', '2020/02/13 00:00:00', 1326, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d987d14-c90b-4478-9741-8404ab887d9c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8378d128-3f7d-480b-8e3a-e4d9c5a8f344', '蒼天航路', '', 'hulu', 'beyond-the-heavens', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50025494_series_art__338x600_beyond_the_heavens_d60f991e6f0b93a66bbb52147260b814.jpg?w=331&h=447&p=t', 'hulu', 2009, 1, 1, 'FINISHED', NULL, 5226, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d123e707-54f4-4340-86dd-11add23ff9cf', '蒼穹のファフナー', '', 'hulu', 'fafner-dead-aggressor', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15e69c22-7a90-4b2c-b4a0-18c5a0db7d76.jpg?w=331&h=447&p=t', 'hulu', 2004, 2, 1, 'FINISHED', NULL, 75, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4adef49a-4e45-4ca1-b7a8-e476053685ca', 'd123e707-54f4-4340-86dd-11add23ff9cf', 'hulu-fafner-dead-aggressor-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fc9f6d0e-d200-432c-a4be-69268a582222.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2595d50f-8ee6-4bf6-8ac4-b33ef6c1413a', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 1, '60701360', '楽園 ～はじまり', '大海に佇む孤島・竜宮島で、真壁一騎や皆城総士は平和な日々を過ごしてきた。そんなある日、空から「あなたはそこにいますか…」という声が響き渡る。そして突然、謎の敵フェストゥムが飛来する。フェストゥムによって無残に破壊されていく竜宮島を前に、アルヴィス司令官・皆城公蔵はファフナーの出撃を決意して…。', '2016/04/22 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fc9f6d0e-d200-432c-a4be-69268a582222.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb6e5c91-6fd9-423e-8e66-61137dc0b252', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 5, '60701343', '約束 ～ちかい', '一騎の行動は、結果的に新国連に竜宮島の存在を知らせることになってしまった。新国連のギャロップ事務総長は島の破壊をにおわせ、史彦にファフナーの引渡しを要求する。そして、ファフナー･マークゼクスを新国連に引き渡す日が来た。だが、竜宮島を目指す輸送船団の行く手に、フェストゥム･スフィンクス型が出現する。', '2016/04/22 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/834bf7ba-1d3f-4457-9efa-e407d517f373.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56722b5c-8579-4887-8a24-f1c4d6415850', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 6, '60701359', '翔空 ～ぎせい', 'マークエルフが新国連の船団を襲ったスフィンクス型の迎撃に向かった隙に、突如新たなスフィンクス型に襲われた竜宮島。破壊されていく島を見た翔子は、マークゼクスに乗り込むことを決める。一騎の戻る場所をこれ以上壊されまいと、翔子は捨て身の決意でスフィンクス型の前に立ちはだかり…。', '2016/04/22 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/19405c3e-6c14-42c8-9516-e811555d28b0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('696e3956-55df-48cb-b406-60ada5fe8e19', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 9, '60701357', '同化 ～わかれ', '島の上空に現れたフェストゥム･マスタータイプのイドゥンは、マークエルフとフェストゥムとの戦いを観察していた。そんな中、溝口と真矢を助けようとしたマークフィアーは、海中に出現したフェストゥムに捕まってしまう。そこに救援にやってきたマークドライが、マークフィアーのコクピットの回収に成功するが…。', '2016/04/22 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/07d93dc9-0e12-4409-9b56-ac82575a9776.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb90d71f-54ba-4a6d-a4b7-8f7fba344d8f', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 10, '60701347', '分解 ～すれちがい', 'ファフナーと仲間のどちらが大切なのか。竜宮島の未来を担う総士の答えは明確だったが、戦いの中で自分の居場所を見失いかけていた一騎は、総士の答えの中に自分の居場所を見出そうとしていた。そんな中、狩谷から外の世界への脱出を囁かれた一騎は、真矢に、自分のことを忘れないでほしいと頼むのだった。', '2016/04/22 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7d690419-d32b-4de8-b799-bd5863942e19.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('83cfe669-d62d-4889-85de-67ee3a9ce2f0', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 11, '60701349', '旧新 ～じんるいぐん', 'リンドブルムに搭乗した狩谷とともに、一騎はマークエルフで竜宮島を去った。総士は、一騎が自分を見捨てたのだと決めつけ、咲良は一騎の行為を裏切りだと切り捨てる。一方、狩谷に導かれ、新たな世界を目撃する一騎。たどり着いた密林の中、一騎はスフィンクス型の襲撃を受けてしまい…。', '2016/04/22 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/326cfba7-9f05-4e4e-a1d3-679964287a3f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('451a8653-a87f-42e1-8dfd-f47b8720d5f5', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 12, '60701341', '不在 ～あせり', 'フェストゥムの新たな襲撃に備えるため、アルヴィスは剣司と衛をパイロットとして投入することを決定。一方、真矢は何もできずにいる自分に焦りを感じていた。そして、一騎不在の中、竜宮島をフェストゥムが襲撃する。咲良のマークドライ、剣司のマークアハト、衛のマークフュンフが出撃するのだが…。', '2016/04/22 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a68f9232-0f66-4b7d-a455-a92f2e3fff2a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79965d49-5ba9-4f21-94b0-c04207378c69', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 13, '60701348', '侵蝕 ～フェストゥム', '狩谷からファフナーの戦闘記録を入手した人類軍は、ファフナーを新たな人類の武器として全世界に宣伝した。一方、一騎はモルドヴァで日野道生の父、洋治に会う。洋治は一騎に、戦う以外の選択肢を与えることができると話し始めた。しかしその時、イドゥンがモルドヴァ基地への侵攻を開始して…。', '2016/04/22 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c51b0422-d187-4efc-82c5-be656be4dc24.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42242cac-db26-4dc6-ad4f-bf05e7cb6e1e', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 14, '60701342', '覚醒 ～せんりょう', '真矢は溝口とともに人類軍モルドヴァ基地へ向かった。その直後、竜宮島に人類軍占領部隊が到着。人間相手に戦えない史彦は戦いを放棄し、島民の避難を優先させる。続々と上陸する人類軍占領部隊。晴れて人類軍の軍服に身を包んだ狩谷はワルキューレの岩戸へ急行するが、そこにコアはいなくなっていて…。', '2016/04/22 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e6d18df4-d347-4414-9ff1-4ee1b11ca063.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6aa0b04-7a90-4d75-a870-baf8cea748ac', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 15, '60701355', '記憶 ～さけび', 'ミョルニアは、マークザインを一騎に届ける。しかし、一騎は母そっくりなミョルニアを見て衝撃を受けていた。その直後、目の前でミョルニアがイドゥンに飲み込まれる光景を見た一騎は怒りの感情に取り込まれてしまう。その怒りはマークザインを変貌させ、フェストゥムや、周囲のものを次々に取り込んでいって…。', '2016/04/22 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/446e060a-06ad-4f08-86d1-6b0e65e49102.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c95a70f1-1b3b-444a-8dd6-1f5d8f59dbd0', '4adef49a-4e45-4ca1-b7a8-e476053685ca', 16, '60701351', '朋友 ～おかえり', '竜宮島では、人類軍占領部隊が島のコア以外の全てを掌握していた。しかしコア不在で手薄になった竜宮島の防衛網を突いて、フェストゥム・プレアデス型が襲撃する。そんな中、総士たちは乙姫に導かれ、ファフナーを取り戻す。出撃する咲良たちだが、強力な敵に歯が立たない。だが、そこに一騎のマークザインが現れて…。', '2016/04/22 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5d5d8298-f664-417c-8a04-f37ad87eddcc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
