INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f24a5976-70f6-4150-a313-c6d31c53df74', '蒼穹のファフナー RIGHT OF LEFT ～single program～', '', 'hulu', 'fafner-in-the-azure-right-of-left', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1ee3b2e-2877-4745-9f6a-8556a177cd99.jpg?w=331&h=447&p=t', 'hulu', 2005, 0, 1, 'FINISHED', NULL, 560, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2d6eeb02-4ba7-426b-8cda-4649d8505d95', '即死チートが最強すぎて、異世界のやつらがまるで相手にならないんですが。', '', 'hulu', 'my-instant-death-ability-is-so-overpowered-no-one-in-this-other-world-stands-a-chance-against-me', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97b792bb-554d-4830-979c-cb3efa0ab269.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 158028, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8553f9db-af5b-488a-b733-3a5b6a7e9cb7', '2d6eeb02-4ba7-426b-8cda-4649d8505d95', 'hulu-my-instant-death-ability-is-so-overpowered-no-one-in-this-other-world-stands-a-chance-against-me-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3341b17-91a4-469c-b999-648f3aef23ca.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('737f5bc9-2a33-405a-b9ef-b43725e45f86', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 1, '100171540', '即死チート', 'ゲームと昼寝が好きな高校生･高遠夜霧。修学旅行中、バスで移動していた夜霧たちは、突然現れた賢者シオンによって異世界へ召喚される。シオンから特殊能力《ギフト》を与えられた生徒たちは、この世界で高位の存在、“賢者”になるための試練に挑むことに。しかし、夜霧や壇ノ浦知千佳など《ギフト》が与えられなかった一部の生徒は、ドラゴンが迫るバスに置き去りにされてしまい……。', '2024/01/11 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3341b17-91a4-469c-b999-648f3aef23ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('829e92f6-c1fe-431e-bff2-b8bb1a97ace1', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 2, '100171938', '私の守護霊が最強すぎて、異世界だって楽勝です!', 'クラスメイトの後を追い、とある街を訪れた夜霧と知千佳。その街で2人は一見親切そうな獣人に騙され、犯罪集団に襲われる。《即死チート》で相手を殺し、窮地を脱する夜霧たち。だが、一部始終を見ていた衛兵に連行されてしまう。どうにかごまかして解放された2人だが、いきなり知千佳の姉にそっくりな守護霊･壇ノ浦もこもこが現れて……!?', '2024/01/18 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27135ba4-6c70-47c8-845f-5f4f9690276e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78edfba2-1d92-4978-84a2-0004fce90118', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 3, '100172731', '一方的に攻撃できるほど世の中甘くない', '日本によく似た街･ハナブサを訪れた夜霧たちは、クラスメイトの橘 裕樹と再会を果たす。再会の挨拶も早々に橘から愛人にならないかと提案された知千佳。困惑しながらも誘いを断り、その場はお開きとなる。後日、宿泊先のホテルで暇を持て余した様子の知千佳。一方、もこもこは何者かが知千佳に敵意を向けていることを感じ取り……?', '2024/01/25 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e33cf40f-db52-4830-817a-39d7ad162153.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6cc7e11b-c488-40e1-87d7-63c00362121c', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 4, '100173548', 'この映像をお前が見ているということは', 'ハナブサの街にゾンビたちを解き放ったマサユキ。賢者レインから夜霧と知千佳の抹殺を命じられた彼はゾンビの停止を交換条件に、街の住民に夜霧たちを連れて来るよう迫る。そんな状況の中、夜霧たちは自らマサユキの前に姿を現して? 一方、街の外から様子を伺うレインは、夜霧の《即死能力》にどれほどの力があるのか確かめるべく、新たな策を練っていた……。', '2024/02/01 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9724e8c8-2c0c-44ba-a7b5-04b4b9503276.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca8b461e-6e27-4fd0-b608-4f994d723a6d', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 5, '100174624', 'AΩ', 'ハナブサの街で起きた一連の騒動を解決した夜霧たちは、王都へ向けて出発する。出発早々、知千佳が運転する車の中で眠りについた夜霧。睡眠中、AΩ (アルファオメガ) と呼ばれ、『独立行政法人高次生命科学研究所』に隔離されていた幼少期の出来事を夢に見るのだった。その後、一同が乗る車はドラゴンの生息地へ突入。行く手には大量のドラゴンが立ちはだかり……?', '2024/02/08 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0002b6d2-4ad9-4559-bf37-b9480d0b82ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77a830d8-6fbd-4424-86e9-b7a18129c067', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 6, '100175121', '助けられといて文句を言うほど野暮じゃないですよ', '魔神と戦う存在･聖王の騎士を決める試練に巻き込まれた夜霧と知千佳。一刻も早く王都へ向かいたい2人は、全100階層ある試練の塔の最下層を目指し、行動を開始する。その道中、参加者狩りを楽しむ元聖王の騎士･テレサが一同の前に立ち塞がり……。その後、セーフエリアにたどり着き、しばしの休息につく夜霧たち。だが、そこでもこもこの身に異変が!?', '2024/02/15 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b6a30a9-e3bf-4387-bfd6-221c2af5af6c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3393371-ad86-4f2b-a523-628f1eccc955', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 7, '100175693', '第一門の常時開放を確認', '行方不明となった妹を探し、試練の塔にやって来た少女･テオディジア。彼女から協力を頼まれた夜霧と知千佳は、それを承諾。一同はテオディジアの同胞が囚われているという試練の塔の地下室へと向かう。一方、地上では、魔王の眷属たちが塔を襲撃。圧倒的な力で試練をくぐり抜けた聖王の騎士たちを追い込んでいく。窮地に陥ったライニールは一か八かで星結晶を使用すると……。', '2024/02/22 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9cffed4-2c0c-4567-bb66-b2f268ba44ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d9b13c8-a9e1-4b5b-9116-f4d08ea74a7c', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 8, '100176157', '機関', '夜霧の幼少期……。『独立行政法人高次生命科学研究所』に就職した高遠朝霞は、夜霧の世話と観察を任され、彼と共同生活を送っていた。ある日、休暇をとり久しぶりに外出した朝霞。その最中、夜霧を狙う『機関』に人質として攫われてしまう。1人で朝霞の帰りを待つ夜霧は一向に帰ってくる気配がない状況に痺れをきらし……。', '2024/02/29 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/637d7ad5-08e4-4235-a1c1-96b7f0fac0e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fcc7144-b78e-462f-b0f1-9dbcc94dd44d', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 9, '100176834', '自分だけ助かりたい一心のクラスって感じよね', 'マニー王国の王都に到着した夜霧と知千佳はクラスメイトたちと合流。一同は国王の命令で、魔界に封印された魔神討伐に挑むことに。そんな中、以前から夜霧の正体を知るというクラスメイトが数名現れて……。一方、試練の塔での一件で、夜霧の恐ろしさを知った賢者アオイはすっかり戦意を喪失。そんな彼女の姿を見たシオンは、本格的に夜霧の調査を開始する。', '2024/03/07 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6493445-cbe6-425a-b95b-3cb2587f8782.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('374247d6-990c-46e6-8ca8-4202b5758c83', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 10, '100177640', 'むかしのおんながあらわれた。ともちかはおどろきとまどっている……', '自分を見捨てたクラスメイトたちへの復讐に燃える篠崎綾香。人造人間である彼女は、ドラゴンの力を取り込み、圧倒的な力を手に入れクラスメイトたちを次々と抹殺していく。さらに、目的に邪魔な存在であるマニー国王さえも殺害してしまう。時を同じくして、篠崎とは異なる何者かの視線と殺意を察知した夜霧。犯人をおびきだすべく、知千佳と共に街へと繰り出して……。', '2024/03/14 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df635d2d-a24c-4978-9651-5311f8a56bb3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8bd40b7-f787-4038-9ea7-420d829fa3f7', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 11, '100178378', 'Phase 2', '賢者候補生たちの前に再び、姿を現したシオン。このままでは新たな賢者が生まれないと考えたシオンは、候補生たちに最後の1人になるまで殺し合えと命じる。理不尽な命令に一部の候補生は、抵抗しようとするが……。一方、デイヴィッドと共に魔界の第7層まで落下した夜霧は花川大門と再会。2人は封印から解き放たれた魔神マナの攻撃をかわしながら第6層への帰還を目指す。', '2024/03/21 00:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ce6a2d4-f231-4cc9-8ed3-f33d1c5c082d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6154d442-67b1-47fb-8359-52786eff07ad', '8553f9db-af5b-488a-b733-3a5b6a7e9cb7', 12, '100178711', '自分の好きなように力を使えばいいんだよ', '【最終話】クラスメイトとの壮絶な戦いに勝利するも、肉体の6割を失った篠崎。最後の力を振り絞り、体をドラゴンへと変貌させた彼女は、再びクラスメイトへの攻撃を始めるのだった。一方、わざと「賢者候補選抜戦」の範囲外に出て、シオンをおびき出した夜霧たち。《即死チート》を駆使して、彼女から元の世界に帰る方法を聞き出そうとする。だが、シオンは中々、口を割らず……?', '2024/03/28 00:30:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1420049-8166-4fb9-b2df-08cd81dc6faf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e88c167c-a273-4a97-bb19-128a36b822e5', '続 夏目友人帳', '', 'hulu', 'zoku-natsume-yujin-cho', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ec45ad8-7e75-4697-8850-a90c35ac177c.jpg?w=331&h=447&p=t', 'hulu', 2009, 0, 1, 'FINISHED', NULL, 5300, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 'e88c167c-a273-4a97-bb19-128a36b822e5', 'hulu-zoku-natsume-yujin-cho-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a4cb6cc8-89e8-4ff9-8847-20722bbc15bd.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e53068c3-611c-4154-9490-81a9fc880e01', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 1, '60083241', '奪われた友人帳', '小さな頃から、妖怪といわれるものの類を見ることができ、そのため周囲から疎まれてきた夏目貴志。用心棒の妖･ニャンコ先生と共に、祖母レイコの遺品「友人帳」に書かれた妖怪達の名前を返す日々を送るうち、少しずつ、レイコのこと、妖のことを知り始めていた。ある日、ニャンコ先生にそっくりの黒ニャンコ先生に「友人帳」を奪われてしまった夏目は、妖怪達の大切な名前を取り返すため、必死にその後を追う。妖怪の宴に向かったと聞いた夏目は、自分の危険も顧みず、その宴に向かうとニャンコ先生に告げる。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a4cb6cc8-89e8-4ff9-8847-20722bbc15bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1fcf8af4-d771-418e-b48e-7cb56a4ef0d9', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 2, '60083237', '春に溶ける', '雪の積もったある日、しばの原にやってきた夏目とニャンコ先生。そこにはかつて、二匹の森の守り神の像があったという。今では一匹しか残っていないその像から、夏目に乗り移ろうと襲いかかる人外の影が…!しかし誤って夏目の作った雪うさぎに乗り移ってしまった妖「玄」は、魔封じの木から放たれた悪霊を退治するのに力を貸してほしいという。玄が退治しようとしている悪霊とは…?', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3ec34dbc-2b37-4a9b-be94-07d31549bbd7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a2bbea5-0d71-45c6-9603-e713c239510e', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 3, '60083238', '妖退治 湯けむり行', '夏目と同じように妖といわれるものの類を見ることができる名取周一。表では人気俳優、裏では妖祓いをしている彼に誘われ、夏目は温泉旅行に行くことに。ニャンコ先生を伴い、二人と一匹、一泊二日の温泉旅行が始まった。旅を満喫する夏目だったが、周りで気になることが起こり始める。押入れからの物音、天井からぶら下がった着物姿の人影。旅行に連れてきてくれた名取のためにも、気を煩わせず、旅行を楽しもうとする夏目だったが…。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4f810cef-e761-4356-9fdf-90dacfe0bdc9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61dfaaac-85bb-41fa-a68d-a636ca3e673d', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 4, '60083240', '雛、孵る', '藤原家の庭先に産み落とされた卵。育てるもののいないその卵を、夏目はニャンコ先生と温めてみることにする。日に日に大きくなる卵、そして、それを主からの命で奪おうとやってくる妖。確かに生きているその卵を守ろうと決めた夏目の前で、ついに卵の中から姿を現したのは、なんと小さな小さな人の形をした「辰未」という妖の雛だった。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6febad47-8dfe-46b1-99e2-c21f28e696db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6de448a0-d81a-4f92-95e6-d0241d91db15', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 5, '60083246', '約束の樹', '夏目の姿を遠くから見つめる気の弱そうな妖、夏目と目が合うや逃げ出す始末。追ってくる理由を聞くと、友人帳の名を返してほしいのだという。名前の返還に応じる夏目だったが、友人帳は反応するものの、どの頁も示すことなく再び閉じてしまった。その妖怪「霧葉」曰く、レイコが50年経ったら名前を返すと言って、森の木の枝に結んでしまったという。結んだ紙をとるな、とレイコに脅されていたと聞いた夏目は、探し出したらその理由がわかるのではと思い、霧葉と森にやってくるのだった。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/325fe1ea-faa4-4418-bff8-7196e0dd8aee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54caed01-7f2e-48a0-803b-0ee1329f5fda', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 6, '60083239', '少女の陣', '散歩中のニャンコ先生を迎えに来た空き地で、地面に何かを一心に描く少女を見かけた夏目。声をかけると夏目の名を呼ぶなり、慌てて走り去ってしまい、その後には見慣れぬ陣が残されていた。翌朝、夏目は突然現れたチョビ髭の妖怪に、人間の娘が不吉な陣を書き歩いているので止めてほしいと頼まれる。チョビ髭に連れられて向かった場所には昨日の少女がいた。夏目の同級生で「多軌」と名乗るその少女は、夏目が妖怪を見ることができると知っており、力を貸してほしいというのだった。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6e4627fa-76f3-493f-acaf-c423c50f1dc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5bc3679f-710a-4979-9b18-309591e51a6a', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 7, '60083242', '呼んではならぬ', '自らの描いた陣に入った妖の姿を見ることができる少女「多軌透」。夏目の同級生である彼女は、ある日偶然目にした妖怪に祟りをかけられ、人と話すことすら許されない生活を送っていたという。夏目はその祟りをとくため、多軌･ニャンコ先生と妖怪探しを始めるが、突然その妖怪に捕らわれてしまう。必死にその場を逃れたものの、その目は妖怪を映さなくなってしまった。さらに困難を極めることとなった妖怪探しに不安を募らせる夏目達。そんな時、夏目の耳にささやきかける姿なき不気味な声が…。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/43601f13-73ae-4591-b049-ce4aef531d47.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2536c302-8eb2-400f-812a-3b68ec63f615', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 8, '60083244', '不死の想い', '西村･北本と共に、宿題合宿のため民宿にやって来た夏目。友との楽しい時間を過ごす夏目だったが、人魚の姿をした友人帳狙いの妖が現れる。なんとか難を逃れた夏目に、民宿の千津が語ったのは、幼い頃に出会った人魚の話だった。口にすると不老不死になるといわれる人魚の血―千津はかつて大切な人にそれを飲ませてしまったことを悔やみ続けており、その人を探しているのだという。それを聞いた夏目は、自分を襲った人魚に再び会いに行くが…。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/eacf0c66-14e8-4da0-858e-f1f219c941d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f32ee5b-7b1b-4f32-a6b7-9f41e7efb18e', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 9, '60083243', '桜並木の彼', '枯れの桜並木が描かれた絵を手にした日から、目覚めると部屋中が花びらで満たされるようになった。妖の仕業なのか―正体をつきとめようとする夏目とニャンコ先生の前に姿を現したのは、不気味な面をつけた妖「巳弥」だった。名のある妖が描いたというその絵に描かれた小さな人影、それはかつて巳弥と友人だったのだという。巳弥に絵を返そうとする夏目だったが、何故かその絵は壁から外れなくなっていた…。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/49183472-e047-4bca-a0b9-0e90db98918e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('209b7e38-1afc-4da1-bfb7-3c646a572828', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 10, '60083245', '仮家', '藤原家の門の前に残された足跡と落書き。おそらく妖怪のものであることに不吉な予感を覚えた矢先、家の中で奇怪なことが起こり始める。藤原夫妻に何か起こることを恐れる夏目は、かつてこの家で同じようなことがあったということを滋から聞く。そしてそれは、滋がある人に出会ったことで治まったという。その人のことを尋ねる夏目に、滋が子供の頃の話を語り出す。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7d81b1b5-50df-40e1-8ecd-0baff1769c4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8798b364-2fe5-4dd4-a52a-345905f4075e', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 11, '60083247', '呪術師の会', '手負いの妖が助けを求めるかのように、夏目の元に現れる。夏目の強い妖力を感じ取りやって来たのだろう、という名取は、夏目を呪術師の会合に誘う。同じ力を持ち、同じ痛みや苦しみを知る人達の中でなら、自分のできることを見つけられるかもしれないと、夏目は先生と共に会合に向かう。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7c56af7a-9227-466c-a0ce-83728dc999ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01dfc958-18cd-4d3b-91cd-1c2388c9e8f2', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 12, '60083248', '廃屋の少年', '夜ごと謎の物音や妙な声が聞こえると言われる洋館にやってきた夏目。子供のもがく声のする方に行ってみると、棺のような箱にランドセルを背負った少年が閉じ込められていた。箱を開けるなり泣きながら走り去った少年の残した名札を手に、その少年「カイ」を探す夏目は、カイがお化けに追われているらしい、という噂を耳にする。本当に妖怪を見て、そして追われているのならば守ってやりたいと思う夏目だが…。', '2020/11/28 00:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f1158fc2-4b5b-4e4e-896c-b6af3573b4d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b793d655-a4e4-42cc-9008-474b4fe3526c', '94e5abc9-cc05-46a5-8bf5-d73225ac96f5', 13, '60083249', '人と妖', '【シーズン2 最終話】カイを追っていたのは妖だけではなかった。名取もまた、カイを追っており、妖であるカイを退治しに来たと言う。突きつけられた事実を受け入れることのできない夏目に対し名取は、「自分にとって大事なのが人か妖か決めるべきだ」と告げる。カイが本当に妖なのか…。カイを探す途中、名取の罠に襲われる夏目を救ったのは、到底人のものとは思えないカイの力だった。自分を祓うだけでなく、夏目をも傷つけようとした名取に怒りを向けるカイは、ついに妖としての力を露にする。夏目にとって大事なのは人か、妖か…。', '2020/11/28 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1cc33508-d8ea-4864-a5c8-81917111444e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0b4bd1f1-c743-4e18-bbae-26e767cc8afc', '続・終物語', '', 'hulu', 'zoku-owarimonogatari', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebe9a90e-472c-434f-96ba-52c0e7d7adc3.jpg?w=331&h=447&p=t', 'hulu', 2019, 0, 1, 'FINISHED', NULL, 100815, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b1b2baf2-e32f-4d71-b9ff-d6322e4f5442', '0b4bd1f1-c743-4e18-bbae-26e767cc8afc', 'hulu-zoku-owarimonogatari-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1f3328f-ec6b-44aa-b13e-9d2e6f734706.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28ae28a9-908e-4c1c-a660-c2602853a660', 'b1b2baf2-e32f-4d71-b9ff-d6322e4f5442', 1, '100035784', 'こよみリバース 其ノ壹', '高校の卒業式の翌朝。顔を洗おうと洗面台の鏡に向かい合った暦は、思わず鏡に手を触れると、そのまま指先が沈み込んでいき…。気がついたとき、反転したような世界にいた。', '2024/07/04 00:00:00', 1476, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1f3328f-ec6b-44aa-b13e-9d2e6f734706.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d6bef35-e1bc-4c04-b664-d4cfde6cf259', 'b1b2baf2-e32f-4d71-b9ff-d6322e4f5442', 2, '100036077', 'こよみリバース 其ノ貳', '神原家で暦の前に現れた人物、そこで危機に陥った暦を救った人物、そして家に帰ったときに暦を待ち受けていた人物…。そのいずれもが、暦を驚かせるのだった。', '2024/07/04 00:00:00', 1476, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f157cfe3-c30d-457d-a889-495a37ddcd80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0bc949d2-95d9-4726-b740-2cbe015c98c0', 'b1b2baf2-e32f-4d71-b9ff-d6322e4f5442', 3, '100036452', 'こよみリバース 其ノ参', '事態の解決方法はわからないまま、長い一日を終えた暦は眠りにつこうとする。しかしベッドに入ったのもつかの間、余接によって起こされた暦は、ある人物の元へと案内されていく。', '2024/07/04 00:00:00', 1476, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bee03ed-4ed1-432e-8678-10161bd44e16.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9eaf4448-ab7e-4b13-8396-d46d1644a744', 'b1b2baf2-e32f-4d71-b9ff-d6322e4f5442', 4, '100036742', 'こよみリバース 其ノ肆', 'この世界における忍野忍は、吸血鬼ではなく人間だった。彼女から、暦がこの世界に及ぼしている影響について聞かされる。', '2024/07/04 00:00:00', 1531, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff8b2dd6-e9f6-4b4e-9c4e-d582fe7e271e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd54a1cb-ee43-4843-994f-3b0815d7c997', 'b1b2baf2-e32f-4d71-b9ff-d6322e4f5442', 5, '100037133', 'こよみリバース 其ノ伍', '余接の助力を得て、暦は神原家の風呂へ忍び込む。そこに現れたのは、本来は既に亡くなっているはずの臥煙遠江。いっしょに入浴をしながら、彼が陥っている状況に対してのヒントをくれた。', '2024/07/04 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf73209d-1020-4bea-9591-620a763d15c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bdcf7808-6aab-4ada-9d0a-f1766527d2a4', 'b1b2baf2-e32f-4d71-b9ff-d6322e4f5442', 6, '100037413', 'こよみリバース 其ノ陸', '【最終話】直江津高校のかつての一年三組の教室。待ち受けていた扇に様々な疑問をぶつけていく暦だが、扇は思いもかけないことを口にする。もしも、この教室から始まったあらゆる出来事が夢だったとしたら? と―。', '2024/07/04 00:00:00', 1561, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/277f89d5-2d0f-4fd9-a142-c748b42f1bee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7d5f0473-44af-4248-9606-339e19635505', '続刀剣乱舞-花丸-', '', 'hulu', 'zoku-touken-ranbu-hanamaru', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f08edaaf-82ff-4c3e-9a11-5b0c47a27e6f.jpg?w=331&h=447&p=t', 'hulu', 2018, 0, 1, 'FINISHED', NULL, 98520, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('427179f0-4777-4e8b-a877-b43f848988c6', '7d5f0473-44af-4248-9606-339e19635505', 'hulu-zoku-touken-ranbu-hanamaru-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa1ad532-4e9f-4bc4-82af-5e5e54637991.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5f2d765-12ad-4b2c-adcb-130dcdc57f0a', '427179f0-4777-4e8b-a877-b43f848988c6', 1, '100012966', '睦月「強くならなきゃ」', '大和守安定が“とある本丸”から旅立ったあとの大晦日。刀剣男士たちは、人間のように正月を祝うことを計画する。一方、源氏の重宝である『髭切』･『膝丸』が顕現、最古参の加州清光は、主から新刀剣男士のお世話係を命じられ本丸を案内する。そんな中、加州清光･獅子王･蛍丸･明石国行･髭切･膝丸に出陣の命が下り…。', '2018/01/11 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa1ad532-4e9f-4bc4-82af-5e5e54637991.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b6abb53-dc5b-482f-ae4b-69c61551300d', '427179f0-4777-4e8b-a877-b43f848988c6', 2, '100013207', '如月「明日もいい日になりますように」', '新たに顕現した『数珠丸恒次』は、山伏国広や加州清光らとともに、本丸の裏山へ修行に向かう。一方、一期一振･鯰尾藤四郎･骨喰藤四郎たちは財政難な本丸を救うため、大坂城の地下へ埋蔵金を探しに行くことになった。だが、骨喰藤四郎が転移先を誤ってしまい…。', '2018/01/18 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87aba58d-2e19-4a9c-819e-af7cff5df824.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7130cabd-c27d-49e7-a499-ac53f0ff1bf1', '427179f0-4777-4e8b-a877-b43f848988c6', 3, '100013584', '弥生「絶対負けね―ッ!」', '縁側でのんびりとお茶を飲む三日月宗近と小狐丸。そんな二振りへ近づく怪しい影が…。伊達忠宗に縁のある刀剣『太鼓鐘貞宗』が顕現した。旧知の仲である燭台切光忠･大倶利伽羅との再会を喜ぶ太鼓鐘貞宗。そんななか、鶴丸国永は最近の本丸には驚きが足りないと悩んでいた。', '2018/01/25 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b87cd3f-499a-40a9-b15b-c2a19c7adf95.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ba2b8ef-ce7f-4a0b-b288-907a4299aff0', '427179f0-4777-4e8b-a877-b43f848988c6', 4, '100013585', '卯月「この本丸の仲間だからだ」', '織田信長に縁のある刀『不動行光』が顕現。しかし彼は、へし切長谷部と言い合いをしてしまうなど、なかなか本丸に馴染めない…。卯月となり今年も万葉桜の樹が満開になったので、みんなで花見の準備をしていた。そのころ『小烏丸』が顕現し、花見を行うと聞きつけた彼も参加をすることに。', '2018/02/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3564e759-6ae7-4fe7-a503-466d01db90aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dec23592-a03d-4fdb-ab70-f4723e55c904', '427179f0-4777-4e8b-a877-b43f848988c6', 5, '100014241', '皐月「俺だから、できること」', '兄である長曽祢虎徹と蜂須賀虎徹に仲良くしてもらいたい浦島虎徹。誉を取った褒美に二振りが作った料理を食べたいと兄たちへお願いする。近侍の山姥切国広が二振りの刀『大典太光世』と『ソハヤノツルキ』を顕現させた。山姥切国広は同じ写しだと言うのに明るいソハヤノツルキのことが気になり後を追う。', '2018/02/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c5c227b-91e2-4d74-9362-7bae2236d649.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d545014-ddfc-41fe-84f8-aaf3d9f5bcd8', '427179f0-4777-4e8b-a877-b43f848988c6', 6, '100014474', '水無月「これからもよろしく」', 'ときおり悪夢にうなされている小夜左文字。そんな彼を心配する兄の江雪左文字と宗三左文字は、小夜左文字とともに花壇を作ることに。『後藤藤四郎』と『信濃藤四郎』が顕現し、本丸は一層賑やかになった。陸奥守吉行はそんなみんなの様子を主に見せようと、ビデオカメラで本丸内を撮影しはじめる。', '2018/02/15 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fb2ccf1-1a8a-46b1-bd3a-f9ecf0086718.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29d39f38-5b32-4a8b-896f-7a88d2936272', '427179f0-4777-4e8b-a877-b43f848988c6', 7, '100014711', '文月「いざ、大勝負」', '新たに『包丁藤四郎』と『物吉貞宗』が顕現した。加州清光は新刀剣男士お世話係として物吉貞宗を案内していると、不思議なことに行く先々で幸運なことが起こり…。とある理由で落ち込んでしまった博多藤四郎。そんな彼を元気づけようと、粟田口の兄弟たちはあることを計画する。', '2018/02/22 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ca3835c-6ea2-4842-a2d4-e10c013e5be8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0537eb2f-6e61-4c5b-9aab-6a0fd382a0bd', '427179f0-4777-4e8b-a877-b43f848988c6', 8, '100014712', '葉月「このことは秘密だからな」', 'へし切長谷部が遠征に行くことになった。『亀甲貞宗』と『千子村正』はへし切長谷部の不在を聞きつけ、留守中の“主お世話係”の座を得るため、勝負をはじめる。平野藤四郎が縁側にいる鶯丸へお茶を差し入れに行くと、彼は楽しそうになにかを書いていた。それは顕現した『大包平』に関するもので…。', '2018/03/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14dc1d34-5241-4b92-94fb-62cfa5053931.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8a94b48-5c86-40fe-8cc3-79783ab9dcd8', '427179f0-4777-4e8b-a877-b43f848988c6', 9, '100015347', '長月「たまにはいいですね…」', '本丸で暮らす刀剣男士たちの中でも特に背が高い太郎太刀。そんな彼は、次郎太刀に頼まれたおつまみを買うために万屋へ向かうが…。残暑も厳しい中、陸奥守吉行は道場で鍛練中の加州清光たちを誘い、暑さを吹き吹き飛ばす“趣向を変えた手合わせ”をしようと言い出す。', '2018/03/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f85ff9d-1254-440d-b400-b8ad6c2465cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb133ea3-02d8-4c2a-883e-4f54caee1254', '427179f0-4777-4e8b-a877-b43f848988c6', 10, '100015691', '神無月「ね、大丈夫でしょう」', '一期一振と喧嘩をした包丁藤四郎は浦島虎徹たちから気分転換に釣りへと誘われる。しかし心地よい陽気につい眠ってしまい、目を覚ますと知らない場所に着いていて…。大典太光世は自身の霊力で本丸に住む動物たちを怖がらせてしまうと感じ、別部屋で過ごしていた。部屋に食事を運んでいた前田藤四郎は、彼も皆と一緒に暮らしてほしいと悩む。', '2018/03/15 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33dfa562-5561-49cc-b2d7-8b9f4f8c7ee3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8072a2b3-e720-4cce-b7c1-816a406d0bb6', '427179f0-4777-4e8b-a877-b43f848988c6', 11, '100016037', '霜月「期待しているよ」', '季節は秋から冬へ。そんな中、信濃藤四郎は主の懐のような温かさを求めて、本丸内を探し回る。時間遡行軍が新たに江戸に出現。敵の狙いは恐らく伊達宗村と細川宗孝だと報告が入った。出陣部隊に選ばれたのは伊達家に縁のある刀と細川家に縁のある刀の六振り。歴史改変を阻止するためいざ出陣!', '2018/03/22 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c223fa2c-17ab-487d-929b-2db58251114a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4dd2999-c3b4-4c3d-8386-3f950cff0f62', '427179f0-4777-4e8b-a877-b43f848988c6', 12, '100016038', '師走「花丸な日々の物語」', '【最終話】主より、江戸に出陣している刀剣男士たちが危機に陥っていると聞かされたへし切長谷部。加州清光らと、なにか助ける手立てはないかと画策するが…。', '2018/03/29 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e216f60-4022-4a52-82c4-5dd2bb930127.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1f02df3a-58fa-4721-a58a-d3f5ff560e2d', '多数欠', '', 'hulu', 'tasuketsu', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/54b0fb16-0380-4da5-95d0-a121f8bf94b6.png?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 174070, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('76013098-50ae-42bc-8280-ee7c9ce9ccc0', '1f02df3a-58fa-4721-a58a-d3f5ff560e2d', 'hulu-tasuketsu-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab6dfc4b-4a3c-47b7-8d3c-b95e85f24390.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f8aa8732-bd82-4d20-a9ea-c4e27d2f3dd1', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 1, '100188987', '明日', 'ある日突然多数の命が失われ、100万人の東京都民のみが生き残った。それは多数派が失われる過酷なゲーム『多数欠』の始まりだった。親友の龍太を失った高校生･成田実篤は、仲間の藤代紗綾と共に『多数欠』を催す謎の存在･『皇帝』を倒す決意をする。', '2024/07/03 02:45:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab6dfc4b-4a3c-47b7-8d3c-b95e85f24390.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2fe566c1-6ca1-4bdb-b7af-a6cba5cf6f5c', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 2, '100188988', '善意', '『男or女』の二択を迫る多数欠で実篤たち全ての男が死んだ。悲しみに暮れる紗綾と依恋は、皇帝を倒すべく本日の指定区域の青いポストを捜しに行く。そんな中、ある“男”が特権利の力を行使し仲間を救うべく立ち上がる……。', '2024/07/10 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bdfcf7af-ae94-48a0-ab89-f634f80d4a35.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17913d34-46f0-4c53-88dd-91ee3b1daa9e', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 3, '100188989', '動', '須藤との密談で仲間の内に『裏切り者』がいることを知った実篤は、水面下で紗綾と動き裏切り者を突き止める。しかし強力な特権利を持つ協力者と共に裏切り者は実篤を殺そうとする。実篤の絶体絶命のピンチに駆けつけたのは……。', '2024/07/17 03:30:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d7cdaba-ca46-4c19-8efe-e714f1ff6751.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9535e13d-52a9-4c83-9edc-3bc41a2db236', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 4, '100188990', '転', '逃走中に実篤達とはぐれた一彦と臣は、中二病の少年･護国鳳天寺暴麟丸ことごぼうに助けられる。2人はごぼうの特権利を使って、実篤達との合流を目指す。一方『皇帝』は多数欠「セカンドステージ」の開始を告げる。', '2024/07/24 02:50:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45272bd5-16a2-40fe-ba46-913d72b7ceb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10e8d44a-64e6-4c11-9332-8cd473cf67b7', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 5, '100188991', '傍', '実篤達の前に姿を現した入賀は、情報の代わりに拒否権の所持者である臣を差し出せと言う。龍太は実篤を何とか逃がし入賀と戦う。圧倒的不利な戦闘の中、龍太は駆けつけた理科と八木橋に助けられる。一方練馬区の高校では、篠崎と須藤が御堂密と対峙していた。', '2024/08/14 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/399d297c-7353-4109-bf4b-23cc972280d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b069d2dc-ae6b-46e6-8bde-7e6147b92f54', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 6, '100188992', '集結', '突然姿を消す依恋。そして新たに仲間になる理科。特権利を得られないことに気づいた実篤は、臣から『特権利』と『収容所』の実態を聞き出す。その中で、少しずつ皇帝の持つ特権利が明らかになって行く。アジトを飛び出した依恋は篠崎の協力者である相馬と遭遇する。', '2024/08/21 03:30:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d102630d-e642-405d-85e7-dd4ff84b8fb4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d34cf28-474d-4a15-b486-cab6a04e5929', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 7, '100188993', '繋', '相次ぐ事実の露呈に動揺する実篤。グループを抜けようとするが、全員に引き留められる。須藤が導き出した皇帝の居場所の推論を確定させるため、実篤達は詳しい情報を知る御堂か入賀を呼び出す計画を立てる。一方入賀は、命令権の保持者である吉井鉄平の家を訪れていた……。', '2024/08/28 02:45:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2cc6c8a9-736c-429d-a477-cd35624b0d93.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67b036e8-b7df-4001-bd8f-5a6ba1d256f2', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 8, '100188994', '作戦', '御堂を尋問する実篤達に、御堂は不敵に皇帝の居場所を語る。それは須藤の推察通りの場所だった。明かされる実篤の特権利。御堂と入れ替わりに現れた入賀は、命令権の保持者･吉井鉄平の手紙を実篤に託す。確かな情報と二本柳達4人の新たな仲間を得た実篤達は、皇帝討伐作戦に向かう。', '2024/09/04 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cf869cc-2631-42bb-8ebe-a7bf53c1ff0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f87776a2-420a-42f0-a187-23c5677849d1', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 9, '100188995', '皇帝', '皇帝討伐作戦が始まる。皇帝の塔を取り囲む10万の傀儡の陽動作戦に挑む二本柳達。2か所の発電所を破壊すべく戦う八木橋、そして依恋と一彦。実篤、紗綾、臣、龍太によって構成される『チーム実篤』は、ごぼう達の援護の元、皇帝の塔へ突入する。', '2024/09/11 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af7684d2-1f33-4a27-80ba-fd5db23991f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c264a012-c090-48bb-a1be-cbe7c9a6a3fd', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 10, '100188996', '結', '遂に皇帝と対面する実篤。そして最後の多数欠が皇帝の塔で行われる。……すべてが終わり、残された者たちはそれぞれの道を歩む。ごぼう達によって作り出された新たな秩序の元動き出す世界。しかし、その在り方に疑問を持つ者がいた。', '2024/09/18 03:30:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c126dbc9-4616-4078-a1cc-d13716d372e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b17e886-e34c-450a-b1bf-e9694f8d5389', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 11, '100188997', '胎動', 'ごぼう達『偽りの皇帝』の支配の下、かろうじて秩序を保つ世界。そこへ彼らの偽皇帝配信に先んじて、『皇帝』を名乗る何者かがテレビ放送で呼びかける。動揺するごぼう達はテレビ局へ相馬の現化獣を差し向ける。そこに待っていたのは一人の少年、王野頼音だった。', '2024/09/25 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee3eb635-dcad-413c-9b32-57ab63fb49b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e66844b4-f712-4cf7-8f30-19063fe6c4f6', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 12, '100188998', '要', '現化獣にアジトへ運ばれた頼音は、偽の皇帝であるごぼうと対面する。頼音は巧みな話術でごぼう達の手の内を探ろうとするが、依恋の服従権に従い真の目的を語る事になる。その時『女王』を名乗る何者かがテレビ放送で偽皇帝に宣戦布告する。', '2024/10/02 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19864cf6-9682-4d3b-83de-cd683b6e780c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('928834d9-2ef5-4f69-a857-1be137362958', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 13, '100188999', '衝撃', '大切な親友を多数欠で失い皇帝を憎んでいた頼音は、平山との戦いで能力を認められ正式にごぼう達の仲間になる。女王達を迎え撃つ為、放送局へ乗り込む煮しめ、頼音、相馬。予想外の特権利を有する新たな敵との戦闘に苦戦する。絶体絶命のピンチに駆けつけたのは……。', '2024/10/09 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c140cf7-ff0f-43c6-8222-7647f3cc4708.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a2b3c9b-7013-41b5-9210-3f48abeb554f', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 14, '100189000', '嘘', '女王は敗退した賀来戦を前線から離脱させ、代わりに嘉藤騎士と璃莉兄妹、睦月冬哉の3人を召集する。睦月は深見率いる不良集団エンペラーを壊滅するが、その後現れたある人物に手玉に取られ捕縛される。一方篠崎はまだ幼い頼音のブレインとしての能力に疑問を抱く。', '2024/10/16 02:45:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d800601-3b5f-4a76-a7a7-154245e05878.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6f8ae74-5036-4d13-8393-abffcbcc5e9f', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 15, '100189001', '尋問', '皇帝の塔で騎士とめぐると対峙する頼音、臣、龍太。頼音は『嘘』を巧みに操りめぐるの拘束に成功する。一方、龍太は融合権を駆使して戦うが、騎士の強力な特権利を前に苦戦する。そのピンチに姿を現したのは、八木橋とあの2人だった。', '2024/10/23 03:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ecfcd18-2a5e-413c-96c6-c432eebadd7d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07d240ee-a95c-4106-b027-8bf74ffe9281', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 16, '100189002', '仲間', '捕らえた睦月を尋問し情報を得ようとする八木橋と須藤。巧みな誘導尋問に頼音は本物のブレインが帰ってきたことを痛感し、組織の中での自分の立ち位置を考える。停止権を入手していた八木橋は、睦月とはまた別にある重要人物を保護していた。そして須藤は今までの女王の行動から状況を推論し、新たなる作戦を皆に伝える。', '2024/10/30 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bce59412-5b8d-4884-8817-fa68230f7240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb5d166a-9844-45c2-8d46-47bf71197eda', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 17, '100189003', 'シナリオ', 'セラフィエルの教会に拠点を移動した女王は総力戦を決意。そんな彼女の前に、協力者として入賀と深見が姿を現す。臣は東北の旅で得た情報を元に、特権利を呼び出す『イタコ』がいる可能性を皆に説明する。そして、須藤の指揮の元、東京封鎖作戦が実行される。苦戦するも敵を撃破する頼音たち。しかし女王が新たに得た特権利により、形勢が逆転する……。', '2024/11/06 02:45:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2307fb95-80ab-43c7-b8bc-0aa4450226ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('269e2a14-5136-48fe-b29c-48683efd391c', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 18, '100189004', '暗躍', '作戦の結果に士気の下がるごぼう達の前に入賀が姿を現し、女王陣営の情報を伝える。そんな中、皇帝の多数欠放送が再開。絶体絶命のピンチに陥る一同だが、ごぼうの機転で一命を取り留める。一方女王陣営では、八木橋の仕組んだ騎士へのトラップが波紋をもたらす。そして明かされる、皇帝と女王の意外な関係……。', '2024/11/13 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1974071-d017-412c-ae9d-2ee18162c62d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04c6edb6-5ca9-4318-becb-ee2f6d139629', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 19, '100189005', '無邪気', '八木橋のやり方に疑問を持つ頼音は八木橋と須藤を問いただすが、軽くあしらわれてしまう。回収権を再び手に入れた皇帝･陽翔は都内で特権利狩りを始め、抵当権の保持者･葛西甲斐を手下にする。皇帝が前線に出てきたことを知った須藤は、龍太と頼音を皇帝の元へ向かわせる。', '2024/11/20 03:30:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21cf7ec1-fe90-436c-9d24-43f2d684eda0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8522299-5cf6-40a0-b343-6a875b5de148', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 20, '100189006', '忠誠', '二重スパイとして女王のアジトに潜入する頼音は、ごぼうの表示権を活用し、アジトの所在地を絞り込むことに成功する。しかし入賀から情報を得た女王に、現化権の所持者である相馬を連れてくる様命令されてしまう。危険の伴う行為に悩む偽皇帝陣営だが、蛯名光の脱出を手助けする条件で須藤は相馬を送り込む決断をする。', '2024/11/27 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7bb91696-49a9-4f67-bfbc-f5a5cdcd2d83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6bb13d0c-e381-46d0-9ff3-a11db8c3a67f', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 21, '100189007', '運命、あるいは奇跡', '光脱出作戦の結末を知り、愕然とする頼音。作戦の発案を悔いるが、依恋の発破を受け立ち直る。女王陣営では、平山と深見が作戦を決行する。しかし霧島コウによって封じられてしまう。そして女王、霧島輝、セラフィエルの真の関係が明らかになる。', '2024/12/04 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1cec0677-c585-4812-98a7-a46ff1fc4368.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd3d1c83-2f77-4326-8bfe-83521c238cea', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 22, '100189008', '特攻戦線', '『特権利』の全ては霧島輝の発明した『マザー･ライト』に起因していた。命令権の保持者･吉井鉄平が多数欠で死んでいたことを入賀から知らされた女王と皇帝は、皇帝の塔へ赴き吉井鉄平の遺体を回収する。そして遂に偽皇帝VS女王&皇帝の最終決戦が始まる……。', '2024/12/11 02:40:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/472e0dc2-2637-4ef7-bdd5-9c9c251d7fd9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7237bb29-6257-4b6c-90d9-f82b29fe1b1f', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 23, '100189009', '決戦', '計算されたチームワークで敵を次々倒していく偽皇帝チーム。そんな中、八木橋と入賀は分割空間で女王の目をくらまし会話をする。皇帝･陽翔と過ごす中で心に変化が生まれた頼音だが、須藤たちの描いたクレイジーな作戦を成功させるため、入賀と手を組み最強の敵･霧島輝と戦う。', '2024/12/18 03:30:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02ae9bbf-a10c-4dfc-953f-66a5f7daee55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53eb35cc-7af3-4372-94b7-9f571e62ef65', '76013098-50ae-42bc-8280-ee7c9ce9ccc0', 24, '100189010', '光の指す方へと', '【シーズン1 最終話】停止権が解除され、遂に最後にして最強の切り札が動き出す。戦況を見て命令権の保持者･吉井鉄平の蘇生を決意する女王･如月。頼音は交渉権の解除を皇帝･陽翔に申し入れ、嘘偽りない本当の想いを陽翔に伝える。そして吉井鉄平が目覚め、遂に命令権が行使される。', '2024/12/25 02:30:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51afcff2-25d8-41cd-9806-ef1b7ba7804f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0b886e1d-5da2-4413-bea8-e56fdb16de87', '多田くんは恋をしない', '', 'hulu', 'tadakoi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60aa75ff-b43a-440e-8fa5-f0ebe249a89c.jpg?w=331&h=447&p=t', 'hulu', 2018, 1, 1, 'FINISHED', NULL, 100179, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('24ea115b-6950-4ae2-b85d-b98796c839fd', '0b886e1d-5da2-4413-bea8-e56fdb16de87', 'hulu-tadakoi-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3238611a-c836-48c0-97de-77b8f13b8da3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d8ae1c4-82d3-4bcc-995d-af41674ff3c9', '24ea115b-6950-4ae2-b85d-b98796c839fd', 1, '100017294', 'ほっとけないだろ', 'カメラを手に、満開の桜の写真を撮りにきていた少年･多田光良 (ただ･みつよし) は、異国の少女･テレサに出会う。ヨーロッパのラルセンブルクという国から留学してきたテレサは、日本に着いて早々、一緒にやってきた連れとはぐれてしまい、迷子になっていた。成り行きからテレサを助けることになった光良は、祖父が営んでいる東京･銀座にある多田珈琲店へと連れていくのだが…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3238611a-c836-48c0-97de-77b8f13b8da3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e5e7965-9238-44f1-a49c-a65758c4605e', '24ea115b-6950-4ae2-b85d-b98796c839fd', 2, '100017600', 'まぁ、間違っちゃいない', '多田と幼なじみの伊集院薫 (いじゅういん･かおる) が通う、銀河大学付属恋ノ星高校に転入生としてやってきたテレサとアレク。恋ノ星高校の生徒は必ず部活動に所属しなければならないという校則があるため、二人は、同じクラスの委員長･長谷川日向子 (はせがわ･ひなこ) と共に、いろいろなクラブを見学して、多田たちが所属する写真部へとやってくる。写真部の部室では、部長の杉本一 (すぎもと･はじめ) が何やら熱弁をふるっていて…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7f86f08e-2348-4334-8aa6-5706f3d77954.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a454ebff-a1f4-462f-afb6-0160a393f111', '24ea115b-6950-4ae2-b85d-b98796c839fd', 3, '100018318', 'それ、好きだなあ', '多田家の飼い猫にして、多田珈琲店のマスコット。そして戦慄のニャンコビッグとしてブログでも活躍する人気者のニャンコビッグ。彼は子猫の頃、庭先で鳴いていたところを多田に拾われた。彼にとって多田は、命の恩人であり、多田の亡き両親にかわって見守るべき存在でもある。今日もいつもと同じように、まだ寝ている多田を起こすため、ニャンコビッグは行動を開始するのだが…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b26cab5e-d077-4e44-8de9-5a4a3b7698b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19eaaced-c16f-4a96-ab86-cec1049379c9', '24ea115b-6950-4ae2-b85d-b98796c839fd', 4, '100018569', '見なかったことにしよう……', '写真部部長の杉本一、通称･ピン先輩は、狂喜乱舞していた。彼がこよなく愛するグラビアアイドル･HINA (ひな) が出す1st写真集のお渡し会の抽選に、見事当選を果たしたからだ。今まで人前には一切出てこなかったHINA。彼女に直接会うことができる貴重なチャンスを得たが、いざ会うことを想像すると、緊張で体が震えて何も喋ることができないピン先輩。多田はとりあえず、会う練習をしてみたらと提案するのだが…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3160fd1b-3e2e-499f-a182-e4b659f065ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43b2c516-8459-4331-940a-9e8e82ffbe8c', '24ea115b-6950-4ae2-b85d-b98796c839fd', 5, '100018681', '大丈夫だ。いないから', '記念すべき『第10回 伊集院薫ショー』の日がやってきた。『伊集院薫ショー』とは、毎年、伊集院が様々なイベントを企画して、多田珈琲店で多田やゆいたちをもてなすお楽しみ会のようなものだ。彼が写真部に入部してからは、杉本と日向子も参加していた。今年は新たにテレサやアレク、山下も加わったので、更に張り切った伊集院は、特別な企画を用意していたのだが…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c01bb3d7-f606-4e33-9af7-7d74dd9716b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a5c6c72-4b22-4591-953a-e56c2de454f6', '24ea115b-6950-4ae2-b85d-b98796c839fd', 6, '100019104', '雨男、じゃないぞ', '大学の夏休みを利用して、テレサの幼馴染みのシャルルが日本にやって来た。シャルルはテレサの憧れる日本を見たいと言って、恋ノ星高校も訪問。対面した写真部メンバーたちは、最初は緊張していたが、シャルルはとても感じが良い人だったので、あっと言う間に打ち解ける。その翌日、多田は伊集院に誘われて参加したパーティーで、偶然、彼を見かける。その隣には、美しくドレスアップしたテレサとアレクもいて…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eafe5d69-3d74-4a14-86e8-82b9668dc11e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48a42fab-c293-45a7-9d8d-952202047718', '24ea115b-6950-4ae2-b85d-b98796c839fd', 7, '100019360', '泣かれるよりはいいだろ', 'ある日、ふらっと出かけたまま、姿を消してしまったニャンコビッグ。いつもであれば絶対に残すはずのないご飯に手をつけておらず、しかも子猫の頃から愛用している猫じゃらしも見当たらないため、何か大変なことが起こったのではないかと慌てるゆい。ニャンコビッグのことだからきっと大丈夫だと、心配するゆいを励ましつつ、多田たちはニャンコビッグを探しに行くのだが…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b6f221f-2d47-4e26-a4fd-b1575e39ae82.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4517bdea-b0aa-4bd0-b7e4-a44d634ed9b5', '24ea115b-6950-4ae2-b85d-b98796c839fd', 8, '100019690', '雨女だったっけ?', 'コンクールに応募する星の写真を撮るために、写真部メンバーは全員、シャルルが運転する車に乗って、泊まりがけの合宿へとやってきた。しかし残念ながら、空は少し曇っていた。星の写真は、深夜から明け方にかけて撮影するため、それまでに雲が晴れるようにと神社にお祈りに向かう。そこでおみくじを引いた多田たちは、書かれた運勢に一喜一憂しながら、恋の話で盛り上がるのだが…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2997070-1771-4b8e-99c3-dda79f72d3d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6236c900-30c0-463f-8cae-6666a790991b', '24ea115b-6950-4ae2-b85d-b98796c839fd', 9, '100020122', '今は、もう、ない……', '帰国するシャルルを、アレクと共に空港で見送ったテレサ。そこで改めてアレクに覚悟を問われて、言葉を続けることができなかった。その夜、テレサは日本への留学を決めたとき、乳母のレイチェルに言われた言葉を思い出す。あのときは考えもしなかったことに今は思い悩んでいた。しかし、何事もなかったように振る舞おうと心に決めて、翌日の新学期から努力するのだが…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0e1f9c9-fbb9-45c5-abdc-51e9597ae0af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7318778-5920-4180-8e49-64800164c4d8', '24ea115b-6950-4ae2-b85d-b98796c839fd', 10, '100020420', '本物、じゃないよな', '東京スターツリーの下で、れいん坊将軍40周年を記念して行われているイベント『れいん坊将軍展』にやってきた多田とテレサ。れいん坊将軍にちなんだ様々なアトラクションで遊び、楽しい時間を過ごす二人。せっかくだからと東京スターツリーに登ってみると、いつの間にか太陽は隠れ、雨が降っていた。雨を見ながら、多田はふと両親が事故にあった日のことをテレサに話し始める。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1c34323-6541-40ed-adcd-961f0a15a5a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9476c75c-9752-483e-b1e6-803155d834a2', '24ea115b-6950-4ae2-b85d-b98796c839fd', 11, '100020655', '特には何も', '多田たちに何も告げることなく、突如としてラルセンブルクへと帰国してしまったテレサとアレク。二人が暮らしていたグランドパレス銀座の部屋のチャイムを鳴らすが、応答はなく、電話をかけても通じない。何があったのかもわからないまま、連絡さえ取れなくなってしまったことに落ち込む多田たち。その後もテレサとアレクからの連絡はなく、気が付くと、季節は冬になっていた。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/837403f7-a896-477b-ab94-7171829aab47.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d39fcca2-8416-4331-8aa9-a908273e5e27', '24ea115b-6950-4ae2-b85d-b98796c839fd', 12, '100021078', '……突然、ごめん', '決死の覚悟で飛行機に乗り、どうにかラルセンブルクへとやってきた多田。精根尽き果てた体を休め、じっちゃんの知り合いだという人物の元へ向かう。クリスマスを目前に、美しく飾り付けされた街や、クリスマス市を抜けてたどり着いた場所は、立派なお城だった。だが、門は固く閉ざされていて、どこから入っていいのかわからない。あきらめずにまわりをうろうろしていると、後ろから声をかけられ…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/094483ea-ad0e-4699-9d40-32d86d74bf83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c74d7436-1cb8-4f4c-911a-ca767ef67eb1', '24ea115b-6950-4ae2-b85d-b98796c839fd', 13, '100021324', '俺も、一生、忘れない', '【シーズン1 最終話】テレサから打ち明けられた真実に、多田は打ちのめされる。全ては生まれてきた時から決まっていたことと言われると、伝えたいことを口にすることもできなかった。伊集院はそれでいいのかと詰め寄るが、多田は何を伝えればいいのかもわからなくなったと告げる。そして、ただ伝えたとしても迷惑なだけではないかと。そんな多田に、伊集院はこれまで胸のうちに秘めていた思いをぶつける。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90c06f22-7aa4-4e75-ab2e-b3c6eacd0653.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1ecc614f-2abd-4974-8735-7d4558abead1', '多聞くん今どっち！？', '', 'hulu', 'tamons-b-side', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94388b25-1da2-46ae-9642-9a1b13ba0c64.jpg?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'RELEASING', NULL, 178005, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9fa1a4e0-1918-4995-8a24-829f1ab19802', '1ecc614f-2abd-4974-8735-7d4558abead1', 'hulu-tamons-b-side-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c499632e-994a-4638-90d0-f7aca1764d7c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6eb56063-3f0e-4a16-ab0e-095d31dc3e7a', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 1, '100248933', '推しを推すには金が要る!', '高校生である木下うたげの生きがいは、唯一無二の推し――大人気アイドルF/ACEのセクシー&ワイルド担当･福原多聞! そんな推しに貢ぐため、家事代行のバイトで日々資金を稼ぎまくるうたげ。そんなある日、バイト先のチャイムを鳴らすと…そこにいたのは、まさかの推し本人! しかもその姿は、ステージの輝きゼロ!? ジメジメ全開、自己肯定感どん底の多聞くんだったーー! パーフェクトな推しの裏の顔を知り、うたげの推し活はまさかの方向に転がり出す!?「多聞くんは神! 全乙女の為に遣わされたもうた愛の使徒!」', '2026/01/04 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c499632e-994a-4638-90d0-f7aca1764d7c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9289c1a7-851d-4827-86ce-73a79c30a7e0', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 2, '100248934', '俺のこと好き?', 'F/ACEの握手会がついに開催決定! 推しの多聞と合法的に触れ合える接触イベントに、うたげの脳内は妄想フルスロットル! しかしその頃多聞は、慣れない握手会にジメジメ全開でメンタル大崩壊モードが発動。見かねたうたげが握手会に向けてイメトレに付き合うが、爆イケファンサに思わず爆散。そして迎えた握手会当日、うたげはファン同士のトラブルに巻き込まれてしまい…?「世界平和と書いてセクシー&ワイルドと読むんだよ」', '2026/01/11 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0435d29b-a7b8-4b20-93df-b7a7ad7f0aaa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b428a39-57d4-4704-8209-5a64e4957d4f', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 3, '100248935', 'テメェ、やべェファンだな', 'F/ACEのセクシー&ワイルド担当･多聞と、完璧王子･坂口桜利の仲良し動画に癒されていたうたげは、ひょんなことからF/ACEメンバーの衝撃的な姿を目撃する。さらに、F/ACEのセンター再選抜企画もスタート。夏休みに入ったうたげは、友達の莉子、結菜と共に、不動のセンター多聞の行く末を固唾を飲んで見守るが…?「多聞くんのいる場所が世界のセンターですよ」', '2026/01/18 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c043307f-3345-46a1-823e-af6442f295de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b09e0fc8-d3bb-46ff-a6b8-4889a4884117', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 4, '100248936', 'あなたは恋のスナイパー', '多聞の家での一件をきっかけに、桜利の挑発に乗ってしまったうたげ。センター争奪戦に勝つために自分に足りないものを探す多聞は、うたげを夏祭りに誘うことに。浴衣姿で現れたうたげと変装した多聞は、賑やかな祭りの中でぎこちなくも絆を深めていく。一方、桜利はその様子を陰から見守り、誤解と苛立ちを募らせる―― (?)「あなたは恋のキューピッド……いえ、  恋のスナイパーなんです!」', '2026/01/25 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85f7e49f-243d-45b6-b9d6-17f744ea2b14.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('195e5e03-4d8a-4442-8586-4e2d83d79aa4', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 5, '100248937', 'RAIN', 'F/ACEのセンターを賭けた戦いはますますヒートアップ! センターで新曲RAINを歌うのは一体誰? 多聞と桜利は正々堂々ライバルとして戦うことを改めて決意し、そんな2人の姿に胸を打たれるうたげ。ある日うたげのもとに思いもよらない人物から電話があり、唐突に看病イベントが発生――!?「多聞くんはわたしの心のセンター」', '2026/02/01 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78ef9c8a-0fe5-48fb-ae3b-27e73e67f0aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6721d491-bff7-474c-9da9-456f81dd164b', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 6, '100248938', '多聞くん今どっち!?', 'センター争奪戦を経て多聞の新たな一面に心打たれたうたげ。そんなある日、ポチの散歩中に導かれるように多聞の家へ――そして屋上で思い詰める多聞を全力で制止する事態に!? センターを逃した悔しさに揺れる多聞は、うたげに自分の秘めた弱さをぶつけてしまい―?「多聞くんが作ったケーキなら、粘土でもガトーショコラ!」', '2026/02/08 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a32a720-eff2-4146-8c12-e56c92583f7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12b446ab-35bb-44ac-9a79-4f123acdfe4f', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 7, '100248939', 'オタクとは恐ろしい生き物だ', '街を歩いていたうたげは、偶然多聞と遭遇し、一緒に休日を過ごすことになる。プライベートにも関わらず、うたげへ過剰なファンサを続ける多聞。そんな彼に”アイドル･福原多聞という存在の尊さ”を理解してもらいたい、と考えたうたげはとある行動に出る。そして、ハウスキーピングのバイトでいつものように多聞の家を訪れたうたげは、F/ACEのリーダー敬人に声をかけられて―?「多聞くんを軽く扱わないでください!」', '2026/02/15 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b884991f-501b-41ee-aec7-01efd83702a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7efc22a7-b59c-4732-93ae-b8bf51c52950', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 8, '100248940', 'F/ACEとナツ旅', 'マネージャー藤田の依頼により、スタッフとしてF/ACEの夏合宿ロケに参加することになったうたげ。賑やかな車内トークや白熱のビーチバレー対決が繰り広げられ、汗と笑顔で輝く多聞にうたげはいつもの様に心を奪われるが、その一方で桜利は複雑な感情を抱き始める。「この合宿の間、敬人くんにヤバオタ認定されないように努めなければ……!」', '2026/02/22 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7cda0a00-2ca8-4a8b-b79c-e7d23ad0fd67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('169fe431-3c23-4ce2-a4db-fec3cd0e7ecf', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 9, '100248941', '勝つのは俺だ', '夏休みの宿題が終わらないうたげは、ひょんなことから敬人の部屋で多聞、桜利と一緒に宿題を片づけることに。桜利はうたげを振り向かせようと躍起になるが、終始手ごたえがなく空回りしてしまう。そんな中、うたげからかけられた言葉で桜利は自分の恋心を自覚して――?「イケ原くんのムダ使いはダメって言ってるでしょう!?」', '2026/03/01 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6705e07a-bc29-4cba-ad7d-afd4f2fbb9fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f67096f3-54b7-4dd0-a325-161fde9c618c', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 10, '100248942', 'イエベ春', '夏休みが明けて、うたげのクラスに新しい担任･飛鳥先生がやってきた。実は彼女も熱心なF/ACEファンで、うたげと推し活仲間になる。放課後、うたげは偶然ドラッグストアでナツキと遭遇するが、その後作詞作曲作業中のナツキが行方不明になってしまい――?「耳がっ!! 耳がアアアアア!!」', '2026/03/08 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5626dfb-c06d-4d1d-b1be-88984df3c245.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('888b39e4-7969-495b-b206-dd5571b42783', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 11, '100248943', 'ここにいてええんかな', '破天荒な一面を見せるナツキは、酔った勢いで飛鳥先生との秘められた過去をうたげと多聞に明かす。孤独だった過去のナツキに、温かな手を差し伸べたのは飛鳥先生だった。だが、音楽への夢や家族の事情、ままならない現実に二人の未来は分かたれてしまったのだった。そんな中、うたげの学校の文化祭にF/ACEが収録でやって来ることが決まり…!?「鎮まれ……!『何か』……!!」', '2026/03/15 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffcac2d9-a2c3-45e7-be26-910a9fd66e49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ecd4467-ed01-480e-a08d-f5a237fa189f', '9fa1a4e0-1918-4995-8a24-829f1ab19802', 12, '100248944', 'FLY', 'ついに迎えた文化祭当日。クラスでたこ焼きの屋台を運営するうたげは「多聞くんが自分の学校に…!」と高鳴る胸を抑えきれない。そんな中、紙袋姿の多聞と、ゴリラの被り物を被った桜利に遭遇し、なぜか3人で文化祭を巡ることに。その裏では、飛鳥先生もナツキに、かつてのわだかまりを解きたいと胸に秘めていた。やがて校内放送でF/ACEの声が流れ始め、文化祭の熱気は最高潮に――!「守りたいこの空間。将来は大気になってこの一帯を循環したい」', '2026/03/22 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc581306-c873-4237-8aeb-122749597e4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7e54a194-841c-4422-b222-73488a4076fa', '太陽よりも眩しい星', '', 'hulu', 'a-star-brighter-than-the-sun', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31e3a12e-6f42-4317-89c4-2b1ef2b87db8.jpg?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 186621, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8643ec16-09ef-4bf7-a7d3-d6dd6482197e', '7e54a194-841c-4422-b222-73488a4076fa', 'hulu-a-star-brighter-than-the-sun-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c632ba9a-245e-49c7-a8ab-3d046bcf389e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c85e6861-b4f0-44ed-af6b-e09f9f3e31c3', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 1, '100240397', '手を伸ばした日', '平均より頑丈な女の子、岩田朔英。初恋の男の子･神城光輝は細くてか弱かったけれど、中学3年生となった今、誰が見てもかっこいい男の子に成長。人気者となった神城とは疎遠になり、朔英の恋は眺めるだけに。しかし、中学最後の体育祭で一緒になり、初恋はついに動き出して――?', '2025/10/10 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c632ba9a-245e-49c7-a8ab-3d046bcf389e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ede48bce-c390-4622-9c9b-eabfc20d049a', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 2, '100240843', '名前を呼んで', '同じ高校、同じクラスになった朔英と神城。入学早々のゴミ拾いで同じ班になるが、神城がクラスメイトと喧嘩!? 間に入ろうとした朔英を、思わず「朔英!」と名前で呼ぶ神城に、幼い頃の淡い記憶が溢れ出す。そんな中、翡翠も神城を気になっている様子で…?', '2025/10/17 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/950b1ad4-4e68-4077-a1a5-db8b38275ae6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac17025f-f5c1-4cf2-ad4a-fa694ed4d909', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 3, '100241385', 'どんなに遠くても', '「神城に好きな子がいる」その事実がどっしりと重しになって朔英にのしかかる。そんな中はじまった研修旅行でも、気が付けば神城ばかり目で追ってしまう朔英。翡翠と香川も朔英の恋を全力で応援しようと頑張るも、どうにも神城の前では残念な姿ばかり見られてしまって…….。', '2025/10/24 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4636117-4a96-4cd7-b9f6-688bfd8bcbb0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1263f76-d509-4da4-90ed-a4b17a15e630', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 4, '100242145', 'まぶた閉じてもそこに在る', '神城から直接「好きな子がいる」と告げられ、さらにその相手が「太陽超えて眩しい星みたいな人」だと聞いてしまった朔英。苦しい気持ちを抑えながらも、神城の恋を応援しようと決意するけれど、いつも通りに接する神城に、朔英は戸惑いを隠せなくて……。', '2025/10/31 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6612db8f-61f0-4e5f-bc3d-6d755d1cadeb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64e64498-18ff-469d-9453-5320e81fc744', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 5, '100242846', '跳ねて、揺らいで', '研修旅行が終わり、クラス対抗大繩大会が開催されることに。朔英と神城は縄回し係に任命され、朔英は想定外の出来事に神城を意識しないよう努力する。いざクラス練習が始まると、思うように練習が進まなく、そんな中朔英は放課後に校舎裏で自主練習をする香川を見つける。', '2025/11/07 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b489c2d-c7a4-4868-9405-4babac4795d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fbc25b0b-6f68-4f21-b71e-e5710c35e502', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 6, '100244159', '知恵と心と、それから勇気', 'ある日学校を休むことになった朔英。翌日、部活でケガをして休む神城。2人はお互いに休んだ分のノートを貸し合う中で、メッセージ交換をする。ある出来事をきっかけに神城に好きな人がいることがバレてしまった朔英だったが「がんばれ」と応援されてしまい、気持ちがすれ違う。', '2025/11/14 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1bfd0f1d-34ff-4196-a680-8757388846c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a38d102c-b61d-40c1-9729-beec5c12c95c', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 7, '100245035', '天気雨', '英語フェスティバルの主演に選ばれた神城。英語が苦手な神城は、朔英に練習を手伝ってもらうことに。練習の流れで、2人は夏休みに映画に行くと約束する。迎えた英フェス本番、クラスの発表が順調に進んでいた中、朔英が急にステージに飛び出してしまい、騒ぎに…!?', '2025/11/21 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/04a1ad1a-813f-4261-8052-ca05fa1fd042.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a3cdb76-0bc4-4b5c-940b-2b6af7d381f9', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 8, '100245803', '10年間', '行事もひと段落し、部活に励む朔英。そんな中、神城から連絡がきて、映画デートの日程が決定! その日を楽しみにしていた朔英だったが、ひょんなことから神城の従姉･昴と出会い、神城の好きな「太陽超えて眩しい星みたいな人」は昴かもしれないと不安を募らせる。', '2025/11/28 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2123408-930e-4873-8f1f-57bcd44bd8b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c662a123-9892-45b0-be37-4f7d9137d8f8', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 9, '100246436', '誰かの気持ち', '映画デートを経て、改めて想いを伝えなければ気づかれないと感じた朔英。翡翠から学祭が告白イベントだと聞き、後夜祭で神城に告白をすると決意する。学祭の準備を進める中、朔英は落書きされた昴の絵を発見する。朔英が落書きの犯人にみえる状況に、神城が現れ..!?', '2025/12/05 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01499360-fbc1-4d73-9e86-1a539a6696d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8ef1d31-13cf-4b08-b3fc-81a72bf40b7e', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 10, '100247083', '噂', 'クラス展示の準備が進む中、神城と距離を詰めようとするものの、なかなか話すタイミングが訪れない。そればかりか翡翠に鮎川とばかり行動していることを指摘されてしまう。朔英が神城ともっと話そうと決めたところ、神城から朔英にある提案をされて…!?', '2025/12/12 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e29759f2-8ba6-4c8a-8add-7ad108c7ceb2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac2ef897-c00a-408a-abfd-4e1849ddb81c', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 11, '100247902', '星座にならない星', '倒れた昴を心配し、保健室に様子を見に行く朔英。元気にふるまう昴を見て、神城は学祭当日昴の手伝いをすると言い出してしまう。告白を考えていただけに朔英は寂しく思うが、しかし朔英との受付係の時間だけは手伝いができないと神城は宣言。そしてついに学祭がはじまり――。', '2025/12/19 01:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05d16e80-3c3f-45d7-a75d-79a7f62c6e10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87462e3c-78e0-40b0-9ec4-70eb3b17b7e9', '8643ec16-09ef-4bf7-a7d3-d6dd6482197e', 12, '100248419', '太陽よりも眩しい星', '【シーズン1 最終話】神城が後夜祭で好きな人に告白をすると聞き、朔英は思わず「神城が好き」と告白をしてしまう。その場から逃げ出した朔英を神城は戸惑いながらも追う。フラれたと思いこんだ朔英は涙を流しながら、体育館倉庫に隠れていた。すると扉が開き、そこにいたのは神城で……。', '2025/12/26 01:00:00', 1410, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4956be86-5a8e-461e-bf63-66ac1fce33d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dd045dab-a993-4ec9-8774-322209e9cd59', '大正オトメ御伽話', '', 'hulu', 'taisho-otome-fairy-tale', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e4bfb99-ee24-46a1-b822-b076cc23dea2.png?w=331&h=447&p=t', 'hulu', 2021, 3, 1, 'FINISHED', NULL, 127412, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a0d04922-91bc-4ed4-b548-706f3843e710', '誰ソ彼ホテル', '', 'hulu', 'tasokare-hotel', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8cc1c4bc-3ff3-4ce2-b21c-09286116ff1e.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 178495, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f698dc62-8c97-4627-ba5d-d5a869afe14c', 'a0d04922-91bc-4ed4-b548-706f3843e710', 'hulu-tasokare-hotel-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0a5695b-984d-49c4-9687-d4fdb681d3ab.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4882d891-49de-43ee-82bd-62f844c89a4f', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 1, '100236158', '黄昏少女', '地平線の彼方まで夕暮れが続く荒野で目覚める主人公･塚原音子。見知らぬ場所で自分が何者なのか、どうしてここにいるのか想い出せない中、背後に「黄昏ホテル」が現れる。ホテルに入ると、頭が燃えている支配人に出迎えられる。自分が死んでいるのか、生きているのか定かではないことを知り、記憶を取り戻すきっかけを探す音子のもとに、不思議なお客様が現れる。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0a5695b-984d-49c4-9687-d4fdb681d3ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7643b6b0-640f-412c-81af-9eb798362595', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 2, '100236159', '人生の賭け', 'この世とあの世の狭間に存在する「黄昏ホテル」で働くことを決めた塚原音子。先輩である阿鳥遥斗の指導のもと、奇妙なホテル生活を始める。業務中、博打好きのパチンコ玉頭の宿泊客から、麻雀をしたいと依頼をうけることに。メンツをそろえて客室へ入ると、そこには様々なギャンブルの道具が散乱していた。部屋の片付けをしていると突然、部屋の黒電話が鳴り始めてーー', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/34173560-9697-41f1-bb65-c406d286c0c8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca93fd34-78ae-4c7a-b536-09b29a334c5d', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 3, '100236160', '血濡れの三色菫', '「黄昏ホテル」での仕事に慣れてきた塚原音子。従業員から認められるよう、来訪者の接客を志願する。チェックインしたお客様はパンジー頭の男で、どこか不気味な雰囲気を醸し出す。客室まで案内し、記憶を想い出す手助けをするべく、部屋の探索を始める。記憶にまつわる品を調べていくと、現世では医大生で、探偵業をしている大外聖生という人物であることがわかった。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb0fc612-c243-4b22-a911-6fa7a12bd835.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b7b1574-c5dd-4ca5-b57f-5046fe14209b', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 4, '100236161', '友情と責任', '「黄昏ホテル」に、生死が定かではないお客様が来訪する。塚原音子と阿鳥遥斗は客室担当として、頭部が剣道面の女と、スマホ頭の女をそれぞれ案内することに。部屋の家具や小物などを手がかりにし、現世では幼馴染であり同じ高校の剣道部であることが判明する。客室の変化とともに、現世の記憶を徐々に取り戻す彼女たちは、ホテルに辿り着いた因縁も想い出す――。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ae46709-c05c-40e8-9196-260c95ab8af7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62e453f3-4a7f-4aac-84fe-fe5ddcd6a7f2', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 5, '100236162', '海辺の灰かぶり姫', '音子とルリは、仲睦まじいカップルを客室へ案内する。部屋はオーシャンビューが広がり、その光景を目にした女性は、とある意思に気がつく。探索を続ける中でシンデレラの劇台本を発見し、馴れ初めと名前を想い出す。しかし、生死の行方は不明のままで…。大外と音子が2人の関係性の違和感について会話をしていると、突如女性の叫び声がホテルに響き渡るーー。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3eaa70c9-18f2-4a76-8716-819eb5c85379.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97a0ab04-632a-4350-9a62-6d587f828c8f', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 6, '100236163', '宇宙と音楽', '「黄昏ホテル」にロケット頭の少年と黒猫が迷い込む。黒猫と仲良くしたい少年は、館内や部屋の中を追いかけ回すも一向に捕まえられない。一方、黒猫は少年には一切触れさせないが離れず見守っている。そこに宿泊客のレコード頭の男が現れ、落ち込んでいる少年の遊び相手になることに。少年と戯れるレコード頭の男は、阿鳥が音楽の道を志した憧れのサックス奏者であった。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cd24944-f5f0-4a5e-a957-a0cd3405bc3a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81db0365-79f7-4cd6-8951-31dfb1c998d0', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 7, '100236164', '回転木馬と拳鍔', '自室から出てくるルリと出くわす音子。部屋の中を目の当たりにした音子は、現世で起きた事故を知ることに。そこにメリケンサック頭の女がホテルに来訪する。現世の記憶を取り戻すために、部屋の探索を促すも全く興味を示さない……女性の客室を調べてみると、片親で子供を育てていたことが判明する。ルリは境遇が似ていることから、女と自分の母親を照らし合わせる――', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5a71061-2a91-4d69-9838-ab01558d4e36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cabe67e1-a10f-4b55-8b0e-5de7814355a2', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 8, '100236165', '偶像の少女', '国民的アイドル･365シスターQ (通称：サンキュー) の金子このみが訪れる。音子は、憧れの存在を目の当たりにし胸をときめかせる。他の来客者と違い、金子の顔は異形化しておらず、自身の名前も記憶も覚えていた。食事中、突然食堂に置かれたラジオからサンキューの記者会見が流れ出し、金子の生死の行方を知ることに。音子は彼女の心残りであった願いを告げられる。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ee508b5-6aa3-48fd-9d3b-a0e1078db598.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59e6bca2-ac37-4776-bed4-edf7837684b0', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 9, '100236166', '少女の素顔', '金子このみの願いでもある、幻のソロ曲のライブに向けて演奏メンバー集めに奔走する音子。サックスを担当してもらうため阿鳥へライブ参加のアプローチを何度も試みるも、一向に首を縦に振らない。阿鳥は、過去の経験からどうしても演奏を拒む理由があって…。果たして無事にライブを開催し金子をあの世へ送ることができるのか? それぞれの想いが交差するーー。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b8c8b62a-d8e2-4a38-8b50-67b37f51eec6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb47e21d-ff79-4f49-912c-05f20629d4d8', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 10, '100236167', '隠し部屋', '金子このみのライブを無事成功させて、阿鳥と和解した音子。とあることをきっかけに、確信には迫らないものの、現世で起きた事件を不意に想い出す。そんな中、大外がルームサービスに不満を持っていると阿鳥から聞き、不服に感じた音子は単独で客室へ向かう。部屋の様子が以前とは変わっていたことに疑問を覚え探索を続けると、隠し部屋を発見して…。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72eeb4cc-ba41-4357-a378-c8881b5d472d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27372f54-545f-47b9-97f4-88a268404b7c', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 11, '100236168', '拳銃と地獄', '大外の隠し部屋から、新たに被害者が記された日記と、大量の現世の阿鳥の写真を見つけた音子。大外が「黄昏ホテル」で何かを企んでいることを確信する。切子から、支配人の部屋に特別な拳銃があることを教えてもらい、大外の計画に抗う覚悟を決める。阿鳥への執拗なストーキング行為、自分を刺した動機ーー音子は、大外へ現世の執着を問いただす。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92c1481b-9376-474b-9000-4a4d082f5d24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('982333ff-cd17-4064-b375-c4db9fcf8874', 'f698dc62-8c97-4627-ba5d-d5a869afe14c', 12, '100236169', 'リベンジ', '【シーズン1 最終話】交戦の末、拳銃で誤って大外を殺してしまったーー。阿鳥は、地獄の門から出てきた無数の手に連れ去られてしまう。拳銃を盗み、思わぬ悲劇を引き起こしてしまった音子は、支配人からクビを宣言され現世に戻ることに。今まで働いた給料を精算するにあたり、時間で支払われることを知った音子は、ルリから頼みごとを受ける…。時を遡り現世に戻った音子は、大外との最期のリベンジに挑む。', '2025/10/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b37d4ee-4906-40f0-91d6-46f7f780aa48.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1cc98d12-d31f-4d24-99a9-778f20952313', '嘆きの亡霊は引退したい ', '', 'hulu', 'let-this-grieving-soul-retire', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9589009e-a9e9-48f6-b596-40d24995d974.png?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 175019, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0e28f5cd-ee40-4fee-a33e-03b770f110ff', '1cc98d12-d31f-4d24-99a9-778f20952313', 'hulu-let-this-grieving-soul-retire-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7df62ecf-5600-4ad4-9ead-8af370248518.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74d38c1c-2825-4748-a98e-c62fcbdc197b', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 1, '100200628', '今日はこのまま帰りたい', '帝都最弱にして、屈指の高レベルハンター、クライ･アンドリヒ。自身がマスターを務めるクラン《始まりの足跡 (ファースト･ステップ)》の新規メンバー採用面接の会場に顔を出すクライだが、無責任な発言によって場は大騒動に……。後日、探索者協会から呼び出しを食らうクライは騒動の責任を取るため、比較的楽そうな依頼――とある宝物殿での遭難者救助を引き受ける。だがクライはとことん人任せ。その依頼をティノになすりつけるのだった!', '2024/10/03 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7df62ecf-5600-4ad4-9ead-8af370248518.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17481ae2-eff9-44db-9c86-79f90d969c03', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 2, '100200629', 'ティノに任せてラクしたい', '宝物殿【白狼の巣】での救助依頼。ティノ、ルーダ、ギルベルト、グレッグ様による、即席パーティが結成された。反発するギルベルトはクライに勝負を挑むも、差し向けられたティノに負け、さらに宝具を高度に扱うクライの姿に畏れ慄き、その実力を認めるに至る。無事に依頼をなすりつけ安心するクライ。しかし、どうやら最近【白狼の巣】が異変によって危険地帯と化していると知り、今更ながら自らの無茶振りに気づくことに……。', '2024/10/10 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8968b34a-1d3b-411b-af18-6033a1d5130a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9021e7ac-6c0f-49e8-a8ec-1ffcbc7109af', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 3, '100200630', 'まっすぐ空を飛んでみたい', '高レベルの幻影 (ファントム) に苦戦するティノ達。一同は強敵を相手に、チームワークを駆使してなんとか宝物殿を進んでいく……。そして迎えたボスファントム戦。死力を尽くし辛くも勝利を収めたものの、新たに4体のボスが出現した! 絶望的な状況に撤退を決めるティノ。だが決死の作戦も失敗に終わってしまう。死を覚悟した一同の前に現れたのは――クライ。レベル8ハンター、《千変万化》の実力が今ここに発揮される! ……のか?', '2024/10/17 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55c7a514-4715-44b4-bd9f-52e2ba47b477.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26d5463c-d300-4b28-9c6a-eac92b37d260', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 4, '100200631', '謎の仮面は戦闘したい', '出口なんて分かるはずもなく、適当に宝物殿の中を進むクライ。そんな中、すっかり忘れていた依頼にあった遭難ハンター達を偶然発見してしまう。話によると遭難者達は「怨念の化身」という凶悪な敵にやられたらしい。出会えば全滅必至。一刻も早く宝物殿を出ようとするクライ達だが、運悪く怨念の化身に遭遇してしまう! その禍々しいオーラに圧倒される一同。と、その時、もう一人謎の仮面をつけた人物が現れて……。', '2024/10/24 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7c3c94f-e0e7-4ee3-9c79-8dbf3dbdce45.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85f32c41-775d-40f8-9b39-ca2a7fd177fb', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 5, '100200632', '全部アークにまかせたい', 'リィズの活躍によって依頼を解決したクライだったが、今度は別の災難に見舞われていた。預かっていたシトリースライムがいなくなっていたのだ! それは帝都を滅ぼすほどの脅威。気が気じゃないクライだが……考えることをいったん放棄。面倒なことは全て他人に押し付けて、リィズと共にデートへと出かける。一方、今なお異変が続いている【白狼の巣】。その地下では、魔術結社『アカシャの塔』による巨大な陰謀が渦巻いていた。', '2024/10/31 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70b57fbc-e81b-431d-853d-026d0b20232e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45625fc7-5426-43ca-abd5-913087eb5682', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 6, '100200633', '指揮は取らずに寝ていたい', 'シトリースライムは一体どこへ? 助言を求めるべく、クライはそれを作った張本人、シトリーの帰還を待つことに。その頃、『アカシャの塔』はとある決断を下した。クライにアジトを特定されたと勘違いしたことで、ハンターとの全面抗争の道を選んだのだ。そんな事はつゆ知らず、協力を仰がれた【白狼の巣】への追加調査をアーク任せにしようとするクライだったが、その適当発言が曲解され、まさかのハンター大調査隊が結成されてしまった!', '2024/11/07 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f154d1bc-b43f-460f-8e7f-480879eeedd9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13e2ff08-0412-45e4-9cb1-0efed1f2d819', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 7, '100200634', 'アカシャの塔は実験したい', '待望のシトリーが帰還した。だがスライムの件はそこそこに、シトリーはクライに不吉な予言をする。このままでは調査隊は全滅する、と……。宝物殿に集結したハンター達はスヴェンを陣頭に、クライの《千の試練》に対して最大級の警戒心で臨んでいた。そんな中、『アカシャの塔』きっての俊英ソフィアによる、ハンター殲滅作戦が着々と実行に移されており――。ハンターvs『アカシャの塔』。総力を挙げた戦いの幕が切って落とされた!', '2024/11/14 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e3f76ed-a488-49a1-92db-929bd8ce9fa8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f80cbbdf-b018-41ab-9aa5-626218dc8ffc', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 8, '100200635', '終わった頃に駆けつけたい', 'シトリーの手腕によって、ピンチを脱したハンター達。焦った『アカシャの塔』の構成員達はソフィアの命令を無視してしまい、あえなく自滅する。さらにシトリーは敵の本陣を難なく特定。ハンター達は一気に攻勢に出ようとするも――。突然、アカシャ屈指の魔導師フリックによる一撃必殺の雷撃魔法が一同を襲う。形勢は逆転しハンター達は全滅してしまった。かに思えたが……。クライもようやく動き出し、戦いはいよいよ最終局面へ。', '2024/11/21 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cdbadedb-ce1c-40b4-a95a-2b9a0fcea5e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('913e6171-7b7f-4460-8bec-da6ea5efd688', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 9, '100200636', '愛と平和を伝えたい', '敵の本陣へ乗り込むハンター達。だが狂暴なキメラに巨大ゴーレム、迫りくる難敵に手こずり一進一退の攻防へ。そんな命を賭けた激しい戦いは、クライの到着により急転直下の結末を迎える……。後日、ノト･コクレア率いる『アカシャの塔』の面々は、無念の敗走からの再起を誓うと、ハンター側に潜入していたソフィアと合流する。だがソフィアの様子はいつもとまるで異なっていた。戸惑う一同の前に現れたのは――「あの人物」だった。', '2024/11/28 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3e0817a-4271-49f4-a716-1c4f5ce265fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5abcc5e-208f-485c-893b-62d088ea4b8b', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 10, '100200637', '帝都でぶいぶい言わせたい', 'レベル7ハンターにして竜殺しの英雄、アーノルド･ヘイル。野心溢れる彼のパーティ《霧の雷竜 (フォーリン･ミスト) 》が、鳴り物入りで帝都へやって来た。だがクライはその存在に興味すら持たず、今日も今日とて、マナ切れを起こした宝具へのチャージを巡ってひと騒動を巻き起こしてしまう……。その後酒場でリィズ、シトリー、ティノと共に宴を楽しむクライだったが――。突如アーノルド達が現れ、場の空気が一変する事態に。', '2024/12/05 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a5e50459-eed7-4988-a435-cc5ccc1ddd82.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e6e1f07-32f9-4f7a-9fb3-d2a24f78dc20', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 11, '100200638', '霧の雷竜は復讐したい', '帝都で名を上げるはずが醜態をさらす羽目になった《霧の雷竜》。憎しみ募るアーノルドは汚名返上するべく、レベル8のクライを狙うことに。その頃、シトリーへの多額の借金に頭を悩ませていたクライ。気分転換にティノと一緒に出掛けるが、運悪く《霧の雷竜》と遭遇してしまう。クライは体よくティノを差し向けるも、アーノルドには全く太刀打ちできない。足蹴にされるティノを見かねて、ついにクライが決闘の場へ進み出る……。', '2024/12/12 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81ba14a3-a759-4068-a115-fedeb4cd4bc7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a198970f-d31c-4009-a600-0c59f4a493ce', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 12, '100200639', '出来ることなら入手したい', '訪れた宝具店で、鑑定依頼品の山の中にとびきりの逸品を発見したクライ。どうしても手に入れたくなり、直接その宝具の持ち主と売買交渉をすることにしたのだが……。持ち主はなんとアーノルドだった! クライの稚拙な交渉術が逆に高度な罠に見えたアーノルドは、その裏をかき宝具を売り渡そうとする。だが、横槍が入り交渉は破談。宝具はオークションに出されることになり、さらにその品を巡ってクライは貴族のエクレール嬢と争うことに。', '2024/12/19 23:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d569ca3-f6fb-4a81-aad4-521de9469c10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45a8a1f6-d906-4a50-946a-4646c455db2a', '0e28f5cd-ee40-4fee-a33e-03b770f110ff', 13, '100200640', '何が何でも落札したい', '【シーズン1 最終話】ついに始まったオークション。目当ての宝具ただ一つを落札するべく巨額の借金を重ねたクライだったが、壇上に上がる宝具の数々に目を奪われ気持ちがかき乱される。クライの理性と我慢が限界を迎える中、会場に運び込まれたのは――シトリーが欲しがっていたアカシャゴーレム。シトリーの想いを汲んだクライは狙っていた宝具を諦め、ゴーレム落札のために全てを投げうち大勝負に出る。様々な思いが交錯するオークション。その結末やいかに?', '2024/12/26 23:30:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4342878a-f271-45c7-92ac-f9e35ef754c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6360bdd1-fdd6-4943-bedc-951869f1b137', '1cc98d12-d31f-4d24-99a9-778f20952313', 'hulu-let-this-grieving-soul-retire-s2', '第2クール', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a310636-494f-4817-adcd-e56b4a150a7f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1dbc269f-ec64-4f8d-882a-0b68d1213332', '6360bdd1-fdd6-4943-bedc-951869f1b137', 14, '100239741', '思い出話を語りたい', '「まさに神でした……」うっとり陶酔し、クライとの出会いを語るティノ。かつてハンターになる前の少女時代、帝都に来て間もない頃の《嘆きの亡霊 (ストレンジ･グリーフ) 》に助けられた思い出話。当時の事はまったく記憶にないクライだったが、あちこち話して回るティノに同行する中で、次第に何があったのか思い出していき……。これはストグリ、そしてクライに対するティノ･シェイドの憧憬。その始まりの物語である。', '2025/10/09 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a310636-494f-4817-adcd-e56b4a150a7f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10607039-17eb-4dda-aa8a-883c3f77d372', '6360bdd1-fdd6-4943-bedc-951869f1b137', 15, '100239742', 'こうなりゃどこかに旅立ちたい', '先日のオークションでクライと宝具を巡り争ったグラディス家から、クライへの指名依頼が届く。全くやる気のないクライだが探索者協会のノルマを達成しないと強制的に除名になるため、依頼を受けざるを得なくなる。更には《魔杖 (ヒドゥン･カース) 》からの打診、《霧の雷竜 (フォーリン･ミスト) 》からの因縁、そして『白剣の集い』への招待……。次々と舞い込むあらゆる面倒事から逃げる為、クライはバカンスへと向かうのだった。', '2025/10/16 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa97ed36-7c98-48d7-b88a-406a3135b257.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0eccd294-4e67-4e53-9bf4-53f1fd6d169b', '6360bdd1-fdd6-4943-bedc-951869f1b137', 16, '100239743', '街の平和はまかせたい', '楽しいバカンスのため温泉を目指して進むクライたち一行。道中を平穏に過ごしたいクライは、リィズにしごかれるティノを見かね「訓練禁止」を言い渡す。バカンス中は戦闘を一切しないこと。そう決めたクライに従うリィズ達は、ゆく先々で起こる大事件をスルーしていく。街を襲う雷精、街道に出現するオークの大群に火精――クライ達に端を発するその全ての厄災は、後を追いかけるアーノルド達に降りかかるのであった。', '2025/10/23 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60b9112a-690a-4bfe-833b-88bf59178832.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f66b238-c89b-42e7-8be7-97e0a608e52e', '6360bdd1-fdd6-4943-bedc-951869f1b137', 17, '100239744', '強い魔物はパスしたい', '追ってくるアーノルド達から逃れるため、魔物がはびこるガレスト山脈を突っ切るクライ達。そんな危険地帯で遭遇したのは、残忍な魔物『迷い巨鬼 (ポテ･ドラゴス) 』。早々に撤退を決めたクライは、ポテ･ドラゴスの執拗な追跡から何とか逃げきることに成功する。到着した湖のほとりで骨休めのキャンプを楽しんでいたクライ達だったが、そこへ現れたのは怒り狂ったアーノルド! しかし、いつもと様子が違っていて……?', '2025/10/30 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ecff2e9c-5359-4645-a136-b4d8ef8362eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26dcecf6-b085-49ed-bf88-10067703d828', '6360bdd1-fdd6-4943-bedc-951869f1b137', 18, '100239745', 'のんびり温泉浸かりたい', '念願の温泉街に到着したクライ達。温泉を堪能するクライが遭遇したのは、のんびりと湯に浸かっているドラゴンだった! 一方、【万魔の城 (ナイトパレス) 】を命からがら脱出してきたアーノルド達も街に到着。《千変万化》の実力を身をもって知った彼らはクライと和解を果たすも、アーノルドは何やら一人で思い悩んでいる様子……。その頃、街では不穏な影がちらつき始めており、クライは謎の亜人に連れ去られてしまう。', '2025/11/06 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95c8fe1d-6f4a-47c0-b306-0178bdeef415.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f1b149b-2d0f-40ab-9390-eeec90638a43', '6360bdd1-fdd6-4943-bedc-951869f1b137', 19, '100239746', 'どうにかこうにか切り抜けたい', 'バレル盗賊団によって街は制圧され、リィズ達は捕まってしまった。いまだ姿を見せないクライをあぶり出すため人質に手をかけようとするバレル一味。だが突然、地底人 (アンダーマン) の襲撃を受ける。無数のアンダーマン達を率いていたのは、なんとクライ! さらにドラゴンまで現れて場は混沌と化す。次々と起こる予測不能の事態に戸惑うバレル盗賊団。そんな彼らの前に現れる笑う骸骨の仮面を被った3人組――。', '2025/11/13 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac108679-0b33-4fd5-9588-40f2750e3dd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77068fee-bcdf-4583-bb73-999354c53ce7', '6360bdd1-fdd6-4943-bedc-951869f1b137', 20, '100239747', 'あちこちお土産渡したい', 'バカンスを謳歌し、3週間ぶりに帝都へ帰還したクライ。終わっていたはずの『白剣の集い』は帝都で起こった抗争のため延期されていた。渋々参加するクライの目の前で、狐面の暗殺者によって皇帝が狙われるという事件が発生。皇帝暗殺を目論むのは巨大犯罪組織『九尾の影狐 (ナインテイル･シャドウフォックス) 』。組織の全貌も全てが謎に包まれた敵から皇帝を守るため、クライに護衛依頼が打診される。', '2025/11/20 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51d865bd-9f9a-41a3-9a4e-3f14c87bcb99.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a029ac06-acdb-4049-b2be-819a04b143f4', '6360bdd1-fdd6-4943-bedc-951869f1b137', 21, '100239748', '護衛の旅は遠慮したい', '宝具に目がくらみ引き受けた皇帝の護衛依頼。仕方なくメンバー集めに動くクライは、相変わらずノリと勢いで決めていく。テルム、ケチャチャッカ、クリュス、キルナイト･バージョンアルファ、そしてクライ。ここにドリームチームが結成された! 厳戒態勢の中、外遊へと向かう皇帝一行。クリュスと近衛団長フランツに怒られながらも緊張感皆無で護衛に参加するクライ。そうして何事もなく初日を終えたかに思えたが……。', '2025/11/27 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6359be3b-4b1d-4756-ac5b-b31bcca8fcd1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('249f81ed-e450-438a-9588-45c79e51f7ed', '6360bdd1-fdd6-4943-bedc-951869f1b137', 22, '100239749', '九尾の狐は暗躍したい', '皇帝の一行に紛れ込んでいた『九尾の影狐』の構成員によるドラゴンの襲撃。駆けつけたアンセム、そしてテルムの活躍によって事なきを得るも、度重なる襲撃に内通者がいると判断した皇帝は、クライを自身のそばで護衛させることに。一方、クライに不信感を抱いていたテルムはとある結論に達した。クライが『狐』の構成員であると……。狐を巡る勘違い。そのことがクライ、テルム、ケチャにとって思いもよらぬ事態を招く。', '2025/12/04 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b6be5a0-1ffa-4cd9-abc1-ad1512ee5bde.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('568962a8-57b5-49fc-9e68-1c198cb82143', '6360bdd1-fdd6-4943-bedc-951869f1b137', 23, '100239750', '仲間の補佐に感謝したい', 'いよいよ旅は終盤へ。空路で目的地に向かうと聞き、準備のために旅程の延期を申し出るクライ。その動向を逐一うかがっていたストグリのメンバーも、クライのサポートに奔走する。ようやくすべての準備が整い満を持して飛行船に乗り込むクライだったが、次第に雲行きが怪しくなっていき……。そんな中、突如として皇帝の命が狙われる事態に。暗躍していた『九尾の影狐』が本性を現す。', '2025/12/11 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1dd5ab6-bd34-4538-b788-6f78759af96f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81b138d7-0615-47fc-bf23-a2cdfe21e6b5', '6360bdd1-fdd6-4943-bedc-951869f1b137', 24, '100239751', '最後はにっこり笑いたい', '【第2クール 最終話】『九尾の影狐』の襲撃から無事に皇帝を守ったクライだったが、さらなる災難が降りかかる。なんと飛行船ごとレベル10の宝物殿【迷い宿】に入り込んでしまったのだ。狐のファントムとの生死をかけたやり取り。それを切り抜けたクライは、全員無事に解放してもらうため宝物殿のボスである母狐に会いに行くことに。相手は人間をはるかに超越する神。そんな母狐を前に、クライがとった行動とは――。', '2025/12/18 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c845240f-b7ca-4204-a42e-63e2ad0a7218.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('fe9b54dc-0e75-41d0-9861-5b1818c9614f', '男女の友情は成立する？（いや、 しないっ!!）', '', 'hulu', 'danjo-no-yujo-wa-seiritsu-suru-iya-shinai', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47ba072c-f031-4482-958f-a421bc4bd633.jpg?w=331&h=447&p=t', 'hulu', 2025, 1, 1, 'FINISHED', NULL, 153554, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 'fe9b54dc-0e75-41d0-9861-5b1818c9614f', 'hulu-danjo-no-yujo-wa-seiritsu-suru-iya-shinai-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caa53ab5-62ca-44af-bf75-d8ec93c75288.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4771135-25df-4a5e-9ca0-c202af0dee6f', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 1, '100223481', 'ニリンソウと月下美人', '中二の秋、文化祭でフラワーアクセサリーを販売する夏目悠宇。売り上げが上がらない中、目の前に現れた美少女･犬塚日葵のおかげで完売する。日葵は悠宇のアクセを作るその瞳に惚れ込んだのだと言う。『しんゆう (運命共同体) 』になろうと言い出す日葵に、戸惑いながらも受け入れる悠宇。そして二年の月日が流れ――。', '2025/04/09 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caa53ab5-62ca-44af-bf75-d8ec93c75288.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d43685f0-e1d1-45e2-af50-294db322e28a', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 2, '100224082', 'ハイビスカスの髪飾り', '凛音にブレスレットを作ったのが悠宇だと知られ、動揺する日葵。一方の悠宇は、姉の咲良から作品の停滞を指摘され思い悩む。顧客目線での恋愛感情について日葵に相談すると、「やってみる? アタシとお試しキス」と突然、悠宇に迫る日葵。いつもと様子が違う日葵に、ついドギマギする悠宇。二人の顔が近づいていき――。', '2025/04/16 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b37d20a3-fedb-4017-b37f-3dd308f13e29.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0996205e-7932-4f3b-a8fa-0dcbbb6e27b3', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 3, '100224897', 'チューリップと恋の表情', '初恋の相手が凛音だったことを知って驚く悠宇。学校へ行くと、悠宇を避ける日葵の態度にも振り回されることに。一方で凛音のモデル計画は進んでいき、日葵、悠宇、凛音の微妙な空気感が露わになる。科学室で悠宇と二人っきりになると、日葵は突然「恋のアクセ、作るんでしょ? アタシで経験しとこ?」と言い始めて――。', '2025/04/23 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e85068dc-bcf3-4749-aece-c526a3e64aec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b095eb0-16d7-4fa3-bcdb-ec380bfa9270', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 4, '100225630', '紫陽花と新しい種', 'アクセサリー･モデルの件で喧嘩し、絶交中の悠宇と日葵。「親友も喧嘩くらいするさ」と高をくくる悠宇だが、突然日葵は「東京に行ってモデルになる」と言い出す。親友と言いながら相談もなく勝手に決めた事に怒る悠宇、弾みで日葵のチョーカーを壊してしまう。泣きながら去って行く日葵。二人の亀裂は決定的に――。', '2025/04/30 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f45670e-1f52-4d57-b619-da5e001e4dc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ea616b1-129c-4a3e-941b-b14a4702b3e3', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 5, '100226602', 'イケメンと朝顔の浴衣', 'それぞれの恋心に気づきながら新たな『しんゆう (運命共同体)』を続けることになった悠宇と日葵。悠宇はアクセ作りに没頭するあまり、試験の答案をほぼ白紙で提出したため担任に呼ばれ、追試で合格ラインを超えなければ留年か退学だと告げられる。青ざめる悠宇と日葵。追試対策のため悠宇は日葵の家に泊まることに――。', '2025/05/07 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f8f9083-e9d9-4ff2-9461-0d5a4e6c4019.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7850d9dc-0ca8-4431-90a6-1417054a19b0', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 6, '100226909', 'チェリーセージの香り', '悠宇が日葵の家に泊まったことを知った凛音。自分も一緒に泊まると言い出す。困り果てる悠宇に友人の真木島は「好きにしたらよい」と突き放す。結局は悠宇の家で勉強を教えることになる凛音、実は学年二位の優等生だった。部屋で二人っきりになり鉢植えのチェリーセージの香りを嗅いだ凛音は、悠宇も驚く大胆な行動に出る。', '2025/05/14 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6842156b-7dff-41be-bda1-ba990c9707b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('638ee3be-eaac-47a1-aa5c-76e4a7b64bbd', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 7, '100227689', 'ひび割れたクロッカス', '追試も無事に終わり衣替えの夏。日葵、凛音、それぞれのまぶしい夏服に悶絶する悠宇。三人でのyouの活動を本格化させようと科学室で相談していると、日葵の友人･茉央と亜寿美がやってくる。二人は悠宇にオーダーメイドのアクセサリーを注文し出来映えに大満足。「あたしらが宣伝隊長になる!」と宣伝を始め――。', '2025/05/21 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c843c4c5-fdb9-49bd-9366-051534821266.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('83f4c0e6-92c8-4fa0-9942-942bb5763a03', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 8, '100228109', 'ジニアと情熱のありか', 'クレームを受け学校から呼び出しを受ける咲良。返品対応に応じれば、サイトで販売するのは咎めないという寛大なものだった。落ち込む悠宇を慰めようと、日葵はアクセを作り続けるようにと発破をかける。だが悠宇に日葵の情熱を受け入れる余裕はない。「悠宇の気持ちはよーくわかった!」 怒った日葵はある決意をし――。', '2025/05/28 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f0ca5bf-f27a-41cf-9a8a-744590e2d377.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5603c09c-4fc0-4c5b-948b-3374b273e119', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 9, '100228660', '恋のチョコレートコスモス', '日差しが眩しく夏休みも間近。悠宇、日葵、凛音の関係にも微妙な変化が訪れる。なぜか日葵は悠宇から避けられているのだった。原因がわからない日葵は真木島に疑いをかけるが、会話の中で凛音の姉でモデルの紅葉が帰ってきていることを知る。一方の紅葉は、同級生である咲良を巻き込み悠宇にある商談を持ちかけて――。', '2025/06/04 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/468d162b-8330-47d6-925a-14ce96d72cd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c635536d-0187-4420-ae3e-3e344a8b663b', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 10, '100229317', 'ヒマワリの花言葉', '日葵の負債と引き換えに紅葉から本気のアクセサリーを作るように言われた翌日。夏休みに入り、日葵、凛音と一緒に課題である「夏の思い出」を探しに出かける悠宇。ワッフルを食べたり海で遊んだりと高校生らしい時間を過ごすが、アイデアは一向に湧いてこない。道ですれ違う小学生達を見て、悠宇は何かを思いついて――。', '2025/06/11 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7743b0e-740b-40ce-97c4-ba779b4f7ede.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78fc2107-a6c8-40a7-baf9-88b4ca08176f', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 11, '100229812', 'さよならヒマワリ', 'ヒマワリ畑での日葵とのキスが頭から離れない悠宇。突然、なぜ日葵があんな行動を取ったのかわからず、一人で花に話しかける。一方の日葵も、とっさに自分がしてしまった事にぐるぐると後悔の念にとらわれる。二人きりの科学室。気まずい空気に「俺は昨日のこと、なかったことにしないんで」と悠宇は日葵に告げて――。', '2025/06/18 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c42f46a9-895a-4612-8f7a-14e3e4183e1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f4166215-1f41-40d0-86b3-1994dae95c11', '0ef8fd84-94d4-45ba-8bfd-f8e75c768f18', 12, '100230843', '夢の道に咲く花たち', '【シーズン1 最終話】紅葉との勝負に敗れた悠宇。と同時に日葵の東京行きが確定する。出発の準備を進める日葵。自分の無力さを痛感し、日葵が帰ってこない未来への不安を拭えない悠宇。一方、二人の様子を見ていた凛音は、紅葉と真木島との関係を突いてある提案を持ちかける。仕方なく受け入れた真木島は、悠宇のいる花壇へと向かい――。', '2025/06/25 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/acfaad96-541c-48d9-9a79-24d1cc24c5ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('127dec14-a055-4303-b90c-65ce64bd1810', '地獄楽', '', 'hulu', 'hells-paradise', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f9b2f07-5cce-477c-8606-14c0453e0f83.jpg?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 128893, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3699699c-d7ad-4e43-ae16-24ead0796ee0', '127dec14-a055-4303-b90c-65ce64bd1810', 'hulu-hells-paradise-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1740fffb-4d0f-4d67-8aae-d2821dfbf2a2.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da9c79d7-abc8-48fd-a96f-879619e2cae9', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 1, '100210193', '【死罪人と執行人】', '処刑執行人『御様御用』の山田浅ェ門佐切は、刑場で一人の死罪人と出会う。超人的な肉体を持ち、大勢の人を殺めた冷血な忍『がらんの画眉丸』。画眉丸は佐切に言う、「殺してほしい」と――。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1740fffb-4d0f-4d67-8aae-d2821dfbf2a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df454e92-6ccd-447e-add9-83f88b590c8f', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 2, '100210194', '【選別と選択】', '不老不死の仙薬を手に入れる為、幕府に集められた画眉丸と死罪人たち。彼らを待ち受けていたのは選別という名の――殺し合い。血風舞う戦場で、佐切は画眉丸が、真に斬るべき悪人か、見極めようとする。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32d9907d-552e-4ca1-be75-7b751fe8403b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f666d6c8-ba52-4b6d-abf7-39bc5331775d', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 3, '100210195', '【弱さと強さ】', '不老不死の仙薬が眠るとされる島『神仙郷』の地を踏む画眉丸と佐切。人面蝶が舞い、美しい花に満ちた不気味な景色が二人を迎える。仙薬を探す画眉丸たちの前に立ちはだかったのは――目的を同じとする筈の死罪人であった。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79a6bbce-cd87-4e1e-8c14-96e53e58686e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4af744f0-cd50-45e7-8965-95ecf0037069', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 4, '100210196', '【地獄と極楽】', '神仙郷は、異形の化物どもが潜む地獄の釜の底であった。見た事もない醜悪な生物に、恐怖と謎が画眉丸と佐切を襲う。窮地の中、死罪人の杠が二人に手を差し伸べる。それは慈悲か、それとも――。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73e5f90f-26fe-4b20-96d4-e8c45167ea5a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57dbc7fa-457b-4fca-b19b-d0c8711a069e', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 5, '100210197', '【侍と女】', '毒に倒れた佐切を待っていたのは、兄弟子の源嗣からの「女は帰れ」という言葉。侍と女――相反する生き方に苦悩する佐切。その頃、浅ェ門の典坐は死罪人ヌルガイと共に島から脱出すべく船を出すが――。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fce67a0-bca7-4636-a1e7-40e6ffd5f24e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('733f3cf9-759d-4dda-bc01-91031c9f5f46', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 6, '100210198', '【心と理 (ことわり)】', '『備前の大巨人 (だいだらぼっち) ･陸郎太』と闘う画眉丸と佐切。生と死の狭間で、佐切は己が進むべき道を見出そうとする。討つべき敵を前に、佐切の刀と画眉丸の技――二つが重なる。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e179963-ab5c-4f17-9e6b-63502bae74d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62ab6fcc-037e-4bc0-a37d-a923130bc983', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 7, '100210199', '【花と贄】', '謎の少女メイと木人に連れられ、村に案内される画眉丸と佐切たち。木人は語る、島を統べる仙人――『天仙様』の存在を。天仙の人を超えた力の前に、弔兵衛と桐馬は倒れ、深き穴へと落ちていく。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b66f61e-654d-4be8-b733-3cf48d6efc99.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cec971bf-0334-46f5-85cc-7efb2442aefc', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 8, '100210200', '【弟子と師】', '「クズ」と呼ばれていた。そんなガキに侍の誇りを与えてくれた先生がいた。そして、心の底から守りたいと思う人ができた。だから、自分は――典坐は刀を振るい続ける。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1257b5a-dfcc-4799-b4f0-cf98b4b55524.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9fd8af4e-fe2c-47ca-849d-62533ac07393', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 9, '100210201', '【神と人】', '妻と会う――その想いが画眉丸を島の中心へと向かわせる。佐切たちを村に置き、たった一人の身で。辿り着いたのは、巨大な人工の建築物。その門の前で、画眉丸は天仙と出逢ってしまう。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f31a13a3-e926-46c6-8de0-956f864ba8ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea5b1ed1-d4a0-4103-8709-8ac055758ce8', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 10, '100210202', '【陰と陽】', 'メイの助けによって窮地を脱した画眉丸は、巌鉄斎と付知と共闘の約を交わす。天仙を討つ術 (すべ) を探す一行に、メイは天仙の力の源――『氣 (タオ)』を教える。その氣を操る異形の道士が、画眉丸たちに襲い掛かる。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84e97005-e7f8-4f30-b591-bd8b497c4059.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5dae4c13-250b-4498-bc7c-0cecf668a3ef', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 11, '100210203', '【弱イと強イ】', '道士との戦いで瀕死の傷を負った弔兵衛は、人ならざる再生力と共に氣 (タオ) に目覚める。画眉丸もまた、道士との死闘の中で氣を体得しようと試みる。その中、道士はメイを見て突如ひざまずく、「天仙様」と――。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c56f5aca-408a-4eb6-98fd-7d9cb0fa799c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16328389-1f87-4537-8e32-5af7f74160cd', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 12, '100210204', '【傘と墨】', '画眉丸を探す佐切たちは、天仙の城『蓬莱』へと足を踏み入れる。そこに待ち受けていたのは、天仙『牡丹 (ムーダン)』。人を実験動物として扱う狂気の笑みが、杠へと向かう。その杠を守るべく――仙汰が立つ。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63bd9c21-37c7-4e62-94b5-0d65f96d41f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc8cd4b1-d580-405a-8f9a-b70d786905e7', '3699699c-d7ad-4e43-ae16-24ead0796ee0', 13, '100210205', '【夢と現 (うつつ)】', '【シーズン1 最終話】全ては亡き弟弟子の無念に悔いるため――士遠は己が命を懸け、怒りの刃を牡丹 (ムーダン) へ振るう。大切な者たちが倒れる中、佐切は皆で共に帰れることを願う。だが、その想いを裏切るように、画眉丸にはある異変が起きていた。', '2025/01/17 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6b3f7c1-e089-4c2d-a73e-ee2f37fd46ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5c854332-937f-4b48-8fdc-f23c31141429', '地獄少女', '', 'hulu', 'hell-girl', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50002394_series_art__338x600_hell_girl_fe49e774189d0cdd1d00d78b0246bb36.jpg?w=331&h=447&p=t', 'hulu', 2005, 3, 1, 'FINISHED', NULL, 228, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', '5c854332-937f-4b48-8fdc-f23c31141429', 'hulu-hell-girl-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2ce3e8a2-f037-448e-80ee-c10ec2fa39e9.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09accaaa-5f58-4d6e-8b71-cddf5b5b961f', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 1, '60808241', '夕闇の彼方より', 'クラスの募金を失くしてしまった真由美。クラスメイトの亜矢が助けてくれてその場は難を逃れたが、この日から亜矢と真由美の辛い主従関係が始まった。追い詰められた真由美は「地獄通信」の噂を耳にする。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2ce3e8a2-f037-448e-80ee-c10ec2fa39e9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a19823c-212f-42a5-8119-30515f090036', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 2, '60808242', '魅入られた少女', '涼子はひどいストーカー行為を受けていた。警察も捜査を続けるが、どうしても捕まえる事ができない。次第にエスカレートしていく嫌がらせに涼子はついに地獄通信にアクセスしてしまう。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4bf89fc4-6c85-44c9-a379-4517474fb0bb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19256c22-5d2c-440f-93e2-6ea0fb86a67b', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 3, '60808253', '汚れたマウンド', '野球部のスター選手･花笠から影のシゴキにあう部員たち。ある日、岩下はシゴキにあった室井を家に送ったが、ケガがもとで命を落としてしまう。岩下は花笠の暴力を訴えるが、逆に犯人と疑われてしまう。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3c9879e8-ea6a-42c4-a61c-b17ebfbf1b76.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46344d4f-6d23-49c2-98f6-69efc756192c', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 4, '60808245', '聞こえぬ叫び声', '純子のたった一人の家族である、犬のキャンディが死んでしまった。その死は有名獣医師･本篠のいいかげんな治療が災いしていたのだ。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7b978b8b-b8d1-4e39-af52-f53d7e5538f1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b61fd0d-c0d6-4f11-9376-16d498345cdf', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 5, '60808233', '高い塔の女', '急成長するベンチャー会社「デッドライン」。カリスマ社長･里穂は美沙里に地獄通信へのアクセスを強要していた。美沙里は里穂に弱みを握られていたのだ。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7f7b4d43-a7cd-4f0d-a25b-67bef5af580c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cac8d7f-988e-4547-b59b-d38496a56cea', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 6, '60808249', '昼下がりの窓', '社宅に越して来たばかりの遥たち一家は、ある日を境に家族ぐるみで嫌がらせを受けるようになる。ある日、起こった事件とは…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ee857bc1-1b7e-488b-af4c-d2672c92dfc5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13f9b52c-a729-4bcf-8aa7-d658941e267e', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 7, '60808252', 'ひびわれた仮面', '養母から厳しい演技の稽古をつけられる彩香。あまりの過酷さに地獄通信へアクセスしてしまう。しかしそんな彼女には、ウラの顔があったのだ。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7ebbbe53-d3c3-4b4d-b6e5-c8574284923e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6130c9bf-759e-4ee0-a7c0-755c63b89e4b', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 8, '60808256', '静寂の交わり', '昏睡状態の祐子。親友の千恵は地獄通信にアクセスした。祐子のかたきを取るために…。地獄少女が動くが、そんな彼女の気配を察する者が現れる。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0b8acf38-739b-4aee-9f79-96b64d2e0a3a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20e23657-b7b9-41a3-ad28-692bb25c0fed', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 9, '60808237', '甘い罠', '由香と弘美は念願のケーキ屋をオープンしようとしていた。彼女らの店を自分の番組で紹介すると、有名パティシエの森崎は言ってくれたのだが…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ee67709e-3e56-4da5-8748-95151ee313c5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ce7157c-f697-4b48-8e8c-a579b1d0bf87', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 10, '60808250', 'トモダチ', '仲の良かったみなみと詩織。しかし、みなみの独占欲の強さに嫌気がさした詩織は、急に態度を変える。裏切られたみなみは、腹いせに地獄通信にアクセスする。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8c0e9543-6458-41b4-ad5d-2fa5ce55c189.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47f7cc3c-fe75-46f8-8db5-125cd9a5cde9', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 11, '60808236', 'ちぎれた糸', '雑誌の偽造告発がきっかけで父親が逮捕され、家族の生活は地に転げ落ちた。全てを失った息子･雅哉はその怨みを晴らすため、地獄少女から黒いわら人形を受け取る。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/12c30954-2eb2-4ead-bb80-83374b2777a7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('918be3c4-6e8a-4f1b-9742-19f5634cdd9e', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 12, '60808257', '零れたカケラ達', '学校に行く事ができない茜。担任は毎日呼びに来るが、それがさらに彼女の重荷となっている。彼女の心許せる唯一の友達は、メール友達のcheppoだけだった。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b15f1750-9d70-4fe7-9856-7b39bd23d76e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db0af0d2-5f7f-4a5e-8650-fdc3d7a782af', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 13, '60808235', '煉獄少女', '古本屋「江黒堂」で柴田が手にした古い一冊の本、そこには地獄通信の話そっくりの「煉獄少女」という小説が掲載されていた。柴田は作者である福本という男を探し当てる。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3a5f6edc-7247-4c7e-aea3-da0f395857d1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff50410a-bace-485d-aacd-7e6fbfd8d3ff', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 14, '60808246', '袋小路の向こう', 'つぐみの頭の中に浮かんだ脈絡のない映像は、地獄少女の事件と関わっているに違いない。柴田はその核心を探るため、父親を亡くしたある少女に近づく。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/784b66ee-1e5a-4eaa-9268-b5e0c0089129.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d23add74-cac9-4a5a-b405-503ff0747972', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 15, '60808254', '島の女', 'つぐみの頭に浮かんだ映像をたよりに、島にたどり着いた柴田とつぐみ。柴田たちが目指した旅館には、少女･三奈がいた。彼女は許されざる恋をしていたのだが…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/464c6f40-4438-46ce-90b2-6244e382214b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1126e036-1a6d-4dc4-b9cd-cfc7e420a4dd', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 16, '60808239', '旅芸人の夜', 'つぐみたちがやって来たのは、小さなサーカス団。ここにいる少女が地獄通信にアクセスしたと確信していたのだが、実際、少女に会ってみると、全く身に覚えがないと言うのだ。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ee85c937-6a98-41d3-b6d4-d528cbe0e330.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8995e9bc-b752-4966-ae55-f6b1dc5ff71d', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 17, '60808232', '硝子ノ風景', '車を走らす柴田たちだが、霧のせいで立ち往生してしまう。そこにはサナトリウムが建っていた。入院中の少女･ニナはつぐみの来訪を喜びもてなすが、つぐみたちはその雰囲気に不審なものを感じていた。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/939a285b-5592-408f-9bd4-07cadfea06fd.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2716ca89-eb13-439c-a8ad-dc0f9680ccc9', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 18, '60808244', '縛られた少女', '芽衣子をかいがいしく世話をする美紀。周囲は気がつかないが、それは芽衣子に弱みを握られてしまった故の奉仕だった。美紀は次第に追い詰められていく。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6c861281-0fcb-4c68-a55f-8681b5d189b8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a749b8bf-f90c-4645-8324-14c096be29db', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 19, '60808243', '花嫁人形', '美しい少女･祈里が嫁いだのは、人形作りで有名な名家。夫の母で偉大な人形師である鏡月との暮らしは、祈里の人間性を無視した悲惨なものだった。息苦しさに耐えられなくなった祈里は、地獄通信にアクセスしてしまう。', '2025/12/26 00:00:00', 1503, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8dcfb026-a2d7-413e-b278-e837fdbe33a0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('193c1568-c820-432b-9d25-fc7b77af13ad', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 20, '60808251', '地獄少女 対 地獄少年', '番組のサイキック能力対決で敗れた超能力タレントは、負けた相手である少年･ジルを倒してもらうため、地獄通信にアクセスしてしまう。', '2025/12/26 00:00:00', 1503, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7f1b315b-e951-4335-8b51-04c65a2372a8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eccea774-8744-4e1c-86d2-f003400cd502', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 21, '60808238', '優しい隣人', 'つぐみは知り合いの少女･優子が地獄少女と会っている場面を見てしまう。それを止めるために柴田と共に優子の家に出向くが、豊かであったはずの優子の家の畑が荒れ果てており…。', '2025/12/26 00:00:00', 1503, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3cbb668c-62e8-4e34-852e-2c314e524b6b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('982b03ab-2124-4726-9458-0bc470ad9492', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 22, '60808248', '悔恨の雨', '今日はつぐみの母･あゆみの命日だ。つぐみは墓参りに行こうともしない柴田に腹を立て、祖父たちと出かけるが、そこで地獄少女の次のターゲットを知ってしまう。', '2025/12/26 00:00:00', 1503, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/508c0a36-f4df-4b9b-9f69-7ddf06256a79.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54a85259-ea8c-48ed-9dbd-d28b34d75156', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 23, '60808247', '病棟の光', 'つぐみが見た次のターゲット、それは病院の看護婦だった。しかし誰が、どんな理由で? 調べれば調べていく程、彼女は問題があるどころか、非常に善良な人だった。', '2025/12/26 00:00:00', 1503, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/aa02c516-c6bb-4cab-a57a-fbda59dd35ed.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75ba40ad-7b40-416f-9131-e18e51ebcfd3', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 24, '60808255', '夕暮れの里', '柴田とつぐみが向かった先に現れたあい。ついに地獄少女と彼らの因縁が明らかになる時がやって来た。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/00b6554e-7e9c-4304-9f9c-5c3a346ae41e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('379c121d-3ff2-47ce-b8c5-ec0e74583941', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 25, '60808240', '地獄少女', '柴田たちとあいの因縁は深く、あいが地獄少女になった事件に強く関わっていた。それは非常に辛く、そして哀しい物語だった…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/26032bfd-5713-4b75-ac1b-5e842c679faa.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e189ce18-765e-40c0-8cfa-df3262a58c3a', 'bccb3012-61fd-4fdc-9c95-9ac81a1a91ce', 26, '60808234', 'かりぬい', '【シーズン1 最終話】つぐみの手に渡された黒いわら人形。そのターゲットは…父親である柴田だ。つぐみは、柴田は、そして地獄少女は? 復讐の物語に、ついに一つの終止符が打たれる。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/12ffa5a5-0a0f-425b-a79b-65936cb11473.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a9eafeca-e463-4132-9aba-12a8ffbfd3b4', '地獄少女 三鼎', '', 'hulu', 'hell-girl-three-vessels', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2ceb190-5a0c-453c-bf6f-ff81709915e4.jpg?w=331&h=447&p=t', 'hulu', 2008, 3, 1, 'FINISHED', NULL, 3713, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('403ca49a-32d5-487d-b5d2-78b601b1b764', 'a9eafeca-e463-4132-9aba-12a8ffbfd3b4', 'hulu-hell-girl-three-vessels-s1', 'シーズン3', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76ad895e-11d7-4114-9368-6b6d5bc6ec02.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10bc4cd6-7d08-4d85-b73d-9e2f25a28b9f', '403ca49a-32d5-487d-b5d2-78b601b1b764', 1, '100004426', '奪われた少女', '逸子は嫌味で陰険な数学教師の丹下が気に入らない。強引にゆずきに協力を頼み、丹下を学校から追い出すための作戦に出るが…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76ad895e-11d7-4114-9368-6b6d5bc6ec02.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f2e219e-32fe-4493-92c3-99e9a676ff43', '403ca49a-32d5-487d-b5d2-78b601b1b764', 2, '100004427', '籠ノ鳥', '中学2年生の明は「山岡電気」にいる美津子に恋心を抱いていた。そんな明は熱心にその店に通うが、ある時、美津子と彼女の夫の秘密を目撃してしまう。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7451dc7-3424-49ec-b918-fd6f7e4d3909.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba286b50-fc7f-4926-9095-593d1e015e38', '403ca49a-32d5-487d-b5d2-78b601b1b764', 3, '100004428', '腐った果実', 'アイドル歌手の森山ジュンを、危ないファンから助けたゆずきと秋恵。お礼にと招待された食事へ向かう途中、百田昌子と名乗る人物からジュンに渡してほしいという封筒を受け取り…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc09defa-f54e-4754-8d41-7d7aced066e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('363858ca-df43-4096-9b2a-8f91813e72a7', '403ca49a-32d5-487d-b5d2-78b601b1b764', 4, '100004429', '兄貴', '仁志田という青年に助けられた、いじめられっ子の湯川猛は、彼の勧めで始めた剣道でいじめから脱却した。尊敬の眼差しで仁志田を慕う猛だが…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/841a8fc2-b7a1-4960-9745-6e57f4c1e623.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f832f48-d583-442b-ae63-125fa0541ff5', '403ca49a-32d5-487d-b5d2-78b601b1b764', 5, '100004430', 'うつせみ', '身に覚えのないことで、生徒である利々香の祖母からクレームを受けた、教師の新山。事情を聞こうと利々香と話し合いをするが、クレームはエスカレートして行くばかりで…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a0cd667-8333-41b2-b9a8-106e05e1bbeb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc757caf-d25a-4b89-9321-da3127670c99', '403ca49a-32d5-487d-b5d2-78b601b1b764', 6, '100004431', 'わたしのセンセイ', '体育の合同授業、創作ダンスに励む女子生徒たちを指導する曽根アンナ先生。彼女たちから慕われている骨女だが、ある女生徒が思わぬ行動を起こし…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b02b0c0e-ac08-4397-b353-47c4a6429603.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('997ef68b-60be-4f0c-b822-ace7cdf85764', '403ca49a-32d5-487d-b5d2-78b601b1b764', 7, '100004432', 'うそつき', '東京から転校してきた犬尾は、同じクラスの鷲巣と意気投合し、学校での行動を共にしていた。しかし、家庭の事情で放課後の誘いをいつも断る犬尾。それを心配した鷲巣は、詳しい事情を聞こうとするが…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ae18b97-40e6-400b-8fea-23c5ef9a0ffb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e53b39c-4af3-4dcd-8a89-03e9924c35e3', '403ca49a-32d5-487d-b5d2-78b601b1b764', 8, '100004433', '隣', '何不自由なく暮らす主婦、みおいの生活は愛犬モモを中心に動いていた。そんなみおいに、ストレスを感じ始める人物がいた…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d02d70d-cb52-49a9-b19e-f19b818cb4db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a051773-df79-42c1-b0e3-b566a1a6a849', '403ca49a-32d5-487d-b5d2-78b601b1b764', 9, '100004434', 'はぐれ稲荷', '自分に“稲荷のゴンさん”が憑いていると信じている楓。クラスメイトからは、からかわれていたが、ある事件をきっかけに楓の能力が本当だと噂が流れて…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01046fca-0692-4d9b-b81d-407f2aa51e94.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a394a21-b704-4b54-9215-ef436f1b3653', '403ca49a-32d5-487d-b5d2-78b601b1b764', 10, '100004435', '鏡の中の金魚', '毎朝、新聞配達のアルバイトをする和也。マラソン大会のトレーニングと言うが、実はたくさんの服を買う母親を、少しでも支えたいという気持ちからの行為だった…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3688cac5-02a7-4bd6-8f08-c648df6045cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b502a5d8-f342-4411-b9ba-2710645fe2d1', '403ca49a-32d5-487d-b5d2-78b601b1b764', 11, '100004436', '滲んだ頁', '小説をなぞらえた連続殺人事件が起きた。編集者の浅羽は真相を確かめるべく、作者の上坂と接触するが、犯人逮捕の情報が舞い込んできて…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d7fd4e9-5dfe-4003-bb34-0a78086ab119.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('740e05d0-1684-40a7-94ff-2e28950ba6b6', '403ca49a-32d5-487d-b5d2-78b601b1b764', 12, '100004437', '真夏のグラフ', '漫画家を目指す信夫は、夏休みの間プールでアルバイトをしていた。内気な性格の彼は、日々溜まる鬱憤をグラフにしていた。そのグラフとは…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9c36c69-57f5-468b-bba2-8a8b6dc4e2b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea3b1f4a-f6b5-45e9-9be9-121e5710bff4', '403ca49a-32d5-487d-b5d2-78b601b1b764', 13, '100004438', '六文燈籠', '地獄に一番近い場所と言われている賽河原市で、毎年行われる“六文燈籠”。その日、ゆずきと秋恵に運命的な出来事が起こる…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3050271-d14b-42cf-a0b8-927ba137cff6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc50f18a-f0d9-4732-90c9-f538fa69ff81', '403ca49a-32d5-487d-b5d2-78b601b1b764', 14, '100004439', '怨みの街角', '都会に出てきた秀美は、終電に乗り損ねてしまい行き場をなくしていた。途方に暮れる秀美だったが、一人の青年が彼女に手を差し伸べて…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/546ea2d2-2ec7-4b6e-b32f-7d197d40b1fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cdaf9b22-c26d-4b0b-919a-1efe74cfe419', '403ca49a-32d5-487d-b5d2-78b601b1b764', 15, '100004440', '兎と亀', 'のんびり屋のうさぎは、何をするにもテンポが遅く、いつも周囲の手を焼かせてばかり。そんなうさぎに、なんと彼氏ができて…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e07411bb-cded-425f-871b-7b0ae12141b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0c99461-42c0-43fe-bc37-738a10dc526d', '403ca49a-32d5-487d-b5d2-78b601b1b764', 16, '100004441', '誘惑の罠', '名和は加世を助けるために藁人形を手にした。それを知ったゆずきは、彼を止めようとするが、突如あいが現れる…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11ae0f4a-78e1-4d9d-b7c1-2f274b2dffcd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('161f9dab-a6f7-42cc-83c9-a764948ee2e8', '403ca49a-32d5-487d-b5d2-78b601b1b764', 17, '100004442', '藁の中', 'ある人物からの依頼を聞いた山童は藁人形になることを自ら志願した。その人物と山童の間には、哀しい過去があった…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1576bbc5-c60c-4e0d-ab0d-e46c680cda75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('484613e9-5212-4095-8f0f-a111ea620d87', '403ca49a-32d5-487d-b5d2-78b601b1b764', 18, '100004443', 'スペシャルレディオ', 'DJ丈太郎のラジオ番組に夢中になっている知里子。ある日“ハガキ職人のちーちゃん”が知里子だということがクラス中に広まり、注目の的となるが…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e5d3819-faed-4d0d-a776-7831470e47f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cec00ea-e2cc-431d-b0ab-9441882dda9c', '403ca49a-32d5-487d-b5d2-78b601b1b764', 19, '100004444', '雪月花', '自分の人生は自分で決めると華道の家元を出た花緒里は、フラワーアレンジメントで名を馳せていた。しかし、父親の死をきっかけに抗えない本能を知ってしまう…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe2f6e33-e406-429f-aedc-87e4fbd7aca1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25420dc5-d795-46bf-817b-6bb51cd51575', '403ca49a-32d5-487d-b5d2-78b601b1b764', 20, '100004445', '地獄博士 対 地獄少女', '溝呂木は自ら見出した“溝呂木定数”である答えを導き出した。そして、彼の“地獄邸”に集まったゆずきとあいたち…。一体何が行われようとしているのか。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1b171ec-003a-4481-b6bf-59cf543c4dbd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fd9ec46-5387-4e7f-9469-877909dfe98a', '403ca49a-32d5-487d-b5d2-78b601b1b764', 21, '100004446', 'うしろの正面', '海斗に新しいお母さんができた。彼女はとても優しく、海斗は幸せだった、彼女の身に変化が訪れるまでは…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4c429d2-9452-4d09-8f40-2a44237b3f04.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ae64448-153d-4633-9dee-b8d1457fbf11', '403ca49a-32d5-487d-b5d2-78b601b1b764', 22, '100004447', '華と月', '高校受験も差し迫ったある日、ゆずきは同じ中学校出身の女子大生、純香に出会う。彼女には双子の妹がいるというのだが…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d726f91-2b97-430a-a668-10d641ea7561.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bacd263-99fc-4186-bcb7-c4349d614cc2', '403ca49a-32d5-487d-b5d2-78b601b1b764', 23, '100004448', '日暮れ坂', '勉強に集中するため、怨みの鈴音を無視し続けるゆずき。その止まない鈴音は同じクラスの文男から鳴り響いていた…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9aaa3c2-0406-484e-8139-018afdeb5ecf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d798aa93-bc2d-4e61-b49c-364b1b77c290', '403ca49a-32d5-487d-b5d2-78b601b1b764', 24, '100004449', '蜉蝣', '合格発表当日に起こった、奇妙な出来事の数々。違和感を感じ始めるゆずきに、信じがたい事実が告げられる…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6b09b5f-7d11-4ed2-bc2c-6f6671a09baa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('384386cc-d291-4a5e-b762-03bf50ae7528', '403ca49a-32d5-487d-b5d2-78b601b1b764', 25, '100004450', 'ゆずき', '混乱するゆずきの前に現れた、あいと四藁たち。そして明かされる、幼いゆずきと両親の哀しい記憶…。', '2025/12/26 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a4ea57b-abd5-4598-a5b6-0b81be007700.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c85e03f5-edbf-4b45-ae37-548c3fa98fa6', '403ca49a-32d5-487d-b5d2-78b601b1b764', 26, '100004451', '魂の軌跡', '【三鼎 最終話】もはや、ゆずきを止めることは出来ないのか…。あいとゆずきの物語、ついに感動の終幕。', '2025/12/26 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63caddd7-bc06-48b9-842d-6306c246aaa7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dd644eae-677a-4d48-bd65-a7989bf4f141', '地獄少女宵伽', '', 'hulu', 'hell-girl-fourth-twilight', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f004c391-a9a5-49d6-a209-79a99bbd1214.jpg?w=331&h=447&p=t', 'hulu', 2017, 2, 1, 'FINISHED', NULL, 98379, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f5508767-ad4d-495c-9422-645f08fac403', 'dd644eae-677a-4d48-bd65-a7989bf4f141', 'hulu-hell-girl-fourth-twilight-s1', 'シーズン4', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a73ae748-920e-4d6d-8618-67f5319cf958.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8261864-26df-4056-a032-bf7738a40694', 'f5508767-ad4d-495c-9422-645f08fac403', 1, '100004328', '見えない聞こえない', 'クラスのグループチャットでいじめを受けていた真山静香。人との関わりを避けているクラスメイトの湯川麻子から友達になろうと声を掛けられ、秘密のグループチャットの中で憂さを晴らしていたが、ある日その内容がクラスの皆に知られてしまい…。', '2025/12/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a73ae748-920e-4d6d-8618-67f5319cf958.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f035fdc1-5bc4-4302-aa1a-d422b37b937c', 'f5508767-ad4d-495c-9422-645f08fac403', 2, '100004558', 'あなたしかいない', 'お笑い芸人･混沌スイーツのナナコとハル。二人の人気は日増しにあがり、ネタを書く時間もないほど多忙を極める。ボケとツッコミの関係を地で生きている二人に見えたが、秘密があった。過去に結ばれた二人だけの約束とは…。', '2025/12/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cb01d70-4d55-446a-9e5d-105f9ded6819.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('238e3b58-bfa7-4bb3-af3f-86539336dfe7', 'f5508767-ad4d-495c-9422-645f08fac403', 3, '100004804', 'いつか誰かが…', '性格に問題がある祖母と両親、姉を持つ末っ子の兄妹。ある夜、亜希良は母が片手に藁人形を握る姿を目撃し、その翌日から祖母の姿が見えなくなる。そして従兄の義則が家に居候することになり妹の亜里奈に悲劇が起きる…。', '2025/12/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ebf3ef7-de76-4aa3-a033-9fae7f0b7b80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccd4440d-9cc4-4524-87a6-88b27de48aa1', 'f5508767-ad4d-495c-9422-645f08fac403', 4, '100005076', 'わたしを深く埋めて', '老人ホームに入所している坪田さくら。手厚いサービスを売りにしているこのホームだが、実態は従業員たちが老人たちに虐待を加える悪質ホームだった。ヘルパーとして勤務する柴田つぐみはその事実を訴えようとするが…。', '2025/12/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69b61dc9-0642-400d-b5c1-d45172a29eb7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51958312-b113-416a-a105-da1eaf458a7d', 'f5508767-ad4d-495c-9422-645f08fac403', 5, '100005725', '風の歌が聞こえる', '風間理史が友達を連れて両親の運転する車で出掛けたある日、事故を起こし友達三人だけが犠牲になってしまう。生き残ってしまった理史は自分を責めるが、亡くなった友達の母親は地獄通信にアクセスし理史を地獄に流してもらおうとする。しかし、事故の原因を知るミチルは…。', '2025/12/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/376e0cad-d1e2-4bed-901f-39b98e53ca26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0062fb0c-fe61-4f97-91a3-ebbe135de6c8', 'f5508767-ad4d-495c-9422-645f08fac403', 6, '100006138', 'あやおり', '食品会社に勤める藍原唯。恋人の哲哉からプロポーズされるが、素直に喜べない事情があった。それは数年前、中華料理店を営んでいた父が出前の途中で酔っ払いに絡まれ、意識不明の重体で入院生活が続いていたのだ。そして唯が捜していた事件のカギを握るタトゥがある人物が…。', '2025/12/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07980684-f2cb-4aef-891c-0024a9e48d07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5221d538-8bfc-4568-b6cb-c3ac7026af67', '地獄少女 二籠', '', 'hulu', 'hell-girl-two-mirrors', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73ae13d8-02ed-4aec-ae19-598fd3a62037.jpg?w=331&h=447&p=t', 'hulu', 2006, 3, 1, 'FINISHED', NULL, 1594, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('37d6b5ad-633e-4452-b2e3-bc8909ca9f84', '5221d538-8bfc-4568-b6cb-c3ac7026af67', 'hulu-hell-girl-two-mirrors-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9268201-affd-4f69-8231-86d62d03db0e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35f71594-3a51-402c-8a4f-982e8b641910', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 1, '100004398', '闇の中の少女', '首謀者がわからないクラスでのいじめ。悩んだ麻紀に手を差し伸べたのは教師の瑛子だけだった。しかし、その犯人は…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9268201-affd-4f69-8231-86d62d03db0e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03cd1081-6d55-48c4-a684-771c66ed3c27', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 2, '100004399', 'うたかた', '行方不明になってしまった妹を探すため、毎日チラシ配りを続ける一家。姉の弥生はずっと、不思議な幻聴を聞き続けていた。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52aa5ff7-3b54-487c-ae8b-5ccd8d9d7743.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('516d9afc-f213-4a2e-8ae3-674d3cf1b18f', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 3, '100004400', '愛しのけいちゃん', '隣に住んでいるけいちゃんは、多恵にとっては大好きだけど触れてはならない神聖な存在だ。しかしそのけいちゃんには弓枝というガールフレンドがいて…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/873365ff-f2aa-4b42-b6a1-f93101903ded.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfe8c0d5-44d8-425e-be26-788bedcd4343', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 4, '100004401', '秘密', '修一は女房の病気を治すために精一杯働いている。しかし医療費はふくらみ、徐々に修一を追い詰めていた。そんな修一がホストクラブを訪れる。その真意は…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d2b5d17-947d-436d-9fb4-fa233fbd2493.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0490deb-db99-478e-ba6b-5a499286018b', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 5, '100004402', '地獄への暴走', 'ホレた少女･泉が兄貴分の力也に取られるとわかった麗音。地獄少女との契約もヨユーで済ませ、ハッピーエンドを迎えるはずが…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/646eedb2-9026-4dae-b8c9-1090beea3b01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37960fb7-fab9-424a-9044-cc0c87615fc4', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 6, '100004403', '陽のあたる場所', '颯太が心に秘めているクラスメイトの少女･紀和子。声をかける事もできずにこっそり写真を撮るのが精一杯だ。そんな彼女を撮影するために行ったボーリング場で、颯太はとんでもない事を聞いてしまう。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/846588f7-f5b2-4641-bc1d-57aade3509bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42452916-64d2-4ba9-87ca-1af69580742b', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 7, '100004404', '絆', '息子が交通事故で死んだのは、行政の対応が悪かったのが原因だ…。そう思い込んだ母親の和子は告発の運動にのめり込んでいく。恵美はそんな母を支えるが…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24659b35-758c-478a-b3c0-2eafef055473.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7788c31d-def1-4b1f-ba0a-3446a31fae65', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 8, '100004405', '偽地獄通信', '生徒たちの嫌われ者･馬場翔子は今日も厳しく生徒たちを指導している。その厳しさを怨んだ郁恵は、地獄通信にアクセスし、馬場先生の名前を書き込むがそれは嘘の地獄通信だった。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c46ebc26-bc9b-4014-a118-f7e7a95829d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8430ce71-cb0f-4a32-aed9-a6db26bb1840', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 9, '100004406', 'あにいもうと', '真帆は好きになった人と付き合った途端、別れられてしまいいつも一人ぼっち。美形の兄、幹夫はいつも優しく慰めてくれたが、真帆は愛憎入り乱れる複雑な感情を持ち続けていた…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7abe4a7e-c575-4a6e-b1ab-02038e325f65.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('283d0cd7-6e5a-48dd-a563-7229a3302452', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 10, '100004407', '曽根アンナの濡れた休日', '骨女が出会った男･哲郎は映画監督志望の全くもってダメな男だ。しかしなぜか骨女は男の事が気にかかる。それは他の女たちも同じだ。彼に振り回された女たちが次第に集まって来る。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bb3b7d7-8ffc-4505-89c1-57808004dd59.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2c986c6-ef05-417f-8b0c-2115f871a4b1', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 11, '100004408', '遠い隣室', '引っ越して来た志津子は誰かから嫌がらせを受けている。彼女はいつも不在で引越しの挨拶ができていなかったお隣が犯人ではないかと思い悩むが…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f148b6bd-bed0-45a0-bf2b-a30aca31bc7c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32f2c7df-3e28-4951-b158-8246dca7678d', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 12, '100004409', '黒の轍', '輪入道がヒッチハイクで乗り込んだトラック。運転手の道郎はこれから向かう先に大きな怨みを持っていた。そこは立ち退きを拒否した老人の住まいがあるのだが…。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ebdfbbf-9b9e-4a46-9136-db4537580c52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2faaaf85-7703-44de-8918-5f0197eedfc8', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 13, '100004410', 'Vの惨劇', '小さな町で起こった連続殺人事件。被害者には全く接点が見つからないが、なぜか死体の片手にはVサインが…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebfd98da-42fa-4372-a0b6-84805834f949.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('206a9253-1cbf-4da9-8624-46052f890f27', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 14, '100004411', '静かな湖畔', 'かつてのトレンディ新興住宅地･ラブリーヒルズは今や不景気と価格下落で見る影もない。そこに戻って来た紅林一家だがある日、息子･拓真が悪魔の子だという中傷ビラが投げ込まれる。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85e07076-7f77-4c9e-8cea-2865790053a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0d1b621-0e27-4d53-ace4-b4c0111c7fa0', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 15, '100004412', 'この国のために', '仕事が来ないのも、生活が苦しいのも、みんな今の政治が悪いんだ! 大泉政権を倒すべく、選挙にのめり込む菅野親子。だがその影には汗して働く母親の姿があった。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71153ed9-82be-47ab-bda6-7d3b8f2feaf3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ced68af7-f31f-4c45-af18-0741273845dd', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 16, '100004413', '悪女志願', '悪い男にだまされた心優しい蘭は、意を決してわら人形の糸を解こうとするが、強気な女･マツの力を得て、男へ復讐する作戦を開始する。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a7f0bf7-5f42-4873-8b0a-661aaacc660a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93779a9d-c52b-4d55-83b3-f2b8689cc1b2', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 17, '100004414', '沈黙のまなざし', '地獄少女と契約した寧々。ターゲットは自分の母親だ。しかし母親はかつてあいと契約し、わら人形の糸を引いた依頼者でもあったのだ。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60dff441-17f1-4134-b1a0-6b8b61bb2687.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cedcbf4f-eeb3-4955-8cac-674caa9d6e3d', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 18, '100004415', 'あのひとの記録', 'ついに結婚を決めた里奈は、将来に夢をふくらませていた。そこへ一本の電話が入る。それはかつて家を出て行った母が戻って来るという知らせだった。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/057c84ed-2411-409f-a073-f48fb77ca90a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1dbb1ac2-912c-4931-88a3-db8cbfc54aba', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 19, '100004416', '湯けむり地獄、旅の宿', '輪入道が訪れた温泉旅館。すっかり新しくなった旅館だが、ここは輪入道にも思い出のある場所だ。その出来事とは…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c8383bae-059e-42cc-92e4-04900f72b86c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85f89f96-a482-40ba-8840-598bc14192a8', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 20, '100004417', '乙女のアルバム', 'いつも仲良しの樹里と真里。学校でもプライベートでもいつも一緒だ。しかしこの二人を繋いでいるのは、わら人形の赤い糸なのだ。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8005e01f-1f79-4014-8508-b55eb97d009a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf891c6b-3691-4cea-a28d-cb6c68d17fc6', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 21, '100004418', '紙風船ふわり', '捨てられる女･洋子はわら人形を隠し持ち、男に必死にすがりついている。その様子を見ているのは骨女だ。彼女の胸に去来する時代を超えた切ない想い…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03978475-cfc2-4d8d-b0da-45ebce7e9d33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e48f9873-b91d-4d59-8255-6273ab214f58', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 22, '100004419', '憧憬', '母が死に、父が重症となった拓真に、両親殺害の嫌疑がかけられる。近隣住民からは疎まれ、孤独を感じている拓真。そこに謎めいた少女･せりが現れる。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e86307e6-5d66-46a9-8528-f9d4c90c0344.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b63145b5-2f2e-4f1e-937c-30db0eb4ebab', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 23, '100004420', '不信', '周囲から拓真への疑惑は日に増していき、街は重苦しい雰囲気に包まれている。そんな事件に刑事の捜査が始まるが…。', '2025/12/26 00:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cff9e589-d7fb-4aac-8caa-067543492771.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6398130-e5f8-4f3d-b56b-cd4a541cfdaf', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 24, '100004421', '連鎖', '一人、また一人と街の住民が姿を消していく、地獄流しの連鎖は止まる事がない。そしてそれは全て、拓真の仕業と住民たちは思っているのだ。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9290c9e2-0bdc-4d81-857d-ac46b1c38e9c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fe161a5-f0ac-4195-bb13-ebd9c15e32df', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 25, '100004422', '彷徨', '刑事の妹･蛍は拓真に残された唯一の味方だ。捕まえようと追い詰める住民から、彼女は必死に拓真を守ろうとする。', '2025/12/26 00:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e73c4270-7dce-4149-bd9b-a30b15c22d2b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a20802a7-1168-43cb-b4b2-c0fe08df0df2', '37d6b5ad-633e-4452-b2e3-bc8909ca9f84', 26, '100004423', 'あいぞめ', '【二籠 最終話】そしてついに拓真の名前が地獄通信に書き込まれた。彼の前に地獄少女が現れる。物語の終わりは誰も想像できない出来事だった…。', '2025/12/26 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebc6d7ac-df0a-4ddd-b68e-9e7366720611.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ea565712-7d88-459f-a035-b3cb43ba33a7', '地獄先生ぬ〜べ〜', '', 'hulu', 'hell-teacher-jigoku-sensei-nube', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/321b2d1a-5580-41e9-a68e-a653b669146f.png?w=331&h=447&p=t', 'hulu', 1996, 2, 1, 'FINISHED', NULL, 8208, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 'ea565712-7d88-459f-a035-b3cb43ba33a7', 'hulu-hell-teacher-jigoku-sensei-nube-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6808149f-89a1-4e81-8c62-d42c7602d005.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a036d7d3-8566-4951-9513-404b1561c0d8', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 1, '100231858', '九十九の足の蟲', '不可解な怪奇現象が多発する童守町。子どもたちを守るため、童守小学校に一人の教師が現れた。5年3組担任の鵺野鳴介、通称ぬ～べ～。日本でただ一人の霊能力教師だ。赴任早々、クラスの生徒･広と衝突する鵺野。怒りを抑えられず、別人のようになった広を心配するクラスメイトたちだが、鵺野は背後に潜む妖怪の存在に気付く。', '2025/07/05 23:45:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6808149f-89a1-4e81-8c62-d42c7602d005.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d521125b-6c81-4d6b-9b8f-ad7ffe75b142', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 2, '100231859', '妖狐･跳梁跋扈', '広に取り憑いた妖怪を必殺の武器･鬼の手で退治した鵺野。だが突如現れた謎の美青年･玉藻により広は連れ去られてしまう。教え子の郷子とともに後を追う鵺野だが、幻術に阻まれ行方を見失う。一方、玉藻はある目的のため、童守町の全域に渡って儀式の準備を進めていた。広を連れ去った目的とは? そして玉藻の真の姿とは!?', '2025/07/06 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0645b83-8ee4-4570-9532-83ede69e2b29.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f8eb7e1-fd85-41ba-a9f7-ad1f3f33af3e', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 3, '100231860', '真夜中の優等生', '真夜中の学校に現れる不気味な影…。誰もいないはずの教室で黒板を消し、花を取り替え、ウサギ小屋を掃除してくれる優等生がいるという。そんな噂の真偽を確かめるため、広たちは鵺野に内緒で夜の学校に忍び込む。しかしそこで出会った少年は、どう見ても人間ではなく…!? 少年は静かに微笑む。「さあ、友達になろう…!」', '2025/07/13 00:25:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1dddab44-0b96-48ec-b7be-370b5603c7cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8bfcc05-4cd1-4afb-96ee-15d71e8a87d0', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 4, '100231861', '妖怪ろくろっ首', '鵺野の力を目撃し、霊能力に憧れを抱き始めた美樹。雑誌や動画に夢中になり妄想が大爆発! 寝る間も惜しんで霊能力開発にのめり込んでいた。そんなある日、なんとベッドで寝ながら人の秘密をのぞき見ることに成功。「千里眼の能力ゲット!」と喜んでいたが、ある日クラスメイトたちから禍々しいものを見るような目で詰め寄られ⁉', '2025/07/20 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1c9b58d-628a-4523-b204-a2c6fb3213c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c9672c6-6fd7-4275-b04a-a17dc617fc29', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 5, '100231862', 'はたもんばの呪い', 'かわいい妹･愛美に人気のクレープを買ってやりたい克也は、足りない金を借りようと知り合いを探すうち、神社に落ちていた金を拾って使ってしまう。しかしそれは数多の罪人の首を斬ってきた呪われた妖刀･はたもんばの罠だった。罪人としてつけ狙われ、凶刃に追われる克也と愛美は必死の思いで鵺野に助けを求めるが…⁉', '2025/07/27 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd789adb-3307-41e1-922b-94a89d36d378.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc974f01-d1c5-4fe6-8d88-70009fa857bf', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 6, '100231863', 'てけてけの怪', '「踏切事故で下半身をなくした女子中学生の霊が、脚を求めてさまよっている…」ネットで話題の「てけてけ」伝説を知り、恐怖に取り憑かれたまこと。「話を聞いた人の元へ三日以内に現れる」――恐怖は周囲に伝染し、童守小は大パニック。だが鵺野はまことに「てけてけは作り話、今後いっさい考えるな!」と声を荒らげ…。', '2025/08/10 00:45:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19fc5880-bd2d-49bb-9955-31996c6567ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3eea664c-816b-48fb-b071-a8f13445b95b', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 7, '100231864', '季節はずれの雪女', '季節外れの雪が降る童守町。雪にまつわる記憶が蘇り浮かれ気味の鵺野の前に現れたのは、一人の美しい少女･ゆきめ。彼女は5年前に故郷の雪山で鵺野と交わした約束を果たしにやってきたのだという。モテない担任教師にやってきた恋の予感に湧く生徒たちだったが、突如ゆきめの様子が一変。雪女の本性を表して……。', '2025/08/17 00:45:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f95dc533-f276-4616-965f-264cf4bfb854.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db8ca881-5006-435d-8544-050a64e70963', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 8, '100231865', '霊界通信機で大発明!', '発明が大好きな晶は、ジャンク品のタブレットを手に入れて以来、何かに取り憑かれたように発明にのめり込んでいた。次々と生み出される発明品にはなぜか霊の気配が宿り始める。ついには「死んだ命を蘇らせる」と言い出し周囲は困惑。異変に気付いた鵺野が真相を探ると、タブレットの中から現れたのは…⁉', '2025/08/24 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7c0c133-9179-4148-b11f-e0f29e06f63f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e9a4545-b0ff-4197-90b5-4382c0cc3895', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 9, '100231866', '幸せを運ぶ少女', 'ある日、ぬ～べ～は人々に幸運をもたらす妖怪「座敷わらし」と出会う。好物の塩せんべいをあげたことで懐かれてしまい、その日から5年3組にも次々と思いがけない幸運が! やがて心優しいまことたちは「座敷わらしに何かお返しを」とある計画を立てる。交流を重ねる中で垣間見た、「幸せを運ぶ妖怪」の悲しい過去とは?', '2025/08/31 00:21:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f73994c8-66a5-4d07-8e1b-d7a00f157589.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97928f30-313c-477a-91df-27894f99fe19', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 10, '100231867', '百鬼夜行', '裕福な家庭に生まれ育った秀一は、不要と言っては物を簡単に捨ててしまう困った性格。物を大切にすることを忘れた秀一だったが、ある日、ボロボロの黄色い傘を見つける。何気なく拾った傘は意思を持ち、彼の前に妖怪としての姿を現した。傘妖怪にさらわれた秀一は、ボロボロになったゴミたちの百鬼夜行に参加させられて…⁉', '2025/09/07 00:21:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbfdf47e-dd85-47c7-81d1-1843be944a67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1bf8923-ba3e-494e-9422-a8da5d83edf6', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 11, '100231868', '鬼の手 VS.火輪尾の術', '広の頭蓋骨を巡ってぬ～べ～と戦い敗れ、消滅したはずの妖狐･玉藻が、童守総合病院の医師として童守小に現れた。怒りをあらわにするぬ～べ～に「しばし休戦」と告げる玉藻の狙いは、すでに広ではないという。突如として5年3組の生徒に炎の術で襲いかかる玉藻。その真の狙いは生徒たちではなくぬ～べ～の持つ「力」にあった。', '2025/09/14 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cffcdd28-d6c9-46c7-83ca-2e04fd4cbd1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75a3bd80-6834-4761-968b-a8932b4948f4', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 12, '100231869', '霊獣･霊霧魚', '童守小に現れた巨大な霊獣･霊霧魚。背中に卵を産み付けられた生徒たちは孵化と同時に死に至るというが、鬼の手で何度切り裂いても再生を繰り返す霊霧魚に為すすべがない。「生徒を守る時に最大の力を発揮する、その力の秘密を見せてみろ」と傍観を決め込む玉藻。刻一刻と孵化の時が迫る中、ぬ～べ～は決死の作戦を⁉', '2025/09/21 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb26f514-481e-44ad-b272-d145d017e406.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fe119d4-0640-46b5-b359-75949d81042f', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 13, '100231870', '人面疽', '突然、数日に渡って学校を休んだぬ～べ～。時を同じくして旧校舎に怪人がでるという噂が。正体を探りに向かった広たちが見たのは、巨大な人面疽に左半身を乗っ取られて悶え苦しむぬ～べ～だった。左手が動かず鬼の手が使えないぬ～べ～の代わりに、人面疽を除霊しなければ。生徒たちは恩師のピンチに知恵と勇気で立ち向かう!', '2025/09/28 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8386739a-1ab7-4771-ab55-ebacf02f601d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62ca66ef-6497-4fd0-97a2-5d1851ebf8f1', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 14, '100231871', '次元妖怪･まくらがえし', '稲葉郷子、26歳。入社4年目の社会人。今日も朝早くから、満員電車に揺られてブラック気味な職場へ。クレーマーの電話を取りつつ、鬼上司からのノルマに頭を抱え…って、こんなの本当の私じゃない! 大人として働く自分に強烈な違和感を覚えた郷子は、なんとか事態を解決しようとぬ～べ～を探すが、そこにいたのは…。', '2026/01/11 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abe4480e-3e26-4fbb-9919-afc7db194c35.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f5e1bcc-f5d6-43ba-aea5-b85847b760f4', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 15, '100231872', '時をかけるぬ〜べ〜', '妖怪チャブクロ――天から下がる巾着袋の姿をしたそれをつかんだ者は、過去へと戻り、自分の失敗を一つだけ修正できるという。ぬ～べ～がたった一つだけやり直したい過去。それは小学校の恩師にまつわる悲しい出来事だった。生徒たちを命がけで守る霊能力教師ぬ～べ～。現在の彼を形作った少年時代のエピソードが今明かされる。', '2026/01/18 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbb9e218-c2dc-4db1-8bdf-1880200e678f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8694f917-e9e7-4f23-8d9f-143963e5786d', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 16, '100231873', '雪女ふたたび', 'ぬ～べ～宛に届いたクール便を開くと、箱から飛び出てきたのは雪女のゆきめ! ぬ～べ～を愛するあまり、ふたたび山から戻ってきたゆきめは「この町で先生と暮らします!」と宣言。だが雪女と人間の同棲は上手くいくはずもなく…。冷たく突き放すぬ～べ～に怒ったゆきめは部屋を飛び出すが、そこでトラブルに巻き込まれ!?', '2026/01/25 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8c5d462-fd23-4faa-b53e-8c8029a426ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4ca207b-0e06-4f26-bf6b-5d3caf5f8f11', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 17, '100231874', '「A」がきた!', '警察官やパトカーがひっきりなしに行き交い、大人たちの携帯電話には緊急速報が鳴り響き、険しい顔で噂話…。いつもより不穏な空気が漂う童守町。そんな中、下校中の広、郷子、美樹の目の前に、赤いマントをまとった謎の仮面の男が現れる。「赤が好き? 青が好き? 白が好き?」奇妙な質問に答えてしまった子供たちは…⁉', '2026/02/01 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ccf9bc5-ed45-4030-9b38-576974046bc1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c14a0bf-5cb4-4cde-a59b-952cd0b1f666', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 18, '100231875', 'ダイダラボッチ', '建設中のビルの陰でしおれる花を見つけた美樹は、ビルに向かって「どっか行きなさいよ」と悪態をつく。すると翌日、ビルは道路の反対側に移動していた! だが美樹以外誰もそのことに気づかない。ぬ～べ～に相談しても「妖気のたぐいは感じない」という。自分にしか認識できない、という状況は次第に不安から恐怖へと変わり…。', '2026/02/08 00:25:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c809fee2-731c-4e8d-bcc7-0e492d66a0a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('776430be-ac37-4c51-983e-b7eb5b951877', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 19, '100231876', '神獣･麒麟', '愛美にもらったお守りを片手に、最近見つけた釣りの穴場へ向かう克也。しかし子犬を助けるために奥の禁足地に踏み入ってしまう。そこは神獣･麒麟が憩う聖域だった。思わぬ事故から麒麟を怒らせてしまった克也だが、助けを求めたぬ～べ～はいつもと違う厳しい表情。妖怪ならぬ神獣を相手に、決死のぬ～べ～に勝機はあるのか⁉', '2026/02/15 00:40:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/27935b85-718a-4477-b95a-e30d3d3d7176.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5a8ec0c-c197-4a9d-8b88-95a7e556413b', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 20, '100231877', '浜辺の雪女', '生徒たちを連れて海に遊びに来たぬ～べ～。そこに現れたゆきめは、暑さに弱い雪女であるにもかかわらず、灼熱のビーチでぬ～べ～に猛アピールしフラフラに。一方郷子は、かつてぬ～べ～を雪山にさらおうとした彼女にまだ強い警戒心が。距離を詰めてくるゆきめを冷たく突き放す郷子だったが、海水浴中に危険な影に襲われ…⁉', '2026/02/22 00:25:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c23e378a-83f3-40a9-b811-7d2f816c1c01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b8ad42c-9e32-4b8e-b8e7-a8cbba84b01e', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 21, '100231878', '妖怪しょうけらが窓から覗く', '5年2組の風間守は広のサッカー友達。人ならざる怪しい影が屋根の上で踊るのを目撃した時から、体調が急激に悪化。怖くなった彼は担任の律子先生ではなくぬ～べ～に相談する。普段の頼りないぬ～べ～しか知らない律子は憤慨するが、入院した風間を見舞いに訪れた病室で、自身もまた生徒を襲う妖怪の姿を目撃してしまう。', '2026/03/01 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08174bfd-422f-40b3-a63d-57dc4c66dfce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49d71ce2-8b5a-4a99-a6ef-31763395cfd5', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 22, '100231879', '七人ミサキ', '嵐が接近し全校生徒が早めに帰宅した童守小。帰りそびれた広と美樹は当直のぬ～べ～と合流。そこに一台の暴走車が校庭に侵入してくる。「化け物からかくまってくれ」と叫ぶ男女二人組。「なんて厄介なものを……」と頭を抱えるぬ～べ～。互いの怨念が絡み合う極めて凶悪な妖怪･七人ミサキ――広と美樹、決死のかくれんぼが始まる。', '2026/03/08 00:25:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/098a8d55-8177-490e-8811-14dd3cf678e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62fc516f-8100-4f1c-beda-4eb23f7b1a86', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 23, '100231880', '約束のレクイエム', 'ぬ～べ～宛に届いた一通の手紙、盗み見たその文面はどう見てもラブレター!? 手紙に書かれた約束の日、ぬ～べ～にこっそりついていった生徒たち。たどり着いた海辺の公園にいたのは、かつての教え子･秋山恵だった。教育実習生時代のぬ～べ～、霊能力教師の最初の一歩とは。そしてぬ～べ～が恵と交わした「約束」とは…。', '2026/03/15 00:25:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93f94020-d7a1-4f9c-a7b1-08164a468caf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4c98ee2-ca21-4ba5-b32a-f353235641d2', '28cbf20e-28fd-4eac-a9c5-54b74e4f585f', 24, '100231881', 'メリーさん', 'それは小学生なら誰でも知っている超有名な学園七不思議。メリーさんから手足の無い呪いの人形を渡された子は、1週間以内に学校のどこかに隠された手足を探し出さなければ、足りない部分をもぎ取られてしまうという。法子に狙いを定めたメリーさんを除霊すべく相対したぬ～べ～だったが、彼女の意外な過去を知り…⁉', '2026/03/22 00:15:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0462aa81-ec9e-4e0c-b66b-c8d17f0df24e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('302f43b3-dc07-4c18-b127-e8c4fe1cc53a', '地縛少年花子くん2', '', 'hulu', 'hanakokun', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/587172e3-4829-4ac6-b04e-9499dea66f83.png?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 170892, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('28031736-b0f6-4208-9114-8d52570526fb', '地縛少年花子くん2', '', 'hulu', 'toilet-bound-hanako-kun2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97fbe571-3db7-4a01-8110-e6b6963bf22b.png?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 170892, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f0267bed-1185-4027-a718-814c8254b48c', '28031736-b0f6-4208-9114-8d52570526fb', 'hulu-toilet-bound-hanako-kun2-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3058d44-9093-4c7f-8718-fda2804c4980.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f73dc06-b662-4c81-a732-ddf8d116d150', 'f0267bed-1185-4027-a718-814c8254b48c', 1, '100211789', 'トイレの花子くん', '花子くんの助手として怪異の噂を安全なものに戻していた寧々と光。親友の葵から ”七不思議が一番『三人の時計守』”の噂を聞いたその日、かもめ学園で生徒たちが急に年老いてしまう怪事件が起こる。花子くんはその事件の裏に、『三人の時計守』が関わっていると踏み、寧々たちと共に時計守を探し始める。', '2025/01/12 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3058d44-9093-4c7f-8718-fda2804c4980.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3fc13995-bd77-417b-a1fe-c91c47821f00', 'f0267bed-1185-4027-a718-814c8254b48c', 2, '100212343', '三人の時計守', '七不思議が一番『三人の時計守』、そのうちのひとりは寧々も良く知るクラスメイトの蒼井 茜だった。花子くんは事態を解決すべく、茜に協力しようと持ちかける。だが、茜は過去の出来事から怪異を憎んでいて、花子くんにも不審感を抱いているようで……。', '2025/01/19 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6897be4-6fd6-47d1-8eaf-8376cf79d89a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11007617-232b-4a16-86e9-34a2fc623dcc', 'f0267bed-1185-4027-a718-814c8254b48c', 3, '100212720', 'さがしもの', '寧々はもうすぐ死んでしまう。思いも寄らない未来の話に、光は悩む。何も知らない寧々は、いつもどおりに学校へ通うも、花子くんの姿が見えない。寧々は花子くんの行きそうな場所をひとつひとつ尋ねていく。', '2025/01/26 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3e87566-b0a1-4674-b509-c2c9bf3474a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a0f550f-a495-4794-a355-e979eb8a693b', 'f0267bed-1185-4027-a718-814c8254b48c', 4, '100214779', '夏灯り', 'ミツバのこと、寧々のこと……いくら考えてもいい解決策は思いつかない。ひとり思い悩む光。そんな光に、もっけ運輸から荷物が届く。それは寧々が悩む光を励ますべく送った夏祭りへのお誘いだった。二人がお祭りに行くのが妬ましい花子くんは、寧々と光を怪異たちの夏祭りへ案内する。', '2025/02/02 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d34ff5a-3c85-4ca9-a92e-d404b6944f68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0679d7e0-ef6c-4548-bcd0-df5ed9a542d6', 'f0267bed-1185-4027-a718-814c8254b48c', 5, '100215487', 'もっけ･オブ･ザ･デッド／新･三番の憂鬱', '誰もいない校舎、誰もいない実験室。捕らわれていた怪異が――逃げ出した。その怪異に噛まれてはいけない。見つかってはいけない。ヤツらはただ求める……飴を。', '2025/02/09 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a9eb73a-47db-45ef-836f-c1c71ff0bc52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40be6493-4902-45f8-a4f6-904918bdf2be', 'f0267bed-1185-4027-a718-814c8254b48c', 6, '100215488', 'エソラゴト', '初夏。むせかえるような暑さとセミの喧噪の中、寧々は登校する。いつもよりちょっと寝坊した、だけどいつもどおりの朝。ホームルームに間に合ってひと息ついたその時、後ろから声をかけられる。振り向くと、そこにいたのはかもめ学園の制服を着た花子くんだった。', '2025/02/16 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0f3246f-64aa-4146-ba42-9ed95847c86a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78937a20-c8ba-48c5-b873-1c65559a9aa9', 'f0267bed-1185-4027-a718-814c8254b48c', 7, '100217987', 'ヨマイゴト', 'そこにいるはずのない、“柚木普”と“三葉惣助”。戸惑う寧々と光をよそに、すべてを受け入れている茜や葵たち。友人が突然バラバラに砕けてしまう……そんな明らかな異常事態さえ笑って見ているだけのクラスメイト。優しい土籠。土籠と親しげなヤコ。料理が得意な輝。何もかもがおかしい世界で、光は真相を突き止めるべくミツバを追う。', '2025/02/23 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e714adb5-0202-4db7-a5fd-90e11d76d4ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e531af1e-c013-4013-90bf-7d48a44a9f0a', 'f0267bed-1185-4027-a718-814c8254b48c', 8, '100218787', 'キレイゴト', 'シジマは言った。「元の世界に戻りたければ“柚木 普”と“三葉惣助”を殺せ」と。つかさは言った。「あまねのこと上手く殺せるといいね」と。頭が追いつかない寧々をよそに、普は無邪気に星を見るため寧々を屋上へ連れて行く。', '2025/03/02 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9644b3df-6a66-4f9b-b456-9556bb227b8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa62ecf9-bf26-43f5-a578-f61f367e198c', 'f0267bed-1185-4027-a718-814c8254b48c', 9, '100220304', 'カクシゴト', '寧々は普の手を取り学校を出る。この世界から逃げ出すために。乗り気ではない普も、寧々を放っておくことはできずついていく。夜の学校を抜けだし、自転車で街へ繰り出す二人。それを阻むようにシジマは行く先々に現れる。シジマから逃げていく先で、寧々と普は不思議な筆と出会う。', '2025/03/09 18:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e525488d-4a8c-4f33-b01a-377a02e25807.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa882435-98d7-417b-bff6-4e0574b15c6d', 'f0267bed-1185-4027-a718-814c8254b48c', 10, '100221055', 'ネガイゴト', '正体を現した花子くんは言った。虚構の世界なら寧々の命は尽きることなく、ずっとずっと生きることができると。その言葉に花子くんを止めようとしていた光の中で迷いが生じる。寧々も自身の寿命のことを知り動揺を隠せない。動揺と同時に、もうひとつふつふつと胸の内に滾る感情。それは寧々のためにと何もかも隠してしまう花子くんへの怒りだった。', '2025/03/16 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f9178a3-8767-4fc8-b5c4-985cc3c8468d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9722fada-6ad9-4399-8d27-79988804338e', 'f0267bed-1185-4027-a718-814c8254b48c', 11, '100221901', 'ヒトリゴト', '生前の四島メイと出会った寧々は彼女もまた、自身の寿命と向き合っていた少女だと知る。それでもメイは挫けない。自分の死を否定して、前向きに筆を取る。そんなメイの前に怪異のシジマが再び現れる。', '2025/03/23 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e2988f2-b7f2-4e78-97a9-e5475c8ee024.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('155f6b4e-c314-4967-943e-35a07d88a2f3', 'f0267bed-1185-4027-a718-814c8254b48c', 12, '100222698', '絵空事', '花子くんの願い。ミツバの願い。シジマの願い。怪異たちのどこか歪な願いを知った寧々は考える。花子くんの本当の願いってなんなんだろう……寧々と光は怪異たちの想いを受け止めながら塔の屋上を目指す。そこにいる花子くんと、もう一度話すために。', '2025/03/30 17:30:00', 1413, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f098c21c-b177-41f2-8ee3-499cfea0b767.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d581cad-a28b-4901-a91e-d9e99a3cc7c7', 'f0267bed-1185-4027-a718-814c8254b48c', 13, '100231789', '期末試験と宿泊学習', '自身の寿命が残り1年と知ってしまった寧々。それでも寧々は現実世界で生きることを選んだ。そんな寧々に目下迫るは——期末試験。同じく赤点ギリギリの光と共に、寧々は試験に向けて勉強に励む。一方、輝は茜に試験での勝負を提案する。', '2025/07/06 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9a96c7a-c90c-40a5-bf50-73b3707cd455.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0351c462-a897-4f1d-aac4-edc6e985bcce', 'f0267bed-1185-4027-a718-814c8254b48c', 14, '100232299', '此岸と彼岸', '六番目の七不思議『シニガミ様』にさらわれた葵。葵を助けたい寧々と茜の前に現れる、少女の霊。霊に導かれるまま、二人は謎のエレベーターに乗り込み閉じ込められてしまう。花子くんに助けを求める寧々。だが、花子くんは他の七不思議たちに足止めを喰らっていた。', '2025/07/13 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f70acd2c-2f5e-47f5-a848-c2f7b1c7e103.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fee5c322-2642-4f3f-a096-a65d5cf087c0', 'f0267bed-1185-4027-a718-814c8254b48c', 15, '100232663', '死神の生贄', '葵を探す寧々。そして寧々の寿命、ミツバとの約束。やるべきことはあるのに自分に出来ることの少なさ、その無力感に悩む光。そんな光の前に、夏彦が現れる。夏彦は言う。"寧々が長生きする秘訣"を教えようか、と。', '2025/07/20 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62196a94-9b81-4685-9487-ec4b89ff2c53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca0e80fd-0d1e-4452-a999-5b68f312748d', 'f0267bed-1185-4027-a718-814c8254b48c', 16, '100233307', 'スミレ', 'シニガミ様のしもべとなった葵。葵に絡め取られ、花子くんと寧々は奈落へと突き落とされた。目を覚ました寧々の眼前に広がる、どこともしれぬ古い村。花子くんと寧々は村人たちに物の怪と恐れられ、殺されかける。そんな二人を助けたのはカンナギである少女、スミレだった。明日は彼女の結婚式。その相手は葵をさらったシニガミ様。', '2025/07/27 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0bd2bf8-2f86-4810-a2fa-8710ddd04433.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9295d168-aee6-420b-bbec-d7548d8ea085', 'f0267bed-1185-4027-a718-814c8254b48c', 17, '100233821', 'アオイとアカネ', 'スミレの代わりに生贄にされそうになる寧々。花子くんの抵抗もむなしく、二人はやがて崖へと追い詰められる。その様子を、ただ見つめるスミレ。いつもと状況の違う生贄の儀式。それでも、シニガミ様はスミレの元にはやってこない。スミレは落胆し、崖から身を投げ出す。', '2025/08/03 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3720f729-d64e-4f34-9af9-5f9fe728be98.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b5d8e8a-2365-4b5a-a1ff-c28ba46bdd6b', 'f0267bed-1185-4027-a718-814c8254b48c', 18, '100234674', '断絶', '本心を打ち明ける茜と葵。初めて心を通わす二人。けれど、もう茜の前に葵はいない。花子くんもいる現実世界で生きたいと願う寧々。その想いとは裏腹にどこか様子がおかしい花子くん。どこまでも人と怪異は混じり合わない。混じり合えない。それを証明するように『断絶』が始まる。', '2025/08/10 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc157779-6e76-4411-8f71-2af60136c8c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49f1661c-e444-431c-b14f-9cdc71e9353f', 'f0267bed-1185-4027-a718-814c8254b48c', 19, '100235050', '遭遇', '怪異の消えた断絶の世界。寧々と茜は、花子くんと葵に会うべく再び立ち上がる。手がかりは、七不思議たち。彼らと縁のあるものを捜し始める。手分けして捜索する中、寧々と光は七不思議三番目『カガミジゴク』となったミツバの生前を追う。', '2025/08/17 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c031abe7-d146-48b7-9db0-986b92efc825.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('060c2c53-94cc-40e2-a6a8-326132c645b3', 'f0267bed-1185-4027-a718-814c8254b48c', 20, '100235523', '赤い家', '赤い家に迷い込んでしまった寧々と光。二人はそこで、花子くんにそっくりな子どもと出会う。花子くんとの繋がりを求めて子どもを保護しようとする寧々たち。だが、それを拒むように家の中で異変が起こりはじめる。', '2025/08/24 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79828a0c-b4b3-49d0-a5bc-bb336f65544b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87ea0298-af65-4785-9a69-fee45bf69784', 'f0267bed-1185-4027-a718-814c8254b48c', 21, '100236100', '呪い', '寧々たちが赤い家に迷い込んでいたその頃、輝と茜は境界へ渡る手がかりを見つけるべく、源家と縁のある神社を訪ねる。不遜な態度で輝たちを出迎えたのは、宮司である渚 國重。一触即発の雰囲気の中、茜に一本の電話が……その声を聞いた渚は青ざめ、ある子どもの話を始める。それは、かつて神隠しにあった柚木家の子どもの話だった。', '2025/08/31 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75ede87e-42d4-4a2a-911d-48407de95870.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8510133a-b911-42f8-b6d7-f3ca43253db9', 'f0267bed-1185-4027-a718-814c8254b48c', 22, '100237354', 'つかさとあまね', 'カタクリに送られ、赤い家に戻ってきた寧々。寧々は目の前の子どもが幼い頃のつかさだと知ると、つかさから生前のあまねの話を聞く。つかさが語る、あまねの過去。赤い家に潜む、妖しい存在。寧々と光は知る。幼いつかさが何故、赤い家に居続けるのか、その意味を。', '2025/09/07 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7beb6cb3-d8e8-415b-8f0f-a80d5b2ebd07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb0c40c1-4f94-4839-a398-78159cca5d60', 'f0267bed-1185-4027-a718-814c8254b48c', 23, '100237797', '片道列車彼岸行', '赤い家から無事に脱出した寧々と光。その間に、輝は境界へと渡る手がかりを手に入れていた。境界へ向かう前日、輝たちは決起集会のようにピザパーティーを開く。花子くんと葵に再会する時を夢見て、密かに心躍らせる寧々。だが、輝が葵を助け、花子くんを殺すという計画を光と茜に打ち明けているのを聞いてしまい――', '2025/09/14 17:30:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf86860a-73c7-438d-a728-43f76cfafb16.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90a3c4d7-0847-4a33-879e-1ee1451f1f46', 'f0267bed-1185-4027-a718-814c8254b48c', 24, '100238744', '願い', '【最終話】寧々は走る。花子くんを連れて。光は構える。二人を守る為、兄の前で。花子くん (怪異) と寧々 (人)、光 (弟) と輝 (兄) ……交わることのなかった想いが、此岸と彼岸を繋ぐ境界でぶつかり合う。', '2025/09/21 17:30:00', 1413, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cfb1c0fb-a8d9-45f1-af23-d426cf970e8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('87e70090-ad6f-40ae-a9ca-6ca8360e6f5c', '池袋ウエストゲートパーク', '', 'hulu', 'ikebukuro-west-gate-park', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea4ed9fb-d6b3-4be7-8a51-6660fe3def5e.jpg?w=331&h=447&p=t', 'hulu', 2020, 3, 1, 'FINISHED', NULL, 111324, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d1ce3a4c-d247-4dd2-8cba-fb9848512cde', '87e70090-ad6f-40ae-a9ca-6ca8360e6f5c', 'hulu-ikebukuro-west-gate-park-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfc74831-cf15-4755-95db-9bcbedae3345.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92bd64cf-d040-4a89-9bc8-d2a9d1193b5d', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 1, '100103476', '北口スモークタワー', '東京、池袋。西一番街にある真島青果店の息子･マコトは、ヤクザ絡みの犯罪やギャングの縄張り争いなど警察では手出しができない問題を解決したことで、“池袋のトラブルシューター”と呼ばれていた。今日もマコトのもとには厄介な事件が持ち込まれて…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfc74831-cf15-4755-95db-9bcbedae3345.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fcbf400-8a77-48c2-a949-ed504b675cec', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 2, '100103477', '西一番街ブラックバイト', 'ある日、池袋にもう一人のカリスマが舞い降りた。名前は尾崎キョウイチ。彼が率いる『レッドエンジェルス』は瞬く間にメンバーを増やし池袋で勢力を広げていた。そんな中、『レッドエンジェルス』と悪名高いブラック企業が裏でつながっているという噂が流れて…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8ac5a5a-1651-426b-97ac-e82940e8f156.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09957100-9cd0-4898-9278-52b6de92a5a0', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 3, '100103478', 'ゼタムーバー＠芸術劇場', '動画投稿サイト「ゼタ･ムービー」の人気投稿者･140☆流星からボディーガードの依頼がきた。対立するライバル投稿者から脅迫を受けているので守ってほしいという。流星の話を聞いているうちに、彼の真剣な仕事への取組みに感銘を受け、その依頼を受けるマコトだったが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7963f8ac-07df-4148-aedc-4dafcc21345a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dac80a21-c3dd-4dd3-b8d1-20a5b8c330be', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 4, '100103479', 'ワルツ･フォー･ベビー', 'クリスマス間近、マコトは殺人事件でひとり息子を亡くしたタクシー運転手･靖洋と出会う。自分と似た境遇の靖洋に親近感を覚え、犯人捜しの協力を申し出たマコトは、靖洋の息子がヘッドを務めていた上野のチームの情報を集めることにする。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bfdedb9-ac41-46d5-b815-4c18d114975c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9a2a470c-9511-42a9-a40a-00e8d318d79a', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 5, '100103480', 'ドラゴン･ティアーズ', '技能実習生のアドバイザー･林は、日本の縫製工場から失踪した少女･クーの行方を追っていた。一週間後の査察でクーがいないと同期の実習生たちが中国に強制送還になってしまうという。タイムリミットが迫る中、マコトにクーの捜索を依頼するが、その裏には中国人組織の「東龍」が深く関わっていて…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/383110a6-6b2a-46e0-8a55-d72d44442365.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f55265e3-8681-4446-8917-cf571e675fc4', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 6, '100103481', 'Gボーイズ冬戦争･前編', '思いがけず自主映画に出演することになったマコトは慣れない芝居に疲労困憊。そんな彼のもとに、Gボーイズ内のヒロト派のチームが何者かに襲われたという情報が舞い込む。タカシに不満を持っていたヒロトはこの襲撃事件はタカシの仕業だと疑いはじめるが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72b7a92a-def6-4001-b159-7de9e6c47e07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4c5d4a5-1d53-4fbe-be05-a2dce28cc4e8', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 7, '100103482', 'Gボーイズ冬戦争･後編', 'Gボーイズからの独立を宣言したヒロト。マコトは戦争を止めるために自主映画の撮影を続けつつ、池袋の混乱をたき付ける組織の情報を掴むが、ついにはマコト自身が襲撃を受けてしまう。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0d5d319-4ffc-45a0-826f-c2e13d668ec8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('835ad116-7fd0-406e-8d42-9869201f4877', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 8, '100103483', '千川フォールアウト･マザー', '母親の留守中に子供がベランダから転落する事故が起きた。キョウイチからの依頼でその親子の様子を見てきてほしいと頼まれるマコト。だが母親のユイは事故後、SNSで酷い誹謗中傷を受けていた。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e21a52d-fb98-405e-950b-951c1f00b0f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f43fe18-7b27-436a-9274-4da29a7ae848', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 9, '100103484', '憎悪のパレード', '今回の依頼は、外国人から日本を取り戻そうと主張する団体「外排会」のデモを守ること。彼らの活動を認めない「へ民会」が依頼主で、過激な仲間が力づくで相手に攻撃するのを防いでほしいという。不本意な依頼に気乗りしないマコトだったが、思わぬところから大きな事件に発展してしまう。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3279f17a-2238-4abc-8999-775931781f6e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09138863-b1ab-4094-994d-aec3c5518490', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 10, '100103485', '野獣とリユニオン', '路上強盗に足を壊され、料理人になる夢を奪われた兄の復讐を誓った妹のチヒロは、少年院から出て普通の生活を送る犯人を恨み、同じ目にあわせてほしいとマコトに依頼する。マコトは調査をする中で、犯人の意外な事実に直面する。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a53e9e7d-2425-4d5f-b599-1e0b8cdc57e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c82aad7-1766-4214-ae2c-8c2964e3b067', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 11, '100103486', 'サンシャイン通り内戦 (シビルウォー) ･前編', 'ここ最近、Gボーイズとレッドエンジェルスの小競り合いが池袋のあちこちで起きていた。事態を収束させようとマコトがトップ会談を進言し、タカシとキョウイチも話し合いでの解決を望んでいたが、レッドエンジェルスのメンバーが刺殺されたことで事態は急変。サンシャイン通りを境界とした全面戦争が始まろうとしていた。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/138fa66e-60f5-4c1b-a8e2-a46d86687010.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e958222-2212-4c35-a2c9-76b2ffcfde64', 'd1ce3a4c-d247-4dd2-8cba-fb9848512cde', 12, '100103487', 'サンシャイン通り内戦 (シビルウォー) ･後編', '【最終話】追われる身となったマコトは、抗争を裏で操っているのが関西の組織･京極会だと掴む。一方、両グループは武器を手に入れ、西口公園での最終決戦への準備を着実に進めていた。タイムリミットが迫るなか、マコトは真の黒幕に接触を図る。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ce55e5b-6ef4-48a1-9ab0-ef9f1208cd85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8a1163db-855e-4002-b774-bbe2cd4f0f1b', '蜘蛛ですが、なにか？', '', 'hulu', 'so-im-a-spider-so-what', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/499d6fcd-2331-4cca-a2bd-d246d0eb0ead.jpg?w=331&h=447&p=t', 'hulu', 2021, 0, 1, 'FINISHED', NULL, 103632, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1a600654-911d-449a-963e-f8d50ccc0d83', '8a1163db-855e-4002-b774-bbe2cd4f0f1b', 'hulu-so-im-a-spider-so-what-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75c400fb-ef00-4e1d-b7d8-57951e6b707f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5f17792-9d2d-4674-8edd-7f0c32425134', '1a600654-911d-449a-963e-f8d50ccc0d83', 1, '100073172', '転生、異世界?', '目を覚ますと蜘蛛に転生していた「私」。生まれてすぐ同種の共食いに巻き込まれ、さらには母蜘蛛にまで命を狙われるって無理ゲーすぎる! メンタル最強女子高生 (?) の異世界サバイバル開幕!', '2021/01/15 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75c400fb-ef00-4e1d-b7d8-57951e6b707f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9318b69a-f86e-4539-909e-23acd5a907cf', '1a600654-911d-449a-963e-f8d50ccc0d83', 2, '100073550', 'マイホーム、炎上?', '拠点となるマイホームを作り、魔物を倒してレベルアップを重ねる「私」。食料がまずいことを除けば、それなりに満足できる生活を送っていた。しかし、人間が現れたことで状況は一変。マイホームに火が放たれ……。', '2021/01/22 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a951eb2-5030-4a80-85e9-d40946d22641.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebf181ce-ae6a-4201-a94c-cd5555c1283d', '1a600654-911d-449a-963e-f8d50ccc0d83', 3, '100074066', '地竜 (龍)、ヤバい?', '上位種に進化した「私」は新スキルの習得やステータス向上により強くなった。向かうところ敵なしとばかりに迷宮を突き進んでいくが、勢い余って凶悪な魔物がうろつく下層に落ちてしまい、さらなるピンチに見舞われる。', '2021/01/29 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e55df5e3-b8c1-4679-ba50-67d4355121c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac1438f1-6b38-481a-a1eb-123f849a9f5a', '1a600654-911d-449a-963e-f8d50ccc0d83', 4, '100074540', '猿、ホアー?', '地龍の脅威から逃れた「私」は、逃げ出したことをちょっぴり悔やみながらも、前を向いて進んでいく。しかし、ここエルロー大迷宮は魔物同士がせめぎ合う弱肉強食の世界! 新たな脅威がすぐ側まで迫りつつあった。', '2021/02/05 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c09ad792-3f0e-4a48-a6ff-1fc01f57f895.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf91a118-e061-4948-a0b3-d1be536e40f2', '1a600654-911d-449a-963e-f8d50ccc0d83', 5, '100075325', 'なまずって、おいしい?', '新たな階層へたどり着いたものの、目の前に広がっていたのは灼熱地獄のマグマ地帯! スキルの要となる糸は燃えるし、マグマの中を泳ぐ魔物とはまともに戦えない。「私」は先送りにしていた次の進化を試みる。', '2021/02/12 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/196884be-35a2-4a43-b3c0-a1eb4c50fca8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26387811-3f66-47da-ba01-978863e3f82d', '1a600654-911d-449a-963e-f8d50ccc0d83', 6, '100075710', '勇者と、魔王?', '中層のマグマ地帯の探索を続け、新たな魔物に遭遇した「私」。素早さ以外は勝るところがない、絶望的なほど格上の強敵だった!「私」は新たに取得したスキルを駆使しながら、反撃の一手を探ろうとする。', '2021/02/19 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1355c2b-3066-46da-af18-3ddbcd7d8852.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee7fb89e-0eac-470b-a742-4a82aff38a6f', '1a600654-911d-449a-963e-f8d50ccc0d83', 7, '100076370', '王子たち、青春する?', '〈忍耐の支配者〉の称号を手に入れた「私」は、邪眼系スキルが解放されたことに大喜び! さらにスキル〈鑑定〉のレベルがカンストし、不思議な現象が起こる。一方、学園ではサバイバル実習が始まろうとしていた。', '2021/02/26 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d512428b-2aeb-4d9c-96a1-4f2d79e57a10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d61bb868-072b-4f63-8f8a-2cd483c5983c', '1a600654-911d-449a-963e-f8d50ccc0d83', 8, '100076861', '私、死す?', '管理者の存在を感じ取り、震え上がる「私」。でも、悩んでいたって仕方ない! 今まで通りを貫く「私」は、異常なステータスを受け入れ、魔法を習得しようとする。すると、遠くから激しい戦闘音が聞こえてきて……。', '2021/03/05 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/121ea0c0-c83d-4b95-9899-c4ef988d2ff4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81f8f1be-657e-418e-ac4a-a439a5dd719e', '1a600654-911d-449a-963e-f8d50ccc0d83', 9, '100077533', 'アイキャントスピーク、イセカイゴ?', '尊敬する勇者、ユリウスが長旅から帰還した。舞い上がるシュンだが、喜びも束の間、ユリウスはまもなく帝国へ向かうという。魔族が不穏な動きを見せているというのだ。大規模な戦闘になるおそれもあるというが……。', '2021/03/12 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d2abad3-86d8-4e8b-ace2-831e6a59bac9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85cdd8d9-1f0c-4706-8050-0f4abbe03b5a', '1a600654-911d-449a-963e-f8d50ccc0d83', 10, '100077989', 'このじじい、誰?', '管理者Dがとんでもなくヤバい奴なのはわかった。でも、今は考えても仕方ない!「私」は上層を目指して前へ進む。たくさん食べて、マイホームを作る夢を見ながら。一方、王国は魔族軍の猛攻によって窮地に陥っていた。', '2021/03/19 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1bfab0d-e044-4d5f-9a19-98e08499d5eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27309836-87f1-4621-bad0-bee4577c0fcd', '1a600654-911d-449a-963e-f8d50ccc0d83', 11, '100078376', '次回、決戦?', '新たな進化を遂げたものの、なんだか不愉快な「私」。それもそのはず、取得したスキルによって世界の真実を知ってしまったのだ。世界のうねりに巻き込まれないため、「私」は自分の“トラウマ”に向き合おうとする。', '2021/03/26 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4144a996-037c-4c5e-b58b-6c86514f3e24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b08edf5c-4c30-4bb1-a96f-adc3355c5d00', '1a600654-911d-449a-963e-f8d50ccc0d83', 12, '100079003', '私の戦いは、これからだ?', '自分の弱さを乗り越えるためにも、地龍アラバと決着をつけなければならない。「私」は着々と準備を進め、持てる力すべてを駆使してトラウマに挑む。……しかし、最強の地龍はチートと呼べるほどの力を隠し持っていた!', '2021/04/02 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/86e0f85a-108d-45d0-a47e-8c5669b1fdec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7eca5b3-55ac-40b5-ac77-1744cf478456', '1a600654-911d-449a-963e-f8d50ccc0d83', 13, '100079998', 'やったー、外だー 私は自由……だ?', '念願だった外の世界! しかし、「私」に敵意を向ける人間や因縁の相手からの妨害があり、門出は前途多難で……。一方、シュンの周辺は魔族との次なる戦争を前に慌ただしさを増し、大切な人たちの前にも脅威が迫っていた。', '2021/04/16 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21fc4f21-21aa-4cef-a827-536b229c426e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('612a7034-418c-478d-87a6-b5a8a7d7776b', '1a600654-911d-449a-963e-f8d50ccc0d83', 14, '100080546', 'おまえ反逆? 私、自虐', 'マザー対策を打って一人旅を続ける「私」は、道すがら盗賊たちに襲われる馬車を発見する。人助けをする義理はなかったが、赤ん坊がいることを知り颯爽登場! だが、その赤ん坊を鑑定すると、驚きの結果が出て……。', '2021/04/23 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6cbe722-6206-495f-b158-15a9bb057d9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de9a742f-eb3d-447e-b1f2-a9d56bf7999c', '1a600654-911d-449a-963e-f8d50ccc0d83', 15, '100080860', 'マザー、からの厄介蜘蛛人形?', 'マザーとの精神の繋がりを利用し、「私」は並列意思を送り込み、マザーの精神を直接攻撃していた。順調に成果を上げていくが、反撃してこないなんて何かおかしい! そこにはマザーの巧妙な罠が仕掛けられていた。', '2021/04/30 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c585d2bd-fc61-4adf-80aa-6ddb1c9b8824.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('044aaeac-6b83-4e30-b3fe-4ae383bb3ebe', '1a600654-911d-449a-963e-f8d50ccc0d83', 16, '100081273', 'フライング、ゲット?', 'ザナ･ホロワに進化し、「私」はとんでもないチートスキルをゲット! だが喜びも束の間、あの管理者Dが再び接触してくるのだった。しぶしぶ相手をする「私」は、転生の理由と世界の秘密の一端を知ることになり……。', '2021/05/07 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d46773f1-c39d-4d09-881d-285277f8f2ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab1ca0c0-e4e1-4191-ac80-fd1ffc7dd8dd', '1a600654-911d-449a-963e-f8d50ccc0d83', 17, '100081940', '私、なにしてる?', 'かつてエルロー大迷宮には伝説として語られる魔物「迷宮の悪夢」が存在した。そして悪夢が残した魔物が、今も迷宮には潜んでいるという。悪夢の残滓を避け、最短コースを抜けようと急ぐシュンたちだったが……?', '2021/05/14 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c09bafb-8f8c-4665-bad9-e4bcf369cc77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7bc3715-b5de-41e1-ab71-2cb4d8b6d9f9', '1a600654-911d-449a-963e-f8d50ccc0d83', 18, '100082623', 'みんな、腹黒くね?', '完全復活を遂げた「私」は、かつて命を救った赤ん坊･ソフィアの住む街に到着! 彼女は今も何者かに狙われている様子で……。一方、シュンはエルロー大迷宮を抜け、女神を信仰するサリエーラ国に辿り着いていた。', '2021/05/21 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa7e0255-0387-4a7d-93e7-8627ba11219f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffa6675a-031b-4f48-a1c4-307c3e97addd', '1a600654-911d-449a-963e-f8d50ccc0d83', 19, '100083183', 'ひらけ、同窓会?', 'ソフィアを守るだけでなく人助けをしたことで、気づけば「私」は人々から「ご神獣様」として崇められていた。こそばゆいけれど、満更でもなくて……。一方、シュンたちはエルフの里で懐かしい顔ぶれに再会する。', '2021/05/28 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95d5c81d-01a0-4bb2-9f95-e5b09bea7ba4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e51afb6e-8f79-41c4-b849-195194c51201', '1a600654-911d-449a-963e-f8d50ccc0d83', 20, '100083587', '私のせいじゃない、よね?', 'マザーを撃破し、アリエルから逃げるようにケレン領へ帰ってきた「私」。そこへ招かれざる客が立て続けにやってくる。一人は「私」の力を狙うオウツ国の使者。もう一人は管理者のギュリエディストディエスだった。', '2021/06/04 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a2be6ce-231a-40e5-aabe-d5957241a43b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1b14122-88d6-4fd2-a643-e04f7c9664ba', '1a600654-911d-449a-963e-f8d50ccc0d83', 21, '100084207', '私、出番ないってか?', 'エルフの里の結界は盤石、強力な仲間も加わった。戦争に向けた準備が着々と進む中、シュンたちはフィリメスから転生者の秘密と管理者の存在を明かされる。そして、この戦争が「仕組まれたもの」であることも……。', '2021/06/11 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/272211a8-1d39-4f9f-a38a-52e687afbd26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b7e5711-7267-468c-b88e-136c1d31c1da', '1a600654-911d-449a-963e-f8d50ccc0d83', 22, '100084527', '私よ、永遠に?', 'ついにオウツ国連合の進撃が始まった。勝ち負けに興味はないけど、経験値を稼ぐために「私」も参戦! アリエルに勝つためには戦争を利用するしかない! だが、当のアリエルが戦場に現れてしまい……!?', '2021/06/18 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c09558a4-a9c4-47eb-9d4c-4e610a478497.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('815fbcce-110e-47d7-bfa7-a137aa9f623c', '1a600654-911d-449a-963e-f8d50ccc0d83', 23, '100084864', '友よ、なぜおまえは……?', '光を纏いし剣と闇を纏いし剣――。シュンとユーゴーの因縁の戦いに決着がついた瞬間、戦場にソフィアが現れる。彼女の存在が意味するのは、魔族軍の介入。そして、シュンはソフィアの異常な強さに驚愕する。', '2021/06/25 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f19cbd12-1b64-4c85-8f0a-c86e3b39b99a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f809d8b1-f489-49ed-b140-c43404f5fd38', '1a600654-911d-449a-963e-f8d50ccc0d83', 24, '100086616', 'まだ蜘蛛ですが、なにか?', '【シーズン1 最終話】絶望的な状況に陥りながらも逆転の一手を模索する「私」。追い詰められながらも剣を構え続けるシュン。時代を超えた不屈の魂はどこへ辿り着くのか。大きな転換を迎える世界の中で、すべてが繋がっていく――。', '2021/07/10 22:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/985de96e-f8ee-4817-a8ac-18d68516ed4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d1a7fb32-6930-4c26-9e79-1030dfbe8219', '中間管理録トネガワ', '', 'hulu', 'mr-tonegawa-middle-management-blues', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9133a4d6-b066-4254-8d4a-d38b12a2658a.jpg?w=331&h=447&p=t', 'hulu', 2018, 2, 1, 'FINISHED', NULL, 101161, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1f48cf62-d536-4b0e-b5ea-67452ee3a9f0', '中高一貫!!キメツ学園物語 ～バレンタイン編～', '', 'hulu', 'junior-high-and-high-school-kimetsu-academy-story', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe9bd166-0332-404b-bc5c-4488d41c1dbd.jpg?w=331&h=447&p=t', 'hulu', 2021, 0, 1, 'FINISHED', NULL, 129627, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1af325a1-a24a-46de-b8b7-09cb70eef351', '1f48cf62-d536-4b0e-b5ea-67452ee3a9f0', 'hulu-junior-high-and-high-school-kimetsu-academy-story-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1a91b92-132c-471e-82c3-f82239b43b42.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aae159e1-c9f0-4896-a045-0a0d7c2ec2dd', '1af325a1-a24a-46de-b8b7-09cb70eef351', 1, '100077591', '鬼滅の宴 特別編 第一話', '体育教師の冨岡先生の指示により、炭治郎たちは順番に自己紹介を行うのだが!?', '2021/03/15 12:00:00', 66, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1a91b92-132c-471e-82c3-f82239b43b42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e014529-e01f-47c5-9317-cee1826fad8f', '1af325a1-a24a-46de-b8b7-09cb70eef351', 2, '100077592', '鬼滅の宴 特別編 第二話', '体育の授業。そこにはひとり、ハッピーモードでウキウキの善逸の姿があった!!', '2021/03/15 12:00:00', 120, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28ad33d4-84d5-4a57-a00f-4e38569b1c80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1513bcb9-b1be-4ea0-a147-3ad8b4068177', '1af325a1-a24a-46de-b8b7-09cb70eef351', 3, '100077593', '鬼滅の宴 特別編 第三話', 'ある日の朝、風紀委員の善逸は校門で生徒たちの服装チェックを行う。しかし、そこにやってくるのは個性豊かな生徒たちばかりだった。', '2021/03/15 12:00:00', 105, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e1200df-2c69-44a7-bfb2-f64ad6d9d0b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ca480ef-67ee-49d2-a9ad-ff2c9d889b1e', '1af325a1-a24a-46de-b8b7-09cb70eef351', 4, '100077594', 'バレンタイン編 第一話', 'バレンタイン当日。ワクワクして落ち着かない善逸は半年前にあった出来事を振りかえる。', '2021/03/15 12:00:00', 142, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0eab6cb5-bfa0-483c-8fd5-4106901ca810.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7db4dadf-4d83-4fe2-83b1-c42b252f59ae', '1af325a1-a24a-46de-b8b7-09cb70eef351', 5, '100077595', 'バレンタイン編 第二話', 'どうしてもチョコが欲しい善逸は、モテるための秘訣を煉獄先生に続き、今度は冨岡先生に聞きに行くのだった。', '2021/03/15 12:00:00', 95, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ce93366-1086-4995-8000-ffc476dfbcde.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a465d45f-fbfc-486c-b354-fdb66ab41346', '1af325a1-a24a-46de-b8b7-09cb70eef351', 6, '100077596', 'バレンタイン編 第三話', 'モテるための秘訣を聞くため、善逸はさらに続いて宇髄先生の元を訪ねることに――。', '2021/03/15 12:00:00', 188, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14bffd21-0c21-4f83-ac04-c020fa32e2b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0da1f4a6-cdc0-4885-aac1-4a9a24053cc2', '1af325a1-a24a-46de-b8b7-09cb70eef351', 7, '100077597', 'バレンタイン編 第四話', '【シーズン1 最終話】ここ数日、学校の周りに不審者が出るという話が。犯人と思しき人物が描かれたプリントを見た炭治郎は、あることに気づいてしまう――。', '2021/03/15 12:00:00', 195, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac1ad7ce-7073-43d7-9d06-9768901ba7fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('08855b9a-a51e-4d52-b3fa-f7f9ff9e1638', '中禅寺先生物怪講義録　先生が謎を解いてしまうから。', '', 'hulu', 'the-mononoke-lecture-logs-of-chuzenji-sensei-he-just-solves-all-the-mysteries', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/499b5257-dd54-4364-96aa-21cb13937580.png?w=331&h=447&p=t', 'hulu', 2025, 1, 1, 'FINISHED', NULL, 182419, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('998cd38d-6d55-40b2-9483-d9d4cfa71d31', '08855b9a-a51e-4d52-b3fa-f7f9ff9e1638', 'hulu-the-mononoke-lecture-logs-of-chuzenji-sensei-he-just-solves-all-the-mysteries-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dcb60e4-77a8-4d5f-9ca0-69745d0407ef.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd353c5a-1fa8-42f0-8a6e-6930a90bc586', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 1, '100222697', '仏頂面な新任講師', 'まだ戦争の傷跡が残る、戦後間もない頃の東京。新制高校の二年生になった日下部栞奈はある日、友人たちから『図書室の幽霊』の噂を耳にする。旧校舎の図書室に現れる幽霊を見た者は、その呪いにより一ヶ月以内に死に至ってしまうという。その幽霊を目撃してまったと怯える栞奈の友人、幸子。死にたくないと嘆く彼女を放っておけない栞奈は、幽霊の正体を探るため夜の旧校舎へと足を踏み入れることを決意する。そんな矢先、栞奈のクラスに新任の講師が赴任してくる。愛想のかけらもない仏頂面な国語講師……それが中禅寺秋彦だった。', '2025/04/13 02:30:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dcb60e4-77a8-4d5f-9ca0-69745d0407ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('48ddfaac-dc64-44ec-a840-31a74a56593b', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 2, '100222805', '赤い紙 ･ 青い紙', '中禅寺の思惑で、図らずも心霊探偵に仕立て上げられてしまった栞奈。心霊絡みの相談に追われる栞奈は、ある日『赤い紙･青い紙』という学校に伝わる七不思議を知る。中禅寺によれば、それは『赤い紙いらんか、青い紙いらんか』と尋ねられた時に『赤い紙』と答えれば全身血だらけにされ『青い紙』と答えれば全身の血を抜かれてしまう妖怪だという。そんな中、旧校舎の男子トイレで男性生徒が血痕を残して姿を消す事件が発生。果たしてこれは怪異の仕業なのか。一方、事件を調べていた栞奈は眼帯を付けた美青年、榎木津礼二郎と出会う。', '2025/04/20 02:30:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1a53e51-2705-4e61-9670-97fb223116ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('edc1cb14-a978-4574-b139-0dd330c8db42', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 3, '100223522', '青マントの男', '学校内に広まる『怪人青マント』の噂。その姿を見た者は体をバラバラにされ、袋に詰められ持ち去られてしまうという。ある日、栞奈は心霊探偵の噂を聞きつけた同級生たちに、その青マントを退治して欲しいと頼まれてしまう。そんな中、栞奈自身も件の青マントを目撃。更に青マントが落としたと思しき財布を拾う。財布の中身を確認して、険しい顔になる中禅寺。そこに入っていた紙幣は全て偽札だったのだ。この事件に犯罪の可能性を見た中禅寺は、友人の警察官である木場修太郎に協力を要請する。', '2025/04/27 02:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed965594-08a4-4636-bb22-ba0d5741e377.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0923aeb1-2f73-47fa-b4eb-96f480df8395', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 4, '100225387', '真夏の神のいたずら', '今夜は久しぶりの夏祭り。浴衣に袖を通した栞奈はタケ坊たちと共に祭りの夜を楽しんでいた。そんな中、栞奈は執拗な父親の追跡から逃げる少女、綾乃と出会う。彼女が落とした巾着袋を渡そうとそのあとを追いかける栞奈。だが……綾乃は神社の境内で忽然とその姿を消してしまう。そして、綾乃の父は愕然としてこう呟く……『神隠しだ』と。実は、彼の妻である綾乃の母もまた10年前にこの神社で神隠しに遭い、それ以来姿を消しているというのだ。この二つの事件の繋がりは、そして二人はどこへ消えてしまったのか。', '2025/05/04 02:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36fb41c8-3a49-413f-8e44-e2d519080dd2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb074f1e-e4d4-4766-b558-fc63f81eb04b', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 5, '100225388', 'ドッペルゲンガー', '自分とそっくりの人間を目撃したと、花代から相談を受ける栞奈。それが原因で不安になっているという花代を救うため、栞奈はその正体を探ることに。その最中、いきつけの本屋で中禅寺の友人である関口と出会う。栞奈から話を聞いた関口は、その怪現象はドッペルゲンガーではないかと推察する。そして、それは一過的な幻覚に過ぎないものだから心配しなくていいと話す。花代を安心させようと関口の話を伝える栞奈。その言葉により一旦は平静を取り戻す花代だったが、その矢先……彼女は更にありえない光景を目撃し、戦慄してしまう。', '2025/05/11 02:30:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a080efe-a1ae-4b34-ba1e-e9b2eca0fdb7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99e1ee0d-9327-4616-ac9a-ad911cfb7e2b', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 6, '100225835', '開けてはいけない葛籠', '物の怪を詰めた葛籠を背負い、夜な夜な徘徊する兵隊服の男。もしも見つかれば葛籠に閉じ込められ、物の怪の仲間にされてしまうという。不気味な怪異の噂が広まる一方、旧校舎の図書準備室を訪れた栞奈は中禅寺に頼み事をする榎木津に遭遇。ケェキに釣られて栞奈も共に青山にあるジャズバーへ向かうことに。そこで待っていたのは榎木津の兄、榎木津総一郎だった。総一郎は中禅寺に、自分のもとで働いているある人物の調査を依頼する。その後日、お遣いで青山へ行った帰り道、栞奈は件の葛籠の男を目撃してしまう。', '2025/05/18 02:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48f06a3f-e749-40f7-9995-a7445377029b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9aee1ec2-58fa-429e-9b44-a7467d26a308', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 7, '100226741', '化け猫の来訪', 'ある日、栞奈と敦子は一匹の汚れた野良猫と出会う。この野良猫に懐かれた栞奈は、貰い手を探してやることに。汚れを落として綺麗にしてあげれば貰い手が見つかるかもしれない。そう敦子に助言された栞奈は共に中禅寺家へ向かう。千鶴子の友人である雪絵の協力もあり、猫は見違えるように綺麗になり『石榴』と名づけられる。その一方、中禅寺家では別の問題が起きていた。千鶴子が、お気に入りの手鏡をなくして困っていたのだ。それを見た石榴は、突如栞奈たちを案内するかのようにどこかへ走り出した。', '2025/05/25 02:30:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e68299de-afaf-4bd1-85ae-7f5f2bb81846.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd3c5baa-dbed-47a1-a1ba-ca68048a5735', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 8, '100227597', '死神の楽譜', '学校に伝わる七不思議の一つ『死神の楽譜』。その楽譜を見た者は死神に連れ去られてしまうという。ある日、赤点の罰で旧校舎の片づけを命じられた栞奈たちは、奇妙な楽譜を発見する。楽譜の体を成していないデタラメな楽譜に、まさかこれが『死神の楽譜』ではと苦笑する栞奈たち。だが、音楽教師の杉本先生だけは、何故かショックを受けた様子を見せていた。楽譜を見つけて以来、元気がない杉本先生を心配し、励ます栞奈。そんな折、杉本先生が覆面を被った暴漢に襲われてしまう。果たして、これも死神の楽譜による影響なのか。', '2025/06/01 02:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6dcc8237-4a90-4903-882f-639c5ffa2a3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0da38f0d-3880-429e-a5f1-bcb7c9cd7ae0', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 9, '100227598', '幽霊屋敷の噂', '巷に広まる『幽霊が出現するとされる屋敷』の噂。夜中に目を覚ますと不気味な白い人影がこちらをのぞき込み、嫌らしい笑いを浮かべるという。ある日、栞奈はこの屋敷に住む婦人、佐和子のことを雪絵から聞く。街中で彼女と出会った栞奈は、困っているのを放っておけず思わず声をかけてしまう。そして栞奈は心霊探偵と名乗り、事件解決に乗り出すことに。だが、彼女一人ではまるで分からない。そこへやってきたのは、正式に調査の依頼を受けた中禅寺。なりゆきで助手という扱いになった栞奈は、中禅寺と共に怪異の解体に挑む。', '2025/06/08 02:30:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4341ad74-dc32-4b55-a6d7-f65b42ba1279.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa9e25a0-6fda-4b08-a572-fca7d5fe379c', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 10, '100228774', 'ブラウニーのいたずら／サロメの首', '噂が噂を呼び、栞奈の元には今日も怪異に関する相談が舞い込む。まるで、妖精の魔法のように美術室から消えたスケッチブックの行方を追う『ブラウニーのいたずら』。旧校舎をはじめ、様々な場所で目撃される白装束を身にまとった生首を持ち歩く女。その怪異の正体を巡る『サロメの首』。様々な難問を前に頭を悩ませる栞奈。だが、いつまでも中禅寺が答えを出してくれるのを待つ彼女ではない。中禅寺に相談をしながらではあっても、少しずつ栞奈は自分なりに怪異と向き合い、その解決方法を模索していく。', '2025/06/15 02:30:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35cdd5cf-9123-43e9-a097-5246d54ead81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49d2b77f-c893-4314-b2b5-076bc85d5e15', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 11, '100228775', '秋高く乙女頬張る', '寒さが身に染み始める秋。食いしん坊の栞奈は、常日頃から美味しい物を求めることに余念がない。図書準備室で見つけたクッキーを巡る中禅寺との心理戦。何とか中禅寺にクッキーを食べようと言わせるため、栞奈は知恵を振り絞り、あの手この手の戦略を巡らせる。そして、榎木津邸で開催される焼き芋大会。そこに集った中禅寺たちの知恵と力を借りて、栞奈はホクホクの甘い焼き芋を焼き上げるべく奮闘する。美味しい食べ物を前に、栞奈の心と食欲は秋の空のように高まるのだった。', '2025/06/22 02:30:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bab5932c-82a5-439c-ad2d-0ad8e2187ebb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8c86b2c-d112-4abe-a2c4-c754e3f3e40d', '998cd38d-6d55-40b2-9483-d9d4cfa71d31', 12, '100229407', '心霊探偵 栞奈', '【シーズン1 最終話】数々の怪異事件を解決してきたことで、今や栞奈の心霊探偵としての噂は不動のものになっていた。そんなある日、栞奈は学校に伝わる七不思議の一つ『増える階段』の噂が本当か、確かめに行きたいと同級生の霧子に誘われる。噂によれば、深夜十二時に旧校舎の階段を昇ると一段階段が増え、階段を踏んだ者を異界に引きずり込んでしまうという。それを確かめるべく、栞奈たちはタケ坊たちと共に夜の旧校舎へと足を踏み入れることに。深淵の闇が支配する異界を舞台に、心霊探偵栞奈の憑き物落としが、今、始まる。', '2025/06/29 02:30:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47745824-ec63-46dc-82d6-da586adb4602.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f3b4ebe9-80d8-464d-a135-f9758e0a510b', '虫かぶり姫', '', 'hulu', 'princess-of-the-bibliophile', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90d7dd17-664a-4666-bb40-5853ec6db412.jpg?w=331&h=447&p=t', 'hulu', 2022, 3, 1, 'FINISHED', NULL, 144533, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4006cf51-699f-40ee-a831-a40ad48c979e', 'f3b4ebe9-80d8-464d-a135-f9758e0a510b', 'hulu-princess-of-the-bibliophile-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70181ee4-ae2e-4e21-b850-1703e213260e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fdef6b66-356d-4088-af4a-b8c1c6df0a8a', '4006cf51-699f-40ee-a831-a40ad48c979e', 1, '100125915', '見せかけの婚約者', '本好きの侯爵令嬢エリアーナと王太子クリストファーは、お互いの利点のために名ばかりの婚約者同士となる。そんなある日、エリアーナはクリストファーが子爵令嬢アイリーンと仲睦まじく語らう姿を目撃してしまう。ついに婚約解消の時が来たと、覚悟したエリアーナの心は揺れ動く……。', '2022/10/13 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70181ee4-ae2e-4e21-b850-1703e213260e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3af8fc75-8ef1-40f2-aea1-492478641d26', '4006cf51-699f-40ee-a831-a40ad48c979e', 2, '100126789', '一人芝居', '今になってクリストファーへの想いを自覚し、自分の不甲斐なさに落ち込むエリアーナ。クリストファーとアイリーンの親しげな様子から婚約解消も覚悟するが、訪れた王宮内はなぜか物々しい雰囲気に包まれていた。そんな時、大階段を上っていたエリアーナの背後で悲鳴が上がる……!', '2022/10/20 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98fc0dbc-5070-49b0-b0fd-2028d4174997.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c977fe14-4210-4854-908c-fa91953f1feb', '4006cf51-699f-40ee-a831-a40ad48c979e', 3, '100127327', 'そして二人は', 'エリアーナが自らの妃となる者であることを、王宮内で正式に宣言したクリストファー。ここへ至るまでには、ベルンシュタイン家から出された条件や、エリアーナを陥れる者の排除など様々な課題があったが、クリストファーはそれらすべてを解決するために奔走していたのだった……。', '2022/10/27 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08deee8d-d4ba-44ed-9318-1d243e939400.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ba18e09-502b-4a6a-808e-5e636544bc06', '4006cf51-699f-40ee-a831-a40ad48c979e', 4, '100128173', '星の旅人', '世界を旅する学識者の一団「シスルの星」が、サウズリンドで本の市場を開くと聞き、エリアーナとクリストファーはお忍びで出かける。珍しい他国の本が並ぶ光景にワクワクしてしまうエリアーナだったが、その市場で本を盗もうとしていた二人の少年を、成りゆきで助けることに……。', '2022/11/03 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a3eae36-c44e-48d5-b4a4-573fb8474757.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4bd6daa8-d8dc-49a1-93d3-b6c62e3aa5bc', '4006cf51-699f-40ee-a831-a40ad48c979e', 5, '100128615', '王子と彼女の宝物', 'レッツィ博士はクリストファーが婚約者問題に悩んでいた頃、相談に乗ってもらった相手だった。クリストファーは博士に「シスルの星」の長への仲介を頼み、一方のエリアーナはルネに付き添い、仲間の子どもたちに会いに行く。そこで彼らに盗みを命じていた貴族の正体が明らかに……。', '2022/11/10 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c1a9104-d3f2-4102-af75-a112d7ba8f55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e386c34d-94a2-40c2-bb3e-050c51c6bb5b', '4006cf51-699f-40ee-a831-a40ad48c979e', 6, '100129109', '狩猟祭と孤独な公務', '公務でミゼラル公国へ赴くクリストファーに、会えなくなる寂しさをうまく伝えられないエリアーナ。そんな愛しい婚約者のリボンをお守りにして、クリストファーは出立した。留守の間、エイデル領で秋の狩猟祭が開催され、エリアーナはクリストファーの名代をしっかり務めようと意気込む。', '2022/11/17 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37cbc291-bc43-4c85-96e0-0144a1e3f813.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b4d0f4c-1e08-473e-9068-c7e845c429ea', '4006cf51-699f-40ee-a831-a40ad48c979e', 7, '100129669', 'エイデルの亡霊', 'エイデル領主の屋敷に滞在中のエリアーナは、辺境伯令嬢のアンナが高慢なレネックから言い寄られている場に遭遇する。毅然とした態度のアンナに加勢するエリアーナ。そんなエリアーナに対し、テオドールと近衛隊長のジークは、狩猟祭を利用して近づこうとする者がいると注意を促す。', '2022/11/24 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80530c00-af81-4d6d-977d-7dc87412b94f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b802c52-fd55-4823-85ab-cdc954eab167', '4006cf51-699f-40ee-a831-a40ad48c979e', 8, '100130515', '花守り虫と祈りを捧げる使者', 'エリアーナを敵視するソフィアの差し金により、エリアーナは古城でアーヴィンと二人きりにさせられてしまう。だが、アーヴィンに敵意はなく、彼は自らの素性とエリアーナに近づいた理由を打ち明ける。二人の仲がようやく打ち解けてきた時、突然、剣を持った男たちが現れて襲いかかる……!', '2022/12/01 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4bf4606d-8888-4a7c-a596-3b1ffe58ee58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('052d2672-438a-4d5e-9f0b-bc03ae03b6a0', '4006cf51-699f-40ee-a831-a40ad48c979e', 9, '100131151', '真珠姫からの手紙', '成婚の儀に備えて王宮に滞在するエリアーナは、ドレスや装飾品を扱う商会相手に苦労していた。アンリエッタ王妃はそんなエリアーナを厳しく指導しつつ、王家に嫁ぐ者として持たなければならない覚悟についても語る。その言葉は、エリアーナの心に小さな不安を芽生えさせた……。', '2022/12/08 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abf32837-f2fe-43e5-aecf-146dadb75991.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8042c16a-5778-41ba-bae4-c34b04d31b55', '4006cf51-699f-40ee-a831-a40ad48c979e', 10, '100131670', '蝶々たちの思惑', 'ミレーユの存在が気になり、エリアーナはモヤモヤした思いを抱えていた。クリストファーに相談したくても、多忙なためになかなか会えず、すれ違いの日々が続く。側室を巡る不穏な動きもあるなか、エリアーナのもとを訪れたシャロンが口にしたのは、思いがけない要求だった……。', '2022/12/15 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e3c4d55-b009-402d-ad94-75aa174cc89e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1305b2ca-2632-43c2-91dc-718294300f92', '4006cf51-699f-40ee-a831-a40ad48c979e', 11, '100132315', 'お邪魔虫', '気持ちを落ち着けるため、一旦ベルンシュタイン家に帰るエリアーナ。翌日、王宮の私室へ戻ると、以前エリアーナのドレス案を盗用した令嬢マティルダが室内を漁っていた。エリアーナに対して怯まず、自らが側室にふさわしいと開き直るマティルダに、エリアーナが見せた態度は……。', '2022/12/22 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3abf7286-e54a-4a89-a994-2305c08b99ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ef2a38b-dc6f-4820-b4bd-aee2628c69f9', '4006cf51-699f-40ee-a831-a40ad48c979e', 12, '100132673', '蝶々たちの踊る聖夜の祝宴', '【シーズン1 最終話】お互いの気持ちを確かめ合ったエリアーナとクリストファー。だが、ミレーユこそがクリストファーの相手にふさわしいと思うシャロンは、エリアーナに取引を申し出る。そんなシャロンに対し、クリストファーはエリアーナとミレーユについて、彼女が知り得なかった“真実”を語る。', '2022/12/29 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/504ac931-5b07-4069-9713-adf8013cc015.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dbfcebdc-c7ca-4709-b5c6-0a3a589a0c6b', '朝だよ！貝社員', '', 'hulu', 'good-morning-shellfish-employee', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50025773_series_art__338x600_good_morning_shellfish_employee_143dd6044152e0df9364ee3216cce833.jpg?w=331&h=447&p=t', 'hulu', 2016, 1, 1, 'FINISHED', NULL, 121718, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('134250ea-e515-4419-ae39-c9fe5fa893a4', '超人高校生たちは異世界でも余裕で生き抜くようです!', '', 'hulu', 'choyoyu', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02a9fc4d-eabf-4845-8660-4de5406adce5.jpg?w=331&h=447&p=t', 'hulu', 2019, 3, 1, 'FINISHED', NULL, 108388, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', '134250ea-e515-4419-ae39-c9fe5fa893a4', 'hulu-choyoyu-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cdcb5a91-ff1e-4aef-a2a6-08a2fe4df4b8.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0a4252a-b41f-4bc7-8ef5-037f0d2495da', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 1, '100043130', '超人高校生たちは異世界に来てしまったようです!', '世界最高レベルの天才、人呼んで「超人高校生」である御子神司たち七人は、それぞれ、政治、経済、剣術、医療、諜報、科学、マジックの類まれなる才能を持ち、世界を股にかけて活躍していた。ところがある日、司たちは不運にも飛行機事故に遭ってしまう。彼らが目を覚ますと、そこはドラゴンが飛び、獣耳を持つ人々が暮らす「異世界」だった。常人なら取り乱し、混乱するところだが、彼らは超人高校生。異世界だろうが余裕で生き抜くのである。むしろ彼らの心配は、彼らの才能が異世界を混乱させてしまわないかということだった。', '2019/10/03 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cdcb5a91-ff1e-4aef-a2a6-08a2fe4df4b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a22de7f0-96dd-4cf9-94db-f77c81e825f6', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 2, '100043303', '勝人は本気で金儲けをするようです', '司たちは、自分たちを助けてくれた少女、リルルと、彼女が住むエルム村に恩返しをするため行動を開始する。エルム村の人々と打ち解け、親しくなっていく超人高校生たち。ところがエルム村は、北部一帯の商業を牛耳る悪徳商人、ノイツェランド商会によって、貧しい生活を強いられていた。その状況に、真田勝人が立ち上がる。彼は元の世界で「財界の魔王」と恐れられた、世界最高の商人である。商業都市ドルムントを訪れた勝人は、神業のような手腕で瞬く間に自分たちの勢力を作り上げ、ノイツェランド商会との全面対決に挑む。', '2019/10/10 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b86bd0d-ada4-4b9d-ae36-9d62a2c8e262.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('98588f4a-3bdd-4998-a923-ac9b735bacd2', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 3, '100043697', 'ルーは自分の価値を自分で決めたようです!', 'ドルムントで出会った少女、ルーを新たな仲間に加えた勝人たち。卑劣なノイツェランド商会の策をものともせず、勝人は大胆不敵に笑う。一方、エルム村には厳しい冬が訪れようとしていた。皆の身を案じ、一計を講じる司。忍者の末裔で世界最高のジャーナリスト、猿飛忍の働きで、朧気ながらこの世界の情勢が判明する。この世界を支配する覇権国家、フレアガルド帝国。失われた信仰、七光聖教。元の世界に帰る方法を探す司たちだが、謎は深まるばかりだった。そんな時、平和なエルム村に危機が訪れる。', '2019/10/17 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19a6dd73-d74b-4328-b7d7-c27f0e6accca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce9eaa2e-e138-4769-a889-c134847906d7', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 4, '100043941', '司は異世界を変える覚悟を決めたようです!', '世界最高のマジシャン、プリンス暁の機転で窮地を脱するエルム村の人々。だが、この一帯を治める卑劣な領主フィンドルフのもとへ、リルルが連れ去られてしまう。義憤に駆られるエルム村の人々。だが、領主に逆らえば村は無事では済まない。司は政治家としての立場からもっとも犠牲が少なくて済む解決策を村人たちに提案する。それでもリルルを取り戻す、と団結した村人たちに助けを求められた司は彼らに力を貸すことを決心する。司たちは持てる技術と才能を発揮して、領主に反旗を翻す。それは、この異世界の在り方を、根本から変えてしまう事を意味していた。', '2019/10/24 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1aebc6af-afe4-4889-b50b-ae9ffe060f94.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6924d8a4-90ce-4585-a0dc-4f611705beb8', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 5, '100044081', '暁はゴッド暁になるようです!', '圧倒的な科学力を以て、悪徳領主フィンドルフを討ち果たした超人高校生たち。だがそれは、全ての始まりにすぎなかった。七光聖教を名乗り、自らを神の使いとして人々の前に姿を現した司たちは、医療やマジック、マヨネーズを奇跡と称して振舞い、異世界の人々をまとめ導こうとする。その第一歩として、大都市ドルムントを平定する司たちだったが、ドルムント警備隊隊長、バーナードは、司たちのやり方に疑問を覚える。領主が倒されて、フレアガルド帝国が黙っているはずがない。来るべき不穏な未来を憂うバーナード。そんな現実的な視点を持つ彼を、司は高く評価し、仲間として迎えようと動き出す。', '2019/10/31 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba7031dd-61f5-4aec-aa97-f327603694dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45406710-fd4e-4629-ab06-9632ac01b3c2', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 6, '100044312', 'リルルは距離を縮めるようです!', 'ドルムントを拠点に、次々に改革を進めていく司だったが、帝国との本格的な衝突にも備える必要があった。司が懸念しているのは、北部一帯を治める総督、オスロー･エル･ギュスターヴ。彼の使う恐るべき戦略魔法、「天の炎」を、司は強く警戒する。一方、リルルはフィンドルフから助けてもらった礼を、司に言えないでいた。自分を避けているフシもある司に、リルルは正面から向かい合う決意をするが…!? その頃、遠く離れたエルム村では、ルーがある試練に立ち向かっていた。', '2019/11/07 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4e79eb4-a362-4aa1-a9cb-fb6edf3f6957.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87a471c8-82b9-4738-b3aa-25cc082a34ea', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 7, '100044744', '忍はシノビの勘がはたらくようです!', '北部の村、ココノノ村を訪れる忍とエルク。二人は予測に反して、村人から惜しみない歓待を受ける。村は綺麗に整備され、住民は身なりもよく、穏やかな人ばかりであった。全ては北領総督、オスロー･エル･ギュスターヴの統治のお陰、と、彼を賞賛する村人たち。ココノノ村は稀に見る豊かな村だったが、忍はその裏にある、底知れぬ闇を感じ取り、調査を進める。そんなココノノ村に、帝国の騎士団が査察に訪れる。騎士団を率いるのは女騎士、ジャンヌ。情報を入手するために、忍がとった手段とは…。', '2019/11/14 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7465ca4c-959b-45e8-aeb9-3b2f8e5e8562.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4486e330-9eed-449c-8a22-875366d633bf', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 8, '100045350', '葵は想像以上のスペックを発揮するようです!', '七光聖教の存在に激怒するギュスターヴは迸る怒りのそのままに、天の炎、ラージュソレイユを解き放つ。突然の攻撃に混乱を極めるドルムント。そんな状況にあって、司は落ち着き払っていた。全ては想定していたこと。皆が為すべきことを為せば、必ず切り抜けられるはず。司が作成した避難計画によって、ドルムントは最悪の被害を免れる。だが、天の炎は止まらない。放たれた炎の精霊たちは、街を焼き尽くさんと攻撃を続けていた。ミサイルも効かない窮地に立たされた時、世界最高の剣豪、一条葵が名乗りを上げる。', '2019/11/21 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dc2ee90-baa2-4aa9-9172-05bc78bf86b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24730a0a-2ee8-4dfa-b7c1-47dd6f765a0b', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 9, '100045825', '司は全てを見通しているようです!', 'ギュスターヴの天の炎を、辛くも破る司たち。七光聖教を危険だと判断したギュスターヴは、すぐさま進軍を命じる。ギュスターヴの命を受け、七光聖教を制圧せんと進軍するアークライド侯爵。七光騎士団は厳寒の冬山で、その軍勢と激突する。その頃忍は、ジャンヌが属する反帝国組織「碧の団」と合流していた。ギュスターヴによる全軍招集の報を受け、一斉蜂起の好機、と見た碧の団はギュスターヴの総督府を包囲する。降伏を呼びかけるジャンヌ。だがギュスターヴは、皇帝への妄執じみた忠誠を胸に、ジャンヌと忍に猛然と反撃を開始する。', '2019/11/28 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccf1301b-329b-4c1f-a418-b8cc68377ac3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c38f1bd-8298-4d09-a085-3aee18d097ea', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 10, '100046315', '林檎は勇気を出して狩人になるようです!', 'ギュスターヴを退け、北部全体を手中に納める七光聖教はもはや帝国全土から見ても、危険な存在となった。これから帝国との戦争が本格化し、忙しくなるだろうと思った矢先、司と林檎は「働きすぎだ」とドクターストップがかけられる。休養を命じられた司は、休息の合間に、一緒に街を散策しようと、林檎に提案する。それはつまり、デートなのでは? 世界最高の科学者である林檎だが、恋愛に関しては無知で無力だった。仲間たちに相談するが、林檎の不安と混乱は全然消えない。そんな林檎に、忍は秘策を授ける。果たして二人のデートの結末は?', '2019/12/05 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2fe3c92c-66a8-4ed7-b22f-71400185db3a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e252591-cb3a-4198-ab39-9d566d8e060b', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 11, '100046961', '桂音は悪い子を決して許したりはしないようです!', '「あるもの」の開発に集中する林檎。司もまた、その開発を頼んだ責任の重みを一身に受け止める。情報収集を続ける忍は、碧の団の不審な動きを掴み、ジャンヌの身を案じていた。一方、街では病が流行していた。異世界の医療では手の施しようがなく、司たちの準備した医薬品も不足している中、患者は死に至る病で苦しんでいる。患者を救うことのできない七光聖教を侮辱する地元の医師会に怒る暁。彼の心意気に応えるように、世界最高の医師、神崎桂音は、薬を作り、患者たちを救うと宣言する。', '2019/12/12 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5991a9f-9619-4641-81b8-2bff97756248.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e69ba46-a3e5-4462-affd-6c18c4a04f70', '5bf18a34-1a41-4a96-b1fd-e7f880a3cacf', 12, '100047499', '超人高校生たちは異世界でも余裕で生き抜くようです!', '【シーズン1 最終話】ジャンヌの窮地を救った忍はジャンヌの意志を受け止め、彼女を七光聖教に招き入れる。一方、帝国元帥ネウロ秘蔵の魔導士、タンガニカは、隠されていた実力をついに現す。まき散らされる破壊と破滅。それは帝国の力を示すに十分なものだった。それに対抗し、世界最高の政治家、御子神司は、かねてから用意していた策を発動する。それは、異世界における革命の始まりを告げる狼煙となった。「帝国を打倒し、革命を起こす」。集まった群衆を前に、司は新たな世界、新たな国の姿を語る。', '2019/12/19 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fec666c2-b96d-44fa-a2b7-c2ea9d7d2b23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6a62b78b-e20f-4e9a-b77b-ce371b865e10', '追放者食堂へようこそ！', '', 'hulu', 'welcome-to-the-outcasts-restaurant', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffe52c50-fe1f-41a0-9a3c-77391a897ba0.png?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 185544, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6e6f4207-90ea-41c3-ac33-b911d629a753', '6a62b78b-e20f-4e9a-b77b-ce371b865e10', 'hulu-welcome-to-the-outcasts-restaurant-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f96c0ca-a65f-475d-a7b3-86eccc49b761.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a7b14a3-9fef-4877-b9c3-856dd5e52372', '6e6f4207-90ea-41c3-ac33-b911d629a753', 1, '100231885', 'お前は自由だ', 'クエスト失敗の責任を負わされ、超一流冒険者パーティー「銀翼の大隊」を追放された料理人･デニス。料理人としての夢だった食堂を開くため奔走する中で奴隷商に売られていた少女･アトリエと出会う。彼女の瞳の中にかつての自分を見たデニスは、持ち金をはたいてアトリエを引き取ることに。 パーティーから追放された料理人と傷を負った少女。ふたりで開く「冒険者食堂」の行方は果たして――?', '2025/07/06 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f96c0ca-a65f-475d-a7b3-86eccc49b761.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b200b75c-f286-46d5-993b-2f6ac339ccdc', '6e6f4207-90ea-41c3-ac33-b911d629a753', 2, '100231886', 'めっちゃおいしいです!', 'ついに迎えた冒険者食堂の開店日。最初のお客は、なんと全身 (フル) 甲冑 (プレート)!? その正体は、女剣士･ヘンリエッタだった。困窮する彼女を見かねたデニスは、かつ丼を振る舞いパーティー探しも手伝うことに。無事ヘンリエッタにパーティーを紹介することができたデニスだったが、きな臭い噂を耳にしてしまい……。不安を抱えるデニスを尻目に、既にヘンリエッタは新たな仲間とダンジョンへ向かっていた――。', '2025/07/13 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d017ba3-0476-40ce-8680-634bacb33ffe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3d9061d-ec29-4ae5-a80a-5142a2c8ffad', '6e6f4207-90ea-41c3-ac33-b911d629a753', 3, '100231887', 'それが冒険者だ!', 'ある日食堂に現れたのは意識高い系の少年･ビビア。彼はその意識の高さと態度が原因で仲間に嫌われ、パーティーを追放されていた。後日、街最強のパーティー「夜の霧団」へ加入したことをデニスに報告するビビアだったが、次に挑むというダンジョンは明らかに実力と見合わない危険な場所で……。『次はカニ炒飯を食べに来ます』と心配するデニスをよそに、ビビアは笑顔で食堂を後にするが――。', '2025/07/20 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec8f5a5c-fac1-4bac-bb33-683d1013819c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1dec6984-a5ba-4733-a1f9-eadf6039d69d', '6e6f4207-90ea-41c3-ac33-b911d629a753', 4, '100231888', 'じゃあ、日替わり定食で', '「夜の霧団」所属の魔法使い･バチェル。彼女は大量の仕事や理不尽な叱責により心身ともに疲れ果てていた。ふと冒険者食堂へと訪れたバチェルは、デニスや常連達が作り出す温かい空間に心が緩み涙が溢れてしまい、あろうことかろくに食事もせず帰ってしまう。その後もうまく寝付けなかった彼女だったが、翌日のクエストで起きた出来事をきっかけに、その心は限界を迎え……。', '2025/07/27 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffc6a00c-b06f-4048-be2b-221e5812b892.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1879cef-d2ce-4c82-9ccd-5c76da84052c', '6e6f4207-90ea-41c3-ac33-b911d629a753', 5, '100231889', 'プロポーズなんて早すぎるだろ!', '後衛の要を担っていたデニスがいなくなり、「銀翼の大隊」は崩壊の危機に瀕していた。「銀翼の大隊」存続のため、副隊長のケイティはデニスにパーティーへの復帰を持ち掛けるも、きっぱりと断られてしまう。一方、冒険者食堂は常連客も増えて大繁盛! ……なのだが当のデニスはとある悩みを抱えていた。それは「アトリエにボーイフレンドができたかもしれない」という疑惑で……!?', '2025/08/03 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06f96d5f-e1c2-4099-bf05-01206980e0dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e68ba503-5e9e-4cac-a607-350fdd338918', '6e6f4207-90ea-41c3-ac33-b911d629a753', 6, '100231890', 'アトリエお嬢様お迎えに上がりました', '突然デニスとアトリエの前に、ワークスタット家の執事長･スティーブンスが現れる。彼は王立裁判所の依頼を受け、アトリエを迎えにきたという。混乱するデニスたちに彼が語ったのはアトリエの生い立ちと壮絶な半生。そして、今は亡きアトリエの父が残した遺言状が発見され、その血筋の正統性を巡る再審が王都で開かれるということ。王都へ戻ることを恐れるアトリエだったが……?', '2025/08/10 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c784c468-f985-4bf5-bb0f-b19e0d4d62be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2aa1b30a-781c-4481-ba69-d54daf6a1d9c', '6e6f4207-90ea-41c3-ac33-b911d629a753', 7, '100234883', '早く、良くなってね', 'アトリエが相続した魔法書の噂を聞きつけ、賢者や魔法使いたちが続々と来店! 冒険者食堂は空前の賑わいを見せていた。店の切り盛りのみならず、さまざまな騒動で疲労を募らせていたデニスは、ついに体調を崩してしまう。高熱にうなされる中、デニスは子供のころの思い出を夢に見る――。一方、ヘンリエッタ、ビビア、バチェルはデニスのためにお粥作りに挑むもなんと全員料理経験ゼロで……。', '2025/08/17 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56e92e9b-56ee-44fb-8f5c-663da4c2eab9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0a5b63e-48d3-40ab-b344-24dd6e68050b', '6e6f4207-90ea-41c3-ac33-b911d629a753', 8, '100234884', '本日、所用につき臨時休業', '大荷物を抱え街中を楽しげに歩くヘンリエッタとビビアの姿があった。街の人たちは『2人がランチ時に食堂にいないなんて珍しい』と不思議がるが、実は今日は常連3人の門出を祝う宴の日。みんなで温泉に浸かった後、始まったのはバーベキュー! それぞれの今後を報告し、楽しい時間を過ごすデニスたち。しかし、楽しむ彼等を尻目に臨時休業中の食堂には怪しい影が近づきつつあった……。', '2025/08/24 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75e112fe-3705-46be-aab9-14fc34d66a76.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc73e7e5-4f8e-460f-9de8-c5ab96a16d3e', '6e6f4207-90ea-41c3-ac33-b911d629a753', 9, '100234885', '大事なものなら、手放さないでください!', 'ヴィゴーとジョゼフ、そして「夜の霧団」の陰謀によって冒険者食堂は焼失。焼け落ちた瓦礫の中、さらなる報復によって常連客たちが危険にさらされることを恐れたデニスは全てを諦め、アトリエと街を離れようとする。しかし、2人の前に立ちはだかったのはヘンリエッタ、ビビア、バチェル、そして街の住人たちだった。『大将、ここがあなたの居場所なんです! 』仲間の熱い思いに触れたデニスの決断とは――!?', '2025/08/31 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d52e383-7fcb-4fc0-9d3b-e9f456f17202.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58eba31c-e85d-4f36-889e-11a45e7f9219', '6e6f4207-90ea-41c3-ac33-b911d629a753', 10, '100234886', 'より遠く、遥かに高いところこそ、俺の目指す場所だ', 'ケイティやジーンの協力により、ヴィゴーやジョゼフらの会合について情報を得たデニスたちは、決戦に向けて着々と準備を進めていた。一方、ヴィゴーは馬車に揺られながら自らの足跡に思いを馳せる――。最底辺の奴隷身分から這い上がるため、自らを鍛え、他者を陥れ、利用できるものをすべて利用してきた過去。そして、ヴィゴーは歩みを進める。すべては、更なる高みへ至るために――。', '2025/09/07 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f76e539-343f-4ae5-b27f-63c0b8eb4456.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('92b8b9fc-8d79-470a-bffe-e34e758f991b', '6e6f4207-90ea-41c3-ac33-b911d629a753', 11, '100234887', '最後のピース?', 'チーム「追放者食堂」の作戦により、数々の悪行が暴かれたヴィゴーたち。王国の法を担う魔法使いや賢者らに会話を聞かれ、もはや法の裁きから逃れる術はない。『あえて言わせてもらおう、ざまぁみろヴィゴー! 』――デニスによる追い打ちに、怒りを爆発させたヴィゴーが絶叫とともに襲いかかる! かつて同じパーティーで冒険をしてきた重剣士と料理人、Lv.99同士の予測不能な真剣勝負が幕を開ける――‼', '2025/09/14 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20a1652e-c5bb-4af7-8a8f-4717d3a356b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('731903a9-ef98-4f7e-834d-b3f3b182195f', '6e6f4207-90ea-41c3-ac33-b911d629a753', 12, '100234888', '追放者食堂へようこそ!', '【シーズン1 最終話】ヴィゴーのとどめの一撃が迫り、デニスの健闘もむなしく勝負が決しようとした瞬間、デニスの足元から七色の光が立ちのぼり、全身を駆け巡る。『あいつらの笑顔を守れる、最強の料理人に……』――ついにデニスは最後のピースを掴む! 光に包まれたまま、真っすぐヴィゴーを見つめるデニスは、肉切り包丁を大きく振りかぶり、ユニークスキルを発動! 全てを乗せた渾身の一撃が、今、放たれる――!', '2025/09/21 22:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d9ca86f-8065-497c-abd7-32d9dd38248a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1d956e5d-a6e6-4e17-977b-1f204af04cb6', '痛いのは嫌なので防御力に極振りしたいと思います。', '', 'hulu', 'bofuri', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39739e2d-6cc7-4f2f-87aa-4107b048c5cb.jpg?w=331&h=447&p=t', 'hulu', 2020, 0, 1, 'FINISHED', NULL, 106479, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('de234bbe-69c2-4989-ad77-071eb71e66bc', '1d956e5d-a6e6-4e17-977b-1f204af04cb6', 'hulu-bofuri-s1', '第1シーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f4be544-c0ec-4d51-8142-293a9f893af3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ba428c3-e597-421d-b333-c8356f364cd4', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 1, '100048541', '防御特化と初戦闘。', '友人の理沙に誘われ、最新ゲームであるVRMMO『NewWorld Online』をはじめることにした楓。自身のキャラ名をメイプルとし、ダメージを受けるのは嫌だからと全ステータスポイントを防御力に極振り! 力もなければ走りも遅い、敵の攻撃も避けられない―そんなありえないシチュエーションを逆手に取って、次々とレアスキルをゲット! 防御力特化の新米冒険者･メイプルの物語が、いま幕を開ける!', '2020/01/15 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f4be544-c0ec-4d51-8142-293a9f893af3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64ca9e1b-ba11-4859-ac79-bee40a76df44', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 2, '100049099', '防御特化とお友達。', '毒竜を倒し、レアな武具とスキルを手に入れたメイプル。防御力がさらに高まり、持っていたスキルも強化。意気揚々と最初のイベント、プレイヤー同士のバトルロイヤルに挑む。そして、楓を誘った張本人の理沙も、サリーとしてついにゲームに参加することになり…。', '2020/01/22 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa8e0e36-f903-4b58-a12e-dc508520df52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c7db988-2a27-4f32-b054-e0abb533462c', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 3, '100049352', '防御特化と二層攻略。', 'カフェで出会った上級者プレイヤーのドラグ、ドレッドに教えてもらい、サリーと共にさらなるレアスキルの習得に向かうメイプル。しかし、思わぬところでサリーの弱点が露呈してしまう。クエストをこなし、レベルとスキルを上げながら、メイプルたちは次なる第二階層へと向かう。', '2020/01/29 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30a10b7b-fdaa-45cd-82a7-b20ebfadf9a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2dd98d9a-c2bd-4787-b289-4d291117d408', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 4, '100049911', '防御特化と第二回イベント。', 'いよいよ始まった第二回イベント。イズ謹製の新装備を手に、銀のメダルを求めてフィールドを探索するメイプル。サリーと共に向かった雪山の山頂で、顔見知りの冒険者のクロムと邂逅。しかし、その先にはイベントボスモンスターが待ち構えていた。氷を自在に操る巨大な怪鳥がメイプルたちに襲い掛かる!', '2020/02/05 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7ce3446-1185-4b0c-83a2-6009ef1446b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac0dbf73-aa8b-4f1e-a607-8fe70d59a676', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 5, '100050446', '防御特化と戦利品。', '突如、和装のプレイヤー･カスミに勝負を挑まれたメイプルとサリー。しかしメイプルの引き起こしたトラブルで、3人とも地下ダンジョンへと飲み込まれてしまう。さらに呪いのアイテムで、一緒に行動しなければならない制約を受けてしまったため、一時休戦。協力してダンジョンからの脱出を試みるのだが…。', '2020/02/12 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac938322-d1df-4436-b4c3-7a651ea597f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ceb278b2-6ebc-4755-98e6-c5dfb67b2853', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 6, '100050810', '防御特化と新戦力。', '新たにゲームに実装されたギルドを作ろうと、イズやクロム、前回のイベントで知り合ったカスミやカナデを勧誘するメイプル。次なるイベントに向け、もう少しメンバーが欲しいと思うメイプルは、双子のプレイヤー･ユイとマイに出会う。ところが二人とも、攻撃力にステータスを極振りしてしまい、まともに戦うことのできない初心者だった。', '2020/02/19 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90238d6b-5fbb-4c81-8121-bca3131c5de5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0cb50f52-fbc7-4f95-9d11-0ea09a6dd3e1', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 7, '100051077', '防御特化と強化。', 'メイプルをマスターに置くギルド『楓の木』。ユイとマイのレベル上げに付き合って、メイプルはひたすらボスを狩り続ける。サリーたちもイベントに向けての準備に余念がない。久しぶりに一人になったメイプルは、とあるクエストに挑戦するが、思いがけない展開に。', '2020/02/26 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8fc8929a-6a04-48a6-b4da-8b603f70b215.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c6512e1-4339-4ad7-ba2f-16b3cebd4dc3', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 8, '100051294', '防御特化と第三回イベント。', '第三回のアイテム集めイベントに苦戦するメイプル。平和なアイテム回収と思いきや、サリーたちが心配したとおり、メイプルはまたも誰もが予期しない展開に。転移の魔法陣を抜けた先、そこに現れたのは、なんと隠しボスの悪魔! 丸呑みにされてしまったメイプルは、悪魔の胃の中で溶かされていくのだが…。', '2020/03/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbee4bc5-e64a-4896-bd86-b82388f0609f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccf8793e-eccd-4450-af99-71ba497a93a2', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 9, '100051766', '防御特化と第四回イベント。', '悪魔の力に加え、超強力なスキル『機械神』も得たメイプル。とうとう始まる第四回イベントのギルド対抗戦に向け、メイプルたちは意欲を燃やす。しかし、最強プレイヤー･ペインの率いる『集う聖剣』、あるいはカリスマ力No.1のミィがギルドマスターの『炎帝ノ国』など、有力ギルドは多数。メンバー数では遠く及ばない小ギルド『楓の木』が立てた作戦は―。', '2020/03/11 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de441945-52db-4b01-b7a0-df50af3c9516.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bbe4ef56-23ee-430b-9ecc-82d1ab2b57ed', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 10, '100052278', '防御特化と出撃。', 'スキルや能力がバレる前に、先行逃げ切りを図るメイプルたち。少数精鋭での奇襲により、次々とオーブが集められる。だがやはりギルド対抗戦、一筋縄ではいかない。カスミの前には『炎帝ノ国』のシンが、サリーの前には『集う聖剣』のフレデリカが立ちはだかる。そして拠点を守るユイとマイたちにも、侵略者の影が近付いてくるのだった。', '2020/03/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5686d1e-4729-4523-9f34-7f83a6196c63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f375ab3b-1af7-4ff1-ac6f-d82c8d57fd38', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 11, '100052974', '防御特化と強敵。', '『炎帝ノ国』との闘いを優位に進めるメイプルたち。だが、その最中、ギルドマスターのミィが駆けつける。強力な炎の攻撃でメイプルを圧倒するミィ。全力で立ち向かうメイプルだったが、『炎帝ノ国』のメンバー･マルクス、ミザリーたちの足止めを受け、ミィの放った炎の檻に捕われてしまう。', '2020/03/25 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db0a6918-726c-4e0c-bae1-188a00b63a8d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba932e70-9c59-4584-909e-d4584b699852', 'de234bbe-69c2-4989-ad77-071eb71e66bc', 12, '100053222', '防御特化とつながり。', '【第1シーズン 最終話】大ギルドの利点を捨て、『楓の木』に少数での奇襲を仕掛けた『集う聖剣』のペインたち。だが、そんな最強プレイヤーを迎え撃つメイプルたちも、ここまで来た以上、一歩も引くわけにはいかない。トップクラスのスキルが応酬するパーティーバトル。ペインの剣技に翻弄されるメイプルは、耐え続ける中、勝機の一瞬を狙う。', '2020/04/01 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83bd261e-fb80-4036-aba7-8eec596222de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ec84e53c-f88e-4b33-87d7-92df19e66de0', '痛いのは嫌なので防御力に極振りしたいと思います。2', '', 'hulu', 'bofuri-i-dont-want-to-get-hurt-so-ill-max-out-my-defense-season-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02e0f86f-dc62-472d-b200-bee6a002989c.jpg?w=331&h=447&p=t', 'hulu', 2023, 0, 1, 'FINISHED', NULL, 116867, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 'ec84e53c-f88e-4b33-87d7-92df19e66de0', 'hulu-bofuri-i-dont-want-to-get-hurt-so-ill-max-out-my-defense-season-2-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79b4678b-29f6-445f-b164-143161647371.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2696904f-b5fe-428e-ad12-465cfcfd9946', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 1, '100135049', '防御特化とクリスマス。', '季節はクリスマスシーズン。『NewWorld Online』では四層が解放され、さっそくメイプルたち【楓の木】も新しい階層へと向かった。探索で街を歩いていたメイプルは、【炎帝ノ国】のギルドマスター･ミィが、変装してこっそりとあるお店に入るところを見かける。一方、探索中に怪しげな妖刀を見つけたカスミは、その効果を試してみるが……。ストレスフリーなメイプルの冒険が、いま再び幕を開ける!', '2023/01/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79b4678b-29f6-445f-b164-143161647371.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6335bf1b-0cf2-4355-872a-cbe40c0ad4c8', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 2, '100135410', '防御特化と五層と六層。', '五層が実装され、四層のボスと戦うサリーたち。無事に倒すものの、そこにメイプルの姿はなく。……実は風邪を引いていたため、ボス戦に参加できなかったのだった。五層に行くために改めてボスを倒さなければならないメイプルは、あえて一人で挑んでみることに。強敵との戦いに苦戦しながら勝利するが、なぜか五層への道は開かない。疑問に感じていたメイプルに衝撃の通知が届くのだった。', '2023/01/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad26ce7e-42aa-4811-aa98-c38d10dc1bb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cab53bc7-c16e-4fad-860a-32ad77a0733d', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 3, '100135810', '防御特化と第七回イベント。', '幽霊や人魂といったゴースト系モンスターが多く出現する六層。とあるクエストで新しいスキルを手に入れたメイプルは、前々から約束をしていたミィと一緒にレベル上げに行くことに。メイプルのサポートを受けながら、強力なスキルや魔法を展開させ、圧倒的な強さを見せるミィ。戦いを終えた二人は、カフェでお茶をしながら、次に開催される第七回イベントについて話をする。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a175d8c8-3599-40a1-97e5-c90154e69a54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8fc3af8-6ac2-4fcd-8db5-0f6e8ae64da4', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 4, '100136321', '防御特化と塔攻略。', 'サリーと共に第七回イベントに挑戦中のメイプル。各階ごとに地形の変わる塔型ダンジョンを昇っていく。だが五階は幽霊系モンスターがいる階。別行動中のクロムたちもホラーが苦手なサリーを案じていた。怖い一方、ペインやミィといった高レベルプレイヤーたちも次々と塔を攻略していく。そしてようやく最上階へと辿り着いたメイプルとサリーの前に現れたのは……。', '2023/02/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb35e2a8-797e-4192-9610-e0b2e2441289.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7304221-de6c-4b07-9bc7-ade869364eaa', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 5, '100137159', '防御特化と触手。', 'イベントのクリア報酬で新たなスキルを手に入れたメイプルたちは、イベント終了後間もなく解放された七層へと向かう。訪れた七層はモンスターの楽園のようなエリア。どうやらゲーム内に新要素が追加され、モンスターをテイムできるらしい。既にシロップや朧のいるメイプルとサリーは、まだテイムモンスターのいない他メンバーのサポートに回ることにするのだった。', '2023/02/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25899bcb-432e-4c2b-a110-f644f8d91842.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9b9cb9c-76eb-435c-9d8e-8dd22ae49b1f', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 6, '100137871', '防御特化とテイムモンスター。', '無事、モンスターをテイムできたカスミとマイ、ユイ。皆をサポートしていたメイプルは新たなスキルを習得し、触手を出せるようになった。クロムやカナデ、イズの三人は、自分の能力とぴったり合うモンスターを求め、七層を探索する。ミィとレベル上げに向かっていたメイプルは、イズから素材集めの協力を依頼され、三人でダンジョン攻略へと向かうのだった。', '2023/02/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b48cb4a-0f89-439b-8511-d6196eb8c1de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55f964e7-5a8e-4315-8bfb-a7149b860900', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 7, '100140149', '防御特化と宝石探し。', 'フレデリカにテイムしたモンスターを見せてもらったり、第八回イベントが告知されて胸を躍らせたりしつつ、久々に二人で探索することにしたメイプルとサリー。七層の探索を続ける中、羊に跳ね飛ばされたメイプルは、とある泉で不思議な宝石を手にする。アイテムの説明欄を確認すると、それは『白の鍵』と呼ばれるものだった。どうやら何かのクエストが発生してしまったようで……?', '2023/03/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dee073c3-aa62-4c99-aca6-f1521dc0be20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3168231e-535f-4c14-8bef-a1d399b62372', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 8, '100140778', '防御特化と第八回イベント。', 'シロップと朧を進化させることができたメイプルとサリー。二匹に新しいスキルを獲得させるため、レベリングに勤しむのだった。やがて始まった第八回イベントは予選と本戦に分かれており、まずは予選に挑むメイプルたち。モンスターを狩ってポイントを稼ぐシンプルなものと思いきや、今回のイベント特有の仕様で、モンスターを倒すたびに様々なバフやデバフがかけられるというギミックがあった。', '2023/03/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fc53516f-4d85-4860-8cb7-53d3afbd43da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05c95937-e0bf-4e46-a1a4-68a28285c357', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 9, '100141198', '防御特化と拠点作り。', '第八回イベント本戦に進むメイプルたち。イベント中にレアドロップする銀メダルは、ギルド内で共有できるとのことだった。効率を考え、二手に分かれることにしたメイプルたち【楓の木】メンバーは、メダルを持っていそうな強力なモンスターと戦いながら、順調にイベントを進めていく。本戦はゲーム内時間で3日間あるため、休憩ポイントが必要と考えたメイプルたちは拠点を作ることに。', '2023/03/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b378982-a67a-431b-b98c-d1abea02b47b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0537257f-25be-4549-99ea-8701d3a7c7b7', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 10, '100141865', '防御特化と新コンビ。', '第八回イベント本戦2日目を迎えるメイプルたち。みんなで作った拠点で一夜を過ごして外に出たところ、まるで夜が明けていないかのように辺りは真っ暗。しかもマップも開けなくなっていた。そして突然、メイプルたちはバラバラの場所に転移させられてしまう。メイプルたちと合流を果たそうと、単身でモンスターと戦っていたサリーは、助太刀に現れたフレデリカと共闘することに。', '2023/04/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2688ba44-fd61-4631-b0a9-2c167183a8ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bbbc0737-f087-4c97-be20-0e2a1cd6cac0', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 11, '100143736', '防御特化と新パーティ。', '【楓の木】の拠点に【集う聖剣】、そして【炎帝ノ国】の主要メンバーも合流。メイプルやペイン、ミィたちは4つのパーティに分かれ、引き続きイベント攻略に乗り出す。時間経過とともに狭くなっていくフィールド。強力なモンスターの出現。イベント特有の様々な仕掛けの中、普段はライバルである他ギルドメンバーたちが仲間であることを心強く感じながら、メイプルたちは奮闘する。', '2023/04/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c083081b-572b-40ba-9d62-a129b311c72f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d841753-65fc-4e56-8ff4-107ff5f97a78', '1454cea0-0a6b-43ab-add2-d0b9eb3ec93d', 12, '100144386', '防御特化と大決戦。', '【シーズン2 最終話】イベント最終日、ついに運営の虎の子である超巨大なモンスターが出現。その強さにやられそうになった他プレイヤーたちを助けようとするメイプル。彼らとも協力してモンスターに立ち向かおうと、ペインやミィも賛同。【楓の木】、【集う聖剣】、【炎帝ノ国】が率先して超巨大モンスターへと挑む。これまで培った技術やスキルを駆使し、戦うメイプルたちの大決戦の行方は――!?', '2023/04/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47b56ffb-70dc-4985-9664-b36309edb12e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('19b73846-5ec3-42b6-a495-46e7dd14235a', '帝乃三姉妹は案外、チョロい。', '', 'hulu', 'dealing-with-mikadono-sisters-is-a-breeze', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed715e5b-cdb6-4fe1-99a1-fe097f378d4c.png?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 178886, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', '19b73846-5ec3-42b6-a495-46e7dd14235a', 'hulu-dealing-with-mikadono-sisters-is-a-breeze-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e539236-540c-4e28-a93d-bdb0460d242b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bdaf263a-0403-4370-9314-c02b89d42626', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 1, '100232312', '「天才と、凡人。」', '才能あふれる生徒たちが通う才華学園。各学科のトップには、“三帝”と呼ばれる天才が君臨している。そんな学園に転入した綾世優は、天才大女優の息子でありながら、超のつく凡人だった!? 優が居候することになったのは、なんと“三帝”である帝乃三姉妹の家。困惑する優だが、かつて母が願った“幸せな家族”を目指すため、凡人なりに天才三姉妹との距離を縮めようと奮闘する。', '2025/07/10 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e539236-540c-4e28-a93d-bdb0460d242b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96ffee74-9e06-4877-bc3e-68e02cb5798c', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 2, '100232933', '「彼女の、秘密。」', '帝乃家の父親から、三姉妹の助けになってほしいと頼まれる優。まずはお互いのコトを知ろうと思い、三姉妹と一緒にご飯を食べることを計画する。三姉妹それぞれのために栄養バランスを考えた料理を作り、二琥と三和の“餌付け”に成功する優。だがしかし、一輝だけは頑として優の料理を食べようとしない。なんとか一輝に料理を食べてもらいたい優は、二琥や三和を頼って一輝の攻略法を探ることにするが……。', '2025/07/17 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b7ac33e-5434-46a8-8f50-855b12c56a74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0c36763-45a9-4a5d-9c31-2dbc5fa7cc1b', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 3, '100233374', '「家族に、なりたい。」', '念願叶って三姉妹と一緒に四人で食卓を囲むことに成功する優。幸せな家族について改めて思いを馳せた優は、三姉妹に「一緒に幸せな家族になりたいんです!」と初めて宣言する。そんな中、子供の頃の三姉妹の写真を見つける優。写真の中の三姉妹は、とても仲が良さそうで楽しそうな笑顔。自分が三姉妹と仲良くなることばかり考えていた優だが、家族として三姉妹の仲も考えねばと思い至り、ある作戦を実行に移す……。', '2025/07/24 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0cf00216-651f-48ab-b610-baf2d2d09bee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94771be4-9b02-42e0-9fab-4d73e4977eea', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 4, '100233915', '「三人の、思い出を。」', '三姉妹水いらずで夜桜祭りを楽しんでもらおうとする優。一輝がファンに取り囲まれて三姉妹がバラバラになってしまったり、優がたった一人で三姉妹の思い出作りのために奮闘したりと様々なハプニングはありつつも、無事にお祭りを楽しむ4人。めでたしめでたし――と思いきや、自室の予約を忘れていた優は泊まるところが無い。三姉妹の提案で、狭いホテルの一室に優も一緒に寝ることになってしまい……!?', '2025/07/31 01:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95fa568e-e466-4c2b-8d6c-0d7c155c812c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae3af204-4673-4bc7-a4d8-f205a1546d67', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 5, '100234641', '「父の、教え。」', '夜桜祭りを経て仲が深まった三姉妹。そこへ、三姉妹の父親が帰宅する。祭りに行ったことが父にバレてしまい、「帝乃家に馴れ合いはいらん!」と叱責される三姉妹。優が来る前の生活に戻ろうとする三姉妹だが、三人共どこか寂し気な様子……。一方の優も、幸せな家族を目指すなんて自分勝手だったと反省する。だが、天才だった母こそが最も幸せな家族を望んでいたことを思い出し、自分にできることをやろうと立ち上がる。', '2025/08/07 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80123d66-62d3-4d58-b438-d80b50861c7e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cbb79c42-5c21-4cc9-acaa-801a7061a0bd', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 6, '100235044', '「これは、デート。」', 'ヒロイン役の役作りのために、優をデートに誘う一輝。デートを通じて、普段慣れない女役の心情を掴もうという作戦らしい。それを聞いた優は、「一輝さんのために最高のデートを用意します!」とやる気満々! デート当日、ヒロインらしく振舞おうとする一輝だが、つい逆に優をエスコートしてしまう。失敗続きのデートに落ち込んでいく一輝を、優は最後のデートプラン――告白の名所である観覧車へと誘う。', '2025/08/14 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6134e453-75a0-4edc-af7c-4bfd8f357f64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb40a64e-5eb8-4736-9e55-9705df459f1d', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 7, '100235414', '「本当の、理由は。」', '優と三姉妹の前に現れたのは、高校空手界のトップ巌山高校のエースにして主将――天才空手家･龍巳ハヤト。ハヤトは二琥に会うなり、「二琥、迎えに来たぞ」と告げる。意味が分からず「!?」となる優。ハヤトは二琥と同じ道場の先輩で、二琥を引き抜きに来たのだと言う。巌山高校は全寮制。今の生活を失いたくない二琥は即答できずに困惑する。優に対して、精一杯の決意で「……一緒に、いたいんだ」と告げる二琥だが……。', '2025/08/21 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fed30e0-2f9a-49cb-9630-4d3dfac28c98.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2c1dd6d-047e-4911-abc4-6cdd92b445be', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 8, '100236105', '「絶対、勝てます。」', 'ハヤトとの一騎打ちに向けて、二琥の協力のもと特訓に励む優。一輝と三和も、二人のことを気に掛けて料理を作ってくれたりしている。一方、二琥はハヤトから自身を否定される言葉を言われて落ち込んでしまう。自分がガラじゃない事を言い出したせいで優にも迷惑を掛けていると言う二琥を、励ます優。本音を吐露する二琥に対し、優はある必勝法を提案する。その必勝法は突飛なもので……!?', '2025/08/28 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78967bd2-24c8-4d70-a0b8-d528efd80d1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35e45c72-3980-479f-a5db-2db9004e15c5', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 9, '100236745', '「キュンを、くれてやる。」', '無事にハヤトとの勝負に勝った二琥は、自分のために頑張ってくれた優に対し、「なんでも願いを聞いてやる」と告げる。二琥と優を二人きりにしたくない一輝と三和も、すかさず同じ提案をする。優の願いは、みんなで一緒に遊園地に行くこと。家族で遊園地に行くことが、優の夢だったのだ。当日、実は各々ある計画を考えていた三姉妹。それは、これまで掌の上で踊らされてきた優に対して「キュン」をくれてやることで……!?', '2025/09/04 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/04a379bd-1b36-473a-b351-b71f4ac0b164.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52017707-08d6-48e8-9706-7e8ccf2723ae', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 10, '100237675', '「天才の、陰。」', '対局中の三和に、忘れ物のお弁当を届けに行く優。喜ぶ三和は、優と一緒にお昼を食べようと誘う。しかし、そこへ現れたのは三和のライバルを自称する女流棋士･矢乙女桜。自信満々な桜だが、中身はポンコツで優とそっくり。圧倒的な研究量でタイトル戦まで上り詰めた努力の人･桜と、正真正銘の天才である三和。互いに譲れぬ戦いが今、幕を開ける――。', '2025/09/11 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcdc0732-2584-4570-9429-d4a7d96cba1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7f04d9d-d447-4537-9355-b833da646554', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 11, '100237909', '「わかってた、コト。」', 'タイトル戦で桜に二連敗してしまう三和。次に負ければ、三和の敗北が決定してしまう。落ち込んでいる三和を励まそうとする一輝と二琥だが、三和は二人の言葉に静かに怒り、家を出て行ってしまった……! 一輝たちから事情を聞いた優は、急いで三和の捜索に向かう。なんとか三和を見つけた優は、彼女がずっと抱えていた悩みを知り、家に帰る前にとある場所へ向かうことを提案する。', '2025/09/18 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/323563f4-0e74-4029-b93c-3357b4f8858e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('571abd13-66da-4724-bb0a-ed28d9172760', '77c8e2e0-b72b-4ed7-894b-17e92d5a3e52', 12, '100238909', '「誰かの、ため。」', '【最終話】優の励ましの言葉で、自分の将棋に揺るぎない自信を持った三和。勝利を目指す理由は、父のため、姉たちのため……そして、優のため!「喜んでもらいたい――いや、喜ばせてやる……!」――決意を新たにした三和は、桜との対局に臨む。', '2025/09/25 01:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61814744-fc5a-4fb3-8a83-35fd341a6dab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('99b48df4-6490-4741-8008-34e9d7c53351', '天官賜福', '', 'hulu', 'heaven-officials-blessing', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0663c29-9195-43f9-b30c-dceeef8d7cfb.jpg?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'FINISHED', NULL, 113260, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d034ff58-46af-49d8-99f8-3c9c61d698fd', '天官賜福 貮', '', 'hulu', 'heaven-officials-blessing-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b15e6ad-e04e-49fa-9b74-4cf87f5a5adb.jpg?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'RELEASING', NULL, 186837, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cd33cdf6-6fa0-4624-97a8-1becc8c67962', 'd034ff58-46af-49d8-99f8-3c9c61d698fd', 'hulu-heaven-officials-blessing-2-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c2d31aa-3304-4f91-bbdd-fb1aa04f49b4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3d9ac02-60df-4192-8d76-50e97cab6b1e', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 1, '100171191', '鬼王現る', '霊文からの伝言を受け天界へ戻った謝憐は、半月関での一件について帝君･君吾に呼び出される。行方不明の神官が救援を求めていることを知った謝憐は、風師･師青玄と共に鬼界へ調査に行くことに…。鬼市に潜入した謝憐が一際賑わっている賭場に入ると、帳の奥に紅衣の人影があることに気づく。', '2024/01/10 12:00:00', 2037, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c2d31aa-3304-4f91-bbdd-fb1aa04f49b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea9e20f8-ea16-4e9a-b5a0-6b2f4a168d98', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 2, '100171905', '玲瓏の賽', '賭場で謝憐たちと落ち合うはずだった武神･郎千秋だが、博徒のあまりの醜態に腹を立て騒ぎを起こしてしまう。城主である花城に攻撃するも歯が立たず、逆に身動きを封じられてしまった郎千秋。道友を助けるべく賭博に参加することになった謝憐は、花城と一対一の勝負をすることになるが…。', '2024/01/17 12:00:00', 1586, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55edd307-700e-4367-9452-4cbce805ceda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f459bfd8-3a7f-4a3d-9551-4ae1c5b0491a', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 3, '100172722', '極楽への誘い', '少年を追いかけて飛び出した謝憐を仮面の男が導き、花城の御殿へと案内する。華美な建築と圧巻の武器庫に魅了されながら、暫しの間、花城との久しぶりの会話を楽しむ謝憐。そして包帯の少年と再会した謝憐は、その姿にいつか見たある少年の面影を重ねるのだった。', '2024/01/24 12:00:00', 1623, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b0ccc46-5d15-44fa-af64-c56a6c9b7cb4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('771eaee6-0bd0-4f67-ac2f-b4b9021a1813', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 4, '100173561', '秘密の地下道', '極楽坊に潜入した師青玄と合流した謝憐は、花城の居ぬ間に例の扉へと向かう。賽の目次第で様々な空間に通じる扉の力で四方八方を彷徨う羽目になる謝憐たち。紆余曲折を経て遂に地下牢に辿り着くと、そこには行方不明となった神官の姿があった…。', '2024/01/31 12:00:00', 1394, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e624d199-90ec-4fa2-b365-8705609ed4c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6502d0c-aa7d-4dae-8052-cb10a82dfb8e', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 5, '100174619', '芳心再臨', '武器庫へ帰り着いた神官たちの前に立ちはだかる城主･花城。助太刀に現れた郎千秋は果敢にも花城へ挑むが、そこへ割って入った謝憐の剣技が繰り出される。間一髪のところで危機を回避し極楽坊を後にする謝憐たちだったが、郎千秋の心の内にはある疑念が渦巻いていた。', '2024/02/07 12:00:00', 1320, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ced60a24-872c-4dd6-8179-6d45746e2ac4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74e3592d-124a-4b63-80d6-b1b9f5b84c85', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 6, '100175064', '万蝶、君を拯いて', 'かつて永安国の国師と太子として親交を深めた謝憐と郎千秋だが、ある事件をきっかけに両者の関係は一変してしまった…。禁足を命じられて仙楽宮に籠る謝憐は、炎に包まれた極楽坊に佇む花城に思いを馳せ、持ち帰った賽子を振るう。すると、仙楽宮へ思いがけない人物が訪問し…。', '2024/02/14 12:00:00', 1366, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7e9ac9d-4e2c-4a0d-86d4-ac0df64e1a10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d5e54e1-620d-4943-9abe-02fd7b483e16', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 7, '100175549', 'ただ一人のために', '攫われた謝憐を取り戻そうと後を追う風信と慕情だったが、賽子の法術に翻弄され彼方此方へと飛ばされてしまう。一方、一足先に謝憐の元へ駆けつけた郎千秋は再び決闘を挑み、遂に謝憐もその申し出に応じるのだった。こじれてしまった二人の関係をよそに、花城はある場所へと彼らを誘う。', '2024/02/21 12:00:00', 1311, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c516e3fa-2586-422e-8374-e3e7b6282e81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9aea385b-fcca-42f4-a52b-814c952589de', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 8, '100176193', '青灯夜遊', '花城とともに変装して薄暗い鬼の巣窟に潜入した謝憐。捕らえられた人間たちの列に混ざって死体吊るしの森を抜けた先には、仮面をつけた青灯夜遊が鎮座していた。鬼花婿の事件から影で糸を引いていた悪鬼の姿は、意外にも謝憐にとって見覚えのあるものだった…。', '2024/02/28 12:00:00', 1228, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cf0233bf-d2a3-4e8b-93da-ecb99bd26acd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7cc436c-48df-42ea-89e2-672a3e6d67fc', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 9, '100176921', '永安と仙楽', '普段の冷静さとは真逆に激しく荒ぶり、一方的に戚容を痛めつける花城。音を上げた戚容はとうとう鎏金宴虐殺事件の真相について口を割るのだった…。時は遡り、郎千秋が17歳の誕生日を迎えようとしていた当時。安寧へと向かっていたはずの永安国で何が起きたのかが語られる。', '2024/03/06 12:00:00', 1590, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/205894c5-6257-468c-a2a4-37f5489ec6d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8727c8e-1c8c-47e8-9a9d-d82b183e7fc4', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 10, '100177704', '血塗られた宴', '滅亡した仙楽国皇室の末裔･安楽は、永安国主から鎏金宴の手配を信任されていた。表向きは永安王族と良好な関係を築きつつ、腹に一物を抱えていた安楽の心の闇に付け入る戚容。宴の場に遅れてやってきた芳心国師こと謝憐は、そこで予期せぬ事態を目の当たりにし、ある決断を迫られることとなる…。', '2024/03/13 12:00:00', 1259, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/733a35b3-a1de-46f5-9412-dbc6d48ebc3c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aba37ec2-9e9d-4be6-8e94-a193c502c385', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 11, '100178289', '月下の惜別', '郎千秋に鎏金宴の真実を知らせた花城を責める謝憐。しかし花城は謝憐の行動は間違っていないとはっきり告げる。謝憐に絶大の信頼を寄せ、ただ一人事件の真相を見抜いていた花城に対して、ついに謝憐は過去にどこかで会ったことがあるのではという疑問を口にするが…。', '2024/03/20 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fafb585c-6bb7-4b04-b2c2-49e59ac6f269.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b9bd008-a939-46d8-b9c5-3402e313e6aa', 'cd33cdf6-6fa0-4624-97a8-1becc8c67962', 12, '100178734', '百無禁忌', '【シーズン2 最終話】仙京に戻った謝憐は君吾に鎏金宴の真実を伝える。一連の出来事を経て花城への信頼を一層強めた謝憐だったが、反対に君吾は花城に強い警戒心を抱いていた。そして天界を後にした謝憐は、荒れ果てたかつての仙楽国へ赴く。両親の棺へと向かう謝憐だったが、そこで待っていたものは…。', '2024/03/27 12:00:00', 1658, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50299486-2728-4651-871a-85d4de13e425.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('aa48ead6-955a-411c-a5ae-236e80a51305', '天久鷹央の推理カルテ', '', 'hulu', 'ameku-takaos-detective-karte', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06483e46-5aa1-4e1c-b0bd-45ba4d326b64.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 176642, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f32ecde4-d325-4905-9008-e9b6f154da0b', 'aa48ead6-955a-411c-a5ae-236e80a51305', 'hulu-ameku-takaos-detective-karte-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59b95f2e-ec2e-46ff-8e96-769aa190bfa2.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51d8a325-38b0-4858-a100-b7b81c5e2683', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 1, '100212094', '「Dr. Sherlock」', 'あらゆる難事件を解決する天才医師、天久鷹央。彼女が副院長を務める天医会総合病院に、大きな獣に足を噛み切られた青い血の男が運び込まれる。この事件に興味を持った鷹央は部下の小鳥遊とともに調査に乗り出す。', '2025/01/05 12:00:00', 1511, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59b95f2e-ec2e-46ff-8e96-769aa190bfa2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c50792d4-1c03-4b62-a088-421d373bb1a1', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 2, '100212095', '青い血と竜の牙', '男の足を切断した凶器は、ティラノサウルス――。鷹央の衝撃的な推理によって事件が急展開を迎える中、残された謎「なぜ、被害者の血は青かったのか?」を解明するため、鷹央たちは「ある場所」へと向かった。', '2025/01/05 12:00:00', 1511, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bced3d0f-5be3-4c67-9506-7ab7f0460aa3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12a1dade-8267-4171-bdef-503db6762de7', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 3, '100212521', '閃光の中へ', '「呪いの動画って信じます?」ある動画を見た直後に線路に飛び込んだ少女が精神科病棟に入院した。下された自殺未遂の診断を否定し、原因は「呪い」と主張する双子の姉の話を、鷹央だけが信じ、捜査を開始する。', '2025/01/12 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e42c2b42-4d53-4ed6-81a8-6e48740c30f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('834a7ee5-4d86-44bd-9455-1661219271e4', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 4, '100214298', '火焔の凶器', '「墓を荒らした者は悉く呪い殺される」蘆屋道満に連なる陰陽師の墓を調べた大学の研究チームが、相次いで不調を訴えた。捜査を依頼された鷹央だったが、事件は思わぬ展開を迎え、謎の人体自然発火現象が起きる。', '2025/01/26 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce6e84de-fab5-4914-9bb7-e961aed9eca0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c1ecbff-924b-4349-8dfd-e4dac3bcb46b', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 5, '100214812', '紅蓮の呪術師', '鷹央の診断で解決したかに見えた「炎蔵の呪い」。だが、不可解な焼死によって捜査は振り出し、さらに「呪い」の被害は続く。別の大学関係者の訃報を受け通夜に赴いた小鳥遊は、そこで不審な男を目撃する。', '2025/02/02 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8caa1bb3-5fa8-4e62-8fd0-2580155e7bbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ac77fdf-e7cb-4648-8bab-8bdde285ae82', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 6, '100216185', '炎の終幕', '再び起こった謎の「人体自然発火現象」。しかも、小鳥遊と鴻ノ池の活躍で逮捕された容疑者は、2つの焼死事件への関与を否定し、鷹央の推理も行き詰まる。これは呪いか、殺人か。驚くべき「真犯人」の正体は……?', '2025/02/09 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/acf1d561-bcf2-4703-846d-44c561d49a88.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22c63888-f879-457f-bcb9-5ce48a6f8a2e', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 7, '100218461', 'オーダーメイドの毒薬', '鷹央が医療過誤で訴えられた!? 誤診を否定する鷹央だったが、訴訟を口実に院長･大鷲は統括診断部を解体しようと動き出す。解体の決議が行われる病院の幹部会の時刻が迫る中、鷹央は真実を明らかにできるのか?', '2025/02/23 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3cc71e15-6df9-4f9f-aac1-1ea038951f12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38466e97-8796-4900-b199-a5246098382e', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 8, '100219057', '天使の舞い降りる夜 前編', '同室の中学生3人が立て続けに急変するという原因不明の現象が起こる。時を同じくして小児科病棟では「天使」が現れると話題に。だが、魅力的な謎にもかかわらず鷹央は興味を示さず、診断に赴くことにも難色を示す。', '2025/03/02 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4a95014-0891-42a5-8f57-f27b340947a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8cca4cd-c64f-4cfb-9d18-a0f0dd02dcd0', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 9, '100220115', '天使の舞い降りる夜 後編', '鷹央の不調の原因は、研修医時代に診察した少年･三木健太だった。白血病が再発した健太と向き合えない鷹央。だが、中学生の1人が再度の急変を起こしたことで「天使」事件の解明に動く。その先に待つのは…。', '2025/03/09 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d1baae9-affe-45fd-be0d-e859651e3eec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c057539b-958f-4a4f-b695-6f502d8d7bd0', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 10, '100221804', '密室で溺れる男　前編', '密室で男が溺死した。その容疑者は小鳥遊の先輩医師･桑田清司であり、結果、清司の代わりに大学病院へ戻るよう小鳥遊に辞令が下る。異動を防ごうと事件解決に動き出す鷹央だったが「密室殺人」の謎が立ち塞がる。', '2025/03/23 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a924cf37-5025-4c6a-9b2a-36a8cc7030f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac8a9157-12ea-43b3-a425-acbc7b8ee5a5', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 11, '100222471', '密室で溺れる男 中編', '小鳥遊の先輩医師･桑田清司が数日中に逮捕される見通しであることを知った鷹央。小鳥遊の異動のタイムリミットは刻一刻と近づいていた…。そんな中事件当時の映像を観た鷹央はある人物の不自然な行動に気づく。', '2025/03/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca4410eb-597d-43cc-a115-48e358250b90.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a485d19d-6876-40db-9b4c-d8cd08df6403', 'f32ecde4-d325-4905-9008-e9b6f154da0b', 12, '100223286', '密室で溺れる男 後編', '【シーズン1 最終話】なぜ密室が生まれたのか。そしてなぜ、桑田大樹は溺死したのか。今夜中に事件を解決しなければ小鳥遊が異動してしまうと焦る鷹央。小鳥遊は限界を悟り、鷹央に語りかけるが…。様々な思惑が交錯した密室事件の真相とは?', '2025/04/06 12:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cac9b147-c919-4595-823e-87aff29241fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('46956689-f9ad-4553-aef9-b8072c6aeb4f', '天元突破グレンラガン', '', 'hulu', 'gurren-lagann', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31f1daad-5fe7-4876-8c19-f47a67bbdcb7.jpg?w=331&h=447&p=t', 'hulu', 2007, 1, 1, 'FINISHED', NULL, 2001, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2948a7a5-bc48-46a8-b395-8bb03cd64b10', '46956689-f9ad-4553-aef9-b8072c6aeb4f', 'hulu-gurren-lagann-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/90c7b89b-4406-4566-a2ed-bdfd1ca25efc.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90e0f024-fb89-4016-884a-158f3d6e769a', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 1, '60502355', 'お前のドリルで天を突け!', '遥かな未来。人々は地中で時折起きる地震と落盤に怯えながら何百年も息を潜めるように暮らしてきた。村を広げるための穴掘りをしていた少年･シモンは、偶然、不思議に光る小さなドリルを見つける。そして、シモンの兄貴分であるカミナ。彼は地上があることを信じ、外へ出ようと目論んでいた。ある日、地震と共に村の天井が崩れ巨大なメカが落ちてくる! 暴れるメカに無謀にも立ち向かおうとするカミナ。その彼の前にライフルを手にメカ＝ガンメンを追ってきた少女･ヨーコが現れる。', '2025/12/26 00:00:00', 1552, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/90c7b89b-4406-4566-a2ed-bdfd1ca25efc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a3da7a6-021d-4d14-8fd6-ce398499ad08', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 2, '60502349', '俺が乗るって言ってんだ!!', 'ジーハ村を襲ったガンメンを撃破し地上に出たカミナとシモン。そこは更なるガンメンが待ち受ける世界だった。ヨーコの住むリットナー村をたずねる二人。そこには毎日のようにガンメンと戦っている村人たちがいた。村人の一人であるリーロンはシモンの乗っている「ラガン」に興味を持ち、何も知らない二人に「ガンメン」のことや地上のことを教える。翌日、夜明けと共に3体のガンメンが襲来する。驚く二人にヨーコは平然と「いつものこと」と答える。村に危機が迫る中、戦いに加わっていたカミナは隊長機らしいガンメンに目をつける。', '2025/12/26 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7c1f6320-9e7e-45c0-ad1c-d14c32ff54ad.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ab400b9-01e0-480e-ae89-3c3cc8ae3734', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 3, '60502359', '顔が2つたぁ生意気な!!', 'シモンとの共同作戦 (?) で見事ガンメンを奪取し、敵を撃破したカミナ。奪ったガンメンを「グレン」と名づけて得意げなカミナはヨーコに誘われ、狩りに出かける。その狩場でヴィラルと名乗る獣人と交戦。ヴィラルのガンメン「エンキ」の強さにラガンとグレンは敗退。なんとか命からがら逃げ出したものの、翌日にはリットナー村が襲われるのは明白だった。ボロボロになっていくグレンの姿に、思わず顔を伏せるシモンに対し、ヨーコはカミナがシモンが必ず来ることを信じて戦っているのだと話す。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4d5db60e-4515-4032-85ef-5dca255a54b3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41451e52-4946-4a50-b1b2-860683e34fea', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 4, '60502358', '顔が多けりゃ偉いのか?', '激しい戦いのなか、ラガンとグレンが奇蹟の合体を果たし、グレンラガンとなってヴィラルを打ち破ったカミナたち。勢いに乗って敵の本拠地に乗り込もうと旅を始めた矢先、突如合体の特訓を始めると言い出すカミナ。前回の合体はあまりにもブサイクすぎて「男の合体」ではなかったというのだ。特訓の最中、突然黒ずくめの4人組がグレンに襲い掛かってくる。彼らは獣人ハンター「黒の兄弟」と名乗り、グレンがシモンを襲っているのだと勘違いして助けに来たのだという。', '2025/12/26 00:00:00', 1461, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0d2dab13-cb2a-463a-94a1-5c239f949ab5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('393bb0b2-80f3-4371-bb7d-04022bbc90fe', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 5, '60502368', '俺にはさっぱりわからねえ!', 'キタンたちと和解を果たし、旅を続けるカミナ一行。とある場所までたどり着いた途端、突然地面が崩れガンメンごと地下に落下してしまう。落ちた先は古びたガンメンを「顔神様」と崇める奇妙な村だった。ガンメンから出てきたカミナたちは「顔神様の使い」として歓待されるが、その態度に不審なものを感じる。その後、村人たちはある儀式を行うが、それは貧しさゆえの過酷なものだった。儀式を「村が生きていくために不可欠なもの」と説く司祭に対し納得できないカミナ。一触即発になりかけたそのとき、新たなガンメンが天井から落下してきた!', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/00e940de-8e9d-42fb-9da8-238fb94a7d7b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42dee314-2af3-45c1-9033-db72a924411a', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 6, '60502360', '見てえものは見てえんだ!!', '仲間にロシウとギミー & ダリーを加え、敵本拠地への旅は続く。彼らの前に突如立ち塞がるガンメン軍団。これまでの戦いで成長しているカミナたちはあっけなく倒してしまうが、1体だけ逃してしまう。敵の本拠に辿り着けると確信し、追跡するグレンラガン。だがいつの間にか立ち込めた霧のために見失ってしまう。霧中をさまよう中、1人の老人に出会う。老人は一行を奇妙な屋敷に案内するが…そこは温泉旅館?! 下にもおかぬもてなしに浮かれっぱなしのカミナたち。ただ一人冷静なロシウは彼らの態度に疑いを抱き、屋敷内の探索を始める。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5f9c3fd9-ed11-484c-bf96-e10d75d11c67.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b0a361b-e543-4505-bb3f-f05f3b939681', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 7, '60502342', 'それはお前がやるんだよ!', 'オオカミ獣人の罠を打ち破ったカミナたち一行。その前に現れた獣人･ヴィラル。前回の戦いに敗れ、雪辱を果たさんと再戦を挑みにきたのだ。そのまま激しい戦いを展開するグレンラガンとエンキドゥ。戦いが優位に傾きかけたとき、突如彼方から砲弾が飛来し吹き飛ばされる。激しい砲撃と共に現れたのは…山のような巨大なガンメン! 圧倒的な戦力の前に撤退を呼びかけるヨーコたちだが、カミナは一歩も退こうとはせず戦いを続けるがまるで歯が立たない。窮地に立たされるカミナたち。そんな彼らの前に新たなガンメンが現れる。彼らの正体は?!', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3826b49f-e437-447c-b59f-4a9ee9bde1b2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5bc2756a-a815-496e-b8c1-b270ae7890e8', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 8, '60502346', 'あばよ、ダチ公', '要塞型ガンメン･ダイガンザンとの戦いの最中、ピンチを救ったのはリットナー村のダヤッカや「黒の兄弟」キタンたちだった。彼らは獣人のガンメンを奪取し自分のものにしてきたのだ。「大グレン団」の旗の下、仲間たちが続々と集結する。カミナは彼らと共にダイガンザンの乗っ取りを決意する。作戦を前に盛り上がる大グレン団の面々とは裏腹に、カミナの行動に一抹の危惧を抱くヨーコ。決戦の朝、シモンはカミナとヨーコのキスシーンを目撃してしまい、激しく動揺する。そんな彼の心中をよそに、激しい戦いの幕は切って落とされる。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f36af3ea-7298-4699-802d-798f9eb76dc9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d953f0e-e4de-41b6-888a-bfb2e85369b0', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 9, '60502345', 'ヒトっていったい何ですか?', '四天王チミルフ戦死の報。それは新たなる戦いの幕開けに過ぎなかった…。激しい戦いの末、ダイガンザンを手に入れた大グレン団。だが代償はあまりにも大きかった。カミナという精神的支柱を失い、「自分のせい」と半ば自暴自棄と化すシモン。仲間たちからも孤立する中、ガンメンとの戦いの最中にラガンが暴走し、グレンと分離し飛び出してしまう。コントロールのきかないラガンは、コンテナが散乱する奇妙な谷に不時着する。谷をさまようシモンの前に、新たなコンテナが落下してくる。その扉を開けると中には一人の女の子が眠っていた…。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5dcc9f63-4a32-4c1d-941b-cf865b1dbfe9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ca4449b-7ad6-41cb-adc3-d05854990918', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 10, '60502367', 'アニキっていったい誰ですか?', 'シモンが連れてきた少女･ニアの正体を知り、動揺を隠せない大グレン団の一行。カミナを失った事実から立ち直れないシモンだったが、ニアに問われるまま、カミナとの絆を語るのだった。一方、ニア姫にためらい、戦いをやめてしまった四天王･アディーネ。都で螺旋王にそのことを責められたアディーネは単身ダイグレンを倒すことを誓い出撃する。ダイグレンの前に再び現れるガンメン･セイルーン。アディーネに対し、ニアは単身甲板に飛び出し、ことの真意を父王にただすべく、自分を都に連れて行くよう命じるのだが…。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/724ba795-0cd7-45d1-889c-f02d8bf0945d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8c6d3ba-6159-4995-84dd-6f7bb9c87ea7', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 11, '60502356', 'シモン、手をどけて。', 'アディーネを退けた大グレン団。だが未だ立ち直れないシモンは部屋に引きこもってしまう。都を目指すダイグレンに入る緊急通信。あからさまに怪しい通信内容にリーロンたちは罠だと疑うが、キタンはそれをきかずに救助に向かってしまう。だがそれは四天王･グアームの狡猾な罠だった。何の抵抗もできずに牢に放り込まれるシモンたち。脱出するべく穴を掘ろうとするが、全く歯が立たず、一人、また一人とあきらめていく。そんな中、黙々と掘り続けるシモン。そのうしろ姿を見て、ヨーコはかつてカミナが言っていたある一言を思い出すのだった…。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c2be7849-8b7f-4b71-85ba-700fd34d24b0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70954cdb-0837-46bc-95b8-d89f2331c58f', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 12, '60502357', 'ヨーコさん、お願いがあります', 'グアームの卑劣な罠を打ち破り、己を取り戻したシモン。カミナの志を受け継ぎ大グレン団の新リーダーとして王都･テッペリンを目指す! そんな彼らの目前に海が広がる。地上専用のダイグレンでは海は航行できないのだが、こんなこともあろうかとリーロンは水上装備を用意していた。装備を換装する間、海水浴を楽しむ一行。その中に仲間として溶け込んだニアもいた。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/df416321-185e-4149-8a96-7df1e2c630eb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0d429d0-f9dc-402f-9d0d-72c702444008', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 13, '60502362', 'みなさん、た～んと召し上がれ。', '四天王の一人、流麗のアディーネとの海戦に勝利したシモンたち大グレン団。その余韻にひたる間もなくテッペリンを目指すなか、突然「働きたい」と申し出るニア。メンバー全員が働いているというのに、自分だけ何もしないのはいやだというのだ。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/16b5417a-a40b-4f6e-8c46-211781763fde.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78bf957f-cc60-4a04-a0ea-c6a082c30567', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 14, '60502353', '皆さん、ごきげんよう。', 'ついに王都･テッペリン目前までたどりついた大グレン団。息つく間もなくテッペリン攻略戦の幕が切って落とされる。大グレン団の前に立ちふさがる四天王の旗艦ダイガンド & イガンテン。地上で、空中で互いのガンメンがぶつかり激しい火花を散らす。2隻の戦艦ガンメン相手にダイグレンは苦戦を強いられる。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a0ebd636-16f0-48cf-ba60-4105d0b0061a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7c52913-0712-4759-8c39-bd34d3f61983', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 15, '60502354', '私は明日へ向かいます。', 'シモンたちの前で、崩壊を始めるテッペリン。その正体は都市そのものが巨大なガンメンだった! 大グレン団の面々が呆然とする中、引き寄せられるように天空へ向かうグレンラガン。雲海を越えるほどの上空にしつらえられた玉座に座る一人の男。ついに螺旋王ロージェノムと相対する!', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a362e8cb-9744-4035-bc15-329c508ef8dd.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb04d8f7-aa5e-4dce-883f-15353d594ada', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 16, '60502361', '総集片', 'これは、まだ運命に気づかぬ一人の男の物語。シモンとカミナ、二人の男が地下の村から地上へ突き抜けて始まった、遥かなる旅。見知らぬ世界、新たな仲間たち、そして別れ。絶望の淵で見つけた出会い。物語の欠片を紡いで語る「総集片」が今、ここに始まる。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/335cd2c4-1802-40cb-9f0c-13f09a8b6c94.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba907fa5-79f7-49b9-8fc6-1ef4a9cb108a', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 17, '60502347', 'あなたは何もわかっていない', 'テッペリンの決戦から7年後…。地上に解放された人々は、螺旋王の残したテクノロジーをもとに瞬く間に文明を構築していく。そんな中であるものは結婚して子供をもうけ、またあるものは新天地を目指し旅立っていった。新政府の総司令の座に着いたシモンは公務に忙殺される日々をぬって、ニアにプロポーズする。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/52980de5-1204-4484-bfd9-fdd041a659a0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f1efcd7-fbc3-411d-98ed-44346b14c49f', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 18, '60502344', '聞かせてもらうぞこの世界の謎を', '螺旋王ロージェノムの予言通り、地上の人間の数が100万人になった瞬間に現れた正体不明の兵器。そして人類に宣戦布告したのはシモンたちにとって全く予想のできない人物だった。かろうじて敵を撃退したシモンは真相をただすべく、その姿を求めてカミナシティをさまよう。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f9dc8284-cf68-4649-8e3c-e05bb16fe129.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e51d10e6-b68c-4ba4-bc9f-9c9192b3bc49', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 19, '60502364', '生き残るんだどんな手段を使っても', '敵を撃退し帰還したシモンはロシウによって逮捕され、そのまま独房に監禁される。カミナシティで暴動を起こした民衆を鎮めるにはこの方法しかないと言うロシウに対し、キタンやダヤッカらグレン団のメンバーはいきり立つものの何も言い返せない。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c8f94dca-6e0c-4039-9c03-85ae22336a24.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('861a30ed-01e6-4bdc-abcc-fc4870fd8b83', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 20, '60502352', '神はどこまで僕らを試す', 'カミナシティに帰還したシモンは監獄に収監される。そこにはかつてのライバル･ヴィラルも投獄されていた…。人間の避難を急がせるロシウ。ロシウの行動に不審を抱くキタンだが、行動の裏に隠された真の意味を知り驚愕する。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4184bb50-a7fa-42e9-b0a0-6e6f29a58a6a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fca2062-8453-4da5-aa25-5f1c3278f161', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 21, '60502348', 'あなたは生き残るべき人だ', '地下から出てきた人間たちが暮らすコレハナ島の小学校に、一人の新任教師が赴任してくる。その女教師は瞬く間に島の生活にとけこみ、生徒たちに慕われる。彼女の生徒の一人･ナキムは父親をなくしてこの島に移り住んだものの、島の生活になじめず、同級生ともうまく付き合うことができないでいた。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f7700712-4c0f-4399-8204-d5c0bce7e0da.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37d30f86-b301-4d48-ab49-6d30b8ee83d3', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 22, '60502350', 'それが僕の最後の義務だ', '宇宙へ脱出したアークグレンを、軌道上で襲うムガンの大編隊。ギミーたちグラパール隊の奮戦もむなしく、アークグレンの損害は増大していく。アークグレンのクルーが絶望のふちに立たされたそのとき、ブリッジに響くシモンの声!「あきらめるな! ロシウ! 」', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/04f0c483-3e97-42ae-a5f3-4fbab6e80b61.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7fa8dd6-453a-4a31-bdc2-ae4b20f1342d', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 23, '60502365', '行くぞ 最後の戦いだ', '圧倒的なアンチスパイラルの猛攻を防ぎきり、逆転勝利を収めた大グレン団。その勝利の余韻も覚めやらぬまま、アンチスパイラルの本拠地探索を開始する。そのころ、ロシウは一人、生まれ故郷であるアダイ村に現れていた。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7f965cbe-ebfe-48dd-9c71-f0b38e61f768.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('594bbf9b-5d16-414b-a89d-5e1d07a4916b', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 24, '60502351', '忘れるものか この一分一秒を', '人類の未来と愛するニアを救うため、次元の狭間にあるというアンチスパイラルの母星を目指すシモンと大グレン団。その行く手を阻むようにあらわれるアンチスパイラルの艦隊。その数、無量大数!シモンの螺旋力に全てを託し、大グレン団が絶望的な戦場で命を賭ける!', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/72d538c1-3c7a-4e12-8862-60d94efe559d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2324cd7e-43f3-4f0b-aebd-0be00d4bca01', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 25, '60502363', 'お前の遺志は受け取った!', 'アンチスパイラルの新たなる攻撃にさらされる超銀河ダイグレン。宇宙が高密度の海と化し、超銀河ダイグレンを沈めていく。罠を打ち破るため、シモンたちは一見無謀にすら思える捨て身の作戦に出る。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/61dc28a2-aadd-4e35-869f-8d7e6d873f2f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd8bf1da-2572-40a5-88ee-eeb890761c56', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 26, '60502366', '行くぜ ダチ公', 'アンチスパイラルの罠を突き破り、ついに変形を完成させ大銀河に立ち上がる超銀河グレンラガン!その圧倒的な力は眼前に立ちふさがる敵艦隊をみるみるうちに駆逐していく。だが、アンチスパイラルの仕掛けた新たなる罠に大グレン団の面々はなすすべなく囚われる。それはシモンですら例外ではなかった。', '2025/12/26 00:00:00', 1462, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/69011722-43d9-486f-bcf2-2ba17e0af137.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4d0a573-c8ac-4cbd-b9ef-66c65465494a', '2948a7a5-bc48-46a8-b395-8bb03cd64b10', 27, '60502343', '天の光は全て星', '【シーズン1 最終話】これは自分の運命を知らなかった一人の男の人生の物語。今、男は自分の運命を知り、愛する女と、友と、まだ見ぬ明日のための最後の戦いが今、始まる!', '2025/12/26 00:00:00', 1446, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/87f7a71b-7399-42c7-8a31-00ccb5032470.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2561a139-71f6-48fd-b945-0007ef9e1b63', '天才王子の赤字国家再生術', '', 'hulu', 'the-genius-princes-guide-to-raising-a-nation-out-of-debt', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9f8cece-14e1-4dcc-b26c-0e96fb09bca7.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 129190, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b47b610d-ba82-4aa8-9981-f1b692c36e7d', '2561a139-71f6-48fd-b945-0007ef9e1b63', 'hulu-the-genius-princes-guide-to-raising-a-nation-out-of-debt-s1', '第1シーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2e43f8a-74fa-49da-b226-1a7d162044e4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f2368cc-76c2-428e-a47e-5e29fdd4779b', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 1, '100101304', 'そうだ、国を売ってトンズラしよう', '父である国王が倒れ、補佐官のニニムと共にナトラ王国を導くことになったウェイン王子。しかし、王国は経済、軍事、人材……そのどれもが行き詰まっていた。国を売って早々に隠居したいウェインは、他国に高く買ってもらうためにしぶしぶ国力を上げようとする。そんな中、隣国のマーデン王国がナトラ王国に進軍を開始。やる気のないウェインだが、武官たちの士気は高まっており……。かくして、戦端の火蓋が切られるのだった。', '2022/01/16 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2e43f8a-74fa-49da-b226-1a7d162044e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29e5172c-f7a3-45eb-b986-6064c72b70c8', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 2, '100101935', '戦場のウェイン･サレマ･アルバレスト', 'マーデン王国軍に大勝したナトラ王国。ウェインの思惑とは裏腹にマーデン王国に逆侵攻することになり、あっさりジラート金鉱山を占拠してしまう。マーデン王国側の猛反撃は避けられない。しかも金鉱山の資源は枯渇しかけ、占拠する意味がなかった。踏んだり蹴ったりのウェインは、金鉱山を巡る策を打ち出す。そのために必要なのは……籠城戦。ナトラ王国軍5千人とマーデン王国軍3万人の1ヶ月にわたる戦いが始まろうとしていた。', '2022/01/23 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/030ebf7e-964f-4f6c-a5c4-706e0050c862.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0cb0c539-010e-48e7-995d-8d3bab22cff2', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 3, '100102359', 'そうだ、政略結婚しよう', 'アースワルド帝国との同盟強化のため、帝国の皇女を迎えることになったウェイン。やってきた皇女とは、なんとウェインとニニムの士官学校時代の友人･ロワことロウェルミナだった。ロウェルミナに縁談を持ちかけられたウェインは、悪巧みのうまい彼女の真意を駆け引きの中で探ろうとする。そしてウェイン、ニニム、ロウェルミナの密談の場が用意されるのだが、ロウェルミナが切り出したのは、あまりに無謀な提案で……!?', '2022/01/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1012dfbb-7520-4813-90e0-b7e5c28aeedc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('acf4cf52-b9f3-4d29-859e-98550eba69a8', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 4, '100103513', '二人の知謀', 'ウェインはロウェルミナの帰国前に茶会を開催する。泥沼化する帝国の後継者争いに勝とうとするロウェルミナの本当の目的を暴いていくウェイン。その果てにあったのは、ナトラ王国とアントガダル自治領の衝突すら辞さない大がかりな計画だった。手段を選ばないロウェルミナの計画に巻きこまれてしまったウェインたち。複雑に絡み合う情勢の中で、ウェインはロウェルミナを出し抜こうとするが……思いも寄らない事態が巻き起こる。', '2022/02/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bcc13952-4a6c-415f-b2c4-f85a572e8b9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('918805ab-175d-4278-b7e5-1794c8a7ade1', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 5, '100103890', 'そうだ、罪を被せてみよう', '不慮の事故で亡くなってしまったゲラルト。ウェインはその父であるアントガダル侯グリナッヘのもとを訪れ、話し合いによる解決を目指す。グリナッヘの反乱計画を見抜いていたウェインは、ある取り引きを持ちかけるのだが……。父親として、領主として悩んだ末に、グリナッヘは意外な選択を決断する。そんな中、会談を終えたウェインたちの行く手を阻む者がいた。さらに何者かによるグリナッヘ暗殺計画も動き出していて……!?', '2022/02/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07da2af2-18ad-427a-9af9-5d6fa555cc11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e156a993-e3a3-4c7d-a2fe-d27d52117f80', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 6, '100104452', 'そうだ、国際会議に出よう', 'カバリヌ王からレベティア教の聖霊祭に招待されたウェイン。ニニムたちとカバリヌ王国を目指すが、その旅は多くの危険を孕んでいた。国境周辺にはカバリヌ王国に滅ぼされたマーデン残党軍が潜み、ナトラ王国内でも諸侯に反乱の兆しがあった。道中、ウェインは正体不明の集団に狙われ、さらに街道から外れた林の中でマーデン残党軍と遭遇。ウェインは残党軍の指導者･ヘルムート王子に面会を求めるが、名代を務めるゼノが現れ……。', '2022/02/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ce5bfe9-ec97-45d9-93e9-3bb49218c03e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3129c8b5-64a4-401a-a590-1b8550837ef6', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 7, '100104843', '昨日の敵は今日の', 'ウェインの命を狙うルベール将軍とホロヌイェ、冷酷な決断を迫るカルドメリア、そして国王としての求心力を失いつつあるオルドラッセ。それぞれの思惑が渦巻く中、ゼノがウェインとオルドラッセの会談に同行したいと申し出る。解放軍が生き残る道を見つけようとするゼノの決意に、同席を許すウェイン。だが、オルドラッセとの会談は予想外の展開を見せ、ウェインが大惨事を引き起こしてしまう。', '2022/02/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/891f5c6d-07fd-457c-810f-1853f01bcff9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b2f29fd-61f1-4ef0-9730-c748a860956b', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 8, '100105681', 'そうだ、私がやってみよう', 'アースワルド帝国の都市ミールタース。ロウェルミナたち帝位継承権を持つ4人がここに集まり、帝位を巡る皇子 (こうし) 会談が開催される。ロウェルミナは同盟国の要人としてウェインを式典に招待したものの、やってきたのはウェインの妹フラーニャだった。単独公務デビューに息巻くフラーニャ。しかし、さっそく彼女を利用しようとするロウェルミナと、ひと癖もふた癖もある三人の皇子たちに翻弄されてしまう。', '2022/03/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1e221bc-1c76-408b-a538-f15914f252f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('542e7a67-8dbe-4086-870c-3d8c166e5fd6', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 9, '100106408', '偶像少女', 'ディメトリオとフラーニャの婚姻は保留となるはずだった。しかし、ウェインがミールタースへやってきたことで、事態は急変。決定権を持つウェインは、妹の婚姻について決断を迫られてしまう。ロウェルミナを巻き込む大胆な作戦で、事態を収束させようとするが……。会談後、ウェインはロウェルミナから呼び出される。珍しく弱気な表情を見せ、愚痴をこぼすロウェルミナ。ウェインは皇子会談に賭けた彼女の思いを見抜く。', '2022/03/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e0d4616-4ae8-4759-a4d3-74cec32e63c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18aebc7b-ccb3-44c9-80d9-f93a94bb0397', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 10, '100107218', 'そうだ、バブルに乗ろう', 'アースワルド帝国からの解放を名目に、レベティア教の軍はミールタースへ侵攻しようとしていた。その大義名分を逆手に取り、ミールタースの民を保護させようとするウェインたち。軍を指揮するカルドメリアとグリュエールと面会したウェインは、二人にある交渉を持ちかける。そして、ロウェルミナを通じて皇子たちとの会談に臨み、騒動の黒幕を明かすのだった。その発言にバルドロッシュもマンフレッドも絶句する。', '2022/03/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c520708-b5a0-4b98-9742-f0083720f1a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac1064a1-1347-4bad-8109-15b61b936f44', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 11, '100107458', '詐欺だけどしらばっくれよう', 'デルーニオ王国の宰相シリジスから交易品の不正に関して不服を申し立てられるゼノヴィア。そこへ現れたウェインは、あれこれ理由をつけてその申し立てを突っぱねようとするのだが……。その数日後、ウェインはソルジェスト王国を訪れ、繁栄を極めた都市に目を奪われる。貿易で利益を得るどころかデルーニオ王国に対する共同戦線も視野に、完璧なプランで同盟関係を結ぼうとするが、グリュエールのもてなしに骨抜きにされてしまう。', '2022/03/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97d7460a-c5e8-4e20-9956-33b719b4ca4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8796c04e-9304-4774-8519-a52af6610237', 'b47b610d-ba82-4aa8-9981-f1b692c36e7d', 12, '100108290', 'そうだ、やっぱり国を売ってトンズラしよう', '【第1シーズン 最終話】グリュエールの策に翻弄されるウェインはデルーニオ王国との和睦を目指し、ゼノヴィアとともにシリジスとの会談に臨む。ゼノヴィアは不幸なすれ違いであると強調するが、想像以上にデルーニオ王国とソルジェスト王国の関係は強固であった。その関係を突き崩すために大きな賭けに出るゼノヴィア。そして、ウェインはシリジスにある提案を持ちかける。それは、ナトラ王国を売国する以上に荒唐無稽な作戦で……!?', '2022/04/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ebf33dd-c281-491d-9d0f-4e84469d0137.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('256e254d-e5f8-49a1-88e5-fa0d1f994885', '天晴爛漫！', '', 'hulu', 'appareranman', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc706d7d-a6f1-49fb-bf1b-918183879ffa.jpg?w=331&h=447&p=t', 'hulu', 2020, 1, 1, 'FINISHED', NULL, 112444, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0d1c7022-c408-45b2-8cab-be3fdbfa5342', '256e254d-e5f8-49a1-88e5-fa0d1f994885', 'hulu-appareranman-s1', '第1シーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35891378-c102-472b-8362-bb754490a4cc.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44e08967-7d25-4a59-97da-f03a7cd1f223', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 1, '100054478', '晴れ、ときどき小雨', 'ときは明治、日本のある港町。半月一刀流道場の師範代･小雨は、カラクリの天才で、キテレツなものを作り出しては実験と称して破天荒な振る舞いを繰り返している空乃屋の次男坊･天晴のお目付役を命じられる。一方、天晴は上級役人の怒りをかって入れられていた牢から勝手に抜け出し、無断で家に帰ってしまう。小雨は、かつて奇妙な武器で打ち負かされた因縁はあろうと、捕まれば打ち首になるかもしれない天晴のことを放ってはおけなかった。だが、天晴の蔵からつながる洞窟で見たものは…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35891378-c102-472b-8362-bb754490a4cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aebe56df-bea0-4cad-b485-ba531d5d612c', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 2, '100054900', 'in the Dark', '天晴の作った蒸気船で漂流していた天晴と小雨は、通りかかった船に救出され、アメリカ･ロサンゼルスに到着する。生活費を稼ぐため、仕事を探す2人。そんな中、天晴の目を奪ったのは、派手なガソリン自動車が先導するパレードだった。後を追い、たどり着いたのはレース場。そして、2人は知る。三大自動車連合『B.I.G.BOSS』が開催する「アメリカ大陸横断レース」に優勝すれば、帰国資金にも十分な、100万ドルという賞金が得られることを…。その夜、レース場に忍び込んだ天晴たちは、一人、暗闇の中サーキットを走るシャーレンと出会う。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5f784ca-c69c-4d64-b8ea-7fe23fa29121.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b046b15-e93a-4551-b81e-b5e6cd8b21b6', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 3, '100055136', 'DUEL', 'ガラの悪い男たちに囲まれていた子供を助けようとして窮地に陥ってしまった小雨は、「サウザンドスリー」のディランに救われる。天晴は、それが先日のパレードで派手なガソリン自動車に乗っていた男だと気づき「俺の車はいつか、お前の前を走る!」と宣言するのだった。子供の名は、ホトト。父親の仇である、首に蛇のタトゥーが入った男を探し、はるか遠くの村から一人で旅して来たのだという。そんな中、寝泊まりする倉庫がBNWの代表アル･リオンに買われ、出て行かなくてはいけなくなってしまう2人。天晴は、倉庫を賭けてアルの車に勝負を挑む!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e002ffb9-26ea-4724-b172-8840bee29a33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b6f12d4-41a1-4dbc-abdb-ff4e2295d433', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 4, '100060759', 'Let It Go', '大陸横断レースのスタートが近づく中、アルからガソリン車を手に入れた天晴は、さっそく発明に向かっていた。その頃、シャーレンは「女はレーサーになれない」という因習を打ち破るべく、自分をテストするようオーナーに直談判する。だが、チームの男たちに嘲笑され…。侮辱に耐えかねた彼女は、解雇されることも厭わず、ドライバーのデビッドに勝負を申し込む。誇りを掛けた戦いが、始まろうとしていた。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cac54036-a8e3-4919-ab64-b758b899b1e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcec272c-959d-465d-a804-fcb5e2dceec6', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 5, '100061060', 'The Eve. And…', '華々しい前夜祭の席に招かれながらも、ドレスコードに引っかかり、追い払われそうになる天晴たち。そこへ「サウザンドスリー」の一人、クレイジー･TJが、派手な音楽を鳴らしながらやってきた。さらに3人目の「サウザンドスリー」にして仮面をかぶった不気味な男―「虐殺のギル」とその相棒チェイスもあわられ、騒然とする会場。そして、スターティンググリッドを決めるくじ引きを始めようという瞬間、TJが銃を抜き!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33174a7b-eb65-4960-8185-7e2706838dcb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b9c81ec-8719-4973-b3d3-8a9cefa6845b', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 6, '100061495', 'I am Gil!', '第1日目、賞金1万ドルを掛けたプレレースの火蓋が切られた。天晴たちも、蒸気エンジン車ながら健闘するが、隣を走る車の進路妨害にあってしまう。巻き込んでしまったことを詫びるのは、人の良さそうなリチャード･リースマン。奇人変人ばかりが参加しているレースではなかったのだと、ホッとする小雨だった。それぞれが出発に向けて準備する中、ホトトは探していたタトゥーをつけた男たちを見かけ、あとをつけるが…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9e01394-acde-4801-9632-96432a4f0439.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f274caf-cea6-4601-8685-cb1e8440df93', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 7, '100062207', 'FAKE', '捕まっていたホトトが必死に天晴たちのもとへ戻り、デスバレーにギル一味の罠が仕掛けられていることを知らせる。先にスタートしたシャーレンたちが、危ない。そのとき、天晴号に秘められた力が、ついに火を吹く――! だが、レースに優勝するための最も合理的な方法は……。すでにホトトを待つことで遅れを取り、その上、ライバルを救うために動くなど、天晴にとっては到底考えられないことだった。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a425e936-4507-44db-8c23-c1c907a59ccf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2498f6a7-c27d-4923-bc22-d5353264894b', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 8, '100062811', 'HEAVY RAIN', 'チェイスの弟･トリスタンが「ギル」を名乗っていたことを懺悔し、バッド兄弟の悪巧みは幕引きを迎える。だが、新たな事件が発生した。トップを走っていたレーサーたちが、無残にも殺されたのだ。唯一の生存者だったリチャードは、襲撃者の残したメッセージを伝える。「このレースに参加するものは、皆死ぬ」と――。しかも、その集団のリーダーらしき男の首筋には、ギルズスネークがあったと言う。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/721d37e7-45fb-4e33-8c37-3f0d3cdc1490.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f202d05c-05b4-4fae-b91f-fa197af908d3', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 9, '100063710', 'short break', '天晴たちに残された最後の“希望”が、見事、彼らを危機から救い出す。だが、ギルの脅威が去ったわけではない。スタッフの安全も考慮し、駅のある都市を補給ポイントとする北寄りのルートに変更して、レースは続行されることとなった。1日待機を命じられたレーサーたちは、それぞれの前へと進む思いをあらたにしながら、つかの間の休息を味わう。天晴はひとり、いまだ完成しないハイブリッドエンジンに思案を巡らせ…。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9dcdf90-f5e8-4748-b5ff-c866fcacc9ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('425c8e12-38b9-4054-a851-b904e3426a73', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 10, '100064413', 'The Bridge to Hell', 'スタッフを乗せた列車の発車と刻を合わせ、全車揃って一斉にスタートした後半戦。はからずも「鉄道VS自動車」の戦いともなったレースは白熱し、最大の見所であるミズーリ大鉄橋には大勢の記者が待ち構えていた。ソフィアは、列車に揺られながら切に願う。「どうか、このままみんなが無事にゴールできますように……」。だが、そこへ無情にも襲い掛かるギルの毒牙……!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c757b37-6270-4a89-adbe-b278a52c062c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff657369-033e-4c67-86e7-7fc21bb00b8e', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 11, '100064785', 'Rain in the Dark Night', '天晴を庇って凶弾に倒れた小雨は、何とか病院に運ばれたものの、厳しい状況にあった。それぞれに大切している思いを踏みにじられ、ボロボロになったレーサーたち。アルは、人質となったソフィアの身を案じ、一刻も早く助けに行くために、天晴に「力を貸して欲しい」と乞うのだが……。トップを走るはずのレースは、さらにその先を目指す天晴の夢は、本当にここでついえてしまうのだろうか?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a72810b2-46b3-459b-bd86-8e9f499ed8b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b78be31-11f5-4737-be80-86a5e45235cd', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 12, '100065043', 'WE WILL STOP YOU!!', '40キロほど先にあるゴーストタウンに、ギルが潜伏しているという情報がもたらされた。州兵が乗り込んで戦場と化す前に、ソフィアを助け出し、レースを続行する――。よみがえった天晴に応え、立ち上がる仲間たち。「見せてやろうぜ、世界が目を覚ますようなやつを!」。しかし、ギルを頭に100人以上もの敵がいる中、こちらは9人。サウザンドスリーの2人がいるとて、劣勢は否めない。だが、そこへ駆けつけたのは……!', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83690491-e93a-47fa-9e83-01295938b07b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36df1ae0-3850-4669-a914-6fc1e889be1f', '0d1c7022-c408-45b2-8cab-be3fdbfa5342', 13, '100065896', 'OVER THE MOON', '【シーズン1 最終話】一丸となって繰り広げられる、ギル一味との死闘。その間にも、ソフィアと大量のダイナマイトを積んだ列車は、刻一刻と、フェスティバルで賑わうシカゴの街に迫っていた……! 鉄道の発達も車の発明も及ばない、暴虐たる「力」こそが世界を支配し続けることを、大惨事によって知らしめようとするギル。果たして天晴たちは、その謀略を止め、チェッカー･フラッグの祝福を浴びることができるのか!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/04c5148b-b0e4-4136-bf19-56086686238d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8f77c587-103c-45a1-ac41-f1a5ec6cc6f9', '天地創造デザイン部', '', 'hulu', 'heavens-design-team', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc5f9a13-5614-40ec-98de-af67cb1688aa.jpg?w=331&h=447&p=t', 'hulu', 2021, 0, 1, 'FINISHED', NULL, 117696, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('02995894-b25c-447f-94ba-175e46d2cf6c', '8f77c587-103c-45a1-ac41-f1a5ec6cc6f9', 'hulu-heavens-design-team-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/388d6b29-9aa1-445f-975a-d0b88c35776c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ba0da1e-7f1c-4a33-b676-8f5016aff19d', '02995894-b25c-447f-94ba-175e46d2cf6c', 1, '100111324', '案件1', '天地創造社に入社したばかりの新人天使の下田。神様からの連絡役としてデザイン部へ挨拶に行くと、ちょうど会議が開かれていた。神様からのオーダーは「すっごい高いところの葉っぱが食べられる動物」。早速アイデアを出し合うデザイナーたちだが……。', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/388d6b29-9aa1-445f-975a-d0b88c35776c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb88860e-3812-4c8a-bece-a97c51203797', '02995894-b25c-447f-94ba-175e46d2cf6c', 2, '100111325', '案件2', '先輩の上田に連れられ、「虫部」のデザイナーに挨拶に行き、個性的な面々に圧倒される下田。そんな中、神様から「かわいくて、かわいくない生き物」というふんわりしたオーダーが下りてくる。自称･かわいい生き物のデザインを得意とする冥戸が手を挙げ、出来上がったのは……。', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b4d3931-11ba-41ed-9bb8-650110d7289b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1eee116-f5c5-461a-bd92-0ff60327841e', '02995894-b25c-447f-94ba-175e46d2cf6c', 3, '100111326', '案件3', '雷鳴が轟く雲空の下、あやしげなフードを被った男が魔法陣から呼びだしたのは……なんと「龍」!「翼がないのに飛ぶ」というオーダーにこたえるため、龍を参考にしようとする下田たち。だが、そこに慌てた様子で水島がやってくる。', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b15f49d-34c9-4888-9339-6dd79bb1df3d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5c19d59-5ea7-4a4d-be51-2e0dfd983877', '02995894-b25c-447f-94ba-175e46d2cf6c', 4, '100111327', '案件4', '「馬をなんとか飛ばして」。神様に指名され、一人で課題に向き合う金森だが、「自由にしていいよ」「なんか違う」とデザイナー泣かせのリテイク地獄! 改良に改良を重ね、突きつけた最終案とは……!?', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bfb4a87-7b39-4489-a42a-1ebd3d3aab81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('520d6202-4fe0-43b0-993c-447e62d6f0f8', '02995894-b25c-447f-94ba-175e46d2cf6c', 5, '100111328', '案件5', '「パンダ騒動」後、神様に地獄行きを命じられた上田。自分のせいで地獄に左遷されたのでは…と不安になる下田とデザイン部の面々の前に、謎の男が現れる。地獄に闇と炎のテーマパークを建設中の彼は、デザイン部に「地獄のマスコット」を造ってほしいと依頼する。', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5d6c4fd-8ff8-474e-9b31-10f2edce5b45.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a485034f-b502-4b8f-b750-8c8945bd0c76', '02995894-b25c-447f-94ba-175e46d2cf6c', 6, '100111329', '案件6', '神様からのねぎらいでガラパゴス慰安旅行が開催されることになった。温泉や宴会を満喫する中、水島が血まみれで倒れていた。「犯人は……必ずこの中にいる!」と自称食い倒れ探偵の木村が犯人を捜そうとするが……。謎を解くカギは、金森が受けたオーダー「オスが授乳する動物」!?', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c81fb867-eff7-4c22-af29-af331c18f324.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87357d4a-8df2-432a-bdbf-a12bc03bad47', '02995894-b25c-447f-94ba-175e46d2cf6c', 7, '100111330', '案件7', 'ある晩、風呂場で謎の視線を感じたという海原は、それを聞いていた神様から「誰もいないように見えて、実はそこにいて見てる動物」を依頼される。相変わらずの無茶ぶりに悩むデザイン部の面々だったが、過去に冥戸がデザインしたイカを使って実験することになり……。', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b1be04a-c10c-4b1c-b0ff-c3a23d6323a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf0ebfd8-9add-4952-84ea-9069738147ad', '02995894-b25c-447f-94ba-175e46d2cf6c', 8, '100111331', '案件8', '体から武器を出し入れする……それはロマン!? 神様から「骨が武器」の生き物を依頼された木村は、自分の肋骨を改造しまくっていた。時に肋骨を折られたり、時に酸欠になったり。これだけ体を張ったのだから、きっと強くてカッコいい生き物が生まれる、はず!?', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd5ee7fb-5e1b-4cd9-8bbf-62f99034b4dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbdaaaed-f7cd-49f6-a9f6-751650b8479c', '02995894-b25c-447f-94ba-175e46d2cf6c', 9, '100111332', '案件9', '神様からの新たなオーダーは「母性本能を刺激する動物」。下田は冥戸とともに様々な生き物たちの母性、すなわち「愛情」とは何かをリサーチする。独特なセンスの持ち主である冥戸が見出した「愛情」とは…!?', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30337f55-62dc-49c4-a9ed-ae43cc69547d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8700beb8-79cf-4631-9a78-834ced2ffd45', '02995894-b25c-447f-94ba-175e46d2cf6c', 10, '100111333', '案件10', 'なぜか地下の王国に迷い込んでしまった下田。この王国は女王を頂点とした「完璧な社会を造る動物」の国だった。見た目の差が少なく、老化もない、そして個よりも全体の幸せを優先する社会。あまりに理想的な場所だが、そのシステムには隠された真実があった。', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0181223-4a56-4af0-ad09-e571d544c867.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17823f71-091c-42e9-8e61-d37e0cade24a', '02995894-b25c-447f-94ba-175e46d2cf6c', 11, '100111334', '案件11', '生物時間加速器が爆発し、ガラパゴスへ吹き飛ばされてしまった下田たち。しかも全員、子どもの姿に! 実験途中の動物に襲われそうになったり、ピンチ連続の中、下田は土屋、火口、虫部の面々と一緒に「SOSの匂いを察知できる虫」を使ってデザイナーたちを捜索する。', '2022/06/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64472867-e535-46e9-9250-55b2ae31f1ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('991970c6-2049-44db-92fd-3933061da148', '02995894-b25c-447f-94ba-175e46d2cf6c', 12, '100111335', '案件12', '地獄社のパーティーへの贈りものとして、神様から「地獄のアトラクションに使えて、下界にも送れる動物」を依頼されるデザイナーたち。「天使を驚かせるようなものがいい」という横田の意見も取り入れ、全力で取り組むのだが……。', '2022/06/09 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/edb7bb84-03a1-46cd-8849-336b5d8031b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bff16aa-8a15-4474-b0c3-7863ebbf2619', '02995894-b25c-447f-94ba-175e46d2cf6c', 13, '100111336', '特別編', '今回の神様のオーダーは「5つの生き物を造って、最終的にその5つを全部足したもの」。超･無理難題な依頼に困惑するデザイナーたち。それぞれの得意分野で試行錯誤を繰り返すが…。最終的に誕生した生き物とは……!?', '2022/06/09 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74e5f9b4-5b44-40e9-8b5b-c54a5fcf5d41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8d298b77-97e2-4a26-a197-2ab03ae4e854', '天穂のサクナヒメ', '', 'hulu', 'sakuna-of-rice-and-ruin', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b8913051-49ff-4005-924d-d7a71f471b95.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 175868, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', '8d298b77-97e2-4a26-a197-2ab03ae4e854', 'hulu-sakuna-of-rice-and-ruin-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef396efa-48af-4b64-a256-7d7b3012c6d3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66c2f4bf-46f4-43d8-afcd-0ca8d39171d5', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 1, '100189438', '頂の世のサクナヒメ', '武神タケリビと豊穣神トヨハナを両親に持つサクナヒメは、その恵まれた境遇に甘えてぐうたらな生活を送っていた。ところがある日、神々の住む頂の世に迷い込んだ人間たちを都に侵入させてしまった上に騒動の末、主神カムヒツキへの献上物を全て台無しにしてしまった! その代償としてカムヒツキがサクナヒメに言い渡したのは…', '2024/07/06 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef396efa-48af-4b64-a256-7d7b3012c6d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f3ae1f72-5c44-4ada-91b2-bbe3d381ee46', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 2, '100190390', 'ヒノエ島に住まう', '荒れ狂う海の中、何とか島に到着したサクナ達は、母のトヨハナがかつて住まっていた家があるという峠を目指す。道中、鬼達と遭遇するがサクナは難なく撃退。そこにサクナの両親とも縁が深いというアシグモが現れ、サクナ達を峠に案内する。無事に住まいは見つかったものの、今度は食料集めに駆られるサクナ達、そんな中、田右衛門は稲の籾を取り出すのだった。', '2024/07/13 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/350ab7fe-58f3-4d4e-a0c4-25779633d4bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cffb6d3d-0f56-411d-86e1-13cdf3f44f26', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 3, '100191083', '田植唄', '母トヨハナの残した農書を頼りに稲作を開始したサクナ。田起こしを済ませ、苗を育て、田植えを開始するが、慣れない稲作に悪戦苦闘する。それに加え食事も不十分で一向に改善しない生活と、途方もない米作りへの道のりに、サクナは嫌気がさして逃げだしそうになってしまう。', '2024/07/20 23:30:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d03779be-0a2a-427c-9ce3-28836699b2b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a123675f-1eed-4509-a1ba-86983ad8be9d', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 4, '100191917', 'Myrthe`s journey', 'サクナの働きにより峠の近くでは鬼を見かけることが少なくなっていた。これならサクナ以外の者でも近くの森や沢に行くことができ、食料調達等手分けもできる。ただ、稲作の方はどうしても人手が足りない。そこでアシグモに相談し、沢の近くにすんでいるという河童達に協力を仰ごうとする。しかし、ミルテを見た河童は…', '2024/07/27 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d33f30a-1552-4648-bfde-d7faf88f62e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d62ba479-f5d8-4792-acf3-a3eebe965463', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 5, '100192773', 'きんたの恩返し', '季節は夏。きんたが所望した鍛冶小屋も完成し稲作も順調に進む。しかし相変わらず、きんたはゆいにきつく当たる。邪険に扱われても、なおそばにいて関わろうとする真っすぐなゆいを見たサクナはきっと恋に違いないと、愛読書である「片恋物語」を参考にゆいを応援しようとするのだった。', '2024/08/03 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fab1e0cc-fff9-4152-8904-4749ceac67cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d494996c-6220-4b63-b53a-b3ae926dc5c1', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 6, '100194026', '恨みの炎', '秋を迎え、稲穂に覆われている田。風が流れ揺れる稲穂。喜ぶサクナを前に、田右衛門は収穫まで油断は出来ないと話す。そんな時、大きな地震が起こる。川も濁り様子がおかしい。多くの鬼が火山に向かっていたという報告もあり、サクナは火山に向かうことに。火山の麓に着くと「憎い、憎い」と声が聞こえる。鬼たちの亡骸に背を向けた先に現れたのは…', '2024/08/10 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4af7ade6-70a1-4fbb-86fd-39bf7bf4db42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('933a74f5-f34e-4132-b7af-373545c6664f', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 7, '100194027', 'ココロワヒメの憂鬱', 'サクナが島に旅立ってからココロワヒメの日々は目まぐるしく変わっていた。カムヒツキからも評価され都で活躍するココロワだったが、サクナが一時呼び戻されると聞いて動揺する自分に気づく。サクナは、ヒノエ島での活動の報告のため、都に一時戻ることになっていたのだ。その後、久々のココロワとの再会にはしゃぐサクナだったが一方のココロワは動揺を隠せないでいた…', '2024/08/17 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47b1a10a-c1cc-4619-a845-b4472b45ab8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ed03c54-0c47-4a41-aa60-9684352f81d4', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 8, '100195351', '都を揺るがす米騒動', 'サクナたちが作り「天穂 (あまほほ)」 と名づけた米は都でも評判になっていた。しかし、ある日峠に現れた瀬守神 (せもりがみ) は天穂が人を惑わす危険な米だと流通を禁じられていることを告げる。サクナ達は、自分たちの米の評判に傷をつけようとした者が米に細工をしているのを察すると、更にココロワヒメにその嫌疑がかけられていると知る。それを信じようとしないサクナは都に戻り真犯人を突き止めようとするが…', '2024/08/24 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87ac4ce1-8e11-454e-9cf7-d82f02f2455b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af9e93ff-e9cd-4e46-a911-411f39979e2e', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 9, '100196025', '鬼、統べる者', 'ある日、峠に傷ついた兎鬼が紛れ込んでいた。鬼の身体の刀傷を見るに、仲間割れの末に追い出されてきたようだ。兎鬼の処遇を巡りサクナ達の意見も割れるが、手当をして開放することに。タマ爺は峠に鬼が現れた原因を邪気が強まっているからではないかと推測し、サクナ、ココロワ、アシグモはその邪気を辿って、かつて戦場になった砦に向かうのだった…', '2024/08/31 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11a48ec1-c57d-4f86-83f3-e9b03702943a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('682fccfa-0081-4e73-93a5-3340f4afd872', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 10, '100196787', '再起', '鬼を束ねていた石丸を追い詰めたサクナだったが、島の火山の大噴火が起こり、悪神･オオミズチが復活してしまう。急いで峠に戻るが、峠は焼き尽くされ田はまっ白な灰に覆われており、サクナは愕然と立ち尽くす。なんとか物陰に隠れて難を逃れた田右衛門たちと再会し安堵するも、サクナはこの状況をどう乗り越えたらよいかと打ち拉がれる…', '2024/09/07 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e69ec080-affd-421b-8762-8c2a482dcd5e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4021e7e0-9b1c-400c-8c4e-e2592d8eb9a2', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 11, '100198153', '赦しの光', '石丸に相対する田右衛門。説得を図ろうとするが石丸はかいまるを人質に取る。すると突如かいまるの身にある変化が起き、更に石丸の脳裏に声が響く。動揺して石丸は逃走する。タマ爺とココロワによれば、田右衛門、ミルテ、ゆい、きんた、かいまるは頂きの世にきて生活をしているうちに、神に近い力、神気を宿し神に近づいているという。', '2024/09/14 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/332213a9-9349-4883-bfab-e6a74dd8d2a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b42b3ad4-429f-4f9d-ae3c-5f80398f1784', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 12, '100199141', '星タマ剣', '石丸との戦いに決着をつけ、この島を守るためにオオミズチと戦う事をサクナは決意する。そんなサクナにタマ爺は、オオミズチを倒すためには羽衣の力だけでは足りず、折れた星魂剣の半身たる自身を溶かして打ち直し、新たな武器とするしかないと説く。しかし、そうとなればタマ爺の心は失われ、話すこともできなくなると拒否するサクナなのだった。', '2024/09/21 23:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7770835d-c6fc-496c-bfaa-3de396dd08eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef271faa-c7cc-4b7b-be63-6fd52a49df79', 'ef16aa58-9a1c-4cdd-aff7-2facf071f5ec', 13, '100199834', '天穂のサクナヒメ', '【シーズン1 最終話】祀られることによって、神は力を増す。戦いを前にした皆の心遣いにより峠では祭りが行われていた。そんな中、地震が起こるが、その災いの源たるオオミズチを討つ決意を皆に告げ勇気づけるサクナ。様々な困難を家族･親友･仲間たちと乗り越え、豊穣神として成長したサクナはついに大龍との決戦に向かう!', '2024/09/28 23:30:00', 1626, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/729e2cee-e53a-453a-90d1-f0d44b866459.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4bb7c8dd-d66e-43b4-9c39-b6536ef4f64c', '天穂のサクナヒメ ココロワ稲作日誌', '', 'hulu', 'sakuna-of-rice-and-ruin-kokorowa-rice-cultivation-diary', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88d64d6b-2b96-4407-8c7c-2f8737ca1690.jpg?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'FINISHED', NULL, 184280, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('78f34b5a-cbe4-4eb0-a1a4-9e050d8370de', '4bb7c8dd-d66e-43b4-9c39-b6536ef4f64c', 'hulu-sakuna-of-rice-and-ruin-kokorowa-rice-cultivation-diary-s1', 'ココロワ稲作日誌', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2377d25e-b4f8-4676-a1ef-17223301ac7e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58fa023f-20b6-4050-a91f-d2ada146fd87', '78f34b5a-cbe4-4eb0-a1a4-9e050d8370de', 1, '100253453', '前編', '車輪と発明を司る神でありサクナヒメの親友、ココロワヒメ。小説家としての一面も持ち、「片恋物語」の作者･朧月香子として新たな作品の執筆をはじめようとしていた。一方、神と人が手を携え鬼を払い、稲の実りで満たしたヒノエ島では、サクナヒメたちはいまだこの地で米作りに励んでいる。ココロワはとある事情によって、サクナと同じくこの地で不慣れな稲作に取り組むことになったのだが――', '2026/02/15 17:15:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2377d25e-b4f8-4676-a1ef-17223301ac7e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0c2fc43-f230-4142-8a1c-2598835c1565', '78f34b5a-cbe4-4eb0-a1a4-9e050d8370de', 2, '100254425', '後編', '車輪と発明を司る神でありサクナヒメの親友、ココロワヒメ。小説家としての一面も持ち、「片恋物語」の作者･朧月香子として新たな作品の執筆をはじめようとしていた。一方、神と人が手を携え鬼を払い、稲の実りで満たしたヒノエ島では、サクナヒメたちはいまだこの地で米作りに励んでいる。ココロワはとある事情によって、サクナと同じくこの地で不慣れな稲作に取り組むことになったのだが――', '2026/02/22 17:15:00', 1445, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7def0979-2f4d-4d38-8dc1-f5a46de28aea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('52645fa8-ef6f-44c0-98db-408e0372229c', '転生したらスライムだった件', '', 'hulu', 'ten-sura', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73eac751-443d-4841-91ec-5b20e5c52d26.jpg?w=331&h=447&p=t', 'hulu', 2018, 3, 1, 'FINISHED', NULL, 101280, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('59043dc0-f303-4257-971e-1416b116d90b', '52645fa8-ef6f-44c0-98db-408e0372229c', 'hulu-ten-sura-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f06a6358-3f5b-4b15-ae26-6b18c3552511.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1b37463-0468-4963-8f78-af8b9415fa0b', '59043dc0-f303-4257-971e-1416b116d90b', 1, '100025814', '暴風竜ヴェルドラ', 'サラリーマン、三上悟は通り魔に刺されて死んだ。ところが意識が戻ると三上はなんとスライムへと転生していた! しかも300年前に封じられた暴風竜ヴェルドラが話しかけてくる。スライム三上の運命は…!', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f06a6358-3f5b-4b15-ae26-6b18c3552511.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f82b0f2-4f13-43aa-ab9d-61ef51604a8d', '59043dc0-f303-4257-971e-1416b116d90b', 2, '100025928', 'ゴブリンたちとの出会い', 'スライム三上は暴風竜と友達になり、互いに名前を送り合う。かくしてスライム三上はリムルと名乗ることになった。リムルはヴェルドラを封印から解放しようと試みるが、それは周辺諸国に大きな衝撃を与えることになる。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56ac1c89-d74e-4165-ad42-d6912df16e44.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfc82aa5-a576-4621-8dfe-a39e36c1e036', '59043dc0-f303-4257-971e-1416b116d90b', 3, '100026267', 'ゴブリン村での戦い', '洞窟を出たリムルが出会ったのは、牙狼族の襲撃に追い詰められたゴブリンたち。なりゆきでゴブリンたちの戦いの手助けをするリムル。そしてその夜、ジュラの森の支配者の座を狙う牙狼族が襲ってきた!', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76eb2280-86af-418b-aa5a-9156fa2f26f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f195118-a1d3-46eb-9806-bc7429595370', '59043dc0-f303-4257-971e-1416b116d90b', 4, '100026560', 'ドワーフの王国にて', 'リムルたちは、衣食住を支えてくれる技術者を求めてドワーフの王国･武装国家ドワルゴンを訪れる。ところが入国の際のトラブルでリムルたちは牢獄に囚われてしまう。そこに鉱山でアーマーサウルスが暴れているという報告が入る!', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5a9618e-2d51-404f-8abd-b681d883dbbb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ebcdb20-0ddd-4d1a-b0de-8ec747c43df0', '59043dc0-f303-4257-971e-1416b116d90b', 5, '100026985', '英雄王ガゼル･ドワルゴ', '鍛冶屋カイジンのピンチを救ったリムルは、エルフの店で祝杯をあげていた。そこに現れたのはカイジンを目の敵にするベスター大臣。大臣がリムルをバカにしたため、カイジンはベスターを殴り飛ばしてしまう。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e197b6a-47b9-4d4d-82fb-c5b9fe4efcd6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfd71130-768b-4170-8d95-ac1df947aca2', '59043dc0-f303-4257-971e-1416b116d90b', 6, '100027151', 'シズ', '近隣のゴブリンたちも合流してますます賑やかになる村。そんなある日、リムルは自由組合 (ギルド) の冒険者、カバル、エレン、ギドと遭遇する。そこにはリムルと同じ日本から呼び出された、召喚者のシズもいた。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0f45864-61b5-4e32-9dad-9fbfaae00e55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ca9d5ac-7d38-4abf-bfd3-88a4565292ec', '59043dc0-f303-4257-971e-1416b116d90b', 7, '100027547', '爆炎の支配者', '魔王レオン･クロムウェルによって、空襲に燃える東京から召喚されたシズ。彼女はレオンによって上位精霊イフリートを憑依させられていた。そのイフリートがシズの体を乗っ取り、暴走を始める。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbec74a7-4583-4527-bc74-1d5e5db997d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db5f5cdd-714e-4311-8ae8-dbd2af748ece', '59043dc0-f303-4257-971e-1416b116d90b', 8, '100027653', '受け継がれる想い', '魔王レオンのもとにいたシズを救い出したのはある勇者だった。その勇者のことを胸に、長い間、人々を救うために働いてきたシズ。そしてシズは今、最期の時を迎えようとしていた。シズはリムルに最期の願いを伝える。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62ece287-9bda-4b98-afa7-ae2576ee80cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1e79c14-57c3-42f0-81ad-34c0e2cde2a8', '59043dc0-f303-4257-971e-1416b116d90b', 9, '100028003', '大鬼族の襲撃', 'リムルたちの村の開発は着々と進んでいた。ひとり洞窟で新たなスキルを試していたリムルに救援要請が入る。駆けつけると、6人の大鬼族 (オーガ) がいた。大鬼族 (オーガ) は言う。「正体を現せ、邪悪な魔人め」。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0d5c5ee1-1a90-4e83-991c-503191372553.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b925701-32ba-4551-a994-302e91d2abc6', '59043dc0-f303-4257-971e-1416b116d90b', 10, '100028265', 'オークロード', '大鬼族 (オーガ) たちは、豚頭族 (オーク) の軍勢に襲われた生き残りだった。豚頭族 (オーク) たちは武装し、道化の仮面の魔人も同道していたという。リムルは大鬼族 (オーガ) に自分の部下にならないかと持ちかける。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c15b8ba-5f2b-4c8d-8287-8e38f6697e5e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ee60072-016a-428c-b611-4ccd9b8e671f', '59043dc0-f303-4257-971e-1416b116d90b', 11, '100028609', 'ガビル参上!', '大鬼族 (オーガ) のベニマルたちを迎え入れ、さらに仲間が増えたリムルの村。そこに蜥蜴人族 (リザードマン) のガビルがやってくる。ガビルは、豚頭族 (オーク) の侵攻に怯えるゴブリンの村々を従えようとしていたのだ。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bc4217c-f3d4-40b1-abc2-e67e52cc0fe2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6a6f6b1-cf8f-4572-824f-c6bd9cd382a5', '59043dc0-f303-4257-971e-1416b116d90b', 12, '100028864', '狂いゆく歯車', '災厄の魔物･豚頭帝 (オークロード) と、豚頭族 (オーク) の軍勢がジュラの森を席巻しようとしていた。この危機に動いたのは大森林の管理者･樹妖精 (ドライアド) のトレイニー。彼女は森で台頭してきたリムルに目をつけていた。リムルに豚頭帝 (オークロード) の討伐を依頼する。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec08fe0d-8549-4021-aca7-b1aee12ad35e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8768950-2053-4dd6-8948-13c79b1a76eb', '59043dc0-f303-4257-971e-1416b116d90b', 13, '100029124', '大激突', '蜥蜴人族 (リザードマン) と同盟を結ぶため湿地帯を目指すリムルたち。道中、リムルたちは豚頭族 (オーク) に襲われていた蜥蜴人族 (リザードマン) を助ける。それはガビルの妹だった。ガビルの妹は、先走る兄を助けてもらえるようリムルに懇願する。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58f50d4d-2306-4809-9111-4d313f9fd99f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e70a5ac5-11e6-476b-8b81-aefecfd22176', '59043dc0-f303-4257-971e-1416b116d90b', 14, '100029342', '全てを喰らう者', 'ついに魔人ゲルミュッドが姿を現す。ゲルミュッドの真の狙いは豚頭帝 (オークロード) を豚頭魔王 (オークディザスター) へと進化させ、ジュラの森を支配させることだった。ゲルミュッドの真意を感じ取った豚頭帝 (オークロード) はある行動に出る。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/497ede38-f775-4ba2-b82b-63276aadffa3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5dbfd6f3-8197-4b9b-81a4-8cf92f36a65c', '59043dc0-f303-4257-971e-1416b116d90b', 15, '100029823', 'ジュラの森大同盟', '豚頭族 (オーク) との戦いの戦後処理が始まった。そこでリムルは豚頭魔王 (オークディザスター) ･ゲルドの最期に「リムル自身がオークの罪を背負う」と約束をしたと打ち明ける。それを聞いた蜥蜴人族 (リザードマン)、大鬼族 (オーガ) がとった行動とは…。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/902984f3-8824-4a0e-8dd3-5488d0ed4dda.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('373801ae-3cf5-4999-9a88-5ba09e8e93a1', '59043dc0-f303-4257-971e-1416b116d90b', 16, '100030231', '魔王ミリム来襲', '穏やかな日々が続くある日、破壊の暴君 (デストロイ) のふたつ名を持つ魔王･ミリムが突如、中央都市リムルを襲撃する。その強大な力の前に圧倒されるランガやベニマルたち。果たしてミリムの狙いは…。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d23c51d-aefe-44c3-a588-277c21eec563.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('637d6ae8-3629-4df5-ab89-64178ef67425', '59043dc0-f303-4257-971e-1416b116d90b', 17, '100030476', '集う者達', '中央都市リムルを、魔王･カリオン配下の三獣士のひとり、魔人フォビオが来襲する。だがフォビオはミリムの返り討ちにあい瞬時に倒されてしまう。リムルたちはフォビオに、この国を訪れた目的を問いただす。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b1c027a-d7dc-4895-8d98-dd7103560cc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ace12d5-4df0-4aed-923c-82622137468e', '59043dc0-f303-4257-971e-1416b116d90b', 18, '100030683', '忍び寄る悪意', 'ミリムに負けた怒りが収まらないフォビオ。その前に現れた、中庸道化連の2人の道化は、フォビオも魔王になればミリムに対抗できるとそそのかす。暴風大妖渦 (カリュブディス) の力を使えばそれが可能になると言う。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c6f1da3-5cd9-4a94-a138-b76d4058dd64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc425ca2-c2f8-4d1a-bb69-351a92957006', '59043dc0-f303-4257-971e-1416b116d90b', 19, '100030804', '暴風大妖渦 (カリュブディス)', '封印を解かれた暴風大妖渦 (カリュブディス) は、空泳巨大鮫 (メガロドン) を引き連れて、中央都市リムルを目指して進む。リムルたちは総力をあげてこれを迎え撃とうとするが、暴風大妖渦 (カリュブディス) はあまりに強い。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60762177-4cc5-40e6-91c5-4bd9a325350f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d301ce3-740f-4d6a-a04b-7b2df6f14be4', '59043dc0-f303-4257-971e-1416b116d90b', 20, '100031202', 'ユウキ･カグラザカ', 'リムルは夢を見る。それはシズがイングラシア王国で、召喚された子供たちの先生をやっている夢だった。シズの未練を晴らすため、イングラシア王国の王都を目指すことを決めるリムル。そこにはシズの教え子たちが待っているのだ。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c780daad-b656-4c2f-8676-2717be2a884a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('455112bb-fcc3-4009-869f-de4f092e83d7', '59043dc0-f303-4257-971e-1416b116d90b', 21, '100031748', 'シズさんの教え子達', 'シズの教え子たちの先生となるリムル。しかし、一方的に召喚され、限られた寿命となった子供たちの胸中は複雑で、リムルにも反抗的な態度をとってくる。そこでリムルは、模擬戦をしようと子供たちに持ちかける。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4f0653b-40a7-44a8-b78d-8c081873a3ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f496fdd-dbcb-40ef-8853-2788964e63bb', '59043dc0-f303-4257-971e-1416b116d90b', 22, '100031913', '迷宮攻略', '自由学園の子供たちはやがて死ぬ運命にあった。だが、リムルは上位精霊を宿らせれば子供たちを救うことができると考える。そこでリムルは子供たちとともに、上位精霊がいるという「精霊の棲家」へと足を踏み入れる。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fded5686-0e32-4d68-9369-3f44fd4c2776.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9275b960-fdfd-44e7-bbae-6c268d25151f', '59043dc0-f303-4257-971e-1416b116d90b', 23, '100032321', '救われる魂', 'うまく精霊を呼び出すことができるのか。精霊の棲家の最深部にたどり着いた子供たちは、順番に光の台座の上で精霊を呼び出すことに挑戦する。それを見守るリムル。そして、子供たちに応えるように姿を現す精霊たち…。', '2020/07/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a76caf12-0936-4272-9b5f-5d7898429dee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d07b87a-0db0-417d-ae28-94b23fdd8c77', '59043dc0-f303-4257-971e-1416b116d90b', 24, '100032892', '外伝：黒と仮面', '【第1期 最終話】これはリムルが転生してくる前の物語。フィルウッド王国が多くの冒険者を集めて、復活した悪魔の退治を依頼する。そこには「爆炎の支配者」の二つ名で知られるシズの姿もあった。だがこの依頼には大きな裏があった。', '2020/07/01 00:00:00', 1426, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4cd49cc0-0373-4910-844f-910ce9217d6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('aafc9fdd-6800-425d-a1fa-e667aa931131', '52645fa8-ef6f-44c0-98db-408e0372229c', 'hulu-ten-sura-s2', '第2期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccc8e61e-4d82-443c-a76e-1bd04baf16ae.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63adea62-bf8c-4e8c-9f37-b5f80f4a4e2a', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 24, '100072410', '閑話:ヒナタ･サカグチ', 'ヒナタは、「ジュラ･テンペスト連邦国」について書かれた親書を受け取り、リムルの存在を知ることになる…。新章への予感とともに、リムルの歩みを振り返る特別編。', '2021/01/06 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccc8e61e-4d82-443c-a76e-1bd04baf16ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2557512e-61a5-4b70-8fa6-c04573fcd0cf', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 25, '100073377', 'リムルの忙しい日々', '魔王カリオンの治める「獣王国ユーラザニア」との国交を結ぶことになったリムル。相手の使節団を迎え、もてなす準備をしていたが、やってきたのは大型魔獣白雷虎 (サンダータイガー) が牽引する、物々しい虎車だった。', '2021/01/20 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2394eafb-34e2-44d8-8e4d-c9c44a0fc11f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a67a01a0-4f4f-4eda-ba4d-df8ad4c5e467', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 26, '100073823', '獣王国との交易', '一悶着あったものの、ユーラザニアとの国交を結ぶことができたリムルは、続いて武装国家ドワルゴンにて行われる友好宣言の式典へ赴くことに。ところが、自分も同行させて欲しいと駄々をこねるシオンが大暴れして…。', '2021/01/27 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62cebc3f-1315-4214-a196-08499cf6dbac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9d37a40-073f-45a0-bef0-5333f33e0a28', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 27, '100074485', '楽園、再び', 'ガゼル王との会談と、武装国家ドワルゴンとの二国間友好宣言に伴う民衆への演説。ふたつの大仕事を終えたリムルは、シュナとシオンの目を盗んで、かつてゴブタと約束した「あの楽園」に意気揚々と向かうのだった。', '2021/02/03 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47af3077-ca17-4805-bd85-9a6b0c805fd7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90ba36b6-0925-4aad-9aea-9d04c8f648fa', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 28, '100074673', '謀略のファルムス王国', 'リムルの帰還を控え、宴の準備を進めるテンペスト。そこに、ヨウム一行が新メンバーの魔導士 (ウィザード) ミュウランを伴い到着。一方、ファルムス王国では不穏な動きが…。', '2021/02/10 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba51039a-995b-49c5-b3bc-44ca65c99118.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('864fa82e-4c76-4d19-9ea9-4f7dcd69c541', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 29, '100075712', '災厄の前奏曲', 'クレイマンの指示により行動を起こすミュウラン。そしてもう一つの勢力――ファルムス王国が送り込んだ三人の異世界人が、盟主不在のテンペストに牙をむく。', '2021/02/17 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d12ecf30-6cfc-41b4-9a83-eee83abf4225.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae8c5558-a903-4a34-a355-c3461d9139bf', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 30, '100076067', '動き出す麗人', 'テンペストが攻撃を受ける中、リムルの前にも刺客が現れる。それは、シズのもうひとりの教え子である、最強の聖騎士 (ホーリーナイト) ――ヒナタ･サカグチであった。', '2021/02/24 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d74f661d-4847-4586-8552-f7515817d2db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82ac74ee-181c-4982-b3c8-20f84b0adc8c', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 31, '100076564', '絶望', 'ヒナタとの戦闘で絶体絶命の状況に陥り、最後の手段、暴食者 (グラトニー) を発動したリムルの運命は――。その頃、テンペストは悲壮な血と煙に包まれていた…。', '2021/03/03 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1dd64107-1f9b-4333-a3be-0c5f3f034242.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bedaaef1-91bc-4c11-8d47-ad8f2a1efed2', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 32, '100077403', '希望', 'クレイマン、そしてファルムス王国の企みを知るリムル。仲間の命と温かな日常を失い、失意の底で目を伏せるリムルの耳に飛び込んだのは、エレンの意外な言葉だった。', '2021/03/10 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88eebe8a-e592-4c80-bfd4-c270d0abfc4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17bd3535-4ecc-4219-9313-0af4127a2b8c', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 33, '100077682', '全てを賭けて', '「俺は魔王になろうと思う」――自らにケジメを付け、シオンたちを蘇生させるため、決戦を前にリムルは仲間たちに人間だった過去を打ち明ける。', '2021/03/17 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbc8392a-a737-4549-81e8-dcd94fbd5d20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7fa242c-03da-46f1-9651-491cd7aebdfb', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 34, '100078147', '神之怒', '雪辱戦の口火がきられた。ベニマル達は各々の任務を遂行していく。ハクロウたちも再度ショウゴとキョウヤとの戦いに挑む。そしてリムルの怒りが、ファルムス軍を包みこむ。', '2021/03/24 12:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebe42236-6252-43f7-9a12-17090c659dc6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84c4f76b-3e1e-4020-bcf1-b5ba690c08d2', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 35, '100078651', '魔王誕生', '進化に必要な魂を確保したリムルに「魔王への進化 (ハーベストフェスティバル)」が訪れる。強烈な睡魔に襲われたリムルは、取り逃した敵を捕らえるため、悪魔を召喚する。', '2021/03/31 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f87d7b83-4024-4065-9768-a394c78b05d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e7e110b-5ee0-47c4-8ce8-ff796bb2252f', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 36, '100079402', '解き放たれし者', 'ファルムス軍を退けて、何とか事なきを得たテンペストだが、問題は山積みで……。そんな中、智慧之王 (ラファエル) から「無限牢獄の解析に成功した」と吉報が舞い込む。', '2021/04/07 12:00:00', 1417, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6062b8b7-d892-4bcd-9745-44745a93ae61.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e28dd47f-bc4e-46c7-8b22-95741c8342cf', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 37, '100086824', '訪れる者たち', '仲間達の蘇生とヴェルドラの復活。それを祝した宴も終わり、今後の方針について会議が始まる。リムルは全世界に向けて魔王を名乗り、クレイマンへの宣戦布告を決意する。', '2021/07/14 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1678d6ca-6690-4422-ba4a-fb577eaa5fd9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4db8ca20-d6c8-4746-82d3-cbf6013f6d12', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 38, '100087030', '人魔会談', 'テンペストで各国の要人が集まり会議が開催される中、ラプラスたちはクレイマンにまつわる計画を企てていた。そこには、とある人物も同席していて―――。', '2021/07/21 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a692799-b416-41c4-b3f4-6487096f9a95.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('103088a3-98c5-4d1f-b1b3-45116eaf85e0', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 39, '100087437', 'ラミリスの報せ', 'リムルはファルムスの新たな王にヨウムを擁立するという計画を発表。それを聞いたガゼル王はヨウムに覚悟を問う。そんな会議の様子を黙って聞いていたエラルドだったが…。', '2021/07/28 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2cfa26f2-cfa2-4535-823d-3b520b3d1a51.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5df6fe4-f46d-45a6-8db1-f5db4bdedb8b', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 40, '100087972', '会議は踊る', '「ジュラの大森林の新勢力であるスライムが魔王を騙ったため、制裁する」という議題で、クレイマンがワルプルギスを発議した。リムル達はクレイマン討伐に備えるが…。', '2021/08/04 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1827e3eb-28ce-4b55-b680-b1578e71d2e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcd05279-019f-45c4-985d-7283d3225ede', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 41, '100088135', '会戦前夜', 'ユーラザニアの民の救出、クレイマン軍への対抗。後手に回ったリムルは「智慧之王 (ラファエル)」からの助言を受ける。さらに、クレイマン討伐の策は秘書からの進言で!?', '2021/08/11 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc60b1f5-a275-4569-b54d-139e1ea1ce0e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8375c14d-2fd0-4055-b6ea-ed94ad69d63d', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 42, '100088990', '魔王たち', '予想外の抵抗を見せるリムルに、怒りを募らせるクレイマン。一方、最古の魔王ギィと魔王レオン、そしてヴェルドラの姉ヴェルザードは、リムルへの関心を強めていた。', '2021/08/18 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93cff788-bac0-4b4a-b24b-5285720eac6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0ce5a91-df44-41df-9f1f-646ad4c6a5c4', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 43, '100089536', '開宴の合図', '転送魔法で一気にユーラザニアに到着したベニマル達。ついにリムルVSクレイマン両軍が激突する。カリオンの生存を信じる三獣士はテンペスト軍と共に敵軍将の討伐に挑む。', '2021/08/25 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58224633-1a9e-49dd-be06-a1ec6ec392cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fa8c23d-2a4f-4fec-8886-399b5fa88135', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 44, '100089939', '因縁の地で', '依然として激しい戦いが各地で繰り広げられる中、三獣士のスフィアは竜を祀る民、ミッドレイに苦戦を強いられていた。一方のアルビスはヤムザを追い詰めるが…。', '2021/09/01 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc8b0cc5-ec46-46b8-a7d3-8bd85d2151e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97c8aad4-1c1c-41b5-af3d-6990f3ed5130', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 45, '100091049', '示指のアダルマン', 'リムルは、ついに魔王達の宴 (ワルプルギス) へと赴く。一方で、シュナたちもクレイマンの領地に向けて出発するが、城の近くに到着すると同時に敵の妨害を受けてしまう。', '2021/09/08 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85089e75-53bd-49db-882f-3fa569a8b873.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02259ebc-fd57-42ee-9d16-cedee9f397ce', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 46, '100091347', '魔王達の宴 ～ワルプルギス～', 'リムルとクレイマンの一騎打ちになるかと思いきや、クレイマンは洗脳したミリムをけしかける。ミリムの相手はリムルが引き受け、クレイマンはシオンが迎え撃つことに。', '2021/09/15 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/797c2dad-3522-4e8e-8122-0e46acc79b52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ecb0ac9-3d3a-45cb-848a-1f99b1fa656c', 'aafc9fdd-6800-425d-a1fa-e667aa931131', 47, '100091962', '起死回生', 'クレイマンの手駒も、クレイマン自身も、リムル達に全く歯が立たない。窮したクレイマンは、ミリムに狂化暴走 (スタンピート) を発動させ、皆殺しにするよう命じる。', '2021/09/22 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83fe3ec4-4dc6-44db-93f8-2ee5a87bf5e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8306ebd2-4885-4721-9692-2fdd5a4ea296', '転生したらスライムだった件 コリウスの夢', '', 'hulu', 'that-time-i-got-reincarnated-as-a-slime-coleus-dream', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bab742c5-f851-4de6-a503-6a893049a401.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 161802, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8bcb487c-045f-40cf-b601-ebb63e6c835f', '8306ebd2-4885-4721-9692-2fdd5a4ea296', 'hulu-that-time-i-got-reincarnated-as-a-slime-coleus-dream-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3dfba085-9c34-4530-8738-b5bdf49c4016.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('834d3ab8-f083-4507-8b3e-f5e1881d7383', '8bcb487c-045f-40cf-b601-ebb63e6c835f', 1, '100163398', 'コリウス国へ', '教師生活もあとわずか。そんなリムルのもとに「コリウス王国の王位継承争い」の調査依頼が舞い込む。次期国王候補のサウザー王子とアスラン王子。ギルド本部はどちらに加担するか、判断材料が欲しいという。', '2023/11/01 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3dfba085-9c34-4530-8738-b5bdf49c4016.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a1d88cb-398e-45e4-a424-e93431db4699', '8bcb487c-045f-40cf-b601-ebb63e6c835f', 2, '100163399', '大怪盗サトル', '両王子の衝突は回避できない。アスラン達の足止めを命じられ、ベニマルとソウエイが参戦しバトル勃発。そこに降り立ったのは、王女をさらった大怪盗サトルだった!', '2023/11/01 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/993b9e5b-31e1-4c42-8921-48c19fc15471.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f69bc99-ca5f-4317-b4aa-1723ab83af58', '8bcb487c-045f-40cf-b601-ebb63e6c835f', 3, '100163400', '紫と薔薇', '【最終話】グスタフとカールの陰謀を暴いたリムルだが、王子達と共に結界に閉じ込められてしまう。結界の外では驚いたことに、ルミナスとヴィオレが激突し始めていた。', '2023/11/01 00:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09879b65-1c94-4c14-8d5a-84b02b5995f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('38d81265-fc4b-4399-986b-279c9d28fa04', '転生したらスライムだった件 転スラ日記', '', 'hulu', 'that-time-i-got-reincarnated-as-a-slime-the-slime-diaries', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90b64fd5-305d-44b3-b84a-1404b1d6a7d2.jpg?w=331&h=447&p=t', 'hulu', 2021, 1, 1, 'FINISHED', NULL, 116741, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2790bec5-3f91-4b11-a138-1f0cd621cc8e', '38d81265-fc4b-4399-986b-279c9d28fa04', 'hulu-that-time-i-got-reincarnated-as-a-slime-the-slime-diaries-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87fc27a0-dd45-4ed1-a17a-875909fea913.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19d36c61-e6f1-47d4-9c54-f94ab013f65a', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 1, '100079883', '魔物の町の住人たち', '壮大なスライムライフを送っているリムルは、その半生を日記に綴ろうとした…が、色々ありすぎて筆が止まってしまった。しかしそれもテンペストの日常である。', '2021/04/14 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87fc27a0-dd45-4ed1-a17a-875909fea913.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5c72a1be-da8b-4706-a2a9-86e34bbc13a2', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 2, '100080156', '春の空気と', 'テンペストにも春が来た。町の自給率向上のため、広大な畑を耕して野菜を育てることに― ― 。一同はリムルの呼びかけによって、種族を超え、畑仕事に精を出すのだった。', '2021/04/21 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff225aae-7835-4171-a7bc-db9a17fe9b72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c9f4680-77b8-4c66-a32b-f01c0fb032fe', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 3, '100080577', 'ジュラの夏', 'テンペストに夏が来た。一昔前はそこまで暑くなかったらしく、自分のせいかもと冷や汗をかくリムル。気分を変えて夏の風物詩――「虫取り」をゴブタたちに教えることに。', '2021/04/28 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/42e43dce-6c8c-4638-89b8-5517dcd78a85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7010e362-001d-4cc2-b7c4-d8676a7a576a', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 4, '100081127', '水着で一日', '猛暑のテンペスト。涼しげな湖に下見に来たリムルたちは、水着に着替えて思い切り遊ぶ…ものと思われたが、シュナとシオンは何故か不満げで…。', '2021/05/05 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eff24889-ef7c-4f08-a8e0-4d036e28881f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ea2a1e1-d11e-49e3-9192-07639bc151df', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 5, '100081778', '再現ナツマツリ', '日本の夏の宴「ナツマツリ」をここでもやりたいと考えたリムル。屋台で作るたこ焼きにかき氷、浴衣に盆踊り、そして花火。魔物たちは一丸となって準備を始める…!', '2021/05/12 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4da498e3-ad15-461d-93a4-d51e5be48140.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53c0a2ab-0f12-4149-b5d2-5d5c0a612fe0', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 6, '100082359', 'うつろいかわる', 'お盆の季節。シズさんが人魂をまとって帰ってきた! 自分の似姿で暮らしているというリムルの様子を見に来たら…そこにはバニー姿のリムルが!?', '2021/05/19 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0ae4cd5-9347-4fc3-8df1-275335dfef68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b062c03e-38f5-466b-8f05-d4863cbff771', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 7, '100082882', '魔王が来た!', '順風満帆に見えるテンペスト…そこに最古の魔王、ミリム･ナーヴァ来襲! テンペストどころか、タイトルまで侵略され、「ミリム日記」――開幕!', '2021/05/26 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0437852b-cc44-4f9b-a569-2afff940b836.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8555c2fa-065e-4502-8bba-68721ce17eb0', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 8, '100083514', 'みのりの秋', 'テンペストに秋が来た。今や町の文化レベルは上がり、衣食住も安定し、秋の味覚を楽しむ余裕すらある。その余裕を冬に持ち越すため、皆で力を合わせた収穫祭が始まる!', '2021/06/02 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0e9a3c1-26dd-4767-957b-2fccf6e2de9d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fbd3e3d-39ba-436e-8d88-cc1a48c63f4b', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 9, '100083894', '冬のおとずれ', '収穫祭から季節は移ろい、あっという間に冬が訪れた。冬は、火事の危険が高まる季節。そこでリムルは古き良き見回り文化「火の用心」キャンペーンを実施する。', '2021/06/09 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0203dfbd-67a3-4588-ad4a-5fed1ba5e6fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09665d5b-5ff1-4fc1-b280-40f46d77d898', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 10, '100084376', '魔物の町の雪化粧', '雪かきをしないとドアが開かない程の積雪。テンペストに本格的な冬が来た。雪にダイブしたい衝動…童心を秘めた同族が少なくとも3人はいるようだ。', '2021/06/16 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e94536c-daad-4628-a111-34ca006fbf04.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d490a9d3-f82c-4d53-b602-8b408a04da1c', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 11, '100084666', 'サンタクロースはどこにいる', '「ひょっとしてサンタさんって異世界人?」 素っ頓狂なリムルの思いつきは、前世の世界よりもずっとメリーなクリスマスを実現! …だが恋人同士は許さんよ。', '2021/06/23 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a691db90-878e-49cf-85b0-cdbf5ecc0ab6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a2da933-00c1-4263-ac9d-7b8f2c67f734', '2790bec5-3f91-4b11-a138-1f0cd621cc8e', 12, '100084984', '正月を満喫', '【シーズン1 最終話】「あけましておめでとう」…怒涛の年末を乗り越えたテンペストは、めでたいめでたい鏡餅リムルで年始め! お正月用の特別な礼装に身を包み、みんなで新年を迎える。', '2021/06/30 12:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68fa8eac-f60c-4728-bf22-aed20ec7c77b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1e23c109-fc47-4c4e-b545-c5381fa82f5f', '転生したらドラゴンの卵だった', '', 'hulu', 'reincarnated-as-a-dragon-hatchling', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92afda26-f0cf-44c1-b954-c1c2c732475c.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'RELEASING', NULL, 187941, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', '1e23c109-fc47-4c4e-b545-c5381fa82f5f', 'hulu-reincarnated-as-a-dragon-hatchling-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f813538c-b558-4fc1-bc06-91cc9da78506.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d8ef99a-1093-4c97-a1bc-ca92a72cd301', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 1, '100249818', '転生したら卵だった', '森の中で目覚めた主人公。身動きも取れず、何とか転がることでたどり着いた泉のほとりで見た自分の姿は“ドラゴンの卵”だった。持っている能力は転がることのみ。味は珍味かつ美味。そのためドラゴンエッグは森に住む様々な魔物に命を狙われることになる。殻が割れないように身を守りつつ、迫りくる魔物から逃げるドラゴンエッグに、謎の声が語り掛けてくるが…。', '2026/01/15 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f813538c-b558-4fc1-bc06-91cc9da78506.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56007c64-478e-4092-b299-82632901c20b', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 2, '100249819', '勇気を出したら嫌われた', 'ようやく人間であるミリアとコミュニケーションが取れた主人公のベビードラゴンだったが、その矢先にリトルロックドラゴンの襲撃に遭ってしまう。ミリアたち冒険者もやられてしまうが、今のベビードラゴンの体力ではリトルロックドラゴンに勝てる方法は無い。今すぐ逃げないと殺されてしまう状況だが、ベビードラゴンはなんとかミリアたちを助け出そうと、ある行動に出る。', '2026/01/22 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/efe562ce-96c2-421f-a495-54374341f54d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3b650b1-b79e-4f95-b5c1-d60c00916553', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 3, '100249820', '進化したら快適だった', 'リトルロックドラゴンから逃げ切ったベビードラゴンは更にレベルを上げ、進化条件を満たす。進化先を確認していくと、あるドラゴン種が持つスキルの中に【人化の術】という、人間の姿になることができる能力を見つける。そのころ、ミリアは自分がリトルロックドラゴンの襲撃を受けた際に、ベビードラゴンに助けられて生還したということをマリエルに相談するが…。', '2026/01/29 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4023a14a-ae0e-4144-8ec7-a271ed1a4bb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d9f2d52-3bc7-4c41-abb7-60e32e3b07d3', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 4, '100249821', 'ツボかと思ったらカメだった', '厄病子竜に進化したことでスキルが増え、生活の質が一気に向上した主人公。さらなるQOL向上のため、厄病子竜は森で野菜や調味料、更には食器を見つけるべく散策に出る。ミリアはマリエルに無断で、一人森の中に入って行ってしまう。しかし時同じくして森の村に、行方不明になっているドーズを捜索する依頼を受けた冒険者のメルティアとユノがやってくる。', '2026/02/05 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6c0a100-d455-4c14-8367-826a2c3363de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61849082-2283-4582-9fd5-7e2b40866e3c', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 5, '100249822', '毒女かと思ったらヨメだった', '突如森の中で黒蜥蜴に襲われた厄病子竜。身体に回った毒を浄化するため、厄病子竜は黒蜥蜴を生きたまま捕まえようとする。しかし黒蜥蜴は高速の“転がる”スキルでその場から逃げ出してしまう。厄病子竜は毒に苦しめられつつ、残された力を振り絞って黒蜥蜴の追跡を開始する。マリエルは近頃ミリアの姿を村で見かけないことを不審に思い、ミリアの元へ向かう。', '2026/02/12 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a4e777d-dc72-4c91-8d0a-c0c08730f156.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93e349c6-4dee-442d-9d68-4bb3cbdf42c0', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 6, '100249823', '人間になったらシバかれた', '黒蜥蜴との同居を始めた厄病子竜は、楽しく二匹で生活していた途中でスキル“人化の術”を取得する。やはり人間と一緒に生活する夢を捨てきれない厄病子竜は、ついに“人化の術”を発動させる! 同じころ、行方不明になったドーズを捜索していた冒険者のメルティアとユノは、森の中で装飾品に囲まれた不思議な洞窟を見つける。そんな二人の前に、二本足で立つ謎のクリーチャーが現れる。', '2026/02/19 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7a845cd-f610-43ec-ab9b-bb873629e218.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf2ecb13-df02-4f27-9a45-7e8e42f46251', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 7, '100249824', 'デートに行ったら放置された', '自分で作った干し肉をかけて、厄病子竜は大猩々と熱いバトルを繰り広げる。黒蜥蜴と猩々が見守る中、拳の応酬の末についに勝者が決定する…。メルティアとユノは森の中で厄病竜を目撃したため、応援の冒険者を呼ぶために大きな街まで一度撤退する。そうとは知らないミリアは、森に入った冒険者二人の帰りを待ちきれず、また一人で森の中に入ってしまう。そこで彼女は森を移動する人影に遭遇する。', '2026/02/26 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45b0d0dc-60a8-416c-acc5-0596dd34a8ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfe48b0d-3821-4dde-b37d-6e08f4748845', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 8, '100249825', '考えたら名前なかった', 'ついにミリアと再会を果たした厄病子竜。魔物たちの撃退にも成功した厄病子竜は、なんとかミリアとコミュニケーションを取ろうと奮闘する。そんな中、ミリアが厄病子竜に問いかける。「ドラゴンさん、名前ってありますか?」一方そのころ、何者かによって操られた魔物がミリアの暮らす村へ一直線に向かっていた。そのモンスターの背中には、長らく森の中で行方不明となっていたある人物の姿が…。', '2026/03/05 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af766399-2f3f-4f6d-a318-36a4a270853a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1441eed1-d77d-481e-958e-a1b2a546aff8', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 9, '100249826', '村に行ったら修羅場だった', 'ドーズの持つ卵を追って、ミリアの住む村まで現れたリトルロックドラゴン。村人を助けるため、イルシアとミリアは一目散に村を目指す。しかしその村はかつて、傷ついたミリアを届けたにも関わらず、モンスターであるというだけでベビードラゴンだったイルシアに、村人たちが槍を突き刺し追い出したあの村だった。再度ミリアを背負って村までやってきたイルシアの前に、槍を持った村人が立ちはだかる。', '2026/03/12 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a24306a-13e7-40b1-b171-6c3eedb6f7f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2158a7db-e48b-4020-aacd-037d0d947abb', 'b8ae0eac-c67c-4c72-8f6b-b5e8742da85e', 10, '100249827', '進化したら邪竜だった', 'リトルロックドラゴンに蹂躙され壊滅的な被害が出ている村にて、イルシアはただ一匹、人間たちを逃がすために必死に奮闘していた。しかしリトルロックドラゴンの力は強大で、今のイルシアには成すすべもない。リトルロックドラゴンに勝つためには、進化によって更なる力を手に入れる必要があるが、それは人間とは二度と相いれない、邪竜への入口だった…。', '2026/03/19 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91cc4db8-be0f-4b3a-b761-450b57543812.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e22044c3-3459-45ea-96a7-4fc573a93051', '転生したら剣でした', '', 'hulu', 'reincarnated-as-a-sword', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f4fd0f3-cdf4-4c12-96da-729f9cb8265f.jpg?w=331&h=447&p=t', 'hulu', 2022, 3, 1, 'FINISHED', NULL, 139587, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9c54250c-5009-40cc-b068-b3c42dfb5ec7', 'e22044c3-3459-45ea-96a7-4fc573a93051', 'hulu-reincarnated-as-a-sword-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ca1cdb1-ae04-4af0-9bf1-da416348dce9.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a0852be-7d74-442c-bcb5-5888ab83e315', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 1, '100168710', 'モフ耳が出会ったのは剣でした', '不慮の事故で異世界に転生し、剣になってしまった“彼”。奴隷として虐げられ、魔獣に襲われる黒猫族のフラン。強さを与えたい者と強さを求める者、その2人が邂逅する――', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ca1cdb1-ae04-4af0-9bf1-da416348dce9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9c6b027-85e3-471d-811b-d4462d98ed7b', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 2, '100168711', '冒険者ギルドに行ったら鬼試験官でした', 'ゴブリンに襲われていた商人を助け、彼を護衛しながらアレッサの街へ行くことになった師匠とフラン。冒険者になるためにギルドを訪れるが、試験官と戦わなければならず……', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/351addad-cf24-47aa-8284-8d6eff0dea89.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45e1686b-3eeb-460b-8ef8-62a68abf3eac', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 3, '100168712', '魔法鍛冶師は曲者でした', 'フランはギルドでの立ち回りから腕利きの魔法鍛冶師ガルスに見込まれ、初めての防具を手に入れる。だが、師匠が「知性を持つ武器 (インテリジェンス･ウェポン)」であることを見抜かれてしまい……', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ea1c670-9878-4a1c-a48c-9263c3edb194.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('339b23df-2825-4aa9-a14b-8512414f5209', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 4, '100168713', 'ゴブリンスタンピードはオオゴトでした', '100体以上のゴブリンを撃破し、師匠とフランはアレッサへ帰還。ゴブリンスタンピードが始まろうとする中、ギルドでは討伐隊が組まれ、フランもその一員に選ばれる。', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4be0246b-50f1-4319-9fc7-2dee27a1877c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6a6c897-ea2c-48a0-9020-a959fc45854d', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 5, '100168714', 'ダンジョンデビューは無双でした', '師匠のサポートもあり、手際よく魔石を回収しつつダンジョンを攻略するフラン。やがてゴブリンキングとクイーンの元へ辿り着くが、ホブゴブリンの群れが立ちはだかる!', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6eb73fcb-bdc2-48e4-aa9c-4145fa713fd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('856a5dea-66a0-4323-bda8-528fa09befcb', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 6, '100168715', '上級悪魔 (グレーターデーモン) はチートでした', 'グレーターデーモンに追い詰められた師匠は、フランに撤退を勧める。だがアレッサを守りたいフランは、決して諦めない。師匠も覚悟を決めるが、決定打には至らず……!?', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1cbdd15-5f72-4024-9a83-4fdaeca50b3d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7022f751-8c17-40ed-ac76-c932cd215ca8', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 7, '100168716', '騎士団副団長はヤな奴でした', 'アレッサ騎士団の副団長オーギュストが現れ、嘘を見抜くスキルでクリムトに理不尽な要求を突きつける。その態度に怒りを滲ませるフラン。それを見た師匠はある提案をする。', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f1041fd-df93-4f1e-8d4d-5680cc8e3c98.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61c632a6-a93c-43c2-9822-791f892ecf94', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 8, '100168717', '青猫族は仇敵でした', '数多く黒猫族を殺害してきたギュラン。フランは怒りを爆発させ、覚悟を決める。一方、アレッサの街にはある女性冒険者が帰還する。彼女はフランの「ママ」を名乗り……!?', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8df6bd90-624e-40d2-8f13-15ca8022618d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63a73671-933f-477a-a160-4ff0b0360009', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 9, '100168718', 'ランクA冒険者はバケモノでした', '「蜘蛛の巣」の調査メンバーと合流したフランたち。いきなりランクEパーティのクラッドに絡まれ、野営の際に模擬戦を挑まれてしまう。クラッドを圧倒するフランだが……', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf7ea005-32e5-4309-88d3-7b4b31e2e509.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e61d0e41-db8d-49b5-8bb6-47d199652b6a', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 10, '100168719', '蜘蛛のトラップは反則でした', 'クラッドたちの活躍もあり、調査メンバーは順調に「蜘蛛の巣」を進んでいく。その道中、フランはアマンダから戦技、スキル、魔術について積極的に学ぼうとする。', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5707a48f-4b94-4b82-80a2-d048cded3a81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a49b1f8-3b9b-478c-8c90-8ff1d0f3114f', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 11, '100168720', '召喚したら魔狼でした', 'フランを見つけるため、師匠はアマンダに正体がバレることを覚悟して、召喚魔術を使用。しかし召喚したオニキスウルフが暴走し、アマンダに敵と見なされてしまい……!?', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6341c46d-0c1f-4735-897a-352d91f47dfa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da414013-bea6-478d-8638-e29385c4cc60', '9c54250c-5009-40cc-b068-b3c42dfb5ec7', 12, '100168721', '旅立つフランはワクワクでした', '【最終話】クルスたちも転移させられ、トリック･スパイダーの大群に襲われていた。仕掛けられた罠まで発動し、絶体絶命の危機に。果たして、フランと師匠は間に合うのか……!?', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b0970d9-ebc5-4877-8baa-be2950860b34.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9dec882b-2741-4a23-a9c4-16254f08b777', '転生したら第七王子だったので、気ままに魔術を極めます', '', 'hulu', 'i-was-reincarnated-as-the-7th-prince-so-i-can-take-my-time-perfecting-my-magical-ability', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/744c7dc2-564b-4e73-981a-658b01179939.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 156415, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9bf892de-7701-45d9-999f-7b526f446d9d', '9dec882b-2741-4a23-a9c4-16254f08b777', 'hulu-i-was-reincarnated-as-the-7th-prince-so-i-can-take-my-time-perfecting-my-magical-ability-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/338a4ae1-cd95-4d86-8936-548f0e30712a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82a38ff8-afba-4614-8073-062b7be6ce5a', '9bf892de-7701-45d9-999f-7b526f446d9d', 1, '100180119', '第七王子に転生しました', '才能に恵まれず息絶えた男は、魔術の血統と才能に恵まれたサルーム王国の第七王子･ロイドに転生。そんなある日、封印書庫へ潜り込み、禁書の魔人を目覚めさせてしまう…。', '2024/04/05 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/338a4ae1-cd95-4d86-8936-548f0e30712a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d91169d8-0b3c-4ffd-9953-4030c96422fa', '9bf892de-7701-45d9-999f-7b526f446d9d', 2, '100180886', '冒険者に遭遇しました', '魔人グリモワールを使い魔として従えたロイドは、ダンジョン探索へと向かう道中で、“気術”を使う武術家･タオと出会う。タオの気術に興味を持ったロイドは、彼女と共にダンジョンの最深部へ向かうのだった。', '2024/04/12 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f2bbf19-ce9d-4478-9ff9-3958cdce2ae5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25c8da11-784c-4aa8-a52c-6ca8898434fe', '9bf892de-7701-45d9-999f-7b526f446d9d', 3, '100181744', '気術とか付与魔術とか', 'ダンジョンの奥に待ち受けていたのは、多くの冒険者たちを葬ってきた魔人･リッチ。タオはとっさにロベルトを逃がすものの、魔人には歯が立たない。満身創痍の彼女にトドメを刺そうとするリッチの前に現れたのは…?', '2024/04/19 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b393835-c280-49ec-ad2a-5632d6537726.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f602ba4-6ad8-4b13-aaa6-ee8262268455', '9bf892de-7701-45d9-999f-7b526f446d9d', 4, '100182364', '魔獣狩りに向かいます', 'ロイドは自身が魔術を付与した武器の完成具合を見るため、アルベルト、シルファ、タオらと共に、魔獣狩りに魔獣の湖へと向かう。しかし、そこで不自然なほどに高い再生能力を持つ魔獣ベアウルフたちに遭遇する…。', '2024/04/26 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a1c4ae0-9a6c-441d-81c8-eb7730e234ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('330e4365-953c-43d2-ae21-a0a52527bdd3', '9bf892de-7701-45d9-999f-7b526f446d9d', 5, '100183229', '魔人が苛立っています', 'シルファの活躍によってベアウルフたちを倒したかに見えたが、魔人･パズズが放出する瘴気により、一転して窮地に陥ってしまう。シルファとタオも反撃できない状況に追い込まれる中、ついにロイドが動きだす。', '2024/05/03 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47e234c1-165a-4d41-b427-a38c1f562420.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54648c30-7a0c-41c2-9289-e075f09352ee', '9bf892de-7701-45d9-999f-7b526f446d9d', 6, '100183740', '姉と魔獣と魔剣と兄と', 'ベアウルフのシロを従えたロイドは、魔獣と心を通わす秘訣を知るべく、第六王女･アリーゼに教えを乞う。その後、鍛冶技術を極め最強の「魔剣」完成を目指す、第四王子･ディアンと再会し、「魔剣」作りに励む。', '2024/05/10 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bced686-5869-46eb-9e84-3a9b9308ad3d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63fd2ec3-49c1-483f-bb69-7688b062c89c', '9bf892de-7701-45d9-999f-7b526f446d9d', 7, '100184443', '暗殺者たちとバトルします', 'ロイドは暗殺者ギルドの少女･レンの「毒のノロワレ」と呼ばれる能力を知り、ほかの暗殺者ギルドメンバーの能力にも興味を持つ。レンの後を付け、彼女らのアジトへ忍び込んだロイドに、暗殺者たちが襲い掛かる…。', '2024/05/17 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2af9e6a1-ed80-4ae4-b692-06d7f7fe01dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b2e4a88-4212-465c-89b8-0aa95e310295', '9bf892de-7701-45d9-999f-7b526f446d9d', 8, '100184912', 'ジェイドに会いに行きます', 'ロイドは、暗殺者ギルドのメンバーであるジェイドの「空間転移」の能力に興味を持つ。そして、ジェイドからの手紙に導かれ、ロードスト領主邸にてジェイドと出会う。再会を喜ぶ暗殺者ギルドのメンバーだったが…。', '2024/05/24 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0627468e-8825-4e19-acb1-224faddee549.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d2b8ebb-f84c-405d-9a0b-294eda76d85b', '9bf892de-7701-45d9-999f-7b526f446d9d', 9, '100185891', 'ギザルムという災厄', 'ジェイドの肉体と「空間転移」の能力を奪った魔族･ギザルムは、魔人を従えて、ロードストを手中に収めていた。そんなギザルムを前に、暗殺者ギルドはピンチに陥る。そこへ駆けつけたロイドはギザルムと対峙する。', '2024/05/31 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a88b0377-f839-448c-8fb2-75cc73298c07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ab44b14-c14e-4cba-a16a-2e9228c4c4e2', '9bf892de-7701-45d9-999f-7b526f446d9d', 10, '100186521', 'シルファの剣', 'ロイドがギザルムと激しい攻防を繰り広げる中、ロイドの術式によって能力を操れるようになった暗殺者ギルドは、迫りくる魔人に対して、それぞれの能力で対抗する。しかし魔人たちに徐々に追い詰められてしまう…。', '2024/06/07 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/487e1a8a-46d9-456f-b4b0-0c96d613fa9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5070c4e1-104b-48b4-a151-993419c867a2', '9bf892de-7701-45d9-999f-7b526f446d9d', 11, '100187226', 'ジェイドの遺言', '「空間転移」の能力を使ったギザルムの波状攻撃に攻めあぐねるロイド。しかし偶然得た気付きから、魔術を吸収する「吸魔の魔剣」を試すことに。果たして、ギザルムに奪われたジェイドの能力の術式を解読できるのか。', '2024/06/14 01:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20cb7091-cb34-4e5d-99a9-90ccec02cda6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('840c0b87-e63c-4ca6-85d2-9eabb0d94004', '9bf892de-7701-45d9-999f-7b526f446d9d', 12, '100187878', 'ロイドの答え', '【最終話】ジェイドが残した意思と術式によって、「空間転移」の能力の魔術を理解したロイド。追い詰められたギザルムは、万物万象をのみ込みすべてを無に帰す奥の手「黒死玉」を発動するが、ロイドは圧倒的な魔力で迎え撃つ。', '2024/06/21 01:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4ca085e-7813-4b59-a26f-b8e2daef92e8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9cb23104-64ef-4fe1-b94b-349ea4cf924a', '転生したら第七王子だったので、気ままに魔術を極めます', '', 'hulu', 'i-was-reincarnated-as-the-7th-prince-so-i-can-take-my-time-perfecting-my-magical-ability-season-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/edf5fc3c-8d8d-4e41-ba85-c8c23f30c750.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 156415, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('27a70c09-e059-46ae-9ad8-ad0de433c248', '9cb23104-64ef-4fe1-b94b-349ea4cf924a', 'hulu-i-was-reincarnated-as-the-7th-prince-so-i-can-take-my-time-perfecting-my-magical-ability-season-2-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d40ebb22-a567-4162-bda4-71a13d561830.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('326eff8a-2e61-4f72-a87d-4534af480a69', '27a70c09-e059-46ae-9ad8-ad0de433c248', 13, '100232539', '入信します!', '魔族･ギザルムとの闘いを経て、ジェイドから空間移動能力を受け継いだロイドは、ガリレアをロードストの領主に任命。復興に向けて動き出すなか、魔人に対抗する力を模索していた。そこでグリモは、不死者にも効果がある「神聖魔術」を提案。ロイドは、バビロンとレンを連れて2年前に出禁となった教会へ向かうのだった。', '2025/07/13 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d40ebb22-a567-4162-bda4-71a13d561830.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99d1c053-660c-4c16-958e-739311cc9c75', '27a70c09-e059-46ae-9ad8-ad0de433c248', 14, '100232890', 'ジリエルの御業', '聖餐式の演奏会のために教会へやってきた第四王女･サリア。彼女のピアノとイーシャの歌声が重なったとき、待ち望んでいた「神聖魔術」が発動。喜びを隠せないロイドだが、魔力を帯びた視線を感じるや否や、転移魔法でその痕跡を追う。そうして辿り着いた先は、神の御使いである天使ジリエルが住む天界であった。', '2025/07/20 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1c631ec-296d-4026-a1ea-02cfa3e357bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8520118f-7bc2-4c25-8044-9eb1ec002fd1', '27a70c09-e059-46ae-9ad8-ad0de433c248', 15, '100233552', 'グール退治', '神々しいほどの力でジリエルに圧勝したロイドは、念願だった「神聖魔術」を習得。地上に戻りガリレア達とも契約を結ばせた。さらに不死者や霊体に特効する「浄化系」の研究をするため、シルファ、レン、タオらと共にグールの目撃情報が多い東区画の下水道へと潜入。するとロイドを巡って奇妙な勝負が始まる。', '2025/07/27 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9842b435-e559-435d-a5f8-eef3a7631525.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e821c88-6ae8-4484-a2ac-f8d0990dcdb0', '27a70c09-e059-46ae-9ad8-ad0de433c248', 16, '100233873', 'シビル･ウォー', '光武でできた武器を手に、次々とグールを倒していくシルファたちだったが、「脊髄の糸」を操る「反射のノロワレ」の出現により状況が一変する。時を同じくして教会の中庭では、謎神父がハーバル神父の首を締め上げていた。偶然その場に居合わせてしまったイーシャは、命を狙われてしまう。', '2025/08/03 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c89630e-a83e-4bf2-8d48-4f573813df8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05e01a5b-d3ee-4d69-9dee-dcb3c11e87d7', '27a70c09-e059-46ae-9ad8-ad0de433c248', 17, '100234718', '教会の秘密', 'イーシャ達を逃がすことに成功したバビロンは、謎神父との絶望的な力の差を本能で感じつつも、一縷の望みをかけて次々と攻撃を繰り出す。一方、冒険者ギルドに神父を託したイーシャは、自らの無力さを痛感するのと同時に、バビロンの身を案じて教会へとひき返していた。涙で視界が歪むなか、目の前に現れたのは…。', '2025/08/10 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a030ca8-9bb3-400b-8b7f-53c68931e66a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce8f6680-45e9-41db-aa85-dc5d7f6da35e', '27a70c09-e059-46ae-9ad8-ad0de433c248', 18, '100235107', 'イーシャの想い', '先の戦いで生死の境を彷徨ったバビロンだが、ロイドの空間転移能力とイーシャの献身的な治癒魔術により、かろうじて一命を取り留める。その後、ロイドたちは謎神父の正体を探るべく教会の中庭を調査。地下へと続く扉を見つけ足を進めると、そこには目を背けたくなる程おぞましい光景が広がっていた。', '2025/08/17 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f2c2247-5f92-4184-8dbe-d0e4237f64d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05598f66-d543-453c-bb10-8dce9a43c584', '27a70c09-e059-46ae-9ad8-ad0de433c248', 19, '100235417', '大聖誕祭', '謎神父の正体は教会本部を統括する「十二神官」の中にいると推理したロイド達。直前に迫る「大聖誕祭」での教皇暗殺を危惧したアルベルトは、シルファ達にそれぞれの神官を見張るように指示を出す。そして迎えた当日――デーン地区の教会にて国王と教皇が再会を喜んでいると、突如として轟音が響き渡る。', '2025/08/24 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cdbc4555-72d4-48f6-814f-02c41ffc576a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b6fa76e-de47-4dc3-b25c-5b0af6994328', '27a70c09-e059-46ae-9ad8-ad0de433c248', 20, '100236109', '襲来', '今回の黒幕であり謎神父の正体は教皇･ギタンであった。国王とアルベルトを空間転移能力で避難させたロイドはギタンと対峙。互いに抑え込んでいた魔力を一気に解き放ち、激しくぶつかり合う…。一方、神官を監視するために各所に散らばっていたレンやタオ達は、桁違いの魔力量を持つキメラによって行く手を阻まれる。', '2025/08/31 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebd4af73-53ab-43fc-96c7-711f25357738.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ebc4077-abbf-46aa-b450-8b0851a6963b', '27a70c09-e059-46ae-9ad8-ad0de433c248', 21, '100237266', '月とトンカツ', '倒す度に再生し硬化する豚のキメラ･完全食を前に、窮地に陥るバビロン達。一方別の場所では、丸腰のシルファが、大神官であるアナスタシアと一触即発の状況に。自らが信じ仕える主のために、お互い一歩も譲れないこの戦い…。シルファは近くにあった燭台を手にし、アナスタシアも容赦なく剣を振り下ろすのだった。', '2025/09/07 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8972ef0c-e35c-4b2f-87f2-38f88d035774.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1388a965-b15a-4040-a066-660f55e6c81f', '27a70c09-e059-46ae-9ad8-ad0de433c248', 22, '100237726', '黒竜', '街の至る所で戦いが繰り広げられるなか、クロウ達の前には巨大なキメラ･黒竜が迫っていた。逃げ遅れた人々を救うために、自らの限界を超えてもなお力を使うクロウ。その目からは次第に光が失われていく。そんな彼を必死に守ろうとする神官･バッツの想いが届いたのか、シルファやタオ、そしてグリモ達が駆けつける。', '2025/09/14 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b71d0b5-ce76-44a4-8e03-d935fae77a57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('395f5f2a-04d2-497b-a54d-0b8f1bdbde83', '27a70c09-e059-46ae-9ad8-ad0de433c248', 23, '100237956', '天上決戦', '黒竜を屠るために人型のグリモが放った「大･螺旋黒閃砲」は、遥か上空で戦っていたロイド達のもとまで届く。それを見たギタンはさらに10体のキメラを投下。誰もが満身創痍ながらも、逃げ惑う人々を救うために立ち上がろうとした刹那、サリアの演奏とイーシャの歌声が温かな光のように降り注ぐ…。', '2025/09/21 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4d730c0-c0fd-40dc-be2a-3d4c63168de1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('274fe938-6ae4-471d-94a2-52af3bb5b5eb', '27a70c09-e059-46ae-9ad8-ad0de433c248', 24, '100238950', '光の中で', '【第2期 最終話】イーシャとサリアの織り成す演奏が人々の心に希望を与えるなか、ロイドもその音に合わせて攻撃を繰り出す。それはギタンでさえも何が起きているのか理解に苦しむほど異次元な力であった。そして、この戦いに終止符を打つべく、ロイドは三重詠唱を発動させる。人類の未来をかけた壮大な戦いが、ついに終局に向けて動き出す…。', '2025/09/28 00:30:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b45df92-bde1-4bf2-8ccc-c2aab58f1d07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('acbe9fa9-840e-45bd-811c-50ca447a8726', '転生悪女の黒歴史', '', 'hulu', 'the-dark-history-of-the-reincarnated-villainess', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d6d98a4-294c-43b2-aca7-1fe456e3c3d6.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 174914, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('7811cbe9-6b58-42b0-8088-1665772f1794', 'acbe9fa9-840e-45bd-811c-50ca447a8726', 'hulu-the-dark-history-of-the-reincarnated-villainess-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cdb054e4-ca67-4d14-bb94-339624a6ec09.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afac369a-b771-4679-a831-b9cea3e316a9', '7811cbe9-6b58-42b0-8088-1665772f1794', 1, '100239164', '大切なのは学力より魔力', '会社員の佐藤コノハは仕事の帰り道に事故によって命を落とし、学生の頃に自分が描いた物語･【黒歴史】の中の登場人物に生まれ変わった。しかも生まれ変わったのは、自分がなりたかったヒロイン･コノハではなく、嫌われ者の妹キャラで稀代の悪女･イアナだった。おまけに物語が進めば自分は執事の男･ソルの手で早々に命を落とす運命にある…! 生き残る道はただ一つ…物語の展開を思い出し、死の運命を回避すること――。', '2025/10/12 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cdb054e4-ca67-4d14-bb94-339624a6ec09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f0bfb49-c3a1-486b-a993-ab93365492ce', '7811cbe9-6b58-42b0-8088-1665772f1794', 2, '100239165', '盆踊りより舞踏会', 'お花見の茶会で淫獣にさらわれたコノハを救出するため、自ら死地に飛び込むイアナ。ソルとギノフォードたちの協力によってコノハの救出に成功する。ホッとしたのも束の間、王都より舞踏会の招待状が届く。だが、この舞踏会こそが【黒歴史】の3話目。舞踏会でコノハが王子様と踊れば、イアナの死亡フラグに繋がってしまうのだ――!', '2025/10/19 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a1e6a0a-1d4d-44d9-b864-a1c79fbe4bd2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3e0f1af-5385-43c8-89a2-b5ef2e63fec7', '7811cbe9-6b58-42b0-8088-1665772f1794', 3, '100239166', 'お前が送ったんかい、黒歴史', '転生した世界での生活にも慣れてきたイアナ。そこに1人の青年が訪ねてくる。それは留学先から戻ってきた幼馴染のヨミ。イアナは自分が創り出したヨミのことを思い出して愕然とする。彼の物語での役割は「コノハを殺す事」――彼が物語通り行動すればそれはすなわちイアナの「死」に繋がる。ヨミの行動を阻止しようと説得を試みるイアナ。だがそれはむしろ火に油を注ぐ結果になってしまう。', '2025/10/26 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1186a49e-1652-4cc0-a6ae-a021dd4fc508.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0915862b-98eb-4015-968e-611f5c5c6f9c', '7811cbe9-6b58-42b0-8088-1665772f1794', 4, '100239167', 'どうせ誰が死んでも私が疑われるんだ', 'ソルにイアナが虐げられていると勘違いしたヨミ。彼はイアナへの純粋な「想い」と「忠誠」からソルの命を狙う。ヨミの仕掛けた魔法によって誕生した「人喰い花」にコノハが襲われる。ギノフォードとともに撃破したソルは自分の周りに起きる不審な出来事から、これも自分を狙ったものと思い、イアナに疑念の目を向ける――「僕がやった」と名乗り出たヨミは、ソルに決闘を申し込む――!', '2025/11/02 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c9f22de-1116-4897-ad0f-e1a92d6bdc4c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('908e648c-8394-4c08-8cf6-58880bb1de3b', '7811cbe9-6b58-42b0-8088-1665772f1794', 5, '100239168', '病人の熱は額を合わせて計る', 'ソルに代わって剣を取り「私が相手よ!」と、ヨミと対峙するイアナ。しかしイアナには重たい剣を振ることさえできない。イアナを愛するヨミは負けを認め、「僕には、できない…!」と、自ら剣を捨てる――。ひとまず事態は収まるが、このままではヨミはコノハの命を狙い続ける。イアナの説得ではヨミが諦めることはない。イアナが導き出した窮余の一策とは――?', '2025/11/09 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75399504-6598-4163-8370-0050c6e46682.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bed5cdbd-3939-40de-98f1-18da32843a85', '7811cbe9-6b58-42b0-8088-1665772f1794', 6, '100239169', '容疑者決定で死亡確定?', 'コノハと共にお忍びで町へと出かけたイアナは、そこでコノハの人気と、自分の嫌われっぷりを実感する。屋敷に戻った2人の前に現れた男に、イアナは強い悪意を感じる。男は警察治安部隊第二班･ハイドランジア隊副隊長･シャノウ。このシャノウこそ、コノハ殺害容疑でイアナを捕らえた男だった。シャノウは半年前から起きている美少女連続失踪事件を調査しており、イアナに疑いの目を向けている――。', '2025/11/16 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/852b2e83-e50a-4109-b41f-c862f4a3bbdb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d81e1601-d362-4bde-9a42-76aa3574a9ba', '7811cbe9-6b58-42b0-8088-1665772f1794', 7, '100239170', '脳内映像は全年齢', '「この子は奴隷なんかじゃない」――友人となったメノアの義姉に向かって啖呵を切るイアナ。アマリリス夫人のパーティーで騒動を起こしたことで、シャノウからますます疑いの目を向けられるイアナ。その矢先、メノアが失踪。メノアがしていた耳飾りを拾っていたイアナに失踪事件犯人の嫌疑がかかる――!', '2025/11/23 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1913e166-1e3b-4f63-bd16-fda4d95ef6d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ad4fe7e-4b51-45ff-bfc0-7644ca0bdf8c', '7811cbe9-6b58-42b0-8088-1665772f1794', 8, '100239171', '『オリジナル』は魔法の5文字', 'アマリリス夫人こそが、美少女たちを誘拐している「ブラッディ･ローザ」――メノアを救う為、シャノウに協力するよう説得し、共に行動を開始するイアナ。だが罠にハマったイアナとシャノウはアマリリス夫人の手に堕ちてしまう。2人が捕らえられた地下室。そこはさらわれたメノアや、シャノウの妹もいる狂気の『楽園』だった――。', '2025/11/30 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb2fa7ec-5136-4b56-9a2e-f7b70fb96094.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e48e4a66-ab66-4992-937b-1cb8ecb05aaa', '7811cbe9-6b58-42b0-8088-1665772f1794', 9, '100239172', '自己評価なんてあてにならない', 'シャノウやメノア、そしてさらわれた美少女たちを救う為、『稀代の悪女=イアナ･マグノリア』として、アマリリス夫人と対峙するイアナ。危機一髪、ハイドランジア隊の突入により、救われるイアナたち。逮捕されたアマリリス夫人が「死」を覚悟していることを知ったイアナは、その命を救おうとする。無事に一件落着――のはずだったが、なぜかソルがお怒りに……。今度の一件がソルの『殺る気スイッチ』を入れてしまったのか?', '2025/12/07 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cbca64f-41f2-40b5-88af-443086392067.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d261025-93d2-4480-8b61-093f7c334488', '7811cbe9-6b58-42b0-8088-1665772f1794', 10, '100239173', '人間界のリア充よりエルフの美しさを知らない', 'これまで【黒歴史】を変えようと奮闘してきたイアナ。しかし物語が、自分の力の及ばないところで修正されていくことに気づく。そんな中、保養地へとコノハたちとともに訪れたイアナは怪我をしたエルフのシュクナを連れた少年･カグラと出会い、別荘に保護することに。それは間もなく起こる『吸血鬼事件』を予見させる出来事だった――。吸血鬼の石室を確認しようとするイアナに「私を連れ出して頂けませんか」と、ソルは同行を願い出る。', '2025/12/14 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99c9460b-db36-4a48-9c2d-120fdc68879b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de3827d7-162e-4496-be7c-257e86e9ac3a', '7811cbe9-6b58-42b0-8088-1665772f1794', 11, '100239174', '萌えより命が大事!', '封印が解かれた石室から『消えた者』を探し回るイアナに、吸血鬼化したエルフたちが襲い掛かる。駆けつけたソルとヨミに救われ「自分は今、1人じゃない」という思いで進むイアナ。しかし、自分を助けてくれたシュクナに案内された先で予期せぬ展開が待ち受けていた――。', '2025/12/21 00:30:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6cf01ae9-0326-4770-aac2-34d5d4af2a2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c6bdd9f-3eaf-410b-ad44-76cc09113bd0', '7811cbe9-6b58-42b0-8088-1665772f1794', 12, '100239175', '優しさと強さと私が消すべき男 (キャラクター)', '【シーズン1 最終話】復活した吸血王の前にかしずくイアナ。だがそれは芝居であり、ハンカチに付いていたコノハ (聖女) の血によって、吸血鬼化を逃れていたイアナは単身、吸血王との戦いに挑む。そしてヨミの元に戻ると、予想外の展開に――。一体、黒歴史の中で何が起こっているのか…?', '2025/12/28 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e08aa421-e4de-4da2-8028-10e67c1b750a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('93a7626f-a1ba-45fb-ad50-57413ea28103', '転生王女と天才令嬢の魔法革命', '', 'hulu', 'the-magical-revolution-of-the-reincarnated-princess-and-the-genius-young-lady', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16e4a691-80fa-47b7-91a7-b47f0f5072e4.jpg?w=331&h=447&p=t', 'hulu', 2023, 0, 1, 'FINISHED', NULL, 153629, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a3efc92b-3999-44db-a8ad-6eb99174204e', '93a7626f-a1ba-45fb-ad50-57413ea28103', 'hulu-the-magical-revolution-of-the-reincarnated-princess-and-the-genius-young-lady-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db80bd45-fbe2-4d35-a81a-26685d6ff2bd.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce8c79c4-05e1-4a93-bedb-d515d297e8fa', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 1, '100134442', '王女と令嬢の魔法革命', '前世の記憶を持つ王女、アニスフィアは魔法で空を飛ぶという夢のため、日夜怪しげな研究に勤しんでいた。ある夜、アニスはお手製魔女箒の試験飛行で、貴族学院の夜会に飛び込んでしまう。そこでは、天才公爵令嬢のユフィリアが王子アルガルドから婚約破棄をつきつけられていて!?', '2023/01/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db80bd45-fbe2-4d35-a81a-26685d6ff2bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01275233-ad3f-42f8-b3f9-5edbebbb4f4b', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 2, '100134960', '趣味と実益の助手獲得', '夜会で婚約破棄をつきつけられたユフィリアを強引に連れ出したアニスフィア。王宮に連れていくと、それぞれの父の前で、消沈するユフィリアの名誉回復のために、自身の助手とすることを宣言。ついでに、一緒に暮らすことまで決めてしまい!? そして、二人の奇妙な同棲生活が始まろうとしていた……。', '2023/01/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44b61a59-1b27-4a6e-ab16-9dfc0170d295.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79c7e779-94e9-45fe-a322-362584d65698', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 3, '100135408', '憧憬と追憶の虹霓魔剣', 'アニスフィアとユフィリアの共同生活が始まってしばらく。だが、ユフィリアは新しい環境、新しい仕事、そして、新しい立場に未だ慣れず、アニスフィアに振り回されっぱなしで、なんだか元気がない様子。そんなユフィリアのために、アニスフィアは専用の魔道具を作ろうと言い出して……。', '2023/01/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8471e95-3e89-4803-b066-45fabb467125.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4a3559f-a299-4c8a-a0cc-1378dd2e7ed3', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 4, '100135808', '姫様と迷子の決意表明', '新生活の気疲れからか体調を崩してしまうユフィリアだったが、アニスフィアの優しい看病と温かな言葉に心が軽くなっていく。そんなある日、イリアから自身の過去とアニスフィアの真意を語りかけられ、ユフィリアは自身の目指すべき姿をおぼろげながら見つけ始めていた。しかし、そこへ冒険者ギルドからの思わぬ急報が飛び込んできて……。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb9a2699-cfbc-40de-92ae-7d09a37c5269.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61aa9cfd-827f-4120-bb59-81b708751b7c', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 5, '100136319', '魔薬と魔剣の魔竜討伐', '冒険者ギルドからもたらされた魔物のスタンピード、そしてドラゴン出現の急報。王都の危機を前に、アニスフィアとユフィリアは戦場へと飛び立った。順調に魔物の掃討を続けていたアニスたちだったが、そこへドラゴンが現れる。絶望的戦力差にもかかわらず、立ち向かうアニスだったが……。', '2023/02/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75a0ad9b-4979-4184-9a57-6873d9ee8040.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dc28428-33e2-4437-934d-791fb6b58b8a', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 6, '100137158', '破談と魅了の真相究明', 'ドラゴンの魔石を手に入れたアニスフィアたちは新たな技術開発のために、共同研究者であり、悪友でもあるティルティの元へ向かう。またしても破天荒で常識はずれな研究にうっきうきわっくわくのアニスフィアだったが、一方その頃、王宮ではユフィリアの婚約破棄について調べが進められていて……。', '2023/02/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bccee1d7-e3f3-4b2c-a629-dfb5faca62ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e38eb731-df66-48d3-ac20-a637e5efb0f3', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 7, '100137869', '開祖と助手の魔学講演', '保護観察と魅了の力の研究のため、離宮で暮らすことになったレイニ。アニスフィアとティルティはレイニの能力について調べ始める。二人の気の置けないやりとりを目の当たりにしたユフィリアは心中にもやもやしたものを抱えていた。そんな折、アニスフィアと対立関係にある魔法省から講演の依頼が舞い込み、ユフィリアは……。', '2023/02/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b3f5689-2102-461e-bb1d-e1584d8aef4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd4bce08-f563-4752-89d9-37609261d953', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 8, '100138296', '怪物と凡愚の魔法定義', '魔法省での講演を無事終えたアニスフィアたち。その慰労を兼ねた立食パーティーの最中、離宮の危機を知らせる警報装置が鳴り響く。離宮へ急行したアニスフィアとユフィリアだったが、そこには悲惨な光景が広がっていた。心臓を貫かれ、血みどろのレイニ。倒れ伏すイリア。そして返り血を浴びるアルガルドの姿が……', '2023/03/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6772fb46-056b-497a-b701-6df5dad62cfd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a16c64b5-9d90-43bb-90f1-12129489d652', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 9, '100139377', '姉弟と誰がための王冠', 'レイニらを必死で治療するユフィリアが見つめる中、アニスフィアとアルガルドの戦いは苛烈さを増していた。自らをヴァンパイアへと変えたアルガルド相手に苦戦するアニスフィアだったが、弟の凶行を止めるべく、命を奪う覚悟を決め、必殺の一撃を放つ。王女と王子。愛憎渦巻く姉弟の戦いに決着がつこうとしていた……', '2023/03/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f0bbadf-2ea0-4c7b-898d-b989ff07b3c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf5709dd-b088-4279-bf7c-eab199788dbd', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 10, '100140151', '諦観と激情の王位継承', 'アルガルドが王都を去り、唯一の王位継承者となったアニスフィアは次期女王として立つべく活動を開始する。そんなアニスフィアの臣下として、助手として支えていこうと決意を新たにするユフィリア。しかし、すっかり片付けられてしまった魔学の研究室や無理して微笑む姿を見て、ユフィリアの胸中には迷いが産まれていた……', '2023/03/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9da752d-e94b-4d79-af32-fa8e66dc3983.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6087dc1-bcd7-484a-b4e9-d5392eeaeeed', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 11, '100140727', '失意と決意の精霊契約', '精霊契約者リュミとの邂逅を経て、新たな王として立つ決意を固めたユフィリア。アニスフィアの夢と笑顔を守りたい一心のユフィリアだったが、精霊契約には隠された真実があった。愛しい存在と己の拠り所を失ってしまう事実を知ったアニスフィアはその重さに耐えきれず、冷たい雨が降りしきる城下へと逃げ出して……', '2023/03/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23510c4a-3fd2-4a6f-9594-9216bfaafcb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bf7c25ec-b72a-4f1d-baff-7221332bd03c', 'a3efc92b-3999-44db-a8ad-6eb99174204e', 12, '100141524', '彼女と彼女の魔法革命', '【シーズン1 最終話】「私は、貴方を王にしたくなどない」「私は、貴方にすべてを奉げさせたくない」 イリアらが固唾を飲んで見守る中、アニスフィアとユフィリア、二人の少女が互いの信念を懸けて対峙する。想い合うが故に譲れない二人。渾身の一撃を放つアニスフィアに全霊でもって応えるユフィリア。その勝負の行く末は……', '2023/03/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3009f9a-001c-40eb-a0da-a082ccca6145.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('283dd212-34f8-4948-9332-19182a014454', '転生貴族、鑑定スキルで成り上がる', '', 'hulu', 'as-a-reincarnated-aristocrat-ill-use-my-appraisal-skill-to-rise-in-the-world', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/096036e4-2343-43eb-b4d2-37f9b2da4c07.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 164702, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f0c55611-a9dc-493d-b455-eeb8bb25854f', '283dd212-34f8-4948-9332-19182a014454', 'hulu-as-a-reincarnated-aristocrat-ill-use-my-appraisal-skill-to-rise-in-the-world-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64c93e16-07e2-4f8f-8365-8935945cbfde.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82c4a813-8c91-4b3a-a10e-6a59694c89e5', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 1, '100180725', '「転生と鑑定」', '異世界に転生したアルスは、人の能力を見抜くことが出来る“鑑定”のスキルを手にしていた。アルスはそのスキルを活かして、まだ世に出ていない「逸材」を探し始める。', '2024/04/11 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64c93e16-07e2-4f8f-8365-8935945cbfde.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a3109e9-0c69-4349-b4c1-b9686a9c6cad', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 2, '100181740', '「上と下」', 'アルスは父の命を受け、リーツと共に魔法に長けた人材を探し始める。多くの人が住む城郭都市･カナレに着いたアルスたちの前に、奴隷商人に追われる謎の少女が現れて――。', '2024/04/18 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af05e372-bd59-4be9-8b58-56e2df764b01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64968d6c-8176-4706-976b-68a65a127a14', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 3, '100182360', '「答え」', 'アルスはリーツと共に、奴隷商人に捕らわれたシャーロットの救出へ向かった。希望をなくしたシャーロットのもとへアルスたちがたどり着くと、ならず者たちに囲まれてしまい――。', '2024/04/25 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/719235f7-7dea-4591-a8c5-3f9d45ad60ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40b77167-8729-4b93-8e75-4fa2c21c12b6', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 4, '100183231', '「才能の居場所」', 'アルスが6才になる頃には、すでにリーツとシャーロットは目覚ましい活躍ぶりを見せていた。 次なる逸材を求めていたところに、才能豊かな狩人の兄弟がいるという噂が飛び込んできて――', '2024/05/02 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93c66ae0-e59a-41c6-9454-6ffe4a39c67f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3dbafa6-0033-4da4-a7fa-9ec001ea1c62', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 5, '100183743', '「嵐、来る!」', '着実に最強の領地づくりが進んでいた矢先、アルスの父･レイヴンが体調を崩してしまう。床に臥せる父がアルスにこぼしたのは、初耳の許嫁の話で…!?', '2024/05/09 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/659f311f-edcc-4699-b067-1e2c8f2f4495.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb282cd0-f0a1-49af-af58-497ed9ad40b9', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 6, '100184446', '「戦士の顔」', 'レイヴンの体調が悪化する中、アルスのいるミーシアン州の総督が暗殺されたという情報が入った。アルスは父に代わってカナレ郡長の招集に応え、軍議に出席することになり――。', '2024/05/16 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c194cb7a-85db-4c1a-94d3-ce92ce85f7b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1845636f-b334-4911-a856-59731efc35eb', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 7, '100184916', '「継承」', '戦場に行くことさえも許されなかったアルスは、なんとか自分も強くなろうともがいていた。しかし、レイヴンとの別れの時は刻一刻と迫っていて――。', '2024/05/23 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c05ac905-1ad9-4f4e-aa90-56801eca456f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1dcda517-fb86-4d50-852e-277ccf1e4de2', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 8, '100185894', '「新世代」', 'ランベルクの新たな領主となったアルスにさっそく試練が訪れる。ミーシアン州の重要な位置にあるペレーナ郡を仲間に引き入れるため、アルスたちが調略をすることになったのだ。', '2024/05/30 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fe0e8b9-0b4c-4a3c-8a92-208c9f3c4bfc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e6d0e7e-ebb6-4e06-b5bb-5706c4530b05', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 9, '100186524', '「探り合い」', 'ペレーナ郡の調略を目指すアルスたちは、ファムの活躍によって敵側の盟約状を手に入れる。しかし、その内容には不可解な点があった。そこでロセルがある作戦を思い付き――。', '2024/06/06 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74804d94-468f-4c77-b1a0-bf92664ec42c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ad2e7ac-aec8-4519-8d1c-309206e4b5cc', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 10, '100187229', '「クラン･サレマキア」', '総督の後継者であるクランから招待を受け、アルスたちは貿易都市･センプラーへ向かう。決起集会のパーティーでクランが語ったのは…!?', '2024/06/13 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5d32194-b635-41fa-863c-a8d126d553fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd921114-c17b-43b6-99c1-06528cef1ce6', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 11, '100187883', '「ミレーユ･グランジオン」', 'アルスの鑑定スキルで、ミレーユが化け物級の逸材だと分かる。なんとミーシアン元総督の参謀を務めたほどの人物だったのだが、リーツは家臣にすることを反対して――', '2024/06/20 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3007f38-d3bd-43d9-874c-fd312dc4cf78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3cbd042-0dfe-4c8f-96bf-054320b77025', 'f0c55611-a9dc-493d-b455-eeb8bb25854f', 12, '100188487', '「誓い」', '【最終話】ローベント家をふたつに分けた模擬戦はさらにヒートアップ! ミレーユは圧倒的戦力差がある中でもリーツ、シャーロット、ロセルを相手に次々と作戦を成功させていき――', '2024/06/27 00:00:00', 1410, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bcb0243-e606-42c9-81c9-4e73be1f88d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('1493fcaf-35d1-4a2a-8188-1b698ed9d80a', '283dd212-34f8-4948-9332-19182a014454', 'hulu-as-a-reincarnated-aristocrat-ill-use-my-appraisal-skill-to-rise-in-the-world-s2', '第2期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a23c8b2-8578-4569-bd54-d5b178cee9aa.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46ef3b4c-782c-403a-88f4-9258f99c1322', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 13, '100200970', '「約束」', 'ミーシアン州の次期総督の座をめぐるクランとバサマークの争いは更に激化していた。そんな中、アルスたちはクラン陣営の軍議に参加するため、貿易都市センプラーへと向かう。', '2024/10/03 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a23c8b2-8578-4569-bd54-d5b178cee9aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f4f0702-e98a-4339-b7c8-5abf2839a753', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 14, '100201702', '「交渉」', 'アルスたちはパラダイル州を味方につけるため、サマフォース帝国の皇帝へ仲介を依頼することに。この重要な交渉を前に、クランの息子であるレングが現れて――', '2024/10/10 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/65c409c4-5153-4c92-92c3-e5b0c2d126e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30afbbf8-6cca-4fa8-8b57-47dd6add4ae6', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 15, '100202602', '「領主の姿」', 'リシアの活躍で、無事にシャクマとの事前交渉は成立した。しかし、レングはアルスたちのやり方に異を唱える。様々な不安が残る中、遂にパラダイル州との本交渉が行われ――', '2024/10/17 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58a577ea-3a84-4730-805d-1da89c59b84e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a799536a-5e7a-4693-9d8c-b3a0aaf422c1', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 16, '100203237', 'ワクマクロ砦', '初陣を迎え緊張気味のアルスだったが、兵力差で上回るクラン陣営は難なく進軍を続ける。そんな中、アルスたちはサムク郡の重要拠点であるワクマクロ砦の攻略を命じられる。', '2024/10/24 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c33b0b73-d45c-4717-a542-e6c09a1003ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9632b29-1884-45cb-aecd-c99fc3c79726', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 17, '100204637', 'サムク城攻略', 'ワクマクロ砦を陥落させたアルスたちは、いよいよサムク城の攻略へと動き出す。しかし、サムク城ではバサマークの右腕と称されるトーマスが指揮を執っていたのだった。', '2024/11/07 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eaf0002c-ad08-450b-9fea-3aa6c7bad295.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1af24269-82ac-4b1a-8e06-d8c40a820b0b', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 18, '100205258', '進化', 'サムク郡攻略後、サムクの街を散策していると、アルスの“鑑定スキル”に異変が起きる。そんな中、クラン陣営は大都市ベルツドへの侵攻を開始することに――', '2024/11/14 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2eafc334-7803-4c7e-9879-218919759d36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aed624fa-bae4-4f0c-9028-ec209659024f', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 19, '100206587', 'ロルト城の脅威', 'アルスは進化した“鑑定スキル”を駆使し見事にリューパの真の目的を見抜いた。そんな時、ロルト城攻略に向け、クランから「最強の援軍」が送られてきて――', '2024/11/21 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/461caaa4-5611-42a9-ac82-69b65ef0aee4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90ec7d40-7ceb-4b77-a770-3d3a71bf0f2d', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 20, '100207469', '家族', 'ファムたちの人質救出作戦のために、命がけの偽装退却をやってのけたアルスたち。それを見た「メイトロー傭兵団」のクラマントたちはアルスを認め、遂に戦闘を開始する。', '2024/11/28 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/232ed6ea-0af8-4b26-9478-644f791c906b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7d1c9e5-7bd1-40bf-a4ac-140dc90c434c', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 21, '100208279', '影の未来', 'アルスの依頼を受け、スターツ城に侵攻中のクランへ報告に向かっていたファム。しかし、ファムがクランの軍勢に追いついたその時、そこには激しい火の手が上がっていた。', '2024/12/05 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3492924-8245-473e-882b-7d9eb6a42e54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a23d1049-97d7-4730-ad15-1447b80e365e', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 22, '100209765', '雪合戦', 'アルスたちが到着したことで、クランが侵攻中だったスターツ城の戦況は大きく動き出す。あっという間に敵軍は降伏したのだが、そこに血気盛んな「悪童」がやって来て――', '2024/12/12 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dcdc5d7e-e110-4e81-800e-8b92a92c32f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffd2f6ed-37bb-42a9-bae7-e275273892c1', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 23, '100210359', '忠誠', 'ベルツド郡の最重要拠点であるベルツド城の攻略に向けて動き出すアルスたち。相次ぐ敗戦で後がなくなったトーマスは、最後までバサマークへの忠誠を誓い、戦場へ向かう。', '2024/12/19 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40373c84-1ff6-47e4-b3b5-0f03f442d11b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79996f2c-f332-4ab1-9e9a-2de90ea95cdc', '1493fcaf-35d1-4a2a-8188-1b698ed9d80a', 24, '100211706', '託される想い', '【第2期 最終話】ベルツド城攻略に向けた最終決戦。敵将トーマスの策を見抜いたアルスたちは、一気に総攻撃を開始しようとしていた。しかし、トーマスの策には更なる罠が用意されていて――', '2024/12/26 00:00:00', 1410, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba989dcc-9d42-49da-8b83-9649e8e4b077.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('717f3519-5f73-4e24-bad7-8557c4ca3435', '転生貴族の異世界冒険録 〜自重を知らない神々の使徒〜', '', 'hulu', 'chronicles-of-an-aristocrat-reborn-in-another-world', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9986c7ef-8346-40b8-bf96-f15df4de1585.jpg?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 153332, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('adfaba4f-b643-44db-9129-59112cbd9d3b', '717f3519-5f73-4e24-bad7-8557c4ca3435', 'hulu-chronicles-of-an-aristocrat-reborn-in-another-world-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f201fd63-95d9-4257-ada2-8e5886fd7cf6.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a02e2724-a7c2-49d4-8032-59f7abd35dae', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 1, '100142809', '『転生しちゃいました』', '少女をかばって死んでしまった高校生･椎名和也は、貴族の少年･カインとして剣と魔法の世界に転生した。ファンタジー世界に胸を躍らせるカインだったが、なんと彼は神々から過大すぎる加護と規格外のステータスを与えられていたのだ! さすがにやりすぎと焦ったカインは魔法でステータスを隠蔽。が、それでも常人では考えられないほどの数値で……。自重してもしきれない!? カインのはちゃめちゃ異世界ライフ、開幕!', '2023/04/09 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f201fd63-95d9-4257-ada2-8e5886fd7cf6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d7063af-0241-4588-94a9-7bcbca3d645c', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 2, '100143175', '『家庭教師は冒険者』', 'カインの元へ、家庭教師として女性冒険者のミリィとニーナがやってくる。だがカインはそのやりすぎステータスであっというまに二人を圧倒! 剣も魔法も教えることないかも……と先生たちを困らせてしまう。そこで屋敷の外へ連れ出して欲しいとお願いするカイン。街の外での訓練や、ギルドへの訪問など、初めての冒険を楽しむこととなる。しかしそんな時、ミリィとニーナは酔っ払い冒険者たちに絡まれてしまい――。', '2023/04/16 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0926fcb7-b893-4910-83b8-3b03ddd979b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30e0406c-2764-45b1-b480-458014c45d77', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 3, '100143744', '『いざ王都へ』', '10歳になったカインは、お披露目会と呼ばれるパーティーに合わせ、家族とともに初めて王都を訪れる旅に出る。お披露目会――それは貴族の子息たちが集まる社交の場。ワクワク気分で馬車に揺られるカインだったが、道中で魔物の群れに襲われ、全滅しかけている別の馬車を発見する。慌てて駆けつけ加勢するカイン。無事に苦境を切り抜けると、馬車に乗っていたのはなんと王女･テレスティアとその友人･シルクで――。', '2023/04/23 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9683fb1-d690-4e79-b7b4-64dff7971781.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('389b2b15-f30e-42ed-b6a9-188ddbd28148', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 4, '100144396', '『王都お披露目会』', '街で偶然再会したネコ耳少女のパルマ。かつてカインが助けたその少女は、いま王都にある伯父の雑貨屋で修行をしていると言う。そこでカインはその伯父･タマニスへ、とある製品の作成を依頼するのだった。それは教会を訪れた際、神様たちからお願いされた「この世界に娯楽品を作って欲しい」という依頼をこなすため。果たしてカインの作った娯楽品とは――? そしてついに、王城ではお披露目会が開催され……!?', '2023/04/30 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f308a0c3-234d-4c44-9edf-b883d49513fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9cedb80-a17f-4ff1-a84d-c84d82037745', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 5, '100144760', '『やりすぎ屋敷へようこそ』', '男爵として叙爵され、王都に屋敷を与えられたカイン。ボロボロだと噂される古い屋敷も、チート能力の前ではなんのその♪ あっというまにお掃除&改修を完了させてしまう。そして専属のメイドとなったシルビアや、新しく赴任してきた執事のコランたちと協力し、屋敷のお披露目パーティーを開く準備を始めるのだった。しかしそこに響いてきたのはメイドたちの悲鳴で――。更には国王陛下までもパーティーへ来ることとなってしまい!?', '2023/05/07 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b697e388-b8f3-4c1a-a258-2a5d654d38e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad4490c1-31e3-4442-a51d-8ef28d790aef', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 6, '100145760', '『最強騎士団長との決闘 (デート) 』', '近衛騎士団の詰所を訪れるカイン。目的は一人でこっそり倒した魔物の素材を引き取ってもらうこと。しかしそれがどんどんどんどん出てくるものだから、近衛騎士団副団長のダイムはびっくり! そそくさと帰ろうとしたカインだったが、そのまま訓練に付き合わされることとなる。一人対三十人で練習が始まり、流石に焦るカイン。それを止めようと割り込んできたのは、エルフの長い耳を持つ美しい少女で……。', '2023/05/14 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0de05c0-df84-4985-909c-4fd577a282b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9bd72ec0-292e-4d49-bbec-e37879680f09', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 7, '100146196', '『新人冒険者カイン』', 'ついに12才の誕生日を迎えたカイン。それは待ちに待った『冒険者登録ができるようになる日』だった! 早速ギルドを訪れるが、そこでまたしてもテンプレのような迷惑冒険者たちに絡まれてしまう。助けてくれたのは氷炎のクロードと呼ばれる赤髪の男性冒険者……。カインはなぜか彼の赤髪に既視感を覚える。その正体が分からないまま、カインはティファーナと共に初デート (と書いて初依頼) へ出掛けることとなり――。', '2023/05/21 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4bb1676-283a-488b-9edd-0223c6f7bf2a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ad30998-da82-4689-84f5-12d019f73ab8', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 8, '100147069', '『王立学園』', '寝過ごしたカインを慌てて起こしに来るシルビア。今日は大事な王立学園･入学試験の日なのだ。こっそり転移魔法を使い、時間には間に合ったカイン。筆記問題を難なくこなし、魔法能力測定へ向かう。「防御結界があるから全力でやっても大丈夫」なんて言われるが、他の生徒の様子を見てやり過ぎフラグだったと理解する。「全力なんかでやったら怒られてたよ! 危ない危ない……」と無事にフラグを回避したかと思えたが……。', '2023/05/28 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6538f16f-002c-48f6-9dab-a96b4b03bdd3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74ce441c-562a-4a5f-ba15-3dbdd194a8e0', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 9, '100147786', '『修行』', '気付くと見知らぬ一軒家のリビングに立っていたカイン。眼の前の青年は自らを、この国の初代国王であり、カインと同じ元の世界からやって来た転移者、平沢優也だと名乗る。驚くカインに対し、彼は「お前のことを鍛える」と伝える。目的は邪神･アーロンの封印。戸惑うカインだったが、ユウヤは「アーロンは椎名和也とも因縁がある」と言い放ち……。厳しい修行が続く中、やがてユウヤはカインへ自らの過去を語り始める。', '2023/06/04 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af82c7e7-8df0-4767-851c-b332c73727de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df190552-e83c-46d6-adf1-d5fbaf55e1fd', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 10, '100148356', '『Aランク冒険者の試練』', 'Aランク冒険者へ昇格するために必要な依頼を受け忘れ、いきなりピンチなカイン。これが達成されないと冒険者登録が取り消されるという。内容は盗賊団の討伐。早速襲撃現場へ駆けつけてみると、襲われていたのはかつてカインの家庭教師だったミリィとニーナ、そしてパルマの父であるサビノスだった。あまりの強さに学校で浮かないのかと心配されるカイン。そこでミリィとニーナ、クロード、リナはとある作戦を思いつく。', '2023/06/11 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b86f86d-0e5f-4f03-a990-8e52cb43e302.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3e612ca-0af5-4d17-923f-6683aeeab257', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 11, '100149325', '『氾濫の予兆』', 'カインは久しぶりに魔法の授業へ参加できることとなる。内容は召喚魔法。意気揚々と授業へ臨むカインだったが、呼び出されたのはなんと魔王であるセトで!? 驚くカインに対し威圧的な態度を取っていたセトだが、カインのステータスを見るやいなや、態度が一変し……? 一方その頃、グラシア領･魔物の森では魔物たちの『氾濫』の兆候が観測されていた。不穏な予兆にカインは懐かしのグラシア領へ戻ることとなる。', '2023/06/18 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/184bb731-b98f-49c6-8721-e1ea5ba6c1e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f284605b-3271-4c82-a081-50e9dcc5ed6d', 'adfaba4f-b643-44db-9129-59112cbd9d3b', 12, '100150139', '『そして領主になる』', '【シーズン1 最終話】邪神･アーロンの気配を感じ取るカイン。魔王･セトや、冒険者ギルドの力を借り、『氾濫』を納めるべく行動を開始する。しかしあまりにも多い魔物たちに、ミリィやニーナたち冒険者は苦戦を強いられる。そこへ助けに入ったのは近衛騎士団･ティファーナで――。そしてついにカインは因縁の敵･アーロンと対峙することとなる! しかし圧倒的な能力に気圧されてしまい……。果たしてカインはアーロンを倒すことが出来るのだろうか!?', '2023/06/25 21:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f431492-0a6c-49b0-b4ac-f6949c70e389.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('69dd9b1c-8067-41d0-a484-5ddd08a35c95', '転生賢者の異世界ライフ ～第二の職業を得て、世界最強になりました～', '', 'hulu', 'my-isekai-life', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f26034d4-7399-44e3-8ddb-0f0e8536ba4d.jpg?w=331&h=447&p=t', 'hulu', 2022, 2, 1, 'FINISHED', NULL, 129192, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('915ed8de-51b4-42ab-a8de-23a30a0ae64b', '69dd9b1c-8067-41d0-a484-5ddd08a35c95', 'hulu-my-isekai-life-s1', '第1シーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3779290a-e9b2-4280-9ceb-61e0c4f17bd3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76231525-5d40-4bbb-a5ac-27a463cc1f6e', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 1, '100117147', '街を守りたくなった', 'ファスタンの街の冒険者ギルドを訪れるユージ。そこへ凶暴化した1万もの魔物が街に向かっているとの報せが入った。街に冒険者がいるとはいえ多勢に無勢、ここは逃げるしか手段がないのだろうか?――ギルドにいた一同が静まり返ったそのとき、ユージは自分が持ち帰ったドラゴンの骨から炎を再現し、魔物たちを一掃することを提案する。ユージの考えに賭けて、協力を申し出る冒険者たち。彼らが門の外で魔物を食い止めている間に、ユージはスライムたちと協力して魔法の準備に取り掛かる。すると、森にいるドライアドから緊急の連絡が。ドライアドが発見した怪しい男は魔石を持っており、おそらくその男が魔物を出現させているに違いない。ユージは魔力投網で男を捕らえるが……。', '2022/07/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3779290a-e9b2-4280-9ceb-61e0c4f17bd3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2aa0a2b-139b-4b5d-a4f3-25eea0855ece', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 2, '100117148', 'パーティーを組んでみた', 'ファスタンの街を救ったユージだったが、騒がれるのはなるべく避けたいと言って街を出ていった。そんなユージ一行がたどり着いた次の街はキリア。さっそく冒険者登録を済ませたユージは1件の依頼と、仲間となるパーティーを紹介される。パーティーのメンバーは短剣使いのロディスと、弓使いのティナ、槍使いのリーサという3人の男女。ロディスはテイマーであるユージを足手まといと小馬鹿にするが、そういうロディスをティナとリーサはいまいち信用していない様子だった。依頼の内容は「アース･ドラゴンの居場所の特定」というもので、ユージは索敵を任されることに。夜になり、パーティーは森でキャンプすることになったが、見張り役のロディスが忽然と姿を消して――!?', '2022/07/09 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ab69627-e63f-4ab0-b890-5676304bf86e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1e710d2-37a2-456e-b669-7a30e9ffb479', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 3, '100117655', '強すぎるって意味だった', '森で盗賊団を捕らえたユージは、ティナ&リーサと共にアース･ドラゴンの捜索を続行することに。近くにいる魔物をスライムたちに倒させながら歩みを進めると、盗賊の件でスライムの強さを目の当たりにしたティナとリーサはさらにその強さに驚愕。すると、スライムたちがアース･ドラゴンとは別の巨大なドラゴンを発見。パーティーはひとまずデライト渓谷に退避することになった。スライムたちとプラウドウルフが先行してデライト渓谷の魔物を倒し、パーティーの安全を確保したのも束の間、突然ユージたちの目の前で地割れが起こり、その裂け目からアース･ドラゴンが出現! 自分の強さをティナとリーサに悟られたくないユージは、何とかして二人にバレずにアース･ドラゴンを倒す方法を考える。', '2022/07/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/471a364a-c741-4c61-86a7-214933c5c1b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9a41b1a8-55b5-48f3-87db-7fac55c9d0f8', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 4, '100118135', 'いろいろ異常事態だった', 'アース･ドラゴンを倒したユージだったが、もう1体のドラゴンがまだ残っていた。「デライトの青いドラゴン」と名付けられたドラゴンを倒すため、街では討伐隊を結成。明朝に総攻撃を仕掛ける手筈になっていた。しかし、巨大化したドラゴンの力はあまりにも強大。ユージは単独でスライムたちとプラウドウルフを引き連れ、夜のうちに森へと向かっていった。攻撃魔法が効かず、森を破壊することで魔力を吸収するドラゴンに対して、ユージが取った選択は教会で渡された「ケシスの短剣」で戦うことだった。広範囲を焼き尽くす「終焉の業火」を「ケシスの短剣」に集中させれば、かなりの威力が得られるはず。そう確信してドラゴンに立ち向かうユージ。はたして、勝利できるのだろうか?', '2022/07/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55ac379e-c67f-4203-b565-fe0380f930b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('613e787f-0651-429d-9f76-661181a8a80e', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 5, '100118683', '寒くて大変みたいだった', 'ユージがめざす次の街はリクアルド。これまで何かと異常事態に遭遇してばかりのユージだったが、ティナとリーサによるとリクアルドは気候も温暖で食事も美味しく、過ごしやすい街とのこと。だが、たどり着いたリクアルドは話とは真逆の、強烈な猛吹雪に覆われる極寒の街だった。街の門番によると、どうやら十日ほど前からリクアルドは大寒波に襲われているらしい。門番の勧めで立ち寄った虎火亭という店でも料理用の薪が確保できず、休業を余儀なくされているという。それでも料理を食べてみたいと思ったユージは魔法とスキルを駆使して薪を手に入れ、料理長に最高の料理を作らせる。その味はまさに絶品で、感動したユージは大量の薪を調達するため冒険者ギルドを訪れる。', '2022/07/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/facdcfe3-c47c-472a-a139-0d9593a01933.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d48d4f19-71dd-4585-8eff-41f4ed4e43ad', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 6, '100119477', '怪しい村に潜り込んだ', '薪を大量に調達してリクアルド名物の煮込み料理を味わったユージだったが、料理長によるとまだ最高の煮込みではないという。ここ最近、畑が魔物に荒らされて材料のリシア草がなかなか手に入らないらしく、ユージはさっそく魔物退治に出発する。すると、森の中で寒さの原因になっていると思われる呪いの魔石を発見。複数の魔石が散在していたその中心部を破壊すると、その先に地下へと続く入り口らしきものが現れた。地下空間の中で見つけたのは巨大な機械と怪しげな男たち。そして、通路を抜けて地上に出ると、そこはリクアルドに来る前に訪れたメシアス村だった。メシアス村には「救済の蒼月」の信者が隠れ住み、ひそかに魔石を作っていたのだ。「救済の蒼月」の恐るべき企みを知ったユージは……。', '2022/08/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7e29354-19bb-4010-bac7-d4411ac74bfe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da3bdc61-1290-4364-825c-0f1672b1a692', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 7, '100120095', '暗殺者に狙われていた', '「救済の蒼月」が狙う暗殺対象の候補者リスト。そのなかに自分の名前があることを知ったユージはリクアルドを出ていくことにする。冒険者ギルドで勧められた次の目的地は魔物防具の名産地ボギニア。ユージはそこに住むガイゲルという腕のいい職人の店を訪ねてみることに。しかし、ボギニアに着いたユージはガイゲルの店に入るも手持ちの金が足りなくて弟子に追い払われ、街ですれ違いざまにぶつかった男にはぺこぺこ頭を下げ、食料を買う金もなく、挙句の果てにはスライムたちに地面に落ちた小銭を拾わせるという信じられないくらい情けない行動ばかり。ユージを暗殺対象候補として付け狙う「救済の蒼月」の暗殺者、ルディとソニアもそんなユージの様子を見て呆れるばかりで……。', '2022/08/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64f8058b-e5a1-4f93-a106-9c49de13827b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('189c4d4c-7b14-4e98-aae7-ee9645fb1d0b', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 8, '100120567', '魔物防具を作ってもらった', '無事に暗殺対象候補から自分を外させることに成功したユージ。ガイゲルの店を再度訪れ、魔物防具を新しく作ってもらえることになった。ただひとつの問題は、希少なブルーレッサーファイアドラゴンの宝玉を手に入れなければ、ユージの魔法に耐え得る防具が作れないということ。さっそく冒険者ギルドに行って、討伐依頼を引き受けるユージ。だが、レッサーファイアドラゴンには魔法が効かず、大量の水を浴びせて倒すしかなく、川を渡らないとドラゴンの棲む場所にもたどり着けないという。さらに川にはマンイーターバスという凶暴な人食い魚が生息しているが、ユージはついでとばかりにマンイーターバス退治の依頼まで引き受ける。', '2022/08/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06afc178-ed55-401c-bd33-7e9c9e178b39.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('868e204a-7218-4b5a-8f03-e018099fceb5', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 9, '100121390', 'ファイアドラゴンと戦った', 'ブルーレッサーファイアドラゴンの宝玉を使って魔物防具を作ってもらったユージだったが、ファイアドラゴンの宝玉を使えばさらに強力な防具が作れるという。ちょうどその頃、火山が噴火してマグマの中からファイアドラゴンが出現! 弱点である水をかけられない限りは暴れることのないファイアドラゴンだが、怪しげな二人組の男が呪いの水をファイアドラゴンに使おうとしていた。ユージに取り押さえられた二人組が自決したことで事なきを得たものの、間の悪いことに雨が降り始めてしまった。降り注ぐ雨が体に落ちるや、怒り狂うファイアドラゴン。過去に一度だけファイアドラゴンの出現と雨天が重なったときは、ボギニアを街ごと焼き尽くしたらしい。ユージは街を救えるか?', '2022/08/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f499a48c-e4bf-45df-a931-e05fc77710f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d95ff7e7-1b49-4367-a29c-37f5ab7ce632', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 10, '100121745', 'それどころじゃないみたいだった', 'ユージはオルダリオンの街で、かつてキリアで出会った司祭シュタイルと再会する。シュタイルは神のお告げを得て、オルダリオンの教会でユージのことを待っていたという。すでにギルドが「救済の蒼月」の手に落ちているこの街で、シュタイルがユージに伝えたいことは自身とヴァルターという男の過去と、ここに来る理由となったお告げの内容について。そのお告げによると、今まさに世界を混乱に陥れているヴァルターのもとに使者が現れるそうで、ユージこそが使者なのだとシュタイルは言う。ユージが使者である何よりの証は「ケシスの剣」を所持していること。そもそも「ケシスの剣」を渡したのはシュタイル本人だろうと訝しがるユージだったが、ほかにも思い当たる点があって……。', '2022/09/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aebb1e4b-689e-402d-af4f-ebf7161f9b66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07595341-5b0e-41ac-af16-c26cd0252a45', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 11, '100122894', 'お告げの通りになった', '「救済の蒼月」の砦で、ついに対峙するヴァルターとユージ。ヴァルターはユージやシュタイルらの目の前で「竜の恵み」を自らの体内に取り込み、異形の怪物へと姿を変えていく。動きが素早く、体も頑丈で、たとえダメージを受けても魔物化した信者を吸収することで回復するヴァルター、「竜の恵み」の力に死角はないかと思われた。しかし、ユージの魔法はさらにその上を行き、ヴァルターを瀕死の状態にまで追い詰める。ところがヴァルターの顔に浮かぶのは苦悶ではなく歓喜の表情だった「私が使者を倒そうとも、使者が私を倒そうとも、どちらにせよ同じことなのだ」。そう言ってヴァルターはあっけなく事切れる。はたして、ヴァルターが最期に残した言葉の意味するところとは?', '2022/09/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52ff69f1-056a-46e1-bc1a-a5232ee396de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a8c3401-fb2b-44c1-8563-329053cde7dd', '915ed8de-51b4-42ab-a8de-23a30a0ae64b', 12, '100123592', '転生賢者の異世界ライフ', '【シーズン1 最終話】シュタイルがユージに伝えたお告げには続きがあった。「導く者の死によって、賢者が現れる」。その文言にある「導く者」とはヴァルターのことで、ユージに倒されたヴァルターがその身を依り代に神話に書かれた賢者を蘇らせたのだ。幾度となく危機に見舞われる世界を救済するため、世界を滅ぼそうとする賢者。その呪いの力によって、世界中の魔物が凶暴化して暴れ出した。目の前で襲いかかってくる賢者と戦いながら、すべての魔物を相手にするのはさすがのユージにも至難の業。すると、テイムしているスライム達から通信が入り、これまでユージが訪れた街で出会ってきた人々が、自分たちの街を守るために立ち上がった様子が伝わってくる。そう、ユージは決してひとりではないのだ。', '2022/09/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb2f6459-bb94-410f-97cf-ce10a5ca42ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('13c09234-870c-4977-bece-a32fec9afe34', '転生宗主の覇道譚 ～すべてを呑み込むサカナと這い上がる～', '', 'hulu', 'the-all-devouring-whale', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bab50b28-9b72-436b-821c-5ea06e6c0e67.jpg?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'FINISHED', NULL, 191974, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
