INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('87825cc6-9c55-4be4-96cc-db956dc35d89', '電波教師', '', 'hulu', 'ultimate-otaku-teacher', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50021062_series_art__338x600_ultimate_otaku_teacher_43126b7bd15279767eb1db9882533641.jpg?w=331&h=447&p=t', 'hulu', 2015, 1, 1, 'FINISHED', NULL, 21018, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('cfe103ac-fdfd-43df-89d0-6502ff218755', '奴隷区 The Animation', '', 'hulu', 'dorei-ku-the-animation', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/520df30b-4c43-4da9-aa1f-4bfa18c9eb47.jpg?w=331&h=447&p=t', 'hulu', 2018, 1, 1, 'FINISHED', NULL, 100251, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d8e2bbcb-1810-42f9-bc85-99142802e7a7', 'cfe103ac-fdfd-43df-89d0-6502ff218755', 'hulu-dorei-ku-the-animation-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45039c32-036d-4b3d-819f-f4a9b17cc03f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bbacb096-26d6-4742-8b4d-a7c39a7266c9', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 1, '100101204', '選択 －sentaku－', 'フリーターの荒川エイアは、友人の紹介で太田ユウガに出会う。ユウガは『SCM』と呼ばれる「他人を奴隷にできる器具」を使った勝負に協力するよう、エイアを誘う。同じ頃、OLの杉並ルシエはある復讐のため『SCM』を手に入れていた。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45039c32-036d-4b3d-819f-f4a9b17cc03f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a985331-87cb-4604-8a52-e5a438095ed4', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 2, '100101205', '束縛 －sokubaku－', '歌舞伎町No.1ホストの新宿セイヤは、常連客の豊島アヤカを邪魔に思い『SCM』で奴隷にしようとする。しかし、彼の企みはアヤカに見破られていた。逆にセイヤを奴隷にし返して、彼を独占しようとするアヤカ。そんな二人の前に、エイアとユウガが現れ、勝負を申し込む。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a5cce11-aa29-415e-b78c-09f4fd62c697.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b659807c-08fa-45f6-947a-766da147595b', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 3, '100101206', '被虐 －higyaku－', 'セイヤの前に姿を現した元カノのキャバ嬢、葛飾ジュリアは、「リュウオウ」と呼ばれる主人の奴隷になっていた。リュウオウに奴隷を奪われ、対抗意識を燃やすユウガ。一方その頃、秋葉原の『お姫様カフェ』で働く足立シヲリは、『SCM』を手にした女性、中野タイジュに、自分を奴隷にしてほしいと頼まれる。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b8d1f543-5f70-49fb-9173-9fd378de78ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d8e6173-9240-423f-9ea1-d068962ce7d2', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 4, '100101207', '計画 －keikaku－', 'シヲリとタイジュを力ずくで奴隷にしようとした文京ゼンイチは、『SCM』を付けた犬、ズシオウマルに敗北してしまった。しかし、タイジュたちは、シヲリを助ける代償として、リュウオウの部下、中央アタルとジュリアの奴隷にされてしまう。一方、人嫌いの青年、品川ゼロは、親の敵討ちをしたいと言う少年に出会う。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f348d6b-c6f7-472d-a68c-932b7cb2955a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be8f5b8e-fee2-4235-bdad-a15b934634d3', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 5, '100101208', '困惑 －konwaku－', '着々と奴隷を増やしていくリュウオウの元に、『あたまのおかしいひと』を名乗る人物から挑戦状が届く。同じく『あたまのおかしいひと』の挑戦状を受け取ったユウガは、勝負を受けようとするが、『SCM』に不信感を抱くエイアと衝突してしまう。『SCM』の勝負から身を引こうとするエイア。そんな彼女の元に、ユウガが敗北したという知らせが届く。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3af4d37-3cb8-4c1d-b8bc-5ec944e1df5f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('184509ef-fb09-4a03-93be-0454fe46dad5', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 6, '100101209', '自覚 －jikaku－', 'かつてエイアのもとを離れ、放浪していたズシオウマルは、『SCM』が生まれた瞬間を目にしていた。一方、エイアを騙して従わせようとしたユウガは、本物の『あたまのおかしいひと』と遭遇し、拉致されてしまう。奴隷となったユウガを、最悪の屈辱が待ち受ける。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a39b14d-f25e-498f-8f51-76ef13557952.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7803e999-6444-4f41-821e-d06b78e847f1', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 7, '100101210', '隷属 －reizoku－', 'リュウオウと出会った頃を思い出すジュリア。リュウオウの本当の目的を知ったジュリアは、彼のために尽くすことを決意する。『あたまのおかしいひと』の挑戦を受けたリュウオウは、互いの奴隷を駒にした集団戦へと挑む。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49e6c1d0-9055-4242-8a34-6d1efc2538b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b77b59d-fd2a-48a7-8003-8de134811ab8', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 8, '100101211', '発覚 －hakkaku－', 'マップに現れた謎の反応、『星印のSCM』について調査すべく、リュウオウはジュリアたちを都内の学校へ潜入させる。一方エイアは、夜の街の実力者、練馬ムオンを味方にすべく、真向から勝負を申し込む。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36f32fd6-7ba0-4d63-a020-b90950297478.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('277c95ce-b8a3-412f-96ec-8cbb4b92d025', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 9, '100101212', '交錯 －kousaku－', '崇拝する動画配信者『マリア』のため、彼女から授かった『SCM』を手にリュウオウを追う男子学生、板橋ゲッコウ。彼はマリアに下された指示に従い、『キヨ』という人物と協力してリュウオウを追い詰めるが……?', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb8a719e-ede4-478f-ac13-4b1bae9038b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e6bfaff-dfe5-4c5c-b200-1159b4d823a3', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 10, '100101213', '転落 －tenraku－', '奴隷を失い混乱するリュウオウ陣営。しかし、主人たるリュウオウは奴隷の指揮を止めてしまう。『SCM』を手にし、その戦いへ身を投じる決意をした過去に心をさまよわせるリュウオウ。その傍らには、常にジュリアの姿があった。一方、行方不明のジュリアたちを奪還すべく、アタルたちは独断で、SCMを流通させた元凶、世田谷ツバキに勝負を挑む。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a7c11ec-de09-4f6d-a524-3208ef63544e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ab9fc4c-7293-4457-a26c-b4a848439d00', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 11, '100101214', '収穫 －syukaku－', '『ジャッジメントSCM』の力でアタルたちを奴隷にしたツバキは、エイアたちに宣戦布告をする。人質にされたサチを助けるべく、ムオンの協力を得て奪還作戦を計画するエイア。その企てすら掌上に弄ぶツバキだが、彼を待ち受けていたのは、裏切りと隷属の結末だった。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0a494e6-a225-4f37-ac61-2ceec5b8a9fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d983f95f-0a50-4d29-8c4f-abb5a33e2b26', 'd8e2bbcb-1810-42f9-bc85-99142802e7a7', 12, '100101215', '起爆 －kibaku－', '【最終話】ツバキを奴隷にし、すべてを手に入れた港タキオ。エイアはすべてのSCM所持者たちを解放するため、最後の勝負に挑む。多数の奴隷を従えるタキオの牙城を崩すため、エイアに手を貸したのは、エイアがSCMと出会う切っ掛けとなった男と、かつて奴隷を奪い合った最大の敵だった。', '2022/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/995dec6d-7e4d-48bd-965c-ec8d46077366.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('545cfb92-b51e-4df7-8afa-0afca8d4e036', '凍牌～裏レート麻雀闘牌録～', '', 'hulu', 'tohai-ura-rate-mahjong-tohai-roku', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06080362-48f9-4227-aa73-200798a23642.png?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 173263, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f74df0bb-ddc2-48e3-b52c-c33deeca20ad', '545cfb92-b51e-4df7-8afa-0afca8d4e036', 'hulu-tohai-ura-rate-mahjong-tohai-roku-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2682e92d-20ad-4c2d-bf77-8e547dc1ded8.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a972bbde-14c3-43ac-a87f-8b63770e8e28', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 2, '100202433', '少女', 'インターネット麻雀で知り合った「まっちゃん」から初めてのリアル麻雀に誘われたケイ。しかし、まっちゃんはマトモな社会の人間ではなく、はじめからケイをカモにするつもりだったのだ。タガログ語で会話するまっちゃんたち3人のチームプレーに翻弄され、ケイは次第に追い詰められていく。そんなケイを救ったのは、アミナという少女の発した一言。大逆転で勝利したケイだったが、彼が欲したのは金ではなく意外なものだった。', '2024/10/19 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2682e92d-20ad-4c2d-bf77-8e547dc1ded8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('42079cc9-df80-4316-8278-1a4983f7c251', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 3, '100202605', '堂嶋', 'ケイはアパートの部屋で段ボール箱いっぱいの札束を見せる。それは賭け麻雀で稼いだものだったが、「お金より命だいじ」というアミナの心配をよそにケイはまたも高レートの卓へと出向いていく。そこで待ち構えていたのは堂嶋という男。衝撃的な出会いを果たした堂嶋との再戦に、ケイは静かに闘志を燃やしていた。堂嶋が用意した1億に対して、ケイの持ち金は3千万。互いの有り金全部を賭けて戦うデスマッチ、勝つのはどっちだ!?', '2024/10/26 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63ba4b24-370c-454d-90e0-5bf04af97f05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65140741-cfd9-458c-a30e-c605213b063e', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 4, '100203549', '畑山', '「賭け麻雀はもう潮時」――そう思うケイだったが、関からの電話はやはり断れず、畑山という男とコンビで代打ちをすることに。勝てば報酬は2千万、ただし負けた場合には足の指10本を奪われる大勝負に挑むケイ。しかし肝心の畑山は勝負の前でもグーグー寝ているような、のんきな男だった。しかも、コンビ打ちにも関わらずケイと足並みを揃えようともしない。だが、ケイが自分から役満を上がったことで畑山の目つきが変わっていく。', '2024/11/02 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/933b680f-cc8b-4539-bf85-d7139b4c61b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da6df3cf-5a3b-4e4b-8cca-b6a5ec388637', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 5, '100204105', '小指', '「一軍」入りの最終テストを受けさせられるケイ。目を覚ましたときには、無残にも左足の小指が切断されていた。再接着までのタイムリミットは残り約4時間。雀荘で1万円を2万円に増やせば小指を取り戻すことができるが、麻酔と痛みでうまく頭が回らない。ケイは傷口に塩を塗ることで強引に頭を覚醒させ、改めて勝負に挑む。しかし、そこに堂嶋が現われ、ケイと同じ卓で打つことに。刻一刻と時間が迫るなか、ケイは強敵とどう戦う?', '2024/11/09 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de09db52-2bdc-4088-bd67-668abe03bbdb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eff4e73d-43e0-489e-b08a-6f00620ed2ef', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 6, '100205103', '選択', 'ケイが「一軍」となってから1か月。代打ちとしての役目を着実に果たしていくケイに、桜輪会の柳も一目置くようになっていた。そんなとき「一軍」から選抜メンバーを決めることになり、ケイは見事に競争相手を打ち破る。しかし、ケイの必死な戦いぶりに高津は疑いの眼差しを向けていた。関とつながっているケイには、何か裏があるかもしれない。事実、ケイはアミナの家族ビザが取れると関に言われ、そのために桜輪会に潜入したのだ。', '2024/11/16 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad0cc204-a975-4633-bdda-fb006cb2a12d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f8ad414-bfe6-47f2-9c6f-e677cc909288', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 7, '100205292', '黒幕', 'ケイは堂嶋とのコンビで代打ちに臨む。相手側の代打ちは関と、変わり果てた姿になった畑山だった。破滅という名のギャンブルを楽しむために人間を辞めたという畑山の異様さに、自分の覚悟はぬるかったと自虐的な笑みを浮かべる堂嶋。1回戦をチョンボで負けて終わらせた後、2回戦に突入する前に彼は驚愕の宣言をする。この勝負に負けたら自分は麻雀をやめる。それどころか二度と牌を握れないように両腕を丸々切り落とすと――!!', '2024/11/23 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bc8659f-849b-4e3f-8519-cfc6b86f7888.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea8afd89-989f-48a4-9a86-dd25523e5ed4', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 8, '100206595', '決死', '高津はこの勝負の黒幕が関であること、そしてケイが関と裏でつながっていることを確信する。ケイの頭に銃口を突きつける高津だったが不発に終わり、関に振り込んだ瞬間に今度こそ殺すと脅しをかける。ケイは1回だけ関にわざと振り込むことを約束しており、最終戦でいよいよその場面がやってきた。牌を手に取るケイを見て、引き金に指を掛ける高津。するとケイは何を血迷ったか自分が裏切り者だと自ら宣言し、信じられない行動に出る!', '2024/11/30 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc353203-0e3e-4115-98b6-0e0f96487524.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d10ef24c-49bc-4423-8f46-96f3401c9f3a', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 9, '100207388', '終局', '関を裏切り、けじめをつけるために切腹したケイ。そのまま麻雀を続けるケイの姿に自らのアイデンティティを取り戻した畑山。今や関は完全に孤立していた。しかし、出血が止まらないケイに残された時間はあとわずか。ホチキスで傷口を止める高津の荒療治を受けてオーラスに臨むものの、限界は迫っていた。そんなケイを見て時間稼ぎをする関をその場にいた誰もが許しはしない。彼らはケイの命を張った大勝負を見届けようとしていたのだ。', '2024/12/07 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8cbb7421-9439-4ebc-8f10-c3ec8715568c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44df92a3-8b13-43bb-872c-672df45acd3e', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 10, '100208273', '慧眼', '高津組による佐々山組麻雀賭博場への荒らしは、高津の予想以上に時間がかかっていた。戦場と化したマンションに現れた高津組「一軍」の松本は二日間ぶっ通しで打ち続けるケイに学校に行くように促し、その間は自分が引き受けると言う。翌日、学校から佐々山組のマンションに向かったケイを松本が穏やかな顔で迎えるが、その姿を見てケイは愕然とする。松本は両手の指をすべて切断されていたのだ。松本を負かしたのはアイという女だった。', '2024/12/14 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/561a75c2-9c5d-4226-9b50-6583d745e3e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0cb86cee-92a0-4c09-801c-d05702f1ba10', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 11, '100209589', '暗鬼', 'すべてを読むことができるアイの瞳に追い詰められ、ついにケイは自分の指すべてをかけた勝負を受けさせられる。負ける恐怖におびえるケイに「逃げるな」と声を掛ける松本。その言葉にハッとさせられ、ケイの顔つきが変わっていく。それでもアイは余裕の構えを見せていたが、自分の手牌をオープンすることから始まったケイの不可解な行動に、次第にケイのことが読めなくなっていく。初めて焦りを募らせるアイを、ケイは見逃さなかった。', '2024/12/21 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e7b049c-2fa9-4136-ac97-d31231d89318.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4691dc9-4331-461f-b0de-c9c8c6f6ecb2', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 12, '100210347', '価値', '昇心会との縄張りを賭けた勝負で、代打ちに臨むケイ。そこに相手側の代打ちとして現れたのはクラスメイトの上野と幼なじみの優だった。ケイに対抗心を燃やす上野と、ケイの秘密を見せてやると言われてついてきただけの優。昇心会は優を人質として、ケイの動揺を誘う魂胆だったのだ。昇心会の男は優の服を脱がし、さらに手の甲にアイスピックを突き刺すという暴挙に出る。それでも一切動じないケイに、優は自分の死を覚悟して告白する。', '2024/12/28 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20a5781c-247c-4f81-970a-dff81b1f5a75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5afebd16-27c9-4d87-9336-2354fe924004', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 13, '100212401', '大会', '優を助けるため、高津に借りを作ってしまったケイ。金はチャラにしていいという高津だったが、ケイにある頼み事をする。その頼みとは、ケイに「日本一」の肩書きを手に入れてもらうこと。かくしてケイは竜凰位トーナメントという日本最大の麻雀大会に出場することとなった。ケイは畑山との再会を喜びつつ、いつもとは違った“表”の大会で純粋に麻雀を楽しんでいた。そして予選通過を賭けた最終戦で、畑山と白熱の勝負を繰り広げる。', '2025/01/18 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d0a0048-bcf7-4b59-b3a8-e2ab02534b87.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('730531c7-b35b-43b9-ba77-a1a967fd463c', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 14, '100212816', '指先', '一次予選に「K」の登録名で参加していた少年が家族もろとも火事で命を落とした。きっと「氷のK」と間違われて消されたんだろうと高津は言う。予選1位の畑山も狙われているという高津の読み通り、二次予選の会場に畑山の姿はなかった。今、ケイと対峙しているのは以前に畑山が警戒していたサングラスの男。ケイの脳裏に思い浮かぶのは畑山、そしてK少年と打った楽しい麻雀。そんな束の間の平和に別れを告げ、ケイは復讐を開始する!', '2025/01/25 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fe36359-db2a-4406-b3df-50d7a714b197.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0da7cdbe-7786-4c08-8c1c-f6e978ec68eb', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 15, '100213704', '女王', 'カタギの大会であるはずの竜凰位戦の裏で、何か大きな陰謀が蠢いていた。その全貌はわからないが、阻止するためには絶対にケイが優勝しなくてはならない。そして迎えた決勝ラウンドでは、九州地区から堂嶋、東北地区からアイ、さらには関西地区から高津の因縁の相手である伝説の男･大辻と、裏の世界の住人が顔を揃えていた。初戦でいきなりケイと当たったアイの瞳には、もはやケイしか映っていない。今日こそケイを超えられるのか?', '2025/02/01 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f0528d2-d218-4539-9793-b7de96373d88.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c66668c1-f0ea-4865-bb54-62c142454eb2', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 16, '100214593', '秘密', '決勝第一ラウンドから数日後、ケイは第二ラウンドに向けて研究に余念がなかった。そこに大辻が乗り込んできて、サンピン勝負を持ちかける。麻雀牌を使った簡単なルールの遊びで、2回勝負で前歯を賭けるという大辻の狙いが何かはわからなかったが、大辻を知るためにも勝負を受けるケイ。そんなケイの前で、大辻は自分が竜凰位戦の参加者殺しに関わっていたことをベラベラと喋りだす。畑山の死に様を嘲笑う大辻。ケイは怒りに身を震わせる。', '2025/02/08 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7f467880-a7e0-4eb3-9d8d-0792a1aedf54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c010aac-077d-4bb6-9ca9-b59d0d278f0a', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 17, '100215298', '誤算', '大辻との勝負に勝ったケイは、前歯の代わりに情報を求める。大辻から得られたキーワードは「名簿」。それは何を意味するのか……? その夜、ケイが帰宅するとアミナが血まみれで倒れていた。アミナの病名は腎芽腫。すでに末期まで進行していて、助かる方法は腎臓移植のみ。しかも、今すぐ移植しないと1か月以内に死亡する。普通の手段ですぐに腎臓を手に入れることは不可能だが、「名簿」があれば何とかなるかもしれないと高津は言う。', '2025/02/15 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81479b39-7cf8-4478-95f1-01d8ae0420aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ff7cc58-10c3-40d8-bcea-2dff1f9020c7', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 18, '100216690', '背水', 'アミナを助けるためにも、ケイはどうしても竜凰位戦で優勝するしかない。決勝戦に進めるのは第二ラウンド終了時点での上位4名のみ。しかし、ケイの最終的な結果は5位。ここで敗退が決まってしまった……。自ら詰めた小指を差し出して、何とかアミナを助けるチャンスをもらえないかと高津に懇願するケイ。高津は小指を受け取らず、竜凰位戦のことは堂嶋に託すと言う。しかし、その堂嶋が何者かに襲われ、両手と両目を潰されてしまった。', '2025/02/22 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f5b0fde-7b1b-4f87-91f7-9872dfc4b01e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abe97b49-7ead-4ea9-9e7c-c9483c0ce8f8', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 19, '100217715', '神業', '棄権した堂嶋に代わり、決勝戦に出場するケイ。対戦するメンバーはアイ、大辻、そしてプロ雀士の前川だ。今日の勝負で負けたらこの場で大辻を殺して自分も死ぬ――ケイはそれだけの覚悟をもって戦いに挑んでいた。強敵･大辻に重圧をかけるためにケイが取った手段は“初心者の麻雀”を打つこと。ビギナーズラックが起きるのを恐れる大辻がペースを乱すことを狙っているのだ。そんな小細工は通用しないと高をくくっていた大辻は……。', '2025/03/01 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ec162f6-f562-4584-a72d-d3415c708779.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e47335ea-52f9-4807-bd6e-5327bdcbed31', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 20, '100218520', '竜凰', 'ケイに対して「そっちがその気なら」とイカサマを解除する大辻。だが、大辻の強さはそれだけでは説明できないものだった。実は大辻は牌を重さで判別することができ、それに気づいたときからケイの反撃が始まった。大辻の性格まで読んだうえで一発逆転の賭けに出るケイ。見事に数え役満を上がり、三回戦を終えた時点でトップに躍り出た。そして迎えた最終戦、ケイと大辻の立場は完全に入れ替わり、大辻は死の恐怖に怯えるばかりだった。', '2025/03/08 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32b0c698-086e-4fb0-8794-91bc5f4340df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51b1ba55-5d2f-43f5-8287-292c7b5c1241', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 21, '100220188', '氷の男', '第27代竜凰の称号を手に入れたケイは今、北海道にいた。ケイを待ち受けていたのは羽鳥という青年と関の二人。羽鳥はアミナに移植手術を受けさせたという。しかも「名簿」も所持しているという羽鳥は、ケイと高津に2対2のコンビ戦を持ちかける。ただし、勝敗を決めるのはケイと羽鳥の点数のみ。しかもケイの点数が6000点減るごとに“人柱”の命が奪われるという残酷なルールを提案する。その人柱の中にはケイの両親と、優がいて……!', '2025/03/15 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66d21915-cf1f-4748-b3c8-5461e4a4c520.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35e28172-08a9-4391-90b2-b0103ffc36da', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 22, '100220309', '二つに一つ', '高津は羽鳥がただの素人ではないことを見抜く。羽鳥の正体はケイも参加していたネット麻雀のランキング1位「アイスマン」だった。その名の通り、一切の感情なしに淡々と勝利を手にしようとする羽鳥。次に点数を取られたら、ケイの父が首吊りの犠牲になってしまう。するとケイは勝負を降り、まるで見殺しにするような形で父の首吊りが実行されることに。死を目の前にした父に対して、ケイは自分が両親の秘密を知っていたことを告白する。', '2025/03/22 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bea5ac5a-e108-4237-bccf-93cb201771a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d77823c8-a6f5-40ba-af81-840b269bfae4', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 23, '100221341', '絶望の館', '羽鳥のあまりに非道な振る舞いに、ケイは命を賭けろと羽鳥に要求する。羽鳥が提案した交換条件はケイの持ち点を3000点にまで減らし、1000点ごとに一人ずつ首吊りを実行。さらに0点を割ったらケイ自身も首を吊ることだ。仕切り直しの後、いきなりケイは2600点を振り込んでしまい、ケイの母とイケが犠牲に。冷静さを欠いたケイの点数はついに0点となってしまい、優が首を吊られる番になるが、ケイは優と交代すると言い出す。', '2025/03/29 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb082cfb-52aa-4b0b-87a9-a915dbe2f6f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2d7237b-7b97-45e7-9447-d4c125e126bd', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 24, '100222569', '最後の勝者', 'ケイは首を吊ったが、3分以内に処置すれば一命を取り留める可能性は残されている。早く決着をつけようと焦る優だったが、無情にも3分が過ぎ去ってしまう。わずかな可能性を求め泣き叫ぶ優とは対照的に、高津は高津組の組長としてケイを見捨てるという非情な決断を下す。オープンリーチをした高津の狙いは優と羽鳥の両者を0点以下にすること。自分が最優先すべきは部外者であるケイの命よりも組の存続という高津の、真の狙いは!?', '2025/04/05 02:53:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ddba7ccb-74a7-44f4-86ed-055e52d74b78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc7f61d5-297e-4b30-9b76-262e38f4f8f8', 'f74df0bb-ddc2-48e3-b52c-c33deeca20ad', 25, '100223382', '人柱', '【シーズン1 最終話】ケイの両親は生きていた。二人は首を吊られたふりをして、羽鳥のイカサマに協力していたのだ。それに気づいたケイは両親を逆に利用し、羽鳥を精神的に追い詰めることに成功。この常軌を逸した戦いは、優の勝利で幕を下ろした。しかし、羽鳥は最後の取引として、ケイの命を救う手助けをする代わりに今後一切自分に手を出さないことを高津に約束させる。裏社会を敵に回して生き残った自分に酔いしれ、高笑いする羽鳥。その背後には……。', '2025/04/12 02:53:00', 1417, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c77b8bf-7d18-495c-9a04-30ed46178743.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b70d1292-ae3d-4f50-8245-8777c32b2596', '劇場版 活撃 刀剣乱舞', '', 'hulu', 'touken-ranbu-hanamaru', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce30d54b-dbc1-47c8-9d91-dd92dc88b72e.jpg?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'NOT_YET_RELEASED', NULL, 100130, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 'b70d1292-ae3d-4f50-8245-8777c32b2596', 'hulu-touken-ranbu-hanamaru-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ae7627c-9b30-4165-a8f4-f485ecf46213.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ed6ff72-f2dc-4a43-bb99-13d224ba1573', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 1, '100011770', '【睦月】ちょーしにのんな', '17振りめの刀剣男士として“とある本丸”に顕現した『大和守安定』。本丸に来て初めての朝を迎え、元の主が同じ新撰組の沖田総司である、『加州清光』とともに雪景色に染まった本丸を散歩する。雪合戦など本丸での日常を楽しむ刀剣男士たちに、時の政府から連絡が入り…。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ae7627c-9b30-4165-a8f4-f485ecf46213.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eceef4fd-dab1-4c6c-9b66-f79ac7f25d28', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 2, '100011771', '【如月】言いたいことなんて…、何もない', '『同田貫正国』と『鶴丸国永』が顕現した。大和守安定･加州清光は2振りを連れて本丸の中を案内することに。一方で、織田信長にゆかりのある へし切長谷部･宗三左文字･薬研藤四郎の3振りをふくむ刀剣男士たちに、本能寺への出陣命令が下される。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9dfa00aa-3f03-4b38-9d81-304f1d174189.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18dbb0d3-de7a-4e04-8f81-a7f400a67cf5', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 3, '100011772', '【弥生】一万分の一なんですって', '『平野藤四郎』は大樹の下で幸運の四葉を見つけた。本丸へ新たにやって来た『鶯丸』に差し上げよう、と届けに行こうとするが、途中で邪魔が入りなかなか思うようにいかない。同じころ、大樹の下では粟田口派の短刀たちがまだ顕現していない兄に思いを馳せる。大和守安定は皆の願いを知り、ある作戦を考える。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec461519-6f8a-4932-b808-d489d17ec8b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c7f55ed-2c3e-403b-bfaa-7cdfb9c6bfc5', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 4, '100011773', '【卯月】強さって、なんだろうな', '『和泉守兼定』が顕現した。元の主が同じ新撰組、土方歳三の愛刀『堀川国広』は喜び、すぐに本丸案内を買って出る。大和守安定と加州清光も和泉守兼定との再会を喜び、新撰組の思い出話に花が咲く。一方、庭にある万葉桜は満開。その樹の下では刀剣男士たちが花見を楽しんでいるが、『次郎太刀』が酔ってしまい大変なことに…。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2fab8690-b083-4385-9735-7484f7ba7643.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f63aa6f-c930-4ce4-8adc-c81236f0a565', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 5, '100011774', '【皐月】優しいは、強い', '燭台切光忠と鶴丸国永は、顕現したばかりの『大倶利加羅』がこの本丸で馴染めるのか心配していた。歌仙兼定や鶯丸たちの行動を見た燭台切光忠は、あることを思いつく。一方、鍛刀部屋ではついに太刀『三日月宗近』が顕現した。天下五剣の登場に、刀剣男士たちが喜びに包まれるなか、主から出陣命令が下された。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2baa6585-7941-4cf6-9781-bcbc5cc63a24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2808ae1-a1f4-422e-9911-926e69b0ba4a', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 6, '100011775', '【水無月】この本丸は、めでたいね', '大和守安定と加州清光は、本丸に来て間もない『山伏国広』『御手杵』『博多藤四郎』らと江戸遠征を控えていたが、遠征直前に主が発熱し、床に伏せてしまう。遠征先である江戸の調査に加え、薬研藤四郎の助言による解熱効果のある薬草を採取するため、江戸の山中へ向かう…。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/710e4131-40ef-4481-a17a-8ab793c3efab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9316d5c-6ce2-42a7-9a94-02b5414db6fe', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 7, '100011776', '【文月】誰かを想う幸せ', '陸奥守吉行の発案で、海水浴へ行くことに。『浦島虎徹』をはじめ、希望した刀剣男士総勢17振りは、初めて触れる海を楽しむ。本丸に『江雪左文字』が来たことで、小夜左文字も喜んでいる様子。そんな微笑ましい風景を見て薬研藤四郎は…。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6598237f-aa42-4883-a9dd-bdec99dca5b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0829d114-be5a-441c-9e0d-b9301e5a5419', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 8, '100011777', '【葉月】幽霊退治戦隊、結成!', '『蜻蛉切』『日本号』が本丸に来て、ついに三名槍が揃った。縁側にやってきた青い鳥を、日本号はある思いから捕獲しようと試みる。その夜、秋田藤四郎がお化けを見たと怯える。本丸に潜む幽霊を退治しに、にっかり青江が立ち上がる。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10b8f184-d59b-4275-9701-3ff7bdeffe76.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc35a655-8c95-4f46-8cb4-40a6eb3eae3e', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 9, '100011778', '【長月】その過去があるから', '鳴狐は『小狐丸』と三日月宗近に手料理をふるまい、楽しませている。それを見た獅子王は「老齢の扱いでは負けられない」と鶴丸国永と共に三日月宗近を楽しませる作戦を考える。その頃、阿津賀志山へ出陣命令が出る。『岩融』と今剣が、源義経の因縁の地へ行くことに…。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d61ff133-dd5d-4706-9a59-15879f08710f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ab375f2-5ef7-4c8e-aae3-9f1713f472af', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 10, '100011779', '【神無月】本当に大事な思い出', '愛染国俊と『蛍丸』は、やる気なく振る舞う『明石国行』が本丸でうまくやっていけるか不安で仕方がない。そんな中、本丸で妙なことが連続して起こり、明石国行に疑いの目が向けられてしまう…。一方、小狐丸たちは江戸へ出陣する。雨の降る合戦場で、狐の嫁入りに遭遇する。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0599ef69-6236-413d-b71e-5e761b480ee7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('424a26f2-5367-42bc-b0a2-ecb84368989b', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 11, '100011780', '【霜月】沖田譲りの、冴えた一撃', '新撰組 近藤勇の愛刀『長曽袮虎徹』が顕現して間もなく、池田屋へ出陣の命が出る。出陣部隊には新撰組に縁のある刀と、坂本龍馬の愛刀、陸奥守吉行が選ばれる。隊長の大和守安定は、かつての池田屋戦の雪辱を果たすため、時間遡行軍の殲滅を誓う。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0a25d3a-86fd-4995-b932-55d98ead8cd2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70b2d8a3-fcbe-435e-8b62-54e91b7deebd', 'fe7ad5f5-eb68-4386-af6d-5fbb48ff2779', 12, '100011781', '【師走】僕たちの本丸は、今日も花丸', '【最終話】池田屋の一階で元の主、沖田総司に出くわしてしまった大和守安定。新撰組の一員に成りすまし、沖田と共に池田屋へ潜入する。不穏に思った加州清光は安定の後を追う…。', '2018/01/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fce2edf1-58ad-46a4-9ff7-791034ac072a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f00e9868-9975-4643-b96f-1d72d1d05a59', '刀剣乱舞 廻 -虚伝 燃ゆる本能寺-', '', 'hulu', 'touken-kai', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c1d4050-6d93-40fe-87cd-0c780db475f4.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 150085, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('026950c4-2bb8-4a78-b1c4-37b98e689121', 'f00e9868-9975-4643-b96f-1d72d1d05a59', 'hulu-touken-kai-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58ebbdcb-a823-4a1e-83ae-a284194d1298.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2894f67-d68f-4064-a855-178231bdad6b', '026950c4-2bb8-4a78-b1c4-37b98e689121', 1, '100179881', '廻転する夢', '燃え上がる本能寺の本堂――宗三左文字は何度も同じ夢を見てはうなされていた。そんなある日、新しく刀剣男士として顕現した不動行光は、自らを「織田信長が最も愛した刀」だという。同じ元主を持つ宗三左文字･へし切長谷部はそんな不動行光の言動に思うところがあるようで……。', '2024/04/05 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58ebbdcb-a823-4a1e-83ae-a284194d1298.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64418874-3eb9-419e-9a70-db5dd6b12079', '026950c4-2bb8-4a78-b1c4-37b98e689121', 2, '100180338', '物語る物語', '主から近侍を拝命した山姥切国広は、過去の出来事から自分は近侍に相応しくないのではと思い悩む。一方、顕現して間もない不動行光は出陣の命が下った刀剣男士たちに「俺も連れてってくれ」と頼むが、山姥切国広に諭され腑に落ちない様子。『歴史を守る』という意味がよく分からない不動は、無邪気な発言でへし切長谷部の顔を曇らせてしまい―。', '2024/04/12 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b147a917-cbe4-423f-b019-dac0c94ece1b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa3d7427-3778-4db4-acb0-40317db5ddc7', '026950c4-2bb8-4a78-b1c4-37b98e689121', 3, '100181644', '相応しき器', '宗三左文字と手合わせをするも、なにやら本調子ではないへし切長谷部。先日の不動行光とのやり取りがフラッシュバックし、刀だった頃の記憶を思い出してしまう。そんな中、気を利かせた鯰尾藤四郎が発した一言により二人の仲はさらに険悪に。信長への思いを互いにぶつけ合う二人を仲裁しようとする宗三左文字だったが―。', '2024/04/19 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3166fca8-bdc0-46aa-9492-9fbc5652b026.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('293120d3-17cf-470b-b926-bc584200a816', '026950c4-2bb8-4a78-b1c4-37b98e689121', 4, '100182179', '角逐の鋼達', '鶴丸国永が計画した『四部隊対抗戦闘訓練』。その組分けに宗三左文字･不動行光･へし切長谷部･薬研藤四郎は動揺を隠せない。実はこの戦闘訓練は、織田信長の元に在った刀たちの不和を解消するためのものだった。だが、相変わらずな様子の織田の刀たちに山姥切国広は苦い表情を浮かべる。それぞれの思いを抱きながら、戦闘訓練が始まるのであった。', '2024/04/26 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eade1c33-b032-4d02-b8c0-43fc3e805850.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f03651d5-f656-4d6c-b8ca-1278e6336348', '026950c4-2bb8-4a78-b1c4-37b98e689121', 5, '100182979', '再会と葛藤', '『本能寺の変』へと出陣した山姥切国広･三日月宗近･宗三左文字･不動行光･へし切長谷部･薬研藤四郎。宗三左文字と不動行光は共に行動していたが、道中ではぐれてしまう。不動行光を見つけた宗三左文字は刀だった頃の記憶を語るが、そこに時間遡行軍が現れる。へし切長谷部と薬研藤四郎も合流し迎え撃つ刀剣男士たち。そこにかつて不動行光と共に在った森蘭丸が通りかかり……。', '2024/05/03 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd70eb53-97e0-498e-8855-8d0dd825246d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7fb0203-9340-4ddd-a7e1-16585695ce99', '026950c4-2bb8-4a78-b1c4-37b98e689121', 6, '100183722', '本能寺の変', 'ついに『本能寺の変』が起こる。今回の任務に疑念を抱く薬研藤四郎や、表情が曇ったままの宗三左文字に「織田信長の物語に向き合わなければならない」と言うへし切長谷部。その話を聞いて「俺はダメ刀だ」と落ち込む不動行光。それぞれの織田信長への思いが交差する。そんな中、明智軍の兵に囲まれてしまった森蘭丸を助けたのは時間遡行軍だった。', '2024/05/10 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08562f98-1782-49dd-ac84-f5d0a17f6326.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6d17a7d-c807-464f-85a0-a395ef8aa14d', '026950c4-2bb8-4a78-b1c4-37b98e689121', 7, '100184297', '誰が為に咲く', '時間遡行軍によって迷宮化した本能寺。遡行軍により人外と化した森蘭丸を宗三左文字と不動行光が迎え撃つ。深手を負いながらも、逃げた明智光秀を必死に追う蘭丸に不動行光は説得しようとするも蘭丸は聞く耳を持たない。正気を失った蘭丸と対峙する刀剣男士たちだが、遡行軍が蘭丸の体を取り巻き……。', '2024/05/17 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/86617e4f-2d97-41c1-aeaa-53142f3da870.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4548ed3b-2d39-4b5a-a1e0-49b5b75f3ba8', '026950c4-2bb8-4a78-b1c4-37b98e689121', 8, '100184783', '燃ゆる本能寺', '絶命した森蘭丸の代わりに明智光秀を討とうと後を追う不動行光。時間遡行軍の軍勢と対峙しながら不動を追う宗三左文字･へし切長谷部･薬研藤四郎。ついに光秀を追い詰めた不動だが、刀剣男士としての使命との間で激しく葛藤する。その時、刀だった頃の蘭丸との記憶を思い出し―。', '2024/05/24 23:30:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5aa7ae3-48ae-4bd3-b9bf-ad8389a01a4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2a8fabb5-8dfc-4439-abf9-467fe9ccf1d5', '刀語', '', 'hulu', 'katanagatari', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14874cb1-825d-46b6-9628-28ca114f2c8f.jpg?w=331&h=447&p=t', 'hulu', 2010, 0, 1, 'FINISHED', NULL, 6594, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a68af76a-7446-4191-8b7a-72c725e0eb69', '2a8fabb5-8dfc-4439-abf9-467fe9ccf1d5', 'hulu-katanagatari-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f6a10ea-8b5a-4da0-b6e2-fcc5fd94b439.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebb423b5-0666-48b2-9095-29b1f9744f9c', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 1, '100155859', '絶刀･鉋', '姉と共に不承島で暮らす青年･鑢七花。彼こそは刀を使わぬ一子相伝の剣術、虚刀流の七代目当主である。とはいえ七花にその剣術を活かす機会はない。体の弱い姉を気遣いつつ、平穏な島での日々が続いていくのみだった。そんな彼のもとに、奇策士を自称するとがめという女性が訪ねてくる。彼女は七花に、伝説の刀鍛冶･四季崎記紀が造りし十二本の完成形変体刀の蒐集を依頼する。さらにとがめを追って、完成形変体刀の一本、絶刀･鉋を携えた真庭蝙蝠が不承島に侵入してきた。こうして十二本の刀をめぐる物語が幕を開ける…。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f6a10ea-8b5a-4da0-b6e2-fcc5fd94b439.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35305279-9c42-456f-bfc7-b88871be1e3b', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 2, '100155860', '斬刀･鈍', 'とがめと七花の、変体刀蒐集の旅が始まった。まず蒐集しようとしたのは、居合い抜きの達人･宇練銀閣が所持する、比類のない切れ味を持つという斬刀･鈍。二人は、宇練銀閣が立てこもる下酷城をめざし、鳥取藩全土を飲み込んだ日本唯一の砂漠、因幡砂漠を進む。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9cf2585-1b7a-41ee-89c0-ee441c1a31cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8feb0588-22cd-4731-a49a-3fb74ce7a9c1', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 3, '100155861', '千刀･鎩', 'この度向かう先は、神々の集う地とされる出雲は三途神社。寸分違わぬ千本もの刀、千本で一本の千刀･鎩が目当てである。鎩の持ち主は三途神社の長、敦賀迷彩。迷彩は、完成形変体刀を賭けた勝負に応じる条件として、とがめにある申し出をする。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ea621be-5aef-4eee-8b48-2913210bbe3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b77a80cd-286c-4048-82c2-e6c14b38f217', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 4, '100155862', '薄刀･針', 'かつてとがめから薄刀･針の回収を命じられながらも、その刀の魅力に取り憑かれて裏切った剣士･錆白兵。七花は日本最強と呼ばれるその錆と、巌流島にて勝負をすることとなる。一方そのころ、七花の姉である七実をねらう魔の手が、不承島へと迫っていた。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bdf80d8a-6f92-470b-921b-1bf9a93d35f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60a6e3c2-70d5-4e0d-9dcd-ae7530ef5e98', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 5, '100155863', '賊刀･鎧', '薩摩は濁音港の元締めである鎧海賊団の船長、校倉必。西洋甲冑に似た形の、防御に特化した賊刀･鎧の持ち主だ。闘技場で客寄せの賭け事を行っている彼は、鎧を賭けて勝負を挑もうとする七花に対し、なんと賭け金としてとがめを要求してくるのだった。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/681baaa9-08fd-4dfc-92a0-3399fdbe3377.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('064e066c-b1ae-4b78-82d6-f02553efa16d', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 6, '100155864', '双刀･鎚', '豪雪のため、尾張幕府指定の壱級災害指定地域である蝦夷の踊山。そこに住む凍空一族に伝わるという双刀･鎚を探すとがめと七花だったが、激しい吹雪に危うく遭難しかけてしまう。そこを救ってくれたのは、凍空一族の少女、こなゆきだった。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f93ee21-6b79-4508-821d-bcb732b4d692.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d80915e8-bab6-4522-863a-340c48c6c938', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 7, '100155865', '悪刀･鐚', '悪刀･鐚が祀られていた陸奥の死霊山が何者かに襲われて壊滅し、鐚も奪われていたという。その何者かの行方を追って、とがめと七花は、四国にある剣士たちの聖地･清涼院護剣寺にたどり着く。だがそこでは、意外な人物が二人を待ち構えているのだった。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d56c281-5668-45f6-8786-508c642d70fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55687eda-19be-46e0-bd24-ee416f0315d2', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 8, '100155866', '微刀･釵', 'とがめと敵対する否定姫からもたらされた情報により、次なる刀は不要湖にあることがわかった。否定姫の懐刀である左右田右衛門左衛門によれば、不要湖はあらゆる生命活動が停止している場所だという。そこに居た微刀･釵の持ち主は、思いも寄らぬ“存在”だった。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9263e67d-844e-4d59-889d-a9d6dc0285aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aaf3e4f4-09aa-409b-8e61-d4138eb85a22', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 9, '100155867', '王刀･鋸', '元来、将棋と剣術で栄えてきたものの、天下泰平の世において剣が廃れてしまった出羽の将棋村。そこに唯一残っていた剣術道場、心王一鞘流の当主である汽口慚愧が、王刀･鋸の所有者だった。しかし思わぬ方向に話が転がり、七花は心王一鞘流に弟子入りする運びとなる。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd8fae45-a8f1-4b9a-aa67-5afc405ff641.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1dade61-411a-47b9-830f-4cab35fc0d36', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 10, '100155868', '誠刀･銓', '十本目の変体刀、誠刀･銓。そのありかは、過去を捨てたとがめにとっての因縁の地だった。そして銓の所有者は、仙人と呼ばれる彼我木輪廻。彼我木はとがめに対し、七花の手を借りずにひとりで、地中に埋まった銓を探すように言い渡す。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/864a7892-7d32-4e41-a1b5-5d540379eabf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df3fdc88-a8f1-4600-90ef-cddfe985ad18', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 11, '100155869', '毒刀･鍍', '残る刀も、あと二本を残すのみ。そのうちの毒刀･鍍を手にした真庭鳳凰が、真庭の隠れ里に向かったことをとがめと七花は知る。鳳凰を追って旅路を急ぐ二人だったが、しかしついに鳳凰に追いついたとき、彼の身には大きな変化が起きていた。', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e12bf79-f825-41e7-b246-c102562e1903.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d2307b3-d4bb-4dca-9779-8b1453274765', 'a68af76a-7446-4191-8b7a-72c725e0eb69', 12, '100155870', '炎刀･銃', '【最終話】十二ヶ月かけて集められた変体刀は、尾張幕府に献上されていた。時の将軍、家鳴匡綱との謁見は、変体刀蒐集を成し遂げた褒美として与えられる、とがめの悲願だったのだが……。尾張城を舞台に、最後の戦いの火花が散る!', '2023/09/24 00:00:00', 2785, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/34b2d3ef-7b7f-4c41-b2e4-bce5e9c5c9c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('33545462-7d6c-49bd-8618-ae02af74f2bb', '東のエデン', '', 'hulu', 'eden-of-the-east', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/596eecdb-f1ba-4829-9094-273ddfdcc696.jpg?w=331&h=447&p=t', 'hulu', 2009, 1, 1, 'FINISHED', NULL, 5630, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('528e9113-fd59-42a5-bc5a-b2d20f613bf4', '33545462-7d6c-49bd-8618-ae02af74f2bb', 'hulu-eden-of-the-east-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c173251-8698-4fab-a518-918c2ee03708.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb48850a-827b-4ce0-9d04-a26a9b3ba391', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 1, '100143268', '王子様を拾ったよ', 'ホワイトハウスへ卒業旅行に来た大学生の咲は、記憶を失った全裸の男･滝沢に危機を救われる。助けてもらったお礼に、滝沢に渡した咲の上着――。中には、パスポートが入っていた! 咲は滝沢を追ってワシントンの街を駆け回る。果たして無事に帰国できるのか?', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c173251-8698-4fab-a518-918c2ee03708.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b445376d-e324-4af6-ba47-3d9d6c914a40', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 2, '100143269', '憂鬱な月曜日', '全裸男･滝沢と咲は日本に帰国する。ミサイル事件発生で空港は大混雑。そんな中、滝沢は電話一本で空港を出る。彼の携帯には80億円が入金してあり、残高の続く限り願いがかなう魔法の様な携帯電話だった! 同じ携帯を持つ刑事。彼は配信される履歴から滝沢を追う。刑事の携帯残高は7千円に減っていた……。', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26b47366-0b50-449c-a0c8-ef4d29bb770d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b905d4c3-9959-4baa-9455-e25c8d17b40d', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 3, '100143270', 'レイトショーの夜に', '滝沢と咲が辿り着いたパスポートの住所にはシネコンに併設されたショッピングモールがあった。滝沢は施設のオーナーなのか!? 二人だけの夜を施設内のシネコンで明かそうとすると、刑事が侵入してくる。滝沢は咲を守るため、刑事と対峙する。そうとは知らず、咲は一人ぼっちで朝をむかえる。滝沢と刑事の戦いの行方は?', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd85c4a9-aa2c-459f-81f7-f6eef30f22f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6840faad-707b-49fe-9070-a2f520e69d9b', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 4, '100143271', 'リアルな現実 虚構の現実', '咲の両親は他界。姉夫婦と同居していた。実家に戻った咲は、就職を前に現実と直面する。一方滝沢は、携帯履歴を追って医者のセレソンに会いに行く。面会を渋った挙句、医者は「飲めば携帯入手経緯を思い出せる」という薬を差し出す。薬を飲むと滝沢の携帯が鳴った――。「ごきげんよう、Mr.OUTSIDEだ」。', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2fdd7a5-07d5-4c8c-8209-a62c7e99c3f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a25b2ae3-daed-43c6-a4d0-7fe2d8ecb6e8', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 5, '100143272', '今そんなこと考えてる場合じゃないのに', 'ノブレス携帯をどう使うべきか考えあぐねた滝沢は、使い途を咲に聞きに行く。一方、面談を控えた咲に、義理の兄は「本当にやりたいことが見つかるまで面倒を見てやる」と優しい言葉をかける。しかし咲にとって義兄の優しさはただ辛いだけだった。「これ以上迷惑はかけられない」咲は内定者面談に臨む。', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20529039-eea6-4d40-8ddc-00757dd5d765.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25d56dc6-a19b-4a44-ba53-34394d7cb75a', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 6, '100143273', '東のエデン', '画期的な携帯サイトを発明しながら起業を断念した大学サークル「東のエデン」。ワシントンでの経緯を聞き、滝沢に興味を持ったメンバーは滝沢のシネコンに向かう。しかしサークルの参謀･平澤は滝沢への不審を拭えず……。', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb43daad-f275-447e-8ce3-44411eba8772.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b676f009-7ce9-4864-b7e4-4623fe96f882', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 7, '100143274', 'ブラックスワン舞う', '失踪した大杉。滝沢はノブレス携帯で大杉の居場所を突き止めるが、No.11のセレソンによって交通事故に巻き込まれてしまう。大杉捜索中に入った妨害。大杉はNo.11に捕まったらしい。しかもNo.11は、男性器を切り取る女連続殺人鬼だった! ノブレス携帯は犯罪者にも配られていたのだ。', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40374cf7-6c0e-47c1-981d-4c98c9d48e5e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('850d1552-c7de-4982-ab3b-64f0b36bdd2a', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 8, '100143275', 'あらかじめ失われた道程をさがして', '滝沢は消去した携帯履歴と記憶を取り戻すべく、ノブレス携帯の解析を決意。通称「パンツ」こと板津豊というすご腕ハッカーのいる京都へ向かう。だが、かつて“神童”と恐れられたこの男、今は四畳半に引きこもって誰とも会わないという。滝沢は記憶の謎を解くため、板津を説得する。', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b51ccb5f-48b8-4fef-81ac-6e95d29b5150.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d67c2f4d-f030-4f8d-96cb-c01f577f2b13', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 9, '100143276', 'ハカナ過ギタ男', '滝沢の携帯を解析する板津。いよいよ滝沢の過去が明らかにされる。活動履歴によれば、セレソンNo.10は、この国に壊滅的な打撃を与える依頼を受理されていた。そんな中、板津のアパートの前には、セレソンNo.10と、No.01の姿があった……。', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bbee2ea5-073d-45a5-a01c-d663112f4b9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a65d1019-9e97-48be-bb9e-7a9ec4f9570c', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 10, '100143277', '誰が滝沢朗を殺したか', '滝沢への不安がつのり、電話をかける咲。滝沢は、記憶の謎とMr.OUTSIDEの秘密を知るセレソンNo.01／物部との会話を聞いて欲しいという。「もしそれで俺が犯罪者だったら、俺のことは忘れて……」。滝沢と物部は、滝沢の記憶の手がかりである播磨学園都市に向かう。物部が明かす真実。咲は電話越しの会話に耳を傾ける。', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a9df103-3fb0-4cb9-a081-36f3e308d5d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6675392e-63c9-4768-9090-5e127e7c4e89', '528e9113-fd59-42a5-bc5a-b2d20f613bf4', 11, '100143278', 'さらにつづく東', '【最終話】豊洲のショッピングモールに帰還する、失踪中のニートたち。日本全国に降り注ぐ60発のミサイル。ミサイルのひとつは、豊洲にも落ちるという。はたして滝沢は、ミサイルを止めることができるのか? この日本は、ミサイル攻撃から救うだけの楽園 (エデン) たりえるのか?', '2023/06/23 00:00:00', 1351, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/889ca30a-3520-4176-aabe-195b1ba1be5f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1d33f269-defd-454b-9092-69fc08f9b851', '東京24区', '', 'hulu', 'tokyo-24th-ward', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0886fb1c-e7e6-4fce-9048-26c209fe09ad.jpg?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 140643, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2a2a7b86-543d-46b2-af3f-1e3946d888a5', '1d33f269-defd-454b-9092-69fc08f9b851', 'hulu-tokyo-24th-ward-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79b0f583-86d1-4985-ba5d-2baf5128738b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ed25608-423b-40dc-b591-4e333bfc4c3b', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 1, '100100211', 'RGB', 'ヒーローに憧れた青年、蒼生シュウタはとある事件で幼馴染である翠堂アスミを助けることが出来ず、ヒーローになることを諦めてしまった。その事件から1年が経った追悼ミサの場で、シュウタは幼馴染の朱城ランと翠堂コウキに偶然再会する。「RGB」と呼ばれていた3人は事件をきっかけに少しずつ疎遠になっていた。そんな3人の携帯が突如一斉に鳴り響く。画面を見ると、死んだはずのアスミからの着信だった。', '2025/12/26 00:00:00', 2881, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79b0f583-86d1-4985-ba5d-2baf5128738b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e519dc66-abd6-4d91-9f5f-6dfd675fa36d', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 2, '100101297', 'セピア･グラフィティ', 'タカラ商店街でお好み焼き店を切り盛りしている櫻木まり。その商店街はタカラモールという新しいショッピングモールが出来て以来、経営が厳しくなっていた。そうしたなか実施される「24区グルメフェスティバル」。グランプリ賞品が大型コンビニとの全面コラボということで、商店街の面々は、まり考案のスペシャルメニュー「まりスペ」の新作に期待を寄せる。まりはそのプレッシャーを感じ、新作をRGBの3人に相談をしようとするものの、忙しそうにする3人に相談できずにいた。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/720c1d67-61f7-4fc4-8b85-1fef9f673783.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('656c7341-0505-4725-a4c6-3f445923b878', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 3, '100101938', '朝には紅顔ありて', 'ついに「24区グルメフェスティバル」当日。まりとRGBの3人はグランプリに向けて気合を入れていたが、使用するはずだったお好み焼き用のキャベツが“半グレ組織”の一人、破鮫に買い占められてしまっていた。一時は途方に暮れていた面々だったが、恩師カバの計らいにより、商店街の知り合いからキャベツを譲ってもらえることに。果たしてまりは妨害に打ち勝ってグランプリを取ることができるのか。そしてそんな最中、RGBのもとには再度アスミからの着信が……!', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/839b0dfe-8873-4438-b86d-3705c5325015.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('239aecb2-ae4a-4f66-9d52-9b03651f3bf8', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 4, '100102613', '鈍色の街', '「グルメフェスティバル」を襲った竜巻による事故。そこでRGBに課せられた未来の選択により、カバをはじめ多くの人が犠牲となってしまった。そして24区のネットワークにハッキングし、謎の言葉を残した「カルネアデス」。3人はまだその正体が分からずにいた。そうした中、旧市街シャンティタウンで、強力な依存性のある謎のドラッグ「D」が流行し、犯罪率が急上昇していた。カバの娘、梢を危険な夜の街で見かけたと聞いたシュウタは、彼女の後を追いかける。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/832f454e-571f-4e71-9d6f-2668623ccdb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a58054b-0ef6-4925-b53f-c5478f35386e', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 5, '100103516', 'レッドライン', '豪華クルーズ船に爆弾が仕掛けられた。新たなトロッコ問題で天秤にかけられたのは、船に乗っている要人たちとテロの犯人の命だった。コウキはテロ行為の被害者を守るため犯人を射殺すべきと主張するが、ランはヴィジョンの中で見た犯人がDoRedのメンバー、クナイであることに気付く。二人には真実を隠したまま、ランはクナイがテロを起こそうとしている動機を探ることに。果たして今回のトロッコ問題はどんな結末を迎えるのか――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fbb7e48-204c-400a-88f6-8da3c82c34f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('492e4ebe-324b-4bc7-a472-219c1bfe4661', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 6, '100104013', '翠花の下に', 'テロを阻止するため、クナイを射殺させたコウキ。一方、クナイが所属していたDoRedに疑惑が向いたことで、リーダーのランはガイケイから追われる立場となってしまった。テロを防いだコウキは、父豪理にヴィジョンの体験を語るが、未だ信頼を得ることはできず、信じてもらえない。そんな中、テレビでクナイが事前投稿してあった、ドラッグDやシャンティタウンの再開発に関する真実が流された。それを見た豪理はコウキをある場所へ案内するのであった。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77a6d6a9-ccdb-47f3-965d-8947789fba35.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f83a8f5-efde-4fb6-a737-431a5622d3d0', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 7, '100105071', '黄金サンライズ', 'KANAEシステムが稼働して2ヶ月。それにより、犯罪検挙率は確実に上がっていた。ランはクナイが起こしたテロ事件の重要参考人として指名手配され、コウキは新たにガイケイのKANAEシステムを運用する部署へ転属となった。一方、コウキ･ランと仲違いしたままのシュウタは、パリへ修行に行ってしまった父･留衣の代わりに蒼生ベーカリーの手伝いをしていた。看板メニューである「黄金サンライズ」をうまく作れず悩んでいる彼の元に、梢からのメールが届く。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/771b98c7-b74a-4756-aae1-3b12db124f80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbf9aab1-169a-472d-bd80-0165cc7afefa', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 8, '100105738', '黒い霧', '「グラフィティ戦争」を仕掛けていたのはカルネアデスではなく、ランの師匠であるゼロスだった。彼からカルネアデスの居場所を聞いたシュウタは、急いでコルヌコピアの最上部へと向かおうとするが、そこにアスミからの着信が届く。届いたヴィジョンは、落雷により制御不能となったコルヌコピアのクレーンが落下し多くの人が犠牲になるか、それともクレーンのシステムを直す代わりにその修理者が犠牲になるか、という、ふたつの未来だった。さらにシステムを修理しているのはトロッコ問題を出しているはずのカルネアデスで……。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c290fa63-a247-445e-9515-fbec6a5088ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dec1d440-dc9e-4cb4-9560-de504fa43e07', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 9, '100106410', 'シルバーソルト', 'KANAEシステムは、かつてコウキとアスミの母･香苗が設計したAIがベースとなっていた。過去、そのAIを搭載した車がゼロスと黒葛川を巻き込んで事故を起こしてしまう。そして、AIの判断でゼロスが被害に遭い、その後遺症で失読症となってしまった。問題を解決するために頭を悩ませる香苗であったが、システムには原理的に解決できない問題があるかもしれないと諭される。加えて、ゼロスがグラフィティに目覚めたことを聞き、開発を諦めることに。時は流れ、順調に発展してゆくかに見えた24区だが、香苗の死をきっかけに大きく運命が動き出す。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1184eccc-2a3e-41c8-a68c-e7d5aba426f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d5b24a2-c6a9-4779-9391-7ce6d8b0404e', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 10, '100107648', '仮面の告白', 'カルネアデスの正体であった黒葛川は、シュウタのおかげで九死に一生を得たが、意識不明のまま入院していた。DoRedとガイケイの緊張関係が高まっていく中、ランは黒葛川がコルヌコピアで何をしていたのかを探っていたが、師匠のゼロスに呼び出され、彼が描こうとしている新たな計画を聞かされる。一方でシュウタはシャンティタウンの混乱の中で、自分がどうすれば良いのか思い悩んでいた。そんな中、目の前にガイケイから追われている梢が現れ、その後を追うことに。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09b98d9f-085c-4f80-81b9-ed8cce4c6c4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eef63542-9b97-444f-b728-e8c681c40cee', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 11, '100108325', 'アディティブ･カラー･ミクスチャー', 'KANAEシステムで多くのエラーが出始めた。それはKANAEシステムの中でアスミの意識が覚醒してしまい、判断を迷っていたことが原因だった。黒葛川より提示されたアスミを救うトロッコ問題に直面し、混乱しているシュウタ。そこにちくわが訪れ、テロの容疑で逮捕されてしまう。一方、ランとコウキはアスミを救うカギとなる「CMD」を探していた。そんな中、アスミを死なせてしまった宝小学校火災事件について、シュウタが圧し殺していたある事実が明らかになる。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0dbed217-16c6-4249-9bd5-44c998fd76c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5f4df57-7d6c-4a44-bc96-e223b938ce95', '2a2a7b86-543d-46b2-af3f-1e3946d888a5', 12, '100109177', '青春24区', '【第1シリーズ 最終話】アスミに会いに行く、そう決めたRGBの下に、アスミから着信が。アスミは改めて自身を取り巻くトロッコ問題を提示する。システム内部にあるアスミの存在を明らかにし、KANAEシステムを解体させるか、アスミの中にあるバグを修正してKANAEシステムによる統制を受けるか、どちらを選んでもアスミを消すことになる選択だった。3人はそれを認めず、意地でもアスミに会いに行く決意を固めるのであった。果たしてRGBの3人はどんな未来を選ぶのか――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48a53125-bca0-4533-a1d0-e15e31129789.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('367b0f58-7498-4ec4-b28f-480ffc2a9b52', '東京マグニチュード8.0', '', 'hulu', 'tokyo-magnitude-80', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fef64275-77ba-4e8b-8b42-d8c8a00f692c.jpg?w=331&h=447&p=t', 'hulu', 2009, 2, 1, 'FINISHED', NULL, 6211, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cf214bf6-84ad-4399-b19c-380e5e710ecd', '367b0f58-7498-4ec4-b28f-480ffc2a9b52', 'hulu-tokyo-magnitude-80-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f91123db-124a-4b2a-a86d-7f9e11ccfb67.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ddf8e287-50e8-4f23-9bb6-6e9e0fd7b456', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 1, '100143313', 'お台場、沈む', '未来は中学1年生。なんとなく今の生活に満ち足りなさを感じている、どこにでもいる女の子。夏休みだというのに特に予定もなく、親には弟の面倒を押しつけられる始末。だが二人で出かけたお台場で、姉弟はマグニチュード8.0の巨大地震に見舞われた!!', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f91123db-124a-4b2a-a86d-7f9e11ccfb67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a398625-71e3-4186-847b-c28d588af29d', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 2, '100143314', '壊れる、世界', '被災後、離ればなれになってしまった悠貴を探して、未来は半壊した建物へ飛び込んでいく。逃げ惑う人々で入り乱れる中、真理の手助けを借りながら探索をすすめるが、余震、火事、液状化と、立て続けに発生していく二次災害がそれを阻む。はたして二人は再会できるのか!?', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70955745-5ad9-4ff4-8e0d-a2695c94c5fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a861751-18b0-405f-b6e1-15b564f14910', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 3, '100143315', '燃える、橋', '途中知り合った真理とともに、自宅に向けて帰宅することとなった未来と悠貴。一晩あけて被害状況が明らかになっていく中、水上バスでお台場を脱出するべく、海上保安庁の誘導で桟橋へと移動する。余震によるパニックに巻き込まれながらも、三人はなんとか船に乗り込むことができたが…', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c8fd0cf-0dbb-412b-b9f5-fbede480de77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc8ab1dc-0d75-424f-94bc-33e860e83af7', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 4, '100143316', '三人の、約束', '広域避難所となっている芝公園で、自治体や自衛隊、企業の支援を受ける三人。水や乾パンなどの支援物資をもらい一息つくのもつかの間、未来の不満は悠貴への八つ当たりとなり、大げんか。しかし、余震とともに東京タワー下に現れた活断層が、そのすべてを消し去っていく!!', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caf43c64-6695-43af-8a02-1740fdd8f59a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b8f128e-0fc6-436b-8397-ff0416583c3e', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 5, '100143317', '慟哭の、学び舎', '未来の通っていた中学校に立ち寄ると、そこは帰宅困難者であふれかえっていた。冷たくなった遺体も多数運び込まれ、見慣れた学校の変貌ぶりに心を痛める。未来はそこで、ボランティアとして活動している老夫婦に優しくされ、真理を含めた大人達の見方を改め、自分にもできることを模索するのだった。', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7730de41-5655-43ce-9e78-c942231e3436.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61b9dac4-72e4-4189-8c83-625a43381ee4', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 6, '100143318', '見捨てる、選択', '麻布十番を経由して世田谷を目指す一行。だが移動中、三軒茶屋焼失のニュースを耳にする。真理はより多くの情報を求めようとするが、都合良く手に入れる術も無いまま、体調を崩してしまう。そこで未来と悠貴は、真理が一刻も早く自宅に帰れるよう、一つのアイディアを実行に移す。', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9c1357e-3375-47e6-b7ce-575fdbd4def1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7de8ebc9-1e69-4490-a2cb-a116fa594af0', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 7, '100143319', '夏の夕暮れ', 'ハイパーレスキュー隊が用いる救助ロボを追い求める少年、健斗と知り合う未来と悠貴。最初はロボットオタクとバカにしていたが、将来のことを真剣に考えている彼の言動に、徐々に惹かれていく。そんな中、追いかけていた救助ロボと共に瓦礫の中に閉じ込められてしまう!', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/146a9999-77af-46e2-afe2-dba36d62f0cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5daf5e58-f8c8-435a-b434-e07c03529537', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 8, '100143320', 'まっしろな朝', '突如、意識を失い倒れる悠貴。トリアージされ病院へと運ばれるが、症状は芳しくない。すぐに手術をすることとなり、気が気でないまま、未来と真理はひたすら待つことに。だが、目覚めた未来の目の前には、元気な姿の悠貴が現れる。再び自宅をめざし、旅を始める三人だが…', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9085f4bc-46cf-4866-a335-2b6ec3c1c866.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fa308e8-46c0-411c-9b99-c87a18b5015f', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 9, '100143321', '今日、さよなら', 'たどり着いた三軒茶屋。しかし、火災による損害は真理の想像を遙かに超えていた。必死になって娘と母親を探し求めるが、様々な憶測や風評に惑わされ、居場所もわからなければ、生死も不明であった。そんなとき、未来と悠貴の機転が功を奏し、真理は二人と再会する。', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e4e8bae-fd94-41d0-a6f9-fdec610234d4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ca3b6cd-32f3-412c-9340-e8d4f56fecd0', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 10, '100143322', 'おねえちゃん、あのね', '真理と別れた二人。自宅までもう一息というところで、悠貴の小学校へ立ち寄ることに。そこで未来は悠貴の足跡を見るが、それらを見るたびに、なぜか涙があふれ出てくる。悠貴はここに居るはずなのに、なぜ? 疑念を払拭できぬまま、未来は悠貴と共に自宅へと向かう。', '2023/06/03 00:00:00', 1370, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/988557c6-dd5a-4629-a32c-7a132c496b8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6bc60b2-d4df-435a-bb3d-ee8217d0d4e5', 'cf214bf6-84ad-4399-b19c-380e5e710ecd', 11, '100143323', '悠貴へ…', '【最終話】ようやく到着した自宅。久しぶりの家族との再会。地震で多くを失った未来は心に空白を抱えたまま、時は過ぎていく。両親に挨拶に来た真理から、以前投げ捨てた携帯電話を手渡される未来。一ヶ月ぶりに電源をいれた携帯電話には、たくさんのメッセージが残されていた。', '2023/06/03 00:00:00', 1355, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d87e2900-5508-4f7f-a99b-2cea6adfde73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6e405c6c-b2a7-4ed1-8828-52c275f51ebc', '東京ミュウミュウ にゅ～♡', '', 'hulu', 'tokyo-mew-mew-new', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/614fd841-2ff9-48a9-8855-99800f869700.png?w=331&h=447&p=t', 'hulu', 2022, 2, 1, 'FINISHED', NULL, 117196, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('657e25dc-f157-4970-b58a-800729e6c6f6', '6e405c6c-b2a7-4ed1-8828-52c275f51ebc', 'hulu-tokyo-mew-mew-new-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b895d1e4-01aa-4cd7-9095-e7bc2d2404ce.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68f3b529-56da-4afc-9782-57fa70c378a7', '657e25dc-f157-4970-b58a-800729e6c6f6', 22, '100147829', 'バラバラの心 涙の夜', 'いちごが目の前で傷つけられたショックで、エイリアンの救世主･ディープブルーとして覚醒した蒼の騎士＝青山くん。その様子を目の当たりにしたいちごは、あまりの衝撃に目の前が真っ暗に……。みんとたち4人は地球の未来を守るためエイリアンと戦うことを決断するが、青山くんを守りたいという強い想いに駆られたいちごはその力を仲間に向けてしまい――? 今、ミュウミュウの絆が試される!', '2023/06/13 00:00:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b895d1e4-01aa-4cd7-9095-e7bc2d2404ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44d99774-54f5-4c1a-b9ae-4c31e5cd7023', '657e25dc-f157-4970-b58a-800729e6c6f6', 23, '100148437', '想いよとどけ! 最後の戦い!!', 'ついにミュウミュウとエイリアンの最終決戦が幕を開ける! パイとタルトとの戦いをみんと、れたす、歩鈴、ざくろに託し、一人ディープブルーのもとへ急ぐいちご。それはミュウアクアを見つけ出し地球の未来を守るため、そして青山くんともう一度話をするため――。しかしディープブルーは、そんないちごを冷たく突き放つ。だがそのとき、二人の間にキッシュが乱入! 彼もまた“大切なもの”を守ろうとしていた…。', '2023/06/20 00:00:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2618963f-3826-4029-bedf-c001f4d971d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6329a9c-4eed-460b-a035-73b62725ab0d', '657e25dc-f157-4970-b58a-800729e6c6f6', 24, '100149128', '私たちがつくる未来', '【最終話】最後のミュウアクアは、なんと青山くんの身体の中にあった! ミュウアクアの力で母星から住人を地球へ呼び、人類を滅ぼそうと企むディープブルーに、人類とエイリアンが共に生きる未来を考えようと必死に訴えかけるいちご。すると、ディープブルーの中にある青山くんの心に変化が生じて……? ミュウミュウとエイリアンの長く激しい戦いはいよいよ決着へ! はたして地球の未来の行方は――⁉', '2023/06/27 00:00:00', 1432, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1fe9aa5-39dc-4004-9816-fb383bbfe994.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5c365060-eab2-4e39-a716-bfc13b4afa68', '東京リベンジャーズ', '', 'hulu', 'tokyo-revengers', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64073776-2286-4808-8565-ea222f9929cc.png?w=331&h=447&p=t', 'hulu', 2021, 1, 1, 'FINISHED', NULL, 120120, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6bc6f081-7b5a-40ef-925c-ecf7d6c2817e', '東京喰種 トーキョーグール', '', 'hulu', 'tokyo-ghoul', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50016886_series_art__338x600_tokyo_ghoul_aa6516cf784bd72b938839aa67a45a64.jpg?w=331&h=447&p=t', 'hulu', 2014, 2, 1, 'FINISHED', NULL, 20605, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('7f60211e-542f-4f4a-9ae2-14e33659d6a2', '6bc6f081-7b5a-40ef-925c-ecf7d6c2817e', 'hulu-tokyo-ghoul-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1a6df92e-62dd-467e-b353-a2c884f6cc7a.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbd97e48-76ff-4f3c-a9ba-c85a7b458fc3', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 1, '60804808', '悲劇', '東京。ここでは、人に紛れ人を喰らう「喰種 (グール)」と呼ばれる怪人がはびこっていた。読書好きの大学生･金木研 (カネキ ケン) は、行きつけの喫茶店「あんていく」で自分の好きな作家･高槻泉 (タカツキ セン) の小説を愛読する神代利世 (カミシロ リゼ) と出会い、本屋デートをすることになる。自らの運命を変える事故に巻き込まれてしまうとも知らずに…。瀕死の重傷を負うカネキだったが、手術により何とか一命を取り留めるが…。「何を食べても不味いんです」目覚めたカネキにある異変が起こりはじめ…!?', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1a6df92e-62dd-467e-b353-a2c884f6cc7a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b841dde-cf3f-40a7-a655-e5914fba716b', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 2, '60804819', '孵化', '死体の香りにつられ、喰種であるニシキと鉢合わせたカネキを救ったのは「あんていく」の店員･霧嶋董香 (キリシマ トーカ) と店長の芳村だった。喰種としての飢えに悩まされるカネキに、芳村は「ある包み」を渡す。翌日、友人･ヒデのメールを見て大学に戻ったカネキは、ヒデから先輩の「西尾」を紹介される。それは、前日鉢合わせた喰種･ニシキだった。ごく普通の人間のようにふるまっていたが、帰り道に突然ヒデに襲いかかり、気絶させてしまう。「お前の喰いモン汚しちまったよ」カネキの前で再び喰種としての本性を現すが…!?', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e75702e5-1cf2-4fce-82f4-159b31ebf589.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37222576-2f3f-45ce-a1b5-0aebe7b6dc4c', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 3, '60804820', '白鳩', '「あんていく」に、喰種の笛口リョーコ (フエグチ リョーコ) とその娘･雛実 (ヒナミ) が匿われることになった。ヒナミの寂しげな表情が気になるカネキ。そんな中、カネキは芳村の右腕である四方蓮示 (ヨモ レンジ) と共に、人を狩れない喰種たちのための食料調達に行くことになる。一方、東京の喰種殲滅を目指すCCG本局ではリゼの一件から、「あんていく」のある20区が捜査対象に挙がっていた。上等捜査官の真戸呉緒 (マド クレオ) と一等捜査官の亜門鋼太朗 (アモン コウタロウ) が20区に向かうことになり…。', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8da99458-97ac-435c-bf1e-8ca2a73038eb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d709a7da-8995-4576-8b8d-a9c125e46d45', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 4, '60804813', '晩餐', '「美食家 (グルメ)」と呼ばれる喰種･月山習 (ツキヤマ シュウ) が「あんていく」を訪れた。月山を20区の厄介者だと言い露骨に嫌な顔をするトーカは、カネキに「あいつとは関わらない方がいい」と釘を刺す。だが、月山はカネキの特殊な「におい」に目をつけ、接触を図ってきた。自らの悲劇の始まりでもあるリゼの事が気になるカネキは「リゼ行き付けの店」という月山の言葉につられ、「喰種レストラン」へ足を運ぶ。', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fc8ca4ed-2a15-4ed7-85f0-a4fd21fa7cd9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47d4e7cf-e8df-4acb-942a-a85fb279ef2a', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 5, '60804825', '残痕', '体調を崩したトーカの見舞いに訪れたカネキは、トーカが人間の友人･依子 (ヨリコ) を大事に思っている事に気が付く。その帰り、カネキは喰種に襲われているニシキを助ける。ニシキを自宅に送ったカネキは、そこでニシキの恋人だという西野貴未 (ニシノ キミ) と出会った。貴未は、ニシキが喰種であると知りながら共に生活していたのだ。だが、貴未はカネキの後をつけていた月山にさらわれてしまった。ニシキと共に貴未を取り戻しに行くカネキだったが…。', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/566f7755-2df2-47d8-99af-bcb4f1ba94bb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3616971-1572-4462-a3fe-08bb182aeb65', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 6, '60804830', '驟雨', 'ヒナミは「あんていく」でカネキに漢字を教えてもらっていた。新しい字を次々と覚えて喜ぶヒナミは、もっとたくさんの字を覚えて父親をびっくりさせたいと、リョーコと共に本を買いに出かけていく。だがその頃、CCG捜査官の草場と中島が、母娘の喰種に絞って付近で捜査にあたっていた。いち早く異変に気が付いたヒナミは、リョーコの手を引いて逃れようとするが…。', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c08cc71f-a565-4940-aaec-65eba66f1f5f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9dd3726c-7279-4c0c-801d-7b56f2032a88', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 7, '60804817', '幽囚', 'ヒナミの母･リョーコがCCG捜査官･真戸の手によって命を落とした。何もできなかったことを後悔するカネキ。一方、その知らせを受けたトーカは仇を取ろうと芳村に訴えるが、「皆の安全の為」と聞き入れてもらえない。更には、CCGに顔を見られてしまったヒナミを“24区”に移す案を告げられてしまう。納得いかないトーカは、リョーコ、そしてヒナミを思い、ある決断をする。', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2d3094a8-c983-4b7c-a8d7-3ab25ff33d00.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0dea7c90-dcc6-4476-b227-04b7dec2b146', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 8, '60804812', '円環', 'ヒナミが「あんていく」から抜け出した。だがそれは、真戸の巧妙な罠だった。ヒナミを見つけたトーカの前に、真戸が姿を現す。その頃、同じようにヒナミを探していたカネキは、もう一人の捜査官･亜門と対峙していた。戦いの中、亜門はカネキに「喰種に家族を奪われ、残された者の悲しみを考えた事があるか?」と問いかけ、喰種がこの世界を歪ませている、と言い切る。', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f3b70c2b-bfd3-4ca2-9bb0-873e8e7e9c3d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac0fefab-ee70-49f6-a83d-33e21d62e7bf', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 9, '60804818', '鳥籠', '「あんていく」の面々は、ようやく以前と変わらないかのような日常を取り戻し始めていた。そんな中、カネキはひとり、自分の運命を変えたリゼのことを知るため、14区にあるバー「ヘルタースケルター」を訪れる。そこで喰種のイトリから、リゼがかつて11区にいたという情報を聞き出し…。一方、11区では謎の喰種たちによる不穏な動きが見られ…?', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/03c52806-9ba7-43fb-9571-4d90dab096ae.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('adcf7a35-9a84-4476-afae-878d6dd1e013', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 10, '60804822', '青桐', 'CCG11区支部が、「アオギリの樹」を自称する喰種の集団に襲撃された。生き残った者はゼロ。それを受け、CCGは過去最大規模の対組織戦の準備を始める。一方、「あんていく」には万丈数壱 (バンジョウ カズイチ) と名乗る男が殴りこんできていた。リゼに心酔している万丈は、「アオギリの樹」がリゼを狙っていると知り、リゼに逃げるよう伝えにやって来たのだ。だがそこへ、「アオギリの樹」幹部の少年、「絢都 (アヤト)」が突如乱入する。その姿を見て、驚くトーカ!', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/93843a8d-f160-46d1-afa1-06d93b3f4571.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5ee6889-ebbd-4a9d-b182-ff016d1cee11', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 11, '60804829', '衝天', '「アオギリの樹」に連れ去られたカネキを救出しようと、芳村、四方、トーカ、ニシキ、ヒナミ、ウタが集まった。更に驚くべき人物もそこに加わり…。CCGの亜門ら捜査官たちもまた、千人を超える体制で11区にあるアオギリの拠点に突入しようとしていた。「アオギリの樹」とCCG、そして「あんていく」の三つ巴の戦いが始まる…。', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/45fcaded-bfe6-4534-bb10-389f941184de.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99c6217e-e096-49b7-8c1f-ac225dc7fe96', '7f60211e-542f-4f4a-9ae2-14e33659d6a2', 12, '60804827', '喰種', '【シーズン1 最終話】戦闘が次第に激しさを増していく、「アオギリの樹」本拠地。喰種VS人間、その戦いの行方は…。「あんていく」の面々はカネキを救い出せるのか!? 一方その頃、アオギリの幹部･ヤモリに一人連れて行かれたカネキは、想像を絶する苦しみを受けることに。意識が朦朧となった彼の精神世界に、突如現れた人物とは…?', '2020/08/20 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e65e4b4c-4340-480f-9421-4bd6835f72b7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ba1b0263-b1a0-471b-9b9f-74e06cc763a9', '東京喰種-トーキョーグール-:re', '', 'hulu', 'tokyo-ghoul-re', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/889d3e93-3b72-4b49-8638-e5eca0a43c55.jpg?w=331&h=447&p=t', 'hulu', 2018, 1, 1, 'FINISHED', NULL, 100240, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 'ba1b0263-b1a0-471b-9b9f-74e06cc763a9', 'hulu-tokyo-ghoul-re-s1', 'シーズン3', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/027b02e6-4941-4562-b561-7e97aa0c8064.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e7f5b07-76ee-4574-9155-9d58715e3bdd', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 1, '100017202', '狩る者たち START', '“ヒト”と変わらぬ姿をしながら“ヒト”の肉を喰らうことでしか生きながらえることができない存在“喰種 (グール)”―。彼らの脅威から人々を守るために設立された［CCG］(喰種対策局) で、“クインクス”と呼ばれるチームが結成された。彼らは特殊な施術により喰種の能力を持つようになったヒトで構成されており、メンターとしてチームを率いる佐々木琲世 (ささき はいせ) には、なぜか2年前までの記憶がない。そして彼には、［CCG］内ではよく知られた秘密があった。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/027b02e6-4941-4562-b561-7e97aa0c8064.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29728741-0a30-4a75-8e9b-3b587aade1a5', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 2, '100017518', '欠片 member', 'クインクスのメンバー、六月透 (むつき とおる) の捨て身の追跡により、駆けつけた瓜江、不知に追い詰められたトルソー。だがそこに“オロチ”と呼ばれる喰種が現れ形勢は逆転する。遅れて援護に入った琲世が単独でオロチに立ち向かうが、非常に危険度の高い「S～(S以上) レート」に指定されるオロチの強さに苦戦。部下たちを守るため、琲世は全力で戦う決意をするが、それは、あまりに強大すぎるがゆえに、彼自身にも制御が難しい“喰種の力”を解放することとなり、己を見失う危険を孕んだ行為だった。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b79cb586-3391-4886-a84a-1617b2b52d97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e20def1b-fd34-4f7c-a0e9-8825164862ca', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 3, '100018189', '前夜祭 fresh', '［CCG］内での出世に執着する瓜江は、さらなる力を得るため、上官である琲世の許可を偽って自らの赫子の稼動レベルを引き上げる施術を受ける。一方クインクス班は、エース捜査官である鈴屋什造 (すずや じゅうぞう) 率いる鈴屋班と、“ナッツクラッカー”と呼ばれる喰種の合同捜査を行うことに。ナッツクラッカーがSSレート喰種“ビッグマダム”の関与するオークションに出品するため、若い女性を中心にヒト攫いを行っていることを知り…。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffce9d7a-9341-470e-8261-d3cadcb5a163.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a77c211d-01df-4331-a01e-186b0ddb43c2', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 4, '100018314', 'オークション MAIN', 'ナッツクラッカーから首尾よく情報を引き出した六月によって、次回オークションの概要が判明した。［CCG］ではこの機会に大掛かりな喰種掃討作戦を行うことになり、六月と自ら志願した什造が“商品”として会場に潜入することに。当日―会場は、出品者や客、ビッグマダムがボディガードとして雇った“アオギリの樹 (き)”構成員など多数の喰種で賑わっていた。什造と引き離され、外部との連絡も絶たれてしまった六月は、動揺を隠せないままオークションにかけられ……。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8567bcf1-8dc9-4ef6-b09f-dde2eb99b8cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8f68fe2-ad3f-4cf3-a962-210737705221', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 5, '100018596', '散りゆく夜 Press', '什造の奇襲により混乱するオークション会場に、待機していた［CCG］の部隊がなだれ込む。大乱戦の中、六月は何とか逃げ出すことに成功するが、月山家に仕える喰種、カナエ＝フォン･ロゼヴァルトに執拗に追いかけられ窮地に陥っていた。そんな六月のもとに琲世たちクインクス班が駆けつけるが…!? 一方、掃討作戦決行中の［CCG］捜査官たちは、報告されているレート以上の戦力を見せつけるナッツクラッカーや、アオギリの樹の構成員で“オウル”と呼ばれる“半喰種 (はんグール) ”を相手に思いがけず苦戦を強いられることになる。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f25e45b7-4a41-4bfa-a543-9674c9e62beb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df398c15-87d1-4fe4-89d7-e0220aaba264', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 6, '100018773', 'その、果てに turn', '戦線離脱した六月と護衛の瓜江が、抜け道を使って逃走を図る多数の喰種を発見。別ルートでたどり着いた什造とともに戦いに突入する。彼らの前に立ちはだかるのは、什造と浅からぬ縁があるビッグマダム。一方、不知たちとナッツクラッカーの駆逐に当たる琲世だったが、作戦の指揮を執る准特等捜査官･和修政 (わしゅう まつり) の命令で、行く手を阻むオウルに独り立ち向かうことに。オウルは、琲世の上司である真戸暁 (まど あきら) のかつての同僚、滝澤政道 (たきざわ せいどう) が喰種化手術を受けさせられた姿だった。彼は自分と似た境遇の琲世への対抗意識を露にし、激しい攻撃で追い詰める。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f9165a9-4649-4490-b55c-3fab22e8c6fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e33e4434-3e39-4cfe-868b-8857e4ba6058', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 7, '100019101', '心覚え在りし日々 mind', 'オークション会場を狙った喰種掃討作戦は終了した。捜査官と喰種の双方に多数の死傷者が出る中、琲世は“過去の自分”を知る喰種の少女、笛口雛実 (ふえぐち ひなみ) の“所有権”を申し入れる。今回の作戦で働きを認められたクインクス班は、同じく功績を認められた他の捜査官たちとともにメンバー全員の昇進が決まり、琲世は上司の暁や、父親のように慕う特等捜査官、有馬貴将 (ありま きしょう) を招いて、メンバーの昇進を祝うホームパーティーを企画。だが、パーティー当日、琲世の中にいるもうひとりの人格“カネキケン”を知る何者かから、“奇妙な贈り物”が届く。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9573d79c-a80a-4079-9a66-5511a937ad5e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab87a426-7600-48de-ae1d-30d8ef4bc296', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 8, '100019218', '蠢くモノ TAKe', '［CCG］で、大量誘拐犯の喰種集団“ロゼ”の捜査が始まった。だが組織的に訓練され、痕跡をほとんど残さない彼らを追い詰める有効な手立ては見つからない。捜査が遅々として進まない中、琲世は自分宛に届いた“マスク”からヒントを得て、ある策を思いつく。一方、先日のオークションで六月を狙ったカナエは、大きな喪失感から心を病んだ主、月山習 (つきやま しゅう) の姿に心を痛めていた。そんなカナエに、月山の友人ホリチエが、彼を助けるための作戦を持ちかける。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d239aa9d-373d-4710-9321-6325c0cf7dc9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f37be2f0-8ba5-4044-b8a8-567415a0ac53', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 9, '100019716', '亡霊 play', 'ホリチエから琲世の写真を見せられた月山は、“金木研”が生きていたことを知り喜々として会いに行く。だが“カネキ”としての記憶を失った琲世には、月山のことがわからない。そんな中、［CCG］准特等捜査官キジマ式が、ロゼの一件で捕らえた月山家の使用人、ユウマの拷問映像をSNS上に流す。それは月山家はもちろん、［CCG］内部でも反発がおきるほどショッキングなものだった。月山は何とかしてユウマを救い出そうと、捜査官である琲世に協力を頼もうと考えるが…。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2ca7f8a-8763-40ea-b9b9-5ba992615698.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb4c1b03-db8f-4533-9c3b-351a750065a2', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 10, '100020268', 'ゆれる think', 'いまだ全容がつかめないロゼの捜査に、クインクスの特性を生かした琲世考案の“マスク作戦”が導入された。だが捜査を進める中で琲世は、喰種にすら畏れられる“眼帯の喰種”の存在を知り、“彼”の調査を始める。そして[CCG]の資料室で、殉職した捜査官、亜門鋼太朗 (あもん こうたろう) が遺したレポートを見つけ…!? そんな中、キジマが仕掛けた新たな策から、ロゼの捜査が大きく進展する。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/227aed8c-4c8b-4768-b072-c0e3c3454603.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54db0a37-eb20-4a62-a680-b270222d4ea7', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 11, '100020608', '欠落者 writE', '[CCG]に屋敷に踏み込まれ、父･観母 (みるも) や使用人たちが投降する中、側近の松前 (まつまえ) とともに逃げのびた月山は、彼を生かすために命を賭した者たちのことを想い、“当主”となる責任を噛み締める。その月山の前に喰種捜査官として立ちふさがる琲世。一方、“月山家駆逐作戦”で伊東倉元 (いとう くらもと) 率いる伊東班と合流したクインクスは、“ノロ”と呼ばれる喰種と遭遇。脅威の再生力を持つノロを相手に迷いを断ち切った不知が、ナッツクラッカーの赫子から作り出したクインケで応戦するが…!?', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2ca9835-a930-40e3-befc-fef24dc4ae43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6734a2de-b8c6-4644-8c7f-84c43a9997ab', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 12, '100020979', '夜明け Beautiful Dream', 'ノロを相手に次々と仲間が倒されてゆく中、踏みとどまって戦う不知。その姿を目にし、必死で立ち上がる瓜江。ふたりの渾身の攻撃がノロを捉える。一方、月山の窮地に駆けつけ、怒涛の攻撃を仕掛けるカナエだったが、“カネキ”の記憶を取り戻し始めた琲世の反撃に瀕死の重傷を負う。そこに“隻眼の梟 (せきがんのフクロウ)”と呼ばれる半喰種、エトが現れ悪意を振りまく。最後の力を振り絞るカナエだが…。そして、琲世がついに、“カネキ”として完全に覚醒し―。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2ffef0c-0dbc-4ce8-b98b-4d39fc8834d4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eaa81ebf-2ea4-41a7-a2ed-d39addd936d3', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 13, '100025924', 'そして、もう一度 Place', '喰種 (グール) から人々を守るために組織された〔CCG〕(喰種対策局) で喰種捜査官として働く佐々木琲世 (ささき はいせ) は、もとは“ヒト”でありながら、喰種が持つ特殊な内臓器官“赫包 (かくほう)”を移植されたことで“半喰種 (はんグール)”となった青年･金木研 (カネキ ケン) であった。〔CCG〕が、喰種の一大組織“アオギリの樹”の本拠地が“流島 (るしま)”にあることを突き止め、殲滅に乗り出す。激戦が繰り広げられる中、作家の高槻泉 (たかつき せん) こと芳村 (よしむら) エトは、記者会見を開き、自ら“喰種”であることを公表。以前からエトを追っていたカネキは捜査官として彼女を喰種収容施設“コクリア”へと連行するが、そこでエトから、あることを託される。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a62b76a-970e-4a16-9df1-d0cc235c1ff6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94ca545f-6a8d-4501-b701-b2664d357302', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 14, '100026174', '白い闇 VOLT', 'コクリアに収容された喰種の少女、笛口雛実 (フエグチ ヒナミ) の“処分”が決まった。彼女のことを幼い頃から知る金木は、すべてを失う覚悟でヒナミを救い出す。同じ頃、アオギリの樹の構成員、霧嶋絢都 (キリシマ アヤト) と万丈数壱 (バンジョー カズイチ) 率いる一団もまた、ヒナミを助けようとコクリアを急襲。だがそんなアヤトたちの前に「死神」と呼ばれる〔CCG〕最強の捜査官、有馬貴将 (ありま きしょう) が立ちふさがる。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7f694a43-60cb-4d3b-bc02-90c9b9c221be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9e735f3-f9c2-4cba-93dc-cc12aa02abcb', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 15, '100026265', 'クロスゲーム union', '流島の各地で〔CCG〕と“喰種”との死闘が続く中、喰種捜査官･阿原半兵衛 (あばら はんべえ) は、敬愛する班長･鈴屋什造 (すずや じゅうぞう) に恨みを持つ半喰種、安久黒奈 (ヤスヒサ クロナ) と遭遇。高い戦闘力と強靭な肉体を持つクロナに完全に追い詰められていた。そこに現れたのは…? 一方、法寺項介 (ほうじ こうすけ) と真戸暁 (まど あきら) が率いる部隊の前に立ちふさがったのは、アオギリの樹の幹部、タタラだった。法寺との遺恨を晴らすべく、容赦ない攻撃を仕掛けてくるタタラ。そこに突如、“オウル”と呼ばれる元喰種捜査官の半喰種･滝澤政道 (タキザワ セイドウ) が割って入り…!?', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2329c807-5576-4605-a67e-8e67266eff25.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b2db9d1-a9de-44df-8768-f907fe7cf30b', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 16, '100026662', '遺したもの vive', '殉職したはずの同僚･滝澤と、上司だった亜門鋼太朗 (あもん こうたろう) との思いもよらぬ再会を果たしたアキラ。だが今の二人は、“実験体”としてその体に赫包を移植された半喰種だった。驚き混乱するアキラ。そこに瓜江久生 (うりえ くき) 率いる “クインクス班”が到着した。クインクス班とは〔CCG〕が人工的に造り出した半喰種で組織されたチームであり、法寺･真戸班の援護のため、連携して滝澤たち“喰種”を追い詰めてゆく。一方、金木と有馬の戦いは激闘の末、有馬が捜査官人生で初めての敗北を喫する。有馬は金木にあることを託すが、それは金木がエトから託されたことと同じであった―。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a5e6397e-e444-4920-8610-287d2707a993.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7dbcedba-141a-404b-8a40-7dae325708ef', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 17, '100026901', '出会い、とまどい MovE', '流島から逃れた喰種と、有馬の命を受けて金木たちの逃走を手助けした元〔CCG〕の“0番隊”、平子丈 (ひらこ たけ) たちが隠れ家に集まった。互いに敵対する立場だった喰種と0番隊は相容れないものがありながら、それぞれが信じるもののために手を組むことにし、“対･人間”の組織“黒山羊 (ゴート)”を結成。金木が彼らをまとめるリーダー“隻眼の王 (せきがんのおう)”となる。そして、やはり流島から逃れ、金木たちのもとに身を寄せていたアキラと亜門は、迷い悩んだ末に、自分自身の心に従うことにし…。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/949d8609-9b5a-4e72-ad09-6db52d7a219c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d7eb9ed-c81d-4ef5-a941-a051e81a7f6d', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 18, '100027279', '赫赫たる FACE', '最強の捜査官･有馬を失ったばかりか、トップである和修 (わしゅう) 一族を暗殺され混乱する〔CCG〕。そんな中、世間を騒がせていた“ピエロ”と呼ばれる喰種の集団が、各区の〔CCG〕支局を同時に襲撃する。これに対し、総議長･和修常吉 (わしゅう つねよし) の遺言により新たな局長となった和修分家の旧多二福 (ふるた にむら) は、「彼ら喰種が次に狙うのは本局である」と推測。各区の防衛はそのままに、本局を有馬にかわる最強の捜査官、鈴屋什造に守らせる作戦に出る。各区で戦いが繰り広げられる中、クインクス班を率いる瓜江は、因縁のある喰種、ドナート･ポルポラの姿を目にし…!?', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e6159e8-f3d1-4d5f-b645-fdbb9aa5c7a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2f9912b-24bf-429f-8d44-d62c52e81d8a', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 19, '100027584', '紲 proof', 'CCGが新造のクインクス部隊“オッガイ”を新たな戦力として投入することになった。彼らの活躍と、新局長、旧多の手腕により窮地に立たされる喰種たち。少しでも多くの喰種を救おうと、黒山羊のメンバーとともに戦う金木だがすべてを救えるわけもない。そんな中、“喫茶 ：re”で束の間の休息をとる金木は、一緒にいたトーカから突然告白され動揺。そこに金木のCCG時代の部下、六月透 (むつき とおる) が現れた。金木に恋心を抱く六月は、どんな手を使っても金木を連れ戻そうと激しい攻撃を繰り出すが、金木とトーカはそんな六月を振り切って逃げ出し―。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd51aee2-13c2-451e-b559-1c7097ff3890.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e525c7a-fb59-4e6c-b430-3312c8ca0368', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 20, '100027930', 'めざめた子 incarnation', '局長、旧多の下、喰種だけでなく、彼らと接点のある民間人に対しても厳しい罰則を加えるなどの強硬手段に出たCCG。これにクインクス班の米林才子 (よねばやし さいこ) らCCG内にも反発する者が現れるが、旧多は喰種排除の手を緩めようとしない。瓜江とベテラン捜査官の黒磐巌 (くろいわ いわお) は、旧多の暴走を止めるため査問にかけることを決めるが、そんな彼らの前に現れたのは!? そしてついに、多くの喰種が身を隠す黒山羊のアジトが見つかり、CCGに寄る大掛かりな掃討作戦が始まった―!!', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e11c3af2-9f6c-4435-bc13-6ac527346fcd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2e98c9d-10a4-4563-be40-480cc61ee58b', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 21, '100028100', '心覚え Morse', '大切なものを守るため、立ちふさがる什造やオッガイたちと戦う金木だが、思った以上に大きなダメージを受けてしまう。動くこともできず追い詰められた金木はある行動に出るが…!? そして―“東京”に、巨大なバケモノ“竜 (りゅう)”が誕生する! 竜の誕生によって街は破壊され多くの犠牲が出る中、これまで謎の人物“スケアクロウ”として成り行きを見守っていた金木の親友、永近英良 (ながちか ひでよし) が、金木と金木の大切なものを守るため動き出す!', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47600d2f-3f36-470e-9fee-f87fb2e321f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd66a3dd-8b34-4c3a-b538-1378ba4252a9', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 22, '100028508', '悲劇の果て call', '什造たちとの戦いの途中で記憶が途絶えた金木が目覚めたのは、不思議な空間だった―。金木はそこで、自らが数奇な運命を辿るきっかけを作った喰種、神代利世 (カミシロ リゼ) と再会する。リゼは金木を「人殺し」と呼びあざ笑うが、そんなリゼに対し金木は自分自身の決意を話す。一方、“核”となっていた金木を救出したことにより、原形をとどめることができず崩壊してゆく竜。だが、竜から産み出された不気味な“落とし児 (おとしご)”たちが振りまく“毒”により、あちこちで恐るべき現象が起こり始める。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d822c3a-c7b1-4cf8-b5fe-0fc1962a6032.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c15aabf0-9500-4c8f-970d-d7104f2a80ac', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 23, '100028660', '邂逅 ACT', '竜とその落とし児の脅威に対抗するため協力し合う喰種とCCGだが、落とし児たちによる被害は広がり続けていた。これに対処するため、喰種の研究者、西野貴未 (にしの きみ) らが毒性の高い卵管の場所を特定。“落とし児の毒”に耐性のある金木が調査に向かうことになり、護衛にアヤトがつく。そんな中、喰種とCCGが共同戦線を張る作戦本部を和修家側近の武装集団、“V (ヴィー)”が襲撃。黒山羊の月山習 (ツキヤマ シュウ)、西尾錦 (ニシオ ニシキ) らがCCGと協力し応戦するが、Vと手を組む喰種集団ピエロが“秘密兵器”を投入し、さらなる激闘が繰り広げられることになる。一方、アヤトとともに卵管の調査に向かった金木は、ついに首謀者、旧多と対峙する―。', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f88ef1ad-7743-48fc-885f-ec13bd3bb000.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00dd9b19-3b68-4c2f-aeb7-2ecc9bdfb604', '11d1c5ea-6c92-4c1d-afb1-282e3fb90a65', 24, '100029052', '最終回', '共同戦線を張る喰種とCCGが、Vと激しい攻防を繰り広げていた頃、卵管のある地下では金木と旧多の戦いが始まった。和修分家に産まれた者たちの中でも恵まれた才能を持つ旧多は手強く、金木は苦戦を強いられる。傷だらけになりながら、互いの思いをぶつけ合い、熾烈な戦いを続ける金木と旧多。「あのとき リゼに 出逢う事がなければ―」それは、果たして“悲劇”だったのか…? その先にある未来とは?', '2020/09/10 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f17cdb4-6539-4522-91b0-55397ee83f53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a6462d75-3af6-4f51-af48-5ddd1ff58160', '東京喰種 トーキョーグール', '', 'hulu', 'tokyo-ghoul-a', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50027375_series_art__338x600_tokyo_ghoul_a_d104816c6c78959a93c6e72400b7859b.jpg?w=331&h=447&p=t', 'hulu', 2014, 2, 1, 'FINISHED', NULL, 20605, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5edc0ccd-349c-4428-89e2-ed937f52a87a', 'a6462d75-3af6-4f51-af48-5ddd1ff58160', 'hulu-tokyo-ghoul-a-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/74e31d70-6a0b-409b-a3ed-49fab797db18.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a39359d0-e378-48d5-acad-7baef4350e8b', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 1, '60804809', '新洸', '人を喰らう怪人“喰種 (グール)”が潜む東京。好戦的な喰種集団「アオギリの樹」のアジトでは、アオギリと「CCG (喰種対策局)」、そして「あんていく」の面々が激戦を繰り広げていた。CCGの篠原幸紀、黒磐巌らはSSSレートの喰種「梟」と戦い苦戦。また、あんていく側のウタ、四方蓮示、月山習の3人はアオギリの幹部･ノロと対決。一方、自らの弟･絢都と対峙する霧嶋董香は、アヤトの圧倒的な力の前に追い込まれていた。そして、最後の一撃がトーカを襲おうとしたその時…。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/74e31d70-6a0b-409b-a3ed-49fab797db18.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c870513-5d30-4610-8052-a8cc2b9d08e1', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 2, '60804816', '舞花', 'アオギリとの戦いを終え、半喰種の青年･金木研 (カネキ ケン) は「あんていく」から去っていった。トーカは現実を忘れようと受験勉強に打ち込み始める。その頃、アオギリ戦で大きな損害を出したCCGは、「アオギリの樹」を完全に殲滅するため、再び動き出していた。その最中、10年前の対「梟」戦を経験している黒磐は、アオギリ戦での「梟」の違和感に気づく。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/13e4b062-79af-4def-b166-4dc8657edcbc.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('533df867-8a7a-4bb9-927c-fef39659a797', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 3, '60804815', '吊人', 'CCGの護送車が、「アオギリの樹」に襲撃された。「あんていく」のトーカと笛口雛実 (フエグチ ヒナミ) は、その襲撃事件にカネキが関わっている事を知り、それぞれに心を痛めていた。そんな中、ヒナミはカネキも愛読していた作家･高槻泉 (タカツキ セン) のサイン会に、トーカに迷惑をかけまいと一人で出かけていく。一方、トーカは志望校の「上井大学」を見学に訪れ、そこでカネキの親友･永近英良 (ナガチカ ヒデヨシ) と再会する。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5468cbe1-0ad8-4dbc-9993-64b37562f8f1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2edc20bb-40a6-4e90-b5c2-7018bd7b733d', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 4, '60804811', '深層', '「梟」の情報を得るため、CCGの亜門鋼太朗 (アモン コウタロウ) とそのパートナーで、かつての上司･真戸呉緒 (マド クレオ) の娘である真戸暁 (マド アキラ) は、生きたまま捕獲された喰種の収容所･コクリアを訪れていた。23区にあるこの施設には、かつて孤児院で亜門の父親代わりだったSSレートの喰種、ドナート･ポルポラが収容されている。彼から情報を聞き出そうとする亜門たち。しかしその時、コクリアに「アオギリの樹」が急襲してくる。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ae02784f-a0ac-4bb0-b74e-e4ec28013cb8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4dc418b-985d-4d78-864d-24795356a20e', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 5, '60804824', '裂目', '安久 (ヤスヒサ) クロナとナシロ、そして鈴屋什造 (スズヤ ジュウゾウ) は、かつては共にCCGの児童養護施設で暮らしていた。その後、嘉納 (カノウ) 教授の手で半喰種となったクロナとナシロ、CCGの二等捜査官となった什造は、コクリアで敵として対峙する。だが、什造の躊躇のない一方的な攻撃に、クロナとナシロは追い詰められて行き…。一方、自身の父「アラタ」をクインケとして装着した篠原と戦うアヤトもまた、苦戦を強いられていた。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/08d89dab-2ab7-44f0-b9be-a7d29eb022eb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('458355a5-91e0-4e6b-b9b9-6cb7678dd35c', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 6, '60804826', '千路', 'アオギリによるコクリア襲撃から数週間。共喰いを繰り返し「半赫者 (はんかくじゃ)」となっていた「眼帯」ことカネキはCCGによってSSレートの喰種に認定された。更に、捜査官の法寺項介 (ホウジ コウスケ) と篠原は鉄骨落下事件の被害者であるカネキが20区の喫茶店「あんていく」でアルバイトをしていた事を突き止める。一方、アオギリのアジトに戻ったカネキは…。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c5e61d94-23b8-4bcd-8277-89805ad2e0d9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a5009505-409c-4ddb-b7a4-388f6be67007', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 7, '60804814', '透過', '月山が「あんていく」にやってきた。月山は、カネキが共喰いを繰り返し「赫者」になろうとしていると芳村 (ヨシムラ) に報告する。そんなカネキを心配するヒナミは月山に誘われ、とある喫茶店を訪れるが、そこで高槻泉と再会する。カネキの事を相談するヒナミに、高槻は連絡先を渡し立ち去る。一方その頃、「あんていく」の芳村の元にカネキが訪れていた。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3a218b20-5c35-4458-a2fc-e4afd707510a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6bfa31c-f992-4b79-a285-e8c26aa2f2ee', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 8, '60804821', '旧九', 'かつて功善 (クゼン) という名の喰種がいた。人を、喰種を殺し続けた功善は、孤独な日々を過ごしていた。やがてその能力を買われ、ある組織と手を組むようになるが、孤独感は癒えないままだった。そんな時、功善は通っていた古い喫茶店で憂那 (ウキナ) というひとりの人間の女性と出会う。ふたりはやがて愛し合うようになるが…。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/16e11aad-6da0-4044-9a75-a602f0c97d1c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64eb0f73-47f7-452e-8980-1db9a7bbe2d5', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 9, '60804823', '街望', 'CCG･和修常吉 (ワシュウ ツネヨシ) 総議長より「梟討伐作戦」の決行の断が下された。対象の居所は…「あんていく」。大規模な作戦になることから、選ばれたCCGの捜査官たちは遺書を書かされ、それぞれが死と向き合う。そしてついに20区がCCGによって封鎖。「あんていく」は梟討伐部隊に包囲される。その一報を耳にしたカネキ、そしてトーカは…。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d6ecca97-1319-4415-a2bc-dfe090a5d9c7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ed9421ce-f556-4b8f-aa0f-162a9f0ceeb1', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 10, '60804807', '終雨', '「あんていく」とCCGの激しい攻防は続いていた。芳村は篠原･黒磐と、「魔猿 (まえん)」こと古間円児 (コマ エンジ) は田中丸望元 (タナカマル モウガン) 特等捜査官と戦う。一方、鉢川忠 (ハチカワ チュウ) 准特等捜査官たちと戦う入見 (イリミ) カヤは、逃げ遅れた老婆を庇って負傷。民間人を巻き添えにしてでも攻撃をしかけてくる鉢川たちの前に、ついに死を覚悟するが…。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f54606dd-c799-45ea-94a2-5247061b4050.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('90f1cd2e-430d-4b5e-a34f-61af44327bc2', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 11, '60804828', '溢花', '梟の攻撃から什造を庇って、篠原が倒れた。時を同じくして、アオギリがCCGとの戦いに乱入、アオギリ兵たちの猛攻にCCGは次第に形勢不利となっていく。一方、カネキはあんていくへの道を封鎖する亜門と対峙していた。互いに一歩も譲らない戦いの中、ついに決着の時が訪れる…。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e0e3efbb-a7cb-4d49-891d-6c5fdf6e2b9c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('543eaa8d-04f1-46c4-b351-449885509e36', '5edc0ccd-349c-4428-89e2-ed937f52a87a', 12, '60804810', '研', '【シーズン2 最終話】アオギリ兵たちが撤退し、「あんていく」での激しい戦いは終焉を迎えようとしていた。その最中、カネキたちの身を案じて「あんていく」への道をひた走るトーカ。人間と喰種、それぞれの想いが交錯する中、崩壊間近のあんていく店内でカネキが選んだ答えは…。', '2020/08/27 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/55622895-bfd8-4d49-be65-79e269c103cd.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('88048e0c-d40f-4f15-b27e-d6576bc05a29', '東島丹三郎は仮面ライダーになりたい', '', 'hulu', 'tojima-wants-to-be-a-kamen-rider', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e78579aa-c52e-42b8-b3d6-d884e111e5a9.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 187464, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8e6db08d-550c-4559-b152-ef61b523342f', '88048e0c-d40f-4f15-b27e-d6576bc05a29', 'hulu-tojima-wants-to-be-a-kamen-rider-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5577ff8c-a080-472c-bc2f-d9ea2d457307.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee5d1c16-50bc-4207-9bd4-cdbf8a13f031', '8e6db08d-550c-4559-b152-ef61b523342f', 1, '100240372', '東島丹三郎は仮面ライダーになりたい', '仮面ライダーに憧れる東島丹三郎は、仮面ライダーになるためバイトをしては山に籠り体を鍛えるという生活を送っていた。そんな彼も今年で40歳。集めた大好きな仮面ライダーグッズが孤独死した後に取り残され、無造作にゴミ袋に入れられてく様を思うと耐えられず、全て手放してしまう。そんな中、「ショッカー現る」というニュースが彼の目に飛び込み……', '2025/10/07 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5577ff8c-a080-472c-bc2f-d9ea2d457307.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8117655a-ded8-48bc-bfa3-308230ab0bb1', '8e6db08d-550c-4559-b152-ef61b523342f', 2, '100240862', '私はタックル', '電波人間タックルに憧れる岡田ユリコは高校教師をしながら、タックル道を突き進むべく日々鍛錬していた。そんな中、東島が倒したショッカー強盗のニュースを見て、先を越された悔しさで苛立ちを覚えるユリコだったが、偶然、彼女の前にもショッカー強盗が現れ……', '2025/10/14 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d598df3e-5ba6-459e-bb20-9f56bce7677a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58be4bef-a4c2-4a4d-852e-a1ca507c65ae', '8e6db08d-550c-4559-b152-ef61b523342f', 3, '100241349', '嫌いが好きになるとスゴク好き', 'ショッカー強盗の生配信があり、現場に向かう東島とユリコ。そこで待ち受けるのは……本物のショッカー戦闘員だった。夢にまで見た本物との出会いに興奮がおさまらない東島。ユリコと協力 (?) して二人でショッカー戦闘員と戦うが、さらに“まさかの存在”まで現れ……', '2025/10/21 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e27f041-1d7d-4366-aa5c-055c4e5a66a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c641d956-8f24-4a40-9f33-7c2055780aba', '8e6db08d-550c-4559-b152-ef61b523342f', 4, '100242084', '最強の仮面ライダーは誰だ', 'ユカリスは実は女ショッカー戦闘員だった! 驚愕の事実とともに襲いかかってくるユカリスだったが、対峙するユリコも対抗する。そんな中、付き合っていた彼女が宿敵だったことを知りショックを受ける三葉の口から、ショッカーとの因縁が語られ……', '2025/10/28 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f2b0209-59a9-4ba0-875c-8d96d5fe7975.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d693c508-6734-4e90-8487-1166f20a228e', '8e6db08d-550c-4559-b152-ef61b523342f', 5, '100243000', '僕にもブイスリーやらせてよ', 'ユカリスの伝令で集まったショッカー戦闘員が東島達に襲い掛かる! が……東島、ユリコ、一葉は戦闘員達を返り討ちにしてしまう! その後、一葉は三葉とユカリスに結婚するのかしないのか問い詰めるが、その背後には恐ろしい影が……', '2025/11/04 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e39706fc-6bbe-4416-a3b4-c08b8ff5b1e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ff6dcc9-58a1-4505-94a5-460b20647275', '8e6db08d-550c-4559-b152-ef61b523342f', 6, '100244056', 'ツマミを注文しろ', '遂に怪人の姿をあらわにした蜘蛛男が東島達に襲いかかる!「仮面ライダーは逃げない!」圧倒的な力を持つ蜘蛛男を相手にも怖気付くことなく、東島は渾身のライダーパンチを放つ。蜘蛛男は目立つことを避け、撤退するのだった。高揚が収まらぬまま東島達は、島村家の長女･二葉が経営する居酒屋ふたばで祝杯を交わす……', '2025/11/11 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/386e70b4-d369-4e96-8cdf-c8920d41c420.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('147645ab-656d-4fd2-8f53-be8ab5ba240b', '8e6db08d-550c-4559-b152-ef61b523342f', 7, '100245261', '俺をショッカーにしてくれ', '無敵と称される男･雲田と喧嘩することになった中尾だが、敵対する極道の襲撃に巻き込まれてしまう。中尾は命からがら子分達を逃がし、組長の仇討ちのため広間に戻ると……なんと雲田が蜘蛛男に変貌し、その場にいる人間を皆殺しにしていた! 正体を見てしまった中尾も蜘蛛男に体を貫かれてしまう……', '2025/11/18 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82937ed5-d1a5-4c45-9b6f-d87a58d4274a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('611fae68-ebbf-49f0-b0f1-d4cc8c45fa68', '8e6db08d-550c-4559-b152-ef61b523342f', 8, '100245924', '強敵が現われた時仮面ライダーはどうする?', '一葉の提案で、東島、ユリコ、一葉、三葉、ユカリスの5人で最強を決めるトーナメント戦をすることに。それぞれが10日後の本番に向けて特訓する一方で、街中に潜む洗脳が解けた元ショッカー戦闘員達にも脅威が迫ろうとしていた……', '2025/11/25 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a4e37e7-bc29-4a4a-9cb0-f2bb40cb2b95.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a722d7b-336d-4c06-bbfa-59eb130b8167', '8e6db08d-550c-4559-b152-ef61b523342f', 9, '100246409', 'お前のライダーを見せてみろ', '遂に最強決定トーナメント戦、開幕! 初戦の対戦カードは東島vs.ユカリス。続いて、一葉vs.三葉の兄弟対決となった。ショッカー戦闘員の姿になってほしいとユカリスに土下座する東島。一方で、プライドをかけた戦いを繰り広げる島村兄弟。激闘必死のトーナメントの行方は……', '2025/12/02 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9de90f9d-b85e-4108-9b80-84ecb2a0e719.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d09243d7-8780-4856-a235-a6b967d216fe', '8e6db08d-550c-4559-b152-ef61b523342f', 10, '100247133', '命を懸けるの', 'トーナメント3戦目は東島vs.ユリコ。蜘蛛男ですら尻餅をつかせた東島のライダーパンチに、思わず身震いするユリコ。しかし、タックルとしてのプライドから己を奮い立たせて対抗する。激戦を繰り広げ最大火力でぶつかる二人に、ユカリスは仮面ライダーと電波人間タックルの姿を見る……', '2025/12/09 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f2e70c0-a726-4565-ab42-6c21d8f87d02.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cdda5a6d-2965-4cf6-aba6-ebb3eaeed865', '8e6db08d-550c-4559-b152-ef61b523342f', 11, '100247881', '一番強いのはタックル', '遂に決勝戦…ユリコvs.三葉! 二人とも疲労の色が見える中、タックルとして、ライダーマンとして、最後の力を振り絞り、ぶつかり合う! はたして勝者は……!? そして、激闘を繰り広げた戦士達は各々の日常に戻っていくが……', '2025/12/16 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1677c765-b701-4e42-8d06-aaac4d474192.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aabaa28c-5d89-43d7-a500-973e355199e4', '8e6db08d-550c-4559-b152-ef61b523342f', 12, '100248500', 'まとめてかかってこいライダー共', '最強決定トーナメント戦を労うべく、後日、居酒屋ふたばで打ち上げを開くことに。そこで一葉はユリコへの想いを再告白するも、あえなく玉砕してしまう。各々が好きなように楽しい時間を過ごす中、ユカリスがショッカー戦闘員の気配を察知して……', '2025/12/23 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f882d5a-7a9f-4f80-b567-0b31a92193f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b5a300f-2d74-4b62-a231-70ba1451c3d5', '8e6db08d-550c-4559-b152-ef61b523342f', 13, '100249659', '俺はショッカーと戦って死ぬ', '打ち上げ会場だった居酒屋ふたばの個室は、中尾との戦いの余波でぐちゃぐちゃに…。呆然とする東島達の前に、怒り心頭に達する二葉が現れ、思わず逃走する一葉。二葉も負けじとどこまでも追いかけるが、遂に二人は激突! そこで二葉は兄への深すぎる恨みと憎しみを爆発させ……', '2025/12/30 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/819b4001-1e89-4c71-85f4-e7da07ca4ac5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c89e9411-feee-4c6f-bd4d-40dbe5bd6ea7', '8e6db08d-550c-4559-b152-ef61b523342f', 14, '100250294', 'もっと人間を知りたい', '雲田を追い詰めたと思いきや、蜘蛛男の姿があらわになり逆に追い詰められる二葉! すんでのところで逃げ切るが、彼女はショッカーの存在を否応無しにも信じることとなる。一方、蜘蛛男の前に新たな怪人が現れ……', '2026/01/13 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5494b774-8e93-4e45-992f-81392b80aeb7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e49d987-616a-47c9-b66a-7d777bb15e5e', '8e6db08d-550c-4559-b152-ef61b523342f', 15, '100250804', '覆面アイドル『ヘビーチョップ』', '雲田は、アイドルのセナを助けたことをきっかけに、奇妙な同居生活を始めることに! メンバーを失ったセナだったが、覆面アイドル「ヘビーチョップ」として活動を続け、雲田も人間の生活に溶け込んで同棲をしていた。そんな中、彼女の部屋に予想外の来訪者がやってきて……', '2026/01/20 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a19179c-309f-4fc2-b846-a321363b15fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e74342de-fc86-46e2-b4de-7c2c773d99a5', '8e6db08d-550c-4559-b152-ef61b523342f', 16, '100251615', '偽物は本物には勝てない', '以前、縁日で助けたたこ焼き屋の親父とばったり出会い、お酒を飲み行くことになった東島。そこで偶然、中尾と出会ってしまう。一方その頃、洗脳が解けた元ショッカー戦闘員が次々と謎の存在に粛正されていた。その正体は、普通の戦闘員を凌駕する戦闘力をもつ女ショッカー戦闘員･サンダーライコ。彼女の魔の手がユカリスにも忍び寄り……', '2026/01/27 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9b02a75-2127-49af-b831-02041d855eff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a9a66c8-67a1-4100-8814-7354da805618', '8e6db08d-550c-4559-b152-ef61b523342f', 17, '100252171', '世界中の人間をショッカーにしてやる', '怪人･蝙蝠男を前に、逃げることしかできなかった東島は失意の中にいた。そんな中、ある親子の会話をきっかけに、東島はヒーローとして、仮面ライダーとして大事なものを取り戻していく。一方、コンバットガールズが出演するアイドルフェスに恐ろしい牙が近づいていた……', '2026/02/03 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ada6561-79e1-4532-8bef-d18c36a55d66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d29783b9-fda9-4654-a2a7-3a9f7b1dfab8', '8e6db08d-550c-4559-b152-ef61b523342f', 18, '100252938', '俺もショッカーと戦う', '蝙蝠男の極秘計画を知ってしまった伊藤、石毛、佐藤は、中尾とともにショッカーに命を狙われることに。偶然出会った東島の家に匿ってもらうが、ショッカーの魔の手がすぐそこまで迫っていて…。一方、三葉に蝙蝠男の計画内容を報告した東島は、みんなで力を合わせて戦う必要性を説く……', '2026/02/10 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d542b0c4-df71-4d68-86f9-173086fd340e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76ca63dc-ceef-4afb-ac91-daf2b8ce8cee', '8e6db08d-550c-4559-b152-ef61b523342f', 19, '100253378', 'ライダーとして死ねるなら本望', '自分を逃す為に犠牲になった子分達の仇を打つべく、強くなる決意を固めた中尾。東島とともに修行の為、一葉の家を訪れるが、そこには怒り浸透の一葉が待ち受けていて…。その一方で、三葉とユカリスは蝙蝠男の計画を打ち破るべく、情報収集を始める……', '2026/02/17 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7670648f-3cb5-491d-9d3b-c2c97b1a7eac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('877d45a3-3be2-448f-ae52-47eb561e5dd5', '8e6db08d-550c-4559-b152-ef61b523342f', 20, '100254170', 'ちょうどショッカーと戦いたかった', '修行の日々を送る東島、一葉、中尾。しかし、中尾だけは二人の激しい修行ぶりにただ圧倒されるだけだった。そんなある日、軍鶏との戦いをきっかけに、自分に足らない点に気づいた中尾は覚醒して…。一方、三葉とユカリスは蝙蝠男が暗躍するイベントに危険を顧みず潜入するが……', '2026/02/24 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b66f0266-ce4c-4bd1-a868-f53716425263.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c1594aa-389d-4aed-8a39-591f847e7b39', '8e6db08d-550c-4559-b152-ef61b523342f', 21, '100254858', '最強の怪人になる', 'イベント会場で異様な事件に巻き込まれてしまう三葉とユカリス。大勢のショッカー戦闘員に囲まれた二人は、逃げ切ることが出来るのか!? 時を同じくして、中尾のもとには宿敵･サンダーライコが! ショッカーの最強を目指す彼女を相手に、中尾は厳しい修行の成果を爆発させる……', '2026/03/03 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e2480cf-49de-40f9-824f-e1ff5a6232a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4fb9545-5882-4c05-b080-dd370a9ff01f', '8e6db08d-550c-4559-b152-ef61b523342f', 22, '100255749', 'ショッカーが動き出した', 'サンダーライコにフラれた中尾だったが、失意のあまり、何故か東島と一葉とバトルロワイヤルに! しかし、三葉とユカリスからの「ショッカーが動き出した!」という知らせを受け、我にかえった三人は作戦会議の為に街へ。怪我から復活したユリコも加わり、蝙蝠男による大規模なショッカー増員計画を阻止する為、6人は力を合わせて戦う決意を固める……', '2026/03/10 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b096a99-b98b-4c2c-b9b1-ac00ff598ee0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d821df1-5b00-48ca-98e8-ffcf87b54693', '8e6db08d-550c-4559-b152-ef61b523342f', 23, '100256534', '行くぞ!! ショッカー!!!!', '蝙蝠男の計画を阻止する為、ライブ会場に潜入する東島達。そんな中、中尾の前に姿を現したのは、無情にもショッカーに洗脳された中尾の子分達だった。早くも阻止作戦が暗礁に乗り上げる中、中尾は子分達に優しい言葉をかける…。一方、ライブ終盤まで別場所で待機していた東島と一葉の前に、なんと蜘蛛男が……!', '2026/03/17 12:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8418e189-2538-4b03-bd51-f6f92a2455b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7078182b-757d-4483-8642-b0b80006115a', '桃源暗鬼', '', 'hulu', 'tougen-anki', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac6fe062-4532-44ae-9759-a138f2f18f5a.jpg?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 177474, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('64e50afe-85a7-4fa9-9267-873e2403459e', '7078182b-757d-4483-8642-b0b80006115a', 'hulu-tougen-anki-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae1ec27d-4503-4835-9a05-b2b96545db08.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5c65df57-9f73-485c-98a3-afbadefae187', '64e50afe-85a7-4fa9-9267-873e2403459e', 1, '100232555', '鬼の血', '突如、謎の男に襲われた一ノ瀬四季。養父の剛志に連れられて逃げる中、出生の秘密を告げられる。実は四季は“鬼”の血を継ぐ存在であり、“桃太郎”の血を継ぐ者たち“桃太郎機関”に狙われているのだと――。', '2025/07/15 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae1ec27d-4503-4835-9a05-b2b96545db08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b5ca9ef-de63-4a8c-835a-91a7035811c5', '64e50afe-85a7-4fa9-9267-873e2403459e', 2, '100233008', '成し遂げたいなら、勝ち続けろ', '桃太郎に対抗する組織"鬼機関"の一員･無陀野無人は、戦いで負傷した四季を回収する。意識を取り戻した四季に、無陀野は審査を開始。鬼の血に目覚めた四季が鬼機関に有用な人材か、冷徹に見極めようとする。', '2025/07/22 00:05:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0dcbf6cd-132d-4fe4-a566-dd1c85e39c18.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('970dc695-a7d7-427b-b2a0-e6e118e09cf1', '64e50afe-85a7-4fa9-9267-873e2403459e', 3, '100233512', '血蝕解放', '羅刹学園への入学初日。四季たち新入生に与えられた課題は、無陀野との“鬼ごっこ”。負けたら即退学というルールでありながら、四季は同じ1組目に選ばれた皇后崎迅の挑発に乗り、開始早々戦い始めてしまう。', '2025/07/29 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b414c7e-d3c3-44bf-b064-5ad32fe12be7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4adeb14f-f612-4c36-99b1-5574fc339f81', '64e50afe-85a7-4fa9-9267-873e2403459e', 4, '100234127', '協力しろ', '血蝕解放を成功させた四季は、造り出した銃で血の巨人を倒すが、血を使いすぎたせいで行動不能に。一方、皇后崎は、倒れた四季や帆稀を顧みることなく「鬼役を殺せば即卒業」という特別ルールに則り、無陀野に挑む。', '2025/08/05 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de7c42eb-5da5-4e34-9266-c782e7940919.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5d221e9-f10d-42d8-86a5-74509d73a4b0', '64e50afe-85a7-4fa9-9267-873e2403459e', 5, '100234855', 'ヤバい奴', '鬼機関京都支部の危機を知った無陀野は、四季たちを連れて救援に向かう。京都では、桃太郎機関戦闘部隊の隊長･桃宮唾切が副隊長･桃草蓬らと共に鬼たちを襲撃。恐ろしい計画を進めようとしていた。', '2025/08/12 00:05:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eca9cac5-7c28-4787-9ec2-1814304c37bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc172b58-5e85-488f-bc96-82bf1134050e', '64e50afe-85a7-4fa9-9267-873e2403459e', 6, '100235195', '外の道にも限度があるだろう', '運び込まれた鬼の遺体には、唾切の細菌が仕込まれていた。唾切の能力により操られた遺体が、かつての仲間たちに襲い掛かる。戦闘能力を持たない援護部隊や怪我人に対抗する手段はなく、京都支部は壊滅の危機に陥る。', '2025/08/19 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/282504ae-31ec-46c3-9f23-4a8bc0e2f098.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d3e5ebc-bfcf-4674-bde2-9eee44ce8933', '64e50afe-85a7-4fa9-9267-873e2403459e', 7, '100235684', '美人は手ごわい', '援護部隊総隊長･花魁坂京夜と皇后崎が、京都支部に侵入した唾切と蓬に遭遇する。花魁坂は伝令の指示を出して皇后崎を撤退させる。対する蓬は、桃の力で巨大な黒い箱を造り出し、京都支部を丸ごと閉じ込めてしまう。', '2025/08/26 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9385cb72-bf3d-4f8d-b753-309239aab81e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd4d1003-ffba-4d74-94f5-3f34ab31ff3a', '64e50afe-85a7-4fa9-9267-873e2403459e', 8, '100236190', '頼りない武勇伝', 'アグリに襲われ、バラバラになった四季たち。漣水鶏は血蝕解放を使い、一匹のアグリを倒すも、続いて現れたアグリに殺されかける。その光景を目の当たりにしながら、手術岾ロクロは何もできずに怯えていて……。', '2025/09/02 00:25:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c815674-901f-4ea7-b9c6-0ec0e68763cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1440e940-0622-45e8-a458-2eb59400efe3', '64e50afe-85a7-4fa9-9267-873e2403459e', 9, '100237303', '桃太郎魂', '四季と対峙し、本気を出すと宣言した唾切。用意していた“棺桶”を開くと、中から桃太郎が現れる。仲間すら人形にするのかと怒りを露わにする四季に対し、唾切はこの死体が自ら望んで人形になったと明かす。', '2025/09/09 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/132760b5-677c-41de-8564-5a66e989966d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f4250f8-d2cc-48e9-ba41-18ae5bc43570', '64e50afe-85a7-4fa9-9267-873e2403459e', 10, '100237768', '鬼神の子', '京都で鬼と桃太郎の激戦が繰り広げられる中、東京の桃太郎機関本部には五月雨の姿があった。21部隊隊長･桃巌深夜の挑発を受け流しながらも、五月雨は“鬼神の子”の1人である四季は自分が殺すと断言する。', '2025/09/16 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d941f37f-cd08-4b9a-affe-42237d609db2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e76c834-2824-49ea-ae17-28bf8746eb09', '64e50afe-85a7-4fa9-9267-873e2403459e', 11, '100238290', 'ありがとう!', '鬼神の力“炎鬼”を覚醒させた四季の力は圧倒的だった。巨大な炎に飲み込まれながらも、唾切の鬼への殺意は揺るがない。それは己が操る人形であり、かつて唾切を導いた桃太郎･桃部真中への誓いであった。', '2025/09/23 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4403386d-bb0d-4c23-8006-762cac29fc8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f2a18d6-9a69-498b-8f81-5ec530c6bdb5', '64e50afe-85a7-4fa9-9267-873e2403459e', 12, '100238994', '嵐の日', 'ひどく荒れた天気に見舞われた羅刹学園。修行を終えた四季たちが風呂場で憩いの時を過ごしていると、無陀野から避難訓練の実施を告げられる。体育館に集められた四季たちは、訓練としてそこで一晩明かすことに。', '2025/09/30 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fa4e492-4da4-4b80-8fca-0bc4f0fd24eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e493be4-7190-42d5-a883-e78e9b05cf6b', '64e50afe-85a7-4fa9-9267-873e2403459e', 13, '100239969', '神の門で神門', '東京の鬼機関の各部隊を見学するため、四季たちは練馬区星が陸へ来ていた。四季は一人抜け出して行った祭りで、警官の神門と出会い、意気投合。無陀野の命令で変装していた四季はナツと名乗って再び会う約束をする。', '2025/10/07 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f712a91-081a-4de2-9d8d-b79ffbc7336c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('14df4883-ec27-405e-ac6d-01b1a8be93af', '64e50afe-85a7-4fa9-9267-873e2403459e', 14, '100240842', '自分ルール', '街中で血蝕解放を使った皇后崎は、桃太郎の監視網に検知されてしまった。避難を余儀なくされた四季たちは、無陀野と共に鬼機関練馬支部のアジトに身を隠す。一方、桃太郎機関は皇后崎の捕縛へと動き出す。', '2025/10/14 00:20:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b7f8478-52d8-479a-a655-202dc7dce711.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a24d8905-3fb9-4bcd-b69f-7c07690245f6', '64e50afe-85a7-4fa9-9267-873e2403459e', 15, '100242047', 'みーつけた', '深夜は、桃太郎機関練馬支部を訪れ、20部隊隊長･桃華月詠と副隊長･桃角桜介に協力を要請。鬼神の子を倒す手柄を譲らせる代わりに、かつて鬼の戦闘部隊のエースであった無陀野との戦いを約束する。', '2025/10/28 00:05:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61383612-58c8-436d-9239-6cf3dd21df43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63b086d0-7a26-4cfd-8a1b-c5690831ff31', '64e50afe-85a7-4fa9-9267-873e2403459e', 16, '100242844', '悪くない', '救出された皇后崎は、自分が助けた少女が人質にされていると明かす。皇后崎、四季、無陀野の3人が急ぎ病院へ向かうが、無陀野は敵の気配を察知し離脱。残った2人が到着すると、病院ではなぜか火災が発生していた。', '2025/11/04 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/240beb9f-5259-4365-8387-3fb98cd39924.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f4164d2-1167-477f-bc9a-7ba457a9c7b2', '64e50afe-85a7-4fa9-9267-873e2403459e', 17, '100244046', '怨みの鬼', '桜介に勝負を吹っかけられた無陀野。桜介が操る伸縮自在の鎖鎌をいなし、強烈な体術と血蝕解放で圧倒する。それでも戦闘狂の桜介は、怖れるどころか強敵との戦いに喜び、防御を捨てて無陀野に突撃する。', '2025/11/11 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c65334c0-b57d-4170-a52c-c2dbeca25dbc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('671ca954-9912-45be-8248-2c68f285aee1', '64e50afe-85a7-4fa9-9267-873e2403459e', 18, '100245006', '疑心暗鬼', '四季たちが少女の自宅に到着すると、家は既に燃えていた。病院の火事も偶然とは思えず、練馬支部に戻り、状況を報告することに。真澄によると、桃太郎がなんらかの能力で皇后崎を監視している可能性が高いという。', '2025/11/18 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a95e03d2-c951-43df-88bf-4a5064fa74bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b49b0205-b911-431f-be81-691269ef005b', '64e50afe-85a7-4fa9-9267-873e2403459e', 19, '100245806', '弱者の声', '皇后崎を誘拐した手下たち“関東ナッツ連合”の居場所が見つからず、四季は再び神門に協力を求める。友を信じたい神門は、深夜に頼んでアジトの場所を調べ、その場に向かう。すべては己の目で真実を確かめるために。', '2025/11/25 00:05:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfb8971c-4f1e-4787-8b8e-1c5898932813.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bb94493-b563-4c6e-be93-7ba444ae5e9d', '64e50afe-85a7-4fa9-9267-873e2403459e', 20, '100246283', '怒VS怒', '桃太郎の力で皇后崎の視界を見た深夜は、鬼の新たなアジトを特定。月詠、桜介、神門を率いて奇襲をかける。ところが、大勢いるはずの鬼の姿はない。慌てて皇后崎の視界を見ると、そこには深夜の背中が映っていた。', '2025/12/02 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9042715c-bb28-44e6-b2c7-a913d1c50332.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0aa1f69b-265f-424b-a95a-6512fef8cf05', '64e50afe-85a7-4fa9-9267-873e2403459e', 21, '100246971', 'パーフェクトof運勢', 'タロットカードを駆使して能力を繰り出す月詠を前に、無陀野は防戦一方を強いられていた。一瞬の隙を突かれ、致命的な攻撃を許してしまう無陀野だったが、月詠に気づかれないよう反撃の一手を仕込んでいて……。', '2025/12/09 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb149c26-072e-44e7-95bf-40a147124501.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('869f077c-2e88-47eb-b677-3d3c55b83879', '64e50afe-85a7-4fa9-9267-873e2403459e', 22, '100247799', '虚しい闘い', '高層ビルの屋上。四季は、神門に身の潔白を話そうとするものの聞く耳を持ってもらえない。怒りをにじませ攻撃を仕かけてくる神門に、すべてが手遅れだと悟る。戦う覚悟を決めた四季は、血蝕解放で応戦する。', '2025/12/16 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b95d2b54-6e03-4f57-9fa3-29fedc955a50.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4868459b-9217-4408-835b-8347f131d288', '64e50afe-85a7-4fa9-9267-873e2403459e', 23, '100248415', '友よ', '6丁の銃を自在に操る神門に圧倒され、四季はついに戦闘不能におちいる。とどめの弾丸が胸を貫くその刹那、もっと強くなりたいという思いが、神門より強くありたいという衝動が、炎鬼の力を呼び起こす――!', '2025/12/23 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c370af9-5c57-42a6-8bbf-06f22311e110.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0bc54a8-dca4-465b-9ee3-e67bd27f968b', '64e50afe-85a7-4fa9-9267-873e2403459e', 24, '100249063', '再びのために', '【シーズン1 最終話】暴走化した四季を止めるべく、神門は決死の一撃を放った。力を使い果たした神門は、駆けつけた無陀野が自分にとどめを刺さないと聞いて唖然。無陀野たちの真の目的を知り、桃太郎である己に何ができるか考える。', '2025/12/30 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9ca6431-3949-46f6-83cb-5fa3c8565a9c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b4894e84-6ad7-4cab-8ed6-9f4b610a2bd7', '逃げ上手の若君', '', 'hulu', 'the-elusive-samurai', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/592cac31-f317-4c19-83d0-51d3cf846e2e.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 162896, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 'b4894e84-6ad7-4cab-8ed6-9f4b610a2bd7', 'hulu-the-elusive-samurai-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/010f869c-0571-40cf-bf82-2e56a8a53a41.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7bf33f0-51e6-4c85-8497-5a9bff2be237', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 1, '100190255', '5月22日', '時は元弘三年 (1333年) 鎌倉。世を治める鎌倉幕府執権の跡継ぎ･北条時行は、武士の子ながらも争いを好まぬ、心優しき少年であった。戦いと死こそが武士の名誉といわれる時代にありながら、武芸の稽古を嫌い、臆病者と囁かれ、逃げることと隠れることばかりが得意な時行。ある日、いつものように稽古から逃げ出した時行の前に現れたのは、怪しき神官･諏訪頼重。未来を見通す力を持つという頼重は、時行が「天を揺るがす英雄になる」と告げるのだった。嵐のような運命に翻弄される少年の、天下をかけた鬼ごっこが始まる――!', '2024/07/09 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/010f869c-0571-40cf-bf82-2e56a8a53a41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84133fc2-11f4-4a56-a86a-b88850773803', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 2, '100191069', 'やさしいおじさん', '鎌倉幕府の守護神とも称された足利高氏。その高氏の謀反により、鎌倉幕府は驚異の速さで滅亡に追い込まれる。伯父の五大院宗繁に保護され、高氏に与する武士たちの目を潜り抜けた時行の兄･邦時。一方、時行は頼重の領地･信濃諏訪に向かうため、鎌倉の外れにある廃屋に身を隠していた。しかしそこにも監視の目が向いてゆく。見知った旗印ばかりが翻る。誰が敵で、誰が味方か。裏切りの連鎖に打ちひしがれる時行たちに、さらなる苦難が迫るのだった――。', '2024/07/16 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc530ef4-586d-4677-80c5-9255c581753c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9fb37907-9500-4595-8313-0271635c4759', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 3, '100191683', '神の住む森', '伯父･宗繁との命をかけた鬼ごっこに勝利し、見事兄の仇を討った時行。諏訪の地に着くも、傷ついた心を癒す間もなく、時行は頼重に鎌倉奪還へ向けた鍛錬を促される。未だ頼重への疑念は拭えず、学ぶことの意味も見いだすことができない。自身が英雄となることを縁遠く考えている時行に、頼重はあるものを見せる。そして、共に鎌倉奪還を目指す「郎党」を作るよう告げるのだった。全てを失った少年は、「神」の加護を受け、諏訪の地で静かに力を蓄えてゆく——。', '2024/07/23 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e46f4f2c-2e6a-49d5-a740-b987b546e4df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a07b1941-a795-4926-b511-c7687e695829', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 4, '100192637', '貞宗登場!', '時行は鎌倉奪還のため、日々剣術の稽古に励む。しかしその太刀筋は、誰もが驚くひ弱さであった――! そんな時行が唯一得意とする武器は「弓」。「逃げ」と「弓」の二つを活かした戦術に頭を悩ませる頼重のもとに、突如来客の知らせが入る。諏訪大社を訪れたのは、新たに信濃守護に任じられた武将･小笠原貞宗。挨拶がわりと天下無双の弓技を見せつけた貞宗の姿に、頼重は妙案を思いつく。鎌倉幕府滅亡を機に動き出した各地の勢力図。諏訪の運命は、時行に託される――。', '2024/07/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25858153-1fbc-4a5c-b661-df4134e7ef23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0ec42fe-b330-4490-a489-38dc0cda157e', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 5, '100193808', '決着! 犬追物、そして…', '武芸に秀で、驚異の「目」の良さを持つ貞宗との犬追物対決。時行は大きく点差をつけられ、負傷し、追い込まれてゆく。しかし、手綱を取り、馬を走らせ、容赦のない攻撃にさらされながら、時行は……瞳を輝かせていた!「逃げ」のなかに自らの戦い方を見いだした時行は、じわじわと貞宗に迫ってゆく。果たして、犬追物の結末は――。貞宗との勝負の相手に時行を指名した、頼重の思惑とは――。そして、諏訪大社から離れた地からは、とある盗人の噂が届くのだった……。', '2024/08/06 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e38f0322-5f70-4905-8e5d-81e1d8b90d72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59181f92-b914-45b9-bbe9-74481df967f3', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 6, '100194613', '盗め綸旨、小笠原館の夜', '自在に姿を変化させ、あらゆる技で敵を翻弄する盗人･風間玄蕃。時行は玄蕃と共に小笠原の館に忍び込み、帝の綸旨が保管されている蔵への侵入に成功する。しかし、そんな二人の様子を、貞宗の配下･市河助房の「耳」が捉えていた……。助房の「地獄耳」に、さすがの玄蕃も苦戦を強いられる。息の音一つさえも命取りとなる状況で、二人は着実に追いつめられてゆく。命の危機に瀕する時に垣間見える人の心こそ本質。闇夜の隠れ鬼に、時行たちは勝利できるのか――。', '2024/08/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67d5e9b5-c704-43db-9a18-7731fc8ad32d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e91fa2e-45d1-444f-867d-966224a2a30b', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 7, '100195253', '冬の子供たち', '諏訪での初めての新年を迎える時行。全国の混乱は一応の小康状態となっているものの、小競り合いは続き、諏訪の地にもまた新たな危機が迫っていた。諏訪領･北の国境付近にて、小笠原の不穏な動きを察知した頼重たち。腕利きの偵察が出払っているなか、時行は「逃若党」による偵察を提案する。心強い申し出に喜ぶ郎党たちだったが、なぜか頼重だけは猛烈に反対し……。大人たちからの期待と心配を背に、逃若党が諏訪を駆ける――!', '2024/08/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90fcb078-c9ef-457e-8e25-4286d44a434e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c85dde0f-dcd3-4647-949b-6a2d18af7545', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 8, '100195886', 'かくれんぼ戦争', '諏訪領の北端･中山庄へと向かった逃若党。そこで時行たちが出会ったのは、吹雪という名の一人の少年だった。小笠原勢により大人たちを殺され、その後も襲われ続けている村を、遺された子供たちとともに守り続けていた吹雪。逃若党は、兵法にも通じる吹雪と協力し敵を迎え討つ作戦に出る。そして時行は、吹雪からある剣技を授かることとなり……。対して村を狙うのは、「悪党」として恐れられた男･瘴奸が率いる、血に飢えた悪鬼ども。新たな若き頭脳を味方に、時行はこの窮地を切り抜けられるか――!', '2024/08/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2551870-2aaf-4c44-a0a3-92f04da96508.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60c6fdb1-cb2c-4233-bd71-5e9387e1eda2', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 9, '100196665', 'わたしの仏様', '激しさを増してゆく瘴奸率いる「征蟻党」と逃若党の戦い。狭い室内、鎧武者相手という厳しい状況のなか、時行は吹雪から授かった「逃げ」を活かした技で大将･瘴奸に立ち向かう。一方、征蟻党幹部・死蝋を相手に苦戦を強いられる弧次郎と亜也子。そして一人、同じく征蟻党の幹部･腐乱を誘い出した吹雪の思惑とは……。圧倒的な戦力差ある大人たちに、天下奪還を目指す少年少女たちが挑む。慈悲深き仏の一太刀は、地獄の闇を彷徨う鬼への救いとなり得るか――。', '2024/09/03 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d2b6900e-3b89-4d20-8519-19bad443906e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5027dba-cb09-4b94-b7b7-7782e37c093a', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 10, '100198849', '変態稚児と神力騒動', '一時的に未来が見えない時期があるのだと、頼重から打ち明けられた時行。神の力を拠りどころとする者もいるため、みなに事情を明かせない頼重は、時行の手を借りて、神力を取り戻すための方法をひとつひとつ試してゆく。諏訪大社中を駆け回り、頼重が望むとおりのものを揃えてゆく時行。しかしどれを試してみても、一向に神力が回復する兆しは見えないどころか、時行に思わぬ影響が及んできて……。神と人とが共存する最後の時代。時行は、つかの間の不可思議に触れる……。', '2024/09/17 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d39d57fe-5146-4f25-bb66-63f4f0b7e646.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('814656e3-b495-4089-86b5-9cf91181399b', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 11, '100199681', '死にたがりと逃げ上手', '朝廷より新たに任じられた信濃国司･清原信濃守。その男は権勢を振るい、領民たちを苦しめる悪徳国司であった。いよいよ圧政に耐えかねた諏訪神党の一人･保科弥三郎は国司を討つため兵を挙げる。しかし諏訪は朝廷との対立を避けるため、救援を出すことができない。頼重の頼みを受け、保科党の反乱をとめるため、北信濃･川中島へ説得に向かうこととなった時行と逃若党。「誇りのために死ぬ」覚悟に燃える武士たちに、時行は「逃げて生きる」覚悟を示せるか―', '2024/09/24 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/574d9305-6440-42dc-8862-7187c3c35a0a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd89761a-fa4a-486f-a6c8-e71e33b0f4e9', 'bbd25654-42d3-4c66-a5ea-e0937cfa66c2', 12, '100200597', 'がんばれ時行、鎌倉奪還のその日まで', '【シーズン1 最終話】時行と諏訪神党･四宮左衛門太郎の説得を受け、川中島からの撤退を決めた保科軍。しかし、悪辣な国司がそれを黙って見逃すはずもなく……。領民たちを守りながらの平地での戦い。国司軍に数で劣る保科軍と逃若党。得意の「逃げ」を活かし、時行は将となり得るか。「逃げるが勝ち」の撤退戦の行方は――!', '2024/10/01 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/768abaaa-e315-4e35-acc4-0b83a4e3e858.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b09c6a6a-7f4c-47de-8c14-321e268dc28a', '逃走中 グレートミッション', '', 'hulu', 'run-for-money-the-great-mission', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/858aba20-8ea8-43fe-9112-ae757069a222.png?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 159560, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0f025d22-dd3f-4d92-a16c-17f82f657716', 'b09c6a6a-7f4c-47de-8c14-321e268dc28a', 'hulu-run-for-money-the-great-mission-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/570d962f-1ce6-4c61-85a6-c3798f96d042.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('074014cb-a542-44f1-9f1c-46b2f9c5ca34', '0f025d22-dd3f-4d92-a16c-17f82f657716', 1, '100141140', '走れ! 運命のステージ', '時は、人類が月に住処を移した未来。月面コロニーに住む人々は、クロノス社が開催する一大エンターテインメントサバイバルゲーム『逃走中』に熱狂していた。', '2023/04/05 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/570d962f-1ce6-4c61-85a6-c3798f96d042.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9684911-d4b4-4baf-b420-bae7caa1400d', '0f025d22-dd3f-4d92-a16c-17f82f657716', 2, '100142937', '救え! 謎の少女', '颯也が飛び込んだ『逃走中』の舞台、それは「2023年の渋谷」であった。突如として出現し、暴れ回る巨大怪獣シブラー。人々が逃げ惑う中、颯也は不思議な少女･すずに出会うが…', '2023/04/12 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af082c6d-18ce-444f-9a2a-3be5d12444d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('843f8b71-3643-4bec-9a40-4c39f0a22b06', '0f025d22-dd3f-4d92-a16c-17f82f657716', 3, '100143723', '食い止めろ! 伝説の破壊神', '怪獣シブラ―が現れ、その触手が町の人々や逃走者たちを襲っていた。そんな中ミッションをクリアし、逃走エリアが拡大。逃げやすくなったかと思われたが…。', '2023/04/19 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b922b795-a5b2-4fe7-988b-5c6f5712df6e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('186abf79-c4f0-4bb0-a957-7996f9284bfd', '0f025d22-dd3f-4d92-a16c-17f82f657716', 4, '100144378', '決めろ! 約束のタッチダウン', '丹波博士が開発したバーストブラスターを使い、シブラー打倒を目指す逃走者たち。だが、バーストブラスターを起動させるにはエターナルメタルのエネルギーが必要だった…。', '2023/04/26 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac109d63-d784-423f-b0d0-5882cd2c24dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79e620e4-d507-48ee-857a-e83f48870d1d', '0f025d22-dd3f-4d92-a16c-17f82f657716', 5, '100144738', '登り切れ! 決死の復活ミッション', '颯也はミッションの最後を仲間に託したが、裏切りにあい、ミッションは失敗。怪獣シブラーは更なる進化を遂げ、ルナは牢獄へ送られてしまった…', '2023/05/03 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fde9fd65-77e5-4b4a-98e0-7411def4cfb8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e27dc69-efaa-4731-8c0e-e397e4492cb8', '0f025d22-dd3f-4d92-a16c-17f82f657716', 6, '100145629', '届けろ! 少女の想い', '最終形態となった怪獣シブラー。シブラーを倒すには、すずのペンダントに収められている高純度のエターナルメタルを利用した最終兵器を完成させる必要があった。', '2023/05/10 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0942ecbe-1f49-4f79-8d38-c1b25ec9ef11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8dd773e-fdec-4c8b-ab5e-2fcbd3170064', '0f025d22-dd3f-4d92-a16c-17f82f657716', 7, '100146104', '倒せシブラー! シブヤ最終決戦', 'バーストグレネード完成まで時間を稼ごうとしていた颯也を、怪獣シブラーが踏み潰した! 絶句する逃走者たちだったが、、、', '2023/05/17 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/271fbe81-f9de-4c35-b327-5eac37acff1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e17292d5-b198-49b9-8869-b92a39bb6bc1', '0f025d22-dd3f-4d92-a16c-17f82f657716', 8, '100147723', '新ステージ開幕! 仮面の男', '『逃走中』から数か月後、バイタルブレスを失った颯也は、ただの運び屋として荷物を運ぶ日々を送っていた。そんな中恐るべき身体能力で移動する謎の男に出会うのだが…。', '2023/05/31 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59b3b6d4-d3a5-419a-aa75-a5b2148993b2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e85b2691-da31-4ff0-ba9e-987e93c896e4', '0f025d22-dd3f-4d92-a16c-17f82f657716', 9, '100148305', '風雲! 復活の覇王信長', '颯也たちが降り立った『逃走中』の新たな舞台、そこは「江戸時代のオワリの国」だった。颯也とルナは、城下町で侍の少年･五郎太を救うのだが…。', '2023/06/07 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f575a5d-4f24-45d8-b5c3-0950a7c63c7f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91474574-c343-494c-a1ca-6308cb4c08e3', '0f025d22-dd3f-4d92-a16c-17f82f657716', 10, '100148976', '魔剣! 嗤う剣客小次郎', '逃走を続ける颯也たちの前に立ちはだかったのは、伝説の剣豪･宮本武蔵だった。さらに、背後から同じく剣豪の佐々木小次郎が迫る。慌てて身を隠す颯也たちだが…。', '2023/06/14 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a57b3194-90ab-4c10-b19d-31aa04cd708a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b5a3ee7-12dd-4df9-80af-fd6fd0532b0d', '0f025d22-dd3f-4d92-a16c-17f82f657716', 11, '100149544', '仇討! 無双の二刀流武蔵', 'ミッションはクリアしたが、モーリスが倒壊する家屋に巻き込まれ、生死不明の状態に。だが、同じく倒壊に巻き込まれた宮本武蔵は生きていた!', '2023/06/21 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9beee5d5-20b2-40fa-a282-a3b9bf7238ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c1ca718-54d8-4d49-9e87-0a44f6cfeeec', '0f025d22-dd3f-4d92-a16c-17f82f657716', 12, '100150558', '眩惑! 妖術絵師国芳', '颯也たちを呼びつけたのは、東の森で暮らす奇人･平賀源内だった。信長に対抗するためには伝説の守り神「侍魔人」を復活させるほかないと言う源内だったが…。', '2023/06/28 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fc487554-5503-4617-8a76-4b8e6b55018b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cf03d54-211a-4f98-92fc-fc4a24e9bebe', '0f025d22-dd3f-4d92-a16c-17f82f657716', 13, '100151209', '攻城! 侍魔人動く', 'オワリ家の守り神である侍魔人を呼び起こせば、織田信長を退けることが出来る。そのことを聞いた颯也たちはオワリ城への潜入を決意する。', '2023/07/05 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf405344-8e31-4723-ab36-7682a5dba707.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31106eb3-fb58-4663-802c-bfd4b186a185', '0f025d22-dd3f-4d92-a16c-17f82f657716', 14, '100151968', '覚悟! 決意の五郎太立つ', 'ミッションをクリアし、侍魔人を呼び起こし歓喜する颯也たちだったが、喜びも束の間、織田信長と安倍天魔に侍魔人を奪われてしまう。', '2023/07/12 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0ad714b2-832d-4813-a9fb-29c5065ceac3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba20d86c-5767-498a-92f9-19131c31acb2', '0f025d22-dd3f-4d92-a16c-17f82f657716', 15, '100152756', '驚愕! 信長怒涛の最終変化', '逃走者たちと空飛ぶ鬼との激闘も終盤戦。武器であるエレキテル砲のエネルギーが僅かとなるが、遂に共闘した颯也とシグマによって、最後の一体を倒すことに成功した。', '2023/07/19 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6412081a-0b83-4de4-84e0-441a930f27e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bba37174-cbb3-4168-811b-c095dbbd89c8', '0f025d22-dd3f-4d92-a16c-17f82f657716', 16, '100154114', '激突! 信長対五郎太', '「五郎太に信長を討ち取らせよ!」この最終ミッション達成のため、信長を目指す颯也たち。だが、復活した妖怪･佐々木小次郎と宮本武蔵が行く手に立ちはだかる。', '2023/08/02 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5b78b12-b50a-4faa-8fd6-a1117bd42a13.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7017ca2f-3050-4dbc-b1c3-8de2cf5f425f', '0f025d22-dd3f-4d92-a16c-17f82f657716', 17, '100155080', '疾走! 魔界城を逃げ延びろ', '逃走成功まであと僅か。残された颯也、ルナ、モーリスを、計8体のハンターが容赦なく追いかける! やがて、3体のハンターに囲まれ、逃げ場を失う颯也だったが…', '2023/08/09 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/721a2334-e6d0-4ba8-8d69-bc37acf695b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa44bea6-0651-4821-9f52-1003bb658e48', '0f025d22-dd3f-4d92-a16c-17f82f657716', 18, '100155537', '謎の逃走者 ジョン ドゥー', '次回『逃走中』の出場辞退を発表した絶対王者モーリス シューメーカー。大本命不在で、次は一体誰が逃走成功するのかと巷で話題になっていた。', '2023/08/16 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b42bbe1-b369-460a-b883-2d908b7bafba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85f2a2d1-da36-4857-a151-b0b780cdf931', '0f025d22-dd3f-4d92-a16c-17f82f657716', 19, '100156467', '霧のミステリー! ジャック･ザ･リッパー', '颯也たちが現れたのは19世紀末のロンドンだった。ここが次なる逃走中の舞台だ。あちこちを散策していた颯也とルナだったが、恐ろしい事件に出くわしてしまう。', '2023/08/23 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4db2e430-90b0-448b-b5dd-67f8728489d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61b2f82c-44a7-470e-a317-7ac28cecefee', '0f025d22-dd3f-4d92-a16c-17f82f657716', 20, '100156863', '炎のチェイス! ロンドン大追跡', '切り裂きジャックの罠にはまり、絶対絶命の颯也とシグマ。だが、颯也の中に新たな力が目覚める。その力によって何とか危機を脱するものの…。', '2023/08/30 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7aba9826-9d9f-41e6-be95-67451136318b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('606cf808-51e8-4ebf-94cb-116c1f867a72', '0f025d22-dd3f-4d92-a16c-17f82f657716', 21, '100157953', '狙われた美女! オペラハウスの謎', '謎の声に導かれ、思わぬ力を発揮した颯也とシグマとルナ。だが、能力があがったのは、颯也たちだけではなかった。パワーアップしたハンターたちが逃走者を追い詰める。', '2023/09/06 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52681e36-e99e-4337-b902-9b6ccb9a8250.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e08c347-2ac9-434f-a686-b8685ad8195f', '0f025d22-dd3f-4d92-a16c-17f82f657716', 22, '100158316', '魔の歌声! テムズ川のセイレーン', 'オペラ歌手を誘拐したのは、タコの化け物のクラーケンと眠れぬ怪物セイレーンだった。さらにハンターの邪魔も入り、ミッションは失敗してしまう。', '2023/09/13 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5042f831-ae89-4286-a6ee-46deb4d2ee83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a29f61c3-3e89-4282-b681-e40ec82cb280', '0f025d22-dd3f-4d92-a16c-17f82f657716', 23, '100159164', '吸血鬼の街 夜明けの列車に乗れ', 'マックス警部の元に新たな予告状が届き、南の街エリアへやってきた逃走者たち。そこでは原因不明の病が流行り、多くの美女が昏倒し眠っていた。', '2023/09/20 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5b4b17f5-7a2e-4d02-9ffb-0e18d35f76bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64b7b0d4-f6bd-4985-b3b9-e5ceed7dad1a', '0f025d22-dd3f-4d92-a16c-17f82f657716', 24, '100160136', '襲われた影 古城のファントム', '古城エリアへと到着し、ドラキュラの城を目指す颯也たちの前に、ドラキュラ伯爵が姿を現した。覚醒し闘いを挑む颯也だが、ドラキュラの強さは凄まじく…', '2023/09/27 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6990cda4-b694-429b-a441-20ab70917b45.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d1a0876-12c5-406b-9a08-568ac515343e', '0f025d22-dd3f-4d92-a16c-17f82f657716', 25, '100161015', '紅の伯爵 不死身のドラキュラ', 'ドラキュラの城へ到着した颯也やシグマたちは、ドラキュラ伯爵の居場所を探る。だが、ファントムによって、吸血鬼に変えられてしまった逃走者たちが行く手を阻む。', '2023/10/04 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/253b6f79-94b0-4ad5-80fc-941894e94ea2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f0f227a-88b9-45b6-8f50-4c1216c10b05', '0f025d22-dd3f-4d92-a16c-17f82f657716', 26, '100161798', '名探偵ハル! ミノタウロスの罠', 'ロンドンで誘拐事件が多発しているとの報告を受け、城から戻ってきた逃走者たち。しかし戻って早々、マックス警部が動くミノタウロスの銅像に攫われてしまう。', '2023/10/11 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa9b8010-a3de-4a92-b70f-4c949774da49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01731d60-069c-4c5e-a6ba-5b6891b4eeed', '0f025d22-dd3f-4d92-a16c-17f82f657716', 27, '100162727', '光る目 メデューサを撃破せよ!', '颯也達の前に現われたのは怒りのメデューサだった。同時に『メデューサを倒し、地下迷宮を脱出せよ! 』という緊急ミッションが開始される。', '2023/10/18 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/812c1f1a-b4b4-4525-9aee-953a4cc3bbf5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfc7fb6b-9cf2-4bb3-8b74-1d61a2b120c6', '0f025d22-dd3f-4d92-a16c-17f82f657716', 28, '100163737', '混乱のラビリンス 裏切り者は誰だ!?', '「逃走者の中に殺人鬼が紛れ込んでいる」と通信が入り、動揺する颯也達。しかし、ゲームマスター･月村サトシはこの状況を利用し、新たなミッションを発動する、、、', '2023/10/25 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f20c5e43-61dd-4c5e-82eb-e97f5a67c757.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c043d177-22ab-477f-b061-4fb1b30d54f6', '0f025d22-dd3f-4d92-a16c-17f82f657716', 29, '100164357', '黒幕始動 潜入! 闇の研究所', '怪事件黒幕である、ガイアロストの秘密研究所へ向かう逃走者達。彼らが見たものは、改造を施された人間たちと、それらを生み出したゼベットと名乗る科学者だった。', '2023/11/01 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f8978ed-9226-4705-b5a7-02227a6b56cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5e44f54-4098-461c-aac1-ba7e2af48dcc', '0f025d22-dd3f-4d92-a16c-17f82f657716', 30, '100165394', '死闘! バトル オブ ロンドン', '全ての黒幕であるゼベット教授を追い詰めようとする逃走者たち。だが、用意周到なゼベットは、ロンドンの地下に巨大飛行船を用意していた。', '2023/11/08 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd97a2b6-60db-45e9-be7c-319fe15b3107.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87baf674-17c9-4fa7-a07b-0d498bd3d39f', '0f025d22-dd3f-4d92-a16c-17f82f657716', 31, '100166097', 'さらばロンドン! 霧の都を逃げきれ!', '最終ミッションを見事クリアし、後は逃げ切るだけとなった颯也達。だが、彼らをロックオンしたハンターは執拗に追いかけてくる。残るは颯也とピエタだけだった。', '2023/11/15 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6313e3b-56aa-4785-9653-3934b01c7765.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('072be459-5d18-4967-831a-ef1d42c392e5', '0f025d22-dd3f-4d92-a16c-17f82f657716', 32, '100166742', '颯也再始動! ガスティン秘密のステージ', '颯也は『逃走中』のトレーニングステージ･シブヤでの修行に入るが、ひとりで複数のハンターから逃げ切るのは難しく、何度挑戦してもゲームオーバーとなるのだが…', '2023/11/22 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/789ae772-d1f7-4938-bf9a-512e48ab545a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ad775e3-8698-4f09-894d-7296c1f6ea2c', '0f025d22-dd3f-4d92-a16c-17f82f657716', 33, '100167324', '灼熱! 砂漠の魔法王国', '新しいステージの舞台は、中世のエジプトに存在したと言われる伝説の国『ジャガリア王国』。葬祭殿では、3000年前に封印された呪われたファラオの復活が企てられていた。', '2023/11/29 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a5a97d93-9b7b-4c3a-b44b-0e1c7d70c1d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6657dc6d-63d5-4bb4-bc2c-07ede03fe02e', '0f025d22-dd3f-4d92-a16c-17f82f657716', 34, '100168140', '恐怖! ミイラだらけの街', 'ミイラの毒液を浴びると身体の水分が蒸発し干からびてしまう。生き玉を狙うミイラから子供を助けようとして毒液を浴びたクレアは干からび、ハンターからも狙われるが、、、', '2023/12/06 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6771b3b8-d9fb-4ed6-98ca-3cc2541ba4d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a4cbbd8-a6b6-4b9a-b6fb-0b99abfb097f', '0f025d22-dd3f-4d92-a16c-17f82f657716', 35, '100168772', '石板の謎を解け!  砂漠のロマンス', '4枚目の石板は港で船に積み込まれる荷物の上に載っていた。船に積まれれば、石版は逃走エリアの外。二度と手に入らなくなり、ミッションは失敗になってしまう、、、', '2023/12/13 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62dc5a92-7d73-4925-9740-3044e1a6e880.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fff3c69-c06f-4770-9f4c-8aa6213c08c3', '0f025d22-dd3f-4d92-a16c-17f82f657716', 36, '100169471', 'さらわれたレイラ! 砂の魔神ラムルを追え!', 'カイト王子の恋人･レイラ姫が誘拐されてしまった。レイラ姫を救出するためには、彼女を攫った砂の化け物の居場所を突き止めなくてはならないのだが、、、', '2023/12/20 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a2ee49b-b59d-4054-b99d-adff161720ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8c03494-d758-4e14-88b1-2132606483fc', '0f025d22-dd3f-4d92-a16c-17f82f657716', 37, '100170406', '動く迷宮 アヌビスの神殿を攻略せよ!', '砂の神殿へとやって来た、颯也たち逃走者とカイト王子。しかし、神殿の内部は迷路になっていた。ハンターたちを掻い潜り、レイラ姫のもとへと近づく颯也たちだが、、、', '2023/12/27 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5d12e90-3aa9-4943-ac40-6b5c637e84f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c4ecc94-394e-44f7-b53f-829468f33869', '0f025d22-dd3f-4d92-a16c-17f82f657716', 38, '100171180', 'スター覚醒! アヌビスを封印せよ', '颯也たちより一足先に迷路を抜け、アヌビス神のもとへ到着したルナやガスティン。アヌビス神の傍にはレイラ姫が眠らされていた。', '2024/01/10 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fae7be96-4fa3-4ad2-b393-b018ba970bfe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dd891588-dd9e-46e6-9dfc-a87eb29e599f', '0f025d22-dd3f-4d92-a16c-17f82f657716', 39, '100172012', '脱落ミッション! ペンタの裏切り', 'ミッションは失敗に終わり、レイラ姫の生き玉は奪われ、ファラオは復活してしまった。だが、カイト王子は、決闘島でファラオを倒せば、レイラ姫も蘇る筈だと颯也に話す。', '2024/01/17 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/65447bdb-bc7e-434d-91a0-fe1f734f9192.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c244932-f7f1-464e-a298-04c7196b86c3', '0f025d22-dd3f-4d92-a16c-17f82f657716', 40, '100172856', '敵は誰だ!? 決闘島魔法対決!', '決闘島へ上陸した颯也たち5人の逃走者たち。そこで待っていたのは、ホルスと名乗る島のあるじだった。戦いは1対1。5人が空中に浮かんだ巨大な島の上で戦う事に。', '2024/01/24 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e584dfaf-c92f-4cb4-b1a1-c8ebe772975e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4730c991-1c10-4e64-8f26-df99af6975dc', '0f025d22-dd3f-4d92-a16c-17f82f657716', 41, '100173440', '邪神覚醒! ファラオの目覚め!', '颯也たちジャガリア王国の5人の戦士たちと、ガルーダル王国の5人の戦士たちとの戦いが続く! そして、ようやく戦いの決着が付き、戦士たちはホルスの神殿へ集められた。', '2024/01/31 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d869d778-f283-4695-8220-0778d2c8cb26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3162c002-6a0f-4cbc-ae02-a3cd78fc8f3b', '0f025d22-dd3f-4d92-a16c-17f82f657716', 42, '100173818', 'レイラの願い…倒せ! ファラオ究極体!', 'ガルーダルの王族やホルスを自らの体内に吸収し、ファラオは恐ろしい巨大な姿へと変貌を遂げた。その禍々しい姿に圧倒される颯也たち。', '2024/02/07 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afc4bd2a-bc2b-4224-a3f5-86b42b995ed8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06331165-40a5-4643-b4ff-9244a82ba6a4', '0f025d22-dd3f-4d92-a16c-17f82f657716', 43, '100175094', '絶望の魔法都市、ホルス最後の希望', '王族とホルス神を吸収し絶大な魔力を手に入れたファラオ。そのファラオを倒すため、颯也とカイトはファラオの体内からの攻撃を試みることに…', '2024/02/14 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e1d830d-ebfc-456e-bedf-ae5272a88b18.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80f3150b-e2b4-4b07-ac43-6a675ce70fe8', '0f025d22-dd3f-4d92-a16c-17f82f657716', 44, '100175579', '闇に向かって撃て! 愛の大魔法!', '怨霊ファラオを倒し世界を滅亡から救うため、3つに分かれて島中に飛散したホルスの矢を手分けして集める逃走者たちだったが…', '2024/02/21 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a2f3f61-4a9a-410d-b495-3c369d4a1ed6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d6ab567-bb23-41f7-8484-59c421a86327', '0f025d22-dd3f-4d92-a16c-17f82f657716', 45, '100176242', '颯也暴走!? 怒涛の魔法都市ラストラン', '全てのミッションが終了し、沈みゆく決闘島から逃げ出そうとする逃走者たち。その最中ガスティンと颯也が島の崩落に巻き込まれてしまう!', '2024/02/28 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5e8dd1e-d917-4f98-8ddf-3208c625bded.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46b4f6b6-337a-4c7e-baa8-29f706ac0712', '0f025d22-dd3f-4d92-a16c-17f82f657716', 46, '100176964', '暴かれる謎! ウォークライと怪盗の秘密!', '魔法都市ステージを逃走失敗で終えた颯也は、ゲーム終盤に発動したウォークライで自我を失い暴走した理由を知るべく、ガスティンの工房を訪れることに', '2024/03/06 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4f22126-03a6-4785-8297-eda51911420b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9488760c-efd9-4e90-bfa6-fab5aba37629', '0f025d22-dd3f-4d92-a16c-17f82f657716', 47, '100178421', '新ハンター起動! 波乱の新ステージ', '新ステージに挑む颯也たちだが、システムが何者かにハッキングされてしまい、月村の判断で強制終了となる。復旧を急ぐクロノス社の面々、そんな彼らの前に現れたのは…', '2024/03/20 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31ed59d9-a3bd-49d8-a09b-b584ce773b56.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfe9f4b9-b131-4926-9e19-88c400b859fe', '0f025d22-dd3f-4d92-a16c-17f82f657716', 48, '100178843', 'ラビの決意! 逃走中を取り戻せ', '宇宙船でA3コロニーへと向かう颯也たちだが、狼月から早速手荒な歓迎を受ける。ミサイルで撃墜され不時着、散り散りになった颯也たちは…', '2024/03/27 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33f23c74-1d34-46d0-ba1d-7fccee463f7b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6a7cdc8-9918-4e04-af4f-a7699d8f6a71', '0f025d22-dd3f-4d92-a16c-17f82f657716', 49, '100179649', 'めざせニューヨーク! アメリカ横断逃走中', '新ステージは1970年代の西海岸! そして最終目的地はニューヨーク! さっそく行動を開始する颯也たちだったが、A3コロニーのハンターは大幅に強化されている!', '2024/04/03 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e525d11-b555-4a6a-8b77-b6d4ea9ed999.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5c9b0a4-de60-410d-88c0-f9d89023b259', '0f025d22-dd3f-4d92-a16c-17f82f657716', 50, '100180455', '謎の美女を運べ 爆走カーレース!', 'マフィア達に追われている謎の女性･キャリーと出会う颯也、隣町で開催されている『バルーン祭り』の会場までコーラを届けたいので手伝ってくれと頼まれるのだが…', '2024/04/10 00:00:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5999892a-49c2-465d-8e35-634f62b6b4eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4c9c492e-46d0-4e53-925d-8e14d41ec8b1', '透明男と人間女～そのうち夫婦になるふたり～', '', 'hulu', 'the-invisible-man-and-his-soon-to-be-wife', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/42c2033a-d840-4308-96dc-c10e5c2d0d22.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'RELEASING', NULL, 185039, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', '4c9c492e-46d0-4e53-925d-8e14d41ec8b1', 'hulu-the-invisible-man-and-his-soon-to-be-wife-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6a918fb-6135-43c8-81ef-eb5aa6a3aecc.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a7e3cb2-d848-4c5d-8ded-c5ba8cb46f72', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 1, '100249618', 'そのうち夫婦になるふたり', 'さまざまな種族の人々が支えあいながら共生する社会。目の見えない人間女性･夜香しずかはある日、透明男の探偵･透乃眼あきらに食事に誘われ、ひそかに想いを寄せるようになっていった。彼の紳士的な一挙手一投足に胸を高鳴らせながらも、探偵事務所の一員として透乃眼を支え続けるしずか。姉御肌な獣人女性の写螺子ルナや、ぶっきらぼうな人間男性の鬼木羅だいちらも加わり、透乃眼探偵事務所の慌ただしくもほほえましい日常が今日も始まった。', '2026/01/09 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6a918fb-6135-43c8-81ef-eb5aa6a3aecc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7943919a-64c4-4cbc-87fa-264ed15a0785', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 2, '100249619', 'デート大作戦', '透乃眼からデートに誘われて、しずかはダークエルフのカルマとホワイトエルフのライトが夫婦で経営する紅茶専門店へとやってくる。互いのためにオリジナル茶葉のブレンドにチャレンジしつつもさらに距離を縮めていく透乃眼としずか。デートは無事に終わったものの、しばらくして今度はカルマとライトが依頼人として透乃眼探偵事務所へとやってきた。夫妻は不審な一団によって監視、追跡されるというストーカー被害を訴えており、事態は探偵事務所のメンバーを巻き込んだ大捕り物へと発展するのだが……。', '2026/01/16 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7200c83-9e97-47eb-a6d7-1dd7d13b96ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43b35b41-82b5-4c9c-869e-e1a9f3deb763', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 3, '100249620', '付き合いはじめて一週間', 'たび重なるデートを経て、なんとか交際を始めた透乃眼としずか。仕事とプライベートとの切り分けに悩みながらも、ふたりはふとしたことで胸が高鳴るような日常を送っていた。そんなある日、娘から噂を聞いて紅茶専門店を訪れたしずかの母は事情を知っているカルマの失言により、ふたりが交際していることを知ってしまう。また、写螺子と鬼木羅もふたりの関係性に言及し、ふたりが恋人であることは公然の事実となっていく。一方で鬼木羅と弁護士･斑糸の関係性も明かされて……。', '2026/01/23 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b69d51ef-1021-4173-b60d-aaed449843ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ed09aad-bac9-40cf-9ceb-efc7ef901135', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 4, '100249621', '暴かせちゃイヤです', 'ある日、透乃眼探偵事務所に透明人間の女性が弁護士の斑糸とともにやってくる。勤務先にある金庫からお金が紛失する事件が発生し、彼女は副社長から完全透明化を悪用した窃盗の疑いをかけられていた。しかし、敏腕な透乃眼探偵事務所の面々と斑糸によって事件は早期解決し、透乃眼は感謝の想いを込めて4人にキャンプ場への慰安旅行をプレゼントする。大自然のなかを散策しながらしずかと透乃眼は憩いのひとときを過ごした。その夜、斑糸は焚火を囲みながら鬼木羅との学生時代のなれそめを語り……。', '2026/01/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0cf666f4-e46f-4ce6-a7ce-fdfa5be1ca14.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a94f60c-09b9-4eb5-b3fa-dc4a701bc84f', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 5, '100252161', '初めてだったので', 'キャンプ場での出来事をきっかけに、さらに親密になったしずかと透乃眼。趣向を変えて雰囲気のいいバーへとデートにくり出したふたりだが、しずかはすっかり酔っ払って自身の恋愛経験の乏しさへの不安を吐露してしまう。透乃眼はそんなしずかに対してやさしく声をかけるのだった。別の日、ゲリラ豪雨に遭遇したふたりはびしょ濡れになりながらも透乃眼探偵事務所へと駆け込む。ふたりは毛布にくるまり、互いの心臓の拍動と体温を感じるようなひとときを過ごすことに……。', '2026/02/06 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1891c5b1-efe2-4747-8138-c02c75138c55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17646988-b56d-46b7-9599-6aefffe90a16', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 6, '100252162', 'わたしの (きみの) 居場所', '潜入調査をおこなうことになった透乃眼探偵事務所の面々。透乃眼は学生服に、鬼木羅は警備員の制服姿に、そして写螺子はメイド服に身を包んだ姿でターゲットの情報を引き出そうと奮闘する。事件解決後、自分にはメイド服が似合っていなかったと落ち込む写螺子をしずかは褒めちぎり、改めてふたりでショッピングの女子会をする流れに。自身の身体の模様にコンプレックスを抱いていた写螺子だが、しずかの言葉に認識を改めてオシャレを楽しむようになっていく。', '2026/02/13 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0a3bbfe-8a3e-46fe-852e-6105937bcf09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abb198cd-2e3d-41e5-b142-b86838f751b7', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 7, '100252163', 'そばにいてほしいです', '探偵事務所の近くにある花屋を訪れた透乃眼としずかは、鬼と人間の異種間夫婦である毛馬内夫婦に迎えられ、親近感を抱く。また、街中を歩いていたしずかはふたりの子どもで、力のコントロールがうまくできずに悩んでいる少年ゆうとも出会い、親交を温める。後日、学校の課題として出された職業インタビューの取材をしようと探偵事務所にやってきたゆうは、好奇心から事件現場に足を運んでしまう。そのせいで凶悪な犯罪者たちと鉢合わせしてしまい……。', '2026/02/20 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/058a19ce-e481-4881-9fa2-3a0c41e8214c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63ca1af1-4db2-419e-8811-f63e34e7c283', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 8, '100252164', 'わがまま、ですよね', '結婚を前提に付き合い始め、まずは同棲しようという話になった透乃眼としずか。なかなか進む気配がない同棲計画に不安を隠せないしずかだったが、ある日の終業後、透乃眼から初めてのお泊りデートの誘いを受けることに。透乃眼の部屋を訪れた彼女はドキドキする気持ちと同時に、過去の女性関係を連想してもやもやする気持ちでいっぱいになってしまう。それでもどうにか前に踏み出そうと、斑糸と同棲中の鬼木羅に助言を求めるのだが……。', '2026/02/27 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/082a5bdf-b215-4a6b-ae7a-28e80ad50f1e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f00002b-c67b-4c6e-b164-22401ed3a014', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 9, '100252165', 'ありのままでいること', 'ドライブの最中に温泉街を見つけた透乃眼としずかは、初めてふたりだけで遠出する。しかし、温泉街を散策しているときに幽霊騒動に遭遇し、宿泊を条件にプライベートで調査依頼を受けることになってしまう。しずかがこれまで縁のなかった温泉を満喫して楽しんでいる間、透乃眼は怪奇現象の調査に取り組む。やがて事件は思わぬ糸口から解決へと向かうが、その過程でふたりは“他種族との付き合いかた”をより深く考えさせられることに。', '2026/03/06 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91b20119-1c2e-48d7-9ac2-d076787d8808.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f80dfc0f-cff7-4394-a090-97d4202d265a', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 10, '100252166', '同棲する前に…', 'パートナーである斑糸のために大量のごみ袋の山から証拠品を見つけ出そうと奮闘する鬼木羅に、アパレルショップに勤める瑞浪と良好な関係を築いていた写螺子。それぞれの関係が前へと進み、透乃眼としずかもお互いの家に泊まりあう関係になっていた。いよいよ同棲を始めるということで、ふたりは報告のためにしずかの自宅へ。同棲に乗り気なしずかの母親･ゆかり、不愛想ながらも歓迎する父親･かおるとは裏腹に、弟･ふうたは複雑な感情を抱いているようで……。', '2026/03/13 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/140d0f85-8a06-4a9f-9144-607a4a91f399.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66cf9546-687b-4e0b-9932-78d8cdb8d079', '7602393c-2c67-4aaf-bb05-6e5a8dcbcbd6', 11, '100252167', '透明人間の里', 'しずかの実家への挨拶を済ませたふたりは、今度は透乃眼の両親に会うべく透明人間の里へと足を運ぶ。商店街でも完全透明化で出歩くことが許されているということからふつうの人であれば戸惑うであろう光景を前に、まったく動じないしずか。彼女は透乃眼の家族にも温かく迎え入れられ、また、彼の幼少期を知る黒霧とも打ち解けた。自分たちをありのままの存在として扱ってくれるパートナーと出会えた幸福を透乃眼は改めてかみしめる。', '2026/03/20 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af5a6156-e8a5-432a-8c33-988b002aac2e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c639bc8d-7de3-49eb-8fc8-8e3acf55a87e', '闘神機ジーズフレーム', '', 'hulu', 'ancient-gs-frame', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6da145a-60a3-4815-89b0-82943253bf72.png?w=331&h=447&p=t', 'hulu', 2021, 3, 1, 'FINISHED', NULL, 126393, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('5f8ed127-8f1f-4815-b5f8-b73fc94c2741', '闘牌伝説アカギ 闇に舞い降りた天才', '', 'hulu', 'akagi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50015623_series_art__338x600_akagi_65c9de098a61b802b5bb9e5255c2b0e0.jpg?w=331&h=447&p=t', 'hulu', 2005, 3, 1, 'FINISHED', NULL, 658, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8dfcc63a-555c-4b82-b474-21a7bb072cf0', '5f8ed127-8f1f-4815-b5f8-b73fc94c2741', 'hulu-akagi-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/85938852-b514-4337-be87-d9385465435b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3839140a-e7c0-4dbd-a1c3-61307f9ae447', '8dfcc63a-555c-4b82-b474-21a7bb072cf0', 14, '60370999', '羅刹の新章', '昭和40年、夏。多摩山中で変死体が見つかる。死因は失血多量だったが身体に外傷が無く、左腕に注射痕があるだけだった。安岡はその死体がかつてコンビを組んだニセアカギだったことから事件の黒幕に気付く。その黒幕とは!?', '2014/09/22 12:00:00', 1340, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/85938852-b514-4337-be87-d9385465435b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dbb004f8-25a1-4caa-8392-4fcf69a56b4a', '8dfcc63a-555c-4b82-b474-21a7bb072cf0', 15, '60370998', '逢魔が時', '怪物狩り。安岡たちの申し出をアカギは了承する。その怪物に自分と同じ匂いを嗅ぎ取ったのだ。その怪物の名前は鷲巣巌。卓越した頭脳と野心で莫大な資産を築き上げ、政財界を支配する日本の闇の帝王だ。鷲巣は賭けの対価としてアカギに血液を要求する。', '2014/09/22 12:00:00', 1340, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5a143d2a-32b7-4ed7-8ae5-48b95b18df2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('bd717a5f-93b3-45e7-834d-3669e6d7075d', '道産子ギャルはなまらめんこい', '', 'hulu', 'dosanko-gal-wa-namaramenkoi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/866c1b63-cc10-48c9-909e-c34bd63d0fd8.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 155963, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a344be1d-7394-4caf-aaf1-2088c41f7fb1', 'bd717a5f-93b3-45e7-834d-3669e6d7075d', 'hulu-dosanko-gal-wa-namaramenkoi-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab2310c1-cdc5-4b3d-bf04-f227974e0696.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd3e7225-7eb3-4f3c-90e0-2045989e6b4a', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 1, '100171843', '道産子ギャルはなまらめんこい', '東京から北海道北見市に引っ越してきた、四季翼。目的地の隣町でタクシーを降り、近所を散策しようとするが…北海道の広大な大地と極寒の中、途方に暮れてしまう。そんな翼の前に現れたのは、“道産子ギャル”冬木 美波だった。道案内をきっかけに知り合った二人は、なんとクラスが同じで、次の日には再会することに! 体も心も距離の近い美波に終始ドギマギする翼だが、休みの日にお家デートに誘われるのだった。', '2024/01/14 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab2310c1-cdc5-4b3d-bf04-f227974e0696.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69d0ab8d-99f9-4cd4-9f2f-614175483463', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 2, '100172265', 'かまくらの中はなまらぬくい', '“北見冬まつり”に美波と行くことになった翼。「これって…デート!?」緊張する翼は、美波から届くメッセージや自撮り写真にお祭り前から浮かれていた。対する美波は少し不安そうな面持ちで…? そしてある日、興味津々な美波が翼の家に来ることに。その道すがら、美波は小さなかまくらを発見し、一緒に入ろうと翼の手を取る。いつも以上の密着にドキドキの翼。その背後から声をかけるのは、偶然その場に現れた翼の祖母だった。', '2024/01/21 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1252c65a-a28b-45f7-a170-0ad5bd0b1950.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('680e92ea-0df3-46e0-952c-dd435594c202', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 3, '100173311', '秋野さんはなまらつれない', '学校の授業でスキーを初めて経験する翼と、対象的に自信満々の美波。二人のやり取りを同じクラスの黒髪清楚ギャル、秋野沙友理がどこか迷惑そうに横目で見ていた。仲良くなりたい美波に反して素知らぬ顔の沙友理。クラスメイトと上手く距離を縮められない美波の姿に驚く翼だった。その後、一緒に練習していた翼と沙友理は打ち解けられないまま時間が過ぎる。だが、休み時間バスに忘れ物を取りに行った翼は、下着姿で汗を拭いていた沙友理に出くわしてしまう。', '2024/01/28 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33bb1dea-c573-4928-9f33-e06e9a09446c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d50dbd8d-7507-4ed9-b5dc-34f26276274c', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 4, '100174111', '夜の電話はなまらもちょこい', '猛吹雪の中、スキー授業で全身筋肉痛の翼は車で登校中の美波に声をかけられる。美波そっくりな母･眞衣が運転する車に同乗させてもらった翼は、親子揃ってギャル、そしてイジり体質を持つ冬木家の血筋を感じながら登校する。スキー授業の一件で打ち解けた翼と沙友理はゲームの師弟関係になっていた。二人を羨ましく思う美波も参加し、三人揃って遊びに行くことに。美波の屈託のない性格に触れ、沙友理の気持ちにも変化が起きていく。', '2024/02/04 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/276b6a82-a5b6-4d16-9ce7-278836efe257.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa944867-e7da-4da6-a0c6-8d278ebdf8c0', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 5, '100174901', 'なまら苦くてなまら甘い', 'カラオケに来ていた翼のクラスメイト達は近づいてきたバレンタインデーの話で盛り上がっていた。美波には決まった渡す人がいないことを知って、何故か安心してしまう翼だった。バレンタインデーには興味が無いと言っていた沙友理だが、後日バレンタインフェアを遠目から見ているところを美波とばったり遭遇してしまう。どうしても翼の顔がよぎってしまう沙友理は美波と一緒にチョコを買うことに。沙友理は意を決してある質問を美波に投げかける。', '2024/02/11 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35d6a467-f4e8-48ec-ba30-7927da6d8472.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea991f83-cd67-408f-bfe7-d3653e0ce39e', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 6, '100175233', '夏川先輩はなまらきりょーよし', '美波の家で期末テストに向けて勉強会を開く翼たち。勉強に熱中するあまり門限を忘れ、慌てて冬木家を出る翼は車で自宅まで送ってもらうことになった。眞衣はバレンタインデー当日の美波の様子や、翼に対して感謝の気持ちを伝える。翌日、翼は登校中に日本人離れした美少女･夏川怜奈と出会う。彼女は学園祭のミスコンで二連覇を果たした、美波が憧れる先輩のようだ。その日の夜、なんと怜奈が翼の家に現れた。怜奈の登場により、さらに波乱の予感が…。', '2024/02/18 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba5e5721-0c6b-4598-8cd7-6c43d38901f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1473ccc2-89d4-40c3-883b-af5b0e01bb9a', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 7, '100176155', '期末試験はなまらゆるくない', '祖母の四季楓から期末テストで十位以内に入れない場合東京に帰らせる、と言われ思い悩む翼のもとに現れたのは、怜奈だった。行き詰まっていた翼は、学年一位の頭脳持つ彼女に勉強を教えてもらうことに。図書委員でもある怜奈の提案で、図書準備室で二人きりで勉強会を開くことになった。勉強会の後、怜奈は「ご褒美」が欲しいと言い出した。その「ご褒美」とは…? そして、翼と怜奈の親しげな様子を目の当たりにした美波は、胸の中にわずかな違和感を感じていた。', '2024/02/25 03:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8eb33ce8-0ef6-45f4-97d1-97a3bb217807.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0b751e8-e773-4ab6-bb84-2c45ab6989ba', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 8, '100176657', 'みんなで焼肉はなまらうまい', '翼と怜奈のデートを目撃した母･眞衣の知らせで、現場に向かった美波と沙友理。楽しげに過ごす二人を遠くから監視する美波は、翼に何を思うのか。映画を楽しんだ後、ヒロインのサクセスストーリーに涙を流していた怜奈は、自身のこれまでの境遇を翼に語り始める。努力をしても全てを認めてもらえないと、もどかしい気持ちを抱える怜奈の話を聞いて、自分の境遇と重ねた翼は、まだ誰にもしたことの無い翼自身の話を語り始めた。', '2024/03/03 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66be1887-0adb-4d0f-ba0c-22aaac166afa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bacbb7a-80a6-4461-80ce-db8ad2c99f04', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 9, '100177421', '網走湖はなまらあずましい', '美波と晴れて仲直り出来たクラスの友人･松尾は、相談に乗ってくれた翼へのお礼として、ワカサギ釣りに連れて行く。釣り場で居合わせた美波も一緒に行動する中、一同はメイクの話題に。将来は美容の勉強のため留学をしたいと真剣に話す美波に、驚く翼だった。後日、風邪をひいてしまい孤独感にさいなまれる翼のもとに、美波が息を切らしてお見舞いに現れた。', '2024/03/10 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33fe8b71-8884-4a86-b6c9-ab52f1fdd2f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c467ca4c-1a98-4993-a000-fe9d7181f3d6', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 10, '100178214', '時はなまら流らさる', '新学期の朝、考え事をしている美波を見つけた翼。いつにもましてグイグイ来る美波と学校へ向かう道中、クラス分けの話題があがると、先程まで元気だった美波の様子が…? そして放課後、「伝えたいことがあるからゴールデンウィークに会いたい」と翼に告げる美波。初めて見る彼女の深刻な表情に黙って立ち尽くすことしか出来ない翼だった。美波が翼に「伝えたいこと」とは一体…?', '2024/03/17 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1ffa1f7-f1de-4634-bd4e-4e0baea367f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f8f7ff02-06e5-4fec-b3ae-691e7edc8ca1', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 11, '100178589', '青春ってなまらえもい', '美波の「伝えたいこと」が気になり、眠れないまま約束の日を迎えた翼は、目的地も知らされず美波について行くことに。寄り道を楽しみながら、美波の秘密の目的地に着いた二人。「何十年後も、一緒に来ようね」と言う美波に、どんな意味で言っているのか…考えずにはいられない翼だった。美波が翼に見せたかったもの、そして「伝えたいこと」が明かされる。', '2024/03/24 01:30:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af91a6db-3030-492d-aef8-65ae612a6d3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('384733cb-95bf-45da-b7b8-dd75af8f595c', 'a344be1d-7394-4caf-aaf1-2088c41f7fb1', 12, '100179332', '君がいないとなまらいずい', '【最終話】海外留学の話をした後、翼と美波は家に帰る手段を失ってしまう。翼の父の紹介でホテルに泊まることができたが、冗談で言っていた“お泊りデート”が本当になってしまい、緊張する二人だが、翼は気が付くと眠ってしまっていた。そして時は経ち、美波の海外留学出発の日が訪れる。美波に今すぐ会いたいのに思うように体が動かない翼は、鞄の中に紛れ込んでいた美波のヘアピンを見つける。「返してあげなきゃ…!」背中を押されたような気がした翼は、美波のもとへ走り出す!', '2024/03/31 01:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce97db8d-9fa9-416f-b97a-8c6458d2f91e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e475c861-66de-45a1-9d85-d2ee9ab514e7', '曇天に笑う', '', 'hulu', 'laughing-under-the-clouds', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50018294_series_art__338x600_laughing_under_the_clouds_6230c2ab6cb8dc1902ef982b78ab28d4.jpg?w=331&h=447&p=t', 'hulu', 2014, 3, 1, 'FINISHED', NULL, 20817, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0cbeb18a-41f5-41dc-8555-84b8dddb3412', '南鎌倉高校女子自転車部', '', 'hulu', 'minami-kamakura-high-school-girls-cycling-club', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/acb7b975-f8fc-4fd2-b307-e7071a9a0fda.jpg?w=331&h=447&p=t', 'hulu', 2017, 0, 1, 'FINISHED', NULL, 21298, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d96ee2e7-9f4e-478d-ade7-a817e130d965', '0cbeb18a-41f5-41dc-8555-84b8dddb3412', 'hulu-minami-kamakura-high-school-girls-cycling-club-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f989b2e6-c67f-41bf-82d7-76a3367c90b7.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c668866-1fe2-4dd6-853a-62e43d7b7a97', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 1, '100101824', '入学式ッ!', '長崎から鎌倉へと引っ越して来た「舞春 ひろみ」は南鎌倉高校の入学式に出席するために自転車で家を出たが、何故か自転車に乗れなくなっていることに気がつく。そんな中、偶然出会った「秋月 巴」と自転車に乗る練習を始めたのだが……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f989b2e6-c67f-41bf-82d7-76a3367c90b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8163399b-9278-47aa-9f08-0906c99ef731', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 2, '100101825', '鎌倉探索にGo!', '自転車に乗れるようになった「ひろみ」は、「巴」と一緒に鎌倉の町を自転車で案内してもらうことに。そこに合流した「森 四季」先生と共に観光していたが、休憩時間に練習をしていた「ひろみ」が迷子になってしまい……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bb30602-157b-43c9-b4fa-3a126363055b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee98f9b8-afbd-482c-8a8d-61b52dd338e5', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 3, '100101826', '女子自転車部、はじめます!', '南鎌倉高校では必ず部に入らなければならないという規則があるため、部活の見学をして行く「ひろみ」達は保健室で一緒になった「神倉 冬音」と祖母で校長の「神倉 龍子」を訪問する。そこで、昔存在したサイクリング部の話を聞き、自転車部を作ろうという提案をする「ひろみ」だったが……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/354303ad-db24-45e5-b1ab-ab8436ad8495.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc1b8751-b6f8-4744-87db-b34c0ce67f23', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 4, '100101827', '夏海ちゃんはわたさない!', '自転車部を作ることにした「ひろみ」達はメンバーの確定と顧問の先生を頼まなければならないことになる。顧問は「四季」先生が引き受けてくれることになったが、メンバーとして入れていた「比嘉 夏海」が水泳部からの強硬な勧誘を受けてしまう。「夏海」をかけて自転車勝負になったが……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af4632e1-42db-4a41-aae0-c5e4dea8a1ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c9c1cd6-11d1-41c0-ae71-9c95d4a20c1a', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 5, '100101828', '自転車を選ぶのってむずかしい?', '自転車部発足にあたって校長先生から「三か月以内に何らかの実績を出すこと。そうでないと部として認めない」という課題が出てしまう。実績をあげるために何をするか? と考える「ひろみ」達。まずは自転車を知り、手に入れることから始めることにするが……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23229226-dd0d-4147-8fa3-aa59c8636350.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4b6a5b2-aea0-4700-8693-921bd6ce73c4', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 6, '100101829', 'はじめてのレース!', '四季先生から提案された実績作りの第1弾は「ナイタークリテリウム」というレースイベント。南鎌倉高校の敷地に設置された1周1kmのコースを10周する初級者クラスのレースだが、スポーツクラブも参加する為かなり過酷な内容に。はたして実績を作ることが出来るだろうか……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09292703-a203-4d3e-a03a-33d43d72ce5c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('585c1a69-e768-4781-813c-0b05d86900af', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 7, '100101830', 'わたしにできること?', '「ナイタークリテリウム」も中盤に差し掛かる中、先頭の「クマ」さんになかなか追いつけずに苦戦している所で2年生、3年生が追ってくる。ところが、「冬音」と「巴」が体力の限界目前になりつつあり、「夏海」も肩が痛み出し厳しい状況になってしまい……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88aa8695-20ed-482c-a937-d2518f560b00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c07b2ff-e764-4ccc-8df4-e8d1c7500176', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 8, '100101831', 'みんなと一緒に!', '「ナイタークリテリウム」もとうとう終盤。巴の作戦で先頭の「クマ」さんに追い着いた「ひろみ」と「夏海」。しかし、肩の痛みが激しくなり「夏海」が離脱。すると、ここで「東」先輩が猛攻をしかけ追い着き、レースは「クマ」さん、「ひろみ」、「東」先輩の三つ巴の戦いに。果たして優勝は誰の手に……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f943236d-0d21-472e-930c-8af9a9d5b234.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73cfb74d-37a6-482c-bc5f-fd1a2c1cb19b', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 9, '100101832', 'クマさんからの挑戦状!?', '学校行事で1年生の部活対抗オリエンテーリングが始まった。鎌倉を探検する内容に一同が楽しみながら散策していると、「クマ」さんが「ひろみ」達の前に姿を現し挑戦状を「ひろみ」に突きつけ勝負を挑まれることに……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/768ed7f7-e33c-461d-b504-b2416406c158.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3e2a283-39c5-4b28-a4bc-bb1a74727214', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 10, '100101833', '輪行で行こう!', '「ナイタークリテリウム」の賞品で「コロネ」が「ひろみ」のロードを作ってくれた。「コロネ」と自転車部のみんなに感謝する「ひろみ」。そして、これからの自転車部の話になり、みんなで輪行という方法で三浦半島にツーリングに行こうとなったのだが……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/738c1a6c-ee62-40ee-9084-d00dfe7e8ae6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97e6af62-236c-457f-adde-098509f01d4e', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 11, '100101834', '自転車って、ふしぎ', '自転車部のみんなで三浦半島の国道をツーリング中にロードに乗った女性三人組に追い抜かれる。それに火がついた「サンディ」が追い着こうと「ひろみ」を誘い「巴」、「夏海」、「冬音」をおいて二人で、三人組に追い着こうとするが……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/616718d5-237f-469a-984d-c24e4d1465d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b171307-46d4-4b91-9b45-53153bfd1586', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 12, '100101835', '道はまだまだつづいてる', '校長の「龍子」に部活動としての三浦半島でのツーリング報告書を提出し、正式な部として認めてもらおうと迫るみんな。だが、報告書を見た「龍子」からは「まだ認められない」と言われ、何が足りないか考える「ひろみ」達。そんな中、「四季」先生から「サンディ」がアメリカに帰ると聞いてしまい……。', '2022/06/26 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5cfa1d4c-b61e-4958-a078-95d3b8bca1f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd578933-8c94-4665-bccf-63797a6735e6', 'd96ee2e7-9f4e-478d-ade7-a817e130d965', 13, '100101836', '来たよ、台湾!!', '【最終話】校長の「龍子」から修学旅行先を台湾にしようと思っていることを告げられ、同時に台湾は自転車先進国としても有数の国なので、修学旅行の下見がてらに、台湾に行ってくるよう言われた自転車部。台湾に着いて早々、「ひろみ」と「サンディ」がはぐれてしまい……。', '2022/06/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4dd71e3-3f87-4c3e-81b4-98d14147b0e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d55cd1be-7d8d-410b-a95b-20e780c96b86', '日々は過ぎれど飯うまし', '', 'hulu', 'food-for-the-soul', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a12bbb42-5834-4ee9-8056-8913ba58d620.jpg?w=331&h=447&p=t', 'hulu', 2025, 1, 1, 'FINISHED', NULL, 185939, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('07f65dd9-9777-4561-af3c-f8f7f224b464', 'd55cd1be-7d8d-410b-a95b-20e780c96b86', 'hulu-food-for-the-soul-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07cfbee1-b9a0-4be8-a58c-01afea751b38.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85fe171e-b937-47a6-8040-a316c1c3e3b3', '07f65dd9-9777-4561-af3c-f8f7f224b464', 1, '100223970', '食文化研究部へようこそ', '一人暮らしを始めた大学一年生の河合まこ。趣味の料理で毎日自炊をしながら、大学生活を送っていた。そんなある日、すごい剣幕でまこに近寄ってきたのは小川しのん。小学校の幼馴染が同じ大学へ通っていたのだ。しのんと一緒にいたのは、比嘉つつじと古館くれあ。三人は新たに作るサークル「食文化研究部」の仲間としてまこを誘う。突然の幼馴染との再会とサークル入部への誘いに戸惑い、思わず断ってしまうまこ。後日、落ち込みながらとある店のショーケースを眺めていると、エプロン姿のくれあが声をかけてくる。この店は、くれあの母親の経営でくれあはバイトとして手伝いをしていた。一人で外食が出来なかったまこだったが、ずっと食べてみたいと思っていたソースかつ丼がテーブルに運ばれてくると思わずゴクリと唾を飲み込み……。', '2025/04/15 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07cfbee1-b9a0-4be8-a58c-01afea751b38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a43a1236-c12b-4a5b-bb61-e4fc0e5353ad', '07f65dd9-9777-4561-af3c-f8f7f224b464', 2, '100224507', '料理したいかも', 'まこが入部した「食文化研究部」。しかし、それはダミーサークルで、しのんが部室をゲットするために適当につけたサークル名だった。まこの期待とは裏腹に、まず最初の活動は、部室の大掃除。遊びながらも片付けも何とか終わり、翌日各自が自分の好きなものを部室に持ち込むことにするが、くれあはテーブル、しのんはゲーム、まこはケトル、なんとつつじが持ってきたのは扉をやっと通れるほどの大きなソファー。まこが持ってきた紅茶でくつろいでいると、事務員さんが活動内容をチェックしにやってくる。活動実態のないサークルはすぐに廃部と聞き、明日までに何か活動がわかるものを見せなければならなくなってしまう。まこが持ってきたケトル以外、調理道具もそろっていない部室で果たしてどうやって活動を証明することに?', '2025/04/22 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0a0a61c-396e-423b-acd4-3da9f436fd3f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3abd370-c83c-4bf1-b499-476704f52948', '07f65dd9-9777-4561-af3c-f8f7f224b464', 3, '100225534', 'お金なくなっちゃった!!', '食文化研究部の仲間とも徐々に打ち解け始めたまこ。週末にみんなでお出かけすることになった。しかし、しのんが泣きながらへそくりのお金をなくしたという。みんなでしのんの家に行き、消えたお金を探すことになったが、どうやらしのんがへそくりを隠した場所がわからなくなってしまったらしい。ヒントになるのは、付箋に書かれた暗号のような言葉……。みんなで謎解きが始まる。晴れた日の朝、集合したまこたちは高尾山へ登山にやってくる。参道のお土産物を見たり、食べ歩きをしたりと楽しい時間を過ごす。山頂へ近づいたころ、見つけたのはモコ太郎の動画に出てきた茶屋で、休憩を兼ねてみんなで昼食を取ることに。まこが頼んだのはモコ太郎が食べていた人気メニューで……。', '2025/04/29 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5de06b21-075f-4365-8dab-97b6ea15196c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88e41b5e-5f5c-4d28-93fd-ae9449cd7083', '07f65dd9-9777-4561-af3c-f8f7f224b464', 4, '100225999', 'この子は星なな', 'ドイツ語の授業が終わり、教室を出ようとしたまこは一人の女の子とぶつかってしまい思わず謝るが、すごい目つきで睨まれて怖気付く。その後、部室で一人くつろぐまこだったが、入り口に人の気配を感じ見てみると、さっきぶつかった怖い人立っていた！どうやら食文化研究部に用があるようで部室に招き入れるが、二人きりでは気まずい雰囲気。隙をみて逃げ出そうとするまこだったがつつじが合流し、彼女は高校時代の同級生で星ななと紹介される。ななはパズル部を作ろうと食文化研究部には入らなかったが、根っからの人見知りが原因で結局パズル部は断念し、この部へ入ろうとやってきたという。新入部員もななも加わり、つつじの提案で土曜日にななとまこの三人で勉強をすることになったが……。', '2025/05/06 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e7da631-6983-4e18-836a-c530ac730276.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8017af4d-c82f-4f1a-8ba2-c8aae2b7e3e0', '07f65dd9-9777-4561-af3c-f8f7f224b464', 5, '100226850', 'ドライブ行かない?', '努力の甲斐あって運転免許を取得したくれあとしのん。5人はくれあのお店の車でドライブに出かけることに。免許を取ろうと考えたことがなかったまこは、くれあから子供のころよく母親に連れられ車で築地に出かけたことが思い出に残っているという話を聞く。最初に運転するのはしのんで、緊張の初ドライブは順調かと思いきや、誤って高速道路に乗ってしまう。高速の出口でうまく出られず、パーキングエリアまで何とか辿り着き胸をなでおろすみんな。今度はくれあの運転で、築地まで足を延ばすことに。新鮮な海鮮が並ぶお店で食べ歩きを楽しみながら食材を買い込み、近くのバーベキュー場でバーベキューをすることになった。海辺近くではしゃぐしのんとななに、火おこしをするつつじ、くれあとまこが調理担当でバーベキューがスタート!', '2025/05/13 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d609b14-8de5-4ba9-8453-f1d57c473e16.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcefea72-dc78-475d-812c-3c4b4b486990', '07f65dd9-9777-4561-af3c-f8f7f224b464', 6, '100227404', 'もしかして私太った…?', 'アウトレットにやってきた5人は、お店でショッピング。まこはスカートを試着してみるが、チャックがあがらない…。ダイエットを決意し、運動もすることに…。', '2025/05/20 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/deaeac2b-7bd3-423f-86c7-ec7cbc1a9738.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5bd089f3-bea8-4ba5-8a23-b8edaa19bb41', '07f65dd9-9777-4561-af3c-f8f7f224b464', 7, '100227894', 'ずっと忘れないと思う', 'いよいよ明日から食文化研究部の合宿。レトロ電車に乗り、あちこちを観光してテンションがあがる5人。しかしバンガローに着くと突然雨が降り出し、予定していたピザ窯が使えなくなってメニューを変更することに。室内では映画観賞をしたりゲームをして、合宿を楽しんで過ごす。そして布団に入ると、つつじはななが起こした高校の頃の思い出の話を始める。くれあにも高校の頃の思い出を訊ねるが、その様子を見ていたまこには少し気になることが……。翌日は晴天になり、キッチンでピザの下ごしらえをするまことくれあ。まこはくれあが寂しそうな表情をしていた理由を聞いてみる。するとくれあの口から語られたのは、まことしのん、つつじとななの昔からの関係で――。', '2025/05/27 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53c4d7cf-6052-4954-b820-c4556389b514.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3270ae86-e8fa-4ef8-b442-b95bc3b629d7', '07f65dd9-9777-4561-af3c-f8f7f224b464', 8, '100228529', 'エアコン…壊れた…?', 'ななの飼っているポチがケージから逃げ出してしまった。ポチが苦手なお姉ちゃんにバレないように支離滅裂なことを話すななだが、ついに事件は起きてしまう…。', '2025/06/03 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e6aedf8-a85d-43f0-9938-f0fee287a9ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('877deb21-5dfe-46a3-9ac3-456fd5b40951', '07f65dd9-9777-4561-af3c-f8f7f224b464', 9, '100229065', '出店してみますか!', '大学祭に出店することを決めた食文化研究部。まこは提供する料理を決めるため、くれあの店で試作をすることに。とりあえずカレーを作ってみるが普通の仕上がりに悩む一同。そこでしのんはさくら先輩に相談して、農業サークルの協力をとりつけるのだった。一方、接客担当のななは人見知りを克服するため、つつじと共に特訓を始めていた。カレーにもう一押しがほしいまこたちはさくら先輩と一緒に道の駅へと向かう。そこで先輩が薦めたのはジビエ肉だった。試作してみた鹿肉スープカレーに大満足の一同。いよいよ大学祭の当日、店の前は人通りがまばらで不安になるまことくれあだったが、つつじとなな、しのんの三人がチラシで呼び込みをかけるとお客さんが集まってくる。スープカレーが次々と売れ始め、味の評判も上々、ついには完売することに!', '2025/06/10 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06fa4362-e807-4082-b745-fa183c20d73b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ac02663f-c629-47bd-a10e-fe71071aa745', '07f65dd9-9777-4561-af3c-f8f7f224b464', 10, '100229589', 'ただいま', '学期末テストも終わり、旅行の計画を立てる食文化研究部。まこの提案で里帰りに合わせてみんなで出かけることに。無事に到着するも長距離を一人で運転をしたくれあは睡魔に襲われノックダウン。みんなで泊まる家はまこのおばあちゃんが使っていた古民家で、かまどや囲炉裏がある素敵な雰囲気。留守番のつつじとななは寝ているくれあのためにお昼ご飯を作ろうと張り切るが、火おこしの仕方がわからず苦戦する。一方、幼馴染に会いに出かけたまことしのんは、ひよりとゆなと再会を果たす。最初は緊張気味のまこだったが、思い出話で盛り上がる。いつの間にか、食文化研究部のことばかり話しているまこ。家に帰り、みんなで食べる釜焚きご飯にお鍋や焼き魚、一つ一つ増えていく思い出にもっとたくさんの思い出を5人で作りたいと思い始めるまこだった――。', '2025/06/17 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2be8d7bb-c3c9-4698-be3c-10050b7b7790.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4da53a9-fee9-471d-9059-402fd138a64f', '07f65dd9-9777-4561-af3c-f8f7f224b464', 11, '100230458', 'クリスマス空いてますか!?', '家で冬野菜を育て始めたまこ。しかし野菜たちに元気がなく、さくら先輩に相談してみる。大学で勉強を終えて帰ろうとするしのん、つつじとななは、鍵を閉められた校舎に取り残されてしまう。事務員さんに見つからないように校舎を出ようとする3人。事務員さんは生徒たちの間で噂になっている「妖怪フード女」の怪談話を笑い飛ばし、校舎を見回っていると不審な人影を目撃してしまう……。ある日、部室でクリスマス会の計画を立てる5人。まこの家でパーティーをすることになった。まこは入念に掃除をして、みんなを迎え入れる準備を張り切る。当日、準備は完ぺきと思ったがうっかり寝坊してしまったまこは、プレゼント用の宅配を受け取り忘れてしまう。落ち込むまこを励ます仲間たち、楽しみにしていたクリスマスパーティーが始まる!', '2025/06/24 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c52e4a21-c627-41e5-adf5-17653410282a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5e786c7-a48a-4625-8551-7d81e1040ff0', '07f65dd9-9777-4561-af3c-f8f7f224b464', 12, '100231331', 'ごちそうさま!!', '【シーズン1 最終話】モコ太郎の動画を見て町中華にやってきたまこ。ボリュームたっぷりの回鍋肉定食に大満足。大晦日、部室の大掃除のために集まった食文化研究部は、初めてこの部室にきたことを思い出しながら作業を進める。こたつもセッティングして写真を整理しながらまったりとくつろぐみんなだったが、年越し用の料理を始める。メニューは年越しそばと手巻き寿司。おなかもいっぱいになって5人で仲良く新年を迎える。しのんの提案で初詣に出かけることにしたみんなは、車で近くの神社に向かう。寒さに震えながらも参拝をすませると甘酒を飲みながらお焚き上げの火を見つめて、この一年の出来事を振り返る。夜も明けはじめ、食文化研究部5人で新年最初の記念撮影をパシャリ!', '2025/07/01 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d10d3bbf-7f8f-4565-84cd-4b0c6ee7782b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('50b59d99-f192-4840-8674-8ffd8984fba0', '日常', '', 'hulu', 'my-ordinary-life', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aaa68cf8-794b-4806-9cfe-696ed170cea9.jpg?w=331&h=447&p=t', 'hulu', 2011, 1, 1, 'FINISHED', NULL, 10165, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b6949c59-0d88-4b46-ae4e-a80ca97f10ce', '50b59d99-f192-4840-8674-8ffd8984fba0', 'hulu-my-ordinary-life-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26b9be0d-ae8a-4c9b-8b17-1eef7a1c6557.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('451371fa-f505-4a94-8320-7faa609dde12', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 1, '100036891', '日常の第一話', 'いつものほのぼのした平日の昼間。いつものゆるゆるとした登校風景。いつもの見慣れた日常が始まるかと思いきや…。突然、大爆発が起きたり、シャケが、こけしが、赤ベコが頭に降ってきたり…。まったく斬新な非日常が始まったのでした。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26b9be0d-ae8a-4c9b-8b17-1eef7a1c6557.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05072965-1e21-4ebc-a57a-760f3cba13a7', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 2, '100036892', '日常の第二話', '長野原みおは、恥ずかしい漫画を描いた学校のノートを、ついうっかり友達の相生ゆっこに貸してしまう。恥ずかしい漫画を見られたくないみおは、ゆっこから必死にノートを取り返そうとするのだが、ゆっこはなかなか返してくれない!!', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4627e28-4b9c-4a28-962c-235c16c43cfd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33cc4380-cc02-4f03-aebf-635ca15068b9', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 3, '100036893', '日常の第三話', '路上に捨てられていた黒猫に興味を惹かれるなの。しかし家には猫以上に世話が大変なはかせがいるため泣く泣くその場を後にするなのだったが、自宅に帰るとそこには先ほどの黒猫が!? どうやらはかせが連れて来たらしかった。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d40ea98a-d926-4c33-a582-ab188224acf6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0400258c-a387-43ab-9566-faef4c4d4f03', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 4, '100036894', '日常の第四話', '学校からの帰宅途中のゆっこと麻衣。二人仲良く土手でゆっくり過ごしている。いい雰囲気の二人。すると突然の麻衣からゆっこへの告白が! どぎまぎするゆっこ。いつもと様子が違う麻衣にゆっこの取った行動は!?', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af6dedfc-1294-49db-8b1c-7e7a5244b002.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d26a5ffd-7c89-47da-be0d-c4a740f3a0dd', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 5, '100036895', '日常の第五話', '非科学的な物を信じられない中之条。恐山に到着した彼は、イタコと出会う。自分の信念を確かめるため、イタコに質問をする中之条だったが、実際は…!?', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba5aa483-9a26-400d-a8e3-87a8bbd6ebbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7ce0d77-81d1-4f1e-9735-3d668770a8a0', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 6, '100036896', '日常の第六話', 'ゆっこ、みお、麻衣の三人は、川辺でキャンプをすることに。早速、みおは飯ごうで御飯を炊き、ゆっこはカレーを作る。ゆっこが出来上がったカレーを持ち運ぼうとした瞬間、事件は起きた!!', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fdf5d095-a869-443d-9caa-6c17ca5d6963.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0594531c-d87e-4ad2-a91b-f3a08b480513', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 7, '100036897', '日常の第七話', '突然の異世界ワールドの展開。ドルフの謀略により囚われの身となった王と姫。王国危機一髪か!? というゆっこの夢のお話です。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc42b2e8-af96-4e53-a9a0-e03eea977e02.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('986886c0-0824-4b6e-9dcc-d9dda7b3a9bc', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 8, '100036898', '日常の第八話', 'いきなりエレベーターに閉じ込められてしまったゆっこ、みお、麻衣の三人。脱出する術もなく、ただただじっとしている三人、と思いきや意外な行動をとる。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe3fd097-b1dd-4404-9457-d4d75b042b15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f1b407a-65fa-46a4-a986-d6191cdafea4', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 9, '100036899', '日常の第九話', 'ある夏の夜、ゆっこはなかなか寝付けないでいた。蚊の羽音がピークに達した時、我慢の限界を超えたゆっこは決意する。蚊との壮絶な戦いが今始まった。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eea7fb3f-5075-45ff-9fac-32fb75926d7c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09951fe0-75c8-4138-ba55-d37eff8dfbaf', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 10, '100036900', '日常の第十話', 'ある休日、安中さんは近所の公園で流し素麺をすると聞いて、ウキウキ気分で出かけた。しかし会場の公園には誰もいない。不審がる安中の前にいきなりおばさんが現れる。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40e594cc-23ab-4528-95da-97e2487e2e0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a84a3bf-0a2d-440f-ace8-d0d4226a42cc', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 11, '100036901', '日常の第十一話', 'はかせが強力のりを発明する。なのと阪本さんにイタズラをするために廊下に強力のりをぶちまける。そこへやってきた阪本さんが見事にハマって大笑いするはかせ。しかし気付くとはかせも強力のりにハマっていて…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09fc84f6-7dfb-4c1b-a687-55bf971db407.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3ef19fd-35d7-4fdd-b82e-f94f8425851b', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 12, '100036902', '日常の第十二話', 'ある休日、安中さんは近所で屋台がでると聞いてウキウキ気分で出かけた。目的は射的。持ち金の500円を射的屋の親父に渡して、銃を構える安中なのだが…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/588ee93a-4f35-402a-b29a-3617115812ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a10d727-ff8d-4cc3-8089-3c5f7f68db90', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 13, '100036903', '日常の第十三話', '嵐の夜に、おしっこに行きたくなって目が覚めてしまったはかせ。だけど怖くて一人でトイレに行けない。何とかなのを起こして二人でトイレに向かうのだが…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b1363c6-4368-4d5e-bcb7-2f73b352fb11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61f48a90-082a-40aa-881c-39e9ff269224', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 14, '100036904', '日常の第十四話', 'ある日、みおはゆっこに昼食の買出しを頼む。しかしなかなか帰ってくる気配がない。昼休みギリギリでゆっこが買ってきたものは、みおが想像もしない意外な食べ物だった!', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dcb8f48-89da-4b98-98d6-0ca4cb302bd0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ef5c5c6-edc9-40d5-a55c-cc0a11078e18', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 15, '100036905', '日常の第十五話', '中村先生は、高性能なロボであるなのに興味を持っていた。何とかしてなのを捕獲しようとあれやこれやと考えをめぐらせていた。そんな時、理科準備室になのがやってきて…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1eb37e49-c285-4069-8a87-2d8b069b87f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7dd9fb26-d623-4b63-990c-559df97e94dd', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 16, '100036906', '日常の第十六話', 'ゆっこが東雲研究所へやってくる。なのはロボであることがバレない様に必死で隠そうとするのだが、それにはお構いなく、ゆっこはすぐにはかせと意気投合して盛り上がってしまう。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e3a67cc-6ef3-4cee-a706-c6064da50cab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e515168f-cc30-419b-92ce-a7cfc49e3126', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 17, '100036907', '日常の第十七話', '東雲研究所に一羽のカラスがやってきた。阪本さんのスカーフをカラスに巻いてしゃべらせてみると、意外に紳士なカラスと仲良くなってしまうはかせとなの。その様子を見ていた阪本さんは?', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1661c8a-7532-4a77-98dd-0db76b9b1a75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7a9b3fb-3dd5-4271-9fad-58b68b348844', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 18, '100036908', '日常の第十八話', 'フェイ王国の飛行船内では、スターラ姫を喜ばせたら金一封というレクリエーションが行われていた。しかしチャレンジに失敗して次々と落下して行く兵士たち。絶望した兵士8番が部屋から抜け出して…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7aed88d4-1761-4955-b465-32fb810c2e43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('783e6c31-9768-4735-ac3c-9755204e1641', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 19, '100036909', '日常の第十九話', 'みおは、走り高跳びにチャレンジしていた。それに付き合うゆっこ。しかし何度チャレンジしてもみおはうまく飛べず、諦めかけたその時、奇跡が起きた!', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/324dc6bf-083a-486e-80fd-f9bcd9f7bdad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40141bcf-3bc9-4e9e-900d-9bc963a7680b', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 20, '100036910', '日常の第二十話', 'はかせとなのと阪本さんは三人でかくれんぼで遊んでいた。絶対見つからない場所に隠れたはかせは、次第に寂しくなって…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76da5c0c-ad2d-4546-bb71-c49898432747.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53f37caa-b4f8-4021-a74b-60cdcaee2ef6', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 21, '100036911', '日常の第二十一話', 'みさとの自宅で、フェッちゃん、ウエボシーの三人はパジャマトークを繰り広げていた。それぞれ好きな人の話題になった時、ウエボシーの口から出たのは意外な人物なのだった。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5b4ab8c-a9c7-47a9-89ce-319bd413bb77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32a3dcb7-476e-4fad-88c1-9962ac652f18', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 22, '100036912', '日常の第二十二話', 'ある日、はかせは阪本さんを引っ張って散歩に出かける。そこでオグリキャップとぴょんを連れた麻衣に出会う。気付くと麻衣だけがいなくなって、犬が苦手な二人は…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd2f529e-2e30-4b8f-bcda-3a3e817ab842.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6717487a-4636-4cdb-9a60-45acade72715', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 23, '100036913', '日常の第二十三話', '桜井泉は、誠の部屋で偶然イケナイ本を発見してしまう。しどろもどろな言い訳をする誠に対して、姉として毅然な態度を取ろうとする泉なのだが…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccb88d3e-c2cb-41e7-bfac-616b27ca2fed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('693a5730-2bad-40cb-b4db-e1c55460ba71', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 24, '100036914', '日常の第二十四話', '阪本さんが風邪を引いてしまう。阪本さんを優しく介抱するなのに、はかせは甘えたくてわがままを言う。はかせと阪本どっちが好きなの? という質問に、なのは…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9eaf7759-7b84-40e6-81ce-e1c7e022a014.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ae6ade6-7bca-4592-9070-92243dce94b1', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 25, '100036915', '日常の第二十五話', '笹原とみさとが腕を組んで歩いている姿を目撃したみおは、ショックのあまり全速力で学校を飛び出してしまう。急いで後を追いかけるゆっこなのだが。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbe1056d-6e79-4465-8e13-4ed3e1be7fe3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7fc55926-a5ed-4d59-b269-21497cfc3d87', 'b6949c59-0d88-4b46-ae4e-a80ca97f10ce', 26, '100036916', '日常の第二十六話', '【シーズン1 最終話】ゆっこ、みお、麻衣は、サプライズでなのとはかせの誕生日のお祝いをするために、東雲研究所へ遊びに行くことになって…。', '2019/07/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b8f1481-181b-4a05-bfd2-0f223bc1cf26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ac194123-e9c7-4bb7-b580-ab2159f5b468', '日本へようこそエルフさん。', '', 'hulu', 'nihon-he-youkoso-elf-san', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccbf0130-afa4-4fe2-b5d5-a8a6575275e9.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 172439, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8b9b6737-74b4-4e37-96e7-18133cc51c0d', 'ac194123-e9c7-4bb7-b580-ab2159f5b468', 'hulu-nihon-he-youkoso-elf-san-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2f68421-53d4-4adb-9f98-e60a9b89daa5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1791e4b-a761-4590-985a-9f7d2e8991fa', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 1, '100212833', 'おはよう、エルフさん。', '普通のサラリーマン･北瀬一廣の趣味は寝ること。夢のなかで幻想世界を訪れることができる彼は、そこで仲良しになったエルフの少女･マリーと冒険を楽しんでいた。しかし、ある日目覚めると、夢の中でしか会えないはずのマリーが隣に!? 驚きと戸惑いのなか、一廣は日本を案内することに。和食に感動し、満開の桜に心奪われるマリー。そんな彼女を見て一廣は優しく語りかける――「日本へようこそ、エルフさん。」', '2025/01/16 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2f68421-53d4-4adb-9f98-e60a9b89daa5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('569bbe3f-39af-4439-b412-cebc46c021f5', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 2, '100213721', 'カツ丼ですよ、エルフさん。', '日本での一日を楽しんだ一廣とマリー。帰宅後、二人は一緒に眠ることで、また幻想世界へ戻れるのではないかと考える。しかし、戻ることができても、そこは遺跡の最深部であり二人を襲った魔導竜の目の前。二人は魔導竜の逸話をもとに「秘密兵器」を用意し、しっかりと抱き合いながら眠りにつく。幻想世界で目覚めたカズヒホが、魔導竜の唸り声が轟くなか取り出したのは……!?', '2025/01/23 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0cfc6d9b-9446-49ee-9460-6f76bdfe4b90.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6522e1cc-1a94-4e7a-8db8-ff0b7cd06961', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 3, '100214485', '失われた魔石', '一緒に眠ることで幻想世界と日本を行き来できるようになり、一廣とマリーは日本での共同生活を満喫中。手作り餃子とワインに舌鼓を打つマリーの姿に、気持ちが和む一廣。一方、幻想世界では、魔石を探しに灼熱のウジャーピーク遺跡へと向かう二人。オアシスの泉から飛び出してきた魔物･クッパーと戦っているカズヒホたちを、物陰から監視する一行がいて――', '2025/01/30 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d44f7c33-8c36-4028-b3b5-9716351d5521.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f023fdd-3266-4d65-8fee-fc572037c056', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 4, '100215229', 'おやすみなさい、エルフさん。', '日本での生活を楽しむエルフの少女･マリー。河川敷で見つけた猫に夢中になり、図書館では司書の一条薫子と出会い、新たな交流が生まれる。家では、手作りパンケーキを頬張りながらアニメ映画に感動する穏やかな時間が流れ、一廣とともに新たな喜びを見つけていく。夜になり、幻想世界のウジャーピーク遺跡で出会った獣人の子供のことが気がかりな二人は、作戦を練り始める。', '2025/02/06 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/805b3fff-b4ed-48f0-b5ef-2f1aa02667da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8df22a7-15dc-40a5-b28a-7809cff55d77', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 5, '100216464', '夢幻剣士', 'カズヒホとマリーは、幻想世界で盗賊団に立ち向かう。捕らわれた獣人の子供･ミュイを救出するため、二人はパーティとして作戦を開始。マリーは精霊魔術で怪物をかく乱し、カズヒホは夢幻剣士のスキルで盗賊団を翻弄するが、盗賊団の頭領は冷徹な戦術で二人を追い詰めていく。激戦のなか、地鳴りと共に再度姿を現した巨大な怪物を目の前にして、ミュイはある決断をする――', '2025/02/13 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f88d581d-8d92-4dc8-81a6-7e8cae78f03d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b61408f-7723-4008-a011-b7c2ed79c9bc', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 6, '100217566', 'フレンチですよ、エルフさん。', '地下迷宮が発見されたことで、アリライ国の街は活気に包まれている。その頃、ナズルナズル遺跡では、かつて出会った「お弁当好き」の魔導竜･ウリドラの卵が千年に一度の孵化の時を迎えていた。一方、日本ではマリーが日本語の勉強に励み、一廣は仕事の合間に迷宮探索への準備を進める。そんな二人が招かれたのは、薫子と夫･一条徹のフレンチレストランでの食事会。マリーは初めてのコース料理に挑戦する!', '2025/02/20 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d46f8640-8a1e-4d79-bf7b-8f6603af4a11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abfff915-c32c-4ad1-b20c-ea4ea1a94a5a', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 7, '100218516', '輝く魔石', '地下迷宮の調査許可証を入手したカズヒホとマリーは、街で暮らし始めた猫族のミュイを訪ねる。そこで魔導竜･ウリドラの鱗を鑑定してもらうと、その身に異変が起きていることが判明。遺跡へ急行した二人を待っていたのは、子育てに奮闘中の魔導竜!? 赤ちゃん竜の世話に疲れ果てた魔導竜を元気づけようと、カズヒホはある約束をしてしまう。その頃、迷宮探索の代理人の座を得ようと、凄腕の魔術師･スヴェンが動き出していた――', '2025/02/27 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1bd9902b-3db8-4931-984a-dd0bd6f4eaa4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31574b72-173f-4af7-a317-2f2d9b1a4918', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 8, '100219313', '日本へようこそ、魔導竜さん。', '魔導竜･ウリドラを連れて、一廣とマリーの温泉旅行がスタート! 一廣が握ったおにぎりを手に、車窓の景色に興味津々のウリドラとはしゃぐマリー。目的地の「秩父」に到着した一行は、ご当地グルメの「みそポテト」を楽しみつつ、いざ温泉旅館へ。初めての大浴場を満喫するマリーとウリドラは、サウナにも挑戦することに。そのなかで、マリーは心にしまっていた一廣への戸惑いをウリドラに打ち明け始める……。', '2025/03/06 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/730da5a0-c096-42c6-a259-858ebbf98ba1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afcf430f-cb4b-4aa2-92dc-46dc15624df9', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 9, '100220319', '天啓と愚直', '幻想世界に戻ったカズヒホたちは、突如、上級魔術師･スヴェンの襲撃を受ける。地下迷宮で巨万の富を得ようと企むスヴェンと、ウリドラから授かった漆黒の剣を手に対峙するカズヒホ。相手の攻撃を記録して回避や反撃につなげるスキル「愚直 (オーネスト)」で立ち向かうが、スヴェンの未来透視能力「天啓 (オラクル)」に苦戦する。スキルの弱点を突かれ、スヴェンの一撃で水中へ沈むカズヒホ。二人の決着は――!', '2025/03/13 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/501b1671-bf92-48f9-b722-680058a36f4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c0849f1-6a6d-497b-8652-f7c07453cc29', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 10, '100221351', '楽しい古代迷宮', '久しぶりに日本で二人きりの休日を楽しむ一廣とマリー。スーパーマーケットで買い物をして、マリーがカレー作りに挑戦する。そして、幻想世界ではいよいよ迷宮探索がスタート! 盾役のウリドラを加え、カズヒホたちは「アメシスト隊」として迷宮へと進み出す。大扉を開け広間に到着すると、突然剣を抜くウリドラ。「わしが相手してやろう。みっちり鍛えてやる!」なにかに怒っているようで!?', '2025/03/20 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/196ef4eb-7a6f-4f70-8d4c-8c31e43507b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc70e697-4f4c-4e81-bfe1-21fa9a4549d2', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 11, '100221968', 'ぶらり青森、二人と一匹。', '楽しみにしていた青森旅行の始まり! ウリドラの使い魔である黒猫と一緒に、東京駅での駅弁選びや初めて乗る新幹線にはしゃぐマリー。一方、一廣は車窓の風景に幼い頃の寂しい記憶が蘇る。弘前に到着した二人は、岩木山を望む雄大な景色を眺めながら一廣の祖父の家へ。おじいさんの作るアンコウの肝や白子が入った鍋とともに、マリーは初めての日本酒を楽しむ。祖父の家での温かなひとときに、二人の絆も深まっていく。', '2025/03/27 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfb39aa1-9f67-432b-b408-d0c5f1d32555.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2a7e4e1-51f8-4a72-9bcc-a8a99d6a6e69', '8b9b6737-74b4-4e37-96e7-18133cc51c0d', 12, '100222724', '桜吹雪ですよ、エルフさん。', '【シーズン1 最終話】青森で過ごす二日目の朝、おじいさんの朝ご飯を堪能した一廣、マリー、黒猫は、近所の温泉へ向かう。地元のおばあちゃんたちと仲良くなり、方言を教えてもらうマリー。その後、弘前城観光に出かけた二人は、舞い散る桜のなかで、瞬間、見つめ合う。二人で過ごす時間が、一廣とマリーにとってかけがえのないものになっていく――。', '2025/04/03 02:30:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55cee70e-8f6c-493d-80db-1f5144143b30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1a696e62-28d6-4fba-b9f3-2c8c7a101947', '忍の一時', '', 'hulu', 'shinobi-no-ittoki', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e8ed512-ca0a-4438-8bae-6c2d7efc41ab.jpg?w=331&h=447&p=t', 'hulu', 2022, 3, 1, 'FINISHED', NULL, 145604, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', '1a696e62-28d6-4fba-b9f3-2c8c7a101947', 'hulu-shinobi-no-ittoki-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afc46899-0ed0-42b9-90c2-3b71bff20537.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df5eade1-cb88-4d75-916c-5d8c176adbea', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 1, '100170741', '青天の霹靂', 'ごく普通の中学生、櫻羽一時は、毎日の習い事と幼馴染、紅雪の監視に嫌気がさしていた。そんな折、後輩の美少女、椿に告白される。人生初めての春に浮足立つ一時だが、母の弓香に交際を止められてしまう。一時はそれでもデートを断行し…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afc46899-0ed0-42b9-90c2-3b71bff20537.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81635d1c-7f2a-4c0d-b9f0-6e24eafa8806', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 2, '100170742', '慈悲なき選択', '突然、忍者になれと迫られる一時。修羅と呼ばれ恐れられる忍者、時貞に諭され、納得できないながらも忍者になることを受け入れる。忍術学園に入学するために、編入試験を受けることになるのだが…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d4ae9e2-c931-4680-9165-1e688e88abfd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25b1cad3-db17-46c2-bc3c-b31c09e4388a', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 3, '100170743', '合縁奇縁', '忍術学園に入学した一時。そこで明るく親切な輝麗、美人でお淑やかな涼子と出会い、学園生活に希望を持ち始める。だが学園には甲賀を頂点とするカーストがあり、甲賀のエリート忍者、朱雀に目をつけられてしまう…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/411ad356-cea2-4ef1-99f5-12026c9ea479.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43c72c60-552d-4df1-8cad-b2b9676186c1', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 4, '100170744', '作り手と使い手', '忍具試験が迫り、試験対策に必死の一時。一方、時貞は甲賀の情報を探るため、雑賀衆を訪れる。雑賀衆は甲賀による下請けいじめに苦しんでいた。時貞は調査のため、甲賀の工場に潜入する。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6df13b4b-d959-478e-9f43-98069be3258e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c011ff3-5b5f-4425-81a3-5d6017a73a97', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 5, '100170745', '痛みの連鎖', '実技試験が近づいてきた。毎年死者が出るといい、甲賀はこれに乗じて一時を殺すつもりだ。殺し殺されが容認される忍者の世界に疑問を抱く一時。朱雀との対決に向け、紅雪とある作戦を練るが…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ee88a99-f803-4adb-bff5-da595ff245d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6712d6db-d32b-4a35-9fe1-03f84801ed2a', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 6, '100170746', '影とぬくもり', '夏休み、一時は伊賀の里に戻る。輝麗と涼子も伊賀に居候することになり、楽しいひとときを過ごす。伊賀の人々の温かさに触れる一時。そんな中、輝麗は朱雀に伊賀の情報を流していた…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58d653b2-3855-4976-8df2-650f7dd69382.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3562b8a3-3a38-4fca-9787-57491c9196a5', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 7, '100170747', '正義はどこにある', '突如、全国の忍の長を集めた忍者大会議が開かれる。弓香、時貞、光蔵が出席。そこには甲賀頭首代行、鬼道の姿もあった。そして安忍長五所川原から、忍者大会議の目的を聞かされる…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/04a8c4ba-4b07-47df-bd6b-f1c3c4a9abb2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37e95abc-830e-43ae-9bac-c09aec57da04', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 8, '100170748', '黄昏は嵐を伴って', '弓香が死刑宣告を受けたことで、伊賀に動揺が走る。頭首代行を任された一時はリーダーシップを試されるが、母が捕らわれたショックでそれどころではない。そんな中、甲賀では恐ろしい『何か』が動き始めていた…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbac81b6-534d-42df-aa1d-2785ea3f4662.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8825d10c-bb66-41a1-99cd-7dafc77d937a', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 9, '100170749', '暁が照らすもの', '伊賀の里に甲賀が攻めてくる。機械忍者『アスラ』を大量投入し、圧倒的な数で伊賀をねじ伏せようとする甲賀。劣勢の伊賀だが、一時が起死回生の策を閃く。一方、弓香の救助に向かった時貞と紅雪は…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4490ee4e-bd1d-4c45-bd82-043dba0cc6e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('628ae35a-21b3-4b56-8256-5a1f472e5e13', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 10, '100170750', '奪われた者たち', '鬼道による侵略は全国に及ぶ。悲しみに暮れる暇もなく、一時は頭首として伊賀をまとめなければならない。そして紅雪は、本当に裏切り者なのか? 時貞の調べによって、衝撃的な事実が明らかになる…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ed8fec6-836e-4410-8641-22ae146826e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7e83da1-1719-4055-a9e7-38fe509b2503', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 11, '100170751', '悔いなき道を', '一時は、秘伝忍核を鬼道に渡す決断をする。それは甲賀への敗北宣言であり、伊賀忍者たちは反発する。輝麗、涼子、朱雀はそれぞれの覚悟を決める。そんな中、伊賀の裏切り者が動き出していた…。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b230fa11-f6f4-47bd-9ff6-31ab41f0cd98.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70ef1909-494c-43f0-9277-dd27e61594c1', '73b19d8b-8a46-4e4d-9b25-5e5e8f0ef469', 12, '100170752', '忍の一時', '【最終話】たった一人、鬼道との決着をつけに向かった一時。そこに時貞、紅雪が駆けつける。鬼道は伊賀の里を殲滅せんと総力を伊賀に送った。忍の一時、最後の戦いが始まる。', '2024/02/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7906f0bc-3502-48a3-8955-1759831351bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a086534c-87b5-41b7-a082-f829430baef5', '忍ばない！クリプトニンジャ咲耶', '', 'hulu', 'shinobanai-cryptoninja-sakuya', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/402b38ac-5d26-45a0-8237-549c9313efa8.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 170041, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1ae26eaa-046a-40d4-9789-9d2b58c7a76d', '忍ばない！クリプトニンジャ咲耶　弐ノ巻', '', 'hulu', 'shinobanai-cryptoninja-sakuya-ninomaki', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23e86b2d-c26f-4892-bcc9-cda85e62df5a.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 172852, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5cafb3b9-b663-4f83-aef6-89367cc3f99c', '1ae26eaa-046a-40d4-9789-9d2b58c7a76d', 'hulu-shinobanai-cryptoninja-sakuya-ninomaki-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/105e99d4-cc67-481d-a094-bc2a0d887742.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f65776ec-3a1c-4b40-afee-60d65504184f', '5cafb3b9-b663-4f83-aef6-89367cc3f99c', 23, '100170775', '鬼道衆', '咲耶の活躍によって鬼道衆の術から開放された狐白。そこに現れたのは死んだはずの…!?', '2024/03/13 01:30:00', 210, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/105e99d4-cc67-481d-a094-bc2a0d887742.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f5c335a-6489-449b-8d98-8fa71424bceb', '5cafb3b9-b663-4f83-aef6-89367cc3f99c', 24, '100170776', '滅びの術', '狐白が甲賀のクリプト絵巻を鬼道衆に渡してしまった…狐白の思惑とは? そして、4つのクリプト絵巻が揃う。', '2024/03/20 01:30:00', 210, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d11518b-e352-4514-8b7e-061c033e47b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4522020-bd71-422a-aa4d-79e819fbedba', '5cafb3b9-b663-4f83-aef6-89367cc3f99c', 25, '100170777', '大団円', '【最終話】配信のコメント欄に助けられた咲耶たちは、見事クリプト絵巻の封印を解くことに成功。ついに滅びの術が発動する!?', '2024/03/27 01:30:00', 210, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/906b244e-7465-4878-b4ea-de4260b869f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b4b0f546-86b7-437e-a553-7023b716c5c3', '忍者コレクション', '', 'hulu', 'ninja-collection', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8552a84d-1a87-446b-9206-d93a2a1fbfc1.jpg?w=331&h=447&p=t', 'hulu', 2020, 2, 1, 'FINISHED', NULL, 120180, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ea742179-39df-4439-a65f-ca45dfd9dd37', 'b4b0f546-86b7-437e-a553-7023b716c5c3', 'hulu-ninja-collection-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/410c1ab5-b8fb-40f8-8d03-9cf0b5eb8d32.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4568cb47-0729-474f-ae99-4b3b10dccc72', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 1, '100096290', '煙', '授業中、ぼんやりと窓の外を眺めていた高校生。見慣れたはずのその風景はどこからか流れてきた煙により一変する。やがてその煙は教室の中にまで流れ込み…。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/410c1ab5-b8fb-40f8-8d03-9cf0b5eb8d32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c697a5eb-e6da-48a7-92c4-e81bc759b080', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 2, '100096291', '嫌な視線', '夜、ひっそりとしたオフィス。残業する女性が突如視線を感じる。だが、そこにいるのは彼女だけ。この邪悪な視線はどこから突き刺さるのか…。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22afd127-d0c2-4aa1-8f24-fe6a03de36e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ffd61f5-bc7e-4ad2-a8ac-9784b9208910', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 3, '100096292', 'ナイトプール', '都心の一等地にあるナイトプールに遊びに来た女性たち。美味しいお酒にお洒落な音楽、華やかなイケメンとの出会いに心躍らせていた彼女たちを、やがて思わぬ恐怖が襲う…。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3239f4d4-40cf-4868-8804-9be51e706f17.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('102982f2-26bc-4114-a71b-1f94e6c2fe2c', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 4, '100096293', '美容師', '商店街の外れにある美容室にやってきた女。そこにはどこか怪し気な美容師が…。友人に起きた異変にこの男が関与しているのか? 彼女はそれを突き止めようとしていた。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e086b94c-a6f4-40e2-8fae-556306ef863a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9aa40e7d-a671-489f-a0a5-c1c3386789c8', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 5, '100096294', 'シミ', 'あるアパートに引っ越してきた大学生の男。破格の家賃に惹かれて選んだ部屋だけに大概のことには目を瞑るつもりだった。だが床に見つけた小さなシミをきっかけにとても見過ごせそうもない事が…。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a37297f-29b1-406a-bf7d-9065f61f96ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d6ad27e-5ff7-4a18-b264-005db6c65b2d', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 6, '100096295', 'ゆらゆらとシュシュ', '他愛もない会話の中で子供が口にした見えない存在。それは子供の空想なのか、それとも…。夜の静まり返った保育園で何かが蠢きはじめる。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e80697ec-450a-499d-b502-4ed23166712d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('acd0f365-0151-4335-8589-8cc0cc5e9239', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 7, '100096296', 'フクロウ', '真夏の熱帯夜に包まれている東京某所。一人の男が、都心の真ん中で一羽のフクロウと遭遇する。男は知らない。それが、自身の運命を狂わせる出会いになると…。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79f05a30-9189-452c-8361-66692b3ad35a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2bc0628-b168-468d-a945-e383fec232fd', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 8, '100096297', '待ち人', '突然の災禍に襲われる幸せな家庭。少女のちいさな命は風前の灯火だった。彼女を救ったのは、一人の男。再び出会うことを願い少女は男を待ち続け、数十年の歳月が流れる。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01953c14-e8fa-4b07-8b69-10b4a03788a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e46df24-5c96-479c-bb55-a05ecf1e29b7', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 9, '100096298', '危篤', '入院中の父親が危篤に。無事を祈り、傍で見守ってやることしかできない家族。深夜の院内で不安に襲われる娘だったが不気味な病室を発見してしまい…。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c46940e5-5a41-421c-a9e8-bb095c6f069f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2310fc09-f28a-4187-b0ac-236ad01a7500', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 10, '100096299', '忘失', 'ある平凡な女性が巻き込まれる不可解な出来事。繰り返される記憶喪失に混乱する彼女。それは部屋に潜む不気味な存在の仕業なのか……。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fe8c629-ace4-4f3a-b5b6-77a879fe3357.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0dce124-3c1b-4903-a74f-f7788831b7cb', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 11, '100096300', '水面', '都会にひっそりと佇む緑あふれる公園。ひと気のない池の水面を見つめる男の姿があった。男は禍々しい気配をにじませたまま静かに誰かを待っていた。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b70fb18d-f936-4312-857f-b55f984462c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f3e5ef58-f7df-4288-8f76-481f62881657', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 12, '100096301', '渇望', '都会の裏路地。敵を斬り捨て始末する忍び。いつもと同じ役目を果たしたはずだった。だが、その夜はそれで終わりではなかった…。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00f03224-ee92-47c6-839f-ebc4e091634e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7fa63723-bb72-40ae-9848-e971cce01535', 'ea742179-39df-4439-a65f-ca45dfd9dd37', 13, '100096302', 'あやとり', '【最終話】仕事に疲れ果て家路をとぼとぼと歩く一人の男。ふと気づけば男の家の前に佇む見知らぬ女の姿が。女が男に向かって差し出した両手には真っ赤なあやとりがあった。', '2022/01/03 00:00:00', 271, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/578a82af-180f-4170-aaa6-385c1ddde359.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0abc0b02-3c92-486d-b3b2-3ce33a279243', '忍者と殺し屋のふたりぐらし', '', 'hulu', 'ninja-to-koroshiya-no-futarigurashi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b12e551-c242-45da-80f8-26624fab502b.jpg?w=331&h=447&p=t', 'hulu', 2025, 1, 1, 'FINISHED', NULL, 177120, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('513cabf0-7284-4822-9319-594ec5d5b4d3', '0abc0b02-3c92-486d-b3b2-3ce33a279243', 'hulu-ninja-to-koroshiya-no-futarigurashi-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95eddda3-7d15-4b1d-9fd6-14c7632f3d69.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eda1763d-ca2a-41d0-8ba8-052edef9f555', '513cabf0-7284-4822-9319-594ec5d5b4d3', 1, '100223966', '忍者と殺し屋の出会い', '「お願いします…何か食べ物を恵んでくれませんか…」 仲間に流されるまま里を飛び出し抜け忍となってしまったくノ一、草隠さとこ。路地裏で行き倒れた彼女は、通りすがりの女子高生古賀このはに助けられる。しかし一息ついたのもつかの間、さとこに追手の忍者が! 絶体絶命のピンチかと思われたその時、あっさりと追手を返り討ちにしたのはまさかのこのはで!?', '2025/04/13 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95eddda3-7d15-4b1d-9fd6-14c7632f3d69.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3ce2db3-71b6-4fc8-95eb-12a910906e7d', '513cabf0-7284-4822-9319-594ec5d5b4d3', 2, '100224797', '忍者と殺し屋の日常', '「わ…すごいお金ですね!!」 このはから初めて「お仕事」の報酬を受け取り色めき立つさとこ。さっそく忍装束以外の服をゲットしにショッピングに向かうふたりだが、さとこは色んなお店を見るも一向に服を買わせてもらえない。そんななかこのはに促されるままひとりでトイレへと向かうさとこだったが、その背後に一つの影が忍び寄る。', '2025/04/20 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31078842-7fc6-4993-b024-fed745d60704.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45b34406-34d2-412e-9dd9-a7e75c2ba937', '513cabf0-7284-4822-9319-594ec5d5b4d3', 3, '100225532', '忍者と殺し屋のお仕事', '「私、バイトしてみたいです!!」 せっかく街に出たからには色々なことに挑戦してみたいと、バイト探しを始めるさとこ。しかし学歴も一般常識も皆無な忍者が面接に受かるはずもない。このはにも手伝ってもらいながらあらゆる経歴を詐称して再挑戦するも、忍者のくせに嘘が下手なさとこは不採用続き。そんななか一本の電話がかかってきて…。', '2025/04/27 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/429fd880-5535-47c5-989c-f090e0100666.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5935e018-8f83-4a40-9bab-cae6e1c72ae0', '513cabf0-7284-4822-9319-594ec5d5b4d3', 4, '100226442', '忍者と殺し屋の関係', '「あの、今日そっちで寝ちゃだめですか?」 リーダーと百合子に影響を受けたさとこは、このはともっと仲良くなろうと試みるが、つれない態度のこのはにただの居候の仕事仲間だと突っぱねられてしまう。仲良しの秘訣をリーダーに相談したさとこは、「モテ」アドバイスを伝授されさっそく実行に移すのだが…。', '2025/05/04 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64a54576-4bc0-4ed9-9793-3e19c0917d3c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5655279-6fda-4ccb-b53c-b4690e8d5459', '513cabf0-7284-4822-9319-594ec5d5b4d3', 5, '100226804', 'ロボットと殺し屋のふたりぐらし', '「オハヨウゴザイマス。オキテクダサイ。コノハサン」 発明家兼殺し屋のマリンによって攫われてしまったさとこ。その身代わりとしてさとこを模したAI搭載型ロボット「ロボ子」がこのはのもとへと送り込まれる。ロボ丸出しのロボ子だが、このははニセモノだと全く気づかない。それどころかさとこを遥かに凌駕する便利機能の数々でこのはにめちゃくちゃ気に入られてしまうのだった。', '2025/05/11 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0eb6235-27d8-4f47-9400-c8669698968b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('819f7da6-de13-41cc-b4e3-df1c18d690c5', '513cabf0-7284-4822-9319-594ec5d5b4d3', 6, '100227402', '巨乳と殺し屋のふたりぐらし', '「そういえばロボ子の葉っぱは回収しなかったね」 ロボ子の一件以来、なんだか気まずいさとことこのは。そんななか、ロボ子の仇だとマリンがふたりに襲い掛かり、ロボットアーム攻撃をくらってしまうさとこ。しかし翌日何事もなかったようにマリン宅へ遊びに赴いたさとこは、そこでなぜか自分の胸が急に大きくなっているのに気が付くのだった。', '2025/05/18 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c65f007-ccd3-4dd7-9c36-0d362ee6293e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('958d1de5-b8cc-455d-950a-be3274308e34', '513cabf0-7284-4822-9319-594ec5d5b4d3', 7, '100227892', '殺し屋とクラスメイトのおともだち', '「そうだ、SNSやってみたら?」 スマホゲームのガチャに夢中のさとこは、プレイしていたゲームのサービス終了を知り落ち込んでしまう。ゲームそのものより、ゲットしたレアキャラを褒めてもらうのが好きというさとこの承認欲求を見抜いたこのはは、彼女にSNSを勧めるのだった。さっそく百合子のアドバイスも受け投稿を始めるさとこだが……。', '2025/05/25 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52486c16-c20a-47a7-9950-af1c7c2c2228.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8421dd82-ce71-4fb5-9f15-a6ed21441027', '513cabf0-7284-4822-9319-594ec5d5b4d3', 8, '100228528', '忍者と殺し屋の大きなおうち', '「家が……」 SNSにすっかりハマったさとこは、他の配信者を煽って怒らせた挙句に実は里の忍者だったその配信者に家を燃やされてしまう。住処を失ったさとことこのはは、マリンに手助けしてもらい新居へと移ることに。しかしさとこはそこでも家の写真をSNSにアップして、速攻で新居を特定されてしまう。', '2025/06/01 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/11f1a995-a05a-4d96-84e6-a2bdc63f50fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('958762fb-b026-416b-9a8d-54773c65c114', '513cabf0-7284-4822-9319-594ec5d5b4d3', 9, '100229147', '忍者と殺し屋と実験', '「このはさん見てください! 新しい忍者服です!」 幽霊騒動も落ち着き、ようやくまともな生活を取り戻してきたこのはとさとこは、まずはさとこの忍者服を新調することに。しかしなかなかしっくりくる服が見つからず、さとこの忍術も調子が出ない。そこで、忍者服を譲ってもらうため2人はある抜け忍のところへ向かうのだった。', '2025/06/08 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cebdf221-790d-4069-81db-aad94a62738d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('627fe1fb-21d5-4d05-b537-a367cb618bba', '513cabf0-7284-4822-9319-594ec5d5b4d3', 10, '100229587', '忍者と殺し屋の赤ちゃん', '「お前のせいでこうなったんだからな。しっかり世話してもらうかんな」 さとこに家を葉っぱにされ大怪我をしたマリンは、さとことこのはが住む家に転がり込んでお世話を受けることに。そこに骨折の回復のために申し込んだカルシウムレディの牛乳宅配サービスが届き、試供品のりんごジュースを飲んだこのはの体に突然異変が表れて……?', '2025/06/15 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6fae01e-b2e6-4e4e-b61e-3fb0dff573ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c12fc513-446c-47a6-b727-5701e5be6587', '513cabf0-7284-4822-9319-594ec5d5b4d3', 11, '100230659', '忍者と殺し屋の大ピンチ', '「じゃあのんびりやっていきましょうか～」 マリンの姉ミナトによる赤ちゃん化事件の影響で、すっかり甘々な性格になってしまったこのは。このはの変化に戸惑いつつも仲良くできて嬉しいさとこだったが、当のこのははこのままでは仕事に戻ることができないと思い悩んでしまう。呑気なさとこの態度に苛立ち、このはは一人飛び出していってしまうのであった。', '2025/06/22 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af0d3323-5016-49fa-951b-4eaf55c609d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d55d7b3b-1725-4eef-863c-03c7122d5e60', '513cabf0-7284-4822-9319-594ec5d5b4d3', 12, '100231330', '忍者と殺し屋のふたりぐらし', '【最終話】「……どうしたんだろ、このはさん」 このはが海外へ特別任務に向かってすでに二週間。お留守番のさとこは、マリンと歯医者に行ったり目を魔改造したりと忙しく過ごしていた。そうこうしている間に、このはからの音沙汰がないまま三週間目に突入し、だんだんと不安になってくるさとこ。そしてまたしてもさとこに魔の手が忍び寄るのであった。', '2025/06/29 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00618907-6798-489e-ac2e-b2ae4951ff10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
