INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4081e37e-f89e-4b9d-bb8b-09e3b2a9268e', 'c7be69bf-8588-427d-924b-abf0b67329ca', 6, '60470863', '2014/07/12 放送回', 'ミー太郎の背番号は、222番。背番号を背中にうまく書けなかったミー太郎が、思いついた方法とは…。', '2014/11/18 12:00:00', 120, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/751192e0-62e3-470b-8f73-19580dd95030.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
