INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e65098e6-ccbf-4010-94bf-0dc6102763b2', 'c7be69bf-8588-427d-924b-abf0b67329ca', 8, '60470866', '2014/08/09 放送回', 'いつもマウンドに立ち、ピッチャーとして大活躍 (?) のミー太郎が、バッターとして、打席に登場!! 果たしてその実力は!?', '2014/12/02 12:00:00', 120, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5a4d1f6d-47ed-4bee-8e2f-03d7b54b8d3f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
