INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0e3e4a0a-a570-45e4-b8c7-050dd0caed03', '猫物語（黒）', '', 'hulu', 'nekomonogatari-black', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af9c38ae-e65d-4fe4-9aa9-8bc07f442a0d.jpg?w=331&h=447&p=t', 'hulu', 2012, 3, 1, 'FINISHED', NULL, 15689, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c62096c2-d72c-418b-b9d0-946ab0e52480', '0e3e4a0a-a570-45e4-b8c7-050dd0caed03', 'hulu-nekomonogatari-black-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87ff702e-e202-4539-ab8f-25ede418462b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8e580ce-9853-4bf5-893e-1a440de76ff9', 'c62096c2-d72c-418b-b9d0-946ab0e52480', 1, '100015787', 'つばさファミリー 其ノ壹', 'ゴールデンウィーク初日の朝。阿良々木暦は、頬に怪我をしている羽川翼と出会う。羽川家の事情について知ることになったが、このことは誰にも言わないでほしい、と翼に懇願されてしまう。', '2024/07/04 00:00:00', 1573, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87ff702e-e202-4539-ab8f-25ede418462b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c0a9362-eeee-4b2f-a779-43e48a6f9766', 'c62096c2-d72c-418b-b9d0-946ab0e52480', 2, '100015788', 'つばさファミリー 其ノ貳', '忍野メメを訪ねた暦。今日翼と一緒に、車に轢かれた「猫」を埋葬してやったことを話すと、メメから今すぐ羽川の無事を確認してくるよう言われる。不思議に思いながら羽川の家を訪ねようとすると、その途中にいたのは…。', '2024/07/04 00:00:00', 1424, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9f91de4-cd67-4862-8861-a5dca1ede937.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cc50506-8146-4b2f-ab1a-4639b58bc217', 'c62096c2-d72c-418b-b9d0-946ab0e52480', 3, '100015789', 'つばさファミリー 其ノ參', '羽川家を訪れ、その異様な光景に逃げるように後を去る暦。その後、障り猫が次々に人を襲っているという噂が世に広まる中、再び障り猫に対峙した暦はついにその目的を知る。', '2024/07/04 00:00:00', 1609, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f416eb3e-7322-4fd1-8fb8-ef11360d8003.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a265e7c-d0a5-49b3-9fe4-eabd4b47d3a2', 'c62096c2-d72c-418b-b9d0-946ab0e52480', 4, '100015790', 'つばさファミリー 其ノ肆', '障り猫に「邪魔をするな」と忠告を受けた暦だが、羽川翼を助けるためある行動に出る。そして、妖刀『心渡』と秘策を携え、障り猫との直接対決に向かった。', '2024/07/04 00:00:00', 1861, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6d48b89-accd-4fa5-b5d6-eb2469f66650.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4da98803-12a5-46ff-9ff4-d0264b2ee8ce', '農民関連のスキルばっか上げてたら何故か強くなった。', '', 'hulu', 'ive-somehow-gotten-stronger-when-i-improved-my-farm-related-skills', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f20ec28f-7f48-4eca-aeaa-9bd8559e0437.jpg?w=331&h=447&p=t', 'hulu', 2022, 3, 1, 'FINISHED', NULL, 145815, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4c6f8d63-1727-48b9-a219-46451ee31375', '4da98803-12a5-46ff-9ff4-d0264b2ee8ce', 'hulu-ive-somehow-gotten-stronger-when-i-improved-my-farm-related-skills-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75a7cd67-773b-4b5b-9e3d-001b528cfcaf.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a664f07c-9343-43d1-b3e9-459e408d1c96', '4c6f8d63-1727-48b9-a219-46451ee31375', 1, '100125493', '超一流農民', 'シルス村で暮らす青年アル･ウェインは農作業をこよなく愛する青年。遂に農民スキルがオール10となり農民スキルが統合され『自然を愛する者へと』進化する。これには幼なじみのテスタもびっくり。そんなある日、野菜の納品のため王都へ向かったアルは、ひょんなことからメイギスの第一王女ファル･イース･メイギスと出会う。そして、この出会いがアルののんびり農民生活を激変させることになるのだった。', '2022/10/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75a7cd67-773b-4b5b-9e3d-001b528cfcaf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26aadef0-c133-4834-adff-8f1abbcae3c2', '4c6f8d63-1727-48b9-a219-46451ee31375', 2, '100125996', '農民とギルド', 'メイギスの第一王女ファルに誘われて冒険者となるアル。さっそく向かったギルドで受付嬢ヘレンと出会う。初めてのクエストは『メルク草の採取』。さくさくとクエストこなしていくアルだったが、オークに遭遇してとんでもない目に! 一方、ヘレンは過去に見舞われたとある事件で記憶を失っていて…。アルの農民兼冒険者生活のスタートは何やら波乱含みだ。', '2022/10/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2424bbfc-a492-4af9-8a39-93cc3de26c29.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d1e3994-dd29-4450-bde2-1b4aad751e2e', '4c6f8d63-1727-48b9-a219-46451ee31375', 3, '100126968', '農民と邪龍ウロボロス', 'グリムの森でウロボロスと遭遇したアルは、ファルと共に調査のためにヘレンの故郷であるホノル村へとやってくる。そして、二人の前に姿を現したヘレンの弟ライの亡霊から、十二年前の事件について聞く。再びウロボロスが現れた目的を知ったアルとファルは、急ぎグリムの森へととって返す。果たして二人はヘレンを救うことができるのか!?', '2022/10/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/867b403d-cb6b-493a-ac57-6f2a8f24424a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('043ffe2d-1017-48dd-8b76-8b63bcfa270f', '4c6f8d63-1727-48b9-a219-46451ee31375', 4, '100127330', '農民と救われた命', 'ウロボロスを倒し、ヘレンを救った! とアルが思った瞬間、あろうことかヘレンに刺されるアル。なんと倒したはずのウロボロスがヘレンを支配していたのだ! アルは亡き弟ライの思いを遂げるためにも、ヘレンの体を傷つけることなくウロボロスを完全に倒すことができるのか? 苦戦を強いられるアル。そんなアルの目の前に、意外な助っ人が姿を現すのだった。『ウロボロス編』完結!!', '2022/10/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a717d763-afa7-4f73-ba40-f7286695ed62.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25aea656-a713-4495-a86d-cc87afc6650a', '4c6f8d63-1727-48b9-a219-46451ee31375', 5, '100128177', '農民とルルグス', '父親ジルと母親ルシカから『たまには帰ってきなさい! 』という手紙を受け取り、久しぶりに両親に会いに行くことにしたアル。グリムの森を通ると、武者修行中だと言うルリに出会い、同行することになる。実家に戻ると、相変わらず息子への溺愛っぷりが半端ないルシカが待ち受けていた。その頃ルリは、ルルグス市街で魔族の調査をしていたのだが…。', '2022/11/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80a09ce4-8f20-4fe7-b799-2f723ee0d843.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6f66a5e-d068-4405-9483-efb147122e91', '4c6f8d63-1727-48b9-a219-46451ee31375', 6, '100128745', '農民と勇者になれない勇者', '魔族であるロキと対峙するアルとルリ。ロキの目的は勇者の子孫であるルリを殺すことだった。魔族調査を依頼したのもルリをおびき出すためだったのだ。アルはルリを守るためロキに立ち向かう。しかし、再生能力を持つロキを倒すことは至難の業だ。そんな時、アルは農民だからこそ持ち合わせていた“ある物”で秘策を思いつく。果たして、その秘策とは? 『ロキ編』完結。アルの熱い思いが炸裂する!!', '2022/11/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/acc7f959-0298-407d-9e58-b85e64c63a19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e365755d-01e6-463d-9d97-38255446dcfd', '4c6f8d63-1727-48b9-a219-46451ee31375', 7, '100129358', '農民と王女の決意', 'ルルグスで手に入れたニガリでトマテを育てるアル。親友のテスタも手伝ってくれている。そんな中、最近、王都では魔物が数多く出没しており、アル達ギルドのメンバーは退治に向かう。すると目の前でアンティスブルクの王子ネディルスが聖剣レーヴァテインを掲げ、魔物を一蹴するのだった。そして、この王子はファルの婚約相手であり、ファルは国のために望まない結婚をすることになっていた。', '2022/11/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fd2658e-3dba-4a7d-8a88-d1832f1041f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9a241739-d1bc-4969-968f-5b64ccecff54', '4c6f8d63-1727-48b9-a219-46451ee31375', 8, '100129885', '農民と結婚式', 'ネルディスの悪事を知ったアル、ヘレン、ルリはファルを救うために、アンティスブルグ国に潜入する。苦労しつつも、なんとか王城に潜り込むことに成功したアルは、ネディルスの悪事を暴き計画を阻止しようとする…。しかし、「メイギスに向け魔物を放った」と言うネディルス。無事にファルを救出できるのか? メイギスではギルドメンバーと近衛兵が総力戦を開始する。果たして!?', '2022/11/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3afe4956-1056-4c0a-9978-0d1398d9db28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3ec6ec0-ac41-428b-a9fd-e684246b56b3', '4c6f8d63-1727-48b9-a219-46451ee31375', 9, '100130768', 'アルの過去', 'トマテの収穫をするアル。この季節になるとアルはいつも思い出すことがあった。それはイルビアという妹同然の少女のこと。幼い頃、アルはテスタとイルビアと三人で楽しい生活を送っていた。しかし、ある日突然、村近くの火山が噴火。思いがけず降りかかった天災によって楽しい日々は一変してしまう。結果、アルはイルビアを……。そしてアルの心の中の棘としてこの思い出はいつまでも残っているのであった。', '2022/12/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f272efed-2cc7-42b5-9154-3cb9d6282cf8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8839d905-01b8-4688-b8ee-fc5cb0839408', '4c6f8d63-1727-48b9-a219-46451ee31375', 10, '100131304', '農民とアシパラの街', '偶然出会ったリネア。彼女は、自分が住むガル街の様子がおかしいので調査して欲しいとギルドに依頼する。さっそくガル街へと行くことになるアル。アルに懐くリネアに嫉妬を覚えるルリとヘレンもこっそり後をつけるのだった。ガル街に到着すると、確かにリネアの言う通り、どこか怪しい雰囲気を醸し出している。街でいったい何が起こっているのか?', '2022/12/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca483f33-6f46-4895-901f-9a0b6d32cfc8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a81b6485-9c00-4e2f-8310-c8405d5681b4', '4c6f8d63-1727-48b9-a219-46451ee31375', 11, '100131832', '農民と魔王城の再会', '野菜の行商の帰りに魔王の娘ユリアに出会い、彼女を助けるアル。ユリアは『魔族の皆を助けて欲しい』とアルに訴える。いったい魔族領で何が起こっているのか? 早々に魔族領へと向かうアル。そこで待ち受けていたのは、ユリアの従者のペドと、アルの母親ルシカだった。「なぜ母さんが?」驚くアル。しかし、ルシカの本当の姿は……アルがずっと想い続けているあの人だった!!', '2022/12/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c39737c-fe2f-465a-95de-74a2091f6b74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4452c7ed-569c-4235-b0c3-561986129026', '4c6f8d63-1727-48b9-a219-46451ee31375', 12, '100132554', '農民と新たな決意', 'イルビアが生きていたことにショックを受けるアル。そして、イルビアの口からアル自身の驚くべき秘密が明かされる。「こっち側に来てくれたら、もっとちゃんと教えてあげる」と言うイルビアに対して、躊躇をしながらも戦闘を開始するアル。激しい戦闘の結末は?', '2022/12/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f62305a-bcd2-4e16-aa33-601eee29d3ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('67a3bf39-ed8e-4056-9895-c42b43ea9018', '這いよれ！ニャル子さん', '', 'hulu', 'haiyore-nyarukosan', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50025015_series_art__338x600_haiyore_nyarukosan_095e56eaf02531dcbfc05bc6e3560953.jpg?w=331&h=447&p=t', 'hulu', 2012, 1, 1, 'FINISHED', NULL, 11785, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('94e32b62-91f3-4e13-8a25-329625904838', '67a3bf39-ed8e-4056-9895-c42b43ea9018', 'hulu-haiyore-nyarukosan-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c51c1a45-f4e9-496f-bb0d-d8b9b8496ff0.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a80832e3-e3e9-493a-9123-89e296f07540', '94e32b62-91f3-4e13-8a25-329625904838', 1, '60670500', '第三種接近遭遇、的な', 'ある夜、八坂真尋は謎の怪物に襲われる。絶体絶命のピンチに現れたのは銀髪碧眼の美少女だった。「いつもニコニコあなたの隣に這いよる混沌、ニャルラトホテプです♪」クトゥルー神話の邪神を名乗る彼女は、真尋を守るためにやってきたという。しかしその仕事っぷりは、真尋を騙くらかして外に連れ出し、アニメショップで自分の趣味のモノを買いあさるなど公私混同はなはだしい。そんな中、謎の怪物から再び襲撃を受ける。はたして、真尋が狙われる目的とは一体…!?', '2016/02/04 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c51c1a45-f4e9-496f-bb0d-d8b9b8496ff0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('236b60b4-d064-47b6-a64f-11882fc5f597', '94e32b62-91f3-4e13-8a25-329625904838', 2, '60670504', 'さようならニャル子さん', '今日も今日とて謎の怪物ことナイトゴーントに襲われる真尋と、それを宇宙CQCで片っ端からなぎ倒して撃退するニャル子。そんな中、後手に回っていたニャル子も攻めに転じると宣言する。敵組織を一網打尽にするべく、闇のオークションが開催される会場があるという敵の本拠地･ルルイエに乗り込む真尋とニャル子。しかし、2人の前に刺客が立ち塞がる。それはニャルラトホテプの天敵、生ける炎･クトゥグアのクー子であった。', '2016/02/04 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b4f67e34-a7ee-4fb0-a6b1-daa0706de770.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2a9740f-d376-48c2-82c0-1fd5cadc87d4', '94e32b62-91f3-4e13-8a25-329625904838', 3, '60670502', '八坂真尋は静かに暮らしたい', '何者かによって幻夢境の神々が殺害された。次の標的はニャル子だという。一方、ニャル子は、なし崩し的に八坂家に居候し、真尋の日常生活、高校生活に這い寄っていく。ニャル子のネタまみれの求愛行動に真尋のイライラは募るばかり。そんなニャル子と真尋の前に、クトゥグアのクー子が転校生として再び現れる。ニャル子と同じく惑星保護機構に就職したクー子は「幻夢境の神々殺害事件をニャル子とのコンビで担当せよ」との指令を受けて地球にきたという。', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6af79bcd-6db3-42e3-832e-dd793ab64695.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96fba1aa-09a5-40c9-a9ad-ca367b57d112', '94e32b62-91f3-4e13-8a25-329625904838', 4, '60670498', 'マザーズ･アタック!', '旅行中だった真尋の母･頼子が、突然家に帰ってきた。宇宙人2人を居候させている言い訳を考える間もなく、いきなり対面する頼子とニャル子たち。慌てふためく真尋。頼子は邪神･ニャルラトホテプの名を聞いた途端、フォークを両手に構え戦闘態勢に。まさか、自分の母親が邪神ハンター!? そんな信じたくない秘密があったなんて! とにかく頼子をなだめようとする真尋だが、緊迫漂う中、家の中にいたシャンタッ君の姿を見つけた頼子は…。', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/306e7b0c-7c40-4972-88fb-938e2ba3b15d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('98ea28d4-cb16-4102-ac37-e193f964175e', '94e32b62-91f3-4e13-8a25-329625904838', 5, '60670493', '大いなるXの陰謀', '真尋たちはハス太こと「風の神性」ハスターと出会う。彼は、父からの依頼で真尋の母･頼子を探しているのだという。やたら親愛の情を示すハス太にイヤな汗をかきながら、真尋はハス太を自宅へと案内し母と会わせる。その時、謎の女･ルーヒーが現れ頼子を連れ去ろうとする。しかも、何事か耳打ちされた頼子は自ら彼女についていこうとする。頼子を取り戻そうとするニャル子とクー子だったが、その戦いの最中なんとクー子までもがルーヒー側についてしまう。一体何がどうなってる!?', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e182e106-8abe-460b-9d56-7dc58688e7d3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93fe16ff-f088-4418-9667-1ab06db6f712', '94e32b62-91f3-4e13-8a25-329625904838', 6, '60670499', 'マーケットの中の戦争', 'ルーヒーたちを追ってルルイエランドに向かうが、行く手を阻む壁としてクー子が立ち塞がる。ニャル子の言葉に従い、母の姿を探して先を急ぐ真尋とハス太。そして、ついにルーヒーと対峙する。ルーヒーの狙いとは…?', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f5de40bf-10fb-4a50-a18e-f44615218496.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('443182a5-246e-4fa8-b03f-8b309ba492d8', '94e32b62-91f3-4e13-8a25-329625904838', 7, '60670496', '碧いSAN瑚礁', '温泉旅行に行くことになった真尋たち。一段とテンションが上がるニャル子の猛アプローチに辟易した真尋は、つい「ニャル子のことがキライ」と告げてしまう。その言葉にSAN値だだ下がりで真っ白になって落ち込むニャル子。さすがに少し言い過ぎたかと感じた真尋は、ニャル子を縁日に誘うことにする…。', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ebe71eaa-7143-4e99-95fe-0fc47fcfca1b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96bb3838-4676-47d2-bc88-4b8e697b6eb9', '94e32b62-91f3-4e13-8a25-329625904838', 8, '60670494', 'ニャル子のドキドキハイスクール', '温泉旅行の最終日、土産物を物色する一行。その途中レトロなおもちゃ屋で、真尋はとあるゲーム機に手を伸ばし起動させてみる。すると一行は突然まばゆい光に包まれて…次の瞬間、真尋は自分の部屋のベッドで目を覚ます。違和感を覚えつつ登校すると、ツンデレ風なニャル子や清楚なクー子、男らしいスポーツマン風のハス太に次々出会い、頭を抱える真尋。呪われた恋愛シミュレーションゲームに取り込まれてしまったらしい。どうする、八坂真尋?', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/853838cd-e6ee-4357-b12d-303027a8615a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fba59d3f-9cd8-496e-b4a2-be4c36f47c26', '94e32b62-91f3-4e13-8a25-329625904838', 9, '60670501', '僕があいつであいつが僕で', '放課後デパートへ買い物に出かけた真尋たち。その帰り道、暮井珠緒が4人の前に現れる。だが、まるでいつもの珠緒とは別人であるかのようだ。その彼女によって、真尋とニャル子の人格が入れ替わるという厄介な状況に…。', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/15beccfa-bed3-4a38-a4a8-29ca7a7200f0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('533f0497-f38f-4a68-b9ab-f7b4a83a3127', '94e32b62-91f3-4e13-8a25-329625904838', 10, '60670495', '超時空の覇者', '人格が入れ替わったまま過ごすことになってしまった真尋とニャル子。その日の放課後、学校を休んでいた余市の見舞いに行くことにした一同。だが、余市の家に着いた時、危険を告げる警報音が突然鳴り響いた…。', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bb5f542d-c153-46a4-ad2b-0ce7a0020fa4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('477b3910-327d-435d-bf9a-12f1e6fa38c5', '94e32b62-91f3-4e13-8a25-329625904838', 11, '60670497', '星から訪れた迷い子', '今日も今日とて大騒ぎの邪神たちに頭を抱える真尋。そんな八坂家に突然女の子がやってきた。彼女はなんと迷子の邪神だという。頼子の頼みで、故郷から迎えがくるまで彼女の面倒を見ることになった真尋たちだったが…。', '2016/02/04 12:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b8893c18-a848-4232-a33e-52ad09270e7e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12d35b57-df68-4d62-949c-5ce39390b108', '94e32b62-91f3-4e13-8a25-329625904838', 12, '60670503', '夢見るままに待ちいたり', '目を覚ました真尋は違和感を覚えていた。いつも騒がしすぎるくらいなニャル子たちの気配が全くしないのだ。それどころか街に人の気配すらなくなっていた。困惑する真尋の前に怪物たちが群れをなして現れた。八坂真尋、絶体絶命の大ピンチ!!', '2016/02/04 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/971b78c0-b6eb-4fa6-a93b-1e4c7d0f4bcf.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c8b36604-ee8d-43d6-b464-9e6a9fe551a2', '這いよれ！ニャル子さん W', '', 'hulu', 'haiyore-nyarukosan-w', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50025016_series_art__338x600_haiyore_nyarukosan_w_800d7e46047e5fd6468de8544499d78b.jpg?w=331&h=447&p=t', 'hulu', 2013, 1, 1, 'FINISHED', NULL, 15699, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 'c8b36604-ee8d-43d6-b464-9e6a9fe551a2', 'hulu-haiyore-nyarukosan-w-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/623193a7-7c98-43fa-b452-08226c9f974f.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70e63172-f590-496d-9b86-414d74e8ac97', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 1, '60671629', '進撃の邪神', 'ごく普通の高校生･八坂真尋の家に居候するクトゥルー神話の邪神、ニャルラトホテプのニャル子、クトゥグアのクー子、ハスターのハス太は、今日も地球のエンタメをガッツリ堪能。ゲームに買い物にコスプレに、真尋をムリヤリ連れ回して…。『怒涛のハイテンション混沌コメディ』魅力をダブルに詰め込んで、あなたのもとへ這いよります!', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/623193a7-7c98-43fa-b452-08226c9f974f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('914002b1-6440-4d4d-bd3f-ee0b0d1586cc', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 2, '60671633', 'セラエノ図書館戦争', '宇宙一の蔵書を誇るプレアデス星団のセラエノ図書館。イベントで手売りされる「ウ＝ス異本」まで取り揃えてあるとか。ニャル子が借りたままだった本の返却に、なぜか真尋まで付き合わされることに。この図書館で働いていたハス太は、真尋にいいところを見せようと張り切って案内するが、その途中、2人組の邪神が忍び込んだ場面に遭遇する…。', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/46ddbb63-d011-4d2d-b09a-09402b68d620.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fedf5e7f-8a39-462a-9103-0565145e75b1', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 3, '60671631', '超邪神黙示録', 'セラエノ図書館を襲った賊は東南アジア･ミャンマーの奥地にある忘れ去られた都市、アラオザルへ逃げ込んだ。それを追って、ニャル子たちは遺跡の奥まで踏み込んでいく。賊は邪神の祭壇に隠された遺産を手に入れることで、宇宙連合の決議を超越する強大な計画を目論むが…。追い詰められた真尋は、ピンチをチャンスにチェンジできるか!?', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cc1c4bee-5dc7-45cb-8e30-9a3f4eb2e504.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e674bd1-39d5-4666-a8ed-1b7e1e0035e6', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 4, '60671627', '恋愛の才能', '「歩くスピーカー」の異名をもつ暮井珠緒は、噂話だけでなく恋愛相談にも定評があり、他校の生徒からも「女装癖のある幼なじみを何とかしたい」などの相談を持ちかけられるほど。そんな珠緒を見込んで、ニャル子は真尋との距離を少しでも詰められるようにアドバイスを貰おうとするのだが…。ニャル子と珠緒の放課後女子会の行方は?', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8ba78adf-f50a-4b55-b7d9-82f8615b3bb4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b39689f3-ad03-4d72-b9fc-fbbc2c4d6d7e', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 5, '60671626', '嘘だと言ってよクー子', '相変わらず八坂家のリビングは邪神たちの溜まり場となって騒々しい。真尋の言いつけで、ようやく自分たちの部屋づくりを始めるニャル子、クー子、ハス太。ただ、油断ならない連中なだけに、真尋はどんな部屋が出来上がったのかと、こっそりチェックに向かう。そんな折、クー子の従姉妹のクー音が、クー子のお見合い話を持って八坂家を訪ねてくる。', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/806ef681-90dd-454d-88dd-1d232baed0d2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e22fa73e-deac-4cb2-b40a-3afe6779a91e', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 6, '60671625', 'エンジテミル', 'クー音を追い返すため、真尋はクー子とのお芝居をしぶしぶ演じ続けることに。しかし、クー音は2人の擬似デートに次々と難癖をつけてくる。恋人同士の目と目で通じ合うかすかに色っぽいニュアンスが感じられ無いとかナントカ。そんな真尋とクー子の婚約者ごっこを見せつけられたニャル子は、とうとう我慢の限界に達し、ついには…!', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ac15a7aa-48f8-4bb7-80d9-1157904d419b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8cac0abc-1167-4b6c-a97a-a237a9b71664', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 7, '60671624', 'プールサイド、血に染めて', '真尋の母･頼子が福引でゲットしたチケットで、プールに遊びに来た真尋たち。ニャル子は、セクシーでコマンドーなすごい水着で真尋を誘惑したり、屋内プールなのにサンオイルを塗って欲しいと真尋を誘惑したり。施設内のたこ焼き屋でアルバイトしていた珠緒は、思い悩む様子のルーヒーの相談に乗ってあげようとする…。', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c12a93e2-f4e1-4f4b-abda-7fddc5a06ad9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8221a250-67fa-433d-abb4-c0701fd7ce3b', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 8, '60671632', '小さな恋のうた。', 'いつもお世話になっている真尋のお役に立ちたいと願うシャンタッ君に、クー子は赤と青のキャンディーを差し出す。それを舐めると、なんと女の子の姿に変身!? シャンタッ君は真尋にご奉仕しようと奮闘するが、ニャル子はなんだか気に入らない。「私のペットがこんなに幼女なわけがありません!」と追いかけまわして…!', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9d1414da-8872-451b-ad30-d60abcf57246.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f88b23c-b72e-490d-99b4-648cf1f17468', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 9, '60671635', 'ハイスクール･オブ･ザ･ヒート', '「八坂家よ、私は帰ってきた!」クー子の従姉妹･クー音は、今まで放って置かれてかなり怒っているようだ。真尋たちが登校すると、校舎は異様なオーラに包まれ、クラスメイトは集団催眠にかかり、人型をした炎が攻撃を仕掛けてきて…。このままじゃ地球が大ピンチ! これはクー音の仕業なのか、それとも…?', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/21e85469-f03e-4bd2-b4ee-966d3811bc9c.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7750dcd-7edf-4c8d-8062-615c2279733a', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 10, '60671634', 'ユゴス･アタック!', 'いつもニコニコハイテンションなニャル子が、風邪をひいて寝込んでしまった。普段よりも少し優しい真尋に、胸キュンのニャル子。そんな時、北極に正体不明の侵略者が現れたと情報が。ニャル子を残して北極へ向った真尋たちが見たものは、巨大な採掘プラントと「ユゴスよりのもの」と呼ばれる地球外生命体、ミ＝ゴだった。', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0c592b91-1a1d-49c8-bcca-68ce0e41455a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('548b5952-ed5a-4e1f-bfc2-c8f82f5cfc21', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 11, '60671628', 'とあるキャンプの悪霊の家', '休日、森のキャンプに訪れた一行。ニャル子がバーベキューで焼くお肉は、真尋が怪しんで食べてくれない。ニャル子の友人のアト子から送られてきたチョコレートも、真尋だけ食べてもらえない。森の中を散策すると、古い洋館を発見。肝試しとばかりに屋敷を探検しようとするが…。いざ開かれよ、新たなる冒険の扉スリー!', '2016/02/11 12:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/66b0253c-741f-4c55-b5ec-3d933f0fd4ba.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a542ff6-1f4d-4c44-90e8-86f71d977a0d', 'c1510e79-e536-4ce0-8c7e-c83b9e8fdc67', 12, '60671623', 'さようならニャル子さんW', '【シーズン2 最終話】惑星保護機構の上司から、幻夢境で新たな蕃神が完成したという報告を受ける。同時に、地球での任務終了が告げられた。それは、真尋とお別れという意味で…。落ち込むニャル子に、とにかくこの目で蕃神を確認しようと、幻夢境に向かうことにするが…。正真正銘のクライマックス! 果たして、ニャル子と真尋の運命は!?', '2016/02/11 12:00:00', 1452, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/55ffd657-980e-41e6-979c-44ce035d573b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1afbb32b-189e-402b-a59e-3c4ffed3b30b', '白い砂のアクアトープ', '', 'hulu', 'the-aquatope-on-white-sand', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fdf6592-f523-4621-bbac-0026c0ca9293.jpg?w=331&h=447&p=t', 'hulu', 2021, 2, 1, 'FINISHED', NULL, 128545, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b7665407-db2e-41fd-b192-1612fd7201b3', '1afbb32b-189e-402b-a59e-3c4ffed3b30b', 'hulu-the-aquatope-on-white-sand-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fd297ac-f022-4816-992f-f98bea9bcee4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcb49997-c97d-424a-a10e-226abe6cc616', 'b7665407-db2e-41fd-b192-1612fd7201b3', 1, '100086828', '熱帯魚、逃げた', '海の生き物が大好きな女子高生･海咲野くくる。彼女の頭の中は、館長代理を務める「がまがま水族館」のことでいっぱい。閉館の危機にある水族館を守るために、夏休み中も仕事に励んでいた。一方、アイドルを辞めた宮沢風花は、あてもなく沖縄へとやってきたが、偶然通りかかった観光協会の久高夏凛に「がまがま水族館」へと案内してもらう。水槽の前で不思議な体験をした風花は、「今、見えてた?」とくくるから声を掛けられる。', '2021/07/14 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fd297ac-f022-4816-992f-f98bea9bcee4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2c65803-974b-45b3-a698-e894383f2766', 'b7665407-db2e-41fd-b192-1612fd7201b3', 2, '100087034', '濡れるのも仕事のうち', '「がまがま水族館」で働くことなった風花は、くくるのおじいとおばあに迎えられ、海咲野家に身を寄せることに。閉館が迫る水族館を立て直すため、夏休みが最後の勝負とより一層仕事へのやる気を見せるくくる。翌日、風花はくくるから水族館の仕事の厳しさを教わりながらも、2人でペンギンのエサやりショーを行うが…!?', '2021/07/21 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef429665-e11d-4ee5-96ac-e22304c2bd8c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a157fbd-b8aa-43a4-9a0e-d57931c0ede3', 'b7665407-db2e-41fd-b192-1612fd7201b3', 3, '100087439', 'いのちは、海から', 'お互いのことを知り少しずつ打ち解けてきたくくると風花。出張でおじいが不在のこの日は、2人でペンギンの体重測定をすることに。風花はエサやり時の失敗を感じさせないほど手際よく仕事をこなしていく。一方くくるは1羽のペンギンの異変に気がつく。命を預かることの重責から不安になった彼女はおじいの帰りを待てず産休中の獣医･竹下に相談するが……。', '2021/07/28 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5746b42b-a7d5-4873-9d42-0caac2b6c2ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f22c90f-40d6-4710-9a11-430297944346', 'b7665407-db2e-41fd-b192-1612fd7201b3', 4, '100087976', '長靴をはいた熱帯魚', '来場者が海の生き物と直接触れ合えるタッチプールの実施が決まった「がまがま水族館」。夏休みの目玉イベント開催に向けてはりきるくくるは、飼育員の屋嘉間志空也や幼なじみの仲村櫂にも手伝ってもらいテキパキと指示を出していく。一方、案内係を任された風花は、人前に立つことを不安に感じつつも懸命に準備をする。そんな時、風花が元アイドルだと知る飼育員･貝殿轟介が休暇から復帰してきて……?', '2021/08/04 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7bd0faf-bb30-457f-bbc2-3a7d21a63673.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28c2bc04-0ff4-42c7-85c3-206558604801', 'b7665407-db2e-41fd-b192-1612fd7201b3', 5, '100088141', '母の来訪', '「がまがま水族館」に娘を連れ戻しにやってきた風花の母･絵里。しかし、まだ帰りたくない風花はくくるの手助けによって母から逃げることに。再び行く当てがなくなった風花は、ふらりと立ち寄った、くくるの友達である照屋月美が手伝うごはん屋「カメ―」である人物と再会する。一方、残されたくくるは、絵里を足止めするために様々な作戦を実行していた。', '2021/08/11 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/295ec5a1-363a-4e51-912a-e2b54db6bb27.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a957ba56-3dd0-45ad-a401-1894af814735', 'b7665407-db2e-41fd-b192-1612fd7201b3', 6, '100088992', 'スイーツラプソディ', '「がまがま水族館」の閉館が8月末に迫り焦るくくる。なんとか状況を変えるべく必死に集客方法を考えるがどれもピンと来ない。そんな時、風花の言葉がきっかけでオリジナルスイーツ作りに挑戦することに。月美の力も借りて、3人は「がまがま水族館」の新たな名物開発に励む。その後、無事メニューも決まり、オリジナルスイーツ作りは順調かに思われたが……。', '2021/08/18 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26218f55-ee1c-4240-8327-3bedff2b4e8a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8d614c3-edca-41f6-9845-afae4e1c1ddb', 'b7665407-db2e-41fd-b192-1612fd7201b3', 7, '100089538', 'アイスで乾杯', 'くくるたちの努力の甲斐もあり、来場者数が増えてきた「がまがま水族館」。結果が出て喜ぶくくるは、閉館阻止に向けてより一層はりきる。だが無茶な提案をしたことで、空也と揉めてしまう。その様子を見かねたおじいは、飼育員たちに息抜きのための休暇を与える。翌日、夏凛や月美も加えて海にやってきた一同。バーベキューや海の遊びで休みを満喫するくくるだったがそこにもう一人加わって……?', '2021/08/25 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/343c5848-2e3a-4f3c-a13a-916f6e335104.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5dac4f4a-111e-4d8a-a19a-557fa19d80c6', 'b7665407-db2e-41fd-b192-1612fd7201b3', 8, '100089940', 'crab crisis', '夏凛の尽力で生き物を連れて出張をする「移動水族館」の開催が決まった「がまがま水族館」。当日、会場となる病院で準備を進める飼育員たち。その途中、看護師長･金城の元に挨拶に向かうくくると夏凛。だが金城の言葉がきっかけで2人は気まずい雰囲気に。一方、準備を進める風花は持ち込みを禁止されたカニが水槽内に紛れ込んでいることに気が付く。病院の関係者に見つかる前に隠そうとするが!?', '2021/09/01 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5f17bfa-0983-4551-99a6-e92c9d73237a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1addb818-ebd3-4aab-9bb4-14521f1b4c50', 'b7665407-db2e-41fd-b192-1612fd7201b3', 9, '100091051', '刺客のシンデレラ', '建設中の水族館「アクアリウム･ティンガーラ」から研修のためにやってきた新人飼育員･南風原知夢 (はえばるちゆ)。おじいの指示で彼女の教育係を任されたくくる。だが新たな水族館を認められないくくるは知夢をライバル視し、試すような態度ばかりとってしまう。その後も打ち解けられずギクシャクする2人は、風花と一緒にペンギンのお散歩を始めるが……?', '2021/09/08 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/530da327-da6c-462d-8468-5b3c54d63a1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb3195c6-9022-42e4-b12b-71a511be34b5', 'b7665407-db2e-41fd-b192-1612fd7201b3', 10, '100091349', '置き去りの幻', '閉館の時が迫り、一発形勢逆転のアイデアを探すくくる。以前、風花も目にした水槽の幻を宣伝しようと提案する。だが、夏凛たちから不確かなものは宣伝できないと反対されてしまう。それでも諦めきれないくくるは、幻が確実に見える方法を探し始める。一方、風花は自身に映画主演のオファーがきていることを知り悩んでいた……。', '2021/09/15 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3684ae9d-38a3-4809-bae1-0de0309bc76e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('420fb165-ee0e-4756-9f3b-4d3d62ca4285', 'b7665407-db2e-41fd-b192-1612fd7201b3', 11, '100091964', '籠城の果て', '南城市に台風が迫る8月のある日。閉館反対を訴えるため、くくるは1人で「がまがま水族館」に立て籠もってしまう。彼女を心配した風花が駆けつけ一緒に立て籠もる。だが、進路に悩む風花に対して、くくるは素直になれずそっけない態度をとってしまう。そんな中、激しさを増す台風によって停電する水族館。2人は水槽や生き物に異常がないか見て回る。', '2021/09/22 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63a537fa-ef5f-47df-905b-d0b273a17eab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b0c2564-6a78-404e-8147-2a1a12e2e354', 'b7665407-db2e-41fd-b192-1612fd7201b3', 12, '100092396', '私たちの海は終わらない', '営業最終日、「がまがま水族館」には多くの客が訪れていた。その様子に満足げなくくるたちは、最後の思い出を作りつつ今日も仕事に励んでいた。たくさんの人の笑顔と賑わいの中、ちいさな水族館は閉館する。その日の夜、お互いの進路について話すくくると風花。彼女たちの決断とは……?', '2021/09/29 00:30:00', 1418, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7945856d-cdfb-4c04-a53c-878e6da264e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08f95658-c004-4b60-bbf2-80a3fcf06a18', 'b7665407-db2e-41fd-b192-1612fd7201b3', 13, '100092800', '海の遙かなティンガーラ', '「がまがま水族館」の閉館から月日は流れ、翌年の春。高校を卒業したくくるは「アクアリウム･ティンガーラ」に就職する。新たな職場でも飼育員を希望するくくるだったが、なぜか営業部に配属されてしまう。気持ちの整理ができないまま、配属先に向かったくくるを待っていたのは、副館長･諏訪哲司だった。さらにかつて「がまがま水族館」に研修で来ていた知夢と再会して……。', '2021/10/06 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b10b7d7e-f637-44db-8e4a-14b799e142d4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4660d254-e3b2-4571-8114-4f748c31d55c', 'b7665407-db2e-41fd-b192-1612fd7201b3', 14, '100093926', 'ペンギンチェイサー', '仕事が上手くいかず落ち込むくくるに声をかけたのは、沖縄に帰ってきた風花だった。諏訪からバックヤードツアーの準備を任されたくくるは、1週間後の開催に向けて知夢や同僚の島袋薫たち飼育員に協力をお願いして回る。一方、くくると同じく「アクアリウム･ティンガーラ」に就職した風花は、「がまがま水族館」での経験からペンギンの飼育を担当することに。そこでチーフの知夢からテストを出される。', '2021/10/13 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b9b7b79-f9b8-4dfd-a788-03f59c762053.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30ae1ce5-768f-4891-a36c-002be17e6c43', 'b7665407-db2e-41fd-b192-1612fd7201b3', 15, '100094470', 'ウミウシ大論戦', '急遽、実施が決まった企画展示のアイデア出しを諏訪から命じられたくくる。風花の「生き物のことを知ってもらうチャンス」という言葉をきっかけに前向きに取り組むことを決める。翌日、諏訪に様々な企画を提案し、その中からウミウシの展示企画が採用される。しかし、飼育難易度が高いウミウシの展示には多くの問題が待ち構えていた……。', '2021/10/20 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/777cde09-135d-4c36-9a5c-55cbc3045b4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1acac2b5-b36b-4a7e-8c6c-361caf08b67b', 'b7665407-db2e-41fd-b192-1612fd7201b3', 16, '100094745', '傷だらけの君にエールを', 'ペンギンの卵の孵化が近づく「アクアリウム･ティンガーラ」。新たな命の誕生を見守るため、泊まり込みで孵化を見守ることになった風花たちペンギン担当の飼育員。だがなぜか、知夢だけは泊まりのシフトを免除される。知夢だけ特別扱いされていることが納得できないくくる。しかし、飼育部長･雅藍洞凡人から知夢が周囲に隠しているある事情を聞いてしまい!?', '2021/10/27 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05dcccf3-7e8d-4c33-b6d0-e3d4a478b640.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bedcaadc-1f06-47ff-bf68-d11db2e1caa1', 'b7665407-db2e-41fd-b192-1612fd7201b3', 17, '100095245', 'くつろぎ処 海月風', '久しぶりに休みが揃ったくくると風花と月美は、「アクアリウム･ティンガーラ」の職員たちとの親睦会を開催することに。やってきたアルバイトの真栄田朱里や、飼育員の米倉マリナに料理をふるまい、もてなすくくるたち。その後、勤務明けの知夢や薫も合流し、さらに空也、櫂、同僚の比嘉瑛士も加わり、賑やかな休日を楽しむ。', '2021/11/03 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7ed4736-d921-476f-bb8f-9038bb9b0ed7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f508431a-697f-47c6-9371-12de4ef2f2d6', 'b7665407-db2e-41fd-b192-1612fd7201b3', 18, '100095539', 'あかりの灯るとき', '朱里が発案した職員たちが海の生き物に関するコスプレをして接客する「コスプレイベント」の実施が決まった。しかし諏訪の判断で、アルバイトである朱里に代わりくくると夏凛が準備を任される。くくるは朱里にも水族館の生き物たちを好きになってもらおうとするが、朱里は今一つ興味を持てないでいた。そんな中、イベント開催前日の夜、配付予定の魚のシールが発注されていないことが判明して!?', '2021/11/10 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36705330-8784-4401-aa3b-3d980ff8786a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15ef38bb-53d2-48e9-a81d-aee5449c3b8c', 'b7665407-db2e-41fd-b192-1612fd7201b3', 19, '100095901', 'さよならハイヒール', 'ペンギンの雛の密着ドキュメンタリーの撮影が決まった「アクアリウム･ティンガーラ」。撮影前日、下見のために番組撮影クルーと風花のアイドル時代の後輩･城居ルカがやってくる。後輩との再会を喜ぶ風花だったが、その場にいたディレクターの提案で、ルカと共にレポーターとして番組に出演する流れに。断ろうとする風花だったが、どこか不安げな様子のルカを見て……。', '2021/11/17 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43b21d5e-364a-49d2-9be5-c93dafcfbc80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26ec67db-3a73-49d8-9e2f-b691790f6e41', 'b7665407-db2e-41fd-b192-1612fd7201b3', 20, '100096413', '迷子のプランクトン', '新エリアオープンにむけて、膨大な量の仕事に追われるくくる。そんな中、空也から近くの海岸に野生のイルカが迷い込んだことを聞く。早速、様子を見に行くと、同じくイルカを見に来ていたおじいと鉢合わせる。その場で、もうすぐ「がまがま水族館」の解体工事が始まることを聞き、ショックを受けるくくる。しかし、気持ちの整理をする間もなく、諏訪から新たな企画を任されてしまい……!?', '2021/11/24 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd9fdaa1-00fe-4f37-812d-ffdc3c6d3d0e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0438172e-ffd4-4cd8-a612-e3fe5adce98c', 'b7665407-db2e-41fd-b192-1612fd7201b3', 21, '100097139', 'ブルー･タートルの夢', '仕事が上手くいかず、さらに解体された「がまがま水族館」を目にしてショックを受けるくくる。翌日、無断で仕事を休み離島へと足を運ぶ。そこでウミガメの研究と保護活動をする轟介の妻･具殿岬と出会ったくくる。岬の仕事を手伝いながら、ウミガメの孵化を見守ることにする。一方、くくるのことが心配で仕事に集中できない風花。そんな中、飼育担当のケープペンギンたちに異変が起こり……。', '2021/12/01 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d314936-38e1-46b7-b4b6-c2600aa90a38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fb49ddc-bd00-4889-b458-c3a184c1e189', 'b7665407-db2e-41fd-b192-1612fd7201b3', 22, '100097762', '覚悟の帰還', 'ウミガメの孵化を見届けたくくるは、気持ちを新たに「アクアリウム･ティンガーラ」へと戻る。そんな彼女を夏凛と朱里は温かく迎え、諏訪は引き続き、新エリアを使った結婚式の企画を任せる。結婚式にふさわしいアイデア出しに悩むくくるは、知夢たちにも協力してもらい、ついに企画書を完成させる。そして、迎えたウエディングプランナー･三浦へのプレゼン当日。果たして、くくるの企画は通るのか!?', '2021/12/08 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/509140f6-13b8-47eb-8caf-5c747b4012f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e83785f7-4079-4d47-bd31-3b562177ef7c', 'b7665407-db2e-41fd-b192-1612fd7201b3', 23, '100098504', '水族館の未来', '星野から、海洋生物の研究や環境問題に取り組む大型プロジェクトが発表される。以前、岬から環境汚染が原因でたくさんのウミガメが命を落としていることを聞いた風花は、強く心を惹かれる。だが、参加条件がハワイでの2年間の研修と言われ、くくると離れたくない風花は参加するか悩む。一方、飼育部への移動について、星野と面談をするくくる。その場で諏訪の過去を聞いて……?', '2021/12/15 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9173cdba-9cdd-450e-a981-b5534c2fefef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97aeb8ae-f7ac-487e-b6f0-317deae35cf6', 'b7665407-db2e-41fd-b192-1612fd7201b3', 24, '100099024', '白い砂のアクアトープ', '【シーズン1 最終話】くくるが企画した結婚式と新エリアのプレオープンを目前に控え、準備に励む「アクアリウム･ティンガーラ」の職員たち。一丸となって準備した甲斐があり当日、会場は新郎新婦や来場者の笑顔が溢れる。無事、大きな企画を終えてここで一度、別々の道へと歩むことになるくくると風花。新たな道へと踏み出す2人に再び、優しい奇蹟が起きる……。', '2021/12/22 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a36b968-1575-4f48-81ad-7585131608fa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9c90bfdb-c240-4f33-9cf1-4f67c93b5073', '白聖女と黒牧師', '', 'hulu', 'saint-cecilia-and-pastor-lawrence', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7991afd7-3363-4118-99d1-ff32526f3ced.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 150972, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('107bee47-2aa2-4ca4-bea8-32469c71f861', '9c90bfdb-c240-4f33-9cf1-4f67c93b5073', 'hulu-saint-cecilia-and-pastor-lawrence-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e66f669-8b73-4fb8-a798-8ac19ac9a733.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72f22e37-72d8-4f61-95a1-4ad199b67b37', '107bee47-2aa2-4ca4-bea8-32469c71f861', 1, '100152300', 'ふたりの関係', '教会にやってくる人々を優しく導く聖女･セシリア。しかしいつも街の人が帰った途端、聖女らしさが消えた素の姿でだらけてしまう。そんなセシリアをつい過保護に甘やかしがちな牧師のローレンスは、セシリアが密かに寄せる想いに気づく気配すらない。ローレンスと街へ向かう日は、二人でのお出かけにウキウキと上機嫌のセシリア。ところが、行く先々で待ち受けるハプニングの数々にセシリアの恋心は振り回されて……!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e66f669-8b73-4fb8-a798-8ac19ac9a733.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e2461d6-50c3-46db-b254-04206a089689', '107bee47-2aa2-4ca4-bea8-32469c71f861', 2, '100153307', 'ふたりの守るもの', 'ある朝、突然ローレンスの友人･アベルが訪ねてきた。しばらくこちらの教会で働くつもりだというアベルと、本気で取り合おうとしないローレンス。友人へのフランクな態度にローレンスの新たな一面を感じてドキドキのセシリアは、二人のやりとりにちょっとジェラシーも。そんな中、ローレンスにあるトラブルが発生してしまう。大慌てのセシリアに冷静にアドバイスするアベル。実はアベルには、人には内緒にしていることがあって……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe4f924e-a2ba-4f21-8385-9b8cb790e898.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e633807-a679-4e0c-88bc-d8baf0554308', '107bee47-2aa2-4ca4-bea8-32469c71f861', 3, '100153781', 'ローレンスの気がかり', '雨に降られてずぶ濡れで帰ってきたアベルが、翌日熱を出して寝込んだ。大丈夫だと言うアベルを押し切って、病人を一人にはしておけないから自分が看病するのだと張り切るセシリア。そんなセシリアの様子にローレンスは謎のもやもやを感じるけれど、それが何なのか自分でも分からない。しかし、セシリアがアベルのそばで無防備に寝ている姿を見たローレンスは、セシリアに対して思わずそっけない態度をとってしまって……!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d48b5a30-85bf-4141-a180-02f9ce1045f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50279149-5fa7-4d1f-ba58-a81d46955d86', '107bee47-2aa2-4ca4-bea8-32469c71f861', 4, '100154686', '聖女と呼ばれるもの', '教会でローレンスとアベルが話していると、誰かが扉を叩いた。応対しようとしたアベルは、来訪者の姿を見るやいなや急いで扉を閉じるも阻止に失敗! むりやり入ってきたのは、家庭教師であるアベルを探しに来たという名家の娘･ヘーゼリッタだった。この街の聖女を見るのも目的の一つだと語ったヘーゼリッタは、ローレンスに対してなぜかトゲのある物言いをする。その理由は、彼女とある人物にまつわる過去の出来事にあって……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daa4aed5-28d0-4fda-8029-6640381ad6b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('002fd3d7-9ee6-4283-87d7-082fccbeb88c', '107bee47-2aa2-4ca4-bea8-32469c71f861', 5, '100155461', 'はじめての出張', '足を悪くして教会に来られなくなった女性･カリーヌを訪ねることになったローレンスとセシリアたち。これまで遠出する機会のなかったセシリアは初めて見る湖に大はしゃぎ! けれどアベルだけはひとり何かを感じていた。カリーヌの相談によれば、妖精が住むとも言われるその湖から、夜になると誰もいないのに話し声が聞こえるらしい。話を聞いたローレンスが一人で夜の湖を訪れてみると、突然誰かが袖を引っ張って……!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35cae6b4-1558-4522-a570-b017a0b44a47.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d78a42c4-88fe-4f5b-90e7-88982f2c192d', '107bee47-2aa2-4ca4-bea8-32469c71f861', 6, '100156128', 'アベルとヘーゼリッタ', '街でローレンスの用事が終わるのを待っていたセシリアは、人手が足りず困っていた喫茶店をなりゆきで手伝うことに。聖女様による接客とあってお客さんには大好評だったけれど、セシリアがアルバイトをしていると聞いたローレンスが平静でいられるはずもなく……!? またある日、アベルのもとに一通の封筒が届いた。中にはセシリアが熱望していたあるものが。それを見たローレンスは、アベルとの神学校での思い出を語りはじめる。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24e04877-a0e0-45b4-a010-691397b4f257.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5966e627-1868-40cc-87a9-aaddfdbde0c5', '107bee47-2aa2-4ca4-bea8-32469c71f861', 7, '100156604', 'セシリアのなやみごと', '最近ローレンスの様子がおかしい、何かかくし事があるのでは……と泣きべそをかくセシリアのために、ヘーゼリッタが立ち上がった! アベルも巻き込み3人で、今日もこっそり出かけたローレンスの尾行を開始。ところが街では予想外の事態が起きて……!? 一方、牧師の定期会議をずっと欠席していたローレンスに、ついに呼び出しの手紙が。セシリアやアベルたちも連れ立って、ヘーゼリッタの実家がある西の街への旅が始まる。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4bef9968-7144-4133-aa47-6f14be812f4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8256c2a0-5582-4d03-b873-da35c3bb6aed', '107bee47-2aa2-4ca4-bea8-32469c71f861', 8, '100157318', 'フレデリカの遺したもの', 'ヘーゼリッタの兄･ギーゼルベルトは、愛する妹の友人ならばとセシリアたちを豪華ディナーでもてなす。翌日はヘーゼリッタの計らいで、ローレンスと二人きりで街の散策を楽しんだセシリア。みんなと合流しランチで初めての味に感激している中、セシリアはふとローレンスの不調に気づく。とある庭園の横を通ってから頭が痛むというローレンスの話を聞いて、ハッとするアベル。そこは、ヘーゼリッタにとって忘れがたい場所で……。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d077f41-bebd-4e50-8f23-2660694a155e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('20fb4b10-0a0f-49b4-b7fc-50e9ce4017fb', '107bee47-2aa2-4ca4-bea8-32469c71f861', 9, '100158150', '聖女の加護', 'ギーゼルベルトの部屋で、フレデリカ聖女の写真を見つけるセシリアとローレンス。聖女のことはきちんと知っておきたいというローレンスに、セシリアとギーゼルベルトは改めて“聖女”と“聖女が与える加護”について説明する。セシリアたちが帰る前日、ギーゼルベルトは盛大な送別パーティを開いた。メイドたちの手でおめかししたセシリアを見たローレンスの反応は。そしてローレンスの友人･カミラがセシリアを質問攻めに……!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10d4f580-6400-4fd3-be20-b5b748eda4cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a848aa6-b4e4-4768-ab96-085eccb94cb0', '107bee47-2aa2-4ca4-bea8-32469c71f861', 10, '100158715', 'ふたりの気持ち', '西の街から戻ったセシリアたち。しばらく家を空けたためローレンスは何かと忙しそうで、全然一緒にいられないセシリアはしょんぼりしていた。その夜セシリアが寝付けずにいると、やっと二人で過ごすチャンスが。ところが、ソファでくつろいでいるとドキドキのアクシデントが発生! 翌日、ローレンスの顔が見られなくなってしまったセシリアと、そんなセシリアに戸惑うローレンス。二人のぎこちなさは街の人も気づくほどで……!?', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/850cd035-633c-4955-8cf7-9af70ce391df.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9dce4cf-243a-4f43-9b94-d73ba1f37b2c', '107bee47-2aa2-4ca4-bea8-32469c71f861', 11, '100159723', 'ふたりの出会い', 'またセシリアたちの街で暮らすことになり、新しく部屋を借りたアベルとヘーゼリッタ。セシリアとローレンスが二人でいる時間が増えれば関係が進展するのではと期待するヘーゼリッタは、アベルにも行動するようけしかける。しぶしぶ探りを入れたアベルは、ローレンスとの会話の中である変化を感じて……。一方のローレンスは、セシリアとの向き合い方に頭を悩ませつつ、初めてセシリアと出会った日のことを思い出していた。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4c08ef8-46e0-45ea-bd7c-edbabefc48a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c91d84ee-de8f-48e9-a813-fcf8300cdc76', '107bee47-2aa2-4ca4-bea8-32469c71f861', 12, '100160320', 'ふたりのかたち', '【最終話】セシリアの存在をどう思っているのかとエリックに尋ねられ、うまく言葉にできないローレンス。自分たちの関係について考え込んでいる中、エリックがこぼした一言をきっかけに、1つのかたちを見出し始める。そのかたちについてセシリアに問いかけ、返答を聞いたローレンスの胸中に去来する思いは……。そして、街全体が恒例のお祭りの装飾と活気にあふれる中、ローレンスはセシリアをある場所へと連れ出すのだった。', '2025/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f54da271-3f4d-42f4-ab58-1bdb41e6c41d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b2a39912-e7fc-425c-b49c-faa26ccb3772', '白豚貴族ですが前世の記憶が生えたので ひよこな弟育てます', '', 'hulu', 'shirohiyo-reincarnated-as-a-neglected-noble-raising-my-baby-brother-with-memories-from-my-past-life', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3317c426-48be-4691-bbc4-d54e6ab98844.png?w=331&h=447&p=t', 'hulu', 2025, 1, 1, 'FINISHED', NULL, 179541, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 'b2a39912-e7fc-425c-b49c-faa26ccb3772', 'hulu-shirohiyo-reincarnated-as-a-neglected-noble-raising-my-baby-brother-with-memories-from-my-past-life-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ea268ce-b457-4568-85da-08c3aeaa6f44.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1bbc6672-2a4d-4d1c-94e2-043bcfabfe2b', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 1, '100230866', '前世の記憶が生えました', '菊乃井鳳蝶に、ある日、ひょっこり生えたもの。それは前世の記憶! 同時に思い知ったのは、これまでの自分がワガママだったこと。今はオトメンだった前世の趣味を生かしたり、家庭教師のロマノフに学んだり、心を入れ替え成長中! そんなある日、庭園の奥で前世の歌を歌っていたら、花の中から神様が現れて……!', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ea268ce-b457-4568-85da-08c3aeaa6f44.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8297f28-3332-4611-96d5-e1a81d2559c7', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 2, '100231833', '弟と初対面しました', '父と母が帰ってくる! でも、思い返すと鳳蝶は両親にあまり好かれてないようで……。ロッテンマイヤーがためらいがちに教えてくれたのは、両親のドロドロの確執。父には他に愛する人がいて、鳳蝶には母親違いの弟もいるという。これってまさか廃嫡の危機!?――と思ったけど、どうやら父の狙いはロマノフらしく……。', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcb0d785-3fd4-43f9-8452-9f2524a9ad12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c759ae14-79fb-44a7-a457-7f96f920bfeb', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 3, '100232577', '菊乃井さんちの家庭の事情', '父に弟の家庭教師を頼まれたものの、ロマノフは気乗りしない様子。説得するはずの父も母と醜い争いを繰り広げてばかり。幼い弟レグルスの未来がかかっているのに! もう彼らには任せてはおけないと、鳳蝶は自分が代わりに話をすることに。ロマノフはそんな鳳蝶の立ち回りをおもしろがっているみたいで……?', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6380546b-b90a-4e9f-b40c-df16f3f080ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53fd65b4-9cfb-4197-b57e-d056ca866e15', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 4, '100233093', '弟に折り鶴、私に茶碗蒸しを作ってみました', '鳳蝶はどうにか両親とロマノフを説得し、弟レグルスの教育係に。百華公主へのお披露目も済み、さっそく弟に教育を……と思ったら、この世界には子供向けの本がない! ――それなら作ってしまえ! ということで、鳳蝶が『青の手』のスキルを活用して作り上げたもの。それは、ロマノフも驚くような「布の絵本」だった。', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dac1b481-3efd-48d6-bec5-bb6be6e1878b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9a7b302-8e24-427b-bb6f-f7cadc4a00e9', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 5, '100233605', '私、あまり長生きできない気がします', 'いつか成長したレグルスに殺される――。以前見た夢が現実になると信じる鳳蝶は、弟のお守り役である宇都宮アリスに自分が死んだ後のことを頼もうとする。しかし、その頼みは彼女にうまく伝わらなかったようで……。一方、百華公主は鳳蝶の魂と肉体の繋がりが細くなっていて、倒れやすくなっていることに気づく。', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccea7771-22a7-4f0c-8c98-8a8aeb3993d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('964bff83-24e6-4e0c-a969-e0e269d3f25f', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 6, '100234183', '私の刺繍が売れました', '鳳蝶の体について調べるため、百華公主は少しの間不在に。その間に鳳蝶はロマノフに誘われ、帝都に向かうことに。でも、5歳児の鳳蝶は無一文! お土産を買うお金もないと心配する鳳蝶を連れ、ロマノフが向かった先は菊乃井領の冒険者ギルドだった。そこでロマノフが見せたのは、鳳蝶が刺繍したハンカチで……。', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7748971-0a59-411a-a35c-034db71cbfdc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('937d3fe5-b0d8-4660-9a44-96a78bf796c4', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 7, '100234867', '帝都へ魔術で行ってきます', '菊乃井領の冒険者ギルドの名物料理として鳳蝶が考えたのは――トンカツ! 評判は上々、お小遣いも稼いで帰宅した鳳蝶を待っていたのは、号泣するレグルスだった。それ以来、鳳蝶と離れるのを嫌がるようになってしまったレグルスだったが、剣術の先生である源三の言葉で落ち着き、鳳蝶はロマノフと帝都へ向かう。', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9be7956-740a-45b4-a572-0eedd7758dee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1dc47017-4a7c-497d-93e4-e1832fb36f3a', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 8, '100235191', 'は、はじめてお目にかかりますっ!', 'いつかミュージカルを上演するため、菊乃井領に『音楽学校』を作りたい……! 帝都で商業の神イゴールと出会った鳳蝶。彼と話すうちに、ぼんやりしていた将来のビジョンが鳳蝶の中で形作られていく。2週間後のマリアの舞台に来ることを約束して、鳳蝶はたくさんのお土産と未来の夢とともに菊乃井邸へ帰宅する。', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3be5a210-a669-4595-870d-7fb9fc32a44e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7abbf383-a7a0-4442-86a9-48e1661c42ab', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 9, '100235712', '帝国一の歌姫、誕生です!', '百華公主に鳳蝶が献上したのは、彼女の羽衣で作ったつまみ細工の牡丹の髪飾りだった。余った布で、マリアの髪飾りも作った鳳蝶は、それを手土産にヴィクトルやロマノフとともに帝都の国立劇場を訪れる。けれど、マリアの控え室で3人が見たものは、床に倒れて苦しみもがく歌姫の姿だった……!', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/294f9774-9bb4-47ae-ba47-b38798074487.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d098142-801e-4aca-8ce3-1702be873202', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 10, '100236336', '教えと真心で、胸が一杯です', '百華公主からもらった仙桃を惜しげもなく他人に与える鳳蝶。それは彼の美点でもあるけれど、同時に危うさでもあった。でも、ロマノフもロッテンマイヤーも、神々の加護を持つ鳳蝶を利用しようとせず、心配し、見守ってくれている。そのことに気づいた鳳蝶は、改めて2人に感謝するのだった。', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15eaa2e0-c87b-431e-9945-17903d0d5004.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22b844b4-ee65-4645-b41c-0cad78a6dbfa', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 11, '100237328', 'ともだちできちゃいました', '美の伝道師ラーラが加わり、菊乃井邸に『人間びいきの3バカエルフ』が勢ぞろい! 自然大好きなエルフたちは、自由時間には庭師の源三を手伝うことも。そこで鳳蝶は源三の孫の奏と出会う。彼は親とケンカして家出中だという。そんな彼に、鳳蝶は無意識に自分と両親の関係を重ね合わせて……。', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abe46650-941e-4520-b420-b4666ae67e18.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a45b1e9c-b7cf-44aa-8041-d0613e58f2d4', '30d2c7b7-6bac-449a-8a27-6e1ce8d13529', 12, '100237826', '前世の記憶を生かして商談します', '【最終話】いきなり訪ねてきたイゴールが持ちかけた商談。それは、鳳蝶が作ったつまみ細工の髪飾りを、とある大貴族が欲しがっているというものだった。正体不明の貴族に警戒する鳳蝶だったけれど、相手は貴族にしては珍しい庶民感覚の持ち主。しかも、なんと異世界の記憶まで持っているようで……?', '2026/03/01 00:00:00', 1423, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/155b1f09-2bf1-4bfa-bf5f-a7539465677e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d48e85ef-0694-4ce5-b24c-22db2d0e85c8', '白猫プロジェクトZERO CHRONICLE', '', 'hulu', 'shironekoproject', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/813c1483-a43e-4fae-83be-b03203e5397c.jpg?w=331&h=447&p=t', 'hulu', 2020, 1, 1, 'FINISHED', NULL, 110458, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d9627007-d623-42fc-8869-7eed0ad7cc59', 'd48e85ef-0694-4ce5-b24c-22db2d0e85c8', 'hulu-shironekoproject-s1', '第1シーズン', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee40b8ca-da04-47a0-b266-587f118f197d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9267a4df-2008-4242-a0d8-1e76302dcc5b', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 1, '100054453', '光に守られし国', 'ずっとずっと、昔のこと。はるかな天空に浮かぶ、美しい王国。その玉座で丸まる気高き白猫に、泥にまみれた黒猫が恋をした。それが、すべてのはじまり―。黒の王国の辺境の集落で、少年は慎ましい暮らしをしていた。しかしある時、少年の住む村に現れた魔獣のせいで、村は壊滅してしまう。一人だけ生き残った少年は、村人の墓を掘っていた。そこへ、黒い鎧を纏った謎の剣士、スキアーズが現れ―。', '2020/04/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee40b8ca-da04-47a0-b266-587f118f197d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b6f087a-e85e-43b0-8a2d-09312b2817e1', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 2, '100054537', '世界の我儘', '白の王国の守護神である光の王アイリスは、光と闇の均衡が闇の王によって破られる事を懸念していた。そこへ、バール出現の知らせが入る。均衡を乱す存在バールは、破滅的な力で西の都を蹂躙する。一方、黒の王国で王を目指す少年は、スキアーズの館で暗黒騎士ヴァルアスから修行を受け、闇の王後継者候補として成長していた。', '2020/04/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fcf9e2c-af58-4e4f-aa64-c4c82c2c5bcc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d830414-b93c-465c-b604-3d2da5e77ac5', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 3, '100054899', '愁傷の光の王', 'アイリスは自身が光の王になる前、シーマと共に修行した頃を思い出していた。王として、孤独と向き合い戦い抜く事を決意するアイリス。一方、グローザに連れられ闘技場に来た少年は、スキアーズ家の代表として王位継承者決定戦に挑む。そこで、同じ候補者であるアデルと対決する。', '2020/04/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/902ba9c3-c6c3-4137-80a5-1aa6b18cc03a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1696975-4c42-4d83-9fd8-001bb7a3fdfe', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 4, '100055135', '黒の使い', '白の王国に特使として派遣されたアデルと闇の王子。ファイオスに警戒されながらも、光の王アイリスと初めて対面する。バールと戦うための、両王国の共闘の盟約を届けるアデルと闇の王子。すぐには受け入れられないアイリスは、返答をためらうが―。', '2020/05/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6b33c12-081a-4b9f-9b0c-a9a609084917.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ec94cae-bda5-4f3d-ba8d-c2371234e878', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 5, '100055477', '共闘', '“均衡の一端”バールが黒の王国に現れる。驚異的な戦闘力で、闇も光も等しく滅ぼそうとするバールは、ヴァルアス、グローザ率いる王国軍と全面対決する。総力を挙げて抑え込もうとする黒の王国だが、力の差は歴然であった―。', '2020/05/11 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82863796-196a-4473-979c-5927b31c18b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6763b25-c274-4e1e-99b0-7976341e9e89', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 6, '100055669', '灰緑の魔障', 'バールとの闘いで力を使い果たしたアイリス。回復には時間がかかるが、意外にも黒の王国は停戦を申し入れる。今後白の王国に攻め入らぬよう、闇の王に進言すると話すアデル。光と闇の戦士たちは、しばしの休息に、街で親睦を深める。そんな時、グローザの提案で、お互いの着ている服を交換することになり―。', '2020/05/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61329a07-a240-408f-bd02-4e392ca38961.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0bf4bf2e-181b-4d4b-b848-9117bd3cf67f', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 7, '100055921', '山菜採り', 'アイリスの提案で山菜採りに向かう、光と闇の戦士たち。山菜採り競争を提案するアデルだったが、アイリスの知識に誰も太刀打ちができない。嬉しそうに山菜を採るアイリスに、感心する闇の王子。そんな時、テオの姿が見当たらなくなり―。', '2020/05/25 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c780325-c4fa-42e1-8d3b-e35f00786e68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75304cb6-6fec-440d-a7c9-bed4eee47cc8', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 8, '100056407', '約束', '黒の王国に帰る事となった、アデルと闇の王子。アイリスは白と黒の平和的な均衡を信じ、通商の盟約を結ぼうとしていた。騎士団長ファイオスともすっかり打ち解けた二人は、アイリスに最後の挨拶をするため王宮に向かうのだが―。', '2020/06/01 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e523de36-9471-413c-95be-3780816be3da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd3ff14c-7d8e-46a5-baed-d1e76ee44076', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 9, '100057131', '光の王と闇の王子', '闇の王子と約束を交わしたアイリス。だが、度重なる戦いで疲弊し、力を失っていた。ファイオスはアイリスを回復させる為、エルフの長アランティアと清浄なるソウルの塊を探しに行く。一方、黒の王国に戻った闇の王子は、光と闇の在り方に疑問を感じていた。グローザと共に魔獣退治を命じられた王子は、辺境の地へと向かうが―。', '2020/06/08 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bc59c7a-04b2-47cf-81ca-f9c40eea720c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('517770a8-2ee6-4497-a98d-e05eca537ae6', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 10, '100057412', 'やさしき闇の詩', 'アイリスは光の王として、黒と白の均衡を保つ重みを実感していた。しかし、自分一人ではこの状況を変える事はできなかった。アランティアと共にソウルの泉に辿り着いたファイオスは、光輝の雫を発見する。黒の王国では、闇の王子とグローザが崖の底で強敵バフォメットと対峙していた―。', '2020/06/15 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13c4701c-9c5c-473d-8c45-d2b556252ea7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b09c67c-6bba-4a42-af02-33e1fc3eb813', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 11, '100057747', 'はるか天空', '黒の王国の城下町。空では大量の軍船が天へと昇る。闇の王は、白の王国を闇で染めるため、決戦に向かおうとしていた。光輝の雫によって力を取り戻したアイリスは、始祖のルーンの力で王国民を強化し、黒の軍勢を迎え撃つ。闇の王とアイリス、闇と光の根源が対峙する―。', '2020/06/22 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce054c75-367e-4604-b96d-07aed0ea1f1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a81d3e6-27bc-4785-afc0-818be807802f', 'd9627007-d623-42fc-8869-7eed0ad7cc59', 12, '100058173', 'はじまりの罪', '【第1シーズン 最終話】黒の王国の王宮へと案内された闇の王子。そこへ、思いも掛けない人物が現れる。闇の王の策略を告げられた闇の王子は、秘められていた真の力を開放する。白の王国では、アイリスとシーマが全てを注ぎ込んだ“運命の歯車”をもってしても、避けることのできない滅びが迫っていた。闇の王の力がアイリスの力を上回り、王国が、闇の瘴気に覆われていく。自分の全てが通じない事を悟った光の王は、最後の決断をする―。', '2020/06/29 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/369b7681-9686-40e0-84b7-4560e412948e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ffaf52bb-f131-4629-a708-afdf7687456d', '薄桜鬼', '', 'hulu', 'hakuoki', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50014269_series_art__338x600_hakuoki_746b64162fb9f6035bab6c3b4c2a6aea.jpg?w=331&h=447&p=t', 'hulu', 2011, 1, 1, 'FINISHED', NULL, 11663, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a299a43a-d96b-4c2f-aa52-ec6af677e15b', 'ffaf52bb-f131-4629-a708-afdf7687456d', 'hulu-hakuoki-s1', '第一期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/54ad084e-bda1-4f32-bc5d-d66567403bf7.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f11ba5f-fcb6-4937-be79-50f6d7d9e3d4', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 1, '60313072', '雪華の都', '文久三年、冬。父の行方を探して京の都にやって来た雪村千鶴は、血を求める化け物に襲われそうになる。千鶴に迫る化け物を斬り伏せたのは、「人斬り集団」と恐れられる新選組の幹部たち―土方歳三、沖田総司、斎藤一だった。舞い散る雪の夜、千鶴は運命の出会いを果たす。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/54ad084e-bda1-4f32-bc5d-d66567403bf7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5716f1c-67e5-4490-89f4-1c00ed5cbeaa', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 3, '60313069', '宵闇に咲く華', '山南の命を受け、土方たちのもとへひた走る千鶴。その頃、近藤たちは既に長州人を始めとする勤王の志士たちが会合する宿―池田屋に踏み込んでいた。そこで沖田と藤堂は、只ならぬ気配を漂わす怪しげな二人の浪士に遭遇し、それぞれ一戦を交えるが…。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/37535e1d-0383-48ba-a4dc-80961095b93d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c48c36a-129e-44a3-9a30-bd91700129f2', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 4, '60313074', '闇より来る者', '池田屋への討ち入りからひと月、京には長州藩の藩兵たちが集結していた。御所に攻め入ろうとする長州藩兵を追い返すため、新選組も出陣する。斎藤は蛤御門、原田は公家御門、土方は天王山へと分かれる中、三人は各地で薩摩や長州に与する者たちに出会う。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6d902efa-c539-47f7-9f3e-7d9a32fb717a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15d6e565-1b86-4bef-a54b-ee3427f2a192', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 5, '60313065', '相克せし刃', '近藤らが江戸でおこなった隊士募集に応じ、伊東が新選組に入隊する。総長でありながら剣客の道を絶たれていた山南は、伊東が参謀の座に就いたことで身の置き場を失くしてしまう。千鶴はそんな山南を気に掛けるが、やがて事態は思いもかけない惨事に発展し―。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f80bc6ea-f2d7-4ab6-a048-d3c9d568892e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6302dd9-d69e-41c5-90c4-8e724927c62c', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 6, '60313068', '鬼の命脈', '綱道が改良したという薬を飲み、人ならざる者へと変貌する山南。土方は伊東派から山南の存在を隠すため、西本願寺への屯所移転を断行する。移転後、藤堂が江戸より帰京。父親探しの進まない千鶴を明るく励ます藤堂だったが、千鶴は彼の様子がおかしいことに気付く。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d9ba7684-ebf1-48d4-a0f6-d53020dc7505.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5cac0b61-a7ba-4e66-8b0f-dd6180633057', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 7, '60313075', '桎梏の運命', '二条城に現れた三人の男たち―風間、天霧、不知火は自らを「鬼」と名乗り、千鶴を連れ去ろうとする。駆けつけた土方、斎藤、原田によって千鶴は窮地を脱するものの、風間たちの残した言葉は謎に包まれたままだった。そんな中、千鶴は「千」という名の少女と出会う。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bc93e009-9616-4209-9a24-0c28ccccdb30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53f7b089-1a55-484e-a6c0-b02f097feaa8', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 8, '60313071', 'あさきゆめみし', '風間から綱道の動向を聞かされた千鶴は、父が新選組と敵対する勢力にいるのではないかと思い悩む。元気のない千鶴を心配する永倉や原田たち。時は過ぎ、京では制札を引き抜く事件が相次いでいた。新選組は制札警護の任を受け、犯人を捕らえようとするが…。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b3a80022-6060-41f1-9741-5013f11c872f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32f6c0f0-1193-4395-a363-47d91b3cf1b8', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 9, '60313066', '修羅の轍', 'しばらく京を離れていた風間が、再び上洛していた。また、伊東は何者かと密会し、怪しい動きを見せ始める。ある日、羅刹となった隊士が千鶴に襲い掛かる―という事件が起き、その惨状を見た伊東は近藤たちに「新選組から分離し、御陵衛士を拝命する」と告げる。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/476867d4-b9fb-471b-80cf-351a6b0596d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc12f859-69f2-4efb-bff8-5a6bc998bd0a', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 10, '60313076', '絆のゆくえ', '風間の襲撃によって、不動堂村への屯所移転を余儀なくされた新選組。まもなく大政奉還が成立するが、坂本暗殺の嫌疑が原田にかかるなど、その波紋はやがて大きなうねりとなって新選組を襲い始める。御陵衛士と事を構えると知った千鶴は、藤堂が心配になり…。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0eb0f84c-0742-4244-b326-7a3a0d221ac0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37f7e7d0-6b1c-4624-b144-2b73523e455a', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 11, '60313067', '零れ落ちるもの', '薩摩・長州の両藩兵が京に集結して軍備を整える中、新選組も不動堂村から伏見奉行所へ拠点を移し、臨戦態勢をとることとなる。奉行所に詰めてから数日後、局長である近藤が軍議から帰る途中で何者かに狙撃される事件が起こり、新選組に激震が走る。', '2022/09/01 00:00:00', 1395, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4ecb42bb-fdc3-441d-8ed0-77e1f31776b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c2b6a2d-685b-4463-85c8-3c4ce9af39b0', 'a299a43a-d96b-4c2f-aa52-ec6af677e15b', 12, '60313070', '剣戟の彼方', '【第一期 最終話】近藤と沖田が大坂に護送されて直ぐ、新政府軍との争いが勃発。永倉率いる二番組は敵の本陣に斬り込むが、射程の長い銃に太刀打ちできない。斎藤、原田らも同様に成す術がなく、土方は伏見から撤退することを決意する。井上と千鶴は淀城まで援軍要請に赴くが―。', '2022/09/01 00:00:00', 1380, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/4792ee79-aafe-40d8-ac12-2edc68d644ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('092b85ec-b093-43ec-95d0-19ea905019d9', 'ffaf52bb-f131-4629-a708-afdf7687456d', 'hulu-hakuoki-s2', '碧血録', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d99d6db-7d96-4c3d-8198-b98471dcc937.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('348101ec-4f82-4b5e-848c-35a4851bbf3e', '092b85ec-b093-43ec-95d0-19ea905019d9', 13, '100119887', '焔の如く', '江戸に戻った土方は薩長との再戦に臨むべく動く。羅刹の身で日中も働き続ける土方を心配する千鶴。山南は怪しい行動を見せ始め、沖田は銃創が癒えずに静養していた。そんな中、新選組は甲府城で敵を迎え撃つよう命じられるが、原田や永倉は任務に懐疑的で…。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d99d6db-7d96-4c3d-8198-b98471dcc937.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52cb7509-f243-456b-885b-38c8b611218d', '092b85ec-b093-43ec-95d0-19ea905019d9', 14, '100119888', '蹉跌の回廊', '新選組は甲陽鎮撫隊として甲州へ進軍するが、甲府城にはすでに新政府軍が入城していた。先を越されたと知り、新参隊士の多くが脱走。原田たちは撤退を主張するものの、近藤は一切応じようとしない。土方が援軍を呼びに戻るものの、その間に戦いは始まってしまう…。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64e7829d-a2d3-472a-b654-a786aaadf247.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76183fcc-79f0-4f22-9039-ec040e6ddf26', '092b85ec-b093-43ec-95d0-19ea905019d9', 15, '100119889', '遠き面影', '甲州勝沼の戦いに敗れて撤退を始めた新選組は、陽の下でも動ける新政府軍の羅刹たちから攻撃を受ける。羅刹たちを率いていたのは雪村綱道だった。一方、千鶴は土方と交わした約束どおり、近藤を逃がそうと奔走していたが、二人の前に立ちはだかる者がいて…。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e48ee7c0-6c50-4b7d-ab70-6ba025576b67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c8b2f7d-df3d-4a34-9dc4-9a9c1d8a9b57', '092b85ec-b093-43ec-95d0-19ea905019d9', 16, '100119890', '誠心は永遠に', '初めて敗戦を経験した近藤は、意気消沈していた。土方は江戸に残っていても戦いの機会を得られないと考え、会津へ向かうことを提案する。新たな隊士を募り、市川で彼らに新式装備の演習をさせる中、流山に移転した近藤たちは新政府軍に取り囲まれてしまう…。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a48b5599-652d-4cc8-a22a-3a939961131b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81f1f724-d0f2-4e49-856f-e1710393415c', '092b85ec-b093-43ec-95d0-19ea905019d9', 17, '100119891', '玉響の夢', '江戸城の無血開城が決まり、土方たちも伝習隊を中心とした旧幕府軍の脱走部隊に加わる。旧幕府軍兵たちが新選組の陰口を叩く中、歩兵奉行の大鳥圭介から先鋒軍の参謀に指名された土方は、自ら先頭に立って新政府軍に恭順する宇都宮城を攻め落とそうとするが…。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fd35c82-d9e2-4825-a844-2b8c57e3ef2a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be7fd999-09f1-4dec-80f5-1987918685ad', '092b85ec-b093-43ec-95d0-19ea905019d9', 18, '100119892', '輝ける暁光', '宇都宮で負傷した土方は、新選組本隊と合流するため、千鶴とともに会津へ向かう。しかし、会津で出迎えた斎藤たちから、近藤が斬首に処せられたと聞かされる。一方、不知火の話が気になり江戸へ戻った原田は、彰義隊が新政府軍から攻撃を受けていることを知る…。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98e8d096-170c-441c-ae14-e51befde2a8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('022482bd-1874-4db9-a849-b60c5e68bbd0', '092b85ec-b093-43ec-95d0-19ea905019d9', 19, '100119893', '天道の刃', '負傷した土方に代わり新選組の指揮を執っていた斎藤は、会津候から命を受けて会津藩士たちとともに戦うことになる。しかし、彼らは斎藤が洋装であることや、刀を右差しにしていることを理由に反発する。斎藤たちは白河口に布陣する新政府軍へ攻め込むが…。', '2022/09/01 00:00:00', 1397, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16f5be6d-9b55-4cd5-b891-701d69bd8a4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23fec2a8-8f7c-4cd4-805e-b12e1f9eea66', '092b85ec-b093-43ec-95d0-19ea905019d9', 20, '100119894', '散ずる桜花', '仙台へ着いた土方を、旧幕府海軍の榎本武揚が訪ねて来る。彼から仙台で辻斬りが横行していると聞いた土方は、連絡の途絶えている山南たちが事件に絡んでいるのではないかとの疑念を持つ。土方が辻斬りの情報を求めて探索に出る中、千鶴の前に藤堂が現れ…。', '2022/09/01 00:00:00', 1397, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c572e99a-5aa8-4382-bb63-6dafedf68aed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0bd0fc57-5fee-457f-b748-60bc43db465b', '092b85ec-b093-43ec-95d0-19ea905019d9', 21, '100119895', '雪割草の花咲きて', '土方は千鶴を仙台に残したまま、榎本たちとともに蝦夷へ渡っていた。松前藩を陥落させた彼らは、旧箱舘奉行所である五稜郭を基点とし、徳川家遺臣たちによる領地を蝦夷に築こうとしていた。入札による選挙も行われ、土方には陸軍奉行並という役職が与えられる…。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6645a4d-38bb-4e8b-bf12-f1d1c0c88d78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc55d332-06ad-4ba0-a176-e5c0e81f3df9', '092b85ec-b093-43ec-95d0-19ea905019d9', 22, '100119896', '夢幻の薄桜', '【碧血録 最終話】ついに新政府軍が蝦夷に上陸する。山中の二股口に陣を構える土方たちは全勝していたものの、大鳥たちが守る松前口が水陸から攻撃を受けて敗れたため、撤退せざるを得なくなってしまう。明治二年五月十一日、新政府軍による箱舘総攻撃の日、土方と千鶴は…。', '2022/09/01 00:00:00', 1382, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7d65900-05f9-41bf-be8b-a2c8c32d9dfb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 'ffaf52bb-f131-4629-a708-afdf7687456d', 'hulu-hakuoki-s3', '黎明録', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58105003-9132-4073-89a5-b028bdb6962b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('821826f7-11f5-4853-8fb7-340d2b629c04', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 1, '100119897', '天武の暁', '文久三年二月。母親を病で亡くし、あてもなくさまよっていた井吹龍之介は、浪人に襲われ行き倒れていたところを、壬生浪士組として上洛の途中であった芹沢鴨に拾われる。連れられた先で出会ったのは、本物の武士を志す男たち…。土方歳三をはじめとする浪士組の面々であった。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58105003-9132-4073-89a5-b028bdb6962b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17a2a831-82d8-47f1-aa46-bdc046499477', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 2, '100119898', '導かれし運命', '拾われた恩を返すべく、芹沢の下で働くことになった龍之介は、次第に浪士組の仲間と打ち解けてゆくが、身勝手な芹沢には相変わらず振り回されていた。そして将軍･家茂の入洛日、浪士組として自主警護を申し出る近藤･土方に対し、芹沢はまたしても異を唱え…。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e11d08a-db36-4b96-a43c-358e0d62a609.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0440ae2e-8afc-4820-92b6-18b4cd2bd200', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 3, '100119899', '群狼の掟', '浪士組に、正式に会津中将御預かりとなる旨の通達が下った。京での残留許可を得て、堂々と見廻りができることに皆が湧く中、芹沢の伝手を頼った結果であることを承知している土方は素直に喜べずにいた。その夜、祝杯をあげに訪れた島原で、舞妓の小鈴が芹沢に反発し、大騒動が巻き起こる。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4cabd98a-de20-4853-b946-625d70a00043.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96f3a074-4763-45cc-9aef-d4b506473eb2', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 4, '100119900', '血塗られし刃', '突然土方より江戸への帰還を告げられた沖田は、思わず八木邸を飛び出してしまう。近藤を筆頭に、沖田の様子を心配する浪士組…。その中で井吹は、近藤と沖田の関係を知る。一方芹沢は、殿内という隊士が近藤暗殺を密かに企てていると沖田に告げる。それを聞いた沖田は…。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0063803-1b3d-4a78-88c3-a45e6227d29f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f419404f-35c4-4e0b-ac8c-898b9f593715', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 5, '100119901', '蒼穹のきざはし', '資金調達のために繰り出した大坂で、芹沢は商家から押し借りまがいの言動で金を出させる。責め立てる近藤や土方であったが、逆に不逞浪士と戦ってゆく覚悟のなさを指摘され、土方は己の甘さを思い知る。約半月後、会津藩主･松平容保公の謁見が決まり、上覧試合が取り行われる。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ca40cda-c522-49ba-9844-25f502896bb8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee5dcf94-4a5c-4f4c-b228-ad66153ff700', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 6, '100119902', '闇よりの咆哮', '新見の紹介で、蘭方医の雪村綱道なる人物が浪士組を訪れる。人材不足を解決する妙案があると言ってほくそ笑む新見に対して、土方らは不信感を募らせていた。そしてその夜、八木邸に突如絶叫が響き渡る…。悲鳴の主は、理性を失った人ならざる者で、駆けつけた藤堂たちに襲いかかる。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21c97b0f-9c02-4625-8985-c889927099f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d24a2e22-e286-460b-af9c-b6fa47e02302', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 7, '100119903', '草颯の誓い', '大坂から戻った山南は、芹沢らが丸腰の力士たちを斬りつけたと報告する。思わず芹沢に詰め寄る土方だったが、芹沢は自らの非を認めるどころか、土方に対して鬼になる覚悟が必要だと言い放つ。その言葉に揺れる土方は、近藤とともに互いに夢を語り合った江戸の試衛館の時代を思い返す…。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/804178d7-aa03-4e8e-b62c-38a821a6f9bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e269288f-1521-4cdc-a410-912a58347088', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 8, '100119904', '修羅の枷鎖', '新見の変若水実験によって作り出された羅刹が再び逃走した。羅刹を眼前に為す術のなかった井吹に、斎藤は隊士と共に剣術を学んではどうかと提案する。一方、羅刹の首を晒したことにより浪士組の悪評は高まるばかりで、京では浪士組の名を騙って押し借りをする手合いが増えていた…。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84126f48-38b6-4fa9-b604-788ebfb6a977.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dc135e4-b721-4b54-bb8e-8866168794ab', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 9, '100119905', '放たれる剣閃', '芹沢が大坂へ赴くことを井吹から聞いた小鈴は、大坂の舞妓が難事に巻き込まれないか心配する。自分が芹沢を見張ると約束し、小鈴を安心させて別れた井吹だったが、二人の様子を見ていた山崎に見咎められる。そして井吹の思いと裏腹に、芹沢の怒号が大坂の吉田屋に轟き渡るのだった。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a094a836-625a-4133-813f-f7f3ba64721a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d681e055-3928-49e8-accd-4694b352a078', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 10, '100119906', '紅蓮の烽火', '京都･大坂の合併相撲興行を無事に終え、その成功を喜ぶ隊士たちのもとに、芹沢が商家の大和屋を焼き討ちにしたとの報せが入る。横暴な振る舞いを繰り返す芹沢だったが、時折我を忘れたような芹沢の様子に井吹は違和感をおぼえていた。そして八月十八日、会津藩と薩摩藩による政変が勃発する。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4dcc481-ce97-4640-831b-87112c70130b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2ff93b8-41a8-4b37-a404-2479cc8c6d1f', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 11, '100119907', '百花月夜', '新選組内で芹沢への反発が高まるなか、近藤はなんとか共生の道を見つけようと芹沢を説得するが、芹沢は聞く耳をもたない。しかし井吹は一方で、お梅に語る芹沢の心中を図らずも聞いてしまう。そんな中、新見が変若水を持って失踪し、程なくして辻斬りの噂が京市中に聞こえ始めた…。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0917c590-c082-46c8-98f4-45ed4226916a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce2ea87f-e760-4881-a6c9-ca344b713cfc', '3d93b8a8-a104-4628-91f1-004d1fd6b3c1', 12, '100119908', '大いなる黎明', '【黎明録 最終話】いよいよ芹沢の暗殺が決行されようとしていた。何も知らされていなかった井吹は、同席した島原の宴会中に寝入ってしまう。目覚めた井吹は、慌てて座敷を飛び出すが…。駆ける井吹と、八木邸で対峙する土方と芹沢…。決着の刻が迫るなか、それぞれの覚悟がいま試される。', '2022/09/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ebd526e-f058-4925-803f-4318e040d1d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e3cfe464-f77e-400f-9f18-933ed1ddf751', 'ffaf52bb-f131-4629-a708-afdf7687456d', 'hulu-hakuoki-s4', '雪華録', 4, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/315e54fd-de8d-426d-a17c-9cb8f3719839.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0725faa6-0007-4a97-bc42-c94704af14fb', 'e3cfe464-f77e-400f-9f18-933ed1ddf751', 1, '100119909', '玄夜の白雪', '慶応二年十二月、京。沖田は千鶴との巡察中に、角屋に潜伏する浪士が新選組屯所の襲撃を狙っているとの噂を聞く。内偵役に千鶴を推薦し、隊士たちの喧騒ぶりを楽しむ沖田だったが、一方で自らの病と向き合い、決意を新たに、一人静かに刀を握るのだった…。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/315e54fd-de8d-426d-a17c-9cb8f3719839.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d572798-28f1-4910-82de-f1ba1a73fce8', 'e3cfe464-f77e-400f-9f18-933ed1ddf751', 2, '100119910', '冬の埋み火', '新選組屯所の襲撃を企てる不逞浪士の内偵のため島原に潜入した千鶴の護衛役として、斎藤は山崎と共に角屋の一室に控えていた。浪士たちに絡まれた千鶴を助けるべく駆けつける斎藤だが、意に反して騒動は大きくなり…不穏な時代の流れを感じながらも、斎藤はその刀の切っ先の如く、迷いなく信念を貫き通す。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b919402-44df-4bab-bde8-4d2af28f4755.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fbf7cf39-9f50-4009-ade5-cb97768e9e56', 'e3cfe464-f77e-400f-9f18-933ed1ddf751', 3, '100119911', '空裂く槍', '千鶴の島原潜入騒動が落着した慶応二年十二月暮れ。京の街に買い出しに行った原田と千鶴は、京からの密書の持ち出しと、苛烈になる幕府の取り締まりを目撃する。役人の横暴な振る舞いに心を痛める千鶴と原田だったが、そんな中、新選組にも京の検問の任が下される。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d60f486e-c13c-46d5-bb42-fca83e840b2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29254884-a909-4611-a2e7-06bc82477b5d', 'e3cfe464-f77e-400f-9f18-933ed1ddf751', 4, '100119912', '揺蕩う舟', '慶応二年十二月。不逞浪士の内偵のため、新選組は千鶴を島原に潜入させることを決める。千鶴の身を案じ、作戦に一人反対する藤堂だったが、思いがけず騒動は広がってゆき…。一方で伊東甲子太郎の暗躍は、新選組に不穏な影を落とすが、その中でも藤堂は己の生き様を示してゆくのだった。', '2022/09/01 00:00:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6d498bf-383b-4d1c-b1c4-fc83410ab9a8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c8eab7da-2224-4399-8049-041369e25cd4', 'e3cfe464-f77e-400f-9f18-933ed1ddf751', 5, '100119913', '天明の風', '不逞浪士を内偵するための千鶴の島原潜入だったが、角屋全体を巻き込むほどの騒動になってしまった。駆けつけた土方は千鶴を見つけ連れ帰ろうとするが…。伊東の陰謀、激動する時代、そして鬼の存在…。様々な思惑が交差する中で、土方は己の信念を、そして新選組の行く道を想う。', '2022/09/01 00:00:00', 1398, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e1b3a7c-9473-4a2c-b5e9-a19271c1acf8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b596551f-9c56-4ad6-ac6b-1fdc22f01a92', 'e3cfe464-f77e-400f-9f18-933ed1ddf751', 6, '100119914', '雪華の舞', '【雪華録 最終話】慶応二年十二月。京の都にて華々しい活躍をみせる新選組。だがその影では迫り来る動乱の時代に呼応するかのように、西国の鬼たちがそれぞれの思惑を持って京に集っていた。新選組襲撃を画策する不逞浪士を探るべく、芸妓に変装して島原に潜入した雪村千鶴だったが、そこには西国の鬼･風間千景の姿があった…。', '2022/09/01 00:00:00', 1691, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd585ed4-64d0-4cdc-9de3-c1a0a6c4feb8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('96909589-eade-4b81-8fd4-5e818fa6bfe1', '爆丸アーマードアライアンス', '', 'hulu', 'bakugan-armored-alliance', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36663442-e1ba-45f0-af20-ad0567e95e85.png?w=331&h=447&p=t', 'hulu', 2020, 1, 1, 'FINISHED', NULL, 116415, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ab33fa86-1340-4c55-83b4-1cb3b53017a8', '96909589-eade-4b81-8fd4-5e818fa6bfe1', 'hulu-bakugan-armored-alliance-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c9aeb15-9494-433a-991e-14899b68032b.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c42d1ef1-f598-48be-9f5d-541ce4daa6ad', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 1, '100079518', '謎の少年／ゴールド爆丸ファロル', 'ゴールド爆丸のチコが巻き起こした大混乱から見事に世界を救ったオーサム･ワンは皆からその栄誉を称えられ、表彰と記念のバトルが行われることになった。ダンとリオットが爆丸バトルを開始すると、突然見たこともないゴールド爆丸が現れ、リオットのマクスタウラーを一撃のもとに吹き飛ばしてしまう!／チャレンジマッチで、ダンの前に突然現れた謎のゴールド爆丸とそのパートナーの少年は、バトルを妨害したとして警備員に捕まえられそうになる。しかし素早い動きでかわすと、少年たちはどこかへと消えてしまう。ダンは消えた少年の後を追う事にする。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c9aeb15-9494-433a-991e-14899b68032b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('421c5c59-a4c2-417e-ac76-f88f11bf8751', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 2, '100079519', '爆ギア／爆丸ロック', '謎のゴールド爆丸とのバトルで出現した爆丸の新しい力を「爆ギア」と名付けたオーサム･ワンは、爆ギアを出す練習をすることに。するとそこにトレイというチェスのチャンピオンの少年が現れ、ダンに爆丸バトルを挑んでくる。／ダンとドラゴのコンビだけが強力な力「爆ギア」を使っており、自分たちも爆ギアを出そうとその方法を探っているウィントンとリアの前に、全身トゲだらけのコスチュームに身を包んだアリソンとローレンという二人が現れ、爆丸バトルを挑んでくる。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3150c8ad-90c7-4cf0-98f9-88ed2c206ef9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8685706e-4d46-487a-9de8-56303a73fd97', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 3, '100079520', 'グランツファイブ／ライトニング、学校へ行く', 'ある時、シュンはカザミのロスヴォルモス支社を任されているトシから、重要な取引先であるシュミット社の次期社長とされるルカという少年をもてなして欲しいと頼まれる。シュンは懸命にルカをもてなすが、どうやらルカには別の目的があるらしく…。／犬のライトニングは、自分以外のオーサム･ワンのメンバーが通っている学校というものに興味津々。どうしても自分も学校生活をしてみたくて、皆には内緒で学校へと行ってみることに。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a89fb80a-961b-4941-ac30-2d65faaa7a0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abfcf5f5-111c-460b-bbe1-4cf58f67b342', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 4, '100079521', 'トラブルバスター!／オーサム･ワン解散!?', 'オーサム･ワンの新しい動画の企画として、爆丸に関して困っている人を助けるという「爆丸トラブルバスター」をスタートした。まず初めにダンたちに困りごとを相談してきたのは「世界一静かな町を目指す町」の町長からだった。／オーサム･ワンはメンバー同士、とても仲が良くて、お互いの事を信頼している。しかしある時、お皿に残った最後の一本のフライドポテトを誰が食べるかで大喧嘩が勃発。それぞれが個人で活動することになってしまう。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3aabfba2-f306-48eb-a22a-4b3977de956d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a84ccd78-f3bd-49cf-89b2-053ce3f94682', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 5, '100079522', '怪盗ストーム参上!／怪盗アジットの挑戦!', 'ロスヴォルモスの郊外で古代文明の遺跡が発見された。勿論、オーサム･ワンの皆も大興奮! しかしそこに怪盗とその弟子の、爆丸を連れた少年が現れ、古代遺跡にあるお宝を盗み出そうとする。／ある日、遺跡から発見された古代爆丸の石像を盗むという予告状が届く。オーサム･ワンは研究所の所長から警備を頼まれ、大いに張り切る。そんなダンたちの前に、以前に出会ったゴールド爆丸を連れた少年が現れる。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ded9511-3ec3-4c56-99ad-93707816c4ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb2cac20-eaa4-4130-a938-2447fac6eeeb', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 6, '100079523', 'リオットの女王様レッスン!／オーサム･ワン映画デビュー!', 'ある時、リオットはバーべトラという新しい爆丸と出会う。ただこのバーべトラ、自分に自信がなくていつもおどおどしていた。そんなバーべトラを鍛えようと、リオットが特訓を開始する!／ブラキスタンの国王、ブラッケン帝から爆丸の映画を撮りたいということで招待を受けたオーサム･ワン。すると子役で有名なデュラン･ディーンも招待を受けていて…。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b672452e-1a2d-426a-b5b4-0e9d3bddc9b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37068351-7dfe-4381-9c43-0e6a71fbbab2', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 7, '100079524', '私のウェバムちゃん!／闇のニリアス', 'マグナスの妹であるエミリーが爆丸バトルに初挑戦! しかもダン相手に勝負を挑む!!／世界は現在、デバイスをつかって爆丸を利用する事が禁止されていた。そんな中、誰よりも爆丸バトルに情熱を燃やしていたマグナスは一人、海辺にたたずんでいた。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/370ab69b-4794-4892-ba59-fd1b1f85a567.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26593a81-08ac-4202-8982-9ad5dc51dcf0', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 8, '100079525', 'ベントンの計画／古代爆丸のジレーター', 'ベントンが新しく作った施設に、ダンたちを呼んで色々と試験や実験をする。なにやら壮大な計画があるようで…。／オーサム･ワンが爆丸たちと共に野球をしていると、古代爆丸のジレーターと出会う。ただこのジレーターという爆丸、相当な頑固者で…。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccdf5385-5e0c-4672-9236-084c0ca662cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1112fa11-ef55-4219-92bc-38376cf4e7a8', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 9, '100079526', '僕が爆丸で爆丸が僕で／ブラジルから来た少年', '自作のレーダーをつかって新しい爆丸のバトリクスを見つけたウィントン。しかしふとした事がきっかけで、そのバトリクスとウィントンの体が入れ替わってしまう!／ペペというサッカーの有名な選手から爆丸バトルの挑戦を受けたシュンは、新しい爆丸のランパリアンでバトルに挑む!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19a5d84e-d8f6-47e1-b026-764d50734c23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0601d953-55bc-4e87-87d3-00623a9fb6fd', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 10, '100079527', 'ゴーストブローラーズ／密着! ライトニング', '最近、子どもたちの間で噂になっている幽霊が出るという古い屋敷があった。そこでオーサム･ワンは本当に幽霊が出るのか確かめに行くことに。／ライトニングが、ある時テレビ局から密着取材を受けることに。ただ新しい爆丸のトレトロスを見つけたライトニングは、取材に対してあまり興味が無いようで…。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fea75fd-4a8f-444d-a4a3-ba1c7fb778a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df7231fa-87ea-4d6c-bb10-2b17d4001a3e', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 11, '100079528', 'マグナスの事件簿･前編／マグナスの事件簿･後編', 'ある時ミドルシティという街で、看板や巨大なオブジェなど変わったものばかりが盗まれるという事件が頻発する。その事件の解明にマグナスが乗り出す。／怪盗の狙いを見抜き迎え撃ったマグナスに、己の意地とプライドを賭けて怪盗が再び挑んでくる。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a32ae1eb-0550-4ca0-9730-4b9f4b720372.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51c0bb04-7878-480f-a38b-0f70e134681f', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 12, '100079529', 'オーサム･ワンの爆丸合宿／アジットの秘密', '爆ゲームに向け合宿をして特訓をすることになったオーサム･ワン。ただ皆、お互いにライバル心が剥き出しで……!!／オーサム･ワンが爆ゲームに向けて合宿をしていると、そこにアジットが現れて合宿に参加することに!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e54cc26b-fb00-4b01-87d7-7b7d2a06fa25.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30d0aefb-fb60-4859-8fb2-c388b9ca8d07', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 13, '100079530', '開幕! 爆ゲーム!!／復讐のリオット', '待ちに待った爆ゲームがとうとう開幕! ただダンだけはなんだか調子が出ないみたいで、一回戦から大苦戦!／大盛況の爆ゲームもいよいよ決勝トーナメントがスタート! 第1試合は前回のリベンジに燃えるリオットがアジットに挑む!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00c5b05b-692e-4c69-8d8e-83d5c774b671.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de476aa4-edca-4fea-be6d-074dedca1419', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 14, '100079531', '爆丸カンフー／人気者はどっちだ!?', 'ますます盛り上がってきた爆ゲーム。次なるダンの相手はカンフーが得意な少年、チャオ。カンフーを駆使したバトルにダンも苦戦必至!!／爆ゲームの最中に、リアが動画配信の面白企画を思いつく。その内容とはウィントンとシュンの試合でどっちが盛り上がるかを競う事。果たしてどっちが人気者!?', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9db1dc5d-e21f-454b-80a8-e6f88d17b4b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('546862a3-d252-427b-a9b1-f95004fa9c07', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 15, '100079532', '謎のリベンジャー／ウィントンVSリア', 'ますます盛り上がっていく爆ゲーム。ダンの次なる相手は覆面を被った謎の男。ただこの覆面男、何やらダンに深い恨みを抱いているようで…!／爆ゲームもいよいよベスト8の戦いに! そしてここでリアとウィントンというオーサム･ワン同士の対戦が始まる!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8c4f1bb-7f47-47f6-a1fc-3cd82f39f0fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0483e49c-ede3-4769-a641-e315a7188749', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 16, '100079533', '親友同士の戦い／怪盗とブローラー', 'ダンにとって最も古くからの友達、ウィントンとのバトルが始まった。お互いの思いがぶつかり合う激しいバトルの幕が上がる!!／シュン対アジットという注目のカードが始まろうとしていた。しかしその試合の前にアジットの師匠であるストームが現れ、アジットに何かを告げる。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b100fd30-adcf-4c2f-8689-1b011334f4f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e86e5ddd-fcde-4f19-8344-bfe7d5fb4944', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 17, '100079534', '決勝! ダンVSアジット／暴かれた秘密', '爆ゲームもいよいよ決勝戦。頂点を決める戦いまで残ったのはダンとアジットの2人。それぞれの想いを胸に、今、バトルがスタートする!!／爆ゲームの決勝も終わり後は表彰式を残すのみとなった。しかしそこで事件が起こる。会場にいる子供たちの爆丸がなくなっていた!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/774192a0-cf6e-482d-ba6d-92b993cb6d89.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('098d2323-514d-41fe-a45e-6eb154d8a890', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 18, '100079535', '宇宙一のおたずね者ハーヴィック／クロス爆丸', '平和な地球に、宇宙で悪名高きハーヴィックなるものが舞い降りた。とんでもない波乱が起こる予感…!!／アリソンとトレイが爆丸バトルをしているとハーヴィックがやってきて、アリソンたちの爆丸をつかってとんでもないものを作り出す!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73ba40ba-774e-472a-8b3b-5e151715f03c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccd39d8d-b713-4b70-9239-e32b1c4f48ba', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 19, '100079536', 'リア、監督デビュー!?／クィーン･エボニー', 'エベレット･レイからリアの元に、爆丸を題材にした映画を撮りたいから監督になってくれないかというオファーが届く。半信半疑のリアだが…。／ロスヴォルモスのストリートにある日、事件が起こる。野良犬たちがエボニーと呼ばれる一匹の猫に支配されてしまったのだ。その事件にライトニングも巻き込まれてしまい…。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6371ddc5-f0dc-41d9-87ac-ecc47f2fa949.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5fce869d-7a14-4f14-8bf8-66eeb905dbbe', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 20, '100079537', '爆丸を守る女･ソフィー／列車での死闘', 'ある日、ダンたちがいつも通り爆丸バトルをしていると、バクガニストと呼ばれる爆丸の保護活動をしているソフィーと呼ばれる女性が出てきて、ダンたちに爆丸バトルをやめるよう言ってくる。／違法デバイスの存在を追っていたマグナスは、違法デバイスの提供源を叩こうと考え、ある鉄道に目をつける。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e31d74fc-a1c7-4c40-98f6-6a4813d21387.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb5fee68-f82b-43ec-9af6-6487732f29e0', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 21, '100079538', '闇商人･マキュー／帰ってきたハンター', '禁止されているはずの違法のデバイスが最近、巷で数多く出回っていた。そこでダンたちは違法デバイスを自分たちで取り締まろうとする。／ある時、ライトニングがいつもの通りのんびりしていると、何者かに突然襲われてしまい、捕まってしまう。なんとその犯人はストラタだった!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9888c26-0203-4939-8ba6-b653204c0800.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a8972a1-3cb4-4c70-bca8-d606cec6cc31', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 22, '100079539', 'さよなら怪盗･前編／さよなら怪盗･後編', '先の爆ゲームの決勝以来、姿を消してしまったアジットを心配していたダン。そこでダンはなにか手掛かりはないかと、ストームのアジトへと行ってみることに。／怪盗をやめようと決心したアジットの前に怪盗の師であるストームが現れ、アジットに制裁を加えるため爆丸バトルを仕掛けてくる。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/261f00b5-ab42-4cde-a846-3952f6f6657d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9616aea-b432-4bb2-9ea4-f70b2ffb976e', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 23, '100079540', 'ハーヴィックの挑戦状･前編／ハーヴィックの挑戦状･後編', 'ある時、宇宙一の危険な男ハーヴィックがダンの前に現れて、「スーパーボーイチャレンジ」なるものに挑戦してみないかと誘う。／ハーヴィックによる恐怖のチャレンジは、徐々にダンとオーサム･ワンを追い込んでいく。そこでダンは最後のチャレンジを爆丸バトルにして、一発逆転を図る!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/163df83a-0351-491d-9a9a-2c46de99dead.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01d9dc05-bf5a-4db5-a1e4-ab8dc06f826c', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 24, '100079541', 'おかしなオーサム･ワン／狙われたカザミ', 'ベントンの所に向かったオーサム･ワン。そこで爆ゲーム東京ラウンドが開催されることを知らされる。大喜びするダンたちだが、だんだんおかしなテンションになってきて…!!／オーサム･ワンのせいで、自分の爆丸保護活動が上手くいかないと感じているソフィーは、次なる狙いをカザミホールディングスに定める。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c8b8178f-854b-410e-aef1-590f21363286.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f418813-fded-435f-b178-8f9acec8c75e', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 25, '100079542', 'ウィントンは宇宙人!／爆丸サッカー', 'ある時、ウィントンが自宅へ帰ると、母親からスタイルズ家は全員、地球以外の惑星からやってきた宇宙人だと告げられる。／ぺガトリクスは爆丸だけど、テレビでサッカーを見るのが大好き。それを見たリアはぺガトリクスに実際にサッカーをしてみようと誘う。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d135aef-0375-4d44-80b2-abde14933ad8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6d19421-011f-4f74-86ac-c623f83eca9a', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 26, '100079543', 'シュンのお願い／嵐の予感', 'ペットを連れていかないと買えない限定ポーちゃんグッズを買うために、シュンとライトニングが列に並んでいると、なんとそこにマキューが!／予定をキャンセルするときは必ず連絡してきたシュンが、練習を無断欠席する。何があったのか心配するダンたち。実はその時、シュンはマキューに捕まってしまっていた。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10d10bb4-3b10-4ffa-8ab5-d957c24c6d88.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85adf95d-8fa1-471a-bf89-fd49e7c5d3d0', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 27, '100079544', 'オーサム･ワン、日本へ行く／TOKYO珍道中!', '爆ゲーム東京ラウンド開催に当たって、ダンがなんと宣伝を担当することに。しかしその宣伝活動はとんでもなく忙しい!／爆ゲーム東京ラウンドの為、東京に滞在しているオーサム･ワン。東京の街を楽しみつくす!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff384aed-7df0-44fb-ab7a-94ec6ecee041.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd72c64b-55cf-481d-a9f3-c4ae48151d8c', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 28, '100079545', '開幕! 爆ゲーム･TOKYOラウンド／バトル･ロイヤル', 'とうとう始まった爆ゲーム･東京ラウンド! 一回戦目はなんと自分以外は全員敵というバトルロイヤル方式で行われることに。／ますますヒートアップしていく爆ゲーム･東京ラウンド一回戦のバトルロイヤル。果たして生き残るのは誰だ!?', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c2c5f744-c385-4be0-bc10-8d7886644686.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e24da2b9-eb6b-4b8c-84fd-865fed6c8898', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 29, '100079546', 'サバイバルレース!／メカノイド', '衝撃の結末を迎えたファーストステージ。ショックを隠せないオーサム･ワンだったが、息つく暇もなくセカンドステージが始まろうとしていた。／セカンドステージのフィールドに現れて、レースに参加する爆丸たちに突然攻撃を仕掛けてくるメカノイドたち。しかしそれもやはりハーヴィックの仕業だった。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f968e7a-40ee-4715-b280-6af304a6fdce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e0d2d300-3307-43db-ac11-c0256cb8eaf2', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 30, '100079547', '潜入! 謎の船／恐るべき計画', 'アジットがドローンによって連れていかれた先は何やら怪しい貨物船。しかもその貨物船にもメカノイドたちがいた。／貨物船の中で、違法デバイスの行方を追っていたマグナスと再会するダン。そのころアジットは、かつての師であるストームと激しいバトルをしていた。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c935e854-c0b2-4784-b41c-25501c4f6162.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c552dca1-b0df-4184-be53-739562cf9b55', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 31, '100079548', '波乱のセカンドステージ!!／衝撃のファイナルステージ!!', 'ある考えがあって、敢えて爆ゲームのステージから姿を消すアジット。その一方でハーヴィックは爆ゲームを乗っ取り、メカノイドまで登場させる。／爆ゲーム東京ラウンド、ファイナルステージ。ニンジャの変装をした謎の3人がリアたちの前に立ちはだかる!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68d334d0-c610-484b-b1a3-289016861c11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02d64c27-1751-41ca-b992-f7b90daa6240', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 32, '100079549', '東京壊滅!?／爆ゲーム･フィナーレ!', 'とうとう明らかになったハーヴィックの本当の狙い。ハーヴィックは爆ゲーム東京ラウンドに参加している沢山の爆丸を暴走させて、東京を壊滅させようとしていた。／東京まで間近に迫った大量の暴走爆丸たち。そこに更にハーヴィックが作り出した超巨大なメカノイドまで現れる。絶体絶命のオーサム･ワン。果たして東京を守ることが出来るのか!?', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f60693cc-2f2a-4a58-8bd1-0537eb376f19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('abf79038-6227-4dcd-b762-04efc4aa51d7', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 33, '100079550', '宇宙チャンピオン･ダン!／赤ちゃんは爆丸がお好き!', 'ダンの家にホームステイすることになったアジット。アジットはそこでダンの秘密を目撃する。ダンは寝相が悪く、いびきがうるさかった!! そしてその寝相が原因で大騒動が起こる!!／ある日、アジットとウィントンはボランティアで赤ちゃんのお世話をすることに。赤ちゃんの世話に慣れているウィントンに対しアジットは初めての経験で、てんやわんや!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5cebe85b-e81e-4862-9050-c99f4cc95558.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63f4f3c1-c1b0-42a8-b50c-5cc87aaceef0', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 34, '100079551', '友情タッグ／アジット密着24時!', 'わがまま娘のリオットが、パートナーとコンビを組んで戦う大会に出場することに。ただリオットにはコンビを組む相手がいなかった。そこでリオットはマグナスの妹、エミリーに目をつける。／リアがまだまだ謎の多いアジットに密着取材をすることに。そんな中、怪盗に憧れる男の子がアジットの前に現れる。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/738f5894-6929-4b07-bdd4-bbed67ab0f81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('727406b6-2867-49b1-9034-8023db0f8959', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 35, '100079552', '狙われたゴールド爆丸／ウィントンはおじいちゃん', '爆丸の中でもトップの力を持つゴールド爆丸を手に入れようと、グレートコアセルの前に現れたマキュー、ソフィー、エベレット･レイ、ストームの4人。そうはさせまいとダンたちが彼らの前に立ちはだかる!／メイズの不思議な力により、どこかへと飛ばされてしまったウィントン。しかもそこは急に年を取ってしまい、お年寄りになってしまうというとんでもない場所。おじいちゃんになってしまったウィントンの大冒険が始まる!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55e5711e-e748-4b46-94e4-8044f47934c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d635e83-9cbd-4d5f-9cac-ea4711866c84', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 36, '100079553', '黄金の記憶／迫りくるストーム', 'メイズの不思議な力によって、どこかへと飛ばされてしまったリアとアジット。しかしそこはアジットがかつて訪れたことのある場所だった。アジットは今まで謎に包まれていたゴールド爆丸たちとの出会いについて語り始める。／アジットとリアがメイズの中を移動しているとそこにストームが現れる。ストームは様々な方法でリアとアジットを追い込んでいく。しかしそんな2人のピンチにゴールド爆丸のゴーレーンが駆けつける!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/382898c5-a700-49af-a278-7abc0eeef23f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23c403a2-ae52-4961-87dd-ee49d88f23e1', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 37, '100079554', 'タリノとの再会／黄金の戦士たち', 'メイズの中を進むダンとシュンの前に、次から次へと地球ではありえない不思議な空間が現れる。そのなかでダンとシュンは驚きのゴールド爆丸と再会する。／メイズの中で様々な試練と困難を潜り抜けて、無事に再開を果たしたオーサム･ワン。しかしそこにゴールド爆丸を狙う、マキュー、ソフィー、エベレット･レイ、ストームの4人が現れる!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9edc7b01-e810-455a-8cb1-b1f90d22c433.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd8fad8b-a6a6-45f1-a685-72e136662f15', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 38, '100079555', '悪夢の始まり／悪ダン', 'ある時、ダンは眠りにつくと自分がとても乱暴者になっている悪夢を見る。翌日眠るとまた同じような悪夢を見るダン。しかもその夢の中にハーヴィックが現れて、ダンに爆丸バトルを挑んでくる。／ハーヴィックの仕業により、悪意に満ちてしまったダンはあらゆるところで悪さをして、人々を困らせる。そんなダンを止めるためにオーサム･ワンの仲間が立ちあがる!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6fdbd93-0bb0-47c9-b3f9-73b2f1dedfc6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1948d3d5-c21d-4463-8ca8-e3eb1068861f', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 39, '100079556', 'ダンを止めろ／黄金のドラゴ', 'ハーヴィックに操られ、ますます手が付けられなくなってしまったダンは、次の標的をベントンの会社であるダスク･インダストリーに定める。／力を増したダンの暴走は誰にも止められないところまで来ていた。しかしそのダンの目を覚まさせるために、永遠のライバルであるマグナスがダンに挑む。果たしてマグナスの想いはダンに届くのか!?', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/731dba3a-f594-4378-a6f6-503b9ce8af67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78fb75e1-bbc0-4e16-bb97-d4fca40602c5', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 40, '100079557', '怪しいのは誰だ!?／逃げ出した爆丸', '変装が得意なハーヴィックのせいで、オーサム･ワンのメンバーは、お互いをハーヴィックが変装しているのではないかと疑ってしまう。それを解決するためにアジットが提案したアイデアとは……?／ある時、オーサム･ワンのメンバーはオリバーという少年から、いなくなったブランカという爆丸を探して欲しいと頼まれる。ただオリバーには何か隠し事があるようで……。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a50881a3-534d-4d2b-903d-f8d4ab20b992.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2314013b-b3c9-41c4-b88f-46390899d898', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 41, '100079558', '爆丸大サーカス!!／エボニーの館', 'ある時、ダンとシュンは爆丸が活躍する爆丸サーカスを見に行く。二人とも爆丸たちの大技の連続に大喜び。ただこの爆丸サーカスには大きな問題があった。／路地裏で野良猫たちのボスに君臨するエボニーだったが、ある時、普段から争いの絶えない野良犬たちから攻撃を受けてボロボロにされてしまう。そんなエボニーの前にハーヴィックが現れる。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9748826-8c0b-4cdb-831b-5798bb435eb8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62d5902e-71ed-4311-af1b-cf71840024e2', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 42, '100079559', 'バトルアイランドの死闘!／強襲! マキュー軍団', '公開爆丸バトルといイベントの誘いを受けて、バトルアイランドへと向かうシュンとマサトだったが、公開爆丸バトルというのは二人をおびき寄せる罠で、待ち受けていたのはエベレット･レイだった。／カザミへの復讐に燃える男、マキューが新型デバイスを狙い、大勢の手下たちを引き連れてカザミの施設に潜入し、破壊の限りを尽くす。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4df9f5d0-4c95-4b4a-8202-dbc5aae75932.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b12a687-5e18-4603-8199-e2fee0304d5f', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 43, '100079560', '爆丸フードバトル／囚われたアジットとストーム', 'オーサム･ワンがいつも行っているバーガーショップで、だれが一番ハンバーガーを食べることが出来るのかを決める大食い大会が開かれることに。ダンとウィントンとライトニングは気合を入れて参加する。／ゴールドという人物の手によって、かつては師と弟子、今は敵同士となってしまったアジットとストームが同じ地下室に閉じ込められてしまう。果たして二人はどうなるのか!?', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c7e3948-bb4c-4431-8de8-4e6bc1d52a97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56a5d16c-f63b-41ff-ad67-2641443e66e9', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 44, '100079561', '爆丸チャンネル争い!／脅威! 5属性爆丸･セーブラ!', 'いつもは仲のいいオーサム･ワンの爆丸たち。ただ今回、どのテレビの番組を見るかという些細な事が原因で大喧嘩になってしまう。／街の人気スポットを破壊して回るハーヴィックを止めようとするオーサム･ワンの前に、火･風･光･水･闇の5つの属性を持ったクロス爆丸のセーブラが現れる!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eac7ce07-f74d-403b-9d96-1854194fac17.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80cfa9cd-5262-4a73-bcf8-acbc82a2c5db', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 45, '100079562', '古代爆丸の秘密／戦士の鎧･インフィニティ!', 'ハーヴィックの爆丸であるセーブラを圧倒した謎の爆丸の存在に驚くダンたち。その爆丸はガリリオンという古代爆丸で、ダンたちに古代爆丸が今まで歩んできた歴史を語り始める。／意見の対立するガリリオンに対し、自分の想いを込めてバトルするダンとドラゴ。しかしその時ハーヴィックがクラビッツのいる治安部隊の本部に現れて、セーブラを使って攻撃を仕掛けてくる!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9aa148c9-8a19-4c07-984a-fb459cb6ab09.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ffd7c21-692a-4e99-91c9-9dd4f5f5374a', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 46, '100079563', '罠にかかったマグナス／悩めるエミリー', '展示されている古代爆丸のレリーフを怪盗であるストームが盗みに来るはずと考え、マグナスが美術館で待っていると、予想どおりストームが現れて激しい爆丸バトルが始まる。／マグナスの妹、エミリーが前から仲良しのウェバムという爆丸に続いて、クリッシーという新しい爆丸を手に入れた。ところがウェバムとクリッシーは相性が悪いのか仲良くなれない。そこでエミリーはダンに相談することに。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21e0c5f9-0fbe-4d1c-b262-9657804d7ac8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52406788-edeb-4ced-9f81-219bddc03c70', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 47, '100079564', '偽オーサム･ワン、再び!／ハーヴィックを追え!', 'ある時、かつてダンたちがメイズで出会った偽物のオーサム･ワンたちがロスヴォルモスに現れる。ダンは偽ウィントン、偽リア、偽シュンたちと過ごし、偽ダンは本物のオーサム･ワンと行動をすることに。／アジットが街を歩いていると、そこにマグナスが現れる。マグナスの見つめる先にはアイス屋から出てくるハーヴィックが。マグナスに話を聞いてみるとハーヴイックを追っているという。そこでアジットはマグナスと共にハーヴィックの後をつけてみることに。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8be941e-fcad-4e1e-9f46-694ea156d6a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da15284a-6732-46e8-8214-57a348f42a52', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 48, '100079565', 'チコ、復活!?／究極のインフィニティ!!', 'オーサム･ワンとの間で繰り返される戦いの中で、だんだんと爆丸バトルに魅せられていくハーヴィック。そんなハーヴィックが次に目を付けたのは、メイズで眠りについているゴールド爆丸のチコだった。／捕らえられてしまったピラビオンを救い出そうとするオーサム･ワンたちだったが、ハーヴィックはそんな彼らの目の前で、セーブラとピラビオンを合体させて究極の爆丸を誕生させてしまう!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c457c630-5cb3-48f1-8074-6d6c495399f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dafc2c6f-a1e1-478e-a178-98b1c21cdfa8', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 49, '100079566', '僕たちの爆ゲーム!! (前編)／僕たちの爆ゲーム!! (後編)', 'ハーヴィックとの決戦を控えるオーサム･ワンは、皆を集めてオーサム･ワンの爆ゲームを開催することに。今まで出会った沢山の人々が集まって大会は大盛り上がり!! ／ますます盛り上がるオーサム･ワンの爆ゲーム。決勝目指してウィントン対アジット、そしてダン対リアという対戦が組まれ、激しい闘いが繰り広げられる!!', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/efb8a8c0-f73e-441e-b0eb-9f94837599ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02db7377-e17c-4b7f-9b10-07bcac67f96c', 'ab33fa86-1340-4c55-83b4-1cb3b53017a8', 50, '100079567', 'ハーヴィックの爆ゲーム／突入! ハーヴィックタワー', '突然、出現したハーヴィックタワーに驚く世界中の人々。そしてハーヴィックはオーサム･ワンに対して、地球とヴェストロイア、二つの星の運命を賭けたハーヴィック爆ゲームの開幕を高らかに宣言する!／いよいよ始まったハーヴィック爆ゲーム。しかしハーヴィックが待つタワーの最上階への道は険しく、凄まじい数のメカノイドや、困難な試練がオーサム･ワンたちを待ち受けていた。', '2021/05/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/793bbe11-2082-4664-900d-b7c7b730d8cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('aec3e327-1f8a-46e6-9d1f-6b776cc11f0c', '爆丸エボリューションズ', '', 'hulu', 'bakugan-evolutions', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8fb83ec-1d9c-43e1-b74e-57a6eba37a35.png?w=331&h=447&p=t', 'hulu', 2022, 0, 1, 'FINISHED', NULL, 146885, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a3e5062b-90dc-4bfa-b215-02b056b112ac', 'aec3e327-1f8a-46e6-9d1f-6b776cc11f0c', 'hulu-bakugan-evolutions-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccfc6a44-8a44-4359-80ad-aa6bc9540d05.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f345128-821c-4f27-985c-9720a78dd745', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 1, '100109101', '爆丸アカデミー／ルームメイト', 'ファウスト学園長から、爆丸の事を学べる学校である爆丸アカデミーへの招待を受けたオーサム･ワン。見学のつもりだったダンたちだったが、ファウストによっていきなり授業に参加させられ、ダンはアカデミーでNo.1の実力者であるアテナとバトルをすることに。／爆丸アカデミーには寮があって二人で一部屋を使うルールになっていた。ダンはウィントンとルームメイトになったのだが距離が近くなったせいで、お互いの癖や行動が気になりはじめ、とうとう喧嘩にまで発展してしまう。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccfc6a44-8a44-4359-80ad-aa6bc9540d05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9df4d5f0-ff40-4d5f-bb8b-5742053b9c0f', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 2, '100109102', '生意気なルームメイト／自由の為に', 'リアのルームメイトはあのリオット。しかし元気で生意気な事で有名なリオットの様子がなんだかおかしい。そんなリオットをチェットという自信家の男の子がなんどもからかう。リアはチェットを懲らしめるため、リオットとタッグを組んでバトルをすることに。／ライトニングが自由気ままに木の下で寝ていると、学園の風紀を取り締まるバーンスタブルに目をつけられ自分の部屋で寝るように命令される。それをライトニングが断ると、バーンスタブルはライトニングを捕まえようと追っかけてくる。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e67b2f71-dd79-42a8-b8d4-7cc343a4ccc4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ecde750-e329-41bf-a9a7-b7ea3a4722ba', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 3, '100109103', 'それぞれの個性／新しいスタジオD', '爆丸アカデミーは、爆丸に関する事ならすべて学べる世界で一つの場所。ただ人には得意と不得意があり、シュンとアジットの二人はそれぞれ苦手な授業があって、どうしたらいいか悩んでいた。／爆丸アカデミーでの生活が始まったオーサム･ワンだが、学校は規則が多くてかなり窮屈な思いをしていた。そこでオーサム･ワンは学校内にみんなに内緒でスタジオDを作って、自分たちの遊び場にしようとする。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1579cbea-95ef-46f5-a915-d5f389c5c744.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97e2c5d2-4819-4fe1-8896-c212445cb143', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 4, '100109104', 'マグナス先生／アテナの想い', 'ある時、爆丸アカデミーに新しい教師が赴任してくる。オーサム･ワンたちの前に現れたその新しい教師とはなんとマグナスだった!!／マグナスが成功させたスピードモードをマスターするために激しい特訓をするアテナ。そんなアテナに対し、リアはなぜそんなに真剣なのかを聞くと、アテナは自分の使命を打ち明け始める。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99c72c60-2544-46f3-8777-fefe0253cb6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('070435f1-b566-4979-860c-50f4accc9b92', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 5, '100109105', 'スターはつらいよ／ゲート･クラッシャーズ', 'インフルエンサーとして人気者になったカブーがスタジオDへとやってきた。ただカブーはなんだか怯えている。ダンたちが理由をきくと過激なファンにストーカー行為をうけているという。／地球とヴェストロイアとのありとあらゆる繋がりを断とうとする危ない集団「ゲート･クラッシャーズ」がベントンの研究所に現れ、占拠してしまう。オーサム･ワンは急いで研究所へと向かう。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1dc7e44-114b-43ba-a305-43fc81a53813.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f7775d5-7721-4774-a722-f97e9c02a779', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 6, '100109106', 'お願い! アテナ先生／実地訓練', 'なかなか思い通りにスピードモードに進化できないダンたちを尻目に、アテナはストレングモードとスピードモードを見事に使いこなしていた。その様子を見たリアはアテナの指導を受ける事を決意する。／爆丸アカデミーでダンたちが食事をしていると、ロスヴォルモス市街にエレメントエネルギーで暴走している爆丸が出現したとの報が入る。リアはまだスピードモードを習得していなかったが、アテナと共に出撃することに。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58819337-926f-400f-b055-fdb1a0bd2d75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23995336-72ac-4a36-922d-4b488f8f58fd', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 7, '100109107', 'ファルクロンとの再会／ライバル校にご用心!', 'ヴェストロイアへとやってきたオーサム･ワンの面々。しかし到着したと同時に「怪しい奴らだ」とそこに住む爆丸たちに捕まってしまう。しかもその爆丸たちの中には、かつて共に闘った仲間であるファルクロンがいた。／ある時、ウィントンとアジットのもとに、エレメント爆丸の使い方を教えるという「ハクスリー学園」という学校から案内が届く。怪しいと思った二人はその学園に潜入して調査を開始することに。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c11202f-f8b3-4f77-aeaf-57cbbabfc242.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4912ff0b-cc00-4efa-bf9f-655b0a07c755', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 8, '100109108', '本当のヒーロー／マグナスの授業', '爆丸アカデミーにいるダンたちのもとに相談があるとクラビッツが尋ねに来る。最近、ダンたちがいなくなったロスヴォルモスに、自らをヒーローと名乗る困った連中が現れるという。／なかなかスピードモードをマスターすることが出来ないダンは焦りに焦っていた。そんなダンを見て、マグナスが挑発してくる。ダンはマグナスとバトルするが、案の定、マグナスに対して手も足も出ない。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2e65476-f3c2-4770-aa62-026af50153ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08674dc1-da1c-482a-aa9b-0599129a777b', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 9, '100109109', '姿なき襲撃者／怪しいハケット', 'ある時、シュンは従兄弟のマサトに呼び出され、ゲートカードの生産拠点が何者かの襲撃で壊されたという事実を知らされる。犯人の目星はついており「ヤンセン･テック」という、最近、急成長中の企業だという。／ある時、街でアジットがゲームをしていると、以前オーサム･ワンの前に敵として立ちはだかったハケットが誰かと電話をしながらアジットの前を通り過ぎる。しかもその会話の内容が何やら物騒で…。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b608dc65-f0cf-43a3-8b81-19d2c20d7772.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('34db4ec3-e55c-4694-9dad-790435859bc6', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 10, '100109110', 'バクガニスト、再び／トゥロックスの超進化', '爆丸アカデミーに依頼があり、爆丸フェスで行われるエキシビジョンマッチで3対3のバトルを行う事になったダンたち。バトルを楽しみにしていたダンたちだったが、そこにバクガニスト、ソフィーが現れる。／進化するために頑張っていたウィントンとトゥロックスだったが、なかなか進化することが出来ない。そこでアテナに教えを乞う事にする。そんなウィントンとトゥロックスのもとに学園バトルというイベントの知らせが入る。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3ccda78-28a0-4796-b6a3-a45ed42e3dcd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('952c187a-1017-48ed-9346-0058d6522577', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 11, '100109111', 'ナノギアの力／真犯人を追え', '世間に爆丸のエレメント化の秘密をばらまいているのはマグナスではないか、という疑いを晴らそうとするダンとドラゴ。しかしマグナスは人気のない廃工場で怪しい連中たちと密談をしていた。／マグナスが残した言葉…「アカデミーが怪しい」という言葉を頼りに、学園内の怪しいと思われる人物たちの調査を開始したオーサム･ワン。そのターゲットには教師陣だけではなくアテナ･モンドも含まれていた。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/101fdbc8-1a91-4d59-abb9-30c4b81c47de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3df3ee4e-89a9-4e5f-a2e4-4acefc51fcf4', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 12, '100109112', 'ファウストの秘密／仲間と共に', 'アカデミー内外で起きていた不審な事件の犯人を追っていたオーサム･ワンのメンバーたちだったが、残された証拠を検証していくと思いもよらない人物が容疑者として浮かび上がってくる。その人物の潔白を証明しようとアテナが動き出す。／事件の犯人の動かぬ証拠をつかんだオーサム･ワンのメンバーたち。しかしどうしてもその事実が信じられないアテナは、一人でファウストの所に行って真実を確かめようとする。そんなアテナを止めようとダンはアテナにバトルを挑む。', '2022/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e167a8c8-eada-44c9-ac1d-3797e3bb68d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da64d561-80c8-452c-9701-3230d9c58d82', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 13, '100109113', 'ファウストとラース／消えない約束', '毅然とした表情でファウストの前にたつオーサム･ワンとアテナ。彼らを前にしてファウストがすべての真相を語りだす。ファウストの口から告げられたのは、あまりにも衝撃的な事実だった。／エレメントの力を我が物としたラースは凄まじいまでの強さを誇り、ファウストは正気を失い完全な悪に染まろうとしていた。この絶体絶命のピンチを爆丸アカデミーの教師、生徒たちが一致団結し、乗り越えようとする。', '2022/06/01 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab30f719-4017-4b29-99cb-cb5d38ff9add.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('86e16f5d-b46c-4234-992d-aeb9c3f107bf', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 14, '100121870', '新しい学園長／イタズラ大戦争', 'エレメントエネルギーを悪用しようとするファウストを、力をあわせて止めたオーサム･ワンとアテナ。その結果、学園に平穏が訪れたかと思われたが、傲慢で短気なショート先生が新しい学園長となってしまい、新たな嵐の予感が吹き荒れる!／新しく学園長になったことを良いことにショートは、今まで以上に生徒たちにいばり散らして大不評を買っていた。そこでダンとウィントンは、いたずらを仕掛けてショートを懲らしめる事にした。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/584adc24-9a11-4fcb-ad83-d3dd410d3fbc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e80ea4ce-e07c-49e6-adb9-7bbe56363bfc', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 15, '100121871', 'ピザ屋を救え／Mr.ジャッジはご勘弁', 'シュンとアジットはルーさんという人が経営するピザ屋のピザが大好き! しかしそんなルーさんの店の土地をヤンセン･テックの傘下の会社が無理やり奪おうとしていた。／ある時、学校の新しい生活指導員としてジャッジという名の男が赴任してくる。しかしこのジャッジという男、ショート校長や前任者のバーンスタプルよりも厳しくて面倒な人物だった!', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95b4d6e9-9f6e-456f-a39e-85ba30a08586.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81038f85-cc39-483c-b312-94de6b1d61ec', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 16, '100121872', 'ゲートクラッシャーズの狙い／カブーが学校にやってきた', '地球とヴェストロイアとの繋がりを断とうとする危険な集団、ゲート･クラッシャーズが再び現れた。彼らの手からエレメントホールを守るため、オーサム･ワンが出動する。／ある時、学校に突然、インターネットの世界で大人気のカブーが現れる。新しい学園長であるショートはカブーを追い返そうとするが、アテナはショートに反抗してカブーを守ろうとする。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e91c9c3-afd2-4565-a0b8-93cac40ad5b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7afd388-baa0-458e-8c52-89c85deec704', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 17, '100121873', '強いぞ! マスター･デザスター／幻の超古代爆丸', 'おっちょこちょいで慌て者のマスター･デザスターの連中が、急に爆丸バトルが強くなっていてビックリするオーサム･ワン。しかしこれにはなんだか裏がありそうで…。／爆丸アカデミーの授業の一環で採掘現場へとやってきたオーサム･ワン。採掘場にはノッケンハマー博士という責任者がおり、彼の説明によるとこの場所で超古代爆丸が発掘されたというが…。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9eee6888-2cbc-411e-870c-3bdc4322903f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ed31466-991a-4cbf-8bf6-e30e538f1b00', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 18, '100121874', '真の学園長は誰だ／激撮エレメンタル', '爆丸アカデミーにてオーサム･ワンの連中とアテナがチーム戦の練習をしていると、そこに前学園長であり、地球とヴェストロイアを危機に陥れた張本人であるファウストが現れる。／復帰したファウストに対して、良い感情を抱いていない生徒や先生が爆丸アカデミーから去ってしまうという危機的状況の中、街の中心部で巨大なエレメントストームが発生してしまう。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7bd2624-66a3-43c0-b65d-91c61b728d5b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66f40294-09a3-4210-8a45-87639a6349ef', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 19, '100121875', 'ベントン奪還作戦／マダムの危険なコレクション', 'ある時、オーサム･ワンの元に、ファウストからベントン･ダスクを乗せたエアシップが突然、姿を消してしまったという報が入る。ダンたちは急いでベントンの行方を捜すことに。／ある時、ライトニングは大金持ちで有名なマダム･デジレに気に入られ、婦人の家で飼われることに。住まいは豪華、出てくる料理はご馳走ばかりでウキウキのライトニングだったが…。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ead43a11-29f3-435b-880d-89d5d48e3048.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2266c6e6-bc38-472e-b0e8-a4dd7fd0c223', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 20, '100121876', '爆丸贋作家／クリスタルに恋して', '博物館へと見学へ行ったオーサム･ワン。そこには古代爆丸が展示されていたが、その古代爆丸が偽物だとアジットは気づく。本物は誰かに盗まれたと判断し、オーサム･ワンは犯人を捜すことに。／爆丸アカデミーにブラッケン帝が現れた。相変わらずリアの事が大好きなブラッケン帝だったが、クリスタル･ブルーを目にした途端、クリスタル･ブルーに一目ぼれしてしまう。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01ef41b4-882f-4ea8-a1b6-e0dcedbb351a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4f46568-b7e3-4ba0-b623-3790b50dc022', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 21, '100121877', '逆襲のワーグナー／最後のゲート', 'ヴェストロイアと地球を繋いでいるゲートをすべて閉じてしまおうと、ゲート･クラッシャーズの連中がゲートシステムの中枢であるゲートコントロールタワーを乗っ取ろうとする。／ゲート･クラッシャーズのリーダー、ワーグナーの巧みな作戦により、ゲート消滅の危機が間近に迫る。ヴェストロイアに残されたダンとドラゴは、果たして地球に戻ることが出来るのか!?', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc47fdda-c4a9-490c-bd51-9a5f4f416b6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bce52805-cb01-45e6-8720-f0157ecd3c98', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 22, '100121878', 'ショート爆丸アカデミー／師匠はマグナス', 'リフレッシュをする為、海へとやってきたオーサム･ワン。するとそこには学校から去ったショートと彼についていった生徒たちの面々が。彼らは砂浜で軍隊のような特訓を開始し始める。／ある時、偶然が重なり、マグナスがゲート･クラッシャーズの連中の手からマスター･デザスターのリッチーを助け出す。するとリッチーはマグナスに「弟子にして下さい」と言いだして…。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/215a5fba-6369-436b-945d-895579e257b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2351f514-22ec-431a-b8aa-8c5576c0a808', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 23, '100121879', 'ルームメイト･バトル／狙われたアカデミー', '爆丸アカデミーは現在、「ルームメイトの絆強化週間」中。皆がルームメイトと共同で作業する中、アジットのルームメイトだけがいまだに正体不明。そこでアジットはルームメイトを本腰を入れて探すことに。／とうとうゲート･クラッシャーズの連中が爆丸アカデミーへと攻め込んできた。彼らの狙いは莫大なエレメントエネルギーを蓄積しているダイヤモンド。ダンたちは必死に抵抗する。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/86fb5679-5662-4324-a6cd-5fbdf2a43afb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe6b7767-db2f-4e35-a20b-e4306d5160ca', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 24, '100121880', '共に闘う仲間／ワーグナーとの決戦', 'ファウストは爆丸アカデミーから去っていった先生と生徒に再び学校へと戻ってきて貰おうとするが、去っていった連中も中々首を縦に振らない。そこで爆丸バトルで勝った方の言う事を聞くという事に。／かつて因縁があったグレゴリウス･リードとゲート･クラッシャーズの連中が裏で手を組み、悪事を尽くしていたことを知ったオーサム･ワンは、敵のアジトに直接、乗り込むことにする。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6819d5cd-5dbc-4114-aed8-fdca079cc095.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6a99518-ed71-4e46-95eb-ddc25f91f926', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 25, '100121881', '切り札の完成／ラースの野望', '世界を危機に陥れてきたエレメントストーム問題を一気に解決できる機械、エレメントインダクターがとうとう完成した。しかしそのエレメントインダクターを狙って爆丸アカデミーが謎の集団の襲撃を受ける。／エレメントインダクターを守ろうとするオーサム･ワンと爆丸アカデミーの先生や生徒たちの前に現れたのは、なんと行方知れずとなっていたラースだった。ラースの出現により、アカデミーは絶体絶命の大ピンチに。', '2022/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c94fcfb4-75ab-4c31-b28d-93782dfff7d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80c0c8b7-5773-4138-8b15-aafcaa58975b', 'a3e5062b-90dc-4bfa-b215-02b056b112ac', 26, '100121882', '絶望の時／ドラゴノイドジェネシス', 'エレメントエネルギーを吸収して凄まじい強さを誇るラースの前になすすべがなくやられてしまうオーサム･ワンと爆丸アカデミーのメンバーたち。しかしこんなピンチでも誰一人諦めてはいなかった。／皆のエレメントエネルギーを受けて誕生したドラゴノイドジェネシスが、皆の想いを背負ってラースへと立ち向かっていく。その時、信じられない奇跡が起きた…!!', '2022/10/01 17:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7230ef79-7cb9-4caa-99c0-1501314b797d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3cfa7af9-78e5-4edd-a2ba-73fda0802e34', '爆丸ジオガンライジング', '', 'hulu', 'bakugan-geogan-rising', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45f2ef71-b811-4a33-ac79-0878ad710d33.png?w=331&h=447&p=t', 'hulu', 2021, 0, 1, 'FINISHED', NULL, 131096, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2bce0c61-5e81-44af-b20f-ad418fe999f6', '3cfa7af9-78e5-4edd-a2ba-73fda0802e34', 'hulu-bakugan-geogan-rising-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d28b84bd-dffc-4631-b75a-b2869cc44b71.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f633f70-9c22-4f57-ab7f-bcd9d1fe39dc', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 1, '100078244', 'ドラゴ復活!／ガラクタ島の爆丸', 'ハーヴィックとの激闘によって傷ついたオーサム･ワンの爆丸たちは、ヴェストロイアで休養中。寂しく思っていたダンたちは爆丸たちに会いにヴェストロイアに行こうとするが原因不明の事態が発生し、ヴェストロイアに行くことが出来ない。／ヴェストロイアに行けなかったり、バトルに負けた爆丸が消えたりと様々な異常現象が起きている中、オーサム･ワンは新しいモバイルゲートを使ってヴェストロイアに行くことに。ヴェストロイアに行くには行けたがなんとそこはガラクタばかりのごみの山で…。', '2021/04/02 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d28b84bd-dffc-4631-b75a-b2869cc44b71.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3515e602-a6eb-43b6-8021-3981493e31fd', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 2, '100078245', 'リアとフェネカ／ライトニングとフェラスカル', '新しく出会った爆丸、フェネカは元気すぎて街中を動き回った挙句、車とぶつかり車の一部を壊してしまう。フェネカを捕まえようとして追いかけていたリアは車の持ち主から多額の弁償代を請求されてしまう。困るリアの前に現れたのはあのエベレット･レイだった! ／リアたちの前に突然現れたクリスタル･ブルーという名の少女。彼女は不思議な力を持っており爆丸を探し当てたり、爆丸や人間の心を読むことが出来るというもっぱらの噂だった。そんな彼女の前で、ひょんなことからドラゴとフェネカがバトルをすることに。', '2021/04/16 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21c35500-0c43-46df-adce-bf0bb76d3d80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8cfccdd7-1c52-4025-9770-bb9a2ff751e6', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 3, '100078246', 'ピンチタウラーの秘密／俺の名はシャークター', 'ヴェストロイアのガラクタ島で出会ったピンチタウラーという爆丸は、穏やかでとってものんびり屋。しかしそのピンチタウラーには恐るべき秘密があった…!! ／マサトに海底にある研究所に呼び出されたシュンは、そこで「衛星防衛システム」という開発中の強力な兵器を見せられる。その兵器を狙って闇の商人であるマキューが研究所に現れる。', '2021/04/30 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61fb7b13-0c22-4f6d-9789-5552f76172aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5904047-37ce-4da3-8174-22151e2712e8', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 4, '100078247', '転入生･ハケット／マグナス再び', 'ある時、ダンたちの学校にジェニー･ハケットという女の子が転入してくる。ハケットは発明や科学が大好きで、同じく発明好きのウィントンと仲良くなる。ただ何やらハケットには秘密があるようで…。／ダンたちが学校に向かって歩いていると、爆丸のカブ―が、嫌がるエミリーを無理やりリュックに詰めてどこかへと運びだそうとしているところに出くわす。', '2021/05/14 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1346d2ea-a745-41e9-a127-84825aab502a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b375996-d17a-4996-95a2-7191193111a0', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 5, '100078248', 'ヒーリング･コアセル／伝説の存在', 'ある時、ドラゴが眠りについていると夢の中にピラビオンが現れ、神聖なものとして大切にされているヒーリング･コアセルが、悪意のある人間によってヴェストロイアから持ち去られてしまったので、取り返して欲しいと頼まれる。／ヒーリング･コアセルを奪った人物を追って、ウィントンとファルクロンと共に探索していると、怪しげな地下実験室へとたどり着く。そこにいたのはなんとハケットと、爆丸コレクターとして世界的な名声をもつグレゴリウス･リードだった。', '2021/05/28 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd656008-deac-4ef8-b519-cd52f372ea0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32c3ac67-21e7-44e6-b45a-96d44a987dd7', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 6, '100078249', 'ジオガン／アーキレオン', '伝説の存在であるジオガンの強さを目の当たりにしたオーサム･ワンたちは、自分たちもジオガンを手に入れようと探しに行くことに。するとおなじくジオガンを探すエベレット･レイやストラタたちと出くわす。／ある時、沢山の爆丸を積んだアーニマスの輸送機が忽然と消息をたってしまうという事件が起こる。オーサム･ワンは輸送機が消えた地点へと向かうと、そこには闇のビジネスに手を染めるマキューがいた。', '2021/06/11 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ba50784-39ae-43a9-8eea-78bc4dae01bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a19242a5-e9c9-4593-b688-bbcc8d24280c', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 7, '100078250', '謎の爆丸を追え／狙われたドラゴ', 'ある時、ロスヴォルモスでは夜の闇に紛れて連日、謎のブローラーと爆丸によって建物や道路が破壊されるという事件が起きていた。オーサム･ワンは街の治安を守るアーニマスのクラビッツから、その犯人を捕まえて欲しいと頼まれる。／今まで通り安全な爆丸バトルが出来る装置、ドローム･ジェネレータ―が完成したことを喜ぶオーサム･ワンたち。しかしその時、いたるところに金色の爆丸が現れて、ドラゴを呼び求めるという事件が発生する。', '2021/06/25 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f3a92d68-c8f1-49f6-b452-933f5e851cef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c28fdcf7-bf02-435d-9156-eb18dbd224e4', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 8, '100078251', '新しきニリアス／ゲートカード', 'スタジオDにて、スパーティリオンとのバトルで地中へと消えたダンとドラゴを心配するオーサム･ワンたちの前に、マグナスが現れる。マグナスは宿命のライバルであるダンとの決着をつけようとするが、肝心のダンがおらず…。／ある時、カザミの技術によってゲートカードシステムというドロームを安定的に発生させることが出来る装置が完成する。また同じタイミングでウィントンがヴェストロイアと地球を繋ぐモバイルゲートの開発に成功するが、その二つの発明をハケットが奪おうとしてくる。', '2021/07/09 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbc1e5e9-7fb3-4c44-b9b4-570b18b0ca57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3950b44c-e84d-43bd-a404-751d9bccf8f0', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 9, '100078252', '最高評議会の思惑／ドラゴの挑戦', 'ダンを追って、ヴェストロイアまでやってきたリア、ウィントン、シュン、ライトニングたち。しかし彼らがヴェストロイアに到着した途端、以前ドラゴとダンと戦ったゴールド爆丸のスパーティリオンが現れ、攻撃を受ける。／地球とヴェストロイアの未来の為に、ヴェストロイアのすべてを決定する機関である最高評議会に入ることにしたドラゴ。ただ最高評議会に入るためには試験をパスしなければならず、ドラゴは3体のゴールド爆丸とバトルをすることに。', '2021/07/23 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab68369b-449d-4b01-9398-8e3a38ba3f8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a20c254-6155-49d1-ae1e-c31143de44ad', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 10, '100078253', '下される決断／三つ子を探せ', '厳しい試練を通過して、ヴェストロイアの最高評議会の一員になったドラゴは、地球とヴェストロイアの未来を決定する会議へと出席する。地球とヴェストロイア、二つの星がこのまま一緒の道を行くか、それとも分離するか…果たして下された決断とは!?／バトルジャッジメントに向けて特訓を開始したオーサム･ワン。するとそこに若い夫婦が現れて、自分たちの子供である三つ子のラウディレッズが家出をしてしまったと告げられる。そこでオーサム･ワンはラウディレッズたちを手分けして探すことに。', '2021/08/06 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d19ab56d-c621-4727-b6c1-d1266020f847.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8765e515-e00b-4442-8e7c-97c66092951a', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 11, '100078254', 'わくわく爆丸ショー／歌姫クリスタル･ブルー', 'ある時、わくわく爆丸ショーというイベントが行われることになり、オーサム･ワンのみんなも参加することに。様々な競技が用意され、参加者は皆大盛り上がり! しかし各競技の優勝者の爆丸が何者かによって取り上げられるという事件が起こる。／全身をトゲトゲの衣装に身を包んだロックンローラー、アリソンとローレンのコンビによるバンド、ニードルズがいつの間にか世間で大人気に。オーサム･ワンがライブに行くと、なんとバンドのボーカルがクリスタル･ブルーになっていた!', '2021/08/20 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70967a10-2ca6-495f-805f-33bb3cd19d4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d81ae2b7-cce9-42f4-9b26-3004d27cb266', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 12, '100078255', 'マグナスの旅／ビーチでの爆丸バトル', 'ダンを追ってヴェストロイアを彷徨うマグナスは、沢山のカブ―たちがいる村へとたどり着く。その村には何故かクリスタル・ブルーがいて、マグナスはこの村に重大な危機が迫っていると知らされる。／バトルジャッジメントでの水のエリアであるアクイラでのバトルに向けて、シュンが苦手とする水泳の特訓を海辺でしていると、サーファーたちから爆丸バトルを挑まれる。', '2021/09/03 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09c1d153-ac97-4fed-932b-5d8e91d079a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('daeb7537-c31e-4897-8993-c679b0670bc3', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 13, '100078256', 'マッドマスク団／マッドマスクのボス', 'ウィントンが開発した爆丸にまつわるエネルギーを感知するアプリ「爆レーダー」に謎の巨大なエネルギー反応があり、オーサム･ワンはその発生源を突き止めようとする。すると巨大な地下下水道にたどり着き、そこでマスクをかぶった怪しい一団と遭遇する。／今、ロスヴォルモスでは「マッドマスク」と呼ばれる一団による貴重な爆丸の化石ばかりを狙う事件が多発していた。そんな中、オーサム･ワンはアーニマスに所属しているクラビッツから会社が所有している爆丸の化石をマッドマスクの手から守って欲しいと頼まれる。', '2021/09/17 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5e7769e-225a-4eef-a7be-b984b0a0e978.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9cce7eb5-882c-4386-a944-fc708676508a', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 14, '100078257', 'ゴミ山のプリンセス／謎のUMA･ラママン', 'しばらく掃除をしていなかったせいでスタジオDはゴミだらけ。そこでオーサム･ワンはスタジオDの大掃除をすることに。掃除をすると大量のゴミが出たのでゴミ捨て場に捨てに行くと、そこには自らをゴミ山のプリンセスと名乗るべサニーという女の子がいた。／最近、配信する動画の視聴数が伸び悩んでいるため、特別な企画をしようと考えるオーサム･ワン。そこで最近、話題になっているロスヴォルモスの森に現れるという噂のラママンという未知の怪物を捜しに行くことに。', '2021/10/01 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40e3d184-806b-4a4f-8686-8d15b76890ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64f8b47f-b1a1-4c41-96cd-fd03926dd3a5', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 15, '100078258', '噂の看板猫／オーサム･ワンの大冒険', 'ライトニングを見ると、いつもおいしいお肉をくれるステーキ屋さんが大ピンチ。エボニーが看板猫になった向かいのお寿司屋さんにお客を奪われていたのだ。ライトニングは大好きなステーキ屋さんを守るため、エボニーとの勝負に挑む。／ブローラーと爆丸が一緒になって楽しめる体験型アトラクション、ヒマジンアドベンチャーにやってきたオーサム･ワン。それぞれピッタリの職業になりきって、ゴールを目指して突き進む!', '2021/10/15 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53b8e368-5770-47c0-a6ff-d4801b5c755b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7cd20ba6-42cf-4697-80db-c91f13a32d8c', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 16, '100078259', '思い出の味／バーチャルバトル', '爆丸バトルの特訓に励むオーサム･ワンは、アジットの思い出の食べ物である、レンズ豆のカレーを作ってあげることに。しかし、材料の豆がどうしても足りない。やっとの思いで豆を見つけたシュンの前に現れたのは……? ／ウィントンとベントンが開発したバーチャルシミュレーションで、爆丸バトルの特訓に励むリアとフェネカ。勢いに乗ってバーチャルのタランを相手に激闘を繰り広げるが、次第にマシンが暴走してしまい……。', '2021/10/29 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c9e3a40-e0bb-4b11-ad6e-6b2ab0de4389.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5c12098-fb77-4804-a763-fba2e1f20f00', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 17, '100078260', '火山島SOS／パニック･イン･ピンポイントパーク', 'バトルジャッジメントに向け、オーサム･ワンが次なる特訓の場所として選んだのは、なんと火山! 熱気あふれるバトルを繰り広げるオーサム･ワンの面々。しかし、ダンたちのいる火山が突然噴火した! どうなる、オーサム･ワン!?／ダンたちが火山で爆丸バトルの特訓をしていた、その頃……ウィントンは、全然言うことを聞いてくれない弟と妹のお世話で大忙し! そこで、兄としての威厳を見せようと、ピンポイントパークに連れて行くが……?', '2021/11/12 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1afa61da-6e52-4fce-95ad-eea1abf16df0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b013974-df6b-40ac-a607-907ed022b7d6', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 18, '100078261', 'アンダーグラウンド･パニック／ウィーアー、エグジット!', 'バトルジャッジメントのダーカビアでのバトルの特訓の為に、環境がダーカビアによく似ている地下資源の採掘場へとやってきたダンたち。特訓が順調に進む中、採掘場の奥底では怪しい影がうごめいていた。／かつて色々な悪さをしてオーサム・ワンと衝突を繰り返したエグジットというチームがあった。しかし今は反省して普通のチームとなっていた。そのエグジットの連中がある時、ダンたちの元を訪れる。何やら相談事があるという。', '2021/11/26 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99fbccb5-fa35-4157-bd3a-c481b7f2e21f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63368671-e76d-4cad-992f-dfac334f711f', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 19, '100078262', 'バトルジャッジメント開幕／アルティメット･ヴァイロック', 'とうとう始まった地球とヴェストロイアの運命を決めるための戦い、「バトルジャッジメント」。必ず勝つと意気込んでヴェストロイアへとやってきたダンたちの前に怪しい人影が現れる。／バトルジャッジメント一回戦。オーサム･ワンからはアジットが出場するが、相手はなんといきなりのヴァイロック! ヴァイロックに隠された恐るべき力が今、明らかになる!', '2021/12/10 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9d8474b-aef3-426a-bbb6-6101bc69c684.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d826b81-cbcf-4780-9cf6-a157625fa445', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 20, '100078263', '水の都アクイラ／激流を超えて', '次なるバトルジャッジメントの舞台である水の世界『アクイラ』へとやってきたダンたちは、ピラビオンにとある場所へと案内される。そこにはなんと、かつてオーサム・ワンのパートナーだったトゥロックスやハウルカーといった数々の爆丸たちが眠っていた。／アクイラでのバトルジャッジメントではダン対クリスタル・ブルーの戦いが始まろうとしていた。しかしダンとドラゴが会場に現れない。その時、ダンたちは海の中でアーティファクトを探していたのだが、激しい海流に苦戦していた。', '2021/12/24 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6218a8f-5529-4847-b300-86b9d3772e30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1c3bcb8f-2ca9-4de2-9226-f7293edb850e', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 21, '100078264', 'ウィントンの秘策／ベンターナの試練', '次なるバトルジャッジメントは、風と大地のエリアであるベンターナが舞台。ダンとドラゴがベンターナのアーティファクトを探しに行く中、ウィントンとマグナスの熾烈なバトルが始まる!／ベンターナのアーティファクトを探すダンとドラゴだったが、巨大な食虫植物やツタに行く手を阻まれ、アーティファクトを手に入れる事が出来ずにいた。一方、その頃ダンを除くオーサム･ワンのメンバーたちは、バトルジャッジメントで激しい闘いを繰り広げていた。', '2022/01/07 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a04e4b8-fc0c-4a52-ba31-43623bcca3ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1064742-f621-4970-acd2-f3e08e6a3bac', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 22, '100078265', '人と爆丸／ハオラーのアーティファクトを追え', '次のバトルジャッジメントは空中に都市が浮かぶハオラーが舞台。初戦はダン対ハケットのバトルなのだが、ハケットはパートナーであるクラスティリオンに、ドラゴの攻撃をわざと受けさせる。一体、ハケットの狙いとは!? ／空を飛ぶドラゴの背に乗り、ハオラーのアーティファクトを探すダン。しかしドラゴが今までの疲労が原因で、突然ミニ爆丸になってしまう。空中へと放り出され、地上へと落ちていってしまうダン。果たしてダンの運命は!?', '2022/01/21 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c583cbb-72a6-4f32-b21f-fc1dc529093f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40e2a994-59e2-437f-924a-f7fcf22240b3', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 23, '100078266', 'マグナスの願い／ダーカビアの試練', 'ハオラーのアーティファクトを手に入れた瞬間にゲートが開き、遠くへ飛ばされてしまったダンとドラゴ。飛ばされた場所は前にも来た、不思議な力で身体が幼くなったり、お年寄りになってしまう場所。しかもそこにはマグナスとニリアスもいた。／ダーカビアのアーティファクトを探すダンとドラゴの前に、アーティファクトを手に入れる方法を知るニンジャトンという爆丸が現れる。ニンジャトンの話では試練を潜り抜けなくてはならず、失敗すると永遠に闇の中を彷徨う事になるという。', '2022/02/04 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/23175797-0cf0-4dcf-8557-51819331c38b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c723c8a-9b11-4d05-aabb-1ad642900f66', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 24, '100078267', '炎の絆／闇を越えて行け', '今度のバトルジャッジメントの舞台はドラゴのふるさとであるパイルール。ダンとドラゴはアーティファクトを探すため、パイルール最大の火山である「ガンス･サータス」を訪れる。するとそこにはドラゴの幼馴染であるベヒモスという爆丸がいた。／ダンとドラゴはバトルジャッジメントにてエベレット･レイとオキシドクスのコンビとバトルすることに。ダンたちは戦いを優位に進めるが、エベレットがジオガンのゴーストビーストを呼び出すと、とたんに劣勢に追い込まれてしまう。', '2022/02/18 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97b643a7-eb82-4fd6-b18c-eb266fa58966.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35f54eba-fac8-4bfd-aede-baa8b2b1bd08', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 25, '100078268', 'ダンVSマグナス／究極の果て', 'バトルジャッジメントもとうとう決勝戦。ダンとドラゴVSマグナスとニリアスという因縁のバトルが始まる。デバイス無しでコミュニケーションを取れるようになったマグナスとニリアスはあまりに強く、ダンとドラゴはいきなりの大ピンチに!! ／ジオガンと合体してアルティメット化したヴァイロックは、さらに６つの属性クリスタルからもパワーを吸収しようとする。なんとかそれを止めようとするダンたちだが、究極の力を手にしたヴァイロックの前に手も足も出なかった。', '2022/03/04 17:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7d0e92db-3dec-4f65-bf10-66449723c7d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0ff7ae44-f65b-4c88-b886-902b61637c9f', '2bce0c61-5e81-44af-b20f-ad418fe999f6', 26, '100078269', 'ジオフォージドラゴノイド／未来を繋ぐもの', '【最終話】ジオガンたちと合体し、ジオフォージドラゴノイドへと進化したドラゴは、アルティメットヴァイロックに果敢に挑んでいく。しかしアルティメットヴァイロックはあまりに強く歯が立たない。／ジオガンの、爆丸の、オーサム･ワンの皆の想いを力に変えて、アルティメットヴァイロックに対して最後の勝負に出るダンとジオフォージドラゴ。果たして勝負の行方は!? 地球とヴェストロイアの運命は如何に!?', '2022/03/18 17:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c43b59b7-1e60-4023-81bf-4b9a1e2df32c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8a45cfa2-3282-499b-9206-325af9930e7e', '爆丸バトルプラネット', '', 'hulu', 'bakugan-bp', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad04f0a6-d10d-426e-a09c-300baf264ca5.png?w=331&h=447&p=t', 'hulu', 2019, 1, 1, 'FINISHED', NULL, 108852, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('eed02e54-1647-4e65-b4a5-b42b14debe4c', '8a45cfa2-3282-499b-9206-325af9930e7e', 'hulu-bakugan-bp-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3c114d0-9def-4154-ad6c-e568d739ab02.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cf0f018-45c9-4e10-9b70-0ca1e6bb5c91', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 1, '100032968', '爆丸ブロー!!／爆丸バトル!!', 'ダン、ウィントン、リアは動画サイトにおもしろ映像をUPするのが大好き!! ある時、12年前にあった大事件「グレートコリジョン」の謎を調べて映像に撮ろうとしたところ、爆丸という不思議な生き物と遭遇する。／爆丸と出会ったオーサムワンは大はしゃぎ! 爆丸について自分たちで色々調べていると、マグナスという謎の少年がダンに爆丸バトルを仕掛けてくる!', '2019/04/02 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3c114d0-9def-4154-ad6c-e568d739ab02.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dff4aa81-3cb9-488a-9bea-5e444fe675c4', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 2, '100032969', 'バーガーパニック!／ラウディーレッズ', 'ドラゴ達がとにかくバトルをしたがるので、ダンたちはちょっとお疲れ気味。そんな時、爆丸を利用し悪い事をするイケナイ奴が現れる。／ある日、幼い三人兄弟が爆丸を手に入れたのは良いものの、爆丸を使って街のみんなに迷惑をかけまくり! ダンが先輩として注意しようとするが…!?', '2019/04/09 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9824fcf8-689e-48f1-bb4e-f0c2456a14e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d71f4957-3143-4d4a-ac04-519dd57ae3ce', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 3, '100032970', 'シンディウス／パートナー', 'ある日、皆の公園をマルコという少年が自分の爆丸を使って独り占めしてしまう。怒ったダンはマルコに爆丸バトルを挑む !!／ウィントンはいたずら好き。パートナーの爆丸でもあるトゥロックスにもいたずらを仕掛け、その様子をネットにUPし楽しんでいると、トゥロックスが怒っていまい…。', '2019/04/16 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6801df0f-218e-448d-9abf-eaf3b8f7614f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4562cd69-b456-4d9a-9bb9-ea76d092856e', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 4, '100032971', '爆丸禁止令!／ぺガトリクス', 'ある日、ダンたちが爆丸と一緒に遊んでいると突然、爆丸が制御不能に。その被害を受けた人々により、爆丸禁止運動が起こってしまう。そんな最中、ものすごい危機が街に迫っていた…!!／ある日、リアがネットにUPする動画を取っていると、ぺガトリクスという爆丸と出会う。そんなリアの元にリオットというお嬢様から爆丸バトルの挑戦状が届く!', '2019/04/23 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/346b1dca-0110-4cee-aaac-bb152c09355a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa7e52a4-7a56-4225-92b2-fe0c0be6dd93', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 5, '100032972', '新しいメンバー／爆丸を狩る男!', 'ある日、オーサムワンに入りたいという少年二人がダンたちの前に現れる。ダンはその少年たちがオーサムワンに入るのに相応しいか入団テストをするが…。／ある日、ボビーという男の子がベアーという熊の爆丸と遊んでいると、ベアーが突然暴れ出し、どこかに行ってしまう。ダンたちはボビーからベアーをさがして欲しいと頼まれるが…。', '2019/04/30 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82c22b9d-4f43-48f6-94a0-67ec0fb2dd43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ba8e72b-36f7-48ad-8c7a-29e7bc81b46a', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 6, '100032973', 'おしゃべりアーチュリーン／スター誕生!', 'ライトニングの新しい爆丸、アーチュリーンはおしゃべりで凄く変わった性格。その為、ライトニングだけではなくオーサムワンも様々な騒動に巻き込まれ、てんてこまい!!／巷で有名になってきたオーサムワン。テレビ局からオーサムワンに密着取材をしたいとの依頼が入る。しかしなぜだかダンばかりが目立つ展開に。浮かれるダンにリアやウィントンは不満がたまる一方で…。', '2019/05/07 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce4a8212-6ef1-44fb-9b66-54cdae27c377.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c419aab-b558-42e3-8618-1685020d5dad', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 7, '100033998', 'エグジット／とりもどせ! 僕たちの場所', 'ダンたちの周りでは今、チーム･エグジットが大人気でオーサムワンも押され気味。そんな中、エグジットのメンバーたちが爆丸バトルの大会を開き、ダンたちに挑戦状を叩きつけてくる。／ある日突然、ダンたちがいつも利用している爆丸フィールドが銀行の管理下におかれ、立ち入り禁止になってしまう。ダンたちはみんなの爆丸フィールドを取り戻そうとするが…。', '2019/05/14 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c788f9b1-39c1-4e87-a8e8-34db3574a267.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67fa8ed8-c7e3-4cde-93da-75b230ea01ad', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 8, '100033999', 'ルピセオン／どうしたんだ、ダン!?', 'ある日、オーサムワンの皆が自分に誕生日のサプライズを仕掛けようとしていることに気づいたウィントンは、そのサプライズを避けようとして森へと向かう。するとそこで今まで見たことのない爆丸と遭遇する。／ある日、いつものようにオーサムワンの前に現れたダンだけど、普段と比べて何か変。ダンはいい奴なのに、今日は嫌みっぽくて悪口ばかり。一体、ダンに何が起きた!?', '2019/05/21 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1fa2f7c5-1f8c-452a-a340-ae8dc2307370.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9e44963-5af9-4103-a4ba-e3639d4ace1b', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 9, '100034000', 'ドロームの光／爆丸家庭教師', 'ある日、突然、ある場所にて沢山の爆丸が発見されるという事態が起きる。子供たちは我先にと爆丸を集め始めるが、その爆丸たちは普通の爆丸と少し様子が違っていた…。／ある日、お金持ちの夫妻から息子の家庭教師をして欲しいと頼まれるダンとオーサムワン。しかしその息子というのがとんでもないやんちゃな子供で、ダンたちに爆丸バトルを挑んでくる!!', '2019/05/28 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8cd4f84e-7b1c-41f8-ac71-7f50604f9219.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('862900a9-b123-4087-bf08-92242076afb4', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 10, '100034001', 'マグナス／謎のSOS', 'ある日、ダンが公園でドラゴと一緒にいると、今まで見かけたことがない少女が現れて、ダンたちにこれからここに来る男と爆丸バトルをしないでとだけ言い残して去っていく。／ある日、ダンたちオーサムワンの元に身元不明のメールが届く。そのメールを開いてみるとそこには一体の爆丸が大勢の兵士に痛めつけられている映像が。それを見たダンたちはその爆丸を助けに行くことに。', '2019/06/04 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c72736d1-0838-44eb-a84c-0a7caeb48e52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c996e9fc-8079-4d4d-bec0-ed9220172582', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 11, '100036749', 'カザミからの使者／サムライ･シャルゴ', '日本の大企業の社長の御曹司であるシュンは高級ホテルで暮らしていた。しかしある日、突然そこに日本からトシとケーコとコーダというシュンの父親の会社の部下たちがやってきて、シュンを無理矢理、日本へと連れ戻そうとしてくる。／ある日、ダンとシュンが爆丸バトルをしていると、侍みたいな恰好をした人物、シャルゴ･ローニンという人物が現れて、2人にバトルを挑んでくる。', '2019/06/11 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de3605a4-9be9-4754-ad5f-e569633950c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10ed3fb3-182e-414e-b9e1-661550421669', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 12, '100036750', '真夜中の秘密／シュンは渡さない!', 'ある日、ドラゴは夜中にどこからかともなく聞こえる不思議な声で目を覚ます。ドラゴはその声に導かれて外に出てみると、他の爆丸たちもその不思議な声に導かれ街中を移動していた。／ある日、シュンの父親でカザミホールディングスの社長であるイチローが訪ねてくる。嫌がるシュンをよそ目に無理やり日本へと連れ戻そうとする。', '2019/06/18 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78cb9d2c-6dec-4ea3-850a-2c035669d8fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7af4abed-b5ea-4abc-9fed-533ba179ae09', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 13, '100036751', '不敵な挑戦者／巨大な陰謀', 'ある日、ダンたちが子供たちに爆丸のレクチャーをしていると、一人のクリンと名乗る少年がダンにバトルを挑んでくる。ただそのクリンという少年、何か裏があるようで…。／謎多き人物、ベントン･ダスクのオフィスへと招待されたオーサム･ワンのメンバーたちは、そこで爆丸に関わる巨大な陰謀の話を聞かされる。', '2019/06/25 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db645f21-016c-4958-a82c-774cf03cc8d6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('049fa99b-e023-422f-97fc-9a89fcb286c4', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 14, '100038509', 'メイズへ／謎の生命体', 'ある日、オーサム･ワンはフィダラスという爆丸から、メイズという地下の迷宮に数多くの爆丸が捕まっているという話を聞かされ、救出へと向かう事に。／巨大な地下迷宮･メイズの中で、迷ってしまったダンたちは出口を求めてさまようが、次々と奇想天外なエリアが現れてダンたちは大混乱!', '2019/07/09 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a850402e-10b5-452a-879a-0dc78f5be745.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('954b13c8-1fbc-43ef-b2a8-493fb22fffeb', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 15, '100038510', 'ちびっ子ジャングル／オーサム･ワン対オーサム･ワン', 'メイズをさまよう中で、ダンたちはジャングルのような密林が生い茂るエリアへとたどり着く。そこでなんとダンたちは不思議な力によって小さな子供になってしまう。／地下迷宮から外へと出られる扉を見つけて喜ぶオーサム･ワン。しかしダンたちを待っていたのは元の世界とそっくりだけど、なにかがちょっとずつ変な世界。一体、この場所の秘密とは…!?', '2019/07/16 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/331adfc6-7722-465e-8608-14229a0fcbed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd46c416-9bc9-4fa1-a8d5-92ace3b92b24', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 16, '100038511', '邪悪な敵／ハイパードラゴ', 'メイズを進む中、疲れがたまったダンたちはひと眠りする事に。するとドラゴを除いたオーサム･ワンの爆丸たちが何者かに導かれ、どこかへと行ってしまう。／ドラゴたちが感じていた力の元へとたどり着いたダンたち。そこにはコア･セルという不思議な物体があった。しかしそこにバクゾンと、バクゾンを率いる謎の爆丸が現れる。', '2019/07/23 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bba4c01-2f7a-499c-9578-16fdb8896c74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7738795-703f-47a0-b609-123a8d97a3fc', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 17, '100039705', 'メイズからの脱出／なまいきカブ―', 'メイズに入ったっきり出てこないオーサム･ワンを心配していたベントンの前に、ライトニングとストラタだけが現れる。果たしてダンたちはどうなってしまったのか!? ／メイズから帰還したリアに爆丸がくっついていた。その爆丸はカブーといって見かけは小さい熊の形をしていてとても可愛いが、話すと物凄く口が悪い。', '2019/07/30 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f22193cb-3fcb-4d6b-921a-67e6fc703b84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6e780d8-cecd-45f7-b827-e06fb811bee0', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 18, '100039706', 'カザミからの刺客／ハイパーハイドロス', 'メイズでの経験を経て、とても強くなったシュン。そんなシュンの前に従兄弟のマサトが現れる。／シュンを連れ戻そうとするマサトからシュンを守ろうと、オーサム･ワンの皆はマサトの強力な爆丸であるサーペンテーゼに立ち向かっていく。', '2019/08/06 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19b70aca-d25e-44ce-a2ec-132c0ec12113.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e19747f6-50ab-4f60-a630-b1297d4d5f75', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 19, '100039707', 'パパのメモリー／デュラン、再び', 'ぺガトリクスを進化させるためダンやシュンたちに爆丸をブローさせ、進化の瞬間を映像に収めようとするリア。そのリアの撮った映像をリオットが勝手に持ち出そうとする。／メイズで一回進化したきり、それ以降進化できていないドラゴ。そのことを気にしていたダンの前にダンとバトルして有名になりたいデュランという少年が現れる。', '2019/08/13 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37ab5e58-af38-4fcc-84f1-d8135c70c9e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a9ab58a-f4cf-4a0c-88a6-5fe7a378735d', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 20, '100039708', 'コアセルを探せ! ／操られたウィントン', '爆丸を進化させるため、ダンたちは色々な方法を試していた。するとウィントンがコアセルの力を利用することが進化に繋がると気づき、コアセルを探し出す道具「コアセル･キャプチャー」を開発する。／ダンとケンカをして気まずい思いをしているウィントンの前にトリップ大佐が現れて、爆丸にではなくウィントンにBマインを着けて操ろうとする。', '2019/08/20 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c0a3de3-08a9-45dc-a1bb-0297abdc9ebb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f13aa1e-2a3d-4cdf-bbbb-dc3a4074ec61', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 21, '100039709', '英雄の秘密／ライトニングの冒険', 'ドラゴを進化させることが出来ずに落ち込むダン。そんなダンの目に、マグナスが爆ローズというチームを結成し皆のヒーローとなっている映像が飛び込んでくる。／ある日、ライトニングは懐かしい匂いを感じる。その匂いに釣られていくとメイズへとたどり着く。そしてそこでライトニングが目にしたものとは…!?', '2019/08/27 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74a23185-e34d-452d-80a7-210359432dcf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cd3d688-bb85-496a-bbaa-191b786f3dfa', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 22, '100041422', 'オーサム･ワンVS爆ローズ／逆襲のダン', '実際は違うのに火山の噴火から街を守った英雄として皆から称えられるマグナスと爆ローズの面々。彼らには隠れた目的があった。コアセルをアーニマスの物にしようとしていたのだ。／ドラゴを進化させることが出来ずにいたダンは元気を失くしていたが、気持ちを切り替え、マグナスとハイパーニリウスの前に立ちはだかる!', '2019/09/03 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a86450ed-8620-43e1-ac33-7f8ed2bf08c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6758655d-a982-4877-b76f-196fe3039769', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 23, '100041423', '危険なお誘い!?／潜入開始!!', 'コアセルの管理をアーニマスがするということになり、コアセルを悪事に利用されないかとダンたちが心配していると、アーニマスからオーサム･ワンを雇いたいという連絡が入る。／アーニマスの中へと案内されたダンたちオーサム･ワンは、アーニマスの最新の爆丸の為の設備の数々に圧倒されてしまう!', '2019/09/10 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/097bfada-3ed9-415a-ab9f-51a82dd5d4bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a00c7c0-2509-4c64-85ce-151a77bb92c9', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 24, '100041424', 'コアセルを守れ!／アーニマスの謎', 'アーニマスからオーサム･ワンに与えられた次の任務はコアセルの護衛。ヘリコプターでコアセルを空中輸送をしていると、マサトが現れ、コアセルを奪おうとしてくる。／あいかわらずアーニマスに雇われているオーサム･ワンは、来る日も来る日もデータを採取されてばかりで少し飽きてしまう。そこでコアセルの様子を探りに行くことにする。', '2019/09/17 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9691e136-0c92-44f4-a29d-05aba233e3f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63871bd9-476e-4baa-b9ec-ea9751e94ce2', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 25, '100041425', '爆丸暴走!／いつわりのユートピア', 'アーニマスで働くオーサム･ワンの元にフィオナから、ねぎらいのプレゼントが届く。浮かれるダンたちの横で、ドラゴたちが謎のノイズに苦しめられる。／「爆丸と人間が仲良く暮らせるユートピアを作る」というから、アーニマスのいう事を聞いていたダンたち。しかしアーニマスが本当に企んでいたことが明らかになる。', '2019/09/24 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d197a399-81c8-4b24-b3b0-82cfc09691d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afd62e72-04f5-4168-a8ea-ef918a0a97f5', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 26, '100041426', 'オーサム･ワンVSアーニマス 前編／オーサム･ワンVSアーニマス 後編', 'アーニマスの手によって、ドラゴやトゥロックスといった爆丸を捕らえられてしまったオーサム･ワン。取り返そうとするにも警備が厳重で難しい。悩むダンたちの前にベントンが現れる。／アーニマスによって操られているドラゴ達は、ダンたちのいう事を全く聞かずに攻撃を仕掛けてくる。ベントンはアーニマスの爆丸たちを操るコンピュータにハッキングをしてドラゴ達を解放しようとするが…。', '2019/10/01 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa739376-5304-43b5-af12-31429c2b7bbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57683d76-889c-4eb7-8faa-0afbc8014c73', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 27, '100043226', '新たなる冒険／キノを取り戻せ!', 'ベントンの指令により、世界中に散らばるコアセルを探すことになったオーサム･ワン。ウィントンが開発したコアセルを発見することが出来る機械、コアセルキャプチャーがまず反応を示したのは南にある島だった。／怪しい男たちによってさらわれてしまったキノを取り戻すため、男たちの基地がある小島へと向かうダンたち。そこでダンたちが目撃したのは、爆丸や人間たちを無理矢理働かせている光景だった。', '2019/10/15 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62d3cfa2-e434-4f30-bd7b-4a0eeca94583.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9560c6ff-6870-4378-b9ad-c5c7b312df22', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 28, '100043227', 'いきなりサバイバル!／少年国王･ブラッケン', 'オーサム･ワンの元に「ブラキスタン」という国から、ネットで一番面白い映像を作った人を決定する「クール･ムービー･グランプリ」というイベントの招待状が届く。ちょうどその時、ベントンからコアセルの反応がブラキスタンから出たとの連絡があり、偶然の一致に喜ぶオーサム･ワンだったが…。／ブラッケン帝の王宮へと案内されたオーサム･ワンはその豪華さに目を見張る。国王のブラッケン帝は前からオーサム･ワンの大ファンで、大歓迎を受ける。だけどなんだか様子がおかしくて…。', '2019/10/22 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81ed3da4-1710-499a-85cd-e5f011d37572.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6579b1ba-4603-491c-ad59-c7c4fb4f5895', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 29, '100043228', '変装大作戦!／リアが結婚!?', 'ブラッケン帝を怒らせてしまったオーサム･ワンは、城から抜け出し街へと逃げ込む。そして追いかけてくるブラキスタンの将軍、キャラスとその部下たちから変装をして逃れようとする。／ブラッケン帝から申し込まれたプロポーズにOKしてしまうリア。ダンたちはリアをブラッケン帝から救い出そうとするが、逆に捕まってしまう。果たして本当にリアはブラッケン帝と結婚してしまうのか!?', '2019/10/29 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57208199-bfdf-4f90-80c2-80428c5c57cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d86d957-dbf6-46d8-a4b6-bd38735632a6', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 30, '100043229', '復活のマグナス／ゴールド爆丸･ピラビオン!', '次のコアセルの場所が分かるまでユカタン半島のリゾートで、羽を伸ばすオーサム･ワン。そのころマグナスは、妹のエミリーの面倒を見ながらダンに負けた時の記憶に苦しめられていた。／ベントンからの指令を受け、コアセルがある場所へと向かうオーサム･ワン。するとそこには大きな古代遺跡があった。早速、遺跡の中へと入ろうとするダンたちだったが、突然、マグナスが現れる。', '2019/11/05 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8c97b85-1572-43d1-ab1a-f948d15802f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1bd2c165-6b1c-4916-bb45-c4ce4973b588', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 31, '100044835', 'カザミの島／執念の男', 'ベントンからの指令が入り、コアセルの反応がキャッチされた場所へと向かうダンたち。しかし一人、シュンだけが浮かない顔をしている。その理由には次の目的地が関係していた…。／シュンの父親であるイチロ─から食事へと招かれて行ってみると、そこには豪華な日本料理の数々が。しかしディナーは重々しい雰囲気で、とても楽しめる感じではない。', '2019/11/12 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a69d765-eb93-4b00-b405-e0cffbb82e85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80b69972-7c86-4f8d-9f29-21bc2a2f052a', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 32, '100044836', 'マサトの記憶／暴走する力', 'ダンたちと共にカザミの島を訪れているドラゴは、カザミホールディングスが開発したコアセルエクストラクターという、コアセルの力を引き出すために造られた機械が暴走して島を崩壊させてしまうという夢を見る。／コアセルエクストラクターの力によってサーペンテーゼは進化し、喜びを爆発させるマサト。しかしその時、コアセルエクストラクターはその巨大な力を制御できず暴走を開始する!', '2019/11/19 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24aef1b1-8457-42dd-8eeb-ff278bc1bb85.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8b744ff-24e3-4990-936d-59f1d0ec6883', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 33, '100044837', '謎のメッセージ／チコ、再び!!', '手軽にメイズに行くことのできる道具、モバイルゲートの開発により順調にコアセルのセットアップに成功していくオーサムワン。ただその裏では恐ろしい事態が進展しつつあった…。／ある日、ダンとドラゴはコアセルが黒く染められていくという不吉な夢をみる。そのことをオーサム･ワンのみんなに話していると、ベントンから通常と違うおかしな信号を出しているというコアセルを見つけたという連絡が入る。', '2019/11/26 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9aae9e7d-5661-4497-9879-e88bec1f0e9e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19e0dabd-3784-4ec9-a5e7-67187d983656', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 34, '100046306', 'おかしなストラタ／残された手がかり', 'ベントンから新しいゲートが遊園地で発見されたとの連絡が入り、遊園地へと向かったオーサム･ワン。するとゲートからストラタが飛び出してくる。しかしストラタの様子がどこかおかしい。果たして何があったのか?／仲間だと思っていたゴールド爆丸のピラビオンから攻撃を受け、ショックを受けるオーサム･ワン。また攻撃を受けるかもしれないという恐怖を乗り越え、ダンたちはもう一度、ピラビオンに会いに行くことにする。', '2019/12/03 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/759ad6f3-fb70-4ce0-827f-530d49deb092.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af817514-1c5d-4167-b1ec-7b9cb9a69cd8', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 35, '100046307', '新たなるゴールド爆丸／誇りの仮面', 'ゴールド爆丸の力によって、メイズから地上へと一瞬で移動させられてしまったダンたち。しかしダンたちはそれにもめげず、再びメイズへと戻りコアセルを守ろうとする。／コアセルを巡り、ダンたちとマグナスの激しいバトルが繰り広げられる中、意識を無くしたゴールド爆丸が超強力な技を四方八方に繰り出してくる。', '2019/12/10 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bf5aaa7-b1c3-40d4-941f-94bac36e9a84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05994988-3a29-4082-92b1-d9cd26afbbd7', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 36, '100046308', 'アルティマニリアス／操り人形', 'コアセルの力によって、マグナスのデバイスは異形な形態となり、パートナーであるニリアスもアルティマニリアスへと進化する。そしてその強さは圧倒的で、ダンたちはまるで歯が立たない。／Ⅴウィルスに感染したコアセルの力を吸収したマグナスが、メイズから地上へと脱出してしまう。ダンたちはⅤウィルスの拡大を防ぐため、マグナスを追う。', '2019/12/17 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c412742-0a82-4e81-877e-79fb02068755.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff2236d0-3589-41cb-add6-0b2a25ba58af', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 37, '100046309', 'コアセル攻防戦!!／アルティマドラゴノイド', '激しさを増すコアセルの攻防戦。その戦いの中でマグナスが先手を取りコアセルの中へと入っていく。それを見たベントンはダンたちに非情な命令を下す…!／Ⅴウイルスに感染してしまい、チコの操り人形となってしまったマグナスを取り戻すために戦うダン。絶望的な状況だったが、ダンは決して諦めない。', '2019/12/24 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6b5b05b-e859-4ad7-b789-650f25d09f08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0eb812ad-a381-40a7-a8e5-e72ea9aab5eb', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 38, '100047719', '黒い影／お菓子なベントン', 'メイズでの激動のあと地上に戻ってきたダンたちは、チコに負けないためにバトルの特訓を開始する。一方、ベントンは爆丸の事やヴェストロイアについて調べ物をしていた。／ベントンが今までに集めたデータを分析して、謎の爆丸チコが何を企んでいるのかをオーサム･ワンに説明していると、ベントンの体を異変が襲う。', '2020/01/07 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60413f16-5433-4db7-ad0b-8a7e3e2d02e3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df018988-06f5-4716-b3c5-f64990d89b80', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 39, '100047720', 'アゲアゲ! ブラキスタン!／逆転不可能裁判!!', 'ベントンから取り付けたコアセル･コネクターが故障したらしいので、ブラキスタンへ行ってもう一度コネクターを取り付けて欲しいと頼まれたオーサム･ワン。ブラキスタンに到着するとダンたちを驚きの光景が待ち受けていた!!／ブラッケン帝に無実の罪で捕らえられてしまったダンたち。身の潔白を証明するために裁判へと挑む!!', '2020/01/14 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02240149-8642-497a-8498-610c8ab45cb3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32655c3c-8ec4-4c22-8b3e-d2dc6a171ebd', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 40, '100047721', '海上大決戦!!／ピラビオンの真意', '世界中に散らばるコアセルにコアセル･コネクターを順調にセットアップしていくダンたち。しかしそこにゴールド爆丸であるピラビオンが現れ、ダンたちに攻撃を仕掛けてくる。／仲の良かったゴールド爆丸のピラビオンが、ダンたちを攻撃してきたことについて理由を考えるダンたち。そこでダンたちはピラビオンに会って直接聞くことにする。', '2020/01/21 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56b6a9c3-cf13-426c-8d56-37604e18c1c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d8681e3-c58e-43c9-94d9-43dfeeb87223', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 41, '100047722', '正体をあばけ!／チコベントン', 'ピラビオンと話をしたことにより、ベントンの行動を怪しいと思い始めたオーサムワン。真相を確かめるために、ベントン相手に一芝居をうつことにする。／チコに取りつかれてしまったベントンを救い出すためにダンたちが訪れた場所は、なんとアーニマスのオフィス。そこで姉であるフィオナに弟のベントンに迫る危機を話す。', '2020/01/28 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b41c5343-02f7-4e6a-a4c2-213f93c8bf22.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('175c45c0-080f-4d57-bad4-aa9f3d3aaddc', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 42, '100047723', '爆丸回収運動!?／取り戻せ! 元気と爆丸!', 'チコベントンがオーサム･ワンを苦しめようと次にとった手段は、爆丸に対して嫌な噂を流し、親たちを心配させて子供たちから爆丸を取り上げさせる事だった。／爆丸をダスク･インダストリーに取り上げられてしまった子供たちに協力を呼びかけるダンたち。しかし子供たちはなかなかダンたちに協力しようとはしない。', '2020/02/04 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e00925d-38a6-4ff0-b24e-d6f9d4547442.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebecd598-2d0a-42e9-b2c5-bab35df2f3f8', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 43, '100049334', '私がプリンセス!／カザミの城', 'ますますひどくなっていく爆丸回収隊に対抗するために、仲間を増やそうとするダンたち。そこでリアはリオットの所に行き仲間になるように誘ってみるが、なぜかそこにはブラッケン帝もいて…。／チコによる攻撃がますます勢いを増して、徐々に追い詰められていくダンたち。そんな意気消沈しているオーサム･ワンの元にイチロー･カザミから日本に来るようにという連絡が入る。', '2020/02/11 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f006e8e-16fa-48b3-b1bb-15c8f333c28d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae20b840-6da7-4c8a-a9cc-d75a28e1fefe', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 44, '100049335', '帰ってきたマサト／要塞陥落', 'バクゾン対策用に開発された新装置、ネオエクストラクターを動かそうとするイチロー･カザミとオーサム･ワンの前に、サーペンテーゼに乗ったマサト･カザミが現れる。／捕らえたゴールド爆丸を犠牲にして、莫大な力を生むネオエクストラクターを破壊しようとするマサトの攻撃をとっさに防いでしまうシュン。その行動にシュンは自分自身で驚いてしまう。', '2020/02/18 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99500bea-4728-4601-84a4-060e4baece62.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcba6a65-6bee-45e3-b894-f02dfcb7a250', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 45, '100049336', 'ゴールド爆丸･ゴーレーン／タリノ救出作戦!', '人間たちの都合で捕らえられ、パワーを吸い取られてしまったゴールド爆丸のゴーレーンは、ダンたちに対して敵意をむきだしにする。そこでダンたちは誤解を解くためにゴーレーンに爆丸バトルを挑む。／タリノが捕らえられているというダスク･インダストリーへと向かうオーサム･ワン。行く手を阻む障害を乗り越えてタリノの元へとたどり着くと、Vウィルスに感染してしまったタリノの姿があった。', '2020/02/25 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af9fb455-650e-481f-8a9d-b0d3945020e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc39c2af-0723-4db8-9d11-8e00e80e8e06', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 46, '100049337', 'たった一つの方法／タリノの中へ', 'チコとの死闘を経て、つかの間の休息を取るオーサム･ワンとドラゴたちパートナー爆丸たち。そこにピラビオンとゴーレーンが現れ、タリノを救うためのアイデアをダンたちに提案する。／ピラビオンとゴーレーンの力により、タリノの内部へと侵入することに成功したダンとドラゴ。しかしタリノの体の中は、ダンたちの想像をはるかに超え、Ⅴウィルスのせいでダメージを受けていた。', '2020/03/03 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7b0e696-dd8c-414c-bb9d-9abe7bbcda70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24142475-9d60-46e4-a78b-841e6fd097e5', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 47, '100049338', '帰らない二人／チコの真実', 'タリノの生命反応が消えたのを感じ取ったピラビオンとゴーレーン。リアやウィントンたちはタリノの中に入ったままのダンとドラゴが無事かどうか尋ねるが、ピラビオンたちは答えることが出来ない。／タリノの精神世界へと飛ばされていたダンとドラゴはそこで死んだはずのタリノと出会う。そしてタリノはダンたちにヴェストロイアの、そしてチコに隠された真実について語り始める…。', '2020/03/10 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ba31b43-d9eb-4c3f-85dd-be7ac3dd5cae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f053fa0f-ae70-4a90-ac4d-d595c97c7784', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 48, '100052244', 'カザミを継ぐもの／エグジット、再び!', 'チコの手によって世界中のコアセルがVウィルスに感染してしまったかのように見えたが、一番重要な存在であるグレートコアセルはまだ感染してはいなかった。オーサム･ワンがグレートコアセルをチコの手から守ろうと駆けつけると、そこにはシュンの父親、イチローがいた。／ダンとドラゴがタリノの体内から戻らない中、他のオーサム･ワンのメンバーたちはゴールド爆丸と共に、凄まじい数の手下を引き連れて迫りくるチコたちの軍団から、グレートコアセルを守ろうとしていた。', '2020/03/17 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4bc2acd7-bb09-43a8-9867-bff4d1a56cd4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9d710e8-8158-46a5-84cd-22e04d817711', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 49, '100052245', '最後の戦い／ドラゴノイドマキシマス', 'とうとうグレートコアセルの前に現れたチコたち。グレートコアセルを巡る最後の戦いが始まろうとしていた。しかし皆の希望であるダンとドラゴは、いまだ姿を現さない。／皆が必死になって守ろうとしたグレートコアセルはⅤウィルスに感染し、ゴールド爆丸のゴーレーンも、Vウィルスに汚染されてしまう。もはやチコに対抗する手段は、ダンたちには何一つ残されてはいなかった…。', '2020/03/24 12:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c124313a-a083-46da-b84a-48d3b2ebdcd9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b463889-c37e-4882-b7cf-99089bb48073', 'eed02e54-1647-4e65-b4a5-b42b14debe4c', 50, '100052246', '光／絆', '【最終話】伝説の戦士であるドラゴノイドマキシマスに変化したドラゴと、チコとの戦いは熾烈を極める。徐々にドラゴがチコを追い込んでいくと、チコは邪悪な力を結集し、真の姿へ変化する!／チコ･ギガンテスの力は強大で、伝説の戦士と言われたドラゴノイドマキシマスも歯が立たない。果たして、このまま世界は滅びてしまうのか!?', '2020/03/31 12:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea142dfa-7fa4-46a7-b144-7f12cc8339dd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7284b65c-bfa3-4533-a5f7-cf6fcd8b18c9', '爆丸レジェンズ', '', 'hulu', 'bakugan-legends', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66e65dc4-0b1a-428e-aaa7-5059f12514f0.png?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 169826, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d592c3f6-06c7-4b9f-a70b-765bf5477d66', '7284b65c-bfa3-4533-a5f7-cf6fcd8b18c9', 'hulu-bakugan-legends-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9d459cc-2a04-4a39-8810-0ccdcffdffc3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecec553f-48d3-45d0-9fe0-2a76c4b444b9', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 1, '100141399', '新たなる危機／ノヴァの力', 'ある時、強い力で結ばれていた地球とヴェストロイアが離れてしまうという人間と爆丸にとって深刻な危機が発生する。その危機を解決しようと、ダンたちはヴェストロイアに向かうが、そこでスワームと呼ばれる大量の爆丸の群れに襲われる。／ノヴァリフレクターの力を使って地球へと戻ってきたダンとアテナ。ノヴァの光に触れた事でオーサム･ワンの爆丸たちはノヴァの力を取り入れてパワーアップする。その新たな力でスワームへと挑んでいく。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9d459cc-2a04-4a39-8810-0ccdcffdffc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75dc7523-9a07-46b6-93b9-dfc16fcd74e6', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 2, '100141400', '究極の爆丸、ハノージ!!／ノヴァコア', 'スワームを倒したオーサム･ワンたちの前に、かつてヴェストロイアを滅亡寸前にまで追い込んだ伝説の爆丸にして、究極の爆丸であるハノージが現れる。ハノージはその凄まじいパワーで宇宙すべてのエネルギーを我が物にしようと企んでいた。／ハノージとバトルジャッジメントで地球とヴェストロイアの運命を決める事になったダンたちは特訓を開始する。すると特訓中に今まで見たことのない新しいコア、「ノヴァコア」が現れる。このノヴァコアを使えばハノージに勝てると考えるダンたちだったが…。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/217f6c54-dc11-4e45-bf3b-1036952d2486.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('456f102b-6bf3-4683-bfbd-f7c2de160eed', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 3, '100141401', 'ノヴァ技マスター大作戦! (前編)／ノヴァ技マスター大作戦! (後編)', 'ノヴァコアを使ったノヴァ技をマスターしようとするオーサム･ワンだったが、なかなかコツが掴めない。そこでオーサム･ワンのメンバーは各々が自分で特訓してノヴァ技をマスターすることに。／ノヴァ技をマスターしようと奮戦するオーサム･ワン。コツをつかんだメンバーもいたが、まだまだ試行錯誤しているメンバーたちがいた。ダン、シュン、ウィントン、アテナがそれぞれのやり方でマスターを目指す。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2104f70f-f9df-4bdf-9937-4196a0839419.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b93aebe-b9a9-424d-bcaf-fc2e079a4928', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 4, '100141402', 'ダンは大器晩成!?／俺たち爆丸カウボーイ!!', '各々の特訓の結果、見事にノヴァ技をマスターしたオーサム･ワン。ただダンだけは未だにマスターすることが出来ずにいた。焦ったダンは、皆がマスターするきっかけとなった特訓方法を片っ端から試してみる事に。／ゴールドラッシュの時代を体験できるテーマパーク「ゴールドロデオパーク」へとやってきたダンたち。しかし施設内は寂れていて様子がおかしい。するとどこからか助けを求める子供の声が聞こえる。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8ea4c6e-63ba-4d31-a571-5da9c5ac764d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05c9a930-31db-4eca-a39d-10eb53028545', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 5, '100141403', '南の島での1回戦!!／時の川での対決', 'とうとう始まった地球とヴェストロイアの運命を賭けたハノージとのバトルジャッジメント。オーサム･ワンがバトルの場所に指定されたマーリエ島へと向かうと、そこにストームが現れる。／バトルジャッジメントの第二試合は、舞台をヴェストロイアに移してのバトル。しかもその場所というのは、そこにいると急に歳をとったり、若くなったりする時の川と言われる場所だった。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9827622-27e5-454c-b2fe-eef26b3aacce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fec1698a-ea68-401d-9ad0-d040e97f9731', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 6, '100141404', '地下牢の鉄仮面／ブラキスタンを救え!', '次なるバトルジャッジメントの舞台は、オーサム･ワンと交流のあるブラッケン帝が治める国「ブラキスタン」。しかし到着すると同時に、ブラキスタンの兵士たちによって捕らえられてしまう。／ブラキスタンの首都に超巨大な砂嵐が迫る中、シュンとアジットVSマキュー、エベレットという対戦のバトルジャッジメントが始まった。吹き荒れる砂煙にいつものようなバトルをすることが出来ない。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32167549-1bda-4d85-9f73-0a76d52d9af3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b57fb28-b692-4214-9998-9a4edfdd98ff', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 7, '100141405', 'スワームを捕まえろ!／カブーのハッタリTVショー', 'ヴェストロイアに行くための手段として、スワームを捕まえようと考えていたオーサム･ワンのメンバーの前に、丁度よくスワームが目の前に現れる。しかしそのスワームは小さくて、ちょっと変わったタイプだった。／配信者として世界的な有名人になったカブーを取り上げるテレビ番組に呼ばれたオーサム･ワンのメンバー。しかしカブーが番組内で言うエピソードは自分に都合のいい嘘ばっかりで……。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d77a8ba1-1516-4d79-aa87-c93e49af133f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('715852e1-2b74-4b03-af32-bc606bb12502', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 8, '100141406', '来襲! チコ&ヴァイロック!／ソフィーとの海上バトル!', 'ハノージは自分の城に来たオーサム･ワンに腹を立て、バトルジャッジメントをロスヴォルモス市街での開催をいきなり宣言する。しかも対戦する相手はチコとヴァイロックという強力過ぎる爆丸たちだった。／ロスヴォルモスがスワームによって荒廃してしまった事に心を痛めていたダンたち。そんなダンたちにバクガニスト、ソフィーから連絡が入る。ソフィーはダンたちに港を封鎖したと告げる。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c8a5d19c-e2c4-49d3-8545-8f4c1aa893f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0edd7898-c4d6-4eda-b412-254d552e8217', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 9, '100141407', 'ねじれた空間／エネルギーを取り戻せ!', '今度のバトルジャッジメントの舞台はダーカビアにある洞窟。空間がねじれている場所で、ダンたちは思う通りの動きが出来ずに、トリップとチコのコンビに大苦戦する。／ハノージによって奪われたエネルギーを、ブンブンを使って少しづつ元の場所へと戻していく事が出来る装置を開発したウィントンとアテナ。さっそくユカタン半島にある遺跡近くのエリアでその装置を起動する。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4294fcbf-7d10-48bc-b8ed-942042680130.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64d633b5-930d-44ac-ba42-566485b77253', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 10, '100141408', '復活のファウスト／犬と猫の宇宙大バトル!', 'ハノージによって今回のバトルジャッジメントの舞台に指定されたのはヴェストロイアの都市、オーロポリス。そこで対戦相手としてダンたちの前に現れたのはリードと、なんと因縁深きファウストだった。／外に散歩に出ていたライトニングとハウルカー。すると突然、光があたりを包み気が付くと宇宙船の中へと連れてこられる。宇宙船には犬の姿をした宇宙人がいて、ライトニングたちにとある頼みごとをしてくる。', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9132596-09fc-4c39-b7c9-f1a697b54517.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55097a55-5140-4998-b6a6-7b2873cc57d4', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 11, '100141409', 'ハーヴィック参戦!／決戦! ダンVSマグナス', '次なるバトルジャッジメントの舞台としてハノージに指定されたのは、ヴェストロイアのハオラーにある空中都市。そして対戦相手としてオーサム･ワンの前に現れたのは、宇宙一のお尋ね者、ハーヴィックだった!!／ダンがバトルの特訓をしていると、ハノージによってヴェストロイアのパイルールとダーカビアの狭間へと連れてこられる。そして次の対戦相手としてダンの前に現れたのは、なんとあのマグナスだった!!', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b31b4ba-3eca-4ae5-bdbb-fa1fe2fc2969.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ab01a99-3310-4e81-9101-ef1e9ab89f67', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 12, '100141410', 'マグナスの狙い／ノヴァ爆クロス! ドラゴ×ニリアス', '熾烈を極めるダンとマグナス、ドラゴとニリアスのバトル。強力な必殺技の応酬が続き、どちらも本気で相手を倒そうとしているようにしか見えない。果たしてこのバトルの行く末は…!?／ベントンやファウストの協力もあって、とうとう完成したノヴァリフレクター。しかし、ハノージがノヴァリフレクターを破壊しようと大量のスワームを向かわせる。オーサム･ワンは無事に守り切ることが出来るのか!?', '2023/06/01 00:00:00', 1480, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3438d5aa-c4df-4d92-a6e5-b32848131710.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae7f65b2-0fa3-4cc8-9fa4-b9eecc112e5d', 'd592c3f6-06c7-4b9f-a70b-765bf5477d66', 13, '100141411', 'アルティメットハノージ／未来への爆丸ブロー', '【最終話】ダンたちにとって切り札であったノヴァリフレクターの力がハノージに吸収されてしまい、アルティメットハノージへと進化してしまう。もはやダンたちに残された方法はなかった…。／一発逆転をかけて、ハノージを再び封印しようとするダンとドラゴ。しかし、ハノージはあまりに強大でダンたちの思惑通りにはいかない。しかしダンたちは地球とヴェストロイア、人間と爆丸の未来の為に困難へと立ち向かっていく!!', '2023/06/01 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4475d66d-6fdd-4f5b-b17e-7ff95f8b7288.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8fe0450b-6f04-4812-8371-89bec7814e63', '八男って、それはないでしょう！', '', 'hulu', 'the-8th-son-are-you-kidding-me', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4b591b1-db8f-4215-bcc3-a3eafd47846e.png?w=331&h=447&p=t', 'hulu', 2020, 1, 1, 'FINISHED', NULL, 106319, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2bb53e65-40f6-46d0-88d7-eacd13d55b83', '彼女、お借りします', '', 'hulu', 'kanokari', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43494339-d76c-4e47-bb8e-daacd6e4b0c9.jpg?w=331&h=447&p=t', 'hulu', 2020, 2, 1, 'FINISHED', NULL, 113813, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', '2bb53e65-40f6-46d0-88d7-eacd13d55b83', 'hulu-kanokari-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d2ef07b-014f-40ee-9b50-8f422c2b45f5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22d67953-f5b0-4d72-853b-3e85965a59fa', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 1, '100059355', '「レンタル彼女」－レンカノ－', 'ダメダメ大学生･木ノ下和也は、生まれて初めてできた彼女にたった1ヶ月でフラれてしまう。ショックで枕を濡らす和也だったが、やけっぱちになり、スマホで偶然見つけた“ある方法”を使って女の子とデートをすることに。「和也くん、だよね?」―翌日、待ち合わせ場所に現れたのは、清楚可憐な美少女･水原千鶴だった。', '2020/07/16 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d2ef07b-014f-40ee-9b50-8f422c2b45f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ef24aa5-6878-405f-b7c7-f290c3008da1', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 2, '100060114', '「元カノと彼女」－モトカノ－', '千鶴にはもう頼らず、会うこともしないと決意した和也。しかし、偶然にも同じ大学で再会し、さらに同じアパートのお隣さんだと判明する。一切の交流なし、干渉なし、詮索もしないと千鶴から釘を刺された和也の元に、祖母･和から電話がかかってくる。「今からそちらに行く。千鶴姫を呼んでおいてくれんか?」。別れたと言い出せない和也は…!?', '2020/07/23 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15b60b1c-0e5b-4758-a172-237bd30236d4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64ed8a96-a65e-426b-9933-13f640bd9adf', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 3, '100060318', '「海と彼女」－ナツカノ－', '「ウチ近いから…休んでったら?」。飲み会からの帰り道、声を掛けてきたのは元カノ･麻美だった。彼氏がいると言ったのは嘘だったと麻美から聞かされ、和也はこのチャンスをものにしようと奮闘する。数日後、飲み会のメンバーと海に行くことになった和也は、この一泊二日の旅行で麻美の気持ちを確かめて、ヨリを戻すと決心する。', '2020/07/30 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2174315c-3e89-4abe-90e3-a3dfa201d60f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb4b9b66-8639-43b5-870c-be7b506f2871', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 4, '100061063', '「友達と彼女」－マサカノ－', '岩陰で麻美に突然抱きつかれ、キスされた和也! 固まっている和也に麻美は「我慢できなくなっちゃった……」と告げる。海岸へ戻っても妄想を爆発させる和也だったが、そこへ和から来週退院するという電話が入る。これで好きな時に千鶴に会いに行けると喜ぶ和に対し、これまで騙していたことを改めて実感した和也はついに千鶴と“別れる”ことを決意する。', '2020/08/06 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f4e7112-6833-425f-9df9-0c861ba8a80b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a73252d-8ad1-4d25-b976-f340a682a55c', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 5, '100061448', '「温泉と彼女」－イマカノ－', '千鶴が目を覚ますと、そこは小島の浅瀬だった。倒れている和也を見つけた千鶴は、海に転落した自分を助けるために和也が飛び込んだことを思い出す。千鶴は和也に呼びかけるが、反応がない。「冗談やめてよ!! 起きてよ。ねえ!!」―目を覚まさない和也に、千鶴は顔を近づけ…。一方、木ノ下家では和の快気祝いに山奥の温泉宿に行く計画が立てられていた。', '2020/08/13 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/266ade4b-2000-4f43-8383-db48780d903e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad51baf3-84c3-47fe-8c86-a83c5f7e0f88', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 6, '100061861', '「彼女と彼女」－カノカノ－', '「この部屋で、寝ればいいじゃない」―温泉宿の同じ部屋で千鶴と一泊することになった和也。ドキドキが止まらない和也だったが、ふと千鶴は自分のことをどう思ってるのかが気になる。数日後、和也は友人の栗林から彼女ができたと報告され、話の流れで千鶴とダブルデートをすることに。当日、栗林から紹介されたのは超美少女･更科瑠夏。和也が偶然、街でぶつかった女の子だった。', '2020/08/20 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a799fd32-2f9f-4d8a-83a4-6bb0c44887c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c20a96ed-22c5-4be4-a03f-53d279d73eda', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 7, '100062628', '「仮カノと彼女」－カリカノ－', '千鶴がレンカノだとバラさせないため瑠夏を尾行していた和也だったが、逆に待ち伏せされてしまう。和也が一切口外しないと約束させようとする中、瑠夏は自分の秘密を明かす。日が変わり、和也が大学で栗林と待ち合わせをしていると―「あ! 和也さーん!」。声をかけてきたのは、和也に会いに来たという瑠夏だった。', '2020/08/27 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0b18f5c-36d4-49a4-b2f5-408c828bebb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3f53a9b-60fb-4660-a16b-938edb2fcce5', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 8, '100063140', '「クリスマスと彼女」－クリカノ－', '瑠夏と交際 (仮) を始めた和也は、千鶴との関係をいつバラされるか分からないという恐怖に怯えながら生活していた。千鶴とは会えないまま季節は冬になり、クリスマス当日。銀行からの帰り道に、いつもよりおしゃれした千鶴を見かけた和也は、“残酷な可能性”を考え始める。「『レンタル彼女･水原千鶴』に彼氏はいるのか……?」。', '2020/09/03 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f74690d-a26e-44f9-828a-4fe4a7f7cfb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('182ea0a3-2cc2-4729-88d4-9927211cf8ec', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 9, '100064046', '「嘘と彼女」－ウソカノ－', '千鶴からのプレゼントに喜ぶ和也だったが、他のレンカノ利用者ももらっていると知り、激しく落ち込む。喫茶店で千鶴にそのことを尋ねるも、事務所の意向だと言われてしまう。一方、アパートでは瑠夏が和也の帰りを待っていた。「今から私とデートしてもらいます!」。和也は瑠夏の行きたいところへ付き合うことに。しかし、連れて来られたのは、ホテルの一室で…!?', '2020/09/10 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/023b8b2c-fd31-4c9a-aff9-53b15b60c6d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a798b6b0-7167-4ab0-b895-d982c6dc5925', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 10, '100064565', '「友達の彼女」－トモカノ－', 'バイトの初任給を何に使おうか考える和也だったが、ふと栗林のことが脳裏をよぎる。最近栗林の様子がおかしいと、木部から話を聞いていたのだ。ボーッとしていたり、女性不信のつぶやきをしているという。和也は意を決して、栗林を呼び出すことに。翌日、栗林が和也を待っていると―「駿君、だよね?」。待ち合わせ場所にやって来たのは、千鶴だった…!', '2020/09/17 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69050fdc-5e6d-4f25-ba82-ec5c2a804969.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0b8ca3f-8b13-46a2-967c-a687bc1437b8', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 11, '100064738', '「真実と彼女」－シンカノ－', '千鶴からの頼みで後輩のレンカノ･桜沢墨とデートすることになった和也。待ち合わせ場所についた和也は、柱に隠れて顔を赤らめプルプルと震えている女の子を発見する。「……あ…………う……」。声もルックスも超絶美少女な墨だが、緊張して挨拶もできないほどの人見知りだったのだ。話せないし笑顔も苦手な墨との練習デートが幕を開ける!', '2020/09/24 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e64fe1e7-2590-4d62-bca8-1d1f18c3ad31.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('598150aa-1a22-40e6-93dd-a7c44abee3c2', '02951fbe-3d40-44ed-bdc8-9ab9e3ac7e7e', 12, '100065299', '「告白と彼女」－コクカノ－', '【シーズン1 最終話】千鶴を予約したのは麻美だった! 千鶴がレンカノであるとバレていたのだ。カラオケ店に入り、千鶴に和也とのことを尋ねる麻美。一方、バイト中の和也は偶然2人が店内を歩いていくのを見かけ、様子を伺う。そんな中、麻美は千鶴にさらに質問を投げかける――「レンタル彼女やってる間に、相手を好きになっちゃったりしないのかなって」。', '2020/10/01 02:00:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba357479-68f7-4506-977e-fb0402221068.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('536ab2be-53d8-494b-b12b-4211868edce4', '2bb53e65-40f6-46d0-88d7-eacd13d55b83', 'hulu-kanokari-s2', 'シーズン2', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c9345dd-5913-4f31-be03-8d810d06e69e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('708f5a43-1d68-45de-b4ef-b7864a20316d', '536ab2be-53d8-494b-b12b-4211868edce4', 1, '100116908', '「夢と彼女」 －ユメカノ－', '「女優1本でやってくのも、アリかなって」“彼女のフリ”をしてもらっている水原千鶴のひと言に、ダメダメ大学生･木ノ下和也は破滅の危機に立たされていた。千鶴は女優として出演する舞台が成功したら、レンカノを辞めるというのだ。舞台の情報を目にした和也は、こっそり劇場を訪れる。そして、運命を左右する舞台の幕が上がり――。', '2022/07/07 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c9345dd-5913-4f31-be03-8d810d06e69e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('443b004c-400c-46fc-a342-cc2646830fe1', '536ab2be-53d8-494b-b12b-4211868edce4', 2, '100117544', '「いつもの彼女」－オフカノ－', 'チャンスを逃して落ち込む千鶴を応援し続けると決めた和也は、さっそくレンカノのサービスを利用する。いつものようにデートを終えた和也に、千鶴はいつもと違うひと言を投げかける。「あなた時間ある? ちょっと寄りたいところがあるんだけど」 レンカノではないオフタイムの千鶴は、和也をとある場所に誘い……!?', '2022/07/14 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f3d2ae4-42a3-41e2-8051-3de9817f0572.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30152338-e231-4fe2-b56c-6002110b3241', '536ab2be-53d8-494b-b12b-4211868edce4', 3, '100117862', '「再来の彼女」－サイカノ－', '家に帰った和也のもとに、先ほど別れたばかりの千鶴が訪ねてくる。「鍵…失くした……」 自宅に千鶴を招き入れるという状況に、混乱と興奮が抑えられない和也。しかしそんな中、二度目のインターホンが鳴り響き、第二の来訪者が和也の部屋を訪れる。', '2022/07/21 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6bdadf50-7a85-4238-ad41-278f699d1246.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c75c855d-3184-400a-ae19-cc8a96eb2fd6', '536ab2be-53d8-494b-b12b-4211868edce4', 4, '100118447', '「夜と彼女」－バンカノ－', '大学のコピー機で資料を印刷している和也のもとに麻美が現れ、千鶴がレンタル彼女であることを知っていると告げる。麻美と千鶴のやり取りを知っている和也は、オーバーリアクションで誤魔化そうとする。そんな和也の慌てぶりに、麻美は思いがけない一言を告げる……。「まさか和くん。本気になってないよね?」', '2022/07/28 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0cdb6a8c-c78f-4167-a948-d03c4208ecc7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a096bd5-7200-4eb4-8ce9-c09b11a4ef92', '536ab2be-53d8-494b-b12b-4211868edce4', 5, '100119138', '「誕生日と彼女」－バーカノ－', '瑠夏との一夜の翌朝、和也は千鶴と偶然出会う。自然体を努めながら千鶴にレンタルの誘いを行うも、瑠夏との関係を誤解されたまま断られてしまう。何とか誤解を解きたい和也は千鶴の誕生日に気がつき、ある決意をする。「しっかりお祝いして、なんとか誤解を解きたい!」', '2022/08/04 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b45d2c5-77cb-4057-a3bc-a0ba07a21598.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2d852f1-f7db-4f4d-addc-63762490c067', '536ab2be-53d8-494b-b12b-4211868edce4', 6, '100119951', '「酒と彼女」－エンカノ－', '瑠夏との誤解が解けた和也は、フェアなお隣さんとして千鶴との距離も縮められたと手ごたえを感じる。そんなある日、「そういえば和也、今日飲み会出れる?」と木部から飲み会の誘い。居酒屋を訪れると、そこには“一ノ瀬ちづる”の姿があり――…?', '2022/08/11 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98fcafc2-28e5-4c58-9a33-9ccefec44217.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4bbb80d7-f175-4fb0-bfd4-0fb8f6379d07', '536ab2be-53d8-494b-b12b-4211868edce4', 7, '100120330', '「元カノとカノジョ」－トリカノ－', '二日酔いに苦しむ和也は、昨晩起こったことのどこまでが現実なのか分からずにいた。その後バイト先で瑠夏と会った和也は、自分たちの関係が誤解だと千鶴に信じてもらえたことを告げる。詰め寄る瑠夏。しかしそれはある客の来店で遮られる。「あ、ハロー。和くん」そこには麻美の姿があり……。', '2022/08/18 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/609e9c58-a058-489f-80c6-5279a961cbbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71a5adc5-5d64-403e-bd88-2a611639e483', '536ab2be-53d8-494b-b12b-4211868edce4', 8, '100120954', '「青春と彼女」－コスカノ－', '久しぶりに千鶴をレンタルしようとサイトを見ると、千鶴がランクアップしていることに気づき喜ぶ和也。いつも通りの予定調和なデートでは飽きているのでは? と自己弁護をしながら和也はあることを考える。「どもっ」 待ち合わせ場所に現れたのは制服姿の千鶴。和也の高校時代からの憧れのデートが今始まる……!', '2022/08/25 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb7ae812-82b3-4f8c-ba72-644b3a9a7e64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fcc373e9-1107-4d4d-b2e5-6a7741fc2dca', '536ab2be-53d8-494b-b12b-4211868edce4', 9, '100121715', '「キスと彼女」－ジッカノ－', '毎年実家で行われる和也の誕生会。千鶴の誕生日を祝い損ねた和は、千鶴と和也の合同誕生会を行おうとする。何とか千鶴に来てもらうようお願いする和也だが、迎えた当日、「さぁ、ご実家へ参りましょうかっ」 和也の目の前に瑠夏が現れて……!?', '2022/09/01 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0cfb9097-624d-4b08-be1f-8c27fb3a3fa0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfdfbaf9-40ef-4a55-93dd-4e3f9e2358bd', '536ab2be-53d8-494b-b12b-4211868edce4', 10, '100122618', '「指輪と彼女」－リンカノ－', '突然の瑠夏とのキスに、和也は今まで瑠夏に大きな我慢をさせていたことを実感する。瑠夏への想いが和也の脳を駆け巡るなか、和は千鶴に小さな箱を渡そうとする。それは和がかつてもらった婚約指輪であり、千鶴に譲りたいという……。戸惑う千鶴、いたたまれない瑠夏を見た和也は決意する。「千鶴が受け取るわけにはいかないんだ……」', '2022/09/08 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/adf41084-bf60-4b99-93ef-fe7974645e66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da6b268b-fa85-4de5-8278-5cecb633bd17', '536ab2be-53d8-494b-b12b-4211868edce4', 11, '100123537', '「お饗しと彼女」－モテカノ－', 'ある朝和也は、千鶴にベランダに呼び出される。どうやら墨がまたレンカノの『練習台』をお願いしたいらしい。承諾する和也だが、小百合の容態と千鶴のことが気になりどこか上の空……。当日待ち合わせ場所へ行くと、現れたのは普段と違う姿の墨!?「今日は私が和也君を、『お饗し』したくて……」', '2022/09/15 02:00:00', 1468, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a22877cb-07b9-4bbc-8ed5-a2438d87a596.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67386735-f1ec-4066-bc8e-ba073f3b66ae', '536ab2be-53d8-494b-b12b-4211868edce4', 12, '100123833', '「彼女と俺」－イツカノ－', '【シーズン2 最終話】墨の“お饗しデート”を経て、千鶴のためにできることを見つけた和也。しかし現実は無情で、千鶴には映画オーディションの落選通知が届く。新たなオーディションや撮影スケジュールを考えると、出演映画を小百合に見せる夢は叶いそうにない。「笑ってないで教えてよ…おじいちゃん……」 亡き祖父の笑顔の写真と、在りし日の千鶴の想いが交錯する……。', '2022/09/22 02:00:00', 1438, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5247adfc-9ed1-401b-baa2-f914d5edf476.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', '2bb53e65-40f6-46d0-88d7-eacd13d55b83', 'hulu-kanokari-s3', 'シーズン3', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01af7410-a6a9-4a57-a855-b76b2e9b32e7.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36d8424b-1b9b-4f83-86d1-36a87579ae24', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 1, '100152078', '「手料理と彼女」―オムカノ―', '千鶴が主演する映画を自主制作すると決めた和也。しかし、作成したクラウドファンディングサイトのページを担当者に見せるも、このままでは企画立ち上げはできないと言われてしまう。アパートのベランダでそのことを話す和也と千鶴だったが……「そんなにイチャイチャしてるなら、付き合っちゃえばいいのに」 2人に声をかけてきたのは、202号室に引っ越してきた八重森みにだった。', '2023/07/13 01:53:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01af7410-a6a9-4a57-a855-b76b2e9b32e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e069b6ca-da31-4722-ac71-9b527ffda3f1', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 2, '100153195', '「隣室の彼女」―トナカノ―', '「お2人はいつからそういう関係に!?」 打ち合わせをする和也と千鶴のもとにやってきたのは、瑠夏だった。和也の部屋に上がり込んだ千鶴の姿を見て、彼女 (仮) である瑠夏は怒り、2人の関係を問いただす。一方、アパートの外では、そのやり取りの一部始終をみにが目撃していて……!?', '2023/07/20 02:08:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5339a791-0d94-4de7-bca7-c9eb9a52aaca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b2bccce-1f89-48f2-8b08-42e7c50cf515', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 3, '100153576', '「経験者と彼女」―サクカノ―', '脚本探しや撮影クルーの手配など、映画制作に邁進する和也だったが、クラウドファンディングのページは公開から3週間が経ち、完全に勢いを失っていた。和也と千鶴の関係の続報を求めてやってきたみににそのことを話すと、作戦会議の開催を提案される。「それなら力になれるかもッス! 自分、クラファン経験者っス!」', '2023/07/27 01:53:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7fda33d-afa5-428c-b11b-70041a562d26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4ce899f-6cc7-4e45-8ce1-8a42a24f6bcc', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 4, '100154020', '「最終日と彼女」―ギリカノ―', 'クラウドファンディング成功のため、千鶴の役者仲間である海が情報拡散に協力してくれることに。喜ぶ和也たちだったが、千鶴は海からある“お願い”をされたことを告げる。「海君に観劇に誘われちゃって」それは、大切なクラウドファンディング最終日に関わることで――。', '2023/08/03 01:53:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0da35c75-eba9-43f7-95ed-ddf4011b9637.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41cdb8b2-9083-4b5e-b4f8-406aa08ed7cb', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 5, '100155008', '「撮影と彼女」―エイガノ―', '夏休みに入り、映画撮影が始まった。和也はプロデューサーという肩書きの重みを実感しつつ撮影現場で雑用をこなしていく。女優として立派に演技をする千鶴を見て、そのすごさを改めて再認識した和也だったが、自身と千鶴の間に大きな距離があることを思い知らされて落ち込む。「今まで迷惑かけて、マジでごめん…」そんな和也に千鶴が声を掛けて……', '2023/08/10 01:53:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63970065-d3e7-46bd-95e1-34b70eacb348.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f9fdb16-4a6a-4759-ae31-2bbbd47f379b', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 6, '100155732', '「ラストシーンと彼女」―ラスカノ―', 'みにの企みにより、千鶴と2人きりで映画の撮影旅行に来た和也。ホテルに到着すると、1部屋しか予約されていないことが判明する。同室で宿泊することになり和也は緊張を隠せない中、映画の撮影準備は進行していく。ラストシーンの撮影が始まろうとしたその時、千鶴が和也を呼び止める。「…話しておきたいことがあるんだけど」', '2023/08/17 01:58:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d82d9aed-83a6-49b8-b154-9a3bd94b7e8a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47b09a35-48fa-4d4a-870a-67b3aefb16a1', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 7, '100156418', '「和也と彼女」―ナマカノ―', '瑠夏の誕生日当日、その日は願い事をなんでも聞くと事前に約束していた和也は、2人でプールへ行くことに。ビキニの水着に着替えた瑠夏は、日焼け止めを塗ってほしいと和也にねだる。「ドキドキさせてみせるっ! 和也君にも目一杯」 誕生日をキッカケに一気に距離を縮めたい瑠夏は、いつも以上に積極的で……!', '2023/08/24 01:58:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81d36ceb-2552-4052-87ae-5100a095c78b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1b9096c-ca69-4101-baa2-96b552c2a14f', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 8, '100157958', '「家族と彼女」―ツミカノ―', 'アパートの外で話す和也、千鶴、みにの姿を目撃した瑠夏。いつもなら和也たちに詰め寄る彼女のはずが、なぜかやや余裕の表情!? しかも、「ね。和也」 突然和也を呼び捨てにした瑠夏に、一同は動揺が隠せない。一方映画制作では、完成披露する映画館へ和也と千鶴が下見に行くことに。そこへ小百合も同行することになって……。', '2023/09/07 01:53:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f22ae5b0-80f6-4cc8-8758-bf471a598ac1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e958f63-cb3f-4079-8740-4f4b16f1b3de', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 9, '100158197', '「お別れと彼女」―セイカノ―', '救急搬送された後も意識が戻らない小百合に付き添う千鶴は、“和也との恋人関係が嘘”だと今からでも告げるべきか葛藤していた。そして、自身の出演映画を小百合に見せられず悔やむのだが、そこへ突然和也が現れる。「ちょ、ちょっと! 何入ってきてんのよ、急に!!」 驚き怒る千鶴。しかし和也は何も言わず、手にしていたノートPCとプロジェクターを起動させて病室を出ていくのだった…。', '2023/09/14 01:53:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21e935f1-b9e9-4f99-994c-907b34b6853b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a035c7a6-8ef9-49f8-a47e-c0d16c962deb', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 10, '100158906', '「突発旅行と彼女」―トツカノ―', '小百合を亡くした千鶴に自身ができることを探すために、和也は“レンタル彼女”として墨を呼び出して事情を打ち明ける。真剣に話を聞いてくれた墨は、和也を引っ張りどこかに連れて行こうとする。「私も千鶴ちゃんの為に…何かしたい…」 向かった先は、まさかの海で……!?', '2023/09/21 01:58:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6bb64ff-8c3c-48ae-9a59-a659d666f2e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6595c1d-d75d-42f5-b27c-7aa49b072408', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 11, '100159935', '「彼女と彼氏」―カノカレ―', '「元気付けてみせる! 1日かけて水原を!!」 千鶴を元気付けるため、デートをすることにした和也。“レンタル彼女”として待ち合わせ場所に現れた千鶴は、まるで何事もなかったかのようにやたらと明るく、意表を突かれる。千鶴が立ち直っているようにしか見えないことを気にしつつも、デートプランを実行していく和也。励ましデートの行方は……!', '2023/09/28 01:58:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9b26a6d-c978-47b2-a0c9-6bae5c268616.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5fc414d-946e-4048-aa08-29af62a7e765', 'e80c2fbc-3bf1-4c4a-b61c-df23ba47383c', 12, '100160793', '「理想の彼女と彼女」―カレカノ―', '【シーズン3 最終話】励ましデートの終盤、夜の公園で線香花火をする最中に、和也は千鶴が涙を滲ませ震える姿を目撃してしまう。すぐにいつもの笑顔に戻る千鶴に対して、和也は“レンタル彼女と客”という自分たちの関係性を再認識し、己の無力さを噛み締める。これまでの、さまざまな千鶴の姿を回想した和也は、ゆっくりと口を開く――。「俺の…『理想の彼女』はさ…」', '2023/10/05 01:58:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c23f93f6-e675-450f-87bf-4a53b3d22ad4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0557e47d-6d13-46c4-8f8e-e1248c18e101', '2bb53e65-40f6-46d0-88d7-eacd13d55b83', 'hulu-kanokari-s4', 'シーズン4', 4, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70c1ad26-c403-421c-932f-a5cc3376d833.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9b775d8-6103-4f01-8df0-6b4205322a94', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 1, '100231806', '「日常と彼女」 ―ニッカノ―', '自主制作映画の上映会も終え、暦は10月。和也は大学へ行き、アルバイトをして、すっかり日常に戻っていた。千鶴の祖母の件がひと段落ついたことで、瑠夏は休戦をやめると宣言。和也は瑠夏から旅行に誘われるも、近所の温泉施設で手を打つことに。そんな折、和也のスマートフォンに千鶴からプライベートなお誘いのメッセージが届く。「今週土日、どっちかヒマ?」', '2025/07/07 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70c1ad26-c403-421c-932f-a5cc3376d833.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0aa403cb-6e54-474d-9b58-c760430154d6', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 2, '100232497', '「溜め息と彼女」 ―タメカノ―', 'カフェの帰り道、意を決して千鶴をランチに誘った和也。千鶴は一瞬考えたのち、その誘いを受け入れる。難航する店探しに、千鶴が提案したのはファミリーレストランだった。ワインを飲み、笑い上戸なOFFモードの千鶴。そんな満面の笑みに、和也のときめきも止まらない。しかし、千鶴がふと、真剣な眼差しで和也にある質問を投げかける。「あなた…私の事…好き?」', '2025/07/14 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b692e328-9142-4b52-afb8-7c0abd352cfb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cfcb968-04e9-4347-8300-f1d8aadb1c9e', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 3, '100232897', '「代官山と彼女」 ―ダイカノ―', '祖母の和と元カノの麻美が仲良くなっていることを知った和也は、千鶴と自分の偽りの恋人関係を、麻美によって周囲にバラされるのではと警戒する。そんな折、千鶴は俳優仲間の海からパーティに誘われ、和也に映画のプロデューサーとして同行して欲しいと相談を持ちかける。パーティ当日、千鶴と共に会場を訪れた和也に、海は2人きりで話がしたいと告げて……「ねえ、この言葉どう思う? 『好きじゃなくもない』」', '2025/07/21 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9dd85e83-a59f-4a8b-999d-477e926bd7a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('424f0b76-06e9-4c48-abc2-003bdc6c5e15', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 4, '100233394', '「決意と彼女」 ―キメカノ―', '自身の気持ちに覚悟を決めた和也は、瑠夏に別れて欲しいと頼み込むも、断られてしまう。千鶴への告白を強行しようとする和也だったが、千鶴にはやんわりと躱されてしまう。しかも彼女は、麻美が自分たちの関係を知りつつも静観している、今の状況の危うさに警鐘を鳴らす。和也は麻美の真意を探るために、木部に話を聞くことに。時を同じくして、大学の廊下では笑顔の麻美が千鶴に接触していた。「こんにちは、水原千鶴さん」', '2025/07/28 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/448dd0c9-75f2-4cf3-b8b5-028b1d4334b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56d9cbaa-bbf6-4055-946a-338c53e0b053', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 5, '100234058', '「その時と彼女」 ―バッカノ―', 'ドーナツ店に連れて来られた千鶴は、和也との関係について麻美から質問される。「助けてあげる、和くんから」 麻美は和也との状況を邪推し、千鶴に救いの手を差し伸べる。一方、瑠夏は和也と通話する中で、和也が千鶴に告白しようとしたことに気づく。なんとしても告白を阻止したい瑠夏は、お泊まり前提で和也の家に押しかけて……', '2025/08/04 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a351be3b-6bfa-4173-9d12-202766ca4a79.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb16170b-8986-4ed6-bad4-f8a43e1f624e', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 6, '100234723', '「家族旅行と彼女」 ―タビカノ―', '木ノ下家の家族旅行に参加することになった千鶴に、なぜ断らなかったのかと瑠夏が問い詰める。さらに「私もう、えっちしましたから!!」 自身と和也との関係が進展していると、瑠夏は嘘のアピールをする。そして迎えた旅行当日。和のサプライズで木部と栗林が合流する。瑠夏を“レンタル”したことがある栗林の参加に、和也だけでなく千鶴も瑠夏も焦りを隠せない。一触即発、福島･ハワイアンズへのカオスな旅行が幕を開ける……!', '2025/08/11 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6246723-f8d7-4ee5-bf17-616dc851c924.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d10f1dc-756c-4064-af48-733ecc7ced83', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 7, '100235146', '「ハワイアンズと彼女」 ―ハワカノ―', '施設に到着した一行を笑顔で迎え入れたのは、なんと麻美だった。聞けば、元々彼女もハワイアンズに来る予定があった中、皆の旅行の情報を知り、挨拶のために現地で待っていたのだという。しかし、和也はそんな偶然があるはずないと考え、危機感を募らせる。一方、栗林は密かに瑠夏を呼び出して――「まだやってるの? 『レンタル彼女』……」', '2025/08/18 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/010a058a-6cac-4707-be0f-c7d98d73a098.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44a91dd2-6687-4fa7-8ec2-425bd91427ab', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 8, '100235518', '「紐と彼女 」―ポロカノ―', 'ハワイアンズでの旅行を楽しむ一行。千鶴と一緒にウォータースライダーに乗ることになった和也は、千鶴と密着した姿勢になりドキドキが抑えられない。乗り終えてプールから上がろうとしたその時、千鶴は水着のブラが外れていることに気がつく。「……流されちゃった。水着…上……」 赤面する千鶴を前に、和也は鼓動を激しくしつつも付近を捜索することに。', '2025/08/25 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bcba9676-d52f-41bd-929d-06f93a9d880d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5cecb9df-322c-4d5c-9da2-1d4e78ed4ea1', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 9, '100236202', '「初めて記念と彼女」 ―ハツカノ―', '「ねぇ。本当の『彼女』になれるって言ったら、どうする?」 瑠夏のところに、麻美がやってきて問いかける。把握している現状を話し揺さぶりをかける麻美に、瑠夏は危うさを感じ取る。その後、皆とプールでひと時を過ごし、瑠夏は千鶴とロッカールームへ。先ほどの麻美の言葉が頭をよぎり、内心で悩む瑠夏。すると横では千鶴が水着を脱げずに困っていて…!?', '2025/09/01 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95c030e3-bc72-4579-8791-12658100ad51.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c08bff6-c87d-4501-b1fe-4c6178ce2761', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 10, '100237271', '「薬指と彼女」 ―ユビカノ―', '露天風呂を堪能する一行。千鶴と瑠夏、和は、女湯でガールズトークに花を咲かせる。その頃男湯では、和也と父･和男が話していた。和男は以前、和也が千鶴に金を渡すところを目撃していたらしい……。その後、風呂を出た瑠夏は、先の麻美の言葉を思い返していた。和也の本当の彼女になれる可能性──。瑠夏は部屋に戻る和を呼び止め、2人きりで話すことに。「例えば千鶴が、“嘘”をついているとしたら……」', '2025/09/08 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fafcd5f1-1ed3-4a38-a80d-fcf2427b7def.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75f954fb-220e-4548-b031-8a054b235461', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 11, '100237732', '「罪悪感と彼女 」―ギルカノ―', 'ハワイアンズ2日目。各自一日自由行動だと聞いた和也は、今日中に告白しようと決意する。千鶴と2人きりになりたい和也は部屋でゆっくり過ごそうと提案するが瑠夏に阻止され、千鶴も手洗いに行ってしまう。その様子を見ていた麻美は千鶴に近づく。そして、和也の母･晴美との『指輪』のやりとりを一部始終目撃していたことを告げ、改めて尋ねるのだった――「和くんは、千鶴さんの『好きな人』なの? それとも『お客』なの?」', '2025/09/15 00:00:00', 1467, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b864cf3-9d8d-4cb1-bf02-671c8ed9f2d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d41d8653-a20e-4f6d-b692-190481176137', '0557e47d-6d13-46c4-8f8e-e1248c18e101', 12, '100238334', '「楽園と彼女」 ―ケッカノ―', '【シーズン4 最終話】麻美から今日中に結論が欲しいと言われた千鶴は、どうするべきなのか考え込む。一方、和也は和から感謝を告げられたことで、千鶴との関係が嘘だったとは絶対に言い出せない状況に追い込まれていた。どんどん事態が悪化する中、和也はふと千鶴とのこれまでを思い出す。数々の出来事を回想した和也は、千鶴のいる教会へと走り出して――「聞いてくれ! 水原!」', '2025/09/22 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b40e73da-64d1-40a6-9e03-ff4478bdb273.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('599c4e15-2769-4537-ade8-fad95d552b4c', '彼女が公爵邸に行った理由', '', 'hulu', 'the-reason-why-raeliana-ended-up-at-the-dukes-mansion', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0b6615d-17c3-4f72-b26b-76d165fba3dc.jpg?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 151847, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ad6d045c-2bfc-4687-a17c-30c6045c66a4', '599c4e15-2769-4537-ade8-fad95d552b4c', 'hulu-the-reason-why-raeliana-ended-up-at-the-dukes-mansion-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/996af097-ce16-4aaf-b71a-e06798278426.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0a5097a-00d8-481e-b26c-d15cb1f353bc', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 1, '100143225', '彼女が取引した理由', '何者かに突き落とされ謎の死を遂げた花咲凛子は、小説の中の登場人物であるマクミラン家の娘･レリアナに転生してしまう。レリアナはその小説における脇役で、婚約者ブルックスに毒殺される運命にあった。そこで凛子は、死の運命を覆すべく「第一王位継承者」で絶大な権力を持つ公爵･ノアにある取引を持ちかける。', '2023/04/15 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/996af097-ce16-4aaf-b71a-e06798278426.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03627f4c-2f34-44a4-80aa-c69777ecd53c', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 2, '100143737', '彼女が契約した理由', '正式に契約を結ぶため、レリアナは単身でウィンナイト家へ乗り込む。レリアナが取引の材料にしたのは『玉璽』――。新興貴族と旧貴族の対立における切り札である玉璽を、ノアが隠し持っているという情報で揺さぶるのだった。しかし、ノアには通用せず、取引不成立の危機に見舞われるレリアナ。その時、目に留まったのは不自然に置かれたチェス盤で……?', '2023/04/22 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99f134c3-20ac-4a6f-983d-5ac8c8322120.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eca867ae-e83a-41da-abd3-b9b1cdc55566', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 3, '100144388', '彼女が花嫁修業した理由', '花嫁修業のためウィンナイト家に移り住むことになったレリアナ。偽装のため愛する婚約者として振舞わなければならない二人だが、呼び方ひとつとってもその前途は多難……。偽りの関係に過ぎず完璧にこなす必要はないと頭では分かりつつも、レリアナは次々に押し付けられる花嫁修業をこなしていくのだった。', '2023/04/29 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a54336d1-b71d-4e91-aa6a-5e4a0d5d946f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab20eb87-ac11-4e0c-b43e-2c96973731a6', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 4, '100144819', '彼女がケンカを買った理由', '舞踏会の会場に到着したレリアナとノア。二人の婚約は貴族の間でも大きな注目を集めていた。レリアナはノアの頼みを受けて、彼に貸しをつくるべくエリティール侯爵夫人と二人きりになろうと画策するが、そこに小説に登場する悪女キャラ･ビビアンが現れる。さらに、レリアナを狙う怪しい人物が……?', '2023/05/06 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7ab05c4-c976-474e-abc6-5e601e079803.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27c8ae9a-2614-4e73-8aea-8e6404ba470c', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 5, '100145634', '彼女が連れ去られた理由', '邸内の混乱に乗じてレリアナが元婚約者のブルックスらに連れ去られた。馬車の中で目を覚ましたレリアナはその場にいた男に解放するよう説得を試みるも、当然のごとく失敗に終わる。しかし、車輪が壊れて馬車が止まった隙をつきなんとか脱出したレリアナ。逃げ込んだ林の中を走ってついに茂みを抜けられると思った瞬間、また何者かの手に捕らえられてしまう。', '2023/05/13 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc8b5b98-82b0-4e24-adf7-66316739d049.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c369f44b-2649-4156-88ba-4111f53b532d', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 6, '100146190', '彼女がコスプレした理由', 'ノアの馬の上で寝落ちてしまったレリアナは、翌朝、彼の寝室で目覚めた。隣には上半身裸のノア。それに混乱したレリアナは、アダムに助けを求め一緒に逃げることに。残されたノアは、執事長･キデオンに命じて屋敷中の騎士を総動員し二人を探させるが、レリアナは捜索を逃れるためにメイドに変装していた。', '2023/05/20 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed49b564-caec-4b43-a49c-6b65923ac694.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('146e26ca-ab8b-4730-b3d2-0f0c0f8e4602', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 7, '100147064', '彼女がハンカチを渡した理由', 'レリアナの元に、以前約束していたフリスからの招待状が届いた。次の会は、シークレット山脈での魔物討伐戦で開かれる。討伐戦では女性が男性にハンカチを贈り、男性が捕まえた魔物を女性に捧げる風習があるが、ノアはまだ、ハンカチを受け取ったことも魔物を捧げたこともないという。そして迎えた、討伐戦当日。ノアはレリアナにある要求をして……?', '2023/05/27 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1eeec7d9-bb44-4ae7-beb6-3c231fa0e924.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4bdb0c24-27b4-4480-9297-cd03c5587d67', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 8, '100148196', '彼女が神殿に行く理由', '討伐戦の戦利品として、山の主とも言われる魔物をレリアナに捧げたノア。契約だけの関係だった二人の距離に変化が現れ始めた一方で、レリアナの運命には暗雲が立ち込める。ノアに思いを寄せていたが、神殿で聖火を灯す役目までをもレリアナに奪われ憎悪を募らせるビビアンに、ある人物が近づいているのだった。', '2023/06/03 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75b06789-6822-44c1-bde3-956e18cc3438.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23e42bd6-c07a-41a4-a1bb-fc9fc2455ed0', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 9, '100148351', '彼女が野蛮人と呼ばれた理由', '聖火式のため神殿に到着したレリアナは、着くなり過酷なノルマを課され、げんなりした気分で泉を訪れる。そこで、溺れている一羽の鳥を助けたが、その場に居合わせた大神官･ヒーカーは、その鳥は死ぬ運命なのだから無駄だといい、ふたりは口論になる。その後、高位の聖職者である自分に対して無礼な態度を取った彼女が気になるヒーカーは、レリアナを神殿中探し回るが、見つけることができないでいた。', '2023/06/10 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7e38727-e07d-4c69-86ef-eccaed7dce5a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1fce4122-9868-4597-bf29-9a1d1eb2d482', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 10, '100148982', '彼女がおじいちゃんと呼んだ理由', 'レリアナに高い才能を見出したヒーカーは、自らの弟子にするべく行動に出る。大神官の威厳を見せるため、滅多に開くことのない神聖国に続くゲートを開けて聖騎士団を呼び出してみたり、親しみやすさをアピールするため、「おじいちゃん」になってもいいと言い出してみたりとレリアナの気を引くため悪戦苦闘する始末……。そんな中、レリアナが身に着けていた髪飾りの宝石が怪しく光り……?', '2023/06/17 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f0bc644-79ad-4e90-87bb-70803ef8a55e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('130af8ef-a776-47e1-937d-8e2db170c6b4', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 11, '100149589', '彼女が知らないふりした理由', '休暇にはいるメイドから、西館の奥の部屋にある鏡は絶対に見てはいけないと忠告されるレリアナ。なにやら、鏡の魂と目が合うと「どんなことでも教えてやる」と声をかけられるという噂があるらしい。だが、本来ノアと結ばれる運命だった小説の主人公･ベアトリスが今どこにいるのか気になるレリアナは、夜、その鏡を手に取ってしまう。不審な音に身をすくませたその時、レリアナの前に現れたのは鏡の魂ではなくノアで――。', '2023/06/24 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9ed7e07-168b-4842-b59f-96f076ee5c04.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c85bd483-fa81-4620-9763-641dda191310', 'ad6d045c-2bfc-4687-a17c-30c6045c66a4', 12, '100150736', '彼女が公爵邸に来た理由', '【シーズン1 最終話】異母兄である現国王･シアトリヒの元を尋ねたノア。そこで、レリアナとの契約について口を開くが、シアトリヒからは、議会の会期終了を控えた今、もはやその婚約は不要であるという事実を突き付けられるのであった。一方レリアナは、小説通りであれば現れるはずのベアトリスを探してウィンナイト家の墓地へと向かうが、そこにいた人物は果たして……?', '2023/07/01 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7f00de5-89cd-4c0b-af0f-928167e66589.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2a374553-b887-4375-b4e2-a9cbb997e65a', '彼方のアストラ', '', 'hulu', 'astra', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b48d402-3c07-4057-9585-d8eba5d46746.jpg?w=331&h=447&p=t', 'hulu', 2019, 2, 1, 'FINISHED', NULL, 107663, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('16095d57-a801-46b1-9c0e-2659c5c5d690', '2a374553-b887-4375-b4e2-a9cbb997e65a', 'hulu-astra-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5792844-cc51-4e5c-9592-cd322f6d8ce1.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7a0d81b-d95f-4c8a-a6c4-7ff6b1d76229', '16095d57-a801-46b1-9c0e-2659c5c5d690', 1, '100038595', 'PLANET CAMP', '生き残れ、宇宙の彼方で。宇宙旅行が当たり前になった時代。ケアード高校の生徒アリエス･スプリングは、初めての惑星キャンプに胸をときめかせていた。同じ班になったのは、宇宙港で顔を合わせたカナタ･ホシジマら計9名。一行は無事に惑星マクパに辿り着つくが…予期せぬ事態が発生する。', '2019/07/10 12:00:00', 1293, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5792844-cc51-4e5c-9592-cd322f6d8ce1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('353f5d31-d574-421a-bcc0-6ed6f550f275', '16095d57-a801-46b1-9c0e-2659c5c5d690', 2, '100038977', 'WILDERNESS', '20日分の食料と水を手に入れるため、惑星ヴィラヴァースに降り立ったカナタたち。特異な生態系に翻弄されながらも生存のために協力し、メンバーは少しずつ環境に順応していく。しかし、十分な食料と水が確保できるとわかった矢先、再び謎の球体が現れる!', '2019/07/17 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/61be9c87-a98f-4a0a-b26f-75f3207a2f91.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b44cc98f-8a66-481c-b092-e38279a14a90', '16095d57-a801-46b1-9c0e-2659c5c5d690', 3, '100039439', 'METEOR', '通信機を壊した犯人がこの中にいる―。カナタはメンバー一人一人に疑いの眼差しを向けるが、証拠となるものは見当たらない。猜疑心に苛まれながら、ついにメンバーに事実を打ち明けるカナタ。誰もが混乱に陥り、疑心暗鬼になる中、アストラ号の壁が突然爆発する!', '2019/07/24 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e98d11c6-9275-4747-9766-901bbee5f03f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cef72503-a1fe-4f2e-ba92-512d10b016ac', '16095d57-a801-46b1-9c0e-2659c5c5d690', 4, '100039725', 'STAR OF HOPE', '墜落の危機を乗り越え、アストラ号は第2の惑星シャムーアに到着する。犯人を探すことをやめ、全員で生き抜くことを優先するカナタ。惑星探査は順調に進み、食料と水の見通しも立った。色めき立つカナタたちだが、ユンファだけはどこか表情が曇っていて…。', '2019/07/31 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab62a394-5c77-479f-be98-99a151ca4f53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc5e0a3d-096f-44a7-89f6-a13ec688a183', '16095d57-a801-46b1-9c0e-2659c5c5d690', 5, '100040042', 'PARADISE', 'B5班を救い、メンバーと打ち解けたユンファ。旅の楽しさを分かち合いながら、アストラ号は次なる惑星を目指そうとしていた。一方、ケアード高校にはカナタたちの親が集められ、行方不明の子どもたちを死亡扱いとする失踪宣告の手続きが始まろうとしていた!', '2019/08/07 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57848757-eec5-44d7-a8cb-7501ef6a18ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e646090a-87fd-48d8-81e9-8a00116914f1', '16095d57-a801-46b1-9c0e-2659c5c5d690', 6, '100040765', 'SECRET', 'ルカの父親マルコ･エスポジトは、ウルガーの仇だった。大切な兄を奪ったマルコに復讐するため、ウルガーは銃の腕を磨き、その機会をうかがっていた。ルカを殺せば、マルコに同じ苦しみを与えられる。その引き金に込められた憎悪に、ルカは…。', '2019/08/14 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3074953-fff9-46fc-a525-ff3d2a215d6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('366dcac9-db5f-4ffe-8dbe-c10ec8f10f3c', '16095d57-a801-46b1-9c0e-2659c5c5d690', 7, '100041194', 'PAST', '惑星イクリス到着を前に、B5班に衝撃が走る。シャルスはもともとケアード高校の生徒ではなく、惑星キャンプの直前に転校してきたというのだ。なぜ、シャルスは転校生であることを不自然に隠していたのか? 今明かされるシャルスの出自に、カナタたちは…。', '2019/08/21 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/268a7ab5-8482-4109-ba43-19abe2a44f05.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79554fba-a1a0-4fe4-9361-6f3b0b542a98', '16095d57-a801-46b1-9c0e-2659c5c5d690', 8, '100041418', 'LOST AND FOUND', 'アストラ号と同型の宇宙船を発見したカナタたちは、船内でコールドスリープ状態の生存者を確認する。彼女の名前はポリーナ･リヴィンスカヤ。この宇宙船、アーク6号の機関士だったという。さらに、アーク6号の発見によってアストラ号の修理にも一筋の光が差し込む。', '2019/08/28 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0741f992-7396-4ba0-acda-b624ea9cdec1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04c0ccfd-5a14-4ae8-923a-d7694e43bb35', '16095d57-a801-46b1-9c0e-2659c5c5d690', 9, '100041735', 'REVELATION', 'キトリーとフニシアはまったく同じDNAを持っていた。ザックから告げられた衝撃の事実に、カナタたちはとある仮説にたどりつく。そしてこれまでの全ての出来事がパズルのピースを埋めていくように仮説を裏付けしていく。', '2019/09/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/18027755-e54f-49de-99ba-f6824b2b9a1b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e40caa32-3bb3-468d-ba3b-8bcc79e5f3bc', '16095d57-a801-46b1-9c0e-2659c5c5d690', 10, '100042184', 'CULPRIT', 'カナタたちの目指す惑星を見て驚愕するポリーナ。次々と判明する新事実に困惑しながらも、B5班とポリーナはお互いの知識、認識をすり合わせ、様々な仮説を立てていく。そして次なる惑星ガレムへの到着を前に、カナタは意を決しアリエスの部屋を訪れる。', '2019/09/11 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7328458-6030-4e10-8e9f-a26a93519718.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df27d3bb-771f-4a5c-9418-1238f567c1fd', '16095d57-a801-46b1-9c0e-2659c5c5d690', 11, '100042459', 'CONFESSION', '刺客の正体が明らかになった…! 戸惑いを隠せないB5班のメンバーたち。旅の中で絆を深めてきた仲間が、なぜメンバーの一斉殺処分という使命を背負い続けるのか? 仲間の問いかけに、刺客はその出生の秘密と自身を突き動かすに至ったある事件の顛末を語り出す。', '2019/09/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/053c54ff-7184-44ff-9145-cd5817fb286a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22fbc10b-59f9-40d8-88d2-09ee85efeb16', '16095d57-a801-46b1-9c0e-2659c5c5d690', 12, '100042776', 'FRIEND─SHIP', '右腕を失いながらも、誰も憎まず今まで通りを貫くカナタ。惑星ガレムを出発する準備も着々と進み、5012光年の旅はいよいよ終着点を迎えようとしていた。そして、故郷への帰還を前に世界の真実を知るカナタたち。果たして、この真実をどう受け止めるのか。', '2019/09/25 12:00:00', 1382, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a818676c-db10-4155-be30-a355d9b063b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a351090f-23ca-48ab-b77a-5cabf2abfa0c', '悲劇の元凶となる最強外道ラスボス女王は民の為に尽くします。mini', '', 'hulu', 'the-most-heretical-last-boss-queen-from-villainess-to-savior', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fabde08c-022d-4e01-9e19-f4c89d5b8cb6.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 169373, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a357197f-7619-418f-8a3b-f991c332729f', 'a351090f-23ca-48ab-b77a-5cabf2abfa0c', 'hulu-the-most-heretical-last-boss-queen-from-villainess-to-savior-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbf31f2b-2d04-485c-829c-17cee7ac108c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c125ac86-c909-47fa-a7ac-ac5b0d844791', 'a357197f-7619-418f-8a3b-f991c332729f', 1, '100151951', '～我儘王女は目を覚ます～', 'フリージア王国の第一王女･プライド。8歳の頃、突如として前世の記憶を取り戻した彼女は、かつてハマっていた乙女ゲーム「君と一筋の光を」の世界に転生していたことに気が付く。このままゲームのストーリー通りに時が経てば、待っているのは極悪非道ラスボス女王に成り下がった自身が国や多くの民を苦しめる最悪の未来……そんなシナリオを変え、全ての人たちが幸せになれる世界を目指して、プライドは前世の記憶と『予知能力』を武器に立ち上がる……。', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbf31f2b-2d04-485c-829c-17cee7ac108c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9005a92-94c5-4511-bc4c-3c60d9cff81b', 'a357197f-7619-418f-8a3b-f991c332729f', 2, '100153031', '～極悪王女は義弟に願う～', '義理の弟になった平民出身の少年･ステイルのことを温かく迎え入れたプライド。ゲーム本来のシナリオでは、自身に憎悪を向けるようになる彼の幸せを願い、プライドはさっそく行動を開始。フリージア王国の王配にして父･アルバートの協力もあって2人は信頼関係を築くのだった。だが、その様子を王国の宰相･ジルベールは快く思っておらず、何やら怪しい動きを始める……。さらに時を同じくして、ゲームの主人公にして王国の第二王女･ティアラと初対面の時がやってきて……。', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/74839e92-23db-4923-96ed-b680761eefb9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74a3ad8f-3595-463b-8a18-240378b6a63c', 'a357197f-7619-418f-8a3b-f991c332729f', 3, '100153542', '～外道王女と騎士団～', 'プライドが前世の記憶を取り戻してから、3年の月日が経過。この間に起こるはずだった悲劇は回避され、11歳のプライドはステイルやティアラと共に平和な時間を過ごしていた。だが、自身のラスボス女王としてのチート能力を実感したことで、ゲーム通りの最悪の未来に近づいているのではないかと不安を募らせるプライド……。そんな中、彼女のもとに王国の騎士団長･ロデリックの率いる兵が奇襲されたとの知らせが届く。彼らを助けるため、特殊能力を使った作戦を開始するプライドとステイルだったが……!?', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fd8e3f1-7800-4d60-a2c7-5db12d6b43fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3d09aace-3992-49be-8f8d-cfbfd4aad18b', 'a357197f-7619-418f-8a3b-f991c332729f', 4, '100154025', '～最低王女と誓いの青年～', '奇襲を受けた騎士団を救うべく自ら戦場に立ったプライド。彼女は、ラスボスとしてのチート能力を存分に発揮し、敵を瞬く間に撃退。見事、ゲーム本来のシナリオで死ぬ運命だったロデリックや騎士たちの救出に成功する。後日、今回の事件について会談の場を設けたプライドとロデリックたち。その場でロデリックから危険を顧みない軽率な行動をとったことを叱責されるプライド。さらに騎士としての誇りと生き方に泥を塗られるところだったと憤る彼に対してプライドがかけた言葉とは!?', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dfffb6a2-a7d1-4b40-923a-195bdb51a56e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('921ad423-a0e5-4716-8f4e-6db0f36cbaca', 'a357197f-7619-418f-8a3b-f991c332729f', 5, '100154958', '～酷悪王女と剣～', '父･ロデリックを救ってくれたプライドへの忠誠を誓ったアーサーは、彼女を護る騎士になることを決意。さっそく稽古を開始し、後に最強の騎士と謳われるまでになる剣術の才能の片鱗を覗かせる。一方、ゲーム内での出来事が頭をよぎり、アーサーやロデリックのことが気になったプライドは、ステイルと共に騎士団演習場へ。するとそこでロデリックの意外な一面を目撃する。さらに時を同じくして演習場にやって来たアーサーは、稽古でステイルと手合わせをすることになり……!?', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8a3f3b4-f6e7-428a-a366-f4f406b6226b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5bc50b3-ebf6-4ac9-bcff-2afc1e43d98d', 'a357197f-7619-418f-8a3b-f991c332729f', 6, '100155410', '～自己中王女は裁く～', 'ゲーム本来のシナリオでは、法律を逆手にとり非道な行いを繰り返していた極悪女王･プライド。11歳のプライドはそんな自分と同じ轍を踏むまいと、法律を正しく運用するため勉強に励むことに。そんな折、母･ローザから次期女王として騎士団を奇襲した盗賊の1人･ヴァルを裁くことを命じられる。本来であれば死罪が妥当であるものの、ヴァルのゲーム設定を思い返し決断を迫られるプライド。果たして、悩める彼女が出した答えとは!?', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1bd956c-0496-4236-9a7c-526b46918bbc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f6618caf-4d1e-44c4-9362-2e793049e7b2', 'a357197f-7619-418f-8a3b-f991c332729f', 7, '100156395', '～冷酷王女とヤメルヒト～', 'フリージア王国騎士団に入隊するために2年間、鍛錬に励んできたアーサーは、見事入隊試験に合格。叙任式の場で、改めてプライドのことを一生かけて護ると誓うのだった。そんなめでたい出来事の後、ジルベールが不穏な動きを開始。以前から推し進めていた国民に特殊能力の申請を義務化させる法案を可決すべく、脅迫気味にプライドに迫る。その様子を見かねたアルバートはジルベールを叱責し、2人は衝突してしまう。翌日、ジルベールは無断で城を抜け出して……。', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/add461cc-77ba-472e-877a-dfeb303c5921.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9cb73e66-a18a-47b7-b4b8-8dbbc1118861', 'a357197f-7619-418f-8a3b-f991c332729f', 8, '100156678', '～無礼王女と裁き～', '婚約者･マリアンヌの病気を治せる能力者を見つけるために暗躍をしていたジルベール。私的な目的の為に王族を裏切り、義姉の名に傷をつける行いをしていたジルベールにステイルは怒りを向け、即座に彼を断罪しようをする。しかし、ジルベールに関するゲーム本来のシナリオを思い出していたプライドはそれを制止。彼の心情を慮り、マリアンヌを助けるべく意外な人物に協力を仰ぐのだった。その後、今まで犯してきた罪を全て告白したジルベールに裁きの時が訪れる……。', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea07007d-b4bf-4639-b8e8-5ae151dd3007.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a790c68b-b254-404e-9cbd-e43e7b898f92', 'a357197f-7619-418f-8a3b-f991c332729f', 9, '100157912', '～残酷王女と罪人～', '凄まじい倍率の選抜試験を突破し、プライドの近衛騎士に就任したアーサー。その結果にプライド、ステイル、ティアラはそれぞれ喜びの声をあげる。後日、公務を終え、宮殿への帰路につく4人は、行き倒れているヴァルを発見する。以前交わした隷属の契約の中の“心から誰かの助けを望む時は私のもとを訪れなさい”という命令に従いやって来た彼に事情を尋ねるプライド。するとヴァルは、一緒に生活していた孤児のセフェクとケメトが人身売買組織に連れて行かれたことや、2人を救出してほしいことをプライドに伝えて……。', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a9a7cab-8f75-4ad3-9004-40d3e4b84ee0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c368633e-441a-4499-89a7-18022e111c69', 'a357197f-7619-418f-8a3b-f991c332729f', 10, '100158278', '～薄情王女は潜入する～', 'セフェクとケメトに対する本当の思いに気が付き、涙を流したヴァル。そんな彼の姿を見たプライドは捕らわれた2人の救出、そして人身売買組織を壊滅させるべく、ステイル、アーサー、ジルベールと共に行動を開始。ジルベールの年齢操作の能力を駆使して、敵の本拠地へと潜入した一同はセフェクとケメトを捜索。さらに敵を制圧しながら、捕らえられていた他の人々を解放していく。そんな中、ステイルは強力な能力を制御できず自暴自棄に陥っている少年と出会い……!?', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/446fb517-2ab2-44db-b903-ef4082fcc00e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a032ada8-83b4-4dbe-b82c-88408b37ba0d', 'a357197f-7619-418f-8a3b-f991c332729f', 11, '100159177', '～惨酷王女と命令～', '一度は窮地に陥るも、見事な連携によって敵を制圧したプライドたち。事件は解決し、後は保護されたセフェクとケメトと合流するのみかと思われた時、プライドたちは謎の爆撃に襲われる。一刻も早く脱出を試みる一同だったが、ヴァルを探すセフェクとケメトが洞窟へ飛び込んでいったとの知らせが届く。そこで、洞窟の崩壊が始まる中、2人のもとへと急ぐヴァルとプライドたち。無事にセフェクを救出したものの、ヴァルとケメトが瓦礫によって閉じ込められてしまい……?', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bda7f06-8a44-4e18-b1ad-df776e1661f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79e77159-68e0-4196-8537-ada8b49cf88b', 'a357197f-7619-418f-8a3b-f991c332729f', 12, '100160044', '～悪虐王女は未来に向かう～', '【最終話】人身売買事件を解決し、平穏な日常生活を取り戻したプライドたち。事件後、ヴァルとセフェク、ケメトは王族専属の“配達人”として働き始め、以前よりも充実した生活を送っていた。そんな3人を見守るプライドは、平和な時間を噛みしめながら、“学校を作る”という自身の新たな目標の為に行動を開始するのだった。一方、実力を高める為にジルベールに稽古をつけてもらうアーサー。その途中、ステイルも加えてアーサー&ステイルVSジルベールで模擬戦を行うことになり!?', '2025/11/01 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c045fc94-fe54-42e5-8df9-089bc45ec3dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('cac8a1b2-56ce-4e9a-bd55-a8d961275d75', '悲劇の元凶となる最強外道ラスボス女王は民の為に尽くします。mini', '', 'hulu', 'the-most-heretical-last-boss-queen-from-villainess-to-savior-season2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94fe3e89-75ac-4d3b-a8f1-7a4dac798646.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 169373, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e5ba4690-6647-40b5-b81b-671ba518aee7', '美少女遊戯ユニットクレーンゲール ギャラクシー', '', 'hulu', 'crane-game-girls-galaxy', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50027081_series_art__338x600_crane_game_girls_galaxy_5c57582986969876eb47f7acc705ff36.jpg?w=331&h=447&p=t', 'hulu', 2016, 3, 1, 'FINISHED', NULL, 21890, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
