INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e626eabe-755a-4835-98d7-3e9b9ca209bc', '4cc238a9-fee7-4b6f-9240-9f003188520e', 1, '60787464', '襲来! ダークチェリー', 'すっかりアイドルとなったクレーンゲールは宇宙ステーションでライブすることに。だがそこに、自分たちを育ててくれた小夜とともに地球侵略アイドル「ダークチェリー」が地球征服のため現れて…!', '2016/10/08 00:00:00', 780, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/639cdab6-0c01-4442-bcbe-eb00fe0d5314.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('60b63868-9748-4737-9972-6d916b1925c8', '美男高校地球防衛部HAPPY KISS！', '', 'hulu', 'cute-high-earth-defense-club-happy-kiss', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb757b7a-8d0b-4b0a-8934-82cd40ad3216.jpg?w=331&h=447&p=t', 'hulu', 2018, 1, 1, 'FINISHED', NULL, 101046, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', '60b63868-9748-4737-9972-6d916b1925c8', 'hulu-cute-high-earth-defense-club-happy-kiss-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19a74c30-1740-4552-bd6f-f0630829581f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd494e8a-2cf9-4d40-b9f3-902b3f4cd583', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 1, '100018601', 'HAPPY! KISSは突然に', '「地球防衛部」を名乗り、かといって何かと戦うわけでもなく、けだるげな日常を謳歌する修善寺鏡太郎、霧島龍馬、和倉七緒、万座太子、道後一六。ある日、5人は黒玉湯に浸かっているときにホニャラランドホニャラ王家の第一王子を名乗るカルルスと出会う。地球をハッピーに統治しにきたというカルルスは防衛部員を手伝いとしてカルルス騎士団ハッピーキッスに勝手に任命。学校で暴れる謎の怪人といきなり戦うことに…!?', '2018/05/07 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19a74c30-1740-4552-bd6f-f0630829581f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87e52259-1bed-47ea-a55f-b704f8980cbd', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 2, '100018602', 'HAPPYのレシピ', '怪人をカルルス騎士団ハッピーキッスとして見事に鎮めた地球防衛部の前に、怪人を生み出した元凶･フラヌイが姿を現した。実は彼はカルルスの腹違いの弟で、次期国王としての資質を示すためにカルルスと競っているのだという。そしてフラヌイの背後にはフラヌイ騎士団エーデルシュタインとなった生徒会役員3人の姿も。彼らは恐怖を広めることで世界を統治すべく、コンプレックスを抱える生徒を怪人へと変えていた。', '2018/05/07 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22416fa1-6a25-490b-8ca4-4e16840f5b07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('436cc81d-21ea-4bf1-a1a5-09d20919c452', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 3, '100018603', 'HAPPYアイスクリーム', '防衛部の部長を務める和倉七緒と、生徒会の役員である宇奈月大樹は魔法騎士としては敵対関係にありながらも以前と変わらぬゆる～っとした態度で接し続けていた。ある日、生徒会のメンバーはアイスクリーム屋でバイトに励む眉難高校の生徒を怪人へと変えるが、そのせいでお店が回らなくなってしまい困った店主に押し切られるまま七緒と大樹が臨時の店員として働くことに。それが思いもよらない大反響を呼び…!?', '2018/05/07 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e425c58-2105-4b3e-be37-abe93d3f2c75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32b18ee8-ee28-44aa-ac4b-cacb3a347188', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 4, '100018633', '素晴らしきかなHAPPY', '黒玉湯の中で「埋蔵金があるかないか」で激しい舌戦を繰り広げる太子と一六の会話に見慣れぬ眉難高校生が乱入してくる。父親が埋蔵金発掘にロマンを追い求めすぎて家庭が崩壊した彼は「埋蔵金はない!」と強く言いきった。そんな中、眉難市のとある山では埋蔵金発掘番組の収録がスタート。防衛部の5人はそれぞれ思い思いの邪な思惑の為ボランティアでロケに参加するのだが…。', '2018/05/07 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03b110c5-4cae-4da8-9124-b2e27503c1f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a27533d-9a9e-443b-98e6-658e23b23b82', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 5, '100018995', 'HAPPYに美しく', '突如眉難高校に発生した長蛇の列。それは生徒会役員の白骨マーサがスペシャルレシピで作ったという評判のクッキーを求める生徒の列だった。そんなクッキーに引き寄せられるようにやってきた一人の生徒。フラヌイは早速この生徒から不幸の匂いを感じるのだった…。一方、マーサは道後一六の姿を見るやいなや逃亡。はたして二人の過去にはどんなドラマがあったのか?', '2018/05/14 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95349bec-8fb9-4e14-bd41-e15ac78a7227.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4cd8b1c-4057-49e9-9c43-bbdf64170f96', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 6, '100019187', 'HAPPYアイデンティティー', '梅雨シーズンに突入しても一向に傘を持ってこない鏡太郎。龍馬が相合傘で鏡太郎を入れてやるが、そんな様子を目にした生徒会の阿多はそっとこぶしを握りしめる。黒玉湯で放課後の憩いのひと時を楽しむ防衛部、その様子を陰からうかがう怪しい影…。「痴漢かっ!?」と焦る防衛部だが、その怪しい影は暇そうな防衛部を見て、誰でもいいから仲良くなりたいと思っている眉難高校の生徒だった…。', '2018/05/21 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90c2a247-3095-4e3f-b5e5-754a5385bfd3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97960f1c-8690-4ad7-bf4c-87901a2fad2b', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 7, '100019692', 'バタアシHAPPY', '眉難高校の100年以上続く学年対抗の伝統行事『眉難高校 男だらけの水泳大会』(美男子コンテストもあるよ☆) が開催される。一六やマーサのように気合を入れて水着を用意するものもいれば、大会への参加を憂鬱に思う泳ぐのが苦手な生徒もいたりとその印象は千差万別だった。さまざまな想いが交錯する中、いよいよ大会はスタート! しかし、予想外の事態が次々と発生して…。', '2018/05/28 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1ff4bd9-2e0a-4f05-9a05-fa5bc123f7eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b25701e9-066c-46a8-be31-72140b76cb3b', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 8, '100019936', 'HAPPYエンドレスサマー', '物語は夏休み。防衛部のメンバーは黒玉湯にぼけ～っと浸かりながら相変わらずの毎日を送っていた。カルルスの「日本の正しい夏休みを送りたい!」という願いに屁理屈ばかり言う鏡太郎。埒があかないと思ったカルルスは鏡太郎に「お願いを聞いてくれたら…」と耳打ちする。それを聞いた鏡太郎はコロッと態度を一変! カルルスの「日本の正しい夏休み」の為に、残りのメンバーを連れて夏休みの思い出作りに奔走するのだった…。', '2018/06/04 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1e3af29-feae-4c40-9347-4b65f3123245.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24ea2d52-6bba-450f-b3cd-74192e0b0267', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 9, '100020275', 'HAPPYダイス', '部活動としての体裁を保つために文化祭への参加を決めた防衛部。なかなかいいアイディアが浮かばず、部員たちが部室を大捜索してヒントを探した結果、見つけたのは『パーティーサイコロ』! 参加者同士が親睦を深めあうこのアイテムが出しものとしてピッタリだと言い出す修善寺。一度は納得する部員たちだったが、文化祭当日は閑古鳥が鳴くハメに。部員たちは客寄せのために身体を張ってゲームを実演して見せるのだが…。', '2018/06/11 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f73ca4ec-6eda-48c9-8ce9-306cc6674808.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('269eb4c5-24f2-4fc6-ab10-c4ce09613a99', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 10, '100020928', 'HAPPYオールドメン', 'いつものごとく黒玉湯でくつろぐ防衛部の5人。話題は鏡太郎の言動がお爺さん臭いという話に。翌日いつも通り眉難高校に登校するが、階段の途中で息切れを起こす一六、後ろから来た太子に「お前、お爺ちゃんになってるぞ!」と言われ驚くが、言った太子もお爺ちゃんになっていた。「昨日、鏡太郎先輩のことお爺ちゃん扱いしたから呪い…?」と焦る一六だが、周りを見渡すと校庭にはお爺ちゃんになった生徒であふれかえっていた!?', '2018/06/25 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e923b11f-7aa9-4232-a046-4dbab48acf12.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1571c461-6561-4546-aba6-d1e7503f6621', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 11, '100021209', 'あと1センチのHAPPY', '鏡太郎の何気ない一言に怒りを爆発させた阿多。エーデルシュタインとハッピーキッスの全面対決がいよいよ始まる! 激しい戦いの最中、ついに阿多の口から積年の恨みが語られる。それは幼い日の苦い記憶で…。', '2018/07/02 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1db8d74-3337-4226-a86a-9ac3591a951a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc72fe8f-aef2-4080-b324-309f3f36662a', '12d1541f-3fa1-49b5-bcc1-d8d8d22c4c4b', 12, '100021623', 'いつも心にHAPPYを', '【シーズン1 最終話】ホニャラランドへとやってきたハッピーキッス。彼らが見たものは、凄惨なクーデターの現場だった。反乱軍に捕らえられたカモパパ王の姿に激しく動揺するカルルスとフラヌイ。そんな二人を励まし、反乱軍に立ち向かうハッピーキッスの最終決戦がついに始まる!!', '2018/07/09 12:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92996c12-2ad3-4f3a-b20e-089ec6a420af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
