INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4196e2c0-2ceb-4824-867b-a7e58499349c', '姫様“拷問”の時間です', '', 'hulu', 'himesama-goumon-no-jikandesu', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7101e1f0-1476-4286-88fe-6de2fb868ad5.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 166522, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', '4196e2c0-2ceb-4824-867b-a7e58499349c', 'hulu-himesama-goumon-no-jikandesu-s1', '第1期', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa4ee064-068c-434b-9da3-e8d1251c52bb.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aaae1e84-09f9-45dc-9e4f-22b35baca319', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 1, '100171398', '第1話', '国王軍と魔王軍が衝突をはじめ、幾年月。王女にして、国王軍第三騎士団“騎士団長”である姫は魔王軍によって囚われの身となっていた。魔王軍の最高位拷問官、トーチャー･トルチュールは、王国の秘密を聞き出すべく、姫への“拷問”を開始する。次々と繰り出される苛烈な“拷問”に屈することなく、姫は秘密を守り通す事が出来るのであろうか…?', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa4ee064-068c-434b-9da3-e8d1251c52bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31ca2e47-0c95-4ee0-ae58-f47a2bd8ff0c', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 2, '100172002', '第2話', 'テレビゲームを用いた“拷問”を得意とする陽鬼と陰鬼。愛くるしい赤ちゃん白熊で翻弄するクロル。大きな体と母性で優しく包み込むジャイアント。新たに現れた個性豊かな拷問官たちによる“拷問”が姫に牙を剥く。トーチャーは「ゴリラのマーチ」を用いた“拷問”を始めるが、姫には「ゴリラのマーチ」にまつわる思い出があるようで…。姫は屈さずにいられるのだろうか。', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1636f111-249d-4535-aa44-40a3b27394f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3569948c-2959-4ae9-9ea0-e80bf704d4d2', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 3, '100172858', '第3話', '陽鬼と陰鬼に遊園地に誘われた姫。外出許可をトーチャーに求めると、引き換えに王国の秘密を要求されてしまう。拷問官との友情か、王国の秘密を守るのか…姫の答えは? さらに、姫の前に魔王の一人娘であるマオマオちゃんが現れる。マオマオちゃんから繰り出される“拷問”に敢え無く屈してしまう姫の元に、ある人物が救援に駆け付けた。', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50eac553-19fe-4e3a-b05a-4f791932a24a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('366ff4a0-4e2a-484b-a1b8-c00b5fb58211', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 4, '100173670', '第4話', '魔王が満足する情報を姫から引き出せないトーチャーは、“拷問”の腕が落ちたのでは…? と疑われていた。技術を量るべく、自らを“拷問”せよと迫る魔王に対して、トーチャーが繰り出す一手は如何に。新たに現れた拷問官、武器職人のギルガによる“拷問”相手は姫ではなくエクスだった! エクスは姫の二の舞いにならず、王国の秘密を守り通せるのか!? ほか、クロルやマオマオちゃんも登場!', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f7b630d-5f45-431a-84d3-eff7d34fc3a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31661542-d706-4fa2-a450-a27dc0b9c771', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 5, '100174964', '第5話', '川辺での“拷問”。姫は川遊びを期待していたが、トーチャーが取り出したのは、姫が苦手としているマシュマロだった…。がっかりする姫だったが、アウトドアならではの“拷問”でトーチャーの手腕が発揮される。他にも、ジャイアントと行く初めてのサウナや、陽鬼発案の学校を使った肝試しで、夏らしい“拷問”を堪能する姫。しかし肝試しの当日、あるトラブルが起きてしまう。', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/948e98d0-f5ce-4d7b-ac84-38d153c93db9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75d75139-eb5b-4036-b6af-05948aae57ac', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 6, '100175144', '第6話', '「ハイパー上級見習い拷問官」から「やったねグレート見習い拷問官」に昇格したマオマオちゃんに、父である魔王はご褒美を与えようとする。さて、マオマオちゃんが魔王にお願いしたご褒美とは? 一方、姫への“拷問”は月に一度の健康診断でお休み。魔王軍の手厚い福利厚生に驚くエクスをよそに、採血の準備をするトーチャーだったが、姫の様子がなにやらおかしくて…?', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89b385dd-e39c-42d4-8400-196f0f9f399c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f229c40e-2436-47a2-9dd7-fa07839bac8a', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 7, '100175716', '第7話', 'クロル隊所属のネコ･シロにゃんとミケにゃんと共に癒やしの“拷問”タイムを満喫したり、マオマオちゃんが通う幼稚園の運動会に応援しに行ったり…可愛いものに姫は屈し続ける。時を同じく、マオマオちゃんの応援をするため運動会に参加していた魔王は、姫との直接対決の舞台を用意していた。運動会で行われた決戦とは――。', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f4203d2-e8af-487f-b0af-3bbceca204fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('943ba5e7-9b1b-4a98-9d94-1b4f748761f9', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 8, '100176341', '第8話', '上級拷問官になるための昇級試験に挑む陽鬼と陰鬼だったが、健闘むなしく魔王から不合格を言い渡されてしまう。二人は“拷問”の対象であり友達でもある姫にアドバイスを求めることに。ときに、姫の前に新たな拷問官が現れる。彼女は魔王軍の中で最も残忍酷薄な吸血鬼一族、ペシュッツ家の娘、バニラ･ペシュッツ!「恐怖と絶望の本物の“拷問”」を策略するバニラが姫に牙を剥く。', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3272d1f0-36ad-4f81-8bb6-6bc3e579e771.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59205f13-937d-46d7-9b74-acbd89e67374', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 9, '100177094', '第9話', '出張中のトーチャーは仕事を終え、ホテルで疲れた体を休めていた。普段はバランスを考えた食事をとる彼女だが、今日は出張のため特別。トーチャー流「頑張った自分へのご褒美晩ごはん」が始まる。魔王城では魔王とルルン、マオマオちゃんが家族でクッキー作りに挑戦! 初めてのクッキー作りに、「上手にできるかな」と意気込むマオマオちゃん。マオマオちゃんの就寝後には、魔王と王妃･ルルンが語らう姿も。', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7883d93e-9857-4ab4-ad62-ebfeb3a5b0bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f3a5f10-f972-405e-8058-74cb9f851c88', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 10, '100178073', '第10話', '海にやってきた姫たち。今日の“拷問”は陽鬼･陰鬼VS姫のビーチチャンバラ! 姫が勝利した場合の条件は「どんな願いでも叶えること」。その願いがたとえ「釈放」でも――。対する陽鬼と陰鬼は、魔王主催のビーチチャンバラ大会タッグ部門2年連続優勝者。果たして、勝敗の行方は。かたや魔王城には、姫を助けに来たルーシュの姿があった。覚悟を決めたルーシュの背後に、突如魔王が現れる。王国の“聖白騎士”と全魔族の頂点が、ついに邂逅する! ほか、新たな方法で姫を“拷問”するバニラや終業後のトーチャーの姿も。', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c565f7c8-dac1-43b7-90e9-f48d464fe394.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('648e62ee-8ede-4802-9c86-cbea857600e1', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 11, '100178565', '第11話', '双子のパンダと手をつなぎ、楽しそうに踊る姫。傍らでは何やら口調のおかしいエクスが手拍子をしている。「あ…夢だこれ。」すぐに気付いた姫は、夢の中であれば屈し放題! と屈し続け、王国の秘密を話し続けた。秘密は夢の中に留まらず、寝言として現実でも垂れ流されていて…!? …またとある日、魔王城で研究中の魔法が暴走し姫以外のみんなが子供になってしまう。 そんな時でも魔王軍は“拷問”を欠かさない。子供の拷問官などに屈さないと息巻く姫だったが…?', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28a326fe-7a81-4ad6-bb70-6605c6574c38.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c2639fd-4064-4e23-ba38-3fc455f7cc9a', 'a3b2bbdc-e9b2-48d1-9af1-5d28553b7700', 12, '100179177', '第12話', '【最終話】晴れて友達になった姫とバニラ。バニラは初めての友達に戸惑いつつも、勇気を出して姫をアイススケートに誘う。ただ友達として遊びに来たつもりのバニラだったが、姫は“拷問”と勘違いしてしまっていた。姫の誤解は解けるのか。さて、魔王軍にも人事異動の季節がやってきた。なんと、トーチャーが姫に行う“拷問”は今日で最後かもしれないというのだ。今日は絶対に屈しない決意を固めた姫が、最後の (?) “拷問”に立ち向かう!', '2026/01/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b558355-5f81-4d5f-b94e-1fee5a3a5b90.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('be9709ee-8557-4e51-8433-6ec1618e0ae2', '4196e2c0-2ceb-4824-867b-a7e58499349c', 'hulu-himesama-goumon-no-jikandesu-s2', '第2期', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bbefae90-de12-4324-adeb-76db60a8b3ee.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9faf4531-503b-4c00-a279-a1d4acb52958', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 1, '100250777', '第13話', '暴走魔法が原因で記憶喪失となってしまった姫…心配したトーチャーは姫の記憶を呼び覚ますために初心に返って拷問をすることに――。そして、魔王が好きなアニメの2期が決定し、魔王城の皆にケーキがふるまわれるが……トーチャーの拷問の手が姫に迫るのだった。またとある日、バスケをしようとの魔王の呼びかけに皆が集まってバスケをすることに……それはこれからもずっと続く、どこか楽しい日常を感じさせるのだった。', '2026/01/16 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bbefae90-de12-4324-adeb-76db60a8b3ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9afd9ad6-3f09-4525-903c-276b12ee7c55', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 2, '100251506', '第14話', '魔王を狙ってやってきた暗殺者･サクラは魔王城に忍び込むものの囚われてしまう――サクラは東南の小さな国で暗殺者をやっていたと告白し、かつて失敗した任務について話すのだった。そこにはどこか懐かしく、悲しい感情が混じっていた……。一方で姫を拷問するのは陰鬼――知恵の輪を駆使して姫を拷問しようとするが、姫の圧倒的な腕力の前に苦戦を強いられることに……さらにクロルは可愛いウサギを連れて姫に拷問を仕掛けるが、トーチャーの様子がどこかおかしいことにまだ誰も気づいていない…。', '2026/01/23 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ab5b7f6-1e9a-41d1-a720-28dc833f2094.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46929abe-2bdb-47ea-bbef-7d592f7cef69', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 3, '100252113', '第15話', '魔王軍に入ることになったサクラは、トーチャーと共につかの間の休暇を楽しむことに。サクラと過ごす中で姫への拷問のヒントを得たトーチャーは早速試そうとして…? 過酷な拷問生活に姫の体の節々が悲鳴を上げている――それを聞いたジャイアントは姫を連れてとある場所に赴くことに…。また、いつもと少し違うマオマオちゃんの拷問に驚いた姫は、屈してしまうのだろうか…?', '2026/01/30 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7fb09a03-350e-4c9c-92d6-32653729f443.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bde28f82-00c7-42c6-a165-c8acc9e6f045', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 4, '100252818', '第16話', 'SNSで人気のプロハムスター、魔界ハムスターのハムちゃん――得意なチンジャオロースで姫に挑むことに…!!「伝説の剣を使いこなす人物」そう見込んでギルガの協力を受け入れた姫は一緒にチャーハンを作ることに――チャーハンは火力が命!! 最高のチャーハンを作ることはできるのだろうか…。バニラに確実に拷問を成功させようとするバニラの父･アリオートはメイドのコンと考えた秘策を伝えようとするが――そこには自信に満ちあふれたバニラの姿があった。', '2026/02/06 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e190e854-0157-44b2-9f15-52502f9b9365.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cead3df1-11c7-4467-a720-8bfa78527488', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 5, '100253280', '第17話', 'いつものごとく拷問のため姫の部屋を訪れるトーチャーだが、まさかのミスで拷問まで少し時間が空いてしまう…。姫とトーチャーはその時間を利用して普段の生活や昔のことについて話すことに――。姫への拷問に使う映画を悩んでいる陰鬼に、そっと背中を押す陽鬼。好きな映画を姫と一緒に見れたことで自信をつけた陰気は新たな拷問を思いつき…。', '2026/02/13 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eff68743-95ce-445f-95d8-7de8c650c273.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c10ad241-565a-4331-9eba-91c8d7b6a8f8', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 6, '100253964', '第18話', '本日のマオマオちゃんの拷問はバルーンアート。バルーンが上手くできなかったその瞬間――颯爽とルルンが現れて…。魔王が口内炎になった――その報告は魔王軍幹部に激震を与えた!? 魔物特別休暇を取得した魔王はストレスから解放された健康的な生活を送ることになり、ルルンとマオマオちゃんとの休日家族ライフが始まることに…。一方で姫も「呪病炎眼」という病気にかかってしまう…。', '2026/02/20 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ffaf6bd-3f65-4687-9b26-a18c5fb07650.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('49503ddf-e8a3-4bb6-85c8-8567df96f4c4', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 7, '100254793', '第19話', 'サクラの指導をするトーチャーは初級拷問官の試験を受けるように勧める。得意な拷問を決めあぐねていたサクラだが、トーチャーと過ごすうちに少しずつ自分自身を見つめ直すことができて…。ガックシと肩を落とすクロル…姫の希望だったペンギンを呼べなくなってしまったとのこと――だが、プロの意地で現れたペン太、彼には芸だけではない秘密もあるようで…。ある日、研究中の魔法が暴走し姫が鳥になってしまった!? 姫は元の姿に戻ることはできるのだろうか…?', '2026/02/27 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85b67c4c-6f9c-413b-b0d0-ed4a58ca167c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eac83a5f-5c2d-4b3b-a73c-31fe5a331c22', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 8, '100255648', '第20話', '今日の拷問は――マオマオちゃんと、まさかの魔王城幼稚園の園児たちだった!? 練習したハンドベルを無事に演奏することはできるのか…。友達である姫とお祭りにいきたいというバニラは、単身で姫の部屋を訪れる――だが、そこには既に陽鬼･陰鬼に誘われている姫が……そっと肩を落とすバニラの携帯が鳴った。それは姫からの誘いの電話だった――。祭りの最中、射的の拷問を仕掛ける陽鬼たちは、姫の優れた腕前を目にして秘策を用いるのだが…。', '2026/03/06 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/943a1e8b-6ea3-45fa-a109-0c579c66d3ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f250f0e8-2b4e-4461-ac16-179fc27b52ec', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 9, '100256408', '第21話', '過去と向き合い、人の幸せのために拷問官となったサクラ。初めての拷問に意気揚々と拷問部屋の扉を開けるとそこには、過去暗殺対象だった姫がいて――。姫は拷問に屈しないよう、魔道具を使って自分を止めるようにエクスに指示するが、誘惑に抗えない姫へ躊躇なく魔道具を使うエクス…姫は最後まで拷問に耐えることができるのだろうか!? ある日、研究中の魔法が暴走し、トーチャーの人格が乖離した…闇の人格と語るトーチャーの拷問とは一体…。', '2026/03/13 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1fcf2241-e16f-44ba-8ad4-04ddb9f5d560.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5f7f219-b6e5-4886-b106-cd0365edd59e', 'be9709ee-8557-4e51-8433-6ec1618e0ae2', 10, '100256882', '第22話', '国王軍第一騎士団の聖白騎士ルーシュ･ブリタン――姫を救出するために新魔法を開発してやってきた。その魔法とは「心が綺麗な人にしか認識できない魔法」、この魔法で無事に脱出することができるのだろうか…。実家に帰っていたトーチャーは拷問の時間ギリギリまでコタツの誘惑と戦っていた…無事に遅れずに拷問へ行くことができるのだろうか? バニラのエスコートで一緒に出掛ける姫や、公園で出会ったパパ友と語らう魔王の親同士の一幕も。', '2026/03/20 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c45151e0-4d98-4a54-9ce8-9f1644928fa6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ad6ecd51-bfab-4574-8ccc-20063f919f62', '百千さん家のあやかし王子', '', 'hulu', 'the-demon-prince-of-momochi-house', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c4a6f01-bb44-45f9-8a0f-771d78ef18be.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 167146, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e17b1517-79d4-410b-8c1b-796f45211633', 'ad6ecd51-bfab-4574-8ccc-20063f919f62', 'hulu-the-demon-prince-of-momochi-house-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c93342b4-4f09-491c-89f8-1f4182a298fa.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1aabede-7354-45cf-b05b-3155e7acbbb6', 'e17b1517-79d4-410b-8c1b-796f45211633', 1, '100171005', '百千さん家のあやしい人々', '赤ん坊の頃に両親を事故で亡くし、施設で育ってきた、百千ひまり。そんなひまりの16歳の誕生日に突然、亡くなった両親からの遺言状が届き、「百千家」を相続することになる。いざ、地図を頼りに百千家に辿り着くと、そこには葵と名乗る謎の少年のほかに紫、伊勢と呼ばれる先住人が…! ひまりは彼らに「百千家の主は葵だから出ていけ」と言われてしまい……!', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c93342b4-4f09-491c-89f8-1f4182a298fa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74b95fa1-4acb-476f-9169-14d28f17670a', 'e17b1517-79d4-410b-8c1b-796f45211633', 2, '100171812', 'マヨイガ', '百千家での新生活が始まり、ひまりは亡くなった両親の手がかりを探すも、謎が増えていくばかり。葵は何かを隠しているような様子なのだが、ひまりが質問してもはぐらかされてしまう。モヤモヤが募る日々を過ごすひまりは、ある日、百千家の中で、室内にも関わらず、桜の花びらが舞い降りてきたのを発見し――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7b32ae4-88c5-4f4e-84c9-bb3d6517544c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('352de8a2-d6ee-4d33-ba31-87a2030ce85d', 'e17b1517-79d4-410b-8c1b-796f45211633', 3, '100172638', '四人目の友達', '転校初日、緊張する中、クラスでの挨拶を終えて優しいクラスメイトたちの反応にほっとするひまり。早速、放課後にクラスメイトを百千家に連れて行くことに。葵たちとの同居を怪しまれないために、協力を頼むひまりだったが、現れた葵や紫、伊勢の姿を見て驚いてしまう。さらに、葵から「友達が死んでいる」と衝撃の一言が……!', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9979c60-f25e-434b-8cb5-b1b47bb8fab1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1423a93-f524-4fb5-b37b-9ed00629016e', 'e17b1517-79d4-410b-8c1b-796f45211633', 4, '100173469', '闇に燃えし紅の', '火車を家に招き入れてしまった日から、百千家の封印が壊れ、妖怪が溢れてしまっていた。再封印の対応に追われる葵たちに、ひまりはあるマークが見えると話す。ちょうどその時、鵺が火車の罠にかかってしまう。鵺を救うために伊勢は「猩々」の姿になるも暴走してしまい……。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75f8ecfa-f7d0-4691-88b5-2c84045f3f70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e636d5c-7e10-444d-9ef4-8b1a6ed5ef8f', 'e17b1517-79d4-410b-8c1b-796f45211633', 5, '100174278', '夕焼け稲荷', 'クラスメイトの日高に「自分に近づくと呪われる」と言われてしまうひまり。斑目たちに聞くと、日高はどうやらあまり学校に来ておらず、変な噂があるという。気になったひまりは彼の家に行くも拒絶されてしまう。また帰り道に出会った狐面の子供にも「日高にこれ以上近づくな」と言われてしまう。この出来事を葵に話すと、どうやら日高のことを知っているようで――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ec96e8f8-ca28-44bf-ad4b-f5a6b9173813.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd2f4ee1-6137-4aec-8389-2ed208c53f0c', 'e17b1517-79d4-410b-8c1b-796f45211633', 6, '100175065', '泡沫今昔', '水場にしている泉の穢れをどうにかしてほしいと妖たちに頼まれる葵。幽世の泉の水源は龍神様の聖域のため、本来、泉が穢れることはあり得ないようだ。龍神様と縁があるという紫が龍神様と交信を図るも失敗に終わってしまう。龍神様に何かあったのではと紫たちは泉に向かってみると、穢水のせいで泉は真っ黒に。それと同時に紫が倒れてしまい……。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3373f72d-8649-4fa1-a0bf-eac369d4f1da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a840934e-77c9-4341-84d8-5d6a2420cb77', 'e17b1517-79d4-410b-8c1b-796f45211633', 7, '100175450', '誰そ彼の、のぞき鏡', '葵に抱きしめられてから、その時のことを夢に見たり、彼の顔をまともに見ることができなくなってしまうひまり。授業中も葵のことを考えて集中できないでいるひまりは、那智先生に注意され、放課後に古文準備室の掃除をするように言われてしまう。掃除をしているひまりは「のぞき鏡」と呼ばれる古い鏡を見つける。それは「人が一番覗きたいものが映る」と言われているもので――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf497dd7-1ad8-41ee-a0d2-4b9679d22df5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43f2182d-7b95-4a92-8f30-198ed2894a09', 'e17b1517-79d4-410b-8c1b-796f45211633', 8, '100176152', '猫と迷い子', '意を決したひまりは葵に想いを伝える。一方、葵は、ここ数日謎のスランプで封印がうまくいかず、百千家に妖が溢れかえってしまう。そのせいで幽世では百千家が通り抜け自由になったと噂になってしまっていた。そんな時、葵を心配した妖･猫ばぁばが百千家に現れる。猫ばぁばは葵に早く一人前の妖になれと言い、嫁をとらせようと彼にお見合いを勧める。ひまりはなんとか葵のスランプを治し、彼のお見合いを止めようとするが……!', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7f82300f-2775-488a-8045-bbcaa2eccc54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c66971f5-0c4e-4c3d-8afc-93715fa812b9', 'e17b1517-79d4-410b-8c1b-796f45211633', 9, '100176736', '濡れ羽色の嵐', '幽霊がいるという噂を確かめるために、ひまりはクラスメイトと籠目公園に来ていた。幽霊や不審者がいないことがわかり、帰ろうとした時、どこからか不気味な風と歌声が聞こえ、男が現れる。その正体はみんなを驚かそうとした妹尾だった。どこか様子のおかしい妹尾を気にしつつも、百千家に帰るひまり。その途中、また不気味な風と共に歌声が聞こえてきて――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2943db0d-812c-450d-bc1e-f034d279bb21.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30d56d78-e91a-49e1-9c38-26f864555409', 'e17b1517-79d4-410b-8c1b-796f45211633', 10, '100177483', '思ほゆの棚', '突然、百千家にやってきた影の正体は、那智先生だった。葵は那智を「お兄さん」と呼び、古くから関係があるようだ。鵺に変身できず戸惑う葵に、那智は穏やかに微笑む。那智の目的は何か? 葵と那智の間に一体、何があったのか? 過去の縁がついに明らかになる――!!', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72090e96-5aff-49d4-b034-b1e8518bebed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad54c2f7-a69d-45de-b3a1-1b54b688b4df', 'e17b1517-79d4-410b-8c1b-796f45211633', 11, '100178304', 'あおい黎明', '思ほゆの棚で、念願であった両親の思い出を知ることよりも、葵の棚を選んだひまり。そこで葵の両親や幼少期の出来事、那智との出会いが明かされる。すべてを知ったひまりは静かに涙を流すも、強い瞳で葵と百千家の家族を救う決意する。すべての妖を憎み、滅ぼそうとする那智との因縁の対決の行方は――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a425f9b-9570-422a-a128-144ce73e07de.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32467261-60fa-44cd-b74c-54a2dbf7c071', 'e17b1517-79d4-410b-8c1b-796f45211633', 12, '100178648', '万里に渡る灯火', '【最終話】那智との闘いに決着がつき、百千家に平和な日常が戻ってきた。「お疲れ様パーティー」を開催するために、みんなで準備を進める中で、葵はひまりに思ほゆの棚の話をする。そして、葵はいままでひた隠しにしていた、彼の秘密を語り始めるのだった――。', '2025/12/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63f602f7-00e3-4bf4-87c4-6cfcdcd141cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ee72c886-781a-40b9-9e84-fbd33fdb0357', '百妖譜', '', 'hulu', 'fairies-album', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c973cc97-7e32-4148-8e8c-7472b9ac92a8.jpg?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'FINISHED', NULL, 114136, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0e85f0de-feda-47ce-ab23-9713595b9391', '氷菓', '', 'hulu', 'hyouka', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7eb226b1-b02c-4a9f-9102-8eb2ae36a9f8.jpg?w=331&h=447&p=t', 'hulu', 2012, 1, 1, 'FINISHED', NULL, 12189, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', '0e85f0de-feda-47ce-ab23-9713595b9391', 'hulu-hyouka-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac250b87-c266-4732-990e-fa2398307a88.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ac1ba68-0d06-49ff-8a70-d16f3bfd4708', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 1, '100036869', '伝統ある古典部の再生', '省エネを自称する折木奉太郎は高校に入学しても灰色人生を突き進むはずだった。ところが、ソウハさせまい! と千反田えるになし崩し的に古典部に入部させられ…。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ac250b87-c266-4732-990e-fa2398307a88.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('237f28ba-113c-4df4-ab96-e59ffdfe16cc', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 2, '100036870', '名誉ある古典部の活動', '最後の「古典部」メンバー、伊原摩耶花登場。彼女には少し気になっていることがあった。好奇心を爆発させたえるは、思わず奉太郎に!?', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc98a273-cb12-4314-b131-1ecd4f13c650.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fb138d1-4c0c-4105-890c-4a517213ca27', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 3, '100036871', '事情ある古典部の末裔', 'イケメン先輩、遠垣内将司登場。遠垣内から文集のバックナンバーを手に入れるために追いつめて行く奉太郎。後がない遠垣内の理性が壊れた!?', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1b70b3da-1b4f-423d-991e-9313be0d8a42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d57bff4e-6438-450b-850a-da1c7b23ef63', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 4, '100036872', '栄光ある古典部の昔日', '奉太郎たちを自宅に誘うえる。えるは奉太郎たちのために一生懸命に振舞う。思わず彼女の部屋を見てしまった奉太郎、おお、何と言うことだ!?', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ae7c084-397e-4a77-9b5e-7361b39204e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87f3b4a1-feb2-406d-b771-a0dbb073dfcd', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 5, '100036873', '歴史ある古典部の真実', '四十五年前の真実。それを知る意外な人物。その人物と関谷純との間に何があったのか。えるが号泣した謎に迫って行く!!', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6431907-2f98-45bd-82b9-0eee8b62b99f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66e9bf35-1077-4f1f-8229-a0f9cc411003', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 6, '100036874', '大罪を犯す', '怒号が飛んでくる。叫ぶえる。いったい何が起こったんだ!? つい気になってしまった奉太郎はえるに真相を尋ねてしまう。実はですね…。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06e5cf93-7783-4b61-86f7-270eb5cb3d02.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82e4defc-a28c-4621-aa89-f14a9091894a', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 7, '100036875', '正体見たり', '温泉旅行。摩耶花の親戚の姉妹、善名姉妹登場。えると奉太郎は二人、温泉に入りに行く。服を脱ぐ二人。湯に浸かる二人、浴衣姿の二人…。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89824c29-9b4b-49bc-9896-b6a342e664ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce7e0f93-2b7f-4724-9b92-d0e6eaab8c7c', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 8, '100036876', '試写会に行こう!', 'とある知人から文化祭で上映する映画の試写会に来て欲しい、と誘われたえる。早速、古典部メンバーで映画を観ることに。ところがその映画はとんでもないものだった。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3219a63-1831-402b-9634-a2e484509632.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('994cdc77-e935-43be-9b80-a16104faf5fa', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 9, '100036877', '古丘廃村殺人事件', '映画の真相を究明すべく、探偵役三人が登場する。探偵役三人の意見を聴く奉太郎たち古典部メンバー。中でも沢木口先輩の推理はあっけにとられるほどのものだった。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f30c74a-1327-4fb3-899c-393e548b939d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6664c83f-8b9b-4661-b3d6-a65b0c0c7fb6', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 10, '100036878', '万人の死角', '入須冬美は思わせぶりな態度で奉太郎をお茶に誘う。あの冷静沈着な入須のいつにない様子に、奉太郎、まんざらでもない。入須が奉太郎を誘った本当の理由とは!?', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59522368-52e9-4ee5-9e87-199293985605.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0172a88-f960-408a-84ae-8143027610fe', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 11, '100036879', '愚者のエンドロール', '奉太郎に詰め寄る摩耶花。真意を確かめる里志。自分自身の思いを伝えるえる。三人のいつになく厳しい表情に困惑する奉太郎。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bda3f178-46be-4e12-9866-b0533008c22a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cdd27bb3-6f0a-4b93-8941-a904e9abba3a', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 12, '100036880', '限りなく積まれた例のあれ', '陸山生徒会長の開会宣言によりいよいよ始まった「カンヤ祭」。せっかくの楽しい文化祭なのに古典部四人は浮かない顔。いったい何があったというのか!?', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0ad5adf-0ef9-4edd-a267-1224c9c55192.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('977483f2-2a9a-42b7-ad7b-d6d6e4a6bfbf', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 13, '100036881', '夕べには骸に', '漫研部で対峙する河内先輩と摩耶花。でも二人とも普通ではない格好をしているため、少し滑稽な雰囲気も…。どんな格好何だろう。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b9ed490-5e4b-44aa-ab80-59166de7489f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6b8d29a-e62a-4309-821d-d01308cf6a75', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 14, '100036882', 'ワイルド･ファイア', 'お料理対決に参加した古典部の三人、える、里志、摩耶花。里志からえるとバトンが渡され順調に料理を仕上げていく。でも最後のバトンを受け取るはずの摩耶花がいない。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78a578e4-2071-48e5-9fab-59a04b56166e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e326ac6d-e25b-4858-8abb-54caefe7181f', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 15, '100036883', '十文字事件', 'お料理対決「ワイルドファイヤー」で優勝した古典部。優勝の余韻冷めやらぬうちに、えるがまた気になる事件を持ち込んだ。「十文字事件」。十文字はなぜ事件を起こしたのか!? 気になります!', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa099780-7bc8-40f5-8a6a-b72f780d15bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0a40f30-25a6-4eed-9139-fc16d2410954', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 16, '100036884', '最後の標的', '怪盗「十文字」を現行犯逮捕しようとする里志。一方、奉太郎は相変わらず、店番。そんな中、奉太郎の姉、供恵が学校にやって来る。店番をしている奉太郎に供恵が渡したものとは…?', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06a6f5a1-3624-471e-8e1a-1c1611307bdd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2df03f3e-b5a0-40e1-8799-8a101b6f7a82', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 17, '100036885', 'クドリャフカの順番', '果たして古典部に現れるのか、怪盗「十文字」!? 大勢のギャラリーを前にターゲットとなる「校了原稿」を前に緊張する古典部の四人。結局、四人は怪盗「十文字」を捕らえることが出来たのか!?', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb9f0212-e19c-410c-9885-888f5faa2df7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a2c5bf39-5ded-4e55-bbc1-de1df10ecb5d', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 18, '100036886', '連峰は晴れているか', '上空を飛ぶヘリコプターの音で、中学時代の英語の小木先生のことに思いをはせる奉太郎。ふと、小木先生がヘリ好きだったことを思い出す。ところがどうやらそれは真実ではないらしい。里志も摩耶花もそんな話耳にしたことがない、と言うのだ。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2bb8721e-93de-4d4a-96bf-5689d20911c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('896ed4af-dc24-45b8-83d8-1b0fd1a3eb9c', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 19, '100036887', '心あたりのある者は', '奉太郎の推理を才能と褒めるえる。奉太郎自身はそんな「たいしたものだ」と自分のことを言うのは違うと反論する。そんな時、古典部部室全体を校内放送の音声が包んだ。この放送がとんでもないことになっていく!?', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f12b7eb-6f2d-4049-9ac4-993a03c5f8fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19afe159-bda1-43d7-b3bd-895ac006fc2a', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 20, '100036888', 'あきましておめでとう', '正月早々からえるに呼び出される奉太郎。えるの新春の挨拶に付き合うことになった奉太郎。えるの着物姿にまんざらでもない。神社では巫女の十文字かほともう一人の巫女姿の女の子がいた。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6141c1b2-b1fb-4a02-9ee2-e7b63fcdacec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd22bc68-774f-46d0-bc91-e79c05f7749d', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 21, '100036889', '手作りチョコレート事件', '鏑矢中学時代、里志にバレンタインチョコレートを受け取ってもらえなかった摩耶花。今年こそはチョコをちゃんと渡して里志の気持ちを確認したい摩耶花はえるに相談を持ちかける。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38bafc6d-6c75-4a42-a314-64ffa09a33ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1bcba891-eda8-4226-8703-273aaf06d666', 'fa7fa4a3-28d2-4ea6-9971-61fab756cd6d', 22, '100036890', '遠まわりする雛', '【シーズン1 最終話】えるに「生き雛祭り」の「傘持ち」役を頼まれた奉太郎。祭りの会場に行ってみると…、そこは戦場さながらの様子。男衆の気迫に圧倒される奉太郎。', '2019/07/18 00:00:00', 1541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e88af4a-f6e9-4bca-8fa5-0698aba8e085.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3aac1419-31f2-4f5c-97fb-e14e3c01cf52', '不器用な先輩。', '', 'hulu', 'my-awkward-senpai', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9e351a5-e096-4f73-9cab-27172f7fefcb.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 185575, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0d5d9302-e4b7-4a8a-a19c-f78424476dfa', '3aac1419-31f2-4f5c-97fb-e14e3c01cf52', 'hulu-my-awkward-senpai-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc1da201-6b7f-4868-aacf-74f9615dcc30.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e2636bd-28d8-414a-bfb0-a3234e4c0684', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 1, '100239155', 'ウチが教育係!?', '宣伝部の鉄輪梓は、社内からクールで仕事が出来ると評判だが、仕事に対してストイックが故に厳しくて怖がられている。そんな鉄輪は、部長からの頼みで期待の新人･亀川侑の教育係を任されることに。コミュニケーション下手な鉄輪は不安でいっぱいだが、決意の表情を浮かべるのであった。', '2025/10/06 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc1da201-6b7f-4868-aacf-74f9615dcc30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a68b65e9-10ab-47dd-9c28-078208fd7067', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 2, '100240680', '後輩をランチに誘いたいっちゃ!', 'とあるゲームのコラボカフェを企画している鉄輪と亀川。亀川と打ち解けたい鉄輪は、ランチに誘おうとするがなかなか誘うタイミングが掴めない。話しかけられないでいると、他の社員に先を越されてしまいショックを受ける鉄輪だったが…', '2025/10/13 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c10a9d77-7c70-4460-8e05-384110d3fd62.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4dda647-321a-4b04-b3a2-c3197b19feca', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 3, '100240873', '飲み会幹事をサポートせんと!', '部長に飲み会の幹事と結婚祝いのプレゼント選びを任された亀川。幹事を任された亀川を支えようと、鉄輪も人付き合いが苦手なりに頑張るが空回りしてしまう。そんな鉄輪を見て、亀川は鉄輪の厳しいながらも優しい一面を少しずつ理解していく。', '2025/10/20 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/46aeab14-5e82-4f6c-acdd-e5658adce016.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb6dfa80-9b44-4a2e-83c4-4be9a72e4ba0', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 4, '100241421', 'しんけんあつい! 沖縄出張', '鉄輪と亀川は沖縄出張でファッション雑誌広告の撮影に同行することに。撮影モデルと衣装を合わせないと失礼だ! という理由で水着を着てきた鉄輪の姿に戸惑う亀川。予定よりも早く撮影が終わり、観光を楽しむ2人だったが鉄輪の手違いでホテルを1部屋分しか予約出来ておらず…', '2025/10/27 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4c3ce4f-247e-4c8b-a483-feb273b047ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2922c7cb-84ee-4356-849b-be40c0763b69', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 5, '100242640', 'ぜんぶ台風のせいっちゃ', '台風接近中のある日、鉄輪と亀川はサンプル品を取引先へ届ける仕事があった。天候が崩れる前に終わらせようと、鉄輪たちは気合いを入れて仕事に取り掛かる。しかし、会社を出る頃には、雨風は本格的になっていき――。', '2025/11/03 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28f54f93-669e-47c6-a20d-37c71bc22420.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4633d48c-015b-4df3-b185-005dc267eb35', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 6, '100243545', '花火大会っち、浴衣やろね', '鉄輪は亀川を飲みに誘おうと決意するが、彼が同期の堀田と楽しげに話す様子を見かけ心が揺れる。亀川と堀田は花火大会の話題で盛り上がっており、飲みに誘うのを諦め落ち込む鉄輪。しかし、思わぬアクシデントにより鉄輪も花火大会に参加することに…?', '2025/11/10 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a0a3ffb-d024-4beb-9959-c32dc9b7d600.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05565d44-6a72-41b0-80be-6a42c457504e', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 7, '100244924', 'お母さんが来るっち!', '鉄輪とのやり取りに振り回されながらも、鉄輪の素顔を少しずつ知っていく亀川。そんな中、鉄輪に母から突然の電話が。いま付き合っている人がいるか、という質問に焦った鉄輪は思わず“彼氏がいる”と見栄を張ってしまい、事態は意外な方向へ転がり始める。', '2025/11/17 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ddcc335-7df8-4ab3-92a9-828ebdf73e77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29c76b02-c2bb-4b30-9c9d-9d75596543ca', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 8, '100245609', 'ウチ、メイドになるけん!', 'アプリゲームとのコラボメイドカフェの準備を進める鉄輪と亀川。企画書段階から初めて任された亀川だが、開店初日に思わぬトラブルに直面してしまう。開店準備が進む中でメイドの人手不足に悩まされる亀川を鉄輪はサポートしようとするが…?', '2025/11/24 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/592e76e9-36b7-4ebe-9bae-2713b28a8547.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cce80b11-9451-4706-bca0-cc15da49554d', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 9, '100246082', 'なして、こげ気になるん?', 'デパートで、偶然出会った亀川に服を購入するのを手伝ってもらう鉄輪。亀川のおかげもあり楽しく買い物をして別れる二人。帰り際、亀川を呼ぶ女性の声が聞こえ振り返ると、そこには亀川と親しく腕を組む女性の姿が…', '2025/12/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3585cab2-5433-4628-99a1-245aa5384e7b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88759af1-7023-4da7-b267-8cd65d686e1a', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 10, '100246812', '後輩のお見舞い行くっちゃ', '体調不良でも出社しようとする亀川に対し、出社を止め休ませた鉄輪。亀川を心配する鉄輪を見かねた同僚たちは、お見舞いへ行くように勧める。緊張しながらも訪れた亀川の自宅で、思いがけず亀川の妹･有希と出会うが…', '2025/12/08 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aec87117-9c6b-4e9d-b430-22f398222648.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cf6687f-c4d7-417a-a2f4-a61f0d23fb34', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 11, '100247555', '誕生日、しんけんお祝いするけんね!', '鉄輪は来月に迫った亀川の誕生日をどう祝えばよいか悩んでいた。人生で初めて友達ができたという戸惑いと不安の中、同僚たちから月初にある会社の合同誕生日会のことを教わる。鉄輪は堀田や観海寺からの助言を受けながら、少しずつ亀川の誕生日を祝う準備を進めていく。', '2025/12/15 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea95159a-9f1d-4e17-9542-9c4a42d9df5b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71595b5a-dbbd-485e-9d07-4ca066964072', '0d5d9302-e4b7-4a8a-a19c-f78424476dfa', 12, '100248198', 'ウチ、しんけん考えたっちゃけど!?', '亀川は鉄輪への想いが友情以上であることを彼女に告白しようと決意し、真剣に向き合おうとする。しかし、思いがけない中断により話すタイミングを逃す亀川。後日、亀川と顔合わすと鉄輪はギクシャクしてしまい…', '2025/12/22 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6ba85fc-81da-4fcb-9f56-e137205b30a9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('33f59ab5-1073-4459-8a36-6f1209ce9cef', '不遇職【鑑定士】が実は最強だった～奈落で鍛えた最強の【神眼】で無双する～', '', 'hulu', 'even-given-the-worthless-appraiser-class-im-actually-the-strongest', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9efe642-afb9-4cac-a67a-ccbd585b395f.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 178548, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('395e7edf-d2c2-472b-9be3-fcdf54736122', '33f59ab5-1073-4459-8a36-6f1209ce9cef', 'hulu-even-given-the-worthless-appraiser-class-im-actually-the-strongest-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad25eba8-b128-4f7c-9c84-f7a9f727a94f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1fcfe78-963b-4df5-8b6c-b4c5e505c34f', '395e7edf-d2c2-472b-9be3-fcdf54736122', 1, '100212835', '鑑定士は不遇職', '鑑定士のアインはパーティの仲間であるゾイドとジョリーンとダンジョンを探索していた。ふたりはアインに重い荷物を背負わせた上、『ゴミ拾い』呼ばわりしている。不遇職の『鑑定士』である自分はそんな扱いを受けても仕方ないと諦めているのだった。そんな中、ヘル･ハウンドの群れに襲われるアイン達。ゾイドとジョリーンはアインを犠牲にして逃げてしまう。絶体絶命になるアイン!', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad25eba8-b128-4f7c-9c84-f7a9f727a94f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6961ee73-885c-4893-9151-e9c30075515a', '395e7edf-d2c2-472b-9be3-fcdf54736122', 2, '100213732', '精霊の目で超鑑定', 'パーティ仲間であるゾイドとジョリーンに裏切られた上、ヘル･ハウンドに襲われ、奈落へと落ちたアイン。そんなアインを助けてくれたのは、世界樹の精霊であるユーリとその守り手であるウルスラだった。ユーリの力で九死に一生を得るアイン。ある行動からアインに好意を持つユーリは、ウルスラに「アインに力を貸して欲しい」と頼むのだったが…。', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/420cb953-80f0-41d7-983c-27632720d787.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ca0518b-69df-4107-a11f-750f442f0b0a', '395e7edf-d2c2-472b-9be3-fcdf54736122', 3, '100214487', 'リベンジマッチ', 'ユーリからもらった『精霊の義眼』とウルスラの特訓のおかげで、S級モンスターを倒せるほどに成長したアイン。いよいよ地上を目指す彼に、ユーリは同行を願い出る。そこでウルスラはアインの義眼を『精霊神の義眼』に強化し、もう片方の目に『賢者の石』を入れる。これによりユーリはアインと共に行動することができ、ウルスラも彼と意識をリンクできるようになる。そしていざ出発となる時、アインはユーリにあることを問いかけるのだった。', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8d3e646-4f1c-4dce-82b4-6756b83ce26c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aac20411-70e5-4486-b0f3-796e92f18799', '395e7edf-d2c2-472b-9be3-fcdf54736122', 4, '100215231', '姉妹を探して', '地上に生還し、ユーリの姉妹を探す旅に出るアイン達は、銀鳳商会リーダーのジャスパーから教えてもらった隠しダンジョンへ向かう。そこには数々のトラップを用意して待ち構える、とある人物がいるのだった。その頃、偶然にも同じダンジョンの別エリアにはゾイドの姿があった。アインが生還したことで彼を見捨てて逃げたことが露見し、世間の風当たりが強くなったゾイドは、単身で難関ダンジョンに挑むのだが…!?', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eba96676-6e3b-42e9-b0d5-f17df966943e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('134a1f87-846e-451c-b651-258c9540a878', '395e7edf-d2c2-472b-9be3-fcdf54736122', 5, '100216466', 'べヒーモス討伐依頼', 'ユーリの姉妹であるピナと、その守り手である黒姫も仲間に加わった。そんな中、アインはジャスパーと共に王都の冒険者ギルドを訪ね、魔物を倒して得たレア素材の買い取りを依頼する。しかし鑑定士に魔物を倒せるはずがないと信じてもらえない。周囲の人々に疑われ、不遇職を見下す空気に辟易するアインだったが、そこへ現れたギルドマスターのミーガンはアインをジョブだけで判断せず、後日SSランク･ベヒーモスの討伐を彼に依頼するのだった', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/599a2552-4b69-4539-bec0-40389ec24977.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef6e32f9-8670-4b0e-be47-11ff7ed3ecf8', '395e7edf-d2c2-472b-9be3-fcdf54736122', 6, '100217568', 'VS. ゾイド', 'ベヒーモスを倒して世間の評価が高まるアインだが、本人はユーリに出会えた幸運と共に、不遇職の『鑑定士』である自身の本質について悩み始める。その頃、落ちぶれたゾイドの前に現れた謎の女は、自らを『精霊』と名乗り、彼のアインに対する憎悪を巧みに利用する――。街で買い物を楽しむユーリとピナの前に突如現れるモンスター。その正体はなんと、超常の力を手にしたゾイドで!?', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f3cfbe8d-dafc-4d03-973d-9ad99917a22e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('483f2f64-6a30-42c3-9015-792088c9af4b', '395e7edf-d2c2-472b-9be3-fcdf54736122', 7, '100218518', '禁書庫の少女', 'ゾイドをモンスター化させた謎の女･エキドナは、次に魔族国を訪ね、ファルコ男爵にアインの殺害を依頼する。一方アインは、ユーリの姉妹がいると思われる新たな『隠しダンジョン』の情報を求めて、王城の禁書庫に向かう。王族しか使うことのない王城の大図書館の中でも、特に国王と司書の両名から認められなければ中に入ることが出来ないと言われる禁書庫。扉をくぐり、そこへ足を踏み入れたアインは、ひとりの少女と出会うのだが……。', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0d27584-0ddf-4b7d-8788-4fdd4747f041.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba06bb1b-75ba-4782-be1d-c4df4eb523a7', '395e7edf-d2c2-472b-9be3-fcdf54736122', 8, '100219317', 'ニグンの陰', 'ユーリの姉妹捜しを続けるアイン達の元へ、冒険者ギルドのマスター･ミーガンが訪ねて来た。最近、ニグンという貴族が治めるレーシック領で『魔族』の目撃情報が頻繁にあるらしく、彼女はその退治をアインに依頼するのだった。困っている人々を想い、早速現地へ向かうアイン達。そこで彼らが目にしたのは、痩せた大地と疲れ切った領民の姿だった。しかも領民は、幼い少女を生贄として魔物に差し出そうとしていて…!?', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6724594a-6486-4c37-8700-f29d74e184a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4731a1a-7ad6-494a-bdfb-ce0677f24acb', '395e7edf-d2c2-472b-9be3-fcdf54736122', 9, '100220321', '決起', 'SSランクの古代種ヒュドラを倒したのも束の間、レーシック領に夥しい数の新たな魔物が迫り来る。その光景に絶望する領民達だったが、満身創痍になりながらも孤軍奮闘するアインの姿に触発され、彼らは立ち上がる勇気を取り戻すのだった。一方、歪んだ形で領地や領民を守ろうとする当代の若き領主･ニグンは、幼い頃に出会った鏡の中の『友達』の言葉を信じてやまない。人並外れた超常の力を持つアインこそが魔族だと、領民達に言い放つのだった!', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b24490a-3b56-4229-b8ee-cdc6b7c5b72a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e00185a4-13a6-46f0-b827-6c76f0b897a9', '395e7edf-d2c2-472b-9be3-fcdf54736122', 10, '100221353', 'ニグンの闇', '先代領主の父を誇りに、自分なりに領民を守ろうと努力してきたニグンだったが、魔族シャドウの下衆な企みによってその志をも踏みにじられ絶望してしまう。その隙をついてニグンの体を乗っ取ったシャドウが、領民達に新たな魔物を消しかける! 防戦一方で劣勢のアイン。しかもシャドウを倒すには、ニグンの体を傷つけなければならない…。それでも誰も見捨てたくないとあがくアインと、心の闇に閉じこもってしまったニグン。その後、それぞれがとった行動とは…!?', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb36007b-f6bf-484b-9f46-095ede490fcb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2866a7c6-b344-4fef-8515-e85101c45ae0', '395e7edf-d2c2-472b-9be3-fcdf54736122', 11, '100221970', '魔族イオアナ', 'アインの存在が噂になり始めた魔族国。そんな中余裕の笑顔を見せるエキドナは、五貴族筆頭魔族の公爵･イオアナにアイン討伐をけしかける。一方、アイン達の前に突如、ユーリの二番目の姉･クルシュが現れた。末っ子･メイの世界樹が魔族に狙われているらしく、単独行動スキルを使って助けを求めて来たのだ。アリスの千里眼でメイのいる隠しダンジョンの場所も判明し、彼らは早速救出に向かう。しかし、そこには新たな敵の影があり…!?', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b47e424-3802-4465-9743-895f02777280.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd30084c-b289-46ef-b9fd-84c13944dac2', '395e7edf-d2c2-472b-9be3-fcdf54736122', 12, '100222725', '幸せよ、永遠 (とわ) に', '【シーズン1 最終話】ユーリ達の一番下の妹･メイは幼く、アインを見た途端大泣き。そんな彼女をあやそうと、真面目なアインは彼女を抱えて世界一の「たかいたかーい」!? 傍らには、この後大災害に転じるのではないかと密かに気を揉むクルシュとピナの姿があるのだった…。五人の精霊姉妹が再会を喜び合う中、アインはユーリ達との出会いに思いを馳せる。自身の境遇だけでなく心も前向きに変わる事ができたと感謝し、これからも皆を守り抜きたいと、アインはウルスラに決意を伝えるのだった。', '2025/10/17 17:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45ccc7b3-aa89-4925-8397-569cdcc6eb28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d68ee76f-8416-4701-9687-b7b3aaac423b', '不滅のあなたへ', '', 'hulu', 'to-your-eternity', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fa6937a-6631-4d51-a500-b7d4adb80228.png?w=331&h=447&p=t', 'hulu', 2021, 1, 1, 'FINISHED', NULL, 114535, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 'd68ee76f-8416-4701-9687-b7b3aaac423b', 'hulu-to-your-eternity-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2237bd10-2cd3-44ea-b08a-ac78bab3bab7.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5aab9a52-13ee-4481-9bd5-03054c151f20', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 1, '100079674', '最後のひとり', '何者かが地上に投げ入れたひとつの球。“それ”は大地を転がり、石やコケ、けがを負い死んだ白いオオカミへと姿を変え、雪原をさまよっていた。やがて“それ”は、飼い主の少年が暮らす小さな家にたどりつく。集落でたったひとり、豊かな土地を求めて去った仲間を待ち続けていた少年は、オオカミとともに旅に出ることを決意する。', '2021/04/13 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2237bd10-2cd3-44ea-b08a-ac78bab3bab7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60bad127-73f3-4b2b-8832-0194163a1673', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 2, '100080094', 'おとなしくない少女', '少年に姿を変えた“それ”は、死と再生を繰り返しながら歩き続けた。森の大地ニナンナに到着するが、突然何者かに襲われてしまう。ニナンナでは「大人になってママになること」を夢見る少女マーチが、家族や友人とともに穏やかな暮らしを送っていた。ところがある日、隣国ヤノメの役人ハヤセが祈祷 (とう) 師ピオランとともに村に現れて…。', '2021/04/20 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39927132-8fa2-4e4c-83aa-320e61a16088.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4743d13d-9973-4bfe-95f3-146df1bd0109', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 3, '100080549', '小さな進化', '少女マーチは森で出会った不死身の少年を“フシ”と名付けた。少年の姿をしているものの、人間らしい意識は持たず、食事や会話もままならないフシに対して、マーチはまるで母親のように優しく接した。彼女とのふれあいを経て、フシの心に変化が起こっていく。儀式から逃げたマーチをあきらめられないハヤセは、その後を必死に追う。', '2021/04/27 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ab05ff63-d670-4d4f-aa4b-53104e789814.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccb3b268-2c7d-4bfa-831a-9bdc00fe6dac', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 4, '100081081', '大きな器', 'フシの不死身の能力に興味を持ったハヤセは、フシ、マーチ、パロナ、そして身分を明かしたピオランをヤノメ国へ連行する。華やかで活気にあふれたヤノメの街を楽しむフシたち。しかし、ハヤセが密かに進める恐ろしい企てにより、フシたちの自由が危うくなろうとしていた', '2021/05/04 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed5070d3-5c45-4726-996d-e91ae50f88e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c79497bd-c629-4a3f-b8b6-c03d4bfd133b', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 5, '100081531', '共にゆく人', '夜の闇にまぎれて監獄を出たフシたちは、馬車でヤノメ国から脱出しようとする。ニナンナの両親のもとに帰れることが嬉しいマーチは、フシに「一緒に大人になろう」と笑いかける。しかし、ハヤセ率いるヤノメの一団がフシたちの逃亡を許すはずはなく…。', '2021/05/11 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00d041aa-8bd3-4a31-816f-bee2aa0fb2ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('157f2ed2-d9e0-47fa-8c96-280d2ecd129a', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 6, '100082160', '私たちの目的', 'わずかな“人間らしさ”を獲得したフシは、ひとり旅立った。フシは森で老婆ピオランと再会し、少しずつ言葉や文字、人間としての生き方を教わっていく。ある夜、フシは森の中から現れた奇妙な触手に襲われる。そして、とうとう、“観察者”がその姿を現す…。', '2021/05/18 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f755481d-9e42-478e-90d1-24c331716142.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96bd4f62-5939-41b1-a6e0-8e3c486a545d', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 7, '100082883', '変わりたい少年', 'フシとピオランは、タクナハに到着。酒爺 (さけじい) の店で仮面の少年グーグーに出会う。3か月前のある出来事のために素顔を隠し、酒爺のもとで使用人として働いているグーグーは、謎めいた少年フシに、どこか親しみを感じる。', '2021/05/25 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5c52789-b457-4277-9dcc-a0bbdf632459.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd491cef-67f5-41f1-97fc-f135c4d9cd9d', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 8, '100083362', '怪物兄弟', 'フシ、グーグー、ピオラン、酒爺 (さけじい)、そこにお金持ちの一人娘リーンが加わり、一風変わった共同生活が続く。リーンに憧れるグーグーは、戸惑いつつも彼女との暮らしにほのかな期待を抱く。ところがある日、酒爺から自分の体の大きな秘密を知らされたグーグーは…。', '2021/06/01 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b7c3d8b-5f07-4c62-ba14-7866e89bbea8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97275222-7b74-4d8f-8849-795dd9d90874', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 9, '100083896', '深い記憶', '兄弟の絆を深めていくフシとグーグー。フシは、これまで出会った雪原の少年やオオカミのジョアン、マーチたちのことをグーグーに話す。グーグーも、フシに「死ぬこと」について教えながら、自分の過去を思い返す。それは、かつて兄とともにお金持ちの家で雇われていた頃、家族の意味に気付かされた時のこと…。', '2021/06/08 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1ae639ac-6bdd-461c-bcd2-0f046d0f6f80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f8bde5a-9021-4f46-9414-6147d67b3a79', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 10, '100084332', '新しい家族', '森の中に現れたのは謎の敵“ノッカー”だった。敵はマーチの器を奪いとり、植物のツルのような無数の触手を伸ばしてフシたちを追い詰める。フシとグーグーは互いを守りながら懸命に戦うが、絶体絶命のピンチに。グーグーはノッカーの弱みに気付き、自分にしかできない攻撃方法を思いつく。', '2021/06/15 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d4411279-22e8-4301-81f1-a10b3806c709.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52162e19-69c6-4e6f-a51d-b51155fdc937', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 11, '100084634', '過去からの贈り物', 'ノッカーとの戦いから4年の歳月が流れ、フシとグーグーはたくましい青年へと成長した。グーグーは生き別れた兄と再会。そしてリーンの屋敷で開かれる、16歳の誕生日パーティーに招かれる。親が決めた相手と結婚しなければならないリーンは、その胸中をフシに打ち明けるのだった。', '2021/06/22 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/954a2238-1a6a-4a87-afa6-6caff2556350.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12d9b2cd-d00b-434c-beaa-4ba49da76c1d', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 12, '100084986', '目覚め', 'グーグーとリーン。ついに二人の心が通い合おうとしたとき、屋敷にノッカーが現れた。華やかなパーティー会場を揺れが襲い、招待客たちは悲鳴をあげながら逃げまどう。フシはおびえる人々を外へと逃がし、グーグーとともにノッカーに挑む。そしてフシは、自分ではない、誰かの激しい痛みを感じる…。', '2021/06/29 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c2307ab-a25e-443b-9c8b-0a972ec3b613.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a20e00f7-f814-444e-ab4b-d55b8d3f24f2', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 13, '100086618', '高みへの意志', '酒爺 (さけじい) たちに別れを告げたフシは、タクナハの地をひとりさまよっていた。道すがら、観察者に自分の存在理由や生き残った意味を問いかけるが、満足な答えは返ってこない。やがてフシを追って、ある人が旅に合流する。そしてフシは、マーチの器と記憶がノッカーに奪われたことに気付かされて…。', '2021/07/13 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d90d0080-68dc-4b57-b437-661b69c7d0a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d5f14da9-e681-4e63-889c-9cb131f6941c', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 14, '100087031', '自由の島･ジャナンダ', 'スカイフィッシュ号の案内役、少女トナリに導かれジャナンダ島へやってきたフシ。そこは凶悪殺人犯たちを囚人として集めた島だった。囚人たちは望みをかなえるために、闘技場で殺しあうという。離れ離れになったピオランを救いたいフシは、闘技場で戦い続ける。', '2021/07/20 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed50bdfc-999f-435e-8727-3b1be3f2413a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62c5f01a-e09c-49c7-bfc8-ddd8d82a43f9', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 15, '100087262', 'トナリという名の少女', 'バーサーカーとの戦いの最中、ニナンナの少女パロナの姿に変身したフシ。その意味を悟り、ショックを受ける。トナリはそんなフシを仲間に引き入れようと、ピオラン救出への協力を申し出る。明るいがとらえどころのないトナリをフシはまだ信じきれずにいたが、再び闘技場での戦いに身を投じていく…。', '2021/07/27 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6daa9ecb-b8e6-4afa-a72f-c6063d1ffe8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('52f412a5-d736-422f-a6d7-ebb9e53e9287', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 16, '100087643', '子どもたちの夢', 'ノッカーとの戦いに辛くも勝利を収めたフシ。トナリやジャナンダ島民との共闘は、フシの心に変化をもたらした。その夜、フシは子どもたちと一緒に火を囲み、それぞれの夢を語りあう。トナリもまた、自分の過去に思いをはせる。そして次はいよいよ島からの脱出をかけた決勝戦。その戦いの場に現れたのは…。', '2021/08/03 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6033daa5-7fdb-44a5-a0b4-061d6889829a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('767b5df2-f65b-4adf-afb9-5f9ad2d75e88', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 17, '100088137', '先覚者', 'フシを倒し優勝したハヤセは、ジャナンダの島民たちに意外な提案をする。眠らせたフシを連行し、いよいよ我が物にしようと企むハヤセ。そこへ、フシを助け出そうとやってきたトナリとその仲間たち。無敵のハヤセに果敢にも挑む子どもたちだったが…。', '2021/08/10 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a35942a-a06a-4a99-93d7-67fa6b822ab8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef73b5ff-7326-493d-8724-87c308f551be', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 18, '100088891', '進み行くために', '囚われの身となったフシを救出するため、トナリはひとりジャナンダ島へ戻った。二人は再び島を脱出しようとするが、海が荒れたため洞窟で一夜を過ごす。トナリは思いを語り、二人は心を通わせる。翌朝、観察者によってノッカーの出現が知らされた。そしてジャナンダの街には、信じられない光景が広がり…。', '2021/08/17 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/401db376-2c0d-4726-9520-1fde2746d527.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38363379-52fa-420e-a201-ce828344c883', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 19, '100089272', 'さまよう殺意', 'フシは島民たちを守るため、次々と現れる死体に乗り移ったノッカーの集団と戦う。しかし仲間たちの命の火が次々と消えていく。大切な人を助けられない自分自身を呪うフシ。一方、トナリとサンデルの前にはハヤセが立ちふさがり、フシにある決断を迫る。', '2021/08/24 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2ab6c271-4dd8-49d8-b6cc-06d18a07ce1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78967e14-c608-425b-ab95-3f2e3025b341', 'c4cd5b88-0c06-44a8-bf05-6bd2d1eeef36', 20, '100089908', '残響', '【シーズン1 最終話】フシはトナリたちに別れを告げ、ピオランが待つゼダンの港へと戻る。しかし、ノッカーを引き寄せてしまう自分の存在は、ピオランに危険を与えてしまう。もう会わない方がいいのではないか。ピオランを案じてなかなか再会できずにいたフシだったが…。', '2021/08/31 12:00:00', 1496, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e45bd814-241c-4334-af6d-ba95bd8c357e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ece6a896-afb1-43c5-8adc-b0ea60cce67f', 'd68ee76f-8416-4701-9687-b7b3aaac423b', 'hulu-to-your-eternity-s2', 'シーズン2', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f68aa75a-80c0-4dae-a56b-106c2a7e4764.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('109c7584-0c48-4fe1-968d-7eeb69df75fd', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 1, '100127079', '転生する愛執', '老婆ピオランとの別れから40年。不死身のフシはたったひとり、孤独で退屈な島での日々を過ごしていた。「もう誰にも会わない」そう決めたはずのフシの前に、ヤノメ国の少女･ヒサメが現れる。彼女は言う。「私はハヤセの生まれ変わりなのだ」と……。再び動き出したノッカーの脅威から罪なき人々を救うため、フシはヒサメたち『守護団』と行動をともにすることにした。', '2022/10/24 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f68aa75a-80c0-4dae-a56b-106c2a7e4764.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00f99ab6-c4a3-4dcb-92d5-4c8d4a0c9f92', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 2, '100127867', '鼓動する遺言', '窮地のフシを救ったのは、かつての仲間･ジャナンダのトナリだった。トナリはフシに自分の素性を明かそうとはせず、ただ「これまで出会ってきた人の顔を見せてほしい」と願う。フシが変身できるのは、この世を去った人の姿だけ。誰かに変身するたびにその死を悟り悲しむフシを、トナリは静かに見守るのだった。一方、ノッカーとともに森に逃げ込んだヒサメは……。', '2022/10/31 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e98b44df-3b35-4ec2-9edf-2c9ba3d5951b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9776f23d-d3ff-45de-95a8-937f3f5e71bb', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 3, '100128363', '待ち望まれた者', '居場所を転々としながら仲間を探すフシのもとへ、守護団はたびたび現れた。ハヤセの6代目継承者･カハクが訪ねてきた時、街にはフシを異端とするベネット教が広まっていた。守護団に同行することを決めたフシは、訪れた村々で奇蹟を起こしながら旅を続ける。ところがある日、ウラリス王国のボンシェン王子に捕らえられ、カハクとともにウラリス城へと連行されてしまう。', '2022/11/07 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d2b7e90-a24e-4ec1-915f-5743b00b534f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99cf17e5-d7a4-4005-b8bf-539ae6f072de', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 4, '100128746', '視える青年', '「新しい世界を与えてやる」ボンシェン王子の言葉に、わずかな感動を覚えたフシ。フシは王子の妹のポコア、付き人のトドとも知り合う。だが、このままウラリスに留まるとノッカーが襲ってくるかもしれない。フシは再び旅に出ることを決めボンシェンに告げると、彼はフシの旅に付いていくと言い出した。不敵に微笑む王子の瞳には、どんな景色が見えているのか。彼は味方か、それとも……。', '2022/11/14 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b933fb4-3391-4e86-a88c-f89c7f125cea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b70fee1-067a-46ba-bd76-a06095b9cc54', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 5, '100129359', '聖者の遠征', 'ノッカーを倒しながら各地をめぐり、順調に支持者を集めていくフシたち一行。旅の途中で立ち寄ったイルサリタ国ウガ城で、フシは城主の娘･アンナを生き返らせてほしいと頼まれる。死んだ人間を蘇らせることはできない。フシは自分の能力の証明としてアンナの姿に変身し、その抜け殻だけを置いて城を後にした。追いかけようとしたボンシェン王子は、城で信じられない事態に直面する……。', '2022/11/21 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae80638f-f48a-4c3b-9181-01cac79d902b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('945744a0-3a07-45af-a2e2-5880bc735b60', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 6, '100130093', '異端の徒', '野営地の夜、カハクに求婚され戸惑うフシ。フシ自身の意思とは別に、パロナの体はカハクの抱擁に拒否反応を起こしてしまう。カハクは、かつて自分の先祖･ハヤセがパロナを殺めていたことを知り、自分の愚かさを恥じるのだった。フシたち一行は、次の目的地･エンタスで歓待を受ける。ところが、その街にはフシを悪魔と信じるベネット教の大教督･サイリーラが待ち構えていた……。', '2022/11/28 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57a0ef3d-53af-44c1-9215-b067de2108b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c89a1606-2d33-454a-8ce2-3892596a7856', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 7, '100130769', '罰とゆるし', '溶けた鉄に焼かれ、肉体の崩壊と再生を繰り返すフシ。一方その頃、ベネット教によって捕らえられたボンシェン王子とトドは、パンを盗んだ罪で同じ檻に入れられた少年･チャボの境遇を聞く。ベネット教の異端審問は何日も続き、3人は疲弊していく。大教督･サイリーラの目的は、フシを悪魔の使いだと認めさせることだった。フシを守るため、ボンシェンは大きな決断をする。', '2022/12/05 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c921fd9-7a6c-413f-8cf9-a83ffc41bd17.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10d92555-8b45-47ca-8261-f381dc65242e', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 8, '100131302', '夢の先', '大観衆が見守る中、死刑台のボンシェン王子めがけてギロチンの刃が落とされた。大教督･サイリーラは勝ち誇る。ボンシェン王子は死に、フシはベネット教によって異端と認定されたのだ。程なくして王子の死の知らせが各地へ届き、ウラリス王国は悲しみに包まれた。フシたちは再び旅立つことを決める。そして、カハクの左腕のノッカーが自らの目的を語り始めた……。', '2022/12/12 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e247b12e-a850-4eba-abc0-7b3884f3dd43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('772d5665-afe5-4847-9754-aec16513e197', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 9, '100131931', '拡がる意識', 'ノッカーの猛攻撃を受けたベネット教の総本山。フシは市民を逃がすために奮闘するが、戦闘は苛烈を極め、一度に多くの器を奪われてしまう。守れなかった人々の墓標を前に、フシは己の無力さを痛感するのだった。ノッカーから皆を守るためには、もっと強くならなければならない。さらなる成長を望むフシに、観察者が道を指し示す。', '2022/12/19 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/379194a2-b860-4e62-a762-fe4c88eea93b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa3a2a2f-17a1-4d30-b28f-6424b3362c4a', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 10, '100132555', '共鳴', 'ノッカーがソニア国の王都レンリルを襲撃するまであと1年。レンリルの王女･アルメに謁見したが、警戒され信頼を得ることができない。修行の合間に街へと出かけたフシは、見世物小屋で土器人の少女を助け、船で一緒に暮らし始めた。フシは言葉を話さない少女に「エコ」という名前を付ける。エコとの土器を介した会話にヒントを得たフシは、船と一体化し、自らの感覚野を広げていく。', '2022/12/26 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd888862-bd99-4c76-871c-026a6e77a1d8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1933761a-3022-4400-9334-f6579759301d', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 11, '100133881', '肉の価値', '船での修行を終えたフシは、王都レンリルに降り立つ。ノッカーは、この平和で美しい都市を襲うと予告した。フシは半年後に向けて、気を引き締める。その頃、ウラリス王国ではレンリルへの出兵準備が整わんとしていた。ついにフシのもとに新たな仲間が集う。カイ、ハイロ、メサール。三人に課せられた役割を知り、フシは思い悩む。', '2023/01/09 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/160b7b42-beb3-40b2-a4fb-96e8dcf03b63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e47d8d5-632f-4805-a944-1e522b5d03c3', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 12, '100134516', 'ベールが秘めるもの', '王都レンリルを守るには、すべての民の信頼を勝ち取る必要がある。市民兵に接触し、交流を深めるハイロ。ハイロはフシに、ベネット教の手で「悪魔つきの子」として育てられた過去を語る。一方、メサールは城に出入りし、王女アルメにゲームを持ちかける。新たな仲間たちの協力を得たフシは、素性を隠した「賢者」として着実に街を作り替えていく。', '2023/01/16 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c45601c-9930-4e07-b696-07b84f0df694.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a247caf-4032-427c-8fa4-fe927da1b75a', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 13, '100135119', '賢者の正体', 'メサールが王女アルメから手に入れたのは、王都レンリルの地下水路の地図。広大な水の道は、ノッカーの侵入経路になりうる。地下に鉄板を張り巡らし、地上の家々を作り替え、防壁を築く。昼夜問わず働くフシの身体には、徐々に疲労がたまっていく。さらに、「賢者」の正体がベネット教に封印されたはずの悪魔フシであることが、市民に露見してしまい……。', '2023/01/23 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f47b0020-3878-41aa-b5c2-695f0d1375b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c804f9c5-36f7-4c2d-ae48-f8a0dd62d1b2', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 14, '100135750', '再生の朝', 'ともに戦う。まっすぐなフシの決意が、市民に伝わった。王女アルメは、正体を明かしたフシを国王のもとへ案内する。やがて、ポコアたちウラリスの面々もレンリルに到着。ウラリス兵、レンリル兵の助けを借りて、王都防衛の準備は順調に進んだ。ノッカーとの決戦の日を前に、カイ、ハイロ、メサールは、運命の選択を迫られる。', '2023/01/30 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ecb304b-a460-4b88-a5f4-c556faeca064.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c8f50cf-b170-4beb-bcb5-aa2d7c764b36', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 15, '100136163', '摩耗する自我', '戦いの火ぶたは切られた。レンリルには決して入らせまいと、フシは強化した能力でノッカーを撃退。状況は優勢に思えたが、敵は見えない場所から凶悪な一手を仕掛けていた。戦いが長引くにつれ、フシの身体に限界が迫る。その傍らで、いつかの少女が目を覚ました。', '2023/02/06 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/049d539d-e754-49de-a671-f8320c72b219.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5f6632e-e279-4623-a5af-b8b4b01a126a', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 16, '100137001', '不滅の三戦士', '三人の死は、フシに強い怒りと深い悲しみをもたらした。目覚めたフシは、鬼神のごとき勢いでノッカーの群れを殲滅する。一人きりで戦況を覆そうともがくフシだったが、ノッカーの罠に囚われてしまう。絶体絶命の危機に現れたのは、復活した「駒」。不死身なのは、フシだけではなかった。', '2023/02/15 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c5b445b-2eba-409d-b5be-3e70ff49b3f7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de24000d-a044-40a1-a03a-a39f2e13f562', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 17, '100137865', '守りたいもの', 'フシだけが、生きる痛みから逃げられない。カハクはそれを「呪い」と言った。不死身の秘密を握るボンシェンを、カハクが追及する。フシの人間性を守りたい。二人の意見は同じようでいて、相容れることはない。それぞれの守るべきもののために、戦いは続く。混迷極まる戦場で、メサールは王女アルメを探していた。', '2023/02/22 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/59dc8add-2f72-41cf-adab-5a3ee919c725.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a3283b2-e876-4e6c-a6a1-979de31df582', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 18, '100138131', '不死身の死', 'ついに、フシが消えた。フシの器はすべてノッカーに奪われてしまった。夜の闇がレンリルを覆い、街にはノッカーの砲弾の音だけが響く。異変を察知し、フシを探すボンシェンの前に、二百年前の生贄の少女が現れる。不死身のフシは死んだのか。少女が示した場所で、待っていたのは……。', '2023/03/01 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89471368-dfcb-4f30-a9a2-f4b4a2a5a034.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a7e4a7c0-07dd-4265-a5da-cdd86ce12d22', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 19, '100139370', 'そして日の出へ', 'それははじめ、球だった。ただの球ではない。ありとあらゆるものの姿を写し取り、変化することができる。フシは、はじまりの姿に戻った。確信は無い。だが、希望は残されている。ボンシェンは、フシのために命をかけた。ノッカーとの決着をつけるため、不死身の仲間が立ち上がる。', '2023/03/08 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/65b184e1-6988-4726-8c3f-dc59975c5052.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40c2b028-e0f7-49ff-bbcf-73dccc0ab9e9', 'ece6a896-afb1-43c5-8adc-b0ea60cce67f', 20, '100140158', '時代の終わり', '【シーズン2 最終話】王都レンリルに夜明けが訪れた。恐ろしいノッカーは去り、市民たちは取り戻した平和に歓喜する。戦いの後始末を終え、ようやく訪れた休息のとき。仲間たちは口々に夢を語り合う。フシには新たな目標ができていた。やがて仲間たちは、それぞれの道を選択する。カハクもまた……。時の流れの果てに、待つものとは。', '2023/03/15 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4d98a9a-e424-4799-9ff4-9fbc483a47f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d992d6aa-9837-42cd-a6bd-da380085fd9a', 'd68ee76f-8416-4701-9687-b7b3aaac423b', 'hulu-to-your-eternity-s3', 'シーズン3', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e95155d-d775-451a-a5f5-3b78295688c1.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e313b4b1-617a-49cc-b9c2-b614cf8b4816', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 1, '100239659', '穏やかなる世', '世界中の地中に根を張りノッカーを滅ぼしたフシ。長い眠りから目を覚ますとそこは自動車が行き交いスマホで何でもできる平和な現代の世だった。フシは中学生のユーキと出会い、仮の住まいを得る。同じ街に暮らす少女ミズハは学業･スポーツ優秀である一方、母親との関係に悩んでいた。フシとミズハ、2人が出会う時、新たな物語が動き始める。', '2025/10/08 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e95155d-d775-451a-a5f5-3b78295688c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0cc635d7-e53d-441d-972f-906295f744eb', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 2, '100240572', 'こころのむすびめ', '現代のヤノメで新しい生活を始めたフシ。復活させたマーチやグーグー、ボンシェンらかつての仲間たちを呼び寄せ、ユーキの家でともに居候させてもらうことに。その頃、ミズハが忽然と姿を消してしまう。同級生のハンナもミズハに憧れるユーキも心配でならない。ミズハとの会話を振り返り、不安を募らせるハンナは……。', '2025/10/15 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/248b6048-6afb-43c2-93ff-da1a89ac8f68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5268b271-35da-4d64-964d-d2f49f9e6b08', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 3, '100240971', 'みずは', '行方不明のミズハを捜すハンナやユーキ、創芸部の仲間たち。しかし居所をつかんだのは、足をケガしたミズハの痛みを察知した、フシだった。隠れていた祖父の家で先祖の話を知ることとなったミズハ。心の内に、フシへの思いが静かに芽生える。しかし、突如として彼女に起こる悲劇。きっかけは、母から娘への贈り物だった。', '2025/10/22 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8fd9ff1b-ad1f-48df-b174-acde51a5e419.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c58df95-3059-4d89-8037-71503f608da0', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 4, '100241522', 'いなくなったひと', '無残に息絶えた母･イズミの姿に衝撃を受け、家を飛び出したミズハは、何があったのかまったく記憶がない。ミズハの孤独と不幸を感じたフシは、ハヤセ一族との因縁にとらわれることなく彼女に手を差し伸べる。しかし翌朝、驚くべき事実が……。何も知らないトナリたちはミズハの存在をどう受け止めるのか。', '2025/10/29 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1064ed2-1adf-4183-8485-72e68f144134.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89784c6d-a499-413f-9732-da99dba66108', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 5, '100242470', 'とどかぬことば', '死んだはずのイズミが、何事もなかったかのようにミズハの母として暮らしている。一体何者なのか、霊体となっているイズミ本人にもわからない。戸惑いの中、フシはトナリたちと学校に通うことに。ボンシェンに、ミズハを見守るよう言われたフシにとっては好都合だ。フシと距離を縮めようとするミズハは、次第にフシに対する自分の思いに気づいていく。', '2025/11/05 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/905a7205-1d75-4b79-955b-4a4be73f278d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('153b9be2-6eb6-4bd7-85b2-400ebe7863bc', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 6, '100243688', 'へいわのしょうめい', 'よみがえらせた仲間たちが安心して生きられるよう、この世は平和な楽園だと証明すると決めたフシ。まず、ハヤセやカハクの子孫･ミズハと、その家系に不安を覚えるトナリの距離を縮めるために、彼なりの工夫を凝らす。一方、同じ頃、ボンシェンが敵の手がかりを突き止めた。すべての謎を解くために、フシが探しにいくのは……。', '2025/11/12 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/620db61e-3b3d-4be8-a6bf-b08dbd0256a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9357616-0303-4b67-bbeb-fb87473282c0', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 7, '100244287', 'しゅうげき', '自室に籠もりゲームと漫画ばかりの毎日を送るひろとし。父親が年の離れた相手と結婚し、その一人娘･みもりが義理の妹となって、退屈な日々が一瞬、明るく変化する。しかしみもり自身は、家でも学校でも孤独だった。そんな彼女の体を理不尽に奪ったノッカー。人間の命を脅かすノッカーに、フシは再び立ち向かうことを覚悟するが、ユーキは反対する。', '2025/11/19 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccfaad9d-6f98-472f-8078-102560d1131e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21a6ce0e-2dae-46a8-ae2d-2a826e490027', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 8, '100245850', 'やっかいごと', 'みもりの体を奪ったノッカーをどうすれば倒せるのか、人の中に潜むノッカーはどうすれば見つかるのか。憤るフシは、少年サトルとして姿を現した観察者に、詰め寄ってしまう。そんな中、恋心を持つミズハの勢いに押されたフシは、初デート。街中で遠い昔の日々に思いをはせるうち、かつてともに生き、戦って失った仲間たちが懐かしくなって……。', '2025/11/26 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/805775ab-5be9-4aa2-b1c1-be5f51a7da58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11d948cd-762c-4458-b77c-e55735d4ff76', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 9, '100246273', 'こばむいのち', '引き裂かれたみもりの心と体。すぐにでもノッカーから体を取り返したいと奮起する義理の兄･ひろとしだが、霊体のみもりはそれを拒む。生き返りたくない理由が、母･みやびの存在にあることを気づいていたひろとしは、決死の覚悟でみもりに訴えかける。みもりの心を救えるのは、ひろとしか、ノッカーか……。', '2025/12/03 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99f1a9ec-8c4d-4609-aefb-c3b872eb4ebf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('26c5a39b-07ca-4989-b39a-f1951307c808', 'd992d6aa-9837-42cd-a6bd-da380085fd9a', 10, '100246703', 'ひとのふり', 'みもりノッカーを倒して楽園に送り返したのは、ミズハの同級生フウナに宿るノッカーだった。再びノッカーを全滅させるまでは家に帰らない、とフシはユーキに宣言する。フウナノッカーの企みを探るうち、ついにフシは因縁の相手との再会を果たす。守護団とノッカー、数百年に渡るその目的が明らかになるも、それが一層フシを悩ませる。', '2025/12/10 12:00:00', 1502, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/94a55a16-fce9-4fe4-809e-2fba71b67667.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('19b0035e-8123-40de-a8cc-d7fb46ecb9a8', '夫婦以上、恋人未満。', '', 'hulu', 'more-than-a-married-couple-but-not-lovers', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5418dd7-8945-40b6-bd02-e79e95ae0f63.jpg?w=331&h=447&p=t', 'hulu', 2022, 3, 1, 'FINISHED', NULL, 141949, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9ace6379-925d-4a80-ae59-877ecd94bc84', '19b0035e-8123-40de-a8cc-d7fb46ecb9a8', 'hulu-more-than-a-married-couple-but-not-lovers-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19b82f8a-ee28-4b3d-96cb-2d0809ee54ff.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18ec6b90-6f84-478e-9e53-2ecccbd83466', '9ace6379-925d-4a80-ae59-877ecd94bc84', 1, '100126001', '同居以上、同棲未満。', '薬院次郎はクラスでも地味な陰キャ高校生。恋人とは無縁の生活を送っていた。そんな中、疑似夫婦生活を送る「夫婦実習」が始まると、自分とは正反対でクラスの陽キャ美少女ギャル･渡辺星とペアを組むことに! 成績上位者はペア交換が出来るそうで、2人はお互いの想い人とペアを組むため、本気で疑似夫婦を演じることに。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19b82f8a-ee28-4b3d-96cb-2d0809ee54ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07700835-e359-402b-884e-8d2367a00c10', '9ace6379-925d-4a80-ae59-877ecd94bc84', 2, '100127077', '妄想以上、現実未満。', '雷が轟く中、星の提案で一緒にホラー映画を観ることになった次郎。二人で怖さを乗り越えてポイントを稼ぐ作戦だが、星はさらにポイントを稼ごうとペアのパジャマを用意していた。なぜか自分の部屋に行かず、その場で着替え始める星。次郎も背を向け、しぶしぶ着替えを始めるが…。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31c22190-c691-47da-88f4-532ea1cee6e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d57bd05-7563-43b5-b2a3-d489c4ec4a5c', '9ace6379-925d-4a80-ae59-877ecd94bc84', 3, '100127865', '破局以上、復縁未満。', '次郎のとあるひと言で、星が岬波に手作り弁当を渡す「ラブ弁当作戦」が始まった。半ば強引に協力させられる次郎だが、一途に弁当作りに励む星に感心し、力になろうと奮起する。ところが、当日になって緊張と不安で動けなくなってしまう星は次郎に…。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e609f9bf-f2f7-4f0f-89fb-aee19fb9ec5f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9ff3162-5aaf-4b54-99ab-526a565a37c7', '9ace6379-925d-4a80-ae59-877ecd94bc84', 4, '100128361', '勇者以上、主⼈公未満。', '星と次郎は詩織･岬波ペアのあるウワサを聞かされる。それは2人がAランクになってもペア替えしないというものだった。このまま2人は結ばれてしまうのか!? 詩織に「ずっと岬波の隣にいるのか」と切り出す次郎。一方、星は体育倉庫で岬波に遭遇。すると急に抱きしめられ…。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73863626-815a-4d30-841f-4956c3b5c988.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f37150eb-ea0f-4682-9ff0-e7f2dfcb45af', '9ace6379-925d-4a80-ae59-877ecd94bc84', 5, '100128743', '⿐⾎以上、キス未満。', '星は「最近次郎をよく目で追っている」とサチとナツミから弄られる。必死に否定する星だが…? 一方、めいに次郎のことを相談した詩織は「いきなりキスしろ」と、思い切ったアプローチをアドバイスされる。放課後、日直で2人きりになった次郎と詩織。会話が途切れた途端、詩織の脳裏にめいの言葉が浮かび…。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2533032-97ce-4521-b95d-4d943a8b1e35.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e010082-ec02-4244-b034-4c6c69b2a42c', '9ace6379-925d-4a80-ae59-877ecd94bc84', 6, '100129356', '童貞以上、処女未満。', '夫婦実習で過ごす中、次郎が名前呼びしてくれないことで、急に「薬院」呼びになってしまう星。鈍感な次郎へ不安が溜まっていく。そんな中で体育の授業中、詩織はサッカーボールが頭に当たり、保健室に運ばれてしまう。次郎はめいにお願いされ、保健室へ向かうのだが…。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e87783d-a4d2-4eaa-aaec-35b10f26915e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ace4999-89bb-4006-898c-eb827e9fd02f', '9ace6379-925d-4a80-ae59-877ecd94bc84', 7, '100130092', '花火以上、抱擁未満。', '次郎に対する詩織の態度を見て、詩織の想いを察するナツミとサチ。2人は星の想いを確認するが、星はどこか曖昧な態度…。ナツミとサチは戸惑う星に何か決定打を与えようと、岬波たち男子グループと花火大会への参加を計画する。星は次郎に浴衣の着付けを手伝ってもらい、気合いを入れてグループデートに臨むのだが…。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0846185b-4838-4588-b6ac-97074701ae83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3d3047d-e413-48c0-ae02-38106a50ad21', '9ace6379-925d-4a80-ae59-877ecd94bc84', 8, '100130766', '哀願以上、安心未満。', '花火大会で星に何があったのか――。次郎が涙の訳をお風呂で逡巡していると、いきなり怯えた星が現れ大騒ぎする。星のためにトイレに付き合ってあげたり、アイスを「あーん」してあげたり、二人の距離が縮まっていく。そんな中とあるペアの話題になり、星から「うちらも付き合ってみる?」と問われ…!?', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb3a52e0-e514-44ef-a3d1-9a0adb1d1b78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70ebcaf2-6bc3-43b0-94ea-f4ff55da690e', '9ace6379-925d-4a80-ae59-877ecd94bc84', 9, '100131299', '幼なじみ以上、本命未満。', '詩織、めい、賀茂と海辺のカフェでのお泊まりバイトが決まり、気合いが入る次郎。実習棟へ帰宅した彼を待っていたのは、際どい水着姿の星だった。星もナツミたちと海へ行くのだという。だが、次郎が詩織と一緒にバイトすると話すと、面白くない様子でのしかかってきて…!? 星に翻弄される次郎だが、さらに衝撃の事実が判明する!', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f22f0419-f10d-4a79-b175-e0a2f9247cd1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12523017-5d19-4d47-9206-9dd01e36f7c7', '9ace6379-925d-4a80-ae59-877ecd94bc84', 10, '100131830', 'already以上、yet未満。', '詩織と海での時間を満喫し、デレデレの次郎に星は不満を募らせていく…。そんな中、買い出し担当になった星と次郎は二人で出掛けるが次郎が目を離した途端、星がナンパ男に絡まれてしまう。次郎は助け船を出そうと勇気を振り絞るが、しどろもどろになってしまい…。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc28980a-2bb5-4d63-9baa-e3d0fb274d7e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1af5f270-027c-47ed-adb1-35bf33ec0a8c', '9ace6379-925d-4a80-ae59-877ecd94bc84', 11, '100132551', '告白以上、失恋未満。', 'バイトの最終日前夜、肝試しをすることになった次郎たち。詩織はふいに触れた次郎の優しさに、うっかり自分の本当の想いを漏らしてしまう。素直に受け止められない次郎だったが、そんな彼に賀茂が囁く。「…力が欲しいか」と。詩織と肝試しのペアにしてやるというのだ。一方、星にも岬波と突然のチャンスが訪れる。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0faa855-8e00-4f18-b2c9-e62ef22532f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b5122b6-cfa0-486f-ab15-8a643094de36', '9ace6379-925d-4a80-ae59-877ecd94bc84', 12, '100133236', '以上、恋愛未満。', '【シーズン1 最終話】決意を新たにする星、ドキドキが止まらない詩織、そして“答え”を出せずにいる次郎――。海でのバイト以降、3人の想いは加速していた。そんな夏休みのある日、次郎は本屋で詩織に遭遇。突然雨が降り出し、急いで帰ろうとするが、詩織から「私の部屋に来ない?」と誘われ…。', '2025/12/26 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd769157-8e47-4254-8d14-339b64c79ba1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f35f87f4-2bbf-427e-a69d-0e827bf18a7b', '父は英雄、母は精霊、娘の私は転生者。', '', 'hulu', 'dad-is-a-hero-mom-is-a-spirit-im-a-reincarnator', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b64f0843-ede4-4b97-b680-1582b4eccff0.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 173692, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0ec023da-45bf-4d37-99c9-70562412aa44', 'f35f87f4-2bbf-427e-a69d-0e827bf18a7b', 'hulu-dad-is-a-hero-mom-is-a-spirit-im-a-reincarnator-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41b0e585-f3ef-4c4e-b7ac-30b1576c0cf9.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('681a580d-34ca-496f-b3f7-252e075cfa0d', '0ec023da-45bf-4d37-99c9-70562412aa44', 1, '100239185', '英雄の帰還', '精霊界で暮らす8歳の少女･エレンは転生者。物質を化合させたり、構造配列を好きに変えられるというチートスキルを持つ。そして、父･ロヴェルは国を救った伝説の英雄、母･オリジンは元始の母にして精霊の女王! 一家は平穏に暮らしていたが、ロヴェルとエレンが修行のために訪れた人間界では、ロヴェルの元婚約者のアギエルが横暴を繰り返していた。ロヴェルは、元護衛のアルベルトから話を聞き、実家に帰る事を決める。', '2025/10/11 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41b0e585-f3ef-4c4e-b7ac-30b1576c0cf9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ec447424-72ac-4964-b78a-f8b9446a5b7c', '0ec023da-45bf-4d37-99c9-70562412aa44', 2, '100240377', 'ヴァンクライフト家の問題', '10年ぶりに再会したロヴェルと弟サウヴェル。当主となっていたサウヴェルは、妻アギエルの身勝手な行動に振り回されながらも、ヴァンクライフト家の為に身を尽くしていた。サウヴェルを助ける為、アギエルの嘘を追求しようと動き出すロヴェルに、テンバール王国の王太子･ラヴィスエルはある条件を提示する。様子を見届けるエレンにはラヴィスエルは「腹黒」に見えて!? そして、二人の離婚調停が開廷する――。', '2025/10/18 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f30794f3-45e4-4246-860a-0a2ca75ff668.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bacd72a8-8660-46c1-8782-8a2ea99719b0', '0ec023da-45bf-4d37-99c9-70562412aa44', 3, '100240864', '国王ラヴィスエル', 'ロヴェルは、家族の情報が王家に流されたせいで、エレンが目を付けられた事に憤りを見せていた。しかし、開き直って妻と娘を堂々と紹介する事にする。エレンは祖母であるイザベラに会う事になり緊張するが、オリジンは「気まずくなれば二度と会わなければいい」とさっぱりした様子。まさに“かーさまらしい”様子に少し緊張がほぐれたエレンだったが……実際に会ってみると、ヴァンクライフト家の人々は大歓迎ムードで!?', '2025/10/25 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/878c6fd2-0f91-4394-a57b-321b6c51b6ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('850ecded-b36e-4e1a-a3d9-e0712678e65f', '0ec023da-45bf-4d37-99c9-70562412aa44', 4, '100241353', '女神ヴァールの断罪', 'エレンに「おじさまと仲直りするまで、とーさまとお話しません!」と言われてしまったロヴェルは、話をするためアルベルトを呼び出していた。家のことを思っての行動とは理解しつつも、娘を危険に晒されたことへの怒りは抑えきれない様子。対して、アルベルトは深く頭を下げ、ラヴィスエル殿下とはすでに関係を断ったと報告する――。一方、再婚を勧められたサウヴェルは、相手アリアと娘のラフィリアを家に招こうとしていた。', '2025/11/01 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f08e44c6-5a55-4392-9973-62e7c8e347e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcf9e679-9a63-4d24-817d-609a4ad01b0f', '0ec023da-45bf-4d37-99c9-70562412aa44', 5, '100242150', '王家と精霊の確執', '叔父サウヴェルとアリアの結婚式の最中、「女神ヴァールの断罪」が発動してしまった! エレンの機転で何とか場の雰囲気を持ち直すことはできたものの、腹黒さんことラヴィスエルは、この機を見逃さなかった。エレンの帰宅を知り安堵するロヴェルたちのもとへ、「黙っていてほしければ娘を差し出せ」と、暗に要求を突きつける。突っぱねることもできない状況に、ロヴェルは怒りをあらわにし、新婦アリアを厳しく問いただす――。', '2025/11/08 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d644f282-32a1-4fd4-9601-6e8adc254b86.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4ec7f23-4df7-4b12-97bb-304c75a76c5b', '0ec023da-45bf-4d37-99c9-70562412aa44', 6, '100243270', '精霊祭の意義', 'ついに、王家へ赴く日がやってきてしまった。腰が重いロヴェルとは対照的に、エレンはどこか好戦的な様子を見せる。王城でラヴィスエルは、父である前国王は、娘アギエルの件で責任を取って退位し、二度と城には戻らないだろうと二人に告げる。その言葉に、エレンは「妹の悪行を利用して父親を王座から引きずりおろすなんて、やはり腹黒い」と強い警戒心を抱く。そして彼女は、本題である結婚式での断罪について切り出す――。', '2025/11/15 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/06da57f4-dd51-4900-8d6d-b009d9de46b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb123142-bd41-4359-95a3-c25c695361e1', '0ec023da-45bf-4d37-99c9-70562412aa44', 7, '100244154', '鉱山の呪い', '王城での出来事からかなりの月日が流れた。以来、ガディエルは足しげくエレンを訪ねたが、一度も面会を果たせずにいた。ヴァンクライフトの屋敷の中で「いつになったら会えるのだろうか」と想うガディエル。そこへ偶然ラフィリアが現れ、不躾とも取れる物言いで贈り物をねだってしまう――。一方、エレンは領地内の鉱山へ挨拶に赴くため、おめかしをして出かけていく。見送ったヴァンは、寂しさから過去を思い返していた。', '2025/11/22 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0d0e9792-c01b-43b3-8129-ac570598711b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8749ec70-e603-4326-a4d3-116f64d2a9c2', '0ec023da-45bf-4d37-99c9-70562412aa44', 8, '100245973', 'ラフィリアの憂鬱', '転生前の知識を生かして、なんとか薬を完成させたエレン。しかし、その疲労から熱を出して倒れてしまう。エレンが無理をするのを止められなかったロヴェルは落ち込み、見守っていたオリジンは、誉めつつ、力の制御について練習するように促す。そして、薬が届けられた鉱山は、活気を取り戻していく。その頃ラフィリアは、貴族となった事で淑女になる教育を受けていた。しかし、思い描いていた家族での生活とは違っていて――。', '2025/11/29 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a93ba5e-e738-49ff-8255-ddbad2e0aa2c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e67e9c3-baa7-4eeb-948c-cfaee2685c17', '0ec023da-45bf-4d37-99c9-70562412aa44', 9, '100245974', '治療のお姫様', '巷では風邪の流行とともに、よく効く薬と「治療のお姫様」の噂が広がっていた。この件にヴァンクライフト家が関係していると知ったラヴィスエルは、探りを入れる事にする。“治療のお姫様”――もといエレンは、ロヴェルたちと、薬の供給不足、治療を求めて領地外から来る人々、これらに伴う治安悪化について話し合っていた。エレンを求める人が急増した事で、身に危険が及ぶと判断したロヴェルたちは、護衛を付ける事を決める。', '2025/12/06 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e4b6970-f780-4f8d-a819-e92b608653a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('123b7f40-d1e5-45c3-9879-b1d61aa1415b', '0ec023da-45bf-4d37-99c9-70562412aa44', 10, '100246735', '誘拐事件', 'ラフィリアが突然いなくなった。その原因が「ヴァンクライフト家のお嬢様と薬の確保」だったと知ったエレンは、自分と間違えて攫われたのだと自責の念に駆られる。そして、ガディエルの関与を示唆する手紙が見つかり、ヴァンの力を借りて怪しい人物達を探し出すと、そこにいたのはガディエル一行だった。サウヴェルは激昂して怒鳴り込むが、娘の姿はなく、見覚えのない手紙にガディエルは困惑する。――ラフィリアは一体どこへ。', '2025/12/13 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a3ebf6e-9662-46da-861a-e3eab199464b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11391da9-6f18-4382-9b2f-594250b842be', '0ec023da-45bf-4d37-99c9-70562412aa44', 11, '100247387', 'ラヴィスエルの思惑', 'ラフィリアは無事に助け出された。目を覚ましたラフィリアは、エレンに対して「あんたのせいよ!」と一方的に責め立てる。たしなめるサウヴェルに対し、彼女は、父や皆がエレンばかり気にして、自分を見てくれない気持ちを吐露する。娘の反抗的な態度の理由にやっと気づいたサウヴェルは、ロヴェルに少しだけ理解できたと感覚を共有する。次の日、エレン達はガディエル一行に対して、事件の真相と、ラヴィスエルの思惑を伝え――。', '2025/12/20 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c7cc4f9-0e43-4698-a94f-b8e52045eb77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f4bdf25-20db-4fd5-ae95-1b65dde4c33e', '0ec023da-45bf-4d37-99c9-70562412aa44', 12, '100247910', '人と精霊の間で', '【最終話】ラヴィスエルの思惑と、自分が手駒にされていた事実を知ったガディエルは、父のもとへ向かう。険しい表情のガディエルに対し、社会を知った顔を評価するラヴィスエル。怒りを抑えきれないガディエルだったが、ヴァンクライフト家を敵に回した代償に、王家の人間として向き合う覚悟を固める。一方エレンは、ラフィリアを誘拐した者たちの処遇を決めていた。王家へ報復する為、非情な選択を行う――。', '2025/12/27 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/362ff1a9-6f7b-4b84-84b6-105f11eb8484.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d887e1bc-6430-4e8f-b903-6d3b329d3f20', '負けヒロインが多すぎる！', '', 'hulu', 'too-many-losing-heroines', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6ceb839-01cb-4843-817e-432c3ef7c757.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 171457, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b14ceb90-c983-44c5-b85c-57d53b73b351', 'd887e1bc-6430-4e8f-b903-6d3b329d3f20', 'hulu-too-many-losing-heroines-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ee0f779-d07b-4281-b66a-88bfb213bcc5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1cce05b-41ea-43eb-8db0-4d6d0a4f4b6a', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 1, '100190751', '「プロ幼馴染八奈見杏菜の負けっぷり」', 'ライトノベル好きの達観系ぼっち･温水和彦は、ある日偶然クラスの人気女子･八奈見杏菜が幼馴染の男子生徒に振られている現場を目撃してしまい、その後立て続けに、陸上部の焼塩檸檬、文芸部の小鞠知花という負け感漂う女子たちと関わりを持つようになる。負けヒロイン――マケインたちになぜか絡まれる温水の謎の青春が、ここに幕を開ける!', '2024/07/16 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5ee0f779-d07b-4281-b66a-88bfb213bcc5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1a3c255-f8b0-4801-b68f-0e98d917f704', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 2, '100191572', '「約束された敗北を君に」', '檸檬に話があると誘われ体育倉庫で二人きりになってしまう温水。檸檬の相談事にアドバイスした矢先、灼熱の体育倉庫に閉じ込められてしまう。熱中症一歩手前のところを救出された二人は保健室で休むことに。差し入れを届けに来た幼馴染･綾野光希に頬を赤く染める檸檬。綾野とともに文芸部を訪れる檸檬だったが…。', '2024/07/23 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69af856b-f126-467b-83ad-ab6183936f52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a5733ed-fb7b-4b9a-b37e-a30157020e36', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 3, '100192520', '「戦う前から負けている」', '校舎の外れの水飲み場で友達がいない者同士、熾烈な水道水談義でしのぎを削る温水と小鞠。檸檬と八奈見も加わった文芸部は、部長の玉木と副部長の古都の発案で、生徒会への活動報告としてWEB小説の投稿を行うことになり、合宿に出かける。小説を執筆しつつ夏の波辺で高校生らしいひと時を楽しむ温水たちだったが、夜の花火でアクシデントが起こり予想外の事態に…。', '2024/07/30 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48b58ba5-5fc5-4e1c-92c6-c5b9188f0b9d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d2461e54-9400-49f9-80ff-6f150a919398', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 4, '100193512', '「負けヒロインを覗く時、負けヒロインもまたあなたを覗いているのだ」', '玉木に告白し、その場から走り去る小鞠。さらに玉木と古都の関係も拗れ、古都はひとり荷物をまとめてキャンプ場を出て行ってしまう。不穏な空気に現実逃避をしかける温水だったが、八奈見、檸檬と共にそれぞれの気持ちに寄り添う。怒涛の合宿が終わり、いつものように非常階段に向かう温水は、自分と八奈見が付き合っているという噂を耳にしてしまい…。', '2024/08/06 12:00:00', 1501, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5c2a02df-b05e-4a33-9f53-3aa502ef8977.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b101861-2010-44d0-a393-22e8a330d793', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 5, '100194149', '「朝雲千早は惑わせる」', '突然自宅に大量の素麺を持って訪れる八奈見と、兄に友人ができたことに過剰に反応する妹･佳樹に振り回され、慌ただしい日々を送る温水。そんなある日、八奈見に呼び出された喫茶店で、檸檬と綾野が二人で出かけているところを目撃する。二人の後を追う温水と八奈見だったが、そこに突然声をかけてきたのは綾野の交際相手の朝雲千早だった…', '2024/08/13 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aba11cd5-f8d7-4685-80db-446d479c582a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ba686a2-8546-4ba8-af33-464f183f962d', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 6, '100194977', '「振られたことのない者だけが、負けヒロインに石を投げなさい」', '千早と二人で一緒にいたところを目撃され、綾野に問い詰められる温水。誤解は解けたが、温水が八奈見を好きだという新たな誤解を生んでしまい、なぜか檸檬と八奈見も含めて五人で遊びに行くことに。プラネタリウムで綾野と千早を二人きりにしようと気を利かせたつもりの檸檬だったが、綾野との言い合いになってしまい…。', '2024/08/20 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/efc3cf40-251b-4dab-87f4-5405fcaea843.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6181e0f8-6781-473f-86c8-8f370f50dddf', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 7, '100195705', '「ハッピーエンドの向こう側」', '檸檬の祖母の家に泊まることになった文芸部員たち。月明りの下で、檸檬は綾野への想いを温水に打ち明ける。綾野、千早と向かい合うことを決意した檸檬は温水に付き添われ、綾野と直接話すために夜の校庭に向かう。お互いの出会いや中学時代の思い出など昔話に花を咲かせ、素直に気持ちを伝える檸檬と綾野。そして檸檬がとった行動とは…。', '2024/08/27 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b6d44e6-90c0-4e51-a1ad-2afe757ccc0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d35aaf0a-d550-42a7-880d-ec54c554a3b8', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 8, '100196297', '「おこまりでしたらコンサルに」', 'ツワブキ祭を控えたある日、温水は玉木と古都から、小鞠に次期部長を、温水に次期副部長をお願いしたいと伝えられる。温水たち1年生が主動となって文芸部の展示準備を行うことになり、八奈見の提案でテーマを決めるために街に取材に行くことになった温水、八奈見、小鞠。不在だった顧問も決まり、準備は順調に進んでいたが…。', '2024/09/03 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a79c37f3-a935-475b-b2e3-45ec41118cb3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c4377ec3-819f-4bbc-826f-18c2d7774a6f', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 9, '100197846', '「先生は天井の染みかなんかだと思って、続きをどうぞ」', '展示テーマが「食べる読書」に決まり、ツワブキ祭の準備を進める温水と小鞠は、参考資料を返すために立ち寄った図書館で、デート中の玉木と古都を目撃する。自分が玉木に告白したことで、三人で過ごせなくなってしまったことを寂しく思い、展示原稿を一人で準備することに拘る小鞠だったが…。', '2024/09/10 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68a6ac3f-18b8-44f1-921d-fd61fb9d10b6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56850360-e9b2-4861-bd13-a6c45a15d0df', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 10, '100198850', '「さようならには早すぎる」', 'なんとか文芸部の展示を完成させた温水たち。復帰した小鞠は恥ずかしがりながらも温水に感謝を伝える。展示が盛況な中、八奈見の計らいで温水と小鞠は二人で校内を回ることに。そしてツワブキ祭終了後、古都から小鞠への秘めたる罪悪感を聞かされる温水。一方、玉木と二人きりになった小鞠は…。', '2024/09/17 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7cfb0c5-e644-4343-9267-7f809161a6d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('887fa881-0147-4cc5-9a8f-b5fd3eae3b0e', 'b14ceb90-c983-44c5-b85c-57d53b73b351', 11, '100199433', '「結果責任についての話をしようか」', '部長会での報告の練習をする小鞠だが、人前に立つことへの緊張から中々上手く話すことができない。人に慣れるためにまずは動物からという八奈見の発案でのんほいパークを訪れる三人。ひたむきに練習する小鞠に温水は助け舟を出すが、言い合いになり小鞠は立ち去ってしまう。謝るタイミングが見つからないまま、とうとう部長会当日を迎えてしまい…。', '2024/09/24 12:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03f82ebd-f980-429c-a866-8307229529b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f4298ca7-ca07-4efa-a121-c3026590bdcf', '武装少女マキャヴェリズム', '', 'hulu', 'armed-girls-machiavellism', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50028837_series_art__338x600_armed_girls_machiavellism_c90ff0a19b189745c99c032fe945d4a2.jpg?w=331&h=447&p=t', 'hulu', 2017, 1, 1, 'FINISHED', NULL, 21851, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6342d7fb-f609-451e-ad68-8139b9c54947', 'f4298ca7-ca07-4efa-a121-c3026590bdcf', 'hulu-armed-girls-machiavellism-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cc1dad50-2adc-4f6e-b4c9-5cfc5b6a16ba.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af4c9538-312b-48ab-bade-85a7a5e539fc', '6342d7fb-f609-451e-ad68-8139b9c54947', 1, '60872917', '素晴らしき刃「鬼瓦輪」', '私立愛地共生学園。そこは女子が男子を「共生」の名の下に「矯正」し、厳しい支配体制を築き上げている、恐るべき学園だった。自由と平穏を愛する高校生･納村不道は、何も知らずに転校してきた初日、いきなり教室で武装した女子たちに取り囲まれる。納村に鋭い刀の切っ先を突きつけたのは、学園の武装女子たちの頂点である「天下五剣」が一人、鬼瓦輪。輪から「矯正」をかけた一対一での戦いを挑まれた納村だったが…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cc1dad50-2adc-4f6e-b4c9-5cfc5b6a16ba.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cfe1ca6-320b-4489-98d5-a4047488275f', '6342d7fb-f609-451e-ad68-8139b9c54947', 2, '60876536', '「貞淑寮」騒乱', '「矯正」をかけた決闘に勝利した上、不可抗力で輪のくちびるまでも奪ってしまった納村は、学園中の女子から恐怖と敵意を向けられるように。中でも、輪を慕う後輩の百舌鳥野のの、「天下五剣」に次ぐ実力を自負する蝶華･U･薔薇咲 (バラガサキ) は、納村に対する敵対心を熱く燃やしていた。しかし納村は、そんなことはどこ吹く風。外出許可証を手に入れるため、決闘の日から学校を休んで女子寮で寝込んでいる輪の元を訪ねて行くのだった。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3f1b3348-f9ae-44cb-9992-f6c50fe65f6e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3fe8b4f9-dd90-4195-96ed-b4da725c28ef', '6342d7fb-f609-451e-ad68-8139b9c54947', 3, '60879222', '麗しき刃「亀鶴城メアリ」', '女子寮での騒ぎを受けて、輪の管理下に置かれることになった納村。そんな彼を、亀鶴城メアリ―「天下五剣一のぶりっ子」が、次なる「矯正」のターゲットに定めた。納村の処遇を巡って、激突する輪とメアリ。輪にうながされてその場を離れた納村は、追ってきた蝶華をあしらう最中、「女帝」こと天羽斬々と遭遇する。自分の前に学園に転入し、「天下五剣」の輪とメアリを退け、圧倒的な実力を示した少女。その凶悪なたたずまいが、納村の心をざわつかせる。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b7224226-9a7b-40e4-ab88-cc76e2b4e23d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8cf5c4b9-ed3f-4010-9997-ca22ee0ce70f', '6342d7fb-f609-451e-ad68-8139b9c54947', 4, '60881050', '「ワラビンピック」開幕宣言!', '輪だけでなく、メアリからも監視されることになってしまった納村。とはいえ監視とは名ばかりで、傍から見れば三人はイチャイチャしているようにしか見えない。その様子が、ハワイから帰国した「天下五剣」の最年長者である花酒蕨の逆鱗に触れた。かくして納村、輪、メアリは、蕨の主催する血の祭典「第拾参回ワラビンピック」への参加を余儀なくされる。第一の種目は相撲。納村はもちろん、輪とメアリもまわしを締めることになって…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bf045be1-3d86-4292-9f29-11e37459dab6.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd4085a0-81f5-4896-a223-6f410c962542', '6342d7fb-f609-451e-ad68-8139b9c54947', 5, '60886562', '愛狂しき刃「花酒蕨」', '納村の奮闘により、ワラビンピックはあっけなく終了した。だがしかし、それで蕨が簡単に引き下がるわけもない。勝利に対する褒美である外出許可証への判子の授与式という建前で、納村を罠に満ちた校舎の中へと誘い込む。立ち塞がる精鋭「WRB34 (ワーラービー サーティーフォー)」。輪、メアリ、のの、蝶華の力を借りながら、納村は前へと進む。その道行きで、納村の前に不気味な少女が姿を見せる。天下五剣がひとり、その名は眠目さとり。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/e4de2c7a-d922-4db2-b561-efa59d59065a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('189bf1fb-8a62-45e9-9865-9be68f1bca48', '6342d7fb-f609-451e-ad68-8139b9c54947', 6, '100001080', 'ある「スキャンダル」の覚え書き', '納村にモテ期がやってきた。ワラビンピックでの大活躍により、学園中の女子から熱い視線を向けられるようになったのだ。それまでと同じ生活をしていても、ささいな一挙手一投足に黄色い声援が飛んでくる有様。納村本人は満更でもないのだが、輪とメアリはすこぶる面白くない。ところが、幸せな時間は長くは続かなかった。ある朝、いつものように輪とメアリの荷物チェックを受けた納村の胸元から、“とんでもないモノ”が…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3c92bd8-c8bd-48b3-a98e-ed2ebb99eeb3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b280441d-3fec-4e2b-882b-3a8f72667818', '6342d7fb-f609-451e-ad68-8139b9c54947', 7, '100001593', '妖しき刃「眠目さとり」', 'さとりの策略で、納村の評判はあっさりと地に堕ちた。輪とメアリにすら見放され、仕置き部屋に囚われてしまった彼を救ったのは、ワラビンピックで彼に一目置くようになった蕨だった。さとりの持つ無修正のスクープ写真さえ手に入れば、身の潔白を証明できる。そう考えた納村は、蕨とともにさとりを襲撃する。戦いの舞台は女子寮の大浴場。一糸まとわぬ姿のさとりを前に動揺する納村だったが、彼女はそんな甘い気持ちで対峙できる相手ではなく、それはまるで人間のフリをした“化け物”のようであった。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfbb7b49-54f2-4797-b147-cb26a640ec1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0d82703-4608-4233-97ab-eaf12fe363a0', '6342d7fb-f609-451e-ad68-8139b9c54947', 8, '100002002', '彼氏彼女オネエの「事情」', '目覚めると、納村は医務室にいた。さとりとの戦いのあと、蕨ともども気を失い、運び込まれたのだ。そんなこととは知りもしない輪とメアリは、仕置き部屋の納村のことが無性に気になってしまい、それぞれこっそりと向かおうとしていたところ、ばったりと鉢合わせてしまう。互いに本来の目的をごまかしておかしな対決が始まってしまった。一方、医務室の蕨に新たな問題が立ちはだかるのだった。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e66c2ace-e063-4379-97d0-0b9744735c08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('03c5e91f-cc75-450f-a188-62434c980c34', '6342d7fb-f609-451e-ad68-8139b9c54947', 9, '100002247', '「愛」が壊れた日', 'その日、納村の寝覚めは最悪だった。過去の忌々しい、血に彩られた記憶を切り取った、最低の悪夢を見たからだ。しかし、そんな憂鬱な気持ちを知ることもない面々によって、納村は起きて早々、男子寮で起こった不思議な騒動に巻き込まれる。男子寮の浴場に、奇妙な怪物があらわれたというのだ。一方、女子寮でも、本来なら消えるはずのない失せ物が多発するという、別のトラブルが発生していた。そして時を同じくして、女帝･天羽斬々の姿も見えなくなっていた…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c992560-bb2c-42fc-93dd-a88cb98f80e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f5d4db6-480b-49e7-ba54-0d2da428289a', '6342d7fb-f609-451e-ad68-8139b9c54947', 10, '100002675', '恐ろしき刃「因幡月夜」', '「天下五剣」の中でも桁違いの実力を誇る少女･因幡月夜。彼女が操る剣術、「薬丸自顕流」。その神速の居合抜きを目の当たりにし、納村は驚きを隠せない。繰り出される技の凄まじさと、腕前が自分よりも遥かに上だと気付いたからだ。だが、その衝撃すらも薄れるような事態が、遠く離れた校舎の屋上で展開されていた。伝わってくる戦いの音から、納村は異変を察知し、月夜を置いて屋上へと向かう。しかし、そこには既に女帝･天羽の姿は無かった…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84d97b67-bbc3-4d4c-9df5-7c32a9c62c55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d743d782-fcba-4953-ad43-01215bd84c9f', '6342d7fb-f609-451e-ad68-8139b9c54947', 11, '100003142', '胸に残るあの日の「弾丸」', '怒りに震える納村の雄叫び。応じる天羽の咆吼。ふたりの魂の声が、学園中に轟く。この学園で初めて出会ったときに抱いた納村の直感は正しかった。「女帝」天羽斬々は、彼がかつて友だと信じ、裏切られ、争い、深い憎しみを覚えた「アモウ」その人だったのだ。天羽もかつての記憶に思いを馳せる。呼び起こされた苦い記憶とともに、今、再戦の火蓋が切って落とされる。自動反撃と鉄壁の防御を突き抜け、納村の「魔弾」は、天羽に届くのか。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bdf98fa-cb1a-4ac1-9824-a5b3901270c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2753b64c-94a7-454a-b190-ab51933bce89', '6342d7fb-f609-451e-ad68-8139b9c54947', 12, '100003454', '少女達の「マキャヴェリズム」', '【シーズン1 最終話】転校以来、納村が輪たちと過ごした、賑やかで楽しい学園での日々。それは斬々にとっては、まるでその身を炎で灼かれるかのような、地獄の苦しみに心を苛まれた日々だった。戦いの最中、お互いの胸にさまざまな思いが去来する。しかし、いくら拳を交えたところで、ふたりの願いは決して重なりはしない。互いを理解すればするほど、心の距離は遠ざかる。そして、ついに訪れる決着のとき。降りしきる激しい雨の中、納村と斬々が最後に辿り着いたのは…。', '2025/12/26 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ecc0b1b-77cd-4bdb-a789-098db0bfe8ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6df5edd1-00d1-4bc2-8ea1-7fa3d19181ee', '武装錬金', '', 'hulu', 'buso-renkin-tv', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a24397f3-4f06-47e5-a07b-26234ec4fbb2.png?w=331&h=447&p=t', 'hulu', 2006, 3, 1, 'FINISHED', NULL, 1536, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e437f164-ba5d-496f-814b-a54f21346f96', '6df5edd1-00d1-4bc2-8ea1-7fa3d19181ee', 'hulu-buso-renkin-tv-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31031e97-9393-4f43-b860-75757e172255.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd170685-a617-4b3d-813a-31e135dba7a0', 'e437f164-ba5d-496f-814b-a54f21346f96', 1, '100221363', '新しい命', '少女を救おうとした少年、武藤カズキは化け物に胸を貫かれるが、翌朝、何事もなかったかのように目を覚ます。訝しむカズキは放課後、化け物に変化した教師の巳田に襲われる。その時、昨夜の少女からの電話が彼の携帯に…!', '2025/04/17 00:00:00', 1497, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31031e97-9393-4f43-b860-75757e172255.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4a7aa28-425f-46b6-ab33-4684172d02e6', 'e437f164-ba5d-496f-814b-a54f21346f96', 2, '100221364', 'ホムンクルスの正体', 'ホムンクルスを生み出した者の正体と目的を探ろうと、捜索を始めたカズキと斗貴子。二人は突如、空中から大鷲の翼を持つホムンクルスに急襲される。更に、斗貴子がホムンクルスの幼体に寄生されてしまい…。', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d31a8927-e728-4f1b-9b76-fe22e2d67f47.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d8fba29-b027-4db8-9e1b-570dd641b489', 'e437f164-ba5d-496f-814b-a54f21346f96', 3, '100221365', 'キミは少し強くなった', '斗貴子のホムンクルス化を防ぐ解毒剤を入手するため、パピヨンマスクの男を探すカズキと斗貴子。同時にカズキは、武装錬金を自在に操れるようになるための特訓にも励む。そんな二人を、ホムンクルスの蛙井が襲う。', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5c36b7b-0763-428a-9ef5-8833fbfa472f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afc021af-8a7a-493e-b99f-c180a3d1c34b', 'e437f164-ba5d-496f-814b-a54f21346f96', 4, '100221366', 'もう一つの新しい命', 'パピヨンマスクの男を探すカズキは、死に至る病を患っているという三年生、蝶野と出会う。彼が手にしていたのは解毒剤…。蝶野こそがホムンクルスの創造主! 彼は人間型ホムンクルスとなり、死を克服しようとしていた!!', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3cd10e56-9f69-42ae-8925-9342a0c52016.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d49c345-a95e-439b-878c-54dec5e42632', 'e437f164-ba5d-496f-814b-a54f21346f96', 5, '100221367', '守るべき人のために', 'ホムンクルスの鷲尾を前に、ホムンクルスの幼体に寄生され動きの鈍い斗貴子と、立ち向かっていくカズキ。斗貴子を守りたいというカズキと、自分を救ってくれた蝶野の望みを叶えさせたいという鷲尾、譲れない二つの想いが激突し、眩い閃光を生む!', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c78ab2d-341c-4167-9ae8-1ccd16d7f743.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fac87730-fa3d-43cf-8665-6b15471b0d76', 'e437f164-ba5d-496f-814b-a54f21346f96', 6, '100221368', '黒死の蝶', '斗貴子を救うため、解毒剤を求めるカズキ。ホムンクルス本体の完成を待つ蝶野攻爵。対峙した二人のもとへ攻爵の弟である次郎が現れ、ホムンクルス本体の入ったフラスコを破壊してしまう。が、攻爵の執念でついに、人間型ホムンクルスのパピヨンが誕生してしまった!', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/052965aa-a116-4184-a04a-cf5ba0ca07be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5be9732f-5564-496b-9b2c-2658640b91fe', 'e437f164-ba5d-496f-814b-a54f21346f96', 7, '100221369', 'もし君が偽善と疑うのなら', '斗貴子を救ったカズキは、キャプテンブラボーよりLXE･超常選民同盟の存在と目的を知らされ、錬金の戦士としてスカウトされる。皆を守りたいという気持ちと、それには自分は力不足ではないかという気持ちに揺れるカズキ。そこへL.X.E.からの刺客、人間型ホムンクルスの金城が現る!!', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37c64fe3-a04c-4908-80ae-bc43b0c2570b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c2fe7b11-c77c-41d6-9db0-28c4cd7b2d3f', 'e437f164-ba5d-496f-814b-a54f21346f96', 8, '100221370', '寄宿舎の夜', 'ブラボーは、カズキを錬金の戦士として鍛え上げるための特訓を開始した。一方、斗貴子は別の任務を指示される。それは、金城の使っていた核鉄を守ることだった。その夜、その核鉄を奪取せんとするホムンクルス陣内に操られた寄宿舎の生徒達が、一斉に斗貴子に襲いかかる!', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4e1c486-24e6-4d3c-8553-c42baa13562b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfc315cb-70f8-41a5-9f66-e735e1fe9d6d', 'e437f164-ba5d-496f-814b-a54f21346f96', 9, '100221371', '早坂姉弟', 'カズキは、生徒会長を務める早坂桜花と、剣道部の強豪である弟の秋水と知り合いになる。剣道の稽古を通じて近寄っていくカズキと秋水だったが…。早坂姉弟は学園に潜む錬金の戦士の捜索と抹殺を命じられたL.X.E.の信奉者だった。そんなある日、L.X.E.のホムンクルス二人が学園に乗り込んでくる。', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80f02e83-2948-4096-8c37-0ce3f0cb7bff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a867c2fe-ffd7-4fb3-90e0-26bf4fd383fd', 'e437f164-ba5d-496f-814b-a54f21346f96', 10, '100221372', '君と俺は相性がいい', '互いの正体を知り、驚くカズキと早坂姉弟。だが早坂姉弟に迷いはない。初手をカズキに譲った秋水は、日本刀の武装錬金“ソードサムライX”を発動させる。激しく激突する両者だったが、サムライXの煌めきは、確実にカズキの身体を切り刻んでいく。そしてついに秋水は渾身の逆胴を放つ!', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64073cfd-edfa-4dc4-95f2-8086cfa67979.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('675fc906-8e4f-446e-8529-283a0f0b147b', 'e437f164-ba5d-496f-814b-a54f21346f96', 11, '100221373', '死が二人を別つまで', '姉弟を殺そうとする斗貴子にカズキは、「救える命は全部救う」と訴え続ける。斗貴子がたじろいだ瞬間、秋水の刃が、カズキの身体を貫いた…! だが咄嗟に桜花が放った矢の能力により、カズキの傷は彼女へと移る。失われようとする命を前に、カズキは、斗貴子は、どうする?', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4799dec-52eb-4152-805f-9555159872a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dab7cc41-94f7-4265-b689-eac29b801531', 'e437f164-ba5d-496f-814b-a54f21346f96', 12, '100221374', 'カーニバル', 'L.X.E.のアジトをブラボー、カズキ、斗貴子が急襲する。だがそこにいたのはムーンフェイスのみ。彼は、ドクトルバタフライが生徒達を生贄にし、裏切りの戦士を復活させるため、銀成学園に向かったことを告げる。急ぎ学園に向かうカズキと斗貴子だったが…。', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a476de2-6fd1-40ac-b8b7-4ebf7c47c38d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e137290-335f-481e-800d-7b6a4af1a5db', 'e437f164-ba5d-496f-814b-a54f21346f96', 13, '100221375', '死の胎動', '友人達の声援を背に戦い続けるカズキの余りの強さに、斗貴子は疑問と不安を抱いていた。だが状況は、核鉄の力を手に入れたパピヨンが乱入し、ドクトルバタフライと戦い始めたこともあって、混戦に。そんな中、ついに裏切りの戦士が目覚めてしまう。', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6a3df1c2-6dca-4b3c-a215-8eb01ff47a1f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('665ef986-ed66-4f88-bb6c-2f4e0cc79ce0', 'e437f164-ba5d-496f-814b-a54f21346f96', 14, '100221376', 'キミは誰だ?', '百年の眠りから目覚めた裏切りの戦士、ヴィクター。彼はカズキと斗貴子を錬金の戦士と見て取ると、激しい憎悪を露わにし、二人を一蹴する。圧倒的な強さにランスを粉々に打ち砕かれるカズキを前に天を仰いで哭く斗貴子…。その時、ひび割れたカズキの核鉄が躍動を始めた…!', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8737d5b7-6740-4da3-b0e3-838c1fe209e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb455ceb-7369-440f-b582-ae8bd1578224', 'e437f164-ba5d-496f-814b-a54f21346f96', 15, '100221377', '中間の存在', 'ヴィクターと同じ容姿と化したカズキは、闘争本能に駆られ、狂戦士の如き戦いぶりを見せるが、斗貴子の悲痛な叫びに我を取り戻す。ヴィクターのこと、カズキのヴィクター化、そして黒い核鉄―ブラボーは本隊に戻り、これらの謎を解くための調査を決意する。', '2025/04/17 00:00:00', 1407, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3f2e6e33-f2d2-4d13-98e4-41e54e706e5c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b091acc1-e76d-46aa-8038-789e30f85672', 'e437f164-ba5d-496f-814b-a54f21346f96', 16, '100221378', '新たなる力', 'カズキはブラボーから驚くべき事実を聞かされていた。黒い核鉄を胸に埋め込まれたカズキは、六週間後にはヴィクターと同じく、存在するだけで死を撒き散らす、忌むべきモンスターと化すという。戸惑うカズキに錬金戦団から再殺命令が下された…!', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/074bff02-b827-4e93-8624-6e59cdb33c21.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b264e3a6-74e4-48a0-abd1-6850e3f49701', 'e437f164-ba5d-496f-814b-a54f21346f96', 17, '100221379', '夜が明けたら', '斗貴子は、彼女が黒い核鉄を手に入れた場所へ向かおうとするカズキに、「私は君から離れない、君と私は一心同体だ」と告げる。その言葉にショックを受けた剛太は、錬金戦団戦士長の火渡率いる再殺部隊と出会ってしまう。斗貴子を反逆者とみなし抹殺すると言う火渡に、剛太は戦いを挑む。', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2107205b-6ca4-4475-8989-58c1d4d471f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b0772bd-9945-447c-a406-14662814282a', 'e437f164-ba5d-496f-814b-a54f21346f96', 18, '100221380', '逃避行', 'ヴィクター化の謎を追い、黒い核鉄のあった場所、ニュートンアップル女学院に向かうカズキ、斗貴子、剛太。再殺部隊もまた学院を目指していたが、その前にパピヨンが立ち塞がる。ホムンクルス撃破数最多記録を持つ男、戦部とパピヨンの戦いはいかに…!', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66dfe488-c6c3-4b8b-8434-61f9c71d5cbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6765def-12ef-42bb-b2df-d550b5f4cc5d', 'e437f164-ba5d-496f-814b-a54f21346f96', 19, '100221381', '君さえ守れれば', 'カズキとはぐれた斗貴子と剛太を、根来が襲う。物体に自在に出入りし神出鬼没な攻撃を前に、剛太は防戦一方。さらに、根来は傷を負った斗貴子にも攻撃を仕掛けてくる。剛太は、斗貴子を守りたいという気持ちに後押しされ、反撃を開始する…。', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e19e536-38a7-494a-bdb9-d03238060213.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1880dbab-6f0b-4211-9103-431ebc7816f1', 'e437f164-ba5d-496f-814b-a54f21346f96', 20, '100221382', '想いと力を込めて', 'カズキとブラボーは、決着を付けるべく戦い始める。カズキを葬った後、自らも命を絶つと告げるブラボー。「俺はアンタに勝つ。勝ってアンタを死なせはしない!」カズキの想いを込めた一撃が眩い閃光と化し、ブラボーへと向かっていく。カズキの想いは、ブラボーに届くのか…!?', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b61fe40-db6b-45b4-8a96-a0f07bc84b6e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('991e2194-d1cd-48d4-b2b7-3c365556beb2', 'e437f164-ba5d-496f-814b-a54f21346f96', 21, '100221383', 'GONE INTO FLAME', '再殺の任を帯びた火渡の武装錬金“ブレイズオブグローリー”が炸裂。しかし、シルバースキンによってカズキ、斗貴子、剛太は救われた。身代わりとなったブラボーを失った怒りに駆られ、激昂するカズキ。その頃ヴィクターは、錬金戦団と交戦し、力の片鱗を見せつけていた…。', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dda38e1-d82c-48df-82c7-5c67125456fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc19d1c7-68de-4dc6-9684-011b734c000f', 'e437f164-ba5d-496f-814b-a54f21346f96', 22, '100221384', '決断を要す', '錬金戦団によるヴィクターへの総攻撃が始まった。火渡の率いる錬金の戦士達が挑むが、ヴィクターの進化は最終段階に達し、更に強大な力を振るい出す。一方ニュートンアップル女学院にたどり着いたカズキ達は、パピヨン、御前と合流していた。一行を迎えた者は…!', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1faacd03-f70a-4cbc-9334-0c5d3f380f82.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68bbb6cb-cf20-47c7-aa00-c8606bee4062', 'e437f164-ba5d-496f-814b-a54f21346f96', 23, '100221385', 'BOY MEETS BATTLE GIRL', '白い核鉄によって人間に戻れるのはヴィクターかカズキ、どちらか一人だけ…。カズキは究極の選択を突きつけられる。夏休みも終わりに近づいた登校日。カズキは斗貴子とともに、仲間達と楽しい時間を過ごしながらも、究極の選択の答えに一人葛藤する。', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b9b9c9f-017f-4969-beb4-6aeab28f69b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5e75031-5b97-48d5-9c43-70666b0486bd', 'e437f164-ba5d-496f-814b-a54f21346f96', 24, '100221386', 'キミが死ぬ時が私が死ぬ時', 'カズキは白い核鉄をヴィクターに使うことを決意する。それは新たな白い核鉄が完成の時までの、人々との別れを意味する。錬金戦団が激闘を繰り広げる戦場へと赴いたカズキと斗貴子は、ヴィクターに白い核鉄を打ち込んだが…!!!', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c4f73fb-3dd4-41bd-a32a-3fe25821391f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e80946d3-8718-44c2-8ea8-52edf2c82e87', 'e437f164-ba5d-496f-814b-a54f21346f96', 25, '100221387', '代わりなどいない', 'ヴィクターとの戦いの後…。世界には平和が戻り、何事もなかったかのように時が過ぎていく。だがそこにはカズキはいない。そんな中、斗貴子は無為の日々を過ごしていた。やがて彼女は、自分がカズキのために何をしてやれるかを考え続け、その答えをみつける。', '2025/04/17 00:00:00', 1437, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/514402c9-3e89-4e84-8bca-d1c789c5ad15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a6637ad-4830-40fd-95a6-f6ac46a61f14', 'e437f164-ba5d-496f-814b-a54f21346f96', 26, '100221388', 'ピリオド', '【最終話】パピヨンは、カズキを諦めず白い核鉄を精製していた。そして斗貴子に、「貴様は武藤カズキを諦められるのか」と尋ねる。斗貴子の頬を伝う涙。見上げた月に、山吹色の閃光が走る。カズキの生存を確信した一同は? そして、斗貴子とカズキは…。', '2025/04/17 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60430e67-99f9-4687-995a-39828c510835.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('07c9b4ea-4d1b-4863-bba3-65a1dec70b29', '舞妓さんちのまかないさん', '', 'hulu', 'maiko-san-chi-no-makanai-san-kiyo-in-kyoto-from-the-maiko-house', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/760d4606-73cd-4fbe-bdf7-44cffa251206.jpg?w=331&h=447&p=t', 'hulu', 2021, 0, 1, 'FINISHED', NULL, 117067, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5d51be6b-bb5e-40f0-add6-57d333805a68', '07c9b4ea-4d1b-4863-bba3-65a1dec70b29', 'hulu-maiko-san-chi-no-makanai-san-kiyo-in-kyoto-from-the-maiko-house-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d2f9469-7ca9-4f6b-b951-4307ad153586.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e630e8e-f40b-4810-a9e7-819a15a3eb88', '5d51be6b-bb5e-40f0-add6-57d333805a68', 1, '100095209', 'キヨちゃんとすーちゃん', '舞妓たちが共同生活をする屋形でキヨはまかないとして働いている。キヨは幼なじみのすみれが舞妓の付き人をしている様子を街で見かける。台所に現れたすみれは舞妓になるため毎日頑張っていると語るのだった。その夜、舞妓デビューが決まったすみれは大喜びでキヨに報告するが…。', '2021/11/02 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d2f9469-7ca9-4f6b-b951-4307ad153586.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0110d64f-3192-4ce9-ba50-48fd77ea73b5', '5d51be6b-bb5e-40f0-add6-57d333805a68', 2, '100095544', '特別な日のためのごはん', '屋形のおかあさんと踊りのお師匠さんは、舞妓デビューするすみれについて話をしていた。その場に居合わせたキヨは、すみれが百年に一人の逸材かもしれないと言われてうれしそうに目を輝かせる。一方、すみれは食事を後回しにして稽古を続けようとして先輩舞妓から心配されていた…。', '2021/11/09 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a3b3f2d-19df-4433-8417-9d904c3b549e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('14800a6a-6dff-4ad3-83a8-8ae8a7c30d12', '5d51be6b-bb5e-40f0-add6-57d333805a68', 3, '100095859', '秘策のごはん', '花街で働く男衆 (おとこし) のおにいさんは毎日稽古を頑張るすみれに期待していた。一方、おかあさんはすみれがやせてきたことを心配していた。キヨはすみれのために精のつく料理を考えるが、すれ違う日々が続いて食べてもらえない。そこでキヨはすみれが食べたくなる秘策のごはんを作ることにした。', '2021/11/16 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d1be35c-bf2f-4596-98ad-7e84cf4227d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f8b591c-3759-49d9-8792-65318683c421', '5d51be6b-bb5e-40f0-add6-57d333805a68', 4, '100096430', '眠れない夜のために', '初めて髪を結い上げることになったすみれは、舞妓たちから髪を結った初日は眠れないと聞かされる。舞妓は寝ている間に髷 (まげ) が崩れないように特別な枕を使うからだ。その夜、すみれは慣れない枕に悪戦苦闘する。どうしても眠れなくて夜中に台所へ行くと、そこではキヨが待っていて…。', '2021/11/23 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c581571-9326-4a24-8dfe-862d00766bb7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96e64b40-d50f-4094-8214-12015cc16c32', '5d51be6b-bb5e-40f0-add6-57d333805a68', 5, '100097002', 'ずっと決まっているもの', 'デビューが決まった舞妓にはお座敷で名乗る名前がつけられる。すみれの舞妓としての名前が「百 (もも) はな」に決まり、キヨは小学生の頃にすみれと名前について話したことを思い出す。その後もキヨはつい「すーちゃん」と呼んでしまい、「百はな」と呼ぶように注意されるが…。', '2021/11/30 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a596277-e239-402b-b4eb-aed6b38de20e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef3ed803-31b6-4c3b-836e-89e21e2fa1c1', '5d51be6b-bb5e-40f0-add6-57d333805a68', 6, '100097705', '同じ雪を見ている', '京都に雪が積もり、キヨは朝早くから一人で屋形の玄関先で雪かきをしていた。雪かきの音で目を覚ましたすみれはキヨを手伝おうとするが、スコップがなくてあきらめる。雪かきを眺めていたすみれは、キヨの後ろ姿を見ているうちに故郷の青森にいるような錯覚を覚え始める…。', '2021/12/07 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d559bce-28ba-4792-94b1-47faac4693d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41b2067b-5bd5-4774-95e4-b25715739300', '5d51be6b-bb5e-40f0-add6-57d333805a68', 7, '100098240', 'キヨちゃん上京す (前編)', '約1年前。京都への出発を間近に控えたキヨは、青森の実家でおばあちゃんと最後の時間を過ごしていた。そこへ幼なじみのすみれと健太が現れて昔話に花を咲かせる。おばあちゃんはそんな三人に郷土料理をごちそうする。その夜、おばあちゃんは夜行バスに乗るキヨたちを見送るが…。', '2021/12/14 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a9ef4f5-5004-4e91-b65b-1950d6037f5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('006c6cc5-a52b-40e6-b085-7664fb04584d', '5d51be6b-bb5e-40f0-add6-57d333805a68', 8, '100098672', 'キヨちゃん上京す (後編)', '半年前。京都で舞妓になるための修行をしていたキヨは、ぼーっとしていつも叱られていた。キヨはまかないさんと仲良くなるが、そのおばちゃんも腰を痛めて入院してしまう。やがてキヨは屋形のおかあさんから、舞妓に向いてないから青森へ帰るようにと言われてしまい…。', '2021/12/21 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b59ea683-1a33-4277-8478-da253bfb52e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b280ac99-c469-45da-aa73-a77273826019', '5d51be6b-bb5e-40f0-add6-57d333805a68', 9, '100099501', '仕込みさんの朝', '舞妓になる前の修行期間は「仕込み」と呼ばれ、舞妓の身の回りの世話や雑務をするのが仕事である。手伝いで仕込みの仕事をすることになったキヨは朝から掃除･洗濯と大忙しだった。その夜、キヨは料理をしながら、すみれと二人で仕込みをしていた当時のことを思い出すのだった。', '2021/12/28 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4c8ec0a-ebc5-4077-853c-3c2e6d06c1ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ed64a25-7760-448f-919c-c5b4ada98ee1', '5d51be6b-bb5e-40f0-add6-57d333805a68', 10, '100099502', '私の食べたいもの', 'キヨは晩ごはんの献立をどうするか悩んでいた。舞妓たちに何を食べたいかたずねるが、好物がバラバラで献立を決められない。その様子を見ていたすみれは好物のからあげが無性に食べたくなる。お座敷の帰り道で我慢できなくなったすみれは舞妓姿のままコンビニに入ろうとするが…。', '2022/01/04 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4dd418a5-67e4-48a2-95f8-ca6a93cef13a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ed094a7-b294-4cbc-b787-1d0f6378fb2d', '5d51be6b-bb5e-40f0-add6-57d333805a68', 11, '100100207', '見習いさんの夜', 'すみれの舞妓デビューが間近に迫ったある日。すみれは他の舞妓たちと、デビュー前の見習いが締める帯「半だらり」の話をしていた。その夜、キヨはすみれがお座敷が終わった後も帰って来ていないことを知る。夜の街を探し回ったキヨは、神社の前で半だらりの後ろ姿を見つけて…。', '2022/01/11 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b20829f-04a6-43e5-992c-0574d7b035da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb2d8600-5e65-4700-8712-834705941450', '5d51be6b-bb5e-40f0-add6-57d333805a68', 12, '100101478', '店出しのいちにち', 'ついにすみれの舞妓デビューとなる店出しの日がやって来た。すみれの支度が進む中、キヨも目の回るような忙しさを味わう。一息ついたキヨは、地元で人が大勢集まったときによく食べた郷土料理を思い出して台所で作り始める。そこへ支度の途中で抜け出してきたすみれがあらわれて…。', '2022/01/18 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ff4e471-cd97-47e3-a942-be08897dec63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9dd0f767-17d2-48a6-8bc9-667d8451f709', '5d51be6b-bb5e-40f0-add6-57d333805a68', 13, '100101933', 'キヨちゃんのいちにち', '朝。キヨは寝ている舞妓たちを起こさないように起床すると、朝食を作り、舞妓たちを送り出して買い物に向かう。昼。キヨは稽古から帰宅した舞妓のために昼食を作り、料理の仕込みを行い、お座敷へ向かう舞妓たちに夕食を出す。夜。キヨは掃除をして銭湯へ行き、夜の京都を散歩する。', '2022/01/25 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38231ebd-96c7-421b-af81-99054f465682.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('530564d0-99cb-4d62-8969-b002586e27ff', '5d51be6b-bb5e-40f0-add6-57d333805a68', 14, '100103511', 'おうちのカレー', 'まかないの仕事が一日休みになり、キヨはカレーを食べようと思い立つ。花街では、ある理由からカレーを食べるのは御法度とされているのだ。楽しみでそわそわするキヨを舞妓たちは不思議に思い、おかあさんはキヨに恋人がいるのではと疑う。休日になり、キヨは一人で外出して…。', '2022/02/08 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dce6f585-2f8f-4f4a-b74c-e5414a24c56a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2dd808a1-e2c9-48cd-b4c7-17da4999188e', '5d51be6b-bb5e-40f0-add6-57d333805a68', 15, '100104011', '雪の日の朝', '雪の日の朝。雪景色を眺めていたキヨは、地元ですみれ、健太と一緒に雪かきをしたことを思い出す。せっせと急いで雪かきするすみれ。雪をきっちり根こそぎすくう健太。こつこつと少しずつ進めるキヨ。三者三様で雪かきしたキヨたちに、おばあちゃんはある料理を作るのだった。', '2022/02/15 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98c0b1b9-a483-4c21-ad7e-a03147f0b632.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40e40e76-f2a2-4208-9efc-87581a1b271b', '5d51be6b-bb5e-40f0-add6-57d333805a68', 16, '100104697', 'おたよりを待つひと', '青森のおばあちゃんの家を訪ねた健太は、郵便受けに手紙が届いていることに気づく。手紙の差出人がキヨだと知った健太は、学生時代のキヨとすみれが授業中にこっそり手紙のやり取りをしていたことを思い出す。そのころから健太はキヨの文字を見るたびに気になることがあって…。', '2022/02/22 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5557c49-7721-447b-a9f1-856e749e3406.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('681044d2-1e4a-40f5-a2c3-78dae9ca3a9f', '5d51be6b-bb5e-40f0-add6-57d333805a68', 17, '100105069', '花街のクリスマス', '花街では、クリスマスになるとお客さんの手土産がケーキになることがよくある。舞妓たちはケーキを今年は何個食べたという話題で盛り上がり、まだ1個も食べていないすみれはショックを受ける。「うちにだけクリスマス来てへん…」と落ち込むすみれに、キヨが取った行動は…。', '2022/03/01 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19ca6864-2bc0-4636-bb5c-ff7de496c291.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dda9d671-996e-4a1b-897a-8ba751f8fdfb', '5d51be6b-bb5e-40f0-add6-57d333805a68', 18, '100105888', '花街の大みそか', '元旦に青森へ帰省する予定のキヨは、京都で大みそかの夜を過ごしていた。除夜の鐘が鳴るなか、キヨはすみれと一緒に風呂に入ったり、おかあさんからもらった福玉の中身を予想したりして一夜を過ごす。夜が明けて屋形を出発しようとするキヨとすみれを、意外な人物が待っていた。', '2022/03/08 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc643085-297a-4da9-94f8-609726eccb2d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93edca81-2d8b-44af-9e79-7d4edee2289f', '5d51be6b-bb5e-40f0-add6-57d333805a68', 19, '100106457', '帰郷1日目', '青森の実家に帰省したキヨは、おばあちゃんと一緒に正月を過ごしていた。そこへ健太とすみれが訪ねてきて、3人でお雑煮にかけるくるみだれを作りながらおしゃべりをする。すり鉢でくるみを潰しながら、キヨはすみれが花街で舞妓として活躍していることを誇らしく語るが…。', '2022/03/15 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93b14767-311e-4dff-8c48-87ac023172c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e51238f-fac7-4db1-86f5-c84378cd0487', '5d51be6b-bb5e-40f0-add6-57d333805a68', 20, '100107216', '初詣へ', 'キヨ、すみれ、健太の3人は初詣をするため神社に向かって雪道を歩いていた。青森で定番の菓子パンを食べながらにぎやかに進むキヨたち。神社で神様に願い事をしたあと、3人はおみくじを引く。くじの結果を見て落ち込むキヨだったが、すみれと健太はキヨのためにある行動に出て…。', '2022/03/22 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/294f9d84-39a2-4178-93b4-c382204ea009.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fdef0fa0-3b82-433f-942b-6be022d2aef5', '5d51be6b-bb5e-40f0-add6-57d333805a68', 21, '100107646', '再び京都へ', '正月が明けて、屋形に戻ってきた舞妓たちは地元のお土産を配りあっていた。屋形は正月休みのため、舞妓たちはおかあさんからもらったお小遣いで外食をすることになる。彼女たちが向かった先は、ふだんの舞妓姿では入ることができない憧れのスポット、ファストフード店だった。', '2022/03/29 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83d69acf-40e5-43f7-b00d-b4c4626a8d74.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e3ae881-7160-4d0e-bd48-3197765ab3e7', '5d51be6b-bb5e-40f0-add6-57d333805a68', 22, '100108324', '仕事始めの日', '1月7日は花街の「仕事始めの日」である。屋形では舞妓たちが慌ただしく仕事の準備を始めていた。すみれは髪を結い、おかあさんに正月の挨拶をして、ハレの日に着る正装「黒紋付」の着付けを行う。着付けを終えたすみれが台所へ向かうと大勢の舞妓たちでごった返していて…。', '2022/04/05 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5101e55f-7c76-454b-bdc3-1143e6012c10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8921a7e-ff83-407d-8f89-90cf4fae8adc', '5d51be6b-bb5e-40f0-add6-57d333805a68', 23, '100109232', '始業式', 'キヨは舞妓たちの部屋のテレビの電源がつけっぱなしになっていることに気づく。テレビには舞妓たちが出席する始業式の様子が映っていた。壇上では優秀な芸舞妓として百子が表彰を受けている。舞妓には姉妹縁組をする習わしがあり、百子はすみれの義姉に当たる存在だった。', '2022/04/12 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14298e66-6515-44f1-8fcb-161b1fd89aca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b2943ae-2122-4b30-b57f-ae66d5aec560', '5d51be6b-bb5e-40f0-add6-57d333805a68', 24, '100109796', '白いハト', '舞妓が正月につけるかんざしは「稲穂とハト」の形をしていて、このハトには「憧れの人に目を入れてもらうと願いがかなう」というジンクスがあった。誰に目を入れてもらったという話題で舞妓たちが盛り上がるなか、すみれは自分のハトにまだ目が入っていないことに気づいて…。', '2022/04/19 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e8d57be-8ae4-4fff-aa3a-e9abeced40d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad18eeb7-0e46-4784-a048-d6ce1998feda', '5d51be6b-bb5e-40f0-add6-57d333805a68', 25, '100110317', 'あったかいお昼', 'おかあさんが高級な牛肉を持って帰ってきた。さっそくキヨは牛肉を使った献立をあれこれと考えはじめる。一方、帰宅した舞妓たちは屋形の中が異様に寒いことに気づく。停電によって暖房器具が動かなくなっていたのだ。寒さに震える舞妓たちの前に、鍋を持ったキヨが現れて…。', '2022/04/26 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4d1b7a3-8b97-42eb-9604-f937befcecae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17247b8b-752f-44a3-bd9f-286d74311b04', '5d51be6b-bb5e-40f0-add6-57d333805a68', 26, '100110791', '風邪の日は…', 'おかあさんが熱を出して寝込んでしまった。キヨは「あったかいうどんを食べて休めばすぐに良くなる」と聞かされるが、京都の透き通ったおつゆのうどんの作り方を知らなかった。おかあさんに京都のうどんを食べさせてあげたいキヨは、作り方を聞き、食材を探しに出かけるが…。', '2022/05/03 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/371c60dc-8cbd-4adc-bb9c-97e5272aaa43.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8712732d-5ada-4280-b00f-dbc1fc0857e7', '5d51be6b-bb5e-40f0-add6-57d333805a68', 27, '100110792', 'ご挨拶回り', '少しでも多くお座敷を経験させてもらえるように、すみれは花街のお茶屋さんを挨拶して回る「お茶屋さん回り」をしていた。相手が留守のとき、すみれは一筆箋にメッセージを書いて渡していた。あるとき、すみれはお茶屋のおかあさんから思いがけない理由で感謝の言葉をかけられる。', '2022/05/10 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71750c41-a592-4610-beb4-406897103b47.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e6376e6-c0c0-4cc5-b586-0e3178902419', '5d51be6b-bb5e-40f0-add6-57d333805a68', 28, '100111672', 'もうひとがんばりの夜', '花街では節分の日に芸妓たちが仮装をするのが慣例になっている。屋形の舞妓たちはその手伝いをするため夜遅くまで小道具や衣装を作っていた。しかし夜が更けるにつれて、疲れた舞妓たちが盛り上がって部屋は大騒ぎになる。騒ぎを収めるため、すみれは台所へ向かうが…。', '2022/05/17 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/907ced90-5c3c-4d66-8b0f-37ae5e78c3ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc55129e-4112-403f-a80a-b855f6ea1d88', '5d51be6b-bb5e-40f0-add6-57d333805a68', 29, '100112240', '豆まき百景', '節分に豆まきをするため落花生を買ってきたキヨ。それを知った舞妓たちは大豆じゃないのかと疑問に思う。舞妓たちは落花生を投げ合って大騒ぎになり、おかあさんに叱られる。台所で落ちている落花生を拾い集めていたキヨは、幼い頃に青森の実家で行った節分を思い出すのだった。', '2022/05/24 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/455f82ad-7207-46b1-9ac1-8571899c6902.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28ed27ed-1a46-452c-b3bb-f45ac820be33', '5d51be6b-bb5e-40f0-add6-57d333805a68', 30, '100113147', 'お気張りの飲みもの', '節分の日。舞妓たちは神社で舞の奉納や豆まきを行うなど忙しい時間を送っていた。疲れて座り込んだまま立てなくなった舞妓たちのために、キヨはホットレモネードを作る。一方、すみれはテキパキ動いて屋形を出て行くが、キヨはすみれが忘れ物をしていることに気がついて…。', '2022/05/31 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1909adfd-72ff-4de9-8235-06c7ee0d74d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4f2f560c-e2be-43d6-9128-6413672171ab', '5d51be6b-bb5e-40f0-add6-57d333805a68', 31, '100113970', 'おねがいごはん', '高級レストランで百子と食事をすることになったすみれだが、メニューを見ても何が書いてあるのかよくわからない。結局百子と同じ物を食べたすみれは、帰宅後に「うちはなにを食べたんやろう…?」と悩む。翌朝、すみれは台所でキヨに食べたい料理をリクエストするのだった。', '2022/06/07 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7966a0d7-b21a-489c-badc-c6aca4116cb7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe15bece-5d1d-4b11-b714-40df19e27450', '5d51be6b-bb5e-40f0-add6-57d333805a68', 32, '100114324', '必死な妹と、その姉', '踊りの稽古が上手くいかず、すみれはもっと練習しなければと自分を戒める。屋形に戻ると、マラソンのテレビ中継にランナーとして走る百子が映っていた。何でもできる百子と自分を比べて落ち込むすみれ。だが百子の応援に向かったすみれは、そこで彼女の意外な一面を知るのだった。', '2022/06/14 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d547cac3-558e-4daa-97dc-c0d3658ab0b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24eddfeb-f5ae-4c22-bfd2-afeda3c1fb19', '5d51be6b-bb5e-40f0-add6-57d333805a68', 33, '100114950', 'キヨちゃんはいつも通り', '百子がキヨを訪ねて屋形にやって来た。すみれの幼なじみだというキヨに百子は興味津々。コーヒーをいれるキヨの姿をじっと観察して時間を過ごす。帰ろうとする百子をキヨはごはんに誘う。メニューが豚汁だと知った百子は快諾して、料理をするキヨを眺めるのだった。', '2022/06/21 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1cf7597a-a493-47ae-bb6a-24eb848928bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43aaf7ea-ce13-447b-9e80-4c0c89f9e471', '5d51be6b-bb5e-40f0-add6-57d333805a68', 34, '100115532', 'お休みギョウザ', '台所にあるにんにくを見て騒然となる舞妓たち。舞妓は香りの強い物を食べてはいけないため、にんにくを食べられるのは翌日が休みの者だけなのだ。翌日が休みのすみれは、にんにくたっぷりのギョウザを楽しみにしながらお座敷に出るが、そのせいで思いがけない言動をしてしまう。', '2022/06/28 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/326a87de-8af7-4479-90c3-55fdf745ce41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5206657-6023-4356-8359-eb22d5558ca6', '5d51be6b-bb5e-40f0-add6-57d333805a68', 35, '100116528', 'すーちゃんのお休みの日 (前編)', '休みの日にすみれは、洋服を着て髪を下ろした普通の女の子の格好でキヨと一緒に街へ出かける。誰にも注目されず、観光客からカメラを向けられることもない状況に、すみれは開放感を覚えるのだった。買い物をしたりアイスを食べたりして、普通の女の子らしく過ごすすみれだったが…。', '2022/07/05 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fece991-a533-4b7b-8c4a-843225efa647.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e50b4296-faa0-4774-9a7c-324dc015228c', '5d51be6b-bb5e-40f0-add6-57d333805a68', 36, '100117233', 'すーちゃんのお休みの日 (後編)', '休日をキヨと一緒に過ごしたすみれは、最後にキヨがいつも買い物をしているスーパーへ行くことにした。そこですみれはキヨをまねて買い物をする。屋形に戻ったすみれはキヨの仕事を手伝い、舞妓たちのためにごはんを作ることで、舞妓を送り出す側の気持ちを知るのだった。', '2022/07/12 12:00:00', 541, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17b260dc-8196-4b7d-8278-ddfca457925b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('0bddfb32-2507-4add-b012-b2b9fb76c0e0', '風が強く吹いている', '', 'hulu', 'kazetsuyo', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6ee3657-ff5a-4489-95e2-f51799f23004.jpg?w=331&h=447&p=t', 'hulu', 2018, 3, 1, 'FINISHED', NULL, 101903, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', '0bddfb32-2507-4add-b012-b2b9fb76c0e0', 'hulu-kazetsuyo-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0983c2bc-0b3b-4f5e-a4ed-1604aa4c13ec.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa5ece5c-3b19-4720-a816-81149626270f', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 1, '100025470', '10人目の男', '夜の街を駆け抜ける蔵原走。走を自転車で追う一人の男。男の名は清瀬灰二。追いつくなり灰二が走に問いかける。「なあ、走るの好きか!」走は灰二に導かれ、竹青荘という学生寮へ辿り着く。奇妙な住人たちとの邂逅。有無を言わせぬ灰二の言動。突然の展開に戸惑うばかりの走。灰二の魂胆を知るものはそこにはいない。同じ夜、住人総出で走の歓迎会が開かれる。そこで灰二の口から、壮大で無謀な、ある目論みが告げられる。それを聞いた走の反応は…。', '2018/10/05 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0983c2bc-0b3b-4f5e-a4ed-1604aa4c13ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee6c048e-2ad7-4988-bc42-ce89ab70ca82', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 2, '100025471', '鬼が来りて', '「竹青荘のみんなで箱根駅伝出場を目指す。」灰二の無謀な提案に強く反発する走。住人たちも陸上は全くの素人。誰も灰二の言葉を真に受けようとはしない。各々の大学生活を続けようとする住人たち。だがそこに灰二の影が迫り来る。灰二の不可解な圧に脅かされ、敢えなく半数が灰二の手に堕ちてしまう。一人、竹青荘から去ろうとした走は、街でニコチャン先輩と遭遇。一方、竹青荘では原因不明の風呂の故障が発生、全員で“地獄の”銭湯行きが決定して…。', '2018/10/12 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f30b5994-99d7-4189-b33c-72c2f7658dd2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fb2a8b7-8411-45ac-80bf-672f10e01341', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 3, '100025472', '花、一輪', '灰二との熱湯対決を引き分けで終えた走は、反発しながらも、住人たちとの早朝ジョギングに参加する。そこには、彼らを諦めさせるという走なりの狙いがあった。翌朝、数名の住人がジョギングをボイコットする。予想通りの変化を冷ややかに受け流し、一人で駆け出していく走。そんな走の前に、制服姿の少女が駆けてくる。彼女の名は勝田葉菜子。葉菜子の屈託のない言動に戸惑う走と住人たち。そのそばに、静かに微笑む灰二の姿があって…。', '2018/10/19 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef8f94c1-e016-44e8-b74c-cf45efbb0401.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('327428c0-4dfb-4f70-baa8-4f0ef120b592', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 4, '100025473', '消えない影', '「久しぶり…。」そう言って不敵に笑う榊浩介。走と榊は旧知の仲。思いがけない再会に動揺を隠せない走。走の胸の内には、高校時代に味わった、才能が故の深い孤独が渦巻いていた。影を振り切るように駆けていく走。その目の間に、“もう一人の走”が現れる。それは、灰二に出会う前の自暴自棄な自分だった。忌々しげに過去を見つめる走。やがて、自分に絶望しそうになったその時、優しく声をかける者が現れる。それは王子とその仲間たちで…。', '2018/10/26 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/757fd152-de31-43b6-8c14-fc27ce02eada.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a41513ab-4718-4963-94eb-1199d50efa6d', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 5, '100026741', '選ばれざる者たち', '東体大の榊に挑発されたことで、結果的に距離を縮めた走と竹青荘の住人たち。皆が決意も新たに盛り上がる中、キングが慣れないスーツ姿で帰って来る。一方、走は、早くも記録会への出場を目論む灰二に異を唱える。素人同然の住人たちに過酷な現実を突きつけてどうするのか。そう訴える走に、灰二が問い返す。走の疑問は晴れぬまま、灰二が本格的な練習を始めようとする。しかし、キングが就活を理由に参加を拒否して…。', '2018/11/02 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49048a23-d435-4d93-a5fe-1227977752b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8796e561-d3a8-45f4-93b5-80be82b5cd9f', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 6, '100026742', '裸の王様', 'エスカレートする灰二の要求に強く反発するキング。就活でも思うような成果は出ず、気遣ってくれる神童にもかえって心を閉ざしてしまう。ついには単独行動を取り始めるキング。他の住人たちも、強引なバイト禁止令には戸惑いを隠せずにいた。一方、走も、灰二への疑念を晴らすため、ニコチャンの元を訪れるが、確たる答えは見つけられずにいた。そんな中、神童があるアイデアを思いつき、住人たちに提案するのだが…。', '2018/11/09 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e69b5f5b-5729-41ef-9f8c-a63a7c0ee9ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b30699bb-e2ee-4742-82b6-598cab65c63b', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 7, '100027513', '頂きに牙を剥け', '初めての記録会。東体大を訪れた竹青荘の住人たちの前に、走の因縁の相手、榊浩介が現れる。執拗に走を挑発する榊。二人を止めようとする灰二。そこに、王者六道大学の絶対的エース、藤岡一真が割って入る。誰もがその風格に気圧される中、なぜか灰二だけが平然と藤岡と言葉を交わす。一方、現実を知らない住人たちのマイペースな言動に苛立ちを募らせる走。スタート直前、灰二に苦言を呈した走は、藤岡の背中を鋭く見据えて…。', '2018/11/16 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/562414de-e7be-4b1c-9f0b-952b9053a661.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f148ca4f-110b-4574-9f75-7b8283aacda5', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 8, '100027514', '危険人物', '記録会で惨敗を喫した竹青荘の住人たち。愚痴をこぼし、自らの力不足を慰める仲間の姿に、走が感情を爆発させる。そんな走をなだめるうちに、ニコチャンが、心の底に燻らせている陸上への想いを吐露する。走は、とことんまで追い込むべきだと進言する。翌朝、走とニコチャンは、灰二の指導を離れ、独断でトレーニングを行う。一方、王子は、練習で奪われてしまった漫画鑑賞の時間を取り戻すため、とある器具の調達を目論んでいて…。', '2018/11/23 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cdd8d26-d724-418a-832c-c7cd5deff675.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41cbfd3d-35a6-4c39-af2c-bfae17f7b2c6', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 9, '100027515', 'ふぞろいの選手たち', '王子に、次回の記録会の成績次第ではメンバーから抜けるよう提案する走。あの発言に効力はないと言う灰二に対し、王子は、僕でも記録は出せるのか? と直言する。さらに灰二にはもう一つの気がかりが。それは、用意した食事が一人分余っていること。灰二は、弁当を携え、食事を抜いた犯人の前に現れる。焦る走とは裏腹に、練習の成果が見え始めてムードを良くする竹青荘の住人たち。そんな彼らに、灰二が意外な指示を与えて…。', '2018/11/30 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccf96a5f-1a05-493c-ba9e-48e638824393.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('354ef728-4b5d-47b1-b9f8-eb222b60b790', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 10, '100028270', '僕たちの速度', '突然の灰二の昏倒。住人たちは灰二に支えられてきたことを痛感し、ニコチャンは、走と王子に和解を持ちかける。しかし、意固地な二人は溝を埋めることができない。翌日、神童が代理キャプテンの選出を提案する。年長たちがことごとく断った結果、走が代理を引き受けることになる。王子をどうにかしたい一心で、口うるさくついて回る走。その態度に反発を強める王子。そして、食事の用意もままならない住人たちに、救いの手を差し伸べる者が…。', '2018/12/07 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28ee1f02-29c5-47ea-8176-b14dbd2aa69d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('469fe77f-c514-4d52-ab51-c5a573111246', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 11, '100028271', 'こぼれる雫', '双子とムサが公認記録を獲得し、希望を掴んだかに見えた竹青荘の住人たち。しかしそこには、一ヶ月近く記録を出せず、焦り始めた神童とユキの姿もあった。灰二が二人を諭そうと語りかけるが、言葉だけでは彼らを救えそうにない。住人たちの行く手を阻むように、重たい雨が降り続く。それでも練習と学業の手を抜かない神童に、住人たちも心配を募らせ始める。一方、走と灰二は、陸上の専門誌に、王者･藤岡一真の姿を見つけて…。', '2018/12/14 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b574fbb5-9afd-474e-a0c2-f7434d886e5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9cc043d7-59f7-43b5-80ec-a8c491bec65a', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 12, '100029434', '夏のいたずら', '寛政大学の公認記録獲得を目指す戦いが本格的に始まる。すでに記録を持っているムサ、ジョータ、ジョージが葉菜子とともにレースを見守る中、走が先頭集団に混ざり、強豪留学生たちと渡り合う。一方、伸び悩んでいた神童とユキも、それぞれの特性を活かし、したたかに目標タイムを狙う。ラスト一周、走の脳裏をよぎる灰二の言葉。「走るの好きか!」。その瞬間なにかが開き、走は驚異的なタイムを叩き出す。レース後、そんな走に一人の記者が歩み寄り…。', '2019/01/11 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19bcde4b-5ef5-4c64-a9af-41fec7f86c3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7d59c41b-ffe1-4946-8cb7-2feacfaa41da', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 13, '100029435', 'そして走り出す', '夏合宿で訪れた白樺湖で、東体大と鉢合わせてしまった寛政大陸上部。走の過去の行為を告発するように、執拗に挑発を繰り返す榊。限界に達した走が掴みかかるも、仲間たちが間に入り事なきを得る。その後の練習は過酷を極めるが、走の心は高校時代の重い記憶に囚われたままだった。それは、選ばれた者たちをさらに追い詰める、残酷すぎる過去だった。破滅を選んだ自分を思い出し、苦悩する走。やがて夜。空には満天の星。一人佇む走のそばに灰二が現れて…。', '2019/01/18 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6b180c1f-f3ac-43df-b559-f486ca93d7c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fef5383-8c6c-44d4-b4f7-fb3732b1c2f8', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 14, '100029436', '一人じゃない', '走の過去を受け入れ、再び走り始めた寛政大陸上部。合宿では地獄の猛特訓が続き、都内に戻ってからは、後援会募集、資金調達、就職活動などに奔走する。いつしか素人の面影は薄れ、誰もが競技者の逞しさを漲らせていく。十人が、たった一度の儚い夏を駆け抜けていく。その眩い姿を見守る葉菜子にも、未来へと続く確かな道が見えてくる。たった一人の夢が、一人、また一人と繋がっていく。ニコチャンが、キングが公認記録に迫る。残すは一人。それは…。', '2019/01/25 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db748038-8eff-4ed4-9447-3cba23388e70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('de101a26-5eb5-4bec-b420-d90c82765411', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 15, '100030398', '運命の場所', '無事にメンバー全員が公認記録を獲得。予選会の出場資格を得て、灰二が監督の田崎に現状を報告する。予選を突破するにはまだまだ厳しい状況が続くが、周囲の期待は高まる一方だった。テレビの取材も舞い込み、浮き足立つメンバー。しかし、ユキだけがどこか浮かない顔をしている。そしてムサの視線の先には双子と葉菜子の仲睦まじい姿が。風雲急を告げる秋。いよいよ予選会の号砲が鳴る!', '2019/02/01 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/adfa6abe-97e2-4af0-aa34-b4c4e5f301dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c85d2f53-6361-4ca6-b300-38bec775248c', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 16, '100030399', '夢と現 (うつつ)', '目の前で他校の選手が転倒する。辛うじて衝突を回避した灰二だったが、右足に全体重をかけてしまう。騒然とする給水所前。不穏な情報に心が波立つ葉菜子。冷たい雨が、選手と見守る大観衆に容赦なく降り注ぐ。集団がばらけ、レースが街路へ移る頃、各校の選手たちが勝負を仕掛ける。状況を察知した灰二が仲間たちに合図を送る。それぞれの生き残りを賭けた孤独な戦い。そんな中、第1集団に大きな動きが。寛政大1年、蔵原走。その衝撃の追走が始まる!', '2019/02/08 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2226f3a6-f313-46af-807b-20fa3017b7e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2dcc7af0-d05d-4c9a-b7d1-1a7786e5954d', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 17, '100030400', '答え探して', '奇跡の予選突破を成し遂げた寛政大学陸上部。入部希望者が押しかけ、取材依頼も殺到する。それでも灰二は冷静に、本番へ集中しようとする。だが、灰二がコースの下見を提案した時、ジョータとジョージが突然反抗を見せる。「俺たち騙されてたんでしょ、ハイジさんに」。力の差は明らか。優勝なんて到底無理。なのに頂点を目指すなんて、俺たちそそのかされたんだ。そう詰め寄る双子。どうにか答えを探そうとする仲間たち。灰二が二人に返した言葉とは…。', '2019/02/15 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/debf0338-79d0-4dfe-bf22-dc6d329b3ca4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f2b1b5b-2a6e-4361-95ff-df83730af951', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 18, '100031252', 'そして朝', 'ムサと二人の帰り道、走は思いがけず、王者六道大の藤岡一真と遭遇する。周囲の心ない囁きを引きずる走に、藤岡は整然と、淀みなく答えを示してみせる。そして藤岡は、灰二との過去について語り始める。灰二が一人で背負ってきたものとは。藤岡に伝えた、精一杯の返事とは。走は藤岡の言葉から、灰二がかつて自分に話してくれた、「強さ」の意味を感じ取る。一方その頃灰二は、一人、医師の診察を受けていた。見据える灰二の瞳に、過酷な現実が映り込む…。', '2019/02/22 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5bcebc56-cb23-4c1d-b6e5-f4835463aaec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f0a241f-f316-4f7b-801f-838c650d2db2', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 19, '100031253', '解き放つ時', 'ついに東京箱根間往復大学駅伝競争の幕が上がる。灰二の賭けが当たり、1区は皆が探り合うスローペースの展開となる。そんな中、スタートの重責を担った王子は、他の選手の背後に位置を取り、体力の温存を目論む。それもまた、灰二が授けた頂点を取るための作戦だった。さらに灰二は、監督車の田崎に王子への伝言を託し、ムサの待つ鶴見中継所を目指す。ペースを上げる集団。必死に喰らいつく王子。その脳裏に去来するのは、いつかの灰二との会話だった…。', '2019/03/01 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e6a90a7-3310-4ff2-a4d9-d7262b03676d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76066161-bb3a-47ab-b419-45e3b924b8db', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 20, '100031959', '壊れても', '沿道に声援を送る葉菜子の姿。頭の中を駆け巡る記憶の欠片。ついに恋に気づいてしまったジョータが、走りを加速させ順位を上げる。兄から弟へ繋がれる襷、と同時に、葉菜子の想いも聞かされたジョージは、すっかり心ここに在らず。突然の葉菜子パニックに他の選手も浮き足立つ。レースを修正するため、走が田崎に伝言を託す。一方、中継所に辿り着いた神童に、灰二が電話で語りかける。長くて短い二人の時間。高熱を帯びた神童の体に、悲壮な決意が滲む…。', '2019/03/08 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/70795f0f-213c-4ff1-a863-9b363d51d8d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d6bf0dc-9a66-4e00-b959-f610c348ffb5', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 21, '100031960', 'さよなら、美しきこの世界', '仲間が決死の走りで繋いだ襷。その重さを噛み締めながら、ユキがレースの準備に臨む。そばに寄り添う神童の姿。溢れる不安や後悔を力に変え、運命のスタートを待つ。一方、横浜では、9区の走と10区の灰二がスタンバイ。しかし、灰二の姿が見あたらず、走の胸に不安がよぎる。そしてそれが的中するように、灰二の部屋からスポーツドクターが現れる。灰二に詰め寄る走。しかし灰二は、どこまでも穏やかな、いつもの灰二だった。午前8時。復路開幕!', '2019/03/15 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/119126e7-0853-4c39-b7c4-3e8d42e1a037.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44d8200f-9767-4372-bbab-af97a5d4dc71', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 22, '100031961', '寂しさを抱きしめろ', '悲壮なまでの榊の闘志。引きずられるようにペースを見失うキング。その脳裏を過るのは、灰二と交わしたある日の会話だった。言い出せない言葉。逃げ出せない現実。絡みつく迷いを解いてくれるのは、やはり灰二の言葉なのか。やがてキングの思いは、竹青荘で出会った、あの日の記憶にたどり着く。それは孤独な、だけど夢のような時間の始まりだった。小さな落胆、小さなプライド。全てを抱えて走り抜け。男たちの、自分を手に入れるための戦いが続く…!', '2019/03/22 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d449e433-1526-41cd-88a3-02fa3f82c6b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b577eae-c1e0-4742-95b2-fdbd12872508', 'e3cc81bb-edfc-48c3-9d4c-0130f60f9fa8', 23, '100031962', 'それは風の中に', '【最終話】未体験の感覚に戸惑う走。その速度は他の選手を圧倒する。一方、王者六道大のエース藤岡も、宣言通り区間記録を更新、チームを1位へ押し上げる。藤岡を迎える灰二。互いの道の先にどんな答えが待つのか。確かめ合うように言葉を交わす二人。灰二の静かな決意に王子が笑顔で背中を押す。やがて、走が衝撃の速度で中継地点に現れる。夢がそこにある。走から灰二へ。襷が二人を、チームを一つに繋いでゆく。寛政大学陸上競技部。彼らが辿り着いた頂とは。', '2019/03/29 00:00:00', 1365, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd5155af-1aef-4669-9da7-792601d04106.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d9498233-c250-4605-b940-992a23c27fb2', '風都探偵', '', 'hulu', 'fuuto-pi', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e59ea48-b4b8-4bef-baa2-7d5d02b9f783.png?w=331&h=447&p=t', 'hulu', 2022, 2, 1, 'FINISHED', NULL, 131912, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4aea23ea-bb53-4c50-b229-08c711c0f17a', '文豪ストレイドッグス', '', 'hulu', 'bungo-stray-dogs', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ed45e91-c8e3-4979-ba1e-028d45e2c3f3.jpg?w=331&h=447&p=t', 'hulu', 2016, 1, 1, 'FINISHED', NULL, 21311, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('04679667-4b2c-4384-9281-836dc17874e4', '4aea23ea-bb53-4c50-b229-08c711c0f17a', 'hulu-bungo-stray-dogs-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7c436d7c-6359-42fe-8f23-a61467b57f14.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('02bb0ba8-0ff0-43de-ba9c-49194a47685e', '04679667-4b2c-4384-9281-836dc17874e4', 1, '60795459', '人生万事塞翁が虎', '孤児院を追い出され、ヨコハマの街を彷徨っていた中島敦。このまま野垂れ死ぬか? いや、何をしても生き延びてやる――。盗っ人やむなしと決意した矢先、川を流されていく奇妙な男と遭遇する。どこか飄々とした自殺マニアの名は、太宰治。噂に聞く異能力集団「武装探偵社」の社員だった。太宰が同僚の国木田独歩とともに「人喰い虎」を探していると知った敦は震え上がる。その虎こそ、すべてを失った元凶だったのだ。だが、彼らは仕事を手伝うよう求め…。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7c436d7c-6359-42fe-8f23-a61467b57f14.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd3745f3-5ff2-4245-b168-37da638ba9bd', '04679667-4b2c-4384-9281-836dc17874e4', 2, '60795461', '或る爆弾', '「武装探偵社」に入社した敦だが「異能を制御できない自分では役に立たない」と、および腰であった。太宰は、そんな敦にもできる仕事を斡旋すると言って、どこかへ連れ出す。だがそこへ、国木田が知らせた緊急事態。探偵社に急行した敦たちが見たものは、か弱き事務員の少女を人質に「社長を出せ!」と声を荒げる爆弾魔の姿だった。探偵社への怨恨か? 唯一、犯人に顔が割れていない敦は、通りすがりの新聞配達員を装い必死に説得を試みる。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/67d8aac2-29f6-466e-af91-0f250013f895.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('564eb7c0-6903-4a0d-bbd0-e50ce58f2369', '04679667-4b2c-4384-9281-836dc17874e4', 3, '60795419', 'ヨコハマ ギャングスタア パラダヰス', '入社試験に合格し、晴れて武装探偵社の一員となった敦。探偵修行の一環だという先輩の前職当てゲームに挑戦するも、太宰の正解を知る者はなかった。そこへ、新たな仕事の依頼が――。スーツ姿の若い女は、会社のビルヂングの裏手にたむろする輩たちを追い払うため、彼らが密輸業者であるという証拠を掴んで欲しいと話す。谷崎とナオミと共に、ただ見張るだけの簡単な初仕事へと向かう敦だったが…。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9854dbfb-5456-4197-a376-3aeb9680c617.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fc98c67-dfd0-4ebc-8625-7154ea35751a', '04679667-4b2c-4384-9281-836dc17874e4', 4, '60795443', '運命論者の悲み', '太宰に助けられ、辛くも芥川の手から逃れられた敦だが、70億もの賞金首となった己のせいで仲間が巻き添えになったことを知り、自責の念にかられるのだった。国木田もまた「最悪の事態」を恐れ、いつになく動揺をあらわにする。お世話になった人たちに、これ以上迷惑を掛けられない――。探偵社から出て行くことを決意した敦は、偽の依頼人だったポートマフィアの樋口に電話を掛ける。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d55b9365-9166-4db1-91cc-b3bdd4bf7715.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('35f5f96b-f995-41ea-a833-747b1362779d', '04679667-4b2c-4384-9281-836dc17874e4', 5, '60795433', 'Murder on D Street', 'ポートマフィアの武闘派「黒蜥蜴」の襲撃を受けながらも、あっさり撃退してしまった武装探偵社。国木田が「最悪の事態」と恐れた通り、社員たちは散らかった事務所の後片付けに追われていた。そんな中、乱歩の仕事現場に付き添うことを命じられた敦。だが、電車の乗り方すら知らない世間知らずな「名探偵」を、少々いぶかしく思う。事件現場で待ち受けていた箕浦刑事と、その部下とされる女性の遺体を前に乱歩は「一分以内に解決できる」と豪語するが…。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/fa5c25a0-0935-4e7a-be9d-c6004f665a0f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2eea7192-b3da-4f5d-864f-ae173b6d87a9', '04679667-4b2c-4384-9281-836dc17874e4', 6, '60795448', '蒼の使徒', 'ヨコハマを訪れた旅行客の連続失踪事件が発生し、武装探偵社に被害者の居所を知らせるタレコミが寄せられる。国木田は、非合法のハッカーである田口六臓に情報源を探らせるが、見つかったのは、被害者の写真と「蒼の使徒」という謎の言葉のみであった。偶然にも11人の被害者のうち2人を目撃したという運転手兼情報屋のタクシーを呼び、敦たちは目的地へと向かう。太宰と国木田のコンビが相変わらず不毛なやりとりを繰り広げる中、着いたのは怪しげな廃病院で――。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/61e8fdaf-f447-49b0-97b7-fe676087474d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50b48b78-d89a-4528-a52a-5c24219e551b', '04679667-4b2c-4384-9281-836dc17874e4', 7, '60795422', '理想という病を愛す', '「蒼の使徒」からの大規模な市街地爆破予告。爆弾を解除せねば、武装探偵社は連続失踪事件に続き多数の死者を出し、同時に、さらなる醜聞の炎に包まれるであろう。そんな社の存続とプライドを掛けた戦いのさなか、太宰はといえば、先の廃病院から唯一救出の叶った佐々城信子にご執心の様子。大学で社会心理学を教えている信子は、今回の事件が「蒼き王」に関連しているのではないかと言う。それは、かつて国木田によって追い詰められた末に自爆したテロリストであった。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7792feef-e7a4-4f79-8289-bd959afa8e86.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32934d92-5fa7-4cc9-b0c8-cd336fa72fc0', '04679667-4b2c-4384-9281-836dc17874e4', 8, '60795449', '人を殺して死ねよとて', '太宰が行方不明になるが、武装探偵社の社員たちは「いつものこと」と気にも留めない。そんな中、敦は与謝野晶子の買い物に付き合うことになる。しかし、マフィアとは、いつどこで襲ってくるとも知れぬもの。「ただいまより、ささやかな物理学実験を行います」――。列車に鳴り響く謎のアナウンスが、乗客たちを恐怖に陥れた。卑劣なる声の主は、狂気の爆弾魔･梶井基次郎。敦は、車内に仕掛けられた爆弾を探して走りだす。そこへ、一人の少女があらわれ…。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/309fc213-d62f-4d69-b7a4-957cd6a68081.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fac1af64-a5ab-4995-bb3f-49b8a096ee0e', '04679667-4b2c-4384-9281-836dc17874e4', 9, '60795427', 'うつくしき人は寂として石像の如く', '異能力を利用され、暗殺者に仕立てられた少女･泉鏡花。黒幕を明かす代わりに、好物の高級湯豆腐を願う様はあどけない。その生い立ちを聞き、敦は一層の同情を寄せるのだった。だが、国木田は問う。彼女が背負うすべてを引き受ける覚悟があるのか、と。どうしても軍警に引き渡すことができないまま、敦は鏡花とヨコハマの街を「デート」する。その頃、行方不明の太宰はポートマフィアの監獄に繋がれていた。芥川は、裏切り者の「元上司」を罵る。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2942a1d8-1b01-4814-aada-c68d7e240b41.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8fe7eea3-7f61-4c61-b2ad-edb40b30e25e', '04679667-4b2c-4384-9281-836dc17874e4', 10, '60795432', '羅生門と虎', '太宰は、監獄にあらわれた「元相棒」中原中也と一戦を交える。中也が疑念を抱いた通り、太宰が容易く捕まったのは、敦に巨額の懸賞金を掛けた依頼主を探るためだった。しかし、すでに敦はポートマフィアの手中だ。自分に向けられた芥川の激しい憎悪を感じながら、密輸船で引き渡しの地へと運ばれていく敦。そんな敦を救おうと、鏡花が自らを犠牲として芥川に立ち向かう。駆けつけた国木田は、鏡花を残して逃げるよう言い聞かせるのだが…。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c18824af-f777-4ebc-a11b-eed7daf1dfeb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17e165b9-88cc-4868-b4cc-2bc68ce7a16f', '04679667-4b2c-4384-9281-836dc17874e4', 11, '60795430', '其の一「彼女には向かない職業」／其の二「有頂天探偵社」', '死の重傷を負い、意識不明のまま眠る芥川。敦の誘拐に失敗したばかりか、作戦の途中で壊滅させた組織の残党が復讐に動き出した今、“先輩”芥川を守れるのは樋口だけだった。「私は、この仕事に向いていない――。」 痛いほど思い知りながら、それでも彼女は己の信じる道を選ぶ。一方、武装探偵社では、敦が宮沢賢治の担当する事件現場へ同行していた。聞き込み調査を行う二人。敦は、持ち前の朗らかさで街の人たちと接する賢治に感心するが…。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a3529145-4583-4ebe-8dd3-d9705fe4ab95.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bc566fd9-82b2-48ae-924d-3aa6a71d761e', '04679667-4b2c-4384-9281-836dc17874e4', 12, '60795418', 'たえまなく過去へ押し戻されながら', '【シーズン1 最終話】敦に懸賞金を掛けた黒幕は、「ギルド」と呼ばれる北米異能力者集団のリーダーだった。先手を打たんとばかりに武装探偵社を来訪したフランシスは、お詫びの商談と称して「異能開業許可証」の買収を持ち掛けるが、理想高き福沢がこれを一蹴。しかし、彼らは一夜にして7階立てのビルを消滅させ、無言の警告を行う。さらに、行方不明となった賢治に続き、ナオミも街中で姿を消し…。敦は、人質となった仲間を救うべく、ルーシーの異能力空間に挑む。', '2018/11/08 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b1cd2be7-a946-411c-8389-4f7a6334d2ba.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c8f515c5-29fb-474f-b029-e020d8e213e2', '4aea23ea-bb53-4c50-b229-08c711c0f17a', 'hulu-bungo-stray-dogs-s2', 'シーズン2', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7397e9e6-4074-4446-b43b-1336162146d7.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bad271a0-8d44-4cd1-9504-5a1e9fe17fa0', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 13, '60790336', '黒の時代', '霧深き夜――。織田作之助がバー「ルパン」へ赴くと、先客の太宰治がいた。そこへ、密輸品の買い付け帰りの坂口安吾も合流。悪名高い「ポートマフィア」に属する男たちの、いつもの夜だった。だが、その日を最後に安吾が消息を絶つ。時を同じくして、暗証番号で守られた最高保管庫のひとつが「ミミック」なる組織に襲撃される。ボス･森鴎外から直々の指令を受けた織田作は、安吾捜索に乗り出すが…。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7397e9e6-4074-4446-b43b-1336162146d7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c1d5729-a70e-40d3-8241-254cdd486c58', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 14, '60793733', '戻れない場所', '織田作がとある洋食店に通うのは、何も好物の混ぜカレーを食べるだけではない。店主に、幼い子供――二年前に起きた抗争で親を失った孤児たちを預けているのである。織田作は、安吾の足跡を求め、彼と初めて出会った施設へと向かう。一方、ミミック兵を生け捕りにすべく仕掛けた罠の成果を確認しに行く太宰。だが、待ち受けていたのは物言わぬ死体。そこには部下の芥川龍之介がいた。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cda782a0-d44e-43d8-b041-544d8869fef1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7dcbb018-ef8e-4d93-bb1d-50a1838a6006', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 15, '60795405', 'いつか海の見える部屋で', '五大幹部会が招集され、ポートマフィア全戦力をもって犯罪組織ミミックを迎撃することが下される。街では奇襲を受けた武闘派の構成員たちが抗争を繰り広げるが、ミミックの首領･ジイドがあらわれ、芥川を圧倒。助けに入った織田作に、彼はある予言じみた言葉を告げるのだった。そして、また夜が来る―。いつものバーを訪れた太宰と織田作の前に、ミミックの手から救出されながらも、謎の黒い特殊部隊と共に消えた安吾が姿をあらわす。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/971f5792-6ce5-4ec2-910d-b2cc564b3835.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bb1e709-4e95-4bdc-9058-f68493bf38cd', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 16, '60798179', '文豪ストレイドッグ', '安吾の仲介により、ポートマフィアの首領･森鴎外と内務省異能特務課の最高指揮官･種田山頭火長官の会合が行われた。太宰は、ミミック襲来に始まる三組織の抗争に隠された思惑へと辿り着こうとしていた。だが、子供たちを惨殺され夢を失った織田作は彼の説得に耳を貸すことなく、たった一人で敵陣へと乗り込む。宿命の時を迎えた、織田作とジイド。同じ未来予測の異能力を持つ2人の戦いは、やがて奇妙な現象を引き起こしていく…。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d8e82e65-32ac-4c38-a64d-432091abf20d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59b3122e-d675-4a84-9e83-81539e42201c', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 17, '60799648', '三社鼎立 (ていりつ)', '人を殺めずに生きられる道を信じ、武装探偵社での初仕事に臨む鏡花だったが、お遣い先で一騒動起こしてしまう。うなだれる鏡花を励ます、敦。そのとき、もはや鳴らないはずの携帯電話から何者かが「夜叉白雪」に命令し、敦を斬りつけた。声の主は、ポートマフィアの幹部･尾崎紅葉。可愛がっている鏡花を連れ戻しにきたのだ。国木田たちが救援に駆けつけ、武装探偵社とポートマフィアは睨み合う。だがそこへ、組合 (ギルド) の異能力者たちがあらわれ…。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ab231855-2988-4289-9b28-20027b7aa291.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6cb2d066-581d-439d-93d2-ceb9aca3cb37', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 18, '60803679', 'The Strategy of Conflict', 'マーガレット･Mとナサニエル･Hは、組合 (ギルド) が拠点とする豪華客船を守っていた。そこへ舞い込んだ一通の手紙。「船と2人の命を消す」と綴られた、ポートマフィアのボス･森鴎外からの予告状だった。続いて船員が、不審な男―梶井基次郎を拘束。2人は梶井を侮るが、やがて彼の持つ真の異能を知ることとなる。そして、沈みゆく船上に次なる刺客の姿が…。さらに鴎外は、とある「手土産」とともに中原中也を武装探偵社へ差し向ける。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/229533c7-3361-4ead-b1e6-3695845f5371.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('062862d5-2179-43be-a5f6-bb56ea57fbb8', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 19, '60806640', 'ウィル･オブ･タイクーン', 'ポートマフィアからリークを受け、郊外に避難していたナオミと春野の誘拐に乗り出す組合 (ギルド) のジョン･Sとラヴクラフト。危ういところを、ありふれたモラルを越えた谷崎の愛が救う。一方、敦と太宰は、逃げてくる彼女たちを安全な場所まで護衛するため駅で待っていた。監視されていることに気付いた太宰は、敦から離れて樋口と黒蜥蜴をおびき出す。しかしそこで、最悪な展開を告げられるのだった。鴎外が、忌まわしき「Q」を解き放った、と――。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f8d384fb-41f5-41e8-9b4d-5d9e8bc62ed3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('973c61ec-cb3c-4314-918f-c1137c6b773e', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 20, '60808204', '頭は間違うことがあっても', '敦を連れ去ろうとするフランシス･Fの前に、消息を絶っていた鏡花が立ちふさがる。生まれて初めての思いを胸に“戦う”ことを決めた鏡花は、敦の手を取り走る。だが、ギルドの参謀長官であるルイーザ･Aの作戦に抜かりはなく…。ついに敦は空に浮かぶ異能要塞へと拉致されてしまう。そして、求めていた「人虎」を手中に収め、さらにQを拘束したフランシス･Fは、ヨコハマの街を混乱に陥れる「緊急プラン」の発動を命じるのだった。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5dec6a50-22f3-408f-b2af-1ad0afb4b18b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc2fcae8-bdd4-402c-a15e-ed04702a43d1', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 21, '60812726', '双 (ふた) つの黒', '探偵社とポートマフィアの共闘。そんな敦の荒唐無稽な提案が、両組織のトップを密談の場へと動かす。だが、鴎外が一時停戦の求めを呑むことはなかった。福沢は牽制する「今夜だけは邪魔をするな」と。その夜、Qの奪還に向かった太宰を待ち受けていたのは、組合 (ギルド) の罠、そして…。太宰と中也。一夜限りの復活を果たす、黒社会最悪と謳われた「双黒」コンビ。それこそが、鴎外の最適解だったのだ。かくして対組合 (ギルド) 共同戦線、反撃の狼煙が上がる――!', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cc7d7ac8-97e5-4d61-bdd3-268206c5bfd0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8277b5aa-9662-4912-a704-1e61e6cf1926', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 22, '60813878', '其の一『ポオと乱歩』／其の二『天 (あま) の海をゆく白鯨のありて』', '乱歩のもとに届いた「推理ゲームへの誘い」。それは、6年前に敗れた雪辱を果たすべく組合 (ギルド) の遠征船に同乗してきたというポオからの挑戦状だった。勝てば「組合 (ギルド) の弱点」を教えるという条件で、乱歩は与謝野とともに勝負を受ける。また太宰は、軍警に捕縛された鏡花を救出するため入院中の安吾を見舞う。そして、敦を白鯨 (モビー･ディック) に単独潜入させる作戦に出た探偵社であったが…。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5235405e-caca-4e30-87fa-7ca7b493d2d3.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e92d067-279b-4409-8c6f-9312371dd0a3', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 23, '60817272', '羅生門と虎と最後の大君', '白鯨 (モビー･ディック) の制御端末を探して敦は船内を走る。だがそこへ、敦への復讐に燃える芥川が立ちふさがるのだった。今にも街が失われようというときに、貴様を殺しに来たと言う芥川に対し、微塵も理解できないと憤る敦だが、2人は分かり合えるはずもなかった。太宰の指示でどうにか逃げおおせたものの、その先で制御端末を守っていたのは――。不運極まる敦が迎えた“最悪な状況”。ヨコハマの空の上、熾烈な戦いがはじまる。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/ba0f7097-87c8-4c6e-9b22-113735ed914e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15a6dc7d-35ef-4300-81ba-86f4aaeb535a', 'c8f515c5-29fb-474f-b029-e020d8e213e2', 24, '60819137', '若し今日この荷物を降ろして善いのなら', '【シーズン2 最終話】己のすべてを賭したフランシス･Fの野望を敦と芥川の協力による一撃が打ち破る。しかし、制御装置を手に安堵したのもつかの間。何者かによって、再び白鯨 (モビー･ディック) は地上へ迫っていく。「まだ方法はある」――。もはやこれまでかと諦めかけたそのとき、届いたのは鏡花の声だった。自分の乗る無人航空機を衝突させ、海に落とそうというのだ。たとえ、その身が硬い鎖につながれていようとも…。', '2018/11/15 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c37a0931-9cc0-4e13-9d9c-422bce6b99ec.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('08607b51-ad1f-4cfd-bbab-97f2054d628a', '4aea23ea-bb53-4c50-b229-08c711c0f17a', 'hulu-bungo-stray-dogs-s3', 'シーズン3', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13b2fcd8-36c4-4ad1-8622-b1ac7681400c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89e1c6dc-472e-41ad-b73b-e0942506fcdf', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 25, '100043739', '独り歩む', '「我が魂をかけて、この完璧なる予定をこなしてみせる!」。超重要案件が鈴生りとなったこの日、彼の意志は固かった。立ちふさがる武装探偵社の面々を払いのけ、相棒･太宰治の策にも弄されず、手帳に記したスケジュールを遂行せんと進む国木田独歩。だが、決して遅れられない列車に乗ったそのとき、黒いフードの男が少女に旅行かばんを手渡す光景が目に入る。頭をよぎる、爆弾魔の噂…。思わずホームへと飛び出した国木田に、番狂わせの一日が襲い掛かる―。', '2019/11/14 00:00:00', 1427, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13b2fcd8-36c4-4ad1-8622-b1ac7681400c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d00795d-55e5-4c85-ae37-5f95b19bce7b', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 26, '100034343', '太宰、中也、十五歳', 'ヨコハマ租界近くの擂鉢街に“とある人物”が現れたという噂を耳にしたポートマフィアのボス･森鴎外は、十五歳の少年･太宰治に真相究明を命じる。だが、調べを進める太宰に、敵対する組織の一つである「羊」のリーダー･中原中也が襲い掛かった。「お前が調べている『アラハバキ』について、話してもらおうか」と、聞き慣れぬ名を口にする中也。しかし2人は、突然の爆発に巻き込まれ…。そのとき太宰が見たのは―黒い爆炎を背に立つ「先代ボス」の姿だった。', '2019/04/19 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3f01d35-573a-4a95-8d2d-cfda5e5a1317.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e7d4eb4e-b7aa-4f15-aa8f-2d27e6689162', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 27, '100034730', '荒神は今', '「羊」の仲間を人質に取られ、太宰と行動を共にする中也。2人は「アラハバキ」による爆発の生存者に聞き込みを行おうとするが、ポートマフィアと敵対する「GSS」の襲撃に遭ってしまう。彼らの向かう先にして、森派に立つ構成員･蘭堂の屋敷をもまた爆破されたことから、すべてはポートマフィアを仲間割れさせるための対立組織による策謀かと思われた。しかし、蘭堂はこう証言し、その推測を覆す。すなわち「あれは、本当に“荒神”だった」と…。', '2019/04/26 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66191bfc-f467-4fc4-9871-4a12e9a1b544.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0a787369-a505-4c4b-9a8c-29bfa35e33d7', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 28, '100034888', 'ダイヤはダイヤでしか', '「どちらが先に犯人を糾弾できるか、勝負しよう」。太宰が持ちかけた推理勝負を受け入れる、中也。「羊」の仲間たちから「ポートマフィアの犬に成り下がったのか」と罵られようとも「これは俺の問題だ」と、その期待の眼差しを振り切って突き進むのだった。やがて彼らは、黒幕の告発に至るが…。明かされる、蘭堂の正体。そして、中也が「アラハバキ」を追っていた真の理由とは―?「先代ボス」の凶刃が、太宰に振り下ろされる!', '2019/05/03 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b07f41b1-cf7c-4d63-8442-90efc9fd028b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6cd0c629-0fc7-4df4-8d40-841edf26b906', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 29, '100035080', '咎与うるは神の業', '手足を拘束され、頭部を袋で覆われた―“怪物”。それは、組合 (ギルド) との抗争の際、密かに白鯨 (モビー･ディック) 墜落を図った、盗賊団「死の家の鼠」の頭目･フョードルであった。ポートマフィアに噛み付いた者には、痛烈なる報いが与えられなければならない。彼をプロの誘拐屋に捕らえさせた五大幹部の一人･エースが、その仕事を買って出る。奴隷同然の扱いを受けている下級構成員の少年･カルマは、袋の鼠となったフョードルを憐れむが…。', '2019/05/10 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/326a08c9-488e-4bc9-940e-a66750802d53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c49fba4d-3f5e-43e6-8725-d609ab246f11', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 30, '100035251', 'Slap the Stick & Addict', '組合 (ギルド) 戦を終え、その遺産を狙った海外組織が街に流入しているという噂もある中、いわゆる燃え尽き症候群に陥ってしまった武装探偵社は、同じビルの1階で営まれている喫茶「うずまき」で、無為に時を過ごしていた。だが、何者かに店が襲われて…。一方、白鯨 (モビー･ディック) の墜落を図った黒幕を追っていた国木田は、残された手がかりを持って、凄腕の情報屋･田山花袋を訪ねる。しかし、花袋はとある理由で異能力が使えなくなっていて―!?', '2019/05/17 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7d485bd-fda9-4fcf-9a79-45f06a73fdd5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f56f4a32-c427-4f32-8231-58049e30d12b', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 31, '100035844', '其の一「ヘルリス!」／其の二「父の肖像」', '武装探偵社の憩いの場である喫茶「うずまき」で、元･組合 (ギルド) のルーシーが住み込みで働き始めた。自分への“復讐”のためだと言われ、心当たりのない敦は戸惑うばかり。そんな中、彼女はぶっきらぼうに書類の束を突きつける。それは、店を訪れた人から託されたという鏡花への探偵仕事の依頼で―? また別の日、敦は、乱歩から、とある仕事を押し付けられてしまう。だが、向かった現場で被害者の身元を知り驚愕する…。', '2019/05/24 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7dd70a64-35e6-4604-aa33-70812a7efe01.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc01868a-5609-495d-83fc-3fe07c5aa0cf', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 32, '100036213', 'フィッツジェラルド･ライジング', 'ヨコハマの貧民街に、元･組合 (ギルド) のルイーザの姿があった。知らない人とは目も合わせられない内気な少女が、なぜ、このような危険な場所に? やがてボロを着た男に金をせびられた彼女は、答える。「差し上げれば、願いを聞いて下さいますか?」。その薄汚れた男こそ―いくら「生きているはずがない」と言われようと、あきらめずに探し続けた、かつてのボス･フランシスだ。だが、フランシスは、ルイーザを拒絶し…。', '2019/05/31 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ef93f5a-6249-473b-968d-64227aade267.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1873fb1-e869-48f6-9c98-c5d907423e8f', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 33, '100036678', '仮面ノ暗殺者', '「異能力者に死を」―。深夜、人気のない路地裏を一人歩いていた武装探偵社の社長･福沢諭吉が、仮面の男に襲われた。福沢は、武術の達人である。しかし、思わぬ“赤い閃光”の餌食となり、一命は取りとめたものの意識を失ってしまう。この頃、夜ともなれば同様の事件が横行し、死者も出ていた。「夜の管理者」たるポートマフィアが、そのような事態を黙って見過ごすわけもなく、すでに犯人は追い詰められていたのだが…。', '2019/06/07 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85c7438d-4ecc-492c-9aa5-0e7cfda3d3c8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5323fc90-38ad-4b12-b367-dd016a33dd4b', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 34, '100036828', '共喰い (其の一)', '福沢と鴎外に巣食うは「共喰い」の異能。48時間掛け、極小型の異能生物が宿主のからだを食い破るまでに成長する。だが、どちらかが死ねば、もう一方の異能も停止するという。これこそが、武装探偵社とポートマフィアを潰し合わせるべく弄された、フョードルの策略であった。ウイルスの異能力者を見つけ出すことを第一とし、ポートマフィアの包囲をくぐり抜けた武装探偵社。しかし、その隠れ家と思しき場所へ向かった国木田と敦を待ち受けていたのは…。', '2019/06/14 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/478fb9e5-f0b5-4bad-80c2-a7315b5abced.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0126c851-1977-4500-b48d-8df1fbd73f8a', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 35, '100037268', '共喰い (其の二)', '福沢は、己の死に瀕しながらも「ポートマフィアと戦ってはならぬ」と命じる。命令違反となる戦いに参加するか否か? 自らの推理力を持ってしてもウイルスの異能者を捕まえるのは無理だと判断した乱歩は、社員たちに選択を迫るのだった。国木田と敦は、花袋が黒幕の居場所を掴んでいるかもしれないという万が一の可能性に賭け、彼のアパートへ向かうのだが…。両社の戦いが、ついに火蓋を切る。ウイルス発症まで、あと14時間―。', '2019/06/21 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af532a6d-c7c8-4549-b4b4-0a87170faeaa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dd5fc4e-83cb-4088-a9dc-34a0fa5758cd', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 36, '100037950', '共喰い (其の三)', '武装探偵社とポートマフィアによる喰い合いは続く。今や、ヨコハマの地を守るべく実現された「三刻構想」は、終焉を迎えようとしていた。そんな中、福沢と鴎外は、同じ思いのもと、病床を抜け出すのだった。因縁の地で、2人は若き日のごとく刃を交え―。一方、敦と芥川は、敵のアジトが構えられた古い炭鉱跡に潜ることとなる。太宰は、2人に共闘を指示した。素直に受け入れる芥川に拍子抜けする敦だったが…?', '2019/06/28 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a78946f3-127e-43b8-89f3-f10064a5029b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d69ad6ae-134c-4a13-a76c-e1212be72c06', '08607b51-ad1f-4cfd-bbab-97f2054d628a', 37, '100038444', '回向 (ECHO)', '【シーズン3 最終話】ウイルス異能力者のプシュキンを追い、トロッコを走らせる敦と芥川。だがそこへ、坑道に地の利がある異能力を持つイワンが襲い掛かる…! 傷一つで感染し、力を奪うウイルスの脅威。2人は、「死の家の鼠」構成員たちとの攻防にあえぐ。その頃、太宰もまた、1回きりのチャンスに賭け、こちらの手勢を削ぐ数々のおとりの中からフョードルを探していた。果たして、太宰をも恐れる“魔人”によって仕組まれた「共喰い」抗争の行方は―!?', '2019/07/05 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ead603fb-7908-451d-8df7-374e08310a93.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', '4aea23ea-bb53-4c50-b229-08c711c0f17a', 'hulu-bungo-stray-dogs-s4', 'シーズン4', 4, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c90563c-3fc6-4470-a293-9e41e6c8fe70.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bba006ae-ee4a-4f4e-bb5b-6eda3d5c1bbb', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 38, '100134278', '孤剣士と名探偵', '軍警にも望まれる剣客ながら、誰とも組まず一人で要人護衛の任にあたる孤高の無頼人、福沢諭吉。この日、彼は自己嫌悪に陥っていた。依頼人の会社社長が暗殺されてしまったのだ。現場では、すでに犯人が捕らえられていたが、福沢はその状況に違和感を覚える。そこに、事務見習いの面接を受ける予定だったという学生帽の少年がやって来て……。少年の名は、江戸川乱歩。「両親を亡くし、行くあてもない」と身上を聞かされた福沢は、仕方なく彼を同伴し、とある演劇場へ向かう。', '2023/01/11 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c90563c-3fc6-4470-a293-9e41e6c8fe70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d49fb76a-08f1-45c4-b776-990a8fbf500c', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 39, '100134722', '晝は夢、夜ぞ現', '乱歩とともに、演劇場の警護にあたる福沢。自分の前職を見抜いた乱歩の類まれなる推理力を認めるとともに、思ったことをはばかり無く口にしてしまう幼さに業を煮やした福沢は、彼の「異能力」が自在にコントロールできる道具だと嘘をつき、ありふれた眼鏡を与える。「僕にはもう見えているんだよ。敵の狙いも計画も全部」。だが、事件は第二幕で起きる。何の凶器もない舞台上で、主役の胸から鮮血が吹き出したのだ――!', '2023/01/18 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4977e54c-127f-4e8c-8031-298be1253f5c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f90a965e-2d83-4afa-9712-78bccd25414f', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 40, '100135284', '探偵社設立秘話', '「天使」による殺人かと思われた演劇場の事件も解決し、あらためて乱歩の慧眼を讃える福沢。だが、乱歩は自分が「異能力者」だと言われたことを真に受け、すっかり調子づいていた。そして、事情調査に向かうべく一人で巡査の車に乗り込むのだが……。届いた凶報に、福沢は思い出す。乱歩が、もっと大きな事件を暴き出すつもりだと話していたことを――。誘拐されてしまう乱歩。福沢は、犯罪組織の情報を得るため、とある人物を尋ねる。', '2023/01/25 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb9291d5-a77f-473b-bad6-0d26974c0d87.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99450af8-303d-403a-96ef-99644acebb2e', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 41, '100135807', '完璧な殺人と殺人者 (其の一)', 'フョードルの仕掛けた罠により、少女爆殺の罪に問われる国木田。それを見破れなかった乱歩もまた悔恨をつのらせ、冤罪を晴らすことを誓う。そして、プシュキンから得た証言と写真を手がかりに、証拠隠滅の専門家である「隠滅屋」があらわれるという展望台へ向かうのだった。とある取り引きのため、たまたま同じ場所に居合わせたポオを無理やり引き入れ、身を潜ませる2人。だが、待ちくたびれた彼らが目にしたのは、写真の男が地上へと転落していく瞬間だった……。', '2023/02/01 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ede5ddc-bfff-4e09-b448-694215ce755b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a463ed14-3eb5-4382-99ea-2beb3355e468', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 42, '100136574', '完璧な殺人と殺人者 (其の二)', '完全犯罪に酔いしれる小栗虫太郎。だがそこへ、あきらめて帰ろうとした乱歩がタクシー乗り場を尋ねてくるという珍事が起こる。さらには、フョードルの寄越した送迎車にまで乗り込んできて……!? 隣に座る人物が誰かも知らず、今の自分が抱えるいくつかの謎における推理を展開していく乱歩。やがて、探している「隠滅屋」と、ポオを始めとするミステリー愛好家たちを騒がせている「推理作家殺し」の犯人が同一人物であると言い出し……。', '2023/02/08 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78d06e45-084a-4361-8e1f-f33e255a4b59.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82e22b4e-1f25-4ae6-9833-639cd3e44afa', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 43, '100137156', '悲劇なる日曜日', '凶悪犯罪者プシュキンとフョードルを捕らえたことで、武装探偵社は祓魔梓弓章を与えられることとなった。一民間企業としては類を見ない栄誉である。そこへ、政府より緊急要請が入る。同一犯による4件の連続殺害事件――。「天人五衰」という猟奇的な殺害方法に見出されたある共通点から、起こるであろうあと1件を未然に阻止すべく探偵社は立ち上がった。だが〝友人〟から警告を受けていた乱歩は、仕事を受けることに反対し……。', '2023/02/15 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b314120-27e5-4ad9-866c-0762d65bfde4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e1d1099-59cf-46af-8988-e91543a8fd51', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 44, '100137950', 'DOGS HUNT DOGS', '斗南司法次官を長とする秘密会議を襲撃した犯罪組織「天人五衰」。だが、ニコライの策略によって、国木田たちがそのテロリストであるように仕立てられてしまう。そして、別のルートから事件にあたっていた乱歩もまた種田長官襲撃犯として追われることとなるのだった。これは、ただの異能力による現実改変ではない。奪われた「白紙の本」の頁によって、自分たちの記憶までも書き換えられているのだ。動揺する探偵社に、福地桜痴率いる軍警最強の特殊部隊「猟犬」が襲いかかる――!', '2023/02/22 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0713a762-3641-4666-857a-29de68c85cd7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3f1e392f-184c-49d6-bf58-c0841b70342d', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 45, '100138703', '君も罪の子、我も罪の子', '社長は逮捕され、逃亡中の国木田が自爆により生死不明。太宰もまた、ポートマフィア時代の罪が明るみとなり、収監されていた。これがフョードルの描くシナリオならば、敦と鏡花のたった2人で立ち向かえるわけもない――。絶望の中、それでも敦は顔を上げた。探偵社の無実を証明する鍵は、この顛末を警告していた虫太郎だ。彼を探し出すため、敦と鏡花は「神の目 (アイズオブゴッド)」を持つフランシスのもとへ向かう。だが、そこにもすでに魔人の手が伸びていて……。', '2023/03/01 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40032148-c9f1-42eb-967f-b700e54fbc6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bd0ed8c5-b9c8-4437-9e6e-4337b33e1f93', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 46, '100139804', '蝶を夢む', 'ポートマフィアが探偵社を救助する対価が「社員一人の移籍」であると聞き、森が自分を目的に提示したことを汲んだ与謝野は憤る。フランシスは、昏睡状態のマーガレットを治癒することを条件に「神の目 (アイズオブゴッド)」の使用を許可するという。だが、彼は勝算のある方に与する男だ。罠の可能性もある中、与謝野は一人で取引場所へ向かった。彼女がポートマフィアを厭う理由――。その因縁の始まりは、大戦末期の戦場で「天使」と呼ばれた11歳の少女が見た地獄にあった。', '2023/03/08 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01305a55-5f68-4d86-ad06-bf456ab065e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfa2f7dc-e683-4ed5-beaa-4c78ae1b8f83', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 47, '100140349', '翅無き身の悲しきかな', 'フランシスは敵側についていた! 政府機動隊に包囲され、ポートマフィアの秘密通路へ逃げ込んだ探偵社。追撃者の中に猟犬が一人いることを察した与謝野は、谷崎と賢治にバラバラに逃げることを提案する。誰が生き残っても、探偵社再建に命を懸けることを約束して――。一人になった与謝野に迫る、雨合羽の男。そこを救ったのは、森から「自分の身に変えても探偵社を守れ」と命じられていた黒蜥蜴の3人だった。だが、地獄からよみがえった「亡霊」も現れ……。', '2023/03/15 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8521476e-c021-4ca1-8d2d-edd30a094892.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a40b2f1b-4ade-42aa-96c7-e5fa17a4b041', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 48, '100140776', '脱獄記', '監禁室へと押し入った敦と鏡花を邪険にする虫太郎であったが、鏡花が乱歩から言われていた「ある言葉」を口にすると一変し、外へ出る。だがそれも、警備員に敦たちを捕まえさせようという魂胆ゆえ。しかし、特務課の機動隊員たちが駆けつけ、虫太郎は震え上がる。なぜなら、その指揮を執る安吾こそ、フョードルと取引する前に囚われていた犯罪組織「七號機関」の長だったのだ。捕まるわけにはいかない――。3人の必死の脱獄劇が始まる!', '2023/03/22 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d76f6e36-a38e-4aed-8204-c361e7873615.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5262cb3-eaa4-45d5-8f39-e3d69b880e2a', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 49, '100141522', '文豪ハウンドドッグス', '凶悪な無国籍テロ組織「天人五衰」の正体が武装探偵社だと判明してから4日。2日前の銀行襲撃を最後に、彼らの足跡は途絶えていた。ルーシーが協力していると踏んだ条野と鉄腸は、喫茶「うずまき」を訪れ、敦たちが向かった場所を突き止める。それは、如何なる国家の警察権も適用されない、蒼穹に浮かぶ天空カジノだった――。カジノを封鎖して捜索に協力するよう求められた総支配人のシグマは要請を拒否するが、黙って追い払われる猟犬ではなく……。', '2023/03/29 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35fa5711-8f43-4295-a807-da7aedd49d4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9dbfc9ad-802b-499d-8be1-276ea7fff51c', '875fdb51-9a1f-46da-b8d5-4ac1a96cbff5', 50, '100141943', 'SKYFALL', '【シーズン4 最終話】明らかになる、天空カジノの真の目的。シグマは、宿泊客を煽動して猟犬を襲わせる。そこには、如何なる手段を講じても与えられた場所を守ろうとする彼の執念があった。だが燁子にも、決してテロリストには屈しまいという覚悟がある。一方、現実改変を引き起こした「白紙の本」の頁のありかを知るシグマを捕獲し、テロを防ぐことで猟犬を味方につけるという太宰からの指令を受けていた敦であったが、両者の間に介入できず焦りが募る。そんな中、ついにシグマは燁子を道連れとする最後の手段に出て……。', '2023/04/05 23:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dcce1176-afe0-479d-b0f7-adf8a996883e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d08d3db0-34e5-452f-846f-0f40d8291531', '文豪ストレイドッグス わん！', '', 'hulu', 'bungo-stray-dogs-wan', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d655e09c-de73-4055-8839-0c11cd5f5d8b.jpg?w=331&h=447&p=t', 'hulu', 2021, 0, 1, 'FINISHED', NULL, 120150, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('69df268a-a1af-4da0-aa61-b645296185c8', 'd08d3db0-34e5-452f-846f-0f40d8291531', 'hulu-bungo-stray-dogs-wan-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c026b15-01e3-4dc1-8d06-45b5c71e446e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ea7459d-f741-4e27-af51-c8bbead0a93f', '69df268a-a1af-4da0-aa61-b645296185c8', 1, '100073257', '第1わん!', '風が吹くその街に、宵闇の中を宛もなくひた疾走る“迷い犬”たちの姿があった。彼らの縄張りに残された危険なにおいに、今、熾烈な戦いの幕が開く……!', '2021/01/18 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c026b15-01e3-4dc1-8d06-45b5c71e446e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('909170ea-3753-4ee8-b99b-102687616829', '69df268a-a1af-4da0-aa61-b645296185c8', 2, '100073757', '第2わん!', '国木田から、武装探偵社のみんなで出掛ける花見の場所取りを頼まれた敦。だが、その話に耳をそばだてる者が……。翌日、気合いを入れて早朝から公園へ向かった敦を待ち受けていた悲劇とは!?', '2021/01/25 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8c683bc3-7cde-4f58-90e2-c0c13104c58a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c0f41f47-de3a-459a-9780-2b6e000302c0', '69df268a-a1af-4da0-aa61-b645296185c8', 3, '100074171', '第3わん!', '多忙で備品の買い出しに行けずにいた与謝野に「僕が頼まれてあげようか?」と、乱歩。珍しいこともあるものだと思いきや……? また、迷子の猫を拾ってきた鏡花に、クドクドと国木田のお説教が始まる!', '2021/02/01 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/874a2a24-1dda-49f4-ad65-cd34cfc42c4b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d4cec20-52fe-49f7-a81c-65f1a49e5b91', '69df268a-a1af-4da0-aa61-b645296185c8', 4, '100074671', '第4わん!', '太宰から電話でお遣いを頼まれた芥川は「何としてでも完遂してみせる!」と、全身全霊で買い物に向かう。またある日、そんな憧れの太宰先輩に“敦にあって、自分にないもの”を指摘された芥川は……。', '2021/02/08 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1cf241a-0f3d-4367-8dfd-506d90f0a68b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('271d1091-3110-45a6-9bfa-c4efb2a6031b', '69df268a-a1af-4da0-aa61-b645296185c8', 5, '100075456', '第5わん!', '包帯ぐるぐるの太宰、チョーカーに黒手袋の中也。顔を合わせればケンカばかりしているふたりは、何かと多感な中学2年生だ。今日も、チャイムの音とともに異能中学校のにぎやかな一日が始まる。', '2021/02/15 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d53ed3f-f105-4157-be5e-da64ab44e896.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e38fba3d-6604-4f1a-b0b2-6763da994941', '69df268a-a1af-4da0-aa61-b645296185c8', 6, '100075890', '第6わん!', 'ちょっとしたいたずらのつもりで、国木田の背中にとある文書を書いた紙を貼り付けた太宰。だが、国木田は、要人との会合に向かってしまう。またある日には、太宰によって「踊ってみたコンテスト」に参加させられる国木田で……。', '2021/02/22 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1e64da2-6e63-420e-8dc5-636d85e4a7e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77c18d60-28f3-4ae9-8973-2fab47e0145b', '69df268a-a1af-4da0-aa61-b645296185c8', 7, '100076451', '第7わん!', '敦は純粋な瞳を輝かせながら太宰の手が差し出されることを求め、誰彼構わず噛み付く芥川さえも太宰に対しては深い尊敬の眼差しでまとわりつく。この太宰を取り巻く喧騒……おちおち自殺もできやしない!', '2021/03/01 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5ab15de-55da-489f-8ab6-57cf15b9516d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b9817c7-af8a-47e9-bcc6-d1c395e88345', '69df268a-a1af-4da0-aa61-b645296185c8', 8, '100076863', '第8わん!', '今日も張り切って仕事に向かう、ポートマフィアの樋口一葉。だが、風邪を引いた芥川が倒れてしまって……。また、危険な取引きへ出掛ける森を守るべく、突如行われた「影武者コンテスト」の優勝者は!?', '2021/03/08 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eec4016d-0fa5-4759-a475-6eb729e2d695.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('344a6e98-b56e-476d-aa2a-f03c06ab4a99', '69df268a-a1af-4da0-aa61-b645296185c8', 9, '100077680', '第9わん!', '愛用のメスが一本見当たらないことに気づいた、与謝野。まさか、手術した誰かの体内に残してきた? 医療ミスの発覚を恐れ、心当たりの同僚たちに、それとなく体調を聞き出そうとするのだが……。', '2021/03/15 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f01ac40b-1660-49e5-a36d-94dadaceea8c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aad70a5f-acad-4aed-8396-5431aa2c39a9', '69df268a-a1af-4da0-aa61-b645296185c8', 10, '100078145', '第10わん!', '寒い寒い、冬の日のこと。「みんなで食べよう!」と、おでんを用意しようとする太宰だが、作り方がわからず……。また、夏には山林へ。武装探偵社の面々は、いつもとは違った装いで、納涼のときを楽しむ。', '2021/03/22 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e4c5e43-8d8b-4598-883b-ede5519cc95c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f04e246a-afe9-41fc-8fc9-9a70865e66b9', '69df268a-a1af-4da0-aa61-b645296185c8', 11, '100078518', '第11わん!', '日頃お世話になっている方たちへ旧年の感謝と新年にも変わらぬ交友を願って送る、年賀状。果たして、そのようなヒューマニティあふれる行いが太宰という男に全うできるのだろうか!?', '2021/03/29 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/837bc7e3-6df5-4d2c-a2a4-7bf007e9c8b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('474ec5a7-0e1f-4e83-873b-3675ceaa3281', '69df268a-a1af-4da0-aa61-b645296185c8', 12, '100079142', '第12わん!', '【最終話】頭と頭をぶつけた太宰と敦の中身が入れ替わってしまった! おとなしくしていてくれとせがむ敦をよそに、太宰は!? またある日には、そんな振り回されてばかりの敦が、逆に太宰を驚かせようとして……?', '2021/04/05 00:30:00', 701, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f75caf71-fc94-49fa-b544-c40285e379ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('36cc532b-67a6-4f56-8b50-551a85b2ccec', '文豪とアルケミスト ～審判ノ歯車～', '', 'hulu', 'bungo-alchemist', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92d6d0d6-6d46-45ae-9464-9ebe7d2c2ef6.jpg?w=331&h=447&p=t', 'hulu', 2020, 1, 1, 'FINISHED', NULL, 114411, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3f83d450-82e5-4d6b-b4d8-7683ffe759c6', '36cc532b-67a6-4f56-8b50-551a85b2ccec', 'hulu-bungo-alchemist-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84b0cf35-2a9d-4fe0-8996-d862a930b9d5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f3d29e9-5710-4729-bf15-4d1ab43e1b24', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 1, '100053424', '走れメロス', 'この世界には無数の本があるが、それらをこの世界から消し去ろうとする“侵蝕者”がいる。侵蝕者の標的となってしまった本には、その本を書いた作家の魂が囚われてしまうのだ―。太宰治は、走っていた。自分の身代わりとして、磔となっている親友との約束を果たすために。しかし、友の元に戻れば自分が王に殺される…。太宰の心は揺れるが、走り続けて王宮へ戻るようにとけしかけてくる不思議な男が現れる。幾多の困難を乗り越え、太宰は日没前に友が待つ王宮へとたどり着く。だが、王に促され親友の顔を改めて確認すると、それはかつて自分を裏切った人物だった…。', '2020/04/07 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84b0cf35-2a9d-4fe0-8996-d862a930b9d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ae788fe-9041-49c4-9d18-ef383b25e591', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 2, '100053425', '桜の森の満開の下 前編', '本の中に入り込み、侵蝕者により自著の中に囚われた作者を救う“潜書”ができるのは、アルケミストによって転生させられた文豪のみだ。坂口安吾の『桜の森の満開の下』に潜書していた織田作之助が、大怪我を負って帰還した。傷がひどく、再び本の中に戻ることが困難な織田に代わり、芥川龍之介、そして坂口、織田と同じ“無頼派”である太宰が潜書に行くと申し出る。無事潜書できたふたりは、それぞれ美しい女性に遭遇するのだった。一方、なんとか起き上がった織田は、「今の安吾は危険すぎる」と、芥川と太宰を案ずる。', '2020/04/14 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d7eac93e-4bb1-469c-902f-3ff017af39eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6fa65ba-ad15-4923-a2d8-df3180212acb', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 3, '100053426', '桜の森の満開の下 後編', '「大切な女房が首をほしがっているから…」と、太宰の目の前で美女の首を斬り落とした坂口。その姿は、作中に登場する“山賊の男”そのものだった。坂口は太刀を振りかぶり、太宰をも斬ろうとするが、既のところで芥川が助けに入る。その後しばらく、山賊と化した坂口とその女房の様子を偵察していた芥川と太宰。物語を正しく完遂させて侵蝕者を消滅するために、ふたりは物語を強制的に動かすことを決意し、ある行動に出るのだった。そのころ図書館では、再び潜書しようとしていた織田が「坂口があの本の囚われているのは、たぶん自分と太宰のせいや」と、中原中也に語る。', '2020/04/21 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb24a4df-364f-4a58-8e5d-2e078c01cdb3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3bd320c1-c478-4055-8310-feb69edb5604', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 4, '100053427', '月に吠える 前編', 'ヨージはある日、バスの中で遭遇した美しい少年･ハルカに心惹かれる。ハルカが読んでいた『斜陽』に興味を持ったヨージが、書店で探していると、どこからともなく本の作者や在り処をガイドする声が聞こえてくる。ヨージは文豪の姿と声を見聞きできる少年だったのだ。ハルカと親交を深めるために本を読み始めたヨージだが、徐々に文学に魅了されていく。しかしある日、大好きだった本たちが突如消え失せてしまう。消失したものが何だったのかも思い出せず、ただ喪失感で苦しむヨージは、ハルカに連絡を取ろうとするが…。', '2020/05/12 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e65da0d7-e358-4203-9c46-88975845fc4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('01a06f3d-0caf-42ce-9b95-5bd69da6a382', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 5, '100053428', '月に吠える 後編', '萩原朔太郎の『月に吠える』へと潜書した芥川ら、文豪たち。ピストルの音を聞き、駆けつけてみると、血だまりの中に中原が沈んでいた。太宰が声をかけてみると普通に受け答えをする中原だが、「どうやら死んでいるみたいだ」と言う。事態を解決するため、中原を殺した犯人を推理する太宰。その犯人が判明した瞬間、今度は太宰が中原同様の“意識のある死体”となって血だまりに沈んでいた! 犯人…つまり侵蝕者は、この物語の世界そのものに干渉していると、芥川は推測するが…。', '2020/05/19 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/699635fb-d0b5-493a-9c7c-64b52506d341.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b58cce1-890c-428b-a322-95385fe7d530', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 6, '100053429', '地獄変 前編', '武者小路実篤と志賀直哉が新たに転生し、図書館へやってきた。生前から志賀のことが気に入らない太宰はイライラを募らせ、芥川本人に向かって『羅生門』を批評する志賀を見て、怒りを爆発させる。そんななか武者小路が、図書館という閉鎖空間での生活がストレスを溜めると考え、全員で農業を始めようと提案。太宰たちが嫌がるも、王子様然としたところのある武者小路は無理くり押し切り、文豪たちは農業を始めることになってしまう。志賀に対抗心を燃やす太宰は、「どちらがおいしい農作物を作るか、芥川先生に判断してもらおう」と、勝負を持ちかける。', '2020/05/26 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15598dbc-9157-42ca-a61e-b9fa3d1844b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('789f08d0-9f52-4f3b-ac87-5926059d18e7', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 7, '100053430', '地獄変 後編', '芥川の『地獄変』が突如侵蝕され始め、芥川本人も本に飲み込まれてしまった。助けたい太宰たちだが、誰ひとりとして本に呼ばれず、潜書ができない。いてもたってもいられない太宰は、無理やり本に触れて潜書を試みるが、即座に体が侵蝕されてしまい、もがき苦しむ。志賀が加勢し、再び本を掴んで侵蝕の苦しみに耐えるふたりだが…!?', '2020/06/02 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd8cfcec-4836-40de-a8ad-ae1b5b694acf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d39ad0a-9698-4259-98a3-c194f480ae2a', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 8, '100054649', '人間失格 前編', '志賀の一件以来、どことなく元気のない芥川。太宰は、芥川を元気づけるための会を発足しようと文豪たちに持ちかける。そのころ芥川は、自分を尊敬してくれる太宰に興味を持ち、同じ無頼派である坂口と織田に「太宰治」という男がどんな人間なのか尋ねてみることに。すると、太宰の本質を知るために、『人間失格』を読むことを勧められる。一方、自らの初期の作風を完全否定する芥川の思考に違和感を覚えていた島崎藤村は、芥川に対してある仮説を立てるのだった。', '2020/07/07 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0b77b34-fc4d-4a25-9d7c-f628ea3c35b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a1471e2-01c8-4452-8814-0e58d7e29a19', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 9, '100054650', '人間失格 後編', '『人間失格』の侵蝕が始まり、本に選ばれた坂口と織田が潜書することになった。さっそく本の中へと入ってみると、屋敷の中には複数の血まみれの死体が転がっている。『人間失格』にはそんな描写はないはずだが…と、ふたりが戸惑っていると、そこへ返り血を浴びた太宰が現れる。そのころ図書館の独房では、意識を取り戻した芥川が、太宰を救うために立ち上がる。', '2020/07/14 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3a91795-dd75-443f-b748-3f2f7b5cf809.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba1d5dec-5931-4430-b918-9856248be651', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 10, '100054651', '藪の中', '「僕は芥川龍之介で間違いないのだろうか」―芥川は、転生直後、これまでの記憶が定かでは無かった。潜書者としての使命を通じて生前の自分を知る文豪たちと再会し、記憶を手繰り寄せることで“欠落した自分”を埋めようとしていた芥川。彼はこれまでどんな思いで戦い、文豪たちを侵蝕から救ってきたのだろうか。そして芥川は、自分自身を救うことができるのか…。', '2020/07/21 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6bbf7683-c786-49bd-88ff-ae4da393ba8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e28c291c-3e8c-4dda-a3bf-3bf6c625783d', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 11, '100060403', '恩讐の彼方に', '「これはきっと、すべて僕のせいなのだ」―。菊池寛、堀辰雄、久米正雄、そして芥川、4名の文豪はアルケミストに呼び出され、転生するはずだった。しかし、異形の侵蝕者によって“狭間の空間”へと送られてしまう。その空虚とされる空間で、いったい何が起こったのか? 今、芥川の本心、そして彼が抱えていた苦悩が明かされる…!', '2020/07/28 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3adb695-ae4a-458d-9604-6a0f8e94b64b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87afd0f4-de07-41bb-b717-4e7e9aa3af70', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 12, '100060404', '歯車 前編', 'これは芥川が転生する前の話―。人々の期待に応えるため、常に自分を責め、その命と精神を削って物語を紡ぎ出していた芥川には、自分のことを肯定してくれる友人が必要だった。「最近、歯車が見えるんだ」―どんなに苦しくても書くことから逃れられない芥川は、“彼”にそうつぶやく。さらに芥川は、“彼”に哀しい頼み事をするのだった…。芥川の死によって、小説に憎悪を抱くようになった“彼”は、侵蝕者につけ入る隙を与えてしまう。 芥川の著作は侵蝕が進み、最後に残るは遺作の『歯車』のみ。彼が本で綴った想いを守るため、太宰をはじめとした文豪たちは『歯車』への潜書を試みる。', '2020/08/04 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd02c9ef-7bd3-4893-8582-06ea045a1126.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c4acaa0-679b-4e2f-ba0e-c086d2022858', '3f83d450-82e5-4d6b-b4d8-7683ffe759c6', 13, '100060405', '歯車 後編', '【最終話】芥川の本を守りたい…そんな強固な想いが、太宰を奮い立たせる。傷だらけになりながらも、立ち向かおうとする太宰。しかし、作家たちの魂が砕かれてしまった今、為す術は残されていない。そんな絶望的状況のなか、アルケミストの石が淡く光を帯びる。この光は、文豪たちの希望となるのか!?', '2020/08/11 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7040c3a8-8fa8-429d-988f-6602a5a6d5ec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('063a5c23-329a-49d9-a3f5-39d9b98df1d1', '変人のサラダボウル', '', 'hulu', 'a-salad-bowl-of-eccentrics', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/462d386e-3f23-4541-8e83-7b5e61cf6606.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 166828, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('642db682-3d14-491b-9939-365a2009bc79', '063a5c23-329a-49d9-a3f5-39d9b98df1d1', 'hulu-a-salad-bowl-of-eccentrics-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62022b51-930d-4c15-b819-b03c6c25bf7e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6fb9625-a09e-4895-934b-9cb94eedff41', '642db682-3d14-491b-9939-365a2009bc79', 1, '100179867', '「麒麟がくる (異世界から) 」', '岐阜県岐阜市に住む貧乏探偵、鏑矢惣助は、調査対象を尾行中、異世界から転移してきた魔術を操る皇女、サラと出会う。身寄りのないサラを仕方なく住まわせることになった惣助。あっという間に現代日本に順応したサラは、貧乏生活から抜け出すため惣助の仕事を手伝うと言い出し…', '2024/04/08 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62022b51-930d-4c15-b819-b03c6c25bf7e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8036a5e4-4ccb-4352-8414-fbe301ea8556', '642db682-3d14-491b-9939-365a2009bc79', 2, '100180673', '「ホームレス女騎士／はじめてのおしごと他」', '主のサラを追って異世界へとやってきた女騎士リヴィアは、行く当てがなくホームレスとなってしまう。サラを探すべく探偵に依頼するため、お金を稼ごうとするリヴィアだが、住所もスマホもないので仕事は見つからない。そこへ怪しげな男、タケオがリヴィアに声をかけてきて…', '2024/04/15 03:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c92e880-dfea-4186-943b-86986844471c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71ea84f8-0e26-4735-bc56-7d558c07585c', '642db682-3d14-491b-9939-365a2009bc79', 3, '100181930', '「救世主女騎士他」', '探偵事務所をクビになり、再びホームレスとして生活することになったリヴィア。いつものように炊き出しに行くと、ボランティアの若者達に声をかけられる。彼らに誘われてリヴィアが訪れたのは、ワールズブランチヒルクランというカルト宗教団体の施設だった…。', '2024/04/22 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0d766c6a-a2cc-4a02-9e2d-d5b21fee7240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e8334a3-19d7-45c9-bd28-51ed4831479c', '642db682-3d14-491b-9939-365a2009bc79', 4, '100182400', '「ハロウィン IN 岐阜他」', '惣助の後輩、閨春花の紹介でイジメの調査を引き受けることになったサラと惣助は、依頼人の娘で中学1年生の少女、永縄友奈に話を聞きに向かう。自分がいじめられていることを頑なに否定する友奈だったが、サラとある共通の趣味の話題で盛り上がり、打ち解けるのだった。', '2024/04/29 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40438ee1-4f54-4cc8-8128-a0a3c899be97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2985b845-4892-40fa-a746-861c6110d30c', '642db682-3d14-491b-9939-365a2009bc79', 5, '100182980', '「ホームレス女騎士、ととのう他」', 'サラのための居場所を作るという目標を見失い、途方に暮れていたリヴィア。ある日、銭湯でくつろいでいると、以前タケオに騙され働いた違法セクキャバで出会った少女、プリケツと再会する。サウナでお互いの近況を話している中、プリケツから自身の夢が語られる…', '2024/05/06 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/42387d83-3064-427b-bade-db267075c570.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40bad6f6-8f24-467b-b12d-943a6579e404', '642db682-3d14-491b-9939-365a2009bc79', 6, '100184001', '「宗教家ちゃんと救世主ちゃん他」', '宗教団体の指導者、皆神望愛は、探偵を雇って救世主リヴィアの居所を探し出す。望愛に「リヴィア様の像を作るため、全身を3Dスキャンさせてほしい」と頼まれたリヴィアは、それを了承し望愛の家を訪れ、そのまま教団の商品開発アドバイザーとして雇われることになる…', '2024/05/13 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5dd6ea2a-0fca-44a8-9fe8-e670ddc3a5bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8233887e-1242-4be0-b565-063922ce4375', '642db682-3d14-491b-9939-365a2009bc79', 7, '100184525', '「異世界人の戸籍問題他」', '「学校に行ってみたい」というサラの願いを叶えるため、惣助は弁護士の愛崎ブレンダに相談を持ちかけるのだが、異世界人であることを隠したまま合法的に戸籍を作る手段はないという。落胆しつつ仕事に向かう惣助とサラ。調査対象を追って辿り着いたのは、隣町の競馬場だった…', '2024/05/20 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9cdc0aad-74f8-4220-9687-1ba9a53ad671.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b42eb997-2c83-4c4e-89f3-8454aa451609', '642db682-3d14-491b-9939-365a2009bc79', 8, '100184979', '「姫と父親他」', 'サラを自分の子供にするため、惣助はかつて自分が勤めていた探偵事務所の所長、草薙勲に仕方なく協力を仰ぐことを決意する。サラが戸籍を手に入れるためには非合法な手段しかなく、勲は惣助に「お前の目指す正義の探偵は、自分が罪を犯すことを許すのか?」と問いかける…。', '2024/05/27 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21d2d9d2-0e1e-4995-9ea4-b8ca2fa6c862.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8b4f099-10fc-4bd0-9ff1-b5d784c7269b', '642db682-3d14-491b-9939-365a2009bc79', 9, '100186009', '「魔王の末裔、小学デビューする他」', '戸籍を手に入れついに小学校に通うことになったサラ。明るく頭脳明晰なサラは瞬く間にクラスで人気者となるのだが、それを妬む児童たちもいた。一方、新しい中学に転校した友奈は初日の言動によりクラスで浮いていた。トイレで昼食を食べていた友奈は、ある日イジメの現場に遭遇し…', '2024/06/03 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0690639-fc2d-4d66-b288-11037dc63ddd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31f6dd91-6e53-4894-8131-bd1b76a45dec', '642db682-3d14-491b-9939-365a2009bc79', 10, '100186712', '「遊び人女騎士他」', 'サラは小学生ライフを謳歌する一方で、リヴィアは望愛のヒモとして毎日パチンコに明け暮れて過ごしていた。あるときチンピラのタケオと再会したリヴィアは、彼から岐阜にはパチンコ以外にも競馬や競輪というギャンブル場があることを教わり、ますます遊び人化していくのだった…', '2024/06/10 02:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5f4a0d2-2d34-4550-8adf-c30e5ebf8d00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be0462c5-727d-4c47-92b0-858576938c1d', '642db682-3d14-491b-9939-365a2009bc79', 11, '100187461', '「クリスマス IN 岐阜他」', '12月24日、一日中たくさんの場所でクリスマスパーティーに出席し、サラが満腹になって事務所で突っ伏していると、サンタコスをしたリヴィアがやってきた。リヴィアがクリスマスプレゼントとしてサラに差し出したのは、ついに完成したリヴィアの着せ替えドールだった…', '2024/06/17 03:30:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e854bb73-b39f-4d99-8481-2acb3d519202.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9af58fa9-b5dc-46fb-878a-e4204efc57bc', '642db682-3d14-491b-9939-365a2009bc79', 12, '100188063', '「変人のサラダボウル他」', '【最終話】リヴィア、プリケツ、望愛のガールズバンド「救世グラスホッパー」がついに本格的に活動を開始する。バンドは瞬く間に人気を獲得していき、ついに…。一方、入学してわずか3ヶ月で卒業となったサラの卒業式に出席する惣助。特に感慨もなく席に座っていた惣助を待っていたのは…', '2024/06/24 02:00:00', 1435, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/66ba04be-b451-4af9-a3ab-0f1450e15e3c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('57a79db3-c938-4c7f-a5c5-a527e63dd46c', '便利屋斎藤さん、異世界に行く', '', 'hulu', 'handyman-saitou-in-another-world', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5e48f23-81da-40bc-9b28-148113332cb3.jpg?w=331&h=447&p=t', 'hulu', 2023, 0, 1, 'FINISHED', NULL, 144092, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5cc20516-280d-4a1c-9847-72e214b2c6f8', '57a79db3-c938-4c7f-a5c5-a527e63dd46c', 'hulu-handyman-saitou-in-another-world-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/096de91f-b350-494c-91f2-79cd8ecff649.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('397a3ffc-5486-471f-a144-d04c9932c50d', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 1, '100134438', '便利屋、斎藤さん', '異世界に転生したサイトウは、重戦士ラエルザ、妖精ラファンパン、魔術師モーロックとパーティを組み、前世で培った便利屋のスキルを活かしながら、冒険者として暮らし始める。', '2023/01/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/096de91f-b350-494c-91f2-79cd8ecff649.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5880fdf8-3a28-4402-bff6-e63bde938dc5', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 2, '100135125', '斎藤さんが出来ること', '隣国の魔王を自ら討伐した王様は、「話が合う」という理由から、首だけの魔王を王宮に迎える。いっぽうサイトウは、自身の失敗で罠を作動させ、迷宮下層に転移させられてしまう。', '2023/01/23 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7ca6b1b5-5c26-49d5-9ae3-bfb9eb4ea85b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1fac969b-eec5-4d1b-a736-5a6bdfde093b', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 3, '100135754', '大迷宮の冒険者たち', 'サイトウが前世から持ち込んだワイヤーカッターが破損。ドンバインというドワーフに修理を依頼する。また、大迷宮で倒したゴーレムが気になったサイトウは、仲間と深層に向かう。', '2023/01/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8eb56526-1393-43a2-89fe-42e6e937d3a6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c27044a-09a4-402c-b6bc-3bba8f44dd83', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 4, '100136173', '新しい時代の幕開け', 'サイトウが発見した新たな区域を目当てに、国中から冒険者が集結。いっぽう、大臣と元魔王の騎士団長には、時を操る魔道士の秘宝を回収するよう、王様から指令が下っていた。', '2023/02/06 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5999bac8-944b-4282-919c-f651c6f58988.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12cfe3d2-0576-40d7-b983-2fec240ffe2b', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 5, '100137016', '忍者と魔女', '魔族を従えたキスルギが、再びサイトウたちを急襲! キスルギは、魔女ラーヴェラを救うため、時を操る魔術師の秘宝を手に入れようと、有力な冒険者を暗殺しているのだった。', '2023/02/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96e7b7ac-1cca-40fb-9efe-b6b2d072733b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('accde84a-f4cd-45a6-9393-bfe5cb689ec9', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 6, '100137362', '老魔術師の記憶', '柱の魔神は強力な光魔法でサイトウたちを見境なく攻撃。その威力はすさまじく、腕利きの冒険者が束になっても防御が精一杯。じり貧の展開の中、サイトウが起死回生の策に出る。', '2023/02/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/65127d10-539b-4588-ae91-d210b250790d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f13c9315-0051-4c54-affb-0d78297c19e1', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 7, '100138002', '極限の接触', '魔法で時を止めたモーロックだったが、自分が何をすべきか忘却。しかし、サイトウはそれさえ見越していて…!? ところが、攻撃に出る直前、ある者の記憶が流れ込んでくる。', '2023/02/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/038720d5-73cb-445b-a010-94fb64ece39a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e57f87b-68e3-4e8a-9aec-80c7591cc71e', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 8, '100139035', '戦いで得たものは?', '王様の力でラーヴェラは救われるが、その対価としてキスルギとプリマスは体の一部を失う。いっぽう、サイトウが転生したのは、モーロックの魔法が誤作動したためと判明し…!?', '2023/03/06 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e5b3156-f533-40e0-983f-5a6865c52243.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3435e5be-a489-4314-bc30-e6e25072634f', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 9, '100140056', '悲しき犬の戦士', 'モーロックが息絶え、町外れの荒野に埋められたと知ったサイトウたちは、いちるの望みを掛けて行動を開始。ところが、モーロックには、思いも寄らない魔法が掛けられていた。', '2023/03/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82ed8e9c-7a07-4505-805c-3043beb927e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4153b901-2ca3-49c6-a525-978da352951b', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 10, '100140548', '魔界の追跡者', 'ラエルザへの思いを語り合うサイトウとモーロックを魔犬が襲撃。劣勢に陥る中、ラエルザとラファンパンが合流するが、そこに魔犬の主で魔王級に強い双頭の悪魔が出現する。', '2023/03/20 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d5b4412-b23b-46dd-bb47-c86632e40f28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18859122-1447-47e6-9047-0475b7f24580', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 11, '100140879', '最終決戦', '双頭の悪魔に強力な魔法をお見舞いしたモーロックは、魔犬に憐れみを感じ、助けようとする。ところがその隙を突いて絶命を免れた双頭の悪魔が復活。悪あがきの魔法攻撃を放つ。', '2023/03/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dff311be-2ff9-4f20-b68e-2e477c5f0855.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93367989-923b-440e-9dc2-56c1070d1353', '5cc20516-280d-4a1c-9847-72e214b2c6f8', 12, '100141885', 'いちばん必要としている人', '【シーズン1 最終話】大迷宮での戦いの後、束の間の日常を取り戻したサイトウたち。しかし、そんなある日、不思議な模様のコップで風呂を浴びたラファンパンが、妖精から人間の姿に変身してしまう。', '2023/04/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60281c4e-a2bc-4372-a555-40e9566478eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2859a1e5-3cfa-4655-88d2-38536b1fb22d', '墓場鬼太郎', '', 'hulu', 'hakaba-kitaro', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/928b8399-0d22-4473-a7f3-821cfa62ac90.png?w=331&h=447&p=t', 'hulu', 2008, 0, 1, 'FINISHED', NULL, 3710, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f6561440-bafe-4d92-8247-61d7f0258ed8', '2859a1e5-3cfa-4655-88d2-38536b1fb22d', 'hulu-hakaba-kitaro-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e5f6369-7f5f-4b19-8a82-457a6df116f4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b962196-dcec-4c56-be8e-be2954f5df36', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 1, '100172419', '鬼太郎誕生', 'ある病院で入院患者が幽霊になった。この原因究明を託されたのが会社員の水木。調べていくと“幽霊族最後の生き残り”と称する夫婦に行き着いた。しかもその幽霊族は、死に瀕しながらも妊娠しているという。会社に真相を報告するべきか迷っていると、「病院にいた幽霊が死んだ」との連絡が入った…。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e5f6369-7f5f-4b19-8a82-457a6df116f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f351ddd-e9fd-419b-ba60-16671a21f58a', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 2, '100172420', '夜叉 対 ドラキュラ四世', '永い眠りについていた夜叉の墓が暴かれた。時を同じくして、吸血鬼ドラキュラが日本にやってきた。夜叉と吸血鬼がひとりの獲物を奪い合う! その獲物とは、ある会社の社長、水木に幽霊患者の原因究明を命令した張本人であった。行方不明になった水木のせいで、社長は倒産寸前の憂き目にあっていた。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fbf0860-6b92-42fc-86e1-0d40994d4b1f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e748c22-7624-45b9-bfb1-73669233e1dc', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 3, '100172421', '吸血木', '地獄から戻ってきた水木。そんな水木とひょんなことから出会った歌手･トランプ重井は、鬼太郎という不吉な子供 の存在を知る。ある夜、ねずみ男が重井に吸血木の種を植えた。人間が木になるという種で、ねずみ男はこの種で金儲けを企んでいた。怯えるトランプ重井の身体は、次第に木になっていく…。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a22d131a-6682-402e-b16a-361f758a3189.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8f2f862-a4e4-4ca2-a8df-d234ea792bc8', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 4, '100172422', '寝子', '鬼太郎が恋心を抱く女の子･寝子。鬼太郎には怪しい影が忍び寄っている。誰かが鬼太郎を貶めようとしているのだ。寝子の夢である歌手への道。鬼太郎はそれを実現させるために尽力する。トランク重井の支援もあり、一気にスターに上り詰める寝子。しかし、何者かが寝子のステージにドブネズミを放つ。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc64c333-94e5-4506-9874-5cf6535392aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9a3a295-48e5-4065-8336-366fbf5dae12', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 5, '100172423', 'ニセ鬼太郎', '鬼太郎の初恋の相手･寝子が死んだ。失意の底に落ちた鬼太郎は寝子に会いに地獄に行こうとするが、何者かにチャンチャンコを盗まれる。犯人はニセ鬼太郎だ。そのチャンチャンコで地獄をさまようニセ鬼太郎は、ねずみ男と画策して大金をせしめようと企む。目玉親父は地獄を訪れ、寝子を連れ戻そうとするが…。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52f4ebb2-f633-4fb9-a0ab-0d61ea924f34.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09563f7a-ab8e-4996-9ce6-d6fd259a0f9c', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 6, '100172424', '水神様', '鬼太郎は神と崇められている水神様を侮辱する。鬼太郎を追って東京にやってきた水神は近代社会を大パニックに陥れる。しかも水神は“水”なのでどこに潜んでいるのか分からない。鬼太郎はなすすべもなく…。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b10768bc-07d4-4981-bb7b-a98cc5b83d06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65c0b190-d3de-4ece-acc0-41aa145e2ba6', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 7, '100172425', '人狼と幽霊列車', 'ガマ令嬢を恋慕する謎の紳士とねずみ男。その恋路を邪魔した鬼太郎は、ふたりの手によって、海底へと沈められる。鬼太郎、死す…。ところが、その夜、鬼太郎から呪いの小包が届く。いったいどこから? そして、幽霊列車が走り始める…。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d78538a6-4566-4157-a199-f31ab3786c64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('929b1317-a3d1-4b88-9cc2-bca96f46c0a3', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 8, '100172426', '怪奇一番勝負', '裏社会を生きる金丸の家に幽霊が住み着いた。金丸は幽霊の正体･鬼太郎を冷蔵庫へ閉じ込めて退治する。だが、そのとき切り落とした鬼太郎の片手が、復讐のために動き始める。鬼太郎の手は、闇夜の家中を徘徊し始める…。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7f1cca5f-4e59-444f-a46a-643022916d3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41fc33b9-5ecd-404c-8925-0058a302fb75', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 9, '100172427', '霧の中のジョニー', '鬼太郎は政府から、吸血鬼ジョニーを退治するよう依頼された。一方、ねずみ男はジョニーに雇われ、鬼太郎退治を命じられる。ニヒルで冷徹なジョニーは、鬼太郎をいとも簡単に殺してしまう。それを目にしたねずみ男は…。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa7d4dbc-c12e-4322-8862-525d540710cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9390b80d-3e48-440f-953a-7c4f0ec401ef', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 10, '100172428', 'ブリガドーン', '台風のような超常現象･ブリガドーンが東京を襲った。そこには妖怪だけが暮らす世界があった。唯一取り残されてしまった人間･水木一家は、貧しかった人間社会では味わえなかった楽しさを体験していく。そして、奇怪な騒乱の一時が始まる。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51904398-f4c0-4a90-bc53-96e23614f7e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea7a4f37-2d0e-4367-912f-de9592a1098f', 'f6561440-bafe-4d92-8247-61d7f0258ed8', 11, '100172429', 'アホな男', '【最終話】鬼太郎は“あの世保険”という保険詐欺を始める。ねずみ男は不老不死の薬を売り歩く。そんなふたりの口車に乗せられた権力者、金持ち、貧乏人が、次々に地獄にやって来る。生きる幸せとは何なのか…そして物語は終焉を迎える。', '2024/03/01 00:00:00', 1367, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a9365cf-8d5e-4947-8417-0e1be7c6a08e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8ccab718-7eaa-41ee-8ec0-dba25115828e', '宝石の国', '', 'hulu', 'land-of-the-lustrous', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97889fb6-924c-4555-9635-b1d4a97112ef.jpg?w=331&h=447&p=t', 'hulu', 2017, 3, 1, 'FINISHED', NULL, 98707, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f86d5ed1-9879-48e3-8a18-37507d1dfb3b', '8ccab718-7eaa-41ee-8ec0-dba25115828e', 'hulu-land-of-the-lustrous-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbcd3435-d4c0-4a07-9126-47e28f581d84.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6806c718-baf6-4a6b-b6fb-c2e5b83df3c0', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 1, '100008453', 'フォスフォフィライト', '宝石たちの中で最年少のフォスフォフィライトは、硬度三半とひときわ脆く、靭性も弱くて戦闘に向かない。また、他の仕事の適性もない。そのくせ口だけは一丁前という、まさに正真正銘の落ちこぼれだった。そんなフォスに、三百歳を目前にしてやっと「博物誌編纂」という初めての仕事が与えられる。', '2017/10/25 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbcd3435-d4c0-4a07-9126-47e28f581d84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ae3b45a-8629-40b1-8b15-2282499bb25b', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 2, '100008454', 'ダイヤモンド', '博物誌編纂のため聞き込みをしているフォスは、最近ダイヤモンドが新しい戦い方をしていると耳にする。ダイヤに会いに行ったフォスだったが話の途中で月人に襲われてしまう。その時ダイヤとフォスの危機に駆けつけてきたのは…。', '2017/10/25 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb423d49-44da-4317-beca-aa8a5b1058ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc0800f8-557d-4dd0-97f2-b0e292f5c740', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 3, '100008455', 'メタモルフォス', '月人が落としていった巨大カタツムリに吸収されてしまったフォス。フォスを救おうと戦うボルツとダイヤは苦戦を強いられるが、ダイヤの機転によって巨大カタツムリを退ける。しかしどこにもフォスの姿が見つからなかった。', '2017/10/25 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c66f6059-057d-48f3-af3a-3a18d622fd0a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6583fc07-f8c4-4db9-874e-afdc53ffc9d0', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 4, '100008456', '魂･肉･骨', 'ダイヤとシンシャの活躍によって再生したフォスはナメクジと会話ができるようになっていた。またもやシンシャに助けられたフォスは、シンシャに何をしてあげられるか悩んでいた。そんな中ナメクジはフォスを海へと誘うのだが…。', '2017/11/01 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a5061027-0d64-4081-b3ec-aaef90909234.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12c6595c-9d92-4bd7-ad49-048c8a3d87ee', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 5, '100008457', '帰還', '海へ出たフォスはウェントリコススによって月人に引き渡されそうになっていた。ウェントリコススもまた弟のアクレアツスを人質に取られ、月人に脅されていたのであった。フォスを引き渡したウェントリコススであったが、月人は更なる要求を突き付ける。', '2017/11/08 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0627539e-13db-4dc0-87ee-d3c5d3f488cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfe1a94e-010a-4fb5-836e-8a751dfb0d43', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 6, '100008458', '初陣', '海から戻り足が速くなり、月人と戦いたいと申し出たフォスは、アメシストの戦闘補佐をすることになった。そして補佐について3日目、ついに月人との初陣に臨む。', '2017/11/15 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f941fc59-ec16-47e3-9b28-ac2bbcbdd5e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1bfe82a-34d3-444a-8fdc-9b542bdaf7d1', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 7, '100008459', '冬眠', '季節は冬に変わり、宝石たちは冬眠に備えていた。そんな中フォスだけは冬眠をせず、冬担当の宝石と一緒に行動することになった。冬の仕事をこなすフォスであったが、ある日突然流氷に話しかけられる。', '2017/11/22 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1cb801c-03d1-4265-9e88-57bc3b3999b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb2d7074-f9ed-4368-bb7c-4cff6a36a153', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 8, '100008460', 'アンタークチサイト', '両腕を失ってしまったフォスは緒の浜で腕の代わりを探すことに。良い素材が見つからなかったので、仕方なく金をはめてみたが、腕から外れなくなったどころかフォスが合金に飲み込まれてしまう。そんな中月人の襲来を受けてしまう。', '2017/11/29 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05b8e00a-5f2f-4674-ac93-aefc1961889c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ab7ee4a-b099-4434-b19c-ddc4058949d1', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 9, '100008461', '春', 'アンタークが連れ去られてから一冬越して、他の宝石たちも冬眠から目覚め始めていた。すっかり戦闘にも慣れたフォスは、あんなに憧れた「戦い」が今は危険な作業になっていることを悟り始めていた。', '2017/12/06 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bdf5a6f5-e4e3-419e-a835-ffb48fe4ae63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ea9d242-aeda-4284-a9b8-1b3d453c1a4e', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 10, '100008462', 'しろ', 'フォスはボルツとペアを組み行動を共にすることになった。そんな中現れた犬の姿の新型月人に遭遇する。勝てる見込みがないと撤退し、金剛先生の元へおびき寄せる作戦をとったが、出払っているはずの校内にダイヤが残っていた。', '2017/12/13 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/674c1c8f-bb90-4091-8085-461d69b0965c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a9b7812-5646-4920-a30b-ed36200275cc', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 11, '100008463', '秘密', '新型月人との戦闘を繰り広げる宝石たちであったが、攻撃をしても分裂を繰り返す相手に苦戦を強いられていた。そこに現れた金剛先生は新型月人に対して思わぬ反応を示す。', '2017/12/20 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/718d69c4-2dfe-4f4b-b0c5-902ec7414041.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d356d58f-2f5a-448f-bffd-7ae7dade3907', 'f86d5ed1-9879-48e3-8a18-37507d1dfb3b', 12, '100008464', '新しい仕事', '【最終話】新型月人との戦闘からフォスは金剛先生と月人の関係に疑問を抱き始めていた。そんな中久しぶりに眠りから覚めたパパラチアに相談を持ちかける。そしてフォスはある決意を固めていた。', '2017/12/27 00:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ade38f7-a275-47a2-a32b-05e571e2cd57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('baebe126-6a06-4c2a-b967-db9b1cf5ee12', '抱かれたい男1位に脅されています。', '', 'hulu', 'the-most-huggable-man-has-threatened-me', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d42fe018-2cd8-4e63-96aa-adecc6d78580.jpg?w=331&h=447&p=t', 'hulu', 2018, 3, 1, 'FINISHED', NULL, 101381, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('44a1290e-ae15-4df9-9826-68371ede68f1', 'baebe126-6a06-4c2a-b967-db9b1cf5ee12', 'hulu-the-most-huggable-man-has-threatened-me-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96e3068b-63de-4a39-8b77-9a6c90d3d06f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f5754de-e825-4fa5-86ef-70846ed40501', '44a1290e-ae15-4df9-9826-68371ede68f1', 1, '100133686', '芸能界は喰うか喰われるか。', '5年連続で“抱かれたい男1位”だったベテラン俳優･西條高人がついに首位陥落。その座を奪ったのは新人俳優･東谷准太だった。映画「真昼の星」で東谷と共演することになった高人は敵意剥き出しで接するが、東谷は天使力全開の笑顔で懐いてきて――。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96e3068b-63de-4a39-8b77-9a6c90d3d06f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4342442-754a-431f-ba4e-8a55a059c819', '44a1290e-ae15-4df9-9826-68371ede68f1', 2, '100133687', 'あいつ、もう俺に飽きやがったのか。', '東谷の純粋な気持ちに負け一夜を過ごしてしまった高人だったが、いつの間にか二人は自然と一緒に過ごすようになっていた。東谷の部屋には高人の歯ブラシ･部屋着が用意され、高人の毎日の送り迎えや料理もする東谷。そんなある日、あんなに懐いてきていた東谷が急によそよそしい態度をとってきて――。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2713190e-cd0f-41d4-bbcf-50770808063c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a71477fd-cc45-4acd-ba3d-5a68fb8bbf52', '44a1290e-ae15-4df9-9826-68371ede68f1', 3, '100133688', 'チカン、ダメ、ゼッタイ。', '映画「真昼の星」の撮影や宣伝活動で東谷と高人は忙しい日々を過ごしていた。やがて撮影はクランクアップを迎える。「こいつに脅かされ続けた日々も終わる…」高人は准太と一緒に過ごした時間が終わることに寂しさを感じていた。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6cb9f8e-3cd6-4a8d-be38-0fd7acea26e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c152b3ec-e110-4cdb-807f-f9b400c0553d', '44a1290e-ae15-4df9-9826-68371ede68f1', 4, '100133689', 'ハメられたああぁぁ。', '主演男優賞を受賞した東谷は仕事が殺到し、多忙な日々を過ごしていた。一方高人は、毎日会いに来ると言っていた東谷が電話すらかけてこないことに不機嫌になる。そんな時、突如東谷が現れ高人は無理矢理車に押し込まれてしまう。車内には不穏な空気が流れていた。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c206ac7-1bdd-4853-a913-b6a35e473aba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77702fd9-5ece-43f4-b897-6d0eddbb1901', '44a1290e-ae15-4df9-9826-68371ede68f1', 5, '100133690', '俺の女にしてあげますよ。', '舞台「紅葉鬼」で東谷と同時期にデビューした綾木千広という俳優と共演することになった高人。初日の顔合わせにも来ない生意気な綾木に業界の厳しさを教えるため、厳しく稽古に挑む高人。そんな高人に苛立ちを感じた綾木は、弱みを握ろうと高人を飲み会に誘う。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81e3bb23-eb2b-45c6-858b-2b7c9dab094a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa720518-f72f-4bc2-a45d-365bc5922d59', '44a1290e-ae15-4df9-9826-68371ede68f1', 6, '100133691', 'なんでコイツとホテルで一緒に…まさか…いやいやいやないよな? そんな…そん…。', '泥酔した高人は綾木と一夜を共にしてしまった。翌朝、携帯を見た高人は一晩中東谷から連絡が来ていたことに気づく。動揺を隠しきれない高人は東谷といつも通り話すことができず、嘘をついてしまう。そんな中、怒りに満ちた表情の東谷が現れ、綾木と対面することになるが――。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1fef7039-2b3a-4784-8625-1cd7ce41ca79.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee03db31-363b-4914-adc5-e729fb73157a', '44a1290e-ae15-4df9-9826-68371ede68f1', 7, '100133692', '好きでいてもいいですか。', '東谷と高人が再会した映画「真昼の星」の撮影の一年前。東谷の役者デビューとなったドラマ「太陽の小瓶」の現場で二人は出逢った。撮影が進み高人と触れ合う中で、東谷は高人に嫌われているのではと感じる。それと同時に、今まで感じたことのない感覚を覚えるのだった。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa9c3a80-b967-4a3c-ad8e-ddfd80b771fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0114beb1-f407-460b-958c-8672208f8ab8', '44a1290e-ae15-4df9-9826-68371ede68f1', 8, '100133693', 'ず、ずらすな、海パンずらすな。', 'ハワイでのCM撮影を終えた高人は、残りの滞在期間を休養にあてるべく海辺でくつろいでいた。そんな時、雑誌の撮影でハワイに来ていた東谷と出会う。誰にも気づかれず海辺でデートが出来ることを喜ぶ東谷だったが、偶然綾木と成宮とも出会ってしまい、結局四人行動となってしまう。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cba80fe0-5618-4b53-bf46-0471d369c96a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e499b20-5bfc-46d9-9cab-e95bcd154924', '44a1290e-ae15-4df9-9826-68371ede68f1', 9, '100133694', '……仲がいいことで。', '舞台「紅葉鬼」の本番も近づき、稽古やTV番組出演で高人は忙しくしていた。そんな中ふと1年前の東谷との出会いを思い返す高人。新人の頃の東谷はいつもどこを見ているかわからない目をしていたのに、今は強い眼差しで自分の側にいる。高人は様々な感情を抱きながらも、舞台「紅葉鬼」初日の幕が開けるのだった。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fcedb78-9300-45eb-9051-cd946178f170.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d50d1eb0-12a7-4936-9606-07d99b6e9113', '44a1290e-ae15-4df9-9826-68371ede68f1', 10, '100133695', '別れるぞ、チュン太。', '「真昼の星」の続編ドラマの制作が決定し、再び高人と一緒に仕事が出来ることを喜ぶ准太。一方、准太と高人のスキャンダル写真を撮るため、カメラマンの長谷川が二人に迫っていた。しぶとく二人を追いかける長谷川に気づかず准太と高人は決定的な瞬間をおさえられてしまい――。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b293cfbe-78d8-454f-a07e-a769fe83da9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('071c6260-30fc-4761-b461-cd4bb5687b92', '44a1290e-ae15-4df9-9826-68371ede68f1', 11, '100133696', 'そんなに俺に惚れてんなら、飽きるまで抱かせてやるよ。', '准太と高人のスキャンダル写真が掲載された週刊冬文がついに発売された。「禁断の愛」疑惑で高人は世間の注目の的になってしまう。しかし准太の俳優生命を守る事に必死の高人は、自分の事など気にせず取り引きをした長谷川からの連絡を待っていた。そんな中、長谷川の前にある人物が現れる。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/123f69b1-14af-4d3e-9c51-d8d9498bbdf6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79d90043-42c7-48b0-b3a2-e61f83b45766', '44a1290e-ae15-4df9-9826-68371ede68f1', 12, '100133697', 'mi tesoro。', '准太と別れ日々の仕事を淡々とこなす高人。ある日佐々木家の晩御飯に招待された高人は、准太への想いを初めて佐々木に吐露する。翌日、エレベーターで偶然准太と会った高人は関係が終わってしまったのだと改めて実感するのだった。一方で准太は、ある策を練っていて――。', '2023/02/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1849cbbb-09b5-4dc0-b3dc-1c8185ab1bef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b054824e-3e2e-41c0-b4ea-a8b2ca82b30a', '44a1290e-ae15-4df9-9826-68371ede68f1', 13, '100133698', 'ふっふっふ～ん♪ ふっふっふ～ん♪ ふっふっふ～ふふ～ん。', '【最終話】准太とクリスマスイブを一緒に過ごす約束をした高人。当日のプランを立てると准太に啖呵を切ったものの、仕事ばかりしてきた高人はプランニングが浮かばず、結局クリスマスイブになってしまう。焦る高人だったが、現場終わりに迎えにくるはずの准太の姿が見当たらず、佐々木さんと探しに行くことになり――。', '2023/02/02 00:00:00', 1406, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e32e4ade-aa62-4bd8-b8db-0ba601bc2199.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('bd805aef-31f3-4e11-8008-362b81e5c3fa', '放課後ていぼう日誌', '', 'hulu', 'teibo', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83ad1dfc-4b0f-411a-b734-1e6abbe4b78f.jpg?w=331&h=447&p=t', 'hulu', 2020, 1, 1, 'FINISHED', NULL, 109019, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 'bd805aef-31f3-4e11-8008-362b81e5c3fa', 'hulu-teibo-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e035d2df-ca0b-406b-ba85-e78d6f682c39.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e64e3ea-0069-4d6d-b211-d8f782661234', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 1, '100054452', 'ていぼう部', '田舎に引っ越してきたばかりの新入生･鶴木陽渚は手芸が好きなインドア派。入学前のある日、海沿いの道を歩いていると、堤防の上でふらふらとしている人影を見かけます。熱中症かと思った陽渚は慌てて駆け寄るのですが、その女性は「釣りをしていた」との事。黒岩と名乗る彼女は、陽渚と同じ高校の先輩だと言うのですが…。', '2020/04/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e035d2df-ca0b-406b-ba85-e78d6f682c39.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88a507b3-3a0b-4b53-84e7-e78fb347708c', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 2, '100054693', 'リールとキャスティング', '成り行きで入った「ていぼう部」で、釣った魚を自宅に持って帰った陽渚。田舎の生活になじめるか不安だった両親も、その様子を見てひと安心です。陽渚は釣れた時の感触に感動し、おいしい魚が食べられる事もあって、せっかく入った部活を楽しもうと意気込みます。しかし今日は体力測定の日。運動が苦手な陽渚は…。', '2020/04/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ecb00dce-141e-4afa-a47f-ad40e59eab66.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71e99395-e6c6-43c9-8ffa-ae41209ddc0e', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 3, '100054973', 'マゴチ', '黒岩から「明日はマゴチを釣りに行こう」と伝えられた陽渚は、パソコンを使ってマゴチについて調べてみました。砂地に生息し、砂に擬態して小魚を食べる魚のようです。翌日、砂地のある近くの海水浴場に行くことになりました。しかし重い荷物を担いで徒歩で移動するにはつらい距離です。そこで先輩たちが持ってきたのは…。', '2020/04/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2a75495d-daff-4939-bb7e-45f2c3502f8d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eab68d61-ff18-43da-a6b5-f48e2d66ece4', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 4, '100060757', 'エギング', '駅で待ち合わせしたていぼう部の4人、今日は電車に乗ってお買い物です。陽渚が帽子やアウトドア系の服を持っていないため、皆で買いに行く事になったのでした。しかし、黒岩が持っているヤッケは陽渚と夏海には可愛くないと不評の様子。お店に着いた陽渚は、さっそく女子高生らしい可愛い服を探すのですが…。', '2020/08/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6fd1dfac-d989-43ae-9b9e-38f83af4baa1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e9c4b153-00c9-45d3-a883-82eebf5d4f43', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 5, '100061277', '潮干狩りと顧問', '陽渚は、イカ墨で汚れたウェアがすっかり綺麗になってご機嫌な様子。そもそもなぜ制服を着て釣りをするのか気になり大野に問いかけると、ていぼう部は昔から学校のジャージか制服で活動する決まりがあるとの事。ダサいジャージで釣りをするくらいなら制服の方がマシだと思っていた陽渚ですが、黒岩に連れて行かれた先は……。', '2020/08/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c1e6f4d-7192-4e08-9d30-98566b3f9566.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f498e8d-1a4e-45b7-9fe0-55ff403b371c', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 6, '100061858', 'アジゴ', '突然「アジゴのから揚げが食べたい!」と部室に現れたのは、顧問の小谷先生。財布がすっからかんでお腹を空かせている様子。下ごしらえが大変だと反対していた黒岩ですが、ふと何かを思いつき、部室では絶対にビールを飲まない事を条件にアジゴ釣りを許可します。準備の為、陽渚と夏海が先生の車に乗って向かった先は……。', '2020/08/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f07286ea-b174-4952-860c-9b7d436a1d9b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ede764a-2578-4711-92e0-3763f0d812df', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 7, '100062335', '穴釣り', '祖父の釣り道具の中に面白い形の物があり、気になっていた陽渚。大野に聞いてみると、それは「ブラクリ」と呼ばれる根魚を釣るための仕掛けだとの事。黒岩からもブラクリで釣れる「ガラカブ」という魚の味噌汁が美味しいと聞いた陽渚は、一気にテンションが上がります。皆でブラクリを使った穴釣りをする事になったのですが…。', '2020/08/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ecdb7fd5-ba1e-4499-bea6-3d09bd20cc0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('18b20241-da62-4412-8491-a4ab96122b7b', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 8, '100062946', 'テナガエビ', '梅雨、雨が降り続きしばらくていぼう部の活動が出来ていない陽渚と夏海は、釣りがしたくてたまらない様子。今週一度も部室に行っていない為、学校にも部室があれば良いのに。と二人が話していると、突然黒岩が現れて「学校にも部室がある」と言い出します。ちょうど今から向かうと言うので、陽渚たちがついて行くと、そこは……。', '2020/08/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f23d079f-a081-4bbb-9a23-27e3264178e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2fcbcbfe-75fe-4cdc-8034-2b09026f7314', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 9, '100064044', '備えとアオサギ', '学校での救命講習会に参加した陽渚と夏海。陽渚は人工呼吸の練習が上手く行かず、人を助けられる自信がない、と不安げな様子です。二人が渡り廊下を歩いていると、どんよりとした大野が現れました。今日は部活でも着衣水泳の練習があるため、泳げない大野は気が重い様子。放課後、プールに集合したていぼう部の面々でしたが……。', '2020/09/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84cde198-b3b2-4f6a-9e1b-a64be168d895.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('448781da-ac7c-422f-8039-6bbec217ebc3', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 10, '100064463', 'のべ竿', '夏真っ盛り、部室の前に集合したていぼう部の面々ですが、黒岩はやる気がない様子。一方、陽渚はせっかく暑い中部室に来たので、何か釣りたいと乗り気です。夏海はルアーでのシーバス釣りを提案しますが、大きいものだと1メートルを超えると聞いて却下する陽渚。そんな中、黒岩はのべ竿でのウキ釣りを提案するのですが……。', '2020/09/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/747afe68-f00b-4e08-947d-f7d4f554d133.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b4d1d41-baef-47d5-9a23-441bbb268fdf', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 11, '100064786', 'キス', '放課後に、のべ竿でウキ釣りをしていた陽渚と夏海ですが、釣りあげたのはバリと呼ばれる魚。正式にはアイゴという、ヒレに毒がある危険な魚です。黒岩は「バリはうまい」と声をかけるのですが、夏海は磯臭いからとリリースしてしまいます。バリを食べたい黒岩は、美味しく食べられるよう大野に処理をお願いすると……。', '2020/09/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cbaf83df-c8ba-45df-ac82-6d6d365735a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19df011b-0e33-42fc-8384-5780183abb15', '0c62afb5-9c2a-4a26-9b5b-5d5f3e721ea4', 12, '100065297', 'これから…', '【シーズン1 最終話】放課後、夏海が部室へ向かう準備をしていると、陽渚から「先に部室行くね!」とメッセージが届きます。陽渚はずいぶんはりきっている様子で、誰よりも早くキス釣りの準備を終わらせていました。昨日釣れなかった原因を調べてみたところ、「虫エサと疑似餌では決定的な違いがあった」と語る陽渚。その違いとは……。', '2020/09/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9b1caf96-4974-47e9-b60c-91a9ba1c92c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('79eb4bbc-af33-4ccb-af21-0acde448531b', '放課後少年花子くん', '', 'hulu', 'after-school-hanako-kun', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6219ce0c-bd3e-4e76-bdf5-ae2df936cc4e.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 159074, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6db51982-0656-4b77-9e03-1a356c92f600', '79eb4bbc-af33-4ccb-af21-0acde448531b', 'hulu-after-school-hanako-kun-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/493e00ca-cb22-4cae-895f-06c852e7240e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('005e7c91-7b78-435d-9155-fcd4f774632b', '6db51982-0656-4b77-9e03-1a356c92f600', 1, '100162107', '1日目', '其の一「放課後の花子くん」花子くんの助手として来る日もトイレ掃除の寧々。せめて楽しくトイレ掃除ができるように、花子くんがアイディアを出したり、友人の葵たちに相談するも、当てにならない答えばかりで……? 其の二「もっけの野望 Mokke be ambitious.」学園の「ようせいさん」こと、怪異･もっけ。その小さな体には「七不思議になりたい」という、大きな野望が秘められていた。花子くんを亡き者にしてでも、七不思議に取って代わろうとするもっけたち。果たして彼らは七不思議に相応しいのか、花子くんによる面接が始まる。', '2023/10/13 12:00:00', 600, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/493e00ca-cb22-4cae-895f-06c852e7240e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('11262df0-9e1b-4bdd-9269-9bd6a4d62b3a', '6db51982-0656-4b77-9e03-1a356c92f600', 2, '100163204', '2日目', '其の一「こっくりさん」蝋燭の炎が怪しく灯る教室に、茜の呼びかけで寧々･葵･檸檬が集まった。茜は、こっくりさんに興味を見せた葵のために「最高のこっくりさん」をするという。最高の10円玉探しなど、周到な準備を経て始まった儀式。想像以上に本格的な様子に寧々が危険を感じると、10円玉が動き出して!? 其の二「ミツバの友達大作戦」「……友達が欲しい」と、放送室の片隅で切実なつぶやきを漏らすミツバ。どうやら雑誌の特集記事に影響を受けたらしく、いつになく落ち込みが激しい様子。それを見かねた夏彦と桜が相談に乗るが、ミツバの希望は叶わない。そして残る相談相手はつかさのみ。ミツバの望みを聞いたつかさの返答は……。', '2023/10/20 12:00:00', 600, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eec1d285-1a49-4bf3-9f2c-3e5d08ee6bf9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43eb16b7-45f7-46ad-96ce-58ff8fa36910', '6db51982-0656-4b77-9e03-1a356c92f600', 3, '100163942', '3日目', '其の一「怪異風邪」一見ふつうの風邪のようで、怪異だけが引く風邪、人呼んで「怪異風邪」。花子くんや、土籠、ヤコが次々と怪異風邪にかかり調子を崩すが、花子くんは何十年ぶりに風邪を引いたと嬉しそう。テンションが上がった花子くんは、光に見せて来ると保健室から飛び出すが!? 其の二「もっけが家にやってきた」由緒正しき源家の長女･源てぃあら5歳。路地でボロボロのもっけを拾った彼女は、そのもっけを自分の“ドレイ”に任命し、お世話を始める。まずはもっけに兄の輝と光をを紹介するが……?', '2023/10/27 12:00:00', 600, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/203cfdcb-1ad9-479c-97e7-9fd43b795acf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('070b011d-2fb0-4dbb-b5e4-fe0cfd1ac403', '6db51982-0656-4b77-9e03-1a356c92f600', 4, '100164554', '4日目', '其の一「トゥルー･オブ･もっけ」ある日、気がつくと、八尋寧々はもっけになっていた。寧々を取り囲むもっけたちと、そこに現れた偉大なるもっけ･えるだーもっけ。えるだーもっけの導きで、寧々は世界の心理に触れる。歴史を揺るがす事実に動揺しながらも寧々はもっけたちからの逃走を図るが……。其の二「かもめモンスター保育園」ここはモンスターの卵が通う、“かもめモンスター保育園”! ハロウィンで活躍する立派なモンスターにすべく、研究員たちは日夜モンスターの育成に励んでいる。そこにやってきたのは見習いのN研究員。S研究員の案内で施設を見学する彼は、3組の研究員とモンスターと出会い……。', '2023/11/03 12:00:00', 600, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/905fc9fb-5264-4930-bb41-465751208e5f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87cfece8-5abf-41af-b247-528cce972f50', '6db51982-0656-4b77-9e03-1a356c92f600', 5, '100201328', '5日目', '其の一「悪夢」最近、悪夢ばかり見ると困り果てている寧々。花子くんと光に相談すると、参考のために他のみんなにも、普段どんな悪夢を見ているのかを聞いて回ることになる。そこで飛び出すのは個性的な悪夢ばかりで……⁉ 其の二「コンビニ」夜の怪異討伐帰りの輝は、コンビニの前で葵と出会う。眠くてテンションが高くなっている輝は、葵にあるものを一緒に作らないかと提案するが、露骨に嫌な顔をされてしまい……。', '2024/10/08 12:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cedb3d43-737e-47df-9581-87baf52b7834.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4f13680-4da0-4187-80e3-606904d0eab7', '6db51982-0656-4b77-9e03-1a356c92f600', 6, '100202581', '6日目', '其の一「夏の魔物 ～地縛少女花子さん～」呪いの不思議道具『夏の魔物』が暴走して、花子くんが女の子になってしまった! 寧々は1日くらいで元に戻ると知り、今のうちに女の子っぽいことをしようと提案する。そこに光がやってきて……。其の二「夏の魔物 ～再来～」花子くんが埋めた『夏の魔物』を掘り起こし、放送室に持ち込んだつかさ。『夏の魔物』はまたもや暴走して、今度は桜を男の子にしてしまう。その様子を見た夏彦が騒ぎ始めて!?', '2024/10/15 12:00:00', 601, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc48c262-7863-4bab-b778-66dd1f0c0736.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80925242-e2e6-4ad1-ab9b-ec11f45e5517', '6db51982-0656-4b77-9e03-1a356c92f600', 7, '100203091', '7日目', '其の一「放課後もっけ」宿直室に泊まっていた土籠は、もっけたちが大暴れする『放課後もっけ』という深夜番組を目にする。土籠は、遊びに来たヤコや花子くんと一緒に観るのだが、それはあまりにも奇妙な番組だった。其の二「放課後の喫茶店」彼岸と此岸の狭間にある喫茶店の留守を預かり、マスターとなった花子くん。寧々と光にも手伝ってもらい、様子を見に来た土籠を接客することに。だがそのあまりのダメっぷりに土籠は……。', '2024/10/22 12:00:00', 600, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fd48e57-022d-41b4-bf17-d114179997f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('846e406b-6719-42b5-bb36-6e15eb34c493', '6db51982-0656-4b77-9e03-1a356c92f600', 8, '100204040', '8日目', '【最終話】「ゴーストホテル」真っ暗な森を彷徨い、寧々がたどり着いたのは、不気味な『ゴーストホテル』だった。中にいる従業員や客人は奇妙な人たちばかり。さらに何か大事なことを忘れている気がして……。', '2024/10/29 12:00:00', 600, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a75ddcb3-f9f9-4828-a362-0cf5f315a3bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e30c7d96-02bb-4fc0-8ac2-6749917c40a3', '放浪息子', '', 'hulu', 'wandering-son', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0d65263b-a111-40c2-9014-4590ed3041a6.jpg?w=331&h=447&p=t', 'hulu', 2011, 2, 1, 'FINISHED', NULL, 10935, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 'e30c7d96-02bb-4fc0-8ac2-6749917c40a3', 'hulu-wandering-son-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/922a8f90-52d5-4471-96e7-46c674056db4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('37384666-6889-4a97-9aa4-3d8e435a9d9c', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 1, '100155882', 'おんなのこって なんでできてる? ～Roses are red, violets are blue～', '女の子になりたい男の子･二鳥修一と、男の子になりたい女の子･高槻よしの。小学校で出会い、お互いの秘密を知った二人は、共通の悩みを相談し合えるかけがえの無い存在になっていた。そして、季節は春。中学校の入学式を迎え、着慣れない制服の感触に戸惑いながらも、新たな生活に期待と不安を募らせる二人だったが、ツメエリを着て登校してきた女の子･更科千鶴の姿に目を奪われて――。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/922a8f90-52d5-4471-96e7-46c674056db4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('274f6192-dcad-4c58-a491-c89249fb1ca0', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 2, '100155883', 'きらい きらい 大きらい ～Cry baby cry～', '中学校での新しい生活が始まったものの、よしのとさおりは、修一のことが原因で小学校の頃に仲違いをして以来、ずっと気まずい関係が続いていた。同じ頃、部活動への仮入部期間がスタートし、よしのと千鶴はバスケ部、さおりと佐々はバレー部に入部することに。二人の間に入り、板ばさみになることの多い佐々も、悩みが尽きない。そんな中さおりは、挨拶を無視したという理由で上級生に目をつけられてしまう。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24696e9e-f6ed-45ce-8d89-3a63c4de8a86.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b0b38ab-7dd9-443a-bd70-8cb6cae46d69', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 3, '100155884', 'ロミオとジュリエット ～Juliet and Romeo～', 'クラスでは文化祭の準備が始まり、1年3組では多数決の結果、さおりの提案した“男子が女子の役を、女子が男子の役を演じる”ことになる「倒錯劇」が出し物に決定。よしのの勧めで、修一は劇の脚本を書きはじめるが、同じく脚本を書いてきていたさおりと、担任の税所先生の提案で共同脚本作業をすることに。一方、バスケ部の顧問から、ブラジャーをつけてくるように言われたよしのは、自分の身体の変化に戸惑いを隠せずにいた。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd48a7b4-8682-4f31-b133-2877387a0f57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('674842c1-8ce3-4269-ab76-d4a5b472efe5', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 4, '100155885', '私の名前をあげる ～The sound of your name～', '文化祭の倒錯劇の脚本作業を進める修一とさおり。だが、二人の気持ちが何となくすれ違い、なかなか作業が進展しない。さおりは修一の脚本を「よしのに女の子として愛されたい修一の願望」だと言う。一方よしのは、ユキさんに教えてもらった下着を買おうと、修一を誘って久々に女装&男装デートをすることに。さおりに言われ自分の気持ちを自覚した修一は、よしのにその想いを告げようとするのだが…。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63a941ef-4e61-4b26-90b5-e54e9382158f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b43cc584-8423-4e22-8267-18dac39c1dfe', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 5, '100155886', '夏のおわりに ～Long, long shadow～', '夏休みが始まった。修一たちはさおりの家に集まって、みんなで倒錯劇の脚本制作をすることに。そんな中、偶然さおりの家にやって来た文弥の発言で、修一が時々女装をしていることが千鶴たちに知られてしまう。興味津々で修一を質問責めにする千鶴に、怒って帰ってしまうよしの。自分の為に怒ってくれたよしのの気持ちが嬉しい修一は、よしのへの気持ちに、今度こそひとつの区切りをつけられそうな気がして…。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77df0e4d-cce6-4e35-b6ae-f42122f2e968.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d24cc66e-e061-4c76-8ce2-7a9c9c57ba0a', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 6, '100155887', '文化祭 ～Dream of butterfly～', 'いよいよ待ちに待った文化祭の当日。修一たちのクラスは劇の準備に大忙し。ジュリエットに扮した誠は、ロミオの衣装を見事に着こなすさおりに対して、自分に自信が持てずにいた。本番が刻一刻と迫る中、緊張を紛らわすためにみんなでお化け屋敷に入ったり、人気モデルの麻衣子ちゃんが来ていることが分かって大騒ぎになったり、ユキさんやしーちゃんも見学に来たりと、賑わいを見せる文化祭。そして、ついに1年3組の倒錯劇『ロミオとジュリエット』の幕が上がって――。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eae0c906-bf5d-4036-8277-9a8b3c9906a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc9de5dc-ae96-4b45-b524-44e3e338bdc0', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 7, '100155888', '薔薇色の頬 ～Growing pains～', 'ある朝、修一は鼻の頭にニキビが出来てしまったことに気づく。真穂に「これからどんどん増える」とからかわれ、一日も早く治そうと奮闘する修一だったが、そうこうするうちにまたニキビは増え…。安那にその話をしたのがきっかけで、色々と相談に乗ってもらうことになり、今まで安那に苦手意識を持っていた修一だが、親身になってくれる彼女に、これまでと違う気持ちが芽生え始めていることに気づく。そんな折、修一はさおりと共に、文化祭の倒錯劇での脚本の腕を買われ、演劇部にスカウトされる。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08389f68-b761-40fb-9459-ceb5791f4617.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59f68217-7619-48c2-b67f-83b46b846c6e', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 8, '100155889', '春 ～Brand new me～', '季節は巡り、また春がやってきた。修一たちも2年生に進級し、ずっと学校を休んでいたさおりも久しぶりに登校してくるように。喜ぶ一同だったが、新学期早々のクラス替えで、修一は小学校の時に嫌がらせをしてきた土居と同じクラスになってしまう。一方よしのは、今回もツメエリで登校してきた千鶴に触発され、新たな一歩を踏み出す決意をする。そんな折、真穂から安那と付き合うなら女装するのをやめるように言われた修一は、悩んだ末、安那に「女の子の恰好をするのが好き」だと打ち明ける。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b98826a-4f3d-4f58-a7c2-2c8e34dc2784.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ddf22755-1b4e-4340-909d-75d8a6794fe3', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 9, '100155890', 'かっこいい彼女 ～Green eye～', 'ついに男子の制服を着て登校することに決めたよしの。周りからの反応に照れながらも、どこかふっ切れた表情を見せるよしのを、密かに羨ましく思う修一。一方修一は、ユキさんに一目ぼれした土居からの頼みを断り切れず、土居をユキさんに会わせることに。ユキさんが元･男だということを知った土居は驚くが、同時に、修一が女装したらどうなるのかと興味を持つようになる。その翌日、修一は土居に、女装した姿を見せて欲しいと言われて…。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee1b77dd-7b6e-4e42-82b9-f892b7e55900.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9f594c8c-8d05-4b38-8029-9d0b32c8e4a6', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 10, '100155891', 'ぼくだけ笑われた ～Black sheep～', 'セーラー服を着て登校して以来、学校に行けなくなってしまった修一。真穂も登校拒否になってしまい、修一は自分の行動に責任を感じてしまう。よしのから手紙をもらった修一はようやく登校する決心をするが、クラスメイトには女装のことでからかわれ、土居からも心ない言葉をかけられて、教室に入れず保健室登校になってしまう。一方で、安那も修一の行動に複雑な想いを抱えていた。', '2023/09/26 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee90ef89-5009-4e15-bc6e-159ca9c1c088.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70608e5b-327b-4aa0-ab96-00cbe14883ff', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 11, '100155892', '告白 ～Each season～', '安那に「彼氏、ムリ」と告げられ、気持ちの整理ができない修一。イヤホンからは、以前、誠と一緒に女の子の服を着て録音した自分の声が繰り返し聴こえる。よしのたちは保健室登校を続ける修一を心配するが、文化祭の出し物で修一のクラスは「倒錯劇」をやることに。そんな折、ユキさんは修一に自分の過去を語り始める…。', '2023/09/26 00:00:00', 1382, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79f2527e-4a52-4645-aff9-4cf1b033c090.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('762be193-cd25-4df3-8f37-7638b843cd9e', 'da8b992a-7f45-4a1a-821d-b49fd57f4f5c', 12, '100155893', '放浪息子はどこまでも ～Wandering son’s progress～', '【最終話】文化祭の倒錯劇の脚本を担当することになった修一は、保健室登校を続けながらも、劇の練習に顔を出すようになる。土居は修一の脚本にアドリブを足してアレンジするが、それが意外に好評で、修一は思い切って土居に脚本制作を手伝ってほしいとお願いする。一方さおりは、久しぶりに修一とよしのを自宅に招き、小学生の頃のように女の子の服を着てみないかと修一に問いかける。あの頃には戻れないけれど、それでも……。修一はさおりからもらったワンピースを見つめながら、ぼんやりとそんなことを考える。そしていよいよ、文化祭の日がやってくる。', '2023/09/26 00:00:00', 1371, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c8568cd-b05e-4228-953a-ebf4e16f846c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('54929318-d1b0-4ee8-94c7-1b4eeb0deea9', '亡念のザムド', '', 'hulu', 'xamd-lost-memories', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/643c87f1-ae51-4063-bb99-5a160f6043c3.jpg?w=331&h=447&p=t', 'hulu', 2008, 2, 1, 'FINISHED', NULL, 4177, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e2fdcc09-cb59-4294-86c7-1304fdd104c4', '54929318-d1b0-4ee8-94c7-1b4eeb0deea9', 'hulu-xamd-lost-memories-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c50af4f8-3dd0-4d90-86ad-01f781100c30.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcca69a8-70f5-4ef6-b845-6623145cb689', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 1, '100006012', 'ザムド 陽炎に現る', '油泥海に囲まれた小さな島、尖端島。70年前の戦争で、南大陸自由圏の属国となったこの島で、高校生のアキユキは母親と二人暮らし。別居中の父親は、町の小さな診療所を一人で営んでいる。二人の間を取り持つために、毎朝欠かさず、母親の手弁当を父親の元へ届けるアキユキ。この日も、いつも通りの朝を迎えたはずだったが…。通学途中、友人のハルやフルイチと共に、ある事件に巻き込まれてしまう。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c50af4f8-3dd0-4d90-86ad-01f781100c30.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c11b8c6-33a7-422d-ac83-d08e44a06bb8', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 2, '100006013', '尖端島 思考停止', '通学用のバスが爆破され、右腕に光る物質を宿したアキユキは、ザムドと呼ばれる異形の怪物となってしまった。謎の言葉を残し、意識を失った白髪の少女。アキユキザムドは我を忘れ、暴走する。同じ頃、北政府の軍艦が尖端島領空に侵攻し、ヒトガタ兵器を産み落とした。アキユキという自我を失ったザムドは、ヒトガタ兵器に襲い掛かられ、戦いが始まった。', '2025/12/26 00:00:00', 1547, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b742ff2f-3966-45a3-b5e0-f7bb0270bea5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4feb4457-ebbf-45b4-b22e-9284b287aa5a', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 3, '100006014', '偽装 国際郵便船', 'ナキアミの介抱によって、目覚めたアキユキ。そこは、尖端島から遠く離れた空の上、国際郵便船ザンバニ号の中だった。ナキアミはザムドの力を制御できるようになるまで、船に留まれと言うが、アキユキは自らの身に起きたことを理解できず、尖端島に戻ることを望む。そんなアキユキは、女船長の紅皮伊舟の所を訪れる。アキユキの礼を欠いた態度に、拳を振り上げる伊舟。二人の間が険悪になったその時、一体の飛行ヒトガタ兵器が襲い来る。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69bd93fa-71ea-47d0-a5d9-1efb4521e629.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16c6207c-07f9-453e-aa29-aef579a07fbc', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 4, '100006015', 'この世に響く耳鳴りの数々', 'アキユキのザムド訓練が開始される。ナキアミに案内され、天心様と呼ばれる老婆と面会するアキユキ。「ザムドは何を求めるか」天心様の問いかけに、アキユキは答えを持たずに戸惑う。アキユキがザムド訓練を受けている頃、ザンバニ号に一艘の船が接近する。それは、ナキアミの昔馴染み、ゼーゲンドォという男の乗る船だった。ナキアミはゼーゲンドォとの再会を望むが、伊舟は頑なに聞き入れようとしない。二人は、ついに口論となってしまい…。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c212214-34ae-4740-b743-6063ebf94d60.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f439eea8-9236-463d-a8a4-e328832e01f0', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 5, '100006016', '調停する者 しない者', '伊舟と仲違いしたまま、昔馴染みのゼーゲンドォに会いに行くナキアミ。ザンバニ号に残されたアキユキは、伊舟からナキアミの話を聞く。ナキアミの出自、そして伊舟との出会い…。伊舟は、ナキアミが自分の元を離れ、故郷へ帰ってしまうのではないかと心配していた。一方、アキユキの故郷尖端島では、ハルとフルイチが町の復興作業に勤しんでいた。そんな二人の前に、同級の設楽という女生徒が現れ、寂しさを吐き出す。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53b1fc14-1295-4ed9-9f39-144c475f5f7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad5f5922-e590-40ff-932b-5f48a06b144a', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 6, '100006017', 'ハルと極東自治区', 'ビートカヤックで哨戒飛行をしていたナキアミが、北政府の空爆に遭って間もない被災地で、一体のヒトガタ兵器を発見する。その石化を止めようとして、自らも石に呑まれそうになるナキアミ。アキユキは腕をザムド化させてヒトガタを倒そうとするが、それをナキアミは拒むのだった。その頃、極東自治区の実験体ザムドが目覚め、暴走してしまう。阻止を命じられたのは、ASPスーツの新人パイロット達だった。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/490d4f42-81bd-4728-a4b2-4287139f41a8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e3784671-4ab9-430f-b028-90bfd1c2fd54', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 7, '100006018', '屹立 背負うは命か猫股か', '極東自治区のASPスーツに追い詰められる実験体ザムド。羽を生やし、飛翔しようとする姿に、ハルはザムドの正体を知り、攻撃を阻止しようとする。そんなハルの心は、ザンバニ号のアキユキの元に、手紙として届いていた。極東自治区の遠征研修で、尖端島を離れるというハル。アキユキは、猫股のロッパを連れて行くことを条件に、ハルのいる詰腹峠へ向かうことを許される。だが、その道中、一人の男と遭遇し…。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9eb9045-3c18-4c2d-9195-46b76e205e33.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('86f5413d-fe19-406f-91af-0ef19489852b', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 8, '100006019', '詰腹峠のヒトガタ狩り', '極東自治区の遠征研修で、詰腹峠の鉱山にやって来たハルとフルイチ。消息を絶ったASP小隊の捜索にあたるが、一途にアキユキを思うハルとフルイチに微妙な距離感が出来始める。その頃、アキユキはズイゾとキーオ親子に導かれ、詰腹峠を目指していた。廃坑に架かる橋の上、ついに再会するアキユキとハル。だが、友人であるはずのフルイチは、手にした銃をアキユキに向ける。そこに、新たな人影が現れた。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ffbfbf3-45ba-42b6-b766-2dab57b05199.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1f6209c-ec2a-4228-b63b-7030bbe7ebe5', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 9, '100006020', '水もしたたる角股雷魚', 'ザンバニ号に乗り込んできた髭面の男、角股雷魚。彼は、かつてナキアミに拾われ教練を施されたザムドだった。雷魚の二年ぶりの帰還に歓喜する、ザンバニ号の船員たち。雷魚の持ってきた土産と旅の話に、船内は華やぎ賑わう。同じザムドでも、お荷物扱いのアキユキと違って、船員たちからの人望が厚い雷魚。アキユキはないがしろにされて不貞腐れつつも、ザムドとして自立して生きるという雷魚に興味を引かれていく…。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f382cbb1-a425-4a80-b132-fbc6e04c12d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0750507-6017-4bae-84b2-3651c7c6b345', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 10, '100006021', '過去 重い斬る', '極東自治区の入隊式を終えたハルとフルイチ。ハルは垣巣中佐に呼び出され、軍人としての自覚を持てと諭される。垣巣は、詰腹峠でハルが犯した軍規違反を、フルイチから聞きだしていたのだ。その頃、ザンバニ号では、船員たちが雷魚の写魂機で集合写真を撮っていた。伊舟は、珍しく素直な気持ちを告げるナキアミを驚きの表情で見つめながら、一抹の寂しさを覚えるのだった。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4944093-d4a5-41b3-9844-bfc4018d18e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e843bba-a075-4145-99b1-7f68e3832015', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 11, '100006022', '襲撃 ザンバニ号', '飛来するヒトガタ投下船。腕をザムド化させ、ヒトガタ兵器と戦うアキユキは、ナキアミから受け取ったウツツダネを使って、殺さずに解体しようと試みる。そこに、ザンバニ号目掛けて、新手のヒトガタ投下船が来襲する。船員それぞれのぶつかり合う思いを飲み込むかのように、船内に侵入してくる無数の小型ヒトガタ。ナキアミはそれでもヒトガタ兵器を助けようと奔走するが、過酷な白兵戦を目の当たりにして言葉を失っていく。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1e42a65b-efcc-40fa-a6fb-fa2416126455.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3aa6c525-8fd3-41b7-a164-85ffbe4115f8', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 12, '100006023', '暗闇で咲く花', '荒野に不時着したザンバニ号。進路を絶たれ、途方に暮れるザンバニ号のメンバーたち。そんな中、ナキアミの身に異変が起こる。黒い影のような化け物が現れ、ナキアミの前へと這い寄ってきたのだ。黒い影の去来をきっかけに感じ、過去と決着をつけなくてはいけないと考えるナキアミ。埋葬されるヒトガタ使いの少女に自分を写しこみ、進むべき道を思い固めていく。その頃、尖端島では、フルイチの身にも異変が起こり始めていた。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8aba822e-d558-4bff-97bb-c76c8fdf54be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ecf7dda9-8251-46c6-ad2e-1a5223ffa943', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 13, '100006024', 'タダ裸足デ走ルシカナイ', 'ザンバニ号から旅立ったナキアミとアキユキ。二人は、テシクの村へ向かう前に、アキユキの故郷、尖端島に立ち寄る。久しぶりに、父リュウゾウの診療所へ帰るアキユキ。リュウゾウは、ヒルコの宿った腕を見て、アキユキの身に起きたことを理解する。そして、アキユキに思わぬ人物を引き合わせた。一方、ナキアミと再開したハルは、アキユキを引き連れていったナキアミに、これまでの自分の思いをぶつける。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a2675b4-f908-4d76-88ab-3be2c71e0d0a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff10f0b0-3bc0-462c-b052-a5ae31f0a701', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 14, '100006025', '蒼スギル空', 'アキユキとハルの仲を引き裂くように現れたフルイチ。アキユキに対する積年の恨みと憎しみと嫉妬の情が噴出し、フルイチの身体はザムドへと変貌していく。我を忘れたフルイチを、必死で止めようとするハル。だが、フルイチのザムド化は止まることなく、ハルを飲み込み、アキユキと対峙する。フルイチを止めるためには戦うしかない事を決意するアキユキ。そして、震天動地、ザムド同士の戦いの火蓋が切って落とされた!', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/56f7646a-382b-4b18-82de-8cb64fbb0208.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76ecd90f-01c2-4698-acc2-96592287ea88', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 15, '100006026', 'まま 眠れる魂', 'フルイチとの戦いの後、我を失ったアキユキは、ザムドの面が剥がれぬまま、人買いの男達に捕まってしまっていた。北政府の荒野を連れまわされる中、アキユキの前に不思議な小さい影が姿を現す。一方、アキユキとはぐれ一人テシクの村を目指していたナキアミは、ビートカヤックの給油のために小さな町に立ち寄る。街を放浪している途中で、独りで生きているテシクの少年に出会い、ナキアミはトラブルに巻き込まれていく。', '2025/12/26 00:00:00', 1457, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dd67ad23-75ca-4895-9bbb-ed3086a06a52.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16785dba-f6d1-45fc-9def-3a79c4c5474d', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 16, '100006027', '途上の季節が炎え墜ちる', 'ヤンゴと共に、故郷への旅を続けるナキアミ。ひょんなことから出会ったテシクの青年。彼から故郷の周辺は、南大陸による空襲が激化していると耳にする。不安なナキアミの心に、ヤンゴの声は届かない。その頃、極東自治区に、白髪の少年が送られてきた。垣巣は、少年の体を用いて対ヒトガタ研究を進めようと目論む。だが、汗馬博士にはその提案を聞き入れる事はできないのだった。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/536fd15a-8dbd-4645-8345-94dd9032ddd4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('351d623f-3952-45bd-a556-988ffee9e7db', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 17, '100006028', '子羊とオボロ月', '老女、須磨子に買い取られたアキユキは、アマウの原と呼ばれる静かな療養所で共同生活を始める。平穏でちょっぴり奇妙な生活に溶け込んでいくアキユキ。その頃、ナキアミとヤンゴは、テシクの郷を探している途中、吹雪で道を失い、洞窟へと身を潜めていた。ヤンゴに励まされながらも、ナキアミは本当は自分が何を求めているのか、故郷に帰る事にどんな意味が有るのかを、思い悩んでいた。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/93c17211-e708-425b-a17e-a10faed6a283.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('402988f4-fb99-49a1-99ef-8c312959559d', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 18, '100006029', 'そこから何が見えるか', '生まれ故郷であるテシクの郷へと帰還したナキアミ。村の人々から温かい歓迎を受けるが、居場所のなさに笑顔を取り戻せないでいた。その頃、白髪の少年アザミと牢獄の中で不思議な出会いをしたハル。アザミの導きにより極東自治区を抜け出し、ハルはアキユキの手がかりを求めて走り出す。一方、アマウに暮らす仮面アキユキは、小さな影の言葉にゆっくりと誘われていくのだった。', '2025/12/26 00:00:00', 1457, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f96cffa9-9a8d-48db-b69e-e8b5727ebdb7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2266bb9-8524-434d-b908-1b6f1baede39', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 19, '100006030', '偶発 ロマンス開花', 'アキユキに会いたい一心から、一路北政府を目指すハル。ビートカヤックを手に入れ先を急ぐ。行く手にはヒトガタ兵器の生産施設が待ち受けていた。国境を越えたハルの一途な想いは、アキユキに届くのか…? その頃、テシクの村では、ナキアミの帰還を祝う宴が、盛大に催されていた。聖地奪還の企てにナキアミを取り込もうとするクジレイカ。だが、その想いに応えられないナキアミは、クジレイカの盃を断ってしまう。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1560d75f-801e-4a1b-8447-742f60cf481c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2849b84e-d545-4972-9976-0549bcd84da5', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 20, '100006031', '涙咲く 散る会うと', '胎動窟を目指し、テシクの郷から旅立つナキアミとヤンゴ。だが、そこに南大陸自由圏軍の爆撃機が飛来する。村を死守するため、ザムドとなって立ち向かう事を決意するクジレイカ。一方、胎動窟に辿り着くアキユキとハル。そこで二人を待っていたのは…。大巡礼を前に、尖端島の運命も大きく動き始める。最終実験を加速させる垣巣。その噂を嗅ぎ付け、阻止しようと陰で密かに立ち上がる男たちがいた。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c51773ff-16bf-41a1-b045-dca697422b8e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f326ef5-7f2e-40f2-8c3b-3fe58f5a09d1', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 21, '100006032', '禁猟区潜入「泣いたら負けだ」フサはずっとそう思っていた', '白髪の青年の導きにより、アキユキとハルは胎動窟内部へと入り込んでいた。彼らがそこで遭遇する、闇の底に隠された秘密とはいったい…。尖端島では、リュウゾウらが垣巣との決着をつけるために、極東自治区への潜入を企てる。作戦を前に、一通の手紙に自分の想いをしたためるリュウゾウ。そんな男たちの不穏な動きを察して、フサは―。一方ナキアミとヤンゴは、北政府のとある町で懐かしい人物と再会するのだった。', '2025/12/26 00:00:00', 1457, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/588fa985-c569-499a-8f21-564ff7efdf53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcb515a4-3206-44e4-9284-b91d05b9c74c', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 22, '100006033', '凍二郎とリュウゾウ', '胎動窟･袋底の町に辿り着いたアキユキとハル。胎動窟と金剛塔、そしてヒルケン皇帝。人類の歴史が生み出した悲劇の装置を目の当たりにして、二人は思い悩む。一方尖端島では、丘の上の公園で待つ垣巣の元にリュウゾウが現れた。17年前、バラドール戦役で拾った命の責任を眼前に突きつけられるリュウゾウ。過去に決着をつけるため、リュウゾウが出した答えとは…。それぞれの銃に、男たちが魂を込める!', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d2f9dbc-8722-4c03-be38-0c4924d587b7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3c78499-870e-4912-ac76-b9373dec8b82', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 23, '100006034', '誕生 ヒルケン皇帝', 'ゼーゲンドォの船で胎動窟へ向かうナキアミとヤンゴ。自分の気持ちを伝えるために、ナキアミはザンバニ号に連絡を取ろうとする。その思いは、荒野にとどまるザンバニ号メンバー達にもある決意を固めさせるのだった。一方、金剛塔への潜入を果たした伊舟と雷魚。激しい僧兵の攻撃の中、二人の記憶が呼び覚まされていく。そして、胎動窟の外へと出てきたアキユキとハル、その上空、南大陸の船団が迫ってきていた。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2558c443-135b-4430-8ce7-8e975a2b97b5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('489416da-3237-49ef-88b5-a8fd83949794', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 24, '100006035', '亡き魂の邂逅 (かいこう)', 'ヒルケン皇帝の目覚めに、光を奪われ闇に覆われていく世界。胎動窟では奇跡の時を待ち望む人々が南大陸自由圏軍の攻撃に晒されていた。そんな中、汗馬博士が投下した切り札とも言うべきヒトガタ兵器が、胎動窟周辺の町を暴走、破壊していく。アキユキとハルは戦禍を前にして為すすべも無い。その時、ハルの耳にヒトガタ兵器の悲しい声が聞こえてきたのだった。', '2025/12/26 00:00:00', 1457, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e7c823f1-db68-4047-9765-163e19faee27.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cac78fb-d873-4ba1-926f-a12979d932df', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 25, '100006036', 'ナキアミとサンノオバ', '長い年月を経て、サンノオバと邂逅したナキアミ。サンノオバがナキアミに語る、世界にザムドを生み出した真意とはいったい…。その頃、ザムドとしての使命を負ったアキユキは、ヒルケン皇帝を阻止しようと戦っていた。それぞれの思いを抱えて行動を起こすヤンゴやクジレイカ。そんな中、ヒルケン皇帝の涙から生まれた黒い雨が地上に降り注ぎ、魂を持つものは次々と黒結晶と化していく。', '2025/12/26 00:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/89e306bf-6240-4a7e-95cf-d6f3b4a02435.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f5978617-151d-41cd-b5a7-368cfd2e4850', 'e2fdcc09-cb59-4294-86c7-1304fdd104c4', 26, '100006037', '大きな石と少女', '【シーズン1 最終話】千年の時を経て開いた胎動窟の扉が、今、閉じようとしている。ヒルケン皇帝の哀しみを鎮めるため、自らの犠牲を厭わず向かい合うアキユキ。その選択は、世界に光を取り戻すことができるのか。そして、ナキアミの選択は…。二人の想いに引き寄せられるかのように、胎動窟に到着するザンバニ号。胎動窟上空に、人々の想いが華と咲く―。', '2025/12/26 00:00:00', 1622, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ffb2902a-2b1e-4f0e-8483-c4aa534d790b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('c3ced814-eaa1-400c-adb5-0d1a41fec703', '忘却バッテリー', '', 'hulu', 'boukyaku-battery', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7015474-06cc-4808-9fd7-122f3b971e2b.jpg?w=331&h=447&p=t', 'hulu', 2020, 3, 1, 'FINISHED', NULL, 124703, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cf8787d1-3698-48c1-ada9-b518d1b97e40', 'c3ced814-eaa1-400c-adb5-0d1a41fec703', 'hulu-boukyaku-battery-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef7c60f6-6a80-494f-9360-54ffa13f62a5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19827bfb-6c19-4dda-9437-69114fc7e2ab', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 1, '100180722', '思い出させてやるよ', '中学で野球を諦め、野球無名高校に進学した山田太郎。そこで、かつて打ちのめされた中学最強のバッテリー ――清峰葉流火、要圭と出会う。だが、この高校に野球部はないはず。しかも圭は記憶喪失のようで……!?', '2024/04/11 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef7c60f6-6a80-494f-9360-54ffa13f62a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c9502f32-ac2e-4cb4-8bca-7e2bd1d2185f', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 2, '100181928', '一緒にやる?', '相変わらず圭は野球を拒否していたが、葉流火がある取り引きをもちかけ、渋々バッティング練習をすることに。一方、山田と同じく最強バッテリーに夢を打ち砕かれた藤堂葵と千早瞬平は、その光景を目撃して驚愕する――!', '2024/04/18 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd2ef6b1-5c60-4433-8c31-5da635b4616f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81029136-d27c-4c7f-aa2a-4818355313e6', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 3, '100182362', 'だから、なんだ', '藤堂、千早との親睦を深めるため圭は自分の家に招待する。そこで葉流火からベッド下に隠されたキャッチャーミットを見せられる。それぞれが「捨てられないもの」と向き合うことになる中、名門帝徳高校の練習試合が決まる――!', '2024/04/25 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0f4060b-04b9-4878-873c-c914b078cc06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b0200968-e900-4d30-9535-23ce5dadda25', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 4, '100183227', '容赦しないよ', '葉流火のピッチングは帝徳バッターを寄せ付けず、あっという間に三者連続三振。攻撃でも一番･藤堂が初球ホームランを放ち、小手指が勢いに乗る。そして、誰もが固唾を呑む中、葉流火と圭と因縁のある天才バッター国都との対決を迎える!', '2024/05/02 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f72a97ea-f97e-48be-ba06-ab2b2eb646d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6260eb54-3dae-445c-80da-eab353252be5', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 5, '100184058', '辞めたきっかけの', '試合後、帝徳の監督から葉流火･圭･藤堂･千早がスカウトを受ける。自分のせいで負けたと気づき、3人を送り出すつもりの圭。転校について悩む藤堂と千早。そして早々に立ち去った葉流火。それぞれの答えは……?', '2024/05/09 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0d0f92f3-66d2-4067-885b-52786f0f6cdf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8dcb7ea8-f1f8-494e-a618-3c354bbce6aa', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 6, '100184641', 'やる!!', '野球とは何か? 悩める圭のために藤堂の家で勉強会をすることに。藤堂の綺麗な姉とかわいい妹に衝撃を受けながらも、圭は純粋な気持ちで野球を学ぼうとしていた。一方、藤堂は自身がある問題を抱えていると告白する…!', '2024/05/16 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f14c2669-a4cc-40f0-ad3a-053b647b5a90.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a91f866a-d884-4f72-ac45-44fe26be277c', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 7, '100185005', '面白いやつら', 'イップスのため、ポジションの変更を申し出る藤堂。似たような経験をした圭の言葉に動かされ、改めて送球の練習をするが、やはりうまく投げられない。そんな藤堂に、葉流火が厳しいひと言をぶつけてしまい……!?', '2024/05/23 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d08169c6-065a-4bb2-ac9c-e4ac0d6621bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82f0ca91-72fb-4167-9168-055ec67c985c', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 8, '100186774', '3次元の野球はちょっと…', '藤堂のイップスが改善し、次の課題は圭の能力向上! しかし、圭は要求の多さに耐えられず、屋上へと逃げてしまう。するとそこで、野球ゲームは好きだが現実の野球は苦手なオタク･土屋和季に出会う。', '2024/06/06 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/345ece86-8681-459f-b040-28bd5c4ea31e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c97027fb-dcda-4d1d-a83b-354c8a4619ad', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 9, '100187464', '誰に向かって口きいてんだ', '「圭の記憶が戻ったらどうなるのか」という土屋の素朴な疑問から、それぞれがあの手この手で圭の記憶を取り戻そうとする。そんな中、土屋の提案した催眠術を試すことに。効果はなかったように見えたが……。', '2024/06/13 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67a5e58b-c605-4b75-beb7-8a4180106832.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('43868365-a505-4aac-ac24-fef177bd19c5', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 10, '100188088', '逃げられない', 'ついに氷河高校との練習試合が始まる――! 復活した智将･要圭の読み通りに試合は進むものの、時々アホ圭が顔を出し、不安に駆られる山田たち。だが、彼らは目撃するのだった、フルスロットルの“最強バッテリー”を!!', '2024/06/20 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef2ad75b-d113-4541-8035-977c00ec0c45.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8732a9f9-c180-497a-a4f7-a2cfb7929f1e', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 11, '100188620', '俺は嘘つきだ', '圭の智将モードがついに終了?! 動揺する小手指はついに逆転を許してしまう。圭はベンチに充満する重い空気を変えようとするも、千早は立ちはだかる“ある壁”に苦しむ。', '2024/06/27 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fdaf6015-3845-437d-97df-047af652e287.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2710b229-b597-4fa2-bbb2-b67b1ed8098e', 'cf8787d1-3698-48c1-ada9-b518d1b97e40', 12, '100189528', '嫌だったか', '【最終話】九回表、ツーアウト一･二塁。逆転の望みは圭に託されるが、元智将は巻田の剛速球にテンパるばかり!「普段、誰の球捕ってるんだ」。葉流火のひと言で何かに気づいた圭が、巻田との勝負に真っ向から挑む!', '2024/07/04 00:30:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81fa28d3-4545-4ca6-a209-375432768f11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a2751707-d30d-40b8-9509-363e0e81f802', '暴食のベルセルク', '', 'hulu', 'berserk-of-gluttony', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a3b7669-e2a3-4778-bdb6-e5550f2069fc.png?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 156039, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2ceabbb0-3a0d-4e0e-a76e-73a868aa848d', '望まぬ不死の冒険者', '', 'hulu', 'the-unwanted-undead-adventurer', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad74315a-c260-4b6b-af2e-2e23bd19ff30.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 147642, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', '2ceabbb0-3a0d-4e0e-a76e-73a868aa848d', 'hulu-the-unwanted-undead-adventurer-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32b6d0d7-b153-4232-99ee-cadc56d43475.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e1be9bb-4368-4679-98ff-6543395be935', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 1, '100171409', '望まぬ不死', '万年銅級冒険者のレントは、毎日一人で迷宮に潜り、弱い魔物を狩って暮らしている。今日もまた《水月の迷宮》で稼いでいると新たな通路を発見。大喜びで貴重な魔道具や名声を期待して探索する。ところが、未踏破区域にいたのは魔物の中でも最上位の存在･龍だった。龍に喰われてしまったレントだが、何故か意識を取り戻す。その姿はスケルトンになっていて――。', '2024/01/12 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32b6d0d7-b153-4232-99ee-cadc56d43475.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fee080ca-dead-4b33-8ff4-a38a91aa11a0', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 2, '100172006', '駆け出しとベテラン', '最弱のスケルトンからグールへと《存在進化》を果たしたレント。さらなる進化を目指して魔物と戦い続けていた。そんな中、《水月の迷宮》に新人冒険者のリナがやってくる。魔物との戦いで窮地に陥ったリナは、助けてくれたグールが冒険者のレントだと知って驚愕。それでも本拠地の街マルトへ戻りたいというレントのために、衣服の調達を引き受ける。', '2024/01/19 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4293180f-545b-4ce6-aeae-66fa9f87f6da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f545bd40-a6de-4913-b073-a11206d26af4', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 3, '100172723', '不死者、街に侵入', 'マルトに戻ったレントは、十年来の友人である学者のロレーヌを頼ることに。魔物や魔術の研究をしているロレーヌは、異形と化したレントを冷静に受け入れ、協力を約束してくれる。アンデッドになっても冒険者を続けたいレント。神銀 (ミスリル) 級冒険者になるという夢を諦める気は全くない。早速装備を整えようと、鍛冶屋･三叉の銛に出かける。', '2024/01/26 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7678a7e6-277c-4346-aef3-22db2486710c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cd4223d-cd71-4fcb-b0ba-93fea3ca0871', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 4, '100173562', '存在進化', 'レントは再び《水月の迷宮》の未踏破区域を探索する。迷宮の中で出会った男･ロリスをマルトに帰すため、探索の途中で引き上げることに。ロリスの命のみならず彼の借金まで助けてやり、深く感謝されるレント。しかし、当のレントは人間の血肉を求める衝動に苦しんでいた。耐えきれなくなったレントは自我を失ってしまい、ロレーヌに襲い掛かる。', '2024/02/02 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a34c94cc-eaf5-4fea-8217-3e67acbd4a3c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74ae9cf5-ade3-481a-9367-aa8a001b79e7', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 5, '100174620', '不死の冒険者', 'グールから屍鬼に存在進化したレント。見た目も大分人間らしくなり、自分で冒険者組合 (ギルド) の依頼を受け、実績を積みたいと考える。しかし、レントは万年銅級冒険者ではあるものの、ギルドへの貢献度は高く、元の顔を知る者も多い。ロレーヌの入れ知恵により、レントは別人としてギルドに登録。鉄級冒険者として改めてスタートすることに。', '2024/02/09 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2a1ab2e-c389-4ef1-b893-732992064eb2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3d3675fa-181c-4310-a6e8-f48c69d378a9', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 6, '100175146', '銅級試験', '新人冒険者「レント･ヴィヴィエ」として、レントは難しい依頼を達成する。ギルドの職員･シェイラから実力を認められ、銅級への昇格試験を許可されたレント。早速、昇格試験に参加し、筆記試験を軽々と突破する。次の実技試験で、レントは同じく受験者のライズとローラとパーティを組み、新月の迷宮へ向かう。だが、その試験は迷宮に入る前から始まっていて……。', '2024/02/16 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0aa1de6-6ceb-4fc8-81dd-1bb9536afded.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf6fc1eb-b4cd-4cc2-8888-d716ee97b685', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 7, '100175550', '魔術契約', 'レントたちが挑んだ実技試験は、受験者の戦う力だけではなく、冒険者としての適性を試すものだった。ライズとローラは戸惑いながらも、レントの手助けを受けて乗り越えていく。そして、そんな受験者たちの様子をギルドの職員はつぶさに観察していた。一連の報告を受けたシェイラは、「レント･ヴィヴィエ」の正体が「レント･ファイナ」だと確信する。', '2024/02/23 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78d6ae47-3d4e-450c-9c53-2387c1443dc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22586bf6-1c22-416c-96aa-609b62eee667', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 8, '100176343', '新たな武器と力', '鍛冶屋のクロープに新しい剣をつくってもらったレント。剣は素晴らしい出来だったが、存在進化に伴って魔力や気力、聖気も増えていたため、より強靭な剣がほしくなる。ミスリル級を目指すうえで良い装備は不可欠であり、そのためには金が必要。しっかり稼ごうとギルドに向かったレントは、そこで厄介な問題を抱えた村人と遭遇する。', '2024/03/01 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36ff2820-faba-4a2a-9a4c-17ec5baefccf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c8edd24-9fba-4d29-bbbf-5d8b092408ee', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 9, '100176922', '竜血花', 'レントはギルドで格安の依頼を見つける。その報酬はたったの銅貨一枚。ギルドが伝統的に行う困っている人を助けるための特別な募集だった。その依頼主はアリゼという名の少女で、彼女が世話になっている孤児院の院長･リリアンを助けてほしいという。依頼を引き受けたレントは、リリアンの病を癒すために必要な竜血花を採りに、危険なタラスクの沼へ向かう。', '2024/03/08 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7a76af9-373b-45c0-b051-82a9d1e40aeb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28adda98-9370-4fd5-98fd-d6a5d4f014f4', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 10, '100177708', '奇妙な男と奇妙な依頼', '強大なタラスクを倒し、シェイラたちを驚かせたレント。その強さは銀級に達していると褒められるが、レントの顔は浮かない。今の強さは存在進化によって得たもので、人間に戻ったら失ってしまうのではと不安に思う。そんな中、無事アリゼの依頼を完了したレントの元に指名依頼が入る。依頼者はマルトに古くからある謎多きラトゥール家で……。', '2024/03/15 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/434345c1-188e-42ae-a2f7-4f21c4ffedd3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c455a499-a22b-4a8b-9bc4-5674f09e7a75', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 11, '100178290', '庭園迷宮', 'レントは、踏破した者には魔導具が与えられるというラトゥール家の巨大な迷路に挑戦する。方角を見失いながらも、仕掛けられた謎に気づいたレントは、何とか迷路を踏破。ラトゥール家の当主である美少女･ラウラは、迷路踏破の賞品を与えるべく、レントを屋敷の中へと案内する。そこには、レントの想像をはるかに超えるコレクションがあった。', '2024/03/22 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa0dee97-4220-43ca-be4f-8a8b725650e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b26e34c9-1ae6-46b7-8625-5e5945451e26', '67ae9e7a-ad3d-4504-aa9c-4c5e851618d5', 12, '100178735', 'レント･ファイナ', '【最終話】レントがラトゥール家から譲り受けたヴァンパイアの血液は、摂取すれば存在進化できると思われるものの、人間が飲んでまともに生き残った記録はない。それでもレントは強くなるために、ヴァンパイアの血液を飲むと決める。何故、命を懸けてまでミスリル級冒険者を目指すのかと問うロレーヌに、レントは己の過去を語りはじめ――。', '2024/03/29 22:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8e9ff5f-8d2d-4924-9d35-e7d9dd5ec8a4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3ac2376f-1656-4a1c-8a2a-47e4a4afe243', '冒険者になりたいと都に出て行った娘がSランクになってた', '', 'hulu', 'my-daughter-left-the-nest-and-returned-an-s-rank-adventurer', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8035b8d7-a3ea-4070-8d2f-4ade9263ed19.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 156184, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', '3ac2376f-1656-4a1c-8a2a-47e4a4afe243', 'hulu-my-daughter-left-the-nest-and-returned-an-s-rank-adventurer-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be2e8a10-6952-4178-88a4-fbc8c846df67.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d2610e6-1a63-46c7-9954-a2db26cf370a', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 1, '100163405', 'アンジェリンの憂鬱', '元冒険者ベルグリフは、故郷へと戻り日々平穏に暮らす中、森で捨てられていた女の子を拾い、自分の娘“アンジェリン”として男手一人で育て上げる。時が経ち成長したアンジェリンは、父と同じく冒険者になりたいと都のギルドへと旅立っていき、「黒髪の戦乙女」の異名を持つSランク冒険者として活躍するように。そんなアンジェリンが久しぶりに長期で休みをとり、5年ぶりの再会を楽しみに父･ベルグリフのいる故郷に帰ろうとするが…。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be2e8a10-6952-4178-88a4-fbc8c846df67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5af384d3-19f0-47b6-bb0c-25f950530000', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 2, '100163406', '赤鬼のベルグリフ', '農作業に勤しむベルグリフのもとに現れた大領主ボルドー家の次女･サーシャ。盗賊に襲われていた三女のセレンをアンジェリンが助けた件で、お礼にやってきたという。謝礼の金貨を贈る中、サーシャはベルグリフに剣技を師事したいと申し出て……。一方、オルフェンにて魔獣退治の依頼に励むアンジェリンは、かつて護衛を依頼された行商人と再会。そこで父･ベルグリフの話を聞くことになる。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/173cdaad-cee9-4a36-86b5-39a27b19e971.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea300279-82d1-4d03-a02a-fbc4dca46d60', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 3, '100163407', 'おかえり、アンジェリン', 'アンジェリンたちが暮らすオルフェンに、引退した元Sランク冒険者のチェボルグとドルトスがやってきた。魔獣の大量発生を憂う2人は、その原因を叩くため復帰を決意したという。そしてアンジェリンたちは、同じく元Sランク冒険者である龍殺しのマリアとも合流しつつ元凶の廃ダンジョンへと向かう。立ちはだかる魔物と戦いながらダンジョンを進む冒険者たち。激戦が繰り広げられる中、最奥で待ち受けるものとは…。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/25585ffa-6f33-4a39-a25f-5ae714696fcc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7e661c93-bfae-4bde-8ee4-37c420a19876', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 4, '100164109', 'トルネラの穏やかな日常、時々親子喧嘩', 'ようやく故郷トルネラに戻り、父･ベルグリフとの再会を果たしたアンジェリン。同行したアネッサやミリアムも一緒にベルグリフと過ごす、念願の穏やかな日々。そんな折、親子は剣の手合わせをすることになるが、昔からの癖を知るベルグリフにアンジェリンは簡単に負かされてしまう。Sランク冒険者である以上、今後も危険な目に遭うかも知れない。冒険者としてのアンジェリンの覚悟を問うため、ベルグリフは再び剣を交える。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abe9f5ce-9f90-45e1-897f-3a487891cf16.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a76d1cdc-fc5c-47c0-ae13-d42fb15d5c92', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 5, '100165116', 'ボルドーへの旅路', 'オルフェンの裏路地を歩くライオネルとチェボルグは、広場でヴィエナ教を批判しているシャルロッテと遭遇。魔王を生み出した大魔導ソロモンを信奉し、警備隊すら退けるシャルロッテとその従者･ビャクに対し、「おいたが過ぎる」とチェボルグたちは対峙する。一方、春告祭が行われているトルネラでベルグリフは、村長からボルドー伯への手紙を送り届けてほしいとの依頼を受け、アンジェリン達とともにボルドーの街へと向かうことに。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a273a093-edee-42e2-ba98-23844e15aca2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7ae862c3-835e-455c-af47-df89d80a82b7', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 6, '100165491', '暗躍する反乱分子', 'ヘルベチカ･サーシャ･セレンの三姉妹がいるボルドーに滞在することになったアンジェリンたち。時を同じくして、シャルロッテたちと手を組んだマルタ伯爵が、ボルドー襲撃を企てる。墓場から大量に現れたアンデッドがボルドーの街を襲う。住民を守るため最前線で戦うアンジェリンたち冒険者パーティー。アンデッドの群れが三姉妹の籠もる屋敷にも迫る中、アンジェリンは、かつて倒した魔王にも似た黒い影と対決する。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd5f207f-480c-4512-8ae8-e3ff94de2890.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3b5891d3-1693-46da-ac96-84fac908bc4d', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 7, '100166466', '長い夜、明るい朝焼け', 'シャルロッテとビャク、そしてマルタ伯爵が計画するボルドー家長女ヘルベチカの殺害計画。それに対し次女サーシャはマルタ伯爵の身柄を取り押さえるため、1人馬を走らせる。そこで遭遇したのは、姉を襲撃しようと目論むシャルロッテとビャクの2人だった。暗闇の中の戦闘で苦戦を強いられるサーシャは、絶体絶命のピンチを迎える…。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/65f4508f-03da-43a0-b43e-22531633286f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f8af850-e8e3-4904-8cae-226a1e95c817', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 8, '100166905', '森の住人との邂逅', 'ボルドー襲撃事件が決着し、アンジェリンはオルフェンへ、ベルグリフは故郷のトルネラへと戻っていく。帰宅したアンジェリンは、「お父さんが寂しい思いをしないよう、お嫁さんを探す」と意気込み、勝手に父の花嫁探しを始め、元･高ランクの女性冒険者や、孤児院のシスターに次々と声をかけていく。一方、トルネラでは魔獣退治に勤しむベルグリフの前に、老エルフ･グラハムが現れる。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a3eb0d7-94bb-4031-ab5d-0b57aab5a63a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9a381a39-6ba5-4f74-8b97-f6825c4b25cb', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 9, '100167317', '親子、それぞれの出会い', 'アンジェリンはオルフェンの路地裏でシャルロッテと再会する。泣きながら許しを請うシャルロッテに対し、アンジェリンは「無抵抗のヤツを殺すのは気分が悪い」と言って矛を収めるが、そこにへルクレシア教皇庁の浄罪機関が襲いかってくる。一方トルネラ近郊の森では、グラハムとマルグリットを追ってきたベルグリフが魔王の気配をまとった謎の子供と遭遇する。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1245f898-9672-45f5-9386-0b4bbf65cf39.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc79919c-e603-4e7a-8dc6-b279807af091', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 10, '100168295', '蠢く悪意', 'アンジェリンの家に居候することになったシャルロッテとビャク。2人を弟妹のように思うアンジェリンは、偶然出会ったマリアに自衛のための魔法を教授してもらえるようお願いする。その帰り道、正体不明の兵士たちの襲撃を受けることに。不意を突かれて苦戦を強いられるアンジェリンたち。その戦いはやがてギルドの冒険者も巻き込んでいく。「誰かが兵士たちを操っているのでは?」と疑うアンジェリンの前に、かつて対峙した影が現れる。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c30d20d0-4fbb-4a74-b000-eab502ff9e83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a73521dc-3a48-4457-9c12-a36efdeea09f', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 11, '100168955', 'ベルグリフの決断', 'アンジェリンはシャルロッテたちが安全に暮らせるよう、二人を連れてトルネラへの帰還を決意するが、そこへエストガル大公からの招待状が届く。魔王討伐の功績を称え、勲章を授けるというのである。一方トルネラでは、「冒険者になるため旅に出る」と宣言するマルグリットに、昔の自分を重ねて思いにふけるベルグリフがいた。グラハムは「過去を精算する必要がある」と、ベルグリフに旅に出るよう促す。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d8ff197f-fb25-46ad-bab6-1b05e8d1508c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('686f44c8-e8ef-4f19-b3b7-eaf21e854337', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 12, '100169757', '過去との対峙', '大公の招待を受け、公都エストガルを訪れるアンジェリン。大公家の次男ヴィラールの尊大な振る舞いにうんざりするも、無邪気で好奇心旺盛な息女のリーゼロッテとは仲良くなる。そして「私の秘密を見せてあげる」と促され、地下牢へ導かれる。一方、マルグリットとともにオルフェンに着いたベルグリフ。そこでアンジェリンが自身の嫁探しに励んでいたことを知り困惑する。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17fca443-501f-4f88-ac48-27a622fe4cd0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca4d3da8-0707-4518-81be-93b27e7e3245', 'e0c2a6a5-4beb-43e2-9006-22b2fed6bb86', 13, '100170784', 'ただいま、お父さん', '【最終話】大公邸の舞踏会に向けてドレスアップされたアンジェリンに対し、エストガル大公の三男フランソワは「君のために余興を用意した」と不敵に笑う。そしていよいよ始まる式典。大公と皇太子も見守る中、フランソワは地下牢に閉じ込めていた“天蓋砕き”の異名を持つ元Sランク冒険者･カシムを式典へと連れ出す。大義もなく対峙することになったアンジェリンとカシム。カシムは「お前ならおいらを殺せると思う」と自嘲的に笑うのだった…。', '2025/01/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55a4f84b-70eb-4b0b-8fea-6ac7c57431a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2653a2b4-3482-41a3-856c-b31952f63230', '北斗の拳 ラオウ外伝 天の覇王', '', 'hulu', 'fist-of-the-north-starlegends-of-the-dark-king', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7253e3b2-8bec-46a2-8c6c-8756157d5a4e.jpg?w=331&h=447&p=t', 'hulu', 2008, 3, 1, 'FINISHED', NULL, 4549, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8fa6c5c1-984d-4e98-9808-263283ff71b6', '2653a2b4-3482-41a3-856c-b31952f63230', 'hulu-fist-of-the-north-starlegends-of-the-dark-king-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa333da9-da04-43fd-9b1b-169b3a002eb4.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('53b84668-7a02-42a1-9b30-3d605ff8a757', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 1, '100242450', 'わが拳は天のため!', '荒れ果てた世界に一人の男が現れた、男の名はラオウ。究極の暗殺拳「北斗神拳」の使い手である彼は、世紀末覇者たらんと己の拳一つで立ち上がる。自らを拳王と名乗り、仲間であるソウガやレイナと鬼王ゴラムの鬼巌城を乗っ取る。ここに拳王軍設立を宣言するラオウ。そして、彼の行動を不敵に笑う一人の女の姿があった…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa333da9-da04-43fd-9b1b-169b3a002eb4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1fb181da-4d4e-4922-a90a-a9f79e885c8c', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 2, '100242451', '王は王を知る!', '拳王軍の破竹の勢いは王たちを震え上がらせた。ある者は戦い散り、ある者は白旗を揚げ降伏をした。その中、拳王精鋭部隊が智王ギオンの策略の前に全滅の報せを聞く。全滅させたのはギオン軍ではなく、漆黒の馬率いる千頭の馬たちであった。ソウガとレイナを引き連れ、黒王谷と呼ばれる場所へ向ったラオウが見たものは…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16cbac1e-e203-4a24-9802-450772b662cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4e6fa7e4-460a-4cae-b363-8b39f973f520', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 3, '100242452', 'われに落とせぬ城なし!', '黒金城に篭城した我王軍を攻略できずにいるラオウたちの前に一人の女が現れた。女の名はサクヤ。彼女は自分一人で黒金城を一晩で落として見せるとラオウに進言する。単身黒金城に乗り込むサクヤ。そしてソウガの指示のもと、レイナも城に突入するが南斗隼牙拳の使い手ハバキの前に絶体絶命のピンチを迎える。その時…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38b827fd-3892-4c51-8ecc-a9e6f489f8ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28d37441-def7-4f3a-a46b-3faa69202ba7', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 4, '100242453', 'この拳、誰がために!', '新たに拳王軍軍師として加わったサクヤをまだ信用できないレイナとソウガ。そこへ何度処刑をしても死なない男が暴れているとギオンから知らせが入る。急ぎ監獄都市カサンドラへと向うラオウ、ソウガ、レイナ、そしてサクヤ。鎖に縛られてもなお激しく暴れまわる大男ウイグルに向ってラオウがとった行動とは…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae233c79-44e5-4649-bc9c-eb28bf4940e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('469d3274-e26b-4030-b78a-c2682c24e671', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 5, '100242454', '相剋の兄弟!', 'ラオウの覇道成就のためには、弟であるトキの力が必要だと諭すレイナ。彼女は自らトキの村へ説得に向うが、北斗神拳を医術として人のために使うトキにはレイナの願いは無駄に終わる。そして、トキの前に現れたラオウにトキは「暴力で人は支配できない」と言う。そんなトキをカサンドラへ収容するようにラオウは命じて…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80fe48bd-bedc-474a-b165-822f03b90dcb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('264cfec7-6238-4d50-8819-3b1125f22b34', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 6, '100242455', '鬼、目覚める!', 'ラオウは、新たなる将を拳王軍に迎え入れるため、南斗の智将と呼ばれた南斗流鴎拳の使い手であるリュウロウを尋ねた。しかし、リュウロウは拳で人を支配するラオウではなく民衆の哀しみを背負う末弟のケンシロウの味方になると言う。さらにリュウロウはラオウに言う「悔い改めろ」と。己の甘さを痛感したラオウは…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b32fd97-038b-4678-a11c-79a40e2ce696.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('006fac94-76a1-4715-9102-335fab5a2ac7', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 7, '100242456', '蒼き狼、大地を駆る!', '冷酷な鬼へと変貌を遂げたラオウの前に天狼凍牙拳のリュウガが現れた。新たに拳王軍の将として迎え入れられたリュウガに不信感を抱くソウガ。そこへ獅子王軍と雷帝軍が同時に拳王軍に攻め込みに来たと知らせが届く。獅子王軍征伐へ向うソウガとリュウガ。そこでのリュウガの残忍な戦いぶりにソウガの怒りが爆発する…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/495be7a6-4d10-43a6-8a62-4ecd444ebe68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa175a0f-8c96-4c8e-88ee-b3f677703265', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 8, '100242457', '慟哭、闇に響く!', 'ラオウの覇道のために誰かが鬼とならねばならない、その言葉に遂にソウガまでも鬼へと変貌してしまった。サザンクロスタウンの噂を聞き、駆けつけたリュウガとレイナの前に雲のジュウザが姿を現した。「妹ユリアが死んだ」と、ジュウザの口から信じられないことを聞くリュウガ。その報せをリュウガから聞いたラオウは…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf5f3f3c-daed-4f81-b5e2-0ed0d3647875.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('67599da7-047b-40b4-9bda-aab5f5b75f7b', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 9, '100242458', '女の戦い', 'ラオウの役に立とうとレイナは独断で南の新たな勢力へと偵察に赴いた。だがそこで待ち受けていたダガールの罠にはまり、レイナは捕まってしまう。忠誠を誓わせようと拷問をかけようとするダガールとコマク。一方、鉄帝軍との戦いの最中、レイナが捕まったことを聞いたラオウはレイナのもとへと愛馬の黒王号を走らせて…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be9922f2-05f1-41b0-b919-3bd03d784b7e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc73bfc2-256b-44d1-9ffe-55fa4a65064e', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 10, '100242459', '熱砂に砕ける拳!', '砂漠を根城とする冥王軍との戦いに苦戦していた拳王軍は、ソウガを先頭に砂漠の村へと潜入捜査を開始した。村への潜入に成功したソウガであったが、姿を見せない敵により致命傷を負わされる。後を追ったリュウガもまた同じように倒される。姿を見せずに敵を倒す拳法とは? その謎を解明すべくラオウはトキを訪れるが…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/265cc6a0-e0ae-4de9-b863-5c76d01533d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1aa0d999-388d-4e70-8402-d7ed2f87e0c0', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 11, '100242460', '聖帝、現る!', '謀反の罪でカサンドラに収容されたサクヤ。真意がつかめないレイナはサクヤの面会に向かう。「聖帝との和議が成り立った時にお開けください」と、サクヤはレイナに袋を渡し、口を閉ざす。いよいよ聖帝の領土に侵攻を開始する拳王軍。そして聖帝との和議が成り立った時、ソウガはレイナから預かった袋の中を確かめるが…。', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4aecd4fd-9da9-460c-8b4b-15735b9f1309.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b32b7267-b36e-4f36-8ae4-b82f888dfe8e', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 12, '100242461', 'いま墜つる拳王府!', '突如として拳王府の前に現れたユダ率いる聖帝精鋭部隊と拳王府を守るレイナ率いる拳王軍との壮絶な戦いが始まった。ユダの執拗な攻撃に苦しむレイナは裏切り者サクヤをカサンドラから呼び戻す。圧倒的形勢不利の中、レイナやサクヤはラオウが来るまで拳王府を守りきれるのか? 果たしてラオウは間に合うのか?', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/adc554a0-4db4-4ae0-af1b-4b3706784561.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8881f3eb-9cc7-479d-a168-79ee6b78cc7b', '8fa6c5c1-984d-4e98-9808-263283ff71b6', 13, '100242462', 'わが赴くは天の道!', '【最終話】遂に拳王府の前でラオウとサウザーの両雄が対峙した。レイナ、サクヤの眼前で二人の男の戦いが始まる。北斗神拳対南斗鳳凰拳、二人の拳が交差する! 壮絶な戦いの結末は!? ラオウの覇道はここで潰えるのか、最終決戦の幕が今開ける! 一片の悔いなく生きた男ラオウの生き様を見よ!', '2025/12/05 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2d95f5d-ab03-4399-97e5-fc6d9c92bfab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('da144255-c225-458e-9f6b-24fbf09043c4', '北斗の拳 イチゴ味', '', 'hulu', 'fist-of-the-north-star-strawberry-flavor', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43b61ede-8464-47cc-9cd6-f3dc2d13c77e.jpg?w=331&h=447&p=t', 'hulu', 2015, 3, 1, 'FINISHED', NULL, 21232, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('eb0b6aed-b0d3-4364-8809-3fddcabfd3ce', 'da144255-c225-458e-9f6b-24fbf09043c4', 'hulu-fist-of-the-north-star-strawberry-flavor-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13dceaaa-6f25-42e2-8a32-dad42a4c237a.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8abc6e4a-8798-429e-963a-843bc267f971', 'eb0b6aed-b0d3-4364-8809-3fddcabfd3ce', 1, '100000454', '第1話～第12話', 'こんなサウザー見たことない! 聖帝サウザーが、はしゃぐ! デレる! 高笑う! 禁断の原哲夫画風で描く今世紀最大の著作権の無駄遣いと言われる問題作が遂にアニメ化。友達がいない聖帝サウザーがケンシロウと仲良くなる方法を考えたり、南斗六聖拳のメンバーと遊んだり、大好物のカレーを食べたり、サウザー様が画面いっぱいはしゃぎまくる!', '2017/06/01 12:00:00', 1659, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13dceaaa-6f25-42e2-8a32-dad42a4c237a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e20035a0-3b77-4e79-982d-c379e0d065ff', '僕だけがいない街', '', 'hulu', 'erased-tv', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/243045ca-77ae-4438-a991-fd63f4b9733d.jpg?w=331&h=447&p=t', 'hulu', 2016, 0, 1, 'FINISHED', NULL, 21234, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0beaa770-0e7f-424e-853a-aacca9751d7f', 'e20035a0-3b77-4e79-982d-c379e0d065ff', 'hulu-erased-tv-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/29345522-11c7-4631-9b8a-70ad0c3588ef.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa031051-e47e-4913-becd-637c62f8bab9', '0beaa770-0e7f-424e-853a-aacca9751d7f', 1, '100153651', '走馬灯', '売れない漫画家である藤沼悟は、悪いことの起こる直前に時間が巻き戻る現象、「リバイバル」に悩まされていた。その日、「リバイバル」が原因で交通事故にあった悟は、18年前の誘拐事件で殺された少女を思い出す。そして、悟の見舞いに訪れた母佐知子は解決されたはずの事件の真相に気づいてしまい…', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/29345522-11c7-4631-9b8a-70ad0c3588ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('352813d5-1bb1-4cf6-92b3-b62ef345fe6b', '0beaa770-0e7f-424e-853a-aacca9751d7f', 2, '100153652', '掌', '母佐知子の死をきっかけに昭和63年に戻ってしまった悟は、小学生時代の生活を追体験する。優しかった母、仲のよかったクラスメイトたち、担任の教師、そして誘拐事件で殺された雛月加代と再会する。過去の誘拐事件を防ぐことが母の死を回避することになると考えた悟は、行動を開始するが…', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1d96adb-86cf-4ee7-b090-88d30b5d217d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('675f12c2-1c10-4721-a70d-a1eb9d235924', '0beaa770-0e7f-424e-853a-aacca9751d7f', 3, '100153653', '痣', '雛月失踪のXデーを探る悟は、18年前と同じ失敗を繰り返して雛月の信頼を失ってしまう。仲直りのために雛月を探すが、いつもの公園にその姿はない…。ユウキさんと再会し、改めて冤罪を確信した悟は事件にさらに踏み込む決意をするが、雛月の家で恐れていた事態に遭遇してしまい…', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32145ab4-7da6-43ac-9342-7a7a6cd170a2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e37384db-a0f3-447d-891c-76ae66a60f2a', '0beaa770-0e7f-424e-853a-aacca9751d7f', 4, '100153654', '達成', 'Xデーを特定し、それまでのあいだ雛月が一人でいる時間をなくそうと懸命に努力する悟。しかし雛月と訪れた科学センターで、知らず知らずのうちに、かつて雛月が殺されたときと同じ“時の流れ”に乗ってしまっていることに気づく。未来は変えられるはずと信じ、Xデーまでの時間を過ごすが…', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e312e2f9-1032-42d1-b581-8e5639b719f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0465c1f-3ad1-4410-a3e2-859bd8c9bc8c', '0beaa770-0e7f-424e-853a-aacca9751d7f', 5, '100153655', '逃走', '姿を消した雛月は、いつまで経っても学校に現れない。焦燥感を募らせる悟。さらにその6日後、別の児童も行方不明になったという情報がもたらされる。時の流れは、確実に18年前と同じレールに乗っていた。そして失意に沈む悟の目の前に、残酷な現実が突きつけられる…', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35653273-af83-4de7-b0db-cdfb5629eef2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f705a808-b6dc-4897-a9b3-6271598760c0', '0beaa770-0e7f-424e-853a-aacca9751d7f', 6, '100153656', '死神', '犯人が近くにいることに気付いた悟は、佐知子のかつての同僚である澤田を訪ね、18年前の誘拐事件の詳細を知る。そして、資料の中の容疑者リストに犯人の名前があることを確信する。一方、犯人の名前を知った愛梨は警察の目を盗んで病院を抜け出し、悟の元に向かうが…。', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa82ede7-2244-4a76-b64b-c2c02d6e59f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5fce61f0-1c50-43e9-a14c-99b07af0fbee', '0beaa770-0e7f-424e-853a-aacca9751d7f', 7, '100153657', '暴走', '愛梨と再会を果たす悟。しかし、愛梨は警察につけられていた。連行される中、悟は佐知子の殺害現場ですれ違った男の姿を目にする。「このまま終わりたくはない!」と願う悟に、再び大きなリバイバルが訪れる。三度目のXデー、昭和63年3月2日を迎えた悟は、雛月を救うため、思わぬ行動に出る…', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03938b37-c26c-48bb-860e-207fd87ec27c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e875a8b8-7fad-478c-9a85-26bd9b955125', '0beaa770-0e7f-424e-853a-aacca9751d7f', 8, '100153658', '螺旋', '深夜、雛月の眠る廃バスに謎の人影が現れる。その男は雛月に気付かず立ち去るが、不安になった雛月は、悟に朝まで一緒にいて欲しいと頼む。バスの中に男の痕跡を探す悟たち。そこにあったのは“犯行に使われるはずの道具”だった。バスを出る決意をした悟は、雛月を連れてある場所を目指す…', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7cd738ce-ade3-4862-9ae8-84217b1bdbae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a9ba2ce-f0ce-4b58-9aed-20d91483bf89', '0beaa770-0e7f-424e-853a-aacca9751d7f', 9, '100153659', '終幕', 'ついに雛月の母親と対峙する悟たち。そこに意外な人物が現れたこともあって、虐待事件は一旦の解決を見る。緊張が解け脱力してしまう悟。だが、真犯人はまだ捕まっていない。ケンヤたちの協力を得て、悟は改めて事件と向き合い始める。しかし、真犯人の視線は意外な生徒に向けられており…。', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/db41cf51-b658-46de-b25c-5ab661b1f177.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('33e2d412-d76c-4331-bf04-485f00dfaecc', '0beaa770-0e7f-424e-853a-aacca9751d7f', 10, '100153660', '歓喜', '雛月を救った悟たちは、第2の被害者であった中西彩に接触する。突然現れた悟たちに不信を抱く彩だが、カズの蛮勇もあって秘密基地に誘うことに成功する。そして一方、ヒロミから美里が一人になっているという話を聞いた悟は、美里のあとを追いはじめる。しかし、そんな悟の前に真犯人が現れ…。', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/45686d7b-d20d-449c-be72-897f18883fbf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('858ee783-23a6-4204-bec0-a7b8a7f9055e', '0beaa770-0e7f-424e-853a-aacca9751d7f', 11, '100153661', '未来', '藤沼悟は眠っている。かつて彼がいた場所で。八代学は独白する。かつて飼っていたハムスターのことを。藤沼佐知子は待っている。我が子が目覚めるのを。雛月加代は抱いている。その胸に未来を。そして、みんなが待っている。悟の目覚めを。', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7a758d7-8861-4c38-a3bf-23bf1a92851e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04878492-0d4d-428e-b2ea-6ec456a3336b', '0beaa770-0e7f-424e-853a-aacca9751d7f', 12, '100153662', '宝物', '【最終話】15年の時を経て目を覚ました悟は、事件の記憶を失っていた。違和感にさいなまれつつリハビリを続ける悟の元に、八代が訪れる。誘われるままひと気のない屋上に上がった悟は、すでに記憶が戻っていることを八代に告げる。静かに語り合う二人。そして、ついに決着の時が訪れる……。', '2023/09/29 00:00:00', 1375, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03d7b7dd-67fa-4371-88ce-340c3e8b399d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('74113f95-15a2-46bf-828a-0ee676dea74e', '僕とロボコ', '', 'hulu', 'meandroboco', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e5bab9f-fa79-4ad4-9f17-47166ab92540.jpg?w=331&h=447&p=t', 'hulu', 2023, 0, 1, 'FINISHED', NULL, 150117, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a80314a6-ce5e-4b67-a7d1-e3dad586450e', '74113f95-15a2-46bf-828a-0ee676dea74e', 'hulu-meandroboco-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f61bbbe6-d8ae-47f7-ae7e-6cd1d792d61c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a5ec0ff-f4a9-4a42-bf59-4c9bb783045c', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 1, '100130697', 'ボンドとロボコ', '平凡な小学5年生 平凡人 (たいらボンド) の前に現れた念願のオーダーメイドは膝が「ナッパ」であり思っていたものとは大きく違う、家事も料理も何も出来ないオーダーメイド?「ロボコ」だった…!', '2022/12/05 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f61bbbe6-d8ae-47f7-ae7e-6cd1d792d61c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af6a5be4-c4d8-4623-849d-d91d59e87b0b', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 2, '100130698', 'メイコとロボコ', '念願のオーダーメイドを手に入れたボンドだったが、ガチゴリラとモツオに最新式オーダーメイド「メイコ」を自慢され、ロボコとメイコのどちらのほうがご主人様をよりおもてなしできるかの対決をすることに!', '2022/12/12 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0807825c-557d-4a2f-b5e4-f311bc749d77.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6366057-9746-4e9a-8f71-4d41af8c0d33', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 3, '100130699', 'あの子とロボコ', 'ボンドの家にやってきたみんなの憧れ「円ちゅわ～ん」 緊張しっぱなしのボンドにおもてなしのプロであるロボコがフォローを入れるが、円ちゅわんがボードゲームを始めると何やら様子が一変し…', '2022/12/19 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5878338e-e08a-4800-87a7-08eaafdfe6d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d6cee30-5ffa-4756-99fa-4bddc570ad8d', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 4, '100130700', '山とロボコ', 'ロボコと一緒に秘境の山へ遊びに来たボンドたち。ネイチャーライター「芹澤岳」を救うために化け物熊「熊八」と闘うロボコ。必殺技「ロボコ砲」を撃とうとするが、それには大きなデメリットがあった。', '2022/12/26 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51a82aab-7597-41f8-8aff-4371c0ac6c41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('459d1cba-684b-41c9-84f7-6cf20ee42a2c', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 5, '100130701', 'ロボコ? とロボコ', '「ご主人さま! 起きてくださいご主人様!」いつもの調子でロボコに起こされるボンドだったが、目の前にいたのはいつも見ていたロボコとは姿、かたちがすべて異なる別人のようなロボコ? だった!', '2023/01/09 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d54276ec-5b1d-45e0-be81-21a826546697.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc682865-f6ee-4e5f-a6ad-e86fe34c417f', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 6, '100134302', 'ニョンタとロボコ', '雨の降るとある日、ロボコは道で出会ったネコ? を拾うが、それは普通のネコよりも身体が大きく立派なタテガミを持ち二足歩行も出来る「ニョン」と鳴く謎の生物「ニョンタ」だった', '2023/01/16 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84f24ec0-8a01-497e-bc8d-bad63a159774.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('628dc414-d4ed-42b3-9bad-cd126b048a69', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 7, '100134303', '過去とロボコ', 'ロボコの前に現れた謎の天才科学者「Dr.モッコス」そして明かされるロボコの過去…大切なご主人さまに自分の過去 (黒歴史) がばれないために次々と繰り出される刺客たちをロボコは倒すことができるのか!?', '2023/01/23 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e2c2e67-760c-4f7a-92a1-45da1c8da480.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3be8a31-7839-469d-8cc7-9c0f285b4625', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 8, '100135603', 'ゴリラとロボコ', 'ボンドたちと映画を観に行く予定のガチゴリラ。しかしオーダーメイド「那須さん」の調子が悪く受付の仕事が出来ない状態に…妹「ルリ」たちに受付をさせるわけにもいかずガチゴリラが代わりに受付をするが…', '2023/01/30 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d5d92b0-01e8-4bba-8196-5499de47c611.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9513726f-79a4-4815-817b-a3dac732de98', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 9, '100135604', '秘密とロボコ', 'ロボコの様子が最近おかしいと感じて尾行するボンド。商店街で買い物かと思いきや、街の人たちからも愛され打ち解けている様子を見てボンドも嬉しくなる。そこに「妙々寺トゥカサ」率いるイケメン金持ち小学生グループ「バミュ4」が現れる!', '2023/02/06 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa68a4c7-8cfa-43be-851c-c4a7deb8031b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5eda968d-a4fa-449e-862d-e72f91e8bc38', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 10, '100135605', 'ツイッターとロボコ', 'SNSに興味が無かったボンドだが、クラスメイトに自慢され自分も始めてみたくなり、ロボコに相談してみることに。ガチゴリラやモツオたちのアカウントを少し覗いて楽しんでいたのだが、ロボコのアカウントには驚きのつぶやきが!', '2023/02/13 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/651c2bc9-a2e4-4d37-bbac-c4f8f15d79da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('af39fb71-f060-45d3-b9b0-34d527667075', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 11, '100135606', '雪とロボコ', '空き地で遊ぶ権利をめぐり恐怖の六つ子「睦野兄弟」たちと雪合戦対決をすることになったボンドたち。幼稚園児相手と軽く見ていたが、ガチゴリラ、ロボコまでやられてしまい絶体絶命のピンチに!! モツオの作戦はこの状況を打ち破れるか!?', '2023/02/20 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96e343a4-a63b-4990-805f-98885cf64340.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c230d22-529f-465d-b0fa-88d0d27aad0d', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 12, '100135607', '大食いとロボコ', '軽い気持ちで大食い大会にエントリーをしてしまったボンド。食べる量もそうだが殺伐とした雰囲気が漂う過酷な大食いにボンドはついにダウンしてしまう…そのあとを引き継ぎロボコがこの大喰いに挑む!', '2023/02/27 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/976a50c1-226c-4395-9434-0eac1727f4d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('65550021-a874-4552-b6de-28bb30c62965', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 13, '100135608', 'ママとロボコ', 'ロボコがパワーダウン (弱体化) したところを狙い、勝負を挑んできたDr.モッコスとカニオたち。パワーダウンしたロボコでは全く歯が立たず一方的にやられてしまうが、そのとき意外な人物が助けに現れる!', '2023/03/06 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41641cc9-6191-4fe9-aa8e-de4d7a7aee73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5664fc71-46fc-4945-b500-84c99747ea15', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 14, '100135609', 'カスタムとロボコ', 'オーダーメイドのカスタムパーツでみんなを驚かせようと自分のカスタムに励むロボコ。カスタムの方向が上手く見出せずトライ&エラーを繰り返した結果、辿りついたロボコのカスタム姿とは…?', '2023/03/13 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/265353c8-8964-453c-82d8-2769a4ba6a04.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1fe9593e-ceb8-4a37-819e-707b2473daae', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 15, '100138861', 'モツオとメイコ', 'メイコのご主人さまであり日本で一番忙しい小学生 金尾モツオ。毎日の勉強から習い事、セレブな人との付き合いなどハードスケジュールを完璧にこなしながら、何よりも大事な予定であるボンド、ガチゴリラと遊ぶ約束は必ず守る。そんなモツオとメイコのとある一日のお話!', '2023/03/20 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f50c4d22-d5b0-4d76-9ee5-7804ea2b90bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a748dcbe-5f1d-4927-bbc6-d0ca66247767', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 16, '100138862', 'ボタンとボンド', 'ロボコのへそにある謎のボタン。好奇心でそれを押してしまったボンドはなんと過去の時代へタイムスリップしてしまう…! 現代に戻る方法はただ一つ過去のロボコを見つけ、もう一度へそを押すこと。そんな中、円ちゅわん、ガチゴリラ、モツオとよく似た人たちと出会い…?', '2023/03/27 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35af1354-1aaf-4213-88c7-dbeb1facd709.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93fdf29e-4215-496b-89d6-b3521e600336', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 17, '100138863', 'モツオとゴリラ', '親しい友達で「親友」 心の友達で「心友」 信じあえる友達で「信友」 真実の友達で「真友」…では、ガチゴリラとモツオの二人は一体どれに当てはまるのだろうか!? 二人の一歩も譲れない戦いが今、始まる!', '2023/04/03 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/220c5a5d-f9e5-489e-bcb3-fb29a5c50bfa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3132ae36-eb6c-4c43-83da-ba80e9b75ca3', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 18, '100138864', '造語とロボコ', 'たこ焼きパーティーの最中、ロボコから送られた「寝坊之助食五郎!!」というメッセージ。じっちゃけずらたんなロボコ語を理解しているボンドはみんなにプルトラで意味を説明をしていくが、ロボコが来ないことに気付き…!?', '2023/04/10 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51c278b2-71c0-4f05-abda-3da4e202613c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee5524ce-4834-48cd-838a-31cb0fa9bfb0', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 19, '100138865', '怪談とロボコ', '夜の学校に忘れ物を取りに来たボンドと円ちゅわん。学校に伝わる悪霊、怪異、お化けは本当に存在するのか、しないのか…? ボンドと円ちゅわんの恐怖体験の授業開始を知らせるチャイムが鳴り響く…! そしてあの先生が!?', '2023/04/17 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c6491b9-d144-4971-a75c-b0e898323661.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61c806c3-c58e-464b-a0ad-d268ecf78894', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 20, '100138866', '超能力とロボコ', 'ボンドのクラスに転校生がやってきた。 その名は「三船千鶴」。彼は他人の心の声を聞くことが出来る超能力者だった! ガチゴリラ、モツオたちの心の声を聞き、実は良い奴!? と驚いていたのも束の間…誰よりもウルサイ思考で自己主張の強い心の声のロボコと出会い、彼の心は次第にシンクロしていき…?', '2023/04/24 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7d94ad3-2765-432e-92ee-f695270b0316.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5845cf65-e2be-45fa-b545-214ab7aa4117', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 21, '100138867', '恋とロボコ', '初めてだった…『だんだん心が惹かれていってしまう』この感情は! 胸がトキメキする度にホントにアイツのことを想ってしまう。これ以上どうすればいいのかな? この恋はいつか愛になるからっ! みんな見ててね!!', '2023/05/01 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1d15a2d-5232-4b02-ad95-7aa78860d767.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ffa5a8a-aed6-46af-a64f-c07c3b364977', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 22, '100144444', 'ズボンとボンド', '彼の穿き忘れに気づいたことから始まった二人のミッション…日常のあらゆるものを駆使し、一刻も早くこのミッションを果たすためガチゴリラとモツオは奮闘する。すべてはボンドにズボンを穿かせるため…に…!!', '2023/05/08 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a9d2785d-d7d5-4ec7-9751-43adbd4013d2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62e6f065-e2b7-4c93-998b-87499e0ba38c', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 23, '100144445', '写真とボンド', '自分を良く見せるという点において右に出るものはいません! と強く語るロボコ。写真うつりが悪く落ち込むボンドのために、奇跡の一枚と呼ぶに相応しいベストショットを伝授することに! 奇跡の一枚に必要なもの。それは、リラックスすること、キメ角度を見極めること。行くぜっ! カメラスタンバイッ!', '2023/05/15 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/acc1feb5-47a8-4d61-95b6-6bbd307b4df3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8cc44841-deeb-4e51-92fd-8a34da4fc47b', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 24, '100144446', 'アイドルとロボコ', 'この世界に新たな伝説を生み出す最強ウルトラアイドル「ロボコ」降臨!! 圧倒的な歌唱力、OMとは思えない程の熱き感情表現、聞く人の心にダイレクトに訴えかける魂の叫び! 重そうな身体がダイナミックに地を駆け、宙を舞う圧巻のライブパフォーマンス! 見ててください、ご主人さま、私のデビュー!!', '2023/05/22 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b1be6bd5-9462-4222-8287-052c4b7d6953.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('663a57e0-496c-4cd9-be72-f2fbd554bcbb', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 25, '100144447', '炎上とロボコ', '自身のSNSが炎上してしまいロボコへ相談しにきた「鳥島ミユウ」。SNSのプロであるロボコが伝授する、炎上･アンチへの対処法は何と自ら「いいね」を押してしまうこと。それは「いつもお前のことを見てる」という意思表示であり…。', '2023/05/29 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b446ac9-ec42-4801-b97c-8de2c25d40cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('edd9599f-2c29-4723-873f-f0b70e757dbd', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 26, '100144448', 'ミリーとロボコ', '「お久しぶりです、ロボコ先輩」それは願ってもいない再会だった…だが同時に、過去の自分を知るものと正面から向き合わなければならない清算の時。ロボコの知られざる過去がついに明かされる!? 人類滅亡を目論む組織EDEN「ミリー」、襲来!!', '2023/06/05 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/082b9941-e03f-42a0-a017-f26ef5a13581.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce2c8a65-4951-4752-9519-18f4e2439488', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 27, '100144449', '理想とロボコ', '自身の目標とすべき理想の女性を見つけたロボコ。強く、美しく、パワフルで常にエネルギッシュ、完璧な美しさに逞しい膝。パリコレ出演という圧倒的な実績、親しみやすいキャラクター、そして周囲を幸せにするポジティブな言動の数々…すべてにおいてロボコを上回る理想の人物とは!?', '2023/06/12 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c41e2a0a-eebc-4e3b-972e-b10b6ccd3999.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('332cc9b8-aaf6-4b95-bb77-875812693038', 'a80314a6-ce5e-4b67-a7d1-e3dad586450e', 28, '100144450', '膝とロボコ', '【最終話】そばにいてずっと、守りたい…! いつまでも君を見つめていたい…変わらない想い今、永遠に続く続くロボコ…ありがとう、すべての僕とロボコ…サヨナラ、すべての僕とロボコ', '2023/06/19 12:00:00', 181, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b7ce13bc-d387-4b24-a21d-9dcfff922111.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8092c48e-5557-47b1-803d-3ec52968d412', '僕のヒーローアカデミア', '', 'hulu', 'my-hero-academia', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dfbbd9d6-bfd4-4544-a2be-469348ec91ca.jpg?w=331&h=447&p=t', 'hulu', 2016, 1, 1, 'FINISHED', NULL, 21459, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d9d5d635-d58e-45db-890a-90897da1a78e', '8092c48e-5557-47b1-803d-3ec52968d412', 'hulu-my-hero-academia-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/95a814b5-3f4f-4fa0-af1d-8f428856a4fd.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('83ce3bd9-20da-4f90-919a-7a574c86312d', 'd9d5d635-d58e-45db-890a-90897da1a78e', 1, '60844984', '緑谷出久：オリジン', '総人口の約8割が何らかの超常能力“個性”を持ち、その“個性”によって社会を守る“ヒーロー”」という存在が確立された世界。緑谷出久はヒーローになることを夢見て、多くのヒーローを輩出する名門･雄英高校ヒーロー科入学を目指していた。しかし、彼は何の“個性”を持たない“無個性”。現実の厳しさ、不平等さを痛感する日々を過ごしていた。そんなある日、出久は強盗をして逃亡中だった敵 (ヴィラン) に襲われてしまう。そこに現れたのは、人気･実力共にNo.1のヒーローだった!', '2017/03/15 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/95a814b5-3f4f-4fa0-af1d-8f428856a4fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f5e212f-8f75-4bee-bfa0-8abca1544553', 'd9d5d635-d58e-45db-890a-90897da1a78e', 2, '60844995', 'ヒーローの条件', 'ヘドロヴィランから出久を救ったのは“平和の象徴”とも称されるNo.1ヒーローのオールマイトだった。出久が「個性がなくてもヒーローになれますか?」と彼に問いかけたその瞬間、目の前に現れたのは、過去の戦いにおける重傷で痩せ細ってしまったオールマイトの真の姿!「ヒーローはいつだって命がけ」その過酷さと自身の夢を叶える厳しさを憧れの人から告げられ、出久は絶望する。そんな中、オールマイトが捕まえたはずのヘドロヴィランが逃走し、下校中の爆豪が取り込まれてしまう!', '2017/03/15 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/28c2ba9a-4bcd-4376-a91d-60cdd2fe41fa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29f1dff6-07a7-421c-9466-e1d2d86cdfa8', 'd9d5d635-d58e-45db-890a-90897da1a78e', 3, '60844994', 'うなれ筋肉', '「君はヒーローになれる。」ヴィランに取り込まれそうになる爆豪を救けようと、考えるより先に体が動いた出久にヒーローの資質を見たオールマイトは、彼に自身の”個性”である“ワン･フォー･オール”を授けることを提案する。その個性は、これまで幾人ものヒーローによって受け継がれてきた「力の結晶」だった。ヒーローになる夢を叶えるため、雄英高校に入学するため、オールマイトから課せられたトレーニングに挑む出久。しかしそのトレーニングは想像以上にハードなものだった!', '2017/03/15 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/15cf8a02-cf67-4214-9f17-94a0e8efb9e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e62017d-39e1-40bc-baec-ba2b40c41d88', 'd9d5d635-d58e-45db-890a-90897da1a78e', 4, '60844989', 'スタートライン', 'オールマイトから個性“ワン･フォー･オール”を与えられた出久は、いざ国内最難関と言われる雄英高校ヒーロー科の入試に臨む。広大な模擬市街地で、そこに多数配置された仮想ヴィランを相手に戦いポイントを競うこの試験。皆が“個性”を生かし次々と仮想ヴィランを撃退する一方、まだ“個性”の使い方を理解していない出久はポイントが稼げない。そんな中、予想できないほどの巨大な仮想ヴィランが出現! ビルが倒壊し、その瓦礫の下には…! 出久は“考えるより先に”拳を振り上げ叫ぶ!', '2017/03/15 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/78597f91-4d8c-477f-b3c2-c991a8f89a46.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb329f59-686e-4b53-ab5d-2bb1b627a6ec', 'd9d5d635-d58e-45db-890a-90897da1a78e', 5, '60844985', '今 僕に出来ることを', '雄英高校での学校生活がスタートした。入学初日、1年A組の担任教師･相澤はいきなり生徒たちに「個性把握テスト」を課す。ソフトボール投げや50M走など一見普通の体力測定だが、それぞれがどのように“個性”を活かすかを見るテストだ。さらに相澤は「最下位の者は見込みなしとして除籍処分」というルールを突きつける! 負傷を危惧して“個性”を使わない出久は平凡な記録しか出せない。このままでは初日で除籍となってしまう! 意を決した出久は“個性”を使おうとするが…。', '2017/03/15 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f74a2d9e-e9ff-42a8-a8fb-3e5c281bac23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('102a4cdc-2795-4a5c-9e61-489dd25f9eb5', 'd9d5d635-d58e-45db-890a-90897da1a78e', 6, '60844987', '猛れクソナード', '個性把握テストで“個性”を発動、最小限の負傷で最大限の力を発揮した出久は自らの可能性を示した。翌日、オールマイトによる授業「屋内対人戦闘訓練」が生徒たちに課せられる。2人1組で一方がヒーロー、もう一方がヴィランとして対峙し、制限時間内にヒーロー側が仮想の核兵器を回収もしくは相手を捕獲するという訓練だ。出久はお茶子とヒーロー側のコンビに、対するヴィラン側は飯田と、出久が“個性”を持っていたことに怒り心頭の爆豪。訓練開始と同時に、爆豪が出久に襲い掛かる!', '2017/03/15 00:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/404e524e-a888-423b-a5d9-85b0f567c46b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc2fa7e3-df5d-4ec5-8230-efa94c4c9175', 'd9d5d635-d58e-45db-890a-90897da1a78e', 7, '60844993', 'デクvsかっちゃん', '「対人戦闘訓練」で対峙する出久&お茶子のヒーロー組と、爆豪&飯田のヴィラン組。爆豪は怒りにまかせて暴走し、出久に向かって一直線に襲い掛かる。対する出久は、これまでヒーローを目指すうえで蓄えてきた知識と機転の良さで対抗。コンビを組むお茶子と一緒にこの訓練に勝つための作戦を練る。“無個性”だったはずの、自分より下のはずの出久が“個性”を隠し持っていた…。「俺の方が上だ!」それを完全に証明するために、爆豪はコスチュームに隠された強力な攻撃を放つ!', '2017/03/15 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6f5975e8-d4a6-4048-9e29-4bd9049faab8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19697bac-48e4-4f27-81d8-adeee6002029', 'd9d5d635-d58e-45db-890a-90897da1a78e', 8, '60844992', 'スタートライン、爆豪の。', '戦闘訓練において、暴走し単独でぶつかってきた爆豪に、出久は“訓練に勝つ”ための作戦で、ボロボロになりながらお茶子と共に勝利を収めた。「出久に負けた」その事実に愕然とする爆豪。そして、轟や八百万をはじめ他の生徒たちも戦闘訓練に臨み、彼らはその“個性”と実力の片りんを見せる。放課後、リカバリーガールの治療を受けた出久は、ひとり家に帰ろうとする爆豪を呼び止め、あることを打ち明ける。それを聞いた爆豪が返した言葉とは…。その一方で、謎の影が雄英高校に迫っていた。', '2017/03/15 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/a5ca2388-978b-4add-8ff9-0b0a8efdb05f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cf15232-8333-4412-a238-46408377b6d5', 'd9d5d635-d58e-45db-890a-90897da1a78e', 9, '60844986', 'いいぞガンバレ飯田くん!', '1年A組で学級委員長を決めることに。皆が立候補しての多数決の結果、なんと出久が委員長に決まった。自身も立候補していた飯田は悔しがりながらも、自身が尊敬する兄の話をしながら「自分が人を導くにはまだ早い」と出久を応援する。そんな中、オールマイト目当てのマスコミが校内になだれ込み、生徒たちはパニックに。そこで飯田はある行動に出る! 後日、1年A組は校内の屋外施設「ウソの災害や事故ルーム (USJ)」での救助訓練へ。そこに突如謎のヴィランたちが現れる。', '2017/03/15 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/495ca703-ec3c-4dbd-be93-435a01b5b5c4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb0382a0-1a6e-42d1-b284-60c6f57f45eb', 'd9d5d635-d58e-45db-890a-90897da1a78e', 10, '60844990', '未知との遭遇', '救助訓練に臨もうとした1年A組の生徒たちの前に現れた、死柄木弔率いる“敵 (ヴィラン) 連合”。肌で感じる悪意と「オールマイトを殺す」という言葉に出久は戦慄する。オールマイトが不在の中、相澤は単身ヴィランたちと戦う。しかし、避難しようとした生徒たちはヴィラン･黒霧の“個性”ワープによってUSJ内で散り散りにされてしまう。水難ゾーンに飛ばされた出久、梅雨、峰田にヴィランたちが襲い掛かる! 3人は状況を打開すべく、それぞれの“個性”を活かしてヴィラン撃破に挑む!', '2017/03/15 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/880dbbfd-3ab0-402a-9b23-faa3eec7d9a7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6023a04-698a-43cd-a381-4e1ddf5777d8', 'd9d5d635-d58e-45db-890a-90897da1a78e', 11, '60844988', 'ゲームオーバー', '見事な連携で水難ゾーンのヴィランを撃破した出久、梅雨、峰田は元いた場所に向かう。一方、爆豪や切島、轟たちもそれぞれ飛ばされたゾーンでヴィランたちと戦っていた。そんな中、生徒を守るために単身で戦っていた相澤が、“敵 (ヴィラン) 連合”の中心と見られる男･死柄木弔の謎の“個性”で負傷、さらに死柄木が連れる“改人”脳無の圧倒的なパワーで窮地に陥ってしまう。13号も倒され、駆け付けた出久たちにも最大の危機が近づいたその時、あの男が現れる!「私が来た!」', '2017/03/15 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d477fe2a-88d1-415a-a223-aec107aeab9d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a857432-50b8-4cc8-ba02-f0e824ff6cfa', 'd9d5d635-d58e-45db-890a-90897da1a78e', 12, '60844991', 'オールマイト', 'USJに駆け付けたオールマイトは、素早い動きで重傷を負い拘束されていた相澤を救出。そのまま脳無との戦闘に突入する。しかし脳無は「ショック吸収」「超回復」という複数の“個性”を持っており、さらに黒霧も加勢してきたことで苦戦。オールマイトの活動限界を唯一知る出久はおもわず飛び出す! すると、そこにヴィランを撃退した爆豪、轟、切島も駆けつけた! 危機を脱するも、活動限界が近づくオールマイトはそれでもたちむかっていく。「私は平和の象徴なのだから!」', '2017/03/15 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0fc84c83-a0c4-4bcc-be68-e567cba09ef8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9022695-8d40-45e7-8294-8e074dd65f94', 'd9d5d635-d58e-45db-890a-90897da1a78e', 13, '60844983', '各々の胸に', '【シーズン1 最終話】全発100%以上のラッシュを繰り出し脳無を倒したオールマイト。しかし、活動限界が近づき一歩も動くことができないところに死柄木たちが襲い掛かる。オールマイトの秘密を知る出久は彼を助けるために飛び込んでいく! そこへ駆けつけたのは英雄の教師であるプロヒーローたち! 間一髪で出久とオールマイトは危機を免れ、死柄木は逃走。そんな死柄木の背後には、謎の男の影があるのだった…。身を挺し戦った出久たち。彼らの成長はまだまだこれから。最高のヒーローへ、Plus Ultra!', '2017/03/15 00:00:00', 1455, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9b028b57-b27f-459f-8aa0-742dccacc95b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('db301c65-cebf-41da-bac0-d06994c2e3bd', '8092c48e-5557-47b1-803d-3ec52968d412', 'hulu-my-hero-academia-s2', 'シーズン2', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48c38c83-c3e2-4ac3-98b7-7e47c7753e58.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('978ab71e-7f30-48b0-a595-95d087e161fe', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 13, '100002240', 'ヒーローノート', '総人口の約8割が何等かの超常能力「個性」を持つ世界で「個性」を持たない主人公･緑谷出久がヒーローを目指す。「友情･努力･勝利」の系譜を継ぐ、ジャンプ王道アニメ。', '2017/06/17 18:30:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48c38c83-c3e2-4ac3-98b7-7e47c7753e58.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c70057ba-c9d2-4492-8152-681889a378f2', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 14, '100001831', 'そういうことね お茶子さん', '雄英高校の敵＜ヴィラン＞連合襲撃事件から2日後。相澤から「雄英高校体育祭」の開催が告げられ、ヒーロー科1-A生徒たちの意気は上がる。その中でもお茶子は目の色が変わり…。', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3cf82e9f-c163-4071-bd9b-72ddc5f8419a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f11e1406-aea8-49e6-be59-18f27dab2e3e', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 15, '100001832', 'うなれ体育祭', 'オールマイトから雄英体育祭に向け大きな期待に戸惑う出久、他クラスのライバルたち、闘志をためる爆豪や轟…。いよいよヒーロー候補生たちの祭典「雄英体育祭」が開幕!', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a4b6edc-7930-4209-8d67-8370f05e3499.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45733bb0-f894-46df-8fa5-6dc28ce62cc1', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 16, '100001833', 'みんな個性的でいいね', '第1種目「障害物競争」がスタート、優勝候補の轟はすさまじい冷気の“個性”で先行するが、爆豪たちも負けじとその後を追う。そんな中出久は、機転を利かせた作戦で勝負に挑む!', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49c3dac0-a6fb-4b72-a3fe-de1d5130dc3d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12e37f00-1e4c-403b-b516-1a12b1b364b9', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 17, '100001834', '策策策', '第1種目で1位の出久だったが、その結果1000万ポイントが与えられ、第2種目「騎馬戦」で周囲から標的にされてしまう!“個性”全開で奪い合うサバイバルがスタート!', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e063b31-4667-4dff-b91e-eb431b2d044b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a61710af-64e8-41b0-839b-a9cecfff0593', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 18, '100001835', '騎馬戦決着', '第2種目「騎馬戦」の終盤、出久チームの前に轟チームが立ち塞がり、両者は激しく競り合う! 一方、あくまでトップを目指す爆豪も物間に突進! 果たして騎馬戦を制するのは…!?', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f44b9e0-75e1-4100-88ca-dfe4c32f58f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8aa7f81-3e6e-405c-9343-1aefbdd07fc8', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 19, '100001836', '全てを持って生まれた男の子', '雄英体育祭は本戦である1対1のトーナメント戦へ。そんな中、出久からオールマイトに似た“なにか”を感じた轟は出久を呼び止め、オールマイトを発端とした自らの境遇を話し始める…。', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/124a0f4e-c457-417d-a859-cff130e8e1e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00fad822-64d5-4494-9660-61093f5aae89', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 20, '100001837', '勝ち負け', '本戦1回戦、普通科･心操と対峙した出久は、開始早々に心操の“個性”「洗脳」にかかってしまう。体の自由がきかず、心操に操られる出久。場外負けの指示に従って歩き出すが…。', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80db2304-b540-4cbd-aab3-3db2d1b5dc83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e84b99e1-4a3c-4d7f-8aef-07b7cb0af8fe', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 21, '100001838', '奮え! チャレンジャー', '轟が瀬呂を一瞬で倒し、2回戦で出久と対戦することになった。上鳴vs塩崎、飯田vs発目、常闇vs八百万、青山vs芦戸、切島vs鉄哲、個性がぶつかり合う試合が続いていく!', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/28511add-bf18-45a0-be4a-cdad4d7a39b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3407e48a-3a03-41e2-809b-9d5689d2c27d', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 22, '100001839', '爆豪VS麗日', '爆豪とお茶子の戦いが始まった。先手必勝とばかりにお茶子は爆豪に突進するが、爆豪の「爆破」の前に近づくことができない。そんな中、お茶子が仕掛けた決死の作戦とは…!?', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9fdab8ea-65d5-41ac-bbac-9817115c166a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17ea781e-e3f9-4a49-95d1-a5d2647bc0a0', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 23, '100001840', '轟焦凍：オリジン', '出久VS轟。強力な氷結の“個性”を繰り出してくる轟に対し、出久は自損覚悟で「ワン･フォー･オール」で対抗する! ボロボロになっていく出久の覚悟を目の当たりにした轟は…。', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b68185d-7000-460f-82ef-5ab1eb5ac802.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d56e32b2-d9ef-42b8-8472-dca27ffe3aac', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 24, '100001841', '飯田くんファイト', '出久と轟の戦いは、左手の“個性”を解放した轟が勝利した。そしてトーナメント戦では爆豪と切島が激突。そして、兄インゲニウムのようなヒーローを目指す飯田は、轟との準決勝へ!', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce815cf2-b6ad-427f-8366-36b1d727b1be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce1ab143-3ad3-43c4-a113-410c7ecd73cb', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 25, '100001842', '轟VS爆豪', '爆豪と轟の決勝戦。試合開始から互角の白熱する展開を見せるが、轟は心の迷いから氷結だけの攻撃を続ける。それに対し、爆豪は「全力で来い!」と叫び、大技を繰り出す!', '2017/06/17 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb74731c-81a3-4ab3-9c29-b99418068f9e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e750ca80-4237-409d-a08b-eb6bac4ffeb9', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 26, '100001843', '名前をつけてみようの会', '雄英体育祭が閉幕し、次なる訓練、プロヒーローの「職場体験」に向けて、ヒーロー科1-Aでは生徒のヒーロー名を決めることに。そして、出久にあるヒーローから指名が入り…。', '2017/06/24 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b7a9c34-fddc-4a18-9d4c-acb3f31af866.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f3b424b6-ad1e-4e29-856f-88fac30947c3', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 27, '100003653', '怪奇! グラントリノ現る', '職場体験でオールマイトの師匠･グラントリノを訪ねた出久。訓練の中で「ワン･フォー･オール」を自在に操るためのヒントをつかもうとするが…。一方飯田は、兄の仇ステインを狙い保須市へ!', '2017/07/08 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebf46c53-dc9d-4433-8da9-a84b121959bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfca118d-1bf6-4fdb-b636-8bde72fcd85e', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 28, '100004265', '緑谷と死柄木', '個性「ワン･フォー･オール」を全身に張り巡らせることをつかんだ出久は、グラントリノと早速敵〈ヴィラン〉退治へ! 一方、死柄木とステインは衝突しながらも手を組んだ。そして飯田は…!', '2017/07/15 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fa837df-bdf6-448f-98d8-0b4ebd70c786.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4eae957c-969e-4e04-b966-d6455291ce57', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 29, '100004590', 'ヒーロー殺しステインVS雄英生徒', '死柄木が放った脳無が暴れ、保須市の街は大混乱に! そんな中で飯田はついに兄の仇ステインを発見、憎悪に燃える! そして出久は飯田の危険を感じ、現場へと急ぐが…! VSステイン、開戦!', '2017/07/22 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3390cd47-21f9-461c-8a09-3fdef47ef028.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4ad26f2-1617-4544-8d76-f61b8e6773e7', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 30, '100004767', '決着', '飯田たちを守るために身を挺す出久と轟。そんな2人の姿から自分の心の未熟さを痛感する飯田。それでも、これ以上2人を傷つけないため、2人に追いつくために立ち上がる! VSステイン、決着!', '2017/07/29 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/029b56a8-f642-418b-9a87-041fc619691e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc7b82c5-dd39-4848-bc02-cb30a95e1346', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 31, '100005246', '「ヒーロー殺しステイン」その余波', '出久たちはステインを倒すが、許可なく個性を使って戦ったことが問題になってしまう。そしてステインが見せたそのカリスマ性に刺激され、世間に潜む“悪意”たちが動き出そうとしていた。', '2017/08/05 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c0ad52c-6f8b-4e38-b1bd-e60a0ddb9cd6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('805e2c2e-1ce4-4b28-9a1e-dcf57ec3e190', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 32, '100005755', 'それぞれの職場体験', '出久たちがステインと戦っていたその頃、その他の1-Aメンバーたちも職場体験で奮闘。そんな中、海難ヒーローのセルキーの下で訓練に励んでいた梅雨ちゃんに、密航者が現れたという通報が入る!', '2017/08/12 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/306b3ff2-812a-44ea-abe9-a7bd11ea07d4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6ed4b3b-62b9-4f3a-8be0-a1bbcd1f00be', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 33, '100006080', '知れ!! 昔の話', '職場体験が終わり、生徒たちが学校に戻ってきた。出久は体験先での成長ぶりを授業で見せつける! そして、オールマイトは出久に「ワン･フォー･オール」の成り立ちと、ある悪の存在を打ち明ける―!', '2017/08/19 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8a18ecbd-2f8a-478e-be97-75394d1d5a32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('326917a3-7b11-466c-82d3-9f00dbd7a0b8', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 34, '100006810', '備えろ期末テスト', '期末テストに向けて、生徒たちは猛勉強に励む! 爆豪は成長を続ける出久に敵対心をムキ出しに! そして迎えた期末テスト当日、その演習試験の内容は、雄英教師VS2人1組の生徒のバトルだった!', '2017/09/02 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22589daf-4c0b-4bef-b3f8-18a418e07f2e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccd640bf-73ec-433f-a186-53f8e7c57e03', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 35, '100007114', '八百万：ライジング', '期末テストの演習試験、梅雨ちゃんと常闇がエクトプラズムに挑む! そして轟と八百万は相澤と対戦。体育祭から自信をなくしている八百万、果たして轟と共に試験をクリアすることができるのか!?', '2017/09/09 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13a1fe51-4717-4a08-aa20-4ccfa92ad920.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce99131c-127a-47f5-810d-c81d32adc160', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 36, '100007384', 'むけろ一皮', '生徒コンビVS教師の対決が続く! お茶子は赤面、響く校長の高笑い、耳郎&口田とマイクの“音”対決、葉隠に降りかかるハプニング、そして逃げ惑う峰田がヒーローを目指す理由とは!?', '2017/09/16 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3ced12b5-ff32-4471-8562-1368515e27ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('746d6276-2d1e-48b2-b1b1-320c0a263607', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 37, '100007653', '爆豪勝己：オリジン', '出久&爆豪チームとオールマイトの戦い! 爆豪は出久の言葉に耳を貸さず、まったく噛み合わない2人は一気にピンチへ!「勝つのを諦めないのが君じゃないか!」果たして2人は手を取り合うのか!?', '2017/09/23 18:30:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/927bf4d5-0d84-4294-9e63-5d3c3737a4eb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5bcdb48e-f134-4309-8e44-f7c2e73d64d0', 'db301c65-cebf-41da-bac0-d06994c2e3bd', 38, '100007986', 'エンカウンター', '【シーズン2 最終話】夏の林間合宿に向けてショッピングモールに買い物にやってきた出久たち。そこに現れた1人の影…死柄木弔。出久と死柄木、言葉を交わす2人。そこで死柄木に宿る《信念》とは―!?', '2017/09/30 18:30:00', 1400, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9141182-d244-4b22-96c4-8f6e5bf5dd68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('653770e1-fa49-4415-8089-c87b389a9d97', '8092c48e-5557-47b1-803d-3ec52968d412', 'hulu-my-hero-academia-s3', 'シーズン3', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a04de029-caa1-43e9-9484-d2f5d9e65556.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9d8fd96-030d-420c-9bbb-50ff23c2592b', '653770e1-fa49-4415-8089-c87b389a9d97', 39, '100020276', 'ゲーム･スタート', '雄英高校は夏休みに突入! 家で自主トレーニングに励んでいた出久は、峰田と上鳴に、学校のプールで林間合宿に向けた体力強化訓練をしようと誘われる。その訓練は、2人が女子たちの水着を見るために仕組まれたものだった―! しかし、そうとも知らない出久が他のA組メンバーに声をかけ、峰田と上鳴の悪巧みはあっさり崩れ去る。訓練に励む中、出久たちは、怒涛のように過ぎ去った1学期を思い返すのだった。その頃、敵〈ヴィラン〉連合のアジトでは、死柄木が次の「ゲーム」を始めようとしていた―。', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a04de029-caa1-43e9-9484-d2f5d9e65556.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a8ec8a9-ffd3-42a0-a2c0-9f2927d8582a', '653770e1-fa49-4415-8089-c87b389a9d97', 40, '100020277', 'ワイルド･ワイルド･プッシーキャッツ', '出久たち雄英高校ヒーロー科は、パワーアップのため林間合宿へ出発。しかしその道中、出久たちは途中でバスを降ろされる。待っていたのはヒーローチーム「プッシーキャッツ」だった。そこから宿泊施設まで“魔獣の森”を通って自力で辿り着くよう指示された出久たちに、次々と魔獣たちが襲い掛かる! それぞれが成長ぶりを見せながら進んでいく1-Aメンバーたち。なんとか宿泊施設にたどり着くと、そこにはヒーローを敵視する少年･洸汰の姿があった。一方その頃、敵〈ヴィラン〉連合は林間合宿に狙いを定め…。', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/19bd21c2-8da1-46d0-81ac-3afd16323a80.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('23c15c77-70cf-43ce-b40d-8ea099bf0a97', '653770e1-fa49-4415-8089-c87b389a9d97', 41, '100020278', '洸汰くん', 'ついに始まった“個性”強化訓練。それは、生徒それぞれが自分の個性の「限界突破」を目指すというシンプルなものであった。1年B組のメンバーも合流し、合宿は激しさを増していく。そんな中、出久は洸汰にとっての“ひみつきち”で、個性社会に対する彼の思いを知るのだった。自分と異なる考え方に直面し悩む出久。しかし、答えを出す暇も無く合宿は進行し、レクリエーションの肝試しが始まった。ペアに分かれ、各々が楽しむ最中、突如有毒のガスが森中に広がる。敵連合･開闢行動隊が出久たちを襲う―!', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a35437e-747f-4450-8eba-e8aedfe22c9d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0fde477e-20fa-4cfa-aeb1-ee0e4ac4b6df', '653770e1-fa49-4415-8089-c87b389a9d97', 42, '100020279', '僕のヒーロー', '雄英の林間合宿地に現れた敵連合･開闢行動隊。そのひとり“血狂い”マスキュラーの魔の手が洸汰に迫る。マスキュラーは、洸汰の両親を殺害した犯人だった。そんな危機一髪の状況に現れたのは、出久! 洸汰を守るため、個性「ワン･フォー･オール」で立ち向かう。しかし強力な「筋肉増強」の個性を持つマスキュラーに追い詰められていく。自損覚悟の100%SMASHですらたいしてダメージを与えられない。本気で襲い掛かるマスキュラーに対し、出久は洸汰を守るために、己の限界を超えていく!!', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/32afe5cb-e3fb-4e7c-8716-3c3982ae58db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4c4cc94b-a52e-4aeb-aa78-7b57c26c21af', '653770e1-fa49-4415-8089-c87b389a9d97', 43, '100020280', 'ブチ込む鉄拳!!!', 'マスキュラーを倒した出久は、相澤のもとに洸汰を連れて行き、状況を報告。そして重傷を負いながらもマンダレイのもとに急ぐ。相澤から下された「戦闘許可」と、敵の狙いのひとつが爆豪であることをヒーロー科全員に伝えるためだ。その爆豪は轟と共に敵･ムーンフィッシュと対峙。そして有毒ガスが充満するエリアでは、鉄哲と拳藤がガスの源である敵･マスタードを発見する。しかし、強力な個性と拳銃を持つマスタードに苦戦を強いられる。それでも、勇気を振り絞り、拳藤の個性と、鉄哲の拳がうなる!', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/30aae930-96b7-401d-87cb-48fdbbde0910.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dfeb92b9-50b3-48fc-a66e-1af83a38fb4d', '653770e1-fa49-4415-8089-c87b389a9d97', 44, '100020281', 'がなる風雲急', '出久は、暴走したダークシャドウに取り込まれる常闇に遭遇する。常闇を救けるか、爆豪のところに急ぐか…。「2人とも救けたい」と、出久は居合わせた障子と共に常闇をムーンフィッシュと戦う爆豪と轟のところまで誘導し、ムーンフィッシュを撃退。常闇も自我を取り戻した。一方、お茶子と梅雨ちゃんもトガを何とか退け、出久たちと合流。しかし、一瞬の隙を突かれ、爆豪と常闇を敵のMr.コンプレスに捕われてしまった! 目標を達成し、退却を始める敵連合。爆豪と常闇を救け出すため、出久や轟たちは懸命にその後を追う!!', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8eecd2e2-bd48-4ab6-8c90-366e5cf703d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('413b0440-2f0d-4180-b878-d9805f2a1d05', '653770e1-fa49-4415-8089-c87b389a9d97', 45, '100020282', '転転転!', '爆豪と常闇が敵連合に捕まった! お茶子と梅雨ちゃんの個性でなんとか追いついた出久たちは常闇を取り戻すも、爆豪はそのまま連れ去られてしまう。林間合宿は最悪の結果で幕を閉じ、雄英はバッシングに晒され、オールマイトは自身のふがいなさを責める。しかし、警察の捜査により敵連合に関する有力な情報が入る。一方、入院した出久は、お見舞いに来たA組メンバーから、八百万が個性で作った発信機によって敵連合のアジトの位置が把握できることを聞かされる。そして切島から爆豪救出に誘われ―!', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae851f46-af7b-48db-bde1-3787ad66c43b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4381cead-8403-4a8f-abee-7acf7ee9cea0', '653770e1-fa49-4415-8089-c87b389a9d97', 46, '100020283', '飯田から緑谷へ', '出久は轟と切島から爆豪救出に誘われるが、その行為は許されるものではなかった。悩んだ結果、救出に向かうことに決めた出久は病院を抜け出すも、飯田が止めに現れる。飯田は3人にかつて兄の仇討ちのため暴走した自分を重ね、厳しい言葉を投げかける。しかし出久たちの決意は固く、かつ戦闘なしの隠密行動という。結果、飯田と八百万も監視役として同行することになり、発信機が示す神野区に向かう。一方、敵連合アジトでは、拘束された爆豪が死柄木に仲間になるよう言葉を投げ掛けられていた。爆豪の答えは―!?', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dc1f7b9-2f75-4128-b52b-b2c6609ff9bd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6d567bb-b858-4f3f-b169-6a5683e026c8', '653770e1-fa49-4415-8089-c87b389a9d97', 47, '100020284', 'オール･フォー･ワン', '死柄木の誘いに対し、爆豪は「オールマイトの勝つ姿に憧れた」と言い放ち拒否する。同時に雄英の責任を問う記者会見が行われていたが、それは敵を欺く罠だった! アジトにオールマイトをはじめとするプロヒーローたちが集い、攻勢を仕掛ける。さらにプロヒーローの別動隊が、出久たちが突き止めた脳無工場を制圧した。追い詰められる敵連合。オールマイトの問いかけに対し、死柄木は叫ぶ。「お前が嫌いだ!!」その時、アジトに大量の脳無が出現。そして出久たちの前に“巨悪”オール･フォー･ワンが姿を現す―。', '2018/07/07 00:00:00', 1415, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a490440-1eb8-41b4-af29-b22ba7148295.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f69a4671-0bb9-4ee0-a121-51e2b1a3b48b', '僕の心のヤバイやつ', '', 'hulu', 'the-dangers-in-my-heart', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64328b6c-e1bd-468b-8009-e365464bddc5.jpg?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 153152, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d7a4e57e-b871-4b15-bcda-136f9eed663a', 'f69a4671-0bb9-4ee0-a121-51e2b1a3b48b', 'hulu-the-dangers-in-my-heart-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/776e496e-eb01-4d29-b353-c6ba2e017b3e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91efb606-8460-48ab-9846-88f8315b42ab', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 1, '100141896', 'karte1／僕は奪われた', '重度の中二病中学生･市川京太郎には殺したい女がいる。クラスメイトの美少女･山田杏奈だ。市川は山田の美しい死体姿を妄想し、自己嫌悪を繰り返す毎日を送っていた。ある日、市川にとっての聖域･図書室に行くと、なぜか大口でおにぎりを頬張る山田の姿が。思いもよらない出来事に動揺を隠せない市川。さらに山田は授業の資料を作り出すも、切るものが見当たらない様子。またしても予想外の行動に出る山田に市川は……。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/776e496e-eb01-4d29-b353-c6ba2e017b3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f14896e1-50df-4d13-a116-ac3e0b988a98', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 2, '100141897', 'karte2／僕は死んだ', '数少ない居場所である図書室に、市川はまたしても山田の侵入を許してしまう。しかも今日の山田は“練って美味しい”アノお菓子を持ち込んでいた。ウキウキ顔で袋を開ける姿に、市川の心のツッコミが止まらない! また蒸し暑いある日の図書室では、暑がりの山田が市川の扇子で顔を仰いでいた。扇子からいい匂いがするからと、市川にも嗅がせようと手招く。市川がおずおずと扇子に顔を近づけると、そこには衝撃的な光景が。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5c060c5-462d-471d-aefc-32fc07ec8be1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82b9fa63-403b-47dc-8607-a5c296496d4b', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 3, '100141898', 'karte3／僕は抱きしめたい', 'モデルをしている山田は、同級生男子の注目の的。思春期まっさかりの足立翔は、友達の神崎健太･太田力と共に「女子にエッチなことを聞く」ゲス･オブ･ゲスゲームをおっぱじめていた。山田やその親友･小林ちひろ達女子に、声をかけようとする足立。山田にそんなことを聞くなと、市川も冷や汗をかきっぱなし。さらに足立は市川に、山田へメモを渡してほしいという。メモの中身は下世話な内容に違いない。どうする市川――!?', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f470ff69-1298-4f23-89f8-3027a6135502.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ee65ab0-4ddb-4ef6-bd3f-836945d55997', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 4, '100141899', 'karte4／僕は心の病', '山田への気持ちに気づいた市川。今まで以上に彼女の姿を目で追っていると、同じように山田のことを気にしているクラスメイト･金生谷倫が目に留まる。彼女は山田の鼻にバスケットボールをぶつけた張本人。気まずくて、まだ謝ることができずにいたようだ。山田の友達･吉田芹那と共に、山田と金生谷の様子を見守るが……。そして放課後、市川が新品の自転車で帰宅していると再び山田と遭遇。しかも、「乗せてって?」と頼まれて――!?', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a8f1a66-7683-4ae2-ab7b-85d740e14d9a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51ea2727-5b5c-40a9-a2f0-975a10c36c75', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 5, '100141900', 'karte5／僕らははぐれた', '職業見学に向けてクラスではグループづくりの真っ最中。市川は足立に誘われるも、人数の問題を建前に山田ら女子と合流しようということに。運よく山田と同じグループになれるかと喜ぶ市川だったが、関根主導で女子による男子の容赦ないドラフト会議が始まる……。さらに放課後、市川は図書室で山田と原さんが楽しそうに話しているところに遭遇。萌えマンガ的な空気が醸し出されるも、話題は恋バナ。会話が気になって仕方ない!', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1793e523-1015-4bde-bee7-3646e027479d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ee9a193-24d9-4f21-9ad2-95728b421687', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 6, '100141901', 'karte6／僕は溶かした', '職業見学の帰り道、市川と山田は電車に乗り遅れてグループからはぐれてしまう。みんなに声をかけなかった自分のせいだと思わず泣いてしまう山田。そんな山田に市川がとった行動は……。そんなドキドキの職業見学から数日後、市川は掲示板の前で深刻な顔をした山田を見つける。視線の先には「図書室で飲食禁止」の張り紙が。お菓子を食べられないなら山田が図書室に来る理由もない。つまり……2人の時間も終わりってこと!?', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72cf3758-3d74-4027-ae5f-be201a26d970.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('800d70b0-72fa-4371-8f88-28616b22b99c', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 7, '100141902', 'karte7／僕らは入れ替わってる', 'イベント行事も案外悪くないと感じ始めていた市川。今日は体育の持久走。並んで走る市川と山田だったが、山田は体操着を前後逆に着ていることに気づき、その場で腕を抜いて服の前後を入れ替え始める! 思わず目が離せずにいる市川。一方で山田も、市川のゆれる前髪から覗く右目を初めて見たと笑いかけきて……。その後、教室に戻るも山田は間違って市川のジャージを着ていた! 市川はこの事実を一刻も早く伝えようとするが――!?', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3eec79a-bf31-4ca7-a321-39de78aef02f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5522bf40-b0ba-4211-b773-066bd7c9b6c9', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 8, '100141903', 'karte8／僕は夢を見た', '地獄の三者面談の日がやってきた。母親と一緒にいるのが照れくさい市川は陰から様子を伺うが、そこで山田と母親が話しているところを目撃する! 気が気でない市川をよそに、2人の会話は弾んで……。また雨の日の放課後、山田の忘れ物を届けに行った市川が雨に濡れたせいで熱を出してしまう。ひさしぶりに学校を休みひとりで家にいると、突然チャイムの音が。門の外に見えたのは山田の姿で……!?', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad73ad1a-3e17-4672-a2cd-e76143c856ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99025360-994a-4664-a8d2-9402bf7735c6', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 9, '100141904', 'karte9／僕は山田が嫌い', '山田に突如、「LINEやってる?」と尋ねられた市川。“友達がいなくてもLINEくらいやるだろ!”と心のツッコミをいれながら、ついつれない態度を取ってしまう。そして教室では、山田の友達･関根萌子が、彼ピ欲しさからクラスの男子全員とLINEを交換しようと言い出す。名案とばかりに山田は、さっそく市川に声をかけようとするも、関根はそれを遮る。しかも関根が市川とLINEを交換して楽しげな様子。そんなふたりに山田は――!?', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee85f36a-69f1-4081-a471-6646a660bb55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41508bb5-bdfd-439a-b366-80fe8ae7b1a1', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 10, '100141905', 'karte10／僕らはゆっくり歩いた', 'マンガの続きを山田から借りることになった市川。待ち合わせ場所はクリスマスイブの渋谷。いつにも増してかわいい山田は、少し照れながらも市川を繁華街に連れ出す。オシャレなカフェに入るものの、慣れない空間に気後れした市川は、小さなやらかしをいくつも重ねてひとり落ち込んでしまうのだった。その後、山田の服選びの買い物に付き合い、試着室の前で彼女を待っていると、よりによって市川の姉・香菜が来店してきて――!?', '2024/10/01 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c552a2a8-cd25-41a4-8c5a-4348428ea3dc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a32df42a-2f23-46f2-90de-64ce64adaa85', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 11, '100141906', 'karte11／僕らは少し似ている', '年の瀬のファミレスに、深刻な顔で黙り込む市川がいた。腕には包帯。隣には関根、そして「ナンパイ」こと南条ハルヤの姿が……。時間は４日前に遡る。市川は家族で秋田の実家に帰省していた。山田とLINEをするようになった彼は、雪景色の写真を彼女に送ると約束する。ところがよい写真を撮ることに夢中になってしまい、足を滑らせ腕を骨折してしまう。夜、そのことをLINEで伝えると、すぐに山田から“ビデオ通話”の着信があって……。', '2024/10/01 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9265f6ea-c509-4d42-8627-93e2b46f020f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e31cfc23-a676-4578-962c-7fe4d0bc71ca', 'd7a4e57e-b871-4b15-bcda-136f9eed663a', 12, '100141907', 'karte12／僕は僕を知ってほしい', '【最終話】新年を迎え、一緒に初詣へ行こうと約束した市川と山田。市川は家族で参拝した後に会うつもりでいたが、約束の時間のだいぶ前から待っていた山田を見つけて驚く。山田が市川の家族に挨拶すると、そのままみんなで参拝することに。さらに山田のことが知りたい香菜は、山田を市川家に誘う。愛弟と山田の関係に可能性を感じた彼女は、恋のキューピッドよろしく、卒業アルバムを開きながら弟の小学生時代を語って聞かせるのだった。', '2024/10/01 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8fa691c9-9353-487a-8ff2-77e7e89be078.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('021155b6-3361-4a5b-9e43-921f310b96df', '僕の心のヤバイやつ', '', 'hulu', 'the-dangers-in-my-heart-season2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3c247e5-09df-46df-b5c5-5566e4dcbe60.jpg?w=331&h=447&p=t', 'hulu', 2023, 1, 1, 'FINISHED', NULL, 153152, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fa8ee0e4-3585-422d-be37-f6532601d372', '021155b6-3361-4a5b-9e43-921f310b96df', 'hulu-the-dangers-in-my-heart-season2-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f867857-64f9-49b3-9ff1-2506ae2cf88d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e02db5c9-e2d1-421b-b406-468fc113d68c', 'fa8ee0e4-3585-422d-be37-f6532601d372', 1, '100170115', 'ツイヤバ', '原作者･桜井のりおの公式X (旧：Twitter) にて公開されてきた「僕の心のヤバイやつ」の、ショート漫画や小ネタがまとめられたスピンオフ的な存在「ツイヤバ」。「お互いの血液型を当てる血液型クイズ」、「ジャージ越しに交わされる闇取引という名の飴交換」、「市川が好きな女子の髪型トーク」など、陰キャな市川と天真爛漫な山田を中心に何気ないながらもクスっと笑える日常が描かれる。', '2024/10/01 00:00:00', 1267, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f867857-64f9-49b3-9ff1-2506ae2cf88d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('601a6e66-4695-4106-b8da-1333b3dd2eeb', 'fa8ee0e4-3585-422d-be37-f6532601d372', 2, '100170116', 'karte13／僕らは探している', 'ついに三学期が始まるも、腕を骨折している市川は少し不便な学生生活を送っていた。担任から仲が良いからと山田による介助を提案されるも、市川はつい「仲良いとかじゃないんで」と断ってしまう。しかし間の悪いことに、その会話を山田が聞いていて……。焦りまくる市川だったが、一方で山田は、クラスメイトの足立にお願いしてさりげなくサポートしてくれる。彼女の優しさを改めて感じた市川は、押し殺していた心の声を少しだけ山田に伝える……。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afe1a6cc-5692-4ef5-9cf6-b8e80d93837d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('44a06551-0b74-4a76-aa15-8dd99d940292', 'fa8ee0e4-3585-422d-be37-f6532601d372', 3, '100170117', 'karte14／僕は大人のなりかけ', '雪が降るなか、山田が失くしたキーホルダーを必死になって見つけた市川。山田は家がすぐそこだからと、体が冷えた市川を自宅へと招く。初めて訪れた山田家で、言われるがままお風呂を勧められて全裸になる状況に、市川は動揺しまくる。なんとか心を落ち着けてお風呂から上がると、今度はパンツが見当たらない！パンツを回収するため、用意された山田のジャージを着て脱衣所から抜け出すも、眼の前にはいつもとは違う部屋着姿の山田が現れて――!?', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae8ab50e-bb7b-46e0-befa-617517d938c7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9eda5a5b-666e-4826-be9e-98b464838151', 'fa8ee0e4-3585-422d-be37-f6532601d372', 4, '100170118', 'karte15／僕は山田と', 'バレンタインデーまであと一週間! 山田･小林･関根･吉田となぜか参加することになった市川は、山田家で手作りチョコの試作会をすることに。出迎えた山田の母が、急に現れた男子の市川を見て怪訝な顔をすると、機転を利かせた関根が「彼ぴ――的な?」と自分の彼氏だとウソをつく。話を合わせるため、その後もイチャイチャする関根と市川。モヤモヤする山田……。市川はギスギスした空気にビビりつつも、山田の母を誤解させたままでいるのはよくないと思い――。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36088882-36f8-4d4d-831c-6ba735f6f831.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae841676-cf3e-45c5-bf88-d420efe31b48', 'fa8ee0e4-3585-422d-be37-f6532601d372', 5, '100170119', 'karte16／山田は僕を', 'バレンタインデー当日、気もそぞろな足立をよそに市川はいつもと変わらない一日を過ごそうとしていた。一方の山田は廊下を何度も往復して女子からの友チョコを集めて回ったり、萌子手作りの義理チョコを市川から横取りしたりするなど、いつも以上に変な様子だ。放課後、チョコまんを頬張りながら山田はおずおずと「どんなチョコなら本命だと思う?」と市川に質問する。そんな彼女が手に持つ袋の中には、あるものが隠されていた……。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84312392-df6a-46de-a008-8ce2df5a5971.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ab70c82-a57b-433e-b1de-464192f984d8', 'fa8ee0e4-3585-422d-be37-f6532601d372', 6, '100170120', 'karte17／僕は知りたい', '放課後、一緒に映画を見に行くことになった市川と山田。映画館に向かう途中、たまたま立ち寄ったたこ焼き屋で、バイト中の香菜と遭遇! 2人の制服デートを羨ましがられてしまう。さらに市川は、熱い物を食べるのが苦手な山田のために、楊枝でたこ焼きを食べさせてあげるなどふたりの距離は近づく一方! 映画が始まると、尊敬する事務所の先輩の演技を真剣に見つめる山田。その横顔を目にした市川は、自分の知らない山田をもっと知りたいと思う。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/367a2fe6-f27c-41e1-ac0c-4b811d2dccce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07618f6e-c59d-426b-a34e-40ff075624a2', 'fa8ee0e4-3585-422d-be37-f6532601d372', 7, '100170121', 'karte18／山田は僕が好き', '卒業式のリハーサルで在校生代表の送辞を読んでほしいと頼まれる市川。山田からの期待の眼差しに背中を押されて挑戦することにするも、緊張してしまい声を張ることができなかった。気落ちする市川に、山田は「発声のレッスンとかやってるから」と色々とアドバイスをくれる。そんな2人は偶然、南条が女子に告白されているところを目撃。彼が山田に本気なことを知った市川は、胸を張れる自分を見せたいと、もう一度壇上に立つ決心をする。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37ad91bd-3ac6-4e7d-9a1d-0db10c611408.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9576d5b9-c1bb-4262-9dcf-3519738c9202', 'fa8ee0e4-3585-422d-be37-f6532601d372', 8, '100170122', 'karte19／僕らは溢れ出る', '山田の「好きな人がいる」という言葉の真意が気になって仕方がない市川。山田が、自分のことが好きかもしれないと思いながらも、なんとか心を落ち着けようとする。しかし、山田が男子も参加するバスケ部のカラオケ会に参加すると聞き、キモイと思いながらも隣の部屋から様子を伺ってしまう! またある日、図書室にいる市川に原さんが声をかける。彼女は3月14日に、市川と山田、神崎と自分の4人で出かけようと誘ってきて……。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92b5403b-8da6-4cf0-ab30-cb45b3b42f35.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91eea6c4-edaa-4a16-b57e-47baad4f39b4', 'fa8ee0e4-3585-422d-be37-f6532601d372', 9, '100170123', 'karte20／僕らは夜更かしした', '終業式がやってきた。3年生になったらもう、別々のクラスになってしまうかもしれない……。放課後、市川がクラスでひとり思い出に浸っていると、山田から体育館に呼び出される。顔を出すと山田がひとりバスケットボールで遊んでおり、「負けた方が勝った方の言うことを何でも聞く」というルールで1 on1を挑んできた。簡単に決着がつかないなか、市川が「これが入ったら告白する」と渾身のシュートを打つ！果たして結果は……。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1c060f2-cb49-49ea-bd34-5629eba9807f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6bc57d77-6c8b-4173-9db2-3c846ae01c40', 'fa8ee0e4-3585-422d-be37-f6532601d372', 10, '100170124', 'karte21／僕らは約束した', '市川家にお泊りした翌日、山田は映画の撮影で広島へと旅立っていった。市川は山田が芸能人であることを再認識しながらスマホを眺めていると、彼女が市川家で撮った写真をSNSに載せているのを発見! しかもリプ欄には彼氏の存在を疑う粘着質なファンが。つい気になってそのアカウントを追うと、山田へのファンなのかアンチなのかわからない投稿をしており、市川は心配で気が気でない。さらに追い打ちをかけるように、山田と電話が突然途絶えてしまって!?', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57a1b143-e9a9-47ca-950a-cb87dc14cc8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d515d4fe-90ed-4e28-b6cc-5ebed46dd71f', 'fa8ee0e4-3585-422d-be37-f6532601d372', 11, '100170125', 'karte22／僕は山田に近づきたい', '3年に進級した市川。新たなクラスへ向かうと、そこには見慣れたメンバーもいつつ、安堂カンナや半沢ユリネなど個性豊かなクラスメイトたちが。教室で市川と山田が仲良さげに話していると、鋭く勘を働かせるのは安堂。彼女はカップルになりそうな男女を見つけては告白を応援し、これでもかと盛り上げようとするお祝い好き女子だった。なんとしても彼女にだけは、山田への気持ちを悟られないように警戒する市川だが……。', '2024/10/01 00:00:00', 1383, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/748505cb-6783-4c8d-985f-75907cdf966c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0c94d49c-21dd-4eb0-b5c9-36065f98a0a3', 'fa8ee0e4-3585-422d-be37-f6532601d372', 12, '100170126', 'karte23／僕は負けたくない', '中学最後の体育祭が迫っていた。市川はクラスメイトの強面男子･鵠沼から騎馬戦の騎手をやってほしいと頼まれる。乗り気でないと断ろうとする市川に、足立が騎馬戦でのタイマン勝負を挑んできた。足立は、自分が好きな山田と自分以上に仲がいい市川に、対抗心を燃やしていたのだ。いつものふざけた様子とは違う真剣な姿に、市川は「やる」と返事をする。勝敗に意味なんてないと考えつつも、「負けたくない」という思いから特訓を開始するが……。', '2024/10/01 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff21e322-2543-4fc0-b050-5e4214184fd1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4ea36a2-37d1-4d13-b65e-85ca55ea177d', 'fa8ee0e4-3585-422d-be37-f6532601d372', 13, '100170127', 'karte24／僕は伝えたい', '修学旅行が間近に迫り、盛り上がる市川のクラス。ところが山田は旅行の日程を知ると驚いた顔を見せ、その後も表情が冴えない。帰宅後、市川がひとり今日の山田について考えていると、イマジナリー京太郎が出現。修学旅行といえば初キスなどと、甘～い妄想をさせられていると、山田からビデオ通話が。今日様子が変だったと山田に聞いてみるも、市川の枕元に林間学校の冊子を見つけた途端、山田は「何でもない!!」と無理に明るく振舞いだし……。', '2024/10/01 00:00:00', 1368, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a8175452-8736-4fb5-b86a-961b2ca3187c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5eb91eb-557d-4818-a4f7-d6455a4e5ac3', 'fa8ee0e4-3585-422d-be37-f6532601d372', 14, '100170128', 'karte25／僕と私の恋心', '【第2期 最終話】修学旅行の最終日と同じ日に行われるドラマ版『君オク』のオーディション。山田は市川のことを思って、大好きな作品のオーディションを諦めようとしていた。それを知った市川は山田と会って話をしようと決意する。――しかしなぜか、今彼は女子部屋の布団の中で、山田とこれでもかと密着していた。ほかのみんなに見つかったら大騒ぎになってしまう。この絶体絶命の状況から市川は無事脱出できるのか。そして山田に、ちゃんと伝えられるのか!?', '2024/10/01 00:00:00', 1374, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d2f8789e-2492-430d-87b1-5fe9992cf42e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d26696fe-584c-41e4-a150-a83a5954f6e8', '僕らの雨いろプロトコル', '', 'hulu', 'our-rainy-protocol', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2a3c6ca-77a4-40ad-ad4b-5da94b9c7ef7.jpg?w=331&h=447&p=t', 'hulu', 2023, 3, 1, 'FINISHED', NULL, 166896, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('6109b47e-9b34-4c39-9225-cd52b5e896ff', 'd26696fe-584c-41e4-a150-a83a5954f6e8', 'hulu-our-rainy-protocol-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bef343e0-f4ac-424d-a9ba-a73a558c8413.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74547ff1-00d7-4eef-ad9e-cabb3454ef95', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 1, '100161953', 'あきらめた未来 －Cold Reboot－', '高校生になった瞬は、家計を助けるため、幼馴染である望の父が経営するeスポーツカフェ「FOX ONE」でバイトをしていた。ある日、店が運営するeスポーツチーム「Team FOX ONE」のメンバー全員が突然チームを脱退。さらに店には多額の借金があることが発覚する。とある事件をきっかけにゲームから身を引いていた瞬だが、eスポーツ大会で賞金を獲得し借金を返済する為、幼馴染たちとチームを結成する。かつての仲間と再び入ったゲームの世界で瞬の目に映るものは…。', '2023/10/11 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bef343e0-f4ac-424d-a9ba-a73a558c8413.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afd677f7-11c2-41b8-a13b-33be0de377d7', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 2, '100162652', '選ばれた邂逅 －Multiplexer－', '瞬は、足が不自由な妹･美桜や、女手一つで家を支えてくれる母に対して後ろめたい気持ちを抱きながらも、望の父が経営するeスポーツカフェ「FOX ONE」の借金返済のため、eスポーツに復帰する。「Team FOX ONE」の瞬、暁斗、望はeスポーツゲーム「ザクセリオン」の大会に出場し、優勝賞金を獲得するために動き出した。1チーム5人のプレイヤーが必要なため、残り2人のプレイヤーを募集する瞬達だったが、期待も虚しく成果が上がらない。そんな中、瞬たちの前に奇妙な人物が現れる。', '2023/10/18 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5a362ee-6f7b-470d-93d4-69269204cea4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2576fbba-c434-4719-bec4-46cd506cc44c', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 3, '100163633', '僕らの始まり －Astable Multivibrator－', '「ビッグバン･インフィニティー」を追う瞬、暁斗、望、流星が追跡した先に見たものは、おんぼろアパートの汚部屋に住む新人女優「ユウ」だった。顔出しNGの悠宇 (ユウ) は、匿名、覆面で正体を隠すという条件でチームに加入する。かくして「Team FOX ONE」に5人のプレイヤーが集まった。「ザクセリオン･チャンピオンシップ」への参加に向け、目まぐるしく準備が進む中、瞬は過去のオンライン仲間である「ばくれつ君」と言葉を重ねる。そして、大会当日を迎えた瞬は、1人の男と邂逅する。', '2023/10/25 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/500dc833-583d-4151-8c5f-bdb2a3b1a4bf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6cd8286b-aa44-4dda-b7c4-e2c9734b6eb7', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 4, '100164304', '繋がる願い －3way Handshaking－', '「ザクセリオン･チャンピオンシップ」に参加する瞬たちと、その前に立ちはだかる優勝候補チーム「スリーピングアウル」。そのチームに居たのは、内嶋睦生こと「ROX」と「Team FOX ONE」を脱退した「JONATHAN」だった。圧倒的な経験値の差に苦戦する瞬たち。ギリギリの場面で『大丈夫。死ぬ時は一緒だ』とメンバーにかつての口癖を言う瞬。その言葉を受けた悠宇は何を思うのか。「Team FOX ONE」の緊張の初戦、それぞれの想いが交錯する中、負けられない激闘がついに始まる。', '2023/11/01 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f77a8fd5-bf3b-463b-86e1-1bc64923113e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3694e7df-3fe6-4e91-a29f-046dc7ce0746', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 5, '100165399', '迷わない決意 －Logic Gate－', '激闘から一夜明け、瞬は美桜との何気ない朝の時間を過ごす。昨日の瞬の雄姿を嬉しく思う美桜と、家族に対して、自分だけゲームをやっていた後ろめたい気持ちを抱える瞬。チグハグとした会話で、美桜の胸に虚しさが少しずつ積もっていく。「Team FOX ONE」は優勝まで残り2回の勝利を収めなければならない。そんな中、再び瞬達の前に立ちはだかる「スリーピングアウル」。昨日の勢いのまま勝利に向かい奮闘する瞬たちだが、内嶋睦生が1人、怪しく動き出す…。', '2023/11/08 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ec7448f-5aa3-4118-b896-89e6c42588af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('732727c9-7903-4cdb-9ff9-e29b9ace9e33', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 6, '100165738', '消えない記憶 －One Time Programmable ROM－', '「スリーピングアウル」に惨敗を喫した瞬たちだったが、準優勝の賞金を手に入れたことで、「FOX ONE」が存続できることになる。次の大会での勝利を誓う暁斗達をよそに、瞬は妹と母のことを想い、ゲームから退こうとする。オンラインチャットで、瞬は「ばくれつ君」に悩みを打ち明ける。「瞬は俺を助けてくれた。俺のヒーロー」だと瞬に伝える「ばくれつ君」。そんな中、舞い込む美桜のリハビリの提案。瞬に決断の時が迫る。そして再び瞬の前に現れる睦生から突きつけられた真実とは。', '2023/11/15 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f318ebb1-afb7-4cf6-8965-0211f33088c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c384ccd9-f66b-4c30-9eaa-202335f38129', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 7, '100166594', '無垢な想い －Solidstate Memory－', '戦績を上げ、知名度を上げていく「Team FOX ONE」。機を見たオーナーの颯太は、総勢128チームが参加する大きな舞台であるプロリーグ「ザクセリオン･ビットテクニカリーグ」への参加を決め、チームも颯太の期待に応えるべく団結を強めていく。しかし瞬は、強さと勝利を求められる状況に、睦生の言葉を思い出し苦悩する。心身ともに疲弊する瞬は、チームメンバーと母の優しさに触れる。そして瞬以外にも、揺れ動く想いを抱える人物が…。', '2023/11/22 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c71ae31-1123-41fc-b632-39a782b1d8ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5855131c-eb86-41ce-893d-c72dc5ab4a8e', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 8, '100166985', 'ターニングポイント －Flip Flop－', 'eスポーツに全力で励む瞬に対して気持ちを告げる美桜。誰よりも瞬の近くに居る人物からの、飾り気の無い残酷な言葉を受けた瞬は何を思うのか…。そして、「Team FOX ONE」はプロリーグ「ザクセリオン･ビットテクニカリーグ」に参加するも、良い戦績を挙げられないでいた。焦る瞬たちの前に現れたのは、過去の「Team FOX ONE」のファン、星詩流。彼女からの苦言混じりのアドバイスを受ける瞬たちは、勝利への道筋を探し奔走する。', '2023/11/29 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/693c032a-41f2-4eaa-9bf2-39930d4c1cd3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b4f9bdb6-3d5a-430e-861e-5b401879ca7d', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 9, '100167754', '崩れる萌 －Latch Up－', '星詩流と恵美子の協力もあり、辛うじて決勝リーグである「Invitational」への参加権を手に入れた「Team FOX ONE」。プロチーム昇格へと、一つずつ駒を進めていく。チームの皆は、手に入れた賞金を美桜の入院に役立てて欲しいと瞬に手渡す。その温情に感謝する瞬だったが、美桜からの返答は思いがけないものだった。大切に思うが故に衝突する兄妹。そして、そこに現れる内嶋睦生。彼の言葉に瞬は――', '2023/12/06 01:30:00', 1396, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e529266-2079-491d-ae6a-608e31682a64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a396ea09-2ff7-4d3d-bc61-f5fc8d6b1f33', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 10, '100168604', '譲れない望み －XOR－', '「美桜の脚は治っている」母から、妹の診断結果を聞かされる瞬。受け入れ難い瞬だったが、睦生の指摘と、現実に美桜の身体に起きていることの辻褄が合っていく。「原因は君だ」「君がいて、歩けなくしている」睦生の残酷な言葉が、瞬を悩ませる。そして、新人女優としての階段を駆け上がる「ユウ」と、ゲームで瞬たちと共闘する「悠宇」にも、選ぶことのできない苦渋の選択が迫っていた…。各々の苦悩が膨らみながら、刻一刻と試合の時間が近づく。', '2023/12/13 01:30:00', 1381, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9e109dc0-ebb5-41a0-909b-6f20e95f7130.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cf666d1-d47f-4e1a-91a4-93147c337049', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 11, '100169271', 'オール･オア･ナッシング －Schmitt Trigger－', '快進撃を続けるチーム「スリーピングアウル」は、いち早く選抜通過まで駒を進め、プロリーグ参加を果たす。一方、瞬たちは苦戦を強いられ、一度も負けを許されない危機的状況に立たされてしまう。宿敵「スリーピングアウル」との負けられない戦いに挑む瞬は、先日の一件以来、会うことを避けていた美桜と顔を合わせる。そして、兄妹の大切な約束を交わす。悠宇もまた、マネージャーからの言葉に苦悩し、揺れ動く。チームのため、瞬のために悠宇は決断する。', '2023/12/20 01:30:00', 1381, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b032147e-22d2-4fae-b99e-b0d8018a5580.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08983211-142f-4770-917c-61a86b4b11d5', '6109b47e-9b34-4c39-9225-cd52b5e896ff', 12, '100170181', '約束 －Protocol－', 'プロリーグに参加するため、家族のため、仲間のため、過去に自分を救ってくれた友のため、各々の譲れないものを持つ少年少女たち。「Team FOX ONE」は一丸となって、強豪「スリーピングアウル」に挑む。美桜と聡美、「FOX ONE」の皆が見守る中、戦いの火蓋が切って落とされた。睦生による冷酷で容赦のない作戦に苦戦を余儀なくされる瞬たちだが、激闘の最中一つの奇跡が起きる。オンラインで紡がれる、少年少女と、家族の物語、ここに完結。', '2023/12/27 01:30:00', 1381, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6bce845-15c8-4f46-95bd-1cdbb91ef329.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('21355f27-594a-437a-ae89-c55489a59f91', '没落予定の貴族だけど、暇だったから魔法を極めてみた', '', 'hulu', 'im-a-noble-on-the-brink-of-ruin-so-i-might-as-well-try-mastering-magic', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/18dd3d37-0f38-4854-8b8f-20cc7339cab2.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 176063, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f7e0a8b9-392c-4cea-a2e9-41daa7e68943', '21355f27-594a-437a-ae89-c55489a59f91', 'hulu-im-a-noble-on-the-brink-of-ruin-so-i-might-as-well-try-mastering-magic-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc4a457e-f886-4995-8c0d-295a3239dddc.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb682983-ac47-49c1-b4dc-ce816b38c06d', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 1, '100212409', 'リアム、初めて魔法を使ってみた', 'ある日突然、庶民の男はハミルトン伯爵家の五男、リアムの体になっていた。リアムとして生活する中で、ハミルトン家は没落寸前であり、五男のリアムはいずれ家を出ることになると知る。貴族としてのしがらみのないリアムは、庶民の頃に憧れていた『魔法』を学ぶことに夢中になっていく!', '2025/01/10 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc4a457e-f886-4995-8c0d-295a3239dddc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7ab3765-550d-46a8-923e-4ea3dc3246c9', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 2, '100212813', 'リアム、冒険者になってみた', '魔法を使えるようになったリアムに、ハミルトン家長男のアルブレビトは、独立のための仕事としてハンターギルドを紹介する。ギルドを訪れたリアムは、ハンターの女の子･アスナと出会い、パーティーを組んで依頼に挑むことに。だが討伐対象は、魔法の効かないモンスターだった……!', '2025/01/17 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb54952d-2022-4960-8440-2cfa2eb8c4e7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e52ffdde-5975-4e00-98be-98ac618963ba', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 3, '100213722', 'リアム、魔竜と話してみた', '順調に功績をあげるリアムに、危機感を抱くアルブレビト。アルブレビトは功を焦るあまり、かつてハミルトン家の先祖が封じた魔竜ラードーンの封印を解き、討伐しようとする。討伐失敗の知らせを聞いたリアムは、魔竜のいる森に急行し、惨状を目の当たりにする。再封印すべく、リアムは魔竜と対峙する……!', '2025/01/24 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5cee6cc2-067a-4312-951c-1cf0a37267c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ded2b72d-7848-4733-af5a-0171d5b64a93', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 4, '100214486', 'リアム、エルフを使い魔にしてみた', '体に宿ったラードーンの力により、新たな魔法を覚えたリアム。リアムはラードーンに頼まれ、ラードーンの封印されていた森に向かう。森にはラードーンが保護していたピクシーたちが住んでおり、リアムはラードーンの代わりをすることに。だが、ラードーンの結界が解けた森は、もはや安全ではなく……。', '2025/01/31 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13c96766-2b4d-479c-9280-181072d3e562.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ac5f327-d897-42b4-9179-21f196cc1336', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 5, '100215230', 'リアム、王女様と婚約してみた', '復活した約束の地で、新たな村作りを進めるリアム。約束の地はジャミール王国、キスタドール王国、パルタ公国の三国と隣接しており、どの国もこの地を狙っていることを知る。ある日、ジャミール王国の使者が来て、リアムへの王女スカーレットの輿入れを提案してくる。その真意をはかりかねたリアムは……。', '2025/02/07 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3685590b-f95a-44e7-91d1-fd3319fa8543.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc565509-bb1c-496f-81b0-ced018a598e8', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 6, '100216465', 'リアム、すごい鎧を作ってみた', '約束の地では、さらに住民が増えて本格的な国作りが始まった。国が大きくなるにつれて、攻め込んでくる脅威もまた大きくなる。住民たちが自衛するための力が必要だと考えるリアムは、これまでに習得した魔法を応用して、新たな魔導戦鎧 (まどうせんがい) 作りを始める……!', '2025/02/14 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b480a11-bccb-4e7b-8620-fbbad54a0bce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcc5fbd5-e304-40dc-a7a6-68f6b0d8593e', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 7, '100217567', 'リアム、ドラキュラと戦ってみた', '久しぶりにハミルトン家の領地に戻ったリアムは、アスナとジョディに、連絡を取らなかったことを問い詰められてしまう。そして二人はリアムの国作りを知り、約束の地に移り住むことに。新たな住人の歓迎。新たな魔法によってさらに発展するリアムの国。だがそんな中で、かつてない脅威が国に迫っていた……!', '2025/02/21 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4e823e2-1d4e-4dbf-b3a8-d03fb7f8b03d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21fc424a-67d9-4aa6-818d-a88340d627e5', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 8, '100218517', 'リアム、約束の地で王になってみた', '強敵ドラキュラをなんとか倒すリアム。ドラキュラの支配下にあった者たちも救われ、リアムの国の住民の数は一万を超える。建設ラッシュとなり、様々な種族が協力して住居を拡大していく。今やリアムは、住民たちも周囲の国も、ラードーンすらも認める国王となる……!', '2025/02/28 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/150f0e1a-6a13-42a9-b97c-16e651dfd29b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a517476-05e6-4a14-8c58-e4c011ce75b9', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 9, '100219315', 'リアム、少女と話してみた', 'パルタ公国からの使者が謁見を申し出る。だが、それはリアムを害するための罠だった。スカーレットの進言により、リアムは国力を隣国に見せつけることに。技術力アピールのため、国の貨幣の製造を始める。だが一方でリアムは、自分の戦闘スタイルの弱点に悩んでいた。そんなリアムを指導するため、謎の少女が現れた!', '2025/03/07 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/449f38cb-6d45-4517-9947-d1006d7063e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63947715-3edf-40ea-9a65-bbf2bdf69a39', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 10, '100220320', 'リアム、海を作って遊んでみた', '国の規模が拡大したことにより、水と塩の不足が問題となる。随時リアムが魔法で用意するという現状を改善するため、国内に海を作ることに。だがリアムの魔法を駆使しても、大規模に地形を変えることは難しく、できあがったのはプール程度のものだった。……そして、みんなで海水浴が始まった!', '2025/03/14 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/92edff3e-788d-4d11-976f-6c6e73899a2b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fea32e24-ce1f-48f4-8a87-dd83c19e1028', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 11, '100221352', 'リアム、魔法都市を作ってみた', 'ジャミール王国の一地方に、災害救助のため密かに幻影を送ったリアム。王国にリアムの干渉を悟らせないため、リアム本体は国内で目立つ必要があった。そんな中、リアムは街の舗装工事を思いつき、さっそく取り掛かる。やがて改善点を見つけ、どんどんのめり込んでいき、ついには……!', '2025/03/21 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f745c70e-6cda-405e-a3d7-5bf1480c1a7a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7be0680c-1270-4147-92c0-4d0bec469f38', 'f7e0a8b9-392c-4cea-a2e9-41daa7e68943', 12, '100221969', 'リアム･ラードーン王国', '【シーズン1 最終話】キスタドール王国の竜騎兵部隊がやって来た。隊長のシーラ王女の決闘を受け、実力を見せるリアム。国の名前を問われ、ラードーンが答える。国の名は――。その国では、住民の誰もが魔法を使い、魔法が生活の一部となっている。リアムの作り上げた国に、圧倒されるシーラ。そして……リアムは今日も新たな魔法の練習を続ける!', '2025/03/28 12:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e3e93538-45ce-4d8a-8587-44405854b953.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8ba831b4-eb08-437a-beaf-2d234a8b4eed', '本好きの下剋上 司書になるためには手段を選んでいられません', '', 'hulu', 'booklove', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1d63c8d-339c-42b1-9504-eda802c37ae9.jpg?w=331&h=447&p=t', 'hulu', 2019, 3, 1, 'FINISHED', NULL, 108268, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2cdb440c-587a-4541-bc1c-46f80174ab5e', '8ba831b4-eb08-437a-beaf-2d234a8b4eed', 'hulu-booklove-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e36ce058-cbeb-4521-b8a0-8739518d1aa9.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69de2af4-b872-4482-9433-9db1850c909c', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 1, '100043161', '本のない世界', '本が大好きな女子大生･本須麗乃は本に埋もれて亡くなり、気がつくと別の世界で、病弱な少女･マインとして転生していた。本があれば、どんな環境でも耐えられると思ったマイン。さっそく本がないか家中を探し回るが、どこにも本が見つからない。さらに母親のエーファと一緒に街へ出ても、文字すらなかなか見かけることができない。そこは識字率が低く、本がとても高価な世界だったのだ―。', '2019/10/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e36ce058-cbeb-4521-b8a0-8739518d1aa9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca68ed02-24ea-4893-857c-f1792e9d9152', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 2, '100043646', '生活改善と石板', '本が貴重なこの世界で、マインは自ら本を作ろうと決意する。だが、体が弱いマイン。姉のトゥーリと一緒に、父親･ギュンターの忘れ物を届けるため門へ行こうとするが、少し歩いただけで息が上がってしまう。そんなマインの前に、ルッツが現れる。マインと同い年のご近所さんだ。転んだマインに手を差し伸べてくれるルッツにマインは感激する。そして、門へ着いたマインはそこで古い石板をもらい、字を書ける喜びをかみしめる。', '2019/10/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b01c4bb-a68c-40bc-afd6-21c1ba657b94.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73421bf0-9624-4c29-8c94-a8e2ea306749', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 3, '100043942', '冬のできごと', '冬。雪に閉ざされる中、マインは本作りの第一歩としてパピルスもどきを作ることに。一方、姉のトゥーリは夏に洗礼式を控え、母･エーファから様々な仕事を教わっていた。マインも見習い仕事について考えるよう言われるが、相変わらず本のことしか頭にない。そんなマインと家族との距離は冬を過ごす間に徐々に縮まっていき、マインはトゥーリの洗礼式のためにある物をプレゼントしたいと思いつく。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4198eb6f-2f4e-4825-b222-3f40c322503f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09592f29-ffb6-4a87-9d15-177ee7e8e77f', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 4, '100044051', '初めての森と粘土板', '春になり、家族に森へ行きたいと言うマイン。だが、体力がないからと反対されてしまう。しばらく門へ通い、皆に遅れずに歩けるようになれば、森へ行っても良いと言うのだ。オットーの書類仕事を手伝うことになったマインは、門へ通いながら体力をつけることに。そして、次第に歩けるようになり、ついに森へ行くことを許されたマイン。さっそく森で、粘土板を作ろうとするのだが…。', '2019/10/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c85788a-7bcb-456c-a899-9008b36d342d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('deed16a9-5bb7-4076-a203-1f503aa3ac50', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 5, '100044314', '洗礼式と不思議な熱', '季節は夏に移り、トゥーリの洗礼式の日がやって来た。マインが作った髪飾りをつけ、注目を集めるトゥーリ。そして森へ行く機会が増えたマインは、ルッツに手伝ってもらいながら木簡作りを始める。そんな中、マインはルッツに、オットーに会わせてほしいと頼まれた。ルッツには、旅商人になりたいという夢があったのだ。だが、度重なる紙作りの失敗にショックを受けたマインは、オットーとの会合を前に高熱で倒れてしまうのだった。', '2019/11/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/901cf49d-dbaf-4aed-8573-91417c55e745.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b02db86-ecac-4b0f-bf8f-ae6870ea16d4', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 6, '100044748', '会合', 'ルッツをオットーに紹介することになったマイン。だが、それはただの会合ではなく、見習い先を紹介してもらうという意味を持っていた。身なりを整え、緊張しつつ会合に臨むマインとルッツ。そんな二人の前に、オットーとベンノが現れる。オットーの旅商人時代の知り合いだというベンノは、値踏みするように二人を見、ルッツに商人になって何を売りたいかを聞く。果たして二人の答えは…。', '2019/11/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a6ee4ca3-78bc-4a96-92f6-4fb586133794.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('913a65f0-865c-496c-9264-f0074953ea3c', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 7, '100045352', '不信感の芽生え', 'いよいよ紙作りをすることになり、わくわくするマイン。そんなマインとルッツに、ベンノから呼び出しがかかる。紙作りに必要な材料を、ベンノが調達してくれると言うのだ。マインは、材料の担保や今後の援助についてベンノと交渉。そして不思議なインクを使い、契約魔術を結ぶ。だがその帰り道、いつもは快活なルッツの態度がよそよそしいことが気になるマイン。ルッツは、ベンノと平気で難しい話をするマインに違和感を覚えていた。', '2019/11/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/834cd03d-9777-4982-82c3-b99ccf5fe6a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5a53432-1ee0-4b53-97eb-d85c789ea2f0', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 8, '100045827', 'ルッツのマイン', '本格的に紙作りの作業が始まった。マインとルッツは作業用の倉庫を借り、必要な道具を揃えていく。さらに二人は森へ行き、木の枝を蒸して紙を作ることに。だが、慣れた様子で紙作りを進めていくマインに、ルッツはさらに違和感を募らせる。紙ができたら話をしたいと言うルッツ。そして最初の紙が完成した時、ルッツはマインに、これまでの疑念をぶつけるのだった。', '2019/11/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3210059-559a-42d7-88ac-8513547b7e9e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79f782fe-f6e0-4e1a-a83a-10393dea5c37', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 9, '100046318', 'ギルド長の孫娘', 'ベンノに連れられて商業ギルドへ行ったマインたちは、そこでギルド長に会うことになった。マインが作っているという髪飾りを見て、驚くギルド長。それは、ギルド長の孫娘･フリーダが欲しがり、ずっと探していた髪飾りだったのだ。ギルド長から、フリーダの髪飾りを作るよう依頼されたマインは、フリーダに会いに行くことに。フリーダは、可憐で可愛らしい少女だったのだが…。', '2019/12/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d6de1519-2dab-4f61-9a5a-900dae57bf73.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7ec9fa6-ddbb-4fd1-a422-37ed4ab91ad8', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 10, '100046965', '二度目の冬に向けて', 'すっかりフリーダに気に入られたマイン。フリーダの話から、マインは身食いという病気だったことが分かる。治すためには、多額のお金がかかるらしい。そのことに気づいていたベンノは、商品についてのマインの情報を買ってくれる。さらに髪飾りの注文を受け、新しい商品のアイデアも次々と考えていくマイン。だが、そんな最中にも身食いの熱はマインを蝕んでいき…。', '2019/12/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d1b8c15-7222-4a8b-ac94-46c1d166035d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9efd6cb6-71a1-49f4-91de-a9c8e76c7be9', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 11, '100047339', '究極の選択と家族会議', '気がつくと、マインはフリーダの家にいた。フリーダの持っていた壊れかけの魔術具のおかげで、マインは命を取りとめたのだ。だがフリーダは、これで身食いを治せたわけではないと言う。この先、魔術具を持つ貴族と契約して貴族に飼い殺されて生きるか、このまま家族の元で朽ち果てるか、二つに一つを選ばなければならない。マインに残された時間は、あと一年。しかし、マインは家族に本当のことをなかなか話せずにいた。', '2019/12/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a2d7b95-cfb2-4b01-9dcd-c99306dec70f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9664f7af-6c7e-4b8b-be55-46966bf1c101', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 12, '100047636', '洗礼式と神の楽園', 'それぞれの進む道が決まったマインとルッツ。そして、二人の洗礼式の日がやってきた。初めて神殿に入ったマインは、神殿長が読む聖典に目を奪われる。その洗礼式の最中、ひょんなことからマインは神殿の中で迷子になり、偶然、図書室を見つける。転生してからはじめて目にする図書室に感激するマイン。しかし、中に入ろうとしても入れない。図書室には神殿関係者しか入れないのだ。その話を聞いたマインは…。', '2019/12/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/114785a4-37c4-40d7-b52e-db137db9ee4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e140641-dbdb-49e1-b770-5d33379cc330', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 13, '100047944', '巫女見習いという選択肢', '神殿の巫女見習いになりたいと言うマインに、激怒するギュンター。神官や巫女見習いは孤児がなるもの。しかも神殿に住み込みで、きつい仕事をしなければならないらしい。マインは、巫女見習いになるのを諦めることにする。そして再び神殿へやって来たマインは、神殿長と神官長のフェルディナンドに、巫女見習いの話を断ろうとするが…。そこで思わぬことが起こってしまう。', '2020/01/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c46f35a4-e2c4-4ce8-a0a8-c09239e5b70b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a9a62742-9bdd-45db-bfdf-3e395cb8d034', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 14, '100047945', '決着', '神殿に呼び出されるマインと両親。交渉次第では、貴族に近い扱いの青色巫女見習いになれるかもしれないと聞き、ギュンターはマインを守る覚悟を決める。そして、交渉の日。神殿長は、マインの両親の貧しい身なりを見たとたん、これまでの温和な態度を一変。両親の言葉には聞く耳をもたず、マインを差し出すよう命じる。断固として断るギュンター。そんなギュンターに神殿長が牙を剥く!', '2020/01/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b694b3a-1551-4ca9-b7cb-47ffa781a7f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a642ff99-8ca9-4508-828a-66d5f4f0cc00', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 15, '100054037', '神殿の巫女見習い', 'いよいよ神殿の巫女見習いになることになったマイン。神殿に入るまでの間、これまでのことをベンノに報告したり、カトルカールの試食会をしたりと、慌ただしく過ごす。そして、マインが神殿へ行く日がやって来た。フェルディナンドによって誓いの儀式が行われ、青色巫女見習いとして認められるマイン。そして、これからマインの身辺の世話をするという側仕えたちを紹介されるのだが…。', '2020/04/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c404ffc-2974-42ed-a856-dc4913acaf8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1a96a33-d0c1-4aed-8f30-df1e7500faf1', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 16, '100054531', '青い衣と異なる常識', '神殿での生活が始まった。新しい仕事を覚えていくマインだが、側仕えたちはマインに反抗的な態度を取る。中でもフェルディナンドの側仕えだったフランは、貴族らしさの欠片もないマインに仕えることに不満を持っていた。一方、マインも側仕えが信用できず、ちっとも神殿に馴染もうとしない。そんな中、寄付金を納めることになったマインはベンノを伴い神官長の元へと赴くことになった。', '2020/04/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a5b5b8cf-a706-43ab-9b63-a2949a98d09f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('615a762b-fe60-4d70-8425-dd8b39d692a5', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 17, '100054887', '与えるべきもの', 'フランの信頼を勝ち取ったマイン。しかし、ギルとデリアはまだマインを主と認めない。「与えるべきもの」を与えていないからだ。神殿では主が側仕えの衣食住を保証するのだ。マインは、麗乃時代とも下町とも異なる神殿での常識に戸惑いながらもギルに食事を与えるためにはどうすれば良いかを考える。一方、自分たちに歩み寄ろうとするマインの姿に、ギルとデリアの心も揺れて…。', '2020/04/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5494ad0a-a1b7-4112-8ea1-b3b3303a2fae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a666966c-9770-41f1-a33d-59400f6e94d7', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 18, '100055127', '孤児院の大改革', '孤児院に案内してもらったマインは、飢えた幼い子供たちを見てショックで倒れてしまう。なんとか子供たちを救えないかとフェルディナンドに相談するが、孤児たちに対して責任を負えるのかと問われ、答えることが出来ない。しかし、飢えた子供たちの姿が頭から離れないマイン。大好きな読書も手につかなくなってしまう。そんな中、ルッツの一言からマインは孤児を救う方法があるかもしれない、と希望を見出す。', '2020/05/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ae3a213d-cb95-44a8-b2d9-9a06fe611052.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6b99dee4-aa6c-4dd4-92f1-52ca2ebc9c57', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 19, '100055471', '大掃除と星祭り', '孤児院長に就任したマインは、手始めに孤児院の大掃除をすることに。さらに採集の仕方やスープ作りを教え、孤児院の環境を改善する。働けば報われることを知った子供たちは、率先してマインのために動くようになり、マインは子供たちから慕われる。そして季節は夏になり、子供たちにも星祭りを体験させたいと思うマイン。フェルディナンドの許可を得て、孤児院の庭でタウの実をぶつけ合うが、そこで不思議なことが起きる。', '2020/05/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cc71d194-fa1e-4a33-a7d4-0e7298bd8082.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d104b75d-6cb9-42f5-82f7-505df2e6b333', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 20, '100055663', 'ルッツの行く道', 'ルッツが家出してしまった。ルッツが商人になることに反対していた父のディードと言い争いになり、飛び出してしまったらしい。一方、ベンノはルッツを養子にすると言い出し、ルッツの家族と険悪になる。どうすればいいのかと悩むマイン。フェルディナンドは双方の話を聞くようにと助言する。親身になってくれるフェルディナンドが意外なマイン。こうして、神殿でルッツの家族会議が行われることになる。', '2020/05/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39877752-2d2a-44a1-bc70-0b4ac363cab5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39a1fbe8-ebd2-420a-b395-aca4bf10cfdd', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 21, '100055909', '新しい側仕え', 'エーファに赤ちゃんが生まれることを知ったマインは、子供用の絵本を作ろうと決意する。絵本作りのため、絵が上手いヴィルマを側仕えにしてほしいと懇願するマイン。さらに、音楽の得意なロジーナも側仕えに加わり、マインは新たに二人の側仕えを迎えることになった。だが、ヴィルマは何か事情がある様子で、孤児院から出たがらない。一方ロジーナは、マインにフェシュピールという楽器を教えてくれることになったのだが…。', '2020/05/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/311b1751-b07a-41d6-87ba-0e04a476a733.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('87f96d75-5e81-4597-95d7-41e0772fea30', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 22, '100056340', 'ヴィルマと子供用聖典', '本格的な絵本作りが始まった。マインはルッツやトゥーリ、孤児院の子供たちに協力して貰いながらインクを手作りし、試行錯誤をくり返して作業を進めていく。これまでの道のりを振り返り、ここまで来られたのはみんなのおかげだと胸がいっぱいになるマイン。一方、みんなが本作りを頑張っている姿を見て、頑なに孤児院の外に出たがらなかったヴィルマの心にある変化が起きていた…。', '2020/05/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50bc47b1-3a33-4ebd-b65b-2adf46ca01fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1901272-7611-4f08-8353-c883b1ba2497', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 23, '100057125', '収穫祭のお留守番', '秋になり、青色神官たちが収穫祭へと出発する中、マインは図書室へ行くことにする。久しぶりに本が読めると、うきうきするマイン。だが図書室の扉を開けたとたん、マインは茫然とする。図書室の中が荒らされ、本や資料が撒き散らされていたのだ。こうなったら十進分類法を使い、好きなように片づけようと奮起するマイン。一方、フェルディナンドはこの世界にはない不思議な知識を持つマインに疑念を抱くのだった。', '2020/06/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9069bb32-2955-4708-93b9-96ac3b3f6840.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('253f807d-3114-4dad-9797-da1a186ae798', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 24, '100057405', '騎士団からの要請', 'フェルディナンドから、冬の間、神殿に籠るようにと言われたマイン。家族に反対されるものの、神殿に残ることを決意する。マインには孤児院長としての、そして青色巫女見習いとしての責任感が芽生えていたのだ。そして、冬が近づいてきたある日のこと。騎士団から要請がきて、マインは儀式を行なうことになる。衣裳を着替え、貴族街へと連れて来られたマイン。そこには、鎧に身を固めた騎士たちが整列していた。', '2020/06/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1506dccc-eec7-4b1b-9777-0895b092a9b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('467de73f-1988-4cb0-a171-d4941b61695f', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 25, '100057741', 'トロンベ討伐', '騎士団からの要請で、出動することになったマイン。フェルディナンドの騎獣に同乗し、空を駆ける。行き先は、森の奥。そこで、巨大化したトロンベが暴れているのだ。枝を振り回すトロンベを見て、驚くマイン。騎士たちは黒く変化させた武器で戦い、トロンベは弱っていく。だがその時、マインの護衛を任されていたシキコーザが、マインを平民だと見下し、威嚇したことで、とんでもない事件が起こってしまう。', '2020/06/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71037a16-bbfb-4fc7-84a4-c09fc8ff2b7f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0c1124b-8815-4a8b-a5fb-23e895054209', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 26, '100058048', '夢の世界', 'トロンベの討伐が終わると、マインは熱を出して寝込んでしまう。そして、ようやく回復したマインが久しぶりに神殿へ行くと、フェルディナンドの部屋に呼ばれた。フェルディナンドは、魔力がけた違いに多く、不思議な知識を持つマインの正体を見極めようとしていたのだ。フェルディナンドの薬を飲み、魔術具をつけたマインは眠くなり、気を失う。そこでマインが見たものとは―。', '2020/06/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/651fb589-a83d-42e5-a5d3-84ed021a2f03.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4eaca973-a668-4101-98b7-300a68a4be0e', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 27, '100109814', '冬の始まり', '秋の終わり。マインは聖典絵本を量産して売り出したり、鍛冶職人見習いのヨハンにパトロンになって欲しいと頼まれたり、次の目標へ向けて精力的に本作りに取り組んでいた。だがそんな中、インク協会会長のヴォルフが、マインのことをかぎ回っていることがわかる。マインはベンノからある事を提案されるのだが……。', '2022/04/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6009a5d0-2e82-4184-862d-2cb5f63ac104.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('635ccba9-87de-48ce-99e6-0c399fc9be94', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 28, '100110329', '冬籠もりと今後の話', '神殿で、冬籠もりをすることになったマイン。だが、早々にホームシックになってしまう。さらに、ベンノとフェルディナンド、カルステッドとの会談では、ヴォルフが危険な人物で貴族とも繋がりがあることが判明。不思議な知識と強大な魔力を持つマインは、貴族たちからも狙われる存在だったのだ。危険を回避するためにフェルディナンドが下した決断とは!?', '2022/04/25 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/563da8a4-922c-43b7-900d-a85a048516cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('816991d3-3251-4194-970a-b9ed0d3bc574', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 29, '100110801', '奉納式と春の訪れ', 'マインの護衛として騎士のダームエルがつくことになった。おかげで出歩くことができるようになったマインは、図書室に行けると大喜び。奉納式を行ない、小聖杯に魔力を満たす職務を果たしながらも、下町へヨハンに注文していた品を受けとりに行く等、本作りへの情熱は失わない。そして春が近づき、家に帰れる日を心待ちにするマイン。だが、そんなマインに残酷な事実が告げられる。', '2022/05/02 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/deea7515-3dd7-4a44-a947-9961d455faa0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cd561104-5a19-437d-acd3-fb83e7b48e58', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 30, '100110802', '祈念式', '祈念式へ向かうことになったマインたち。そこへ、ジルヴェスターという青色神官が現れる。自由奔放なジルヴェスターにからかわれ、戸惑うマイン。ジルヴェスターを牽制しながら各地の農村を回り、祈念式を立派に務める。そしてマインたち一行は、以前からマインに興味を持っていたというゲルラッハ子爵のもとを訪れることに。だが、その日の夜――。大変な事件が起こってしまう!', '2022/05/09 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3002d895-9b8b-477d-be2c-05c334c98e32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a794ec70-9645-41e2-bce8-eca3552d3782', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 31, '100111566', '青色神官の贈り物と帰宅', '祈念式を終え、マインたちが神殿に帰って来た。ジルヴェスターは、孤児院や工房を見てみたいと、マインを案内係に任命。聖典絵本を作る様子等を見て回る。そして去り際、ジルヴェスターはマインに、「いざという時のお守りだ」と、黒い石のついたネックレスを渡す。一方、ジルヴェスターと共に本作りの様子を見たフェルディナンドは、マインの技術は歴史を変えてしまうと、危機感を募らせるのだった。', '2022/05/16 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e62a7e08-19b7-4548-a971-dd61bdb8c465.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('235be791-36eb-4cdb-a016-f97275a5bf62', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 33, '100113044', 'デリアとディルク', '赤ん坊のディルクが、高熱を出してしまった。ディルクを可愛がり、親身に面倒を見ていたデリアは、心配でたまらない。症状を見て、ディルクが身食いではないかと気づいたマイン。フェルディナンドと相談の末、ディルクを守るために、身食いであることを隠して育てることにする。マインは、ハイディと共に色インクの実験を進めつつ、神殿でディルクの世話をしていたのだが……。', '2022/05/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fec63a63-6c24-414c-a833-0a2cb1d5d14d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f69dea53-e645-4993-8204-182a7adbc600', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 34, '100113622', '不穏な動き', 'ハイディの工房からの帰り道。非常事態を知らせる鐘が鳴り、救援信号の赤い光が上がる。何があったのかと、不安になるマイン。状況がはっきりするまで、マインは安全のため、家に引きこもることになった。束の間の家族との時間を過ごすマイン。そして、ようやく外出を許されたマインが神殿へ行くと……。そこに、ディルクの姿はなかった。そしてマインに、さらなる危機が襲いかかる!', '2022/06/06 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/022a8a90-02cf-4ba7-b3b3-6dae3fe80e5b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('41653ac3-6737-4c36-a91a-e1cae639a25d', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 35, '100114334', '黒いお守り', '門番のミスで、他領の貴族の馬車が町に入りこんでしまった。マインが狙われていることを知っているギュンターは、マインを守るために奮闘する。だが、謎の男たちに襲われてしまうマイン。ジルヴェスターの言葉を思い出し、黒いお守りに血判を押す。しかし、状況は何も変わらない。そんな中、マインを狙う者たちが、ついに牙を剥く! そして、ディルクも巻き込んだ神殿長たちの陰謀が明らかになる。', '2022/06/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/36bb9189-3b8c-411a-8756-78ba8fd6fa68.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('81c1c69c-be77-4af3-833b-5c7df176a5a8', '2cdb440c-587a-4541-bc1c-46f80174ab5e', 36, '100114902', '祝福', '【最終話】不当な契約を迫る神殿長とビンデバルトに、魔力を暴走させたマイン。そこへ現れたフェルディナンドは、ビンデバルトと対戦する。さらに一同のもとへ、ジルヴェスターとカルステッドもやって来た。神殿長とビンデバルトは、自分たちに刃向かったマインに、罰を与えてほしいと要求。一同の裁定が行なわれる。そして、マインは大切な家族に、一つの決断をしたことを告げることになる――。', '2022/06/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb8384bf-8e78-4b36-92cb-8cba5f9a9dc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dc18090f-ddee-4e79-a5a9-5e31c2f8f4fd', '魔王2099', '', 'hulu', 'demon-lord-2099', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e00d568b-1f03-4206-a376-051d3e025e8a.jpg?w=331&h=447&p=t', 'hulu', 2024, 3, 1, 'FINISHED', NULL, 163135, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('13a093a6-a840-4954-a483-68af6ef8b16a', 'dc18090f-ddee-4e79-a5a9-5e31c2f8f4fd', 'hulu-demon-lord-2099-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c7b8b64-a56d-46b4-b139-3254659ac7d9.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99786143-190c-4e3a-a19a-6c7cb406315a', '13a093a6-a840-4954-a483-68af6ef8b16a', 1, '100202797', '電子荒廃都市･新宿', 'かつて勇者との戦いに敗れた魔王･ベルトールは、転生の魔法により500年ぶりに復活を遂げた。再び世を支配しようと意気込むベルトールだったが、臣下である六魔侯の一人、マキナから、思いもよらぬ事実を告げられる。', '2024/10/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c7b8b64-a56d-46b4-b139-3254659ac7d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4583fff-6902-4a44-92df-8e30fc6f3eea', '13a093a6-a840-4954-a483-68af6ef8b16a', 2, '100203244', '魔王と臣下', 'かつての臣下･マルキュスの裏切りを、その身をもって知ることとなったベルトール。他方、マキナはベルトールを街に連れ出す。変わり果てた未来の世界で生きていくため奮闘するベルトールに、マキナはある人物を紹介する。', '2024/10/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/afd2e626-7d4d-4908-84e0-300a8a83fb51.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76f72889-c3f6-42ac-a903-bbcec958f90e', '13a093a6-a840-4954-a483-68af6ef8b16a', 3, '100204340', '【初配信】魔王ベルトール復活の時である!', 'マキナの友人･高橋の勧めにより、顔出しでゲーム配信をはじめるベルトール。高橋の戦略と勢いのもと、配信者像を確立させていく日々。そんな中、新宿外縁の裏路地を歩いていたベルトールは、とある浮浪者の姿に息を呑む。', '2024/11/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/129e2e54-d70c-49d1-ace9-b049b6251991.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cdd3951c-ce89-49ac-900a-0666e1f53fa8', '13a093a6-a840-4954-a483-68af6ef8b16a', 4, '100204982', '新宿市の影', '高橋に仕事のボディーガードを頼まれたベルトール。回復してきた信仰力の力試しも兼ね、ヤクザに急襲をしかけるベルトールだったが、ありふれた盗み仕事は思わぬ展開へと進み、二人はこの都市の闇へと入り込んでいく。', '2024/11/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c1b12dd-157b-4f54-916d-eb3fc3b11485.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fb31ef08-b6e3-40c7-ab65-9a4273aeab16', '13a093a6-a840-4954-a483-68af6ef8b16a', 5, '100205261', '坩堝の底', 'マキナは夕食の支度をしながら、ベルトールに対し思いを巡らせていた。一方、“不死炉”についての新事実を知ったベルトールは、マキナにこの事を伝えようと念話を行うが、応答がない。同刻、マキナのもとに来客が――。', '2024/11/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13807180-6460-40bc-a254-8abb7baff672.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c5daa148-eccf-4086-8c8d-1dd7d65ed0fb', '13a093a6-a840-4954-a483-68af6ef8b16a', 6, '100206769', '勇者の戦い', '新宿市･エーテルリアクターの直下、“不死炉”にて。不死についての凄惨な事実を告げるマルキュスに、マキナは激昂する。一方、ベルトールたちの行く手を阻む木ノ原。その斬撃を受け止めるグラムに、ベルトールは命ずる。', '2024/11/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0a45039-ec22-4a0e-b9c3-885020f4c636.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7373817c-89e3-45cf-b39c-a8f537536400', '13a093a6-a840-4954-a483-68af6ef8b16a', 7, '100207468', '魔王再誕', '木ノ原の相手をグラムに託し、不死炉へとたどり着いたベルトール。マキナを攫ったことや、不死達への裏切りについて、マルキュスを問いただす。伝説の魔王と新宿市の支配者。かつての王と臣下は、新たなる世界で剣を交える。', '2024/11/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3a567f5-1e96-4db7-ae5e-96031587fdae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19612159-7a3b-4a76-8f9f-00a30c1558e6', '13a093a6-a840-4954-a483-68af6ef8b16a', 8, '100208585', '電脳魔導都市･秋葉原', '秋葉原魔法学園《ル･クセル》に通う山田･レイナード=緋月は、今日も教室の片隅で深いため息をついていた。一方、マルキュスを倒し無事にマキナを救出したベルトール。彼が次に求めるものは、どうやら秋葉原市にあるようで――。', '2024/12/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/18e3b7f5-def5-4cb0-ab3c-c8fea22aa80f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57c3ed96-bfdd-4fe1-ab9b-02d734a8a4a5', '13a093a6-a840-4954-a483-68af6ef8b16a', 9, '100209764', '劣等生と留学生', 'レガリアを求め、短期留学と称して秋葉原魔法学園に潜入したベルトール、マキナ、高橋。三人が学食でテーブルを囲んでいると、近くに座っていた山田･レイナード=緋月に、学園一の優等生･アルバートが因縁をつけ始め…。', '2024/12/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14a9f27f-5664-4a05-b772-14842e7420fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96a44390-e5d1-4510-b7c9-38703cdf629b', '13a093a6-a840-4954-a483-68af6ef8b16a', 10, '100210358', '秋葉原御三家', '緋月が働く電気街のメイド喫茶･へるへいむへ来店したベルトールたち。メイド喫茶ならではのおもてなしを受けつつ、ベルトールはレガリアについて緋月に尋ねる。その後、電気街に繰り出した4人は、ある人物と出くわす。', '2024/12/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad1eb6e0-97b0-4a11-9d4c-4af0abe07aaf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('525f97cc-ccc7-4354-9d6c-04ebe4d4785c', '13a093a6-a840-4954-a483-68af6ef8b16a', 11, '100211393', '女神降ろし', '電気街に出かけた後、レイナード家の屋敷に訪れたベルトールたち。余興も終わったところで、浴室へと向かった緋月だったが、そこにはベルトールの姿が…! ――次の日の事。緋月は教室で、電気街で起きた爆発事故の噂を聞く。', '2024/12/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6ab84da6-d3e5-45f4-83f2-e3e8c3f2bfc7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('acc126d0-d258-4894-a067-fda799cf233b', '13a093a6-a840-4954-a483-68af6ef8b16a', 12, '100212118', '還帰の王', '【最終話】マグ=ロサンタの企てにより、緋月を依代に顕現した女神･メルディア。ベルトールは緋月を救うべく、メルディアと戦うが…。他方、マキナはバイザーを着けた少女と対峙する。対立する電気街と魔法街、秋葉原市の行方とは――。', '2025/01/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/253986db-06df-4eda-bd5c-87d8ad8189b4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ea7a7019-c1d3-4466-8f4b-74e9f5dff212', '魔王の俺が奴隷エルフを嫁にしたんだが、どう愛でればいい？', '', 'hulu', 'an-archdemons-dilemma-how-to-love-your-elf-bride', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/955d4130-905f-4a91-8c52-c81be24600b6.jpg?w=331&h=447&p=t', 'hulu', 2024, 1, 1, 'FINISHED', NULL, 156023, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('afff938b-c338-47e3-ab18-6da6187b23f7', 'ea7a7019-c1d3-4466-8f4b-74e9f5dff212', 'hulu-an-archdemons-dilemma-how-to-love-your-elf-bride-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/910f1646-f38e-4ef5-bee2-cba8b4876747.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22b2bb3d-2872-42a2-ae1b-a94b4eb5bfff', 'afff938b-c338-47e3-ab18-6da6187b23f7', 1, '100180727', '初恋とは誰もが一度はかかる質の悪い病である', '悪の魔術師として人々に恐れられているザガン。悪友のバルバロスに誘われて参加した闇のオークション会場で、魔王の遺品として出品された白い髪のエルフの少女ネフィと運命的な出会いを果たす。全財産をはたいて、ネフィを自身の城へ連れ帰ったが、これまで人付き合いをすることのなかった口下手なザガンは、ネフィにどう接していいかわからないまま、まともな会話も出来ず狼狽えるばかり。これからはじまる二人の共同生活の行方は如何に――。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/910f1646-f38e-4ef5-bee2-cba8b4876747.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f66873d1-ff9f-4f1f-85d6-d2fed1b8b748', 'afff938b-c338-47e3-ab18-6da6187b23f7', 2, '100181742', 'コミュ障の初恋はカビたパンの味に似ている', 'エルフの少女ネフィを自身の城に連れ帰り一夜が明けた。朝食としてザガンから手渡された干し肉を見て、ネフィは料理を作ることを申し出る。一目ぼれした少女の手料理が食べれることを喜んだザガンは、早速街へ買い物に出かけようとするが、全財産をはたいてネフィを落札したため街へ向かう馬車に乗る金もない。仕方なく歩いて街へ向かっている最中、野盗に襲われている馬車を見つける――。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38d3e130-93bb-4a8a-b889-d64b2a4e7483.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b27b6838-39d1-4cc8-8564-e7a07276cc02', 'afff938b-c338-47e3-ab18-6da6187b23f7', 3, '100182363', '普段おとなしい子ほど怒ると破壊的に恐ろしい', '一目ぼれしたエルフの少女･ネフィとの共同生活を送りながらも、魔術の研鑽を忘れないザガン。書庫で魔術の仕組みについてネフィに説明していると、城を覆っていたザガンの結界が領地への侵入者を感知する。様子を見に行ったザガンの前に現われたのはザガン討伐の命を受けた、教会の聖騎士と「聖剣の乙女」シャスティルであった。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f0770bb-9e86-45dc-8862-ddd4d1f592cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cdca7e23-95b6-4d79-bd9a-be9aae41b2ad', 'afff938b-c338-47e3-ab18-6da6187b23f7', 4, '100183232', '魔王からの勧誘とかロクなことにならないから、断った方がいい', '聖騎士の攻撃から自身を庇って負傷したザガンを見たネフィは、我を忘れエルフの強力な魔法を使い聖騎士たちを退けた。その夜、ネフィは「呪い子」と呼ばれていた自身の過去をザガンに打ち明ける。ザガンはネフィのすべてを受け入れ弟子として魔術を教えることにする。ネフィを城に連れ帰ってから半年ほどたったある日、ザガンのもとに魔術師の極致〈魔王〉からの召喚状が届く。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5ac9a79-91fc-42c6-8612-acb16eaa07f9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ffd8243f-9e3e-4b67-bbff-ea4df2d62844', 'afff938b-c338-47e3-ab18-6da6187b23f7', 5, '100183744', '失恋というのは物理的にもけっこう痛いもので', '〈魔王〉を襲名したザガン。ネフィの未来を案じたザガンは、ネフィの首輪を外し「出て行ってくれ」と冷たく告げた。街の路地裏でうずくまっていたネフィに声をかけたのは、シャスティルであった。マニュエラに連れられ街の食堂で教会と魔王の関係を聞かされたネフィ。突如として、食堂に黒い影が現われ、ネフィ達を連れ去ってしまう。影の主は自らを“ザガン”と名乗るのであった。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fbb3e303-6c8a-41ed-9d1c-2b61be66e250.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72c1d269-fc96-466f-b154-ae23be07bdee', 'afff938b-c338-47e3-ab18-6da6187b23f7', 6, '100184447', '魔王になったからには傍若無人に振る舞う義務みたいなものがある', '影から逃れたマニュエラからネフィたちが攫われたことを聞いたザガンは、魔王を継承した身でネフィを助けに行くことに葛藤する。ネフィとシャスティルを連れ去った影の主はバルバロスであった。ネフィから、ザガンが魔王となったこと知らされたバルバロスは激昂し、ネフィに手を上げようとした。その時、魔術による爆発で岩壁が崩れ落ち、土煙がたつ。その中から現れたのはザガンであった。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6874603a-06f2-4895-b886-f19c111af86c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cae7484f-c049-4d3d-a31c-0d9da6e03fa4', 'afff938b-c338-47e3-ab18-6da6187b23f7', 7, '100184917', '魔王だって小さい子に手をあげるのは良くない', 'バルバロスを倒し、囚われていたネフィを助け出したザガン。互いの想いを知った二人の心の距離はさらに縮まってゆく。バルバロスの魔法陣から召喚された魔族の存在について調べていたザガンのもとに、全身甲冑に身を包んだ魔術師〈亡霊〉ウォルフォレが現れる。一方、魔王となったザガンを庇い、討伐の命令に背いたシャスティルは、聖騎士長としての権限を無期限凍結されてしまう。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96221f05-deda-4276-866f-a4d25ac538ad.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e18a4b8d-f498-496a-9d95-6894123c5e66', 'afff938b-c338-47e3-ab18-6da6187b23f7', 8, '100186096', '竜を拾ったら懐かれたので娘にすることにした', 'ザガンの城を襲撃するもあっけなく返り討ちにあった竜の少女フォルは、ネフィの手伝いをしながらザガンの城で居候することになった。魔族の研究に行き詰まったザガンは魔術師であり竜でもあるフォルを連れ、先代魔王マルコシアスの城―魔王殿を、今一度、調べることにする。竜の術式によって隠されていた書庫で明らかになった魔王の刻印と十二本の聖剣に関する新たな事実とは――。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fb339db-c6a0-43cc-9fab-a0782b4accc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fb5073f-5960-41ba-8986-bb49fc2836bc', 'afff938b-c338-47e3-ab18-6da6187b23f7', 9, '100186525', '聖騎士の事情はドロドロしているので関わりたくないのだが', '酒場にいたザガンとバルバロスの前に、最恐の聖剣所持者ラーファエルが現れる。ラーファエルは、魔王ザガン討伐に異を唱えたシャスティルが教会から処分の対象になっていることを告げ、酒場を後にするのであった。城に戻ったザガンのもとに、何者かに毒を盛られたシャスティルがバルバロスに連れられて転移魔術で現れる。シャスティルは倒れる前に謎の人物に呼び出されていたことを思い出す。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9694c396-a04c-4394-95aa-521bace44292.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5479e0d-ba6e-470d-bc95-034396e33a3c', 'afff938b-c338-47e3-ab18-6da6187b23f7', 10, '100187230', '娘に家出されたら親としては必死になるもので', '玉座で眠っていたザガンは、城からフォルがいなくなったというネフィからの知らせに目を覚ます。ザガンとネフィ、二人の娘としての生活を気に入りながらも、聖騎士への復讐を忘れることができないフォルは、新たな力を求め魔王殿を訪れていた。後をつけていた最恐の聖剣所持者ラーファエルと対峙したフォルはあることに気づく。殺されたフォルの父と聖騎士ラーファエルの関係とは――。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/137797df-3d99-4a47-946e-b19a604fde1a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('616d9f3f-4636-4035-be78-de37e6002827', 'afff938b-c338-47e3-ab18-6da6187b23f7', 11, '100188089', 'それでも邪悪な魔物をやっつけるのが聖騎士らしい', '二本の聖剣が衝突した余波で封印が解かれたキメラの攻撃からフォルを庇い、重症を負ったラーファエルは、フォルの父である『賢竜オロバス』との関係とその最期、そして近いうちに世界に訪れる危機についてフォルに告げる。その後、ネフィの言葉で迷いが消えたシャスティルはザガンと共闘しキメラを破壊する。その姿を見たラーファエルはシャスティルにあることを依頼するのであった――。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d143358-78d0-4ab4-8cae-1dd382157fa5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06d6af6b-4747-47b2-b6fb-887f402f1cde', 'afff938b-c338-47e3-ab18-6da6187b23f7', 12, '100188489', '月夜の音楽会は美しいが、コミュ障にはまだ早い', '【最終話】魔王殿での一件の後、フォルは「魔王観察日記」を再び書き始める。ザガンとネフィのもだもだしている様子を観察をしていると、執事として雇われた新しい城の住人ラーファエルに「貴様にはまだ早い」といつも目隠しされてしまう。そんなある日、シャスティルを城に招いての食事会の買い出しに街へ出かけたザガンたちは、立ち寄ったマニュエラの店で、路地裏の子供たちが店に持ち込んできたという壊れた蓄音機を見つける。', '2024/10/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d694823b-54f2-4956-9b8b-9990ef3a9482.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e5f3c637-ef00-44a1-a82c-93e0f3c68565', '魔王の娘は優しすぎる!!', '', 'hulu', 'the-demon-kings-daughter-is-too-kind', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3e0b4c3-0087-40ec-926f-9934e6292e3f.jpg?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'FINISHED', NULL, 194742, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('13c9fcc5-0d71-4c68-9e46-eb9965527840', 'e5f3c637-ef00-44a1-a82c-93e0f3c68565', 'hulu-the-demon-kings-daughter-is-too-kind-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b56b62e-2d44-4c4a-afee-1fdb2e9b882e.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4eb44609-6236-424d-a337-1aac4f70de6b', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 1, '100247857', '「魔王の娘は優しすぎる!!」「魔王の娘はお手伝いがすぎる!!」', '魔王アーリマンの侵略を止めたのは、娘ドゥの優しさだった! 冷徹な側近ジャヒーは、そんなドゥに人間を使った試練を課すが、彼女はそれすらも優しさで乗り越えてしまう。', '2026/01/12 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b56b62e-2d44-4c4a-afee-1fdb2e9b882e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e776277-5f26-45a4-84f1-bf34b32d9e58', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 2, '100247858', '「魔王の娘は人間をしいたけすぎる!!」「魔王の側近は教育がすぎる!!」', '囚人を虐げる試練を与えられたドゥだが、むしろ人間たちを助け始めてしまう。続く試練では攻撃魔術を教わり、ついにドゥの中の魔族の力が目を覚ます――!?', '2026/01/19 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5beb601-d9fd-478e-81e2-4cc015b00fa1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b2c3b13-b50f-47de-89c2-35352c40630e', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 3, '100247859', '「使い魔探しは大変すぎる!!」「誘惑の魔女 (パリカー) がせくしーすぎる!!」', '動物に懐かれるドゥは、使い魔探しでも大苦戦。強力な魔獣を仲間にできるのか? 一方、ジャヒーの前に誘惑の魔女サティが現れ、ドゥを巻き込んで勝負を挑む!', '2026/01/26 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91b5d26e-7003-4c29-b6a8-597b46a56693.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('299ce474-8597-4fb5-97a4-0ecc2748bd3b', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 4, '100247860', '「サンタがプレゼントを配りすぎる!!」「魔王の使い魔は人間が好きすぎる!!」', 'サンタの存在に心躍らせるドゥ。しかしジャヒーはサンタ捕獲を試練に!? 料理修行に励むドゥに新たな試練が迫る。人間好きな魔物との対決の行方は――。', '2026/02/02 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fdfba92-e486-4971-9859-7d92211f688c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da44c0b9-28a9-441c-aa42-27502e826168', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 5, '100247861', '「神の使いが迷惑すぎる!!」「神の使い (真) は血の気が多すぎる!!」', '人間の村で新たな試練を計画するジャヒーだが、村人はすでに苦しんでいた! 原因は“神の使い”を名乗る存在。そこに天界の天使が舞い降り、運命が動き出す。', '2026/02/09 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9126ddc3-8526-4d3b-8fc2-3f5071ea7b21.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('30a6e6b8-f62f-457d-ada1-d181523a5a24', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 6, '100247862', '「魔王の娘がイメチェンしすぎる!!」「〇△×は誘惑の魔女 (パリカー) の天職すぎる!!」', '「形から魔族化!」とドゥを変身させるジャヒーだが、結果は予想外!? 一方、職探し中の魔女サティはジャヒーに勝負を挑み、自らの天職を発見する!', '2026/02/16 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d98b267b-40d4-4940-845b-a931d2d31c5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e4b417a-3752-4136-b597-ed588a2f4e77', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 7, '100247863', '「恐怖の怪物がみにくすぎる!!」「霊怪楼はワクワクすぎる!!」「魔王の側近は考えすぎる!!」', '魔界を震撼させる怪物が現れ、外出中のドゥに迫る。一方、異界の旅館“霊怪楼”ではドゥたちがはぐれ騒動。真面目すぎるジャヒーの素顔も明らかに!?', '2026/02/23 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09d259d0-9f98-4734-9511-c6c644052e82.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62be66a7-0a94-4b70-8ea4-c30c7ef3d4df', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 8, '100247864', '「魔王の側近が落ち込みすぎる!!」「魔王の側近はお疲れすぎる!!」', '盗まれた宝物を取り戻すため、ドゥが奮闘! 働きすぎて倒れたジャヒーを看病するドゥの優しさが、彼女の心を少しずつ変えていく。', '2026/03/02 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a53cdaaf-1dd9-4f21-988e-736fea352d63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4e2090a-59b7-4edd-b45e-27c4cefdc462', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 9, '100247865', '「先代魔王が怖すぎる!!」「先代魔王がジジバカすぎる!!」', '破壊王･先代魔王ザレス来訪! ドゥの優しさが露見すれば魔城崩壊!? だが孫を前にしたザレスはデレデレに。魔族最恐の“ジジバカ”誕生!', '2026/03/09 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b841a012-1e70-4788-aad8-05f5e6286693.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('afa1220d-95f5-40fd-bc5c-145a07f4d621', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 10, '100247866', '「魔女の薬が効きすぎる!!」「勇者が頼りなさすぎる!!」', '魔女の薬でドゥがまさかの凶変!? ついに魔族らしい魔族に!? 一方、ポンコツ勇者との出会いが、ドゥの運命を大きく動かす。', '2026/03/16 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/87841be9-4652-493c-8436-d92860d232ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b630697d-e72c-4a40-b977-7b76af855d3c', '13c9fcc5-0d71-4c68-9e46-eb9965527840', 11, '100247867', '「魔王の嫁は娘が好きすぎる!!」「顔見せの儀がもうすぐすぎる!!」', '母ダハーカが帰還。ドゥ誕生の秘密が明らかに! 次期魔王お披露目“顔見せの儀”を前に、家族と側近たちはそれぞれの想いを抱く。', '2026/03/23 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4f0b0a3a-b04b-4a84-a864-836015ce1f6d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f05d66e0-5342-4088-965d-80f2ee7bad49', '魔王学院の不適合者 ～史上最強の魔王の始祖、転生して子孫たちの学校へ通う～', '', 'hulu', 'maohgakuin', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0d50bb80-5a60-469b-a24f-3bd84d8e3435.jpg?w=331&h=447&p=t', 'hulu', 2020, 2, 1, 'FINISHED', NULL, 112301, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 'f05d66e0-5342-4088-965d-80f2ee7bad49', 'hulu-maohgakuin-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5e6eeba-68bc-438c-8823-9f0a6a2dafe1.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('916b0368-728d-43ff-8614-b134e4418212', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 1, '100059176', '魔王学院の不適合者', '「―よく聞け。愛しき子孫どもよ。お前達の始祖は帰ってきた」二千年前、暴虐の限りを尽くした史上最強の魔王アノス。そんな彼の血を引く後継者、《魔皇 (まおう)》を育成するべく、現代の魔王学院では入学試験が行われていた。試験内容は生徒同士で決闘を行う「実技試験」。そこに現れたのは、二千年前に荒んだ世界に飽き、転生した暴虐の魔王アノスの姿だった。', '2020/07/09 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5e6eeba-68bc-438c-8823-9f0a6a2dafe1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('446c209a-bd1d-489d-9c5c-d619d694b0a4', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 2, '100059739', '破滅の魔女', '「殺したぐらいで死ぬなら、俺は二千年前にとうに死んでいる」 始祖としての莫大な魔力を有しているにも関わらず、《不適合者》の烙印を押されてしまったアノス。彼はそんな不当な扱いも意に介さず、圧倒的な実力を示し続け、班別対抗試験にはリーダーとして参加する事に。だが、クラスメイトは混血のアノスを認めず、班員はミーシャのみになってしまう。さらに対戦相手は、実の妹であるミーシャを《ガラクタ人形》と蔑む姉、サーシャ率いる班となった。', '2020/07/16 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fb79020-5bae-418b-ad54-bd8ada1d8649.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa08187f-9796-46cb-ab69-f5664a410bf5', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 3, '100060112', 'サーシャの真意', '「サーシャ……ただですむとは思っていないだろうな」「最後に、あなたに会えてよかったわ」。意味深な言葉を残したサーシャの真意を掴めぬまま時は経ち、魔王学院では特別授業として、七魔皇老アイヴィスによる大魔法教練が開催される。七魔皇老は始祖が自らの血を使い生み出した七人の配下。「くれぐれも失礼のないように」とエミリアに念を押されたアノスだったが、躊躇いもなくアイヴィスのことを呼び捨てにしてしまう。', '2020/07/23 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3a53ba70-8bbb-4e32-9e51-b6ecac9ac707.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e500ab86-c39a-436b-a55b-c3f4bc302f16', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 4, '100060429', '十五の誕生日', '「俺が魔王アノス･ヴォルディゴードだ」「十五歳の誕生日…。午前零時に私は消える…」。ミーシャが衝撃の事実を告げる。アイヴィス･ネクロンの掛けた魔法により、仮初めの生を過ごしていたミーシャは"本来は存在しない存在"であった。「十五年が私の一生」。それでいいのだと諦観する彼女にアノスは告げる。「俺には知らぬことが二つある。後悔と不可能だ」。《不適合者》が姉妹を縛り付ける悲劇を、理不尽を、いま粉砕する。', '2020/07/30 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb5958c2-498f-4189-b38e-5fe1caaa6b9a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6dfe561f-26a8-4e02-801a-081f1f578e6e', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 5, '100061061', '転入生', '「俺に抜けぬ剣など、この世に一本しかない」 ミーシャ、サーシャとの邂逅。アイヴィスとの激闘も記憶に新しい中、魔王学院では、七魔皇老をも打ち負かす実力者、《錬魔の剣聖》レイが転入生として現れる。レイは有能なリーダーのもとに就きたいと言い、アノス班に入ることを希望した。しかしアノスがこれを拒否。代わりに「相応の結果を見せれば配下に加えてやる」と条件を提示する。かくしてレイは班を結成し、アノス班と、班別対抗試験で真っ向勝負をすることに。', '2020/08/06 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/17766800-c3f3-41f6-b17e-c7fc2e4fec20.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69fa351a-3c1c-4ac0-87dd-950f597b1161', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 6, '100061533', '魔剣大会', '「一分で終わらせてやろう」班別対抗試験での活躍を認められ、アノス班に加入する事となったレイとミサ。その後、アノス家にて行われた祝勝会で喜びを分かち合ったのも束の間、魔剣大会への参加者として、レイとアノスが選抜されることに。再戦のチャンスが早くも訪れたと喜ぶレイとは対照的に、アノスは「何か裏があるのではないか」という疑念を拭いきれない。そしてミサの案内で七魔皇老の一人メルへイス･ボランと出会い、事態は加速していく。', '2020/08/13 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a78afe2d-9577-43b3-a888-f44ad8960592.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b7c7ebfc-0f50-46fe-a940-ca214e0f214c', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 7, '100062045', '母の言葉', '「嘘つきの行く末は、地獄だ」「皇族派がどんな罠を仕掛けてこようと打ち砕く」。そう決心したアノスは、父グスタから託された剣を手に、魔剣大会の一回戦へ臨む。また同時刻、選手控室にて己の胸元を強く押さえるレイ。いつもと様子が違うレイに対し、アノスは「首輪をつけられているな」と人質の可能性を感じ取る。魔剣大会の背後で蠢く、存在と陰謀とは一体。', '2020/08/20 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/90b23fc7-faa3-41dc-a65d-c8888b14d028.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e7483e9-76a5-41aa-91b2-8ffb9d49a23b', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 8, '100062626', '二人の決勝戦', '「今は俺とお前だけの時間だ」ディルヘイド魔剣大会決勝—アノスとレイが激突する。シーラを人質に取られ、実力を出し切れない状況へ追い込まれた両者は一つの決断を下す。そして決着の瞬間、突如舞台に巨大な魔法陣が出現。二人の周囲の景色は歪み、異次元空間へと飛ばされる。事件の黒幕が、遂にその姿を現す。', '2020/08/27 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8afa4296-e3ba-4281-9966-19c71d81b208.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d066f85-f3d3-414d-846d-16c397e1a039', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 9, '100063514', '勇者学院の謎', '「何を言っている。一秒で着く」魔剣大会も幕を閉じ、アノス達は勇者学院との交流授業のため、人間界･アゼシオンへと赴く。現地で各自行動をとる中、「調べ物がしたい」というアノスは、勇者学院へ向かい、“部外者立ち入り禁止”の学院内に堂々と侵入しようとする。するとそこに「ボクと一緒ならお咎めなしだぞ」といたずらっぽく笑う、勇者学院三回生エレオノール･ビアンカが現れ、特別に学院を案内してもらうことに。', '2020/09/03 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8321368-ce9a-4121-afa3-6dae45dd5eec.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e970703c-3804-4d00-8cdf-d95783ac96fc', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 10, '100064416', '学院別対抗試験', '「—あとは俺に任せておけ」アノス達は勇者学院との学院交流初日を迎えた。しかし“学院交流”とは名ばかりで、勇者学院の面々は、歓迎ムードとは程遠い雰囲気。魔王学院三回生首席のリーベストが魔法の発動に失敗すると、勇者学院の面々はくすくすと笑い声を漏らす。不愉快そうに表情を歪める魔王学院の生徒達。そんな状況をアノスの一言が切り裂く。「—相変わらず、罠を仕掛けるのが好きだな、人間は」。学院交流は、不穏な雰囲気で幕を開けた。', '2020/09/10 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cb9c2e11-6d0e-4f1f-b377-ab5f60b3cf70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f5f8be4-4a9b-4ada-96ee-11e39974a369', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 11, '100064787', '命の輝き', '「……ほう。なかなか歯ごたえのある者もいるようだな」学院別対抗試験第二戦が開始された。ハイネ達に敗北したリーベストの悔恨を引き受け、アノス達は勇者学院の面々と対峙する。作戦は必要なら考えると、莫大な魔力を用いて、正面から相手を叩き潰しに行くアノス。たが、都市を覆う結界『デ･イジェリア』と、少女･ゼシアの聖剣エンハーレの斬撃によって攻撃は防がれてしまう。そして次なる攻め手に欠ける状況下で、ミーシャがある打開策を提案する。', '2020/09/17 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72ebdb5a-3a95-4045-a9df-33e752566c9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('50d76728-b0b5-44e3-a36f-e31453967cf8', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 12, '100065251', '禁忌の魔法', '「全員まとめて、幸せにしてやればいいのだろう?」「お願い。ゼシアはボクにしか止められないぞ」。ディエゴによって瀕死まで追い詰められたミーシャを抱き上げ、神殿の奥間へと向かうアノス。そこにはエレオノールの姿があった。自身が“魔法そのもの”であるという彼女は、その真意について、そして勇者学院の狂気に満ちた真実について語っていく。', '2020/09/24 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20399358-e91a-42bf-8636-d1b569fff004.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57ea2e7d-56b3-4b8f-8539-94c2bd6d39a1', '9d67792d-72ea-4dd9-b48c-c6f4bd115d4c', 13, '100065493', '世界が愛に満ちるように', '【シーズン1 最終話】「生きよ!! 魔王が戻る、その日まで……!!」全ては二千年前から始まっていた。黒い仮面の男･アヴォス･ディルヘヴィアの正体が明らかになり、事態は急転する。二千年を経ても癒えぬ魔族と人間の禍根。その果てに、暴虐の魔王アノス･ヴォルディゴードが取った選択とは――。', '2020/10/01 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24ee9d4b-322b-44bb-9946-0c0683485217.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('fc61131d-0ffe-4e07-ae51-076b4a4ec353', '魔王軍最強の魔術師は人間だった', '', 'hulu', 'the-strongest-magician-in-the-demon-lords-army-was-a-human', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e57a2724-f68f-4b47-98be-de7454ba0777.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 173584, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('09921c66-33ca-4b50-9404-e6b0997baf70', 'fc61131d-0ffe-4e07-ae51-076b4a4ec353', 'hulu-the-strongest-magician-in-the-demon-lords-army-was-a-human-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daca3269-0232-4a73-afec-84a594623b55.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2218d8ce-e5a1-4b00-846e-c5cb126204af', '09921c66-33ca-4b50-9404-e6b0997baf70', 1, '100190445', '不死旅団長アイク', '人間と戦いを続ける魔王軍。その不死旅団の団長･アイクは、難攻不落といわれた交易都市を1週間で陥落させるほどの実力者だ。偉大な大魔術師ロンベルクの孫として多くの魔族から一目置かれるアイクだが、その正体は人間。バレたら大変と、正体を隠し通そうとするが……。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daca3269-0232-4a73-afec-84a594623b55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb8a0136-2a81-4d8a-af6b-b4a7903a39bf', '09921c66-33ca-4b50-9404-e6b0997baf70', 2, '100191077', '白薔薇騎士団長アリステア', '魔王軍に攻め込まれたローズアリア王国は、近隣国と同盟を締結し状況を打破しようとしていた。さらに、ローズアリア軍はその同盟の行動よりも先に、魔王軍に打って出ようとしているらしい。それを知ったアイクはその襲撃を阻止しようとするが――。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3b1fab6-80fc-461f-8f5c-26c988011544.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bee80d4a-16c7-4df4-9a4c-ca621d8cd1ee', '09921c66-33ca-4b50-9404-e6b0997baf70', 3, '100192067', '裏切者', '戦いでアイクを背後から襲ったのは、ローズアリア軍の白薔薇騎士団の矢だった。自陣に暗殺に加担した者がいる――。その正体を探るべく、白薔薇騎士団の団長･アリステアが囚われた塔へとやってきたアイクは、そこで彼女から「人間ではないか」と詰問される。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/328bf972-de26-41b8-a0a3-c0320ee60eb1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('38f24df1-d54a-4ef2-86ed-779d7aeb73c9', '09921c66-33ca-4b50-9404-e6b0997baf70', 4, '100192670', '決闘', 'アイク暗殺の首謀者は、魔王軍第三軍団長のバステオだった。それを認めないバステオに、魔王はアイクの直属の上司･セフィーロとの決闘を申し付ける。勝ったほうが正義であり、負けた者には死を。そんな生死を賭けた戦いに、セフィーロはアイクを代理人として出すと宣言する。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/673f2950-062b-431f-b530-a538dc02c771.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b92cae1-ca24-4591-9670-08b996256f38', '09921c66-33ca-4b50-9404-e6b0997baf70', 5, '100193820', '野望', 'アイクとバステオの決闘は、最初こそバステオが有利だったものの、アイク軍が銃を使ったことで形勢が逆転。ついにバステオは追い詰められた。魔王から、「潔く自害するか」「自分に殺されるか」の二択を迫られたバステオだったが……。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84b98346-4270-44d8-90c0-e3329055e7fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68ff9079-b8f2-4051-b768-0cee18343989', '09921c66-33ca-4b50-9404-e6b0997baf70', 6, '100194402', 'ドワーフ王', '魔王にイヴァリアスを魔族と人間が共存する最初の町にすると約束したアイク。まずは農地を休ませない四輪農法をはじめることにする。ところが、ついに諸王同盟軍が動き出し、魔王軍の第二軍団がやられたとの連絡が入る。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/516f1575-d9c3-4654-8b64-b317ca4bf049.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc789ef8-bc4e-411e-976f-0061447381ab', '09921c66-33ca-4b50-9404-e6b0997baf70', 7, '100195259', '開戦', '諸王同盟軍との戦いの全権をセフィーロから任されたアイク。魔王軍の6倍ほどの人数を率いるという諸王同盟軍に対し、アイクはイヴァリアス城で迎え撃つ作戦に出る。アイクの狙いは、最短、最小限の被害なのだが……。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10568828-7410-456c-88da-e20a3417c979.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cef1954-8b19-4beb-af38-5cfa1d5bc3be', '09921c66-33ca-4b50-9404-e6b0997baf70', 8, '100195896', '決戦イヴァリアス', '魔王軍と諸王同盟軍の戦いが始まった。味方を巻き込むことも厭わない諸王同盟軍将軍の指揮に対し、アイクは冷静に“シフト制”を用いて立ち向かっていこうとする。攻め込ませる隙をわざと作り、自軍に有利に事を運ぼうとするアイクだが……。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1dfc8e78-eeed-43b6-bf23-9fe5218a229a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6f44bcf-52bf-49f3-a8d0-5b109ce278ac', '09921c66-33ca-4b50-9404-e6b0997baf70', 9, '100196670', '交渉', '見事、諸王同盟軍を撃退したアイク。そんな彼に次に下された命令は、食糧不足を解消するために貿易都市ゼノビアで人間と通商条約の直接交渉をしてこいというものだった。人間と魔族が交渉をする難しさを感じながら、アイクはイヴァリアスを旅立つ。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/707e3c7e-ece8-4d9f-a1c7-990c807dc289.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91870234-f32b-424a-8386-e20f80e469f9', '09921c66-33ca-4b50-9404-e6b0997baf70', 10, '100197851', '海賊', 'ゼノビアを襲う海賊にサティがさらわれた。アイクが慌てて船を調達し追いかける一方、サティは船の中で、ゼノビアの街から盗まれた品々を発見する。なんとかアイクに気づいてもらいたい……そう考えたサティはランタンを使って船を見つけてもらえるように策を練る。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5e08f09-12f0-43e2-97cc-f54e4f59abe1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8d13802e-4bd9-4ef6-9982-7ebebaa9100d', '09921c66-33ca-4b50-9404-e6b0997baf70', 11, '100199154', 'セフィーロ、討たれる', '諸王同盟軍の総攻撃が始まった。ゼノビアにいたアイクは、魔王からセフィーロがアレスタ城に閉じ込められていると聞かされ、慌ててイヴァリアスへと帰還する。そこからセフィーロ救出に向かおうとしたアイクだが、兵力もほとんど残っておらず……。', '2025/09/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e0aec821-aa21-466a-8982-64285cc528fb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('76560fa1-8f08-4c4f-8567-59c7cfcace90', '09921c66-33ca-4b50-9404-e6b0997baf70', 12, '100199685', 'エ･ルドレ将軍', '【最終話】セフィーロが囚われたアレスタ城へアイクが現れたことで士気が上がる魔族たち。しかし、傷ついた者も多く、戦いでは不利な状況が続く。ところが、その戦況を覆す者が現れる。その正体は、イヴァリアスの住人で、アイクを慕って戦いに志願した人間たちだった。', '2025/09/27 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08787249-2e38-4251-b958-21bcb397fb11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('62c142f2-98c9-4e89-bba1-ef1b8a9cbdb4', '魔王城でおやすみ', '', 'hulu', 'sleepy-princess-in-the-demon-castle', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b6bdbc9-b932-49e0-bd6f-5d0a74c1d429.jpg?w=331&h=447&p=t', 'hulu', 2020, 3, 1, 'FINISHED', NULL, 111428, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ee583f8e-a036-4bfa-a928-6950aaf4f125', '62c142f2-98c9-4e89-bba1-ef1b8a9cbdb4', 'hulu-sleepy-princess-in-the-demon-castle-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a9f7ed6-862a-4b43-865b-3ccc7fde1054.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f95319f6-b5ce-4858-b7de-b7fa59628c17', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 1, '100066649', '眠れぬ城の姫', 'かつて、人と魔が交わり、共に存在した時代。人間の姫であるスヤリス姫は、人間に敵対する魔王タソガレによってさらわれ、魔王城に幽閉される。牢の中でベッドに座った姫はつぶやく。「…寝る以外…することがない」。しかし、寝具の質は悪くて安眠できた試しがない。眠ることが大好きな姫は快適な寝床を手に入れると決め、たった一人、魔王城探検へと出発するのだった。', '2020/10/12 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a9f7ed6-862a-4b43-865b-3ccc7fde1054.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('966b139b-92f7-48a0-a6e2-7a10a61bae17', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 2, '100066874', '姫と怒りのモフモフ', '魔王城の塔の上に、姫がいた。今日の姫の目的は、安眠を脅かす蚊対策! 壁を歩けるネコスタンプの靴を借りて頂上まで登ると、塔のでっぱりに紐をくくりつけ、かいぶつふろしきで作った蚊帳をつるしてセッティングは無事完了。ただひたすらに安眠を求める姫の行動は、日々エスカレートしていく。そんな姫に苛立ちを覚えるレッドシベリアン･改。囚われの姫は人質らしくするべきだと、魔王城法典に従わせようとするが…。', '2020/10/19 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/215466c6-fa3c-4233-a247-10bdebe17d78.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bffb37e4-f2c0-47db-9681-54c2f24561a7', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 3, '100067324', '姫と禁断の叡智 (あれこれ)', '難しい本を寝る前に読めば、よく眠れるに違いないと思いついた姫。地下書物庫に忍び込んでさっそく実践するが、MPが吸い取られるばかりで全然眠れない。ところが、うっかり禁断の魔導書の封印を解いてしまい、偶然にも魔導書の精霊･アラージフをゲットする。アラージフは、どんな魔法でも与えてくれると言うので、姫は最強の睡眠魔法を教えてもらう。だが、本人には効かないようで……。', '2020/10/26 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af475f0a-5b47-4557-a103-fc67058afa96.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84367402-9d95-4118-a5c3-0588e03b0fc4', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 4, '100067592', '姫と破壊と小さな冒険', 'スヤリス姫の新たな悩みのタネは、お風呂がめちゃくちゃ狭いこと。この魔王城で、ゆったりお風呂で眠るという長年の夢を叶えたいと思い、さっそく行動を開始。まずはお湯の確保へむかうが、行き先は魔物用大浴場で、風呂に入っていた魔物たちは大混乱。次に浴槽の確保と思っていたところ、大きな甲羅のロケットタートルが現れる。レッドシベリアン･改は、その魔物の側では火気厳禁だというが……。', '2020/11/02 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3c3ba383-5513-4b10-9073-32ac395f87ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df82082d-29e4-41ec-87b5-009c5810df3b', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 5, '100068556', '姫と戦う女たち', '魔王軍女部隊の帰還により、騒がしくなる魔王城。人間と仲良くなりたいハーピィが、姫の牢へとやってきた。しかし姫は、新しい布団を作ることしか頭にない様子。どれだけ話しかけてもつれない姫に、ハーピィも負けじと女子トークを繰り広げるが、なかなか距離は縮まらず…。自分が魔族だからイヤなのか、と思うものの、それでも友達になりたい! と気持ちを伝えると、姫はその背中を見てハッとして…。', '2020/11/09 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a3cd594-3625-44d3-a459-41f36955455a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28035f66-b8ca-42b7-b785-345fdf9fc7a3', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 6, '100068843', '姫の迷いなき選択', 'ベッドに寝ころんだために、お気に入りのシーツにジュースをこぼしてしまった姫。「今宵の安眠のためにすぐに布団を洗わなくては!」とさっそく行動開始。城内を歩き回る。そんな中、魔王は魔王城の幹部である十傑衆を集め、勇者の迷子問題を解決しようと対策会議を開いていた。そこへ現れたギミックのプロ･ギアボルト博士は、不敵な笑みを浮かべ、秘密兵器の存在を明かす…。', '2020/11/16 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/24119916-d2d6-457f-885b-6e652235a530.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f102685-5043-4ab6-9c28-1859446dce58', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 7, '100069497', 'もっと眠れぬ城の姫', '囚われの姫が再びさらわれた!? 犯人は、魔王の座を狙う反乱分子、ハデスだった。彼が住む旧魔王城の牢の中で、姫はつぶやく。「…寝る以外…することがない」。だが、枕は絶望的に質が悪かった。新たな寝具を求めて牢の外へ踏み出した姫は、罠だらけの中で眠る魔物、睡魔と遭遇する。その堂々たる眠りは、まさに眠りの師匠! すっかり意気投合した姫は、姫奪還のために必死な魔王たちとは対照的に、次々に快眠を手に入れていく。', '2020/11/23 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f9819eb-268d-47d2-a45b-aac44925554f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc4f334d-59e8-474e-982e-0ca673779f38', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 8, '100070053', '姫と魔族の恐るべき悪夢', '囚われの姫を救うべく冒険を続ける勇者たち一行は、魔王城との空間をつなげる術を試そうとしていた。その勇者との戦いに出向く、古の大火山のボス･かえんどくりゅうのため、壮行会を開く魔王たち。そこに現れた姫は、自分が見た悪夢の話を始める。その内容は、姫の小さい頃の思い出で、幼馴染である『アなんとか君』とのとある出来事だった。強烈すぎる『アなんとか君』の正体とは…!?', '2020/11/30 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05573abe-4241-4cde-89a2-a644da73b553.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2731970e-5115-4149-9cd6-bccdd5d45d25', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 9, '100070912', '姫と人質強化週間', '魔王城の食堂のテレビになぜか映る、人間界の通販番組『ヒューマンズショッピング』。その番組で紹介されたウォーターベッドをさっそく注文する姫。しかし、魔王城が配達エリア外であることを知り、怒りに任せて通信機を破壊する。最近の姫の行動が目に余ると苦言を呈する改に、魔王も甘やかしすぎたことを反省し、人質らしさを強化するための『人質強化週間』として、姫をみんなで無視するが…?', '2020/12/07 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7cbf31b9-b8e7-485f-8158-be1ec657348c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9cc6a5dc-cf6a-4eda-a268-2d5534fa9781', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 10, '100071567', '姫とオワリノシティ', '姫の脱走が今回はいつになく本気モード。ついに魔王城から脱出する気になったのか!? と、大慌てで捕まえようとする魔王たちだが、姫はものともせずに突き進む。脱走した目的は、人間界でしか手に入らない安眠グッズの購入だった。やっとの思いで姫を捕らえた魔王達。それなのに、姫の提案に乗せられて、魔王たちも人間界に一緒に行くことになり……!?', '2020/12/14 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4187f690-cc5f-4c3c-9928-825d6255d28c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1fa263e6-5037-4c77-83d9-a185edc1f50f', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 11, '100071806', '姫の眠れない夢', 'ハーピィからパジャマパーティに招待された姫は、練習の為に魔王の部屋へ押しかける。パジャマパーティをよく知らない姫は、魔王にエスコートを依頼しに来たのだ。その必要は無いと必死に説得する魔王だったが、恋愛の話題になり、突如ドギマギしてしまう。しかし、恋バナとは無縁の姫はすっかり興味を失い、だんだん眠くなってくる。そんな魔王の部屋に近づいてくる足音が…。', '2020/12/21 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8e2fe399-30d6-45be-9b70-b4e9f03a161f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1faac4f0-bf8b-439f-a864-1d495f90b4cd', 'ee583f8e-a036-4bfa-a928-6950aaf4f125', 12, '100072135', '魔王城の眠り姫', '【シーズン1 最終話】クリスマスが近づき、魔王城に雪が降り出した。姫は嬉しそうに空を見つめ、サンタクロースへメッセージカードをしたためる。何をリクエストしたのか気になる魔物達。再び脱走されても困るということで、こっそり中身を確認すると、「サンタさんへ。実家に帰りたいです」と書かれていた。姫がホームシックになったのかと思い、魔王達は心配になってきて……。', '2020/12/28 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb0e1038-90e9-4663-80f6-18262d2caced.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('8a445cd1-3f4c-42f1-84a3-ce8e56bb1396', '魔王様、リトライ!', '', 'hulu', 'maousama', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2015e25-6624-40cc-afe2-4c45238c9b7c.png?w=331&h=447&p=t', 'hulu', 2019, 2, 1, 'FINISHED', NULL, 104252, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7c7ba9af-f1a0-4b4a-af88-586c2d31d305', '魔術士オーフェンはぐれ旅', '', 'hulu', 'ssorphen', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2e9453ff-7aa3-4879-8cb2-14eb6fb216d7.jpg?w=331&h=447&p=t', 'hulu', 2020, 0, 1, 'FINISHED', NULL, 101367, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('bd03b305-b9ee-476a-9aec-3a30a70da53c', '7c7ba9af-f1a0-4b4a-af88-586c2d31d305', 'hulu-ssorphen-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3dd24bc1-7e99-45b7-a2db-12990af57f84.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54bb4075-fb3b-4825-83a8-3f001c0b99cf', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 1, '100048540', '追憶の呼び声', 'かつてはドラゴン種族が棲息し、現在は人間種族が繁栄する地、キエサルヒマ大陸。魔術士養成機関《牙の塔》で暮らしていた少年･キリランシェロは、異形の姿となって失踪した義姉･アザリーを探すために旅に出る。それから五年。男はオーフェンと名乗り、モグリの金貸し業を営んでいた。ある日オーフェンは、地人種族のボルカン、ドーチンとともに、エバーラスティン家の令嬢への結婚詐欺をするはめになる。', '2020/01/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3dd24bc1-7e99-45b7-a2db-12990af57f84.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85cf4e5a-255d-492d-ada5-cf44dcf24479', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 2, '100048993', '牙の塔', '異形の姿のアザリーとついに再会するが、逃げられるオーフェン。オーフェンはかつての師･チャイルドマンから、五年前にアザリーが異形と化した原因を知らされる。それは、古代遺産･バルトアンデルスの剣を使った魔術実験の失敗によるものだった。アザリーを抹殺すべく行方を追うチャイルドマン達に、オーフェンは同行する。命を懸けてもアザリーを守るという決意を胸に秘めて。', '2020/01/22 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f8f13544-d6d6-420e-8658-24b4ff36b88b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('298b2eec-100a-4a04-8a42-dcd4c4a1e28e', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 3, '100049320', '我が呼び声に応えよ獣', 'チャイルドマン率いるアザリー討伐隊とオーフェンは、異形の姿のアザリーを見つけ出す。襲い来るアザリーにオーフェンの声は届かず、討伐隊は次々に殺されてゆく。対決するチャイルドマンとアザリー、その双方の魔術を防ぎながら、アザリーを救うために説得を続けるオーフェン。しかし、チャイルドマンはとうとうアザリーを倒す。死にゆく怪物を見取るオーフェンは、ある違和感を覚えて…。', '2020/01/29 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3993d086-9e74-4dee-8345-72b84ec26a5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6845c928-9c8a-4dea-a1e3-48292969cf77', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 4, '100049633', '天魔の魔女と鋼の後継', '五年前、オーフェンがキリランシェロという名で《牙の塔》にいた頃。《牙の塔》の教師･チャイルドマンが指導するチャイルドマン教室には、キリランシェロ、ハーティア、コミクロン、アザリー、レティシャ、フォルテ、コルゴンの七人の生徒が在籍していた。ある日、キリランシェロとアザリーは墓参りのために廃村を訪れる。そこに突然現れた襲撃者が、アザリーをさらったと告げてくる。', '2020/02/05 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96127796-d5cb-4188-9333-a620335e28d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea326e02-2baf-44c0-814b-55d9871a3abb', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 5, '100050260', 'ディープ･ドラゴン', 'オーフェンはおしかけ同行者のクリーオウ、マジクと共に、《牙の塔》のあるタフレム市を目指して旅を続ける。一行は道中、フェンリルの森と呼ばれる大森林の中を通る。食糧を探すマジクは、そこで巫女フィエナと出会う。近くにはドラゴン信仰者の隠れ里「偉大なる心臓」があり、マジクは住人達に捕まってしまう。マジクを助けに向かったオーフェンは、教祖マクドガルと対峙し、追いつめられるが…。', '2020/02/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd322db2-51a0-4b99-9a6d-ee9f1f2e2c08.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a89e2621-f68c-4227-b49c-2d28e9f0cd9e', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 6, '100050813', '《森》の巫女', 'マクドガルと対峙するオーフェンの前に、突如現れるディープ･ドラゴン。オーフェンはディープ･ドラゴンの魔術を受けるが、フィエナの癒しの力で命拾いする。明日はマクドガルがドラゴンの聖域に向かう日で、その目的のためにフィエナは犠牲になろうとしていた。フィエナを助けたいマジク。フィエナはオーフェン達に、このまま里から逃げるように告げるが…。', '2020/02/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2d8706b3-f3ff-4bc8-b085-c9451e2b196d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('149c31f8-afa2-4129-9d6d-a005691bbe79', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 7, '100051038', '我が森に集え狼', 'オーフェンはフィエナを助けるために、マクドガルに戦いを挑む。その戦いの中、オーフェンはマクドガルがキムラック教会で見たある出来事のために、ドラゴンの聖域で強力な力を得ようとしていたことを知る。マクドガルの意思を継ぎ、ドラゴンの聖域で強力な力を得ようと意気込む村人たち…。その時、マクドガルや村人達がドラゴンの聖域に入ろうとするという禁忌を犯したことにより、ディープ･ドラゴンが村を滅ぼしにオーフェンたちの目の前に現れる。', '2020/02/26 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f76a02c1-6e38-421d-b61f-1246302d1ce5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8448f82-517a-4b44-b69c-b12239105cd4', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 8, '100051296', '唐突の暗殺者', 'ディープ･ドラゴンの子供であるレキを加えたオーフェン一行。道中、一行は謎の暗殺者に襲われる。暗殺者の顔は昔のオーフェン、キリランシェロにそっくりだった。オーフェンは義姉レティシャと再会し、一行は《牙の塔》のある街タフレム市に着く。街では《牙の塔》の長老達が暗殺される事件が起きていた。オーフェン達がレティシャ邸に泊まったその晩、オーフェンの前に現れた暗殺者は、自らをキリランシェロと名乗る。', '2020/03/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7b786120-efdf-44b5-b8c4-5fd6db46dbd7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4316d6b-f0c5-46ce-a91d-0e097dc112cb', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 9, '100051634', '過去の亡霊', 'レティシャはキリランシェロ達との、《牙の塔》時代のことを思い起こす。レティシャはキリランシェロとアザリーがいなくなってからの五年間、ずっと帰りを待っていた。レティシャはその思いをオーフェンに吐露する。そこに、クリーオウがさらわれたとの知らせが入る。オーフェンはクリーオウを助けるため、暗殺者の待つチャイルドマン邸に向かう。', '2020/03/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6246882d-0cc1-4ce8-af3a-3180a33b42a0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91f570b4-c422-40cd-a2c8-f14454d79762', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 10, '100052280', '我が過去を消せ暗殺者', 'チャイルドマン邸に乗り込んだオーフェンは、暗殺者との戦闘を開始する。そして暗殺者はその正体を明かす。暗殺者は天人種族の遺産である殺人人形を、アザリーが自分の理想の通りの暗殺者に変化させた物だった。アザリーはキリランシェロそっくりの人形とオーフェンを戦わせることで、オーフェンを昔のようなキリランシェロに戻そうとしていたのだった。オーフェンは人形を通して、過去の自分と向き合うことになる。', '2020/03/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7c11993d-113d-4f0e-bcf9-f7b2c138cd70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e5fb733b-e385-482b-9944-d5badc9ca25a', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 11, '100052751', 'ウオール教室', 'チャイルドマン邸での戦闘で負傷したオーフェンは、レティシャ邸で休んでいた。その夜、屋敷に侵入してきた暗殺者《スタッバー》に襲われる。翌日、少しでもオーフェンの力になりたいと願うマジクと魔術士学校へ向かう道中で、過去、オーフェンと因縁があった最高執行部ハイドラントが現れる。さらに、オーフェンの《牙の塔》でのかつての師であり、《牙の塔》の実権を握ろうと目論むウオール･カーレンが現れる…。', '2020/03/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b8f3d1c-1705-4869-90ce-a70fd359ea6a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8b4d0a13-333d-482e-9944-1edc4c2f797b', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 12, '100053118', '死の絶叫', 'マジクは《牙の塔》への入門申請を済ませる。オーフェン達がレティシャ邸に戻ると、クリーオウが何者かに襲われていた。襲撃者を追ったレティシャは返り討ちに遭ってしまう。その夜、オーフェンの前にアザリーが現れ、ウオール一派はチャイルドマンが持っているはずの「世界書」を探しており、チャイルドマン教室の者達を狙っていると伝える。それを知ったオーフェンは自らウオール･カーレン達のいる《牙の塔》に向かう。', '2020/04/01 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e410fd60-4244-4869-9ee0-6a70678d844a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('83e817c6-1941-45a5-8084-f61a064fe4fb', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 13, '100053366', '我が塔に来たれ後継者', '《牙の塔》に潜入したオーフェン達は、待ち構えていたウオール･カーレンの部下達と戦闘になる。敵を制したオーフェンは、ウオール･カーレンと対峙する。そこにフォルテとアザリーの加勢により、ウオール一派を捕らえ、罪を糾弾することに成功した。アザリーはチャイルドマンが持っていたはずの「世界書」を手に入れ、次はキムラック教の総本山であるキムラック市に行くとオーフェンに告げる…。', '2020/04/08 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/137a7e1c-d538-4d35-ad94-6f907b52a6cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2339b4f4-e505-45c4-8eae-bf03c03f2fbd', 'bd03b305-b9ee-476a-9aec-3a30a70da53c', 14, '100054442', '天人の遺産', '【シーズン1 最終話】アザリーは、チャイルドマンが何をしようとしていたかを突き止めるべく、バルトアンデルスの剣と「世界書」を携え、キムラックへ出発していた。一方、アザリーとの決着をつけるために、一人でキムラックへ向かおうとするオーフェンだったが、クリーオウ、マジクと供にキムラックへ向かうことになり、レティシャ邸を後にする。はたして、オーフェンたちの旅の行く末は…。', '2020/04/15 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9915893f-abd9-4aa5-a9e8-f980ee62a0f4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3789c83d-5931-49cd-9f5c-9e449ad75ee3', '魔術士オーフェンはぐれ旅', '', 'hulu', 'sorcerous-stabber-orphen-battle-of-kimluck', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0f4f76eb-3cbc-4b77-976f-c82de916ba86.jpg?w=331&h=447&p=t', 'hulu', 2020, 0, 1, 'FINISHED', NULL, 101367, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cad98324-a92b-4455-9de7-f9f23f19c094', '3789c83d-5931-49cd-9f5c-9e449ad75ee3', 'hulu-sorcerous-stabber-orphen-battle-of-kimluck-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4cc6946-b1c3-40a9-97cb-76e61a3cf265.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('69097ad5-0654-44f9-bc77-fba89174ac1f', 'cad98324-a92b-4455-9de7-f9f23f19c094', 1, '100073828', '我が遺志を伝えよ魔王', 'アザリーを追い、キムラック市へ旅を続けるオーフェン一行。道中、怪物に襲われていた盗賊団の男達と遭遇する。オーフェン達も怪物に囲まれ、なんとか劇場内に逃げ込むと目の前に現れたのは盗賊団の首領女･剣士メッチェン。彼女は魔術士と敵対するキムラック市への進入を手助けする交換条件として、遺跡探索の協力をオーフェンに持ちかける…。', '2021/01/27 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4cc6946-b1c3-40a9-97cb-76e61a3cf265.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3132b5ce-0eac-478f-b6a2-7ba650615868', 'cad98324-a92b-4455-9de7-f9f23f19c094', 2, '100074487', '彼にとっての天使と悪魔', 'メッチェンと共にカミスンダ劇場の探索を続ける事になったオーフェン一行。ところが地下で待ち受けていた殺人人形 (キリングドール) の襲撃を受け、クリーオウ、マジク、メッチェンが連れ去られてしまう。仲間を救出する為に奥へと進むオーフェンの前に、再び立ち塞がる殺人人形 (キリングドール) が語り始め衝撃の事実とは!?', '2021/02/03 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/848ffdce-c9e8-4a21-96f9-ea369bf49dd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('489552a3-65c5-4d4c-ad9f-70d57f295dd0', 'cad98324-a92b-4455-9de7-f9f23f19c094', 3, '100075326', '魔術士を拒む街', 'キムラック行きの準備を整えるオーフェン一行だったが、クリーオウとマジクを危険に晒さない為に、オーフェンはメッチェンと二人きりでキムラックへ出発する。その道中、メッチェンの目的は不満が蔓延する現体制を改革し、〈死の教師〉のリーダーであるクオの暗殺を企んでいることを知る。同じ頃、キムラックへ到着したアザリーも神殿街への潜入を試みていた…。', '2021/02/10 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d10fb23-3712-4f2f-b8d2-e7c8a34726fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7ea6ed1-d99b-4030-bf27-4d10b99c1c58', 'cad98324-a92b-4455-9de7-f9f23f19c094', 4, '100075714', 'シスター･イスターシバ', '街で騒ぎを起こしたオーフェン達は、ラニオットという男に助けられ隠れ家に匿われていた。彼は自分を王都から派遣されたスパイだと告げ、オーフェンに協力を申し出る。秘密の地下道からキムラック神殿街への潜入を図るオーフェン一行とラニオット。一方、アザリーは「世界書」を読み、世界の秘密に触れてゆく…。', '2021/02/17 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e51204e-4b3f-45f9-8305-436027346632.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7b168ed4-06f3-4502-8abc-887380351f56', 'cad98324-a92b-4455-9de7-f9f23f19c094', 5, '100076069', '我が聖都を濡らせ血涙', 'キムラック神殿街を目指し地下道を進むオーフェン一行。途中、不意の鉄砲水に襲われ、離れ離れになってしまうオーフェンとクリーオウ、マジク…。一人になったオーフェンの前に現れたラニオットは、自らを「死の教師ネイム」だと明かし、オーフェンに襲いかかり、狂信的な強さでオーフェンを圧倒する。一方マジクは、追って来た教会の神官兵に囲まれ、追いつめられるままに魔術を乱発してしまう。', '2021/02/24 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbbd95f6-f5b6-4b82-ac2c-f4d6f7cb31d7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e73667a9-0e69-4bed-a99a-cd9fd661c06d', 'cad98324-a92b-4455-9de7-f9f23f19c094', 6, '100076566', '死の聖なるかな', 'オーフェンは初めておかした殺人に激しく取り乱す。その顛末を知ったキムラック教･教主ラモニロックは最強の暗殺者クオにオーフェン抹殺の指令を出す。その頃、アザリーは読み終えた世界書を燃やすと、一人でキムラック教会の神殿に向かっていた…。', '2021/03/03 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52c7bc4d-bbf2-4a69-a35c-a5537f6405fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bfcc8f9e-828b-4c50-ae3c-7120336ee46d', 'cad98324-a92b-4455-9de7-f9f23f19c094', 7, '100077405', 'その魔術が彼を殺すと', 'マジクが魔術を制御できない事を見抜いたオーフェンは、魔術の使用を禁じる。しかしマジクは自分を半人前扱いするオーフェンにイラ立ちを募らせてゆく。一行が地下道を出るとそこは牢屋で、サルアが捕まっていた。サルアと共に牢を破ると、追手がすぐ背後に迫る。すかさず魔術を構成するオーフェンだったが、その魔術は…。', '2021/03/10 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/367437ed-452f-4ef8-afa6-58df31800002.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('06c85103-9441-4763-ad0e-d06f8937eccd', 'cad98324-a92b-4455-9de7-f9f23f19c094', 8, '100077685', '詩聖の間', 'オーフェン達とサルアが地下牢をぬけた先は神殿の地下にある「詩聖の間」。そこにはクオと教会の兵達が待ち構えていた。マジクは魔術が使えないオーフェンの代わりに懸命に戦うが、クオの力の前に圧倒される。激闘の中で、「詩聖の間」への扉が崩れ、オーフェン達はその中に異様な光景を目撃するのだった。', '2021/03/17 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6ffe58a-4718-4a2a-84db-ec3ebd56f712.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d53391d-c9f2-4c59-ba73-a1db647bc7f4', 'cad98324-a92b-4455-9de7-f9f23f19c094', 9, '100078191', '死の教師たち', '銃で撃たれ、地底湖に沈むオーフェンは意識下でイスターシバと名乗る女性とある男性、2人の光景を目にする。アザリーは転移装置を渡してクリーオウ達を逃がすと、オーフェンを追って地底湖に飛び込む。クリーオウ達はサルアの兄ラポワントの屋敷に逃げ込み、メッチェンと再開する。だがそこにはカーロッタの魔の手が迫る。その頃、クオは女神の意志にそぐわないラモニロックに、刃を向けていた…。', '2021/03/24 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/455987d3-5062-4889-bd01-c9f3ff10b023.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f2f4bde-ee2c-46d8-a0c4-9e8c8122d39b', 'cad98324-a92b-4455-9de7-f9f23f19c094', 10, '100078652', '彼女を殺せる唯一の', '「詩聖の間」でラモニロック、クオと対峙するオーフェン、アザリー。ラモニロックの真の目的は、女神が世界を滅ぼす前に、その怒りの対象である人間の魔術士を根絶することだった。そしてついにラモニロックの口から隠されていた世界の真実が語られる。戦いはさらに過熱、クオの刃がアザリーを切り裂く…。', '2021/03/31 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/774e2a99-2a41-4836-8aed-a2dbab8d542e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e31bd81b-87c3-4006-b80e-815fa85c1479', 'cad98324-a92b-4455-9de7-f9f23f19c094', 11, '100079404', '我が神に弓ひけ背約者', '【シーズン2 最終話】イスターシバの予言した大陸に迫る破滅の危機とは、女神の襲来だった。自分を取り戻したオーフェンは再び魔術を使えるようになり、アザリーと共にクオと戦う。そこにクリーオウ、マジクたちも駆け付ける。追い詰められたクオは女神の教義を全うする為、女神を食い止めるオーリオウルの頭を貫く。そして、ついに女神が結界を越える…。', '2021/04/07 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce11a4b7-ce80-411a-ae3f-7d0d2703be0d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1d31464d-434b-45c9-b92a-a2c41cd3f27c', '魔女と野獣', '', 'hulu', 'witch-and-the-beast', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/34fe285e-362f-49b5-9fb7-85a40c150490.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 153818, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', '1d31464d-434b-45c9-b92a-a2c41cd3f27c', 'hulu-witch-and-the-beast-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63a32afb-ac2c-4966-9265-6e776fd623c5.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cfd7a773-9417-4f04-a940-702783ded7e4', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 1, '100171846', '【魔女と紅蓮の街】', 'ギドとアシャフがたどり着いた先は、「魔女･イオーネ」がいる街であった。その日はイオーネにとって「記念日」であり、屋敷でパーティーがあることを知る2人。しかしその「記念日」に疑念を抱いたアシャフは、イオーネについて調べるが――。', '2024/01/15 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/63a32afb-ac2c-4966-9265-6e776fd623c5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('928d63a3-38d9-4518-8b5b-6b232667452a', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 2, '100172641', '【魔女の戯れ －序幕－】', '平和な日々に不満が募るギド。そんな中、教団から黒い封筒が届き、2人は急遽ハイデンに向かうことに。魔女による連続殺人が起きており、さらにその事件では「あるモノ」が関与していると知る。ハイデン到着後、2人は市警の前に姿を現し――。', '2024/01/22 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/663fb03e-61ba-4eed-a454-18ad5ada53f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('513b4311-0fca-4714-8763-d3ab78643e6b', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 3, '100173312', '【魔女の戯れ －終幕－】', '魔女に尾けられていたことを知ったギドとアシャフは、ヘインスに心当たりがないか尋ねる。魔女は自分の親しい人間ばかりを狙っている事と、ヘインスが自身の悲しい過去を打ち明ける中、再び魔女から「予告状」が届く。魔女の正体を掴むため、アシャフは策略を立てる。', '2024/01/29 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6acd75d5-96a0-4aa1-b9ea-441f063a5901.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2b015e6-77d1-4c5e-9a82-964afd0c16ed', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 4, '100174112', '【美と死 －序幕－】', '魔響教団随一の死霊魔術師であるファノーラと助手のヨハンは、アシャフの紹介により死屍人事件に派遣される。ファノーラは違法に蘇生された「野良」の数を把握するため、死屍人を呼び寄せると、予想以上に大量の死屍人が姿を現す――。', '2024/02/05 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e087739d-b4a6-4fca-808a-c30c4d54665b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54c3cd51-5876-4b66-975c-994e6f0480fc', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 5, '100175019', '【美と死 －終幕－】', '屋敷の中に招かれたファノーラ達は、死霊魔術師と対面する。死霊魔術師は過去に大事な人を亡くし、その練習台として死屍人を生み出していた。身勝手な発言に怒りを爆発させたファノーラは、自身の能力を開放。戦いが始まる…!!', '2024/02/12 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/123bbf51-db96-4610-b92e-999c1f0dfe63.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2cca2a7-c721-4f94-b2c1-ede5ee4186c7', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 6, '100175453', '【魔女と魔剣 －序幕－】', '舞台は第四大陸から第三陸へ。世界聖教会教団の聖都に近い大陸のため、今回の事件は魔女狩りのエキスパート「聖騎士団」が障害になるとアシャフは予想する。ギドとアシャフは街の潜入に成功すると、そこには聖騎士団に襲われる魔女ヘルガの姿が……。', '2024/02/19 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/552c98a1-d34b-4bf9-8116-a7785890c806.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4815e3ba-56bd-4dd4-b677-11611d052d1f', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 7, '100176656', '【魔女と魔剣 －第二幕－】', 'ヘルガは戦いの最中魔剣を手放してしまい、クーガの手元に渡る。魔剣を奪還しようとするギドだったが、クーガの精霊魔術によってヘルガと供に拘束されてしまう。そんな中アシャフは一連の事件の真犯人について、クーガに接触を試みるが――。', '2024/03/04 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca4b614e-cd9e-4c48-b06d-6c390cfca750.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eae23601-9246-418e-90ff-c5b1a1a05fb7', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 8, '100177422', '【魔女と魔剣 －第三幕－】', 'ギドは魔剣を持って聖騎士団から逃げ出すと、満身創痍になったアシャフとクーガを発見する。その直後処刑人と禁具によって洗脳操作された騎士団が現れ、その中にはヘルガの姿も。魔剣を守るべくアシャフ達は抵抗し、ギドにヘルガを連れて逃げろというが……。', '2024/03/11 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/865b591a-49cd-4a8f-b68e-da56a56a064c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c38c34a8-40fd-4fc9-8af8-7142ab418d3d', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 9, '100178294', '【魔女と魔剣 －終幕－】', '封印から解き放たれた魔剣アシュガン。その強大な力に対抗すべく、ギドはヘルガとの接触によって本体を取り戻す。そこにクーガも応戦しようとするが、大聖霊は魔剣以上にギドを警戒していて…。2つの「世界を滅ぼす力」がぶつかり、遂に決着!!', '2024/03/18 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d03ba0b-2836-4c76-b12e-ba9a35d0bb3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6348a060-c4a4-4ec5-89e1-987286aa65f5', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 10, '100178651', '【起源の魔女】', 'アシャフがヘルガを教団へ送り届ける一方、待機していたギドは、町の子供たちとともに魔女がいるとおぼしき家を訪ねる。魔女ではないと分かり肩透かしをくらったギドだったが、直後、処刑人に襲われる。そして、そこにギドの宿怨の魔女も現われて……!!', '2024/03/25 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8009294b-10e4-47eb-b416-d6ab2d952271.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4446aa1b-4271-4157-a3b3-222a01949d29', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 11, '100179433', '【雄弁と沈黙 －序幕－】', 'アシャフはギドとの出会いを思い出す。3年前、第五大陸のとある村に魔女を保護すべくやってきたアシャフ。偶然に魔女ハルベルを見つけたものの、突如、棺を担いだギドに襲われる。さらに、アシャフたちは奇怪な事件に巻き込まれ……。', '2024/04/01 02:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/03e90bb2-96e4-49fe-86d0-6effc4da54ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e9c7fc6-1257-4861-9f88-1d33f6fd53a4', '3b8058ce-17bc-4a33-aeb6-03bc8ee5c29f', 12, '100180357', '【雄弁と沈黙 －終幕－】', '【最終話】アシャフはギドに魔女を守ることと引き換えに、呪いを解く方法を教える。事件の首謀者である処刑人は、村人をたきつけ、魔女の力を奪うべくハルベルを捕らえる。追い詰められたギドは、ハルベルとのキスで本来の姿に戻る……!!', '2024/04/08 02:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c40389c7-b53e-4f88-b8c5-48248672e8d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('d0983b75-27c9-43b3-94af-e0119d2d84ae', '魔女の旅々', '', 'hulu', 'wandering-witch-the-journey-of-elaina', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8459f483-1b47-4a7a-8dca-b2adb9a3b99e.jpg?w=331&h=447&p=t', 'hulu', 2020, 3, 1, 'FINISHED', NULL, 112609, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a35b7cdd-63b5-4dbd-867e-2291a5407739', 'd0983b75-27c9-43b3-94af-e0119d2d84ae', 'hulu-wandering-witch-the-journey-of-elaina-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50aecc02-72f5-4356-848f-4765f8adaba9.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('606bc642-d3ef-4438-8329-ae4079863ab8', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 1, '100065993', '魔女見習いイレイナ', 'イレイナは『ニケの冒険譚』を読み、魔女になって旅をする夢を抱く。試験に合格し、あとは他の魔女に弟子入りして一人前になるだけなのに、どの魔女からも門前払い。遂に怪しげな「星屑の魔女」に弟子入りを頼むことにする。', '2020/10/05 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50aecc02-72f5-4356-848f-4765f8adaba9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9cb23e72-a415-46e1-baf2-439f6bc90a2e', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 2, '100066641', '魔法使いの国', '魔法使いの国を訪れたイレイナは、入国早々ほうきに乗って猛スピードで突っ込んできた少女と正面衝突し、散々な1日を送ることに。少女･サヤはイレイナに、魔女見習い試験の極意を教えてほしいと頼み込む。', '2020/10/12 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/abad2bbc-0339-47be-8d5b-2ade6bf1d2b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7734b38-9bbe-47a6-9ba7-ffc500133126', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 3, '100066869', '花のように可憐な彼女／瓶詰めの幸せ', '旅の途中で美しい花畑に降り立ったイレイナは、そこにいた少女から花束を預かる。花が美しいと思われることが大事で、誰でもいいから渡してほしいという不思議なお願いと一緒に。イレイナは近くの国へと向かうが……。', '2020/10/19 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/33dfc113-2e36-494b-885b-97a14f5b3218.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('070e1dd0-5e18-485a-b19d-d95641a3d9e6', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 4, '100067318', '民なき国の王女', '滅びた国に辿り着いたイレイナは、唯一破壊を免れていた王城で美しい女性に出会う。正体は記憶を失ったこの国の王女であり魔女･ミラロゼ。彼女と国を滅ぼした巨大な化け物との闘いをイレイナは見届けることになる。', '2020/10/26 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/78c00520-6e5e-4508-b59b-873b630bb801.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('27296c59-32da-4186-b396-3743c14849be', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 5, '100067585', '王立セレステリア', 'イレイナはとある本を片手に、半年前に訪れた魔法使いが活躍する国を思い出す。街中で突然魔法学校の生徒に同行を求められ、拒否したイレイナ。壮絶な追いかけっこの末に待っていたのはなんと師匠･フランだった。', '2020/11/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9abb84e1-2cc5-477a-8815-1d089d5541e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('537ebc6c-0591-4b75-8955-6cfb782f3be8', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 6, '100068551', '正直者の国', '正直者の国――そこは国王が持つ不思議な剣の力で、嘘がつけなくなる国。一見普通だが、住民は静かで、殺伐とした空気が漂う街に疑問を抱いたイレイナは、嘘をつくための法則性を調べることに。そこでひとりの魔女と再会する。', '2020/11/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d26b7975-4aeb-44e6-aa10-053b50341198.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8045f713-5e4a-486b-8d28-76d593d9a97a', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 7, '100068838', '旅人が刻む壁／ぶどう踏みの少女', '『ニケの冒険譚』に綴られた、壁で分断された仲の悪い2つの国。ある日役人が旅人のニケに、壁のこちら側がいかに素晴らしいかを自慢したいと相談すると、ニケはおもむろに壁に賞賛の文字を掘り始める。', '2020/11/16 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/637a3a40-2eae-4111-85c1-117c38c73305.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d3fbfcd-bf42-4015-8535-f4dc4103d3b9', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 8, '100069492', '切り裂き魔', '人形であふれた国で、イレイナは魔法統括協会の魔女が切り裂き魔事件の聞き込み調査をしているところに遭遇する。首を突っ込むつもりのなかったイレイナだったが、なんと自分自身が次の被害者になってしまう。', '2020/11/23 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/76cbbb39-8a2b-490f-88bd-b482a40130ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ad5fea2-61ed-47b1-ae04-1a46fedb3622', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 9, '100070047', '遡る嘆き', '金欠のイレイナは、お金儲けの甘言に釣られて「薫衣の魔女」エステルに会う。彼女は親友の不幸な結末を変えるため、魔法で過去に戻ろうとしていた。2人は10年前の街で、悲劇の始まりとなる事件を阻止しようと奔走する。', '2020/11/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/785ea8b5-df1a-4f43-9571-3d9574356ee6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c73da976-4585-4e8e-a70a-52dbfbd11cbf', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 10, '100070908', '二人の師匠', '揃って休暇をとり旅行に出かけるフランとシーラ。フランは師匠がもうひとり弟子をとりたいといった日のこと、そして犬猿の仲だったシーラと過ごした弟子時代に想いを馳せる。それは、魔法統括協会からのある高額報酬依頼……。', '2020/12/07 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a318800-8664-4dda-b8b2-9b01dea1f07a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b81698d-f25f-4331-bf45-1256f56aaf80', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 11, '100071571', '二人の弟子', 'クノーツの街を訪れたイレイナは、魔法使いを嫌悪する強盗集団「骨董堂」復活の報を耳にして正体を隠す。いっぽうサヤは謎の小箱を届ける仕事の途中で妹に再会する。そんなときイレイナとサヤの体に異変が……?', '2020/12/14 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/328b0950-f42f-423a-929e-c7dab3d46d1d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c804f420-2667-4cdb-bcbf-c131dfb6f031', 'a35b7cdd-63b5-4dbd-867e-2291a5407739', 12, '100071925', 'ありとあらゆるありふれた灰の魔女の物語', '【シーズン1 最終話】「あなたの願いを叶える国」と書かれた門を潜ったイレイナは、見知った城の中で眼鏡をかけたもうひとりの自分に出会う。そこには性格が異なる何人ものイレイナが存在した。イレイナの願いとはいったい何なのか?', '2020/12/21 00:00:00', 1441, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8ce1ebf9-0cc1-45f3-b0fe-ee8c0d3f59cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('4b556193-241a-4217-ba37-d82e3fb9d32a', '魔神創造伝ワタル', '', 'hulu', 'mashin-souzouden-wataru', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0bb5a69e-5d49-44fb-a6bf-7972ee2dacf4.jpg?w=331&h=447&p=t', 'hulu', 2025, 0, 1, 'FINISHED', NULL, 173333, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2cc3f7c3-9838-4087-adb7-125698c7e037', '4b556193-241a-4217-ba37-d82e3fb9d32a', 'hulu-mashin-souzouden-wataru-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07ef66ec-e78e-4d69-8f43-1ed9a33d9928.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c37dcf69-ff56-4ce8-aa8a-589af5b16f9b', '2cc3f7c3-9838-4087-adb7-125698c7e037', 1, '100212406', '【救世主はRyuTuber】星部ワタルがふってきた!', '小学4年生の「星部ワタル」は、スーパースターを目指すリューチューバー。ある日、イトコの「天部カケル」と動画配信の準備をしていると、何者かに名前を呼ばれ、異世界「宙部界」に迷いこんでしまう。そこで出会ったのは、剣豪の「御富良院」と人気Vtuberの「マロ」。二人はワタルのことを宙部界を救う救世主として歓迎する。そんな中、「爺チャンネル」というとんでもないヤツが人々を困らせているという話を聞き、ワタルたちは「チャンネル登録お願い島」へ向かうことになる。', '2025/01/12 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/07ef66ec-e78e-4d69-8f43-1ed9a33d9928.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('12d0a758-d456-4d15-900c-d69d67d30b8e', '2cc3f7c3-9838-4087-adb7-125698c7e037', 2, '100213332', '【風神丸見参】おでこがピンチの御富良院!', '魔神「龍神丸」と共に敵を倒してゴキゲンなワタル。だが、敵はまだまだたくさんいて、ラスボスの「エンジョーダ」を倒さなければならないことを知る。そんなワタルたちの冒険の案内役として、龍神の使い「リュンリュン」が現れる。リュンリュンに連れられて新しいエリアに向かうと、そこでは「おわり親方」が好き勝手に暴れていた……。', '2025/01/19 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c16fc6d2-4e57-4672-aeee-6c84831dfb67.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('391e59ae-fce5-415d-b7b4-ff408811cb40', '2cc3f7c3-9838-4087-adb7-125698c7e037', 3, '100214290', '【大暴露】マロの謎をさぐれ!', '宙部界へ来たときに、はなればなれになってしまったカケルのことを心配するワタル。一方、御富良院はマロの正体が何者なのか気になり、ワタルも人気Vtuberのマロがなぜ宙部界にいるのか疑問に思う。もしかしてマロはエンジョーダのスパイ!?  そこに、週刊くつろぎの記者を名乗る「増行暴露宇」が現れ、マロの秘密を暴露しはじめる!', '2025/01/26 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4a2fcbd3-afff-48f0-9c21-ec6cf783f958.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('102ce08e-6b7b-46b0-a976-91316424643d', '2cc3f7c3-9838-4087-adb7-125698c7e037', 4, '100214805', '【ドッキリ】カケルとの再会!?', 'エンジョーダを倒せるという「大いなる神の力」を手に入れるため、ワタルは7つのお宝「セブンブロック」を探し始める。そんなとき、カケルとバッタリ再会! カケルも自分を助けてくれた「ショウ」と「マイガー」に恩返しをするため、セブンブロックを探していた。ワタルとカケルは、どっちが早くセブンブロックを手に入れるか競争しようと宣言する。そこに、人々にドッキリを仕掛けまくっている「ドッキリマン」が現れる。', '2025/02/02 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff9fbc81-048e-4781-8e48-e550724b18fa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6dd125b8-b1e3-441a-92a5-1237b074de76', '2cc3f7c3-9838-4087-adb7-125698c7e037', 5, '100216179', '【秒で最終回】エンジョーダのアジトに参上だ!', '最初のセブンブロックはカケルにとられてしまった。くやしがるワタルは、セブンブロックを集めるよりも「直接エンジョーダを倒せばいんじゃね?」、ということに気づく。ちょうどそのとき「有限会社エンジョーダ」の定時社員総会のお知らせを発見! さっそく会場に潜入してみると、そこでは「厚目ニク」を筆頭に「ブロッキン」たちが宙部界を炎上させようと団結していた。', '2025/02/09 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/231a5c12-d3b3-4173-a7e0-722bedc34575.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4caa51a7-6b05-452b-a3e3-8515a9682996', '2cc3f7c3-9838-4087-adb7-125698c7e037', 6, '100217048', '【緊急謝罪】リュンリュンの黒歴史!?', '朝からワタルたちの世話で大忙しのリュンリュン。地図をながめていたワタルは、近くにセブンブロックの反応があることに気づくが、なぜかリュンリュンの様子がおかしく、道案内もあてにならない。ようやく目的地の村にたどり着くと、村人たちはリュンリュンを見て逃げ出してしまう。戸惑うワタルたちのもとへリュンリュンにそっくりな「ホンホン」が現れた!', '2025/02/16 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe0c00e6-b85f-4b31-9ab6-b24504d0beca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a11c49a4-e44f-4089-bffc-dc431cc6dad5', '2cc3f7c3-9838-4087-adb7-125698c7e037', 7, '100218308', '【サバイバル】カケルたちはどう生きるか', 'ようやく1個目のセブンブロックを手に入れたワタル一行は、ある町で1000組目のお客さまとして盛大なおもてなしを受ける。そのころ、カケル一行は竹林で迷子になっていた。そこへ「サバイ･バル」という名の男が、崖から落ちてくる。同じく迷子になっていたサバイからサバイバルのルールを学びながら、カケルはショウ、マイガーとともに過酷なサバイバル生活を送ることになる。', '2025/02/23 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5cb24ba4-3b33-4683-80d6-c2854308ee9a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('faabdf3c-ad9c-418b-8dce-e2de81c58bea', '2cc3f7c3-9838-4087-adb7-125698c7e037', 8, '100218922', '【閲覧注意】幽霊屋敷へレッツゴー!', '久しぶりに再会したワタルとカケル。これまでに手に入れたセブンブロックの数は、ワタルが1個で、カケルが3個とカケルがややリード。次の勝負に意気込む二人だが、目的地である「アヤカシの里」のおばあさんから助けを求められる。どうやら「占部霊子」という髪の長い女性に、自分の家を事故物件にされてしまったらしい。たどり着いたアヤカシの里は不気味な雰囲気に包まれていた……。', '2025/03/02 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1be3a18b-d336-4cfc-844d-86ab50835c15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9519d526-9cac-458a-8530-93651db03533', '2cc3f7c3-9838-4087-adb7-125698c7e037', 9, '100220110', '【切り抜き】御富良院が裏切り者すぎた!', 'カケルを宙部界で捕らえた人物は、御富良院の顔をしていた。そのことを思い出したカケルはすぐにワタルに伝えるが、なぜカケルが御富良院を疑うのかワタルにはわからない。そこへ「キリー&ヌッキー」兄弟が現れる。彼らは御富良院がエンジョーダの手下だと証明する「切り抜き動画」を見せてきた!', '2025/03/09 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cfbce199-077f-442c-a8a4-d5b862c85624.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1b2fc50b-f27c-4a80-8b91-0354ac0e0686', '2cc3f7c3-9838-4087-adb7-125698c7e037', 10, '100220782', '【永久保存版】ウソを見破る100の方法!?', 'ワタルに「御富良院は敵だ」と伝えても、相手にされず落ちこむカケル。そんなカケルにショウとマイガーは、人の嘘を見破ることができるウッソリストの「Mr.ライアー」を紹介する。カケルはさっそく御富良院と引き合わせるが、御富良院は自信に満ちた表情で「エンジョーダの手下ではない」と言い張る。Mr.ライアーはなんとしても嘘を認めさせようと、強引な手段に出る……!', '2025/03/16 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf2649f9-be12-4280-8a98-e9b300e9fb94.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e692110-b57b-48c5-97c8-c21de4a49ae7', '2cc3f7c3-9838-4087-adb7-125698c7e037', 11, '100221791', '【ガチ裏切り】どうするカケル!', '手に入れたセブンブロックの数は、ワタルが3個でカケルが4個。7個そろえるために、なんとか相手の分を手に入れようと、勝負することに!? その一方で、カケルはショウとマイガーがエンジョーダの手下だと気づき、悩んでいた。だが、友達だと信じている二人のためにセブンブロックを奪おうと、カケルは魔神対決でワタルに挑む!', '2025/03/23 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ccdac600-9098-46ea-97c5-c4d4bfd0bdfe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('545f62b8-0815-4ce2-b396-797ff8e05a69', '2cc3f7c3-9838-4087-adb7-125698c7e037', 12, '100222466', '【必見レシピ】大いなる神の力を手に入れろ!', '7個のセブンブロックがそろい、カケルもワタルと共にエンジョーダを倒すと決めた。マロに案内されたキッチンで「大いなる神の力」を手に入れるための儀式をおこなうと、セブンブロックが突然喋りだし、驚くワタル一行。そこへショウとマイガーがセブンブロックを奪いに攻撃を仕掛けてくる。絶体絶命のピンチのなか、龍神丸はワタルに、セブンブロックに何を願うのか問いかける……。', '2025/03/30 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e7e53a2-fa01-4c6b-a1ba-825057d9daf3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('da0cc0db-ba0c-4d94-a7e6-3b3d645806f2', '2cc3f7c3-9838-4087-adb7-125698c7e037', 13, '100223000', '【魔神改造】分解したら直らなくなった件www', 'ショウたちとの戦いで壊れてしまった麒麟丸を直そうとするカケル。龍神丸は「すべては心のままに」とアドバイスして消えるが、カケルは具体的にどうすればいいのかわからない。パーツをバラバラにして組み直すのにも失敗したカケルに、ワタルは「新しく創っちゃばいいんじゃね?」と語る。その言葉でカケルは、新しい魔神を自由に創ってみようと決意する!', '2025/04/06 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a73a1fd-c758-47e1-9d18-ce1e07a2ef90.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea66b267-2440-431f-b242-53a443dcec58', '2cc3f7c3-9838-4087-adb7-125698c7e037', 14, '100223844', '【マロ流ハウツー】これでキミも人気RyuTuber!', 'エンジョーダの手下「御羅院」が現れ、倒すべき相手を認識したワタルとカケル。だが、今は動画を撮りたい気持ちが大爆発! 二人はマロからリューチューブのハウツーを学ぶ。そこへリューチューバーの「赤ペンコーシ」が現れる。ワタルたちは赤ペンコーシからリューチューブで一番必要なもの「オモシロソウ!!!」を教わり、リューチューブ魂を全開させる。', '2025/04/13 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f399096c-8b4e-4c48-8328-2d5ef4bec28d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a3ac9ba-d98b-4a2d-9bad-d9b982bbc3c3', '2cc3f7c3-9838-4087-adb7-125698c7e037', 15, '100224485', '【ものまねメイク】マロがマロでマロはマロロン', '御羅院のサウナ監獄でパワーアップしたショウとマイガー。二人はワタルたちからウズメを奪うため、メイクの達人「MANEKO」を呼んでいた。MANEKOは超絶メイクでマロに変身! マロが二人になって驚いたワタルたちは、本物のマロを当てる企画で動画を撮る。だが、どちらが本物なのか全く見分けがつかなくなり……!?', '2025/04/20 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/587981ff-621a-4a3b-bd71-0840aa814271.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e019de6e-200e-4fd7-9dba-cd68e560145b', '2cc3f7c3-9838-4087-adb7-125698c7e037', 16, '100225441', '【効き目抜群】みんなでワンツー! 最強筋トレ!', '龍王丸や皇龍丸のようにパワーアップするため、御富良院は風神丸を鍛えたいと感じるようになっていた。そんなとき、新エリアでジムを発見! オーナーの「マッスマイル健児」に乗せられて、ワタルたちはマッスマイル体操にはげむ。気がつけば御富良院の体は、風神丸と同じくらいの巨大サイズに……。だがすべてはエンジョーダの手下であるマッスマイル健児の罠だった!', '2025/04/27 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9993642-c8ab-4e34-8a20-57ef41f675e9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3fdb9ef-2efc-44e6-8674-6567a6710f62', '2cc3f7c3-9838-4087-adb7-125698c7e037', 17, '100225982', '【地獄】ドッキドキ!? ワナだらけの罰ゲーム大会!', 'にぎやかな町へやってきたワタル一行を、ショウとマイガーが待ち受けていた。だが、カケルと戦いたくない本音がバレバレの二人。ワタルたちはなぜか町の人から罰ゲームを仕掛けられてしまうが、ここはあらゆる罰ゲームが襲いかかる「罰ゲー村」だった!', '2025/05/04 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad29dd25-0234-475d-82f3-cd2902db52be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3fa82e6b-add2-4a96-914c-f245bea545d0', '2cc3f7c3-9838-4087-adb7-125698c7e037', 18, '100226724', '【神回】世界のヒミツを教えます!', '宙部界の秘密を教えてくれる場所としてマロが案内したのは、なんとエンジョーダの本拠地! 潜入したワタルたちが池に飛びこむと、その先の異空間にあったのは神様が暮らす宙部大社だった。神様の使いであるホンホン、ゲンゲン、ビャクビャクの案内で奥の社へ進むと、そこにいたのは宙部界トップの神々「神7」だった。', '2025/05/11 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/99932feb-647a-47cc-aea9-310c22e96c26.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1121619-0fad-4bda-a254-0e7037802ffb', '2cc3f7c3-9838-4087-adb7-125698c7e037', 19, '100227184', '【ざっくり解説】御富良院のできるまでとか', '御富良院と御羅院は元々ひとりの人間だった。その名は「熱良院」。彼は神7の世話をするために作られた存在で、とても働き者だった。だが、やがて宙部界の人間たちの怒りや妬みの感情から「ベイビーエンジョーダ」が生まれ、神の力を羨む気持ちが芽生えた熱良院が狙われることになる。', '2025/05/18 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/912b655b-845a-4dd8-819c-76db0ff6dacb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('78aa9bcc-1617-4402-9fd9-a5d1b586cee3', '2cc3f7c3-9838-4087-adb7-125698c7e037', 20, '100227828', '【漢の男気バトル】オトコとオトコのオトコ勝負!', 'エンジョーダの天守閣へ突入したワタルたちの前に現れたのは御羅院だった。そこで魔神バトルをくり広げ、カケルは御羅院に加勢するショウとマイガーを説得しようとする。一方、御富良院と御羅院は1対1で勝負するがなかなか決着がつかない。御羅院はかつて自分が熱良院だったときの不満を、御富良院にぶつけるが……。', '2025/05/25 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/54b999cb-21c8-4ead-bbe6-798a85335b55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45d4e01d-5fc4-43f7-ab9d-83290bc21f27', '2cc3f7c3-9838-4087-adb7-125698c7e037', 21, '100228309', '【感動の再会!? 】スサノオをさがせ!', '御羅院はエンジョーダに取りこまれ、雷神丸も「炎上丸」へと姿を変える。エンジョーダは人間たちの炎上エネルギーを集めた「炎上玉」で、宙部界を焼きつくそうとしていた。ワタルたちは宙部大社に逃げこむが、炎上丸の攻撃でセブンブロックが欠けてしまう。直すには神7の力が必要で、そのひとり･スサノオは行方不明だったが、彼は意外なところにいた……。', '2025/06/01 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ecd13a3-a4c0-475a-a806-a931c9d65671.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6598eb3b-44f2-4359-823a-07d57228a279', '2cc3f7c3-9838-4087-adb7-125698c7e037', 22, '100229049', '【ガチ勝負】ぜんぶ当てなきゃ帰れま7!', 'エンジョーダはマロを連れ去り、炎上玉と共にワタルたちの世界へ向かった。追いかけようとするワタルに、スサノオは「ぜんぶ当てなきゃ帰れま7」に挑戦すれば、ふたつの世界をつなぐゲートが出現すると語る。進行役の「継音ユキ」によると、何かのランキングを当てるようだが、そこに現れたのは、これまでに戦ってきたエンジョーダの手下たちだった!', '2025/06/08 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bebe5e64-24d0-401d-8801-9d8ff091c778.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df4c215e-fa1b-4308-82ff-d633b67324cb', '2cc3f7c3-9838-4087-adb7-125698c7e037', 23, '100229503', '【悲報】燃える世界と突然のわかれ', 'これまでの冒険をマロが配信していたため、人気リューチューバーになっていたワタルとカケル。だが、二人を批判する「悪マロチャンネル」がアンチの炎上コメントを集め、それが炎上玉を巨大化させていた。龍王丸たちが炎上丸に苦戦することで、さらに増えていく炎上コメント。エンジョーダの狙いは、マロの力を利用して、より巨大な「炎上太陽」を生み出すことだった!', '2025/06/15 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26f54efa-38e1-49a8-a20c-f4f113c99dc7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('496ab791-9a66-4dc3-ac0e-e5ace016ae27', '2cc3f7c3-9838-4087-adb7-125698c7e037', 24, '100230437', '【二人は救世主】創れ! オレたちの輝く未来!', '【最終話】龍神丸と皇龍丸が融合し、神龍王丸が誕生した! ワタルとカケルは力を合わせて、再びエンジョーダに立ち向かう。だが、ついに炎上太陽が完成し、宇宙に向けて打ち上がってしまう。それを止めるためにワタルが思いついた秘策とは…? はたして、ワタルとカケル二人の救世主はエンジョーダを倒し、人々の笑顔を取り戻すことができるのか!?', '2025/06/22 18:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c50bdbbe-fe9a-4e72-a372-dc69767a4d0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('393aee7a-ad87-47f3-807b-d804c4ef490e', '魔人探偵 脳噛ネウロ', '', 'hulu', 'neuro-supernatural-detective', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e9a31a5c-73f8-4381-9e99-b43df3c783b4.png?w=331&h=447&p=t', 'hulu', 2007, 3, 1, 'FINISHED', NULL, 2985, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a47c75aa-2c7c-455f-82f7-3308d204a6c9', '魔弾の王と戦姫 (ヴァナディース)', '', 'hulu', 'lord-marksman-and-vanadis', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f016ffa3-5541-493e-b77d-49cd0994841d.jpg?w=331&h=447&p=t', 'hulu', 2014, 3, 1, 'FINISHED', NULL, 20809, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 'a47c75aa-2c7c-455f-82f7-3308d204a6c9', 'hulu-lord-marksman-and-vanadis-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5251fcdb-c49b-46b4-87d7-a42de1cd4e11.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('32c966a8-8d92-4be0-b2eb-70e3c862284d', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 1, '100084277', '戦場の風姫', 'ブリューヌ王国の若き伯爵ティグルは、ジスタート王国との戦へと駆り出されるが、瞬く間に蹂躙されてしまう。戦場で彼が出会ったのは、ジスタートの七戦姫の一人、“銀閃の風姫 (シルヴフラウ)”ことエレンだった。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5251fcdb-c49b-46b4-87d7-a42de1cd4e11.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f80cdaf2-5683-43fe-af66-fd1261c781a7', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 2, '100084278', '帰還', 'エレンの捕虜となったティグルは、老臣バートランと再会し、テナルディエ公爵の軍が故郷アルサスに侵攻を開始したという事実を知る。急ぎ故郷へと帰還しようとするティグルだったが、その前にエレンが立ちはだかる。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aee8fbe0-97c3-4bb9-b6c5-51e383014c4f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fd9838a-8835-46c1-8959-a9c99bd2c365', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 3, '100084279', '甦る魔弾', 'テナルディエの息子ザイアンは、予期せぬティグルたちの反撃を受け、モルザイム平原にまで敗走した。劣勢を跳ねのけて進軍するティグルたちだったが、その勢いを止めたのはザイアンが操る地竜だった。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91d236f3-beb2-4e1f-80fd-2daac911f592.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59696657-5c36-4d3b-8397-9afa85673790', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 4, '100084280', '凍漣の雪姫 (ミーチェリア)', 'アルサスの地に、つかの間の平穏が訪れた。エレンはジスタート国王に申し開きをするために、王都へと赴く。謁見を終え、安堵したエレンだったが、予期せず天敵、“凍漣の雪姫 (ミーチェリア)”ことミラと再会する。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af92b343-b6ae-4b0b-a411-b328689f51ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c7d7995f-b29e-48e7-a688-e79061c79d17', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 5, '100084281', 'タトラ山攻略戦', 'ミラはタトラ山の城砦で鉄壁の防御を築くが、ティグルは突破口を探しタトラ山へと潜入。山中で食糧を確保しようとするが、同じ獲物を狙う者がいた。目の前にいたのは、あろうことか敵軍の戦姫であるミラであった。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b221bb90-52cb-4a09-a47b-b23e1bf1fe00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2dc1655d-8ecc-431a-9066-292215b41993', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 6, '100084282', '黒騎士', 'エレンとミラの竜技を駆使した戦いを、ティグルたちはただ見守るしかない。暴風と氷塊が吹き荒れる中、暗殺者･セラシュが飛び出し、ミラの命をも狙おうとするが、ティグルの放った弓がその行動を阻止するのだった。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9e22ab2-4c89-4b52-8b13-70e4a8bd6114.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b4120da-b302-4c15-8bda-a34fa45a6fc9', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 7, '100084283', '守るために', '黒騎士ロランからエレンを守るため、重傷を負ってしまったティグル。銀の流星軍は撤退を余儀なくされ、エレンはやむなく、「人間に竜技を使う」という戦姫にとっての暗黙の掟を破ろうとしていた。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82646b2d-910c-45ac-b978-46b0e2bfc7ae.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2c2b9106-6c7c-41e1-a4c2-c07c9ee1f2a9', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 8, '100084284', '二千対二万', '親友の危機を救うため、銀の流星軍から一時的に離脱したエレンたち。ティグルは残った兵を率い、ムオジネル軍の侵攻を阻止するために南へ向かったが、その戦力差は約10倍。戦いの行方は火を見るより明らかだった。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/73f6458e-875a-492f-a069-1dbeffd41965.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2ad4e3f-70ae-407d-88d0-8548c21560af', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 9, '100084285', '雷渦と煌炎', 'レグニーツァへ向かったエレンは、病床の親友サーシャとの再会を果たす。サーシャから語られたのは、同じ戦姫である“雷渦の閃姫 (イースグリーフ)”ことエリザヴェータによるレグニーツァへの侵攻だった。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee944288-4ff5-40e8-9af3-742c5d90d2f1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e15bd998-38c1-43d4-b875-31766d6b11c0', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 10, '100084286', 'オルメア会戦', '銀の流星軍+オルミュッツ連合軍と、ムネオジル軍との戦いが幕を開けた。劣勢ながら最後まで戦い抜くことを誓ったティグルとミラの前に、新たな軍勢が出現する。彼らが掲げていたのはブリューヌ王国の軍旗であった。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97cbeebb-3fcf-49eb-a668-efd64d814a55.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('573c0c12-d66f-4a4d-91ff-51de5c9a88fb', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 11, '100084287', '戦姫二人', 'ムオジネル軍との戦いに勝利した銀の流星軍はペルシュ城砦に滞在していた。エレンも合流し、つかの間の休息に安堵するティグルたち。だがレギンのある告白により、急きょルテティアの都市アルテシウムへと出立する。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9f0f354f-398e-44f7-8066-0bf2aafdd7a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('405c4b10-ccbd-4eb2-ac9c-7361db4180f2', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 12, '100084288', '聖窟宮 (サングロエル)', 'ティグルたちは、当初の予定どおり“シャルルの聖窟宮”へと向かった。聖窟宮は、かつて建国王シャルルが王となる天啓を受けた地。ところが宮内では、すでにテナルディエが待ち構えていた。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fcbc88fa-7c03-4c78-8ca6-ef64714d65af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31976f52-e663-44ea-a1c7-7a5c39949d16', 'f7163b32-4e15-4a03-ba6e-2fb6d43fddb5', 13, '100084289', '広がる世界', '【シーズン1 最終話】失意のどん底にいるティグルに、エレンは戦いを放棄することも1つの手段だと語りかける。それでも戦士の誇りは持ち続けるというエレンに、ティグルは自分にも意地があることを思い出し、心を奮い立たせるのだった。', '2021/07/08 00:00:00', 1428, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c1f73a3f-c11b-4700-a8f1-b840d69c497a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ad62ec1b-7bc9-460a-a800-2538fd2bdfa2', '魔都精兵のスレイブ', '', 'hulu', 'chained-soldier', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fa4d0342-5d2d-4e45-a8ee-625bf16e7de5.png?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 141821, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('8c381ccb-86b9-4d9b-b176-774ad4aba452', 'ad62ec1b-7bc9-460a-a800-2538fd2bdfa2', 'hulu-chained-soldier-s1', '魔都精兵のスレイブ1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/120804fd-2986-4d86-be56-330e5309283c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d66bab68-0cac-4916-b0b9-89e5df506400', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 1, '100170449', '誕生、優希、目醒める', '異空間「魔都」に通じる門「クナド」が各地に発生した日本。魔都には人間を襲う「醜鬼」と女性のみ特異な能力を与える「桃」が存在していた。ある日、和倉優希は、突如として出現した門により魔都に迷い込んでしまう。そこで、魔都の脅威に対抗するための組織「魔防隊」の七番組組長、羽前京香と出逢う。他者を奴隷にする「無窮の鎖 (スレイブ)」の能力で、優希を強化することにより窮地を脱した二人。その能力の代償として優希はご褒美をもらえることになり……', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/120804fd-2986-4d86-be56-330e5309283c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55b34a24-c954-430c-b566-dead51c0cb02', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 2, '100170857', '興味、朱々、肌蹴る', '優希は魔都にある七番組寮の管理人として働くことに。日々、家事をして過ごすなか、駿河朱々に弱みを握られ奴隷にされてしまう優希。ある日、優希と朱々二人きりの時に巨大醜鬼が寮を襲撃する。朱々は身体の大きさを変化させる能力「玉体革命 (パラダイムシフト)」で応戦するも、徐々に押され始めていく。朱々を助けるために京香不在のなか、何とか変身しようとする優希。果たして優希は朱々を助けることができるのか!?', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aa51b8ad-bfdc-4e42-a42e-02b2a203aef2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8efc4a02-c31f-4961-8ea0-aa72ff3140e4', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 3, '100171257', '遭遇、京香、猛る', '魔都のクレーターに大量の醜鬼達が集まっているという報告を受けた七番組は壊滅作戦を実行し、スレイブ状態の優希と共に順調に醜鬼を減らしていた。そこに突如、京香の故郷を滅ぼした醜鬼「一本角」とそれを従える人型醜鬼が乱入し、日万凛と朱々が負傷してしまう。優希は人型醜鬼に襲われるがそこに姉の面影を感じ取り、人型醜鬼も優希を見るなり動揺し撤退する。残った醜鬼達を掃討し、寮に帰った優希は姉に似た醜鬼や強力な一本角と新たな問題に直面することになる。', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3fd37726-bf35-4fa9-a019-588455bc661a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a744d04-6b44-445c-b1ea-52154db8bbfa', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 4, '100171600', '旋風、日万凜、吼える', '人型醜鬼に備えるため各組の連携を密にすることにした魔防隊。京香は六番組組長「出雲天花」に戦力把握のため魔都交流戦を提案する。それは、日万凛に何かと絡んでくる六番組副組長「東八千穂」を見返すためでもあった。日万凛は、他人の能力を使用できる能力「青雲の志 (ラーニング)」により、優希をスレイブ化することに。スピード特化に変身した優希は、時を操る能力者の八千穂に勝つために最速の一撃必殺技「烙印破」を編み出すが……。', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/487aca4a-ab3d-4421-af18-58a243392bce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f1b4334-1aa9-4d96-a21c-b77961a89895', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 5, '100172409', '姉妹、八千穂、嘲る', '開幕「烙印破」を受けた八千穂は、「東の辰刻 (ゴールデンアワー)」を使用し、試合開始前に戻る。能力を使用したと見抜いた日万凛は、撹乱させて八千穂の能力を消耗させる作戦に変更する。八千穂に能力を無駄打ちさせ、徐々に追い詰めていく日万凛達だったが、八千穂の秘策によって倒れてしまう。絶体絶命の中、最後に優希が囮になることで勝利することができた日万凛達。そして、優希を認めた日万凛からのご褒美が始まる。', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ff593c2-a68e-4b08-b518-0be6b0c7010a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24e66835-749c-4988-a716-87fa8634bf4d', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 6, '100173291', '強襲、サハラ、煌めく', '魔都交流戦第二回戦は、朱々対若狭サハラの肉弾系のバトルになる。サハラの能力「怒れる羊 (クレイジーシープ)」はあらかじめ定めた分数だけ自身を強化するもので、巨大化した朱々の攻撃は避けられ手痛い反撃を受ける。朱々は奮戦するもサハラの隠しモードにより敗れてしまう。その時、突如人型醜鬼「雷煉」が大量の醜鬼を引き連れ襲撃してくる。優希は、京香と日万凛の同時スレイブ化で「無窮の鎖･戦雲」という新たな形態になり大量の醜鬼を薙ぎ払っていく。', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0a89c6c6-8f79-4348-bab3-a561933a62ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('076d762a-91b9-490d-8424-d7449c28dc2d', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 7, '100174143', '共闘、天花、翔る', '出雲天花は雷煉と対峙し、雷煉の狙いは組長だと知る。天花は空間を操作する能力「天御鳥命 (アメノミトリ)」を使い、大量の醜鬼ごと雷煉を空間の断裂に飲み込んでしまう。醜鬼掃討後、寧が千里眼で見つけた別の人型醜鬼のこともあり、魔都交流戦は中止。後日改めて六番組寮で作戦会議をすることになる。京香が会議をしている間、優希は六番寮管理人の仕事を手伝うことに。会議終了後、京香は天花から人事に関して「奴隷クン私に頂戴」と言われて……。', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/897bc60b-94ec-480f-ab38-8e99fcc596f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1db424c-4e17-427a-82e7-588d161bc98a', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 8, '100174960', '約束、寧、憶う', '天花からの優希の人事異動を拒否した京香はプライベートまでは口出ししないと天花に伝える。天花は早速能力を使い優希の部屋に忍び込み猛アタックをかけるが、朱々に見つかってしまう。早朝訓練の日、京香は他の組員にスレイブ能力の貸出を試みることに。寧は索敵特化、朱々はパワー特化と特性に合わせた変身ができるが、京香の消耗が激しいことが判明する。学校へ行く寧を送ることにした優希は、寧の千里眼能力「きっと見つける (プロミス)」について聞くことに。', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd81381c-0c81-4f8f-84e7-cfc5aacde0f5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e970e32d-2c81-43ed-b37f-ed0370c00ad0', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 9, '100175438', '再会、ココ、舐る', '魔都災害の現場へ向かう優希の前に、姉の面影を持つ人型醜鬼が現れ優希を拉致してしまう。目が覚めた優希は、そこが人型醜鬼達の隠れ里で、優希を拉致した人型醜鬼は優希の姉の「青羽」だったことを知る。人型醜鬼が元は人間だと知った優希は魔防隊への保護を訴えるが、青羽は魔防隊は敵と拒絶する。一方、京香はご褒美を与えるために自動的に優希のもとへ向かう自身をレーダーとして、六番組と共同で救出作戦を決行する。', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/232d27e6-ba9f-415a-b7f8-5f0e92867502.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1ed9357-0875-4491-b5ff-3ff6853bd14c', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 10, '100175891', '開戦、波音、詠う', '人型醜鬼の隠れ里まで辿り着いた京香達。行く手を阻む銭函ココと熊童子には朱々とサハラが、湯野波音とアクラには日万凛と八千穂が対峙し組長たちを先に行かせることに。無事優希の元へ合流できた京香達はそこで、人型醜鬼が元は人間だったことや陰陽寮での人体実験を受けていたという事実を知る。京香は陰陽寮を潰すことを約束するが青羽は陰陽寮を襲い仲間たちを救うと聞かないため力ずくで止めることに。京香達と人型醜鬼達の正面衝突が今始まる!!', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c0865df-cdd5-4f56-aaf6-cd78d47a7de0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c63dba2e-4ac6-486f-8448-168286e725ca', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 11, '100177412', '死闘、青羽、昂る', 'ココと熊童子との戦いはサハラが小さくなった朱々を投げ、熊童子体内から大きくなり撃破、その牙でココも撃退する。湯野波音とアクラとの戦いでは日万凛の新技「フルバースト」で敵をあぶりだし、八千穂のプライムタイムで撃退する。青羽と一本角との戦いは、天花が青羽の隙を作りだすも優希の事が頭をよぎり、攻撃できず反撃を受け倒れてしまう。ココと波音、朱々や日万凛達も合流し、互いににらみ合う面々。そこに突如、醜鬼達を束ねる八雷神と名乗る者たちが現れて……', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7568552f-7d63-4ed9-af1c-c4ac631e5f40.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b30d6e3-d95c-4ca2-84db-c228e46f9f83', '8c381ccb-86b9-4d9b-b176-774ad4aba452', 12, '100177413', '帰還、新たな、決意', '【最終話】八雷神の壌竜はココと波音をさらっていってしまう。紫黒は自身の毒で一本角を強化暴走状態にさせる。仲間達を守るため、そして京香の故郷の仇を討つために二人は力を合わせて一本角を撃破する。陰陽寮を黙認している総組長に対し、京香は自分が総組長になることで非道の行いを正すことを青羽に誓う。それまで青羽はココと波音を助けるために単独で動くことに。優希は青羽を元の人間に戻すという新たな戦う理由を見つける。それぞれの思惑を胸に今日も屈服の時間が始まる!!', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b97e5b0-5759-458e-b2af-a2b190f1d240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('7c9f281d-3d42-46e9-aa57-337b8b659052', 'ad62ec1b-7bc9-460a-a800-2538fd2bdfa2', 'hulu-chained-soldier-s2', '魔都精兵のスレイブ2', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e4ed0bd-1ed8-4028-863b-0880cc23c355.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eab67f3e-6f52-4bc6-88e6-59bee37e70ee', '7c9f281d-3d42-46e9-aa57-337b8b659052', 1, '100249847', '組長会議', '激闘を乗り越えた優希は管理人としての役目を果たしながら、着実な成長を見せる。そんな中、優希は総組長･山城恋の指名により、京香とともに組長会議へ出席することに。組長たちの迫力に圧倒されつつも、挨拶を済ませたその最中、醜鬼の大群が迫っているとの報告が入る――。', '2026/01/12 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e4ed0bd-1ed8-4028-863b-0880cc23c355.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b8aaf49-649f-4d8e-9d7a-0904c6c585d9', '7c9f281d-3d42-46e9-aa57-337b8b659052', 2, '100250165', '恋の影', '組長会議の夜、優希の寝床へ八雷神が忍び込んだことをきっかけに、警戒を強める七番組。優希は寧とのスレイブ形体《煌星》で周囲の探索を行う。しかし、能力を貸出す一部始終を総組長･山城恋に目撃されてしまう…。', '2026/01/19 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3e1285a-ba11-4bd2-a469-db14e5c27f54.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fdd9a2f-fc91-4a5d-a80d-7c2d84511621', '7c9f281d-3d42-46e9-aa57-337b8b659052', 3, '100251430', 'やってきた嵐', '五･六･七番組の合同訓練を通じて、着実に力をつけていく各隊員たち。そんな中、五番組組長･蝦夷夜雲が優希の貸出しを求める。新たな戦力としての可能性を見据え、京香は渋々ながらも、優希を貸し出すことになる。', '2026/01/26 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4c807186-c03f-480e-80f5-eb0905d6f6ed.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c1f0d88e-31e9-4c72-970c-13b28f171b01', '7c9f281d-3d42-46e9-aa57-337b8b659052', 4, '100252126', '暴走', '十番組との合同訓練のため、魔防隊本部へと向かった七番組。総組長･山城恋に呼び出された京香と優希は、2人きりで彼女のもとへ赴くこととなる。その目的は——「優希の貸出し」だった。恋が鎖に触れた瞬間、圧倒的な力に呼応した優希は、新たな形体《殺牙》として禍々しい姿へと変貌する。', '2026/02/02 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8964452-3d53-4194-b545-4eff18336476.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3c3aa426-9cf5-43aa-9d61-f2145eb3f9b6', '7c9f281d-3d42-46e9-aa57-337b8b659052', 5, '100252127', '東の晩餐', '次の東家当主を決める儀式《東の晩餐》。優希たちを伴い、日万凛と八千穂はその会場へと足を踏み入れる。東家が一堂に会する緊迫の場で、日万凛はかつて自分を虐めていた誉に絡まれる。しかし怯むことなく真っ向から宣戦布告した日万凛は、優希とともに、運命の戦いへと挑む――!', '2026/02/09 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d008c714-2dd5-487c-a0d1-644b7f53ae9d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3e21be08-33f6-4c11-b06e-aa6b35524024', '7c9f281d-3d42-46e9-aa57-337b8b659052', 6, '100253232', '新たなる東', '《東の晩餐》へと参加し、誉を倒した優希と日万凛は九番組組長･風舞希と対峙する。奴隷化の進化形態《天進》で戦うも、風舞希の圧倒的な一撃から日万凛を庇った優希は意識を失ってしまう。日万凛は自身の能力だけで母である風舞希へ挑む——', '2026/02/16 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a47a50a0-1adb-40da-8f29-6aa36784f811.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47497a2b-9e23-4036-8fdf-d89d3fe576f6', '7c9f281d-3d42-46e9-aa57-337b8b659052', 7, '100254169', 'スレイブの晩夏', '《東の晩餐》を終えた優希と日万凛は、風舞希に稽古をつけてもらう。その最中、風舞希が鎖に触れたことで貸出しが発動。優希は新たなスレイブ形態《肉弾》へと変身してしまう。一方、現世では新たな八雷神･空折が出現し、餌として女性の誘拐を始めていた——。', '2026/02/23 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/04618fa5-28c5-4b83-97ec-daa585770ffd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bf36f77-d45f-4964-b9f2-e26a6373b047', '7c9f281d-3d42-46e9-aa57-337b8b659052', 8, '100254624', '二番組 組長', '組長会議に招集された各組長と優希。横浜市内での相次ぐ女性失踪事件と、その裏に新たな八雷神の関与が共有される。事件解決の任を受けた二番組組長･美羅は、同行者として京香を指名。こうして、美羅･京香･優希の三人は現世へと赴くことになるのだった。', '2026/03/02 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c23b98ae-7aa5-47c4-a3cc-fa96325f9117.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3737b50e-0ad8-4e78-b1a5-9640d7c973eb', '7c9f281d-3d42-46e9-aa57-337b8b659052', 9, '100255617', '組長の覚悟', '優希の前に、突如姿を現した空折。強引に交合を迫るも、優希の叫びを聞きつけた美羅が駆けつける。逃走を図る空折に向け、美羅は能力《緋色の連隊》を発動する——。', '2026/03/09 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a995bd4-0962-43ba-abba-1493b911de42.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19e85c99-f1c0-4e95-860f-cfdec1a14b6b', '7c9f281d-3d42-46e9-aa57-337b8b659052', 10, '100255618', '横浜決戦', '駆けつけた優希と京香の目に映ったのは、美羅を取り込み、力を吸収する空折の姿だった。美羅を救おうと立ち向かう2人だったが、力を得た空折に苦戦を強いられる。巨大な醜鬼を横浜上空に召喚し、さらに自らを分身させることで軍勢を形成する空折。一方、ついに魔防隊側の援軍も横浜へと集結する――。', '2026/03/16 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64fe67f1-d90c-49f3-8ebf-bb83e31eb785.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a056b43-0a67-4521-bd5a-10b865ccc677', '7c9f281d-3d42-46e9-aa57-337b8b659052', 11, '100256784', '無窮の鎖 天', '空折と渡り合うも、決定打を欠く魔防隊。戦況を打開すべく、優希は《天進》へと形態を変え、京香も技で動きを高める。一方、空折も腕を分身させた《百万神罰》の形態へと変貌し、両者は激しくぶつかり合う。激化する戦いの中、優希と京香は新たな技を空折へと繰り出す――!', '2026/03/23 00:30:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85abd008-f672-4c83-98e5-c2147b83151f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('a82627ac-3873-463c-ac69-ee1cc6d4f55b', '魔導具師ダリヤはうつむかない', '', 'hulu', 'dahliya-in-bloom', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a414f9bc-078f-41d4-878b-28460f3e40f0.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 168623, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 'a82627ac-3873-463c-ac69-ee1cc6d4f55b', 'hulu-dahliya-in-bloom-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9f1e4aa-51cc-404f-8a2c-9fbb48ac1963.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aad985ed-0584-47c4-ac2d-255ae7adee8d', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 1, '100190448', 'ダリヤの夢', 'ダリヤ･ロセッティは二度目の人生を魔法のある世界で歩むことになった。父･カルロが見せてくれた魔導具･妖精結晶のランタンの輝きに感動して、父と同じ魔導具師になることを決意する。幼いながらも、さまざまな魔導具を夢想しては、書き溜めていく日々。そんなある日、ダリヤは父が出かけている間に、一人で魔導具を作ろうとするが――。', '2024/07/12 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9f1e4aa-51cc-404f-8a2c-9fbb48ac1963.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f410b3ba-a477-481e-9fe3-334dd141b163', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 2, '100191079', 'カルロとの思い出', '雨に濡れた父のコートをヒントに、レインコートの制作を思いつくダリヤ。兄弟子･トビアスに手伝ってもらいながら試行錯誤を繰り返す。遂に完成した完全防水の布と、その布を使ったレインコートは大きな話題となり注文が殺到する。そんな折、魔導具作りに成功した二人に、婚約の話が飛び出す。', '2024/07/19 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a2a13ee9-240a-47ae-9a7c-22671fee43d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d73f6081-6ebb-4634-af10-eedeefce8bc3', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 3, '100192070', '真実の愛?', '最愛の父･カルロがこの世を去ってから1年後、ダリヤは婚約者のトビアスから婚約を破棄させてほしいと告げられる。ひとりぼっちになってしまったダリヤは、前世の最期を思い返し、今度こそうつむかず、生きたいように生きていこうと決意する。', '2024/07/26 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a22e9c1c-81b8-4f42-bae0-8de0b8922487.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc1d0041-b2a9-4ad7-8c2e-e820ab9abfe9', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 4, '100192681', '騎士との出会い', '森に出掛けたダリヤは、重傷を負った騎士･ヴォルフと出会う。助けてくれた礼をしたいと申し出るヴォルフに、今度会ったらという約束をして別れる。一方、商業ギルドで、トビアスによる契約トラブルが発覚する。巻き込まれたダリヤに、商業ギルドの面々は協力を名乗り出る。皆の後押しもあり、ダリヤは商会設立を決める。', '2024/08/02 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebda7d8f-d38f-40ab-b8cf-e8e6a4ae131c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db750b9b-685a-4c3e-af36-c6a65366136f', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 5, '100193823', '父の贈り物', 'カフェテラスでヴォルフと再会するダリヤ。森では姿を偽っていたダリヤだったが、ヴォルフはすぐに本人だと見抜き、食事をご馳走させてほしいと申し出る。ヴォルフは貴族で騎士、さらに衆目を集める美貌の持ち主だったが、魔導具が大好きなダリヤと魔剣に興味津々なヴォルフは話が盛り上がり、貴族街にある魔導具店に出掛ける約束をする。', '2024/08/09 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7247916f-1310-4ca5-bcbe-927e7c339193.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a30519dc-662e-4783-8689-fcb7eb6fb035', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 6, '100194405', '妖精結晶の眼鏡', '亡き父の旧友が営む魔導具店を訪れた夜、ダリヤは自分の家にヴォルフを招待して夕食を振る舞う。友人として気が合う二人。ヴォルフは目立つ美貌のせいで常に女性から欲望の目を向けられ、男性とは仲良くなってもすぐに友情が破綻してしまうことを打ち明ける。自分の顔が大嫌いだという彼の悩みを聞いたダリヤは、妖精結晶を使った魔導具で彼の金の目を隠すことを思いつく。', '2024/08/16 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7cdbc8a-bdf7-4c19-a8e3-a9e717702079.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ebd0a3f-535a-4b0e-9ebb-1e8a487fde73', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 7, '100195262', '大騒動の予感', '一緒に人工魔剣をつくる約束をしたダリヤとヴォルフだったが、ヴォルフの遠征任務が入り延期になってしまう。魔剣作成が待ちきれないヴォルフは、いつになく積極的に任務にあたり、予定よりも早くダリヤの家を訪れる。二人は協力しあいながら魔剣作成に挑むが、やはり一筋縄ではいかず試行錯誤する。やがて一本の試作品が出来上がったのだが、それは禍々しいオーラを放っており……?', '2024/08/23 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d4902ad-f6bf-460e-ab64-c83d29d9e71d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58710bc3-179f-44ae-b4db-6dc202f33305', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 8, '100195899', 'ロセッティ商会', '暑さと湿気の厳しい土地へ遠征に向かうヴォルフに、ダリヤが渡した試作品の魔導具･五本指靴下と乾燥中敷きが討伐部隊内で話題となり皆が欲しがる大人気商品になってしまう。ただちに正式導入したいと、騎士団から大量発注がかかり、手に負えなくなったダリヤはヴォルフとともに商業ギルドへ相談に行くことに。服飾ギルドや冒険者ギルドも巻きこんでの大きな話となっていき……。', '2024/08/30 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/10d4b51e-fe07-4271-bb8a-65ed2ea14e5c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4da4022c-2048-4ab3-bc16-5638a8603c30', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 9, '100196673', '悪夢を越えて', 'ロセッティ商会の保証人になった件について話すため、王都にある実家スカルファロット家の別邸を訪れるヴォルフ。迎えた兄･グイードは歓迎し、惜しみない協力を申し出る。これまで交流のなかった弟の世話を熱心に焼こうとするのはなぜなのか、その原因が、ヴォルフの母がグイードらを守って命を落としたことにあると気づき……。一方、ダリヤは泡ポンプボトル改良のため、職人のフェルモに共同開発の依頼を持ち掛ける。', '2024/09/06 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64481225-1f07-4a94-b97f-2af4e3f0b9af.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e28419ca-8117-4758-ae1b-e70f81800663', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 10, '100197854', '王城への招待', '風魔法の効果を付与した腕輪型の魔導具を試作したダリヤ。すさまじい跳躍を可能にする腕輪に興味をそそられたヴォルフは、自分専用の魔導具にしてもらうことに。一緒に食事を楽しんだり、ヴォルフの話をヒントにダリヤが靴乾燥機の魔導具を新しく作ったり、二人の時間は過ぎていく。その翌日、商業ギルドを訪れていたダリヤの元に、魔物討伐部隊の副隊長が書簡を届けに来る。', '2024/09/13 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38fb94ce-5e5d-4ba0-ac33-5763ed5c1ad3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('28579907-f47c-46ac-86ba-14e4080c720f', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 11, '100198856', '空へと咲く花', '魔物討伐部隊長からの書簡で招きを受けたダリヤは、王城へ向かう。急な呼び出しに緊張しながら待っていると、現れたのはヴォルフだった。隊長のグラートがダリヤに直接、五本指靴下と乾燥中敷きのお礼が言いたいのだという。王城訪問を終えた夜、訪ねてきたヴォルフ。彼と酒を飲みながら互いに秘密を暴露しあう遊びをする。ダリヤは今まで一度も触れなかった自身の母についてヴォルフに語り……。', '2024/09/20 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0136df3-4e82-45e1-9876-3256b29a3835.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('166ddcac-69e9-4959-9097-fc8ff1c6c0e3', '4232dd92-56d1-4f00-a229-2ffb0e6ccbb2', 12, '100199688', '魔導具師ダリヤはうつむかない', '【シーズン1 最終話】久しぶりに人工魔剣の試作に取り組むダリヤとヴォルフ。作業を終えて机を片付けていた時、置きっぱなしになっていた鏡蛇の鱗が目に留まる。めくらまし効果があると言われている鏡蛇の鱗。ダリヤが付与を試みると、突如鱗が光り出し二人を取り囲む。光の中で二人が見た光景は、煌びやかなダンスホールで一緒に踊る自分たちの姿だった。', '2024/09/27 03:38:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df2e34e1-152b-40fa-82e0-32eabfadd608.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('748fb335-25a7-41b3-b809-48a0e2cb6c6e', '魔道祖師Q', '', 'hulu', 'the-founder-of-diabolism-q', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e0ba5b7-56df-4d1f-a3dd-355c32c22b78.png?w=331&h=447&p=t', 'hulu', 0, 0, 1, 'FINISHED', NULL, 120343, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e64c8cb4-59c5-491e-a8d2-42d63fdf67c3', '魔入りました！入間くん', '', 'hulu', 'irumakun', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e121bfdf-194a-431b-96e2-49a1b412a0ae.jpg?w=331&h=447&p=t', 'hulu', 2019, 3, 1, 'FINISHED', NULL, 107693, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2ba87985-c615-4c57-a63a-fd676a5d3d43', 'e64c8cb4-59c5-491e-a8d2-42d63fdf67c3', 'hulu-irumakun-s1', '第1シリーズ', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2402d3dd-2d3d-48e5-a141-e3728f34a560.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b6e2822-edab-4029-aab5-0b7d027d0379', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 1, '100043160', '悪魔学校の入間くん', '頼み事を断れない極度のお人よし少年･鈴木入間 (いるま) は、ある日突然、悪魔たちの住む魔界へと連れてこられてしまう。大悪魔･サリバンの屋敷に着いた入間は、そこで信じられない“頼み事”をされる…。それは“サリバンの孫になる”こと! 早速、溺愛される入間は、彼が理事長を務める悪魔学校･バビルスに入学することに…。人間の正体を隠しながらの、魔界のドキドキスクールライフがいま、始まる!', '2019/10/07 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2402d3dd-2d3d-48e5-a141-e3728f34a560.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('855651c6-6b66-45ad-a1e3-ea7571c63d5c', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 2, '100043580', '使い魔、召喚!', 'バビルスに通うことになった入間は、人間だとバレないよう、平穏に過ごしたいと考えている。しかし、入学式や入試主席アスモデウス･アリスとの一件により、すでに生徒の注目の的となってしまっていた! 1年生の入間たちは、悪魔の位階 (ランク) を決めるための行事「使い魔召喚の儀式」に参加することに。担当はバビルスでもひときわ厳しい教官、ナベリウス･カルエゴ。入間が召喚する使い魔とは、いったい…?', '2019/10/14 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d94991fa-63d8-4118-9bf3-f90f6d48fa70.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7da78687-0568-4e91-8a39-dde26c2acafa', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 3, '100043770', '入間とクララ／悪魔のお友達', '「入間とクララ」：入間とアスモデウスがバビルスで新たに出会ったのは、変わり者の女子悪魔、ウァラク･クララ。珍獣扱いされているクララは、他の生徒からいいように利用されているようなのだが…?「悪魔のお友達」：アスモデウス、クララとすっかり打ち解けた入間。通学のお迎えから始まり、悪魔の文化に戸惑いつつも学生生活を送っていた。そんなとき、食堂で他の生徒からイタズラをされるが…!?', '2019/10/21 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a60d3c8-0a1f-42e7-9aba-62a051cc178a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96953fb8-83ad-4d1c-85f6-1d2f137260f3', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 4, '100044049', '問題児 (アブノーマル) クラス', '入間のクラスはアスモデウス、クララと同じ「問題児 (アブノーマル) クラス」に決まった。その名のとおり問題児ばかりのクラスで、入間は次期魔王を目指す巨体の悪魔、サブノック･サブロにいきなりライバル宣言される。早速始まった授業では「飛行レース」が行われることに。レースの舞台となる谷には、「囀 (さえず) り谷」と「金剪 (カナキリ) の谷」という異なる難易度のコースがあるらしい。そこには危険な怪鳥もいて…。', '2019/10/28 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cff9da62-8fa7-4347-8fb3-c557c69ad50f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f732b97c-4c79-4be8-9b95-848bd7afeda5', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 5, '100044265', '魔王を目指す者', '悪魔の位階 (ランク) 決めのための試練「飛行レース」。飛ぶことができない入間は怪鳥のヒナの背に乗せられ、どこかへ連れていかれてしまう。一方、単身危険な金剪 (カナキリ) の谷コースへ向かったサブノックは、凶暴な谷の長 (おさ) と死闘を繰り広げていた。「魔王になるまでは死ねない!」と心に誓うサブノックの“魔王を目指す理由”とは? 入間とサブノック、果たして二人は無事、谷から生還することはできるのか!?', '2019/11/04 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/14611013-7ed5-41af-97b2-28615634e31f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('46543c4d-d262-49f6-85e9-dcf2c5db0134', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 6, '100044746', 'アメリの仮説', '魔力をためることができる“悪食 (あくじき) の指輪”を手に入れてしまった入間。常日頃から、人間だとバレないように生活していきたいのだが、指輪の力を知らずに、授業でまたもや生徒たちの注目を集める事件を起こしてしまう。そんな入間を「人間ではないか」と疑う悪魔がいた。その悪魔とは、生徒たちから尊敬を集める生徒会長のアザゼル･アメリ! 女傑のアメリだが、入間を疑っているのには、ある意外な秘密があって…?', '2019/11/11 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/77e94b73-8449-473c-b9f8-e03c893bcc1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9f47ea2-7b73-452b-ad7d-5d0a54709a5b', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 7, '100045168', '初恋メモリー', '入間が廊下でぶつかったのは、入間のことを人間だと疑ってやまないアメリだった! 入間はぶつかった拍子に、アメリが人間界の少女漫画『初恋メモリー』を所持していることを知ってしまう。『初恋メモリー』は、魔界では禁書扱い。しかし、そのトキメキあふれる内容への興味を抑えきれないアメリは、正体を突きとめることを言い分に、入間に漫画の朗読をさせることに! 入間とアメリの、ナイショの朗読会が始まる!', '2019/11/18 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/538f8859-ab0b-49cf-a3ae-80922b9eaea9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('492917a8-013b-4af6-a5fe-69ccc57804a1', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 8, '100045670', 'クララにメロメロ', '入間が頻繁にアメリに呼び出されることをおもしろく思っていないクララ。入間の気持ちを自分へと向かせるため、サキュバス族であるライム先生の誘惑授業を受けることに。入間を夢中にさせようと意気込むクララだが、クララの「イロケ度」はライム先生も驚くほど壊滅的な数値を記録。それでもめげずに、あの手この手を使って入間を虜 (とりこ) にしようとたくらむクララ! 果たして、入間をメロメロにすることはできるのか!?', '2019/11/25 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b8d8ba6-ccba-4be9-be88-0fbfb6daabbc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3314359f-8975-47ed-b6a7-df62f260d12a', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 9, '100046333', '入間の決意、高鳴る努力', 'アメリとの約束で、位階 (ランク) の昇級を目指すことにした入間。1週間後に開催される昇級試験「処刑玉砲」を受けることに。「処刑玉砲」とは、入間もよく知る人間界のあの球技によく似ていて…!? 他の問題児クラスの生徒たちとの力の差を感じた入間は、特訓することを決意。魔術に頼らず自分の力で勝負したいという入間に、屋敷の執事･オペラによるスパルタ特訓が待っていた。特訓に特訓を重ねた入間が得たものとは…!?', '2019/12/02 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9264547-b313-4a32-8518-414f32cd6a4c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('83c2244a-9f04-4323-99f0-ce4fad08a74a', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 10, '100046963', '激闘、処刑玉砲!!', '位階 (ランク) 昇級試験、「処刑玉砲」当日。気合い十分で試合に臨む入間だが、チーム分けでアスモデウスと敵対するチームになってしまう。入間を勝たせるべく、策を練るアスモデウス。その間にも、クラスメートたちはおのおの得意とする魔術を使って容赦なくゲームを進めていく。果たして入間は、特訓の成果を見せることはできるのか!? そして入間とアスモデウスの、勝負のゆくえは…!?', '2019/12/09 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/183ddbae-3a3f-42c7-b3cb-086047f2d5ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('993917d5-7970-465f-8383-c8f80a9f1a82', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 11, '100047210', '使い魔といっしょ!／師団 (バトラ) の挑戦', '「使い魔といっしょ!」無邪気で怖いもの知らずの新任教師、バルス･ロビンがバビルスにやって来た! 彼による初授業は『使い魔との交流』。使い魔としてカルエゴを召喚してしまった入間は授業内容に青ざめるが…?「師団 (バトラ) の挑戦」位階 (ランク) 上げの次なる目標を探す入間。バビルスには共通の趣味を持つ者同士で交流する団体活動、師団なるものが存在するらしい。師団に興味を持つ入間の元に、謎の足音が…!?', '2019/12/16 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d0cf49e-7621-4c38-9fa1-3bd75a4ffbf5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('777642d0-d8d0-442d-a8a4-c097284e5348', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 12, '100047634', '1年生争奪戦 (ルーキーハント)!!', '新入生を巡って、上級生が師団 (バトラ) へと勧誘する1年生争奪戦 (ルーキーハント) が始まった。優秀な新入生を獲得しようと、力ずくで襲いかかってくる上級生たち。そこで繰り広げられる、すさまじい攻防戦! 1年生争奪戦をなんとか乗り切った入間たちは、学内のさまざまな師団を見学して回ることに。そんな中、突然入間の指輪が暴走し始め、とある上級生に激突してしまう事態に!?', '2019/12/23 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c703fea1-200a-478b-9b5e-a1c6408d8352.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb8fdc65-0c04-439d-97f4-77a0933c929f', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 13, '100047935', '魔具研究師団 (バトラ)／13冠の集い (サーティーン･ディナー)', '「魔具研究師団 (バトラ)」魔具研究師団の部屋の前で、再び上級生のアミィ･キリヲに出会う入間。魔具研究師団の部屋には不思議な器具や装置など怪しいものがいっぱい。入間はそこでキリヲの野望を聞く。「13冠の集い (サーティーン･ディナー)」バビルスでは新入団員のお披露目として『師団パーティー』が行われる。入間の晴れ姿を楽しみにするサリバンだが、魔界の有力者が集う「13冠の集い」に出席しているようで…?', '2019/12/30 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b53b7c9-7503-4dd5-a69a-61546188a5d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2a298ae-f4f3-40f9-b435-8f0649ae9e98', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 14, '100048283', '師団 (バトラ) のお披露目', '人間界への渡航の疑いで、サリバンが魔関署に拘束されてしまった! 入間のためにも、師団披露 (バトラパーティー) にはなんとか駆けつけたいところなのだが…。一方、そんな事情を知らない入間は、魔具研究師団の披露の準備を進めていた。みんなのやりたいことを集めた結果、人間界で言うところの「花火」を作ることに。泊まりがけで作業をすることにした入間たち。魔具研究室で、楽しいお泊まり会がはじまる!?', '2020/01/13 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00498b04-7aad-4c1b-8fe1-62f3ffc03289.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36f7e732-fdbf-4dad-b08c-aa9bc595c8a8', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 15, '100048284', 'キリヲの隠し部屋', '師団披露 (バトラパーティー) の準備を着々と進めていく入間たち。花火の砲台が完成に近づきつつある中、姿の見えないキリヲを探しに行く入間。入間は指輪に強引に導かれ、バビルス校内にある謎の隠し部屋にたどり着く。そこではキリヲが、秘密裏に“ある計画”を企てていた! さらに、キリヲが連絡を取っていた相手も明らかに! キリヲのたくらみとは!? そして、隠し部屋で入間が見たものとは、いったい…!?', '2020/01/13 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/82dd6749-9e69-4902-b944-4b5da0672c0f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5be21cdd-1e81-47d5-b5fd-3f4210891732', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 16, '100048988', '前夜祭', 'キリヲが語った「野望」。魔力が弱い悪魔も強い悪魔も関係ない、上下関係のない世界―に共感した入間は師団披露 (バトラパーティー) で特賞を狙おうと宣言。自分たちが特賞をとれば、ハイランクの悪魔から魔具研究師団、そしてキリヲの努力も注目されるはず…。ついに始まった前夜祭では、屋台や出し物など、お楽しみが盛りだくさん! しかしその裏で、入間たちが準備していた花火の玉がなくなっていて…?', '2020/01/20 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d0769677-6af9-4a11-8bbb-6fc004a14ac0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fec7e54a-f4da-4e63-ad6d-4e67fd3e74be', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 17, '100049315', '走れ入間、キリヲのもとへ!', '突如としてバビルス全体が見えない壁で取り囲まれてしまった! さらに、外部との連絡は取れず、校内のあちこちにも見えない壁が出現。バビルス中が大混乱に陥る中、カルエゴたち教師陣は、前夜祭を続行しつつ生徒を中央広場に避難させようと策を練る。行方の知れないキリヲの身を案じた入間は、アスモデウス、クララと力を合わせてキリヲを探しに行くことに。果たして入間は、キリヲのもとへたどり着けるのか!?', '2020/01/27 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b525bc9-1bcd-445f-9dfb-dcbca49d273d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa45fd58-bee2-4d98-86e0-e6b9f1e668c8', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 18, '100049909', '心から望むもの', '刻一刻とキリヲによるバビルス爆破計画が進む。何とか隠し部屋までたどり着いた入間。魔具研究師団 (バトラ) の花火を使ってバビルスの爆破をもくろむキリヲは、ふだんの姿からは想像もつかないものだった…。キリヲは入間に、幼き日のある出来事を語る。キリヲの悪魔としての本性を悟る入間。バビルス絶体絶命の危機を回避することはできるのか!?', '2020/02/03 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b64688ec-9e39-4a62-b98a-6ed0e5e2e9d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17d3ee2a-bfa5-4a76-9c3b-3455a23d0c17', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 19, '100050434', '全部拾いたい／家族との時間', '「全部拾いたい」入間が目を覚ますと、すでに一連の騒ぎは収まっていた。入間はサリバンからキリヲが逮捕されたことを知らされる。巨大花火が上空に打ち上がったあと、火花降り注ぐ地上で起きたこととは…?「家族との時間」バビルスの危機も一件落着。いよいよ師団披露 (バトラパーティー) 本祭の始まりだ! 優秀な師団に贈られる『特賞』を目指し披露に力が入る生徒たち。見学に来た生徒たちの家族も加わり祭りは一層にぎやかに!', '2020/02/10 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/72031a29-6aec-4a14-8447-8fd81fc7680d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f716f890-c76b-42c2-8c53-90b696c8adfc', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 20, '100050808', '栄えある表彰／人間の処遇', '「栄えある表彰」優秀な師団 (バトラ) の表彰が行われる、師団披露 (パーティー) 後夜祭。入間たち魔具研究師団も『特賞』を狙う! それは、入間がキリヲと交わした約束でもあった。果たして、賞の行方は…!?「人間の処遇」花火の一件で、またまた目立ってしまった入間。そんな入間を「人間ではないか」と疑う魔関署の警備長、アザゼル･アンリがバビルスにやって来た! あれ…? この感じ、前にも見たことがあるぞ?', '2020/02/17 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/286c5a0f-3e86-4259-8c4d-9154e16e9737.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9b1e99c9-0403-4042-9af2-dcb7301fa707', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 21, '100051035', 'アクドルくろむちゃん!', '魔界で大人気のアクドルくろむの、朝昼晩のいちにちライブが魔苦針 (まくばり) ドームで開催! アクドルとは、悪魔たちの『悪周期』の悪意を発散させる重要な職業。中でもくろむは若手の有望株で、チケットは即日完売するほどの人気ぶりらしい。しかしくろむには、人には言えない秘密があった…。幸運にも、くろむのライブチケットを手に入れた入間はアスモデウス、クララと一緒にライブへ行くことに!', '2020/02/24 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9930ca14-3724-4803-8da8-619920c1bb5e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c3581861-0243-4928-9122-5be2c96c472e', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 22, '100051292', 'キラキラの衝撃', 'くろむの正体は、問題児 (アブノーマル) クラスの生徒、クロケル･ケロリだった! ケロリは入間と話をするうちに、入間の人気ぶりに嫉妬。感情が高ぶり、ついには倒れてしまう! とてもライブができる状態ではないケロリだが、ケロリには、どうしてもライブを中止にしたくない、ある理由があった。そんなくろむの魔苦針 (まくばり) ドームライブを成功させるため、入間たちは驚きの行動に出る!!', '2020/03/02 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/979039e0-5076-45dc-a73b-6c5e496ef191.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4f98fc4-ef95-4adb-a87b-aca63636cc39', '2ba87985-c615-4c57-a63a-fd676a5d3d43', 23, '100051764', '馴染 (なじ) みました! 入間くん', '【第1シリーズ 最終話】すっかり魔界での生活になじんだ入間。いつもどおり、クラスメートたちと楽しく過ごしていたが、ふと「このまま魔界に居続けていいのか?」と考え始める。一人悩む入間の姿を見たアスモデウスとクララは、入間を元気づけるため、手料理をふるまうことに! しかしクララの母直伝のレシピには、アスモデウスでも知らない要素が満載。ライバル心むき出しの二人は、いつの間にかお料理対決へと発展!? 入間が選んだのは、果たして―?', '2020/03/09 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a8b8819-fb1f-44c1-98d8-19a30f558fe3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('cc655703-1c73-4f14-a380-18bda557843d', 'e64c8cb4-59c5-491e-a8d2-42d63fdf67c3', 'hulu-irumakun-s2', '第2シリーズ', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48cb9a73-dbff-4b54-9de0-56639c95574f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d1d4eb66-31dc-4020-8e6a-3bbab238dc48', 'cc655703-1c73-4f14-a380-18bda557843d', 1, '100080122', '指輪の秘密', 'ひょんなことから魔界に連れてこられた少年、鈴木入間。彼は、人間であることを秘密にしながら悪魔学校バビルスに通っている。魔力を持たない人間であるため、魔術の授業は、魔力を保管できる魔具「悪食 (あくじき) の指輪」を使って乗り切っていた。そんなある日…突然! その指輪がしゃべりだした!? 一体なぜ…? 入間は、アリクレッド、通称「アリさん」と名乗る指輪の化身と初めての対話を果たすことに…!', '2021/04/19 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/48cb9a73-dbff-4b54-9de0-56639c95574f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cbb48322-394a-44c9-9e13-b4d8cf99a2f3', 'cc655703-1c73-4f14-a380-18bda557843d', 2, '100080550', 'アメリの決断', '先輩キリヲの不在により活動休止となってしまった「魔具研究師団 (バトラ)」。活動を再開させる条件として生徒会長のアメリから課されたのは、他師団での研修! アスモデウスは「魔術開発師団」、クララは「遊戯 (ゲーム) 師団」、そして入間は「生徒会」で研修を受けることに。目まぐるしい生徒会活動と厳しい鍛錬に励む入間!…そんな中、アメリに魔の手が忍び寄ろうとしていた…。', '2021/04/26 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7186ebbf-497e-482b-a669-976d777a4221.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d8ad02b-b178-4d51-b0a2-b333bd6c41ab', 'cc655703-1c73-4f14-a380-18bda557843d', 3, '100081082', '乙女な悪魔', '何者かの仕業により性格を変えられてしまった生徒会長アメリ! いつもに比べておしとやかなアメリに生徒会メンバーたちは動揺を隠せない。そんな中、自称生徒会のライバル「風紀師団 (バトラ)」団長のロノウェ･ロミエールが会長の座を狙い乗り込んできた! ロノウェはチャンスだといわんばかりに、アメリに現生徒会の解散選挙――〈タイマン〉を申し込む! アメリを襲った犯人は誰なのか? そして、決闘の行方は…!?', '2021/05/03 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9312088-efcb-4a13-8b2b-3079271d8d32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f6b9859-cb3c-4f4a-993d-844307954ac3', 'cc655703-1c73-4f14-a380-18bda557843d', 4, '100081532', '生徒会長の眺め', 'ロノウェが生徒会長の座を奪うため突きつけた宣戦布告――「解散選挙 (タイマン)」は投票日が迫っていた! しかし、何者かにかけられた魔術により、いつも通りに振る舞うことができないアメリは、期待に応えられないと弱気に…。そんなアメリに入間は、かつてアメリから言われた言葉を返し勇気づける。生徒たちの注目がロノウェに集まる中、アメリはどんな演説をするのか…? そして、彼女が心の中で見つけた気持ちとは…?', '2021/05/10 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb055a2e-2fec-4bdd-8f7c-e6d570ec532f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15eb6cc5-7c78-46f6-be9f-b07b4eff1cd7', 'cc655703-1c73-4f14-a380-18bda557843d', 5, '100082161', 'オトモダチご招待!', '生徒会での研修を無事に終え、久々に帰宅した入間。入間が帰ってきてうれしくてたまらないサリバンは、お祝いのパーティーを開催! 招待されてやって来たアスモデウスとクララも一緒に、みんなで楽しい時間を過ごす中、ダンス対決で最下位になってしまったサリバンは、入間にかっこいい姿を見せるため「暗黒大行進」なるものを提案して…?', '2021/05/17 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e35572e4-3787-4cff-8911-b9ab767bff87.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7fa723a1-59b9-4227-bd4b-054d916262d5', 'cc655703-1c73-4f14-a380-18bda557843d', 6, '100082625', '王の教室 (ロイヤル･ワン)', '悪食の指輪の化身、アリさんにより「悪周期」にされてしまった入間。普段ではあり得ない強気な立ち居振る舞いに、クラスメイト達は困惑しつつも感心。そんな中、アブノーマルクラスの教室が、劣悪な環境であることに気が付いた入間は、担任カルエゴにある提案をする。それは、悪魔学校バビルスにおいて、最高の価値を持つ、王の教室――ロイヤル･ワンへの移動だった…! 突然の無茶な提案に対して、カルエゴは一つの条件を出す。', '2021/05/24 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0e82ff0e-9f14-42c1-b38d-47ca4fe12fc2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0efc12d-9105-4961-8c1c-d30419a1559a', 'cc655703-1c73-4f14-a380-18bda557843d', 7, '100083363', '悪魔学校 (バビルス) の教師たち', '王の教室 (ロイヤル･ワン) への移動条件として「学校の教職員全員の許可書を3日以内に集めること」となった、アブノーマルクラス一同。「悪周期」の入間は、なかなか許可書に判を押さない教師たちに対して、クラスメイトの能力を生かした作戦を立てる。その作戦の第一歩として強敵カルエゴと対じするのは、アンドロ･M･ジャズ! はたして入間たちの作戦は成功なるか!?', '2021/05/31 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ad124f85-6e00-4316-9da1-e658c8e8eebf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04792c9f-7780-4db3-892b-40a5926b9d36', 'cc655703-1c73-4f14-a380-18bda557843d', 8, '100083826', '道化師の奇跡', 'クラスメイト一同で協力し、ようやく教員たちの許可書を集めた入間たちは、「自分以外の全てを集めれば判を押す」と言っていた、担任カルエゴの元を訪れる。しかし、カルエゴは判を押そうとしない。計画の欠陥に気付かされ、土壇場での形勢逆転に万事休すとなる入間たち…。だがロイヤル･ワンへの教室移動を諦めかけたその時、職員室のドアをノックする音が聞こえた! そこにいたのは…?', '2021/06/07 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ee0b5a4d-3076-4f62-9f7b-21950f4c765e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('587a5d28-19e3-48d9-ab0c-a07f3711d69b', 'cc655703-1c73-4f14-a380-18bda557843d', 9, '100084211', '魔界のお勉強', 'もうすぐ悪魔学校の長期休暇、「終末日」がやってくる! 浮かれるアブノーマルクラスの生徒たちだが、終末日の前には座学の一斉テスト「終末テスト」が…。「終末日」を補習で終わらせないためにも、赤点は絶対に避けたいところ。だが、人間の入間にとって魔界の知識は皆無に等しい。どうにか成績を上げるべく、アスモデウスとクララの協力のもと、入間はあの手この手でテストのための勉強を開始する!', '2021/06/14 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a1df1db-e686-4de5-b417-4f947591679b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ea66a688-8c71-4a25-b0a5-665aa08c9fd8', 'cc655703-1c73-4f14-a380-18bda557843d', 10, '100084588', 'バラムの授業', '生きものを見ると生徒でもお構いなく「触り癖 (スキンシップ)」が出てしまう空想生物学の担当教師、バラム･シチロウ。見た目の恐ろしさも相まって、生徒たちからは怖がられている存在だ。そんなバラムが授業中、入間の背中に悪魔の羽がないことに気付いてしまう! 魔界で人間だとバレるとどんな目に遭うか分からない。だがピンチにも関わらず、入間はバラムに思わぬことを口走ってしまい…!?', '2021/06/21 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/836aaf6b-ac31-4bef-8781-fa778a65c4cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64eaf97c-550a-4408-b2f3-54b3034f56ad', 'cc655703-1c73-4f14-a380-18bda557843d', 11, '100084987', '終末テスト／ガールズトーク', '「終末テスト」いよいよ終末テストが返却される! 果たして入間、そしてアブノーマルクラスの生徒たちは赤点を回避し補習を免れることができるのか!?「ガールズトーク」入間との読書会の支度をするアメリ。そこにいきなりクララが乗り込んできた! クララはアメリを連れ出すと、エリザベッタとケロリを交え、突然の女子会を始める。世間話あり、禁断の恋バナありで盛り上がる中、一同はだんだんおかしなテンションになっていき…?', '2021/06/28 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52608055-173c-4606-be17-f9e9fe88ba6b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a964906-13fc-4dd8-9822-b68edc9c4b58', 'cc655703-1c73-4f14-a380-18bda557843d', 12, '100085605', 'カルエゴ先生の家庭訪問', 'サリバンに命じられ、アブノーマルクラスの生徒たちの家庭訪問をすることになったカルエゴ。さっさと済ませてしまいたいところだが、アスモデウス邸やクララの家をはじめとする各家庭では生徒同様、個性豊かな面々に出迎えられ、一筋縄ではいかない! そしてたどり着いた入間宅、つまりサリバンの屋敷で、誰かを異常なほど警戒するカルエゴ。どうやらその相手とは、学生時代からの因縁があるらしいが…?', '2021/07/05 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/81e2fcb4-f5ec-4e4c-825b-e7956e17f941.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2db56d80-a66e-470f-a649-df4ef12f7192', 'cc655703-1c73-4f14-a380-18bda557843d', 13, '100086619', 'ウォルターパーク', '待ちに待った終末日に突入し、魔界屈指の遊園地「ウォルターパーク」に遊びにやってきたアブノーマルクラスの生徒たち。護衛として付き添うことになったカルエゴ、バラム、オペラと、入間とのデートだと勘違いしてやってきたアメリも加わって一行は大にぎわい。3つのチームに分かれて、どのチームが一番遊園地を楽しんだか勝負をすることに!', '2021/07/12 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5222a6aa-f9f7-49bc-b384-b8b75333921e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1214fbe4-f663-4744-9e41-a470f5387901', 'cc655703-1c73-4f14-a380-18bda557843d', 14, '100086956', 'みんなの遊び相手', 'ウォルターパークには楽しいものがいっぱい! どのチームが一番遊園地を楽しんだかを競うため、全力で遊ぶ一同。かわいい衣装に着替えて大はしゃぎのクララたちオペラチームや、射的勝負をするジャズたちカルエゴチーム。一行はそれぞれの行先で「ウォルタースタッフ」と出会い、楽しい時を過ごす。入間たちバラムチームもロノウェが加わって盛り上がるが、浮かれた入間は一人迷子になり、怪しい小道に迷い込んでしまう!', '2021/07/19 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e9a04aa-5ad4-4d0a-81bd-e455802a6df8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a2efc23-a15a-4039-91db-e3a43dc9aeda', 'cc655703-1c73-4f14-a380-18bda557843d', 15, '100087263', '魔獣襲撃', '入間たちが出会ったウォルタースタッフは、遊園地の破壊をもくろむ集団「六指衆 (むさしのしゅう)」だった! 六指衆の手により、ウォルターパークの各エリアで3体の巨大魔獣が出現。遊園地は一気に恐怖と混乱の渦に巻き込まれてゆく。ジャズたちカルエゴチームは、「バビルス教師心得」にのっとり、実地訓練として青牛 (マウンテン･ブル) と戦うことに!? 一方、地下の監獄ではキリヲによる脱獄計画が着々と進行していて…?', '2021/07/26 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2dd558da-ca91-45ba-97c4-273c8a15efe5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6822493-da7e-48d5-a1d2-e01a3e5e292a', 'cc655703-1c73-4f14-a380-18bda557843d', 16, '100087644', 'この感情の名前は', 'ウォルターパークに3体の巨大魔獣が出現。楽しかった遊園地の惨状をまのあたりにした入間はアスモデウスたちと共に状況を打破するべく立ち上がる! 黄鼠 (パンサー･ラット) の出現したエリアでは、オペラ、アメリが戦闘を開始。一方、青牛 (マウンテン･ブル) を相手にジャズたちは苦戦を強いられていた。リード、カムイをはじめ、戦闘向きでない家系能力を持つ者ばかりだが、ジャズの考えた作戦で起死回生の一撃を狙う!', '2021/08/02 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/273252be-078c-4465-9106-44e4ad42987b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('475acb5f-85c8-4b63-8144-53607c035e78', 'cc655703-1c73-4f14-a380-18bda557843d', 17, '100088031', '最強の矛', '逃げ遅れた子供を救出し、安全な場所に避難しようとする入間たちバラムチーム。だが、アスモデウスとサブノックが勝手に赤龍 (カーマイン･ドラゴン) と戦闘を始めてしまう! 張り合う2人は使い魔を召喚し、戦闘はさらに過激に。そのさなか、巨大な赤龍を目の前にしたアスモデウスを最大のピンチが襲う。アスモデウスとサブノック、2人の赤龍との戦いの行方は…!?', '2021/08/09 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8cf6aca9-898c-430e-a1e0-d87db2e6e817.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24b06c33-c95a-4aae-955d-6c2c581de573', 'cc655703-1c73-4f14-a380-18bda557843d', 18, '100088815', '僕の欲', '3体の巨大魔獣が合体し強力な「合成魔獣」が誕生。大量の魔力をため込み始めた合成魔獣の攻撃の軌道をそらすため、ロノウェは家系能力「カリスマ」を発動させるが…!? そして合成魔獣の強力な一撃が放たれようとする時、入間はアリさんとともに眼前に飛び出す! 入間のむちゃな挑戦に高まる緊張。果たして、決着は――? そしてウラボラス監獄からの脱獄に成功したキリヲ。その手引きをしていた悪魔の正体も明らかに…。', '2021/08/16 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/00bcfe3e-3ec2-40e2-9399-53c1a65c542c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8904de37-3868-43cd-b577-4ead8f0a4297', 'cc655703-1c73-4f14-a380-18bda557843d', 19, '100089214', 'クララのお家', 'ウォルターパークを救った英雄として世間の注目を集めた入間は、連日詰めかける大勢の取材陣のせいで帰るに帰れなくなっていた。そこで、アスモデウスと一緒にクララの家にお泊りすることに。クララの家は、不思議な生きものや植物が生息するガヤガヤ森にある。いつものようにウァラク家の大歓迎を受けたあと、一同は森に食材探しへ。マミーによると、ガヤガヤ森には「究極の食材」なるものが存在するらしいが…?', '2021/08/23 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/49d595ae-7ec0-47e7-8200-e5d4c415bea2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62ddcdb4-dabb-4380-9723-8aac460129ca', 'cc655703-1c73-4f14-a380-18bda557843d', 20, '100090743', '夢見るデート', 'ガイドブックや憧れの漫画「初恋メモリー」を参考に、なにやら入念に計画を立てるアメリ――。ついに、念願の入間とのデートへ出かけることになったのだ! 水族館とプールを併せたレジャー施設「アクアケース」で待ち合わせ、水着に着替えたら…いよいよデート開始! お手製の極秘デートプランを元に、なんとかして「初恋メモリー」のようなドキドキの展開に持ち込みたいアメリだが、やることなすこと全て裏目に出てしまい…!?', '2021/09/06 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/71f0db56-c882-4c8c-b595-15f89abb3dd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a63a2f0-4b7d-48b3-859e-cb31e919ed19', 'cc655703-1c73-4f14-a380-18bda557843d', 21, '100091306', '魔界を統べる者', '【第2シリーズ 最終話】終末日も終盤。宿題を無事片付け終えた入間は、サリバンに誘われて、魔界の繁華街「マジカルストリート」へオペラと3人で買い物に出かけることに。新学期で使う教科書や魔具などの商店を楽しく巡る入間たち。そこで町の悪魔たちの会話を耳にした入間はふと、魔王の有力候補でありながらバビルスの理事長を続けるサリバンに「魔王」について問う。魔界における絶対的な存在「魔王」とは――。', '2021/09/13 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3cc0bb4d-766f-487b-ae1d-fc27da9c5736.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('73c023c5-52a7-4d11-af70-f0e6cfd92378', 'e64c8cb4-59c5-491e-a8d2-42d63fdf67c3', 'hulu-irumakun-s3', '第3シリーズ', 3, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a56fcc3c-40f7-4a88-8381-42b280f64ca7.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be0cc6fd-858d-46a4-a6fe-1650ade6ebef', '73c023c5-52a7-4d11-af70-f0e6cfd92378', 1, '100125664', '問題児クラスの新学期', 'アブノーマルクラスの生徒たちに、特別指令が下された。それは、クラス全員が2年生に上がるまでにランク4 (ダレス) に昇級すること! さもなくば苦労して手に入れた「王の教室 (ロイヤル･ワン)」から退去しなければならない。位階 (ランク) アップのための次なる行事は「収穫祭」。短期間での実力アップのため、学校側は超強力な特別講師陣を用意した。新学期早々、入間たちの、まさに規格外な特訓の日々が始まる!', '2022/10/10 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a56fcc3c-40f7-4a88-8381-42b280f64ca7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b47e785-7fca-4a59-b5b2-59ef427e4156', '73c023c5-52a7-4d11-af70-f0e6cfd92378', 2, '100125993', '師匠バチコ', 'ロビンの親戚、バルバトス･バチコから特訓をつけられることになった入間&リード。バチコはサリバンから直々に頼まれて、ロビンの助っ人として講師に着任した実力者だ。さぞハードな特訓の日々を送るはず……と思いきや、バチコから命じられるのは、使い走りや雑用ばかり。音を上げたリードは、ロビンのもとへ戻ることに。ひとり、悔しさに燃える入間。アスモデウスやクララが特訓に励んでいることを知り、ある行動に出る!', '2022/10/17 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fba44193-b2d9-42c5-84ed-97bfbad28da7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0b68c7bf-2a0d-45d9-a560-835a16989b58', '73c023c5-52a7-4d11-af70-f0e6cfd92378', 3, '100127075', '入間の本音', '入間は、ようやくバチコに特訓をつけてもらえることになった。魔界きっての弓の名手バチコから出された条件は、自分だけの弓を作ること。魔具研究師団 (バトラ) で見つけた、金剪 (カナキリ) の長 (オサ) の羽根に魔力を込め、弓を作る入間。しかし、出来上がった弓はバチコからことごとくダメ出しをされてしまう。大事なのは、「自分の欲しい弓」をイメージすることだとバチコは言うのだが…。', '2022/10/24 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e9e7423-e94c-4e2e-95aa-b38c1d52b239.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('89a40dfe-769b-4e9b-8f96-364038432d9e', '73c023c5-52a7-4d11-af70-f0e6cfd92378', 4, '100127863', '収穫祭の狼煙', 'いよいよバビルス1年生最終バトル「収獲祭」が始まる。収穫祭は、約4日間にわたって行われるサバイバル方式の位階 (ランク) 昇級試験。制限時間内にジャングルに生息する魔獣や魔植物を狩り、その累計ポイントが最も高い者が優勝となる。ハードな特訓の日々に明け暮れたアブノーマルクラスの生徒たちは、特訓を行ったチームごとに対抗意識バチバチで、気合十分。いざ、危険な魔獣が潜むジャングルへ!', '2022/10/31 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6878532a-21df-4793-8602-5b3c2d6b7f2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('daa653ef-fd92-4b5b-bf34-1b091b2121bc', '73c023c5-52a7-4d11-af70-f0e6cfd92378', 5, '100128359', '狡猾な悪魔', '圧倒的武力で獲物を狩るアスモデウス&サブノック組の前に、優勝者の有力候補「ドロドロ兄弟」イチロとニロが現れた。ドロドロ兄弟は2人に勝負を持ちかける。もし2人が勝てばすべてのポイントを差し出すと言うが……? 同じ頃、多くの魔獣を従え優位に戦うケロリ&カムイ組の一方で、ジャズ&シュナイダー組は戦略的に他者からうばいポイントを稼いでいた。彼らの過ごした、フルフル軍曹による地獄のような特訓の日々とは……!?', '2022/11/07 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4be6d287-68bf-43a3-a218-e60aa9632a3b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ed0c7ff-4a7c-42dc-b286-9d6977aa38a7', '73c023c5-52a7-4d11-af70-f0e6cfd92378', 6, '100128741', '魔性のピュア', '他のアブノーマルクラスの生徒たちが順調にポイントを稼いでいる中、ジャングルで収穫した食材でのんきに食事を満喫する入間&リード組。入間は、久々に生き残りを意識する状況に身を置き、「サバイバル･ハイ」になっていた。いかにして生き延びるかを第一に考え、収穫祭そっちのけで生活を充実させていく2人。デビコンの思い出話にも花が咲き、楽しく盛り上がる。しかしその背後には、忍び寄るあやしい着ぐるみの姿が……!?', '2022/11/14 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e3d2d62-2cef-4a86-9f57-5586304443ac.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('24e5b947-aac4-4d18-8fbd-e6a1abccb5f9', '魔法つかいプリキュア！', '', 'hulu', 'witchy-pretty-cure', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1785099-e924-413d-80c6-45dba67a0039.png?w=331&h=447&p=t', 'hulu', 2016, 0, 1, 'FINISHED', NULL, 21506, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('0b7a9710-42e6-48d1-94fa-3fdfe55c4499', '24e5b947-aac4-4d18-8fbd-e6a1abccb5f9', 'hulu-witchy-pretty-cure-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55ede4e6-b891-4fdb-967d-375b9ac881fd.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73edc3f2-96a9-449e-a85f-d659f286e565', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 1, '100208114', '出会いはミラクルでマジカル! 魔法のプリキュア誕生!', '朝日奈みらいはもうすぐ中学2年生になる13才の女の子。ある月夜の晩、みらいは空から魔法のほうきに乗った魔法使いの女の子が落ちてくるのを目撃しました。女の子の名前はリコ。お腹が減って力が出ないというリコを助けたみらいですが、そこに怪しい男が…!', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/55ede4e6-b891-4fdb-967d-375b9ac881fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dad6a7a6-10ba-4e50-896d-ad3cb84c3bcd', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 2, '100208115', 'ワクワクの魔法学校へ! 校長先生はどこ!?', '伝説の魔法つかいプリキュアになったみらいとリコ。言葉が話せるようにモフルンとみらいを魔法学校に連れ帰ったリコは、教頭先生に普通の人間を連れてきたことを怒られ、退学されそうになります。リコをかばうため、校長先生に会おうとするみらいですが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6856442-02d9-46dd-a206-8e0ac8d07227.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e2c37b7-c19d-4583-b4ca-59a69c7c2e07', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 3, '100208116', '魔法商店街でショッピング! 目覚めるルビーの力!', 'みらいは春休みの間、魔法学校に通って魔法の勉強をすることになりました。リコとモフルンと一緒に魔法のじゅうたんに乗って、魔法商店街へ魔法の道具を買いに向かうみらいですが、そのさなか、クモの糸のようなものにリンクルストーンを奪われて…!', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/09f573e0-320b-42e0-8a63-4781087b621d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9007d925-8363-4431-a386-03e498a7cd36', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 4, '100208117', '魔法の授業スタート! ふしぎなちょうちょを探せ!', '魔法図書館。そこは校長先生でも迷子になる『知識の森』がある場所。魔法学校の補習授業で紙の蝶を追いかけているうちに、図書館に向かったみらいは、知識の森に迷い込んでしまいます。ドクロクシーの手下ガメッツが迫る中、みらいとリコは一冊の本に導かれ…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c149b0b-015e-455d-9112-d0ec0708724e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b516db7f-83f2-446f-918d-eeaed5e7c73b', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 5, '100208118', '氷の島ですれ違い!? 魔法がつなぐ友情!', '二回目の補習の授業は寒い島の中で魔法のやかんを沸かしてお茶をいれること。寒くて魔法が使えない中、押しくらまんじゅうで暖かくなることを思いつき、みらいたちの魔法は大成功。でも、魔法を上手く使えなかったリコは、みらいとケンカしてしまい…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d147d88c-e100-47d9-9687-f6c84aed91ca.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0dcecf83-878d-432e-86c8-e87f438c9c77', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 6, '100208119', '特訓! 魔法の杖! 先生はリコのお姉ちゃん!?', '補習授業は、教育実習生でリコのお姉さんでもあるリズ先生が担当。授業の内容は、魔法の杖を使い水でものを作って10秒間保つことでした。リコはお姉さんの前でいいところを見せようと、失敗ばかりした上、リズとケンカをして授業を飛び出してしまいます。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fe52019f-62ce-4d20-a10e-7105541219cd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2575b911-67a0-4550-8b01-062eb9920e41', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 7, '100208120', '人魚の里の魔法! よみがえるサファイアの想い!', '今回の補習授業は人魚の里でおこなわれ、補習内容は発声の練習。声で固く閉じたマール貝を開けることでした。貝を開けることができず苦戦するみんな。そんなとき、みらいとリコは3人の人魚の子供たちと友達になり、秘密の場所に案内してもらうことに。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/37b1a113-7130-4688-8448-d715d4a44077.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('594cb384-1f51-4ade-a76c-968f857174a1', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 8, '100208121', '魔法のほうきでGO! ペガサス親子を救え!', '今回の補習授業は、空を飛ぶペガサスと一緒に記念撮影をすることです。まだ、魔法のほうきに上手く乗ることのできないみらいも、ヤル気満々でペガサスを追いかけたのですが、誤って森の中へと落ちてしまいました。その森で、みらいとリコが見つけたものは…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/40c0dd87-4fb8-4380-a8c8-7ffd2f16be10.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f1dcfe01-39e4-4ee8-b85d-6a80576e826b', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 9, '100208122', 'さよなら魔法界!? みらいとリコの最終テスト!', 'いよいよ最後の補習授業です。その内容は相手の花を魔法で咲かせる魔法対決でした。補習を受けるみらいたち5人は一つのチームとなって、リズ先生との魔法勝負に挑みますが、次々と花を咲かされて、残るはみらいとリコだけになってしまいました。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c455799e-9138-4066-b107-62dd31f22351.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d20d4cc9-3533-4917-92e7-dff82df0747c', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 10, '100208123', 'ただいま! ナシマホウ界! ってリコはどこ?', '校長先生に次のリンクルストーンがナシマホウ界に現れると言われ、リコはみらいを追ってカタツムリニアに乗り込んだのです。駅に着いた途端、二人はリンクルストーン･トパーズを見つけます。でも、カラスがトパーズをくわえて、どこかへ飛んでいってしまい…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a510330b-1a11-4d76-a135-d15e5673f25f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb7ef1c7-65b3-4639-bca0-862e9f9594ff', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 11, '100208124', 'モフルンの初登校? ワクワクのトパーズをゲットモフ!', 'リコはみらいの家で暮らし、学校にも通うことに。でも、魔法を使うことを知られてはいけないのに、ほうきに乗って登校するところを見られたり、こっそりついてきたモフルンとはーちゃんが見つかってしまい大慌て。モフルンは甘い匂いに気がつくのですが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/caefa39d-e6d6-4fa1-afa1-356316e8d17f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c58a2077-9d5e-4302-98d3-638754ca1f1e', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 12, '100208125', '満天の星空とみらいの思い出', '今日からみらいとリコの通う中学校では授業開始です。魔法界では優等生だったリコですが、魔法界とナシマホウ界では違うこともあって、あまり上手くはいきませんでした。みらいたちとも一緒に遊ばずに、家で一人で部屋にこもって予習をするリコにみらいは…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/88385a91-e1d6-4716-9c5f-c891981fb2c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('debb9cc6-288b-4c62-9251-aa8bb4b5c535', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 13, '100208126', 'たのしいBBQ! 幸せたくさんみ～つけた!', 'キャンプ場にバーベキューをしに来たみらいとリコたち。そこには、校長先生の手紙を持ってきたリズが待っていました。みらいはワクワクしながらバーベキューの支度を楽しんでいますが、初めてのリコは便利な電化製品や魔法を使わない理由がよくわかりません。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13d9c7ed-06b8-4549-9767-8175cc178787.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b3d5eb6c-3024-49e7-84d0-6a503829214e', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 14, '100208127', 'みんな花マル! テスト大作戦!', '数学のテストが戻ってきました。みらいは赤点で再試験ですが、リコはクラスでただ一人の満点を取ります。みらいは落ち込みます。再試験のため勉強するみらいを励ましながら一緒に勉強するリコ。みらいはリコが一生懸命努力していたのを知り…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7e2630d7-ac74-45b8-adc5-f544774648c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cf0b9d4-27d0-4e73-a640-16bed724ace8', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 15, '100208128', 'ハチャメチャ大混乱! はーちゃん七変化!', 'お腹が減ったはーちゃんですが、みらいもリコもかまってくれず、仕方なく自分で、魔法で朝ご飯を出して食べました。お腹一杯になったはーちゃんですが、くしゃみをするたびに変身してしまうようです。そのまま外へ遊びに出掛け、みんなに目撃されて大騒ぎに!', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbdc711d-62d5-4880-aeb6-755ccbf0ba97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('94c473e0-7d33-4b0a-8c76-10979c7848c1', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 16, '100208129', '久しぶりっ! 補習メイトがやってきた!', '魔法界から一緒に補習を受けた魔法学校の同級生ジュン、ケイ、エミリー、さらに仕立て屋のフランソワがナシマホウ界へ遊びに来ました。さっそく町を案内するみらいとリコでしたが、みんなが魔法つかいだと知られないように気を使わなくてはならなくて大変!', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6433e3f3-afdc-4e63-8331-8f65dda8280a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('40b80f32-233e-4ed5-a865-857b0485cd37', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 17, '100208130', '水晶さんおしえて! おばあちゃんの思い出の人', '一枚の写真から、おばあちゃんが今のみらいと同じくらいの歳ごろのとき出会った不思議な男の人が今でも忘れられないという話になりました。思い出の人が気になるみらいとリコは、水晶さんに協力してもらいつつ、思い出の人を捜すため街に出かけますが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc5febd8-392b-40a2-a8b0-228c52b70500.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fd6cc8c1-098c-4c3e-a54c-13d8d9885b1e', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 18, '100208131', '魔法界再び! リンクルストーンを取り返せ!', 'ガメッツからの挑戦状が届き、みらいとリコは、奪われたガーネットを取り返すため、魔法界へと向かいます。本来の姿である魔法戦士へと変身したガメッツを前に、プリキュアは倒れてしまいます。そのとき、はーちゃんがガメッツを止めようと…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8077adf2-a2f4-49ac-8377-122d2a87511e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8158f53c-92e7-4667-a672-a28c5be5dc2d', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 19, '100208132', '探検&冒険! 魔法のとびらのナゾ!', 'プリキュアのピンチを救った、はーちゃんの不思議な力の秘密を校長先生に教えてもらおうと、みらいとリコが居なくなった校長先生を捜していると、学校を支え見下ろしている大木の頂上に校長先生にしか開けられない扉があるというので早速向かいますが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97f776ba-8d7a-4486-8f9f-762e7cc66588.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('31ac6fa8-1b0f-407b-aad6-bcb7024c84b4', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 20, '100208133', 'ドタバタでヤバスギ! 魔法界に生まれたエメラルド!', 'みらいとリコとモフルンが、校長先生のことを思い浮かべて魔法の扉を開くと、そこはドクロクシーの本拠地でした。ドクロクシーの正体は、校長先生の友だちだったクシィでした。校長先生は、今まで封印していた魔法の力を解き放ち、ドクロクシーに挑みますが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44e5c0c9-9bb9-4c44-815c-793d1d5d4402.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ddd15e5-d764-4429-ae5c-08ecb3f478d4', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 21, '100208134', 'STOP! 闇の魔法! プリキュアVSドクロクシー!', 'はーちゃんの眠るリンクルスマホンごとリンクルストーン･エメラルドを飲み込み、完全体になったドクロクシー。全てを闇で覆うドクロクシーに対して、みらいは「はーちゃんを返して!」と毅然と立ち向かいます。その姿に、リコも勇気を取り戻し…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/503b2705-09d1-461e-9418-5b2d58c23473.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5245003f-5b42-4ea6-8e77-d083f523dd17', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 22, '100208135', '芽生える新たな伝説! キュアフェリーチェ誕生!', 'リコもみらいも、どこか悩みを隠しているようです。二人とも口には出さないけど、行方不明のはーちゃんが心配だったのです。そんな二人の前に、消えたはずのヤモーが現れ、強力なヨクバールを生み出しました。ピンチに陥るプリキュアの前に現れたのは…!?', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c511439-d9db-4acb-9578-c45b85e0ef27.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e1f9df29-e1c5-4aa8-a7bf-9ea66b3761f1', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 23, '100208136', 'これからもよろしく! おかえり、はーちゃん!', '成長して、プリキュアにも変身できるようになったはーちゃん。ワクワクが止まらないはーちゃんに、みらいとリコとモフルンも大喜び。これからも4人一緒にいることを誓います。でも、魔法のほうきが上手く使えず、はーちゃんだけがはぐれてしまい…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b5f40dbe-ab54-4caa-b2cf-088852627035.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff15b8da-f04c-41e6-9648-739c208343fc', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 24, '100208137', 'ワクワクリフォーム! はーちゃんのお部屋づくり!', 'みらいの家に住むことになったはーちゃん。そこで、使っていない屋根裏部屋を、はーちゃんの部屋にリフォームすることになりました。さっそく、片付けをしようとするみらいとリコですが、はーちゃんは魔法で部屋をキレイにし、次々と家具を作り出していきます。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64655517-25eb-462d-842b-4593e6da3be7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5d15e2d4-e3b3-4d4c-9947-26843d0e7c98', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 25, '100208138', '夏だ! 海だ! 大はしゃぎ! かき氷が食べた～いっ!', 'みらいたちが海にやって来ました。クラスメイトも一緒です。海の家のかき氷が美味しいと教えてもらい楽しみにしていたのですが、製氷機が直るのを待たなくてはいけません。海岸で遊ぶみらいたちを楽しませようと、はーちゃんは次々に魔法を使いはじめ…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fc649e7-a2b6-4a2b-b76d-3f4d38c7244d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('714c7db6-4801-4fdc-8353-a6479a698dc6', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 26, '100208139', '想いはみんな一緒! はーちゃんのクッキー', 'リンクルストーン･エメラルドを狙うヤモー。はーちゃんはこのままでは、みらいとリコを危険な目に遭わせ続けると心配になります。魔法を使わない手作りのクッキーををみらいとリコに渡した翌日、はーちゃんはだまって家を出てしまい…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5600314-63cd-4726-8228-527780d825aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4f8731c-159b-490f-a267-cc003140a68a', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 27, '100208140', 'Let''sエンジョイ! 魔法学校の夏休み!', '夏休みになったので、みらいたちが魔法界を訪れると、夏祭りの準備中。ジュン、ケイ、エミリーたちとも再会します。食べ放題の学校の食堂へ案内されるみらいたちは、果物を運んできた魔法商店街のトッドに、ピーカンみかんの育ちが悪いことを聞かされます。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f9c1f139-3b99-44ed-8355-7945ab89a05a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('51f29794-224f-4817-b476-e887184e1606', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 28, '100208141', '魔法界の夏祭り! 花火よ、たかくあがれ!', '魔法学校の夏祭りで最後の打ち上げ花火の担当は、ジュン、ケイ、エミリーです。でも、花火の元になるパチパチ花が必要となり、みらい、はーちゃん、エミリーはペガサスの森へパチパチ花を探しに、残るリコたちは図書館で花を調べることになるのですが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef22ca98-6c9c-4f23-b1a7-0ef787380da6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('529151cc-6f0c-4b67-a0b0-4a05610de1e9', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 29, '100208142', '新たな魔法の物語! 主役はモフデレラ!?', '図書館で『シンデレラ』の絵本を見つけるリコ。魔法界ではシンデレラでなく魔法つかいが主役でした。その夜、みらいたちは『シンデレラ』の夢を見ます。モフルンはモフデレラになり、リコは魔法つかい。みらいとはーちゃんはねずみになっていて…!?', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2499466e-d9e8-4b54-aa64-0133ee7be9c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cc653ac2-91f6-47a3-a34c-65aef7fdb2d9', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 30, '100208143', '魔法の自由研究! が、終わらな～い!!', 'みらいたちは、ジュンたちの夏休みの自由研究を手伝うことに。ジュンはモデルにアート製作、ケイは図鑑作成、エミリーはヘアメイクの練習。それぞれが夢のため、自由研究に取り組んでいる姿に、リコは夢を見つけていないことが不安になります。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2ad7d2b-a3b5-41d1-bf4b-3e2c2088b467.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ebaded3a-13e2-43ba-9403-57adffe4f4d4', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 31, '100208144', '結晶する想い! 虹色のアレキサンドライト!!', 'ナシマホウ界に帰るみらいたちですが、ラブーの罠によって車両が見知らぬ空間に迷いこんでしまいます。ラブーは巨大化すると、みらいたちに襲いかかってきました。巨大化したラブーはとても強く、3人のプリキュアとモフルンは離ればなれになってしまい…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e74ae2a8-ff1d-4ab6-acea-bcb03c338538.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b22cb121-d174-4bf7-a250-8f812f5e6e8c', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 32, '100208145', 'ワクワクいっぱい! はーちゃんの学校生活!', 'はーちゃんは二学期からみらいとリコと同じ中学校へ通えるとあって大喜び、2時間も早く学校に着くほど。でも、それとは逆に暗い表情をしている壮太のことが気になりました。壮太はサッカー部の部長として、みんなとどう接していいのかを悩んでいたのです。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/75f11b70-c043-4b6d-ad40-f5fa333173c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('047bae22-8f80-4994-92ab-5bb44969e912', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 33, '100208146', 'すれ違う想い! 父と娘のビミョ～な1日!', 'リコのお父さんで考古学者のリアンがみらいたちの前に現れました。校長先生に頼まれてリンクルストーンや精霊のことを調べに来たのです。久しぶりに会ったリコとお父さんですが、長い間会っていなかったので、二人ともお互いにどう接したらいいか悩んでいて…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/545e383b-e03e-40ee-93aa-e5862bd2f636.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3499d7e7-353b-4bd1-af2e-a343907ea44b', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 34, '100208147', 'ドキドキ! 初恋の味はイチゴメロンパン!?', 'まゆみに好きな男の子ができたのですが、勇気がなくて自分の思いを伝えられないようです。そこでみらいたちは、まゆみの恋を応援することにします。かなからも、自分が信じていることをあきらめてはいけないと言われ、みんなから勇気をもらったまゆみは…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f7236541-bc61-46d6-9b36-8a0af7bf5f0b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fdc39242-82cd-46ff-8deb-a7b30815f97a', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 35, '100208148', '生徒会長総選挙! リコに清き一票を!', '生徒会長になるようすすめられ、やる気になったリコは選挙に立候補。活発に選挙運動をします。一方、もう一人の候補者のゆうとは、自分の気持ちを伝えるのが上手くありません。でも、彼は目に見えない場所で学校のため働いていて、リコはその姿を見かけ…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6576165-bc37-477e-ad6c-af4ed1112857.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7e48934-5ed0-49dd-811a-27e749a75b47', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 36, '100208149', 'みらいとモフルン、ときどきチクルン! って誰!?', 'オルーバの命令でプリキュアのことを調べているチクルンは、みらいたちに見つかってしまいますが、魔法界から来た妖精だと自己紹介し、みらいたちと仲良くなりました。オルーバは、モフルンが元はぬいぐるみだったことを知ってモフルンに興味を持ち…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/136809b1-5b0c-4ef2-9b45-f997e2afc40a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59b92faa-40a0-41da-843b-a4c9f2e8f686', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 37, '100208150', '魔法が決め手? 冷凍みかんのレシピ!', '校長先生は明日のお祭りの冷凍みかんづくりのため、『ぬっくい島』でピーカンみかんを収穫中で、みらいたちも協力しますが、ピーカンみかんを凍らせるには『ひゃっこい島』のアイスドラゴンのため息が必要。でも、なかなかアイスドラゴンはため息を出しません…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb8697f1-bce8-47de-9c24-ef5cc82f0023.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5473170b-ea2c-40f6-8f4e-f2850f80ead2', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 38, '100208151', '甘い? 甘くない? 魔法のかぼちゃ祭り!', '魔法商店街のお祭りで、お菓子が食べられると聞いて大喜びするみらいたち。でも、お祭りは一年に一度だけ現れるカボチャドリを誰が捕まえるのかを競うというもの。カボチャドリが持つという金の卵に、何が入っているか想像してみんなはワクワクしますが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eeb0447d-dbd8-4c2a-9abb-891fed733240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6ccb06d-908b-44a2-b7a4-824f1cca6e15', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 39, '100208152', '今日はハロウィン! み～んな笑顔になぁれ!', '今日はハロウィン。みんなが仮装して楽しむお祭りです。だから魔法つかいがいてもおかしくないと、みらいの発案で魔法学校の生徒たちを招きました。魔法界とナシマホウ界の友達が仲良くなりますが、ジュンたちがクレープ作りを手伝おうと、魔法を使って…!?', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4bee290-ad29-4cf4-8d07-ccba79c31842.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08ac5241-4edb-4e94-ac5b-d2717ecd25cc', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 40, '100208153', '愛情いっぱいのおめでとう! リコの誕生日!', 'テレビで活躍している料理研究家のリリアを見ておどろくリコ。リリアはリコのお母さんだったのです。リコの誕生会に、そのリリアが家をたずねてきました。さらにお父さんのリアンとお姉さんのリズもやって来ます。お祝いされることが苦手なリコは困った顔ですが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2c5896e2-f8f9-4aed-af25-7881aaa93886.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a720d616-b2ac-4243-9149-e40bb9c30894', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 41, '100208154', 'ジュエリーな毎日! 魔法学校へ放課後留学!', '最近、魔法界とナシマホウ界が近くなったことを知ったみらいたちは、学校が終わってから魔法学校へ通うことにします。明日は学校がお休みなので、魔法学校の寮にお泊まりすることにしたみらいたち。ジュンの部屋にケイとエミリーも合流して、お泊まり会が始まります。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b741f2a-9a48-4553-b001-d9a70a62f819.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('07ab86c9-7f23-4505-aa9f-030b4c22f596', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 42, '100208155', 'チクルンにとどけ! 想いをのせた魔法のプリン!', 'チクルンがオルーバに従う理由。それは、妖精の女王様にサボっていたことを言いつけると、おどされていたから。リンクルストーンを奪えと命令されたチクルン。プリキュアに変身しなければ、みらいたちがもう戦わないですむと思い、いけないとは知りながら…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f52a4e5d-84fe-415d-a414-aea3b7397397.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e6ccf15-f7fe-4161-8c4c-75bc01b51a29', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 43, '100208156', 'いざ妖精の里へ! あかされる魔法界のヒミツ!', '扉により妖精の里にやって来たみらいたち。そこでレジェンド女王が語った話、それはまだすべての生き物が一緒に暮らしていた時代、マザー･ラパーパにより世界は平和でした。でも、デウスマストの出現によって世界は混乱してしまったのです。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c985457-4f56-4ff4-a4d2-c9685dc57b2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f0072da0-ae19-4f23-b386-994020c43176', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 44, '100208157', 'モフルン大奮闘! みんな子供になっちゃった!?', 'オルーバの闇の魔法で、みらい、リコ、はーちゃんの3人が小さな子供になってしまいました。小さな子供になった3人は魔法も上手く使えなくなり、校長先生に連絡しました。モフルンは無事な自分が3人を助けなくてはいけないとがんばりますが…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44235888-440a-4f26-86ab-05cd06034e65.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0275895-65e6-4d33-bfb7-a39684fddd88', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 45, '100208158', '想いは時を超えて…! 友情のかたち!', '闇の魔法の本を書いたのが親友のクシィだったことから、校長先生はあまり元気がありません。校長先生を笑顔にしようと、みらいたちがイチゴメロンパンを買って帰ってくると、校長先生はバッティをはげましていました。そこへオルーバがやってきて…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/38c790d5-74bf-47da-ac71-0fc5f93e7556.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4cb1207b-001d-408b-a548-f887cde1596d', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 46, '100208159', '魔法のクリスマス! みらい、サンタになる!?', '今日はクリスマス。リコに連れられてサンタクロースに会いに行ったみらいとはーちゃんは、魔法商店街へ行きビックリ。何故ならサンタは魔法つかいのみんなだったからです。みらいたちはギックリ腰で倒れたアイザック先生の代わりにサンタのお手伝いを願い出て…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21ccbee1-def2-4edc-851b-1546b9098e3e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1e7fb1a2-04c2-4e2e-b73e-31f4f6b15717', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 47, '100208160', 'それぞれの願い! 明日はどっちだー?', '神社で初詣をするみらいたち。願い事はそれぞれ違いますが、みんなこれからも仲良く一緒にやっていこうと固く誓いました。そんなときナシマホウ界と魔法界の空は急に暗くなり、一面を闇に包んでしまいました。それはデウスマスト復活の予兆だったのです。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6df89464-85e6-456c-b2d0-042e6f4860c2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bdc8e639-7f5b-4bb2-8fb9-c1bca0c56b16', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 48, '100208161', '終わりなき混沌! デウスマストの世界!!', 'デウスマストが、世界を混沌にして一つにしてしまいました。ナシマホウ界と魔法界を元通り別々にできても、行き来できないくらい離れてしまうそうです。マザー･ラパーパの意思に守られた二つの世界を飲み込もうと迫るデウスマストに対してみらいたちは…。', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b3883e51-e350-43cd-84bf-8f12e32ef7c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9376f73a-2757-45f4-89e2-4d04cb50412c', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 49, '100208162', 'さよなら…魔法つかい! 奇跡の魔法よ、もう一度!', '終わりなき混沌･デウスマストの巨大な力に圧倒されるプリキュアたちは、真の力に目覚めたリンクルストーンによって完成したレインボーキャリッジの魔法陣で最終決戦に臨みます!!', '2025/01/02 00:00:00', 1460, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3b1556c9-8e6b-494d-8056-d9b9c0dcd5a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b69cb240-a8b5-4b43-a782-55bbf896050b', '0b7a9710-42e6-48d1-94fa-3fdfe55c4499', 50, '100208163', 'キュアップ･ラパパ! 未来もいい日になあれ!!', '【最終話】久しぶりの再会を喜ぶみらい、リコ、はーちゃん、モフルンは、お祝いに思い出のイチゴメロンパンを食べることにします。はーちゃんの魔法で出会った頃の姿に戻り、楽しくしていたのですが、突然、現れたドクロムシーにイチゴメロンパンを取られてしまい!?', '2025/01/02 00:00:00', 1430, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96c799f2-8f21-47f4-8eb9-70e289af3843.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('b732d8b2-3937-4fc3-a18a-0d1f1e1ca6ad', '魔法つかいプリキュア！', '', 'hulu', 'witchy-precure-mirai-days', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/368b4270-5d34-4687-a994-5d3c6cdd8490.png?w=331&h=447&p=t', 'hulu', 2016, 0, 1, 'FINISHED', NULL, 21506, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d6943245-2152-4484-b5fb-4da55dbfae84', 'b732d8b2-3937-4fc3-a18a-0d1f1e1ca6ad', 'hulu-witchy-precure-mirai-days-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd8ce9a9-a925-47c7-bcc9-9fd775121b9f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c72e692b-c33b-4367-9891-cab1bd2d5082', 'd6943245-2152-4484-b5fb-4da55dbfae84', 1, '100212348', '再会はミラクルでマジカル!', '朝日奈みらいはごく普通の大学生らしい日常を送る傍らで、密かに魔法で人助けをする「魔法ガール」として活動してたが、ある日、みらいが暮らす津成木町に、巨大なモンスターが出没して……?', '2025/01/15 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd8ce9a9-a925-47c7-bcc9-9fd775121b9f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e5074b3-f468-409e-b3ec-f436f36ee6a2', 'd6943245-2152-4484-b5fb-4da55dbfae84', 2, '100213058', '久しぶりの魔法界', 'アイルが残した意味深な言葉に、新たな危機の到来を察知するみらいとリコ。さらに二人は、不思議な女の子･ひすいにも出会う。彼女は花海ことはによく似ているようだが……?', '2025/01/22 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f99045fa-4f1b-47f4-ad2b-46c4fb7c6e98.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9205f470-c0f1-45ec-b9a9-8712c054376e', 'd6943245-2152-4484-b5fb-4da55dbfae84', 3, '100213817', '刻 (とき) の魔法', 'アイルが言っていた時刻にみらいが見たのは、キュアミラクルとキュアマジカルが荒野に倒れ、ひすいがアイルに捕らわれているイメージだった――。みらいとリコは、それが未来の出来事なのかもしれないと考える。', '2025/01/29 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69df6548-d4fa-4c28-9247-f5e3958015ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55cd0216-acfc-4b48-9efd-69c35a4d452b', 'd6943245-2152-4484-b5fb-4da55dbfae84', 4, '100214568', 'ひすいの秘密', 'アイルの企みを阻み、ひすいを守ろうと改めて決心したみらいとリコ。みらいが見た、本棚の前に立つアイルのイメージを手掛かりに、彼の居場所を探ることに。そんなとき、魔法ガールへの依頼も届き……?', '2025/02/05 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a0a7d6ab-fc2b-453b-804d-8aa1affc7e0c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b700e4ff-6369-4b25-8775-933303556ffa', 'd6943245-2152-4484-b5fb-4da55dbfae84', 5, '100215416', '流れ行く歳月', '普通では考えられないようなスピードで、日々どんどん大きくなっていくひすい。周囲の人に怪しまれないよう、みらいとリコはひすいを連れて、リコが借りたアパートに引っ越すことにする。', '2025/02/12 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6980eba3-01a9-4515-a85f-0b1603eca45d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a0139c89-cc08-41a7-9e0d-1dd20a3df0af', 'd6943245-2152-4484-b5fb-4da55dbfae84', 6, '100216847', '真の目的', 'みらいとリコ、そしてモフルンが見た不吉なイメージは、なんと明日実現するという。みらいたちはその未来を変えるため、ひすいをナシマホウ界に残して、二人で魔法界へ行くことにする。', '2025/02/19 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50fa1e34-0c8e-476c-a48c-cd2805f20476.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5c5e146d-b407-47fe-9ae0-bf098d383c5c', 'd6943245-2152-4484-b5fb-4da55dbfae84', 7, '100217968', '刻 (とき) をつかさどるもの', '姿を露わにした刻の魔獣クロノウスト。その力によって石化したアイル。そして、ことはに姿を変えて消えてしまったひすい――。疑問だらけのみらいたちは、ことはにいったい何があったのかを質問する。', '2025/02/26 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/281acb23-0c0c-402e-9e21-8ce6058cc3cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d434ed56-cf28-4503-a74c-f308f8988baf', 'd6943245-2152-4484-b5fb-4da55dbfae84', 8, '100218523', 'ことはとひすい', '魔法界での調査の結果、アイルのバックボーンが少しずつ明らかになってきた。さらにみらいたちは、妖精の里の使いとしてやって来たチクルンから、ことはとひすいの関係について知らされる――。', '2025/03/05 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/be181800-aefc-4eb2-b017-dc6125485730.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dc5d0f3b-5bfe-4285-b2ce-7b75b89029ea', 'd6943245-2152-4484-b5fb-4da55dbfae84', 9, '100219529', 'それぞれの世界', '壮太やさらだけでなく、津成木町の住人たちを次々に襲い、石像に変えていくクロノウストの影。事情を知らない人々の間でも、それは「謎の失踪事件」として少しずつ話題になっていた……。', '2025/03/12 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e98aaf62-f000-4d6e-87f1-84d89a7d8d0e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b62e2dcd-3d11-4536-978b-8143267572bf', 'd6943245-2152-4484-b5fb-4da55dbfae84', 10, '100220444', '刻 (とき) を追って', '増殖したクロノウストの影によって、石化された魔法界の人々。さらに、ジュンやケイ、エミリーまでもが石にされていたことを知ったみらいたちは、次なる被害を防ぐべく、再びナシマホウ界へ戻ることにする。', '2025/03/19 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7dcb9619-e4e4-4209-85d3-2438a2e4870f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1a37a19f-4dc8-467f-aaff-67b63b6feb86', 'd6943245-2152-4484-b5fb-4da55dbfae84', 11, '100221424', 'みらいの決断', 'クロノウストの意味深な言葉と共に、ナシマホウ界上空には巨大なコクーン出現した。世界中の人々が恐怖と混乱に包まれる中、プリキュアはクロノウストの野望を止めることができるのか?', '2025/03/26 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/42d9551b-fab4-4244-ae90-5dc88eceb12f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d8ea5ad9-596c-4b69-ba4a-4a32f4020570', 'd6943245-2152-4484-b5fb-4da55dbfae84', 12, '100222088', '進むべき未来', '【シーズン1 最終話】過去から脱出するのと引き換えに記憶を失ってしまったみらい、リコ、ことは、モフルン。互いのことを思い出せないまま、記憶の中を漂うみらいたち。そこで彼女たちが見たものは……?', '2025/04/02 02:30:00', 1419, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01d56244-7852-4d20-a518-8d7ed13da005.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('008e0f52-4411-4433-a8cf-2b857d6a6c7a', '魔法科高校の優等生', '', 'hulu', 'the-honor-at-magic-high-school', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c839da00-2add-4386-ad5c-96c11f3f2058.jpg?w=331&h=447&p=t', 'hulu', 2021, 2, 1, 'FINISHED', NULL, 127688, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a5d9c0ad-91f1-45f5-af62-579a0766dd99', '008e0f52-4411-4433-a8cf-2b857d6a6c7a', 'hulu-the-honor-at-magic-high-school-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68bdbe02-043d-4f12-a893-1d1b4a361271.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b5414ca-0a04-444e-b5a1-e256b202ad84', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 1, '100086187', '一生大事にします', '2095年3月25日。司波深雪は15歳の誕生日に、兄の達也と横浜へショッピングに向かう。デート気分を満喫する深雪は、達也からのサプライズなどもあり上機嫌。そんな中、二人の実家である十師族･四葉家から連絡が入り、達也は呼び出されてしまう。一人達也の帰りを待つ深雪。だがその時、火災警報が鳴り響く。魔法による犯罪の気配を察知した深雪は単身、火災の中心へと向かっていく。', '2021/07/08 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68bdbe02-043d-4f12-a893-1d1b4a361271.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6e3d14a-b8e6-44ee-a5d8-cb0cbb37098d', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 2, '100086885', 'ご一緒してもいいですか?', '第一高校に入学した光井ほのかと北山雫。入試の時から深雪に憧れていたほのかは、図らずも深雪と友人になり大喜び。しかし、同じく優秀な魔法師として注目していた達也が、なぜか劣等生扱いの二科生になっていたと知り、「一科生と二科生の違いって何なんだろう」と疑問を抱く。そんな中、一科生と二科生の揉め事にほのかたちも巻き込まれてしまう。ほのかは禁止されてると知りつつも、魔法で騒ぎを鎮めようとするが……。', '2021/07/15 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/feb577fa-722c-4b61-bf69-cd6cb8aefe06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f94d7006-27a2-4bc7-84b1-7ff59fff6888', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 3, '100087177', '少女探偵団、始動よ!', '第一高校は新入部員勧誘週間の真っ最中。成績優秀なほのかと雫は各部から狙われ、揉みくちゃに。そこに現れた赤毛の美少女･エイミィが二人を救出。三人は友達になる。そんなある日の下校時、ほのかたちは風紀委員となった達也が何者かに襲われるところを目撃。事件と達也に興味津々なエイミィは、自ら犯人捜索に乗り出す。ほのかと雫も巻き込まれ、なぜか少女探偵団が結成されてしまう。', '2021/07/22 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21ed001f-cbc9-4d6c-ab40-ad87e15e5484.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ceb121fb-f666-460b-983a-9d8fd8225c82', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 4, '100087527', '友達', '達也は剣道部の壬生たちの言動から、自分を襲った者の正体を反魔法国際政治団体･ブランシュと突き止める。一科生と二科生の分断を図ろうとするブランシュの行動に憤る深雪。一方、ほのかたち少女探偵団は犯人を剣道部の主将･司甲と特定し、尾行を開始するが、気づかれて謎のバイク集団に襲われてしまう。魔法で対抗する三人だったが、魔法を無効化するキャスト･ジャミングを使われて大ピンチに。', '2021/07/29 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05bb03ca-9802-4f70-94d3-1633461f63d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c911ccbf-2d70-486b-a953-047afcad404b', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 5, '100087975', '手出しはさせません', '有志同盟との討論会の最中、ブランシュの戦闘部隊が第一高校に侵入。ほのかと雫も襲われそうになるが、魔法で応戦。深雪たちの活躍もあり、大事には至らなかったが、ほのかたちはブランシュのやり方に憤りを隠せない。深雪と達也はブランシュを完全に叩き潰すべく、エリカたちと共に敵のアジトへ乗り込む。魔法師を化け物と呼び、その存在を認めないブランシュの戦闘員たちに対し、深雪の恐るべき魔法が放たれる。', '2021/08/05 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d14c999e-cca7-4597-80cf-71ac5da87514.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5bfeea38-e03d-41f4-b038-5ae2b8691359', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 6, '100088570', '九校戦、開幕です', '全国魔法科高校親善魔法競技大会、通称「九校戦」。今年は一高の3連覇がかかっているため、真由美たち最強世代は気合いが入っている。一方、第三高校は一年生の一色愛梨･十七夜栞･四十九院沓子らを筆頭に、打倒一高に燃えていた。かくして九校戦が開幕。一高は順調にポイントを挙げていくが、バトル･ボードの競技中に優勝候補の摩利が事故に巻き込まれて負傷。総合優勝を狙う真由美は、摩利が出場する予定だったミラージ･バットの代役に、深雪を指名する。', '2021/08/12 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f26818e-ad19-4e32-a569-494dc04b1f8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4db21f97-3759-4494-ba7c-c3cda3544af6', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 7, '100089113', '数学的連鎖 (アリスマティック･チェイン)', '九校戦は新人戦が始まる。雫はスピード･シューティングで栞と対戦。栞はスパコン並みの演算能力を駆使した魔法「アリスマティック･チェイン」を使用。落ちぶれた家を捨てて愛梨と共に歩む決意をした栞の執念が、雫を追い詰めていく。客席で見守るほのかたちも気が気でない様子。だが深雪は一人、余裕の笑み。「雫の担当技術者を誰だと思っているの?」。その言葉通り、技術者の達也には秘策があった。', '2021/08/19 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d5a205d7-9d5e-4dc6-ad8a-b9036fc74357.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72f8bf29-1752-415b-b874-0fa8f91a12b0', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 8, '100089650', '氷熱地獄 (インフェルノ)', '新人戦二日目。愛梨はエクレール (稲妻) の呼び名の通り、超高速の移動魔法を駆使してクラウド･ボールを制覇。復活した栞もアイス･ピラーズ･ブレイクで敵を圧倒。三高と一高の差が徐々に詰まっていく中、遂に深雪のピラーズ･ブレイク初戦が始まる。その圧倒的な魔法力に観客もライバル校も慄然。更に同じ競技に出場するエイミィまで圧倒されてしまう。そんなエイミィの次の対戦相手は、栞だった。', '2021/08/26 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bafd9b1e-3f76-4c2b-ba7f-3ff5c629ea41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f4f97e7c-2b6c-4273-be6b-135e827654e6', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 9, '100090161', 'あなたがいたから', 'エイミィvs栞の試合開始。エイミィは一高の上位独占を目指し、予選と同じ戦法で栞の氷柱を倒していく。だが栞も対策済みだった。次第に追い詰められていくエイミィ。一方、ほのかは沓子とのバトル･ボード決勝戦。ほのかは得意の光魔法と、光のエレメンツとしての眼を使い、沓子の仕掛けた古式魔法のトラップを次々とクリアしていく。引き離される沓子。だが、彼女にはまだ奥の手があった。', '2021/09/02 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/46c22393-3a2c-4144-9189-02cdb2e46ac9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3778d9a4-5664-421f-848d-ecc4bd48bb0e', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 10, '100091160', '負けたくない', '深雪と雫の対戦の時が迫る。優れた魔法師としての深雪との対戦を願っていた雫は、本気で彼女に勝つために達也と共に策を練り、試合に臨む。そんな雫の覚悟を知った深雪も、全力で彼女に挑む決意をする。超満員の観客が見守る中、アイス･ピラーズ･ブレイク決勝が始まる。雫は得意の振動魔法で攻めるが、深雪には届かない。誰もが諦めかけたその時、雫は遂に秘策を投入。その技に深雪は驚愕する。', '2021/09/09 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/217072b2-a048-4758-ab57-f09ce30adf57.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8c0ff1e2-c88c-47a6-9333-453210ae529b', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 11, '100091727', 'お兄様、ご武運を', '負傷した森崎たちに代わり、達也･レオ･幹比古がモノリス･コード新人戦に出場することになった。深雪は、妨害工作が達也たちにも及ぶのではと危惧。すると、ほのかたち一年女子は新人戦でお世話になった達也のためにと一致団結。モノリス･コードのステージのチェックや会場の監視などをし、達也たちを守ろうとする。深雪たちの行動もあって何事も無く試合が進むが、ステージの異常にいち早く気づく者がいた。', '2021/09/16 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cdb37df7-fc3d-436b-a253-a215a2ddadd8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('005876a6-10ef-4025-a45c-c0dae86a6563', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 12, '100092025', '飛びます!', 'ミラージ･バット本戦当日。深雪は一高の総合優勝に向けて気を引き締める。一方、愛梨は師族間の権力争いに辟易しつつも、水尾とのワン･ツーフィニッシュを誓う。そんな中、試合中に一高の小早川がまたしても事故に遭遇。達也がCADへの細工を看破し、深雪には影響はなかったが、一高の選手は深雪だけになってしまう。負けられない試合、負けたくない試合に深雪は、達也にある魔法の使用を申し出る。', '2021/09/23 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1a2769ce-fddf-4489-bd62-2eae70b8ea97.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a1d89784-e950-4b73-8916-7e05b7211ae0', 'a5d9c0ad-91f1-45f5-af62-579a0766dd99', 13, '100092626', 'ゆずれない想い', '【シーズン1 最終話】ミラージ･バット本戦決勝。全選手が飛行魔法を使う中、一日の長のある深雪がポイントを挙げていく。他の選手たちは慣れない飛行魔法で次々と離脱していくが、愛梨だけは諦めない。急ごしらえの飛行魔法に、得意の跳躍魔法と高速移動、持てる力の全てを駆使して深雪に戦いを挑む。その勇敢な姿に深雪は驚くが、同時に「負けられない」との思いを強くする。深雪vs愛梨、全力同士の激突。果たして勝者は――!?', '2021/09/30 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/29a0eda7-467a-4a4a-875a-0aac4c9d2181.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2b3be307-94f5-4cfc-bd44-4813925715e0', '魔法科高校の劣等生', '', 'hulu', 'the-irregular-at-magic-high-school', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f19c1e4e-9b4b-4fbd-8201-e79060e6f9af.jpg?w=331&h=447&p=t', 'hulu', 2014, 1, 1, 'FINISHED', NULL, 20458, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fbcd63e4-36d0-4174-9454-b40dcd1254b8', '2b3be307-94f5-4cfc-bd44-4813925715e0', 'hulu-the-irregular-at-magic-high-school-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/574cbab2-7ccb-495c-9cda-0babb3c5dbdb.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c730818-91f6-4c74-9ebd-3d4208601781', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 1, '100001254', '入学編 I', '西暦2095年―魔法が現実の技術として確立し、魔法師の育成が国策となった時代。国立魔法大学付属第一高校に対照的な兄妹が入学した。主席入学を果たした司波深雪は成績優秀な『一科生』。ある欠陥を抱えた兄の司波達也は『一科生』の補欠『二科生』に所属する。入学直後から、才能容姿ともに完璧な深雪には多くの取り巻きができるが、深雪が心から慕うのは達也のみ。そのせいで達也は一科生から敵視されるようになり…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/574cbab2-7ccb-495c-9cda-0babb3c5dbdb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f89a19b4-93c1-4576-98ab-16d1468e9892', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 2, '100001255', '入学編 II', '深雪を巡る対立は、達也の機転で大事にならずにすんだものの、一科生と二科生の間に横たわる差別意識を浮き上がらせる結果となった。翌日、生徒会長の七草真由美から生徒会に勧誘された深雪は、入試のペーパーテストで一位を取った達也こそ役員にふさわしいと提案する。しかし、生徒会役員は一科生から選ぶという規則があり、深雪の願いはかなえられない。すると、風紀委員長の渡辺摩利が達也をスカウトすると言い出す。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de4444f0-99f9-4f3d-8f74-888c0172a68c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('470194ed-58ec-4eea-b5d4-2325b8f45c0d', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 3, '100001256', '入学編 III', '生徒会副会長の服部刑部との模擬戦に勝ったことで、達也の実力が証明され、風紀委員会入りが決定した。二科生が風紀委員になるのは前代未聞であり、今後起こるであろう各方面からの反発を予想し、さすがに気が重くなる達也。しかし、服部を倒した実績は実力主義者である風紀委員の多くから認められ、歓迎される。それから間もなくして、風紀委員会にとって最初の山場となる新入生部員勧誘週間がやってきた。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1028c9aa-2bd9-495e-a270-e0073d3cda90.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eed16999-8dca-4bd7-899e-8b1aacda6fe8', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 4, '100001257', '入学編 IV', '部員勧誘演武の場で、剣道部の壬生紗耶香と剣道部の桐原武明が衝突。エース同士の争いは両部の乱闘にまで発展したものの、達也がケガ人を出すことなく騒動を収めた。達也の活躍はすぐに広まり、有名になると同時に何者かによる嫌がらせを受けるようになる。ようやく勧誘週間が終わった折、紗耶香から呼び出された達也は剣道部に勧誘される。丁重に、かつ即座に断った達也に対し、紗耶香は二科生の待遇への憤りを打ち明ける。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05ac5491-67b0-4a47-ab32-a7debe28e044.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ee1e381-44cc-459f-85f3-ed3b7c3bf5ac', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 5, '100001258', '入学編 V', '二科生の待遇改善を求める“学内の差別撤廃を目指す有志同盟”が放送室を占拠した。彼らは差別撤廃を求めるが、達也や部活連の会頭･十文字克人によって占拠は失敗。真由美から公開討論会を提案され、いったんは解散する。翌日、約束の討論会が開催された。差別ではなく、差別意識の克服を訴える真由美の主張に、生徒たちはみな拍手を送る。ところが、そこに同盟を陰で操る政治結社“ブランシュ”が奇襲をかけてきて…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/faf18601-0f24-45b6-8eb5-ba88e475a36b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2e11a51-d5ca-4a84-8d82-5508e1ab3b6b', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 6, '100001259', '入学編 VI', '生徒会や風紀委員の活躍によって、ブランシュの襲撃は速やかに鎮圧されていく。敵の情報を得た達也は、深雪たちとともにブランシュが狙っているという図書館へ急ぐ。 同じころ、図書館にある特別閲覧室では、テロリストが魔法大学の所蔵する機密文献にハッキングを仕掛けていた。同盟のリーダーである司甲から、彼らの手引きを命じられた紗耶香。言いつけに従いながらも、明らかな犯罪行為を前に心中は複雑で…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b3f6bbc-5340-4114-8fb5-d4f055d0bbfb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b957ef75-b929-44bf-95ff-ad6fbb704f05', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 7, '100001260', '入学編 VII', '紗耶香は催眠術によって過去の記憶を改ざんされ、ブランシュに利用されていた。達也は自分と深雪の日常を損なおうとするものすべて駆除すべく、ブランシュを叩き潰そうとする。敵のアジトに向かう達也に、深雪、エリカ、レオ、十文字、そして紗耶香を利用されたことに憤る桐原まで同行するという。達也の指揮の下、アジトに乗り込む一同。そこには武装したブランシュのメンバーとそのリーダー･司一が待ち構えていた。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21b68af6-a525-4764-9acb-b5945b23f4e2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6f48a0da-36d8-4408-bcfa-76f22aa00dd0', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 8, '100001261', '九校戦編 I', '全国の魔法大学付属高校が、年に一度スポーツ系の魔法を競い合う“九校戦”の時期が近づいてきた。エンジニアの人材不足に頭を悩ませていた真由美は、CADの知識に長け、調整もできるという達也に注目。エンジニアとして、二科生では初となる九校戦メンバーに推薦する。しかし、一科生の選手やエンジニアたちの一部から不満の声が上がったため、真由美はみんなの前で、達也の実力を証明しようと提案する。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b75f18d5-a376-4261-9510-e777f6d53b56.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ff9315ea-f6e8-4fe7-b1ed-e173cdf68714', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 9, '100001262', '九校戦編 II', 'エンジニアとして正式に九校戦メンバーに加わった達也。九校戦発足式が終わり、本格的に準備が始まると、深雪や光井ほのか、北山雫ら担当する選手たちとともに、CADの調整や訓練を開始する。九校戦に向けて校内が慌ただしくなる中、達也の同級生･柴田美月は、人気のない放課後の校舎で不自然な霊子放射光を見つける。気になった美月は、発生源の実験棟へ足を向けると、そこでは同級生の吉田幹比古が精霊魔法の訓練をしていて…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a0b52ff-0752-409f-9ea7-02544769c3ef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b8a19a07-e156-4c4e-880a-529bcd265749', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 10, '100001263', '九校戦編 III', '九校戦の会場に向かう途中、対向車線を走る車がガード壁に激突。宙を舞って一高生の乗ったバスに突っ込んできた。慌てた一高生たちが無秩序に魔法を発動したせいで、サイオンの嵐が起き、まともに魔法が効果を発揮しなくなってしまう。それでも、達也のひそかな機転、十文字や深雪たちの活躍により、バスは被害をまぬがれた。特殊な知覚を有する達也は、車の動きに魔法の痕跡を発見し、事故は何者かが故意に仕掛けたものだと気づく。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb850ef4-3c47-487d-8ea2-66fedd148f41.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d6235dec-0776-4e19-ae17-5c9db5dea36f', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 11, '100001264', '九校戦編 IV', '九校戦前夜、幹比古は生徒の宿舎に侵入した不審者を察知。精霊魔法で捕らえようと忍び寄るも、相手に気づかれてしまう。それでも達也の援護に助けられ、幹比古は侵入者の無力化に成功する。そこで、達也から術式に無駄があると指摘された幹比古は激しく動揺。吉田家が長年に渡って改良してきた技を、一度見ただけで理解したという達也に驚愕する。そして翌日、この一件は伏せられたまま九校戦の幕が上がる。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9099b15c-3a99-444e-9ef7-8271cd14d7d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('16f67005-2ffd-4126-a454-7f5e3eef1dc5', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 12, '100001265', '九校戦編 V', '大会3日目、バトル･ボード準決勝に進出した摩利は、その第一試合で“海の七高”と呼ばれる強豪校と対決する。出だしからリードするが、鋭角コーナーにさしかかったところでアクシデントが発生。制御不能に陥って突っ込んできた七高選手を受け止めた摩利は、怪我を負って棄権を余儀なくされる。この事故が人為的なものだと推測した達也は、幹比古に協力を要請。摩利が巻き込まれた現象は精霊魔法で起こせると確認する。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ce2c4098-6b4e-4cdd-abb0-1889ed91c3be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba0c7cf7-801d-4a22-8663-dec2cea81c17', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 13, '100001266', '九校戦編 VI', '達也が調整を担当した一年生女子選手が、スピードシューティングで一位から三位までを独占した。その中の一人、雫が使用した魔法は新種魔法と認められ、魔法の百科事典“インデックス”への記録が打診される。かつてない快挙に真由美たちは快哉するが、開発者の達也は迷わず辞退。雫を登録するよう勧める。一方、三高のエース･一条は、相棒の吉祥寺とともに、一高に多大な戦果をもたらしている謎のエンジニアに警戒を強め…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6247165c-d6ca-4588-8d18-652184a7a8d9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f464dba-d35a-477c-919e-c49287f85a0d', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 14, '100001267', '九校戦編 VII', '吉祥寺と一条が、達也に宣戦布告をしてきた。彼らは新人戦のモノリス･コードに出場すると宣言して達也を挑発するが、そっけない態度で一蹴されてしまう。そんな幕間劇を挟みながら競技は進み、一高は首位を独走。新人戦ピラーズ･ブレイク決勝戦は、深雪対雫という一高生同士の戦いとなる。試合開始直後、深雪の放った“氷炎地獄”の熱波が雫のエリアを支配する。それでも雫は冷静に、達也から授けられた作戦を開始する。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/385133ed-bdb1-45f9-9f7f-141810f2835d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d79a77d-d010-472a-b59b-492e899e5088', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 15, '100001268', '九校戦編 VIII', '一高対四高の新人戦モノリス･コードで一高選手全員が重傷を負った。運営委員会は四高に悪質なルール違反があると判定し、残りの試合を翌日に延期する。真由美に代わりの選手として指名された達也は、レオと幹比古をメンバーに加え、一晩でできる限りの準備を整える。翌日、障害物の多い森林ステージで一高対二高の試合が幕を開けた。達也の戦いぶりを観戦していた吉祥寺は、達也が繰り出した魔法に気づいて驚愕する。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/263ef16b-e52f-4d1a-912c-53608d3a5c7d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('25c7f03e-d44b-4692-bb0d-580987317a91', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 16, '100001269', '九校戦編 IX', 'モノリス･コードを勝ち進んだ達也たちは、一条率いる三高と激突。レオと幹比古は、達也が吉祥寺に対抗するため考案したデバイスを用いて善戦し、強豪校相手に激しい戦いを展開する。一方、達也は一条が次々と撃ち出す圧縮空気弾を、術式解体で打ち落としながら前進。体術も駆使してあとわずかの距離まで迫る。焦った一条は、レギュレーションを超えた威力をもつ圧縮空気弾を連射してしまう。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a29a9ef-20fd-47c8-937f-c607f4678232.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('246c44a1-9615-4483-8c56-225519573249', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 17, '100001270', '九校戦編 X', '九校戦九日目、ミラージ･バット本戦第一試合は、一高の総合優勝がかかった大事な試合。ところが、一高選手の小早川が高所から転落してリタイアしてしまう。警戒して試合を観ていたという美月の話から、達也は事故の仕掛けを推察するが、運営委員会は事故と判断。九校戦は中断されず、深雪の試合の時が迫る。担当エンジニアの達也は、選手用CADのチェックを受けるべく、大会委員のテントに赴くが…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b6fff43-5cf3-4008-86f0-ecde23d38218.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f47f3165-e872-49b1-aa34-db4c6a18b80c', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 18, '100001271', '九校戦編 XI', '深雪がミラージ･バットで優勝したことで、最終日を待たずして一高の総合優勝が確定する。真由美たちが一足早く勝利を祝う一方で、達也は横浜市内へと向かっていた。行き先は一連の事件を引き起こした国際犯罪シンジケート･無頭竜の拠点。日常では決して表に出すことのない能力を使い、深雪に危害を与えようとした幹部たちを消し去る。そして迎えた九校戦最終日。最後の種目、モノリス･コード本戦決勝トーナメントが開催される。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16b03136-198b-4314-9b1d-3a7bf8c3c966.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82976316-597d-4138-bd22-dc9ccec98402', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 19, '100001272', '横浜騒乱編 I', '二学期になり、三年生が委員会や部活動を引退。生徒会も会長があずさ、副会長は深雪の新体制が始動する。一方、達也は、論文コンペの一高代表メンバーに加わり、鈴音と五十里に協力するよう頼まれる。最初は断ろうとした達也だが、鈴音の論文のテーマが研究中の「重力制御による魔法式熱核融合炉」と知って参加。さらに、義母の小百合から聖遺物 (レリック) の解析も引き受ける。だが、この聖遺物を大亜連合が狙っていて…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d082d7ca-eb03-43a6-9e31-131d2352e7d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4dae1127-a7f9-41e3-9431-a7bc83bd78f5', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 20, '100001273', '横浜騒乱編 II', '達也の自宅にハッキングが仕掛けられた。達也は魔法コンペの研究が狙われているのではと警戒。摩利もまた、論文が産学スパイの標的になることを懸念し、鈴音たちに警備をつけることに。達也たちの予測は的中し、彼らを尾行する者や、奇妙な術式で校内に探りを入れる者たちが現れる。同じころ、エリカの兄･千葉寿和は横浜や横須賀で起きた密入国事件を調査していた。その過程で、思いがけない人物から協力を要請される。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a139a802-81b5-4981-a96f-4364f527d97c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('923879ec-4e8e-4eb0-be30-bff535be0aea', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 21, '100001274', '横浜騒乱編 III', '論文コンペの準備が進む中、紗耶香が実験機の傍にいる不審な少女を発見。エリカたちの協力を受け、その少女･平河千秋を捕まえた。花音が事情を聞いたところ、千秋の動機は八つ当たりともいえる達也個人への恨みだった。パスワードブレイカーという違法の品を持っていたことから、黒幕の存在は明らかであったが、達也は想定の範囲と意に介さない。一方、千秋の事件がおとりだと察したエリカは、レオとともに独自に動き出す。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e041b60-d968-4480-bc17-2abdd78ebd3a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5fed6daa-978e-45d9-a660-90c000250395', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 22, '100001275', '横浜騒乱編 IV', '一高のロボット研究部で、論文コンペ用のプログラムをデバックしている最中、達也は不意に眠気に襲われる。睡眠ガスを流し込んで侵入してきたのは鈴音とコンペ出場を競った一科生･関本勲。コンペのプログラムを盗もうとするが、異変を察して駆けつけた花音と眠ったフリをしていた達也に取り押さえられる。一方、千秋が保護されている病院を訪れた摩利と恋人の千葉修次は、大亜連合の陳祥山が差し向けた刺客･呂剛虎と遭遇する。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c0621304-9323-48cc-b262-390e8df26a5f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('56f5b4b9-6a8c-489d-898f-713f1a0c7388', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 23, '100001276', '横浜騒乱編 V', '呂をはじめ、大亜連合のスパイたちが捕らえられたことで事件は解決したかに思われた。それでも、エリカたちは論文コンペの警備を達也に申し出て、事件の調査にあたった独立魔装大隊少尉･藤林もまた寿和に警戒を促す。それぞれの思惑が錯綜する中、ついに論文コンペ開催の日がやってきた。一高の発表が始まる中、全国から集まった魔法関係者、そして魔法協会関東支部を狙い、大亜連合の特殊工作部隊が作戦を開始する。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e69325cc-66f4-44ad-a63f-6e746d343d94.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('816b60dc-da12-48ca-9d90-df0387191c27', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 24, '100001277', '横浜騒乱編 VI', '横浜の各地に次々と大亜連合特殊工作部隊が姿を現し、制圧を開始した。論文コンペ会場も標的となったが、達也がテロリストを撃退。雫の提案を受けてVIP会議室の端末で情報を得たところ、敵の勢力は予想以上に大きいことが判明する。避難する前にデモ機のデータを処分しようとした達也たちは、同じ考えの真由美や十文字たちと合流。今後の方針を話し合う一同の前に、思いがけない人物がやってきて…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d62ab1c6-99f9-4134-9fd7-e25b9afa21a1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('236a8f1a-898b-41d2-aa96-8e66d9d84cfe', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 25, '100001278', '横浜騒乱編 VII', '横浜中が戦場と化す中、魔法科高校の生徒たちはテロリストを相手に奮戦。十師族としての務めを果たさんと、十文字は魔法協会支部へ向かい、将輝は義勇軍に参加する。達也を独立魔装大隊に送り出した深雪は、真由美や一般市民とともに避難するが、直立戦車にシェルターへつながる入り口を破壊されてしまう。脱出用ヘリが到着するまでの間、人々をテロリストから守るべく、深雪たちは二手にわかれて撃退に乗り出す。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/97278999-5dbd-4eb5-8519-25b5dd6cffd6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a525c04-4e45-461d-8d6c-9c22b2282b5f', 'fbcd63e4-36d0-4174-9454-b40dcd1254b8', 26, '100001279', '横浜騒乱編 VIII', '独立魔装大隊が組織した達也たち飛行兵部隊により、テロリストの部隊は次々と殲滅。さらに「分解」と「再成」という己の能力を存分に使って戦う達也の姿に、敵兵の間には激しい動揺が走る。同じころ、深雪たちは達也の助けによって全員無事にヘリに乗り込んでいた。そのまま横浜を脱出しようとした深雪たちだが、魔法協会支部の危機を知って進路を変更。支部があるベイヒルズタワー屋上には、脱走した呂剛虎が待ち構えていて…。', '2020/06/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e444c920-4020-416a-80b5-72e348a6faa5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('e942d028-7be8-42d2-8e8e-a48a8a8f778f', '魔法科高校の劣等生', '', 'hulu', 'the-irregular-at-magic-high-school-3', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6c5c9556-c3fa-43a1-b050-4847b810af2c.jpg?w=331&h=447&p=t', 'hulu', 2014, 1, 1, 'FINISHED', NULL, 20458, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('3bd00d2e-8797-4214-8ba4-039e89433319', 'e942d028-7be8-42d2-8e8e-a48a8a8f778f', 'hulu-the-irregular-at-magic-high-school-3-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/218cdd5a-d0fe-4016-bef4-6c3c4d20b129.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0928a072-1aeb-4043-8279-033377da8ffe', '3bd00d2e-8797-4214-8ba4-039e89433319', 1, '100180362', 'ダブルセブン編Ⅰ', '2096年4月を向かえ、二年生に進級した達也の身の回りには色々な変化があった。達也と美月は新設された魔法工学科に転科。幹比古は二科から一科へと転科した。また達也と深雪は四葉本家から使用人として使わされた水波と同居することになり、三人での生活が始まった。今年こそ平穏な学生生活を、と願って登校する達也だが、新入生は七草家の双子である香澄･泉美と、新入生総代で七草家に対抗意識を持つ七宝琢磨と、一癖も二癖もある顔ぶればかりだった……。', '2024/04/10 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/218cdd5a-d0fe-4016-bef4-6c3c4d20b129.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59c10d74-1ab0-4a80-8167-2e3be1e0470c', '3bd00d2e-8797-4214-8ba4-039e89433319', 2, '100181739', 'ダブルセブン編 II', '入学式が終わり、今年も各クラブによる新入生への勧誘活動が始まった。新入生を巡って睨み合いを始めたロボ研とバイク部の間に、風紀委員の香澄と、部活連執行部の七宝が仲裁に入る。だがどちらが主導権を握るかで言い争いを始め、ついに一触即発の事態に陥ってしまう。一方、七草家の当主である弘一は、USNAの人間主義者がマスコミ工作を始めたことを利用し、四葉家の力を削ごうと画策していた。', '2024/04/17 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6eafbaa4-eae4-4fcb-8b72-c83f53800bf5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('71c4121b-0a79-487e-a92b-c13b848766fb', '3bd00d2e-8797-4214-8ba4-039e89433319', 3, '100182357', 'ダブルセブン編 III', '反魔法主義者の神田議員が、マスコミを引き連れて第一高校を視察に訪れるという情報が入った。少しでも軍事に関係することがあれば、マスコミに針小棒大に騒ぎ立てさせ、魔法科高校が軍事教育の場と化していると主張するつもりだという。そこで達也は生徒たちで、常駐型重力制御魔法式熱核融合炉＝恒星炉の実験を行なうことを提案。第一高校の魔法教育が、魔法によってエネルギー問題を解消し、人類の平和に貢献していることを主張しようとする。', '2024/04/24 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f4af950c-d29f-4e13-b95d-0b10fa67e5a3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('85c1b46b-4d5c-4423-b189-12231bea6784', '3bd00d2e-8797-4214-8ba4-039e89433319', 4, '100183223', 'ダブルセブン編 IV', '恒星炉の実験は見事成功し、ニュースでもその成功が大々的に報道された。だが父親から神田議員の件は七草家が対処すると聞かされていた七宝は、七草家が達也を利用して自分たちの功績にしたと思い込み、通りがかった香澄に鬱憤を叩きつけてしまう。香澄も自分の家に対する侮辱を看過できず、二人は魔法を使った戦闘準備に入るが、その現場を風紀委員に発見され、拘束される。この二人の遺恨を無くすために、達也は試合で勝敗をつけることを提案する。', '2024/05/01 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/42f326bb-feb8-439a-9d42-ef8695c11550.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6946108e-12eb-434e-9c74-3e8d0b6f37a2', '3bd00d2e-8797-4214-8ba4-039e89433319', 5, '100183735', 'スティープルチェース編 I', '全国の魔法科高校に、九校戦の種目を一部変更するという通知が送られてきた。変更があったのは六種目中の三種目で、実に半分もの競技が変更になるという。急な種目変更に対応するため、第一高校の生徒会はルールの把握や選手の再選考、CADの再調整などに追われることになる。九校戦開始一ヶ月前という急なタイミングの変更に、誰もが大会運営に対する不満をこぼす中、達也は新しく追加された競技がどれも軍事色が強いことに疑念を抱いていた。', '2024/05/08 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/57170c6d-0798-4468-8654-287ad4e5e10a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fde31f2b-a388-43cc-80b9-74418ff1c86b', '3bd00d2e-8797-4214-8ba4-039e89433319', 6, '100184440', 'スティープルチェース編 II', '九校戦の急な競技変更に対応するため、達也は他の生徒会役員とともに多忙な毎日を送っていた。そんなある日、達也のもとに差出人不明のメールが届く。メールには、今回の種目変更が国防軍の圧力によるもの、そして九島家が国防軍の動きに乗じて、秘密裏に開発した兵器の性能試験をスティープルチェース･クロスカントリーで行なおうとしていると記されていた。達也は九島家が行なっている実験の内容を調べるため、九島家の本拠地である奈良へと向う。', '2024/05/15 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f58d5562-e9d5-4996-8299-1f4040e77a22.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ae10fd4-0a18-46f9-9692-ccb6493e26ac', '3bd00d2e-8797-4214-8ba4-039e89433319', 7, '100184908', 'スティープルチェース編 III', '九島家が極秘裏に行なっていた実験は、パラサイトを女性型戦闘ロボットに憑依させたパラサイドールの開発だった。パラサイドールの運用実験が行なわれるスティープルチェース･クロスカントリーの会場警備は、異常なまでに厳しく、達也ですら侵入出来ない。そこで達也はピクシーにパラサイトの監視を命じ、自分はエンジニアとしてCADの調整を行ないながら、下級生への指導を行なう。だが連日の激務と緊張の連続で達也はこれまでにない疲れを感じていた。', '2024/05/22 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d94fbc6b-6522-43a0-aa76-7b5528448c7c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79a2494e-d149-4ef7-9d9b-d440f2288c6d', '3bd00d2e-8797-4214-8ba4-039e89433319', 8, '100185886', 'スティープルチェース編 IV', 'ついにスティープルチェース･クロスカントリーの女子の部が始まった。達也はピクシーに全パラサイドールの位置を把握させると、パラサイドールが選手に接触する前に、すべて始末しようとする。だがパラサイドールは達也の想像を超えたスピードで魔法を発動。手こずりながらも何とか最初のパラサイドール封印に成功する。残りのパラサイドールたちを次々と封印していく達也だが、彼の前に最高性能個体プライム･フォーが立ちはだかる。', '2024/05/29 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/12d8231d-c069-445d-97fa-ece4e596b451.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5fa77bf0-19b3-44eb-98e1-a8a9a2114867', '3bd00d2e-8797-4214-8ba4-039e89433319', 9, '100186526', '古都内乱編 I', '九校戦が終わり、二学期が始まったある日、亜夜子と文弥が真夜直々の手紙を達也に届けに来た。手紙の内容は「周公瑾の捕縛について協力を依頼する」というもの。周公瑾は黒羽家が追跡していたが、京都付近で見失ってしまったという。どうやら周公瑾の逃亡を古式魔法師の一派である「伝統派」が手助けしていると見られる。伝統派は長年、九島家と対立している。そこで達也は九島烈の孫である藤林を通して、周公瑾の捕縛に協力を依頼する。', '2024/06/05 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e98fbf1-1aa1-4400-b7da-c6ec0d08ebba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('39733355-b076-47ff-8ed1-55067ef1437b', '3bd00d2e-8797-4214-8ba4-039e89433319', 10, '100187221', '古都内乱編 II', '九島烈から周公瑾捕縛の協力を取りつけるため、達也と深雪、水波は九島家の本拠地である奈良を訪れる。九島烈は達也の申し出を快諾すると、孫の光宣を紹介。光宣は達也の一年後輩で、身体は弱いものの強力な魔法力を備えているという。食事の席で達也たちが伝統派の術者を探していると聞いた光宣は、自分から協力したいと申し出る。翌日、光宣の案内で奈良にある伝統派の拠点を回っていた達也たちは、奈良公園で伝統派の襲撃を受ける。', '2024/06/12 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62982ec2-5656-41c6-b3b5-89795450bf5e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0677ff7a-79cf-493b-a71d-27771fddd19a', '3bd00d2e-8797-4214-8ba4-039e89433319', 11, '100187874', '古都内乱編 III', '日本魔法協会が主催している全国高校生魔法学論文コンペティション。通称、論文コンペが京都で開催されることになった。昨年の論文コンペが大亜連合に襲撃された経験から、今年は警備を万全にするため事前に会場周辺を下見したいと風紀委員長の幹比古が生徒会に提案。達也や深雪、水波、レオ、エリカもそれに同行することになる。生徒会が終わった後の帰り道、達也はニュースで真由美のボディガードである名倉三郎が京都で何者かに殺されたことを知る。', '2024/06/19 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5f8da307-9b94-4d15-97e8-4ff7f5c46128.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef0a4db5-cfbc-409e-8bce-eac9e3cca8ec', '3bd00d2e-8797-4214-8ba4-039e89433319', 12, '100188482', '古都内乱編 IV', '光宣の案内で京都にある伝統派の拠点を調べていた達也たちは、伝統派の一派で、清水寺の参道で飲食店を経営している店主と出会った。店主は、奈良の伝統派が大陸の術者に取り込まれてしまっている現状に危機感を抱いていると告げると、達也に情報提供を申し出る。店主の情報から京都の伝統派が潜んでいる場所に目星をつけた達也は、名倉を殺した犯人を捜したいという真由美と、伝統派との戦いに偶然出くわした将輝とともに、嵐山へと向う。', '2024/06/26 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/daba151d-54a3-40b9-907d-20d624d7ebc3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d7825422-b95b-4327-a105-25898e780c12', '3bd00d2e-8797-4214-8ba4-039e89433319', 13, '100189275', '古都内乱編 V', '【最終話】論文コンペ前日の夜。達也は文弥から周公瑾の居場所を突き止めたと報告を受ける。潜伏場所は何と、国防陸軍宇治第二補給基地。国防軍の基地に自分ひとりでは戦力が足りないと考えた達也は、将輝に連絡。場所が国防軍の基地だと聞かされた将輝は一瞬、躊躇するものの、十師族の責務を果たすため達也に同行することを決意。二人は周公瑾に操られた兵たちが待ち構える国防軍基地に侵入する。', '2024/07/03 23:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/080ad0ea-2677-4d40-9001-8ac6bd681337.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1f291ecf-a631-445d-a5c9-d22c6e1550ef', '魔法科高校の劣等生', '', 'hulu', 'the-irregular-at-magic-high-school-reminiscence-arc', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1099d3c1-bad2-4f39-926b-733eda3ad30b.jpg?w=331&h=447&p=t', 'hulu', 2014, 1, 1, 'FINISHED', NULL, 20458, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('577cb923-96eb-42e9-9ff5-ee9b3f81b23b', '1f291ecf-a631-445d-a5c9-d22c6e1550ef', 'hulu-the-irregular-at-magic-high-school-reminiscence-arc-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4fc0658-8be0-4f6d-b395-7b4e278be674.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a5a7845-f004-4e00-b39d-d5524b78e500', '577cb923-96eb-42e9-9ff5-ee9b3f81b23b', 1, '100099803', 'Chapter.1', '魔法科高校に入学する3年前、中学一年生の深雪と達也は、母の深夜とともに家族旅行のため沖縄に向かっていた。当時の達也はまるで使用人のように扱われており、深雪はそんな仕打ちを唯々諾々と受け入れているように見える兄が理解できず、イライラを達也にぶつけがちだった。ところが達也が不良軍人から自分を守ってくれたことをきっけかに、深雪は兄への考え方を変えていく。', '2022/01/06 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4fc0658-8be0-4f6d-b395-7b4e278be674.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6e81a7ad-ee4d-4bce-98b6-44862635855b', '577cb923-96eb-42e9-9ff5-ee9b3f81b23b', 2, '100099804', 'Chapter.2', 'ヨットでクルーズ中に、深雪たちは国籍不明の潜水艦から魚雷攻撃を受けた。魚雷は達也が使った魔法でバラバラにされ、事なきを得たが、この事件を重く見た国防軍は、恩納基地に駐留している風間大尉を派遣し、真夜に事情徴収を行なう。翌日、深夜たちは沖縄舞踊の観覧と体験会に行こうとする。だがこの催しが女性限定だったため、深夜は達也に恩納基地に見学に行くようにと命ずる。それを聞いた深雪は自分も達也と一緒に基地を見学したいと言いだす。', '2022/01/06 00:00:00', 1416, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60eac44d-785e-46c1-bb6f-1d828a4d6928.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c51d9afb-6a39-4db4-8c3e-2696b735ed0c', '577cb923-96eb-42e9-9ff5-ee9b3f81b23b', 3, '100099805', 'Chapter.3', '沖縄に突如、大亜連合軍が侵攻してきた。深雪は達也、深夜、穂波とともに恩納基地に避難する。だが大亜連合軍の攻撃と呼応するように恩納基地の部隊から反乱が起き、避難民たちを攻撃。その巻き添えで深雪と深夜、穂波が銃撃を受け、致命傷を負ってしまう。だが深雪の命が失われる寸前、達也の魔法が深雪の命を救う。深雪が命を失うほど深く傷つけられたことに激しく憤った達也は、大亜連合軍を殲滅すべく出撃する。', '2022/01/06 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/783b26b9-1b4b-4579-b676-720201105fc6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f166ff94-3010-40da-90dd-43ec195974c5', '魔法科高校の劣等生', '', 'hulu', 'the-irregular-at-magic-high-school-visitor-arc', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a41b3172-2134-450f-844d-15e0e9aaf34c.jpg?w=331&h=447&p=t', 'hulu', 2014, 1, 1, 'FINISHED', NULL, 20458, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 'f166ff94-3010-40da-90dd-43ec195974c5', 'hulu-the-irregular-at-magic-high-school-visitor-arc-s1', 'シーズン2', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/914fbb74-8152-437d-8cbc-1cd960b17fab.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a4184246-0df4-4f2b-9ffa-f52bde72960d', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 1, '100066645', '来訪者編 I', '《灼熱のハロウィン》から2か月。達也たちは交換留学でアメリカに行くことになった雫の送別会を楽しんでいた。そして新学期になって雫と交換でアメリカから留学生がやって来た。彼女の名はアンジェリーナ=クドウ=シールズ。深雪に匹敵するほど強い魔法力を持った彼女の正体とは……?', '2020/10/09 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/914fbb74-8152-437d-8cbc-1cd960b17fab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('59e8401d-a520-4bc5-bce2-f9c000276d80', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 2, '100066872', '来訪者編Ⅱ', '体内から血を抜き取られ、死亡するという猟奇殺人事件が発生した。その手口から「吸血鬼事件」と呼ばれたこの事件は、アメリカでも同様に起こっていた。吸血鬼が世を騒がせる中、その脅威がレオへと襲い掛かる。', '2020/10/16 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9a9fdca4-9893-4bf3-a475-7591615819ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a43156a4-01b8-4f9a-a84c-d7c2e64cccc2', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 3, '100067185', '来訪者編Ⅲ', 'レオを襲った吸血鬼はパラサイトと呼ばれる魔物だった。事件を解決すべく七草家と十文字家が協力して動き出す。一方、レオの仇を討つべく幹比古とともにパラサイトの捜索を行っていたエリカは、仮面をつけた謎の魔法師と対峙する。', '2020/10/23 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/281e5826-5030-43d0-92f4-396e20c5fe48.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('492c2ed0-c7a8-4ea7-831f-8cdf5e1434f2', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 4, '100067447', '来訪者編 IV', 'エリカと剣を交えた仮面の魔法師の正体はリーナだった。正体を暴かれたリーナは『パレード』を使用し、達也に襲いかかる。達也は『分解』で『パレード』の無効化を試みるも失敗。リーナの魔法を前に苦戦を強いられる。', '2020/10/30 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e70d315e-098a-4e28-a411-9ccbcf2f08b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e6d0e5cd-f0b9-4634-9700-706cff3583b1', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 5, '100068569', '来訪者編Ⅴ', '精神に由来する情報生命体であるパラサイト。本来こちらの世界には現れない、異次元の住人である彼らが何故出現したのか? 原因不明の来訪者が魔の手を第一高校へと伸ばす……!', '2020/11/06 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f58cb047-a0fd-4c50-b98a-19b77e223ee3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a834c8f-5339-4248-a573-82ceec5a34f9', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 6, '100068988', '来訪者編Ⅵ', '意中の相手にチョコレートを贈り、思いを打ち明ける日･バレンタインデー。この習慣はいまも健在で、当日はチョコレートを巡って悲喜こもごものドラマが繰り広げられる。それは魔法科高校といえども例外ではない。果たして今年のバレンタインデーはどうなるのか?', '2020/11/13 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/16a2295a-ba26-4172-b474-4a7a73158842.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0bf62de6-d5e5-4d58-a9fe-3a35ee81cbdc', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 7, '100069390', '来訪者編 VII', 'バランスからリーナに、《灼熱のハロウィン》を引き起こした術者の捕獲命令が下された。バランスは「確保が不可能な場合は抹殺もやむを得ない」という言葉とともに、戦略級魔法を発動させるためのリーナ専用のCAD･ブリオネイクを渡すのだった。', '2020/11/20 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d04ea596-08d9-43c4-befa-f04a3e54f303.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5a7df8ae-5dd0-426e-a66b-522c3ccd4c75', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 8, '100070050', '来訪者編Ⅷ', '四葉家の工作によって、達也たちの身辺を脅かしていたUSNA軍は排除された。残る脅威はパラサイトだけ。達也はピクシーから残るパラサイトの情報を聞き出すと、深雪、ほのかとともに他のパラサイトをおびき出すため青山霊園へと向かう。', '2020/11/27 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9da8c284-13ee-4785-a0f4-bf5dd64cf6a5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ccf0589f-883a-4646-96a4-56dddd75218d', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 9, '100070910', '来訪者編Ⅸ', 'ピクシーの強力なサイキックのおかげもあり、達也たちはついにパラサイトの捕縛に成功。パラサイトの身柄はエリカたちに任せ、一度撤退する。しかし、パラサイト達を収容しようとするエリカたちの前に、警察に扮した第三の勢力が現れる。', '2020/12/04 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3063caf3-16f0-4a7b-b325-dfd08b98d619.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9e1c3006-5d0f-4b8f-93a8-caf1db83adab', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 10, '100071428', '来訪者編 X', '「七賢人」レイモンドに指定されたとおり、達也たちは2月19日の夜、第一高校の野外演習場へと向かった。そこにはレイモンドの言葉通り、活動中のすべてのパラサイトと、リーナの反応があった。このままでは、シリウスとしての任務を遂行するリーナとの衝突は避けられない。それぞれの思いが交錯する中、パラサイトとの最終決戦が始まる。', '2020/12/11 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/01105d51-3a92-49dc-9a5b-1391e05caf0f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('be4589e7-842e-47af-897d-b84eb2804f1a', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 11, '100071804', '来訪者編 XI', 'パラサイト事件から約一ヶ月が過ぎ、第一高校は第29回の卒業式を迎えていた。達也たちは真由美、摩利、克人たちをはじめとする卒業生との別れを惜しみながら過ごす。そしてもう一人、アメリカから来た友人との別れが目前に迫っていた。', '2020/12/18 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/738bc9a8-9961-456c-bf97-63aa0fda190b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('319ef0e5-9c00-423c-8525-6963f82156a1', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 12, '100072174', '来訪者編Ⅻ', '日本初のハイパービルディング･オフショアタワーの竣工記念パーティに誘われた達也と深雪は、会場で葉山に桜井水波という少女を紹介される。彼女に3年前のある事件で亡くなった女性の面影を見て動揺する2人。そんな時、過激な魔法主義者･進人類フロントがパーティを狙っているという情報が入る。', '2020/12/25 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e799e8ec-520f-43a6-a516-b3d963ae3708.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6fc9b3a9-6618-4b43-a3ce-fd8a6249387d', '591c5025-42aa-45e0-9a35-eef2a5ff7f2c', 13, '100072358', '来訪者編XⅢ', '【シーズン2 最終話】進人類フロントが「一時間後にオフショアタワーを爆破する」と宣言した。だが彼らが一時間というタイムリミットを守る保証はない。進人類フロントの企みを阻止するため、達也は深雪と水波を連れ、地下一階の管理センターへと向かう。', '2021/01/01 00:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c7a3017-6007-4dd6-8a36-68b23b4fdae1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('69ad035d-3758-47bd-810a-045196a1965a', '魔法使いの嫁', '', 'hulu', 'the-ancient-magus-bride', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fcab31d-cfe9-406c-ae26-bf64780cf053.jpg?w=331&h=447&p=t', 'hulu', 2017, 3, 1, 'FINISHED', NULL, 98436, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('c746fc6d-176c-4a5b-8df1-ba2c0f537624', '69ad035d-3758-47bd-810a-045196a1965a', 'hulu-the-ancient-magus-bride-s1', 'SEASON1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83490f2c-51c5-446d-9cec-ad075f1d198d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('859435a3-e8f9-4a92-b66f-881e6688fa32', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 1, '100008469', 'April showers bring May flowers.', 'この世界で生きることを投げ出そうとした15歳の少女、羽鳥チセ。彼女はオークショニアの誘いに応じ、自分自身を商品とし、闇の競売会へ出品する。ヒト為らざる魔法使い、エリアス･エインズワースに500万ポンドの値で買われ、将来の「花嫁」として迎えられたとき、チセに見えていた世界の姿が変わり始める―。', '2017/10/10 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83490f2c-51c5-446d-9cec-ad075f1d198d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aec35a44-2790-451e-b5b2-ed7548c405e0', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 2, '100008688', 'One today is worth two tomorrows.', 'ロンドンの片隅にある古書店。その本当の姿を知るものは少ない。エリアスに連れられ、彼が古くから取引を続ける魔法道具の工房を訪れたチセ。工房の女主人アンジェリカは、チセにささやかな魔法を教えるが…。夜の愛し仔 (スレイ･ベガ) のまことの力が、彼女の記憶の一欠片を水晶細工として蘇らせる。', '2017/10/17 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/741f97ca-4cf7-4568-b5f5-3d02d7526f06.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c891f415-0b4a-42d0-8b57-badf9995f38c', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 3, '100009256', 'The balance distinguishes not between gold and lead.', '教会の命を受け、エリアスを監視する聖職者サイモン。彼はエリアスたちに、3つの案件を伝える。そのひとつを解決するため、最果ての地に赴むいたチセとエリアス。そこではエリアスの師、リンデルと、滅びに瀕した旧き種族が待っていた。今まさに大地に還らんとする古の者と共に、チセは天空を馳せる夢を見る。', '2017/10/24 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/68e7622e-8b8e-4a4d-9b8c-f6b86902b5e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('baa4b768-3870-429c-9dcc-780bc96de1cd', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 4, '100009623', 'Everything must have a beginning.', '猫の集う街、ウルタール。その昔ウルタールでは、人と猫との間に悲しい出来事があった。惨禍の中心にいたものの魂は澱みとなり、代々の猫の王により封印され続けている。ふたつ目の案件を解決するため、この街を訪れたチセとエリアスは、そこに残る妄念を浄化しようと試みるが…。', '2017/10/31 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26e6fee1-f5e6-465f-b9b3-579ae43738d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('79583003-5715-43fb-b841-22ec4b2f7d0f', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 5, '100010299', 'Love conquers all.', '魔法使いに騙された、哀れな少女。魔術師レンフレッドにはそう見えていた。だがチセは、エリアスの真意がどうあれ、彼から離れるつもりはなかった。なぜならエリアスは、初めて自分を必要としてくれた存在だから。チセは澱みの中に歩みを進め、惨禍の真相を知る。そして悲劇の裏側には、ひとりの少年の姿が―。', '2017/11/07 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aedb7b55-6e28-4468-9d3f-46f1ee80d924.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('24f526d5-546e-479d-b93a-87b3c801c119', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 6, '100010485', 'The Faerie Queene.', '本来還るべきところに、還っていく魂たち。それを見送りながらチセは自身を想う。ウルタールの一件から10日と数日が過ぎても、チセは眠りに落ちたままだった。彼女を案じるエリアスとサイモンの前に、予期せぬ客が姿を現す。それは常若の国 (ティル･ナ･ノーグ) の主。ブリテンの夜の一角を統べるもの。妖精たちの女王 (ゲアラハ)、ティターニア。', '2017/11/14 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/22fea091-c27b-4263-b8ff-fee194371baf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b1910ab5-c234-4c1b-8a52-a9368dcf8b0d', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 7, '100010979', 'Talk of the devil, and he is sure to appear.', 'たなびく漆黒の毛並み、燃えるように赤い目をしたその犬は、チセのことをイザベルと呼んだ。教会からの最後の案件は、とある墓地に現れた黒妖犬 (ブラック･ドッグ) の検分。だが、見定めるべき彼の助けでチセはからくも難を逃れる。一方、レンフレッドの弟子アリスもまた、黒妖犬 (ブラック･ドッグ) を手に入れるべく動き出していた。', '2017/11/21 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/62e6865d-3e4b-4d42-83bb-ef0459ef0975.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('136a4619-f62c-4659-8907-1bd6f09da79e', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 8, '100011159', 'Let sleeping dogs lie.', 'アリスは変貌したエリアスを見て、直感する。これは、けしてヒトには為り得ぬものだと。レンフレッドとアリスを操り、黒妖犬 (ブラック･ドッグ) を手に入れようとしていた魔術師カルタフィルス。彼の「作品」にチセを傷つけられたエリアスは、今までとは違う異様な姿と力の片鱗を見せる。エリアスを知る魔術師たちは彼をこう呼ぶ。裂き食らう城 (ピルム･ムーリアリス)、と。', '2017/11/28 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eecaec62-b230-45b9-a13d-995c0d9dc0b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62d5a388-59fe-43d5-b2ff-6f2daa0420d3', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 9, '100011399', 'None so deaf as those who will not hear.', '教会の案件はすべて片付き、おだやかな日々が戻ってくるはずだった。だが最後の一件以来、エリアスの様子がおかしい。チセが初めてエリアスの部屋で一夜を過ごした翌朝、彼はこつ然と姿を消した。チセの身を案じるアンジェリカの言葉も、人より純粋なルツの言葉も、戸惑うチセの心を上滑りしていく。', '2017/12/05 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4aa3cecf-923f-46ca-8752-56c20bdf9e9c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8f06648b-717f-496c-9d05-e13d2df2d913', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 10, '100012136', 'We live and learn.', '海豹人 (セルキー) と共に竜の背に乗り、チセはリンデルの許へと向かう。自分だけの、魔法使いの杖を作るために。エリアスに「飼われるままでいる」ことを拒もうとしないチセを見かね、リンデルは夜の闇の中からエリアスを見出した頃の話を始める。そのころ、独り残るエリアスに魔術師たちの集う場、院 (カレッジ) からの便りが届いていた。', '2017/12/12 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3975b6f8-02b3-40a8-b9cc-55ee914cb240.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c032cebd-ecc9-4d33-90a9-b2c7877b6c05', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 11, '100012476', 'Lovers ever run before the clock.', 'ヒトのふりをしたがる、奇妙な為り損ない。いつしかエリアスが己のことを話さなくなったのは、師の教え故か、人への苦い記憶がそうさせるのか。リンデルの二つ名、百花の歌 (エコーズ) の由来。その歌は雪解けの水音に似て、朗々と風に乗り、季節外れの開花と妖精たちの輪舞を現出させる。そして歌の魔力はチセが覗き込む水面 (みなも) を水鏡に変えた。水鏡の向こう側に見える姿はもちろん―。', '2017/12/19 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8098a532-f2be-4767-a85d-b59d46a381fc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bcafcb72-f286-4eb5-b99d-e75a3ef23268', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 12, '100012694', 'Better to ask the way than go astray.', '完成した杖に触れた瞬間、チセは幻視する。無数の閃光の先に広がる、霧に包まれた巨木の群れを。縁 (えにし) の糸が結ばれ、彼女はかつて見送った竜と再会する。自ら命を絶った母、自分を置いていった父。その本当の思いは、今となっては知る術はない。しかし今のチセには、伝えたい思いと言葉、そして伝えるべき相手がいる。切なる思いは彼女をはるか遠く、帰るべき場所へと運んでいく。', '2017/12/26 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02343321-1448-46af-b407-607dbfa494f6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('61924158-233b-450d-8def-7f156f2ba2e2', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 13, '100012947', 'East, west, home''s best.', '野に森に、夏の足音が聞こえだした頃。風に舞う綿蟲たちの毛刈りに追われるチセとエリアス。竜の国から急ぎ帰ったチセには、伝えたい想いがあるはずだった。しかし、それはいつ、どんな形で伝えたらいいのかが解らない。そしてエリアスもまた、己の中に芽生えた理解しがたい感覚に戸惑っていた…。', '2018/01/09 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d64b593-1b5e-43ce-bea8-17a96abb8943.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3712426b-b1b4-44d4-948c-589bf0aea920', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 14, '100013266', 'Looks breed love.', '愛した相手に才を与える代わりに、命を奪う吸血鬼、リャナン･シー。彼女にとって愛すことと、大切な存在を失わぬため愛さぬことは、どれほどの違いがあるのだろう。彼女の想い人、ジョエルの命は尽きかけていた。その胸の内には、薔薇の園で見た一瞬の幻としてリャナン･シーの姿が焼き付いている。終わりが訪れる前に、惹かれ合う二人をひと目だけでも会わせたい。そう強く願うチセは、彼らの為に出来る事をやろうと決意する。', '2018/01/16 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc139fbb-a707-4609-ba1d-99d93a5b973b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c75b763-fb21-4659-8d28-9c5f3fb01483', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 15, '100013651', 'There is no place like home.', '行き過ぎた魔力の行使に悲鳴をあげるチセの体。チセの傷を癒やすため、エリアスは彼女を抱えて妖精の国へ向かう。ティターニアは問う。人の世で疎まれ、魔力に耐えられぬ愛し仔と、人の為りそこないと謗られる茨の魔法使いが、なぜ人の世に居続けるのかと。魔法使いという人と交わる生き方をエリアスが選んだ理由とは。', '2018/01/23 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1f95e7a0-5ffe-4f3f-8f01-e4328473926a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e72e5853-5f8f-4c1b-9f7e-19657760bcc7', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 16, '100013782', 'God''s mill grinds slow but sure.', '野山は雪をまとい、旧き女神と神獣が森を闊歩する最も昼の短き頃。クリスマスが近づき、活気づくロンドンの街で再会した魔法使いの弟子と魔術師の弟子。大切な人のためにプレゼントを選ぶ二人だが、何を贈ればいいものか、見当すらつかない。一日を共に過ごし、チセに心を開いたアリスは、レンフレッドと出会った頃を語り始める。', '2018/01/30 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9c5e8731-9e19-41c7-a1bf-e71040d662be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ce0aa70-9a26-45cb-9265-a4b5dd9d34df', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 17, '100014067', 'Look before you leap.', '「弟なんていらない!」少女ステラが口にした心にもない一言は、恐ろしい出来事を引き起こす。弟イーサンは消え、父も母も弟のことを忘れた。イーサンを覚えているのは言葉を発したステラひとりだけ。弟を探すステラと出会ったチセたちは、灰ノ目が仕掛けた遊びに巻き込まれる。', '2018/02/06 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8befa23a-c46a-4dc7-b44a-139e400b0537.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad3f37f5-5814-4e6f-a325-4dbc65c5945d', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 18, '100014452', 'Forgive and forget.', 'チセと友達になったステラは、すぐさまエインズワース邸を訪れた。彼女の子供らしい率直さが、チセには少しだけ眩しい。だがステラが来た直後から、エリアスの様子が落ち着かない。彼はその身を獣のような姿に変えると、逃げるように駆け去った。エリアスの中にまた新たに芽生えたもの。それは痛みにも似た、自分では抑えがたい感情だった。', '2018/02/13 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b1e586a-f01d-4ec6-9e9c-33036b363ae9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3ccb586f-db62-414b-81e9-6fbfb3653cf2', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 19, '100014703', 'Any port in a storm.', 'それは夢の中の出来事。しかしチセは確かに彼と会い、言葉を交わした。チセたちがカルタフィルスと呼ぶ魔術師と。そして彼の中で彼と共に在る、何者かとも。竜の国から連れ去られた雛たちを取り戻すべく、学院の魔術師たちと競売場に向かったチセとエリアス。希少な竜の雛を欲する者たちの熱狂が最高潮に達したその時、人間は自らの愚かさを知ることとなる。', '2018/02/20 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58cb7d8d-666b-4734-bb76-5b1f68a2ff5d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eac62fdd-f7f3-43d8-8507-b040e52f0395', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 20, '100015033', 'You can''t make an omelet without breaking a few eggs.', '空覆う巨影。渦巻く炎の息。生きとし生けるものの恐怖を形にしたかのような古の姿を取り戻した竜は、ロンドンの空を舞う。だがチセにはそれが、戸惑う幼子のように感じられた。チセは竜の背に乗り、彼の魂を鎮めようとする。しかしその代償は大きく、彼女の身に異変が起こる。', '2018/02/27 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3661630e-52c6-4e49-b4f3-762764307df1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('648cb920-78d2-4560-9e57-546273f4b9ce', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 21, '100015291', 'Necessity has no law.', '草色の蝋燭の灯り。塩入りの林檎酒。ローズマリーの枝と百合の花。それが秘密の集いに加わるための招待状。竜の呪いを解く方法を求め、チセとエリアスは古今の呪いに通じる魔女たちの集会に同席する。そして茨の魔法使いは立ち返る。命を繋ぐには、別の命で贖う他はないという真理に。', '2018/03/06 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5329e2a5-ced1-4ee7-9708-a094170de048.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ea2c32c-b851-4c30-b219-94f498c13d0c', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 22, '100015748', 'As you sow, so shall you reap.', 'たとえ自分のためだとしても。自分が求めていた答えが絵空事だったとしても。その人が為そうとしたことは、裏切りに他ならなかった。不死と噂される魔術師はチセに取引を持ちかける。彼がチセの眼前に差し出したもの、そして求めた対価とは―。', '2018/03/13 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3bd6b15f-84bd-4789-8f4f-8e0ca5c33c8a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05cbbf3c-eafb-4d77-b80d-17d983649485', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 23, '100016034', 'Nothing seek, nothing find.', '人為らざる者の好意は必ずしも人のためになるとは限らない。自明だったはずの事を、己の身と魂で識ることとなった茨の魔法使いは独り荒れ野を彷徨う。ならば、人の好意は人ならぬ身に何をもたらすのか。救いを求めた者と、救おうとした者。カルタフィルスとヨセフの旧き記憶をチセは幻視する。', '2018/03/20 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ea3389f2-417e-4bdc-9205-68b9a36a9d0a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7ac579c-8976-44e4-827e-49e20be4448e', 'c746fc6d-176c-4a5b-8df1-ba2c0f537624', 24, '100016210', 'Live and let live.', '【シーズン1 最終話】この国に来て関わった大切な人々と妖精たち。彼らの力を借り、ついにチセは不死の魔術師と対峙する。ふたりの魂を苛んできた痛みや苦しみは、どこか似ていた。苦痛から逃れるために、一方はいつしか己の身を顧みなくなり、もう一方は他者を生贄にし続けた。その繰り返しに果てがないことを今のチセは識っている。少女の想いは、逃れがたき連鎖にひとつの区切りをもたらす。', '2018/03/27 12:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1c9da66c-11ab-4daf-ac3b-47df08f5b3e5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('dec2a056-5757-496a-929e-cbbfbca13382', '魔法使いの嫁', '', 'hulu', 'the-ancient-magus-bride-season2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/969840ff-4ffc-462a-9ab2-1311bc5f22c5.jpg?w=331&h=447&p=t', 'hulu', 2017, 3, 1, 'FINISHED', NULL, 98436, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2395b987-692e-4fd2-ae8d-d1582023a53d', 'dec2a056-5757-496a-929e-cbbfbca13382', 'hulu-the-ancient-magus-bride-season2-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1d4775f-3c4f-48b4-ab3c-03671d908908.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('808050cb-5eb7-4364-bceb-c7ce3d3524c0', '2395b987-692e-4fd2-ae8d-d1582023a53d', 1, '100186888', 'Live and let live. II', 'チセの元に届いた一通の招待状―――それは魔術師の原石が集う”学院 (カレッジ) ”からのものだった。蘇る過去の記憶、やっと手に入れた居場所。悩みながらもチセは門を叩く決意をかためる。―学びたいんです。それが私や誰かの助けになるかもしれないから―', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e1d4775f-3c4f-48b4-ab3c-03671d908908.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c17bd029-29bd-4b8e-8470-4dd6ed50273d', '2395b987-692e-4fd2-ae8d-d1582023a53d', 2, '100186889', 'Birds of a feather flock together. I', '初めての授業。同室となる魔術師との邂逅。慣れぬ世界に戸惑うチセだったが、アリスとの再会に胸をなでおろす。2人の前には教壇に立つエリアスの姿。魔術師が集う学院で“魔法”の授業が始まろうとしていた。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/83d6193f-3575-4aa2-9e53-d3942251a937.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2cc3907f-f8d0-4f78-ab9c-ed96539db8f9', '2395b987-692e-4fd2-ae8d-d1582023a53d', 3, '100186890', 'Birds of a feather flock together. II', 'チセの前に現れた凛とした青年、リアン。魔法の教えを乞う彼に、アリスの使い魔ウィル･オー･ウィスプは適性の欠如を宣告する。リアンは悲しげな表情を浮かべるも、気にした様子は見せない。彼の案内によってエリアスと合流したチセは食堂の訪問を提案される。そこにはチセのクラスメイトが集まっていた―――', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd19dd9c-4fda-4265-a62f-f6ef5fbdb691.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d2677fa-33ce-469e-a4f7-8a1baa58bd74', '2395b987-692e-4fd2-ae8d-d1582023a53d', 4, '100186891', 'The cowl does not make the monk.', '不意に誘われた霧の中。待ち受けていたのは、謎めいた婦女･ラハブとの邂逅だった。チセの胸元に光る翡翠の色を見て、彼女は過ぎし日を語り始める。人の形をなぞる日々が、人為らざる者にもたらしたものとは。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d93d8abd-bc50-4589-8ef1-6e029ec9430b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f1d067e-87b7-497f-b6b4-a3a4b0ebefea', '2395b987-692e-4fd2-ae8d-d1582023a53d', 5, '100186892', 'First impressions are the most lasting.', '魔術師達との関わりの中で、チセは学院を飛び交う噂話を耳にする。学び舎の礎を築いた魔術大家<七つの盾>。そしてルームメイトに纏わる<書紡ぎ蜘蛛 (ウェブスター) の悲劇>。学院に渦巻く因果が次第に姿を現し始める。そんな最中、同級生のゾーイの余所余所しさを憂いたチセは会話を試みるが…', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4844b132-0e8e-4406-9a6e-2be1ed037393.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5288cb6-7baf-4e0e-bb13-333d46cf7677', '2395b987-692e-4fd2-ae8d-d1582023a53d', 6, '100186893', 'Better bend than break.', '師からの思いがけない言葉に不満を燻らせ、エインズワース邸を訪ねたアリス。その胸中を知り、チセもまた自分の境遇を思い返していた。「師弟」「伴侶」「親子」交わりの中で得た在り方。望むものと望まれるものの狭間で、少女達は揺れ動く。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51035ddc-1a8c-4495-aec5-f37e16f174b3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58aad51c-0235-4d51-9068-d733c999556d', '2395b987-692e-4fd2-ae8d-d1582023a53d', 7, '100186894', 'Slow and sure. I', '期せずして知ったゾーイの秘密。その共有をきっかけに、生徒達は少しずつ打ち解け始めていた。しかしチセは未だ識らない。居合わせていた少女にもまた、縛られた運命があることに。一羽の夜鷹が、囚われた心を呼び戻す。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/67975a50-99fa-4ba2-8525-506be9b98ee1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c224f9e2-c8a8-4b55-935d-363132a98b43', '2395b987-692e-4fd2-ae8d-d1582023a53d', 8, '100186895', 'Slow and sure. II', '生きる知恵を得るための校外実習、“ブッシュクラフト”。生徒達は授業の一環としてスコットランドへ赴いていた。そこは、夜の者どもが荒野に遊ぶ地。善き者も悪しき者も、此方を見据える瞳は常に闇の中に在る。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6737b7f4-eaff-4d52-acb3-7df609331d23.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77c91ac0-0508-4c03-a229-de3a9eed9909', '2395b987-692e-4fd2-ae8d-d1582023a53d', 9, '100186896', 'Conscience does make cowards of us all. I', 'あの時、耳元で囁かれた声。声に導かれるままに、海妖馬を傷つけた自分。その選択にチセは困惑していた。一方、学院内では閉架に収まるはずの禁書盗難が判明する。それは“カルナマゴスの遺言”の写本、生ける者の生死と時に纏わる書――。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50cd80cb-d201-4323-ab24-f12e3be4db00.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2f9eec5c-a7f2-4c20-a07d-2f2d6f6acd9e', '2395b987-692e-4fd2-ae8d-d1582023a53d', 10, '100186897', 'Conscience does make cowards of us all. II', 'ルーシーが目を覚まし、ひとたびの安堵が訪れたのも束の間。学院に忍び込んだ2匹の獣人がチセたちに襲いかかる。その姿に底知れぬ憎悪を表し、叫ぶルーシー。混沌とした状況で活路を思案するチセ。その時、彼女の内なる声の主が再び囁き始める――。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2b526c41-be76-4c20-9f78-39ad4ee90f96.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96c2cd2c-a1b0-4f74-9368-3e7c5154245c', '2395b987-692e-4fd2-ae8d-d1582023a53d', 11, '100186898', 'A small leak will sink a great ship. I', '意識が戻らないルーシーとシメオンを心配するチセ。その原因は禁書“カルナマゴスの遺言”による魔力不足だと知らされる。2人の救出に手を差し伸べるエリアスに、チセも協力を申し出るが…。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5adec210-0934-4ac9-988c-c1f7666a975c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('283beeb2-3110-401c-8acc-e329415e095c', '2395b987-692e-4fd2-ae8d-d1582023a53d', 12, '100186899', 'A small leak will sink a great ship. II', '【第1クール 最終話】亡霊彷徨うハロウィーンの夜。禁書の影響で体調の芳しくないルーシーの代わりとして、チセ達は廃棄塔を訪れる。現れたのは怪しげな風体の男、ザッケローニ。招かれるままに足を踏み入れた塔の地下、その先には――。ひと司る魔術の世界で、魔法使いは何を見るのか。', '2024/07/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6600115-89b2-4be2-82df-20cdfd7ae9d5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f885e8a8-f8a1-4dfd-896a-3567c00d8934', '2395b987-692e-4fd2-ae8d-d1582023a53d', 13, '100209661', 'Nothing venture, nothing have.I', '奪われた魔術書。フィロメラの自主退校の報せ。二つの危機が降りかかる中、学院の封鎖により一時の安息を得たチセ。だが、それは仮初めに過ぎない。生徒たちは己を守る術を習得するため特別授業に臨む。魔術に限らない“戦闘”の訓練に。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6052ab2-951f-41eb-91b2-66f15b71a29d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('72e91849-2f4b-4adc-a33c-86da1fe81793', '2395b987-692e-4fd2-ae8d-d1582023a53d', 14, '100209662', 'Nothing venture, nothing have.II', 'ロンドンの街に降り立つ二人の魔女。行方知れずの魔術書を求め、夜の街を巡り歩く。遠く響くは悲痛と憎悪を帯びた獣の声。時同じくして臥せるフィロメラ。知るはずのなかった優しさが彼女の心を締め付ける。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3faeab27-3920-469b-8da0-ef1d81565a37.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca529f50-b865-4ede-8f9b-d9b15d3f2a8c', '2395b987-692e-4fd2-ae8d-d1582023a53d', 15, '100209663', 'Needs must when the devil drives.I', '迫る試験に向け四苦八苦する生徒たち。息抜きに始まった小さな余興でリアンはフィロメラに勝負を挑む。ヴェロニカの一声で応じるフィロメラ。接戦の末に勝利したリアンだったが、彼の目に喜びの色は露ほどもなかった。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/05697d45-be5f-4867-9caa-ce4991a99226.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('88610277-d158-4f08-bfe8-19d4494c6a16', '2395b987-692e-4fd2-ae8d-d1582023a53d', 16, '100209664', 'Needs must when the devil drives.II', 'ヴァイオレットの発案で始まった「肝試し」二人組になって進む中、チセのペアとなったのはヴェロニカだった。慣れない組み合わせだが、チセには確かに聞きたいことがあった。フィロメラについて。彼女の家について。ヴェロニカは微笑みながら、フィロメラの生い立ちを語りだす。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/80b12deb-e751-43f4-8592-ab570e514e95.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcf2e4be-6403-476f-b900-abcb4b394c96', '2395b987-692e-4fd2-ae8d-d1582023a53d', 17, '100209665', 'Gather ye rosebuds while ye may.', '原因不明の悪夢。魔力を抜かれ倒れてゆく者、閉鎖の理由を知り動揺する者。混沌とした学院の中で、チセは禁書と接触する。エリアスとの一時の休息も束の間、学院に不穏な気配が漂い始める。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e7b8940-99d8-42db-9ff3-d9fc519ea9e4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84de0854-3f02-4242-9043-564ea4db2917', '2395b987-692e-4fd2-ae8d-d1582023a53d', 18, '100209666', 'Coming events cast their shadows before.', '少女の願いはただひとつ。愛されることだった。愛を注がれなかった空虚な心が、少女を異形へと変化させる。寄るべを求めた少女が、今は何を欲するのか。それは少女にも分からなくなっていた。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f897b1c3-fe9f-46d6-9ef9-56620d31f39d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2d66f762-b7b7-48f6-b8cf-5d31390e7124', '2395b987-692e-4fd2-ae8d-d1582023a53d', 19, '100209667', 'Man''s extremity is God''s opportunity.', '変わり果てた友の姿。チセが踏み出すには、それだけで十分な理由だった。友として、魔法使いとして、彼女を救うためチセは走り出す。今動かなければ、彼女は死んでしまうから。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44a5d94a-ad4e-428c-8282-a25fb96b9467.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0de9f9de-a6fd-4745-90ae-50c29dbbee35', '2395b987-692e-4fd2-ae8d-d1582023a53d', 20, '100209668', 'Even a worm will turn.', 'これはいつかの記憶。精霊が生まれた日。最も大事な命が下された日。娘が愛されていたことを記憶し、伝える。例えその先にどんな悲劇が待っていようと、その役目だけは果たすはずだった。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6967a416-f87e-4257-a263-35f340e9839c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2722d0ba-2f61-41c3-9478-1735123606cb', '2395b987-692e-4fd2-ae8d-d1582023a53d', 21, '100209669', 'A burnt child dreads the fire.', '友のために奮闘するゾーイ。その働きもあり、チセたちはついにフィロメラの元に辿り着く。溢れ、暴走した魔力は彼女らを記憶の回廊へと取り込む。惨憺とした過去を巡る歩みが、フィロメラの本音を引き出していく。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/788da05e-ad93-45c3-9add-e4f24928a042.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6826452-6816-4946-8f96-e915068d3df1', '2395b987-692e-4fd2-ae8d-d1582023a53d', 22, '100209670', 'Give a thief enough rope and he''ll hang himself.', '明かされたリズベスの過去。愛とも憎しみとも取れる感情、その執着の果てに生まれた結末。幽かな望みに縋ったフィロメラの祈りは、どこにも届かず闇に消えていくのか。愛されたかった、認められたかった、それだけなのに自分には何もない。そうだとしても。祈りを辞めなければ、差し出される手は掴むことはできない。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64629e1c-ff9d-4307-954e-2a3f81b0a524.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4833c0d3-937a-4b1d-a911-22d9a1f728c4', '2395b987-692e-4fd2-ae8d-d1582023a53d', 23, '100209671', 'Of two evils choose the less.', 'エリアスの助けで、リズベスの魔術を打ち破ったアルキュオネは本来の命令に従う。そこにはフィロメラを守るため、アダムの残した仕掛けが施されていた。しかし、リズベスは止まらず、自身すらも贄として異邦の神を顕現させてしまう。すべてを塵と化す神に、チセたちは女神モリガンの助けを借りて立ち向かうのだった。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ef4630fc-9063-4159-a1cc-004409d7abef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c537c91f-59da-45fa-b4a0-0dfd305cdcf7', '2395b987-692e-4fd2-ae8d-d1582023a53d', 24, '100209672', 'The show must go on.I', '【シーズン2 最終話】ついにリズベスと決別するフィロメラ。学院で出会った大切な友と協力し、偽神の封印を試みる。彼女は、自分がもう1人でないことを知っていた。封印のため、助けを求めるその手には、すでに迷いなど無かった。', '2025/01/01 00:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4b3a7792-fbe9-4fd0-905d-a4ca004a9e24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('ca829988-40be-44dd-add2-2099c654eb38', '魔法使い黎明期', '', 'hulu', 'the-dawn-of-the-witch', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98b2ab77-d53f-4fa3-af75-a52c93571115.jpg?w=331&h=447&p=t', 'hulu', 2022, 1, 1, 'FINISHED', NULL, 133175, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5a71ecfc-805d-437b-bc3d-41c1307f3e22', 'ca829988-40be-44dd-add2-2099c654eb38', 'hulu-the-dawn-of-the-witch-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd0b4c56-c13b-4470-927a-b67ac80c5128.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66a0453c-27ce-4d29-ba72-e1868f2d65f1', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 1, '100109243', '劣等生と杖の魔女', 'ウェニアス王国王立魔法学校の劣等生セービル。入学以前の記憶を失っている彼はどこか空虚な学校生活を送っていた。そんなある日、学長のアルバスから呼び出され、“魔女狩りのある地域で、魔法の有用性を広める”という特別実習への参加を命じられるセービル。自身の目的を果たすため実習先まで“引率の先生”を引き受けた黎明の魔女ロー･クリスタスと共に旅立つが……。', '2022/04/11 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd0b4c56-c13b-4470-927a-b67ac80c5128.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8396b8df-5706-409b-ac7d-ea60a04bbdc8', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 2, '100109803', '裏切り者と呼ばないで', 'ロスや秀才少女ホルトと共に実習先へと旅立ったセービルだったが、未だに魔女を快く思わない存在が彼らをつけ狙っていた。一方、セービルたちとは別に実習先を目指す“獣堕ち”のクドーは魔女狩りのための戦闘集団〈デア･イグニス〉の裁定官に襲撃され窮地に陥る。生徒を危険な目にあわせまいと、1人で救出に向かうロス。しかし、クドーの悲鳴を聞いたセービルとホルトはいてもたってもいられず……?', '2022/04/18 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/60e27faf-7ecf-4161-bf3d-3f005901cf03.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a9f48a8-1182-44ea-9a0e-1335f428977e', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 3, '100110326', '湯けむりの向こうがわ', '〈デア･イグニス〉を退けたセービルたちは旅の仲間にクドーを加えて再び実習先を目指すことに。道中、ロスから様々なことを学び、身につけていくセービル、ホルト、クドー。お互いに過去や素性も明かし、皆の間には少しずつ絆が芽生えていく。さらに旅を続ける一同は大きな町に到着。町にある大浴場で旅の汗を流すことにしたセービルとクドーの前に思いもよらない人物が現れて……!?', '2022/04/25 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d610553b-5350-4b52-a387-7517886a07b1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c17c7e9a-9012-4a71-9d6e-35fd88c74ed6', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 4, '100110797', '僕は死ぬのは怖くない', '猛獣のような見た目の“獣堕ち”に追われる少年ライオスを助け、実習先の村に辿り着いたセービルたち。村はずれの教会で出会ったのは、両目を眼帯で覆った神父だった。神父の話によると、実習生の監督官となる魔女は既におらず、村は2年前から別の魔女に支配されていると言う。神父に引き返すように言われ、実習を諦めそうになる生徒たちだが、ロスは神父が魔女の手下であることを疑って……。', '2022/05/02 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a1f4141c-8534-4772-84c3-584b456f1652.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9ec04c4b-e654-497a-9057-914a294cad5b', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 5, '100110967', 'ふさわしいかは自分で決める', '攫われたホルトを救出するため、洞窟に突入したセービルとロス。そこで2人を待っていたのはセービルの記憶に微かに残る泥闇の魔女だった。彼女は「君は特別な存在だ」と恐ろしいほどセービルへの執着をみせ、村を奪ったのも彼のためだと告げる。自分のために大切な仲間を傷つけられたと知り怒りを露わにするセービル。ロスと共に立ち向かうが、その場で特別実習に仕組まれたさらなる真実が明らかになり……!?', '2022/05/09 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e4b986ea-59ca-4a18-b20d-243511f08c81.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b47ff01d-aa93-4046-b1df-4fcca38390b0', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 6, '100111561', '無知の知', '実習先で試験に見事合格したセービル、ホルト、クドー。泥闇の魔女ことゼロの指導の下、改めて特別実習をスタートさせる。新たな課題は魔法を使った仕事で村に貢献すること。ホルトは便利屋を開業し、クドーは診療所で働く一方、魔力を供給する仕事を始めたセービルだったが、店に引き籠りがちになってしまう。その状況を心配したロスは、用事を頼みなんとかセービルを外出させるが……。', '2022/05/16 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91e374d0-a322-43fe-9d51-1ea762e4d8e1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9751812b-b49e-4be0-b579-4fff2501e3ba', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 7, '100113040', '僕には何も救えない', '魔法を仲間に当ててしまったホルトと、魔力切れで倒れてしまったクドー。落ち込む2人はさらなる成長のためゼロに相談しに向かう。しかし、あくまで魔力屋として振るまうセービルは、ゼロに「魔法使いを目指す気がないなら、君がこの村で学ぶことは何もない」と厳しい言葉をかけられてしまう。自分の進むべき道について思い悩むセービルだったが、ライオスと出かけた森で危機に直面することになり……!?', '2022/05/30 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8b92fd63-5031-4854-96a2-6a82631aec4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d13330c8-d760-4f87-8260-6ba6af1da6b8', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 8, '100113616', 'それぞれの代償', '森でセービルとライオスを襲った“災厄の残滓”。何者かが村に放った危険な存在に警戒心を高める一同。そんな折、魔法学校からホルデムがやって来る。「村の視察」が目的だと言う彼に、疑いの眼差しを向けるホルトたち。一方、森でライオスを守れなかったことで、改めて魔法使いを目指す決意を固めるセービル。しかし、何者かの手引きで村に侵入していた暴虐に連れ去られてしまい!?', '2022/06/06 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/85252e67-e473-4307-8206-fab57a0ffb4c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99c3e45e-3ca8-4047-b845-20876887acef', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 9, '100114331', '投げ込まれた石', '記憶を取り戻したセービルだったが、いまだに“誰かを好きになる”という気持ちが分からずにいた。しかし、ホルトから“好き”という感覚を教えられたセービル。「僕はロス先生のことが好きなのかもしれない」と自分の気持ちと向き合い始めた。そんな中、ゼロは自身の兄であり、セービルの父である魔術師“十三番”について語り始める……。', '2022/06/13 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/52f60329-2070-4d04-a7f8-b88e7f9f3023.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d5f98f5-b2bf-4321-8e58-9cecc254540a', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 10, '100114897', 'おやつのじかん', '教会の反魔女派から魔女の村に送り込まれた少年カディを監視するクドーたち。洗脳によって魔女や“獣堕ち”を敵視するカディだったが、しかし、リーリの作る美味しい食事や村での穏やかな日々は、彼の頑なだった心を溶かしていく。一方、魔法薬の実験をするセービルとロス。その最中、ストレートに好意を向けてくるセービルにタジタジになるロス。だがそんな平和な日常は急に終わりを告げる……。', '2022/06/20 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/549fa5d0-13fd-4c7c-bb0e-02ab6644f2c0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e5d3ebb-f8a4-44b7-aba2-cb963e4e9c29', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 11, '100115502', '殺す決意', '怪物となったカディを命懸けで止めたホルト、クドー、暴虐。その場に居合わせず、仲間の力になれなかったことに悔しさを滲ませるセービル。そんな折、魔女の村が反魔女派との戦場になるという知らせが届き、セービルたちはウェニアス王国への帰還を命じられる。村に残り戦おうとする一同だったが、ゼロからは命令に従わなければ退学だと告げられる。開戦の時が迫る中、彼らが下した決断とは?', '2022/06/27 12:00:00', 1451, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f178236-3f88-4e0a-bef7-d238b80a7da7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7da4d31a-9c06-4ece-b8d2-363ab3a99beb', '5a71ecfc-805d-437b-bc3d-41c1307f3e22', 12, '100116270', '冒険の幕開け', '【シーズン1 最終話】殺す準備を整えてくる敵に対して、殺さない準備を整えた村の面々。村には1万もの反魔女派の兵士が進軍してくるが、セービルたちが仕掛けた罠が敵を翻弄し次々と敗走に追いやっていく。そんな中、罠をかいくぐり、進軍を続ける“獣堕ち”の傭兵集団。セービル、ホルト、クドーは大切な場所を守るため、敵と正面から戦う覚悟を決める。さらに戦いの激しさが増す中、この騒動を招いた黒幕の正体が明らかになり……?', '2022/07/04 12:00:00', 1436, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e6b30ab8-7183-44fb-8b5e-c62743fd6aef.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7e11b7af-443c-4ebd-8e1c-5c2a3ff85a5c', '魔法少女 俺', '', 'hulu', 'magical-girl-ore', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/aca8b6bc-1970-4e92-894e-38948dc5cf21.png?w=331&h=447&p=t', 'hulu', 2018, 1, 1, 'FINISHED', NULL, 100715, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('7847f4ee-57a6-4226-8fbb-d8e6e16f2aae', '魔法少女にあこがれて', '', 'hulu', 'i-admire-magical-girls-and', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eab268b2-8729-47c3-a000-11896bfb054f.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 162780, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', '7847f4ee-57a6-4226-8fbb-d8e6e16f2aae', 'hulu-i-admire-magical-girls-and-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15fdfa57-5053-49e0-ac56-59e52e14d603.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cbebac69-6061-4d24-8e51-0150dffac156', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 1, '100171189', '悪の女幹部、誕生!?', '魔法少女に憧れる柊うてなは、ある日謎のマスコット･ヴェナリータに出会う。ヴェナリータの力で魔法少女に変身できると思ったうてなは、心を踊らせていた。しかし、変身後の姿は魔法少女とはほど遠い、悪の組織の女幹部そのものだった!?', '2024/01/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15fdfa57-5053-49e0-ac56-59e52e14d603.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4792d935-213e-44f9-95a5-33cba93e2d9b', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 2, '100171903', 'その名は、マジアベーゼ', 'ひょんなことから悪の組織「エノルミータ」の女幹部になってしまった柊うてな。彼女はトレスマジアとの戦いで内に秘めたるS心に目覚めると、新しく覚えたプレイをアズールたちに試していく。そして、そのプレイで悶える魔法少女たちの姿を見て、ベーゼは快感を覚えていき……!', '2024/01/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c8be10e8-ad48-4331-bf51-68c79f206610.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('510e7249-ddaf-499c-aacc-edcf44db660d', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 3, '100172720', '爆裂娘レオパルト', 'エノルミータの活動拠点「ナハトベース」でうてなが来るのを待ち構えていた阿良河キウィこと、レオパルト。どうやら彼女は魔法少女が嫌いなようで、魔法少女に負けてもヘラヘラしていたベーゼを敵視していた。しかし、ベーゼの一言で心をわしづかみにされてしまう。', '2024/01/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0985ca84-df58-4fd9-a50f-a48828dc29bb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d857db5-7800-4ae7-a559-c01a22348624', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 4, '100173567', '最強アイドル♡ トレスマジア', 'トレスマジアの活動は悪の組織「エノルミータ」を倒すだけではなく、メディア活動を行うなど多岐にわたる。そんなある日、雑誌の撮影を行っていたところへ、いつものようにベーゼとレオパルトが姿を現した。街の平和を守るために3人はバトルに挑む。', '2024/01/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5b16a7b-57a9-4196-8f54-b56e2cf40ac6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6ac281fa-3739-4470-b8b4-7d22bd024fc4', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 5, '100174617', '不思議の国のネロアリス', '再びヴェナリータに呼び出されたうてなとキウィ。ふたりがナハトベースに向かうと、「エノルミータ」に新しく加わった森乃こりすこと、ネロアリスがいた。ヴェナリータはネロアリスの力がどのようなものか、うてなとキウィに見てもらうためにトレスマジアの3人をおびき寄せることに。', '2024/02/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bbef3b3e-b1ba-4e1b-bb93-e0eb03a46f5b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ade641da-9aa7-4981-b44b-7a8bc1ea4e1b', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 6, '100175063', 'トレスマジア誕生秘話', '公園でひとりで遊んでいるこりすに話しかけるはるか。ふたりは人形でままごとをするまでに仲が深まった。しかし、一足先にはるかが帰ってしまい寂しく思っていると、こりすは何かを思いついたかのように変身して……。', '2024/02/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/665285e6-3c15-4320-8ebd-2c445071e61d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('252a2623-0894-499c-a1a1-c5c7a4a56532', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 7, '100175547', '逆境アズール', '最近のベーゼたちとの戦いにおいて、全く集中できていないと感じるアズール。このままではダメだと思い、気分転換を図り心機一転すると、覚悟を決めて再びベーゼの前に立ちはだかる。しかし、またしてもベーゼに弄ばれる快感に溺れてしまうことに。', '2024/02/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed07e8fa-6fbc-4a4b-8773-f0b76225d1c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('123ff6df-03e7-4ff9-b1a3-a14c92d39186', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 8, '100176191', 'ロード団、現る!', 'ベーゼたちは、魔法少女狩りから帰還したエノルミータの初期構成員のロードエノルメ、シスタギガント、ロコムジカ、ルベルブルーメの4人と顔を合わせた。世界征服を一緒に目指す旨の提案をされたマジアベーゼの返答にロードエノルメは激怒する。', '2024/02/28 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fdea1cbc-c8ee-4728-b3f7-9f0063840f07.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5e15c694-1bbe-44bf-afb0-5c84ef8fc61a', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 9, '100176919', 'アイドルにあこがれて!', 'アイドルになることを夢見るロコムジカ。そんな彼女が野外ステージで熱唱していると、ベーゼたちによる邪魔が入ってしまう。ロコは横にいたルベルと一緒にベーゼに立ち向かうも、徐々に形勢不利になっていく。そしていよいよ観念したロコはベーゼの要求に従い……。', '2024/03/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d2acc97c-e46f-439c-be2d-1299accac867.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c7a91af-18b4-45bd-8e34-55ecd2afd3ca', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 10, '100177701', 'ロコ×ルベ', 'ロード団から寝返り、ベーゼたちの仲間に加わったロコとルベルだったが、過去に魔法少女狩りをしていたことをベーゼに掘り起こされ、禊としてドールハウスに閉じ込められてしまう。ここから脱出するためには、よりふたりの仲の良さを深めなければならないようで……。', '2024/03/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6afb7256-7a96-40ae-8551-4f0f76347cf7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa9a32cb-cc13-459b-b13b-d6144a24e102', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 11, '100178287', '世界征服にあこがれて!', '世界征服の野望を企んでいたロードエノルメは、自身に真っ向から歯向かい、悪の組織でありながら市民たちを守ろうとするベーゼの行いに対して苛立ちが隠せない。一方で、世界征服に一切興味のないベーゼは、ロードを倒す手段を模索する。', '2024/03/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d255eeab-9c9a-4f7f-ab71-e428cc8ca95b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f40634fe-9330-4c69-8bdd-17d303bfd56c', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 12, '100178732', '総帥マジアベーゼの決断', '先の戦いでロードに勝利を収めたものの、心身ともに疲れ果ててしまったうてな。その戦いで街には甚大な被害をもたらし、魔法少女たちが大破した街を修繕する事態に。そんな中、目の前に現れたアズールの凛とした姿に感激したうてなは、元気を取り戻し――!', '2024/03/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/616b0bde-4ee2-40ca-8668-3e81ae6dac96.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ca7c5e43-28d2-43ee-84fd-c50a3142c999', '4c5ce77c-4fdd-46db-8c3d-2ad7e556887f', 13, '100179553', 'やっぱり魔法少女にあこがれて', '【最終話】バカンスで海にやってきたうてなたち。そこではるかたち3人とバッタリ出くわすと、仲良く夏の海を満喫していた。しかし、キウィの咄嗟の行動が仇となり、トレスマジアとエノルミータが大集合していた海は一瞬にして戦場に!? 今回もマジアベーゼが優勢かと思われたが……?', '2024/04/03 00:00:00', 1431, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c43d8a46-4076-4283-88c3-ec25f4ceee4d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('cbeb892a-dcf9-4244-9eca-960c43a7317f', '魔法少女まどか☆マギカ', '', 'hulu', 'puella-magi-madoka-magica', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/666c5410-a9c6-4717-a3cb-333133130fd5.png?w=331&h=447&p=t', 'hulu', 2011, 0, 1, 'FINISHED', NULL, 9756, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('22603262-dd13-41f4-9869-c5f0c701e3eb', 'cbeb892a-dcf9-4244-9eca-960c43a7317f', 'hulu-puella-magi-madoka-magica-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c35289f-45a7-488a-b631-7224229c9eb1.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a736a6f5-1306-474f-95f2-b691e03b456d', '22603262-dd13-41f4-9869-c5f0c701e3eb', 1, '100018739', '夢の中で会った、ような.....', '大好きな家族がいて、親友がいて、時には笑い、時には泣く、そんな平和な日々を送る中学二年生、鹿目まどか。ある晩、まどかはとても不思議な夢を見る。その日も訪れるはずだった、変わらぬ日常―。しかし、訪れたのは非日常―。まどかの通うクラスにやってきた、一人の転校生、暁美ほむら。まどかが夢で見た少女と瓜二つの容姿をした少女。偶然の一致に戸惑うまどかに、ほむらは意味深な言葉を投げかけるのだった…。', '2025/10/18 00:00:00', 1540, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c35289f-45a7-488a-b631-7224229c9eb1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75542fa8-e7a8-4903-b515-950579a3e48b', '22603262-dd13-41f4-9869-c5f0c701e3eb', 2, '100018740', 'それはとっても嬉しいなって', 'ほむらに襲われたキュゥべえを助ける途中、迷い込んだのは摩訶不思議な空間。絶対絶命のピンチに陥ったまどかとさやかを救ったのは一人の魔法少女。巴マミ。その後二人が誘われたのは、魔法少女の部屋。そこでマミは、キュゥべえに選ばれた者に与えられる資格について語る。魔法少女という存在、そして魔女という存在について。どんな望みをも叶えるチャンスと、その先に待つ過酷な使命。悩む二人に、マミは「自分の魔女退治に付き合わないか」と提案をするのだった。', '2025/10/18 00:00:00', 1540, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb7a4952-7404-4073-acee-d1bf66584e36.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ba55984-402c-4866-81f9-50aa19330b7f', '22603262-dd13-41f4-9869-c5f0c701e3eb', 3, '100018741', 'もう何も恐くない', 'マミの魔女退治体験コースにも慣れつつある、まどかとさやか。ただし、肝心な願い事は未決のまま。悩む二人に明かされた、マミの過去。「願いの内容が、自分のための事柄でなくてはならいのか?」と問うさやかに、マミは、厳しい口調で「他人の願いを叶えるのなら、なおのこと自分の望みをはっきりさせておかないと」と嗜めるのだった。翌日の放課後、恭介の見舞いに行ったさやかと付き添いのまどかは、その帰り道、偶然にも病院の駐輪場で孵化しかけたグリーフシードを発見する。放置すれば、大惨事になりかねない事態に、さやかはキュゥべえと共に見張りを、まどかはマミを助けに呼びに走るのだった。', '2025/10/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6d9c73d0-20d7-4710-af74-7956c3248fa4.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a8703ac9-5b8d-43e6-8f3d-87e297812c58', '22603262-dd13-41f4-9869-c5f0c701e3eb', 4, '100018742', '奇跡も、魔法も、あるんだよ', 'マミと魔女との壮絶な戦いの翌日、訪れたのはいつもと変わらない平和な日常。魔法少女の敗北の結果を目の当たりにしたまどかとさやかは、魔法の世界に関わったことの重さを実感し、魔法少女になることを諦める。その日の夕方、誰もいなくなったマミの部屋を訪れたまどかは、帰り道、マンションのエントランスでほむらと出会う。夕日の中、並んで歩く二人。魔法少女としての死ぬことの現実を語るほむらに、まどかは切ないほど優しい言葉をかけるのだった。', '2025/10/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f85ffc0e-3772-4e00-b174-a15cabcf2c4c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('05e6ca6e-e507-46eb-8125-b2173584ec1d', '22603262-dd13-41f4-9869-c5f0c701e3eb', 5, '100018743', '後悔なんて、あるわけない', '魔法少女として、魔女の手からまどかと仁美を救ったさやか。キュゥべえとの契約により願いを叶えた今、その心は清々しく、魔法少女となったことに後悔はない様子。恭介の両親、主治医、病院スタッフが集まり、病院の屋上で開かれたのは恭介の手の快復祝い。その光景を見たさやかは、至福の喜びをかみ締める…。', '2025/10/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd8ff4e7-ab22-471f-b81e-4afd9496cebc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d38b630b-410b-45e1-b008-6afb23d8678e', '22603262-dd13-41f4-9869-c5f0c701e3eb', 6, '100018744', 'こんなの絶対おかしいよ', 'さやかと杏子の戦闘現場に、突如現れたほむら。戦闘の仲裁に入った彼女はさやかを一撃で気絶させ、それを見た杏子はほむらを警戒し、その場を離脱したことにより、戦闘は終息する。翌日、杏子の乱入により取り逃してしまった使い魔の痕跡を探すさやかとまどか。戦闘の痕跡が残るその現場で、杏子との平和的な解決を提案するまどかと、命を賭けた魔法少女同士の闘いに覚悟を決めたさやか。二人の意見は擦れ違ってしまう。そんな二人のやりとりの一方、ゲームセンターでは、とある目的のため、ほむらは杏子と接触するのだった。', '2025/10/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/43a9f3b2-8831-4666-ab60-db64b3a88160.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70d3bc60-aa79-4f40-9a5c-927c465ead9d', '22603262-dd13-41f4-9869-c5f0c701e3eb', 7, '100018745', '本当の気持ちと向き合えますか?', '魔法少女となった自分の体の真実を知ったさやか。戦いの運命を受け入れてまで叶えた願いと、その代償の大きさの間で揺れてしまう。そんな自宅でふさぎ込むさやかの元に現れたのは、敵対していたはずの佐倉杏子。彼女はさやかを外へと連れ出し、とある廃墟の教会へと誘う。そこで杏子の口から語られたのは、自身が魔法少女となった理由。果たして彼女の真意とは―。', '2025/10/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/41b7488e-0976-48bb-acf5-a7786531a53b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1ecbb365-7fae-4195-b219-62beb3178a39', '22603262-dd13-41f4-9869-c5f0c701e3eb', 8, '100018746', 'あたしって、ほんとバカ', '自らの負傷も意に介さず、ただ目の前の魔女を切り刻むさやか。治癒魔法のおかげで最終的には無傷で魔女に勝利するも、もはや憔悴しきった様子。その帰り道、降り出した雨の雨宿りがてらの休憩中、憔悴しきったさやかの様子を見かねたまどかは、さやかの戦い方について、口を出してしまう。きれいごとばかりに感じるまどかのその言葉に、さやかはついに感情を爆発させ、その場を立ち去ってしまう。涙に暮れながら、それでも追いかけられないまどか―。雨の中をはしりながら、自己嫌悪に悔し泣きをするさやか―。彼女のソウルジェムは、黒く黒く濁っていくのであった。', '2025/10/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c34daf14-b5c8-4bfd-be74-62a9bd030e24.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e089d6ce-a6c3-4ea8-ba15-31ea90d8df26', '22603262-dd13-41f4-9869-c5f0c701e3eb', 9, '100018747', 'そんなの、あたしが許さない', '漆黒のグリーフシードと化したさやかのソウルジェム。そのグリーフシードは孵化し、新たな魔女が現れる。魔女の攻撃に防戦一方の杏子。魔女の結界に入ってきたほむらは杏子を先導し結界から脱出する。そして変わり果てた姿となったさやかの前で泣き崩れるまどかにほむらは冷淡な口調でソウルジェムの最後の秘密を語り…。', '2025/10/18 00:00:00', 1540, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b22c162-9b9a-46e9-bef4-f86570aeec75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5ad617d0-24b8-420c-a908-617100d5a591', '22603262-dd13-41f4-9869-c5f0c701e3eb', 10, '100018748', 'もう誰にも頼らない', 'それはとある少女の転校風景。必要以上に緊張し、萎縮する気弱そうな少女は、クラスの全生徒の視線を一身に浴びながら、慣れない自己紹介をする。休み時間、押しかけて興味津々に質問をしてくる女子たちに、気圧されておどおどしている彼女を、その場から連れ出してくれたのは、クラスの保健委員を名乗る少女。優しい笑顔を向ける彼女は、自分を名前負けだと感じる少女に対し、カッコいい名前だと言う。長らくの入院生活により、学力も体力も他の生徒に劣る彼女は、劣等感に肩を落として帰宅する途中、ふとしたことで魔女の結界に迷い込んでしまう。彼女の絶対絶命のピンチに現れたのは、二人の魔法少女だった。', '2025/10/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a062d0a-ddac-43ad-a049-8133300c074b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('60090bf9-ac7e-44d4-b861-e7462889c83e', '22603262-dd13-41f4-9869-c5f0c701e3eb', 11, '100018749', '最後に残った道しるべ', '雨の中、しめやかに行われたさやかの葬儀。うつろな目をして家に戻ったまどかは、玄関で出迎えた詢子への挨拶もそこらに自分の部屋に入ってしまう。一人悲しみに暮れるまどかの元に現れたのはキュゥべえ。さやかたちの死について冷たい口調で語るその姿に、さすがのまどかも怒りを感じる。そんなまどかの態度が理解できないキュゥべえは、自分たちと人類がこれまで共に歩んできた歴史を語るのだった。', '2025/10/18 00:00:00', 1540, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/35fc0223-cfc1-47f3-94dc-cdd9a7fcbda6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
