INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('a24c2922-d880-463a-aa29-2e3be0aec667', '437f5743-9fb1-4963-9357-44fa11277b56', 'hulu-miru-paths-to-my-future-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8c8c01c-f516-4218-8d94-09cf799d77f3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('999951dc-295e-4d05-a70d-8add7cbf7375', 'a24c2922-d880-463a-aa29-2e3be0aec667', 1, '100224461', 'Episode 079「スターダストメモリー」', '宇宙清掃員のヨシムラは、10年間スペースデブリの回収業務に携わってきたが、AI技術の進化により、上司から引退勧告を受ける。ヨシムラの後任として現れたのは、若き女性職員ウミだった。真剣に引き継ぎを受けようとするウミに対し、やる気のない態度のヨシムラ。そんな彼らに最高レベルの緊急事態が…。', '2025/05/08 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e8c8c01c-f516-4218-8d94-09cf799d77f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6a369fc5-cbe0-446c-a5fd-8c0b8c3dfd6b', 'a24c2922-d880-463a-aa29-2e3be0aec667', 2, '100224462', 'Episode 101「The King of the Forest」', '熱帯雨林地域で暮らすマリオは、森のツアーガイドとして観光客を案内する日々を送っているが、森の様子も幼い頃とは徐々に変わってきてしまっていた。そんなある日、マリオは金の違法採掘現場を目撃してしまい…。', '2025/05/08 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f0430c4a-0277-4638-b7d0-46857efda2be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b07312ba-d1bb-4757-9f02-30c965eb367f', 'a24c2922-d880-463a-aa29-2e3be0aec667', 3, '100224463', 'Episode 217「この世の波風さわぎ」', 'アメは、プロのピアニストを目指して音楽学校に通っている。学費を稼ぐために工事現場でバイトをしている彼女の密かな楽しみは、街角に設置されたピアノで演奏すること。ある日、ピアノの演奏技術を高く評価されたアメは、AI実証実験に協力することになり…。', '2025/05/08 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3aa008e5-251b-4feb-9a6a-0dfdac299ad1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('13bbc823-3e81-4539-bc05-761608685e04', 'a24c2922-d880-463a-aa29-2e3be0aec667', 4, '100224464', 'Episode 630「Re: MIRU」', '分断と紛争、温暖化が進む世界で、和平交渉を成し遂げ帰国した若き外交官トシ。しかし、一息ついたのも束の間、交渉決裂の知らせに希望は絶望へ。憔悴し街を彷徨う彼を救ったのは、冴えない中年サラリーマンだった――。', '2025/05/08 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6468426-fc79-4383-a616-f73e6fbfcd34.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('04814210-f412-494e-978d-1fb67ed150ac', 'a24c2922-d880-463a-aa29-2e3be0aec667', 5, '100224465', 'Episode 926「待ってて、今行く」', '【シーズン1 最終話】極寒の雪原が広がる終末の世界で、相棒のポチマルとともに旅を続けるアイル。旅の目的は、植物学者の母が残した「魔法の砂」で、世界中に綺麗な花々を咲かせること。旅の途中、枯れ木が茂る山中で、遠い未来からやってきたイズミフと名乗る少年と出会い…。', '2025/05/08 22:30:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/295869b7-a2c2-4526-8cd7-14d29cad1df3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f5e4ba80-dae5-41e8-9c41-a75ef2dd7112', '未来の黒幕系悪役令嬢モリアーティーの異世界完全犯罪白書', '', 'hulu', 'mirai-no-kuromakukei-akuyaku-reijyou-moriarty-no-isekai-kanzen-hanzai-hakusyo', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4fbe272c-2887-4a92-9322-d2aacd052057.jpg?w=331&h=447&p=t', 'hulu', 2024, 2, 1, 'FINISHED', NULL, 179954, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('af3a8fe3-bcc1-4e0e-a9b5-9317f7a68f16', 'f5e4ba80-dae5-41e8-9c41-a75ef2dd7112', 'hulu-mirai-no-kuromakukei-akuyaku-reijyou-moriarty-no-isekai-kanzen-hanzai-hakusyo-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/401ef8cb-0a00-4f56-a2e5-59e7c7520e75.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('70c6ab95-f335-4785-941e-5a4623411f54', 'af3a8fe3-bcc1-4e0e-a9b5-9317f7a68f16', 1, '100191472', '2人のモリアーティー', '最恐の犯罪者 ジェームズ＝モリアーティー。名探偵との戦いに敗れて命を落とした彼が目を覚ますと、自殺しようとする令嬢、シェリー＝モリアーティーに憑依していた。', '2024/07/20 12:00:00', 631, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/401ef8cb-0a00-4f56-a2e5-59e7c7520e75.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('493a5950-8100-42f6-b76b-6ddf5a6d89a1', 'af3a8fe3-bcc1-4e0e-a9b5-9317f7a68f16', 2, '100192523', 'シェリーの想い', '陰湿ないじめに遭い、もう、死ぬしか……と悲観するシェリー。記憶を失い、名前を思い出せないジェームズ＝モリアーティーはシェリーに問う。「君は自分に死んでほしいのか?」', '2024/07/27 12:00:00', 631, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/42cea8b1-c93f-4e34-84cc-59627b307eba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('896d5010-dde3-4c0a-99a5-4824039481b9', 'af3a8fe3-bcc1-4e0e-a9b5-9317f7a68f16', 3, '100194218', '完全犯罪講義 開始', 'シェリーの体を借り、寄宿舎内を見て回る教授。シェリーもコションと戦う覚悟を決める。そんなシェリーに対し、教授は“講義”を始める。', '2024/08/10 12:00:00', 631, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5d0f4996-4d00-4bfe-a058-30ddd71170b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('115d75b4-5ecd-454e-8b33-6f0bb8322bee', 'af3a8fe3-bcc1-4e0e-a9b5-9317f7a68f16', 4, '100195017', 'ミス＝フィアレディー', '教授の罠にかかったコションのもとにミス＝フィアレディーが現れる。シェリーに侮辱されたと主張するコションに対し、教授が用意した方程式とは……', '2024/08/17 12:00:00', 631, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b4e0de6b-3720-4b77-bf6f-9c8020070218.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4b3cca98-ec7f-4419-81cf-43a813084d7b', 'af3a8fe3-bcc1-4e0e-a9b5-9317f7a68f16', 5, '100195709', 'ジェームズの魔法', '野草採集に出かけたシェリーを追いかけ、井戸に落ちてしまうコション。そんなコションに対し、シェリーがとった選択とは……', '2024/08/24 12:00:00', 631, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de17b9ef-6b16-4382-80c4-b94a24ef408a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3292f15a-14d1-4640-ac5f-78348eb7e89b', 'af3a8fe3-bcc1-4e0e-a9b5-9317f7a68f16', 6, '100196300', 'シェリーの意志', '【最終話】不正解を正そうとする教授に自身の描く最高の令嬢は何かを説くシェリー。そしてシェリーはコションに仲直りしませんかと手を差し伸べる。', '2024/08/31 12:00:00', 631, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7666ab39-112b-4a1a-875c-38ca4c6a0066.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9f4f6ba6-2d92-4971-a20b-f4c5fe70ab28', '未来日記', '', 'hulu', 'future-diary', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3e6c17d6-3521-4f12-b9d4-d8eef0a0e9cb.jpg?w=331&h=447&p=t', 'hulu', 2010, 3, 1, 'FINISHED', NULL, 8460, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e947fe4b-64d4-4d63-86fe-2a6ccdd83318', '9f4f6ba6-2d92-4971-a20b-f4c5fe70ab28', 'hulu-future-diary-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d43098e8-e17c-420b-8f12-4df38a2f6490.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58cf4fec-d0e9-40c4-9bff-42443c529bce', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 1, '100041814', 'サインアップ', '友達付き合いをしない天野雪輝は、携帯電話で日記をつけるのが毎日の習慣となっていた。家に帰っても自室にこもり、ひとり空想にふける。そんなある日、いつも通り空想にふける雪輝の前に、デウスと名乗る時空を操る神が現れる。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d43098e8-e17c-420b-8f12-4df38a2f6490.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36d04576-228b-424e-83c0-7bd9b082e6e6', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 2, '100041815', '契約条件', 'サードを倒したことで他の日記所有者たちから狙われることになった天野雪輝。その雪輝が通う桜見中学校に9番目の日記所有者「雨流みねね」が現れる。仕掛け爆弾を使って雪輝の命を狙うみねねに対し、雪輝を守ろうと奔走する我妻由乃。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ba039d52-e2ef-4608-ab87-eeaa295e03e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('201452ea-9dd8-4e13-b429-9b2a6dc88b5e', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 3, '100041816', '初期不良', '天野雪輝と未来日記同盟を結んだ刑事「来須圭悟」。彼もまた4番目の日記所有者である。彼の指示で遊園地で遊びまくる雪輝と由乃。遊びの最中、由乃の女の子らしい仕草に思わず胸がドキドキする雪輝。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c9e771dc-5a93-4829-9b95-5289988851ce.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('82e39deb-0691-43d2-b52a-f47e139e1242', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 4, '100041817', '手書き入力', '雨流みねねが新興宗教の教団「御目方教」に拘束された事を知った来須、雪輝、由乃は、早速、教団内に入り込む。教団を率いる「御目方様」、春日野椿に面会した雪輝たち。そこで椿から驚くべき話を聞かされる。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bc24b92a-97cf-4efc-af39-2505e9d54821.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('561048d4-4641-4150-bc6d-411ad691f219', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 5, '100041818', 'ボイスメモ', '平坂黄泉が動き出した。千倍の聴覚と催眠術を駆使しながら雪輝たちに襲いかかる。由乃は雪輝と一刻も早く教団を脱出したい。ところが、椿の身を案じる雪輝は動こうとしない。いよいよ迫る黄泉の攻撃!', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6423521a-9fa7-4a0f-b893-f09dcbb785bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9e85ccc-89a0-4f83-a9ef-72e5d6e93310', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 6, '100041819', 'マナーモード', '久しぶりに雪輝の母親の天野礼亜が仕事先から帰宅した。その日によりにもよって由乃が家にやって来る。由乃の存在を母親に知られてしまった雪輝だったが、礼亜と由乃はすぐに仲良くなる。少し安心した雪輝だったが…。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/7a60a3b1-6b28-49c8-b2c8-4cebb4dbf459.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('36fcd7ed-f7bb-4e5c-b628-1b3a3a05f39a', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 7, '100041820', '留守応答', '三日間預かる事になった幼児、「豊穣礼佑」。両親の敵、我妻由乃の命を狙ってあの手この手で作戦を実行してくる。彼を日記所有者と確認した雪輝と由乃は、礼佑の日記を探そうとするも、何処にも見当たらない。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/13f2abf5-7e7f-4f8a-a68e-c6374e17315a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7cb6db0c-beac-4962-a4b6-05f6c9c028f9', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 8, '100041821', '新機種', '雪輝と由乃は、新しい学校に通う事になった。二人は別々のクラスに。友達が出来るか心配な雪輝。偶然、同じクラスには高坂王子がいた。相変わらずの彼の悪態に困惑する雪輝。そんな雪輝に「ともだち」が現れる。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df3b000f-9bd9-466a-8f12-0134bb0d306a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('114f2457-580a-401e-9dfc-8bee6632e2e7', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 9, '100041822', '着信拒否', '日向は雪輝の携帯と雪輝自身を人質に秋瀬と勝負することに。勝負はコインで決める。雪輝の未来日記「無差別日記」で未来を予知出来る日向の方に有利な展開かと思いきや、意外にも秋瀬の反撃に合う日向。動揺する日向。更に秋瀬は由乃と共同戦線を張って日向を追いつめる。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3306d1e3-ff12-4ca5-ac44-421acabc90f2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8ec9eac3-110c-4280-890e-f07a2ed9e610', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 10, '100041823', '家族プラン', '雪輝と由乃は、秋瀬によって結婚式の見学会に呼び出される。食事会に参加したり、試着をしたりする内に、段々その気になっていく二人。特に、雪輝は「あの事件」さえなければ、と思い始める。見学会を終えて由乃の自宅まで戻ってきた二人の前に現れる秋瀬。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/15456bc3-fdd3-41ec-8c82-f4dc4249834b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d3a6d850-02b1-4704-9af4-ecb68b26f26b', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 11, '100041824', 'サービス終了', '雪輝と由乃を桜見署に呼びつけた来須。このままだと二人を逮捕する理由がない。そこで来須が取った突飛な行動に驚く雪輝。刑事達に追われる二人。逃亡犯となった二人は病院に逃げ込む。そこで9thの雨流みねねと出会う。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/729141da-fff3-47b3-b0e2-9775766d2236.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('96de8cec-019f-4473-84f4-014271b3f455', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 12, '100041825', '受信圏外', '警察に包囲された雪輝と由乃とみねね。絶体絶命の中、来須の家族を人質に来須と交渉するみねね。だが、交渉は失敗。雪輝は捕まり、来須が迫る! 由乃と対峙した来須。由乃は、自身の命を投げうって雪輝を助けようとする。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d1222c37-40fa-47c8-90da-0104d1f754d1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4a004527-abc1-4997-ab38-18dfddcca208', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 13, '100041826', '非通知設定', '雪輝は由乃と二人で星を見に行く事になった。星が綺麗に見えそうな場所に着いた時、喉が渇いた由乃は雪輝にジュースを飲ませるのだった。一方、或、日向、まお、高坂の四人は快気祝いをかねて山間の温泉街へ旅行に来ていた。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/02802139-e70d-4121-93a8-27c5086ae7f3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d9a678c4-472e-4e17-b12d-ee14d5c4b290', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 14, '100041827', 'メモリー消去', '雪輝を監禁している由乃のトラップによって捕らわれてしまう日向。一方、地下室に閉じこめられてしまった或、まお、高坂の三人。絶体絶命の状況下で或は、由乃に向かって衝撃の事実を突き付けた!', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/47e20dfc-f5a1-4252-afcf-1424d60c45aa.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c73668f4-0a4e-4d7b-a76e-756bf3554a9d', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 15, '100041828', 'ダブルホルダー', '新たな敵8thの「孫日記」の秘密をつかんだ或は、雪輝を守るために高坂邸で敵の孫日記所有者たちを迎え撃つ作戦に出た。しかし作戦開始早々に予期せぬ停電が起きてしまい、敵の侵入を許してしまうのだった。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f51ec1ca-a545-4969-ab06-5c329b3ea01e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e603acdb-12cc-4c13-8f96-b93454c09d81', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 16, '100041829', '修理', '7thの襲撃によって負傷した雪輝は入院していた。そこへ父の「天野九郎」がお見舞いにやって来る。半年振りに父と再会した雪輝は、離婚してしまった両親が再婚して欲しいと願うのだが。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/18bd8241-3b05-4abf-912e-0e51c64a6af0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('09f74625-2b7d-4a90-ba5f-8428e5962980', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 17, '100041830', '家族割り', '倒壊を始めた「桜見タワー」はマルコと愛にとって特別な場所だった。二人の「ラブ」の力に圧倒されて、苦戦をする雪輝と由乃。一方、雪輝の事が心配で現場に駆けつけた礼亜は偶然、九郎と再会をして…。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fd2b8667-feff-4c38-b3ef-1d8360db01c6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e2955f63-e1cd-44ef-9de6-13f1038005ae', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 18, '100041831', '混線', '一年前、我妻由乃が天野雪輝のことを意識し始めていた頃、雪輝が書いたラブレターを偶然発見してしまう。相手は学級委員長の若葉萌絵。雪輝が彼女にラブレターを渡さないように変装したウサギの着ぐるみで邪魔をする由乃であった。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2dff998-b02d-4ccf-805c-3170ce361341.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3623caa1-5645-4f19-9345-51760686e46a', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 19, '100041832', '全件削除', '1stと2ndが消息を絶ってから五日。11thが不穏な動きを始めていた。因果律大聖堂に集合した残りの日記所有者たちの前で雪輝たちを排除しようと進言する。デウスによって二人の存在が抹消されそうになった時、間一髪で雪輝と由乃が現れて11thの正体を暴いた!', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/af5b07e0-aad2-4fa3-8aa9-e7acca9b9baf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c080aa9-81bf-4876-9d59-fd774629a6ac', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 20, '100041833', 'データ転送', '9th雨流みねねは、11thジョン･バックスを倒して「神」になるために、彼のいる桜見中央大学に単身で乗り込んだ。警備の隙を突いてドーム内に侵入したみねねなのだが、なぜか11thにすべての行動が読まれていた…。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/011a64ad-bc36-4ca1-88ac-2356b8470c19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('226201ca-fa1f-47c4-a625-8e37b6098642', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 21, '100041834', '暗証番号', '11thを倒すため一時共闘していた雪輝とみねねだったのだが、あと一歩のところで「クアッドタワービル」北塔32階の奥にある金庫室の中に逃げ込まれてしまった。作戦が失敗してしまい、西島を見殺しにされた怒りが収まらないみねねは、雪輝に襲いかかるのだった。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/397e43e0-479e-4a25-b376-05549e99f848.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74805f1b-d4d0-4938-84e8-79fda2e777d5', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 22, '100041835', '切断', '崩壊を始めた世界で、死んでしまった人間を生き返らせるために神になると決意した雪輝は、残りの日記所有者である8th上下かまどを倒すために、由乃と行動を共にしていた。その雪輝に「真実」を伝えるために秋瀬或がとった行動とは。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/febbff5d-740e-4fd5-83a0-fdfe6ccb94d0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4d78d3bf-f8f3-4061-b555-010d27afe109', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 23, '100041836', '契約不履行', '8thを倒し日記所有者は雪輝と由乃だけになった。そして由乃の携帯電話に「7月28日に世界が滅ぶ」と「ユッキーが由乃と結ばれる」と予知される。残りの時間、雪輝は由乃を疑いながらも、その気持ちに応えようとするのだが…。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b0ce9446-bd74-46ca-91d8-f4779dae8624.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('356447fd-7cbc-4d2b-97e1-58c3268faae9', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 24, '100041837', '検索中', '崩壊を始めた因果律大聖堂で雪輝と由乃は対峙していた。最後の勝者を決めなければ世界の崩壊が止まらない。由乃は「神」になってゲームをまたやり直すため、雪輝を突き落としてしまう。だが、由乃を愛した雪輝はボロボロになりながらも崖を昇っていた!', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/cd17ae9e-8ed7-4e23-9031-bf8c860a58da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('489a070b-efb8-45e2-bd8b-7eeac4c036f0', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 25, '100041838', 'リセット', '「神」になった由乃の力で、「サバイバルゲーム」は何度も繰り返されていた! 真実を知った雪輝は、「由乃」と「世界」を救うためにすべての始まりである「学校」へ向かう。悲しみと絶望が交錯する中、「神･由乃」との最後の戦いが始まった…。', '2019/10/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bfd1536f-ed65-47f7-b624-0dbb012aa421.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d0b7f974-c897-4964-ab44-2a463cc24541', 'e947fe4b-64d4-4d63-86fe-2a6ccdd83318', 26, '100041839', '初期化', '【シーズン1 最終話】「神･由乃」の力によって、雪輝は「幻覚空間」に閉じ込められていた。その幸せな空間で両親と念願の星を見に行くことになる。しかし雪輝は本当に愛する人の名前を忘れてしまっていた。両親が温かく見守る中、雪輝はすべてを思い出し、大声で彼女の名前を叫んだ!', '2019/10/24 00:00:00', 1414, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dfb6ef1f-9425-41bd-a5be-ed6ce291bd51.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f73a9602-947e-4c4f-a4f1-ed0605083a3e', '夢見る男子は現実主義者', '', 'hulu', 'the-dreaming-boy-is-a-realist', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a42f67c0-8712-4266-a2da-d700985bfad0.png?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 157397, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('ac563e03-6d5a-4fdb-84b4-78bed517f66a', 'f73a9602-947e-4c4f-a4f1-ed0605083a3e', 'hulu-the-dreaming-boy-is-a-realist-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b3e0925-ba70-4113-80ad-d2f7c381d3c3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8a6b6277-ace4-445b-9169-a2e21e85a5dd', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 1, '100150613', '好きだ。付き合ってくれ', '同じクラスの美少女･夏川愛華に恋焦がれる高校生･佐城渉は、今日も愛華につきまとい、熱烈なアプローチを続けていた。しかし、ある出来事をきっかけに愛華とは釣り合わないという“現実”を見た渉は我に返り、距離を取ろうとする。突然の変化に戸惑う愛華。さらに、そんな渉のもとに可愛くてちょっとチャラそうな女の子･藍沢レナがやってきた! それを見た愛華は、まさかの行動に――?!', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b3e0925-ba70-4113-80ad-d2f7c381d3c3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f12ca4ee-17de-49cf-87d1-6ce4fd585477', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 2, '100151288', 'どうぞ。スペアの三角チョコパイです', '愛華の魅力を布教することにした渉。そんな時、どういうわけか風紀委員長･四ノ宮凛が自分を生徒指導室で待っていると言う。そこで小動物のように可愛らしい稲富ゆゆも交え、三人で話すことに。一方その頃、渉がつきまとわなくなった愛華の元にはクラスメイトたちが集まっていた。週末に愛華の家に遊びに行きたいと周囲が盛り上がるなか、愛華の胸には一つの思いが湧き起こって――。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/84d289b1-08b5-4854-9f82-3df52035cecc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0968cc1d-4111-4c60-a5b2-ebea514aac35', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 3, '100151975', '夏服を薄着って言うのやめてくんない?', 'クラスの子と仲良くなってきていることを素直に嬉しく思う反面、胸の内ではモヤモヤを抱えていた愛華は、自分の感情もわからないまま、渉に不満をぶつけてしまう。突然のことに困惑する渉。そこに生徒会長･結城楓斗がやって来て、渉をある場所に連れ出す。そこで渉を待っていたのは――。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/91f54610-8ee6-4cac-9d70-17a8ef73de4a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('980851ac-8728-41ea-8f10-85a340629666', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 4, '100152741', 'ダークブラウン? なんかカッコ良い響きだな', '朝から姉･佐城楓に「小汚い」と伸びかけの髪の毛を指摘される渉。以前ほど身なりを気にしなくなったのも、愛華の隣に並ぼうとは思わなくなったからだった。昼休みにはなぜか風紀委員の美少女三人とランチを囲み、クラスメイトの佐々木からはある想いを打ち明けられる。一方、愛華は親友･芦田圭に諭され、あらためて自分の心情と向き合うことに。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/96777c07-b5e6-4200-9679-3e8bc3dbc996.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b27a607c-d006-40a1-961c-d1512ebd920a', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 5, '100153565', '開けちゃう? 開けちゃう? 中見ちゃう?', '体調を崩し、教室で倒れる渉。保健室で休んでいると、愛華と圭、さらには姉の楓や風紀委員長･凛までもが心配して様子を見にやって来た。楓や凛に安心して身をゆだねる渉の様子に、愛華は言葉にならない想いを抱く。数日後、金髪の美少女･東雲･クロディーヌ･茉莉花が取り巻きを引き連れ、愛華を訪ねてやってきた。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d9dd0a91-2461-4501-b7db-21555c03b0cf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bb949cb7-e176-40fe-b326-efd6b52315db', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 6, '100154117', '一学期終了記念パフェ!', '「風紀委員会に入らないか?」と四ノ宮凛に誘われ、思わず変な声が出る渉。さらに姉であり生徒会副会長である楓からも生徒会に入るよう誘いを受ける。一方、夏休み中に行われる中学生向けの学校見学の案内担当に佐々木とともに任命された愛華は、夏休みの予定を圭と話し合う。夏休みに入り、古書店でバイトを始めた渉。そこにお姉さんオーラをまとった大学生らしき女性･笹木風香が現れて……。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/69a11734-6f00-4e15-a32e-6bdd5578b99a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0aa4451b-b9a8-4b4a-b2fc-a5de06b463d7', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 7, '100155084', '女子大生って、マジすげぇ', '夏休み。渉は素敵なお姉さん風香と一緒に、海沿いの町･美白浜まで“特別なお出かけ”へ。二人きりのデートでも自然体の風香に女子大生の余裕を感じながら、渉はアクセサリー作りや浜辺の散策を楽しむ。同じ日、遊ぶ約束をしていた愛華と圭は、せっかくなら渉も誘おうと急遽佐城家を訪ねる。行き先はなんと、渉と同じ美白浜だった。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e2df1108-21e3-4f69-b66a-34553e33d20a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('368c5c2a-6d89-4553-b6d8-e8327fb7fa5a', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 8, '100155527', 'ギルティすぎない?', '渉がアルバイトをする古書店に、クラスメイトの一ノ瀬深那が新たに採用される。声も小さくオドオド、頼りなさ100%な深那に、渉はつきっきりで指導にあたるも、なかなか成長しない。向いていないバイト先を選んでしまった深那のためを思い、無理して続ける必要はないと伝えた渉に対し、深那はまさかの行動に出る。なぜそこまでしてバイトを続けたいのか? 渉は深那と向き合おうとする。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/272b0d7c-a933-46e3-bf4a-a3d496d838a8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('bad4ea1d-8ec8-4c57-bb4a-3a5d25197333', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 9, '100156478', 'コーヒー。8：2くらいでミルクね。砂糖小さじ1、キャラメルパウダーも宜しく', '深那がどうしてもアルバイトを続けたい理由を知った渉。それは渉にとっても共感できるものだった。人とのコミュニケーションが苦手だった深那も、常連客になった風香と次第に打ち解け始める。先輩として自分にできることはないかを模索し、深那と向き合うことで、渉自身もまた成長していた。一方その頃、学校見学の準備で、愛華は精悍さを増した佐々木と久しぶりに再会する。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0b7d9b2c-68b7-4ca3-b571-3a7b12626f4e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2e3ad042-90e4-467c-bc05-da361778e098', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 10, '100156955', '足がもう発射5秒前だから', '楓から学校見学の手伝いを頼まれた渉は、風紀委員会の助っ人として夏休み中の学校で凛と再会する。一方、愛華と佐々木も学校見学の案内役として、事前説明会のために登校していた。ぼんやりと中学生の頃の自分の生活や、渉との出会いを思い返す愛華。気付くと、誰かを探すように校舎のあちこちを眺めている。そして、遠くに渉の姿を見つけ――。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e90e1823-bf05-4c08-af62-5bfbc52ecd72.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee74414c-7e97-470a-8464-b86761713f13', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 11, '100157972', '汗のにおいがする……いっぱい働いたんだ', '久しぶりに二人きりの時間を過ごす愛華と渉。部活終わりの圭も合流し、近況を報告しあう。学校見学当日、中学の友人らと一緒に鴻越高校を訪れた風香の案内を終えた愛華は、勇気を出して渉にある提案をする。', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3e07704-503e-49c5-b4ae-eb7baf0ff775.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4fd51784-ddb8-4802-a218-63e76b35b59b', 'ac563e03-6d5a-4fdb-84b4-78bed517f66a', 12, '100158467', 'だって、アンタは私の居場所なんだから', '【最終話】雨の中、バイト先にやって来て、あらためて渉を自分の家に誘う愛華。初めて愛華の家を訪れた渉は、妹の愛莉や圭と一緒に楽しい時間を過ごす。その帰り道。友達も増え、憧れていたような高校生活を過ごしている愛華だったが、楽しい時間にも何か物足りないものを感じているという――。渉と愛華は、自分の気持ちに素直になれるのか?', '2024/04/01 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb2c8f4e-5aa2-4a16-9483-d0c3e802b17c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('879a0068-b600-4983-8b69-a2dc07fb8730', '夢中さ、きみに。', '', 'hulu', 'there-is-no-other', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca397634-faed-4b01-9ff8-102086e6e794.jpg?w=331&h=447&p=t', 'hulu', 2025, 2, 1, 'FINISHED', NULL, 183128, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('28d0d01b-6af7-40f7-ad54-47847fdaf8f4', '879a0068-b600-4983-8b69-a2dc07fb8730', 'hulu-there-is-no-other-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da0f2cf8-0d10-4b61-bbd9-24e9db9a177f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('21e3eb8e-e5de-4d12-9096-c7abeafd95fd', '28d0d01b-6af7-40f7-ad54-47847fdaf8f4', 1, '100235708', 'かわいい人', '中高一貫の男子校･鐘亀高校に通う江間譲二は、ここ最近、風変わりなクラスメート･林美良から変な絡まれ方をされている。きっかけは体育祭。借り物競走で「かわいい人」というお題を引いた江間は、なぜか林のことが気にかかり、一緒にゴールしたのだった。', '2025/08/24 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/da0f2cf8-0d10-4b61-bbd9-24e9db9a177f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d30a1401-e032-4a1f-b999-b8967e17e6b9', '28d0d01b-6af7-40f7-ad54-47847fdaf8f4', 2, '100236204', '友達になってくれませんか&描く派', '読書好きの松屋めぐみは、小説の感想をSNSに投稿していた。そこからハンドルネーム「仮釈放」との思いがけない交流が始まる。一方、鐘亀の中等部3年で美術部の小松豊は、なんとなくスケッチした高等部の林が気になり、モデルになってほしいと声をかける。', '2025/08/31 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3d73898e-0218-4769-a9a1-0c2c12bb449e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b2900fd-4c76-486b-9a62-090d0d794cf7', '28d0d01b-6af7-40f7-ad54-47847fdaf8f4', 3, '100237332', '走れ、山田!', '鐘亀高校1年の山田章太郎は、あるきっかけで2年の妹尾正広のパシリとなり、専属宅配弁当屋として昼飯を奢らされていた。妹尾からの理不尽な扱いに憤りを募らせる山田だが、その思いはいつも非常階段から自分たちを眺めている林にも向けられた……。', '2025/09/07 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3213dde3-e9ee-4e17-8c81-e295a6c5e850.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('eb623edf-789d-4ef6-a977-09c5d9239ab2', '28d0d01b-6af7-40f7-ad54-47847fdaf8f4', 4, '100237772', 'うしろの二階堂', '共学の戸塚高校に通う目高優一は、校内で忌み嫌われている不気味キャラ･二階堂明が後ろの席になり、憂鬱な気分を抱えていた。思いきって話しかけても、二階堂の反応は無愛想なまま。そんな時、目高は中学時代の二階堂が、今とは別人のようだったと知る……。', '2025/09/14 22:00:00', 1440, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1559678d-8e0e-4364-a66a-6ae988853c8f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c6d1472-8298-4596-b394-8e91c5b9c5de', '28d0d01b-6af7-40f7-ad54-47847fdaf8f4', 5, '100238338', 'うしろの二階堂 恐怖の修学旅行編', '【シーズン1 最終話】沖縄への修学旅行で、二階堂を自分と同じグループに入れた目高。二階堂は沖縄でも暗い表情と低いテンションを保ち目高を感心させるが、ホテルのロビーではソフトクリームを堪能し、「ふつう」でいようとメガネを外す。だが、逆にその姿で注目されてしまう。', '2025/09/21 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/de5d2963-0e80-4a1f-9274-a9b7768d48b0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('6fb9b67a-cf9a-4648-af1a-a939ec1838e3', '信じていた仲間達にダンジョン奥地で殺されかけたがギフト『無限ガチャ』でレベル9999の仲間達を手に入れて元パーティーメンバーと世界に復讐＆『ざまぁ！』します！', '', 'hulu', 'my-gift-lvl-9999-unlimited-gacha-backstabbed-in-a-backwater-dungeon-im-out-for-revenge', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/044c59c0-6e91-411a-b374-a63d53320344.jpg?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 184322, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e30e077f-a3e5-4f9e-98b6-106e68f9ca29', '6fb9b67a-cf9a-4648-af1a-a939ec1838e3', 'hulu-my-gift-lvl-9999-unlimited-gacha-backstabbed-in-a-backwater-dungeon-im-out-for-revenge-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb8d37af-6a1b-4d9a-a6a6-95c494376c2f.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9cced28c-5c1a-4130-8bfe-ada16cf86cec', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 1, '100240151', '裏切りと救い', '立派な冒険者を目指し、故郷を旅立った人種 (ヒューマン) の少年･ライト。だが、彼の恩恵 (ギフト) 『無限ガチャ』が生み出すのは、役に立たないガラクタばかり。結果、冒険者ギルドでは最低のF級にランクされてしまう。そんなライトに救いの手を差し伸べたのは、「種族間の差別をなくし、平等な世界を作る」という理念を掲げる『種族の集い』だった。彼は強力な冒険者パーティーに迎え入れられ、世界最大最強最悪のダンジョン『奈落』へと挑んでいたのだが――。', '2025/10/07 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb8d37af-6a1b-4d9a-a6a6-95c494376c2f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d66fbe6-7078-4e9b-97d5-fd3209b6c959', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 2, '100240695', '奈落', 'あれから3年…。ライトが『無限ガチャ』で呼び出したのは、真祖ヴァンパイア騎士･ナズナ、天才モンスターテイマー･アオユキ、禁忌の魔女･エリーといった、いずれもレベル9999の強者たち。そしてライト自身もまた、レベル9999へと到達し、『奈落』の最下層に、地上の全戦力･国家を殲滅し得る最強国家を築き上げていた。今日も訓練に励み、仲間たちの様子を見回るライト。そんな中入ったメイからのある報告が、ついに復讐の始まりの合図となる――。', '2025/10/14 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/26d7cb62-7490-4f83-a2bc-90da97999df1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('287a5409-5273-4d40-b6ae-1533be5ded13', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 3, '100241143', '破滅の王', '獣人連合国ウルフ種主要都市･アクラ。元『種族の集い』のメンバー、ガルーは意気揚々と街を歩いていた。いまや彼は、ウルフ種族長からも認められた次期族長の最有力候補。酒を浴びるように飲み、気ままな日々を送っていた。そこへかつてライトに仕えていたという人種 (ヒューマン) のメイドが声をかけてきた。彼女は、ライトが最期を遂げた場所を案内してほしいという。ガルーは警戒しつつも、この奇妙な依頼を引き受ける。だが、『奈落』で彼を待ち受けていたのは――。', '2025/10/21 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/857c6d20-e478-45e7-9054-0fceafc2d3b9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6515eac-e155-4bf5-8556-3fa7b42b989e', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 4, '100241959', '冒険者', 'ガルーの反応を見て、自らの力が世界に通用すると確信したライト。しかし、各国の戦力を把握しないまま戦いを挑むことには危険が伴う。そこで冒険者としてランクを上げ、各国の情報収集を行う作戦を計画する。ゴールドとネムムを伴い、ドワーフ王国最南端の街『ダガス』へと訪れたライトは、早速ギルドに登録。しかし、向かったダンジョンの入り口は多くの冒険者たちで大行列。ライトたちも列に加わるが、あるパーティーが割り込みをしているところを見つけて…。', '2025/10/28 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf2d479f-4cd7-4a8e-867a-fc334ae39c19.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('aa315113-7618-445a-847d-8677373e5521', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 5, '100242777', '小さな願い', 'ライトたちの前にあらわれたのは、レベル500の強敵『フォーサイス･マンティス』。ギルドの冒険者たちが総出で戦わなければ倒せないと考えるエリオに対し、ライトたちは瞬く間にマンティスを撃退する。その夜、ライトとエリオたちは野営地で共に過ごし、信頼関係を深めていくのだった。一方、3階層まで進んでいたカイトとヤナークはある実験のために、人種 (ヒューマン) を次々と襲っていた――。', '2025/11/04 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/44237397-0272-44ad-acf9-45ae2f29bded.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ba352406-e51b-40a9-8cc4-8b507eed94e4', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 6, '100243767', '冒険者殺し', '短期間でD級へとランクアップしたライトたち。さらなるランクアップをギルドに要求するネムムだが、短期間でのC級へのレベルアップは前例がないという。さらに大きな功績をあげるために、ライトは人種 (ヒューマン) を狙った『冒険者殺し』の討伐クエストに挑もうとしていた。そのとき、ライトたちは宿の部屋で異様な気配を感じ取る。天井に突如として発生した空間の歪みからあらわれたのは、ズタボロになったミヤだった。', '2025/11/11 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c22c3df4-f3c9-4935-9e14-9b668bab0295.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('436cd194-a45d-40f3-88f1-ade67822524a', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 7, '100244966', 'ありがとう', 'ヤナークが自身の実験で生み出していたのは、人種 (ヒューマン) とモンスターの融合種だった。その非道な実験に、怒りを抑えきれないライトたち。ゴールド、ネムムが融合種と戦う中、混乱のスキをついてカイトがライトに攻撃を仕掛けてきた。軽くあしらうライトだったが、カイトがマスターの血を引く『さぶますたー』と知って、『奈落』で情報を聞き出すことを決断する。一方、カイトは宝剣『グランディウス』最大最強の奥義で、ライトを圧倒しようとするが…。', '2025/11/18 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5384528-352e-4561-8e89-e462255f9077.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('727c9989-de3d-4cf7-a581-fd42566131cd', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 8, '100245809', '白の騎士団', 'エルフ種のサーシャは、『白の騎士団』副団長のミカエルと婚約し、幸せな時間を過ごしていた。そのころ、ライトたちはエリーとともに『サーシャ復讐作戦』を実行するために、エルフ女王国へと潜入。サーシャへの復讐だけではなく、『さぶますたー』の集まりである『白の騎士団』を確保し、『ますたー』の情報を引き出すことも目的のひとつであった。エリーはエルフ女王国の首都近郊に謎の巨塔を出現させ、サーシャと『白の騎士団』を誘い出そうとするが…。', '2025/11/25 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0fef1129-481d-46dc-b30e-a35fc4dde93f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1f3e260d-0472-445e-bd30-5635acd94b9d', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 9, '100246266', '開宴', 'ライトは4人の強力な仲間、アイスヒート、メラ、ジャック、スズと合流。巨塔にてエリーたちとも再会し、『サーシャ復讐計画』がついに幕を開ける。この計画はサーシャへの復讐が目的であると同時に、エルフ女王国最強の『白の騎士団』と戦い、『奈落』の実力を測るという狙いもあった。ライトが意図的に流した情報により、騎士団は巨塔の制圧に動き出す。案内役を買って出たサーシャは、密かにライト抹殺を企てていた。', '2025/12/02 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e084553e-f4f9-466c-846a-c005b6f7f148.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6771360-6797-4316-9d67-3343027046e8', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 10, '100246959', '巨塔の戦い', '巨塔に入ると同時に、転移トラップによって各階へと飛ばされた『白の騎士団』のメンバーたち。1階ではメラとアイスヒートが、ニアとキアと相対していた。圧倒的なスピードで、メラとアイスヒートを翻弄するニアとキア。絶え間なく繰り出されるウィンドカッターは、ついにメラの右腕を奪い去った。そのころ、2階ではスズがシャープハットと対峙していた。『不可視のクロスボウ』によって、シャープハットはスズを追い詰めるが…。', '2025/12/09 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2863cdf3-afa6-4f1b-881f-479eec5dc91a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9bdd281-f6eb-4524-9c1d-72b0dc81bbaf', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 11, '100247581', '神葬グングニール', '巨塔の4階では、『白の騎士団』最強の団長ハーディーと、『奈落』最強のナズナが相対していた。少女ながら大剣を軽々と扱うナズナを、相当の実力者だと警戒するハーディー。だが、ナズナの超人的パワーは想像以上だった。一方、5階には、サーシャとミカエルが飛ばされていた。仮面を外し、素顔をさらけ出すライト。本当に自分のことを待ち受けていたライトとの再会に、愕然とするサーシャ。復讐計画はついに最終局面へと突入する。', '2025/12/16 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e83101ab-b798-4623-aeee-6f3813e8aab5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ae6b3ba2-242c-44bc-addc-acb20a106075', 'e30e077f-a3e5-4f9e-98b6-106e68f9ca29', 12, '100248408', '新たなる道へ', 'ミカエルとサーシャの挑発に対し、ライトは創世級 (ジェネシスクラス) の武具『神葬グングニール』の封印を第一限定解除。天使たちに絶大な効果を示し、『天使のオカリナ』と『祝福と天罰』をまたたく間に破壊する。逃亡を図るミカエルたちだが、転移阻害魔術が発動。さらに、最後の頼みだった『白の騎士団』の全滅を目の当たりにし、絶望の底へ。ミカエルにも裏切られ、命乞いするサーシャに、ライトが下した決断とは――。', '2025/12/23 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c3d034eb-6310-4179-9ed7-d113410f0372.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('9348a2ea-dd04-43db-968f-ad9395f450ec', '無限の住人', '', 'hulu', 'blade-of-the-immortal', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/116d173d-3d4f-4ede-aad6-1e26eda7b397.png?w=331&h=447&p=t', 'hulu', 2008, 2, 1, 'FINISHED', NULL, 4151, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1c39506f-2964-46fe-a7d7-ca754ece238c', '無職の英雄 別にスキルなんか要らなかったんだが', '', 'hulu', 'hero-without-a-class-who-even-needs-skills', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4990c58c-514b-4466-a380-b66ea4d5f92b.png?w=331&h=447&p=t', 'hulu', 2025, 3, 1, 'FINISHED', NULL, 169969, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('678ecc91-f787-4866-9cd0-452bf1166234', '1c39506f-2964-46fe-a7d7-ca754ece238c', 'hulu-hero-without-a-class-who-even-needs-skills-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6519f399-48ff-4959-960d-ef68ab8348fd.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('135652ec-14fd-4214-aaf9-a7cb3c2d351d', '678ecc91-f787-4866-9cd0-452bf1166234', 1, '100239497', '無職宣告', '『剣姫』ファラと『魔導王』レオンの間に生まれた少年アレルは、あろうことか『無職』の烙印を押されてしまう。しかし、アレルは自身が『無職』であることなど一切気にせず、努力を重ねることで周囲を圧倒していく。そんなアレルに、自警団長の子で『剣士』のライナが勝負を挑んできて――。', '2025/10/01 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6519f399-48ff-4959-960d-ef68ab8348fd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e8d01d35-f5e0-4611-8a8a-c06e7cc5274b', '678ecc91-f787-4866-9cd0-452bf1166234', 2, '100240435', '剣の都市ブレスギア', '『無職』認定されてから五年後。剣士のスキルを学ぶため、剣の都市プレスギアへとやってきたアレルは剣士ギルドに所属しようとするが、どこに行っても門前払いされてしまう。そんななか、諦めずにギルドを探すアレルの前に、リリアと名乗る少女が現れる。怪しげなリリアの誘いを断るアレルだったが、彼女のギルドはかつてアレルの母である『剣姫』ファラが所属していた『ドラゴンファング』だと判明するのだった。', '2025/10/08 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9ed358e9-e6c5-46df-a127-7cca28db0c7d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8135f4e0-65df-4291-8f17-62967643d568', '678ecc91-f787-4866-9cd0-452bf1166234', 3, '100240534', 'ギルド対抗戦', 'リリアの独断で、ギルド対抗戦にエントリーされてしまったアレルとライナ。対抗戦に勝利し、賞金を手にしなければギルドを維持していくことが難しいのだという。対抗戦に向けて修行を行うアレルとライナたちだったが、なんと初戦の相手がプレスギア最強のギルド『ブラックブレード』と判明。しかも、それは仕組まれた組み合わせなのだった――。', '2025/10/15 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a90f5f99-45ce-497a-bc9e-cb0ce9aecfc9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9755af86-b5eb-430d-8ec7-3f47b26cb1fc', '678ecc91-f787-4866-9cd0-452bf1166234', 4, '100240535', '地下ダンジョン', '『ブラックブレード』に見事勝利したアレルたち。しかし、アレルたちは後日控えた剣神杯に備えてより強くなる必要があると考え、プレスギアの地下に存在するダンジョンに挑むことに。ダンジョンで魔物と戦い打ち破っていくなか、アレルたちは血まみれで助けを求める青年ディールと出会う。彼とそのパーティは凶悪なトラップで全滅し、仲間はいまだにダンジョンの奥で助けを待っているらしい。リリアとライナは、彼らの救出を決断するが――。', '2025/10/22 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/39156878-feb8-47c4-a05a-5d7f303f4bd7.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('80444f5a-c9e2-4a68-a492-174c09be1e06', '678ecc91-f787-4866-9cd0-452bf1166234', 5, '100240536', '剣神杯', 'いまや弱小ギルドである『ドラゴンファング』に所属しながらも、着実に剣神杯を勝ち進んでいくアレル。『無職』であるはずのアレルに多くの人々が注目するなか、ついに決勝戦でアレルと『ブラックブレード』のリーダーにして『剣帝』でもあるゲオルグとの試合が決定する。だが、怪しげな剣を手にしたゲオルグは、以前とは別人のような姿で現れるのだった。', '2025/10/29 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c4cfbcda-5187-4607-8cf7-08718d7abf92.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b57cca6a-e42e-4134-b469-5818cbe3eb67', '678ecc91-f787-4866-9cd0-452bf1166234', 6, '100240537', 'アレルの帰省', '剣神杯を制したアレルは、故郷の村に戻っていた。その目的は家族に元気な姿を見せること、そして母であるファラへと挑戦することであった。経験を積んだ今であれば、ファラをも越えられるはずだと、アレルは覚悟と共に剣を抜く。一方、『ドラゴンファング』で共に過ごしていたライナは、何の相談もなくギルドを去ったアレルに怒り、アレルと同じ故郷の村を目指していた――。', '2025/11/05 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4482b650-429d-4e3c-80f7-945dbee52ae2.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ece64da1-93ed-4d53-9a8e-570055121196', '678ecc91-f787-4866-9cd0-452bf1166234', 7, '100240538', '魔法都市アルスベル', '剣技を極めたアレルは、父であるレオンから魔法を学ぶ。そして、さらに深く魔法を学ぶべく、魔法都市アルスベルの魔法学院へと向かうのだった。道中、アレルは同じく入学を希望するカイト、コレット、クーファの三人と出会う。『無職』であるにも関わらず魔法学院に入学しようとするアレルは、年下のカイトたちからも冗談だと思われてしまうが、道中でのトラブルなどを経てその仲を深めていく。', '2025/11/12 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b9d3304c-627a-4997-b757-3f19f3abc158.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7bc40cf9-db17-488f-a32b-f5df3c700edb', '678ecc91-f787-4866-9cd0-452bf1166234', 8, '100240539', '魔法学院', '赤･青･緑･黄･白･黒。六つすべての魔法学院への入学を果たしたアレル。赤の学院では火の魔法術式をアレンジし、緑の学院でも自分なりの飛行魔法を編み出そうとするなど、アレルはここでも周囲の人々を驚かせていく。そしてアレルは赤の学院の教師バッカスの推薦で、通常は二年後に行われる進級試験を、一年生にも関わらず受験することとなるのだった。', '2025/11/19 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/166a4bf8-dfe4-4993-8571-7158f56f8013.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2a9f49f4-2015-4c04-a533-dc9e86c9c9ef', '678ecc91-f787-4866-9cd0-452bf1166234', 9, '100240540', '飛行レース', '青の学院でも早い進級を望むアレルは、その態度が失礼だと教師ヘンゲルを怒らせてしまう。アレルに思い知らせるためヘンゲルが提案してきたのは、魔導王候補の実力者でもある、自身との模擬戦であった。また、アレルは緑の学院での進級も希望するが、学院長グリンの多忙により検討すら断られてしまう。しかし、近く行われる飛行レースの優勝者であれば、グリンと会える機会があると知り――。', '2025/11/26 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e7390bf-1b3e-4e2f-aaa8-2bc0de2ea867.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('651a8414-0c79-45b1-bbd0-1c9008095cf6', '678ecc91-f787-4866-9cd0-452bf1166234', 10, '100240541', '悪魔の契約', '黄の学院の研究発表会への参加登録をうっかり忘れてしまったアレルは、教師ログウェルの機転により、研究助手として発表会に参加する事になる。しかし、ログウェルは毎回生徒を対戦相手に選んでは、容赦なく叩き潰すことで有名な問題教師であった。そして発表会本番。自信満々に自分のゴーレムを見せつけるログウェルに対し、アレルが披露したのは――。', '2025/12/03 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dbcb6d5e-c34f-42e6-99ee-0018916881e6.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47ec7ae5-539b-4762-84a6-04426a2dc009', '678ecc91-f787-4866-9cd0-452bf1166234', 11, '100240542', '無職の英雄', '予算を削られ続ける黒の学院。上層部の判断は正当なものであったが、黒の学院長ブラグは逆恨みによって魔界の魔物･グラトニースライムを召喚してしまう。すべてを喰らうグラトニースライムに、魔法も効かないどころか吸収されてしまい、魔法都市の人々はなすすべもなく追い詰められていく。しかし、誰もが諦め、絶望したその時、無職の英雄が立ち上がる。', '2025/12/10 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f6694b81-dd84-4da9-b216-414c96e266b8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c76d79f4-bbac-4496-88d0-dedda436042f', '678ecc91-f787-4866-9cd0-452bf1166234', 12, '100240543', '女皇の皇国', '【シーズン1 最終話】魔法都市から去り、故郷を目指すアレルは温泉宿へと立ち寄るが、謎の刺客たちと遭遇する。彼らは皇国の八将軍を名乗り、女皇の命令でアレルを皇国に連れていくのが目的だと語る。当初は興味がないと断るアレルであったが、とあることに気付き、女皇の待つという皇国へと向かうのだった――。', '2025/12/17 22:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/79700004-b49d-4391-8dee-958f6c8732ff.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('2e1bdee0-7cbb-4b2d-9b63-0cc19c22e8c8', '無職転生 ～異世界行ったら本気だす～', '', 'hulu', 'mushoku-tensei-jobless-reincarnation', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/819b7484-9df8-4dd4-bfa1-9a498eceef4e.jpg?w=331&h=447&p=t', 'hulu', 2021, 0, 1, 'FINISHED', NULL, 108465, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('e5653a04-5603-4824-93ad-4040dc43eecf', '2e1bdee0-7cbb-4b2d-9b63-0cc19c22e8c8', 'hulu-mushoku-tensei-jobless-reincarnation-s1', '第1クール', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a22ea9c-b571-4b80-947e-b53e4e724d7c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b2b57f7b-3cdf-4fc9-b75e-66f945b61fff', 'e5653a04-5603-4824-93ad-4040dc43eecf', 1, '100073217', '無職転生', '34歳･童貞･無職の引きこもりだった男は車に撥ねられ、その一生を終える……はずだった。しかし、男が次に目を覚ましたとき、そこは剣と魔法の異世界であった。少年･ルーデウスとして転生した男は考える、この世界ならば、自分も本気で生きていくことができるかもしれない……と。', '2021/01/16 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5a22ea9c-b571-4b80-947e-b53e4e724d7c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('74d0a905-ddae-4e94-94ce-272d6d155218', 'e5653a04-5603-4824-93ad-4040dc43eecf', 2, '100073549', '師匠', '3歳という幼さで魔術の才を見せたルーデウスに、家庭教師が付くことになった。無愛想でジト目のロリっ娘なロキシー師匠による魔術の授業で、めきめきと成長するルーデウス。そして月日が流れ、ルーデウスはロキシーにある試験を課される。しかし、その試験のためにはルーデウスは前世のトラウマを乗り越える必要があった。', '2021/01/23 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/832907cb-501e-4b92-8374-c651ccecddf9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f9ff5007-e23b-40d3-afb8-6114a6d47f0f', 'e5653a04-5603-4824-93ad-4040dc43eecf', 3, '100074065', '友達', '村はずれでいじめの現場を目撃したルーデウス。その光景に前世の苦い記憶を思い出しながらも、いじめられていた子供･シルフを助ける。前世でできなかったことを少しずつ“やり直す”と決めていたルーデウスはシルフと友達に。この世界で初めての友達に魔術を教え始めるのだが……。', '2021/01/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5cd28f43-cc1f-475f-80a9-5c374d3764f0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97f4e689-45a5-4f89-a343-561d2c62144b', 'e5653a04-5603-4824-93ad-4040dc43eecf', 4, '100074539', '緊急家族会議', 'ルーデウスの母･ゼニスの懐妊に、喜びに沸くグレイラット家。だがそのひと月後、メイドのリーリャまで妊娠していることが発覚する。しかもその父親はあろうことか…。修羅場必至、一家の一大事に直面したルーデウスは機転を利かせて……。', '2021/02/06 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bf5c97ab-6964-4d00-adee-6c424f457c99.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('4ac431b8-b22b-4afc-bece-be0a370a2073', 'e5653a04-5603-4824-93ad-4040dc43eecf', 5, '100075374', 'お嬢様と暴力', 'パウロによってロアの町に送られたルーデウスは、パウロの知り合いであるギレーヌに連れられ、ボレアス家の息女･エリスの家庭教師を務めることになった。しかし、そのエリスは一筋縄ではいかない暴れん坊お嬢様で、ルーデウスは傍若無人なエリスを躾けるため、ある計画を実行するのだが……。', '2021/02/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ff9f4340-a7bb-4393-bf6e-bd6c5826cf2a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1cb0c463-a12e-4b7b-a1c6-e2446be138ad', 'e5653a04-5603-4824-93ad-4040dc43eecf', 6, '100075888', 'ロアの休日', '誘拐事件が幕を閉じ、正式にエリスの家庭教師として働くことになったルーデウス。エリスとギレーヌに算術や魔術を教える傍ら、ギレーヌから剣術を教わるというハードながらも平穏で充実した毎日が続いていた。しかしある日、休みのない授業のストレスでエリスが再び狂暴になってしまい……。', '2021/02/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a540a8be-0d61-49f9-a3c9-84ce73927266.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fc8341c8-57bd-4d1c-ad9a-09f397597823', 'e5653a04-5603-4824-93ad-4040dc43eecf', 7, '100076369', '努力の先にあるもの', '10歳の誕生日を迎えるエリス。その日には盛大なパーティーが開かれる予定だが、エリスはダンスが大の苦手。そんな彼女のために、ルーデウスは練習に付き合う。その甲斐あってエリスは次第に上達していく。そして誕生日当日が近づくある日、ルーデウスのもとにロキシーから手紙が届き…。', '2021/02/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b2a7c463-6252-4d92-b40b-5c8118683fd9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c689a88d-d1a3-4930-9a3d-4db5652a24ea', 'e5653a04-5603-4824-93ad-4040dc43eecf', 8, '100076860', 'ターニングポイント1', 'ルーデウスがボレアス家に来て3年が経ち、エリスたちはルーデウスの10歳の誕生日を祝うためにこっそりとパーティーの準備を進めていた。ルーデウスはエリスたちのサプライズに気づきながらも、知らないふりをして迎えた誕生日当日。ボレアス家の心のこもった誕生パーティーのあと、ルーデウスが自室に戻るとそこには意外な人物の姿が…!?', '2021/03/06 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/3caadb2d-b0a6-4d8b-81f3-1b8a35049226.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('58848d6c-2d4c-4f5a-a88d-6845c04407a2', 'e5653a04-5603-4824-93ad-4040dc43eecf', 9, '100077535', '邂逅', '謎の光に包まれたルーデウスの前に、神を自称する存在“ヒトガミ”が姿を見せる。ヒトガミとの邂逅を終え、次にルーデウスが目覚めると、そこは魔大陸の荒野だった。さらにそこにはひとりの男の姿が。その男は、かつてロキシーから「絶対に近づかないように」と教えられたスペルド族の特徴である緑色の髪と額に宝石のような石が付いていて――!', '2021/03/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e126fe5a-7fb4-4084-8573-976c66192e8b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('942b8057-a0f4-4cdd-af90-f7c4fb0f5e89', 'e5653a04-5603-4824-93ad-4040dc43eecf', 10, '100077988', '人の命と初仕事', 'ルーデウスたちはミグルド族の村を離れ、リカリスの町へと向かう。町の検問で、ルイジェルドが“デッドエンド”として恐れられていることを実感したルーデウスは、スペルド族汚名返上の作戦を思いつく。', '2021/03/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/98502c0a-ea5a-4bb0-84b5-22469cd063bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9cc34ce-3908-448a-a4d1-3d59a51f0c94', 'e5653a04-5603-4824-93ad-4040dc43eecf', 11, '100078429', '子供と戦士', '【第1クール 最終話】ルーデウス、エリス、ルイジェルドがギルドの魔物調査の依頼で石化の森へ向かうと、そこには同じ依頼を受けた2組の冒険者がいた。早い物勝ちで依頼を遂行しようとする中、ルーデウスはある判断を迫られる。一方、ロキシーは転移事件が起きたフィットア領にあるルーデウスの家を訪れるが…。', '2021/03/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f309cb5a-8937-4456-b9ee-9058bad69f76.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', '2e1bdee0-7cbb-4b2d-9b63-0cc19c22e8c8', 'hulu-mushoku-tensei-jobless-reincarnation-s2', '第2クール', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2a2fbd1-e017-4867-b816-d515e811b4d3.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cbe89cb5-6375-4180-8b30-efb00e2ac6f3', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 12, '100093661', '魔眼を持つ女', '魔大陸最南端の港町･ウェンポートに到着したルーデウスたち。3人は船でミリス大陸へ渡ろうとするが、スペルド族がいるという理由で途方もない渡航費用を請求されてしまう。その夜、資金不足に悩むルーデウスの夢にヒトガミが姿を現すと、彼に助言を残していく。翌日、ルーデウスが町の中を散策していると、お腹をすかせた謎の少女と出会う。', '2021/10/09 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f2a2fbd1-e017-4867-b816-d515e811b4d3.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('1d787116-ec52-41d5-a3eb-6ec948aa6e06', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 13, '100094222', 'すれ違い', '行方知れずのルーデウスたちを探していたロキシー。彼の父･パウロの知り合いであるエリナリーゼ、タルハンドと共にウェンポートにやってきたロキシーは、手がかりを探す中で、悪名高いデッドエンドの噂を耳にする。一方、ルーデウスたちは密輸組織のガルスと取引し、アジトにいる奴隷を解放することを条件に念願のミリス大陸へ渡るのだが……。', '2021/10/16 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5e995f44-61e3-4c30-a2bd-ccab57a23702.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0f139162-7aeb-436c-9743-2e3a40ff1f4f', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 14, '100094611', '只より高いものはない', '無実の罪で獣族の村に捕らえられてしまったルーデウス。エリスとルイジェルドが迎えに来てくれることを期待する中、そこへギャンブルのイカサマが原因で魔族のギースが同じ牢に叩き込まれてくる。ギースと話しながらルーデウスは脱獄の可能性を探るが、突如村に密輸組織の一団が襲い掛かってくる。', '2021/10/23 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d19ee3e3-b104-4268-848a-465fb22ed7ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('17c4fd82-af02-4bb3-bc45-3abe14a15bff', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 15, '100095205', 'ドルディア村のスローライフ', 'ドルディア族の集落に迎え入れられたルーデウス、エリス、ルイジェルド。この村がギレーヌの故郷だと知ったエリスは喜ぶが、ギレーヌの兄･ギュエスは彼女のことを一族の面汚しだと吐き捨て、二人は一触即発の事態に。タダならぬ様子にルーデウスたちが困惑する中、エリスはギュエスの娘であるミニトーナに剣術を教えることになって……。', '2021/10/30 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f5b73b50-f7a8-4bc7-86a7-49030e12f7ee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e42063c0-4d83-4056-af03-8c2e0e9e2794', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 16, '100095449', '親子げんか', 'ルーデウスたちはミリス神聖国の首都･ミリシオンにたどり着く。資金集めのためにしばらく滞在することに決めたルーデウスが街を散策していると、子どもが攫われている現場に出くわしてしまう。子どもを助けようと後をつけたルーデウスは人攫いの一味と戦闘になってしまうが、そこにはルーデウスのよく知る人物が関わっていたのだった。', '2021/11/06 12:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/20525baf-d51a-4f8c-956e-d389c3bd03ba.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ad9c9c27-8910-4172-9521-21283518f37f', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 17, '100095851', '再会', '父･パウロと再会を果たしたものの、ゼニス、リーリャ、アイシャ、シルフィが転移事件で行方不明になったこと、そしてパウロとの衝突で傷心するルーデウス。一方のパウロはギースに諭され、ルーデウスにぶつけた言葉など己の過ちに気づき、もう一度息子と会って話をしようとする。勇気を振り絞りパウロと対峙するルーデウスだが……。', '2021/11/13 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f30a904-05eb-4e9e-ac03-78eb2072d6c9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('63f83079-5bb0-45b8-b85c-2c3ad7299346', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 18, '100096285', 'それぞれの旅', 'パウロと和解し、互いに家族を探すべく別れたルーデウスは、エリスとルイジェルドとともに船で中央大陸へ。一方、ゼニスらグレイラット家を探すロキシー、エリナリーゼ、タルハンド。リカリスの街で再会したノコパラに促され、ロキシーは故郷であるミグルド族の村を訪れる。家出同然に飛び出した故郷に心穏やかではいられなかったロキシーだが、果たして両親との再会は…。', '2021/11/20 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/95958c14-8ef3-4f22-85f8-fd5754b1e4be.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7451f17e-076d-4499-a617-3aba4393a078', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 19, '100096957', 'ルート選択', 'ヒトガミからリーリャとアイシャの居場所を聞きだしたルーデウスは、シーローン王国の首都･ラタキアへとやってくる。すると、街で兵士から逃げていたアイシャと遭遇したルーデウスはアイシャを救出し、なぜ兵士に追われていたか、そしてリーリャがどこにいるかを聞き出す。そして同じくシーローンの王宮で働いているはずのロキシーを頼ろうと考えるが…', '2021/11/27 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a907881e-421d-4d35-a946-230eb43e840f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('542fc9cc-6542-4783-8416-374bd5f4737f', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 20, '100097565', '妹侍女の生まれた日', 'ロキシーをおびき寄せる餌としてパックスに捕まり監禁部屋に入れられてしまったルーデウスの前に、シーローン第三王子でパックスの兄･ザノバが現れた。ザノバはあるものを取り出し、ルーデウスに質問をする。すると事態は思わぬ方向へ…。一方、エリスとルイジェルドはルーデウスが捕まったことを聞き救出に向かう。', '2021/12/04 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8f01191b-5785-4b09-beac-0424fc52cc28.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('91df0dee-08e1-433f-9995-9c09a705a876', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 21, '100098102', 'ターニングポイント2', 'リーリャやアイシャと別れ、故郷を目指して進むルーデウスたち。その道中で、七大列強のひとり龍神･オルステッドに出会う。すると、エリスとルイジェルドは突然顔色を変え震え始める。初対面のはずなのにエリスとルイジェルド、さらにはパウロのことをよく知るオルステッドだが、ルーデウスのことは知らない様子。そこでオルステッドのある質問にルーデウスが答えると、突如オルステッドが襲い掛かり――!', '2021/12/11 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/629881f4-673c-4c86-b899-3f30f0b4c43b.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('141a4866-4153-4c92-98fa-4efa38c0303b', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 22, '100098631', '現実 (ユメ)', 'ついにフィットア領へと戻ってきたルーデウスたち。しかし、故郷のブエナ村は荒地になり、ボレアス家のあったロアの街も転移事件に巻き込まれた人たちが集まる難民キャンプとなっていた。執事のアルフォンス、そしてギレーヌと再会し、フィットア領やボレアス家の現状を知ったエリスは、ひとり考えた末にルーデウスの元を訪れる。', '2021/12/18 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/df85aa5d-bf2b-48cd-a717-778a1eabb43a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6aecb6de-2a70-4a39-959b-a21eef3d5c1b', '5c05fa7b-f7d1-43cb-a498-aeb79a6b40e6', 23, '100099487', '目覚め、一歩、', '【第2クール 最終話】突如、手紙を残してエリスがいなくなった。人生をやり直し、様々な出会いや旅を経験して変わることができたと思っていたルーデウスだが、エリスを失ったショックで、再び前世のように引きこもってしまう。ルーデウスがなにもかも諦めかけたその時、彼の脳裏に母･ゼニスの思い出がよぎって……。', '2021/12/25 12:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/21504ed9-e212-4c17-9ff5-488815ee5cfb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('18e724db-912a-45fc-84eb-3828e9f311b8', '無職転生Ⅱ ～異世界行ったら本気だす～', '', 'hulu', 'mushoku-tensei-jobless-reincarnation-2', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/932a3638-ad7e-480e-bd05-65c043dafe95.jpg?w=331&h=447&p=t', 'hulu', 2023, 2, 1, 'FINISHED', NULL, 146065, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('d2191dfc-74fe-4230-b3a4-7dc32de79c30', '18e724db-912a-45fc-84eb-3828e9f311b8', 'hulu-mushoku-tensei-jobless-reincarnation-2-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53cc501a-cb8a-47a4-94e8-42c6ac01ef53.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('93b604e2-a293-47ef-b31c-d8f28dd0e1c3', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 1, '100151901', '失意の魔術師', '母･ゼニスを探すために歩き出したルーデウス。しかし、エリスに姿を消された失意の底から抜け出せずにいた。北方大地に向かう馬車の中で冒険者パーティー“カウンターアロー”のサラとスザンヌに出会ったルーデウスは、冒険者ギルドにあったある依頼のためにカウンターアローに同行する。', '2023/07/13 00:00:00', 1420, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/53cc501a-cb8a-47a4-94e8-42c6ac01ef53.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dde60c36-0d4a-4095-8026-f46fc420960b', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 2, '100152568', '真夜中の森', '母･ゼニスに自分の名前が届くよう、冒険者稼業の実績により“泥沼”の異名で名を広めるルーデウス。ある日、カウンターアローと共にある依頼を受けるが、訪れた場所で大量の魔物が出現。そこに現れたのは剣士ゾルダートのパーティーだった。ゾルダートはルーデウスたちに傍若無人な態度で迫り…。', '2023/07/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58f6d0a6-f4f5-43b0-afe3-c0468ee17dcd.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5da36e6d-4972-48d9-8c26-122b0225c901', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 3, '100153578', '急接近', 'ルーデウスがサラの命を救った一件以来、サラの接し方も変化し、2人の距離が近くなった。新しい短剣を買いたいとサラに誘われたルーデウスはデートへ。楽しく買い物をし、酒場で語り合う中で雰囲気が高まる2人。エリスが頭をよぎりながらも、サラの自分への態度を受けてルーデウスは意を決する…!', '2023/07/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/f1c6dbf9-0de0-4b5d-bfff-7082d5fa17bc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e83e7d08-3e49-497e-a0b3-8da187370067', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 4, '100154021', '推薦状', '不能になり抱えていた気持ちを吐き出したルーデウスは、ゾルダートと意気投合し行動を共にするようになる。ピピンの町に滞在中、ルーデウスの前に現れたのは、かつてパウロと同じパーティーメンバーで、ロキシーと旅をしていたエリナリーゼだった。彼女はルーデウスにある情報を伝える。', '2023/08/03 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c7a4dbfa-8a91-40a3-add5-b05a0138d450.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3cd29f47-5603-4c0a-8c75-f30da79c1a99', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 5, '100155009', 'ラノア魔法大学', '推薦状とヒトガミの助言を受け、ラノア魔法大学に入学することを決めたルーデウス。エリナリーゼと共に大学へ到着すると、試験として在学生との模擬戦に臨むことになる。その相手は、ルーデウスと同じく無詠唱魔術の使い手、フィッツという人物だった。そして、大学には個性的な生徒たちが集まっていた。', '2023/08/10 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/2f2be51e-e620-40a5-acc2-6afd8dd13921.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ee410463-28bc-49f0-9b10-8fcd2ae7d1ee', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 6, '100155735', '死にたくない', 'ラノア魔法大学に通い始めたルーデウスは、転移事件のことを調べる中でフィッツと交流を深めていく。大学にはルーデウスを人形 (フィギュア) 作りの師匠と崇めるザノバがいた。その異常な怪力のためうまく人形が作れないザノバに代わって手先の作業をする者を探し、ルーデウスは奴隷市場に足を運ぶ。', '2023/08/17 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/0c8ce2ac-eca6-4995-9d99-85c76be3f8cb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dcd93687-8107-461f-8d1b-b6cceded04d0', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 7, '100156419', '獣族令嬢拉致監禁事件', 'ザノバとジュリと共に人形を作っていたある日、ルーデウスはかつて自分が作り、流れ着いてザノバが手に入れたロキシー人形のことを思い出す。ザノバに確認をするが、人形はバラバラになっていた。獣人族のリニアとプルセナとの決闘に負け、破壊されたという。怒りに震えるルーデウスは…!?', '2023/08/24 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ebae0c41-28f6-4e30-be61-aad33433f645.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a969c532-2443-4c88-93b5-92aad9520453', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 8, '100156823', '絶望の婚約者', '恋の季節到来…!? ルーデウスは特別生のクリフからある女性を紹介してほしいと頼まれる。一方、獣族は秋になると求婚の決闘が盛んになるため、ドルディア族の姫であるリニアとプルセナは決闘を避けようと寮に籠るという。しかし、なぜかルーデウスに決闘を申し込む者が現れ…!?', '2023/08/31 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8767adbd-1383-4708-9f1d-ba3dabe02bc0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('8e8d785b-c274-404d-9fb9-5695530655b4', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 9, '100157863', '白い仮面', 'フィッツとフィットア領転移事件について調べるルーデウス。転移と召喚が似ていることから、ルーデウスは召喚魔術の知識を得るべく、大学で召喚魔術を専門的に研究している特別生のサイレント･セブンスターという人物を訪ねる。その人物の正体とは…。', '2023/09/07 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9d39f4c7-23dd-441f-adbe-ebfc0f9b0426.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('063195f8-80f5-48d6-8596-07d46bb718d5', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 10, '100158264', 'この気持ち', '転生ではなくとも自分と同じ世界からやって来たサイレント･セブンスター＝ナナホシと共に転移事件や召喚魔術について調べるルーデウス。そんな2人に、理由はわからずも妙な絆を感じるフィッツは消沈してしまう。しかし、一方のルーデウスも男性であるフィッツにある想いを抱き始めていた。', '2023/09/14 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/08ed1f85-4f7b-4cd5-83dd-5613f28e53da.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f38511f6-bba8-4bce-b9e4-b729c99ad508', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 11, '100159182', 'あなたへ', 'フィッツは実は女性だった。彼女の体に触れたことで自分の不能が治る兆しもあった。ルーデウスはフィッツの存在に希望を見出すが、彼女が男性と偽っていることから距離感に思い悩む。そこにルークが訪ねてきて…。一方、フィッツはアリエルからある言葉をかけられる。', '2023/09/21 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8d1db6f0-6d5c-4298-93f8-f9e72df22249.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6dcf9829-5730-478e-8adc-51c9465d0ee5', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 12, '100160152', '伝えたい', '【第1クール 最終話】遂に、フィッツがシルフィであることを知ったルーデウス。シルフィもルーデウスに自分の想いを告げ、2人は結ばれる。長い間フィッツ=シルフィだと気づけなかったことを詫びるルーデウスに、フィッツは優しく微笑む。ルーデウスは意を決しフィッツと共にアリエルの下を訪れる――。', '2023/09/28 00:00:00', 1422, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/dc5c3cad-503a-462a-bec7-79b2dc6f1bc1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68fbff07-650a-42f3-8b87-6e30c110dc89', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 13, '100180719', '夢のマイホーム', 'シルフィと婚約したルーデウスだったが、この世界での結婚の手順がわからず、ザノバとクリフに相談する。暮らす家を決めるのが先決と聞いたルーデウスは、不動産屋で大きいわりに安い物件を紹介される。そこは呪いにより訪れる者が謎の死を遂げる、ワケあり物件だというが…。', '2024/04/11 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1d123990-c4de-4b92-9f22-1c2040b3ffdf.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cb4f8fc9-704a-4f8a-9c86-0c20b4739569', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 14, '100181741', '披露宴', 'この世界では結婚する際は自宅でパーティーを開くということで、ルーデウスはシルフィと共にその準備を進める。そしてパーティー当日、アリエルやザノバらラノア魔法大学の面々が出席する中、エリナリーゼの表情がいつもと違っていた。そんな中ルーデウスはアリエルからある申し出を受けて…。', '2024/04/18 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d46013a7-0a0a-4d0a-a102-c4416ca798c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a973fe90-0329-4b69-8e16-1ae2d28accbe', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 15, '100182361', '遥か', '父パウロから手紙が届いた。妹のノルンとアイシャを引き取ってほしいので、護衛付きでこちらに送ったというが…。そんな中、ルーデウスと同じ世界から“転移”してきたナナホシは、元の世界に戻るための召喚魔術の研究を続けていたが、なかなか糸口が見つからずに焦りを募らせていた…。', '2024/04/25 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d804e7f3-5342-40d5-b2ce-a8b2e11fa0ab.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('10c28086-7336-4651-914b-1e3792f05228', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 16, '100183222', 'ノルンとアイシャ', 'ルーデウスの妹ノルンとアイシャがルーデウスの家にやって来た。しかし快活なアイシャとは対照的にノルンは内気で、そしてルーデウスに心を開かない…。正反対なふたりの妹への接し方に手を焼くルーデウスは、パウロからの言伝に従い、ふたりを学校に通わせようとするが…。', '2024/05/02 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ed82b62a-91fb-4d5a-8205-0539427db2cc.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('66030425-de11-4a9f-a865-1f5cf9a68f09', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 17, '100183734', '兄貴の気持ち', 'ラノア魔法大学の寮で暮らし始めたノルンが引き籠ってしまった。前世の自分と重ね合わせ、なんとかノルンを救おうとするルーデウスは、ノルンの教室に向かう。そしてそこで耳にする言葉にルーデウスは愕然とする…。一方のノルンもルーデウスという存在への向き合いに悩んでいた…。', '2024/05/09 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c6db2735-b688-49ea-84af-8bb01f05caeb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b712c8c-9496-40bd-8175-c5a9239e5782', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 18, '100184439', 'ターニングポイント3', 'ルーデウスへの接し方、そして学校に友達ができるなど、ノルンにも変化が見られてきた。家族との、そして大学での生活も穏やかに進んでいく。そんなある日、シルフィから告げられる事とは…? そしてある人物から届く手紙の内容とは…? さらにヒトガミの新たな“助言”とは…!?', '2024/05/16 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/8bd1df1d-8620-4cf3-b0f1-f76d6095bdbb.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7c620c88-3ddd-4511-906b-e37e66ad6a42', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 19, '100185884', '砂漠の旅', 'ギースからの「ゼニス救出困難、救援求む」という手紙を受けたルーデウス。妊娠したシルフィやノルン、アイシャを残すことになる…。悩みながらもベリガット大陸の迷宮都市ラパンへ行くことを決意する。しかしその道のりは、想像以上に険しく、命の危険を伴うものだった。', '2024/05/30 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/1377ce8f-2dcf-4cb0-915a-e3478659831e.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9c701d2b-ef8f-4874-8c36-aeb7acd8b398', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 20, '100186517', '迷宮入り', '迷宮都市ラパンへとたどり着いたルーデウスとエリナリーゼは早速ギースを見つけ、パウロとリーリャのもとに案内される。ゼニスが救出できずに疲労し、憔悴するパウロに対し、ルーデウスは優しく声をかける。ゼニスのいる迷宮攻略について話し合うが、その場にいるはずのロキシーの姿がなく…。', '2024/06/06 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/ca4bf80d-991d-41ff-8565-c39ecf2b955a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a67290b2-6c95-486f-8187-02081285f88f', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 21, '100187220', '第六階層の魔法陣', '迷宮にひとり残されていたロキシーを救い出し、回復のために一度街に戻ったルーデウスやパウロたち。時折よそよそしいロキシーが気になりつつも、ルーデウスは昔話に花を咲かせる。3日後、転移迷宮へ再び入り、階層攻略のスピードを上げていく――!', '2024/06/13 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/c5c56617-c687-4c8e-b79b-fccd29c17cee.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ce6f9a4f-c8e1-41fd-b8bb-3f5aae8b9995', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 22, '100188087', '親', '最終階層へと転移したルーデウスたちは、ついにゼニスの姿を確認する! しかしそこに、この迷宮の守護者〈ガーディアン〉と思われる、巨大なヒュドラが立ちふさがる。そのヒュドラは絶滅したはずの伝説の生き物、“悪魔の竜”とも呼ばれる強敵だった――!', '2024/06/20 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/720e2633-b561-4edd-a76b-ced3c6249c21.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9d24645b-da17-43e5-a964-4d767e8ca2e8', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 23, '100188481', '帰ろう', 'マナタイトヒュドラとの壮絶な死闘の末、ゼニスを救出したルーデウスたち。その代償は、ルーデウスの左腕と、パウロの命。さらにゼニスは心を失くしたかのようになっていた…。父パウロの死に、後悔と絶望がルーデウスに押し寄せる。そんな彼にロキシーが声をかけて…。', '2024/06/27 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/31f3a69f-f5fd-46a0-9b9c-4298887c1523.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b32fe923-07d6-459f-8f58-ce7c444970ff', 'd2191dfc-74fe-4230-b3a4-7dc32de79c30', 24, '100189527', '嗣ぐ', '【第2クール 最終話】ルーデウスは半年ぶりにシルフィたちが待つ家へと帰ってきた。転移迷宮でのこと、パウロの死、ゼニスの状態などを話すルーデウス。そして、ロキシーとのことも…。それを受けたノルン、アイシャ、そして、シルフィの答えとは…?', '2024/07/04 00:00:00', 1421, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d85d1912-37f9-4aa0-a15b-3f03e53835c1.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('094643cf-a280-40ec-84a3-0b0678507efe', '霧尾ファンクラブ', '', 'hulu', 'kirio-fanclub-anime', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd4eb757-832e-4872-8cac-c9af25cef799.jpg?w=331&h=447&p=t', 'hulu', 2026, 1, 1, 'NOT_YET_RELEASED', NULL, 181284, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1bc83d95-3738-4f47-a4f6-5d80567330b6', '名探偵コナン', '', 'hulu', 'conan', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/50c15386-6af5-4d1c-8d6d-cf447ebbb26a.jpg?w=331&h=447&q=80', 'hulu', 1996, 0, 1, 'RELEASING', NULL, 235, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('b4105d7b-8de5-4296-b783-12e0869e66e3', '1bc83d95-3738-4f47-a4f6-5d80567330b6', 'hulu-conan-s1', 'シーズン1 (第1話～)', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c3ea7dc1-c672-499f-b9dc-c2cdd2d388f7.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d50da348-37a8-4c44-b1ca-4f9c61f41a04', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 1, '60474603', 'ジェットコースター殺人事件', '数々の難事件を解決する高校生探偵･工藤新一は、ガールフレンドの毛利蘭と遊園地でデート中、ジェットコースターで殺人事件にまき込まれた。ズバ抜けた推理力で事件を解決したが乗客の中にいた怪しげな黒服の男たちが現金受け渡しする犯罪現場に遭遇。現場の証拠を押さえようとするが背後から襲われ気を失ってしまい…。', '2014/12/03 12:00:00', 1486, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c3ea7dc1-c672-499f-b9dc-c2cdd2d388f7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('73b9cfdf-e1af-4949-81ed-29850f553758', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 2, '60474607', '社長令嬢誘拐事件', '黒服の男に殴られ意識を失った新一が目覚めると、飲まされた毒薬のせいで身体が小学生くらいまでに縮んでしまっていた。新一は小学生･江戸川コナンと名乗り、黒服の男たちの情報を得るため私立探偵の父を持つガールフレンドの毛利蘭の家に居候することに。すると金持ちの娘が黒ずくめの男たちに誘拐されたという話が入る。', '2014/12/03 12:00:00', 1487, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b133d707-c687-4596-afe7-8725971dbbc4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7a8a9924-a550-4be8-ab50-04306202ac18', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 3, '60474617', 'アイドル密室殺人事件', '毛利小五郎の事務所に、アイドル･沖野ヨーコが訪ねてきた。何者かに後をつけられたり、部屋に侵入されているというのだ。調査のためコナンたちがヨーコの部屋に入ると、そこには男の刺殺死体があった…。コナンは小五郎を気絶させ、阿笠博士が発明した蝶ネクタイ型変声機を使って小五郎の声で事件の謎解きを始める。', '2014/12/03 12:00:00', 1489, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/27080943-a24c-4500-89da-ce9f36c50114.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('08db948a-8083-4454-8066-2d90177828ed', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 4, '60474596', '大都会暗号マップ事件', '偶然謎の図形と「ORO」という文字が書かれた紙を手に入れたコナンと同級生三人組。宝の地図に違いないと、早速捜索を開始したが、実はその暗号は、現在逃走中のイタリアの強盗団が隠したという金貨のありかを示したものだった。暗号を解読し、忍び寄る強盗団をかいくぐり、見事お宝にたどり着くことができるのか!?', '2014/12/03 12:00:00', 1490, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/9251aaa9-0bab-46af-a163-18d49ce31366.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f198278-abdf-4ab5-9494-7536f63f3137', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 5, '60474618', '新幹線大爆破事件', '京都に向かう新幹線でコナンは毒薬を飲ませた黒服の男たちそっくりな二人組と鉢合わせする。阿笠博士が開発した超小型盗聴器を二人の座席にセットすると、4億円と引換えに渡したアタッシュケースには高性能爆弾が入っていて、取引相手が何も知らず爆破スイッチを押すと十秒後に新幹線もろとも木っ端微塵にという声が…。', '2014/12/03 12:00:00', 1489, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/700fdfe6-7def-457f-bc66-82481394b962.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('77aefa94-6366-4de7-806d-b62f5e932b97', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 6, '60474611', 'バレンタイン殺人事件', '蘭がバレンタインパーティーに招かれた。主催者の医大生･克彦に夢中な同級生の園子にむりやり付き合わされたらしいが、コナンは気が気ではない。テニス仲間が集まるパーティーで、仲間の一人･好美が贈ったチョコレートを食べた克彦が、苦しみ出し死亡する。駆けつけた目暮警部と小五郎は、好美が犯人だとにらむが…。', '2014/12/03 12:00:00', 1486, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c05812b4-7c3c-4331-98d8-387a69f106cb.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0d8de022-c169-4ac6-adbd-f09b2aaf5c9c', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 7, '60474600', '月いちプレゼント脅迫事件', '毛利探偵事務所に小川という依頼人がやってきた。二年前から毎月、送り主の名前も住所もデタラメなオモチャと現金が送られてきていて、今日送られてきた現金には、「2500万円払い終わりました。引き替えに、いただきに参ります」という意味不明の手紙が添えられていた。小五郎は手のこんだイタズラだと断定するが…。', '2014/12/03 12:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/44bdd0bb-1a73-43a6-958f-b841b0967008.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('707b0173-3beb-4955-8a40-ac882d91f850', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 8, '60474590', '美術館オーナー殺人事件', '夜な夜な甲冑の騎士が歩き回るというウワサの美術館。興味津々の蘭は、コナンと小五郎を連れ見学に行く。だが最後の「地獄の間」でコナンたちが見たのは、ホテルに転業するため美術館を閉館すると決めた新オーナー･真中が、「天罰」と題された絵画の後ろで、絵と同じように喉を剣で串刺しにされて絶命している姿だった。', '2014/12/03 12:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c232b45b-881b-42dc-8c67-d48dd7eb5a45.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b6a05768-486b-4f36-a8a0-5a29995fb32d', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 9, '60474615', '天下一夜祭殺人事件', '天下一春祭りの夜、ホテルの居室で人気作家･今竹智が殺害された。友人の笹井の犯行ではないかと疑われたが、笹井は祭りの会場にいたと主張し、証拠に蘭がシャッターを押したインスタントカメラを差し出した。完壁なアリバイに笹井は自信満々だが、コナンは笹井が犯人だと確信し、笹井のアリバイを崩す糸口を探し始める。', '2014/12/03 12:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/675ae1f1-33c7-42c5-ae4e-f86450caf596.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d49ecbed-7e42-489e-b748-7069ab21fb98', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 10, '60474584', 'プロサッカー選手脅迫事件', '毛利探偵事務所に赤木量子と名乗る女子高生が、新一を探してほしいと訪ねてきた。量子と会ったこともないコナンは戸惑うばかりだが、蘭のほうは新一への怒りで我を忘れてしまっている。新一をとっちめようと、蘭はコナンを連れて量子の家に押しかけるが、その依頼が、あるプロサッカー選手の脅迫事件と関係する事を知り…。', '2014/12/03 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/0fc4013c-d41a-4be5-b1a6-fd36ce70d384.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5dad4534-bb20-492f-8298-9688fd11f1ac', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 11, '60474625', 'ピアノソナタ「月光」殺人事件', '謎の依頼人に伊豆の小島･月影島に呼び出されたコナンたち。依頼人は12年前にピアノソナタ「月光」を弾きながら死亡した有名なピアニストだったことを知る。謎の依頼主のことを調べるため訪れた公民館で営まれていた前村長の法要の最中、「月光」の第一楽章と共に村の資産家が殺され、これを機に次々と殺人事件が…。', '2014/12/03 12:00:00', 2910, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/84da6d8c-05f1-4652-90f5-5fae78d9599b.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('64d722b0-948a-4b79-be48-81de363cb37b', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 12, '60474621', '歩美ちゃん誘拐事件', '公園でかくれんぼをするコナンたち。二時間たってもみつからない歩美にコナンがトランシーバーで連絡を取ると、歩美はなんと車のトランクの中。しかも、それは少女連続誘拐殺人事件の犯人の車だった! スケボーの動力ソーラー･エンジンも日没が迫り、時間がたてば歩美の命も危ない。コナンは絶体絶命のピンチに陥る。', '2014/12/03 12:00:00', 1485, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/11d04fa1-cb04-42c2-ba35-6a47b387d9c7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('29323298-39b4-4550-a968-ffaaaa46f590', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 13, '60474585', '奇妙な人捜し殺人事件', '毛利探偵事務所に広田雅美と名乗る娘が、1か月前から行方不明になっている父を捜してほしいと依頼に来た。蘭は広田の飼っていた猫の名前が人気の競争馬の名前から付けられたことに気づき、競馬場であっという間に観客の中から広田を見つけ出す。雅美との感激の再会となったが、その翌日、広田がアパートで絞殺された。', '2014/12/03 12:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/325a46c1-f8a6-4836-923c-cc983b20895f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('e4a66ba4-6a6d-4f97-9dab-40f70df4a2e7', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 14, '60474594', '謎のメッセージ狙撃事件', 'コナンたちが川原で遊んでいると銃声のような音とともに風船が破裂した。コナンが双限鏡で川の対岸を見ると、土手の向こうのビルの屋上で二人の男に拳銃を向けられライフルを構えている男を目撃。その現場に駆けつけると、謎の十桁の数字を表示した電卓が置かれていた。これは男がコナンに残したメッセージだろうか。', '2014/12/03 12:00:00', 1486, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/cac0db08-2273-4683-b04d-06cfd3625bd1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ab8b167a-069b-45ab-a2ea-c0fd817b3632', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 15, '60474614', '消えた死体殺人事件', '猫を探す依頼を受けたコナンたちは、猫が出てきた家の浴室で男の死体を発見した。コナンたちの通報で駆けつけた目暮警部は、その家を捜索するが、死体のあった浴室には一滴の血痕すら残っていない。コナンたちに見られずに死体を運び出すのは不可能だと判断した目暮警部は、コナンの通報がウソだと判断するが…。', '2014/12/03 12:00:00', 1485, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/333581ee-8a8d-4600-b88f-0ef8fe2d34c2.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6829c807-81a1-4e43-916f-091632d229ed', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 16, '60474604', '骨董品コレクター殺人事件', 'コナンたちが、資産家の丸伝次郎の屋敷に妻の浮気調査報告のために訪れていた時、伝次郎自身が何者かによって惨殺された。残された伝次郎の手帳に名前が書き込まれていたのは、小五郎、伝次郎の主治医･波多野、彫刻家の阿久津、そして居合の道場主･諏訪の4人。はたして、この中に犯人がいるのか？', '2014/12/03 12:00:00', 1485, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7aeeeeef-425d-45de-8a59-d7ea358fdf7a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6c79bae1-3fa8-4833-b218-ab82ae7e3411', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 17, '60474591', 'デパートジャック事件', '「仮面ヤイバーショー」を見にデパートを訪れたコナンたちは、元太が大事なヤイバーのサインを忘れ閉店間際のデパートにとりに戻るが、出入口が閉まり閉店後のデパートに取り残されてしまう。警備室に行ったコナンたちは、そこでヤイバーとジョッカー軍団の着ぐるみ姿で閉店後のデパートを狙う強盗団に遭遇してしまう。', '2014/12/03 12:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/888a39d8-3569-475f-a8c4-bfff8c53f6d4.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5cc06f61-dca5-4cd0-8554-05e7cd5fdf47', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 18, '60474613', '6月の花嫁殺人事件', '今日は新一と蘭の中学の恩師･松本小百合先生の結婚式。式の時間が迫り、小百合は控室に一人で残った。妙な物音がして、コナンたちが控室に戻ってみると、純白のウェディングドレスに身を包んだ小百合が苛性ソーダの混入されたレモンティーを飲み吐血して倒れていた。容疑者は新婦の控室に出入りしたものに絞られる…。', '2014/12/03 12:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/76a3e2ed-6431-41d5-8b2a-177c097a48e0.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('99514692-6e46-4480-a4b2-f28c71574ca2', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 19, '60474599', 'エレベーター殺人事件', 'トップデザイナーの芦屋映子に街でファッションモデルにスカウトされた蘭。衣装合わせのためビルに行くと、秘書の美香がエレベーターの中で殺害されているのに出くわした。暎子は床に残った靴跡を見つけビル荒らしに殺されたのだと断定するが、コナンは映子がエレベーターのボタンをハンカチで拭いたのを見逃さなかった。', '2014/12/03 12:00:00', 1486, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c22e825c-7364-4139-b426-e2fa14b6caf9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2b05c20c-f436-46bc-aa51-efdf4e5e2768', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 20, '60474623', '幽霊屋敷殺人事件', '歩美が幽霊屋敷を見つけてきた。コナンたち少年探偵団は、さっそく幽霊退治に乗り出すことになった。そこは5年前に殺人事件があった家で、現在は空き家のはずだ。一人でトイレに行った光彦の悲鳴に続き、元太の悲鳴が聞こえた。本当に幽霊なのか?コナンは床の隠し扉に気づき開けると、扉の向こうは地下への階段だった。', '2014/12/03 12:00:00', 1484, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b6c47a8a-2730-43b2-a2c4-5305d0815575.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('db8c7c43-c259-465b-a47b-da76274ed69a', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 21, '60474606', 'TVドラマロケ殺人事件', '人気アイドル沖野ヨーコ主演のサスペンスドラマのロケが米花神社で行われた。そのドラマの推理監修として協力することになった小五郎はゴキゲンだ。しかしその日の夜、コナンたちが神社の前を通りかかると、撮影助手の安西が狛犬の前で血まみれで倒れていた。手掛かりは血で書かれた「コマイヌ」の文字だけ。', '2014/12/11 12:00:00', 1486, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/6c7235ac-c8ab-403a-bb16-7e774a212a56.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c6e4e554-166d-4dd1-8331-c5964563ba70', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 22, '60474589', '豪華客船連続殺人事件 (前編)', '旗本島に旅行に来たコナンたち。偶然、旗本島の旧家･旗本一族が貸切りにした豪華客船に便乗させてもらうことになった。一族の当主･豪蔵は今日の結婚式の途中から機嫌が悪く、自室に引き上げて行った。夕食に姿を見せない豪蔵を迎えに行くと、自室で殺害されていた。遺産分配をめぐっての争いだろうと推察されるのだが…。', '2014/12/11 12:00:00', 1486, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/22f100d3-526d-4c80-9fd5-c9081e063422.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d04181ca-f2d5-4f8d-a31a-064a4c788b93', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 23, '60474601', '豪華客船連続殺人事件 (後編)', '旗本一族のチャーターした豪華客船内で、当主の豪蔵が刺殺され、孫娘の夏江と結婚式を挙げたばかりの花婿･武が犯人と疑われ、倉庫に監禁された。これで一件落着かと思われたが、惨劇の幕はまだ下りていなかった。第二の殺人が起き、武が監禁されていた倉庫の扉が開いていて、武の姿が消えていた。真犯人は一体誰なのか?', '2014/12/11 12:00:00', 1485, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/38edd70b-42d3-412f-9f69-694846a63d97.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2bc9e132-4959-4142-becb-30f5ced15d05', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 24, '60474610', '謎の美女記憶喪失事件', '二か月前にコナンの推理で逮捕された保険金殺人犯･湯田が、刑務所を脱走した。いつものようにコナンが小五郎の声を使って事件を解決したのだが、そうとは知らない湯田は、小五郎を恨んでいた。逮捕された時に「この礼は必ずしてやる」と言った湯田の言葉を思い出し、蘭は小五郎の身を案じる。小五郎に魔の手がしのびよる。', '2014/12/11 12:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2aeeca79-29da-495a-bf5a-b5c1be36624f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('c95a6830-52d3-4ea2-b2ec-a21a449a8133', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 25, '60474588', '偽りの身代金誘拐事件', '蘭の同級生･直子が誘拐され身代金の受渡しが埠頭で行なわれたが、誘拐犯の車は逃走途中、直子を乗せたまま海中に転落してしまった。しかし引き上げられた車には、直子も犯人の姿もなかった。その後事件当日、埠頭の対岸で不審なクルーザーがいた事を知り、コナンは直子たちが生きていると確信し、推理をはじめる…。', '2014/12/11 12:00:00', 1473, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/203135f0-7efa-41a2-a849-e980e9da2e47.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('080cb60e-7550-4d10-8bbf-481da3a1a398', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 26, '60474608', '愛犬ジョン殺人事件', 'コナンたちは、学校帰りに坂口家の愛犬ジョンと遊ぶのを楽しみにしていた。ある夜、コナンが小五郎と蘭と共に坂口家の前を通りかかると、犬の鳴き声と悲鳴が聞こえ、若い女性が飛び出してきた。家の中では倒れた男性と唸っているジョンの姿が。コナンや蘭には人懐っこいジョンが訳もなく人を襲うとは考えられないのだが…。', '2014/12/11 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/d81221bb-1f8b-4107-ae26-19dc2f74d000.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('884be64e-5032-47b9-a7c2-255aca72ac29', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 27, '60474620', '小五郎の同窓会殺人事件 (前編)', '小五郎の大学の柔道部の同窓会が開かれることになった。昔のアルバムを眺め、思い出話に花が咲く。中道が皆を卓球に誘うと、かつて恋人だった由美は疲れたから休むと言って部屋に戻ってしまう。由美を除いた全員で卓球を楽しんだ後、一同は花火大会に。しかし部屋に戻ってみると、側頭部を銃で撃ち抜かれた由美の姿が。', '2014/12/11 12:00:00', 1473, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/8912e85a-6f3f-402d-aff1-c2adb88ea549.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3a174c71-bd77-4186-92cf-fb34c1033421', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 28, '60474592', '小五郎の同窓会殺人事件 (後編)', '小五郎の大学の柔道部の同窓会で柔道部のマドンナだった堀田由美が死んだ。旅館の自室で頭を銃で撃ち抜いていたのだが、数々の証拠から自殺に見せかけた他殺とわかった。犯人は同窓会に集まった小五郎の親友の四人の内の誰か。だが、この時間は全員が卓球をしていたというアリバイがある。小五郎のつらい謎ときが始まる。', '2014/12/11 12:00:00', 1472, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/10b3de39-126d-43d6-bcf4-e84f33cf3c50.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('977d6083-9a7e-4a37-8e87-120247a50324', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 29, '60474616', 'コンピューター殺人事件', 'コンピューター･ソフト会社の社長･大木田が死亡した。遺体に外傷はなく、毒物を飲んだ形跡もないことから、突然死だと思われた。しかしコナンは家中がコンピューターで快適な温度に管理されているはずなのに、遺体が多量の汗をかいている事に気づく。急激に温度が上昇しただけで心臓発作を起こすとは考えにくいのだが。', '2014/12/11 12:00:00', 1473, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f358a51f-dde5-49e1-96ec-e2d353b597f5.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('3606aedc-b732-43bd-a054-260bb0bc1d19', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 30, '60474593', 'アリバイ証言殺人事件', '小五郎に高名な弁護士･巽から妻の浮気調査の依頼があった。しかし、その日、自宅で縛り上げられて空の浴槽に押し込まれていた巽の妻の遺体が発見された。死亡推定時刻に小五郎と一緒にいた巽には完璧なアリバイがあるはずだが、コナンは、何か釈然としないものを感じる。全ての推理の出発点は、あのホテルだ。', '2014/12/11 12:00:00', 1473, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bb958d6b-1374-4fab-b26d-732cf258a1e0.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('081d0d2a-5c6d-4859-806e-fd24ab0a5283', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 31, '60474587', 'テレビ局殺人事件', '小五郎がゲスト出演した人気番組の生放送終了直後、プロデューサー･諏訪が、ミーティングルームで殺された。諏訪はここで番組終了後に司会の松尾と打合せをすることになっていた。番組降板の噂もあった松尾に目暮警部が問い正すが、生番組の司会をやっている自分に犯行は不可能だと自分のアリバイに自信たっぷりだ。', '2014/12/11 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/add6acc9-57db-4c13-b468-7c6362d35c0d.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b9ea92b3-8db3-4cda-b731-799071ccb574', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 32, '60474622', 'コーヒーショップ殺人事件', '蘭が新一とデートだと言って、うれしそうに出かけて行った。「新一はオレなのに」とコナンは気が気でない。不安になったコナンは無理やり待ち合わせの喫茶店までついていく。客の観察をしているその時、トイレから男の絶叫が響きわたった。トイレの個室の中で心臓をナイフで一突きされた女性が血まみれで倒れていた。', '2014/12/18 12:00:00', 1456, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/2899d6a9-a907-49eb-b321-0f8342709072.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5f6ca32c-532b-46c7-9a4f-70c58ea37cef', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 33, '60474602', '探偵団サバイバル事件', '川原にキャンプにやってきたコナンと少年探偵団の四人は、阿笠博士から宝物の在りかだという古い絵地図をもらいはりきって宝探しを始める。地図に従って森の中の目印をたどっていくと、途中で怪しげな二人組の男にでくわすが、男たちは四人を見てあわてて立ち去った。その後地図に書かれた暗号の謎を解いていくのだが…。', '2014/12/18 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/5d712d4d-96bf-4447-b6e9-38d5cef43815.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('b5588d4c-e904-46a8-8b91-0f4b4401c469', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 34, '60474609', '山荘包帯男殺人事件 (前編)', '蘭とコナンは同級生･園子の別荘に招待された。そこには園子の姉と姉の大学時代の映画研究会の仲間も集まっていた。蘭が森の中で顔に包帯を巻いた男に斧で襲われた。そして山荘の電話線は切断され、吊り橋が落とされていた。その夜、コナンたちは森の中で、バラバラに切断された脚本家の知佳子の惨殺死体を発見する。', '2014/12/18 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7ba752a1-4a65-41b1-ab4d-eb20ed4e220e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('394bc076-fa31-4dfb-83b1-53cab5be6b0f', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 35, '60474598', '山荘包帯男殺人事件 (後編)', '包帯男に蘭が再び襲われたことで、全員が食堂で夜明かしすることになった。知佳子が連れ去られた時に首に付けていたチョーカーを綾子が玄関で見つけ、知佳子殺しの謎が新たに浮上する。内部の犯行だとすると、蘭がなぜ二度までも襲われるのか。コナンは山荘に到着した時の出来事を思い出す。', '2014/12/18 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/61eb7153-fed1-412f-9616-9b7fee4ae597.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f7271a84-106b-42a8-9d1e-dc81a8fd2703', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 36, '60474605', '月曜夜7時30分殺人事件', '歩美が歯科医･沢木葉子に歯を抜いてもらった夜、あるマンションで殺人事件が起こった。第一発見者は隣室に住む葉子。葉子には、歯科医院で歩美と一緒にテレビを見ていたというアリバイがあった。が、歩美は眠ってしまって番組の最初と最後しか見ていないという。コナンはどこかにトリックが隠されているとにらむが…。', '2014/12/18 12:00:00', 1454, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b2209012-3657-414f-9b79-ebf937fa708a.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('260b0718-f11d-4570-8a45-392881f63826', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 37, '60474624', 'サボテンの花殺人事件', '小五郎に人捜しの依頼が来た。手掛かりは赤いスポーツカーのナンバーと、依頼人･典子が描いた似顔絵だ。信州でその男と知り合ったという典子の話に、小五郎は勝手に恋の相手だと決めつけるが、コナンは似顔絵の表情が陰険なのが気になった。コナンは小五郎にこのことを指摘するが、相手にされず一人で調査を開始した。', '2014/12/18 12:00:00', 1469, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c4a1cebd-87c8-4cbc-ab0d-0d06be1335e1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('6d06fb4b-1ecd-4118-98d0-63ffbca7e8fa', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 38, '60474586', '赤鬼村火祭殺人事件', '赤鬼村の火祭会場で、燃えさかる櫓の中から焼死体が発見された。殺人事件として捜査が始まったが、被害者の根岸は小五郎が阿部という男の依頼で3日間尾行をしていた相手で、しかも二人は互いに五億円の生命保険をかけていた。状況から、犯人は阿部に違いない。が、小五郎によって阿部のアリバイは完璧に証明されていた。', '2014/12/18 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bfeaa804-5383-4456-b7e8-bc84caa8972f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22de84e7-6d8d-4f22-b744-0670dc8aa585', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 39, '60474597', '資産家令嬢殺人事件 (前編)', '資産家の一人娘･四井麗花の誕生パーティーに招かれた小五郎と蘭、コナン。わがままな麗花の一言で、麗花の花婿候補と目されているヨットクラブのメンバー四人が家政婦の米、コナンたちと共に別荘に残ることになった。そんな中で麗花が行方不明になり、捜している最中に、二階堂が庭の噴水で溺死しているのが発見された。', '2014/12/18 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/b301b5b0-e9b3-4781-9e4b-b8fd73adadef.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('302b9228-67f7-445e-9121-528db3d94d15', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 40, '60474619', '資産家令嬢殺人事件 (後編)', '人里離れた別荘で資産家令嬢･麗花の花婿候補の一人･二階堂が不審な溺死を遂げ、蘭までもが同様の手口で襲われた。行方不明だった麗花も浴室で溺死体となっていた。三件の犯行はこの夜別荘にいた同一人物によるものに違いない。全身ずぶ濡れの麗花の死体の状況から、コナンはシャワーを利用したトリックを見破る。', '2014/12/18 12:00:00', 1469, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/c637db73-1b01-4127-927c-af3ed25767b7.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('47cdc0d2-ea17-4fab-a118-f12fd5031501', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 41, '60474612', '優勝旗切り裂き事件', 'コナンと小五郎、蘭は米花高校野球部の遠征試合を応援に行った。相手は昨年の地区大会優勝校で、今年も優勝候補ナンバーワンの修好学園。試合は思わぬ展開で米花が逆転勝利したが、試合直後、修好学園の理事長室で昨年の優勝旗がズタズタに引き裂かれているのが発見され、校長は、野球部の大会出場を辞退すると宣言した…。', '2014/12/18 12:00:00', 1469, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7c7d05b2-fad0-4c54-9307-2143ef70d28e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('286a8ded-d683-49db-86d2-023fd5e89ac5', 'b4105d7b-8de5-4296-b783-12e0869e66e3', 42, '60474595', 'カラオケボックス殺人事件', '【シーズン1 最終話】園子に誘われ、人気バンド「レックス」の打ち上げパーティーに参加した蘭とコナン。しかし、ボーカルの達也が、ヒット曲を熱唱した直後に吐血して倒れ、死亡した。死因は青酸カリ中毒。警察は昔のバンド仲間だったカラオケボックスの店長を疑うが…。コナンはカラオケボックスに全員を集め、店内放送を使って推理を始める。', '2014/12/18 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/f5438da0-7e6a-4001-9301-fb681e3a142e.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('586c7036-43ed-4cd4-a3ff-abf358899dcb', '1bc83d95-3738-4f47-a4f6-5d80567330b6', 'hulu-conan-s2', 'シーズン2 (第43話～)', 2, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1daf299c-e5da-4408-b726-9f692fa55845.jpg', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2eeb6e0b-49b0-475f-b6b6-8a5a8efbdd0c', '586c7036-43ed-4cd4-a3ff-abf358899dcb', 43, '60492623', '江戸川コナン誘拐事件', '毛利探偵事務所にコナンの母親だという女が現れた。蘭や小五郎の手前、ウソだとも言えず、コナンは女の車に乗り込んだが、コナンに母親などいるわけがない。案の定、女はコナンの正体が工藤新一だと知っていて誘拐したのだ。謎のベールに包まれていた世界的推理作家と元美人女優の新一の両親がついに登場する特別編。', '2014/12/25 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/1daf299c-e5da-4408-b726-9f692fa55845.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('68f5ff83-59d9-486b-ada6-cbddc47f4d96', '586c7036-43ed-4cd4-a3ff-abf358899dcb', 44, '60492601', '堀田三兄弟殺人事件', '小五郎と蘭、コナンは、山道で車が故障して困っていた、堀田重工の会長･堀田耕作を別荘まで送っていった。別荘では堀田の誕生パーティーが開かれるところだったが、息子たちがケンカを始めて険悪な雰囲気になった。その夜、堀田の寝室が爆破され、堀田が死亡。小五郎は行方不明になった次男を疑うが…。', '2014/12/25 12:00:00', 1469, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/74609ee7-14a4-45c7-9d1c-7c104b87470f.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d240936a-ecdb-438f-95d7-eaeaadb14424', '586c7036-43ed-4cd4-a3ff-abf358899dcb', 45, '60492609', '顔パック殺人事件', '高級住宅街で会社社長･児島郁子が顔にパックしたまま、ガウン姿で絞殺された。防犯カメラの映像とガードマンの証言から、死亡時刻が夜の9時すぎの18分間と推定される。容疑者は専務の吉岡、娘の千尋、証券マンの泉の三人。来客の予定があったのに、ガウン姿でパックをしているのは不自然だと気づいたコナンだが…。', '2014/12/25 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/7acd0fc2-b051-4d44-b908-aed9aaab41b9.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fe98ac69-185b-4162-98cf-09d2f5d8dce5', '586c7036-43ed-4cd4-a3ff-abf358899dcb', 46, '60492615', '雪山山荘殺人事件', '雪山にスキーに来たコナンと蘭、小五郎は、貸別荘の鍵を無くして医大教授･大山将の別荘で電話を借りることにした。別荘には大山の弟子の助教授や助手たちが集まり、コナンたちも鍋パーティーに招待される。食後、一人別室でテレビを見ていた大山の惨殺死体が発見された。コナンは大山のダイイングメッセージに気付く。', '2014/12/25 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/69f9d0e7-ae8c-411b-9b8a-ea72f0a29720.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('19ce9db1-8f03-4130-9d7a-7531b8442fae', '586c7036-43ed-4cd4-a3ff-abf358899dcb', 47, '60492608', 'スポーツクラブ殺人事件', '元高飛び込み女子選手がオーナーであるスポーツクラブが新装オープンすることになった。その前日に招待されたコナン、蘭、小五郎だが、高飛び込みの代表選手の西条と他のインストラクターたちが対立しているところを目撃してしまう。その夜、西条の死体がプールに浮いているのが発見された。西条の死は事故か殺人か。', '2014/12/25 12:00:00', 1471, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/93de9018-e942-464b-8df8-1830d529e781.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('00e6103a-23de-43c6-8721-ef8a35c2db53', '586c7036-43ed-4cd4-a3ff-abf358899dcb', 48, '60492612', '外交官殺人事件 (前編)', '新一に会うために、蘭のところへ “西の高校生探偵･服部平次” と名乗る少年が押しかけてきた。風邪気味のコナンは服部に飲まされた中国酒でフラフラになる。蘭が服部をにらみつけているところへ小五郎の依頼人が訪れる。小五郎と蘭、コナン、服部の四人で依頼人の外交官宅へ出向くと、外交官は何者かに毒殺されていた。', '2014/12/25 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/bf3bd7ea-6fa4-4e6d-84ae-acc8908205e1.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('84d10645-5836-4aaa-a173-2c3ac13b043f', '586c7036-43ed-4cd4-a3ff-abf358899dcb', 49, '60492595', '外交官殺人事件 (後編)', '服部に飲まされた中国酒のせいで気分が悪くなったコナンは、外交官･辻村勲の殺害現場で倒れてしまう。辻村を毒殺したトリックを暴いた服部は、辻村の父･利光を犯人だと決めつける。そこへ、突然、新一が現れ、服部の推理の間違いを指摘する。新一は、真犯人を突き止め、辻村夫婦の過去を掘り起こす。', '2014/12/25 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/3df4807d-273b-4cc5-a9db-5bcbfb0dbaa8.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('298f3f6a-0832-4215-ae77-309ebf062cec', '586c7036-43ed-4cd4-a3ff-abf358899dcb', 50, '60492605', '図書館殺人事件', '図書館で逆向きにケースに入れられて包装された変な洋書を見つけたコナンは、ここの図書館の職員が行方不明になっていることを知る。警察は手掛かりを見つけられずに帰っていったが、コナンは少年探偵団の3人と一緒に閉館した図書館の内部を捜索する。そして児童図書の書棚で背表紙のない本に隠された麻薬を発見した。', '2014/12/25 12:00:00', 1470, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/17f623cb-d152-4bf7-8c05-9d6a2cfa5710.jpg', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1c844de2-ccf8-4eb3-b511-80f93e6b90f1', '名探偵コナン エピソード"ONE" 小さくなった名探偵', '', 'hulu', 'case-closed-episode-one-the-great-detective-turned-small', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6e8b4286-9916-4dbc-927b-42b95901a991.jpg?w=331&h=447&p=t', 'hulu', 2016, 3, 1, 'FINISHED', NULL, 98604, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('124fb846-5ffd-45c0-bb94-d873e39704fb', '1c844de2-ccf8-4eb3-b511-80f93e6b90f1', 'hulu-case-closed-episode-one-the-great-detective-turned-small-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7e3eaea-cd41-4037-9e05-1853ff141c83.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('df8fee3f-1f58-4295-8884-7797dd05d529', '124fb846-5ffd-45c0-bb94-d873e39704fb', 1, '100078629', '名探偵コナン エピソード“ONE” 小さくなった名探偵', '新一と蘭は遊園地トロピカルランドでデート中に事件に巻き込まれる。2人がジェットコースターに乗っている最中に殺人事件が発生。容疑者の乗客7人の中には黒ずくめの組織のジン、ウォッカの姿も。新一は犯人と殺害トリックを見破って事件を解決するが…。その後、新一は怪しい雰囲気漂うジン、ウォッカの跡をつけ、闇の取引現場を目撃する。だが、ジンたちに気付かれた新一は組織が新開発した毒薬を飲まされ、子供の姿になってしまう…。今回の完全新作では、新一と最後に別れた時の蘭の届かぬ想い…、新一が子供の姿になった時の衝撃の事実…、黒ずくめの組織ジンとウォッカの真の企み…など、800話以上の物語へと繋がる知られざる真実が次々と明らかになる!?', '2026/01/23 22:54:00', 5734, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a7e3eaea-cd41-4037-9e05-1853ff141c83.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('1f76f1ca-5910-49bc-9e3f-58ae22dd7a5c', '名探偵コナン', '', 'hulu', 'case-closed-detective-conan-police-school-edition-wild-police-story', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e5583d54-87d9-4343-80ca-bd1a5c70dacd.jpg?w=331&h=447&p=t', 'hulu', 1996, 0, 1, 'RELEASING', NULL, 235, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('fd787687-a617-454b-bc76-1f7031708eba', '1f76f1ca-5910-49bc-9e3f-58ae22dd7a5c', 'hulu-case-closed-detective-conan-police-school-edition-wild-police-story-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fbb25ad-cf49-43a3-88b1-8af584a1777c.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('75d80dbd-89ad-4d33-9f93-ff2560b48c54', 'fd787687-a617-454b-bc76-1f7031708eba', 1, '100176670', 'CASE.松田陣平', '夜の警視庁警察学校。桜が舞い散る中、敷地内では降谷零と松田陣平が殴り合う音が響いていた。松田は警察学校にいるにもかかわらず「どうしても警察官になりたい」という降谷が気に入らないという。二人の争いは一歩も引かずに続いた。夜中の2時、諸伏景光が悪夢で飛び起きると、ドアをノックする音がする。そこには傷だらけの降谷の姿があった。降谷の様子を見ていた諸伏は「その相手とは仲良くやっていけそうか?」と質問するのだった。朝礼の際、傷だらけになっている降谷と松田の横には、同期の諸伏、萩原研二、伊達航が並んでいた。初任科鬼塚教場教官･鬼塚八蔵は、二人の傷の理由を問うが伊達が機転を利かせて嘘を付く。警察が嫌いだという割に、警察官の心得についてはしっかりと答えることができる松田の姿に疑問を持った降谷は…', '2026/03/14 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5fbb25ad-cf49-43a3-88b1-8af584a1777c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a12a691a-749c-43aa-85bc-11bf86e3940d', 'fd787687-a617-454b-bc76-1f7031708eba', 2, '100176671', 'CASE.伊達航', '逮捕術の授業で戦った降谷と伊達。伊達が勝利し、負けた降谷に「なぜ自身の弱点を突かなかったのか?」「誰よりも強くなければ、正義は遂行できない」といった言葉を投げかける。その夜、降谷は一人ベッドで伊達の言葉について考えていた。そんな降谷の部屋に、外出するという諸伏がやってくる。「買ってきて欲しいものはないか?」という言葉に「特にない」と返した降谷だったが、しばらくして歯磨き粉が切れていることを思い出す。お願いしようと部屋を出るが、すでに諸伏、萩原、松田の姿はなく一人でコンビニに行くことにする。降谷が外に出ると、そこには伊達の姿があり、父との過去の出来事を語りだした……。', '2026/03/14 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a4c13b3d-653e-4136-87bf-42e43191cdb5.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d458f6d1-7467-43d8-831b-e52caa99196a', 'fd787687-a617-454b-bc76-1f7031708eba', 3, '100176672', 'CASE.萩原研二', '警察学校で「RX-7FD3S」を発見した萩原、降谷、伊達、松田、諸伏。萩原の好きな車種だったようで、車から出てきた鬼塚教官を圧倒するほど熱弁する。しかし、これは鬼塚の持ち物ではなく殉職したある先輩刑事の愛車。先輩の娘が刑事を目指しており、それまで預かっているものだった。その後の重装備訓練では、先ほどの萩原の様子について話題になる。萩原の実家は車の修理工場をしていたため、車に詳しかったらしい。しかし工場は潰れてしまい「警察は絶対に倒産しない」という理由で警察官を目指したと語る。重装備訓練終了後、萩原と松田に声をかけてくる男がおり……。', '2026/03/14 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/58764526-dfe7-4c2c-8dbb-2c69f3f1cada.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('55fd4fd0-580f-466e-bce0-04ac490f72bd', 'fd787687-a617-454b-bc76-1f7031708eba', 4, '100176673', 'CASE.諸伏景光', '降谷、萩原、伊達、松田が止めるのを振り切り、諸伏は炎に包まれた家の階段を駆け上っていく――! 話は三時間前にさかのぼる。五人は鬼塚教官に捕まり派手な行動の数々に対して咎めを受け、風呂掃除を命じられていた。その最中に昨夜捜索願が出された女の子の情報を目にする。女の子を町で見かけたことのあった諸伏は写真を貰っていた。掃除中もその話題になったが、諸伏は何故か話をはぐらかそうとする。', '2026/03/14 00:00:00', 1465, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4ce407ae-5736-4706-823d-544a14b04ca9.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('62e90f18-5d11-47c0-98f1-9598ece61604', 'fd787687-a617-454b-bc76-1f7031708eba', 5, '100176674', 'CASE.降谷零', '【最終話】部屋で身支度を整えていた降谷のもとに、出かけるという諸伏がやってくる。二人が話していると松田も合流し、そのままコンビニに出かけることになった。大切な式の前だというのに、のんびりと過ごす三人を萩原と伊達は呆れ顔で出迎える。降谷、松田、萩原、伊達、諸伏が過ごした警視庁警察学校の初任科課程は今日、多くの想い出とともに卒業式を迎えた。五人はそれぞれの明日へと歩き出す。', '2026/03/14 00:00:00', 1425, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/5064ed2b-7f56-43e4-ab57-e963a1dcc44a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('274fadfe-a531-45f9-a6b2-ebf1e01a42b7', '名探偵コナン 江戸川コナン失踪事件～史上最悪の二日間～', '', 'hulu', 'detective-conan-missing-conan-edogawa-case-his-historys-worst-two-days', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/migration/50027337_series_art__338x600_detective_conan_missing_conan_edogawa_case__his_historys_worst_two_days_e02bc245898c30d2453b9092642269b4.jpg?w=331&h=447&p=t', 'hulu', 2014, 3, 1, 'FINISHED', NULL, 20878, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('f6f9a631-5aa8-430a-be47-5f77a36524f9', '名探偵プリキュア！', '', 'hulu', 'star-detective-precure', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/662d717a-d178-4d60-b2ea-250438ad2cf6.png?w=331&h=447&p=t', 'hulu', 2026, 0, 1, 'RELEASING', NULL, 202957, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('671a3711-694e-4906-ba66-94ae5b680c85', 'f6f9a631-5aa8-430a-be47-5f77a36524f9', 'hulu-star-detective-precure-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/784c6f59-d110-4575-b1e5-5831b2ea6d64.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('9250bbc3-a710-4e58-af64-e9d6f525a64d', '671a3711-694e-4906-ba66-94ae5b680c85', 1, '100252136', '誕生! 名探偵プリキュア!', '14歳の誕生日をむかえた明智あんなは、部屋に置かれていたペンダントを身に着けていたところに、妖精のポチタンと出会う。さらにペンダントの光に飲み込まれ、目を覚ました先は――', '2026/02/04 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/784c6f59-d110-4575-b1e5-5831b2ea6d64.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('57833649-671c-4a15-af74-2cff88693097', '671a3711-694e-4906-ba66-94ae5b680c85', 2, '100252799', '天才登場! その名はジェット先輩!', 'みくるに連れられ、キュアット探偵事務所を訪れるあんな。事務所にいた自称天才博士の妖精･ジェットによって、タイムスリップの原因はポチタンだったことが判明する。', '2026/02/11 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/780dae33-e388-469b-9b7c-8081c1c9fc49.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('dea713d2-05a4-4916-9b30-04f3d92676db', '671a3711-694e-4906-ba66-94ae5b680c85', 3, '100253339', 'みんなおいでよ! キュアット探偵事務所!', 'キュアット探偵事務所での共同生活が始まり、掃除や片付けに追われるあんなたち。インテリアや雑貨をそろえようと出かけた先で、お店のシンボルが消えてしまう事件に遭遇する。', '2026/02/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/eb8b7358-f524-4430-adb6-187bbc16e24f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('54aac642-d1e4-401d-8037-f98494eef246', '671a3711-694e-4906-ba66-94ae5b680c85', 4, '100253852', 'ドキドキ! 初めての依頼!', 'キュアット探偵事務所に初めての依頼人がやってくる。駅前で誰かのものと入れ違いになってしまったらしいバッグを探すあんなたちだったが、そこに怪盗団ファントムがあらわれる。', '2026/02/25 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/d3b5ad81-ad8b-432e-a35d-b78f9db96a15.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('0e516330-5488-43d1-8bdc-048b4f20344c', '671a3711-694e-4906-ba66-94ae5b680c85', 5, '100254764', '名探偵の大ピンチ!', 'みくるに傘を届けるため、まことみらい学園にやってきたあんなは、そこで困っている様子の真理子に出会い、妹･恵子の行方を探すことに。一方みくるも、高等部の幽霊さわぎを解決してほしい、と理事長に依頼される。', '2026/03/04 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/6f301d86-ca75-4e88-8782-2b2822e785db.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('d4a3f95c-04dc-4464-80a4-db6063623184', '671a3711-694e-4906-ba66-94ae5b680c85', 6, '100255645', '奇跡のプリキットミラールーペ!', '倒れたポチタンをあんなとジェット先輩にまかせ、マコトジュエルを取り返そうと駆け出していくみくる。残されたあんなは、みくるにプリキットを手渡せなかった理由をジェット先輩に打ち明ける。', '2026/03/11 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b35ec3dc-b14e-4eab-a7ec-40fc4b67005a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('fa4542d1-505e-4be0-9e9e-2b5ca46c4356', '671a3711-694e-4906-ba66-94ae5b680c85', 7, '100256406', '大変! 学校が迷路!?', 'みくると同じクラスに転校し、まことみらい学園に通えることになったあんな。広い校舎におどろいていたが、ゴウエモンが作り出した「からくり迷路」にみくると迷い込んでしまう。', '2026/03/18 00:00:00', 1450, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/64904341-461b-4ece-b37f-40201fd302ea.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO anime (id, title, description, provider, content_id, entity_type, maturity_rating, image_url, benefit_id, year, quarter, is_identified, status, tmdb_id, anilist_id, created_at, updated_at) VALUES ('3d8d4cbf-259f-4128-a114-37e7be5910cc', '名湯『異世界の湯』開拓記 ～アラフォー温泉マニアの転生先は、のんびり温泉天国でした～', '', 'hulu', 'meitou-isekainoyu-kaitakuki', 'tv', NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/a3ff139c-64d1-46f7-968e-e3e33eec9765.jpg?w=331&h=447&p=t', 'hulu', 2024, 0, 1, 'FINISHED', NULL, 171019, '2026-03-24T04:57:14.416Z', '2026-03-24T04:57:14.416Z');
INSERT INTO seasons (id, anime_id, season_id, display_name, season_number, image_url, created_at) VALUES ('2fde4571-ffb2-4897-97e5-58afd2250f4b', '3d8d4cbf-259f-4128-a114-37e7be5910cc', 'hulu-meitou-isekainoyu-kaitakuki-s1', 'シーズン1', 1, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e71df25f-4b27-4a53-a87f-cb68a20a894d.png', '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('ef322221-0635-46a0-b83d-b78f90442213', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 1, '100171832', '狐少女と温泉の作法', '温泉ハンターこと湯川好蔵は、お稲荷さまのお使い姫･繭玉さんと、異世界にやって来た。硫黄泉のにおいを嗅ぎつけた彼は、不思議な世界には目もくれず、においのする方へ駆けだしていく。', '2024/01/15 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/e71df25f-4b27-4a53-a87f-cb68a20a894d.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('22ffe7f2-e306-4e02-8db2-103bfa80fa28', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 2, '100172634', 'エルフの娘と作法違反', '混浴する好蔵と繭玉さんの前に、エルフの少女が現れた。なぜか敵意むき出しの彼女は、全裸の好蔵と繭玉さんに、魔法で攻撃をしかけてくる。', '2024/01/22 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/51efb08a-9d60-4983-a760-a722243c084a.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a6fc13f0-e556-4264-a84c-b7791bc9f190', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 3, '100173299', '森の民とモール泉', 'エルフの少女･リリウムは、繭玉さんに敗北。裸にされると、森の中で新たに見つけたモール泉に放り込まれていた。どうやらエルフ族は、温泉を呪われた死の泉として恐れているらしく……。', '2024/01/29 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/499db2d9-1bce-4ac2-ae71-b5acd6aefe1c.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('cf0dc5f6-a496-463c-9721-351a7c12dd57', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 4, '100174098', 'エルフの族長と呪いの湯', '好蔵と繭玉さんのおかげで、温泉の素晴らしさを知ることができたリリウム。好蔵は、温泉は皆で分かち合うべき自然の贈り物だと説く。そこに現れたのは、リリウムの姉でエルフ族の族長･オーヘンデックだった。', '2024/02/05 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4d8c944d-a858-471f-b0af-b826e15962fe.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('97affe3e-fdeb-46e6-80c8-3502ed10b721', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 5, '100175059', '我らが森に祝福を', 'オーヘンデックも好蔵たちと混浴。さっそく温泉の素晴らしさを体感したかと思いきや、繭玉さんの狐耳と尻尾を見て仰天し、慌てて頭を下げてくる。', '2024/02/12 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/594e595d-9eb1-4889-ba67-f45ae993309f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('7f9b8a59-9c50-46bb-ad73-57b0948d716a', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 6, '100175223', '妙案と温泉の効能', '繭玉さんとリリウムが仲良くなる一方、オーヘンデックは好蔵の語る温泉の効能に興味津々。実は今、エルフの里は財政難。それを打開するため、温泉を利用したいのだという。', '2024/02/19 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4661648d-02e5-4e0d-b5ef-8617e570e038.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('45d837a1-6c03-4286-96d5-4120022cea25', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 7, '100175898', '夢と湯あたり', '好蔵がぶち上げたのは、エルフの里に温泉街を建設するという計画だった。繭玉さんやリリウムやオーヘンデックは、ちょっとセクシーな温泉街の様子を妄想し始め……。', '2024/02/26 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/420942ae-0698-4898-80f8-34369e508e46.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('2ed23897-2269-41a8-94c0-5d7ec82d2094', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 8, '100176561', '転げ落ちた日の想い出', 'ふるさとの町に賑わいを取り戻すため、観光資源になる温泉を探していた好蔵。崖から滑落した彼を異世界に転生させたのは、忘れられた小さな社のお稲荷さまだった。', '2024/03/04 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/4e7cafe1-ba8f-4c7e-aa35-80be00dfbb32.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('15195b16-4c45-4a11-b5a0-9cf7a512f37b', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 9, '100177407', '先輩と有言十支族の王', '異世界を統べる王･ルイルイが、温泉街を建設中の好蔵たちを居城に呼びつける。ルイルイの側に控える小町は、何と繭玉さんの先輩お使い姫。そしてルイルイには、何やら目的があるらしく……。', '2024/03/11 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/fb417297-65af-4245-91f3-a4495ff628f8.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('f2457665-5680-474d-9c9d-e7f1b66d3685', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 10, '100178201', '王の頼みと好蔵の想い', 'ルイルイは好蔵と同じ、異世界からの転生者だった。女性であることを隠して王位に就いている彼女は、好蔵を家臣にすることで世界を変えようとしていた。', '2024/03/18 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/9103887e-0ad2-4e0f-afaf-6420aa17d212.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('a3495ad5-a567-4e12-adb9-f76b57aa6b47', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 11, '100178579', '呪われた血の湯と蜂蜜酒', '好蔵には、異世界で出来るだけ長生きしてほしい。そんなことを口にする繭玉さんの真意を、好蔵は小町の口を通して聞く。そこに入って来た一同と、血のように赤い含鉄泉を楽しむ。', '2024/03/25 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/bd24b9bc-cef3-4299-8115-25b2e7312a5f.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
INSERT INTO episodes (id, season_id, episode_number, episode_id, title, description, release_date, duration, maturity_rating, image_url, has_subtitles, has_dub, benefit_id, recorded, created_at) VALUES ('5b2667a6-1b28-43af-a88e-cc7924b8a763', '2fde4571-ffb2-4897-97e5-58afd2250f4b', 12, '100179323', '繭玉山荘', '【最終話】ついに温泉街が完成。温泉宿の表看板を見た繭玉さんは驚く。そこには『繭玉の湯』と、自分の名前が記されていたのだ。好蔵は、そう名付けた理由を語る。', '2024/04/01 12:00:00', 236, NULL, 'https://images.prod.hjholdings.tv/d3urerHm/uploads/b6a17660-12ad-4158-a55e-fa2d44b3d404.png', 0, 0, 'hulu', 0, '2026-03-24T04:57:14.416Z');
